INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AADE_WEBSERVICE_KEY', 'string', NULL, 'societe', 'Stores the API key (password) credential for the Greek AADE VAT validation web service.', 'Written via admin/company.php (line 283) and rendered as a password input (line 930). Used in societe/checkvat/checkVatGr.php (line 29) and societe/card.php (line 85) as the password for AADE authentication.', 'Setting this value provides the secret credential required to authenticate VAT number lookups against the AADE web service.', 'String (AADE web service API key/password); empty means authentication will fail.', 0, 0, 'admin/company.php|admin/company.php', 1, '1fc65d0434f7e6605b4d6dc46a4d1cc6e3d407921311e4554f49951ba5e15e96', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:283|write|dolibarr_set_const($db, \"AADE_WEBSERVICE_KEY\", GETPOST(\"AADE_WEBSERVICE_KEY\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "societe/checkvat/checkVatGr.php:29|read|$password = getDolGlobalString(''AADE_WEBSERVICE_KEY''); // Get password from request", "societe/card.php:85|read|$p = getDolGlobalString(''AADE_WEBSERVICE_KEY'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AADE_WEBSERVICE_USER', 'string', NULL, 'societe', 'Stores the username credential for the Greek AADE VAT validation web service.', 'Written via admin/company.php (line 282) and displayed as a text input (line 925). Used in societe/checkvat/checkVatGr.php (line 28) and societe/card.php (line 84) to authenticate against the AADE web service.', 'Setting this value enables the Greek VAT number validation feature; leaving it empty disables authentication to the AADE service.', 'String (AADE web service username); empty means the service cannot authenticate.', 0, 0, 'admin/company.php|admin/company.php', 1, '3b505eaf1a4f7e91ce1bce354331cbd90e2afc6a34e99b8387b2456ed69c3c9b', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:282|write|dolibarr_set_const($db, \"AADE_WEBSERVICE_USER\", GETPOST(\"AADE_WEBSERVICE_USER\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "societe/checkvat/checkVatGr.php:28|read|$username = getDolGlobalString(''AADE_WEBSERVICE_USER''); // Get username from request", "societe/card.php:84|read|$u = getDolGlobalString(''AADE_WEBSERVICE_USER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_AUTOFIX_MISSING_LINK_TO_USER_ON_SALARY_BANK_PAYMENT', 'string', NULL, 'accountancy', 'Legacy fix-up flag that re-links a salary bank payment to its user when the link was missing (a v14.0.0-era data issue).', 'Read in accountancy/journal/bankjournal.php:596, guarded by a comment stating it is ''no more required'' and kept only ''to solve case where a link were missing (with v14.0.0)''.', 'When enabled, on encountering a payment_salary link, the code fetches the Salary and its user to compensate for a historical missing link, keeping bookkeeping writes complete; the comment recommends instead deleting/recreating the payment or fixing the bookkeeping table manually.', 'Boolean-like: truthy enables the legacy auto-fix path for missing salary-to-user links.', 1, 0, NULL, 1, 'e4e1dabff59a87bdaef1967dd39f57683a7dee0a071d2206fd91a72ae982830a', 'v2', '2026-07-24T07:05:23+00:00', '["bankjournal.php: // This part of code is no more required. it is here to solve case where a link were missing (with v14.0.0) and keep writing in accountancy complete.", "bankjournal.php: // Note: A better way to fix this is to delete payment of salary and recreate it, or to fix the bookkeeping table manually after.", "bankjournal.php:596: if (getDolGlobalString(''ACCOUNTANCY_AUTOFIX_MISSING_LINK_TO_USER_ON_SALARY_BANK_PAYMENT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_AUXACCOUNT_DONOTSEARCH_ANYWHERE', 'string', NULL, 'core', 'Controls whether the auxiliary account ajax search matches anywhere in the string (default) or only as a prefix.', 'Read in core/ajax/auxaccount.php:74, where it toggles a leading SQL LIKE wildcard (''%'') used to search code_compta/code_compta_fournisseur/nom fields; comment at line 73 states the default behavior is ''Search anywhere by default (use LIKE %term%)''.', 'When set/true, the leading ''%'' wildcard is dropped so the ajax search only matches values starting with the typed text instead of matching anywhere in the field.', 'Boolean-like: true/non-empty disables the anywhere-search wildcard; unset/false keeps default anywhere search.', 1, 0, NULL, 1, '5983c991426c3a470c06d389e45d57e503c2c479555d9d60b64be6358232ac5d', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/auxaccount.php:73: // Search anywhere by default (use LIKE ''%term%'')", "core/ajax/auxaccount.php:74: $prefix = getDolGlobalString(''ACCOUNTANCY_AUXACCOUNT_DONOTSEARCH_ANYWHERE'') ? '''' : ''%'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_AUXACCOUNT_SEARCH_LIMIT', 'string', NULL, 'core', 'Sets the maximum number of rows returned by the auxiliary account (thirdparty) ajax search used in accounting.', 'Read in core/ajax/auxaccount.php:64 as the SQL LIMIT applied to the ajax search for auxiliary accounts (societe table) used by the accounting module''s account-selection widgets.', 'Increasing the value returns more matching thirdparties in the ajax dropdown at the cost of a larger query result; default is 100 when unset.', 'Integer row limit; default 100 if not set.', 1, 0, NULL, 1, 'd5803f3501eef95a4493660da6540fa8a07c77419d7e16042d7d1d3d1fff0794', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/auxaccount.php:64: $limit     = getDolGlobalInt(''ACCOUNTANCY_AUXACCOUNT_SEARCH_LIMIT'', 100);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_AUXACCOUNT_USE_SEARCH_TO_SELECT', 'bool', NULL, 'compta', 'Sets the subledger account selection mode: 0 = dropdown list, integer N >= 2 = search-to-select triggered after N-1 characters.', 'Checked in admin/system/perf.php:658 and compta/bank/various_payment/card.php:737,68 against value > 0. Read in core/ajax/auxaccount.php:65 where minLength is set to value-1, and in core/class/html.formaccounting.class.php:511. Comment at core/ajax/auxaccount.php:22 states ''Called by select_auxaccount() when ACCOUNTANCY_AUXACCOUNT_USE_SEARCH_TO_SELECT >= 2''. Configurable via admin/system/perf.php.', 'Setting to 0 uses a standard dropdown for subledger account selection. Setting to 2 or higher activates an AJAX search triggered after the user types (value-1) characters, improving performance with large subledger account lists.', '0 = dropdown list; integer >= 2 = AJAX search triggered after (value-1) characters typed', 0, 0, 'admin/system/perf.php|admin/system/perf.php', 1, 'b7405da8736a25ff4ea72d3fe88e8fbb6067a4219cb0050f8ac37df754e35e54', 'v2', '2026-04-21T11:16:15+00:00', '["core/ajax/auxaccount.php:22  *              Called by select_auxaccount() when ACCOUNTANCY_AUXACCOUNT_USE_SEARCH_TO_SELECT >= 2", "core/class/html.formaccounting.class.php:489  * Behavior depends on constant ACCOUNTANCY_AUXACCOUNT_USE_SEARCH_TO_SELECT:", "core/ajax/auxaccount.php:65|read|$minLength = getDolGlobalInt(''ACCOUNTANCY_AUXACCOUNT_USE_SEARCH_TO_SELECT'', 2) - 1;", "compta/bank/various_payment/card.php:737|check|if (getDolGlobalString(''ACCOUNTANCY_AUXACCOUNT_USE_SEARCH_TO_SELECT'') > 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_DISABLE_CLOSURE_LINE_BY_LINE', 'bool', NULL, 'accountancy', 'Disables line-by-line closure processing in the accounting module, merging closure into fewer steps.', 'Checked in accountancy/closure/index.php (lines 358, 430, 424, 447), accountancy/bookkeeping/export.php (lines 219, 837), accountancy/class/bookkeeping.class.php:2841, and accountancy/bookkeeping/listbyaccount.php:213. When set, the ''date_validated'' column is hidden and closure step numbering changes.', 'When enabled, the accounting closure process skips the line-by-line validation step and the date_validated column is disabled in related views; when disabled, line-by-line closure is available.', 'Truthy (non-empty) to disable line-by-line closure; empty/unset to enable it.', 1, 0, NULL, 1, 'dbff1d91412d966ac67c09b1b03f8d6da32ff9839971d398fa419c9ddbe2eb7f', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/bookkeeping/export.php:837|check|if (!getDolGlobalString(\"ACCOUNTANCY_DISABLE_CLOSURE_LINE_BY_LINE\")) {", "accountancy/closure/index.php:358|check|if (!getDolGlobalString(\"ACCOUNTANCY_DISABLE_CLOSURE_LINE_BY_LINE\")) {", "accountancy/bookkeeping/listbyaccount.php:213|read|''t.date_validated'' => array(''label'' => \"DateValidation\", ''checked'' => ''-1'', ''enabled'' => (string) (int) !getDolGlobalString(\"ACCOUNTANCY_DISABLE_CLOSURE_LINE_BY_LINE\")),", "accountancy/class/bookkeeping.class.php:2841|check|if (getDolGlobalString(\"ACCOUNTANCY_DISABLE_CLOSURE_LINE_BY_LINE\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_DO_NOT_AUTOFILL_ACCOUNT_WITH_GENERIC', 'string', NULL, 'accountancy', 'Disables the automatic fallback that fills in a suggested accounting account from the generic default code when no product- or thirdparty-specific account was found.', 'In accountancy/class/accountingaccount.class.php:925, the generic-code fallback (setting $suggestedid from $code_l) is only applied when $suggestedid and $code_p are both empty, $code_l is non-empty, AND this constant is falsy; setting it truthy blocks that autofill.', 'Setting it prevents the accounting ventilation process from auto-suggesting the generic default accounting account when no more specific product/thirdparty account is found, likely leaving the suggested account unset in that case.', 'Boolean-like: truthy disables the generic-account autofill fallback in account suggestion logic.', 0, 0, NULL, 1, '15f55acdcc1a9a39fad26c1160a9982221181e4536514a2fb3181c149e2acf27', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/class/accountingaccount.class.php:925|check|if (empty($suggestedid) && empty($code_p) && !empty($code_l) && !getDolGlobalString(''ACCOUNTANCY_DO_NOT_AUTOFILL_ACCOUNT_WITH_GENERIC'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_ENABLE_FKDOCDET', 'bool', NULL, 'accountancy', 'When enabled, populates the fk_doc_det (document detail foreign key) field on bookkeeping entries, linking them to their source document lines.', 'Checked in accountancy/class/bookkeeping.class.php at lines 344 and 365 during bookkeeping record creation.', 'Enabling this constant causes bookkeeping entries to store a reference to the originating document detail line, enabling more granular audit tracing.', '0 or unset = fk_doc_det not populated; truthy = fk_doc_det populated on bookkeeping entries.', 1, 0, NULL, 1, '7b9d3c8683eae531e1f19acca3acdb4dd7f8446f18217a01580da8a6c8ac26a5', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/bookkeeping.class.php:344|check|if (getDolGlobalString(''ACCOUNTANCY_ENABLE_FKDOCDET'')) {", "accountancy/class/bookkeeping.class.php:365|check|if (getDolGlobalString(''ACCOUNTANCY_ENABLE_FKDOCDET'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_ER_DATE_RECORD', 'string', NULL, 'accountancy', 'Chooses which date of an expense report line (record date vs. expense date) is used as the accounting entry date in the expense-reports journal.', 'Read/toggled in accountancy/admin/index.php:709 (ADMIN_UI accountancy/admin/index.php, only shown when ACCOUNTING_DISABLE_BINDING_ON_EXPENSEREPORTS is not set) and consumed in accountancy/journal/expensereportsjournal.php:207 to pick between $obj->df (record/validation date) and $obj->de (expense date).', 'When activated, expense report journal entries are dated using the report''s record/validation date ($obj->df) instead of the actual expense date ($obj->de).', 'Boolean-like toggle exposed as Activated/Disabled in the admin UI; true = use record date, false/unset = use expense date.', 0, 0, 'accountancy/admin/index.php', 1, '8a95d7a325172f9c2df1a70bd26de5ef71d4ea7586e51c956361ded7bc8383fa', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/admin/index.php:709: if (getDolGlobalInt(''ACCOUNTANCY_ER_DATE_RECORD'')) { ... img_picto($langs->trans(\"Activated\"), ''switch_on''); ...", "expensereportsjournal.php:207: if (getDolGlobalInt(''ACCOUNTANCY_ER_DATE_RECORD'')) { $taber[$obj->rowid][\"date\"] = $db->jdate($obj->df); } else { $taber[$obj->rowid][\"date\"] = $db->jdate($obj->de); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_FISCALYEAR_DEFAULT', 'string', NULL, 'accountancy', 'Stores the rowid of the default fiscal year used to pre-filter bookkeeping views.', 'Set via accountancy/admin/fiscalyear.php (line 94). When set, bookkeeping pages such as export.php, balance.php, listbyaccount.php, and list.php use this value to filter entries to the selected fiscal year (e.g. accountancy/bookkeeping/export.php:175: `$sql .= " WHERE rowid = " . getDolGlobalInt(''ACCOUNTANCY_FISCALYEAR_DEFAULT'')`).', 'Changing this value redirects all bookkeeping list views to display entries for the newly selected fiscal year by default.', 'Integer (rowid of a fiscal year record); empty/0 means no default filter applied.', 0, 0, 'accountancy/admin/fiscalyear.php|accountancy/admin/fiscalyear.php', 1, 'e725241610e1ed6fe77ce039c19711fbc3aac09764a57ac286332c58c1c11f8f', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/fiscalyear.php:94|write|dolibarr_set_const($db, ''ACCOUNTANCY_FISCALYEAR_DEFAULT'', $defaultFiscalYear, ''chaine'', 0, '''', $conf->entity);", "accountancy/bookkeeping/export.php:175|read|$sql .= \" WHERE rowid = \" . getDolGlobalInt(''ACCOUNTANCY_FISCALYEAR_DEFAULT'');", "accountancy/bookkeeping/balance.php:107|read|$sql .= \" WHERE rowid = \" . getDolGlobalInt(''ACCOUNTANCY_FISCALYEAR_DEFAULT'');", "accountancy/admin/fiscalyear.php:201|check|if (getDolGlobalString(''ACCOUNTANCY_FISCALYEAR_DEFAULT'') == (int) $fiscalyearstatic->ref) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_FISCAL_PERIOD_MODE', 'string', NULL, 'accountancy', 'Selects the fiscal-period locking mode used across accountancy bookkeeping and journals.', 'Read across 15 occurrences (bookkeeping.class.php:305,2581,2714; journal/variousjournal.php:252; journal/bankjournal.php:1255; journal/purchasesjournal.php:1039; journal/cashsellsjournal.php:1119; index.php:195, and 7 more), compared against the value ''blockedonclosed''.', 'Setting the value to ''blockedonclosed'' triggers additional blocking checks in bookkeeping and journal code paths tied to closed fiscal periods.', '''blockedonclosed'' is a recognized value (compared explicitly in code).', 0, 0, NULL, 1, '0567d86f91d824ba3ad1e9c2dbc83dba33b7b813dff2659e34ebcc68ee1746f0', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''ACCOUNTANCY_FISCAL_PERIOD_MODE'') == ''blockedonclosed'') {", "if (getDolGlobalString(''ACCOUNTANCY_FISCAL_PERIOD_MODE'') != ''blockedonclosed'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_HIDE_EXPORT_FILES_MENU', 'bool', NULL, 'core', 'Hides the accounting export files menu entries when set, removing them from the accountancy navigation.', 'Checked with negation at two locations in core/menus/standard/eldy.lib.php:1893 and 2020. No admin UI write detected.', 'Setting this constant removes accounting export file links from the menu. Removing it restores both menu entries.', 'Non-empty = export file menu items hidden; absent/empty = items shown.', 1, 0, NULL, 1, '326336758c676e6f2e72f1fa9383c1be0a95365469be69e850f21594f6f96284', 'v2', '2026-04-21T13:29:58+00:00', '["core/menus/standard/eldy.lib.php:1893|check|if (!getDolGlobalString(''ACCOUNTANCY_HIDE_EXPORT_FILES_MENU'')) {", "core/menus/standard/eldy.lib.php:2020|check|if (!getDolGlobalString(''ACCOUNTANCY_HIDE_EXPORT_FILES_MENU'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_JOURNAL_USE_CURRENT_MONTH', 'bool', NULL, 'accountancy', 'Toggles whether accountancy journals (cash sells / sells) use the current month for some date logic.', 'Checked in accountancy/journal/cashsellsjournal.php:134 and accountancy/journal/sellsjournal.php:133.', 'Enabling it changes journal date-related behavior in the cash-sells and sells journals; exact effect on the computed date is not detailed in the payload.', NULL, 0, 0, NULL, 1, 'feef8d55282ad68ce6d636ceb79dabf41b4596de86d7dc76e9cfac7d24dd8ab0', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''ACCOUNTANCY_JOURNAL_USE_CURRENT_MONTH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_MAX_TOO_MANY_LINES_TO_PROCESS', 'string', NULL, 'accountancy', 'Caps the number of lines processed before journals warn/stop with a ''too many lines'' condition, default 10000.', 'Used as a threshold in accountancy/journal/purchasesjournal.php:403, cashsellsjournal.php:421 and sellsjournal.php:427, each comparing a counter $i against getDolGlobalInt(..., 10000).', 'Raising the value allows more lines to be processed before the ''too many lines'' condition triggers in purchases/cash-sells/sells journals; lowering it triggers the condition sooner.', 'Default when unset: 10000.', 0, 0, NULL, 1, '779874b484fcd15f405936cb537874ab208b7ce9cddc1fa06ff13eaf31fd7afc', 'v2', '2026-07-24T06:41:12+00:00', '["if ($i > getDolGlobalInt(''ACCOUNTANCY_MAX_TOO_MANY_LINES_TO_PROCESS'', 10000)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_SHOW_DEVELOP_JOURNAL', 'bool', NULL, 'core', 'Controls whether the detailed/developed accounting journal is shown in the menu.', 'Checked in core/menus/standard/auguria.lib.php:462 and core/menus/standard/eldy.lib.php:1855. When not set, the developed journal menu entry is hidden.', 'Setting this constant makes the developed accounting journal menu entry visible; leaving it unset hides that entry.', 'Non-empty = developed journal menu shown; empty or unset = hidden', 1, 0, NULL, 1, 'df9ec819b81a7caa694366077c58d4c28446988539b5e87a0fcac72e452376ae', 'v2', '2026-04-21T13:29:58+00:00', '["core/menus/standard/auguria.lib.php:462|check|if (!getDolGlobalString(''ACCOUNTANCY_SHOW_DEVELOP_JOURNAL'')) {", "core/menus/standard/eldy.lib.php:1855|check|if (!getDolGlobalString(''ACCOUNTANCY_SHOW_DEVELOP_JOURNAL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_SHOW_OPENING_BALANCE', 'bool', NULL, 'accountancy', 'Controls whether the opening balance column is displayed in the accounting bookkeeping balance report.', 'Checked in 12 locations across accountancy/bookkeeping/balance.php (lines 486, 515, 587, 592, 637, 668, 696, 701 and more) to conditionally render opening balance data. No admin UI is present.', 'Enabling this causes the opening balance column and related computations to appear in the balance report; disabling it hides that data.', '0 or unset = opening balance not shown; truthy value = opening balance displayed.', 1, 0, NULL, 1, '63d8bb30ddce577e3c550afe0c43540fb3a16ce82ede7d62168878f787882f06', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/bookkeeping/balance.php:486|check|if (getDolGlobalString(''ACCOUNTANCY_SHOW_OPENING_BALANCE'')) {", "accountancy/bookkeeping/balance.php:515|check|if (getDolGlobalString(''ACCOUNTANCY_SHOW_OPENING_BALANCE'')) {", "accountancy/bookkeeping/balance.php:637|check|if (getDolGlobalString(''ACCOUNTANCY_SHOW_OPENING_BALANCE'')) {", "accountancy/bookkeeping/balance.php:696|check|if (getDolGlobalString(''ACCOUNTANCY_SHOW_OPENING_BALANCE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_SHOW_PROD_DESC', 'bool', NULL, 'accountancy', 'Controls whether the product description column is shown in the accounting product account admin page.', 'Checked in accountancy/admin/productaccount.php at lines 608, 642, and 759 to conditionally render the product description column. Configured via accountancy/admin/productaccount.php.', 'Enabling this constant adds a description column to the product accounting account tables; disabling or leaving it unset hides that column.', 'Integer/bool (truthy=shown, 0/empty=hidden)', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, 'a0026b8bfc49de62485cbdbe5e8e53b6106342b4ecf6cfd2cde6f733933cc9e3', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:759|check|if (getDolGlobalInt(''ACCOUNTANCY_SHOW_PROD_DESC'')) {", "accountancy/admin/productaccount.php:608|check|if (getDolGlobalInt(''ACCOUNTANCY_SHOW_PROD_DESC'')) {", "accountancy/admin/productaccount.php:642|check|if (getDolGlobalInt(''ACCOUNTANCY_SHOW_PROD_DESC'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_TRUNC_DECIMAL_ON_BALANCE_REPORT', 'string', NULL, 'compta', 'When set to a non-zero integer, truncates decimal digits in balance report amount displays.', 'Checked in 8 locations all within compta/resultat/result.php (lines 393, 424, 448, 473, 643, 654, 664, 699). No admin UI write path exists in the payload.', 'Enabling this constant causes balance report monetary values to be displayed without decimal places.', 'Non-zero integer = truncate decimals in balance report; 0 or unset = show full precision (default)', 1, 0, NULL, 1, 'e580fe20feb3b7f786929504d9b1300468d752e0521367625efba0e12268613c', 'v2', '2026-04-21T11:16:15+00:00', '["compta/resultat/result.php:393|check|if (getDolGlobalInt(''ACCOUNTANCY_TRUNC_DECIMAL_ON_BALANCE_REPORT'')) {", "compta/resultat/result.php:424|check|if (getDolGlobalInt(''ACCOUNTANCY_TRUNC_DECIMAL_ON_BALANCE_REPORT'')) {", "compta/resultat/result.php:643|check|if (getDolGlobalInt(''ACCOUNTANCY_TRUNC_DECIMAL_ON_BALANCE_REPORT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_USE_EXPENSE_REPORT_VALIDATION_DATE', 'bool', NULL, 'accountancy', 'When enabled, adds a ''Date Validation'' column (expense report validation date) to the accountancy expense-report binding lists.', 'Checked identically in accountancy/expensereport/lines.php:120-122 and accountancy/expensereport/list.php:135-137: `if (getDolGlobalString(''ACCOUNTANCY_USE_EXPENSE_REPORT_VALIDATION_DATE'')) { $arrayfields[''er.date_valid''] = array(''label'' => "DateValidation", ...); }`.', 'When enabled, both the expense-report accounting binding line list and the summary list display and can sort/filter by the expense report''s validation date (er.date_valid) as an extra column.', 'Boolean-like: truthy adds the ''er.date_valid'' / DateValidation column to $arrayfields on both expense report accountancy list pages.', 0, 0, NULL, 1, '0a61683080bc4eb1a2bd8934acd5c07a192d297a038432ea19f7c03e4a1e88f6', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/expensereport/lines.php:120|check|if (getDolGlobalString(''ACCOUNTANCY_USE_EXPENSE_REPORT_VALIDATION_DATE'')) {", "accountancy/expensereport/list.php:135|check|if (getDolGlobalString(''ACCOUNTANCY_USE_EXPENSE_REPORT_VALIDATION_DATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_USE_PRODUCT_ACCOUNT_ON_THIRDPARTY', 'bool', NULL, 'accountancy', 'Enables the ability to assign per-product accounting accounts directly on third-party (company) records.', 'Configured via accountancy/admin/index.php. Checked in 9 occurrences including societe/card.php:2042, :3404, accountancy/customer/list.php:961, accountancy/supplier/list.php:975, and accountancy/class/accountingaccount.class.php:870.', 'When enabled, accounting account fields per product appear on the third-party card, allowing overrides of default product accounting accounts for specific customers or suppliers.', '0 or unset = feature disabled; non-empty = feature enabled', 0, 0, 'accountancy/admin/index.php', 1, '32e26f71dad400694797d4d29014c256e824c3a888ac260188980feea4ff3913', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/index.php:487|check|if (getDolGlobalString(''ACCOUNTANCY_USE_PRODUCT_ACCOUNT_ON_THIRDPARTY'')) {", "societe/card.php:2042|check|if (getDolGlobalString(''ACCOUNTANCY_USE_PRODUCT_ACCOUNT_ON_THIRDPARTY'')) {", "accountancy/customer/list.php:961|check|if (getDolGlobalString(''ACCOUNTANCY_USE_PRODUCT_ACCOUNT_ON_THIRDPARTY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTANCY_VALID_REDIRECT_TO_CARD', 'string', NULL, 'accountancy', 'Changes the post-validation redirect target on the accounting bookkeeping entry page to go to the validated entry''s own card instead of back to the journal view.', 'In accountancy/bookkeeping/card.php:459, after a successful validation, if truthy the code redirects to the current page filtered by the new piece_num (the entry''s card); otherwise it redirects back to the journal listing page (backtopage).', 'Setting it changes the post-save navigation flow in bookkeeping entry validation: the user lands on the validated entry''s own view instead of returning to the journal list.', 'Boolean-like (read via getDolGlobalInt): truthy redirects to the validated entry''s card; default behavior redirects back to the journal view.', 0, 0, NULL, 1, '1afeb3d87b95542f9b993d9cdb90ac1cb17f7cba17758be10fb5036561459ecc', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/bookkeeping/card.php:459|check|if (getDolGlobalInt(''ACCOUNTANCY_VALID_REDIRECT_TO_CARD'')) {", "accountancy/bookkeeping/card.php: // Default behavior: return on journal view"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_', 'string', NULL, 'accountancy', 'Name prefix for a family of dynamic constants (e.g. ACCOUNTING_ACCOUNT_CUSTOMER_DEPOSIT, ACCOUNTING_ACCOUNT_SUPPLIER_DEPOSIT) that store the accounting account code to use for deposit invoice lines, built as ACCOUNTING_ACCOUNT_<TYPE>_DEPOSIT.', 'In accountancy/class/accountingaccount.class.php:883, the code builds the constant name dynamically as ''ACCOUNTING_ACCOUNT_'' . strtoupper($type) . ''_DEPOSIT'' (type is ''customer'' or ''supplier''), then uses getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER_DEPOSIT'') / ''..._SUPPLIER_DEPOSIT'' at lines 888/890/912/913 to fetch the accounting account for lines flagged as deposits ($factureDet->desc == "(DEPOSIT)" or invoice type TYPE_DEPOSIT).', 'Setting ACCOUNTING_ACCOUNT_CUSTOMER_DEPOSIT or ACCOUNTING_ACCOUNT_SUPPLIER_DEPOSIT to an accounting account code (other than ''-1'') makes the accounting ventilation logic use that specific account for deposit invoice lines instead of falling through to the generic/default account lookup.', 'String: an accounting account code; ''-1'' or empty means not configured (falls back to generic account resolution).', 0, 0, NULL, 1, 'fdf5b86aeaf8252a18f2a9fdc028893c1e59a0538dbc7bce96de2f200611f64a', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/class/accountingaccount.class.php:883|read|$account_deposit = getDolGlobalString(''ACCOUNTING_ACCOUNT_'' . strtoupper($type) . ''_DEPOSIT'');", "accountancy/class/accountingaccount.class.php:884  if (!empty($account_deposit) && $account_deposit != ''-1'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_CUSTOMER', 'string', NULL, 'accountancy', 'Defines the default general accounting account used for customers.', 'Read across 25 occurrences including accountancy/class/accountingjournal.class.php:819, journal/bankjournal.php:1292, journal/treasuryjournal.php:1399, compta/journal/sellsjournal.php:183, journal/cashsellsjournal.php:228,1139, journal/sellsjournal.php:227, and more.', 'If empty, '''' or ''-1'', code treats the customer accounting account as not configured (e.g. journal/cashsellsjournal.php:1139 checks in_array(..., ['''',''-1''])); some code falls back to ''NotDefined'' as a reserved placeholder value.', ''''' or ''-1'' = not configured/reserved ''NotDefined'' placeholder used in fallback default.', 0, 0, NULL, 1, 'd9071b654debd0b8cb9d8b910941e6790d113b09e227ef80050eb32bdde94fb6', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER'') == \"\" || getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER'') == ''-1''", "$account_customer = getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER'', ''NotDefined''); // NotDefined is a reserved word", "$acctCustomerNotConfigured = in_array(getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER''), ['''',''-1'']);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_CUSTOMER_DEPOSIT', 'string', NULL, 'accountancy', 'Defines the accounting account used for customer deposits, configurable via the accountancy default-accounts admin page.', 'Set/read via accountancy/admin/defaultaccounts.php:341,345 (admin UI with a select_account widget) and used in journal/cashsellsjournal.php:1360,693, journal/sellsjournal.php:1366,699, and accountingaccount.class.php:888,911.', 'If empty or ''-1'', the deposit-account feature check in defaultaccounts.php:345 evaluates false; journals compare booking rows against this account number ($k == getDolGlobalString(...)).', '''-1'' treated as unset/invalid alongside empty string.', 0, 0, 'accountancy/admin/defaultaccounts.php|accountancy/admin/defaultaccounts.php', 1, '712dd37e39573924292108f909c66aa0fe176d7f86bb79a0c5cc33a4875a9de5', 'v2', '2026-07-24T06:41:12+00:00', '["if (isModEnabled(''societe'') && getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER_DEPOSIT'') && getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER_DEPOSIT'') != ''-1'') {", "if ($k == getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER_DEPOSIT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_CUSTOMER_RETAINED_WARRANTY', 'string', NULL, 'accountancy', 'Defines the accounting account used for customer retained-warranty amounts in sells/cash-sells journals.', 'Read in accountancy/journal/cashsellsjournal.php:1279,512,577,987 and journal/sellsjournal.php:1285,518,583,993, used for display (length_accountg), fetching the account object, and setting bookkeeping->numero_compte.', 'Changing it changes which accounting account number retained-warranty bookkeeping entries and CSV export rows use in the cash-sells and sells journals.', NULL, 0, 0, NULL, 1, 'f309583904c51b5c3aae9d89e94cf19b5412254b6a51bcb7df4a107a6d462613', 'v2', '2026-07-24T06:41:12+00:00', '["$accountoshow = length_accountg(getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER_RETAINED_WARRANTY''));", "$bookkeeping->numero_compte = getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER_RETAINED_WARRANTY'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_CUSTOMER_USE_AUXILIARY_ON_DEPOSIT', 'bool', NULL, 'accountancy', 'Toggles whether an auxiliary (subsidiary) account is used on customer deposit bookkeeping entries.', 'Set from accountancy/admin/defaultaccounts.php:199 via dolibarr_set_const with type ''yesno'', checked in defaultaccounts.php:348 and in journal/cashsellsjournal.php:1359,692 and journal/sellsjournal.php:1365,698.', 'Enabling it changes deposit-related journal branching that depends on getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER_USE_AUXILIARY_ON_DEPOSIT'') in the cash-sells and sells journals.', 'Stored as ''yesno'' type (0/1).', 0, 0, 'accountancy/admin/defaultaccounts.php|accountancy/admin/defaultaccounts.php', 1, 'c8c8921874bd913a7b31ab12373af06682a3d6a85a47af39bb170c20a94b0c31', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_ACCOUNT_CUSTOMER_USE_AUXILIARY_ON_DEPOSIT\", $setDisableAuxiliaryAccountOnCustomerDeposit, ''yesno'', 0, '''', $conf->entity);", "if (getDolGlobalString(''ACCOUNTING_ACCOUNT_CUSTOMER_USE_AUXILIARY_ON_DEPOSIT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_DISCOUNT_GRANTED', 'string', NULL, 'accountancy', 'Stores the general ledger account number used for discounts granted to customers.', 'Read in accountancy/class/accountingjournal.class.php:805 and checked in accountancy/journal/variousjournal.php at lines 196 and 200 to detect unconfigured state (''-1'' or empty). No admin UI write found; HIDDEN_GUESS is 1.', 'If not set or set to ''-1'', the various journal flags discount-granted configuration as incomplete, blocking related journal generation.', 'String: general ledger account number; '''' or ''-1'' = not configured', 1, 0, NULL, 1, '64314a2863e5a44648d7159b659087e123b085c40d1c421d95d40897c76e2e82', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/accountingjournal.class.php:805|read|$acc_disc_granted = getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_GRANTED'');", "accountancy/journal/variousjournal.php:196|read||| !getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_GRANTED'') || getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_GRANTED'') == ''-1''", "accountancy/journal/variousjournal.php:200|read||| !getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_GRANTED'') || getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_GRANTED'') == ''-1''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_DISCOUNT_RECEIVED', 'string', NULL, 'accountancy', 'Stores the general ledger account number used for discounts received from suppliers.', 'Read in accountancy/class/accountingjournal.class.php:1114 and checked in accountancy/journal/variousjournal.php at lines 197 and 201 to detect unconfigured state (''-1'' or empty). No admin UI write found; HIDDEN_GUESS is 1.', 'If not set or set to ''-1'', the various journal flags discount-received configuration as incomplete, blocking related journal generation.', 'String: general ledger account number; '''' or ''-1'' = not configured', 1, 0, NULL, 1, 'f026c5fa4f4fd16bc683b06ff2a0d9ffe4f7e0224a5d7d825caf504966b4bd55', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/accountingjournal.class.php:1114|read|$acc_disc_recv    = getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_RECEIVED'');", "accountancy/journal/variousjournal.php:197|read||| !getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_RECEIVED'') || getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_RECEIVED'') == ''-1'';", "accountancy/journal/variousjournal.php:201|read||| !getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_RECEIVED'') || getDolGlobalString(''ACCOUNTING_ACCOUNT_DISCOUNT_RECEIVED'') == ''-1'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_EXPENSEREPORT', 'string', NULL, 'accountancy', 'Stores the default general ledger account number used for expense report entries in accounting journals.', 'Read in accountancy/journal/expensereportsjournal.php:185 and :798, accountancy/journal/bankjournal.php:272, :729, and :867 (12+ occurrences). Checked against '''' and ''-1'' to detect unconfigured state; ''NotDefined'' is used as a reserved word fallback. No admin UI write found; HIDDEN_GUESS is 1.', 'If not set or set to ''-1'', expense report journal entries cannot be posted and the journal flags the configuration as incomplete.', 'String: general ledger account number; '''' or ''-1'' = not configured (treated as error in journals)', 1, 0, NULL, 1, 'eeb39025af2408a570e539d6214e0ec637e3ae7337d66cb44fdc8a60d509850f', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/expensereportsjournal.php:185|read|$account_salary = getDolGlobalString(''ACCOUNTING_ACCOUNT_EXPENSEREPORT'', ''NotDefined'');", "accountancy/journal/expensereportsjournal.php:656|check|if (!getDolGlobalString(''ACCOUNTING_ACCOUNT_EXPENSEREPORT'') || getDolGlobalString(''ACCOUNTING_ACCOUNT_EXPENSEREPORT'') == ''-1'') {", "accountancy/journal/bankjournal.php:272|read|$account_expensereport = getDolGlobalString(''ACCOUNTING_ACCOUNT_EXPENSEREPORT'', ''NotDefined''); // NotDefined is a reserved word", "accountancy/journal/bankjournal.php:867|read|$bookkeeping->numero_compte = getDolGlobalString(''ACCOUNTING_ACCOUNT_EXPENSEREPORT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_SUPPLIER', 'string', NULL, 'accountancy', 'Defines the default general accounting account used for suppliers.', 'Read across 22 occurrences including accountancy/class/accountingjournal.class.php:1128, compta/journal/purchasesjournal.php:162, journal/bankjournal.php:269,1293, journal/treasuryjournal.php:1400, journal/purchasesjournal.php:225,1059, fourn/card.php:281, and more.', 'If empty or ''-1'', code treats the supplier accounting account as not configured (in_array check against ['''',''-1'']); some code falls back to ''NotDefined'' as a reserved placeholder value.', ''''' or ''-1'' = not configured/reserved ''NotDefined'' placeholder used in fallback default.', 0, 0, NULL, 1, 'a0b24be7ca9fde75df44d66960e94d944a7700ddb32dce5275752c26ca7e4aa3', 'v2', '2026-07-24T06:41:12+00:00', '["$account_supplier = getDolGlobalString(''ACCOUNTING_ACCOUNT_SUPPLIER'', ''NotDefined''); // NotDefined is a reserved word", "$acctSupplierNotConfigured = in_array(getDolGlobalString(''ACCOUNTING_ACCOUNT_SUPPLIER''), ['''',''-1'']);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_SUPPLIER_DEPOSIT', 'string', NULL, 'accountancy', 'Accounting account number used to book supplier deposit invoices in the chart of accounts.', 'Configured via accountancy/admin/defaultaccounts.php (lines 368, 372). Read in accountancy/class/accountingaccount.class.php (lines 889, 912) to fetch the account object, and checked in accountancy/journal/purchasesjournal.php (lines 585, 1230) when classifying journal entries for supplier deposits.', 'Setting this to a valid account number causes supplier deposit lines to be posted to that account in the purchase journal; leaving it empty or set to ''-1'' skips the deposit-specific path.', 'String: chart-of-accounts account number; ''-1'' means not configured.', 0, 0, 'accountancy/admin/defaultaccounts.php|accountancy/admin/defaultaccounts.php', 1, 'c948d34d3c8d48580dd620b0f5622948e1b814248229327e9f4eda4b90aede61', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/defaultaccounts.php:372|check|if (isModEnabled(''societe'') && getDolGlobalString(''ACCOUNTING_ACCOUNT_SUPPLIER_DEPOSIT'') && getDolGlobalString(''ACCOUNTING_ACCOUNT_SUPPLIER_DEPOSIT'') != ''-1'') {", "accountancy/journal/purchasesjournal.php:585|check|if ($k == getDolGlobalString(''ACCOUNTING_ACCOUNT_SUPPLIER_DEPOSIT'')) {", "accountancy/class/accountingaccount.class.php:889|read|$result = $accountdeposittoventilated->fetch(0, getDolGlobalString(''ACCOUNTING_ACCOUNT_SUPPLIER_DEPOSIT''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_SUPPLIER_USE_AUXILIARY_ON_DEPOSIT', 'bool', NULL, 'accountancy', 'Controls whether the auxiliary (third-party) account is applied when posting supplier deposit invoices.', 'Configured via accountancy/admin/defaultaccounts.php (lines 213 write, 375 check). Checked in accountancy/journal/purchasesjournal.php at lines 584 and 1229 to decide whether auxiliary account details are included in supplier deposit journal entries.', 'When enabled, supplier deposit journal lines include auxiliary account information; when disabled, they are posted without it.', 'yesno (1/0): 1 to use auxiliary account on supplier deposits; 0 to disable.', 0, 0, 'accountancy/admin/defaultaccounts.php|accountancy/admin/defaultaccounts.php', 1, 'a4ccf72c1fc9b26a1436ae10a8d1191dc28fc9a1d169cc08e03ee6fcce916c45', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/defaultaccounts.php:213|write|$res = dolibarr_set_const($db, \"ACCOUNTING_ACCOUNT_SUPPLIER_USE_AUXILIARY_ON_DEPOSIT\", $setDisableAuxiliaryAccountOnSupplierDeposit, ''yesno'', 0, '''', $conf->entity);", "accountancy/admin/defaultaccounts.php:375|check|if (getDolGlobalInt(''ACCOUNTING_ACCOUNT_SUPPLIER_USE_AUXILIARY_ON_DEPOSIT'')) {", "accountancy/journal/purchasesjournal.php:584|check|if (getDolGlobalString(''ACCOUNTING_ACCOUNT_SUPPLIER_USE_AUXILIARY_ON_DEPOSIT'')) {", "accountancy/journal/purchasesjournal.php:1229|check|if (getDolGlobalString(''ACCOUNTING_ACCOUNT_SUPPLIER_USE_AUXILIARY_ON_DEPOSIT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_SUSPENSE', 'string', NULL, 'accountancy', 'Stores the general ledger suspense account number used when no specific third-party account can be determined.', 'Read in accountancy/journal/bankjournal.php at lines 732, 963, 1192, 1568, and 1474 where it is shown as ''UnknownAccountForThirdparty''. Also read in core/boxes/box_accountancy_suspense_account.php:73. Checked against '''' and ''-1'' at bankjournal.php:1471. No admin UI write found; HIDDEN_GUESS is 1.', 'If not set or set to ''-1'', the bank journal cannot post lines for unknown third parties; when set, those lines are posted to the suspense account for later correction.', 'String: general ledger account number; '''' or ''-1'' = not configured', 1, 0, NULL, 1, '721e3fc61a16d5e7a300373b0c712a2c592acd2eebbfcade0516a8e5a1575bf1', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/bankjournal.php:732|read|$accountingaccountsuspense->fetch(0, getDolGlobalString(''ACCOUNTING_ACCOUNT_SUSPENSE''), true);", "accountancy/journal/bankjournal.php:1471|check|if (!getDolGlobalString(''ACCOUNTING_ACCOUNT_SUSPENSE'') || getDolGlobalString(''ACCOUNTING_ACCOUNT_SUSPENSE'') == ''-1'') {", "accountancy/journal/bankjournal.php:1474|read|$accounttoshow = ''<span class=\"warning small\">''.$langs->trans(''UnknownAccountForThirdparty'', length_accountg(getDolGlobalString(''ACCOUNTING_ACCOUNT_SUSPENSE''))).''</span>'';", "core/boxes/box_accountancy_suspense_account.php:73|read|$suspenseAccount = getDolGlobalString(''ACCOUNTING_ACCOUNT_SUSPENSE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ACCOUNT_TRANSFER_CASH', 'string', NULL, 'accountancy', 'Accounting account number used to book internal bank-to-bank cash transfers in the bank journal export.', 'Read in accountancy/journal/bankjournal.php:276 and accountancy/journal/treasuryjournal.php:1065, both with default ''NotDefined'' (a reserved word per the inline comment) alongside other counterpart accounts (supplier, customer, employee, VAT).', 'Setting a valid accounting account number here allows internal transfer bank movements to be posted to that account in the bookkeeping; if left as ''NotDefined'', transfer lines cannot be properly bound to an account.', 'Any accounting account number string; default ''NotDefined'' is a reserved sentinel meaning not configured.', 1, 0, NULL, 1, 'fdb664fecfd9d4c1fcea43a0473c862d78c1dd768d762be03320ab7ac3dbdd40', 'v2', '2026-07-24T07:05:23+00:00', '["bankjournal.php:276: $account_transfer = getDolGlobalString(''ACCOUNTING_ACCOUNT_TRANSFER_CASH'', ''NotDefined''); // NotDefined is a reserved word", "treasuryjournal.php:1065: $account_transfer = getDolGlobalString(''ACCOUNTING_ACCOUNT_TRANSFER_CASH'', ''NotDefined''); // NotDefined is a reserved word"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_BANK_CONCILIATED', 'string', NULL, 'accountancy', 'Filters the bank journal to include only reconciled (conciliated) bank lines, or all lines.', 'Configured via accountancy/admin/index.php:653. Read in accountancy/journal/bankjournal.php:91 and accountancy/journal/treasuryjournal.php:69 as $only_rappro. Value 2 is checked specifically in the admin page; the journal files use the integer value directly as a filter parameter.', 'When set to 2 (or non-zero), the bank and treasury journals show only reconciled bank transactions; when 0 or unset, all bank lines are included.', '0 or unset = all bank lines; 2 = only reconciled/conciliated lines', 0, 0, 'accountancy/admin/index.php', 1, '3189511a9f3225a7b4e8d4e817ae71296bb6515bf08deee2edc3acb7c74395ad', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/index.php:653|check|if (getDolGlobalInt(''ACCOUNTING_BANK_CONCILIATED'') == 2) {", "accountancy/journal/bankjournal.php:91|read|$only_rappro = getDolGlobalInt(''ACCOUNTING_BANK_CONCILIATED'');", "accountancy/journal/treasuryjournal.php:69|read|$only_rappro = getDolGlobalInt(''ACCOUNTING_BANK_CONCILIATED'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_CAN_REOPEN_CLOSED_PERIOD', 'string', NULL, 'accountancy', 'Allows administrators to reopen a closed fiscal year period.', 'Checked in accountancy/admin/fiscalyear_card.php (line 396) to show the reopen button when the period is closed, and at line 176 to authorize the reopen action.', 'Enabling this setting makes the reopen action available for closed fiscal periods; disabling it prevents reopening once a period is closed.', 'Truthy string (non-empty) = reopening closed periods is allowed; empty/not set = reopening is not allowed.', 0, 0, 'accountancy/admin/fiscalyear_card.php|accountancy/admin/fiscalyear_card.php', 1, '0dec434466334ec0c36aac771634191a82569fa40af4d38a8775d463e9f1e708', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/fiscalyear_card.php:396|check|if (getDolGlobalString(''ACCOUNTING_CAN_REOPEN_CLOSED_PERIOD'') && $object->status == $object::STATUS_CLOSED) {", "accountancy/admin/fiscalyear_card.php:176|read|} elseif ($action == ''reopen'' /* && $permissiontoadd // always true */ && getDolGlobalString(''ACCOUNTING_CAN_REOPEN_CLOSED_PERIOD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_CLONING_ENABLE_INPUT_JOURNAL', 'bool', NULL, 'accountancy', 'Allows users to specify an input journal when cloning bookkeeping entries, instead of inheriting the source journal.', 'Checked at accountancy/bookkeeping/card.php:773, accountancy/bookkeeping/listbyaccount.php:948, and accountancy/bookkeeping/list.php:923 to show the journal input field on clone. Read at accountancy/class/bookkeeping.class.php:3512-3513 and :3617-3618 to determine whether to use the user-supplied journal or the source entry''s journal.', 'When enabled, cloned bookkeeping entries use the journal code/label entered by the user; when disabled, the source entry''s journal is copied verbatim.', '0 or not set = cloned entry inherits source journal; non-zero = user can specify a new journal when cloning.', 1, 0, NULL, 1, '8859335237e143ad1e6cb818b0740d76636cdaed0c8f3e47e2c6d6db1100178a', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/bookkeeping/card.php:773|check|if (getDolGlobalString(''ACCOUNTING_CLONING_ENABLE_INPUT_JOURNAL'')) {", "accountancy/class/bookkeeping.class.php:3512|read|$code_journal = getDolGlobalString(''ACCOUNTING_CLONING_ENABLE_INPUT_JOURNAL'') ? $code_journal : $bookKeeping->code_journal;", "accountancy/class/bookkeeping.class.php:3513|read|$journal_label = getDolGlobalString(''ACCOUNTING_CLONING_ENABLE_INPUT_JOURNAL'') ? $accountingJournal->label : $bookKeeping->journal_label;", "accountancy/bookkeeping/list.php:923|check|if (getDolGlobalString(''ACCOUNTING_CLONING_ENABLE_INPUT_JOURNAL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_CLOSURE_ACCOUNTING_GROUPS_USED_FOR_BALANCE_SHEET_ACCOUNT', 'string', NULL, 'accountancy', 'Defines the comma-separated list of accounting groups used to compute the balance-sheet account during accountancy closure.', 'Set from a text input in accountancy/admin/closure.php:169,76 via dolibarr_set_const (type ''chaine''), and read/exploded on commas in accountancy/closure/index.php:163,125 and accountancy/class/bookkeeping.class.php:3090.', 'Changing the list changes which accounting groups are included when computing the balance-sheet account during closure; if unset, the check in closure/index.php:163 fails (''if (!getDolGlobalString(...))'').', 'Comma-separated list of accounting group codes.', 0, 0, 'accountancy/admin/closure.php|accountancy/admin/closure.php', 1, 'f0ea6bd60a22f297f4f64e5eeb04b84197366bb27b3a8b4ef4fed405afebee03', 'v2', '2026-07-24T06:41:12+00:00', '["if (!dolibarr_set_const($db, ''ACCOUNTING_CLOSURE_ACCOUNTING_GROUPS_USED_FOR_BALANCE_SHEET_ACCOUNT'', $accountinggroupsusedforbalancesheetaccount, ''chaine'', 0, '''', $conf->entity)) {", "if (!getDolGlobalString(''ACCOUNTING_CLOSURE_ACCOUNTING_GROUPS_USED_FOR_BALANCE_SHEET_ACCOUNT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_CLOSURE_ACCOUNTING_GROUPS_USED_FOR_INCOME_STATEMENT', 'string', NULL, 'accountancy', 'Defines the comma-separated list of accounting groups used to compute the income statement during accountancy closure.', 'Set from a text input in accountancy/admin/closure.php:85,178 via dolibarr_set_const (type ''chaine''), and read/exploded on commas in accountancy/bookkeeping/balance.php:736, bookkeeping.class.php:2963,2964,3091, and closure/index.php:126,166.', 'Changing the list changes which accounting groups are included when computing the income statement during closure; if unset, closure/index.php:166 treats it as not configured.', 'Comma-separated list of accounting group codes.', 0, 0, 'accountancy/admin/closure.php|accountancy/admin/closure.php', 1, 'ed96c6f3b76281297a0b9194761db43dc33371b73a79405cfa5bb69d308edbdc', 'v2', '2026-07-24T06:41:12+00:00', '["if (!dolibarr_set_const($db, ''ACCOUNTING_CLOSURE_ACCOUNTING_GROUPS_USED_FOR_INCOME_STATEMENT'', $accountinggroupsusedforincomestatement, ''chaine'', 0, '''', $conf->entity)) {", "} elseif (!getDolGlobalString(''ACCOUNTING_CLOSURE_ACCOUNTING_GROUPS_USED_FOR_INCOME_STATEMENT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_CLOSURE_DEFAULT_JOURNAL', 'string', NULL, 'accountancy', 'Stores the default journal identifier used during accounting closure operations.', 'Written via accountancy/admin/closure.php:67 and read at accountancy/admin/closure.php:159 and accountancy/class/bookkeeping.class.php:3029 where it is passed to max(0, ...) to determine the journal ID.', 'Setting this constant pre-selects the journal for accounting closure entries; an invalid or missing value causes bookkeeping to use journal ID 0.', 'String (used as integer): journal ID; empty = 0 (no default journal)', 0, 0, 'accountancy/admin/closure.php|accountancy/admin/closure.php', 1, '5db03dc6dfb6fa874542539315d1a0ad5750d6afb92f0626109662c77cfe31fd', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/closure.php:67|write|if (!dolibarr_set_const($db, ''ACCOUNTING_CLOSURE_DEFAULT_JOURNAL'', $defaultjournal, ''chaine'', 0, '''', $conf->entity)) {", "accountancy/admin/closure.php:159|read|$defaultjournal = getDolGlobalString(''ACCOUNTING_CLOSURE_DEFAULT_JOURNAL'');", "accountancy/class/bookkeeping.class.php:3029|read|$journal_id = max(0, getDolGlobalString(''ACCOUNTING_CLOSURE_DEFAULT_JOURNAL''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_COUNTERPART_VAT_NPR', 'string', NULL, 'accountancy', 'Accounting account code used as the counterpart (subvention account) for non-recoverable VAT (NPR) amounts on purchase invoice lines.', 'Read in accountancy/journal/purchasesjournal.php:269 (`$compta_counterpart_tva_npr = getDolGlobalString(''ACCOUNTING_COUNTERPART_VAT_NPR'', ''NotDefined'')`) and accumulated into $tabother at lines 384-387 whenever a line has non-recoverable VAT (tva_npr). If unset, an on-screen error at line 1343 tells the admin to ''Set ACCOUNTING_COUNTERPART_VAT_NPR to the subvention account''.', 'Required when purchase invoices contain non-recoverable VAT lines; if left unset the purchases journal export shows a blocking error asking the admin to configure this constant.', 'Free-text accounting account number string (the ''subvention account''); falls back to literal ''NotDefined'' if unset, which triggers an error message in the journal UI.', 0, 0, NULL, 1, 'c8c9ba625ee4ca0fd9128f667493ee8612e6c82a28611da67112f4d34a3c62d0', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:269|read|$compta_counterpart_tva_npr = getDolGlobalString(''ACCOUNTING_COUNTERPART_VAT_NPR'', ''NotDefined'');", "accountancy/journal/purchasesjournal.php:1343: print ''...''.$langs->trans(\"VATAccountNotDefined\").'' (...NPR counterpart...). Set ACCOUNTING_COUNTERPART_VAT_NPR to the subvention account</span>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DATE_START_BINDING', 'string', NULL, 'accountancy', 'Defines the start date from which accountancy binding/journal computations are considered, used pervasively across accountancy list/index/journal pages.', 'Read across 49 occurrences, e.g. accountancy/customer/index.php:369,508,613,710, accountancy/customer/list.php:85, accountancy/class/accountingjournal.class.php:466, accountancy/journal/bankjournal.php:183, accountancy/journal/treasuryjournal.php:137, and 41 more.', 'Setting it restricts/filters which entries are considered for binding and journal listing starting from that date; exact date format/effect is not detailed further in the payload.', NULL, 0, 0, NULL, 1, '71043997ccdb27ee326cacdca4f086ab8aa9f54fc240994208449ca6a87ac81c', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalInt(''ACCOUNTING_DATE_START_BINDING'')) {", "if (empty($search_date_start) && getDolGlobalInt(''ACCOUNTING_DATE_START_BINDING'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DEFAULT_NOTIFIED_EXPORTFULL', 'string', NULL, 'accountancy', 'Controls whether full export is marked as notified by default in accountancy bookkeeping export.', 'Set via admin/admin/index.php:496 using dolibarr_set_const and checked in accountancy/admin/index.php:1123 and accountancy/bookkeeping/export.php:868.', 'Changing it toggles whether the export screen treats a full export as already notified (''true''/''false'').', NULL, 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '07068695920708c2c7f520adce96b4439a1178808a66132c80a125d08b19ff42', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalInt(''ACCOUNTING_DEFAULT_NOTIFIED_EXPORTFULL'')) {", "$res = dolibarr_set_const($db, \"ACCOUNTING_DEFAULT_NOTIFIED_EXPORTFULL\", $setexportenablefull, ''yesno'', 0, '''', $conf->entity);", "$checked_exportfull = getDolGlobalString(''ACCOUNTING_DEFAULT_NOTIFIED_EXPORTFULL'') ? ''true'' : ''false'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DEFAULT_NOTIFIED_VALIDATION_DATE', 'string', NULL, 'accountancy', 'Toggles whether the export screen defaults to enabling the ''notified validation date'' checkbox.', 'Set from accountancy/admin/index.php:482 via dolibarr_set_const (type ''yesno''), checked at accountancy/admin/index.php:1109 and read in accountancy/bookkeeping/export.php:839 to compute $checked_validationdate as ''true''/''false''.', 'Enabling it makes the export screen''s validation-date checkbox pre-checked by default.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, 'd287a777fcb079997c3e42dc531fa04c172afefd7ce4cd341ca4377ab6a3b2de', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_DEFAULT_NOTIFIED_VALIDATION_DATE\", $setexportenablevalidationdate, ''yesno'', 0, '''', $conf->entity);", "$checked_validationdate = getDolGlobalString(''ACCOUNTING_DEFAULT_NOTIFIED_VALIDATION_DATE'') ? ''true'' : ''false'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DEFAULT_NOT_EXPORT_LETTERING', 'string', NULL, 'accountancy', 'Toggles whether the export screen defaults to enabling the ''reconcile/lettering'' export checkbox.', 'Set from accountancy/admin/index.php:454 via dolibarr_set_const (type ''yesno''), checked at accountancy/admin/index.php:1081 and read in accountancy/bookkeeping/export.php:815 to compute $checked_exportreconcile as ''true''/''false''.', 'Enabling it makes the export screen''s reconcile/lettering-export checkbox pre-checked by default.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, 'd619bc50fba9c3d86bfe37c11fc4d45e41dc1c2b2af50b16cdf1ffe7f8f2706f', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_DEFAULT_NOT_EXPORT_LETTERING\", $setexportenablelettering, ''yesno'', 0, '''', $conf->entity);", "$checked_exportreconcile = getDolGlobalString(''ACCOUNTING_DEFAULT_NOT_EXPORT_LETTERING'') ? ''true'' : ''false'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DEFAULT_NOT_NOTIFIED_EXPORT_DATE', 'string', NULL, 'accountancy', 'Toggles whether the export screen defaults to enabling the ''export date'' checkbox.', 'Set from accountancy/admin/index.php:468 via dolibarr_set_const (type ''yesno''), checked at accountancy/admin/index.php:1095 and read in accountancy/bookkeeping/export.php:827 to compute $checked_exportdate as ''true''/''false''.', 'Enabling it makes the export screen''s export-date checkbox pre-checked by default.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, 'aa206c6e5474e45e3dafb421f4291684d74d2f9e12315845cf5595fb8e704746', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_DEFAULT_NOT_NOTIFIED_EXPORT_DATE\", $setexportenableexportdate, ''yesno'', 0, '''', $conf->entity);", "$checked_exportdate = getDolGlobalString(''ACCOUNTING_DEFAULT_NOT_NOTIFIED_EXPORT_DATE'') ? ''true'' : ''false'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DEFAULT_PERIOD_ON_TRANSFER', 'string', NULL, 'accountancy', 'Default period selected for the ''transfer to bookkeeping'' screen: previous month, current month, or fiscal year.', 'Read in accountancy/admin/index.php:625 (ADMIN_UI accountancy/admin/index.php) to render the binding-options select, and in core/lib/accounting.lib.php:384 inside getDefaultDatesForTransfer() which computes the actual default date range used by the transfer screen.', 'Changing it changes which default date range (previous month, current month, or the current fiscal year) is pre-selected/used when transferring accounting entries to the bookkeeping.', '0 = previous month (PreviousMonth), 1 = current month (CurrentMonth), 2 = fiscal year (Fiscalyear) [from admin select array and code comment ''0: previous month | 1: current month | 2: fiscal year''].', 0, 0, 'accountancy/admin/index.php', 1, 'f3615f0e28e5fa01f962ab47a9af5ab156b66e6b654f82d53dd63e3c0601473c', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/admin/index.php:624: $array = array(0=>$langs->trans(\"PreviousMonth\"), 1=>$langs->trans(\"CurrentMonth\"), 2=>$langs->trans(\"Fiscalyear\"));", "core/lib/accounting.lib.php: // Period by default on transfer (0: previous month | 1: current month | 2: fiscal year)", "core/lib/accounting.lib.php:384: $periodbydefaultontransfer = getDolGlobalInt(''ACCOUNTING_DEFAULT_PERIOD_ON_TRANSFER'', 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DISABLE_BINDING_ON_EXPENSEREPORTS', 'bool', NULL, 'accountancy', 'Disables accounting binding (bookkeeping linkage) for expense reports.', 'Set from accountancy/admin/index.php:342 (type ''yesno''), checked at accountancy/admin/index.php:669,706 and in core/menus/standard/eldy.lib.php:1830,1886 and auguria.lib.php:448, both gated by isModEnabled(''expensereport'').', 'Enabling it turns off the accounting-binding menu entry/behavior for expense reports when the expensereport module is enabled.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php|accountancy/admin/index.php', 1, '1843b1c6892a845fb303f620a74de2971ce56e42d49746659159d8fcd97db90e', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_DISABLE_BINDING_ON_EXPENSEREPORTS\", $setdisablebindingonexpensereports, ''yesno'', 0, '''', $conf->entity);", "if (isModEnabled(''expensereport'') && !getDolGlobalString(''ACCOUNTING_DISABLE_BINDING_ON_EXPENSEREPORTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DISABLE_BINDING_ON_PURCHASES', 'bool', NULL, 'core', 'Disables accounting binding (bookkeeping linkage) for purchases (supplier invoices).', 'Set from accountancy/admin/index.php:328 (type ''yesno''), checked at accountancy/admin/index.php:656 and in core/menus/standard/eldy.lib.php:1823,1877 and auguria.lib.php:442, both gated by isModEnabled(''supplier_invoice'').', 'Enabling it turns off the accounting-binding menu entry/behavior for purchases when the supplier_invoice module is enabled.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, 'e5512916e00b14688584ec94a808bdd9604493c60b89cf10fc24e6617ce4be5a', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_DISABLE_BINDING_ON_PURCHASES\", $setdisablebindingonpurchases, ''yesno'', 0, '''', $conf->entity);", "if (isModEnabled(''supplier_invoice'') && !getDolGlobalString(''ACCOUNTING_DISABLE_BINDING_ON_PURCHASES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DISABLE_BINDING_ON_SALES', 'bool', NULL, 'core', 'Disables accounting binding (bookkeeping linkage) for sales (customer invoices).', 'Set from accountancy/admin/index.php:314 (type ''yesno''), checked at accountancy/admin/index.php:643 and in core/menus/standard/auguria.lib.php:437 and eldy.lib.php:1816,1866,1872, gated by isModEnabled(''invoice'').', 'Enabling it turns off the accounting-binding menu entry/behavior for sales when the invoice module is enabled.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '52c6d5ce779ee3b738230b9079e925e9d4d453d30d9cf8aa78b5fcf82ee2682b', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_DISABLE_BINDING_ON_SALES\", $setdisablebindingonsales, ''yesno'', 0, '''', $conf->entity);", "if (isModEnabled(''invoice'') && !getDolGlobalString(''ACCOUNTING_DISABLE_BINDING_ON_SALES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DISABLE_TRANSFER_ON_ASSETS', 'bool', NULL, 'accountancy', 'Disables accounting transfer for asset-related journal entries.', 'Configured via accountancy/admin/index.php. Checked in 3 occurrences: admin page display at :612, write at :356, and accountancy/class/accountingjournal.class.php:379 which skips asset transfer when this constant is set.', 'When enabled, asset entries are excluded from accounting journal transfer operations.', '0 or unset = asset transfer enabled; non-empty = asset transfer disabled', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '89368e874754d98cc27221163e8b0d608dc6ad3e8e0018aad37875c18b944f34', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/index.php:356|write|$res = dolibarr_set_const($db, \"ACCOUNTING_DISABLE_TRANSFER_ON_ASSETS\", $setdisabletransferonassets, ''yesno'', 0, '''', $conf->entity);", "accountancy/class/accountingjournal.class.php:379|check|if (isModEnabled(''asset'') && !getDolGlobalInt(''ACCOUNTING_DISABLE_TRANSFER_ON_ASSETS'')) {", "accountancy/admin/index.php:612|check|if (getDolGlobalString(''ACCOUNTING_DISABLE_TRANSFER_ON_ASSETS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DISABLE_TRANSFER_ON_DISCOUNTS', 'bool', NULL, 'accountancy', 'Disables accounting transfer for discount-related journal entries (both sales and supplier invoices).', 'Configured via accountancy/admin/index.php. Checked in 4 occurrences: admin page display at :625 and write at :370, and accountancy/class/accountingjournal.class.php:385 (sales invoice discounts) and :391 (supplier invoice discounts).', 'When enabled, discount entries from both sales and supplier invoices are excluded from accounting journal transfer operations.', '0 or unset = discount transfer enabled; non-empty = discount transfer disabled', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '1a25e64a864886806859a0682caca62211bf33977af884b7123f532a07893cb4', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/index.php:370|write|$res = dolibarr_set_const($db, \"ACCOUNTING_DISABLE_TRANSFER_ON_DISCOUNTS\", $setdisabletransferondiscounts, ''yesno'', 0, '''', $conf->entity);", "accountancy/class/accountingjournal.class.php:385|check|if (isModEnabled(''invoice'') && !getDolGlobalInt(''ACCOUNTING_DISABLE_TRANSFER_ON_DISCOUNTS'')) {", "accountancy/class/accountingjournal.class.php:391|check|if (isModEnabled(''supplier_invoice'') && !getDolGlobalInt(''ACCOUNTING_DISABLE_TRANSFER_ON_DISCOUNTS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_DISSOCIATE_CASH_SALES', 'string', NULL, 'accountancy', 'Enables dissociation of cash sales into a separate accounting journal/menu entry.', 'Set from accountancy/admin/index.php:440 (dolibarr_set_const) and accountancy/admin/journals_list.php; checked in cashsellsjournal.php, sellsjournal.php, accountingjournal.class.php, and the eldy menu.', 'When enabled, cash sales (nature == 6) are processed/displayed separately in the cash sells journal and accounting journal class, and an extra menu entry appears.', NULL, 0, 0, 'accountancy/admin/journals_list.php|accountancy/admin/index.php|accountancy/admin/index.php', 1, '5b1d5cb0019d5bfba1cc610ee6f2ec816072b3508f66b115bf8e09edd8436556', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalInt(''ACCOUNTING_DISSOCIATE_CASH_SALES'')) {", "$res = dolibarr_set_const($db, \"ACCOUNTING_DISSOCIATE_CASH_SALES\", $setenabledissociatecashsales, ''yesno'', 0, '''', $conf->entity);", "} elseif ($nature == 6 && getDolGlobalInt(''ACCOUNTING_DISSOCIATE_CASH_SALES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ENABLE_AUTOLETTERING', 'bool', NULL, 'accountancy', 'Enables automatic lettering (auto-reconciliation) of accounting entries in journals.', 'Set from accountancy/admin/index.php:398 (type ''yesno''), checked at accountancy/admin/index.php:906 and in journal/purchasesjournal.php:568, cashsellsjournal.php:657, sellsjournal.php:663 and bankjournal.php:987, always combined with ACCOUNTING_ENABLE_LETTERING.', 'Enabling it, together with ACCOUNTING_ENABLE_LETTERING, triggers automatic lettering during journal processing in purchases, cash-sells, sells and bank journals.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '795ffb57abba15e10251738b9493ffee9ec7d0532ad949cd492fc55de54ff321', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_ENABLE_AUTOLETTERING\", $setenableautolettering, ''yesno'', 0, '''', $conf->entity);", "if (getDolGlobalInt(''ACCOUNTING_ENABLE_LETTERING'') && getDolGlobalInt(''ACCOUNTING_ENABLE_AUTOLETTERING'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ENABLE_EXPORT_DRAFT_JOURNAL', 'bool', NULL, 'accountancy', 'Enables a button/feature to export draft (not-yet-validated) journal entries.', 'Set from accountancy/admin/index.php:300 (type ''yesno''); checked in journal/variousjournal.php:297, treasuryjournal.php:1408, purchasesjournal.php:1068, cashsellsjournal.php:1148, expensereportsjournal.php:665, sellsjournal.php:1154, bankjournal.php:1308. Comment: ''Note that to have the button to get this feature enabled, you must enable ACCOUNTING_ENABLE_EXPORT_DRAFT_JOURNAL''.', 'Enabling it is required (per the code comment) to show the draft-journal export button/feature across various journals.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php', 1, '4edfd9529ed5103e905dd53a44a47f06e9fc440c1e88e37759d49bd23a4853c4', 'v2', '2026-07-24T06:41:12+00:00', '["// Note that to have the button to get this feature enabled, you must enable ACCOUNTING_ENABLE_EXPORT_DRAFT_JOURNAL", "$res = dolibarr_set_const($db, \"ACCOUNTING_ENABLE_EXPORT_DRAFT_JOURNAL\", $setenabledraftexport, ''yesno'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ENABLE_LETTERING', 'bool', NULL, 'accountancy', 'Enables the lettering (reconciliation) feature in accountancy.', 'Set from accountancy/admin/index.php:384 (type ''yesno''); checked across 20 occurrences including accountancy/admin/index.php:884,873, admin/account.php:115, bookkeeping/export.php:813, bookkeeping/card.php:480, bookkeeping/listbyaccount.php:503,602, and 12 more.', 'Enabling it turns on lettering-related UI and processing (export options, account card options, listbyaccount reconciliation) across accountancy screens.', '''yesno'' type (0/1).', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php|accountancy/admin/account.php|accountancy/admin/index.php', 1, '350c99491dd3a4821a7429e31c659007524a9b32082ef86b5f7f3594977a12a6', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"ACCOUNTING_ENABLE_LETTERING\", $setenablelettering, ''yesno'', 0, '''', $conf->entity);", "if (getDolGlobalInt(''ACCOUNTING_ENABLE_LETTERING'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ENABLE_MULTI_REPORT', 'bool', NULL, 'accountancy', 'Enables a ''new system'' for multiple accounting reports/categories.', 'Checked across 11 occurrences in accountancy/admin/categories_list.php:87,170,454,535,993, admin/account.php:274,783, admin/categories.php:98 (sets $useNewSystem). Comment in accountancy/class/accountancycategory.class.php:913: ''Requires constant ACCOUNTING_ENABLE_MULTI_REPORT''.', 'Enabling it switches accounting categories/reports to the ''new system'' referenced by the code comment, affecting category list and report screens.', NULL, 0, 0, 'accountancy/admin/categories_list.php|accountancy/admin/categories_list.php|accountancy/admin/categories_list.php|accountancy/admin/categories_list.php|accountancy/admin/categories_list.php|accountancy/admin/categories_list.php|accountancy/admin/categories.php|accountancy/admin/account.php|accountancy/admin/account.php', 1, '051a1ad09df5b6a68f1e000f3f13f10d5c3e343bae7c24a2181d8e0779698dea', 'v2', '2026-07-24T06:41:12+00:00', '["// Requires constant ACCOUNTING_ENABLE_MULTI_REPORT", "$useNewSystem = (getDolGlobalInt(''ACCOUNTING_ENABLE_MULTI_REPORT''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_ENABLE_TABONTHIRDPARTY', 'bool', NULL, 'accountancy', 'Adds an accounting movements tab on third-party (company) record pages for users with the appropriate rights.', 'When enabled and the accounting module is active, core/lib/company.lib.php:144 injects an extra tab on third-party pages, provided the user holds the ''accounting > mouvements > lire'' right. Configured via accountancy/admin/index.php.', 'Enabling this constant exposes accounting ledger movements directly on the third-party card; disabling it hides that tab.', 'yesno (truthy=tab shown, empty/0=tab hidden)', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '6013df4f26f60cbdd1706e71857923ffefedaba1421abfd6847c935957eeca0c', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/company.lib.php:144|check|if (isModEnabled(''accounting'') && getDolGlobalString(''ACCOUNTING_ENABLE_TABONTHIRDPARTY'') && ($user->hasRight(''accounting'', ''mouvements'', ''lire''))) {", "accountancy/admin/index.php:426|write|$res = dolibarr_set_const($db, \"ACCOUNTING_ENABLE_TABONTHIRDPARTY\", $setenabletabonthirdparty, ''yesno'', 0, '''', $conf->entity);", "accountancy/admin/index.php:865|check|if (getDolGlobalString(''ACCOUNTING_ENABLE_TABONTHIRDPARTY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPENSEREPORT_DO_NOT_DISPATCH_TAXES', 'string', NULL, 'accountancy', 'When enabled, keeps expense report tax amounts on the same accounting line instead of splitting them to a separate tax account during journalization.', 'Read once in the accountancy expense-report journal generator (accountancy/journal/expensereportsjournal.php:187) with an inline comment explaining its effect.', 'Enabling it prevents tax from being split off from the base entry and credited to a separate tax account, which the comment says is appropriate for non-VAT countries like the USA.', 'Boolean-like: enabled (non-zero) = tax stays with the base line; disabled/unset = tax is split off to a separate tax account (default accounting behavior).', 0, 0, NULL, 1, 'd32983fbe58bdf3d49e2133291d7511a931497b7aff64b1912acc48c10208c80', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/expensereportsjournal.php:187: getDolGlobalInt(''ACCOUNTING_EXPENSEREPORT_DO_NOT_DISPATCH_TAXES''); //If enabled, Tax will NOT get split off from the base entry and credited to a separate tax account (good for non-VAT countries like USA)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_DATE', 'string', NULL, 'accountancy', 'Specifies the date format string used for date fields in accounting exports.', 'Used in accountancy/class/accountancyexport.class.php:1361 via dol_print_date and registered as an export parameter in accountancyexport.class.php:256. The default fallback is ''%Y-%m-%d''. Configured via accountancy/admin/index.php.', 'Changing the date format alters how document dates appear in exported accounting files; an incorrect format string produces malformed dates.', 'strftime-compatible format string; default fallback is ''%Y-%m-%d''', 0, 0, 'accountancy/admin/index.php', 1, 'a4e7a9d00b3dbb45ced44a8cb64b1faec8c6631bfc6726116b169b1c61808c26', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/accountancyexport.class.php:256|read|''ACCOUNTING_EXPORT_DATE'' => getDolGlobalString(''ACCOUNTING_EXPORT_DATE'', ''%Y-%m-%d''),", "accountancy/class/accountancyexport.class.php:1361|read|$date_document = dol_print_date($line->doc_date, getDolGlobalString(''ACCOUNTING_EXPORT_DATE''));", "accountancy/admin/index.php:924|read|print ''            jQuery(\"#ACCOUNTING_EXPORT_DATE\").val(\"''.getDolGlobalString(''ACCOUNTING_EXPORT_DATE'').''\");''.\"\\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_ENDLINE', 'string', NULL, 'accountancy', 'Controls the line ending character used when exporting accounting data: 1 produces LF (Unix), any other truthy value produces CRLF (Windows).', 'Read in accountancy/class/accountancyexport.class.php:133 to set the end-of-line sequence for export files. If not set, defaults to LF (\n). Also stored with a default of 1 per accountancyexport.class.php:255.', 'Setting this to 1 produces Unix line endings (\n); setting to any other truthy value produces Windows line endings (\r\n); leaving unset defaults to LF.', '1 = LF (\n); other truthy value = CRLF (\r\n); empty/unset = LF (\n) by default.', 1, 0, NULL, 1, '6faf9c3141b8132c286d95ff59d99a7e1213117b50a796894c34af8b6e9bdd5f', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/accountancyexport.class.php:133|read|$this->end_line = getDolGlobalString(''ACCOUNTING_EXPORT_ENDLINE'') ? (getDolGlobalInt(''ACCOUNTING_EXPORT_ENDLINE'') == 1 ? \"\\n\" : \"\\r\\n\") : \"\\n\";", "accountancy/class/accountancyexport.class.php:255|read|''ACCOUNTING_EXPORT_ENDLINE'' => getDolGlobalString(''ACCOUNTING_EXPORT_ENDLINE'', 1),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_FORMAT', 'string', NULL, 'accountancy', 'Specifies the file format used for accounting journal exports (e.g. ''txt'').', 'Configured via accountancy/admin/index.php:902 (JavaScript sets a select element) with a commented example at line 266 showing ''txt''. Read in accountancy/tpl/export_journal.tpl.php:51 and accountancy/class/accountancyexport.class.php:253 with default ''txt'', and displayed on the export button in accountancy/bookkeeping/balance.php:359.', 'Changing this value switches the output format of all accounting journal export files.', 'String format code (e.g. ''txt''); default ''txt'' per accountancy/class/accountancyexport.class.php:253', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '15696fe2eb7d3d5c6f593433e7f3eae23f04df0bdfa614699c3f98b7619b8796', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/tpl/export_journal.tpl.php:51|read|$format = getDolGlobalString(''ACCOUNTING_EXPORT_FORMAT'');", "accountancy/class/accountancyexport.class.php:253|read|''ACCOUNTING_EXPORT_FORMAT'' => getDolGlobalString(''ACCOUNTING_EXPORT_FORMAT'', ''txt''),", "accountancy/admin/index.php:266  //\tdolibarr_set_const($db, ''ACCOUNTING_EXPORT_FORMAT'', ''txt'', ''chaine'', 0, '''', $conf->entity);", "accountancy/bookkeeping/balance.php:359|read|$newcardbutton .= dolGetButtonTitle($langs->trans(\"Export\").'' ('' . getDolGlobalString(''ACCOUNTING_EXPORT_FORMAT'').'')'', '''', ''fa fa-file-csv paddingleft'', $_SERVER[''PHP_SELF''], ''expo"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_MODELCSV', 'string', NULL, 'accountancy', 'Selects the export template (model) used when exporting accounting bookkeeping entries.', 'Written in accountancy/admin/index.php:262 and read in accountancy/bookkeeping/export.php:229 to determine which export format is applied. Displayed as a select list in accountancy/admin/index.php:967.', 'Changing this value switches the accounting export format; an invalid or missing model identifier causes the export to fall back to undefined behaviour.', 'String identifier of an available export template as listed in the admin UI select list', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '59cc03d052825bc7d5c213992a28e8e4d5ff5f675bdc1f6ee8c9cdad0eecd82d', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/index.php:262|write|if (!dolibarr_set_const($db, ''ACCOUNTING_EXPORT_MODELCSV'', $modelcsv, ''chaine'', 0, '''', $conf->entity)) {", "accountancy/bookkeeping/export.php:229|read|$formatexportset = getDolGlobalString(''ACCOUNTING_EXPORT_MODELCSV'');  // TODO: Verify if this should be int!", "accountancy/admin/index.php:967|read|print $form->selectarray(\"ACCOUNTING_EXPORT_MODELCSV\", $listofexporttemplates, getDolGlobalString(''ACCOUNTING_EXPORT_MODELCSV''), 0, 0, 0, '''', 0, 0, 0, '''', '''', 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_NO_DATE_IN_FILENAME', 'string', NULL, 'accountancy', 'Omits the date/time suffix normally appended to generated accounting export filenames.', 'Read as an int in accountancy/tpl/export_journal.tpl.php:52 ($nodateexport) and used at line 87 to conditionally suppress the $date_export segment (''_YYYYMMDDHHMMSS'') of the export filename.', 'When set (truthy), the export filename no longer contains a date/time stamp, which can risk overwriting previous exports with the same name; when unset, each export filename includes a unique date/time suffix.', 'Not set/0 (default): filename includes date_export suffix. Truthy int: date suffix omitted from filename.', 1, 0, NULL, 1, 'ad31f35a3ae13b8c7042536748c76e93ce7e0a632c7c9c5722cf5c0a9a81c352', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/tpl/export_journal.tpl.php:52|read|$nodateexport = getDolGlobalInt(''ACCOUNTING_EXPORT_NO_DATE_IN_FILENAME'');", "accountancy/tpl/export_journal.tpl.php:87|code|$completefilename = (...).$filename.($nodateexport ? \"\" : $date_export).\".\".$format;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_PREFIX_SPEC', 'string', NULL, 'accountancy', 'Adds a custom prefix string to the generated accounting export filename.', 'Read in accountancy/tpl/export_journal.tpl.php:50 and used at line 87 to build the export filename ($code_$prefix_$filename$date_export.$format); also exposed in the admin UI at accountancy/admin/index.php:119 as part of the ''Parameters for export options'' ($main_option list).', 'When set, the accounting export filename includes this prefix segment (with a trailing underscore) before the base filename; when unset, that segment is omitted from the filename.', 'Free-form string prepended (with ''_'' separator) to the export filename when non-empty.', 0, 0, NULL, 1, 'caa352bf150235f75a6e1a40a70a3e60cbb761a9f70680042a8e9007c2212355', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/tpl/export_journal.tpl.php:50|read|$prefix = getDolGlobalString(''ACCOUNTING_EXPORT_PREFIX_SPEC'');", "accountancy/tpl/export_journal.tpl.php:87|code|$completefilename = ($code ? $code.\"_\" : \"\").($prefix ? $prefix.\"_\" : \"\").$filename.($nodateexport ? \"\" : $date_export).\".\".$format;", "accountancy/admin/index.php:119|admin_ui|''ACCOUNTING_EXPORT_PREFIX_SPEC'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_QUADRATUS_DISABLE_THIRDPARTY_UPDATE', 'bool', NULL, 'accountancy', 'Controls whether the Quadratus accounting export marks thirdparty records for update ("Maj" field) in the export file.', 'Read in AccountancyExport::export...() at accountancy/class/accountancyexport.class.php:957, next to a comment block explaining the ''Maj'' field: blank means no update if account already exists, 2 means partial update.', 'When enabled, the exported ''Maj'' field is left blank instead of ''2'', so Quadratus will not update existing thirdparty accounts (alpha key, label, address, collectif, RIB) from the export.', 'blank = no update if account already exists; 2 = partial update (alpha key, label, address, collectif, RIB) [from adjacent code comment].', 1, 0, NULL, 1, '8e3f4df964b8513ba0cbdaf277b23b0cdddd7728c7bd5b056756fb76ed596d73', 'v2', '2026-07-24T07:05:23+00:00', '["accountancyexport.class.php: // Field \"Maj\" (static position 1 char):", "accountancyexport.class.php: // blank = no update if account already exists", "accountancyexport.class.php: // 2 = partial update (alpha key, label, address, collectif, RIB)", "accountancyexport.class.php:957: if (getDolGlobalString(''ACCOUNTING_EXPORT_QUADRATUS_DISABLE_THIRDPARTY_UPDATE'')) { $tab[''Maj''] = '' ''; } else { $tab[''Maj''] = 2; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_REMOVE_EXPENSEREPORT_SOURCE_FILE', 'string', NULL, 'accountancy', 'Determines whether the source expense report file is removed after an accounting export.', 'Checked at accountancy/bookkeeping/export.php:861 and in accountancy/class/accountancyexport.class.php:1611 and :1851. When non-zero, the expense report source file is removed; when zero, it is kept.', 'Enabling this constant causes the source expense report file to be deleted after export; disabling it preserves the file.', '0 or not set = source file kept; non-zero = source file removed after export.', 1, 0, NULL, 1, '34e4ebb3ce2a392ed2a3ccded9768f4527c4fb2e8216a3641a89a11a61d5704a', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/bookkeeping/export.php:861|check|if (getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_EXPENSEREPORT_SOURCE_FILE'')) {", "accountancy/class/accountancyexport.class.php:1611|check|if (!getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_EXPENSEREPORT_SOURCE_FILE'')) {", "accountancy/class/accountancyexport.class.php:1851|check|if (!getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_EXPENSEREPORT_SOURCE_FILE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_REMOVE_INVOICE_SOURCE_FILE', 'string', NULL, 'accountancy', 'Determines whether the source invoice file is removed after an accounting export.', 'Checked at accountancy/bookkeeping/export.php:858 and in accountancy/class/accountancyexport.class.php:1607 and :1847. When the integer value is non-zero, the invoice source file is removed; when zero, it is kept.', 'Enabling this constant causes the source invoice file to be deleted after export; disabling it preserves the file.', '0 or not set = source file kept; non-zero = source file removed after export.', 1, 0, NULL, 1, '6cbf8ef7d8c9dedc7167196b90cd08315352c801b750bf857c9892f373974370', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/bookkeeping/export.php:858|check|if (getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_INVOICE_SOURCE_FILE'')) {", "accountancy/class/accountancyexport.class.php:1607|check|if (!getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_INVOICE_SOURCE_FILE'')) {", "accountancy/class/accountancyexport.class.php:1847|check|if (!getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_INVOICE_SOURCE_FILE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_REMOVE_SUPPLIERINVOICE_SOURCE_FILE', 'string', NULL, 'accountancy', 'Determines whether the source supplier invoice file is removed after an accounting export.', 'Checked at accountancy/bookkeeping/export.php:864 and in accountancy/class/accountancyexport.class.php:1615 and :1855. When non-zero, the supplier invoice source file is removed; when zero, it is kept.', 'Enabling this constant causes the source supplier invoice file to be deleted after export; disabling it preserves the file.', '0 or not set = source file kept; non-zero = source file removed after export.', 1, 0, NULL, 1, '30385c8f8b4c59e83089bafe4cb94ce932898997d614bf88b5596747915c32d8', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/bookkeeping/export.php:864|check|if (getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_SUPPLIERINVOICE_SOURCE_FILE'')) {", "accountancy/class/accountancyexport.class.php:1615|check|if (!getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_SUPPLIERINVOICE_SOURCE_FILE'')) {", "accountancy/class/accountancyexport.class.php:1855|check|if (!getDolGlobalInt(''ACCOUNTING_EXPORT_REMOVE_SUPPLIERINVOICE_SOURCE_FILE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_SEPARATORCSV', 'string', NULL, 'accountancy', 'Sets the CSV field separator character used for accountancy exports.', 'Read across 10 occurrences including accountancy/admin/index.php:996 (JS field), journal/bankjournal.php:1092, purchasesjournal.php:856, cashsellsjournal.php:937, expensereportsjournal.php:551, sellsjournal.php:943, bookkeeping/balance.php:241, and accountancyexport.class.php:132 ($this->separator).', 'Changing it changes the separator character used when generating CSV exports across the various accountancy journals and the export class.', NULL, 0, 0, 'accountancy/admin/index.php', 1, 'e2c0fe48e29e043181f95d3e22ed4d6e926ecefa2e0bc13af37205a131bebf75', 'v2', '2026-07-24T06:41:12+00:00', '["$sep = getDolGlobalString(''ACCOUNTING_EXPORT_SEPARATORCSV'');", "$this->separator = getDolGlobalString(''ACCOUNTING_EXPORT_SEPARATORCSV'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_EXPORT_XIMPORT_FORCE_FILENAME', 'string', NULL, 'accountancy', 'Forces the accounting export filename to the fixed name ''XIMPORT.TXT'' when exporting the general ledger in Ciel format, to support automatic import of the file from a directory by Sage 50c Ciel software.', 'Checked in accountancy/tpl/export_journal.tpl.php:84 (format code ''ciel'' and type_export ''general_ledger''); documented directly in a code comment at accountancy/class/accountancyexport.class.php:838-839 (''If you want to force filename to "XIMPORT.TXT" for automatically import file present in a directory: use constant ACCOUNTING_EXPORT_XIMPORT_FORCE_FILENAME'').', 'When set, exporting the general ledger in Ciel format writes to a fixed filename ''XIMPORT.TXT'' instead of the normal prefix/date-based filename, enabling Sage 50c''s automatic import folder workflow; repeated exports would overwrite the same file.', 'Not set/falsy (default): normal filename pattern used. Truthy: filename forced to ''XIMPORT.TXT'' for Ciel general_ledger export.', 1, 0, NULL, 1, '84e4e70317f74a990c52834e25a059b5d76be20c98bdb778d0988c237e22836b', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/class/accountancyexport.class.php:838-839|comment|If you want to force filename to \"XIMPORT.TXT\" for automatically import file present in a directory : use constant ACCOUNTING_EXPORT_XIMPORT_FORCE_FILENAME", "accountancy/tpl/export_journal.tpl.php:84|check|elseif ($accountancyexport->getFormatCode($formatexportset) == ''ciel'' && $type_export == \"general_ledger\" && getDolGlobalString(''ACCOUNTING_EXPORT_XIMPORT_FORCE_FILENAME'')) {", "accountancy/tpl/export_journal.tpl.php:85|code|$completefilename = \"XIMPORT.TXT\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_FEC_DECIMAL_LENGTH', 'string', NULL, 'core', 'Sets the number of decimal digits used when formatting amounts in FEC accounting exports.', 'Read in core/lib/functions2.lib.php:2793 where it overrides the default of 2 decimal places for FEC output.', 'Changing this alters the precision of all monetary amounts written to FEC export files.', 'Integer number of decimal digits; default 2.', 1, 0, NULL, 1, 'c83ade846c9a3fba62f911a1d4326a268afb9913bd9420fc683aa4e1a6362051', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:2793|read|$nbdecimal = (!getDolGlobalString(''ACCOUNTING_FEC_DECIMAL_LENGTH'') ? 2 : $conf->global->ACCOUNTING_FEC_DECIMAL_LENGTH);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_FEC_DECIMAL_SEPARATOR', 'string', NULL, 'core', 'Sets the decimal separator character used when formatting amounts in FEC accounting exports.', 'Read in core/lib/functions2.lib.php:2796 where it overrides the default comma '','' separator for FEC output.', 'Changing this alters the decimal separator in all monetary amounts written to FEC export files, which must match the expected format of receiving software.', 'Any character string; default '',''.', 1, 0, NULL, 1, '5b13e223afa8716694e16b491c560830765411dcbfd1c3224ac10bbc3e5ead18', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:2796|read|$dec = (!getDolGlobalString(''ACCOUNTING_FEC_DECIMAL_SEPARATOR'') ? '','' : $conf->global->ACCOUNTING_FEC_DECIMAL_SEPARATOR);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_FEC_THOUSAND_SEPARATOR', 'string', NULL, 'core', 'Sets the thousands separator character used when formatting amounts in FEC accounting exports.', 'Read in core/lib/functions2.lib.php:2797 where it overrides the default empty string (no thousands separator) for FEC output.', 'Setting this adds a thousands separator to all monetary amounts in FEC export files.', 'Any character string; default '''' (no separator).', 1, 0, NULL, 1, 'c2d8307593a4eba47168d2fad44fc7e3d77072446256ea4c09eb908e7a941979', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:2797|read|$thousand = (!getDolGlobalString(''ACCOUNTING_FEC_THOUSAND_SEPARATOR'') ? '''' : $conf->global->ACCOUNTING_FEC_THOUSAND_SEPARATOR);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE', 'bool', NULL, 'accountancy', 'Forces VAT reverse-charge accounting treatment regardless of the company''s country code.', 'Normally reverse-charge processing in the purchases journal is restricted to French companies (country_code == ''FR''); setting this constant extends that behaviour to all entities. It is also checked in fourn/card.php:326 and elsewhere. Configured via accountancy/admin/index.php.', 'Enabling this constant activates VAT reverse-charge journal entries and related UI for companies outside France; disabling it restricts that treatment to FR-coded companies only.', 'yesno (truthy=forced, empty/0=country-code-dependent)', 0, 0, 'accountancy/admin/index.php|accountancy/admin/defaultaccounts.php|accountancy/admin/index.php', 1, '955acafa439f9ab43cc8b7f418a6025c33cea4ed0b665ee332d8b3a1a88f4d61', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/purchasesjournal.php:313|check|if (($mysoc->country_code == ''FR'' || getDolGlobalString(''ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE'')) && $obj->vat_reverse_charge == 1 ...", "accountancy/journal/purchasesjournal.php:645|check|if ($mysoc->country_code == ''FR'' || getDolGlobalString(''ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE'')) {", "accountancy/admin/index.php:412|write|$res = dolibarr_set_const($db, \"ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE\", $setenablevatreversecharge, ''yesno'', 0, '''', $conf->entity);", "fourn/card.php:326|check|if (getDolGlobalString(''ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LABEL_OPERATION_ON_TRANSFER', 'string', NULL, 'accountancy', 'Controls how the operation label is generated when accounting entries are transferred to the general ledger.', 'Documented in accountancy/class/bookkeeping.class.php:2615-2618: ''If ACCOUNTING_LABEL_OPERATION_ON_TRANSFER is 0, we concat thirdparty name, ref and label. If ... is 1, we concat thirdparty name, ref. If ... is 2, we return just thirdparty name.'' Configured via accountancy/admin/index.php. 4 occurrences.', 'Setting different integer values changes what information is included in the accounting entry label: 0 gives full detail, 1 omits the label, 2 gives only the third-party name.', '0 = thirdparty name + ref + label; 1 = thirdparty name + ref; 2 = thirdparty name only', 0, 0, 'accountancy/admin/index.php', 1, '30d95fd6c4820aaefd6191ef867b9cd3ae0a4372d74eeb20afb962c44d01b270', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/bookkeeping.class.php:2616  * If ACCOUNTING_LABEL_OPERATION_ON_TRANSFER is 0, we concat thirdparty name, ref and label.", "accountancy/class/bookkeeping.class.php:2617  * If ACCOUNTING_LABEL_OPERATION_ON_TRANSFER is 1, we concat thirdparty name, ref.", "accountancy/class/bookkeeping.class.php:2618  * If ACCOUNTING_LABEL_OPERATION_ON_TRANSFER is 2, we return just thirdparty name", "accountancy/class/bookkeeping.class.php:2615  * Generate label operation when operation is transferred into accounting according to ACCOUNTING_LABEL_OPERATION_ON_TRANSFER"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LENGTH_AACCOUNT', 'string', NULL, 'accountancy', 'Sets the fixed padding length for auxiliary (sub-account) account numbers in the accounting module.', 'Checked and read across 9 occurrences in accountancy/admin/subaccount.php (lines 159-160, 206-207, 254-255) and accountancy/admin/account.php (lines 287-288), where it is used as `$lengthpaddingaccount`.', 'Setting this value enforces zero-padding of auxiliary account codes to the specified length, ensuring uniform account number formatting.', 'Integer (number of digits for padding); 0 or empty means no padding is applied.', 0, 0, 'accountancy/admin/subaccount.php|accountancy/admin/subaccount.php|accountancy/admin/subaccount.php|accountancy/admin/subaccount.php|accountancy/admin/subaccount.php|accountancy/admin/subaccount.php|accountancy/admin/account.php|accountancy/admin/account.php', 1, 'ac1b02a3d12b15062aaa77777ea1777182793d8956a7dc23beb3e0443310b993', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/subaccount.php:159|check|if (getDolGlobalInt(''ACCOUNTING_LENGTH_AACCOUNT'')) {", "accountancy/admin/subaccount.php:160|read|$lengthpaddingaccount = getDolGlobalInt(''ACCOUNTING_LENGTH_AACCOUNT'');", "accountancy/admin/account.php:288|read|$lengthpaddingaccount = max(getDolGlobalInt(''ACCOUNTING_LENGTH_GACCOUNT''), getDolGlobalInt(''ACCOUNTING_LENGTH_AACCOUNT''));", "accountancy/admin/account.php:287|check|if (getDolGlobalInt(''ACCOUNTING_LENGTH_GACCOUNT'') || getDolGlobalInt(''ACCOUNTING_LENGTH_AACCOUNT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LENGTH_DESCRIPTION', 'string', NULL, 'accountancy', 'Sets the maximum character length for truncating description text in accounting line-binding and list pages.', 'Configured via accountancy/admin/productaccount.php:763. Read in 7 locations: customer/lines.php:724, expensereport/lines.php:619, customer/list.php:855, expensereport/list.php:663, supplier/lines.php:753, and supplier/list.php:893, all with a default of 32.', 'Increasing this value allows longer description strings to be displayed in accounting tables; decreasing it truncates descriptions more aggressively.', 'Integer character count (default 32); controls truncation of description text in accounting views', 0, 0, 'accountancy/admin/productaccount.php', 1, '3e035e85df1a88763554e3ba907c623a88d5a7d7c8fd7efc010642202ebe5023', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:763|read|$trunclength = getDolGlobalInt(''ACCOUNTING_LENGTH_DESCRIPTION'', 32);", "accountancy/customer/lines.php:724|read|$trunclength = getDolGlobalInt(''ACCOUNTING_LENGTH_DESCRIPTION'', 32);", "accountancy/expensereport/lines.php:619|read|$trunclength = getDolGlobalInt(''ACCOUNTING_LENGTH_DESCRIPTION'', 32);", "accountancy/supplier/lines.php:753|read|$trunclength = getDolGlobalInt(''ACCOUNTING_LENGTH_DESCRIPTION'', 32);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LENGTH_DESCRIPTION_ACCOUNT', 'string', NULL, 'core', 'Sets the truncation length for accounting account labels displayed in the account-selection dropdown.', 'Read in core/class/html.formaccounting.class.php:388 as $trunclength, defaulting to 50, used when building the cached list of accounting account options for select_account()-style dropdowns.', 'Increasing it shows longer (less truncated) account labels in the accounting account select list; decreasing it truncates labels more aggressively.', 'Integer character length; default is 50.', 1, 0, NULL, 1, 'a2bfa1082982e81f20bc7368d2e882af95ac5a64561b47d14ecfd3e9fe9ed2a7', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formaccounting.class.php:388|read|$trunclength = getDolGlobalInt(''ACCOUNTING_LENGTH_DESCRIPTION_ACCOUNT'', 50);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LENGTH_GACCOUNT', 'string', NULL, 'accountancy', 'Sets the minimum length (padding) applied to general accounting account numbers.', 'Used in accountancy/admin/account.php:288 as one of the two values compared with max() to determine the padding length for account numbers, alongside ACCOUNTING_LENGTH_AACCOUNT. Also read in core/lib/accounting.lib.php:162.', 'Changing this value alters how general account numbers are padded or validated; an inconsistency with ACCOUNTING_LENGTH_AACCOUNT may affect account display and journal entries.', 'Integer representing the desired account number length; 0 or not set = no enforced length', 0, 0, 'accountancy/admin/account.php|accountancy/admin/account.php', 1, 'e8909c8fa47290bfd6ff5db05ddc95cfc8b8d8c6c6b9b4867868fbf4d63df296', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/account.php:287|check|if (getDolGlobalInt(''ACCOUNTING_LENGTH_GACCOUNT'') || getDolGlobalInt(''ACCOUNTING_LENGTH_AACCOUNT'')) {", "accountancy/admin/account.php:288|read|$lengthpaddingaccount = max(getDolGlobalInt(''ACCOUNTING_LENGTH_GACCOUNT''), getDolGlobalInt(''ACCOUNTING_LENGTH_AACCOUNT''));", "core/lib/accounting.lib.php:162|read|$g = getDolGlobalInt(''ACCOUNTING_LENGTH_GACCOUNT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LETTERING_NBLETTERS', 'string', NULL, 'accountancy', 'Sets the number of characters (n) used to build the lettering code string, default 3.', 'Set from accountancy/admin/index.php:239 (type ''chaine''), read at admin/index.php:892-893 and accountancy/class/lettering.class.php:309,533 with default 3. Comment: ''Generate a string with n char A (for manual/auto reconcile) or a (for partial reconcile) where n is ACCOUNTING_LETTERING_NBLETTERS (So AA/aa, AAA/aaa, ...)''.', 'Changing the value changes the length of the generated lettering code string (e.g. ''AA''/''aa'' for n=2, ''AAA''/''aaa'' for n=3).', 'String length n; ''A'' repeated for manual/auto reconcile, ''a'' repeated for partial reconcile (e.g. ''AA''/''aa'', ''AAA''/''aaa'', ...). Default 3.', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php|accountancy/admin/index.php', 1, 'e17371b0fab2dc47ae97699cc54198592431a848bd8760bd4808a69fad6a1dfd', 'v2', '2026-07-24T06:41:12+00:00', '["// Generate a string with n char ''A'' (for manual/auto reconcile) or ''a'' (for partial reconcile) where n is ACCOUNTING_LETTERING_NBLETTERS (So ''AA''/''aa'', ''AAA''/''aaa'', ...)", "$letter = str_pad(\"\", getDolGlobalInt(''ACCOUNTING_LETTERING_NBLETTERS'', 3), $partial ? ''a'' : ''A'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LIMIT_LIST_VENTILATION', 'string', NULL, 'accountancy', 'Overrides the default page-size limit for accounting ventilation and bookkeeping list pages.', 'Configured via accountancy/admin/productaccount.php:95 (read into $limit). Read in 10 locations including accountancy/customer/lines.php:78, expensereport/lines.php:71, customer/list.php:90, expensereport/list.php:82, bookkeeping/export.php:145, bookkeeping/listbyaccount.php:143, and bookkeeping/list.php:134, all falling back to $conf->liste_limit.', 'Setting this constant changes the number of rows displayed per page on accounting ventilation and bookkeeping list screens.', 'Integer page-size limit; unset = use the global $conf->liste_limit default', 0, 0, 'accountancy/admin/productaccount.php', 1, '944c267c96a434e213f2afab31953ee77964870f2ee836393009796b292be43f', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:95|read|$limit = GETPOSTINT(''limit'') ? GETPOSTINT(''limit'') : getDolGlobalInt(''ACCOUNTING_LIMIT_LIST_VENTILATION'', $conf->liste_limit);", "accountancy/customer/lines.php:78|read|$limit = GETPOSTINT(''limit'') ? GETPOSTINT(''limit'') : getDolGlobalString(''ACCOUNTING_LIMIT_LIST_VENTILATION'', $conf->liste_limit);", "accountancy/bookkeeping/list.php:134|read|$limit = GETPOSTINT(''limit'') ? GETPOSTINT(''limit'') : getDolGlobalString(''ACCOUNTING_LIMIT_LIST_VENTILATION'', $conf->liste_limit);", "accountancy/bookkeeping/export.php:145|read|$limit = GETPOSTINT(''limit'') ? GETPOSTINT(''limit'') : getDolGlobalString(''ACCOUNTING_LIMIT_LIST_VENTILATION'', $conf->liste_limit);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LIST_SORT_VENTILATION_DONE', 'string', NULL, 'accountancy', 'When set to a positive integer, sorts already-ventilated lines to the bottom on accounting line-binding pages.', 'Checked in accountancy/customer/lines.php:92, expensereport/lines.php:85, and supplier/lines.php:93. Written via dolibarr_set_const at customer/lines.php:208, supplier/lines.php:212, and expensereport/lines.php:201 with type ''yesno''.', 'Setting this to a positive integer causes ventilated (already-assigned) accounting lines to be sorted after unventilated lines on binding pages.', 'Positive integer = sort ventilated lines to bottom; 0 or unset = default sort order', 1, 0, NULL, 1, 'e8817f73ec7cdc26f0e510508944cf11a722f887d7421918765135debaeb5ac1', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/customer/lines.php:92|check|if (getDolGlobalInt(''ACCOUNTING_LIST_SORT_VENTILATION_DONE'') > 0) {", "accountancy/customer/lines.php:208|write|$res = dolibarr_set_const($db, \"ACCOUNTING_LIST_SORT_VENTILATION_DONE\", $value, ''yesno'', 0, '''', $conf->entity);", "accountancy/expensereport/lines.php:85|check|if (getDolGlobalInt(''ACCOUNTING_LIST_SORT_VENTILATION_DONE'') > 0) {", "accountancy/supplier/lines.php:93|check|if (getDolGlobalInt(''ACCOUNTING_LIST_SORT_VENTILATION_DONE'') > 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LIST_SORT_VENTILATION_TODO', 'string', NULL, 'accountancy', 'Controls whether accounting allocation lists are sorted to show unallocated (todo) items first.', 'Written and read in accountancy/customer/list.php, accountancy/supplier/list.php, and accountancy/expensereport/list.php. When value > 0 (checked at lines :104, :96, :100 respectively), sorting is applied to prioritize pending ventilation items. Stored as ''yesno'' type.', 'Enabling this constant changes the default sort order in accounting allocation lists to surface unallocated entries at the top.', '0 or unset = normal sort order; >0 = sort to show unallocated items first', 1, 0, NULL, 1, '28c28c6f7466b7d4ba9df10a14ab7831161ce4666db9b5ef7446c4dfee991871', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/customer/list.php:104|check|if (getDolGlobalInt(''ACCOUNTING_LIST_SORT_VENTILATION_TODO'') > 0) {", "accountancy/supplier/list.php:253|write|$res = dolibarr_set_const($db, \"ACCOUNTING_LIST_SORT_VENTILATION_TODO\", $value, ''yesno'', 0, '''', $conf->entity);", "accountancy/expensereport/list.php:96|check|if (getDolGlobalInt(''ACCOUNTING_LIST_SORT_VENTILATION_TODO'') > 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LT1_BUY_ACCOUNT', 'string', NULL, 'accountancy', 'Accounting account code used for local tax 1 (LT1) on purchases when no per-line account is defined.', 'Read in accountancy/journal/purchasesjournal.php:229 (`$cptlocaltax1 = getDolGlobalString(''ACCOUNTING_LT1_BUY_ACCOUNT'', ''NotDefined'')`) as a fallback used to build the purchases journal. Editable via accountancy/admin/defaultaccounts.php:107 ($list_account[] = ''ACCOUNTING_LT1_BUY_ACCOUNT''), always shown (not conditional on reverse charge).', 'Sets which accounting account receives local tax 1 amounts on supplier invoice lines that do not carry their own accounting_code_buy; affects the generated purchases journal entries.', 'Free-text accounting account number string; falls back to literal ''NotDefined'' if unset.', 0, 0, NULL, 1, '81eccfb789ef52ef0ebd6fc856f3553beb2fb38130b0f498ff97e3ee633edb58', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:229|read|$cptlocaltax1 = getDolGlobalString(''ACCOUNTING_LT1_BUY_ACCOUNT'', ''NotDefined'');", "accountancy/admin/defaultaccounts.php:107: $list_account[] = ''ACCOUNTING_LT1_BUY_ACCOUNT'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LT1_BUY_REVERSE_CHARGES_CREDIT', 'string', NULL, 'accountancy', 'Accounting account code used as the credit counterpart for local tax 1 (LT1) reverse charge on purchases.', 'Read in accountancy/journal/purchasesjournal.php:230 (`$rcclocaltax1 = getDolGlobalString(''ACCOUNTING_LT1_BUY_REVERSE_CHARGES_CREDIT'', ''NotDefined'')`) and used as fallback in the reverse-charge block (~line 321-330). Editable via accountancy/admin/defaultaccounts.php:116, shown only when ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE is enabled.', 'Determines which accounting account is credited for local tax 1 reverse charge on purchase invoices lacking a per-VAT-rate reverse-charge account.', 'Free-text accounting account number string; falls back to literal ''NotDefined'' if unset.', 0, 0, NULL, 1, '7d0ffc9eedf3aa885ff80e806f1a5f970286b711de53b572d3f79e1653ee7e17', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:230|read|$rcclocaltax1 = getDolGlobalString(''ACCOUNTING_LT1_BUY_REVERSE_CHARGES_CREDIT'', ''NotDefined'');", "accountancy/admin/defaultaccounts.php:116: $list_account[] = ''ACCOUNTING_LT1_BUY_REVERSE_CHARGES_CREDIT'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LT1_BUY_REVERSE_CHARGES_DEBIT', 'string', NULL, 'accountancy', 'Accounting account code used as the debit counterpart for local tax 1 (LT1) reverse charge on purchases.', 'Read in accountancy/journal/purchasesjournal.php:231 (`$rcdlocaltax1 = getDolGlobalString(''ACCOUNTING_LT1_BUY_REVERSE_CHARGES_DEBIT'', ''NotDefined'')`) and used as fallback in the reverse-charge block. Editable via accountancy/admin/defaultaccounts.php:117, shown only when ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE is enabled.', 'Determines which accounting account is debited for local tax 1 reverse charge on purchase invoices lacking a per-VAT-rate reverse-charge account.', 'Free-text accounting account number string; falls back to literal ''NotDefined'' if unset.', 0, 0, NULL, 1, '2dec7156bf8a82a100eb495a4c610a51a14c42efb95826527531dad0334da0f6', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:231|read|$rcdlocaltax1 = getDolGlobalString(''ACCOUNTING_LT1_BUY_REVERSE_CHARGES_DEBIT'', ''NotDefined'');", "accountancy/admin/defaultaccounts.php:117: $list_account[] = ''ACCOUNTING_LT1_BUY_REVERSE_CHARGES_DEBIT'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LT1_SOLD_ACCOUNT', 'string', NULL, 'accountancy', 'Defines the accounting account used for local tax 1 (LT1) on sales.', 'Read in accountancy/journal/cashsellsjournal.php:230 and journal/sellsjournal.php:229, both falling back to ''NotDefined'' when unset.', 'Changing it changes which accounting account local-tax-1 amounts are booked to in the cash-sells and sells journals.', 'Falls back to ''NotDefined'' when unset.', 0, 0, NULL, 1, '4ea931108fe59f4f181cae947bd4db7898fea83e198b7f3fdb9c23d7519a394a', 'v2', '2026-07-24T06:41:12+00:00', '["$cptlocaltax1 = getDolGlobalString(''ACCOUNTING_LT1_SOLD_ACCOUNT'', ''NotDefined'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LT2_BUY_ACCOUNT', 'string', NULL, 'accountancy', 'Accounting account code used for local tax 2 (LT2) on purchases when no per-line account is defined.', 'Read in accountancy/journal/purchasesjournal.php:232 (`$cptlocaltax2 = getDolGlobalString(''ACCOUNTING_LT2_BUY_ACCOUNT'', ''NotDefined'')`) as a fallback used to build the purchases journal. Editable via accountancy/admin/defaultaccounts.php:110 ($list_account[] = ''ACCOUNTING_LT2_BUY_ACCOUNT''), always shown.', 'Sets which accounting account receives local tax 2 amounts on supplier invoice lines that do not carry their own accounting_code_buy; affects the generated purchases journal entries.', 'Free-text accounting account number string; falls back to literal ''NotDefined'' if unset.', 0, 0, NULL, 1, '9ee7ad2195a34bbe92970620032702883cfb11f255e684d6cd0ce880bf21b888', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:232|read|$cptlocaltax2 = getDolGlobalString(''ACCOUNTING_LT2_BUY_ACCOUNT'', ''NotDefined'');", "accountancy/admin/defaultaccounts.php:110: $list_account[] = ''ACCOUNTING_LT2_BUY_ACCOUNT'';"]', 'medium', NULL);
