INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LT2_BUY_REVERSE_CHARGES_DEBIT', 'string', NULL, 'accountancy', 'Accounting account code used as the debit counterpart for local tax 2 (LT2) reverse charge on purchases.', 'Read in accountancy/journal/purchasesjournal.php:234 (`$rcdlocaltax2 = getDolGlobalString(''ACCOUNTING_LT2_BUY_REVERSE_CHARGES_DEBIT'', ''NotDefined'')`) and used as fallback in the reverse-charge block. Editable via accountancy/admin/defaultaccounts.php:119, shown only when ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE is enabled.', 'Determines which accounting account is debited for local tax 2 reverse charge on purchase invoices lacking a per-VAT-rate reverse-charge account.', 'Free-text accounting account number string; falls back to literal ''NotDefined'' if unset.', 0, 0, NULL, 1, 'c4a07e5c0fb87701a66f03afb00d1a5dce08ece9d1175924c1d98d58ea50e397', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:234|read|$rcdlocaltax2 = getDolGlobalString(''ACCOUNTING_LT2_BUY_REVERSE_CHARGES_DEBIT'', ''NotDefined'');", "accountancy/admin/defaultaccounts.php:119: $list_account[] = ''ACCOUNTING_LT2_BUY_REVERSE_CHARGES_DEBIT'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_LT2_SOLD_ACCOUNT', 'string', NULL, 'accountancy', 'Defines the accounting account used for local tax 2 (LT2) on sales.', 'Read in accountancy/journal/cashsellsjournal.php:231 and journal/sellsjournal.php:230, both falling back to ''NotDefined'' when unset.', 'Changing it changes which accounting account local-tax-2 amounts are booked to in the cash-sells and sells journals.', 'Falls back to ''NotDefined'' when unset.', 0, 0, NULL, 1, 'c44227619da7578a3112970ba8daa984cbe71838b0773d2071b722864439a951', 'v2', '2026-07-24T06:41:12+00:00', '["$cptlocaltax2 = getDolGlobalString(''ACCOUNTING_LT2_SOLD_ACCOUNT'', ''NotDefined'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_MANAGE_ZERO', 'string', NULL, 'accountancy', 'Controls whether trailing zeros in accounting account codes are treated as significant.', 'Checked in accountancy/admin/card.php:98,155, admin/index.php:93, product/class/product.class.php:1066,1515, core/lib/accounting.lib.php:158,196, and core/modules/import/modules_import.class.php:1369. Comment: ''When ACCOUNTING_MANAGE_ZERO is on, trailing zeros are part of the code and must be kept.''', 'Enabling it makes trailing zeros part of the accounting account code and preserves them (e.g. in product.class.php account-code handling); disabling it does not keep them.', NULL, 0, 0, 'accountancy/admin/index.php|accountancy/admin/card.php|accountancy/admin/card.php', 1, '3f3f8ce369c565140fe2157336347a6dcee9aba881b0a3749fbe7b4bc890f02f', 'v2', '2026-07-24T06:41:12+00:00', '["// When ACCOUNTING_MANAGE_ZERO is on, trailing zeros are part of the code and must be kept.", "if (!getDolGlobalString(''ACCOUNTING_MANAGE_ZERO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_MODE', 'string', NULL, 'compta', 'Selects the accounting mode used for financial result calculations (''CREANCES-DETTES'' for accrual or ''RECETTES-DEPENSES'' for cash basis).', 'Configured in admin/compta.php:86 and accountancy/admin/index.php:185. Read by all financial result pages including compta/resultat/projects.php:147, result.php:162, index.php:124, and clientfourn.php:149 with default ''CREANCES-DETTES''. Comments at admin/compta.php:157 and accountancy/admin/index.php:500 describe handling of this parameter.', 'Switching from ''CREANCES-DETTES'' (accrual) to ''RECETTES-DEPENSES'' (cash) changes how all income/expense result reports are computed.', '''CREANCES-DETTES'' = accrual accounting (default); ''RECETTES-DEPENSES'' = cash-basis accounting', 0, 0, 'accountancy/admin/index.php|admin/compta.php|accountancy/admin/index.php|admin/compta.php', 1, '68b5d73836d982acb7b95ff292ca5e870db7dc15ca82b3eebc892b1ff5b763db', 'v2', '2026-04-21T11:16:15+00:00', '["admin/compta.php:72|read|$accounting_mode = getDolGlobalString(''ACCOUNTING_MODE'', ''CREANCES-DETTES'');", "admin/compta.php:157  // case of the parameter ACCOUNTING_MODE", "accountancy/admin/index.php:500  // Case of the parameter ACCOUNTING_MODE", "compta/resultat/projects.php:147|read|$modecompta = getDolGlobalString(''ACCOUNTING_MODE'', ''CREANCES-DETTES'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PRODUCT_', 'string', NULL, 'accountancy', 'Family of dynamic constants (ACCOUNTING_PRODUCT_{TYPE}_ACCOUNT, _INTRA_ACCOUNT, _EXPORT_ACCOUNT) that provide accounting account codes for physical product types.', 'Accessed dynamically in accountancy/class/accountingaccount.class.php:796, :800, :803, :806, and :809 by appending a computed suffix (_ACCOUNT, _INTRA_ACCOUNT, _EXPORT_ACCOUNT) to the base prefix ''ACCOUNTING_PRODUCT_''. No admin UI is configured.', 'Setting these constants assigns specific accounting accounts for physical product lines in standard, intra-community, and export sale contexts.', 'Chart-of-accounts code string for each variant; variants are ACCOUNTING_PRODUCT_{TYPE}_ACCOUNT, ACCOUNTING_PRODUCT_{TYPE}_INTRA_ACCOUNT, ACCOUNTING_PRODUCT_{TYPE}_EXPORT_ACCOUNT.', 1, 0, NULL, 1, '67be7acc9ed5eb96dc7c80357605c9b81013072cfb3f0508b4408e45ea880cda', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/accountingaccount.class.php:796|read|$code_l = getDolGlobalString(''ACCOUNTING_PRODUCT_'' . $const_name . ''_ACCOUNT'');", "accountancy/class/accountingaccount.class.php:806|read|$code_l = getDolGlobalString(''ACCOUNTING_PRODUCT_'' . $const_name . ''_INTRA_ACCOUNT'');", "accountancy/class/accountingaccount.class.php:809|read|$code_l = getDolGlobalString(''ACCOUNTING_PRODUCT_'' . $const_name . ''_EXPORT_ACCOUNT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PRODUCT_BUY_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for product (goods) purchases when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:307 and accountancy/journal/purchasesjournal.php:253 as the fallback purchase account for goods. Also used in product/card.php:1931 as the default. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the default ledger account assigned to goods purchase lines in the purchases journal when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, 'fbe11b784cf552cce2d921f5b780c1966e11d2a7c80416af665cc744698f811c', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/purchasesjournal.php:253|read|$compta_prod = getDolGlobalString(''ACCOUNTING_PRODUCT_BUY_ACCOUNT'', ''NotDefined'');", "accountancy/admin/productaccount.php:307|read|$aacompta_prodbuy           = getDolGlobalString(''ACCOUNTING_PRODUCT_BUY_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1931|read|$accountancy_code_buy = (GETPOST(''accountancy_code_buy'', ''alpha'') ? (GETPOST(''accountancy_code_buy'', ''alpha'')) : getDolGlobalString(\"ACCOUNTING_PRODUCT_BUY_ACCOUNT\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PRODUCT_BUY_EXPORT_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for export product (goods) purchases when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:309 and productaccount.php:717 as the fallback export purchase account for goods. Also used in product/card.php:1955. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the ledger account used for export goods purchase lines when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, '4526818e5606fa3812ba0bd4ec86131f5bca1cc76e8577e2b232e31270a187c5', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:309|read|$aacompta_prodbuy_export    = getDolGlobalString(''ACCOUNTING_PRODUCT_BUY_EXPORT_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "accountancy/admin/productaccount.php:717|read|$compta_prodbuy = getDolGlobalString(''ACCOUNTING_PRODUCT_BUY_EXPORT_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1955|read|$accountancy_code_buy_export = (GETPOST(''accountancy_code_buy_export'') ? GETPOST(''accountancy_code_buy_export'', ''alpha'') : getDolGlobalString(\"ACCOUNTING_PRODUCT_BUY_EXPORT_ACCOUNT"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PRODUCT_BUY_INTRA_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for intra-community product (goods) purchases when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:308 and productaccount.php:714 as the fallback intra-community purchase account for goods. Also used in product/card.php:1943. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the ledger account used for intra-EU goods purchase lines when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, '7143a083972b55e47bebdc34537c092512d09823a9460fd1391ac81df68de2da', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:308|read|$aacompta_prodbuy_intra     = getDolGlobalString(''ACCOUNTING_PRODUCT_BUY_INTRA_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "accountancy/admin/productaccount.php:714|read|$compta_prodbuy = getDolGlobalString(''ACCOUNTING_PRODUCT_BUY_INTRA_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1943|read|$accountancy_code_buy_intra = (GETPOSTISSET(''accountancy_code_buy_intra'') ? GETPOST(''accountancy_code_buy_intra'', ''alpha'') : getDolGlobalString(\"ACCOUNTING_PRODUCT_BUY_INTRA_ACCOUN"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PRODUCT_MODE', 'string', NULL, 'accountancy', 'Configures the mode used to determine per-product accounting codes in the Accountancy module.', 'Written from accountancy/admin/productaccount.php:192 via dolibarr_set_const() when the admin saves the product accounting configuration page.', 'Changing it switches how product accounting codes are computed/assigned in the accountancy product setup; exact modes are not shown in the payload.', 'Not specified in the available evidence (a mode selector value submitted from the admin form as $accounting_product_mode).', 0, 0, 'accountancy/admin/productaccount.php', 1, '73203076900902de7b25da26e43548f6dc82f4f59b06541705a9ccd1bfce9389', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/admin/productaccount.php:192|write|if (!dolibarr_set_const($db, ''ACCOUNTING_PRODUCT_MODE'', $accounting_product_mode, ''chaine'', 0, '''', $conf->entity)) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PRODUCT_SOLD_ACCOUNT', 'string', NULL, 'accountancy', 'Defines the default accounting account used for sold products.', 'Read across 8 occurrences in accountancy/admin/productaccount.php:678,300,313,687, compta/journal/sellsjournal.php:188, product/card.php:1897, journal/cashsellsjournal.php:248, journal/sellsjournal.php:247. Comment: ''at this time ACCOUNTING_SERVICE_SOLD_ACCOUNT & ACCOUNTING_PRODUCT_SOLD_ACCOUNT are account number not accountingacount rowid''.', 'Changing it changes the account number (not the accountingaccount table rowid, per the code comment) used as the default sold-product accounting account in journals and the product card.', 'Stores an account number (not an accountingaccount rowid), per the code comment.', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, '76156ceddf19782a64c5d6a2c2875e9ec4c09070077d14c13d5af9e893495981', 'v2', '2026-07-24T06:41:12+00:00', '["// at this time ACCOUNTING_SERVICE_SOLD_ACCOUNT & ACCOUNTING_PRODUCT_SOLD_ACCOUNT are account number not accountingacount rowid", "$compta_prodsell = getDolGlobalString(''ACCOUNTING_PRODUCT_SOLD_ACCOUNT'', $langs->trans(\"CodeNotDef\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PRODUCT_SOLD_EXPORT_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for export product (goods) sales when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:315 and productaccount.php:685 as the fallback export sales account for goods. Also used in product/card.php:1920. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the ledger account used for export goods sales lines when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, '14c9d7d5f9bd2e305df2358fda9a069a8bf9a51f53d1e9d4d974cd78e69ce549', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:315|read|$aacompta_prodsell_export   = getDolGlobalString(''ACCOUNTING_PRODUCT_SOLD_EXPORT_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "accountancy/admin/productaccount.php:685|read|$compta_prodsell = getDolGlobalString(''ACCOUNTING_PRODUCT_SOLD_EXPORT_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1920|read|$accountancy_code_sell_export = (GETPOST(''accountancy_code_sell_export'') ? GETPOST(''accountancy_code_sell_export'', ''alpha'') : getDolGlobalString(\"ACCOUNTING_PRODUCT_SOLD_EXPORT_ACC"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PRODUCT_SOLD_INTRA_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for intra-community product (goods) sales when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:314 and productaccount.php:682 as the fallback intra-community sales account for goods. Also used in product/card.php:1908. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the ledger account used for intra-EU goods sales lines when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, '2fc9cff943c31f05fb6b19ef6633fd019ed1b371a56bb2b4e37c0e49536527a0', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:314|read|$aacompta_prodsell_intra    = getDolGlobalString(''ACCOUNTING_PRODUCT_SOLD_INTRA_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "accountancy/admin/productaccount.php:682|read|$compta_prodsell = getDolGlobalString(''ACCOUNTING_PRODUCT_SOLD_INTRA_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1908|read|$accountancy_code_sell_intra = (GETPOSTISSET(''accountancy_code_sell_intra'') ? GETPOST(''accountancy_code_sell_intra'', ''alpha'') : getDolGlobalString(\"ACCOUNTING_PRODUCT_SOLD_INTRA_AC"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_PURCHASES_DO_NOT_DISPATCH_TAXES', 'string', NULL, 'accountancy', 'When enabled, prevents tax amounts from being split off from the base entry into a separate tax account in the purchases journal.', 'Read in accountancy/journal/purchasesjournal.php:235: `$noTaxDispatchingKeepWithLines = getDolGlobalInt(''ACCOUNTING_PURCHASES_DO_NOT_DISPATCH_TAXES'')`, with an inline comment explaining the effect.', 'If enabled, tax will NOT get split off from the base entry and credited to a separate tax account (useful for non-VAT countries like USA), changing how purchase journal lines are generated.', 'If enabled, Tax will NOT get split off from the base entry and credited to a separate tax account (good for non-VAT countries like USA)', 0, 0, NULL, 1, 'e92b21cc662085c8b6f39dede4297e992c6493384fb506b82d09265b92638099', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:235|read|$noTaxDispatchingKeepWithLines = getDolGlobalInt(''ACCOUNTING_PURCHASES_DO_NOT_DISPATCH_TAXES''); //If enabled, Tax will NOT get split off from the base entry and credited to a separ"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_REEXPORT', 'string', NULL, 'accountancy', 'Enables re-exporting bookkeeping movements that were already exported/validated.', 'Set from accountancy/bookkeeping/export.php:482 (type ''yesno''); checked at export.php:487,600,683,686,945,963 and used in a fetchAll filter at export.php:643. Comment: ''Reexport not enabled (default mode)''.', 'Enabling it allows movements to be re-exported even if already exported/validated (export.php:683,686 check it alongside date_export/date_validation); default mode is disabled per the code comment.', '''yesno'' type (0/1); default mode is disabled (''Reexport not enabled (default mode)'').', 0, 0, NULL, 1, '534b17a804bddc6e3153ad05dab4753c4c35e7ba06162107f7e49f5d2e26f3b6', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''ACCOUNTING_REEXPORT'')) {\t// Reexport not enabled (default mode)", "if (!dolibarr_set_const($db, \"ACCOUNTING_REEXPORT\", $setreexport, ''yesno'', 0, '''', $conf->entity)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_REPORTS_INCLUDE_LOAN', 'string', NULL, 'compta', 'When enabled, includes loan data in accounting result reports when the loan module is active.', 'Configured via admin/compta.php (yes/no selector at line 203, saved at lines 118 and 124). Checked in compta/resultat/projects.php:946, index.php:887, and clientfourn.php:1238, conditioned additionally on isModEnabled(''loan'') or isModEnabled(''don'') and accounting mode.', 'Enabling this constant causes loan entries to appear in result and balance reports; disabling it hides them.', '1 = include loan lines in reports; empty/0 = exclude (default)', 0, 0, 'admin/compta.php|admin/compta.php|admin/compta.php', 1, '97baf1c86c7a796db76384fa66ce72de29b7091e5091d6e118bcb97a2bd33e36', 'v2', '2026-04-21T11:16:15+00:00', '["admin/compta.php:203|read|print $form->selectyesno(''ACCOUNTING_REPORTS_INCLUDE_LOAN'', (getDolGlobalString(''ACCOUNTING_REPORTS_INCLUDE_LOAN'')));", "compta/resultat/index.php:887|check|if (getDolGlobalString(''ACCOUNTING_REPORTS_INCLUDE_LOAN'') && isModEnabled(''loan'') && ($modecompta == ''CREANCES-DETTES'' || $modecompta == \"RECETTES-DEPENSES\")) {", "compta/resultat/projects.php:946|check|if (getDolGlobalString(''ACCOUNTING_REPORTS_INCLUDE_LOAN'') && isModEnabled(''don'')) {", "compta/resultat/clientfourn.php:1238|check|if (getDolGlobalString(''ACCOUNTING_REPORTS_INCLUDE_LOAN'') && isModEnabled(''don'') && ($modecompta == ''CREANCES-DETTES'' || $modecompta == \"RECETTES-DEPENSES\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_REPORTS_INCLUDE_VARPAY', 'string', NULL, 'compta', 'When enabled, includes bank variable payment lines in accounting result reports.', 'Configured via admin/compta.php (yes/no selector at line 196, saved at lines 104 and 110). Checked in compta/resultat/projects.php:854, index.php:816, and clientfourn.php:1159, all conditioned additionally on isModEnabled(''bank'') and accounting mode.', 'Enabling this constant adds bank payment variation lines to the balance/result reports; disabling it excludes those lines.', '1 = include variable payment lines in reports; empty/0 = exclude (default)', 0, 0, 'admin/compta.php|admin/compta.php|admin/compta.php', 1, '218d3cb79528568337b7aa2ad5e737b907cb43c48cc89bc5ae22d493a024656d', 'v2', '2026-04-21T11:16:15+00:00', '["admin/compta.php:196|read|print $form->selectyesno(''ACCOUNTING_REPORTS_INCLUDE_VARPAY'', (getDolGlobalString(''ACCOUNTING_REPORTS_INCLUDE_VARPAY'')));", "compta/resultat/index.php:816|check|if (getDolGlobalString(''ACCOUNTING_REPORTS_INCLUDE_VARPAY'') && isModEnabled(\"bank\") && ($modecompta == ''CREANCES-DETTES'' || $modecompta == \"RECETTES-DEPENSES\")) {", "compta/resultat/projects.php:853  //$conf->global->ACCOUNTING_REPORTS_INCLUDE_VARPAY = 1;", "compta/resultat/clientfourn.php:1157  //$conf->global->ACCOUNTING_REPORTS_INCLUDE_VARPAY = 1;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_RESULT_LOSS', 'string', NULL, 'accountancy', 'Accounting account number configured as the ''Loss'' result account, used to bypass the bookkeeping duplicate-line check.', 'Read in Bookkeeping::create() at accountancy/class/bookkeeping.class.php:357, compared against the current line''s numero_compte alongside ACCOUNTING_RESULT_PROFIT to decide whether to skip the uniqueness check.', 'When the account being written matches this constant''s value, the code intentionally allows duplicate bookkeeping lines for that account instead of blocking them via the normal existence check.', 'Any accounting account number string; empty/unset disables the bypass for the loss account.', 1, 0, NULL, 1, '53cc315a38a7f38665461f18eb019a3907a3b51b5922ad908ebf10fd7135bc07', 'v2', '2026-07-24T07:05:23+00:00', '["bookkeeping.class.php:357: $accountLoss   = getDolGlobalString(''ACCOUNTING_RESULT_LOSS'');", "bookkeeping.class.php: // Allow duplicates in incomes or loss statements", "bookkeeping.class.php: // If the account being processed corresponds to the “Profit” or “Loss” constant, the detection is bypassed"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_RESULT_PROFIT', 'string', NULL, 'accountancy', 'Accounting account number configured as the ''Profit'' result account, used to bypass the bookkeeping duplicate-line check.', 'Read in Bookkeeping::create() at accountancy/class/bookkeeping.class.php:356, compared against the current line''s numero_compte to decide whether to skip the uniqueness check.', 'When the account being written matches this constant''s value, the code intentionally allows duplicate bookkeeping lines for that account (adds ''AND 1 = 2'' to the pre-insert existence check) instead of blocking them.', 'Any accounting account number string; empty/unset disables the bypass for the profit account.', 1, 0, NULL, 1, '0df9cc3bed8ee2e3aa0ae59e439a34f8726f2c2eec9cce7b8779ef79ad08f907', 'v2', '2026-07-24T07:05:23+00:00', '["bookkeeping.class.php:356: $accountProfit = getDolGlobalString(''ACCOUNTING_RESULT_PROFIT'');", "bookkeeping.class.php: // Allow duplicates in incomes or loss statements", "bookkeeping.class.php: // If the account being processed corresponds to the “Profit” or “Loss” constant, the detection is bypassed"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_REVENUESTAMP_SOLD_ACCOUNT', 'string', NULL, 'accountancy', 'Accounting account code intended for revenue stamp sales, currently unused: both its read sites are commented out.', 'The only two occurrences, accountancy/journal/sellsjournal.php:253 and accountancy/journal/cashsellsjournal.php:254, are commented-out lines: `// $compta_revenuestamp = getDolGlobalString(''ACCOUNTING_REVENUESTAMP_SOLD_ACCOUNT'', ''NotDefined'');`. The related admin list entry in accountancy/admin/defaultaccounts.php is also wrapped in a /* ... */ comment block gated on $mysoc->useRevenueStamp().', 'Setting this constant currently has no effect since the code paths that would read it are commented out in both journals and its admin field entry is also disabled.', 'Free-text accounting account number string; would default to ''NotDefined'' if the commented code were active.', 1, 0, NULL, 1, '0b12ee9fe9015a2175921dc3ddc39fb0ae0d7e13c3acaa40ec3161a34f05692f', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/sellsjournal.php:253  // $compta_revenuestamp = getDolGlobalString(''ACCOUNTING_REVENUESTAMP_SOLD_ACCOUNT'', ''NotDefined'');", "accountancy/journal/cashsellsjournal.php:254  // $compta_revenuestamp = getDolGlobalString(''ACCOUNTING_REVENUESTAMP_SOLD_ACCOUNT'', ''NotDefined'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_REVERSE_CHARGE_ALSO_NON_EEC', 'string', NULL, 'accountancy', 'When enabled, applies VAT reverse-charge accounting treatment to purchase invoice lines even for suppliers outside the EEC.', 'Checked in accountancy/journal/purchasesjournal.php:321 as part of the condition that decides whether a purchase line is treated as VAT reverse charge: `... && (in_array($obj->country_code, $country_code_in_EEC) || getDolGlobalString(''ACCOUNTING_REVERSE_CHARGE_ALSO_NON_EEC''))`.', 'Extends reverse-charge posting logic (normally restricted to EEC countries) to non-EEC supplier countries when the line is flagged vat_reverse_charge=1 and the reverse-charge feature is force-enabled.', 'Boolean-like: truthy value widens the EEC country check to also match non-EEC countries in the reverse-charge condition.', 0, 0, NULL, 1, 'b74dfa0b882c4786713dff93401d7a09dfd810108b72e18037da56e640e6d830', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:321|check|if (($mysoc->country_code == ''FR'' || getDolGlobalString(''ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE'')) && $obj->vat_reverse_charge == 1 && (in_array($obj->country_code, $country_co"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_SERVICE_', 'string', NULL, 'accountancy', 'Family of dynamic constants (ACCOUNTING_SERVICE_{TYPE}_ACCOUNT, _INTRA_ACCOUNT, _EXPORT_ACCOUNT) that provide accounting account codes for service product types.', 'Accessed dynamically in accountancy/class/accountingaccount.class.php:778, :782, :784, :787, and :790 by appending a computed suffix (_ACCOUNT, _INTRA_ACCOUNT, _EXPORT_ACCOUNT) to the base prefix ''ACCOUNTING_SERVICE_''. No admin UI is configured.', 'Setting these constants assigns specific accounting accounts for service product lines in standard, intra-community, and export sale contexts.', 'Chart-of-accounts code string for each variant; variants are ACCOUNTING_SERVICE_{TYPE}_ACCOUNT, ACCOUNTING_SERVICE_{TYPE}_INTRA_ACCOUNT, ACCOUNTING_SERVICE_{TYPE}_EXPORT_ACCOUNT.', 1, 0, NULL, 1, 'd9a3a88e95db2b5d951036cb14862e154d9326adc682bafb1b444387dd90702d', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/accountingaccount.class.php:778|read|$code_l = getDolGlobalString(''ACCOUNTING_SERVICE_'' . $const_name . ''_ACCOUNT'');", "accountancy/class/accountingaccount.class.php:787|read|$code_l = getDolGlobalString(''ACCOUNTING_SERVICE_'' . $const_name . ''_INTRA_ACCOUNT'');", "accountancy/class/accountingaccount.class.php:790|read|$code_l = getDolGlobalString(''ACCOUNTING_SERVICE_'' . $const_name . ''_EXPORT_ACCOUNT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_SERVICE_BUY_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code used for service purchases when no per-product code is set.', 'Read in accountancy/admin/productaccount.php and accountancy/journal/purchasesjournal.php:255 as the fallback purchase account for services. Also used in product/card.php:1933 as the default when no explicit buy account is entered. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the default ledger account assigned to service purchase lines in the purchases journal for products without a specific account override.', 'Accounting account code string (e.g. chart-of-accounts number); fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, 'f40fd6474db15da40c39f3f067561c5cb43fcc581bea154c94781a7d3be5b37b', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/purchasesjournal.php:255|read|$compta_prod = getDolGlobalString(''ACCOUNTING_SERVICE_BUY_ACCOUNT'', ''NotDefined'');", "accountancy/admin/productaccount.php:304|read|$aacompta_servbuy           = getDolGlobalString(''ACCOUNTING_SERVICE_BUY_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1933|read|$accountancy_code_buy = (GETPOST(''accountancy_code_buy'', ''alpha'') ? (GETPOST(''accountancy_code_buy'', ''alpha'')) : getDolGlobalString(\"ACCOUNTING_SERVICE_BUY_ACCOUNT\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_SERVICE_BUY_EXPORT_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for export service purchases when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:306 and productaccount.php:731 as the fallback export purchase account for services. Also used in product/card.php:1957 as the default. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the ledger account used for export service purchase lines when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, '3d4f9ebef96c389dbcb2b23ca009238605061872c2d325965fc5265c80b10c16', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:306|read|$aacompta_servbuy_export    = getDolGlobalString(''ACCOUNTING_SERVICE_BUY_EXPORT_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "accountancy/admin/productaccount.php:731|read|$compta_prodbuy = getDolGlobalString(''ACCOUNTING_SERVICE_BUY_EXPORT_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1957|read|$accountancy_code_buy_export = (GETPOST(''accountancy_code_buy_export'') ? GETPOST(''accountancy_code_buy_export'', ''alpha'') : getDolGlobalString(\"ACCOUNTING_SERVICE_BUY_EXPORT_ACCOUNT"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_SERVICE_BUY_INTRA_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for intra-community service purchases when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:305 and productaccount.php:728 as the fallback intra-community purchase account for services. Also used in product/card.php:1945 as the default. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the ledger account used for intra-EU service purchase lines when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, 'f536dee72566ef57e7d827d57d667b8a4774539d75c4e70efdfcfd6edd341c04', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:305|read|$aacompta_servbuy_intra     = getDolGlobalString(''ACCOUNTING_SERVICE_BUY_INTRA_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "accountancy/admin/productaccount.php:728|read|$compta_prodbuy = getDolGlobalString(''ACCOUNTING_SERVICE_BUY_INTRA_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1945|read|$accountancy_code_buy_intra = (GETPOSTISSET(''accountancy_code_buy_intra'') ? GETPOST(''accountancy_code_buy_intra'', ''alpha'') : getDolGlobalString(\"ACCOUNTING_SERVICE_BUY_INTRA_ACCOUN"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_SERVICE_SOLD_ACCOUNT', 'string', NULL, 'accountancy', 'Defines the default accounting account used for sold services.', 'Read across 8 occurrences in accountancy/admin/productaccount.php:297,310,692,702, compta/journal/sellsjournal.php:190, product/card.php:1899, journal/cashsellsjournal.php:250, journal/sellsjournal.php:249. Comment: ''at this time ACCOUNTING_SERVICE_SOLD_ACCOUNT & ACCOUNTING_PRODUCT_SOLD_ACCOUNT are account number not accountingacount rowid''.', 'Changing it changes the account number (not the accountingaccount table rowid, per the code comment) used as the default sold-service accounting account in journals and the product card.', 'Stores an account number (not an accountingaccount rowid), per the code comment.', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, '06716155c797b9d1024286abb4b2a0123de263991eda1c3b39640803056ddbde', 'v2', '2026-07-24T06:41:12+00:00', '["// at this time ACCOUNTING_SERVICE_SOLD_ACCOUNT & ACCOUNTING_PRODUCT_SOLD_ACCOUNT are account number not accountingacount rowid", "$aacompta_servsell          = getDolGlobalString(''ACCOUNTING_SERVICE_SOLD_ACCOUNT'', $langs->trans(\"CodeNotDef\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_SERVICE_SOLD_EXPORT_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for export service sales when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:312 and productaccount.php:699 as the fallback export sales account for services. Also used in product/card.php:1922. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the ledger account used for export service sales lines when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, 'ec664cd120520a9ffebd165e50a7667cc52daf03edef4487391542d8d185c931', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:312|read|$aacompta_servsell_export   = getDolGlobalString(''ACCOUNTING_SERVICE_SOLD_EXPORT_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "accountancy/admin/productaccount.php:699|read|$compta_prodsell = getDolGlobalString(''ACCOUNTING_SERVICE_SOLD_EXPORT_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1922|read|$accountancy_code_sell_export = (GETPOST(''accountancy_code_sell_export'') ? GETPOST(''accountancy_code_sell_export'', ''alpha'') : getDolGlobalString(\"ACCOUNTING_SERVICE_SOLD_EXPORT_ACC"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_SERVICE_SOLD_INTRA_ACCOUNT', 'string', NULL, 'accountancy', 'Default accounting account code for intra-community service sales when no per-product code is set.', 'Read in accountancy/admin/productaccount.php:311 and productaccount.php:696 as the fallback intra-community sales account for services. Also used in product/card.php:1910. Configured via accountancy/admin/productaccount.php.', 'Changing this value alters the ledger account used for intra-EU service sales lines when no product-level override exists.', 'Accounting account code string; fallback label is ''CodeNotDef''', 0, 0, 'accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, 'ba0f2d1999babd081225b1066b487fb94731716cfb2c22a8648665df8df9a088', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/admin/productaccount.php:311|read|$aacompta_servsell_intra    = getDolGlobalString(''ACCOUNTING_SERVICE_SOLD_INTRA_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "accountancy/admin/productaccount.php:696|read|$compta_prodsell = getDolGlobalString(''ACCOUNTING_SERVICE_SOLD_INTRA_ACCOUNT'', $langs->trans(\"CodeNotDef\"));", "product/card.php:1910|read|$accountancy_code_sell_intra = (GETPOSTISSET(''accountancy_code_sell_intra'') ? GETPOST(''accountancy_code_sell_intra'', ''alpha'') : getDolGlobalString(\"ACCOUNTING_SERVICE_SOLD_INTRA_AC"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_VAT_BUY_ACCOUNT', 'string', NULL, 'accountancy', 'Defines the default accounting account code used for VAT on purchases in accounting journals.', 'Read in accountancy/journal/purchasesjournal.php:226, accountancy/journal/expensereportsjournal.php:186, accountancy/journal/treasuryjournal.php:363 and :474, accountancy/class/accountingjournal.class.php:806, and compta/journal/purchasesjournal.php:157. Fallback is ''NotDefined''. No admin UI configured.', 'If unset, purchase and expense-report journals use the reserved string ''NotDefined'' as the VAT account code, producing unresolved accounting entries for VAT on purchases.', 'A chart-of-accounts code string; ''NotDefined'' is the reserved fallback used when the constant is absent.', 1, 0, NULL, 1, '3a5c427c62127c8c17b53f82cbb379aff563f1e8465fb5ea6ee6f5f49c6aef14', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/purchasesjournal.php:226|read|$cpttva = getDolGlobalString(''ACCOUNTING_VAT_BUY_ACCOUNT'', ''NotDefined'');", "accountancy/journal/treasuryjournal.php:363|read|$account_vat_buy = getDolGlobalString(''ACCOUNTING_VAT_BUY_ACCOUNT'', ''NotDefined''); // NotDefined is a reserved word", "accountancy/class/accountingjournal.class.php:806|read|$acc_vat_coll_def = getDolGlobalString(''ACCOUNTING_VAT_BUY_ACCOUNT'');", "accountancy/journal/expensereportsjournal.php:186|read|$account_vat = getDolGlobalString(''ACCOUNTING_VAT_BUY_ACCOUNT'', ''NotDefined'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_VAT_BUY_REVERSE_CHARGES_CREDIT', 'string', NULL, 'accountancy', 'Accounting account number used for the credit side of VAT reverse-charge entries in the purchases journal.', 'Read in accountancy/journal/purchasesjournal.php:227 with default ''NotDefined'' (a reserved word, per the same convention as other account constants in this file), alongside its debit-side counterpart ACCOUNTING_VAT_BUY_REVERSE_CHARGES_DEBIT.', 'Setting a valid accounting account number allows purchase VAT reverse-charge credit entries to be posted correctly in bookkeeping; left as ''NotDefined'' it is treated as not configured.', 'Any accounting account number string; default ''NotDefined'' is a reserved sentinel meaning not configured.', 1, 0, NULL, 1, '0c74ba51e18ac8b18d5fb207c17dd4e3a1a40f1a7df03dcb00c017aaee16a4ce', 'v2', '2026-07-24T07:05:23+00:00', '["purchasesjournal.php:227: $rcctva = getDolGlobalString(''ACCOUNTING_VAT_BUY_REVERSE_CHARGES_CREDIT'', ''NotDefined'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_VAT_BUY_REVERSE_CHARGES_DEBIT', 'string', NULL, 'accountancy', 'Accounting account code used as the debit counterpart for VAT reverse charge on purchases when no per-VAT-rate account is defined.', 'Read in accountancy/journal/purchasesjournal.php:228 (`$rcdtva = getDolGlobalString(''ACCOUNTING_VAT_BUY_REVERSE_CHARGES_DEBIT'', ''NotDefined'')`) and used as fallback at line ~321-330 when generating the purchases journal reverse-charge entries. Editable via the accountancy Default Accounts admin page (accountancy/admin/defaultaccounts.php) but only shown when ACCOUNTING_FORCE_ENABLE_VAT_REVERSE_CHARGE is enabled.', 'Determines which accounting account is debited for VAT reverse charge on purchase invoices when the transaction''s own VAT rate has no dedicated reverse-charge account configured; wrong or unset value posts to ''NotDefined''.', 'Free-text accounting account number string; falls back to literal ''NotDefined'' if unset.', 0, 0, NULL, 1, 'aa46e4ffee506585862d074ce506a339e4340139efff52ee620d328ac9fcb924', 'v2', '2026-07-24T07:05:23+00:00', '["accountancy/journal/purchasesjournal.php:228|read|$rcdtva = getDolGlobalString(''ACCOUNTING_VAT_BUY_REVERSE_CHARGES_DEBIT'', ''NotDefined'');", "accountancy/admin/defaultaccounts.php:115: $list_account[] = ''ACCOUNTING_VAT_BUY_REVERSE_CHARGES_DEBIT'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_VAT_PAY_ACCOUNT', 'string', NULL, 'accountancy', 'Stores the general ledger account number used for VAT payment entries in the bank journal.', 'Read in accountancy/journal/bankjournal.php:273 and :1459, and in accountancy/journal/treasuryjournal.php:710. The ''NotDefined'' reserved-word fallback is applied at both bankjournal and treasuryjournal read sites. No admin UI write found; HIDDEN_GUESS is 1.', 'If not set, VAT payment lines in the bank and treasury journals use ''NotDefined'' as the account, which will cause posting errors.', 'String: general ledger account number; empty = not configured', 1, 0, NULL, 1, '9cbef94c5b0d6f5eb72b1c75d1fc4da0d1e15424c0c900ed5cc741ce83c47d3a', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/bankjournal.php:273|read|$account_pay_vat = getDolGlobalString(''ACCOUNTING_VAT_PAY_ACCOUNT'', ''NotDefined''); // NotDefined is a reserved word", "accountancy/journal/bankjournal.php:1459|read|$account_ledger = getDolGlobalString(''ACCOUNTING_VAT_PAY_ACCOUNT'');", "accountancy/journal/treasuryjournal.php:710|read|$account_pay_vat = getDolGlobalString(''ACCOUNTING_VAT_PAY_ACCOUNT'', ''NotDefined''); // NotDefined is a reserved word"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACCOUNTING_VAT_SOLD_ACCOUNT', 'string', NULL, 'accountancy', 'Defines the default accounting account used for VAT on sales.', 'Read in accountancy/class/accountingjournal.class.php:1120 (comment: ''Normal to apply vat default account for sold with supplier''s discount''), journal/cashsellsjournal.php:229, journal/sellsjournal.php:228, compta/journal/sellsjournal.php:193, journal/treasuryjournal.php:245, most falling back to ''NotDefined''.', 'Changing it changes which accounting account VAT-on-sales amounts are booked to across the sells/cash-sells/treasury journals.', 'Falls back to ''NotDefined'' when unset (reserved word).', 0, 0, NULL, 1, 'dde323f4afd9500664608dc05012dd107fbe21e11eb96f5d4f12fa79544cff53', 'v2', '2026-07-24T06:41:12+00:00', '["$acc_vat_ded_def  = getDolGlobalString(''ACCOUNTING_VAT_SOLD_ACCOUNT'');\t\t\t// Normal to apply vat default account for sold with supplier''s discount", "$account_vat_sold = getDolGlobalString(''ACCOUNTING_VAT_SOLD_ACCOUNT'', ''NotDefined''); // NotDefined is a reserved word"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ACTION_EVENT_ADDON_PDF', 'string', NULL, 'admin', 'Name of the PDF document template model used for agenda event (action/communication) documents.', 'COMMENTS state: ''Name of PDF model of actioncomm''. Written via admin/agenda_other.php:178, admin/agenda_reminder.php:147-150 (including deletion at line 142) and read/checked across both admin pages. Configurable via admin/agenda_other.php and admin/agenda_reminder.php.', 'Changing this value switches the PDF template used when generating agenda event documents; an invalid model name will prevent document generation.', 'String name of a PDF model class available for action/communication documents (e.g. ''standard''). Empty = default model used.', 0, 0, 'admin/agenda_other.php|admin/agenda_other.php|admin/agenda_other.php|admin/agenda_reminder.php|admin/agenda_reminder.php|admin/agenda_other.php|admin/agenda_reminder.php|admin/agenda_other.php|admin/agenda_reminder.php', 1, '5a514145c15dbce8ac6f08d8a0f6ceb66e551d553bd55a9ba14e7e7133784971', 'v2', '2026-04-21T13:29:58+00:00', '["// $this->const[$r] = [\"ACTION_EVENT_ADDON_PDF\", \"chaine\", \"standard\", ''Name of PDF model of actioncomm'', 0];", "admin/agenda_other.php:178|write|dolibarr_set_const($db, \"ACTION_EVENT_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity);", "admin/agenda_other.php:306|check|if (getDolGlobalString(''ACTION_EVENT_ADDON_PDF'') == \"$name\") {", "admin/agenda_reminder.php:147|write|if (dolibarr_set_const($db, \"ACTION_EVENT_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADD_UNSPLASH_LOGIN_BACKGROUND', 'string', NULL, 'core', 'Sets a background image URL (e.g. from Unsplash) to display on the Dolibarr login page.', 'When set, the login page renders the value as a CSS background-image URL on the body element (core/tpl/login.tpl.php:217). It is also checked in passwordforgotten and passwordreset templates. Configurable via admin/ihm.php.', 'Setting this changes the login page background from the default theme to the specified image URL. Removing it reverts to the default background style.', 'Any valid image URL string, e.g. ''https://source.unsplash.com/random''', 0, 0, 'admin/ihm.php', 1, '4b9de2f54c8546a05fd96b7cde2cfe4225d302d340dceabd55150506d194bf21', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/login.tpl.php:216  // For example $conf->global->ADD_UNSPLASH_LOGIN_BACKGROUND = ''https://source.unsplash.com/random''?>", "core/tpl/login.tpl.php:217|read|<body class=\"body bodylogin\" style=\"background-image: url(''<?php echo dol_escape_htmltag(getDolGlobalString(''ADD_UNSPLASH_LOGIN_BACKGROUND'')); ?>'');", "admin/ihm.php:721|check|if (getDolGlobalString(''ADD_UNSPLASH_LOGIN_BACKGROUND'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_ADDON_PDF', 'string', NULL, 'adherents', 'Selects the default PDF document model used to generate member (adherent) card/document PDFs.', 'In adherents/class/adherent.class.php:2850-2851, generateDocument() falls back to this constant''s value as $modele if the member has no per-record model_pdf set, before falling back further to ''standard''.', 'Setting it changes which PDF template (from core/modules/member/doc/) is used by default to generate member documents/cards when no record-specific model is set.', 'String: name of a member PDF doc model (e.g. matching a model in core/modules/member/doc/).', 1, 0, NULL, 1, '45873db789ba8a5c25ae5a8435c393c75b7f0d01a9e345993a097afe4e627855', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/class/adherent.class.php:2850|read|} elseif (getDolGlobalString(''ADHERENT_ADDON_PDF'')) {", "adherents/class/adherent.class.php:2851|read|$modele = getDolGlobalString(''ADHERENT_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_ADDRESSES_MANAGEMENT', 'string', NULL, 'adherents', 'Switches the member canvas UI labels between member-centric and address-centric terminology.', 'Checked in three consecutive lines of adherents/canvas/default/actions_adherentcard_default.class.php (lines 66, 69, 72) to choose between ''Adherent''/''EditAdherent''/''NewAdherent'' and ''ContactAddress''/''EditAdherentAddress''/''NewAdherentAddress'' translations. No admin UI is provided.', 'Setting this constant changes the display labels in the member canvas, presenting the form as a member record rather than an address record.', 'Non-empty/truthy = member terminology used; empty/unset = address terminology used.', 1, 0, NULL, 1, '2a1c61b835f85ae9d0834292a049615d34a215d6ccf4c2fdc53949102c194b9b', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/canvas/default/actions_adherentcard_default.class.php:66|read|$out .= (getDolGlobalString(''ADHERENT_ADDRESSES_MANAGEMENT'') ? $langs->trans(\"Adherent\") : $langs->trans(\"ContactAddress\"));", "adherents/canvas/default/actions_adherentcard_default.class.php:69|read|$out .= (getDolGlobalString(''ADHERENT_ADDRESSES_MANAGEMENT'') ? $langs->trans(\"EditAdherent\") : $langs->trans(\"EditAdherentAddress\"));", "adherents/canvas/default/actions_adherentcard_default.class.php:72|read|$out .= (getDolGlobalString(''ADHERENT_ADDRESSES_MANAGEMENT'') ? $langs->trans(\"NewAdherent\") : $langs->trans(\"NewAdherentAddress\"));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_AUTOREGISTER_NOTIF_MAIL', 'string', NULL, 'public', 'Body content of the internal notification email sent to the company when a guest self-registers as a member.', 'Configured via admin UI adherents/admin/member_emails.php:78 (type ''html'') and read in public/members/new.php:531/553, used via $adh->makeSubstitution(getDolGlobalString(''ADHERENT_AUTOREGISTER_NOTIF_MAIL'')) as the message body.', 'Required together with ADHERENT_AUTOREGISTER_NOTIF_MAIL_SUBJECT and MAIN_INFO_SOCIETE_MAIL for the notification email to be sent; its content supports member substitution variables (per __ID__, __FIRSTNAME__ etc. listed as helptext in member_emails.php).', 'HTML content string; en_US description: ''Content of the notification email received in case of auto-inscription of a guest''.', 0, 0, NULL, 1, 'da47eaea7430c99657f7a0dafa0b2afdb643ea759ca33ff7708d1f6d1622d9eb', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/admin/member_emails.php:78: ''ADHERENT_AUTOREGISTER_NOTIF_MAIL'' => array(''type'' => ''html'', ''tooltip'' => $helptext, ''label'' => '''')", "public/members/new.php:531: getDolGlobalString(''ADHERENT_AUTOREGISTER_NOTIF_MAIL'')) {", "langs/en_US/members.lang:153: DescADHERENT_AUTOREGISTER_NOTIF_MAIL=Content of the notification email received in case of auto-inscription of a guest"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_AUTOREGISTER_NOTIF_MAIL_SUBJECT', 'string', NULL, 'public', 'Subject line of the internal notification email sent to the company when a guest self-registers as a member.', 'Configured via admin UI adherents/admin/member_emails.php:77 (type ''string'') and read in public/members/new.php:530/550, used as part of the subject ''[appli] ''.getDolGlobalString(''ADHERENT_AUTOREGISTER_NOTIF_MAIL_SUBJECT'') when sending the notification.', 'This subject (together with ADHERENT_AUTOREGISTER_NOTIF_MAIL and MAIN_INFO_SOCIETE_MAIL) must all be set for the auto-registration notification email to be sent at all; without it the notification email is skipped.', 'Free-form string; en_US description: ''Subject of the notification email received in case of auto-inscription of a guest''.', 0, 0, NULL, 1, 'fedfcb563f7c5d1299c975fabbec3eacf390ed7ea951cc65e22702f4d37ea870', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/admin/member_emails.php:77: ''ADHERENT_AUTOREGISTER_NOTIF_MAIL_SUBJECT'' => array(''type'' => ''string'', ''label'' => ''''),", "public/members/new.php:530: if (getDolGlobalString(''MAIN_INFO_SOCIETE_MAIL'') && getDolGlobalString(''ADHERENT_AUTOREGISTER_NOTIF_MAIL_SUBJECT'') &&", "langs/en_US/members.lang:152: DescADHERENT_AUTOREGISTER_NOTIF_MAIL_SUBJECT=Subject of the notification email received in case of auto-inscription of a guest"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_BANK_USE', 'string', NULL, 'adherents', 'Controls how member subscription payments are recorded in the banking system.', 'Determines whether subscription payments are recorded directly to a bank account (''bankdirect''), via an invoice (''bankviainvoice''), or not at all. Checked across adherents/subscription.php:864, adherents/subscription/card.php:255-351, and public/payment/paymentok.php:744. Configurable via adherents/admin/member.php:179.', 'Changing this value alters how member subscription payments are processed and recorded: direct bank entry, invoice-based bank entry, or no bank recording.', '''bankdirect'' = direct bank account entry; ''bankviainvoice'' = payment via generated invoice; empty/unset = no bank recording.', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php|adherents/admin/member.php', 1, 'd3def328e53b0962cefe15f62e04ce121b8d53e41796283b1c71ba3dc9b5273b', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:638|check|if (getDolGlobalString(''ADHERENT_BANK_USE'') == ''bankdirect'' || getDolGlobalString(''ADHERENT_BANK_USE'') == ''bankviainvoice'') {", "public/payment/paymentok.php:744|check|if (getDolGlobalString(''ADHERENT_BANK_USE'') == ''bankviainvoice'' && isModEnabled(\"bank\") && isModEnabled(\"societe\") && isModEnabled(''invoice'')) {", "adherents/subscription.php:864|check|if (getDolGlobalString(''ADHERENT_BANK_USE'') == ''bankviainvoice'' && isModEnabled(''bank'') && isModEnabled(''societe'') && isModEnabled(''invoice'')) {", "adherents/admin/member.php:179|write|$res4 = dolibarr_set_const($db, ''ADHERENT_BANK_USE'', GETPOST(''ADHERENT_BANK_USE'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CARDS_ADDON_PDF', 'string', NULL, 'core', 'Specifies the PDF template module class name used to generate member visit/ID cards.', 'Read at core/modules/member/modules_cards.php:97–98 to load the configured PDF template class. The docblock comment at :69 states ''Create a document for visit card according to template defined in ADHERENT_CARDS_ADDON_PDF''. When unset, no specific template is selected.', 'Changing this value switches the PDF template used for member card generation. Leaving it unset means no template class is loaded via this constant.', 'String: PHP class name of the PDF template module (e.g. ''pdf_standard_cards''); empty/unset = no template loaded.', 1, 0, NULL, 1, '211a14ccaac7e49147dcc4ca113dcfdc16c2860fe0c323e01f36f725cf73d648', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/member/modules_cards.php:69  *\tCreate a document for visit card according to template defined in ADHERENT_CARDS_ADDON_PDF", "core/modules/member/modules_cards.php:97|check|if (getDolGlobalString(''ADHERENT_CARDS_ADDON_PDF'')) {", "core/modules/member/modules_cards.php:98|read|$code = getDolGlobalString(''ADHERENT_CARDS_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CARD_BACKGROUND', 'string', NULL, 'core', 'Specifies the filename (relative to the member output directory) of a background image for member card PDFs.', 'Checked and read in core/modules/member/doc/pdf_standard_member.class.php at lines 139-140. If the file exists at the expected path, it is set as the background image for the generated member card PDF. No admin UI write is present.', 'When set and the referenced file exists, the member card PDF uses it as a background image. When unset or file not found, no background image is applied.', 'Filename string relative to the member output directory; empty or unset for no background.', 1, 0, NULL, 1, '2e7f2960f3fd5d68609f5ebeda3a15d6f5d8e7d9a8650e05a6d17ca069132d63', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/member/doc/pdf_standard_member.class.php:139|check|if (getDolGlobalString(''ADHERENT_CARD_BACKGROUND'') && file_exists($conf->adherent->dir_output.''/'' . getDolGlobalString(''ADHERENT_CARD_BACKGROUND''))) {", "core/modules/member/doc/pdf_standard_member.class.php:140|read|$backgroundimage = $conf->adherent->dir_output.''/'' . getDolGlobalString(''ADHERENT_CARD_BACKGROUND'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CARD_FOOTER_TEXT', 'string', NULL, 'adherents', 'Stores the footer text printed at the bottom of member identification cards.', 'Set via the admin UI at adherents/admin/member.php:207 and rendered as a text input at :779. The value is passed through make_substitutions and used in adherents/cartes/carte.php:200 and core/modules/member/doc/pdf_standard_member.class.php:356.', 'Changing this value updates the footer text on all newly generated member cards.', 'Any string; substitution tokens are replaced at render time', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'a98970125413b88bc4b98f532fb02207fe2336cff7c8b7c0d10e5b3e95582f27', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:207|write|$res4 = dolibarr_set_const($db, ''ADHERENT_CARD_FOOTER_TEXT'', GETPOST(''ADHERENT_CARD_FOOTER_TEXT'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "adherents/cartes/carte.php:200|read|$textfooter = make_substitutions(getDolGlobalString(''ADHERENT_CARD_FOOTER_TEXT''), $substitutionarray);", "core/modules/member/doc/pdf_standard_member.class.php:356|read|$textfooter = make_substitutions(getDolGlobalString(\"ADHERENT_CARD_FOOTER_TEXT\"), $substitutionarray);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CARD_HEADER_TEXT', 'string', NULL, 'adherents', 'Stores the header text printed at the top of member identification cards.', 'Set via the admin UI at adherents/admin/member.php:204 and rendered as a text input at :760. The value is passed through make_substitutions and used in both adherents/cartes/carte.php:199 and core/modules/member/doc/pdf_standard_member.class.php:355.', 'Changing this value updates the header text on all newly generated member cards.', 'Any string; substitution tokens (e.g. __MEMBER_FULLNAME__) are replaced at render time', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'b090099288218b051703002f73f49ff0c2c09eaf3ed936051bb83c01b31d09f9', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:204|write|$res2 = dolibarr_set_const($db, ''ADHERENT_CARD_HEADER_TEXT'', GETPOST(''ADHERENT_CARD_HEADER_TEXT'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "core/modules/member/doc/pdf_standard_member.class.php:355|read|$textheader = make_substitutions(getDolGlobalString(\"ADHERENT_CARD_HEADER_TEXT\"), $substitutionarray);", "adherents/cartes/carte.php:199|read|$textheader = make_substitutions(getDolGlobalString(''ADHERENT_CARD_HEADER_TEXT''), $substitutionarray);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CARD_TEXT', 'string', NULL, 'adherents', 'Stores the left-side body text printed on member identification cards.', 'Set via the admin UI at adherents/admin/member.php:205. The value is passed through make_substitutions and used in adherents/cartes/carte.php:198 and core/modules/member/doc/pdf_standard_member.class.php:354.', 'Changing this value updates the left body text on all newly generated member cards.', 'Any string; substitution tokens are replaced at render time', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'f6f4af1839ff6bf6d081904b8ae5c0dc96492525277e4aa3eb30d5ba61bdd5da', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:205|write|$res3 = dolibarr_set_const($db, ''ADHERENT_CARD_TEXT'', GETPOST(''ADHERENT_CARD_TEXT'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "adherents/cartes/carte.php:198|read|$textleft = make_substitutions(getDolGlobalString(''ADHERENT_CARD_TEXT''), $substitutionarray);", "core/modules/member/doc/pdf_standard_member.class.php:354|read|$textleft = make_substitutions(getDolGlobalString(\"ADHERENT_CARD_TEXT\"), $substitutionarray);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CARD_TEXT_RIGHT', 'string', NULL, 'adherents', 'Stores the right-side body text printed on member identification cards.', 'Set via the admin UI at adherents/admin/member.php:206. The value is passed through make_substitutions and used in adherents/cartes/carte.php:201 and core/modules/member/doc/pdf_standard_member.class.php:357.', 'Changing this value updates the right body text on all newly generated member cards.', 'Any string; substitution tokens are replaced at render time', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'ebbd42b769fed522884522d9a30e77443127130f1cef0de9d7886edcc23e28b3', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:206|write|$res3 = dolibarr_set_const($db, ''ADHERENT_CARD_TEXT_RIGHT'', GETPOST(''ADHERENT_CARD_TEXT_RIGHT'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "adherents/cartes/carte.php:201|read|$textright = make_substitutions(getDolGlobalString(''ADHERENT_CARD_TEXT_RIGHT''), $substitutionarray);", "core/modules/member/doc/pdf_standard_member.class.php:357|read|$textright = make_substitutions(getDolGlobalString(\"ADHERENT_CARD_TEXT_RIGHT\"), $substitutionarray);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CARD_TYPE', 'string', NULL, 'adherents', 'Specifies the default card model used when printing member identification cards.', 'Set via the admin UI at adherents/admin/member.php:203 and rendered as a dropdown at :754 defaulting to ''CARD''. Also read in adherents/cartes/carte.php:339 and :357 as the pre-selected model for card printing.', 'Changing this value alters which card template is pre-selected on the member card printing page.', 'String name of the card model (e.g. ''CARD''); empty or unset = no default selected', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, '402970de2502e3635de5e74524bc69d465b314412c6b6b5b010cb06b4ffab117', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:754|read|print $form->selectarray(''ADHERENT_CARD_TYPE'', $arrayoflabels, getDolGlobalString(''ADHERENT_CARD_TYPE'', ''CARD''), 1, 0, 0);", "adherents/admin/member.php:203|write|$res1 = dolibarr_set_const($db, ''ADHERENT_CARD_TYPE'', GETPOST(''ADHERENT_CARD_TYPE''), ''chaine'', 0, '''', $conf->entity);", "adherents/cartes/carte.php:339|read|print $form->selectarray(''modelcard'', $arrayoflabels, (GETPOST(''modelcard'') ? GETPOST(''modelcard'') : getDolGlobalString(''ADHERENT_CARD_TYPE'')), 1, 0, 0, '''', 0, 0, 0, '''', '''', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CC_MAIL_FROM', 'string', NULL, 'adherents', 'Sets a CC (carbon-copy) email address applied to the automatic member subscription-expiration reminder email.', 'In adherents/class/adherent.class.php:3338, within sendReminderForExpiredSubscription(), $cc = getDolGlobalString(''ADHERENT_CC_MAIL_FROM'') is passed to the CMailFile constructor alongside the from-address (ADHERENT_MAIL_FROM) and the member''s email as recipient.', 'Setting it adds the given address as CC on every expiration-reminder email sent to members; leaving it unset (empty string) means no CC is added.', 'String: an email address (or empty, the default, meaning no CC).', 1, 0, NULL, 1, 'b5e5b64c92cb4ee310c193a035378d233f4cebd0d5c6055fcf0e4fa85bec2759', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/class/adherent.class.php:3338|read|$cc = getDolGlobalString(''ADHERENT_CC_MAIL_FROM'');", "adherents/class/adherent.class.php: $cmail = new CMailFile($subject, $to, $email_from, $msg, array(), array(), array(), $cc, '''', 0, 1, '''', '''', $trackid, $moreinheader);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_CREATE_EXTERNAL_USER_LOGIN', 'string', NULL, 'adherents', 'Controls whether an external user login is automatically created when a member subscription payment is completed.', 'Rendered as a yes/no selector in adherents/admin/member.php:601 and saved via dolibarr_set_const at :178. Checked at public/payment/paymentok.php:900 to trigger external user creation after successful payment.', 'Enabling this causes Dolibarr to create an external user account for new members upon payment confirmation; disabling skips that step.', '0 = do not create external user login; 1 = create external user login on payment', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'c51cfd2e75dd41c4ddb2c1a238065886918f7c173cea6dde82a520bd4b203cd9', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:601|read|print $form->selectyesno(''ADHERENT_CREATE_EXTERNAL_USER_LOGIN'', getDolGlobalInt(''ADHERENT_CREATE_EXTERNAL_USER_LOGIN''), 1, false, 0, 1);", "adherents/admin/member.php:178|write|$res3 = dolibarr_set_const($db, ''ADHERENT_CREATE_EXTERNAL_USER_LOGIN'', GETPOST(''ADHERENT_CREATE_EXTERNAL_USER_LOGIN'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "public/payment/paymentok.php:900|check|if (getDolGlobalString(''ADHERENT_CREATE_EXTERNAL_USER_LOGIN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_DEFAULT_CREATE_THIRDPARTY', 'string', NULL, 'public', 'Controls whether a linked third party is created by default when a member (adherent) is created.', 'Checked in public/members/new.php:569 (public member subscription form) and adherents/card.php:665.', 'Enabling it triggers automatic third-party creation when a new member record is created via the public form or the member card.', NULL, 0, 0, NULL, 1, 'd8041b63c42630c5bce95151ec843d9bed541e31fa92ae836430dac26005d3db', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''ADHERENT_DEFAULT_CREATE_THIRDPARTY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_DEFAULT_SENDINFOBYMAIL', 'string', NULL, 'adherents', 'Sets the default checked state of the ''send information by email'' checkbox on member subscription and card forms.', 'Read at adherents/subscription.php:1189 and adherents/card.php:1731, 1795, 1856 to pre-check the email notification checkbox when no explicit POST value is present. Configurable via adherents/admin/member.php:177.', 'Enabling this constant causes the email notification checkbox to be pre-checked by default on member-related forms, increasing the likelihood that confirmation emails are sent.', 'Non-empty/truthy = checkbox pre-checked; empty/unset = checkbox unchecked by default.', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'f6207da48bd96a8fc68f9b2479a6c550254a73b27151668b424fe0c7d56bc9de', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/subscription.php:1189|read|$tmp = ''<input name=\"sendmail\" type=\"checkbox\"''.(GETPOST(''sendmail'', ''alpha'') ? '' checked'' : (getDolGlobalString(''ADHERENT_DEFAULT_SENDINFOBYMAIL'') ? '' checked'' : '''')).''>'';", "adherents/card.php:1731|read|$formquestion[] = array(''type'' => ''checkbox'', ''name'' => ''send_mail'', ''label'' => $label, ''value'' => (getDolGlobalString(''ADHERENT_DEFAULT_SENDINFOBYMAIL'') ? true : false));", "adherents/admin/member.php:177|write|$res3 = dolibarr_set_const($db, ''ADHERENT_DEFAULT_SENDINFOBYMAIL'', GETPOST(''ADHERENT_DEFAULT_SENDINFOBYMAIL'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "adherents/admin/member.php:606|read|print $form->selectyesno(''ADHERENT_DEFAULT_SENDINFOBYMAIL'', getDolGlobalInt(''ADHERENT_DEFAULT_SENDINFOBYMAIL''), 1, false, 0, 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_EMAIL_TEMPLATE_AUTOREGISTER', 'string', NULL, 'public', 'Selects the email template used to notify a member when they self-register via the public member form.', 'Configured via admin UI adherents/admin/member_emails.php:70 (type ''emailtemplate:member'') and read in public/members/new.php:502 to fetch the template via $formmail->getEMailTemplate(..., $labeltouse) for the auto-registration confirmation email.', 'Setting this to a template label makes the auto-registration confirmation email use that template''s subject/content instead of the default hard-coded text.', 'Label/id of an email template of type ''member'' (as selectable in the emailtemplate:member admin picker); DescADHERENT_EMAIL_TEMPLATE_AUTOREGISTER lang string: ''Email template to use to send email to a member on member auto-registration''.', 0, 0, NULL, 1, 'c0b095a84ecc8ddc4f9efea450fcf736ba031973fc2f0c9733fd02fd690f365d', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/admin/member_emails.php:70: ''ADHERENT_EMAIL_TEMPLATE_AUTOREGISTER'' => array(''type'' => ''emailtemplate:member'', ''label'' => ''''),", "public/members/new.php:502: $labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_AUTOREGISTER'');", "langs/en_US/members.lang:154: DescADHERENT_EMAIL_TEMPLATE_AUTOREGISTER=Email template to use to send email to a member on member auto-registration"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_EMAIL_TEMPLATE_CANCELATION', 'string', NULL, 'adherents', 'Selects which email template (by label) is used to send the member-cancelation notification email.', 'Read twice in adherents/card.php (lines 798 and 1762) as $labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_CANCELATION''); if non-empty, $formmail->getEMailTemplate(...) loads the named template (''member'' type) to build the cancelation email sent to the member.', 'Setting it to a valid email-template label makes the cancelation email use that template''s subject/content; leaving it unset skips loading a template for this notification path.', 'String: label of an email template (of type ''member'') used when canceling a member''s subscription/membership.', 1, 0, NULL, 1, '77ce49842f3d0bbad5d5f53a43e0a9e3b55560cd406209aa221eb929f0e5cac6', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/card.php:798|read|$labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_CANCELATION'');", "adherents/card.php:1762|read|$labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_CANCELATION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_EMAIL_TEMPLATE_EXCLUSION', 'string', NULL, 'adherents', 'Sets the email template label used for the member exclusion/subscription email sent from the member card.', 'Read in adherents/card.php:865 and :1823 as $labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_EXCLUSION''), then passed to FormMail::getEMailTemplate() to fetch a predefined email template by label.', 'If set, the email sent (e.g. on exclusion/subscription action) uses the named template''s subject/content instead of the default; if empty, no default template is looked up (default flow uses hardcoded subject/content).', 'String: a template label recognized by FormMail::getEMailTemplate (module ''member'').', 1, 0, NULL, 1, 'd456e6696f15233e72c04c6ec70dd7643db05615ab2d3632c17dd6afa339dea1', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/card.php:865: $labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_EXCLUSION'');", "adherents/card.php:866: if (!empty($labeltouse)) { $arraydefaultmessage = $formmail->getEMailTemplate($db, ''member'', $user, $outputlangs, 0, 1, $labeltouse); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_EMAIL_TEMPLATE_MEMBER_VALIDATION', 'string', NULL, 'adherents', 'Selects which email template (by label) is used to send the member-validation/subscription confirmation email.', 'Read twice in adherents/card.php (lines 730 and 1698) as $labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_MEMBER_VALIDATION''); if non-empty, $formmail->getEMailTemplate(...) loads the named template (''member'' type) to build the subscription email sent to the member.', 'Setting it to a valid email-template label makes the validation email use that template''s subject/content; leaving it unset skips loading a template for this notification path.', 'String: label of an email template (of type ''member'') used when validating a member''s subscription.', 1, 0, NULL, 1, '12bedde22556490fa22f8c28f68e5062d321512ddabe00fa006c8260d8fba190', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/card.php:730|read|$labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_MEMBER_VALIDATION'');", "adherents/card.php:1698|read|$labeltouse = getDolGlobalString(\"ADHERENT_EMAIL_TEMPLATE_MEMBER_VALIDATION\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_EMAIL_TEMPLATE_REMIND_EXPIRATION', 'string', NULL, 'adherents', 'Selects which email template (by label) is used to send the subscription-expiration reminder email to members.', 'In adherents/class/adherent.class.php:3323, sendReminderForExpiredSubscription() reads this constant as $labeltouse and, if non-empty, loads the corresponding template via $formmail->getEMailTemplate(...); it is configured in adherents/admin/member_emails.php as the template row shown only when MEMBER_REMINDER_EMAIL is enabled.', 'Setting it to a valid email-template label makes the reminder cron use that template''s subject/content (with substitution variables) instead of sending no templated reminder.', 'String: label of an email template (of type ''member'') to use for expiration reminders.', 0, 0, NULL, 1, 'e8119da16134c79777c16dd27ba171b3e34ee15f2bf8cf1d6b4743cc6570f3f6', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/class/adherent.class.php:3323|read|$labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_REMIND_EXPIRATION'');", "adherents/admin/member_emails.php:202|check|if ($const == ''ADHERENT_EMAIL_TEMPLATE_REMIND_EXPIRATION'' && !getDolGlobalString(''MEMBER_REMINDER_EMAIL'')) { continue; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_EMAIL_TEMPLATE_SUBSCRIPTION', 'string', NULL, 'adherents', 'Specifies the email template label used when sending subscription confirmation emails to members.', 'The template label is read at adherents/subscription.php:382 and 1173, and at public/payment/paymentok.php:948, to select the appropriate email template for subscription events. No admin UI is provided.', 'Setting this constant to a valid email template label causes that template to be used for member subscription confirmation emails instead of any default.', 'A string matching an email template label; empty/unset = no specific template selected.', 1, 0, NULL, 1, '35044f3369a6f2a6c370b220b23fdbb56f175ea6d831090690492f90f3ac0c52', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/subscription.php:382|read|$labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_SUBSCRIPTION'');", "adherents/subscription.php:1173|read|$labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_SUBSCRIPTION'');", "public/payment/paymentok.php:948|read|$labeltouse = getDolGlobalString(''ADHERENT_EMAIL_TEMPLATE_SUBSCRIPTION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_ETIQUETTE_TEXT', 'string', NULL, 'adherents', 'Defines the text template used when printing member address labels.', 'Set via the admin UI at adherents/admin/member.php:220. If not set, adherents/cartes/carte.php:235–236 applies a default template with member title, full name, address, zip, town, and country tokens. The value is passed through make_substitutions at carte.php:238.', 'Changing this value alters the layout of member address labels; clearing it causes Dolibarr to fall back to the built-in default label template.', 'Any string with substitution tokens; empty = default template applied (__MEMBER_TITLE__, __MEMBER_FULLNAME__, __MEMBER_ADDRESS__, __MEMBER_ZIP__ __MEMBER_TOWN__, __MEMBER_COUNTRY__)', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'b0cd921cfd4b5ff08656592641aad549784e2b216f266ebf1f39fd8990acabb5', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/cartes/carte.php:235|check|if (!getDolGlobalString(''ADHERENT_ETIQUETTE_TEXT'')) {", "adherents/cartes/carte.php:236|write|$conf->global->ADHERENT_ETIQUETTE_TEXT = \"__MEMBER_TITLE__\\n__MEMBER_FULLNAME__\\n__MEMBER_ADDRESS__\\n__MEMBER_ZIP__ __MEMBER_TOWN__\\n__MEMBER_COUNTRY__\";", "adherents/admin/member.php:220|write|$res2 = dolibarr_set_const($db, ''ADHERENT_ETIQUETTE_TEXT'', GETPOST(''ADHERENT_ETIQUETTE_TEXT'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "adherents/cartes/carte.php:238|read|$textleft = make_substitutions(getDolGlobalString(''ADHERENT_ETIQUETTE_TEXT''), $substitutionarray);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_ETIQUETTE_TYPE', 'string', NULL, 'adherents', 'Stores the selected label model (sticker template) used when printing member address cards.', 'Written by adherents/admin/member.php:219 and defaulted to ''CARD'' in the selector at adherents/admin/member.php:818. Read in core/modules/printsheet/modules_labels.php:98-99 to select the label module, and in barcode/printsheet.php:426 and adherents/cartes/carte.php:376 as the pre-selected model.', 'Changing this value changes the default label template applied when printing member cards; the selected value must correspond to an installed label module.', 'Label module code string, e.g. ''CARD''; empty = none selected.', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, '780fbd448a5c177608821087fe5eadf60ffc637433d26de9c749d0666da52b1a', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:219|write|$res1 = dolibarr_set_const($db, ''ADHERENT_ETIQUETTE_TYPE'', GETPOST(''ADHERENT_ETIQUETTE_TYPE''), ''chaine'', 0, '''', $conf->entity);", "adherents/admin/member.php:818|read|print $form->selectarray(''ADHERENT_ETIQUETTE_TYPE'', $arrayoflabels, getDolGlobalString(''ADHERENT_ETIQUETTE_TYPE'') ? getDolGlobalString(''ADHERENT_ETIQUETTE_TYPE'') : ''CARD'', 1, 0, 0)", "core/modules/printsheet/modules_labels.php:99|read|$code = getDolGlobalString(''ADHERENT_ETIQUETTE_TYPE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_LOGIN_NOT_REQUIRED', 'string', '1', 'adherents', 'Controls whether a login is required for member (adherent) records; when truthy, login is not required.', 'Managed via adherents/admin/member.php. The comment at adherents/class/adherent.class.php:958 explains: ''If option ADHERENT_LOGIN_NOT_REQUIRED is on, there is no login of member, so we do not overwrite user login to keep existing one.'' The admin UI stores 0 when the user selects ''yes'' (login not required) and 1 when ''no''. Checked in adherents/card.php, adherents/subscription.php, and partnership/partnership_list.php.', 'When set (truthy), member records can be created without a login field. When unset or 0, a login is enforced for members, and the login field is required and may overwrite linked user logins.', '1 (default) = login not required for members; 0 = login required.', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, '6dd852ab3ba82434fcdca585ec0c649cf69c450e6beafb16aeb0b355684dad68', 'v2', '2026-04-21T11:16:15+00:00', '["// If option ADHERENT_LOGIN_NOT_REQUIRED is on, there is no login of member, so we do not overwrite user login to keep existing one.", "adherents/admin/member.php:175|write|$res1 = dolibarr_set_const($db, ''ADHERENT_LOGIN_NOT_REQUIRED'', GETPOST(''ADHERENT_LOGIN_NOT_REQUIRED'', ''alpha'') ? 0 : 1, ''chaine'', 0, '''', $conf->entity);", "adherents/class/adherent.class.php:959|check|if (!getDolGlobalString(''ADHERENT_LOGIN_NOT_REQUIRED'')) {", "partnership/partnership_list.php:536|check|if (!getDolGlobalString(''ADHERENT_LOGIN_NOT_REQUIRED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_MAILMAN_ADMIN_PASSWORD', 'string', NULL, 'mailmanspip', 'Stores the Mailman list administrator password used when calling the Mailman HTTP API to manage mailing-list subscriptions from the legacy mailmanspip module.', 'In mailmanspip/class/mailmanspip.class.php:159, the value of getDolGlobalString(''ADHERENT_MAILMAN_ADMIN_PASSWORD'') is substituted for the ''%MAILMAN_ADMINPW%'' placeholder in the Mailman call URL template before invoking callMailman().', 'Setting it provides the credential required for the module''s curl-based calls to the Mailman admin interface to succeed (add/remove subscribers); an incorrect value would cause those Mailman API calls to fail.', 'String password value substituted into a URL template.', 1, 0, NULL, 1, 'a44489be1f08ece9f1834fe853f33e7431df95284002761a30da11e3da36c07a', 'v2', '2026-07-24T07:05:23+00:00', '["mailmanspip/class/mailmanspip.class.php:159: getDolGlobalString(''ADHERENT_MAILMAN_ADMIN_PASSWORD'')", "mailmanspip/class/mailmanspip.class.php: ''%MAILMAN_ADMINPW%''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_MAILMAN_LISTS', 'string', NULL, 'mailmanspip', 'Comma-separated list of Mailman mailing lists to subscribe/unsubscribe members to, with optional TYPE: or CATEG: filters.', 'Used in mailmanspip/class/mailmanspip.class.php at lines 330-331 and 400-401 to determine which lists to process. The comment at line 339 documents the format.', 'If empty, no default lists are processed; only explicitly passed lists are used. The format allows filtering by member type or category.', 'Comma-separated list: "mailinglist0,TYPE:typevalue:mailinglist1,CATEG:categvalue:mailinglist2"', 1, 0, NULL, 1, '313e1d2b0583a6aa1fc24ecb9ba9a4dedef7b18c7550e5c413ad42b423b79700', 'v2', '2026-04-21T11:16:15+00:00', '["// Filter on type something (ADHERENT_MAILMAN_LISTS = \"mailinglist0,TYPE:typevalue:mailinglist1,CATEG:categvalue:mailinglist2\")", "mailmanspip/class/mailmanspip.class.php:330|check|if ($listes == '''' && getDolGlobalString(''ADHERENT_MAILMAN_LISTS'')) {", "mailmanspip/class/mailmanspip.class.php:331|read|$lists = explode('','', getDolGlobalString(''ADHERENT_MAILMAN_LISTS''));", "mailmanspip/class/mailmanspip.class.php:401|read|$lists = explode('','', getDolGlobalString(''ADHERENT_MAILMAN_LISTS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_MAILMAN_UNSUB_URL', 'string', NULL, 'mailmanspip', 'URL template used to unsubscribe a member''s email from Mailman mailing lists.', 'Used in mailmanspip/class/mailmanspip.class.php:399-424 when the member module is enabled to call Mailman''s unsubscribe endpoint for each list; if unset, the module sets an error ''ADHERENT_MAILMAN_UNSUB_URL not defined''. Default value is registered by the module descriptor core/modules/modMailmanSpip.class.php:75.', 'If left empty, member unsubscription synchronization with Mailman fails with an explicit error instead of silently skipping.', 'URL template with placeholders, e.g. ''http://lists.example.com/cgi-bin/mailman/admin/%LISTE%/members?adminpw=%MAILMAN_ADMINPW%&user=%EMAIL%'' (module default).', 0, 0, NULL, 1, 'e28036b6f754d2ee1583a900e65df73e55b9e289b77887c4b7642f8c661125ea', 'v2', '2026-07-24T07:05:23+00:00', '["mailmanspip/class/mailmanspip.class.php:399: if (getDolGlobalString(''ADHERENT_MAILMAN_UNSUB_URL'')) {", "mailmanspip/class/mailmanspip.class.php:435: $this->error = \"ADHERENT_MAILMAN_UNSUB_URL not defined\";", "core/modules/modMailmanSpip.class.php:75: array(\"ADHERENT_MAILMAN_UNSUB_URL\", \"chaine\", \"http://lists.example.com/cgi-bin/mailman/admin/%LISTE%/members?adminpw=%MAILMAN_ADMINPW%&user=%EMAIL%\", \"Url de d\\u00e9sinscription aux listes mailman\")"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_MAILMAN_URL', 'string', NULL, 'mailmanspip', 'Base URL of the Mailman instance used by the legacy mailmanspip module to subscribe/unsubscribe members to mailing lists.', 'In mailmanspip/class/mailmanspip.class.php:329, member synchronization only runs if getDolGlobalString(''ADHERENT_MAILMAN_URL'') is set; the raw value $conf->global->ADHERENT_MAILMAN_URL is then passed directly to callMailman($object, $conf->global->ADHERENT_MAILMAN_URL, $list) at line 354 to build the actual HTTP call.', 'Setting it enables and targets the Mailman synchronization feature for members/mailing lists; if unset, the whole member-to-Mailman synchronization block is skipped.', 'String URL of the Mailman server/CGI endpoint, used as a base for building the actual curl request URL.', 1, 0, NULL, 1, '521377cb6dd907df40620b806b828ee5c1015a0f84698db36c2ab4ea243445dd', 'v2', '2026-07-24T07:05:23+00:00', '["mailmanspip/class/mailmanspip.class.php:329: if (getDolGlobalString(''ADHERENT_MAILMAN_URL'')) {", "mailmanspip/class/mailmanspip.class.php:354: $result = $this->callMailman($object, $conf->global->ADHERENT_MAILMAN_URL, $list);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_MAIL_FROM', 'string', NULL, 'adherents', 'Overrides the ''from'' email address used for emails sent to members, falling back to $conf->email_from.', 'Read across 10 occurrences including adherents/class/adherent.class.php:508,3336, public/members/new.php:548, and adherents/card.php:1715,1718,1779,1782,1840, all using getDolGlobalString(''ADHERENT_MAIL_FROM'', $conf->email_from).', 'Setting it changes the sender address used for member-related emails instead of the global $conf->email_from default.', NULL, 0, 0, NULL, 1, 'da0d87f07864c4c510668f7d6d8ae1a38f1da02dd6359f7833976c3d5241d1a5', 'v2', '2026-07-24T06:41:12+00:00', '["$email_from = getDolGlobalString(''ADHERENT_MAIL_FROM'', $conf->email_from);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_MAIL_REQUIRED', 'string', NULL, 'adherents', 'Makes the email address field mandatory when creating or validating a member record.', 'When set, member creation and validation logic in adherents/class/adherent.class.php rejects records with an invalid or missing email. The email field is rendered with a required indicator in adherents/card.php and public/members/new.php. Configured via adherents/admin/member.php.', 'Enabling this enforces a valid email for all members. Disabling it makes email optional during member creation and subscription.', 'Truthy = email required and validated; empty/falsy = email optional', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'bb37755dee3f8bedf582e6a9c80add8418e9f3eda46e781f90e931f54b0dd11e', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/class/adherent.class.php:673|check|if (getDolGlobalString(''ADHERENT_MAIL_REQUIRED'') && !isValidEmail((string) $this->email)) {", "adherents/admin/member.php:176|write|$res2 = dolibarr_set_const($db, ''ADHERENT_MAIL_REQUIRED'', GETPOST(''ADHERENT_MAIL_REQUIRED'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "adherents/card.php:1215|read|print ''<tr><td>''.(getDolGlobalString(''ADHERENT_MAIL_REQUIRED'') ? ''<span class=\"fieldrequired\">'' : '''')...", "public/members/new.php:872|read|print ''<tr><td>''.(getDolGlobalString(''ADHERENT_MAIL_REQUIRED'') ? ''<span class=\"fieldrequired\">'' : '''')..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_PRODUCT_ID_FOR_SUBSCRIPTIONS', 'string', NULL, 'adherents', 'Specifies the product or service ID to use when creating an invoice line for a member subscription.', 'When set and the product or service module is enabled, a product line is automatically created on the subscription invoice using the product identified by this ID. Configured via adherents/admin/member.php.', 'Setting this causes subscription invoices to include a line for the specified product. Removing it disables automatic product line creation on subscription invoices.', 'Product/service rowid integer as a string; empty = no product linked to subscriptions', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php|adherents/admin/member.php', 1, '2d0df348ea23a5bcbd35949916cd890c84ab5493b9804c969122e0ca66fd4399', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/class/adherent.class.php:2067|check|if (getDolGlobalString(''ADHERENT_PRODUCT_ID_FOR_SUBSCRIPTIONS'') && (isModEnabled(\"product\") || isModEnabled(\"service\"))) {", "adherents/class/adherent.class.php:2068|read|$idprodsubscription = getDolGlobalString(''ADHERENT_PRODUCT_ID_FOR_SUBSCRIPTIONS'');", "adherents/subscription.php:1076|read|$result = $prodtmp->fetch(getDolGlobalInt(''ADHERENT_PRODUCT_ID_FOR_SUBSCRIPTIONS''));", "adherents/admin/member.php:188|write|$res5 = dolibarr_set_const($db, ''ADHERENT_PRODUCT_ID_FOR_SUBSCRIPTIONS'', GETPOST(''ADHERENT_PRODUCT_ID_FOR_SUBSCRIPTIONS'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_SPIP_DB', 'string', NULL, 'mailmanspip', 'Name of the MySQL database used by the SPIP CMS for member synchronization.', 'Used exclusively in mailmanspip/class/mailmanspip.class.php (lines 110, 124, 130) to open and log connections to the SPIP MySQL database. No admin UI writes this constant.', 'An incorrect database name will cause the SPIP connection to fail.', 'String: MySQL database name for the SPIP installation.', 1, 0, NULL, 1, '8c9807a116a2f0221c8f611f149ff45cbeb6aea3ce79ee43d62a655d0a7749f8', 'v2', '2026-04-21T11:16:15+00:00', '["mailmanspip/class/mailmanspip.class.php:110|check|if (getDolGlobalString(''ADHERENT_SPIP_SERVEUR'') != '''' && getDolGlobalString(''ADHERENT_SPIP_USER'') != '''' && getDolGlobalString(''ADHERENT_SPIP_PASS'') != '''' && getDolGlobalString(''ADH...", "mailmanspip/class/mailmanspip.class.php:124|read|$resource = getDoliDBInstance(''mysql'', getDolGlobalString(''ADHERENT_SPIP_SERVEUR''), getDolGlobalString(''ADHERENT_SPIP_USER''), getDolGlobalString(''ADHERENT_SPIP_PASS''), getDolGlobal...", "mailmanspip/class/mailmanspip.class.php:130|read|dol_syslog(''Error when connecting to SPIP ''.getDolGlobalString(''ADHERENT_SPIP_SERVEUR'')..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_SPIP_PASS', 'string', NULL, 'mailmanspip', 'MySQL password used to authenticate the connection to the SPIP database.', 'Used exclusively in mailmanspip/class/mailmanspip.class.php to open a database connection (line 124) and to log errors (line 130). No admin UI writes this constant.', 'An incorrect password will cause the SPIP database connection to fail and an error will be logged.', 'String: MySQL password for the SPIP database.', 1, 0, NULL, 1, 'e86ede3a77c66e87674249032e0d8662af45bb6658df3c2ea3e0e07705792792', 'v2', '2026-04-21T11:16:15+00:00', '["mailmanspip/class/mailmanspip.class.php:110|check|if (... && getDolGlobalString(''ADHERENT_SPIP_PASS'') != '''' ...", "mailmanspip/class/mailmanspip.class.php:124|read|$resource = getDoliDBInstance(''mysql'', getDolGlobalString(''ADHERENT_SPIP_SERVEUR''), getDolGlobalString(''ADHERENT_SPIP_USER''), getDolGlobalString(''ADHERENT_SPIP_PASS''), ...", "mailmanspip/class/mailmanspip.class.php:130|read|dol_syslog(''Error when connecting to SPIP ''.getDolGlobalString(''ADHERENT_SPIP_SERVEUR'').'' ''.getDolGlobalString(''ADHERENT_SPIP_USER'').'' ''.getDolGlobalString(''ADHERENT_SPIP_PASS'')..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_SPIP_PORT', 'string', NULL, 'mailmanspip', 'Sets the TCP port used to connect to the external SPIP MySQL database for the legacy mailmanspip member-synchronization module.', 'In mailmanspip/class/mailmanspip.class.php:124, connectSpip() calls getDoliDBInstance(''mysql'', getDolGlobalString(''ADHERENT_SPIP_SERVEUR''), getDolGlobalString(''ADHERENT_SPIP_USER''), getDolGlobalString(''ADHERENT_SPIP_PASS''), getDolGlobalString(''ADHERENT_SPIP_DB''), getDolGlobalInt(''ADHERENT_SPIP_PORT'')), using this constant as the DB connection port alongside the related ADHERENT_SPIP_SERVEUR/USER/PASS/DB constants.', 'Setting it (together with the other ADHERENT_SPIP_* constants) determines which external MySQL server/port the mailmanspip module connects to for SPIP synchronization; incorrect value breaks the connectSpip() call.', 'Integer TCP port number for a MySQL connection.', 1, 0, NULL, 1, 'ac8dc42032cb3dfb7ccbf02a0cfa811f183d2239954909759145bcdabca87e9a', 'v2', '2026-07-24T07:05:23+00:00', '["mailmanspip/class/mailmanspip.class.php:124: $resource = getDoliDBInstance(''mysql'', getDolGlobalString(''ADHERENT_SPIP_SERVEUR''), getDolGlobalString(''ADHERENT_SPIP_USER''), getDolGlobalString(''ADHERENT_SPIP_PASS''), getDolGlobalString(''ADHERENT_SPIP_DB''), getDolGlobalInt(''ADHERENT_SPIP_PORT''))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_SPIP_SERVEUR', 'string', NULL, 'mailmanspip', 'Hostname or IP of the MySQL server hosting the SPIP database for member synchronization.', 'Used exclusively in mailmanspip/class/mailmanspip.class.php to open a database connection (line 124) and to log connection errors (line 130). No admin UI writes this constant; it must be set directly in the database.', 'If incorrect, the connection to the SPIP MySQL server will fail and an error will be logged via dol_syslog.', 'String: hostname or IP address of the SPIP MySQL server.', 1, 0, NULL, 1, 'aad4ee437747c1b8ab559e6ad85c7555ab7c7834c32b5f96843b85cec401eaa6', 'v2', '2026-04-21T11:16:15+00:00', '["mailmanspip/class/mailmanspip.class.php:110|check|if (getDolGlobalString(''ADHERENT_SPIP_SERVEUR'') != '''' && getDolGlobalString(''ADHERENT_SPIP_USER'') != '''' ...", "mailmanspip/class/mailmanspip.class.php:124|read|$resource = getDoliDBInstance(''mysql'', getDolGlobalString(''ADHERENT_SPIP_SERVEUR''), getDolGlobalString(''ADHERENT_SPIP_USER''), ...", "mailmanspip/class/mailmanspip.class.php:130|read|dol_syslog(''Error when connecting to SPIP ''.getDolGlobalString(''ADHERENT_SPIP_SERVEUR'')..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_SPIP_USER', 'string', NULL, 'mailmanspip', 'MySQL username used to authenticate the connection to the SPIP database.', 'Used exclusively in mailmanspip/class/mailmanspip.class.php to open a database connection (line 124) and to log errors (line 130). No admin UI writes this constant.', 'An incorrect username will cause the SPIP database connection to fail and an error will be logged.', 'String: MySQL username for the SPIP database.', 1, 0, NULL, 1, 'c5ec38e65d7c646c613157f9cb81a5b55143d1be3d273277741ee1b92dce95f7', 'v2', '2026-04-21T11:16:15+00:00', '["mailmanspip/class/mailmanspip.class.php:110|check|if (... && getDolGlobalString(''ADHERENT_SPIP_USER'') != '''' ...", "mailmanspip/class/mailmanspip.class.php:124|read|$resource = getDoliDBInstance(''mysql'', getDolGlobalString(''ADHERENT_SPIP_SERVEUR''), getDolGlobalString(''ADHERENT_SPIP_USER''), ...", "mailmanspip/class/mailmanspip.class.php:130|read|dol_syslog(''Error when connecting to SPIP ''.getDolGlobalString(''ADHERENT_SPIP_SERVEUR'').'' ''.getDolGlobalString(''ADHERENT_SPIP_USER'')..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_SUBSCRIPTION_ACCOUNTINGACCOUNT', 'string', NULL, 'accountancy', 'Stores the general ledger account number used for member subscription payment entries in accounting journals.', 'Read in accountancy/journal/bankjournal.php:275 and :1462, and in accountancy/journal/treasuryjournal.php:1000 with ''NotDefined'' as reserved-word fallback. No admin UI write found; HIDDEN_GUESS is 1.', 'If not set, member subscription payment lines in the bank and treasury journals use ''NotDefined'' as the account, which will cause posting errors.', 'String: general ledger account number; empty = not configured', 1, 0, NULL, 1, '6eddac366ec4888662532ae55cb340bf31d81922b201647ea0b6f52aeae528e5', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/bankjournal.php:275|read|$account_pay_subscription = getDolGlobalString(''ADHERENT_SUBSCRIPTION_ACCOUNTINGACCOUNT'', ''NotDefined''); // NotDefined is a reserved word", "accountancy/journal/bankjournal.php:1462|read|$account_ledger = getDolGlobalString(''ADHERENT_SUBSCRIPTION_ACCOUNTINGACCOUNT'');", "accountancy/journal/treasuryjournal.php:1000|read|$account_subscription = getDolGlobalString(''ADHERENT_SUBSCRIPTION_ACCOUNTINGACCOUNT'', ''NotDefined''); // NotDefined is a reserved word"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_SUBSCRIPTION_HIDECOMPLEMENTARYACTIONS', 'bool', NULL, 'adherents', 'Hides the ''complementary actions'' block (bank entry / invoice creation options) on the member subscription form.', 'Used in adherents/subscription.php:1066: the ''MoreActions'' block (radio choices for none / bankdirect / invoiceonly / bankviainvoice) is shown only if (bank or invoice module enabled) AND this constant is NOT set.', 'Enabling it removes the complementary-actions radio-button section from the subscription form even when the bank or invoice module is active, so users cannot choose to auto-create a bank entry or invoice from that form.', 'Boolean-like: truthy hides the MoreActions (complementary actions) block on the subscription form.', 0, 0, NULL, 1, '4a06527b7ffe915f8328c6293c869a85e423de4b51e0c4ea39af9ba836d1e713', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/subscription.php:1066|check|if ((isModEnabled(''bank'') || isModEnabled(''invoice'')) && !getDolGlobalString(''ADHERENT_SUBSCRIPTION_HIDECOMPLEMENTARYACTIONS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_USE_MAILMAN', 'bool', NULL, 'adherents', 'Enables Mailman mailing list synchronization for member subscription and unsubscription events.', 'When set and the mailman/mailmanspip module is enabled, member subscribe/unsubscribe actions trigger Mailman list synchronization calls. Configured via admin/mailman.php.', 'Enabling this causes member events (subscribe, unsubscribe) to be forwarded to configured Mailman lists. Disabling it suppresses Mailman integration entirely.', 'Truthy = Mailman synchronization enabled; empty/falsy = disabled', 0, 0, 'admin/mailman.php|admin/mailman.php|admin/mailman.php', 1, 'b369428ed21dc82d14d8bf8deafee06bea7153ff02901daa04fc6a9323f3a937', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/class/adherent.class.php:2348|check|if (getDolGlobalString(''ADHERENT_USE_MAILMAN'') && isModEnabled(''mailmanspip'')) {", "admin/mailman.php:106|check|if (($action == ''testsubscribe'' || $action == ''testunsubscribe'') && getDolGlobalString(''ADHERENT_USE_MAILMAN'')) {", "adherents/class/adherent.class.php:2400|check|if (getDolGlobalString(''ADHERENT_USE_MAILMAN'')) {", "adherents/card.php:1733|check|if (isModEnabled(''mailman'') && getDolGlobalString(''ADHERENT_USE_MAILMAN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_USE_SPIP', 'bool', NULL, 'adherents', 'Enables integration between the Members (adherents) module and the SPIP CMS/Mailman system.', 'Configured via admin/spip.php. When enabled, member card actions and the adherent class trigger synchronization with the Mailman/SPIP subsystem (adherents/class/adherent.class.php lines 2368 and 2419, adherents/card.php lines 1736 and 2191).', 'When set, member subscription and unsubscription events trigger calls into the mailmanspip module, propagating changes to external mailing-list or SPIP services.', 'Truthy (non-empty) value enables the integration; empty/unset disables it.', 0, 0, 'admin/spip.php', 1, '870562c0be5929091580e99addf71918485e67795b43d0ed245a0aae617c3e22', 'v2', '2026-04-21T11:16:15+00:00', '["admin/spip.php:128|check|if (getDolGlobalString(''ADHERENT_USE_SPIP'')) {", "adherents/class/adherent.class.php:2368|check|if (getDolGlobalString(''ADHERENT_USE_SPIP'') && isModEnabled(''mailmanspip'')) {", "adherents/card.php:2191|check|if (isModEnabled(''mailmanspip'') && getDolGlobalString(''ADHERENT_USE_SPIP'')) {", "mailmanspip/class/mailmanspip.class.php:96|check|if (getDolGlobalInt(\"ADHERENT_USE_SPIP\") == 1) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ADHERENT_VAT_FOR_SUBSCRIPTIONS', 'string', NULL, 'adherents', 'Controls whether VAT is applied to member subscription invoices and which VAT rate is used.', 'When set to ''defaultforfoundationcountry'', VAT is applied using the default rate for the foundation''s country. Any other value (including empty or ''0'') results in no VAT on subscriptions. Configured via adherents/admin/member.php.', 'Setting this to ''defaultforfoundationcountry'' adds VAT to subscription invoice lines. Any other value suppresses VAT on subscriptions.', '''0'' = NoVatOnSubscription; ''defaultforfoundationcountry'' = use default VAT for foundation country', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, '539fa85f3ba6eee7079d6447942ca60ccd451c004e28cab00d10f41642e537bb', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/class/adherent.class.php:2072|check|if (getDolGlobalString(''ADHERENT_VAT_FOR_SUBSCRIPTIONS'') == ''defaultforfoundationcountry'') {", "adherents/subscription.php:1071|check|if (!getDolGlobalString(''ADHERENT_VAT_FOR_SUBSCRIPTIONS'') || getDolGlobalString(''ADHERENT_VAT_FOR_SUBSCRIPTIONS'') != ''defaultforfoundationcountry'') {", "adherents/admin/member.php:649|read|print $form->selectarray(''ADHERENT_VAT_FOR_SUBSCRIPTIONS'', array(''0'' => $langs->trans(\"NoVatOnSubscription\"), ''defaultforfoundationcountry'' => $langs->trans(\"Default\")), ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_ADDACTIONFOREMAIL', 'string', NULL, 'core', 'Enables automatic creation of an agenda action event when an email is sent from Dolibarr.', 'Checked in core/lib/functions.lib.php:4500; a commented-out example at line 4454 shows how to set it. The function parameter doc at line 4443 describes its role: ''link to create action if constant AGENDA_ADDACTIONFOREMAIL is on''.', 'When set, sending an email from a presend form triggers an agenda event to be created. Without it, no agenda entry is created.', 'email has a html email link (+ link to create action if constant AGENDA_ADDACTIONFOREMAIL is on). Non-empty = create agenda action on email send; absent/empty = no agenda entry.', 1, 0, NULL, 1, 'd92a804753b973117ee30c1a3e6bf9d9bfa4fa06f191dcb0e9d2c49fe49b3b14', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:4443  * @param \tint|string\t$addlink\t\t0=no link, 1=email has a html email link (+ link to create action if constant AGENDA_ADDACTIONFOREMAIL is on), ''thirdparty''=link to the thirdparty presend email", "core/lib/functions.lib.php:4454  //global $conf; $conf->global->AGENDA_ADDACTIONFOREMAIL = 1;", "core/lib/functions.lib.php:4500|check|if (getDolGlobalString(''AGENDA_ADDACTIONFOREMAIL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_ADDACTIONFORPHONE', 'string', NULL, 'core', 'Enables a link to create an agenda event when a phone number is clicked via the Click-to-Dial or phone link mechanism.', 'Checked in core/lib/functions.lib.php:5109. The function parameter doc at line 4827 describes its role: ''add link to create event (if conf->global->AGENDA_ADDACTIONFORPHONE set)''. No admin UI write detected.', 'When set, phone number display includes a link to create an agenda event. Without it, no agenda entry link is shown alongside phone numbers.', '''AC_TEL''=add link to clicktodial (if module enabled) and add link to create event (if conf->global->AGENDA_ADDACTIONFORPHONE set). Non-empty = show agenda event link; absent/empty = no link.', 1, 0, NULL, 1, '7f3ae74f953c68b29afe7b300f4752dc4b9ce51990af1c98003bb8ff795aed32', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:4827  * \t@param \tstring\t$addlink\t    ''''=no link to create action, ''AC_TEL''=add link to clicktodial (if module enabled) and add link to create event (if conf->global->AGENDA_ADDACTIONFORPHONE set), ''tel''=Force \"tel:...\" link", "core/lib/functions.lib.php:5109|check|if (getDolGlobalString(''AGENDA_ADDACTIONFORPHONE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_ADDACTIONFORSKYPE', 'string', NULL, 'core', 'Shows an ''Add action'' (agenda event) link next to Skype call/chat buttons on a Skype social-network field.', 'In core/lib/functions.lib.php:4698, when rendering a Skype contact value with call/chat buttons, if the user has agenda create rights and this constant is set, a link to create an agenda action (actioncode AC_SKYPE) is appended.', 'Enabling it adds a quick-create-agenda-event link next to Skype contact buttons for users with ''create action'' rights.', 'Boolean-like: any truthy value shows the add-to-agenda link for Skype contacts.', 1, 0, NULL, 1, '4dc467e64af590aba2ee857d05fa9f9043aaf9cff329b283e3dcd033efd707ff', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:4698|check|if (getDolGlobalString(''AGENDA_ADDACTIONFORSKYPE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_ALL_CALENDARS', 'string', NULL, 'comm', 'Controls whether the agenda defaults to showing all calendars without a filter type restriction.', 'Checked in comm/action/pertype.php:63, comm/action/list.php:133, and comm/action/index.php:72 to skip defaulting the filter type when no explicit filter is set.', 'Enabling this constant causes all event types to be displayed by default on agenda views without pre-filtering by type.', 'Truthy value = all calendars shown by default; empty/unset = default filter type applied.', 1, 0, NULL, 1, 'aed268653da1afeffedd60c623d7dc6046061f3985fd895096d45a3e356eda2b', 'v2', '2026-04-21T11:16:15+00:00', '["comm/action/pertype.php:63|check|if (empty($filtert) && !getDolGlobalString(''AGENDA_ALL_CALENDARS'')) {", "comm/action/list.php:133|check|if (empty($filtert) && !getDolGlobalString(''AGENDA_ALL_CALENDARS'')) {", "comm/action/index.php:72|check|if (empty($filtert) && !getDolGlobalString(''AGENDA_ALL_CALENDARS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_ALWAYS_HIDE_AUTO', 'bool', NULL, 'comm', 'Hides automatically-generated agenda events (type ''AC_OTH_AUTO'') from all agenda views.', 'Checked in comm/action/pertype.php:700, comm/action/peruser.php:877, comm/action/list.php:1030, comm/action/index.php:948, and core/class/html.formactions.class.php:398; skips rendering when the event type code is ''AC_OTH_AUTO''.', 'Enabling this constant removes auto-generated events from display in all agenda views and event type selector lists.', 'Truthy value = auto events hidden; empty/unset = auto events visible.', 1, 0, NULL, 1, 'a923ed258dc22342ba4c9b0c2640b926cae3cc9362a92d628bb354ed883bdb4a', 'v2', '2026-04-21T11:16:15+00:00', '["comm/action/pertype.php:700|check|if (getDolGlobalString(''AGENDA_ALWAYS_HIDE_AUTO'') && $obj->type_code == ''AC_OTH_AUTO'') {", "comm/action/peruser.php:877|check|if (getDolGlobalString(''AGENDA_ALWAYS_HIDE_AUTO'') && $obj->type_code == ''AC_OTH_AUTO'') {", "comm/action/list.php:1030|check|if (getDolGlobalString(''AGENDA_ALWAYS_HIDE_AUTO'') && $obj->type_code == ''AC_OTH_AUTO'') {", "core/class/html.formactions.class.php:398|check|if (array_key_exists(''AC_OTH_AUTO'', $arraylist) && getDolGlobalString(''AGENDA_ALWAYS_HIDE_AUTO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_AUTOSET_END_DATE_WITH_DELTA_HOURS', 'string', NULL, 'comm', 'Number of hours added to an event''s start date/time to auto-compute its end date when no end date was provided.', 'Read in comm/action/card.php:1546 as the delta passed to dol_time_plus_duree($datep, ..., ''h''), only when no $datef was given and (action code is AC_RDV, or AGENDA_USE_EVENT_TYPE_DEFAULT is unset/''-1''); default value used is 1 if not set.', 'Increasing the value makes newly created agenda events (without an explicit end date) last longer by default; decreasing it shortens the auto-computed duration.', 'Integer number of hours; default fallback is 1 (per the getDolGlobalInt(''...'', 1) call).', 1, 0, NULL, 1, '1b31c72a484864e2d1c07553216f3d779e0790cddac57eb9a6d6b50de234a55a', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/card.php:1546|read|$datef = dol_time_plus_duree($datep, getDolGlobalInt(''AGENDA_AUTOSET_END_DATE_WITH_DELTA_HOURS'', 1), ''h'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_BEGIN_TIME', 'string', NULL, 'comm', 'Default start time (HHMMSS) prefilled when creating a new agenda event from the day view.', 'Read in comm/action/index.php:1966; if empty or not matching the 6-digit pattern /^[0-9]{6}$/, it falls back to ''100000'' (10:00:00), and the value is appended to the create-event URL''s datep parameter.', 'Setting a valid 6-digit HHMMSS string changes the pre-filled start time for events created via the ''create'' link in the agenda day view; an invalid/empty value silently falls back to 10:00:00.', 'String: 6 digits HHMMSS (e.g. ''090000'' for 9:00:00); invalid or empty values default to ''100000''.', 1, 0, NULL, 1, '0f52b150b8f73ad300627c96f12244952b58d79443ef290a2f1ceebad8976d35', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/index.php:1966|read|$hourminsec = getDolGlobalString(''AGENDA_DEFAULT_BEGIN_TIME''); if (empty($hourminsec) || !preg_match(''/^[0-9]{6}$/'', $hourminsec)) { $hourminsec = ''100000''; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_FILTER_STATUS', 'string', NULL, 'comm', 'Sets the default event status filter applied to agenda views.', 'Written in admin/agenda_other.php:99 and admin/agenda_reminder.php:89; read in comm/action/pertype.php:158, comm/action/peruser.php:163, comm/action/list.php:110, and comm/action/index.php:149 to pre-select the status filter.', 'Changing this constant alters which event status is pre-selected as the default filter across all agenda listing views.', 'String status code; empty/unset = no default status filter.', 0, 0, 'admin/agenda_other.php|admin/agenda_other.php|admin/agenda_reminder.php', 1, '1e5623e7e51cc95f86a596828fe63e3e1198187e958008d6409557d0a79cfea1', 'v2', '2026-04-21T11:16:15+00:00', '["admin/agenda_other.php:99|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_FILTER_STATUS'', GETPOST(''AGENDA_DEFAULT_FILTER_STATUS''), ''chaine'', 0, '''', $conf->entity);", "admin/agenda_reminder.php:89|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_FILTER_STATUS'', GETPOST(''AGENDA_DEFAULT_FILTER_STATUS''), ''chaine'', 0, '''', $conf->entity);", "comm/action/pertype.php:158|read|$status = ((!getDolGlobalString(''AGENDA_DEFAULT_FILTER_STATUS'') || $disabledefaultvalues) ? '''' : getDolGlobalString(''AGENDA_DEFAULT_FILTER_STATUS''));", "comm/action/list.php:110|read|$search_status = ((!getDolGlobalString(''AGENDA_DEFAULT_FILTER_STATUS'') || $disabledefaultvalues) ? '''' : $conf->global->AGENDA_DEFAULT_FILTER_STATUS);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_FILTER_TYPE', 'string', NULL, 'comm', 'Sets the default event type filter applied to agenda views.', 'Written in admin/agenda_other.php:98 and admin/agenda_reminder.php:88; read in comm/action views to pre-select the action type filter. A commented module default of ''AC_NON_AUTO'' is noted in core/modules/modAgenda.class.php:93.', 'Changing this constant alters which event type is pre-selected as the default filter on all agenda listing views.', 'String action code (e.g. ''AC_NON_AUTO''); empty/unset = no default type filter.', 0, 0, 'admin/agenda_other.php|admin/agenda_other.php|admin/agenda_reminder.php', 1, 'e2e5db32f2e5eb3238b77eb3be8b2301fa1629e55d9d8f30db63f4a11e998a8c', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/modAgenda.class.php:93  // $this->const[] = array(''AGENDA_DEFAULT_FILTER_TYPE'', ''chaine'', ''AC_NON_AUTO'', ''Default filter for type of event on agenda'', 0, ''current'');", "admin/agenda_other.php:98|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_FILTER_TYPE'', $defaultfilter, ''chaine'', 0, '''', $conf->entity);", "admin/agenda_reminder.php:88|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_FILTER_TYPE'', GETPOST(''AGENDA_DEFAULT_FILTER_TYPE''), ''chaine'', 0, '''', $conf->entity);", "admin/agenda_other.php:413|read|print $formactions->select_type_actions(getDolGlobalString(''AGENDA_DEFAULT_FILTER_TYPE''), \"AGENDA_DEFAULT_FILTER_TYPE\", '''', (getDolGlobalString(''AGENDA_USE_EVENT_TYPE'') ? -1 : 1),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_FILTER_TYPE_FOR_OBJECT', 'string', NULL, 'hrm', 'Sets the default event/action type filter pre-selected on agenda tabs of object detail pages.', 'Read in 52 locations across object agenda pages (e.g. asset/model/agenda.php:58, partnership/partnership_agenda.php:61, projet/agenda.php:72) as the fallback value for the ''actioncode'' filter when no POST parameter is provided.', 'Setting this constant pre-filters the agenda tab by a specific action code on every object detail page that displays an agenda; clearing it shows all event types by default.', 'Action code string (e.g. ''AC_TEL''); empty string or unset = no type filter applied.', 1, 0, NULL, 1, '42ba93bc732a589b912f55bd0c4094ff49650500a45b3c10f4d8854df57f061f', 'v2', '2026-04-21T11:16:15+00:00', '["asset/model/agenda.php:58|read|$actioncode = GETPOST(\"actioncode\", \"alpha\", 3) ? GETPOST(\"actioncode\", \"alpha\", 3) : (GETPOST(\"actioncode\") == ''0'' ? ''0'' : getDolGlobalString(''AGENDA_DEFAULT_FILTER_TYPE_FOR_OBJEC", "partnership/partnership_agenda.php:61|read|$actioncode = GETPOST(\"actioncode\", \"alpha\", 3) ? GETPOST(\"actioncode\", \"alpha\", 3) : (GETPOST(\"actioncode\") == ''0'' ? ''0'' : getDolGlobalString(''AGENDA_DEFAULT_FILTER_TYPE_FOR_OBJEC", "compta/facture/messaging.php:60|read|$actioncode = GETPOST(\"actioncode\", \"alpha\", 3) ? GETPOST(\"actioncode\", \"alpha\", 3) : (GETPOST(\"actioncode\") == ''0'' ? ''0'' : getDolGlobalString(''AGENDA_DEFAULT_FILTER_TYPE_FOR_OBJEC"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_FILTER_TYPE_FOR_OBJECTS', 'string', NULL, 'fourn', 'Sets the default agenda event-type filter (actioncode) preselected on the supplier order events/agenda tab.', 'Used in fourn/commande/info.php:80 to preset $actioncode when the user has not chosen an actioncode filter via GET. Only this single call site was found in the source tree.', 'Changing it changes which agenda event type is preselected in the filter dropdown on the supplier order info/agenda tab; it does not restrict what can be selected.', 'String matching an agenda event type code (actioncode); empty/undefined means no default filter (shows '''').', 1, 0, NULL, 1, '769cc749ee5a1d0c301438588ff3d7816a8b072c8ae41b72938cf777a52baac8', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/info.php:80|read|$actioncode = ... : (!getDolGlobalString(''AGENDA_DEFAULT_FILTER_TYPE_FOR_OBJECTS'') ? '''' : $conf->global->AGENDA_DEFAULT_FILTER_TYPE_FOR_OBJECTS));"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_REMINDER_EMAIL_MODEL', 'string', NULL, 'comm', 'Stores the ID of the default email template used for agenda event reminders.', 'Written via admin/agenda_reminder.php:93 from the POST field ''AGENDA_DEFAULT_REMINDER_EMAIL_MODELmodel_mail''. Read in comm/action/card.php lines 1955 and 2576.', 'Changing this value changes which email template is pre-selected for reminders on new events.', 'Integer ID of an email template; 0 or unset = no default email template.', 0, 0, 'admin/agenda_reminder.php|admin/agenda_reminder.php', 1, 'e49ad6d1d90c29bba21a063c7bbe2d860fc0585b59dbbe6063e74c08e3675561', 'v2', '2026-04-21T13:29:58+00:00', '["admin/agenda_reminder.php:93|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_REMINDER_EMAIL_MODEL'', GETPOSTINT(''AGENDA_DEFAULT_REMINDER_EMAIL_MODELmodel_mail''), ''chaine'', 0, '''', $conf->entity);", "comm/action/card.php:1955|read|$reminderDefaultEmailModel = getDolGlobalInt(''AGENDA_DEFAULT_REMINDER_EMAIL_MODEL'');", "comm/action/card.php:2576|read|$reminderDefaultEmailModel = getDolGlobalString(''AGENDA_DEFAULT_REMINDER_EMAIL_MODEL'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_REMINDER_EVENT_TYPES', 'string', NULL, 'comm', 'Stores a JSON-encoded list of event type codes for which reminders are enabled by default.', 'Written by admin/agenda_reminder.php:94 as a JSON-encoded array and read back at line 289 via json_decode. Also read in comm/action/card.php lines 1952 and 2573 to pre-select reminder event types on new events.', 'Changing this value alters which event types automatically get a reminder pre-configured when creating a new event.', 'JSON-encoded array of event type code strings; empty/unset = no default reminder event types.', 0, 0, 'admin/agenda_reminder.php|admin/agenda_reminder.php', 1, '7a578ce09de99426e963c45d809de13f6a2a9b370b85d1d9585ebb579c3e4d46', 'v2', '2026-04-21T13:29:58+00:00', '["admin/agenda_reminder.php:94|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_REMINDER_EVENT_TYPES'', json_encode(GETPOST(''AGENDA_DEFAULT_REMINDER_EVENT_TYPES'')), ''chaine'', 0, '''', $conf->entity);", "admin/agenda_reminder.php:289|read|$selected = json_decode(getDolGlobalString(''AGENDA_DEFAULT_REMINDER_EVENT_TYPES'', ''''));", "comm/action/card.php:1952|read|$reminderDefaultEventTypes = getDolGlobalString(''AGENDA_DEFAULT_REMINDER_EVENT_TYPES'', '''');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_REMINDER_OFFSET', 'string', NULL, 'comm', 'Sets the global default reminder offset (numeric value) applied to new agenda event reminders.', 'Written via admin/agenda_reminder.php:91 and read in comm/action/card.php lines 1953 and 2574 with a default of 30. This is the system-level default; AGENDA_REMINDER_DEFAULT_OFFSET is the per-session override.', 'Changing this value changes the pre-filled reminder offset for all new events globally; individual events can still override it.', 'Integer (default 30); unit determined by AGENDA_DEFAULT_REMINDER_OFFSET_UNIT.', 0, 0, 'admin/agenda_reminder.php|admin/agenda_reminder.php', 1, '06ed3e6f8af68c6c6e493bee55a26f98f4e9359cff83a93370cd207c58dabce9', 'v2', '2026-04-21T13:29:58+00:00', '["admin/agenda_reminder.php:91|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_REMINDER_OFFSET'', GETPOSTINT(''AGENDA_DEFAULT_REMINDER_OFFSET''), ''chaine'', 0, '''', $conf->entity);", "comm/action/card.php:1953|read|$reminderDefaultOffset = getDolGlobalInt(''AGENDA_DEFAULT_REMINDER_OFFSET'', 30);", "comm/action/card.php:2574|read|$reminderDefaultOffset = getDolGlobalString(''AGENDA_DEFAULT_REMINDER_OFFSET'', 30);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_REMINDER_OFFSET_UNIT', 'string', NULL, 'comm', 'Stores the time unit for the global default reminder offset (e.g. minutes, hours).', 'Written via admin/agenda_reminder.php:92 from the POST field ''AGENDA_DEFAULT_REMINDER_OFFSET_UNIT_type_duration''. Read in comm/action/card.php lines 1954 and 2575.', 'Changing this value changes the unit applied to the default reminder offset for all new events.', 'String time-unit identifier (e.g. ''m'' for minutes, ''h'' for hours); empty/unset = no default unit.', 0, 0, 'admin/agenda_reminder.php|admin/agenda_reminder.php', 1, 'b259812f32c117ff40f17e7b5d1a073f39c48e50d397e0089659ea4370794b1d', 'v2', '2026-04-21T13:29:58+00:00', '["admin/agenda_reminder.php:92|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_REMINDER_OFFSET_UNIT'', GETPOST(''AGENDA_DEFAULT_REMINDER_OFFSET_UNIT_type_duration''), ''chaine'', 0, '''', $conf->entity);", "comm/action/card.php:1954|read|$reminderDefaultUnit = getDolGlobalString(''AGENDA_DEFAULT_REMINDER_OFFSET_UNIT'');", "comm/action/card.php:2575|read|$reminderDefaultUnit = getDolGlobalString(''AGENDA_DEFAULT_REMINDER_OFFSET_UNIT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DEFAULT_VIEW', 'string', NULL, 'comm', 'Sets the default calendar view mode (e.g. month, list, per-user, per-type) on the agenda.', 'Written in admin/agenda_other.php:100 and admin/agenda_reminder.php:90; read in comm/action/index.php:152 (default ''show_month''), comm/action/list.php:113 (default ''show_list''), comm/action/pertype.php:161, and comm/action/peruser.php:167.', 'Changing this constant determines which calendar view is displayed by default when a user first opens the agenda.', 'String view name: ''show_month'', ''show_list'', ''show_pertype'', ''show_peruser'', or other supported view identifiers.', 0, 0, 'admin/agenda_other.php|admin/agenda_other.php|admin/agenda_reminder.php', 1, '9ccab6cb7e27a8ac545ff91dc9b40493a65c8a513b7d25c28319acae010a1e93', 'v2', '2026-04-21T11:16:15+00:00', '["admin/agenda_other.php:100|write|dolibarr_set_const($db, ''AGENDA_DEFAULT_VIEW'', GETPOST(''AGENDA_DEFAULT_VIEW''), ''chaine'', 0, '''', $conf->entity);", "comm/action/index.php:152|read|$defaultview = getDolGlobalString(''AGENDA_DEFAULT_VIEW'', ''show_month'');\t// default for app", "comm/action/list.php:113|read|$mode = getDolGlobalString(''AGENDA_DEFAULT_VIEW'', ''show_list'');", "user/param_ihm.php:452  // Landing page for Agenda - AGENDA_DEFAULT_VIEW"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DISABLE_BUILDDOC', 'bool', NULL, 'comm', 'Hides the ''generated documents'' block (attached files / build document) on the agenda event card.', 'Checked in comm/action/card.php:3061; when not set, the code prints the showdocuments() file/document block plus (nested) the linked-elements block for the event.', 'Setting it to true removes the entire generated-documents section from the agenda event view, including the nested linked-elements block gated by AGENDA_ENABLE_LINKED_ELEMENTS.', 'Boolean-like: true/1 hides the build-document block (inferred from negation in the if-condition).', 1, 0, NULL, 1, '0a3d9c9a690d7f171534d642c8d417a5852ed4d3a23a975d75719f06acca4896', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/card.php:3061|check|if (!getDolGlobalString(''AGENDA_DISABLE_BUILDDOC'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DISABLE_EXACT_USER_EMAIL_COMPARE_FOR_EXTERNAL_CALENDAR', 'bool', NULL, 'user', 'Switches the user lookup by e-mail (for external calendar sync) from an exact match to a partial LIKE match.', 'Documented in the docblock of User::findUserIdByEmail() (user/class/user.class.php:4418: ''Use AGENDA_DISABLE_EXACT_USER_EMAIL_COMPARE_FOR_EXTERNAL_CALENDAR to disable exact e-mail search'') and used at line 4434 to branch the SQL WHERE clause between `email LIKE ''%...%''` and `email = ''...''`.', 'When set, user-by-email lookups (used for matching external calendar attendees to Dolibarr users) use a substring LIKE match instead of an exact match, which can match more users but risks false positives.', 'Boolean: unset/false = exact e-mail match (WHERE email = ...); true = partial match (WHERE email LIKE ''%email%'').', 1, 0, NULL, 1, '48777059b34dff2694814de4036e3696b563478b07187c258b02842dc9fddfd8', 'v2', '2026-07-24T07:05:23+00:00', '["user/class/user.class.php:4418| * Use AGENDA_DISABLE_EXACT_USER_EMAIL_COMPARE_FOR_EXTERNAL_CALENDAR", "user/class/user.class.php:4418| * to disable exact e-mail search", "user/class/user.class.php:4434|check|if (getDolGlobalString(''AGENDA_DISABLE_EXACT_USER_EMAIL_COMPARE_FOR_EXTERNAL_CALENDAR'')) {", "user/class/user.class.php:4435|  $sql .= \" WHERE email LIKE ''%\".$this->db->escape(...).\"%''\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DISABLE_EXT', 'bool', NULL, 'admin', 'Global switch that disables all external agenda/calendar sites (ext-sites feature) configured in the Agenda module.', 'Set via admin/agenda_extsites.php:115 (dolibarr_set_const) from a form field posted as ''AGENDA_DISABLE_EXT''; only one occurrence found (the admin write), no read occurrence appears in this payload/search.', 'Presumably suppresses display/use of external agenda sites when enabled, but no read-side usage was found in the searched source to confirm exact effect [SPECULATION].', 'Value taken verbatim from GETPOST(''AGENDA_DISABLE_EXT'', ''alpha''); likely a boolean/flag string, exact accepted values not shown in code read.', 0, 0, 'admin/agenda_extsites.php', 1, '757150bf389f2d93dc1fabacaa5d7e46aac6c3e08aba98d755f61dfee772602c', 'v2', '2026-07-24T07:05:23+00:00', '["admin/agenda_extsites.php:115|write|$res = dolibarr_set_const($db, ''AGENDA_DISABLE_EXT'', $disableext, ''chaine'', 0, '''', $conf->entity);", "admin/agenda_extsites.php:114: $disableext = GETPOST(''AGENDA_DISABLE_EXT'', ''alpha'');"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_DISABLE_LOCATION', 'bool', NULL, 'comm', 'Disables the location field on agenda event forms and exports.', 'Checked in comm/action/card.php at lines 1639, 2266, 2733, 2783, comm/action/document.php:273, and resource/element_resource.php:477 to skip rendering or exporting the location field.', 'Enabling this constant hides the location field from agenda event create/edit forms and omits it from calendar exports.', 'Truthy value = location field disabled; empty/unset = location field shown.', 1, 0, NULL, 1, '5878186bd83ef54026ca2cfa9c87550c00e5e2e145a6c53c8dd7acfa8de5c4a9', 'v2', '2026-04-21T11:16:15+00:00', '["comm/action/document.php:273|check|if (!getDolGlobalString(''AGENDA_DISABLE_LOCATION'')) {", "resource/element_resource.php:477|check|if (!getDolGlobalString(''AGENDA_DISABLE_LOCATION'')) {", "comm/action/card.php:1639|check|if (!getDolGlobalString(''AGENDA_DISABLE_LOCATION'')) {", "comm/action/card.php:2266|check|if (!getDolGlobalString(''AGENDA_DISABLE_LOCATION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_ENABLE_LINKED_ELEMENTS', 'bool', NULL, 'comm', 'Shows a ''link to object'' block (linked elements) on the agenda event card.', 'Checked in comm/action/card.php:3074, nested inside the AGENDA_DISABLE_BUILDDOC block; when true, calls $form->showLinkToObjectBlock() to render UI for linking other objects to the event.', 'Setting it to true enables an additional UI section on the agenda event card allowing the user to link other Dolibarr objects to the event; it only appears if AGENDA_DISABLE_BUILDDOC is not also set.', 'Boolean-like: true/1 enables the linked-elements block.', 1, 0, NULL, 1, '10cb9c05a04efff265d70b2d0681d41f7a6134e1c7a60e142b6ac397381441db', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/card.php:3074|check|if (getDolGlobalString(''AGENDA_ENABLE_LINKED_ELEMENTS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_ENABLE_SHOW_BIRTHDAY_PER_USER', 'bool', NULL, 'comm', 'Enables showing user birthdays in the per-user agenda view.', 'In comm/action/peruser.php:62, an inline comment states ''disabled by default''; the value is read as an int flag controlling display of birthdays in the per-user calendar view.', 'Enabling it makes the per-user agenda view show birthday markers/events for users; disabled (default) hides them.', 'int/boolean: 0 or unset = disabled (default, per comment); 1 = birthdays shown per user.', 0, 0, NULL, 1, 'e7eee312d565b39f4209d08b99376438a8fc9480071fe22d96f910cd5be2ca20', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/peruser.php:62: $showbirthday = getDolGlobalInt(''AGENDA_ENABLE_SHOW_BIRTHDAY_PER_USER''); // disabled by default"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXPORT_FIX_TZ', 'string', NULL, 'comm', 'Applies a timezone-fix offset (in hours) to agenda/event dates when exporting to iCal/xCal.', 'Set via admin/agenda_xcal.php:83 (dolibarr_set_const) and read at agenda_xcal.php:58, then used in comm/action/class/actioncomm.class.php:2374,2378,2414,2415,2489,2490, each multiplying the value by 3600 to convert hours to seconds.', 'Changing the value shifts exported event start/end/created/modified timestamps by that many hours (value * 3600 seconds) in the xCal/iCal export.', 'Numeric hour offset, multiplied by 3600 to get seconds.', 0, 0, 'admin/agenda_xcal.php|admin/agenda_xcal.php', 1, '23e029d67b018b71e22a603865ce42137b763f038821945038f80c9380dfac53', 'v2', '2026-07-24T06:41:12+00:00', '["$datestart = (int) $this->db->jdate($obj->datep) - (getDolGlobalInt(''AGENDA_EXPORT_FIX_TZ'') * 3600);", "$AGENDA_EXPORT_FIX_TZ = getDolGlobalString(''AGENDA_EXPORT_FIX_TZ'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXT_CALENDAR_IP_MODE', 'string', NULL, 'comm', 'Controls the $localip parameter passed to getURLContent() when fetching external iCal calendar feeds.', 'Read in comm/action/class/ical.class.php:102-103 and cast with intval() before being passed as the $localip argument to getURLContent(), which the code comment says has documented possible values.', 'Changing the value alters how getURLContent() treats local/private IP addresses when fetching the external calendar URL (e.g. allowing or blocking requests to local network addresses), per getURLContent''s own semantics.', 'Integer, passed as getURLContent()''s $localip argument; comment: ''See documentation of getURLContent function for $localip and $sslverify possible values.'' Exact numeric meanings not restated at this call site.', 1, 0, NULL, 1, '43d24f30d7db7157cbd03c8b97f22c022bb276bccea9204d3b4df4ffcbd02ccd', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/class/ical.class.php:102|check|if (getDolGlobalString(''AGENDA_EXT_CALENDAR_IP_MODE'')) {", "comm/action/class/ical.class.php:103|read|$localip = intval(getDolGlobalString(''AGENDA_EXT_CALENDAR_IP_MODE''));", "comm/action/class/ical.class.php: // See documentation of getURLContent function for $localip and $sslverify possible values."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXT_CALENDAR_SSLVERIFY_MODE', 'string', NULL, 'comm', 'Controls the $sslverify parameter passed to getURLContent() when fetching external iCal calendar feeds.', 'Read in comm/action/class/ical.class.php:105-106 and cast with intval() before being passed as the $ssl_verifypeer argument to getURLContent() (default -1 otherwise).', 'Changing the value alters whether/how SSL certificate verification is performed when fetching the external calendar URL, per getURLContent''s own semantics.', 'Integer, passed as getURLContent()''s $ssl_verifypeer argument; comment: ''See documentation of getURLContent function for $localip and $sslverify possible values.'' Default when unset is -1.', 1, 0, NULL, 1, 'd8567cc554aac03315f939f481dd1563f969edd6c5efa7804602043663a1a539', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/class/ical.class.php:105|check|if (getDolGlobalString(''AGENDA_EXT_CALENDAR_SSLVERIFY_MODE'')) {", "comm/action/class/ical.class.php:106|read|$sslverify = intval(getDolGlobalString(''AGENDA_EXT_CALENDAR_SSLVERIFY_MODE''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXT_COLOR', 'string', NULL, 'admin', 'Per-site display color for an external calendar feed, dynamic constant AGENDA_EXT_COLOR<n> (module-wide) or AGENDA_EXT_COLOR_<userid>_<n> (per-user), configured under Agenda external sites setup.', 'Written by admin/agenda_extsites.php:152 via dolibarr_set_const with numeric suffix i, selected through a color-picker widget ($formother->selectColor, admin/agenda_extsites.php:244); read in comm/action/index.php:282/308 and comm/action/peruser.php:261/287 and core/lib/usergroups.lib.php:87 to color-code events from that external source in agenda views.', 'Changing the value changes the color used to render events from the corresponding external calendar feed in the agenda/calendar UI; no other effect found.', 'Hex color string (default ''ffffff'' when unset per user/agenda_extsites.php:265), selected via a color-picker form widget.', 0, 0, 'admin/agenda_extsites.php', 1, '6e6c7a10e4b1c87b7be747be5e33cd31bec24e164b88ebac8ab17d672546f2e4', 'v2', '2026-07-24T07:05:23+00:00', '["admin/agenda_extsites.php:152|write|$res = dolibarr_set_const($db, ''AGENDA_EXT_COLOR''.$i, $color, ''chaine'', 0, '''', $conf->entity);", "user/agenda_extsites.php:265: $color_value = (GETPOST(\"AGENDA_EXT_COLOR_\".$id.''_''.$key) ? ... : (empty($object->conf->$color) ? ''ffffff'' : $object->conf->$color));", "admin/agenda_extsites.php:244: print $formother->selectColor((GETPOST(\"AGENDA_EXT_COLOR\" . $key) ? ... : getDolGlobalString($color)), \"AGENDA_EXT_COLOR\" . $key, ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXT_ENABLED', 'bool', NULL, 'admin', 'Enables or disables individual external calendar sources displayed in the agenda (one constant per source, suffixed by index).', 'Written as ''AGENDA_EXT_ENABLED''.$i in admin/agenda_extsites.php:156; read as ''AGENDA_EXT_ENABLED''.$key at line 264 to determine if each external site entry is enabled. The constant name is dynamic, indexed per external calendar entry.', 'Setting AGENDA_EXT_ENABLED{N} to a truthy value enables that external calendar source; leaving it empty or absent disables it.', 'Non-empty string value enables the indexed external calendar; empty or absent disables it.', 0, 0, 'admin/agenda_extsites.php|admin/agenda_extsites.php', 1, 'ae84ce61db68344825d45f6620779749dc4abbed4ece426f364e515826b7ab43', 'v2', '2026-04-21T13:50:40+00:00', '["admin/agenda_extsites.php:156|write|$res = dolibarr_set_const($db, ''AGENDA_EXT_ENABLED''.$i, $enabled, ''chaine'', 0, '''', $conf->entity);", "admin/agenda_extsites.php:264|read|$disabled = getDolGlobalString(''AGENDA_EXT_ENABLED''.$key) ? 0 : 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXT_NAME', 'string', NULL, 'admin', 'Per-site display name for an external calendar source, dynamic constant AGENDA_EXT_NAME<n> (module-wide) or AGENDA_EXT_NAME_<userid>_<n> (per-user), configured under Agenda external sites setup.', 'Written by admin/agenda_extsites.php:140 (module-wide, suffix numeric index i) via dolibarr_set_const, and used per-user in user/agenda_extsites.php (stored in $tabparam, not via dolibarr_set_const there); read in admin/agenda_extsites.php:234, comm/action/index.php:280, comm/action/peruser.php:259, and core/lib/usergroups.lib.php:84 to label each external agenda feed in the calendar views.', 'Changing the name only relabels the corresponding external agenda entry in the UI; the numeric suffix links it to the matching AGENDA_EXT_SRC/AGENDA_EXT_OFFSETTZ/AGENDA_EXT_COLOR entries for the same site index.', 'Free-text string entered via GETPOST(''AGENDA_EXT_NAME''.$i, ''alpha'') on the admin setup form.', 0, 0, 'admin/agenda_extsites.php', 1, '61cee6ee3fa66cb585db058ae493a58fa8afe7cd7a78a4153fe76ee59ca9b7ec', 'v2', '2026-07-24T07:05:23+00:00', '["admin/agenda_extsites.php:140|write|$res = dolibarr_set_const($db, ''AGENDA_EXT_NAME''.$i, $name, ''chaine'', 0, '''', $conf->entity);", "admin/agenda_extsites.php:122: $name = trim(GETPOST(''AGENDA_EXT_NAME''.$i, ''alpha''));", "comm/action/index.php:280: $name = ''AGENDA_EXT_NAME''.$i;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXT_NB', 'string', NULL, 'comm', 'Sets the maximum number of external agenda sites configurable in the agenda external sites settings.', 'Read in admin/agenda_extsites.php:55, user/agenda_extsites.php:55, comm/action/peruser.php:51, comm/action/index.php:52, and core/lib/usergroups.lib.php:78 as the $MAXAGENDA limit; the default fallback is 6.', 'Changing this constant adjusts how many external calendar integrations can be configured per entity.', 'Integer; default fallback = 6.', 0, 0, 'admin/agenda_extsites.php', 1, 'ce8ddd8a83e3c9f436c69460233d9566ec2683fdd4b4ee558fad9b47ec456384', 'v2', '2026-04-21T11:16:15+00:00', '["admin/agenda_extsites.php:55|read|$MAXAGENDA = getDolGlobalInt(''AGENDA_EXT_NB'', 6);", "user/agenda_extsites.php:55|read|$MAXAGENDA = getDolGlobalString(''AGENDA_EXT_NB'', 6);", "comm/action/peruser.php:51|read|$MAXAGENDA = getDolGlobalString(''AGENDA_EXT_NB'', 6);", "comm/action/index.php:52|read|$MAXAGENDA = getDolGlobalString(''AGENDA_EXT_NB'', 6);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXT_OFFSETTZ', 'string', NULL, 'admin', 'Per-site timezone offset for an external calendar feed, dynamic constant AGENDA_EXT_OFFSETTZ<n> (module-wide) or AGENDA_EXT_OFFSETTZ_<userid>_<n> (per-user), configured under Agenda external sites setup.', 'Written by admin/agenda_extsites.php:148 via dolibarr_set_const with numeric suffix i; input rendered as a small text field of size 2 (admin/agenda_extsites.php:240); read in comm/action/index.php:281/307 and comm/action/peruser.php:260/286 and core/lib/usergroups.lib.php:86 alongside the matching AGENDA_EXT_SRC entry.', 'Adjusts the timezone offset applied when displaying events pulled from the corresponding external calendar source; exact arithmetic not shown in the code read.', 'Numeric offset string entered via GETPOST(''AGENDA_EXT_OFFSETTZ''.$i, ''alpha''), free text limited to size=2 input.', 0, 0, 'admin/agenda_extsites.php', 1, '348f8ca0d2c24392b6bd1a8127861fee58f356cf8c73cc615cd6438890de6d66', 'v2', '2026-07-24T07:05:23+00:00', '["admin/agenda_extsites.php:148|write|$res = dolibarr_set_const($db, ''AGENDA_EXT_OFFSETTZ''.$i, $offsettz, ''chaine'', 0, '''', $conf->entity);", "admin/agenda_extsites.php:240: print ''<td><input type=\"text\" class=\"flat hideifnotset\" name=\"AGENDA_EXT_OFFSETTZ'' . $key . ''\" ... size=\"2\"></td>'';", "comm/action/index.php:281: $offsettz = ''AGENDA_EXT_OFFSETTZ''.$i;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_EXT_SRC', 'string', NULL, 'admin', 'Per-site source URL for an external calendar feed, dynamic constant AGENDA_EXT_SRC<n> (module-wide) or AGENDA_EXT_SRC_<userid>_<n> (per-user), configured under Agenda external sites setup.', 'Written by admin/agenda_extsites.php:144 via dolibarr_set_const with numeric suffix i, entered as a URL field (type="url" input, admin/agenda_extsites.php:237); read in comm/action/index.php:279/305 and comm/action/peruser.php:258/284 and core/lib/usergroups.lib.php:85 to fetch/display the external calendar feed.', 'Changing the value changes which external calendar URL is queried/displayed for that agenda source index; invalid URLs would presumably break the feed [SPECULATION].', 'URL string entered via GETPOST(''AGENDA_EXT_SRC''.$i, ''alpha'') on the admin setup form (rendered as an HTML5 url input).', 0, 0, 'admin/agenda_extsites.php', 1, '472e05783af65b621aae3d5a8895774b78e35c6bd1515f6b87dbabdef06f8993', 'v2', '2026-07-24T07:05:23+00:00', '["admin/agenda_extsites.php:144|write|$res = dolibarr_set_const($db, ''AGENDA_EXT_SRC''.$i, $src, ''chaine'', 0, '''', $conf->entity);", "admin/agenda_extsites.php:237: print ''<td><input type=\"url\" class=\"flat hideifnotset width300\" name=\"AGENDA_EXT_SRC'' . $key . ''\" ...", "comm/action/index.php:279: $source = ''AGENDA_EXT_SRC''.$i;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_MAX_EVENTS_DAY_VIEW', 'string', NULL, 'comm', 'Sets the maximum number of events shown per day in the agenda day view.', 'Read in comm/action/pertype.php:114, comm/action/peruser.php:110, and comm/action/index.php:126 as the fallback value for $maxprint when no POST parameter is provided; the default fallback is 3.', 'Changing this constant adjusts how many events are displayed per day before additional events are hidden or paginated.', 'Integer; default fallback = 3.', 1, 0, NULL, 1, 'bb70397baee1328869d0e61d1f1e04a9771949e12cbc67dd77be8117b988e18a', 'v2', '2026-04-21T11:16:15+00:00', '["comm/action/pertype.php:114|read|$maxprint = GETPOSTISSET(\"maxprint\") ? GETPOSTINT(\"maxprint\") : getDolGlobalInt(''AGENDA_MAX_EVENTS_DAY_VIEW'', 3);", "comm/action/peruser.php:110|read|$maxprint = GETPOSTISSET(\"maxprint\") ? GETPOSTINT(\"maxprint\") : getDolGlobalInt(''AGENDA_MAX_EVENTS_DAY_VIEW'', 3);", "comm/action/index.php:126|read|$maxprint = GETPOSTISSET(\"maxprint\") ? GETPOSTINT(\"maxprint\") : getDolGlobalInt(''AGENDA_MAX_EVENTS_DAY_VIEW'', 3);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_MAX_EVENTS_ON_PAGE_WITHOUT_PAGINATION', 'string', NULL, 'core', 'Sets the maximum number of agenda events displayed on a page before pagination is applied, defaulting to 100.', 'Read with getDolGlobalInt at core/lib/company.lib.php:2155 and core/lib/functions.lib.php:16607, both using a default of 100. No comment is present in the payload.', 'Increasing the value allows more events per page without pagination; decreasing it triggers pagination sooner, which may improve rendering performance for busy calendars.', 'Integer; default is 100 when unset.', 1, 0, NULL, 1, '01b53b7e364a037b36d3ca07aa4c6323e9dd7511be933296128abb54a8c00320', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/company.lib.php:2155|read|$MAXWITHOUTPAGINATION = getDolGlobalInt(''AGENDA_MAX_EVENTS_ON_PAGE_WITHOUT_PAGINATION'', 100);", "core/lib/functions.lib.php:16607|read|$MAXWITHOUTPAGINATION = getDolGlobalInt(''AGENDA_MAX_EVENTS_ON_PAGE_WITHOUT_PAGINATION'', 100);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_NB_WEEKS_IN_VIEW_PER_USER', 'string', NULL, 'comm', 'Sets how many weeks are shown in the per-user agenda view.', 'In comm/action/peruser.php:421, the constant value (an integer number of weeks) is multiplied by 7 to compute the day range shown; if unset, the view defaults to 7 days (1 week).', 'Increasing the value widens the date range displayed in the per-user calendar view (value * 7 days); leaving it unset shows only 7 days.', 'string/int: number of weeks to display; unset/falsy = defaults to 7 days (1 week) range.', 0, 0, NULL, 1, '454f4ce0d04f8bfee9f60824d13fcd52066d2f045dc7dc74173361bea8948053', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/peruser.php:421: $nb_weeks_to_show = (getDolGlobalString(''AGENDA_NB_WEEKS_IN_VIEW_PER_USER'')) ? ((int) $conf->global->AGENDA_NB_WEEKS_IN_VIEW_PER_USER * 7) : 7;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_NOTIFICATION_METHOD', 'string', NULL, 'core', 'Specifies the JavaScript notification method used for agenda reminders in the browser (default ''jnotify'').', 'Read in core/js/lib_notification.js.php:81 and :123. The value is resolved first from user preference via getDolUserString, falling back to getDolGlobalString with a hardcoded default of ''jnotify''.', 'Changing this constant alters the global default notification method for all users who have not set a personal preference.', 'String identifying the notification method; default is ''jnotify''', 1, 0, NULL, 1, 'dbb22b700ff8c8423f78f11abcd7d32b300d4f484f80a7b4c4df17a1c56d50dc', 'v2', '2026-04-21T13:29:58+00:00', '["var methodfornotification = ''<?php print getDolUserString(''AGENDA_NOTIFICATION_METHOD'', getDolGlobalString(''AGENDA_NOTIFICATION_METHOD'', ''jnotify'')); ?>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_NO_TRANSPARENT_ON_NOT_BUSY', 'string', NULL, 'comm', 'Disables the transparent/opacity rendering of non-busy agenda events in calendar views.', 'Checked in comm/action/index.php:2202 and comm/action/peruser.php at lines 2344, 2361, 2378, 2395, and comm/action/pertype.php at lines 1253 and 1270 to suppress the ''opacitymedium'' CSS class.', 'Enabling this constant prevents non-busy events from being rendered with reduced opacity, making all events appear at full opacity regardless of busy status.', 'Truthy value = no transparency on non-busy events; empty/unset = non-busy events rendered with reduced opacity.', 1, 0, NULL, 1, 'efcb5080b5637d92e66978e2a672f88d9816d7cc9becbb990273d1e362654f59', 'v2', '2026-04-21T11:16:15+00:00', '["comm/action/index.php:2198  //if (empty($event->transparency) && empty($conf->global->AGENDA_NO_TRANSPARENT_ON_NOT_BUSY)) print '' opacitymedium'';\t// Not busy", "comm/action/index.php:2202|check|if (empty($event->transparency) && !getDolGlobalString(''AGENDA_NO_TRANSPARENT_ON_NOT_BUSY'')) {", "comm/action/pertype.php:1253|check|if (!getDolGlobalString(''AGENDA_NO_TRANSPARENT_ON_NOT_BUSY'')) {", "comm/action/peruser.php:2344|check|if (!empty($ev[''busy'']) && !getDolGlobalString(''AGENDA_NO_TRANSPARENT_ON_NOT_BUSY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_REMINDER_BROWSER', 'string', NULL, 'comm', 'Enables browser-based push reminders for agenda events.', 'Checked across admin/agenda_reminder.php (lines 197, 275, 298), main.inc.php:2063, comm/action/class/actioncomm.class.php:2704, and comm/action/card.php:165 and :168 to enable or disable the browser reminder feature and its UI controls.', 'Enabling this activates browser push notification reminders for agenda events; disabling it suppresses the browser reminder feature and its UI.', '0 or unset = browser reminders disabled; 1 (truthy) = browser reminders enabled', 0, 0, 'admin/agenda_reminder.php|admin/agenda_reminder.php|admin/agenda_reminder.php', 1, 'eaf1ea12acee9785035d84f4ebbc5f251e89a70914254eafcb139127273c90b2', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:2063|check|if (isModEnabled(''agenda'') && getDolGlobalString(''AGENDA_REMINDER_BROWSER'')) {", "admin/agenda_reminder.php:197|check|if (!getDolGlobalString(''AGENDA_REMINDER_BROWSER'')) {", "comm/action/card.php:168|read|''disabled'' => (getDolGlobalString(''AGENDA_REMINDER_BROWSER'') ? 0 : 1),", "comm/action/class/actioncomm.class.php:2704|check|if (!getDolGlobalString(''AGENDA_REMINDER_BROWSER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_REMINDER_BROWSER_SOUND', 'string', NULL, 'core', 'Enables an audio notification sound when a browser agenda reminder fires.', 'In core/js/lib_notification.js.php:154, the value is looked up per-user via getDolUserString with a fallback to the global getDolGlobalString of the same name; when truthy, an Audio object is created pointing to theme/common/sound/notification_agenda.wav.', 'Enabling it (globally or per-user) plays a notification sound (notification_agenda.wav) each time past reminders are retrieved via the ajax notification check.', 'boolean/string: truthy = play notification_agenda.wav sound on reminder; unset/0 = silent. Can be set per-user (getDolUserString) overriding the global default.', 0, 0, NULL, 1, '99802c18fcbbbbb181a2fd113786e7516a91499f927929d0f8325c350849017d', 'v2', '2026-07-24T07:05:23+00:00', '["core/js/lib_notification.js.php:154: if (getDolUserString(''AGENDA_REMINDER_BROWSER_SOUND'', getDolGlobalString(''AGENDA_REMINDER_BROWSER_SOUND''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_REMINDER_DEFAULT_OFFSET', 'string', NULL, 'comm', 'Sets the default reminder offset value pre-filled when adding a reminder to an agenda event.', 'Read in comm/action/card.php at lines 1932 and 2508 with a default of 30. Used to pre-populate the offset input field and to set the reminder''s offsetvalue property.', 'Changing this value changes the numeric reminder offset shown by default; users can still override it per event.', 'Integer (default 30); unit determined by AGENDA_DEFAULT_REMINDER_OFFSET_UNIT.', 1, 0, NULL, 1, '598ffc8c36bd7e5e353a34d120e422bd3c784aab47cfbfe5f6ef4f338bc8845a', 'v2', '2026-04-21T13:29:58+00:00', '["comm/action/card.php:1932|read|print ''<input class=\"width50\" type=\"number\" name=\"offsetvalue\" value=\"''.(GETPOSTISSET(''offsetvalue'') ? GETPOSTINT(''offsetvalue'') : getDolGlobalInt(''AGENDA_REMINDER_DEFAULT_OFFSET'',", "comm/action/card.php:2508|read|$actionCommReminder->offsetvalue = getDolGlobalInt(''AGENDA_REMINDER_DEFAULT_OFFSET'', 30);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_REMINDER_EMAIL', 'string', NULL, 'comm', 'Enables the email reminder feature for agenda events.', 'Written in admin/agenda_reminder.php at lines 88 and 89; checked in admin/agenda_reminder.php at lines 213, 227, 275, 298, 316, and in comm/action/card.php at lines 1943 and 2544, and in comm/action/class/actioncomm.class.php:2701.', 'Enabling this constant activates email reminders for agenda events, allowing the system to send reminder emails before scheduled events.', 'Truthy value = email reminders enabled; empty/unset = email reminders disabled.', 0, 0, 'admin/agenda_reminder.php|admin/agenda_reminder.php|admin/agenda_reminder.php|admin/agenda_reminder.php|admin/agenda_reminder.php', 1, '53365e417d6722d6d2c5ac76fb86e71286f747caa69b700158032a67a122f096', 'v2', '2026-04-21T11:16:15+00:00', '["admin/agenda_reminder.php:275|check|if (getDolGlobalString(''AGENDA_REMINDER_BROWSER'') || getDolGlobalString(''AGENDA_REMINDER_EMAIL'') || getDolGlobalString(''AGENDA_REMINDER_SMS'')) {", "admin/agenda_reminder.php:316|check|if (getDolGlobalString(''AGENDA_REMINDER_EMAIL'')) {", "comm/action/card.php:1943|check|if (getDolGlobalString(''AGENDA_REMINDER_EMAIL'')) {", "comm/action/class/actioncomm.class.php:2701|check|if (!getDolGlobalString(''AGENDA_REMINDER_EMAIL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_REMINDER_SMS', 'string', NULL, 'admin', 'Enables SMS reminders for agenda events when set to a truthy value.', 'Controls whether the SMS reminder channel is active for agenda events. Checked in admin/agenda_reminder.php to conditionally display SMS reminder settings, and in comm/action/class/actioncomm.class.php and comm/action/card.php to conditionally enable SMS reminder functionality.', 'When unset or falsy, SMS reminders are disabled and not offered as an option. When set, SMS reminders are enabled and users can configure them for agenda events.', 'Truthy string (enabled) or empty/unset (disabled).', 0, 0, 'admin/agenda_reminder.php|admin/agenda_reminder.php|admin/agenda_reminder.php|admin/agenda_reminder.php', 1, 'b731872ff95deae2f1f7f8534e593bd55caa858d4bbb0a3b85c8937244280374', 'v2', '2026-04-21T13:29:58+00:00', '["admin/agenda_reminder.php:251|check|if (getDolGlobalString(''AGENDA_REMINDER_SMS'')) {", "admin/agenda_reminder.php:265|check|if (!getDolGlobalString(''AGENDA_REMINDER_SMS'')) {", "comm/action/class/actioncomm.class.php:2935|check|if (!getDolGlobalString(''AGENDA_REMINDER_SMS'')) {", "comm/action/card.php:192|read|$enablereminders = getDolGlobalString(''AGENDA_REMINDER_EMAIL'') || getDolGlobalString(''AGENDA_REMINDER_BROWSER'') || getDolGlobalString(''AGENDA_REMINDER_SMS'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_SHOWOWNERONLY_ONPERUSERVIEW', 'bool', NULL, 'comm', 'Restricts the per-user agenda view to only show users who actually have events assigned.', 'In comm/action/peruser.php:1700, a comment says ''Use this to have list of users only if users have events''; when set, the code iterates events to build the list of assigned user IDs instead of showing all users.', 'Enabling it filters the user list/columns in the per-user agenda view down to only users with at least one assigned event, instead of listing every eligible user.', 'boolean: 1/true limits the per-user view to users with events; unset/0 = all users shown.', 0, 0, NULL, 1, '59fbf1edbb722a0a52fb8e46caa74f5a55aa14032e58fe60b5be6e386c8c34cb', 'v2', '2026-07-24T07:05:23+00:00', '["comm/action/peruser.php:1699: /* Use this to have list of users only if users have events */", "comm/action/peruser.php:1700: if (getDolGlobalString(''AGENDA_SHOWOWNERONLY_ONPERUSERVIEW'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_SHOW_LINKED_OBJECT', 'bool', NULL, 'comm', 'Enables display of the linked object on agenda event cards in the month view.', 'Checked in comm/action/index.php:2356 when an event has a linked element; also controls the ''visible'' attribute of the fk_element field in comm/action/class/actioncomm.class.php:447.', 'Enabling this constant causes linked business objects (e.g. invoices, orders) to be shown on event tiles in the agenda.', 'Truthy value = linked object shown; empty/unset = linked object hidden.', 1, 0, NULL, 1, 'cd8452a9419b0e95264434c78eacf6046e86dc7c10a6449542dd44c399cfcf54', 'v2', '2026-04-21T11:16:15+00:00', '["comm/action/index.php:2356|check|if (!empty($event->fk_element) && $event->fk_element > 0 && !empty($event->elementtype) && getDolGlobalString(''AGENDA_SHOW_LINKED_OBJECT'')) {", "comm/action/class/actioncomm.class.php:447|read|\"fk_element\" => array(\"type\" => \"integer\", \"label\" => \"LinkedObject\", \"enabled\" => \"getDolGlobalString(''AGENDA_SHOW_LINKED_OBJECT'')\", ''position'' => 145, ''notnull'' => 0, \"visible\" =>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_SHOW_PERTYPE', 'bool', NULL, 'core', 'Adds a ''View per type'' tab to the agenda/events list navigation.', 'Checked in core/lib/agenda.lib.php:551 inside the tab-head builder for the agenda; when set, it appends a head entry pointing to comm/action/pertype.php labelled ViewPerType.', 'Enabling it shows an extra tab in the agenda view allowing events to be grouped/viewed by type; no other effect is evidenced.', 'Boolean-like: truthy adds the ViewPerType tab, falsy/unset hides it.', 1, 0, NULL, 1, '4ce352f9dee06c3f4a72024959762c15bd4e4bc477cd783b8bb7197366b21c0a', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/agenda.lib.php:551|check|if (getDolGlobalString(''AGENDA_SHOW_PERTYPE'')) {", "$head[$h][0] = dolBuildUrl(DOL_URL_ROOT.''/comm/action/pertype.php'', $query); $head[$h][1] = $langs->trans(\"ViewPerType\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_SORT_EVENT_TYPE_BY_POSITION_FIRST', 'string', NULL, 'comm', 'Makes event type position the primary sort criterion in agenda event type lists.', 'Checked in comm/action/class/cactioncomm.class.php:188; the comment at line 186 states: ''If AGENDA_SORT_EVENT_TYPE_BY_POSITION_FIRST is defined, we use position as main sort criterion''. No admin UI; only one occurrence.', 'When set, event types are sorted by their position field first rather than by default ordering, changing the display order in agenda dropdowns.', 'Truthy string (sort by position first) or empty/unset (default sort order).', 1, 0, NULL, 1, '5cbde5d950f948aa1ff27638271a606a28dc1448997b67dba17fea1962a81fda', 'v2', '2026-04-21T13:29:58+00:00', '["comm/action/class/cactioncomm.class.php:186  // If AGENDA_SORT_EVENT_TYPE_BY_POSITION_FIRST is defined, we use position as main sort criterion", "comm/action/class/cactioncomm.class.php:188|check|if (getDolGlobalString(''AGENDA_SORT_EVENT_TYPE_BY_POSITION_FIRST'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_SUPPORT_PRIORITY_IN_EVENTS', 'string', NULL, 'comm', 'Enables a priority field on agenda event cards.', 'When set, the priority input is displayed on the event creation and edit forms in comm/action/card.php at lines 1895, 2390, and 2887.', 'Enabling this adds a priority field to all event forms; disabling it hides the field and priority data is not collected.', 'Empty/unset = no priority field on events; truthy value = priority field is displayed.', 1, 0, NULL, 1, '55962951c97544b8b7447223899bfbfec16fb98416ddcdb734b4421a3781de9b', 'v2', '2026-04-21T13:29:58+00:00', '["comm/action/card.php:1895|check|if (getDolGlobalString(''AGENDA_SUPPORT_PRIORITY_IN_EVENTS'')) {", "comm/action/card.php:2390|check|if (getDolGlobalString(''AGENDA_SUPPORT_PRIORITY_IN_EVENTS'')) {", "comm/action/card.php:2887|check|if (getDolGlobalString(''AGENDA_SUPPORT_PRIORITY_IN_EVENTS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_USE_COLOR_PER_EVENT_TYPE', 'bool', NULL, 'comm', 'Enables color-coding of agenda events based on their event type.', 'Checked in comm/action/peruser.php at lines 1822 (combined with AGENDA_USE_EVENT_TYPE), 2010, and 2046; a commented note in comm/action/index.php:2053 reads: ''May be we need this: if (getDolGlobalString(AGENDA_USE_COLOR_PER_EVENT_TYPE))''.', 'Enabling this constant causes events in the per-user agenda view to be rendered with colors corresponding to their event type.', 'Truthy value = color-per-event-type enabled; empty/unset = no type-based coloring.', 1, 0, NULL, 1, '2408de9d6022ec934e9b5839ea28c0470f4fa255844cc0d4db3ab6a18da11757', 'v2', '2026-04-21T11:16:15+00:00', '["comm/action/peruser.php:1822|check|if (getDolGlobalString(''AGENDA_USE_EVENT_TYPE'') && getDolGlobalString(''AGENDA_USE_COLOR_PER_EVENT_TYPE'')) {", "comm/action/peruser.php:2010|check|if (getDolGlobalString(''AGENDA_USE_COLOR_PER_EVENT_TYPE'')) {", "comm/action/peruser.php:2046|check|if (getDolGlobalString(''AGENDA_USE_COLOR_PER_EVENT_TYPE'')) {", "comm/action/index.php:2053  /* May be we need this: if (getDolGlobalString(''AGENDA_USE_COLOR_PER_EVENT_TYPE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_USE_EVENT_TYPE', 'bool', NULL, 'comm', 'Enables the event type classification system on the agenda, showing event type selectors and type-based filtering.', 'Written and read in admin/agenda_other.php (lines 370, 377, 411, 413). Checked across 44 occurrences in multiple files including comm/action/pertype.php:566, comm/action/peruser.php:735, comm/action/list.php:495, and comm/action/document.php:235.', 'Enabling this constant activates event type classification across all agenda views, enabling type selectors, type-based filtering, and type display.', 'Truthy value = event type system enabled; empty/unset = event types not used.', 0, 0, 'admin/agenda_other.php|admin/agenda_other.php|admin/agenda_other.php|admin/agenda_other.php', 1, '8126d4b895a83acc33321a7b52c4b4ec8757fb50087aae4eed249c5ace3a1899', 'v2', '2026-04-21T11:16:15+00:00', '["admin/agenda_other.php:369  //print ajax_constantonoff(''AGENDA_USE_EVENT_TYPE'');\tDo not use ajax here, we need to reload page to change other combo list", "admin/agenda_other.php:370|check|if (!getDolGlobalString(''AGENDA_USE_EVENT_TYPE'')) {", "comm/action/pertype.php:566|check|if (!getDolGlobalString(''AGENDA_USE_EVENT_TYPE'')) {", "comm/action/document.php:235|check|if (getDolGlobalString(''AGENDA_USE_EVENT_TYPE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_USE_EVENT_TYPE_DEFAULT', 'bool', NULL, 'admin', 'Sets the default event type code preselected when creating a new agenda event, default ''AC_OTH''.', 'Set from admin/agenda_other.php:97 and admin/agenda_reminder.php:87 (dolibarr_set_const, type ''chaine''), used in admin/agenda_other.php:383 (select_type_actions) and comm/action/card.php:1545,1518 with default ''AC_OTH''; ''-1'' is also checked as an unset-equivalent value.', 'Changing it changes which event-type code is pre-selected by default in the agenda event creation form; unless overridden by the special code ''AC_RDV'' or set to ''-1''.', '''AC_OTH'' is the default value; ''-1'' is treated like unset; ''AC_RDV'' is special-cased in comm/action/card.php:1545.', 0, 0, 'admin/agenda_other.php|admin/agenda_other.php|admin/agenda_reminder.php', 1, 'e91cb01c0d5a6d72d6f9c9e097778aaa73f29fa91d1b067bf7f2750578ac91a5', 'v2', '2026-07-24T06:41:12+00:00', '["$default = getDolGlobalString(''AGENDA_USE_EVENT_TYPE_DEFAULT'', ''AC_OTH'');", "if (GETPOST(\"actioncode\", ''aZ09'') == ''AC_RDV'' || (!getDolGlobalString(''AGENDA_USE_EVENT_TYPE_DEFAULT'') || getDolGlobalString(''AGENDA_USE_EVENT_TYPE_DEFAULT'') == ''-1'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENDA_USE_MULTISELECT_TYPE', 'bool', NULL, 'core', 'Switches the agenda event-type filter on list search forms from a single-select to a multi-select dropdown.', 'In core/lib/company.lib.php:2391, the actioncode type filter is built via $formactions->select_type_actions(...) where the multiselect argument is (getDolGlobalString(''AGENDA_USE_MULTISELECT_TYPE'') ? 1 : 0), controlling whether users can pick multiple event types at once.', 'Enabling it lets users filter agenda/event lists by several event types simultaneously instead of only one.', 'Boolean-like: set/non-empty enables multiselect (passes 1); unset (default) uses single-select (passes 0).', 1, 0, NULL, 1, 'cd2dbb0b3456439b4df2d57b82c9bd05703e6075f5abee2163942025c61e6d99', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/company.lib.php:2391: (getDolGlobalString(''AGENDA_USE_MULTISELECT_TYPE'') ? 1 : 0), 1, ''selecttype combolargeelem ...''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AGENT_CONTACT_TYPE', 'string', NULL, 'margin', 'Defines the contact type code used to identify sales agents linked to invoices in the margin agent report.', 'Written via margin/admin/margin.php at line 85 and read in margin/agentMargins.php at line 171 to build the SQL JOIN on element_contact; when unset the join uses -1 (no match). The admin UI at margin/admin/margin.php renders a contact-type selector.', 'Changing this alters which contact type is recognized as a sales agent, directly affecting which contacts appear in the agent margin report.', 'String: contact type code (e.g. internal contact type code); unset = no agent contact join (-1)', 0, 0, 'margin/admin/margin.php|margin/admin/margin.php', 1, '8490d96aef85a36d31dba594f2baa99905441d2a9142de8799b5f19f2bcaf46b', 'v2', '2026-04-21T13:50:40+00:00', '["margin/admin/margin.php:85|write|if (dolibarr_set_const($db, ''AGENT_CONTACT_TYPE'', GETPOST(''AGENT_CONTACT_TYPE''), ''chaine'', 0, '''', $conf->entity) <= 0) {", "margin/agentMargins.php:171|read|$sql .= \" LEFT JOIN \".MAIN_DB_PREFIX.\"element_contact e ON e.element_id = f.rowid and e.statut = 4 and e.fk_c_type_contact = \".(!getDolGlobalString(''AGENT_CONTACT_TYPE'') ? -1 : $co", "margin/admin/margin.php:225|read|print $formcompany->selectTypeContact($facture, getDolGlobalString(''AGENT_CONTACT_TYPE''), \"AGENT_CONTACT_TYPE\", \"internal\", \"code\", 1, \"maxwidth250\");", "margin/agentMargins.php:179|check|if (getDolGlobalString(''AGENT_CONTACT_TYPE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_API_', 'string', NULL, 'ai', 'Dynamic constant prefix resolving to per-AI-service settings: AI_API_<SERVICE>_KEY, _URL, and _MODEL_DOCPARSING (and similar _MODEL_* suffixes).', 'Read in ai/admin/assistant.php:109-110, ai/admin/server_mcp.php:109-110, and ai/class/ai.class.php:79,124,142,173 using string concatenation like ''AI_API_'' . strtoupper($this->apiService) . ''_KEY''/''_URL''/''_MODEL_DOCPARSING''. Comment in ai/assistant/parse_intent.php:335,337 notes the per-function model is stored under AI_API_<SERVICE>_MODEL_TEXT, and warns a previous lookup used AI_API_<SERVICE>_MODEL which is never written.', 'Changing the resolved per-service constant (e.g. AI_API_CHATGPT_KEY) changes the credential/URL/model used for that AI service; per the code comment, looking up AI_API_<SERVICE>_MODEL (without a function suffix) is a documented bug since it is never written.', 'Per-service suffixes: _KEY (credential, encrypted per ai/admin/setup.php comment), _URL (endpoint), _MODEL_DOCPARSING and other _MODEL_<FUNCTION> variants (e.g. _MODEL_TEXT).', 0, 0, 'ai/admin/assistant.php|ai/admin/assistant.php|ai/admin/server_mcp.php|ai/admin/server_mcp.php', 1, '94eeb3b77475cbd7ef7030d11a4c39ff1f3fcd4fd0c8d21a7354366bfe940a1c', 'v2', '2026-07-24T06:41:12+00:00', '["$credential = getDolGlobalString(''AI_API_'' . strtoupper($service) . ''_KEY'');", "// previous lookup used AI_API_<SERVICE>_MODEL which is never written by that", "/*$item = $formSetup->newItem(''AI_API_''.strtoupper($ia).''_ENDPOINT'');\t// Name of constant must end with _KEY so it is encrypted when saved into database."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_API_CUSTOM_URL', 'string', NULL, 'ai', 'Holds the custom API endpoint URL used when the AI module''s service is set to ''custom'' (a user-provided AI API rather than a built-in one like chatgpt/groq/mistral).', 'Checked in Ai::generateContent() (ai/class/ai.class.php:116): if apiEndpoint is not otherwise set, apiService is ''custom'', and this constant is empty, the call fails with an explicit error.', 'Leaving it unset while apiService=''custom'' causes AI content generation calls to fail immediately with ''API URL is not defined for the AI enabled service''; setting it supplies the endpoint used for custom AI API calls.', 'String: a URL; required (non-empty) when the AI service is configured as ''custom''.', 0, 0, NULL, 1, '2c78cf5dd46902df14d8771cac8f97422bafa9d40730f0f848e43566342c6be2', 'v2', '2026-07-24T07:05:23+00:00', '["ai/class/ai.class.php:116: if (empty($this->apiEndpoint) && $this->apiService == ''custom'' && !getDolGlobalString(''AI_API_CUSTOM_URL'')) {", "ai/class/ai.class.php:117: return array(''error'' => true, ''message'' => ''API URL is not defined for the AI enabled service (''.$this->apiService.'')'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_API_SERVICE', 'string', NULL, 'ai', 'Selects which AI service/provider is currently configured, default ''chatgpt''.', 'Set/read across 9 occurrences: ai/admin/setup.php:235,225, ai/admin/custom_prompt.php:82 (default ''chatgpt''), ai/admin/assistant.php:312, ai/admin/server_mcp.php:313, ai/class/ai.class.php:78 (default ''chatgpt''), ai/lib/ai.lib.php:479, ai/assistant/parse_intent.php:85.', 'Changing it switches which AI provider/service is used throughout the AI module (assistant, MCP server, prompt building), defaulting to ''chatgpt'' if unset.', 'Default ''chatgpt'' when unset.', 0, 0, 'ai/admin/custom_prompt.php|ai/admin/assistant.php|ai/admin/setup.php|ai/admin/setup.php|ai/admin/server_mcp.php', 1, '950fb13b2dad5457c1b271cc17b723694d0d21e5f2b6ed064935ed808c69c947', 'v2', '2026-07-24T06:41:12+00:00', '["$aiservice = getDolGlobalString(''AI_API_SERVICE'', ''chatgpt'');", "$this->apiService = getDolGlobalString(''AI_API_SERVICE'', ''chatgpt'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_ASK_FOR_CONFIRMATION', 'string', NULL, 'ai', 'Controls whether the AI assistant asks for user confirmation before performing an action, default 1 (enabled).', 'Set from ai/admin/assistant.php:70 and ai/admin/server_mcp.php:70 (dolibarr_set_const, type ''int''), configured via a select in assistant.php:273/server_mcp.php:274 with default 1, and read in ai/assistant/parse_intent.php:70.', 'Disabling it (setting to 0) skips the confirmation step before the AI assistant executes an action; default is 1 (ask for confirmation).', 'Integer value driving a selectarray of confirmation options; default 1.', 0, 0, 'ai/admin/assistant.php|ai/admin/server_mcp.php|ai/admin/assistant.php|ai/admin/server_mcp.php', 1, 'a60c020e2695bb9a84a611c6096cebe5a3deed3917fed9e2bd41f2b8ffa9c1c9', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"AI_ASK_FOR_CONFIRMATION\", GETPOSTINT(\"AI_ASK_FOR_CONFIRMATION\"), ''int'', 0, '''', $conf->entity);", "print $form->selectarray(''AI_ASK_FOR_CONFIRMATION'', $confirmation_options, getDolGlobalInt(''AI_ASK_FOR_CONFIRMATION'', 1), 0, 0, 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_ASSISTANT_ALLOWED_TOOLS', 'bool', NULL, 'ai', 'Allow-list of tools visible/usable by the private AI chat assistant.', 'Set via ai/admin/configure_tools.php:122 (dolibarr_set_const) and read at ai/admin/configure_tools.php:98; enforced in ai/assistant/execute_tool.php:69.', 'Restricts which tools the private chat assistant can see and execute; the allow-list is enforced on both schema and execution.', NULL, 0, 0, 'ai/admin/configure_tools.php|ai/admin/configure_tools.php', 1, '7017aa1d5b223623bd773175b6a2c7c9dc214c58a938b7f2132180829cef96b1', 'v2', '2026-07-24T06:41:12+00:00', '["AI_ASSISTANT_ALLOWED_TOOLS  — tools visible to the private chat assistant", "// allow-list (AI_ASSISTANT_ALLOWED_TOOLS) is enforced on both schema and execution."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_ASSISTANT_DISABLE_TOOLS', 'bool', NULL, 'ai', 'Disables all MCP tools from being offered to the AI assistant''s LLM, restricting it to plain conversational responses.', 'In ai/assistant/parse_intent.php:310, if this constant is truthy, $toolsForLLM is reset to an empty array before being included in the system prompt sent to the LLM.', 'When set, the AI assistant can no longer call any tool (e.g. create documents, lookups) and can only use conversational fallback behavior.', 'Boolean-like flag (truthy disables tools).', 0, 0, NULL, 1, '2aaa45fba9d7f5b202d84e73093143032ed2bc73b5a06d6ecb68a8ca3409559e', 'v2', '2026-07-24T07:05:23+00:00', '["ai/assistant/parse_intent.php:310: if (getDolGlobalString(''AI_ASSISTANT_DISABLE_TOOLS'')) {", "ai/assistant/parse_intent.php:311: $toolsForLLM = array();"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_ASSISTANT_ENABLED', 'bool', NULL, 'ai', 'Master switch enabling the AI chat assistant feature across the application.', 'Toggled via ai/admin/assistant.php:230 and checked in main.inc.php:2759 and across ai/assistant/*.php (execute_tool.php, popover.php, parse_intent.php, index.php, download_pdf.php).', 'When disabled, the assistant popover, intent parsing, tool execution, and PDF download entry points all refuse to run (guarded together with isModEnabled(''ai'')).', NULL, 0, 0, 'ai/admin/assistant.php', 1, '05db65ea61aa1d8b84aa7556a9b9e7e9eb413dd591cfbe83aa9d7b3b5392c268', 'v2', '2026-07-24T06:41:12+00:00', '["if (!isModEnabled(''ai'') || !getDolGlobalString(''AI_ASSISTANT_ENABLED'') || empty($conf->use_javascript_ajax)) {", "$assistantEnabled = getDolGlobalInt(''AI_ASSISTANT_ENABLED'', 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_CONFIGURATIONS_PROMPT', 'string', NULL, 'ai', 'Stores the JSON-encoded configuration of custom AI prompts per function, managed via the AI admin UI.', 'Contains a JSON string of prompt configurations read and written by ai/admin/custom_prompt.php (lines 113, 150, 175, 197). At generation time, ai/class/ai.class.php:181 decodes this JSON to select the appropriate prompt.', 'Changing this value alters the system prompts sent to the AI for each configured function; clearing it resets to default built-in prompts.', 'JSON-encoded string of prompt configurations keyed by function; empty/unset = default prompts are used.', 0, 0, 'ai/admin/custom_prompt.php|ai/admin/custom_prompt.php|ai/admin/custom_prompt.php|ai/admin/custom_prompt.php', 1, 'a94b8b5c53036119e8d5c71664b7fdc380e4e834639a7494a6fb18fbbea0a7c1', 'v2', '2026-04-21T13:29:58+00:00', '["ai/admin/custom_prompt.php:113|read|$currentConfigurationsJson = getDolGlobalString(''AI_CONFIGURATIONS_PROMPT'');", "ai/admin/custom_prompt.php:150|write|$result = dolibarr_set_const($db, ''AI_CONFIGURATIONS_PROMPT'', $newConfigurationsJson, ''chaine'', 0, '''', $conf->entity);", "ai/class/ai.class.php:181|read|$configurationsJson = getDolGlobalString(''AI_CONFIGURATIONS_PROMPT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_DEBUG', 'string', NULL, 'ai', 'Enables debug logging for the AI module.', 'Checked in ai/admin/setup.php:270,291 and ai/class/ai.class.php:187,473,346,400. Comment in ai/ajax/generate_content.php:91: ''The option AI_DEBUG will generate a log file dolibarr_ai.log when calling generateContent()''.', 'Enabling it generates a dolibarr_ai.log debug log file when generateContent() is called, per the code comment.', NULL, 0, 0, 'ai/admin/setup.php|ai/admin/setup.php', 1, 'db0752afd57d27c41b4a177530533467e68a8e55ce68fb1a748346013cc8fe75', 'v2', '2026-07-24T06:41:12+00:00', '["// Note: The option AI_DEBUG will generate a log file dolibarr_ai.log when calling generateContent()", "if (getDolGlobalString(\"AI_DEBUG\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_DEFAULT_INPUT_MODE', 'string', NULL, 'ai', 'Sets the default input mode preselected in the AI assistant/MCP server admin configuration.', 'Set from ai/admin/assistant.php:82 and ai/admin/server_mcp.php:82 (dolibarr_set_const, type ''chaine''), used in a selectarray at assistant.php:251/server_mcp.php:252, and read in ai/lib/ai.lib.php:598 to populate a ''mode'' value.', 'Changing it changes which input mode is preselected by default for the AI assistant and is used as the ''mode'' value returned by ai.lib.php.', NULL, 0, 0, 'ai/admin/assistant.php|ai/admin/server_mcp.php|ai/admin/assistant.php|ai/admin/server_mcp.php', 1, '6c2b796e6d3ad45d704b3425a354d340f08071757793ce2707304917f0876b7c', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"AI_DEFAULT_INPUT_MODE\", GETPOST(\"AI_DEFAULT_INPUT_MODE\"), ''chaine'', 0, '''', $conf->entity);", "''mode'' => getDolGlobalString(''AI_DEFAULT_INPUT_MODE''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_INTENT_PROMPT', 'string', NULL, 'ai', 'Base prompt text used to instruct the AI assistant on how to interpret user intent.', 'Set and read via ai/admin/assistant.php:206/89 and ai/admin/server_mcp.php:206/89 through the admin UI (dolibarr_set_const/getDolGlobalString), and consumed as a fallback base prompt in ai/assistant/parse_intent.php:304.', 'Changing it alters the instructions given to the AI assistant when parsing user intent; if unset, a hardcoded default prompt text is used instead.', NULL, 0, 0, 'ai/admin/assistant.php|ai/admin/server_mcp.php|ai/admin/assistant.php|ai/admin/server_mcp.php', 1, 'f96dad24834a74ef963674253e6aee92d715151fa06be6717cbf2cc3738a5e70', 'v2', '2026-07-24T06:41:12+00:00', '["$currentPrompt = getDolGlobalString(''AI_INTENT_PROMPT'', $defaultPromptText);", "$basePrompt = getDolGlobalString(''AI_INTENT_PROMPT'') ?: \"You are a professional Dolibarr assistant.\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_LOG_REQUESTS', 'string', NULL, 'ai', 'Enables logging of AI assistant/MCP requests and responses into the llx_ai_request_log table.', 'In ai/lib/ai.lib.php:323, ai_log_request() returns immediately (no-op) unless this constant is truthy; ai/server/mcp_server.php:286 confirms logging tools/call events is ''no-op unless AI_LOG_REQUESTS is enabled''. Has an admin UI toggle (ajax_constantonoff) in ai/admin/assistant.php:281 and ai/admin/server_mcp.php:282.', 'Enabling it causes AI queries, tool calls, responses, timing, and status to be persisted to the request log table for later review; leaving it disabled skips all logging.', 'Boolean (0/1) via admin Yes/No toggle.', 0, 0, NULL, 1, '9044a7d0e6f928d40c1402e6ea54cbae27236415d5e1d4abd24aee7883ebc6b2', 'v2', '2026-07-24T07:05:23+00:00', '["ai/server/mcp_server.php:286: // Log this tools/call to llx_ai_request_log (no-op unless AI_LOG_REQUESTS is enabled", "ai/lib/ai.lib.php:323: if (!getDolGlobalInt(''AI_LOG_REQUESTS'')) { return 0; }", "ai/admin/assistant.php:281: print ajax_constantonoff(''AI_LOG_REQUESTS'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_LOG_RETENTION', 'string', NULL, 'ai', 'Number of days AI-related logs are retained before being purged, with 0 meaning forever.', 'Set via ai/admin/assistant.php:75 and ai/admin/server_mcp.php:75 (dolibarr_set_const) and displayed/read at ai/admin/assistant.php:288 and ai/admin/server_mcp.php:289 with a default of 30.', 'Setting it to 0 keeps AI logs forever; other values control how long logs are kept before cleanup.', '0 = Forever; default 30', 0, 0, 'ai/admin/assistant.php|ai/admin/server_mcp.php|ai/admin/assistant.php|ai/admin/server_mcp.php', 1, 'f3199318db8490db6646c81d920584e85e2b889e42b9b74fb9c6846a1a9c3faf', 'v2', '2026-07-24T06:41:12+00:00', '["print ''<td><input class=\"width50\" type=\"number\" name=\"AI_LOG_RETENTION\" value=\"'' . getDolGlobalInt(''AI_LOG_RETENTION'', 30) . ''\"> (0 = Forever)</td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_MCP_API_KEY', 'string', NULL, 'ai', 'API key used to authenticate requests to the AI module''s MCP (Model Context Protocol) server.', 'Generated and stored via ai/admin/assistant.php:161 and ai/admin/server_mcp.php:161 (dolibarr_set_const), read at ai/admin/assistant.php:192, ai/admin/server_mcp.php:192, and checked against incoming requests in ai/server/mcp_server.php:89.', 'This key gates access to the MCP server endpoint; rotating or changing it invalidates prior clients using the old key.', NULL, 0, 0, 'ai/admin/assistant.php|ai/admin/server_mcp.php|ai/admin/assistant.php|ai/admin/server_mcp.php', 1, 'a9e2ef23ae98af2d8ea2fa465ddf2c295445e8d6158bd0a7fd0cdd8630cc5527', 'v2', '2026-07-24T06:41:12+00:00', '["// and/or rotate AI_MCP_API_KEY regularly.", "$storedKey    = getDolGlobalString(''AI_MCP_API_KEY'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_MCP_ENABLED', 'bool', NULL, 'ai', 'Enables the AI module''s MCP (Model Context Protocol) server.', 'Toggled via ai/admin/server_mcp.php:230 and checked in ai/server/mcp_server.php:58 alongside isModEnabled(''ai'').', 'When disabled, the MCP server entry point refuses requests.', NULL, 0, 0, 'ai/admin/server_mcp.php', 1, 'accc77c471f6c9f85b1c66e44f02fefc2ac290e60b0d1de6c318222228f11d38', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''AI_MCP_ENABLED'')) {", "if (!isModEnabled(''ai'') || !getDolGlobalString(''AI_MCP_ENABLED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_MCP_SERVER_ALLOWED_TOOLS', 'bool', NULL, 'ai', 'Allow-list of tools visible to and usable by external MCP clients connecting to the AI module''s MCP server.', 'Set via ai/admin/configure_tools.php:134 (dolibarr_set_const) and read at ai/admin/configure_tools.php:99; enforced in ai/class/mcp_protocol.class.php on tool listing and execution.', 'Tools not present in this allow-list are disabled by the admin, excluded from the tool list returned to MCP clients, and execution is blocked for any tool not in the list.', NULL, 0, 0, 'ai/admin/configure_tools.php|ai/admin/configure_tools.php', 1, '555e709a2c2c399b9bb949bc34117cdfcce091e815e5832ef0e4ce343d6ce390', 'v2', '2026-07-24T06:41:12+00:00', '["AI_MCP_SERVER_ALLOWED_TOOLS — tools visible to external MCP clients", "* Only tools permitted by AI_MCP_SERVER_ALLOWED_TOOLS are returned.", "* Execution is blocked for any tool not in AI_MCP_SERVER_ALLOWED_TOOLS,"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_MCP_USER_ID', 'string', NULL, 'ai', 'ID of the Dolibarr user account used as the service/technical user for MCP requests handled by the AI module.', 'Set via ai/admin/assistant.php:138 and ai/admin/server_mcp.php:138 (dolibarr_set_const), selected in the admin UI at ai/admin/assistant.php:357 and ai/admin/server_mcp.php:358, and used at ai/server/mcp_server.php:127 and by tool classes such as ai/tools/reports.class.php:47.', 'Determines which user''s permissions and identity are used when the MCP handler executes actions on behalf of AI requests.', NULL, 0, 0, 'ai/admin/assistant.php|ai/admin/server_mcp.php|ai/admin/assistant.php|ai/admin/server_mcp.php', 1, '71dd1cca13be75a20dfeda175f3be06fc451b823c2b56092a4c2e17b63fd69c8', 'v2', '2026-07-24T06:41:12+00:00', '["* \t@param\tUser|null\t$user\t\tService user provided by McpHandler (from AI_MCP_USER_ID)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_PRIVACY_REDACTION', 'string', NULL, 'ai', 'Enables redaction of sensitive data before it is sent to the AI provider by the AI assistant intent parser.', 'Read in ai/assistant/parse_intent.php:86 as $doRedact = getDolGlobalInt(''AI_PRIVACY_REDACTION'', 0), used by the privacy name-resolution/masking step of the assistant request. It has an admin UI toggle (ajax_constantonoff) in ai/admin/assistant.php:259 and ai/admin/server_mcp.php:260.', 'When enabled, the assistant applies name resolution/masking to the query before further processing, reducing personal/business data sent to the AI provider.', 'Boolean (0/1), default 0 (disabled).', 0, 0, NULL, 1, 'a2da7b6ac268d33ff9b2fae80588d353046ed55543584b17c9cf7befa3ed9e9d', 'v2', '2026-07-24T07:05:23+00:00', '["ai/assistant/parse_intent.php:86: $doRedact = getDolGlobalInt(''AI_PRIVACY_REDACTION'', 0);", "ai/admin/assistant.php:259: print ajax_constantonoff(''AI_PRIVACY_REDACTION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AI_REQUEST_TIMEOUT', 'string', NULL, 'ai', 'Sets the timeout in seconds for AI assistant requests to the external AI provider.', 'Read in ai/assistant/parse_intent.php:87 as $timeout = getDolGlobalInt(''AI_REQUEST_TIMEOUT'', 120), then used at line 102 to extend the PHP execution time via set_time_limit($timeout + 5).', 'Increasing the value allows longer-running AI provider calls before the request is aborted; PHP''s own execution time limit is set to timeout+5 seconds.', 'Integer seconds, default 120.', 1, 0, NULL, 1, '563bed78d732d301b21d39a8a3febd7c5f3fb1c4b147f1830f59f08b4e9e206c', 'v2', '2026-07-24T07:05:23+00:00', '["ai/assistant/parse_intent.php:87: $timeout = getDolGlobalInt(''AI_REQUEST_TIMEOUT'', 120);", "ai/assistant/parse_intent.php:102: set_time_limit($timeout + 5);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ALLOW_THEME_JS', 'bool', NULL, 'core', 'Enables loading of a custom theme.js JavaScript file from the active theme''s directory.', 'In main.inc.php:2168, when set, Dolibarr builds the path ''/theme/<theme>/<theme>.js'' and includes it via a <script> tag if the file exists on disk.', 'Setting it allows a theme to inject custom JavaScript sitewide by placing a <themename>.js file in its theme directory; if the file does not exist, nothing changes.', 'Boolean-like: truthy enables loading of the per-theme JS file when present.', 0, 0, NULL, 1, '4bd4252d8aa9c4d24ae46a4b08ae6c08f91868e82ecaf8646f480e4a7c6f4e7e', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:2168|check|if (getDolGlobalString(''ALLOW_THEME_JS'')) {", "main.inc.php: //If you want to load custom javascript file from your selected theme directory"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ALLOW_USE_KITS_INTO_BOM_AND_MO', 'bool', NULL, 'mrp', 'Allows kit/virtual products (products with sub-products) to be used as the product of a Bill of Materials or Manufacturing Order.', 'Checked in mrp/class/mo.class.php:328: when module option PRODUIT_SOUSPRODUITS (kits) is enabled and this constant is NOT set, Dolibarr blocks using a virtual/kit product in a BOM or MO.', 'If left unset (default), creating a BOM/MO on a kit product (one with parent/child product links) raises error ''ErrorAVirtualProductCantBeUsedIntoABomOrMo''. Setting it removes that restriction.', 'Not set/false (default): kit products forbidden in BOM/MO. True: kit products allowed.', 1, 0, NULL, 1, '71f05c2416d1e4279908b94713a67ec7a5c158f3b98e1a77d7a845a7ff4ccfc4', 'v2', '2026-07-24T07:05:23+00:00', '["mrp/class/mo.class.php:328|check|if (getDolGlobalString(''PRODUIT_SOUSPRODUITS'') && !getDolGlobalString(''ALLOW_USE_KITS_INTO_BOM_AND_MO'') && $this->fk_product > 0) {", "mrp/class/mo.class.php:333|check|$this->error = ''ErrorAVirtualProductCantBeUsedIntoABomOrMo'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_ALLOW_PASSWORD_RESET', 'bool', NULL, 'user', 'Enables the REST API''s user password-reset endpoint, which is otherwise forbidden by default.', 'Checked in user/class/api_users.class.php:524 inside setPassword(), after a separate API_ENABLE_LOGIN_API gate; the error message states ''password reset APIs are disabled by default. To allow this, the option API_ALLOW_PASSWORD_RESET must be set.''', 'Enabling it (together with API_ENABLE_LOGIN_API) allows the {id}/setPassword API endpoint to proceed instead of throwing a 403 RestException; without it, all password-reset API calls are rejected regardless of caller permissions.', 'Boolean-like (truthy/falsy); explicitly documented as off by default for security.', 1, 0, NULL, 1, 'b1ac99a194683f9cfaf85e598f9b1612e603388f0304228bf6a29c82cafa60a3', 'v2', '2026-07-24T07:05:23+00:00', '["user/class/api_users.class.php:524: if (!getDolGlobalString(''API_ALLOW_PASSWORD_RESET'')) {", "user/class/api_users.class.php:525: throw new RestException(403, \"Error: password reset APIs are disabled by default. To allow this, the option API_ALLOW_PASSWORD_RESET must be set.\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_CONTRAT_PUTLINE_OUTPUT_LINE_ONLY', 'string', NULL, 'contrat', 'Restricts the API PUT contract-line endpoint response to return only the updated line object, stripping several extra fields, instead of the full response.', 'In contrat/class/api_contracts.class.php:501, after a successful line update ($updateRes > 0), when truthy the code fetches the ContratLigne and unsets fields like array_languages, contacts_ids, linked_objects, linkedObjectsIds, actiontypecode, module, canvas, user, origin, origin_id, ref_ext from the returned object.', 'Setting it changes the API response shape for the contract line PUT endpoint, trimming metadata fields from the returned line object; API clients depending on those fields being present would need to adapt.', 'Boolean-like (read via getDolGlobalInt): truthy trims the listed fields from the API response for this endpoint.', 0, 0, NULL, 1, '9556774c70eb3212afb839c57aacdd366123cdb8359d6bb6acc0fc0527432d34', 'v2', '2026-07-24T07:05:23+00:00', '["contrat/class/api_contracts.class.php:501|check|if (getDolGlobalInt(''API_CONTRAT_PUTLINE_OUTPUT_LINE_ONLY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_COUNTER_COUNT', 'string', NULL, 'api', 'Stores the running total number of API accesses, incremented automatically when API_COUNTER_ENABLED is on.', 'Written in api/class/api_access.class.php:304 via dolibarr_set_const, incrementing its own current value by 1 on each API key authentication (only when API_COUNTER_ENABLED is set and API_IN_TOKEN_TABLE is not).', 'This is a counter value maintained by the application itself; manually editing it only resets the starting count, it has no other effect on behavior.', 'Integer counter, auto-incremented by the code; no other meaning.', 1, 0, NULL, 1, 'b2ffe47c40a7d0a7029f425961726338f5b62150d2a28f252728330fc74fd966', 'v2', '2026-07-24T07:05:23+00:00', '["api/class/api_access.class.php:304|read|dolibarr_set_const($this->db, ''API_COUNTER_COUNT'', getDolGlobalInt(''API_COUNTER_COUNT'') + 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_COUNTER_ENABLED', 'bool', NULL, 'api', 'Enables counting of API accesses (incrementing a counter each time a user authenticates via API key).', 'Checked in api/class/api_access.class.php:300 inside the API key authentication check; when true, the code increments either a llx_const counter (API_COUNTER_COUNT) or, if API_IN_TOKEN_TABLE is set, columns in llx_oauth_token.', 'Enabling it causes every authenticated API call to trigger a counter update (extra DB write per call); disabling it skips the counting entirely.', 'Boolean-like: truthy enables API access counting.', 1, 0, NULL, 1, 'ccd756e35e021a1dd616100ef8087a8daedf726bae764b980aca6499b18563c1', 'v2', '2026-07-24T07:05:23+00:00', '["api/class/api_access.class.php:300|check|if (getDolGlobalString(''API_COUNTER_ENABLED'')) {", "api/class/api_access.class.php:304|read|dolibarr_set_const($this->db, ''API_COUNTER_COUNT'', getDolGlobalInt(''API_COUNTER_COUNT'') + 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_DISABLE_COMPRESSION', 'bool', NULL, 'api', 'Disables HTTP response compression for the Dolibarr REST API.', 'Set via api/admin/index.php and read at api/index.php:425. When set, compression is disabled and the response is output directly instead of using the compressed returnResponse handler. See comment: ''If API_DISABLE_COMPRESSION is set, returnResponse is false => It use default handling so output result directly.''', 'Disabling compression increases response size but removes the overhead of encoding; enabling compression (default) reduces bandwidth usage.', '0 or not set = compression enabled (if client accepts encoding); non-zero = compression disabled.', 0, 0, 'api/admin/index.php|api/admin/index.php', 1, 'bc8afe44c8a0800d929096efd8f905b1201f0b7ea586da358f008d3ca7554380', 'v2', '2026-04-21T11:16:15+00:00', '["api/index.php:424  // If API_DISABLE_COMPRESSION is set, returnResponse is false => It use default handling so output result directly.", "api/index.php:425|read|$usecompression = (!getDolGlobalString(''API_DISABLE_COMPRESSION'') && !empty($_SERVER[''HTTP_ACCEPT_ENCODING'']));", "api/admin/index.php:92|write|if (dolibarr_set_const($db, ''API_DISABLE_COMPRESSION'', GETPOSTINT(''status''), ''chaine'', 0, '''', 0) <= 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_ENABLE_COUNT_CALLS', 'bool', NULL, 'api', 'Enables counting of successful API calls per user.', 'Set via api/admin/index.php and checked at api/index.php:475 and user/card.php:2164. When enabled (or when $dolibarr_api_count_always_enabled is set), API call counts are recorded for users with an API key on successful (HTTP 200) responses.', 'Enabling this constant activates API call tracking; disabling it stops counting unless the global variable $dolibarr_api_count_always_enabled overrides it.', '0 or not set = call counting disabled (unless overridden by global variable); non-zero = call counting enabled.', 0, 0, 'api/admin/index.php|api/admin/index.php', 1, 'e12307589b72230226623e098431b27484ba08fabb54bdc037ef01f8c1317efc', 'v2', '2026-04-21T11:16:15+00:00', '["api/index.php:475|check|if ((getDolGlobalInt(\"API_ENABLE_COUNT_CALLS\") || !empty($dolibarr_api_count_always_enabled)) && $api->r->responseCode == 200) {", "user/card.php:2164|check|if ($object->api_key && (getDolGlobalString(''API_ENABLE_COUNT_CALLS'') || !empty($dolibarr_api_count_always_enabled))) {", "api/admin/index.php:99|write|if (dolibarr_set_const($db, ''API_ENABLE_COUNT_CALLS'', GETPOSTINT(''status''), ''chaine'', 0, '''', 0) <= 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_ENABLE_LOGIN_API', 'bool', NULL, 'api', 'Enables the API login endpoint that lets clients authenticate via the REST API.', 'Displayed/read in admin/system/security.php:796 (recommended value 0) and checked in api/class/api_login.class.php:44/101 and user/class/api_users.class.php:520.', 'When not enabled (default recommended value 0), the API login class and user API login refuse the request; enabling it opens the login-via-API surface.', 'Recommended: 0', 0, 0, 'admin/system/security.php', 1, '5b77164486b11f4e3ea269117631efaf34c9535eb8cfe7a594fcd6161dd9902e', 'v2', '2026-07-24T06:41:12+00:00', '["print ''<strong>API_ENABLE_LOGIN_API</strong> = ''.getDolGlobalString(''API_ENABLE_LOGIN_API'', ''0'').'' &nbsp; <span class=\"opacitymedium\">(''.$langs->trans(\"Recommended\").'': 0)</span>", "if (!getDolGlobalInt(''API_ENABLE_LOGIN_API'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_ENDPOINT_RULES', 'string', NULL, 'api', 'Defines access rules for API endpoints as a comma-separated list of endpoint:flag pairs.', 'Displayed in admin/system/security.php:789 and processed in api/index.php:369-371. A COMMENT shows the expected format: ''$conf->global->API_ENDPOINT_RULES = "endpoint1:1,endpoint2:1,..."''. The value is exploded by comma and each entry parsed to enforce endpoint-level access control.', 'Setting this restricts or grants access to specific API endpoints; an empty or undefined value means no endpoint-level rules are applied.', '''endpoint1:1,endpoint2:1,...'' — comma-separated list of endpoint name and access flag pairs; empty = no endpoint rules', 0, 0, 'admin/system/security.php', 1, '9ae38bb61996dd29eb1181ac187d54f66e482ed8c423c6f842eb929d69a80b75', 'v2', '2026-04-21T11:16:15+00:00', '["api/index.php:369  // $conf->global->API_ENDPOINT_RULES = ''endpoint1:1,endpoint2:1,...''", "api/index.php:370|check|if (getDolGlobalString(''API_ENDPOINT_RULES'')) {", "api/index.php:371|read|$listofendpoints = explode('','', getDolGlobalString(''API_ENDPOINT_RULES''));", "admin/system/security.php:789|read|print ''<strong>API_ENDPOINT_RULES</strong> = ''.getDolGlobalString(''API_ENDPOINT_RULES'', ...)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_EXPLORER_DISABLED', 'bool', NULL, 'api', 'Disables the Dolibarr API explorer (Redoc UI) and related explorer endpoints.', 'Checked at api/admin/explorer_withredoc.php:49 to block access to the explorer UI, and at api/index.php:146 to block explorer URLs via pattern match. Configured in api/admin/explorer_withredoc.php (listed in ADMIN_UI).', 'When enabled, the API explorer UI is inaccessible and requests to explorer URLs are rejected; when disabled, the API explorer is available.', '0 or not set = API explorer accessible; non-zero = API explorer disabled.', 0, 0, 'api/admin/explorer_withredoc.php', 1, 'd1b3953560cd775e216b2db95cda125a68e454bd80f73584d8e91c327f00bfd0', 'v2', '2026-04-21T11:16:15+00:00', '["api/admin/explorer_withredoc.php:49|check|if (getDolGlobalString(''API_EXPLORER_DISABLED'')) {", "api/index.php:146|check|if (preg_match(''/api\\/index\\.php\\/explorer/'', $url) && getDolGlobalString(''API_EXPLORER_DISABLED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_IN_TOKEN_TABLE', 'string', NULL, 'user', 'Enables use of the oauth_token database table for storing and validating API tokens instead of user profile tokens.', 'Checked in api/class/api_access.class.php (lines 137, 279), user/card.php (lines 1278, 2147, 2789), and core/lib/api.lib.php:44. The comment at user/card.php:2006 documents the purpose.', 'When enabled, API authentication uses the oauth_token table; when disabled, API tokens are managed via user profile fields.', 'Integer: 1 to enable oauth_token table for API tokens; 0 or unset to use the default.', 1, 0, NULL, 1, '9f1e6f216e22a2799a3fdbbb62b6297f7f8b6966d2a5ed87a69ff2d1f2e86499', 'v2', '2026-04-21T11:16:15+00:00', '["// API_IN_TOKEN_TABLE=1 to enable use of oaut_token table for API tokens", "api/class/api_access.class.php:279|check|if (!getDolGlobalString(''API_IN_TOKEN_TABLE'')) {", "core/lib/api.lib.php:44|check|if (getDolGlobalString(''API_IN_TOKEN_TABLE'')) {", "user/card.php:2147|check|if (getDolGlobalString(''API_IN_TOKEN_TABLE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_LOGINS_ALLOWED_FOR_CONST_READ', 'bool', NULL, 'api', 'Restricts the getConf/getConfs API endpoints (reading Dolibarr configuration constants) to admin users plus one specific non-admin login.', 'Checked in api/class/api_setup.class.php:2825 (getConf) and :2858 (getConfs), each rejecting non-admin callers with a 403 unless their login matches the constant. getConf() also blocks reading secret keys via isASecretKey().', 'Setting it to a login name grants that specific non-admin user API read access to configuration constants; leaving it unset restricts these endpoints to admins only.', 'String, a single Dolibarr user login allowed to call the const-read APIs as non-admin.', 0, 0, NULL, 1, '400caf3a281a3e8d05f266d47fbe859ddd64a2fe9a3a9b61f2bc90cc6bfd2ed3', 'v2', '2026-07-24T07:05:23+00:00', '["api/class/api_setup.class.php:2825|&& (!getDolGlobalString(''API_LOGINS_ALLOWED_FOR_CONST_READ'') || DolibarrApiAccess::$user->login != getDolGlobalString(''API_LOGINS_ALLOWED_FOR_CONST_READ''))) {", "api/class/api_setup.class.php| if (isASecretKey($constantname)) { throw new RestException(403, ''Forbidden. This parameter can not be read with APIs''); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_LOGINS_ALLOWED_FOR_GET_COMPANY', 'bool', NULL, 'api', 'Restricts the getCompany API endpoint to admin users plus one specific non-admin login.', 'Checked in api/class/api_setup.class.php:2692: a non-admin API caller is rejected with a 403 RestException (''Error API open to admin users only or to the users with logins defined into constant API_LOGINS_ALLOWED_FOR_GET_COMPANY'') unless their login matches the constant.', 'Setting it to a login name grants that specific non-admin user API access to read company (mysoc) info; leaving it unset restricts the endpoint to admins only.', 'String, a single Dolibarr user login allowed to call the getCompany API as non-admin.', 0, 0, NULL, 1, '2b88f9d46fa4029de3c9fdfb10d1e4cca2ab4da3afbadb6448dd71677a23c794', 'v2', '2026-07-24T07:05:23+00:00', '["api/class/api_setup.class.php:2692|&& (!getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_COMPANY'') || DolibarrApiAccess::$user->login != getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_COMPANY''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_LOGINS_ALLOWED_FOR_GET_EXTRAFIELDS', 'bool', NULL, 'api', 'Restricts the extrafields API endpoint (getListOfExtrafields) to admin users plus one specific non-admin login.', 'Checked in api/class/api_setup.class.php:1463: a non-admin API caller is rejected with a 403 RestException unless their login exactly matches the constant''s value.', 'Setting it to a login name grants that specific non-admin user API access to list extrafields; leaving it unset means only admin users can call this endpoint.', 'String, a single Dolibarr user login allowed to call the extrafields API as non-admin.', 0, 0, NULL, 1, 'e4d198eb9d155669b86afa09baf79220d6ade306b77558604d87b12a60e7555d', 'v2', '2026-07-24T07:05:23+00:00', '["api/class/api_setup.class.php:1463|&& (!getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_EXTRAFIELDS'') || DolibarrApiAccess::$user->login != getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_EXTRAFIELDS''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_LOGINS_ALLOWED_FOR_GET_MODULES', 'bool', NULL, 'api', 'Restricts the API endpoint for listing modules to a specific user login.', 'Read at api/class/api_setup.class.php:3179, :3205, and :3305: ''&& (!getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_MODULES'') || DolibarrApiAccess::$user->login != getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_MODULES''))''. No admin UI write path is present.', 'When set, only the user whose login matches the value can access the get-modules API endpoints; when empty, standard permission checks apply.', 'Empty/not set = standard permission check applies; login string = only this user login can access the get-modules endpoints.', 1, 0, NULL, 1, '5401092825ac42182d65fc87f7d20aff670ae093a441e8584dc46a780ba13342', 'v2', '2026-04-21T11:16:15+00:00', '["api/class/api_setup.class.php:3179|read|&& (!getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_MODULES'') || DolibarrApiAccess::$user->login != getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_MODULES''))) {", "api/class/api_setup.class.php:3205|read|&& (!getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_MODULES'') || DolibarrApiAccess::$user->login != getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_MODULES''))) {", "api/class/api_setup.class.php:3305|read|&& (!getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_MODULES'') || DolibarrApiAccess::$user->login != getDolGlobalString(''API_LOGINS_ALLOWED_FOR_GET_MODULES''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_LOGINS_ALLOWED_FOR_INTEGRITY_CHECK', 'bool', NULL, 'api', 'Restricts the getCheckIntegrity API endpoint to admin users plus one specific non-admin login.', 'Checked in api/class/api_setup.class.php:2903: a non-admin API caller is rejected with a 403 RestException unless their login matches the constant''s value.', 'Setting it to a login name grants that specific non-admin user API access to run the file integrity check endpoint; leaving it unset restricts it to admins only.', 'String, a single Dolibarr user login allowed to call the integrity-check API as non-admin.', 0, 0, NULL, 1, '9b10ce421ca0b95bebb44a709cc35624d4a2f3f5fdd01027b86c4626a13561b4', 'v2', '2026-07-24T07:05:23+00:00', '["api/class/api_setup.class.php:2903|&& (!getDolGlobalString(''API_LOGINS_ALLOWED_FOR_INTEGRITY_CHECK'') || DolibarrApiAccess::$user->login != getDolGlobalString(''API_LOGINS_ALLOWED_FOR_INTEGRITY_CHECK''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_PRODUCTION_DO_NOT_ALWAYS_REFRESH_CACHE', 'string', NULL, 'api', 'Controls whether the REST API''s routes.php cache file (used in production mode) is regenerated on every API call or reused across calls.', 'In api/index.php:189, a preceding comment (lines 186-188) explains: in production mode a cached api/temp/routes.php file lists the API routes seen so far; without forcing refresh on each call, a route for one API might be missing from the cache when a different API is called, causing a 404. $refreshcache is set to false only when this constant is set (and true otherwise, i.e. by default it always refreshes).', 'When set, the API route cache is not forced to refresh on every call (better performance in production), but risks 404 errors when switching between different API endpoints not yet present in the cached routes.php; when unset (default), the cache is refreshed on every call, avoiding that 404 risk at a performance cost.', 'Not set/falsy (default): $refreshcache = true (always refresh route cache). Truthy: $refreshcache = false (cache reused, not always refreshed).', 1, 0, NULL, 1, 'de59561f1927ff5c28b826aca6db360d2da5e0c908c07d490d58f1971d5bafb6', 'v2', '2026-07-24T07:05:23+00:00', '["api/index.php:186-188|comment|// When in production mode, a file api/temp/routes.php is created... if we set $refreshcache to false... an API is not into the api/temp/routes.php and a 404 is returned. So we force refresh to each call.", "api/index.php:189|read|$refreshcache = (getDolGlobalString(''API_PRODUCTION_DO_NOT_ALWAYS_REFRESH_CACHE'') ? false : true);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_PRODUCTION_MODE', 'string', NULL, 'api', 'Switches the REST API between production mode (strict) and development/debug mode.', 'Configured via api/admin/index.php (written at line 63, read at line 145). Also read in api/class/api.class.php:62 to set the $production_mode flag that controls API error verbosity.', 'When enabled, the API runs in production mode with reduced error detail; when disabled, more verbose debug information is returned.', 'Boolean string: truthy to enable production mode; falsy/unset for development mode.', 0, 0, 'api/admin/index.php|api/admin/index.php', 1, 'cb8746ff2f81196636f7f52a5b45adbadf04ed6cda296efcb6e3e75c4044fde7', 'v2', '2026-04-21T11:16:15+00:00', '["api/admin/index.php:63|write|if (dolibarr_set_const($db, ''API_PRODUCTION_MODE'', $status, ''chaine'', 0, '''', 0) > 0) {", "api/admin/index.php:145|read|$production_mode = getDolGlobalBool(''API_PRODUCTION_MODE'');", "api/class/api.class.php:62|read|$production_mode = getDolGlobalBool(''API_PRODUCTION_MODE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('API_RESTRICT_ON_IP', 'string', NULL, 'api', 'Restricts API access to a space-separated list of allowed IP addresses.', 'Configured via api/admin/index.php and checked at api/index.php:225 and api/admin/explorer_withredoc.php:58. When set, incoming requests are validated against the list; non-matching IPs are logged and denied. Value is split by space: ''$allowedip = explode('' '', getDolGlobalString(''API_RESTRICT_ON_IP''))''.', 'Setting a non-empty value blocks all API access from IPs not in the list; leaving it empty allows access from any IP.', 'Empty/not set = no IP restriction; space-separated IP addresses = only those IPs are allowed.', 0, 0, 'api/admin/index.php|api/admin/explorer_withredoc.php|api/admin/explorer_withredoc.php|api/admin/explorer_withredoc.php|api/admin/index.php', 1, 'e7aed798365d8a76015bd4292f8b6753d695ef76e17f7ef47599d7dac51e107d', 'v2', '2026-04-21T11:16:15+00:00', '["api/admin/explorer_withredoc.php:59|read|$allowedip = explode('' '', getDolGlobalString(''API_RESTRICT_ON_IP''));", "api/index.php:226|read|$allowedip = explode('' '', getDolGlobalString(''API_RESTRICT_ON_IP''));", "api/index.php:229|read|dol_syslog(''Remote ip is ''.$ipremote.'', not into list '' . getDolGlobalString(''API_RESTRICT_ON_IP''));", "api/admin/index.php:105|write|if (dolibarr_set_const($db, ''API_RESTRICT_ON_IP'', GETPOST(''API_RESTRICT_ON_IP'', ''alpha'')) <= 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASSET_ACCOUNTANCY_CATEGORY', 'string', NULL, 'core', 'Defines the accounting account type/category (''pcg_type'') used to detect whether a product''s buy accounting code corresponds to an asset account.', 'In core/tpl/objectline_view.tpl.php:651-664, the object line view builds a SQL query against llx_accounting_account filtering on pcg_type = this constant''s value, combined with the product''s accountancy_code_buy(/_intra/_export) codes, to decide whether to show asset-related UI on the line.', 'Setting it to a valid pcg_type value in the chart of accounts enables detection of asset accounts on product lines for the asset-related display logic; an incorrect or unset value means no accounting_account rows match and the asset check silently finds nothing.', 'String: must match a pcg_type value used in the llx_accounting_account table (chart-of-accounts account type/category code).', 1, 0, NULL, 1, '1daf049af20d456ad6e6e950cb4cf9fc76c672fe216ebb18b53448a2136f974e', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_view.tpl.php:651|read|$accountancy_category_asset = getDolGlobalString(''ASSET_ACCOUNTANCY_CATEGORY'');", "core/tpl/objectline_view.tpl.php:664|read|$sql .= \" WHERE pcg_type = ''\" . $this->db->escape($conf->global->ASSET_ACCOUNTANCY_CATEGORY) . \"''\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASSET_ADVANCED_MASK', 'string', NULL, 'core', 'Numbering mask (template pattern) used by the ''Advanced'' numbering module for Asset references.', 'Read/written by the mod_asset_advanced numbering module (core/modules/asset/mod_asset_advanced.php:85,130): the admin setup page shows an input pre-filled with this value and getNextValue() uses it as the mask to compute the next Asset ref. If empty, ref generation returns ''NotConfigured''.', 'Changing the mask changes the format of future Asset references generated by this numbering module (prefix/date/counter placeholders per GenericMaskCodes tooltip); does not affect already-assigned refs.', 'Free-form mask string using Dolibarr''s generic mask code syntax (e.g. {000000} for counter, {yy}{mm} for date parts) as documented by the GenericMaskCodes translation strings shown in the tooltip; no fixed enum found in payload.', 0, 0, NULL, 1, '8f2e8c690fabf3743c3a9c9ac06a3170f50068750802436003484b6b1a9c7e2b', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/asset/mod_asset_advanced.php:130|read|$mask = getDolGlobalString(''ASSET_ADVANCED_MASK'');", "core/modules/asset/mod_asset_advanced.php:85|read|...value=\"''.getDolGlobalString(''ASSET_ADVANCED_MASK'').''\">''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASSET_ASSET_ADDON', 'string', NULL, 'asset', 'Specifies the numbering module class name used to generate asset reference numbers.', 'Read in asset/class/asset.class.php:1662 to determine the active numbering add-on. If not set, the default ''mod_asset_standard'' is applied (asset/class/asset.class.php:1655). The class name is also used to build the include file path.', 'Changing this constant selects a different numbering scheme for assets; an invalid class name will cause asset reference generation to fail.', 'String class name of a numbering module (e.g. ''mod_asset_standard'')', 1, 0, NULL, 1, 'f1baa8e89f781a61a917fd165dd0eb763c654fe48570ed7798290f565b1d3c95', 'v2', '2026-04-21T13:29:58+00:00', '["asset/class/asset.class.php:1654|check|if (!getDolGlobalString(''ASSET_ASSET_ADDON'')) {", "asset/class/asset.class.php:1655|write|$conf->global->ASSET_ASSET_ADDON = ''mod_asset_standard'';", "asset/class/asset.class.php:1661|read|$file = getDolGlobalString(''ASSET_ASSET_ADDON'') . \".php\";", "asset/class/asset.class.php:1662|read|$classname = getDolGlobalString(''ASSET_ASSET_ADDON'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASSET_ASSET_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies the directory path(s) for ODT document templates used by the generic asset ODT module.', 'Read in doc_generic_asset_odt.modules.php at line 136 (split into list of dirs), line 164 (display in UI), and line 176 (existence check). No admin UI write via dolibarr_set_const is present in the payload.', 'Changing this path redirects the module to a different set of ODT template directories; an invalid path disables ODT template loading.', 'Comma-separated directory path(s); empty = no custom ODT path.', 1, 0, NULL, 1, 'a28c715a3ad85622cdb7a6174b875116e54272bb80e1e7fcd299dc90fe037efb', 'v2', '2026-04-21T13:50:40+00:00', '["doc_generic_asset_odt.modules.php:136|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''ASSET_ASSET_ADDON_PDF_ODT_PATH''))));", "doc_generic_asset_odt.modules.php:164|read|$texte .= getDolGlobalString(''ASSET_ASSET_ADDON_PDF_ODT_PATH'');", "doc_generic_asset_odt.modules.php:176|check|if (getDolGlobalString(''ASSET_ASSET_ADDON_PDF_ODT_PATH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASSET_DEPRECIATION_DURATION_PER_MONTH', 'string', NULL, 'asset', 'Sets the number of days considered as one full month when computing asset depreciation amounts.', 'Read via getDolGlobalInt(''ASSET_DEPRECIATION_DURATION_PER_MONTH'', 30) in asset/class/asset.class.php:1100, used analogously to the per-year constant for monthly depreciation-type assets: depreciation_ht = period_amount * nb_days / nb_days_in_month.', 'Changing the value changes the proration base for monthly depreciation lines (duration_type == 1); default is 30 days if unset.', 'Integer number of days representing a full month for depreciation proration; default 30 when not set.', 0, 0, NULL, 1, '981851a7492510dd3b65dcda35ad11a492069368938e6489a0873e43370f9b11', 'v2', '2026-07-24T07:05:23+00:00', '["asset/class/asset.class.php:1100|read|$nb_days_in_month = getDolGlobalInt(''ASSET_DEPRECIATION_DURATION_PER_MONTH'', 30);", "asset/class/asset.class.php: nb_days = min($nb_days_in_month, num_between_day($begin_date, $end_date, 1));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASSET_DEPRECIATION_DURATION_PER_YEAR', 'string', NULL, 'asset', 'Sets the number of days considered as one full year when computing asset depreciation amounts.', 'Read via getDolGlobalInt(''ASSET_DEPRECIATION_DURATION_PER_YEAR'', 360) in asset/class/asset.class.php:1099, used to compute annual depreciation share as period_amount * nb_days_real / nb_days_in_year. It is exposed in the Assets module admin setup (asset/admin/setup.php: ''ASSET_DEPRECIATION_DURATION_PER_YEAR'' => array(''type'' => ''string'', ...)) and has a translated help label in langs/*/assets.lang (''Proportional period in days for calculating amortization over one year'').', 'Changing the value changes the proration base for annual depreciation lines: a smaller value increases the daily depreciation rate for a given period, a larger value decreases it. Default is 360 days if unset.', 'Integer number of days representing a full year for depreciation proration; default 360 when not set.', 0, 0, NULL, 1, 'e6ef73c61324b067bd7acef212e87639124caeb155e041f9be47864a1217e9bd', 'v2', '2026-07-24T07:05:23+00:00', '["asset/class/asset.class.php:1099|read|$nb_days_in_year = getDolGlobalInt(''ASSET_DEPRECIATION_DURATION_PER_YEAR'', 360);", "asset/admin/setup.php:60|''ASSET_DEPRECIATION_DURATION_PER_YEAR'' => array(''type'' => ''string'', ''css'' => ''minwidth200'', ''enabled'' => 1),", "langs/fr_FR/assets.lang:38|ASSET_DEPRECIATION_DURATION_PER_YEAR=Période proportionnelle en jours pour le calcul de l''amortissement sur un an"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASSET_DISPOSAL_VAT', 'string', NULL, 'accountancy', 'VAT rate (percent) applied to the disposal line of a fixed asset when computing its accounting entries, defaulting to 20 if unset or non-positive.', 'Read in accountancy/class/accountingjournal.class.php:618, guarded by a condition using ACCOUNTING_DATE_START_BINDING; used to compute the disposal_vat value for the asset disposal accounting block.', 'Setting a positive value changes the VAT rate used for the fixed-asset disposal accounting line; if unset or <=0, the code falls back to a hardcoded 20% rate.', 'A VAT rate as an integer/percent; getDolGlobalInt(''ASSET_DISPOSAL_VAT'') > 0 uses that value, otherwise defaults to 20.', 0, 0, NULL, 1, 'ac585f3997fea5101ac19c436384e981013faecf72bfc34f1f8737145afd4d11', 'v2', '2026-07-24T07:05:23+00:00', '["accountingjournal.class.php:618: $disposal_vat = getDolGlobalInt(''ASSET_DISPOSAL_VAT'') > 0 ? getDolGlobalInt(''ASSET_DISPOSAL_VAT'') : 20;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASSET_ROUND_INTEGER_NUMBER_UPWARDS', 'string', NULL, 'asset', 'Rounds computed depreciation line amounts up to the nearest integer (ceil) instead of using the raw decimal value, except for the last depreciation line.', 'Checked at asset/class/asset.class.php:1156: `if (getDolGlobalInt(''ASSET_ROUND_INTEGER_NUMBER_UPWARDS'') == 1) { if ($idx_loop < $max_loop) { $depreciation_ht = ceil($depreciation_ht); } }`.', 'When set to 1, every depreciation amount computed for a period (except the final one in the loop) is rounded up with ceil(), which slightly increases early depreciation amounts and correspondingly reduces the final period''s residual amount.', 'Integer: 1 = round depreciation amounts upwards (ceil) except on the last period; any other value/unset = use raw computed amount.', 0, 0, NULL, 1, '88390a594662f28d120a244ef268aff7a064dedda15ed1ec9715c3c58c6af709', 'v2', '2026-07-24T07:05:23+00:00', '["asset/class/asset.class.php:1156|check|if (getDolGlobalInt(''ASSET_ROUND_INTEGER_NUMBER_UPWARDS'') == 1) {", "if ($idx_loop < $max_loop) { // avoid last depreciation value\\n\\t\\t\\t\\t\\t\\t\\t$depreciation_ht = ceil($depreciation_ht);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASTERISK_CONTEXT', 'string', NULL, 'asterisk', 'Asterisk dialplan context used when originating calls via the click-to-dial (clicktodial) wrapper.', 'Read in asterisk/wrapper.php:144 with default ''from-internal''; inline comment notes it is ''generalement from-internal'' (generally from-internal). CONF_PHP_WIRING: no admin UI page found; set via constant editor/conf.php.', 'Setting it changes which Asterisk dialplan context is used to originate the call; if unset, defaults to ''from-internal''.', 'String: an Asterisk dialplan context name. Default (if unset): ''from-internal''.', 1, 0, NULL, 1, '8ccd3f414549011bdbdeb93bf285ede43fa2df2a5a52ece010b7e8d6b03b6fb5', 'v2', '2026-07-24T07:05:23+00:00', '["asterisk/wrapper.php:144|read|$strContext = getDolGlobalString(''ASTERISK_CONTEXT'', ''from-internal'');", "// Context ( generalement from-internal )"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASTERISK_HOST', 'string', NULL, 'asterisk', 'IP address or hostname of the Asterisk PBX server used by the click-to-dial (clicktodial) wrapper.', 'Read in asterisk/wrapper.php:131 with default ''127.0.0.1''; used to build the connection target for the Asterisk Manager Interface call in the click-to-dial wrapper script (CONF_PHP_WIRING: this constant has no admin UI page and appears set only via constant editor/conf.php).', 'Setting it points the click-to-dial wrapper at a specific Asterisk server; if unset, it defaults to 127.0.0.1 (localhost).', 'String: IP address or hostname. Default (if unset): ''127.0.0.1''.', 1, 0, NULL, 1, '62e632bd2116c277d95dfccd485033c6f7685be84e56710b4e7836b3408b67f4', 'v2', '2026-07-24T07:05:23+00:00', '["asterisk/wrapper.php:131|read|$strHost = getDolGlobalString(''ASTERISK_HOST'', ''127.0.0.1'');", "// IP address of Asterisk server"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASTERISK_INDICATIF', 'string', NULL, 'asterisk', 'Sets the country/area dialling prefix used by the Asterisk click-to-call wrapper when placing outbound calls.', 'Checked in asterisk/wrapper.php:115: if set to ''NONE'', the value is cleared to an empty string. Read at asterisk/wrapper.php:138 with a default of ''0''.', 'Setting this to ''NONE'' strips any prefix from dialled numbers; setting it to a string prepends that string as a dialling prefix; leaving it empty uses ''0'' as the default prefix.', '''NONE'' = no prefix used; any other string = used as dialling prefix; default ''0'' when empty.', 1, 0, NULL, 1, '0d88ee5b8b236068a957d7b348fad6c43022564f84a1af8b0f75ae09c681c839', 'v2', '2026-04-21T11:16:15+00:00', '["asterisk/wrapper.php:115|check|if (getDolGlobalString(''ASTERISK_INDICATIF'') == ''NONE'') {", "asterisk/wrapper.php:116|write|$conf->global->ASTERISK_INDICATIF = '''';", "asterisk/wrapper.php:138|read|$prefix = getDolGlobalString(''ASTERISK_INDICATIF'', ''0'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASTERISK_MAX_RETRY', 'string', NULL, 'asterisk', 'Maximum number of call attempts (retries) used when originating calls via the click-to-dial (clicktodial) wrapper.', 'Read in asterisk/wrapper.php:153 with default "2"; inline comment: ''Number of call attempts''. CONF_PHP_WIRING: no admin UI page found; set via constant editor/conf.php.', 'Setting it changes how many times Asterisk retries originating the call; if unset, defaults to 2 attempts.', 'String/integer: number of retry attempts. Default (if unset): ''2''.', 1, 0, NULL, 1, 'b813913a4fa4900eecbc222f5bf864ab3d0a5842d4bce3b986494f08a0c8468c', 'v2', '2026-07-24T07:05:23+00:00', '["asterisk/wrapper.php:153|read|$strMaxRetry = getDolGlobalString(''ASTERISK_MAX_RETRY'', \"2\");", "// Number of call attempts"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASTERISK_PORT', 'string', NULL, 'asterisk', 'TCP port of the Asterisk Manager Interface used by the click-to-dial (clicktodial) wrapper.', 'Read via getDolGlobalInt() in asterisk/wrapper.php:141 with default 5038, the standard Asterisk Manager Interface (AMI) port. CONF_PHP_WIRING: no admin UI page found; set via constant editor/conf.php.', 'Setting it points the click-to-dial wrapper at a non-default AMI port; if unset, defaults to 5038.', 'Integer: TCP port number. Default (if unset): 5038.', 1, 0, NULL, 1, '65cb739d9d91b8d19024e2ae2e5182ecc296de846acf2695c29c6728a985dec8', 'v2', '2026-07-24T07:05:23+00:00', '["asterisk/wrapper.php:141|read|$port = getDolGlobalInt(''ASTERISK_PORT'', 5038);", "// Asterisk Port"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASTERISK_PRIORITY', 'string', NULL, 'asterisk', 'Dialplan priority used when originating calls via the click-to-dial (clicktodial) wrapper.', 'Read in asterisk/wrapper.php:150 with default ''1''. CONF_PHP_WIRING: no admin UI page found; set via constant editor/conf.php.', 'Setting it changes which dialplan priority step Asterisk starts the call at; if unset, defaults to ''1''.', 'String/integer: Asterisk dialplan priority number. Default (if unset): ''1''.', 1, 0, NULL, 1, '4dfa3dff2b7ae41754f4da2539beed91915cbfa7c5714d439a3f74788cf56bdf', 'v2', '2026-07-24T07:05:23+00:00', '["asterisk/wrapper.php:150|read|$strPriority = getDolGlobalString(''ASTERISK_PRIORITY'', ''1'');", "// Priority"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASTERISK_TYPE', 'string', NULL, 'asterisk', 'Asterisk channel technology/prefix used to build the dial string in the click-to-dial (clicktodial) wrapper.', 'Read in asterisk/wrapper.php:135 with default ''SIP/''; the inline comment explains it specifies ''the type of extension through which your extension is connected'' (e.g. SIP/, IAX2/, ZAP/). CONF_PHP_WIRING: no admin UI page found; set via constant editor/conf.php.', 'Setting it changes the channel technology prefix used when originating calls through Asterisk (e.g. switching from SIP/ to IAX2/ or ZAP/); if unset, defaults to ''SIP/''.', 'String: channel prefix, e.g. ''SIP/'', ''IAX2/'', ''ZAP/''. Default (if unset): ''SIP/''.', 1, 0, NULL, 1, '637c91ec0c834a4e01ce8fc3063cc54c7bdd042f057a7e1d1e975be1cb4c51fa', 'v2', '2026-07-24T07:05:23+00:00', '["asterisk/wrapper.php:135|read|$channel = getDolGlobalString(''ASTERISK_TYPE'', ''SIP/'');", "// Specify the type of extension through which your extension is connected.", "// ex: SIP/, IAX2/, ZAP/, etc"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ASTERISK_WAIT_TIME', 'string', NULL, 'asterisk', 'Number of seconds to wait before hanging up an unanswered call originated via the click-to-dial (clicktodial) wrapper.', 'Read in asterisk/wrapper.php:147 with default ''30''; inline comment: ''Waiting time before hanging up''. CONF_PHP_WIRING: no admin UI page found; set via constant editor/conf.php.', 'Setting it changes how long Asterisk waits for the call to be answered before hanging up; if unset, defaults to 30 seconds.', 'String/integer: number of seconds. Default (if unset): ''30''.', 1, 0, NULL, 1, '281d0c168a27af79ef253c4c47555f03115e17f692546bd7834f75a82176b9b7', 'v2', '2026-07-24T07:05:23+00:00', '["asterisk/wrapper.php:147|read|$strWaitTime = getDolGlobalString(''ASTERISK_WAIT_TIME'', ''30'');", "// Waiting time before hanging up"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AUDIT_ENABLE_PREFIX_SESSION', 'bool', NULL, 'admin', 'Enables display of the ''UserAgent'' (prefix_session) column in the security events (audit log) list.', 'Read twice in admin/tools/listevents.php (lines 127-128): ''checked'' => getDolGlobalInt(''AUDIT_ENABLE_PREFIX_SESSION''), ''enabled'' => getDolGlobalInt(''AUDIT_ENABLE_PREFIX_SESSION'') for the ''e.prefix_session'' column entry in $arrayfields.', 'When enabled, the audit/security events list page shows (and allows toggling) a ''UserAgent'' column sourced from e.prefix_session; when disabled, that column is neither shown nor available in the column picker.', 'Boolean/int: 1 enables and marks the prefix_session column as checked/enabled in the events list.', 0, 0, 'admin/tools/listevents.php|admin/tools/listevents.php', 1, '29f7840d6ca3a66ad545e54ff3ea766da139c404550db981dc6117c0952f7ff8', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/listevents.php:127: ''checked'' => getDolGlobalInt(''AUDIT_ENABLE_PREFIX_SESSION''),", "admin/tools/listevents.php:128: ''enabled'' => getDolGlobalInt(''AUDIT_ENABLE_PREFIX_SESSION''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('AVAILABILITIES_ADDON_PDF', 'string', NULL, 'bookcal', 'Names the default PDF document model used to generate ''availabilities'' (bookcal) documents.', 'Read in bookcal/class/availabilities.class.php:964-965 inside generateDocument(), as fallback model name (''standard_availabilities'' otherwise) when no object-specific model_pdf is set.', 'Setting it changes which PDF template (registered under core/modules/bookcal/doc/) is used by default when generating an availabilities document.', 'String: name of a registered bookcal/availabilities PDF document model (fallback default is ''standard_availabilities'').', 1, 0, NULL, 1, '1b045387bcdeff2f37ea38804ebc6d21142d1db4feeb82610bcfa84aa5626ea0', 'v2', '2026-07-24T07:05:23+00:00', '["bookcal/class/availabilities.class.php:964|read|} elseif (getDolGlobalString(''AVAILABILITIES_ADDON_PDF'')) {", "bookcal/class/availabilities.class.php:965|read|$modele = getDolGlobalString(''AVAILABILITIES_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANKADDON_PDF', 'string', NULL, 'admin', 'Specifies the PDF template module used to generate bank account (RIB) documents.', 'Set via admin/bank.php UI. Read in societe/paymentmodes.php:1724-1725 to select the model and in public/onlinesign/newonlinesign.php:567 as the default template for online signing. 9 occurrences across admin and runtime files.', 'Changing this value switches the PDF template used for RIB/bank account document generation including for online signing.', 'String: name of the PDF addon module; empty = no default template selected', 0, 0, 'admin/bank.php|admin/bank.php|admin/bank.php|admin/bank.php|admin/bank.php', 1, '47d83b32ed5971734f29c0ef43374149195fe0d879ef512de748cee8d24c7376', 'v2', '2026-04-21T11:16:15+00:00', '["admin/bank.php:201|write|if (dolibarr_set_const($db, \"BANKADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "societe/paymentmodes.php:1724|check|if (getDolGlobalString(''BANKADDON_PDF'')) {", "public/onlinesign/newonlinesign.php:567|read|$defaulttemplate = getDolGlobalString(\"BANKADDON_PDF\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_ACCOUNT_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'societe', 'Enables an external (unauthenticated share-link) direct download link for bank account documents on the thirdparty card.', 'Checked in societe/paymentmodes.php:1950 to conditionally show the direct-download link for the company bank account ECM file, and in core/class/commonobject.class.php:6394 where, for element ''bank_account'', it sets $setsharekey = true (same pattern used by PROPOSAL/INVOICE/CONTRACT/SUPPLIER_PROPOSAL _ALLOW_EXTERNAL_DOWNLOAD constants).', 'When enabled, a public share key is generated for bank_account documents, allowing them to be downloaded via a direct external link without login.', 'Boolean: truthy allows generating an external download share link for bank account docs; unset/false disables it.', 1, 0, NULL, 1, '58afcf9420e2111aa73f422df56ffbd3fc7b1077706757674c160539210b3871', 'v2', '2026-07-24T07:05:23+00:00', '["societe/paymentmodes.php:1950|check|if (getDolGlobalString(''BANK_ACCOUNT_ALLOW_EXTERNAL_DOWNLOAD'')) {", "core/class/commonobject.class.php:6394|check|if ($this->element == ''bank_account'' && getDolGlobalInt(\"BANK_ACCOUNT_ALLOW_EXTERNAL_DOWNLOAD\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_ALLOW_TRANSACTION_DELETION_EVEN_IF_IN_ACCOUNTING', 'bool', NULL, 'compta', 'Allows deletion of bank transaction lines even if they have already been transferred/booked into accounting, bypassing the default protection.', 'Checked in compta/bank/class/account.class.php:2422 (comment at line 2421: ''Protection to avoid any delete of accounted lines. Protection on by default''); when NOT set, the code queries llx_accounting_bookkeeping for matching entries and blocks deletion if any exist.', 'When set, bank lines already recorded in accounting can be deleted, risking inconsistency between bank records and the accounting ledger; when unset (default), deletion of accounted bank lines is blocked.', 'Not set/falsy (default): deletion of accounted bank lines blocked (protection on). Truthy: deletion allowed even if the line is already in accounting.', 1, 0, NULL, 1, '94b14414c0a9e52390c4fb69c7f0042b4f19ab3c0ce0babfb6bb4c17814c0dc4', 'v2', '2026-07-24T07:05:23+00:00', '["compta/bank/class/account.class.php:2421|comment|// Protection to avoid any delete of accounted lines. Protection on by default", "compta/bank/class/account.class.php:2422|check|if (!getDolGlobalString(''BANK_ALLOW_TRANSACTION_DELETION_EVEN_IF_IN_ACCOUNTING'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_ASK_PAYMENT_BANK_DURING_ORDER', 'string', NULL, 'commande', 'Prompts the user to select a bank account during order creation or validation.', 'Written via dolibarr_set_const at admin/order.php:234. Checked in commande/card.php:2422 and :3257 to display bank account selection. Also checked in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:128 to decide whether to inherit the bank account from the third party.', 'Enabling this displays a bank account selector during order processing; disabling skips that prompt and falls back to inheriting the account from the customer.', '0 or empty = bank account not requested during order; non-empty = bank account selector shown', 0, 0, 'admin/order.php', 1, 'e0b029774d0465521529b9f3abe1ce1b03c1565bb26b70e15064204cdf560d1b', 'v2', '2026-04-21T11:16:15+00:00', '["admin/order.php:234|write|$res = dolibarr_set_const($db, \"BANK_ASK_PAYMENT_BANK_DURING_ORDER\", $value, ''chaine'', 0, '''', $conf->entity);", "commande/card.php:2422|check|if (getDolGlobalString(''BANK_ASK_PAYMENT_BANK_DURING_ORDER'') && isModEnabled(\"bank\")) {", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:128|check|if (empty($object->fk_account) && !empty($object->thirdparty->fk_account) && !getDolGlobalInt(''BANK_ASK_PAYMENT_BANK_DURING_ORDER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_ASK_PAYMENT_BANK_DURING_PROPOSAL', 'string', NULL, 'supplier_proposal', 'Enables display of a bank account selection field on supplier and customer proposal forms.', 'Written via admin/propal.php (line 172). Checked across 5 occurrences in supplier_proposal/card.php (lines 1615, 2079) and comm/propal/card.php (lines 2473, 3293), always conditioned on the bank module being enabled.', 'Enabling this setting adds a bank account selector to the proposal validation workflow.', 'Truthy string (non-empty) = bank selector shown on proposals; empty/not set = bank selector hidden.', 0, 0, 'admin/propal.php', 1, '18aaaee4ba662d4b906a7b02db54adac63d2b8ca793b157e9d963ab75406e6d3', 'v2', '2026-04-21T11:16:15+00:00', '["admin/propal.php:172|write|$res = dolibarr_set_const($db, \"BANK_ASK_PAYMENT_BANK_DURING_PROPOSAL\", $value, ''chaine'', 0, '''', $conf->entity);", "supplier_proposal/card.php:1615|check|if (getDolGlobalString(''BANK_ASK_PAYMENT_BANK_DURING_PROPOSAL'') && isModEnabled(\"bank\")) {", "comm/propal/card.php:2473|check|if (getDolGlobalString(''BANK_ASK_PAYMENT_BANK_DURING_PROPOSAL'') && isModEnabled(\"bank\")) {", "comm/propal/card.php:3293|check|if (getDolGlobalString(''BANK_ASK_PAYMENT_BANK_DURING_PROPOSAL'') && isModEnabled(\"bank\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_ASK_PAYMENT_BANK_DURING_SUPPLIER_ORDER', 'string', NULL, 'fourn', 'Controls whether the user is prompted to select a bank account for payment when creating/handling a supplier order.', 'Set via supplier_order/admin/supplier_order.php:210 (dolibarr_set_const) and checked in fourn/commande/card.php at lines 2066 and 2576, combined with a check that the bank module is enabled.', 'When enabled and the bank module is active, the supplier order workflow asks for a payment bank account; otherwise this prompt is skipped.', NULL, 0, 0, 'supplier_order/admin/supplier_order.php', 1, 'e5f1521bbd3902e758225716e31a4d9cfd137ee71f7f62b4dc620457246a2419', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''BANK_ASK_PAYMENT_BANK_DURING_SUPPLIER_ORDER'') && isModEnabled(\"bank\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_ASK_PAYMENT_BANK_DURING_SUPPLIER_PROPOSAL', 'string', NULL, 'supplier_proposal', 'Controls whether the bank account to be paid is asked for when creating/managing a supplier proposal.', 'Written from supplier_proposal/admin/supplier_proposal.php:164 via dolibarr_set_const() when the admin saves the supplier proposal module setup form.', 'Changing it toggles a bank-account prompt/behavior tied to supplier proposals; exact effect on the proposal workflow is not detailed in the available evidence.', 'Not specified in the available evidence ($value submitted from the setup form, likely a 0/1 toggle given the constant''s name).', 0, 0, 'supplier_proposal/admin/supplier_proposal.php', 1, '1f205e161d8fbd1c4b65731be9c4e1887907e528cf9a36eef288cd4d18fb7c07', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_proposal/admin/supplier_proposal.php:164|write|$res = dolibarr_set_const($db, \"BANK_ASK_PAYMENT_BANK_DURING_SUPPLIER_PROPOSAL\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_CAN_RECONCILIATE_CASHACCOUNT', 'string', NULL, 'compta', 'Allows bank reconciliation to be performed on cash-type accounts.', 'By default, reconciliation is blocked for accounts of type TYPE_CASH. Setting this constant enables reconciliation for cash accounts. Checked in compta/bank/class/account.class.php:487 and :1501, and in core/lib/bank.lib.php:103.', 'Without this constant, cash accounts are excluded from reconciliation flows. Enabling it lifts that restriction.', '0 or empty = cash accounts cannot be reconciled; non-empty = cash accounts can be reconciled', 1, 0, NULL, 1, '7fd44d4c9cb87d80d56d07d48b3c8419120ba37660902d9c011527b0488c72b3', 'v2', '2026-04-21T11:16:15+00:00', '["compta/bank/class/account.class.php:487|check|if ($this->type == Account::TYPE_CASH && !getDolGlobalString(''BANK_CAN_RECONCILIATE_CASHACCOUNT'')) {", "compta/bank/class/account.class.php:1501|check|if (!getDolGlobalString(''BANK_CAN_RECONCILIATE_CASHACCOUNT'')) {", "core/lib/bank.lib.php:103|check|if ($object->type != Account::TYPE_CASH || getDolGlobalString(''BANK_CAN_RECONCILIATE_CASHACCOUNT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_CAN_REOPEN_DIRECT_DEBIT_OR_CREDIT_TRANSFER', 'string', NULL, 'compta', 'Allows reopening a direct debit or credit transfer batch that is already in a debited/credited status.', 'Checked in compta/prelevement/card.php:450 and compta/prelevement/requests.php:448; when true and the BonPrelevement status is STATUS_DEBITED or STATUS_CREDITED, a ''ReOpen'' action button is displayed.', 'Enabling it exposes a ReOpen button on completed direct-debit/credit-transfer batches, allowing their status to be reverted, gated by the prelevement debit/credit user rights.', 'Boolean-like: any truthy value shows the ReOpen button for debited/credited batches.', 1, 0, NULL, 1, '327359df8d9287290fc3bc35f40c8e6ab84253e6bccf8378e92cd82c6c8556d9', 'v2', '2026-07-24T07:05:23+00:00', '["compta/prelevement/card.php:450: if (getDolGlobalString(''BANK_CAN_REOPEN_DIRECT_DEBIT_OR_CREDIT_TRANSFER'')) {", "compta/prelevement/requests.php:448: if (getDolGlobalString(''BANK_CAN_REOPEN_DIRECT_DEBIT_OR_CREDIT_TRANSFER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_CHEQUERECEIPT_FREE_TEXT', 'string', NULL, 'admin', 'Free text saved from the cheque deposit slip (chequereceipts) admin setup and printed on the cheque receipt PDF.', 'Set via admin/chequereceipts.php:96 (action ''set_BANK_CHEQUERECEIPT_FREE_TEXT'', dolibarr_set_const) and consumed by core/modules/cheque/doc/pdf_blochet.class.php:446 as the free-text parameter for the cheque receipt PDF model.', 'Changing the value changes the footer free text printed on generated cheque deposit receipt PDFs; no other effect found.', 'Any HTML/restricted-HTML string entered by the admin (GETPOST ''restricthtml'' filter); empty means no free text.', 0, 0, 'admin/chequereceipts.php', 1, 'ccf0cb8cbf6ab147406857b4c9d175f6be29ec01841bd0144cfe95e84e4ea3c9', 'v2', '2026-07-24T07:05:23+00:00', '["admin/chequereceipts.php:96|write|$res = dolibarr_set_const($db, \"BANK_CHEQUERECEIPT_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);", "admin/chequereceipts.php:94: $freetext = GETPOST(''BANK_CHEQUERECEIPT_FREE_TEXT'', ''restricthtml''); // No alpha here, we want exact string", "core/modules/cheque/doc/pdf_blochet.class.php:446: $paramfreetext = ''BANK_CHEQUERECEIPT_FREE_TEXT'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_COLORIZE_MOVEMENT', 'string', NULL, 'admin', 'Enables color-coding of debit and credit movements in the bank entries list.', 'Toggled via admin/bank.php (written as 1 at :104, written as 0 at :109). Checked at admin/bank.php:456 and :470 and at compta/bank/bankentries_list.php:1468 to apply or suppress row coloring.', 'Enabling this causes bank transaction rows to be colored differently based on movement direction; disabling shows uniform row styling.', '0 = movements not colorized; 1 = movements colorized', 0, 0, 'admin/bank.php|admin/bank.php|admin/bank.php|admin/bank.php', 1, 'bd1656ac97bbf74bc7b7eadcadc865685d141c7a8559659322e8d63b6f70b0b6', 'v2', '2026-04-21T11:16:15+00:00', '["admin/bank.php:104|write|if (dolibarr_set_const($db, \"BANK_COLORIZE_MOVEMENT\", 1, ''chaine'', 0, '''', $conf->entity) > 0) {", "admin/bank.php:109|write|if (dolibarr_set_const($db, \"BANK_COLORIZE_MOVEMENT\", 0, ''chaine'', 0, '''', $conf->entity) > 0) {", "compta/bank/bankentries_list.php:1468|check|if (!getDolGlobalString(''BANK_COLORIZE_MOVEMENT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_COLORIZE_MOVEMENT_COLOR', 'string', NULL, 'admin', 'Dynamic-suffix constant (BANK_COLORIZE_MOVEMENT_COLOR1/2) storing the highlight color used for bank transaction rows of a given sign/type.', 'Written from admin/bank.php:129 inside a loop ''while ($i <= 2)'' that saves BANK_COLORIZE_MOVEMENT_COLOR1 and BANK_COLORIZE_MOVEMENT_COLOR2 from GETPOST(''BANK_COLORIZE_MOVEMENT_COLOR''.$i). The plain ''BANK_COLORIZE_MOVEMENT_COLOR'' name (without numeric suffix) does not appear standalone in the admin form; the DB row name may be a truncation of the real dynamic constants BANK_COLORIZE_MOVEMENT_COLOR1/COLOR2.', 'Changing it changes the CSS color used to colorize bank movement rows (e.g. debit vs credit) in the bank transaction list; setting the posted value to ''-1'' clears it (code maps ''-1'' to an empty string).', 'A CSS color value (hex string); posting ''-1'' clears the setting to empty.', 0, 0, 'admin/bank.php', 1, '797ed0acdb0ef6435d5407d905a1ef4f5ed57971c4c54603a7a542452675bc0f', 'v2', '2026-07-24T07:05:23+00:00', '["admin/bank.php:129|write|$res = dolibarr_set_const($db, ''BANK_COLORIZE_MOVEMENT_COLOR''.$i, $color, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_COLORIZE_MOVEMENT_COLOR1', 'string', NULL, 'compta', 'Sets the background color (hex, without ''#'') used to highlight negative-amount (debit) bank movement rows when row colorization is enabled via BANK_COLORIZE_MOVEMENT.', 'Read with a default fallback in compta/bank/bankentries_list.php:1471: getDolGlobalString(''BANK_COLORIZE_MOVEMENT_COLOR1'', ''fca955''), used only when BANK_COLORIZE_MOVEMENT is set and the row amount ($objp->amount) is negative.', 'When BANK_COLORIZE_MOVEMENT is enabled, changing this value changes the row background color used for negative/debit bank movement lines in the bank entries list; has no effect if BANK_COLORIZE_MOVEMENT is not set.', 'Hex color string without ''#'' prefix (e.g. default ''fca955''); prepended with ''#'' when building the CSS background value.', 1, 0, NULL, 1, '5db0d3d016899fc449f23d4582c35a7713cebf80de14736ba9687a6113175e6e', 'v2', '2026-07-24T07:05:23+00:00', '["compta/bank/bankentries_list.php:1467-1471|code|if (!getDolGlobalString(''BANK_COLORIZE_MOVEMENT'')) { ... } else { if ($objp->amount < 0) { $color = ''#'' . getDolGlobalString(''BANK_COLORIZE_MOVEMENT_COLOR1'', ''fca955''); ..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_COLORIZE_MOVEMENT_COLOR2', 'string', NULL, 'compta', 'Sets the background color (hex, without ''#'') used to highlight positive-amount (credit) bank movement rows when row colorization is enabled via BANK_COLORIZE_MOVEMENT.', 'Read with a default fallback in compta/bank/bankentries_list.php:1474: getDolGlobalString(''BANK_COLORIZE_MOVEMENT_COLOR2'', ''7fdb86''), used only when BANK_COLORIZE_MOVEMENT is set and the row amount ($objp->amount) is not negative.', 'When BANK_COLORIZE_MOVEMENT is enabled, changing this value changes the row background color used for positive/credit bank movement lines in the bank entries list; has no effect if BANK_COLORIZE_MOVEMENT is not set.', 'Hex color string without ''#'' prefix (e.g. default ''7fdb86''); prepended with ''#'' when building the CSS background value.', 1, 0, NULL, 1, '15c8ff4e62060494936551df12fdaf83478dde771af1e75ff942c8fbefc439e2', 'v2', '2026-07-24T07:05:23+00:00', '["compta/bank/bankentries_list.php:1467-1474|code|if (!getDolGlobalString(''BANK_COLORIZE_MOVEMENT'')) { ... } else { ... } else { $color = ''#'' . getDolGlobalString(''BANK_COLORIZE_MOVEMENT_COLOR2'', ''7fdb86''); ..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_DISABLE_CHECK_DEPOSIT', 'bool', NULL, 'index.php', 'Disables the check deposit feature in the bank module, hiding the related menu entry and dashboard block.', 'Checked in index.php:296 (to hide the check deposit sub-block on the dashboard) and in core/menus/standard/eldy.lib.php:2168 (to hide the check deposit menu item). No admin UI is present.', 'Setting this constant hides the check deposit UI from both the menu and the dashboard across the application.', 'Boolean flag: truthy = check deposit hidden; 0 or unset = check deposit displayed.', 1, 0, NULL, 1, '6aa9120056e6c6f5b7011efb76ee2da9cceacca1f3cf72d1f647e8c84ab09642', 'v2', '2026-04-21T11:16:15+00:00', '["index.php:296|check|if (!getDolGlobalString(''BANK_DISABLE_CHECK_DEPOSIT'')) {", "core/menus/standard/eldy.lib.php:2168|check|if (!getDolGlobalString(''BANK_DISABLE_CHECK_DEPOSIT'') && isModEnabled(''bank'') && (isModEnabled(''invoice'') || getDolGlobalString(''MAIN_MENU_CHEQUE_DEPOSIT_ON''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_DISABLE_DIRECT_INPUT', 'bool', NULL, 'admin', 'Disables the ability to directly add/record a bank transaction line manually from the bank entries list.', 'It has an admin yes/no setting in accountancy/admin/index.php:69 (via FormSetup->newItem(''BANK_DISABLE_DIRECT_INPUT'')->setAsYesNo()) and is checked in admin/bank.php:510 and compta/bank/bankentries_list.php:905; when true, the ''Add'' button on the bank entries list is disabled with the tooltip ''Direct input in bank lines has been disabled by option BANK_DISABLE_DIRECT_INPUT''.', 'Enabling it removes/disables the manual ''add bank record'' button from the bank entries list, forcing transactions to be recorded through other means (e.g. imports or linked documents).', 'Yes/No, per accountancy.lang label: ''Disable direct recording of transaction in bank account''.', 0, 0, 'admin/bank.php', 1, 'b1666a3e051d999b4bd906c795ea666066ba26497583e500972b6a8798cf2413', 'v2', '2026-07-24T07:05:23+00:00', '["compta/bank/bankentries_list.php:916: ''Direct input in bank lines has been disabled by option BANK_DISABLE_DIRECT_INPUT''", "accountancy/admin/index.php:69: $item = $formSetup->newItem(''BANK_DISABLE_DIRECT_INPUT'')->setAsYesNo();", "langs/en_US/accountancy.lang: BANK_DISABLE_DIRECT_INPUT=Disable direct recording of transaction in bank account [from fr/other translations seen]"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_ENABLE_POS_CASHCONTROL', 'bool', NULL, 'blockedlog', 'Signals that an external POS module requires cash control tracking in the blockedlog.', 'Read at blockedlog/class/blockedlog.class.php:307 where it is OR-combined with isModEnabled(''cashdesk'') and isModEnabled(''takepos'') to determine whether POS cash control is active. The comment at line 306 states this must be set to 1 by all external POS modules.', 'Setting this constant to 1 activates cash control blockedlog tracking for external POS modules that do not have a native Dolibarr module enable flag.', '$conf->global->BANK_ENABLE_POS_CASHCONTROL must be set to 1 by all external POS modules.', 1, 0, NULL, 1, '443e7909204a440b081854e894c8ece57312adbd1a43156a18ad407ec509ae4e', 'v2', '2026-04-21T11:16:15+00:00', '["blockedlog/class/blockedlog.class.php:306  // $conf->global->BANK_ENABLE_POS_CASHCONTROL must be set to 1 by all external POS modules", "blockedlog/class/blockedlog.class.php:307|read|$moduleposenabled = (isModEnabled(''cashdesk'') || isModEnabled(''takepos'') || getDolGlobalString(''BANK_ENABLE_POS_CASHCONTROL''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_PAYMENT_MODES_FOR_DEPOSIT_MANAGEMENT', 'string', NULL, 'compta', 'Defines the comma-separated list of payment mode codes managed through the cheque deposit interface.', 'Read in compta/paiement/cheque/index.php:57, card.php:104, and list.php:88 via explode('','', getDolGlobalString(..., ''CHQ'')). The comments in all three files state: ''// Example: BANK_PAYMENT_MODES_FOR_DEPOSIT_MANAGEMENT = \''CHQ\'',\''TRA\''''.', 'Changing this constant alters which payment mode codes are included in the deposit management workflow; removing a code excludes those payments from the deposit lists.', 'Comma-separated payment mode codes; default is ''CHQ''. Example: ''CHQ'',''TRA''', 1, 0, NULL, 1, '129a46dd1ad1cc8d5f9a7fd6f114c0b2fb9f24f5616b3eb4d4b4838e62b3613c', 'v2', '2026-04-21T13:29:58+00:00', '["// Example: BANK_PAYMENT_MODES_FOR_DEPOSIT_MANAGEMENT = ''CHQ'',''TRA''", "$arrayofpaymentmodetomanage = explode('','', getDolGlobalString(''BANK_PAYMENT_MODES_FOR_DEPOSIT_MANAGEMENT'', ''CHQ''));", "if (getDolGlobalString(''BANK_PAYMENT_MODES_FOR_DEPOSIT_MANAGEMENT'', ''CHQ'') == ''CHQ'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_REPORT_LAST_NUM_RELEVE', 'string', NULL, 'admin', 'Controls whether the last bank statement number is automatically carried forward to the next statement.', 'Toggled via admin/bank.php (written as 1 at :91, written as 0 at :96). Checked at admin/bank.php:526 and compta/bank/bankentries_list.php:1031. The comment at bankentries_list.php:1030 explicitly documents its purpose.', 'Enabling this causes the last statement number to be reported automatically; disabling requires the number to be entered manually each time.', '0 = last statement number not auto-reported; 1 = last statement number automatically reported', 0, 0, 'admin/bank.php|admin/bank.php|admin/bank.php', 1, '0d4191b38617cc5a84f64283409c835f2354218592362f3eb9f3e28202dd0417', 'v2', '2026-04-21T11:16:15+00:00', '["compta/bank/bankentries_list.php:1030  // Using BANK_REPORT_LAST_NUM_RELEVE to automatically report last num (or not)", "admin/bank.php:91|write|if (dolibarr_set_const($db, \"BANK_REPORT_LAST_NUM_RELEVE\", 1, ''chaine'', 0, '''', $conf->entity) > 0) {", "admin/bank.php:96|write|if (dolibarr_set_const($db, \"BANK_REPORT_LAST_NUM_RELEVE\", 0, ''chaine'', 0, '''', $conf->entity) > 0) {", "compta/bank/bankentries_list.php:1031|check|if (getDolGlobalString(''BANK_REPORT_LAST_NUM_RELEVE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_SHOW_ORDER_OPTION', 'bool', NULL, 'compta', 'Selects the ordering field used to sort bank account transactions in the account register.', 'Configurable via admin/bank.php. When set to ''1'', one sort order is applied; numeric values select among available sort options; a regex replacement on the value derives the final field name (compta/bank/class/account.class.php:1960). Set via dolibarr_set_const at admin/bank.php:83.', 'Changing this value alters the default sort order of bank transaction listings. The value is used both as a flag and as a field-name pattern.', 'Empty = default ordering; ''1'' = sort by BankAccountNumber; numeric value = selects sort index; string = sort field pattern', 0, 0, 'admin/bank.php|admin/bank.php', 1, '464b9002277b4e5da2bf11b800d43934b5850d7da56ccfe23a1ac92903ac81fd', 'v2', '2026-04-21T11:16:15+00:00', '["compta/bank/class/account.class.php:1947|check|if (is_numeric(getDolGlobalString(''BANK_SHOW_ORDER_OPTION''))) {", "compta/bank/class/account.class.php:1948|check|if (getDolGlobalString(''BANK_SHOW_ORDER_OPTION'') == ''1'') {", "compta/bank/class/account.class.php:1960|read|preg_replace(''/ ?[^Bank]AccountNumber ?/'', ''BankAccountNumber'', $conf->global->BANK_SHOW_ORDER_OPTION)", "admin/bank.php:83|write|if (dolibarr_set_const($db, \"BANK_SHOW_ORDER_OPTION\", GETPOST(''value'', ''alpha''), ''chaine'', 0, '''', $conf->entity) > 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_STATEMENT_REGEX_RULE', 'string', NULL, 'compta', 'Defines a regular expression that bank statement reference numbers must match.', 'When set, the value is used as a regex pattern validated against the statement number (num_releve) via preg_match. If the number does not match, an error is added to the object. Checked at compta/bank/class/account.class.php:2569–2571.', 'Setting a regex forces statement reference numbers to conform to that pattern; non-matching values trigger a validation error preventing save.', 'Empty = no format constraint; any valid regex string = pattern that statement numbers must match', 1, 0, NULL, 1, '42b9502ca2396c1e83a562c25ab23a985ab4b6df82d392c2b5f68529f256a2e8', 'v2', '2026-04-21T11:16:15+00:00', '["compta/bank/class/account.class.php:2570|check|if (!preg_match(''/'' . getDolGlobalString(''BANK_STATEMENT_REGEX_RULE'').''/'', $this->num_releve)) {", "compta/bank/class/account.class.php:2571|read|$this->errors[] = $langs->trans(\"ErrorBankStatementNameMustFollowRegex\", getDolGlobalString(''BANK_STATEMENT_REGEX_RULE''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_TRANSFER_ASK_CHQ_NUMBER_OF_SRC_ACCOUNT', 'string', NULL, 'compta', 'Adds a cheque-number input column to the internal bank transfer form (compta/bank/transfer.php).', 'Read twice in compta/bank/transfer.php (lines 318 and 369): once to decide whether to print the ''ChequeNumber'' table header, once to print the corresponding input cell for each transfer line.', 'When enabled, users creating an internal bank-to-bank transfer see and can fill in a cheque number field per line; when disabled, that column is omitted from the transfer form.', 'Boolean-like: truthy shows the cheque-number column/input on the transfer screen.', 1, 0, NULL, 1, 'f8941e68c2735b8af6de36bdc363f12ddaf7ec0fbef0d98063c199b98f0b21eb', 'v2', '2026-07-24T07:05:23+00:00', '["compta/bank/transfer.php:318: if (getDolGlobalString(''BANK_TRANSFER_ASK_CHQ_NUMBER_OF_SRC_ACCOUNT'')) { print ''<th>''.$langs->trans(\"ChequeNumber\").''</th>''; }", "compta/bank/transfer.php:369: if (getDolGlobalString(''BANK_TRANSFER_ASK_CHQ_NUMBER_OF_SRC_ACCOUNT'')) { print ''<td><input name=\"''.$i.''_num_chq\" ..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BANK_USE_OLD_VARIOUS_PAYMENT', 'bool', NULL, 'compta', 'Enables the legacy inline various payment entry form in bank entries list instead of the modern miscellaneous payments module.', 'Checked at compta/bank/bankentries_list.php:812, :389, and :910. When set, the old inline form is shown and the new miscellaneous payment path is bypassed. When unset, the default is to use the new miscellaneous payments module (bankentries_list.php:910 comment: ''Default is to record miscellaneous direct entries using miscellaneous payments''). Also controls a menu entry in core/menus/standard/eldy.lib.php:1705 and a project element tab in projet/element.php:782.', 'When unset, the modern miscellaneous payments workflow is used and the corresponding menu entry is shown. When set, the old inline payment form is activated and the new menu entry is hidden.', 'Truthy value = legacy inline various payment form enabled; empty/unset = modern miscellaneous payments used.', 1, 0, NULL, 1, '499a9559688ea58f63dfce9cd1ac71b4d7e74d42d45518f1bd42358680dd553e', 'v2', '2026-04-21T11:16:15+00:00', '["compta/bank/bankentries_list.php:910|check|if (!getDolGlobalString(''BANK_USE_OLD_VARIOUS_PAYMENT'')) {\t// Default is to record miscellaneous direct entries using miscellaneous payments", "compta/bank/bankentries_list.php:812|check|if ($user->hasRight(''banque'', ''modifier'') && $action == ''addline'' && getDolGlobalString(''BANK_USE_OLD_VARIOUS_PAYMENT'')) {", "core/menus/standard/eldy.lib.php:1705|check|if (isModEnabled(''bank'') && !getDolGlobalString(''BANK_USE_OLD_VARIOUS_PAYMENT'')) {", "projet/element.php:782|read|''test'' => isModEnabled(\"bank\") && $user->hasRight(''banque'', ''lire'') && !getDolGlobalString(''BANK_USE_OLD_VARIOUS_PAYMENT'')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_FORCEIMGSCALEHEIGHT', 'string', NULL, 'barcode', 'Forces the vertical scale factor applied to the barcode image on printed label sheets.', 'Read in barcode/printsheet.php:322 with a default of 1, used when rendering label sheets in ''label'' mode alongside BARCODE_FORCEIMGSCALEWIDTH.', 'Changing it rescales the height of the barcode image printed on labels; the exact rendering formula is not shown in the reviewed code.', 'Numeric scale factor; default 1.', 1, 0, NULL, 1, '362520c0a54fd497a1c5d0355c9e97aa287d86a172b8eedfc01480f9066afd8f', 'v2', '2026-07-24T07:05:23+00:00', '["barcode/printsheet.php:322: $forceimgscaleheight = getDolGlobalString(''BARCODE_FORCEIMGSCALEHEIGHT'', 1);"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_FORCEIMGSCALEWIDTH', 'string', NULL, 'barcode', 'Forces the horizontal scale factor applied to the barcode image on printed label sheets.', 'Read in barcode/printsheet.php:321 with a default of 1, used when rendering label sheets in ''label'' mode alongside BARCODE_FORCEIMGSCALEHEIGHT.', 'Changing it rescales the width of the barcode image printed on labels; the exact rendering formula is not shown in the reviewed code.', 'Numeric scale factor; default 1.', 1, 0, NULL, 1, '26901b1539a63b365b3f4b90ce17b7161ff967a6e5d73e4ff6490065329ecc0d', 'v2', '2026-07-24T07:05:23+00:00', '["barcode/printsheet.php:321: $forceimgscalewidth = getDolGlobalString(''BARCODE_FORCEIMGSCALEWIDTH'', 1);"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_INIT_MAX', 'string', NULL, 'barcode', 'Maximum number of barcodes that can be generated in a single mass barcode initialization run.', 'Read in barcode/codeinit.php:56 with a default of 1000, used as $maxperinit to cap the mass barcode-initialization tool for products/thirdparties.', 'Increasing it allows more barcodes to be assigned per initialization run; decreasing it lowers the cap. No batching/threshold detail beyond the default is shown in code.', 'Integer, default 1000.', 1, 0, NULL, 1, '8d2a6a8c3864734b0e1d4116ea9cd139bd647d217e0533806b4602db21cb09d4', 'v2', '2026-07-24T07:05:23+00:00', '["barcode/codeinit.php:56: $maxperinit = getDolGlobalInt(''BARCODE_INIT_MAX'', 1000);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_LABEL_FOOTER_TEXT', 'string', NULL, 'barcode', 'Custom text template printed in the footer area of a barcode sticker label.', 'Used in barcode/printsheet.php:318 as the footer text for label sheets, passed through make_substitutions(). Overridden by the product label when a specific product option is set.', 'Changing it alters the footer text shown on printed barcode label stickers unless a per-product label option overrides it.', 'Any string, may contain substitution tags resolved by make_substitutions().', 1, 0, NULL, 1, '194424b51e19468e344ed7625eb5c7eacf6d3ae58d847fb3532615a171e913e7', 'v2', '2026-07-24T07:05:23+00:00', '["barcode/printsheet.php:318: $textfooter = make_substitutions(getDolGlobalString(''BARCODE_LABEL_FOOTER_TEXT''), $substitutionarray);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_LABEL_HEADER_TEXT', 'string', NULL, 'barcode', 'Custom text template printed in the header area of a barcode sticker label.', 'Used in barcode/printsheet.php:313 as the header text for label sheets, passed through make_substitutions(). Overridden by the product reference when a specific product option is set.', 'Changing it alters the header text shown on printed barcode label stickers unless a per-product label option overrides it.', 'Any string, may contain substitution tags resolved by make_substitutions().', 1, 0, NULL, 1, 'efacda2a1903b6adfd3f873599bf7a7fa588c2355549db6314077b63b1655d5d', 'v2', '2026-07-24T07:05:23+00:00', '["barcode/printsheet.php:313: $textheader = make_substitutions(getDolGlobalString(''BARCODE_LABEL_HEADER_TEXT''), $substitutionarray);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_LABEL_LEFT_TEXT', 'string', NULL, 'barcode', 'Custom text template printed on the left side of a barcode sticker label.', 'Used in barcode/printsheet.php:309 as the left-side text of a label sheet, passed through make_substitutions() so it supports substitution tags. Defaults to a photo placeholder string ($txtforsticker) if unset.', 'Changing it alters the text shown on the left area of printed barcode label stickers; no other behavior is affected.', 'Any string, may contain substitution tags (e.g. %COMPANY%, __LOGIN__) resolved by make_substitutions().', 1, 0, NULL, 1, 'e081e1ac748d2c4446b0af1fe002b3298956d5ace8f7a2b22da83fb91f4e11e8', 'v2', '2026-07-24T07:05:23+00:00', '["barcode/printsheet.php:309: $textleft = make_substitutions(getDolGlobalString(''BARCODE_LABEL_LEFT_TEXT'', $txtforsticker), $substitutionarray);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_LABEL_RIGHT_TEXT', 'string', NULL, 'barcode', 'Custom text template printed on the right side of a barcode sticker label.', 'Used in barcode/printsheet.php:320 as the right-side text of a label sheet, passed through make_substitutions().', 'Changing it alters the text shown on the right area of printed barcode label stickers; no other behavior is affected.', 'Any string, may contain substitution tags resolved by make_substitutions().', 1, 0, NULL, 1, 'eafda32ad0b247a28894362b1deddeaccb17c0c02b62a76c25de46202508723a', 'v2', '2026-07-24T07:05:23+00:00', '["barcode/printsheet.php:320: $textright = make_substitutions(getDolGlobalString(''BARCODE_LABEL_RIGHT_TEXT''), $substitutionarray);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_ON_RECEPTION_PDF', 'string', NULL, 'admin', 'Enables printing barcodes on reception PDF documents when the barcode module is active.', 'Written in admin/pdf_other.php at line 172 and displayed as a select at line 789. Checked in pdf_squille.modules.php at line 384 in conjunction with the barcode module being enabled.', 'Enabling this constant (with the barcode module active) causes barcodes to be printed on reception PDFs. Disabling it omits barcodes.', 'Non-zero integer to enable barcodes on reception PDFs (requires barcode module); 0 or unset to disable.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, 'bfc4d89998a96c00d1ed89233f60d176cca1e54b28e6ae24018e2596cb6d1e6b', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:172|write|dolibarr_set_const($db, \"BARCODE_ON_RECEPTION_PDF\", GETPOSTINT(\"BARCODE_ON_RECEPTION_PDF\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/reception/doc/pdf_squille.modules.php:384|check|if (isModEnabled(''barcode'') && getDolGlobalString(''BARCODE_ON_RECEPTION_PDF'')) {", "admin/pdf_other.php:789|read|print $form->selectarray(\"BARCODE_ON_RECEPTION_PDF\", $arrval, getDolGlobalString(''BARCODE_ON_RECEPTION_PDF''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_ON_SHIPPING_PDF', 'string', NULL, 'admin', 'Selects whether/which barcode is printed on shipping (expedition) PDF documents.', 'Set via admin/pdf_other.php:169 (dolibarr_set_const) and selected from a dropdown at admin/pdf_other.php:742; read by PDF generation code in core/modules/expedition/doc/pdf_rouget.modules.php:428 and pdf_espadon.modules.php:531, gated on the barcode module being enabled.', 'Its value determines whether a barcode appears on generated shipping PDFs, but only when the barcode module is enabled.', NULL, 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '8be9c8f289824a92d3aaee80e372edf7f50bddc5d74ce33f982917a645878382', 'v2', '2026-07-24T06:41:12+00:00', '["if (isModEnabled(''barcode'') && getDolGlobalString(''BARCODE_ON_SHIPPING_PDF'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_ON_STOCKTRANSFER_PDF', 'string', NULL, 'admin', 'Controls whether barcodes are printed on stock-transfer PDF documents.', 'Configured via admin/pdf_other.php (UI write at line 175, select array at line 814). Checked in core/modules/stocktransfer/doc/pdf_eagle.modules.php:446 alongside a check that the barcode module is enabled.', 'When set to a truthy value (and the barcode module is enabled), barcodes are rendered on stock-transfer PDFs. When unset or 0, barcodes are omitted.', 'Value from the configured select array in admin/pdf_other.php; 0 or empty to disable barcodes.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '53f4613077b1dc2ae6d742e7cb6fd97067617be865cd3293b319bc9f121bbac6', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:175|write|dolibarr_set_const($db, \"BARCODE_ON_STOCKTRANSFER_PDF\", GETPOSTINT(\"BARCODE_ON_STOCKTRANSFER_PDF\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf_other.php:814|read|print $form->selectarray(\"BARCODE_ON_STOCKTRANSFER_PDF\", $arrval, getDolGlobalString(''BARCODE_ON_STOCKTRANSFER_PDF''));", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:446|check|if (isModEnabled(''barcode'') && getDolGlobalString(''BARCODE_ON_STOCKTRANSFER_PDF'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_PRODUCT_ADDON_NUM', 'string', NULL, 'product', 'Identifies the active automatic barcode numbering module used for product records.', 'Written by admin/barcode.php:63 (set) and admin/barcode.php:68 (delete). Read in admin/barcode.php:297 to highlight the selected module, in barcode/codeinit.php:182 and :194 during initialisation, and in product/class/product.class.php:1355 and :6947 when auto-generating product barcodes.', 'Setting this constant activates a specific numbering module for auto-generating product barcodes; clearing it disables automatic barcode numbering for products.', 'Module filename string (e.g. ''mod_barcode_product_standard''); empty = no automatic numbering.', 0, 0, 'admin/barcode.php|admin/barcode.php|admin/barcode.php', 1, 'efa5c82b214e2be75b3908557ab8bd5e695544faa7c7d2ee85390076f84ff9c4', 'v2', '2026-04-21T11:16:15+00:00', '["admin/barcode.php:63|write|$res = dolibarr_set_const($db, \"BARCODE_PRODUCT_ADDON_NUM\", $barcodenumberingmodule, ''chaine'', 0, '''', $conf->entity);", "barcode/codeinit.php:182|check|if (getDolGlobalString(''BARCODE_PRODUCT_ADDON_NUM'')) {", "barcode/codeinit.php:194|check|if ($file == getDolGlobalString(''BARCODE_PRODUCT_ADDON_NUM'')) {", "product/class/product.class.php:1355|check|if (isModEnabled(''barcode'') && getDolGlobalString(''BARCODE_PRODUCT_ADDON_NUM'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_STANDARD_PRODUCT_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the standard product barcode generation module.', 'Managed via admin/barcode.php; if unset when the standard module is active, the admin page writes a default of ''04{0000000000}'' at line 65. The mask is read and applied in core/modules/barcode/mod_barcode_product_standard.php at lines 196 and 334.', 'Changing this mask alters the format of auto-generated product barcodes; removing it causes the admin page to reset it to the default ''04{0000000000}''.', 'Mask string, e.g. ''04{0000000000}''; default set to ''04{0000000000}'' if unset.', 0, 0, 'admin/barcode.php|admin/barcode.php', 1, 'd3b8e42c59871ce7cf964211311834c9979307427aae06bbc0e3091e1731fd86', 'v2', '2026-04-21T13:50:40+00:00', '["admin/barcode.php:65|write|$res = dolibarr_set_const($db, \"BARCODE_STANDARD_PRODUCT_MASK\", ''04{0000000000}'', ''chaine'', 0, '''', $conf->entity);", "core/modules/barcode/mod_barcode_product_standard.php:196|read|$mask = getDolGlobalString(''BARCODE_STANDARD_PRODUCT_MASK'');", "core/modules/barcode/mod_barcode_product_standard.php:334|read|$mask = !getDolGlobalString(''BARCODE_STANDARD_PRODUCT_MASK'') ? '''' : $conf->global->BARCODE_STANDARD_PRODUCT_MASK;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_STANDARD_THIRDPARTY_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the standard third-party barcode generation module.', 'Managed via admin/barcode.php; if unset when the standard thirdparty module is active, the admin page writes a default of ''04{0000000000}'' at line 75. The mask is read and applied in core/modules/barcode/mod_barcode_thirdparty_standard.php at lines 220 and 355.', 'Changing this mask alters the format of auto-generated third-party barcodes; removing it causes the admin page to reset it to the default ''04{0000000000}''.', 'Mask string, e.g. ''04{0000000000}''; default set to ''04{0000000000}'' if unset.', 0, 0, 'admin/barcode.php|admin/barcode.php', 1, '8d24a2d0398aa08936d2f1b7acde3eceb412cfc61c7ca4c00804826920b4304c', 'v2', '2026-04-21T13:50:40+00:00', '["admin/barcode.php:75|write|$res = dolibarr_set_const($db, \"BARCODE_STANDARD_THIRDPARTY_MASK\", ''04{0000000000}'', ''chaine'', 0, '''', $conf->entity);", "core/modules/barcode/mod_barcode_thirdparty_standard.php:220|read|$mask = getDolGlobalString(''BARCODE_STANDARD_THIRDPARTY_MASK'');", "core/modules/barcode/mod_barcode_thirdparty_standard.php:355|read|$mask = !getDolGlobalString(''BARCODE_STANDARD_THIRDPARTY_MASK'') ? '''' : $conf->global->BARCODE_STANDARD_THIRDPARTY_MASK;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_THIRDPARTY_ADDON_NUM', 'string', NULL, 'admin', 'Identifies the active automatic barcode numbering module used for third-party records.', 'Written by admin/barcode.php:73 (set) and admin/barcode.php:78 (delete). Read in admin/barcode.php:366 to highlight the selected module in the admin UI, and checked in barcode/codeinit.php:77 before initialising third-party barcodes.', 'Setting this constant activates a specific numbering module for auto-generating third-party barcodes; clearing it disables automatic numbering.', 'Module filename string (e.g. ''mod_barcode_thirdparty_standard''); empty = no automatic numbering.', 0, 0, 'admin/barcode.php|admin/barcode.php|admin/barcode.php', 1, 'b51fc7dd8504edc0d8e7d5cd05beef101307470aa86d10b132aac2ba22867166', 'v2', '2026-04-21T11:16:15+00:00', '["admin/barcode.php:73|write|$res = dolibarr_set_const($db, \"BARCODE_THIRDPARTY_ADDON_NUM\", $barcodenumberingmodule, ''chaine'', 0, '''', $conf->entity);", "admin/barcode.php:366|check|if (getDolGlobalString(''BARCODE_THIRDPARTY_ADDON_NUM'') && getDolGlobalString(''BARCODE_THIRDPARTY_ADDON_NUM'') == \"$file\") {", "barcode/codeinit.php:77|check|if (getDolGlobalString(''BARCODE_THIRDPARTY_ADDON_NUM'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_USE_ON_PRODUCT', 'bool', NULL, 'product', 'Enables barcode support/usage on product records.', 'Checked extensively in admin/barcode.php (lines 257, 396, 502, 533) to control the barcode admin setup screen, and in product/card.php (lines 1415, 2240, 2590, 234) to decide whether barcode fields/creation are shown, always combined with isModEnabled(''barcode'').', 'When enabled together with the barcode module, products display and allow creation/management of a barcode field; otherwise barcode UI on products is hidden.', NULL, 0, 0, 'admin/barcode.php|admin/barcode.php|admin/barcode.php|admin/barcode.php', 1, '1c698080d763c1c21b46f18f663af3c1fa531b3ba48ababe3daecf0e104345f2', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''BARCODE_USE_ON_PRODUCT'') && isModEnabled(''product'')) {", "$showbarcode = (isModEnabled(''barcode'') && getDolGlobalString(''BARCODE_USE_ON_PRODUCT''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BARCODE_USE_ON_THIRDPARTY', 'bool', NULL, 'admin', 'When enabled, activates barcode field display and functionality on third-party records.', 'Checked in admin/barcode.php:325, :396, :502, :544 to conditionally render barcode configuration options when the societe module is active. Also checked in societe/card.php:1610, :2485, :3072 to display the barcode field on third-party cards. Seven occurrences across two files; written via admin/barcode.php.', 'Enabling this constant adds a barcode input field to third-party cards and activates related barcode configuration sections in the barcode admin panel.', 'Boolean flag; unset or 0 = barcode not shown on third parties; any truthy value = barcode field displayed.', 0, 0, 'admin/barcode.php|admin/barcode.php|admin/barcode.php|admin/barcode.php', 1, '980288f4c38203cc6c49809ea73db59d722b57d96f10d19c489d15420a5002d3', 'v2', '2026-04-21T11:16:15+00:00', '["admin/barcode.php:325|check|if (getDolGlobalString(''BARCODE_USE_ON_THIRDPARTY'') && isModEnabled(''societe'')) {", "societe/card.php:1610|check|if (isModEnabled(''barcode'') && getDolGlobalString(''BARCODE_USE_ON_THIRDPARTY'')) {", "admin/barcode.php:396|check|if (getDolGlobalString(''BARCODE_USE_ON_PRODUCT'') || getDolGlobalString(''BARCODE_USE_ON_THIRDPARTY'')) {", "societe/card.php:3072|check|if (isModEnabled(''barcode'') && getDolGlobalString(''BARCODE_USE_ON_THIRDPARTY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BILL_ADD_PAYMENT_VALIDATION', 'string', NULL, 'compta', 'Enables a payment validation workflow for customer and supplier invoices, adding a ''payments to validate'' queue and menu entry.', 'Checked across fourn/paiement/card.php, compta/payment_sc/card.php, compta/paiement/card.php, and core/menus/standard/eldy.lib.php. The file compta/paiement/tovalidate.php:23 describes it as: ''Page list payment to validate. Visible in menu when option BILL_ADD_PAYMENT_VALIDATION is on.''', 'Enabling this constant activates the payment validation step, shows the validation status column in payment lists (compta/paiement/list.php:129), and adds the corresponding menu entry.', 'Boolean/truthy: non-empty enables the validation workflow; empty/unset disables it.', 1, 0, NULL, 1, '186d96d6c119a664aad407fcc88d2be0f11ed137816c9c30dfef9c6e639b2c1b', 'v2', '2026-04-21T11:16:15+00:00', '["* \tbrief      Page list payment to validate. Visible in menu when option BILL_ADD_PAYMENT_VALIDATION is on.", "if (getDolGlobalString(''BILL_ADD_PAYMENT_VALIDATION'')) {", "''enabled'' => (getDolGlobalString(''BILL_ADD_PAYMENT_VALIDATION''))"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_ADD_ACTIONS_SUPPORTED', 'string', NULL, 'core', 'Comma-separated list of extra element/action types added to those supported by the blocked log (audit trail) feature.', 'Checked in blockedlog/class/blockedlog.class.php:335/341 and core/triggers/interface_99_modBlockedlog_ActionsBlockedLog.class.php:93/94/224, where it is exploded on commas and merged into the list of qualified elements for logging.', 'Adding entries to this comma-separated list extends which additional actions/elements get recorded by the blocked log trigger.', 'comma-separated list of element/action identifiers', 1, 0, NULL, 1, 'ebb5be1cc3037a4789451f65573a997abd920bdcf5240cf113dcf7f3b026b9a2', 'v2', '2026-07-24T06:41:12+00:00', '["$listofqualifiedelement = array_merge($listofqualifiedelement, explode('','', getDolGlobalString(''BLOCKEDLOG_ADD_ACTIONS_SUPPORTED'')));", "(getDolGlobalString(''BLOCKEDLOG_ADD_ACTIONS_SUPPORTED'') && in_array($action, explode('','', getDolGlobalString(''BLOCKEDLOG_ADD_ACTIONS_SUPPORTED''))))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_ADD_DEBUG_INFO', 'string', NULL, 'blockedlog', 'Enables recording internal hash/signature debug information into the blocked log entry''s debuginfo field.', 'In blockedlog/class/blockedlog.class.php:1352 and :1532, when truthy, the code sets $this->debuginfo to a string combining previoushash, the first part of the signature key, and the computed signature, both when creating a new log entry and when detecting a signature anomaly.', 'Setting it stores extra internal hash-chain debug details in each blocked-log record''s debuginfo column, useful for diagnosing signature/hash chain issues in the unalterable log; the comment marks this field as ''Not used'' otherwise and something that ''we can clean this field later''.', 'Boolean-like: truthy populates debuginfo with ''previoushash=...'' plus signature details on log entry creation and on anomaly detection.', 0, 0, NULL, 1, '7dbf74e764121f482dbee012d1788dea0876a4f8a7e4065ae05559160da21b54', 'v2', '2026-07-24T07:05:23+00:00', '["blockedlog/class/blockedlog.class.php:1352|check|if (getDolGlobalString(''BLOCKEDLOG_ADD_DEBUG_INFO'')) {", "blockedlog/class/blockedlog.class.php: // For debug info (we can clean this field later)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_ADD_OLD_CASHCONTROL_VALIDATE', 'string', NULL, 'blockedlog', 'Enables tracking of the legacy CASHCONTROL_VALIDATE cash-register event in the unalterable blocked log, in addition to CASHCONTROL_CLOSE which is always tracked.', 'In blockedlog/class/blockedlog.class.php:327, when a POS module is enabled (cashdesk/takepos/BANK_ENABLE_POS_CASHCONTROL) and this constant is truthy, the CASHCONTROL_VALIDATE event is added to $this->trackedevents alongside the always-tracked CASHCONTROL_CLOSE event.', 'Setting it adds an extra, older cash-register-validation event type to the unalterable log''s tracked event list; without it only CASHCONTROL_CLOSE is tracked for cash register closing.', 'Boolean-like: truthy adds CASHCONTROL_VALIDATE to the tracked blocked-log events for POS cash control.', 0, 0, NULL, 1, '98cd109219092ec923e3888cbe93d04940fd5a76de05e2a138efae36f9f726a1', 'v2', '2026-07-24T07:05:23+00:00', '["blockedlog/class/blockedlog.class.php:327|check|if (getDolGlobalString(''BLOCKEDLOG_ADD_OLD_CASHCONTROL_VALIDATE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_AUTHORITY_URL', 'string', NULL, 'blockedlog', 'URL of the remote authority used by the blocked log module when remote authority validation is enabled.', 'Set/displayed in blockedlog/admin/blockedlog.php:212 (text input) and checked together with BLOCKEDLOG_USE_REMOTE_AUTHORITY in blockedlog/admin/blockedlog_list.php:1166.', 'Its value is only used when BLOCKEDLOG_USE_REMOTE_AUTHORITY is enabled, providing the endpoint used for remote authority checks.', NULL, 0, 0, 'blockedlog/admin/blockedlog.php|blockedlog/admin/blockedlog_list.php', 1, 'b702e9494f1b8dc835bbd1e6c1be43a355b2e1cb6522d240fcbf9e831c2871e3', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''BLOCKEDLOG_USE_REMOTE_AUTHORITY'') && getDolGlobalString(''BLOCKEDLOG_AUTHORITY_URL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_DEBUG', 'string', NULL, 'blockedlog', 'Enables debug information display in the blocked log (audit trail) admin list pages.', 'Checked repeatedly (9 occurrences) throughout blockedlog/admin/blockedlog_list.php, e.g. lines 468, 501, 558, 660, 786, 794, 939, 1048, each guarding debug output blocks.', 'When enabled, extra debug information is shown to help developers find the origin of bugs in blocked log processing.', NULL, 0, 0, 'blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_list.php', 1, '0897e92a52d7ee3c8b15c782759d7e8c2af1300640e8c186823068065067d7f3', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(\"BLOCKEDLOG_DEBUG\")) {\t// If in experimental or develop mode, we add some debug information. It may help developers to find origin of bugs."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_DISABLE_NOT_ALLOWED_FOR_COUNTRY', 'bool', NULL, 'core', 'Stores a comma-separated list of country codes for which the BlockedLog module is disabled.', 'Read at blockedlog/admin/blockedlog.php:240 (exploded into an array for a multi-select) and at core/modules/modBlockedLog.class.php:89, 99–100. The module activation logic at lines 99–100 checks if $mysoc->country_code appears in this list to suppress the module.', 'If the installation''s company country code is in this list, the BlockedLog module is disabled for that entity.', 'A comma-separated string of ISO country codes (e.g. ''FR,DE''); empty means the module is not disabled for any country.', 0, 0, 'blockedlog/admin/blockedlog.php', 1, 'f95e04521517cdd8d45a934bc5db795bf7241b80a735d7f594ab957273737cfa', 'v2', '2026-04-21T11:16:15+00:00', '["/*if (getDolGlobalString(''BLOCKEDLOG_DISABLE_NOT_ALLOWED_FOR_COUNTRY'')) {", "$tmp = explode('','', getDolGlobalString(''BLOCKEDLOG_DISABLE_NOT_ALLOWED_FOR_COUNTRY''));", "&& in_array((empty($mysoc->country_code) ? '''' : $mysoc->country_code), explode('','', getDolGlobalString(''BLOCKEDLOG_DISABLE_NOT_ALLOWED_FOR_COUNTRY'')))"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_ENABLE_DONATION', 'bool', NULL, 'blockedlog', 'Enables tracking of donation-related events (validate/delete donations and donation payments) in the unalterable blocked log (used by countries requiring tamper-proof logs for donations).', 'In blockedlog/class/blockedlog.class.php:271, when isModEnabled(''don'') and this constant are both true, DON_VALIDATE/DON_DELETE/DONATION_PAYMENT_CREATE/DONATION_PAYMENT_DELETE events are added to $this->trackedevents for the blocked (unalterable) log module.', 'Setting it adds donation module events to the list of actions recorded in the unalterable audit log, which is required in some countries for legal compliance on donation logging.', 'Boolean-like: truthy plus donation module enabled adds donation events to the tracked/logged event list.', 0, 0, NULL, 1, '1d1a347dc1908371b5f4333c270762008767c8aae8e2fa97350efa8b86f49ea8', 'v2', '2026-07-24T07:05:23+00:00', '["blockedlog/class/blockedlog.class.php:271|check|if (isModEnabled(''don'') && getDolGlobalString(''BLOCKEDLOG_ENABLE_DONATION'')) {\t// For countries that need unalterable logs for donations"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_ENABLE_MEMBER', 'bool', NULL, 'blockedlog', 'Enables tracking of membership-related events (subscriptions, payments) in the unalterable blocked log (used by countries requiring tamper-proof logs for membership management).', 'In blockedlog/class/blockedlog.class.php:294, when isModEnabled(''member'') and this constant are both true, member subscription/payment events are added to $this->trackedevents for the blocked (unalterable) log module.', 'Setting it adds membership module events to the list of actions recorded in the unalterable audit log, required in some countries for legal compliance on membership record logging.', 'Boolean-like: truthy plus member module enabled adds membership events to the tracked/logged event list.', 0, 0, NULL, 1, '71608c86c8ba06457c03c7669bc932f2ed50ec94f75f885711fac61fea035c26', 'v2', '2026-07-24T07:05:23+00:00', '["blockedlog/class/blockedlog.class.php:294|check|if (isModEnabled(''member'') && getDolGlobalString(''BLOCKEDLOG_ENABLE_MEMBER'')) {\t// For countries that need unalterable logs for membership management"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_ENTITY_FINGERPRINT', 'string', NULL, 'blockedlog', 'Unique fingerprint generated for the entity''s blocked log chain, used as part of its integrity signature.', 'Generated and stored via dolibarr_set_const at blockedlog/class/blockedlog.class.php:2367/2369 on first insert, and read back at line 2372; the admin UI comment at blockedlog/admin/blockedlog.php:195 documents this behavior.', 'This value is auto-generated on first blocked-log insert and used as a fingerprint; it is not intended to be manually edited.', NULL, 1, 0, NULL, 1, 'f4dc873a876f0b0a395e01a5f3aef853897c55709aecc6826094433192013a61', 'v2', '2026-07-24T06:41:12+00:00', '["// Generated randomly when doing the first insert by blockedlog.class.php, and saved into BLOCKEDLOG_ENTITY_FINGERPRINT", "if (!getDolGlobalString(''BLOCKEDLOG_ENTITY_FINGERPRINT'')) { // creation of a unique fingerprint"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_FOR_TAX_AUDITOR', 'string', NULL, 'blockedlog', 'Enables a special mode of the blocked log module for external tax auditors, with values 1 or 2 changing the access condition.', 'Checked in blockedlog/admin/registration.php:68 combined with userIsTaxAuditor(), and in blockedlog/lib/blockedlog.lib.php:597 where the value 1 requires $user->socid while value 2 does not.', 'Must be set to 1 (with the user linked to a third party) or 2 to grant tax-auditor mode access to the blocked log; other/unset values do not grant this access.', '1 = requires external user with $user->socid set; 2 = grants access regardless of socid', 0, 0, 'blockedlog/admin/registration.php', 1, '313fac4194500823240da1ba5154a80c5754cfeef6dd761b8c6025f09153aa2e', 'v2', '2026-07-24T06:41:12+00:00', '["* Must be an external user and BLOCKEDLOG_FOR_TAX_AUDITOR must be set to 1 OR", "* BLOCKEDLOG_FOR_TAX_AUDITOR must be set to 2"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_HMAC_KEY', 'string', NULL, 'core', 'Secret HMAC key used to sign/verify blocked log (audit trail) records, stored obfuscated rather than in clear text.', 'Generated and stored via install/upgrade2.php:5778 (dolibarr_set_const with comment ''The secret key for HMAC used for blockedlog record'') and read/decoded in blockedlog/admin/registration.php:264 and install/upgrade2.php:5771.', 'This key is used to compute HMAC signatures for blocked log records; it is stored obfuscated and must be un-obfuscated before use, so changing or losing it affects the ability to verify existing signed records.', 'starts with ''BLOCKEDLOGHMAC....''', 1, 0, 'blockedlog/admin/registration.php', 1, '1e7eff3c4622435e63974b24752dc23287dd7a45700fe40e97ba704f3e4eb874', 'v2', '2026-07-24T06:41:12+00:00', '["// BLOCKEDLOG_HMAC_KEY is a HMAC key starting with ''BLOCKEDLOGHMAC....''. It is not stored as a clear data but", "$result = dolibarr_set_const($db, ''BLOCKEDLOG_HMAC_KEY'', $hmac_secret_key, ''chaine'', 0, ''The secret key for HMAC used for blockedlog record'', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_MAX_FOR_SHOWN_LINKS', 'bool', NULL, 'blockedlog', 'Maximum number of BlockedLog entries for which document links are rendered/shown in the blocked-log list and archives admin pages.', 'Read identically in blockedlog/admin/blockedlog_list.php:134 and blockedlog/admin/blockedlog_archives.php:135 (ADMIN_UI both files), stored in $MAXFORSHOWNLINKS with default 100.', 'Raising it shows clickable links for more log lines on the BlockedLog list/archive screens; lowering it reduces the number of lines for which links are displayed, likely for performance on large logs.', 'An integer count; defaults to 100 when unset.', 0, 0, 'blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_archives.php', 1, '3777787d91cae907a59537987e47d767160fcf1592c4495dfd76c08b53d8ff9f', 'v2', '2026-07-24T07:05:23+00:00', '["blockedlog/admin/blockedlog_list.php:134: $MAXFORSHOWNLINKS = getDolGlobalInt(''BLOCKEDLOG_MAX_FOR_SHOWN_LINKS'', 100);", "blockedlog/admin/blockedlog_archives.php:135: $MAXFORSHOWNLINKS = getDolGlobalInt(''BLOCKEDLOG_MAX_FOR_SHOWN_LINKS'', 100);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_MAX_LINES', 'string', NULL, 'blockedlog', 'Sets the maximum number of log lines processed or displayed in blockedlog list and archive pages.', 'Read at blockedlog/admin/blockedlog_list.php:129 and blockedlog/admin/blockedlog_archives.php:134, both with a default of 10000.', 'Reducing this value limits the number of log entries processed per request; increasing it allows more entries but may impact performance.', 'An integer; default is 10000.', 0, 0, 'blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_archives.php', 1, '616b566c60137455b4241d6df1369be98a3146c34876e2ceec91ad405c929437', 'v2', '2026-04-21T11:16:15+00:00', '["$MAXLINES = getDolGlobalInt(''BLOCKEDLOG_MAX_LINES'', 10000);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_RANDOMRANGE_FOR_TRACKING', 'string', NULL, 'blockedlog', 'Controls the probability denominator for blockedlog tracking pings; lower values increase ping frequency.', 'Read at blockedlog/lib/blockedlog.lib.php:443 with a max cap of 10. The comment at line 442 states the probability is between 1/10 by default and 1/1 if set to 1. A separate line at lib:440 forces it to 1 to guarantee every call is tracked.', 'Setting to 1 forces a ping on every call; the default of 10 means roughly a 1/10 chance per call. Cannot be set lower than 1/10 per the code comment.', 'Integer 1–10; default 10. Comment: ''Probability will be between 1/10 by default and 1/1 if const BLOCKEDLOG_RANDOMRANGE_FOR_TRACKING is set to 1. Can''t be lower than 1/10.''', 1, 0, NULL, 1, '7e23f65164c1c2b7b683486c931dc9e6b90e59e9fc14d9a2620c1bafc7502e50', 'v2', '2026-04-21T11:16:15+00:00', '["// Probability will be between 1/10 by default and 1/1 if const BLOCKEDLOG_RANDOMRANGE_FOR_TRACKING is set to 1. Can''t be lower than 1/10.", "$conf->global->BLOCKEDLOG_RANDOMRANGE_FOR_TRACKING = 1;\t\t// Force probability to 1", "$BLOCKEDLOG_RANDOMRANGE_FOR_TRACKING = min(10, getDolGlobalInt(''BLOCKEDLOG_RANDOMRANGE_FOR_TRACKING'', 10));", "//$BLOCKEDLOG_RANDOMRANGE_FOR_TRACKING = 1;\t// To force track at every call"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_REGISTRATION_ADDRESS', 'string', NULL, 'blockedlog', 'Stores the street address of the company used in blockedlog registration data.', 'Written via blockedlog/admin/registration.php:133 and read at line 421 as the default field value. Also consumed at main.inc.php:3887 as ''company_address'' in the ping payload, falling back to $mysoc->address.', 'Changing this value updates the company address transmitted in blockedlog registration payloads.', 'Any string address; falls back to $mysoc->address when not set.', 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|blockedlog/admin/registration.php', 1, 'f77a7e790b97eb299f7d506d7f117ce0010af944f65764570e002f481ffd15b7', 'v2', '2026-04-21T11:16:15+00:00', '["$res = dolibarr_set_const($db, \"BLOCKEDLOG_REGISTRATION_ADDRESS\", $company_address, ''chaine'', 0, '''', $conf->entity);", "''company_address'' => getDolGlobalString(''BLOCKEDLOG_REGISTRATION_ADDRESS'', $mysoc->address),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_REGISTRATION_COUNTRY_ID', 'string', NULL, 'blockedlog', 'Country ID pre-filled in the BlockedLog company registration setup form, defaulting to the company''s own country.', 'Read in blockedlog/admin/registration.php:556 (ADMIN_UI blockedlog/admin/registration.php), used as the default value for a country select feeding BLOCKEDLOG_REGISTRATION_COUNTRY_CODE.', 'Setting it changes which country is pre-selected in the BlockedLog registration/company-identity setup screen; it falls back to $mysoc->country_id when unset.', 'A country id (int); defaults to $mysoc->country_id if not set.', 0, 0, 'blockedlog/admin/registration.php', 1, '17318ba9f853dee532a187fe4b425b55f806ce172f2cc30ba3b2f03ed5b8157b', 'v2', '2026-07-24T07:05:23+00:00', '["blockedlog/admin/registration.php:556: $country_id = getDolGlobalString(''BLOCKEDLOG_REGISTRATION_COUNTRY_ID'', $mysoc->country_id);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_REGISTRATION_EMAIL', 'string', NULL, 'blockedlog', 'Company email address used for blocked log module registration, defaulting to the company''s own email if unset.', 'Set via blockedlog/admin/registration.php:187 (dolibarr_set_const) and read/defaulted to $mysoc->email in blockedlog/admin/registration.php:468/534, main.inc.php:4100, and blockedlog/lib/blockedlog.lib.php:148.', 'Changing it overrides the company email used specifically for the blocked log registration process, otherwise the company''s default email is used.', NULL, 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|blockedlog/admin/registration.php', 1, 'a83fbc1d59e9bef983ecd87503ba85eb165a3fdcbd8d357184a0da6d43ff365a', 'v2', '2026-07-24T06:41:12+00:00', '["''company_email'' => getDolGlobalString(''BLOCKEDLOG_REGISTRATION_EMAIL'', $mysoc->email),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_REGISTRATION_NAME', 'string', NULL, 'blockedlog', 'Company name used for blocked log module registration, defaulting to the company''s own name if unset.', 'Set via blockedlog/admin/registration.php:183 (dolibarr_set_const) and read/defaulted to $mysoc->name in blockedlog/admin/registration.php:467/529, main.inc.php:4099, and blockedlog/lib/blockedlog.lib.php:147.', 'Changing it overrides the company name used specifically for the blocked log registration process, otherwise the company''s default name is used.', NULL, 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|blockedlog/admin/registration.php', 1, 'b36061951c055333c87f171937f86f5d3568cb7ba38366da47cbe302630b8c2e', 'v2', '2026-07-24T06:41:12+00:00', '["''company_name'' => getDolGlobalString(''BLOCKEDLOG_REGISTRATION_NAME'', $mysoc->name),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_REGISTRATION_STATE', 'string', NULL, 'blockedlog', 'Stores the state/region ID of the company used in blockedlog registration data.', 'Written via blockedlog/admin/registration.php:137 and read at lines 333 and 431 to populate the state field in registration forms. Also read at main.inc.php:3888 as ''company_state'' in the ping payload, falling back to $mysoc->state.', 'Changing this value updates the company state transmitted in blockedlog registration payloads.', 'An integer state ID (as stored in llx_c_departements); falls back to $mysoc->state when not set.', 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|blockedlog/admin/registration.php|blockedlog/admin/registration.php', 1, '2e19e0729b4fbaef3bed4cc6f1226175a64becf642f6272ead58255b301f95d3', 'v2', '2026-04-21T11:16:15+00:00', '["$res = dolibarr_set_const($db, \"BLOCKEDLOG_REGISTRATION_STATE\", $company_state, ''chaine'', 0, '''', $conf->entity);", "''company_state'' => getDolGlobalString(''BLOCKEDLOG_REGISTRATION_STATE'', $mysoc->state),", "$company_state = getState(getDolGlobalInt(''BLOCKEDLOG_REGISTRATION_STATE''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_REGISTRATION_TEL', 'string', NULL, 'blockedlog', 'Would hold the registered company phone number used for KYC/registration completeness checks in the blocked-log module, but the code reading it is commented out.', 'In blockedlog/lib/blockedlog.lib.php:152, the line ''$companytel = getDolGlobalString("BLOCKEDLOG_REGISTRATION_TEL", $mysoc->phone);'' is commented out inside isRegistrationDataSaved(), so it is not currently used to determine registration completeness (unlike the active BLOCKEDLOG_REGISTRATION_NAME/EMAIL checks nearby).', 'Currently has no effect since the line reading it is commented out; if uncommented, it would fall back to $mysoc->phone and be used as part of the KYC mandatory-fields check.', 'String: intended to be a phone number, defaulting to $mysoc->phone if unset (per the commented-out code).', 0, 0, NULL, 1, '4becdf3eeb02f71ff14f7e4dac0603f23d327e375c4e97fdbd23fae8d0f76d41', 'v2', '2026-07-24T07:05:23+00:00', '["blockedlog/lib/blockedlog.lib.php:152|read|//$companytel = getDolGlobalString(''BLOCKEDLOG_REGISTRATION_TEL'', $mysoc->phone);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_REGISTRATION_TOWN', 'string', NULL, 'blockedlog', 'Stores the city/town of the company used in blockedlog registration data.', 'Written via blockedlog/admin/registration.php:145 and read at line 441 as the default field value. Also consumed at main.inc.php:3890 as ''company_town'' in the ping payload, falling back to $mysoc->town.', 'Changing this value updates the company town transmitted in blockedlog registration payloads.', 'Any string town name; falls back to $mysoc->town when not set.', 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|blockedlog/admin/registration.php', 1, '420db343978390f03f17e93e322728d41fd2682c94cdb4d9578f5a5497a8116b', 'v2', '2026-04-21T11:16:15+00:00', '["$res = dolibarr_set_const($db, \"BLOCKEDLOG_REGISTRATION_TOWN\", $company_town, ''chaine'', 0, '''', $conf->entity);", "''company_town'' => getDolGlobalString(''BLOCKEDLOG_REGISTRATION_TOWN'', $mysoc->town),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_REGISTRATION_ZIP', 'string', NULL, 'blockedlog', 'Stores the postal/ZIP code of the company used in blockedlog registration data.', 'Written via blockedlog/admin/registration.php:141 and read at line 436 as the default field value. Also consumed at main.inc.php:3889 as ''company_zip'' in the ping payload, falling back to $mysoc->zip.', 'Changing this value updates the company ZIP code transmitted in blockedlog registration payloads.', 'Any string postal code; falls back to $mysoc->zip when not set.', 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|blockedlog/admin/registration.php', 1, '996293243c138b92a81c67cd853d2adcb3c14a7279b5a95e401e49d1d8f28ade', 'v2', '2026-04-21T11:16:15+00:00', '["$res = dolibarr_set_const($db, \"BLOCKEDLOG_REGISTRATION_ZIP\", $company_zip, ''chaine'', 0, '''', $conf->entity);", "''company_zip'' => getDolGlobalString(''BLOCKEDLOG_REGISTRATION_ZIP'', $mysoc->zip),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BLOCKEDLOG_USE_REMOTE_AUTHORITY', 'bool', NULL, 'blockedlog', 'Enables use of a remote authority service for the blocked log (audit trail) module.', 'Set/displayed in blockedlog/admin/blockedlog.php:203, and checked together with BLOCKEDLOG_AUTHORITY_URL in blockedlog/admin/blockedlog_list.php:1166; a related usage in blockedlog/admin/blockedlog_archives.php:1324 is commented out.', 'When enabled, blocked log processing consults the remote authority URL configured in BLOCKEDLOG_AUTHORITY_URL.', NULL, 0, 0, 'blockedlog/admin/blockedlog.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_archives.php', 1, 'ba657b3ff5ab76d957f7c1d1ff05c9e6e77b9b3295bcc4e4c27623bf5e9116aa', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''BLOCKEDLOG_USE_REMOTE_AUTHORITY'') && getDolGlobalString(''BLOCKEDLOG_AUTHORITY_URL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_ADDON', 'string', NULL, 'bom', 'Selects the numbering module (add-on) used to generate reference numbers for Bills of Materials.', 'Stores the class name of the active BOM reference numbering add-on. Read in bom/class/bom.class.php:881-882 where the value is used as a filename and class name to instantiate the numbering module. Configurable via admin/bom.php.', 'Changing this value switches the numbering module used for new BOM references; existing references are unaffected.', 'String: name of a numbering module class (e.g. ''mod_bom_standard''). Must match an existing .php file in the BOM module.', 0, 0, 'admin/bom.php|admin/bom.php', 1, 'e1cf8bd165954bdaa204b46e08638232e275e148baa74a33573acb96cdc725e0', 'v2', '2026-04-21T11:16:15+00:00', '["bom/class/bom.class.php:868  *  defined into BOM_ADDON", "bom/class/bom.class.php:881|read|$file = getDolGlobalString(''BOM_ADDON'') . \".php\";", "bom/class/bom.class.php:882|read|$classname = getDolGlobalString(''BOM_ADDON'');", "admin/bom.php:148|write|dolibarr_set_const($db, \"BOM_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_ADDON_PDF', 'string', NULL, 'admin', 'Selects the PDF template module used to generate PDF documents for Bills of Materials.', 'Stores the name of the active PDF model for BOMs. Read in bom/class/bom.class.php:1331-1332 to select the PDF generation class. Configurable via admin/bom.php.', 'Changing this value switches the PDF template used when generating BOM documents; no effect on already-generated files.', 'String: name of a PDF model class available in the BOM module.', 0, 0, 'admin/bom.php|admin/bom.php|admin/bom.php|admin/bom.php|admin/bom.php', 1, 'cdd043a1694b3d22f472c65cc91136981b3b1433ce19f2eebad7a26f4031934f', 'v2', '2026-04-21T11:16:15+00:00', '["bom/class/bom.class.php:1331|read|} elseif (getDolGlobalString(''BOM_ADDON_PDF'')) {", "bom/class/bom.class.php:1332|read|$modele = getDolGlobalString(''BOM_ADDON_PDF'');", "admin/bom.php:133|write|if (dolibarr_set_const($db, \"BOM_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "admin/bom.php:127|check|if (getDolGlobalString(''BOM_ADDON_PDF'') == \"$value\") {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Comma/newline-separated list of directories to scan for ODT templates used to generate BOM (Bill of Materials) documents.', 'Set as `$this->scandir = ''BOM_ADDON_PDF_ODT_PATH''` in core/modules/bom/doc/doc_generic_bom_odt.modules.php:71 and read at line 114 as `$odtPath = trim(getDolGlobalString(''BOM_ADDON_PDF_ODT_PATH''))`; it is also wired into the module''s admin form as a hidden ''param1''/''keyforuploaddir'' field for file upload/delete actions.', 'Changing it changes which directories are scanned for ODT model files offered when generating a BOM document; an invalid/empty path means no custom ODT templates are found.', 'Free-form string: one or more directory paths (may include the DOL_DATA_ROOT placeholder), comma or newline separated.', 0, 0, NULL, 1, '33b0bc36e2492a5eac86d2892416567d0ffa05d4833071961830b1f9dbe50b5b', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/bom/doc/doc_generic_bom_odt.modules.php:71: $this->scandir = ''BOM_ADDON_PDF_ODT_PATH''; // Name of constant that is used to save list of directories to scan", "core/modules/bom/doc/doc_generic_bom_odt.modules.php:114: $odtPath = trim(getDolGlobalString(''BOM_ADDON_PDF_ODT_PATH''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_ADVANCED_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the Advanced BOM module for bill-of-materials references.', 'Read in core/modules/bom/mod_bom_advanced.php at line 139 for mask-based reference generation, and at line 90 to populate the mask input field in the module''s configuration UI.', 'Changing this value alters the format of BOM reference numbers generated by the Advanced module; leaving it unset results in an empty mask.', 'Any valid mask string for BOM numbering.', 1, 0, NULL, 1, 'ea5b209df3ac816fb76121320b9412403aae416d1f7183299d2d0a822299a96c', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/bom/mod_bom_advanced.php:139|read|$mask = getDolGlobalString(''BOM_ADVANCED_MASK'');", "core/modules/bom/mod_bom_advanced.php:90|read|$texte .= ''<td class=\"right\">''.$form->textwithpicto(''<input type=\"text\" class=\"flat minwidth175\" name=\"maskBom\" value=\"''.getDolGlobalString(''BOM_ADVANCED_MASK'').''\">'', $tooltip, 1,"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_BOX_LAST_BOMS_SHOW_VALIDATE_USER', 'bool', NULL, 'core', 'Shows the validating user column in the ''Last BOMs'' dashboard box.', 'In core/boxes/box_boms.php:130, when set, the box adds a column showing the user who validated the BOM (fk_user_valid), mirroring the same pattern used by ORDER_BOX_LAST_ORDERS_SHOW_VALIDATE_USER.', 'When enabled, the last-BOMs dashboard widget displays an extra column with the validating user''s link; when unset, the column is omitted.', 'boolean: 1/true adds the validate-user column to the box; unset/0 = column not shown.', 1, 0, NULL, 1, '5418477b7cf2dba344b88a21bfb87ed21eaa8d82f6129cc760cc355bd77a14a6', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_boms.php:130|check|if (getDolGlobalString(''BOM_BOX_LAST_BOMS_SHOW_VALIDATE_USER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_CLONE_DEFBOM', 'string', NULL, 'product', 'Sets the default checked/unchecked state of the ''clone default BOM'' checkbox when cloning a product.', 'Read in product/card.php:3130 as the default ''value'' of a checkbox in the clone confirmation form ($formquestionclone), shown only when the bom module is enabled and the product has a default BOM (fk_default_bom > 0).', 'Only affects whether the clone-BOM checkbox is pre-checked by default; the user can still toggle it before confirming the clone.', 'Integer used as a checkbox default value (0 = unchecked, non-zero = checked).', 0, 0, NULL, 1, 'a52f6b85854440fcf46340e2309c327d3d4193d30e3da831186d9145288d1575', 'v2', '2026-07-24T07:05:23+00:00', '["product/card.php:3130|''value'' => getDolGlobalInt(''BOM_CLONE_DEFBOM'')"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_DRAFT_WATERMARK', 'string', NULL, 'admin', 'Defines the watermark text displayed on draft BOM PDF documents.', 'Configurable via the admin UI at admin/bom.php (written at line 151, displayed at line 534 as a text input). No occurrence in the PDF generation code is present in this payload.', 'Setting this to a non-empty string causes the specified text to appear as a watermark on draft BOM documents; clearing it removes the watermark.', 'string (watermark text); empty = no watermark', 0, 0, 'admin/bom.php|admin/bom.php', 1, 'a58ea9580c1fb1225f75e8373f8037f78014f7eae80da802a106f3ce7307a199', 'v2', '2026-04-21T13:29:58+00:00', '["admin/bom.php:151|write|$res = dolibarr_set_const($db, \"BOM_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "admin/bom.php:534|read|print ''<input class=\"flat minwidth200\" type=\"text\" name=\"BOM_DRAFT_WATERMARK\" value=\"''.dol_escape_htmltag(getDolGlobalString(''BOM_DRAFT_WATERMARK'')).''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated Bill of Materials (BOM) documents.', 'Written from admin/bom.php:163 via dolibarr_set_const() when the admin saves the BOM module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated BOM documents; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/bom.php', 1, '7f085b8094df222435af1cd1b9911494f663c317a69219f5dd517ce2718b425c', 'v2', '2026-07-24T07:05:23+00:00', '["admin/bom.php:163|write|$res = dolibarr_set_const($db, \"BOM_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_MAX_VISIBLE_PHOTO', 'string', NULL, 'core', 'Sets the maximum number of photos shown in the Bill of Materials (BOM) photo block on the object card.', 'In core/lib/functions.lib.php:3458, used as `getDolGlobalInt(''BOM_MAX_VISIBLE_PHOTO'', 5)` to cap photos passed to show_photos() for a BOM object; default is 5, forced to 1 on phone layout.', 'Increasing/decreasing the value changes how many BOM photos are displayed at once in the card header photo block.', 'Integer count of photos to display; default 5 if unset.', 1, 0, NULL, 1, '5329727ebdecea165afe7828d602ed57123631599b69769f526f17cf21544c53', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3458|read|$maxvisiblephotos = getDolGlobalInt(''BOM_MAX_VISIBLE_PHOTO'', 5);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_NODISPLAYIFNOPHOTO', 'string', NULL, 'core', 'Suppresses the ''no photo'' placeholder image on the BOM card when the BOM has no photo.', 'In core/lib/functions.lib.php:3465, mirrors the product/category/ticket pattern: if no photo is available and this constant is set, an empty div is shown instead of the nophoto.png placeholder.', 'Enabling it hides the generic ''no photo'' placeholder for BOMs without photos, showing an empty block instead.', 'Boolean-like: any truthy value suppresses the no-photo placeholder.', 1, 0, NULL, 1, '7f056e1aa863993ac9734db1da83a8262825b109a2242dd0dab1a5afac2c449f', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3465|check|if (getDolGlobalString(''BOM_NODISPLAYIFNOPHOTO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_SHOW_ALL_BOM_BY_DEFAULT', 'bool', NULL, 'mrp', 'Controls whether all Bill of Materials (BOM) lines are expanded (shown) by default in BOM and MRP views.', 'Checked in mrp/tpl/originproductline.tpl.php and bom/tpl/objectline_view.tpl.php. When falsy, a closed-folder icon is shown and BOM lines are collapsed; when truthy, an open-folder icon is shown and all BOM lines are displayed. No admin UI is configured.', 'Enabling this constant causes BOM sub-lines to be expanded by default in the UI, improving visibility at the cost of a more cluttered display.', 'Truthy (non-empty / 1) = all BOM lines shown expanded by default; falsy (empty / 0) = BOM lines collapsed by default.', 1, 0, NULL, 1, '8fbbeac75e464570e6dc3a6b7cfb29e2869e42727d07780a6abecbebdc73f3ba', 'v2', '2026-04-21T11:16:15+00:00', '["mrp/tpl/originproductline.tpl.php:76|read|print(!getDolGlobalString(''BOM_SHOW_ALL_BOM_BY_DEFAULT'') ? img_picto('''', ''folder'') : img_picto('''', ''folder-open''));", "bom/tpl/objectline_view.tpl.php:128|read|print(!getDolGlobalString(''BOM_SHOW_ALL_BOM_BY_DEFAULT'') ? img_picto('''', ''folder'') : img_picto('''', ''folder-open''));", "mrp/tpl/originproductline.tpl.php:146|check|if (!getDolGlobalString(''BOM_SHOW_ALL_BOM_BY_DEFAULT'')) {", "bom/tpl/objectline_view.tpl.php:308|check|if (!getDolGlobalString(''BOM_SHOW_ALL_BOM_BY_DEFAULT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_SUB_BOM', 'string', NULL, 'bom', 'Enables the use of sub-BOMs (nested Bills of Materials) within a BOM or Manufacturing Order.', 'Checked in admin/bom.php at line 479, mrp/class/mo.class.php at line 1785, and bom/ template files at lines 74 and 155. Also used in bom/bom_net_needs.php at line 245 for tree-view rendering of nested BOM needs.', 'When disabled, sub-BOM lines are hidden from BOM and MO line templates and the net-needs tree view is suppressed. Enabling it allows hierarchical BOM structures.', '0 or unset = sub-BOMs disabled; 1 = sub-BOMs enabled', 0, 0, 'admin/bom.php', 1, 'c437a9efd2b06556eabb9b2821b621bf3293cc6a2e17ec495daae35ddae53e70', 'v2', '2026-04-21T11:16:15+00:00', '["if (!getDolGlobalString(''BOM_SUB_BOM'')) {", "if (getDolGlobalString(''BOM_SUB_BOM'')) {", "if (getDolGlobalString(''BOM_SUB_BOM'') && $filtertype != 1) {", "if (getDolGlobalString(''BOM_SUB_BOM'')  && $action == ''treeview'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOM_USE_SEARCH_TO_SELECT', 'bool', NULL, 'admin', 'Enables the search-to-select (ajax combobox) mode for BOM selection dropdowns instead of a plain select.', 'Configurable via admin UI at admin/bom.php (written at line 157, displayed at line 504) and shown in admin/system/perf.php at lines 628 and 631. The combobox is activated in core/class/html.form.class.php:3070.', 'Enabling this activates an AJAX-powered search input for selecting BOMs, improving performance with large datasets; disabling it uses a plain dropdown.', 'string/int; truthy = use search-to-select; empty/not set = plain select', 0, 0, 'admin/bom.php|admin/system/perf.php|admin/system/perf.php|admin/bom.php', 1, 'cfd53f89c31388daa845f43e087d4c99010a4253873ccb57f2a2eb1f27a10dd9', 'v2', '2026-04-21T13:29:58+00:00', '["admin/bom.php:157|write|$res = dolibarr_set_const($db, \"BOM_USE_SEARCH_TO_SELECT\", $bomsearch, ''chaine'', 0, '''', $conf->entity);", "admin/bom.php:504|read|print $form->selectarray(\"activate_BOM_USE_SEARCH_TO_SELECT\", $arrval, getDolGlobalString(\"BOM_USE_SEARCH_TO_SELECT\")).''</td>'';", "admin/system/perf.php:628|check|if (!getDolGlobalString(''BOM_USE_SEARCH_TO_SELECT'')) {", "core/class/html.form.class.php:3070|read|$out .= ajax_combobox($htmlname, $events, getDolGlobalInt(\"BOM_USE_SEARCH_TO_SELECT\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOOKCAL_AVAILABILITIES_ADDON', 'string', NULL, 'core', 'Selects the add-on module class used to generate availability reference numbers in the BookCal module.', 'Read in core/modules/modAi.class.php:331-332. When empty, defaults to ''mod_availabilities_standard''; otherwise uses the configured value as both the class name and the PHP file path under /core/modules/commande/.', 'Changing this constant switches the availability numbering add-on; an incorrect value will cause a missing-file error when generating availability references.', 'String module name, e.g. ''mod_availabilities_standard''.', 1, 0, NULL, 1, 'e176bdd66a6ffc5e708fdacacce09c4c22aeb9e9bce34aaa58c0414b67f065b7', 'v2', '2026-04-21T13:50:40+00:00', '["''class''=>(empty($conf->global->BOOKCAL_AVAILABILITIES_ADDON) ? ''mod_availabilities_standard'' : $conf->global->BOOKCAL_AVAILABILITIES_ADDON),", "''path''=>\"/core/modules/commande/\".(empty($conf->global->BOOKCAL_AVAILABILITIES_ADDON) ? ''mod_availabilities_standard'' : $conf->global->BOOKCAL_AVAILABILITIES_ADDON).''.php''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOOKCAL_PUBLIC_INTERFACE_TOPIC', 'string', NULL, 'public', 'Sets the page title/topic displayed in the public BookCal (appointment booking) interface header.', 'Read at public/bookcal/index.php:151 as the topic argument to htmlPrintOnlineHeader(); falls back to the translated string ''BookCalSystem'' if unset. Referenced in bookcal/admin/setup.php:77 as a setup configuration constant.', 'If set, the public booking page header will display this custom topic string instead of the default translated label.', 'Any string; defaults to trans(''BookCalSystem'') if not set.', 1, 0, NULL, 1, '0339798f5b6f12cd951d159be4cc0a060223199d1ee24a4707371f663edca810', 'v2', '2026-04-21T13:50:40+00:00', '["bookcal/admin/setup.php:77  // Setup conf BOOKCAL_PUBLIC_INTERFACE_TOPIC", "public/bookcal/index.php:151|read|htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''BOOKCAL_PUBLIC_INTERFACE_TOPIC'', $langs->trans(\"BookCalSystem\")), ''BOOKCAL_PUBLIC_INTERFACE_IMAGE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOOKCAL_SECUREKEY', 'string', NULL, 'bookcal', 'Secret key used to derive the security token embedded in public booking-calendar links.', 'Read in bookcal/calendar_card.php:387 where it is concatenated with the string ''bookcal'' and the object id, then hashed (md5) to produce the ''securekey'' URL parameter of the public booking page link.', 'Changing this value invalidates all previously generated public booking links, since the hash embedded in those URLs will no longer match; it acts as a salt/secret for the public link''s access token.', 'String: an arbitrary secret/salt value used only as hash input; no enumerated values found.', 1, 0, NULL, 1, '446606a9388ec3e1c04561012800ab23d0e7c48c679a60784c0872da91232a11', 'v2', '2026-07-24T07:05:23+00:00', '["bookcal/calendar_card.php:387|read|$encodedsecurekey = dol_hash(getDolGlobalString(''BOOKCAL_SECUREKEY'').''bookcal''.((int) $object->id), ''md5'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOOKKEEPING_ADDON', 'string', NULL, 'accountancy', 'Specifies the bookkeeping reference number generator module to use.', 'Configured via accountancy/admin/index.php. Documented in accountancy/class/bookkeeping.class.php:2041: ''defined into BOOKKEEPING_ADDON''. The class name is read at bookkeeping.class.php:2054 and the file loaded at :2053. Default ''mod_bookkeeping_neon'' is set during install/upgrade (install/upgrade2.php:5477) and used as fallback in accountancy/bookkeeping/card.php:120.', 'Changing this value switches the module responsible for generating bookkeeping reference numbers; an empty value causes fallback to ''mod_bookkeeping_neon''.', 'String: module name (e.g. ''mod_bookkeeping_neon''); empty = no module selected', 0, 0, 'accountancy/admin/index.php|accountancy/admin/index.php', 1, '7611fcf35f403edce4785cf900d5a712abbe32f7442bc0a510183fec583941ba', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/class/bookkeeping.class.php:2041  *  defined into BOOKKEEPING_ADDON", "install/upgrade2.php:5477|write|dolibarr_set_const($db, ''BOOKKEEPING_ADDON'', ''mod_bookkeeping_neon'', ''chaine'', 0, '''', $entity);", "accountancy/bookkeeping/card.php:120|read|$numRefModel = getDolGlobalString(''BOOKKEEPING_ADDON'', ''mod_bookkeeping_neon'');", "accountancy/class/bookkeeping.class.php:2053|read|$file = getDolGlobalString(''BOOKKEEPING_ADDON'') . \".php\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOOKKEEPING_HELIUM_MASK', 'string', NULL, 'core', 'Numbering mask used by the ''Helium'' numbering module for bookkeeping/accountancy entry references.', 'Read/written by mod_bookkeeping_helium (core/modules/accountancy/mod_bookkeeping_helium.php:96,144): shown in an admin setup form input and consumed by getNextValue() to compute the next bookkeeping entry ref.', 'Changing the mask changes the format of future bookkeeping references generated by this numbering module; existing refs are unaffected.', 'Free-form mask string using Dolibarr''s generic mask code syntax (GenericMaskCodes tooltip), same convention as other numbering-module masks.', 0, 0, NULL, 1, 'bbba9151b017697aef49e7e88f0cc2acc0f4088b210ccfabb8d0c2bf0621efd9', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/accountancy/mod_bookkeeping_helium.php:144|read|$mask = getDolGlobalString(\"BOOKKEEPING_HELIUM_MASK\");", "core/modules/accountancy/mod_bookkeeping_helium.php:96|read|...name=\"maskbookkeeping\" value=\"''.getDolGlobalString(\"BOOKKEEPING_HELIUM_MASK\")"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BOOKMARKS_SHOW_IN_MENU', 'bool', NULL, 'bookmarks', 'Sets the maximum number of bookmark links displayed in the top navigation menu.', 'Written by bookmarks/admin/bookmark.php:54 and displayed as a text input at bookmarks/admin/bookmark.php:94. Read in bookmarks/bookmarks.lib.php:116 and :150 and core/bookmarks_page.php:113 as a loop limit: bookmarks are iterated while the count is below this value.', 'Setting a number limits the menu to that many bookmark entries; leaving it empty shows all bookmarks in the menu.', 'Integer string = maximum number of bookmarks shown in menu; empty/0 = no limit (all bookmarks shown).', 0, 0, 'bookmarks/admin/bookmark.php|bookmarks/admin/bookmark.php', 1, '2775aadc9b809a93979e9eee8586633544e1076b6e6f3bef2c614975ce74e82a', 'v2', '2026-04-21T11:16:15+00:00', '["bookmarks/admin/bookmark.php:54|write|$res = dolibarr_set_const($db, \"BOOKMARKS_SHOW_IN_MENU\", $showmenu, ''chaine'', 0, '''', $conf->entity);", "bookmarks/bookmarks.lib.php:116|read|while ((!getDolGlobalString(''BOOKMARKS_SHOW_IN_MENU'') || $i < getDolGlobalInt(''BOOKMARKS_SHOW_IN_MENU'')) && $obj = $db->fetch_object($resql)) {", "core/bookmarks_page.php:113|read|while ((!getDolGlobalString(''BOOKMARKS_SHOW_IN_MENU'') || $i < $conf->global->BOOKMARKS_SHOW_IN_MENU) && $obj = $db->fetch_object($resql)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('BUYPRICEHISTORY_PRODUCTFOURNISSEURPRICE_ADDON', 'string', NULL, 'product', 'Specifies the add-on class name used for buy-price history numbering on supplier product prices.', 'Checked and read in product/class/productfournisseurprice.class.php (lines 901, 905, 908, 909). If not set, the code writes the default value ''mod_productfournisseurprice_standard'' (line 902) before loading the class. The add-on filename is derived by appending ''.php'' to the constant value.', 'Changing this value to a custom add-on class name replaces the standard buy-price history numbering logic with the specified module.', 'String class name; default ''mod_productfournisseurprice_standard'' when not set', 1, 0, NULL, 1, 'f53de3e29cd80a4c32312f642ffc1027106a239fdea5070833fa1b585a72afe6', 'v2', '2026-04-21T11:16:15+00:00', '["product/class/productfournisseurprice.class.php:901|check|if (!getDolGlobalString(''BUYPRICEHISTORY_PRODUCTFOURNISSEURPRICE_ADDON'')) {", "product/class/productfournisseurprice.class.php:902|write|$conf->global->BUYPRICEHISTORY_PRODUCTFOURNISSEURPRICE_ADDON = ''mod_productfournisseurprice_standard'';", "product/class/productfournisseurprice.class.php:908|read|$file = getDolGlobalString(''BUYPRICEHISTORY_PRODUCTFOURNISSEURPRICE_ADDON'') . \".php\";", "product/class/productfournisseurprice.class.php:909|read|$classname = getDolGlobalString(''BUYPRICEHISTORY_PRODUCTFOURNISSEURPRICE_ADDON'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CALENDAR_ADDON_PDF', 'string', NULL, 'bookcal', 'Names the default PDF document model used to generate ''calendar'' (bookcal) documents.', 'Read in bookcal/class/calendar.class.php:979-980 as fallback model name (''standard_calendar'' otherwise); note this code block is inside a commented-out /* ... */ section in the source read (generateDocument body appears disabled/inactive in this version).', 'If active, setting it would change which PDF template (registered under core/modules/bookcal/doc/) is used by default when generating a calendar document; however the surrounding code is currently commented out in the file as read.', 'String: name of a registered bookcal/calendar PDF document model (fallback default is ''standard_calendar'').', 1, 0, NULL, 1, 'b9c0031b15b02e6807b445db406cdd1660adc91846868dfa0a449f70ea17f081', 'v2', '2026-07-24T07:05:23+00:00', '["bookcal/class/calendar.class.php:979|read|} elseif (getDolGlobalString(''CALENDAR_ADDON_PDF'')) {", "bookcal/class/calendar.class.php:980|read|$modele = getDolGlobalString(''CALENDAR_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CANDIDATURE_ADDON', 'string', NULL, 'emailcollector', 'Would select the numbering module for candidature refs in an emailcollector operation, but the code path is commented out.', 'The only occurrence, emailcollector/class/emailcollector.class.php:3816, sits inside a /* ... */ commented-out block (confirmed by reading lines 3790-3830) that was meant to assign a ref-numbering class (''mod_candidature_simple'' default) to a candidature created from an email. This code is dead/inactive on develop; the active, unrelated constant for candidature numbering is RECRUITMENT_RECRUITMENTCANDIDATURE_ADDON in core/modules/modRecruitment.class.php.', 'No effect: the block reading this constant is commented out, so setting CANDIDATURE_ADDON does not currently change any behavior in the codebase.', 'Not specified; intended as a numbering-module class name (e.g. ''mod_candidature_simple'') per the dead code''s fallback default.', 1, 0, NULL, 1, 'e91c2b5c272f3f8472a58b4817f781e2b926e4e40f0f7a5bc34d7b473bbdab13', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:3816|read|$modele = empty($conf->global->CANDIDATURE_ADDON) ? ''mod_candidature_simple'' : $conf->global->CANDIDATURE_ADDON;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_FORCE_DECREASE_STOCK', 'string', NULL, 'takepos', 'Deprecated constant that formerly forced stock decrease on TakePOS sales; no longer functional.', 'Checked once at takepos/admin/terminal.php:359. The adjacent comment at line 358 reads: ''Deprecated: CASHDESK_FORCE_DECREASE_STOCK is now always false. No more required/used.'' Configurable via the admin UI at takepos/admin/terminal.php.', 'This constant has no effect on current behavior; it is retained only for backward compatibility and should not be set.', 'Deprecated — value has no effect', 0, 0, 'takepos/admin/terminal.php', 1, '189290bb3401b7a1d150d32a647d0e4bfe582aa2ab460ba58dfbb3462db9e392', 'v2', '2026-04-21T13:50:40+00:00', '["// Deprecated: CASHDESK_FORCE_DECREASE_STOCK is now always false. No more required/used.", "if (isModEnabled(''productbatch'') && getDolGlobalString(''CASHDESK_FORCE_DECREASE_STOCK'') && !getDolGlobalString(''CASHDESK_NO_DECREASE_STOCK''.$terminal)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_BANKACCOUNT_CASH', 'string', NULL, 'takepos', 'ID of the bank account used for cash payments on a given TakePOS (point of sale) terminal.', 'Set via takepos/admin/terminal.php:94 (dolibarr_set_const, suffixed with the terminal id) and read at takepos/admin/terminal.php:226/228, compta/cashcontrol/cashcontrol_card.php:208, and takepos/invoice.php:318 (marked ''For backward compatibility'').', 'Selects which bank account cash payments from the specified TakePOS terminal are recorded against; if unset (and the non-suffixed variant is also unset), cash register control checks flag this as missing configuration.', NULL, 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'db928d8b9f182d2f978840c7faeac3e33d95ebf66d09ae1e6711574a9186944f', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''CASHDESK_ID_BANKACCOUNT_CASH'') && !getDolGlobalString(''CASHDESK_ID_BANKACCOUNT_CASH1'')) {", "$bankaccount = getDolGlobalInt(''CASHDESK_ID_BANKACCOUNT_CASH''.$_SESSION[\"takeposterminal\"]);            // For backward compatibility"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_BANKACCOUNT_CASH1', 'string', NULL, 'compta', 'Stores the bank account ID used for cash payments on TakePOS terminal 1 (the numeric suffix identifies the terminal).', 'Written via admin UI takepos/admin/terminal.php (dolibarr_set_const on GETPOSTISSET(''CASHDESK_ID_BANKACCOUNT_CASH''.$terminaltouse)) and auto-created/fallback-set in core/modules/modTakePos.class.php:330-346 during module init if not already set (creates a ''CASH-POS'' bank account and stores its id).', 'If unset, TakePos module activation automatically creates a CASH-POS bank account and stores its id here; changing it redirects where TakePos cash payments for terminal 1 are recorded (compta/cashcontrol/cashcontrol_card.php, takepos/invoice.php).', 'Integer id of a bank account (fk_bank record); empty/0 means not yet configured, in which case module init auto-creates one.', 0, 0, NULL, 1, 'fc089be1bd0496191868b38ebf70edf85299c968572ecbe5381dbb39a7611613', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modTakePos.class.php:330: if (!getDolGlobalInt(''CASHDESK_ID_BANKACCOUNT_CASH1'')) {", "core/modules/modTakePos.class.php:346: dolibarr_set_const($this->db, \"CASHDESK_ID_BANKACCOUNT_CASH1\", $searchaccountid, ''chaine'', 0, '''', $conf->entity);", "takepos/admin/terminal.php:94: $res = dolibarr_set_const($db, \"CASHDESK_ID_BANKACCOUNT_CASH\".$terminaltouse, ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_BANKACCOUNT_CB', 'string', NULL, 'takepos', 'Stores the id of the bank account used for card (CB) payments on a given TakePOS cash desk terminal; name is suffixed with the terminal number.', 'In takepos/admin/terminal.php the admin form writes this per-terminal constant (line 100, dolibarr_set_const with suffix $terminaltouse) and reads it back (line 244) to preselect the bank account in a select_comptes dropdown; line 246 checks it to count configured accounts.', 'Setting it selects which bank account receives CB card payment records for that TakePOS terminal; the constant name as stored in the DB always carries a numeric terminal suffix (e.g. CASHDESK_ID_BANKACCOUNT_CB1), not the bare name.', 'integer bank account (llx_bank_account) id, or empty if none configured for that terminal.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '0f6a049a3440c996050534fb5d7c5b4d7e5278b1aa07c06104d538b52f3acfb1', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/admin/terminal.php:99: if (GETPOSTISSET(''CASHDESK_ID_BANKACCOUNT_CB''.$terminaltouse)) {", "takepos/admin/terminal.php:100|write|$res = dolibarr_set_const($db, \"CASHDESK_ID_BANKACCOUNT_CB\".$terminaltouse, (GETPOST(''CASHDESK_ID_BANKACCOUNT_CB''.$terminaltouse, ''alpha'') > 0 ? GETPOST(...", "takepos/admin/terminal.php:244|read|print $form->select_comptes(getDolGlobalInt(''CASHDESK_ID_BANKACCOUNT_CB''.$terminaltouse), ''CASHDESK_ID_BANKACCOUNT_CB''.$terminaltouse, 0, \"(courant:=:1)\", 1, ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_BANKACCOUNT_CHEQUE', 'string', NULL, 'takepos', 'ID of the bank account used for cheque payments on a given TakePOS (point of sale) terminal.', 'Set via takepos/admin/terminal.php:97 (dolibarr_set_const, suffixed with the terminal id) and read at takepos/admin/terminal.php:235/237 and takepos/invoice.php:320 (marked ''For backward compatibility'').', 'Selects which bank account cheque payments from the specified TakePOS terminal are recorded against.', NULL, 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '0784faf2d00eb4ef625681cddb8956eaaac5f04d66a0ca015ba1533309cffc51', 'v2', '2026-07-24T06:41:12+00:00', '["$bankaccount = getDolGlobalInt(''CASHDESK_ID_BANKACCOUNT_CHEQUE''.$_SESSION[\"takeposterminal\"]);    // For backward compatibility"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_BANKACCOUNT_STRIPETERMINAL', 'string', NULL, 'takepos', 'Stores the id of the bank account associated with a Stripe Terminal card reader on a given TakePOS cash desk terminal; name is suffixed with the terminal number.', 'In takepos/admin/terminal.php the admin form writes this per-terminal constant (line 103, dolibarr_set_const) and reads it back (line 284) to preselect the value in a select of available Stripe Terminal readers, shown only when isModEnabled(''stripe'') && STRIPE_CARD_PRESENT.', 'Setting it links a specific Stripe Terminal reader/bank account to that TakePOS terminal for in-person Stripe card payments; the stored constant name carries a numeric terminal suffix.', 'integer bank account id (as stored via the Stripe reader select), or empty if none configured.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '85dca17f993cef29da9e02f8f45c059e22c08c7ef5e9d54eb0c0db2ee4e8f95a', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/admin/terminal.php:102: if (GETPOSTISSET(''CASHDESK_ID_BANKACCOUNT_STRIPETERMINAL''.$terminaltouse)) {", "takepos/admin/terminal.php:103: $res = dolibarr_set_const($db, \"CASHDESK_ID_BANKACCOUNT_STRIPETERMINAL\".$terminaltouse, GETPOST(..., ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/admin/terminal.php:284: print $form->selectarray(''CASHDESK_ID_BANKACCOUNT_STRIPETERMINAL''.$terminaltouse, $reader, getDolGlobalString(...));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_BANKACCOUNT_SUMUP', 'string', NULL, 'takepos', 'Stores the id of the bank account used for SumUp card payments on a given TakePOS cash desk terminal; name is suffixed with the terminal number.', 'In takepos/admin/terminal.php the admin form writes this per-terminal constant (line 106, dolibarr_set_const) and reads it back (line 292) to preselect the account in a select_comptes dropdown, shown only when TAKEPOS_ENABLE_SUMUP is on.', 'Setting it selects which bank account receives SumUp card payment records for that TakePOS terminal; the stored constant name carries a numeric terminal suffix (e.g. CASHDESK_ID_BANKACCOUNT_SUMUP1).', 'integer bank account (llx_bank_account) id, or empty if none configured for that terminal.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '7d1b6d5dd7b361252cb47a4e51b327a5074c5d1bd7ea1b9bbfa08d331e08e7bf', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/admin/terminal.php:105: if (GETPOSTISSET(''CASHDESK_ID_BANKACCOUNT_SUMUP''.$terminaltouse)) {", "takepos/admin/terminal.php:106|write|$res = dolibarr_set_const($db, \"CASHDESK_ID_BANKACCOUNT_SUMUP\".$terminaltouse, (GETPOST(''CASHDESK_ID_BANKACCOUNT_SUMUP''.$terminaltouse, ''alpha'') > 0 ? GETPOST(...", "takepos/admin/terminal.php:288: if (getDolGlobalInt(''TAKEPOS_ENABLE_SUMUP'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_PROJECT', 'string', NULL, 'takepos', 'ID of the project automatically linked to invoices created on a TakePOS terminal (per-terminal constant, suffixed with terminal number).', 'Written via takepos/admin/terminal.php:91 and read at terminal.php:373 into `$projectid`. Used in takepos/invoice.php:186-187 to set `$invoice->fk_project` when the project module is enabled.', 'Setting this to a valid project ID causes all invoices generated on that terminal to be linked to that project; leaving it empty means no project association is made.', 'Integer: ID of a Dolibarr project; empty = no project linked', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '3324d1a7fb867e000667f8bbea07fccf622da945c44836de625a1b756b2b7380', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"CASHDESK_ID_PROJECT\".$terminaltouse, (GETPOSTINT(''projectid'') > 0 ? GETPOSTINT(''projectid'') : ''''), ''chaine'', 0, '''', $conf->entity);", "if (isModEnabled(''project'') && getDolGlobalInt(\"CASHDESK_ID_PROJECT\".$takeposterminal)) {", "$invoice->fk_project = getDolGlobalInt(\"CASHDESK_ID_PROJECT\".$takeposterminal);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_THIRDPARTY', 'string', NULL, 'takepos', 'ID of the default thirdparty (customer) associated with a given TakePOS (point of sale) terminal.', 'Set via takepos/admin/terminal.php:88 (dolibarr_set_const, suffixed with the terminal id) and read at takepos/admin/terminal.php:217, takepos/receipt.php:251/256, takepos/index.php:99, and takepos/invoice.php:1107.', 'Determines the default/expected thirdparty used for POS invoices and receipts on the given terminal; receipt.php checks the object''s socid against this value.', NULL, 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '0e49a0a6f3ec2fb3c181df434a3b05706a8c69b9ccaf06bafa636bc727bd7741', 'v2', '2026-07-24T06:41:12+00:00', '["if ($object->socid != getDolGlobalInt(''CASHDESK_ID_THIRDPARTY''.$_SESSION[\"takeposterminal\"])) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_THIRDPARTY1', 'string', NULL, 'core', 'Stores the thirdparty (customer) ID used as the default generic customer for the TakePos point-of-sale module.', 'Checked in core/modules/modTakePos.class.php:276 inside the module''s init() (run when TakePos is enabled): `if (!getDolGlobalInt(''CASHDESK_ID_THIRDPARTY1'')) { // If a customer has already ben set into the TakePos setup page ... }` — if unset, the module auto-creates a default generic customer thirdparty and (per surrounding logic) stores its ID here.', 'If unset when TakePos is activated, Dolibarr auto-creates a generic ''default POS customer'' thirdparty; if already set, that creation step is skipped and the existing thirdparty ID is reused as TakePos''s default customer.', 'Integer thirdparty (societe) ID; 0/unset triggers auto-creation of a default customer on module init.', 0, 0, NULL, 1, 'a3eb22aa787abab8dd85efefa2566d130c571e081d37bdf72279c70f9897465e', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modTakePos.class.php:276|check|if (!getDolGlobalInt(''CASHDESK_ID_THIRDPARTY1'')) {\t// If a customer has already ben set into the TakePos setup page"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_ID_WAREHOUSE', 'string', NULL, 'takepos', 'ID of the warehouse used for stock movements on a TakePOS terminal (per-terminal constant, suffixed with terminal number).', 'Written via takepos/admin/terminal.php:118 and rendered as a warehouse selector at terminal.php:351. Checked extensively in takepos/ajax/ajax.php (lines 126, 284, 310, 328, 339) to control stock availability checks and stock decrement operations.', 'Setting this to a valid warehouse ID enables stock tracking and decrements for sales on that terminal; without it, stock management for the terminal is disabled or uses defaults.', 'Integer: ID of a Dolibarr warehouse; empty = no warehouse configured', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'f7e744554a621002fbec5e76c916ef451c2d9357f0d0ce4ce730a2c83eb4fc1f', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"CASHDESK_ID_WAREHOUSE\".$terminaltouse, (GETPOST(''CASHDESK_ID_WAREHOUSE''.$terminaltouse, ''alpha'') > 0 ? GETPOST(''CASHDESK_ID_WAREHOUSE''.$terminaltous", "if ($prod->stock_warehouse[getDolGlobalString(''CASHDESK_ID_WAREHOUSE''.$_SESSION[''takeposterminal''])]->real <= 0) {", "if (getDolGlobalInt(''CASHDESK_ID_WAREHOUSE''.$_SESSION[''takeposterminal''])) {", "if (!$disabled && !getDolGlobalString(''CASHDESK_ID_WAREHOUSE''.$terminal)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_NO_DECREASE_STOCK', 'string', NULL, 'takepos', 'Disables automatic stock decrease at the POS terminal level when enabled.', 'Configured per-terminal via takepos/admin/terminal.php (UI write at line 121, with the terminal suffix appended). The value is also read globally in core/modules/modProductBatch.class.php:139 and written there (line 141). A commented-out yes/no selector at line 328 indicates the feature is partially exposed in the UI.', 'When set for a terminal, stock is not decremented upon POS sales for that terminal. When the ProductBatch module is activated, this constant may be auto-set.', 'Truthy value (e.g. 1) to disable stock decrease; 0 or empty to allow stock decrease.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'd9df00b60317ff2c960d099d305b95526fc4ca9f7217c06c787b67ea02149c0b', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/terminal.php:121|write|$res = dolibarr_set_const($db, \"CASHDESK_NO_DECREASE_STOCK\".$terminaltouse, GETPOST(''CASHDESK_NO_DECREASE_STOCK''.$terminaltouse, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "core/modules/modProductBatch.class.php:139|check|if (!getDolGlobalString(''CASHDESK_NO_DECREASE_STOCK'')) {", "core/modules/modProductBatch.class.php:141|write|$res = dolibarr_set_const($db, \"CASHDESK_NO_DECREASE_STOCK\", 1, ''chaine'', 0, '''', $conf->entity);", "takepos/admin/terminal.php:333|read|$disabled = getDolGlobalInt(''CASHDESK_NO_DECREASE_STOCK''.$terminal);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_READER_KEYCODE_FOR_ENTER', 'string', NULL, 'takepos', 'Key code sent by the barcode reader to signal end-of-scan (Enter) on a TakePOS terminal (per-terminal constant, suffixed with terminal number).', 'Written via takepos/admin/terminal.php:143 and displayed as a text input at terminal.php:380. Read in takepos/index.php:177 into `$keyCodeForEnter` for use in the POS JavaScript barcode scanning logic.', 'Setting this to the correct key code for the barcode scanner''s end-of-scan signal ensures barcodes are correctly parsed; an incorrect value causes barcode scanning to malfunction.', 'Integer key code (e.g. 13 for Enter, or a scanner-specific code); 0 or absent = use default', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '0744688442502817d58debbbc478a0a408a0761ffe4e591b589ac7c31ffaa352', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, ''CASHDESK_READER_KEYCODE_FOR_ENTER''.$terminaltouse, (GETPOSTINT(''CASHDESK_READER_KEYCODE_FOR_ENTER''.$terminaltouse) > 0 ? GETPOSTINT(''CASHDESK_READER", "$keyCodeForEnter = getDolGlobalInt(''CASHDESK_READER_KEYCODE_FOR_ENTER''.$_SESSION[''takeposterminal'']) > 0 ? getDolGlobalString(''CASHDESK_READER_KEYCODE_FOR_ENTER''.$_SESSION[''takepos", "print ''<input type=\"text\" class=\"width50\" name=\"CASHDESK_READER_KEYCODE_FOR_ENTER''.$terminaltouse.''\" value=\"''.getDolGlobalString(''CASHDESK_READER_KEYCODE_FOR_ENTER''.$terminaltouse)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CASHDESK_SERVICES', 'string', NULL, 'takepos', 'TakePOS setting (currently rendered via ajax_constantonoff rather than the commented-out selectyesno) controlling whether services (as opposed to only products) can be sold from the cash desk / POS screen.', 'Configured in takepos/admin/setup.php:297 via ajax_constantonoff("CASHDESK_SERVICES", ...); an older commented-out line at :298 shows it was previously a $form->selectyesno yes/no field.', 'Toggling it on the TakePOS setup page changes whether service-type items are sellable/visible from the point-of-sale interface.', 'Boolean (yes/no), toggled via the ajax_constantonoff widget on the TakePOS setup page.', 0, 0, 'takepos/admin/setup.php', 1, 'ce456f92020e4f8112c3b7f41cfa0a069b95af6175b35364b74fff279796eee8', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/admin/setup.php:297: print ajax_constantonoff(\"CASHDESK_SERVICES\", array(), $conf->entity, 0, 0, 1, 0);", "takepos/admin/setup.php:298: //print $form->selectyesno(\"CASHDESK_SERVICES\", $conf->global->CASHDESK_SERVICES, 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORIE_RECURSIV_ADD', 'string', NULL, 'categories', 'When enabled, adding a category also recursively adds all its parent categories.', 'Configured via the categories admin UI (categories/admin/categorie.php:112). Checked in categories/class/categorie.class.php:866 to trigger recursive parent-category addition when an object is assigned to a category.', 'Enabling this constant causes parent categories to be automatically added whenever a category is assigned. Disabling it limits assignment to the directly selected category only.', 'Truthy value to enable recursive parent-category addition; unset or 0 to disable.', 0, 0, 'categories/admin/categorie.php', 1, 'ded722cbc6ac1545464db2cbaa94b55d5fb87b6e64e879af3b386bc6dd420b93', 'v2', '2026-04-21T11:16:15+00:00', '["categories/admin/categorie.php:112|check|if (!getDolGlobalString(''CATEGORIE_RECURSIV_ADD'')) {", "categories/class/categorie.class.php:866|check|if (getDolGlobalString(''CATEGORIE_RECURSIV_ADD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_ADD_DESC_INTO_DOC', 'string', NULL, 'core', 'Appends the description of a product''s categories to the product/service label shown in generated PDF documents.', 'Used once in core/lib/pdf.lib.php:2199, guarding a block that fetches all categories linked to a product via Categorie::containing() and concatenates each category''s description onto $libelleproduitservice for PDF output.', 'When enabled (and the category module is active and a product id is present), non-empty category descriptions are appended to the line label text printed on PDF documents, making lines longer.', 'Boolean-like: any truthy value enables the behavior (checked with getDolGlobalString, no admin UI comment found).', 1, 0, NULL, 1, '68fbb2caf4d9b52191598944e73960a63fadac38b78e88544b74e95a71e01a7d', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:2199: if (getDolGlobalString(''CATEGORY_ADD_DESC_INTO_DOC'') && $idprod && isModEnabled(''category'')) {", "core/lib/pdf.lib.php:2206: $desccateg = $cate->description;", "core/lib/pdf.lib.php:2208: $libelleproduitservice = dol_concatdesc($libelleproduitservice, $desccateg);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_ASSIGNED_TO_A_CUSTOMER', 'string', NULL, 'categories', 'When enabled, restricts category association operations to categories belonging to a specific customer (thirdparty).', 'Checked in categories/class/categorie.class.php:593, :609, and :699 to filter or adjust category logic based on thirdparty assignment. The constant''s role is documented in the class property comment at line 289: ''Id of thirdparty when CATEGORY_ASSIGNED_TO_A_CUSTOMER is set''. No admin UI write path is present in the payload.', 'Enabling this constant activates thirdparty-scoped category filtering in the categorie class. Leaving it unset applies the default category association logic.', 'Truthy value (thirdparty ID or flag) to enable customer-scoped category filtering; unset or 0 for default behaviour.', 1, 0, NULL, 1, 'd6e15db0d13b439f9b6473e74d8777d717ffa10b9364c2cc95cfc403845d9641', 'v2', '2026-04-21T11:16:15+00:00', '["categories/class/categorie.class.php:289  * @var int\t\t  Id of thirdparty when CATEGORY_ASSIGNED_TO_A_CUSTOMER is set", "categories/class/categorie.class.php:593|check|if (getDolGlobalString(''CATEGORY_ASSIGNED_TO_A_CUSTOMER'')) {", "categories/class/categorie.class.php:609|check|if (getDolGlobalString(''CATEGORY_ASSIGNED_TO_A_CUSTOMER'')) {", "categories/class/categorie.class.php:699|check|if (getDolGlobalString(''CATEGORY_ASSIGNED_TO_A_CUSTOMER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_EDIT_IN_MENU_NOT_IN_POPUP', 'string', NULL, 'core', 'Changes how category editing is triggered from the left menu, using an in-menu edit form instead of a popup.', 'Checked extensively (18 occurrences) throughout core/menus/standard/eldy.lib.php, e.g. lines 1272, 1350, 1357, 1382, 1454, 1506, 1590, 1626, gated with isModEnabled(''category'').', 'When enabled, category editing UI is rendered directly in the menu rather than opening a popup; requires the category module to be enabled for most of these checks.', NULL, 1, 0, NULL, 1, 'ef5e9a1c3b6c18bc3ad9f90c50a155a5a842e7015ab1ff8cc7962b43a442c0b3', 'v2', '2026-07-24T06:41:12+00:00', '["if (isModEnabled(''category'') && getDolGlobalString(''CATEGORY_EDIT_IN_MENU_NOT_IN_POPUP'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_GRAPHSTATS_ON_PRODUCTS', 'string', NULL, 'product', 'Shows a per-category product-count graph/table on the product module''s index (dashboard) page.', 'Checked in product/index.php:248 together with isModEnabled(''category'') and the ''categorie''/''read'' user right; when true, a table listing categories with their product counts (queried from categorie_product/categorie) is built and displayed.', 'Enabling it adds a category-distribution graph/table to the products dashboard, requiring the Category module to be enabled and the viewing user to have category read rights.', 'Boolean-like: any truthy value enables the category stats block on the product index page.', 1, 0, NULL, 1, 'c219c203198109b86446c5c26553fe5ff08190d776814f1967108e611f8b6eb3', 'v2', '2026-07-24T07:05:23+00:00', '["product/index.php:248: if (isModEnabled(''category'') && getDolGlobalString(''CATEGORY_GRAPHSTATS_ON_PRODUCTS'') && $user->hasRight(''categorie'', ''read'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_GRAPHSTATS_ON_THIRDPARTIES', 'string', NULL, 'societe', 'Specifies a category label (or numeric ID) for which a graph of thirdparties per category is displayed on the thirdparty dashboard.', 'Checked and read in societe/index.php:215, :226, :227. When set to a non-numeric value it is used as a label filter (LIKE match); when numeric it is used directly. The graph is only rendered when the category module is enabled and this constant is set.', 'Setting this to a category label or ID causes a thirdparty-count-by-category graph to appear on the societe dashboard. Leaving it unset suppresses the graph.', 'Category label string (for LIKE match) or numeric category ID.', 1, 0, NULL, 1, '4a5ee919cac5ab7b0e01281b15fec34bb821f466f7a674663ed0734b48fb03e4', 'v2', '2026-04-21T11:16:15+00:00', '["societe/index.php:215|check|if (isModEnabled(''category'') && getDolGlobalString(''CATEGORY_GRAPHSTATS_ON_THIRDPARTIES'')) {", "societe/index.php:226|check|if (!is_numeric(getDolGlobalString(''CATEGORY_GRAPHSTATS_ON_THIRDPARTIES''))) {", "societe/index.php:227|read|$sql .= \" AND c.label like ''\".$db->escape(getDolGlobalString(''CATEGORY_GRAPHSTATS_ON_THIRDPARTIES'')).\"''\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_MAX_VISIBLE_PHOTO', 'string', NULL, 'core', 'Sets the maximum number of category photos shown in the category photo block on the object card.', 'In core/lib/functions.lib.php:3437, used as `getDolGlobalInt(''CATEGORY_MAX_VISIBLE_PHOTO'', 5)` to cap photos passed to show_photos() for a category; default is 5, forced to 1 on phone layout.', 'Increasing/decreasing the value changes how many category photos are displayed at once in the card header photo block.', 'Integer count of photos to display; default 5 if unset.', 1, 0, NULL, 1, '3a34d7c2f2445a2695b7765bd46f02cbb4e44760b9a34d6130f35b021a17fc3b', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3437|read|$maxvisiblephotos = getDolGlobalInt(''CATEGORY_MAX_VISIBLE_PHOTO'', 5);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_NODISPLAYIFNOPHOTO', 'string', NULL, 'core', 'Suppresses the ''no photo'' placeholder image on the category card when the category has no photo.', 'In core/lib/functions.lib.php:3444, mirrors the product/BOM/ticket pattern: if no photo is available and this constant is set, an empty div is shown instead of the nophoto.png placeholder.', 'Enabling it hides the generic ''no photo'' placeholder for categories without photos, showing an empty block instead.', 'Boolean-like: any truthy value suppresses the no-photo placeholder.', 1, 0, NULL, 1, '80a17370cc04f0fd8d6d6d3c95675e0c47d095ec36030f440d424038bfca69ad', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3444|check|if (getDolGlobalString(''CATEGORY_NODISPLAYIFNOPHOTO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_SHOW_COUNTS', 'bool', NULL, 'categories', 'When enabled, displays item counts alongside category entries in category list and view pages.', 'Checked in categories/categorie_list.php:391, :417 and categories/viewcat.php:460, :486 to conditionally render count columns or values next to category names. No admin UI write path is present in the payload.', 'Enabling this constant adds item counts to category listings and category view pages. Leaving it unset hides the count information.', 'Truthy value to show counts; unset or 0 to hide.', 1, 0, NULL, 1, '1ed21441d43f59e0e04ba6aa0bfd34f6454bef72e0c841007b405bddda4d67ed', 'v2', '2026-04-21T11:16:15+00:00', '["categories/categorie_list.php:391|check|if (getDolGlobalString(''CATEGORY_SHOW_COUNTS'')) {", "categories/categorie_list.php:417|check|if (getDolGlobalString(''CATEGORY_SHOW_COUNTS'')) {", "categories/viewcat.php:460|check|if (getDolGlobalString(''CATEGORY_SHOW_COUNTS'')) {", "categories/viewcat.php:486|check|if (getDolGlobalString(''CATEGORY_SHOW_COUNTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CATEGORY_USE_OTHER_FIELD_IN_TRANSLATION', 'bool', NULL, 'categories', 'Shows an extra ''Other'' translation field on the category translation view.', 'In categories/traduction.php:340, when set, an additional table row for the ''other'' multilangs field is displayed, labeled ''Other (Not yet available)''.', 'Enabling it reveals a not-yet-fully-functional ''Other'' field row in the per-language translation display of a category; the label itself notes the feature is not yet available.', 'boolean: 1/true shows the extra ''Other'' translation row; unset/0 = row hidden.', 1, 0, NULL, 1, 'f3f3036c0c26c83f038f86b55a614f9e7999d5b631a25a96d2dc30dc9b00e977', 'v2', '2026-07-24T07:05:23+00:00', '["categories/traduction.php:340: if (getDolGlobalString(''CATEGORY_USE_OTHER_FIELD_IN_TRANSLATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CAT_HIGH_QUALITY_IMAGES', 'string', NULL, 'core', 'Forces PDF generators to use full-resolution product images instead of thumbnails.', 'Checked in 17 locations across expedition, reception, stocktransfer, commande, and facture PDF modules. Inline comment at core/modules/reception/doc/pdf_squille.modules.php:195 states: ''If CAT_HIGH_QUALITY_IMAGES not defined, we use thumb if defined and then original photo''.', 'When not set, PDF generators prefer thumbnails if available and fall back to original. When enabled, full-resolution images are used directly in PDFs, increasing file size.', 'If CAT_HIGH_QUALITY_IMAGES not defined, we use thumb if defined and then original photo; set to 1 to always use full-resolution images', 1, 0, NULL, 1, '000da9c16eeef257cfc907e54737387693d60895cc90687eb1422f4ffbf2c71b', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/reception/doc/pdf_squille.modules.php:195  // If CAT_HIGH_QUALITY_IMAGES not defined, we use thumb if defined and then original photo", "core/modules/expedition/doc/pdf_rouget.modules.php:233  // If CAT_HIGH_QUALITY_IMAGES not defined, we use thumb if defined and then original photo", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:241  // If CAT_HIGH_QUALITY_IMAGES not defined, we use thumb if defined and then original photo", "modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:241|check|if (!getDolGlobalInt(''CAT_HIGH_QUALITY_IMAGES'')) {\t\t// If CAT_HIGH_QUALITY_IMAGES not defined, we use thumb"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CDAV_CONTACT_TAG', 'string', NULL, 'dav', 'Value used to define the PHP constant CDAV_CONTACT_TAG, used by the DAV/CardDAV server code for contact-related tagging.', 'Defined once in dav/dav.lib.php:25-30 with the comment ''define CDAV_CONTACT_TAG if not'': `if (!defined(''CDAV_CONTACT_TAG'')) { if (getDolGlobalString(''CDAV_CONTACT_TAG'')) { define(''CDAV_CONTACT_TAG'', getDolGlobalString(''CDAV_CONTACT_TAG'')); } else { define(''CDAV_CONTACT_TAG'', ''''); } }`. CONF_PHP_WIRING-style bootstrap: the global config value seeds a hard PHP constant used elsewhere in the DAV code, but exact downstream usage of CDAV_CONTACT_TAG was not found in this payload.', 'Setting this global changes the value of the PHP constant CDAV_CONTACT_TAG used by the DAV module; leaving it unset makes the constant default to an empty string. Exact behavior unclear from code alone [SPECULATION].', 'Any string; if unset/empty, CDAV_CONTACT_TAG constant defaults to '''' (empty string).', 1, 0, NULL, 1, 'ca4809f45b676c4a89a220fb7fc4f449bd3a6f35d48d5e6201d5c5d9f690ecae', 'v2', '2026-07-24T07:05:23+00:00', '["dav/dav.lib.php:25: // define CDAV_CONTACT_TAG if not", "dav/dav.lib.php:27: if (getDolGlobalString(''CDAV_CONTACT_TAG'')) {", "dav/dav.lib.php:28: define(''CDAV_CONTACT_TAG'', getDolGlobalString(''CDAV_CONTACT_TAG''));"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CDAV_URI_KEY', 'string', NULL, 'dav', 'Value used to define the PHP constant CDAV_URI_KEY, used by the DAV/CalDAV/CardDAV server as a URI key/salt; defaults to a hash of the HTTP host.', 'Defined once in dav/dav.lib.php:34-40 with comment ''define CDAV_URI_KEY if not'': `if (!defined(''CDAV_URI_KEY'')) { if (getDolGlobalString(''CDAV_URI_KEY'')) { define(''CDAV_URI_KEY'', getDolGlobalString(''CDAV_URI_KEY'')); } else { define(''CDAV_URI_KEY'', substr(md5($_SERVER[''HTTP_HOST'']), 0, 8)); } }`. Downstream usage of the CDAV_URI_KEY constant elsewhere in the DAV module was not present in this payload.', 'Setting this global fixes the DAV URI key to a chosen value instead of the default host-derived hash (first 8 chars of md5 of HTTP_HOST); this could matter for consistency of DAV resource URIs across different hostnames/reverse proxies. Exact downstream effect unclear from code alone [SPECULATION].', 'Any string; if unset/empty, defaults to `substr(md5($_SERVER[''HTTP_HOST'']), 0, 8)`.', 1, 0, NULL, 1, '79c6bbfd3dc1d4a62fcaa058a8622380f386127aa29e5765f9333da5eb035830', 'v2', '2026-07-24T07:05:23+00:00', '["dav/dav.lib.php:34: // define CDAV_URI_KEY if not", "dav/dav.lib.php:37: define(''CDAV_URI_KEY'', getDolGlobalString(''CDAV_URI_KEY''));", "dav/dav.lib.php:38: define(''CDAV_URI_KEY'', substr(md5($_SERVER[''HTTP_HOST'']), 0, 8));"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CERTIFICATE_CRT', 'string', NULL, 'core', 'Stores the digital certificate (PEM string or path) used to cryptographically sign generated PDF documents.', 'Read across 6 occurrences in PDF generation modules; some fallback to a per-user value via getDolUserString (e.g. core/modules/facture/doc/pdf_octopus.modules.php:459 and pdf_sponge.modules.php:389). No admin UI write is present.', 'Setting this value enables digital signatures on PDFs; a per-user override takes precedence where getDolUserString is used.', 'String (PEM certificate content or file path); empty = no PDF signing.', 1, 0, NULL, 1, 'b555d367a83a32e36ede9eeff7f5e9329f9db7147c6bb94fa8d7ca5983f3eb25', 'v2', '2026-04-21T11:16:15+00:00', '["modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:349|read|$cert = getDolGlobalString(''CERTIFICATE_CRT'');", "core/modules/facture/doc/pdf_octopus.modules.php:459|read|$cert = getDolUserString(''CERTIFICATE_CRT'', getDolGlobalString(''CERTIFICATE_CRT''));", "recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:299|read|$cert = !getDolGlobalString(''CERTIFICATE_CRT'') ? '''' : $conf->global->CERTIFICATE_CRT;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CERTIFICATE_CRT_PRIVATE', 'string', NULL, 'core', 'Stores the global private certificate used for electronic signing of invoice and asset PDFs.', 'Read in core/modules/facture/doc/pdf_octopus.modules.php at line 460, pdf_sponge.modules.php at line 390, and pdf_standard_asset.modules.php at line 264; in each case it is used as the default fallback when the per-user certificate (getDolUserString) is not set.', 'Setting this constant provides a global private certificate for PDF signing. A per-user certificate (CERTIFICATE_CRT_PRIVATE on the user record) takes precedence over this global value.', 'A PEM-encoded private certificate string; empty/unset = no global certificate (per-user certificate still applies if set).', 1, 0, NULL, 1, 'b55fc12d4df40c1d3e781eeb10524d380593669462795b135b86c9eff8ec17d2', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/facture/doc/pdf_octopus.modules.php:460|read|$certprivate = getDolUserString(''CERTIFICATE_CRT_PRIVATE'', getDolGlobalString(''CERTIFICATE_CRT_PRIVATE''));", "core/modules/facture/doc/pdf_sponge.modules.php:390|read|$certprivate = getDolUserString(''CERTIFICATE_CRT_PRIVATE'', getDolGlobalString(''CERTIFICATE_CRT_PRIVATE''));", "core/modules/asset/doc/pdf_standard_asset.modules.php:264|read|$certprivate = getDolUserString(''CERTIFICATE_CRT_PRIVATE'', getDolGlobalString(''CERTIFICATE_CRT_PRIVATE''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CHARTOFACCOUNTS', 'string', NULL, 'accountancy', 'ID of the chart of accounts (accounting system) row selected for the accountancy module.', 'Set via accountancy/admin/account.php:213 (dolibarr_set_const) and read across many files (46 occurrences), including asset/admin/setup.php:555, accountancy/admin/card.php:89/146/213, and accountancy/admin/productaccount.php:328, typically to fetch the accounting_system record or its pcg_version.', 'Changing this value switches which chart-of-accounts system (accounting_system row) is used throughout accountancy, PDF/asset, and product account computations.', NULL, 0, 0, 'asset/admin/setup.php|accountancy/admin/card.php|accountancy/admin/card.php|accountancy/admin/card.php|accountancy/admin/productaccount.php|accountancy/admin/account.php|accountancy/admin/account.php|accountancy/admin/account.php', 1, '50da383b6989eed60c74c2372ae5cde59703a8d6c989fb3e5ac066062679d7f3', 'v2', '2026-07-24T06:41:12+00:00', '["$sql = \"SELECT pcg_version FROM \" . MAIN_DB_PREFIX . \"accounting_system WHERE rowid = \".((int) getDolGlobalInt(''CHARTOFACCOUNTS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CHECKLASTVERSION_EXTERNALMODULE', 'string', NULL, 'admin', 'Triggers an automatic version check against an external source for all external modules when the admin module list is built.', 'The code comment warns: ''Setting CHECKLASTVERSION_EXTERNALMODULE to on is a bad practice to activate a check on an external access during the building of the admin page.'' (admin/modules.php:1026). The check fires for every external module when the constant is set (admin/modules.php:1025).', 'Enabling this constant causes an external network request per module during admin page rendering, which can significantly slow down the modules list. It is explicitly noted in the code as bad practice.', '0 or unset = no automatic version check; non-zero = version check triggered on page load for all external modules', 0, 0, 'admin/modules.php|admin/modules.php|admin/modules.php', 1, 'cb6509c6d3c4a8b4c4a7e3f5bac41f3863201a780b73c78d3a6e78d817113c13', 'v2', '2026-04-21T13:29:58+00:00', '["admin/modules.php:1026  // Setting CHECKLASTVERSION_EXTERNALMODULE to on is a bad practice to activate a check on an external access during the building of the admin page.", "admin/modules.php:1025|check|if ($objMod->isCoreOrExternalModule() == ''external'' && ($action == ''checklastversion'' || getDolGlobalString(''CHECKLASTVERSION_EXTERNALMODULE''))) {", "admin/modules.php:416|read|$checkOldValue = getDolGlobalInt(''CHECKLASTVERSION_EXTERNALMODULE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CHEQUERECEIPTS_ADDON', 'string', NULL, 'compta', 'Specifies the active numbering module (addon) used to generate cheque receipt reference numbers.', 'Configured via admin/chequereceipts.php which reads, writes, and validates the value. If not set, the code defaults to ''mod_chequereceipts_mint.php'' (admin/chequereceipts.php:58). The class name is loaded at runtime from this constant (compta/paiement/cheque/class/remisecheque.class.php:449).', 'Changing this constant switches the numbering module for cheque receipts; an invalid or missing module name will cause reference generation to fail.', 'String filename of the numbering module (e.g. ''mod_chequereceipts_mint''); defaults to ''mod_chequereceipts_mint.php''', 0, 0, 'admin/chequereceipts.php|admin/chequereceipts.php|admin/chequereceipts.php|admin/chequereceipts.php|admin/chequereceipts.php', 1, '201d8fb5fbcd5ab2ec048f709ffa9f27513e427f684cdb2c24cfce2e68f1b1fb', 'v2', '2026-04-21T13:29:58+00:00', '["if (!getDolGlobalString(''CHEQUERECEIPTS_ADDON'')) {", "$conf->global->CHEQUERECEIPTS_ADDON = ''mod_chequereceipts_mint.php'';", "dolibarr_set_const($db, \"CHEQUERECEIPTS_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "$classname = getDolGlobalString(''CHEQUERECEIPTS_ADDON'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CHEQUERECEIPTS_THYME_MASK', 'string', NULL, 'core', 'Numbering mask used by the ''Thyme'' numbering module for cheque deposit receipt (RemiseCheque) references.', 'Read/written by mod_chequereceipt_thyme (core/modules/cheque/mod_chequereceipt_thyme.php:84,136): shown in an admin setup form input and consumed by getNextValue() to compute the next receipt ref; returns ''NotConfigured'' if the mask is empty.', 'Changing the mask changes the format of future cheque-receipt references generated by this numbering module; existing refs are unaffected.', 'Free-form mask string using Dolibarr''s generic mask code syntax (GenericMaskCodes tooltip), same convention as other numbering-module masks.', 0, 0, NULL, 1, 'eb1609fd1998267097269335eea314410824f19fe37612070db9464f085d9b75', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/cheque/mod_chequereceipt_thyme.php:136|read|$mask = getDolGlobalString(''CHEQUERECEIPTS_THYME_MASK'');", "core/modules/cheque/mod_chequereceipt_thyme.php:84|read|...name=\"maskchequereceipts\" value=\"'' . getDolGlobalString(''CHEQUERECEIPTS_THYME_MASK'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CHEQUERECEIPT_ADDON_PDF', 'string', NULL, 'core', 'Specifies the PDF template module to use for generating cheque receipt documents.', 'When set, its value is read at core/modules/cheque/modules_chequereceipts.php:152 to select the PDF generation module. If unset, the default module selection logic applies.', 'Changing this switches the PDF layout used for cheque receipts; removing it reverts to the default module.', 'String name of the PDF module class for cheque receipts.', 1, 0, NULL, 1, '098b4b9b989f5521f059b7626dfcc9c8429134abe045b4df84e9f4772df31068', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/cheque/modules_chequereceipts.php:151|check|if (getDolGlobalString(''CHEQUERECEIPT_ADDON_PDF'')) {", "core/modules/cheque/modules_chequereceipts.php:152|read|$modele = getDolGlobalString(''CHEQUERECEIPT_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CKEDITOR_NATIVE_SPELLCHECKER', 'string', NULL, 'core', 'Toggles use of the browser''s native spellchecker versus CKEditor''s own spellchecker, for both the CKEditor and TinyMCE integrations.', 'Read twice in core/class/doleditor.class.php: at line 332 for CKEditor (disableNativeSpellChecker is the inverse of this constant) and at line 406 for TinyMCE (browser_spellcheck is set directly to this constant''s truthiness).', 'Enabling it makes both supported WYSIWYG editors rely on the browser''s built-in spellchecker instead of the editor''s internal one (CKEditor: disableNativeSpellChecker=false; TinyMCE: browser_spellcheck=true).', 'Boolean-like: truthy = use native browser spellchecker (CKEditor disableNativeSpellChecker:false, TinyMCE browser_spellcheck:true); falsy/unset = use the editor''s own spellchecker.', 1, 0, NULL, 1, 'eb6e9015bafbe7daa25fe8dfd6368ff02203da5061882fa267896c5751cb464e', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/doleditor.class.php:332|read|disableNativeSpellChecker: ''.(getDolGlobalString(''CKEDITOR_NATIVE_SPELLCHECKER'') ? ''false'' : ''true'');", "core/class/doleditor.class.php:406|read|$out .= ''\t\tbrowser_spellcheck: ''.(getDolGlobalString(''CKEDITOR_NATIVE_SPELLCHECKER'') ? ''true'' : ''false'').'',''.\"\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CLICKTODIAL_DO_NOT_USE_AJAX_CALL', 'bool', NULL, 'core', 'Switches ClickToDial phone links from the default ajax-based call method to a legacy plain-link method.', 'In core/lib/functions.lib.php:5081, when rendering a clickable phone number, the default (recommended) behavior uses an ajax call handled by lib_foot.js.php; if this constant is set, the old method is used instead, generating a plain `<a href>` link without the ajax history-back trick.', 'Enabling it disables the ajax-based ClickToDial flow and falls back to the older direct-link method, which may also honor CLICKTODIAL_FORCENEWTARGET for opening in a new tab.', 'Boolean-like: any truthy value forces the old non-ajax method; default (empty) uses the recommended ajax method.', 1, 0, NULL, 1, 'cef7601565ad238eae0879777a42bf46f701a5be0e9083cc59163957f56bb683', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5081|check|if (!getDolGlobalString(''CLICKTODIAL_DO_NOT_USE_AJAX_CALL'')) {", "// Default and recommended: New method using ajax without submitting a page ... // Old method"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CLICKTODIAL_FORCENEWTARGET', 'string', NULL, 'core', 'Forces ClickToDial phone links (in the legacy non-ajax mode) to open in a new browser tab.', 'In core/lib/functions.lib.php:5088, only used inside the ''old method'' branch (when CLICKTODIAL_DO_NOT_USE_AJAX_CALL is set): if this constant is set, `target="_blank" rel="noopener noreferrer"` is added to the ClickToDial link.', 'Enabling it (together with CLICKTODIAL_DO_NOT_USE_AJAX_CALL) makes clicking a phone number open a new tab instead of navigating/using ajax in the current page.', 'Boolean-like: any truthy value adds target=_blank to the legacy ClickToDial link.', 1, 0, NULL, 1, 'cb4b3ac1b8bd23ec8975bad3a11ec48ca49d282e4678a37e7d5b40ef9a214ebe', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5088|check|if (getDolGlobalString(''CLICKTODIAL_FORCENEWTARGET'')) {", "$newphoneastart .= '' target=\"_blank\" rel=\"noopener noreferrer\"'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CLICKTODIAL_KEY_FOR_CIDLOOKUP', 'string', NULL, 'admin', 'Security key required to authenticate external CID (Caller ID) lookup requests to the Dolibarr public click-to-dial endpoint.', 'Written via admin/clicktodial.php:62 and displayed as a text input at clicktodial.php:154. The public endpoint public/clicktodial/cidlookup.php:80 rejects requests where the submitted securitykey does not match this constant. The admin page also shows the full lookup URL incorporating this key.', 'If this key is absent or does not match the incoming request, the CID lookup endpoint returns an authentication error, preventing external phone systems from resolving caller IDs.', 'Any string (acts as a shared secret/token for the CID lookup URL)', 0, 0, 'admin/clicktodial.php|admin/clicktodial.php|admin/clicktodial.php', 1, '4ed725a69349a2ace33ca0ebafecd582b62da5ea54e33b798b22244610b14a64', 'v2', '2026-04-21T13:50:40+00:00', '["$url = $urlwithroot.''/public/clicktodial/cidlookup.php?securitykey=''.getDolGlobalString(''CLICKTODIAL_KEY_FOR_CIDLOOKUP'', ''ValueToDefine'').''&phone=...'';", "$result3 = dolibarr_set_const($db, \"CLICKTODIAL_KEY_FOR_CIDLOOKUP\", GETPOST(\"CLICKTODIAL_KEY_FOR_CIDLOOKUP\"), ''chaine'', 0, '''', $conf->entity);", "if ($securitykey != getDolGlobalString(''CLICKTODIAL_KEY_FOR_CIDLOOKUP'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CLICKTODIAL_URL', 'string', NULL, 'admin', 'Defines the Click-to-Dial URL template used to initiate calls, supporting placeholders for login, password, extension, and phone number.', 'Set via dolibarr_set_const in admin/clicktodial.php:61, read in core/lib/functions.lib.php:5069 with error fallback ''ErrorClickToDialModuleNotConfigured''. Validated in admin/clicktodial.php:169-191 for placeholder consistency. Has a full admin UI at admin/clicktodial.php.', 'Changing this URL alters the endpoint called when a user clicks a phone number. Incorrect or missing placeholders (__LOGIN__, __PASSWORD__, __PHONEFROM__) trigger warnings in the admin UI.', 'URL string with optional placeholders: __LOGIN__, __PASSWORD__, __PHONEFROM__, and phone number placeholder. Default fallback: ''ErrorClickToDialModuleNotConfigured''.', 0, 0, 'admin/clicktodial.php|admin/clicktodial.php|admin/clicktodial.php|admin/clicktodial.php|admin/clicktodial.php|admin/clicktodial.php', 1, 'fd156ca656bf37b4953e9015d0fc391885d413a054308c4ed5d959a4548e8bf5', 'v2', '2026-04-21T13:29:58+00:00', '["admin/clicktodial.php:61|write|$result2 = dolibarr_set_const($db, \"CLICKTODIAL_URL\", GETPOST(\"CLICKTODIAL_URL\"), ''chaine'', 0, '''', $conf->entity);", "core/lib/functions.lib.php:5069|read|$urlmask = getDolGlobalString(''CLICKTODIAL_URL'', ''ErrorClickToDialModuleNotConfigured'');", "admin/clicktodial.php:185|check|if (preg_match(''/__LOGIN__/'', getDolGlobalString(''CLICKTODIAL_URL'')) && empty($user->clicktodial_login)) {", "user/clicktodial.php:151|check|if (!getDolGlobalString(''CLICKTODIAL_URL'') && empty($object->clicktodial_url)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CLICKTODIAL_USE_TEL_LINK_ON_PHONE_NUMBERS', 'bool', NULL, 'admin', 'Switches phone number display to use native ''tel:'' links instead of the Click-to-Dial URL mechanism.', 'Set via dolibarr_set_const in admin/clicktodial.php:60 and read in admin/clicktodial.php:104 as a yes/no select. Also checked in core/lib/functions.lib.php:5060 as an OR condition alongside browser phone layout detection.', 'Enabling this renders phone numbers as standard tel: HTML links, which triggers the OS dialer on mobile devices. Disabling it uses the Click-to-Dial URL template instead.', '1 = use tel: links; 0 or absent = use Click-to-Dial URL.', 0, 0, 'admin/clicktodial.php|admin/clicktodial.php|admin/clicktodial.php', 1, '5640ce619b1efa9e449943636d4758ce30ad758d75071e4ce308c230cd4788ac', 'v2', '2026-04-21T13:29:58+00:00', '["admin/clicktodial.php:60|write|$result1 = dolibarr_set_const($db, \"CLICKTODIAL_USE_TEL_LINK_ON_PHONE_NUMBERS\", GETPOST(\"CLICKTODIAL_USE_TEL_LINK_ON_PHONE_NUMBERS\"), ''chaine'', 0, '''', $conf->entity);", "admin/clicktodial.php:104|read|print $form->selectyesno(\"CLICKTODIAL_USE_TEL_LINK_ON_PHONE_NUMBERS\", getDolGlobalString(''CLICKTODIAL_USE_TEL_LINK_ON_PHONE_NUMBERS''), 1).''<br>'';", "core/lib/functions.lib.php:5060|check|if ($addlink == ''tel'' || $conf->browser->layout == ''phone'' || (isModEnabled(''clicktodial'') && getDolGlobalString(''CLICKTODIAL_USE_TEL_LINK_ON_PHONE_NUMBERS''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_ADDON', 'string', NULL, 'commande', 'Specifies the numbering module class used to generate customer order reference numbers.', 'Documented in commande/class/commande.class.php:455 as: defined into COMMANDE_ADDON. Written via admin/order.php:156; read in commande/class/commande.class.php:469 to instantiate the class. Default is ''mod_commande_marbre'' as referenced in core/modules/modCommande.class.php:363.', 'Changing this switches the order reference numbering logic to a different module class; removing it causes the system to use the default ''mod_commande_marbre'' module.', 'String class name of the order numbering module; default ''mod_commande_marbre''.', 0, 0, 'admin/order.php|admin/order.php', 1, '887858f36cb9c77779bde008e4507f24d2216508f97408c7cbe20f1491134e88', 'v2', '2026-04-21T13:50:40+00:00', '["commande/class/commande.class.php:455  *  defined into COMMANDE_ADDON", "admin/order.php:156|write|dolibarr_set_const($db, \"COMMANDE_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "core/modules/modCommande.class.php:363|read|''class'' => getDolGlobalString(''COMMANDE_ADDON'', ''mod_commande_marbre''),", "commande/class/commande.class.php:469|read|$classname = getDolGlobalString(''COMMANDE_ADDON'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_ADDON_PDF', 'string', NULL, 'admin', 'Specifies the name of the PDF generation module to use by default for sales order documents.', 'Written in admin/order.php:141 and read in commande/class/commande.class.php:4228-4229 to select the PDF module, and in commande/card.php:2506 as the pre-selected template. Configurable via admin/order.php.', 'Changing this value switches the default PDF template used for sales order generation. Removing it falls back to the system default.', 'String name of the PDF module (e.g. ''einstein''); empty = use system default', 0, 0, 'admin/order.php|admin/order.php|admin/order.php|admin/order.php|admin/order.php', 1, '0049685d0a129e7e838c57133b98be5c3d969fef3273c92beb5094de2203c4e5', 'v2', '2026-04-21T13:50:40+00:00', '["admin/order.php:141|write|if (dolibarr_set_const($db, \"COMMANDE_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "commande/class/commande.class.php:4228|read|} elseif (getDolGlobalString(''COMMANDE_ADDON_PDF'')) {", "commande/class/commande.class.php:4229|read|$modele = getDolGlobalString(''COMMANDE_ADDON_PDF'');", "commande/card.php:2506|read|$preselected = getDolGlobalString(''COMMANDE_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Stores the filesystem path to the directory containing ODT template files for order document generation.', 'Used in core/modules/commande/doc/doc_generic_order_odt.modules.php:120 where it is read and trimmed to resolve the ODT template path. The COMMENTS in the payload cite core/class/commondocgenerator.class.php:82 which documents this as the constant to use to scan ODT files.', 'Setting this to a valid directory path allows the ODT-based order document generator to locate custom templates. An empty or invalid path causes the generator to fall back to its default template location.', 'Any non-empty string = filesystem path to the ODT templates directory; empty/unset = default path used.', 1, 0, NULL, 1, 'eed754b9c8746f513f2610294f2a6e71652185d91cbdd4e7149ad57b1db64114', 'v2', '2026-04-21T13:50:40+00:00', '["doc_generic_order_odt.modules.php:120|$odtPath = trim(getDolGlobalString(''COMMANDE_ADDON_PDF_ODT_PATH''));", "commondocgenerator.class.php:82|* @var string\tThe name of constant to use to scan ODT files (Example: ''COMMANDE_ADDON_PDF_ODT_PATH'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_DISABLE_ADD_CONTRACT', 'bool', NULL, 'commande', 'Hides the ''Add contract'' action button on the sales order card.', 'Checked in commande/card.php:3557: if (!getDolGlobalInt(''COMMANDE_DISABLE_ADD_CONTRACT'')) { ... adds the AddContract button to $arrayforbutaction }.', 'When enabled, the button/action to create a linked contract from the sales order is removed from the action list; when disabled (default), it is shown (subject to the contract module and order status).', 'Boolean: 1/true disables (hides) the Add contract button.', 0, 0, NULL, 1, 'dae512afc6323a87aab523d5e843deb7ab70fb63c727df87908059fa50d220c1', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3557: if (!getDolGlobalInt(''COMMANDE_DISABLE_ADD_CONTRACT'')) { $arrayforbutaction[] = [... ''label'' => ''AddContract'' ...]; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_DISABLE_ADD_INTERVENTION', 'bool', NULL, 'commande', 'Hides the ''Add intervention'' action button on the sales order card.', 'Checked in commande/card.php:3546: if (!getDolGlobalInt(''COMMANDE_DISABLE_ADD_INTERVENTION'')) { ... adds the AddIntervention button to $arrayforbutaction }.', 'When enabled, the button/action to create a linked intervention (fichinter) from the sales order is removed from the action list; when disabled (default), it is shown (subject to the intervention module and order status/lines).', 'Boolean: 1/true disables (hides) the Add intervention button.', 0, 0, NULL, 1, '96cfa26054f75cf0bd8aece7f246ad60ab20fd29d5fc185cab02094d014e0467', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3546: if (!getDolGlobalInt(''COMMANDE_DISABLE_ADD_INTERVENTION'')) { $arrayforbutaction[] = array(... ''label'' => ''AddIntervention'' ...); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_DISABLE_ADD_PURCHASE_ORDER', 'bool', NULL, 'commande', 'Hides the ''Add purchase order'' action button on the sales order card.', 'Checked in commande/card.php:3529: if (!getDolGlobalInt(''COMMANDE_DISABLE_ADD_PURCHASE_ORDER'')) { ... adds the AddPurchaseOrder button to $arrayforbutaction }.', 'When enabled, the button/action to create a linked supplier (purchase) order from the sales order is removed from the action list; when disabled (default), it is shown (subject to the supplier_order module and order status).', 'Boolean: 1/true disables (hides) the Add purchase order button.', 0, 0, NULL, 1, '9693f070799d542a6ec3824948ba9e7c2f61599644eb3dc29965f1609e26cf08', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3529: if (!getDolGlobalInt(''COMMANDE_DISABLE_ADD_PURCHASE_ORDER'')) { $arrayforbutaction[] = array(... ''label'' => ''AddPurchaseOrder'' ...); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_DRAFT_WATERMARK', 'string', NULL, 'core', 'Stores the watermark text to overlay on draft sales order PDFs.', 'Configurable via the admin UI at admin/order.php. When a sales order is in draft status and this constant is set, its value is used as the watermark in pdf_einstein.modules.php and pdf_eratosthene.modules.php, and also referenced (currently commented out) in delivery and supplier order PDF modules. The COMMENTS in the payload show commented-out usage in pdf_vinci, pdf_muscadet, pdf_zenith, and pdf_cornas.', 'Setting a non-empty value causes draft order PDFs to display the specified watermark text. Clearing the value removes the watermark from draft PDFs.', 'Any non-empty string = watermark text displayed on draft order PDFs; empty/unset = no watermark.', 0, 0, 'admin/order.php|admin/order.php', 1, 'c7f8a4fdc51c469e87b47e86ea37b8efcdebec222a147662f879aa6d3a0bfa05', 'v2', '2026-04-21T13:50:40+00:00', '["admin/order.php:159|$res = dolibarr_set_const($db, \"COMMANDE_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "pdf_einstein.modules.php:201|if ($object->statut == $object::STATUS_DRAFT && getDolGlobalString(''COMMANDE_DRAFT_WATERMARK'')) {", "pdf_storm.modules.php:707|if ($object->statut == 0 && getDolGlobalString(''COMMANDE_DRAFT_WATERMARK'')) {", "/*if($object->statut==0 && getDolGlobalString(''COMMANDE_DRAFT_WATERMARK''))"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_EMAIL_SENDER', 'string', NULL, 'core', 'Sets the ''From'' email address used when pre-filling the send-by-email form for customer orders (commande).', 'Used in core/tpl/card_presend.tpl.php:206-207: when $object->element === ''commande'' and this constant is truthy, $formmail->frommail is set to its value and fromtype forced to ''special''.', 'Setting it overrides the default sender email address specifically for outgoing customer order emails.', 'Free-text email address string; when non-empty, activates the order-specific sender override branch.', 0, 0, NULL, 1, 'dcdef3852512026dc147bf400b30b183bc3e6c06473610208ac2b8ded70f9c16', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:206|check|if ($object->element === ''commande'' && getDolGlobalString(''COMMANDE_EMAIL_SENDER'')) {", "core/tpl/card_presend.tpl.php:207|read|$formmail->frommail = getDolGlobalString(''COMMANDE_EMAIL_SENDER'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_EMAIL_SENDER_NAME', 'string', NULL, 'core', 'Sets the ''From'' display name used when pre-filling the send-by-email form for customer orders (commande).', 'Used in core/tpl/card_presend.tpl.php:208 to set $formmail->fromname within the commande sender branch guarded by COMMANDE_EMAIL_SENDER (line 206), defaulting to empty string.', 'Setting it customizes the sender display name on customer order emails; only applies when COMMANDE_EMAIL_SENDER is also set.', 'Free-text sender display name string; defaults to '''' if unset.', 0, 0, NULL, 1, '8581e188c11e988ecad5610f24605928c125337ea763bf4d8f78445627d5ebd4', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:208|read|$formmail->fromname = getDolGlobalString(''COMMANDE_EMAIL_SENDER_NAME'', '''');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_FOURNISSEUR_ORCHIDEE_MASK', 'bool', NULL, 'core', 'Numbering mask used by the ''Orchidee'' numbering module for supplier order references.', 'Read/written by mod_commande_fournisseur_orchidee (core/modules/supplier_order/mod_commande_fournisseur_orchidee.php:97,148): shown in an admin setup form input and consumed by getNextValue() to compute the next supplier order ref. Note: payload lists TYPE as bool, but code usage (getDolGlobalString + mask text pattern) shows it is actually a string mask like the other *_MASK constants.', 'Changing the mask changes the format of future supplier order references generated by this numbering module; existing refs are unaffected.', 'Free-form mask string using Dolibarr''s generic mask code syntax (GenericMaskCodes tooltip), same convention as other numbering-module masks.', 0, 0, NULL, 1, 'c36d456f0390d102efced8dfba1f75c2fc98a78533a34003e71b0252caf6cbe0', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_order/mod_commande_fournisseur_orchidee.php:148|read|$mask = getDolGlobalString(\"COMMANDE_FOURNISSEUR_ORCHIDEE_MASK\");", "core/modules/supplier_order/mod_commande_fournisseur_orchidee.php:97|read|...name=\"maskorder\" value=\"''.getDolGlobalString(\"COMMANDE_FOURNISSEUR_ORCHIDEE_MASK\")"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_SAPHIR_MASK', 'string', NULL, 'core', 'Stores the numbering mask pattern used by the saphir sales order reference numbering module.', 'Used in core/modules/commande/mod_commande_saphir.php in two locations: line 95 populates a UI input field for configuring the mask, and line 147 retrieves the mask to generate order references.', 'Changing the mask pattern alters how new sales order references are formatted by the saphir module. Clearing it results in no mask being applied.', 'Any string = mask pattern for order reference generation; empty/unset = no mask pattern.', 1, 0, NULL, 1, 'a7b34c54daee4e212d9ef78b6bb14c0e81a9c5cd7432ea62dc80cff56f0bc8f2', 'v2', '2026-04-21T13:50:40+00:00', '["mod_commande_saphir.php:95|value=''\".getDolGlobalString(\"COMMANDE_SAPHIR_MASK\").\"''", "mod_commande_saphir.php:147|$mask = getDolGlobalString(\"COMMANDE_SAPHIR_MASK\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_SENDBYEMAIL_FOR_ALL_STATUS', 'string', NULL, 'commande', 'Allows sending a customer order by email regardless of its status, not just non-draft ones.', 'Checked in commande/card.php:3479 to allow the send-by-email action for draft orders too, and in core/actions_massactions.inc.php:348 to allow the mass-action email send for draft orders.', 'When enabled, draft customer orders can also be sent by email (individually or via mass actions); otherwise sending by email is restricted to non-draft orders.', NULL, 1, 0, NULL, 1, 'a8eb0726e947f69ffd1f433a42d4e33c978ac1618efc26300f92993cbc1ee117', 'v2', '2026-07-24T06:41:12+00:00', '["if ($object->status > Commande::STATUS_DRAFT || getDolGlobalString(''COMMANDE_SENDBYEMAIL_FOR_ALL_STATUS'')) {", "if ($objectclass == ''Commande'' && $objectobj->status == Commande::STATUS_DRAFT && !getDolGlobalString(''COMMANDE_SENDBYEMAIL_FOR_ALL_STATUS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_SUPPLIER_ADDON_NUMBER', 'string', NULL, 'core', 'Name of the numbering module class used to generate supplier order reference numbers.', 'Set via supplier_order/admin/supplier_order.php:171 (dolibarr_set_const) and used in fourn/class/fournisseur.commande.class.php:1169/1172/1173 to build the file/class name, defaulting to ''mod_commande_fournisseur_muguet'' in core/modules/modSupplierOrder.class.php:467/468 when unset.', 'Changing it switches which numbering module class is used to generate new supplier order references; if unset, the default ''mod_commande_fournisseur_muguet'' module is used.', 'class name of a numbering module (e.g. mod_commande_fournisseur_muguet), default when unset: mod_commande_fournisseur_muguet', 0, 0, 'supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php', 1, 'd401decf5e8b3fbf0b3cff492e8b74a08702753681620f9fd8c92217d8c32f70', 'v2', '2026-07-24T06:41:12+00:00', '["*  numbering model defined within COMMANDE_SUPPLIER_ADDON_NUMBER", "''class'' => (!getDolGlobalString(''COMMANDE_SUPPLIER_ADDON_NUMBER'') ? ''mod_commande_fournisseur_muguet'' : $conf->global->COMMANDE_SUPPLIER_ADDON_NUMBER),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMMANDE_SUPPLIER_ADDON_PDF', 'string', NULL, 'supplier_order', 'Name of the PDF document model/template used to generate supplier order PDFs.', 'Set via supplier_order/admin/supplier_order.php:154 (dolibarr_set_const) or removed via dolibarr_del_const at lines 149/166, selected among candidates checked at lines 148/428/444, and used in fourn/commande/card.php:3135 as a fallback when the object has no specific model_pdf.', 'Changing it switches the default PDF template used for supplier orders when the individual order does not specify its own model_pdf.', NULL, 0, 0, 'supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php', 1, '3718a387cc3d5613607ba591415d40672c48657dca857ec2534f9eef753611ea', 'v2', '2026-07-24T06:41:12+00:00', '["$modelpdf = (!empty($object->model_pdf) ? $object->model_pdf : (!getDolGlobalString(''COMMANDE_SUPPLIER_ADDON_PDF'') ? '''' : $conf->global->COMMANDE_SUPPLIER_ADDON_PDF));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_ADDON_PDF', 'string', NULL, 'societe', 'Specifies the PDF template module name used to generate company (third-party) PDF documents.', 'Written in societe/admin/societe.php:162 via dolibarr_set_const. Read in societe/class/societe.class.php:5479 to set the active PDF model. Checked in core/tpl/card_presend.tpl.php:136 to handle the case where no model is defined.', 'If unset, the presend card template handles the missing-model case. When set, the named PDF module is used to generate company documents.', 'Name of the PDF addon module (e.g. a class name string); empty means no model selected.', 0, 0, 'societe/admin/societe.php', 1, '8f351bcde4b76c115da0c63e224db1e9e603992026a3a29bc2afab8899b66f53', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:162|write|dolibarr_set_const($db, \"COMPANY_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity);", "societe/class/societe.class.php:5479|read|$modele = getDolGlobalString(''COMPANY_ADDON_PDF'');", "core/tpl/card_presend.tpl.php:136|check|if ($object->element == ''societe'' && !getDolGlobalString(''COMPANY_ADDON_PDF'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies the directory path(s) to scan for ODT templates used in company/third-party document generation.', 'Read in core/modules/societe/doc/doc_generic_odt.modules.php. Per the code comment in core/lib/functions2.lib.php: ''with the constant that contains list of directories to scan (COMPANY_ADDON_PDF_ODT_PATH, ...)''. The value is split on commas/newlines to build a directory list.', 'Changing this value redirects ODT template discovery for company documents to the specified directories; leaving it unset skips custom template directory scanning.', 'Comma- or newline-separated list of directory paths.', 1, 0, NULL, 1, '4a4036738ce008bffbd6b74dc427a62fb88a4a541418e48c58a04c9e9da7677e', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/functions2.lib.php:1897  // with the constant that contains list of directories to scan (COMPANY_ADDON_PDF_ODT_PATH, ...).", "core/modules/societe/doc/doc_generic_odt.modules.php:117|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''COMPANY_ADDON_PDF_ODT_PATH''))));", "core/modules/societe/doc/doc_generic_odt.modules.php:163|check|if (getDolGlobalString(''COMPANY_ADDON_PDF_ODT_PATH'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_AQUARIUM_CLEAN_REGEX', 'string', NULL, 'core', 'Defines a regex pattern applied to accountancy codes in the Aquarium module to extract and keep only captured groups.', 'Used in core/modules/societe/mod_codecompta_aquarium.php. Per the code comments: ''Apply a regex replacement pattern on code if COMPANY_AQUARIUM_CLEAN_REGEX is set. Value must be a regex with parenthesis. The part into parenthesis is kept, the rest removed.'' Example in code: ''^..(..)..''.', 'Setting this constant applies a preg_replace transformation to generated codes, retaining only the portions matched by capturing groups; leaving it unset skips this transformation.', 'Apply a regex replacement pattern on code if COMPANY_AQUARIUM_CLEAN_REGEX is set. Value must be a regex with parenthesis. The part into parenthesis is kept, the rest removed. Example: $conf->global->COMPANY_AQUARIUM_CLEAN_REGEX=''^..(..)..'';', 1, 0, NULL, 1, '7fec5f7f5b73f6ba8fd7d465be2d8deabe59ebe674be5281567e597b0c11b4ad', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_aquarium.php:197  // Apply a regex replacement pattern on code if COMPANY_AQUARIUM_CLEAN_REGEX is set. Value must be a regex with parenthesis. The part into parenthesis is kept, the rest removed.", "core/modules/societe/mod_codecompta_aquarium.php:187  //$conf->global->COMPANY_AQUARIUM_CLEAN_REGEX=''^..(..)..'';", "core/modules/societe/mod_codecompta_aquarium.php:198|check|if (getDolGlobalString(''COMPANY_AQUARIUM_CLEAN_REGEX'')) {\t// Example: $conf->global->COMPANY_AQUARIUM_CLEAN_REGEX=''^..(..)..'';", "core/modules/societe/mod_codecompta_aquarium.php:199|read|$codetouse = preg_replace(''/'' . getDolGlobalString(''COMPANY_AQUARIUM_CLEAN_REGEX'').''/'', ''\\1\\2\\3'', (string) $codetouse);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_AQUARIUM_MASK_CUSTOMER', 'string', NULL, 'core', 'Defines the accountancy code prefix used for customers in the Aquarium module.', 'Used in core/modules/societe/mod_codecompta_aquarium.php. If unset or empty, defaults to ''411''. The value is assigned to prefixcustomeraccountancycode and used when building customer accountancy codes.', 'Changing this value alters the prefix prepended to customer accountancy codes generated by the Aquarium module; the default fallback is ''411''.', 'Numeric string (e.g. ''411''); defaults to ''411'' if empty or unset.', 1, 0, NULL, 1, 'b707df3184dbd0e1686bbbf296ee248afb0727795a9c37df76f3697b93b46098', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_aquarium.php:75|read|if (!isset($conf->global->COMPANY_AQUARIUM_MASK_CUSTOMER) || trim($conf->global->COMPANY_AQUARIUM_MASK_CUSTOMER) == '''') {", "core/modules/societe/mod_codecompta_aquarium.php:76|write|$conf->global->COMPANY_AQUARIUM_MASK_CUSTOMER = ''411'';", "core/modules/societe/mod_codecompta_aquarium.php:86|read|$this->prefixcustomeraccountancycode = getDolGlobalString(''COMPANY_AQUARIUM_MASK_CUSTOMER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_AQUARIUM_MASK_SUPPLIER', 'string', NULL, 'core', 'Defines the accountancy code prefix used for suppliers in the Aquarium module.', 'Used in core/modules/societe/mod_codecompta_aquarium.php. If unset or empty, defaults to ''401''. The value is assigned to prefixsupplieraccountancycode and used when building supplier accountancy codes.', 'Changing this value alters the prefix prepended to supplier accountancy codes generated by the Aquarium module; the default fallback is ''401''.', 'Numeric string (e.g. ''401''); defaults to ''401'' if empty or unset.', 1, 0, NULL, 1, '1c9fe411fff96bd31461570d85182f831a299c17f5c7fa4ddc5652ada3a08aa5', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_aquarium.php:78|read|if (!isset($conf->global->COMPANY_AQUARIUM_MASK_SUPPLIER) || trim($conf->global->COMPANY_AQUARIUM_MASK_SUPPLIER) == '''') {", "core/modules/societe/mod_codecompta_aquarium.php:79|write|$conf->global->COMPANY_AQUARIUM_MASK_SUPPLIER = ''401'';", "core/modules/societe/mod_codecompta_aquarium.php:87|read|$this->prefixsupplieraccountancycode = getDolGlobalString(''COMPANY_AQUARIUM_MASK_SUPPLIER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_AQUARIUM_NO_PREFIX', 'string', NULL, 'core', 'Controls whether the Aquarium accountancy code module omits the prefix when generating company codes.', 'Used exclusively in core/modules/societe/mod_codecompta_aquarium.php. When set, the prefix step is skipped during accountancy code generation. The value is also displayed in the module''s info text output.', 'Enabling this constant causes the Aquarium module to generate accountancy codes without a prefix; disabling or unsetting it restores prefix-based code generation.', 'Any truthy string to enable; empty or unset to disable.', 1, 0, NULL, 1, '354b56c16986f418aea1663c11a8d1e2a8ad88d2ed5878790727704cc096f6dd', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_aquarium.php:82|check|if (getDolGlobalString(''COMPANY_AQUARIUM_NO_PREFIX'')) {", "core/modules/societe/mod_codecompta_aquarium.php:127|check|if (getDolGlobalString(''COMPANY_AQUARIUM_NO_PREFIX'')) {", "core/modules/societe/mod_codecompta_aquarium.php:128|read|$texte .= $langs->trans(''COMPANY_AQUARIUM_NO_PREFIX'').'' = '' . getDolGlobalString(''COMPANY_AQUARIUM_NO_PREFIX'').\"<br>\\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_AQUARIUM_REMOVE_ALPHA', 'string', NULL, 'core', 'Strips alphabetic characters from the accounting code generated by the ''Aquarium'' third-party accounting-code numbering model.', 'Documented by an inline comment (core/modules/societe/mod_codecompta_aquarium.php:193: ''Remove special alpha if COMPANY_AQUARIUM_REMOVE_ALPHA is set to 1'') and applied at line 194-195: if set, `preg_replace(''/([a-z])/i'', '''', $codetouse)` removes all letters from the code.', 'Setting it to 1 removes all alphabetic characters from the generated accounting code, leaving only digits/other characters.', 'Boolean, per comment: ''set to 1'' removes alpha characters from the code; unset/0 (default) leaves letters in place.', 1, 0, NULL, 1, 'cffe3421af3a1d7859dd2b61c96624f4ef0c62dd7f6764d76ed55ebd68960724', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/societe/mod_codecompta_aquarium.php:193| // Remove special alpha if COMPANY_AQUARIUM_REMOVE_ALPHA is set to 1", "core/modules/societe/mod_codecompta_aquarium.php:194|check|if (getDolGlobalString(''COMPANY_AQUARIUM_REMOVE_ALPHA'')) {", "core/modules/societe/mod_codecompta_aquarium.php:195|  $codetouse = preg_replace(''/([a-z])/i'', '''', (string) $codetouse);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_AQUARIUM_REMOVE_SPECIAL', 'string', NULL, 'core', 'Controls whether special characters are stripped from accountancy codes in the Aquarium module.', 'Used in core/modules/societe/mod_codecompta_aquarium.php. Per the code comment: ''Remove special char if COMPANY_AQUARIUM_REMOVE_SPECIAL is set to 1 or not set (default)''. Special character removal is active both when the constant is truthy and when it is not set.', 'Setting this to 1 or leaving it unset causes special characters to be removed from generated codes; explicitly setting it to 0 disables removal.', 'Remove special char if COMPANY_AQUARIUM_REMOVE_SPECIAL is set to 1 or not set (default)', 1, 0, NULL, 1, '59acd56dd045e05ca40803da002db4bcaba4a3865c2b216cdd6a33ba6462e84e', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_aquarium.php:189  // Remove special char if COMPANY_AQUARIUM_REMOVE_SPECIAL is set to 1 or not set (default)", "core/modules/societe/mod_codecompta_aquarium.php:190|check|if (!isset($conf->global->COMPANY_AQUARIUM_REMOVE_SPECIAL) || getDolGlobalString(''COMPANY_AQUARIUM_REMOVE_SPECIAL'')) {", "core/modules/societe/mod_codecompta_aquarium.php:120|check|if (getDolGlobalInt(''COMPANY_AQUARIUM_REMOVE_SPECIAL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DIGITARIA_CLEAN_REGEX', 'string', NULL, 'core', 'Defines a regex pattern applied to accountancy codes in the Digitaria module to retain only captured groups.', 'Used in core/modules/societe/mod_codecompta_digitaria.php. Per code comments: ''Apply a regex replacement pattern on code if COMPANY_DIGITARIA_CLEAN_REGEX is set. Value must be a regex with parenthesis. The part into parenthesis is kept, the rest removed.'' Applied via preg_replace keeping groups \1\2\3.', 'Setting this constant applies a regex transformation to generated codes, retaining only captured groups and removing the rest; leaving it unset skips this transformation.', 'Apply a regex replacement pattern on code if COMPANY_DIGITARIA_CLEAN_REGEX is set. Value must be a regex with parenthesis. The part into parenthesis is kept, the rest removed. Example: $conf->global->COMPANY_DIGITARIA_CLEAN_REGEX=''^..(..)..'';', 1, 0, NULL, 1, '82c89914bed1a55dadb8597fd132fd0e4313b19347b8d1992cbe7895cbf00cc2', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_digitaria.php:137  // Apply a regex replacement pattern on code if COMPANY_DIGITARIA_CLEAN_REGEX is set. Value must be a regex with parenthesis. The part into parenthesis is kept, the rest removed.", "core/modules/societe/mod_codecompta_digitaria.php:243  // Apply a regex replacement pattern on code if COMPANY_DIGITARIA_CLEAN_REGEX is set. Value must be a regex with parenthesis. The part into parenthesis is kept, the rest removed.", "core/modules/societe/mod_codecompta_digitaria.php:244|check|if (getDolGlobalString(''COMPANY_DIGITARIA_CLEAN_REGEX'')) {\t// Example: $conf->global->COMPANY_DIGITARIA_CLEAN_REGEX=''^..(..)..'';", "core/modules/societe/mod_codecompta_digitaria.php:245|read|$codetouse = (string) preg_replace(''/'' . getDolGlobalString(''COMPANY_DIGITARIA_CLEAN_REGEX'').''/'', ''\\1\\2\\3'', $codetouse);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DIGITARIA_CLEAN_WORDS', 'string', NULL, 'core', 'Defines a semicolon-separated list of words to be removed from company names when generating accountancy codes in the Digitaria module.', 'Used in core/modules/societe/mod_codecompta_digitaria.php. When set, the value is split on '';'' and each word is stripped from the company name before code generation. The value is also displayed in the module configuration info text.', 'Setting this constant removes the listed words from company names prior to code generation; leaving it unset skips this word-cleaning step.', 'Semicolon-separated list of words to remove (e.g. ''SARL;SAS;SA'').', 1, 0, NULL, 1, 'd7c4f966244c7c40e10854e33504b5862114da266078469bd14304c78ca28d38', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_digitaria.php:235|check|if (getDolGlobalString(''COMPANY_DIGITARIA_CLEAN_WORDS'')) {", "core/modules/societe/mod_codecompta_digitaria.php:236|read|$cleanWords = explode(\";\", getDolGlobalString(''COMPANY_DIGITARIA_CLEAN_WORDS''));", "core/modules/societe/mod_codecompta_digitaria.php:158|check|if (getDolGlobalString(''COMPANY_DIGITARIA_CLEAN_WORDS'')) {", "core/modules/societe/mod_codecompta_digitaria.php:159|read|$texte .= $conf->global->COMPANY_DIGITARIA_CLEAN_WORDS;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DIGITARIA_MASK_CUSTOMER', 'string', NULL, 'core', 'Defines the accountancy code prefix for customers in the Digitaria module.', 'Used in core/modules/societe/mod_codecompta_digitaria.php. If unset or empty, defaults to ''411''. Assigned to prefixcustomeraccountancycode and rendered in the module''s configuration form.', 'Changing this value alters the customer accountancy code prefix generated by the Digitaria module; the default fallback is ''411''.', 'Numeric string (e.g. ''411''); defaults to ''411'' if empty or unset.', 1, 0, NULL, 1, 'b0e6090c48bd6df73882bdd05cdb7b28d4fdcebd353c79073e1b4da5d812d42b', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_digitaria.php:83|read|if (!isset($conf->global->COMPANY_DIGITARIA_MASK_CUSTOMER) || trim($conf->global->COMPANY_DIGITARIA_MASK_CUSTOMER) == '''') {", "core/modules/societe/mod_codecompta_digitaria.php:84|write|$conf->global->COMPANY_DIGITARIA_MASK_CUSTOMER = ''411'';", "core/modules/societe/mod_codecompta_digitaria.php:89|read|$this->prefixcustomeraccountancycode = getDolGlobalString(''COMPANY_DIGITARIA_MASK_CUSTOMER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DIGITARIA_MASK_NBCHARACTER_CUSTOMER', 'string', NULL, 'core', 'Sets the number of characters used in the customer accountancy code generated by the Digitaria module.', 'Used in core/modules/societe/mod_codecompta_digitaria.php. If unset or empty, defaults to ''5''. Assigned to customeraccountancycodecharacternumber and displayed in the module''s configuration form.', 'Changing this value controls how many characters are used when truncating or padding customer accountancy codes; the default fallback is ''5''.', 'Numeric string indicating character count (e.g. ''5''); defaults to ''5'' if empty or unset.', 1, 0, NULL, 1, '1a02b4ff312a76fa243c1fd0422811b55afac49a35ff49275c4ccaa5c6c11817', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_digitaria.php:92|read|if (!isset($conf->global->COMPANY_DIGITARIA_MASK_NBCHARACTER_CUSTOMER) || trim($conf->global->COMPANY_DIGITARIA_MASK_NBCHARACTER_CUSTOMER) == '''') {", "core/modules/societe/mod_codecompta_digitaria.php:93|write|$conf->global->COMPANY_DIGITARIA_MASK_NBCHARACTER_CUSTOMER = ''5'';", "core/modules/societe/mod_codecompta_digitaria.php:98|read|$this->customeraccountancycodecharacternumber = getDolGlobalString(''COMPANY_DIGITARIA_MASK_NBCHARACTER_CUSTOMER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DIGITARIA_MASK_NBCHARACTER_SUPPLIER', 'string', NULL, 'core', 'Sets the number of characters used in the supplier accountancy code generated by the Digitaria module.', 'Used in core/modules/societe/mod_codecompta_digitaria.php. If unset or empty, defaults to ''5''. Assigned to supplieraccountancycodecharacternumber and displayed in the module''s configuration form.', 'Changing this value controls how many characters are used when truncating or padding supplier accountancy codes; the default fallback is ''5''.', 'Numeric string indicating character count (e.g. ''5''); defaults to ''5'' if empty or unset.', 1, 0, NULL, 1, '0f06a095d02fcf19280ef3f53bf4b64cd3ab6b6be3ff641f4cef7f0718ec2f86', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_digitaria.php:95|read|if (!isset($conf->global->COMPANY_DIGITARIA_MASK_NBCHARACTER_SUPPLIER) || trim($conf->global->COMPANY_DIGITARIA_MASK_NBCHARACTER_SUPPLIER) == '''') {", "core/modules/societe/mod_codecompta_digitaria.php:96|write|$conf->global->COMPANY_DIGITARIA_MASK_NBCHARACTER_SUPPLIER = ''5'';", "core/modules/societe/mod_codecompta_digitaria.php:99|read|$this->supplieraccountancycodecharacternumber = getDolGlobalString(''COMPANY_DIGITARIA_MASK_NBCHARACTER_SUPPLIER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DIGITARIA_MASK_SUPPLIER', 'string', NULL, 'core', 'Defines the accountancy code prefix for suppliers in the Digitaria module.', 'Used in core/modules/societe/mod_codecompta_digitaria.php. If unset or empty, defaults to ''401''. Assigned to prefixsupplieraccountancycode and rendered in the module''s configuration form.', 'Changing this value alters the supplier accountancy code prefix generated by the Digitaria module; the default fallback is ''401''.', 'Numeric string (e.g. ''401''); defaults to ''401'' if empty or unset.', 1, 0, NULL, 1, '94a4c68ee5518cbdf9649ae991ee9f0032090933d74467a814ba6a88e10dd460', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_digitaria.php:86|read|if (!isset($conf->global->COMPANY_DIGITARIA_MASK_SUPPLIER) || trim($conf->global->COMPANY_DIGITARIA_MASK_SUPPLIER) == '''') {", "core/modules/societe/mod_codecompta_digitaria.php:87|write|$conf->global->COMPANY_DIGITARIA_MASK_SUPPLIER = ''401'';", "core/modules/societe/mod_codecompta_digitaria.php:90|read|$this->prefixsupplieraccountancycode = getDolGlobalString(''COMPANY_DIGITARIA_MASK_SUPPLIER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DIGITARIA_REMOVE_SPECIAL', 'string', NULL, 'core', 'Controls whether special characters are stripped from accountancy codes in the Digitaria module.', 'Used in core/modules/societe/mod_codecompta_digitaria.php. Per code comments: ''Remove special char if COMPANY_DIGITARIA_REMOVE_SPECIAL is set to 1 or not set (default)''. Removal is active when the constant is truthy or not set.', 'Setting to 1 or leaving unset causes special characters to be removed from generated codes; explicitly setting to 0 disables removal.', 'Remove special char if COMPANY_DIGITARIA_REMOVE_SPECIAL is set to 1 or not set (default)', 1, 0, NULL, 1, '71b86f7b8e2173a9f7036b93de5fbbc30e9faa9eef7c5ddcb8a942d8dbddf4b9', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_digitaria.php:133  // Remove special char if COMPANY_DIGITARIA_REMOVE_SPECIAL is set to 1 or not set (default)", "core/modules/societe/mod_codecompta_digitaria.php:239  // Remove special char if COMPANY_DIGITARIA_REMOVE_SPECIAL is set to 1 or not set (default)", "core/modules/societe/mod_codecompta_digitaria.php:134|check|if (!isset($conf->global->COMPANY_DIGITARIA_REMOVE_SPECIAL) || getDolGlobalString(''COMPANY_DIGITARIA_REMOVE_SPECIAL'')) {", "core/modules/societe/mod_codecompta_digitaria.php:240|check|if (!isset($conf->global->COMPANY_DIGITARIA_REMOVE_SPECIAL) || getDolGlobalString(''COMPANY_DIGITARIA_REMOVE_SPECIAL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DIGITARIA_UNIQUE_CODE', 'string', NULL, 'core', 'Controls whether the Digitaria module enforces unique accountancy codes across companies.', 'Used in core/modules/societe/mod_codecompta_digitaria.php. Per code comments: ''If value is not unique (if COMPANY_DIGITARIA_UNIQUE_CODE is set to 0), we show this'' and ''Unique index on code if COMPANY_DIGITARIA_UNIQUE_CODE is set to 1 or not set (default)''.', 'Setting to 1 or leaving unset enforces unique code constraint; setting to 0 disables the uniqueness check and displays an informational note.', '1 or not set = enforce unique codes (default); 0 = allow duplicate codes', 1, 0, NULL, 1, 'd9b96915df2a5500c1e97308e6c750a03ba5ef21fe3663be9adb2e1e8b86e6d4', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codecompta_digitaria.php:141  // If value is not unique (if COMPANY_DIGITARIA_UNIQUE_CODE is set to 0), we show this", "core/modules/societe/mod_codecompta_digitaria.php:251  // Unique index on code if COMPANY_DIGITARIA_UNIQUE_CODE is set to 1 or not set (default)", "core/modules/societe/mod_codecompta_digitaria.php:142|check|if (!getDolGlobalString(''COMPANY_DIGITARIA_UNIQUE_CODE'', ''1'')) {", "core/modules/societe/mod_codecompta_digitaria.php:252|check|if (getDolGlobalString(''COMPANY_DIGITARIA_UNIQUE_CODE'', ''1'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_DONOTSEARCH_ANYWHERE', 'string', NULL, 'admin', 'Restricts third-party name searches to prefix matching (instead of substring matching) to allow database index usage.', 'Checked in admin/system/perf.php (line 709) and societe/ajax/ajaxcompanies.php:116. Read in core/class/html.form.class.php:1652: `$prefix = !getDolGlobalString(''COMPANY_DONOTSEARCH_ANYWHERE'') ? ''%'' : ''''; // Can use index if COMPANY_DONOTSEARCH_ANYWHERE is on`.', 'Enabling this setting changes the SQL LIKE pattern from `%search%` to `search%`, enabling index use and improving search performance at the cost of not matching mid-string occurrences.', 'Truthy string (non-empty) = prefix search only (index-optimized); empty/not set = substring search (full LIKE with leading wildcard).', 0, 0, 'admin/system/perf.php|admin/system/perf.php', 1, 'd6e5744689452be1c2ad6b9f697ead245b02da0361c321065fd65afcaf5e5f93', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.form.class.php:1652|read|$prefix = !getDolGlobalString(''COMPANY_DONOTSEARCH_ANYWHERE'') ? ''%'' : ''''; // Can use index if COMPANY_DONOTSEARCH_ANYWHERE is on", "societe/ajax/ajaxcompanies.php:116|check|if (getDolGlobalString(''COMPANY_DONOTSEARCH_ANYWHERE'')) {   // Can use index", "admin/system/perf.php:709|check|if (!getDolGlobalString(''COMPANY_DONOTSEARCH_ANYWHERE'')) {", "admin/system/perf.php:713|read|print img_picto('''', ''tick'', ''class=\"pictofixedwidth\"'').'' ''.$langs->trans(\"YouHaveXObjectAndSearchOptimOn\", $nb, …"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_ELEPHANT_DATE_START', 'string', NULL, 'core', 'Defines the start date threshold used by the Elephant module when assigning customer codes based on company creation date.', 'Read in core/modules/societe/mod_codeclient_elephant.php. Used alongside COMPANY_ELEPHANT_DATE_START_ENABLE: when that flag is enabled and a company''s creation date is before this value, a specific code assignment path is taken.', 'Changing this date alters which companies are subject to the date-based code assignment logic in the Elephant module.', 'A date string value compared against company creation date.', 1, 0, NULL, 1, '51f0ab493bdef652e3ce9a37944159c06e8a26384c30b2cd45a904adaefc729b', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codeclient_elephant.php:127|read|$datedb = getDolGlobalString(''COMPANY_ELEPHANT_DATE_START'');", "core/modules/societe/mod_codeclient_elephant.php:326|check|if (getDolGlobalString(''COMPANY_ELEPHANT_DATE_START_ENABLE'') && $soc->date_creation < getDolGlobalString(''COMPANY_ELEPHANT_DATE_START'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_ELEPHANT_DATE_START_ENABLE', 'bool', NULL, 'core', 'Enables the date-based code assignment logic in the Elephant module.', 'Checked in core/modules/societe/mod_codeclient_elephant.php alongside COMPANY_ELEPHANT_DATE_START. When truthy, companies with a creation date before the value of COMPANY_ELEPHANT_DATE_START follow a separate code assignment path.', 'Enabling this flag activates the date-threshold code assignment logic; disabling it bypasses the date check.', 'Truthy value to enable date-based logic; empty or unset to disable.', 1, 0, NULL, 1, '11a2bdb667f23a6e35b38c3adb87b54a9957bb11f1ea817f453dfd6592dd00d7', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codeclient_elephant.php:326|check|if (getDolGlobalString(''COMPANY_ELEPHANT_DATE_START_ENABLE'') && $soc->date_creation < getDolGlobalString(''COMPANY_ELEPHANT_DATE_START'')) {", "core/modules/societe/mod_codeclient_elephant.php:146|read|$isEnabled = getDolGlobalString(''COMPANY_ELEPHANT_DATE_START_ENABLE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_ELEPHANT_MASK_CUSTOMER', 'string', NULL, 'core', 'Defines the numbering mask for customer codes in the Elephant module.', 'Read in core/modules/societe/mod_codeclient_elephant.php at multiple locations (lines 247, 288, 337) for generating customer codes, and at line 115 to populate the configuration form input. Falls back to empty string when unset.', 'Changing this value alters the mask pattern used to generate customer codes in the Elephant module; leaving it unset produces an empty mask.', 'Any valid mask string for customer code generation; empty string if unset.', 1, 0, NULL, 1, '683897365239dea7e18f31afe677f57d9540d68f5a5fe13ad6e9efa638b5a227', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codeclient_elephant.php:247|read|$mask = getDolGlobalString(''COMPANY_ELEPHANT_MASK_CUSTOMER'');", "core/modules/societe/mod_codeclient_elephant.php:337|read|$mask = !getDolGlobalString(''COMPANY_ELEPHANT_MASK_CUSTOMER'') ? '''' : $conf->global->COMPANY_ELEPHANT_MASK_CUSTOMER;", "core/modules/societe/mod_codeclient_elephant.php:288|read|$mask = getDolGlobalString(''COMPANY_ELEPHANT_MASK_CUSTOMER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_ELEPHANT_MASK_SUPPLIER', 'string', NULL, 'core', 'Defines the numbering mask for supplier codes in the Elephant module.', 'Read in core/modules/societe/mod_codeclient_elephant.php at multiple locations (lines 250, 293, 340) for generating supplier codes, and at line 123 to populate the configuration form input. Falls back to empty string when unset.', 'Changing this value alters the mask pattern used to generate supplier codes in the Elephant module; leaving it unset produces an empty mask.', 'Any valid mask string for supplier code generation; empty string if unset.', 1, 0, NULL, 1, 'bc77dc30170fa831a8cf7223c35cd1a4105b9d8d16d2faf2f544cdaafd3df247', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/societe/mod_codeclient_elephant.php:250|read|$mask = getDolGlobalString(''COMPANY_ELEPHANT_MASK_SUPPLIER'');", "core/modules/societe/mod_codeclient_elephant.php:340|read|$mask = !getDolGlobalString(''COMPANY_ELEPHANT_MASK_SUPPLIER'') ? '''' : $conf->global->COMPANY_ELEPHANT_MASK_SUPPLIER;", "core/modules/societe/mod_codeclient_elephant.php:293|read|$mask = getDolGlobalString(''COMPANY_ELEPHANT_MASK_SUPPLIER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_HIDE_INACTIVE_IN_COMBOBOX', 'bool', NULL, 'core', 'Hides inactive (closed/archived) companies from third-party selection comboboxes.', 'When set, core/class/html.form.class.php filters out inactive companies from the SQL query used to populate the third-party selector. Configurable via the admin UI at societe/admin/societe.php. Saved via dolibarr_set_const.', 'Enabling this constant removes inactive companies from all third-party comboboxes; disabling it shows all companies regardless of status.', 'Non-empty (truthy) hides inactive companies; empty or undefined shows all.', 0, 0, 'societe/admin/societe.php', 1, '109a35f8bffa8b899ef3ab2c6659e0018d573432c4b92d4371a23b23c479bec1', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:1639|check|if (getDolGlobalString(''COMPANY_HIDE_INACTIVE_IN_COMBOBOX'')) {", "societe/admin/societe.php:315|write|$result = dolibarr_set_const($db, \"COMPANY_HIDE_INACTIVE_IN_COMBOBOX\", $status, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_NEWFORM_TEXT', 'string', NULL, 'public', 'Custom help/intro text (translation key) shown above the public new-company/subscription form; overrides the default ''contact us'' text.', 'Checked and read in public/company/new.php:301-302; if set, its value is passed through $langs->trans() and printed instead of the default ContactUsDesc text that references MAIN_INFO_SOCIETE_MAIL.', 'Setting it replaces the default ''contact us'' help text on the public subscription form with a custom translated string; if unset, the default ContactUsDesc language string (including the company''s info email) is shown.', 'String: a translation key or text passed to $langs->trans(); default behavior if unset shows ContactUsDesc with MAIN_INFO_SOCIETE_MAIL.', 1, 0, NULL, 1, '00bc4ce31100d3b462dc6283d3da1b304780cb30b5794ce986feb230c063d85a', 'v2', '2026-07-24T07:05:23+00:00', '["public/company/new.php:301|check|if (getDolGlobalString(''COMPANY_NEWFORM_TEXT'')) {", "public/company/new.php:302|read|print $langs->trans(getDolGlobalString(''COMPANY_NEWFORM_TEXT'')) . \"<br>\\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_SHOW_ADDRESS_SELECTLIST', 'bool', NULL, 'societe', 'Enables display of ZIP code and town in third-party selection dropdowns.', 'Written via societe/admin/societe.php (line 223). Read in societe/class/societe.class.php (lines 987-988) to set `showoncombobox` for zip and town fields. Checked in core/class/html.form.class.php:1616 and societe/ajax/ajaxcompanies.php (lines 104, 108, 163). COMMENT: `//$this->fields[''fk_pays''][''showoncombobox''] = $conf->global->COMPANY_SHOW_ADDRESS_SELECTLIST;`.', 'Enabling this setting adds the city and ZIP code alongside the company name in third-party autocomplete lists.', '0 or empty = only company name shown; 1 = ZIP and town shown in dropdowns.', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, '05a7b1b9a3e509b744c92502d0da98ab37dde5ac85b63816040cb00202c714a4', 'v2', '2026-04-21T11:16:15+00:00', '["societe/class/societe.class.php:989  //$this->fields[''fk_pays''][''showoncombobox''] = $conf->global->COMPANY_SHOW_ADDRESS_SELECTLIST;", "societe/class/societe.class.php:987|read|$this->fields[''zip''][''showoncombobox''] = getDolGlobalInt(''COMPANY_SHOW_ADDRESS_SELECTLIST'');", "societe/class/societe.class.php:988|read|$this->fields[''town''][''showoncombobox''] = getDolGlobalInt(''COMPANY_SHOW_ADDRESS_SELECTLIST'');", "societe/admin/societe.php:223|write|$res = dolibarr_set_const($db, \"COMPANY_SHOW_ADDRESS_SELECTLIST\", $val, ''yesno'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('COMPANY_USE_SEARCH_TO_SELECT', 'bool', NULL, 'core', 'Enables Ajax autocomplete search for third-party (company) selection dropdowns instead of loading the full list.', 'Controls whether company selector inputs use an Ajax autocomplete widget. When set, the numeric value is used as the minimum character count before triggering search, defaulting to 2 if non-numeric. Configured via societe/admin/societe.php.', 'When disabled, the full company list is loaded in the selector. When enabled, an Ajax endpoint is called after the configured minimum number of characters are typed.', 'Empty/0 = disabled (full list loaded); positive integer = minimum chars to trigger Ajax search (default 2 if non-numeric value set)', 0, 0, 'societe/admin/societe.php|admin/system/perf.php|admin/system/perf.php|societe/admin/societe.php', 1, 'bdae10202e89a15552f38c79b37cb436eccb345a4724637d48b452739828dc13', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.formcompany.class.php:659|read|$minLength = (is_numeric(getDolGlobalString(''COMPANY_USE_SEARCH_TO_SELECT'')) ? $conf->global->COMPANY_USE_SEARCH_TO_SELECT : 2);", "admin/system/perf.php:565|check|if (!getDolGlobalString(''COMPANY_USE_SEARCH_TO_SELECT'')) {", "core/lib/ajax.lib.php:463  * TODO: It is used when COMPANY_USE_SEARCH_TO_SELECT and CONTACT_USE_SEARCH_TO_SELECT are set by html.formcompany.class.php. Should use ajax_autocompleter instead like done by html.form.class.php for select_produits.", "societe/admin/societe.php:85|write|$res = dolibarr_set_const($db, \"COMPANY_USE_SEARCH_TO_SELECT\", $companysearch, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONFERENCEORBOOTHATTENDEE_ADDON_PDF', 'string', NULL, 'eventorganization', 'Sets the default PDF document model/template used to generate conference-or-booth attendee documents.', 'Read in eventorganization/class/conferenceorboothattendee.class.php:1097-1098 as a fallback model name (after the object''s own model_pdf) when generateDocument() is called without an explicit model.', 'Setting it changes which PDF template (''standard_conferenceorboothattendee'' by default) is used to generate attendee documents when no per-object model is set.', 'String: name of a PDF document model under core/modules/eventorganization/doc/; default fallback is ''standard_conferenceorboothattendee''.', 1, 0, NULL, 1, '1786ff24809a52f9476db1c1b6a45b5101d2c7eeaccade0dc344015667a342eb', 'v2', '2026-07-24T07:05:23+00:00', '["eventorganization/class/conferenceorboothattendee.class.php:1097: } elseif (getDolGlobalString(''CONFERENCEORBOOTHATTENDEE_ADDON_PDF'')) {", "eventorganization/class/conferenceorboothattendee.class.php:1098: $modele = getDolGlobalString(''CONFERENCEORBOOTHATTENDEE_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONFERENCEORBOOTH_ADDON_PDF', 'string', NULL, 'eventorganization', 'Sets the default PDF document model/template used to generate conference-or-booth documents.', 'Read in eventorganization/class/conferenceorbooth.class.php:823-824 as a fallback model name (after the object''s own model_pdf) when generateDocument() is called without an explicit model.', 'Setting it changes which PDF template (''standard_conferenceorbooth'' by default) is used to generate conference/booth documents when no per-object model is set.', 'String: name of a PDF document model under core/modules/eventorganization/doc/; default fallback is ''standard_conferenceorbooth''.', 1, 0, NULL, 1, '00eb2e52993f5ebac752e5e47762854299303d74f2aa2860a534d3a27151c8bf', 'v2', '2026-07-24T07:05:23+00:00', '["eventorganization/class/conferenceorbooth.class.php:823: } elseif (getDolGlobalString(''CONFERENCEORBOOTH_ADDON_PDF'')) {", "eventorganization/class/conferenceorbooth.class.php:824: $modele = getDolGlobalString(''CONFERENCEORBOOTH_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTACTS_DEFAULT_ROLES', 'string', NULL, 'societe', 'Stores the comma-separated list of default role codes automatically assigned to new contacts created for a third party.', 'Written via societe/admin/societe.php:124 using implode('','', $rolessearch) and read at societe/admin/societe.php:974 with explode. Applied in societe/class/societe.class.php:1235-1236 when creating a contact, setting $contact->roles from the exploded value.', 'When set, newly created contacts inherit the specified roles automatically; when empty, no default roles are assigned.', 'String: comma-separated role codes (e.g. ''BILLING,SHIPPING''); empty = no default roles', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, 'b8543e7b1cfb2a61350fc4d5629116968cd7599d75cabb78705b3e07984cd089', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:124|write|$res = dolibarr_set_const($db, \"CONTACTS_DEFAULT_ROLES\", implode('','', $rolessearch), ''chaine'', 0, '''', $conf->entity);", "societe/class/societe.class.php:1235|check|if (getDolGlobalString(''CONTACTS_DEFAULT_ROLES'')) {", "societe/class/societe.class.php:1236|read|$contact->roles = explode('','', getDolGlobalString(''CONTACTS_DEFAULT_ROLES''));", "societe/admin/societe.php:974|read|$selected = explode('','', getDolGlobalString(''CONTACTS_DEFAULT_ROLES''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTACT_DONOTSEARCH_ANYWHERE', 'string', NULL, 'contact', 'When enabled, disables the wildcard prefix in the contact ajax search-as-you-type query so the search can use a database index.', 'Read in contact/ajax/contact.php:140: `$prefix = getDolGlobalString(''CONTACT_DONOTSEARCH_ANYWHERE'') ? '''' : ''%''; // Can use index if CONTACT_DONOTSEARCH_ANYWHERE is on`, used to build the SQL LIKE filter prefix for the contact search-as-you-type ajax endpoint.', 'When enabled, contact ajax search matches only from the start of fields (index-friendly, prefix search) instead of matching anywhere in the field (leading wildcard, not index-friendly); improves search performance on large contact tables at the cost of no longer matching mid-string substrings.', 'Boolean-like: truthy sets prefix to '''' (search must match from start, index-friendly); falsy/unset uses ''%'' (search matches anywhere in the field).', 1, 0, NULL, 1, 'a55f5a0e0383970acc2cdaee9d1470ca87f3768c1ff5cff4f460d2a4c63b1df1', 'v2', '2026-07-24T07:05:23+00:00', '["contact/ajax/contact.php:140|read|$prefix = getDolGlobalString(''CONTACT_DONOTSEARCH_ANYWHERE'') ? '''' : ''%''; // Can use index if CONTACT_DONOTSEARCH_ANYWHERE is on"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTACT_HIDE_INACTIVE_IN_COMBOBOX', 'bool', NULL, 'core', 'Excludes inactive (statut=0) contacts from the contact selection combobox/list SQL query.', 'core/class/html.form.class.php:2326: `if (getDolGlobalString(''CONTACT_HIDE_INACTIVE_IN_COMBOBOX'')) { $sql .= " AND sp.statut <> 0"; }`, appended to the contact-search SQL that builds the select_contacts-style list.', 'Setting it to a truthy value adds a `sp.statut <> 0` filter, hiding inactive contacts from this contact combobox/search result; unset shows all contacts regardless of status.', 'Truthy = hide inactive contacts (statut=0 excluded); 0/unset = show all contacts (default).', 0, 0, NULL, 1, '4554e4911ba2a6677540ac69752460310c75c52bfc5cfec066bf4dab57afc57e', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:2326: if (getDolGlobalString(''CONTACT_HIDE_INACTIVE_IN_COMBOBOX'')) { $sql .= \" AND sp.statut <> 0\"; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTACT_PHONEMOBILE_SHOW_LINK_TO_WHATSAPP', 'bool', NULL, 'core', 'Adds a WhatsApp click-to-chat link next to a rendered mobile phone number.', 'In core/lib/functions.lib.php:5112, when rendering a phone value with picto type ''mobile'', if this constant is set the code appends a `https://wa.me/...` link with a WhatsApp icon next to the phone number.', 'Enabling it displays a WhatsApp icon/link for mobile phone numbers, letting users open a WhatsApp chat with that number directly.', 'Boolean-like: any truthy value enables the WhatsApp link for mobile numbers.', 1, 0, NULL, 1, 'd1ede4daf33b46e8cb1e53f279c90b835db24e2a6d3b69b79a6bdd0a4e827ef7', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5112|check|if (getDolGlobalString(''CONTACT_PHONEMOBILE_SHOW_LINK_TO_WHATSAPP'') && $withpicto == ''mobile'') {", "$newphone .= '' <a href=\"https://wa.me/'' . $newphonewa . ''\" target=\"_blank\"'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTACT_SEARCH_AUTOFOCUS', 'string', NULL, 'core', 'Adds the HTML ''autofocus'' attribute to the contact search input box.', 'core/class/html.form.class.php:1965: `$out .= ''<input type="text" ... '' . (getDolGlobalString(''CONTACT_SEARCH_AUTOFOCUS'') ? ''autofocus'' : '''') . '' spellcheck="false" />'';` — same pattern as THIRDPARTY_SEARCH_AUTOFOCUS but applied to the contact search field.', 'Setting it to a truthy value makes the browser automatically place keyboard focus in the contact search field when the page loads; no effect otherwise.', 'Truthy = ''autofocus'' attribute added to the search input; 0/unset = no autofocus (default).', 1, 0, NULL, 1, '85e1b1b09ebdbe5b000589fc43bbad21d2c9a39689529fc772187f890a35fa21', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:1965: (getDolGlobalString(''CONTACT_SEARCH_AUTOFOCUS'') ? ''autofocus'' : '''') . '' spellcheck=\"false\" />'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTACT_SHOW_EMAIL_PHONE_TOWN_SELECTLIST', 'bool', NULL, 'core', 'Shows email, phone, and town information alongside contact names in contact selection dropdowns.', 'When enabled, additional fields (email, phone, town) are rendered next to contact names in contact selector lists. Configured via societe/admin/societe.php.', 'Enabling this provides more context in contact selectors at the cost of wider list entries. Disabling it shows only the contact name.', 'Truthy = show additional fields; empty/falsy = hide', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, '029754d98af4763a65b3d3d723204744f7593f8930053a5e49423a8358f14f7c', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:237|write|$res = dolibarr_set_const($db, \"CONTACT_SHOW_EMAIL_PHONE_TOWN_SELECTLIST\", $val, ''yesno'', 0, '''', $conf->entity);", "core/class/html.form.class.php:1878|check|if ($showsoc > 0 || getDolGlobalString(''CONTACT_SHOW_EMAIL_PHONE_TOWN_SELECTLIST'')) {", "core/class/html.form.class.php:1942|check|if (getDolGlobalString(''CONTACT_SHOW_EMAIL_PHONE_TOWN_SELECTLIST'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTACT_USE_COMPANY_ADDRESS', 'bool', NULL, 'contact', 'Forces contact records to inherit the linked company''s address fields when the contact''s own address is empty.', 'When enabled, address, zip, town, phone, fax, and email fields are copied from the associated third-party if the contact''s own fields are blank. Checked in contact/card.php:730, :749, :752, :786, :789, :820, and in contact/canvas/actions_contactcard_common.class.php:151.', 'Enabling this ensures contacts always display address data even when no explicit contact address is entered, by falling back to the company address.', '0 or empty = contact address is used as-is; non-empty = company address fills in blank contact fields', 1, 0, NULL, 1, '452cb8f2dc934901eb1387093a16fd17859dffce549a612b5688d2d1c322685a', 'v2', '2026-04-21T11:16:15+00:00', '["contact/card.php:730|check|if (((isset($objsoc->typent_code) && $objsoc->typent_code == ''TE_PRIVATE'') || getDolGlobalString(''CONTACT_USE_COMPANY_ADDRESS'')) && dol_strlen(trim($object->address)) == 0) {", "contact/card.php:749|check|if (((isset($objsoc->typent_code) && $objsoc->typent_code == ''TE_PRIVATE'') || getDolGlobalString(''CONTACT_USE_COMPANY_ADDRESS'')) && dol_strlen(trim($object->zip)) == 0) {", "contact/canvas/actions_contactcard_common.class.php:151|check|if ((isset($objsoc->typent_code) && $objsoc->typent_code == ''TE_PRIVATE'') || getDolGlobalString(''CONTACT_USE_COMPANY_ADDRESS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTACT_USE_SEARCH_TO_SELECT', 'bool', NULL, 'comm', 'Switches the contact selection widget to a search-based (autocomplete) selector instead of a plain dropdown, and can also set a minimum character threshold.', 'Set via societe/admin/societe.php:98 (dolibarr_set_const) and checked/read across many files (19 occurrences) including admin/system/perf.php:585/588, contact/ajax/contact.php:158, comm/action/card.php:1821/2403, and core/class/html.form.class.php:1942.', 'When enabled, contact selection uses an ajax search-to-select widget instead of a full dropdown, improving performance for large contact lists; contact/ajax/contact.php also uses its value as a minimum character count to guard against DOS via short search filters.', NULL, 0, 0, 'societe/admin/societe.php|admin/system/perf.php|admin/system/perf.php|societe/admin/societe.php', 1, '6d3ac0fa98d3508adee4bc8eb9d4e5e08f112e385fb95d4e1059d6649e1e30a0', 'v2', '2026-07-24T06:41:12+00:00', '["// If CONTACT_USE_SEARCH_TO_SELECT is set, check that nb of chars in $filter is >= to avoid DOS attack", "if (getDolGlobalInt(''CONTACT_USE_SEARCH_TO_SELECT'') && $nbchar < getDolGlobalInt(''CONTACT_USE_SEARCH_TO_SELECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_ADDON', 'string', NULL, 'contrat', 'Specifies the numbering module class used to generate contract reference numbers.', 'Read in contrat/class/contrat.class.php:321 to load the appropriate numbering class; the class file is included via contrat/class/contrat.class.php:2649. The default value is ''mod_contract_serpis'' as set in admin/contract.php:59. Configurable via admin/contract.php.', 'Changing this value switches the contract reference numbering algorithm. If the specified module class does not exist, contract number generation will fail.', 'String name of a module class under core/modules/contract/; default is ''mod_contract_serpis''.', 0, 0, 'admin/contract.php|admin/contract.php|admin/contract.php|admin/contract.php', 1, 'dd2a53bf6bb298682f426983e39b530e93389f0387187e3fc352007f5689f7dd', 'v2', '2026-04-21T11:16:15+00:00', '["contrat/class/contrat.class.php:321|read|$classname = getDolGlobalString(''CONTRACT_ADDON'');", "contrat/class/contrat.class.php:2649|read|require_once DOL_DOCUMENT_ROOT.\"/core/modules/contract/\" . getDolGlobalString(''CONTRACT_ADDON'').''.php'';", "admin/contract.php:59|write|$conf->global->CONTRACT_ADDON = ''mod_contract_serpis'';", "admin/contract.php:153|write|dolibarr_set_const($db, \"CONTRACT_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_ADDON_PDF', 'string', NULL, 'admin', 'Specifies the PDF generation module used to produce contract documents.', 'Written and read in admin/contract.php (lines 130, 131, 136, 139, 148) for selection and persistence. Used in contrat/card.php:703 to conditionally generate PDFs and in contrat/class/contrat.class.php:2550 to select the PDF module. Configurable via the admin UI at admin/contract.php.', 'Changing this value switches the PDF template used for contract documents. Deleting it disables automatic PDF generation for contracts.', 'String name of a PDF module class; unset means no default PDF type defined and automatic PDF generation is skipped.', 0, 0, 'admin/contract.php|admin/contract.php|admin/contract.php|admin/contract.php|admin/contract.php|admin/contract.php', 1, 'f6f51c5fe2f2762559785d6ed21e5a8a826ac6b6d44433bdcb290fbf2818ed98', 'v2', '2026-04-21T11:16:15+00:00', '["contrat/card.php:703|check|if (!getDolGlobalString(''MAIN_DISABLE_PDF_AUTOUPDATE'') && getDolGlobalString(''CONTRACT_ADDON_PDF'')) {    // No generation if default type not defined", "admin/contract.php:136|write|if (dolibarr_set_const($db, \"CONTRACT_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "admin/contract.php:148|write|dolibarr_del_const($db, \"CONTRACT_ADDON_PDF\", $conf->entity);", "contrat/class/contrat.class.php:2550|read|} elseif (getDolGlobalString(''CONTRACT_ADDON_PDF'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_ADDON_PDF_ODT_PATH', 'string', 'DOL_DATA_ROOT/doctemplates/contracts', 'core', 'Specifies the directory path(s) where ODT contract document templates are stored.', 'Read in core/modules/contract/doc/doc_generic_contract_odt.modules.php:124, :151, and :159. The value is split by comma and newline to build the list of template directories. Defaults to ''DOL_DATA_ROOT/doctemplates/contracts''.', 'Changing this constant redirects contract ODT template lookups to different directories; an invalid path causes template loading to fail.', 'Comma or newline-separated directory path(s) (default: ''DOL_DATA_ROOT/doctemplates/contracts'')', 1, 1, NULL, 1, '6624d272e5f8a85b2906454160c9293513513bcc5fbbec9cb5ad5d9d26031813', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/contract/doc/doc_generic_contract_odt.modules.php:124|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim($conf->global->CONTRACT_ADDON_PDF_ODT_PATH)));", "core/modules/contract/doc/doc_generic_contract_odt.modules.php:151|read|$texte .= getDolGlobalString(''CONTRACT_ADDON_PDF_ODT_PATH'');", "core/modules/contract/doc/doc_generic_contract_odt.modules.php:159|check|if (getDolGlobalString(''CONTRACT_ADDON_PDF_ODT_PATH'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'core', 'Enables an external download link for contract documents.', 'Checked in core/class/commonobject.class.php:6386 and core/lib/functions.lib.php:10743. When set, a public download link is generated for contract (contrat) objects.', 'Enabling this constant exposes contract documents via a public URL; disabling it removes the external download option.', 'Non-zero/non-empty = external download enabled; 0 or unset = disabled', 1, 0, NULL, 1, '65a9843da463dc34b4c7f275265a8b4b38a91e32ec9ab808aa4cbd09eebef27b', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:6386|check|if ($this->element == ''contrat'' && getDolGlobalInt(\"CONTRACT_ALLOW_EXTERNAL_DOWNLOAD\")) {", "core/lib/functions.lib.php:10743|check|if (getDolGlobalString(''CONTRACT_ALLOW_EXTERNAL_DOWNLOAD'') && is_object($object) && $object->element == ''contrat'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_ALLOW_ONLINESIGN', 'bool', NULL, 'admin', 'Enables online signature functionality for non-draft contracts.', 'When set, contrat/card.php:2408 shows the online sign action for contracts not in draft status. Also checked at admin/contract.php:546 to display the related configuration UI, and written at admin/contract.php:174. Only 3 occurrences across 2 files.', 'Enabling this constant makes the online signature action available on validated contracts.', 'Non-empty/truthy = online signature enabled; empty/unset = online signature not shown.', 0, 0, 'admin/contract.php|admin/contract.php', 1, '993084a7857dad3478372032e00476ee0a5fed77ebf7503320f0677e78029808', 'v2', '2026-04-21T11:16:15+00:00', '["admin/contract.php:174|write|if (!dolibarr_set_const($db, \"CONTRACT_ALLOW_ONLINESIGN\", $value, ''int'', 0, '''', $conf->entity)) {", "admin/contract.php:546|check|if (getDolGlobalString(''CONTRACT_ALLOW_ONLINESIGN'')) {", "contrat/card.php:2408|check|if ($object->status != Contrat::STATUS_DRAFT && getDolGlobalString(''CONTRACT_ALLOW_ONLINESIGN'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_ALLOW_TO_LINK_FROM_OTHER_COMPANY', 'bool', NULL, 'core', 'Controls whether contracts belonging to other companies (thirdparties) can be linked, either for all (''all'') or a specific comma-separated list of thirdparty ids.', 'Checked in core/class/html.formcontract.class.php at lines 90, 92, 93, and 140, where its value ''all'' bypasses the restriction and otherwise its value is used as a list of allowed thirdparty ids in a SQL IN clause.', 'When set to ''all'', contracts from any thirdparty can be linked; when set to a list of ids, only contracts from those specific thirdparties (plus the current one) can be linked; otherwise linking is restricted to the current thirdparty.', '''all'' or a list of ids separated by comma', 1, 0, NULL, 1, 'f5eea1cdc7b7f6b5f905a1bd2723269d6ccf5708cb6f0ed7c02db9c4a9d0fef5', 'v2', '2026-07-24T06:41:12+00:00', '["// CONTRACT_ALLOW_TO_LINK_FROM_OTHER_COMPANY is ''all'' or a list of ids separated by coma.", "} elseif (getDolGlobalString(''CONTRACT_ALLOW_TO_LINK_FROM_OTHER_COMPANY'') != ''all'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_CAN_USE_THE_BUGGED_SELECT_COMPONENT', 'bool', NULL, 'fichinter', 'Opts into using a known-buggy select UI component in contract/intervention-related forms instead of the default one.', 'Checked in fichinter/card.php (2 occurrences), fichinter/card-rec.php (2 occurrences), ticket/card.php, and core/class/html.formticket.class.php; documented in core/class/html.formcontract.class.php:57.', 'Enabling it switches affected forms to use the bugged select component, per the explicit comment describing it as required to allow its use.', NULL, 0, 0, NULL, 1, 'd2e503d74e891d4635c72ceeab550f779bf9d1d887cb6b35a45505e0130b2d84', 'v2', '2026-07-24T06:41:12+00:00', '["*  To allow its use, you must set the constant CONTRACT_CAN_USE_THE_BUGGED_SELECT_COMPONENT.", "if (getDolGlobalString(\"CONTRACT_CAN_USE_THE_BUGGED_SELECT_COMPONENT\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_CREATE_FROM_INVOICE', 'string', NULL, 'compta', 'Enables an ''Add Contract'' action button on validated invoices, allowing a contract to be created directly from an invoice.', 'In compta/facture/card.php:6729, if this constant is truthy and the contract module is enabled and the invoice is validated, an ''AddContract'' link is printed (subject to $usercancreatecontract permission).', 'Enabling it adds a button on the invoice card letting users with contract-creation rights generate a new contract with this invoice as origin.', 'Boolean-like flag (truthy shows the Create Contract action).', 1, 0, NULL, 1, 'f079bded40a6b14878b849a63a265ac7aae5bfc912391ec293baca63acba1665', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/card.php:6729: if (getDolGlobalString(''CONTRACT_CREATE_FROM_INVOICE'')) {", "compta/facture/card.php:6730: if (isModEnabled(''contract'') && $object->status == Facture::STATUS_VALIDATED) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_DISABLE_AUTOSET_AS_CLIENT_ON_CONTRACT_VALIDATION', 'bool', NULL, 'contrat', 'Disables the automatic promotion of a thirdparty to ''customer'' status when a contract is validated.', 'In contrat/class/contrat.class.php:548, Contrat::validate() normally calls $this->thirdparty->setAsCustomer() when the thirdparty is not already a supplier ($this->thirdparty->fournisseur == 0); setting this constant truthy skips that automatic call.', 'Setting it prevents contract validation from automatically flagging the associated thirdparty as a customer, leaving the thirdparty''s customer status unchanged.', 'Boolean-like: truthy disables the automatic setAsCustomer() call during contract validation.', 0, 0, NULL, 1, '61739c4e7a4b70d1633cd1fac220967257b328a83e568b56924df022c4635aeb', 'v2', '2026-07-24T07:05:23+00:00', '["contrat/class/contrat.class.php:548|check|if (!getDolGlobalString(''CONTRACT_DISABLE_AUTOSET_AS_CLIENT_ON_CONTRACT_VALIDATION'') && $this->thirdparty->fournisseur == 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_DRAFT_WATERMARK', 'string', NULL, 'admin', 'Watermark text printed on draft contract PDF documents.', 'Set via admin/contract.php:159 (dolibarr_set_const with trim($draft)) and displayed in a text input at admin/contract.php:529; used in core/modules/contract/doc/pdf_strato.modules.php:167/168 to set the PDF watermark when the contract status is draft.', 'When set, its text is shown as a watermark on draft contract PDFs generated with the strato model; when empty, no watermark check passes.', NULL, 0, 0, 'admin/contract.php|admin/contract.php', 1, 'cdd56e294136a43bab46147a63261643c5677a48be8f3de1cc75366d86e18a8d', 'v2', '2026-07-24T06:41:12+00:00', '["if ($object->status == $object::STATUS_DRAFT && (getDolGlobalString(''CONTRACT_DRAFT_WATERMARK''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_EXCLUDE_SERVICES_STATUS_FOR_INVOICE', 'string', NULL, 'compta', 'Specifies a comma-separated list of contract service statuses that are excluded when generating an invoice from a contract.', 'Read and conditionally set in compta/facture/card.php at lines 1922-1925. Defaults to ''5'' if not already set (line 1923). Service lines whose status matches any value in this list are skipped during invoice creation from a contract.', 'Changing this value alters which contract service lines are included or excluded when generating invoices from contracts.', 'Comma-separated integer statuses; defaults to ''5'' if not set. Lines with a status in this list are excluded from invoice generation.', 1, 0, NULL, 1, '348e9ca9ee61b04af53e23d6f0479f026e67e51fbeeddfc5dc7cf6439b07e8a0', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:1923|write|$conf->global->CONTRACT_EXCLUDE_SERVICES_STATUS_FOR_INVOICE = ''5'';", "compta/facture/card.php:1922|read|if (!isset($conf->global->CONTRACT_EXCLUDE_SERVICES_STATUS_FOR_INVOICE)) {", "compta/facture/card.php:1925|check|if ($srcobject->element == ''contrat'' && in_array($lines[$i]->statut, explode('','', getDolGlobalString(''CONTRACT_EXCLUDE_SERVICES_STATUS_FOR_INVOICE'')))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_FREE_TEXT', 'string', NULL, 'admin', 'Free text saved from the Contract module admin setup and printed in the footer of contract PDF/ODT documents.', 'Set via admin/contract.php:156 (dolibarr_set_const, action set from admin form) and read by PDF model core/modules/contract/doc/pdf_strato.modules.php:874 (pdf_pagefoot) and ODT model doc_generic_contract_odt.modules.php:352 as the free-text parameter name for contract documents.', 'Changing the value changes the free text block printed at the bottom of generated contract documents (PDF and ODT); it does not affect any other business logic.', 'Any HTML/restricted-HTML string entered by the admin (GETPOST uses ''restricthtml'' filter); empty means no free text.', 0, 0, 'admin/contract.php', 1, '206179d6e488b39a4637ae003fca47b1cd30b3ab4ac4a4b1dae734e9d9553ec9', 'v2', '2026-07-24T07:05:23+00:00', '["admin/contract.php:156|write|$res1 = dolibarr_set_const($db, \"CONTRACT_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);", "admin/contract.php:155: $freetext = GETPOST(''CONTRACT_FREE_TEXT'', ''restricthtml''); // No alpha here, we want exact string", "core/modules/contract/doc/pdf_strato.modules.php:874: return pdf_pagefoot($pdf, $outputlangs, ''CONTRACT_FREE_TEXT'', ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_CLOSED_SERVICES_BY_DEFAULT', 'bool', NULL, 'contrat', 'Hides closed service lines on the contract card by default unless the user explicitly requests to show them.', 'When enabled, contrat/card.php:1682 and 1953 skip rendering lines with STATUS_CLOSED unless the action is ''showclosedlines'', and contrat/card.php:2349 shows a reveal button when closed services exist. Configurable via admin/contract.php:162.', 'Enabling this constant causes closed service lines to be hidden by default on contract cards, reducing visual clutter; users can still reveal them via the ''showclosedlines'' action.', 'Non-empty/truthy = closed services hidden by default; empty/unset = all services shown.', 0, 0, 'admin/contract.php|admin/contract.php', 1, '9fb482ea6d439e08ee5dd83bc07fea372af8472e1c1b839ed10e69a85234531a', 'v2', '2026-04-21T11:16:15+00:00', '["admin/contract.php:162|write|$res3 = dolibarr_set_const($db, \"CONTRACT_HIDE_CLOSED_SERVICES_BY_DEFAULT\", $value, ''chaine'', 0, '''', $conf->entity);", "contrat/card.php:1682|check|if (getDolGlobalString(''CONTRACT_HIDE_CLOSED_SERVICES_BY_DEFAULT'') && $objp->statut == ContratLigne::STATUS_CLOSED && $action != ''showclosedlines'') {", "contrat/card.php:1953|check|if (getDolGlobalString(''CONTRACT_HIDE_CLOSED_SERVICES_BY_DEFAULT'') && $object->lines[$cursorline - 1]->statut == ContratLigne::STATUS_CLOSED && $action != ''showclosedlines'') {", "contrat/card.php:2349|check|if (getDolGlobalString(''CONTRACT_HIDE_CLOSED_SERVICES_BY_DEFAULT'') && $object->nbofservicesclosed > 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_CLOSED_SERVICES_IN_GRAPH', 'bool', NULL, 'contrat', 'Hides the closed-services (status 5) series from the contract statistics graph on the contract index page.', 'Read in contrat/index.php:197, where the code builds $listofstatus for the graph and by default adds status 5 (closed) unless this constant is set.', 'When enabled, the closed-contract-lines count is excluded from the statistics graph shown on the contract module home page; when disabled/unset, closed services are included in the graph.', 'Boolean-like: any truthy value hides status 5 (closed) from the graph series; unset/false shows it.', 1, 0, NULL, 1, '34c71048865c45184dbcc8423ac6c580b9fa9fb0d1e643a6e9cee619e3cdafa2', 'v2', '2026-07-24T07:05:23+00:00', '["contrat/index.php:196: $listofstatus = array(0, 4, 4); // Note: status 5=closed is useless as it increase all the time.", "contrat/index.php:197: if (!getDolGlobalString(''CONTRACT_HIDE_CLOSED_SERVICES_IN_GRAPH'')) { $listofstatus[] = 5; // We add this status too (even if useless"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_MYCOMPANY_SIGNATURE_SECTION_PDF', 'bool', NULL, 'core', 'Hides the ''my company'' (issuer) signature box in the tabSignature section of the contract PDF (strato model).', 'Checked in core/modules/contract/doc/pdf_strato.modules.php:617 (negated), inside protected function tabSignature(); when unset (default), draws the issuer''s name and a rounded signature rectangle on the left half.', 'Enabling it removes the issuer/company signature block from the generated contract PDF''s signature section.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, '93159e345287d49f2fd574d4e4668243bec14ad5c491ef010548460565c08472', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:617: if (!getDolGlobalString(''CONTRACT_HIDE_MYCOMPANY_SIGNATURE_SECTION_PDF'')) {", "core/modules/contract/doc/pdf_strato.modules.php:618: $pdf->SetXY($this->marge_gauche, $posy);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_PLANNED_DATE_ON_PDF', 'bool', NULL, 'core', 'Hides the planned start/end date line from each contract service description printed on the contract PDF (strato model).', 'Checked in core/modules/contract/doc/pdf_strato.modules.php:375 (negated), in the same $txt-building loop as the other CONTRACT_HIDE_*_ON_PDF constants.', 'Enabling it removes the DateStartPlanned/DateEndPlanned text from the generated contract PDF line descriptions.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, '0e5d963da02108e0ee9bd3275bc3b094945665d417a3a2eca21d252696ef2fd4', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:375: if (!getDolGlobalString(''CONTRACT_HIDE_PLANNED_DATE_ON_PDF'')) {", "core/modules/contract/doc/pdf_strato.modules.php:377: $txt .= $outputlangs->transnoentities(\"DateStartPlannedShort\").\" : <strong>\".$datei.\"</strong> - \".$outputlangs->transnoentities(\"DateEndPlanned\").\" : <strong>\".$datee.''</strong>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_PRICE_ON_PDF', 'bool', NULL, 'core', 'Hides the unit price line from each contract service description printed on the contract PDF (strato model).', 'Checked in core/modules/contract/doc/pdf_strato.modules.php:372 (negated), in the same $txt-building loop as CONTRACT_HIDE_QTY_ON_PDF.', 'Enabling it removes the UnitPrice text from the generated contract PDF line descriptions.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, '33d01dbe18b9215efb732cb52202a925aa4019ac7190ade49fe83f94fb910f70', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:372: if (!getDolGlobalString(''CONTRACT_HIDE_PRICE_ON_PDF'')) {", "core/modules/contract/doc/pdf_strato.modules.php:373: $txt .= '' - '' . $outputlangs->transnoentities(\"UnitPrice\") . '' : <strong>'' . price($objectligne->subprice) . ''</strong>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_QTY_ON_PDF', 'bool', NULL, 'core', 'Hides the quantity line (''Quantity : X'') from each contract service description printed on the contract PDF (strato model).', 'Checked in core/modules/contract/doc/pdf_strato.modules.php:369 (negated), inside the loop building $txt for each contract line''s description block.', 'Enabling it removes the Quantity text from the generated contract PDF line descriptions.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, 'a5dd76b78654faa625eab9b56fad017d0186d04cb8952cdc33229e18117c411b', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:369: if (!getDolGlobalString(''CONTRACT_HIDE_QTY_ON_PDF'')) {", "core/modules/contract/doc/pdf_strato.modules.php:370: $txt .= $outputlangs->transnoentities(\"Quantity\") . '' : <strong>'' . $objectligne->qty . ''</strong>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_REAL_DATE_ON_PDF', 'bool', NULL, 'core', 'Hides the real (actual) start/end date line from each contract service description printed on the contract PDF (strato model).', 'Checked in core/modules/contract/doc/pdf_strato.modules.php:379 (negated), in the same $txt-building loop as the other CONTRACT_HIDE_*_ON_PDF constants.', 'Enabling it removes the DateStartReal/DateEndReal text from the generated contract PDF line descriptions.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, 'c620bf247fafa585b1ccfd5ea47efb3b1768397092b7390fe5dffe013576c64b', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:379: if (!getDolGlobalString(''CONTRACT_HIDE_REAL_DATE_ON_PDF'')) {", "core/modules/contract/doc/pdf_strato.modules.php:381: $txt .= $outputlangs->transnoentities(\"DateStartRealShort\").\" : <strong>\".$daters.''</strong>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_THIRPARTY_SIGNATURE_SECTION_PDF', 'bool', NULL, 'core', 'Hides the thirdparty (recipient) signature box in the tabSignature section of the contract PDF (strato model).', 'Checked in core/modules/contract/doc/pdf_strato.modules.php:625 (negated, combined with is_object($this->recipient)); when unset (default) draws the recipient''s name and signature area on the right half.', 'Enabling it removes the recipient/thirdparty signature block from the generated contract PDF''s signature section.', 'Boolean-like (truthy/falsy). Note: constant name contains a typo ''THIRPARTY'' (missing D) which is preserved verbatim as it appears in code.', 1, 0, NULL, 1, '167614528eeab634677699119f5a10fe47853e8cc0459623fa896c7dd6e82d2a', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:625: if (!getDolGlobalString(''CONTRACT_HIDE_THIRPARTY_SIGNATURE_SECTION_PDF'') && is_object($this->recipient)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_HIDE_UNSELECTABLES', 'bool', NULL, 'core', 'When enabled, hides non-selectable (already linked or ineligible) contracts from the contract combo list.', 'Checked in core/class/html.formcontract.class.php:75 inside select_contract(), a function whose own docblock (lines 56-58) warns it downloads all contracts into the select and can hang the browser on a large database.', 'Setting it true removes ineligible contracts from the dropdown instead of showing them disabled/greyed; the underlying performance issue of the function itself is unrelated to this flag.', 'Boolean: true/1 hides unselectable contracts from the list.', 0, 0, NULL, 1, 'df24d79c9686060345442ec0c1be855bcc53d38f9e6f3913fee17398eaedc4b8', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formcontract.class.php:75|check|if (getDolGlobalString(''CONTRACT_HIDE_UNSELECTABLES'')) {", "core/class/html.formcontract.class.php: TODO This is a bugged function. It downloads all contracts into the select hanging the browser on large database."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_MAGRE_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the ''magre'' contract numbering module.', 'Read in core/modules/contract/mod_contract_magre.php:81 (UI display) and :129 (mask application). The mask string is used to generate contract reference numbers according to the Magre pattern.', 'Changing this mask alters the format of automatically generated contract reference numbers when the Magre module is active.', 'Mask string (e.g. ''{YYYY}{MM}{DD}-{####}'')', 1, 0, NULL, 1, '18d864914bf40f52c1c0d124bb363bac094804a46cfdac9f0bff06b9776c840b', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/contract/mod_contract_magre.php:81|read|$texte .= ''<td class=\"right\">''.$form->textwithpicto(''<input type=\"text\" class=\"flat minwidth175\" name=\"maskcontract\" value=\"''.getDolGlobalString(\"CONTRACT_MAGRE_MASK\").''\">'', $toolt", "core/modules/contract/mod_contract_magre.php:129|read|$mask = getDolGlobalString(\"CONTRACT_MAGRE_MASK\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_NEW_CONTRACT_ON_RENEWAL', 'string', NULL, 'comm', 'When generating a new proposal from a contract renewal, controls whether the origin link to the source contract is preserved.', 'Checked in comm/propal/card.php:629 with the comment ''If this is a renewal proposal for a contract, we might choose to systematically create a new contract''; when unset (and not a true renewal), the code sets $object->origin/$object->origin_id and records the linked object.', 'If truthy (and the request is a contract renewal), the origin/linked-object assignment is skipped, effectively decoupling the new proposal from the originating contract link in that branch.', 'Boolean-like (int via getDolGlobalInt).', 1, 0, NULL, 1, 'ab963f9df4969217e80f67c70fd1e0d0d3983fdeb297abcc2a3377116e13b440', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:628: // If this is a renewal proposal for a contract, we might choose to systematically create a new contract,", "comm/propal/card.php:629: if (($origin != ''contrat'' || $renewal != ''true'') && !getDolGlobalInt(''CONTRACT_NEW_CONTRACT_ON_RENEWAL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_ONLINE_SIGNATURE_SECURITY_TOKEN', 'string', NULL, 'core', 'Seed/salt value used to compute the secure key for the contract online signature feature.', 'Read in core/lib/signature.lib.php:146, public/onlinesign/newonlinesign.php:152, and core/ajax/onlineSign.php:91, each with a fallback to $defaultsalt when unset.', 'Its value is used as a seed to derive the secure key protecting online signature links; if unset, a default salt is used instead.', NULL, 1, 0, NULL, 1, '3d2bad64358741d78a559fb5dac281043ee5753ea105479b99aa76e10a703af5', 'v2', '2026-07-24T06:41:12+00:00', '["$securekeyseed = getDolGlobalString(''CONTRACT_ONLINE_SIGNATURE_SECURITY_TOKEN'', $defaultsalt);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_SHOW_SIGNATURE_STATUS_WITH_SERVICE_STATUS', 'bool', NULL, 'contrat', 'When enabled, displays the contract signature status alongside the service status on contract pages.', 'Checked in contrat/card.php:2358 and contrat/class/contrat.class.php:2007 to conditionally render signature status information. No admin UI write is present; two occurrences across two files.', 'Enabling this constant causes signature status to be shown together with service status on the contract card and in related class logic.', 'Boolean flag; unset or 0 = signature status not shown with service status; any truthy value = shown.', 1, 0, NULL, 1, 'b34223b08db1de7e338cb3486a16d895bebd38e51e87e3675a57fc1ccd2831e2', 'v2', '2026-04-21T11:16:15+00:00', '["contrat/card.php:2358|check|if (getDolGlobalString(''CONTRACT_SHOW_SIGNATURE_STATUS_WITH_SERVICE_STATUS'') && $object->status > Contrat::STATUS_DRAFT) {", "contrat/class/contrat.class.php:2007|check|if (getDolGlobalString(''CONTRACT_SHOW_SIGNATURE_STATUS_WITH_SERVICE_STATUS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_SHOW_TOTAL_OF_PRODUCT_AS_PRICE', 'bool', NULL, 'contrat', 'Controls whether the linked-object block for a contract shows a computed total price, which is hidden by default because a contract''s price is considered meaningless.', 'Checked in contrat/tpl/linkedobjectblock.tpl.php:75; a code comment (lines 72-74) explains price of a contract is not shown by default since a contract lists services with start/end dates that don''t map to a fixed reference period, and real prices live on the invoices tied to the contract.', 'When set, the linked-object block computes and displays the sum of total_ht of the contract''s lines as a price column; when unset (default) that price cell is left blank.', 'Not set/falsy (default): total price not shown. Truthy: total price of contract lines is displayed.', 1, 0, NULL, 1, '90aa60f8b8a8797d4fb2ed7d901c4333d5cc79ed21ca49972aa1d028657d77f7', 'v2', '2026-07-24T07:05:23+00:00', '["contrat/tpl/linkedobjectblock.tpl.php:72-74|comment|// Price of contract is not shown by default because a contract is a list of service with start and end date that change with time...", "contrat/tpl/linkedobjectblock.tpl.php:75|check|if ($user->hasRight(''contrat'', ''lire'') && !getDolGlobalString(''CONTRACT_SHOW_TOTAL_OF_PRODUCT_AS_PRICE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_SIGNATURE_ON_ALL_PAGES', 'string', NULL, 'core', 'Stamps the online-signature image on every page of the contract PDF instead of only the last page.', 'Mirrors PROPAL_SIGNATURE_ON_ALL_PAGES for contracts: read in core/ajax/onlineSign.php:417 (per-page loop, contract signing branch) and line 446 (fallback: if unset, signature is added once, on the last page).', 'When set, dolPrintSignatureImage() is called for every page of the contract PDF; when unset, the signature is placed only once, on the last processed page.', 'Truthy string = stamp signature on all pages; empty/unset = stamp once, on the last page.', 1, 0, NULL, 1, '1d64bf04e5d4ddabbf28d207f2c5c62af78eeef492bd93d95dc9859e6c8b1182', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:417: if (getDolGlobalString(\"CONTRACT_SIGNATURE_ON_ALL_PAGES\")) { // A signature image file is 720 x 180 ...", "core/ajax/onlineSign.php:446: if (!getDolGlobalString(\"CONTRACT_SIGNATURE_ON_ALL_PAGES\")) { // A signature image file is 720 x 180 ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_SIGNATURE_WFORIMG', 'string', NULL, 'core', 'Overrides the width, in PDF units, of the online-signature image stamped on contract PDFs.', 'Read in core/ajax/onlineSign.php:431-432, used as $param[''wforimg''] passed to dolPrintSignatureImage(); if unset, defaults to the remaining horizontal space (page width - (xforimgstart + 16)).', 'Setting a value forces the signature image on contract PDFs to a specific width; leaving it unset scales it to fill the remaining space to the right margin.', 'Numeric value = explicit width; unset = computed default ($s[''w''] - ($param[''xforimgstart''] + 16)).', 1, 0, NULL, 1, '2ed27591667442ba3f5ef9509ab9747a6490c1e8702eecdf17d679cbd64aabe4', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:431-434: if (getDolGlobalString(\"CONTRACT_SIGNATURE_WFORIMG\")) { $param[''wforimg''] = getDolGlobalString(...); } else { $param[''wforimg''] = $s[''w''] - ($param[''xforimgstart''] + 16); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_SIGNATURE_XFORIMGSTART', 'string', NULL, 'core', 'Overrides the horizontal (X) start position, in PDF units, of the online-signature image stamped on contract PDFs.', 'Read in core/ajax/onlineSign.php:421-422, used as $param[''xforimgstart''] passed to dolPrintSignatureImage(); if unset, defaults to (page width / 2), or 110 if width is unknown.', 'Setting a value repositions the signature image horizontally on the contract PDF page; leaving it unset uses the computed default based on the page''s width.', 'Numeric value = explicit X start coordinate; unset = computed default ($s[''w''] / 2 - 0, or 110 if page width unknown).', 1, 0, NULL, 1, '6f3b6f1203f39912df688085bb6fbaad9fbf9d40ae1e2462e2553b73d8cde1c3', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:421-424: if (getDolGlobalString(\"CONTRACT_SIGNATURE_XFORIMGSTART\")) { $param[''xforimgstart''] = getDolGlobalString(...); } else { $param[''xforimgstart''] = (empty($s[''w'']) ? 110 : $s[''w''] / 2 - 0); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_SIGNATURE_YFORIMGSTART', 'string', NULL, 'core', 'Overrides the vertical (Y) start position, in PDF units, of the online-signature image stamped on contract PDFs.', 'Read in core/ajax/onlineSign.php:426-427, used as $param[''yforimgstart''] passed to dolPrintSignatureImage(); if unset, defaults to (page height - 62), or 250 if height is unknown.', 'Setting a value repositions the signature image vertically on the contract PDF page; leaving it unset uses the computed default based on the page''s height.', 'Numeric value = explicit Y start coordinate; unset = computed default ($s[''h''] - 62, or 250 if page height unknown).', 1, 0, NULL, 1, '586bf647f232aaae668a3fd903f012101ea61b8bbca5302d42ffdaabe47a5db4', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:426-429: if (getDolGlobalString(\"CONTRACT_SIGNATURE_YFORIMGSTART\")) { $param[''yforimgstart''] = getDolGlobalString(...); } else { $param[''yforimgstart''] = (empty($s[''h'']) ? 250 : $s[''h''] - 62); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_SUPPORT_PRODUCTS', 'string', NULL, 'core', 'Enables product (type=0) lines in addition to services on contracts.', 'By default, contracts only allow service-type lines (product_type=1). When this constant is set, contrat/card.php:368 also accepts product_type=0, and core/tpl/objectline_create.tpl.php:287 and 1353 adjust their filtering accordingly. Also affects mailing module eligibility at core/modules/mailings/thirdparties_services_expired.modules.php:73. No admin UI is provided.', 'Enabling this constant allows physical products to be added as lines on contracts; disabling it restricts contracts to services only.', 'Non-empty/truthy = products allowed on contracts; empty/unset = only services allowed.', 1, 0, NULL, 1, '25613e7c1d422cd069b7dab3158fbc8be006a8da30beae2b115d26b2b28fd25b', 'v2', '2026-04-21T11:16:15+00:00', '["contrat/card.php:368|check|if ($product_type == 1 || (getDolGlobalString(''CONTRACT_SUPPORT_PRODUCTS'') && in_array($product_type, array(0, 1)))) { \t// TODO Exclude also deee", "core/tpl/objectline_create.tpl.php:287|check|if (!empty($object->element) && $object->element == ''contrat'' && !getDolGlobalString(''CONTRACT_SUPPORT_PRODUCTS'')) {", "contrat/card.php:1353|check|if (!getDolGlobalString(''CONTRACT_SUPPORT_PRODUCTS'')) {", "core/modules/mailings/thirdparties_services_expired.modules.php:73|check|if (!getDolGlobalString(''CONTRACT_SUPPORT_PRODUCTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONTRACT_SYNC_PLANNED_DATE_OF_SERVICES', 'string', NULL, 'contrat', 'When enabled, changing the planned start or end date of one contract service line propagates that same planned date to all other service lines of the same contract.', 'Checked in contrat/class/contratligne.class.php:727; a dol_syslog debug message at line 728 confirms the intent (''...is on so we update date for all lines''), and the following code (lines 730+) runs an UPDATE on contratdet setting date_ouverture_prevue for all lines of the contract when date_start changed.', 'When set, editing the planned date of one line on a contract cascades that date to every other line on the same contract; when unset, planned dates of other lines are left untouched.', 'Not set/falsy (default): only the edited line''s planned date changes. Truthy: planned date change syncs across all lines of the contract.', 1, 0, NULL, 1, '7faca850ac0fa80043b2a56c186a0eae341d5f6fc15f77f75d7ea9894a812368', 'v2', '2026-07-24T07:05:23+00:00', '["contrat/class/contratligne.class.php:727|check|if (!$error && getDolGlobalString(''CONTRACT_SYNC_PLANNED_DATE_OF_SERVICES'')) {", "contrat/class/contratligne.class.php:728|log|dol_syslog(get_class($this).\"::update CONTRACT_SYNC_PLANNED_DATE_OF_SERVICES is on so we update date for all lines\", LOG_DEBUG);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CONVERT_TO_WORD_FR', 'string', NULL, 'core', 'Selects the French number-to-words spelling convention used when converting amounts to words.', 'Read once in core/lib/functionsnumtoword.lib.php:321, documented at line 318 as configurable via Home - Setup - Other setup.', 'When set to the exact value ''REFORME1990'', the 1990 French spelling reform convention is used ($reform = true); otherwise the standard convention applies.', 'REFORME1990 = use the 1990 spelling reform convention', 0, 0, NULL, 1, '0c2ea4a25c9e4af03f007169350f6d17e7124a0b8e2c4334de6734eb1603dcfa', 'v2', '2026-07-24T06:41:12+00:00', '["// Spelling convention, set with constant CONVERT_TO_WORD_FR (Home - Setup - Other setup):", "$reform = (getDolGlobalString(''CONVERT_TO_WORD_FR'') === ''REFORME1990'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CREATE_NEW_SALARY_WITHOUT_AUTO_PAYMENT', 'string', NULL, 'salaries', 'Default state (checked/unchecked) of the ''auto_create_paiement'' option when creating a new salary payment record.', 'Read in salaries/card.php:77 as the negation used to initialize $auto_create_paiement, only when the form field itself was not posted and action is not ''add''.', 'When set, new salary records default to NOT auto-creating an associated payment; when unset, the default is to auto-create the payment (the user can still override via the ''auto_create_paiement'' form field).', 'Bool: truthy disables auto-creation of the payment by default when adding a new salary.', 1, 0, NULL, 1, '86af31f8d439b6673f03018bde2f97552c8ec16fd83f0c61ec77b82af946689b', 'v2', '2026-07-24T07:05:23+00:00', '["salaries/card.php:77|read|$auto_create_paiement = !getDolGlobalString(''CREATE_NEW_SALARY_WITHOUT_AUTO_PAYMENT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CREATE_NEW_VAT_WITHOUT_AUTO_PAYMENT', 'string', NULL, 'compta', 'Controls whether creating a new VAT (TVA) declaration automatically also creates its payment.', 'Read in compta/tva/card.php:68 as the inverse default for $auto_create_payment when the ''auto_create_paiement'' POST field is not explicitly set; also exposed in the admin UI at admin/taxes.php:212 via ajax_constantonoff(''CREATE_NEW_VAT_WITHOUT_AUTO_PAYMENT'').', 'Enabling it makes new VAT declarations created without auto-payment by default (the user must record the payment separately); leaving it disabled keeps the default behavior of auto-creating the payment alongside the VAT record.', 'Boolean-like: truthy disables automatic payment creation on new VAT declarations (via ajax on/off toggle in admin/taxes.php).', 0, 0, NULL, 1, '57e3fce65d0f269150d553a67cb347b82646b91bb7e1066ef899f84ed8a0af70', 'v2', '2026-07-24T07:05:23+00:00', '["compta/tva/card.php:68|read|$auto_create_payment = !getDolGlobalString(''CREATE_NEW_VAT_WITHOUT_AUTO_PAYMENT'');", "admin/taxes.php:212|$key = ''CREATE_NEW_VAT_WITHOUT_AUTO_PAYMENT''; print ''<tr><td>''.$langs->trans($key).''</td><td>''.ajax_constantonoff($key).''</td></tr>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CREDITTRANSFER_USTRD', 'string', NULL, 'compta', 'Overrides the free-text ''Ustrd'' (unstructured remittance information) field in generated SEPA credit-transfer XML.', 'Has an admin UI write in admin/paymentbybanktransfer.php:205 (currently inside a commented-out `/* ... */` block) and is read in compta/prelevement/class/bonprelevement.class.php:2623, falling back to an auto-built string from the invoice ref/comment if unset.', 'When set, the value replaces the auto-generated remittance text (invoice ref + comment, truncated to 135 chars) in the SEPA XML Ustrd element sent to the bank.', 'String, max 140 chars per ISO20022 comment (''A string with some information on payment - 140 max'').', 0, 0, 'admin/paymentbybanktransfer.php', 1, '91abd4eb666c7a73d13c8448a31949e02bd821d4e9e111f65fb24f9284e49d25', 'v2', '2026-07-24T07:05:23+00:00', '["admin/paymentbybanktransfer.php:205|read|print ''<input type=\"text\" name=\"CREDITTRANSFER_USTRD\" value=\"''.$conf->global->CREDITTRANSFER_USTRD.''\" class=\"width100\"></td>'';", "compta/prelevement/class/bonprelevement.class.php:2622|read|// A string with some information on payment - 140 max", "compta/prelevement/class/bonprelevement.class.php:2623|read|<Ustrd>'' . getDolGlobalString(''CREDITTRANSFER_USTRD'', dolEscapeXML(dol_trunc(...))) . ''</Ustrd>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CRON_DISABLE_KEY_CHANGE', 'bool', NULL, 'cron', 'Controls whether the cron security key (CRON_KEY) can be modified or refreshed via the admin UI.', 'Checked at cron/admin/cron.php:103-129; value 1 prevents modification, value -1 hides the refresh button, value 0 allows full key management. Comment at line 99 states: ''Security key for cron (if CRON_DISABLE_KEY_CHANGE is 1: modification is not allowed, -1: no button refresh)''.', 'Setting this to 1 locks the cron key and prevents admin changes; setting it to -1 hides the key refresh button; 0 or unset allows full key management.', '1 = modification not allowed; -1 = no refresh button shown; 0 or unset = full key management allowed.', 0, 0, 'cron/admin/cron.php|cron/admin/cron.php|cron/admin/cron.php|cron/admin/cron.php|cron/admin/cron.php', 1, '917d97f53d951316c14f816e47e22b9eaa65a2d873f1df9808b32a5d816d8cad', 'v2', '2026-04-21T11:16:15+00:00', '["cron/admin/cron.php:99  // Security key for cron (if CRON_DISABLE_KEY_CHANGE is 1: modification is not allowed, -1: no button refresh)", "cron/admin/cron.php:103|check|if (getDolGlobalInt(''CRON_DISABLE_KEY_CHANGE'') > 0) {", "cron/admin/cron.php:107|check|if (getDolGlobalInt(''CRON_DISABLE_KEY_CHANGE'') != 1) {", "cron/admin/cron.php:113|read|} elseif (getDolGlobalInt(''CRON_DISABLE_KEY_CHANGE'') == -1) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CRON_DISABLE_TUTORIAL_CRON', 'bool', NULL, 'core', 'Hides the OS-specific (Linux/Windows/Mac) tutorial/help note shown on the cron job list page explaining how to schedule the cron runner script.', 'Checked in core/lib/cron.lib.php:143; when falsy, additional explanatory text (branching on PHP_OS to detect Linux-like vs Windows/Mac) is printed after showing the cron_run_jobs.php command line.', 'Enabling it suppresses the extra tutorial/help text block on the cron admin page; it does not affect actual cron job execution, only the displayed documentation.', 'Boolean: truthy value disables display of the cron setup tutorial note.', 1, 0, NULL, 1, 'a00c5f381f9aa4d31dccea7b3873e0985cc3cab78f1c3e8e840e1b89fa444702', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/cron.lib.php:143|check|if (!getDolGlobalString(''CRON_DISABLE_TUTORIAL_CRON'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CRON_KEY', 'string', NULL, 'cron', 'Security key required to trigger cron job execution via URL without being logged in.', 'Set via cron/admin/cron.php:57 (dolibarr_set_const), displayed/read at cron/admin/cron.php:106/119, and checked against a provided key in public/cron/cron_run_jobs_by_url.php:103, cron/card.php:108, and cron/list.php:211.', 'If set, the provided security key must match this value to run cron jobs by URL or to access certain cron actions; if it does not match, the action is refused.', NULL, 0, 0, 'cron/admin/cron.php|cron/admin/cron.php|cron/admin/cron.php', 1, '4a1d894e6f869b067a7af9b779cd56cb3dd848f553105a1ad09a7aa4d43c2440', 'v2', '2026-07-24T06:41:12+00:00', '["if ($key != getDolGlobalString(''CRON_KEY'')) {", "if (getDolGlobalString(''CRON_KEY'') && getDolGlobalString(''CRON_KEY'') != $securitykey) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CRON_MAX_DELAY_FOR_JOBS', 'string', NULL, 'public', 'Sets the maximum age (in hours) of the last-run timestamp used to select cron jobs eligible to run via the public URL runner.', 'Used in public/cron/cron_run_jobs_by_url.php:148, in a SQL WHERE clause comparing datelastrun against now minus this many hours (default 24).', 'Increasing the value widens the time window during which a job is still considered due to run; decreasing it narrows the window, potentially skipping jobs whose last run is older than the delay allows for this URL-triggered execution path.', 'Integer, number of hours; default 24 when unset (getDolGlobalInt(''CRON_MAX_DELAY_FOR_JOBS'', 24)).', 1, 0, NULL, 1, 'bd75f8a5b06eac565c4f3d295a6d209096570a2deac4b2585bed03cdfe01c81c', 'v2', '2026-07-24T07:05:23+00:00', '["public/cron/cron_run_jobs_by_url.php:148: $sql .= \" AND datelastrun <= ''\".$db->idate(dol_now() - getDolGlobalInt(''CRON_MAX_DELAY_FOR_JOBS'', 24) * 3600, ''gmt'').\"''\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('CRON_WARNING_DELAY_HOURS', 'string', NULL, 'cron', 'Sets the number of hours after which a delayed cron job triggers a warning.', 'When set, cron/admin/cron.php:140 displays an admin info message and cron/list.php:511 appends a warning text referencing the configured delay hours value. Configurable via cron/admin/cron.php.', 'Setting this constant causes warnings to appear in the cron admin and list pages when jobs are delayed beyond the specified number of hours.', 'A positive integer representing hours; empty/unset = no delay warning shown.', 0, 0, 'cron/admin/cron.php|cron/admin/cron.php', 1, '246843e564b89493fe98bcf02e4605208a0babf857164e03f4be521b230c5fac', 'v2', '2026-04-21T11:16:15+00:00', '["cron/admin/cron.php:139|check|if (getDolGlobalString(''CRON_WARNING_DELAY_HOURS'')) {", "cron/admin/cron.php:140|read|print info_admin($langs->trans(\"WarningCronDelayed\", getDolGlobalString(''CRON_WARNING_DELAY_HOURS''))).''<br>'';", "cron/list.php:510|check|if (getDolGlobalString(''CRON_WARNING_DELAY_HOURS'')) {", "cron/list.php:511|read|$text .= $langs->trans(\"WarningCronDelayed\", getDolGlobalString(''CRON_WARNING_DELAY_HOURS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DATABASE_PWD_ENCRYPTED', 'string', NULL, 'admin', 'Indicates whether database-stored passwords (e.g. user/member passwords) are encrypted rather than stored in clear text; shared across all entities.', 'Set (entity=0, i.e. shared) or removed via admin/security.php:74/71/118/119 (dolibarr_set_const/dolibarr_del_const), checked at admin/security.php:418/422 and admin/system/security.php:562/560, and referenced in adherents/class/adherent.class.php:83 and user/class/user.class.php:203 docblocks for the clear-password field.', 'When enabled, passwords are stored encrypted; the ''Clear password in database'' field is only defined/used when this is 0 (disabled). It is deliberately shared across all entities (entity=0) rather than per-entity.', '0 = passwords stored in clear text (clear password field defined); non-zero/set = passwords encrypted', 0, 0, 'admin/security.php|admin/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/security.php|admin/security.php|admin/security.php|admin/security.php', 1, 'a123d29bf3054195b88939f297cf4fdd7f25af4c784595f7a6a6190490c37a90', 'v2', '2026-07-24T06:41:12+00:00', '["// We set entity=0 (all) because DATABASE_PWD_ENCRYPTED is a setup into conf file, so always shared for everybody", "* @var string Clear password in database (defined if DATABASE_PWD_ENCRYPTED=0)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DATE_LIVRAISON_WEEK_DELAY', 'string', NULL, 'supplier_proposal', 'Sets the default delivery date as a number of weeks from today when creating a proposal.', 'Checked via `is_numeric()` in supplier_proposal/card.php:1635 and comm/propal/card.php:2520. When numeric, the delivery date is computed as `time() + (7 * getDolGlobalInt(''DATE_LIVRAISON_WEEK_DELAY'') * 24 * 60 * 60)` (supplier_proposal/card.php:1636 and comm/propal/card.php:2521).', 'Setting this to an integer pre-fills the delivery date field with today plus the specified number of weeks; setting to 0 pre-fills today''s date.', 'Integer (number of weeks); 0 = today; positive integer = N weeks from today; empty/not numeric = no default delivery date.', 1, 0, NULL, 1, '49f8fd289eb12b93f403f108d6db761e38dff960378175f8edbfcef1b3d9fc20', 'v2', '2026-04-21T11:16:15+00:00', '["supplier_proposal/card.php:1635|check|if (is_numeric(getDolGlobalString(''DATE_LIVRAISON_WEEK_DELAY''))) {\t// If value set to 0 or a num, not empty", "supplier_proposal/card.php:1636|read|$tmpdte = time() + (7 * getDolGlobalInt(''DATE_LIVRAISON_WEEK_DELAY'') * 24 * 60 * 60);", "comm/propal/card.php:2520|check|if (is_numeric(getDolGlobalString(''DATE_LIVRAISON_WEEK_DELAY''))) {\t// If value set to 0 or a num, not empty", "comm/propal/card.php:2521|read|$tmpdte = time() + (7 * getDolGlobalInt(''DATE_LIVRAISON_WEEK_DELAY'') * 24 * 60 * 60);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DAV_ALLOW_ECM_DIR', 'bool', NULL, 'dav', 'Exposes the ECM (Electronic Content/Document Management) directory as a browsable node on the WebDAV server, when the ECM module is enabled.', 'Used in dav/fileserver.php:205: `if (isModEnabled(''ecm'') && getDolGlobalString(''DAV_ALLOW_ECM_DIR'')) { $nodes[] = new \Sabre\DAV\FS\Directory($ecmDir); }`, alongside the always-present private dir and the DAV_ALLOW_PUBLIC_DIR-gated public dir.', 'When enabled (and the ECM module is active), WebDAV clients connecting to Dolibarr''s DAV server can browse/access the ECM directory tree in addition to the private directory.', 'Boolean (getDolGlobalString truthiness): truthy exposes the ECM directory over WebDAV (requires isModEnabled(''ecm'') too); falsy/unset keeps it hidden from DAV clients.', 1, 0, NULL, 1, '9216e631f6918198527a14ee675656163cd4791208b7d250712d2cf66bbfbd09', 'v2', '2026-07-24T07:05:23+00:00', '["dav/fileserver.php:205: if (isModEnabled(''ecm'') && getDolGlobalString(''DAV_ALLOW_ECM_DIR'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DAV_ALLOW_PUBLIC_DIR', 'bool', NULL, 'dav', 'Enables access to the public documents directory via the DAV file server.', 'Checked at dav/fileserver.php:199 and dav/fileserver.php:235 to grant access to the public directory; also checked at admin/dav.php:209 in the admin UI.', 'Enabling this allows DAV clients to browse and access public documents; disabling it blocks this directory from DAV access.', '0 or unset = public directory not accessible via DAV; 1 = accessible.', 0, 0, 'admin/dav.php', 1, 'eef785d4b56aade6b2465adc4983c04ca023107e63859a7ce64662b39a704828', 'v2', '2026-04-21T11:16:15+00:00', '["admin/dav.php:209|check|if (getDolGlobalString(''DAV_ALLOW_PUBLIC_DIR'')) {", "dav/fileserver.php:199|check|if (getDolGlobalString(''DAV_ALLOW_PUBLIC_DIR'')) {", "dav/fileserver.php:235|check|if ((!getDolGlobalString(''DAV_ALLOW_PUBLIC_DIR'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DAV_DISABLE_BROWSER', 'bool', NULL, 'dav', 'Disables the Sabre DAV HTML browser plugin, which otherwise lets users browse WebDAV directories from a normal web browser.', 'Used in dav/fileserver.php:248: `if (!getDolGlobalString(''DAV_DISABLE_BROWSER'')) { $browser = new \Sabre\DAV\Browser\Plugin(); $server->addPlugin($browser); }` — the browser plugin is added only when the constant is falsy.', 'When enabled (truthy), accessing the DAV endpoint with a regular web browser no longer shows Sabre''s built-in HTML directory listing/browser UI; WebDAV clients (e.g. mounting as a drive) are unaffected.', 'Boolean (getDolGlobalString truthiness): truthy disables the HTML DAV browser plugin; falsy/unset (default) keeps it enabled.', 1, 0, NULL, 1, '467c98e90017fb35adeb35cd549c35ab7bc3e113f5c412bdd06b7b2b1a4c427c', 'v2', '2026-07-24T07:05:23+00:00', '["dav/fileserver.php:248: if (!getDolGlobalString(''DAV_DISABLE_BROWSER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DAV_RESTRICT_ON_IP', 'string', NULL, 'dav', 'Restricts access to the DAV file server to a space-separated list of allowed IP addresses.', 'Checked at dav/fileserver.php:81; if set, the remote IP is compared against the space-delimited list (dav/fileserver.php:82) and access is denied with a syslog entry if not matched (dav/fileserver.php:85).', 'Setting this value limits DAV access to the listed IPs only; removing or leaving it empty disables IP-based access restriction.', 'Space-separated list of allowed IP addresses (e.g. ''192.168.1.1 10.0.0.5''); empty = no restriction.', 1, 0, NULL, 1, 'd39c50f086f96d643a988c3f695a9428e772ec44d7c1fa94f75f0ad0e2f10561', 'v2', '2026-04-21T11:16:15+00:00', '["dav/fileserver.php:81|check|if (getDolGlobalString(''DAV_RESTRICT_ON_IP'')) {", "dav/fileserver.php:82|read|$allowedip = explode('' '', getDolGlobalString(''DAV_RESTRICT_ON_IP''));", "dav/fileserver.php:85|read|dol_syslog(''Remote ip is ''.$ipremote.'', not into list '' . getDolGlobalString(''DAV_RESTRICT_ON_IP''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DEBUGBAR_LOGS_LINES_NUMBER', 'string', NULL, 'admin', 'Sets the maximum number of log lines loaded and displayed in the debug bar log collector.', 'Read in debugbar/class/DataCollector/DolLogsCollector.php:61 to set $this->maxnboflines (defaulting to 250). Written via admin/debugbar.php:59 and displayed with a default of ''250'' at admin/debugbar.php:113, which notes that a high number ''slows seriously output''.', 'Increasing this value loads more log lines in the debug bar but degrades page performance; decreasing it speeds up the debug bar display.', 'Positive integer. Default is 250.', 0, 0, 'admin/debugbar.php|admin/debugbar.php', 1, '7b84930bbf4573437e94503023bfe2753284c69b6bec1e0051490f537004dee1', 'v2', '2026-04-21T11:16:15+00:00', '["debugbar/class/DataCollector/DolLogsCollector.php:61|read|$this->maxnboflines = getDolGlobalInt(''DEBUGBAR_LOGS_LINES_NUMBER'', 250); // High number slows seriously output", "admin/debugbar.php:113|read|print ''<td><input type=\"text\" class=\"flat width75\" name=\"DEBUGBAR_LOGS_LINES_NUMBER\" value=\"''.getDolGlobalString(''DEBUGBAR_LOGS_LINES_NUMBER'', ''250'').''\">''; // This slow seriously o", "admin/debugbar.php:59|write|$result1 = dolibarr_set_const($db, \"DEBUGBAR_LOGS_LINES_NUMBER\", GETPOSTINT(''DEBUGBAR_LOGS_LINES_NUMBER''), ''chaine'', 0, '''', 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DEBUGBAR_USE_LOG_FILE', 'bool', NULL, 'admin', 'Enables reading log entries from the log file instead of the in-memory log buffer in the debug bar.', 'Read in debugbar/class/DataCollector/DolLogsCollector.php:102 as $uselogfile. Written via admin/debugbar.php:60 and rendered as a yes/no select at admin/debugbar.php:107.', 'Enabling this constant causes the debug bar log collector to source entries from the log file; disabling it uses the in-memory buffer.', '1 = use log file; 0 = use in-memory buffer.', 0, 0, 'admin/debugbar.php|admin/debugbar.php', 1, 'eaa29b8771cb960abb059ee28c297cf53ccb5c4855e7405e93f2b5b9af4b43f6', 'v2', '2026-04-21T11:16:15+00:00', '["debugbar/class/DataCollector/DolLogsCollector.php:102|read|$uselogfile =  getDolGlobalInt(''DEBUGBAR_USE_LOG_FILE'');", "admin/debugbar.php:60|write|$result2 = dolibarr_set_const($db, \"DEBUGBAR_USE_LOG_FILE\", GETPOSTINT(''DEBUGBAR_USE_LOG_FILE''), ''chaine'', 0, '''', 0);", "admin/debugbar.php:107|read|print $form->selectyesno(''DEBUGBAR_USE_LOG_FILE'', getDolGlobalString(''DEBUGBAR_USE_LOG_FILE''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DECREASE_ONLY_UNINVOICEDPRODUCTS', 'string', NULL, 'product', 'Restricts stock decrease compensation to orders that have not yet been invoiced.', 'Checked in product/class/product.class.php:3703. The comment at line 3704 states: ''If option DECREASE_ONLY_UNINVOICEDPRODUCTS is on, we make a compensation but only if order not yet invoice.'' Line 3735 states: ''If option DECREASE_ONLY_UNINVOICEDPRODUCTS is off, we make a compensation with lines of invoices linked to the order''.', 'When enabled, only uninvoiced orders are considered for stock compensation; when disabled, invoiced order lines are also included.', 'Truthy string (compensation limited to uninvoiced orders) or empty/unset (compensation includes invoiced orders).', 1, 0, NULL, 1, '9e71febb0f04b5a01eaf36e2f4e6be9a2c6701be2741e4984d7bdb5f5fc3d9b7', 'v2', '2026-04-21T13:29:58+00:00', '["product/class/product.class.php:3704  // If option DECREASE_ONLY_UNINVOICEDPRODUCTS is on, we make a compensation but only if order not yet invoice.", "product/class/product.class.php:3735  // If option DECREASE_ONLY_UNINVOICEDPRODUCTS is off, we make a compensation with lines of invoices linked to the order", "product/class/product.class.php:3703|check|if (getDolGlobalString(''DECREASE_ONLY_UNINVOICEDPRODUCTS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DEFAULT_SEARCH_INTO_MODULE', 'string', NULL, 'core', 'Specifies the default module to pre-select in the global search form when the page loads.', 'Read in core/ajax/selectsearchbox.php:211 where its value is concatenated as ''searchinto'' + value to identify the default search key; checked at line 210 to determine whether a default module override is configured.', 'Setting this causes the search box to default to a specific module''s search result set rather than the generic search.', 'A module suffix string matching the ''searchinto*'' key (e.g. ''invoice'', ''shipment''); empty/unset = no default override.', 1, 0, NULL, 1, '2f12e0285543a5b2384f5e776f49ee936d1068939ce2c5bfe69b53ddfdb3608f', 'v2', '2026-04-21T13:29:58+00:00', '["core/ajax/selectsearchbox.php:210|check|if (getDolGlobalString(''DEFAULT_SEARCH_INTO_MODULE'')) {", "core/ajax/selectsearchbox.php:211|read|$key = ''searchinto'' . getDolGlobalString(''DEFAULT_SEARCH_INTO_MODULE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DELIVERY_ADDON_NUMBER', 'string', NULL, 'admin', 'Name of the numbering module used to generate delivery (receipt) reference numbers.', 'Set via admin/delivery.php:194 (dolibarr_set_const), selected among candidates checked at admin/delivery.php:291, and used in delivery/class/delivery.class.php:425/427 to build the numbering module name.', 'Changing it switches which numbering module class is used to generate new delivery reference numbers.', NULL, 0, 0, 'admin/delivery.php|admin/delivery.php', 1, 'a2021c1d765f81ee986a6a2124ad11ade444f89cc2fede5e164d1e4b604e9172', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''DELIVERY_ADDON_NUMBER'')) {", "$modName = getDolGlobalString(''DELIVERY_ADDON_NUMBER'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DELIVERY_ADDON_PDF', 'string', NULL, 'admin', 'Specifies the PDF template module to use for generating delivery order documents.', 'Set via admin/delivery.php:177 and read by delivery/class/delivery.class.php:161 to assign the default PDF model for delivery objects. The admin UI at admin/delivery.php allows selecting among available PDF modules.', 'Changing this value switches the PDF layout used when generating delivery documents; if unset, no PDF model is pre-selected.', 'Name of the PDF module class (e.g. a string identifier matching a module file in the delivery modules directory).', 0, 0, 'admin/delivery.php|admin/delivery.php|admin/delivery.php|admin/delivery.php|admin/delivery.php', 1, '54492b4971e8608ea158668d02210848cb48bedb40b2079f0f07be555d57ebc1', 'v2', '2026-04-21T11:16:15+00:00', '["admin/delivery.php:177|write|if (dolibarr_set_const($db, \"DELIVERY_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "delivery/class/delivery.class.php:161|read|$this->model_pdf = getDolGlobalString(''DELIVERY_ADDON_PDF'');", "delivery/class/delivery.class.php:1151|read|$modele = getDolGlobalString(''DELIVERY_ADDON_PDF'');", "admin/delivery.php:433|check|if (getDolGlobalString(''DELIVERY_ADDON_PDF'') == \"$name\") {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DELIVERY_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated delivery receipt documents.', 'Written from admin/delivery.php:113 via dolibarr_set_const() when the admin saves the delivery receipt module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated delivery documents; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/delivery.php', 1, '39212012728fd4f131991352dc281f98cf25908a705b176c2991fab6c64332e5', 'v2', '2026-07-24T07:05:23+00:00', '["admin/delivery.php:113|write|$res = dolibarr_set_const($db, \"DELIVERY_FREE_TEXT\", $free, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DELIVERY_PDF_HIDE_QTYTOSHIP', 'bool', NULL, 'core', 'Hides the ''quantity remaining to ship'' column on the delivery PDF document.', 'Used in core/modules/delivery/doc/pdf_storm.modules.php:1002 to set the qty_remaining column''s visibility: `''status'' => !getDolGlobalString(''DELIVERY_PDF_HIDE_QTYTOSHIP''),` — the column is shown by default and hidden when this constant is truthy.', 'Setting this constant removes the ''Qty remaining to ship'' column from the delivery PDF layout; leaving it unset keeps the column visible (default behavior).', 'Truthy/falsy flag; truthy = hide the column (status becomes false).', 0, 0, NULL, 1, '25585bb8b9f9d191b631cdfc66f50056c15464fbefac019a747d9200b68e4de4', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/delivery/doc/pdf_storm.modules.php:1002|read|''status'' => !getDolGlobalString(''DELIVERY_PDF_HIDE_QTYTOSHIP''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DELIVERY_PDF_HIDE_SHIPPED', 'bool', NULL, 'core', 'Hides the ''quantity shipped'' column on the delivery PDF document.', 'Used in core/modules/delivery/doc/pdf_storm.modules.php:991 to set the qty_shipped column''s visibility: `''status'' => !getDolGlobalString(''DELIVERY_PDF_HIDE_SHIPPED''),` — the column is shown by default and hidden when this constant is truthy.', 'Setting this constant removes the ''Qty shipped'' column from the delivery PDF layout; leaving it unset keeps the column visible (default behavior).', 'Truthy/falsy flag; truthy = hide the column (status becomes false).', 0, 0, NULL, 1, '7c695231e9ed34f1651a1173ff69568ec7bff2684ec64162e80f35b04f445626', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/delivery/doc/pdf_storm.modules.php:991|read|''status'' => !getDolGlobalString(''DELIVERY_PDF_HIDE_SHIPPED''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DELIVERY_SAPHIR_MASK', 'string', NULL, 'core', 'Numbering mask used by the ''Saphir'' numbering module for delivery (shipment receipt) references.', 'Read/written by mod_delivery_saphir (core/modules/delivery/mod_delivery_saphir.php:95,148): shown in an admin setup form input and consumed by getNextValue() to compute the next delivery ref.', 'Changing the mask changes the format of future delivery references generated by this numbering module; existing refs are unaffected.', 'Free-form mask string using Dolibarr''s generic mask code syntax (GenericMaskCodes tooltip), same convention as other numbering-module masks.', 0, 0, NULL, 1, '6e396c07835aa1fc6a1f91c7365a046284b5738ee4338502f32691e1c0197e5f', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/delivery/mod_delivery_saphir.php:148|read|$mask = getDolGlobalString(''DELIVERY_SAPHIR_MASK'');", "core/modules/delivery/mod_delivery_saphir.php:95|read|...name=\"maskdelivery\" value=\"''.getDolGlobalString(''DELIVERY_SAPHIR_MASK'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DEPOSIT_CAN_BE_CONVERTED_AS_AVAILABLE_CREDIT_EVEN_IF_NOT_YET_PAID', 'string', NULL, 'compta', 'Hidden/unstable option allowing a down-payment invoice to be converted into an available credit/discount before it is fully paid.', 'Checked in compta/facture/card.php:6862 and :1238, described in comments at lines 1236 and 6861 as a hidden and unstable option.', 'Bypasses the normal rule that a down payment can only be closed/converted to credit once the paid amount equals the down payment amount, per the comment ''We can bypass this if hidden and unstable option ... is set''.', NULL, 1, 0, NULL, 1, 'df4374b94d911664dbf5c4e29c9b0aa6885f8aa8f422c7981d95f3c6f28e7c38', 'v2', '2026-07-24T06:41:12+00:00', '["// (option DEPOSIT_CAN_BE_CONVERTED_AS_AVAILABLE_CREDIT_EVEN_IF_NOT_YET_PAID allows creating the discount/credit even if the down payment", "// We can bypass this if hidden and unstable option DEPOSIT_CAN_BE_CONVERTED_AS_AVAILABLE_CREDIT_EVEN_IF_NOT_YET_PAID is set."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DISABLE_BAD_REPUTATION_PRODUCT_PRICE', 'bool', NULL, 'fourn', 'Disables the automatic exclusion of supplier prices from suppliers flagged with a bad reputation (DONOTORDER) when computing best supplier prices.', 'Checked once in fourn/ajax/getSupplierPrices.php:101 to skip the reputation filter that would otherwise exclude a supplier''s price when supplier_reputation == ''DONOTORDER''.', 'When set, supplier prices from suppliers marked DONOTORDER are no longer excluded from the price suggestions returned by the ajax endpoint.', 'Boolean-like (getDolGlobalInt): non-zero disables the reputation-based exclusion; 0/unset (default) keeps the exclusion active.', 1, 0, NULL, 1, '9594dd724cf04cd939e292a560d9984ee55359fd0d1af963554d222ec97eef86', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/ajax/getSupplierPrices.php:101: if (getDolGlobalInt(\"DISABLE_BAD_REPUTATION_PRODUCT_PRICE\") && $productSupplier->supplier_reputation == \"DONOTORDER\") {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DISABLE_CHECK_ON_MALWARE_MODULES', 'bool', NULL, 'admin', 'Disables the malware/compliance check performed on external modules during version checking.', 'Referenced in admin/modules.php:1037 to skip the compliance check when set, and in admin/modules.php:1556 to pre-check the ''checkforcompliance'' checkbox if not set. Both uses are in the context of external module management.', 'Enabling this constant bypasses the malware check for external modules, removing a security verification step. Disabling restores compliance checking.', 'Empty/unset = compliance check enabled; non-empty = compliance check disabled', 0, 0, 'admin/modules.php|admin/modules.php', 1, 'c7eadcc760cc1428b595df1d6bd6a397ea050778efaf6fe7fa85412d4989fb52', 'v2', '2026-04-21T13:29:58+00:00', '["admin/modules.php:1037|check|if ($objMod->isCoreOrExternalModule() == ''external'' && $action == ''checklastversion'' && !getDolGlobalString(''DISABLE_CHECK_ON_MALWARE_MODULES'')) {", "admin/modules.php:1556|read|print ''<span class=\"opacitymedium\"><input class=\"paddingright\" type=\"checkbox\" name=\"checkforcompliance\" id=\"checkforcompliance\"''.(getDolGlobalString(''DISABLE_CHECK_ON_MALWARE_MODU"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DISCOUNT_SPLIT_MORE_THAN_TWO_PARTS', 'string', NULL, 'comm', 'Enables a form allowing a discount/credit note to be split into more than two parts on the discount management page.', 'Checked twice in comm/remx.php (lines 620 and 914): if (getDolGlobalInt(''DISCOUNT_SPLIT_MORE_THAN_TWO_PARTS'') && !getDolGlobalInt(''MAIN_DISABLE_JAVASCRIPT'')) prints a ''#formsplit'' form with a ''confirm_split_more'' action, requiring JavaScript to be enabled.', 'When enabled (and JavaScript is not disabled), users can split a discount amount into more than two parts via an additional form; when disabled, this splitting UI is not shown.', 'Boolean: 1/true shows the split-into-more-than-two-parts form; also requires MAIN_DISABLE_JAVASCRIPT to be unset.', 0, 0, NULL, 1, '8c92eca3c644511c7affe699b49ab99e68b7cb32ee6f31a0b2733a66e901ba74', 'v2', '2026-07-24T07:05:23+00:00', '["comm/remx.php:620/914: if (getDolGlobalInt(''DISCOUNT_SPLIT_MORE_THAN_TWO_PARTS'') && !getDolGlobalInt(''MAIN_DISABLE_JAVASCRIPT'')) {", "comm/remx.php: print ''<form method=\"POST\" ... id=\"formsplit\" ...><input type=\"hidden\" name=\"action\" value=\"confirm_split_more\">"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DISPLAY_DISCOUNTED_SUPPLIER_PRICE', 'string', NULL, 'core', 'Controls whether supplier prices shown in product combo/select lists are displayed after applying the discount percentage.', 'Used exclusively in core/class/html.form.class.php (lines 4260–4546). When truthy, prices are multiplied by (1 - remise_percent/100) before display in option labels and values; when falsy the raw supplier price is shown.', 'Enabling causes all supplier price fields in product selectors to reflect the post-discount price. Disabling shows the gross price, which may lead to misinterpretation of supplier pricing.', 'Truthy = display discounted price (fprice * (1 - remise_percent/100)); empty/unset/falsy = display raw supplier price.', 1, 0, NULL, 1, '4a3d42a3f2a5326fa4b3019ee3eb9ac4c3e4e967a88b40ace76f3c60fa4f6637', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:4260|read|$optlabel .= '' - '' . price($objp->fprice * (getDolGlobalString(''DISPLAY_DISCOUNTED_SUPPLIER_PRICE'') ? (1 - $objp->remise_percent / 100) : 1), 1, $langs, 0, 0, -1, $conf->currency)", "core/class/html.form.class.php:4534|read|$opt .= price($objp->fprice * (getDolGlobalString(''DISPLAY_DISCOUNTED_SUPPLIER_PRICE'') ? (1 - $objp->remise_percent / 100) : 1), 1, $langs, 0, 0, -1, $conf->currency) . \"/\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DISPLAY_MARGIN_RATES', 'string', NULL, 'margin', 'Enables display of margin rate columns and fields across invoices, orders, and margin reports.', 'Configured in margin/admin/margin.php at line 159. Checked in over 40 locations including core/tpl/objectline_title.tpl.php, core/tpl/objectline_edit.tpl.php, and margin tab files. A JS property comment documents it as a boolean configuration flag.', 'Disabling this constant hides all margin-rate display columns site-wide. Enabling it shows margin rates on document lines and margin report pages, subject to user rights.', '0 or unset = margin rates hidden; 1 = margin rates displayed', 0, 0, 'margin/admin/margin.php', 1, 'a6224878f57b4a8ddace21dec6bc9fcec802bcb92118d73f567260bd592c8ade', 'v2', '2026-04-21T11:16:15+00:00', '["* @property {boolean} conf.DISPLAY_MARGIN_RATES", "if (!getDolGlobalString(''DISPLAY_MARGIN_RATES'')) {", "if (getDolGlobalString(''DISPLAY_MARGIN_RATES'') && $user->hasRight(''margins'', ''liretous'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DISPLAY_MARK_RATES', 'string', NULL, 'margin', 'Enables display of mark-up rate columns and fields across invoices, orders, and margin reports.', 'Configured in margin/admin/margin.php at line 176. Checked in over 40 locations including core/tpl/objectline_edit.tpl.php and margin tab files. A JS property comment documents it as a boolean configuration flag alongside DISPLAY_MARGIN_RATES.', 'Disabling this constant hides all mark-rate columns site-wide. Enabling it shows mark-up rates on document lines and margin report pages.', '0 or unset = mark rates hidden; 1 = mark rates displayed', 0, 0, 'margin/admin/margin.php', 1, '8c64891ac7a3ce7c3e143196f55ff62c4b2d1970770b777d756ba7a6c0a8af8e', 'v2', '2026-04-21T11:16:15+00:00', '["* @property {boolean} conf.DISPLAY_MARK_RATES", "if (!getDolGlobalString(''DISPLAY_MARK_RATES'')) {", "if (getDolGlobalString(''DISPLAY_MARK_RATES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DOC_SHOW_CUSTOMER_CODE', 'bool', NULL, 'core', 'Shows the customer''s internal code (code_client) on the Eagle proforma PDF document template for stock transfers.', 'Checked in core/modules/stocktransfer/doc/pdf_eagle_proforma.modules.php:1333: `if (getDolGlobalString(''DOC_SHOW_CUSTOMER_CODE'') && !empty($object->thirdparty->code_client))`.', 'Enabling it (when the third party has a code_client set) adds the customer code to this specific proforma PDF template''s output.', 'Boolean: true shows the customer code on the PDF (if present); false/unset (default) omits it.', 1, 0, NULL, 1, '825e92d59e38dc566ba3e4f05853708bb7e4a328db4f0fc582e7a8a741e4eb31', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/stocktransfer/doc/pdf_eagle_proforma.modules.php:1333|check|if (getDolGlobalString(''DOC_SHOW_CUSTOMER_CODE'') && !empty($object->thirdparty->code_client)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DOC_SHOW_FIRST_SALES_REP', 'bool', NULL, 'core', 'Controls whether the first assigned sales representative is printed in generated PDF documents.', 'Written via admin/pdf.php:191 and rendered in the admin UI at admin/pdf.php:662. Checked in 18 locations across invoice, order, contract, and stocktransfer PDF modules.', 'When enabled, the name of the first sales representative assigned to the object is included in the PDF output.', '0 (hide sales rep) or 1 (show first sales rep)', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '8fa3876473abeca5ea6360709303ec0c34b343cfeaf4cf83652f75d3b9825a5c', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:191|write|dolibarr_set_const($db, \"DOC_SHOW_FIRST_SALES_REP\", GETPOST(''DOC_SHOW_FIRST_SALES_REP'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:662|read|print $form->selectarray(\"DOC_SHOW_FIRST_SALES_REP\", $arrval, getDolGlobalString(''DOC_SHOW_FIRST_SALES_REP''));", "core/modules/commande/doc/pdf_einstein.modules.php:1478|check|if (getDolGlobalString(''DOC_SHOW_FIRST_SALES_REP'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:2179|check|if (getDolGlobalString(''DOC_SHOW_FIRST_SALES_REP'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DOL_URL_ROOT_DOCUMENT_PHP', 'string', NULL, 'admin', 'Alternate URL/wrapper to use instead of the default document.php for building document download links.', 'Read in admin/geoipmaxmind.php:118, admin/pdf_other.php:255, and core/class/html.formfile.class.php:977, each falling back to DOL_URL_ROOT.''/document.php'' when unset; also used in comm/action/rapport/index.php:186/187 with the comment ''To use another wrapper''.', 'When set, document links use this alternate URL/wrapper instead of the default document.php endpoint.', NULL, 1, 0, 'admin/geoipmaxmind.php|admin/pdf_other.php', 1, 'be5c0c98dbad8dbee672ff3d4792ce474178e169d7bcaab9590f31f83536843c', 'v2', '2026-07-24T06:41:12+00:00', '["$documenturl = getDolGlobalString(''DOL_URL_ROOT_DOCUMENT_PHP'', DOL_URL_ROOT.''/document.php''); // DOL_URL_ROOT_DOCUMENT_PHP can be used to set another wrapper", "$documenturl = getDolGlobalString(''DOL_URL_ROOT_DOCUMENT_PHP''); // To use another wrapper"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_ACCOUNTINGACCOUNT', 'string', NULL, 'don', 'Stores the general ledger account number used for donation payment entries in accounting journals.', 'Configured via don/admin/donation.php:124 (write) and displayed with a select_account widget at line 359. Read in accountancy/journal/bankjournal.php:274 and accountancy/journal/treasuryjournal.php:777 with ''NotDefined'' as reserved-word fallback.', 'If not set, donation payment lines in the bank and treasury journals use ''NotDefined'' as the account, which will cause posting errors.', 'String: general ledger account number; empty = not configured', 0, 0, 'don/admin/donation.php|don/admin/donation.php|don/admin/donation.php', 1, '3f7cd9b3644467e1226bd42a1f846787576556ec992dbc637ff80d5c79a5e22c', 'v2', '2026-04-21T11:16:15+00:00', '["don/admin/donation.php:124|write|$res = dolibarr_set_const($db, \"DONATION_ACCOUNTINGACCOUNT\", $account, ''chaine'', 0, '''', $conf->entity);", "accountancy/journal/bankjournal.php:274|read|$account_pay_donation = getDolGlobalString(''DONATION_ACCOUNTINGACCOUNT'', ''NotDefined''); // NotDefined is a reserved word", "accountancy/journal/treasuryjournal.php:777|read|$account_pay_donation = getDolGlobalString(''DONATION_ACCOUNTINGACCOUNT'', ''NotDefined''); // NotDefined is a reserved word", "don/admin/donation.php:359|read|print $formaccounting->select_account(getDolGlobalString(''DONATION_ACCOUNTINGACCOUNT''), ''DONATION_ACCOUNTINGACCOUNT'', 1, array(), 1, 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_ART200', 'string', NULL, 'don', 'Selects the fiscal article 200 tax-reduction option shown on the French Cerfa donation receipt PDF.', 'Read at don/admin/donation.php:402 to populate a dropdown selector. Checked at core/modules/dons/html_cerfafr.modules.php:199; when the integer value is >= 1, the article 200 section is included in the Cerfa PDF.', 'Enabling this option (value >= 1) causes the French Cerfa PDF to include the article 200 tax-reduction checkbox; leaving it unset or 0 omits that section.', 'Integer: 0 or unset = article 200 not included; >= 1 = article 200 included in Cerfa PDF.', 0, 0, 'don/admin/donation.php', 1, '5ff21f9226b5e0026d3c3fe292c655fc3352c0a54a32f598a0cc68ecb4755dda', 'v2', '2026-04-21T13:29:58+00:00', '["don/admin/donation.php:402|read|print $form->selectarray(\"DONATION_ART200\", $arrval, getDolGlobalString(''DONATION_ART200''));", "core/modules/dons/html_cerfafr.modules.php:199|check|if (getDolGlobalInt(''DONATION_ART200'') >= 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_ART238', 'string', NULL, 'don', 'Selects the fiscal article 238 tax-reduction option shown on the French Cerfa donation receipt PDF.', 'Read at don/admin/donation.php:413 to populate a dropdown selector. Checked at core/modules/dons/html_cerfafr.modules.php:209; when the integer value is >= 1, the article 238 section is included in the Cerfa PDF.', 'Enabling this option (value >= 1) causes the French Cerfa PDF to include the article 238 tax-reduction checkbox; leaving it unset or 0 omits that section.', 'Integer: 0 or unset = article 238 not included; >= 1 = article 238 included in Cerfa PDF.', 0, 0, 'don/admin/donation.php', 1, 'f7b31d4ccb61c5185abcd2667b80a4ebfa246a687ad1ddeed3fcb106f48bab79', 'v2', '2026-04-21T13:29:58+00:00', '["don/admin/donation.php:413|read|print $form->selectarray(\"DONATION_ART238\", $arrval, getDolGlobalString(''DONATION_ART238''));", "core/modules/dons/html_cerfafr.modules.php:209|check|if (getDolGlobalInt(''DONATION_ART238'') >= 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_ART978', 'string', NULL, 'don', 'Selects the fiscal article 978 tax-reduction option shown on the French Cerfa donation receipt PDF.', 'Read at don/admin/donation.php:424 to populate a dropdown selector. Checked at core/modules/dons/html_cerfafr.modules.php:219; when the integer value is >= 1, the article 978 section is included in the Cerfa PDF.', 'Enabling this option (value >= 1) causes the French Cerfa PDF to include the article 978 tax-reduction checkbox; leaving it unset or 0 omits that section.', 'Integer: 0 or unset = article 978 not included; >= 1 = article 978 included in Cerfa PDF.', 0, 0, 'don/admin/donation.php', 1, '308c82558997fb78c18955c7a011291d1a3f5d81ed81f02abe2a9f9d4972c758', 'v2', '2026-04-21T13:29:58+00:00', '["don/admin/donation.php:424|read|print $form->selectarray(\"DONATION_ART978\", $arrval, getDolGlobalString(''DONATION_ART978''));", "core/modules/dons/html_cerfafr.modules.php:219|check|if (getDolGlobalInt(''DONATION_ART978'') >= 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_COUNTERS_ARE_PUBLIC', 'string', NULL, 'don', 'Controls whether the total amount of valid donations is publicly visible (e.g. on the public donation counters/website widget).', 'Set via an admin yes/no selector in don/admin/website.php:204 and written with dolibarr_set_const at don/admin/website.php:83; the language string confirms: ''The total amount of valid donations is publicly visible''.', 'Enabling it makes the aggregate valid-donations total publicly visible; disabling it hides that public total.', 'Yes/No: ''The total amount of valid donations is publicly visible'' (from don/website.lang).', 0, 0, 'don/admin/website.php|don/admin/website.php', 1, '376a35138a61b2e2f2d8c38f52efe67560105c5dbfbc0aace6eee4824447b259', 'v2', '2026-07-24T07:05:23+00:00', '["don/admin/website.php:204: print $form->selectyesno(\"DONATION_COUNTERS_ARE_PUBLIC\", getDolGlobalInt(''DONATION_COUNTERS_ARE_PUBLIC''), 1, false, 0, 1);", "don/admin/website.php:83: $res = dolibarr_set_const($db, \"DONATION_COUNTERS_ARE_PUBLIC\", $publiccounters, ''chaine'', 0, '''', $conf->entity);", "langs/en_US/website.lang:484: DONATION_COUNTERS_ARE_PUBLIC=The total amount of valid donations is publicly visible"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_ENABLE_PUBLIC', 'bool', NULL, 'don', 'Enables the public-facing online donation form accessible without authentication.', 'Written via don/admin/website.php (lines 69, 71, 82) and checked at don/admin/website.php:148/165 and public/donations/new.php:95. When unset or 0, access to the public donation page is blocked.', 'Setting this to 1 opens the public donation form to unauthenticated visitors; setting to 0 or leaving unset blocks public access.', '1 = public donation form enabled; 0 or unset = public form disabled.', 0, 0, 'don/admin/website.php|don/admin/website.php|don/admin/website.php|don/admin/website.php|don/admin/website.php|don/admin/website.php', 1, '5159b2088ab1919a4381895d18db0026814a1d5a680d960e1c8b15521d0b727f', 'v2', '2026-04-21T13:29:58+00:00', '["don/admin/website.php:69|write|dolibarr_set_const($db, ''DONATION_ENABLE_PUBLIC'', 1, ''chaine'', 0, '''', $conf->entity);", "don/admin/website.php:148|check|if (!getDolGlobalString(''DONATION_ENABLE_PUBLIC'')) {", "public/donations/new.php:95|check|if (!getDolGlobalString(''DONATION_ENABLE_PUBLIC'')) {", "don/admin/website.php:165|check|if (getDolGlobalString(''DONATION_ENABLE_PUBLIC'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_EXT_URL_SUBSCRIPTION_INFO', 'string', NULL, 'public', 'External URL linked from the public donation/subscription payment form, offering more information about the subscription amount.', 'Checked and read in public/payment/newpayment.php:2085-2086; when set, an ''external'' link (''SeeHere'' label) to this URL is printed next to the amount field on the public donation form.', 'Setting it adds a clickable external link on the public donation payment page pointing donors to more subscription information; if unset, no such link is shown.', 'String: a URL, opened in a new tab (rel="external" target="_blank").', 1, 0, NULL, 1, '0ac05489ce387d54297d7bb9a131e9b3093f17026bc705f298767dfc920a6025', 'v2', '2026-07-24T07:05:23+00:00', '["public/payment/newpayment.php:2085|check|if (getDolGlobalString(''DONATION_EXT_URL_SUBSCRIPTION_INFO'')) {", "public/payment/newpayment.php:2086|read|print '' - <a href=\"'' . getDolGlobalString(''DONATION_EXT_URL_SUBSCRIPTION_INFO'').''\" rel=\"external\" target=\"_blank\" rel=\"noopener noreferrer\">''.$langs->trans(\"SeeHere\").''</a>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_INVOICE_MIN_AMOUNT', 'string', NULL, 'public', 'Sets the minimum accepted amount for a public donation invoice submission.', 'Read at public/invoice/new.php:545 via max() to enforce a floor on the amount, checked at :258 to reject amounts at or below this value, and used at :260 to display an error message with the minimum. Described in the file header as ''Minimum amount''.', 'Amounts submitted below or equal to this value are rejected with an error; the floor is enforced server-side.', 'Minimum amount (numeric float/int string)', 1, 0, NULL, 1, '88ceade20c86eebebff657f20852f756397b5838c3bfd95e96a9415b9e420d5b', 'v2', '2026-04-21T13:50:40+00:00', '["public/invoice/new.php:33  *  DONATION_INVOICE_MIN_AMOUNT                   Minimum amount", "public/invoice/new.php:545|read|$amount = max(0, (float) $amount, (float) getDolGlobalInt(\"DONATION_INVOICE_MIN_AMOUNT\"));", "public/invoice/new.php:258|check|if (!$amount || $amount <= (float) getDolGlobalString(\"DONATION_INVOICE_MIN_AMOUNT\")) {", "public/invoice/new.php:260|read|$errmsg .= $langs->trans(\"ErrorFieldMinimumAmount\", (float) getDolGlobalString(\"DONATION_INVOICE_MIN_AMOUNT\")).\"<br>\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_MESSAGE', 'string', NULL, 'core', 'Custom free-text message displayed on the donation form and embedded in donation PDF documents.', 'Written via don/admin/donation.php:142 and rendered in a textarea at don/admin/donation.php:374. Read and substituted into the Cerfa PDF template at core/modules/dons/html_cerfafr.modules.php:180 and conditionally inserted as an HTML block in core/modules/dons/html_generic.modules.php:159-160.', 'Setting this constant inserts a custom message into both the donation input form and generated donation documents; leaving it empty omits the message block.', 'Arbitrary HTML/text string. Empty or unset = no message displayed.', 0, 0, 'don/admin/donation.php|don/admin/donation.php', 1, '17434e001c05e11859f23575837bac26ea013441201b6f30a5e9fc56db910eae', 'v2', '2026-04-21T13:29:58+00:00', '["don/admin/donation.php:374|read|print ''<textarea name=\"DONATION_MESSAGE\" class=\"flat\" cols=\"80\">'' . getDolGlobalString(''DONATION_MESSAGE'').''</textarea>'';", "core/modules/dons/html_cerfafr.modules.php:180|read|$form = str_replace(''__DONATION_MESSAGE__'', getDolGlobalString(''DONATION_MESSAGE''), $form);", "core/modules/dons/html_generic.modules.php:159|check|if (getDolGlobalString(''DONATION_MESSAGE'')) {", "core/modules/dons/html_generic.modules.php:160|read|$donationMessage = ''<div id=\"donation-message\"><p>'' . getDolGlobalString(''DONATION_MESSAGE'').''</p></div>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_MIN_AMOUNT', 'string', NULL, 'public', 'Minimum amount required for a donation submission on the public donation form.', 'COMMENTS state: ''DONATION_MIN_AMOUNT   Minimum amount''. Written via don/admin/website.php:83 and enforced in public/donations/new.php:218-220 (form validation) and public/donations/new.php:541 (max with 0). Also enforced in public/payment/newpayment.php:2152-2153.', 'Setting a positive value prevents donors from submitting amounts below the threshold; the form displays an error and the payment amount is floored to the minimum.', 'Numeric value representing the minimum donation amount in the default currency. 0 or unset = no minimum enforced.', 0, 0, 'don/admin/website.php|don/admin/website.php', 1, '0f0dd2434c2fa70134e296e24e628c7232d0e832d7c9c32877ad93f478ce59ef', 'v2', '2026-04-21T13:29:58+00:00', '["public/donations/new.php:33  *  DONATION_MIN_AMOUNT                   Minimum amount", "public/donations/new.php:218|check|if (!GETPOST(''amount'') || GETPOST(''amount'') < getDolGlobalInt(''DONATION_MIN_AMOUNT'')) {", "public/donations/new.php:541|read|$amount = max(0, (float) $amount, (float) getDolGlobalInt(\"DONATION_MIN_AMOUNT\"));", "public/payment/newpayment.php:2153|read|$valtoshow = max(getDolGlobalString(''DONATION_MIN_AMOUNT''), $valtoshow);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_NEWFORM_AMOUNT', 'string', NULL, 'public', 'Sets the pre-filled default donation amount displayed and submitted on the public donation payment form.', 'Checked and read at public/payment/newpayment.php:2123, :2129, :2140, :2141, :2144, :2145; used both as the displayed value and as the submitted amount when set.', 'When set, the donation form pre-fills with this amount; when unset, the user must enter an amount manually.', 'A numeric amount string; empty/unset means no default amount is pre-filled.', 1, 0, NULL, 1, '7cb993f6d1dc57586e1aa43cb59f560dccb2118ea233f70f415cba6ab09f8355', 'v2', '2026-04-21T13:50:40+00:00', '["public/payment/newpayment.php:2141|read|$valtoshow = getDolGlobalString(''DONATION_NEWFORM_AMOUNT'');", "public/payment/newpayment.php:2145|read|$amount = getDolGlobalString(''DONATION_NEWFORM_AMOUNT'');", "public/payment/newpayment.php:2140|check|if (getDolGlobalString(''DONATION_NEWFORM_AMOUNT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_NEWFORM_EDITAMOUNT', 'string', NULL, 'public', 'Allows the donation amount on the public donation form to be edited/prefilled from the DONATION_NEWFORM_AMOUNT default instead of forcing manual entry.', 'Checked in public/payment/newpayment.php:2098; when set and no amount is otherwise provided, the code uses DONATION_NEWFORM_AMOUNT (if also set) as the editable default value shown to the donor, rather than leaving the field for the user''s own POSTed value only.', 'Enabling it makes the public donation amount field prefill with the DONATION_NEWFORM_AMOUNT default when no amount is otherwise supplied; leaving it unset means only a POSTed value is used for the default.', 'Boolean-like: truthy enables using DONATION_NEWFORM_AMOUNT as an editable default amount on the public donation form.', 1, 0, NULL, 1, 'd7cc15f15c36b140e668433909a46676af7bee723f54002da24026243d5060e1', 'v2', '2026-07-24T07:05:23+00:00', '["public/payment/newpayment.php:2098|check|if (getDolGlobalString(''DONATION_NEWFORM_EDITAMOUNT'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_NEWFORM_PAYONLINE', 'string', NULL, 'public', 'Specifies the online payment method suggested on the public donation form (e.g. paypal, paybox, stripe, or ''all'').', 'COMMENTS state: ''DONATION_NEWFORM_PAYONLINE   Suggest payment with paypal, paybox or stripe''. Written via don/admin/website.php:85 and checked/read in public/donations/new.php:320, :326, :327, :537. When set to ''-1'', the payment redirect is skipped.', 'Setting this to a specific payment provider name restricts online payment to that provider; ''all'' enables all configured providers; ''-1'' disables online payment suggestion.', 'Payment provider name string (e.g. ''paypal'', ''paybox'', ''stripe''); ''all'' = all providers; ''-1'' = no online payment; unset = no payment method suggested.', 0, 0, 'don/admin/website.php|don/admin/website.php', 1, 'cb74e7bedef7cd55822cb1e8b19a45460b9f041b263ce1b707a1d65a131d3d7b', 'v2', '2026-04-21T13:29:58+00:00', '["public/donations/new.php:34  *  DONATION_NEWFORM_PAYONLINE            Suggest payment with paypal, paybox or stripe", "public/donations/new.php:320|check|if (getDolGlobalString(''DONATION_NEWFORM_PAYONLINE'') && getDolGlobalString(''DONATION_NEWFORM_PAYONLINE'') != ''-1'') {", "public/donations/new.php:326|check|if (getDolGlobalString(''DONATION_NEWFORM_PAYONLINE'') != ''-1'' && getDolGlobalString(''DONATION_NEWFORM_PAYONLINE'') != ''all'') {", "public/donations/new.php:327|read|$urlback .= ''&paymentmethod=''.urlencode(getDolGlobalString(''DONATION_NEWFORM_PAYONLINE''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_NOTE_PUBLIC', 'string', NULL, 'core', 'Enables inclusion of a donation''s public note in the generated donation receipt/document.', 'Checked in core/modules/dons/html_generic.modules.php:153: `if (getDolGlobalInt(''DONATION_NOTE_PUBLIC'') >= 1 && !empty($don->note_public)) { $notePublic = ''<div id="note-public"><p>''.$don->note_public.''</p></div>''; }`, substituted into the ''__NOTE_PUBLIC__'' placeholder of the donation HTML template.', 'When set to 1 or more, and the donation has a non-empty public note, that note text is rendered into the donation document/receipt output; otherwise the placeholder is left blank.', '>=1 = show the donation''s public note in the document; 0/unset = do not show it.', 1, 0, NULL, 1, '1df06f6c711b0cca29dae720ca0107ce098f8b8aaadd62477c546e595898403d', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/dons/html_generic.modules.php:153|check|if (getDolGlobalInt(''DONATION_NOTE_PUBLIC'') >= 1 && !empty($don->note_public)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_PUBLIC_INTERFACE', 'string', NULL, 'public', 'Selects/customizes the logo or interface variant shown in the header of the public online donation registration page.', 'In public/donations/new.php:165, llxHeaderVierge() calls htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''DONATION_PUBLIC_INTERFACE''), ''DONATION_IMAGE_PUBLIC_REGISTRATION''), passing the constant''s value as a parameter to the shared public-header logo/interface renderer alongside the related DONATION_IMAGE_PUBLIC_REGISTRATION constant.', 'Setting it changes the value passed to the shared public header function, likely affecting logo/branding shown on the public donation form; exact rendering logic is in htmlPrintOnlineHeader() which was not inspected.', 'String, passed positionally to htmlPrintOnlineHeader(); exact accepted values not documented in this payload.', 1, 0, NULL, 1, '01ff9b3c4b63a97182109d22d8c43bda2e4aa7128a45a478b810da9850fbe89e', 'v2', '2026-07-24T07:05:23+00:00', '["public/donations/new.php:165: htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''DONATION_PUBLIC_INTERFACE''), ''DONATION_IMAGE_PUBLIC_REGISTRATION'');"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONATION_USE_THIRDPARTIES', 'bool', NULL, 'don', 'Links donation records to third-party (company/contact) entities when the Societe module is enabled.', 'Configured in don/admin/donation.php:342 via a selectarray UI and checked extensively in don/card.php and don/list.php. When enabled, donation forms require or display a third-party selector, and statistics are grouped by third-party.', 'Enabling this constant associates donations with third-party records, enabling CRM-style tracking; disabling it keeps donations standalone without a third-party link.', 'String value selected from an array in admin; truthy enables third-party linkage, empty/falsy disables it.', 0, 0, 'don/admin/donation.php', 1, 'b894c0bbd545920ced1b1dfa7992afbb81b47e59b7f7ccc3b62dfa64eaff5feb', 'v2', '2026-04-21T13:29:58+00:00', '["don/admin/donation.php:342|read|print $form->selectarray(\"DONATION_USE_THIRDPARTIES\", $arrval, getDolGlobalString(''DONATION_USE_THIRDPARTIES''));", "don/card.php:414|check|if (isModEnabled(\"societe\") && getDolGlobalString(''DONATION_USE_THIRDPARTIES'')) {", "don/list.php:670|check|if (getDolGlobalString(''DONATION_USE_THIRDPARTIES'')) {", "don/stats/index.php:218|check|if (getDolGlobalString(''DONATION_USE_THIRDPARTIES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DONT_INCLUDE_COMPLETED_ELEMENTS_LINKS', 'string', NULL, 'core', 'Controls whether the ''link to element'' popup (proposals, orders, invoices, shipments, tickets, MOs...) excludes already-completed/closed/paid items.', 'Read in core/class/html.form.class.php:11121 as $dontIncludeCompletedItems, then appended as extra SQL WHERE conditions (e.g. ''t.fk_statut < 4'', ''t.paye < 1'', ''t.billed < 1'') on each element type''s candidate-link query throughout the same function.', 'Enabling it filters out elements considered ''completed'' (e.g. paid invoices, billed orders, closed proposals/tickets/MOs) from the list of linkable objects shown to the user.', 'Boolean: truthy value adds status-based exclusion filters per element type (invoices: paye<1, orders: facture<1/billed<1, proposals/supplier_proposal: fk_statut<4, shipping: fk_statut<2, ticket: fk_statut<8, mo: status<3).', 1, 0, NULL, 1, 'e5c4a5a8fbbd35f5d26030a173a20bf68ac308d2375c6852c0c44c8e0b88701a', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:11121|read|$dontIncludeCompletedItems = getDolGlobalString(''DONT_INCLUDE_COMPLETED_ELEMENTS_LINKS'');", "core/class/html.form.class.php:11176|...($dontIncludeCompletedItems ? '' AND t.paye < 1'' : '''')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DON_ADDON_MODEL', 'string', NULL, 'don', 'Selects the active PDF document template (addon model) used to generate donation documents.', 'Set and read via the donation admin page at don/admin/donation.php. The value is the model name string; it is read in don/class/don.class.php:1063-1064 to load the appropriate PDF class. Multiple write and check occurrences confirm it is an actively managed admin setting.', 'Changing the value switches the PDF layout used for donation documents; deleting the constant (via dolibarr_del_const) reverts to the default template.', 'String; name of a donation PDF addon model class available in the system.', 0, 0, 'don/admin/donation.php|don/admin/donation.php|don/admin/donation.php|don/admin/donation.php|don/admin/donation.php|don/admin/donation.php', 1, '4308694e63ba75d0bd28e9972b3fbc5b385fdf0b506784607a1af2bc0bf64b27', 'v2', '2026-04-21T13:29:58+00:00', '["don/admin/donation.php:97|write|if (dolibarr_set_const($db, \"DON_ADDON_MODEL\", $value, ''chaine'', 0, '''', $conf->entity)) {", "don/class/don.class.php:1063|read|} elseif (getDolGlobalString(''DON_ADDON_MODEL'')) {", "don/class/don.class.php:1064|read|$modele = getDolGlobalString(''DON_ADDON_MODEL'');", "don/admin/donation.php:115|write|dolibarr_del_const($db, ''DON_ADDON_MODEL'', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('DO_NOT_TRY_TO_DEFRAGMENT_STOCKS_WAREHOUSE', 'string', NULL, 'product', 'Reverses warehouse stock sort order to DESC to skip defragmentation-friendly ordering.', 'Read in product/class/product.class.php:6350 and product/class/productbatch.class.php:535. Comments on both lines note that ASC order is important for expedition card to avoid stock fragmentation; setting this constant switches to DESC.', 'When set, stock rows are fetched in descending quantity order, preventing the defragmentation behaviour that ASC ordering provides for shipment picks.', 'Truthy string (DESC order, no defragmentation) or empty/unset (ASC order, defragmentation-friendly).', 1, 0, NULL, 1, '36ae763cac413d771ca78449644856d3add86ec94405a7447f45bf885ac9fe11', 'v2', '2026-04-21T13:29:58+00:00', '["product/class/product.class.php:6350|read|$sql .= \" ORDER BY ps.reel \".(getDolGlobalString(''DO_NOT_TRY_TO_DEFRAGMENT_STOCKS_WAREHOUSE'') ? ''DESC'' : ''ASC''); // Note : qty ASC is important for expedition card, to avoid stock", "product/class/productbatch.class.php:535|read|$sql .= \", t.qty \".(!getDolGlobalString(''DO_NOT_TRY_TO_DEFRAGMENT_STOCKS_WAREHOUSE'') ? ''ASC'' : ''DESC''); // Note : qty ASC is important for expedition card, to avoid stock fragmenta"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ECM_AUTO_TREE_HIDEN', 'bool', NULL, 'core', 'Hides the automatic directory tree in the ECM (Electronic Content Management) module when enabled.', 'Referenced in admin/ecm.php, core/lib/ecm.lib.php, ecm/index_auto.php, and core/modules/modECM.class.php. The module menu entry for the ECM auto tree is also conditionally suppressed based on this constant (modECM.class.php:182).', 'Enabling this constant hides the automatic ECM folder tree from the UI and the module menu. Disabling restores the tree view.', 'Empty/unset = tree visible; non-empty = tree hidden', 0, 0, 'admin/ecm.php', 1, '5268d12cce73b34251800d1cb61aae73fa94c414b506e073eefeb3c3d3039cd3', 'v2', '2026-04-21T13:29:58+00:00', '["admin/ecm.php:111|check|if (!getDolGlobalString(''ECM_AUTO_TREE_HIDEN'')) {", "core/lib/ecm.lib.php:57|check|if (!getDolGlobalString(''ECM_AUTO_TREE_HIDEN'')) {", "ecm/index_auto.php:316|check|if (!getDolGlobalString(''ECM_AUTO_TREE_HIDEN'')) {", "core/modules/modECM.class.php:182|read|''enabled'' => ''($user->hasRight(\"ecm\", \"read\") || $user->hasRight(\"ecm\", \"upload\")) && !getDolGlobalInt(\"ECM_AUTO_TREE_HIDEN\")'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ECM_SHOW_GENERATE_WEBP_BUTTON', 'bool', NULL, 'core', 'Shows a ''Generate webp image'' toolbar button in the ECM (document management) file manager for converting images to webp format.', 'Used in core/tpl/filemanager.tpl.php:134: within the ''ecm'' module branch (and only when not already showing the website-media webp button), if truthy and the user has add permission, prints a toolbar link with action=confirmconvertimgwebp.', 'Enabling it adds a visible toolbar button in the ECM file manager that links to the confirmconvertimgwebp action, letting users trigger webp image conversion from that screen.', 'Boolean-like (read via getDolGlobalInt): truthy shows the ''GenerateImgWebp'' toolbar button in the ECM file manager.', 0, 0, NULL, 1, '063b91f269827b2cafb57a0109a3e0bbccd6e669dc2b9673e32f4918531bb73b', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/filemanager.tpl.php:134|check|if (getDolGlobalInt(''ECM_SHOW_GENERATE_WEBP_BUTTON'')) {", "core/tpl/filemanager.tpl.php:135|print ''<a id=\"agenerateimgwebp\" href=\"''.$_SERVER[\"PHP_SELF\"].''?action=confirmconvertimgwebp...''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EDIT_ORDER_SHIPMENT_ON_PROCESS', 'string', NULL, 'commande', 'Allows editing (Modify button) of a sales order that is in ''shipment on process'' status, not just validated orders.', 'Checked in commande/card.php:3523: the Modify button is shown if ($object->status == Commande::STATUS_VALIDATED || ($object->status == Commande::STATUS_SHIPMENTONPROCESS && getDolGlobalString(''EDIT_ORDER_SHIPMENT_ON_PROCESS''))) && $usercancreate.', 'When enabled, orders whose status is STATUS_SHIPMENTONPROCESS can still be modified via the Modify button; when disabled (default), only STATUS_VALIDATED orders show that button.', 'Boolean: 1/true allows editing of orders in shipment-on-process status.', 0, 0, NULL, 1, 'c483250ec06208187551aa9ea06494d1d394e6bcb9e92752411f74f1075f04c8', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3523: if ((status==VALIDATED || (status==SHIPMENTONPROCESS && getDolGlobalString(''EDIT_ORDER_SHIPMENT_ON_PROCESS''))) && $usercancreate) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAILCOLLECTOR_ISNOTANSWER_USE_REFERENCES', 'bool', NULL, 'admin', 'Causes emails with generic References headers to be treated as replies when applying the ''isnotanswer'' collector filter.', 'When enabled, the email collector checks the References header even for emails not otherwise identified as answers. The comment states: ''Consider generic References as answer for isnotanswer filter.'' Configured via a select dropdown in admin/emailcollector_list.php.', 'Enabling this constant allows emails with References headers to match the ''isnotanswer'' filter as if they were replies; disabling it restricts the filter to emails identified as answers by other means.', 'Integer: non-zero enables References-based answer detection; 0 disables it.', 0, 0, 'admin/emailcollector_list.php', 1, '9faab17ef189c4ff8ff2e7c7e1b09afb769d90950fc080ea05aef98d7803df2a', 'v2', '2026-04-21T13:50:40+00:00', '["// EMAILCOLLECTOR_ISNOTANSWER_USE_REFERENCES: Consider generic References as answer for \"isnotanswer\" filter.", "emailcollector/class/emailcollector.class.php:2076|check|if (!$isanswer && getDolGlobalInt(''EMAILCOLLECTOR_ISNOTANSWER_USE_REFERENCES'') && !empty($headers[''References''])) {", "admin/emailcollector_list.php:815|read|print $form->selectarray(\"EMAILCOLLECTOR_ISNOTANSWER_USE_REFERENCES\", $arrval, getDolGlobalInt(''EMAILCOLLECTOR_ISNOTANSWER_USE_REFERENCES'', 0));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAILCOLLECTOR_NO_FILTER_ON_DATE_IF_THERE_IS_A_TARGETDIR', 'string', NULL, 'emailcollector', 'Disables the default date-based filter (SINCE) used when fetching emails, even when the collector has a target IMAP directory configured.', 'Checked in emailcollector/class/emailcollector.class.php:1553; by default (constant unset) the collector filters messages with SINCE=last successful check date (minus a 1-day overlap) whenever a targetdir is set. Setting the constant skips that date filter in that case.', 'Setting it makes email collectors with a targetdir re-scan all messages instead of only those since the last successful check, which can reprocess older emails.', 'Boolean: truthy disables the SINCE date filter when a targetdir is configured.', 0, 0, NULL, 1, '1cb4549911acf4cb4cf0ffe9a0671282deffe23638a6bccc4334f2e4f48d54a2', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:1553|if (empty($targetdir) || !getDolGlobalString(''EMAILCOLLECTOR_NO_FILTER_ON_DATE_IF_THERE_IS_A_TARGETDIR'')) {\t// Use the last date of successful check as a filter if there is no targ"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAILCOLLECTOR_USE_IN_REPLY_TO_TO_DETECT_ANSWERS', 'bool', NULL, 'emailcollector', 'Enables using the email ''In-Reply-To'' header as a signal to detect whether an incoming email is a reply to a previous one.', 'Checked twice in emailcollector/class/emailcollector.class.php:2056 and 2087: when set, a non-empty In-Reply-To header marks the email as an answer ($isanswer = 1), used both for the general answer-detection rule and the isnotanswer rule.', 'Enabling it makes the collector rely on In-Reply-To in addition to subject reply markers, which the code comments describe as ''not reliable'' because In-Reply-To/References can be reused by unrelated forwarded emails.', 'Boolean: truthy makes non-empty In-Reply-To count as evidence the email is an answer.', 0, 0, NULL, 1, '817940a5a92efa072bf3e41ca8c6b82d8791009aff626dccd5151e838a4c662e', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:2056|if (getDolGlobalString(''EMAILCOLLECTOR_USE_IN_REPLY_TO_TO_DETECT_ANSWERS'')) {", "// Note: \"In-Reply-To\" to detect if mail is an answer of another mail is not reliable because we can have: Message-ID=A, In-Reply-To=B, References=B and message can BE an answer but may be NOT"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAILCOLLECTOR_USE_THIS_THIRDPARTY_ID_IF_DUPLICATE', 'bool', NULL, 'emailcollector', 'Specifies a fallback thirdparty ID to use when the email collector finds more than one matching thirdparty for an incoming email.', 'Read in emailcollector/class/emailcollector.class.php:2956-2957: when findNearest() returns -2 (ambiguous, multiple thirdparties found) and this constant is set, its value is used as the thirdparty id via $thirdpartystatic->fetch($idtouseforthirdparty).', 'Setting it to a valid thirdparty ID resolves ambiguous thirdparty matches to that generic thirdparty instead of failing/erroring; leaving it unset causes the collector to raise an error in that duplicate case.', 'Integer, a thirdparty (societe) row id to use as the generic fallback.', 0, 0, NULL, 1, '17e3fc2153097cafdbfbd1b35b805fb4a45b1b67068a6913b6da48578960bf1f', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:2956|if (getDolGlobalInt(''EMAILCOLLECTOR_USE_THIS_THIRDPARTY_ID_IF_DUPLICATE'') && $result == -2) {\t// If 2 thirdparty found, we will use a generic one defined by EMAILCOLLECTOR_USE_THIS", "emailcollector/class/emailcollector.class.php:2957|$idtouseforthirdparty = getDolGlobalInt(''EMAILCOLLECTOR_USE_THIS_THIRDPARTY_ID_IF_DUPLICATE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAILINGS_SUPPORT_ALSO_SMS', 'string', NULL, 'comm', 'Enables SMS support alongside email in the mass mailing (emailings) module.', 'Referenced across comm/mailing/list.php, comm/mailing/index.php, and comm/mailing/card.php. When set to a non-zero integer, additional SMS-related UI sections and logic branches are activated in the mailing interface.', 'Enabling this constant unlocks SMS sending capabilities within the emailings module. Disabling hides SMS-related options and paths.', '0 or unset = email only; 1 = SMS support also enabled', 1, 0, NULL, 1, '8e0fdeec7acea22c6e4905c029f60939f3d9dc10845a83eb01cc36642fd50c99', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/list.php:454|check|if (getDolGlobalInt(''EMAILINGS_SUPPORT_ALSO_SMS'')) {", "comm/mailing/index.php:76|check|if (getDolGlobalInt(''EMAILINGS_SUPPORT_ALSO_SMS'')) {", "comm/mailing/card.php:862|check|if (getDolGlobalInt(''EMAILINGS_SUPPORT_ALSO_SMS'')) {", "comm/mailing/list.php:508|check|if (getDolGlobalInt(''EMAILINGS_SUPPORT_ALSO_SMS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAILING_CAN_EDIT_BACKGROUND_COLOR', 'string', NULL, 'comm', 'Would enable a background-color picker for mass emailing messages, but the code that reads it is commented out in both locations found.', 'Both occurrences in comm/mailing/card.php:929 and comm/mailing/card.php:1431 are inside PHP block comments (/* ... */): the getDolGlobalString(''EMAILING_CAN_EDIT_BACKGROUND_COLOR'') check and its surrounding ''Background color'' picker code are disabled/dead code.', 'Setting this constant currently has no effect since the only two call sites are commented out; the feature (BackgroundColorByDefault color picker) is inactive in this codebase version.', 'Exact behavior unclear from code alone (feature appears disabled/dead code in current source).', 1, 0, NULL, 1, '1ad0f706778724dc4759210d25e6ab41348107e50a503f1991812f7765bb704f', 'v2', '2026-07-24T07:05:23+00:00', '["comm/mailing/card.php:929: /* if (getDolGlobalString(''EMAILING_CAN_EDIT_BACKGROUND_COLOR'')) {", "comm/mailing/card.php:1431: /* if (getDolGlobalString(''EMAILING_CAN_EDIT_BACKGROUND_COLOR'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAILING_MAIL_SENDMODE', 'string', NULL, 'comm', 'Overrides the mail sending mode (e.g. mail/smtp/smtps) used specifically when sending a mass emailing campaign.', 'Read in comm/mailing/card.php:999 as the primary source for $sendingmode when action==''sendall''; if empty, code falls back to the global MAIN_MAIL_SENDMODE, and if that is also empty, defaults to ''mail'' (comment at line 1000-1001: ''If not defined, we use php mail function'').', 'Lets mass emailing use a different transport (mail/smtp/smtps) than the rest of the application (which uses MAIN_MAIL_SENDMODE).', 'Same values as MAIN_MAIL_SENDMODE, e.g. ''mail'', ''smtp'', ''smtps''; empty/unset falls back to MAIN_MAIL_SENDMODE then ''mail''.', 0, 0, NULL, 1, '164763842f8e857f33e40e2f87c0b76d5146300d18314be30671744238e67669', 'v2', '2026-07-24T07:05:23+00:00', '["comm/mailing/card.php:999: $sendingmode = getDolGlobalString(''EMAILING_MAIL_SENDMODE'');", "comm/mailing/card.php:1001: $sendingmode = ''mail''; // If not defined, we use php mail function"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAILING_USE_ADVANCED_SELECTOR', 'bool', NULL, 'core', 'Enables an ''Advanced target recipients'' tab on emailing campaigns, with a dedicated selector page.', 'core/lib/emailing.lib.php:53 shows: if getDolGlobalString(''EMAILING_USE_ADVANCED_SELECTOR'') is true, an extra tab is added linking to comm/mailing/advtargetemailing.php (''MailAdvTargetRecipients''). core/class/conf.class.php:1372 shows this is auto-set to 1 by Dolibarr itself when MAIN_FEATURES_LEVEL >= 1 and javascript/ajax is enabled: `$this->global->EMAILING_USE_ADVANCED_SELECTOR = 1;`.', 'When enabled (manually or automatically via MAIN_FEATURES_LEVEL>=1), an additional ''advanced target recipients'' tab/page appears on emailing records for building complex recipient selection criteria.', 'Boolean; auto-forced to 1 when MAIN_FEATURES_LEVEL >= 1 and ajax is active, per conf.class.php.', 0, 0, NULL, 1, '29506b2516113603a3a90590b523d218f7c91f9da454582e13418a45e66f2fb7', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/emailing.lib.php:53: if (getDolGlobalString(''EMAILING_USE_ADVANCED_SELECTOR'')) {", "core/class/conf.class.php:1371-1372: if (!empty($this->use_javascript_ajax) && getDolGlobalInt(''MAIN_FEATURES_LEVEL'') >= 1) { $this->global->EMAILING_USE_ADVANCED_SELECTOR = 1; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EMAIL_ALTERNATIVE_HOST_SIGNATURE', 'string', NULL, 'emailcollector', 'Specifies an alternative hostname used to match Dolibarr tracking IDs in incoming email references.', 'Used in emailcollector/class/emailcollector.class.php at lines 2037-2038 and 2403-2404 to match the pattern ''dolibarr-([a-z]+)([0-9]+)@<hostname>'' in email References and In-Reply-To headers for tracking ID detection. No admin UI write path is present.', 'Setting this allows the email collector to recognize tracking IDs in replies that were sent from an alternative hostname, enabling correct thread linking.', 'String: alternative email hostname (e.g. ''mail.example.com'') used to match Dolibarr tracking references', 1, 0, NULL, 1, '4a848fd4850fcea7ebed83060027f78bb3db4926cffc0cf16d1f5301d85457ec', 'v2', '2026-04-21T13:50:40+00:00', '["emailcollector/class/emailcollector.class.php:2037|read|} elseif (getDolGlobalString(''EMAIL_ALTERNATIVE_HOST_SIGNATURE'')) {", "emailcollector/class/emailcollector.class.php:2038|check|if (preg_match(''/dolibarr-([a-z]+)([0-9]+)@''.preg_quote(getDolGlobalString(''EMAIL_ALTERNATIVE_HOST_SIGNATURE''), ''/'').''/'', $referencesforanswer)) {", "emailcollector/class/emailcollector.class.php:2403|check|if (empty($resultsearchtrackid) && getDolGlobalString(''EMAIL_ALTERNATIVE_HOST_SIGNATURE'')) {", "emailcollector/class/emailcollector.class.php:2404|read|$resultsearchtrackid = preg_match(''/dolibarr-([a-z]+)([0-9]+)@''.preg_quote(getDolGlobalString(''EMAIL_ALTERNATIVE_HOST_SIGNATURE''), ''/'').''/'', $reference, $reg);\t// trackid found"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ENTREPOT_EXTRA_STATUS', 'string', NULL, 'product', 'Enables extended warehouse status filtering beyond the default open/closed states.', 'When set, additional warehouse statuses are available for filtering in stock views and product stock calculations. Cited in product/stock/class/entrepot.class.php and product/class/product.class.php.', 'When enabled, filtering on warehouse status is possible in stock-at-date reports and product stock queries. Disabling it restricts warehouse filtering to basic status values.', 'Truthy = extra warehouse statuses available for filtering; empty/falsy = standard statuses only', 1, 0, NULL, 1, 'd45729fa9e8bf0246764c7852aaebfd4fa6cb794fc083e56f4c002108b70d32e', 'v2', '2026-04-21T11:16:15+00:00', '["product/stock/class/entrepot.class.php:211  * Used when ENTREPOT_EXTRA_STATUS is on;", "product/class/product.class.php:6308  * If ENTREPOT_EXTRA_STATUS is set, filtering on warehouse status is possible.", "product/class/html.formproduct.class.php:310|check|if ((!getDolGlobalString(''ENTREPOT_EXTRA_STATUS'')) && ($filterstatus === \"warehouseinternal\")) {", "product/stock/stockatdate.php:167|check|if (getDolGlobalString(''ENTREPOT_EXTRA_STATUS'') && count($warehouseStatus)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ENTREPOT_WAREHOUSEINTERNAL_NOT_SELL', 'string', NULL, 'core', 'Excludes internal-only warehouses from the product/warehouse selector used when adding a sales line, restricting stock selection to open warehouses only.', 'Used in core/tpl/objectline_create.tpl.php:293: for a non-supplier (buyer) product line, if this constant is truthy, $statuswarehouse is limited to ''warehouseopen'' instead of the default ''warehouseopen,warehouseinternal''.', 'Enabling it hides internal-transfer warehouses from the product selection combo on sales document lines, so users cannot pick stock from internal warehouses when adding a sold product line.', 'Boolean-like: truthy restricts the product-selector warehouse filter to ''warehouseopen'' only, excluding ''warehouseinternal''.', 0, 0, NULL, 1, '965503bbd38e53c386ac3efa61e2106ef640e8c3272051800bb8c9be2245f452', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:292|$statuswarehouse = ''warehouseopen,warehouseinternal'';", "core/tpl/objectline_create.tpl.php:293|check|if (getDolGlobalString(''ENTREPOT_WAREHOUSEINTERNAL_NOT_SELL'')) {", "core/tpl/objectline_create.tpl.php:294|$statuswarehouse = ''warehouseopen'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVALUATION_ADDON_PDF', 'string', NULL, 'hrm', 'Name of the PDF document model (template) used to generate PDFs for HRM evaluation objects.', 'Used as fallback model name in Evaluation''s document-generation method when $this->model_pdf is empty, hrm/class/evaluation.class.php:1027-1028, same pattern as SKILL_ADDON_PDF.', 'Changing it selects which PDF generation model class is used to build the evaluation PDF document.', 'Name of an evaluation PDF doc-generation model.', 1, 0, NULL, 1, '60387050a3aa296843095a72f66a287333a21e5ff0381752f13be2177bd2616a', 'v2', '2026-07-24T07:05:23+00:00', '["hrm/class/evaluation.class.php:1027|read|} elseif (getDolGlobalString(''EVALUATION_ADDON_PDF'')) {", "hrm/class/evaluation.class.php:1028|read|$modele = getDolGlobalString(''EVALUATION_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_ALLOW_REGISTRATION_WHEN_MAX_REACHED', 'bool', NULL, 'public', 'Provides a bypass value that allows online event registration to proceed even after the maximum attendee count has been reached, when the submitted form matches it.', 'In public/eventorganization/attendee_new.php:813, the registration form is shown if attendee count is below max, OR if !getDolGlobalString(''EVENTORGANIZATION_ALLOW_REGISTRATION_WHEN_MAX_REACHED'') is false and the constant''s value equals GETPOST(''EVENTORGANIZATION_ALLOW_REGISTRATION_WHEN_MAX_REACHED'') (a matching secret/token passed via the form/URL).', 'Setting it to a non-empty value creates a bypass: submitting the same value as a GET/POST parameter named EVENTORGANIZATION_ALLOW_REGISTRATION_WHEN_MAX_REACHED lets registration continue past the max-attendees limit.', 'String, acts like a shared secret/token compared against a GET/POST parameter of the same name.', 1, 0, NULL, 1, '327b612407eae71c240a18b12c741c8f28d4e007fffdae83f6ac3d3b5a997c9b', 'v2', '2026-07-24T07:05:23+00:00', '["public/eventorganization/attendee_new.php:813: (!getDolGlobalString(''EVENTORGANIZATION_ALLOW_REGISTRATION_WHEN_MAX_REACHED'') || (getDolGlobalString(''EVENTORGANIZATION_ALLOW_REGISTRATION_WHEN_MAX_REACHED'') == GETPOST(''EVENTORGANIZATION_ALLOW_REGISTRATION_WHEN_MAX_REACHED'')))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_CATEG_THIRDPARTY_BOOTH', 'string', NULL, 'public', 'Category (tag) automatically assigned to a third-party created via the public ''suggest a booth'' event-organization form.', 'Read in public/project/suggestbooth.php:340 as a category ID, fetched via Categorie::fetch() and then applied to the newly created/matched thirdparty with setCategoriesCommon(). Configurable in admin/eventorganization.php as a ''category:customer'' type setting.', 'Setting it tags every thirdparty that registers a booth online with this customer category, enabling automated segmentation of booth exhibitors.', 'A customer category (tag) ID, selected via admin UI (''category:''.Categorie::TYPE_CUSTOMER).', 0, 0, NULL, 1, 'f41ca2b1bf4b115c1d8bd13b13367805e307eb9f477034a4db460710062fa49d', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/suggestbooth.php:340: $resultcategory = $category->fetch(getDolGlobalInt(''EVENTORGANIZATION_CATEG_THIRDPARTY_BOOTH''));", "admin/eventorganization.php:63: ''EVENTORGANIZATION_CATEG_THIRDPARTY_BOOTH'' => array(''type'' => ''category:''.Categorie::TYPE_CUSTOMER, ''enabled'' => 1, ''css'' => ''''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_CATEG_THIRDPARTY_CONF', 'string', NULL, 'public', 'Category (tag) automatically assigned to a third-party created via the public ''suggest a conference'' event-organization form.', 'Read in public/project/suggestconference.php:340 as a category ID, fetched via Categorie::fetch() and then applied to the newly created/matched thirdparty with setCategoriesCommon(). Configurable in admin/eventorganization.php as a ''category:customer'' type setting.', 'Setting it tags every thirdparty that submits a conference proposal online with this customer category, enabling automated segmentation of conference speakers.', 'A customer category (tag) ID, selected via admin UI (''category:''.Categorie::TYPE_CUSTOMER).', 0, 0, NULL, 1, '7ecc2824907df9c80da0ad4c1d5c45f8fd75943c3efdc97e2355044bc3863db2', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/suggestconference.php:340: $resultcategory = $category->fetch(getDolGlobalInt(''EVENTORGANIZATION_CATEG_THIRDPARTY_CONF''));", "admin/eventorganization.php:62: ''EVENTORGANIZATION_CATEG_THIRDPARTY_CONF'' => array(''type'' => ''category:''.Categorie::TYPE_CUSTOMER, ''enabled'' => 1, ''css'' => ''''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_CONFERENCEORBOOTHATTENDEE_ADDON', 'string', NULL, 'eventorganization', 'Specifies the numbering module class name used to generate reference numbers for conference/booth attendee records.', 'Checked at conferenceorboothattendee.class.php:1023-1031; if unset, the code defaults to ''mod_conferenceorboothattendee_standard''. The value is used both to derive the PHP filename to include and the classname to instantiate.', 'Changing this constant switches the attendee reference numbering algorithm; if the referenced module file does not exist the numbering step will fail.', 'Empty/unset = defaults to ''mod_conferenceorboothattendee_standard''; any valid module class name string = use that module.', 1, 0, NULL, 1, '057e43aaff45f55c5eff85bf5dffd4f95fcaac36e5a0fe94b0f672bddd0535c0', 'v2', '2026-04-21T13:50:40+00:00', '["eventorganization/class/conferenceorboothattendee.class.php:1024|write|$conf->global->EVENTORGANIZATION_CONFERENCEORBOOTHATTENDEE_ADDON = ''mod_conferenceorboothattendee_standard'';", "eventorganization/class/conferenceorboothattendee.class.php:1031|read|$classname = getDolGlobalString(''EVENTORGANIZATION_CONFERENCEORBOOTHATTENDEE_ADDON'');", "eventorganization/class/conferenceorboothattendee.class.php:1030|read|$file = getDolGlobalString(''EVENTORGANIZATION_CONFERENCEORBOOTHATTENDEE_ADDON'') . \".php\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_DEFAULT_NOTE_ON_REGISTRATION', 'string', NULL, 'public', 'Provides a default public note text pre-filled in the note field of the online event attendee registration form.', 'In public/eventorganization/attendee_new.php:941-942, if getDolGlobalString(''EVENTORGANIZATION_DEFAULT_NOTE_ON_REGISTRATION'') is set, its value (with literal ''\n'' replaced by real newlines) replaces $note_public as the text shown in the registration form''s Note textarea.', 'Setting it pre-populates the public note field shown to attendees during online registration with custom default text.', 'String; literal ''\n'' sequences in the value are converted to real newlines before display.', 1, 0, NULL, 1, '9eeb047516a999eac4becbd9298d41e7ae3348e0f5e63269c07ab63c61588d59', 'v2', '2026-07-24T07:05:23+00:00', '["public/eventorganization/attendee_new.php:941: if (getDolGlobalString(''EVENTORGANIZATION_DEFAULT_NOTE_ON_REGISTRATION'')) {", "public/eventorganization/attendee_new.php:942: $notetoshow = str_replace(''\\n'', \"\\n\", getDolGlobalString(''EVENTORGANIZATION_DEFAULT_NOTE_ON_REGISTRATION''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_DISABLE_RETREIVE_THIRDPARTY_FROM_NAME', 'bool', NULL, 'public', 'Disables automatic lookup/matching of an existing thirdparty by company name + email when a new event attendee registers online.', 'In public/eventorganization/attendee_new.php:393, when no fk_soc is already known for the attendee, the code only attempts $thirdparty->fetch(0, $societe, ..., $emailcompany) to find a matching thirdparty by name+email if !getDolGlobalString(''EVENTORGANIZATION_DISABLE_RETREIVE_THIRDPARTY_FROM_NAME'').', 'Enabling it stops the public attendee registration form from trying to auto-link the new attendee to an existing thirdparty found by matching company name and email; a new/blank thirdparty association is used instead.', 'Boolean-like truthy check via getDolGlobalString().', 1, 0, NULL, 1, '2d7c0ed1e1e9f4e9c941ae5f11c51c407be806979fd47cd979e95dcdd5cf3a87', 'v2', '2026-07-24T07:05:23+00:00', '["public/eventorganization/attendee_new.php:393: if (!getDolGlobalString(''EVENTORGANIZATION_DISABLE_RETREIVE_THIRDPARTY_FROM_NAME'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_ENABLE_PUBLIC', 'bool', NULL, 'admin', 'Was intended to gate display of the public subscription-form links block on the event organization admin page, but the check is currently commented out in source.', 'In admin/eventorganization_public.php:227 the line `//if (getDolGlobalString(''EVENTORGANIZATION_ENABLE_PUBLIC'')) {` is commented out along with its matching closing brace, so the public-links block below it (BlankSubscriptionForm, QR code URL) is always displayed unconditionally regardless of this constant''s value.', 'Currently has no effect: since the guarding `if` is commented out in this Dolibarr version, setting this constant does not change behavior in the code read.', 'no functional effect observed (guard code commented out); presumably intended true/1 = show public links block.', 0, 0, 'admin/eventorganization_public.php', 1, '4a5ed4c0753767a1ad897083b4c281e06dc58034668a3a994f89d1a7d2ad50dd', 'v2', '2026-07-24T07:05:23+00:00', '["admin/eventorganization_public.php:227  //if (getDolGlobalString(''EVENTORGANIZATION_ENABLE_PUBLIC'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_FILTERATTENDEES_CAT', 'string', NULL, 'eventorganization', 'Restricts the third-party (''fk_soc'') selector for conference/booth attendees to companies belonging to a given category (category rowid).', 'Used in eventorganization/class/conferenceorboothattendee.class.php:250-251, where the field type SQL filter for ''fk_soc'' is extended with a subquery on llx_categorie_societe filtered by fk_categorie = this constant''s value.', 'Setting it to a category rowid limits which third parties can be chosen as event attendees to those tagged with that category; changing/removing it changes the selectable company list.', 'Integer category rowid (fk_categorie of llx_categorie_societe); empty/unset applies no category filter.', 1, 0, NULL, 1, 'f52870bb573ccb052feb55b55cf953a497ea3eb256748ba1788d749833f426f4', 'v2', '2026-07-24T07:05:23+00:00', '["eventorganization/class/conferenceorboothattendee.class.php:250: if (getDolGlobalString(''EVENTORGANIZATION_FILTERATTENDEES_CAT'')) {", "eventorganization/class/conferenceorboothattendee.class.php:251: ... WHERE c.fk_categorie=''.(int) $conf->global->EVENTORGANIZATION_FILTERATTENDEES_CAT.'')'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_FILTERATTENDEES_TYPE', 'string', NULL, 'eventorganization', 'Restricts the third-party (''fk_soc'') selector for conference/booth attendees to companies matching a given client/customer type code.', 'Used in eventorganization/class/conferenceorboothattendee.class.php:253-256; if set and not empty string or ''-1'', the fk_soc field''s SQL filter is extended with ''client:=:<value>''.', 'Setting it to a customer-type value restricts the attendee company selector to that client type; leaving it empty or ''-1'' disables the filter.', 'Integer client/customer type code used in the ''client'' filter; '''' or ''-1'' means no filter applied.', 1, 0, NULL, 1, '0d7926b13ab23c640283ea8d324a4ad194ea350684a7a3491b2062a9c03e9cab', 'v2', '2026-07-24T07:05:23+00:00', '["eventorganization/class/conferenceorboothattendee.class.php:254: && getDolGlobalString(''EVENTORGANIZATION_FILTERATTENDEES_TYPE'') !== ''''", "eventorganization/class/conferenceorboothattendee.class.php:255: && getDolGlobalString(''EVENTORGANIZATION_FILTERATTENDEES_TYPE'') !== ''-1'') {", "eventorganization/class/conferenceorboothattendee.class.php:256: $this->fields[''fk_soc''][''type''] .= '' AND (client:=:''.((int) getDolGlobalInt(''EVENTORGANIZATION_FILTERATTENDEES_TYPE'', 0) . '')'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_IMAGE_PUBLIC_INTERFACE', 'string', NULL, 'public', 'Stores the URL of an image displayed on the public event organization subscription and attendee pages.', 'Checked in public/eventorganization/subscriptionok.php:143 and public/eventorganization/attendee_new.php:217; when set, the image URL is rendered as an <img> tag on both pages (lines 145 and 219 respectively). No admin UI write is present.', 'Setting this constant causes a custom image to appear on the public-facing event subscription and confirmation pages; leaving it unset suppresses the image.', 'String URL of the image to display; unset/empty = no image shown.', 1, 0, NULL, 1, 'a96283fc6c6395806d22c7110ffd14fecd8291969063000128cd1108d523e2fe', 'v2', '2026-04-21T13:50:40+00:00', '["public/eventorganization/subscriptionok.php:143|check|if (getDolGlobalString(''EVENTORGANIZATION_IMAGE_PUBLIC_INTERFACE'')) {", "public/eventorganization/subscriptionok.php:145|read|print ''<img id=\"idEVENTORGANIZATION_IMAGE_PUBLIC_INTERFACE\" src=\"'' . getDolGlobalString(''EVENTORGANIZATION_IMAGE_PUBLIC_INTERFACE'').''\">'';", "public/eventorganization/attendee_new.php:217|check|if (getDolGlobalString(''EVENTORGANIZATION_IMAGE_PUBLIC_INTERFACE'')) {", "public/eventorganization/attendee_new.php:219|read|print ''<img id=\"idEVENTORGANIZATION_IMAGE_PUBLIC_INTERFACE\" src=\"'' . getDolGlobalString(''EVENTORGANIZATION_IMAGE_PUBLIC_INTERFACE'').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_SECUREKEY', 'string', NULL, 'eventorganization', 'Secret key used to compute security hashes (e.g. for booth/conference suggestion links, votes, and attendee subscription confirmation) in the event organization module.', 'Read in numerous public-facing files (26 occurrences) such as public/project/suggestbooth.php:97, public/project/suggestconference.php:97, public/project/viewandvote.php:181, public/eventorganization/subscriptionok.php:85, and public/eventorganization/attendee_new.php:145/370, always combined with dol_hash() and a context string like ''conferenceorbooth'' or ''vote''.', 'This key is combined with an id and context string via dol_hash() (md5) to produce security tokens for public event-organization links; changing it invalidates previously generated links/hashes.', NULL, 1, 0, NULL, 1, '4162db922d1959811ff0cf9faa1db08f9fba5ef876f5e20bbcc3cbda0b91593c', 'v2', '2026-07-24T06:41:12+00:00', '["$securekeytocompare = dol_hash(getDolGlobalString(''EVENTORGANIZATION_SECUREKEY'') . ''conferenceorbooth''.((int) $id), ''md5'');", "$hashedvote = dol_hash(getDolGlobalString(''EVENTORGANIZATION_SECUREKEY'').''vote''.$idvote, ''md5'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_TASK_LABEL', 'string', NULL, 'core', 'Newline-separated list of task labels auto-created as project tasks when an event-organization project is validated.', 'Read in core/triggers/interface_50_modEventOrganization_EventOrganization.class.php:83-84 on the PROJECT_VALIDATE trigger; only applied if the project has usage_organize_event set; the string is split with explode("\n", ...) into one Task per line.', 'Setting this creates one project Task per line of text automatically whenever an event-organization project is validated, using each line as the task''s label; leaving it empty skips auto-task creation.', 'String: free text, one task label per line (split on "\n").', 1, 0, NULL, 1, '619ed3a26f516696861a82ac632875cf8ea894bb43587abe1a6681232c066fca', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_50_modEventOrganization_EventOrganization.class.php:83|check|if (getDolGlobalString(''EVENTORGANIZATION_TASK_LABEL'') && !empty($object->usage_organize_event)) {", "core/triggers/interface_50_modEventOrganization_EventOrganization.class.php:84|read|$taskToDo = explode(\"\\n\", getDolGlobalString(''EVENTORGANIZATION_TASK_LABEL''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_TEMPLATE_EMAIL_AFT_SUBS_BOOTH', 'string', NULL, 'public', 'ID of the email template used to notify a registrant after they subscribe to a conference/event booth.', 'Read via getDolGlobalInt() in public/payment/paymentok.php:1853 with an inline comment ''Email sent after registration for a Booth''; the ID is used to fetch the template via $formmail->getEMailTemplate() and, if found, send the confirmation email. Configured in the admin UI at admin/eventorganization.php:69 as an ''emailtemplate:conferenceorbooth'' type field.', 'Setting it to a valid email template ID enables sending a specific templated confirmation email after a successful booth subscription payment; if empty/0, no such templated email is sent (per the surrounding !empty($idoftemplatetouse) check).', 'Integer: the rowid of an email template of type ''conferenceorbooth''; 0/unset disables the templated email.', 0, 0, NULL, 1, '8b7c9656e4af943b903af0b3c4c9ec052d0857903d82203c6e6b0509e0797ac6', 'v2', '2026-07-24T07:05:23+00:00', '["public/payment/paymentok.php:1853|read|$idoftemplatetouse = getDolGlobalInt(''EVENTORGANIZATION_TEMPLATE_EMAIL_AFT_SUBS_BOOTH'');\t// Email sent after registration for a Booth", "admin/eventorganization.php:69|''EVENTORGANIZATION_TEMPLATE_EMAIL_AFT_SUBS_BOOTH'' => array(''type'' => ''emailtemplate:conferenceorbooth'', ''enabled'' => 1, ''css'' => ''''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_TEMPLATE_EMAIL_AFT_SUBS_EVENT', 'string', NULL, 'public', 'Holds the id of the email template used to notify an attendee after they subscribe/register to an event (conference/booth).', 'In public/eventorganization/attendee_new.php:668 and public/payment/paymentok.php:1616 (comment: ''Email to send for Event organization registration''), the constant''s integer value ($labeltouse / $idoftemplatetouse) is passed to $formmail->getEMailTemplate(...) to fetch the template content, used to send the post-subscription email.', 'Setting it to a valid email-template id determines which template is used for the automatic post-registration email sent after event subscription and after payment confirmation; if empty, no template lookup/default message is applied.', 'Integer id referencing a row in the email templates table (c_email_templates), context ''eventorganization_send'' / ''conferenceorbooth''.', 1, 0, NULL, 1, '4ec05f164b175d1cbf2a0e797890e751f74180b8f44ff30169a4c16dba03ed0f', 'v2', '2026-07-24T07:05:23+00:00', '["public/payment/paymentok.php:1616: $idoftemplatetouse = getDolGlobalInt(''EVENTORGANIZATION_TEMPLATE_EMAIL_AFT_SUBS_EVENT'');\t// Email to send for Event organization registration", "public/eventorganization/attendee_new.php:668: $labeltouse = getDolGlobalInt(''EVENTORGANIZATION_TEMPLATE_EMAIL_AFT_SUBS_EVENT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_TEMPLATE_EMAIL_ASK_BOOTH', 'string', NULL, 'public', 'Email template used to send the confirmation email after a booth request is submitted on the public suggest-a-booth form.', 'Read in public/project/suggestbooth.php:520 as $labeltouse, passed as a template ID to FormMail::getEMailTemplate() for the ''conferenceorbooth'' email type. Configurable in admin/eventorganization.php as an ''emailtemplate:conferenceorbooth'' type setting.', 'Setting it selects which pre-defined email template is sent to the requester confirming their booth request; if empty, no default subject/message is generated from a template.', 'An email template ID of type ''conferenceorbooth'', selected via admin UI.', 0, 0, NULL, 1, 'bc0df405fe8ee66f3880ca1fbd3587dd6c0ce3328c3eb3096d4ca9ea8c9ebf89', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/suggestbooth.php:520: $labeltouse = getDolGlobalInt(''EVENTORGANIZATION_TEMPLATE_EMAIL_ASK_BOOTH'');", "admin/eventorganization.php:68: ''EVENTORGANIZATION_TEMPLATE_EMAIL_ASK_BOOTH'' => array(''type'' => ''emailtemplate:conferenceorbooth'', ''enabled'' => 1, ''css'' => ''''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EVENTORGANIZATION_TEMPLATE_EMAIL_ASK_CONF', 'string', NULL, 'public', 'Email template used to send the confirmation email after a conference proposal is submitted on the public suggest-a-conference form.', 'Read in public/project/suggestconference.php:457 as $labeltouse, passed as a template ID to FormMail::getEMailTemplate() for the ''conferenceorbooth'' email type. Configurable in admin/eventorganization.php as an ''emailtemplate:conferenceorbooth'' type setting.', 'Setting it selects which pre-defined email template is sent to the requester confirming their conference proposal; if empty, no default subject/message is generated from a template.', 'An email template ID of type ''conferenceorbooth'', selected via admin UI.', 0, 0, NULL, 1, 'df7355e2dd12acd2dd09eb783320d2ec1f120d8c3ef3caccb378a48afe033469', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/suggestconference.php:457: $labeltouse = getDolGlobalInt(''EVENTORGANIZATION_TEMPLATE_EMAIL_ASK_CONF'');", "admin/eventorganization.php:67: ''EVENTORGANIZATION_TEMPLATE_EMAIL_ASK_CONF'' => array(''type'' => ''emailtemplate:conferenceorbooth'', ''enabled'' => 1, ''css'' => ''''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPEDITION_ADDON_NUMBER', 'string', NULL, 'admin', 'Selects the active numbering module (addon) for shipment/expedition reference number generation.', 'Configured via admin/expedition.php (UI writes at lines 65 and 167). If not set, it defaults to ''mod_expedition_safor'' (line 65). The value is used in expedition/class/expedition.class.php:384-385 to load the corresponding module file and class.', 'Changing this constant switches the numbering scheme for all future shipment references. The chosen module file must exist; otherwise reference generation will fail.', 'Name of a valid expedition numbering module (e.g. ''mod_expedition_safor''); default is ''mod_expedition_safor''.', 0, 0, 'admin/expedition.php|admin/expedition.php|admin/expedition.php|admin/expedition.php', 1, '703c49fc57421e432629167b763bbb9874ccac2adae26de84a23984636ea108f', 'v2', '2026-04-21T13:50:40+00:00', '["admin/expedition.php:64|check|if (!getDolGlobalString(''EXPEDITION_ADDON_NUMBER'')) {", "admin/expedition.php:65|write|$conf->global->EXPEDITION_ADDON_NUMBER = ''mod_expedition_safor'';", "expedition/class/expedition.class.php:384|read|$file = getDolGlobalString(''EXPEDITION_ADDON_NUMBER'') . \".php\";", "expedition/class/expedition.class.php:385|read|$classname = getDolGlobalString(''EXPEDITION_ADDON_NUMBER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPEDITION_ADDON_PDF', 'string', NULL, 'admin', 'Selects the active PDF template module for shipment/expedition document generation.', 'Configured via admin/expedition.php (UI writes at lines 155 and 158). The value is read in expedition/class/expedition.class.php:3316-3317 to determine which PDF model to use, and displayed in a select list on expedition/card.php:1627.', 'Changing this constant switches the PDF template applied to all newly generated shipment documents. The selected module must be available; otherwise document generation falls back or fails.', 'Name of a valid expedition PDF module (e.g. a template slug string); empty to use the default.', 0, 0, 'admin/expedition.php|admin/expedition.php|admin/expedition.php|admin/expedition.php|admin/expedition.php', 1, '9da92a6713aebd275cbfd57ee2cbc2508c7cd63c46064a2f56c1489faa15afb2', 'v2', '2026-04-21T13:50:40+00:00', '["admin/expedition.php:155|write|if (dolibarr_set_const($db, \"EXPEDITION_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "expedition/class/expedition.class.php:3316|read|} elseif (getDolGlobalString(''EXPEDITION_ADDON_PDF'')) {", "expedition/class/expedition.class.php:3317|read|$modele = getDolGlobalString(''EXPEDITION_ADDON_PDF'');", "expedition/card.php:1627|read|print $form->selectarray(''model'', $list, getDolGlobalString(''EXPEDITION_ADDON_PDF''), 0, 0, 0, '''', 0, 0, 0, '''', ''widthcentpercentminusx'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPEDITION_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Comma-separated list of directories scanned for shipment (expedition) ODT document templates.', 'Read and trimmed in core/modules/expedition/doc/doc_generic_shipment_odt.modules.php:116, following the same directory-scan pattern as the other *_ADDON_PDF_ODT_PATH constants (DOL_DATA_ROOT token substitution, dol_dir_list scan for .odt/.ods files).', 'Adding directories here makes additional ODT templates available for shipment document generation.', 'Comma or newline separated directory paths; ''DOL_DATA_ROOT'' token replaced by the actual data root.', 1, 0, NULL, 1, '38e37d985618e35f5dced0fef751e8ddf96850d6773d454cb810f14382978f50', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expedition/doc/doc_generic_shipment_odt.modules.php:116|read|$odtPath = trim(getDolGlobalString(''EXPEDITION_ADDON_PDF_ODT_PATH''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPEDITION_ALLOW_ONLINESIGN', 'bool', NULL, 'core', 'Enables the online signature feature for shipments (expeditions), both in email substitution tags and on the shipment card.', 'In core/lib/functions.lib.php:10841 it gates filling `__ONLINE_SIGN_URL__` via getOnlineSignatureUrl() for shipping objects; in expedition/card.php:3885 it gates whether the ''Show online signature link'' block is printed on the shipment card; exposed via admin/expedition.php:498 as `ajax_constantonoff(''EXPEDITION_ALLOW_ONLINESIGN'', ...)` with a warning message about Dolistore.', 'Enabling it lets customers digitally sign a shipment online (link shown on the card and usable in email templates); the admin toggle displays a warning referencing a Dolistore-related dependency for the signature feature.', 'Boolean-like toggle, set via the shipment module''s admin setup page (ajax on/off).', 0, 0, NULL, 1, 'f2c849955efa4fcc16e775b785c0ac3b5a1cb5400984f4ef2127acd30f54c4ae', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:10841|check|if (getDolGlobalInt(''EXPEDITION_ALLOW_ONLINESIGN'')) {", "expedition/card.php:3885|read|$useonlinesignature = getDolGlobalInt(''EXPEDITION_ALLOW_ONLINESIGN'');", "admin/expedition.php:498: print ajax_constantonoff(''EXPEDITION_ALLOW_ONLINESIGN'', array(), null, 0, 0, 0, 2, 0, 1, ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPEDITION_RIBERA_MASK', 'string', NULL, 'core', 'Stores the numbering mask (ref format) for the ''Ribera'' shipment numbering model.', 'Written via a hidden form field ''maskconstexpedition'' => ''EXPEDITION_RIBERA_MASK'' in core/modules/expedition/mod_expedition_ribera.php:75, displayed/edited at line 91, and read at line 139: `$mask = getDolGlobalString(''EXPEDITION_RIBERA_MASK''); if (empty($mask)) { $this->error = ''NotConfigured''; return 0; }`.', 'Changing it changes the reference mask/pattern used to generate shipment numbers under the Ribera numbering model; if empty, the model reports itself as ''NotConfigured'' and generates no ref.', 'Free-form generic numbering mask string (Dolibarr ''GenericNumRefModelDesc'' mask syntax), configured through the numbering model''s own admin form (not the general admin/*.php pages).', 0, 0, NULL, 1, '7619cb66ea3ce14de3644e06e857f287609c3e4d848e935fe94b3e487c327fd9', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expedition/mod_expedition_ribera.php:139: $mask = getDolGlobalString(''EXPEDITION_RIBERA_MASK'');", "core/modules/expedition/mod_expedition_ribera.php:141-143: if (empty($mask)) { $this->error = ''NotConfigured''; return 0; }", "core/modules/expedition/mod_expedition_ribera.php:91: ...name=\"maskexpedition\" value=\"''.getDolGlobalString(''EXPEDITION_RIBERA_MASK'').''\"..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_ADDON', 'string', NULL, 'expensereport', 'Selects the numbering addon module used to generate expense report reference numbers.', 'Set via admin/expensereport.php:156 and read in expensereport/class/expensereport.class.php:1744-1748 to load the numbering class file and instantiate it for reference generation.', 'Changing this value switches the numbering scheme for expense report references; an incorrect value will cause reference generation to fail.', 'String; the class name (without .php extension) of a numbering addon in the expense report module.', 0, 0, 'admin/expensereport.php|admin/expensereport.php', 1, 'f1115bf1c844bf33bbaaaaf89707a14722d71c8f650a99d9eaa6f1a1621b0a97', 'v2', '2026-04-21T13:29:58+00:00', '["admin/expensereport.php:156|write|dolibarr_set_const($db, \"EXPENSEREPORT_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "expensereport/class/expensereport.class.php:1744|check|if (getDolGlobalString(''EXPENSEREPORT_ADDON'')) {", "expensereport/class/expensereport.class.php:1747|read|$file = getDolGlobalString(''EXPENSEREPORT_ADDON'') . \".php\";", "expensereport/class/expensereport.class.php:1748|read|$classname = getDolGlobalString(''EXPENSEREPORT_ADDON'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_ADDON_PDF', 'string', NULL, 'admin', 'Selects the active PDF document template addon used to generate expense report PDF documents.', 'Set and managed via admin/expensereport.php (lines 129-144) with dolibarr_set_const and dolibarr_del_const. Read in expensereport/class/expensereport.class.php:2488 to determine which PDF class to instantiate.', 'Changing this value switches the PDF layout for expense reports; deleting the constant reverts to the system default template.', 'String; name of an expense report PDF addon model available in the system.', 0, 0, 'admin/expensereport.php|admin/expensereport.php|admin/expensereport.php|admin/expensereport.php|admin/expensereport.php|admin/expensereport.php|admin/expensereport.php', 1, '055a9651934770e80f65f104a72d8ad028f51453b9b368f2073d5bf582c05f73', 'v2', '2026-04-21T13:29:58+00:00', '["admin/expensereport.php:141|write|if (dolibarr_set_const($db, \"EXPENSEREPORT_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "admin/expensereport.php:144|write|$conf->global->EXPENSEREPORT_ADDON_PDF = $value;", "expensereport/class/expensereport.class.php:2488|read|} elseif (getDolGlobalString(''EXPENSEREPORT_ADDON_PDF'')) {", "admin/expensereport.php:413|check|if (getDolGlobalString(''EXPENSEREPORT_ADDON_PDF'') == \"$name\") {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_ALLOW_OVERLAPPING_PERIODS', 'bool', NULL, 'expensereport', 'Controls whether a user is allowed to create an expense report whose date period overlaps an existing one.', 'Checked in expensereport/card.php:316 during expense report creation; when false (default), periodExists() is called and an ''ErrorDoubleDeclaration'' error blocks creation if an overlapping report is found.', 'Setting it true disables the overlap check, allowing two expense reports with overlapping date_debut/date_fin for the same user.', 'Boolean: true/1 allows overlapping periods (skips the duplicate/overlap check); false/unset (default) blocks overlapping periods.', 0, 0, NULL, 1, 'a269cac475a20c18bf1dee6eb66e016abed750071165b3771aeb470d7d7f8c46', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/card.php:316|check|if (!$error && !getDolGlobalString(''EXPENSEREPORT_ALLOW_OVERLAPPING_PERIODS'')) {", "expensereport/card.php: setEventMessages($langs->trans(\"ErrorDoubleDeclaration\")..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_ASK_PAYMENTMODE_ON_CREATION', 'string', NULL, 'expensereport', 'Controls whether the payment method field is shown when creating or editing an expense report.', 'Checked at expensereport/card.php:1545, :1665, and :1822; the payment-mode UI element is rendered only when this constant is set.', 'Enabling this constant displays the payment method selector on expense report creation and edit views; disabling it hides that field.', 'Empty/unset = payment mode field hidden; any truthy value = payment mode field shown on creation/edit.', 1, 0, NULL, 1, 'c2966e09ede8708a4d80faabce3ddb8cc15b9a38e4f957973a36087275b7b8e4', 'v2', '2026-04-21T13:50:40+00:00', '["expensereport/card.php:1545|check|if (getDolGlobalString(''EXPENSEREPORT_ASK_PAYMENTMODE_ON_CREATION'')) {", "expensereport/card.php:1665|check|if (getDolGlobalString(''EXPENSEREPORT_ASK_PAYMENTMODE_ON_CREATION'')) {", "expensereport/card.php:1822|check|if (getDolGlobalString(''EXPENSEREPORT_ASK_PAYMENTMODE_ON_CREATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_BLOCK_LINE_CREATION_IF_NOT_BETWEEN_DATES', 'string', NULL, 'admin', 'Blocks the creation of expense report lines when the line date falls outside the report''s defined date range.', 'Configured via admin/expensereport.php. When active, two guards in expensereport/card.php (lines 1216 and 1382) check this constant and prevent line additions if the date is out of range. The admin UI offers a yes/no selector for this option.', 'Enabling this setting enforces date discipline on expense reports, preventing users from adding lines with dates outside the report period. Disabling allows lines regardless of date.', '0 = disabled (no date range enforcement); 1 = enabled (line creation blocked if date is out of range)', 0, 0, 'admin/expensereport.php|admin/expensereport.php', 1, 'ed9dc066c515cc25f6d1622aa7c11669614b1305d2375b146662d8966f9da5ef', 'v2', '2026-04-21T13:29:58+00:00', '["admin/expensereport.php:524|read|print $form->selectyesno(''EXPENSEREPORT_BLOCK_LINE_CREATION_IF_NOT_BETWEEN_DATES'', getDolGlobalString(''EXPENSEREPORT_BLOCK_LINE_CREATION_IF_NOT_BETWEEN_DATES'') ? 1 : 0, 1);", "expensereport/card.php:1216|check|if (getDolGlobalString(''EXPENSEREPORT_BLOCK_LINE_CREATION_IF_NOT_BETWEEN_DATES'')) {", "expensereport/card.php:1382|check|if (getDolGlobalString(''EXPENSEREPORT_BLOCK_LINE_CREATION_IF_NOT_BETWEEN_DATES'')) {", "admin/expensereport.php:178|write|$res6 = dolibarr_set_const($db, ''EXPENSEREPORT_BLOCK_LINE_CREATION_IF_NOT_BETWEEN_DATES'', intval($linesblocked), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_CALCULATE_MILEAGE_EXPENSE_COEFFICIENT_ON_CURRENT_YEAR', 'string', NULL, 'expensereport', 'Enables computing the mileage expense coefficient based on cumulative mileage for the current year only.', 'Checked in expensereport/class/expensereport.class.php:2770 inside computeTotalkm(): `if (getDolGlobalInt(''EXPENSEREPORT_CALCULATE_MILEAGE_EXPENSE_COEFFICIENT_ON_CURRENT_YEAR'')) { $arrayDate = dol_getdate(dol_now()); ... }` which then restricts the cumulative mileage SQL query to the current year''s data.', 'Enabling it changes the mileage tier/coefficient calculation to reset each year (based on current-year cumulative mileage) rather than an all-time cumulative total.', 'Boolean-like: truthy restricts the cumulative-mileage lookup used for the coefficient to the current year.', 0, 0, NULL, 1, '28acf6b9fd6009ecc4d39f57cf963c178f1a6fe284fe2c064b0c2c77aaca097f', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/class/expensereport.class.php:2770: if (getDolGlobalInt(''EXPENSEREPORT_CALCULATE_MILEAGE_EXPENSE_COEFFICIENT_ON_CURRENT_YEAR'')) {", "expensereport/class/expensereport.class.php:2771: $arrayDate = dol_getdate(dol_now());"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_DEFAULT_VALIDATOR', 'string', NULL, 'expensereport', 'Forces a specific user as the default preselected approver/validator on new expense reports.', 'Read in expensereport/card.php:1531-1532 with the inline comment ''Can force default approver''; it overrides the normal default (the user''s own hierarchical supervisor) unless overridden again by a POSTed fk_user_validator.', 'Setting it to a user id changes the preselected approver shown in the expense report creation form for all users, instead of each user''s own supervisor.', 'A user id (integer) to force as default validator; comment: ''Can force default approver''.', 0, 0, NULL, 1, '421f2a104ceeaf5c9f0047e0b6805b57244f4b0c38ccd05df6c9fc6f56ecb12f', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/card.php:1531|check|if (getDolGlobalString(''EXPENSEREPORT_DEFAULT_VALIDATOR'')) {", "expensereport/card.php:1532|read|$defaultselectuser = getDolGlobalString(''EXPENSEREPORT_DEFAULT_VALIDATOR''); // Can force default approver"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_DEFAULT_VALIDATOR_UNCHANGEABLE', 'string', NULL, 'expensereport', 'Makes the default approver combo box read-only (disabled) on the expense report form, preventing the user from picking a different validator.', 'Used in expensereport/card.php:1537 as part of the disabled-flag expression for the select_dolusers() approver dropdown: disabled unless $defaultselectuser is empty or this constant is false.', 'Enabling it (together with a non-empty default validator) locks the approver field so the submitting user cannot change who will validate their expense report.', 'Boolean: true/1 makes the validator selector unchangeable when a default validator is set.', 0, 0, NULL, 1, 'f3089d49c62614aef1ef70c0c16d385f8165c7255784c07b6611bdab0b6911b9', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/card.php:1537|check|$s = $form->select_dolusers($defaultselectuser, \"fk_user_validator\", 1, null, ((empty($defaultselectuser) || !getDolGlobalString(''EXPENSEREPORT_DEFAULT_VALIDATOR_UNCHANGEABLE'')) ? "]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_DISABLE_ATTACHMENT_ON_LINES', 'bool', NULL, 'expensereport', 'Disables the file attachment control on individual expense report lines.', 'Checked in expensereport/tpl/expensereport_linktofile.tpl.php:33 and at expensereport/card.php:2398, 2538, and 2554; the attachment UI element is rendered only when this constant is NOT set.', 'Enabling this constant (setting to a truthy value) hides the per-line attachment widget across expense report views; leaving it unset preserves the attachment functionality.', 'Empty/unset = attachments on lines enabled; any truthy value = attachments on lines disabled.', 1, 0, NULL, 1, '0c56199fb6bea9a955b578601f4662a6fad63ef8183b45b7a7183b493c9b7d0a', 'v2', '2026-04-21T13:50:40+00:00', '["expensereport/tpl/expensereport_linktofile.tpl.php:33|check|if (!getDolGlobalString(''EXPENSEREPORT_DISABLE_ATTACHMENT_ON_LINES'')) {", "expensereport/card.php:2398|check|if (!getDolGlobalString(''EXPENSEREPORT_DISABLE_ATTACHMENT_ON_LINES'')) {", "expensereport/card.php:2538|check|if (!getDolGlobalString(''EXPENSEREPORT_DISABLE_ATTACHMENT_ON_LINES'')) {", "expensereport/card.php:2554|check|if (!getDolGlobalString(''EXPENSEREPORT_DISABLE_ATTACHMENT_ON_LINES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_DRAFT_WATERMARK', 'string', NULL, 'admin', 'Stores the watermark text printed on draft expense report PDF documents.', 'Set via admin/expensereport.php:164 with a free-text input field (admin/expensereport.php:498). Applied in core/modules/expensereport/doc/pdf_standard_expensereport.modules.php:688 via pdf_watermark when the expense report status is 0 (draft).', 'Setting this constant causes the specified text to be rendered as a watermark on draft expense report PDFs; leaving it empty suppresses the watermark.', 'String; any text to display as a watermark on draft PDFs.', 0, 0, 'admin/expensereport.php|admin/expensereport.php', 1, '744deda6864e8225abd2bcf65400ff6a12bc6ddd9e0638373ecd0f96503df3a8', 'v2', '2026-04-21T13:29:58+00:00', '["admin/expensereport.php:164|write|$res2 = dolibarr_set_const($db, \"EXPENSEREPORT_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "admin/expensereport.php:498|read|print ''<input class=\"flat minwidth200\" type=\"text\" name=\"EXPENSEREPORT_DRAFT_WATERMARK\" value=\"''.dol_escape_htmltag(getDolGlobalString(''EXPENSEREPORT_DRAFT_WATERMARK'')).''\">'';", "core/modules/expensereport/doc/pdf_standard_expensereport.modules.php:687|check|if ($object->fk_statut == 0 && getDolGlobalString(''EXPENSEREPORT_DRAFT_WATERMARK'')) {", "core/modules/expensereport/doc/pdf_standard_expensereport.modules.php:688|read|pdf_watermark($pdf, $outputlangs, $this->page_hauteur, $this->page_largeur, ''mm'', $conf->global->EXPENSEREPORT_DRAFT_WATERMARK);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_FILE_IS_REQUIRED', 'string', NULL, 'expensereport', 'Controls whether a supporting document/file is mandatory when creating or validating an expense report line.', 'Read in expensereport/card.php:140 into $fileRequired, alongside the analogous EXPENSEREPORT_PROJECT_IS_REQUIRED check for the project field, on the expense report card page.', 'Enabling it enforces that a file must be attached to the expense report, otherwise the form/validation is expected to block submission.', 'Exact behavior unclear from code alone; value is read as a string/flag via getDolGlobalString.', 0, 0, NULL, 1, '97d37cd88e5a7722fcee979d33cc011ceb9b7bda52cc7e85c5b4302e9961590b', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/card.php:140|read|$fileRequired = getDolGlobalString(''EXPENSEREPORT_FILE_IS_REQUIRED'');", "expensereport/card.php: $projectRequired = isModEnabled(''project'') && getDolGlobalString(''EXPENSEREPORT_PROJECT_IS_REQUIRED'');"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_FORCE_LINE_AMOUNTS_INCLUDING_TAXES_ONLY', 'string', NULL, 'admin', 'Forces expense report line amounts to be entered inclusive of taxes only, disabling the tax-exclusive unit price field.', 'Configured via admin/expensereport.php. When enabled, the tax-exclusive unit price input is rendered disabled on expense report lines (expensereport/card.php:1715). The admin UI uses a yes/no selector to toggle the value (admin/expensereport.php:518).', 'Enabling this setting removes the tax-exclusive price field from expense report entry, ensuring all amounts entered already include taxes. Disabling restores the standard dual-amount input.', '0 = disabled (both inclusive and exclusive amounts allowed); 1 = enabled (only tax-inclusive amounts accepted)', 0, 0, 'admin/expensereport.php|admin/expensereport.php', 1, 'dfc658164aff38c4bebfa9e09b6cebcd60de23a867a479a61647037a620cdec1', 'v2', '2026-04-21T13:29:58+00:00', '["admin/expensereport.php:518|read|print $form->selectyesno(''EXPENSEREPORT_FORCE_LINE_AMOUNTS_INCLUDING_TAXES_ONLY'', getDolGlobalString(''EXPENSEREPORT_FORCE_LINE_AMOUNTS_INCLUDING_TAXES_ONLY'') ? 1 : 0, 1);", "expensereport/card.php:1715|read|$taxlessUnitPriceDisabled = getDolGlobalString(''EXPENSEREPORT_FORCE_LINE_AMOUNTS_INCLUDING_TAXES_ONLY'') ? '' disabled'' : '''';", "expensereport/card.php:2754|check|if (getDolGlobalString(''EXPENSEREPORT_FORCE_LINE_AMOUNTS_INCLUDING_TAXES_ONLY'')) {", "admin/expensereport.php:175|write|$res5 = dolibarr_set_const($db, ''EXPENSEREPORT_FORCE_LINE_AMOUNTS_INCLUDING_TAXES_ONLY'', intval($amounts), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated expense report documents.', 'Written from admin/expensereport.php:161 via dolibarr_set_const() when the admin saves the expense report module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated expense report documents; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/expensereport.php', 1, '4d0bd27d26a73b31da85496147dfc4cc4bb60a06f646983ea7994079ec7575e6', 'v2', '2026-07-24T07:05:23+00:00', '["admin/expensereport.php:161|write|$res1 = dolibarr_set_const($db, \"EXPENSEREPORT_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_LINES_SORTED_BY_ROWID', 'string', NULL, 'expensereport', 'Changes the sort order of expense report lines when fetched: by rowid instead of by date.', 'Checked in expensereport/class/expensereport.class.php:1146: `if (getDolGlobalString(''EXPENSEREPORT_LINES_SORTED_BY_ROWID'')) { $sql .= '' ORDER BY de.rang ASC, de.rowid ASC''; } else { $sql .= '' ORDER BY de.rang ASC, de.date ASC''; }`.', 'When enabled, expense report detail lines are ordered by rang then rowid instead of the default rang then date ordering.', 'Boolean-like: any truthy value switches ORDER BY from ''rang ASC, date ASC'' to ''rang ASC, rowid ASC''.', 0, 0, NULL, 1, 'fae3a30a9b3b1266fb1be178695b9e61b1363068e8b0140203b0d503018fa3c7', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/class/expensereport.class.php:1146: if (getDolGlobalString(''EXPENSEREPORT_LINES_SORTED_BY_ROWID'')) {", "expensereport/class/expensereport.class.php:1147: $sql .= '' ORDER BY de.rang ASC, de.rowid ASC'';", "expensereport/class/expensereport.class.php:1149: $sql .= '' ORDER BY de.rang ASC, de.date ASC'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_NO_DEFAULT_VAT', 'string', NULL, 'expensereport', 'Disables automatic VAT-rate autodetection on expense report lines, forcing a ''none'' fallback instead.', 'Checked in expensereport/card.php:2664, where enabling it sets $conf->global->MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS = ''none'' with the inline comment ''If option to have no default VAT on expense report is on, we force MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS''.', 'Enabling it means expense report VAT selection will not fall back to an autodetected default rate; instead the VAT-autodetect-failure fallback is forced to ''none'', leaving the VAT field unset by default.', 'Boolean: true/1 forces no default VAT (sets MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS to ''none'' for the line).', 0, 0, NULL, 1, '5a3243339b13171ce533a0d9956f7c5abc5079aead8a141a312e10b86190ba44', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/card.php:2664|check|if (getDolGlobalString(''EXPENSEREPORT_NO_DEFAULT_VAT'')) {", "expensereport/card.php: // If option to have no default VAT on expense report is on, we force MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_OVERRIDE_VAT', 'string', NULL, 'core', 'Allows overriding the VAT selection on expense reports even when the seller''s VAT option is disabled.', 'Checked at core/class/html.form.class.php:7581. The comments at :7578–:7579 describe it as ''a strange option that allow to override/enable VAT regardless of seller vat option - needed for expense report''. When unset, VAT selection is disabled when the seller does not use VAT.', 'Enabling this constant forces the VAT selector to remain active on expense report lines regardless of the company VAT configuration. Disabling (leaving unset) hides VAT selection when the seller is not subject to VAT.', 'Truthy = enable VAT override on expense reports; empty/unset = respect seller VAT setting.', 1, 0, NULL, 1, '2e11728c879421e0293c60e1fdd445fe9d4b2aa26b1190efaed648ea23d70703', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:7578  // When we are seller and we do not use VAT, we want to force to disable VAT selection, except if EXPENSEREPORT_OVERRIDE_VAT is set", "core/class/html.form.class.php:7579  // EXPENSEREPORT_OVERRIDE_VAT is a strange option that allow to override/enable VAT regardless of sellet vat option - needed for expense report if", "core/class/html.form.class.php:7581|check|if (!getDolGlobalString(''EXPENSEREPORT_OVERRIDE_VAT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_PREFILL_DATES_WITH_CURRENT_MONTH', 'string', NULL, 'admin', 'Pre-fills the expense report date range fields with the current month''s start and end dates.', 'Set via admin/expensereport.php:172 with a yes/no selector (admin/expensereport.php:512). Checked in expensereport/card.php:86 to auto-populate date fields when creating a new expense report.', 'Enabling this constant automatically fills in the current month date range on new expense reports, reducing data entry effort; disabling it leaves the date fields blank.', 'Yes/no integer (1=prefill current month, 0=leave blank); set via selectyesno in the admin UI.', 0, 0, 'admin/expensereport.php|admin/expensereport.php', 1, '7acc5055381c4e5734cb007908a8f02460a84c92dc9eec244ca3500789bf6c10', 'v2', '2026-04-21T13:29:58+00:00', '["admin/expensereport.php:172|write|$res4 = dolibarr_set_const($db, ''EXPENSEREPORT_PREFILL_DATES_WITH_CURRENT_MONTH'', intval($dates), ''chaine'', 0, '''', $conf->entity);", "admin/expensereport.php:512|read|print $form->selectyesno(''EXPENSEREPORT_PREFILL_DATES_WITH_CURRENT_MONTH'', getDolGlobalString(''EXPENSEREPORT_PREFILL_DATES_WITH_CURRENT_MONTH'') ? 1 : 0, 1);", "expensereport/card.php:86|check|if (getDolGlobalString(''EXPENSEREPORT_PREFILL_DATES_WITH_CURRENT_MONTH'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_PROJECT_IS_REQUIRED', 'string', NULL, 'admin', 'Makes the project field mandatory on expense report entries when the project module is enabled.', 'Set via admin/expensereport.php:168 with a yes/no selector (admin/expensereport.php:505). Read in expensereport/card.php:140 to set $projectRequired, which gates project field validation.', 'Enabling this constant forces users to assign a project to every expense report; disabling it makes the project field optional.', 'Yes/no integer (1=required, 0=optional); set via selectyesno in the admin UI.', 0, 0, 'admin/expensereport.php|admin/expensereport.php', 1, '808e7dd30b71a5ff97bf2fcc9de17e5d1effad735b537865bfde5cfd0d03dacc', 'v2', '2026-04-21T13:29:58+00:00', '["admin/expensereport.php:168|write|$res3 = dolibarr_set_const($db, ''EXPENSEREPORT_PROJECT_IS_REQUIRED'', GETPOSTINT(''EXPENSEREPORT_PROJECT_IS_REQUIRED''), ''chaine'', 0, '''', $conf->entity);", "admin/expensereport.php:505|read|print $form->selectyesno(''EXPENSEREPORT_PROJECT_IS_REQUIRED'', getDolGlobalString(''EXPENSEREPORT_PROJECT_IS_REQUIRED'') ? 1 : 0, 1);", "expensereport/card.php:140|read|$projectRequired = isModEnabled(''project'') && getDolGlobalString(''EXPENSEREPORT_PROJECT_IS_REQUIRED'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_SAND_MASK', 'string', NULL, 'core', 'Stores the numbering mask (template) used by the ''sand'' numbering module for expense report references.', 'Read/written via the admin mask-editing form in core/modules/expensereport/mod_expensereport_sand.php:93 (hidden field ''maskconst'' = ''EXPENSEREPORT_SAND_MASK'') and consumed in getNextValue() at line 140 to compute the next expense report reference; if empty, getNextValue() returns an error ''NotConfigured''.', 'Changing the mask changes the format of newly generated expense report references under the sand numbering module; an empty mask prevents generating any new reference.', 'A Dolibarr generic numbering mask string; no explicit example given in the excerpt.', 0, 0, NULL, 1, '5f839f4c00481f8824f99893ee92e0f6abc83f0085bd7252e91d1ad8053b3714', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expensereport/mod_expensereport_sand.php:93: name=\"maskconst\" value=\"EXPENSEREPORT_SAND_MASK\"", "core/modules/expensereport/mod_expensereport_sand.php:140: $mask = getDolGlobalString(''EXPENSEREPORT_SAND_MASK''); if (!$mask) { $this->error = ''NotConfigured''; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_SEND_EMAIL_ON_STATUS_PAID', 'string', NULL, 'expensereport', 'Enables sending an email notification to the expense report author when the report''s status changes to paid.', 'Checked in expensereport/card.php:1091, guarded by a comment stating a hidden constant was added because Dolibarr must never send an email without an explicit setup/confirm option (''TODO We must never send an email without a setup or confirm option...'').', 'Enabling it triggers an email to the report''s author once the expense report is marked paid; the surrounding TODO comment marks this as a workaround pending a proper setup option.', 'Boolean: true/1 enables the paid-status notification email.', 1, 0, NULL, 1, 'ae239a4dc5607acfeeeebdfb345abad53220fd789fcf820d4c2f1d456889e5e5', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/card.php:1091|check|if (getDolGlobalString(''EXPENSEREPORT_SEND_EMAIL_ON_STATUS_PAID'')) {", "expensereport/card.php: // TODO We must never send an email without a setup or confirm option to choose if email is / // sent or not. So we add a hidden constant to avoid this for the moment."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSEREPORT_USE_OLD_NUMBERING_RULE', 'bool', NULL, 'core', 'Switches the ''jade'' expense report numbering module to a legacy reference-generation algorithm for backward compatibility.', 'Checked in core/modules/expensereport/mod_expensereport_jade.php:134, comment ''For backward compatibility and restore old behavior to get ref of expense report''; when true, getNextValue() builds the ref from user name + NDF_EXPLODE_CHAR + EXPENSE_REPORT_PREFIX + a MAX(ref_number_int)+1 counter + date, instead of the module''s normal (non-legacy) logic.', 'When enabled, expense report references are generated using the old format (username_PREFIXnumber_date based on MAX(ref_number_int)) and the related constants NDF_EXPLODE_CHAR, NDF_NUM_CAR_REF and EXPENSE_REPORT_PREFIX take effect; when disabled those three constants are not read here.', 'Boolean-like: truthy activates the legacy numbering algorithm.', 1, 0, NULL, 1, '387ad6937d9547382aade3d4cc2955b509c296d27349127061f9faeea09d6cff', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expensereport/mod_expensereport_jade.php:133: // For backward compatibility and restore old behavior to get ref of expense report", "core/modules/expensereport/mod_expensereport_jade.php:134: if (getDolGlobalString(''EXPENSEREPORT_USE_OLD_NUMBERING_RULE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPENSE_REPORT_PREFIX', 'string', NULL, 'core', 'Overrides the default ''ER'' prefix used in the legacy expense report reference format.', 'Read in core/modules/expensereport/mod_expensereport_jade.php:168-169, only inside the EXPENSEREPORT_USE_OLD_NUMBERING_RULE branch: $prefix = ''ER''; if (getDolGlobalString(''EXPENSE_REPORT_PREFIX'')) { $prefix = getDolGlobalString(''EXPENSE_REPORT_PREFIX''); } used when composing the legacy ref string.', 'Changing this value replaces the ''ER'' prefix in newly generated legacy-format expense report references; only takes effect when EXPENSEREPORT_USE_OLD_NUMBERING_RULE is enabled.', 'Any string used as reference prefix; default ''ER'' if unset.', 1, 0, NULL, 1, 'a9f1e6d9333c9abe1594f758ef51b09eee28ac6b3829fc0f937edd8d550ab521', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expensereport/mod_expensereport_jade.php:167: $prefix = \"ER\";", "core/modules/expensereport/mod_expensereport_jade.php:168-169: if (getDolGlobalString(''EXPENSE_REPORT_PREFIX'')) { $prefix = getDolGlobalString(''EXPENSE_REPORT_PREFIX''); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORTS_SHARE_MODELS', 'string', NULL, 'core', 'When enabled, makes all export and import templates visible to all users regardless of who owns them.', 'Checked in imports/import.php:1486, exports/export.php:1200, and core/class/html.formother.class.php:158 and :227. The inline comment on each check reads ''EXPORTS_SHARE_MODELS means all templates are visible, whatever is owner.'' No admin UI is configured.', 'Enabling this constant removes ownership filtering on export/import templates, making every template accessible to all users.', 'Truthy (non-empty / 1) = all templates visible to all users; falsy (empty / 0) = templates filtered by owner.', 1, 0, NULL, 1, 'd7bf020fad6a5db036de773fc0c02cd98c1f94cabb3761db05be088699446c6f', 'v2', '2026-04-21T11:16:15+00:00', '["imports/import.php:1486|check|if (!getDolGlobalString(''EXPORTS_SHARE_MODELS'')) {\t// EXPORTS_SHARE_MODELS means all templates are visible, whatever is owner.", "exports/export.php:1200|check|if (!getDolGlobalString(''EXPORTS_SHARE_MODELS'')) {\t// EXPORTS_SHARE_MODELS means all templates are visible, whatever is owner.", "core/class/html.formother.class.php:158|check|if (!getDolGlobalString(''EXPORTS_SHARE_MODELS'')) {\t// EXPORTS_SHARE_MODELS means all templates are visible, whatever is owner.", "core/class/html.formother.class.php:227|check|if (!getDolGlobalString(''EXPORTS_SHARE_MODELS'')) {\t// EXPORTS_SHARE_MODELS means all templates are visible, whatever is owner."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORTTOOL_CATEGORIES', 'string', NULL, 'core', 'When set, includes category-related data in export tool definitions for products and services.', 'Checked in at least 14 occurrences across core/modules/modService.class.php and core/modules/modProduct.class.php, consistently guarding blocks that add category fields or joins to export definitions.', 'Enabling this enriches product and service exports with category data. Disabling (or leaving unset) excludes category fields from those exports.', 'Empty/unset = no category data in exports; any truthy value = category fields included in product/service exports.', 1, 0, NULL, 1, 'afdf5edf023b3d1a0ab3c73bfad3e3dd281fd4c0f08544fb8622b76b373b9108', 'v2', '2026-04-21T13:50:40+00:00', '["modService.class.php:203|if (getDolGlobalString(''EXPORTTOOL_CATEGORIES'')) {", "modService.class.php:238|if (getDolGlobalString(''EXPORTTOOL_CATEGORIES'')) {", "modProduct.class.php:259|if (getDolGlobalString(''EXPORTTOOL_CATEGORIES'')) {", "modService.class.php:291|if (getDolGlobalString(''EXPORTTOOL_CATEGORIES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORT_CSV_FORCE_CHARSET', 'string', NULL, 'core', 'Forces the character encoding used for CSV exports.', 'Used throughout core/modules/export (exportcsv.class.php, export_csvutf8.modules.php, export_csviso.modules.php) and core/lib/functions2.lib.php:3076 to override the output charset. The comment at functions2.lib.php:3065 states: ''Expected output character set (UTF-8, ISO-8859-1, ...). Default empty will use the value into EXPORT_CSV_FORCE_CHARSET.''', 'Changing this alters the byte encoding of all CSV export files; export modules for UTF-8 and ISO-8859-1 write this constant automatically.', '''UTF-8'' = UTF-8 encoding; ''ISO-8859-1'' = Latin-1 encoding; empty/unset = use system default.', 1, 0, NULL, 1, '5d1b9e84c35405d9d1d4abd1e005d848768218b4d3bd16f3785b568379720846', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:3065  * @param\tstring\t\t\t\t$charset\tExpected output character set (''UTF-8'', ''ISO-8859-1'', ...). Default '''' will use the value into EXPORT_CSV_FORCE_CHARSET.", "core/modules/export/export_csvutf8.modules.php:78|write|$conf->global->EXPORT_CSV_FORCE_CHARSET = ''UTF-8'';", "core/modules/export/export_csviso.modules.php:51|write|$conf->global->EXPORT_CSV_FORCE_CHARSET = ''ISO-8859-1'';", "core/modules/export/exportcsv.class.php:248|read|$outputlangs->charset_output = getDolGlobalString(''EXPORT_CSV_FORCE_CHARSET'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORT_CSV_SEPARATOR_TO_USE', 'string', NULL, 'core', 'Sets the column separator character used for CSV exports.', 'Written via the admin UI at admin/export.php:59 and read in core/lib/functions2.lib.php:3079 and both CSV export modules. The comment at functions2.lib.php:3066 states: ''CSV char separator (often comma or semicolon). Default empty will use the value into EXPORT_CSV_SEPARATOR_TO_USE.''', 'Changing this alters the delimiter in all CSV export files; a mismatch with the recipient''s expectations will cause import failures.', 'Any short string (typically '','' or '';''); empty/unset = use module default.', 0, 0, 'admin/export.php|admin/export.php', 1, 'cf4231335fe994cbe2a71d7152586e44d57027f9999bf39e385a29163f6346c7', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:3066  * @param\tstring\t\t\t\t$separator\tCSV char separator (often '','' or '';''). Default '''' will use the value into EXPORT_CSV_SEPARATOR_TO_USE.", "admin/export.php:59|write|dolibarr_set_const($db, ''EXPORT_CSV_SEPARATOR_TO_USE'', GETPOST(''EXPORT_CSV_SEPARATOR_TO_USE'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "core/modules/export/export_csvutf8.modules.php:48|read|$this->separator = getDolGlobalString(''EXPORT_CSV_SEPARATOR_TO_USE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORT_LABEL_FOR_SELECT', 'string', NULL, 'core', 'When set, uses the label field instead of the technical identifier in export and import extra-field selects.', 'Checked in core/extrafieldsinexport.inc.php:69 and core/extrafieldsinimport.inc.php:66. Both files share the same condition guard.', 'Enabling this constant changes how extra-field select values are represented in export/import files, affecting compatibility with external tools expecting technical keys.', 'Any non-empty value = use label for select in export/import; empty/unset = use technical value', 1, 0, NULL, 1, '750becccb94e3f4be9afee61b91db7ae19d46a8d421394578b7e73aceba418b8', 'v2', '2026-04-21T13:29:58+00:00', '["if (getDolGlobalString(''EXPORT_LABEL_FOR_SELECT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORT_MAX_EXECUTION_TIME', 'string', NULL, 'blockedlog', 'Sets the maximum PHP execution time in seconds allowed for export operations.', 'Read at blockedlog/admin/blockedlog_list.php:122, blockedlog/admin/blockedlog_archives.php:127, and exports/export.php:301, all with the inline comment ''5mn if not defined'' and a default of 300 seconds.', 'Increasing this value allows larger exports to complete without hitting a PHP timeout; decreasing it causes exports to abort sooner.', 'An integer number of seconds; default is 300 (5 minutes).', 0, 0, 'blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_archives.php', 1, 'f64e719dd39977e1762283ecf185b80e6463e4a83a1873c9fde334481cb82929', 'v2', '2026-04-21T11:16:15+00:00', '["$max_execution_time_for_importexport = getDolGlobalInt(''EXPORT_MAX_EXECUTION_TIME'', 300); // 5mn if not defined"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORT_NAME_WITH_DT', 'string', NULL, 'exports', 'When enabled, appends the current date/time to the generated export filename.', 'Checked in exports/class/export.class.php:744: `if (getDolGlobalString(''EXPORT_NAME_WITH_DT'')) { $filename .= dol_print_date(dol_now(), ''%Y%m%d%_%H%M''); }`, applied after the prefix is built.', 'When enabled, the export filename gets a ''%Y%m%d_%H%M'' timestamp suffix appended before the file extension, making each export''s filename unique per run.', 'Boolean-like: truthy value appends a YYYYMMDD_HHMM timestamp to the filename.', 1, 0, NULL, 1, '7dd3d5f69b8f953d9dcf22865783eb189faec04eaa5230056dfd38d8df622e6c', 'v2', '2026-07-24T07:05:23+00:00', '["exports/class/export.class.php:744|check|if (getDolGlobalString(''EXPORT_NAME_WITH_DT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORT_PREFIX_SPEC', 'string', NULL, 'exports', 'Custom filename prefix used for generated data export files, replacing the default ''export_'' prefix.', 'Checked and read in exports/class/export.class.php:739-740: `if (getDolGlobalString(''EXPORT_PREFIX_SPEC'')) { $filename = getDolGlobalString(''EXPORT_PREFIX_SPEC'') . "_".$datatoexport; } else { $filename = "export_".$datatoexport; }`.', 'When set, changes the prefix of the generated export filename from ''export_'' to the configured value, followed by an underscore and the export dataset code.', 'Free-text string used verbatim as the filename prefix; if empty/unset, defaults to ''export''.', 1, 0, NULL, 1, '5fd6d2c7eea48a9438adc426b1ade6a49250b148724dd40d27ddfe6c7f5927b9', 'v2', '2026-07-24T07:05:23+00:00', '["exports/class/export.class.php:739|check|if (getDolGlobalString(''EXPORT_PREFIX_SPEC'')) {", "exports/class/export.class.php:740|read|$filename = getDolGlobalString(''EXPORT_PREFIX_SPEC'') . \"_\".$datatoexport;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXPORT_TSV_FORCE_CHARSET', 'string', NULL, 'core', 'Forces a specific character set encoding for TSV export output.', 'Read in three locations in core/modules/export/export_tsv.modules.php: at line 269 to override $outputlangs->charset_output, at line 238 as an argument to tsv_clean(), and at line 358 to set the $charset variable. No admin UI write is present.', 'Setting this constant forces all TSV export data to be encoded in the specified character set, overriding the default output language charset. Leaving it unset uses the default charset.', 'A charset string (e.g. ''UTF-8'', ''ISO-8859-1''); empty or unset = default output language charset used.', 1, 0, NULL, 1, '7f7a66a6555906db780def5179a4c407db59e8f6fcd6f8573915e791db7f2191', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/export/export_tsv.modules.php:269|read|$outputlangs->charset_output = getDolGlobalString(''EXPORT_TSV_FORCE_CHARSET'');", "core/modules/export/export_tsv.modules.php:238|read|$newvalue = $this->tsv_clean($newvalue, getDolGlobalString(''EXPORT_TSV_FORCE_CHARSET''));", "core/modules/export/export_tsv.modules.php:358|read|$charset = getDolGlobalString(''EXPORT_TSV_FORCE_CHARSET'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXTERNALRSS_USE_SIMPLEXML', 'bool', NULL, 'core', 'Forces the RSS parser to use PHP''s SimpleXMLElement instead of the default array-based parser.', 'Checked in core/class/rssparser.class.php at lines 336, 419, 472, 480, 518, and 535. The COMMENTS entry states: ''* @var SimpleXMLElement|array<string,mixed>  SimpleXMLElement when getDolGlobalString(''EXTERNALRSS_USE_SIMPLEXML'')''.', 'Enabling this constant causes the RSS parser to return a SimpleXMLElement object; disabling it returns an array. Code that consumes the parser output must handle both types.', 'Truthy string to use SimpleXMLElement; empty/unset to use array-based parsing.', 1, 0, NULL, 1, 'd4128a6024aafef1db0fa672932e67da5cd8e7d02dccdd41704515f062d93fa7', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/rssparser.class.php:108  * @var SimpleXMLElement|array<string,mixed>  SimpleXMLElement when getDolGlobalString(''EXTERNALRSS_USE_SIMPLEXML'')", "core/class/rssparser.class.php:336|check|if (getDolGlobalString(''EXTERNALRSS_USE_SIMPLEXML'')) {", "core/class/rssparser.class.php:419|check|if (getDolGlobalString(''EXTERNALRSS_USE_SIMPLEXML'')) {", "core/class/rssparser.class.php:480|check|if (getDolGlobalString(''EXTERNALRSS_USE_SIMPLEXML'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXTERNAL_RSS_TITLE_', 'string', NULL, 'admin', 'Stores the display title for an indexed external RSS feed configured in the admin RSS settings.', 'Written and deleted in admin/external_rss.php:115 and :176. The constant name is built as EXTERNAL_RSS_TITLE_ concatenated with the RSS feed index number.', 'Changing this constant updates the label shown for the corresponding RSS feed widget.', 'String title for the RSS feed.', 0, 0, 'admin/external_rss.php|admin/external_rss.php', 1, '7552a0914ab1f7faf55431441b833e3d1caaf36d529541074a1ea9f7ea2ef38d', 'v2', '2026-04-21T13:50:40+00:00', '["$result1 = dolibarr_set_const($db, \"EXTERNAL_RSS_TITLE_\".GETPOSTINT(\"norss\"), GETPOST($external_rss_title), ''chaine'', 0, '''', $conf->entity);", "$result1 = dolibarr_del_const($db, \"EXTERNAL_RSS_TITLE_\".GETPOSTINT(\"norss\"), $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXTERNAL_RSS_URLRSS_', 'string', NULL, 'admin', 'Per-feed RSS URL for the External RSS module, dynamic constant EXTERNAL_RSS_URLRSS_<id> where <id> is the numeric feed identifier.', 'Deleted by admin/external_rss.php:179 (dolibarr_del_const) when a feed is removed (identified by GETPOSTINT(''norss'')); the admin page also enumerates all such constants via a SQL LIKE ''EXTERNAL_RSS_URLRSS_%'' query (line 66) since ids are not necessarily sequential/paddable; read via getDolGlobalString($keyrssurl) in admin/external_rss.php:262 and box_external_rss.php:84 to fetch the RSS feed URL for display in the feed box widget.', 'The value is the URL fed to RssParser::parser() to fetch and display an external RSS feed; removing the constant deletes that configured feed.', 'Feed URL string, keyed by numeric feed id (paired with EXTERNAL_RSS_TITLE_<id> for the feed''s title).', 0, 0, 'admin/external_rss.php', 1, '43dc7b993612a658d2da5a33b46faf5b6bf77438acff015f8b9ae4f06151edff', 'v2', '2026-07-24T07:05:23+00:00', '["admin/external_rss.php:179|write|$result2 = dolibarr_del_const($db, \"EXTERNAL_RSS_URLRSS_\".GETPOSTINT(\"norss\"), $conf->entity);", "admin/external_rss.php:66: $sql .= \" WHERE \".$db->decrypt(''name'').\" LIKE ''EXTERNAL_RSS_URLRSS_%''\";", "core/boxes/box_external_rss.php:84: $keyforparamurl = \"EXTERNAL_RSS_URLRSS_\".$site; ... $url = getDolGlobalString($keyforparamurl);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('EXTERNAL_USERS_ARE_AUTHORIZED', 'string', NULL, 'comm', 'Grants external (third-party contact) users access to the emailing module, overriding the default restriction.', 'Checked in five mailing PHP files (targetemailing.php:106, info.php:46, card.php:118, advtargetemailing.php:122, list.php:109) with the pattern: if (!getDolGlobalString(''EXTERNAL_USERS_ARE_AUTHORIZED'') && $user->socid > 0) — deny access when unset and user is external.', 'When unset, external users (socid > 0) are blocked from all mailing pages. When set to a truthy value, external users with the mailing read right gain access.', 'Non-empty string = external users allowed. Empty/unset = external users denied.', 1, 0, NULL, 1, 'd56f4bf09df1d249f48dcf761a9695dcddcfa60f577b0fd460a0e4519a0a4e5e', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/targetemailing.php:106|check|if (!$user->hasRight(''mailing'', ''lire'') || (!getDolGlobalString(''EXTERNAL_USERS_ARE_AUTHORIZED'') && $user->socid > 0)) {", "comm/mailing/info.php:46|check|if (!$user->hasRight(''mailing'', ''lire'') || (!getDolGlobalString(''EXTERNAL_USERS_ARE_AUTHORIZED'') && $user->socid > 0)) {", "comm/mailing/card.php:118|check|if (!$user->hasRight(''mailing'', ''lire'') || (!getDolGlobalString(''EXTERNAL_USERS_ARE_AUTHORIZED'') && $user->socid > 0)) {", "comm/mailing/list.php:109|check|if (!$user->hasRight(''mailing'', ''lire'') || (!getDolGlobalString(''EXTERNAL_USERS_ARE_AUTHORIZED'') && $user->socid > 0)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTUREFOURN_REUSE_NOTES_ON_CREATE_FROM', 'bool', NULL, 'fourn', 'Controls whether note_public/note_private are copied from the source document when creating a supplier invoice from another object (e.g. order).', 'Checked twice in fourn/facture/card.php:2363-2364, gating whether getDefaultCreateValueFor() uses $objectsrc->note_public/note_private or null.', 'When set (and origin/originid/objectsrc are present), the new supplier invoice''s public/private notes default to the source object''s notes instead of being left empty.', 'Bool: truthy copies notes from the origin object when creating a supplier invoice from it.', 1, 0, NULL, 1, '390797c897211f65bc5e238f374270a70f250336810199fa53cc4f61507bca34', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:2363|check|$note_public = $object->getDefaultCreateValueFor(''note_public'', ((!empty($origin) && !empty($originid) && is_object($objectsrc) && getDolGlobalString(''FACTUREFOURN_REUSE_NOTES_ON_CREATE_FROM'')) ? $objectsrc->note_public : null));", "fourn/facture/card.php:2364|check|$note_private = $object->getDefaultCreateValueFor(''note_private'', (... getDolGlobalString(''FACTUREFOURN_REUSE_NOTES_ON_CREATE_FROM'')) ? $objectsrc->note_private : null));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTUREREC_SUPPORT_RULE_FOR_LINES', 'string', NULL, 'compta', 'Enables support for date rules applied to individual lines on recurring invoices.', 'Checked at compta/facture/card-rec.php:1367 and :1740 to conditionally display line-level date rule controls. Also used as an ''enabled'' condition for the ''rule_for_lines_dates'' field in compta/facture/class/facture-rec.class.php:284.', 'When enabled, recurring invoice lines can have individual date rules configured; when disabled, the date rule field and its UI are hidden.', '0 or not set = line-level date rules not available; non-zero = line-level date rules enabled on recurring invoices.', 1, 0, NULL, 1, 'b4250d1597c6466f3964940fe4123ab82f641a4a5e0daa89b70b79733af90865', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card-rec.php:1367|check|if (getDolGlobalInt(\"FACTUREREC_SUPPORT_RULE_FOR_LINES\")) {", "compta/facture/class/facture-rec.class.php:284|read|''rule_for_lines_dates'' => array(''type'' => ''varchar(255)'', ''label'' => ''RuleForLinesDates'', ''enabled'' => ''getDolGlobalInt(\"FACTUREREC_SUPPORT_RULE_FOR_LINES\")'', ''visible'' => 1,"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_ADDON', 'string', NULL, 'compta', 'Name of the numbering module class used to generate customer invoice reference numbers.', 'Set via admin/invoice.php:168 (dolibarr_set_const) and checked/used in admin/invoice.php:380/405/480 and compta/facture/class/facture.class.php:5100-5105, where it falls back to ''mod_facture_mars'' or ''mod_facture_mercure'' when unset.', 'Changing it switches which numbering module generates new customer invoice references; if unset, a default module (mod_facture_mars or mod_facture_mercure depending on context) is used.', NULL, 0, 0, 'admin/invoice.php|admin/invoice.php|admin/invoice.php|admin/invoice.php', 1, '6da5c189bb636ad1b2d48803e161c3318ca8a76340d9b54ccc2d51fe4e5b39e7', 'v2', '2026-07-24T06:41:12+00:00', '["*      according to numbering module defined into constant FACTURE_ADDON", "if (!getDolGlobalString(''FACTURE_ADDON'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_ADDON_PDF', 'string', NULL, 'compta', 'Name of the PDF document model/template used to generate customer invoice PDFs (also referenced from supplier payment and product lot admin screens).', 'Set via admin/invoice.php:154 (dolibarr_set_const) or removed via dolibarr_del_const at line 149, selected among candidates checked at admin/invoice.php:148/604, supplier_invoice/admin/supplier_payment.php:98, and product/admin/product_lot.php:115.', 'Changing it switches the default PDF template used to render customer invoices.', NULL, 0, 0, 'supplier_invoice/admin/supplier_payment.php|product/admin/product_lot.php|admin/invoice.php|admin/invoice.php|admin/invoice.php|supplier_invoice/admin/supplier_payment.php|admin/invoice.php|admin/invoice.php|admin/invoice.php|product/admin/product_lot.php', 1, '7c6a384b9b4f52694a192a3eb2ee9888a33962c326e5ed2e4a41213024ec12fa', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''FACTURE_ADDON_PDF'') == (string) $value) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_ADDON_PDF_', 'string', NULL, 'admin', 'Per-invoice-type default PDF model: dynamic constant FACTURE_ADDON_PDF_<type> stores which PDF model to use for invoice type <type> (0=standard,1=replacement,2=credit note,3=deposit,5=situation).', 'Written by admin/invoice.php:234 as ''FACTURE_ADDON_PDF_''.intval($type) via dolibarr_set_const from the per-type model selector on the invoice setup page, and read via getDolGlobalString($thisTypeConfName, ...) in admin/invoice.php:685 and compta/facture/card.php:4477/4710 and class/facture.class.php:1782/5757 to auto-select the PDF model when creating/generating a document for that invoice type, falling back to the generic FACTURE_ADDON_PDF constant if unset.', 'Setting FACTURE_ADDON_PDF_<type> forces that invoice type to use the named PDF model instead of the module-wide FACTURE_ADDON_PDF default; used e.g. by the card.php JS auto-select feature gated by INVOICE_USE_DEFAULT_DOCUMENT.', 'String = name of a registered invoice PDF model (e.g. ''sponge'', ''octopus''); type suffix taken from Facture::TYPE_STANDARD/TYPE_REPLACEMENT/TYPE_CREDIT_NOTE/TYPE_DEPOSIT/TYPE_SITUATION constants.', 0, 0, 'admin/invoice.php', 1, 'cbb18c72524e5083379d60f0328da1540c626fbb08ff1600226767438ef99952', 'v2', '2026-07-24T07:05:23+00:00', '["admin/invoice.php:234|write|$res = dolibarr_set_const($db, ''FACTURE_ADDON_PDF_''.intval($type), $value, ''chaine'', 0, '''', $conf->entity);", "admin/invoice.php:685: $thisTypeConfName = ''FACTURE_ADDON_PDF_''.$type; $current = getDolGlobalString($thisTypeConfName, getDolGlobalString(''FACTURE_ADDON_PDF''));", "compta/facture/card.php:4472: if (getDolGlobalString(''INVOICE_USE_DEFAULT_DOCUMENT'')) { // Hidden conf"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies the directory path(s) where ODT invoice template files are stored.', 'Read in core/modules/facture/doc/doc_generic_invoice_odt.modules.php at lines 127 and 154; at line 127 the value is split by comma/newline into a list of directories to search for ODT templates. Checked at line 162 to determine whether to scan those paths.', 'Setting this constant to one or more comma-separated directory paths enables the ODT invoice module to find custom templates. If unset, the module cannot locate any templates.', 'Comma-separated or newline-separated directory paths pointing to ODT template files.', 1, 0, NULL, 1, 'fdd8d89bf5c86aac6a9d933ffb7782a8eb95e93b5f073d0baa79808a872240bd', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/facture/doc/doc_generic_invoice_odt.modules.php:127|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim($conf->global->FACTURE_ADDON_PDF_ODT_PATH)));", "core/modules/facture/doc/doc_generic_invoice_odt.modules.php:154|read|$texte .= getDolGlobalString(''FACTURE_ADDON_PDF_ODT_PATH'');", "core/modules/facture/doc/doc_generic_invoice_odt.modules.php:162|check|if (getDolGlobalString(''FACTURE_ADDON_PDF_ODT_PATH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_CHQ_NUMBER', 'string', NULL, 'core', 'Stores the bank account identifier used to print cheque/payment details on invoices, proposals, and orders.', 'Written via admin/invoice.php:174, admin/order.php:189, and admin/propal.php:132. Read in many places including admin/propal.php:587 and 603 to populate select options, and admin/invoice.php:757 to retrieve the configured bank account. Used across proposals, orders, and invoice PDF generation.', 'Changing this value changes the bank account whose details appear in cheque payment sections of generated documents.', '''-1'' = use company default (mysoc); any other value = ID of the selected bank account; empty = none configured', 0, 0, 'admin/propal.php|admin/propal.php|admin/invoice.php|admin/order.php|admin/order.php|admin/order.php|admin/propal.php|admin/invoice.php', 1, 'f8284478b2ff2e50c2f1755e21050d5f44ce50610f8044c9c99b7f083cb7affe', 'v2', '2026-04-21T13:29:58+00:00', '["admin/invoice.php:174|write|$res = dolibarr_set_const($db, \"FACTURE_CHQ_NUMBER\", $chq, ''chaine'', 0, '''', $conf->entity);", "admin/propal.php:587|read|print ''<option value=\"-1\"''.(getDolGlobalString(''FACTURE_CHQ_NUMBER'') ? '' selected'' : '''').''>''.$langs->trans(\"MenuCompanySetup\").'' (''.($mysoc->name ? $mysoc->name : $langs->trans(\"No", "admin/invoice.php:757|read|$FACTURE_CHQ_NUMBER = getDolGlobalInt(''FACTURE_CHQ_NUMBER'');", "admin/order.php:189|write|$res = dolibarr_set_const($db, \"FACTURE_CHQ_NUMBER\", $chq, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_DEPOSITS_ARE_JUST_PAYMENTS', 'string', NULL, 'compta', 'Treats deposit invoices as simple payments rather than as invoices with their own accounting entries, for sale invoices; not recommended.', 'Checked extensively (59 occurrences) across accounting/statistics code such as accountancy/admin/index.php:551, compta/tva/clients.php:169, compta/stats/cabyprodserv.php:272, compta/stats/cabyuser.php:212/272, and projet/element.php:986.', 'When enabled, deposit-type invoices are excluded from normal invoice accounting/statistics and treated as plain payments instead; the code comments explicitly mark this option ''not recommended''.', NULL, 0, 0, 'accountancy/admin/index.php', 1, 'cea7f8dccd29179b0bb8dece73a77c2b9614292f3ec7d49c772767ec44edb614', 'v2', '2026-07-24T06:41:12+00:00', '["*  Should always be empty, except if option FACTURE_DEPOSITS_ARE_JUST_PAYMENTS is on for sale invoices (not recommended),", "if (getDolGlobalString(''FACTURE_DEPOSITS_ARE_JUST_PAYMENTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_DRAFT_WATERMARK', 'string', NULL, 'core', 'Sets the text string used as a watermark on draft invoice and asset PDFs.', 'Written in admin/invoice.php at line 188 and displayed as a text input at line 857. Read in pdf_octopus.modules.php at line 297, pdf_sponge.modules.php at line 231, and pdf_standard_asset.modules.php at line 818 to set $this->watermark; the watermark is only applied when invoice status is STATUS_DRAFT.', 'Setting this constant to a non-empty string causes a visible watermark (e.g. ''DRAFT'') to appear on draft invoice and draft asset PDFs. Clearing it removes the watermark.', 'Any non-empty string to use as the watermark text; empty/unset = no watermark.', 0, 0, 'admin/invoice.php|admin/invoice.php', 1, '94d2d317a67c3a42ccf0541ed445561f06e5ac1c3cf41747e5c44982796f797c', 'v2', '2026-04-21T13:50:40+00:00', '["admin/invoice.php:188|write|$res = dolibarr_set_const($db, \"FACTURE_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "core/modules/facture/doc/pdf_octopus.modules.php:296|check|if ($object->status == $object::STATUS_DRAFT && (getDolGlobalString(''FACTURE_DRAFT_WATERMARK''))) {", "core/modules/facture/doc/pdf_octopus.modules.php:297|read|$this->watermark = getDolGlobalString(''FACTURE_DRAFT_WATERMARK'');", "core/modules/asset/doc/pdf_standard_asset.modules.php:818|read|pdf_watermark($pdf, $outputlangs, $this->page_hauteur, $this->page_largeur, ''mm'', $conf->global->FACTURE_DRAFT_WATERMARK);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_ENABLE_NEGATIVE', 'bool', NULL, 'compta', 'When enabled, allows creation and validation of invoices with a negative total amount (excluding credit notes).', 'Checked in compta/facture/card.php:422 to skip the blocking error when total_ttc is negative, and referenced in card.php:5004 in a comment confirming this condition only occurs when this constant is on.', 'Without this constant, invoices with a negative total (other than credit notes) are blocked from validation. Enabling it permits negative-total standard invoices.', '0 or unset = negative-total invoices blocked; truthy = negative-total invoices allowed.', 1, 0, NULL, 1, '7911d3c11700e822d7a6010aedbb4a28abdccb90100fde8902dae2c0350d3bbb', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:422|check|if (!getDolGlobalString(''FACTURE_ENABLE_NEGATIVE'') && $object->total_ttc < 0) {", "compta/facture/card.php:5004|check|if ($object->type != Facture::TYPE_CREDIT_NOTE && $object->total_ttc < 0) { \t\t// Can happen only if getDolGlobalString(''FACTURE_ENABLE_NEGATIVE'') is on"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_ENABLE_NEGATIVE_LINES', 'bool', NULL, 'compta', 'Allows negative unit prices/amounts on invoice lines (outside of credit notes).', 'Checked in compta/facture/class/facture.class.php:4743 (combined with INVOICE_KEEP_DISCOUNT_LINES_AS_IN_ORIGIN for credit notes) and repeatedly in compta/facture/card.php (lines 454, 2620, 3287, 3288, 2615-2617) guarding negative price/amount checks.', 'When enabled, negative prices/amounts are permitted on invoice lines where they would otherwise be rejected; for credit notes, both this constant and INVOICE_KEEP_DISCOUNT_LINES_AS_IN_ORIGIN must be enabled together for negative lines to be allowed.', NULL, 1, 0, NULL, 1, 'a51e275e3f50cdf9eed7dc67ca857eef84e73a15919303a0f25ab7961dfd2fab', 'v2', '2026-07-24T06:41:12+00:00', '["if ($this->type == self::TYPE_CREDIT_NOTE && !(getDolGlobalInt(''FACTURE_ENABLE_NEGATIVE_LINES'') && getDolGlobalInt(''INVOICE_KEEP_DISCOUNT_LINES_AS_IN_ORIGIN''))) {", "if (($tmp_total_ht < 0 || $tmp_total_ht_devise < 0) && !getDolGlobalString(''FACTURE_ENABLE_NEGATIVE_LINES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_LOCAL_TAX1_OPTION', 'string', NULL, 'core', 'Controls whether local tax 1 is applied on invoices and related documents.', 'Written via admin/company.php at line 258 and displayed as radio buttons at lines 797 and 815. Checked against ''localtax1on'' in multiple PDF generation modules (e.g. core/modules/supplier_order/doc/pdf_cornas.modules.php line 1044, pdf_muscadet.modules.php line 875) and in core/tpl/objectline_title.tpl.php at line 91.', 'Setting to ''localtax1on'' activates local tax 1 on invoice lines and document totals; other values or empty disables it.', '''localtax1on'' = local tax 1 active; ''localtax1off'' or empty = local tax 1 inactive', 0, 0, 'admin/company.php|admin/company.php|admin/company.php', 1, 'd1bc40647c947ba4a43a829e4d68f3a73ed8668ae7ad1e87fc78d556db5012e9', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:258|write|dolibarr_set_const($db, \"FACTURE_LOCAL_TAX1_OPTION\", $uselocaltax1, ''chaine'', 0, '''', $conf->entity);", "core/modules/supplier_order/doc/pdf_cornas.modules.php:1044|check|if (getDolGlobalString(''FACTURE_LOCAL_TAX1_OPTION'') == ''localtax1on'' && $object->total_localtax1 > 0) {", "core/modules/supplier_order/doc/pdf_muscadet.modules.php:875|check|if (getDolGlobalString(''FACTURE_LOCAL_TAX1_OPTION'') == ''localtax1on'' && $object->total_localtax1 > 0) {", "core/tpl/objectline_title.tpl.php:91|check|if (getDolGlobalString(''FACTURE_LOCAL_TAX1_OPTION'') || getDolGlobalString(''FACTURE_LOCAL_TAX2_OPTION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_LOCAL_TAX2_OPTION', 'string', NULL, 'core', 'Controls whether the second local tax (localtax2) is enabled or disabled on invoices and related documents.', 'Configured via admin/company.php (written by dolibarr_set_const). Checked across invoice, order, and proposal PDF modules to decide whether to display or compute the second local tax column. Value ''localtax2on'' enables local tax 2; absence or ''localtax2off'' disables it.', 'Setting this to ''localtax2on'' causes local tax 2 amounts to be rendered in PDF documents and included in totals. Disabling it suppresses the localtax2 column and computations in those documents.', '''localtax2on'' = local tax 2 enabled; ''localtax2off'' or empty = local tax 2 disabled', 0, 0, 'admin/company.php|admin/company.php|admin/company.php', 1, '606642dc7088fb9079f6bd7bcebe5da4e498664b2f8ea115430843c794cc1975', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:259|write|dolibarr_set_const($db, \"FACTURE_LOCAL_TAX2_OPTION\", $uselocaltax2, ''chaine'', 0, '''', $conf->entity);", "core/modules/supplier_order/doc/pdf_cornas.modules.php:1053|check|if (getDolGlobalString(''FACTURE_LOCAL_TAX2_OPTION'') == ''localtax2on'' && $object->total_localtax2 > 0) {", "admin/company.php:841|read|print ''<tr class=\"oddeven\"><td><input type=\"radio\" name=\"optionlocaltax2\" id=\"lt2\" value=\"localtax2on\"''", "core/modules/supplier_order/doc/pdf_muscadet.modules.php:884|check|if (getDolGlobalString(''FACTURE_LOCAL_TAX2_OPTION'') == ''localtax2on'' && $object->total_localtax2 > 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_MERCURE_MASK_CREDIT', 'string', NULL, 'core', 'Stores the numbering mask pattern for credit notes in the Mercure invoice numbering module.', 'Used in core/modules/facture/mod_facture_mercure.php in two locations: line 109 populates a UI input, and line 174 retrieves it to generate credit note reference numbers.', 'Changing the mask pattern alters how new credit note numbers are generated by the Mercure module. Clearing it causes the module to have no mask for credit notes.', 'Any string = mask pattern for Mercure credit note numbering; empty/unset = no mask pattern.', 1, 0, NULL, 1, 'ed9017e28653a0466456188de4ec47c08a8b7234aeb34d04feb4ca0591b4e769', 'v2', '2026-04-21T13:50:40+00:00', '["mod_facture_mercure.php:109|value=''\".getDolGlobalString(\"FACTURE_MERCURE_MASK_CREDIT\").\"''", "mod_facture_mercure.php:174|$mask = getDolGlobalString(''FACTURE_MERCURE_MASK_CREDIT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_MERCURE_MASK_DEPOSIT', 'string', NULL, 'core', 'Numbering mask used by the ''mercure'' invoice numbering module for deposit (down-payment) invoices.', 'Set/read via an inline HTML form in core/modules/facture/mod_facture_mercure.php (input name ''maskdeposit'', lines 122/176); getNextValue() uses it when the invoice type is 3 (deposit) and INVOICE_DISABLE_DEPOSIT is not set.', 'Changing this mask changes the reference numbering pattern applied to future deposit invoices generated under the mercure numbering module; it has no effect if INVOICE_DISABLE_DEPOSIT is set.', 'String: a Dolibarr numbering mask pattern.', 0, 0, NULL, 1, '0a62919137d7f892e721d8eab201ebab72015902a37c0f143680621b4358d83f', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/mod_facture_mercure.php:122: ...name=\"maskdeposit\" value=\"''.getDolGlobalString(\"FACTURE_MERCURE_MASK_DEPOSIT\").''\">...", "core/modules/facture/mod_facture_mercure.php:176: $mask = getDolGlobalString(''FACTURE_MERCURE_MASK_DEPOSIT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_MERCURE_MASK_INVOICE', 'string', NULL, 'core', 'Stores the numbering mask pattern for standard invoices in the Mercure invoice numbering module.', 'Used in core/modules/facture/mod_facture_mercure.php in three locations: line 101 populates a UI input, line 172 provides it as the fallback for FACTURE_MERCURE_MASK_REPLACEMENT, and line 178 retrieves it directly for standard invoice numbering.', 'Changing the mask pattern alters how new standard invoice numbers are generated by the Mercure module. Clearing it causes the module to have no mask for standard invoices.', 'Any string = mask pattern for Mercure standard invoice numbering; empty/unset = no mask pattern.', 1, 0, NULL, 1, '4ba116eb1d00ce960ab33a6f39c49601ab0a98a47162ed84a8f4026738e634b9', 'v2', '2026-04-21T13:50:40+00:00', '["mod_facture_mercure.php:101|value=''\".getDolGlobalString(\"FACTURE_MERCURE_MASK_INVOICE\").\"''", "mod_facture_mercure.php:172|$mask = getDolGlobalString(''FACTURE_MERCURE_MASK_REPLACEMENT'', getDolGlobalString(''FACTURE_MERCURE_MASK_INVOICE''));", "mod_facture_mercure.php:178|$mask = getDolGlobalString(''FACTURE_MERCURE_MASK_INVOICE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_MERCURE_MASK_REPLACEMENT', 'string', NULL, 'core', 'Numbering mask used by the ''mercure'' invoice numbering module for replacement invoices.', 'Set/read via an inline HTML form in core/modules/facture/mod_facture_mercure.php (input name ''maskreplacement'', lines 115/172); getNextValue() uses it (falling back to FACTURE_MERCURE_MASK_INVOICE) when the invoice type is 1 (replacement) and INVOICE_DISABLE_REPLACEMENT is not set.', 'Changing this mask changes the reference numbering pattern applied to future replacement invoices generated under the mercure numbering module; it has no effect if INVOICE_DISABLE_REPLACEMENT is set.', 'String: a Dolibarr numbering mask pattern; falls back to FACTURE_MERCURE_MASK_INVOICE if empty.', 0, 0, NULL, 1, '7b905806b5ad71b909d78262a7c3e34b4705e20f73909acc5899a53c0d6b6118', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/mod_facture_mercure.php:115: ...name=\"maskreplacement\" value=\"''.getDolGlobalString(\"FACTURE_MERCURE_MASK_REPLACEMENT\").''\">...", "core/modules/facture/mod_facture_mercure.php:172: $mask = getDolGlobalString(''FACTURE_MERCURE_MASK_REPLACEMENT'', getDolGlobalString(''FACTURE_MERCURE_MASK_INVOICE''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_PAYMENTS_INVOICE_REQUESTED_SORT_FIRST', 'string', NULL, 'compta', 'Changes the sort order of the unpaid-invoices list on the payment-entry page so the invoice the payment was requested for is listed first.', 'Checked in compta/paiement.php:623; when falsy, invoices are sorted by date/ref ascending (oldest first, per comment); when truthy, the ORDER BY instead sorts so f.rowid = $facid comes first, then by date/ref.', 'Enabling it reorders the unpaid invoices list shown when entering a payment so the originating invoice ($facid) appears at the top instead of following strict date order.', 'Boolean-like: falsy = sort by date/ref ascending (oldest first); truthy = requested invoice ($facid) sorts first, then by date/ref.', 1, 0, NULL, 1, '91db241150b6280ddd2902ae1dd58768fcda6a28c987c95ad01010c339285dc2', 'v2', '2026-07-24T07:05:23+00:00', '["compta/paiement.php:623: if (!getDolGlobalInt(''FACTURE_PAYMENTS_INVOICE_REQUESTED_SORT_FIRST'')) {", "compta/paiement.php:624: // Sort invoices by date and serial number: the older one comes first", "compta/paiement.php:627: // The requested invoice sort first"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_PAYMENTS_ON_DIFFERENT_THIRDPARTIES_BILLS', 'string', NULL, 'admin', 'Allows a single payment to be split/applied across invoices belonging to different (parent/child) thirdparties.', 'Set via admin/payment.php:92 (dolibarr_set_const) and checked in fourn/facture/paiement.php:570, compta/paiement.php:606, and accountancy/journal/bankjournal.php:388/483, always combined with a check on $object->thirdparty->parent.', 'When enabled, a payment can cover invoices from more than one thirdparty (e.g. a parent company paying for subsidiary invoices); when disabled, the accounting bank journal instead adds the full amount to a single thirdparty ($amounttouse).', NULL, 0, 0, 'admin/payment.php|admin/payment.php', 1, '5609e79efb8c5147bf00444af23ff23927ac6c03667810dd65ccb1bbb6979e98', 'v2', '2026-07-24T06:41:12+00:00', '["// in case option FACTURE_PAYMENTS_ON_DIFFERENT_THIRDPARTIES_BILLS is on, payment could be for more than one third-partie", "// if FACTURE_PAYMENTS_ON_DIFFERENT_THIRDPARTIES_BILLS is off we add $amounttouse"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_PAYMENTS_ON_SUBSIDIARY_COMPANIES', 'string', NULL, 'fourn', 'Allows paying/reconciling invoices of a thirdparty''s own subsidiary companies (children), not just parent-linked ones.', 'Checked in fourn/facture/paiement.php:574 and compta/paiement.php:610; when set it extends the SQL to include invoices of companies whose parent is the current thirdparty''s id.', 'When set, the invoice-selection SQL on the payment page adds ''OR f.fk_soc IN (SELECT rowid FROM societe WHERE parent = <thirdparty id>)'', letting a single payment page pull in invoices from that thirdparty''s subsidiaries.', 'Bool: truthy enables inclusion of invoices of subsidiary companies (companies with parent = current thirdparty id).', 1, 0, NULL, 1, 'f1edfa44f779ac73943ff9428c3ed3a99d7786ddc6b67b2cc9c8bf4771ea84c1', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/paiement.php:574|check|if (getDolGlobalString(''FACTURE_PAYMENTS_ON_SUBSIDIARY_COMPANIES'')) {", "compta/paiement.php:610|check|if (getDolGlobalString(''FACTURE_PAYMENTS_ON_SUBSIDIARY_COMPANIES'')) {", "fourn/facture/paiement.php:576|read|$sql .= '' OR f.fk_soc IN (SELECT rowid FROM ''.MAIN_DB_PREFIX.''societe WHERE parent = ''.((int) $object->thirdparty->id).'')'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_PAYMENTS_SHOW_LINK_TO_INPUT_ORIGIN_IS_MORE_THAN', 'bool', NULL, 'compta', 'Shows a ''Go to source invoice'' link on the payment-entry page when entering a payment (used when many invoices are listed).', 'Checked in compta/paiement.php:584 (guarded also by $action != ''add_paiement''); when truthy, a link to ''#amount_''.$facid is printed, per the inline comment ''useful when there are many invoices''.', 'Enabling it adds a jump-to-source-invoice link on the payment entry page''s invoice list; despite the constant''s name suggesting a numeric threshold, the code only tests it as a boolean/truthy flag.', 'Boolean-like in the code (truthy/falsy check); despite the name implying a count threshold, no numeric comparison against this value was found.', 1, 0, NULL, 1, 'f1704da4c5fe1dfd0415343fe28362c18f29c661ec0195102498f5b0db089494', 'v2', '2026-07-24T07:05:23+00:00', '["compta/paiement.php:584: if ($action != ''add_paiement'' && getDolGlobalString(''FACTURE_PAYMENTS_SHOW_LINK_TO_INPUT_ORIGIN_IS_MORE_THAN'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_PAYMENT_FIX_LINK_TO_BANK', 'string', NULL, 'compta', 'Forces a fixed bank account link on payment records and pre-selects that account in the payment list search.', 'Checked in compta/paiement/list.php:522 to show a fix-link action for users with payment permission, and read at :675 to pre-select the account in the search dropdown when set.', 'Enabling this constant causes a bank account to be pre-selected and a fix-link action to appear on the payment list; disabling it removes both behaviors.', 'Any non-empty value (interpreted as account identifier) = enable fixed bank account link; empty/unset = no fixed link', 1, 0, NULL, 1, '4a4df6356570c626e083c245ca0af0a53cd8b942f131d63c6405f849f3c52ba3', 'v2', '2026-04-21T13:29:58+00:00', '["if (!empty($permissiontopay) && getDolGlobalString(''FACTURE_PAYMENT_FIX_LINK_TO_BANK'')) {", "getDolGlobalString(''FACTURE_PAYMENT_FIX_LINK_TO_BANK'') ? 1 : 0"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_REMINDER_EMAIL', 'string', NULL, 'compta', 'Would gate sending an invoice payment reminder email; the only reference in the codebase is inside a commented-out (deactivated) code block.', 'Found in compta/facture/class/facture.class.php:6197 as the condition opening a block comment (''/*if (empty($conf->global->FACTURE_REMINDER_EMAIL)) {''), meaning this reminder-email logic is currently disabled/dead code.', 'This constant has no active effect since the only code referencing it is commented out.', 'Exact behavior unclear from code alone [SPECULATION].', 1, 0, NULL, 1, '2ad9f36ec913c6448420eda777ba90a83c4d0d086be3d4163ff0760b6b663d04', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/class/facture.class.php:6197: /*if (empty($conf->global->FACTURE_REMINDER_EMAIL)) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_REUSE_NOTES_ON_CREATE_FROM', 'bool', NULL, 'compta', 'When enabled, copies the public and private notes from the source document into a new invoice created from it.', 'Checked in compta/facture/card.php at lines 3865 and 3866 when populating default note_public and note_private values during invoice creation from a source object.', 'Enabling this constant causes invoices created from source documents to inherit both public and private notes from the source.', '0 or unset = notes are not copied from source; truthy = notes are copied from source document.', 1, 0, NULL, 1, '358763c2279e07cc71142efdec9c7c595873e7fc4c81345ce62c2a25b6014a4a', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:3865|check|$note_public = $object->getDefaultCreateValueFor(''note_public'', ((!empty($origin) && !empty($originid) && is_object($objectsrc) && getDolGlobalString(''FACTURE_REUSE_NOTES_ON_CREATE", "compta/facture/card.php:3866|check|$note_private = $object->getDefaultCreateValueFor(''note_private'', ((!empty($origin) && !empty($originid) && is_object($objectsrc) && getDolGlobalString(''FACTURE_REUSE_NOTES_ON_CREA"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_RIB_NUMBER', 'string', NULL, 'core', 'Stores the identifier of the bank account (RIB) to print by default on invoices, orders, and proposals.', 'Holds the rowid or account number of the bank account selected for inclusion in generated documents. Written by admin/invoice.php, admin/order.php, and admin/propal.php. Used in over 30 PDF generation modules to decide whether to print bank details.', 'Setting this causes the corresponding bank account details to appear on generated PDF documents (invoices, orders, proposals). Clearing it removes the default bank account from those documents.', 'String matching a bank account rowid/identifier; empty = no default bank account printed', 0, 0, 'admin/propal.php|admin/invoice.php|admin/order.php|admin/order.php|admin/propal.php|admin/invoice.php', 1, '61385fb33b7b0ee03773549d0eff02e935e245521b75a001314aba2780065235', 'v2', '2026-04-21T11:16:15+00:00', '["admin/invoice.php:173|write|$res = dolibarr_set_const($db, \"FACTURE_RIB_NUMBER\", $rib, ''chaine'', 0, '''', $conf->entity);", "admin/order.php:601|read|print getDolGlobalString(''FACTURE_RIB_NUMBER'') == $row[0] ? '' selected'' : '''';", "core/modules/stocktransfer/doc/pdf_eagle_proforma.modules.php:1009|check|if (!empty($object->fk_account) || !empty($object->fk_bank) || getDolGlobalInt(''FACTURE_RIB_NUMBER'')) {", "core/modules/commande/doc/pdf_einstein.modules.php:878|check|if ($object->fk_account > 0 || $object->fk_bank > 0 || getDolGlobalInt(''FACTURE_RIB_NUMBER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_SENDBYEMAIL_FOR_ALL_STATUS', 'string', NULL, 'compta', 'Allows sending a customer invoice by email regardless of its status, not just validated/closed ones.', 'Checked in compta/facture/card.php:6776 to allow the send-by-email action for draft invoices too, and in core/actions_massactions.inc.php:354 to allow the mass-action email send for draft invoices.', 'When enabled, draft customer invoices can also be sent by email (individually or via mass actions); otherwise sending by email is restricted to validated or closed invoices.', NULL, 1, 0, NULL, 1, 'b439d09c6ce880d57e784bc629969cd0cb46496a619bba67adf7f00a96e253a4', 'v2', '2026-07-24T06:41:12+00:00', '["if (($object->status == Facture::STATUS_VALIDATED || $object->status == Facture::STATUS_CLOSED) || getDolGlobalString(''FACTURE_SENDBYEMAIL_FOR_ALL_STATUS'')) {", "if ($objectclass == ''Facture'' && $objectobj->status == Facture::STATUS_DRAFT && !getDolGlobalString(''FACTURE_SENDBYEMAIL_FOR_ALL_STATUS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_SUPPLIER_DEPOSITS_ARE_JUST_PAYMENTS', 'string', NULL, 'compta', 'When enabled, treats supplier deposit invoices as simple payments rather than as real invoices generating discount lines (not recommended).', 'Checked in 38 locations across accountancy/admin/index.php:484, fourn/commande/card.php:2515, compta/resultat pages, and supplier_proposal/card.php:1984. Code comments at core/class/commoninvoice.class.php:382 state this option is ''not recommended'' for purchase invoices, and core/class/discount.class.php:710 notes it should ''always be empty''.', 'Enabling this option causes supplier deposit invoices to be processed as payments, bypassing discount line generation; this is explicitly flagged as not recommended in the source.', 'Non-empty/truthy = deposits treated as payments (not recommended); empty = standard deposit invoice behaviour (default)', 0, 0, 'accountancy/admin/index.php', 1, '9eb6dc3d9c4a2a0316e42c88eb6660747153f5dc60d6955f75febc14ad073a76', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/commoninvoice.class.php:382  *  of FACTURE_SUPPLIER_DEPOSITS_ARE_JUST_PAYMENTS is on for purchase invoices (not recommended).", "core/class/commoninvoice.class.php:391  // FACTURE_SUPPLIER_DEPOSITS_ARE_JUST_PAYMENTS was never supported for purchase invoice, so we can return 0 with no need of SQL for this case.", "core/class/discount.class.php:710  *  Should always be empty, except if option FACTURE_DEPOSITS_ARE_JUST_PAYMENTS or FACTURE_SUPPLIER_DEPOSITS_ARE_JUST_PAYMENTS is on (not recommended).", "accountancy/admin/index.php:484|check|if (getDolGlobalString(''FACTURE_SUPPLIER_DEPOSITS_ARE_JUST_PAYMENTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_TVAOPTION', 'string', NULL, 'admin', 'Sets the default VAT usage option (subject to VAT or not) proposed on the third-party/company setup screen.', 'Read via getDolGlobalString(''FACTURE_TVAOPTION'') in admin/dict.php:1551 and admin/company.php (783, 793, 801) to pre-select the ''use_vat''/''no_vat'' radio buttons, and written by admin/company.php:265 via dolibarr_set_const. Also read in societe/class/societe.class.php:4878 to set $this->tva_assuj.', 'Changing it flips the default VAT-subject radio choice shown on the company setup page and the tva_assuj value assigned to societe objects that read it.', NULL, 0, 0, 'admin/company.php|admin/company.php|admin/company.php|admin/dict.php|admin/company.php', 1, 'a4dcf0d0ea9ca655b88a5d69db56f7d6c36f4a317f3733f29f84312dc1533cb8', 'v2', '2026-07-24T06:41:12+00:00', '["admin/company.php:265|write|dolibarr_set_const($db, \"FACTURE_TVAOPTION\", $usevat, ''chaine'', 0, '''', $conf->entity);", "societe/class/societe.class.php:4878|read|$this->tva_assuj = getDolGlobalInt(''FACTURE_TVAOPTION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FACTURE_VALIDATED_IN_AMOUNT', 'string', NULL, 'core', 'Switches the customer/supplier invoice late-payment dashboard boxes to sum invoice amounts (total_ht) instead of counting invoices.', 'core/lib/invoice.lib.php:443 sets `$amount_mode = (getDolGlobalInt(''FACTURE_VALIDATED_IN_AMOUNT'') == 1)`, which is then used throughout the surrounding SQL (lines 446-451) to choose between summing `f.total_ht` (amount_mode true) or counting rows with `1` (amount_mode false) for the late30/late15/latenow/notlatenow/notlate15/notlate30 buckets.', 'Setting it to 1 makes the invoice status boxes report the summed HT amounts of validated invoices per due-date bucket instead of the number of invoices; any other value keeps the default count-based behavior.', '1 = amounts (sum of f.total_ht) mode; other/unset = count mode (per `== 1` comparison in code).', 0, 0, NULL, 1, 'dc7cd323a2fa3f41e7a0341e68f441cf894270590a0203c7e671b26c762dbd44', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/invoice.lib.php:443: $amount_mode = (getDolGlobalInt(''FACTURE_VALIDATED_IN_AMOUNT'') == 1);", "core/lib/invoice.lib.php:446: sum(...) as late30 ... $amount_mode ? \"f.total_ht\" : 1"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FAC_FORCE_DATE_VALIDATION', 'string', NULL, 'compta', 'Forces the invoice date to be set to the validation date when an invoice is validated.', 'Set via admin/invoice.php:216 and checked in compta/facture/class/facture.class.php:3703 and :3725 with the inline comment ''If option enabled, we force invoice date''. Also read at compta/facture/card.php:4950 and :5480 to hide the manual date edit option. Admin UI at admin/invoice.php:872.', 'Enabling this prevents users from manually setting an invoice date that differs from the validation date; the date is overwritten at validation time.', '0 or unset = invoice date set manually; truthy value = invoice date forced to validation date.', 0, 0, 'admin/invoice.php|admin/invoice.php|admin/invoice.php', 1, 'fcb8a3ac2097a78a808b739a4804e4c26036ceb5f0077627251a2718c60b0d56', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/class/facture.class.php:3703|check|if (getDolGlobalString(''FAC_FORCE_DATE_VALIDATION'')) {\t// If option enabled, we force invoice date", "compta/facture/class/facture.class.php:3725|check|if (getDolGlobalString(''FAC_FORCE_DATE_VALIDATION'')) {\t// If option enabled, we force invoice date", "admin/invoice.php:872|read|print $form->selectyesno(\"forcedate\", getDolGlobalInt(''FAC_FORCE_DATE_VALIDATION'', 0), 1);", "compta/facture/card.php:5480|check|if ($action != ''editinvoicedate'' && $object->status == $object::STATUS_DRAFT && $usercancreate && !getDolGlobalString(''FAC_FORCE_DATE_VALIDATION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FATURE_LOCAL_TAX2_OPTION', 'string', NULL, 'core', 'Not a real active constant: appears to be a typo of FACTURE_LOCAL_TAX2_OPTION, found only inside a commented-out line of code.', 'The only occurrence in the source tree is a commented-out line in core/modules/commande/doc/pdf_einstein.modules.php:1152: `//if (getDolGlobalString(''FACTURE_LOCAL_TAX2_OPTION'') && getDolGlobalString(''FATURE_LOCAL_TAX2_OPTION'') == ''localtax2on'')`. The functioning constant elsewhere in Dolibarr (with an admin UI write in admin/company.php) is spelled FACTURE_LOCAL_TAX2_OPTION, not FATURE_LOCAL_TAX2_OPTION.', 'Setting this exact misspelled name has no effect in the codebase since the only reference to it is commented out; it is effectively dead/inert.', 'Exact behavior unclear from code alone.', 1, 0, NULL, 1, 'e28326a3c82afe4d0457a7ddc5b10a76bdf7eba445140eedef9fab90e9d1b25e', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/commande/doc/pdf_einstein.modules.php:1152: //if (getDolGlobalString(''FACTURE_LOCAL_TAX2_OPTION'') && getDolGlobalString(''FATURE_LOCAL_TAX2_OPTION'') == ''localtax2on'')"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ALLOW_ANY_CONTENT', 'bool', NULL, 'core', 'Allows any HTML content in the WYSIWYG editor instead of restricting to a predefined safe set of tags.', 'Checked at core/class/doleditor.class.php:221-222; when set, $restrictContent is set to false, disabling tag filtering. No admin UI; hidden setting.', 'Enabling this allows users to insert arbitrary HTML in the editor, which reduces XSS protection. Leaving unset restricts content to a safe predefined tag list.', '0 or empty = only predefined list of html tags are allowed; non-empty = all HTML content allowed in the editor', 1, 0, NULL, 1, 'cc50aca05a700e40605b2690166d7c3ccf230c7750fd11a2da8abfd78aaf1a6e', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/doleditor.class.php:222|read|$restrictContent = !getDolGlobalString(''FCKEDITOR_ALLOW_ANY_CONTENT''); // Only predefined list of html tags are allowed or all", "core/class/doleditor.class.php:221|read|if (isset($conf->global->FCKEDITOR_ALLOW_ANY_CONTENT)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_EDITORNAME', 'string', NULL, 'core', 'Selects which WYSIWYG editor backend (ckeditor or tinymce) is used across the application.', 'Defined via admin/fckeditor.php:128 (dolibarr_set_const) and read with getDolGlobalString(''FCKEDITOR_EDITORNAME'', ''ckeditor'') in admin/fckeditor.php:179, main.inc.php (2066, 2092), and core/class/doleditor.class.php:136.', 'Setting it to ''tinymce'' switches the editor backend loaded in main.inc.php to TinyMCE instead of the default CKEditor.', '''ckeditor'' or ''fckeditor'' (per comment); also used with value ''tinymce'' to select the TinyMCE backend', 0, 0, 'admin/fckeditor.php|admin/fckeditor.php', 1, 'd87b8209ba6e6ae028f7d32d48277218a4b34da5d4d314c61496600c5ca59b84', 'v2', '2026-07-24T06:41:12+00:00', '["core/class/doleditor.class.php:134  // Name of extended editor to use (FCKEDITOR_EDITORNAME can be ''ckeditor'' or ''fckeditor'')", "main.inc.php:2091  // TinyMCE (alternative WYSIWYG backend, selected by FCKEDITOR_EDITORNAME=''tinymce'')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_', 'bool', NULL, 'admin', 'Enables or disables the FCKeditor/CKeditor rich-text editor for a specific field or context identified by the constant suffix.', 'Written in admin/fckeditor.php:107 (set to ''1'') and :115 (set to ''0'') via dolibarr_set_const. The constant name is built as FCKEDITOR_ENABLE_ concatenated with a field/context identifier.', 'Setting to ''1'' activates the rich-text editor for the corresponding field; setting to ''0'' disables it and falls back to plain text.', '''1'' = editor enabled; ''0'' = editor disabled.', 0, 0, 'admin/fckeditor.php|admin/fckeditor.php', 1, '3823f27858b395a47836d9dd576f27974571241f343dd5779f35d91861cced63', 'v2', '2026-04-21T13:50:40+00:00', '["dolibarr_set_const($db, \"FCKEDITOR_ENABLE_\".$const, \"1\", ''chaine'', 0, '''', $conf->entity);", "dolibarr_set_const($db, \"FCKEDITOR_ENABLE_\".$const, \"0\", ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_DETAILS', 'bool', NULL, 'product', 'Enables the rich-text (FCKeditor/DolEditor) editor for product and intervention line description fields.', 'Passed as the editor-enable parameter to DolEditor instances in fichinter/card.php:1678 and 1759, product/card.php:1644 and 2275, contrat/card.php:1875, product/price_suppliers.php:843, and others (15 total occurrences). Written via admin/fckeditor.php:111 which sets it to ''1''. The comment in core/tpl/objectline_create.tpl.php:763 references it as a boolean conf property.', 'Enabling this constant activates the rich-text editor for description fields on product and intervention line forms; disabling it falls back to a plain textarea.', '1 = rich-text editor enabled; 0 or absent = plain textarea.', 0, 0, 'admin/tools/ui/components/inputs.php|admin/fckeditor.php', 1, '7fc297db739548a3e14cfaae264fc0283e2b59cf9f0cb6a817e13f2fde33296e', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:763  * @property {boolean} conf.FCKEDITOR_ENABLE_DETAILS", "admin/fckeditor.php:111|write|dolibarr_set_const($db, \"FCKEDITOR_ENABLE_DETAILS\", \"1\", ''chaine'', 0, '''', $conf->entity);", "fichinter/card.php:1678|read|$doleditor = new DolEditor(''np_desc'', $objp->description, '''', 164, ''dolibarr_details'', '''', false, true, getDolGlobalInt(''FCKEDITOR_ENABLE_DETAILS''), ROWS_2, ''90%'');", "product/card.php:1644|read|$doleditor = new DolEditor(''desc'', GETPOST(''desc'', ''restricthtml''), '''', 160, ''dolibarr_details'', '''', false, true, getDolGlobalString(''FCKEDITOR_ENABLE_DETAILS''), ROWS_4, ''90%'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_DETAILS_FULL', 'bool', NULL, 'core', 'Enables the FCKEditor (rich text editor) for the product description field on document line create and edit forms.', 'When set, a DolEditor rich text editor is rendered for the line description field in both objectline_create.tpl.php:453 and objectline_edit.tpl.php:193.', 'Enabling this constant replaces the plain textarea with a full rich-text editor for line descriptions, affecting both line creation and editing.', 'Truthy value = FCKEditor enabled; empty/unset = plain textarea.', 1, 0, NULL, 1, '991d685e9e275649223711bcbeb5dd996b4a741208e737957e201e0193fd470f', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:453|check|if (getDolGlobalString(''FCKEDITOR_ENABLE_DETAILS_FULL'')) {", "core/tpl/objectline_edit.tpl.php:193|check|if (getDolGlobalString(''FCKEDITOR_ENABLE_DETAILS_FULL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_IMAGE_UPLOAD', 'bool', NULL, 'core', 'Enables the local file browser/upload button in the CKEditor WYSIWYG toolbar used for composing emails.', 'Read in core/class/html.formmail.class.php:1169 to set $uselocalbrowser, passed to the DolEditor constructor that builds the mail composition WYSIWYG editor.', 'When true, the mail editor''s DolEditor instance is created with local browser/upload enabled, letting users insert images from local storage into the message body; when false/unset this is disabled.', 'Boolean: true/1 enables local image browser/upload in the mail editor, false/0 (default) disables it.', 1, 0, NULL, 1, '4be1f4850fb6383472fa008d962204dc8ffe2a1584d224f35f0969b158a18d5c', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:1169|read|$uselocalbrowser = getDolGlobalBool(''FCKEDITOR_ENABLE_IMAGE_UPLOAD'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_MAIL', 'bool', NULL, 'admin', 'Enables the CKEditor (FCKEditor) rich-text editor for mail composition fields in tickets and mail templates.', 'Checked across admin/ticket.php, admin/ticket_public.php, and admin/mails_templates.php. When enabled, DolEditor instances use CKEditor for mail body fields; when disabled, plain text areas are used.', 'Enabling activates the WYSIWYG HTML editor for mail fields; disabling falls back to plain text input.', 'Truthy integer (1) to enable CKEditor for mail fields; 0 or absent to use plain text.', 0, 0, 'admin/ticket.php|admin/ticket.php|admin/ticket.php|admin/ticket_public.php|admin/ticket_public.php|admin/mails_templates.php|admin/mails_templates.php|admin/mails_templates.php', 1, '855e4a2d27e4ccb4cf17eaa4a7feb7b3c4a00b60a2fa59e40b3c870550f87470', 'v2', '2026-04-21T13:29:58+00:00', '["admin/ticket.php:680|check|if (!getDolGlobalString(''FCKEDITOR_ENABLE_MAIL'')) {", "admin/ticket_public.php:505|read|$ckeditorenabledforticket = getDolGlobalInt(''FCKEDITOR_ENABLE_MAIL'') ? true : false;", "admin/mails_templates.php:928|check|if (!getDolGlobalString(''FCKEDITOR_ENABLE_MAIL'')) {", "admin/ticket.php:790|read|$doleditor = new DolEditor(''TICKET_MESSAGE_MAIL_INTRO'', $mail_intro, ''100%'', 90, ''dolibarr_mailings'', '''', false, true, getDolGlobalInt(''FCKEDITOR_ENABLE_MAIL''), ROWS_2, ''70'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_MAILING', 'bool', NULL, 'comm', 'Enables the rich-text (WYSIWYG) editor for composing the email body in the mass-mailing module.', 'Read via getDolGlobalInt(''FCKEDITOR_ENABLE_MAILING'') in comm/mailing/card.php (964, 1445, 1731) to pass as a DolEditor toolbar flag, and checked in comm/mailing/class/mailing.class.php:429 and comm/mailing/card.php:1286.', 'Enabling it activates the WYSIWYG editor for the mailing body field instead of a plain textarea, and gates the dol_textishtml check in mailing.class.php:429.', NULL, 0, 0, NULL, 1, '014b69ee6a2af8513875654c9a13e1b563475dfbd3aa74aa00eea37f9dc35cff', 'v2', '2026-07-24T06:41:12+00:00', '["comm/mailing/class/mailing.class.php:429|check|if (getDolGlobalString(''FCKEDITOR_ENABLE_MAILING'') && dol_textishtml(dol_html_entity_decode($obj->body, ENT_COMPAT | ENT_HTML5))) {", "comm/mailing/card.php:1286|check|if (isModEnabled(''fckeditor'') && getDolGlobalInt(''FCKEDITOR_ENABLE_MAILING'') && $object->messtype != ''sms'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_NOTE_PRIVATE', 'bool', NULL, 'fourn', 'Enables the rich-text editor for the private note field across many object cards (invoices, orders, contracts, contacts, products, etc.).', 'Checked in core/tpl/notes.tpl.php:131 and used as the DolEditor toolbar flag in fourn/facture/card.php:2942, fourn/commande/card.php:2132, product/card.php:1827, fichinter/card.php:1168, contrat/card.php:1355, contact/card.php:1184, compta/facture/card.php:4780, and more.', 'Enabling it activates the WYSIWYG editor for the note_private textarea instead of plain text across all these object cards.', NULL, 0, 0, NULL, 1, '1d73837b8cfcdb686b63bf7f04b72117c2f0f3bc8d15e039c6b7eecd1d836099', 'v2', '2026-07-24T06:41:12+00:00', '["core/tpl/notes.tpl.php:131|check|if (isModEnabled(''fckeditor'') && getDolGlobalString(''FCKEDITOR_ENABLE_NOTE_PRIVATE'')) {", "product/card.php:1827|read|$doleditor = new DolEditor(''note_private'', GETPOST(''note_private'', ''restricthtml''), '''', 140, ''dolibarr_details'', '''', false, true, getDolGlobalString(''FCKEDITOR_ENABLE_NOTE_PRIVATE''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_NOTE_PUBLIC', 'bool', NULL, 'fourn', 'Enables the rich-text editor for the public note field across many object cards (receptions, invoices, orders, contracts, etc.).', 'Checked in core/tpl/notes.tpl.php:126 and used as the DolEditor toolbar flag in reception/card.php (1343, 1468), fourn/facture/card.php:2933, fourn/facture/card-rec.php:1051, fourn/commande/card.php:2124, fichinter/card.php:1158, contrat/card.php:1348.', 'Enabling it activates the WYSIWYG editor for the note_public textarea instead of plain text across these object cards.', NULL, 0, 0, NULL, 1, 'c1a02304eb0929d8f60d3529835a7cb3e35681e86670b6c3c32c6f652a44764b', 'v2', '2026-07-24T06:41:12+00:00', '["core/tpl/notes.tpl.php:126|check|if (isModEnabled(''fckeditor'') && getDolGlobalString(''FCKEDITOR_ENABLE_NOTE_PUBLIC'')) {", "reception/card.php:1343|read|$doleditor = new DolEditor(''note_public'', (string) $note_public, '''', 80, ''dolibarr_notes'', ''In'', false, false, !getDolGlobalString(''FCKEDITOR_ENABLE_NOTE_PUBLIC'') ? 0 : 1, ROWS_3,"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_PDF', 'bool', NULL, 'core', 'Enables the CKEditor ''exportpdf'' plugin (export editor content to PDF) in the CKEditor toolbar.', 'Checked in core/class/doleditor.class.php:271 in the same plugin-disable list builder as FCKEDITOR_ENABLE_WSC; if not set, '',exportpdf'' is appended to $pluginstodisable, removing that button/feature from the toolbar.', 'Enabling it keeps the CKEditor ''export to PDF'' plugin active in the editor toolbar; disabled by default.', 'Boolean-like: truthy keeps the ''exportpdf'' plugin enabled; falsy/unset (default) disables it.', 1, 0, NULL, 1, '66af3bf2592bc0cdf6dcee491eb819572e6d59be8a4486f5d008fce8ac0c3799', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/doleditor.class.php:271|check|if (!getDolGlobalString(''FCKEDITOR_ENABLE_PDF'')) {", "$pluginstodisable .= '',exportpdf'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_SCAYT_AUTOSTARTUP', 'bool', NULL, 'core', 'Auto-starts the CKEditor SCAYT (Spell Check As You Type) plugin when the editor loads.', 'Checked in core/class/doleditor.class.php:278; when set, the JS config is given ''scayt_autoStartup: true,'' plus a scayt_sLang language setting; when unset, SCAYT is instead added to the disabled-plugins list ('',scayt'').', 'Enabling it makes CKEditor start spell-check-as-you-type automatically for all editor instances using this toolbar; leaving it unset disables the SCAYT plugin entirely rather than just not-autostarting it.', 'Boolean-like: truthy enables SCAYT with autostart; falsy/unset disables the SCAYT plugin outright.', 1, 0, NULL, 1, 'd33d59ca4e531edd6b811ab7339b1a4b46024de791a59c9f1089bf264b9a6478', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/doleditor.class.php:278|check|if (getDolGlobalString(''FCKEDITOR_ENABLE_SCAYT_AUTOSTARTUP'')) {", "$scaytautostartup = ''scayt_autoStartup: true,''; $scaytautostartup .= ''scayt_sLang: \\''''.dol_escape_js($langs->getDefaultLang()).''\\'','';", "} else { $pluginstodisable .= '',scayt''; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_SOCIETE', 'bool', NULL, 'projet', 'Enables the rich-text (FCKEditor/DolEditor) widget on note and description fields across project, task, and third-party forms.', 'Checked in 16 locations. projet/tasks/task.php:121 disables a behaviour when this constant is absent; projet/card.php:924 and :1338 pass it as the editor-enable flag to DolEditor; projet/tasks.php:885 and webportal/class/html.formwebportal.class.php:1268 also use it as the enable condition.', 'Enabling this constant activates the rich-text editor on description and note fields in project and task forms; disabling reverts to plain-text areas.', 'Non-zero/non-empty = rich-text editor enabled; 0 or unset = plain-text textarea.', 1, 0, NULL, 1, 'ac14b8aa343db923ca246a53378bdab7df7a30bf75a1d2c504280b0be94e36f4', 'v2', '2026-04-21T11:16:15+00:00', '["projet/tasks/task.php:121|check|if (!getDolGlobalString(''FCKEDITOR_ENABLE_SOCIETE'')) {", "projet/card.php:924|read|$doleditor = new DolEditor(''description'', GETPOST(\"description\", ''restricthtml''), '''', 90, ''dolibarr_notes'', '''', false, true, isModEnabled(''fckeditor'') && getDolGlobalString(''FCKEDI", "projet/card.php:1338|read|$doleditor = new DolEditor(''description'', $object->description, '''', 90, ''dolibarr_notes'', '''', false, true, isModEnabled(''fckeditor'') && getDolGlobalInt(''FCKEDITOR_ENABLE_SOCIETE''),", "webportal/class/html.formwebportal.class.php:1268|read|$doleditor = new DolEditor($htmlName, $value, '''', 200, ''dolibarr_notes'', ''In'', false, false, isModEnabled(''fckeditor'') && getDolGlobalInt(''FCKEDITOR_ENABLE_SOCIETE''), ROWS_5, ''90%''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_SPECIALCHAR', 'bool', NULL, 'core', 'Enables the special-character insertion button/toolbar entry in the rich-text editor.', 'Written (set to ''1'' or deleted) by admin/fckeditor.php (119, 122) and checked via getDolGlobalString(''FCKEDITOR_ENABLE_SPECIALCHAR'') in core/class/doleditor.class.php (262, 372).', 'Enabling it changes the toolbar/config generated by doleditor.class.php to include the special character feature.', NULL, 0, 0, 'admin/fckeditor.php|admin/fckeditor.php', 1, '49a6c84016b49df5a604b6a19bcfa40e07836c5a16927a68e1b6a5cd064740a3', 'v2', '2026-07-24T06:41:12+00:00', '["admin/fckeditor.php:119|write|dolibarr_set_const($db, \"FCKEDITOR_ENABLE_SPECIALCHAR\", \"1\", ''chaine'', 0, '''', $conf->entity);", "core/class/doleditor.class.php:262|check|if (!getDolGlobalString(''FCKEDITOR_ENABLE_SPECIALCHAR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_TICKET', 'bool', NULL, 'public', 'Controls where the rich-text editor is allowed for ticket messages: disabled, backoffice only, or backoffice plus the public ticket page.', 'Read via getDolGlobalInt/getDolGlobalString(''FCKEDITOR_ENABLE_TICKET'') in public/ticket/create_ticket.php (272, 335), ticket/class/actions_ticket.class.php:246, and core/class/html.formticket.class.php (571, 1899).', 'Setting it to 2 enables the rich-text editor even on the public ticket creation page, which the code comments flag as ''very dangerous''; 1 restricts it to backoffice only; 0 disables it.', '0=no rich text editor, 1=allowed on backoffice only, 2=allowed on backoffice and public page (very dangerous)', 0, 0, NULL, 1, 'f8c28285d566de5b5efcce11cca3de9954d3998b819b4ed5d6edfb27c5a81ccd', 'v2', '2026-07-24T06:41:12+00:00', '["public/ticket/create_ticket.php:272|check|if (getDolGlobalInt(''FCKEDITOR_ENABLE_TICKET'') >= 2) {\t\t// 0=no reich text editor, 1=allowed on backoffice only, 2=allowed on backoffice and public page (very dangerous)", "ticket/class/actions_ticket.class.php:246|read|$ckeditorenabledforticket = (getDolGlobalString(''FCKEDITOR_ENABLE_TICKET'') >= 1);\t\t// 0=no, 1=from backoffice only, 2=from backoffice+public (very dangerous)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_USERSIGN', 'bool', NULL, 'admin', 'Enables the rich-text (FCKeditor/DolEditor) editor for user email signature fields when set to a truthy value.', 'Referenced in admin/mails_senderprofile_list.php (lines 449, 481) and user/card.php (lines 1462, 3090). The editor''s wysiwygtype parameter is set to 1 when the constant is non-empty, and 0 (plain textarea) otherwise.', 'Enabling this constant activates the rich-text editor for signature fields; disabling it reverts signatures to plain-text input.', 'Empty/0 = plain textarea; any non-empty/truthy value = rich-text editor enabled.', 0, 0, 'admin/mails_senderprofile_list.php|admin/mails_senderprofile_list.php', 1, '7c810939f9c49206934bfdcde006b5396af12db6ea4d537e074e5c4be62c7c63', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_senderprofile_list.php:481|read|!getDolGlobalString(''FCKEDITOR_ENABLE_USERSIGN'') ? 0 : 1, ROWS_4, ''90%''", "user/card.php:3090|read|!getDolGlobalString(''FCKEDITOR_ENABLE_USERSIGN'') ? 0 :", "admin/mails_senderprofile_list.php:449|read|!getDolGlobalString(''FCKEDITOR_ENABLE_USERSIGN'')", "user/card.php:1462|read|getDolGlobalString(''FCKEDITOR_ENABLE_USERSIGN'')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_ENABLE_WSC', 'bool', NULL, 'core', 'Enables the legacy CKEditor ''wsc'' (WebSpellChecker) plugin in the CKEditor toolbar.', 'Checked in core/class/doleditor.class.php:268 while building the list of CKEditor plugins to disable; if not set, '',wsc'' is appended to $pluginstodisable, removing the spellchecker plugin from the toolbar. The inline comment notes the spellchecker service reached end-of-life in December 2021.', 'Enabling it keeps the CKEditor WSC spellchecker plugin active in the toolbar instead of being disabled by default; per the code comment the underlying WSC service is already end-of-life so it may have no functional effect even if enabled [SPECULATION].', 'Boolean-like: truthy keeps the ''wsc'' plugin enabled; falsy/unset (default) disables it.', 1, 0, NULL, 1, 'e516d0dd4aed2fbf584f6f8e43d171d7d13e487507dd8948dcc9520ca72621c1', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/doleditor.class.php:268|check|if (!getDolGlobalString(''FCKEDITOR_ENABLE_WSC'')) {\t// spellchecker has end of life december 2021", "$pluginstodisable .= '',wsc'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_SKIN', 'string', NULL, 'core', 'Specifies the CKEditor skin (theme) used by the Dolibarr rich text editor.', 'Read in core/lib/doleditor.lib.php:52 and core/class/doleditor.class.php:250 with a default of ''moono-lisa'', which is noted as the default with CKEditor 4.6. No admin UI manages this constant.', 'Changing this alters the visual theme of the CKEditor interface; incorrect skin names will cause the editor to fall back or fail to render.', 'Skin name string; default with ckeditor 4.6 : moono-lisa.', 1, 0, NULL, 1, '1090f3f4613d5d58e43cde567a69b1679792bc3ab21b4c191b8f8e2ceb35f01d', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/doleditor.class.php:250|read|$skin = getDolGlobalString(''FCKEDITOR_SKIN'', ''moono-lisa'');\t\t// default with ckeditor 4.6 : moono-lisa", "core/lib/doleditor.lib.php:52|read|$selected_theme = getDolGlobalString(''FCKEDITOR_SKIN'', ''moono-lisa'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FCKEDITOR_TEST', 'string', NULL, 'admin', 'Stores a test string used to validate and preview the FCKEditor/rich-text editor configuration in the Dolibarr admin panel.', 'Written via admin/fckeditor.php:131 through dolibarr_set_const and read back at admin/fckeditor.php:266 to populate a DolEditor instance for preview, and at admin/fckeditor.php:271 to print the raw value. Managed entirely via the admin UI at admin/fckeditor.php.', 'Changing this value alters the content shown in the editor test/preview field; it has no effect on production document generation.', 'Any string (used as editor preview content)', 0, 0, 'admin/fckeditor.php|admin/fckeditor.php|admin/fckeditor.php', 1, 'f94a345c54e5d7f810a4372e0e2b00c0416d05db449d158a2fa9323429d0fa13', 'v2', '2026-04-21T13:50:40+00:00', '["$result = dolibarr_set_const($db, ''FCKEDITOR_TEST'', $fckeditor_test, ''chaine'', 0, '''', $conf->entity);", "$editor = new DolEditor(''formtestfield'', getDolGlobalString(''FCKEDITOR_TEST'', ''Test''), '''', 200, $mode, ''In'', true, $uselocalbrowser, 1, 120, ''8'', $readonly);", "print getDolGlobalString(''FCKEDITOR_TEST'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHEINTER_ADDON', 'string', NULL, 'fichinter', 'Selects the numbering module used to generate reference numbers for intervention sheets.', 'Stores the class name suffix of the active numbering module for intervention sheets. Used in fichinter/class/fichinter.class.php:1032-1033 to build the filename and class name, and in fichinter/card.php:53-54 to require the module file. Configured via admin/fichinter.php.', 'Changing this value switches the numbering algorithm applied to new intervention sheet references.', 'Name suffix of the numbering module (e.g. ''mod_fichinter_mercure''). Must match a file in core/modules/fichinter/.', 0, 0, 'admin/fichinter.php|admin/fichinter.php', 1, 'd749cc03a8b13e45d088993ae61807b0ca6620a825427287026e50d843c9ef6d', 'v2', '2026-04-21T11:16:15+00:00', '["fichinter/class/fichinter.class.php:1019  *\tdepending on the module numbering assets within FICHEINTER_ADDON", "fichinter/class/fichinter.class.php:1032|read|$file = \"mod_\" . getDolGlobalString(''FICHEINTER_ADDON'').\".php\";", "fichinter/card.php:53|check|if (getDolGlobalString(''FICHEINTER_ADDON'') && is_readable(DOL_DOCUMENT_ROOT.\"/core/modules/fichinter/mod_\" . getDolGlobalString(''FICHEINTER_ADDON'').\".php\")) {", "admin/fichinter.php:153|write|dolibarr_set_const($db, \"FICHEINTER_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHEINTER_ADDON_PDF', 'string', NULL, 'admin', 'Selects the PDF/document numbering template module used to generate intervention (fichinter) documents.', 'Set via admin/fichinter.php (write at 138/141, delete at 133) and read via getDolGlobalString(''FICHEINTER_ADDON_PDF'') in core/modules/fichinter/modules_fichinter.php:125-126 and fichinter/class/fichinter.class.php:849 to pick the model class.', 'Changing the value switches which fichinter document-generation template class is used to create the intervention PDF.', NULL, 0, 0, 'admin/fichinter.php|admin/fichinter.php|admin/fichinter.php|admin/fichinter.php|admin/fichinter.php', 1, '935df23db58f10d6bfeb546ccac44904e8c4eb0455a138decb36872263bd5859', 'v2', '2026-07-24T06:41:12+00:00', '["core/modules/fichinter/modules_fichinter.php:102  *  Create an intervention document on disk using template defined into FICHEINTER_ADDON_PDF", "core/modules/fichinter/modules_fichinter.php:126|read|$modele = getDolGlobalString(''FICHEINTER_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'admin', 'Allows external (customer-facing) users to download the intervention (fichinter) document.', 'Set via dolibarr_set_const in admin/fichinter.php:242 (''yesno'' type) and checked via getDolGlobalString(''FICHINTER_ALLOW_EXTERNAL_DOWNLOAD'') in admin/fichinter.php:687, fichinter/card.php:2059, and core/lib/functions.lib.php:10752.', 'Enabling it allows the external download link/action for non-draft intervention documents to appear, per fichinter/card.php:2059''s status check.', 'yesno (0 or 1)', 0, 0, 'admin/fichinter.php|admin/fichinter.php', 1, '0255fc0a71707779f31bc4e8f887540fb4b547a3019926215d17883316e07318', 'v2', '2026-07-24T06:41:12+00:00', '["admin/fichinter.php:242|write|$res = dolibarr_set_const($db, \"FICHINTER_ALLOW_EXTERNAL_DOWNLOAD\", $setFichInterAllowExternalDownload, ''yesno'', 0, '''', $conf->entity);", "fichinter/card.php:2059|check|if ($object->status != Fichinter::STATUS_DRAFT && getDolGlobalString(''FICHINTER_ALLOW_EXTERNAL_DOWNLOAD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_ALLOW_ONLINE_SIGN', 'bool', NULL, 'admin', 'Allows online electronic signature of the intervention (fichinter) document.', 'Set via dolibarr_set_const in admin/fichinter.php:230 (''yesno'' type) and checked via getDolGlobalString(''FICHINTER_ALLOW_ONLINE_SIGN'') in admin/fichinter.php:667 and fichinter/card.php:2065.', 'Enabling it makes the online-signature feature available for non-draft intervention sheets, per fichinter/card.php:2065''s status check.', 'yesno (0 or 1)', 0, 0, 'admin/fichinter.php|admin/fichinter.php', 1, '7302eb0e3310eaf297ee4703b43049931a5a042cb58b8404597ebe199f5dc318', 'v2', '2026-07-24T06:41:12+00:00', '["admin/fichinter.php:230|write|$res = dolibarr_set_const($db, \"FICHINTER_ALLOW_ONLINE_SIGN\", $setFichInterAllowOnlineSign, ''yesno'', 0, '''', $conf->entity);", "fichinter/card.php:2065|check|if ($object->status != Fichinter::STATUS_DRAFT && getDolGlobalString(''FICHINTER_ALLOW_ONLINE_SIGN'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_ARTIC_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the ''Arctic'' automatic numbering module for intervention sheets.', 'Used exclusively within core/modules/fichinter/mod_arctic.php. At line 96 it is displayed in a configuration input field; at line 142 it is loaded as the active mask for number generation.', 'Changing the mask alters the format of newly generated intervention-sheet reference numbers; existing references are unaffected.', 'Any mask string accepted by the Arctic numbering module (e.g. ''{YYYY}{MM}{0000}'').', 1, 0, NULL, 1, 'e1acbe20ae5b982e5efbdb03da63f7c131000d779b24aa4ce09fbff9ed3b1310', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/fichinter/mod_arctic.php:96|read|value=\"''.getDolGlobalString(\"FICHINTER_ARTIC_MASK\").\"''>\"", "core/modules/fichinter/mod_arctic.php:142|read|$mask = getDolGlobalString(\"FICHINTER_ARTIC_MASK\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_CLASSIFY_BILLED', 'string', NULL, 'fichinter', 'Enables a dedicated ''billed'' status classification for intervention sheets, controlling billing-state workflow and trigger handling.', 'When set, fichinter/card.php:1943 activates the billed classification path (noted as deprecated in the comment on that line). When unset, admin/agenda.php:202 discards the FICHINTER_CLASSIFY_BILLED and FICHINTER_CLASSIFY_UNBILLED triggers. fichinter/card.php:1966 gates the billing action button on this constant being absent and the status being between draft and closed.', 'Enabling this constant activates the legacy billed-status workflow for intervention sheets; disabling it suppresses the related triggers and billing action.', 'Truthy value enables billed classification; absent or falsy disables it. The code marks this option as deprecated.', 0, 0, 'admin/agenda.php|admin/agenda.php', 1, 'ced45f76002050b239c86c8c43ee9b8cf53b4fdd163d36085b6b1279ab87edae', 'v2', '2026-04-21T11:16:15+00:00', '["admin/agenda.php:201  // Discard special case: If option FICHINTER_CLASSIFY_BILLED is not set, we discard both trigger FICHINTER_CLASSIFY_BILLED and FICHINTER_CLASSIFY_UNBILLED", "fichinter/card.php:1943|check|if (getDolGlobalString(''FICHINTER_CLASSIFY_BILLED'')) {    // Option deprecated. In a future, billed must be managed with a dedicated field to 0 or 1", "fichinter/card.php:1966|check|if (!getDolGlobalString(''FICHINTER_CLASSIFY_BILLED'') && $object->status > Fichinter::STATUS_DRAFT && $object->status < Fichinter::STATUS_CLOSED) {", "modulebuilder/template/core/triggers/interface_99_modMyModule_MyModuleTriggers.class.php:253  //case ''FICHINTER_CLASSIFY_BILLED'':\t\t\t// TODO Replace it with FICHINTER_BILLED"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_DATE_WITHOUT_HOUR', 'string', NULL, 'fichinter', 'Controls whether intervention (fichinter) dates are displayed/handled without a time component (date only, no hour).', 'Set via dolibarr_set_const in admin/fichinter.php:218 (''yesno'' type) and checked in fichinter/card.php (647, 1750, 1835, 1843) and core/modules/fichinter/doc/pdf_soleil.modules.php:315 to choose date-only vs date+hour formatting.', 'Enabling it switches date printing in fichinter/card.php:1679 from ''dayhour'' format to a date-only format, affecting intervention date display and the PDF template.', 'yesno (0 or 1)', 0, 0, 'admin/fichinter.php|admin/fichinter.php', 1, 'a06e82d503dc457fef256abdd0d7e9374b17c0aab05230ba4c1407a28e9d5728', 'v2', '2026-07-24T06:41:12+00:00', '["admin/fichinter.php:218|write|$res = dolibarr_set_const($db, \"FICHINTER_DATE_WITHOUT_HOUR\", $setFichInterDateWithoutHour, ''yesno'', 0, '''', $conf->entity);", "fichinter/card.php:1679|read|print ''<td class=\"center\" width=\"150\">''.(!getDolGlobalString(''FICHINTER_DATE_WITHOUT_HOUR'') ? dol_print_date($db->jdate($objp->date_intervention), ''dayhour'') : dol_print_date($db->"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_DISABLE_DETAILS', 'bool', NULL, 'fichinter', 'Hides or restricts the intervention line-detail table on the fichinter (intervention) card.', 'Checked at 16 occurrences across fichinter/card.php and fichinter/card-rec.php. The pattern `!getDolGlobalString(''FICHINTER_DISABLE_DETAILS'') || getDolGlobalString(''FICHINTER_DISABLE_DETAILS'') == ''2''` shows the duration/line-detail blocks unless the value is truthy and not ''2''; separately, value ''1'' specifically allows validating an intervention with zero lines (fichinter/card.php:1921).', 'Setting it to any truthy value other than ''2'' hides the intervention line-detail sections (duration, line list/add forms); setting it specifically to ''1'' additionally allows validating an intervention that has no lines at all; setting it to ''2'' keeps details visible while still enabling that relaxed validation behavior implied elsewhere in the same conditions.', '0/empty = show details (default); ''1'' = disable details and allow validation with 0 lines; ''2'' = special value still shown as satisfying the ''not disabled'' condition.', 0, 0, NULL, 1, 'b44b182707ccb24268e21beb829fe9134ed359b02171a7a4b3bddab00f918129', 'v2', '2026-07-24T07:05:23+00:00', '["fichinter/card.php:1559|if (!getDolGlobalString(''FICHINTER_DISABLE_DETAILS'') || getDolGlobalString(''FICHINTER_DISABLE_DETAILS'') == ''2'') {", "fichinter/card.php:1921|if ($object->status == Fichinter::STATUS_DRAFT && (count($object->lines) > 0 || getDolGlobalString(''FICHINTER_DISABLE_DETAILS'') == ''1'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_DRAFT_WATERMARK', 'string', NULL, 'admin', 'Specifies the watermark text overlaid on draft intervention (fichinter) PDF documents.', 'Written via admin/fichinter.php:169 and displayed in the settings UI at :579. Applied in core/modules/fichinter/doc/pdf_soleil.modules.php:155-156 when the intervention status is draft.', 'Setting a non-empty string overlays that text as a watermark on draft fichinter PDFs. Leaving empty disables the draft watermark.', 'Empty = no watermark on draft PDFs; any string = text used as watermark on draft intervention PDFs', 0, 0, 'admin/fichinter.php|admin/fichinter.php', 1, '54e4bfa6a46af366725e6638ba3ec8b73b4b118df2d01bf75122659126610830', 'v2', '2026-04-21T13:50:40+00:00', '["admin/fichinter.php:169|write|$res = dolibarr_set_const($db, \"FICHINTER_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "core/modules/fichinter/doc/pdf_soleil.modules.php:155|check|if ($object->status == $object::STATUS_DRAFT && (getDolGlobalString(''FICHINTER_DRAFT_WATERMARK''))) {", "core/modules/fichinter/doc/pdf_soleil.modules.php:156|read|$this->watermark = getDolGlobalString(''FICHINTER_DRAFT_WATERMARK'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_EMPTY_LINE_DESC', 'string', NULL, 'fichinter', 'Allows intervention (fichinter) lines to be added without a description.', 'Checked in fichinter/card.php:610 (addline action: skips the ''Description is required'' error) and :1809 in the intervention line detail area.', 'When set, users can save an intervention line with an empty description; by default an empty description with no np_desc GETPOST triggers a required-field error.', 'Boolean: truthy allows empty line description; falsy (default) requires it.', 0, 0, NULL, 1, '9717a900f82c5aa28ea0c133d5ae86abb230c5c999fec3369135af95e970d0e9', 'v2', '2026-07-24T07:05:23+00:00', '["fichinter/card.php:610|if (!GETPOST(''np_desc'', ''restricthtml'') && !getDolGlobalString(''FICHINTER_EMPTY_LINE_DESC'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated intervention sheet (fiche d''intervention) documents.', 'Written from admin/fichinter.php:156 via dolibarr_set_const() when the admin saves the intervention module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated intervention documents; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/fichinter.php', 1, 'd70bd7bd7d5cc47c405c3e05e2b43217811dee0b21c7333a22b917f0aae60de0', 'v2', '2026-07-24T07:05:23+00:00', '["admin/fichinter.php:156|write|$res = dolibarr_set_const($db, \"FICHINTER_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_HIDE_ADD_CONTACT_THIPARTY', 'bool', NULL, 'fichinter', 'Hides the ''add third-party contact'' option on the intervention (fichinter) contact-add form (note: constant name has a typo, ''THIPARTY'' instead of ''THIRDPARTY'').', 'Checked in fichinter/contact.php:177; when set, the local variable $hideaddcontactforthirdparty is forced to 1, which is passed to the shared contact-list template to suppress the third-party contact-add control.', 'When set, users cannot add a third-party contact on an intervention via this screen.', 'Not set/falsy (default): third-party contact-add control shown. Truthy: control hidden.', 1, 0, NULL, 1, '30a0976df859594dbe5bf664a92323cd591bad679d4b0c59c40cb2f3fadb74a4', 'v2', '2026-07-24T07:05:23+00:00', '["fichinter/contact.php:177|check|if (getDolGlobalString(''FICHINTER_HIDE_ADD_CONTACT_THIPARTY'')) {", "fichinter/contact.php:178|code|$hideaddcontactforthirdparty = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_HIDE_ADD_CONTACT_USER', 'bool', NULL, 'fichinter', 'Hides the ''add internal user contact'' option on the intervention (fichinter) contact-add form.', 'Checked in fichinter/contact.php:174; when set, the local variable $hideaddcontactforuser is forced to 1, which is passed to the shared contact-list template to suppress the internal-user contact-add control.', 'When set, users cannot add an internal user as a contact on an intervention via this screen.', 'Not set/falsy (default): internal user contact-add control shown. Truthy: control hidden.', 1, 0, NULL, 1, '74ef9f014c0aab23d55c484b3cb8c05fa3ed926db29aa32f0ff74ac54467d128', 'v2', '2026-07-24T07:05:23+00:00', '["fichinter/contact.php:174|check|if (getDolGlobalString(''FICHINTER_HIDE_ADD_CONTACT_USER'')) {", "fichinter/contact.php:175|code|$hideaddcontactforuser = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_HIDE_EMPTY_DURATION', 'bool', NULL, 'fichinter', 'Hides intervention lines that have a zero duration from the line-detail listing.', 'Checked in fichinter/card.php:1605: when set, the SQL query for fichinterdet lines adds a `AND ft.duree <> 0` filter, excluding zero-duration lines from the results.', 'Enabling it removes zero-duration intervention lines from the displayed list of lines on the card.', 'Boolean: truthy filters out lines where duree = 0.', 0, 0, NULL, 1, 'fae6f2e12e384f73df90fd255d185a688ca5dc3e44909866715ba989b38c9e17', 'v2', '2026-07-24T07:05:23+00:00', '["fichinter/card.php:1605|if (getDolGlobalString(''FICHINTER_HIDE_EMPTY_DURATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_ONLINE_SIGNATURE_SECURITY_TOKEN', 'string', NULL, 'core', 'Secret salt used to verify the security key on public online-signature links for interventions (fichinter).', 'Read in core/lib/signature.lib.php:166, public/onlinesign/newonlinesign.php:154 and core/ajax/onlineSign.php:93 as $securekeyseed, falling back to a hash derived from the instance unique ID if unset; combined with type/ref via dol_verifyHash() to validate the SECUREKEY query parameter.', 'Changing this value invalidates all previously generated online-signature links for fichinter documents, since the verification hash depends on it.', 'Any string used as a hash salt; falls back to substr(dol_hash(''dolibarr''.$dolibarr_main_instance_unique_id,''sha256''),0,32) if not set.', 1, 0, NULL, 1, '8cf03097095feeed43a5645fda27ea602fa130f0a789f6d5e12858da68a73343', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/signature.lib.php:166: $securekeyseed = getDolGlobalString(''FICHINTER_ONLINE_SIGNATURE_SECURITY_TOKEN'', $defaultsalt);", "public/onlinesign/newonlinesign.php:150: $defaultsalt = substr(dol_hash(''dolibarr''.$dolibarr_main_instance_unique_id, ''sha256''), 0, 32);", "public/onlinesign/newonlinesign.php:159: if (!dol_verifyHash($securekeyseed.$type.$ref...(...), $SECUREKEY, ''hash'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_PRINT_PRODUCTS', 'string', NULL, 'fichinter', 'Controls whether product-type lines (not just service-type lines) are printed/shown when generating an intervention from an origin document.', 'Set via dolibarr_set_const in admin/fichinter.php:182 (''yesno'' type) and checked in fichinter/card.php:419 and fichinter/card.php:1237 (printOriginLinesList call).', 'Enabling it makes printOriginLinesList show both services and products instead of restricting the origin lines list to services only.', 'yesno (0 or 1)', 0, 0, 'admin/fichinter.php|admin/fichinter.php', 1, '795d92e9d24e29cd5fc4765f524585fc85d0f64ac307a62e3de1bafe106bb5d7', 'v2', '2026-07-24T06:41:12+00:00', '["admin/fichinter.php:182|write|$res = dolibarr_set_const($db, \"FICHINTER_PRINT_PRODUCTS\", $setFichInterPrintProducts, ''yesno'', 0, '''', $conf->entity);", "fichinter/card.php:1237|read|$objectsrc->printOriginLinesList(!getDolGlobalString(''FICHINTER_PRINT_PRODUCTS'') ? ''services'' : ''''); // Show only service, except if option FICHINTER_PRINT_PRODUCTS is on"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_SIGNATURE_ON_ALL_PAGES', 'string', NULL, 'core', 'Controls whether the online signature image is stamped on every page of a fichinter (intervention) PDF or only the last one.', 'Checked in core/ajax/onlineSign.php:556 inside the PDF page loop, and again at line 585 (negated) after the loop to place the signature only once if the option is off.', 'When set, the signature image is drawn on each imported PDF page during the loop; when unset, it is drawn once after all pages are processed.', 'Boolean-like (truthy/falsy), no explicit value list in code.', 1, 0, NULL, 1, '335fe751961ae923c108214c3f046ead3c2eae3347405d9127cc324cc25b9aa4', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:556: if (getDolGlobalString(\"FICHINTER_SIGNATURE_ON_ALL_PAGES\")) {", "core/ajax/onlineSign.php:585: if (!getDolGlobalString(\"FICHINTER_SIGNATURE_ON_ALL_PAGES\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_SIGNATURE_WFORIMG', 'string', NULL, 'core', 'Overrides the width of the online signature image on a fichinter PDF, used only when FICHINTER_SIGNATURE_ON_ALL_PAGES is set.', 'Read at core/ajax/onlineSign.php:571; if truthy it replaces the computed default of $s[''w''] - ($param[''xforimgstart''] + 20).', 'Setting it changes the rendered width of the signature image; leaving it unset keeps the automatic default computed from page width and X start.', 'Numeric width in PDF units; falls back to computed default if empty.', 1, 0, NULL, 1, 'eab78ca90e1ba3017c1a28cca66147dc7ae9249146a269abd1a9975c769ea75c', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:570: if (getDolGlobalString(\"FICHINTER_SIGNATURE_WFORIMG\")) {", "core/ajax/onlineSign.php:571: $param[''wforimg''] = getDolGlobalString(\"FICHINTER_SIGNATURE_WFORIMG\");", "core/ajax/onlineSign.php:573: $param[''wforimg''] = $s[''w''] - ($param[''xforimgstart''] + 20);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_SIGNATURE_XFORIMGSTART', 'string', NULL, 'core', 'Overrides the X coordinate where the online signature image starts on a fichinter PDF, used only when FICHINTER_SIGNATURE_ON_ALL_PAGES is set.', 'Read at core/ajax/onlineSign.php:561; if truthy it replaces the computed default of $s[''w'']/2 - 2 (or 110 if page width unknown).', 'Setting it changes the horizontal placement of the signature image; leaving it unset keeps the automatic centering computed from page width.', 'Numeric X coordinate in PDF units; falls back to computed default if empty.', 1, 0, NULL, 1, '0c44458383e3b45c824cdc1ab46ff9fe4d70d9871983db4e5ce54adbcfa763b0', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:560: if (getDolGlobalString(\"FICHINTER_SIGNATURE_XFORIMGSTART\")) {", "core/ajax/onlineSign.php:561: $param[''xforimgstart''] = getDolGlobalString(\"FICHINTER_SIGNATURE_XFORIMGSTART\");", "core/ajax/onlineSign.php:563: $param[''xforimgstart''] = (empty($s[''w'']) ? 110 : $s[''w''] / 2 - 2);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_SIGNATURE_YFORIMGSTART', 'string', NULL, 'core', 'Overrides the Y coordinate where the online signature image starts on a fichinter PDF, used only when FICHINTER_SIGNATURE_ON_ALL_PAGES is set.', 'Read at core/ajax/onlineSign.php:566; if truthy it replaces the computed default of $s[''h''] - 62 (or 250 if page height unknown).', 'Setting it changes the vertical placement of the signature image; leaving it unset keeps the automatic default computed from page height.', 'Numeric Y coordinate in PDF units; falls back to computed default if empty.', 1, 0, NULL, 1, '9281f5e7ca00e9fae022909ea525ade82899dc3f276733c4f49c20361d9c47c4', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:565: if (getDolGlobalString(\"FICHINTER_SIGNATURE_YFORIMGSTART\")) {", "core/ajax/onlineSign.php:566: $param[''yforimgstart''] = getDolGlobalString(\"FICHINTER_SIGNATURE_YFORIMGSTART\");", "core/ajax/onlineSign.php:568: $param[''yforimgstart''] = (empty($s[''h'']) ? 250 : $s[''h''] - 62);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_USE_PLANNED_AND_DONE_DATES', 'bool', NULL, 'fichinter', 'Adds display of planned start/end dates (dateo) on the intervention (fichinter) card view.', 'Checked in fichinter/card.php:1452: when set, the card prints a ''Dateo'' (start date) row (and further planned/done date rows) in the tableforfield block.', 'Enabling it adds extra date fields to the intervention card display for tracking planned vs done dates.', 'Boolean: truthy shows the planned/done date rows; falsy (default) hides them.', 0, 0, NULL, 1, '64bb2cef3c832a0f1161046c4398345e142d7e5f2bed09108950dfe38bc85cc5', 'v2', '2026-07-24T07:05:23+00:00', '["fichinter/card.php:1452|if (getDolGlobalString(''FICHINTER_USE_PLANNED_AND_DONE_DATES'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_USE_SERVICE_DURATION', 'bool', NULL, 'admin', 'Makes the intervention line duration default to the linked service product''s predefined duration.', 'Set via dolibarr_set_const in admin/fichinter.php:194 (''yesno'' type) and checked in fichinter/card.php:450 alongside a check on $prod->duration_value.', 'Enabling it causes the intervention line duration to be pre-filled from the service product''s duration_value when adding a service product.', 'yesno (0 or 1)', 0, 0, 'admin/fichinter.php|admin/fichinter.php', 1, '9e0dd146f8a9b792a63bae3b88ecebffb56a9e2b9e9157854d6e0f3df0d9521b', 'v2', '2026-07-24T06:41:12+00:00', '["admin/fichinter.php:194|write|$res = dolibarr_set_const($db, \"FICHINTER_USE_SERVICE_DURATION\", $setFichInterUseServiceDuration, ''yesno'', 0, '''', $conf->entity);", "fichinter/card.php:450|check|if ($prod->duration_value && getDolGlobalString(''FICHINTER_USE_SERVICE_DURATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FICHINTER_WITHOUT_DURATION', 'string', NULL, 'fichinter', 'Disables the duration field for intervention lines, so interventions are recorded without a duration value.', 'Set via dolibarr_set_const in admin/fichinter.php:206 (''yesno'' type) and checked in fichinter/card.php (614, 618, 627, 1682, 1759, 1852) to skip duration validation/display and force duration to 0.', 'Enabling it forces duration to 0 (fichinter/card.php:627) and skips the duration validation checks at lines 614 and 618, and changes how duration is displayed in the line list.', 'yesno (0 or 1)', 0, 0, 'admin/fichinter.php|admin/fichinter.php', 1, '43f3b313c0fb638bc7a6a0e0771761ba8f45761786f655007556b454bbed1c87', 'v2', '2026-07-24T06:41:12+00:00', '["admin/fichinter.php:206|write|$res = dolibarr_set_const($db, \"FICHINTER_WITHOUT_DURATION\", $setFichInterWithoutDuration, ''yesno'', 0, '''', $conf->entity);", "fichinter/card.php:627|read|$duration = !getDolGlobalString(''FICHINTER_WITHOUT_DURATION'') ? convertTime2Seconds(GETPOSTINT(''durationhour''), GETPOSTINT(''durationmin'')) : 0;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FOURN_PRODUCT_AVAILABILITY', 'string', NULL, 'product', 'Enables the availability delay field on supplier product price records.', 'When non-zero, an availability column is shown in product/price_suppliers.php:972 and the fk_availability field on supplier product records is active. The class comment at fourn/class/fournisseur.product.class.php:178 describes it as an ID for availability delay, visible only when this option is on.', 'Enabling this adds the availability delay field to supplier pricing views; disabling hides it.', '0 = availability field hidden; non-zero = availability field visible and used', 1, 0, NULL, 1, '83bee19ff08635f467cad8c2c78b0963aa10688f609437cffac6151f262650af', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/class/fournisseur.product.class.php:178  * @var int ID availability delay - visible/used if option FOURN_PRODUCT_AVAILABILITY is on (duplicate information compared to delivery delay)", "product/price_suppliers.php:972|read|''pfp.fk_availability'' => array(''label'' => $langs->trans(\"Availability\"), ''enabled'' => (string) getDolGlobalInt(''FOURN_PRODUCT_AVAILABILITY''), ''checked'' => ''0'', ''position'' => 4),", "product/price_suppliers.php:585|check|if (getDolGlobalInt(''FOURN_PRODUCT_AVAILABILITY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FROM_MAIL_DONT_USE_INPUT_FILE_MULTIPLE', 'bool', NULL, 'core', 'Disables the HTML5 ''multiple'' attribute on the file-attachment input of email composition forms, restricting attachment to one file per input.', 'Checked in core/class/html.formmail.class.php:1001: if (!getDolGlobalString(''FROM_MAIL_DONT_USE_INPUT_FILE_MULTIPLE'')) renders ''<input type="file" ... name="addedfile[]" ... multiple />''; else renders a single-file input without ''multiple'' and without the array name.', 'When set/true, the ''Add attachment'' file input on email forms no longer accepts multiple files at once (loses the multiple attribute and the addedfile[] array name), limiting users to attaching one extra file per input.', 'Boolean-like: truthy disables multi-file selection on the attachment input.', 1, 0, NULL, 1, 'b30d3e0689e700972e62fa8000763b6126a3ca46db102de81f5e94dcf130aef5', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:1001: if (!getDolGlobalString(''FROM_MAIL_DONT_USE_INPUT_FILE_MULTIPLE'')) {", "core/class/html.formmail.class.php:1002-1005: renders name=\"addedfile[]\" ... multiple vs single name=\"addedfile\" without multiple"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_CONNECT_TIMEOUT', 'string', NULL, 'core', 'Overrides the default FTP connection timeout of 40 seconds.', 'Read at core/lib/ftp.lib.php:55; when unset the fallback value 40 is used. The expression is ''$connecttimeout = (!getDolGlobalString(...) ? 40 : $conf->global->FTP_CONNECT_TIMEOUT)''. No comment is present in the payload.', 'Setting a shorter timeout makes FTP connections fail faster on unreachable servers; a longer value accommodates slow networks.', 'Integer (seconds); default is 40 when unset.', 1, 0, NULL, 1, '8d77f7b4bb53cc6e3451c0ee9b9897c10e18babc8c68c585cb4c51ba0c23b753', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/ftp.lib.php:55|read|$connecttimeout = (!getDolGlobalString(''FTP_CONNECT_TIMEOUT'') ? 40 : $conf->global->FTP_CONNECT_TIMEOUT);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_CONNECT_WITH_SFTP', 'string', NULL, 'core', 'Selects SFTP as the connection protocol for the built-in FTP client module instead of plain FTP.', 'Checked via getDolGlobalString(''FTP_CONNECT_WITH_SFTP'') in ftp/index.php:469 and repeatedly in core/lib/ftp.lib.php (70, 150, 167, 177, 195, 203, 221) to branch connection logic. No admin UI write path shown in this payload.', 'Enabling it switches the FTP module''s connection/transfer logic in core/lib/ftp.lib.php to use SFTP instead of standard FTP.', NULL, 0, 0, NULL, 1, 'fb8fcbb1f74b6bc46a263f2a7ae0afe342370689482a7e4e90f8e41b0137fbce', 'v2', '2026-07-24T06:41:12+00:00', '["ftp/index.php:469|check|if (getDolGlobalString(''FTP_CONNECT_WITH_SFTP'') && !empty($conn_id)) {", "core/lib/ftp.lib.php:70|check|if (getDolGlobalString(''FTP_CONNECT_WITH_SFTP'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_CONNECT_WITH_SSL', 'string', NULL, 'ftp', 'Selects FTPS (FTP over SSL, ftp_ssl_connect) instead of plain FTP when the FTP module connects to a server.', 'Declared as a real admin constant in core/modules/modFTP.class.php:78 (type ''chaine'', default ''0'', label ''Use FTPS for FTP module''), used in core/lib/ftp.lib.php:61 to choose ftp_ssl_connect() over ftp_connect() (unless FTP_CONNECT_WITH_SFTP is set, which takes priority), and displayed as Yes/No on ftp/index.php:401.', 'Enabling it makes the FTP module connect using FTPS (SSL) on the configured port instead of plain unencrypted FTP; port 21 is used for both plain FTP and FTPS per the admin page hint, while FTP_CONNECT_WITH_SFTP (port 22, SSH) takes precedence if also set.', '''1'' = connect via FTPS (ftp_ssl_connect); ''0''/unset (default) = plain FTP (ftp_connect), per modFTP.class.php declared default ''0''.', 0, 0, NULL, 1, 'e8e0a6d9bd4d2630cc51cc2f6891b3f1c9a7cba1c9dbcbab18f4ae110d687a62', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modFTP.class.php:78: [''FTP_CONNECT_WITH_SSL'', ''chaine'', ''0'', ''Use FTPS for FTP module'', 1, ''current'', 1],", "core/lib/ftp.lib.php:61|read|} elseif (getDolGlobalString(''FTP_CONNECT_WITH_SSL'')) {", "ftp/admin/ftpclient.php:208: ''21 for pure non encrypted FTP or if option FTP_CONNECT_WITH_SSL ... is on (FTPS)<br>22 if option FTP_CONNECT_WITH_SFTP ... is on (SFTP)''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_NAME_', 'string', NULL, 'ftp', 'Stores the display name or label for an indexed FTP server connection profile in the FTP client module.', 'Written and deleted in ftp/admin/ftpclient.php:115 and :147. The constant name is built as FTP_NAME_ concatenated with an entry index.', 'Changing this constant updates the human-readable label shown for the corresponding FTP connection entry.', 'String label/name.', 0, 0, 'ftp/admin/ftpclient.php|ftp/admin/ftpclient.php', 1, 'e0da9f4b158b95a5d8d47bb46ed76bfdf450c8fe64193ec08c853944863afa23', 'v2', '2026-04-21T13:50:40+00:00', '["$result5 = dolibarr_set_const($db, \"FTP_NAME_\".$entry, GETPOST($ftp_name, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$result5 = dolibarr_del_const($db, \"FTP_NAME_\".$entry, $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_PASSIVE_', 'string', NULL, 'ftp', 'Controls whether passive mode is used for an indexed FTP server connection profile in the FTP client module.', 'Written and deleted in ftp/admin/ftpclient.php:118 and :150. The constant name is built as FTP_PASSIVE_ concatenated with an entry index.', 'Enabling passive mode is typically required when the FTP client is behind a firewall; disabling it uses active mode.', 'Non-empty/truthy = passive mode; empty/unset = active mode.', 0, 0, 'ftp/admin/ftpclient.php|ftp/admin/ftpclient.php', 1, 'f0adf4aaeea521d97ea2ea640aba7a7ff074407c8c29578248a612a3e8d95025', 'v2', '2026-04-21T13:50:40+00:00', '["$result6 = dolibarr_set_const($db, \"FTP_PASSIVE_\".$entry, GETPOST($ftp_passive, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$result6 = dolibarr_del_const($db, \"FTP_PASSIVE_\".$entry, $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_PASSWORD_', 'string', NULL, 'ftp', 'Stores the login password for an indexed FTP server connection profile in the FTP client module.', 'Written and deleted in ftp/admin/ftpclient.php:112 and :144. The constant name is built as FTP_PASSWORD_ concatenated with an entry index.', 'Changing this constant changes the password used to authenticate to the corresponding FTP server.', 'String password.', 0, 0, 'ftp/admin/ftpclient.php|ftp/admin/ftpclient.php', 1, '6692af2ac1aa903b17eaa69e5aa28c4da33bb5c105eee121e96f9a5603a21828', 'v2', '2026-04-21T13:50:40+00:00', '["$result4 = dolibarr_set_const($db, \"FTP_PASSWORD_\".$entry, GETPOST($ftp_password, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$result4 = dolibarr_del_const($db, \"FTP_PASSWORD_\".$entry, $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_PORT_', 'string', NULL, 'ftp', 'Stores the TCP port number for an indexed FTP server connection profile in the FTP client module.', 'Written and deleted in ftp/admin/ftpclient.php:104 and :136 via dolibarr_set_const and dolibarr_del_const. The constant name is built dynamically as FTP_PORT_ concatenated with an entry index.', 'Changing this constant alters the port used when connecting to the corresponding FTP server entry.', 'Numeric string representing a TCP port (e.g. ''21'').', 0, 0, 'ftp/admin/ftpclient.php|ftp/admin/ftpclient.php', 1, 'e2e4e358222576adad79575d4551068b3d74bf77b74e74230f9244892b1be0a2', 'v2', '2026-04-21T13:50:40+00:00', '["$result1 = dolibarr_set_const($db, \"FTP_PORT_\".$entry, GETPOST($ftp_port, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$result1 = dolibarr_del_const($db, \"FTP_PORT_\".$entry, $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_SERVER_', 'string', NULL, 'ftp', 'Stores the hostname or IP address for an indexed FTP server connection profile in the FTP client module.', 'Written and deleted in ftp/admin/ftpclient.php:106 and :138. The constant name is built as FTP_SERVER_ concatenated with an entry index.', 'Changing this constant redirects FTP connections for the corresponding entry to a different server.', 'String hostname or IP address.', 0, 0, 'ftp/admin/ftpclient.php|ftp/admin/ftpclient.php', 1, 'bf69f298109f1a1d48bf964904654b8675cfef6014f76beecab19b31d69d1562', 'v2', '2026-04-21T13:50:40+00:00', '["$result2 = dolibarr_set_const($db, \"FTP_SERVER_\".$entry, GETPOST($ftp_server, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$result2 = dolibarr_del_const($db, \"FTP_SERVER_\".$entry, $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_SUGGEST_PASSIVE_BYDEFAULT', 'string', NULL, 'ftp', 'Controls whether the FTP client admin form pre-checks ''passive mode'' by default when adding/editing an FTP connection.', 'In ftp/admin/ftpclient.php:227, $defaultpassive is set to 1 if this bool is truthy, else 0; this value is used to pre-select the passive-mode checkbox shown in the FTP client admin setup form.', 'Enabling it makes the admin form default to suggesting passive-mode FTP connections; unset/false defaults the suggestion to non-passive (active) mode.', 'true/1 = default the passive-mode checkbox to checked; false/unset (default) = default to unchecked.', 0, 0, 'ftp/admin/ftpclient.php', 1, 'ec74a87bff5695a153e5fb1598af0b498cdd96f53d0f3af3ddacfcfacb55451d', 'v2', '2026-07-24T07:05:23+00:00', '["ftp/admin/ftpclient.php:227|read|$defaultpassive = !getDolGlobalString(''FTP_SUGGEST_PASSIVE_BYDEFAULT'') ? 0 : 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('FTP_USER_', 'string', NULL, 'ftp', 'Stores the login username for an indexed FTP server connection profile in the FTP client module.', 'Written and deleted in ftp/admin/ftpclient.php:109 and :141. The constant name is built as FTP_USER_ concatenated with an entry index.', 'Changing this constant changes the username used to authenticate to the corresponding FTP server.', 'String username.', 0, 0, 'ftp/admin/ftpclient.php|ftp/admin/ftpclient.php', 1, '8f63b3460189af7002c9beb2710aa1d76075a7947b284bfbb4fddd7b21453513', 'v2', '2026-04-21T13:50:40+00:00', '["$result3 = dolibarr_set_const($db, \"FTP_USER_\".$entry, GETPOST($ftp_user, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$result3 = dolibarr_del_const($db, \"FTP_USER_\".$entry, $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GENBARCODE_BARCODETYPE_THIRDPARTY', 'string', NULL, 'core', 'Stores the default barcode type (format) used when generating barcodes for third parties.', 'Written by admin/barcode.php:99 and rendered as a selector at admin/barcode.php:548. Read in core/modules/barcode/mod_barcode_thirdparty_standard.php:216 for automatic numbering and in barcode/printsheet.php:154-155 and core/class/commonobject.class.php:2057 as a fallback type when none is defined on the record.', 'Setting this value changes the barcode format applied to third-party records when no per-record override is present; clearing it disables the fallback.', 'Stores a barcode type ID (integer as string) referencing the selected format; empty = no default.', 0, 0, 'admin/barcode.php|admin/barcode.php', 1, '5cb0db41ba71d0e0f4df161fe6abff4f086efb02d122243b320c326763f8abdf', 'v2', '2026-04-21T11:16:15+00:00', '["admin/barcode.php:99|write|$res = dolibarr_set_const($db, \"GENBARCODE_BARCODETYPE_THIRDPARTY\", $coder_id, ''chaine'', 0, '''', $conf->entity);", "core/modules/barcode/mod_barcode_thirdparty_standard.php:216|read|$type = getDolGlobalString(''GENBARCODE_BARCODETYPE_THIRDPARTY'');", "barcode/printsheet.php:154|check|if (empty($fk_barcode_type) && getDolGlobalString(''GENBARCODE_BARCODETYPE_THIRDPARTY'')) {", "core/class/commonobject.class.php:2057|read|$idtype = getDolGlobalString(''GENBARCODE_BARCODETYPE_THIRDPARTY'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GENBARCODE_LOCATION', 'string', NULL, 'admin', 'Stores the filesystem path to the external genbarcode binary used for barcode image generation.', 'Configured via admin/barcode.php (UI write at line 95). The path is checked for existence at admin/barcode.php:523; if set and the file does not exist, an ''ErrorFileNotFound'' error is displayed. The value is read in core/lib/barcode.lib.php:66 to set the barcode generator location.', 'If the path is set but points to a non-existent file, barcode generation will fail and an error is shown. If left empty, the system uses a default or compiled-in barcode generator.', 'Absolute filesystem path string to the genbarcode executable; empty string to use the default.', 0, 0, 'admin/barcode.php|admin/barcode.php|admin/barcode.php|admin/barcode.php', 1, '6cde9b1dbca84eeb3b281a5cace6f3213415dd17e372abc5076623892efa01ea', 'v2', '2026-04-21T13:50:40+00:00', '["admin/barcode.php:523|check|if (getDolGlobalString(''GENBARCODE_LOCATION'') && !@file_exists(getDolGlobalString(''GENBARCODE_LOCATION''))) {", "admin/barcode.php:525|read|print ''<br><span class=\"error\">''.$langs->trans(\"ErrorFileNotFound\", getDolGlobalString(''GENBARCODE_LOCATION'')).''</span>'';", "core/lib/barcode.lib.php:65|check|if (getDolGlobalString(''GENBARCODE_LOCATION'')) {", "core/lib/barcode.lib.php:66|read|$genbarcode_loc = getDolGlobalString(''GENBARCODE_LOCATION'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GEOIPMAXMIND_COUNTRY_DATAFILE', 'string', NULL, 'admin', 'Stores the filesystem path to the MaxMind GeoIP country database file.', 'Written via admin/geoipmaxmind.php:78 and read in admin/geoipmaxmind.php:138, 180, 185, and core/lib/functions.lib.php:5290, 5327 to locate the data file for IP-to-country resolution.', 'Changing this path redirects GeoIP lookups to a different database file. An invalid path will cause GeoIP resolution to fail.', 'An absolute filesystem path string pointing to the MaxMind country data file; empty = no custom path configured', 0, 0, 'admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php', 1, '19d43e3d7e1d514fcf5b9268ac728e48dd364bfeb5d0d45d4ebdfd031003fcad', 'v2', '2026-04-21T13:29:58+00:00', '["admin/geoipmaxmind.php:78|write|$res2 = dolibarr_set_const($db, \"GEOIPMAXMIND_COUNTRY_DATAFILE\", $gimcdf, ''chaine'', 0, '''', $conf->entity);", "admin/geoipmaxmind.php:138|read|$datafile = getDolGlobalString(''GEOIPMAXMIND_COUNTRY_DATAFILE'');", "core/lib/functions.lib.php:5327|read|$datafile = getDolGlobalString(''GEOIPMAXMIND_COUNTRY_DATAFILE'');", "core/lib/functions.lib.php:5290|read|$datafile = getDolGlobalString(''GEOIPMAXMIND_COUNTRY_DATAFILE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GEOIPMAXMIND_COUNTRY_DATAFILE_EMBEDDED', 'string', NULL, 'admin', 'Stores the filename of the embedded MaxMind GeoIP country database file (relative to the Dolibarr data directory).', 'Read in admin/geoipmaxmind.php:141, 264 and core/lib/functions.lib.php:5293. The value is appended to the data directory path ($diroffile) to locate the embedded database. Checked at geoipmaxmind.php:263 before use.', 'Setting this to a valid filename enables the embedded GeoIP data file path. Clearing it disables the embedded file lookup.', 'A relative filename string appended to the data directory to form the full embedded data file path; empty = embedded file not used', 0, 0, 'admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php', 1, '9ccc7a1a1c0af779ed5eb003742dfaf28dea9cd4ea44294df846b47ffe8c3545', 'v2', '2026-04-21T13:29:58+00:00', '["admin/geoipmaxmind.php:263|check|if (getDolGlobalString(\"GEOIPMAXMIND_COUNTRY_DATAFILE_EMBEDDED\")) {", "admin/geoipmaxmind.php:141|read|$datafile = $diroffile . ''/'' . getDolGlobalString(''GEOIPMAXMIND_COUNTRY_DATAFILE_EMBEDDED'');", "core/lib/functions.lib.php:5293|read|$datafile = $diroffile . ''/'' . getDolGlobalString(''GEOIPMAXMIND_COUNTRY_DATAFILE_EMBEDDED'');", "admin/geoipmaxmind.php:264|read|$geoipfile = getDolGlobalString(\"GEOIPMAXMIND_COUNTRY_DATAFILE_EMBEDDED\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GEOIP_VERSION', 'string', NULL, 'admin', 'Specifies the GeoIP library version or backend to use for IP-to-country lookups.', 'Extensively checked in admin/geoipmaxmind.php across 19 occurrences. The value ''php'' selects the PHP-based GeoIP backend; when unset, the system defaults to version ''2'' (written at admin/geoipmaxmind.php:53 as $conf->global->GEOIP_VERSION = ''2''). The admin UI exposes this setting.', 'Changing this value switches the GeoIP resolution backend. Setting it to ''php'' activates the PHP legacy path; other values (e.g. ''2'') select alternative backends.', '''php'' = PHP-based GeoIP library; ''2'' = GeoIP version 2 backend (default when not set)', 0, 0, 'admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php', 1, '3757fbecf7c5e10cc9b28f903c126e099204f90522bf3f2f598126deca8d96e1', 'v2', '2026-04-21T13:29:58+00:00', '["admin/geoipmaxmind.php:69|check|if (getDolGlobalString(''GEOIP_VERSION'') == ''php'') {", "admin/geoipmaxmind.php:52|check|if (!getDolGlobalString(\"GEOIP_VERSION\")) {", "admin/geoipmaxmind.php:53|write|$conf->global->GEOIP_VERSION = ''2'';", "admin/geoipmaxmind.php:137|check|if (getDolGlobalString(''GEOIP_VERSION'') == ''php'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GOOGLE_ENABLE_GMAPS', 'bool', NULL, 'core', 'Enables display of a Google Maps link/widget for a thirdparty''s (company''s) address.', 'In core/lib/functions.lib.php:5346, inside the address-printing function, if the element is ''thirdparty''/''societe'', the Google module is enabled (isModEnabled(''google'')), and this constant is set, a Google Maps view is shown for the address ($showgmap = 1).', 'Enabling it (with the Google module active) adds a Google Maps view/link below a thirdparty''s printed address.', 'Boolean-like: any truthy value enables the Google Maps link, requires the ''google'' module to also be enabled.', 1, 0, NULL, 1, 'ffd7fa54e4a2d18c0b64b1be65ba7c3487c9fa7dd17e1f78d0440f96d0c6567b', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5346|check|if (($element == ''thirdparty'' || $element == ''societe'') && isModEnabled(''google'') && getDolGlobalString(''GOOGLE_ENABLE_GMAPS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GOOGLE_ENABLE_GMAPS_CONTACTS', 'bool', NULL, 'core', 'Enables display of a Google Maps link/widget for a contact''s address.', 'In core/lib/functions.lib.php:5349, same pattern as GOOGLE_ENABLE_GMAPS but restricted to elements of type ''contact''; requires the ''google'' module enabled and this constant set to show the map.', 'Enabling it (with the Google module active) adds a Google Maps view/link below a contact''s printed address.', 'Boolean-like: any truthy value enables the Google Maps link for contacts.', 1, 0, NULL, 1, 'a22a263193001f0b9f28c421896771cc57d83a263c6b8be4fad72ed705f2b5a2', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5349|check|if ($element == ''contact'' && isModEnabled(''google'') && getDolGlobalString(''GOOGLE_ENABLE_GMAPS_CONTACTS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GOOGLE_ENABLE_GMAPS_MEMBERS', 'bool', NULL, 'core', 'Enables display of a Google Maps link/widget for a foundation member''s address.', 'In core/lib/functions.lib.php:5352, same pattern restricted to elements of type ''member''; requires the ''google'' module enabled and this constant set.', 'Enabling it (with the Google module active) adds a Google Maps view/link below a member''s printed address.', 'Boolean-like: any truthy value enables the Google Maps link for members.', 1, 0, NULL, 1, '79f94c25d19299f506b8c113682a84d73c68bda87ee4e84d85f703d7bca23ed2', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5352|check|if ($element == ''member'' && isModEnabled(''google'') && getDolGlobalString(''GOOGLE_ENABLE_GMAPS_MEMBERS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GOOGLE_ENABLE_GMAPS_USERS', 'bool', NULL, 'core', 'Enables display of a Google Maps link/widget for a Dolibarr user''s address.', 'In core/lib/functions.lib.php:5355, same pattern restricted to elements of type ''user''; requires the ''google'' module enabled and this constant set.', 'Enabling it (with the Google module active) adds a Google Maps view/link below a user''s printed address.', 'Boolean-like: any truthy value enables the Google Maps link for users.', 1, 0, NULL, 1, '104da1631f1aa41e4f1d0c2edca93af569d1a1eb61c80eacbc73177ccdb16347', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5355|check|if ($element == ''user'' && isModEnabled(''google'') && getDolGlobalString(''GOOGLE_ENABLE_GMAPS_USERS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GOOGLE_SHOW_COUNTRY_GRAPH', 'bool', NULL, 'adherents', 'Enables displaying a graphical (Google Charts-style) map/graph of members by country on the members statistics page.', 'In adherents/stats/geo.php:236 and :253, when set and mode is ''memberbycountry'', extra descriptive text (MembersByCountryDesc2) is shown and a graphics block is rendered using theme colors.', 'Enabling it adds a visual country-distribution graph (plus extra description text) to the member statistics ''by country'' view; leaving it unset shows only the textual/tabular breakdown.', 'boolean: 1/true shows the country graph and its description on the memberbycountry stats view; unset/0 = graph not shown.', 1, 0, NULL, 1, '9f7b5a24d14f4a0ac702c85f0d8286d937ce8c25f0431b99c98a91d0d42ddc7a', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/stats/geo.php:236: if (getDolGlobalString(\"GOOGLE_SHOW_COUNTRY_GRAPH\")) {", "adherents/stats/geo.php:253: if (getDolGlobalString(\"GOOGLE_SHOW_COUNTRY_GRAPH\") && $mode == ''memberbycountry'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('GRAPH_USE_FISCAL_YEAR', 'bool', NULL, 'core', 'Switches dashboard graph widgets from the calendar year to the fiscal year as the time axis.', 'Checked with negation (!getDolGlobalString(...)) in six box files: box_graph_orders_permonth.php:73, box_graph_invoices_peryear.php:71, box_graph_invoices_supplier_permonth.php:72, box_graph_orders_supplier_permonth.php:72, box_graph_propales_permonth.php:73, and box_graph_invoices_permonth.php:74.', 'Enabling this causes all per-month and per-year graph widgets to align their date range with the configured fiscal year rather than the January–December calendar year.', 'Empty/not set = calendar year used; any truthy string = fiscal year used', 1, 0, NULL, 1, 'e98b6b4c16c12fbda96d86104d72de61bfddb29d16a5ef8dfa99f425b800b6bf', 'v2', '2026-04-21T11:16:15+00:00', '["core/boxes/box_graph_orders_permonth.php:73|check|if (!getDolGlobalString(''GRAPH_USE_FISCAL_YEAR'')) {", "core/boxes/box_graph_invoices_peryear.php:71|check|if (!getDolGlobalString(''GRAPH_USE_FISCAL_YEAR'')) {", "core/boxes/box_graph_invoices_permonth.php:74|check|if (!getDolGlobalString(''GRAPH_USE_FISCAL_YEAR'')) {", "core/boxes/box_graph_propales_permonth.php:73|check|if (!getDolGlobalString(''GRAPH_USE_FISCAL_YEAR'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HIDE_LABEL_VARIANT_PDF', 'bool', NULL, 'core', 'Hides the product label on PDF lines for product variants, showing only the free-text description.', 'Checked in core/lib/pdf.lib.php:2108, only reached when MAIN_DOCUMENTS_DESCRIPTION_FIRST is not set; when set and $prodser->isVariant() is true, $libelleproduitservice is replaced by $desc alone instead of label+desc concatenation.', 'For product variant lines specifically, removes the variant''s label from the printed line and shows only its description.', 'Boolean-like (set/unset); applies only when the product/service line is a variant (isVariant())', 1, 0, NULL, 1, '57013fef8e59142802f92b1c84877fa0afb51687859a9f694e748add4b758f0a', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:2108|check|if (getDolGlobalString(''HIDE_LABEL_VARIANT_PDF'') && $prodser->isVariant()) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_ADDON', 'string', NULL, 'holiday', 'Selects the active numbering module (addon) used to generate holiday request reference numbers.', 'Set via admin/holiday.php (dolibarr_set_const at line 149) and defaults to ''mod_holiday_madonna'' when not set (lines 59, 231). Read in holiday/class/holiday.class.php at line 238 to instantiate the numbering class. A comment at line 220 documents that the classname is defined into HOLIDAY_ADDON.', 'Changing this value switches the numbering algorithm for holiday requests; setting an invalid class name will break reference generation.', 'String classname of the addon module, e.g. ''mod_holiday_madonna''.', 0, 0, 'admin/holiday.php|admin/holiday.php|admin/holiday.php|admin/holiday.php', 1, 'e9d3f42e2b0f6a85ecf41776fb0dd788ee601f937b41a2be6d81e4ed5dad1e9e', 'v2', '2026-04-21T13:50:40+00:00', '["holiday/class/holiday.class.php:220  *  defined into HOLIDAY_ADDON", "admin/holiday.php:149|write|dolibarr_set_const($db, \"HOLIDAY_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "holiday/class/holiday.class.php:238|read|$classname = getDolGlobalString(''HOLIDAY_ADDON'');", "admin/holiday.php:59|write|$conf->global->HOLIDAY_ADDON = ''mod_holiday_madonna'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_ADDON_PDF', 'string', NULL, 'admin', 'Selects the active PDF document template used for holiday request documents.', 'Set and deleted via admin/holiday.php (dolibarr_set_const at line 134, dolibarr_del_const at line 129). The selected value is compared against available PDF module names (lines 128, 398) to highlight the active template in the admin UI.', 'Changing this value switches which PDF template is used to generate holiday request documents.', 'String name of the PDF module; empty = no PDF module selected.', 0, 0, 'admin/holiday.php|admin/holiday.php|admin/holiday.php|admin/holiday.php|admin/holiday.php', 1, '11db3e617270d51d926e9db7e48a1f482801992590c61eaaf34c2abc5304ed9b', 'v2', '2026-04-21T13:50:40+00:00', '["admin/holiday.php:134|write|if (dolibarr_set_const($db, \"HOLIDAY_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "admin/holiday.php:128|check|if (getDolGlobalString(''HOLIDAY_ADDON_PDF'') == \"$value\") {", "admin/holiday.php:398|check|if (getDolGlobalString(''HOLIDAY_ADDON_PDF'') == $name) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_ALLOW_ZERO_IN_DIC', 'bool', NULL, 'core', 'Allows the leave/holiday-type dictionary (c_holiday_types) to include entity id 0 (shared/global) entries in single-company (non-Multicompany) mode.', 'Checked in getEntity()-related code in core/lib/functions.lib.php:657 with inline warning comment ''this constant break the dictionary admin without Multicompany''; when set, ''c_holiday_types'' is added to the $addzero array of elements for which entity ''0,'' is prefixed to the entity filter.', 'Enabling it changes how the c_holiday_types dictionary is entity-filtered, adding entity 0 to the scan; the code comment explicitly warns this breaks the dictionary admin screen when Multicompany is not active, so enabling it without Multicompany is expected to cause admin UI problems.', 'Boolean: truthy value adds ''c_holiday_types'' to the list of dictionaries queried with entity 0 included; comment warns this breaks dictionary admin without Multicompany module.', 1, 0, NULL, 1, '021778b112f7335fe3cac2fc65a10a67aa4a637d12f3cdf2b3e9d2ec1e77cae2', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:657|check|if (getDolGlobalString(''HOLIDAY_ALLOW_ZERO_IN_DIC'')) { // this constant break the dictionary admin without Multicompany"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_CAN_APPROVE_ONLY_THE_SUBORDINATES', 'string', NULL, 'holiday', 'Restricts holiday approval so that an approver can only approve requests for their direct subordinates.', 'Checked in three holiday files (holiday/document.php:103, holiday/info.php:76, holiday/card.php:105). Each check also requires permissiontoapprove and that the current user is the designated validator; setting this constant removes that self-approval path. Marked with a TODO comment in the source.', 'When set, an approver who is the designated validator cannot approve their own or non-subordinate requests via the standard path. When unset, any user with approve permission who is the validator may approve.', 'Truthy = restrict approval to subordinates only; falsy or unset = no subordinate restriction.', 1, 0, NULL, 1, '856611623217720f1f24738659ea5f46c7b36293bae88e6c273e6f16ea057c94', 'v2', '2026-04-21T13:50:40+00:00', '["holiday/document.php:103|check|if ($permissiontoapprove && $object->fk_validator == $user->id && !getDolGlobalString(''HOLIDAY_CAN_APPROVE_ONLY_THE_SUBORDINATES'')) {", "holiday/info.php:76|check|if ($permissiontoapprove && $object->fk_validator == $user->id && !getDolGlobalString(''HOLIDAY_CAN_APPROVE_ONLY_THE_SUBORDINATES'')) {", "holiday/card.php:105|check|if ($permissiontoapprove && $object->fk_validator == $user->id && !getDolGlobalString(''HOLIDAY_CAN_APPROVE_ONLY_THE_SUBORDINATES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_DECREASE_AT_END_OF_MONTH', 'string', NULL, 'holiday', 'Controls the decrease amount applied to holiday balances at the end of each month.', 'Read as an integer in holiday/class/holiday.class.php:1686 and holiday/card.php (lines 644, 877) to compute the monthly balance decrease. Checked in admin/holiday.php:564 to conditionally show related UI. Set via admin/holiday.php.', 'Changing this value alters how many holiday days are deducted from balances at month-end processing.', 'Integer representing the decrease amount; 0 or unset = no end-of-month decrease.', 0, 0, 'admin/holiday.php', 1, 'e28c5627b90391161375e76642683bbf1371aefe6de0b777b6a4eb91c9c9e881', 'v2', '2026-04-21T13:50:40+00:00', '["admin/holiday.php:564|check|if (getDolGlobalString(''HOLIDAY_DECREASE_AT_END_OF_MONTH'')) {", "holiday/class/holiday.class.php:1686|read|$decrease = getDolGlobalInt(''HOLIDAY_DECREASE_AT_END_OF_MONTH'');", "holiday/card.php:644|read|$decrease = getDolGlobalInt(''HOLIDAY_DECREASE_AT_END_OF_MONTH'');", "holiday/card.php:877|read|$decrease = getDolGlobalInt(''HOLIDAY_DECREASE_AT_END_OF_MONTH'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_DEFAULT_VALIDATOR', 'string', NULL, 'holiday', 'Sets the default approver user ID for holiday requests.', 'Checked and read in holiday/card_group.php:617-618 and holiday/card.php:1243-1244. The comment in the source explicitly states ''// Can force default approver''. No admin UI write is present.', 'Setting this constant forces a specific user as the pre-selected approver when creating holiday requests, for both individual and group cards. Unsetting it leaves the approver selector empty by default.', 'A user ID (integer as string); empty or unset = no default approver forced.', 1, 0, NULL, 1, '7b45f7c8d9b64762cb08aa9e7d5dd476e1a869e130ce3e5ca9ba2ec1f5d05d97', 'v2', '2026-04-21T13:50:40+00:00', '["holiday/card_group.php:617|check|if (getDolGlobalString(''HOLIDAY_DEFAULT_VALIDATOR'')) {", "holiday/card_group.php:618|read|$defaultselectuser = getDolGlobalString(''HOLIDAY_DEFAULT_VALIDATOR''); // Can force default approver", "holiday/card.php:1243|check|if (getDolGlobalString(''HOLIDAY_DEFAULT_VALIDATOR'')) {", "holiday/card.php:1244|read|$defaultselectuser = getDolGlobalString(''HOLIDAY_DEFAULT_VALIDATOR''); // Can force default approver"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_DISALLOW_NEGATIVE_BALANCE', 'bool', NULL, 'holiday', 'Blocks the submission or approval of holiday requests that would result in a negative leave balance.', 'Checked in holiday/class/holiday.class.php at lines 782, 906, and 1035, all evaluating ($balance - $daysAsked) < 0 combined with this constant. No admin UI write is present.', 'When set, attempts to request or approve leave that would push the balance below zero are blocked at the class level. Leaving it unset permits negative balances.', 'Truthy = negative balance requests blocked; falsy or unset = negative balances permitted.', 1, 0, NULL, 1, '4abee3b1dd0354a9eff805a611fedb57cf60c2c27dfea8e9a97e9f555cf86bf0', 'v2', '2026-04-21T13:50:40+00:00', '["holiday/class/holiday.class.php:782|check|if (($balance - $daysAsked) < 0 && getDolGlobalString(''HOLIDAY_DISALLOW_NEGATIVE_BALANCE'')) {", "holiday/class/holiday.class.php:906|check|if (($balance - $daysAsked) < 0 && getDolGlobalString(''HOLIDAY_DISALLOW_NEGATIVE_BALANCE'')) {", "holiday/class/holiday.class.php:1035|check|if (($balance - $daysAsked) < 0 && getDolGlobalString(''HOLIDAY_DISALLOW_NEGATIVE_BALANCE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_DRAFT_WATERMARK', 'string', NULL, 'admin', 'Sets the watermark text printed on draft holiday request PDF documents.', 'Configured via admin/holiday.php: saved with dolibarr_set_const (line 155) and displayed in a text input (line 600). The value is used by the PDF generation code as the draft watermark string.', 'Changing this value changes the watermark text shown on draft holiday documents; clearing it removes the watermark.', 'Arbitrary string (watermark text); empty = no watermark.', 0, 0, 'admin/holiday.php|admin/holiday.php', 1, '6f9dc2e4e933359e897c035b8963112fc15e0c309852115372168417a3c274e4', 'v2', '2026-04-21T13:50:40+00:00', '["admin/holiday.php:155|write|$res2 = dolibarr_set_const($db, \"HOLIDAY_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "admin/holiday.php:600|read|print ''<input ... name=\"HOLIDAY_DRAFT_WATERMARK\" value=\"''.dol_escape_htmltag(getDolGlobalString(''HOLIDAY_DRAFT_WATERMARK'')).''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated holiday/leave-request documents.', 'Written from admin/holiday.php:152 via dolibarr_set_const() when the admin saves the holiday (leave requests) module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated holiday/leave documents; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/holiday.php', 1, '81135b95057c321bddaf348e7542eec5e84714bd4cdebea6bb5cd6d74a805cc9', 'v2', '2026-07-24T07:05:23+00:00', '["admin/holiday.php:152|write|$res1 = dolibarr_set_const($db, \"HOLIDAY_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_HIDE_APPROVER_ABOUT_NEGATIVE_BALANCE', 'bool', NULL, 'holiday', 'Hides the warning shown to the approver when a holiday request would bring the requester''s leave balance negative.', 'In holiday/card.php:540-541 and holiday/card_group.php:762, a comment says ''option to notify the validator if the balance is less than the request (only for leave types that actually use the balance counter)''; when unset, the negative-balance warning is added to the approval email.', 'Setting it to true suppresses the negative-balance notice in the approval notification email; leaving it unset keeps the warning for leave types using the balance counter.', 'boolean: 1/true hides the warning; unset/0 = warning shown when balance would go negative.', 0, 0, NULL, 1, '367acbc3b3e769fb0844cd52a61defdffa245082c52a859b17a23542eae5fa11', 'v2', '2026-07-24T07:05:23+00:00', '["holiday/card.php:539-540: // option to notify the validator if the balance is less than the request\\n// (only for leave types that actually use the balance counter)", "holiday/card.php:541: if (!getDolGlobalString(''HOLIDAY_HIDE_APPROVER_ABOUT_NEGATIVE_BALANCE'')) {", "holiday/card_group.php:762|check|if (!getDolGlobalString(''HOLIDAY_HIDE_APPROVER_ABOUT_NEGATIVE_BALANCE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_HIDE_APPROVER_ABOUT_TOO_LOW_DELAY', 'bool', NULL, 'holiday', 'Hides the warning shown to the approver when a holiday request is submitted with too short a notice delay.', 'In holiday/card.php:526-527 and holiday/card_group.php:749, a comment marks this as the ''option to warn the validator in case of too short delay''; when the constant is NOT set, the code adds a delay-warning line to the validation email based on HOLIDAY_DELAY_TO_APPROVE_FOR_TYPE_<type>.', 'Setting it to true suppresses the too-low-delay warning text in the approval notification email; leaving it unset keeps the warning.', 'boolean: 1/true hides the warning; unset/0 = warning shown when delay is too low.', 0, 0, NULL, 1, '4c44e3a28de8c8beae1d98a1574beb3b0f1e3be2ba22e496cc0cf922149a51e3', 'v2', '2026-07-24T07:05:23+00:00', '["holiday/card.php:526: // option to warn the validator in case of too short delay", "holiday/card.php:527: if (!getDolGlobalString(''HOLIDAY_HIDE_APPROVER_ABOUT_TOO_LOW_DELAY'')) {", "holiday/card_group.php:749|check|if (!getDolGlobalString(''HOLIDAY_HIDE_APPROVER_ABOUT_TOO_LOW_DELAY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_HIDE_BALANCE', 'bool', NULL, 'holiday', 'Hides the holiday (leave) balance display or replaces it with a translated label string.', 'Checked in hrm/index.php, holiday/list.php, and holiday/card.php. When empty, balance is shown. When set to a non-numeric string, that string is used as a translation key to display a custom label instead of the balance (hrm/index.php:198-199, holiday/card.php:1159-1161).', 'Setting this to a non-numeric string replaces the numeric balance with a translated label. Setting to a numeric value hides the balance display. Clearing it restores the standard balance view.', 'Empty/unset = balance shown; numeric string = balance hidden; non-numeric string = value used as translation key displayed instead of balance', 1, 0, NULL, 1, '60dda23d01713e0973dcf76e1b1ad3b5a58bc28433967178be3929480c405101', 'v2', '2026-04-21T13:29:58+00:00', '["hrm/index.php:173|check|if (!getDolGlobalString(''HOLIDAY_HIDE_BALANCE'')) {", "hrm/index.php:198|read|} elseif (!is_numeric(getDolGlobalString(''HOLIDAY_HIDE_BALANCE''))) {", "hrm/index.php:199|read|print $langs->trans(getDolGlobalString(''HOLIDAY_HIDE_BALANCE'')).''<br>'';", "holiday/card.php:1159|read|} elseif (!is_numeric(getDolGlobalString(''HOLIDAY_HIDE_BALANCE''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_HIDE_FOR_NON_SALARIES', 'bool', NULL, 'holiday', 'Hides holiday-related pages and features for users who are not classified as salaried employees.', 'Checked across five holiday module files (holiday/document.php:79, holiday/card_group.php:82, holiday/list.php:618, holiday/info.php:52, holiday/card.php:78), all gating display of holiday content on this flag. No admin UI write is present.', 'When set, non-salaried users will not see holiday documents, group cards, lists, info pages, or individual cards. Unsetting it makes those pages visible to all users with the relevant permissions.', 'Truthy = hide holiday UI for non-salaried users; falsy or unset = show to all.', 1, 0, NULL, 1, '37c6762cd12f676d358125cd16a28aff735be737fe1d3fb839141484f854ea99', 'v2', '2026-04-21T13:50:40+00:00', '["holiday/document.php:79|check|if (getDolGlobalString(''HOLIDAY_HIDE_FOR_NON_SALARIES'')) {", "holiday/card_group.php:82|check|if (getDolGlobalString(''HOLIDAY_HIDE_FOR_NON_SALARIES'')) {", "holiday/list.php:618|check|if (getDolGlobalString(''HOLIDAY_HIDE_FOR_NON_SALARIES'')) {", "holiday/card.php:78|check|if (getDolGlobalString(''HOLIDAY_HIDE_FOR_NON_SALARIES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HOLIDAY_IMMACULATE_MASK', 'string', NULL, 'core', 'Stores the numbering mask pattern used by the immaculate holiday reference numbering module.', 'Used in core/modules/holiday/mod_holiday_immaculate.php in two locations: line 87 populates a UI input field, and line 134 retrieves the mask to generate holiday references.', 'Changing the mask pattern alters how new holiday references are formatted by the immaculate module. Clearing it results in no mask being applied.', 'Any string = mask pattern for holiday reference generation; empty/unset = no mask pattern.', 1, 0, NULL, 1, 'b4cd82a4ca00f6b5c880342b6956220a76ea9363965cf31008de1d08417e549d', 'v2', '2026-04-21T13:50:40+00:00', '["mod_holiday_immaculate.php:87|value=''\".getDolGlobalString(''HOLIDAY_IMMACULATE_MASK'').\"''", "mod_holiday_immaculate.php:134|$mask = getDolGlobalString(''HOLIDAY_IMMACULATE_MASK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HRMTEST_EVALUATION_ADDON', 'string', NULL, 'hrm', 'Specifies the numbering add-on module class name for HRM evaluations, defaulting to ''mod_evaluation_standard''.', 'Read and checked in hrm/class/evaluation.class.php at lines 956, 957, 960, 963, and 964. When not set, the code forces $conf->global->HRMTEST_EVALUATION_ADDON = ''mod_evaluation_standard''; then loads the corresponding .php file.', 'Changing this to a different add-on class name switches the numbering module used for evaluation references; an invalid value will cause a file-load failure.', 'string class name, e.g. ''mod_evaluation_standard''; default set to ''mod_evaluation_standard'' when empty', 1, 0, NULL, 1, 'e48e368b979a2770844bf8f12158d114d5bf95f556d9113facbb4ad26152ac0c', 'v2', '2026-04-21T13:29:58+00:00', '["hrm/class/evaluation.class.php:956|check|if (!getDolGlobalString(''HRMTEST_EVALUATION_ADDON'')) {", "hrm/class/evaluation.class.php:957|write|$conf->global->HRMTEST_EVALUATION_ADDON = ''mod_evaluation_standard'';", "hrm/class/evaluation.class.php:963|read|$file = getDolGlobalString(''HRMTEST_EVALUATION_ADDON'') . \".php\";", "hrm/class/evaluation.class.php:964|read|$classname = getDolGlobalString(''HRMTEST_EVALUATION_ADDON'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HRM_DEFAULT_SKILL_DESCRIPTION', 'string', NULL, 'hrm', 'Default description text applied to auto-created skill entries (skilldets) when creating skills for a rank.', 'Read in hrm/class/skill.class.php:269 as the fallback for $defaultSkillDesc, defaulting to the translated ''NoDescription'' string if unset; configurable in the admin UI at admin/hrm.php:68 as a ''varchar'' constant field.', 'Setting it changes the description text stored on newly auto-created skill detail (skilldet) records; if unset, the translated ''NoDescription'' text is used instead.', 'String: free-text default skill description. Default fallback if unset: translated ''NoDescription'' string.', 0, 0, NULL, 1, '718fe23d293ddd602f963365abbcf9bf3ce3f42eafc4666b22f7e00120497ade', 'v2', '2026-07-24T07:05:23+00:00', '["hrm/class/skill.class.php:269|read|$defaultSkillDesc = getDolGlobalString(''HRM_DEFAULT_SKILL_DESCRIPTION'', $langs->trans(\"NoDescription\"));", "admin/hrm.php:68|''HRM_DEFAULT_SKILL_DESCRIPTION'' => array(''type'' => ''varchar'',''enabled'' => 1, ''css'' => ''''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HRM_EVALUATION_ADVANCED_MASK', 'string', NULL, 'core', 'Numbering mask used by the ''Advanced'' numbering module for HRM Evaluation references.', 'Read/written by mod_evaluation_advanced (core/modules/hrm/mod_evaluation_advanced.php:90,143): shown in an admin setup form input and consumed by getNextValue() to compute the next evaluation ref.', 'Changing the mask changes the format of future HRM evaluation references generated by this module; existing refs are unaffected.', 'Free-form mask string using Dolibarr''s generic mask code syntax (GenericMaskCodes tooltip), same convention as other numbering-module masks; no fixed enum in payload.', 0, 0, NULL, 1, '77d59f1135948b211ffc019bd3c2975fb118cc61b590f39db049addd1d23c78c', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/hrm/mod_evaluation_advanced.php:143|read|$mask = getDolGlobalString(''HRM_EVALUATION_ADVANCED_MASK'');", "core/modules/hrm/mod_evaluation_advanced.php:90|read|...name=\"maskEvaluation\" value=\"''.getDolGlobalString(''HRM_EVALUATION_ADVANCED_MASK'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HRM_JOB_POSITON_ENDING_COMMENT', 'string', NULL, 'hrm', 'Enables the ''abort_comment'' (AbandonmentComment) field on HRM job positions.', 'Used directly as the ''enabled'' condition for the abort_comment field definition in hrm/class/position.class.php:105, gating visibility of that varchar(255) field.', 'When set (truthy int), the AbandonmentComment field becomes enabled/visible on position records; when unset, the field is disabled.', 'Int, truthy enables the field (used as ''enabled'' => ''getDolGlobalInt("HRM_JOB_POSITON_ENDING_COMMENT")'').', 1, 0, NULL, 1, 'bc1921176bd294e3d3f4ceea562e137cce2fce8e51fff0cbb71c6240b66628d8', 'v2', '2026-07-24T07:05:23+00:00', '["hrm/class/position.class.php:105|read|''abort_comment'' => array(... ''enabled'' => ''getDolGlobalInt(\"HRM_JOB_POSITON_ENDING_COMMENT\")'' ...)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('HRM_MAXRANK', 'string', NULL, 'hrm', 'Sets the maximum number of skill rank levels (skill detail rows) that can be defined per skill.', 'Comment in hrm/class/skill.class.php:261: ''@param int $i Rank from which we want to create skilldets (level $i to HRM_MAXRANK will be created)''. Read in hrm/class/skill.class.php:268, hrm/skill_card.php:109, and hrm/lib/hrm_skillrank.lib.php:131 via getDolGlobalInt(''HRM_MAXRANK'', Skill::DEFAULT_MAX_RANK_PER_SKILL). Written via admin/hrm.php:505 if not already set.', 'Increasing this value allows more rank levels per skill; decreasing it limits the number of rank rows that can be created. The fallback is Skill::DEFAULT_MAX_RANK_PER_SKILL when unset.', 'Integer number of max rank levels. Default: Skill::DEFAULT_MAX_RANK_PER_SKILL when unset.', 0, 0, 'admin/hrm.php|admin/hrm.php|admin/hrm.php', 1, '34de4b0bb19df4d89dbbd796da27dca85358506449acffad768aa6c2cd4833ca', 'v2', '2026-04-21T13:29:58+00:00', '["hrm/class/skill.class.php:261  * @param int \t$i \t\tRank from which we want to create skilldets (level $i to HRM_MAXRANK will be created)", "hrm/class/skill.class.php:268|read|$maxNumberSkill = getDolGlobalInt(''HRM_MAXRANK'', self::DEFAULT_MAX_RANK_PER_SKILL);", "hrm/skill_card.php:109|read|$MaxNumberSkill = getDolGlobalInt(''HRM_MAXRANK'', Skill::DEFAULT_MAX_RANK_PER_SKILL);", "admin/hrm.php:505|write|$conf->global->HRM_MAXRANK = Skill::DEFAULT_MAX_RANK_PER_SKILL;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMAP_FORCE_NORSH', 'string', NULL, 'emailcollector', 'Forces the ''/norsh'' flag on IMAP email collector connections, disabling the rsh/ssh pre-authenticated stream.', 'Checked in emailcollector/class/emailcollector.class.php:837 in getConnectStringIMAP(); applied in addition to (not instead of) the collector''s own norsh property.', 'Setting it appends ''/norsh'' to the imap_open connect string for all collectors, which can be needed for some IMAP server configurations that reject rsh negotiation.', 'Boolean: truthy appends the ''/norsh'' flag.', 0, 0, NULL, 1, 'd729d08c1a11cfef8747a4b308daeaa98fef0fa527eeddc85a7f091a3e082ea6', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:837|if (!empty($this->norsh) || getDolGlobalString(''IMAP_FORCE_NORSH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMAP_FORCE_NOSSL', 'string', NULL, 'emailcollector', 'Disables SSL on IMAP email collector connections that are configured with ssl encryption.', 'Checked in emailcollector/class/emailcollector.class.php:828: only relevant when the collector''s imap_encryption is ''ssl'' and IMAP_FORCE_TLS is not set; if true, no encryption flag is appended to the imap_open connect string.', 'Setting it can downgrade an IMAP collector configured for SSL to an unencrypted connection.', 'Boolean: truthy suppresses the SSL flag for collectors configured with imap_encryption == ''ssl''.', 0, 0, NULL, 1, '105b850f81a56cb238cfb72a4e5e0063ffaac2581db40397c282231589d6ea64', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:828|} elseif (empty($this->imap_encryption) || ($this->imap_encryption == ''ssl'' && getDolGlobalString(''IMAP_FORCE_NOSSL''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMAP_FORCE_TLS', 'string', NULL, 'emailcollector', 'Forces the IMAP email collector to use TLS when connecting, regardless of the collector''s configured encryption.', 'Checked first in emailcollector/class/emailcollector.class.php:826 inside getConnectStringIMAP(): if set, appends ''/tls'' to the PHP imap_open connect string flags, taking priority over the collector''s own imap_encryption setting.', 'Setting it forces all IMAP email collectors on the instance to connect with TLS, overriding any per-collector SSL choice.', 'Boolean: truthy forces ''/tls'' flag on the IMAP connection string.', 0, 0, NULL, 1, '3365831f90232d6233a9f855bdde9e7e8da9207e6b87fcf4527f027202fca2b8', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:826|if (getDolGlobalString(''IMAP_FORCE_TLS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMPORT_CSV_FORCE_CHARSET', 'string', NULL, 'core', 'Forces the charset used when reading a CSV file during the CSV import wizard.', 'Checked in core/modules/import/import_csv.modules.php:277-278: `if (getDolGlobalString(''IMPORT_CSV_FORCE_CHARSET'')) { // Forced charset` then `if (strtolower(getDolGlobalString(''IMPORT_CSV_FORCE_CHARSET'')) == ''utf8'') {`.', 'When set, it overrides automatic charset detection for the imported CSV file; setting it to ''utf8'' (case-insensitive) selects UTF-8 decoding specifically.', 'Free-form string; comparison is only made against ''utf8'' (case-insensitive) to trigger UTF-8 handling, other non-empty values still enable the ''forced charset'' branch.', 0, 0, NULL, 1, '2a8660c7ddb6c51a50e8b40c6eff56066838bb4decf0e4a921565e493a0ab749', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/import/import_csv.modules.php:277: if (getDolGlobalString(''IMPORT_CSV_FORCE_CHARSET'')) {\t// Forced charset", "core/modules/import/import_csv.modules.php:278: if (strtolower(getDolGlobalString(''IMPORT_CSV_FORCE_CHARSET'')) == ''utf8'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMPORT_CSV_SEPARATOR_TO_USE', 'string', NULL, 'imports', 'Specifies the field separator character used when parsing CSV import files.', 'Read in admin/import.php:102, imports/import.php:710, and core/modules/import/import_csv.modules.php:109. The default when unset is '',''. Configurable via the admin/import.php UI.', 'Changing this separator affects how CSV data is split into fields during import; using the wrong separator causes fields to be misread.', 'Single character string; default is '',''.', 0, 0, 'admin/import.php', 1, '7ff86150bb2cfa164e4277c7989d73c85e9d0495bc6b3353d06a3d1f00ffbbe6', 'v2', '2026-04-21T11:16:15+00:00', '["admin/import.php:102|read|print ''<td width=\"60\" align=\"center\"><input size=\"3\" class=\"flat\" type=\"text\" name=\"value\" value=\"''.getDolGlobalString(''IMPORT_CSV_SEPARATOR_TO_USE'', '','').''\">''", "imports/import.php:710|read|$separator = (!getDolGlobalString(''IMPORT_CSV_SEPARATOR_TO_USE'') ? '','' : $conf->global->IMPORT_CSV_SEPARATOR_TO_USE);", "core/modules/import/import_csv.modules.php:109|read|$this->separator = (GETPOST(''separator'') ? GETPOST(''separator'') : getDolGlobalString(''IMPORT_CSV_SEPARATOR_TO_USE'', '',''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMPORT_MAX_EXECUTION_TIME', 'string', NULL, 'imports', 'Sets the maximum execution time in seconds allowed for import/export operations.', 'Read twice in imports/import.php:1532 and :2076 via getDolGlobalInt. The inline comment reads ''5mn if not defined''. The default when unset is 300. No admin UI is configured.', 'Increasing this value allows longer-running imports to complete; decreasing it causes large imports to be aborted earlier.', 'Integer (seconds); default is 300 (5 minutes).', 1, 0, NULL, 1, '73acc51448feb29cd89670b1c95fa486f73ad99fa1fdb229aed889cac5b99c11', 'v2', '2026-04-21T11:16:15+00:00', '["imports/import.php:1532|read|$max_execution_time_for_importexport = getDolGlobalInt(''IMPORT_MAX_EXECUTION_TIME'', 300); // 5mn if not defined", "imports/import.php:2076|read|$max_execution_time_for_importexport = getDolGlobalInt(''IMPORT_MAX_EXECUTION_TIME'', 300); // 5mn if not defined"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMPORT_MAX_NB_OF_ERRORS', 'string', NULL, 'imports', 'Sets the maximum number of errors tolerated before an import operation is halted.', 'Read in imports/import.php:1875 via getDolGlobalInt and in imports/import.php:2318 via getDolGlobalString, both defaulting to 50. No admin UI is configured.', 'Reducing this limit causes imports to abort sooner when errors are encountered. Increasing it allows more errors before stopping.', 'Integer; default is 50.', 1, 0, NULL, 1, 'f671f21549a83d3f9046b0d4cf3b1db8b633630b410a18d9b6628cf1c9837513', 'v2', '2026-04-21T11:16:15+00:00', '["imports/import.php:1875|read|$maxnboferrors = getDolGlobalInt(''IMPORT_MAX_NB_OF_ERRORS'', 50);", "imports/import.php:2318|read|$maxnboferrors = !getDolGlobalString(''IMPORT_MAX_NB_OF_ERRORS'') ? 50 : $conf->global->IMPORT_MAX_NB_OF_ERRORS;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMPORT_MAX_NB_OF_WARNINGS', 'string', NULL, 'imports', 'Sets the maximum number of warnings tolerated before an import operation is halted.', 'Read in imports/import.php:1876 via getDolGlobalInt and in imports/import.php:2319 via getDolGlobalString, both defaulting to 50. No admin UI is configured.', 'Reducing this limit causes imports to abort sooner when warnings accumulate. Increasing it allows more warnings before stopping.', 'Integer; default is 50.', 1, 0, NULL, 1, 'fc4972b8bfd7969f3ad9e36236e6745263a2e6695e028798f970f39278a22747', 'v2', '2026-04-21T11:16:15+00:00', '["imports/import.php:1876|read|$maxnbofwarnings = getDolGlobalInt(''IMPORT_MAX_NB_OF_WARNINGS'', 50);", "imports/import.php:2319|read|$maxnbofwarnings = !getDolGlobalString(''IMPORT_MAX_NB_OF_WARNINGS'') ? 50 : $conf->global->IMPORT_MAX_NB_OF_WARNINGS;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMPORT_TRIGGER_ENRICH_OBJECT', 'string', NULL, 'core', 'Enables enriched trigger context (full object data) during CSV/data imports.', 'Read in core/modules/import/modules_import.class.php at line 779. Per the code comment: ''optional richer trigger context can be enabled with IMPORT_TRIGGER_ENRICH_OBJECT''. Cast to bool via getDolGlobalInt.', 'Setting this to 1 causes the import process to pass a fully populated object to triggers; leaving it unset uses a leaner trigger context.', 'optional richer trigger context can be enabled with IMPORT_TRIGGER_ENRICH_OBJECT', 1, 0, NULL, 1, '3b00ed7aa3e6c40f745fca74e39b731cb6112179268ee010811803afe19c3417', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/import/modules_import.class.php:786  // - optional richer trigger context can be enabled with IMPORT_TRIGGER_ENRICH_OBJECT.", "core/modules/import/modules_import.class.php:779|read|$needenrichobject = (bool) getDolGlobalInt(''IMPORT_TRIGGER_ENRICH_OBJECT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('IMPORT_TRIGGER_MODE_DEFAULT', 'string', NULL, 'imports', 'Sets the default trigger mode used during data imports, controlling how triggers are fired per imported line.', 'Read in imports/import.php:165 and core/modules/import/modules_import.class.php:469 with a default of ''strict_line''. No admin UI is configured.', 'Changing this value alters the default trigger-firing behavior for all import operations that do not explicitly override the mode.', 'String mode name; default is ''strict_line''.', 1, 0, NULL, 1, '3c7911a9708f4293eb9d27c56f3089f34979243f885499e61d12e8a23c839fd2', 'v2', '2026-04-21T11:16:15+00:00', '["imports/import.php:165|read|$importtriggermode = getDolGlobalString(''IMPORT_TRIGGER_MODE_DEFAULT'', ''strict_line'');", "core/modules/import/modules_import.class.php:469|read|$mode = (string) getDolGlobalString(''IMPORT_TRIGGER_MODE_DEFAULT'', ''strict_line'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INTERVENTION_ADDLINE_FREEDUREATION', 'string', NULL, 'fichinter', 'Switches the duration input on the intervention add/edit line form from a dropdown selector to a free-text field.', 'Checked in fichinter/card.php:1761 and 1854 (both guarded by `!getDolGlobalString(''FICHINTER_WITHOUT_DURATION'')`): sets $selectmode = ''text'' instead of the default ''select'' passed to $form->select_duration().', 'Enabling it lets users type an arbitrary duration value instead of choosing from the standard hour/minute select widget, when duration entry is otherwise enabled.', 'Boolean: truthy uses free-text duration input; falsy (default) uses the select-based duration widget.', 0, 0, NULL, 1, 'b870c21fe2aa3dbe8aa8c79da1cac4f1b6b6edb4071f74d5f469cd20492e633c', 'v2', '2026-07-24T07:05:23+00:00', '["fichinter/card.php:1761|if (getDolGlobalString(''INTERVENTION_ADDLINE_FREEDUREATION'')) { $selectmode = ''text''; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INTRACOMMREPORT_CATEG_FRAISDEPORT', 'string', NULL, 'intracommreport', 'Identifies the product category ID to treat as shipping costs (frais de port) in intracomm DEB exports.', 'Configurable via the admin UI at intracommreport/admin/intracommreport.php (written at line 86, displayed as a category selector at line 176). Checked in intracommreport/class/intracommreport.class.php at lines 405 and 419; the category is fetched at line 407.', 'Setting this to a valid category ID causes products in that category to be identified and handled as shipping costs in the DEB export; leaving it at 0 skips shipping-cost filtering.', 'integer (product category ID); 0 = no shipping cost category filter', 0, 0, 'intracommreport/admin/intracommreport.php|intracommreport/admin/intracommreport.php', 1, '46fb20edd3ae8df2c3066aa23ef9b2c0a95092a334f662ca2bee20378678648d', 'v2', '2026-04-21T13:29:58+00:00', '["intracommreport/admin/intracommreport.php:86|write|dolibarr_set_const($db, \"INTRACOMMREPORT_CATEG_FRAISDEPORT\", GETPOST(\"INTRACOMMREPORT_CATEG_FRAISDEPORT\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "intracommreport/class/intracommreport.class.php:405|check|if ($exporttype == ''deb'' && getDolGlobalInt(''INTRACOMMREPORT_CATEG_FRAISDEPORT'') > 0) {", "intracommreport/class/intracommreport.class.php:407|read|$categ_fraisdeport->fetch(getDolGlobalInt(''INTRACOMMREPORT_CATEG_FRAISDEPORT''));", "intracommreport/class/intracommreport.class.php:419|check|if (getDolGlobalInt(''INTRACOMMREPORT_CATEG_FRAISDEPORT'') > 0 && $categ_fraisdeport->containsObject(''product'', $res->id_prod)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INTRACOMMREPORT_NIV_OBLIGATION_', 'string', NULL, 'intracommreport', 'Prefix for two constants (INTRACOMMREPORT_NIV_OBLIGATION_INTRODUCTION / _EXPEDITION) selecting the DEB obligation level (threshold) used for the declarationTypeCode in the intracommunity report XML.', 'Read dynamically in intracommreport/class/intracommreport.class.php:331 as getDolGlobalString(''INTRACOMMREPORT_NIV_OBLIGATION_''.strtoupper($type)) where $type is ''introduction'' or ''expedition''. Set via admin page intracommreport/admin/intracommreport.php with a select box.', 'The chosen value changes the declarationTypeCode reported in the DEB/DES XML, reflecting whether the company is above or below the intra-community trade threshold; wrong values can lead to an incorrectly classified declaration.', 'For INTRODUCTION: 1 = ''Seuil de 460 000 EUR'', 2 = ''En dessous de 460 000 EUR''. For EXPEDITION: 3 = ''Seuil de 460 000 EUR'', 4 = ''En dessous de 460 000 EUR'' (per admin select arrays).', 0, 0, NULL, 1, 'd87bba3aa4d732a223bafb22ed0f268398662aa01201f2170856eccc32244833', 'v2', '2026-07-24T07:05:23+00:00', '["intracommreport/class/intracommreport.class.php:331|read|$declaration->addChild(''declarationTypeCode'', getDolGlobalString(''INTRACOMMREPORT_NIV_OBLIGATION_''.strtoupper($type)));", "intracommreport/admin/intracommreport.php: $arraychoices = array(1 => ''Seuil de 460 000 €'', 2 => ''En dessous de 460 000 €'');", "intracommreport/admin/intracommreport.php: $arraychoices = array(3 => ''Seuil de 460 000 €'', 4 => ''En dessous de 460 000 €'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INTRACOMMREPORT_NIV_OBLIGATION_EXPEDITION', 'string', NULL, 'intracommreport', 'Stores the obligation level for Intrastat expeditions (exports) used in the Intrastat report configuration.', 'Set at intracommreport/admin/intracommreport.php:85 and displayed in a selectarray at intracommreport/admin/intracommreport.php:169. No comment is present in the payload and no class-level read is present.', 'Changing this value adjusts the declared obligation level for export flows in the Intrastat setup; the exact effect on report generation is not visible in the available payload.', 'String; a valid obligation level code from the admin selectarray choices.', 0, 0, 'intracommreport/admin/intracommreport.php|intracommreport/admin/intracommreport.php', 1, 'c3e09a70d71d505e269fc25c6c6ce3e001f66a6965da97754a97b23200a505ba', 'v2', '2026-04-21T13:29:58+00:00', '["intracommreport/admin/intracommreport.php:85|write|dolibarr_set_const($db, \"INTRACOMMREPORT_NIV_OBLIGATION_EXPEDITION\", GETPOST(\"INTRACOMMREPORT_NIV_OBLIGATION_EXPEDITION\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "intracommreport/admin/intracommreport.php:169|read|print $form->selectarray(''INTRACOMMREPORT_NIV_OBLIGATION_EXPEDITION'', $arraychoices, getDolGlobalString(''INTRACOMMREPORT_NIV_OBLIGATION_EXPEDITION''), 0);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INTRACOMMREPORT_NIV_OBLIGATION_INTRODUCTION', 'string', NULL, 'intracommreport', 'Stores the obligation level for Intrastat introductions (imports) used in the Intrastat report configuration.', 'Set at intracommreport/admin/intracommreport.php:84 and displayed in a selectarray at intracommreport/admin/intracommreport.php:161. No comment is present in the payload and the constant is not read in any class file in the payload.', 'Changing this value adjusts the declared obligation level for import flows in the Intrastat setup; the exact effect on report generation is not visible in the available payload.', 'String; a valid obligation level code from the admin selectarray choices.', 0, 0, 'intracommreport/admin/intracommreport.php|intracommreport/admin/intracommreport.php', 1, 'a1bfe31a9c627f04abb1ac936f5d186a35df3e24751cef6230c38bef7509ccbb', 'v2', '2026-04-21T13:29:58+00:00', '["intracommreport/admin/intracommreport.php:84|write|dolibarr_set_const($db, \"INTRACOMMREPORT_NIV_OBLIGATION_INTRODUCTION\", GETPOST(\"INTRACOMMREPORT_NIV_OBLIGATION_INTRODUCTION\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "intracommreport/admin/intracommreport.php:161|read|print $form->selectarray(''INTRACOMMREPORT_NIV_OBLIGATION_INTRODUCTION'', $arraychoices, getDolGlobalString(''INTRACOMMREPORT_NIV_OBLIGATION_INTRODUCTION''), 0);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INTRACOMMREPORT_NUM_AGREMENT', 'string', NULL, 'intracommreport', 'Approval/agreement number used as the envelopeId in the generated DEB/DES intracommunity trade declaration XML.', 'Read in intracommreport/class/intracommreport.class.php:310 (getXML) to fill the <envelopeId> element of the INSTAT XML envelope. It is settable via the admin page intracommreport/admin/intracommreport.php (listed in $list_DEB array).', 'Changing this value changes the envelopeId identifier reported to customs authorities in the generated declaration file; an incorrect value could cause the declaration to be rejected.', 'Free-text string, the agreement number assigned to the declarant.', 0, 0, NULL, 1, '240dedab718e1fa74b6b778389157e0ff7fa23ad5b7bd8274e5c59af82f01d12', 'v2', '2026-07-24T07:05:23+00:00', '["intracommreport/class/intracommreport.class.php:310|read|$envelope->addChild(''envelopeId'', getDolGlobalString(''INTRACOMMREPORT_NUM_AGREMENT''));", "intracommreport/admin/intracommreport.php: $list_DEB = array(''INTRACOMMREPORT_NUM_AGREMENT'',);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INTRACOMMREPORT_ROLE_ACTEUR', 'string', NULL, 'intracommreport', 'Stores the party role code (partyRole) used when generating the Intrastat XML report.', 'Set via admin/intracommreport.php:83 and read into the XML attribute $party->addAttribute(''partyRole'', ...) at intracommreport/class/intracommreport.class.php:316. Selected from an array of choices in the admin UI.', 'Changing this value alters the partyRole attribute in the Intrastat declaration XML, which must match the value required by the national customs authority.', 'String; a valid partyRole code from the choices available in the admin selectarray.', 0, 0, 'intracommreport/admin/intracommreport.php|intracommreport/admin/intracommreport.php', 1, 'd20644d81d5761582ded75065e0c642e17fe4de95ba7109698c235c8ceae2a53', 'v2', '2026-04-21T13:29:58+00:00', '["intracommreport/admin/intracommreport.php:83|write|dolibarr_set_const($db, \"INTRACOMMREPORT_ROLE_ACTEUR\", GETPOST(\"INTRACOMMREPORT_ROLE_ACTEUR\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "intracommreport/class/intracommreport.class.php:316|read|$party->addAttribute(''partyRole'', $conf->global->INTRACOMMREPORT_ROLE_ACTEUR);", "intracommreport/admin/intracommreport.php:153|read|print $form->selectarray(''INTRACOMMREPORT_ROLE_ACTEUR'', $arraychoices, getDolGlobalString(''INTRACOMMREPORT_ROLE_ACTEUR''), 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INTRACOMMREPORT_TYPE_ACTEUR', 'string', NULL, 'intracommreport', 'Specifies the actor type (e.g. PSI) for intracomm report XML declarations.', 'Configurable via the admin UI at intracommreport/admin/intracommreport.php (written at line 82, displayed as a select at line 145). Used in intracommreport/class/intracommreport.class.php at lines 315 and 323.', 'Setting this to ''PSI'' triggers a specific code path in the declaration; other values use the default path. Incorrect values may produce non-compliant declarations.', 'string (actor type code), e.g. ''PSI''; selected from predefined array choices', 0, 0, 'intracommreport/admin/intracommreport.php|intracommreport/admin/intracommreport.php', 1, 'cf69c4c57020be85db6e3f910b32f7906591f080318b953acb63f28a901be674', 'v2', '2026-04-21T13:29:58+00:00', '["intracommreport/admin/intracommreport.php:82|write|dolibarr_set_const($db, \"INTRACOMMREPORT_TYPE_ACTEUR\", GETPOST(\"INTRACOMMREPORT_TYPE_ACTEUR\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "intracommreport/class/intracommreport.class.php:315|read|$party->addAttribute(''partyType'', $conf->global->INTRACOMMREPORT_TYPE_ACTEUR);", "intracommreport/class/intracommreport.class.php:323|check|if (getDolGlobalString(''INTRACOMMREPORT_TYPE_ACTEUR'') === ''PSI'') {", "intracommreport/admin/intracommreport.php:145|read|print $form->selectarray(''INTRACOMMREPORT_TYPE_ACTEUR'', $arraychoices, getDolGlobalString(''INTRACOMMREPORT_TYPE_ACTEUR''), 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVENTORY_INCLUDE_SUB_WAREHOUSE', 'string', NULL, 'product', 'Includes stock from sub-warehouses when loading inventory lines for a parent warehouse.', 'Checked at product/inventory/inventory.php lines 514 and 629, product/inventory/card.php lines 298 and 429, and product/inventory/class/inventory.class.php line 286. COMMENT at core/actions_addupdatedelete.inc.php:546 states: ''// Can happen when the conf INVENTORY_INCLUDE_SUB_WAREHOUSE is set''.', 'Enabling this constant causes inventory loading to include stock from child warehouses of the selected warehouse. Disabling it restricts inventory to the directly selected warehouse.', 'Boolean/integer flag; 0 or absent = only selected warehouse; non-zero = selected warehouse plus sub-warehouses included.', 1, 0, NULL, 1, '0cf28dc38364975975a670b02a93e411411e87cf194bd0c30d1284387a3f0ebb', 'v2', '2026-04-21T13:29:58+00:00', '["core/actions_addupdatedelete.inc.php:546  // Can happen when the conf INVENTORY_INCLUDE_SUB_WAREHOUSE is set", "product/inventory/inventory.php:514|check|if (getDolGlobalInt(''INVENTORY_INCLUDE_SUB_WAREHOUSE'') && !empty($object->fk_warehouse)) {", "product/inventory/card.php:298|check|if (getDolGlobalInt(''INVENTORY_INCLUDE_SUB_WAREHOUSE'') && !empty($object->fk_warehouse)) {", "product/inventory/class/inventory.class.php:286|check|if (!empty($include_sub_warehouse) && getDolGlobalInt(''INVENTORY_INCLUDE_SUB_WAREHOUSE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVENTORY_MANAGE_REAL_PMP', 'string', NULL, 'product', 'Enables management and display of the real weighted-average purchase price (PMP) during inventory operations.', 'Checked at 8 locations in product/inventory/inventory.php (lines 230, 256, 976, 1019, 1145, 1202, 1258, 1337); real PMP fields and calculations are shown or processed only when this constant is set.', 'Enabling this constant activates real-PMP columns and processing in the inventory workflow. Disabling it hides those fields.', 'Boolean/string flag; absent/falsy = real PMP not managed; truthy = real PMP managed and displayed.', 1, 0, NULL, 1, '9181077b2a30253e68f641ce4a65a9c2d9eda7bf8f570d1426b491a69066eff8', 'v2', '2026-04-21T13:29:58+00:00', '["product/inventory/inventory.php:1145|check|if (getDolGlobalString(''INVENTORY_MANAGE_REAL_PMP'')) {", "product/inventory/inventory.php:230|check|if (!empty($line->pmp_real) && getDolGlobalString(''INVENTORY_MANAGE_REAL_PMP'')) {", "product/inventory/inventory.php:976|check|if (getDolGlobalString(''INVENTORY_MANAGE_REAL_PMP'')) {", "product/inventory/inventory.php:1258|check|if (getDolGlobalString(''INVENTORY_MANAGE_REAL_PMP'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICEREC_SET_AUTOFILL_DATE_END', 'string', NULL, 'compta', 'Default value (yes/no) used to pre-fill the ''auto-fill date end'' option on lines of a recurring (template) invoice.', 'Read in core/tpl/objectline_view.tpl.php:294 (only when viewing lines in the recurring invoice card, i.e. PHP_SELF == ''card-rec.php'') and in compta/facture/class/facture-rec.class.php:459 when generating a real invoice from the template, both via getDolGlobalInt.', 'Setting it changes the default shown/used for whether a recurring invoice line''s end date is auto-filled from the recurrence date when the template is displayed or when a new invoice is generated from it.', 'Integer used as a yes/no flag (displayed via yn()): 0 = No (default), 1 = Yes.', 0, 0, NULL, 1, 'd0ea15417fd011b737d29a043201ec902336ace25a6eb4c81b53c44cf434d9c9', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_view.tpl.php:294: $default_end_fill = getDolGlobalInt(''INVOICEREC_SET_AUTOFILL_DATE_END'');", "core/tpl/objectline_view.tpl.php:298: ...AutoFillDateToShort'').'':</span> ''.yn($default_end_fill);", "compta/facture/class/facture-rec.class.php:459: $default_end_fill = getDolGlobalInt(''INVOICEREC_SET_AUTOFILL_DATE_END'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICEREC_SET_AUTOFILL_DATE_START', 'string', NULL, 'compta', 'Default value (yes/no) used to pre-fill the ''auto-fill date start'' option on lines of a recurring (template) invoice.', 'Read in core/tpl/objectline_view.tpl.php:293 (only when viewing lines in the recurring invoice card, i.e. PHP_SELF == ''card-rec.php'') and in compta/facture/class/facture-rec.class.php:458 when generating a real invoice from the template, both via getDolGlobalInt.', 'Setting it changes the default shown/used for whether a recurring invoice line''s start date is auto-filled from the recurrence date when the template is displayed or when a new invoice is generated from it.', 'Integer used as a yes/no flag (displayed via yn()): 0 = No (default), 1 = Yes.', 0, 0, NULL, 1, 'd1205a29113e36315ed33def799d9bd1a9abdfd704a29e0546749eddb345a856', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_view.tpl.php:293: $default_start_fill = getDolGlobalInt(''INVOICEREC_SET_AUTOFILL_DATE_START'');", "core/tpl/objectline_view.tpl.php:296: ...AutoFillDateFromShort'').'':</span> ''.yn($default_start_fill);", "compta/facture/class/facture-rec.class.php:458: $default_start_fill = getDolGlobalInt(''INVOICEREC_SET_AUTOFILL_DATE_START'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ADD_DEPOSIT_DATE', 'string', NULL, 'core', 'Adds a deposit date column or field to invoice line displays and PDF outputs.', 'Checked in societe/consumption.php:685, contact/consumption.php:591, core/tpl/objectline_view.tpl.php:167, core/lib/pdf.lib.php:2073, and core/lib/doc.lib.php:90 to conditionally render a deposit date element across consumption views and document generation.', 'Enabling this constant causes deposit date information to appear in invoice line views and generated PDF documents.', 'Truthy value adds deposit date display; absent or falsy omits it.', 1, 0, NULL, 1, '0741f31b3a707d1a7387af523587e6550e552e6c280ae5adb430d49e00104d80', 'v2', '2026-04-21T11:16:15+00:00', '["societe/consumption.php:685|check|if (getDolGlobalString(''INVOICE_ADD_DEPOSIT_DATE'')) {", "core/tpl/objectline_view.tpl.php:167|check|if (getDolGlobalString(''INVOICE_ADD_DEPOSIT_DATE'')) {", "core/lib/pdf.lib.php:2073|check|if (getDolGlobalString(''INVOICE_ADD_DEPOSIT_DATE'')) {", "core/lib/doc.lib.php:90|check|if (getDolGlobalString(''INVOICE_ADD_DEPOSIT_DATE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ADD_EPC_QR_CODE', 'string', NULL, 'core', 'Controls placement of an EPC (European Payments Council) QR code on invoice PDFs to facilitate bank transfers.', 'Written in admin/pdf_other.php at lines 139 and 141 (set/del) and displayed as a select at line 566. Checked in pdf_octopus.modules.php at lines 558, 577, and 1608 and pdf_sponge.modules.php at lines 507 and 1674 to place the QR code in-line or at the bottom when there is a remaining balance and the payment mode is bank transfer (VIR).', 'Setting to ''1'' adds the EPC QR code inline on the invoice (for bank transfer payment mode); setting to ''bottom'' places it at the bottom of the last page when a balance remains. Leaving unset omits the QR code entirely.', '''1'' = add EPC QR code inline (payment mode VIR); ''bottom'' = add at bottom of last page when remaining balance > 0; empty/unset = no QR code.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, '070abfe60f95f58a35de71bf75a745a9d64a77c36dee7164637a8d40edccb04d', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/facture/doc/pdf_octopus.modules.php:577|check|if (getDolGlobalString(''INVOICE_ADD_EPC_QR_CODE'') == ''1'' && (empty($object->mode_reglement_code) || $object->mode_reglement_code == ''VIR'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:1608|check|if (getDolGlobalString(''INVOICE_ADD_EPC_QR_CODE'') == ''bottom'' && ($object->getRemainToPay() > 0)) {", "core/modules/facture/doc/pdf_sponge.modules.php:507|check|if (getDolGlobalString(''INVOICE_ADD_EPC_QR_CODE'') == ''1'' && (empty($object->mode_reglement_code) || $object->mode_reglement_code == ''VIR'')) {", "core/modules/facture/doc/pdf_sponge.modules.php:1674|check|if ((getDolGlobalString(''INVOICE_ADD_EPC_QR_CODE'') == ''bottom'') && ($object->getRemainToPay() > 0)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ADD_EXTRAFIELD_IN_NOTE', 'string', NULL, 'core', 'Appends the invoice''s extrafields (rendered as HTML) to the public note shown on the Canelle supplier-invoice PDF model.', 'In core/modules/supplier_invoice/doc/pdf_canelle.modules.php:335-339, if getDolGlobalString(''INVOICE_ADD_EXTRAFIELD_IN_NOTE'') is true, $this->getExtrafieldsInHtml($object, $outputlangs) is computed and concatenated onto $notetoshow before it is printed on the PDF.', 'Enabling it adds the object''s extrafield values into the notes section of this specific PDF template''s output.', 'Boolean: true appends extrafields to the printed note; false/unset (default) leaves the note as-is.', 1, 0, NULL, 1, 'e0c2460c8c47ce8acb1d2365768fa86b4dd551fb579cf466080aba5845f2a66a', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_invoice/doc/pdf_canelle.modules.php:335|check|if (getDolGlobalString(''INVOICE_ADD_EXTRAFIELD_IN_NOTE'')) {", "core/modules/supplier_invoice/doc/pdf_canelle.modules.php:336|  $extranote = $this->getExtrafieldsInHtml($object, $outputlangs);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ADD_SWISS_QR_CODE', 'string', NULL, 'core', 'Controls the placement of a Swiss QR code on invoice PDFs, configured via the admin UI.', 'Managed via the admin UI at admin/pdf_other.php (written, deleted, and displayed as a select array). Checked in modules_facture.php, pdf_octopus.modules.php, and pdf_sponge.modules.php with the value ''bottom'' to determine QR code placement, and compared against ''bottom'' negation for alternative layout.', 'Setting this to ''bottom'' places the Swiss QR code at the bottom of the invoice PDF. Other values or clearing may disable or reposition the QR code depending on template logic.', '''bottom'' = Swiss QR code added at the bottom of the invoice PDF; other/unset = QR code not placed at bottom.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, '28d4bd231972ac8e47b2b32cd26c6517266dcca230a19c066b0feda82b6230ac', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:145|dolibarr_set_const($db, \"INVOICE_ADD_SWISS_QR_CODE\", GETPOST(\"INVOICE_ADD_SWISS_QR_CODE\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/pdf_other.php:571|if (getDolGlobalString(''INVOICE_ADD_SWISS_QR_CODE'') == ''bottom'') {", "modules_facture.php:268|if (getDolGlobalString(''INVOICE_ADD_SWISS_QR_CODE'') == ''bottom'') {", "modules_facture.php:159|if (getDolGlobalString(''INVOICE_ADD_SWISS_QR_CODE'') != ''bottom'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ADD_ZATCA_QR_CODE', 'string', NULL, 'admin', 'Enables adding a ZATCA-compliant QR code to invoice PDFs (Saudi Arabia e-invoicing standard).', 'Written in admin/pdf_other.php at lines 133 and 147 (set/del) and displayed as a select at line 555. Checked in pdf_octopus.modules.php at line 552 and pdf_sponge.modules.php at line 482.', 'Enabling this constant causes invoice PDFs to include a ZATCA QR code for Saudi e-invoicing compliance. Disabling it omits the QR code from PDFs.', 'Truthy value to add ZATCA QR code; empty/unset to omit.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, '5641c342e90d15760ac7ec708da9aa8a17816e8054713d8e11100f99303cc7e9', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:133|write|dolibarr_set_const($db, \"INVOICE_ADD_ZATCA_QR_CODE\", GETPOSTINT(\"INVOICE_ADD_ZATCA_QR_CODE\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/facture/doc/pdf_octopus.modules.php:552|check|if (getDolGlobalString(''INVOICE_ADD_ZATCA_QR_CODE'')) {", "core/modules/facture/doc/pdf_sponge.modules.php:482|check|if (getDolGlobalString(''INVOICE_ADD_ZATCA_QR_CODE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'core', 'Enables an external download link for customer invoice documents.', 'Checked in core/class/commonobject.class.php:6380 and core/lib/functions.lib.php:10738. When set, a public download link is generated for invoice (facture) objects.', 'Enabling this constant exposes invoice documents via a public URL; disabling it removes the external download option.', 'Non-zero/non-empty = external download enabled; 0 or unset = disabled', 1, 0, NULL, 1, '2caaf4267c4906d3425ec2f1b109a4ae5ca9e1b59dcfd9d6eda0221f831e4632', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:6380|check|if ($this->element == ''facture'' && getDolGlobalInt(\"INVOICE_ALLOW_EXTERNAL_DOWNLOAD\")) {", "core/lib/functions.lib.php:10738|check|if (getDolGlobalString(''INVOICE_ALLOW_EXTERNAL_DOWNLOAD'') && is_object($object) && $object->element == ''facture'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ALLOW_FREE_REF', 'bool', NULL, 'compta', 'Allows manually editing the invoice reference (ref) of a draft invoice for companies not subject to EEC (EU) rules.', 'In compta/facture/card.php:5378, the free-ref edit path is enabled only if the invoice is a draft, the company (mysoc) is not in the EEC, and this constant is truthy.', 'Enabling it (for non-EEC companies) lets users freely edit/override the invoice reference on draft invoices instead of relying solely on the numbering module.', 'Boolean-like flag; only takes effect combined with draft status and !mysoc->isInEEC().', 1, 0, NULL, 1, '6640fe1acb088058d583ddcd3de6af810cbc5dcf5df859926fa346d0c20206c1', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/card.php:5378: if ($object->status == $object::STATUS_DRAFT && !$mysoc->isInEEC() && getDolGlobalString(''INVOICE_ALLOW_FREE_REF'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ALLOW_POS_SOURCE_EDIT', 'bool', NULL, 'compta', 'Allows the Point-of-Sale-related section of the invoice card to be shown/edited even when the takepos module is disabled and the invoice has no module_source.', 'In compta/facture/card.php:5504, the POS info block is displayed if the takepos module is enabled, or the invoice has a module_source, or this constant is truthy.', 'Enabling it exposes the POS/PointOfSale field on invoices that were not created from a POS module_source and even if takepos is disabled.', 'Boolean-like flag (one of three OR''d conditions gating POS block display).', 1, 0, NULL, 1, '42bcd0ac3cd78a176ea694d0460b563c8ac6850ae41488ffb28f492b71ead96d', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/card.php:5504: if (isModEnabled(''takepos'') || $object->module_source || getDolGlobalString(''INVOICE_ALLOW_POS_SOURCE_EDIT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ALLOW_REUSE_OF_CREDIT_WHEN_PARTIALLY_REFUNDED', 'bool', NULL, 'compta', 'When enabled, allows a credit note to be reused as credit even when it has been only partially refunded.', 'Checked in compta/facture/card.php at lines 1029 and 6759 in conditions related to credit note reuse and display of the credit reuse action.', 'Enabling this constant permits partially-refunded credit notes to be applied as credits, which would not otherwise be allowed.', '0 or unset = credit reuse blocked if partially refunded; truthy = credit reuse allowed even if partially refunded.', 1, 0, NULL, 1, 'c51deac60142ebc5c54ed3d8dc8408f7cee1ad7dd2688598bcaa286cafa6f8d4', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:1029|check|if (getDolGlobalString(''INVOICE_ALLOW_REUSE_OF_CREDIT_WHEN_PARTIALLY_REFUNDED'') && $object->type == Facture::TYPE_CREDIT_NOTE) {", "compta/facture/card.php:6759|read|&& (getDolGlobalString(''INVOICE_ALLOW_REUSE_OF_CREDIT_WHEN_PARTIALLY_REFUNDED'') || $sumofpayment == 0) && $object->total_ht < 0"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_AUTO_NEXT_MONTH_ON_LINES', 'string', NULL, 'compta', 'Enables month-by-month auto-update of service line start/end dates when a validated invoice is cloned.', 'In Facture::createFromClone (compta/facture/class/facture.class.php:1361), for each cloned line with both date_start and date_end set, the code recomputes the first/last day of the following month(s) when this constant is truthy.', 'When enabled, cloning an invoice with service lines shifts their date_start/date_end to the next month period instead of keeping the original dates.', 'Boolean-like flag (0/1 via getDolGlobalString truthiness).', 1, 0, NULL, 1, 'ebbb71aacbe353bf6b67404fdb81f59f15e1a4ea8755f4e5c0900355a31ef025', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/class/facture.class.php:1361: if (getDolGlobalString(''INVOICE_AUTO_NEXT_MONTH_ON_LINES'') && !empty($line->date_start) && !empty($line->date_end)) {", "compta/facture/class/facture.class.php:1359: // Block to update dates of service (month by month only if previously filled and similar to start and end of month)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CAN_BE_EDITED_EVEN_IF_PAYMENT_DONE', 'string', NULL, 'compta', 'When enabled, allows editing of an invoice that has already been fully paid.', 'Checked in compta/facture/card.php at lines 862 and 6591 as an override condition that permits editing when payment has been recorded.', 'Enabling this constant allows modification of fully paid invoices, which can lead to discrepancies between recorded payments and invoice amounts.', '0 or unset = editing blocked when payment is done; truthy = editing allowed even after payment.', 1, 0, NULL, 1, '565296f3c5e2757b713e894f396ec44e7274d8e99da492531281c060ecd596ae', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:862|check|if (getDolGlobalString(''INVOICE_CAN_BE_EDITED_EVEN_IF_PAYMENT_DONE'') || ($resteapayer == $object->total_ttc && empty($object->paye))) {", "compta/facture/card.php:6591|check|if (getDolGlobalString(''INVOICE_CAN_BE_EDITED_EVEN_IF_PAYMENT_DONE'') || ($resteapayer == price2num($object->total_ttc, ''MT'', 1) && empty($object->paye))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CAN_DELETE_PAYMENT_EVEN_IF_INVOICE_CLOSED', 'string', NULL, 'compta', 'Allows deletion of a payment even when at least one linked invoice is already marked as paid.', 'By default, compta/paiement/card.php:602 blocks deletion if any linked invoice has paye==1. Setting this constant overrides that guard. The comment explicitly states it is for maintenance purposes only and should never be used in production.', 'Enabling this constant removes a safety guard and permits deletion of payments linked to closed invoices, which can break invoice/payment reconciliation. It must not be used in production.', 'Truthy string (deletion allowed on closed invoices) or empty/unset (deletion blocked). // If at least one invoice is paid, disable delete. INVOICE_CAN_DELETE_PAYMENT_EVEN_IF_INVOICE_CLOSED Can be use for maintenance purpose. Never use this in production', 1, 0, NULL, 1, '586a67fe0c7126622e9c9d4e7c0b00bc0254a905a8c2c996189a092df2e2c5e6', 'v2', '2026-04-21T13:29:58+00:00', '["compta/paiement/card.php:601  // If at least one invoice is paid, disable delete. INVOICE_CAN_DELETE_PAYMENT_EVEN_IF_INVOICE_CLOSED Can be use for maintenance purpose. Never use this in production", "compta/paiement/card.php:602|check|if ($objp->paye == 1 && !getDolGlobalString(''INVOICE_CAN_DELETE_PAYMENT_EVEN_IF_INVOICE_CLOSED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CAN_NEVER_BE_CANCELED', 'string', NULL, 'fourn', 'Hides the ''ClassifyCanceled'' action button, preventing supplier/customer invoices from being manually classified as canceled.', 'Checked in fourn/facture/card.php:4361 and compta/facture/card.php:6893; when not set, the ''ClassifyCanceled'' button is shown for validated unpaid invoices with no linked payments/credit notes.', 'When set, the classify-as-canceled action is removed from the invoice card, so users cannot cancel that invoice through the UI.', 'Bool: truthy hides/disables the ability to classify an invoice as canceled.', 1, 0, NULL, 1, 'ed173e919e11dc36497dbd0577f85558023db705d1ab97abc894bcba37eff1e8', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:4361|check|if (!getDolGlobalString(''INVOICE_CAN_NEVER_BE_CANCELED'')) {", "compta/facture/card.php:6893|check|if (!getDolGlobalString(''INVOICE_CAN_NEVER_BE_CANCELED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CAN_NEVER_BE_EDITED', 'string', NULL, 'compta', 'When enabled, prevents any editing of validated invoices regardless of payment status.', 'Checked in compta/facture/card.php at lines 809, 4961, and 6586. When set, the confirm_modif action is blocked (line 809) and the edit UI is suppressed for validated invoices (line 4961 and 6586).', 'Enabling this constant makes validated invoices permanently read-only, blocking all editing actions even for users with unvalidate permissions.', '0 or unset = editing allowed under normal conditions; truthy = editing always blocked for validated invoices.', 1, 0, NULL, 1, 'aaa8bcae9008ceeddd25c456e8137a1f0218a2039b15f9a971abe2084e27acf9', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:4961|check|if (getDolGlobalString(''INVOICE_CAN_NEVER_BE_EDITED'')) {", "compta/facture/card.php:809|read|} elseif ($action == ''confirm_modif'' && $usercanunvalidate && !getDolGlobalString(''INVOICE_CAN_NEVER_BE_EDITED'')) {", "compta/facture/card.php:6586|check|if ($object->status == Facture::STATUS_VALIDATED && !getDolGlobalString(''INVOICE_CAN_NEVER_BE_EDITED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CAN_NEVER_BE_REMOVED', 'string', NULL, 'core', 'Prevents deletion of any invoice when set to 1, overriding all other deletion permission checks.', 'Checked at core/class/commoninvoice.class.php:725 and :898 to block invoice deletion. The comment at :873 confirms: ''If hidden option INVOICE_CAN_NEVER_BE_REMOVED is 1 -> no (0)''. No admin UI; hidden setting.', 'Setting to 1 makes all invoices permanently non-deletable regardless of status or user permissions. Setting to 0 or leaving unset allows normal deletion rules to apply.', '0 or empty = normal deletion rules apply; 1 = no invoice can ever be removed', 1, 0, NULL, 1, 'ea5d17ed66a7d9276e72b72abcbb44430315b2b68be84b2efd440c202e95b610', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/commoninvoice.class.php:873  *  If hidden option INVOICE_CAN_NEVER_BE_REMOVED is 1 -> no (0)", "core/class/commoninvoice.class.php:725|check|if (getDolGlobalInt(''INVOICE_CAN_NEVER_BE_REMOVED'')) {", "core/class/commoninvoice.class.php:898|check|if (getDolGlobalInt(''INVOICE_CAN_NEVER_BE_REMOVED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CAN_SET_PAID_EVEN_IF_PARTIALLY_PAID', 'string', NULL, 'compta', 'When enabled, allows marking an invoice as paid even when no payment has been recorded (full remaining balance), bypassing the partial-payment restriction.', 'Checked in compta/facture/card.php at lines 5155, 5158, 6777, and 6793 in the paid-status transition logic.', 'Enabling this constant allows the ''paid'' action to be triggered on invoices with an outstanding balance equal to the full invoice amount, without requiring a recorded payment.', '0 or unset = invoice can only be marked paid when balance is zero or partially reduced; truthy = paid action allowed even when full balance remains.', 1, 0, NULL, 1, '5ba1ea5bb95d7c1ffc13db1d080adb3e0a3bea9c0e8b5c5d9488e08ffc77e04f', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:5155|check|if ($action == ''paid'' && ($resteapayer <= 0 || (getDolGlobalString(''INVOICE_CAN_SET_PAID_EVEN_IF_PARTIALLY_PAID'') && $resteapayer == $object->total_ttc))) {", "compta/facture/card.php:5158|check|if ($action == ''paid'' && $resteapayer > 0 && (!getDolGlobalString(''INVOICE_CAN_SET_PAID_EVEN_IF_PARTIALLY_PAID'') || $resteapayer != $object->total_ttc)) {", "compta/facture/card.php:6793|check|if ($object->status == Facture::STATUS_VALIDATED && $object->paye == 0 && $resteapayer > 0 && (!getDolGlobalString(''INVOICE_CAN_SET_PAID_EVEN_IF_PARTIALLY_PAID'') || $resteapayer !="]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CATEGORY_OF_OPERATION', 'string', NULL, 'core', 'Specifies the category of operation for invoice PDF generation, used notably for French VAT self-billing rules.', 'Written in admin/pdf_other.php at line 151 and displayed as a select at line 593. Also written programmatically in master.inc.php at line 330 and api/class/api_access.class.php at line 184 where it is set to 1. Checked in pdf_octopus.modules.php at lines 1449 and 1877 and pdf_sponge.modules.php at lines 1515 and 2135 comparing against values 1 and 2.', 'Setting to 1 or 2 activates specific invoice category logic (e.g. different VAT or self-billing sections) in PDF templates. The value is also forced to 1 automatically in API access and master.inc.php contexts.', 'Integer: 1 or 2 trigger specific category-of-operation rendering branches in PDF templates; 0 or unset applies no special category logic.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, 'eab03d6196c515482b0649ecd6735f8a6a2b0d92954342ee60ade7a6a5062b5b', 'v2', '2026-04-21T13:50:40+00:00', '["master.inc.php:330|write|$conf->global->INVOICE_CATEGORY_OF_OPERATION = 1;", "api/class/api_access.class.php:184|write|$conf->global->INVOICE_CATEGORY_OF_OPERATION = 1;", "core/modules/facture/doc/pdf_octopus.modules.php:1449|check|if (getDolGlobalInt(''INVOICE_CATEGORY_OF_OPERATION'') == 2 && $this->categoryOfOperation >= 0) {", "core/modules/facture/doc/pdf_octopus.modules.php:1877|check|if (getDolGlobalInt(''INVOICE_CATEGORY_OF_OPERATION'') == 1 && $this->categoryOfOperation >= 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CHECK_POSTERIOR_DATE', 'string', NULL, 'compta', 'Requires that a new invoice date is not earlier than the most recent existing invoice date for the same entity.', 'Set via admin/invoice.php:248 and checked in core/actions_massactions.inc.php:1050, compta/facture/class/facture.class.php:3575, and compta/facture/card.php:402. Admin UI available at admin/invoice.php.', 'Enabling this enforces chronological ordering of invoice dates, blocking validation if the new date is earlier than the last recorded invoice date.', '0 or unset = no posterior date check; truthy value = invoice date must not be before the most recent invoice date.', 0, 0, 'admin/invoice.php', 1, '9119a267dfc36f5850e336f88a31746ff8a4cce60919d30596a446b4b56c962e', 'v2', '2026-04-21T11:16:15+00:00', '["admin/invoice.php:248|write|$res = dolibarr_set_const($db, ''INVOICE_CHECK_POSTERIOR_DATE'', $check_posterior_date, ''chaine'', 0, '''', $conf->entity);", "compta/facture/class/facture.class.php:3575|check|if (getDolGlobalString(''INVOICE_CHECK_POSTERIOR_DATE'')) {", "compta/facture/card.php:402|check|if (getDolGlobalString(''INVOICE_CHECK_POSTERIOR_DATE'')) {", "core/actions_massactions.inc.php:1050|check|if (!empty($toselect) && getDolGlobalString(''INVOICE_CHECK_POSTERIOR_DATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_CREDIT_NOTE_STANDALONE', 'string', NULL, 'fourn', 'Allows creating a customer or supplier credit note that is not linked to a source invoice.', 'Checked via getDolGlobalString(''INVOICE_CREDIT_NOTE_STANDALONE'') in fourn/facture/card.php (900, 2699, 2746) and compta/facture/card.php (1355, 4393, 4446); it is force-set to 1 in master.inc.php:361 when $mysoc->country_code == ''GR'' and not already set.', 'Enabling it lifts the requirement that a credit note originate from a source invoice ($sourceinvoice), allowing standalone credit note creation; for Greek companies (country_code ''GR'') it is automatically enabled by master.inc.php if unset.', NULL, 0, 0, NULL, 1, '94fd97f223c8922b78f489980e3d076d03a9f8f274efbc0b6255ecdc601a43cc', 'v2', '2026-07-24T06:41:12+00:00', '["master.inc.php:359|read|if ($mysoc->country_code == ''GR'' && !isset($conf->global->INVOICE_CREDIT_NOTE_STANDALONE)) {", "master.inc.php:361|write|$conf->global->INVOICE_CREDIT_NOTE_STANDALONE = 1;", "fourn/facture/card.php:900|check|if (!($sourceinvoice > 0) && !getDolGlobalString(''INVOICE_CREDIT_NOTE_STANDALONE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DEFAULT_UNPAYED_SORT_ORDER', 'string', NULL, 'compta', 'Overrides the default sort order applied to the invoice list when filtering on unpaid invoices and no explicit sort order was requested.', 'Used in compta/facture/list.php:220-221: `if (!$sortorder && getDolGlobalString(''INVOICE_DEFAULT_UNPAYED_SORT_ORDER'') && $search_status == ''1'') { $sortorder = getDolGlobalString(''INVOICE_DEFAULT_UNPAYED_SORT_ORDER''); }`. Falls back to ''DESC'' if still empty.', 'When set, changes the default row order of the invoice list specifically when the status filter is ''1'' (unpaid) and the user has not explicitly chosen a sort order/column.', 'A SQL sort order string, typically ''ASC'' or ''DESC'' (consistent with the $sortorder variable and the later `if (!$sortorder) { $sortorder = ''DESC''; }` fallback).', 1, 0, NULL, 1, '988981cfe42df18b5f952be85ad6c482fbaf251616ed4b8a26666b6822015095', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/list.php:220: if (!$sortorder && getDolGlobalString(''INVOICE_DEFAULT_UNPAYED_SORT_ORDER'') && $search_status == ''1'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DEPOSIT_INVOICE_ONLY_SAME_LINES', 'string', NULL, 'compta', 'When enabled, restricts deposit invoices to include only the same lines as the source order rather than all lines.', 'Checked in compta/facture/card.php at lines 4080 and 4139 during deposit invoice creation logic.', 'Enabling this constant changes which lines are included when generating a deposit invoice from an order.', '0 or unset = deposit invoice line selection is unrestricted; truthy = only lines matching the source are included.', 1, 0, NULL, 1, 'd9e4d322fb9d08bf42e45a89e175c78de52d346427961d95fd70ed6f270e7e52', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:4080|check|if (!getDolGlobalInt(''INVOICE_DEPOSIT_INVOICE_ONLY_SAME_LINES'')) {", "compta/facture/card.php:4139|check|if (!getDolGlobalInt(''INVOICE_DEPOSIT_INVOICE_ONLY_SAME_LINES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DEPOSIT_VARIABLE_MODE_DETAIL_LINES_IN_DESCRIPTION', 'string', NULL, 'compta', 'Adds a detailed list of source lines (product/label/qty/total) inside the description of variable-mode deposit invoice lines.', 'In facture.class.php:1900, when generating a deposit invoice in variable mode, if this constant is truthy the accumulated per-VAT-rate description (built from source lines) is appended as an HTML list to the deposit line description.', 'Enabling it makes deposit invoice lines show a breakdown (<ul> of product/qty/total) of the originating lines instead of just the generic deposit wording.', 'Boolean-like flag; comment in code labels this a ''Hidden conf''.', 1, 0, NULL, 1, 'aae9b347b95700e0d3fb1610117e687793184cf6ec6a0faed8e421773f475d76', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/class/facture.class.php:1900: if (getDolGlobalString(''INVOICE_DEPOSIT_VARIABLE_MODE_DETAIL_LINES_IN_DESCRIPTION'') && !empty($descriptions[$tva])) {", "compta/facture/class/facture.class.php:1899: // Hidden conf"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DIABLE_MASS_DELETION_ON_DRAFT_INVOICES', 'string', NULL, 'compta', 'Disables the ''Delete draft'' mass action on the invoice list when set (name contains a typo: DIABLE instead of DISABLE).', 'Used in compta/facture/list.php:1490: `if ($user->hasRight(''facture'', ''supprimer'')) { if (!getDolGlobalString(''INVOICE_DIABLE_MASS_DELETION_ON_DRAFT_INVOICES'')) { $arrayofmassactions[''predeletedraft''] = ...''Deletedraft''; } }` — the mass-delete-draft option is added to the list''s mass actions menu only if the constant is falsy.', 'When enabled (truthy), users with delete rights on invoices no longer see/can use the ''Delete draft'' mass action in the invoice list, even if they otherwise have permission.', 'Boolean (getDolGlobalString truthiness): truthy removes the mass ''Delete draft'' action from the invoice list; falsy/unset keeps it available (default, subject to the facture/supprimer permission).', 1, 0, NULL, 1, '2fa1c0f7058d9ea97957b0bc8a4e319fcd90bc443027cc68646541d0ad6c30dc', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/list.php:1490: if (!getDolGlobalString(''INVOICE_DIABLE_MASS_DELETION_ON_DRAFT_INVOICES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DISABLE_AUTOMATIC_RECURRING_INVOICE', 'bool', NULL, 'fourn', 'Disables the mention/offer of automatic generation of recurring supplier or customer invoices from a template when creating an invoice from a contract.', 'Checked in fourn/facture/card.php:2370 and compta/facture/card.php:3958; when not set, an extra help text about automatic recurring invoice generation is appended to the info message shown for contract-origin invoices.', 'When set, the informational text about automatic generation of the recurring invoice (module ''Financial''/recurring templates) is suppressed on the invoice-creation-from-contract screen.', 'Bool: truthy hides the ''ToCreateARecurringInvoiceGeneAuto'' help text.', 1, 0, NULL, 1, '77dcd78613592efecda3eb2c80dab168378b9a508d72e62e266d6c52618a7e2d', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:2370|check|if (!getDolGlobalString(''INVOICE_DISABLE_AUTOMATIC_RECURRING_INVOICE'')) {", "compta/facture/card.php:3958|check|if (!getDolGlobalString(''INVOICE_DISABLE_AUTOMATIC_RECURRING_INVOICE'')) {", "fourn/facture/card.php:2371|read|$text .= '' ''.$langs->trans(\"ToCreateARecurringInvoiceGeneAuto\", $langs->transnoentitiesnoconv(''Module2300Name''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DISABLE_CREDIT_NOTE', 'bool', NULL, 'fourn', 'Hides the option to create a credit note (avoir) link when creating a new supplier/customer invoice.', 'Checked in fourn/facture/card.php:2669 and compta/facture/card.php:4359; when not set, the code fetches qualified ''avoir''/credit-note invoices for the thirdparty and offers the credit-note link.', 'When set, the ''show link for credit note'' block is skipped entirely, removing that option from the invoice creation screen.', 'Bool: truthy disables/hides the credit note creation link.', 1, 0, NULL, 1, '396e8540da106804717c4de8a5879ae1f74d84b89f39eb16ec96884ae446160e', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:2668|read|// Credit note", "fourn/facture/card.php:2669|check|if (!getDolGlobalString(''INVOICE_DISABLE_CREDIT_NOTE'')) {", "compta/facture/card.php:4359|check|if (!getDolGlobalString(''INVOICE_DISABLE_CREDIT_NOTE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DISABLE_DEPOSIT', 'bool', NULL, 'core', 'When enabled, disables the deposit invoice type, preventing its creation on both customer and supplier invoice screens.', 'Checked in compta/facture/card.php:4088, fourn/facture/card.php:2510, and core/modules/facture/mod_facture_mercure.php:120. Auto-set to 1 for Greek companies in master.inc.php:344 and via API in api/class/api_access.class.php:198.', 'Enabling this constant removes the deposit invoice option from invoice creation and numbering module logic for both customer and supplier invoices.', '0 or unset = deposit invoice type available; 1 = deposit invoice type disabled.', 1, 0, NULL, 1, 'cff9f16b242cc8d8c5f7642fcfd7fead61d0b1c39dbe57c1377f9b734a372520', 'v2', '2026-04-21T11:16:15+00:00', '["master.inc.php:344|write|$conf->global->INVOICE_DISABLE_DEPOSIT = 1;", "master.inc.php:342|read|if ($mysoc->country_code == ''GR'' && !isset($conf->global->INVOICE_DISABLE_DEPOSIT)) {", "compta/facture/card.php:4088|check|if (!getDolGlobalString(''INVOICE_DISABLE_DEPOSIT'')) {", "core/modules/facture/mod_facture_mercure.php:120|check|if (!getDolGlobalString(''INVOICE_DISABLE_DEPOSIT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DISABLE_REPLACEMENT', 'bool', NULL, 'master.inc.php', 'When enabled, disables the replacement invoice type, preventing its creation for both customer and supplier invoices.', 'Checked in admin/invoice.php:433, compta/facture/card.php:4207, core/modules/facture/mod_facture_mercure.php:113, and core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:116. Also auto-set to 1 for Greek companies and via API. Visible and configurable via admin/invoice.php (ADMIN_UI present).', 'Enabling this constant removes the replacement invoice option from the invoice creation UI and from invoice numbering module logic.', '0 or unset = replacement invoice type available; 1 = replacement invoice type disabled.', 0, 0, 'admin/invoice.php', 1, 'e17437168172b700e98b4166efd8b80efefd56a4b2ce32edc08c17f0879641dd', 'v2', '2026-04-21T11:16:15+00:00', '["master.inc.php:336|write|$conf->global->INVOICE_DISABLE_REPLACEMENT = 1;", "admin/invoice.php:433|check|if (!getDolGlobalString(''INVOICE_DISABLE_REPLACEMENT'')) {", "core/modules/facture/mod_facture_mercure.php:113|check|if (!getDolGlobalString(''INVOICE_DISABLE_REPLACEMENT'')) {", "api/class/api_access.class.php:190|write|$conf->global->INVOICE_DISABLE_REPLACEMENT = 1;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DISABLE_SOURCE', 'bool', NULL, 'compta', 'When enabled, hides the source document selector on invoice forms, preventing users from linking an invoice to a source object.', 'Checked in compta/facture/card.php at lines 4556 and 5512 to conditionally show or hide the source document field.', 'Enabling this constant removes the source document field from the invoice UI, so invoices cannot be linked to source orders or proposals.', '0 or unset = source document field shown; truthy = source document field hidden.', 1, 0, NULL, 1, '1dc6da842af60831dc1ea86fd7d66963fea203599afcbb44f63aca2d6d338698', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:4556|check|if (!getDolGlobalInt(''INVOICE_DISABLE_SOURCE'')) {", "compta/facture/card.php:5512|check|if (!getDolGlobalInt(''INVOICE_DISABLE_SOURCE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DISALLOW_REOPEN', 'bool', NULL, 'compta', 'Forcibly disables the ability to reopen a closed invoice, regardless of the user''s advanced permissions.', 'In compta/facture/card.php:167, right after computing $usercanreopen from MAIN_USE_ADVANCED_PERMS and the invoice_advance/reopen right, this constant, if truthy, forces $usercanreopen = false.', 'Enabling it removes the ''ReOpen'' action/button for all users on all invoices, overriding any per-user ''reopen'' permission.', 'Boolean-like flag (truthy = disallow reopen for everyone).', 1, 0, NULL, 1, 'b3a085cc4e580e4a0452b66d0d189a7f172e8a8cf7c154c03a891f7b5c3d0062', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/card.php:166: $usercanreopen = ((!getDolGlobalString(''MAIN_USE_ADVANCED_PERMS'') && $usercancreate) || (getDolGlobalString(''MAIN_USE_ADVANCED_PERMS'') && $user->hasRight(''facture'', ''invoice_advance'', ''reopen'')));", "compta/facture/card.php:167: if (getDolGlobalString(''INVOICE_DISALLOW_REOPEN'')) { $usercanreopen = false; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_DO_NOT_PROPAGATE_REF_CUSTOMER_OF_SRC_TO_INVOICE', 'string', NULL, 'compta', 'Prevents copying the customer reference (ref_client/ref_customer) from the source document (order/proposal/contract) onto a new invoice created from it.', 'In compta/facture/card.php:3840, when creating an invoice from a source object, if this constant is truthy $ref_client is forced to empty string; otherwise it is copied from $objectsrc->ref_client or ->ref_customer.', 'Enabling it means invoices generated from another document (order, proposal, etc.) will not inherit the customer reference of that source document.', 'Boolean-like flag (truthy = do not propagate ref_client).', 1, 0, NULL, 1, '4d3e5ee38b053daeb59b4533154c964e98e837a1ca8f0b8209c52db8ab709b3d', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/card.php:3839: // Propagate ref customer of src object to the invoice ?", "compta/facture/card.php:3840: if (getDolGlobalString(\"INVOICE_DO_NOT_PROPAGATE_REF_CUSTOMER_OF_SRC_TO_INVOICE\")) { $ref_client = \"\"; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_EMAIL_SENDER', 'string', NULL, 'core', 'Overrides the From email address when sending customer invoices or salary slips by email.', 'Checked in core/tpl/card_presend.tpl.php:185 for the ''facture'' element and line 180 for ''salary''. When set, frommail is replaced with this value (line 186).', 'Setting this causes the From address on customer invoice and salary emails to be replaced with the configured address, regardless of the user or company default.', 'Empty/not set = default sender used; email address string = used as From address for invoice and salary emails', 1, 0, NULL, 1, 'b3555eac23a146dad818214512a7e868737bb85e24c932d10b0652db7dcd0dad', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/card_presend.tpl.php:185|check|if ($object->element === ''facture'' && getDolGlobalString(''INVOICE_EMAIL_SENDER'')) {", "core/tpl/card_presend.tpl.php:180|check|if ($object->element == ''salary'' && getDolGlobalString(''INVOICE_EMAIL_SENDER'')) {", "core/tpl/card_presend.tpl.php:186|read|$formmail->frommail = getDolGlobalString(''INVOICE_EMAIL_SENDER'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_EMAIL_SENDER_NAME', 'string', NULL, 'core', 'Sets the ''From'' display name used when pre-filling the send-by-email form for salary slips and customer invoices.', 'Used in core/tpl/card_presend.tpl.php:193 (for element ''salary'', guarded by INVOICE_EMAIL_SENDER) and :198 (for element ''facture'', also guarded by INVOICE_EMAIL_SENDER) to set $formmail->fromname, with default fallback of empty string.', 'Setting it customizes the sender display name shown/used on outgoing invoice/salary emails, but only takes effect when INVOICE_EMAIL_SENDER is also set (same guard condition as the sender email itself).', 'Free-text sender display name string; defaults to '''' if unset.', 0, 0, NULL, 1, 'a2eb7b9871e4bed528a13ce9958ec457b3f9e890e91e0a03de30d36b5e45cb84', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:193|read|$formmail->fromname = getDolGlobalString(''INVOICE_EMAIL_SENDER_NAME'', '''');", "core/tpl/card_presend.tpl.php:196|if ($object->element === ''facture'' && getDolGlobalString(''INVOICE_EMAIL_SENDER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_ENABLE_NEGATIVE_QTY', 'bool', NULL, 'compta', 'When enabled, allows negative quantities to be entered on invoice lines.', 'Checked in compta/facture/card.php at lines 2567 and 3202; without this constant, a qty < 0 triggers a blocking error.', 'Disabling or leaving unset blocks negative quantities on invoice lines. Enabling it permits negative quantities, which can be used for returns or corrections.', '0 or unset = negative quantities blocked; truthy = negative quantities allowed.', 1, 0, NULL, 1, 'c32b97b90ea3b72e61f1f53e9f47e3e51eae3a1ca39294ab8f110a2a6d6f5e6c', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:2567|check|if ($qty < 0 && !getDolGlobalString(''INVOICE_ENABLE_NEGATIVE_QTY'')) {", "compta/facture/card.php:3202|check|if ($qty < 0 && !getDolGlobalString(''INVOICE_ENABLE_NEGATIVE_QTY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_FREE_TEXT', 'string', NULL, 'admin', 'Free text saved from the Invoice module admin setup and printed in the footer of customer invoice PDF/ODT documents.', 'Set via admin/invoice.php:202 (action ''set_INVOICE_FREE_TEXT'', dolibarr_set_const) and read by many invoice PDF models (e.g. pdf_sponge.modules.php:2606, pdf_octopus.modules.php:2421) and ODT generic model doc_generic_invoice_odt.modules.php:391 via pdf_pagefoot/$paramfreetext.', 'Changing the value changes the free text block printed at the bottom of generated customer invoice documents across all invoice PDF models; no effect on invoice calculation or workflow.', 'Any HTML/restricted-HTML string entered by the admin (GETPOST ''restricthtml'' filter); empty means no free text.', 0, 0, 'admin/invoice.php', 1, 'eddbed4863a4fee8adfaad63344b2782c252d09838eb229989946ec54ac77aea', 'v2', '2026-07-24T07:05:23+00:00', '["admin/invoice.php:202|write|$res = dolibarr_set_const($db, \"INVOICE_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);", "admin/invoice.php:200: $freetext = GETPOST(''INVOICE_FREE_TEXT'', ''restricthtml''); // No alpha here, we want exact string", "core/modules/facture/doc/pdf_sponge.modules.php:2606: return pdf_pagefoot($pdf, $outputlangs, ''INVOICE_FREE_TEXT'', ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_HIDE_LINKED_OBJECT', 'bool', NULL, 'admin', 'Hides the linked object section on invoice PDFs when enabled.', 'Written in admin/pdf_other.php at line 166 and displayed as a select at line 638. Checked (negated) in pdf_octopus.modules.php at line 2196 and pdf_sponge.modules.php at line 2431; the linked object block is shown only when this constant is falsy.', 'Enabling this constant removes the linked object references from invoice PDFs. Disabling it (or leaving unset) shows the linked object section.', 'Truthy string to hide linked objects; empty/unset to show linked objects.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '0b4bdb5b16761cf0688b0dde469acdfd1f545c693e541f28bc566536fb8606d7', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:166|write|dolibarr_set_const($db, \"INVOICE_HIDE_LINKED_OBJECT\", GETPOSTINT(\"INVOICE_HIDE_LINKED_OBJECT\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/facture/doc/pdf_octopus.modules.php:2196|check|if (!getDolGlobalString(''INVOICE_HIDE_LINKED_OBJECT'')) {", "core/modules/facture/doc/pdf_sponge.modules.php:2431|check|if (!getDolGlobalString(''INVOICE_HIDE_LINKED_OBJECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_HIDE_UNSELECTABLES', 'bool', NULL, 'core', 'Controls whether non-selectable invoices are hidden (vs shown disabled) in the invoice-selection dropdown for time/project entry.', 'Read in Form::selectInvoiceForTimeProject() in core/class/html.form.class.php:12393; sets local $hideunselectables = true when the constant is set.', 'Enabling it hides invoices that cannot be selected from the dropdown entirely, instead of listing them as disabled/greyed-out options.', 'Boolean: truthy value hides unselectable invoice options from the select list.', 1, 0, NULL, 1, 'ad271c8a919904528ed165aab73b4461c8050d81ea99c81e41584262c4686d0c', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:12393|check|if (getDolGlobalString(''INVOICE_HIDE_UNSELECTABLES'')) {", "$hideunselectables = true;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_INCUDE_DETAILS_OF_LOTS_SERIALS', 'string', NULL, 'compta', 'Would append lot/serial batch details (batch number and qty) to an invoice line''s description when using product batch tracking.', 'Referenced in compta/facture/card.php:2902, but this whole code block is inside a comment ("/* Disable strange code that use $lines[$i] that is not defined ... */", lines 2899-2908) — the feature is currently dead/disabled code, not executed.', 'Because the code path is commented out, setting this constant currently has no effect in this location; [SPECULATION] it may have been intended to add batch/lot details to invoice line descriptions when productbatch is enabled.', 'Boolean-like flag (usage disabled in current code).', 1, 0, NULL, 1, '06fc88256acfea1fc91bbd8f2f49c108b4287d13dd29a0c551e3764f993599e5', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/card.php:2898: if (!$error) { /* Disable strange code that use $lines[$i] that is not defined", "compta/facture/card.php:2902: if (isModEnabled(''productbatch'') && !empty($lines[$i]->detail_batch) && is_array($lines[$i]->detail_batch) && getDolGlobalString(''INVOICE_INCUDE_DETAILS_OF_LOTS_SERIALS'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_KEEP_DISCOUNT_LINES_AS_IN_ORIGIN', 'string', NULL, 'compta', 'Keeps negative-amount discount lines as-is (instead of filtering them out) when copying lines from an origin document into an invoice, order, or shipment.', 'Checked via getDolGlobalInt/getDolGlobalString(''INVOICE_KEEP_DISCOUNT_LINES_AS_IN_ORIGIN'') in compta/facture/class/facture.class.php:4743 (combined with FACTURE_ENABLE_NEGATIVE_LINES), compta/facture/card.php:2010, commande/list.php:558, and expedition/list.php:366, all guarding a check on $lines[$i]->subprice < 0.', 'Enabling it preserves lines with negative subprice (discount lines) as they were in the origin document instead of the default handling that treats subprice < 0 specially.', NULL, 0, 0, NULL, 1, '2fd650cac42b61b1794938a4bf8a42ddf2299c5a94bcbdd4b73246b7b58200bd', 'v2', '2026-07-24T06:41:12+00:00', '["compta/facture/card.php:2010|check|if ($lines[$i]->subprice < 0 && !getDolGlobalString(''INVOICE_KEEP_DISCOUNT_LINES_AS_IN_ORIGIN'')) {", "compta/facture/class/facture.class.php:4743|check|if ($this->type == self::TYPE_CREDIT_NOTE && !(getDolGlobalInt(''FACTURE_ENABLE_NEGATIVE_LINES'') && getDolGlobalInt(''INVOICE_KEEP_DISCOUNT_LINES_AS_IN_ORIGIN''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_MAX_FUTURE_DELAY', 'string', NULL, 'compta', 'Maximum number of seconds an invoice date may be in the future relative to the current time.', 'Checked in 16 locations across compta/facture/card.php, fourn/facture/card.php, compta/facture/class/facture.class.php, and compta/facture/prelevement.php. When the invoice date exceeds now + this value, validation is blocked. When the constant is not set (falsy), no future date limit is enforced (compta/facture/card.php:536). No admin UI is present.', 'Setting this value enforces a maximum allowed future date on invoices; leaving it unset disables future date validation.', 'Integer number of seconds; 0 or unset = no maximum future date limit enforced.', 1, 0, NULL, 1, 'b5d77a1f6a9449d19d01d7422a78feaa47ab4b4bebd123d46607d58c272d0e05', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:535|check|if ($newdate > (dol_now(''tzuserrel'') + getDolGlobalInt(''INVOICE_MAX_FUTURE_DELAY''))) {", "compta/facture/card.php:536|check|if (!getDolGlobalString(''INVOICE_MAX_FUTURE_DELAY'')) {", "compta/facture/class/facture.class.php:1720|check|if ($date > (dol_get_last_hour(dol_now(''tzuserrel'')) + getDolGlobalInt(''INVOICE_MAX_FUTURE_DELAY''))) {", "fourn/facture/card.php:830|read|} elseif ($dateinvoice > (dol_get_last_hour(dol_now(''tzuserrel'')) + getDolGlobalInt(''INVOICE_MAX_FUTURE_DELAY''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_NO_PAYMENT_DETAILS', 'string', NULL, 'core', 'Suppresses the payment details section on invoice and related PDF documents.', 'Checked across 8 occurrences in core/lib/pdf.lib.php, pdf_octopus.modules.php, pdf_sponge.modules.php, pdf_canelle.modules.php, and other module PDFs. When truthy, payment history blocks are not rendered. No admin UI write is present.', 'Enabling this removes all payment detail sections from generated invoice PDFs, including paid amounts, credit notes, and deposits.', 'Truthy string (non-empty) = hide payment details; absent/empty = show payment details when amounts exist.', 1, 0, NULL, 1, '9667abffd720b4589a8dd824c7e060c682f9b3bb73dca45b31c5e7a3f7549873', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:1054|check|if ((($deja_regle > 0 || $creditnoteamount > 0 || $depositsamount > 0) && !getDolGlobalString(''INVOICE_NO_PAYMENT_DETAILS''))", "core/modules/facture/doc/pdf_octopus.modules.php:412|check|if (!getDolGlobalString(''INVOICE_NO_PAYMENT_DETAILS'') && $nbpayments > 0) {", "core/modules/facture/doc/pdf_sponge.modules.php:345|check|if (!getDolGlobalString(''INVOICE_NO_PAYMENT_DETAILS'') && $nbpayments > 0) {", "core/modules/supplier_invoice/doc/pdf_canelle.modules.php:815|check|if (($deja_regle > 0 || $creditnoteamount > 0 || $depositsamount > 0) && !getDolGlobalString(''INVOICE_NO_PAYMENT_DETAILS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_NUMBERING_MARS_FORCE_PREFIX', 'string', NULL, 'core', 'When set, overrides the default prefix used by the Mars invoice numbering module.', 'Checked in core/modules/facture/mod_facture_mars.php:91-92. When the constant is set, $this->prefixinvoice is assigned its value, overriding the module''s default prefix.', 'Setting this forces the Mars numbering module to use the specified prefix for all new invoice numbers. Clearing it causes the module to use its built-in default prefix.', 'Any non-empty string = forced prefix for Mars invoice numbering; empty/unset = default prefix used.', 1, 0, NULL, 1, 'ac3ce622be7c1f295aff883c38b0a5498f1d8639a477c68eff56221808212c7f', 'v2', '2026-04-21T13:50:40+00:00', '["mod_facture_mars.php:91|if (getDolGlobalString(''INVOICE_NUMBERING_MARS_FORCE_PREFIX'')) {", "mod_facture_mars.php:92|$this->prefixinvoice = getDolGlobalString(''INVOICE_NUMBERING_MARS_FORCE_PREFIX'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_NUMBERING_TERRE_FORCE_PREFIX', 'string', NULL, 'core', 'When set, overrides the default prefix used by the Terre invoice numbering module.', 'Checked in core/modules/facture/mod_facture_terre.php:94-95. When the constant is set, $this->prefixinvoice is assigned its value, overriding the module''s built-in default prefix.', 'Setting this forces the Terre numbering module to use the specified prefix for all new invoice numbers. Clearing it causes the module to use its built-in default prefix.', 'Any non-empty string = forced prefix for Terre invoice numbering; empty/unset = default prefix used.', 1, 0, NULL, 1, '0f04f77c8410eeb338cd3310cf25739c55d06fbef376ef57eb9a7bb594531809', 'v2', '2026-04-21T13:50:40+00:00', '["mod_facture_terre.php:94|if (getDolGlobalString(''INVOICE_NUMBERING_TERRE_FORCE_PREFIX'')) {", "mod_facture_terre.php:95|$this->prefixinvoice = getDolGlobalString(''INVOICE_NUMBERING_TERRE_FORCE_PREFIX'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_PAYMENT_ENABLE_STRUCTURED_COMMUNICATION', 'bool', NULL, 'core', 'Enables structured communication (Belgian OGM/VCS format) on invoices and SEPA payment files.', 'Checked in bonprelevement.class.php:2465 specifically for Belgian companies (country_code == ''BE''), in core/lib/functions.lib.php:10723 for facture objects, and in PDF modules pdf_octopus and pdf_sponge at lines 1631 and 1697. No admin UI write path exists.', 'Enabling this constant activates structured payment references on invoices and in SEPA XML for Belgian entities; without it, unstructured references are used.', 'Truthy string/bool=structured communication enabled, empty/0=disabled', 1, 0, NULL, 1, 'ce5ed1fc71ec93b286ebe4a5aec1dbe2d4e8f3bb916c1548433eeecc6b3dfd85', 'v2', '2026-04-21T11:16:15+00:00', '["compta/prelevement/class/bonprelevement.class.php:2465|check|if (getDolGlobalString(''INVOICE_PAYMENT_ENABLE_STRUCTURED_COMMUNICATION'') && $mysoc->country_code == ''BE'') {", "core/lib/functions.lib.php:10723|check|if (getDolGlobalString(''INVOICE_PAYMENT_ENABLE_STRUCTURED_COMMUNICATION'') && $object->element == ''facture'') {", "core/modules/facture/doc/pdf_octopus.modules.php:1631|check|if (getDolGlobalString(''INVOICE_PAYMENT_ENABLE_STRUCTURED_COMMUNICATION'')) {", "core/modules/facture/doc/pdf_sponge.modules.php:1697|check|if (getDolGlobalString(''INVOICE_PAYMENT_ENABLE_STRUCTURED_COMMUNICATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_POINTOFTAX_DATE', 'string', NULL, 'compta', 'Enables a separate point-of-tax date field on invoice and related document forms.', 'Checked in 7 locations: compta/facture/card.php:4476 and :5494, comm/propal/card.php:2849, commande/card.php:2775, core/modules/facture/doc/pdf_octopus.modules.php:2146, pdf_sponge.modules.php:2381, and compta/facture/class/facture.class.php:372 where the field is conditionally enabled. No admin UI is present.', 'Enabling this causes a point-of-tax date field to appear on invoices, proposals, and orders, and that date is included in PDF document rendering.', '0 or unset = point-of-tax date field hidden; truthy value = field displayed and active.', 1, 0, NULL, 1, '2831287dcd5face26a38b929dcd2996d00f83ddb0a9cacc7d98d8e2328d698f8', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:4476|check|if (getDolGlobalString(''INVOICE_POINTOFTAX_DATE'')) {", "compta/facture/class/facture.class.php:372|read|''date_pointoftax'' => array(''type'' => ''date'', ''label'' => ''DatePointOfTax'', ''enabled'' => ''getDolGlobalString(\"INVOICE_POINTOFTAX_DATE\")'', ''visible'' => -1, ''position'' => 270),", "core/modules/facture/doc/pdf_octopus.modules.php:2146|check|if (getDolGlobalString(''INVOICE_POINTOFTAX_DATE'')) {", "commande/card.php:2775|check|if (getDolGlobalString(''INVOICE_POINTOFTAX_DATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_POSITIVE_CREDIT_NOTE', 'string', NULL, 'core', 'Forces credit note (type 2 invoice) amounts to be displayed as positive values in PDFs.', 'Checked across core/lib/pdf.lib.php and core/modules/facture/doc/pdf_octopus.modules.php whenever object type == 2 (credit note). 16+ occurrences across multiple invoice PDF modules. No admin UI write is present.', 'Enabling this flips sign display of credit note lines and totals to positive in PDFs; disabling it uses native negative values.', 'truthy = display credit note amounts as positive; empty/not set = use native negative amounts', 1, 0, NULL, 1, 'd68705bc18e40d229db10ef01528df779ad58e3bb95fd8d0c187f47a7d2b1eb9', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:2457|check|if (isset($object->type) && $object->type == 2 && getDolGlobalString(''INVOICE_POSITIVE_CREDIT_NOTE'')) {", "core/lib/pdf.lib.php:2500|check|if (isset($object->type) && $object->type == 2 && getDolGlobalString(''INVOICE_POSITIVE_CREDIT_NOTE'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:873|check|if (isset($object->type) && $object->type == 2 && getDolGlobalString(''INVOICE_POSITIVE_CREDIT_NOTE'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:1112|check|if ($object->type == 2 && getDolGlobalString(''INVOICE_POSITIVE_CREDIT_NOTE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_POSITIVE_CREDIT_NOTE_SCREEN', 'string', NULL, 'compta', 'When enabled, displays credit note amounts as positive values on the invoice screen and related views, inverting the usual sign display.', 'Checked in compta/facture/card.php:5795, compta/facture/card-rec.php:1806, compta/facture/prelevement.php:619, and core/tpl/objectline_view.tpl.php:117 for credit note type invoices and supplier invoices.', 'Enabling this constant changes the sign display of credit note amounts to positive across invoice, recurring invoice, direct debit, and line views.', '0 or unset = credit note amounts displayed as negative (standard); truthy = credit note amounts displayed as positive.', 1, 0, NULL, 1, '51c9f748eeece97a9e2cebd092b5188c421bb0573cad0e7632492ddeeb77eb5c', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:5795|check|if (getDolGlobalString(''INVOICE_POSITIVE_CREDIT_NOTE_SCREEN'') && $object->type == $object::TYPE_CREDIT_NOTE) {", "core/tpl/objectline_view.tpl.php:117|check|if (getDolGlobalString(''INVOICE_POSITIVE_CREDIT_NOTE_SCREEN'') && in_array($object->element, array(''facture'', ''invoice_supplier''))) {", "compta/facture/card-rec.php:1806|check|if (getDolGlobalString(''INVOICE_POSITIVE_CREDIT_NOTE_SCREEN'') && $object->type == $object::TYPE_CREDIT_NOTE) {", "compta/facture/prelevement.php:619|check|if (getDolGlobalString(''INVOICE_POSITIVE_CREDIT_NOTE_SCREEN'') && $object->type == $object::TYPE_CREDIT_NOTE) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_PRODUCTID_DEPOSIT', 'string', NULL, 'compta', 'Sets the product ID to associate with deposit invoice lines.', 'Read in 4 locations: compta/facture/class/facture.class.php:1882 (twice), compta/facture/card.php:1842, and fourn/facture/card.php:1278 (which falls back to SUPPLIER_INVOICE_PRODUCTID_DEPOSIT or this constant). Used as the fk_product parameter when inserting deposit lines. No admin UI is present.', 'Setting this to a valid product ID links deposit invoice lines to that product for accounting and reporting purposes; when unset (or 0), no product is linked.', 'Integer product ID; 0 or unset = no product linked to deposit lines.', 1, 0, NULL, 1, '08523bb7ec223eb74254d6ef2bf9925fe0fc70f988c0f5754f333fd7ead5bc4a', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/class/facture.class.php:1882|read|(!getDolGlobalString(''INVOICE_PRODUCTID_DEPOSIT'') ? 0 : $conf->global->INVOICE_PRODUCTID_DEPOSIT), // fk_product", "compta/facture/card.php:1842|read|getDolGlobalInt(''INVOICE_PRODUCTID_DEPOSIT''), // fk_product", "fourn/facture/card.php:1278|read|getDolGlobalInt(''SUPPLIER_INVOICE_PRODUCTID_DEPOSIT'', getDolGlobalInt(''INVOICE_PRODUCTID_DEPOSIT'')), // fk_product"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_REC_CAN_DISABLE_DOCUMENT_FILE_GENERATION', 'bool', NULL, 'fourn', 'Allows disabling automatic PDF/document file generation for recurring (template) invoices.', 'Checked via getDolGlobalString(''INVOICE_REC_CAN_DISABLE_DOCUMENT_FILE_GENERATION'') in fourn/facture/card-rec.php (1103, 1461) and compta/facture/card-rec.php (1491, 2073).', 'Enabling it exposes/activates a code path that lets recurring invoice document generation be turned off, on both supplier and customer recurring invoice templates.', NULL, 0, 0, NULL, 1, 'b76db56c03f7e7a731fdf02cda512db03c2a1be07c12121a09fce08f0f7383f9', 'v2', '2026-07-24T06:41:12+00:00', '["fourn/facture/card-rec.php:1103|check|if (getDolGlobalString(''INVOICE_REC_CAN_DISABLE_DOCUMENT_FILE_GENERATION'')) {", "compta/facture/card-rec.php:1491|check|if (getDolGlobalString(''INVOICE_REC_CAN_DISABLE_DOCUMENT_FILE_GENERATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_REC_DATE_TO_YES', 'string', NULL, 'core', 'Defaults the ''auto-fill date from/to'' options to Yes for recurring invoice/supplier-invoice template lines with a linked service.', 'Used in core/tpl/objectline_create.tpl.php:462, only within the branch for $object->element in (''facturerec'',''invoice_supplier_rec'') with the service module enabled: if truthy, $line->date_start_fill and $line->date_end_fill are both forced to 1 before rendering the yes/no selectors.', 'Enabling it pre-selects ''Yes'' for both the auto-fill start-date and end-date options on recurring invoice template lines, changing only the default UI selection (users can still change it via the selectyesno widgets).', 'Boolean-like: truthy sets both date_start_fill and date_end_fill defaults to 1 (Yes) on recurring invoice lines.', 0, 0, NULL, 1, 'cf507945eefd80ae712b9c83ce174072be93b41cdb06f2032ed2c79a0fbeee86', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:462|check|if (getDolGlobalString(''INVOICE_REC_DATE_TO_YES'')) {", "core/tpl/objectline_create.tpl.php:463|$line->date_start_fill = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_REC_PRICE_MAY_CHANGE', 'string', NULL, 'compta', 'Shows a selector on recurring/template invoice lines letting the user choose between always using the fixed template price or the (currently non-functional) new price.', 'In compta/facture/card-rec.php:1530-1537, if this constant is truthy, a <select name="usenewprice"> is rendered with ''AlwaysUseFixedPrice'' enabled and ''AlwaysUseNewPrice'' present but disabled.', 'Enabling it displays the price-mode selector on recurring invoice template lines, though the ''use new price'' option is rendered disabled in the current UI.', 'Boolean-like flag; select options are 0=AlwaysUseFixedPrice (selectable), 1=AlwaysUseNewPrice (disabled option).', 1, 0, NULL, 1, 'c3060ac151ce514f682fe31fcb6bcb814bb73637ac89598e1c3af06e28a86692', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/card-rec.php:1530: $flag_price_may_change = getDolGlobalString(''INVOICE_REC_PRICE_MAY_CHANGE'');", "compta/facture/card-rec.php:1534-1535: print ''<option value=\"0\">''.$langs->trans(\"AlwaysUseFixedPrice\").''</option>''; print ''<option value=\"1\" disabled>''.$langs->trans(\"AlwaysUseNewPrice\").''</option>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_RETAINED_WARRANTY_LIMITED_TO_FINAL_SITUATION', 'string', NULL, 'accountancy', 'Limits retained-warranty invoicing/accounting to only the final situation invoice rather than every situation invoice.', 'Checked via getDolGlobalString(''INVOICE_RETAINED_WARRANTY_LIMITED_TO_FINAL_SITUATION'') in accountancy/journal/cashsellsjournal.php:345, accountancy/journal/sellsjournal.php:351 (both alongside INVOICE_USE_RETAINED_WARRANTY), and compta/facture/class/facture.class.php (6018, 6055) guarded by isSituationInvoice(). A TODO comment notes there is no dedicated invoice flag to store this config.', 'Enabling it changes retained-warranty journal/accounting logic so it only applies to the final situation invoice, per the isSituationInvoice() checks in facture.class.php.', NULL, 0, 0, NULL, 1, '74426f82249077ffae657c9879fc37c9d56971062c2add4a63713af730005247', 'v2', '2026-07-24T06:41:12+00:00', '["compta/facture/class/facture.class.php:6010  // TODO : add a flag on invoices to store this conf : INVOICE_RETAINED_WARRANTY_LIMITED_TO_FINAL_SITUATION", "compta/facture/class/facture.class.php:6018|check|if ($this->isSituationInvoice() && getDolGlobalString(''INVOICE_RETAINED_WARRANTY_LIMITED_TO_FINAL_SITUATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SHOW_ALSO_LOCALTAX1_LINE_IF_ZERO', 'bool', NULL, 'core', 'Forces display of the local tax 1 line in PDF invoice tax summaries even when the tax amount is zero.', 'Checked at core/lib/pdf.lib.php:823 and :957; when truthy, a local tax 1 summary line is rendered even if the tax key amount is zero. No admin UI write is present.', 'Enabling this ensures local tax 1 always appears in the tax breakdown table on invoices, even for zero-amount entries.', 'Truthy string (non-empty) = always show local tax 1 line; absent/empty = only show when tax amount is non-zero.', 1, 0, NULL, 1, '4033d809eec3b1413872f11bc6ed7cec6a72101d00e058169a86beb57215698e', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:823|check|if ($tvakey != 0 || getDolGlobalString(''INVOICE_SHOW_ALSO_LOCALTAX1_LINE_IF_ZERO'')) {", "core/lib/pdf.lib.php:957|check|if ($tvakey != 0 || getDolGlobalString(''INVOICE_SHOW_ALSO_LOCALTAX1_LINE_IF_ZERO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SHOW_ALSO_LOCALTAX2_LINE_IF_ZERO', 'bool', NULL, 'core', 'Forces display of the local tax 2 line in PDF invoice tax summaries even when the tax amount is zero.', 'Checked at core/lib/pdf.lib.php:861 and :995; when truthy, a local tax 2 summary line is rendered even if the tax key amount is zero. No admin UI write is present.', 'Enabling this ensures local tax 2 always appears in the tax breakdown table on invoices, even for zero-amount entries.', 'Truthy string (non-empty) = always show local tax 2 line; absent/empty = only show when tax amount is non-zero.', 1, 0, NULL, 1, 'e0d8b22c91ff78f709763fbd83cc6f1435b979a1d306dfdfdce24ada591a6d7d', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:861|check|if ($tvakey != 0 || getDolGlobalString(''INVOICE_SHOW_ALSO_LOCALTAX2_LINE_IF_ZERO'')) {", "core/lib/pdf.lib.php:995|check|if ($tvakey != 0 || getDolGlobalString(''INVOICE_SHOW_ALSO_LOCALTAX2_LINE_IF_ZERO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SHOW_ALSO_VAT_LINE_IF_ZERO', 'bool', NULL, 'core', 'Forces display of the VAT breakdown line for a 0% VAT rate on invoice PDFs, which is otherwise hidden.', 'Checked in core/lib/pdf.lib.php:918 inside the VAT breakdown loop; without it, a $tvakey of 0 (0% rate line) is skipped unless this constant is set.', 'Adds a VAT total line for the 0% rate to the PDF VAT summary table, useful to show exempt/zero-rated amounts explicitly.', 'Boolean-like (set/unset); when set, the 0% VAT line is shown alongside non-zero rate lines', 1, 0, NULL, 1, '57653c970866b235c8719754735640a78164cb716be53c5b53e2bd891e01f4be', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:918|check|if ($tvakey != 0 || getDolGlobalString(''INVOICE_SHOW_ALSO_VAT_LINE_IF_ZERO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SHOW_POS', 'bool', NULL, 'compta', 'Shows point-of-sale (POS) related fields/columns on invoices even when the cashdesk/takepos modules are not enabled.', 'Checked via getDolGlobalString/getDolGlobalInt(''INVOICE_SHOW_POS'') in core/modules/modFacture.class.php (550, 710, 725), compta/facture/list.php:264, and compta/facture/class/facture.class.php (378-380) as an OR condition alongside isModEnabled(''cashdesk'')/isModEnabled(''takepos'').', 'Enabling it makes the module_source, pos_source, and pos_print_counter invoice fields active even without the cashdesk or takepos modules enabled.', NULL, 0, 0, NULL, 1, 'fd074d1c236187ab4520524c627b09e6c8bc215ffe03cf6b4fe90892d5dd9bf1', 'v2', '2026-07-24T06:41:12+00:00', '["compta/facture/list.php:264|read|$showpos = (isModEnabled(''cashdesk'') || isModEnabled(''takepos'') || getDolGlobalInt(''INVOICE_SHOW_POS'')) ? ''1'' : ''0'';", "compta/facture/class/facture.class.php:378|read|''module_source'' => array(''type'' => ''varchar(32)'', ''label'' => ''POSModule'', ''langfile'' => ''cashdesk'', ''enabled'' => \"(isModEnabled(''cashdesk'') || isModEnabled(''takepos'') || getDolGlob"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SHOW_SHIPPING_ADDRESS', 'bool', NULL, 'admin', 'Controls whether the shipping address is printed on invoice PDFs.', 'Written in admin/pdf_other.php at lines 154 and 155 (set/del) and displayed as a select at line 514. Checked in pdf_octopus.modules.php at lines 611 and 2310 and pdf_sponge.modules.php at line 2545 via getDolGlobalInt.', 'Enabling this constant causes invoice PDFs to include the customer''s shipping address. Disabling it omits the shipping address from invoices.', 'Non-zero integer to show shipping address; 0 or unset to hide it.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, 'e6ae87fb1af16e2a2127e0d2ea8c206ae3b352129b044dea78d8255d7d7f6c9b', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:154|write|dolibarr_set_const($db, \"INVOICE_SHOW_SHIPPING_ADDRESS\", GETPOSTINT(\"INVOICE_SHOW_SHIPPING_ADDRESS\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/facture/doc/pdf_octopus.modules.php:611|check|if (getDolGlobalInt(''INVOICE_SHOW_SHIPPING_ADDRESS'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:2310|check|if (getDolGlobalInt(''INVOICE_SHOW_SHIPPING_ADDRESS'')) {", "core/modules/facture/doc/pdf_sponge.modules.php:2545|check|if (getDolGlobalInt(''INVOICE_SHOW_SHIPPING_ADDRESS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SITUATION_CAN_BE_REMOVED_EVEN_IF_NOT_LAST', 'string', NULL, 'core', 'Allows situation invoices to be deleted even when they are not the last in their billing cycle.', 'Checked (negated) at core/class/commoninvoice.class.php:776, :831, and :946 — when NOT set, situation invoices that are not last in cycle are blocked from deletion. No admin UI; hidden setting.', 'When set, situation invoices can be deleted regardless of their position in the cycle. When unset (default), only the last situation invoice in a cycle can be removed.', 'Empty = only last situation invoice in cycle can be removed; non-empty = any situation invoice can be removed', 1, 0, NULL, 1, '1d13ac25c1efb8a7f9e5802175b6b7ec80f73ca3d769f29fa62f81fb4f451aa2', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/commoninvoice.class.php:776|check|if (!getDolGlobalString(''INVOICE_SITUATION_CAN_BE_REMOVED_EVEN_IF_NOT_LAST'') && $this->situation_cycle_ref && method_exists($this, ''is_last_in_cycle'')) {", "core/class/commoninvoice.class.php:831|check|if (!getDolGlobalString(''INVOICE_SITUATION_CAN_BE_REMOVED_EVEN_IF_NOT_LAST'') && $this->situation_cycle_ref && method_exists($this, ''is_last_in_cycle'')) {", "core/class/commoninvoice.class.php:946|check|if (!getDolGlobalString(''INVOICE_SITUATION_CAN_BE_REMOVED_EVEN_IF_NOT_LAST'') && $this->situation_cycle_ref && method_exists($this, ''is_last_in_cycle'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SITUATION_CAN_FORCE_UPDATE_DESCRIPTION', 'string', NULL, 'core', 'Allows forcing the description field to be editable on situation-invoice lines even when normally locked (e.g. lines linked to a parent situation line, or subtotal lines).', 'Used in core/tpl/objectline_edit.tpl.php:201 (if !$situationinvoicelinewithparent || this constant, allow editing) and core/tpl/subtotal_edit.tpl.php:120 (directly gates editing) to override the default restriction on editing descriptions of situation-invoice lines.', 'Enabling it lets users edit the description of situation-invoice lines that are otherwise description-locked because they are tied to a parent situation line or are subtotal lines.', 'Boolean-like: truthy overrides the description-edit lock for situation-invoice lines.', 0, 0, NULL, 1, '4e642c8f15d71de3a3f27eadb0191d9ba3c5094ea1e5381acb7d7a796b5256cb', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_edit.tpl.php:201|check|if (!$situationinvoicelinewithparent || getDolGlobalString(''INVOICE_SITUATION_CAN_FORCE_UPDATE_DESCRIPTION'')) {", "core/tpl/subtotal_edit.tpl.php:120|check|if (getDolGlobalString(''INVOICE_SITUATION_CAN_FORCE_UPDATE_DESCRIPTION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SITUATION_DEFAULT_RETAINED_WARRANTY_COND_ID', 'string', NULL, 'admin', 'Sets the default payment terms/conditions record used for retained warranty on situation invoices.', 'Configured via admin/invoice_situation.php (126, 127, 129) using getSelectConditionsPaiements, and read via getDolGlobalString/getDolGlobalInt(''INVOICE_SITUATION_DEFAULT_RETAINED_WARRANTY_COND_ID'') in compta/facture/card.php (4592, 5828) to pre-fill $retained_warranty_fk_cond_reglement.', 'Changing it alters which payment-condition record ID is used by default for the retained warranty field when creating/editing situation invoices.', NULL, 0, 0, 'admin/invoice_situation.php|admin/invoice_situation.php|admin/invoice_situation.php', 1, '12b400c2e8def9ef8cf92923a502733b5e9cec0d660bd00ec54cab38c3f28b19', 'v2', '2026-07-24T06:41:12+00:00', '["compta/facture/card.php:5828|check|$retained_warranty_fk_cond_reglement = !empty($retained_warranty_fk_cond_reglement) ? $retained_warranty_fk_cond_reglement : getDolGlobalString(''INVOICE_SITUATION_DEFAULT_RETAINED_", "admin/invoice_situation.php:129|read|$item->fieldInputOverride = $form->getSelectConditionsPaiements(getDolGlobalInt(\"INVOICE_SITUATION_DEFAULT_RETAINED_WARRANTY_COND_ID\"), ''INVOICE_SITUATION_DEFAULT_RETAINED_WARRANTY"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SITUATION_DEFAULT_RETAINED_WARRANTY_PERCENT', 'string', NULL, 'compta', 'Specifies the default retained warranty percentage applied to situation invoices when no per-invoice value has been set.', 'Read in compta/facture/card.php:4503 as the fallback for $retained_warranty, and in core/modules/facture/doc/pdf_octopus.modules.php:3581 to compute the retained warranty rate for PDF generation.', 'Changing this value alters the default retained warranty rate applied to situation invoices and their PDF output.', 'Numeric percentage value (e.g. ''5'' for 5%); used as fallback when the invoice-level retained warranty is not set.', 1, 0, NULL, 1, '32aba92d2143f1636e77f8efaccd88c52cd206cab337dfc06a704a890f7cfeb0', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:4503|check|$retained_warranty_js_default = !empty($retained_warranty) ? $retained_warranty : getDolGlobalString(''INVOICE_SITUATION_DEFAULT_RETAINED_WARRANTY_PERCENT'');", "core/modules/facture/doc/pdf_octopus.modules.php:3581|read|$retainedWarrantyRate = (float) ($object->retained_warranty ? price2num($object->retained_warranty) : price2num(getDolGlobalString(''INVOICE_SITUATION_DEFAULT_RETAINED_WARRANTY_PERC"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SITUATION_USE_DGD', 'bool', NULL, 'core', 'Appends ''DGD'' (Décompte Général Définitif / definitive general statement) to the invoice reference label on the PDF when the situation invoice is the final one.', 'Checked at core/modules/facture/doc/pdf_octopus.modules.php:3553; when the invoice''s situation_final flag is true, '' - DGD'' is appended to the printed reference and force_to_zero is set.', 'Enabling it changes how the final situation invoice''s reference is labeled on the generated PDF, marking it explicitly as a DGD; the code comment notes this is a debated/optional convention.', 'Truthy: final situation invoices get ''- DGD'' appended to their PDF reference line; empty/0: no DGD suffix.', 1, 0, NULL, 1, 'c7fc3fe0939241f25241e77308e1b886f75e5285fb84e8c193177af9faf773f5', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/pdf_octopus.modules.php:3552: // TODO Discuss whether to declare a final invoice as a DGD (definitive general statement, \"decompte general definitif\") or not.", "core/modules/facture/doc/pdf_octopus.modules.php:3553: if (getDolGlobalInt(''INVOICE_SITUATION_USE_DGD'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SUBTYPE_ENABLED', 'bool', NULL, 'fourn', 'Enables an invoice subtype field/selector on customer and supplier invoices and their recurring templates.', 'Checked via getDolGlobalInt(''INVOICE_SUBTYPE_ENABLED'') in fourn/facture/card.php (928, 1097, 2776), fourn/facture/card-rec.php (958, 1237), compta/facture/card.php:4507, and compta/facture/card-rec.php (1288, 1660).', 'Enabling it activates the ''subtype'' field/input handling on invoice cards and recurring invoice templates for both customer and supplier invoices.', NULL, 0, 0, NULL, 1, 'a2d509bd55f093a4faf1755fb24022c470a236218f530d47ad1b65e15a1dc082', 'v2', '2026-07-24T06:41:12+00:00', '["fourn/facture/card.php:928|check|if (getDolGlobalInt(''INVOICE_SUBTYPE_ENABLED'') && empty(GETPOST(\"subtype\"))) {", "compta/facture/card.php:4507|check|if (getDolGlobalInt(''INVOICE_SUBTYPE_ENABLED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SUPPLIER_ADDON_NUMBER', 'string', NULL, 'core', 'Selects the numbering module (class) used to generate supplier invoice reference numbers.', 'Configured via supplier_invoice/admin/supplier_invoice.php:181 (dolibarr_set_const) and read via getDolGlobalString(''INVOICE_SUPPLIER_ADDON_NUMBER'') in fourn/class/fournisseur.facture.class.php (3036-3043, defaulting to ''mod_facture_fournisseur_cactus'') and core/modules/modSupplierInvoice.class.php (747-748).', 'Changing it switches which numbering module class is instantiated to generate the supplier invoice number, per the comment ''according to numbering module defined into constant INVOICE_SUPPLIER_ADDON_NUMBER''.', 'defaults to ''mod_facture_fournisseur_cactus'' when unset', 0, 0, 'supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplier_invoice.php', 1, '83141103ea6b032d6f0aa07dc5d369c4d7c62005e40853d1c37c13ffc9df1744', 'v2', '2026-07-24T06:41:12+00:00', '["fourn/class/fournisseur.facture.class.php:3024  *      according to numbering module defined into constant INVOICE_SUPPLIER_ADDON_NUMBER", "fourn/class/fournisseur.facture.class.php:3037|write|$conf->global->INVOICE_SUPPLIER_ADDON_NUMBER = ''mod_facture_fournisseur_cactus'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_SUPPLIER_ADDON_PDF', 'string', NULL, 'supplier_invoice', 'Selects the PDF template model used to generate supplier invoice documents.', 'Set via supplier_invoice/admin/supplier_invoice.php (write 162/165, delete 157/174) and checked via getDolGlobalString(''INVOICE_SUPPLIER_ADDON_PDF'') in supplier_invoice/admin/supplier_invoice.php:436 and fourn/class/fournisseur.facture.class.php:3320.', 'Changing it selects which PDF model class is used when generating the supplier invoice document.', NULL, 0, 0, 'supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplier_invoice.php', 1, '81eaf4c03fcfd89ab600e1a2cacf09e87534d448fd28dd28364d68b1c588c6ea', 'v2', '2026-07-24T06:41:12+00:00', '["supplier_invoice/admin/supplier_invoice.php:162|write|if (dolibarr_set_const($db, \"INVOICE_SUPPLIER_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "fourn/class/fournisseur.facture.class.php:3320|check|if (getDolGlobalString(''INVOICE_SUPPLIER_ADDON_PDF'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_USE_DEFAULT_DOCUMENT', 'bool', NULL, 'compta', 'When enabled, automatically selects the default document template for new invoices, bypassing manual template selection.', 'Checked in admin/invoice.php:654 (labeled ''Hidden conf''), compta/facture/card.php:4394, and compta/facture/card.php:4630. Admin UI is present (admin/invoice.php), though the comment labels it as hidden.', 'Enabling this constant causes the default document template to be pre-selected automatically when creating or viewing invoices.', '0 or unset = no automatic template selection; truthy = default document template is auto-selected.', 0, 0, 'admin/invoice.php', 1, 'd8ba55d144b066de78c07200340b98d85c91eaada9db7336971b3a05f38fb309', 'v2', '2026-04-21T11:16:15+00:00', '["admin/invoice.php:654|check|if (getDolGlobalString(''INVOICE_USE_DEFAULT_DOCUMENT'')) { // Hidden conf", "compta/facture/card.php:4394|check|if (getDolGlobalString(''INVOICE_USE_DEFAULT_DOCUMENT'')) { // Hidden conf", "compta/facture/card.php:4630|check|if (getDolGlobalString(''INVOICE_USE_DEFAULT_DOCUMENT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_USE_RETAINED_WARRANTY', 'bool', NULL, 'compta', 'Enables the retained warranty (retenue de garantie) feature on customer invoices and the related accounting journals.', 'Configured via accountancy/admin/defaultaccounts.php:124 and checked extensively in accountancy/journal/cashsellsjournal.php (345, 561, 979, 1271) and accountancy/journal/sellsjournal.php (351, 567, 985) to gate retained-warranty accounting entries.', 'Enabling it activates retained-warranty handling in the sells/cash-sells accounting journals; a code comment notes it is not re-checked once an invoice''s retained_warranty field was already set while the option was active.', NULL, 0, 0, 'accountancy/admin/defaultaccounts.php', 1, 'fe8973cccbdc7947ebdd7b6ee9f6847bc42be51958aba1a92afbda7c42b4072d', 'v2', '2026-07-24T06:41:12+00:00', '["compta/facture/class/facture.class.php:6012  // note : we don''t need to test INVOICE_USE_RETAINED_WARRANTY because if $this->retained_warranty is not empty it''s because it was set when this conf was active", "accountancy/admin/defaultaccounts.php:124|check|if (getDolGlobalString(''INVOICE_USE_RETAINED_WARRANTY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_USE_SITUATION', 'bool', NULL, 'compta', 'A 3-state flag controlling situation invoices: off, cumulative/legacy mode, or progressive mode.', 'Configured in admin/invoice.php:680 and checked across dozens of files including compta/journal/sellsjournal.php:207 and accountancy/customer/index.php/lines.php, comparing the value against 1 and 2.', 'Setting it to 1 uses the legacy cumulative situation-invoice calculation (noted by a TODO as producing wrong compensation values in some accountancy views), and setting it to 2 (progressive) enables an alternate PDF template per core/modules/facture/doc/pdf_octopus.modules.php:178.', '0=off, 1=cumulative/legacy, 2=progressive', 0, 0, 'admin/invoice.php', 1, '29818ae4dcd042e6b42a69c820cdfa68dc372d3ccd1ae419b8c5e78f1876870f', 'v2', '2026-07-24T06:41:12+00:00', '["admin/invoice_situation.php:72  // INVOICE_USE_SITUATION is a 3-state flag (0=off, 1=cumulative/legacy, 2=progressive), see admin/invoice.php.", "core/modules/facture/doc/pdf_octopus.modules.php:178  // If hidden option INVOICE_USE_SITUATION is set to 2, we can show the invoice situation template", "accountancy/customer/index.php:389  // TODO When INVOICE_USE_SITUATION = 1, values here are wrong. There is no compensation on bad stored amounts"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_USE_SITUATION_CREDIT_NOTE', 'bool', NULL, 'compta', 'Allows situation (progressive) invoices to be selected as source for a credit note even if they are not the last invoice in the situation cycle.', 'Used in facture.class.php:5376 (list_qualified_avoir_invoices SQL), card.php:6932 and html.formmargin.class.php:114 to gate situation-cycle-aware credit note logic. It has an admin UI toggle in admin/invoice_situation.php:86 (''UseSituationInvoicesCreditNote''), set via setAsYesNo.', 'When enabled, the query for invoices eligible for a credit note keeps situation invoices that are the max rowid per situation_cycle_ref; margin calculation logic also treats situation credit notes differently when situation_counter > 0.', 'Yes/No (admin UI setAsYesNo).', 0, 0, NULL, 1, '110e8d3b7faa6f8bda85b51b31975eed39aeaff9ed1d935028aef8e9b8eb25e3', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/class/facture.class.php:5376: if (getDolGlobalString(''INVOICE_USE_SITUATION_CREDIT_NOTE'')) {", "admin/invoice_situation.php:86: $item = $formSetup->newItem(''INVOICE_USE_SITUATION_CREDIT_NOTE'')->setAsYesNo()->nameText = $langs->trans(''UseSituationInvoicesCreditNote'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_USE_SITUATION_RETAINED_WARRANTY', 'bool', NULL, 'core', 'Legacy/retro-compatibility switch that enables retained warranty specifically for situation (progress) invoices, later superseded by INVOICE_USE_RETAINED_WARRANTY.', 'In core/modules/facture/doc/pdf_octopus.modules.php:172-175, if this is set and INVOICE_USE_RETAINED_WARRANTY is not, the constructor copies its value into INVOICE_USE_RETAINED_WARRANTY and also forces USE_RETAINED_WARRANTY_ONLY_FOR_SITUATION_FINAL=1, per the comment ''for retro compatibility ... before it was only for final situation invoice''.', 'Setting this (without INVOICE_USE_RETAINED_WARRANTY) auto-enables retained warranty behavior restricted to the final situation invoice only, for backward compatibility with older configurations.', 'Truthy triggers retro-compatibility auto-configuration of INVOICE_USE_RETAINED_WARRANTY + USE_RETAINED_WARRANTY_ONLY_FOR_SITUATION_FINAL; ignored if INVOICE_USE_RETAINED_WARRANTY is already set.', 1, 0, NULL, 1, 'cc33ad2816c1ecec1a5cdd16e61bedb559852e430143a0652d425bfb01114b7c', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/pdf_octopus.modules.php:172: // for retro compatibility", "core/modules/facture/doc/pdf_octopus.modules.php:173: if (getDolGlobalString(''INVOICE_USE_SITUATION_RETAINED_WARRANTY'') && !getDolGlobalString(''INVOICE_USE_RETAINED_WARRANTY'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:174: // before it was only for final situation invoice"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_VAT_SHOW_REVERSE_CHARGE_MENTION', 'bool', NULL, 'core', 'Prints an intra-EEC VAT reverse-charge mention on generated invoice PDFs when seller and buyer are in different EEC countries.', 'In core/modules/facture/doc/pdf_sponge.modules.php:1399 and pdf_octopus.modules.php:1383, for a French seller with a total_tva of 0, if this bool is set and the seller''s country differs from the customer''s, and both are in the EEC (isInEEC()), the PDF prints the ''VATIsNotUsedReverseChargeProcedure'' translated mention instead of the normal not-VAT-liable text.', 'Enabling it adds the reverse-charge VAT legal mention to invoice PDFs for qualifying intra-EEC cross-border sales; unset/false omits this specific mention (other VAT mentions, like the not-liable-for-VAT text, are governed by other conditions in the same block).', 'true/1 = print ''VATIsNotUsedReverseChargeProcedure'' mention on qualifying invoices; false/unset (default) = mention not printed.', 1, 0, NULL, 1, '418b587be208a9475454b179f0a75121e7b8b162a6d7e6b2729fd2676d601b69', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/pdf_sponge.modules.php:1399: elseif (getDolGlobalString(\"INVOICE_VAT_SHOW_REVERSE_CHARGE_MENTION\") && country_code != thirdparty country_code && both isInEEC()) {", "core/modules/facture/doc/pdf_sponge.modules.php:1400: MultiCell(... transnoentities(\"VATIsNotUsedReverseChargeProcedure\") ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('INVOICE_VAT_TO_USE_ON_CREDIT_NOTE_WHEN_GENERATED_FROM_REMAIN_TO_PAY', 'bool', NULL, 'compta', 'Specifies the VAT rate (or mode) to apply when generating a credit note from an invoice''s remaining amount to pay.', 'Read in compta/facture/card.php at lines 1490, 1499, and 1500. If set to ''default'', the default product VAT rate is used; if set to a positive float, that numeric rate is applied directly.', 'Setting this constant controls which VAT rate is assigned to automatically generated credit notes for remaining balances, overriding the default behavior.', '''default'' = use default product VAT rate; positive float string = use that numeric VAT rate; empty/unset = standard logic applies.', 1, 0, NULL, 1, '00875fc9b522be56264fad5febb07dd7cdebd8f32ff53e5c822c58fe7ec54bf1', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:1490|check|if (getDolGlobalString(''INVOICE_VAT_TO_USE_ON_CREDIT_NOTE_WHEN_GENERATED_FROM_REMAIN_TO_PAY'') == ''default'') {", "compta/facture/card.php:1499|read|} elseif ((float) getDolGlobalString(''INVOICE_VAT_TO_USE_ON_CREDIT_NOTE_WHEN_GENERATED_FROM_REMAIN_TO_PAY'') > 0) {", "compta/facture/card.php:1500|read|$tva_tx = (float) getDolGlobalString(''INVOICE_VAT_TO_USE_ON_CREDIT_NOTE_WHEN_GENERATED_FROM_REMAIN_TO_PAY'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('JOB_ADDON_PDF', 'string', NULL, 'hrm', 'Name of the PDF document model (template) used to generate PDFs for HRM job-profile objects.', 'Used as fallback model name in Job''s document-generation method when $this->model_pdf is empty, hrm/class/job.class.php:977-978, same pattern as SKILL_ADDON_PDF.', 'Changing it selects which PDF generation model class is used to build the job-profile PDF document.', 'Name of a job-profile PDF doc-generation model.', 1, 0, NULL, 1, '204d3a574822b7c2b7bc1bfa4024d616ae4aacad2beee23b398b46a86ada7f0a', 'v2', '2026-07-24T07:05:23+00:00', '["hrm/class/job.class.php:977|read|} elseif (getDolGlobalString(''JOB_ADDON_PDF'')) {", "hrm/class/job.class.php:978|read|$modele = getDolGlobalString(''JOB_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('KNOWLEDGEMANAGEMENT_KNOWLEDGERECORD_ADDON', 'string', NULL, 'knowledgemanagement', 'Specifies the numbering module class name used to generate references for knowledge records.', 'Defaults to ''mod_knowledgerecord_standard'' if not set, as shown in admin/knowledgemanagement.php:73 and knowledgemanagement/class/knowledgerecord.class.php:1040. The value is used to load the corresponding PHP class file at knowledgemanagement/class/knowledgerecord.class.php:1046. Configurable via the admin UI at admin/knowledgemanagement.php.', 'Changing this value selects a different numbering/reference-generation module for knowledge records; an invalid class name will cause the reference generation to fail.', 'String: name of a module class (e.g., ''mod_knowledgerecord_standard''). Defaults to ''mod_knowledgerecord_standard'' when empty.', 0, 0, 'admin/knowledgemanagement.php|admin/knowledgemanagement.php', 1, 'e56de9e90a2955c72225c0d17c0ef40bd575e8de707ed9861df90620318cfa98', 'v2', '2026-04-21T11:16:15+00:00', '["admin/knowledgemanagement.php:73|write|$conf->global->KNOWLEDGEMANAGEMENT_KNOWLEDGERECORD_ADDON = ''mod_knowledgerecord_standard'';", "knowledgemanagement/class/knowledgerecord.class.php:1046|read|$file = getDolGlobalString(''KNOWLEDGEMANAGEMENT_KNOWLEDGERECORD_ADDON'') . \".php\";", "knowledgemanagement/class/knowledgerecord.class.php:1040|write|$conf->global->KNOWLEDGEMANAGEMENT_KNOWLEDGERECORD_ADDON = ''mod_knowledgerecord_standard'';", "knowledgemanagement/class/knowledgerecord.class.php:1047|read|$classname = getDolGlobalString(''KNOWLEDGEMANAGEMENT_KNOWLEDGERECORD_ADDON'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('KNOWLEDGEMANAGEMENT_KNOWLEDGERECORD_ADVANCED_MASK', 'string', NULL, 'knowledgemanagement', 'Numbering mask pattern used by the ''advanced'' ref generator for KnowledgeRecord objects.', 'Read in knowledgemanagement/core/modules/knowledgemanagement/mod_knowledgerecord_advanced.php:141 to build the next reference, and shown/edited as a text input on the numbering module''s own config screen (line 88), not a dedicated admin/*.php page.', 'Changing it changes the format of newly generated KnowledgeRecord references.', 'Free-form mask string consumed by the module''s own mask-parsing logic (no fixed enum given in the payload).', 0, 0, NULL, 1, '4c598a9e30e35c573108bb5cbf3f8bb9b13a5d88d0b6393cfd025500aa8f37f0', 'v2', '2026-07-24T07:05:23+00:00', '["knowledgemanagement/core/modules/knowledgemanagement/mod_knowledgerecord_advanced.php:141: $mask = getDolGlobalString(''KNOWLEDGEMANAGEMENT_KNOWLEDGERECORD_ADVANCED_MASK'');", "knowledgemanagement/core/modules/knowledgemanagement/mod_knowledgerecord_advanced.php:88: value=''...getDolGlobalString(''KNOWLEDGEMANAGEMENT_KNOWLEDGERECORD_ADVANCED_MASK'')...''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('KNOWLEDGERECORD_ADDON_PDF', 'string', NULL, 'knowledgemanagement', 'Name of the PDF document template (model) used to generate KnowledgeRecord documents.', 'Read in knowledgemanagement/class/knowledgerecord.class.php:1124-1125 as a fallback model name when generating the PDF for a KnowledgeRecord object.', 'Setting it selects which PDF template class is used to generate KnowledgeRecord documents.', 'String matching the name of an installed KnowledgeRecord PDF model/template.', 0, 0, NULL, 1, 'd6f5d78c3652af76d1ba9d5e816cf438712aa2515aa0aa41e176ec7dd5b88fa3', 'v2', '2026-07-24T07:05:23+00:00', '["knowledgemanagement/class/knowledgerecord.class.php:1124: } elseif (getDolGlobalString(''KNOWLEDGERECORD_ADDON_PDF'')) {", "knowledgemanagement/class/knowledgerecord.class.php:1125: $modele = getDolGlobalString(''KNOWLEDGERECORD_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_ADMIN_DN', 'string', NULL, 'admin', 'Specifies the Distinguished Name (DN) of the LDAP administrator account used to bind and search the directory.', 'Assigned to $ldap->searchUser in core/class/ldap.class.php and used alongside LDAP_ADMIN_PASS to perform authenticated LDAP binds. Displayed in bind success/failure messages in admin/ldap.php. Configurable via the admin UI at admin/ldap.php.', 'Changing this value alters the account used for LDAP authentication; an incorrect DN will cause bind failures and prevent directory synchronization.', 'A valid LDAP DN string for the admin/bind account, e.g. ''cn=admin,dc=example,dc=com''.', 0, 0, 'admin/ldap.php|admin/ldap.php|admin/ldap.php|admin/ldap.php|admin/ldap.php', 1, '2f7d4649ed2bc371c27928d97c8605e796ff38e348835b4af4838e8176338a87', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/ldap.class.php:288|read|$this->searchUser = getDolGlobalString(''LDAP_ADMIN_DN'');", "admin/ldap.php:298|check|if (getDolGlobalString(''LDAP_ADMIN_DN'') && getDolGlobalString(''LDAP_ADMIN_PASS'')) {", "admin/ldap.php:259|read|print ''<input class=\"minwidth300\" type=\"text\" name=\"admin\" value=\"''.getDolGlobalString(''LDAP_ADMIN_DN'').''\">'';", "admin/ldap.php:95|write|if (!dolibarr_set_const($db, ''LDAP_ADMIN_DN'', GETPOST(\"admin\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_ADMIN_PASS', 'string', NULL, 'admin', 'Stores the password for the LDAP administrator account used to bind to the directory.', 'Assigned to $ldap->searchPassword in core/class/ldap.class.php and used together with LDAP_ADMIN_DN to perform authenticated LDAP binds. Rendered as a password input in admin/ldap.php. Configurable via the admin UI at admin/ldap.php.', 'Changing this value alters the credential used for LDAP authentication; an incorrect password will cause bind failures and prevent directory synchronization.', 'A string containing the LDAP admin account password.', 0, 0, 'admin/ldap.php|admin/ldap.php|admin/ldap.php|admin/ldap.php|admin/ldap.php|admin/ldap.php', 1, '14d2843504691455c58896ebe63eca2c758276e05fd63f8f09c61a94ab6b5943', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/ldap.class.php:289|read|$this->searchPassword = getDolGlobalString(''LDAP_ADMIN_PASS'');", "admin/ldap.php:298|check|if (getDolGlobalString(''LDAP_ADMIN_DN'') && getDolGlobalString(''LDAP_ADMIN_PASS'')) {", "admin/ldap.php:265|read|print ''<input class=\"minwidth150\" type=\"password\" name=\"pass\" value=\"''.dol_escape_htmltag(getDolGlobalString(''LDAP_ADMIN_PASS'')).''\">'';", "admin/ldap.php:98|write|if (!dolibarr_set_const($db, ''LDAP_ADMIN_PASS'', GETPOST(\"pass\", ''none''), ''chaine'', 0, '''', $conf->entity)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_CONTACT_ACTIVE', 'string', NULL, 'core', 'Determines the active LDAP synchronisation direction for contacts (Dolibarr-to-LDAP, LDAP-to-Dolibarr, or disabled).', 'Set via admin/ldap.php:107 using a radio-button selector (line 176) and checked in core/triggers/interface_50_modLdap_Ldapsynchro.class.php:375, 394, 429 to gate contact synchronisation trigger logic. Also used in contact/ldap.php:151, 157 and core/lib/ldap.lib.php:62.', 'Changing this value enables, disables, or reverses the LDAP synchronisation direction for contacts, affecting whether contact changes are pushed to or pulled from LDAP.', 'One of the Ldap::SYNCHRO_* constants; empty/unset = synchronisation disabled.', 0, 0, 'admin/ldap.php|admin/ldap.php', 1, '1c11038df685a9be5fdb1e5ecfecd7635ee909d73293da20e3f5e17f289c97df', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap.php:107|write|if (!dolibarr_set_const($db, ''LDAP_CONTACT_ACTIVE'', GETPOST(\"activecontact\", ''aZ09''), ''chaine'', 0, '''', $conf->entity)) {", "admin/ldap.php:176|read|print $formldap->selectLdapDnSynchroActive(getDolGlobalInt(''LDAP_CONTACT_ACTIVE''), ''activecontact'', array(Ldap::SYNCHRO_LDAP_TO_DOLIBARR));", "core/triggers/interface_50_modLdap_Ldapsynchro.class.php:375|check|if (getDolGlobalString(''LDAP_CONTACT_ACTIVE'')) {", "contact/ldap.php:151|check|if (getDolGlobalString(''LDAP_CONTACT_ACTIVE'') && getDolGlobalInt(''LDAP_CONTACT_ACTIVE'') != Ldap::SYNCHRO_LDAP_TO_DOLIBARR) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_CONTACT_DN', 'string', NULL, 'contact', 'Defines the LDAP Distinguished Name (DN) base path under which contact entries are stored.', 'Set via admin/ldap_contacts.php:63 and read at lines 168, 299, and in contact/class/contact.class.php:806–808 to construct the DN for LDAP contact operations. Also displayed in contact/ldap.php:129.', 'Changing this value redirects all LDAP contact read and write operations to a different branch of the LDAP directory tree.', 'A valid LDAP DN string, e.g. ''ou=contacts,dc=example,dc=com''.', 0, 0, 'admin/ldap_contacts.php|admin/ldap_contacts.php|admin/ldap_contacts.php', 1, '54381ab59f57a77d444d7b870872e34f353caf97db099d04c163540717f8665d', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_contacts.php:63|write|if (!dolibarr_set_const($db, ''LDAP_CONTACT_DN'', GETPOST(\"contactdn\"), ''chaine'', 0, '''', $conf->entity)) {", "admin/ldap_contacts.php:168|read|print ''<input size=\"48\" type=\"text\" name=\"contactdn\" value=\"'' . getDolGlobalString(''LDAP_CONTACT_DN'').''\">'';", "contact/class/contact.class.php:806|read|$dn = getDolGlobalString(''LDAP_KEY_CONTACTS'') . \"=\".$info[getDolGlobalString(''LDAP_KEY_CONTACTS'')].\",.\" . getDolGlobalString(''LDAP_CONTACT_DN'');", "contact/ldap.php:129|read|print ''<tr><td>LDAP ''.$langs->trans(\"LDAPContactDn\").''</td><td class=\"valeur\" colspan=\"3\">''.getDolGlobalString(''LDAP_CONTACT_DN'').\"</td></tr>\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_CONTACT_FIELD_ADDRESS', 'string', NULL, 'admin', 'Maps the Dolibarr contact address to the corresponding LDAP attribute name for synchronisation.', 'Set via admin/ldap_contacts.php:97 and displayed at line 256; used in contact/class/contact.class.php:864–865 where the contact''s address is conditionally written to the LDAP entry under this attribute.', 'Changing this value changes which LDAP attribute receives the contact''s address during synchronisation.', 'Any valid LDAP attribute name string, e.g. ''street''.', 0, 0, 'admin/ldap_contacts.php|admin/ldap_contacts.php|admin/ldap_contacts.php', 1, 'bff43f04d6c107c97f132c3e838eddfe4ea6c5aab8f4c8323a515e2bf174469a', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_contacts.php:97|write|if (!dolibarr_set_const($db, ''LDAP_CONTACT_FIELD_ADDRESS'', GETPOST(\"fieldaddress\"), ''chaine'', 0, '''', $conf->entity)) {", "contact/class/contact.class.php:864|check|if ($this->address && getDolGlobalString(''LDAP_CONTACT_FIELD_ADDRESS'')) {", "contact/class/contact.class.php:865|read|$info[getDolGlobalString(''LDAP_CONTACT_FIELD_ADDRESS'')] = $this->address;", "admin/ldap_contacts.php:256|read|print ''<input size=\"25\" type=\"text\" name=\"fieldaddress\" value=\"'' . getDolGlobalString(''LDAP_CONTACT_FIELD_ADDRESS'').''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_CONTACT_FIELD_COMPANY', 'string', NULL, 'admin', 'Maps the Dolibarr contact''s associated company name to the corresponding LDAP attribute name for synchronisation.', 'Set via admin/ldap_contacts.php:79 and displayed at line 214; consumed in contact/class/contact.class.php:853 where the associated thirdparty name is written to the LDAP entry under this attribute.', 'Changing this value changes which LDAP attribute receives the contact''s company name during synchronisation.', 'Any valid LDAP attribute name string, e.g. ''o''.', 0, 0, 'admin/ldap_contacts.php|admin/ldap_contacts.php|admin/ldap_contacts.php', 1, 'a44b2e5550383e7e742402668a469216ab9e066c851da3e9e14babf110656dd3', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_contacts.php:79|write|if (!dolibarr_set_const($db, ''LDAP_CONTACT_FIELD_COMPANY'', GETPOST(\"fieldcompany\"), ''chaine'', 0, '''', $conf->entity)) {", "contact/class/contact.class.php:853|read|$info[getDolGlobalString(''LDAP_CONTACT_FIELD_COMPANY'')] = $soc->name;", "admin/ldap_contacts.php:214|read|print ''<input size=\"25\" type=\"text\" name=\"fieldcompany\" value=\"'' . getDolGlobalString(''LDAP_CONTACT_FIELD_COMPANY'').''\">'';", "admin/ldap_contacts.php:216|read|print ''<td class=\"right\"><input type=\"radio\" name=\"key\" value=\"LDAP_CONTACT_FIELD_COMPANY\"''.(getDolGlobalString(''LDAP_KEY_CONTACTS'') && getDolGlobalString(''LDAP_KEY_CONTACTS'') == g"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_CONTACT_FIELD_COUNTRY', 'string', NULL, 'admin', 'Maps the Dolibarr contact country code to the corresponding LDAP attribute name for synchronisation.', 'Set via admin/ldap_contacts.php:106 and displayed at line 277; used in contact/class/contact.class.php:873–874 where the contact''s country_code is conditionally written to the LDAP entry under this attribute.', 'Changing this value changes which LDAP attribute receives the contact''s country code during synchronisation.', 'Any valid LDAP attribute name string, e.g. ''c''.', 0, 0, 'admin/ldap_contacts.php|admin/ldap_contacts.php|admin/ldap_contacts.php', 1, 'd68d38fd0238d6bcdea7ebf65d6dfcb8179e74a973a472a1d9cc015b602b02cf', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_contacts.php:106|write|if (!dolibarr_set_const($db, ''LDAP_CONTACT_FIELD_COUNTRY'', GETPOST(\"fieldcountry\"), ''chaine'', 0, '''', $conf->entity)) {", "contact/class/contact.class.php:873|check|if ($this->country_code && getDolGlobalString(''LDAP_CONTACT_FIELD_COUNTRY'')) {", "contact/class/contact.class.php:874|read|$info[getDolGlobalString(''LDAP_CONTACT_FIELD_COUNTRY'')] = $this->country_code;", "admin/ldap_contacts.php:277|read|print ''<input size=\"25\" type=\"text\" name=\"fieldcountry\" value=\"'' . getDolGlobalString(''LDAP_CONTACT_FIELD_COUNTRY'').''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_CONTACT_FIELD_DESCRIPTION', 'string', NULL, 'contact', 'Name of the LDAP attribute to map the contact''s private note (description) to when syncing a Dolibarr contact to LDAP.', 'Read in contact/class/contact.class.php:888-889: `if ($this->note_private && getDolGlobalString(''LDAP_CONTACT_FIELD_DESCRIPTION'')) { $info[getDolGlobalString(''LDAP_CONTACT_FIELD_DESCRIPTION'')] = dol_string_nohtmltag($this->note_private, 2); }`, following the same LDAP_CONTACT_FIELD_* pattern as FULLNAME/NAME/PHONE/MAIL etc. Unlike those siblings, admin/ldap_contacts.php does not expose an input field for this specific constant (checked: no fielddescription entry in that admin page).', 'When set to an LDAP attribute name, the contact''s private note is exported to that attribute during LDAP synchronization; since there is no admin form field for it, it must be set through some other means (direct constant edit) rather than the LDAP contacts setup page.', 'Free-text string naming an LDAP attribute (e.g. ''description''), used as the array key for $this->note_private in the LDAP info array; no effect if empty/unset.', 1, 0, NULL, 1, '25da5d9eb1d92ab1b57cac1553f3df809065c127d955dcc900731a15e464d9ad', 'v2', '2026-07-24T07:05:23+00:00', '["contact/class/contact.class.php:888|check|if ($this->note_private && getDolGlobalString(''LDAP_CONTACT_FIELD_DESCRIPTION'')) {", "contact/class/contact.class.php:889|read|$info[getDolGlobalString(''LDAP_CONTACT_FIELD_DESCRIPTION'')] = dol_string_nohtmltag($this->note_private, 2);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_CONTACT_FIELD_FAX', 'string', NULL, 'admin', 'Maps the Dolibarr contact fax number to the corresponding LDAP attribute name for synchronisation.', 'Set via admin/ldap_contacts.php:94 and displayed at line 249; used in contact/class/contact.class.php:885–886 where the contact''s fax is conditionally written to the LDAP entry under this attribute.', 'Changing this value changes which LDAP attribute receives the contact''s fax number during synchronisation.', 'Any valid LDAP attribute name string, e.g. ''facsimileTelephoneNumber''.', 0, 0, 'admin/ldap_contacts.php|admin/ldap_contacts.php|admin/ldap_contacts.php', 1, '50fa0021c17beb793acf162b75e3f4466189cfce108e9748d34a1d8d8fb59b5b', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_contacts.php:94|write|if (!dolibarr_set_const($db, ''LDAP_CONTACT_FIELD_FAX'', GETPOST(\"fieldfax\"), ''chaine'', 0, '''', $conf->entity)) {", "contact/class/contact.class.php:885|check|if ($this->fax && getDolGlobalString(''LDAP_CONTACT_FIELD_FAX'')) {", "contact/class/contact.class.php:886|read|$info[getDolGlobalString(''LDAP_CONTACT_FIELD_FAX'')] = $this->fax;", "admin/ldap_contacts.php:249|read|print ''<input size=\"25\" type=\"text\" name=\"fieldfax\" value=\"'' . getDolGlobalString(''LDAP_CONTACT_FIELD_FAX'').''\">'';"]', 'high', NULL);
