INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_DESCRIPTION', 'string', NULL, 'adherents', 'Maps the member private note to its corresponding LDAP attribute name.', 'When set, the member''s note_private value (stripped of HTML) is written to the LDAP attribute named by this constant during sync. Configured via admin/ldap_members.php.', 'Setting this enables the private note to be synchronised to LDAP as a description. Leaving it empty suppresses this field from LDAP sync.', 'LDAP attribute name string, e.g. ''description''', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, '82d97538b8001c53bd4d9fdbbfdcf171b86dfb5fc0ca2163ea1c1655722182c6', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members.php:125|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_DESCRIPTION'', GETPOST(\"fielddescription\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:3040|check|if ($this->note_private && getDolGlobalString(''LDAP_MEMBER_FIELD_DESCRIPTION'')) {", "adherents/class/adherent.class.php:3041|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_DESCRIPTION'')] = dol_string_nohtmltag($this->note_private, 2);"]', 'medium', NULL);
