INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_NAME', 'string', NULL, 'admin', 'Specifies the LDAP attribute name mapped to the member''s last name during LDAP synchronization.', 'Written at admin/ldap_members.php:89 via dolibarr_set_const and displayed in a text input at :255; also used as a candidate key option for LDAP_KEY_MEMBERS at :257. Configurable through the admin UI.', 'Changing this value remaps the LDAP attribute used for the member''s last name; an incorrect attribute will cause sync failures.', 'Any valid LDAP attribute name string; empty = no mapping for last name.', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php|admin/ldap_members.php', 1, '9d7bc54213f962ee4812d72bb20cc61aaccc2253fa045df790d0add8a1a4db98', 'v2', '2026-04-21T13:50:40+00:00', '["admin/ldap_members.php:89|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_NAME'', GETPOST(\"fieldname\"), ''chaine'', 0, '''', $conf->entity)) {", "admin/ldap_members.php:255|read|print ''<input size=\"25\" type=\"text\" name=\"fieldname\" value=\"'' . getDolGlobalString(''LDAP_MEMBER_FIELD_NAME'').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_NOTE_PUBLIC', 'string', NULL, 'adherents', 'Maps the member public note to its corresponding LDAP attribute name.', 'When set, the member''s note_public value (stripped of HTML) is written to the LDAP attribute named by this constant during sync. Configured via admin/ldap_members.php.', 'Setting this enables the public note to be synchronised to LDAP. Leaving it empty suppresses this field from LDAP sync.', 'LDAP attribute name string', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, '6273eac49ab7a6d186c171989280cf883f65ecd532decb7a23d0768faf780bb6', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members.php:128|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_NOTE_PUBLIC'', GETPOST(\"fieldnotepublic\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:3043|check|if ($this->note_public && getDolGlobalString(''LDAP_MEMBER_FIELD_NOTE_PUBLIC'')) {", "adherents/class/adherent.class.php:3044|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_NOTE_PUBLIC'')] = dol_string_nohtmltag($this->note_public, 2);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_PASSWORD', 'string', NULL, 'adherents', 'Maps the member''s unencrypted password to its corresponding LDAP attribute name.', 'When set, the member''s plain-text password (pass or pass_indatabase) is written to the LDAP attribute named by this constant during sync. Configured via admin/ldap_members.php.', 'Setting this causes the unencrypted password to be stored in the named LDAP attribute on sync. This should only be used when the LDAP server itself handles hashing.', 'LDAP attribute name string', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, '163548f38e1aae83b2c5ff02f21ab3d9d81eba6a0aa9f2dedccd23245afb9759', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/class/adherent.class.php:3079|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_PASSWORD'')] = $this->pass_indatabase; // $this->pass_indatabase = Unencrypted password", "adherents/class/adherent.class.php:3059|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_PASSWORD'')] = $this->pass; // this->pass = Unencrypted password", "admin/ldap_members.php:83|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_PASSWORD'', GETPOST(\"fieldpassword\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:3058|check|if (getDolGlobalString(''LDAP_MEMBER_FIELD_PASSWORD'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_PASSWORD_CRYPTED', 'string', NULL, 'adherents', 'Maps the member''s crypted password to its corresponding LDAP attribute name.', 'When set, the member''s hashed password is written to the LDAP attribute named by this constant during sync, using OpenLDAP password hash format. Configured via admin/ldap_members.php.', 'Setting this enables synchronisation of a hashed password to LDAP using the dol_hash openldap scheme. Leaving it empty suppresses crypted password sync.', 'LDAP attribute name string, e.g. ''userPassword''', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, 'd32272fb4c4e10f05ede035d4f6effc571c08e5813ac554cc0f375361647bbd9', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/class/adherent.class.php:3062|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_PASSWORD_CRYPTED'')] = dol_hash($this->pass, ''openldap''); // Create OpenLDAP password (see LDAP_PASSWORD_HASH_TYPE)", "adherents/class/adherent.class.php:3073|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_PASSWORD_CRYPTED'')] = dolGetLdapPasswordHash($this->pass_indatabase_crypted, ''md5frommd5'');", "admin/ldap_members.php:86|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_PASSWORD_CRYPTED'', GETPOST(\"fieldpasswordcrypted\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:3061|check|if (getDolGlobalString(''LDAP_MEMBER_FIELD_PASSWORD_CRYPTED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_PHONE', 'string', NULL, 'adherents', 'Maps the member office phone number to its corresponding LDAP attribute name.', 'When set, the member''s phone value is written to the LDAP attribute named by this constant during sync. Configured via admin/ldap_members.php.', 'Setting this enables the office phone number to be synchronised to LDAP. Leaving it empty suppresses phone sync.', 'LDAP attribute name string, e.g. ''telephoneNumber''', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, 'd5705a158904f2a4306dc6006f2294ca002d1dba262fb88e2b30884441e9366b', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members.php:98|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_PHONE'', GETPOST(\"fieldphone\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:3028|check|if ($this->phone && getDolGlobalString(''LDAP_MEMBER_FIELD_PHONE'')) {", "adherents/class/adherent.class.php:3029|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_PHONE'')] = $this->phone;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_PHONE_PERSO', 'string', NULL, 'adherents', 'Maps the member personal phone number to its corresponding LDAP attribute name.', 'When set, the member''s phone_perso value is written to the LDAP attribute named by this constant during sync. Configured via admin/ldap_members.php.', 'Setting this enables the personal phone number to be synchronised to LDAP. Leaving it empty suppresses personal phone sync.', 'LDAP attribute name string, e.g. ''homePhone''', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, '6036db1ad24ecd8b825d102cfbcbdd87b2014eed1a20d456b3de2cccfc4a19b4', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members.php:101|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_PHONE_PERSO'', GETPOST(\"fieldphoneperso\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:3031|check|if ($this->phone_perso && getDolGlobalString(''LDAP_MEMBER_FIELD_PHONE_PERSO'')) {", "adherents/class/adherent.class.php:3032|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_PHONE_PERSO'')] = $this->phone_perso;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_TITLE', 'string', NULL, 'adherents', 'Maps the member''s job title (''poste'') field to a specific LDAP attribute name during LDAP synchronization.', 'In adherents/class/adherent.class.php:3012-3013, if the member has a poste value and this constant is set, the LDAP attribute named by this constant''s value is populated with $this->poste in the $info array sent to LDAP; it is one of several LDAP_MEMBER_FIELD_* mapping constants (FIRSTNAME, COMPANY, ADDRESS, ZIP, TOWN, COUNTRY, PHONE, and dynamic social-network fields) seen in the same function.', 'Setting it to an LDAP attribute name (e.g. ''title'') causes the member''s job title to be synced to that LDAP attribute; leaving it unset means the title is not synced to LDAP at all.', 'String: name of the target LDAP attribute to receive the member''s job title.', 1, 0, NULL, 1, '58c62134fd5b7b3c8ddc868f8ff6a63d526740f390718c906536f788e041f11c', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/class/adherent.class.php:3012|check|if ($this->poste && getDolGlobalString(''LDAP_MEMBER_FIELD_TITLE'')) {", "adherents/class/adherent.class.php:3013|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_TITLE'')] = $this->poste;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_TOWN', 'string', NULL, 'adherents', 'Maps the member town/city to its corresponding LDAP attribute name.', 'When set, the member''s town value is written to the LDAP attribute named by this constant during sync. Configured via admin/ldap_members.php.', 'Setting this enables the town field to be synchronised to LDAP. Leaving it empty suppresses town sync.', 'LDAP attribute name string, e.g. ''l''', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, 'a7c5deb2fbaf7d2fc187222071a520aed193598ff9f80f8732afd6e627dba356', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members.php:119|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_TOWN'', GETPOST(\"fieldtown\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:3017|check|if ($this->town && getDolGlobalString(''LDAP_MEMBER_FIELD_TOWN'')) {", "adherents/class/adherent.class.php:3018|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_TOWN'')] = $this->town;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FIELD_ZIP', 'string', NULL, 'adherents', 'Maps the member postal code to its corresponding LDAP attribute name.', 'When set, the member''s zip/postal code value is written to the LDAP attribute named by this constant during sync. Configured via admin/ldap_members.php.', 'Setting this enables the postal code to be synchronised to LDAP. Leaving it empty suppresses zip code sync.', 'LDAP attribute name string, e.g. ''postalCode''', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, '572fd26408563a6ae600551d6f88f4f7f539bda6f1ec21c6f674bd3357a5f2f3', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members.php:116|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FIELD_ZIP'', GETPOST(\"fieldzip\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:3014|check|if ($this->zip && getDolGlobalString(''LDAP_MEMBER_FIELD_ZIP'')) {", "adherents/class/adherent.class.php:3015|read|$info[getDolGlobalString(''LDAP_MEMBER_FIELD_ZIP'')] = $this->zip;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_FILTER', 'string', NULL, 'admin', 'Defines the LDAP filter string applied when searching for member entries during member synchronization.', 'Written in admin/ldap_members.php:70, displayed in UI at :229. Applied in core/class/ldap.class.php:295 as $this->filtermember.', 'Changing this filter restricts which LDAP entries are matched during member import/sync. An incorrect filter can prevent member synchronization.', 'LDAP filter string (e.g. ''(objectClass=inetOrgPerson)''); empty = no additional filter applied for members', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php', 1, '250512f694ca2abae30fbbdaae6a2dc849756e55bad32cb8171a1bb829081d11', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/ldap.class.php:295|read|$this->filtermember        = getDolGlobalString(''LDAP_MEMBER_FILTER''); // Filter on member", "admin/ldap_members.php:70|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_FILTER'', GETPOST(\"filterconnection\"), ''chaine'', 0, '''', $conf->entity)) {", "admin/ldap_members.php:229|read|print ''<input size=\"48\" type=\"text\" name=\"filterconnection\" value=\"'' . getDolGlobalString(''LDAP_MEMBER_FILTER'').''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_OBJECT_CLASS', 'string', NULL, 'admin', 'Defines the LDAP objectClass value(s) assigned to member entries.', 'Holds a comma-separated string of LDAP object class names applied to member entries when they are created or updated. Used in adherents/class/adherent.class.php. Configured via admin/ldap_members.php.', 'Setting this to valid LDAP object class names ensures member entries conform to the directory schema. An incorrect value will cause LDAP write operations to fail schema validation.', 'Comma-separated LDAP object class names string', 0, 0, 'admin/ldap_members.php|admin/ldap_members.php|admin/ldap_members.php', 1, '8a8123ba3f704f756d901e3e8d0f6759f3af516737619bc50518b6ded5872166', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members.php:67|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_OBJECT_CLASS'', GETPOST(\"objectclass\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent.class.php:2970|read|$info[\"objectclass\"] = explode('','', getDolGlobalString(''LDAP_MEMBER_OBJECT_CLASS''));", "admin/ldap_members.php:451|read|$objectclass = getDolGlobalString(''LDAP_MEMBER_OBJECT_CLASS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_TYPE_ACTIVE', 'string', NULL, 'core', 'Controls the synchronization direction between Dolibarr member types and LDAP.', 'Compared against Ldap::SYNCHRO_DOLIBARR_TO_LDAP across admin/ldap_members_types.php:202 and multiple trigger points in core/triggers/interface_50_modLdap_Ldapsynchro.class.php (lines 460, 578, 696, 735, 759). Configurable via admin/ldap.php:113.', 'Changing this value enables or disables automatic push of member type changes from Dolibarr to LDAP when triggers fire.', 'Value equal to Ldap::SYNCHRO_DOLIBARR_TO_LDAP = sync from Dolibarr to LDAP enabled; other values = sync disabled.', 0, 0, 'admin/ldap_members_types.php|admin/ldap.php|admin/ldap.php', 1, '4cc2120217141f7fd759e1c39c14ccd43228b44d1b47546322aab3ecee0ef7dc', 'v2', '2026-04-21T11:16:15+00:00', '["core/triggers/interface_50_modLdap_Ldapsynchro.class.php:460|check|if (getDolGlobalString(''LDAP_MEMBER_TYPE_ACTIVE'') && getDolGlobalInt(''LDAP_MEMBER_TYPE_ACTIVE'') === Ldap::SYNCHRO_DOLIBARR_TO_LDAP) {", "admin/ldap_members_types.php:202|check|if (getDolGlobalInt(''LDAP_MEMBER_TYPE_ACTIVE'') === Ldap::SYNCHRO_DOLIBARR_TO_LDAP) {", "admin/ldap.php:113|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_TYPE_ACTIVE'', GETPOST(\"activememberstypes\", ''aZ09''), ''chaine'', 0, '''', $conf->entity)) {", "core/triggers/interface_50_modLdap_Ldapsynchro.class.php:578|check|if (getDolGlobalString(''LDAP_MEMBER_TYPE_ACTIVE'') && getDolGlobalInt(''LDAP_MEMBER_TYPE_ACTIVE'') === Ldap::SYNCHRO_DOLIBARR_TO_LDAP) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_TYPE_DN', 'string', NULL, 'admin', 'Sets the LDAP distinguished name (DN) branch under which member-type entries are stored/looked up.', 'Set via admin/ldap_members_types.php:64 (dolibarr_set_const) and read via getDolGlobalString(''LDAP_MEMBER_TYPE_DN'') in admin/ldap_members_types.php (140, 206), adherents/class/adherent_type.class.php (1159, 1162), and adherents/type_ldap.php:115.', 'Changing it alters the DN string used to build LDAP queries/entries for member types (combined with LDAP_KEY_MEMBERS_TYPES).', NULL, 0, 0, 'admin/ldap_members_types.php|admin/ldap_members_types.php|admin/ldap_members_types.php', 1, 'e3f6a747b8517d98d0636a13e097a71e8e42ee12836a49fcd3d3983b936b921b', 'v2', '2026-07-24T06:41:12+00:00', '["admin/ldap_members_types.php:64|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_TYPE_DN'', GETPOST(\"membertype\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent_type.class.php:1159|read|$dn = getDolGlobalString(''LDAP_KEY_MEMBERS_TYPES'') . \"=\".$info[getDolGlobalString(''LDAP_KEY_MEMBERS_TYPES'')].\",\" . getDolGlobalString(''LDAP_MEMBER_TYPE_DN'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_TYPE_FIELD_DESCRIPTION', 'string', NULL, 'admin', 'Specifies the LDAP attribute name used to store the description/public note of a member type.', 'Written in admin/ldap_members_types.php:74, displayed in :176 and :178, and applied in adherents/class/adherent_type.class.php:1194-1195 to map the member-type public note to the LDAP attribute.', 'Changing this value remaps which LDAP attribute receives the member-type public note during synchronization.', 'Any valid LDAP attribute name string (e.g. ''description'')', 0, 0, 'admin/ldap_members_types.php|admin/ldap_members_types.php|admin/ldap_members_types.php', 1, '397c270bd0b99b4a29635440e91e2f43abd70202502886f23f9d07b6949f5b17', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members_types.php:74|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_TYPE_FIELD_DESCRIPTION'', GETPOST(\"fielddescription\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent_type.class.php:1194|check|if ($this->note_public && getDolGlobalString(''LDAP_MEMBER_TYPE_FIELD_DESCRIPTION'')) {", "adherents/class/adherent_type.class.php:1195|read|$info[getDolGlobalString(''LDAP_MEMBER_TYPE_FIELD_DESCRIPTION'')] = dol_string_nohtmltag($this->note_public, 0, ''UTF-8'', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_TYPE_FIELD_FULLNAME', 'string', NULL, 'admin', 'Specifies the LDAP attribute name used to store the full name of a member type.', 'Written in admin/ldap_members_types.php:71, displayed in :169 and :171, and applied in adherents/class/adherent_type.class.php:1191-1192 to map the member-type label to the LDAP attribute.', 'Changing this value remaps which LDAP attribute receives the member-type label during synchronization.', 'Any valid LDAP attribute name string (e.g. ''cn'', ''displayName'')', 0, 0, 'admin/ldap_members_types.php|admin/ldap_members_types.php|admin/ldap_members_types.php', 1, '54ae1e5ccc2dbf8420f17fc7388e38e452d64c8c22f29fc5e469184294398f79', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members_types.php:71|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_TYPE_FIELD_FULLNAME'', GETPOST(\"fieldfullname\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent_type.class.php:1191|check|if ($this->label && getDolGlobalString(''LDAP_MEMBER_TYPE_FIELD_FULLNAME'')) {", "adherents/class/adherent_type.class.php:1192|read|$info[getDolGlobalString(''LDAP_MEMBER_TYPE_FIELD_FULLNAME'')] = $this->label;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_TYPE_FIELD_GROUPMEMBERS', 'string', NULL, 'admin', 'Specifies the LDAP attribute name used to store the list of members within a member type.', 'Written in admin/ldap_members_types.php:77, displayed in :183 and :185, and applied in adherents/class/adherent_type.class.php:1197 and :1205 to populate the LDAP group-members attribute.', 'Changing this value remaps which LDAP attribute receives the list of members for a member-type group during synchronization.', 'Any valid LDAP attribute name string (e.g. ''member'', ''uniqueMember'')', 0, 0, 'admin/ldap_members_types.php|admin/ldap_members_types.php|admin/ldap_members_types.php', 1, 'd1390b02b6436baecae2061d24211e8cfd0194c5f9ba4bc1fd0efb250f8ba0c5', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members_types.php:77|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_TYPE_FIELD_GROUPMEMBERS'', GETPOST(\"fieldmembertypemembers\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent_type.class.php:1197|check|if (getDolGlobalString(''LDAP_MEMBER_TYPE_FIELD_GROUPMEMBERS'')) {", "adherents/class/adherent_type.class.php:1205|read|$info[getDolGlobalString(''LDAP_MEMBER_TYPE_FIELD_GROUPMEMBERS'')] = (!empty($valueofldapfield) ? $valueofldapfield : '''');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_MEMBER_TYPE_OBJECT_CLASS', 'string', NULL, 'admin', 'Specifies the LDAP objectClass value(s) for member-type entries.', 'Written in admin/ldap_members_types.php:67, displayed in :148, used in :207, and applied as a comma-separated list in adherents/class/adherent_type.class.php:1184.', 'Changing this value alters the objectClass attribute set on member-type LDAP entries during synchronization.', 'Comma-separated list of LDAP objectClass names (e.g. ''groupOfNames,top'')', 0, 0, 'admin/ldap_members_types.php|admin/ldap_members_types.php|admin/ldap_members_types.php', 1, 'aa4a8f9415b530e87371479e5b6ee4ff907720227da8d7d678b4f31f38967a1a', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap_members_types.php:67|write|if (!dolibarr_set_const($db, ''LDAP_MEMBER_TYPE_OBJECT_CLASS'', GETPOST(\"objectclass\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/class/adherent_type.class.php:1184|read|$info[\"objectclass\"] = explode('','', getDolGlobalString(''LDAP_MEMBER_TYPE_OBJECT_CLASS''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_PASSWORD_HASH_TYPE', 'string', NULL, 'admin', 'Selects the hash algorithm used to encode passwords stored/compared in LDAP.', 'Set via admin/ldap.php:116 (dolibarr_set_const) and read via getDolGlobalString(''LDAP_PASSWORD_HASH_TYPE'', ''md5'') in admin/ldap.php:249 and blockedlog/lib/securitycore.lib.php (281, 283), defaulting to ''md5''.', 'Changing it selects a different hash algorithm passed to dolGetLdapPasswordHash, affecting how passwords are hashed for LDAP.', 'defaults to ''md5'' when unset', 0, 0, 'admin/ldap.php|admin/ldap.php', 1, '85e3e114bd5103a56a7dce3d6f40823e5f3b16423eee9c220fc57f18ce8e65dc', 'v2', '2026-07-24T06:41:12+00:00', '["admin/ldap.php:116|write|if (!dolibarr_set_const($db, ''LDAP_PASSWORD_HASH_TYPE'', GETPOST(\"LDAP_PASSWORD_HASH_TYPE\", ''aZ09''), ''chaine'', 0, '''', $conf->entity)) {", "blockedlog/lib/securitycore.lib.php:281|read|return array(''pass_encrypted'' => dolGetLdapPasswordHash($chain, getDolGlobalString(''LDAP_PASSWORD_HASH_TYPE'', ''md5'')), ''pass_encoding'' => ''ldappasswordhash''.getDolGlobalString(''LDA"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SEND_EMPTY_MEMBERS_TO_GROUP', 'string', NULL, 'core', 'Controls whether empty member lists are sent to LDAP group entries during synchronisation.', 'Checked in core/triggers/interface_50_modLdap_Ldapsynchro.class.php at lines 293, 313, and 338; when not set, empty member arrays are suppressed from the LDAP update; when set, empty member lists and null member sets are included.', 'When set, LDAP group entries receive an empty member attribute, which may clear existing members; when not set, empty member lists are not transmitted to LDAP.', 'Empty/unset = empty member lists suppressed; non-empty = empty member lists sent to LDAP.', 1, 0, NULL, 1, 'd351f1fc3fcd4a620d645cfec70e2084d8e360463c15ccf6686b5b4657dc6c68', 'v2', '2026-04-21T11:16:15+00:00', '["core/triggers/interface_50_modLdap_Ldapsynchro.class.php:293|check|if (isset($info[''member'']) && empty($info[''member'']) && !getDolGlobalString(''LDAP_SEND_EMPTY_MEMBERS_TO_GROUP'')) {", "core/triggers/interface_50_modLdap_Ldapsynchro.class.php:313|check|if ($object->members === null && getDolGlobalString(''LDAP_SEND_EMPTY_MEMBERS_TO_GROUP'')) {", "core/triggers/interface_50_modLdap_Ldapsynchro.class.php:338|check|if (isset($info[''member'']) && empty($info[''member'']) && !getDolGlobalString(''LDAP_SEND_EMPTY_MEMBERS_TO_GROUP'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SERVER_DN', 'string', NULL, 'admin', 'Specifies the base Distinguished Name (DN) of the LDAP server used for directory operations.', 'Assigned to both $ldap->dn and $ldap->domain in core/class/ldap.class.php when the LDAP connection is initialized. Configurable via the admin UI at admin/ldap.php and saved via dolibarr_set_const.', 'Changing this value alters the root search base and domain used for all LDAP directory queries; an incorrect DN will break directory connectivity.', 'A valid LDAP DN string, e.g. ''dc=example,dc=com''.', 0, 0, 'admin/ldap.php|admin/ldap.php', 1, '21a35f1fbdc5bcae607d518115641ce8ea993a5742fbdc9b6ea2a64859988b1e', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/ldap.class.php:284|read|$this->dn = getDolGlobalString(''LDAP_SERVER_DN'');", "core/class/ldap.class.php:287|read|$this->domain = getDolGlobalString(''LDAP_SERVER_DN'');", "admin/ldap.php:239|read|print ''<input class=\"minwidth300\" type=\"text\" name=\"dn\" value=\"''.getDolGlobalString(''LDAP_SERVER_DN'').''\">'';", "admin/ldap.php:92|write|if (!dolibarr_set_const($db, ''LDAP_SERVER_DN'', GETPOST(\"dn\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SERVER_HOST', 'string', NULL, 'admin', 'Sets the hostname/address of the primary LDAP server used for authentication and directory lookups.', 'Set via admin/ldap.php:83 (dolibarr_set_const) and read via getDolGlobalString(''LDAP_SERVER_HOST'') in admin/ldap.php (223, 284), core/class/ldap.class.php:277, and displayed in contact/ldap.php:135, adherents/ldap.php:161, adherents/type_ldap.php:123, user/group/ldap.php:145.', 'Changing it points the LDAP class connection logic (core/class/ldap.class.php:277) to a different primary LDAP server host.', NULL, 0, 0, 'admin/ldap.php|admin/ldap.php|admin/ldap.php', 1, '7f8737820c7ce88a0647a853aa74751a9a100a213d84b6d15e8fbdc2d9fe02af', 'v2', '2026-07-24T06:41:12+00:00', '["admin/ldap.php:83|write|if (!dolibarr_set_const($db, ''LDAP_SERVER_HOST'', GETPOST(\"host\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity)) {", "core/class/ldap.class.php:277|check|if (getDolGlobalString(''LDAP_SERVER_HOST'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SERVER_HOST_SLAVE', 'string', NULL, 'admin', 'Sets the hostname/address of a secondary (slave) LDAP server used as a fallback for authentication and directory lookups.', 'Set via admin/ldap.php:86 (dolibarr_set_const) and read via getDolGlobalString(''LDAP_SERVER_HOST_SLAVE'') in admin/ldap.php:229, core/class/ldap.class.php:280, and displayed in contact/ldap.php:136, user/group/ldap.php:146, adherents/ldap.php:162, adherents/type_ldap.php:124, user/ldap.php:157.', 'Changing it points the LDAP class connection logic (core/class/ldap.class.php:280) to a different secondary/slave LDAP server host.', NULL, 0, 0, 'admin/ldap.php|admin/ldap.php', 1, '14e3159a68bafe568af90f3ec6cb76dd71868578937c4a17d9331d1e615917ce', 'v2', '2026-07-24T06:41:12+00:00', '["admin/ldap.php:86|write|if (!dolibarr_set_const($db, ''LDAP_SERVER_HOST_SLAVE'', GETPOST(\"slave\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity)) {", "core/class/ldap.class.php:280|check|if (getDolGlobalString(''LDAP_SERVER_HOST_SLAVE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SERVER_PORT', 'string', NULL, 'admin', 'TCP port number used to connect to the LDAP server.', 'Used when establishing the LDAP TCP connection; displayed in connection success/failure messages at admin/ldap.php:295-331. The default shown in the admin UI input is ''389''. Configurable via admin/ldap.php.', 'Changing this port affects all LDAP connections; an incorrect port will cause connection failures for all LDAP-dependent features.', 'Integer as string: TCP port number (default ''389'' for plain LDAP; ''636'' for LDAPS).', 0, 0, 'admin/ldap.php|admin/ldap.php|admin/ldap.php|admin/ldap.php|admin/ldap.php|admin/ldap.php', 1, 'fc6fbdb37a6adae035552f3da047c23f7bca0fb55ecdafa6c4b1190878bee754', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap.php:234|read|print ''<input class=\"width75\" type=\"text\" name=\"port\" value=\"''.getDolGlobalString(''LDAP_SERVER_PORT'', ''389'').''\">'';", "admin/ldap.php:295|read|print ''<span class=\"ok\">''.$langs->trans(\"LDAPTCPConnectOK\", $ldap->connectedServer, getDolGlobalString(''LDAP_SERVER_PORT'')).''</span>'';", "admin/ldap.php:89|write|if (!dolibarr_set_const($db, ''LDAP_SERVER_PORT'', GETPOSTINT(\"port\"), ''chaine'', 0, '''', $conf->entity)) {", "adherents/ldap.php:163|read|print ''<tr><td>LDAP ''.$langs->trans(\"LDAPServerPort\").''</td><td class=\"valeur\">''.getDolGlobalString(''LDAP_SERVER_PORT'').\"</td></tr>\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SERVER_PROTOCOLVERSION', 'string', NULL, 'adherents', 'Specifies the LDAP protocol version used when connecting to the LDAP server.', 'Stored as a string and assigned to the ldapProtocolVersion property of the LDAP connection object in core/class/ldap.class.php. Also governs conditional logic in adherents/class/adherent.class.php and user/class/user.class.php. Configured via admin/ldap.php.', 'Changing this value alters the protocol version negotiated with the LDAP server. Setting it to a version not supported by the server will cause connection failures.', 'Protocol version string, e.g. ''2'' or ''3''', 0, 0, 'admin/ldap.php|admin/ldap.php', 1, 'e3c800c5ce1c3ca88ab97c0637ef5f6a5db53c2913e0ea3742ece83ace892b5d', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/ldap.class.php:283|read|$this->ldapProtocolVersion = getDolGlobalString(''LDAP_SERVER_PROTOCOLVERSION'');", "adherents/class/adherent.class.php:3064|read|} elseif (getDolGlobalString(''LDAP_SERVER_PROTOCOLVERSION'') !== ''3'') {", "admin/ldap.php:80|write|if (!dolibarr_set_const($db, ''LDAP_SERVER_PROTOCOLVERSION'', GETPOST(\"LDAP_SERVER_PROTOCOLVERSION\", ''aZ09''), ''chaine'', 0, '''', $conf->entity)) {", "user/class/user.class.php:3618|read|} elseif (getDolGlobalString(''LDAP_SERVER_PROTOCOLVERSION'') !== ''3'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SERVER_TYPE', 'string', NULL, 'core', 'Specifies the type of LDAP server (e.g. standard LDAP, Active Directory, eGroupware) for authentication and synchronisation.', 'Controls LDAP-specific behaviour throughout the stack. Checked in core/login/functions_ldap.php:191 for ''activedirectory'' to adjust bind logic, in contact/class/contact.class.php:895 for ''egroupware'', and in core/triggers/interface_50_modLdap_Ldapsynchro.class.php:227 for sync direction. Configurable via admin/ldap.php.', 'Changing this value alters how Dolibarr authenticates users and synchronises data with the LDAP server; an incorrect type will break LDAP login or sync.', 'String: ''openldap'' (standard LDAP), ''activedirectory'' (Microsoft Active Directory), ''egroupware''.', 0, 0, 'admin/ldap.php|admin/ldap.php', 1, 'e5e307a38309a1464b18cdf7f8c3292dcbf6f29cdba48c440443302417e7f94f', 'v2', '2026-04-21T11:16:15+00:00', '["core/login/functions_ldap.php:191|check|if (getDolGlobalString(''LDAP_SERVER_TYPE'') == \"activedirectory\") {", "contact/class/contact.class.php:895|check|if (getDolGlobalString(''LDAP_SERVER_TYPE'') == ''egroupware'') {", "core/triggers/interface_50_modLdap_Ldapsynchro.class.php:227|check|if (getDolGlobalInt(\"LDAP_SYNCHRO_ACTIVE\") === Ldap::SYNCHRO_DOLIBARR_TO_LDAP && getDolGlobalString(''LDAP_SERVER_TYPE'') == \"activedirectory\") {", "admin/ldap.php:74|write|if (!dolibarr_set_const($db, ''LDAP_SERVER_TYPE'', GETPOST(\"type\", ''aZ09''), ''chaine'', 0, '''', $conf->entity)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SERVER_USE_TLS', 'bool', NULL, 'admin', 'Enables TLS encryption for the LDAP server connection.', 'When set to a truthy value, the LDAP class activates TLS on the connection (core/class/ldap.class.php:393). Configurable via a yes/no select in the admin UI at admin/ldap.php and stored via dolibarr_set_const.', 'Enabling TLS secures the LDAP connection; disabling it leaves the connection unencrypted.', 'Non-empty (truthy) enables TLS; empty or ''0'' disables it.', 0, 0, 'admin/ldap.php|admin/ldap.php', 1, '54681865e1339d4ce55a28ef9069f944efda40879df27540c0728134b7933c9a', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/ldap.class.php:393|check|if (getDolGlobalString(''LDAP_SERVER_USE_TLS'')) {", "admin/ldap.php:244|read|print $form->selectyesno(''usetls'', getDolGlobalInt(''LDAP_SERVER_USE_TLS''), 1);", "admin/ldap.php:101|write|if (!dolibarr_set_const($db, ''LDAP_SERVER_USE_TLS'', GETPOST(\"usetls\", ''aZ09''), ''chaine'', 0, '''', $conf->entity)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_SYNCHRO_ACTIVE', 'string', NULL, 'core', 'Determines the active LDAP synchronisation direction globally (Dolibarr-to-LDAP, LDAP-to-Dolibarr, or disabled).', 'Set via admin/ldap.php:104 and displayed at line 166; checked extensively across admin/ldap_groups.php, admin/ldap_users.php, and core/triggers/interface_50_modLdap_Ldapsynchro.class.php to gate all LDAP synchronisation trigger logic for users, groups, and contacts.', 'Changing this value enables, disables, or reverses the global LDAP synchronisation direction, affecting whether all object changes are pushed to or pulled from LDAP.', 'One of the Ldap::SYNCHRO_* constants (e.g. Ldap::SYNCHRO_DOLIBARR_TO_LDAP, Ldap::SYNCHRO_LDAP_TO_DOLIBARR); empty/unset = synchronisation disabled.', 0, 0, 'admin/ldap_groups.php|admin/ldap_groups.php|admin/ldap.php|admin/ldap.php|admin/ldap_users.php|admin/ldap_users.php|admin/ldap.php', 1, '167fdecd2955037f48ef4caa364478546f5dbd4183c23917340d87589283f6b4', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap.php:104|write|if (!dolibarr_set_const($db, ''LDAP_SYNCHRO_ACTIVE'', GETPOST(\"activesynchro\", ''aZ09''), ''chaine'', 0, '''', $conf->entity)) {", "core/triggers/interface_50_modLdap_Ldapsynchro.class.php:87|check|if (getDolGlobalString(''LDAP_SYNCHRO_ACTIVE'') && getDolGlobalInt(''LDAP_SYNCHRO_ACTIVE'') === Ldap::SYNCHRO_DOLIBARR_TO_LDAP) {", "admin/ldap_groups.php:233|check|if (getDolGlobalInt(''LDAP_SYNCHRO_ACTIVE'') === Ldap::SYNCHRO_DOLIBARR_TO_LDAP) {", "admin/ldap_users.php:410|check|if (getDolGlobalString(''LDAP_SYNCHRO_ACTIVE'') == Ldap::SYNCHRO_DOLIBARR_TO_LDAP) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_USERACCOUNTCONTROL', 'string', NULL, 'admin', 'Stores the userAccountControl value to set on LDAP user entries when synchronising users to Active Directory.', 'Set via admin/ldap.php:77 with a displayed default of 512; read in admin/ldap.php:212 and assigned to $info[''userAccountControl''] in core/triggers/interface_50_modLdap_Ldapsynchro.class.php:97 during user sync.', 'Changing this value alters the userAccountControl flags written to Active Directory user entries during synchronisation.', 'An integer string representing an Active Directory userAccountControl bitmask; default display value is ''512'' (normal account).', 0, 0, 'admin/ldap.php|admin/ldap.php', 1, 'c3fcfb185bacfaa6cc4c80b426f1569580724d20bcfdb2144cd5987682399ba1', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ldap.php:212|read|print ''<input class=\"width75\" type=\"text\" name=\"userAccountControl\" value=\"''.getDolGlobalString(''LDAP_USERACCOUNTCONTROL'', ''512'').''\">'';", "admin/ldap.php:77|write|if (!dolibarr_set_const($db, ''LDAP_USERACCOUNTCONTROL'', GETPOSTINT(\"userAccountControl\"), ''chaine'', 0, '''', $conf->entity)) {", "core/triggers/interface_50_modLdap_Ldapsynchro.class.php:97|read|$info[''userAccountControl''] = getDolGlobalString(''LDAP_USERACCOUNTCONTROL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_USER_DN', 'string', NULL, 'admin', 'Specifies the LDAP Distinguished Name (DN) of the branch where user entries are stored.', 'Used as the base DN when searching for or synchronizing user records in the LDAP directory. Read by both admin/ldap_users.php (for listing and sync operations) and user/card.php (for individual user lookups). Configurable via the admin UI at admin/ldap_users.php.', 'Changing this value redirects all LDAP user lookups and synchronization operations to the specified DN; an incorrect value will cause user queries to fail.', 'A valid LDAP DN string, e.g. ''ou=users,dc=example,dc=com''.', 0, 0, 'admin/ldap.php|admin/ldap_users.php|admin/ldap_users.php|admin/ldap_users.php|admin/ldap_users.php|admin/ldap_users.php|admin/ldap_users.php', 1, '7b3d8ea2ab4fcbd6ceb5f4c2404d7dfeac31af1b1202c657cc4750c616c7b360', 'v2', '2026-04-21T13:50:40+00:00', '["admin/ldap_users.php:507|read|$ldapusers = $ldap->getRecords(''*'', getDolGlobalString(''LDAP_USER_DN''), getDolGlobalString(''LDAP_KEY_USERS''), $required_fields, 1);", "admin/ldap.php:168|check|if (getDolGlobalString(''LDAP_SYNCHRO_ACTIVE'') && !getDolGlobalString(''LDAP_USER_DN'')) {", "admin/ldap_users.php:65|write|if (!dolibarr_set_const($db, ''LDAP_USER_DN'', GETPOST(\"user\"), ''chaine'', 0, '''', $conf->entity)) {", "user/card.php:774|read|$ldapusers = $ldap->getRecords($selecteduser, getDolGlobalString(''LDAP_USER_DN''), getDolGlobalString(''LDAP_KEY_USERS''), $required_fields);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LDAP_USER_OBJECT_CLASS', 'string', NULL, 'admin', 'Specifies the LDAP objectClass value(s) used to identify user entries in the LDAP directory.', 'Configured via admin/ldap_users.php (written at line 68, displayed at line 212). In user/class/user.class.php:3546 the value is split by comma and assigned to the ''objectclass'' attribute when building the LDAP user entry.', 'Changing this value alters the objectClass set on LDAP user records created or updated by Dolibarr; an incorrect value will cause LDAP write operations to fail.', 'Comma-separated LDAP objectClass names (e.g. ''inetOrgPerson,posixAccount'').', 0, 0, 'admin/ldap_users.php|admin/ldap_users.php|admin/ldap_users.php|admin/ldap_users.php', 1, 'fd048c199f7356fe9575c93dbce8c6d6a8106eaad7a6999025c7bffc370b446f', 'v2', '2026-04-21T13:50:40+00:00', '["admin/ldap_users.php:68|write|dolibarr_set_const($db, ''LDAP_USER_OBJECT_CLASS'', GETPOST(\"objectclass\")", "user/class/user.class.php:3546|read|$info[\"objectclass\"] = explode('','', getDolGlobalString(''LDAP_USER_OBJECT_CLASS''));", "admin/ldap_users.php:212|read|print ''<input size=\"48\" type=\"text\" name=\"objectclass\" value=\"''.getDolGlobalString(''LDAP_USER_OBJECT_CLASS'').''\">''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LIST_OF_QUALIFIED_INVOICES_LIMIT_DEFINED', 'string', NULL, 'compta', 'Caps the number of rows returned by the query that lists invoices qualified as source for a credit note.', 'In facture.class.php:5397-5400 (list_qualified_avoir_invoices), when this constant is a positive integer, the SQL query is ordered and passed to $this->db->plimit() with that value as the row limit.', 'Setting a positive integer limits how many qualified invoices are returned/orderable when picking a source invoice for a credit note; a value <= 0 leaves the query unordered/unlimited by this mechanism.', 'Integer > 0 = row limit applied; <= 0 = no limit (default ORDER BY f.ref only).', 1, 0, NULL, 1, 'eb488731a88530375fc67cb45e1954f0226b0b3011414b264bcceea7e6493e91', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/class/facture.class.php:5397: if (getDolGlobalInt(''LIST_OF_QUALIFIED_INVOICES_LIMIT_DEFINED'') > 0) {", "compta/facture/class/facture.class.php:5400: $sql .= $this->db->plimit(getDolGlobalInt(''LIST_OF_QUALIFIED_INVOICES_LIMIT_DEFINED''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LOAN_ACCOUNTING_ACCOUNT_CAPITAL', 'string', NULL, 'accountancy', 'Specifies the accounting account code for loan capital repayment entries in the treasury journal and loan card.', 'Read in accountancy/journal/treasuryjournal.php:844 with fallback ''NotDefined'', and used as the default account in loan/card.php:379 when no POST value is provided. No admin UI is configured.', 'If unset, loan capital entries in the treasury journal use the reserved string ''NotDefined'', resulting in unresolved accounting entries.', 'A chart-of-accounts code string; ''NotDefined'' is the reserved fallback used when the constant is absent.', 1, 0, NULL, 1, '5685a1e1d342bc4971cd6c8bb1e9fd53b7f213331bceffdb7c88bb1badbc1c61', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/treasuryjournal.php:844|read|$account_pay_loan_capital = getDolGlobalString(''LOAN_ACCOUNTING_ACCOUNT_CAPITAL'', ''NotDefined''); // NotDefined is a reserved word", "loan/card.php:379|read|print $formaccounting->select_account(GETPOST(''accountancy_account_capital'') ? GETPOST(''accountancy_account_capital'') : getDolGlobalString(''LOAN_ACCOUNTING_ACCOUNT_CAPITAL'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LOAN_ACCOUNTING_ACCOUNT_INSURANCE', 'string', NULL, 'accountancy', 'Specifies the accounting account code for loan insurance payment entries in the treasury journal and loan card.', 'Read in accountancy/journal/treasuryjournal.php:846 with fallback ''NotDefined'', and used as the default account in loan/card.php:385 when no POST value is provided. No admin UI is configured.', 'If unset, loan insurance entries in the treasury journal use the reserved string ''NotDefined'', resulting in unresolved accounting entries.', 'A chart-of-accounts code string; ''NotDefined'' is the reserved fallback used when the constant is absent.', 1, 0, NULL, 1, '9c33393e54cd31a7451653f076aaa5658631e078774c9097330f265e3852fbe9', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/treasuryjournal.php:846|read|$account_pay_loan_insurance = getDolGlobalString(''LOAN_ACCOUNTING_ACCOUNT_INSURANCE'', ''NotDefined''); // NotDefined is a reserved word", "loan/card.php:385|read|print $formaccounting->select_account(GETPOST(''accountancy_account_insurance'') ? GETPOST(''accountancy_account_insurance'') : getDolGlobalString(''LOAN_ACCOUNTING_ACCOUNT_INSURANCE'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LOAN_ACCOUNTING_ACCOUNT_INTEREST', 'string', NULL, 'accountancy', 'Specifies the accounting account code for loan interest repayment entries in the treasury journal and loan card.', 'Read in accountancy/journal/treasuryjournal.php:845 with fallback ''NotDefined'', and used as the default account in loan/card.php:391 when no POST value is provided. No admin UI is configured.', 'If unset, loan interest entries in the treasury journal use the reserved string ''NotDefined'', resulting in unresolved accounting entries.', 'A chart-of-accounts code string; ''NotDefined'' is the reserved fallback used when the constant is absent.', 1, 0, NULL, 1, 'cd98f0c77147a722d41fb89e66083b6c30cab3d27aae988ca307fa0e25a49b4c', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/treasuryjournal.php:845|read|$account_pay_loan_interest = getDolGlobalString(''LOAN_ACCOUNTING_ACCOUNT_INTEREST'', ''NotDefined''); // NotDefined is a reserved word", "loan/card.php:391|read|print $formaccounting->select_account(GETPOST(''accountancy_account_interest'') ? GETPOST(''accountancy_account_interest'') : getDolGlobalString(''LOAN_ACCOUNTING_ACCOUNT_INTEREST'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('LOT_ADVANCED_MASK', 'string', NULL, 'product', 'Defines the global mask pattern used for advanced lot number generation when no product-specific mask is set.', 'Read in core/modules/product_batch/mod_lot_advanced.php at lines 71 and 153 as the primary mask. Also read in product/card.php at lines 1562 and 2179 as the inherited mask, with line 2174 preferring the product''s own batch_mask when available.', 'Changing this mask changes the format of automatically generated lot numbers for all products that do not override it with a product-specific mask.', 'string (mask pattern); empty = no auto-generation pattern', 1, 0, NULL, 1, '4493183b6b41687e4779b47f42fc06a1ca5d229b383eb0788b9ad49c4ce11289', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/product_batch/mod_lot_advanced.php:71|read|$mask = getDolGlobalString(''LOT_ADVANCED_MASK'');", "core/modules/product_batch/mod_lot_advanced.php:153|read|$mask = getDolGlobalString(''LOT_ADVANCED_MASK'');", "product/card.php:2174|check|$mask = !empty($object->batch_mask) ? $object->batch_mask : getDolGlobalString(''LOT_ADVANCED_MASK'');", "product/card.php:1562|read|$inherited_mask_lot = getDolGlobalString(''LOT_ADVANCED_MASK'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_ADD_TAB_ON_PROJECT', 'string', NULL, 'core', 'Adds a Mailing/Emailing tab on project cards when the mailing module is enabled.', 'In core/lib/project.lib.php:284, the tab is added only if isModEnabled(''mailing'') && getDolGlobalInt(''MAILING_ADD_TAB_ON_PROJECT''); the inline comment says this tab is shown only as a hidden option since the info is otherwise obtainable, to avoid ''tabflation''.', 'Enabling it adds an extra tab to the project view for viewing mailings tied to that project; the code comment explains it''s deliberately opt-in to avoid cluttering the UI with too many tabs.', 'Boolean-like/int: set/non-empty (with mailing module enabled) shows the tab; unset (default) hides it.', 1, 0, NULL, 1, 'aa443f72684808e29ec5bb066786c3963ed87443ecaff6d01cb53e59a70d40a3', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/project.lib.php:284: if (isModEnabled(''mailing'') && getDolGlobalInt(''MAILING_ADD_TAB_ON_PROJECT'')) { // Show this tab only in hidden option is on (we can already get the information from other view and we must fight against the tabflation)."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_CONTACT_DEFAULT_BULK_STATUS', 'string', NULL, 'societe', 'Sets the default bulk email opt-out status applied to new contacts when the emailing module is enabled.', 'Written in admin/mailing.php:95 and displayed in admin/mailing.php:208 for configuration. Read in contact/card.php:856 as default value for the no_email field on new contact forms. The COMMENTS confirm: ''Default value is in MAILING_CONTACT_DEFAULT_BULK_STATUS that you can modify in setup of module emailing''.', 'Changing this value alters the pre-selected opt-out status for all newly created contacts. A value of 2 triggers additional JavaScript behavior on the contact creation form.', 'Integer stored as string; 0 = opted-in by default, 1 = opted-out by default, 2 = opted-out with additional UI enforcement (value 2 triggers JS).', 0, 0, 'admin/mailing.php|admin/mailing.php', 1, 'fb0f8c71df78316eb4996e579ebe58700228f3e621088d188d7272cf3676e490', 'v2', '2026-04-21T11:16:15+00:00', '["contact/card.php:855  // Default value is in MAILING_CONTACT_DEFAULT_BULK_STATUS that you can modify in setup of module emailing", "contact/card.php:833|check|if ($conf->use_javascript_ajax && getDolGlobalInt(''MAILING_CONTACT_DEFAULT_BULK_STATUS'') == 2) {", "admin/mailing.php:95|write|$res = dolibarr_set_const($db, \"MAILING_CONTACT_DEFAULT_BULK_STATUS\", $contactbulkdefault, ''chaine'', 0, '''', $conf->entity);", "contact/card.php:856|read|print $form->selectyesno(''no_email'', (GETPOSTISSET(\"no_email\") ? GETPOSTINT(\"no_email\") : getDolGlobalInt(''MAILING_CONTACT_DEFAULT_BULK_STATUS'')), 1, false, (int) (getDolGlobalInt("]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_DELAY', 'string', NULL, 'comm', 'Sets a delay in seconds between each email sent during a mailing campaign.', 'Written via admin/mailing.php:91 and read in comm/mailing/card.php:447-448. The value is cast to float and used as argument to usleep() (multiplied by 1,000,000 to convert seconds to microseconds). The log entry confirms: ''Wait a delay of MAILING_DELAY=''.', 'Increasing the delay slows the mailing send rate, which can help avoid being flagged as spam or overloading an SMTP server. Setting to 0 or empty disables the inter-email delay.', 'A numeric value in seconds (float accepted); 0 or empty = no delay between emails', 0, 0, 'admin/mailing.php|admin/mailing.php', 1, '02c0b5f120a3f2bd10413f4ac1871908799227abef8e8542e34c8fac3a69429f', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/card.php:447|read|dol_syslog(\"Wait a delay of MAILING_DELAY=\".((float) $conf->global->MAILING_DELAY));", "comm/mailing/card.php:448|read|usleep((int) ((float) $conf->global->MAILING_DELAY * 1000000));", "admin/mailing.php:91|write|$res = dolibarr_set_const($db, \"MAILING_DELAY\", $mailingdelay, ''chaine'', 0, '''', $conf->entity);", "comm/mailing/card.php:446|check|if (getDolGlobalString(''MAILING_DELAY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_EMAIL_ERRORSTO', 'string', NULL, 'admin', 'Sets the email address to which mailing delivery errors (bounces) should be reported.', 'Written via admin/mailing.php:87 and read in both admin/mailing.php:174 (UI display) and comm/mailing/card.php:899 as the default for the ''errorsto'' field. Validated as a correct email format before saving.', 'Changing this value redirects delivery error notifications to a different address. An invalid email format is rejected by the admin UI.', 'A valid email address string; empty = no specific error recipient configured', 0, 0, 'admin/mailing.php|admin/mailing.php|admin/mailing.php', 1, '8f8fe1a48222f2454b8883baffb6410bf126fd7646316d25c692a1f3f73d28ec', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mailing.php:87|write|$res = dolibarr_set_const($db, \"MAILING_EMAIL_ERRORSTO\", $mailerror, ''chaine'', 0, '''', $conf->entity);", "admin/mailing.php:175|check|if (getDolGlobalString(''MAILING_EMAIL_ERRORSTO'') && !isValidEmail(getDolGlobalString(''MAILING_EMAIL_ERRORSTO''))) {", "admin/mailing.php:174|read|print ''<input class=\"minwidth100\" type=\"text\" name=\"MAILING_EMAIL_ERRORSTO\" value=\"'' . getDolGlobalString(''MAILING_EMAIL_ERRORSTO'') . ''\">'';", "comm/mailing/card.php:899|read|print ''<td>''.img_picto('''', ''email'', ''class=\"pictofixedwidth\"'').''<input class=\"flat minwidth200\" name=\"errorsto\" value=\"''.getDolGlobalString(''MAILING_EMAIL_ERRORSTO'', getDolGlobalSt"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_EMAIL_FROM', 'string', 'no-reply@mydomain.tld', 'public', 'Sets the default sender email address for mass mailing campaigns.', 'Written via admin/mailing.php:83 and read in multiple files including comm/mailing/card.php:893, public/payment/paymentok.php:2274, public/project/suggestbooth.php:545, and public/eventorganization/attendee_new.php:691. Validated as a correct email format before saving.', 'Changing this value updates the From address used in mailing campaigns and public event emails. An invalid email format is rejected by the admin UI.', 'A valid email address string; default ''no-reply@mydomain.tld'' when unset', 0, 0, 'admin/mailing.php|admin/mailing.php|admin/mailing.php', 1, '5662d48187d62b79c70fdbe251957623ab4e19f8ddbe6ed14f1ffdce17f98a6a', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mailing.php:83|write|$res = dolibarr_set_const($db, \"MAILING_EMAIL_FROM\", $mailfrom, ''chaine'', 0, '''', $conf->entity);", "admin/mailing.php:165|check|if (getDolGlobalString(''MAILING_EMAIL_FROM'') && !isValidEmail(getDolGlobalString(''MAILING_EMAIL_FROM''))) {", "public/payment/paymentok.php:2274|read|$from = getDolGlobalString(''MAILING_EMAIL_FROM'', getDolGlobalString(\"MAIN_MAIL_EMAIL_FROM\"));", "public/project/suggestbooth.php:545|read|$from = getDolGlobalString(''MAILING_EMAIL_FROM'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_EMAIL_REPLYTO', 'string', NULL, 'comm', 'Default ''Reply-To'' email address pre-filled on the mass emailing (mailing) card, falling back to MAIN_MAIL_REPLY_TO if unset.', 'Read in comm/mailing/card.php:904 as the default value of the ''replyto'' input field on the mailing creation form.', 'Pre-populates the Reply-To address for new mailings; if not set, the form falls back to the global MAIN_MAIL_REPLY_TO value.', 'An email address string.', 0, 0, NULL, 1, 'a0d7157617db57dcd0da883f20e3cbe943be51299f5646f1c2f90b2b4cdb3239', 'v2', '2026-07-24T07:05:23+00:00', '["comm/mailing/card.php:904: value=\"''.getDolGlobalString(''MAILING_EMAIL_REPLYTO'', getDolGlobalStri..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_EMAIL_UNSUBSCRIBE_KEY', 'string', NULL, 'comm', 'Stores the secret key used to generate and verify HMAC security tokens for mailing unsubscribe and read-tracking links.', 'Set via admin/mailing.php:105 and displayed at line 195; used in public/emailing/mailing-unsubscribe.php:79 and public/emailing/mailing-read.php:114 to validate the securitykey parameter, and in multiple admin and core files to construct __CHECK_READ__ and __UNSUBSCRIBE_URL__ substitution values.', 'Changing this value invalidates all previously generated unsubscribe and read-tracking links that used the old key.', 'Any non-empty string; used as the base for dol_hash(key.''-''.tag.''-''.email.''-''.mtid, ''md5'').', 0, 0, 'admin/mailing.php|admin/mails.php|admin/mails_emailing.php|admin/mailing.php', 1, '41c3b846e109aab654be37d0d5eec7e323c2170e4090e9a3226cedf809bd1b35', 'v2', '2026-04-21T11:16:15+00:00', '["admin/mailing.php:105|write|$res = dolibarr_set_const($db, \"MAILING_EMAIL_UNSUBSCRIBE_KEY\", $checkread_key, ''chaine'', 0, '''', $conf->entity);", "public/emailing/mailing-unsubscribe.php:79|check|if ($securitykey != dol_hash(getDolGlobalString(''MAILING_EMAIL_UNSUBSCRIBE_KEY'').\"-\".$tag.\"-\".$email.\"-\".$mtid, ''md5'')) {", "public/emailing/mailing-read.php:114|check|if ($securitykey != dol_hash(getDolGlobalString(''MAILING_EMAIL_UNSUBSCRIBE_KEY'').\"-\".$tag.\"-\".$email.\"-\".$mtid, ''md5'')) {", "core/tpl/card_presend.tpl.php:330|read|$checkRead .= ''&securitykey=''.(getDolGlobalString(''MAILING_EMAIL_UNSUBSCRIBE_KEY'') ? urlencode(getDolGlobalString(''MAILING_EMAIL_UNSUBSCRIBE_KEY'')) : \"\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_LIMIT_SENDBYCLI', 'string', NULL, 'comm', 'Limits or forbids sending mass emailings from the command-line script, independent of the web-based send limit.', 'Defined via conf.php ($dolibarr_main_mailing_limit_sendbycli, CONF_PHP_WIRING) rather than the admin UI. Checked in comm/mailing/card.php:1060 to decide whether to show the command-line sending instructions; comment at line 1009/81 states ''MAILING_LIMIT_SENDBYCLI may be defined or not (-1=forbidden, 0 or undefined=no limit)''.', '-1 forbids sending via the command-line script (the CLI instructions/hint are then hidden); 0 or undefined means no limit, so the CLI hint is shown; the value itself is not enforced as a numeric cap in the excerpt shown.', '-1=forbidden, 0 or undefined=no limit (verbatim from comment).', 1, 0, NULL, 1, 'fbb846bd203c387359a8ade1adf676d4b65ec1e34d4aceecbd0deae91eff21d3', 'v2', '2026-07-24T07:05:23+00:00', '["comm/mailing/card.php:1009: // MAILING_LIMIT_SENDBYCLI may be defined or not (-1=forbidden, 0 or undefined=no limit).", "comm/mailing/card.php:1060: if (!isset($conf->global->MAILING_LIMIT_SENDBYCLI) || getDolGlobalInt(''MAILING_LIMIT_SENDBYCLI'') >= 0) {"]', 'high', '$dolibarr_main_mailing_limit_sendbycli (conf.php) → ${conf->global->MAILING_LIMIT_SENDBYCLI}');
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_LIMIT_SENDBYDAY', 'string', NULL, 'comm', 'Caps the number of mass-emailing messages that can be sent per day; shown as a warning to the user before sending.', 'Defined via conf.php ($dolibarr_main_mailing_limit_sendbyday, CONF_PHP_WIRING) rather than the admin UI. Checked in comm/mailing/card.php:1053 (if > 0) to display a WarningLimitSendByDay message before sending; comment at line 1010/71 states ''MAILING_LIMIT_SENDBYDAY may be defined or not (0 or undefined=no limit)''.', 'Setting a positive value shows a daily-limit warning to the user before sending a mailing; 0 or undefined means no limit is enforced/shown.', '0 or undefined = no limit (per comment); positive integer = daily send limit shown in a warning message.', 1, 0, NULL, 1, 'aa8ee2bbd416552a617dd81619d49f47972d9ed159f054478709f48f0365068b', 'v2', '2026-07-24T07:05:23+00:00', '["comm/mailing/card.php:1010: // MAILING_LIMIT_SENDBYDAY may be defined or not (0 or undefined=no limit).", "comm/mailing/card.php:1053: if (getDolGlobalInt(''MAILING_LIMIT_SENDBYDAY'') > 0) {"]', 'high', '$dolibarr_main_mailing_limit_sendbyday (conf.php) → ${conf->global->MAILING_LIMIT_SENDBYDAY}');
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_LIMIT_SENDBYWEB', 'string', '25', 'comm', 'Limits the number of recipients allowed per web-triggered mailing send; -1 forbids sending via web entirely.', 'Defined in conf.php (not via the admin UI) via $dolibarr_main_mailing_limit_sendbyweb, though it can also be written through the admin UI at admin/mailing.php (admin/mailing.php:99). Checked in multiple places including core/tpl/massactions_pre.tpl.php:357 and comm/mailing/card.php:1530 to restrict recipient count during web-based sends. The comment notes it is always defined to something != 0, and can also be set to ''default''.', 'When set to -1, web-based sending is forbidden. When set to a positive integer, sends exceeding that recipient count are blocked with a warning.', '-1=forbidden', 0, 0, 'admin/mailing.php|admin/mailing.php', 1, '9441bf6244812b00be9e81b91fb0752b783984be3a0f2d267d53526abd3257de', 'v2', '2026-04-21T10:47:32+00:00', '["comm/mailing/card.php:1006  // MAILING_LIMIT_SENDBYWEB is always defined to something != 0 (-1=forbidden).", "comm/mailing/card.php:1529  // MAILING_LIMIT_SENDBYWEB can be ''default''", "core/tpl/massactions_pre.tpl.php:357|check|if (getDolGlobalString(''MAILING_LIMIT_SENDBYWEB'') && count($listofselectedrecipientobjid) > $conf->global->MAILING_LIMIT_SENDBYWEB) {", "admin/mailing.php:99|write|$res = dolibarr_set_const($db, \"MAILING_LIMIT_SENDBYWEB\", $batchlimit, ''chaine'', 1, '''', 0);"]', 'high', '$dolibarr_main_mailing_limit_sendbyweb (conf.php) → ${conf->global->MAILING_LIMIT_SENDBYWEB}');
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_LIMIT_WARNING_NOPHPMAIL', 'string', NULL, 'comm', 'Stores a translation key for a warning message displayed when the mailing send mode is not PHP mail().', 'Checked in comm/mailing/card.php at lines 1030 and 1045, both conditioned on sendingmode != ''mail''. The value is passed to $langs->transnoentitiesnoconv() and shown as a warning event message.', 'Setting this to a valid translation key causes a warning to appear on the mailing page when a non-PHP-mail sending mode is active. Clearing it suppresses the warning.', 'A translation key string whose translated value is shown as a warning when sendingmode is not ''mail''; empty = no warning', 1, 0, NULL, 1, '43be5f450ece23b2da9a0b2b410e8544e311467a311313fe1b9ffe454b29321f', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/card.php:1030|check|if (getDolGlobalString(''MAILING_LIMIT_WARNING_NOPHPMAIL'') && $sendingmode != ''mail'') {", "comm/mailing/card.php:1031|read|setEventMessages($langs->transnoentitiesnoconv($conf->global->MAILING_LIMIT_WARNING_NOPHPMAIL), null, ''warnings'');", "comm/mailing/card.php:1045|check|if (getDolGlobalString(''MAILING_LIMIT_WARNING_NOPHPMAIL'') && $sendingmode != ''mail'') {", "comm/mailing/card.php:1046|read|setEventMessages($langs->transnoentitiesnoconv($conf->global->MAILING_LIMIT_WARNING_NOPHPMAIL), null, ''warnings'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_LIMIT_WARNING_PHPMAIL', 'string', NULL, 'comm', 'Stores a translation key for a warning message displayed when the mailing send mode is PHP mail().', 'Checked in comm/mailing/card.php at lines 1027 and 1042, both conditioned on sendingmode == ''mail''. The value is passed to $langs->transnoentitiesnoconv() and shown as a warning event message.', 'Setting this to a valid translation key causes a warning to appear on the mailing page when PHP mail() is the active sending mode. Clearing it suppresses the warning.', 'A translation key string whose translated value is shown as a warning when sendingmode is ''mail''; empty = no warning', 1, 0, NULL, 1, '593c19de942aa7a483e38315078962862c9d2ed55efc7d29b1cb02689bbe9f9f', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/card.php:1027|check|if (getDolGlobalString(''MAILING_LIMIT_WARNING_PHPMAIL'') && $sendingmode == ''mail'') {", "comm/mailing/card.php:1028|read|setEventMessages($langs->transnoentitiesnoconv($conf->global->MAILING_LIMIT_WARNING_PHPMAIL), null, ''warnings'');", "comm/mailing/card.php:1042|check|if (getDolGlobalString(''MAILING_LIMIT_WARNING_PHPMAIL'') && $sendingmode == ''mail'') {", "comm/mailing/card.php:1043|read|setEventMessages($langs->transnoentitiesnoconv($conf->global->MAILING_LIMIT_WARNING_PHPMAIL), null, ''warnings'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_NO_USING_PHPMAIL', 'string', NULL, 'comm', 'Prevents the use of PHP''s built-in mail() function for sending mailing campaigns when EMAILING_MAIL_SENDMODE is ''mail''.', 'The code comment states: ''MAILING_NO_USING_PHPMAIL may be defined or not.'' (comm/mailing/card.php:1005). Checked in both comm/mailing/card.php:1009 and core/class/CMailFile.class.php:886 when the sending mode is ''mail''.', 'Enabling this constant blocks PHP mail() from being used in mailing campaigns even if the send mode is ''mail'', forcing an error or alternative path. Disabling allows PHP mail() to be used.', 'Empty/unset = PHP mail() allowed when sendmode is ''mail''; non-empty = PHP mail() blocked for mailing campaigns', 1, 0, NULL, 1, '783bd90e1aa2be18e61cd4ef48046625de6fa9a5cf49dcaa2b1dcf0f7d40abf0', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/card.php:1005  // MAILING_NO_USING_PHPMAIL may be defined or not.", "comm/mailing/card.php:1009|check|if (getDolGlobalString(''MAILING_NO_USING_PHPMAIL'') && $sendingmode == ''mail'') {", "core/class/CMailFile.class.php:886|check|if ($this->sendcontext == ''emailing'' && getDolGlobalString(''MAILING_NO_USING_PHPMAIL'') && $sendingmode == ''mail'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_SMS_FROM', 'string', NULL, 'comm', 'Default ''from'' phone number pre-filled in the SMS sending fields of the mass emailing (mailing) card when creating an SMS-mode mailing.', 'Read in comm/mailing/card.php:898 as the default value of the ''fromphone'' input field (shown for the SMS variant of the mailing form, class ''fieldsforsms''), used only if the field is not already posted by the user.', 'Pre-populates the SMS sender number field on the mailing creation form; does not affect the email sender field (MAILING_EMAIL_FROM handles that).', 'A phone number string, e.g. in international ''+123...'' format per the field placeholder.', 0, 0, NULL, 1, '4f2c1a9746012d8deb730950340ae324b23434b810cd87e40f6fba80348ce7d3', 'v2', '2026-07-24T07:05:23+00:00', '["comm/mailing/card.php:898: getDolGlobalString(''MAILING_SMS_FROM'')).''\" placeholder=\"+123...\">''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_SMTP_SETUP_EMAILS_FOR_QUESTIONS', 'string', NULL, 'core', 'Stores an email address displayed in warnings when the SMTP setup requires attention for mailing campaigns.', 'Checked in both comm/mailing/card.php:1022 and core/class/CMailFile.class.php:901. When set, the value is passed to $langs->trans(''MailSendSetupIs3'', ...) to produce a warning message shown to the user and logged as an error.', 'Setting this constant causes a warning with the configured email address to appear when the mailing SMTP setup triggers the MailSendSetupIs3 condition. Clearing it suppresses the warning.', 'An email address string shown in the SMTP setup warning message; empty = no warning displayed', 1, 0, NULL, 1, '616ee5138534a52392deb70e3d6842c5a7d4498c54b6b0b8b36e2c322a3e7abf', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/card.php:1022|check|if (getDolGlobalString(''MAILING_SMTP_SETUP_EMAILS_FOR_QUESTIONS'')) {", "comm/mailing/card.php:1023|read|setEventMessages($langs->trans(\"MailSendSetupIs3\", getDolGlobalString(''MAILING_SMTP_SETUP_EMAILS_FOR_QUESTIONS'')), null, ''warnings'');", "core/class/CMailFile.class.php:901|check|if (getDolGlobalString(''MAILING_SMTP_SETUP_EMAILS_FOR_QUESTIONS'')) {", "core/class/CMailFile.class.php:902|read|$this->error .= ''<br>''.$langs->trans(\"MailSendSetupIs3\", getDolGlobalString(''MAILING_SMTP_SETUP_EMAILS_FOR_QUESTIONS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAILING_USE_NEW_PATH_FOR_FILES', 'bool', NULL, 'comm', 'Switches the mailing attachment directory from a legacy 2-level subdirectory layout to a flat (new) path layout.', 'Read in seven locations across comm/mailing/targetemailing.php and comm/mailing/card.php via the pattern: get_exdir($object->id, getDolGlobalInt(''MAILING_USE_NEW_PATH_FOR_FILES'') ? 0 : 2, 0, 1, $object, ''mailing''). When truthy, level=0 (flat); when falsy, level=2 (subdirectory).', 'Enabling this constant moves mailing file storage to the flat path layout; disabling keeps the legacy two-level subdirectory structure. Changing this after mailings have files stored risks broken file references.', 'Non-empty/non-zero = new flat path (level 0). Empty/unset/0 = legacy 2-level path.', 1, 0, NULL, 1, '65a626cb8713207183f65ad440a16339356c96182880224c49b0d3dc250403b5', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/targetemailing.php:289|read|$upload_dir = $conf->mailing->dir_output.\"/\".get_exdir($object->id, getDolGlobalInt(''MAILING_USE_NEW_PATH_FOR_FILES'') ? 0 : 2, 0, 1, $object, ''mailing'');", "comm/mailing/card.php:125|read|$upload_dir = $conf->mailing->dir_output.\"/\".get_exdir($object->id, getDolGlobalInt(''MAILING_USE_NEW_PATH_FOR_FILES'') ? 0 : 2, 0, 1, $object, ''mailing'');", "comm/mailing/card.php:635|read|$upload_dir = $conf->mailing->dir_output.\"/\".get_exdir($object->id, getDolGlobalInt(''MAILING_USE_NEW_PATH_FOR_FILES'') ? 0 : 2, 0, 1, $object, ''mailing'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_DISABLE_UTF7_ENCODE_OF_DIR', 'bool', NULL, 'emailcollector', 'Disables UTF-7 encoding of IMAP mailbox folder names in the email collector.', 'Checked in emailcollector/class/emailcollector.class.php at lines 1351, 1795, and 3989; when not set, folder names are encoded to UTF-7 before use in IMAP commands. No admin UI write path is present.', 'Setting this skips UTF-7 encoding of mailbox folder names, which may be needed for servers that do not expect UTF-7 encoded folder names.', '0 or unset = UTF-7 encode folder names; non-zero = skip UTF-7 encoding', 1, 0, NULL, 1, '8444badfcf482c50c428e55cf535890ec34074db4f46bf857f2ac5f8b27d8e00', 'v2', '2026-04-21T13:50:40+00:00', '["emailcollector/class/emailcollector.class.php:1351|check|if (!getDolGlobalString(''MAIL_DISABLE_UTF7_ENCODE_OF_DIR'')) {", "emailcollector/class/emailcollector.class.php:1795|check|if (!getDolGlobalString(''MAIL_DISABLE_UTF7_ENCODE_OF_DIR'')) {", "emailcollector/class/emailcollector.class.php:3989|check|if (!getDolGlobalString(''MAIL_DISABLE_UTF7_ENCODE_OF_DIR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_FORCE_DELIVERY_RECEIPT_INVOICE', 'string', NULL, 'core', 'Forces the delivery receipt checkbox to be pre-checked by default on the send-email form for customer invoices.', 'Read in core/class/html.formmail.class.php:1481, inside getHtmlForDeliveryreceipt(), only applied when $this->param[''models''] == ''facture_send''.', 'When set, $defaultvaluefordeliveryreceipt is forced to 1 for the facture_send email form, checking the delivery receipt box by default.', 'Boolean-like: any truthy value forces default-checked state for facture_send emails; unset/false leaves default at 0.', 1, 0, NULL, 1, '30f87eda556958dc51ec1253d96f22d5b35eac98cec3e6b9953e34719395397e', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:1481|check|if (getDolGlobalString(''MAIL_FORCE_DELIVERY_RECEIPT_INVOICE'') && !empty($this->param[''models'']) && $this->param[''models''] == ''facture_send'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_FORCE_DELIVERY_RECEIPT_ORDER', 'string', NULL, 'core', 'Forces the delivery receipt checkbox to be pre-checked by default on the send-email form for customer orders.', 'Read in core/class/html.formmail.class.php:1478, inside getHtmlForDeliveryreceipt(), only applied when $this->param[''models''] == ''order_send''.', 'When set, $defaultvaluefordeliveryreceipt is forced to 1 for the order_send email form, checking the delivery receipt box by default.', 'Boolean-like: any truthy value forces default-checked state for order_send emails; unset/false leaves default at 0.', 1, 0, NULL, 1, '19356be2d177d9de2f87256a6e71f14f2bd4c11cc9d25f4b7d0b73dd4eb62e35', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:1478|check|if (getDolGlobalString(''MAIL_FORCE_DELIVERY_RECEIPT_ORDER'') && !empty($this->param[''models'']) && $this->param[''models''] == ''order_send'') {"]', 'medium', NULL);
