INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_FORCE_DELIVERY_RECEIPT_SUPPLIER_ORDER', 'string', NULL, 'core', 'Forces the delivery receipt checkbox to be pre-checked by default on the send-email form for supplier orders.', 'Read in core/class/html.formmail.class.php:1484, inside getHtmlForDeliveryreceipt(), only applied when $this->param[''models''] == ''order_supplier_send''.', 'When set, $defaultvaluefordeliveryreceipt is forced to 1 for the order_supplier_send email form, checking the delivery receipt box by default.', 'Boolean-like: any truthy value forces default-checked state for order_supplier_send emails; unset/false leaves default at 0.', 1, 0, NULL, 1, '250cb88dd579fc2ca8641ad1cfa782362327f889912259fb2769cb9a5526c0fc', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:1484|check|if (getDolGlobalString(''MAIL_FORCE_DELIVERY_RECEIPT_SUPPLIER_ORDER'') && !empty($this->param[''models'']) && $this->param[''models''] == ''order_supplier_send'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_FORCE_DELIVERY_RECEIPT_SUPPLIER_PROPOSAL', 'string', NULL, 'core', 'Forces the delivery receipt checkbox to be pre-checked by default on the send-email form for supplier proposals.', 'Read in core/class/html.formmail.class.php:1475, inside getHtmlForDeliveryreceipt(), only applied when $this->param[''models''] == ''supplier_proposal_send''.', 'When set, $defaultvaluefordeliveryreceipt is forced to 1 for the supplier_proposal_send email form, checking the delivery receipt box by default.', 'Boolean-like: any truthy value forces default-checked state for supplier_proposal_send emails; unset/false leaves default at 0.', 1, 0, NULL, 1, '1775d8bbed3aefd0c35f41a9d02f92d526a68145d528be8a689833e460fa88e5', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:1475|check|if (getDolGlobalString(''MAIL_FORCE_DELIVERY_RECEIPT_SUPPLIER_PROPOSAL'') && !empty($this->param[''models'']) && $this->param[''models''] == ''supplier_proposal_send'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_FROM_EMAILS_TO_CONSIDER_SENDING', 'string', NULL, 'emailcollector', 'Specifies a comma-separated list of email addresses to treat as outgoing sender addresses during email collection.', 'The COMMENT in emailcollector/class/emailcollector.class.php:2740 states ''If sender is in the list MAIL_FROM_EMAILS_TO_CONSIDER_SENDING''. At line 2741, the value is split on commas and trimmed to build an array of sender addresses. No admin UI write path is present.', 'Setting this causes the collector to recognize emails from the listed addresses as outgoing (sent) messages rather than incoming ones.', 'String: comma-separated list of email addresses to treat as outgoing senders', 1, 0, NULL, 1, '603c3ea22bf8e533710d9b458278e2491023f197cc4ce7b7d9723d0b13857a79', 'v2', '2026-04-21T13:50:40+00:00', '["emailcollector/class/emailcollector.class.php:2740  // If sender is in the list MAIL_FROM_EMAILS_TO_CONSIDER_SENDING", "emailcollector/class/emailcollector.class.php:2741|read|$arrayofemailtoconsidersender = array_filter(array_map(''trim'', explode('','', getDolGlobalString(''MAIL_FROM_EMAILS_TO_CONSIDER_SENDING''))));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_MASS_ACTION_ADD_LAST_IF_MAIN_DOC_NOT_FOUND', 'string', NULL, 'core', 'Attaches the last main document when the primary document is not found during mass-action email sending.', 'Checked in core/class/html.formmail.class.php:924 and core/actions_massactions.inc.php:456. The second check also requires $objectobj->last_main_doc to be non-empty before attaching.', 'Enabling this causes the last available main document to be attached as a fallback; disabling it skips attachment when the primary document is missing.', 'truthy = attach last main doc as fallback; empty/not set = do not attach', 1, 0, NULL, 1, 'f46adf05061a14883d46dfa6537d842aa90b0f6d9590f1519974a5781436f194', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/html.formmail.class.php:924|check|if (getDolGlobalString(''MAIL_MASS_ACTION_ADD_LAST_IF_MAIN_DOC_NOT_FOUND'')) {", "core/actions_massactions.inc.php:456|check|if (getDolGlobalString(''MAIL_MASS_ACTION_ADD_LAST_IF_MAIN_DOC_NOT_FOUND'') && !empty($objectobj->last_main_doc)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_MASS_ACTION_SEARCH_MOST_RECENT_FILE_IF_NOT_FOUND', 'string', NULL, 'core', 'During mass email actions, if the expected document file is missing, falls back to searching the directory for the most recently generated file matching the object ref.', 'Checked at core/actions_massactions.inc.php:447 inside the ''addmaindocfile'' mass-action email attachment logic; if set and the expected $filepath does not exist, dol_most_recent_file() is used to locate a substitute (optionally restricted to .pdf when MAIN_ODT_AS_PDF is set).', 'When enabled, mass mailing with ''attach main document'' will still find and attach a file even if the exact expected filename is absent, using the most recent matching file instead of failing silently.', 'Truthy enables the most-recent-file fallback search; empty/0 leaves the mass action unable to attach a document if the expected file path is missing.', 1, 0, NULL, 1, '677a0af7357c121f2ca135ba172aa71f447bf12b5a1e43a9d9caefa77a37a605', 'v2', '2026-07-24T07:05:23+00:00', '["core/actions_massactions.inc.php:447: if (getDolGlobalInt(''MAIL_MASS_ACTION_SEARCH_MOST_RECENT_FILE_IF_NOT_FOUND'') && isset($filepath) && !dol_is_file($filepath)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_MAX_NB_OF_RECIPIENTS_BCC_IN_SAME_EMAIL', 'string', NULL, 'core', 'Sets the maximum number of BCC recipients allowed in a single outgoing email.', 'If unset, the code at core/class/CMailFile.class.php:930 writes a default of 10 at runtime. The limit is enforced at line 933 by comparing the BCC recipient count against this value.', 'Lowering this value restricts BCC recipients per email; raising it permits more. If unset, the effective default is 10.', 'Integer; defaults to 10 if not set.', 1, 0, NULL, 1, '7100e5aa771ee1b355c1388ffc4ffe64f6dda66cdb1aa025f89b770d2f1a767b', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:929|check|if (!getDolGlobalString(''MAIL_MAX_NB_OF_RECIPIENTS_BCC_IN_SAME_EMAIL'')) {", "core/class/CMailFile.class.php:930|write|$conf->global->MAIL_MAX_NB_OF_RECIPIENTS_BCC_IN_SAME_EMAIL = 10;", "core/class/CMailFile.class.php:933|read|if (count($tmparray3) > $conf->global->MAIL_MAX_NB_OF_RECIPIENTS_BCC_IN_SAME_EMAIL) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_MAX_NB_OF_RECIPIENTS_CC_IN_SAME_EMAIL', 'string', NULL, 'core', 'Sets the maximum number of CC recipients allowed in a single outgoing email.', 'If unset, the code at core/class/CMailFile.class.php:921 writes a default of 10 at runtime. The limit is enforced at line 924 by comparing the CC recipient count against this value.', 'Lowering this value restricts CC recipients per email; raising it permits more. If unset, the effective default is 10.', 'Integer; defaults to 10 if not set.', 1, 0, NULL, 1, 'a36752d8fce8678a87769c3d7d0d036dab2414b978b5eec48caebef493582b46', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:920|check|if (!getDolGlobalString(''MAIL_MAX_NB_OF_RECIPIENTS_CC_IN_SAME_EMAIL'')) {", "core/class/CMailFile.class.php:921|write|$conf->global->MAIL_MAX_NB_OF_RECIPIENTS_CC_IN_SAME_EMAIL = 10;", "core/class/CMailFile.class.php:924|read|if (count($tmparray2) > $conf->global->MAIL_MAX_NB_OF_RECIPIENTS_CC_IN_SAME_EMAIL) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_MAX_NB_OF_RECIPIENTS_IN_SAME_EMAIL', 'string', NULL, 'core', 'Sets the maximum total number of recipients (To + CC + BCC combined) allowed in a single outgoing email.', 'Described in core/class/CMailFile.class.php:910 as: check number of recipient is lower or equal than MAIL_MAX_NB_OF_RECIPIENTS_IN_SAME_EMAIL. If unset, the code at line 939 writes a default of 10. Enforced at line 941 against the combined count.', 'Lowering this restricts total recipients per email; raising it permits more combined recipients. If unset, the effective default is 10.', 'Integer; defaults to 10 if not set.', 1, 0, NULL, 1, '28ca8cf873686b89f3bc3ee0c923cae35b53a541c630ad80b2221f3001e36112', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:910  // Check number of recipient is lower or equal than MAIL_MAX_NB_OF_RECIPIENTS_IN_SAME_EMAIL", "core/class/CMailFile.class.php:939|write|$conf->global->MAIL_MAX_NB_OF_RECIPIENTS_IN_SAME_EMAIL = 10;", "core/class/CMailFile.class.php:941|read|if ((count($tmparray1) + count($tmparray2) + count($tmparray3)) > $conf->global->MAIL_MAX_NB_OF_RECIPIENTS_IN_SAME_EMAIL) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_MAX_NB_OF_RECIPIENTS_TO_IN_SAME_EMAIL', 'string', NULL, 'core', 'Sets the maximum number of To recipients allowed in a single outgoing email.', 'If unset, the code at core/class/CMailFile.class.php:912 writes a default of 10 at runtime. The limit is enforced at line 915 by comparing the To recipient count against this value.', 'Lowering this value restricts To recipients per email; raising it permits more. If unset, the effective default is 10.', 'Integer; defaults to 10 if not set.', 1, 0, NULL, 1, '9c22c858944e60ab088be2fcc57d7258d6cf0c5d9d38bcb26b7f28a7e520b10c', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:911|check|if (!getDolGlobalString(''MAIL_MAX_NB_OF_RECIPIENTS_TO_IN_SAME_EMAIL'')) {", "core/class/CMailFile.class.php:912|write|$conf->global->MAIL_MAX_NB_OF_RECIPIENTS_TO_IN_SAME_EMAIL = 10;", "core/class/CMailFile.class.php:915|read|if (count($tmparray1) > $conf->global->MAIL_MAX_NB_OF_RECIPIENTS_TO_IN_SAME_EMAIL) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_PREFIX_FOR_EMAIL_ID', 'string', NULL, 'core', 'Sets a custom prefix string used when constructing the Message-ID header for outgoing emails.', 'Checked and read at core/lib/functions.lib.php:1585-1587. When set to ''SERVER_NAME'', the server name is used instead of the literal value. A comment at line 1593 notes the recommended value when this constant is not defined.', 'Changing this value alters the Message-ID prefix in outgoing emails. Using ''SERVER_NAME'' dynamically uses the server hostname.', 'Any string prefix, or ''SERVER_NAME'' to use the server hostname. The recommended value if MAIL_PREFIX_FOR_EMAIL_ID is not defined (may be not defined for old versions).', 1, 0, NULL, 1, '9ae7c62870d61cf2e93994d9db57e99ad7e82031d14eee07e4eefb772100d3eb', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:1585|check|if (getDolGlobalString(''MAIL_PREFIX_FOR_EMAIL_ID'')) {\t// If MAIL_PREFIX_FOR_EMAIL_ID is set", "core/lib/functions.lib.php:1586|check|if (getDolGlobalString(''MAIL_PREFIX_FOR_EMAIL_ID'') != ''SERVER_NAME'') {", "core/lib/functions.lib.php:1593  // The recommended value if MAIL_PREFIX_FOR_EMAIL_ID is not defined (may be not defined for old versions)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIL_SMTP_USE_FROM_FOR_HELO', 'bool', NULL, 'core', 'Controls the domain name sent in the SMTP HELO/EHLO command, with three modes: string domain, domain from sender address, or domain from Dolibarr URL.', 'Read extensively in core/class/smtps.class.php. COMMENTS state: ''If value of MAIL_SMTP_USE_FROM_FOR_HELO is a string, we use it as domain name''; ''If value of MAIL_SMTP_USE_FROM_FOR_HELO is 1, we use the domain in the from.''; ''If value of MAIL_SMTP_USE_FROM_FOR_HELO is 2, we use the domain in the $dolibarr_main_url_root.'' An inline note states ''default value is forced to MAIL_SMTP_USE_FROM_FOR_HELO=2 if not set''.', 'Changing this value alters which domain is advertised during the SMTP handshake, affecting mail server acceptance and DMARC/SPF alignment.', 'String or int: a literal domain string = use as HELO domain; 1 = use sender''s domain; 2 = use dolibarr_main_url_root domain (default when unset).', 1, 0, NULL, 1, '29cbf845a68f11238cdbd408192c972852c3a161ffa2cc66c963c4f592260236', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/smtps.class.php:570  // If value of MAIL_SMTP_USE_FROM_FOR_HELO is a string, we use it as domain name", "core/class/smtps.class.php:573  // If value of MAIL_SMTP_USE_FROM_FOR_HELO is 1, we use the domain in the from.", "core/class/smtps.class.php:580  // If value of MAIL_SMTP_USE_FROM_FOR_HELO is 2, we use the domain in the $dolibarr_main_url_root.", "core/class/smtps.class.php:568|check|if (getDolGlobalString(''MAIL_SMTP_USE_FROM_FOR_HELO'')) {\t// Note that default value is forced to MAIL_SMTP_USE_FROM_FOR_HELO=2 if not set"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ACTIONCOM_CAN_ADD_ANY_CONTACT', 'string', NULL, 'comm', 'Allows adding contacts from any third-party (not just the event''s linked third-party) to an agenda event.', 'When set, the contact selector uses socid=0 (all contacts) instead of restricting to the event''s socid. Seen in comm/action/card.php lines 1780, 1792, 2361, 2365, 2369. Two comments warn this can hang on large databases.', 'Enabling this on a large database risks slow page loads or timeouts due to loading all contacts without a third-party filter.', 'Empty/unset = contacts filtered to the event''s third-party; truthy value = all contacts selectable (Warning: MAIN_ACTIONCOM_CAN_ADD_ANY_CONTACT will hangs on large databases).', 1, 0, NULL, 1, '23807c9d538b4d4e147bea71c9031f7f7e1c1a0c6f6587da6e28f3b3fe097b87', 'v2', '2026-04-21T13:29:58+00:00', '["comm/action/card.php:1781  // Warning: MAIN_ACTIONCOM_CAN_ADD_ANY_CONTACT will hangs on large databases", "comm/action/card.php:1780|check|if (getDolGlobalInt(''MAIN_ACTIONCOM_CAN_ADD_ANY_CONTACT'')) {", "comm/action/card.php:1792|read|print $form->select_contact(getDolGlobalString(''MAIN_ACTIONCOM_CAN_ADD_ANY_CONTACT'') ? 0 : $object->socid, $selected, ''socpeopleassigned'', 1, '''', '''', 1, ''minwidth300 widthcentperce", "comm/action/card.php:2368  // Warning: MAIN_ACTIONCOM_CAN_ADD_ANY_CONTACT will hangs on large databases"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ACTIVATE_FILECACHE', 'string', NULL, 'core', 'Enables file-based caching for dashboard box content to reduce repeated database queries.', 'Set via admin/boxes.php:63 and admin/system/perf.php (read at line 759); checked in core/boxes/modules_boxes.php:465 to decide whether to serve box content from a file cache. Temporarily overridden in core/boxes/box_activity.php:83 and restored at line 436 during box rendering.', 'Enabling this constant causes box content to be written to and served from a file cache for the duration defined by MAIN_ACTIVATE_FILECACHE_DELAY; disabling it forces live queries for every page load.', '0 or empty = file cache disabled; non-zero = file cache enabled.', 0, 0, 'admin/system/perf.php|admin/system/perf.php|admin/boxes.php|admin/boxes.php', 1, '8a0969d50f549d92ae312253bba2e72f3756e5b7a90a3c708c5b92fa32abc509', 'v2', '2026-04-21T11:16:15+00:00', '["admin/boxes.php:63|write|dolibarr_set_const($db, \"MAIN_ACTIVATE_FILECACHE\", GETPOST(\"MAIN_ACTIVATE_FILECACHE\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "core/boxes/modules_boxes.php:465|check|if (getDolGlobalString(''MAIN_ACTIVATE_FILECACHE'')) {", "core/boxes/box_activity.php:83|write|$conf->global->MAIN_ACTIVATE_FILECACHE = 1;", "admin/system/perf.php:759|read|print yn(getDolGlobalInt(''MAIN_ACTIVATE_FILECACHE''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ACTIVATE_FILECACHE_DELAY', 'string', NULL, 'core', 'Sets, in seconds, how long the file-based cache for dashboard boxes remains valid before being regenerated.', 'Read via getDolGlobalInt(''MAIN_ACTIVATE_FILECACHE_DELAY'', 900) in admin/boxes.php:462 (displayed to the user) and core/boxes/modules_boxes.php:268, where the comment ''900 : 15mn'' explains the default.', 'Increasing the value makes dashboard box file-cache entries stay valid longer before being refreshed; decreasing it refreshes them more often.', 'seconds; defaults to 900 (15 minutes)', 0, 0, 'admin/boxes.php', 1, '6320a87342c254e42584244a9d7c93a4dead5b1a46b128729d64ff0a1b89703a', 'v2', '2026-07-24T06:41:12+00:00', '["core/boxes/modules_boxes.php:268|read|$cachetime = getDolGlobalInt(''MAIN_ACTIVATE_FILECACHE_DELAY'', 900); // 900 : 15mn", "admin/boxes.php:462|read|print $form->textwithpicto($langs->trans(\"EnableFileCache\").'' <span class=\"opacitymedium\">(''.getDolGlobalInt(''MAIN_ACTIVATE_FILECACHE_DELAY'', 900).\" \".$langs->trans(\"seconds\").\")</"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ACTIVATE_VALIDATION_RESULT', 'string', NULL, 'core', 'Enables field-level validation via validateField() on object fields marked with ''validate'' => 1, as an alternative to requiring MAIN_FEATURES_LEVEL >= 1.', 'Checked alongside MAIN_FEATURES_LEVEL in core/actions_addupdatedelete.inc.php:194 and 354, asset/class/assetdepreciationoptions.class.php:305, and core/class/fieldsmanager.class.php:874 and 914. Multiple class docblocks state: ''validate'' is 1 if you need to validate the field with $this->validateField(). Need MAIN_ACTIVATE_VALIDATION_RESULT.', 'When set, field validation via validateField() is active for all object fields with ''validate'' => 1, even without MAIN_FEATURES_LEVEL >= 1.', 'Empty/unset = validation only active when MAIN_FEATURES_LEVEL >= 1; non-empty = validation always active.', 1, 0, NULL, 1, '2908d72f8490401077ddda150842bb40ae2e7fc2f04e84ba68ea424df06085f4', 'v2', '2026-04-21T11:16:15+00:00', '["societe/class/societeaccount.class.php:89  *\t''validate'' is 1 if you need to validate the field with $this->validateField(). Need MAIN_ACTIVATE_VALIDATION_RESULT.", "mrp/class/moline.class.php:89  *\t''validate'' is 1 if you need to validate the field with $this->validateField(). Need MAIN_ACTIVATE_VALIDATION_RESULT.", "core/actions_addupdatedelete.inc.php:194|check|if (getDolGlobalInt(''MAIN_FEATURES_LEVEL'') >= 1 || getDolGlobalString(''MAIN_ACTIVATE_VALIDATION_RESULT'')) {", "core/class/fieldsmanager.class.php:874|check|if (getDolGlobalInt(''MAIN_FEATURES_LEVEL'') >= 1 || getDolGlobalString(''MAIN_ACTIVATE_VALIDATION_RESULT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADD_CREATOR_IN_NOTE', 'string', NULL, 'core', 'When enabled, appends the name of the document''s creator/author to the note shown in the Cyan and Azur proposal PDF templates.', 'Checked identically in core/modules/propale/doc/pdf_cyan.modules.php:416 and core/modules/propale/doc/pdf_azur.modules.php:437, both guarded by $object->user_author_id > 0; when true it fetches the author user and builds a ''CaseFollowedBy <name>'' string appended to the note.', 'Enabling it adds a ''followed by <creator name>'' line to the note section of generated Cyan/Azur proposal PDFs, when the proposal has a recorded author.', 'Boolean: true/1 adds the creator''s name to the PDF note.', 0, 0, NULL, 1, 'e66906bc6eee148a8d0183c16bda1d7a0727c0075130f520598c9dca6096f9f9', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:416|check|if (getDolGlobalString(''MAIN_ADD_CREATOR_IN_NOTE'') && $object->user_author_id > 0) {", "core/modules/propale/doc/pdf_azur.modules.php:437|check|if (getDolGlobalString(''MAIN_ADD_CREATOR_IN_NOTE'') && $object->user_author_id > 0) {", "core/modules/propale/doc/pdf_cyan.modules.php: $creator_info = $langs->trans(\"CaseFollowedBy\").'' ''.$tmpuser->getFullName($langs);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADD_EVENT_ON_ELEMENT_CARD', 'string', NULL, 'fourn', 'Would show an ''Add action/event'' button on object cards (supplier invoice, supplier order, proposal, project), but all four occurrences are inside commented-out code blocks.', 'Found only inside `/* ... */` commented-out code in fourn/facture/card.php:4368, fourn/commande/card.php:2899, comm/propal/card.php:3631, projet/card.php:1667, each annotated ''Add hidden condition because this is not a workflow action so should appear somewhere else on page.''', 'Currently has no effect at runtime in any of the four locations found, since the checking code is commented out; the comment indicates the feature was intentionally disabled/relocated.', 'Bool (intended): truthy would have shown an ''AddAction'' link when agenda module is enabled, per the (dead) code, but this is currently inactive.', 1, 0, NULL, 1, '955f9eaf286483b00e3bd3b855b843514fe5503e95a68ed849ce0e5e32e1908d', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:4368|check|/*if (isModEnabled(''agenda'') && getDolGlobalString(''MAIN_ADD_EVENT_ON_ELEMENT_CARD'')) { \t// Add hidden condition because this is not a \"workflow\" action so should appears somewhere else on page.", "fourn/commande/card.php:2899|check|/*if (isModEnabled(''agenda'') && getDolGlobalString(''MAIN_ADD_EVENT_ON_ELEMENT_CARD'')) \t// Add hidden condition because this is not a \"workflow\" action so should appears somewhere else on page.", "comm/propal/card.php:3631|read|/*if (isModEnabled(''agenda'') && !empty($conf->global->MAIN_ADD_EVENT_ON_ELEMENT_CARD)) \t// Add hidden condition because this is not a \"workflow\" action so should appears somewhere else on page."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADD_ICONPICKER_JS', 'string', NULL, 'core', 'Enables loading of the icon-picker JavaScript library for icon selection fields in forms.', 'Checked via getDolGlobalInt in core/class/html.form.class.php:12899, core/class/extrafields.class.php:1341, and webportal/class/html.formwebportal.class.php:1442. No admin UI writes this constant.', 'When non-zero, the icon-picker JS component is included in pages that render icon selection fields.', 'Integer: 1 to enable the icon picker JS; 0 or unset to disable.', 1, 0, NULL, 1, '9a991661a67821147285b8b727d893ee37c1af3e9cbdf794c0f92690727b6222', 'v2', '2026-04-21T11:16:15+00:00', '["webportal/class/html.formwebportal.class.php:1442|check|if (getDolGlobalInt(''MAIN_ADD_ICONPICKER_JS'')) {", "core/class/html.form.class.php:12899|check|if (getDolGlobalInt(''MAIN_ADD_ICONPICKER_JS'')) {", "core/class/extrafields.class.php:1341|check|if (getDolGlobalInt(''MAIN_ADD_ICONPICKER_JS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADD_LINE_AT_POSITION', 'string', NULL, 'fourn', 'Shows a ''position'' number input when adding a new line to an invoice/order, letting the user insert the line at a specific rank instead of at the end.', 'Checked in core/tpl/objectline_create.tpl.php:421 (the shared add-line template) to display an extra numeric ''rank'' input field, and also checked in fourn/class/fournisseur.facture.class.php:1402 and compta/facture/class/facture.class.php:2937 when processing the line creation.', 'Enabling it lets users choose the insertion position of new invoice/order lines instead of always appending them at the end.', 'Boolean: 0/unset = no position input shown, lines always appended at end; 1 = position input shown, allowing insertion at a chosen rank.', 0, 0, NULL, 1, 'b3f3713d35ece09256fee8efc194d4ac66aec7274ff1403d2a806134c623aab4', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:421: if (getDolGlobalString(''MAIN_ADD_LINE_AT_POSITION'')) {", "core/tpl/objectline_create.tpl.php:422: echo ''<br>''.$langs->trans(''AddLineOnPosition'').'' : <input type=\"number\" name=\"rank\" step=\"1\" min=\"0\" ...>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADD_MORE_EXAMPLE_IN_ACCURANCY_SETUP', 'string', NULL, 'admin', 'Adds a second rounding example (with qty 1.234) to the accuracy/rounding setup page in admin/limits.php.', 'Used once in admin/limits.php:324 to print an extra price-rounding example block (after the default example) on the accuracy setup screen. There is no admin UI write for it (ADMIN_UI blank in payload); it is a hidden/manual-only debug toggle read on that same page.', 'When set, the accuracy setup page (admin/limits.php) prints an additional worked example of price rounding using qty=1.234, useful for verifying rounding behavior; no other effect.', 'Boolean-like: any truthy value (getDolGlobalString truthy) shows the extra example; unset/falsy shows only the standard example.', 1, 0, 'admin/limits.php', 1, 'e2cc0918695582654d2ae6d5e089976e0ba0f2cf3498eebe587abd36415ed3c0', 'v2', '2026-07-24T07:05:23+00:00', '["admin/limits.php:324|check|if (getDolGlobalString(''MAIN_ADD_MORE_EXAMPLE_IN_ACCURANCY_SETUP'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADD_PDF_BACKGROUND', 'string', NULL, 'core', 'Specifies a background image file to overlay on generated PDF documents using FPDI.', 'Checked across 75 occurrences in PDF generation modules; some also require MAIN_DISABLE_FPDI to be unset (e.g. core/modules/stock/doc/pdf_standard_stock.modules.php:236). No admin UI write is present.', 'Setting this to a file path adds a background image to all generated PDFs; it has no effect if MAIN_DISABLE_FPDI is set.', 'String (path to background image file); empty or unset = no background image.', 1, 0, NULL, 1, '80913501eb3a1b10eeae780900eddbc4024ac7d00e554e4c0d4f58b3ea6178ea', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/stock/doc/pdf_standard_stock.modules.php:236|check|if (!getDolGlobalString(''MAIN_DISABLE_FPDI'') && getDolGlobalString(''MAIN_ADD_PDF_BACKGROUND'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:322|check|if (!getDolGlobalString(''MAIN_DISABLE_FPDI'') && getDolGlobalString(''MAIN_ADD_PDF_BACKGROUND'')) {", "recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:273|check|if (getDolGlobalString(''MAIN_ADD_PDF_BACKGROUND'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADD_SALE_REP_SIGNATURE_IN_NOTE', 'string', NULL, 'core', 'When enabled, appends the sales representative''s signature block to the note/footer section of generated PDF documents.', 'Checked in 9+ locations across multiple PDF generation modules: expense report, stock transfer, orders (einstein, eratosthene), invoices (octopus, sponge), supplier proposal (aurore), proposal (cyan). In each module the same check triggers signature inclusion.', 'Enabling causes sales rep signatures to appear in PDF notes across all supported document types. Disabling omits signatures from PDFs.', 'Truthy = include sales rep signature in PDF note section; empty/unset = no signature added.', 1, 0, NULL, 1, 'f586144955460cf783f6396eb2e54cd2b33769fe694088cf8d3acc06375b06fe', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/expensereport/doc/pdf_standard_expensereport.modules.php:325|check|if (getDolGlobalString(''MAIN_ADD_SALE_REP_SIGNATURE_IN_NOTE'')) {", "core/modules/commande/doc/pdf_einstein.modules.php:356|check|if (getDolGlobalString(''MAIN_ADD_SALE_REP_SIGNATURE_IN_NOTE'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:2758|check|if (getDolGlobalString(''MAIN_ADD_SALE_REP_SIGNATURE_IN_NOTE'')) {", "core/modules/propale/doc/pdf_cyan.modules.php:392|check|if (getDolGlobalString(''MAIN_ADD_SALE_REP_SIGNATURE_IN_NOTE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADMIN_TOOLS_EXPORT_FILES_EXEC_TIME_LIMIT', 'string', NULL, 'admin', 'PHP execution time limit (in seconds) applied while running the admin ''Export files/database backup'' tool.', 'Used in admin/tools/export_files.php:102: `$ExecTimeLimit = getDolGlobalInt(''MAIN_ADMIN_TOOLS_EXPORT_FILES_EXEC_TIME_LIMIT'', 1800);; // 30mn`, then applied via `@set_time_limit($ExecTimeLimit)` if non-empty. This is a UI page, so hidden_setting_int is 0 even though there is no dedicated settings form field — it is directly usable/effective from that admin page.', 'Increasing the value allows the export/backup process to run longer before PHP kills it (useful for large databases); default is 1800 seconds (30 minutes).', 'Integer number of seconds passed to PHP''s set_time_limit(); default 1800 (30 minutes); 0/empty leaves the normal PHP execution time limit unchanged (the set_time_limit call is skipped).', 0, 0, 'admin/tools/export_files.php', 1, 'c0480e76257ba69e6b36d83da016896f2da52aa6e45fb763e76b453be33a630b', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/export_files.php:102: $ExecTimeLimit = getDolGlobalInt(''MAIN_ADMIN_TOOLS_EXPORT_FILES_EXEC_TIME_LIMIT'', 1800);; // 30mn"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ADMIN_TOOLS_PURGE_EXEC_TIME_LIMIT', 'string', NULL, 'admin', 'PHP execution time limit (in seconds) applied while running the admin ''Purge'' tool (delete temp/all files).', 'Used in admin/tools/purge.php:69: `$ExecTimeLimit = getDolGlobalInt(''MAIN_ADMIN_TOOLS_PURGE_EXEC_TIME_LIMIT'', 600);`, then applied via `@set_time_limit($ExecTimeLimit)` if non-empty, before calling `$utils->purgeFiles($choice, $nbsecondsold)`.', 'Increasing the value allows the purge operation (deleting temp files or all documents) to run longer before PHP''s execution time limit kills it; default is 600 seconds (10 minutes).', 'Integer number of seconds passed to PHP''s set_time_limit(); default 600; 0/empty leaves the normal PHP execution time limit unchanged.', 0, 0, 'admin/tools/purge.php', 1, '31a223ae1cb34259fe62443d7b96b02633b1a60ab040f2181eeacf5306afe9e3', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/purge.php:69: $ExecTimeLimit = getDolGlobalInt(''MAIN_ADMIN_TOOLS_PURGE_EXEC_TIME_LIMIT'', 600);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AGENDA_EXPORT_CACHE', 'string', NULL, 'core', 'Sets the cache duration in seconds for the public agenda iCal/vCal export feed.', 'Written via admin/agenda_xcal.php:82 and read in core/lib/xcal.lib.php:75-78 where it is checked (must be > 60) and decomposed into hours, minutes, seconds via convertSecondToTime. Also checked in public/agenda/agendaexport.php:295-296 to determine the cache delay.', 'If set to a value greater than 60, the exported calendar feed is cached for that many seconds, reducing database load for frequent subscribers. If unset or 60 or below, caching is not applied.', 'Integer number of seconds. Must be > 60 for caching to activate (per core/lib/xcal.lib.php:75 check). 0 or unset = no cache.', 0, 0, 'admin/agenda_xcal.php|admin/agenda_xcal.php', 1, '93151c0f650493e2903f80ba4b4f9023222083087261a373b4d0eaa0256089ed', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/xcal.lib.php:75|check|if (getDolGlobalString(''MAIN_AGENDA_EXPORT_CACHE'') && getDolGlobalInt(''MAIN_AGENDA_EXPORT_CACHE'') > 60) {", "core/lib/xcal.lib.php:76|read|$hh = convertSecondToTime(getDolGlobalInt(''MAIN_AGENDA_EXPORT_CACHE''), \"hour\");", "public/agenda/agendaexport.php:295|check|if (getDolGlobalString(''MAIN_AGENDA_EXPORT_CACHE'')) {", "admin/agenda_xcal.php:82|write|$i += dolibarr_set_const($db, ''MAIN_AGENDA_EXPORT_CACHE'', $MAIN_AGENDA_EXPORT_CACHE, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AGENDA_EXPORT_PAST_DELAY', 'string', NULL, 'admin', 'Sets the number of days into the past that agenda events are included in the iCal export.', 'Configured via admin/agenda_xcal.php (dolibarr_set_const at line 81). Read at admin/agenda_xcal.php:56 with a default of 100 days, and at public/agenda/agendaexport.php:154 where it filters events not older than the delay.', 'Increasing this value includes older past events in the exported calendar feed; decreasing it trims older events from the export.', 'Positive integer (days); default = 100.', 0, 0, 'admin/agenda_xcal.php|admin/agenda_xcal.php', 1, '1ca77892b1aac7fcf0118f549252e5a22b6978cd0ecbc97bba390444fb426c09', 'v2', '2026-04-21T13:50:40+00:00', '["admin/agenda_xcal.php:56|read|$MAIN_AGENDA_EXPORT_PAST_DELAY = getDolGlobalInt(''MAIN_AGENDA_EXPORT_PAST_DELAY'', 100);", "admin/agenda_xcal.php:81|write|$i += dolibarr_set_const($db, ''MAIN_AGENDA_EXPORT_PAST_DELAY'', $MAIN_AGENDA_EXPORT_PAST_DELAY, ''chaine'', 0, '''', $conf->entity);", "public/agenda/agendaexport.php:154|read|$filters[''notolderthan''] = getDolGlobalInt(''MAIN_AGENDA_EXPORT_PAST_DELAY'', 100);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AGENDA_XCAL_EXPORTKEY', 'string', NULL, 'admin', 'Secret key that authenticates public iCal/vCal/RSS agenda export URLs.', 'Comment in core/modules/modAgenda.class.php:108: "Securekey for the public link". Read in admin/agenda_xcal.php:55 and written at line 80. Used in admin/agenda_xcal.php:197-226 to construct public export URLs containing the key as the exportkey parameter.', 'Changing this key invalidates all previously shared public agenda export URLs. Clearing it disables key-based access control for the export feed.', 'Arbitrary string (secret key). Example default from comment: "123456".', 0, 0, 'admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php|admin/agenda_xcal.php', 1, '72cfe3939f60a4c9154c96d5aca1c16a395b7fa0bd154cde045bba3648975657', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/modAgenda.class.php:108  //$this->const[] = array(\"MAIN_AGENDA_XCAL_EXPORTKEY\", \"chaine\", \"123456\", \"Securekey for the public link\");", "admin/agenda_xcal.php:80|write|$i += dolibarr_set_const($db, ''MAIN_AGENDA_XCAL_EXPORTKEY'', $MAIN_AGENDA_XCAL_EXPORTKEY, ''chaine'', 0, '''', $conf->entity);", "admin/agenda_xcal.php:202|check|if (getDolGlobalString(''MAIN_AGENDA_XCAL_EXPORTKEY'')) {", "admin/agenda_xcal.php:197|read|$urlvcal = ''<a href=\"''.$urlwithroot.''/public/agenda/agendaexport.php?format=vcal''.$getentity.''&exportkey=''.urlencode(getDolGlobalString(''MAIN_AGENDA_XCAL_EXPORTKEY'', ''...'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_AUTOMATIC_CONCILIATION', 'bool', NULL, 'core', 'Enables display of automatic (vs manual) bank statement conciliation mode on bank account tabs.', 'Read via getDolGlobalBool in core/lib/bank.lib.php:58 inside bank_prepare_head(), guarded by a `// TODO` comment, to decide whether the conciliation tab link/title shows a manual/auto distinction.', 'When true, the conciliate tab labels append ''(Manual)''/''(Auto)'' distinctions; the code is marked TODO so the feature may be incomplete [SPECULATION].', 'Boolean: true/1 enables the automatic-conciliation label distinction, false/unset (default) shows plain ''Conciliate'' label.', 1, 0, NULL, 1, 'c204ccb128b8cdbb7dfa4360eeaf52e0e62467d05dd743d3db0fbed344968ef0', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/bank.lib.php:58|read|$allowautomaticconciliation = getDolGlobalBool(''MAIN_ALLOW_AUTOMATIC_CONCILIATION''); // TODO"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_BACKUP_BY_EMAIL', 'bool', NULL, 'core', 'Gates whether the built-in cron job that emails a local database backup (''MakeSendLocalDatabaseDump'') is allowed to run.', 'Used as part of the ''test'' condition for cron job #2 in core/modules/modCron.class.php:100: the job only runs if getDolGlobalString(''MAIN_ALLOW_BACKUP_BY_EMAIL'') is true and the DB type is mysqli.', 'Enabling it allows the scheduled job that sends a local database dump by email to actually execute (it is disabled by ''status''=>0 by default, and additionally gated by this constant plus MySQL-only support).', 'Boolean: truthy enables the send-backup-by-email cron job to run (subject to also being mysqli and job status enabled).', 1, 0, NULL, 1, 'ab65fea599424c63d40b0c9a3b56d1ec90d7fc34f260f7625e6022e7465c2ce4', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modCron.class.php:100|read|...''test''=>''getDolGlobalString(\"MAIN_ALLOW_BACKUP_BY_EMAIL\") && getDolDBType() == \\''mysqli\\'''')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_INTEGRITY_CHECK_ON_UNSTABLE', 'bool', NULL, 'blockedlog', 'Forces the file-integrity check tool (blockedlog/admin/filecheck.php) to allow comparing against the remote signature file even when running an unstable (beta/alpha/rc) Dolibarr version.', 'Read in blockedlog/admin/filecheck.php:185, ADMIN_UI blockedlog/admin/filecheck.php. Without it, remote check is force-disabled whenever DOL_VERSION matches beta|alpha|rc.', 'Setting it true re-enables the remote integrity check ($enableremotecheck stays true) on unstable versions, where it would otherwise be automatically disabled because no official signature file exists for that version.', 'Boolean-like: truthy overrides the automatic disabling of remote integrity check on beta/alpha/rc versions.', 0, 0, 'blockedlog/admin/filecheck.php', 1, '59ef47aff5af14d7a617493a37c3b3e288b9cdb0e68a776b612f2affb81945fb', 'v2', '2026-07-24T07:05:23+00:00', '["blockedlog/admin/filecheck.php:185: if (preg_match(''/beta|alpha|rc/i'', DOL_VERSION) || getDolGlobalString(''MAIN_ALLOW_INTEGRITY_CHECK_ON_UNSTABLE'')) { $enableremotecheck = false; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_LINK_STARTING_WITH_FILE', 'bool', NULL, 'core', 'Allows links starting with the ''file://'' protocol to be used as external links on Dolibarr objects.', 'Checked in core/actions_linkedfiles.inc.php:125 and :232 to permit or block file:// URLs when adding linked files. Displayed in admin/system/security.php:1032 as a security information item.', 'When unset, file:// links are rejected for security; when set, file:// links are accepted as external links.', 'Bool-like string: empty/unset = file:// links blocked; non-empty = file:// links allowed.', 0, 0, 'admin/system/security.php', 1, '9eb5badadf2f29f070cd6f37cea69a7403bb67e6cca6fe43d25ae180dae8a710', 'v2', '2026-04-21T13:50:40+00:00', '["core/actions_linkedfiles.inc.php:125|read|&& (substr($link, 0, 7) != ''file://'' || !getDolGlobalString(''MAIN_ALLOW_LINK_STARTING_WITH_FILE''))) {", "core/actions_linkedfiles.inc.php:232|read|&& (substr($link->url, 0, 7) != ''file://'' || !getDolGlobalString(''MAIN_ALLOW_LINK_STARTING_WITH_FILE''))) {", "admin/system/security.php:1032|read|print ''<strong>MAIN_ALLOW_LINK_STARTING_WITH_FILE</strong> = ''.getDolGlobalString(''MAIN_ALLOW_LINK_STARTING_WITH_FILE'', ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_LOCAL_LINKS_AS_EXTERNAL_LINKS', 'bool', NULL, 'core', 'Intended to allow local (non-external) URLs to be accepted as external hyperlinks on records; currently referenced but the actual host/IP validation is unimplemented.', 'Read in core/actions_linkedfiles.inc.php:141, guarding a branch whose body is only a ''TODO'' comment (no isIPAllowed()-based check implemented yet). Referenced as a bare comment marker (no active print) at admin/system/security.php:1063.', 'As currently coded, setting or not setting this constant has no functional effect since the code path only contains a TODO and performs no check either way. [SPECULATION]', 'Exact behavior unclear from code alone -- the intended semantics (block local links unless set) are documented in the surrounding comment but not implemented.', 1, 0, NULL, 1, '6203e7fef06b6ef0f4dc4081d412bd92db9026a39ce8f4368db8bb35529d103c', 'v2', '2026-07-24T07:05:23+00:00', '["core/actions_linkedfiles.inc.php:141: if (!getDolGlobalString(''MAIN_ALLOW_LOCAL_LINKS_AS_EXTERNAL_LINKS'')) { // Test $newUrlAray[''host''] ... TODO", "admin/system/security.php:1063: // MAIN_ALLOW_LOCAL_LINKS_AS_EXTERNAL_LINKS"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_OBFUSCATION_METHODS_IN_DOL_EVAL', 'bool', NULL, 'core', 'Allows PHP functions that can obfuscate callable names to be used inside dol_eval expressions.', 'Checked at core/lib/functions.lib.php:12374 and 12451. The comment at line 12451 states ''We disallow all function that allow to obfuscate the real name of a function''. When this constant is absent or falsy, such functions are blocked. Displayed in admin/system/security.php:1035.', 'Enabling this constant is a security risk as it permits obfuscation techniques inside evaluated expressions; disabling it (the default) blocks those techniques.', '0 or empty = obfuscation functions blocked in dol_eval; any truthy value = obfuscation functions permitted', 0, 0, 'admin/system/security.php', 1, 'f33f867c3b1d33c20c9ed0addeedd20081eb49735a5ab220288b6185eb78a1be', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:12451|check|if (!getDolGlobalString(''MAIN_ALLOW_OBFUSCATION_METHODS_IN_DOL_EVAL'')) {\t// We disallow all function that allow to obfuscate the real name of a function", "core/lib/functions.lib.php:12374|check|if (!getDolGlobalString(''MAIN_ALLOW_OBFUSCATION_METHODS_IN_DOL_EVAL'')) {", "admin/system/security.php:1035|read|print ''<strong>MAIN_ALLOW_OBFUSCATION_METHODS_IN_DOL_EVAL</strong> = ''.getDolGlobalString(''MAIN_ALLOW_OBFUSCATION_METHODS_IN_DOL_EVAL'', ''<span class=\"opacitymedium\">''.$langs->trans"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_OLD_VAR_OBJ_IN_DOL_EVAL', 'bool', NULL, 'core', 'Permits legacy $object and $obj variable references inside dol_eval expressions.', 'Checked at core/lib/functions.lib.php:11988 and 12270. When set, the eval context includes older-style variable names that were available in previous Dolibarr versions.', 'Enabling this constant restores backward-compatible variable names in evaluated expressions; disabling it enforces the stricter modern variable scope.', '0 or empty = old $object/$obj variables not allowed in dol_eval; any truthy value = old variable names permitted', 1, 0, NULL, 1, 'e5bc21b41c75aca4c271e97a358f65e35dc9471ad7f89cd45a176a111154d8ab', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:11988|check|if (getDolGlobalString(''MAIN_ALLOW_OLD_VAR_OBJ_IN_DOL_EVAL'')) {", "core/lib/functions.lib.php:12270|check|if (getDolGlobalString(''MAIN_ALLOW_OLD_VAR_OBJ_IN_DOL_EVAL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_SVG_FILES_AS_EXTERNAL_LINKS', 'bool', NULL, 'core', 'Allows SVG files to be attached as external hyperlinks on records, which are otherwise rejected for XSS-risk reasons.', 'Read in core/actions_linkedfiles.inc.php:133, guarding the external-link rejection for .svg URLs when adding a link via GETPOST(''linkit''). Its current value is displayed (read-only) on the admin/system/security.php:1053 security diagnostics page alongside a recommended-value hint, but that page does not provide a form to set it -- it must be defined in conf.php.', 'When set (non-empty), links to external .svg files are accepted without the ErrorSVGFilesNotAllowedAsLinksWithout error; when unset (default), such links are rejected because SVG can carry executable script content.', 'Recommended per admin page comment: ''Undefined'' or ''0'' (i.e. leave disabled); truthy value allows SVG external links.', 1, 0, 'admin/system/security.php', 1, 'e928df02fa508d51712cce4fea74b1b09641d173d9ce07c2c62601f97fb7194d', 'v2', '2026-07-24T07:05:23+00:00', '["core/actions_linkedfiles.inc.php:133: if (!getDolGlobalString(''MAIN_ALLOW_SVG_FILES_AS_EXTERNAL_LINKS'')) { if (...preg_match(''/\\.svg$/i'', ...)) { ... ErrorSVGFilesNotAllowedAsLinksWithout ...", "admin/system/security.php:1053: print ''<strong>MAIN_ALLOW_SVG_FILES_AS_EXTERNAL_LINKS</strong> = ''.getDolGlobalString(...).'' (Recommended: Undefined or 0)'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_SVG_FILES_AS_IMAGES', 'bool', NULL, 'core', 'Enables SVG files to be accepted and rendered as images throughout Dolibarr.', 'Visible in admin/system/security.php:811 with a default display value of ''0''. When enabled, SVG is allowed in the file manager connector (core/filemanagerdol/connectors/php/config.inc.php:172) and in image processing (core/lib/images.lib.php:71, core/lib/functions.lib.php:13838).', 'Enabling this allows SVG uploads and rendering; because SVG can contain active content, this has security implications noted in the security admin page.', '0 = SVG files not accepted as images; 1 = SVG files accepted as images', 0, 0, 'admin/system/security.php', 1, 'be62ab15348f3e87a480bf97e224db427c6c1afadd22fe3e1a996c9de1dca4ca', 'v2', '2026-04-21T11:16:15+00:00', '["admin/system/security.php:811|read|print ''<strong>MAIN_ALLOW_SVG_FILES_AS_IMAGES</strong> = ''.getDolGlobalString(''MAIN_ALLOW_SVG_FILES_AS_IMAGES'', ''0'')", "core/lib/images.lib.php:71|check|if ($acceptsvg || getDolGlobalString(''MAIN_ALLOW_SVG_FILES_AS_IMAGES'')) {", "core/filemanagerdol/connectors/php/config.inc.php:172|check|if (getDolGlobalString(''MAIN_ALLOW_SVG_FILES_AS_IMAGES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_UNSECURED_FALLBACK_FOR_SELECTOBJECT', 'bool', NULL, 'core', 'Allows the generic object-selector AJAX endpoint to instantiate an arbitrary class from a caller-supplied class path when the normal fetchObjectByElement() lookup fails.', 'Read in core/ajax/selectobject.php:125, guarding a fallback branch that dol_include_once()''s $classpath (derived from the $objectdesc GET/POST parameter) and does ''new $classname($db)'' if the class exists.', 'When set, an unresolved object element falls back to dynamically including and instantiating a class from a path effectively controlled by the request, which the code explicitly labels ''unsecured''; disabling it (default) removes this fallback so only fetchObjectByElement()-resolvable objects are usable.', 'Truthy string enables the unsecured classpath-based fallback; empty/unset (recommended default) disables it.', 1, 0, NULL, 1, 'b2b572cd138b6e8d9cf653697eb57ba7d9f62109317469f505f950f291ba5dfb', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectobject.php:125: if (getDolGlobalString(\"MAIN_ALLOW_UNSECURED_FALLBACK_FOR_SELECTOBJECT\") && empty($objecttmp) && !empty($classpath) && preg_match(''/\\.class\\.php$/'', $classpath)) {", "core/ajax/selectobject.php:126: dol_include_once($classpath); if ($classname && class_exists($classname)) { $objecttmp = new $classname($db); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_WYSIWYG_EVEN_ON_UNSECURED_EXTERNAL_HTTP_URL', 'bool', NULL, 'core', 'Allows local media links in email/WYSIWYG content even when the instance''s public URL is plain HTTP (not HTTPS).', 'In core/lib/functions2.lib.php:2945-2946, inside acceptLocalLinktoMedia(), if this int is falsy and the instance''s public URL matches ''http:'' (not https), the code forces $acceptlocallinktomedia = 0 with a comment noting it would ''generate security alerts when email will be sent''; setting the constant skips this downgrade.', 'Enabling it permits local media links to be added to WYSIWYG/email HTML content even when the site''s configured URL is insecure HTTP, at the risk of the security concern noted in the code comment; unset/false blocks such links on HTTP-only sites.', 'true/1 (int) = allow local media links even on HTTP-only public URL; false/unset (default) = block local media links when public URL is HTTP.', 1, 0, NULL, 1, 'f752905619d3b563f37bf5438f2d6cacf56f8b696e4ff6b453c7f61aecda9123', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions2.lib.php:2945|read|$allowUrlInHTTP = getDolGlobalInt(''MAIN_ALLOW_WYSIWYG_EVEN_ON_UNSECURED_EXTERNAL_HTTP_URL'');", "core/lib/functions2.lib.php:2946: if (!$allowUrlInHTTP && preg_match(''/http:/i'', $urlwithouturlroot)) {", "core/lib/functions2.lib.php:2947: // If public url is not a https, we do not allow to add medias link. It will generate security alerts when email will be sent."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALLOW_WYSIWYG_LOCAL_MEDIAS_ON_PRIVATE_NETWORK', 'bool', NULL, 'core', 'Allows WYSIWYG editor content to embed local or private-network media URLs when set.', 'Read in core/lib/functions2.lib.php:2937; the comment at line 2919 explains: ''except if MAIN_ALLOW_WYSIWYG_LOCAL_MEDIAS_ON_PRIVATE_NETWORK is set, in which case we accept also if instance has a local or private network URL.'' The comment at line 2941 shows how to use this constant to allow local URLs.', 'Enabling this permits WYSIWYG content to reference private-network URLs for media, which is otherwise blocked as a security measure.', '0 or unset = local/private-network media URLs blocked in WYSIWYG; 1 = allowed.', 1, 0, NULL, 1, '6aaccbb2a488e922a6c1f381ed671cc799dce3e23cc006f0970f50aea84e88e8', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:2919  // except if MAIN_ALLOW_WYSIWYG_LOCAL_MEDIAS_ON_PRIVATE_NETWORK is net, in which case we accept also if instance has a local or private network URL.", "core/lib/functions2.lib.php:2941  //dol_syslog(\"WYSIWYG Editor : local media not allowed (checked IP: {$iptocheck}). Use MAIN_ALLOW_WYSIWYG_LOCAL_MEDIAS_ON_PRIVATE_NETWORK = 1 to allow local URL into WYSIWYG html content\");", "core/lib/functions2.lib.php:2937|read|$allowPrivateNetworkIP = getDolGlobalInt(''MAIN_ALLOW_WYSIWYG_LOCAL_MEDIAS_ON_PRIVATE_NETWORK'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALL_TOWN_TO_UPPER', 'string', NULL, 'core', 'Forces the address and town fields to full uppercase on save.', 'Checked in core/class/commonpeople.class.php:407 inside setUpperOrLowerCase(): `$this->address = dol_strtoupper($this->address ?? ''''); $this->town = dol_strtoupper($this->town ?? '''');`.', 'When set, address and town values are stored in ALL CAPS; independent of the name-casing constants (MAIN_FIRST_TO_UPPER / MAIN_ALL_TO_UPPER) which affect name fields only.', 'Truthy/falsy flag.', 1, 0, NULL, 1, '1b457601cee48245dff6a742394b44597fb3a1f5e5b144a66112712601915623', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonpeople.class.php:407|check|if (getDolGlobalString(''MAIN_ALL_TOWN_TO_UPPER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALL_TO_UPPER', 'string', NULL, 'core', 'Forces lastname, name and name_alias to full uppercase on save.', 'Checked in core/class/commonpeople.class.php:400 inside setUpperOrLowerCase(): when set, `$this->lastname = dol_strtoupper($this->lastname); $this->name = dol_strtoupper($this->name);` and name_alias likewise.', 'When set, person/company name fields are stored in ALL CAPS; distinct from MAIN_FIRST_TO_UPPER (Title Case) and MAIN_ALL_TOWN_TO_UPPER (address/town only).', 'Truthy/falsy flag.', 1, 0, NULL, 1, '2b458b3f48641f52a25219b79af6a3cb7a31f6e0eb842607437941c48b3a5785', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonpeople.class.php:400|check|if (getDolGlobalString(''MAIN_ALL_TO_UPPER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ALWAYS_CREATE_LOCK_AFTER_LAST_UPGRADE', 'string', NULL, 'core', 'Forces creation of the install.lock file after every upgrade, regardless of whether the version is the latest.', 'When enabled, Dolibarr creates the install.lock file after upgrade completion even if not on the last version. Referenced in install/step5.php:524 and install/step5.php:574 and displayed in admin/system/security.php:814.', 'Enabling this constant ensures the install directory is locked after every upgrade step, preventing re-execution of the installer.', 'Empty/not set = lock only created on last version upgrade; any non-empty value = always create lock', 0, 0, 'admin/system/security.php', 1, 'f6aa3e4d32f347156ab69b0b4e380ff7dedf49096612e30a272ce10b2db84a7d', 'v2', '2026-04-21T11:16:15+00:00', '["install/step5.php:359  // The install.lock file is created few lines later if version is last one or if option MAIN_ALWAYS_CREATE_LOCK_AFTER_LAST_UPGRADE is on", "install/step5.php:524|check|if (!empty($force_install_lockinstall) || getDolGlobalString(''MAIN_ALWAYS_CREATE_LOCK_AFTER_LAST_UPGRADE'')) {", "install/step5.php:574|check|if (!empty($force_install_lockinstall) || getDolGlobalString(''MAIN_ALWAYS_CREATE_LOCK_AFTER_LAST_UPGRADE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ANONYMIZE_USER_FULLNAME', 'string', NULL, 'core', 'Replaces a person''s full name with a masked placeholder (''***'') wherever the anonymisable full name accessor is used.', 'Checked in core/class/commonpeople.class.php:143 inside getAnonymisableFullName(): `if (getDolGlobalInt(''MAIN_ANONYMIZE_USER_FULLNAME'') == 1) { return ''***''; }`, otherwise falls back to the normal getFullName() output.', 'Setting the value to 1 makes any code calling getAnonymisableFullName() display ''***'' instead of the person''s real civility/first/last name, for privacy/anonymization purposes.', '1 = anonymize (return ''***''); any other value/unset = show real full name (per the strict `== 1` comparison in code).', 1, 0, NULL, 1, '97e0e3e5e82fb5f76ba25225407aaf66f79b76bd57273819802fe0ca54bed82b', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonpeople.class.php:143|check|if (getDolGlobalInt(''MAIN_ANONYMIZE_USER_FULLNAME'') == 1) {", "core/class/commonpeople.class.php|return ''***'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ANTIVIRUS_ALLOW_JS_IN_PDF', 'bool', NULL, 'core', 'Disables Dolibarr''s built-in check that rejects uploaded PDF files containing embedded JavaScript.', 'Used in core/lib/files.lib.php:1464 inside dolCheckOnFileName(), which scans destination files whose name matches *.pdf for a ''/JavaScript'' marker; if the constant is not set, a match returns the error ''File is a PDF with javascript inside'' and blocks the file.', 'Setting it truthy disables the JS-in-PDF scan entirely (logged as ''Check js into pdf disabled''), allowing PDFs containing JavaScript to be uploaded/accepted; leaving it unset keeps the security check active.', 'Boolean-like: truthy disables the JS-in-PDF security scan; falsy/unset (default) keeps the scan active and blocks PDFs containing ''/JavaScript''.', 1, 0, NULL, 1, 'abd4158d9a734513aad1fa54384ba36174a1ee4d0ac07afea764ed425a08f7f7', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/files.lib.php:1464|check|if (!getDolGlobalString(''MAIN_ANTIVIRUS_ALLOW_JS_IN_PDF'')) {", "if (preg_match(''/[\\n\\s]+\\/JavaScript[\\n\\s]+/m'', $tmp)) { return array(''File is a PDF with javascript inside''); }", "dol_syslog(\"dolCheckOnFileName Check js into pdf disabled\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ANTIVIRUS_COMMAND', 'string', NULL, 'admin', 'Path to the antivirus executable used to scan uploaded files.', 'Written via admin/security_file.php:104 and read in core/class/antivir.class.php:138 with default ''/usr/bin/clamdscan''. Also read in admin/security_file.php:251 to derive the base directory of the command. Shown in admin/system/security.php:621.', 'Changing this constant redirects file scanning to the specified antivirus binary. If unset, the system defaults to /usr/bin/clamdscan.', 'File path string to the antivirus binary. Default: ''/usr/bin/clamdscan''.', 0, 0, 'admin/security_file.php|admin/security_file.php|admin/system/security.php|admin/system/security.php|admin/security_file.php|admin/security_file.php', 1, '27060c83284ab85fd896778ad66d9d81120b3d7e93073034a55434e1a5903e48', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/antivir.class.php:138|read|$command = getDolGlobalString(''MAIN_ANTIVIRUS_COMMAND'', ''/usr/bin/clamdscan'');", "admin/security_file.php:104|write|$res5 = dolibarr_set_const($db, \"MAIN_ANTIVIRUS_COMMAND\", trim($antivircommand), ''chaine'', 0, '''', $conf->entity);", "admin/security_file.php:251|read|$basedir = preg_replace(''/''.''\"/'', '''', dirname($conf->global->MAIN_ANTIVIRUS_COMMAND));", "admin/system/security.php:621|read|print '' &nbsp; - '' . getDolGlobalString(''MAIN_ANTIVIRUS_COMMAND'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ANTIVIRUS_PARAM', 'string', NULL, 'admin', 'Command-line parameters passed to the antivirus binary when scanning an uploaded file.', 'Written via admin/security_file.php:105 and read in core/class/antivir.class.php:139 and :148. Line 148 checks whether the param string contains %file (the placeholder for the scanned file path).', 'If the parameter string does not contain %file, the antivirus scan invocation will not include the target file path, rendering scanning ineffective. Correct parameters must include %file.', 'String of CLI arguments for the antivirus command. Must contain ''%file'' as placeholder for the uploaded file path.', 0, 0, 'admin/security_file.php|admin/security_file.php', 1, 'e311b0577c3378b458ae14671cc0eebf476735becf558603aa01c66df6a64b21', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/antivir.class.php:139|read|$param = getDolGlobalString(''MAIN_ANTIVIRUS_PARAM'');", "core/class/antivir.class.php:148|check|if (!preg_match(''/%file/'', getDolGlobalString(''MAIN_ANTIVIRUS_PARAM''))) {", "admin/security_file.php:105|write|$res6 = dolibarr_set_const($db, \"MAIN_ANTIVIRUS_PARAM\", trim($antivirparam), ''chaine'', 0, '''', $conf->entity);", "admin/security_file.php:271|read|print ''<input type=\"text\" ''.(defined(''MAIN_ANTIVIRUS_PARAM'') ? ''disabled '' : '''').''name=\"MAIN_ANTIVIRUS_PARAM\"...''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ANTIVIRUS_UPLOAD_ON', 'string', NULL, 'admin', 'Enables antivirus scanning of uploaded files.', 'Checked in admin/security_file.php:233 and :242, and in core/lib/files.lib.php:1394 via getDolGlobalString(''MAIN_ANTIVIRUS_UPLOAD_ON''). Also displayed in admin/system/security.php:616-617 as a yes/no indicator.', 'When enabled, every uploaded file is scanned using the command defined in MAIN_ANTIVIRUS_COMMAND. When disabled, uploads bypass antivirus scanning.', 'Non-empty string = antivirus scanning enabled. Empty/unset = scanning disabled.', 0, 0, 'admin/security_file.php|admin/security_file.php|admin/system/security.php|admin/system/security.php|admin/system/security.php', 1, '6b23fc1a9ff6415d98090292ce3a4b165a27381158d7010d165d769b033debcc', 'v2', '2026-04-21T13:29:58+00:00', '["admin/security_file.php:233|check|if (!getDolGlobalString(''MAIN_ANTIVIRUS_UPLOAD_ON'')) {", "admin/security_file.php:242|check|if (getDolGlobalString(''MAIN_ANTIVIRUS_UPLOAD_ON'')) {", "core/lib/files.lib.php:1394|check|if (getDolGlobalString(''MAIN_ANTIVIRUS_UPLOAD_ON'')) {", "admin/system/security.php:617|read|print yn(!getDolGlobalString(''MAIN_ANTIVIRUS_UPLOAD_ON'') ? 0 : 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_API_DEBUG', 'string', NULL, 'api', 'When set to 1, enables saving of API request/response logs into the file ''dolibarr_api.log''.', 'Checked in api/index.php (lines 195, 443) and api/class/api.class.php:70. The comment at api/index.php:194 documents the behavior explicitly.', 'When enabled, API activity is logged to dolibarr_api.log; when disabled, no API-specific log file is written.', 'Integer: 1 to enable API debug logging; 0 or unset to disable.', 1, 0, NULL, 1, '35d781ad3d22b4349fb5470f529bc977d606d2e4802c17bfed9d47097430c12a', 'v2', '2026-04-21T11:16:15+00:00', '["// If MAIN_API_DEBUG is set to 1, we save logs into file \"dolibarr_api.log\"", "api/index.php:195|check|if (getDolGlobalString(''MAIN_API_DEBUG'')) {", "api/class/api.class.php:70|check|if (getDolGlobalString(''MAIN_API_DEBUG'')) {", "api/index.php:443|check|if (getDolGlobalString(''MAIN_API_DEBUG'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_API_KEY', 'string', NULL, 'api', 'Server-side secret mixed into the hash used to generate a user''s API token.', 'Used in api/class/api_login.class.php:161: `dol_hash($login.bin2hex(random_bytes(32)).getDolGlobalString(''MAIN_API_KEY''), ''hash'')` when generating/resetting a user''s api_key, alongside the login and a random 32-byte value.', 'Setting/changing this value contributes additional entropy/secret material to newly generated API tokens; it does not affect already-generated tokens stored in the database.', 'String, an arbitrary secret value used as extra hash input.', 0, 0, NULL, 1, '03bd9b8a234b57e4ed201aed662a680009191564d1f7b424739d026a0667774d', 'v2', '2026-07-24T07:05:23+00:00', '["api/class/api_login.class.php:161|$token = dol_hash($login.bin2hex(random_bytes(32)).getDolGlobalString(''MAIN_API_KEY''), ''hash'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_APPLICATION_TITLE', 'string', NULL, 'public', 'Sets a custom application title/branding string used in the page title and various public-facing pages instead of the default ''Dolibarr''.', 'Set via admin/security_other.php:80 (dolibarr_set_const, ''alphanohtml'') and read via getDolGlobalString(''MAIN_APPLICATION_TITLE'') in dozens of locations including public/members/new.php:534, public/website/javascript.js.php:112, public/website/index.php:195, public/website/styles.css.php:112, public/partnership/new.php:379, public/stripe/ipn.php:180, and theme/manifest.json.php:76.', 'Changing it replaces the application title shown across public pages, the website module output, and the PWA manifest, wherever the constant is set and non-empty.', NULL, 0, 0, 'admin/security_other.php', 1, 'f28362ca3e4578c68ac305e4387a8461c18113fa3d93e090194f2bd5d1f3603c', 'v2', '2026-07-24T06:41:12+00:00', '["admin/security_other.php:80|write|$res1 = dolibarr_set_const($db, \"MAIN_APPLICATION_TITLE\", GETPOST(\"MAIN_APPLICATION_TITLE\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "theme/manifest.json.php:76|check|if (getDolGlobalString(''MAIN_APPLICATION_TITLE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_APPLY_DISCOUNT_ON_UNIT_PRICE_THEN_ROUND_BEFORE_MULTIPLICATION_BY_QTY', 'string', NULL, 'core', 'Controls the rounding mode applied when computing a discounted unit price before multiplying by quantity in price calculations.', 'Checked via getDolGlobalString(...) in core/lib/price.lib.php:203 and used as the rounding-mode argument to price2num() at lines 205-206, with a comment noting it may need to be ''MU'' for e-invoicing recalculation.', 'Setting it (e.g. to ''MU'') changes the rounding parameter passed to price2num() when computing the discounted unit price, affecting how the per-line discount and total-with-discount are rounded before multiplying by quantity.', '''MU'' is mentioned as a value used for einvoice recalculation needs', 0, 0, NULL, 1, 'f48136e382eaf109ce90fefa98d9fa1a9365b902b478186d7a8c88699beefa24', 'v2', '2026-07-24T06:41:12+00:00', '["core/lib/price.lib.php:201  // Note: For einvoice, we may need to have MAIN_APPLY_DISCOUNT_ON_UNIT_PRICE_THEN_ROUND_BEFORE_MULTIPLICATION_BY_QTY = ''MU'' because, we must recalculate", "core/lib/price.lib.php:205|read|$pudiscount = (float) price2num($pu * ((float) $remise_percent_ligne / 100), getDolGlobalString(''MAIN_APPLY_DISCOUNT_ON_UNIT_PRICE_THEN_ROUND_BEFORE_MULTIPLICATION_BY_QTY''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ASK_CUSTOMER_REF_OF_PROPOSAL_AT_CREATION', 'string', NULL, 'comm', 'Shows an extra ''customer reference'' input field on the proposal creation form.', 'Checked in comm/propal/card.php:2470 (create form section, comment ''Reference of proposal on customer side''); when set, an input named ref_client is printed.', 'Enabling it lets users capture the customer''s own reference number for the proposal at creation time; leaving it off hides that field.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, '0fc2a1ed5461e4416f209475ca07fba1f648a28f064804e752a7d1fc1658a87a', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:2469: // Reference of proposal on customer side", "comm/propal/card.php:2470: if (getDolGlobalString(''MAIN_ASK_CUSTOMER_REF_OF_PROPOSAL_AT_CREATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ASK_CUSTOMER_REF_OF_SALE_ORDER_AT_CREATION', 'string', NULL, 'commande', 'Shows a ''customer reference'' input field on the sales order creation form.', 'Checked in commande/card.php:2345: if (getDolGlobalString(''MAIN_ASK_CUSTOMER_REF_OF_SALE_ORDER_AT_CREATION'') || getDolGlobalString(''MAIN_USE_PROPAL_REFCLIENT_FOR_ORDER'')) prints the RefCustomer/ref_client row on the creation form.', 'When enabled, the order creation form displays a field to enter the customer''s own reference for the order; when both this and MAIN_USE_PROPAL_REFCLIENT_FOR_ORDER are unset, the field is not shown at creation.', 'Boolean: 1/true shows the customer ref field at order creation.', 0, 0, NULL, 1, '44e4b3dbbb02a68d1d2f5a299722f5a90a38d4a8586de8af4d73eb75f25cba4b', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:2345: if (getDolGlobalString(''MAIN_ASK_CUSTOMER_REF_OF_SALE_ORDER_AT_CREATION'') || getDolGlobalString(''MAIN_USE_PROPAL_REFCLIENT_FOR_ORDER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ASK_SUPPLIER_REF_OF_PURCHASE_ORDER_AT_CREATION', 'string', NULL, 'fourn', 'Shows an extra ''RefSupplier'' input field on the supplier order creation form, to capture the vendor''s own reference for the purchase order at creation time.', 'Checked in fourn/commande/card.php:2020: `if (getDolGlobalString(''MAIN_ASK_SUPPLIER_REF_OF_PURCHASE_ORDER_AT_CREATION'')) { print ''<tr><td>''.$form->textwithpicto($langs->trans(''RefSupplier''), ...` which adds a ''refsupplier'' text input row to the creation form.', 'When enabled, users creating a supplier order see an extra text field to enter the supplier''s own reference for the order at creation; when disabled the field is not shown on that form.', 'Boolean: truthy adds the ''RefSupplier'' input field to the supplier order creation form.', 1, 0, NULL, 1, '2cf45c622c600e49cb928bb5964589f6cf493b1b764d7be8add81b3e30fbe601', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:2020|check|if (getDolGlobalString(''MAIN_ASK_SUPPLIER_REF_OF_PURCHASE_ORDER_AT_CREATION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_AUTHORIZE_URL', 'string', NULL, 'admin', 'Stores the OpenID Connect authorization endpoint URL used to initiate OIDC login.', 'Written by admin/openid_connect.php:87 and read in core/lib/openid_connect.lib.php:99 to build the OIDC authorization redirect URL. Configurable via admin/openid_connect.php.', 'Changing this value points the OIDC login flow to a different authorization server; an incorrect URL prevents OIDC authentication.', 'String: full HTTPS URL of the OIDC authorization endpoint.', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '07bcd761b166bed10bee79786efec6dbbe10bc159780350213e8822c368c829c', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:87|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_AUTHORIZE_URL'', $authorize_url, ''chaine'', 0, '''', 0);", "core/lib/openid_connect.lib.php:99|read|$url = getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_AUTHORIZE_URL'').''?client_id=''.urlencode(getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLIENT_ID'')).''&redirect_uri=''.urlencode(ope", "admin/openid_connect.php:286|read|print ''<input name=\"MAIN_AUTHENTICATION_OIDC_AUTHORIZE_URL\" ...''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_CLAIM_EMAIL', 'string', NULL, 'admin', 'Specifies the OIDC claim name used to extract the user''s email address from the identity token.', 'Written by admin/openid_connect.php:150 and read in core/lib/openid_connect.lib.php:121 with a default of ''email''. Configurable via admin/openid_connect.php.', 'Changing this value allows mapping a non-standard claim (e.g. a custom claim name) to the Dolibarr user''s email field; an incorrect value causes the email not to be populated after OIDC login.', 'String: OIDC claim name (default ''email'').', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '86eb0d9899eeefc3c22da1df4e2045b87a77af0e959f670177eba51ec45c3d8e', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:150|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_CLAIM_EMAIL'', $value, ''chaine'', 0, '''', 0);", "core/lib/openid_connect.lib.php:121|read|$claim_email = getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLAIM_EMAIL'', ''email'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_CLAIM_FIRSTNAME', 'string', NULL, 'admin', 'Specifies the OIDC claim name used to extract the user''s first name from the identity token.', 'Written by admin/openid_connect.php:136 and read in core/lib/openid_connect.lib.php:122 with a default of ''given_name''. Configurable via admin/openid_connect.php.', 'Changing this value maps a custom OIDC claim to the Dolibarr user''s firstname field; an incorrect claim name results in the firstname not being set after login.', 'String: OIDC claim name (default ''given_name'').', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '8bcd81ec566555dade1f595dd72443298cd1c59fa9f75d31bd0dd6295945c020', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:136|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_CLAIM_FIRSTNAME'', $value, ''chaine'', 0, '''', 0);", "core/lib/openid_connect.lib.php:122|read|$claim_firstname = getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLAIM_FIRSTNAME'', ''given_name'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_CLAIM_LASTNAME', 'string', NULL, 'admin', 'Specifies the OIDC claim name used to extract the user''s last name from the identity token.', 'Written by admin/openid_connect.php:143 and read in core/lib/openid_connect.lib.php:123 with a default of ''family_name''. Configurable via admin/openid_connect.php.', 'Changing this value maps a custom OIDC claim to the Dolibarr user''s lastname field; an incorrect claim name results in the lastname not being set after login.', 'String: OIDC claim name (default ''family_name'').', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '5c9ad80b2aaf44e0b09e9479e0669b214b90091f12a3e0dc9a7b8fa73dd3d8a9', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:143|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_CLAIM_LASTNAME'', $value, ''chaine'', 0, '''', 0);", "core/lib/openid_connect.lib.php:123|read|$claim_lastname = getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLAIM_LASTNAME'', ''family_name'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_CLIENT_ID', 'string', NULL, 'admin', 'Sets the OAuth2/OpenID Connect client ID used when authenticating users against an external OIDC identity provider.', 'Set via admin/openid_connect.php:66 (dolibarr_set_const) and read via getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLIENT_ID'') in user/logout.php:116, core/login/functions_openid_connect.php:94, and core/lib/openid_connect.lib.php:99, used to build the OIDC authorize/logout URLs.', 'Changing it changes the client_id parameter sent to the OIDC provider''s authorize and logout endpoints, which must match the registered client at the identity provider.', NULL, 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '4a33273db342705b2242e290862cab70c182cc9c4053f6f64eead165cd99c54f', 'v2', '2026-07-24T06:41:12+00:00', '["admin/openid_connect.php:257  // MAIN_AUTHENTICATION_OIDC_CLIENT_ID", "core/lib/openid_connect.lib.php:99|read|$url = getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_AUTHORIZE_URL'').''?client_id=''.urlencode(getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLIENT_ID'')).''&redirect_uri=''.urlencode(ope"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_CLIENT_SECRET', 'string', NULL, 'admin', 'Stores the OAuth2/OIDC client secret used to authenticate Dolibarr with the OpenID Connect provider.', 'Written via admin/openid_connect.php:73 and read in core/login/functions_openid_connect.php:95 as ''client_secret'' in the authentication parameter array. Displayed as a password input in admin/openid_connect.php:270.', 'Changing this secret invalidates the current OIDC provider handshake; the new secret must match what is registered at the identity provider.', 'Arbitrary secret string provided by the OIDC identity provider. Must be kept confidential.', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, 'a93ef1ca381ef29d2266dd42d6138aa1842ead9529a53553507b28969e6fe45e', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:73|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_CLIENT_SECRET'', $client_secret, ''chaine'', 0, '''', 0);", "core/login/functions_openid_connect.php:95|read|''client_secret'' => getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLIENT_SECRET''),", "admin/openid_connect.php:270|read|print ''<input type=\"password\" name=\"MAIN_AUTHENTICATION_OIDC_CLIENT_SECRET\"..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_DEFAULT_CREATOR', 'string', NULL, 'admin', 'Specifies the default Dolibarr user ID to assign as creator when a new user is provisioned via OpenID Connect.', 'Read in core/lib/openid_connect.lib.php:169 via getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_DEFAULT_CREATOR'', 1) to set the creator_id for new OIDC-provisioned accounts. Configured via admin/openid_connect.php where it is written with dolibarr_set_const.', 'Changing this value alters which user is recorded as the creator for all newly provisioned OIDC accounts. If unset, the fallback default of 1 (superadmin) is used.', 'Integer user ID. Falls back to 1 when not set (getDolGlobalInt default).', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '21f2845fe48ba79ffa5838f7a1962094d274ceb305f08bb2a3e0c3ab8123c0b1', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:129|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_DEFAULT_CREATOR'', $value, ''chaine'', 0, '''', 0);", "core/lib/openid_connect.lib.php:169|read|$creator_id = getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_DEFAULT_CREATOR'', 1);", "admin/openid_connect.php:361|read|$creator_val = GETPOSTISSET(''MAIN_AUTHENTICATION_OIDC_DEFAULT_CREATOR'') ? GETPOSTINT(''MAIN_AUTHENTICATION_OIDC_DEFAULT_CREATOR'') : getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_DEFAULT"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_DEFAULT_GROUP', 'string', NULL, 'admin', 'Specifies the default Dolibarr group ID to assign to a new user provisioned via OpenID Connect.', 'Read in core/lib/openid_connect.lib.php:190 via getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_DEFAULT_GROUP'') to determine the group for new OIDC accounts. Configured and written in admin/openid_connect.php.', 'Changing this value changes the group membership assigned to all newly created OIDC accounts. If unset, no default group is applied.', 'Integer group ID. No default applied when absent.', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, 'bc2f58db5c901802427771823cac08d1ba7948a349b5b298b01e906d6dd70e9c', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:122|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_DEFAULT_GROUP'', $value, ''chaine'', 0, '''', 0);", "core/lib/openid_connect.lib.php:190|read|$default_group = getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_DEFAULT_GROUP'');", "admin/openid_connect.php:370|read|$defaultgroup_val = GETPOSTISSET(''MAIN_AUTHENTICATION_OIDC_DEFAULT_GROUP'') ? GETPOSTINT(''MAIN_AUTHENTICATION_OIDC_DEFAULT_GROUP'') : getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_DEFAUL"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_LOGIN_CLAIM', 'string', NULL, 'admin', 'Selects which claim from the OIDC identity token is used as the Dolibarr login name.', 'Set via admin/openid_connect.php:59 (dolibarr_set_const) and read via getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_LOGIN_CLAIM'') in core/login/functions_openid_connect.php (135, 136).', 'Changing it changes which field of the OIDC token claims is mapped to the local login, affecting how OIDC users are matched to Dolibarr accounts.', NULL, 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '0f4f219499d0948951f10735dea524090c881f1c2d05484cb8680e6d44983683', 'v2', '2026-07-24T06:41:12+00:00', '["admin/openid_connect.php:249  // MAIN_AUTHENTICATION_OIDC_LOGIN_CLAIM", "core/login/functions_openid_connect.php:136|read|$login_claim = getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_LOGIN_CLAIM'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_LOGOUT_URL', 'string', NULL, 'admin', 'Stores the OpenID Connect provider''s logout endpoint URL used to redirect users on Dolibarr logout.', 'Configured via admin/openid_connect.php and consumed in user/logout.php:111-116, where it is appended with client_id and returnTo parameters to build the full OIDC logout redirect URL. Requires MAIN_AUTHENTICATION_OIDC_ON to be active.', 'Setting this URL enables single sign-out with the OIDC provider; leaving it empty means logout only clears the Dolibarr session without notifying the identity provider.', 'String; a valid HTTPS URL to the OIDC provider''s end_session_endpoint.', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, 'ed32bfd62cc78590ae9b12e9ede87106352296338b740c7121cd1b611208b512', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:108|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_LOGOUT_URL'', $logout_url, ''chaine'', 0, '''', 0);", "user/logout.php:111|check|if (getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_ON'', 0) > 0 && !empty($_SESSION[''OPENID_CONNECT'']) && getDolGlobalString(\"MAIN_AUTHENTICATION_OIDC_LOGOUT_URL\")) {", "user/logout.php:116|read|$url = getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_LOGOUT_URL'') . ''?client_id='' . getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLIENT_ID'') . ''&returnTo='' . urlencode($url);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_ON', 'string', NULL, 'core', 'Enables OpenID Connect (OIDC) authentication and shows the OIDC login button on the login page.', 'When set to a positive integer, core/tpl/login.tpl.php:181 and 452 render the OIDC login button if the openid_connect authentication method is configured. Also controls OIDC logout redirect at user/logout.php:111 and is required by core/login/functions_openid_connect.php:45. Configurable via admin/openid_connect.php.', 'Setting this to a positive integer activates OIDC login and logout integration; setting it to 0 or leaving it unset disables OIDC UI elements.', 'Positive integer = OIDC enabled and login button shown; 0 or unset = OIDC disabled.', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '17e30176e8498fa1b3e2758e4e29f7ff83078900d1f28fbf834d0e36e3235f4a', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/login.tpl.php:181|check|if (getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_ON'', 0) > 0 && isset($conf->file->main_authentication) && preg_match(''/openid_connect/'', $conf->file->main_authentication)) {", "core/login/functions_openid_connect.php:45|check|if (getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_ON'', 0) <= 0) {", "user/logout.php:111|check|if (getDolGlobalInt(''MAIN_AUTHENTICATION_OIDC_ON'', 0) > 0 && !empty($_SESSION[''OPENID_CONNECT'']) && getDolGlobalString(\"MAIN_AUTHENTICATION_OIDC_LOGOUT_URL\")) {", "admin/openid_connect.php:199|check|if (!getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_ON'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_SCOPES', 'string', NULL, 'admin', 'Stores the OAuth2 scopes requested during the OIDC authorization flow.', 'Written by admin/openid_connect.php:80 and included in the authorization URL built in core/lib/openid_connect.lib.php:99. Configurable via admin/openid_connect.php.', 'Changing the scopes alters what user information is requested from the identity provider; missing required scopes (e.g. ''openid'', ''email'') cause authentication failures.', 'Space-separated string of OAuth2 scope names (e.g. ''openid email profile'').', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '14df0627bc846be540bd50d63a0b7d3015b13234c6a10ded4ce771950a1ac985', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:80|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_SCOPES'', $scopes, ''chaine'', 0, '''', 0);", "core/lib/openid_connect.lib.php:99|read|$url = getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_AUTHORIZE_URL'').''?client_id=''.urlencode(getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_CLIENT_ID'')).''&redirect_uri=''.urlencode(ope", "admin/openid_connect.php:278|read|print ''<input name=\"MAIN_AUTHENTICATION_OIDC_SCOPES\" ...''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_TOKEN_URL', 'string', NULL, 'admin', 'Specifies the token endpoint URL of the OpenID Connect provider used to exchange an authorization code for tokens.', 'Written via admin/openid_connect.php:94 and read in core/login/functions_openid_connect.php:100 via getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_TOKEN_URL'') as the target of a POST request to obtain tokens. Displayed in admin/openid_connect.php:294.', 'Setting an incorrect URL will cause OIDC token exchange to fail and prevent user login via OpenID Connect. Must match the provider''s token endpoint.', 'URL string of the OIDC token endpoint (e.g. ''https://provider.example.com/token'').', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, 'd23374a08b8088e8fd21b325217c2409a351049f95f880401fd32e329286e959', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:94|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_TOKEN_URL'', $value, ''chaine'', 0, '''', 0);", "core/login/functions_openid_connect.php:100|read|$token_response = getURLContent(getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_TOKEN_URL''), ''POST'', http_build_query($auth_param), 1, array(), array(''https''), 2);", "admin/openid_connect.php:294|read|print ''<input name=\"MAIN_AUTHENTICATION_OIDC_TOKEN_URL\"..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OIDC_USERINFO_URL', 'string', NULL, 'admin', 'Specifies the userinfo endpoint URL of the OpenID Connect provider used to retrieve authenticated user attributes.', 'Written via admin/openid_connect.php:101 and read in core/login/functions_openid_connect.php:128 via getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_USERINFO_URL'') as the target of a GET request for user information. Displayed in admin/openid_connect.php:302.', 'Setting an incorrect URL will cause user attribute retrieval to fail after token exchange, preventing successful OIDC login. Must match the provider''s userinfo endpoint.', 'URL string of the OIDC userinfo endpoint (e.g. ''https://provider.example.com/userinfo'').', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '39ec358449c4f360d6c4932b1918cdc1019aec79681dfe43fb0f67395c460535', 'v2', '2026-04-21T13:29:58+00:00', '["admin/openid_connect.php:101|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OIDC_USERINFO_URL'', $value, ''chaine'', 0, '''', 0);", "core/login/functions_openid_connect.php:128|read|$userinfo_response = getURLContent(getDolGlobalString(''MAIN_AUTHENTICATION_OIDC_USERINFO_URL''), ''GET'', '''', 1, $userinfo_headers, array(''https''), 2);", "admin/openid_connect.php:302|read|print ''<input name=\"MAIN_AUTHENTICATION_OIDC_USERINFO_URL\"..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OPENID_URL', 'string', NULL, 'core', 'Stores the base URL for the OpenID Connect authentication provider used on the login page.', 'Read in core/tpl/login.tpl.php:461 and core/class/openid.class.php:386 and :509 to construct the OpenID Connect authorization URL. No admin UI write found; HIDDEN_GUESS is 1.', 'When set, the login page displays an OpenID Connect login button linking to this URL with the OIDC state parameter appended. Removing it disables the OpenID Connect login option.', 'Any valid OpenID Connect authorization endpoint URL', 1, 0, NULL, 1, '1925f631c1f20ddac7acabf8e08a4daabbcde8f155eef0cd3a5a6e730bfb9ad2', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/login.tpl.php:458|check|if (!getDolGlobalString(\"MAIN_AUTHENTICATION_OPENID_URL\")) {", "core/tpl/login.tpl.php:461|read|$url = getDolGlobalString(''MAIN_AUTHENTICATION_OPENID_URL'').''&state='' . openid_connect_get_state();", "core/class/openid.class.php:386|read|$url = getDolGlobalString(''MAIN_AUTHENTICATION_OPENID_URL'');", "core/class/openid.class.php:509|read|$url = getDolGlobalString(''MAIN_AUTHENTICATION_OPENID_URL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTHENTICATION_OPENID_URL_IMG', 'string', NULL, 'admin', 'Stores the URL of a logo image to display on the OpenID Connect login button.', 'Written via admin/openid_connect.php:115 and displayed in core/tpl/login.tpl.php:467. When the value is set, an img tag with height 50px is rendered; otherwise a translatable label is shown.', 'Changing this URL updates the image shown on the OpenID Connect login button on the login page.', 'Any valid image URL string; empty/unset shows default text label', 0, 0, 'admin/openid_connect.php|admin/openid_connect.php', 1, '2875ff776d2933c15649f5bbedcee36f75d8339fc51fcf8666a727b4d331f0e8', 'v2', '2026-04-21T11:16:15+00:00', '["admin/openid_connect.php:115|write|$res = dolibarr_set_const($db, ''MAIN_AUTHENTICATION_OPENID_URL_IMG'', $openid_url_img, ''chaine'', 0, '''', 0);", "core/tpl/login.tpl.php:467|read|print getDolGlobalString(''MAIN_AUTHENTICATION_OPENID_URL_IMG'') ? ''<img src=\"''.getDolGlobalString(''MAIN_AUTHENTICATION_OPENID_URL_IMG'').''\" height=\"50px\" >'' : $langs->trans(\"LoginUsi", "admin/openid_connect.php:334|read|print ''<input name=\"MAIN_AUTHENTICATION_OPENID_URL_IMG\" id=\"MAIN_AUTHENTICATION_OPENID_URL_IMG\" class=\"minwidth400 centpercent\" value=\"...''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTOFILL_DATE', 'string', NULL, 'fourn', 'Controls whether date fields on payment and invoice forms are pre-filled with the current date.', 'Read in 11 locations across payment and invoice pages (e.g. fourn/commande/card.php:1922, compta/paiement.php:528, salaries/payment_salary.php:219). When truthy, the date variable is set to an empty string (triggering today''s date autofill); when falsy, it is set to -1 (leaving the field empty).', 'Enabling this constant pre-fills date fields with today''s date on payment and invoice entry forms; disabling leaves date fields blank by default.', 'Non-empty/non-zero = date fields auto-filled with current date; 0 or unset = date fields left empty.', 1, 0, NULL, 1, 'ae02df45fb866a2955bb2501fc0445c5ea18d935fa6016fe3759fa465c271af7', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/commande/card.php:1922|read|$dateinvoice\t\t= getDolGlobalString(''MAIN_AUTOFILL_DATE'') ? '''' : -1;", "compta/paiement.php:528|read|$datepayment = ($datepayment == '''' ? (getDolGlobalString(''MAIN_AUTOFILL_DATE'') ? '''' : -1) : $datepayment);", "salaries/payment_salary.php:219|read|$datepayment = getDolGlobalString(''MAIN_AUTOFILL_DATE'') ? '''' : (GETPOST(\"remonth\") ? $datepaye : -1);", "fourn/facture/paiement.php:403|read|$dateinvoice = ($datefacture == '''' ? (getDolGlobalString(''MAIN_AUTOFILL_DATE'') ? '''' : -1) : $datefacture);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTOFILL_DATE_ORDER', 'string', NULL, 'commande', 'Controls whether the order date is auto-filled with the current date or left empty when creating an order from another object (e.g. a proposal).', 'Read twice in commande/card.php (lines 2221 and 2249): $dateorder = getDolGlobalString(''MAIN_AUTOFILL_DATE_ORDER'') ? '''' : -1.', 'When enabled, $dateorder is set to '''' which causes the date field to autofill with the current date; when disabled, $dateorder is -1 which keeps the date field empty.', 'Boolean: enabled ('''') triggers autofill of current date; disabled (-1) leaves date empty.', 0, 0, NULL, 1, '09c708b1523ac9babc4423f16d7db3532bddbf7603e2e2e758e1d3e4bde5d9f7', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:2221/2249: $dateorder = getDolGlobalString(''MAIN_AUTOFILL_DATE_ORDER'') ? '''' : -1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTO_OPEN_SELECT2_ON_FOCUS_FOR_CUSTOMER_PRODUCTS', 'string', NULL, 'core', 'Automatically opens the select2 product dropdown on keyboard focus when adding a line for a customer (non-supplier) document, to support keyboard-only navigation.', 'Used in core/tpl/objectline_create.tpl.php:302: when truthy, injects inline JS that, on focus of the ''#idprod'' select2 combo, calls .select2(''open''); the inline comment explains it is to allow keyboard-only use.', 'Enabling it changes UI behavior so the product select2 combo auto-opens on focus instead of requiring a click, aiding keyboard navigation on sales document lines.', 'Boolean-like: truthy enables the auto-open-on-focus JS behavior for the customer product combo.', 0, 0, NULL, 1, '817da6c85cb945b147139ed2e9b6c56b996ebeded08b87632a80fd9266d3b5a5', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:302|check|if (getDolGlobalString(''MAIN_AUTO_OPEN_SELECT2_ON_FOCUS_FOR_CUSTOMER_PRODUCTS'')) {", "core/tpl/objectline_create.tpl.php:306|// On first focus on a select2 combo, auto open the menu (this allow to use the keyboard only)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTO_OPEN_SELECT2_ON_FOCUS_FOR_SUPPLIER_PRODUCTS', 'string', NULL, 'core', 'Automatically opens the select2 supplier-product dropdown on keyboard focus when adding a line for a supplier document, to support keyboard-only navigation.', 'Used in core/tpl/objectline_create.tpl.php:344: when truthy, injects inline JS that, on focus of the ''#idprodfournprice'' select2 combo, calls .select2(''open''), mirroring the customer-side behavior at line 302.', 'Enabling it changes UI behavior so the supplier-product select2 combo auto-opens on focus instead of requiring a click, aiding keyboard navigation on supplier document lines.', 'Boolean-like: truthy enables the auto-open-on-focus JS behavior for the supplier product combo.', 0, 0, NULL, 1, '1ff232851f975add1f4f9338b442e78c9ab78996cd1a457b1a718e617e79ee10', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:344|check|if (getDolGlobalString(''MAIN_AUTO_OPEN_SELECT2_ON_FOCUS_FOR_SUPPLIER_PRODUCTS'')) {", "core/tpl/objectline_create.tpl.php:350|//console.log(''focus on a select2 because of MAIN_AUTO_OPEN_SELECT2_ON_FOCUS_FOR_SUPPLIER_PRODUCTS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTO_TIMESTAMP_IN_PRIVATE_NOTES', 'string', NULL, 'core', 'Automatically prepends a date/time and user-name stamp when editing an object''s private note.', 'In core/tpl/notes.tpl.php:74, when this constant is set and the current action is editing the private note, the template concatenates a ''<date> <user fullname> --'' string onto the existing note content before it is shown for editing (mirrors MAIN_AUTO_TIMESTAMP_IN_PUBLIC_NOTES for the private note).', 'Enabling it inserts an auto-generated timestamp/author line into the private note text each time the note is opened for editing.', 'Boolean/truthy: when set, a timestamp+username line is auto-appended to the private note on edit.', 1, 0, NULL, 1, '4a5cb9927202866d8b540947e2242ae932f58b9b761dfe76b43bc385174cf0b4', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/notes.tpl.php:74|check|if (getDolGlobalString(''MAIN_AUTO_TIMESTAMP_IN_PRIVATE_NOTES'')) {", "core/tpl/notes.tpl.php: $stringtoadd = dol_print_date(dol_now(), ''dayhour'').'' ''.$user->getFullName($langs).'' --'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_AUTO_TIMESTAMP_IN_PUBLIC_NOTES', 'string', NULL, 'core', 'Automatically prepends a date/time and user-name stamp when editing an object''s public note.', 'In core/tpl/notes.tpl.php:63, when this constant is set and the current action is editing the public note, the template concatenates a ''<date> <user fullname> --'' string onto the existing note content before it is shown for editing.', 'Enabling it inserts an auto-generated timestamp/author line into the public note text each time the note is opened for editing, effectively logging who/when edited it inline in the note body.', 'Boolean/truthy: when set, a timestamp+username line is auto-appended to the public note on edit.', 1, 0, NULL, 1, '0ab103477b7657e800a5aa89447b3c3b7a5341025ccf1be0feb8c6b38c5cff6f', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/notes.tpl.php:63|check|if (getDolGlobalString(''MAIN_AUTO_TIMESTAMP_IN_PUBLIC_NOTES'')) {", "core/tpl/notes.tpl.php: $stringtoadd = dol_print_date(dol_now(), ''dayhour'').'' ''.$user->getFullName($langs).'' --'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BANK_ACCOUNTANCY_CODE_ALWAYS_REQUIRED', 'string', NULL, 'compta', 'Makes the accountancy code field mandatory when creating or updating a bank account.', 'Checked in compta/bank/card.php at lines 210, 320, 653, and 1120 to enforce that account_number is not empty and to mark the accountancy code field as required in the UI.', 'Enabling this constant prevents saving a bank account without an accountancy code, enforcing accounting integration compliance.', 'Truthy value = accountancy code required; empty/unset = field optional.', 1, 0, NULL, 1, '00da561614316d760519129e8946d07ccbb768e6944a780fd02727f6cb5368e3', 'v2', '2026-04-21T11:16:15+00:00', '["compta/bank/card.php:210|check|if (getDolGlobalInt(''MAIN_BANK_ACCOUNTANCY_CODE_ALWAYS_REQUIRED'') && empty($object->account_number)) {", "compta/bank/card.php:320|check|if (getDolGlobalInt(''MAIN_BANK_ACCOUNTANCY_CODE_ALWAYS_REQUIRED'') && empty($object->account_number)) {", "compta/bank/card.php:653|check|if (getDolGlobalString(''MAIN_BANK_ACCOUNTANCY_CODE_ALWAYS_REQUIRED'')) {", "compta/bank/card.php:1120|check|if (getDolGlobalString(''MAIN_BANK_ACCOUNTANCY_CODE_ALWAYS_REQUIRED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BARCODE_CODE_ALWAYS_REQUIRED', 'string', NULL, 'core', 'Forces barcode codes to be required even when the active barcode module marks them as optional.', 'When set, core/modules/barcode/modules_barcode.class.php overrides the code_null flag at six check points (lines 163, 167, 174, 178, 185, 189), making barcode entry mandatory regardless of the module''s own nullability setting.', 'Enabling this makes barcode entry mandatory system-wide; disabling it defers to each module''s own code_null setting.', 'Any non-empty string value forces barcode codes to be required.', 1, 0, NULL, 1, '56ee4d002bce53f7487d7f682d8a576f9705355180bbb68ca02f7e317583ca2e', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/barcode/modules_barcode.class.php:163|check|if (getDolGlobalString(''MAIN_BARCODE_CODE_ALWAYS_REQUIRED'') && !empty($this->code_null)) {", "core/modules/barcode/modules_barcode.class.php:167|check|if (getDolGlobalString(''MAIN_BARCODE_CODE_ALWAYS_REQUIRED'') && !empty($this->code_null)) {", "core/modules/barcode/modules_barcode.class.php:174|check|if (getDolGlobalString(''MAIN_BARCODE_CODE_ALWAYS_REQUIRED'') && !empty($this->code_null)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BOX_ACTIVITY_DURATION', 'string', NULL, 'core', 'Sets the number of periods used to calculate the activity duration displayed in the activity dashboard box.', 'Checked and read in core/boxes/box_activity.php at lines 85 and 86; the value is assigned to $nbofperiod.', 'Changing this constant alters how many periods are included in the activity box calculations.', 'Integer number of periods; empty/unset = default period used by the box.', 1, 0, NULL, 1, '446f62e2fbcfeb50f09f788585a5c4b3997e620bca79d5e9c0195b2b053d472d', 'v2', '2026-04-21T11:16:15+00:00', '["core/boxes/box_activity.php:85|check|if (getDolGlobalString(''MAIN_BOX_ACTIVITY_DURATION'')) {", "core/boxes/box_activity.php:86|read|$nbofperiod = getDolGlobalString(''MAIN_BOX_ACTIVITY_DURATION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BOX_ENABLE_BEST_CUSTOMERS', 'bool', NULL, 'core', 'Enables the "Best customers" home dashboard box, which is disabled by default because it is slow on large databases.', 'In core/boxes/box_goodcustomers.php:60, the box constructor sets $this->enabled = 0 unless getDolGlobalString(''MAIN_BOX_ENABLE_BEST_CUSTOMERS'') is truthy; comment explicitly states ''not enabled by default. Very slow on large database''.', 'Enabling this box can slow down the home page load on large databases, per the code comment.', 'Boolean-like; truthy enables the box, empty/unset (default) leaves it disabled.', 1, 0, NULL, 1, '898f2b42ba2db59f19d5e86bdc42c5de4e0e29fb116001cc46160c9c74c54f21', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_goodcustomers.php:60|check|if (!getDolGlobalString(''MAIN_BOX_ENABLE_BEST_CUSTOMERS'')) {", "core/boxes/box_goodcustomers.php:61|comment|$this->enabled = 0; // not enabled by default. Very slow on large database"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BROWSER_NOTIFICATION_CHECK_FIRST_EXECUTION', 'string', NULL, 'core', 'Sets the delay (in seconds) before the first browser-notification check is run after page load.', 'In core/js/lib_notification.js.php:98, the value is read with max(3, ...) and a default of 0, then used as the setTimeout delay (in seconds, converted to ms) before calling first_execution() for the browser notification poller.', 'Increasing the value delays how soon after page load the browser starts polling for agenda/reminder notifications; the effective minimum is always 3 seconds regardless of a lower configured value.', 'int: seconds to wait before first notification check; effective value is max(3, configured); default base is 0 (so minimum 3s applies).', 0, 0, NULL, 1, '0ef785e7e343299e28246a88aef930c564cc6f4dc6023fdc178446c98f39f26d', 'v2', '2026-07-24T07:05:23+00:00', '["core/js/lib_notification.js.php:98: var time_first_execution = <?php echo max(3, getDolGlobalInt(''MAIN_BROWSER_NOTIFICATION_CHECK_FIRST_EXECUTION'', 0)); ?>;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BROWSER_NOTIFICATION_FREQUENCY', 'string', NULL, 'core', 'Sets the polling interval (in seconds) for browser-side agenda notifications.', 'Read in core/js/lib_notification.js.php:75 where it is used as: max(1, getDolGlobalInt(''MAIN_BROWSER_NOTIFICATION_FREQUENCY'')). A commented-out reference also appears in core/ajax/check_notifications.php:107 noting it is ''Always defined''.', 'Increasing the value reduces polling frequency; decreasing it increases how often the browser checks for new notifications.', 'Integer number of seconds >= 1; values below 1 are clamped to 1', 1, 0, NULL, 1, 'f070955598921e7cfbf1bddf0a4f1219991a24d79736bb1437d8b784cade2db5', 'v2', '2026-04-21T13:29:58+00:00', '["/*$time_update = (int) $conf->global->MAIN_BROWSER_NOTIFICATION_FREQUENCY; // Always defined", "print ''var time_auto_update = ''.max(1, getDolGlobalInt(''MAIN_BROWSER_NOTIFICATION_FREQUENCY'')).'';''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BUGTRACK_ENABLELINK', 'bool', NULL, 'core', 'Enables a bug-tracker link in the footer, optionally pointing to GitHub or a custom URL.', 'Written in admin/ihm.php:287 and displayed as a text input at :545. Checked in main.inc.php:3335, :3389, :3392, and :3427-3428 to render the bug-tracker link; ''github'' triggers a GitHub-specific URL, any other value is used directly as the base URL.', 'Setting to ''github'' adds a link to the GitHub issue tracker; setting to another URL uses that as the bug base URL; unsetting removes the link.', ''''' or unset = bug tracker link hidden; ''github'' = link to GitHub issues; any other URL string = link to that URL', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '35c32f1cb4c20762581056743fc3287b16f776bc39a2bda3b4f946af22abe4d8', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:3392|check|if (getDolGlobalString(''MAIN_BUGTRACK_ENABLELINK'') == ''github'') {", "main.inc.php:3427|read|} elseif (getDolGlobalString(''MAIN_BUGTRACK_ENABLELINK'')) {", "main.inc.php:3428|read|$bugbaseurl = getDolGlobalString(''MAIN_BUGTRACK_ENABLELINK'');", "admin/ihm.php:545|read|print ''<input type=\"text\" name=\"MAIN_BUGTRACK_ENABLELINK\" value=\"'' . getDolGlobalString(''MAIN_BUGTRACK_ENABLELINK'') . ''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BUILD_LOGIN_RULE', 'string', NULL, 'core', 'Specifies the algorithm used to auto-generate a login from a user''s first and last name.', 'Checked in core/lib/functions2.lib.php and user/card.php (5 occurrences total): values ''flastname'' and ''f.lastname'' select different formatting rules. The comment at functions2.lib.php:2004 shows the example value ''f.lastname''.', 'Setting this determines the pattern of auto-generated logins; leaving it unset uses the default login construction logic.', '''flastname'' = first initial concatenated with last name; ''f.lastname'' = first initial, separator, last name; other/unset = default rule.', 1, 0, NULL, 1, 'b0db3eb26f2f660f0815d36690ebf9f163f89998cb8197992fc52d89e3e12bfc', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:2004  //$conf->global->MAIN_BUILD_LOGIN_RULE = ''f.lastname'';", "core/lib/functions2.lib.php:2010|check|if (getDolGlobalString(''MAIN_BUILD_LOGIN_RULE'') == ''flastname'') {", "core/lib/functions2.lib.php:2014|read|} elseif (getDolGlobalString(''MAIN_BUILD_LOGIN_RULE'') == ''f.lastname'') {", "user/card.php:1090|check|if (getDolGlobalString(''MAIN_BUILD_LOGIN_RULE'') == ''flastname'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BUTTON_HIDE_UNAUTHORIZED', 'bool', NULL, 'theme', 'Hides action buttons for non-admin users when they lack permission for the associated action.', 'When enabled, buttons are hidden rather than shown as disabled for users without the required permission. Referenced in core/lib/functions.lib.php:14945, core/class/html.formfile.class.php:194, and theme/eldy/btn.inc.php:412. The admin UI write is commented out in admin/ihm.php:280, suggesting the setting is managed manually or via another mechanism.', 'Enabling this setting removes unauthorised action buttons from the UI for non-admin users, reducing visual clutter and preventing confusion over disabled controls.', 'Empty/0 = disabled (buttons shown as disabled); non-empty = enabled (buttons hidden for non-admin users without permission).', 0, 0, 'admin/ihm.php', 1, '1fa5f963651b8f6320084de25e40e4bf895b6bae768793caaffdd30944faf2de', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/functions.lib.php:14945|check|if (getDolGlobalString(''MAIN_BUTTON_HIDE_UNAUTHORIZED'') && (!$user->admin) && $status <= 0) {", "core/class/html.formfile.class.php:194|check|if (!$perm && getDolGlobalString(''MAIN_BUTTON_HIDE_UNAUTHORIZED'')) {", "theme/eldy/btn.inc.php:412|<?php if (getDolGlobalString(''MAIN_BUTTON_HIDE_UNAUTHORIZED'') && (!$user->admin)) { ?>", "admin/ihm.php:280  //dolibarr_set_const($db, \"MAIN_BUTTON_HIDE_UNAUTHORIZED\", GETPOST(\"MAIN_BUTTON_HIDE_UNAUTHORIZED\", ''aZ09''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_BUTTON_POSITION_FIRST_OR_LEFT', 'string', NULL, 'core', 'Controls button ordering in action bar: when set, main action button is placed first/left; when unset, the default order is main action first, then complementary, then cancel at end.', 'Checked at core/class/html.form.class.php:12439 via getDolGlobalInt. The comment at :12438 states ''If MAIN_BUTTON_POSITION_FIRST_OR_LEFT not set, default is to have main action first, then complementary, then cancel at end''.', 'Changing this value reorders buttons in action bars throughout the UI. The default (unset/0) already places the main action first, so this constant modifies the complementary/cancel layout.', 'If MAIN_BUTTON_POSITION_FIRST_OR_LEFT not set, default is to have main action first, then complementary, then cancel at end.', 1, 0, NULL, 1, '5666db0d4cb331c6abf62a50d46e0c8e3d4f0607afe17ecf6687aeadfe814d31', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:12438  // If MAIN_BUTTON_POSITION_FIRST_OR_LEFT not set, default is to have main action first, then complementary, then cancel at end", "core/class/html.form.class.php:12439|check|if (!getDolGlobalInt(''MAIN_BUTTON_POSITION_FIRST_OR_LEFT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CACHE_COUNT', 'string', NULL, 'admin', 'Enables/requires a shared-memory count cache used by memory.lib.php to save data shared across all users and sessions on the server.', 'Displayed/toggled in admin/system/perf.php (764, 771) and checked via getDolGlobalString(''MAIN_CACHE_COUNT'') in core/lib/memory.lib.php (78, 185), where the doc comment states it ''must be set'' for the shared memory save function to work.', 'Enabling it is required for the dolSaveIntoMemory-style shared memory area described in memory.lib.php to actually persist/save data; without it, the memory.lib.php:78/185 guarded code paths are skipped.', NULL, 0, 0, 'admin/system/perf.php|admin/system/perf.php', 1, '74f7e1bcd4d1ac4d5d9146a06cf96ef59997b0097de80ac323aff49f8510c172', 'v2', '2026-07-24T06:41:12+00:00', '["core/lib/memory.lib.php:61  * \tSave data into a memory area shared by all users, all sessions on server. Note: MAIN_CACHE_COUNT must be set.", "core/lib/memory.lib.php:78|check|if (!getDolGlobalString(''MAIN_CACHE_COUNT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CAN_EDIT_SUPPLIER_ON_SUPPLIER_ORDER', 'string', NULL, 'fourn', 'Allows the supplier (third party) to be changed on a supplier order when the order is in draft status.', 'Checked across 4 occurrences in fourn/commande/card.php:355, :2435, :2444, :2445. When set, an ''edit_thirdparty'' action is available and the supplier field becomes editable on draft orders.', 'Enabling this adds a UI control to change the supplier on a draft supplier order; disabling it prevents supplier modification regardless of status.', 'Empty/0 = supplier cannot be changed after creation; truthy = supplier editable on draft orders', 1, 0, NULL, 1, '9efe7e9cafb61d8ea2526e0be30abc18613454866635fa28e7afbb50779a3449', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/commande/card.php:355|check|if (getDolGlobalString(''MAIN_CAN_EDIT_SUPPLIER_ON_SUPPLIER_ORDER'') && $action == ''set_thirdparty'' && $usercancreate && $object->status == CommandeFournisseur::STATUS_DRAFT) {", "fourn/commande/card.php:2435|check|if (getDolGlobalString(''MAIN_CAN_EDIT_SUPPLIER_ON_SUPPLIER_ORDER'') && !empty($usercancreate) && $action == ''edit_thirdparty'') {", "fourn/commande/card.php:2444|check|if (!getDolGlobalString(''MAIN_CAN_EDIT_SUPPLIER_ON_SUPPLIER_ORDER'') || $action != ''edit_thirdparty'') {", "fourn/commande/card.php:2445|check|if (getDolGlobalString(''MAIN_CAN_EDIT_SUPPLIER_ON_SUPPLIER_ORDER'') && $object->status == CommandeFournisseur::STATUS_DRAFT) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CARE_GRANDCHILD', 'string', NULL, 'core', 'Controls whether grandchild (multi-level nested) object lines are included when reordering parent/child lines.', 'Read in core/class/commonobject.class.php:3554 inside line_order(): `$grandchild = getDolGlobalInt(''MAIN_CARE_GRANDCHILD'');` then passed as an argument to `$this->getChildrenOfLine($row[0], $grandchild)` when computing which child lines to reorder alongside their parent.', 'Changes how deep the line-reordering logic descends into nested (grandchild) lines when renumbering position after a parent line; exact depth semantics of the getChildrenOfLine parameter are not shown in the excerpt read.', 'Integer value passed to getChildrenOfLine() as a depth/flag argument; exact accepted values not documented in code comments seen.', 1, 0, NULL, 1, 'd1194d90fbe395e47aeece005ab7a42eff3ef86de02d77e6965a2f63668c9b39', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonobject.class.php:3554|read|$grandchild = getDolGlobalInt(''MAIN_CARE_GRANDCHILD'');", "core/class/commonobject.class.php|$children = $this->getChildrenOfLine($row[0], $grandchild);"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CHANGE_ORDER_CONCAT_DESCRIPTION', 'string', NULL, 'fourn', 'Controls whether the product description and line description are concatenated in inverted order when adding a product line to a document.', 'Read across 9 files including supplier_proposal/card.php:888, fourn/commande/card.php:712, comm/propal/card.php:1562, and reception/card.php:1012, always passed as the `$invert` parameter to `dol_concatdesc`. COMMENT from core/lib/functions.lib.php:10166: `@param bool $invert invert order of description lines (we often use config MAIN_CHANGE_ORDER_CONCAT_DESCRIPTION in this parameter)`.', 'Enabling this setting causes the product description to be appended after the line description (inverted order) rather than before it.', 'Truthy string (non-empty) = invert concatenation order; empty/not set = normal concatenation order.', 1, 0, NULL, 1, '2509702fb954b5be4d61ca19a4369b07bcc68810632b912868800b54e82f6a43', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/functions.lib.php:10166  *  @param  bool    $invert         invert order of description lines (we often use config MAIN_CHANGE_ORDER_CONCAT_DESCRIPTION in this parameter)", "supplier_proposal/card.php:888|read|$desc = dol_concatdesc($desc, $line_desc, false, getDolGlobalString(''MAIN_CHANGE_ORDER_CONCAT_DESCRIPTION'') ? true : false);", "fourn/commande/card.php:712|read|$desc = dol_concatdesc($desc, $line_desc, false, getDolGlobalString(''MAIN_CHANGE_ORDER_CONCAT_DESCRIPTION'') ? true : false);", "comm/propal/card.php:1562|read|$desc = dol_concatdesc($desc, $line_desc, false, getDolGlobalString(''MAIN_CHANGE_ORDER_CONCAT_DESCRIPTION'') ? true : false);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CHECKBOX_LEFT_COLUMN', 'string', NULL, 'user', 'Controls whether the row-selection checkbox column in list views is displayed on the left side of the table instead of the default position.', 'Set via admin/ihm.php:276 (dolibarr_set_const) and per-user via user/param_ihm.php (466, 470, 610), and read via getDolGlobalString(''MAIN_CHECKBOX_LEFT_COLUMN'', '''') in accountancy/admin/template/list.php:428 and core/class/conf.class.php:1319 (main_checkbox_left_column property).', 'Enabling it moves the checkbox column to the left in the multi-select array/list rendering, per accountancy/admin/template/list.php:428, and can also be overridden per-user via $object->conf->MAIN_CHECKBOX_LEFT_COLUMN.', NULL, 0, 0, 'accountancy/admin/template/list.php|admin/ihm.php', 1, '80768da323d98d1866cbe8da0bd105d9f52f8092ba7055e6090b63d749729bce', 'v2', '2026-07-24T06:41:12+00:00', '["admin/ihm.php:276|write|dolibarr_set_const($db, \"MAIN_CHECKBOX_LEFT_COLUMN\", GETPOSTINT(\"MAIN_CHECKBOX_LEFT_COLUMN\"), ''chaine'', 0, '''', $conf->entity);", "core/class/conf.class.php:1319|read|$this->main_checkbox_left_column = getDolGlobalInt(\"MAIN_CHECKBOX_LEFT_COLUMN\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_COMPANY_CODE_ALWAYS_REQUIRED', 'string', NULL, 'core', 'Forces company/product codes to be mandatory even when the numbering module allows null codes.', 'When set, code generator modules such as core/modules/societe/mod_codeclient_monkey.php:176 and core/modules/product/mod_codeproduct_leopard.php:124 treat an empty code as an error regardless of the module''s code_null setting. Also enforced during member subscription at adherents/subscription.php:935. No admin UI is provided.', 'Enabling this constant prevents saving records without a code, overriding any ''optional code'' setting in the active numbering module.', 'Non-empty/truthy = code always required; empty/unset = code requirement follows the numbering module''s code_null setting.', 1, 0, NULL, 1, 'da75709ac8e1309afd395af023fa66f4b1b293014cc170a8aa167fc71e941ba4', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/product/mod_codeproduct_leopard.php:124|check|} elseif (empty($code) && (!$this->code_null || getDolGlobalString(''MAIN_COMPANY_CODE_ALWAYS_REQUIRED''))) {", "core/modules/societe/mod_codeclient_monkey.php:176|check|} elseif (empty($code) && (!$this->code_null || getDolGlobalString(''MAIN_COMPANY_CODE_ALWAYS_REQUIRED''))) {", "core/modules/product/modules_product.class.php:137|check|if (getDolGlobalString(''MAIN_COMPANY_CODE_ALWAYS_REQUIRED'') && !empty($this->code_null)) {", "adherents/subscription.php:935|check|if (getDolGlobalString(''MAIN_COMPANY_CODE_ALWAYS_REQUIRED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_COMPANY_PERENTITY_SHARED', 'string', NULL, 'accountancy', 'Enables sharing the main company/third-party (thirdparty) record across entities in a multi-entity (multi-company) setup.', 'Set/toggled in accountancy/admin/index.php:560 and checked pervasively via getDolGlobalString(''MAIN_COMPANY_PERENTITY_SHARED'') in fourn/index.php (243, 250), societe/class/societe.class.php (1667, 1824, 2512), and societe/index.php (290, 302).', 'Enabling it changes societe.class.php''s per-entity company logic (e.g. lines 1667, 1824, 2512) to treat certain company data as shared across entities rather than isolated per entity.', NULL, 0, 0, 'accountancy/admin/index.php', 1, '4138dd8efe348d990819c71cf1ffa002a6ffad4a3054e9bca7ee8629ccafffd2', 'v2', '2026-07-24T06:41:12+00:00', '["accountancy/admin/index.php:560|check|if (getDolGlobalString(''MAIN_COMPANY_PERENTITY_SHARED'')) {", "societe/class/societe.class.php:1667|check|if (!getDolGlobalString(''MAIN_COMPANY_PERENTITY_SHARED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CONTRACT_CODE_ALWAYS_REQUIRED', 'string', NULL, 'core', 'Forces a contract product/service code to be required even for numbering modules (like mod_contract_olive) that would otherwise allow an empty/null code.', 'Checked in core/modules/contract/mod_contract_olive.php:110-112 inside verif(): when the module allows null codes (code_null) and this constant is unset, an empty code passes (result 0); if set, an empty code returns error -2.', 'Enabling it makes contract numbering modules that normally tolerate an empty code start rejecting empty codes (verif() returns -2, a validation error).', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, 'ecb973cba684a3fef6db2189b03d8fd3611b8d876936fbb3b4bc652cf0a67686', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/contract/mod_contract_olive.php:110: if (empty($code) && $this->code_null && !getDolGlobalString(''MAIN_CONTRACT_CODE_ALWAYS_REQUIRED'')) {", "core/modules/contract/mod_contract_olive.php:112: } elseif (empty($code) && (!$this->code_null || getDolGlobalString(''MAIN_CONTRACT_CODE_ALWAYS_REQUIRED''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_COPY_FILE_IN_EVENT_AUTO', 'string', NULL, 'core', 'When an agenda event (ActionComm) is auto-created by a trigger, copies the triggering object''s attached files into the new event''s document directory.', 'Read in core/triggers/interface_50_modAgenda_ActionsAuto.class.php:1675, right after the ActionComm is created, guarding a loop over $object->attachedfiles[''paths''] that dol_copy()''s each file into the event''s dir_output.', 'When set and the originating object exposes an ''attachedfiles'' property (paths/names arrays), each listed file is physically copied via dol_mkdir()+dol_copy() into the new event''s folder; if unset, no file copy is attempted even if attachedfiles exist.', 'Truthy string enables copying attached files into the auto-created event; empty/unset disables it.', 1, 0, NULL, 1, '4d0387592fe9becbdb8fa583621ab5ced703fa39ce661c1e02626cf76c068ecb', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_50_modAgenda_ActionsAuto.class.php:1675: if ($ret > 0 && getDolGlobalString(''MAIN_COPY_FILE_IN_EVENT_AUTO'')) {", "core/triggers/interface_50_modAgenda_ActionsAuto.class.php:1676: // Note: None of the dolibarr classes seem to have an attachedfiles property"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CORE_ERROR', 'string', NULL, 'core', 'Displays a generic core error dialog/message banner to the user when set, used as an internal error signaling flag.', 'In main.inc.php:3935, when truthy, Dolibarr shows an ajax_dialog or inline ''<div class="error">'' with the CoreErrorTitle/CoreErrorMessage translations; a nearby comment shows it is normally defined via define(), not admin UI or conf.php, and notes ''Constant was defined and we can''t change value of a constant''.', 'Setting it (typically via PHP define(), per the inline comment) triggers a generic core-error UI notification on the current page; the comment implies this is meant to be set programmatically/temporarily by core code, not as a persistent user setting.', 'Boolean-like: truthy shows the core error message; comment gives example usage ''define("MAIN_CORE_ERROR",0);'' as a placeholder.', 1, 0, NULL, 1, '2cb637dbdc694afd56329ba92424514f60b13d3e00eb9bd0d3264b276e38cfb8', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:3935|check|if (getDolGlobalString(''MAIN_CORE_ERROR'')) {", "main.inc.php:3946  //define(\"MAIN_CORE_ERROR\",0);      // Constant was defined and we can''t change value of a constant"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_COUNTER_WITH_LESS_3_DIGITS', 'string', NULL, 'core', 'Allows document numbering masks whose counter part has fewer than 3 digits, bypassing the normal minimum-digit validation.', 'In core/lib/functions2.lib.php:855, get_next_value() (or related mask-parsing code) returns the error ''ErrorCounterMustHaveMoreThan3Digits'' when the mask''s counter length is under 3 digits, unless this bool is set, in which case the check is skipped.', 'Enabling it lets numbering masks with a counter of 1-2 digits be accepted instead of raising a validation error; leaving it unset/false enforces the minimum of 3 digits for the counter part of a mask.', 'true/1 = skip the minimum-3-digits validation for mask counters; false/unset (default) = enforce minimum 3 digits (else error ErrorCounterMustHaveMoreThan3Digits).', 1, 0, NULL, 1, '1b1b3fdfd1ecc909ae2038b87c7e31d42dfd8654e2a579e2f35f054de51a510c', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions2.lib.php:855|check|if (dol_strlen($maskcounter) < 3 && !getDolGlobalString(''MAIN_COUNTER_WITH_LESS_3_DIGITS'')) {", "core/lib/functions2.lib.php:856: return ''ErrorCounterMustHaveMoreThan3Digits'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CREATEFROM_KEEP_LINE_ORIGIN_INFORMATION', 'string', NULL, 'compta', 'Changes how origin references are stored on document lines: when set, stores the origin line ID and line type instead of the parent document ID and type.', 'Checked in compta/facture/class/facture.class.php:974, comm/propal/class/propal.class.php:1353, and commande/class/commande.class.php:1116. Multiple docblock comments at propal.class.php:632-633, commande.class.php:1584-1585, and facture.class.php:4160-4161 explain that $origin and $origin_id take line-level values (''orderdet'', ''propaldet'', line id) when set, vs document-level values otherwise. No admin UI is present.', 'Enabling this causes document line origin fields to reference the specific source line (''orderdet''/''propaldet'' + line id) rather than the source document (''order''/''propal'' + document id).', '0 or unset = origin fields store document-level reference; truthy value = origin fields store line-level reference (''orderdet'', ''propaldet'', etc.).', 1, 0, NULL, 1, '29853ec697d1f8f4ddf55f29b941fa56c61af9f81b3425d5ad960c72eed4add4', 'v2', '2026-04-21T11:16:15+00:00', '["comm/propal/class/propal.class.php:632  *      @param\t\tstring\t\t\t$origin\t\t\t\tDepend on global conf MAIN_CREATEFROM_KEEP_LINE_ORIGIN_INFORMATION can be ''orderdet'', ''propaldet''..., else ''order'',''propal,''....", "comm/propal/class/propal.class.php:633  *      @param\t\tint\t\t\t\t$origin_id\t\t\tDepend on global conf MAIN_CREATEFROM_KEEP_LINE_ORIGIN_INFORMATION can be Id of origin object (aka line id), else object id", "commande/class/commande.class.php:1584  * \t@param\t\tstring\t\t    $origin\t\t\t\tDepend on global conf MAIN_CREATEFROM_KEEP_LINE_ORIGIN_INFORMATION can be ''orderdet'', ''propaldet''..., else ''order'',''propal,''....", "compta/facture/class/facture.class.php:974|check|if (getDolGlobalString(''MAIN_CREATEFROM_KEEP_LINE_ORIGIN_INFORMATION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CRON_EXEC_TIME_LIMIT', 'string', NULL, 'cron', 'PHP execution time limit (seconds) applied via set_time_limit() while a scheduled cron job is running.', 'Read in CronJob::run_jobs() at cron/class/cronjob.class.php:1316 with default 600, applied through @set_time_limit($ExecTimeLimit) (with error reporting temporarily disabled around the call).', 'Raising it allows long-running cron jobs more time before PHP''s execution-time limit kills them (only effective if PHP safe mode/restrictions allow set_time_limit); default is 600 seconds if unset.', 'An integer number of seconds; default 600. Per code comment, may need to be >240 on Windows/IIS.', 1, 0, NULL, 1, 'f2cd578dc172958bc15a6c1c5c09282230faa8d71203de9e9979ea4d8d8712b8', 'v2', '2026-07-24T07:05:23+00:00', '["cronjob.class.php:1316: $ExecTimeLimit = getDolGlobalInt(''MAIN_CRON_EXEC_TIME_LIMIT'', 600);", "cronjob.class.php: // Increase limit of time. Works only if we are not in safe mode", "cronjob.class.php: @set_time_limit($ExecTimeLimit); // Need more than 240 on Windows 7/64"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CRON_MEMORY_LIMIT', 'string', NULL, 'cron', 'PHP memory_limit value applied via ini_set() while a scheduled cron job is running.', 'Read in CronJob::run_jobs() at cron/class/cronjob.class.php:1324, right after the exec time limit is set, applied through @ini_set(''memory_limit'', $MemoryLimit) only if non-empty.', 'Setting it raises (or changes) the PHP memory limit specifically for the duration of a cron job execution, letting memory-intensive jobs run without hitting the default PHP memory_limit.', 'A PHP memory_limit-style string (e.g. ''256M''); no default is applied if unset (ini_set is skipped).', 1, 0, NULL, 1, '014d39d479a9c1ccfd702dc2bd88e1c537a42ee87447beec40304f666f261da6', 'v2', '2026-07-24T07:05:23+00:00', '["cronjob.class.php:1324: $MemoryLimit = getDolGlobalString(''MAIN_CRON_MEMORY_LIMIT''); if (!empty($MemoryLimit)) { @ini_set(''memory_limit'', $MemoryLimit); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CSS_LONGMESSSAGECUT', 'string', NULL, 'theme', 'Sets the max-height in pixels for the ''.longmessagecut'' CSS class used to truncate long descriptions and extrafield text with a scrollbar.', 'Read with a default of 250 in both theme/eldy/global.inc.php:1373 and theme/md/style.css.php:1509, applied to the ''max-height'' CSS property of ''.longmessagecut''.', 'Increasing/decreasing it changes how tall the scrollable truncated-text boxes (long variant) are allowed to be before scrolling kicks in, in both the Eldy and MD themes.', 'Integer, pixel value; default 250.', 0, 0, NULL, 1, 'f63791743b2a8c1729c39a0b5b9b82a069badf5a53b75b16f8b5fb9108755cc5', 'v2', '2026-07-24T07:05:23+00:00', '["theme/eldy/global.inc.php:1372-1373: .longmessagecut { max-height: <?php print getDolGlobalInt(''MAIN_CSS_LONGMESSSAGECUT'', 250); ?>px;", "theme/md/style.css.php:1509: max-height: <?php print getDolGlobalInt(''MAIN_CSS_LONGMESSSAGECUT'', 250); ?>px;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CSS_SHORTMESSSAGECUT', 'string', NULL, 'theme', 'Sets the max-height in pixels for the ''.shortmessagecut'' CSS class used to truncate long descriptions and extrafield text with a scrollbar.', 'Read with a default of 125 in both theme/eldy/global.inc.php:1367 and theme/md/style.css.php:1503, applied to the ''max-height'' CSS property of ''.shortmessagecut'' (comment: ''CSS used for long description and extrafield text'').', 'Increasing/decreasing it changes how tall the scrollable truncated-text boxes are allowed to be before scrolling kicks in, in both the Eldy and MD themes.', 'Integer, pixel value; default 125.', 0, 0, NULL, 1, '1d766f59e84b960351e14abd02cd658d8d05f353d473a41941a6a06c0535f6a5', 'v2', '2026-07-24T07:05:23+00:00', '["theme/eldy/global.inc.php:1365-1367: /* CSS used for long description and extrafield text */ .shortmessagecut { max-height: <?php print getDolGlobalInt(''MAIN_CSS_SHORTMESSSAGECUT'', 125); ?>px;", "theme/md/style.css.php:1503: max-height: <?php print getDolGlobalInt(''MAIN_CSS_SHORTMESSSAGECUT'', 125); ?>px;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CSS_USE_SHADOWS', 'bool', NULL, 'theme', 'Enables box-shadow styling on stat/box tables in the Eldy theme, except when dark mode is fully enabled.', 'Read in theme/eldy/global.inc.php:5409, combined with a check that THEME_DARKMODEENABLED != 2, guarding a CSS block that adds ''box-shadow: -2px 1px 12px rgba(192,192,192,0.5);'' to ''.boxtable''/''.firstcolumn table.noborder''/''.secondcolumn table.noborder''.', 'Enabling it (while not in full dark mode) adds a drop-shadow to box tables across the Eldy theme; unset/0 or dark mode level 2 leaves them without shadow.', 'Boolean-like: enabled = apply box-shadow (only if THEME_DARKMODEENABLED != 2); unset/0 = no shadow.', 0, 0, NULL, 1, 'b454d3d765c6238d652a7d16715b80f72f3e5c77af01e672805c7a793f1221e0', 'v2', '2026-07-24T07:05:23+00:00', '["theme/eldy/global.inc.php:5409: <?php if (getDolGlobalString(''MAIN_CSS_USE_SHADOWS'') && getDolGlobalInt(''THEME_DARKMODEENABLED'') != 2) { ?>", "theme/eldy/global.inc.php:5410-5411: .boxtable, .firstcolumn table.noborder, .secondcolumn table.noborder { box-shadow: -2px 1px 12px rgba(192, 192, 192, 0.5); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CURL_DEBUG', 'string', NULL, 'core', 'Enables detailed cURL request/response logging to the dolibarr_curl.log file when set.', 'Checked at 8 locations in core/lib/geturl.lib.php. The inline comment at line 33 documents: ''You can enable constant MAIN_CURL_DEBUG to get detail of output/input into dolibarr_curl.log file.'' No admin UI write is present.', 'When enabled, all cURL HTTP calls are logged with full request and response details to dolibarr_curl.log, which aids in debugging outbound HTTP issues. Leaving this on in production generates large log files.', 'Truthy integer (e.g. 1) to enable cURL debug logging; 0 or unset to disable.', 1, 0, NULL, 1, 'c93afdac75815577fc95302c500a8869b2259d73ba55a5ff224a7b8762a76150', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/geturl.lib.php:33  * You can enable constant MAIN_CURL_DEBUG to get detail of output/input into dolibarr_curl.log file.", "core/lib/geturl.lib.php:326|check|if (getDolGlobalInt(''MAIN_CURL_DEBUG'')) {", "core/lib/geturl.lib.php:59|check|if (getDolGlobalInt(''MAIN_CURL_DEBUG'')) {", "core/lib/geturl.lib.php:67|check|if (getDolGlobalInt(''MAIN_CURL_DEBUG'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CURL_DISABLE_VERIFYPEER', 'bool', NULL, 'paypal', 'Disables cURL SSL peer certificate verification for outbound HTTP requests including PayPal API calls.', 'Checked at paypal/lib/paypal.lib.php:498 and core/lib/geturl.lib.php:113; when set, CURLOPT_SSL_VERIFYPEER is disabled for the cURL session.', 'Disabling peer verification removes SSL certificate validation, which reduces security for all outbound cURL requests.', '0 or unset = verify peer (default); any truthy value = skip verification.', 1, 0, NULL, 1, 'e6744287bb2ca652aa7890f1b48877cf0fd9503829877d87bf062ac9be95e631', 'v2', '2026-04-21T11:16:15+00:00', '["paypal/lib/paypal.lib.php:498|check|if (getDolGlobalString(''MAIN_CURL_DISABLE_VERIFYPEER'')) {", "core/lib/geturl.lib.php:113|check|if (getDolGlobalString(''MAIN_CURL_DISABLE_VERIFYPEER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CURL_GET_RESPONSE_HEADER', 'string', NULL, 'core', 'Makes Dolibarr''s internal cURL wrapper (getURLContent) include the raw HTTP response header in the returned content.', 'core/lib/geturl.lib.php:98: `if (getDolGlobalInt(''MAIN_CURL_GET_RESPONSE_HEADER'')) { curl_setopt($ch, CURLOPT_HEADER, true); // To be able to retrieve response header }`, and reused at line 377 for HEAD-like requests: `if ($postorget == ''HEAD'' || getDolGlobalInt(''MAIN_CURL_GET_RESPONSE_HEADER'')) { // In this case, response contains header + body }`.', 'Setting it to a truthy value makes all outbound HTTP calls made via getURLContent() prepend the response headers to the body in the returned content, which callers must then account for when parsing the response.', 'Truthy = CURLOPT_HEADER enabled, response contains header + body; 0/unset = only body returned (except for HEAD requests, which always include headers).', 1, 0, NULL, 1, '955804d638c58039abfc58265f8e7ab4532f89d1a223b1707fa98686e2eee724', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/geturl.lib.php:98: if (getDolGlobalInt(''MAIN_CURL_GET_RESPONSE_HEADER'')) { curl_setopt($ch, CURLOPT_HEADER, true); // To be able to retrieve response header }", "core/lib/geturl.lib.php:377: if ($postorget == ''HEAD'' || getDolGlobalInt(''MAIN_CURL_GET_RESPONSE_HEADER'')) { // In this case, response contains header + body"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CURL_SSLVERSION', 'string', NULL, 'core', 'Overrides the SSL/TLS version used by the Dolibarr cURL HTTP client.', 'Checked and read in core/lib/geturl.lib.php at lines 102-103. When set, the value is interpreted as either a numeric cURL constant or a named constant string, and passed as the CURLOPT_SSLVERSION option. No admin UI write is present.', 'When set, forces all outbound cURL requests to use the specified SSL version, which can resolve compatibility issues with certain servers or cause connection failures if the version is unsupported.', 'Numeric cURL CURLOPT_SSLVERSION value (e.g. 6 for TLSv1.2) or a named constant string (e.g. ''CURL_SSLVERSION_TLSv1_2''); empty or unset uses the cURL default.', 1, 0, NULL, 1, 'bbf0e0469b32788f059a94314d88bad99a6f1d76748a60946a3c1c8f8309c252', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/geturl.lib.php:102|check|if (getDolGlobalString(''MAIN_CURL_SSLVERSION'')) {", "core/lib/geturl.lib.php:103|read|$sslversion = is_numeric(getDolGlobalString(''MAIN_CURL_SSLVERSION'')) ? getDolGlobalInt(''MAIN_CURL_SSLVERSION'') : constant(getDolGlobalString(''MAIN_CURL_SSLVERSION''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_CUSTOMERS_ARE_COMPANIES_EVEN_IF_SET_AS_INDIVIDUAL', 'string', NULL, 'societe', 'Forces thirdparties to be treated as companies even when their type (typent_code) is explicitly set to an individual/private type.', 'Checked in societe/class/societe.class.php:4443 inside isACompany(): if not set, thirdparties whose typent_code matches ''^TE_PRIVATE'' are classified as individual (isACompany=0); if set, they are forced to isACompany=4 (company) regardless of typent_code. The inline comment marks it ''// never or rarely set''.', 'Enabling it overrides the normal individual/company classification derived from typent_code, forcing all such thirdparties to be treated as companies; this is described in code as rarely used.', 'Boolean-like: truthy forces company classification even for TE_PRIVATE typent_code thirdparties.', 1, 0, NULL, 1, 'c6bd02a47a77c6d496882479b70b872f3e500aab0696cec6826ec870bf2767ab', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4443|check|if (!getDolGlobalString(''MAIN_CUSTOMERS_ARE_COMPANIES_EVEN_IF_SET_AS_INDIVIDUAL'')) {\t// never or rarely set"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DASHBOARD_USE_TOTAL_HT', 'bool', NULL, 'comm', 'Switches commercial dashboard amount columns from TTC (tax-inclusive) to HT (tax-exclusive) totals.', 'Read in at least 8 locations in comm/index.php (lines 193, 225, 229, 297, 326, 330, 398, 429 and more) to select between total_ht and total_ttc when rendering dashboard summary rows.', 'Enabling this causes the commercial dashboard to display pre-tax amounts instead of tax-inclusive totals across all proposal, order, and invoice summary rows.', 'Empty/not set = TTC (tax-inclusive) totals shown; any truthy string = HT (tax-exclusive) totals shown', 1, 0, NULL, 1, '6dd686c4552b97d3d9a99d3d8cc8a328ad0fa76928c6dd2ddc5de4d8c8a0455c', 'v2', '2026-04-21T11:16:15+00:00', '["comm/index.php:193|read|$total += (getDolGlobalString(''MAIN_DASHBOARD_USE_TOTAL_HT'') ? $obj->total_ht : $obj->total_ttc);", "comm/index.php:225|read|print ''<td class=\"nowrap right tdamount amount\">''.price((getDolGlobalString(''MAIN_DASHBOARD_USE_TOTAL_HT'') ? $obj->total_ht : $obj->total_ttc)).''</td>'';", "comm/index.php:297|read|$total += (getDolGlobalString(''MAIN_DASHBOARD_USE_TOTAL_HT'') ? $obj->total_ht : $obj->total_ttc);", "comm/index.php:326|read|print ''<td class=\"nowrap right tdamount amount\">''.price(getDolGlobalString(''MAIN_DASHBOARD_USE_TOTAL_HT'') ? $obj->total_ht : $obj->total_ttc).''</td>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DATABASE_PWD_CONFIG_ENCRYPTED', 'string', NULL, 'admin', 'Would flag that the database password stored in conf.php is encrypted, but both the set and delete calls are currently dead (commented-out) code.', 'Both occurrences in admin/security.php (lines 129 and 141) are commented out (''// dolibarr_set_const...'' and ''// dolibarr_del_const...''); the surrounding active code (encodedecode_dbpassconf()) manages the conf.php password encryption toggle but explicitly notes ''database value not required'' for this constant, since the real state is tracked in conf.php itself (DATABASE_PWD_ENCRYPTED), not the database.', 'No effect: this constant is not actually written or deleted anywhere active in the code; the real encryption state is a conf.php-level setting (DATABASE_PWD_ENCRYPTED), not this DB constant.', 'Not specified; the dead code only ever attempted the literal ''1''.', 1, 0, 'admin/security.php|admin/security.php', 1, '79f7b85bf0b3ab8f51ea5deeae2b1920f6739145411607deae30b220bc327f65', 'v2', '2026-07-24T07:05:23+00:00', '["admin/security.php:129|write (commented)|// dolibarr_set_const($db, \"MAIN_DATABASE_PWD_CONFIG_ENCRYPTED\", \"1\");", "admin/security.php:141|write (commented)|// dolibarr_del_const($db, \"MAIN_DATABASE_PWD_CONFIG_ENCRYPTED\",$conf->entity);", "admin/security.php: // database value not required"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DATE_IN_MEMORY_ARE_NOT_GMT', 'string', NULL, 'core', 'Disables forcing UTC/GMT timezone when building in-memory DateTime objects for date-add/subtract helper calculations.', 'Checked in core/lib/date.lib.php:167 with a function_exists guard (''Add function_exists to allow usage of this function with minimal context''); when unset (default), the DateTime is forced to UTC via setTimezone(new DateTimeZone(''UTC'')).', 'Setting it truthy skips forcing the internal DateTime object to UTC, so date arithmetic in this helper uses the PHP process''s default timezone instead of GMT; may change computed date/time results depending on server timezone.', 'Truthy skips forcing UTC on the internal DateTime object; empty/0 (default) forces UTC.', 1, 0, NULL, 1, '048dcf9315202e25f05bb5990f8fd9113a6034bfc80eb60eb7fc48fa9453cbff', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/date.lib.php:167: if (!function_exists(''getDolGlobalString'') || !getDolGlobalString(''MAIN_DATE_IN_MEMORY_ARE_NOT_GMT'')) {\t// Add function_exists to allow usage of this function with minimal context"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DB_AUTOFIX_BAD_SQL_REQUEST', 'string', NULL, 'core', 'On PostgreSQL, auto-quotes unquoted date-time literals found in SQL requests before execution.', 'Used in core/db/pgsql.class.php:529 inside DoliDBPgsql::query(): when set, the code loops and regex-fixes occurrences of unquoted ''YYYY-MM-DD HH:MM:SS'' patterns in the query by wrapping them in quotes, logging a warning each time via dol_syslog.', 'Enabling it silently rewrites malformed SQL requests containing bare date-time literals instead of failing; the code comment notes such malformed requests ''should not occur'', implying this is a defensive/compatibility workaround rather than a normal-use setting.', 'Boolean-like: truthy enables the auto-fix loop for unquoted date-time literals in queries; only applies to the PostgreSQL driver.', 1, 0, NULL, 1, 'f27a8831cd041f420a81c79ea9ff85f70b717c1f4b5ab1ac62fb97b9c0cf2ac9', 'v2', '2026-07-24T07:05:23+00:00', '["core/db/pgsql.class.php:529|check|if (getDolGlobalString(''MAIN_DB_AUTOFIX_BAD_SQL_REQUEST'')) {", "core/db/pgsql.class.php:530|// Fix bad formed requests. If request contains a date without quotes, we fix this but this should not occurs."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_DATE_END_HOUR', 'string', NULL, 'core', 'Sets the default hour value pre-filled in the service end date hour field on document line forms.', 'When non-empty, jQuery sets the value of #date_endhour to this constant''s value on both the create form (core/tpl/objectline_create.tpl.php:663-664) and the edit form (core/tpl/objectline_edit.tpl.php:481-482).', 'Setting this constant causes the end hour field to be pre-populated with the specified hour value, overriding the blank default.', 'Any non-empty string/integer representing an hour; empty/unset = field left blank.', 1, 0, NULL, 1, '4b277637107af50abbff0a447e9ccff7c01223a4c69c3c4f5c8c81124e7c9caf', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:663|check|if (getDolGlobalString(''MAIN_DEFAULT_DATE_END_HOUR'')) {", "core/tpl/objectline_create.tpl.php:664|read|print ''jQuery(\"#date_endhour\").val(\"'' . getDolGlobalString(''MAIN_DEFAULT_DATE_END_HOUR'').''\");'';", "core/tpl/objectline_edit.tpl.php:481|check|if (getDolGlobalString(''MAIN_DEFAULT_DATE_END_HOUR'') != '''') {", "core/tpl/objectline_edit.tpl.php:482|read|print ''jQuery(\"#date_endhour\").val(\"'' . getDolGlobalString(''MAIN_DEFAULT_DATE_END_HOUR'').''\");'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_DATE_END_MIN', 'string', NULL, 'core', 'Sets the default minute value pre-filled in the service end date minute field on document line forms.', 'When non-empty, jQuery sets the value of #date_endmin to this constant''s value on both the create form (core/tpl/objectline_create.tpl.php:666-667) and the edit form (core/tpl/objectline_edit.tpl.php:484-485).', 'Setting this constant causes the end minute field to be pre-populated with the specified minute value, overriding the blank default.', 'Any non-empty string/integer representing a minute; empty/unset = field left blank.', 1, 0, NULL, 1, '3d4511aca1a1fc64df865bc3b8b79a5dc85c2172d207b7c87c8ca0a45dd52f87', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:666|check|if (getDolGlobalString(''MAIN_DEFAULT_DATE_END_MIN'')) {", "core/tpl/objectline_create.tpl.php:667|read|print ''jQuery(\"#date_endmin\").val(\"'' . getDolGlobalString(''MAIN_DEFAULT_DATE_END_MIN'').''\");'';", "core/tpl/objectline_edit.tpl.php:484|check|if (getDolGlobalString(''MAIN_DEFAULT_DATE_END_MIN'') != '''') {", "core/tpl/objectline_edit.tpl.php:485|read|print ''jQuery(\"#date_endmin\").val(\"'' . getDolGlobalString(''MAIN_DEFAULT_DATE_END_MIN'').''\");'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_DATE_HOUR', 'string', NULL, 'core', 'Sets the default hour value pre-filled in date/time selectors when no date is set.', 'Used in Form::select_date() in core/class/html.form.class.php:8378 as the fallback for $shour when the date is empty or -1, defaulting to ''23'' if $h == -1 else ''''.', 'Changing it changes which hour is pre-selected in date pickers that have no explicit value; only applies to the specific end-of-range case where $h == -1.', 'Any hour string (e.g. ''23''); default fallback used by code is ''23'' when $h==-1, else ''''.', 1, 0, NULL, 1, '8483af0ca97fec327cf4ba087567ebd62a10b2b4a2537d9005960b45c402d061', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:8378|read|$shour = getDolGlobalString(''MAIN_DEFAULT_DATE_HOUR'', ($h == -1 ? ''23'' : ''''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_DATE_MIN', 'string', NULL, 'core', 'Sets the default minute value pre-filled in date/time selectors when no date is set.', 'Used in Form::select_date() in core/class/html.form.class.php:8379 as the fallback for $smin when the date is empty or -1, defaulting to ''59'' if $h == -1 else ''''.', 'Changing it changes which minute is pre-selected in date pickers that have no explicit value; only applies to the specific end-of-range case where $h == -1.', 'Any minute string (e.g. ''59''); default fallback used by code is ''59'' when $h==-1, else ''''.', 1, 0, NULL, 1, '2f427ac8e5c2cd739e8fe35e024aaf3f1c3483398b8e1154e94adeb56f98ddc4', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:8379|read|$smin = getDolGlobalString(''MAIN_DEFAULT_DATE_MIN'', ($h == -1 ? ''59'' : ''''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_DATE_SEC', 'string', NULL, 'core', 'Sets the default second value pre-filled in date/time selectors when no date is set.', 'Used in Form::select_date() in core/class/html.form.class.php:8380 as the fallback for $ssec when the date is empty or -1, defaulting to ''59'' if $h == -1 else ''''.', 'Changing it changes which second is pre-selected in date pickers that have no explicit value; only applies to the specific end-of-range case where $h == -1.', 'Any second string (e.g. ''59''); default fallback used by code is ''59'' when $h==-1, else ''''.', 1, 0, NULL, 1, '5751a5ea68673348b7d0e653dc9896146a12eb608847c57c6e375ff18098c1b8', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:8380|read|$ssec = getDolGlobalString(''MAIN_DEFAULT_DATE_SEC'', ($h == -1 ? ''59'' : ''''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_DATE_START_HOUR', 'string', NULL, 'core', 'Sets the default hour value pre-filled in the service start date hour field on document line forms.', 'When non-empty, jQuery sets the value of #date_starthour to this constant''s value on both the create form (core/tpl/objectline_create.tpl.php:655-656) and the edit form (core/tpl/objectline_edit.tpl.php:463-464).', 'Setting this constant causes the start hour field to be pre-populated with the specified hour value, overriding the blank default.', 'Any non-empty string/integer representing an hour; empty/unset = field left blank.', 1, 0, NULL, 1, 'b5b2945ff33865eeebaa8513184a9486cd245767b083a8753193bf2487945376', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:655|check|if (getDolGlobalString(''MAIN_DEFAULT_DATE_START_HOUR'') != '''') {", "core/tpl/objectline_create.tpl.php:656|read|print ''jQuery(\"#date_starthour\").val(\"'' . getDolGlobalString(''MAIN_DEFAULT_DATE_START_HOUR'').''\");'';", "core/tpl/objectline_edit.tpl.php:463|check|if (getDolGlobalString(''MAIN_DEFAULT_DATE_START_HOUR'') != '''') {", "core/tpl/objectline_edit.tpl.php:464|read|print ''jQuery(\"#date_starthour\").val(\"'' . getDolGlobalString(''MAIN_DEFAULT_DATE_START_HOUR'').''\");'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_DATE_START_MIN', 'string', NULL, 'core', 'Sets the default minute value pre-filled in the service start date minute field on document line forms.', 'When non-empty, jQuery sets the value of #date_startmin to this constant''s value on both the create form (core/tpl/objectline_create.tpl.php:658-659) and the edit form (core/tpl/objectline_edit.tpl.php:466-467).', 'Setting this constant causes the start minute field to be pre-populated with the specified minute value, overriding the blank default.', 'Any non-empty string/integer representing a minute; empty/unset = field left blank.', 1, 0, NULL, 1, '741207a785e0b0d49246b315ee3482c026c1a6f225f8a48c8196ffe8dfb5088c', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:658|check|if (getDolGlobalString(''MAIN_DEFAULT_DATE_START_MIN'') != '''') {", "core/tpl/objectline_create.tpl.php:659|read|print ''jQuery(\"#date_startmin\").val(\"'' . getDolGlobalString(''MAIN_DEFAULT_DATE_START_MIN'').''\");'';", "core/tpl/objectline_edit.tpl.php:466|check|if (getDolGlobalString(''MAIN_DEFAULT_DATE_START_MIN'') != '''') {", "core/tpl/objectline_edit.tpl.php:467|read|print ''jQuery(\"#date_startmin\").val(\"'' . getDolGlobalString(''MAIN_DEFAULT_DATE_START_MIN'').''\");'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_LANGUAGE_FILTER', 'string', NULL, 'core', 'Adds a default language-code filter to the language selector combo (Form::select_language).', 'Used in core/class/html.formadmin.class.php:79-83; if set, its value is added as a key to the $filter array passed into get_available_languages(), restricting/filtering the displayed languages.', 'Setting it to a language code filters the language dropdown lists shown throughout the UI to only include/exclude that filter entry, changing which languages users can pick from.', 'String: a language filter key added to the $filter array used by get_available_languages(); empty/unset applies no extra filter.', 1, 0, NULL, 1, '864d1e12b1521b183396da2c8454c9271837d69e2c18c75d23373065bca1d395', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formadmin.class.php:79: if (getDolGlobalString(''MAIN_DEFAULT_LANGUAGE_FILTER'')) {", "core/class/html.formadmin.class.php:83: $filter[getDolGlobalString(''MAIN_DEFAULT_LANGUAGE_FILTER'')] = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_PAYMENT_TERM_ID', 'string', NULL, 'core', 'Sets the application-wide default payment term ID pre-selected in payment term dropdowns.', 'Checked and read in core/class/html.form.class.php:4960 and :4962 to pre-select a payment term when none is specified. Also read in societe/card.php:1110. The COMMENTS warn: ''Constant MAIN_DEFAULT_PAYMENT_TERM_ID can be used to set default value but scope is all application, probably not what you want.''', 'Setting this value pre-selects the specified payment term across all payment term selectors in the application. Because the scope is application-wide, this affects all entities and contexts.', 'Integer ID of a payment term record; unset or 0 = no application-wide default.', 1, 0, NULL, 1, '83580445b504c68904d4f41a31e3bb75e3282f6db20eacf64c67d94beaffa1e4', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.form.class.php:4906  *    Constant MAIN_DEFAULT_PAYMENT_TERM_ID can be used to set default value but scope is all application, probably not what you want.", "core/class/html.form.class.php:4960|check|if (empty($selected) && strpos($htmlname, ''search_'') !== 0 && getDolGlobalInt(''MAIN_DEFAULT_PAYMENT_TERM_ID'')) {", "core/class/html.form.class.php:4962|read|$selected = getDolGlobalInt(''MAIN_DEFAULT_PAYMENT_TERM_ID'');", "societe/card.php:1110|read|$paymentTermId = getDolGlobalString(''MAIN_DEFAULT_PAYMENT_TERM_ID'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_PAYMENT_TYPE_ID', 'string', NULL, 'core', 'Sets the application-wide default payment type ID pre-selected in payment type dropdowns.', 'Checked and read in core/class/html.form.class.php:5105 and :5107 to pre-select a payment type when none is specified. Also read in societe/card.php:1115. The COMMENTS note: ''Constant MAIN_DEFAULT_PAYMENT_TYPE_ID can used to set default value but scope is all application, probably not what you want.''', 'Setting this value pre-selects the specified payment type across all payment type selectors in the application. Because the scope is application-wide, this affects all entities and contexts.', 'Integer ID of a payment type record; unset or 0 = no application-wide default.', 1, 0, NULL, 1, '9bf5022b3a5bf07bd46e22ae6060c29fcdf4e0f3d1cb40a62bd150b1a5ad3a33', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.form.class.php:5070  * Constant MAIN_DEFAULT_PAYMENT_TYPE_ID can used to set default value but scope is all application, probably not what you want.", "core/class/html.form.class.php:5105|check|if (empty($selected) && strpos($htmlname, ''search_'') !== 0 && getDolGlobalString(''MAIN_DEFAULT_PAYMENT_TYPE_ID'')) {", "core/class/html.form.class.php:5107|read|$selected = getDolGlobalString(''MAIN_DEFAULT_PAYMENT_TYPE_ID'');", "societe/card.php:1115|read|$paymentTypeId = getDolGlobalString(''MAIN_DEFAULT_PAYMENT_TYPE_ID'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_WAREHOUSE', 'string', NULL, 'product', 'Sets the default warehouse pre-selected in warehouse dropdowns across purchase, sale, and stock forms.', 'Configured via admin/stock.php (written at line 140, read at line 785). Checked in comm/propal/card.php:2350, commande/card.php:2288, product/stock/tpl/stockcorrection.tpl.php:168, and product/class/html.formproduct.class.php:328 when no warehouse is explicitly selected.', 'Setting this constant causes the specified warehouse to be pre-selected in warehouse pickers when no other warehouse is set, streamlining stock operations.', 'Integer warehouse ID; -1 or empty = no default warehouse.', 0, 0, 'admin/stock.php|admin/stock.php|admin/stock.php|admin/stock.php', 1, 'fcf7d55f327c8827b869a6a676a3d25458b79328c47a5fc44566f1303359fab7', 'v2', '2026-04-21T11:16:15+00:00', '["admin/stock.php:140|write|$res = dolibarr_set_const($db, \"MAIN_DEFAULT_WAREHOUSE\", $value, ''chaine'', 0, '''', $conf->entity);", "admin/stock.php:785|read|print $formproduct->selectWarehouses(getDolGlobalInt(''MAIN_DEFAULT_WAREHOUSE'', -1), ''default_warehouse'', '''', 1, 0, 0, '''', 0, 0, array(), ''left reposition'');", "comm/propal/card.php:2350|check|if (empty($object->warehouse_id) && getDolGlobalString(''MAIN_DEFAULT_WAREHOUSE'')) {", "commande/card.php:2288|check|if (empty($object->warehouse_id) && getDolGlobalString(''MAIN_DEFAULT_WAREHOUSE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_WAREHOUSE_USER', 'bool', NULL, 'user', 'Controls whether a per-user default warehouse preference is enabled.', 'Configured via admin/stock.php (read at line 797, checked at line 802). Checked in user/card.php at lines 1490, 1869, and 2948, in user/list.php:742, in product/stock/replenish.php:100, and in product/class/html.formproduct.class.php:332.', 'Enabling this constant activates the per-user warehouse preference feature, allowing each user to have a different default warehouse.', 'Truthy value = per-user default warehouse enabled; empty/unset = feature disabled.', 0, 0, 'admin/stock.php|admin/stock.php', 1, '0e31550f880e38b9d6ad5383500bb5207b03ffce31d3dc91f5678110dd724e8c', 'v2', '2026-04-21T11:16:15+00:00', '["admin/stock.php:797|read|print $form->selectarray(\"MAIN_DEFAULT_WAREHOUSE_USER\", $arrval, getDolGlobalString(''MAIN_DEFAULT_WAREHOUSE_USER''));", "user/card.php:1490|check|if (isModEnabled(''stock'') && getDolGlobalString(''MAIN_DEFAULT_WAREHOUSE_USER'')) {", "product/stock/replenish.php:100|check|if (!GETPOSTISSET(''fk_warehouse'') && (empty($fk_entrepot) || $fk_entrepot <= 0) && getDolGlobalString(''MAIN_DEFAULT_WAREHOUSE_USER'')) {", "product/class/html.formproduct.class.php:332|check|if (is_scalar($selected) && ($selected == ''-2'' || $selected == ''ifone'') && getDolGlobalString(''MAIN_DEFAULT_WAREHOUSE_USER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_WORKING_DAYS', 'string', NULL, 'projet', 'Defines the default working day range (e.g. ''1-5'') used to pre-select days in activity and action views.', 'Stored as a dash-separated string such as ''1-5'' representing day indices. Configured via admin/ihm.php and read in comm/action/pertype.php:151, comm/action/peruser.php:147, projet/activity/perday.php:648, and projet/activity/perweek.php:527 where it is split on ''-'' to derive day boundaries.', 'Changing this value alters the default day range pre-filled in project activity per-day and per-week views as well as action-by-type and action-by-user views.', '''1-5'' (Monday to Friday, default); any dash-separated day index range', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'dff5e3231c0dc1cc26ce5905b9a9cdee8cc9358456b7d6a960fb6e0ea24a2202', 'v2', '2026-04-21T11:16:15+00:00', '["comm/action/pertype.php:151|read|$tmp = getDolGlobalString(''MAIN_DEFAULT_WORKING_DAYS'', ''1-5'');", "projet/activity/perday.php:648|read|$tmparray = explode(''-'', getDolGlobalString(''MAIN_DEFAULT_WORKING_DAYS''));", "admin/ihm.php:496|read|print ''<input type=\"text\" name=\"MAIN_DEFAULT_WORKING_DAYS\" size=\"5\" value=\"'' . getDolGlobalString(''MAIN_DEFAULT_WORKING_DAYS'', ''1-5'') . ''\">'';", "admin/ihm.php:284|write|dolibarr_set_const($db, \"MAIN_DEFAULT_WORKING_DAYS\", GETPOST(\"MAIN_DEFAULT_WORKING_DAYS\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_WORKING_HOURS', 'string', NULL, 'comm', 'Sets the default working hours range (e.g. ''9-18'') used in agenda views to define the visible day range.', 'Written in admin/ihm.php:285 and read in admin/ihm.php:502, comm/action/pertype.php:135, comm/action/peruser.php:131, and comm/action/index.php:1861; the default fallback is ''9-18''.', 'Changing this constant adjusts the start and end hours of the working day displayed in agenda calendar views.', 'String in ''HH-HH'' format (e.g. ''9-18''); default fallback = ''9-18''.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'e34c3061a92ceb2e1c67dcdc387b0f67375c5ca22d88a160a1a99ac174270515', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:502|read|print ''<input type=\"text\" name=\"MAIN_DEFAULT_WORKING_HOURS\" size=\"5\" value=\"'' . getDolGlobalString(''MAIN_DEFAULT_WORKING_HOURS'', ''9-18'') . ''\">'';", "admin/ihm.php:285|write|dolibarr_set_const($db, \"MAIN_DEFAULT_WORKING_HOURS\", GETPOST(\"MAIN_DEFAULT_WORKING_HOURS\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "comm/action/pertype.php:135|read|$tmp = getDolGlobalString(''MAIN_DEFAULT_WORKING_HOURS'', ''9-18'');", "comm/action/index.php:1861|read|$tmp = explode(''-'', getDolGlobalString(''MAIN_DEFAULT_WORKING_HOURS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEFAULT_WORKSTATION', 'string', NULL, 'product', 'Sets the default workstation pre-selected in workstation dropdowns.', 'Checked and read in product/class/html.formproduct.class.php at lines 451, 452, and 455 when the selected value is ''-2'' or ''ifone''.', 'Setting this constant causes the specified workstation to be pre-selected in workstation pickers when no explicit selection is made.', 'String workstation identifier; ''-2'' or ''ifone'' triggers the default lookup.', 1, 0, NULL, 1, '9576570644d2316d018201e7f63691de2a70c88e6e220c0df38d27906d4b6687', 'v2', '2026-04-21T11:16:15+00:00', '["product/class/html.formproduct.class.php:451|check|if (($selected == ''-2'' || $selected == ''ifone'') && getDolGlobalString(''MAIN_DEFAULT_WORKSTATION'')) {", "product/class/html.formproduct.class.php:452|read|$selected = getDolGlobalString(''MAIN_DEFAULT_WORKSTATION'');", "product/class/html.formproduct.class.php:455|check|if (($selected == ''-2'' || $selected == ''ifone'') && getDolGlobalString(''MAIN_DEFAULT_WORKSTATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_ACTIONS_TODO', 'string', '7', 'core', 'Number of days before a pending action is considered overdue and triggers a warning.', 'Read as an integer and multiplied by 24*60*60 to produce a delay in seconds across comm/action/list.php, comm/action/card.php, comm/action/document.php, core/boxes/box_actions.php:113, core/boxes/box_actions_future.php:120, and resource/element_resource.php:331. Default is 7 days set in admin/delais.php:168 with comment ''Must be same value than into conf.class.php''. Managed via admin/delais.php.', 'Increasing this value gives more days before an action is flagged as late; decreasing it makes warnings appear sooner. Affects all action-list and dashboard views that highlight overdue items.', 'Integer number of days; default 7', 0, 0, 'admin/delais.php|admin/delais.php', 1, '525c7be41ae329367ad00e596094de8077b88be9dee063fd90188e7904c78027', 'v2', '2026-04-21T11:16:15+00:00', '["admin/delais.php:168|write|$conf->global->MAIN_DELAY_ACTIONS_TODO = 7; // Must be same value than into conf.class.php", "core/boxes/box_actions_future.php:120|read|$delay_warning = getDolGlobalInt(''MAIN_DELAY_ACTIONS_TODO'') * 24 * 60 * 60;", "core/boxes/box_actions.php:113|read|$delay_warning = getDolGlobalInt(''MAIN_DELAY_ACTIONS_TODO'') * 24 * 60 * 60;", "resource/element_resource.php:331|read|$delay_warning = getDolGlobalInt(''MAIN_DELAY_ACTIONS_TODO'') * 24 * 60 * 60;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_BANK_CREDIT_TRANSFER', 'string', NULL, 'core', 'Number of days used to compute the warning delay for pending bank credit-transfer transactions, with a default of 15 days if unset.', 'Read in core/class/conf.class.php:1284 as `$this->warning_delays[''bank_credit_transfer''] = getDolGlobalInt(''MAIN_DELAY_BANK_CREDIT_TRANSFER'', 15) * 86400;` — the second argument to getDolGlobalInt supplies a built-in default of 15 when the constant is not set. No entry for this constant was found in admin/delais.php.', 'Changing it changes the day-count tolerance before a pending credit-transfer bank transaction is flagged as a warning; if unset it defaults to 15 days.', 'Integer number of days; defaults to 15 if not set; multiplied by 86400 to get a warning delay in seconds.', 1, 0, NULL, 1, '1f4cb4f6877083044bf799899be0cd3cf71d35edff4dd11aa452d3f8e04c0dfb', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1284: $this->warning_delays[''bank_credit_transfer''] = getDolGlobalInt(''MAIN_DELAY_BANK_CREDIT_TRANSFER'', 15) * 86400;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_BANK_DIRECT_DEBIT', 'string', NULL, 'core', 'Number of days used to compute the warning delay for pending bank direct-debit transactions, with a default of 15 days if unset.', 'Read in core/class/conf.class.php:1283 as `$this->warning_delays[''bank_direct_debit''] = getDolGlobalInt(''MAIN_DELAY_BANK_DIRECT_DEBIT'', 15) * 86400;` — the second argument to getDolGlobalInt supplies a built-in default of 15 when the constant is not set. No entry for this constant was found in admin/delais.php.', 'Changing it changes the day-count tolerance before a pending direct-debit bank transaction is flagged as a warning; if unset it defaults to 15 days.', 'Integer number of days; defaults to 15 if not set; multiplied by 86400 to get a warning delay in seconds.', 1, 0, NULL, 1, '1f6d4803cec338b68066d1dd3c8cb099d6531b4dbff7c29ecab62b73321b351a', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1283: $this->warning_delays[''bank_direct_debit''] = getDolGlobalInt(''MAIN_DELAY_BANK_DIRECT_DEBIT'', 15) * 86400;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_CHEQUES_TO_DEPOSIT', 'string', NULL, 'core', 'Number of days used to trigger the ''cheques waiting to be deposited'' warning/alert on the Dolibarr home dashboard.', 'Read in core/class/conf.class.php:1282 and :1288 as `getDolGlobalInt(''MAIN_DELAY_CHEQUES_TO_DEPOSIT'') * 86400`, stored into $this->warning_delays[''bank_cheque_to_be_deposited''] and $this->bank->cheque->warning_delay, and exposed in admin/delais.php (code ''MAIN_DELAY_CHEQUES_TO_DEPOSIT'', under the ''banque'' section).', 'Increasing the value raises the tolerance (in days) before undeposited cheques are flagged as late on the dashboard.', 'Integer number of days; multiplied by 86400 to get a warning delay in seconds.', 0, 0, NULL, 1, 'ae86ada547793a52636db9a647b4e3c1f202699cc40d85e4e99deb2c33694e7f', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1282: $this->warning_delays[''bank_cheque_to_be_deposited''] = getDolGlobalInt(''MAIN_DELAY_CHEQUES_TO_DEPOSIT'') * 86400;", "core/class/conf.class.php:1288: $this->bank->cheque->warning_delay = getDolGlobalInt(''MAIN_DELAY_CHEQUES_TO_DEPOSIT'') * 86400;", "admin/delais.php:127: ''code'' => ''MAIN_DELAY_CHEQUES_TO_DEPOSIT'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_CUSTOMER_BILLS_UNPAYED', 'string', '31', 'core', 'Sets the number of days after customer invoice due date before unpaid invoices trigger a warning.', 'Read in core/class/conf.class.php:1255 and 1259, multiplied by 86400 for the customer invoice warning_delay.', 'Increasing this value extends the period before unpaid customer invoices are flagged. Decreasing it triggers earlier payment warnings.', 'Integer number of days; default 31 (configured DEFAULT)', 1, 1, NULL, 1, '29388736d1aa127721003ed0c9dca9b478191366733e1b83aaccb6e040b8500f', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/conf.class.php:1255|read|$this->warning_delays[''invoice''] = getDolGlobalInt(''MAIN_DELAY_CUSTOMER_BILLS_UNPAYED'') * 86400;", "core/class/conf.class.php:1259|read|$this->facture->client->warning_delay = getDolGlobalInt(''MAIN_DELAY_CUSTOMER_BILLS_UNPAYED'') * 86400;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_EXPENSEREPORTS', 'string', NULL, 'core', 'Number of days used to trigger the ''expense report waiting for approval'' warning/alert on the Dolibarr home dashboard.', 'Read in core/class/conf.class.php:1291 and :1294 as `getDolGlobalInt(''MAIN_DELAY_EXPENSEREPORTS'') * 86400`, stored into $this->warning_delays[''expensereport_approve''] and $this->expensereport->approve->warning_delay, and exposed in admin/delais.php (code ''MAIN_DELAY_EXPENSEREPORTS'', under the ''expensereport'' section). A related comment notes: ''No delay configured (MAIN_DELAY_EXPENSEREPORTS / MIN_DELAY_EXPENSEREPORTS_TO_PAY not set), so nothing is late.''', 'Increasing the value raises the tolerance (in days) before an expense report pending approval is flagged as late on the dashboard.', 'Integer number of days; multiplied by 86400 to get a warning delay in seconds.', 0, 0, NULL, 1, '8e80d8c4c4bcd1051408b11c2a94a244bc832cfd581ef461d9623e4269b29c3b', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1291: $this->warning_delays[''expensereport_approve''] = getDolGlobalInt(''MAIN_DELAY_EXPENSEREPORTS'') * 86400;", "expensereport/class/expensereport.class.php:2663: // No delay configured (MAIN_DELAY_EXPENSEREPORTS / MIN_DELAY_EXPENSEREPORTS_TO_PAY not set), so nothing is late.", "admin/delais.php:139: ''code'' => ''MAIN_DELAY_EXPENSEREPORTS'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_EXPENSEREPORTS_TO_PAY', 'string', '31', NULL, 'Tolerance delay in days before an alert is raised for expense reports that are due to be paid; declared as a default constant by the ExpenseReport module but not currently wired into any active admin screen.', 'Default value ''31'' registered in core/modules/modExpenseReport.class.php:95-98 with the label ''Tolerance delay (in days) before alert for expense reports to pay''; its entry in admin/delais.php is commented out (lines 141-146: ''/* TODO Enable this ... */''), so it is not currently exposed in the admin delay-alerts screen (CONF_PHP_WIRING: must be set via conf.php or direct constant, no live admin UI).', 'If manually set (e.g. in conf.php or database const table), it would presumably control the alert threshold for overdue expense-report payments, mirroring the sibling MAIN_DELAY_EXPENSEREPORTS constant, but since the admin/delais.php row is commented out, no UI currently reads/displays it [SPECULATION].', 'Numeric string, number of days; module registers default ''15'' (modExpenseReport.class.php), while the payload''s extracted DEFAULT field shows ''31'' - source of this discrepancy not resolved by the code read.', 1, 1, NULL, 1, '6f327e2d70229527ee5f92c89879f94fbec2c062b226cf27490ed9e6b95f8a3e', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modExpenseReport.class.php:94-98: [\"MAIN_DELAY_EXPENSEREPORTS_TO_PAY\", \"chaine\", \"15\", ''Tolerance delay (in days) before alert for expense reports to pay'', 0],", "admin/delais.php:141-146: /* TODO Enable this array( ''code'' => ''MAIN_DELAY_EXPENSEREPORTS_TO_PAY'', ''img'' => ''trip'' )*/"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_HOLIDAYS', 'string', NULL, 'core', 'Number of days used to trigger the ''holiday/leave request waiting for approval'' warning/alert on the Dolibarr home dashboard.', 'Read in core/class/conf.class.php:1299 and :1301 as `getDolGlobalInt(''MAIN_DELAY_HOLIDAYS'') * 86400`, stored into $this->warning_delays[''holiday_approve''] and $this->holiday->approve->warning_delay, and exposed in admin/delais.php (code ''MAIN_DELAY_HOLIDAYS'', under the ''holiday'' section).', 'Increasing the value raises the tolerance (in days) before a holiday/leave request pending approval is flagged as late on the dashboard.', 'Integer number of days; multiplied by 86400 to get a warning delay in seconds.', 0, 0, NULL, 1, '76a144590574328bf5d57d9413bcee8a7c23b004708234a8c17c8a3297769424', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1299: $this->warning_delays[''holiday_approve''] = getDolGlobalInt(''MAIN_DELAY_HOLIDAYS'') * 86400;", "core/class/conf.class.php:1301: $this->holiday->approve->warning_delay = getDolGlobalInt(''MAIN_DELAY_HOLIDAYS'') * 86400;", "admin/delais.php:150: ''code'' => ''MAIN_DELAY_HOLIDAYS'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_MEMBERS', 'string', '31', 'core', 'Sets the number of days after a membership subscription expires before a warning is triggered.', 'Written in admin/delais.php:165 with a default of 0 when not set. Read in core/class/conf.class.php:1214 and 1216 and multiplied by 86400 to convert days to seconds for the warning_delay on subscriptions.', 'Increasing this value extends the grace period before overdue membership warnings appear. Setting to 0 disables the delay-based warning.', 'Integer number of days; default 31 (configured DEFAULT); 0 = no delay warning', 0, 0, 'admin/delais.php|admin/delais.php', 1, '61dacd61ee2d09e439a57be8d8c46e8936b914d1101005b016734a322c7c270a', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/conf.class.php:1214|read|$this->warning_delays[''subscription''] = getDolGlobalInt(''MAIN_DELAY_MEMBERS'') * 86400;", "core/class/conf.class.php:1216|read|$this->adherent->subscription->warning_delay = getDolGlobalInt(''MAIN_DELAY_MEMBERS'') * 86400;", "admin/delais.php:165|write|$conf->global->MAIN_DELAY_MEMBERS = 0; // Must be same value than into conf.class.php"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_MRP', 'string', NULL, 'core', 'Number of days used to trigger a warning/alert for MRP (manufacturing order) progress on the Dolibarr home dashboard.', 'Read in core/class/conf.class.php:1304 and :1306 as `getDolGlobalInt(''MAIN_DELAY_MRP'') * 86400`, stored into $this->warning_delays[''mrp''] and $this->mrp->progress->warning_delay, following the same pattern as the other MAIN_DELAY_* dashboard-warning constants in this file.', 'Increasing the value raises the tolerance (in days) before an MRP-related item is flagged as late/stalled on the dashboard.', 'Integer number of days; multiplied by 86400 to get a warning delay in seconds.', 0, 0, NULL, 1, '11bbeb816116912ea3ea8810e376b6b71aeb6cd5cde2f09bf4c0dc6768fbd256', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1304: $this->warning_delays[''mrp''] = getDolGlobalInt(''MAIN_DELAY_MRP'') * 86400;", "core/class/conf.class.php:1306: $this->mrp->progress->warning_delay = getDolGlobalInt(''MAIN_DELAY_MRP'') * 86400;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_NOT_ACTIVATED_SERVICES', 'string', '0', 'core', 'Number of days used to trigger the ''contract service not yet activated'' warning/alert on the Dolibarr home dashboard.', 'Read in core/class/conf.class.php:1272 and :1277 as `getDolGlobalInt(''MAIN_DELAY_NOT_ACTIVATED_SERVICES'') * 86400`, stored into $this->warning_delays[''contract_inactive''] and $this->contrat->services->inactifs->warning_delay, and exposed in admin/delais.php (code ''MAIN_DELAY_NOT_ACTIVATED_SERVICES'', under the ''service'' section).', 'Increasing the value raises the delay tolerance before an inactive contract service is flagged as late on the dashboard.', 'Integer number of days (default ''0'' per payload); multiplied by 86400 to get a warning delay in seconds.', 0, 1, NULL, 1, '4513d26916d96c5a4f62a8e827e44966880f2803638d0a57df7bab3fa16b920b', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1272: $this->warning_delays[''contract_inactive''] = getDolGlobalInt(''MAIN_DELAY_NOT_ACTIVATED_SERVICES'') * 86400;", "core/class/conf.class.php:1277: $this->contrat->services->inactifs->warning_delay = getDolGlobalInt(''MAIN_DELAY_NOT_ACTIVATED_SERVICES'') * 86400;", "admin/delais.php:113: ''code'' => ''MAIN_DELAY_NOT_ACTIVATED_SERVICES'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_ORDERS_TO_PROCESS', 'string', '2', 'admin', 'Sets the number of days after order creation before unprocessed orders trigger a warning.', 'Written multiple times in admin/delais.php with a default of 2 days. Read in core/class/conf.class.php and multiplied by 86400 for warning_delay. The admin/delais.php file resets the value to 2 in multiple conditions.', 'Increasing this value gives more time before orders are flagged as overdue. Decreasing it triggers earlier warnings for pending orders.', 'Integer number of days; default 2', 0, 0, 'admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php', 1, 'f6014042d3b719e8504dec4b835b2c9a3fa625474ae64d21637a6a99a62f2000', 'v2', '2026-04-21T13:29:58+00:00', '["admin/delais.php:171|write|$conf->global->MAIN_DELAY_ORDERS_TO_PROCESS = 2;", "admin/delais.php:170|read|if (!isset($conf->global->MAIN_DELAY_ORDERS_TO_PROCESS)) {", "admin/delais.php:177|write|$conf->global->MAIN_DELAY_ORDERS_TO_PROCESS = 2;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_PROJECT_TO_CLOSE', 'string', NULL, 'core', 'Sets the number of days before a project''s expected close date at which a warning is triggered.', 'Read in core/class/conf.class.php:1223 and 1225, both with a default of 7 days when not set. Multiplied by 86400 to convert to seconds for warning_delay on projects.', 'Increasing this value gives earlier warnings for projects approaching their close date. Decreasing it shortens the warning window.', 'Integer number of days; default 7 when not set', 1, 0, NULL, 1, '55e0ebc7762a9b37db64d511d468420361ae67c466736a1b5c983da2b18fa447', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/conf.class.php:1223|read|$this->warning_delays[''project''] = (getDolGlobalInt(''MAIN_DELAY_PROJECT_TO_CLOSE'', 7) * 86400);", "core/class/conf.class.php:1225|read|$this->projet->warning_delay = (getDolGlobalInt(''MAIN_DELAY_PROJECT_TO_CLOSE'', 7) * 86400);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_PROPALS_TO_BILL', 'string', '7', 'core', 'Sets the number of days after proposal acceptance before unbilled proposals trigger a billing warning.', 'Read in core/class/conf.class.php:1239 and 1243, multiplied by 86400 for the proposal billing warning_delay.', 'Increasing this value extends the grace period before accepted proposals are flagged for invoicing. Decreasing it triggers earlier billing warnings.', 'Integer number of days; default 7 (configured DEFAULT)', 1, 1, NULL, 1, 'a98c4db79505b4e7a44906471613423e7c72c62adc782076ff855b0a9fd56fe0', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/conf.class.php:1239|read|$this->warning_delays[''proposal_invoice''] = getDolGlobalInt(''MAIN_DELAY_PROPALS_TO_BILL'') * 86400;", "core/class/conf.class.php:1243|read|$this->propal->facturation->warning_delay = getDolGlobalInt(''MAIN_DELAY_PROPALS_TO_BILL'') * 86400;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_PROPALS_TO_CLOSE', 'string', '31', 'core', 'Sets the number of days after proposal creation before open proposals trigger a closing warning.', 'Read in core/class/conf.class.php:1238 and 1242, multiplied by 86400 for the proposal close warning_delay.', 'Increasing this value delays when open proposals are flagged for closing. Decreasing it triggers earlier closing warnings.', 'Integer number of days; default 31 (configured DEFAULT)', 1, 1, NULL, 1, '143c03f4cccc22a1289c5786dfbe5ca24c37be2b057a4f86c427383e96d35ee8', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/conf.class.php:1238|read|$this->warning_delays[''proposal_close''] = getDolGlobalInt(''MAIN_DELAY_PROPALS_TO_CLOSE'') * 86400;", "core/class/conf.class.php:1242|read|$this->propal->cloture->warning_delay = getDolGlobalInt(''MAIN_DELAY_PROPALS_TO_CLOSE'') * 86400;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_RUNNING_SERVICES', 'string', '0', 'core', 'Number of days before contract service expiration used to trigger the ''service about to expire'' warning/alert on the Dolibarr home dashboard.', 'Read in core/class/conf.class.php:1273 and :1278 as `getDolGlobalInt(''MAIN_DELAY_RUNNING_SERVICES'') * 86400`, stored into $this->warning_delays[''contract_expired''] and $this->contrat->services->expires->warning_delay, and exposed in admin/delais.php (code ''MAIN_DELAY_RUNNING_SERVICES'', under the ''service'' section).', 'Increasing the value raises the number of days before expiration at which a running contract service starts being flagged on the dashboard.', 'Integer number of days (default ''0'' per payload); multiplied by 86400 to get a warning delay in seconds.', 0, 1, NULL, 1, '273e9296e6dfbb2aeea3a2c4acf90094f7780748773dac09de727e670b8b1fab', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1273: $this->warning_delays[''contract_expired''] = getDolGlobalInt(''MAIN_DELAY_RUNNING_SERVICES'') * 86400;", "core/class/conf.class.php:1278: $this->contrat->services->expires->warning_delay = getDolGlobalInt(''MAIN_DELAY_RUNNING_SERVICES'') * 86400;", "admin/delais.php:117: ''code'' => ''MAIN_DELAY_RUNNING_SERVICES'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_SUPPLIER_BILLS_TO_PAY', 'string', '2', 'core', 'Number of days before a supplier invoice due date used to trigger the ''unpaid supplier bill'' warning/alert on the Dolibarr home dashboard.', 'Read in core/class/conf.class.php:1265 and :1269 as `getDolGlobalInt(''MAIN_DELAY_SUPPLIER_BILLS_TO_PAY'') * 86400`, stored into $this->warning_delays[''supplier_invoice''] and $this->facture->fournisseur->warning_delay, and exposed in the admin delay-settings page (admin/delais.php, code ''MAIN_DELAY_SUPPLIER_BILLS_TO_PAY'').', 'Increasing the value raises the number of days of tolerance before an unpaid supplier bill is flagged as late on the dashboard; the stored value is multiplied by 86400 to become a delay in seconds.', 'Integer number of days (default ''2'' per payload); combined with the invoice due date to compute a warning delay in seconds.', 0, 1, NULL, 1, 'f6d8be0821c603e2576a79b4ad492890ec3cd0da5d741701c1d7a35438919e11', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1265: $this->warning_delays[''supplier_invoice''] = getDolGlobalInt(''MAIN_DELAY_SUPPLIER_BILLS_TO_PAY'') * 86400;", "core/class/conf.class.php:1269: $this->facture->fournisseur->warning_delay = getDolGlobalInt(''MAIN_DELAY_SUPPLIER_BILLS_TO_PAY'') * 86400;", "admin/delais.php:99: ''code'' => ''MAIN_DELAY_SUPPLIER_BILLS_TO_PAY'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_SUPPLIER_ORDERS_TO_PROCESS', 'string', '7', 'core', 'Sets the number of days after supplier order creation before unprocessed supplier orders trigger a warning.', 'Written in admin/delais.php:174 with a default of 7 days. Read in core/class/conf.class.php:1231 and 1235 with a fallback of 7, multiplied by 86400 for the warning_delay on purchase orders.', 'Increasing this value extends the grace period before supplier orders are flagged. Decreasing it shortens the warning window.', 'Integer number of days; default 7', 0, 0, 'admin/delais.php|admin/delais.php', 1, '633354552cd44c4fb4a3cfd3296e9dd70b39d3238edd3bb4dd6eb9491201fd91', 'v2', '2026-04-21T13:29:58+00:00', '["admin/delais.php:174|write|$conf->global->MAIN_DELAY_SUPPLIER_ORDERS_TO_PROCESS = 7;", "core/class/conf.class.php:1231|read|$this->warning_delays[''purchase_order''] = getDolGlobalInt(''MAIN_DELAY_SUPPLIER_ORDERS_TO_PROCESS'', 7) * 86400;", "core/class/conf.class.php:1235|read|$this->commande->fournisseur->warning_delay = getDolGlobalInt(''MAIN_DELAY_SUPPLIER_ORDERS_TO_PROCESS'', 7) * 86400;"]', 'high', NULL);
