INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_SUPPLIER_PROPALS_TO_CLOSE', 'string', NULL, 'core', 'Sets the number of days after supplier proposal creation before open supplier proposals trigger a closing warning.', 'Read in core/class/conf.class.php:1247 and 1251, multiplied by 86400 for the supplier_proposal close warning_delay.', 'Increasing this value delays when open supplier proposals are flagged for closing. Decreasing it triggers earlier warnings.', 'Integer number of days; unset/0 = no warning delay configured', 1, 0, NULL, 1, '39c3da2d7f0051e9896aa4fe21b1d549a4b2281656207926ce717016a780b910', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/conf.class.php:1247|read|$this->warning_delays[''supplier_proposal_close''] = getDolGlobalInt(''MAIN_DELAY_SUPPLIER_PROPALS_TO_CLOSE'') * 86400;", "core/class/conf.class.php:1251|read|$this->supplier_proposal->cloture->warning_delay = getDolGlobalInt(''MAIN_DELAY_SUPPLIER_PROPALS_TO_CLOSE'') * 86400;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_TASKS_TODO', 'string', NULL, 'core', 'Sets the number of days before a task''s due date at which a warning is triggered.', 'Read in core/class/conf.class.php:1224 and 1227, both with a default of 7 days when not set. Multiplied by 86400 to convert to seconds for warning_delay on tasks.', 'Increasing this value provides earlier warnings for overdue tasks. Decreasing it shortens the warning window.', 'Integer number of days; default 7 when not set', 1, 0, NULL, 1, '38c489ec51fd3cf709138b337d8ffb4de526f370137064e193936ef71d7fd659', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/conf.class.php:1224|read|$this->warning_delays[''task''] = (getDolGlobalInt(''MAIN_DELAY_TASKS_TODO'', 7) * 86400);", "core/class/conf.class.php:1227|read|$this->projet->task->warning_delay = (getDolGlobalInt(''MAIN_DELAY_TASKS_TODO'', 7) * 86400);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DELAY_TRANSACTIONS_TO_CONCILIATE', 'string', '62', 'core', 'Number of days used to trigger the ''bank transactions to reconcile'' warning/alert on the Dolibarr home dashboard.', 'Read in core/class/conf.class.php:1281 and :1287 as `getDolGlobalInt(''MAIN_DELAY_TRANSACTIONS_TO_CONCILIATE'') * 86400`, stored into $this->warning_delays[''bank_cheque_to_conciliate''] and $this->bank->rappro->warning_delay, and exposed in admin/delais.php (code ''MAIN_DELAY_TRANSACTIONS_TO_CONCILIATE'', under the ''banque'' section).', 'Increasing the value raises the tolerance (in days) before unreconciled bank transactions are flagged as late.', 'Integer number of days (default ''62'' per payload); multiplied by 86400 to get a warning delay in seconds.', 0, 1, NULL, 1, '719e6b321a3e17e8609c4b5e3182580d05afe2d4b1aa24f2340aef6fda55df15', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1281: $this->warning_delays[''bank_cheque_to_conciliate''] = getDolGlobalInt(''MAIN_DELAY_TRANSACTIONS_TO_CONCILIATE'') * 86400;", "core/class/conf.class.php:1287: $this->bank->rappro->warning_delay = getDolGlobalInt(''MAIN_DELAY_TRANSACTIONS_TO_CONCILIATE'') * 86400;", "admin/delais.php:123: ''code'' => ''MAIN_DELAY_TRANSACTIONS_TO_CONCILIATE'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DEPOSIT_MULTI_TVA', 'string', NULL, 'compta', 'Enables splitting deposit invoice discount lines into multiple lines, one per VAT rate.', 'Checked in 7 locations: compta/facture/card.php:1749 and :1872, fourn/facture/card.php:1194 and :1302, and compta/facture/class/facture.class.php:1809 and :1912. The inline comment at card.php:1749 explicitly states the purpose. No admin UI is present.', 'Enabling this causes deposit balance invoice adjustment lines to be split by VAT rate rather than consolidated into a single line.', '0 or unset = single consolidated adjustment line; truthy value = one line per VAT rate.', 1, 0, NULL, 1, '37a64932c106fda7c1fd2b1395f6b7d296b6f4d9fcdb030f701480eb895bf010', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:1749|check|if (getDolGlobalString(''MAIN_DEPOSIT_MULTI_TVA'')) {\t// We want to split the discount line into several lines, one per vat rate.", "compta/facture/card.php:1866|read|(getDolGlobalString(''MAIN_DEPOSIT_MULTI_TVA'') ? 0 : 1)", "compta/facture/class/facture.class.php:1809|check|if (getDolGlobalString(''MAIN_DEPOSIT_MULTI_TVA'')) {", "fourn/facture/card.php:1194|check|if (getDolGlobalString(''MAIN_DEPOSIT_MULTI_TVA'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DIRECT_STATUS_UPDATE', 'string', NULL, 'core', 'Enables inline AJAX-based status toggling for third-parties and products directly from list views.', 'When set, list pages render AJAX toggle controls (via objectonoff.php) for entity status fields, as documented in core/ajax/objectonoff.php:23 and core/lib/ajax.lib.php:777. Requires JavaScript/AJAX to be enabled and appropriate create rights.', 'Enabling this constant adds interactive status-switch UI elements to list views; disabling it removes those controls, requiring users to open the record to change status.', 'Any truthy value enables inline status updates; unset disables the feature.', 1, 0, NULL, 1, 'cd1b83607fccc2c2dba2655fadbea524057e9e5c8080a2837f7dbbb2f5f964f8', 'v2', '2026-04-21T13:29:58+00:00', '["core/ajax/objectonoff.php:23  *       \t\t\tThis Ajax service is often called when option MAIN_DIRECT_STATUS_UPDATE is set.", "core/lib/ajax.lib.php:777  *  This uses the ajax service objectonoff.php (May be called when MAIN_DIRECT_STATUS_UPDATE is set for some pages)", "core/lib/functions.lib.php:3613|check|if (!empty($conf->use_javascript_ajax) && $user->hasRight(''societe'', ''creer'') && getDolGlobalString(''MAIN_DIRECT_STATUS_UPDATE'')) {", "product/list.php:2415|check|if (!empty($conf->use_javascript_ajax) && $user->hasRight(\"produit\", \"creer\") && getDolGlobalString(''MAIN_DIRECT_STATUS_UPDATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLEDRAFTSTATUS', 'bool', NULL, 'projet', 'Globally disables the ''Draft'' status step across multiple modules, forcing objects to skip draft and go directly to an active status.', 'Checked in projet/card.php:1691 and :1116, projet/class/project.class.php:577, and compta/paiement/cheque/class/remisecheque.class.php:304. When set, the draft button is hidden and newly created objects bypass the draft state. Module-specific overrides (e.g. MAIN_DISABLEDRAFTSTATUS_PROJECT) exist alongside this global flag.', 'Enabling this constant removes the draft status from affected modules application-wide; disabling restores the normal draft workflow.', 'Non-empty = draft status disabled globally; 0 or unset = draft workflow active.', 1, 0, NULL, 1, '46824bc45242257d360db99b1ae8d1682680de3ff3e0d1b85aee4d8cd1b29c54', 'v2', '2026-04-21T11:16:15+00:00', '["projet/card.php:1691|check|if (!getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') && !getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_PROJECT'')) {", "projet/class/project.class.php:577|check|if (!$error && (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_PROJECT''))) {", "compta/paiement/cheque/class/remisecheque.class.php:304|check|if (!$this->errno && (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_CHEQUE''))) {", "projet/card.php:1116|check|if (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_PROJECT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLEDRAFTSTATUS_CHEQUE', 'bool', NULL, 'compta', 'Skips the draft status for cheque deposit slips (RemiseCheque), auto-validating them on creation, specifically for the cheque-remittance object.', 'Read in RemiseCheque::Create() at compta/paiement/cheque/class/remisecheque.class.php:304, combined with the generic MAIN_DISABLEDRAFTSTATUS flag: either one triggers an immediate $this->validate($user) call after creation.', 'When enabled (alone or together with MAIN_DISABLEDRAFTSTATUS), newly created cheque remittances are immediately validated instead of staying in draft status.', 'Boolean-like: truthy causes auto-validation of the cheque remittance right after creation.', 1, 0, NULL, 1, '67538f62f392e73a1b938340b91e766dc39bb5be3f18d9131af0231160b0228f', 'v2', '2026-07-24T07:05:23+00:00', '["remisecheque.class.php:304: if (!$this->errno && (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_CHEQUE''))) { $res = $this->validate($user); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLEDRAFTSTATUS_DONATION', 'bool', NULL, 'don', 'Would disable the draft status step for donations (skip straight to validated), analogous to MAIN_DISABLEDRAFTSTATUS_PROJECT/_CHEQUE used elsewhere, but the only reference in code is commented out.', 'The sole occurrence in don/class/don.class.php:487 is inside a commented-out block (''//if (!$error && (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_DONATION''))) {''), meaning this constant is currently inert/non-functional in the donation module, unlike its active siblings for projects (projet/class/project.class.php:577) and cheques (compta/paiement/cheque/class/remisecheque.class.php:304).', 'Setting this constant currently has no effect, since the only code path that would read it is commented out.', 'Boolean-like (by analogy with active sibling constants MAIN_DISABLEDRAFTSTATUS_PROJECT/_CHEQUE), but currently non-functional in code.', 1, 0, NULL, 1, '74664dd230cbf58bce4b89954ccd59254f994cc45175afc5e3e66126345ca9a6', 'v2', '2026-07-24T07:05:23+00:00', '["don/class/don.class.php:487|//if (!$error && (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_DONATION''))) {", "projet/class/project.class.php:577|if (!$error && (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_PROJECT''))) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLEDRAFTSTATUS_PROJECT', 'bool', NULL, 'projet', 'Disables the Draft status specifically for Projects, auto-validating new projects and hiding Draft from the status selector.', 'Checked together with the global MAIN_DISABLEDRAFTSTATUS in projet/class/project.class.php:577 (auto-calls setValid() on create when either is set) and in projet/card.php:1119/1695 (removes STATUS_DRAFT from the status dropdown and skips draft-only UI).', 'Enabling it makes newly created projects skip the Draft state and go straight to Validated, and removes the Draft option from the project status edit form.', 'Boolean; acts as an OR together with MAIN_DISABLEDRAFTSTATUS (project-specific override/addition).', 1, 0, NULL, 1, '8b6fe649597e65b40f4c8281bb43971cb4c80648a6ee7306a3cce9a71c9fdebb', 'v2', '2026-07-24T07:05:23+00:00', '["projet/class/project.class.php:577: if (!$error && (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_PROJECT''))) {", "projet/card.php:1119: if (getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS'') || getDolGlobalString(''MAIN_DISABLEDRAFTSTATUS_PROJECT'')) { unset($statuses[$object::STATUS_DRAFT]); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLEPROFIDRULES', 'bool', NULL, 'core', 'Disables validation rules applied to professional ID fields (e.g. SIREN/SIRET-like identifiers) on third parties.', 'Checked in societe/class/societe.class.php:4332, core/class/html.formcompany.class.php:981, and core/lib/profid.lib.php:265 to decide whether profid validation rules are enforced.', 'When set, professional ID format/validation rules are bypassed, allowing third-party profid fields to be saved without the normal checks.', NULL, 1, 0, NULL, 1, 'db5d1bc00e18a3349cb03faeba9459c13e7f92ef68d7af8715303a0be240e2e7', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_DISABLEPROFIDRULES'')) {", "if (!getDolGlobalString(''MAIN_DISABLEPROFIDRULES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLEVATCHECK', 'bool', NULL, 'societe', 'Disables VAT number validation for third parties located in the European Economic Area.', 'Checked in societe/canvas/company/actions_card_company.class.php at lines 105, 133, and 161, and in societe/card.php at lines 1790, 2703, and 3220, always combined with isInEEC(). When not set, VAT validation is performed on save.', 'Setting this constant skips the VAT number format/existence check for EEC companies, which may be needed when the validation service is unavailable or for non-standard VAT numbers.', '0 or unset = VAT check enabled for EEC third parties; 1 = VAT check disabled', 1, 0, NULL, 1, '447f582cf9535fc02d44fce3327493df1823f1c282c9e00dfcf3cfe0127b550b', 'v2', '2026-04-21T11:16:15+00:00', '["if (!getDolGlobalString(''MAIN_DISABLEVATCHECK'')) {", "if ($conf->use_javascript_ajax && !getDolGlobalString(''MAIN_DISABLEVATCHECK'')) {", "if (!getDolGlobalString(''MAIN_DISABLEVATCHECK'') && isInEEC($object)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_AJAX_COMBOX', 'bool', NULL, 'core', 'Globally disables the select2/ajax combobox enhancement for all browsers.', 'Checked in ajax_combobox() in core/lib/ajax.lib.php:485, immediately after the smartphone-specific check; when set, the function returns '''' unconditionally, so no ajax combobox JS is generated.', 'Enabling it turns off the select2 ajax combobox feature everywhere in the application, reverting affected selects to plain behavior.', 'Boolean: truthy value makes ajax_combobox() return '''' (feature disabled) for all requests.', 1, 0, NULL, 1, '51efa8f4ebb0be4e78b18df53c10d0e92f5eb89af44924b296d46481b554c800', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/ajax.lib.php:485|check|if (getDolGlobalString(''MAIN_DISABLE_AJAX_COMBOX'')) {", "return '''';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_ALL_MAILS', 'bool', NULL, 'admin', 'Globally disables sending of all outgoing emails from Dolibarr.', 'Set via admin/mails.php:101 (dolibarr_set_const) and checked in admin/mails.php (e.g. lines 694, 703, 873, 902, 1015, 1052) and admin/mails_passwordreset.php:600 before sending mail.', 'When enabled, email sending is blocked application-wide, including password reset and other notification emails.', NULL, 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails.php', 1, '588ef0453dedf2e1849e305dac43ef682029be38b0a33cb07ba29e865ef4efb8', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''MAIN_DISABLE_ALL_MAILS'')) {", "dolibarr_set_const($db, \"MAIN_DISABLE_ALL_MAILS\", GETPOSTINT(\"MAIN_DISABLE_ALL_MAILS\"), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_ALL_SMS', 'bool', NULL, 'admin', 'Globally disables all SMS sending from Dolibarr when enabled.', 'Configured via admin/sms.php (UI write at line 62, displayed as yes/no at line 193). Checked in core/class/CSMSFile.class.php:179: when set, the SMS send code path is skipped.', 'Setting this to a truthy value prevents any SMS from being sent system-wide, regardless of other SMS configuration.', 'Truthy value (e.g. 1) to disable all SMS; 0 or empty to allow SMS sending.', 0, 0, 'admin/sms.php|admin/sms.php|admin/sms.php', 1, '00df05706ab328d251710e90ad4eea0251c3948a2cf3d8209264d704959c119a', 'v2', '2026-04-21T13:50:40+00:00', '["admin/sms.php:193|read|print $form->selectyesno(''MAIN_DISABLE_ALL_SMS'', getDolGlobalString(''MAIN_DISABLE_ALL_SMS''), 1);", "core/class/CSMSFile.class.php:179|check|if (!getDolGlobalString(''MAIN_DISABLE_ALL_SMS'')) {", "admin/sms.php:62|write|dolibarr_set_const($db, \"MAIN_DISABLE_ALL_SMS\", GETPOST(\"MAIN_DISABLE_ALL_SMS\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_AUTOFIX_CORRUPTED_LINES_WHEN_TOTAL_DOES_NOT_MATCH_RECALCULATION_FROM_UP', 'bool', NULL, 'core', 'Disables the automatic SQL fix-up of a document line''s VAT/total_ttc when recalculation from the unit price detects a rounding inconsistency versus the stored line total.', 'Checked in core/class/commonobject.class.php:4184 inside update_price()-style total-recalculation code: `if ($obj->description != ''(DEPOSIT)'' && !getDolGlobalInt(''MAIN_DISABLE_AUTOFIX_CORRUPTED_LINES_WHEN_TOTAL_DOES_NOT_MATCH_RECALCULATION_FROM_UP''))`, guarding an UPDATE that overwrites total_tva/total_ttc/multicurrency totals on the line, per the comment ''this part of code must be called only to fix corrupted data due to the use of the old feature to round total instead of rounding lines''.', 'When left unset (default, autofix enabled), Dolibarr silently rewrites a line''s VAT/TTC totals in the database whenever it detects the old ''round total'' vs ''round per line'' inconsistency; setting it disables this automatic DB correction.', 'Boolean flag; when true, disables the autofix described above (double negative: getDolGlobalInt(...) is negated in the condition, so setting it to a truthy value prevents the fix from running).', 1, 0, NULL, 1, '4e2aec8e17ea48118048b74e383a7a0eb56dc7f99e5eb9c2121a657d7f25bbec', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonobject.class.php:4184|check|if ($obj->description != ''(DEPOSIT)'' && !getDolGlobalInt(''MAIN_DISABLE_AUTOFIX_CORRUPTED_LINES_WHEN_TOTAL_DOES_NOT_MATCH_RECALCULATION_FROM_UP'')) {", "// This part of code must be called only to fix corrupted data due to the use of the old feature to round total instead of rounding lines."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_AUTO_UPDATE_OF_TMS_FIELDS', 'bool', NULL, 'core', 'Forces explicit PHP-side update of a record''s ''tms'' (timestamp modification) field on update() instead of relying on the database''s automatic ON UPDATE timestamp behavior.', 'Checked twice in core/class/commonobject.class.php (lines 10868 and 11178) inside the generic update() logic: `if (getDolGlobalString(''MAIN_DISABLE_AUTO_UPDATE_OF_TMS_FIELDS'') && array_key_exists(''tms'', $fieldvalues)) { $fieldvalues[''tms''] = $this->db->idate($now); }`, per the inline comment ''If we want the explicit update of tms fields instead of the deprecated update by database''.', 'When set, Dolibarr explicitly writes the current timestamp into the ''tms'' column from PHP on every update() call instead of depending on the database engine''s automatic timestamp-on-update trigger/default.', 'Truthy/falsy flag.', 1, 0, NULL, 1, '737718f858eaf7307e14a684707f96d5b8eb483e3597686c4f26084043d293da', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonobject.class.php:10868|check|if (getDolGlobalString(''MAIN_DISABLE_AUTO_UPDATE_OF_TMS_FIELDS'') && array_key_exists(''tms'', $fieldvalues)) {", "// If we want the explicit update of tms fields instead of the deprecated update by database"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_BLOCK_ADHERENT', 'bool', NULL, 'index.php', 'Hides the "foundation members (shift/expired)" block from the home page dashboard.', 'Checked in index.php:348 to gate the Adherent workboard block; also toggled via an on/off admin control in admin/ihm.php:655 (ajax_constantonoff).', 'Setting this constant removes the members shift/expired counters from the home dashboard for non-thirdparty-restricted users.', 'Boolean-like; truthy hides the block, empty/unset (default) shows it.', 0, 0, NULL, 1, '3b84e60820d26c0d41d8a776bcf9a76efc4f9bf7c0ca721980e206805c32f5a8', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:348|check|if (isModEnabled(''member'')  && !getDolGlobalString(''MAIN_DISABLE_BLOCK_ADHERENT'') && $user->hasRight(''adherent'', ''lire'') && !$user->socid) {", "admin/ihm.php:655|code|print ajax_constantonoff(\"MAIN_DISABLE_BLOCK_ADHERENT\", array(), $conf->entit..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_BLOCK_AGENDA', 'bool', NULL, 'index.php', 'Hides the "actions to do (late)" agenda block from the home page dashboard.', 'Checked in index.php:225 (dashboard section) to gate the ActionComm workboard block; also toggled via an on/off admin control in admin/ihm.php:613 (ajax_constantonoff).', 'Setting this constant removes the late-actions agenda block from the home dashboard for users who would otherwise see it.', 'Boolean-like; truthy hides the block, empty/unset (default) shows it.', 0, 0, NULL, 1, 'd1ecd1977f108763248109245c83d312a571fc288dec0446c35e13aeecef894f', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:225|check|if (isModEnabled(''agenda'') && !getDolGlobalString(''MAIN_DISABLE_BLOCK_AGENDA'') && $user->hasRight(''agenda'', ''myactions'', ''read'')) {", "admin/ihm.php:613|code|print ajax_constantonoff(\"MAIN_DISABLE_BLOCK_AGENDA\", array(), $conf->entity,..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_BLOCK_BANK', 'bool', NULL, 'index.php', 'Hides the bank-related home dashboard blocks (transactions to reconcile, cheques/direct-debit/credit-transfer to send).', 'Checked twice in index.php:319 and index.php:329 to gate the Account reconciliation block and the cheque/prelevement/credit-transfer block; also toggled via an on/off admin control in admin/ihm.php:649 (ajax_constantonoff).', 'Setting this constant removes both bank-related dashboard blocks (reconciliation counter and payments-to-send counters) for non-thirdparty-restricted users.', 'Boolean-like; truthy hides both blocks, empty/unset (default) shows them.', 0, 0, NULL, 1, 'f0f704c88aa891dff78671d5eb89973b09dae42e2b763bf5e8c361e28cf19de9', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:319|check|if (isModEnabled(''bank'')  && !getDolGlobalString(''MAIN_DISABLE_BLOCK_BANK'') && $user->hasRight(''banque'', ''lire'') && !$user->socid) {", "index.php:329|check|if (isModEnabled(''bank'') && !getDolGlobalString(''MAIN_DISABLE_BLOCK_BANK'') && $user->hasRight(''banque'', ''lire'') && !$user->socid) {", "admin/ihm.php:649|code|print ajax_constantonoff(\"MAIN_DISABLE_BLOCK_BANK\", array(), $conf->entity, 0..."]', 'high', NULL);
