INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_BLOCK_CUSTOMER', 'bool', NULL, 'index.php', 'Hides all customer-related dashboard blocks (proposals, orders, invoices) from the Dolibarr home page.', 'Checked in index.php:212, 231, and 271 to suppress the customer proposals, customer orders, and customer invoices workboard blocks respectively. No admin UI is present.', 'Setting this constant hides all three customer commercial blocks from the dashboard for all users.', 'Boolean flag: truthy = customer blocks hidden; 0 or unset = blocks displayed (when modules are enabled and user has rights).', 1, 0, NULL, 1, '17f65d64bcebb894611d5106a6f97b09cf19a06104880a481feda69b42751c27', 'v2', '2026-04-21T11:16:15+00:00', '["index.php:212|check|if (isModEnabled(''propal'') && !getDolGlobalString(''MAIN_DISABLE_BLOCK_CUSTOMER'') && $user->hasRight(''propal'', ''read'')) {", "index.php:231|check|if (isModEnabled(''order'')  && !getDolGlobalString(''MAIN_DISABLE_BLOCK_CUSTOMER'') && $user->hasRight(''commande'', ''lire'')) {", "index.php:271|check|if (isModEnabled(''invoice'') && !getDolGlobalString(''MAIN_DISABLE_BLOCK_CUSTOMER'') && $user->hasRight(''facture'', ''lire'')) {"]', 'medium', NULL);
