INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_BLOCK_HOLIDAY', 'bool', NULL, 'index.php', 'Hides the holiday-requests-to-approve block from the home dashboard.', 'Checked in the main dashboard builder at index.php:370 inside the condition that adds the holiday-approval board when the holiday module is enabled and the user has approve rights.', 'Setting it to true removes the ''holidays to approve'' indicator block from the dashboard for users who would otherwise see it.', 'Boolean-like: true/1 disables the block, unset/false shows it (inferred from negation in the if-condition).', 1, 0, NULL, 1, '45e4b986dabbd3855bc3e700420a1527bdb6793e015c2c8c9e636b931470b755', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:370|check|if (isModEnabled(''holiday'')  && !getDolGlobalString(''MAIN_DISABLE_BLOCK_HOLIDAY'') && $user->hasRight(''holiday'', ''approve'')) {"]', 'medium', NULL);
