INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_BLOCK_PROJECT', 'bool', NULL, 'index.php', 'Hides the "projects opened" and "tasks to do (late)" blocks from the home page dashboard.', 'Checked in index.php:232 and index.php:239 to gate the Project and Task workboard blocks; also toggled via an on/off admin control in admin/ihm.php:619 (ajax_constantonoff).', 'Setting this constant removes both the open-projects block and the late-tasks block from the home dashboard.', 'Boolean-like; truthy hides both blocks, empty/unset (default) shows them.', 0, 0, NULL, 1, '7ac426a2ea72ddfd99910156774ea98fe04792a1d235e977081a812cba0ce91b', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:232|check|if (isModEnabled(''project'') && !getDolGlobalString(''MAIN_DISABLE_BLOCK_PROJECT'') && $user->hasRight(''projet'', ''lire'')) {", "index.php:239|check|if (isModEnabled(''project'') && !getDolGlobalString(''MAIN_DISABLE_BLOCK_PROJECT'') && !getDolGlobalString(''PROJECT_HIDE_TASKS'') && $user->hasRight(''projet'', ''lire'')) {", "admin/ihm.php:619|code|print ajax_constantonoff(\"MAIN_DISABLE_BLOCK_PROJECT\", array(), $conf->entity..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_BLOCK_SUPPLIER', 'bool', NULL, 'index.php', 'Hides all supplier-related dashboard blocks (supplier proposals, orders, invoices) from the Dolibarr home page.', 'Checked in index.php:221, 245, and 278 to suppress the supplier proposals, supplier orders, and supplier invoices workboard blocks respectively. No admin UI is present.', 'Setting this constant hides all three supplier commercial blocks from the dashboard for all users.', 'Boolean flag: truthy = supplier blocks hidden; 0 or unset = blocks displayed (when modules are enabled and user has rights).', 1, 0, NULL, 1, '813fec27fd41ac0ec6292604fb445c0ba00be489c358ac2ef1c383ccab3fabae', 'v2', '2026-04-21T11:16:15+00:00', '["index.php:221|check|if (isModEnabled(''supplier_proposal'')  && !getDolGlobalString(''MAIN_DISABLE_BLOCK_SUPPLIER'') && $user->hasRight(''supplier_proposal'', ''lire'')) {", "index.php:245|check|if (isModEnabled(''supplier_order'')  && !getDolGlobalString(''MAIN_DISABLE_BLOCK_SUPPLIER'') && $user->hasRight(''fournisseur'', ''commande'', ''lire'')) {", "index.php:278|check|if (isModEnabled(''supplier_invoice'') && !getDolGlobalString(''MAIN_DISABLE_BLOCK_SUPPLIER'') && $user->hasRight(''fournisseur'', ''facture'', ''lire'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_BLOCK_TICKET', 'bool', NULL, 'index.php', 'Hides the "tickets open" block from the home page dashboard.', 'Checked in index.php:296 to gate the Ticket workboard block; also toggled via an on/off admin control in admin/ihm.php:643 (ajax_constantonoff).', 'Setting this constant removes the open-tickets block from the home dashboard for users who would otherwise see it.', 'Boolean-like; truthy hides the block, empty/unset (default) shows it.', 0, 0, NULL, 1, 'a56c03efb2e106e61ed74a9335a461e38b5e898e4f90eec8ce9b5751f4aaaacf', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:296|check|if (isModEnabled(''ticket'')  && !getDolGlobalString(''MAIN_DISABLE_BLOCK_TICKET'') && $user->hasRight(''ticket'', ''read'')) {", "admin/ihm.php:643|code|print ajax_constantonoff(\"MAIN_DISABLE_BLOCK_TICKET\", array(), $conf->entity,..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_CANVAS', 'bool', NULL, 'core', 'Disables Dolibarr''s legacy ''canvas'' object-template lookup mechanism to increase performance.', 'Checked in core/class/commonobject.class.php:5132 inside getCanvas(): `if (getDolGlobalString(''MAIN_DISABLE_CANVAS'')) { return 0; // To increase speed. Not enabled by default. }` — short-circuits before querying the DB for the record''s canvas field.', 'When set, getCanvas() always returns 0 immediately instead of querying the database for a custom canvas template, which speeds up object loading but disables the canvas customization feature for that object.', 'Truthy/falsy flag; per the inline comment, not enabled (falsy) by default.', 1, 0, NULL, 1, '97b255451e656cf79f54801bbf304c29c24baa957c84d580cf7855fdaf8831de', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonobject.class.php:5132|check|if (getDolGlobalString(''MAIN_DISABLE_CANVAS'')) {", "// To increase speed. Not enabled by default."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_CONTACTS_TAB', 'bool', NULL, 'core', 'Hides the Contacts tab on object cards (proposals, orders, invoices, contracts, tickets, etc.).', 'Checked across many card.php files (e.g. supplier_proposal/card.php:2204, fourn/commande/card.php:2765, contrat/card.php:1085, compta/facture/card.php:6550, ticket/card.php:1359, commande/card.php:2081, comm/propal/card.php:3503) and referenced in core/ajax/extraparams.php:23 as used by bloc_showhide.tpl.php.', 'When enabled, the Contacts tab is not shown on the affected object cards.', NULL, 1, 0, NULL, 1, 'c02579a5c4d99e7de04eee46c3ae739090bf3e6a14dd26b8b3e6159d3e387498', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_DISABLE_CONTACTS_TAB'')) {", "*\t\t\t\tCalled bu bloc_showhide.tpl.php, itself called when MAIN_DISABLE_CONTACTS_TAB or MAIN_DISABLE_NOTES_TAB are set"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_DEFAULT_FILTER_FOR_QUICK_SEARCH', 'bool', NULL, 'core', 'Controls whether a user''s saved default list filters are still applied when the user performs a quick/global search.', 'Checked in core/lib/functions.lib.php:1273 inside logic that applies $user->default_values[...][''filters''] to list output; the check only runs inside a branch handling the case where $_POST[''search_all''] or $_GET[''search_all''] is set (i.e. a quick-search request), gating whether the default filter value is still substituted in that case.', 'Enabling it stops the user''s configured default column filters from being re-applied when a quick search is performed, so quick search results are not additionally constrained by those saved defaults.', 'Boolean: truthy value skips applying default_values filters during a quick-search request (search_all set in $_POST/$_GET).', 1, 0, NULL, 1, 'b4fec9bc1025fe6a420029e78540c9caf6c21a2b95ac4fd3b2f6c59bd4856562', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:1273|check|if (!getDolGlobalString(''MAIN_DISABLE_DEFAULT_FILTER_FOR_QUICK_SEARCH'')) {", "// We made a search from quick search menu, do we still use default filter ?"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_DNS_GET_RECORD', 'bool', NULL, 'admin', 'Disables the DNS TXT record lookup (SPF/DMARC check) performed by the mail setup test page.', 'Checked at admin/mails.php:1124 in the testsetup action: `if (!empty($domaintotest) && function_exists(''dns_get_record'') && !getDolGlobalString(''MAIN_DISABLE_DNS_GET_RECORD''))`. Distinct from the related MAIN_DISABLE_DNS_GET_RECORD_FOR_IP_RESOLUTION constant used in core/lib/geturl.lib.php for a different purpose (resolving hostnames to IPs).', 'When truthy, the SPF/DMARC DNS TXT lookups in the mail configuration test are skipped entirely, so no DNS-based warnings/errors about SPF/DMARC records are shown.', 'Boolean: truthy disables the dns_get_record() call for SPF/DMARC checking on the mail setup test page.', 1, 0, 'admin/mails.php', 1, '108bbcd4eca31750ea74905423a7bac24415ddbb387106405a4c197aed9d1c91', 'v2', '2026-07-24T07:05:23+00:00', '["admin/mails.php:1124|check|if (!empty($domaintotest) && function_exists(''dns_get_record'') && !getDolGlobalString(''MAIN_DISABLE_DNS_GET_RECORD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_DNS_GET_RECORD_FOR_IP_RESOLUTION', 'bool', NULL, 'core', 'Disables use of PHP''s dns_get_record() when Dolibarr resolves a hostname to an IP address (e.g. for SSRF/URL validation).', 'core/lib/geturl.lib.php:409, in function resolveDns($hosttocheck): `if (function_exists(''dns_get_record'') && !getDolGlobalString(''MAIN_DISABLE_DNS_GET_RECORD_FOR_IP_RESOLUTION'')) { $records = dns_get_record($hosttocheck, DNS_A + DNS_AAAA); ... }`.', 'Setting it to a truthy value skips the dns_get_record()-based resolution path entirely, so resolveDns() falls through to whatever fallback method exists (e.g. gethostbyname); useful on hosts where dns_get_record is slow, blocked, or unreliable.', 'Truthy = skip dns_get_record() resolution; 0/unset = use dns_get_record() when available (default).', 1, 0, NULL, 1, '0a983caea77f9724406143473995fba7b98289dbf6648effc534bc2dd318317b', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/geturl.lib.php:409: if (function_exists(''dns_get_record'') && !getDolGlobalString(''MAIN_DISABLE_DNS_GET_RECORD_FOR_IP_RESOLUTION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_EDIT_PREDEF_PRICEHT', 'bool', NULL, 'core', 'Disables auto-filling/editing of the predefined (HT) unit price field when a predefined product price is selected on a document line.', 'Read in core/tpl/objectline_create.tpl.php:690 into a JS config object (jsConf.conf.MAIN_DISABLE_EDIT_PREDEF_PRICEHT), documented at line 768 as ''@property {boolean} conf.MAIN_DISABLE_EDIT_PREDEF_PRICEHT'', and checked at JS lines 1009 and 1555 to gate whether selecting a product/supplier price triggers auto-filling the HT price field.', 'Enabling it prevents the HT unit price field from being auto-populated/updated by JS when a predefined product price is chosen, forcing manual price entry.', 'Boolean, read via getDolGlobalInt cast to (bool); truthy disables the predefined HT price auto-fill/edit behavior in the line-creation JS.', 0, 0, NULL, 1, 'a214e1784758d63372eef1bebed5b0ff950b0c0a2774b0b5cf94fe4536e4170f', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:690|read|''MAIN_DISABLE_EDIT_PREDEF_PRICEHT'' => (bool) getDolGlobalInt(''MAIN_DISABLE_EDIT_PREDEF_PRICEHT''),", "core/tpl/objectline_create.tpl.php:768|* @property {boolean} conf.MAIN_DISABLE_EDIT_PREDEF_PRICEHT", "core/tpl/objectline_create.tpl.php:1009|if(!jsConf.conf.MAIN_DISABLE_EDIT_PREDEF_PRICEHT && !jsConf.docObject.senderissupplier) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_EDIT_PREDEF_PRICETTC', 'bool', NULL, 'core', 'Disables auto-filling/editing of the predefined TTC (tax-inclusive) unit price field when a predefined product price is selected on a document line.', 'Read in core/tpl/objectline_create.tpl.php:691 into the JS config object (jsConf.conf.MAIN_DISABLE_EDIT_PREDEF_PRICETTC) and checked at JS line 1565 to gate whether selecting a product price triggers auto-filling the TTC price field, mirroring MAIN_DISABLE_EDIT_PREDEF_PRICEHT for the HT field.', 'Enabling it prevents the TTC unit price field from being auto-populated/updated by JS when a predefined product price is chosen, forcing manual price entry.', 'Boolean, read via getDolGlobalInt cast to (bool); truthy disables the predefined TTC price auto-fill/edit behavior in the line-creation JS.', 0, 0, NULL, 1, 'a265f223c783b238f3f1d7c6a305a93e80d285b471de950857565e9f1424898f', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:691|read|''MAIN_DISABLE_EDIT_PREDEF_PRICETTC'' => (bool) getDolGlobalInt(''MAIN_DISABLE_EDIT_PREDEF_PRICETTC''),", "core/tpl/objectline_create.tpl.php:1565|if (!jsConf.conf.MAIN_DISABLE_EDIT_PREDEF_PRICETTC) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_EXTERNALMODULES_COMMUNITY', 'bool', NULL, 'admin', 'Hides the community-modules source status/cache information block on the admin Modules page even when the community modules source is enabled.', 'Checked in admin/modules.php:1401 together with MAIN_ENABLE_EXTERNALMODULES_COMMUNITY; when this constant is falsy and the community source is enabled, a status block (cache file info, GitHub errors) is printed for the ''Community Modules'' source row.', 'Setting it suppresses the community-modules cache/status details block on the admin Modules page, independent of whether the community modules source itself is enabled via MAIN_ENABLE_EXTERNALMODULES_COMMUNITY.', 'Boolean-like: truthy value hides the community modules source status block.', 0, 0, 'admin/modules.php', 1, '6eadc079562d4120d7e244eb846b48cb035a92ae14f6a6b26c7888689bd681c7', 'v2', '2026-07-24T07:05:23+00:00', '["admin/modules.php:1401: if (!getDolGlobalString(''MAIN_DISABLE_EXTERNALMODULES_COMMUNITY'') && getDolGlobalInt(''MAIN_ENABLE_EXTERNALMODULES_COMMUNITY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_EXTERNALMODULES_DOLISTORE', 'bool', NULL, 'admin', 'Hides the DoliStore marketplace source status block on the admin Modules page even when the DoliStore source is enabled.', 'Checked in admin/modules.php:1424 together with MAIN_ENABLE_EXTERNALMODULES_DOLISTORE; when this constant is falsy and the DoliStore source is enabled, a status block (API status, errors) is printed for the ''DoliStore'' source row.', 'Setting it suppresses the DoliStore marketplace status/error details block on the admin Modules page, independent of whether MAIN_ENABLE_EXTERNALMODULES_DOLISTORE itself is enabled.', 'Boolean-like: truthy value hides the DoliStore source status block.', 0, 0, 'admin/modules.php', 1, '516accbc9e4800b0f994a8ae936e05b83a441542550f093cbb7739474da02deb', 'v2', '2026-07-24T07:05:23+00:00', '["admin/modules.php:1424: if (!getDolGlobalString(''MAIN_DISABLE_EXTERNALMODULES_DOLISTORE'') && getDolGlobalInt(''MAIN_ENABLE_EXTERNALMODULES_DOLISTORE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_EXTRAFIELDS_CHECK_FOR_UPDATE', 'bool', NULL, 'core', 'Disables validation checks (minimum length, reserved keywords) when creating/updating an extrafield attribute code.', 'In core/actions_extrafields.inc.php:358 and :368, this constant, when set, bypasses the check that the attrname is at least 3 characters long and the check against a list of reserved keywords.', 'Setting it allows saving extrafield attribute codes shorter than 3 characters or matching reserved keywords, which normally trigger ErrorValueLength/ErrorReservedKeyword errors.', 'boolean: 1/true disables both the length and reserved-keyword checks for extrafield attribute codes; unset/0 = checks enforced.', 1, 0, NULL, 1, 'c8935777c0bc0ccf49f407776ed5a7ff962e10db4b651689ec994962ea5554dc', 'v2', '2026-07-24T07:05:23+00:00', '["core/actions_extrafields.inc.php:358: if (strlen(GETPOST(''attrname'', ''aZ09'')) < 3 && !getDolGlobalString(''MAIN_DISABLE_EXTRAFIELDS_CHECK_FOR_UPDATE'')) {", "core/actions_extrafields.inc.php:368: if (in_array(strtoupper(GETPOST(''attrname'', ''aZ09'')), $listofreservedwords) && !getDolGlobalString(''MAIN_DISABLE_EXTRAFIELDS_CHECK_FOR_UPDATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_FORCE_SAVEAS', 'bool', NULL, 'core', 'Controls whether file downloads are forced as Save-As (Content-Disposition: attachment) or can be displayed inline.', 'Checked across 10 occurrences in core/class/html.formfile.class.php:996, :1243, :1541, :2160, webportal/controllers/document.controller.class.php:137, ecm/class/ecmfiles.class.php:1069, and others. When value equals 2, inline display is forced; any other truthy value disables the forced Save-As header.', 'Setting to 2 allows documents to open inline in the browser; any truthy value disables the forced download prompt; leaving unset forces Save-As behavior.', '0/empty = force Save-As download; 1 = disable forced Save-As; 2 = force inline display', 1, 0, NULL, 1, 'cc54bd35f48f6e957cefa191542a43936f52fe3d9bed5d20665fa58e6d387a54', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.formfile.class.php:1243|check|if (getDolGlobalInt(''MAIN_DISABLE_FORCE_SAVEAS'') == 2) {", "webportal/controllers/document.controller.class.php:137|check|if (getDolGlobalString(''MAIN_DISABLE_FORCE_SAVEAS'')) {", "core/modules/member/doc/pdf_standard_member.class.php:501|check|if (getDolGlobalString(''MAIN_DISABLE_FORCE_SAVEAS'')) {", "ecm/class/ecmfiles.class.php:1069|check|if (getDolGlobalInt(''MAIN_DISABLE_FORCE_SAVEAS'') == 2) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_FORCE_SAVEAS_WEBSITE', 'bool', NULL, 'core', 'When enabled, disables the forced Save-As behaviour in website container wrappers, allowing normal page rendering instead.', 'Checked in multiple website template wrapper files (install/doctemplates/websites/*/containers/wrapper.php and website/samples/wrapper.php) to determine whether to bypass the forced save-as download behaviour. No admin UI write path is present in the payload.', 'Enabling this constant suppresses the forced file download (Save-As) triggered by website container wrappers, allowing the page to render normally in the browser.', 'Truthy value to disable forced Save-As; unset or 0 to keep default Save-As behaviour.', 1, 0, NULL, 1, '908136201220d26e37478059dc7fb35f7ff8e926014ac9c15d7980249df2f3ea', 'v2', '2026-04-21T11:16:15+00:00', '["install/doctemplates/websites/website_template-homesubmenu_dev/containers/wrapper.php:68|check|if (getDolGlobalString(''MAIN_DISABLE_FORCE_SAVEAS_WEBSITE'')) {", "website/samples/wrapper.php:121|check|if (getDolGlobalString(''MAIN_DISABLE_FORCE_SAVEAS_WEBSITE'')) {", "install/doctemplates/websites/website_template-association_exp/containers/wrapper.php:116|check|if (getDolGlobalString(''MAIN_DISABLE_FORCE_SAVEAS_WEBSITE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_FPDI', 'bool', NULL, 'core', 'When enabled, disables the FPDI library used to embed PDF background images into generated PDF documents.', 'Checked in 11 locations across multiple PDF generation modules (stock, stocktransfer, expedition, supplier_order, accountancy, etc.) always in the pattern: if (!MAIN_DISABLE_FPDI && MAIN_ADD_PDF_BACKGROUND). When this constant is set, the background embedding block is skipped.', 'Enabling prevents PDF background images from being applied to any generated documents, which may be needed if FPDI is unavailable or causes errors. Disabling allows background images when MAIN_ADD_PDF_BACKGROUND is also set.', 'Truthy = disable FPDI/PDF background embedding; empty/unset = FPDI enabled (backgrounds applied when MAIN_ADD_PDF_BACKGROUND is set).', 1, 0, NULL, 1, 'a15a5c3c34c21af47d7523311fb8dc7a85a772ee2144cf1194f9da97d8010e9f', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/stock/doc/pdf_standard_stock.modules.php:236|check|if (!getDolGlobalString(''MAIN_DISABLE_FPDI'') && getDolGlobalString(''MAIN_ADD_PDF_BACKGROUND'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:322|check|if (!getDolGlobalString(''MAIN_DISABLE_FPDI'') && getDolGlobalString(''MAIN_ADD_PDF_BACKGROUND'')) {", "core/modules/expedition/doc/pdf_rouget.modules.php:306|check|if (!getDolGlobalString(''MAIN_DISABLE_FPDI'') && getDolGlobalString(''MAIN_ADD_PDF_BACKGROUND'')) {", "core/modules/supplier_order/doc/pdf_cornas.modules.php:294|check|if (!getDolGlobalString(''MAIN_DISABLE_FPDI'') && getDolGlobalString(''MAIN_ADD_PDF_BACKGROUND'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_FREE_LINES', 'bool', NULL, 'compta', 'Prevents adding free-text lines (without a linked product) to documents such as invoices, orders, and proposals.', 'Checked in reception/card.php:933, compta/facture/card.php:2496, commande/card.php:991, comm/propal/card.php:1263, expedition/card.php:1196, contrat/card.php:506, compta/facture/card-rec.php:556, and core/tpl/objectline_create.tpl.php:212. When set and $idprod <= 0, the free line is rejected. No admin UI write path exists.', 'Enabling this constant blocks entry of any document line not tied to a product reference; this enforces product-only line entry across invoices, orders, proposals, contracts, shipments, and receptions.', 'Truthy string/bool=free lines blocked, empty/0=free lines allowed', 1, 0, NULL, 1, '2d00abd58bc9d9bade03320913a58ad2fef04d26e4fd2defbd032597fc6c0069', 'v2', '2026-04-21T11:16:15+00:00', '["reception/card.php:933|check|if (getDolGlobalString(''MAIN_DISABLE_FREE_LINES'') && $idprod <= 0) {", "compta/facture/card.php:2496|check|if (getDolGlobalString(''MAIN_DISABLE_FREE_LINES'') && $idprod <= 0) {", "core/tpl/objectline_create.tpl.php:212|check|if (!getDolGlobalString(''MAIN_DISABLE_FREE_LINES'')) {", "commande/card.php:991|check|if (getDolGlobalString(''MAIN_DISABLE_FREE_LINES'') && $idprod <= 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_FULL_SCANLIST', 'bool', NULL, 'product', 'Disables the ''full scan'' mode of list pages (loading of the complete unpaginated dataset) across many admin and module list screens.', 'Checked in over a hundred files including admin/emailcollector_list.php:315, hrm/admin/admin_establishment.php:115, api/admin/token_list.php:182, and accountancy/admin listing pages, all guarded by getDolGlobalInt(''MAIN_DISABLE_FULL_SCANLIST'').', 'When enabled, the full-scan listing behavior is disabled on the many list pages that check this constant.', NULL, 1, 0, 'admin/emailcollector_list.php|hrm/admin/admin_establishment.php|api/admin/token_list.php|accountancy/admin/template/list.php|accountancy/admin/fiscalyear.php|accountancy/admin/subaccount.php|accountancy/admin/productaccount.php|accountancy/admin/categories.php|accountancy/admin/account.php|admin/mails_senderprofile_list.php|admin/dict.php|admin/tools/listevents.php', 1, '60d8b134ba596e5428513c8b1cfc65f2f1e8babe0ee40fd81b6f2a0be7433916', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalInt(''MAIN_DISABLE_FULL_SCANLIST'')) {", "/*if (empty($conf->global->MAIN_DISABLE_FULL_SCANLIST))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_GLOBAL_BOXSTATS', 'bool', NULL, 'theme', 'When enabled, suppresses the global statistics box from appearing on the opened dashboard.', 'Checked in theme/eldy/info-box.inc.php:254, theme/md/info-box.inc.php:400, and core/boxes/box_dolibarr_state_board.php:69. The global stats box is only rendered when this constant is falsy AND MAIN_INCLUDE_GLOBAL_STATS_IN_OPENED_DASHBOARD is set. No admin UI write path is present in the payload.', 'Enabling this constant hides the global statistics dashboard box from all users. Leaving it unset allows the box to appear when MAIN_INCLUDE_GLOBAL_STATS_IN_OPENED_DASHBOARD is also set.', 'Truthy value to disable; unset or 0 to allow global stats box.', 1, 0, NULL, 1, '38a9959d3a72993b7ebab4506aed23c27ac98cdd4affe020cf76c767e2c55da8', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/info-box.inc.php:254|check|<?php if (!getDolGlobalString(''MAIN_DISABLE_GLOBAL_BOXSTATS'') && getDolGlobalString(''MAIN_INCLUDE_GLOBAL_STATS_IN_OPENED_DASHBOARD'')) { ?>", "theme/md/info-box.inc.php:400|check|<?php if (!getDolGlobalString(''MAIN_DISABLE_GLOBAL_BOXSTATS'') && getDolGlobalString(''MAIN_INCLUDE_GLOBAL_STATS_IN_OPENED_DASHBOARD'')) { ?>", "core/boxes/box_dolibarr_state_board.php:69|check|if (empty($user->socid) && !getDolGlobalString(''MAIN_DISABLE_GLOBAL_BOXSTATS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_GLOBAL_WORKBOARD', 'bool', NULL, 'admin', 'Hides the global workboard (task/todo dashboard block) from the Dolibarr home page.', 'Toggled via an on/off admin control in admin/ihm.php:600 (ajax_constantonoff) under the ''Display'' setup screen, and checked in admin/ihm.php:604 and index.php:215 to decide whether to render the workboard on the home page.', 'Enabling it removes the global workboard block from the main index page for all users, regardless of MAIN_OPTIMIZEFORTEXTBROWSER.', 'Boolean: 0/unset = workboard shown (default); 1 = workboard hidden.', 0, 0, 'admin/ihm.php', 1, 'd9c39ee933cf42a24c73bb870c6bd93de11fc284a300ddc100e6e97ae79d42ab', 'v2', '2026-07-24T07:05:23+00:00', '["admin/ihm.php:600: print ajax_constantonoff(\"MAIN_DISABLE_GLOBAL_WORKBOARD\", array(), $conf->entity, 0, 0, 1, 0, 0, 0, ''_red'', ''dashboard'');", "index.php:215: if (!getDolGlobalString(''MAIN_DISABLE_GLOBAL_WORKBOARD'') && getDolGlobalInt(''MAIN_OPTIMIZEFORTEXTBROWSER'') < 2) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_JAVASCRIPT', 'bool', NULL, 'comm', 'Disables JavaScript/AJAX features globally across the Dolibarr interface.', 'Read in core/class/conf.class.php:946 to set the global use_javascript_ajax flag. Configurable via admin/ihm.php (write line 279, though currently commented out). Also checked in comm/remx.php to gate discount-split features.', 'Setting this to a truthy value disables all JavaScript and AJAX-dependent UI components. This affects dynamic product selectors, inline editing, and other interactive elements.', '0 or not set = JavaScript enabled; 1 = JavaScript/AJAX disabled', 0, 0, 'admin/ihm.php', 1, 'e3bdfb69bc2d0df28b7941b5afb15fc3ea0b37833ab497cc940466e5bee4d09c', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/conf.class.php:946|read|$this->use_javascript_ajax = (int) !getDolGlobalInt(''MAIN_DISABLE_JAVASCRIPT'');", "admin/ihm.php:279|write|//dolibarr_set_const($db, \"MAIN_DISABLE_JAVASCRIPT\", GETPOST(\"MAIN_DISABLE_JAVASCRIPT\", ''aZ09''), ''chaine'', 0, '''', $conf->entity);", "comm/remx.php:658|check|if (getDolGlobalInt(''DISCOUNT_SPLIT_MORE_THAN_TWO_PARTS'') && !getDolGlobalInt(''MAIN_DISABLE_JAVASCRIPT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_JQUERY_JNOTIFY', 'bool', NULL, 'core', 'Disables the jQuery jNotify plugin used for in-page notification pop-ups.', 'Checked in main.inc.php:1992, core/js/lib_head.js.php:1511, and core/lib/functions.lib.php:11492 and :11517 to suppress jNotify loading and usage.', 'Enabling this prevents jNotify pop-up notifications from being displayed; messages fall back to static display instead.', '0 or unset = jNotify enabled; 1 (truthy) = jNotify disabled', 1, 0, NULL, 1, '0036cd30b313753f25322363e2ede9fe47b4e75e35c907ee8177cbe0b920975f', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1992|check|if (!getDolGlobalString(''MAIN_DISABLE_JQUERY_JNOTIFY'') && !defined(''DISABLE_JQUERY_JNOTIFY'')) {", "core/js/lib_head.js.php:1511|check|if (!getDolGlobalString(''MAIN_DISABLE_JQUERY_JNOTIFY'') && !defined(''DISABLE_JQUERY_JNOTIFY'')) {", "core/lib/functions.lib.php:11517|check|if (!empty($conf->use_javascript_ajax) && !getDolGlobalString(''MAIN_DISABLE_JQUERY_JNOTIFY'') && empty($keepembedded)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_LDAP_TAB', 'bool', NULL, 'core', 'Hides the LDAP tab on user, group, member, and contact detail pages for non-admin users.', 'Checked in core/lib/usergroups.lib.php:57 and :264, core/lib/member.lib.php:48 and :198, and core/lib/contact.lib.php:47 with the pattern: !getDolGlobalString(''MAIN_DISABLE_LDAP_TAB'') || !empty($user->admin). When set, the LDAP tab is suppressed unless the user is an admin.', 'Setting this constant removes the LDAP tab from all relevant entity pages for non-admin users. Admin users always retain the LDAP tab regardless of this setting.', 'Non-empty string = LDAP tab hidden for non-admins. Empty/unset = LDAP tab visible for all.', 1, 0, NULL, 1, '28c778c4b456f97c682d853ad08c05170f3fad2b09034bb51a33426af3544fe1', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/usergroups.lib.php:57|read|&& (!getDolGlobalString(''MAIN_DISABLE_LDAP_TAB'') || !empty($user->admin))) {", "core/lib/usergroups.lib.php:264|read|&& (!getDolGlobalString(''MAIN_DISABLE_LDAP_TAB'') || !empty($user->admin))) {", "core/lib/member.lib.php:48|read|&& (!getDolGlobalString(''MAIN_DISABLE_LDAP_TAB'') || !empty($user->admin))) {", "core/lib/contact.lib.php:47|read|&& (!getDolGlobalString(''MAIN_DISABLE_LDAP_TAB'') || !empty($user->admin))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_METEO', 'bool', NULL, 'admin', 'Controls whether and how the weather-indicator widget is shown on the Dolibarr home dashboard.', 'Read in index.php:182 to set $showweather (0=hidden, 1=shown, 2=shown but hidden on mobile). Selectable via admin/delais.php using a dropdown with labelled options. The value 1 fully disables the widget; value 2 hides it only on small screens.', 'Changing this value shows or hides the weather/health indicator on the dashboard; value 2 keeps it visible on desktop only.', 'Integer: 0 or unset = widget shown; 1 = widget disabled; 2 = widget shown but hidden on smartphones.', 0, 0, 'admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php', 1, 'df59054361ae0da682f3939d459f6d6c41e7f3b55ee1a6cb28be0052f5fb8d55', 'v2', '2026-04-21T11:16:15+00:00', '["index.php:182|read|$showweather = (!getDolGlobalString(''MAIN_DISABLE_METEO'') || getDolGlobalInt(''MAIN_DISABLE_METEO'') == 2) ? 1 : 0;", "index.php:702|read|$appendClass = (getDolGlobalInt(''MAIN_DISABLE_METEO'') == 2 ? '' hideonsmartphone'' : '''');", "admin/delais.php:315|check|if (!getDolGlobalString(''MAIN_DISABLE_METEO'') || getDolGlobalInt(''MAIN_DISABLE_METEO'') != 1) {", "admin/delais.php:202|write|dolibarr_set_const($db, \"MAIN_DISABLE_METEO\", GETPOST(\"MAIN_DISABLE_METEO\"), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_MULTIPLE_FILEUPLOAD', 'bool', NULL, 'core', 'Disables multiple-file selection on file upload inputs.', 'Checked at core/upload_page.php:328 and core/class/html.formfile.class.php:247; when set, the file input renders as a single-file selector (name=''userfile'') instead of a multi-file selector (name=''userfile[]'' with the ''multiple'' attribute). No admin UI is provided.', 'Enabling this constant restricts file upload inputs to one file at a time, preventing bulk uploads.', 'Non-empty/truthy = multiple file upload disabled; empty/unset = multiple file upload allowed.', 1, 0, NULL, 1, '480ef092fd1bf2c1897b03c521af991df0d20bfa30767b0d3de2922cf2c9afcf', 'v2', '2026-04-21T11:16:15+00:00', '["core/upload_page.php:328|read|$out .= ((getDolGlobalString(''MAIN_DISABLE_MULTIPLE_FILEUPLOAD'') || $disablemulti) ? '' name=\"userfile\"'' : '' name=\"userfile[]\" multiple'');", "core/class/html.formfile.class.php:247|read|$out .= ((getDolGlobalString(''MAIN_DISABLE_MULTIPLE_FILEUPLOAD'') || $disablemulti) ? '' name=\"userfile\"'' : '' name=\"userfile[]\" multiple'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_NEW_OPENED_DASH_BOARD', 'bool', NULL, 'index.php', 'Disables the newer ''open items'' consolidated dashboard section on the home page.', 'Checked at index.php:576 where the code scans $groupElement[''stats''] to build the consolidated ''open objects'' dashboard section only when this constant is not set.', 'Setting it to true skips the grouping/consolidation logic for the open-items dashboard, reverting to the older per-module board layout.', 'Boolean-like: true/1 disables the new consolidated board (inferred from negation in the if-condition).', 1, 0, NULL, 1, 'f2458847b1d837194b1cbc7c3d844282898b81d4f1fea10f505eab6ca446233c', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:576|check|if (!getDolGlobalString(''MAIN_DISABLE_NEW_OPENED_DASH_BOARD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_NOTES_TAB', 'bool', NULL, 'core', 'Hides the Notes tab on object cards (proposals, invoices, orders, products, contracts, etc.).', 'Checked across many card.php files (e.g. supplier_proposal/card.php:2210, fourn/facture/card.php:4134, fourn/commande/card.php:2771, product/card.php:2469/3067, fichinter/card.php:1580, contrat/card.php:1685, compta/facture/card.php:6556) and referenced in core/ajax/extraparams.php:23.', 'When enabled, the Notes tab is not shown on the affected object cards.', NULL, 1, 0, NULL, 1, '6e8fb6dff803392501566cb32b8bb855d527b4deee142220c5ff93295911011b', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_DISABLE_NOTES_TAB'')) {", "*\t\t\t\tCalled bu bloc_showhide.tpl.php, itself called when MAIN_DISABLE_CONTACTS_TAB or MAIN_DISABLE_NOTES_TAB are set"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_OTHER_LINK', 'bool', NULL, 'fourn', 'Disables display of the ''Link to other objects'' block on supplier proposal/invoice cards and related tabs (messaging, info, note, document, agenda, contact).', 'Checked in supplier_proposal/card.php:1943 and many fourn/facture/*.php files (messaging.php:181, info.php:95, card.php:3377, note.php:124, document.php:128, agenda.php:174, contact.php:164), each guarded together with a check on $object->thirdparty->id > 0.', 'When enabled, the linked-objects/other-link section is hidden on these supplier-related pages.', NULL, 1, 0, NULL, 1, '5e8ce820165f5776d6eeb91e8f8198bbf50306ddddd9af67ab0c948959e7c2a1', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''MAIN_DISABLE_OTHER_LINK'') && $object->thirdparty->id > 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_PDF_AUTOUPDATE', 'bool', NULL, 'fourn', 'Disables automatic regeneration of the PDF document when an object (invoice, order, reception, supplier proposal, etc.) is updated.', 'Checked in fourn/class/paiementfourn.class.php:419, reception/card.php (lines 270, 539, 587, 819, 910, 1103), and supplier_proposal/class/supplier_proposal.class.php:1756; also referenced (commented out) in compta/facture/card-rec.php:776/1106 and adherents/class/adherent.class.php:2164-2165.', 'When enabled, PDF documents are not automatically regenerated on object update, per the comment ''Generate PDF (whatever is option MAIN_DISABLE_PDF_AUTOUPDATE)''.', NULL, 1, 0, NULL, 1, '1af4f0bd8d6bb090049ea40e27631ffc0dc6edd79fb810109ce6c42075237c4f', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''MAIN_DISABLE_PDF_AUTOUPDATE'')) {", "// Generate PDF (whatever is option MAIN_DISABLE_PDF_AUTOUPDATE) so we can include it into email"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_PDF_COMPRESSION', 'bool', NULL, 'core', 'Disables output compression when generating PDF files.', 'Checked across 51 occurrences in PDF generation modules and core/ajax/onlineSign.php; when set, PDF output is generated without compression.', 'Disabling compression increases PDF file sizes but can aid debugging or compatibility with certain PDF processors.', '0 or unset = PDF compression enabled; 1 = PDF compression disabled.', 1, 0, NULL, 1, '52f53e140706e763abfecd27e0fd52205d0592fa68801027aa648ccfd94853dd', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/rapport/pdf_paiement.class.php:394|check|if (getDolGlobalString(''MAIN_DISABLE_PDF_COMPRESSION'')) {", "core/ajax/onlineSign.php:178|check|if (getDolGlobalString(''MAIN_DISABLE_PDF_COMPRESSION'')) {", "modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:341|check|if (getDolGlobalString(''MAIN_DISABLE_PDF_COMPRESSION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_PDF_THUMBS', 'bool', NULL, 'expensereport', 'Disables PDF thumbnail generation via Imagick, useful when the thumbnail generation causes errors.', 'Checked with negation in three files: core/lib/functions.lib.php:3548, expensereport/tpl/expensereport_linktofile.tpl.php:97, and expensereport/card.php:2324. Each occurrence includes the inline comment about Imagick trouble.', 'Setting this constant prevents PDF thumbnail creation across core file handling and expense reports. Without it, thumbnails are generated using Imagick when available.', 'If you experience trouble with pdf thumb generation and imagick, you can disable here. Non-empty = thumbnails disabled; absent/empty = thumbnails enabled.', 1, 0, NULL, 1, '244c5363c07239edf2afc07992cc81e289babb2aec85759813e55aff7db95c10', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:3548|check|if (!getDolGlobalString(''MAIN_DISABLE_PDF_THUMBS'')) {\t\t// If you experience trouble with pdf thumb generation and imagick, you can disable here.", "expensereport/tpl/expensereport_linktofile.tpl.php:97|check|if (!getDolGlobalString(''MAIN_DISABLE_PDF_THUMBS'')) {\t\t// If you experience trouble with pdf thumb generation and imagick, you can disable here.", "expensereport/card.php:2324|check|if (!getDolGlobalString(''MAIN_DISABLE_PDF_THUMBS'')) {\t\t// If you experience trouble with pdf thumb generation and imagick, you can disable here."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_PROPAGATE_NOTES_FROM_ORIGIN', 'bool', NULL, 'compta', 'Disables automatic propagation of notes from an origin document when creating a new document.', 'Checked with negation in 4 locations: compta/facture/class/facture.class.php:1505, :1642, :1771, and commande/class/commande.class.php:1480. Notes are propagated when this constant is not set; setting it prevents that behaviour. No admin UI is present.', 'When set, notes from the origin document are not copied to the new document; when unset, notes are propagated automatically.', '0 or unset = notes are propagated from origin; truthy value = notes are not propagated.', 1, 0, NULL, 1, '6e81405c80e43e2d89a6941a6aa2e7a88f1265879d3e0a9302d74d4c9ea3b189', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/class/facture.class.php:1505|check|if (!getDolGlobalString(''MAIN_DISABLE_PROPAGATE_NOTES_FROM_ORIGIN'')) {", "compta/facture/class/facture.class.php:1642|check|if (!getDolGlobalString(''MAIN_DISABLE_PROPAGATE_NOTES_FROM_ORIGIN'')) {", "compta/facture/class/facture.class.php:1771|check|if (!getDolGlobalString(''MAIN_DISABLE_PROPAGATE_NOTES_FROM_ORIGIN'')) {", "commande/class/commande.class.php:1480|check|if (!getDolGlobalString(''MAIN_DISABLE_PROPAGATE_NOTES_FROM_ORIGIN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_RECURRING_EVENTS', 'bool', NULL, 'comm', 'Disables the recurring/repeat event feature in the agenda module.', 'When set to a non-zero integer, the $userepeatevent flag is forced to 0 in comm/action/card.php at lines 584 and 1533, hiding the recurring event UI. The same logic appears commented out at line 2197.', 'Enabling this constant removes the repeat-event UI from action/event cards, preventing users from creating recurring agenda entries.', '0 or unset = recurring events enabled; non-zero = recurring events disabled.', 1, 0, NULL, 1, '1bae22f30a153ce04655ac06dbf1737e26bf4878910cf47f2432336eacc34949', 'v2', '2026-04-21T13:29:58+00:00', '["comm/action/card.php:584|read|$userepeatevent = (getDolGlobalInt(''MAIN_DISABLE_RECURRING_EVENTS'') ? 0 : 1);", "comm/action/card.php:1533|read|$userepeatevent = (getDolGlobalInt(''MAIN_DISABLE_RECURRING_EVENTS'') ? 0 : 1);", "comm/action/card.php:2197  // $userepeatevent = (getDolGlobalInt(''MAIN_DISABLE_RECURRING_EVENTS'') ? 0 : 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_SELECT2_FOCUS_PROTECTION', 'bool', NULL, 'core', 'Disables a JS workaround for a select2/jQuery 3.6.4 nested-focus bug requiring a double click on ajax comboboxes.', 'In core/js/lib_head.js.php:1675, a comment explains this is a ''Hacky fix for a bug in select2 with jQuery 3.6.4''s new nested-focus protection'' needed to avoid clicking twice on an ajax combo; the fix is applied unless the constant is set or DISABLE_SELECT2_FOCUS_PROTECTION is defined.', 'Setting it to true removes the JS workaround, so the original select2/jQuery focus bug (requiring a second click on ajax-populated select2 dropdowns) may reappear; it exists as an escape hatch in case the fix itself causes issues.', 'boolean: 1/true disables the focus-protection JS fix; unset/0 = fix applied (default).', 1, 0, NULL, 1, '6c04ea1a9a60432486d9c0391e2ac2e9d278c68b5980f87f7792202f92c25289', 'v2', '2026-07-24T07:05:23+00:00', '["core/js/lib_head.js.php:1667-1673: /**\\n * Hacky fix for a bug in select2 with jQuery 3.6.4''s new nested-focus \"protection\"\\n * This fix the need to click a second time when clicking into a combo with ajax", "core/js/lib_head.js.php:1675: if (!getDolGlobalString(''MAIN_DISABLE_SELECT2_FOCUS_PROTECTION'') && !defined(''DISABLE_SELECT2_FOCUS_PROTECTION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_SUGGEST_REF_AS_PREFIX', 'bool', NULL, 'core', 'Disables suggesting the object''s reference as a filename prefix when uploading a file/document.', 'Checked in core/tpl/document_actions_post_headers.tpl.php:133/135, expensereport/tpl/expensereport_addfile.tpl.php:49, and core/class/fileupload.class.php:95, with the comment at fileupload.class.php:94/453 stating ''Add object reference as file name prefix if const MAIN_DISABLE_SUGGEST_REF_AS_PREFIX is not enabled''.', 'When enabled, uploaded file names no longer get the object reference automatically prefixed.', NULL, 1, 0, NULL, 1, 'c8ce6ca17b1bc3ffd787c27e7de164a187e74cf2e064eb2a2b83158c4dd5f2d0', 'v2', '2026-07-24T06:41:12+00:00', '["// Add object reference as file name prefix if const MAIN_DISABLE_SUGGEST_REF_AS_PREFIX is not enabled", "if (!getDolGlobalString(''MAIN_DISABLE_SUGGEST_REF_AS_PREFIX'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_TCPDI', 'bool', NULL, 'core', 'Disables use of the TCPDI library (TCPDF wrapper enabling PDF merge/import features) when generating PDFs.', 'Checked twice in core/lib/pdf.lib.php: at line 181 to decide whether to require_once TCPDI_PATH.''tcpdi.php'', and at line 192 to decide whether to instantiate `new TCPDI(...)` versus falling back to plain `new TCPDF(...)`.', 'Enabling it forces Dolibarr to use plain TCPDF instead of TCPDI for PDF generation; per the inline code comment this will break PDF merge features that depend on TCPDI.', 'Boolean-like: truthy disables TCPDI (falls back to TCPDF, breaking merge features); falsy/unset (default) uses TCPDI when available.', 1, 0, NULL, 1, 'ad7b9aeb9f6aa1b1efc7aa0be3d9ef895635f9a7a7ead17c818513e2c2a21c82', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:181|check|if (!getDolGlobalString(''MAIN_DISABLE_TCPDI'')) { require_once TCPDI_PATH.''tcpdi.php''; }", "// We need to instantiate tcpdi object (instead of tcpdf) to use merging features. But we can disable it (this will break all merge features).", "core/lib/pdf.lib.php:192|check|if (!getDolGlobalString(''MAIN_DISABLE_TCPDI'') && class_exists(''TCPDI'')) { $pdf = new TCPDI(...); } else { $pdf = new TCPDF(...); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_TRUNC', 'bool', NULL, 'core', 'Disables all string truncation performed by Dolibarr''s truncation helper when set to 1.', 'The comment in core/lib/functions.lib.php:5565 states ''MAIN_DISABLE_TRUNC=1 can disable all truncings''. The truncation function at line 5579 skips truncation entirely when this constant is truthy.', 'Setting this to 1 causes all truncated strings (labels, descriptions, etc.) to be rendered at full length, which may break fixed-width UI layouts.', '1 = disable all truncation; 0 or empty = normal truncation applies', 1, 0, NULL, 1, '67c34e5250c0b1c6c33ea9c64f27e8018f500a3dbb64d3b4a6ab88519e4215d6', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:5565  *  MAIN_DISABLE_TRUNC=1 can disable all truncings", "core/lib/functions.lib.php:5579|check|if (empty($size) || getDolGlobalString(''MAIN_DISABLE_TRUNC'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISABLE_WRAPPING_ON_COLUMN_TITLE', 'bool', NULL, 'core', 'Disables the tooltip title attribute added to column header cells to prevent text wrapping hints.', 'Used in the column-header rendering function at core/lib/functions.lib.php:7209 and 7223. When set, the code omits the title attribute from column headers. Commented-out legacy code at lines 7222 and 7250 shows the same pattern was retained across refactors.', 'Enabling this constant removes column-title tooltips from list views, which suppresses wrapping prevention behavior in column headers.', '0 or empty = column title tooltips generated; any truthy value = column title tooltips suppressed', 1, 0, NULL, 1, '7d785b660628d5a01ba9e0ee5f4f71dfc590294feb26b4f50e0c23c2f75554e6', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:7209|check|if (!getDolGlobalString(''MAIN_DISABLE_WRAPPING_ON_COLUMN_TITLE'') && $wrapcolumntitle) {", "core/lib/functions.lib.php:7223|read|$tagstart .= ($name && !getDolGlobalString(''MAIN_DISABLE_WRAPPING_ON_COLUMN_TITLE'') && $wrapcolumntitle && !dol_textishtml($name)) ? '' title=\"'' . dolPrintHTMLForAttribute($langs->t", "//$out .= (getDolGlobalString(''MAIN_DISABLE_WRAPPING_ON_COLUMN_TITLE'') ? '''' : '' title=\"''.dol_escape_htmltag($langs->trans($name)).''\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISALLOW_MEDIAS_IN_EMAIL_TEMPLATES', 'bool', NULL, 'core', 'Forbids adding local media-browser links into HTML email templates/content.', 'In core/lib/functions2.lib.php:2916, function acceptLocalLinktoMedia() computes $acceptlocallinktomedia = getDolGlobalInt(''MAIN_DISALLOW_MEDIAS_IN_EMAIL_TEMPLATES'') ? 0 : 1, so setting this int forces the function to return false (disallow), overriding the default of allowing such links.', 'Enabling it blocks users from inserting locally-hosted media (uploaded documents/images) as links into email template HTML content; unset/false (default) permits it, subject to further checks (private-network IP, HTTP-only URL) in the same function.', 'true/1 (int) = disallow local media links in email templates; false/unset (default) = allow (subject to other security checks in the same function).', 1, 0, NULL, 1, 'f02bc3f57ebd08e449bbf79e5f6ddb32d661101f9811859521aff2a4bd0bfa60', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions2.lib.php:2911: // If $acceptlocallinktomedia is true, we can add link media files int email templates (we already can do this into HTML editor of an email).", "core/lib/functions2.lib.php:2916|read|$acceptlocallinktomedia = getDolGlobalInt(''MAIN_DISALLOW_MEDIAS_IN_EMAIL_TEMPLATES'') ? 0 : 1;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISALLOW_SELECT2_WITH_SMARTPHONE', 'bool', NULL, 'core', 'Disables the select2/ajax combobox enhancement specifically when the browser is detected as a smartphone.', 'Checked in ajax_combobox() in core/lib/ajax.lib.php:481; comment states ''select2 can be disabled for smartphones''. When the browser layout is ''phone'' and this constant is set, the function returns '''' (no combobox enhancement).', 'Enabling it makes select2-style ajax comboboxes fall back to plain HTML selects on smartphone browsers, avoiding potential usability issues with select2 on mobile.', 'Boolean: truthy value disables ajax_combobox() output when $conf->browser->layout == ''phone''.', 1, 0, NULL, 1, '2e507d7a915acf8f7ff3a67b5affbefcaf072adc3d755873b03415a15c119b9b', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/ajax.lib.php:481|check|if (!empty($conf->browser->layout) && $conf->browser->layout == ''phone'' && getDolGlobalString(''MAIN_DISALLOW_SELECT2_WITH_SMARTPHONE'')) {", "// select2 can be disabled for smartphones"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISALLOW_URL_INTO_DESCRIPTIONS', 'bool', NULL, 'core', 'Controls whether and how URL links are disallowed inside description fields.', 'Checked at core/lib/functions.lib.php:9820 and 9824, and in core/class/doleditor.class.php:265. The comments at admin/system/security.php:1024-1025 document the two modes: ''= 1, disallow url links except if on the local wrapper document.php or viewimage.php'' and ''= 2, disallow all urls link''.', 'Setting to 1 blocks external URLs while allowing local ones; setting to 2 blocks all URLs in descriptions; 0 or unset allows all URLs.', '1 = disallow url links except if on the local wrapper document.php or viewimage.php; 2 = disallow all urls link; 0 or empty = URLs allowed', 0, 0, 'admin/system/security.php', 1, '3cc8c003046f7b7cf02dd90499ff495c6bddbec5e816ed7c6d66a0ab822f1481', 'v2', '2026-04-21T13:29:58+00:00', '["admin/system/security.php:1024  // MAIN_DISALLOW_URL_INTO_DESCRIPTIONS = 1, disallow url links except if on the local wrapper document.php or viewimage.php", "admin/system/security.php:1025  // MAIN_DISALLOW_URL_INTO_DESCRIPTIONS = 2, disallow all urls link", "core/lib/functions.lib.php:9820|check|if (getDolGlobalInt(''MAIN_DISALLOW_URL_INTO_DESCRIPTIONS'') == 2 || $check == ''restricthtmlnolink'') {", "core/lib/functions.lib.php:9824|read|} elseif (getDolGlobalInt(''MAIN_DISALLOW_URL_INTO_DESCRIPTIONS'') == 1) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DISPLAY_SQL_INSTALL_LOG', 'string', NULL, 'core', 'Controls whether SQL execution output is displayed during module install/uninstall SQL script runs.', 'Read in core/modules/DolibarrModules.class.php at lines 1319, 1344, 1369, 1394, and 1419: the second argument to run_sql() is set to 0 (verbose) when the constant is non-empty, or 1 (silent) when it is empty.', 'Setting this to a non-empty value causes SQL install/uninstall log output to be displayed; leaving it empty suppresses the output.', 'Empty = SQL log suppressed (default); any non-empty value = SQL log displayed.', 1, 0, NULL, 1, '4b98a1502fcfaaa487b2b46264977fa462fc41a0eccffaf26583cdd93ec22ce1', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/DolibarrModules.class.php:1319|read|$result = run_sql($dir.$file, !getDolGlobalString(''MAIN_DISPLAY_SQL_INSTALL_LOG'') ? 1 : 0, 0, 1);", "core/modules/DolibarrModules.class.php:1344|read|$result = run_sql($dir.$file, !getDolGlobalString(''MAIN_DISPLAY_SQL_INSTALL_LOG'') ? 1 : 0, 0, 1);", "core/modules/DolibarrModules.class.php:1369|read|$result = run_sql($dir.$file, !getDolGlobalString(''MAIN_DISPLAY_SQL_INSTALL_LOG'') ? 1 : 0, 0, 1);", "core/modules/DolibarrModules.class.php:1394|read|$result = run_sql($dir.$file, !getDolGlobalString(''MAIN_DISPLAY_SQL_INSTALL_LOG'') ? 1 : 0, 0, 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENTS_DESCRIPTION_FIRST', 'string', NULL, 'core', 'Reorders PDF document lines to show the free-text description before the product/service label instead of after.', 'Checked in core/lib/pdf.lib.php:2105; when set, dol_concatdesc($desc, $libelleproduitservice) is called (description first) instead of the default dol_concatdesc($libelleproduitservice, $desc) (label first).', 'Swaps the order of label and description text on invoice/order/proposal PDF lines.', 'Boolean-like (set/unset); when set, description appears before the product/service label', 1, 0, NULL, 1, 'b97757694fbfc783010c202aa10f0fbf452cd861f375834a12eb8cd473119936', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:2105|check|if (getDolGlobalString(''MAIN_DOCUMENTS_DESCRIPTION_FIRST'')) {", "core/lib/pdf.lib.php:2106: $libelleproduitservice = dol_concatdesc($desc, $libelleproduitservice);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENTS_LIST_IN_TWOCOLUMNS', 'string', NULL, 'core', 'Renders the attached document list in a two-column layout instead of the default single-column layout.', 'Checked three times in core/tpl/document_actions_post_headers.tpl.php at lines 186, 217, and 235 to switch between single- and two-column rendering. No admin UI write was found; HIDDEN_GUESS is 1.', 'Enabling this constant changes the document list layout to two columns, affecting display width and arrangement of listed files.', '0 (single column) or 1 (two columns)', 1, 0, NULL, 1, '65c7a7d925287bd33dcb3dc4f6419cd59433a1c95c252d051670a72c18c2c2c7', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/document_actions_post_headers.tpl.php:186|check|if (getDolGlobalString(''MAIN_DOCUMENTS_LIST_IN_TWOCOLUMNS'')) {", "core/tpl/document_actions_post_headers.tpl.php:217|check|if (getDolGlobalString(''MAIN_DOCUMENTS_LIST_IN_TWOCOLUMNS'')) {", "core/tpl/document_actions_post_headers.tpl.php:235|check|if (getDolGlobalString(''MAIN_DOCUMENTS_LIST_IN_TWOCOLUMNS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENTS_LOGO_HEIGHT', 'string', NULL, 'admin', 'Sets the height (in pixels) of the logo printed on PDF documents.', 'Written at admin/pdf.php:153 via dolibarr_set_const and displayed in a text input at :532 using getDolGlobalInt with a default of 20. Configurable through the admin UI at admin/pdf.php.', 'Changing this integer value resizes the logo in generated PDF documents; the default is 20 when unset.', 'Integer (pixels); default = 20 when unset.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '0adf63afab76e35be9a0f59fe8caa964920dd687b7e5e37a0e33e0bacb3af4da', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf.php:532|read|print ''<input type=\"text\" class=\"maxwidth50\" name=\"MAIN_DOCUMENTS_LOGO_HEIGHT\" value=\"''.getDolGlobalInt(''MAIN_DOCUMENTS_LOGO_HEIGHT'', 20).''\">'';", "admin/pdf.php:153|write|dolibarr_set_const($db, \"MAIN_DOCUMENTS_LOGO_HEIGHT\", GETPOSTINT(\"MAIN_DOCUMENTS_LOGO_HEIGHT\"), ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENTS_SHOW_FILE_ATTACHMENT_FORM', 'bool', NULL, 'core', 'Forces the ''attach file/document'' upload form to be shown expanded by default on object document tabs, instead of collapsed behind a show/hide toggle.', 'In core/tpl/document_actions_post_headers.tpl.php:211, $showHideAddButtonValue defaults to 1 (collapsed, toggle needed) but is set to 0 (expanded/always shown) when this constant is set.', 'Enabling it makes the file-attachment upload form visible immediately on document tabs rather than hidden behind a toggle button.', 'Boolean/int: truthy forces the attachment form open by default; unset/0 (default) keeps it collapsed behind the toggle.', 1, 0, NULL, 1, '47f98bfab9d1d7e767974d1aa406c106ddabefe9a0287b80f891c69369730701', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/document_actions_post_headers.tpl.php:211|check|if (getDolGlobalInt(''MAIN_DOCUMENTS_SHOW_FILE_ATTACHMENT_FORM'')) {", "core/tpl/document_actions_post_headers.tpl.php: $showHideAddButtonValue = 1; ... $showHideAddButtonValue = 0;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENTS_SHOW_FILE_LINKING_FORM', 'bool', NULL, 'core', 'Forces the ''link to external file/URL'' form to be shown expanded by default on object document tabs, instead of collapsed behind a show/hide toggle.', 'In core/tpl/document_actions_post_headers.tpl.php:250, $showHideAddButtonValue defaults to 1 (collapsed) but is set to 0 (expanded/always shown) when this constant is set, before the list-of-links form is rendered.', 'Enabling it makes the file-linking form visible immediately on document tabs rather than hidden behind a toggle button.', 'Boolean/int: truthy forces the linking form open by default; unset/0 (default) keeps it collapsed behind the toggle.', 1, 0, NULL, 1, 'f1f12fa77ab9002b3a269bbb871befa00aa6b00328b280dab203965949ed5005', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/document_actions_post_headers.tpl.php:250|check|if (getDolGlobalInt(''MAIN_DOCUMENTS_SHOW_FILE_LINKING_FORM'')) {", "core/tpl/document_actions_post_headers.tpl.php: $showHideAddButtonValue = 1; ... $showHideAddButtonValue = 0;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENTS_WITH_PICTURE_HEIGHT', 'string', NULL, 'core', 'Sets the maximum height (in PDF mm units) used to scale product/attachment images embedded in generated PDF documents.', 'Read in core/lib/pdf.lib.php:3163 inside pdf_getSizeForImage(), with a default of 32, alongside the sibling MAIN_DOCUMENTS_WITH_PICTURE_WIDTH (default 20) which caps the computed width.', 'Increasing the value allows taller images to be embedded before the function falls back to constraining by width instead; the function''s docblock states the default max is ''20x32''.', 'Integer, in PDF mm units; default is 32 per the getDolGlobalInt() call and confirmed by the docblock ''(20x32 by default)''.', 1, 0, NULL, 1, 'aac21533ece2b32ec7206e9e7259d437ecb17df493d237feb8f90c2bc8b16db9', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:3154: * Return dimensions to use for images onto PDF checking that width and height are not higher than", "core/lib/pdf.lib.php:3155: * maximum (20x32 by default).", "core/lib/pdf.lib.php:3163: $maxheight = getDolGlobalInt(''MAIN_DOCUMENTS_WITH_PICTURE_HEIGHT'', 32);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENTS_WITH_PICTURE_WIDTH', 'string', NULL, 'core', 'Sets the column width in millimetres reserved for product pictures in PDF documents.', 'Written via admin/pdf_other.php:118 and read in 24 locations including core/modules/stocktransfer/doc/pdf_eagle.modules.php:144, core/modules/expedition/doc/pdf_rouget.modules.php:135, and core/lib/pdf.lib.php:3150. Default fallback value is 20 mm as shown in the comment.', 'Changing this value alters the width of the picture column in all PDF generators that include product images; the default is 20 mm when not set.', 'Integer value in millimetres; default 20 mm when not set (e.g. getDolGlobalInt(''MAIN_DOCUMENTS_WITH_PICTURE_WIDTH'', 20))', 0, 0, 'admin/pdf_other.php', 1, '17ad39f72548d0094e750b41026573ec98549149f23d171614bae6eae0537b74', 'v2', '2026-04-21T11:16:15+00:00', '["modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:1278  // \t''width'' => (!getDolGlobalInt(''MAIN_DOCUMENTS_WITH_PICTURE_WIDTH'') ? 20 : getDolGlobalInt(''MAIN_DOCUMENTS_WITH_PICTURE_WIDTH'')), // in mm", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:144|read|$this->posxpicture = $this->posxweightvol - getDolGlobalInt(''MAIN_DOCUMENTS_WITH_PICTURE_WIDTH'', 20); // width of images", "core/modules/expedition/doc/pdf_rouget.modules.php:135|read|$this->posxpicture = $this->posxweightvol - getDolGlobalInt(''MAIN_DOCUMENTS_WITH_PICTURE_WIDTH'', 20); // width of images", "core/lib/pdf.lib.php:3150|read|$maxwidth = getDolGlobalInt(''MAIN_DOCUMENTS_WITH_PICTURE_WIDTH'', 20);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENT_DISABLE_NOEXE_IN_MEDIAS_DIR', 'bool', NULL, 'api', 'Disables appending the ''.noexe'' suffix to uploaded files with executable content when they are stored specifically inside the public medias directory.', 'Checked (as int) in core/lib/files.lib.php:1558 and api/class/api_documents.class.php:1020 (identical logic, same inline comment ''We never add .noexe on files into media directory''): the ''.noexe'' suffix is added unless the upload path is inside the medias directory AND this constant is set.', 'When set, executable-content files uploaded into the medias directory keep their original extension instead of being renamed with a ''.noexe'' suffix, restoring a small security mitigation that is normally applied outside the medias dir; when unset (default), the special-case exemption for the medias dir does not apply and normal .noexe rules still get bypassed only within the medias dir per the comment logic.', 'Not set/0 (default): files inside medias dir do not get .noexe suffix (medias dir already exempted). Truthy int: also affects behavior per the OR condition (files outside medias dir path get .noexe unless this is set) — exact interaction unclear, see condition combining strpos() and this flag with OR.', 1, 0, NULL, 1, '98f9b1c9a95bb6f4da87d93bb57d2decc43e30f96e72ce0068dbf662398c57bf', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/files.lib.php:1558|check|if (strpos($upload_dir, $publicmediasdirwithslash) !== 0 || !getDolGlobalInt(\"MAIN_DOCUMENT_DISABLE_NOEXE_IN_MEDIAS_DIR\")) {\t// We never add .noexe on files into media directory", "api/class/api_documents.class.php:1020|check|if (strpos($upload_dir, $publicmediasdirwithslash) !== 0 || !getDolGlobalInt(\"MAIN_DOCUMENT_DISABLE_NOEXE_IN_MEDIAS_DIR\")) {\t// We never add .noexe on files into media directory"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOCUMENT_IS_OUTSIDE_WEBROOT_SO_NOEXE_NOT_REQUIRED', 'string', NULL, 'core', 'Disables the automatic appending of the .noexe extension to uploaded executable files.', 'Checked in core/lib/files.lib.php:1505, api/class/api_documents.class.php:1200, and core/actions_linkedfiles.inc.php:283. The comment at core/lib/files.lib.php:1441 explains that .noexe is added when a file has executable content unless this constant is set. Displayed in admin/system/security.php:1044.', 'When set, executable uploaded files will not have .noexe appended, which is safe only if the document directory is outside the webroot. When unset, executable files receive the .noexe suffix as a security measure.', '0 or unset = .noexe extension is appended to executable files (default/secure); truthy value = .noexe is not appended (only safe if documents are outside webroot).', 0, 0, 'admin/system/security.php', 1, '413ee97151d2317753c02dd5ea1254e83d112d8c746eb63293f3c1c77fa42c1e', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/files.lib.php:1441  *  - Extension .noexe may be added if file is executable and MAIN_DOCUMENT_IS_OUTSIDE_WEBROOT_SO_NOEXE_NOT_REQUIRED is not set.", "core/lib/files.lib.php:1505|check|if (isAFileWithExecutableContent($dest_file) && !getDolGlobalString(''MAIN_DOCUMENT_IS_OUTSIDE_WEBROOT_SO_NOEXE_NOT_REQUIRED'')) {", "api/class/api_documents.class.php:1200|check|if (isAFileWithExecutableContent($dest_file) && !getDolGlobalString(''MAIN_DOCUMENT_IS_OUTSIDE_WEBROOT_SO_NOEXE_NOT_REQUIRED'')) {", "core/actions_linkedfiles.inc.php:283|check|if (isAFileWithExecutableContent($filenameto) && !getDolGlobalString(''MAIN_DOCUMENT_IS_OUTSIDE_WEBROOT_SO_NOEXE_NOT_REQUIRED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOC_CREATE_METAFILE', 'string', NULL, 'core', 'Enables generation of a meta file alongside document files when they are created.', 'The comment states: ''This feature to generate the meta file is enabled only if option MAIN_DOC_CREATE_METAFILE is set.'' In core/lib/files.lib.php, when this constant is not set, meta file generation is skipped. No admin UI; hidden setting.', 'Setting this constant enables meta file creation alongside document generation; leaving it unset skips meta file generation.', 'Non-empty (truthy) enables meta file generation; empty or undefined disables it.', 1, 0, NULL, 1, '8f1967c2cd8a71d0298d1fc7ba9208157165e9bd4fcb8aa53c4bee5f329abd02', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/files.lib.php:1879  *  This feature to generate the meta file is enabled only if option MAIN_DOC_CREATE_METAFILE is set.", "core/lib/files.lib.php:1889|check|if (!getDolGlobalString(''MAIN_DOC_CREATE_METAFILE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOC_ODT_IMAGE_RATIO', 'string', NULL, 'core', 'Sets a scale ratio applied to images embedded in ODT documents generated from templates.', 'Checked across 46 occurrences in ODT generation modules; when set, the ratio value overrides the default image scaling used during ODT template substitution.', 'Setting this value scales images in generated ODT documents; leaving it unset uses the default image dimensions.', 'Numeric string (scale ratio, e.g. ''0.5'' for half size); empty or unset = default scaling.', 1, 0, NULL, 1, 'fb2d8396b2f5ecb0eed92b3125ffb6e982de6e2597effe9ec075ccbaf6d8d9f2', 'v2', '2026-04-21T11:16:15+00:00', '["recruitment/core/modules/recruitment/doc/doc_generic_recruitmentjobposition_odt.modules.php:411|check|if (getDolGlobalString(''MAIN_DOC_ODT_IMAGE_RATIO'')) {", "core/modules/contract/doc/doc_generic_contract_odt.modules.php:393|check|if (getDolGlobalString(''MAIN_DOC_ODT_IMAGE_RATIO'')) {", "core/modules/member/doc/doc_generic_member_odt.class.php:357|check|if (getDolGlobalString(''MAIN_DOC_ODT_IMAGE_RATIO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOC_SORT_FIELD', 'string', NULL, 'projet', 'Specifies the default field used to sort documents in document list views across multiple modules.', 'Checked and read across at least 10 occurrences in document list pages including projet/document.php (line 77-78), societe/document.php (line 69-70), contact/document.php (line 76-77), comm/propal/document.php, and commande/document.php.', 'Setting this value changes the default sort column applied to document lists in the affected modules.', 'String (field name, e.g. ''date'', ''name''); empty means the default sort field for each page is used.', 1, 0, NULL, 1, '16a02f149dfed4978d2c7835b76ab0578f378ee3c0e909146d722facc79d8781', 'v2', '2026-04-21T11:16:15+00:00', '["projet/document.php:77|check|if (getDolGlobalString(''MAIN_DOC_SORT_FIELD'')) {", "projet/document.php:78|read|$sortfield = getDolGlobalString(''MAIN_DOC_SORT_FIELD'');", "societe/document.php:70|read|$sortfield = getDolGlobalString(''MAIN_DOC_SORT_FIELD'');", "contact/document.php:77|read|$sortfield = getDolGlobalString(''MAIN_DOC_SORT_FIELD'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOC_SORT_ORDER', 'string', NULL, 'projet', 'Specifies the default sort direction (ASC or DESC) for document lists across multiple modules.', 'Checked and read across at least 10 occurrences in document list pages including projet/document.php (line 80-81), societe/document.php (line 72-73), contact/document.php (line 79-80), comm/propal/document.php, and commande/document.php.', 'Setting this value changes the default sort direction applied to document lists in the affected modules.', 'String (''ASC'' or ''DESC''); empty means the default sort order for each page is used.', 1, 0, NULL, 1, '75d40e174c1efaf59c8f1609b829018e121551b05e625f7c5e5f2acf5cccf015', 'v2', '2026-04-21T11:16:15+00:00', '["projet/document.php:80|check|if (getDolGlobalString(''MAIN_DOC_SORT_ORDER'')) {", "projet/document.php:81|read|$sortorder = getDolGlobalString(''MAIN_DOC_SORT_ORDER'');", "societe/document.php:73|read|$sortorder = getDolGlobalString(''MAIN_DOC_SORT_ORDER'');", "contact/document.php:80|read|$sortorder = getDolGlobalString(''MAIN_DOC_SORT_ORDER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOC_UPLOAD_NOT_RENAME_BY_DEFAULT', 'string', NULL, 'core', 'Controls whether the ''rename file on upload using mask'' checkbox is pre-checked by default in the document upload form.', 'In core/class/html.formfile.class.php:289, `$rename = getDolGlobalString(''MAIN_DOC_UPLOAD_NOT_RENAME_BY_DEFAULT'') ? '''' : ''checked'';` — when the constant is set, the ''savingdocmask'' checkbox (auto-rename uploaded file using the naming mask) starts unchecked; when unset (default), it starts checked.', 'Setting it changes the default state of the upload form''s rename-on-upload checkbox from checked to unchecked, meaning uploaded files are not renamed to the mask pattern unless the user manually checks the box.', 'Boolean-like: set/non-empty leaves the ''savingdocmask'' rename checkbox unchecked by default; unset (default) leaves it checked.', 1, 0, NULL, 1, 'c47a342abb8f8af3693c20c84cb156b1e7e343b9c41f4a052c39fadd1db79f75', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formfile.class.php:289: $rename = getDolGlobalString(''MAIN_DOC_UPLOAD_NOT_RENAME_BY_DEFAULT'') ? '''' : ''checked'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOC_USE_OBJECT_THIRDPARTY_NAME', 'bool', NULL, 'core', 'Prefixes generated ODT document filenames with the sanitized thirdparty name.', 'In core/modules/societe/doc/doc_generic_odt.modules.php:264, when building the ODT output filename, if this bool is set the code prepends dol_sanitizeFileName(dol_string_nospecial($object->name)) to the template-derived filename part.', 'Setting it to true changes the generated ODT/ODS document filename to start with the thirdparty''s sanitized name; leaving it unset/false keeps the default filename derived from the template name only.', 'true/1 = prefix filename with thirdparty name; false/unset (default) = no prefix.', 1, 0, NULL, 1, '7c009a0d56b4979824cd2f4d98f27a244fe825554468c19faf32e94dccd54b5a', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/societe/doc/doc_generic_odt.modules.php:264|check|if (getDolGlobalString(''MAIN_DOC_USE_OBJECT_THIRDPARTY_NAME'')) {", "core/modules/societe/doc/doc_generic_odt.modules.php:265: $newfiletmp = dol_sanitizeFileName(dol_string_nospecial($object->name)) . ''-'' . $newfiletmp;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOC_USE_TIMING', 'bool', NULL, 'core', 'Enables timing/profiling output during ODT document generation for debugging purposes.', 'Checked across 44 occurrences in ODT document generation modules (e.g. contracts, stock, users, members, shipments, orders) at the start of the document build process.', 'Enabling this activates timing measurements during document generation; it is a debugging aid with no effect on the generated document content.', '0 or unset = no timing output; 1 = timing output enabled.', 1, 0, NULL, 1, 'f7be731c77a9219d5296024f773a8a5af9377b144c72c99b1fb56f7e615ea08e', 'v2', '2026-04-21T11:16:15+00:00', '["recruitment/core/modules/recruitment/doc/doc_generic_recruitmentjobposition_odt.modules.php:291|check|if (getDolGlobalString(''MAIN_DOC_USE_TIMING'')) {", "core/modules/contract/doc/doc_generic_contract_odt.modules.php:277|check|if (getDolGlobalString(''MAIN_DOC_USE_TIMING'')) {", "core/modules/user/doc/doc_generic_user_odt.modules.php:303|check|if (getDolGlobalString(''MAIN_DOC_USE_TIMING'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOLEDITOR_HEIGHT', 'string', NULL, 'core', 'Sets the height (in pixels) of the DolEditor rich text editor on document line create and edit forms.', 'The value is passed directly as the height argument to DolEditor in core/tpl/objectline_create.tpl.php:456 and core/tpl/objectline_edit.tpl.php:196; the default fallback is 100.', 'Changing this constant adjusts the visible height of the line description editor on both the create and edit templates.', 'Integer (pixels); default fallback = 100.', 1, 0, NULL, 1, 'e208d9b1d01d4207fcfc404b3a9e446ad490d8fde5df3489ca0a4c631f02e7ac', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:456|read|$doleditor = new DolEditor(''dp_desc'', GETPOST(''dp_desc'', ''restricthtml''), '''', getDolGlobalInt(''MAIN_DOLEDITOR_HEIGHT'', 100), $toolbarname, '''', false, true, $enabled, $nbrows, ''98%''", "core/tpl/objectline_edit.tpl.php:196|read|$doleditor = new DolEditor(''product_desc'', GETPOSTISSET(''product_desc'') ? GETPOST(''product_desc'', ''restricthtml'') : $line->description, '''', getDolGlobalInt(''MAIN_DOLEDITOR_HEIGHT'',"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOLIBARR_USER_TIMEZONE', 'string', NULL, 'core', 'Sets a fallback timezone used in cron/CLI contexts where no user session timezone is available, defaulting to UTC.', 'Checked in core/lib/functions.lib.php:3943 with a default of ''UTC''; the comment at line 3942 explains this is used when there is no session (e.g. in cron). No admin UI write detected.', 'Changing this value shifts date/time calculations in cron jobs to the specified timezone. Without it, UTC is used as the fallback.', 'if no session (by example in cron) may use MAIN_DOLIBARR_USER_TIMEZONE instead UTC. Any valid PHP timezone string (e.g., ''Europe/Berlin'', ''Indian/...''); default ''UTC''.', 1, 0, NULL, 1, 'db4dcf357f63530deb4a124218e38067d928e9a169ea7da1e3756ae16118c81a', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:3942  // if no session (by example in cron) may use MAIN_DOLIBARR_USER_TIMEZONE instead UTC", "core/lib/functions.lib.php:3943|check|$offsettzstring = (empty($_SESSION[''dol_tz_string'']) ? getDolGlobalString(''MAIN_DOLIBARR_USER_TIMEZONE'', ''UTC'') : $_SESSION[''dol_tz_string'']);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DOL_SCRIPTS_ROOT', 'string', NULL, 'core', 'Specifies the filesystem path to the Dolibarr scripts root directory, used for locating the odt2pdf conversion script and cron scripts.', 'Checked and read at includes/odtphp/odf.php lines 941 and 944 to build the odt2pdf.sh command path. Also checked and read at core/lib/cron.lib.php lines 134 and 135 to set the path to cron scripts.', 'Setting this constant enables ODT-to-PDF conversion via the odt2pdf.sh script and provides the base path for cron scripts. Clearing it disables those integrations.', 'String; filesystem path to the scripts root directory, e.g. ''/var/www/dolibarr/scripts''.', 1, 0, NULL, 1, '4a09dec47a0b3617097583cdba8c6ef0a196aef1df2021356115d0abebf35693', 'v2', '2026-04-21T13:29:58+00:00', '["includes/odtphp/odf.php:944|read|$command = dol_sanitizePathName(getDolGlobalString(''MAIN_DOL_SCRIPTS_ROOT'')).''/scripts/odt2pdf/odt2pdf.sh ''.escapeshellarg($tmpname).'' ''.escapeshellarg($paramodt2pdf);", "includes/odtphp/odf.php:941|check|if (getDolGlobalString(''MAIN_DOL_SCRIPTS_ROOT'')) {", "core/lib/cron.lib.php:134|check|if (getDolGlobalString(''MAIN_DOL_SCRIPTS_ROOT'')) {", "core/lib/cron.lib.php:135|read|$pathtoscript = getDolGlobalString(''MAIN_DOL_SCRIPTS_ROOT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DONT_KEEP_NOTE_ON_CLONING', 'string', NULL, 'fourn', 'Controls whether the private/public note is kept or cleared when cloning an object (supplier invoice, invoice, proposal).', 'Checked with strict equality to 1 in fourn/class/fournisseur.facture.class.php:3250, compta/facture/class/facture.class.php:1346, and comm/propal/class/propal.class.php:1604.', 'When set to 1, the note is not carried over to the cloned object.', '1 = do not keep note on cloning (per usage pattern == 1)', 1, 0, NULL, 1, '984fea004d90893027e6aacab7a32d062d955250e87851d87fbf42a2ec7a8ab6', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalInt(''MAIN_DONT_KEEP_NOTE_ON_CLONING'') == 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DONT_SHIP_MORE_THAN_ORDERED', 'string', NULL, 'expedition', 'Blocks creating/validating a shipment line whose quantity exceeds the quantity ordered on the source order line.', 'Checked once in expedition/card.php:493 when building shipment lines: if set and the subtotal quantity being shipped exceeds $objectsrc->lines[$i]->qty (the ordered quantity), the line is rejected with error ErrorTooMuchShipped.', 'Enabling it enforces a hard cap so shipment quantities can never exceed the ordered quantity per line; leaving it unset/off allows over-shipping.', 'Boolean via getDolGlobalInt: truthy enables the ordered-quantity cap check.', 1, 0, NULL, 1, 'b071d15c616e1966abef1453f70efc16593f8190c098e452f5a505e636ba110a', 'v2', '2026-07-24T07:05:23+00:00', '["expedition/card.php:492: // check qty shipped not greater than ordered", "expedition/card.php:493: if (getDolGlobalInt(\"MAIN_DONT_SHIP_MORE_THAN_ORDERED\") && $subtotalqty > $objectsrc->lines[$i]->qty) {", "expedition/card.php:494: setEventMessages($langs->trans(\"ErrorTooMuchShipped\", $i + 1), null, ''errors'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DO_FETCH_IN_ONE_SQL_REQUEST', 'string', NULL, 'compta', 'Enables fetching invoice lines via a single consolidated SQL request instead of individual queries.', 'Configured via admin/system/perf.php (read at line 799, checked at line 793). Read in compta/facture/class/facture.class.php (lines 2207, 2476) and compta/facture/class/factureligne.class.php:204 to control the fetch strategy for invoice lines.', 'When enabled, invoice line loading uses a single SQL query which can improve performance on large invoice sets; when disabled or unset, the default fetch strategy is used.', 'Integer: non-zero to enable single-SQL fetch; 0 or unset to use the default.', 0, 0, 'admin/system/perf.php|admin/system/perf.php', 1, '272424a13abc9e85c624a3b542dd5f34cfd3d3a67d0a69fb7b4b6d7e7e1eb635', 'v2', '2026-04-21T11:16:15+00:00', '["admin/system/perf.php:799|read|print '' = ''.getDolGlobalString(''MAIN_DO_FETCH_IN_ONE_SQL_REQUEST'', ''<span class=\"opacitymedium\">''.$langs->trans(\"Undefined\").''</span>'');", "compta/facture/class/facture.class.php:2207|read|$doFetchInOneSqlRequest = getDolGlobalInt(''MAIN_DO_FETCH_IN_ONE_SQL_REQUEST'');", "compta/facture/class/factureligne.class.php:204|read|$doFetchInOneSqlRequest = getDolGlobalInt(''MAIN_DO_FETCH_IN_ONE_SQL_REQUEST'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DO_NOT_AUTOFILL_DATE_INVOICE', 'string', NULL, 'compta', 'Prevents automatic pre-filling of the invoice date field on invoice creation, leaving it empty instead.', 'In compta/facture/card.php:3781, $dateinvoice is set to -1 (meaning keep empty) when this constant is truthy; otherwise it defaults to '''' which triggers autofill of today''s date, per the inline comment.', 'Enabling it makes the invoice date field blank by default on the invoice creation form instead of being pre-filled with the current date.', 'Boolean-like flag; per inline comment: default '''' = autofill date, truthy => -1 = keep empty.', 1, 0, NULL, 1, 'b0528e2c188ff0bb78022b9a596934c729aad514a6b152e57cac891e9a622510', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/card.php:3781: $dateinvoice = (getDolGlobalString(''MAIN_DO_NOT_AUTOFILL_DATE_INVOICE'') ? -1 : ''''); // By default '''' so we will autofill date. -1 means keep empty."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DO_NOT_AUTOFILL_DATE_ORDER', 'string', NULL, 'commande', 'Controls whether the order date field is left empty or auto-filled with the current date on the order creation form.', 'Read in commande/card.php:2383 with inline comment: $dateorder = (getDolGlobalString(''MAIN_DO_NOT_AUTOFILL_DATE_ORDER'') ? -1 : ''''); // By default '''' so we will autofill date. -1 means keep empty.', 'When enabled, the order date field starts empty (-1) instead of being autofilled with today''s date ('''').', 'Boolean: unset/0 (default) autofills date (''''); 1/true keeps date field empty (-1), per inline comment.', 0, 0, NULL, 1, '1914ac88f9ccb148d1fed3cffe51c1975a4524ca126d988fa3acd0bd69d7570d', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:2383: $dateorder = (getDolGlobalString(''MAIN_DO_NOT_AUTOFILL_DATE_ORDER'') ? -1 : '''');\t\t// By default '''' so we will autofill date. -1 means keep empty."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DO_NOT_AUTOFILL_DATE_PROPOSAL', 'string', NULL, 'comm', 'Controls whether the proposal creation date field is auto-filled or left empty by default.', 'When set, the proposal date field is initialized to -1 (kept empty) instead of being auto-filled with the current date. Seen in comm/propal/card.php:2240.', 'If enabled, users must manually enter the proposal date; if absent or empty, the date is auto-filled automatically.', 'Empty/unset = auto-fill date; any truthy value = keep date field empty (-1).', 1, 0, NULL, 1, '9d457b3c6be302b755807def8eaf8be0bbe68890fbea3ee82de7d815eca3383c', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/card.php:2240|read|$datepropal = (getDolGlobalString(''MAIN_DO_NOT_AUTOFILL_DATE_PROPOSAL'') ? -1 : '''');  // By default '''' so we will autofill date. -1 means keep empty."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DUPLICATE_CONTACTS_TAB_ON_CUSTOMER_CARD', 'string', NULL, 'comm', 'Additionally prints the contacts list directly on the third-party (customer) card page, duplicating what is normally only shown on the dedicated Contacts tab.', 'Used in comm/card.php:1823: if truthy, calls show_contacts($conf, $langs, $db, $object, ...) to print the contact list inline on the company card, right after the main action-buttons block.', 'Enabling it adds a redundant contacts list section directly on the third-party card view, in addition to the existing Contacts tab.', 'Boolean-like: truthy triggers an extra show_contacts() call on the customer/company card page.', 0, 0, NULL, 1, '77fea0729c584670b408b320f37c9cf295f090e6287f95ae634ff59d5b48dd6e', 'v2', '2026-07-24T07:05:23+00:00', '["comm/card.php:1823|check|if (getDolGlobalString(''MAIN_DUPLICATE_CONTACTS_TAB_ON_CUSTOMER_CARD'')) {", "comm/card.php:1825|show_contacts($conf, $langs, $db, $object, $_SERVER[\"PHP_SELF\"].''?socid=''.$object->id);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DUPLICATE_CONTACTS_TAB_ON_MAIN_CARD', 'string', NULL, 'societe', 'Displays a contacts tab directly on the main third-party card in addition to the dedicated contacts page.', 'When set, societe/card.php:933 renders the contacts section on the main company card (subject to SOCIETE_DISABLE_CONTACTS and SOCIETE_ADDRESSES_MANAGEMENT) and societe/card.php:3605 adds a tab. fourn/card.php:1114 also checks it for supplier cards.', 'Enabling this constant duplicates the contacts tab on main entity cards; disabling it removes that duplicate.', 'Truthy value shows contacts on the main card; absent or falsy hides it.', 1, 0, NULL, 1, 'de41459b6d5c87f6c144aa2b2d4c9f231ec5a35333a10ac05eacc17c253bfcd4', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/card.php:1114|check|if (getDolGlobalString(''MAIN_DUPLICATE_CONTACTS_TAB_ON_MAIN_CARD'')) {", "societe/card.php:933|check|if (getDolGlobalString(''MAIN_DUPLICATE_CONTACTS_TAB_ON_MAIN_CARD'') && (!getDolGlobalString(''SOCIETE_DISABLE_CONTACTS'') || getDolGlobalString(''SOCIETE_ADDRESSES_MANAGEMENT''))) {", "societe/card.php:3605|check|if (getDolGlobalString(''MAIN_DUPLICATE_CONTACTS_TAB_ON_MAIN_CARD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DURATION_OF_WORKDAY', 'string', NULL, 'projet', 'Defines the number of seconds in a workday, used when converting time durations to a days-hours-minutes display.', 'Read as $conf->global->MAIN_DURATION_OF_WORKDAY and passed to convertSecondToTime() across multiple files including projet/tasks/time.php:518, :711, :869, projet/element.php:1900, fichinter/card.php:1510, fichinter/card-rec.php:353, and ticket/card.php:1240. No admin UI write path is present in the payload.', 'Setting this to the number of seconds in a workday (e.g. 28800 for 8 hours) controls how time totals are broken into days versus hours in duration displays.', 'Integer number of seconds per workday (e.g. 28800 = 8 hours).', 1, 0, NULL, 1, '5f17570f042599ce0d1cb19751a79cbc5d3d94c276d7820874292acf89d6fd00', 'v2', '2026-04-21T11:16:15+00:00', '["projet/tasks/time.php:518|read|$qtyhourtext = convertSecondToTime($timespent_data[''timespent''], ''all'', $conf->global->MAIN_DURATION_OF_WORKDAY);", "fichinter/card.php:1510|read|print ''<td>''.convertSecondToTime($object->duration, ''all'', $conf->global->MAIN_DURATION_OF_WORKDAY).'' (''.convertDurationtoHour($object->duration, \"s\").'' ''.$langs->trans(\"HourShort\"", "ticket/card.php:1240|read|print $foundinter ? convertSecondToTime($timing, ''all'', getDolGlobalInt(''MAIN_DURATION_OF_WORKDAY'')) : '''';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_DURATION_STEP', 'string', NULL, 'core', 'Sets the step (in minutes) between options in the minutes <select> of duration/hour-minute input widgets.', 'Read in Form''s duration selector code at core/class/html.form.class.php:8866; used as $step, and if not >0 the code falls back to a duration_step of 5 minutes when building the minute <option> list.', 'Increasing it produces fewer, more widely spaced minute options in the select (e.g. 0,5,10... by default); a non-positive or unset value falls back to steps of 5.', 'Integer number of minutes per step; if not set or <=0, code uses 5 as the effective step.', 1, 0, NULL, 1, '06fb01696d8d1867a0cf2782fc108a7805dc015ad520a32d34aac6b3a0102725', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:8866|read|$step = getDolGlobalInt(''MAIN_DURATION_STEP'');", "core/class/html.form.class.php:8867|$duration_step = ($step > 0) ? $step : 5;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EASTER_EGG_COMMITSTRIP', 'string', NULL, 'core', 'Enables an easter-egg widget on the login page that fetches and displays a CommitStrip comic.', 'In core/tpl/login.tpl.php:559, if set, the login template calls getURLContent() against the CommitStrip RSS feed (French or English depending on language) and embeds the comic on the login screen.', 'Enabling it makes the login page perform an outbound HTTP request to commitstrip.com on every login view to fetch and display a comic strip; purely cosmetic/easter-egg, no functional impact on authentication.', 'Boolean/truthy: when set, the CommitStrip comic feed is fetched and shown on the login page.', 1, 0, NULL, 1, 'c39204a5db398ed36c8b32fab2664d64ba55aa1c3c4eb5860c120ed4a2ba88a5', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/login.tpl.php:559|check|if (getDolGlobalString(''MAIN_EASTER_EGG_COMMITSTRIP'')) {", "core/tpl/login.tpl.php: $resgetcommitstrip = getURLContent(\"https://www.commitstrip.com/fr/feed/\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ECM_DISABLE_JS', 'bool', NULL, 'core', 'Disables JavaScript/AJAX-based interactions in the ECM (document management) file manager pages.', 'Checked in website/index.php:3079, ecm/index.php:333, ecm/index_auto.php:305/445/558, ecm/index_medias.php:302, and core/tpl/filemanager.tpl.php:123/188, generally combined with a check on $conf->use_javascript_ajax.', 'When enabled, the ECM/file manager falls back to non-AJAX navigation links (e.g. manual refresh) instead of dynamic JS behavior.', NULL, 1, 0, NULL, 1, '30fc63fef7aff106d405c96fc2c4b719aaffa15aefcac2e643e94aca32c7d08b', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''MAIN_ECM_DISABLE_JS'')) {", "$url = ((!empty($conf->use_javascript_ajax) && !getDolGlobalString(''MAIN_ECM_DISABLE_JS'')) ? ''#'' : ($_SERVER[\"PHP_SELF\"].''?action=refreshmanual''..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EDIT_LINE_ALLOW_ALL_UNIT_TYPE', 'bool', NULL, 'reception', 'When set, allows editing a line''s unit type to any unit regardless of the existing unit assignment.', 'Checked in reception/tpl/objectline_edit.tpl.php:142, core/tpl/objectline_edit.tpl.php:317, and expedition/tpl/objectline_edit.tpl.php:142. When absent and the line has an existing fk_unit, the unit selector is restricted.', 'Setting this constant allows users to freely change the unit type on existing document lines; without it, unit editing is restricted when a unit is already assigned.', 'Non-empty/truthy = allow any unit type selection; empty/unset = restrict unit editing (default)', 1, 0, NULL, 1, '5cbd7f0a45a53bfced4a1819da3a930a1b0b213e5cc1bfe8a5bd278164f73185', 'v2', '2026-04-21T11:16:15+00:00', '["reception/tpl/objectline_edit.tpl.php:142|check|if (!empty($line->fk_unit) && !getDolGlobalString(''MAIN_EDIT_LINE_ALLOW_ALL_UNIT_TYPE'')) {", "core/tpl/objectline_edit.tpl.php:317|check|if (!empty($line->fk_unit) && !getDolGlobalString(''MAIN_EDIT_LINE_ALLOW_ALL_UNIT_TYPE'')) {", "expedition/tpl/objectline_edit.tpl.php:142|check|if (!empty($line->fk_unit) && !getDolGlobalString(''MAIN_EDIT_LINE_ALLOW_ALL_UNIT_TYPE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAILCOLLECTOR_MAIL_WITHOUT_HEADER', 'string', NULL, 'emailcollector', 'Hides e-mail headers from messages collected by the Email Collector module.', 'Checked in emailcollector/class/emailcollector.class.php at lines 3190, 3484, 3634, and 3784; documented in admin/emailcollector_list.php:798 as ''Hide e-mail headers from collected messages''.', 'When enabled, collected email headers are not shown/stored as part of the collected message.', NULL, 1, 0, NULL, 1, 'd8838360f8bf9fe416436a11d9429aba24d667b363faa7559d9be06c7cc2d275', 'v2', '2026-07-24T06:41:12+00:00', '["// MAIN_EMAILCOLLECTOR_MAIL_WITHOUT_HEADER: Hide e-mail headers from collected messages", "if (!getDolGlobalString(''MAIN_EMAILCOLLECTOR_MAIL_WITHOUT_HEADER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAILCOLLECTOR_TICKET_CATEGORY_CODE', 'string', NULL, 'emailcollector', 'Default ticket category code assigned to tickets auto-created by the email collector from incoming emails.', 'Read in emailcollector/class/emailcollector.class.php:3642 as the default value passed to getDolGlobalString, falling back to dol_getIdFromCode() lookup of the c_ticket_category dictionary''s ''use_default'' entry if unset.', 'Setting it overrides which ticket category code is used for tickets created by the email collector, instead of the dictionary''s default category.', 'String, a valid c_ticket_category dictionary code.', 0, 0, NULL, 1, 'd5592a3b5f4d64d5fd63876cf1444d2b84c2e39f038c326546d69495535f99b8', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:3642|$tickettocreate->category_code = (getDolGlobalString(''MAIN_EMAILCOLLECTOR_TICKET_CATEGORY_CODE'', dol_getIdFromCode($this->db, 1, ''c_ticket_category'', ''use_default'', ''code'', 1)));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAILCOLLECTOR_TICKET_SEVERITY_CODE', 'string', NULL, 'emailcollector', 'Default ticket severity code assigned to tickets auto-created by the email collector from incoming emails.', 'Read in emailcollector/class/emailcollector.class.php:3643 as the default value passed to getDolGlobalString, falling back to dol_getIdFromCode() lookup of the c_ticket_severity dictionary''s ''use_default'' entry if unset.', 'Setting it overrides which ticket severity code is used for tickets created by the email collector, instead of the dictionary''s default severity.', 'String, a valid c_ticket_severity dictionary code.', 0, 0, NULL, 1, 'fbd8168b09a1ff7086c6d0c1ac26edfc8eb8a9797b8a81494e1aff3bf44e338a', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:3643|$tickettocreate->severity_code = (getDolGlobalString(''MAIN_EMAILCOLLECTOR_TICKET_SEVERITY_CODE'', dol_getIdFromCode($this->db, 1, ''c_ticket_severity'', ''use_default'', ''code'', 1)));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAILCOLLECTOR_TICKET_TYPE_CODE', 'string', NULL, 'emailcollector', 'Default ticket type code assigned to tickets auto-created by the email collector from incoming emails.', 'Read in emailcollector/class/emailcollector.class.php:3641 as the default value passed to getDolGlobalString, falling back to dol_getIdFromCode() lookup of the c_ticket_type dictionary''s ''use_default'' entry if unset.', 'Setting it overrides which ticket type code is used for tickets created by the email collector, instead of the dictionary''s default type.', 'String, a valid c_ticket_type dictionary code.', 0, 0, NULL, 1, '30fe0043f051cacad9ac526688ad06529160c26e7cc78474a25b3ccb97aab60d', 'v2', '2026-07-24T07:05:23+00:00', '["emailcollector/class/emailcollector.class.php:3641|$tickettocreate->type_code = (getDolGlobalString(''MAIN_EMAILCOLLECTOR_TICKET_TYPE_CODE'', dol_getIdFromCode($this->db, 1, ''c_ticket_type'', ''use_default'', ''code'', 1)));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAIL_COLLECTOR_ACCEPT_EMOJIS', 'string', NULL, 'emailcollector', 'Controls whether emoji characters are removed from collected email subjects and bodies.', 'In emailcollector/class/emailcollector.class.php at lines 2130, 2139, and 2178, the integer value (defaulting to 1 if unset) is passed to removeEmoji() for subject and body processing. No admin UI write path is present.', 'Setting to 1 (default) retains emojis in collected emails; setting to 0 strips emoji characters from subjects and message text.', 'Integer: passed to removeEmoji(); default 1 = keep emojis; 0 = remove emojis', 1, 0, NULL, 1, '16cfbbea7c52c4eb97cd479aa6d44bb13987e12da772951facb540286c30daa3', 'v2', '2026-04-21T13:50:40+00:00', '["emailcollector/class/emailcollector.class.php:2130|read|$overview[''subject''] = removeEmoji($overview[''subject''], getDolGlobalInt(''MAIN_EMAIL_COLLECTOR_ACCEPT_EMOJIS'', 1));", "emailcollector/class/emailcollector.class.php:2139|read|$overview[0]->subject = removeEmoji($overview[0]->subject, getDolGlobalInt(''MAIN_EMAIL_COLLECTOR_ACCEPT_EMOJIS'', 1));", "emailcollector/class/emailcollector.class.php:2178|read|$messagetext = removeEmoji($messagetext, getDolGlobalInt(''MAIN_EMAIL_COLLECTOR_ACCEPT_EMOJIS'', 1));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAIL_DISABLE_ADD_CONTENT_ENCODING_8BIT', 'bool', NULL, 'core', 'Disables adding the ''Content-Transfer-Encoding: 8bit'' header when building raw SMTP headers for mail-mode emails.', 'In core/class/CMailFile.class.php:1743-1745, the header `Content-Transfer-Encoding: 8bit` is only appended if `!getDolGlobalString("MAIN_EMAIL_DISABLE_ADD_CONTENT_ENCODING_8BIT")`; an inline TODO comment notes ''Seems to be ignored. Header is 7bit once received.''', 'Setting it removes the 8bit Content-Transfer-Encoding header from outgoing mail-mode emails; per the code''s own TODO comment, this header may already be ignored/overridden by the receiving side in practice.', 'Boolean-like: set/non-empty omits the ''Content-Transfer-Encoding: 8bit'' header; unset (default) adds it.', 1, 0, NULL, 1, '237cc9d40bf0774992868b40aab2ced8302ae055edbe13781140563292f86ed7', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/CMailFile.class.php:1743: if (!getDolGlobalString(\"MAIN_EMAIL_DISABLE_ADD_CONTENT_ENCODING_8BIT\")) {", "core/class/CMailFile.class.php:1744: $out .= \"Content-Transfer-Encoding: 8bit\".$this->eol2; // TODO Seems to be ignored. Header is 7bit once received."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAIL_SUPPORT_ACK', 'string', NULL, 'core', 'Enables the ''delivery receipt'' (read acknowledgement) request checkbox on email composition forms.', 'Checked in core/class/html.formmail.class.php:918: if (!empty($this->withdeliveryreceipt) && getDolGlobalInt(''MAIN_EMAIL_SUPPORT_ACK'')) { $out .= $this->getHtmlForDeliveryreceipt(); } — both the form''s withdeliveryreceipt flag and this global must be truthy.', 'When enabled (and the calling form has withdeliveryreceipt set), a delivery-receipt request option is rendered on the email form; if this constant is unset, the delivery-receipt UI is never shown regardless of withdeliveryreceipt.', 'Boolean-like: truthy enables the delivery-receipt UI, acting as a global on/off switch for the feature.', 0, 0, NULL, 1, 'e52326efaef44086737e2c12b9e2611e4132c646591b7a43a500a2e4d8defe9f', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:918: if (!empty($this->withdeliveryreceipt) && getDolGlobalInt(''MAIN_EMAIL_SUPPORT_ACK'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAIL_TEMPLATES_FOR_OBJECT_LINES', 'string', NULL, 'admin', 'Enables editing of email template content for document lines (line-level content_lines field) in the mailing templates admin.', 'Documented at admin/mails_templates.php:186 with the comment ''Set MAIN_EMAIL_TEMPLATES_FOR_OBJECT_LINES to allow edit of template for lines''. Controls visibility of the content_lines field in cemailtemplate.class.php:64 and multiple display branches in admin/mails_templates.php.', 'Enabling this constant exposes the content_lines field for editing in email templates, allowing per-line content customisation; disabling it hides that field.', 'Any truthy value enables line-level template editing; unset or empty disables it.', 0, 0, 'admin/mails_templates.php|admin/mails_templates.php|admin/mails_templates.php|admin/mails_templates.php|admin/mails_templates.php|admin/mails_templates.php|admin/mails_templates.php', 1, '365b8247563cf09f16289c85482ecffca53a6b2a538c84c8cac47c71e5834da9', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails_templates.php:186  // Set MAIN_EMAIL_TEMPLATES_FOR_OBJECT_LINES to allow edit of template for lines", "core/class/cemailtemplate.class.php:64|read|\"content_lines\" => array(\"type\" => \"text\", \"label\" => \"Contentlines\", \"enabled\" => \"getDolGlobalString(''MAIN_EMAIL_TEMPLATES_FOR_OBJECT_LINES'')\", ''position'' => 80, ''notnull'' => 0,", "admin/mails_templates.php:188|check|if (!getDolGlobalString(''MAIN_EMAIL_TEMPLATES_FOR_OBJECT_LINES'')) {", "admin/mails_templates.php:897|check|if (getDolGlobalString(''MAIN_EMAIL_TEMPLATES_FOR_OBJECT_LINES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAIL_USECCC', 'string', NULL, 'core', 'Sets the default BCC (hidden copy) email address added to all outgoing emails.', 'Read in core/tpl/massactions_pre.tpl.php:306, core/tpl/card_presend.tpl.php:429, and comm/mailing/card.php:1353 to populate the withtoccc field of the mail form. The comment in core/class/html.formmail.class.php:1321 confirms the field is shown when this constant is set.', 'Setting this causes all email send forms to pre-populate the BCC field with the configured address, resulting in every outgoing email being silently copied.', 'Empty/not set = no BCC; email address string = that address is added as BCC', 1, 0, NULL, 1, 'ef5b2251833adbb3d6010296392f3c83a4fc445849ac1d2da596663609cec119', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.formmail.class.php:1321  * This information is show when MAIN_EMAIL_USECCC is set.", "core/tpl/massactions_pre.tpl.php:306|read|$formmail->withtoccc = getDolGlobalString(''MAIN_EMAIL_USECCC'');", "core/tpl/card_presend.tpl.php:429|read|$formmail->withtoccc = getDolGlobalString(''MAIN_EMAIL_USECCC'');", "comm/mailing/card.php:1353|read|$formmail->withtoccc = getDolGlobalString(''MAIN_EMAIL_USECCC'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EMAIL_USE_LAYOUT', 'bool', NULL, 'core', 'Enables a ''Fill message with a layout'' helper link in the email composition form, letting users insert a predefined HTML layout into the message body.', 'Read in comm/mailing/card.php:1700 and core/class/html.formmail.class.php:1132/1937, where it''s combined with $formmail->withfckeditor to decide whether to show the layout-insertion link ($showlinktolayout), labelled via langs->trans(''FillMessageWithALayout'').', 'When enabled (and the FCK/rich-text editor is active), a link to insert a predefined layout into the email body is shown on mailing, generic email, and ticket email forms; when disabled, no such link appears.', 'Boolean-like flag (getDolGlobalInt): truthy enables the layout-insertion link.', 0, 0, NULL, 1, 'f8e46d9d073c0160550d4f0f3da5569950174f2b52d61f2762afaad7305e2adc', 'v2', '2026-07-24T07:05:23+00:00', '["comm/mailing/card.php:1700: $showlinktolayout = getDolGlobalInt(''MAIN_EMAIL_USE_LAYOUT'') ? ''emailing'' : '''';", "core/class/html.formmail.class.php:1132: $showlinktolayout = ($formmail->withfckeditor && getDolGlobalInt(''MAIN_EMAIL_USE_LAYOUT'')) ? $formmail->withlayout : '''';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_ACCENT_INSENSITIVE_SEARCH', 'bool', NULL, 'core', 'Makes the select2 combobox client-side search matcher ignore accents (in addition to case) when filtering options.', 'Checked in core/lib/ajax.lib.php:521 with inline comment ''lowercase + remove accents''; when set, the generated JS matcher normalizes both search term and option text via NFD + accent-stripping regex before lowercasing; otherwise it only lowercases (accents kept).', 'Enabling it lets users find select2 options by typing without accents (e.g. ''e'' matches ''é''); the else-branch comment confirms default behavior only lowercases and keeps accents intact.', 'Boolean: truthy value = lowercase + remove accents matcher; falsy/default = lowercase only, accents kept (per inline comments in the code).', 1, 0, NULL, 1, 'c1938f1a86bdebccc79c79f2a3e6c2417abe82f4f80ef55f56ee428ea3ac0b3e', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/ajax.lib.php:521|check|if (getDolGlobalString(''MAIN_ENABLE_ACCENT_INSENSITIVE_SEARCH'')) {\t// lowercase + remove accents", "} else {  // lowercase only (accent kept)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_AJAX_TOOLTIP', 'bool', NULL, 'webportal', 'Enables AJAX-based tooltips across many object classes and pages instead of static tooltips.', 'Toggled via admin/system/perf.php:754/761 and checked in many classes such as opensurvey/class/opensurveysondage.class.php:574, projet/class/task.class.php:1037, salaries/class/paymentsalary.class.php:870, contrat/class/contrat.class.php:2111, and delivery/class/delivery.class.php:806.', 'When enabled, tooltips are rendered via AJAX in the affected object views; the admin/system/perf.php page reports its yes/no state.', NULL, 0, 0, 'admin/system/perf.php|admin/system/perf.php', 1, 'c5c5a18bf0ead5922ce8e0d0870b7e5f663e265b057879da12ed6d6c9214acdd', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalInt(''MAIN_ENABLE_AJAX_TOOLTIP'')) {", "print yn(getDolGlobalInt(''MAIN_ENABLE_AJAX_TOOLTIP''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_DEFAULT_VALUES', 'string', '1', 'admin', 'Enables the default values feature, which pre-fills form fields with administrator-defined defaults.', 'Written (set to 1 or 0) via admin/defaultvalues.php:122-124. Checked in core/lib/functions.lib.php:1135 and user/class/user.class.php:841. Comment at core/lib/functions.lib.php:1125: ''Same if option MAIN_ENABLE_DEFAULT_VALUES is not set''. Also checked in admin/defaultvalues.php:219, 227, 369 to guard the management UI.', 'When enabled (non-empty), Dolibarr pre-fills eligible form fields with the configured defaults. When disabled, default value injection is skipped and the management UI blocks modifications.', '1 = enabled (default values active). 0 or empty = disabled.', 0, 0, 'admin/defaultvalues.php|admin/defaultvalues.php|admin/defaultvalues.php|admin/defaultvalues.php|admin/defaultvalues.php', 1, 'f2c9c7b735e89d55f7e17e79bcb9eacfea0bd0c2f97adb93af0693abf2f5cddb', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:1125  // If we did a click on a field to sort, we do no apply default values. Same if option MAIN_ENABLE_DEFAULT_VALUES is not set", "core/lib/functions.lib.php:1135|check|if (getDolGlobalString(''MAIN_ENABLE_DEFAULT_VALUES'')) {", "admin/defaultvalues.php:122|write|dolibarr_set_const($db, ''MAIN_ENABLE_DEFAULT_VALUES'', 1, ''chaine'', 0, '''', $conf->entity);", "admin/defaultvalues.php:219|check|if (!getDolGlobalString(''MAIN_ENABLE_DEFAULT_VALUES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_EXTERNALMODULES_COMMUNITY', 'bool', NULL, 'admin', 'Enables browsing and installing modules from the community (GitHub) repository in the module administration page.', 'The code comment states: ''MAIN_ENABLE_EXTERNALMODULES_COMMUNITY is 1 if we enabled the community modules'' (admin/modules.php:94). When set, GitHub-sourced modules are fetched (admin/remotestore/class/externalModules.class.php:406) and search includes the GitHub source (admin/modules.php:95).', 'Enabling activates community module discovery from GitHub. Disabling hides community modules from the module list.', '0 or unset = community modules not shown; 1 = community modules enabled', 0, 0, 'admin/modules.php|admin/modules.php|admin/remotestore/class/externalModules.class.php|admin/remotestore/class/externalModules.class.php', 1, '208dee9b3205e04a186267e32fe86c2393aa60ae3729434d6cf9a35fc34e0057', 'v2', '2026-04-21T13:29:58+00:00', '["admin/modules.php:94  // MAIN_ENABLE_EXTERNALMODULES_COMMUNITY is 1 if we enabled the community modules", "admin/modules.php:95|read|$options[''search_source_github''] = getDolGlobalInt(''MAIN_ENABLE_EXTERNALMODULES_COMMUNITY'');", "admin/remotestore/class/externalModules.class.php:406|check|if (!empty($this->githubFileStatus) && getDolGlobalInt(''MAIN_ENABLE_EXTERNALMODULES_COMMUNITY'')) {", "admin/modules.php:1392|check|if (!getDolGlobalString(''MAIN_DISABLE_EXTERNALMODULES_COMMUNITY'') && getDolGlobalInt(''MAIN_ENABLE_EXTERNALMODULES_COMMUNITY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_EXTERNALMODULES_DOLISTORE', 'bool', NULL, 'admin', 'Enables browsing and installing modules from the Dolistore remote repository in the module administration page.', 'The code comment states: ''MAIN_ENABLE_EXTERNALMODULES_DOLISTORE is 1 if we enabled the dolistore modules'' (admin/modules.php:92). When set, the Dolistore API is queried (admin/remotestore/class/externalModules.class.php:389) and search results include Dolistore modules (admin/modules.php:93).', 'Enabling this constant activates Dolistore module browsing and installation. Disabling it (or leaving unset) hides Dolistore modules from the list.', '0 or unset = Dolistore modules not shown; 1 = Dolistore modules enabled', 0, 0, 'admin/modules.php|admin/modules.php|admin/remotestore/class/externalModules.class.php|admin/remotestore/class/externalModules.class.php', 1, '4fa6b4c19c1e78b6e3ffb93298c80ac91217541914b7362315383100b49afe55', 'v2', '2026-04-21T13:29:58+00:00', '["admin/modules.php:92  // MAIN_ENABLE_EXTERNALMODULES_DOLISTORE is 1 if we enabled the dolistore modules", "admin/modules.php:93|read|$options[''search_source_dolistore''] = getDolGlobalInt(''MAIN_ENABLE_EXTERNALMODULES_DOLISTORE'');", "admin/remotestore/class/externalModules.class.php:389|check|if ($this->dolistoreApiStatus > 0 && getDolGlobalInt(''MAIN_ENABLE_EXTERNALMODULES_DOLISTORE'')) {", "admin/modules.php:1359|check|if (!getDolGlobalString(''MAIN_DISABLE_EXTERNALMODULES_DOLISTORE'') && getDolGlobalInt(''MAIN_ENABLE_EXTERNALMODULES_DOLISTORE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_FONT_ROBOTO', 'bool', NULL, 'core', 'Enables loading of the Google Roboto web font (via fonts.gstatic.com/fonts.googleapis.com) in the HTML head.', 'In main.inc.php:1895, when set, Dolibarr prints <link> tags to preconnect and load the Roboto font family from Google Fonts CDN in every page header.', 'Setting it adds external requests to Google''s font CDN on every page load, which pulls in a third-party dependency and network call not present by default.', 'Boolean-like: truthy enables Google Fonts Roboto loading.', 0, 0, NULL, 1, '315d7bd04937845ca568104292315ef529053d9394cc854216035c312b2bd1d3', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:1895|check|if (getDolGlobalString(''MAIN_ENABLE_FONT_ROBOTO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_IMPORT_LINKED_OBJECT_LINES', 'bool', NULL, 'mrp', 'Enables the ''Import lines from linked object'' button on document line sections.', 'Checked in 10 locations across linkedobjectblock templates (e.g. compta/facture/tpl/linkedobjectblock.tpl.php:76, mrp/tpl/linkedobjectblock.tpl.php:74, comm/propal/tpl/linkedobjectblock.tpl.php:66, reception/tpl/linkedobjectblock.tpl.php:70). The button is rendered only when both $showImportButton and this constant are truthy.', 'Enabling this constant activates an import button that allows copying line items from a linked source document into the current document.', 'Non-zero/non-empty = import lines button visible; 0 or unset = button hidden.', 1, 0, NULL, 1, '503842eee479dd46c1242efd457ac8f4d35f7644455a67ad84f6f25132544655', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/tpl/linkedobjectblock.tpl.php:76|check|if (!empty($showImportButton) && getDolGlobalString(''MAIN_ENABLE_IMPORT_LINKED_OBJECT_LINES'')) {", "mrp/tpl/linkedobjectblock.tpl.php:74|check|if (!empty($showImportButton) && getDolGlobalInt(''MAIN_ENABLE_IMPORT_LINKED_OBJECT_LINES'')) {", "comm/propal/tpl/linkedobjectblock.tpl.php:66|check|if (!empty($showImportButton) && getDolGlobalInt(''MAIN_ENABLE_IMPORT_LINKED_OBJECT_LINES'')) {", "reception/tpl/linkedobjectblock.tpl.php:70|check|<?php if (!empty($showImportButton) && getDolGlobalInt(''MAIN_ENABLE_IMPORT_LINKED_OBJECT_LINES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_LOGINS_PRIVACY', 'bool', NULL, 'user', 'Controls visibility of user login date information in user lists and profile pages.', 'Checked in user/card.php and user/list.php across 9 occurrences. When set to 0, last/previous login dates are shown in user lists and on card pages. When set to 1, only the current user can see their own login dates.', 'Setting to 0 exposes login date columns to all authorized viewers; setting to 1 restricts login date visibility so each user can only see their own.', '0 = login dates visible to all; 1 = login dates visible only to the user themselves.', 1, 0, NULL, 1, '818e9f1e51af69b92aaba63277166e18017cb3708f117af7f801ea8205615950', 'v2', '2026-04-21T13:50:40+00:00', '["user/card.php:2174|check|if ((getDolGlobalInt(''MAIN_ENABLE_LOGINS_PRIVACY'') == 0) || (getDolGlobalInt(''MAIN_ENABLE_LOGINS_PRIVACY'') == 1 && $object->id == $user->id)) {", "user/list.php:1382|check|if (!empty($arrayfields[''u.datelastlogin''][''checked'']) && getDolGlobalInt(''MAIN_ENABLE_LOGINS_PRIVACY'') == 0) {", "user/list.php:162|check|if (getDolGlobalInt(''MAIN_ENABLE_LOGINS_PRIVACY'') == 0) {", "user/list.php:853|check|if (!empty($arrayfields[''u.datelastlogin''][''checked'']) && getDolGlobalInt(''MAIN_ENABLE_LOGINS_PRIVACY'') == 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_LOG_INLINE_HTML', 'bool', NULL, 'core', 'Enables inline HTML log rendering triggered by the ''log'' GET parameter; marked as deprecated in source comments.', 'Checked in core/lib/functions.lib.php:2845 with GETPOSTINT(''log''). A comment at line 2843 marks it as TODO for removal: ''MAIN_ENABLE_LOG_INLINE_HTML should be deprecated and use a log handler dedicated to HTML output''.', 'Setting this constant enables a legacy inline HTML log mechanism when the log parameter is passed. It should not be used in new deployments as it is flagged for deprecation.', 'Non-empty = inline HTML log active with ?log parameter; absent/empty = disabled. //TODO: Remove this. MAIN_ENABLE_LOG_INLINE_HTML should be deprecated and use a log handler dedicated to HTML output.', 1, 0, NULL, 1, '6728cb40f80076a0d9b4f9c00c50d24b3f0ad79ad854b4c173c48024ddd41efb', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:2843  //TODO: Remove this. MAIN_ENABLE_LOG_INLINE_HTML should be deprecated and use a log handler dedicated to HTML output", "core/lib/functions.lib.php:2845|check|if (getDolGlobalString(''MAIN_ENABLE_LOG_INLINE_HTML'') && GETPOSTINT(\"log\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_LOG_TO_HTML', 'string', '0', 'core', 'Enables in-page HTML log output during install and upgrade procedures, and optionally during normal requests when the logtohtml request parameter is present.', 'Set to 1 during install/upgrade in install/step5.php:263, install/step5.php:464, install/inc.php:262, install/upgrade2.php:208, install/check.php:444, install/repair.php:328, install/upgrade2.php:317. Checked at core/lib/functions.lib.php:2834 with GETPOST(''logtohtml'').', 'When active, log messages are accumulated and rendered inline in the HTML page. This is enabled automatically during install/upgrade and can be triggered during normal operation via the logtohtml request parameter.', '1 = log to HTML output enabled; 0 or absent = disabled. Default: ''0''.', 1, 1, NULL, 1, '4fba130181d82ab1f605cb4105171d9f8cd5682e3a9f1697c2320ff8be3a1061', 'v2', '2026-04-21T13:29:58+00:00', '["install/step5.php:263|write|$conf->global->MAIN_ENABLE_LOG_TO_HTML = 1;", "install/upgrade2.php:317|write|$conf->global->MAIN_ENABLE_LOG_TO_HTML = 1;\t\t// Add also log into conf->logbuffer.", "core/lib/functions.lib.php:2834|check|if ((!empty($_REQUEST[''logtohtml'']) && getDolGlobalString(''MAIN_ENABLE_LOG_TO_HTML''))"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_MULTISELECT_TYPE', 'bool', NULL, 'admin', 'Enables a multiselect widget for choosing agenda/event types instead of a single-select.', 'Set via admin/agenda_other.php and checked in admin/agenda_other.php:409 and core/lib/agenda.lib.php:97, the latter commented ''We use an option here because it adds bugs when used on agenda page "peruser" and "list"''.', 'When enabled, agenda event type selection uses a multiselect control; the code comment notes this option exists because using it unconditionally caused bugs on certain agenda views.', NULL, 0, 0, 'admin/agenda_other.php', 1, 'ca122e085c9ab0155afac8bc6fda77ae318d42e0d199202c0bcdcea7f48e802e', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_ENABLE_MULTISELECT_TYPE'')) {", "if (getDolGlobalString(''MAIN_ENABLE_MULTISELECT_TYPE'')) {     // We use an option here because it adds bugs when used on agenda page \"peruser\" and \"list\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_OVERWRITE_TRANSLATION', 'string', '1', 'admin', 'Enables the custom translation overwrite feature, allowing administrators to define per-entity translation overrides through the admin UI.', 'Configured via admin/translation.php (UI writes at lines 120 and 122). Checked at multiple points (lines 234, 241, 362, 366) to gate editing and display of custom translations. Also checked in core/class/translate.class.php:538 to apply overrides during translation loading.', 'When enabled (default ''1''), custom translation overrides can be managed via admin/translation.php and are applied at runtime. When disabled, overrides are not applied and the UI restricts editing.', '1 to enable overwrite translation (default); 0 to disable.', 0, 0, 'admin/translation.php|admin/translation.php|admin/translation.php|admin/translation.php|admin/translation.php|admin/translation.php|admin/translation.php', 1, 'f20318a1b7af3300058b58cc1191a8b183c9266fb21a9909955259bdd09f2bc1', 'v2', '2026-04-21T13:50:40+00:00', '["admin/translation.php:120|write|dolibarr_set_const($db, ''MAIN_ENABLE_OVERWRITE_TRANSLATION'', 1, ''chaine'', 0, '''', $conf->entity);", "admin/translation.php:122|write|dolibarr_set_const($db, ''MAIN_ENABLE_OVERWRITE_TRANSLATION'', 0, ''chaine'', 0, '''', $conf->entity);", "core/class/translate.class.php:538|check|if (!$found && getDolGlobalString(''MAIN_ENABLE_OVERWRITE_TRANSLATION'')) {", "admin/translation.php:234|check|if (!getDolGlobalString(''MAIN_ENABLE_OVERWRITE_TRANSLATION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ENABLE_PRODUCTS_CONTACTS_TAB', 'bool', NULL, 'core', 'Enables display of a ''Contacts/Addresses'' tab on product/service cards.', 'In core/lib/product.lib.php:175, this bool gates whether a ContactsAddresses tab (linking to product/contact.php) is added to the product or service''s tab list, showing the count of internal+external contacts linked to the object.', 'Enabling it adds a Contacts/Addresses tab to product and service cards, showing linked contacts; unset/false hides that tab.', 'true/1 = show Contacts/Addresses tab on products/services; false/unset (default) = tab hidden.', 1, 0, NULL, 1, '82a2723c2139a797ca7c6ba73caf2f7d4ca355a9e611e1fa881632eed1b07505', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/product.lib.php:175|check|if (getDolGlobalString(''MAIN_ENABLE_PRODUCTS_CONTACTS_TAB'')) {", "core/lib/product.lib.php:183: $head[$h][1] = $langs->trans(\"ContactsAddresses\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXEC_USE_POPEN', 'bool', NULL, 'admin', 'Selects the PHP execution method used for shell commands: popen (method 2) instead of exec (method 1).', 'Configurable via admin/system/security.php. Read in admin/system/security.php line 67 (defaulting to 1), described in line 234 as ''exec or popen can be used depending on MAIN_EXEC_USE_POPEN option''. Used in includes/odtphp/odf.php line 888 (''1 or 2''), core/class/utils.class.php line 441, and admin/tools/dolibarr_export.php line 301.', 'Enabling this constant switches shell execution from exec() to popen(), which is required on some server configurations where exec() is disabled. The admin security page documents the current setting.', '1 = popen used; 0 or absent = exec used. From odf.php:888: $execmethod = (getDolGlobalString(''MAIN_EXEC_USE_POPEN'') ? 2 : 1); // 1 or 2.', 0, 0, 'admin/tools/dolibarr_export.php|admin/tools/dolibarr_export.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php', 1, 'f7506cbc2f7396f159a24042328a4c4223c967352bfed027eba607df9451c954', 'v2', '2026-04-21T13:29:58+00:00', '["admin/system/security.php:234|read|print ''<span class=\"opacitymedium\" title=\"exec or popen can be used depending on MAIN_EXEC_USE_POPEN option, currently to ''.getDolGlobalInt(''MAIN_EXEC_USE_POPEN'').''\">''", "includes/odtphp/odf.php:888|read|$execmethod = (getDolGlobalString(''MAIN_EXEC_USE_POPEN'') ? 2 : 1);\t// 1 or 2", "admin/tools/dolibarr_export.php:301|check|if (getDolGlobalString(''MAIN_EXEC_USE_POPEN'')) {", "admin/system/security.php:67|read|$execmethod = getDolGlobalInt(''MAIN_EXEC_USE_POPEN'', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXPENSEREPORT_COMBINE_GRAPH_STAT', 'string', NULL, 'expensereport', 'Sets the ''combine'' threshold ratio used to group small slices of the expense-report status pie chart into an ''other'' category.', 'Read in expensereport/index.php:177 where DolGraph::$combine is set to this value if defined, otherwise defaults to 0.05 (5%).', 'Increasing the value groups more small categories into a combined slice on the pie chart; decreasing it shows more categories separately. Value is used directly as DolGraph''s combine ratio.', 'Numeric ratio (e.g. 0.05 = 5%) passed to DolGraph->combine; default when unset is 0.05.', 0, 0, NULL, 1, 'cd5cd01138f5a5b2168ac8d06d3c66956fc17c2469054c048887657b07e36a57', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/index.php:177|read|$dolgraph->combine = !getDolGlobalString(''MAIN_EXPENSEREPORT_COMBINE_GRAPH_STAT'') ? 0.05 : $conf->global->MAIN_EXPENSEREPORT_COMBINE_GRAPH_STAT;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXPENSE_APPLY_ENTIRE_OFFSET', 'string', NULL, 'expensereport', 'Controls whether the full yearly mileage (''ik'') offset is applied at once, instead of prorating it over 12 months, when computing expense report mileage costs.', 'Checked in expensereport/class/expensereport.class.php:2178: `if (getDolGlobalString(''MAIN_EXPENSE_APPLY_ENTIRE_OFFSET'')) { $ikoffset = $range->ikoffset; } else { $ikoffset = $range->ikoffset / 12; // The amount of offset is a global value for the year }`.', 'Enabling it makes the mileage-rate offset ($range->ikoffset) applied in full rather than divided by 12, changing the computed mileage expense amount.', 'Boolean-like: truthy applies the full-year ikoffset value; falsy (default) divides ikoffset by 12.', 0, 0, NULL, 1, '5daef874d08097dcd007db1c4fab0e649fc76c33fbe21d0201f3d7fc2a0a8346', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/class/expensereport.class.php:2178: if (getDolGlobalString(''MAIN_EXPENSE_APPLY_ENTIRE_OFFSET'')) {", "expensereport/class/expensereport.class.php:2179: $ikoffset = $range->ikoffset;", "expensereport/class/expensereport.class.php:2181: $ikoffset = $range->ikoffset / 12; // The amount of offset is a global value for the year"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTERNAL_MAIL_SPF_STRING_TO_ADD', 'string', NULL, 'admin', 'Provides the SPF include string to add for the platform when Dolibarr sends mail via the PHP mail() method, shown in a setup warning message.', 'Used at admin/mails.php:1060, inline commented ''Not defined by default. Depend on platform. List of string to add in SPF if the setup use the mail method. Example include:sendgrid.net include:spf.mydomain.com''. Set via conf.php/database global, no admin UI form field found for it directly.', 'When set, the email setup test page (admin/mails.php, testsetup action) shows a warning telling the admin to add this SPF include string to their domain''s DNS records.', 'String: SPF include directive, e.g. ''include:sendgrid.net include:spf.mydomain.com''. Not defined by default.', 1, 0, 'admin/mails.php', 1, 'fb77dbbf8295ca237fe6f8c62e446b88624102526bd329de6c7c02c9736342c7', 'v2', '2026-07-24T07:05:23+00:00', '["admin/mails.php:1060|check|if (getDolGlobalString(''MAIN_EXTERNAL_MAIL_SPF_STRING_TO_ADD'')) {\t// Not defined by default. Depend on platform.", "// List of string to add in SPF if the setup use the mail method. Example ''include:sendgrid.net include:spf.mydomain.com''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTERNAL_SMTP_CLIENT_IP_ADDRESS', 'string', NULL, 'admin', 'Stores the list of IP addresses from which emails are sent, used for display and SPF diagnostics in the mail admin page.', 'Holds a comma-separated list of IP addresses (or a URL) representing the server''s outgoing mail IPs. The comment states: ''MAIN_EXTERNAL_SMTP_CLIENT_IP_ADDRESS is list of IPs where email is sent from. Example: 1.2.3.4, [aaaa:bbbb:cccc:dddd].'' A second comment notes it can also be a URL to dynamically detect the public IP. Configured via admin/mails.php.', 'When set, admin/mails.php explodes the value by comma and displays each IP; changing or clearing it affects which IPs are shown in the SPF diagnostic section.', 'Comma-separated IP addresses, e.g. ''1.2.3.4, [aaaa:bbbb:cccc:dddd]''; or a URL for dynamic detection. Not defined by default.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php', 1, '20c9e5458d9fb4fd835932d828fc63ee9aa1a7832cc7f9a30c8a1ce6420e05a7', 'v2', '2026-04-21T13:50:40+00:00', '["// MAIN_EXTERNAL_SMTP_CLIENT_IP_ADDRESS is list of IPs where email is sent from. Example: ''1.2.3.4, [aaaa:bbbb:cccc:dddd]''.", "// If MAIN_EXTERNAL_SMTP_CLIENT_IP_ADDRESS is an URL to get/show the public IP/name of server detected dynamically", "admin/mails.php:1079|read|$arrayipstoshow = explode('','', getDolGlobalString(''MAIN_EXTERNAL_SMTP_CLIENT_IP_ADDRESS''));", "admin/mails.php:1076|check|if (getDolGlobalString(''MAIN_EXTERNAL_SMTP_CLIENT_IP_ADDRESS'')) {\t// Not defined by default. Depend on platform."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTERNAL_SMTP_SPF_STRING_TO_ADD', 'string', NULL, 'admin', 'Provides the SPF include string to add when Dolibarr is configured to send mail via SMTP/SMTPS, shown in a setup warning message.', 'Used at admin/mails.php:1072-1074, commented ''Should be required only if you have preset the Dolibarr to use your own SMTP and you want to warn users to update their domain name to match your SMTP server'' and ''List of string to add in SPF if we use the smtp method. Example include:spf.mydomain.com''.', 'When set, the mail setup test page appends a WarningPHPMailSPF message containing this string, prompting the admin to update SPF DNS records for the SMTP server''s domain.', 'String: SPF include directive, e.g. ''include:spf.mydomain.com''.', 1, 0, 'admin/mails.php|admin/mails.php', 1, '1c9c19cc86605f8a2e0852f739e413ead4bccb5d71ded48e9c44e9640b790b38', 'v2', '2026-07-24T07:05:23+00:00', '["admin/mails.php:1072|check|if (getDolGlobalString(''MAIN_EXTERNAL_SMTP_SPF_STRING_TO_ADD'')) {\t// Should be required only if you have preset the Dolibarr to use your own SMTP", "// List of string to add in SPF if we use the smtp method. Example ''include:spf.mydomain.com''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTRAFIELDS_CODE_AUTOFILL_DISABLED', 'bool', NULL, 'core', 'Disables the JS autofill of the extrafield ''code'' from the field label when creating an extrafield in admin.', 'Checked in core/tpl/admin_extrafields_add.tpl.php:164; when not set, a jQuery keyup handler auto-generates the #attrname value from the #label text.', 'Setting it disables the automatic slug-like generation of the extrafield technical name from its label, requiring manual entry in the admin extrafield-creation form.', 'Boolean-like: true/1 disables the autofill behavior (inferred from the negated if-condition wrapping the JS handler).', 0, 0, NULL, 1, 'cd94fe5d2aa0a736f0e5293542d7cad5e86f66b7d0dab67712e81c0daa8a0b2b', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/admin_extrafields_add.tpl.php:164|check|<?php if (!getDolGlobalInt(''MAIN_EXTRAFIELDS_CODE_AUTOFILL_DISABLED'')) : ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTRAFIELDS_DISABLED', 'bool', NULL, 'comm', 'Globally disables extra fields (custom attributes) processing across all modules.', 'When set, extra field processing is skipped in reception, expedition, mailing, and other modules across at least 14 occurrences in multiple files. Checked in reception/class/reception.class.php:1021, comm/mailing/class/advtargetemailing.class.php:614, and expedition/class/expedition.class.php:1352 among others.', 'Enabling this constant prevents extra fields from being saved or displayed throughout Dolibarr, effectively disabling all custom attribute functionality.', '0 or unset = extra fields enabled; non-empty = extra fields disabled', 1, 0, NULL, 1, '56d0507c44c41f80c7317576ccf31720913a73d43685d041443eb65492f5e510', 'v2', '2026-04-21T11:16:15+00:00', '["reception/class/reception.class.php:1021|check|if (!getDolGlobalInt(''MAIN_EXTRAFIELDS_DISABLED'') && is_array($array_options) && count($array_options) > 0) {", "comm/mailing/class/advtargetemailing.class.php:614|check|if (!getDolGlobalString(''MAIN_EXTRAFIELDS_DISABLED'')) {", "expedition/class/expedition.class.php:1352|check|if (!getDolGlobalString(''MAIN_EXTRAFIELDS_DISABLED'') && is_array($array_options) && count($array_options) > 0) { // For avoid conflicts if trigger used"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTRAFIELDS_DISABLE_SELECT2', 'bool', NULL, 'core', 'Disables the select2 JS enhancement on extrafield multiselect/select/radio/checkbox form widgets.', 'Checked in core/class/fields/checkboxfield.class.php:83, sellistfield.class.php:68, selectfield.class.php:69, radiofield.class.php:69, chkbxlstfield.class.php:69/98, and core/class/commonobject.class.php:8138/8171, always combined with a check on $conf->use_javascript_ajax.', 'When enabled, extrafield select-type widgets do not get the select2 enhancement even if JS/AJAX is active.', NULL, 1, 0, NULL, 1, 'bb62282102d451d5263b95b2c898da8e62aaa460945e58f3385a74eccbb7395d', 'v2', '2026-07-24T06:41:12+00:00', '["if (!empty($conf->use_javascript_ajax) && !getDolGlobalString(''MAIN_EXTRAFIELDS_DISABLE_SELECT2'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTRAFIELDS_ENABLE_NEW_SELECT2', 'bool', NULL, 'core', 'Enables a newer select2 implementation for extrafields of type sellist.', 'Checked in core/class/extrafields.class.php at lines 1490, 1524, 1812, 1856, and core/class/fields/sellistfield.class.php:100, the latter combined with $conf->use_javascript_ajax.', 'When enabled, the newer select2 rendering path is used for sellist-type extrafields instead of the legacy one.', NULL, 1, 0, NULL, 1, '72dbf7ec2b545a7034252082eb16420346123f8d59e5b45fb8112d9f32d98b21', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_EXTRAFIELDS_ENABLE_NEW_SELECT2'')) {", "if (!empty($conf->use_javascript_ajax) && getDolGlobalString(''MAIN_EXTRAFIELDS_ENABLE_NEW_SELECT2'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTRAFIELDS_LIMIT_SELLIST_SQL', 'string', NULL, 'core', 'Sets the SQL LIMIT applied to extrafield select-list (sellist) queries.', 'Used in core/class/commonobject.class.php:8260, core/class/extrafields.class.php:1678, and core/class/fields/commonsellistfield.class.php:316 to cap the number of rows returned in sellist dropdown queries. Defaults to 1000.', 'Lowering the limit reduces the number of options shown in sellist extrafield dropdowns; raising it allows more results at the cost of potentially larger queries.', 'Integer (default: 1000)', 1, 0, NULL, 1, 'd111b1b86ceabb461c396c964c59728ac8695f20ab8917562ac9133e7f8ceba4', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:8260|read|$sql .= '' LIMIT '' . getDolGlobalInt(''MAIN_EXTRAFIELDS_LIMIT_SELLIST_SQL'', 1000);", "core/class/extrafields.class.php:1678|read|$sql .= '' LIMIT '' . getDolGlobalInt(''MAIN_EXTRAFIELDS_LIMIT_SELLIST_SQL'', 1000);", "core/class/fields/commonsellistfield.class.php:316|read|$limit = getDolGlobalInt(''MAIN_EXTRAFIELDS_LIMIT_SELLIST_SQL'', $fieldInfos->optionsSqlLimit ?? 1000);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTRAFIELDS_USE_TWO_COLUMS', 'bool', NULL, 'core', 'Displays object extrafields in a two-column layout on card views instead of a single column.', 'Checked in core/class/commonobject.class.php:9739 inside the extrafields rendering loop: `if (getDolGlobalString(''MAIN_EXTRAFIELDS_USE_TWO_COLUMS'') && ($e % 2) == 0) { $colspan = 0; }`, applied only when `$display_type == ''card''`.', 'When set, extrafields on card-type views are laid out two per row (colspan reset every second even-indexed field) instead of the default single-column stacked layout.', 'Truthy/falsy flag; no enumerated values in payload.', 1, 0, NULL, 1, '063827bee5f5f82266e907c1d3f9238bf2fb1c968d95f7f5fa4cea67b2e1fa57', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonobject.class.php:9739|check|if (getDolGlobalString(''MAIN_EXTRAFIELDS_USE_TWO_COLUMS'') && ($e % 2) == 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_EXTRALANGUAGES_DISABLED', 'bool', NULL, 'core', 'Disables the extra languages (multi-language field values) feature across the application.', 'Checked in core/class/commonobject.class.php at lines 7298 and 7758 to skip extra-language processing, and in societe/class/societe.class.php:1881 to skip the trigger that saves extra-language values. No admin UI write found; HIDDEN_GUESS is 1.', 'When enabled, extra-language field values are not loaded, saved, or processed, preventing conflicts if the feature causes issues with certain triggers.', 'Any non-empty value = feature disabled; empty = extra languages enabled', 1, 0, NULL, 1, 'e331743ca59e2b859180c4f5e770079108fe55c7e547a3237d99ec4ebce92570', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/commonobject.class.php:7758|check|if (getDolGlobalString(''MAIN_EXTRALANGUAGES_DISABLED'')) {", "core/class/commonobject.class.php:7298|check|if (getDolGlobalString(''MAIN_EXTRALANGUAGES_DISABLED'')) {", "societe/class/societe.class.php:1881|check|if (!$error && !getDolGlobalString(''MAIN_EXTRALANGUAGES_DISABLED'')) { // For avoid conflicts if trigger used"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FAKE_EINVOICE_MODULE_FOUND', 'string', NULL, 'admin', 'Debug/testing flag that makes the admin dashboard''s e-invoicing setup section behave as if an e-invoice module were already installed and enabled.', 'Read in admin/index.php:199, ORed with the real $modulefound detection result to decide which message (''AnEInvoiceModuleHasBeenEnabled'' vs ''SetupDescriptionEInvoice'') to display in the e-invoice setup section of the admin home page.', 'Enabling it forces the admin index page to display the ''an e-invoice module has been enabled'' message even if no such module is actually installed, useful for testing that UI branch.', 'Boolean-like: enabled = treat as if an e-invoice module was found (display the ''enabled'' message); unset/0 = use the real detection.', 0, 0, 'admin/index.php', 1, '1a4cbc6724de7807928e1eb46c21cbd908b738e1b309af6b75c686b22e7207c8', 'v2', '2026-07-24T07:05:23+00:00', '["admin/index.php:199: if ($modulefound || getDolGlobalString(''MAIN_FAKE_EINVOICE_MODULE_FOUND'')) {", "admin/index.php:200: print ''<br><br>''.$langs->trans(\"AnEInvoiceModuleHasBeenEnabled\", $mysoc->country_code);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FAVICON_URL', 'string', NULL, 'core', 'Specifies a custom URL for the browser favicon, overriding the default Dolibarr favicon.', 'Checked and read in both main.inc.php:1729-1730 and core/lib/security2.lib.php:301-302 to set the $favicon variable used when rendering the HTML head.', 'Setting this replaces the default favicon with the URL provided; unsetting it reverts to the default Dolibarr favicon.', 'Any valid URL string pointing to a favicon image; empty/unset = default Dolibarr favicon is used', 1, 0, NULL, 1, '9be31072cbd520f775562320277b9de4b205df60f9c32ea73f92a96a5e0f13eb', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1729|check|if (getDolGlobalString(''MAIN_FAVICON_URL'')) {", "main.inc.php:1730|read|$favicon = getDolGlobalString(''MAIN_FAVICON_URL'');", "core/lib/security2.lib.php:302|read|$favicon = getDolGlobalString(''MAIN_FAVICON_URL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FEATUREES_LEVEL', 'string', NULL, 'core', 'Apparent typo of MAIN_FEATURES_LEVEL; used only in extrafields admin templates to show/hide an extra help line for sellist/chkbxlst extrafield parameters.', 'Found in core/tpl/admin_extrafields_add.tpl.php:208-209 and core/tpl/admin_extrafields_edit.tpl.php:281-282, all reading getDolGlobalInt(''MAIN_FEATUREES_LEVEL'') (with the extra ''E'') to decide whether to append the ''ExtrafieldParamHelpsellist2'' help text. The correctly-spelled MAIN_FEATURES_LEVEL is a different, widely-used and admin-UI-wired constant found across ~35 admin/*.php files (e.g. admin/modules.php) controlling display of development/experimental modules; MAIN_FEATUREES_LEVEL is not the same setting and has no admin UI writing it under this exact name.', 'Setting the double-E spelled MAIN_FEATUREES_LEVEL to a value > 0 shows an extra help line (''ExtrafieldParamHelpsellist2'') on the sellist/chkbxlst extrafield creation/edit forms; it does not affect module visibility level (that is controlled by the correctly-spelled MAIN_FEATURES_LEVEL).', 'Integer via getDolGlobalInt; > 0 shows the extra help text line, otherwise hidden. Likely intended to alias MAIN_FEATURES_LEVEL but misspelled in these 4 occurrences.', 1, 0, NULL, 1, 'e9a9306b03f847fd86b85227c24d32a05ea6fb29063dcbf443980722ea367f45', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/admin_extrafields_edit.tpl.php:281|getDolGlobalInt(''MAIN_FEATUREES_LEVEL'') > 0 ? ''<br>''.$langs->trans(\"ExtrafieldParamHelpsellist2\") : ''''", "core/lib/admin.lib.php:1467|if ($objMod->version == ''development'' && getDolGlobalInt(''MAIN_FEATURES_LEVEL'') < 2 && !getDolGlobalString($const_name)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FEATURES_LEVEL', 'string', '0', 'admin', 'Controls the minimum maturity level of features/modules shown or enabled in the application (stable/experimental/development).', 'Default ''0''. Checked extensively (276 occurrences) such as projet/admin/project.php:349/352 and admin/payment.php:190/193, comparing module->version against thresholds (''development'' needs level >= 2, ''experimental'' needs level >= 1). Documented at core/class/conf.class.php:1029 and comm/mailing/advtargetemailing.php:24 (''Visible when MAIN_FEATURES_LEVEL is 1'').', 'Raising this value exposes modules/pages/menus marked as ''experimental'' (level 1) or ''development'' (level 2) that are hidden at the default level.', '0 = stable only (default); 1 = also show experimental features; 2 = also show development features', 0, 0, 'projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|admin/payment.php|admin/payment.php|admin/syslog.php|admin/syslog.php|admin/syslog.php|admin/ticket.php|admin/ticket.php|admin/ticket.php|admin/ticket.php|admin/bom.php|admin/bom.php|admin/bom.php|admin/bom.php|admin/bom.php|admin/user.php|admin/user.php|admin/expensereport.php|admin/expensereport.php|admin/expensereport.php|admin/expensereport.php|supplier_proposal/admin/supplier_proposal.php|supplier_proposal/admin/supplier_proposal.php|supplier_proposal/admin/supplier_proposal.php|supplier_proposal/admin/supplier_proposal.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.p