INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FEATURE_TO_SHOW_TOP_MENU_URL_IN_FRAME', 'bool', NULL, 'admin', 'Enables experimental support for rendering top-menu URLs in an iframe within the admin menu editor.', 'Checked at admin/menus/edit.php:416 and :550 (where it is also combined with a check that the menu type is ''top''). A reference also exists in core/class/conf.class.php:1022.', 'Enabling this constant activates the iframe rendering path for top-menu URLs in the menu editor; disabling it keeps the standard link behavior.', 'Empty/unset = iframe rendering disabled; any truthy value = top-menu URLs rendered in frame.', 0, 0, 'admin/menus/edit.php|admin/menus/edit.php', 1, '38d0c5b1e8f85b78452de8baefa5c1281e9a0615c33986af35b182c786e8569e', 'v2', '2026-04-21T13:50:40+00:00', '["admin/menus/edit.php:416|check|if (getDolGlobalString(\"MAIN_FEATURE_TO_SHOW_TOP_MENU_URL_IN_FRAME\")) {", "admin/menus/edit.php:550|check|if (getDolGlobalString(\"MAIN_FEATURE_TO_SHOW_TOP_MENU_URL_IN_FRAME\") && $menu->type == ''top'') {", "core/class/conf.class.php:1022  // MAIN_FEATURE_TO_SHOW_TOP_MENU_URL_IN_FRAME"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FICHINTER_EXPORT_CACHE', 'string', NULL, 'public', 'Sets a cache delay for the intervention (fichinter) agenda export (ICS/XCal) feed.', 'Set via admin/fichinter_xcal.php (read at line 57, written at line 81 with dolibarr_set_const) and consumed in public/fichinter/agendaexport.php:251/252 as $cachedelay.', 'When set, the public fichinter agenda export uses this value as the cache delay for the exported feed.', NULL, 0, 0, 'admin/fichinter_xcal.php|admin/fichinter_xcal.php', 1, '79f4233bebd804193debd78de783e45dc6349ad854678f8f2ed0542ff96b46ee', 'v2', '2026-07-24T06:41:12+00:00', '["$MAIN_FICHINTER_EXPORT_CACHE = getDolGlobalInt(''MAIN_FICHINTER_EXPORT_CACHE'');", "if (getDolGlobalString(''MAIN_FICHINTER_EXPORT_CACHE'')) {", "$cachedelay = getDolGlobalString(''MAIN_FICHINTER_EXPORT_CACHE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FICHINTER_EXPORT_FIX_TZ', 'string', NULL, 'public', 'Applies a fixed timezone offset (in hours) to all dates exported in the fichinter iCal/vCal feed.', 'Written in admin/fichinter_xcal.php:82; applied as a subtraction in hours at public/fichinter/agendaexport.php:584 and :630-631 for start, created, and modified dates. The comment at :588 confirms the pattern: ''// $dateend = $db->jdate($obj->datee) - ((int) getDolGlobalString(''MAIN_FICHINTER_EXPORT_FIX_TZ'', 0) * 3600);''.', 'Setting an integer value shifts all exported event timestamps by that many hours. A value of 0 or empty applies no offset.', '0 or empty = no timezone correction; integer (positive or negative) = number of hours to subtract from exported event timestamps', 0, 0, 'admin/fichinter_xcal.php|admin/fichinter_xcal.php', 1, '140e615777c286c1e182721f021f20f6cc7e6562ab7c94f6d6043438e45596ac', 'v2', '2026-04-21T13:50:40+00:00', '["public/fichinter/agendaexport.php:588  // \t$dateend = $db->jdate($obj->datee) - ((int) getDolGlobalString(''MAIN_FICHINTER_EXPORT_FIX_TZ'', 0) * 3600);", "public/fichinter/agendaexport.php:584|read|$datestart = $db->jdate($obj->date) - ((int) getDolGlobalString(''MAIN_FICHINTER_EXPORT_FIX_TZ'', 0) * 3600);", "public/fichinter/agendaexport.php:630|read|$event[''created''] = $db->jdate($obj->datec) - ((int) getDolGlobalString(''MAIN_FICHINTER_EXPORT_FIX_TZ'', 0) * 3600);", "admin/fichinter_xcal.php:82|write|$i += dolibarr_set_const($db, ''MAIN_FICHINTER_EXPORT_FIX_TZ'', $MAIN_FICHINTER_EXPORT_FIX_TZ, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FICHINTER_EXPORT_PAST_DELAY', 'string', NULL, 'admin', 'Sets the maximum age in days of interventions included in the public iCal/vCal export feed, defaulting to 100 days.', 'Written in admin/fichinter_xcal.php:80 and defaulted to 100 at :100 and public/fichinter/agendaexport.php:81; used at agendaexport.php:120 as the ''notolderthan'' filter. The comment at admin/fichinter_xcal.php:243 shows: ''// $defaultnotolderthan = getDolGlobalString(''MAIN_FICHINTER_EXPORT_PAST_DELAY'', 100);''.', 'Increasing the value includes older interventions in the calendar feed; decreasing it limits the feed to more recent entries. Default is 100 days when not set.', 'Integer number of days; empty or 0 triggers default of 100 days', 0, 0, 'admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php', 1, '56acb89e95cb5b88c0b3740d45ffb081309b13066c1921bff9cd89c2a1053a90', 'v2', '2026-04-21T13:50:40+00:00', '["admin/fichinter_xcal.php:243  // $defaultnotolderthan = getDolGlobalString(''MAIN_FICHINTER_EXPORT_PAST_DELAY'', 100);", "admin/fichinter_xcal.php:100|write|$conf->global->MAIN_FICHINTER_EXPORT_PAST_DELAY = 100;", "public/fichinter/agendaexport.php:120|read|$filters[''notolderthan''] = getDolGlobalString(''MAIN_FICHINTER_EXPORT_PAST_DELAY'', 100);", "public/fichinter/agendaexport.php:81|write|$conf->global->MAIN_FICHINTER_EXPORT_PAST_DELAY = 100; // default limit"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FICHINTER_XCAL_EXPORTKEY', 'string', NULL, 'admin', 'Defines the secret export key required to access the public iCal/vCal feed for interventions (fichinter).', 'Written and read extensively in admin/fichinter_xcal.php (19 occurrences); the key is embedded in the public export URL as the ''exportkey'' parameter used to authenticate access to agendaexport.php.', 'Changing this key invalidates existing calendar subscription URLs. Leaving it empty prevents authenticated access to the public calendar feed.', 'Empty = key not defined (export URL shows placeholder ''...''); any string = the secret key embedded in the public export URL', 0, 0, 'admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php|admin/fichinter_xcal.php', 1, '110dd4ab8fcde48687bac0c5cf91e2f7fc5ff8db28230890d25f64bf38d5cbc8', 'v2', '2026-04-21T13:50:40+00:00', '["admin/fichinter_xcal.php:79|write|$i += dolibarr_set_const($db, ''MAIN_FICHINTER_XCAL_EXPORTKEY'', $MAIN_FICHINTER_XCAL_EXPORTKEY, ''chaine'', 0, '''', $conf->entity);", "admin/fichinter_xcal.php:198|read|$urlvcal = ''<a href=\"''.$urlwithroot.''/public/fichinter/agendaexport.php?format=vcal''.$getentity.''&exportkey=''.urlencode(getDolGlobalString(''MAIN_FICHINTER_XCAL_EXPORTKEY'', ''...''))", "admin/fichinter_xcal.php:203|check|if (getDolGlobalString(''MAIN_FICHINTER_XCAL_EXPORTKEY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIELDS_NEW_OBJECT_KEY_PREFIX', 'string', NULL, 'core', 'Prefixes each standard object field''s array key with ''object_'' when building the fields-info array in FieldsManager.', 'In core/class/fieldsmanager.class.php:390 and :461, `getDolGlobalInt(''MAIN_FIELDS_NEW_OBJECT_KEY_PREFIX'') ? ''object_'' : ''''` computes $keyPrefix/$patternObjectPrefix, which is prepended to each field key drawn from $object->fields.', 'Enabling it changes the array keys used internally to reference standard object fields (prefixed with ''object_''), which could affect code/hooks/templates that key off these field arrays directly.', 'Boolean: true prefixes standard field keys with ''object_''; false/unset (default) uses the bare field name as key.', 1, 0, NULL, 1, 'ac7a4ad6338d2043c8b1bc7437a610bde7135a979038b8066be6ae8af8b5a8ba', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/fieldsmanager.class.php:390|read|$keyPrefix = getDolGlobalInt(''MAIN_FIELDS_NEW_OBJECT_KEY_PREFIX'') ? ''object_'' : '''';", "core/class/fieldsmanager.class.php:461|read|$patternObjectPrefix = getDolGlobalInt(''MAIN_FIELDS_NEW_OBJECT_KEY_PREFIX'') ? ''object_'' : '''';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIELDS_SORT_WITH_EXTRA_FIELDS', 'string', NULL, 'core', 'Changes when extrafields are merged into the sort order relative to standard object fields when building field-layout columns (FieldsManager).', 'In core/class/fieldsmanager.class.php: if the constant is false (line 302), standard fields are sorted by ''position'' BEFORE extrafields are merged in (fields2 appended unsorted relative to extrafields); if true (line 311), the merged combined list (standard+extra) is sorted by ''position'' AFTER merging, i.e. extrafields interleave with standard fields by position.', 'Toggling it changes whether extrafields can be interleaved among standard fields by their ''position'' value (true) or are always appended after already-sorted standard fields (false/legacy behavior, ''Old sort'').', 'Boolean: 0/unset = legacy ''Old sort'' (standard fields sorted first, extrafields appended); 1 = ''New sort'' (all fields incl. extrafields sorted together by position).', 1, 0, NULL, 1, 'cc949ae313f18b0ad6cb215c3fe0ea330937e90dc84e0dbd46c606c039c1ce3f', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/fieldsmanager.class.php:301| // Old sort", "core/class/fieldsmanager.class.php:302|check|if (!getDolGlobalInt(''MAIN_FIELDS_SORT_WITH_EXTRA_FIELDS'')) {", "core/class/fieldsmanager.class.php:310| // New sort", "core/class/fieldsmanager.class.php:311|check|if (getDolGlobalInt(''MAIN_FIELDS_SORT_WITH_EXTRA_FIELDS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FILECHECK_LOCAL_EXT', 'string', NULL, 'api', 'Specifies an additional extension appended after ''.xml'' in the local file integrity check XML filename.', 'Read at blockedlog/admin/filecheck.php:141 and api/class/api_setup.class.php:2874 to construct the XML filename: ''filelist-''+DOL_VERSION+getDolGlobalString(''MAIN_FILECHECK_LOCAL_SUFFIX'')+''.xml''+getDolGlobalString(''MAIN_FILECHECK_LOCAL_EXT''). Admin UI present via blockedlog/admin/filecheck.php.', 'Setting this value appends a custom extension after ''.xml'' in the integrity check file name, enabling use of compressed or variant formats.', 'Empty/not set = filename ends with ''.xml''; string = extension appended after ''.xml'' (e.g. ''.gz'' for compressed files).', 0, 0, 'blockedlog/admin/filecheck.php', 1, '1374103c6a032bf2fadedefb00119df65124213d5d488fd302345aada5fb5d43', 'v2', '2026-04-21T11:16:15+00:00', '["blockedlog/admin/filecheck.php:141|read|$xmlshortfile = dol_sanitizeFileName(GETPOST(''xmlshortfile'', ''alpha'') ? GETPOST(''xmlshortfile'', ''alpha'') : ''filelist-''.DOL_VERSION.getDolGlobalString(''MAIN_FILECHECK_LOCAL_SUFFIX'')", "api/class/api_setup.class.php:2874|read|$xmlshortfile = dol_sanitizeFileName(''filelist-''.DOL_VERSION.getDolGlobalString(''MAIN_FILECHECK_LOCAL_SUFFIX'').''.xml''.getDolGlobalString(''MAIN_FILECHECK_LOCAL_EXT''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FILECHECK_LOCAL_SUFFIX', 'string', NULL, 'api', 'Specifies a suffix appended to the local file integrity check XML filename.', 'Read at blockedlog/admin/filecheck.php:141 and api/class/api_setup.class.php:2874 to construct the XML filename: ''filelist-''+DOL_VERSION+getDolGlobalString(''MAIN_FILECHECK_LOCAL_SUFFIX'')+''.xml''+getDolGlobalString(''MAIN_FILECHECK_LOCAL_EXT''). Admin UI present via blockedlog/admin/filecheck.php.', 'Setting this value appends a custom suffix to the integrity check XML file name, allowing use of customized or locally-named file lists.', 'Empty/not set = no suffix added to XML filename; string = suffix appended between version and ''.xml'' extension.', 0, 0, 'blockedlog/admin/filecheck.php', 1, 'a57d58ba4d66fa07da5628e2ef9369484c55e3f961fb2e097873063b403731f2', 'v2', '2026-04-21T11:16:15+00:00', '["blockedlog/admin/filecheck.php:141|read|$xmlshortfile = dol_sanitizeFileName(GETPOST(''xmlshortfile'', ''alpha'') ? GETPOST(''xmlshortfile'', ''alpha'') : ''filelist-''.DOL_VERSION.getDolGlobalString(''MAIN_FILECHECK_LOCAL_SUFFIX'')", "api/class/api_setup.class.php:2874|read|$xmlshortfile = dol_sanitizeFileName(''filelist-''.DOL_VERSION.getDolGlobalString(''MAIN_FILECHECK_LOCAL_SUFFIX'').''.xml''.getDolGlobalString(''MAIN_FILECHECK_LOCAL_EXT''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FILECHECK_URL', 'string', NULL, 'api', 'Specifies a custom remote URL for fetching the file integrity check XML manifest.', 'Checked at blockedlog/admin/filecheck.php:150 and api/class/api_setup.class.php:2883: ''if (empty($xmlremote) && getDolGlobalString(''MAIN_FILECHECK_URL''))'' followed by ''$xmlremote = getDolGlobalString(''MAIN_FILECHECK_URL'')''. Admin UI present via blockedlog/admin/filecheck.php.', 'When set, the integrity check uses the specified URL to fetch the remote XML manifest instead of the default Dolibarr URL.', 'Empty/not set = default remote manifest URL used; URL string = custom remote URL for the integrity check XML file.', 0, 0, 'blockedlog/admin/filecheck.php|blockedlog/admin/filecheck.php', 1, '830fdee7fd6a7b9cc219e751d5dfdcaa43d97587dd80e6cf26e06d69fd54dcaf', 'v2', '2026-04-21T11:16:15+00:00', '["blockedlog/admin/filecheck.php:150|check|if (empty($xmlremote) && getDolGlobalString(''MAIN_FILECHECK_URL'')) {", "blockedlog/admin/filecheck.php:151|read|$xmlremote = getDolGlobalString(''MAIN_FILECHECK_URL'');", "api/class/api_setup.class.php:2883|check|if (empty($xmlremote) && getDolGlobalString(''MAIN_FILECHECK_URL'')) {", "api/class/api_setup.class.php:2884|read|$xmlremote = getDolGlobalString(''MAIN_FILECHECK_URL'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FILESYSTEM_ENCODING', 'string', NULL, 'admin', 'Overrides the filesystem character encoding used by dol_osencode() to convert strings before writing them to disk.', 'Read in admin/system/dolibarr.php:387-388 to display the current encoding on the system info page, and used by dol_osencode() in core/lib/functions.lib.php:11822-11823 to force a specific encoding instead of the auto-detected default (iso-8859-1 on Windows, utf-8 otherwise).', 'If set, forces dol_osencode() to use this encoding for filesystem operations regardless of the platform default; if the value is ''iso-8859-1'' the string is converted from UTF-8 to ISO-8859-1 before being used as a filename.', 'Any charset string accepted by mb_convert_encoding, e.g. ''iso-8859-1'' or ''utf-8''; empty/unset falls back to platform auto-detection.', 0, 0, 'admin/system/dolibarr.php|admin/system/dolibarr.php', 1, 'd6b26de10446e4c7d1c14f7b4c7cda3364c2b706d36c4eb99fe9e696cd29c5ce', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:11822: if (getDolGlobalString(''MAIN_FILESYSTEM_ENCODING'')) {", "core/lib/functions.lib.php:11823: $tmp = getDolGlobalString(''MAIN_FILESYSTEM_ENCODING'');", "admin/system/dolibarr.php:387-388: same pattern, displayed as ''File encoding'' on system info page"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FILE_EXTENSION_UPLOAD_RESTRICTION', 'string', NULL, 'admin', 'Defines a comma-separated list of file extensions restricted (blocked) from upload.', 'Set via admin/security_file.php:108/217 (form field MAIN_FILE_EXTENSION_UPLOAD_RESTRICTION) and read in admin/system/security.php:633 and core/lib/files.lib.php:2128 to build $fileextensionrestriction, defaulting to getExecutableContent().', 'When set, uploads with the listed extensions are treated as restricted; if unset, the default executable-content extension list is used instead.', NULL, 0, 0, 'admin/security_file.php|admin/system/security.php|admin/security_file.php', 1, 'e03f1260b449ed87d2fa8b8468026c87e536585e4a85698f3d63e07121701366', 'v2', '2026-07-24T06:41:12+00:00', '["$res7 = dolibarr_set_const($db, \"MAIN_FILE_EXTENSION_UPLOAD_RESTRICTION\", GETPOST(''MAIN_FILE_EXTENSION_UPLOAD_RESTRICTION'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$fileextensionrestriction = getDolGlobalString(\"MAIN_FILE_EXTENSION_UPLOAD_RESTRICTION\", $defaultexecutableextensions);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FILL_SERVICE_DATES_FROM_LAST_SERVICE_LINE', 'string', NULL, 'core', 'Pre-fills service start/end dates on a new line from the dates of the previous service line in the document.', 'Checked in core/tpl/objectline_create.tpl.php:604 and core/tpl/objectline_edit.tpl.php:424 when the object already has lines and the current index is greater than zero.', 'Enabling this constant causes service date fields to be pre-populated from the preceding line, reducing manual data entry for recurring services.', 'Truthy value = pre-fill from last service line; empty/unset = dates left blank.', 1, 0, NULL, 1, 'e7fd8bada8850a43353a986853af23be02784bb96da5a5c5c829cda8b5c33052', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_edit.tpl.php:424|check|if (getDolGlobalString(''MAIN_FILL_SERVICE_DATES_FROM_LAST_SERVICE_LINE'') && !empty($object->lines) && $i > 0) {", "core/tpl/objectline_create.tpl.php:604|check|if (getDolGlobalString(''MAIN_FILL_SERVICE_DATES_FROM_LAST_SERVICE_LINE'') && !empty($object->lines)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FINISHED_LINES_OPACITY', 'string', NULL, 'fourn', 'Reduces the visual opacity of list rows for objects/lines considered finished/closed (status > 1 or billed).', 'Checked in projet/list.php:2083, supplier_proposal/list.php:1165, fourn/facture/list.php:1859, fourn/commande/list.php:1866, compta/facture/list.php:2425, commande/list.php:2456, and comm/propal/list.php:1921, each applying an ''opacitymedium'' CSS class when the value equals 1 and the row''s status/billed condition is met.', 'When set to 1, finished/closed rows in these lists are rendered with reduced opacity (CSS class ''opacitymedium'').', '1 = apply reduced opacity to finished lines', 1, 0, NULL, 1, '609c567d44306ed3c3711701df6ac688773aa70647daf8c8fdd070b70dc648e5', 'v2', '2026-07-24T06:41:12+00:00', '["((getDolGlobalInt(''MAIN_FINISHED_LINES_OPACITY'') == 1 && $object->status > 1) ? ''opacitymedium'' : '''')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIRSTNAME_NAME_POSITION', 'string', NULL, 'core', 'Controls the display order of first name and last name throughout the application.', 'Written by admin/ihm.php:289 and rendered as a selector at admin/ihm.php:509. A comment at core/class/html.form.class.php:2440 states: ''$fullNameMode is 0=Lastname+Firstname (MAIN_FIRSTNAME_NAME_POSITION=1), 1=Firstname+Lastname (MAIN_FIRSTNAME_NAME_POSITION=0)''. Checked in core/class/html.form.class.php:2343 and :2442, core/class/html.formother.class.php:581, and opensurvey/list.php:265.', 'Setting this to 0 displays names as Firstname Lastname; setting to 1 displays names as Lastname Firstname across all name-formatting functions.', '0 = Firstname + Lastname order; 1 = Lastname + Firstname order.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '9692509297a6ad5825df04f11e3a608fd3a515bb0d0646db771bf949e6f468b3', 'v2', '2026-04-21T11:16:15+00:00', '["// $fullNameMode is 0=Lastname+Firstname (MAIN_FIRSTNAME_NAME_POSITION=1), 1=Firstname+Lastname (MAIN_FIRSTNAME_NAME_POSITION=0)", "core/class/html.form.class.php:2343|check|if (!getDolGlobalString(''MAIN_FIRSTNAME_NAME_POSITION'')) {    // MAIN_FIRSTNAME_NAME_POSITION is 0 means firstname+lastname", "core/class/html.formother.class.php:581|check|if (!getDolGlobalString(''MAIN_FIRSTNAME_NAME_POSITION'')) {\t// MAIN_FIRSTNAME_NAME_POSITION is 0 means firstname+lastname", "admin/ihm.php:289|write|dolibarr_set_const($db, \"MAIN_FIRSTNAME_NAME_POSITION\", GETPOST(\"MAIN_FIRSTNAME_NAME_POSITION\", ''aZ09''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIRST_PING_OK_DATE', 'string', NULL, 'core', 'Records the timestamp of the first successful anonymous telemetry ping sent by this Dolibarr instance.', 'Written from core/ajax/pingresult.php:86 and read/written in main.inc.php (~line 4035) as $constanttosavefirstok, part of the asynchronous anonymous ''first ping'' telemetry mechanism triggered from the homepage (comment: ''Add code for the asynchronous anonymous first ping (for telemetry)'').', 'Presence of a value marks the ping as already completed for this install/version, which suppresses re-sending the JS ping code on subsequent page loads; clearing it or using &forceping=1 forces the ping again.', 'A formatted date string (dol_print_date with ''dayhourlog'',''gmt''); absence/empty means the ping has not yet succeeded.', 1, 0, NULL, 1, '2b45d7fa27d7553f8e5095eb46a5bc1181c7ab21c679a468780cc83412e232a5', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/pingresult.php:86|write|dolibarr_set_const($db, ''MAIN_FIRST_PING_OK_DATE'', dol_print_date($now, ''dayhourlog'', ''gmt''), ''chaine'', 0, '''', $conf->entity);", "main.inc.php:4036: $constanttosavefirstok = ''MAIN_FIRST_PING_OK_DATE'';", "main.inc.php: // Add code for the asynchronous anonymous first ping (for telemetry)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIRST_PING_OK_ID', 'string', NULL, 'core', 'Stores the identifier and version recorded when the Dolibarr instance first successfully sends a ping.', 'Written in core/ajax/pingresult.php:87 as a hash plus DOL_VERSION string. Read in install/step2.php:619 to determine the state of the ping opt-out checkbox.', 'Changing or clearing this constant affects whether the instance is considered to have previously opted in to pinging, altering the installer checkbox state.', 'String: ''<hash> - <DOL_VERSION>''; ''disabled'' = ping explicitly opted out; empty/unset = no ping recorded.', 1, 0, NULL, 1, '7c5c93bc1a44ef56283fadae9d4d060dfa90c9becd3d75494e4ebc3eea4b93c9', 'v2', '2026-04-21T11:16:15+00:00', '["core/ajax/pingresult.php:87|write|dolibarr_set_const($db, ''MAIN_FIRST_PING_OK_ID'', $hash_unique_id.'' - ''.DOL_VERSION, ''chaine'', 0, '''', $conf->entity);", "install/step2.php:619|read|$out .= ''<input type=\"checkbox\" name=\"dolibarrpingno\" id=\"dolibarrpingno\"''.((getDolGlobalString(''MAIN_FIRST_PING_OK_ID'') == ''disabled'') ? '''' : '' value=\"checked\" checked=\"true\"'').''>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIRST_REGISTRATION_OK_DATE', 'string', NULL, 'blockedlog', 'Records the date/time when the first successful Dolibarr registration (blocked-log registration) was confirmed.', 'Written in core/ajax/pingresult.php:98 via dolibarr_set_const, and read in blockedlog/admin/registration.php:445, blockedlog/admin/documentation.php:178, blockedlog/admin/blockedlog.php:171, and blockedlog/lib/blockedlog.lib.php:176 where isRegistrationDataSaved() also checks it.', 'Once set, blockedlog code treats registration data as saved (isRegistrationDataSaved()) and displays the stored date in admin blockedlog pages.', NULL, 1, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|blockedlog/admin/documentation.php|blockedlog/admin/documentation.php|blockedlog/admin/blockedlog.php|blockedlog/admin/blockedlog.php', 1, '73833d48f237bdf9ab9866a540a2c02ba0e3188d92d027d5ec9c3eae4ace187f', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, ''MAIN_FIRST_REGISTRATION_OK_DATE'', dol_print_date($now, ''dayhourlog'', ''gmt''), ''chaine'', 0, '''', $conf->entity);", "return isRegistrationDataSaved() && (bool) getDolGlobalString(''MAIN_FIRST_REGISTRATION_OK_DATE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIRST_REGISTRATION_OK_ID', 'string', NULL, 'core', 'Stores a unique hash+version identifier marking that the BlockedLog module registration succeeded for this instance/version.', 'Written from core/ajax/pingresult.php:99 as $hash_unique_id.'' - ''.DOL_VERSION; used by main.inc.php''s BlockedLog registration block (constant name there is MAIN_FIRST_PING_OK_ID / MAIN_FIRST_REGISTRATION_OK_ID pattern) to detect if registration for the current hash+version was already done, or was explicitly ''disabled''.', 'Changing/clearing it causes the registration ping to be re-attempted on next relevant page load; setting it to ''disabled'' suppresses the registration prompt.', 'A string of form ''<hash> - <DOL_VERSION>'', or the literal ''disabled'' to suppress registration.', 1, 0, NULL, 1, 'a963a1a0cb65c8f6fd08a43afc6ca1f886bde5e075e8394c3846fe23e27b9716', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/pingresult.php:99|write|dolibarr_set_const($db, ''MAIN_FIRST_REGISTRATION_OK_ID'', $hash_unique_id.'' - ''.DOL_VERSION, ''chaine'', 0, '''', $conf->entity);", "main.inc.php:4083: $constanttosavefirstokid = ''MAIN_FIRST_REGISTRATION_OK_ID'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIRST_TO_UPPER', 'string', NULL, 'core', 'Normalizes lastname, firstname, name and name_alias to Title Case (ucwords of lowercase) on save.', 'Checked in core/class/commonpeople.class.php:392 inside setUpperOrLowerCase(): when set, lastname/firstname/name/name_alias are each rewritten via dol_ucwords(dol_strtolower(...)).', 'When set, every save of a person/company-like object title-cases its name fields regardless of thirdparty type (unlike MAIN_TE_PRIVATE_FIRST_AND_LASTNAME_TO_UPPER, which special-cases TE_PRIVATE and force-uppercases the lastname).', 'Truthy/falsy flag.', 1, 0, NULL, 1, 'b439d42e87ef59196e1991e523b3c31e3c0f45e87b6fe77ca26705aefd575e04', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonpeople.class.php:392|check|if (getDolGlobalString(''MAIN_FIRST_TO_UPPER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIX_FLASH_ON_CHROME', 'string', NULL, 'core', 'Legacy workaround that injected a link to a non-existent stylesheet to fix an old Chrome flash-of-content bug.', 'In main.inc.php:1948, the check is inside a /* ... */ commented-out code block (''To fix old chrome bug''), so the code path is currently disabled/dead in this codebase version.', 'Even if set, this constant currently has no effect since the code that reads it is commented out.', 'Boolean-like historically, but the reading code is commented out so the constant is presently inert.', 0, 0, NULL, 1, '2cc0a62cc9a41eb5ed7896afab1ced857cf18980f045c0fc08807fb5a97b9932', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:1948|check|if (getDolGlobalString(''MAIN_FIX_FLASH_ON_CHROME'')) {", "main.inc.php: // To fix old chrome bug"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FIX_FOR_BUGGED_MTA', 'string', '1', 'admin', 'Enables a workaround for mail transfer agents that do not support CRLF line endings in email body content.', 'When enabled, CMailFile uses LF-only line endings (\n) instead of CRLF (\r\n) when wrapping email body text. Checked across admin/mails.php, admin/mails_passwordreset.php, admin/mails_ticket.php, and admin/mails_emailing.php to show warnings when the send mode is ''mail''. Default value is ''1''.', 'Enabling this constant changes the line ending character used in email bodies from \r\n to \n; disabling it restores standard CRLF line endings required by RFC 2822.', 'Non-empty string (truthy) enables the fix; empty or undefined disables it.', 0, 0, 'admin/mails.php|admin/mails_passwordreset.php|admin/mails_ticket.php|admin/mails_emailing.php', 1, '65f3a5b29d6cf4bd05f0912aa0b23365de4632bef0874327b9ad6cc13325263f', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:1809|read|$strContentAltText = trim(wordwrap($strContentAltText, 75, !getDolGlobalString(''MAIN_FIX_FOR_BUGGED_MTA'') ? \"\\r\\n\" : \"\\n\"));", "core/class/CMailFile.class.php:1818|read|$strContent = rtrim(wordwrap($strContent, 75, !getDolGlobalString(''MAIN_FIX_FOR_BUGGED_MTA'') ? \"\\r\\n\" : \"\\n\"));", "admin/mails.php:1037|check|if (getDolGlobalString(''MAIN_MAIL_SENDMODE'', ''mail'') == ''mail'' && !getDolGlobalString(''MAIN_FIX_FOR_BUGGED_MTA'')) {", "core/class/CMailFile.class.php:272|check|if (getDolGlobalString(''MAIN_FIX_FOR_BUGGED_MTA'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FONTAWESOME_DIRECTORY', 'string', NULL, 'core', 'Overrides the relative path used to load the Font Awesome CSS directory in the HTML head.', 'In main.inc.php:1924, its value (default ''/theme/common/fontawesome-5'') is used to build the URL of the Font Awesome all.min.css stylesheet included on every page, unless DISABLE_FONT_AWSOME is defined.', 'Changing it redirects the Font Awesome stylesheet include to a different directory, e.g. to point at an alternate/custom Font Awesome version.', 'String path relative to DOL_URL_ROOT, default ''/theme/common/fontawesome-5''.', 0, 0, NULL, 1, 'a85fe77cd4824947b3f9d9e3ed14b3d82e09dc3bf9d5f474a8a7c5571e60eb99', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:1924|read|$fontawesome_directory = getDolGlobalString(''MAIN_FONTAWESOME_DIRECTORY'', ''/theme/common/fontawesome-5'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FONTAWESOME_FAMILY', 'string', NULL, 'theme', 'Specifies the Font Awesome CSS font-family name used for icons across the Eldy and MD themes.', 'Read across many theme files including theme/eldy/dropdown.inc.php:420, theme/md/dropdown.inc.php:176, :438, theme/eldy/btn.inc.php:215, theme/eldy/main_menu_fa_icons.inc.php:57, and theme/eldy/global.inc.php:1649, :4211, :8860 to set the CSS font-family for icon elements. Falls back to ''Font Awesome 5 Free'' if unset. No admin UI write path is present in the payload.', 'Setting this to a different font family name replaces the Font Awesome icon font used throughout the interface. Leaving it unset defaults to ''Font Awesome 5 Free''.', 'CSS font-family name string. Defaults to ''Font Awesome 5 Free''.', 1, 0, NULL, 1, 'f6528d24e5f6a2a053adecbde0a9cfaf548bdc6f05ceabaaaddb9e252bdca247', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/dropdown.inc.php:420|read|font-family: \"<?php echo getDolGlobalString(''MAIN_FONTAWESOME_FAMILY'', ''Font Awesome 5 Free''); ?>\";", "theme/md/dropdown.inc.php:176|read|font-family: \"<?php echo getDolGlobalString(''MAIN_FONTAWESOME_FAMILY'', ''Font Awesome 5 Free''); ?>\";", "theme/eldy/btn.inc.php:215|read|font-family: \"<?php echo getDolGlobalString(''MAIN_FONTAWESOME_FAMILY'', ''Font Awesome 5 Free''); ?>\";", "theme/eldy/global.inc.php:1649|read|font-family: \"<?php echo getDolGlobalString(''MAIN_FONTAWESOME_FAMILY'', ''Font Awesome 5 Free''); ?>\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FONTAWESOME_ICON_STYLE', 'string', NULL, 'core', 'Sets the default FontAwesome icon style/prefix class used when rendering picto icons.', 'In core/lib/functions.lib.php:5772, `$fa = getDolGlobalString(''MAIN_FONTAWESOME_ICON_STYLE'', ''fas'')` sets the base FA class (''fas'' = solid by default), later overridden to ''far'' or ''fab'' for specific picto codes (regular/brand icon sets).', 'Changing it switches the default FontAwesome icon family (e.g. ''fas'' solid vs ''far'' regular vs ''fal'' light) used across the UI for icons that are not explicitly forced to far/fab.', 'FontAwesome class prefix string, e.g. ''fas'' (default), ''far'', ''fal'', ''fab''.', 1, 0, NULL, 1, 'fbabb44a8c5927b4541e376e95b1400e119fefdc743f97f90f617b4194597bee', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5772|read|$fa = getDolGlobalString(''MAIN_FONTAWESOME_ICON_STYLE'', ''fas'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCELANGDIR', 'string', NULL, 'core', 'Forces translation file loading from a custom subdirectory path appended to each language directory.', 'Checked and read in core/class/translate.class.php at lines 130, 134, and 395. The inline comment at line 134 documents: ''For example $conf->global->MAIN_FORCELANGDIR is "/mymodule" meaning we search files into "/mymodule/langs/xx_XX"''. No admin UI write is present.', 'When set, all translation file lookups are redirected to the specified subdirectory, allowing custom or module-specific language files to override defaults. When unset, the standard language directory structure is used.', 'Subdirectory path string (e.g. ''/mymodule''); empty or unset to use default language directories.', 1, 0, NULL, 1, '2f125003a5f1fe6dfed6c8c086667446e23a2940aa6ad1312671db74238e4b94', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/translate.class.php:134|read|$newdir = $dir . getDolGlobalString(''MAIN_FORCELANGDIR''); // For example $conf->global->MAIN_FORCELANGDIR is ''/mymodule'' meaning we search files into ''/mymodule/langs/xx_XX''", "core/class/translate.class.php:130|check|if (getDolGlobalString(''MAIN_FORCELANGDIR'')) {", "core/class/translate.class.php:395|check|if (!getDolGlobalString(''MAIN_FORCELANGDIR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCETHEME', 'string', NULL, 'core', 'Forces all users to use a specific UI theme, overriding individual user theme preferences.', 'Checked in main.inc.php:1191 to suppress per-user theme selection, and in core/lib/usergroups.lib.php:433-435 where a warning is displayed showing the forced theme name.', 'When set, individual users cannot change their theme; the named theme is applied globally.', 'Any valid theme name string; empty/unset = users may choose their own theme', 1, 0, NULL, 1, '6055d6e3b19cdf5ca0d154c8eaa633a0afd4250f83c937db17f0a904505385d1', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1191|check|if (!getDolGlobalString(''MAIN_FORCETHEME'') && getDolUserString(''MAIN_THEME'')) {", "core/lib/usergroups.lib.php:433|check|if (getDolGlobalString(''MAIN_FORCETHEME'')) {", "core/lib/usergroups.lib.php:435|read|print $langs->trans(\"WarningThemeForcedTo\", getDolGlobalString(''MAIN_FORCETHEME''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_DISABLE_MAIL_SPOOFING', 'bool', NULL, 'core', 'Prevents email ''From'' address spoofing by rewriting the From header to the configured SMTPS identity when it doesn''t match, for strict SMTP server configurations.', 'In core/class/CMailFile.class.php:721-729, when getDolGlobalString(''MAIN_FORCE_DISABLE_MAIL_SPOOFING'') is set, the From address is regex-extracted and compared against getDolGlobalString(''MAIN_MAIL_SMTPS_ID''); if it''s a valid email and differs from the extracted from-address, the message From is forced to MAIN_MAIL_SMTPS_ID instead of the original addr_from. Comment: ''Prevent email spoofing for smtp server with a strict configuration.''', 'Enabling it can silently override the visible From address of outgoing emails to the configured SMTPS identity when the intended From doesn''t match, which helps pass strict SMTP server/relay checks but changes the sender identity shown to recipients.', 'Boolean-like: set/non-empty enables anti-spoofing From rewriting (depends also on MAIN_MAIL_SMTPS_ID being a valid email); unset (default) uses the original addr_from unmodified.', 1, 0, NULL, 1, '1b99818cd4145838024b54228a04c1dbfe247bb2778e3b982c591b91be55f3bb', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/CMailFile.class.php:721: if (getDolGlobalString(''MAIN_FORCE_DISABLE_MAIL_SPOOFING'')) {", "core/class/CMailFile.class.php:722: // Prevent email spoofing for smtp server with a strict configuration", "core/class/CMailFile.class.php:726-727: if ($emailMatchs !== false && filter_var(getDolGlobalString(''MAIN_MAIL_SMTPS_ID''), FILTER_VALIDATE_EMAIL) && getDolGlobalString(''MAIN_MAIL_SMTPS_ID'') !== $adressEmailFrom[0]) { $this->message->setFrom(getDolGlobalString(''MAIN_MAIL_SMTPS_ID'')); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_DOWNLOAD_IN_HTML_FORMFILE', 'string', NULL, 'core', 'Forces file download (instead of inline display) for documents rendered via the html.formfile component.', 'Read as an integer in core/class/html.formfile.class.php at lines 1035, 1654, and 2201 to set the forcedownload flag used when generating file links.', 'When set to a truthy integer, clicking document links triggers a download prompt rather than in-browser display. When 0 or unset, files open inline if the browser supports the format.', 'Integer: 1 to force download; 0 or unset to allow inline display.', 1, 0, NULL, 1, 'a26bc92a5c1d67e80f8339b8d0a44a6a6cb8827187f378f6d8d0fbb903f7d46c', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.formfile.class.php:1035|read|$forcedownload = getDolGlobalInt(''MAIN_FORCE_DOWNLOAD_IN_HTML_FORMFILE'');", "core/class/html.formfile.class.php:1654|read|$forcedownload = getDolGlobalInt(''MAIN_FORCE_DOWNLOAD_IN_HTML_FORMFILE'');", "core/class/html.formfile.class.php:2201|read|$forcedownload = getDolGlobalInt(''MAIN_FORCE_DOWNLOAD_IN_HTML_FORMFILE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_READFILE_WITH_FREAD', 'string', NULL, 'core', 'Forces readfileLowMemory() to use the fread-based method (method=1) instead of PHP readfile() when serving large files.', 'In core/lib/functions.lib.php:15966-15977, readfileLowMemory($fullpath, $method=-1) auto-selects a method: default 0=readfile(), but if getDolGlobalString(''MAIN_FORCE_READFILE_WITH_FREAD'') is set, method becomes 1 (fread-based loop), and MAIN_FORCE_READFILE_WITH_STREAM_COPY overrides it further to method 2.', 'Forces an alternate low-memory file output strategy for large file downloads; useful when the default readfile() has problems on a given hosting/PHP setup.', 'Set (non-empty) = use fread method (1) instead of default readfile() (0); overridden by MAIN_FORCE_READFILE_WITH_STREAM_COPY if both set.', 1, 0, NULL, 1, '038ec215b1ae6f2bb308321d0292b082cb95e58d8710a10aba24e86edc79be27', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:15968: @param int<-1,2> $method -1 automatic, 0=readfile, 1=fread, 2=stream_copy_to_stream", "core/lib/functions.lib.php:15972: if (getDolGlobalString(''MAIN_FORCE_READFILE_WITH_FREAD'')) { $method = 1; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_READFILE_WITH_STREAM_COPY', 'string', NULL, 'core', 'Forces readfileLowMemory() to use the stream_copy_to_stream method (method=2) instead of PHP readfile() when serving large files.', 'In core/lib/functions.lib.php:15966-15977, readfileLowMemory() defaults to method 0 (readfile()); getDolGlobalString(''MAIN_FORCE_READFILE_WITH_STREAM_COPY'') sets method to 2 (stream_copy_to_stream), checked after MAIN_FORCE_READFILE_WITH_FREAD so it takes precedence if both are set.', 'Changes the internal PHP mechanism used to stream large files to the client; alternate to the fread and default readfile strategies.', 'Set (non-empty) = use stream_copy_to_stream method (2); takes priority over MAIN_FORCE_READFILE_WITH_FREAD if both set.', 1, 0, NULL, 1, '1777cde2b473c3e31c889082c064544ccf72d4364d0e6e96e2cc6aa1177f087a', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:15968: @param int<-1,2> $method -1 automatic, 0=readfile, 1=fread, 2=stream_copy_to_stream", "core/lib/functions.lib.php:15975: if (getDolGlobalString(''MAIN_FORCE_READFILE_WITH_STREAM_COPY'')) { $method = 2; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_RELOAD_PAGE', 'string', NULL, 'core', 'Forces a full page reload (instead of an ajax/DOM update) after certain line reordering or subtotal actions in list/order tables.', 'Read via getDolGlobalInt() in variants/list.php:873, core/tpl/subtotal_ajaxrow.tpl.php:62, and core/tpl/ajaxrow.tpl.php:71, where its value is passed into the page''s JS config as ''forceReloadPage'' to control drag-and-drop line reorder behavior.', 'Setting it non-zero forces the page to fully reload after ajax line-reorder/drag-and-drop operations on lists/tables instead of updating in place via JavaScript.', 'Integer: truthy value forces full page reload after ajax row reorder; 0/unset keeps default ajax-only behavior.', 1, 0, NULL, 1, '45b1dadfe05bab31e98570b826971eb53eb2266e9f5831a0f4e8151218d7b91b', 'v2', '2026-07-24T07:05:23+00:00', '["variants/list.php:873|read|$forcereloadpage = getDolGlobalInt(''MAIN_FORCE_RELOAD_PAGE'');", "core/tpl/ajaxrow.tpl.php:71|read|''forceReloadPage'' => getDolGlobalInt(''MAIN_FORCE_RELOAD_PAGE''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_SHARING_ON_ANY_UPLOADED_FILE', 'string', NULL, 'core', 'Forces every uploaded file to get a random share key so it becomes externally downloadable via a share link.', 'Read in core/lib/files.lib.php:2378 right before the ECM file object is saved; if set, $setsharekey is forced to 1, which then makes the code call getRandomPassword(true) to populate $ecmfile->share.', 'Enabling it means all newly uploaded files (not just ones explicitly marked shareable) get an ECM share key generated automatically, making them accessible via the public share URL.', 'Boolean-like/string truthy value forces $setsharekey = 1 for any uploaded file.', 1, 0, NULL, 1, '51851f8eac0ab07354353ec265c1b8de3c0a3e22999ea79fd7cb4c268bc8fc77', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/files.lib.php:2378|check|if (getDolGlobalString(''MAIN_FORCE_SHARING_ON_ANY_UPLOADED_FILE'')) { $setsharekey = 1; }", "if ($setsharekey) { $ecmfile->share = getRandomPassword(true); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_STATE_INTO_ADDRESS', 'string', NULL, 'core', 'Forces the state/province to be included in formatted address strings for all countries, not just those that normally use it.', 'Checked in core/class/commonpeople.class.php:244-245 and webportal/class/webportalmember.class.php:471-472 with the comment ''If MAIN_FORCE_STATE_INTO_ADDRESS is on, state is already returned previously with getFullAddress''. Also used in core/lib/functions.lib.php:3803.', 'When enabled, the state field appears in address output for all countries regardless of country-specific rules; without it, only AU, CA, US, CN automatically include the state.', '0 or unset = state shown only for countries that use it (AU, CA, US, CN); non-empty = state always shown', 1, 0, NULL, 1, '4643eed71b23ce3c82208bec6a5a088de190ce201c3539393a7f4dc36dd3b54b', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/commonpeople.class.php:244  // If MAIN_FORCE_STATE_INTO_ADDRESS is on, state is already returned previously with getFullAddress", "webportal/class/webportalmember.class.php:471  // If MAIN_FORCE_STATE_INTO_ADDRESS is on, state is already returned previously with getFullAddress", "core/lib/functions.lib.php:3803|check|if (isset($object->country_code) && in_array($object->country_code, array(''AU'', ''CA'', ''US'', ''CN'')) || getDolGlobalString(''MAIN_FORCE_STATE_INTO_ADDRESS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_SYSTEM_MESSAGE', 'string', NULL, 'index.php', 'Displays a forced system/legal-announcement warning banner on the home page, using the constant''s value as a language-translation key/string.', 'In index.php:119-121, if getDolGlobalString(''MAIN_FORCE_SYSTEM_MESSAGE'') is set, its value is passed through $langs->trans() and shown via info_admin() as a warning box; comment marks it ''Specific warning for legal announcement''.', 'Setting this constant forces a warning message to appear at the top of the home page for all users; the value is treated as a translation key/text.', 'String; a language key or literal text to display as a warning banner. Empty/unset shows nothing.', 1, 0, NULL, 1, '4bd845643c56e9398faee31f90764e2413127f07e28c8251b92fec1ff523a44c', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:119|check|if (getDolGlobalString(''MAIN_FORCE_SYSTEM_MESSAGE'')) {", "index.php:121|read|$messagetoshow = $langs->trans(getDolGlobalString(''MAIN_FORCE_SYSTEM_MESSAGE''));", "index.php:117|comment|// Specific warning for legal announcement"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_UPGRADE_MESSAGE', 'string', NULL, 'index.php', 'Forces display of an upgrade message on the login/index page, with a default translation key if unset.', 'Checked/read in index.php:137, :139, and :142; combined with MAIN_FORCE_UPGRADE_URL and default ''YourInstallIsOldThanksToUpgrade''.', 'When set, index.php shows this message (or, if numeric, is treated specially); if unset it defaults to the ''YourInstallIsOldThanksToUpgrade'' translation string when MAIN_FORCE_UPGRADE_URL is also set.', 'Default translation key: YourInstallIsOldThanksToUpgrade', 1, 0, NULL, 1, '4856228117a534946c47398c588bad132d65ef5353022c588293f444beca3b28', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_FORCE_UPGRADE_MESSAGE'') || getDolGlobalString(''MAIN_FORCE_UPGRADE_URL'')) {", "if (is_numeric(getDolGlobalString(''MAIN_FORCE_UPGRADE_MESSAGE''))) {", "$messagetoshow = $langs->trans(getDolGlobalString(''MAIN_FORCE_UPGRADE_MESSAGE'', \"YourInstallIsOldThanksToUpgrade\"));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FORCE_UPGRADE_URL', 'string', NULL, 'index.php', 'Forces a clickable upgrade URL to be displayed alongside the forced upgrade message on the login/index page.', 'Checked/read in index.php:137, :144, and :145, combined with MAIN_FORCE_UPGRADE_MESSAGE.', 'When set, index.php renders it as a link (''<br><a href=...target="_blank">'') appended to the upgrade message.', NULL, 1, 0, NULL, 1, '8d3b075101e33fb54aa8cdee0118a57df896004c3e205aa36e682fa7fb6c5fee', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_FORCE_UPGRADE_MESSAGE'') || getDolGlobalString(''MAIN_FORCE_UPGRADE_URL'')) {", "$messagetoshow .= ''<br><a href=\"''.getDolGlobalString(''MAIN_FORCE_UPGRADE_URL'').''\" target=\"_blank\">''.getDolGlobalString(''MAIN_FORCE_UPGRADE_URL'').''</a>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FRANCE_TODO_LOI_FINANCE', 'string', NULL, 'core', 'Blocks invoice validation for a French individual customer subject to VAT unless the Unalterable Archives module is enabled (French Loi Finance 2025).', 'In core/class/interfaces.class.php:113-136, run_triggers() checks this bool together with the invoice being validated (action BILL_VALIDATE), country FR, VAT-liable seller, an individual (non-company) customer, and the blockedlog module NOT enabled; if all match, it aborts with error -1 and a detailed message about needing to enable Unalterable Archives.', 'Enabling it enforces a legal-compliance block preventing invoice validation for individual French customers unless the Unalterable Archives module is active; leaving it unset/false does not enforce this check.', 'true/1 = enforce the French Loi Finance 2025 block on BILL_VALIDATE for individual FR customers without blockedlog enabled; false/unset (default) = no enforcement.', 1, 0, NULL, 1, 'fedeaea0c9f6f2c8d7bac05ab4d58b27cdd7578f076957170547d25961e63138', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/interfaces.class.php:114|read|getDolGlobalString(''MAIN_FRANCE_TODO_LOI_FINANCE'')", "core/class/interfaces.class.php:131: ''This means you are eligible the to the French Loi Finance 2025 and need to enable the module Unalterable Archives...''", "core/class/interfaces.class.php:135: return -1;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_FREE_PRODUCT_CHECKED_BY_DEFAULT', 'string', NULL, 'core', 'Controls which entry mode radio button (free-text or product/service) is pre-selected when adding document lines.', 'Read in core/tpl/objectline_create.tpl.php:230 to decide the checked state, and checked in core/class/html.form.class.php:1250 (''product'') and :1257 (''service'') to pre-select the product type radio.', 'Setting to ''product'' pre-selects the product radio; setting to ''service'' pre-selects the service radio; leaving unset defaults to the standard selection logic.', 'Empty/not set = default selection; ''product'' = product radio pre-selected; ''service'' = service radio pre-selected', 1, 0, NULL, 1, '44b55806f32d39accdbf8133f94af599f1a192d405a56388f4becf37da6711a5', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:230|read|print((GETPOST(''prod_entry_mode'', ''alpha'') == ''free'' || getDolGlobalString(''MAIN_FREE_PRODUCT_CHECKED_BY_DEFAULT'')) ? '' checked'' : '''');", "core/class/html.form.class.php:1250|check|if (0 == $selected || ($selected == -1 && getDolGlobalString(''MAIN_FREE_PRODUCT_CHECKED_BY_DEFAULT'') == ''product'')) {", "core/class/html.form.class.php:1257|check|if (1 == $selected || ($selected == -1 && getDolGlobalString(''MAIN_FREE_PRODUCT_CHECKED_BY_DEFAULT'') == ''service'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DELIVERY_WITH_PICTURE', 'string', NULL, 'core', 'Includes a product photo column when generating the delivery (shipment) PDF document.', 'Checked twice in core/modules/delivery/doc/pdf_storm.modules.php: line 186, guarding a loop that fetches each shipped product''s photo into `$realpatharray` (`if (getDolGlobalString(''MAIN_GENERATE_DELIVERY_WITH_PICTURE'')) { $objphoto = new Product($this->db); ... }`); and line 960, enabling the ''photo'' column (`$this->cols[''photo''][''status''] = true;`) only if the flag is set AND at least one photo was found.', 'When set, the delivery PDF attempts to look up and display a product photo for each shipped line (adds a photo column) if at least one product has a photo; when unset, no photo lookup/column is added.', 'Truthy/falsy flag.', 0, 0, NULL, 1, '0926ed2b2329eee1646ea578ad58f87afde8d14e0fdf31ef2181cc3c9354ae57', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/delivery/doc/pdf_storm.modules.php:186|check|if (getDolGlobalString(''MAIN_GENERATE_DELIVERY_WITH_PICTURE'')) {", "core/modules/delivery/doc/pdf_storm.modules.php:960|check|if (getDolGlobalString(''MAIN_GENERATE_DELIVERY_WITH_PICTURE'') && !empty($this->atleastonephoto)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_HIDE_DESC', 'bool', NULL, 'core', 'Hides line-item description text when generating PDF or other documents.', 'Written via admin/pdf.php (line 142) and shown as a yes/no selector (line 601). Read across at least 26 files including supplier_proposal/card.php:91, reception/card.php:122, and api/class/api_documents.class.php:236 to set the `$hidedesc` flag.', 'Enabling this setting causes generated documents to omit line-item description text.', '0 = show descriptions (default); 1 = hide descriptions.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '866a248da6aef13b0edca3803dba8092bc588f6e63f2470d0af6aa158aa57bbc', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:142|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_HIDE_DESC\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_HIDE_DESC\"), ''chaine'', 0, '''', $conf->entity);", "api/class/api_documents.class.php:236|read|$hidedesc = !getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_HIDE_DESC'') ? 0 : 1;", "supplier_proposal/card.php:91|read|$hidedesc = (GETPOSTINT(''hidedesc'') ? GETPOSTINT(''hidedesc'') : (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_HIDE_DESC'') ? 1 : 0));", "admin/pdf.php:601|read|print $form->selectyesno(''MAIN_GENERATE_DOCUMENTS_HIDE_DESC'', getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_HIDE_DESC''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_HIDE_DETAILS', 'bool', NULL, 'core', 'Hides line-item detail rows when generating PDF or other documents.', 'Written via admin/pdf.php (line 139) and shown as a yes/no selector (line 611). Read across at least 26 files including supplier_proposal/card.php:90, reception/card.php:121, and api/class/api_documents.class.php:235 to set the `$hidedetails` flag.', 'Enabling this setting causes generated documents to omit line-item detail rows; documents will show only summary-level information.', '0 = show details (default); 1 = hide details.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'f65369b4103ff7542d67d2bcf038d6b68e3201cee8906115fe2b3ec7248737c9', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:139|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_HIDE_DETAILS\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_HIDE_DETAILS\"), ''chaine'', 0, '''', $conf->entity);", "api/class/api_documents.class.php:235|read|$hidedetails = !getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_HIDE_DETAILS'') ? 0 : 1;", "supplier_proposal/card.php:90|read|$hidedetails = (GETPOSTINT(''hidedetails'') ? GETPOSTINT(''hidedetails'') : (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_HIDE_DETAILS'') ? 1 : 0));", "admin/pdf.php:611|read|print $form->selectyesno(''MAIN_GENERATE_DOCUMENTS_HIDE_DETAILS'', getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_HIDE_DETAILS''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_HIDE_REF', 'bool', NULL, 'core', 'Hides line-item reference codes when generating PDF or other documents.', 'Written via admin/pdf.php (line 145) and shown as a yes/no selector (line 579). Read across at least 27 files including supplier_proposal/card.php:92, compta/facture/card.php:117, and recruitment/class/recruitmentjobposition.class.php:748 to set the `$hideref` flag.', 'Enabling this setting causes generated documents to omit line-item reference codes.', '0 = show references (default); 1 = hide references.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'b2be4c250165ad869853232feea3f9fee99e8ab7d0f269b06ae00fe4fcccf26c', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:145|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_HIDE_REF\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_HIDE_REF\"), ''chaine'', 0, '''', $conf->entity);", "recruitment/class/recruitmentjobposition.class.php:748|read|$hideref = (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_HIDE_REF'') ? 1 : 0);", "supplier_proposal/card.php:92|read|$hideref = (GETPOSTINT(''hideref'') ? GETPOSTINT(''hideref'') : (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_HIDE_REF'') ? 1 : 0));", "admin/pdf.php:579|read|print $form->selectyesno(''MAIN_GENERATE_DOCUMENTS_HIDE_REF'', getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_HIDE_REF''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_TOTAL_COLUMN', 'string', NULL, 'admin', 'Suppresses the total column in purchase order PDF documents when enabled.', 'Written in admin/pdf_other.php at line 115 and displayed as a select at line 716. Checked (negated) in pdf_muscadet.modules.php at line 530 and pdf_cornas.modules.php at line 1710; the total column is rendered only when this constant is falsy.', 'Enabling this constant hides the total column from purchase order PDFs. Disabling it (or leaving unset) shows the total column.', 'Truthy string to hide total column; empty/unset to show total column.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '9a6aa19d45063f69a38bb08fc2dd3e8cef76bce264dbebc79146aa62d4faff64', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:115|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_TOTAL_COLUMN\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_TOTAL_COLUMN\"), ''chaine'', 0, '''', $con", "core/modules/supplier_order/doc/pdf_muscadet.modules.php:530|check|if (!getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_TOTAL_COLUMN'')) {", "core/modules/supplier_order/doc/pdf_cornas.modules.php:1710|check|if (!getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_TOTAL_COLUMN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_UNIT_PRICE', 'string', NULL, 'admin', 'Suppresses the unit price column in purchase order PDF documents when enabled.', 'Written in admin/pdf_other.php at line 112 and displayed as a select at line 705. Checked (negated) in pdf_muscadet.modules.php at line 504 and pdf_cornas.modules.php at line 1656; the unit price column is rendered only when this constant is falsy.', 'Enabling this constant hides the unit price column from purchase order PDFs. Disabling it (or leaving unset) shows the unit price column.', 'Truthy string to hide unit price column; empty/unset to show unit price column.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, 'c326771fce6224de9f4d36c69f63f6940e9d3b129212a4e06a664f1f4865a5b2', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:112|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_UNIT_PRICE\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_UNIT_PRICE\"), ''chaine'', 0, '''', $conf->e", "core/modules/supplier_order/doc/pdf_muscadet.modules.php:504|check|if (!getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_UNIT_PRICE'')) {", "core/modules/supplier_order/doc/pdf_cornas.modules.php:1656|check|if (!getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_PURCHASE_ORDER_WITHOUT_UNIT_PRICE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_SHOW_FOOT_DETAILS', 'bool', NULL, 'core', 'Controls the level of company detail shown in the footer of generated PDF documents.', 'Configured via admin/pdf.php:169 using a select array and read across 82 occurrences as $showdetails = getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_SHOW_FOOT_DETAILS'', 0) in all major PDF generation modules.', 'Changing this value alters how much company information appears in PDF footers; the default value 0 shows minimal detail.', 'Integer. 0 = minimal footer details (default); higher values show progressively more company information.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '47649f50bf576db284007558946754184c45dfd383b01935e2045ed6bb8f39e4', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:169|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_SHOW_FOOT_DETAILS\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_SHOW_FOOT_DETAILS\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:650|read|print $form->selectarray(''MAIN_GENERATE_DOCUMENTS_SHOW_FOOT_DETAILS'', $arraydetailsforpdffoot, getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_SHOW_FOOT_DETAILS'', ''0''));", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:1291|read|$showdetails = getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_SHOW_FOOT_DETAILS'', 0);", "core/modules/commande/doc/pdf_einstein.modules.php:1672|read|$showdetails = getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_SHOW_FOOT_DETAILS'', 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_SHOW_PRODUCT_BARCODE', 'bool', NULL, 'admin', 'Controls whether product barcodes are displayed in PDF line items when the barcode module is enabled.', 'Configured via admin/pdf.php (written at line 149, rendered as a yes/no selector at line 590). Checked at core/lib/pdf.lib.php:2056; requires both the barcode module to be enabled and a non-empty product_barcode value.', 'Enabling this causes product barcodes to be rendered in line item blocks on generated PDFs when the barcode module is active.', '1 = show product barcode in PDF lines (requires barcode module enabled); 0 or absent = do not show barcode.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '40e88df2089e0e8a8e3748bdd76c51f1ee062d5b6141a16df133525d236651de', 'v2', '2026-04-21T13:29:58+00:00', '["admin/pdf.php:149|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_SHOW_PRODUCT_BARCODE\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_SHOW_PRODUCT_BARCODE\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:590|read|print $form->selectyesno(''MAIN_GENERATE_DOCUMENTS_SHOW_PRODUCT_BARCODE'', getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_SHOW_PRODUCT_BARCODE''), 1);", "core/lib/pdf.lib.php:2056|check|if (isModEnabled(''barcode'') && getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_SHOW_PRODUCT_BARCODE'') && !empty($product_barcode)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_SUPPLIER_PROPOSAL_WITHOUT_TOTAL_COLUMN', 'string', NULL, 'admin', 'Suppresses the total column in supplier proposal PDF documents when enabled.', 'Written in admin/pdf_other.php at line 109 and displayed as a select at line 677. Checked (negated) in core/modules/supplier_proposal/doc/pdf_zenith.modules.php at line 1650; the total column is rendered only when this constant is falsy.', 'Enabling this constant hides the total column from supplier proposal PDFs. Disabling it (or leaving unset) shows the total column.', 'Truthy string to hide total column; empty/unset to show total column.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '33f392d4c5e2076c780b1e8c54492df745ad82f16c4cb3df552ce6496983266e', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:109|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_SUPPLIER_PROPOSAL_WITHOUT_TOTAL_COLUMN\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_SUPPLIER_PROPOSAL_WITHOUT_TOTAL_COLUMN\"), ''chaine'', 0, ''''", "core/modules/supplier_proposal/doc/pdf_zenith.modules.php:1650|check|if (!getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_SUPPLIER_PROPOSAL_WITHOUT_TOTAL_COLUMN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_SUPPLIER_PROPOSAL_WITHOUT_UNIT_PRICE', 'string', NULL, 'admin', 'Suppresses the unit price column in supplier proposal PDF documents when enabled.', 'Written in admin/pdf_other.php at line 106 and displayed as a select at line 666. Checked (negated) in core/modules/supplier_proposal/doc/pdf_zenith.modules.php at line 1596; the unit price column is rendered only when this constant is falsy.', 'Enabling this constant hides the unit price column from supplier proposal PDFs. Disabling it (or leaving unset) shows the unit price column.', 'Truthy string to hide unit price column; empty/unset to show unit price column.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '232bb33e709f389b7b14b650cf4b29785ef9f9340971dbc87b3874174453a25c', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:106|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_SUPPLIER_PROPOSAL_WITHOUT_UNIT_PRICE\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_SUPPLIER_PROPOSAL_WITHOUT_UNIT_PRICE\"), ''chaine'', 0, '''', $c", "core/modules/supplier_proposal/doc/pdf_zenith.modules.php:1596|check|if (!getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_SUPPLIER_PROPOSAL_WITHOUT_UNIT_PRICE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT', 'string', NULL, 'core', 'Suppresses VAT/tax columns and totals from all generated PDF documents.', 'Written via admin/pdf.php:118 and rendered via admin/pdf.php:502 with selectyesno. Checked in 41 locations across expense report, order, invoice, supplier order, and proposal PDF modules. Often evaluated together with MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_COLUMN.', 'When enabled, VAT amounts and related columns are omitted from all generated PDF documents; the layout adapts to exclude tax sections.', '0 (VAT shown) or 1 (VAT hidden from documents)', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '1ed36b66e29fd8a3a8569f3889d406277141f094b898fb627d1ff96057247ad6', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:118|write|dolibarr_set_const($db, \"MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT\", GETPOST(\"MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:502|read|print $form->selectyesno(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT'', getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT''), 1);", "core/modules/supplier_invoice/doc/pdf_canelle.modules.php:128  /* if (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT'') || getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_COLUMN'')) {", "core/modules/commande/doc/pdf_einstein.modules.php:464|check|if (!getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT'') && !getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_COLUMN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_COLUMN', 'string', NULL, 'core', 'Hides the VAT column specifically in generated PDF documents while leaving VAT totals intact.', 'Checked in 23 locations across order, supplier order, proposal, product, and stocktransfer PDF modules. No admin UI write was found; HIDDEN_GUESS is 1. Typically used in conjunction with MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT.', 'When set, the VAT rate/amount column is removed from PDF line item tables without necessarily removing the total VAT section.', '0 (VAT column shown) or 1 (VAT column hidden)', 1, 0, NULL, 1, '5636bd0da6bb32917a43e3541dd4fe521d5d8ba50b8476633f574abf5f57b08c', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/supplier_invoice/doc/pdf_canelle.modules.php:128  /* if (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT'') || getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_COLUMN'')) {", "core/modules/commande/doc/pdf_einstein.modules.php:464|check|if (!getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT'') && !getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_COLUMN'')) {", "core/modules/stock/doc/pdf_standard_stock.modules.php:130|check|if (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT'') || getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_COLUMN'')) {", "modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:1306|check|if (!getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT'') && !getDolGlobalInt(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_COLUMN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_IFNULL', 'string', NULL, 'core', 'When set, suppresses the VAT line from generated PDF documents when the VAT amount is null or zero.', 'Checked in 7 PDF modules (pdf_einstein, pdf_eratosthene, pdf_octopus, pdf_sponge, pdf_aurore, pdf_cyan, pdf_azur) combined with a $tvaisnull condition before rendering the VAT row.', 'Enabling this removes the VAT line from PDFs whenever the computed VAT is null/zero. Disabling (or leaving unset) causes the VAT line to be rendered regardless of the VAT amount.', 'Empty/unset = always show VAT line; any truthy value = hide VAT line when VAT is null or zero.', 1, 0, NULL, 1, '3371753860393ae5ea5a4279d6ca50c97d26f8bd684a191bf85bece70b96a7cd', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_einstein.modules.php:999|if (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_IFNULL'') && $tvaisnull) {", "pdf_eratosthene.modules.php:1261|if (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_IFNULL'') && $tvaisnull) {", "pdf_octopus.modules.php:1719|if (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_IFNULL'') && $tvaisnull) {", "pdf_cyan.modules.php:1354|if (getDolGlobalString(''MAIN_GENERATE_DOCUMENTS_WITHOUT_VAT_IFNULL'') && $tvaisnull) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_INVOICES_WITH_PICTURE', 'string', NULL, 'core', 'Enables inclusion of product pictures in invoice PDF documents.', 'Read via admin/pdf_other.php:503 (select UI) and checked in core/modules/facture/doc/pdf_octopus.modules.php:310, :2472 and core/modules/facture/doc/pdf_sponge.modules.php:244, :2707. The modulebuilder reference at line 1290 is commented out.', 'When enabled, invoice PDF generators include product images in the document output when at least one photo is available.', '0 (no pictures in invoices) or 1 (include pictures in invoices)', 0, 0, 'admin/pdf_other.php', 1, '58310c58223f97d5f390ac4ed08feeecff8a01619686f0f32a886be56146cd8d', 'v2', '2026-04-21T11:16:15+00:00', '["modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:1290  // if (getDolGlobalInt(''MAIN_GENERATE_INVOICES_WITH_PICTURE'') && !empty($this->atleastonephoto)) {", "core/modules/facture/doc/pdf_octopus.modules.php:310|check|if (getDolGlobalString(''MAIN_GENERATE_INVOICES_WITH_PICTURE'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:2472|check|if (getDolGlobalString(''MAIN_GENERATE_INVOICES_WITH_PICTURE'') && !empty($this->atleastonephoto)) {", "admin/pdf_other.php:503|read|print $form->selectarray(\"MAIN_GENERATE_INVOICES_WITH_PICTURE\", $arrval, getDolGlobalString(''MAIN_GENERATE_INVOICES_WITH_PICTURE''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_MYOBJECT_WITH_PICTURE', 'string', NULL, 'modulebuilder', 'Template placeholder constant (in modulebuilder''s PDF generator skeleton) intended to enable including product pictures in the generated object''s PDF lines, but the code reading it is commented out.', 'In modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:214, the check ''if (getDolGlobalInt("MAIN_GENERATE_MYOBJECT_WITH_PICTURE")))'' sits inside a /* ... */ commented-out block that would loop over lines and load a Product object to check for photos.', 'Currently has no effect in this template since the reading code is commented out; if uncommented and adapted in a generated module, it would enable rendering line-level product pictures on the PDF.', 'Boolean-like (read via getDolGlobalInt), currently inert since the code path is commented out in the template.', 0, 0, NULL, 1, 'c9ec58fd8c442b09f8fade87675a731636498a3541d72a5a066024c88d433a1d', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:214|check|if (getDolGlobalInt(''MAIN_GENERATE_MYOBJECT_WITH_PICTURE''))) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_ORDERS_WITH_PICTURE', 'string', NULL, 'core', 'When set, includes product pictures in generated sales order PDF documents.', 'Managed via the admin UI at admin/pdf_other.php as a select array. Checked in pdf_eratosthene.modules.php and pdf_eagle_proforma.modules.php before including product images. In pdf_eratosthene.modules.php, the second check is combined with $this->atleastonephoto.', 'Setting a truthy value causes product images to be embedded in sales order PDFs. Clearing the value omits product pictures.', 'Empty/unset = no pictures in order PDFs; any truthy value = include product pictures.', 0, 0, 'admin/pdf_other.php', 1, 'b2ba6f73204f1f747f09bd86d36308dc1f2361bfcaa86fb61564be3497a85df4', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:381|print $form->selectarray(\"MAIN_GENERATE_ORDERS_WITH_PICTURE\", $arrval, getDolGlobalString(''MAIN_GENERATE_ORDERS_WITH_PICTURE''));", "pdf_eagle_proforma.modules.php:1589|if (getDolGlobalString(''MAIN_GENERATE_ORDERS_WITH_PICTURE'')) {", "pdf_eratosthene.modules.php:207|if (getDolGlobalInt(''MAIN_GENERATE_ORDERS_WITH_PICTURE'')) {", "pdf_eratosthene.modules.php:2031|if (getDolGlobalInt(''MAIN_GENERATE_ORDERS_WITH_PICTURE'') && !empty($this->atleastonephoto)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_PROPOSALS_WITH_PICTURE', 'string', NULL, 'core', 'Enables inclusion of product images in generated proposal PDFs.', 'Written in admin/pdf_other.php at line 96 and displayed as a select at line 301. Checked in pdf_azur.modules.php at lines 223 and 1492 and pdf_cyan.modules.php at lines 200 and 2163 to conditionally render product photos in PDF output.', 'Enabling this constant causes proposal PDFs to include product images when available. Disabling it omits images from proposals.', 'Truthy string to include product pictures; empty/unset to omit pictures.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '44ac78678807f7a24180660f9cee4d5205ae5608e32e285bc19456e30eaa217e', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:96|write|dolibarr_set_const($db, \"MAIN_GENERATE_PROPOSALS_WITH_PICTURE\", GETPOST(\"MAIN_GENERATE_PROPOSALS_WITH_PICTURE\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/propale/doc/pdf_cyan.modules.php:2163|check|if (getDolGlobalString(''MAIN_GENERATE_PROPOSALS_WITH_PICTURE'') && !empty($this->atleastonephoto)) {", "core/modules/propale/doc/pdf_azur.modules.php:1492|check|if (getDolGlobalString(''MAIN_GENERATE_PROPOSALS_WITH_PICTURE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_SHIPMENT_WITH_PICTURE', 'string', NULL, 'core', 'When set, includes product pictures in generated shipment PDF documents.', 'Checked in pdf_rouget.modules.php, pdf_espadon.modules.php, and pdf_squille.modules.php before including product images in the PDF layout. In pdf_espadon.modules.php the check is combined with $this->atleastonephoto to guard the photo rendering section.', 'Enabling this causes product images to be embedded in shipment and reception PDFs. Disabling (or leaving unset) omits product pictures from those documents.', 'Empty/unset = no pictures in shipment PDFs; any truthy value = include product pictures.', 1, 0, NULL, 1, '1b0bcea3fdb748a7327827406498a3b3564ca7f369cfcd89696a84bf85a3cb57', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_rouget.modules.php:211|if (getDolGlobalString(''MAIN_GENERATE_SHIPMENT_WITH_PICTURE'')) {", "pdf_espadon.modules.php:179|if (getDolGlobalString(''MAIN_GENERATE_SHIPMENT_WITH_PICTURE'')) {", "pdf_espadon.modules.php:1423|if (getDolGlobalString(''MAIN_GENERATE_SHIPMENT_WITH_PICTURE'') && !empty($this->atleastonephoto)) {", "pdf_squille.modules.php:172|if (getDolGlobalString(''MAIN_GENERATE_SHIPMENT_WITH_PICTURE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_STOCKTRANSFER_WITH_PICTURE', 'string', NULL, 'core', 'Includes product images in generated stock-transfer PDF documents when enabled.', 'Checked in core/modules/stocktransfer/doc/pdf_eagle.modules.php at lines 219 and 269, and in core/modules/stocktransfer/doc/pdf_eagle_proforma.modules.php:192 to conditionally render product images in the PDF.', 'When set, product images are embedded in stock-transfer PDF output. When unset, images are omitted.', 'Truthy value (e.g. 1) to include product images; 0 or empty to omit them.', 1, 0, NULL, 1, '9434caa1f2cbfaed0765fa3af39abfbe5e114d8145ff14b6a7d7e7c8244d63de', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/stocktransfer/doc/pdf_eagle.modules.php:219|check|if (getDolGlobalString(''MAIN_GENERATE_STOCKTRANSFER_WITH_PICTURE'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:269|check|if (getDolGlobalString(''MAIN_GENERATE_STOCKTRANSFER_WITH_PICTURE'')) {", "core/modules/stocktransfer/doc/pdf_eagle_proforma.modules.php:192|check|if (getDolGlobalString(''MAIN_GENERATE_STOCKTRANSFER_WITH_PICTURE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_SUPPLIER_ORDER_WITH_PICTURE', 'string', NULL, 'core', 'Enables inclusion of product pictures in supplier order PDFs generated by Cornas and Muscadet modules.', 'Checked in pdf_cornas.modules.php at lines 188 and 1625, and in pdf_muscadet.modules.php at line 200. No admin UI write is present.', 'Enabling this causes product images to appear in supplier order PDFs when photos are available; disabling suppresses all images.', 'Truthy (non-empty) = pictures included; empty/unset = no pictures.', 1, 0, NULL, 1, '17699d9c06e0228a1e8c60948a994aab9d54247ebf21ee30cccecb6461f59e39', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_cornas.modules.php:188|check|if (getDolGlobalString(''MAIN_GENERATE_SUPPLIER_ORDER_WITH_PICTURE'')) {", "pdf_muscadet.modules.php:200|check|if (getDolGlobalString(''MAIN_GENERATE_SUPPLIER_ORDER_WITH_PICTURE'')) {", "pdf_cornas.modules.php:1625|check|if (getDolGlobalString(''MAIN_GENERATE_SUPPLIER_ORDER_WITH_PICTURE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GENERATE_SUPPLIER_PROPOSAL_WITH_PICTURE', 'string', NULL, 'core', 'Enables inclusion of product images in supplier proposal PDF documents.', 'When set, product images are included in the PDF generation logic for both the zenith template (core/modules/supplier_proposal/doc/pdf_zenith.modules.php:186 and 1565) and the aurore template (core/modules/supplier_proposal/doc/pdf_aurore.modules.php:198).', 'Enabling this embeds product pictures in supplier proposal PDFs; disabling it omits images.', 'Any non-empty string value enables product image inclusion in supplier proposal PDFs.', 1, 0, NULL, 1, '72378d307361fde4ecf30747df0a9acfb0bb7b9c6327b2e966d8ead9112d8ceb', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/supplier_proposal/doc/pdf_zenith.modules.php:186|check|if (getDolGlobalString(''MAIN_GENERATE_SUPPLIER_PROPOSAL_WITH_PICTURE'')) {", "core/modules/supplier_proposal/doc/pdf_aurore.modules.php:198|check|if (getDolGlobalString(''MAIN_GENERATE_SUPPLIER_PROPOSAL_WITH_PICTURE'')) {", "core/modules/supplier_proposal/doc/pdf_zenith.modules.php:1565|check|if (getDolGlobalString(''MAIN_GENERATE_SUPPLIER_PROPOSAL_WITH_PICTURE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GET_LOCALTAXES_VALUES_FROM_THIRDPARTY', 'string', NULL, 'core', 'Forces local tax rate retrieval from the third-party record rather than the default tax table.', 'The comment at core/lib/functions.lib.php:8130 states ''For some country MAIN_GET_LOCALTAXES_VALUES_FROM_THIRDPARTY is forced to on.'' The constant is programmatically set to 1 at line 8132 for such countries, and checked at line 8136 to route local tax lookups.', 'When active, local tax values are read from the third-party (customer/supplier) record; disabling it reverts to the default tax table lookup.', '0 or empty = local taxes from default table; 1 = local taxes from third-party record (forced for some countries)', 1, 0, NULL, 1, 'fdc910fa403ad43314bd7e58ecd6b1bf40194286fd76ca70ef3313b9adfd99fd', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:8130  // For some country MAIN_GET_LOCALTAXES_VALUES_FROM_THIRDPARTY is forced to on.", "core/lib/functions.lib.php:8132|write|$conf->global->MAIN_GET_LOCALTAXES_VALUES_FROM_THIRDPARTY = 1;", "core/lib/functions.lib.php:8136|check|if (getDolGlobalString(''MAIN_GET_LOCALTAXES_VALUES_FROM_THIRDPARTY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GOOGLE_AD_CLIENT', 'string', NULL, 'public', 'Stores the Google AdSense client ID used to display ads on the Dolibarr public demo page.', 'Checked at public/demo/index.php line 456 (requires both MAIN_GOOGLE_AD_CLIENT and MAIN_GOOGLE_AD_SLOT to be set, and the Google module enabled). Read at line 460 to emit the google_ad_client JavaScript variable. Also referenced at core/lib/security2.lib.php line 292.', 'Setting this constant (together with MAIN_GOOGLE_AD_SLOT) enables Google AdSense ads on the public demo page. Clearing it disables the ad block.', 'String; Google AdSense publisher ID (e.g. ''ca-pub-XXXXXXXXXXXXXXXX''). Both MAIN_GOOGLE_AD_CLIENT and MAIN_GOOGLE_AD_SLOT must be set for ads to appear.', 1, 0, NULL, 1, '3a9fe61d6f4edeebc084d0e5116cc89d3b8a64bdffece084ee5495fadb3b2bac', 'v2', '2026-04-21T13:29:58+00:00', '["public/demo/index.php:456|check|if (isModEnabled(''google'') && getDolGlobalString(''MAIN_GOOGLE_AD_CLIENT'') && getDolGlobalString(''MAIN_GOOGLE_AD_SLOT'')) {", "public/demo/index.php:460|read|print ''google_ad_client = \"'' . getDolGlobalString(''MAIN_GOOGLE_AD_CLIENT'').''\"'';", "core/lib/security2.lib.php:292|read|$main_google_ad_client = ((getDolGlobalString(''MAIN_GOOGLE_AD_CLIENT'') && getDolGlobalString(''MAIN_GOOGLE_AD_SLOT'')) ? 1 : 0);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GOOGLE_AD_HEIGHT', 'string', NULL, 'public', 'Sets the pixel height of the Google AdSense ad block printed on the public demo page.', 'In public/demo/index.php:463, inside the same isModEnabled(''google'') + MAIN_GOOGLE_AD_CLIENT/MAIN_GOOGLE_AD_SLOT gated block as MAIN_GOOGLE_AD_WIDTH, the value of getDolGlobalString(''MAIN_GOOGLE_AD_HEIGHT'') is printed as the ''google_ad_height'' JS variable.', 'Setting it controls the height value written into the Google AdSense JS snippet on the demo/public page; only takes effect if the ''google'' module is enabled and MAIN_GOOGLE_AD_CLIENT/MAIN_GOOGLE_AD_SLOT are also set.', 'Numeric height in pixels, used directly (unquoted) as a JS value.', 1, 0, NULL, 1, '49cd674c93d447d0542303247c1bb607cbb57d8a2ee2341f1f3902adcb765f75', 'v2', '2026-07-24T07:05:23+00:00', '["public/demo/index.php:463: print ''google_ad_height = '' . getDolGlobalString(''MAIN_GOOGLE_AD_HEIGHT'').'';''.\"\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GOOGLE_AD_SLOT', 'string', NULL, 'public', 'Stores the Google AdSense ad-slot ID used to display ads on the Dolibarr public demo page.', 'Checked at public/demo/index.php line 456 (requires both MAIN_GOOGLE_AD_CLIENT and MAIN_GOOGLE_AD_SLOT to be set, and the Google module enabled). Read at line 461 to emit the google_ad_slot JavaScript variable. Also referenced at core/lib/security2.lib.php line 292.', 'Setting this constant (together with MAIN_GOOGLE_AD_CLIENT) enables Google AdSense ads on the public demo page. Clearing it disables the ad block.', 'String; Google AdSense ad slot ID (numeric string). Both MAIN_GOOGLE_AD_CLIENT and MAIN_GOOGLE_AD_SLOT must be set for ads to appear.', 1, 0, NULL, 1, '3d96f753706c698cb26f15d7affd4a93700f46b49ee5e63c7eba8ff3ba133b2a', 'v2', '2026-04-21T13:29:58+00:00', '["public/demo/index.php:456|check|if (isModEnabled(''google'') && getDolGlobalString(''MAIN_GOOGLE_AD_CLIENT'') && getDolGlobalString(''MAIN_GOOGLE_AD_SLOT'')) {", "public/demo/index.php:461|read|print ''google_ad_slot = \"'' . getDolGlobalString(''MAIN_GOOGLE_AD_SLOT'').''\"'';", "core/lib/security2.lib.php:292|read|$main_google_ad_client = ((getDolGlobalString(''MAIN_GOOGLE_AD_CLIENT'') && getDolGlobalString(''MAIN_GOOGLE_AD_SLOT'')) ? 1 : 0);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GOOGLE_AD_WIDTH', 'string', NULL, 'public', 'Sets the pixel width of the Google AdSense ad block printed on the public demo page.', 'In public/demo/index.php:462, inside a block gated by isModEnabled(''google'') plus MAIN_GOOGLE_AD_CLIENT/MAIN_GOOGLE_AD_SLOT, the value of getDolGlobalString(''MAIN_GOOGLE_AD_WIDTH'') is printed as the ''google_ad_width'' JS variable for the AdSense script.', 'Setting it controls the width value written into the Google AdSense JS snippet on the demo/public page; only takes effect if the ''google'' module is enabled and MAIN_GOOGLE_AD_CLIENT/MAIN_GOOGLE_AD_SLOT are also set.', 'Numeric width in pixels, used directly (unquoted) as a JS value.', 1, 0, NULL, 1, 'f79da1e5d17cafc8d9a1988f9825d30533d99368375eda908aaf4cbc8c59f9a7', 'v2', '2026-07-24T07:05:23+00:00', '["public/demo/index.php:462: print ''google_ad_width = '' . getDolGlobalString(''MAIN_GOOGLE_AD_WIDTH'').'';''.\"\\n\";", "public/demo/index.php: if (isModEnabled(''google'') && getDolGlobalString(''MAIN_GOOGLE_AD_CLIENT'') && getDolGlobalString(''MAIN_GOOGLE_AD_SLOT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GOOGLE_AN_ID', 'string', NULL, 'core', 'Stores one or more Google Analytics tracking IDs used to inject GA scripts into pages.', 'Checked and read at core/lib/functions.lib.php:13252-13253. Requires the ''google'' module to be enabled. The value is split by comma to support multiple tracking IDs. Listed in the docblock at line 13031.', 'Setting this constant enables Google Analytics tracking on all pages; leaving it empty disables GA injection.', 'Comma-separated string of Google Analytics tracking IDs (e.g. ''UA-XXXXX-Y,G-XXXXXXXXXX''); empty/unset = no GA tracking', 1, 0, NULL, 1, 'e6d7d994e995a138d570c93e4608a3cef4548d25e5991e31aa4d182f23643ddd', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:13031  * \t\tjs for conf->global->MAIN_GOOGLE_AN_ID", "core/lib/functions.lib.php:13252|check|if (isModEnabled(''google'') && getDolGlobalString(''MAIN_GOOGLE_AN_ID'')) {", "core/lib/functions.lib.php:13253|read|$tmptagarray = explode('','', getDolGlobalString(''MAIN_GOOGLE_AN_ID''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_GRANDTOTAL_LIST_SHOW', 'bool', NULL, 'core', 'Shows a grand-total row at the bottom of list views (via the list_print_total template) when the list is not truncated by pagination.', 'Used in core/tpl/list_print_total.tpl.php:126: if truthy AND the list is not limited (no $limit or $num >= $limit), the grand-total row is printed.', 'Enabling it adds a grand-total summary row to applicable list pages, but only when all matching records fit on the current page (not paginated/truncated).', 'Boolean-like: truthy enables printing the grand-total row when the list is fully shown (not paginated).', 0, 0, NULL, 1, '7f428e6090631ed787710493b1c39c189020f431ba77284a9141150eda39b09c', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/list_print_total.tpl.php:126|check|if (getDolGlobalString(''MAIN_GRANDTOTAL_LIST_SHOW'') && (!(is_null($limit) || $num < $limit))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HELPCENTER_LINKTOUSE', 'string', NULL, 'core', 'Specifies a custom help center URL to display on the login page.', 'Checked at core/lib/security2.lib.php:276 to render a help center link, and read at core/tpl/login.tpl.php:204 to populate $helpcenterlink. Also interacts with MAIN_SECURITY_DISABLEFORGETPASSLINK at security2.lib.php:271. No admin UI is provided.', 'Setting this constant to a URL causes a custom help center link to appear on the login page; leaving it empty hides the help center link.', 'A URL string; empty/unset = no custom help center link shown.', 1, 0, NULL, 1, 'd5f3ded7553564a9a310ca4065f5313f2a02d43228d714fb76d9d9332a2a00b0', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/security2.lib.php:276|check|if (getDolGlobalString(''MAIN_HELPCENTER_LINKTOUSE'')) {", "core/tpl/login.tpl.php:204|read|$helpcenterlink = getDolGlobalString(''MAIN_HELPCENTER_LINKTOUSE'');", "core/lib/security2.lib.php:271|check|if (!getDolGlobalString(''MAIN_SECURITY_DISABLEFORGETPASSLINK'') || getDolGlobalString(''MAIN_HELPCENTER_LINKTOUSE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HELP_DISABLELINK', 'bool', NULL, 'imports', 'Disables the help/documentation link shown in the page toolbar and import pages.', 'Checked at main.inc.php:2319 and used in imports/import.php:1781 and :2275 to suppress help page links. The write in admin/ihm.php:297 is commented out, indicating the setting is managed externally or manually.', 'Enabling this hides help links from the page toolbar and import pages.', '0 or unset = help link shown; 1 (truthy) = help link hidden', 0, 0, 'admin/ihm.php', 1, '75c4beb7cc857f5ac8c9ca594ef114ecb0022b6f731eb2302d4978a4c25ababc', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:297  //dolibarr_set_const($db, \"MAIN_HELP_DISABLELINK\", GETPOST(\"MAIN_HELP_DISABLELINK\", ''aZ09''), ''chaine'', 0, '''', 0); // Param for all entities", "main.inc.php:2319|check|if (!getDolGlobalString(''MAIN_HELP_DISABLELINK'') && !getDolGlobalString(''MAIN_OPTIMIZEFORTEXTBROWSER'')) {", "imports/import.php:1781|read|if ($helppagename && empty($conf->global->MAIN_HELP_DISABLELINK))", "imports/import.php:2275|read|if ($helppagename && empty($conf->global->MAIN_HELP_DISABLELINK))"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT', 'bool', NULL, 'core', 'Hides the ''amount before discount'' column/line on generated PDF documents (orders, invoices, proposals) across multiple PDF models.', 'Checked in core/modules/commande/doc/pdf_einstein.modules.php:124, pdf_eratosthene.modules.php:130, core/modules/facture/doc/pdf_sponge.modules.php:162, and core/modules/propale/doc/pdf_cyan.modules.php:137 / pdf_azur.modules.php:162, each combined with a document-type-specific variant constant (e.g. MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_ORDER).', 'When enabled, the showAmountBeforeDiscount flag is set to 0 in these PDF models, hiding that amount on generated documents.', NULL, 1, 0, NULL, 1, 'aed4b762b5b2d0560e7ecf73c17ef0fe4d5ffd57bb7c7254e6a44be43d6a748b', 'v2', '2026-07-24T06:41:12+00:00', '["$this->showAmountBeforeDiscount = getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT'') || getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_ORDER'') ? 0 : 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_INVOICE', 'bool', NULL, 'core', 'Hides the pre-discount amount and discount amount on invoice PDF documents (pdf_sponge model).', 'Read twice in core/modules/facture/doc/pdf_sponge.modules.php:162-163, combined with the more general MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT and MAIN_HIDE_AMOUNT_DISCOUNT constants.', 'When set, showAmountBeforeDiscount and showDiscountAmount are both forced to 0 on invoice PDFs generated with the pdf_sponge model.', NULL, 1, 0, NULL, 1, 'e5e4d68c850247ad178a845bb04c1893fc7c2f88da401761550adfb402364b00', 'v2', '2026-07-24T06:41:12+00:00', '["$this->showAmountBeforeDiscount = (getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT'') || getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_INVOICE'')) ? 0 : 1;", "$this->showDiscountAmount =  (getDolGlobalInt(''MAIN_HIDE_AMOUNT_DISCOUNT'') || getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_INVOICE'')) ? 0 : 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_ORDER', 'bool', NULL, 'core', 'Hides the pre-discount amount and discount amount on sales order PDF documents (pdf_einstein and pdf_eratosthene models).', 'Read in core/modules/commande/doc/pdf_einstein.modules.php:124-125 and pdf_eratosthene.modules.php:130-131, combined with the more general MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT and MAIN_HIDE_AMOUNT_DISCOUNT constants.', 'When set, showAmountBeforeDiscount and showDiscountAmount are both forced to 0 on order PDFs generated with the einstein or eratosthene models.', NULL, 1, 0, NULL, 1, '7f6b92d4f645b36a107f80b248c09413c78715f1893341c2bf57bb14a2ac3877', 'v2', '2026-07-24T06:41:12+00:00', '["$this->showAmountBeforeDiscount = getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT'') || getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_ORDER'') ? 0 : 1;", "$this->showDiscountAmount =  getDolGlobalInt(''MAIN_HIDE_AMOUNT_DISCOUNT'') || getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_ORDER'') ? 0 : 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_PROPALE', 'bool', NULL, 'core', 'Hides the pre-discount amount and discount amount on commercial proposal PDF documents (pdf_cyan and pdf_azur models).', 'Read in core/modules/propale/doc/pdf_cyan.modules.php:137-138 and pdf_azur.modules.php:162-163, combined with the more general MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT and MAIN_HIDE_AMOUNT_DISCOUNT constants.', 'When set, showAmountBeforeDiscount and showDiscountAmount are both forced to 0 on proposal PDFs generated with the cyan or azur models.', NULL, 1, 0, NULL, 1, '92128cd0376976aca3772910078e7e0c23fddceef72f9643dc565750feb7bc65', 'v2', '2026-07-24T06:41:12+00:00', '["$this->showAmountBeforeDiscount = getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT'') || getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_PROPALE'') ? 0 : 1;", "$this->showDiscountAmount =  getDolGlobalInt(''MAIN_HIDE_AMOUNT_DISCOUNT'') || getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_PROPALE'') ? 0 : 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_AMOUNT_DISCOUNT', 'bool', NULL, 'core', 'Hides the discount amount column/line on generated PDF documents (orders, invoices, proposals) across multiple PDF models.', 'Checked in core/modules/commande/doc/pdf_einstein.modules.php:125, pdf_eratosthene.modules.php:131, core/modules/facture/doc/pdf_sponge.modules.php:163, and core/modules/propale/doc/pdf_cyan.modules.php:138 / pdf_azur.modules.php:163, each combined with a document-type-specific variant constant.', 'When enabled, the showDiscountAmount flag is set to 0 in these PDF models, hiding the discount amount on generated documents.', NULL, 1, 0, NULL, 1, '86aa24ca224be8477aa688f2b1e92feb1da81aff1250cec0c4ea5ea24553d1b6', 'v2', '2026-07-24T06:41:12+00:00', '["$this->showDiscountAmount =  getDolGlobalInt(''MAIN_HIDE_AMOUNT_DISCOUNT'') || getDolGlobalInt(''MAIN_HIDE_AMOUNT_BEFORE_DISCOUNT_ORDER'') ? 0 : 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_INACTIVETAB_ON_PRINT', 'bool', NULL, 'core', 'Hides inactive (non-selected) tabs with a print-only CSS class when printing a Dolibarr page.', 'In core/lib/functions.lib.php:3208, when building the tabs bar (dol_get_fiche_head-style tab rendering), inactive tabs get the ''hideonprint'' CSS class added if this constant is set, so they are hidden in the print stylesheet.', 'Enabling it removes non-active tabs from the printed/PDF-exported view of a tabbed page, keeping only the active tab visible on print.', 'Boolean-like: any truthy value enables hiding of inactive tabs on print.', 1, 0, NULL, 1, '3e09f86df62c65b965de9833d1ccc38a55578b90574c3ec3d54d91b91f3ace15', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3208|read|... ((!$isactive && getDolGlobalString(''MAIN_HIDE_INACTIVETAB_ON_PRINT'')) ? '' hideonprint'' : '''') ..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_LEFT_MENU', 'bool', NULL, 'core', 'Forces the left (vertical) menu to be hidden globally.', 'Read in core/class/conf.class.php:1326-1327: `if (!empty($this->global->MAIN_HIDE_LEFT_MENU)) { $this->dol_hide_leftmenu = (int) (bool) getDolGlobalInt(''MAIN_HIDE_LEFT_MENU''); }`, feeding into the documented property `$dol_hide_leftmenu` (''@var int<0,1> Set if we force param dol_hide_leftmenu into login url''). This is distinct from the per-request URL parameter dol_hide_leftmenu used elsewhere (e.g. collab/index.php, compta/cashcontrol/report.php) but produces the same global effect when set as a constant.', 'Setting it truthy forces the left menu to be hidden application-wide, equivalent to always passing dol_hide_leftmenu=1.', 'Boolean-like (0/1): 1 hides the left menu globally.', 1, 0, NULL, 1, '72e8996617d8626493c2d503d3642b6fe6a0e899412a2012aa51a032702907bd', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1326: if (!empty($this->global->MAIN_HIDE_LEFT_MENU)) {", "core/class/conf.class.php:1327: $this->dol_hide_leftmenu = (int) (bool) getDolGlobalInt(''MAIN_HIDE_LEFT_MENU'');", "core/class/conf.class.php:163: * @var int<0,1> Set if we force param dol_hide_leftmenu into login url"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_LINK_BY_REF_IN_LINKTO', 'bool', NULL, 'core', 'Controls whether the ''link by reference'' feature is visible and functional in the link-to UI.', 'Checked in core/actions_dellink.inc.php:57 and core/class/html.form.class.php:10634, 10664, and 10730 to gate display and processing of the link-by-reference input in the object linking form.', 'When set, the link-by-reference input is hidden and the corresponding action is not processed; when unset, the feature is shown and operational.', 'Empty/unset = feature enabled; non-empty = feature hidden.', 1, 0, NULL, 1, '10044bf12e24091f682b7943a107d9079c5f1433b81d2ec9188c120c7e3052f4', 'v2', '2026-04-21T11:16:15+00:00', '["core/actions_dellink.inc.php:57|check|if ($action == ''addlinkbyref'' && !empty($permissiondellink) && !$cancellink && $id > 0 && !empty($addlinkref) && !getDolGlobalString(''MAIN_HIDE_LINK_BY_REF_IN_LINKTO'')) {", "core/class/html.form.class.php:10634|check|if (!getDolGlobalString(''MAIN_HIDE_LINK_BY_REF_IN_LINKTO'')) {", "core/class/html.form.class.php:10664|check|if (getDolGlobalString(''MAIN_HIDE_LINK_BY_REF_IN_LINKTO'')) {", "core/class/html.form.class.php:10730|check|if ($num > 0 || !getDolGlobalString(''MAIN_HIDE_LINK_BY_REF_IN_LINKTO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_MESSAGES_ON_CARD', 'bool', NULL, 'ticket', 'Hides the right-hand ''full conversation / full list'' messaging block on the ticket card when set.', 'Used in ticket/card.php:1693: `if (!getDolGlobalString(''MAIN_HIDE_MESSAGES_ON_CARD'')) { print ''<div class="fichehalfright">''; ... FullConversation / FullList buttons ... }` — the block is only rendered when the constant is falsy.', 'When enabled, the right-column messaging summary (links to FullConversation/FullList) is removed from the ticket card display.', 'Boolean (getDolGlobalString truthiness): truthy hides the messages block on the card; falsy/unset shows it (default behavior).', 1, 0, NULL, 1, '3f306f7fd4110cd82b18ec03da78a6643982e0920449ff7cb8851e478983d39f', 'v2', '2026-07-24T07:05:23+00:00', '["ticket/card.php:1693: if (!getDolGlobalString(''MAIN_HIDE_MESSAGES_ON_CARD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_POWERED_BY', 'bool', NULL, 'public', 'Hides the ''Powered by Dolibarr'' branding notice on public-facing pages.', 'Checked as a negated condition across 12+ occurrences in public pages (public/recruitment, public/project, public/eventorganization, core/lib/company.lib.php). When set, the branding block is not rendered.', 'Setting this constant removes the Dolibarr branding footer from all public portal pages; unsetting it restores the notice.', 'Any truthy value hides the branding; unset displays it.', 1, 0, NULL, 1, '5e515e62204981f85fad70d24852dbba0fc4e4b4403feff9a14e400b84d7e0fb', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/company.lib.php:2878|check|if (!getDolGlobalString(''MAIN_HIDE_POWERED_BY'')) {", "public/recruitment/view.php:358|check|if (!getDolGlobalString(''MAIN_HIDE_POWERED_BY'')) {", "public/project/index.php:155|check|if (!getDolGlobalString(''MAIN_HIDE_POWERED_BY'')) {", "public/eventorganization/subscriptionok.php:137|check|if (!getDolGlobalString(''MAIN_HIDE_POWERED_BY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_TOP_MENU', 'bool', NULL, 'core', 'Forces the top menu bar to be hidden globally.', 'Read in core/class/conf.class.php:1323-1324: `if (!empty($this->global->MAIN_HIDE_TOP_MENU)) { $this->dol_hide_topmenu = (int) (bool) getDolGlobalInt(''MAIN_HIDE_TOP_MENU''); }`, feeding into the documented property `$dol_hide_topmenu` (''@var int<0,1> Set if we force param dol_hide_topmenu into login url''). This is distinct from the per-request URL parameter dol_hide_topmenu used elsewhere (e.g. core/lib/functions.lib.php, collab/index.php) but produces the same global effect when set as a constant.', 'Setting it truthy forces the top menu to be hidden application-wide, equivalent to always passing dol_hide_topmenu=1.', 'Boolean-like (0/1): 1 hides the top menu globally.', 1, 0, NULL, 1, '64c2d2ad1c902a111b11c5a0f3d3c53cf83726a57c200e3a37833bcab3ab20fa', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1323: if (!empty($this->global->MAIN_HIDE_TOP_MENU)) {", "core/class/conf.class.php:1324: $this->dol_hide_topmenu = (int) (bool) getDolGlobalInt(''MAIN_HIDE_TOP_MENU'');", "core/class/conf.class.php:158: * @var int<0,1> Set if we force param dol_hide_topmenu into login url"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_VERSION', 'bool', NULL, 'core', 'Hides the Dolibarr version number from the page footer.', 'Read in admin/ihm.php:529 as a yes/no select, and checked at main.inc.php:2375 where the version is shown only when this is 0.', 'Setting to 1 suppresses the version display in the footer; setting to 0 or unsetting shows the version.', '0 = version shown (default); 1 = version hidden', 0, 0, 'admin/ihm.php', 1, 'ec0346eb789f9539300dbf8bf775613fb9474e13348115a31bee3095f734f753', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:529|read|print $form->selectyesno(''MAIN_HIDE_VERSION'',$conf->global->MAIN_HIDE_VERSION,1);", "main.inc.php:2375|check|if (!getDolGlobalString(''MAIN_OPTIMIZEFORTEXTBROWSER'') && getDolGlobalInt(''MAIN_HIDE_VERSION'') == 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HIDE_WARNING_TO_ENCOURAGE_SMTP_SETUP', 'bool', NULL, 'admin', 'Suppresses the warning message that encourages administrators to configure SMTP when the default PHP mail() sender is active.', 'Checked in admin/mails.php:717 and core/menus/standard/eldy.lib.php:1204 paired with MAIN_MAIL_SENDMODE. Set to 1 via dolibarr_set_const in admin/mails.php:140. A comment at admin/mails.php:716 notes the constant is treated as 1 by default if not set.', 'Setting this to 1 hides the SMTP setup nudge from the mail admin page and the navigation menu. Unsetting it restores the warning.', 'Note MAIN_HIDE_WARNING_TO_ENCOURAGE_SMTP_SETUP is set to 1 by default if not set. 1 = hide warning; absent/0 = show warning.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php', 1, '132bcb510ffde3e967a5dfcf6411fc94c28fb778df2bcc1406240123322bbe27', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:716  // Note MAIN_HIDE_WARNING_TO_ENCOURAGE_SMTP_SETUP is set to 1 by default if not set", "admin/mails.php:717|check|if (getDolGlobalString(''MAIN_MAIL_SENDMODE'', ''mail'') == ''mail'' && getDolGlobalString(''MAIN_HIDE_WARNING_TO_ENCOURAGE_SMTP_SETUP'')) {", "admin/mails.php:140|write|dolibarr_set_const($db, ''MAIN_HIDE_WARNING_TO_ENCOURAGE_SMTP_SETUP'', 1, ''chaine'', 1, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HOME', 'string', NULL, 'admin', 'Stores the HTML content displayed on the Dolibarr home/login page as a custom welcome message.', 'Written via admin/ihm.php:296 using dol_htmlcleanlastbr and restricted HTML input. Read in core/lib/security2.lib.php:286 via make_substitutions and displayed on the login page when set (checked at line 283). Edited in admin/ihm.php:713 via DolEditor.', 'If set to HTML content, that content is rendered on the home/login page after variable substitutions. Clearing it removes the custom welcome message.', 'HTML string with optional substitution variables. Empty/unset = no custom home message.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'f1affc143c5fbd22aaa8750d7e1d946a361be68b1e4de96ef5bd4d11f5def9f7', 'v2', '2026-04-21T13:29:58+00:00', '["admin/ihm.php:296|write|dolibarr_set_const($db, \"MAIN_HOME\", dol_htmlcleanlastbr(GETPOST(\"main_home\", ''restricthtml'')), ''chaine'', 0, '''', $conf->entity);", "core/lib/security2.lib.php:283|check|if (getDolGlobalString(''MAIN_HOME'')) {", "core/lib/security2.lib.php:286|read|$texttoshow = make_substitutions(getDolGlobalString(''MAIN_HOME''), $substitutionarray, $langs);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HOME_PAGE', 'string', NULL, 'core', 'Sets the default landing page (URL/relative path) users are redirected to after login, unless overridden per-user.', 'Read in core/menus/standard/eldy.lib.php:77 via getDolUserString(''MAIN_HOME_PAGE'', getDolGlobalString(''MAIN_HOME_PAGE'')): the per-user MAIN_HOME_PAGE setting takes priority, falling back to this global value; non-admin users with a homepage set are redirected there instead of index.php.', 'Setting it changes the default home page path non-admin users land on (via dol_buildpath) instead of the standard /index.php dashboard; admins always use the default index.php regardless.', 'String: a relative module path (passed to dol_buildpath), e.g. ''/mymodule/index.php''.', 1, 0, NULL, 1, 'dff6a02262eda42a8d0f0272b6f9dd6476e0ff53830821e00c3c59c8df7e9a95', 'v2', '2026-07-24T07:05:23+00:00', '["core/menus/standard/eldy.lib.php:77: $homepage = getDolUserString(''MAIN_HOME_PAGE'', getDolGlobalString(''MAIN_HOME_PAGE''));", "core/menus/standard/eldy.lib.php:78: if (!empty($homepage) && !$user->admin) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HOOK_DEBUG', 'string', NULL, 'core', 'Enables debug logging for the hook manager, outputting information about hook execution.', 'Checked via getDolGlobalInt at core/class/hookmanager.class.php:322 and 371. When set to a non-zero value, hook invocation details are written to the debug output.', 'Enabling this constant produces verbose hook execution traces useful for module development; it should be disabled in production.', '0 or empty = hook debug disabled; any non-zero integer = hook execution debug output enabled', 1, 0, NULL, 1, '9b2509a04c1a742de6c7dc6c58a17f88c54be3fa60330dccc7481ca72cccaea3', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/hookmanager.class.php:322|check|if (getDolGlobalInt(''MAIN_HOOK_DEBUG'')) {", "core/class/hookmanager.class.php:371|check|if (getDolGlobalInt(''MAIN_HOOK_DEBUG'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HTML_FOOTER', 'string', NULL, 'core', 'Injects custom HTML content into the footer of Dolibarr pages, including login and authentication pages.', 'Read at core/tpl/login.tpl.php:600, core/tpl/passwordforgotten.tpl.php:349, core/tpl/passwordreset.tpl.php:373, and core/lib/functions.lib.php:13060 where the value is printed directly. Also referenced in a docblock at core/lib/functions.lib.php:13029.', 'When set, the raw HTML string is output at the bottom of the page body on login, password-forgotten, password-reset, and main application pages.', 'Any valid HTML string', 1, 0, NULL, 1, '713ca74d9bc01a9f8adb18f0d9d4dc4b521903810f0f29db51a4489805b56612', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/functions.lib.php:13029  * \t\tconf->global->MAIN_HTML_FOOTER", "core/lib/functions.lib.php:13060|read|print getDolGlobalString(''MAIN_HTML_FOOTER'') . \"\\n\";", "core/tpl/login.tpl.php:600|read|print getDolGlobalString(''MAIN_HTML_FOOTER'');", "core/tpl/passwordforgotten.tpl.php:349|read|print getDolGlobalString(''MAIN_HTML_FOOTER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HTML_HEADER', 'string', NULL, 'core', 'Stores additional HTML content injected into the <head> section of every Dolibarr page.', 'Initialized in main.inc.php:211-212 if unset, appended to via main.inc.php:214 from renderers, and printed in main.inc.php:2129. Five occurrences in one file. No admin UI write is present.', 'Setting this constant causes its content to be output inside the HTML head element on every page, allowing custom meta tags, scripts, or styles to be injected globally.', 'Any valid HTML string intended for the <head> section; unset results in an empty string being used.', 1, 0, NULL, 1, '8bd18ecf1f94b77cdbc5f59e99e192594ec1b685406549d234fbedfe5dd5b7a0', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:211|check|if (!getDolGlobalString(''MAIN_HTML_HEADER'')) {", "main.inc.php:212|write|$conf->global->MAIN_HTML_HEADER = '''';", "main.inc.php:2129|read|print getDolGlobalString(''MAIN_HTML_HEADER'') . \"\\n\";", "main.inc.php:214|read|$conf->global->MAIN_HTML_HEADER .= $renderer->renderHead();"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_HTML_TITLE', 'string', NULL, 'societe', 'Customizes the HTML page title format shown in the browser (e.g. showing only the project or thirdparty name).', 'Checked in many pages such as projet/document.php:117, projet/contact.php:346, projet/card.php:643, fourn/card.php:225, and societe/paymentmodes.php:909, using preg_match against patterns like ''projectnameonly'' or ''thirdpartynameonly''; documented at core/class/conf.class.php:1029.', 'Setting a value like ''projectnameonly'' or ''thirdpartynameonly'' changes the HTML title to show only that name instead of the default composed title.', '''projectnameonly'' = show only project name; ''thirdpartynameonly'' = show only thirdparty name; ''ordernamonly'' = show only order name', 0, 0, NULL, 1, 'a47e8ea551038c6b32b5842247bc03fc63fb4179e14595e203b09471d1324783', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_HTML_TITLE'') && preg_match(''/projectnameonly/'', getDolGlobalString(''MAIN_HTML_TITLE'')) && $object->name) {", "if (getDolGlobalString(''MAIN_HTML_TITLE'') && preg_match(''/thirdpartynameonly/'', getDolGlobalString(''MAIN_HTML_TITLE'')) && $object->name) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_IBAN_IS_NEVER_MANDATORY', 'string', NULL, 'compta', 'Forces both IBAN and BIC to never be considered mandatory on a bank account, overriding country-based mandatory rules.', 'Checked in compta/bank/class/account.class.php in both needIBAN() (line 1809) and needBIC() (line 1864): when set, both methods return 0 (not mandatory) immediately, bypassing further country-specific logic.', 'When set, bank account forms/validations will never require IBAN or BIC to be filled in, regardless of country; when unset, mandatoriness follows the normal country-based rules implemented further in needIBAN()/needBIC().', 'Not set/falsy (default): IBAN/BIC mandatoriness determined by country rules. Truthy: IBAN/BIC never mandatory (both needIBAN() and needBIC() return 0).', 1, 0, NULL, 1, '071e1624ce39d954de13f52d765e7ab77e2a57d58c0143a22d2527e384606cf4', 'v2', '2026-07-24T07:05:23+00:00', '["compta/bank/class/account.class.php:1809|check|if (getDolGlobalString(''MAIN_IBAN_IS_NEVER_MANDATORY'')) { return 0; }", "compta/bank/class/account.class.php:1864|check|if (getDolGlobalString(''MAIN_IBAN_IS_NEVER_MANDATORY'')) { return 0; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_IGNORE_CONTACTS_ON_CLONING', 'string', NULL, 'comm', 'Skips copying internal contacts when cloning a commercial proposal.', 'Checked in comm/propal/class/propal.class.php:1616 right after the object is cloned; when not set, copy_linked_contact($this, ''internal'') is called to copy internal contacts to the new proposal.', 'Setting it to true means a cloned proposal will NOT inherit the internal contacts of the source proposal (external contacts copying, governed separately, is unaffected by this constant).', 'Boolean-like: true/1 skips copying internal contacts on cloning (inferred from negation in the if-condition).', 1, 0, NULL, 1, 'a54898291f9c4d7e4663f782c711a23575d3e3b301e934e96daee0eafd1f3b33', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/class/propal.class.php:1616|check|if (!$error && !getDolGlobalInt(''MAIN_IGNORE_CONTACTS_ON_CLONING'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_IHM_CUSTOM_CSS', 'string', NULL, 'admin', 'Stores custom CSS content that is injected into every page of the Dolibarr interface.', 'When set, custom CSS is output directly into page responses via theme/custom.css.php:58. It is written via admin/ihm.php:341 and read in main.inc.php:1970 before being applied. Configurable through the admin UI at admin/ihm.php.', 'Changing this value immediately affects the visual appearance of all pages. Clearing it removes any custom CSS overrides.', 'Any valid CSS string; empty or unset means no custom CSS is applied.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '1ff200588e26f10ef099421984003e7c40b14c34e4344bf99078ba6fd436eb8e', 'v2', '2026-04-21T11:16:15+00:00', '["theme/custom.css.php:58|read|print getDolGlobalString(''MAIN_IHM_CUSTOM_CSS'');", "main.inc.php:1970|check|if (getDolGlobalString(''MAIN_IHM_CUSTOM_CSS'')) {", "admin/ihm.php:341|write|dolibarr_set_const($db, \"MAIN_IHM_CUSTOM_CSS\", $csscontent, ''chaine'', 0, '''', $conf->entity);", "admin/ihm.php:757|read|$customcssValue = getDolGlobalString(''MAIN_IHM_CUSTOM_CSS'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_IHM_PARAMS_REV', 'string', NULL, 'modulebuilder', 'An integer revision counter incremented whenever UI/IHM parameters or module configurations are changed.', 'Incremented by dolibarr_set_const in admin/ihm.php (lines 93, 119, 270, 349) and admin/modules.php (lines 428, 452, 460, 469) whenever UI settings change. Refreshed before forging parameter lines as noted at main.inc.php:1792.', 'Incrementing this value forces browsers to reload cached UI assets; it is managed automatically by the admin interface.', 'Integer; auto-incremented on each UI parameter save', 0, 0, 'admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/modules.php|admin/modules.php|admin/modules.php|admin/modules.php|admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/modules.php|admin/modules.php|admin/modules.php|admin/modules.php', 1, '8c84df11d0534cb8f853825e07da6c7b9e99b3b18b5139e02b386ea78940a78f', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1792  // Refresh value of MAIN_IHM_PARAMS_REV before forging the parameter line.", "admin/ihm.php:93|write|dolibarr_set_const($db, \"MAIN_IHM_PARAMS_REV\", getDolGlobalInt(''MAIN_IHM_PARAMS_REV'') + 1, ''chaine'', 0, '''', $conf->entity);", "admin/modules.php:428|write|dolibarr_set_const($db, \"MAIN_IHM_PARAMS_REV\", getDolGlobalInt(''MAIN_IHM_PARAMS_REV'') + 1, ''chaine'', 0, '''', $conf->entity);", "admin/modules.php:469|write|dolibarr_set_const($db, \"MAIN_IHM_PARAMS_REV\", (getDolGlobalInt(''MAIN_IHM_PARAMS_REV'') + 1), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_IMAGE_PUBLIC_PAYMENT', 'string', NULL, 'public', 'Specifies the URL of an image displayed on public payment pages (new payment, payment OK, payment KO).', 'Checked and read at public/payment/newpayment.php:1056-1058, public/payment/paymentok.php:279-281, and public/payment/paymentko.php:315-317; when set, an img element is rendered with this URL as the src. No admin UI write found.', 'When set, the specified image is shown on all public payment status pages; when unset, no image is displayed.', 'A URL string pointing to an image; empty/unset means no image is shown.', 1, 0, NULL, 1, 'dc9d6f52ccc7536c964d562270862e92d498ff5ce435e9666c5e2c4a97ce3952', 'v2', '2026-04-21T13:50:40+00:00', '["public/payment/paymentko.php:315|check|if (getDolGlobalString(''MAIN_IMAGE_PUBLIC_PAYMENT'')) {", "public/payment/newpayment.php:1058|read|print ''<img id=\"idMAIN_IMAGE_PUBLIC_PAYMENT\" src=\"''.getDolGlobalString(''MAIN_IMAGE_PUBLIC_PAYMENT'').''\">'';", "public/payment/paymentok.php:281|read|print ''<img id=\"idMAIN_IMAGE_PUBLIC_PAYMENT\" src=\"'' . getDolGlobalString(''MAIN_IMAGE_PUBLIC_PAYMENT'').''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_IMAP_USE_PHPIMAP', 'bool', NULL, 'emailcollector', 'Switches the email collector to use the PHP IMAP library instead of the native IMAP extension.', 'Documented at admin/emailcollector_list.php:781: ''MAIN_IMAP_USE_PHPIMAP: Enable use of the PHP Imap library''. Configured via a selectarray in admin/emailcollector_list.php:791 and checked throughout emailcollector/class/emailcollector.class.php at 8+ locations to branch all IMAP connection and mail-fetch logic.', 'Enabling this constant causes all email collection operations to use the PHP IMAP library code path instead of native IMAP functions; disabling it uses the native path.', 'Any truthy value enables the PHP IMAP library; 0 or unset uses native IMAP.', 0, 0, 'admin/emailcollector_card.php|admin/emailcollector_card.php|admin/emailcollector_list.php', 1, '7518c4928ef105634168c6545ac7559228acc18bbb6f62bad309b5c339bdc660', 'v2', '2026-04-21T13:29:58+00:00', '["admin/emailcollector_list.php:781  // MAIN_IMAP_USE_PHPIMAP: Enable use of the PHP Imap library", "admin/emailcollector_list.php:791|read|print $form->selectarray(\"MAIN_IMAP_USE_PHPIMAP\", $arrval, getDolGlobalString(\"MAIN_IMAP_USE_PHPIMAP\"));", "emailcollector/class/emailcollector.class.php:1210|check|if (getDolGlobalString(''MAIN_IMAP_USE_PHPIMAP'')) {", "admin/emailcollector_card.php:613|read|$morehtml = $form->textwithpicto($langs->trans(\"NbOfEmailsInInbox\"), ''Connect string = ''.$connectstringserver.''<br>Option MAIN_IMAP_USE_PHPIMAP = ''.getDolGlobalInt(''MAIN_IMAP_USE_P"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INCLUDE_GLOBAL_STATS_IN_OPENED_DASHBOARD', 'string', NULL, 'theme', 'When enabled (together with MAIN_DISABLE_GLOBAL_BOXSTATS being unset), shows the global statistics box inside the opened dashboard.', 'Checked in theme/eldy/info-box.inc.php:254 and theme/md/info-box.inc.php:400, always in conjunction with the negation of MAIN_DISABLE_GLOBAL_BOXSTATS. No admin UI write path is present in the payload.', 'Enabling this constant (while MAIN_DISABLE_GLOBAL_BOXSTATS is unset) causes the global statistics box to be rendered in the dashboard. Leaving it unset suppresses the box regardless of MAIN_DISABLE_GLOBAL_BOXSTATS.', 'Truthy value to show global stats box in dashboard; unset or 0 to hide.', 1, 0, NULL, 1, '7c17ce1d48a1596f030fac4541b4ae20c83efccf037b8aa5492a9c10be107260', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/info-box.inc.php:254|check|<?php if (!getDolGlobalString(''MAIN_DISABLE_GLOBAL_BOXSTATS'') && getDolGlobalString(''MAIN_INCLUDE_GLOBAL_STATS_IN_OPENED_DASHBOARD'')) { ?>", "theme/md/info-box.inc.php:400|check|<?php if (!getDolGlobalString(''MAIN_DISABLE_GLOBAL_BOXSTATS'') && getDolGlobalString(''MAIN_INCLUDE_GLOBAL_STATS_IN_OPENED_DASHBOARD'')) { ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_ACCOUNTANT_ADDRESS', 'string', NULL, 'admin', 'Stores the street address of the company''s accountant.', 'Written via admin/subcontractors.php:66 and read at line 160 to display the accountant address in the admin form.', 'Changing this value updates the accountant address for the entity.', 'String: street address.', 0, 0, 'admin/subcontractors.php|admin/subcontractors.php', 1, '578cef0f68aed06fd360753a43f3c17c7260a1cf0a8dcffc1f6292a3cb63236e', 'v2', '2026-04-21T13:50:40+00:00', '["admin/subcontractors.php:66|write|dolibarr_set_const($db, \"MAIN_INFO_ACCOUNTANT_ADDRESS\", GETPOST(\"address\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/subcontractors.php:160|read|print dolPrintText(GETPOSTISSET(''address'') ? GETPOST(''address'', ''alphanohtml'') : getDolGlobalString(''MAIN_INFO_ACCOUNTANT_ADDRESS''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_ACCOUNTANT_CODE', 'string', NULL, 'admin', 'Stores the accountant/subcontractor identification code used in accounting journal exports.', 'Configured via admin/subcontractors.php (written at line 77, read in the form at line 216). Used in accountancy/tpl/export_journal.tpl.php:49 to populate the $code variable for journal file generation.', 'Changing this value updates the accountant code embedded in exported accounting journal files.', 'Free string; the accountant''s identification code', 0, 0, 'admin/subcontractors.php|admin/subcontractors.php', 1, '5a7045d85b9c285edae249445dab6c9abf8fd855edc8576b86ad96ded7de55d5', 'v2', '2026-04-21T11:16:15+00:00', '["admin/subcontractors.php:77|write|dolibarr_set_const($db, \"MAIN_INFO_ACCOUNTANT_CODE\", GETPOST(\"code\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "accountancy/tpl/export_journal.tpl.php:49|read|$code = getDolGlobalString(''MAIN_INFO_ACCOUNTANT_CODE'');"]', 'medium', NULL);
