INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_ACCOUNTANT_REGION', 'string', NULL, 'admin', 'Stores the region code of the company''s accountant, part of the accountant contact-info block used for the ''Third parties surveillance'' (subcontractors/experts) admin setup.', 'Written from admin/subcontractors.php:103 via dolibarr_set_const() from GETPOST(''region_code'',''alphanohtml''), alongside sibling constants MAIN_INFO_ACCOUNTANT_NAME/ADDRESS/TOWN/ZIP/STATE/COUNTRY/PHONE/MAIL/WEB/IDPROF1/IDPROF2/CODE/NOTE that together define the accountant''s identity/contact card.', 'Changing it changes the region value stored for the accountant contact block configured on the subcontractors/experts admin page; no further consuming code was inspected.', 'A region code string (from a region selector, ''region_code'' POST field).', 0, 0, 'admin/subcontractors.php', 1, 'cd84ee7cd341ec4575f129aa7fdff7444e27282460f32facc8936466322df109', 'v2', '2026-07-24T07:05:23+00:00', '["admin/subcontractors.php:103|write|dolibarr_set_const($db, \"MAIN_INFO_ACCOUNTANT_REGION\", GETPOST(\"region_code\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
