INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_CAPITAL', 'string', NULL, 'admin', 'Stores the share capital amount of the company.', 'Written via admin/company.php at line 226 and displayed in the admin form at line 604. Read in societe/class/societe.class.php at line 4898 and converted to a float using price2num.', 'Changing this constant updates the capital amount used in company records and documents.', 'Numeric string representing the capital amount', 0, 0, 'admin/company.php|admin/company.php', 1, '27523dd9d1ae3ee2cfc6c101ea4bf699cc81c9b9c26093dfa471d528d0d4d271', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:226|write|dolibarr_set_const($db, \"MAIN_INFO_CAPITAL\", GETPOST(\"capital\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "societe/class/societe.class.php:4898|read|$this->capital = is_numeric(price2num(getDolGlobalString(''MAIN_INFO_CAPITAL''))) ? (float) price2num(getDolGlobalString(''MAIN_INFO_CAPITAL'')) : null;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_CONTRACT_TERMSOFSALE', 'string', NULL, 'admin', 'Stores the filename of a terms-of-sale document to append/reference on generated contract PDFs.', 'Set/read via admin/pdf_other.php:456-457, and used in core/modules/contract/doc/pdf_strato.modules.php:494-495 (combined with MAIN_PDF_ADD_TERMSOFSALE_CONTRACT) and contrat/card.php:2502 in a tooltip message about file concatenation.', 'When set, this filename is used as the terms-of-sale document that gets concatenated to the contract PDF, provided MAIN_PDF_ADD_TERMSOFSALE_CONTRACT is also enabled.', NULL, 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '484fa52fc06174776fe52e9c6d21e9bc51fba77a080d410e9b55f0b868ce4370', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_INFO_CONTRACT_TERMSOFSALE'')) {", "if (getDolGlobalString(''MAIN_INFO_CONTRACT_TERMSOFSALE'') && getDolGlobalInt(''MAIN_PDF_ADD_TERMSOFSALE_CONTRACT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_EUID', 'string', NULL, 'societe', 'Stores the company''s European Unique Identifier (EUID) used in the company profile.', 'Read into Societe::$euid in societe/class/societe.class.php:4864, alongside other company profile fields like MAIN_INFO_APE and MAIN_INFO_RCS set from the company setup screen.', 'Changing the value updates the EUID shown/printed for the company record; no other logic branches on it in this occurrence.', 'Free text string, the company''s EUID identifier.', 0, 0, NULL, 1, 'dd153a17e48d043a63b5ac63dafa3412ef5cb14cdcb88a9a0e5e00c2d6e61eeb', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4864|read|$this->euid = getDolGlobalString(''MAIN_INFO_EUID'');"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_GDPR', 'string', NULL, 'admin', 'Stores the name or contact information of the GDPR data protection officer for the company.', 'Written at admin/company.php:225 from the POST ''MAIN_INFO_GDPR'' field. Displayed as an editable text input at admin/company.php:600 with the field id ''infodirector''. Managed via the admin company setup UI.', 'Changing this value updates the GDPR contact information stored for the company entity.', 'Any alphanumeric string (name/contact of GDPR officer); empty = no GDPR contact defined', 0, 0, 'admin/company.php|admin/company.php', 1, 'e5bd28cd8ab8b754c5594d316fd4490cf48b90157002718435b8355eef18ee42', 'v2', '2026-04-21T13:29:58+00:00', '["admin/company.php:225|write|dolibarr_set_const($db, \"MAIN_INFO_GDPR\", GETPOST(\"MAIN_INFO_GDPR\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/company.php:600|read|print ''<input name=\"MAIN_INFO_GDPR\" id=\"infodirector\" class=\"minwidth300\" value=\"''.dolPrintHTMLForAttribute((GETPOSTISSET(\"MAIN_INFO_GDPR\") ? GETPOST(\"MAIN_INFO_GDPR\", ''alphanohtml"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_INVOICE_TERMSOFSALE', 'string', NULL, 'admin', 'Specifies the filename of the terms-of-sale document to be appended to invoice PDFs when MAIN_PDF_ADD_TERMSOFSALE_INVOICE is enabled.', 'Read in core/modules/facture/doc/pdf_octopus.modules.php:1038 and pdf_sponge.modules.php:1108 as the terms-of-sale filename. Also read and displayed in admin/pdf_other.php:534-535 and compta/facture/card.php:6926 as a tooltip. Configurable via admin/pdf_other.php.', 'Setting this constant to a valid filename causes that file to be concatenated to generated invoice PDFs when terms-of-sale appending is enabled.', 'String filename of the terms-of-sale document; empty/unset = no file is appended.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '5441fb7cf474c8de500d5a80fbec831031e14b0161ef826f6a1ee6cbe5d82c5e', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/facture/doc/pdf_octopus.modules.php:1038|read|$termsofsalefilename = getDolGlobalString(''MAIN_INFO_INVOICE_TERMSOFSALE'');", "core/modules/facture/doc/pdf_sponge.modules.php:1108|read|$termsofsalefilename = getDolGlobalString(''MAIN_INFO_INVOICE_TERMSOFSALE'');", "admin/pdf_other.php:535|read|$termofsale = getDolGlobalString(\"MAIN_INFO_INVOICE_TERMSOFSALE\");", "compta/facture/card.php:6926|read|$tooltipAfterComboOfModels = $langs->trans(\"AccordingToYourSetupTheFileWillBeConcatenated\", getDolGlobalString(''MAIN_INFO_INVOICE_TERMSOFSALE''));"]', 'high', NULL);
