INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_ITPROVIDER_IDPROF2', 'string', NULL, 'blockedlog', 'Stores the IT provider''s professional ID (idprof2) used in company subcontractor and blocked-log registration settings.', 'Set via admin/subcontractors.php:126 and blockedlog/admin/registration.php:233 (both dolibarr_set_const); read in blockedlog/admin/registration.php:486/603, admin/subcontractors.php:340, and main.inc.php:4118.', 'Changing it updates the IT provider idprof2 value used both on the subcontractors admin page and in blocked-log registration data.', NULL, 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|admin/subcontractors.php|blockedlog/admin/registration.php|admin/subcontractors.php', 1, '92528a59aa30c3fad7bb28530f200e420054af51246719310d04b1afbcfdcd87', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, \"MAIN_INFO_ITPROVIDER_IDPROF2\", GETPOST(\"itprovider_idprof2\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "''provider_idprof2'' => getDolGlobalString(''MAIN_INFO_ITPROVIDER_IDPROF2'')"]', 'high', NULL);
