INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_ITPROVIDER_NAME', 'string', NULL, 'blockedlog', 'Stores the name of the IT provider (subcontractor) associated with this Dolibarr instance.', 'Set via admin UI at blockedlog/admin/registration.php and admin/subcontractors.php. Used in registration payloads sent to the blockedlog authority and displayed in subcontractor admin pages. Read at blockedlog/lib/blockedlog.lib.php:151 with the comment ''Can be myself''.', 'Changing this value updates the provider name transmitted in blockedlog registration data and shown in the subcontractors admin form.', 'Any string; the comment notes it can be ''myself''.', 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/registration.php|admin/subcontractors.php|blockedlog/admin/registration.php|admin/subcontractors.php', 1, 'c67ea17a7ec892a7999b7b04b7cd0364e72b05fa17565dc341d9d90fee88e711', 'v2', '2026-04-21T11:16:15+00:00', '["''provider_name'' => getDolGlobalString(''MAIN_INFO_ITPROVIDER_NAME''),", "$providerset = getDolGlobalString(''MAIN_INFO_ITPROVIDER_NAME'');\t// Can be ''myself''", "$res = dolibarr_set_const($db, \"MAIN_INFO_ITPROVIDER_NAME\", $provider_name, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_ITPROVIDER_NOTE', 'string', NULL, 'admin', 'Stores a free-text note about the IT provider associated with the Dolibarr instance.', 'Configured via admin/subcontractors.php. The value is written with dolibarr_set_const and rendered in a textarea on the subcontractors admin page (admin/subcontractors.php:304).', 'Changing this value updates the IT provider note displayed in the subcontractors admin interface; no functional system behaviour is affected.', 'Any free-text string.', 0, 0, 'admin/subcontractors.php|admin/subcontractors.php', 1, 'e1bb3b4cac53895238f808f5b3dbb6b0be555f7446fe2ab2cec45dd8487abb89', 'v2', '2026-04-21T13:50:40+00:00', '["admin/subcontractors.php:304|read|print ''<textarea ... name=\"itprovider_note\"", "admin/subcontractors.php:93|write|dolibarr_set_const($db, \"MAIN_INFO_ITPROVIDER_NOTE\", GETPOST(\"itprovider_note\", ''restricthtml'')"]', 'medium', NULL);
