INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_ITPROVIDER_REGION', 'string', NULL, 'admin', 'Stores the region code of the company''s IT provider, part of the IT provider contact-info block used for the ''Third parties surveillance'' (subcontractors/experts) admin setup.', 'Written from admin/subcontractors.php:119 via dolibarr_set_const() from GETPOST(''itprovider_region_code'',''alphanohtml''), alongside sibling constants MAIN_INFO_ITPROVIDER_NAME/ADDRESS/TOWN/ZIP/STATE/COUNTRY/PHONE/MAIL/WEB/IDPROF1/IDPROF2 that together define the IT provider''s identity/contact card, mirroring the MAIN_INFO_ACCOUNTANT_* block.', 'Changing it changes the region value stored for the IT provider contact block configured on the subcontractors/experts admin page; no further consuming code was inspected.', 'A region code string (from a region selector, ''itprovider_region_code'' POST field).', 0, 0, 'admin/subcontractors.php', 1, '2f42f9a9a20f4459f4083a066422f0badf7e71a0311a27368216ff9f1afa8ef9', 'v2', '2026-07-24T07:05:23+00:00', '["admin/subcontractors.php:119|write|dolibarr_set_const($db, \"MAIN_INFO_ITPROVIDER_REGION\", GETPOST(\"itprovider_region_code\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
