INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_ADDRESS', 'string', NULL, 'compta', 'Stores the company''s street address used across invoicing, SEPA XML generation, and the Dolibarr footer.', 'Configured via admin/company.php (written at line 123). Read in compta/prelevement/class/bonprelevement.class.php for SEPA XML <AdrLine> fields (lines 2721, 2745, 2787, 2811) and in societe/class/societe.class.php:4792 to populate the company address property.', 'Changing this value updates the company address displayed in the application footer and embedded in generated SEPA XML payment files.', 'Free-form multi-line string (postal address).', 0, 0, 'admin/company.php|admin/company.php', 1, '1032e096decb0c93c1cfed5f1683c5fbd9f5aaeeb6bb62b3040526f09e3e8ea1', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:123|write|dolibarr_set_const($db, \"MAIN_INFO_SOCIETE_ADDRESS\", GETPOST(\"MAIN_INFO_SOCIETE_ADDRESS\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "compta/prelevement/class/bonprelevement.class.php:2721|read|$addressline1 = strtr(getDolGlobalString(''MAIN_INFO_SOCIETE_ADDRESS''), array(chr(13) => \", \", chr(10) => \"\"));", "societe/class/societe.class.php:4792|read|$this->address = getDolGlobalString(''MAIN_INFO_SOCIETE_ADDRESS'');", "main.inc.php:3515|read|print ''<tr><td>''.dol_escape_htmltag(getDolGlobalString(''MAIN_INFO_SOCIETE_ADDRESS'')).''<br>''..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_COUNTRY', 'string', NULL, 'societe', 'Stores the country of the main company (mysoc), used to check setup completeness and drive country-dependent logic.', 'Written in blockedlog/admin/registration.php:124 and admin/company.php:112 via dolibarr_set_const, and checked in admin/index.php:86, hrm/index.php:74, societe/class/societe.class.php:4771, core/redirect_if_setup_not_complete.inc.php:41, and core/menus/standard/eldy.lib.php:1184 together with MAIN_INFO_SOCIETE_NOM.', 'If empty, Dolibarr considers company setup incomplete and shows setup warnings/redirects (core/redirect_if_setup_not_complete.inc.php:41); setting it also feeds default country logic elsewhere (ai/tools/thirdparty.class.php:420).', NULL, 0, 0, 'admin/index.php|blockedlog/admin/registration.php|admin/company.php', 1, 'e954cfb2509209dc77f82d8ba17d135f9e8881a0aff15eee710d8ac4f1260fc7', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''MAIN_INFO_SOCIETE_NOM'') || !getDolGlobalString(''MAIN_INFO_SOCIETE_COUNTRY'') || getDolGlobalString(''MAIN_INFO_SOCIETE_SETUP_TODO_WARNING'')) {", "dolibarr_set_const($db, \"MAIN_INFO_SOCIETE_COUNTRY\", $s, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_EMAIL', 'string', NULL, 'core', 'Provides a fallback display label for the company''s own email address when suggesting recipients in email address pickers, used together with MAIN_INFO_SOCIETE_MAIL.', 'Read in core/class/html.formmail.class.php:741 as the fallback value of MAIN_INFO_SOCIETE_NOM: getDolGlobalString(''MAIN_INFO_SOCIETE_NOM'', getDolGlobalString(''MAIN_INFO_SOCIETE_EMAIL'')). ''.'' &lt;''.getDolGlobalString(''MAIN_INFO_SOCIETE_MAIL'').''&gt;''; only used when MAIN_INFO_SOCIETE_MAIL is also set (line 739-740).', 'When MAIN_INFO_SOCIETE_NOM is empty and MAIN_INFO_SOCIETE_MAIL is set, this value is used as the display label preceding the company email address in the recipient suggestion list of email forms.', 'A display name/label string, typically the company name or email.', 0, 0, NULL, 1, '472f92dec474949252e2b01534792dfb12efd900401d3d5a0384b9f699e7d140', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:739-740: // Add also company main email / if (getDolGlobalString(''MAIN_INFO_SOCIETE_MAIL'')) {", "core/class/html.formmail.class.php:741: $s = getDolGlobalString(''MAIN_INFO_SOCIETE_NOM'', getDolGlobalString(''MAIN_INFO_SOCIETE_EMAIL'')).'' &lt;'' . getDolGlobalString(''MAIN_INFO_SOCIETE_MAIL'').''&gt;'';"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_FACEBOOK_URL', 'string', NULL, 'societe', 'Stores the company''s Facebook page URL, used to populate the thirdparty''s own-company social network info.', 'Read in societe/class/societe.class.php:4826 and assigned into $this->socialnetworks[''facebook''] when non-empty. No admin UI write for this constant was found in htdocs (unlike MAIN_INFO_SOCIETE_TEL/WEB which are set via admin/company.php), so it appears to require manual configuration (CONF_PHP_WIRING or direct const-table edit).', 'Setting it populates the ''facebook'' entry of the own-company (mysoc) social network array, likely used wherever company social links are displayed.', 'Free-text string: a Facebook URL.', 1, 0, NULL, 1, '0475d6a4fe41959b43441bd9380e8cc2c4f8f098f2b8b923cccdfd10b7d3a4eb', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4826|read|$facebook_url = getDolGlobalString(''MAIN_INFO_SOCIETE_FACEBOOK_URL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_FAX', 'string', NULL, 'admin', 'Stores the fax number of the company.', 'Written via admin/company.php at line 130. Read in societe/class/societe.class.php at line 4854 to populate the fax property.', 'Changing this constant updates the company fax number used in company records.', 'Fax number string', 0, 0, 'admin/company.php|admin/company.php', 1, '371015e832156db926f2e534bda2956b8a231f78e7c666c2a94abfcc915fb73d', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:130|write|dolibarr_set_const($db, \"MAIN_INFO_SOCIETE_FAX\", GETPOST(\"fax\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "societe/class/societe.class.php:4854|read|$this->fax = getDolGlobalString(''MAIN_INFO_SOCIETE_FAX'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_FORME_JURIDIQUE', 'string', NULL, 'admin', 'Stores the legal form code of the company (e.g. SA, SARL, SAS).', 'Written via admin/company.php at line 227 and read as an integer at line 619 to render the juridical status selector. Read in societe/class/societe.class.php at line 4899 to populate the forme_juridique_code property.', 'Changing this constant updates the legal form used in company records and documents.', 'Integer code corresponding to a legal form from the Dolibarr dictionary', 0, 0, 'admin/company.php|admin/company.php', 1, '0c469bf3ae53beebc6eacec72aa7dec68dfbf648bcef4d71b329714480e3ec26', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:227|write|dolibarr_set_const($db, \"MAIN_INFO_SOCIETE_FORME_JURIDIQUE\", GETPOST(\"forme_juridique_code\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/company.php:619|read|print $formcompany->select_juridicalstatus(getDolGlobalInt(''MAIN_INFO_SOCIETE_FORME_JURIDIQUE''), $mysoc->country_code, '''', ''forme_juridique_code'');", "societe/class/societe.class.php:4899|read|$this->forme_juridique_code = getDolGlobalInt(''MAIN_INFO_SOCIETE_FORME_JURIDIQUE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_GENCOD', 'string', NULL, 'admin', 'Stores the company''s barcode (GenCode) identifier used in company information.', 'Written at admin/company.php:134 from the POST ''barcode'' field. Displayed in the company admin form at line 539 as an editable input. Managed via the admin company setup UI.', 'Changing this value updates the barcode associated with the company record, affecting any barcode-based document or label generation.', 'Any alphanumeric string representing the company barcode; empty = no barcode set', 0, 0, 'admin/company.php|admin/company.php', 1, '642cceafba29ef05e92b8929a37c853d26593d8bf25ef30269e458abd0151c10', 'v2', '2026-04-21T13:29:58+00:00', '["admin/company.php:134|write|dolibarr_set_const($db, \"MAIN_INFO_SOCIETE_GENCOD\", GETPOST(\"barcode\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/company.php:539|read|print ''<input name=\"barcode\" id=\"barcode\" class=\"minwidth150 widthcentpercentminusx maxwidth300\" value=\"''.dolPrintHTMLForAttribute(GETPOSTISSET(''barcode'') ? GETPOST(''barcode'', ''alp"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_GEO_COORDINATES', 'string', NULL, 'core', 'Stores the company''s geographic coordinates as a JSON string used to initialize map widgets.', 'Read in core/class/html.form.class.php:12936, core/class/extrafields.class.php:2072, and webportal/class/html.formwebportal.class.php:1479 as the default centroid JSON for map fields. No admin UI writes this constant.', 'When not set, the default value ''{}'' is used, leaving map widgets without a preset location.', 'JSON string representing geographic coordinates (e.g. ''{"lat":48.8566,"lng":2.3522}''); defaults to ''{}''.', 1, 0, NULL, 1, 'ea2ea9e683c12790eb7fd332ab34cc7fa4f9c5ea2357fb9f2481721bd081ce97', 'v2', '2026-04-21T11:16:15+00:00', '["webportal/class/html.formwebportal.class.php:1479|read|$centroidjson = getDolGlobalString(''MAIN_INFO_SOCIETE_GEO_COORDINATES'', ''{}'');", "core/class/html.form.class.php:12936|read|$centroidjson = getDolGlobalString(''MAIN_INFO_SOCIETE_GEO_COORDINATES'', ''{}'');", "core/class/extrafields.class.php:2072|read|$centroidjson = getDolGlobalString(''MAIN_INFO_SOCIETE_GEO_COORDINATES'', ''{}'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_GITHUB_URL', 'string', NULL, 'societe', 'Stores the company''s GitHub URL, used to populate the thirdparty''s own-company social network info.', 'Read in societe/class/societe.class.php:4831 and assigned into $this->socialnetworks[''github''] when non-empty (pattern mirrors the facebook_url handling on the surrounding lines). No admin UI write for this constant was found in htdocs.', 'Setting it populates the ''github'' entry of the own-company (mysoc) social network array.', 'Free-text string: a GitHub URL.', 1, 0, NULL, 1, '1ca710f46abab7b105f324012c99de805407b1f073c09a5e509a80ef962bcc91', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4831|read|$github_url = getDolGlobalString(''MAIN_INFO_SOCIETE_GITHUB_URL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_INSTAGRAM_URL', 'string', NULL, 'societe', 'Stores the company''s Instagram URL, used to populate the thirdparty''s own-company social network info.', 'Read in societe/class/societe.class.php:4829 and assigned into $this->socialnetworks[''instagram''] when non-empty (pattern mirrors the facebook_url handling on the surrounding lines). No admin UI write for this constant was found in htdocs.', 'Setting it populates the ''instagram'' entry of the own-company (mysoc) social network array.', 'Free-text string: an Instagram URL.', 1, 0, NULL, 1, '91c0ff4e47473bf40f0b46f268a9884d12ccbdc8d2b5d709a4bc770f43a00252', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4829|read|$instagram_url = getDolGlobalString(''MAIN_INFO_SOCIETE_INSTAGRAM_URL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_LINKEDIN_URL', 'string', NULL, 'societe', 'Stores the company''s LinkedIn URL, used to populate the thirdparty''s own-company social network info.', 'Read in societe/class/societe.class.php:4828 and assigned into $this->socialnetworks[''linkedin''] when non-empty (pattern mirrors the facebook_url handling on the surrounding lines). No admin UI write for this constant was found in htdocs.', 'Setting it populates the ''linkedin'' entry of the own-company (mysoc) social network array.', 'Free-text string: a LinkedIn URL.', 1, 0, NULL, 1, '6a09cae0de697425515e48d257e2f9e8b70cbca1ac302e98c24630b7b583b80e', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4828|read|$linkedin_url = getDolGlobalString(''MAIN_INFO_SOCIETE_LINKEDIN_URL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_LOGO', 'string', NULL, 'core', 'Stores the filename of the company''s main logo image.', 'Read in main.inc.php at lines 3510-3511 to display the logo in the page header (conditional on MAIN_SHOW_LOGO). Read in societe/class/societe.class.php at line 4902. A comment in core/multicompany_page.php notes: ''Logo is inside MAIN_INFO_SOCIETE_LOGO_SQUARRED/_MINI/_SMALL else MAIN_INFO_SOCIETE_LOGO/_MINI/_SMALL''.', 'Changing this constant changes the logo file displayed in the page header when MAIN_SHOW_LOGO is set.', 'Filename string of the logo image stored in the logos/ directory', 1, 0, NULL, 1, 'e50ba8704b325d8c742509b34d077ed44114968543d60bd0d8e9e088a6dcb28f', 'v2', '2026-04-21T11:16:15+00:00', '["core/multicompany_page.php:131  // Logo is inside MAIN_INFO_SOCIETE_LOGO_SQUARRED/_MINI/_SMALL else MAIN_INFO_SOCIETE_LOGO/_MINI/_SMALL", "main.inc.php:3510|check|if (getDolGlobalString(''MAIN_SHOW_LOGO'') && !getDolGlobalString(''MAIN_OPTIMIZEFORTEXTBROWSER'') && getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO'')) {", "main.inc.php:3511|read|print ''<img id=\"mysoc-info-header-logo\" style=\"max-width:100%\" alt=\"\" src=\"''.DOL_URL_ROOT.''/viewimage.php?cache=1&modulepart=mycompany&file=''.urlencode(''logos/''.dol_escape_htmltag(", "societe/class/societe.class.php:4902|read|$this->logo = getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_LOGO_MINI', 'string', NULL, 'core', 'Stores the filename of the company''s mini logo image used in menus.', 'Deleted via admin/ihm.php at line 108. Read in societe/class/societe.class.php at line 4904. Commented-out references appear in core/menus/standard/auguria.lib.php and eldy.lib.php showing the previous access pattern.', 'Changing this constant changes the mini logo filename used in menu rendering.', 'Filename string of the mini logo image', 0, 0, 'admin/ihm.php', 1, '1ee20831db60ded1ff7e6c1476fc61bf900c088fd9f44c2d79ebaeb28f9429ad', 'v2', '2026-04-21T11:16:15+00:00', '["core/menus/standard/auguria.lib.php:163  //$mysoc->logo_mini=(empty($conf->global->MAIN_INFO_SOCIETE_LOGO_MINI)?'''':$conf->global->MAIN_INFO_SOCIETE_LOGO_MINI);", "core/menus/standard/eldy.lib.php:580  //$mysoc->logo_mini=(empty($conf->global->MAIN_INFO_SOCIETE_LOGO_MINI)?'''':$conf->global->MAIN_INFO_SOCIETE_LOGO_MINI);", "admin/ihm.php:108|write|dolibarr_del_const($db, \"MAIN_INFO_SOCIETE_LOGO_MINI\",$conf->entity);", "societe/class/societe.class.php:4904|read|$this->logo_mini = getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_MINI'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_LOGO_NO_BACKGROUND', 'string', NULL, 'core', 'Selects the company logo variant without background for use in menu banners.', 'Checked in core/menus/standard/auguria.lib.php:167 and core/menus/standard/eldy.lib.php:584. When set, the no-background logo is used in the top menu area instead of the standard logo.', 'Setting this constant switches the displayed company logo to the transparent/no-background version in the Auguria and Eldy menu themes.', 'Non-empty = no-background logo used; empty or unset = standard logo used', 1, 0, NULL, 1, '88d849be7de7fda2142dc18728604b17e9d2b910a12758956e68d0786eea10fb', 'v2', '2026-04-21T13:29:58+00:00', '["core/menus/standard/auguria.lib.php:167|check|if (getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_NO_BACKGROUND'')) {", "core/menus/standard/eldy.lib.php:584|check|if (getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_NO_BACKGROUND'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_LOGO_SMALL', 'string', NULL, 'societe', 'Stores the filename of the company''s small logo image.', 'Deleted via admin/ihm.php at line 103 (no write found for setting the value). Read in societe/class/societe.class.php at line 4903 to populate the logo_small property.', 'Changing this constant changes the small logo file used in company records.', 'Filename string of the small logo image', 0, 0, 'admin/ihm.php', 1, 'e6f4db6a5e6c357ecdd63d69e04c66ed76ecd0118eb5e3734a125a9755c49402', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:103|write|dolibarr_del_const($db, \"MAIN_INFO_SOCIETE_LOGO_SMALL\",$conf->entity);", "societe/class/societe.class.php:4903|read|$this->logo_small = getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_SMALL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_LOGO_SQUARRED', 'string', NULL, 'theme', 'Stores the filename of the company''s squared logo, used for the web manifest icon and stored on the societe object.', 'Checked in theme/manifest.json.php:139-140 to build the icon relative path, and read in societe/class/societe.class.php:4873 as $this->logo_squarred; documented at core/multicompany_page.php:131 (''Logo is inside MAIN_INFO_SOCIETE_LOGO_SQUARRED/_MINI/_SMALL else MAIN_INFO_SOCIETE_LOGO/_MINI/_SMALL'').', 'When set, this filename (under logos/) is used as the app icon in the web manifest and as the company''s squared logo.', NULL, 0, 0, NULL, 1, '020b1d6bd81c02ff3398fa42ea3eff49d95a7e3fe533215573567b3042d4b245', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_SQUARRED'')) {", "// Logo is inside MAIN_INFO_SOCIETE_LOGO_SQUARRED/_MINI/_SMALL else MAIN_INFO_SOCIETE_LOGO/_MINI/_SMALL"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_LOGO_SQUARRED_MINI', 'string', NULL, 'core', 'Stores the filename of the company''s mini squared logo, used in menu themes (auguria, eldy) and the web manifest.', 'Read in societe/class/societe.class.php:4875 as $this->logo_squarred_mini, and in core/menus/standard/auguria.lib.php:164 and core/menus/standard/eldy.lib.php:581; checked in theme/manifest.json.php:109-110 to build the thumbs icon path.', 'When set, this filename (under logos/thumbs/) is used as the mini squared logo shown in the auguria/eldy menu themes and the manifest icon.', NULL, 0, 0, NULL, 1, 'b5bf43a590ede67cfe047c01d19f65a527ac4504e469f55f2a498ffd19fd4ea7', 'v2', '2026-07-24T06:41:12+00:00', '["$mysoc->logo_squarred_mini = getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_SQUARRED_MINI'');", "if (getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_SQUARRED_MINI'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_LOGO_SQUARRED_SMALL', 'string', NULL, 'theme', 'Stores the filename of the company''s small squared logo, used in the web manifest icon.', 'Read in societe/class/societe.class.php:4874 as $this->logo_squarred_small, and checked in theme/manifest.json.php:124-125 to build the thumbs icon relative path.', 'When set, this filename (under logos/thumbs/) is used as the small squared logo icon in the web manifest.', NULL, 0, 0, NULL, 1, '70474ee180a616bb55c56f1d39b46befffcaf4027c70f6dac8d2db7280a28200', 'v2', '2026-07-24T06:41:12+00:00', '["$this->logo_squarred_small = getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_SQUARRED_SMALL'');", "if (getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO_SQUARRED_SMALL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_MAIL', 'string', NULL, 'public', 'Stores the main company''s email address, used as the default ''from'' company email in admin mail setup and member notifications.', 'Set via admin/company.php:139 and read in admin/mails.php (lines 646-647, 931, 1100-1101) to test/display the company email, and checked in public/members/new.php:530 alongside ADHERENT_AUTOREGISTER_NOTIF_MAIL_SUBJECT.', 'When set, this address is displayed as the company email in admin/mails.php and used in the mail connectivity test list.', NULL, 0, 0, 'admin/company.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/company.php', 1, 'd8dec53db856ab5c903764f66237c74e311fd0c00e39645f256da9bf1268feee', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, \"MAIN_INFO_SOCIETE_MAIL\", GETPOST(\"mail\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''MAIN_INFO_SOCIETE_MAIL'')) {"]', 'medium', NULL);
