INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_MANAGERS', 'string', NULL, 'admin', 'Stores the names of the company''s managers or directors.', 'Written via admin/company.php at line 224 and displayed in the admin form at line 594. Read in societe/class/societe.class.php at line 4897 to populate the managers property.', 'Changing this constant updates the manager/director names used in company records and documents.', 'Free-text string listing manager names', 0, 0, 'admin/company.php|admin/company.php', 1, '6b6ff4996a8abcb23ee8323a3c5a9b03d6fba320969cd8784227bf3f1441a24a', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:224|write|dolibarr_set_const($db, \"MAIN_INFO_SOCIETE_MANAGERS\", GETPOST(\"MAIN_INFO_SOCIETE_MANAGERS\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "societe/class/societe.class.php:4897|read|$this->managers = getDolGlobalString(''MAIN_INFO_SOCIETE_MANAGERS'');"]', 'medium', NULL);
