INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_SOCIETE_ZIP', 'string', NULL, 'compta', 'Stores the company''s postal/ZIP code used in SEPA XML address lines and the application footer.', 'Configured via admin/company.php (written at line 125). Read in compta/prelevement/class/bonprelevement.class.php (lines 2722, 2746, 2788, 2812) to compose address lines in SEPA XML, and in societe/class/societe.class.php:4793 to set the company zip property.', 'Changing this value updates the ZIP code shown in the application footer and included in SEPA XML payment file address lines.', 'Free-form string (postal/ZIP code).', 0, 0, 'admin/company.php|admin/company.php', 1, '03936798553671a37651fadb1bdf1195df9e546fc4362a57309a2190061b0890', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:125|write|dolibarr_set_const($db, \"MAIN_INFO_SOCIETE_ZIP\", GETPOST(\"MAIN_INFO_SOCIETE_ZIP\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "compta/prelevement/class/bonprelevement.class.php:2746|read|$XML_SEPA_INFO .= ''<AdrLine>''.dolEscapeXML(dol_trunc(dol_string_nospecial(dol_string_unaccent(getDolGlobalString(''MAIN_INFO_SOCIETE_ZIP'')...", "societe/class/societe.class.php:4793|read|$this->zip = getDolGlobalString(''MAIN_INFO_SOCIETE_ZIP'');", "main.inc.php:3515|read|print ''<tr><td>''.dol_escape_htmltag(getDolGlobalString(''MAIN_INFO_SOCIETE_ADDRESS'')).''<br>''.dol_escape_htmltag(getDolGlobalString(''MAIN_INFO_SOCIETE_ZIP''))..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_TVAINTRA', 'string', NULL, 'admin', 'Stores the company''s intra-community VAT number used across tax forms and third-party records.', 'Written via admin/taxes.php (line 137) and admin/company.php (line 239). Read in societe/class/societe.class.php:4895 (`$this->tva_intra = getDolGlobalString(''MAIN_INFO_TVAINTRA''); // VAT number, not necessarily INTRA.`), used in the Greek VAT check (checkVatGr.php:30) and displayed in the top-bar dropdown (main.inc.php:2487).', 'Changing this value updates the company VAT number shown in documents, the top-bar info panel, and used in VAT cross-checks.', 'String (VAT number, e.g. ''FR12345678901''); empty means no VAT number is configured.', 0, 0, 'admin/company.php|admin/taxes.php|admin/company.php|admin/taxes.php', 1, '5eb673134346af406906e23e4e8783c6819ec6cf1ed3993c2660921c6d235ca7', 'v2', '2026-04-21T11:16:15+00:00', '["societe/class/societe.class.php:4895|read|$this->tva_intra = getDolGlobalString(''MAIN_INFO_TVAINTRA''); // VAT number, not necessarily INTRA.", "societe/checkvat/checkVatGr.php:30|read|$myafm = preg_replace(''/\\D/'', '''', getDolGlobalString(''MAIN_INFO_TVAINTRA'')); // Get Vat from request after removing non-digit characters", "admin/taxes.php:137|write|dolibarr_set_const($db, \"MAIN_INFO_TVAINTRA\", GETPOST(\"tva\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "main.inc.php:2487|read|$dropdownBody .= ''<br><b>''.$langs->trans(\"VATIntraShort\").''</b>: <span>''.dol_print_profids(getDolGlobalString(\"MAIN_INFO_TVAINTRA\"), ''VAT'').''</span>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_TVA_DAY_DEADLINE_SUBMISSION', 'string', NULL, 'admin', 'Stores the day-of-month deadline for VAT submission as configured in the tax settings admin page.', 'Written via dolibarr_set_const in admin/taxes.php:141 from the POST field ''deadline_day_vat'', and displayed in the form at admin/taxes.php:209 with a placeholder showing '':21''. The admin UI is admin/taxes.php.', 'Changing this value updates the configured VAT submission deadline day displayed and used within tax administration workflows.', 'A day-of-month integer (e.g. 21); empty or unset means no deadline configured.', 0, 0, 'admin/taxes.php|admin/taxes.php', 1, 'f71e0b16599443f111787e1e0110c6183d2368a0e5f9017a287d312850255035', 'v2', '2026-04-21T13:50:40+00:00', '["admin/taxes.php:141|write|dolibarr_set_const($db, \"MAIN_INFO_TVA_DAY_DEADLINE_SUBMISSION\", GETPOSTINT(\"deadline_day_vat\"), ''chaine'', 0, '''', $conf->entity);", "admin/taxes.php:209|read|print ''<input placeholder=\"''.$langs->trans(\"Example\").'':21\" name=\"deadline_day_vat\" id=\"deadline_day_vat\" class=\"minwidth200\" value=\"''.getDolGlobalString(''MAIN_INFO_TVA_DAY_DEADLIN"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_VALUE_LOCALTAX1', 'string', NULL, 'admin', 'Stores the company-level local tax 1 (IRPF or equivalent) rate configured in the admin company setup.', 'Written via admin/company.php:263 (reset to 0) and 265 (set from POST ''lt1''). Read at core/lib/functions.lib.php:8144 to return the local tax 1 rate. Managed through admin/company.php UI.', 'Changing this value alters the local tax 1 rate applied in tax calculations for the entity.', 'Numeric string representing the local tax 1 rate; 0 = no local tax 1', 0, 0, 'admin/company.php|admin/company.php', 1, '8af5cda236391e416ee9d7d20a5ecf81e3156cbcfa063e4b407230d0c9b0952b', 'v2', '2026-04-21T13:29:58+00:00', '["admin/company.php:263|write|dolibarr_set_const($db, \"MAIN_INFO_VALUE_LOCALTAX1\", 0, ''chaine'', 0, '''', $conf->entity);", "admin/company.php:265|write|dolibarr_set_const($db, \"MAIN_INFO_VALUE_LOCALTAX1\", GETPOST(''lt1'', ''aZ09''), ''chaine'', 0, '''', $conf->entity);", "core/lib/functions.lib.php:8144|read|return getDolGlobalString(''MAIN_INFO_VALUE_LOCALTAX1'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_VALUE_LOCALTAX2', 'string', NULL, 'admin', 'Stores the company-level local tax 2 rate configured in the admin company setup.', 'Written via admin/company.php:271 (reset to 0) and 273 (set from POST ''lt2''). Read at core/lib/functions.lib.php:8158 to return the local tax 2 rate. Managed through admin/company.php UI.', 'Changing this value alters the local tax 2 rate applied in tax calculations for the entity.', 'Numeric string representing the local tax 2 rate; 0 = no local tax 2', 0, 0, 'admin/company.php|admin/company.php', 1, 'e8992a660918b481a1adc9c7ff366c31276c02795ad2def444773ee4fb229353', 'v2', '2026-04-21T13:29:58+00:00', '["admin/company.php:271|write|dolibarr_set_const($db, \"MAIN_INFO_VALUE_LOCALTAX2\", 0, ''chaine'', 0, '''', $conf->entity);", "admin/company.php:273|write|dolibarr_set_const($db, \"MAIN_INFO_VALUE_LOCALTAX2\", GETPOST(''lt2'', ''aZ09''), ''chaine'', 0, '''', $conf->entity);", "core/lib/functions.lib.php:8158|read|return getDolGlobalString(''MAIN_INFO_VALUE_LOCALTAX2'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INFO_VAT_RETURN', 'string', NULL, 'compta', 'Specifies the VAT return frequency, used to compute default date ranges on VAT reports.', 'Written via admin/taxes.php (line 139) and shown as a select array (line 203). Read in compta/tva/initdatesforvat.inc.php to branch date logic: line 54 checks for value 2 (quarterly), line 57 for value 3 (yearly), and line 69 for value 1 (monthly).', 'Changing this value alters the default date range pre-filled on VAT declaration forms to match the selected reporting frequency.', '1 = monthly; 2 = quarterly; 3 = yearly; empty or 2 = quarterly (default).', 0, 0, 'admin/taxes.php|admin/taxes.php', 1, '8860659afaa27bd3d7a7d49cbe4806543903037761069c45f1392110a00520dc', 'v2', '2026-04-21T11:16:15+00:00', '["admin/taxes.php:139|write|dolibarr_set_const($db, \"MAIN_INFO_VAT_RETURN\", GETPOST(\"MAIN_INFO_VAT_RETURN\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "compta/tva/initdatesforvat.inc.php:54|check|if (!getDolGlobalString(''MAIN_INFO_VAT_RETURN'') || getDolGlobalInt(''MAIN_INFO_VAT_RETURN'') == 2) { // quaterly vat, we take last past complete quarter", "compta/tva/initdatesforvat.inc.php:57|read|} elseif (getDolGlobalInt(''MAIN_INFO_VAT_RETURN'') == 3) { // yearly vat", "compta/tva/initdatesforvat.inc.php:69|read|} elseif (getDolGlobalInt(''MAIN_INFO_VAT_RETURN'') == 1) {\t// monthly vat, we take last past complete month"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INPUT_DESC_HEIGHT', 'string', NULL, 'core', 'Sets the number of rows for description textarea inputs across several modules.', 'When set, the integer value is used as the row count ($nbrows) for description textareas in projet/tasks.php, contrat/card.php, and core/tpl/objectline_create.tpl.php and objectline_edit.tpl.php. Read at projet/tasks/task.php:568 via getDolGlobalInt with a default of 0.', 'Without this constant, description textareas use their default height. Setting it overrides the row count in all affected pages.', 'Integer (number of rows); 0 or unset = default height.', 1, 0, NULL, 1, '8d30e8f1e9bcc436ded3e2743e5d734d94008dd0873c0ed3f0febeff9be16989', 'v2', '2026-04-21T11:16:15+00:00', '["projet/tasks/task.php:568|read|$nbrows = getDolGlobalInt(''MAIN_INPUT_DESC_HEIGHT'', 0);", "projet/tasks.php:882|check|if (getDolGlobalString(''MAIN_INPUT_DESC_HEIGHT'')) {", "contrat/card.php:1872|check|if (getDolGlobalString(''MAIN_INPUT_DESC_HEIGHT'')) {", "core/tpl/objectline_create.tpl.php:449|check|if (getDolGlobalString(''MAIN_INPUT_DESC_HEIGHT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_INVERT_SENDER_RECIPIENT', 'string', NULL, 'core', 'Swaps the sender and recipient address block positions in generated PDF documents.', 'Configured via admin/pdf.php:159 and read across 64 occurrences in PDF modules. Also set programmatically in memory at master.inc.php:326 and api/class/api_access.class.php:180, and auto-applied for German companies at master.inc.php:324 when not already set.', 'Enabling this moves the sender address to the left and the recipient to the right (or vice versa) in PDF document headers; the value is automatically set to 1 for German companies.', '0 = sender left, recipient right (default); 1 = sender and recipient positions inverted.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'd91cfec13e7eb0bb7264cbb4f638a5cb37d2df7fe165425085a207d0d6c1e64c', 'v2', '2026-04-21T11:16:15+00:00', '["master.inc.php:324|read|if ($mysoc->country_code == ''DE'' && !isset($conf->global->MAIN_INVERT_SENDER_RECIPIENT)) {", "master.inc.php:326|write|$conf->global->MAIN_INVERT_SENDER_RECIPIENT = 1;", "admin/pdf.php:159|write|dolibarr_set_const($db, \"MAIN_INVERT_SENDER_RECIPIENT\", GETPOST(\"MAIN_INVERT_SENDER_RECIPIENT\"), ''chaine'', 0, '''', $conf->entity);", "recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:932|check|if (getDolGlobalString(''MAIN_INVERT_SENDER_RECIPIENT'')) $posx = $this->marge_gauche;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_JQUERY_JNOTIFY_BOTTOM', 'string', NULL, 'theme', 'Repositions jNotify popup notifications to the bottom of the screen instead of the top, in both Eldy and MD themes.', 'Read in theme/eldy/global.inc.php:7455 and theme/md/style.css.php:7254, both conditionally overriding the ''.jnotify-container'' CSS with ''top: auto !important; bottom: 4px !important;''.', 'Enabling it moves the jNotify notification popups to the bottom of the viewport in either theme; unset/0 leaves them at the top (default fixed position).', 'Boolean-like: enabled = notifications anchored to bottom; unset/0 = anchored to top (default).', 0, 0, NULL, 1, 'f2386f862df014e90ca7b540d26650b51ad6a6e89ad2800c3b16cb9a922deae8', 'v2', '2026-07-24T07:05:23+00:00', '["theme/eldy/global.inc.php:7455: <?php if (getDolGlobalString(''MAIN_JQUERY_JNOTIFY_BOTTOM'')) { ?>", "theme/eldy/global.inc.php:7456-7457: top: auto !important; bottom: 4px !important;", "theme/md/style.css.php:7254: <?php if (getDolGlobalString(''MAIN_JQUERY_JNOTIFY_BOTTOM'')) { ?>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_JQUERY_JNOTIFY_UNDER_MENU', 'string', NULL, 'theme', 'Positions jNotify popup notifications just below the top menu bar instead of at the very top of the viewport, in both Eldy and MD themes.', 'Read in theme/eldy/global.inc.php:7459 and theme/md/style.css.php:7258, setting ''.jnotify-container'' ''top'' to either 32px (if images disabled) or $heightmenu + 4 px.', 'Enabling it shifts jNotify notifications down so they appear under the top menu rather than overlapping it; unset/0 leaves the default fixed top positioning (or bottom, if MAIN_JQUERY_JNOTIFY_BOTTOM is also set).', 'Boolean-like: enabled = position notifications under the menu bar; unset/0 = default top positioning.', 0, 0, NULL, 1, '099e659d5cb7d55c2836a11532285d1b55311dddfc65e1a598c465f6662eb253', 'v2', '2026-07-24T07:05:23+00:00', '["theme/eldy/global.inc.php:7459: <?php if (getDolGlobalString(''MAIN_JQUERY_JNOTIFY_UNDER_MENU'')) { ?>", "theme/eldy/global.inc.php:7460: top: <?php print $disableimages ? ''32'' : ($heightmenu + 4); ?>px;", "theme/md/style.css.php:7258: <?php if (getDolGlobalString(''MAIN_JQUERY_JNOTIFY_UNDER_MENU'')) { ?>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_JS_GRAPH', 'string', NULL, 'core', 'Specifies the JavaScript graphing library to use for charts, defaulting to ''chart''.', 'Checked in main.inc.php:2000 to decide whether to load the chart.js library, and read in core/class/dolgraph.class.php:243 to set the active library.', 'Changing this value switches the charting library used for all graphs in Dolibarr.', ''''' or unset = ''chart'' (Chart.js) is used; any other string = that library name is used', 1, 0, NULL, 1, '2bd4de029ab4d0e9c2c2f25c14f0aaba332781ef456c0ccb3dd5ddcc994c9562', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:2000|check|if (empty($disableforlogin) && (!getDolGlobalString(''MAIN_JS_GRAPH'') || getDolGlobalString(''MAIN_JS_GRAPH'') == ''chart'') && !defined(''DISABLE_JS_GRAPH'')) {", "core/class/dolgraph.class.php:243|read|$this->_library = (!getDolGlobalString(''MAIN_JS_GRAPH'') ? ''chart'' : $conf->global->MAIN_JS_GRAPH);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_JS_SWITCH_AGENDA', 'string', NULL, 'comm', 'Enables JavaScript-based show/hide switching for additional agenda events beyond the displayed limit.', 'Written at runtime to value 1 in comm/action/index.php:1951 and public/bookcal/index.php:612. Read at comm/action/index.php:2031 to decide whether to render additional items, and at :2438 to show a switch link when more items exist.', 'This constant is set programmatically at runtime rather than via configuration; it controls whether overflow agenda entries are rendered with a JS toggle.', '1 = JS switch enabled (set at runtime); empty/unset = no JS switch', 1, 0, NULL, 1, '577d2488db09ec93e9cc997b0237d918b00419dd095d9d831b375bb3c7113f38', 'v2', '2026-04-21T13:29:58+00:00', '["$conf->global->MAIN_JS_SWITCH_AGENDA = 1;", "if ($i < $maxprint || $maxprint == 0 || getDolGlobalString(''MAIN_JS_SWITCH_AGENDA'')) {", "if (getDolGlobalString(''MAIN_JS_SWITCH_AGENDA'') && $itoshow > $ireallyshown && $maxprint) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_JUMP_TAG', 'string', NULL, 'supplier_proposal', 'Enables appending an HTML anchor tag (e.g. #reopen, #close, #builddoc) to action button URLs so the page jumps to a specific section after reload.', 'Checked in supplier_proposal/card.php:2357/2381/2387, recruitment/recruitmentjobposition_card.php:434, comm/propal/card.php:3643/3760/3770, and societe/paymentmodes.php:1723, each appending a fragment like ''#reopen'' or ''#close'' only if the constant is set.', 'When enabled, action buttons (reopen, close, builddoc, etc.) include a URL fragment that jumps the browser to the relevant page section after the action.', NULL, 1, 0, NULL, 1, 'f9a2d5c555c21c418ca97a33e9d4e818488d1cc66ff482826acd1b81d16ae5ae', 'v2', '2026-07-24T06:41:12+00:00', '["(!getDolGlobalString(''MAIN_JUMP_TAG'') ? '''' : ''#reopen'')", "(!getDolGlobalString(''MAIN_JUMP_TAG'') ? '''' : ''#close'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_KEEP_REF_CUSTOMER_ON_CLONING', 'string', NULL, 'comm', 'Preserves the customer reference field when cloning a proposal or order.', 'Checked in comm/propal/class/propal.class.php:1504 and :1589, and in commande/class/commande.class.php:1338. When falsy (default), the customer reference is cleared on clone; when set, it is retained.', 'Setting this constant causes cloned proposals and orders to carry the original customer reference, which may create duplicate references in the system.', 'Truthy string (customer ref kept) or empty/unset (customer ref cleared on clone).', 1, 0, NULL, 1, '4275f2d05a44ade3c594a26ab3c14da207c25166af5947701f48729033670757', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/class/propal.class.php:1504|check|if (!getDolGlobalString(''MAIN_KEEP_REF_CUSTOMER_ON_CLONING'')) {", "comm/propal/class/propal.class.php:1589|check|if (!getDolGlobalString(''MAIN_KEEP_REF_CUSTOMER_ON_CLONING'')) {", "commande/class/commande.class.php:1338|check|if (!getDolGlobalString(''MAIN_KEEP_REF_CUSTOMER_ON_CLONING'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LANDING_PAGE', 'string', NULL, 'user', 'Defines the default landing page URL that users are redirected to after login.', 'Read in main.inc.php:1106 and core/menus/standard/eldy.lib.php:1155 as a fallback when no user-level override is set. Also displayed in user/param_ihm.php:442 and :564 as the global default.', 'Setting this redirects all users without a personal landing-page preference to the specified URL after login.', 'Any valid Dolibarr-relative URL string; empty/unset = use system default', 1, 0, NULL, 1, 'c6fe161712a005aebfb7596ddd6b6a8a37142001729310b87193c67dd2a734cf', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1106|read|$landingpage = getDolUserString(''MAIN_LANDING_PAGE'', getDolGlobalString(''MAIN_LANDING_PAGE''));", "core/menus/standard/eldy.lib.php:1155|read|$landingpage = getDolUserString(''MAIN_LANDING_PAGE'', getDolGlobalString(''MAIN_LANDING_PAGE''));", "user/param_ihm.php:564|read|print(!getDolGlobalString(''MAIN_LANDING_PAGE'') ? '''' : $conf->global->MAIN_LANDING_PAGE);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LANGUAGES_ALLOWED', 'bool', NULL, 'core', 'Restricts the list of languages available to those explicitly listed, filtering out all others.', 'Checked in core/class/translate.class.php:946. The inline comment at line 945 states: ''We must keep only languages into MAIN_LANGUAGES_ALLOWED''. When set, only language codes present in the comma-separated list are kept. No admin UI write is present.', 'When set, only the specified language codes are available in the system, preventing users from selecting unlisted languages. When unset, all languages are available.', 'Comma-separated list of language codes (e.g. ''fr_FR,en_US''); empty or unset to allow all languages.', 1, 0, NULL, 1, '5ce8659e06961eb8c6ded6a8631636da12fc78f770a39273f5e3ea3808d74a69', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/translate.class.php:945  // We must keep only languages into MAIN_LANGUAGES_ALLOWED", "core/class/translate.class.php:946|check|if (getDolGlobalString(''MAIN_LANGUAGES_ALLOWED'') && !in_array($dir, explode('','', getDolGlobalString(''MAIN_LANGUAGES_ALLOWED'')))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LANG_DEFAULT', 'string', NULL, 'webservices', 'Sets the default language/locale for the Dolibarr instance.', 'Configurable via admin/ihm.php, admin/website.php, and admin/dict.php UI. Read in master.inc.php:307 and api/class/api_access.class.php:211 as the fallback language when no user or request language is specified. The modulebuilder template comments show ''auto'' as a valid value meaning automatic detection.', 'Changing this affects the language used for all users who have not set a personal language preference, including API responses and public pages.', 'Language code string (e.g. ''fr_FR'', ''en_US'') or ''auto'' for automatic detection', 0, 0, 'admin/ihm.php|admin/website.php|admin/dict.php|admin/ihm.php', 1, '1392349ed259979505d32bc237cd21708a46479dccf562257b92f8df0ccd41d8', 'v2', '2026-04-21T11:16:15+00:00', '["modulebuilder/template/myobject_list.php:29  //if (! defined(''MAIN_LANG_DEFAULT''))        define(''MAIN_LANG_DEFAULT'', ''auto'');\t\t\t\t\t// Force LANG (language) to a particular value", "master.inc.php:307|read|$langcode = (GETPOST(''lang'', ''aZ09'') ? GETPOST(''lang'', ''aZ09'', 1) : getDolGlobalString(''MAIN_LANG_DEFAULT'', ''auto''));", "admin/ihm.php:269|write|dolibarr_set_const($db, \"MAIN_LANG_DEFAULT\", GETPOST(\"MAIN_LANG_DEFAULT\", ''aZ09''), ''chaine'', 0, '''', $conf->entity);", "api/class/api_access.class.php:211|read|$langcode = getDolGlobalString(''MAIN_LANG_DEFAULT'', ''auto'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LASTBOX_ON_OBJECT_DATE', 'string', NULL, 'core', 'Sorts dashboard ''last records'' boxes by the object''s own date instead of the modification date.', 'Checked in at least 8 box files (box_propales.php:105, box_commandes.php:120, box_factures_fourn.php:107, box_supplier_orders.php:102, box_contracts.php:94, box_factures.php:112, box_supplier_orders_awaiting_reception.php:98). The title text at box_propales.php:77 switches from ''LastModified'' to ''Last'' based on this constant.', 'Enabling this causes the last-records dashboard widgets to order by the document date rather than the last-modified timestamp, changing which records appear at the top.', 'Empty/not set = sort by modification date; any truthy string = sort by object date', 1, 0, NULL, 1, '5ed8621efd107588625b9d5f34825b7b8d18c7279f12b315884783e9c0b3f3b0', 'v2', '2026-04-21T11:16:15+00:00', '["core/boxes/box_propales.php:105|check|if (getDolGlobalString(''MAIN_LASTBOX_ON_OBJECT_DATE'')) {", "core/boxes/box_commandes.php:120|check|if (getDolGlobalString(''MAIN_LASTBOX_ON_OBJECT_DATE'')) {", "core/boxes/box_propales.php:77|read|$text = $langs->trans(\"BoxTitleLast\".(getDolGlobalString(''MAIN_LASTBOX_ON_OBJECT_DATE'') ? \"\" : \"Modified\").\"Propals\", $max);", "core/boxes/box_factures.php:112|check|if (getDolGlobalString(''MAIN_LASTBOX_ON_OBJECT_DATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LAST_PING_KO_DATE', 'string', NULL, 'core', 'Records the timestamp of the last failed (KO) anonymous telemetry ping attempt.', 'Written from core/ajax/pingresult.php:93 (''erase last value'') and referenced in main.inc.php:4035 as $constanttosavelastko, part of the same anonymous ping telemetry mechanism as MAIN_FIRST_PING_OK_DATE.', 'Used by the ping logic to track/erase the last failure timestamp; does not itself gate whether the ping code is emitted (that depends on MAIN_FIRST_PING_OK_DATE / MAIN_FIRST_PING_OK_ID).', 'A formatted date string (dol_print_date with ''dayhourlog'',''gmt'').', 1, 0, NULL, 1, '452e8f73253b833e5a06d26e40ba622cc6ba9f63c0d4799ea2aa06e121638dee', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/pingresult.php:93|write|dolibarr_set_const($db, ''MAIN_LAST_PING_KO_DATE'', dol_print_date($now, ''dayhourlog'', ''gmt''), ''chaine'', 0, '''', $conf->entity); // erase last value", "main.inc.php:4035: $constanttosavelastko = ''MAIN_LAST_PING_KO_DATE'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LAST_REGISTRATION_KO_DATE', 'string', NULL, 'core', 'Records the timestamp of the last failed BlockedLog module registration attempt.', 'Written from core/ajax/pingresult.php:105 (''erase last value'') and referenced in main.inc.php:4081 as $constanttosavelastko within the ''asynchronous registration of the use of the BlockedLog module'' block.', 'Used to track/erase the last registration failure timestamp as part of the retry logic for BlockedLog module registration telemetry.', 'A formatted date string (dol_print_date with ''dayhourlog'',''gmt'').', 1, 0, NULL, 1, '240637f386a051b8f2ff6297c1918104b4c44a225a9892a7b669e395851b3ef0', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/pingresult.php:105|write|dolibarr_set_const($db, ''MAIN_LAST_REGISTRATION_KO_DATE'', dol_print_date($now, ''dayhourlog'', ''gmt''), ''chaine'', 0, '''', $conf->entity); // erase last value", "main.inc.php:4081: $constanttosavelastko = ''MAIN_LAST_REGISTRATION_KO_DATE'';", "main.inc.php: // Add code for the asynchronous registration of the use of the BlockedLog module if not yet done but ready"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LEGALFORM_IN_ADDRESS', 'string', NULL, 'core', 'Adds the target company''s legal form label to the target address block on generated PDF documents.', 'Checked in core/lib/pdf.lib.php:674 (function pdf_build_address, target mode); when set and $targetcompany->forme_juridique_code is not empty, the label from getFormeJuridiqueLabel() is appended.', 'Enables display of the recipient company''s legal form (e.g. SARL, SAS) on PDF documents.', 'Boolean-like (set/unset); when set, target legal form label is printed', 1, 0, NULL, 1, '860a3e819391d8a9d82c4adfe55f56547ea5c67a502eca3382639a12eed6368f', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:674|check|if (getDolGlobalString(''MAIN_LEGALFORM_IN_ADDRESS'') && !empty($targetcompany->forme_juridique_code)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LIMIT_FOR_MASS_ACTIONS', 'string', NULL, 'product', 'Sets the maximum number of records allowed to be selected for a mass action, defaulting to 1000.', 'Checked in product/stock/movement_list.php:1169 (mass stock reversal), eventorganization/core/actions_massactions_mail.inc.php:72, and core/actions_massactions.inc.php:130, all using getDolGlobalInt(''MAIN_LIMIT_FOR_MASS_ACTIONS'', 1000).', 'Raising or lowering this value changes how many selected records a mass action (e.g. mass reverse of stock movements) will process before being blocked by the limit.', 'default 1000 if unset', 1, 0, NULL, 1, '73788565933ba3d9c91a1496873359a0cee61932d6b4b7e03543636b9c7632a7', 'v2', '2026-07-24T06:41:12+00:00', '["if ($massaction == ''prereverse'' && count($toselect) <= getDolGlobalInt(''MAIN_LIMIT_FOR_MASS_ACTIONS'', 1000)) {", "$maxformassaction = getDolGlobalInt(''MAIN_LIMIT_FOR_MASS_ACTIONS'', 1000);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LIST_HIDE_PRIVATE_NOTES', 'bool', NULL, 'fourn', 'Hides the private note column from list views (supplier proposals, invoices, orders, shipments, receptions, interventions, thirdparties, contracts).', 'Checked in supplier_proposal/list.php:217, fourn/facture/list.php:242, fourn/commande/list.php:225, compta/facture/list.php:320, expedition/list.php:160, reception/list.php:149, fichinter/list.php:175, and societe/list.php:338, each toggling the ''enabled''/''visible'' flag of the note_private column.', 'When enabled, the private note column is disabled/hidden in these list views.', NULL, 1, 0, NULL, 1, 'ffad09b74b1964c5a97bd6b3177b4352b4ddcb7df7a5f4c7475f221625c1f1da', 'v2', '2026-07-24T06:41:12+00:00', '["''sp.note_private'' => array(''label'' => ''NotePrivate'', ''checked'' => ''0'', ''position'' => 521, ''enabled'' => (getDolGlobalInt(''MAIN_LIST_HIDE_PRIVATE_NOTES'') ? ''0'' : ''1'')),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LIST_HIDE_PUBLIC_NOTES', 'bool', NULL, 'fourn', 'Hides the public note column from list views (invoices, receptions, supplier proposals, orders, interventions, thirdparties, contracts).', 'Checked in compta/facture/list.php:319, reception/list.php:148, supplier_proposal/list.php:216, fourn/facture/list.php:241, fourn/commande/list.php:224, fichinter/list.php:174, societe/list.php:337, and contrat/list.php:209, each toggling the ''enabled''/''checked'' flag of the note_public column.', 'When enabled, the public note column is disabled/hidden in these list views.', NULL, 1, 0, NULL, 1, '327bd44bae5aa9cee446416aca0de946ecbc4c666eb2686d4feb009274d85f09', 'v2', '2026-07-24T06:41:12+00:00', '["''f.note_public'' => array(''label'' => ''NotePublic'', ''checked'' => ''0'', ''position'' => 520, ''enabled'' => (!getDolGlobalInt(''MAIN_LIST_HIDE_PUBLIC_NOTES''))),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LIST_ORDER_LINK_DONT_USE_STATUS', 'bool', NULL, 'commande', 'Forces the order reference link in the order list to omit the status-based URL option (e.g. ignoring the current status filter) instead of using $obj->fk_statut.', 'Checked in commande/list.php:2486 with inline comment: if (getDolGlobalInt(''MAIN_LIST_ORDER_LINK_DONT_USE_STATUS'')) { // TODO: This hidden conf must be added to the user''s individual conf ... $getNomUrlOption = ''''; }.', 'When enabled, the ref link''s nomUrl option is forced empty regardless of the current status filter, making the link behavior consistent across different list filters; comment marks it a hidden/TODO configuration not yet exposed per-user.', 'Boolean: 1/true clears $getNomUrlOption (forces default link behavior instead of status-filter-based one). Comment explicitly calls it a ''hidden configuration''.', 1, 0, NULL, 1, '60faf9a8b1bb71f01eff10216b62e5a20010086ab7b67583ac09cfc2162b8eb1', 'v2', '2026-07-24T07:05:23+00:00', '["commande/list.php:2486: if (getDolGlobalInt(''MAIN_LIST_ORDER_LINK_DONT_USE_STATUS'')) {", "commande/list.php: // TODO : This hidden conf must be added to the user''s individual conf. The user must be able to manage this behavior...", "commande/list.php: // This hidden configuration ensures that users are not confused by keeping the same behavior of click, whatever the current filter."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LIST_SHOW_REF_EXT', 'bool', NULL, 'product', 'Controls visibility of the external reference (ref_ext) column/field in list views and object field definitions (products, salaries, invoices, orders, members, expense reports, contacts).', 'Checked in product/list.php:271, salaries/class/salary.class.php:218, compta/facture/class/facture.class.php:470, commande/class/commande.class.php:451, adherents/class/adherent.class.php:439, expensereport/class/expensereport.class.php:367, societe/list.php:302, and contact/class/contact.class.php:392, each setting the ref_ext field''s ''visible''/''enabled'' flag.', 'When enabled, the ref_ext column/field becomes visible in the corresponding list views and object field definitions.', NULL, 1, 0, NULL, 1, 'e2c597fdfde63acf14e7de1ff5e7536ad8ec491e49f8cc92505adfd18b36fbb2', 'v2', '2026-07-24T06:41:12+00:00', '["''p.ref_ext'' => array(''label'' => ''RefExt'', ''checked'' => ''-1'', ''position'' => 6, ''visible'' => getDolGlobalInt(''MAIN_LIST_SHOW_REF_EXT'')),", "$this->fields[''ref_ext''][''visible''] = getDolGlobalInt(''MAIN_LIST_SHOW_REF_EXT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LOGEVENTS_DISABLE_ALL', 'bool', NULL, 'core', 'Globally disables the security/audit event-logging trigger (Logevents) for all event types.', 'Checked at core/triggers/interface_20_all_Logevents.class.php:95 as the very first line of runTrigger(); the code comment marks it as a ''hidden feature''.', 'Setting it to true stops the Logevents trigger from recording any audit log entries at all, including the finer-grained MAIN_LOGEVENTS_<action> per-action switches checked afterward.', 'Boolean-like: true/1 disables all log-events recording; comment: ''// Log events is disabled (hidden features)''.', 1, 0, NULL, 1, 'bd580f4803b37dff7a1641d31b7cb3bca4053c9b4e689bb32300f98bfe0ab991', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_all_Logevents.class.php:95|check|if (getDolGlobalString(''MAIN_LOGEVENTS_DISABLE_ALL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LOGIN_BACKGROUND', 'string', NULL, 'core', 'Stores the filename of the background image displayed on the Dolibarr login page.', 'Written in admin/ihm.php:314, deleted in admin/ihm.php:98, and read in admin/ihm.php:96 and :737 to display a preview. Used in core/tpl/login.tpl.php:242 to apply the background image style. Twenty occurrences across multiple files; configurable via admin/ihm.php.', 'Setting this value applies the specified image as the login page background. Removing it reverts to the default login page appearance.', 'String filename of an image stored under the mycompany logos directory; unset = no custom login background.', 0, 0, 'admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/ihm.php', 1, 'f67e56c32622dcba439b687ed43553d01b3fd530af07ae272c800bdd3f292ede', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:314|write|dolibarr_set_const($db, \"MAIN_LOGIN_BACKGROUND\", $original_file, ''chaine'', 0, '''', $conf->entity);", "admin/ihm.php:96|read|$logofile = $conf->mycompany->dir_output.''/logos/'' . getDolGlobalString(''MAIN_LOGIN_BACKGROUND'');", "core/tpl/login.tpl.php:242|read|print !getDolGlobalString(''MAIN_LOGIN_BACKGROUND'') ? '' style=\"background-size: cover; background-position: center center; background-attachment: fixed; background-repeat: no-repeat", "admin/ihm.php:737|read|print ''<img class=\"marginleftonly boxshadow valignmiddle\" width=\"100\" src=\"'' . DOL_URL_ROOT . ''/viewimage.php?modulepart=mycompany&amp;file='' . urlencode(''logos/'' . getDolGlobalStr"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LOGIN_BACKGROUND_STYLE', 'string', NULL, 'core', 'Overrides the CSS background style string applied to the login, password-forgotten, and password-reset pages.', 'Read in core/tpl/login.tpl.php:241, core/tpl/passwordforgotten.tpl.php:147, and core/tpl/passwordreset.tpl.php:185 to override the $backstyle variable. No admin UI write was found; HIDDEN_GUESS is 1.', 'When set, the specified CSS style string replaces the computed background style on all three authentication pages.', 'Any valid CSS background style string', 1, 0, NULL, 1, '66675f8aa3277b67d7a3812cdb4c67954e6a246ed0f5e0cdb6c47bb2bf24c83e', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/login.tpl.php:241|read|$backstyle = getDolGlobalString(''MAIN_LOGIN_BACKGROUND_STYLE'', $backstyle);", "core/tpl/passwordforgotten.tpl.php:147|read|$backstyle = getDolGlobalString(''MAIN_LOGIN_BACKGROUND_STYLE'', $backstyle);", "core/tpl/passwordreset.tpl.php:185|read|$backstyle = getDolGlobalString(''MAIN_LOGIN_BACKGROUND_STYLE'', $backstyle);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LOGIN_BADCHARUNAUTHORIZED', 'string', NULL, 'core', 'Defines the set of characters forbidden in user login names.', 'Read in getDolGlobalLoginBadCharUnauthorized() in core/lib/functions.lib.php:314, but only used when the separate $dolibarr_login_badcharunauthorized conf.php variable is explicitly set to the literal string ''MAIN_LOGIN_BADCHARUNAUTHORIZED''; otherwise conf.php''s own value (or the hardcoded default) is returned instead. CONF_PHP_WIRING: the effective bad-char list is primarily controlled by conf.php''s $dolibarr_login_badcharunauthorized, not directly by this DB constant.', 'Setting this constant only has an effect if conf.php sets $dolibarr_login_badcharunauthorized = ''MAIN_LOGIN_BADCHARUNAUTHORIZED'' to opt into reading it from the DB; otherwise changing it in the DB is ignored and the comma/@/<>/quote default (or conf.php''s own value) is used.', 'String of forbidden characters; default is '',@<>"\'''' (comma, @, <, >, double-quote, single-quote).', 1, 0, NULL, 1, 'f8534bc7c54c88002da92106037fc65530c0369f4239c7c9cb8c076639c5490f', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:314|read|return getDolGlobalString(''MAIN_LOGIN_BADCHARUNAUTHORIZED'', '',@<>\"\\'''');", "if ($dolibarr_login_badcharunauthorized === ''MAIN_LOGIN_BADCHARUNAUTHORIZED'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LOGIN_ENABLE_PASSWORD_AUTOCOMPLETE', 'bool', NULL, 'core', 'Enables browser autocomplete on the password field of the login form.', 'In core/tpl/login.tpl.php:320, the password <input> element''s autocomplete attribute is set to ''on'' if this boolean is true, otherwise ''off'' (the default, disabling browser autocomplete/autofill for the login password field).', 'Enabling it lets browsers offer to save/autofill the login password; disabling (default) turns off that browser convenience for stronger security posture on the login form.', 'Boolean: true/1 sets autocomplete="on"; false/0 (default) sets autocomplete="off".', 1, 0, NULL, 1, 'c7464cd7e0679c7d69148ea0d55dd25c4cee2268bd49d0580dcadc4229debe70', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/login.tpl.php:320|read|autocomplete=\"<?php echo !getDolGlobalString(''MAIN_LOGIN_ENABLE_PASSWORD_AUTOCOMPLETE'') ? ''off'' : ''on''; ?>\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LOGOUT_GOTO_URL', 'string', NULL, 'user', 'Overrides the default post-logout redirect URL, replacing the standard index.php destination.', 'Read at user/logout.php:90-91 to set the redirect target after session destruction. Displayed (read-only) in admin/openid_connect.php:326 with a default fallback of DOL_MAIN_URL_ROOT/index.php.', 'Setting this constant redirects users to a custom URL after logout instead of the Dolibarr home page; useful for SSO portals or custom landing pages.', 'String; a valid URL. Default (when unset) is DOL_MAIN_URL_ROOT/index.php.', 0, 0, 'admin/openid_connect.php', 1, '5cd3a939b74bda6da5b4a4e0b757765273b944715e4563f3d555f3e10a736736', 'v2', '2026-04-21T13:29:58+00:00', '["user/logout.php:90|check|if (getDolGlobalString(''MAIN_LOGOUT_GOTO_URL'')) {", "user/logout.php:91|read|$url = getDolGlobalString(''MAIN_LOGOUT_GOTO_URL'');", "admin/openid_connect.php:326|read|print ''<input class=\"minwidth400 centpercent\" value=\"'' . dol_escape_htmltag(getDolGlobalString(''MAIN_LOGOUT_GOTO_URL'', DOL_MAIN_URL_ROOT . \"/index.php\")) . ''\" disabled>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LOG_ON_ONE_LINE', 'string', NULL, 'core', 'Switches the log serialization format used by formatLogObject() from a multi-line human-readable tree to a single-line JSON string.', 'Checked in formatLogObject() in core/lib/functions.lib.php:136; doc comment says ''An option allow to output log in one line instead of a structured human tree''. When set, returns json_encode($data); otherwise returns var_export($data, true).', 'Enabling it makes serialized log data (e.g. for dol_syslog of complex data) appear as compact one-line JSON instead of multi-line var_export output, which can be easier to grep/parse in log files.', 'Boolean: truthy value uses json_encode() (one line); falsy/default uses var_export() (structured multi-line tree).', 1, 0, NULL, 1, '8eade3d878447cbf2effb74230b827af379b7397219023323a6c086ea947feff', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:136|check|if (getDolGlobalInt(\"MAIN_LOG_ON_ONE_LINE\")) {", "// An option allow to output log in one line instead of a structured human tree"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_LOW_MEMORY_DUMP', 'string', NULL, 'admin', 'Enables low-memory mode for database export operations, reducing peak memory usage at the cost of speed.', 'Read in admin/tools/dolibarr_export.php:309 as the default state of a ''lowmemorydump'' checkbox, and in admin/tools/export.php:124 to set the $lowmemorydump integer flag used during the export process.', 'Enabling this flag activates a lower-memory export strategy; disabling it uses the standard export path.', '0 = standard export (default); 1 = low-memory export mode.', 0, 0, 'admin/tools/export.php|admin/tools/dolibarr_export.php', 1, '473853dbf858c002a90b49182f53e82fbb1f7927084e4564287c5d6ed67d6e9f', 'v2', '2026-04-21T13:50:40+00:00', '["admin/tools/dolibarr_export.php:309|read|getDolGlobalInt(''MAIN_LOW_MEMORY_DUMP'')", "admin/tools/export.php:124|read|$lowmemorydump = (int) (GETPOSTISSET(\"lowmemorydump\") ? GETPOSTINT(\"lowmemorydump\") : getDolGlobalInt(''MAIN_LOW_MEMORY_DUMP''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAILFORM_DISABLE_ENTERKEY', 'bool', NULL, 'core', 'Disables the Enter key submission in mail and ticket form text areas.', 'The COMMENTS state: ''Disable enter key if option MAIN_MAILFORM_DISABLE_ENTERKEY is set'' (core/class/html.formmail.class.php:1165 and core/class/html.formticket.class.php:1928). Checked at the corresponding lines 1166 and 1929.', 'Enabling this prevents accidental form submission via the Enter key in email and ticket compose forms; disabling it restores default Enter key behaviour.', 'truthy = disable Enter key in mail/ticket forms; empty/not set = Enter key works normally', 1, 0, NULL, 1, '0ae37ac864e0bfc7ddd4f46e50336ca447de4c636a4ae68649a2eae1ae206e7f', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/html.formmail.class.php:1165  // Disable enter key if option MAIN_MAILFORM_DISABLE_ENTERKEY is set", "core/class/html.formticket.class.php:1928  // Disable enter key if option MAIN_MAILFORM_DISABLE_ENTERKEY is set"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_ADD_INLINE_IMAGES_IF_DATA', 'string', NULL, 'core', 'Converts base64 data-URI images embedded in HTML email bodies into CID-linked inline attachments (on by default).', 'In core/class/conf.class.php:1363-1364 the default is set to 1 if unset; in core/class/CMailFile.class.php:345, `if (getDolGlobalString(''MAIN_MAIL_ADD_INLINE_IMAGES_IF_DATA''))` triggers findHtmlImagesIsSrcData() to replace `src="data:image..."` with a cid link plus attached file, with the comment ''On by default because Gmail does not support src="data:image..."''.', 'Disabling it (setting to 0) would leave data-URI images as-is in the HTML body, which the code comment states Gmail fails to render; keeping it enabled (the default) ensures broader email client compatibility for inline images.', 'Boolean-like, default 1 (enabled): 1/set = convert data-URI images to CID attachments; 0 = leave as data URIs.', 1, 0, NULL, 1, 'd32f28858a52e8e5bb416de1fe2c9adc58c853817e96a3c7aee59403b55734c6', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1363-1364: if (!isset($this->global->MAIN_MAIL_ADD_INLINE_IMAGES_IF_DATA)) { $this->global->MAIN_MAIL_ADD_INLINE_IMAGES_IF_DATA = 1; }", "core/class/CMailFile.class.php:345: if (getDolGlobalString(''MAIN_MAIL_ADD_INLINE_IMAGES_IF_DATA'')) { // On by default because Gmail does not support src=\"data:image...\""]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_ADD_INLINE_IMAGES_IF_IN_MEDIAS', 'string', NULL, 'core', 'Enables embedding of inline images from the medias library into outgoing emails.', 'When set, the CMailFile constructor processes images stored in the medias directory and embeds them as inline attachments. Documented in core/class/CMailFile.class.php:2065 as off by default. Checked at core/class/CMailFile.class.php:327.', 'Enabling this causes images referenced from the medias directory to be embedded inline in emails; leaving it unset keeps this behavior off by default.', 'Off by default; any non-empty string value enables inline image embedding from medias.', 1, 0, NULL, 1, '2f1f15fdde183ba4629635affcb488e54a33d7a50c2bb086b14c4931d877884b', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:2065  * This is called in the CMailFile constructor but only if MAIN_MAIL_ADD_INLINE_IMAGES_IF_IN_MEDIAS is set (Off by default)", "core/class/CMailFile.class.php:327|check|if (getDolGlobalString(''MAIN_MAIL_ADD_INLINE_IMAGES_IF_IN_MEDIAS'')) {\t// Off by default"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_ALLOW_SENDMAIL_F', 'bool', NULL, 'core', 'Allows use of the sendmail -f option to set the envelope sender address from the From header.', 'Documented at core/class/CMailFile.class.php:1015: forcing using the option -f of sendmail is possible if constant MAIN_MAIL_ALLOW_SENDMAIL_F is defined. Also referenced at line 1683 regarding the SMTP header and command-line sender.', 'Enabling this passes the -f flag to the sendmail command, setting the envelope sender; disabling it omits the flag.', 'Any non-empty string value enables the -f sendmail option.', 1, 0, NULL, 1, 'b872910b17ce2141c46f8ced3f58cd273c050c5943cde025d5667b1103b47ec6', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:1015  // So forcing using the option -f of sendmail is possible if constant MAIN_MAIL_ALLOW_SENDMAIL_F is defined.", "core/class/CMailFile.class.php:1683  // SMTP header, with a value guessed by command line tool. See option MAIN_MAIL_ALLOW_SENDMAIL_F to provide email to the command line tool."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_AUTOCOPY_HOLIDAY_TO', 'string', NULL, 'holiday', 'Specifies a BCC email address to receive copies of all holiday notification emails.', 'Read in five locations across holiday/card_group.php and holiday/card.php as the $sendtobcc variable (lines 803, 586, 717, 802, 969). Covers multiple notification events (submission, approval, refusal, etc.). No admin UI write is present.', 'Setting this constant causes all holiday-related notification emails to be blind-carbon-copied to the specified address. Leaving it unset disables the BCC.', 'An email address string; empty or unset = no BCC.', 1, 0, NULL, 1, '6c628f5414e34d8e66b8f72cf8735c369c1ee53aa5f413252c64c45e8f6caf0c', 'v2', '2026-04-21T13:50:40+00:00', '["holiday/card_group.php:803|read|$sendtobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_HOLIDAY_TO'');", "holiday/card.php:586|read|$sendtobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_HOLIDAY_TO'');", "holiday/card.php:717|read|$sendtobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_HOLIDAY_TO'');", "holiday/card.php:802|read|$sendtobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_HOLIDAY_TO'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_AUTOCOPY_INVOICE_TO', 'string', NULL, 'core', 'Specifies a BCC email address to automatically copy when sending invoice emails.', 'Checked and read in core/class/html.formmail.class.php:1372–1373 when the model is ''facture_send''. Also appended to BCC in core/actions_massactions.inc.php:533. The COMMENT states: ''$autocopy can be MAIN_MAIL_AUTOCOPY_PROPOSAL_TO, MAIN_MAIL_AUTOCOPY_ORDER_TO, MAIN_MAIL_AUTOCOPY_INVOICE_TO, MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO...''', 'Setting this to an email address causes all invoice send emails to include that address as a hidden BCC recipient; clearing it disables the autocopy.', 'string (email address); empty = no autocopy', 1, 0, NULL, 1, '27769a8ae71688fe9e9c6ec74d8a0b1a37ec232363e003155b74192bbd39c474', 'v2', '2026-04-21T13:29:58+00:00', '["core/actions_sendmails.inc.php:380  // $autocopy can be MAIN_MAIL_AUTOCOPY_PROPOSAL_TO, MAIN_MAIL_AUTOCOPY_ORDER_TO, MAIN_MAIL_AUTOCOPY_INVOICE_TO, MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO...", "core/class/html.formmail.class.php:1372|check|if (getDolGlobalString(''MAIN_MAIL_AUTOCOPY_INVOICE_TO'') && !empty($this->param[''models'']) && $this->param[''models''] == ''facture_send'') {", "core/class/html.formmail.class.php:1373|read|$showinfobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_INVOICE_TO'');", "core/actions_massactions.inc.php:533|read|$sendtobcc .= (!getDolGlobalString(''MAIN_MAIL_AUTOCOPY_INVOICE_TO'') ? '''' : (($sendtobcc ? \", \" : \"\") . getDolGlobalString(''MAIN_MAIL_AUTOCOPY_INVOICE_TO'')));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_AUTOCOPY_ORDER_TO', 'string', NULL, 'core', 'Specifies a BCC email address to automatically copy when sending order emails.', 'Checked and read in core/class/html.formmail.class.php:1369–1370 when the model is ''order_send''. Also appended to BCC in core/actions_massactions.inc.php:530. The COMMENT states: ''$autocopy can be MAIN_MAIL_AUTOCOPY_PROPOSAL_TO, MAIN_MAIL_AUTOCOPY_ORDER_TO, MAIN_MAIL_AUTOCOPY_INVOICE_TO, MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO...''', 'Setting this to an email address causes all order send emails to include that address as a hidden BCC recipient; clearing it disables the autocopy.', 'string (email address); empty = no autocopy', 1, 0, NULL, 1, 'bb8af5fc4719f0e7146739e64abd503a438efd4678ddbc0cf380649b48a61f4b', 'v2', '2026-04-21T13:29:58+00:00', '["core/actions_sendmails.inc.php:380  // $autocopy can be MAIN_MAIL_AUTOCOPY_PROPOSAL_TO, MAIN_MAIL_AUTOCOPY_ORDER_TO, MAIN_MAIL_AUTOCOPY_INVOICE_TO, MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO...", "core/class/html.formmail.class.php:1369|check|if (getDolGlobalString(''MAIN_MAIL_AUTOCOPY_ORDER_TO'') && !empty($this->param[''models'']) && $this->param[''models''] == ''order_send'') {", "core/class/html.formmail.class.php:1370|read|$showinfobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_ORDER_TO'');", "core/actions_massactions.inc.php:530|read|$sendtobcc .= (!getDolGlobalString(''MAIN_MAIL_AUTOCOPY_ORDER_TO'') ? '''' : (($sendtobcc ? \", \" : \"\") . getDolGlobalString(''MAIN_MAIL_AUTOCOPY_ORDER_TO'')));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_AUTOCOPY_PROJECT_TO', 'string', NULL, 'core', 'Specifies a BCC email address to automatically copy when sending project emails.', 'Checked and read in core/class/html.formmail.class.php:1384–1385 when the model is ''project''. The code comment notes: ''don''t know why there is not _send at end of''. Also appended to BCC in core/actions_massactions.inc.php:545.', 'Setting this to an email address causes all project emails to include that address as a hidden BCC recipient; clearing it disables the autocopy.', 'string (email address); empty = no autocopy', 1, 0, NULL, 1, 'd77359fb3cc37722619c79062253628a28b83bbb957f319901a97802b631e974', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/html.formmail.class.php:1384|check|if (getDolGlobalString(''MAIN_MAIL_AUTOCOPY_PROJECT_TO'') && !empty($this->param[''models'']) && $this->param[''models''] == ''project'') {\t// don''t know why there is not ''_send'' at end of", "core/class/html.formmail.class.php:1385|read|$showinfobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_PROJECT_TO'');", "core/actions_massactions.inc.php:545|read|$sendtobcc .= (!getDolGlobalString(''MAIN_MAIL_AUTOCOPY_PROJECT_TO'') ? '''' : (($sendtobcc ? \", \" : \"\") . getDolGlobalString(''MAIN_MAIL_AUTOCOPY_PROJECT_TO'')));"]', 'high', NULL);
