INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_AUTOCOPY_SUPPLIER_INVOICE_TO', 'string', NULL, 'core', 'Specifies a BCC email address to automatically copy when sending supplier invoice emails.', 'Checked and read in core/class/html.formmail.class.php:1381–1382 when the model is ''invoice_supplier_send''. Also appended to BCC in core/actions_massactions.inc.php:542.', 'Setting this to an email address causes all supplier invoice send emails to include that address as a hidden BCC recipient; clearing it disables the autocopy.', 'string (email address); empty = no autocopy', 1, 0, NULL, 1, 'f01d503b02559ce08e19987b93604eeebf66e9c7ab72bf6d7f3c394e760d97ca', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/html.formmail.class.php:1381|check|if (getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_INVOICE_TO'') && !empty($this->param[''models'']) && $this->param[''models''] == ''invoice_supplier_send'') {", "core/class/html.formmail.class.php:1382|read|$showinfobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_INVOICE_TO'');", "core/actions_massactions.inc.php:542|read|$sendtobcc .= (!getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_INVOICE_TO'') ? '''' : (($sendtobcc ? \", \" : \"\") . getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_INVOICE_TO'')));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_AUTOCOPY_SUPPLIER_ORDER_TO', 'string', NULL, 'core', 'Specifies a BCC email address to automatically copy when sending supplier order emails.', 'Checked and read in core/class/html.formmail.class.php:1378–1379 when the model is ''order_supplier_send''. Also appended to BCC in core/actions_massactions.inc.php:539.', 'Setting this to an email address causes all supplier order send emails to include that address as a hidden BCC recipient; clearing it disables the autocopy.', 'string (email address); empty = no autocopy', 1, 0, NULL, 1, '528be11ea7d85be07eff1180b49aa10486fdfe80b7d904fa1b2839dd20235085', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/html.formmail.class.php:1378|check|if (getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_ORDER_TO'') && !empty($this->param[''models'']) && $this->param[''models''] == ''order_supplier_send'') {", "core/class/html.formmail.class.php:1379|read|$showinfobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_ORDER_TO'');", "core/actions_massactions.inc.php:539|read|$sendtobcc .= (!getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_ORDER_TO'') ? '''' : (($sendtobcc ? \", \" : \"\") . getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_ORDER_TO'')));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO', 'string', NULL, 'core', 'Specifies a BCC email address to automatically copy when sending supplier proposal emails.', 'Checked and read in core/class/html.formmail.class.php:1375–1376 when the model is ''supplier_proposal_send''. Also appended to BCC in core/actions_massactions.inc.php:536. The COMMENT states: ''$autocopy can be MAIN_MAIL_AUTOCOPY_PROPOSAL_TO, MAIN_MAIL_AUTOCOPY_ORDER_TO, MAIN_MAIL_AUTOCOPY_INVOICE_TO, MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO...''', 'Setting this to an email address causes all supplier proposal send emails to include that address as a hidden BCC recipient; clearing it disables the autocopy.', 'string (email address); empty = no autocopy', 1, 0, NULL, 1, 'ca5eb12a6ed53f9aa0128f8178c454ecc6fd27ac71bc206301a9d941acc14348', 'v2', '2026-04-21T13:29:58+00:00', '["core/actions_sendmails.inc.php:380  // $autocopy can be MAIN_MAIL_AUTOCOPY_PROPOSAL_TO, MAIN_MAIL_AUTOCOPY_ORDER_TO, MAIN_MAIL_AUTOCOPY_INVOICE_TO, MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO...", "core/class/html.formmail.class.php:1375|check|if (getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO'') && !empty($this->param[''models'']) && $this->param[''models''] == ''supplier_proposal_send'') {", "core/class/html.formmail.class.php:1376|read|$showinfobcc = getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO'');", "core/actions_massactions.inc.php:536|read|$sendtobcc .= (!getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO'') ? '''' : (($sendtobcc ? \", \" : \"\") . getDolGlobalString(''MAIN_MAIL_AUTOCOPY_SUPPLIER_PROPOSAL_TO'')));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_AUTOCOPY_TO', 'string', NULL, 'core', 'Specifies one or more email addresses to automatically BCC on every outgoing email sent by Dolibarr.', 'Configured via the mail admin UI (admin/mails.php:130, :662). The value supports special tokens such as __USER_EMAIL__ in addition to plain addresses (core/class/CMailFile.class.php:394). When set, the value is split by comma and each address is added as BCC to all outgoing emails (core/class/CMailFile.class.php:395, :396).', 'Setting this causes every outgoing email to be BCC''d to the listed addresses. Clearing it stops the automatic BCC.', 'Comma-separated list of email addresses. Supports token __USER_EMAIL__. Example: ''email@example.com, __USER_EMAIL__''.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '5489f44b95749ad0d98368f6d008af0e3fd17b74f8085206d6630a5f3475a1ea', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/CMailFile.class.php:215  *\t@param \tstring\t\t$addr_bcc            \tEmail bcc (Note: This is autocompleted with MAIN_MAIL_AUTOCOPY_TO if defined)", "core/class/CMailFile.class.php:394  // For example MAIN_MAIL_AUTOCOPY_TO can be ''email@example.com, __USER_EMAIL__, ...''", "core/class/CMailFile.class.php:395|check|if (getDolGlobalString(''MAIN_MAIL_AUTOCOPY_TO'')) {", "core/class/CMailFile.class.php:396|read|$listofemailstoadd = explode('','', getDolGlobalString(''MAIN_MAIL_AUTOCOPY_TO''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_COPY_ON_CLICK', 'string', NULL, 'core', 'Adds a clipboard copy button next to displayed email addresses.', 'In core/lib/functions.lib.php:4528, inside the function that renders an email address as HTML (`dol_print_email`-style), if this constant is set the code appends `showValueWithClipboardCPButton($newemail, 0, ''none'')` after the rendered email link.', 'Enabling it shows a small clipboard icon/button next to every rendered email address, letting users copy the address without selecting text.', 'Boolean-like: any truthy value enables the clipboard copy button.', 1, 0, NULL, 1, '45ccf055c533866cdb2dbf1dcb01ced5bd1f208815a0951a3cff1f4ee431173d', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:4528|check|if (getDolGlobalString(''MAIN_MAIL_COPY_ON_CLICK'')) {", "core/lib/functions.lib.php|$rep .= showValueWithClipboardCPButton($newemail, 0, ''none'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_DEBUG', 'string', NULL, 'core', 'Enables verbose debug logging for the email sending subsystem.', 'When set, debug output is written at multiple points throughout core/class/CMailFile.class.php (lines 1040, 1066, 1234, 1240, 1257, 1278, 1421, 1438, and at least one more). No admin UI manages this constant.', 'Enabling this generates extensive debug output for email operations; it should be disabled in production to avoid log bloat.', 'Any non-empty string value enables debug logging.', 1, 0, NULL, 1, 'c919295b61b7225b7b8a00f81bf253f7838eba7bce48203aaad0863f6ff3ee63', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:1421|check|if (getDolGlobalString(''MAIN_MAIL_DEBUG'')) {", "core/class/CMailFile.class.php:1040|check|if (getDolGlobalString(''MAIN_MAIL_DEBUG'')) {", "core/class/CMailFile.class.php:1066|check|if (getDolGlobalString(''MAIN_MAIL_DEBUG'')) {", "core/class/CMailFile.class.php:1234|check|if (getDolGlobalString(''MAIN_MAIL_DEBUG'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_DEBUG_ERR_WITH_DATE', 'string', NULL, 'core', 'Includes a timestamp in the filename of the mail error log file moved from dolibarr_mail.log when a mail send error occurs.', 'In core/class/CMailFile.class.php:1604-1608, on mail error the log file is renamed/moved: if getDolGlobalString(''MAIN_MAIL_DEBUG_ERR_WITH_DATE'') is set, the destination is ''dolibarr_mail.<date>.err'' (dol_print_date with ''dayhourlog'' format); otherwise it is always ''dolibarr_mail.err'' (overwritten each time).', 'Enabling it preserves a distinct, timestamped error log file per failed mail send instead of overwriting a single dolibarr_mail.err file each time, useful for keeping a history of mail failures for debugging.', 'Boolean-like: set/non-empty names the error file ''dolibarr_mail.<timestamp>.err''; unset (default) always uses ''dolibarr_mail.err'' (overwritten).', 1, 0, NULL, 1, 'f262f54152f54e8710cc2ffbac486409740627c3ab5bedc6f23055640232cdbb', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/CMailFile.class.php:1604: // Move dolibarr_mail.log into a dolibarr_mail.err or dolibarr_mail.date.err", "core/class/CMailFile.class.php:1605: if (getDolGlobalString(''MAIN_MAIL_DEBUG_ERR_WITH_DATE'')) { $destfile = $dolibarr_main_data_root.\"/dolibarr_mail.\".dol_print_date(dol_now(), ''dayhourlog'', ''gmt'').\".err\"; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_DEBUG_LOG_WITH_DATE', 'string', NULL, 'core', 'Controls archiving of the email debug log file with a date suffix.', 'When set to a non-zero integer, the debug log output file is archived using archiveOrBackupFile() with this value as the rotation parameter at core/class/CMailFile.class.php:1562. Checked at line 1560.', 'Setting this to a positive integer causes the debug log to be rotated/archived with date; leaving it unset or zero skips archiving.', 'Integer; passed to archiveOrBackupFile() as the rotation parameter.', 1, 0, NULL, 1, '855f72090b01682ac32403b3f190b81b8d35887814d5612ee0739c69260d981a', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:1560|check|if (getDolGlobalInt(''MAIN_MAIL_DEBUG_LOG_WITH_DATE'')) {", "core/class/CMailFile.class.php:1562|read|archiveOrBackupFile($outputfile, getDolGlobalInt(''MAIN_MAIL_DEBUG_LOG_WITH_DATE''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_DEFAULT_FROMTYPE', 'string', NULL, 'admin', 'Sets the default sender type used for outgoing emails.', 'Written and read in admin/mails.php (e.g. lines 131, 652, 951-958). The value is compared to ''robot'', ''user'', and ''company'' string constants, and also matched against ''senderprofile_*'' patterns for stored sender profiles. Defaults to ''user'' in fallback reads at lines 1199 and core/tpl/massactions_pre.tpl.php:262.', 'Changing this value alters the pre-selected From address type in email send forms; it affects all outgoing email compositions that do not override the sender explicitly.', '''robot'' = system robot address; ''user'' = logged-in user address; ''company'' = company address; ''senderprofile_N'' = stored sender profile N', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '775bb4e8b8b85c182bb2d0bbb1e6bbb5e49431b7c6b6e7159e26a80e96a3f34c', 'v2', '2026-04-21T11:16:15+00:00', '["admin/mails.php:951|check|if (getDolGlobalString(''MAIN_MAIL_DEFAULT_FROMTYPE'') === ''robot'') {", "admin/mails.php:953|read|} elseif (getDolGlobalString(''MAIN_MAIL_DEFAULT_FROMTYPE'') === ''user'') {", "admin/mails.php:955|read|} elseif (getDolGlobalString(''MAIN_MAIL_DEFAULT_FROMTYPE'') === ''company'') {", "admin/mails.php:131|write|dolibarr_set_const($db, ''MAIN_MAIL_DEFAULT_FROMTYPE'', GETPOST(''MAIN_MAIL_DEFAULT_FROMTYPE'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_DO_NOT_USE_SIGN', 'bool', NULL, 'admin', 'Suppresses inclusion of the user''s email signature in outgoing mail templates when enabled.', 'Checked in admin/mails.php, admin/mails_emailing.php, admin/mails_passwordreset.php, and admin/mails_ticket.php. In each, the substitution variable __USER_SIGNATURE__ and __SENDEREMAIL_SIGNATURE__ are set to empty string when this constant is set.', 'Enabling this constant removes user signatures from all outgoing emails across the system. Disabling restores signature insertion when a user signature is defined.', 'Empty/unset = user signature included if present; non-empty = user signature suppressed', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, 'cb863cc829817f5ddce31b5a494d505239876b050b081dbe3fed5fb344bfd391', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:66|read|''__USER_SIGNATURE__'' => (($user->signature && !getDolGlobalString(''MAIN_MAIL_DO_NOT_USE_SIGN'')) ? $usersignature : '''')", "admin/mails.php:67|read|''__SENDEREMAIL_SIGNATURE__'' => (($user->signature && !getDolGlobalString(''MAIN_MAIL_DO_NOT_USE_SIGN'')) ? $usersignature : '''')", "admin/mails_emailing.php:57|read|''__USER_SIGNATURE__'' => (($user->signature && !getDolGlobalString(''MAIN_MAIL_DO_NOT_USE_SIGN'')) ? $usersignature : '''')", "admin/mails_ticket.php:57|read|''__USER_SIGNATURE__'' => (($user->signature && !getDolGlobalString(''MAIN_MAIL_DO_NOT_USE_SIGN'')) ? $usersignature : '''')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_DKIM_DOMAIN', 'string', NULL, 'admin', 'Stores the domain name used in the DKIM email signature.', 'Written at admin/mails.php:124. Read in core/class/CMailFile.class.php:1415 as the domain component of the DKIM signature. Displayed and edited via admin/mails.php:603 and 841.', 'Setting this to the correct domain is required for valid DKIM signatures; an incorrect or empty value will cause DKIM signing to fail or produce invalid signatures.', 'Domain name string (e.g. ''example.com''); empty = DKIM domain not configured', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php', 1, '7baaf3d3c55b6e76917f70975293277fe2cbf3bfd2e192802bae1427166269d1', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:124|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_DKIM_DOMAIN\", GETPOST(\"MAIN_MAIL_EMAIL_DKIM_DOMAIN\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "core/class/CMailFile.class.php:1415|read|$domainName = getDolGlobalString(''MAIN_MAIL_EMAIL_DKIM_DOMAIN'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_DKIM_ENABLED', 'bool', NULL, 'admin', 'Enables DKIM email signing for outgoing messages sent via the CMailFile class.', 'Written at admin/mails.php:123. Checked in core/class/CMailFile.class.php:1413 before applying DKIM signing. Also displayed and managed via admin/mails.php (lines 302, 592, 830).', 'Enabling this constant activates DKIM signing on outgoing emails using the configured domain, selector, and private key; disabling it sends emails without DKIM signatures.', '0 = DKIM signing disabled; 1 = DKIM signing enabled', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '007f1b27af89c31a324209cd3c81333b57d17c625518e9996feb22bba188d91c', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:123|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_DKIM_ENABLED\", GETPOSTINT(\"MAIN_MAIL_EMAIL_DKIM_ENABLED\"), ''chaine'', 0, '''', $conf->entity);", "core/class/CMailFile.class.php:1413|check|if (getDolGlobalString(''MAIN_MAIL_EMAIL_DKIM_ENABLED'')) {", "admin/mails.php:830|read|print yn(getDolGlobalInt(''MAIN_MAIL_EMAIL_DKIM_ENABLED''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_DKIM_PRIVATE_KEY', 'string', NULL, 'admin', 'Stores the PEM-encoded RSA private key used to sign outgoing emails with DKIM.', 'Written at admin/mails.php:126. Read in core/class/CMailFile.class.php:1414 as the private key for DKIM signing. Displayed as a textarea at admin/mails.php:613 and summarised at line 851.', 'Setting this to a valid RSA private key (matching the public key published in DNS) enables DKIM signing; an invalid or mismatched key produces invalid DKIM signatures.', 'PEM-encoded RSA private key string; empty = DKIM private key not configured', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php', 1, '23931513b1d0caac31c2493807d6b4c65376ddc0626b9b622e4d4690d704998a', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:126|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_DKIM_PRIVATE_KEY\", GETPOST(\"MAIN_MAIL_EMAIL_DKIM_PRIVATE_KEY\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "core/class/CMailFile.class.php:1414|read|$privateKey = getDolGlobalString(''MAIN_MAIL_EMAIL_DKIM_PRIVATE_KEY'');", "admin/mails.php:613|read|print ''<td><textarea id=\"MAIN_MAIL_EMAIL_DKIM_PRIVATE_KEY\" name=\"MAIN_MAIL_EMAIL_DKIM_PRIVATE_KEY\" rows=\"15\" cols=\"100\">''.getDolGlobalString(''MAIN_MAIL_EMAIL_DKIM_PRIVATE_KEY'').''</"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_DKIM_SELECTOR', 'string', NULL, 'admin', 'Stores the DNS selector used to locate the DKIM public key for signature verification.', 'Written at admin/mails.php:125. Read in core/class/CMailFile.class.php:1416 as the selector component of the DKIM signature. Displayed and edited via admin/mails.php:608 and 846.', 'Setting the correct selector is required for receiving mail servers to locate the DKIM public key in DNS; an incorrect value causes DKIM verification failure.', 'DNS selector string (e.g. ''dkim'', ''mail''); empty = DKIM selector not configured', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php', 1, '36cea2568da4274cfa4f4ee9d040cd5be7ca4a54a2c9a762fef740f76324a60b', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:125|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_DKIM_SELECTOR\", GETPOST(\"MAIN_MAIL_EMAIL_DKIM_SELECTOR\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "core/class/CMailFile.class.php:1416|read|$selector = getDolGlobalString(''MAIN_MAIL_EMAIL_DKIM_SELECTOR'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_FROM', 'string', 'robot@domain.com', 'admin', 'Stores the default ''from'' email address used when Dolibarr sends emails, defaulting to ''robot@domain.com''.', 'Set via admin/mails.php:128 and read in admin/mails.php (lines 636, 921, 1101, 1103), admin/mails_passwordreset.php:855/747, admin/mails_ticket.php:800, and admin/ticket.php:205 which copies it into TICKET_NOTIFICATION_EMAIL_FROM.', 'When unset, mail sending checks warn/fallback (e.g. admin/mails.php:921, mails_passwordreset.php:747 also checks MAIN_MAIL_EMAIL_FROM_PASSWORDRESET); when set, it is used as the default sender address across mail forms.', NULL, 0, 0, 'admin/ticket.php|admin/ticket.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails.php', 1, '607bcd914d7e50161e2c9c1f775a99e5f6252d5460b8df5f3c2e9e66b713a915', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''MAIN_MAIL_EMAIL_FROM'')) {", "dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_FROM\", GETPOST(\"MAIN_MAIL_EMAIL_FROM\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_FROM_PASSWORDRESET', 'string', NULL, 'admin', 'Overrides the default sender email address used specifically for password-reset notification emails.', 'Configured via admin/mails_passwordreset.php (UI write at line 109). When set, it is used as the From address for password-reset emails instead of MAIN_MAIL_EMAIL_FROM (user/class/user.class.php:2826). The value is validated as an email address at admin/mails_passwordreset.php:750.', 'If left empty, the system falls back to MAIN_MAIL_EMAIL_FROM. If set to an invalid email address, a warning icon is displayed and the send may fail.', 'Any valid email address string; empty string causes fallback to MAIN_MAIL_EMAIL_FROM.', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, 'a3ba991d6f242208fca2a2771486c64605b1b06f212001c2175ad01cfe6e8269', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:743|check|if (!getDolGlobalString(''MAIN_MAIL_EMAIL_FROM_PASSWORDRESET'')) {", "admin/mails_passwordreset.php:750|read|} elseif (getDolGlobalString(''MAIN_MAIL_EMAIL_FROM_PASSWORDRESET'') && !isValidEmail(getDolGlobalString(''MAIN_MAIL_EMAIL_FROM_PASSWORDRESET''))) {", "user/class/user.class.php:2826|read|getDolGlobalString(\"MAIN_MAIL_EMAIL_FROM_PASSWORDRESET\", getDolGlobalString(\"MAIN_MAIL_EMAIL_FROM\")),", "admin/mails_passwordreset.php:109|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_FROM_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_EMAIL_FROM_PASSWORDRESET\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_HOLIDAY_FROM', 'string', NULL, 'holiday', 'Overrides the sender email address used for holiday-request notification emails.', 'In holiday/card.php:509-510, a comment states ''You can specify a special address from for holiday''; the constant is read with a fallback to MAIN_MAIL_EMAIL_FROM if unset.', 'Setting it changes the From address on holiday-request validation emails sent to approvers; the user''s own email is intentionally not used per an adjacent comment because it may belong to another company.', 'string: an email address; falls back to MAIN_MAIL_EMAIL_FROM if not set.', 0, 0, NULL, 1, 'a33ceeeb27b4698858bcc3a031a0f281400f6ca2f5246bc889b2c80d6e5dd314', 'v2', '2026-07-24T07:05:23+00:00', '["holiday/card.php:509: // You can specify a special address from for holiday", "holiday/card.php:510: $emailFrom = getDolGlobalString(''MAIN_MAIL_EMAIL_HOLIDAY_FROM'', getDolGlobalString(''MAIN_MAIL_EMAIL_FROM''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED', 'bool', NULL, 'admin', 'Allows the SMTP mailer to accept self-signed TLS certificates from the mail server.', 'Written at admin/mails.php:121, read and displayed at lines 272, 300, 579, and 815. Managed via the admin mail configuration UI (admin/mails.php).', 'Enabling this constant disables certificate validation for SMTP connections, which is insecure but necessary for some private mail servers with self-signed certificates.', '0 = self-signed certificates rejected; 1 = self-signed certificates accepted for SMTP', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '83b3aa83784a8a99e514f296ce76d1cc913fb6e5c89db781582cbeb1b557a9b2', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:121|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED\", GETPOSTINT(\"MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails.php:579|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED'', (getDolGlobalString(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SE", "admin/mails.php:815|read|print yn(getDolGlobalString(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_EMAILING', 'bool', NULL, 'admin', 'Allows self-signed SSL/TLS certificates on SMTP connections used for mass emailing.', 'Configured via admin/mails_emailing.php (dolibarr_set_const at line 108). Displayed as a yes/no selector (line 553) and summary (line 695). Also sets a JS variable at lines 247 and 275.', 'Enabling this accepts self-signed certificates on the emailing SMTP server; disabling enforces certificate validation.', 'Yes/No (selectyesno); 1 = self-signed certificates allowed, 0 = not allowed.', 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, '0d6986d056bfab927b9de8656dd9b732ae3292ca2153579bf01904a07b2007e1', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_emailing.php:108|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_EMAILING\", GETPOST(\"MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_EMAILING\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_emailing.php:553|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_EMAILING'', ...", "admin/mails_emailing.php:695|read|print yn(getDolGlobalInt(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_EMAILING''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_PASSWORDRESET', 'bool', NULL, 'admin', 'Allows self-signed TLS certificates on the SMTP connection used specifically for password reset emails.', 'Written at admin/mails_passwordreset.php:106 and read/displayed at :250, :278, :552, :714. Rendered as a yes/no selector and read as integer at :714 via getDolGlobalInt.', 'Enabling disables certificate validation for password reset SMTP, which may be necessary for internal mail servers with self-signed certificates but reduces security. Disabling enforces valid certificates.', '1/truthy = allow self-signed certificate; 0/empty = require valid certificate.', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, '026e9942e69d88c923dda34c7747cda8f98940c7fa90aab5e2599ca9ecfef552', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:106|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_PASSWORDRESET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_passwordreset.php:552|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_PASSWORDRESET'', (getDolGlobalString(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_PASSWORDRESET'') ? getDolGlobalString(''M", "admin/mails_passwordreset.php:714|read|print yn(getDolGlobalInt(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_PASSWORDRESET''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_TICKET', 'bool', NULL, 'admin', 'Allows self-signed SSL/TLS certificates on the SMTP server used for ticket emails.', 'Written in admin/mails_ticket.php at line 106 and read/rendered at lines 248, 276, 547, and 689. Displayed as a yes/no select in the admin UI.', 'Enabling this constant bypasses SSL certificate validation for the ticket email SMTP connection, which allows use of self-signed certificates but reduces security.', '1 = allow self-signed certificates; 0 or empty = require valid certificates.', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, '75f5c18398541d9247e248dd98363d6199ec5400af563c785888a530c31e9836', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:106|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_TICKET\", GETPOST(\"MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_TICKET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_ticket.php:689|read|print yn(getDolGlobalInt(''MAIN_MAIL_EMAIL_SMTP_ALLOW_SELF_SIGNED_TICKET''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_STARTTLS', 'string', NULL, 'admin', 'Enables STARTTLS encryption upgrade for SMTP connections.', 'Read in admin/mails.php:566 as a yes/no select and displayed at admin/mails.php:798. Written via admin/mails.php:120. A commented-out line in core/class/CMailFile.class.php:1999 shows the original intent to set the SMTP host to ''tls://'' when this constant and openssl are available.', 'Setting this to 1 enables STARTTLS negotiation on the SMTP connection; setting it to 0 disables it.', '1 = STARTTLS enabled; 0 = STARTTLS disabled.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '8241cff1a6fc0d07cb3415b375d2bde259296f22b821bea8f03a2a8088351570', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/CMailFile.class.php:1999  //if (getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS'') && function_exists(''openssl_open'')) $host=''tls://''.$host;", "admin/mails.php:566|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_STARTTLS'', (getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS'') : 0), 1);", "admin/mails.php:120|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_STARTTLS\", GETPOSTINT(\"MAIN_MAIL_EMAIL_STARTTLS\"), ''chaine'', 0, '''', $conf->entity);", "debugbar/class/DataCollector/DolibarrCollector.php:116|read|$info .= $langs->trans(''TLS/STARTTLS'').'': <strong>''.getDolGlobalString(\"MAIN_MAIL_EMAIL_TLS\").''</strong> / <strong>''.getDolGlobalString(\"MAIN_MAIL_EMAIL_STARTTLS\").''</strong><br>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_STARTTLS_EMAILING', 'string', NULL, 'admin', 'Enables STARTTLS encryption for SMTP connections used specifically for mass emailing.', 'Configured via admin/mails_emailing.php (dolibarr_set_const at line 107). Displayed as a yes/no selector (line 540) and summary (line 678). Also sets a JS variable at lines 245 and 273.', 'Enabling STARTTLS upgrades the SMTP connection to encrypted for mass emails; disabling sends without STARTTLS.', 'Yes/No (selectyesno); 1 = STARTTLS enabled, 0 = STARTTLS disabled.', 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, '7b6891de6e10884b49be5037c26e9225012d6d021931e04f3feb6d96f23950fd', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_emailing.php:107|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_STARTTLS_EMAILING\", GETPOST(\"MAIN_MAIL_EMAIL_STARTTLS_EMAILING\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_emailing.php:540|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_STARTTLS_EMAILING'', (getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS_EMAILING'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS_EMAILING'') : 0", "admin/mails_emailing.php:678|read|print yn(getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS_EMAILING''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_STARTTLS_PASSWORDRESET', 'string', NULL, 'admin', 'Enables STARTTLS upgrade for the SMTP connection used specifically for password reset emails.', 'Written at admin/mails_passwordreset.php:105 and read/displayed at :248, :276, :539, :697. Rendered as a yes/no selector in the admin UI.', 'Enabling upgrades the password reset SMTP connection to TLS via STARTTLS. Disabling sends without STARTTLS on that specific connection.', '1/truthy = use STARTTLS; 0/empty = no STARTTLS for password reset SMTP.', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, 'bffc02445c69c5a14cf66493a38b1746329c60d4f1ba8e23beb1d59286e7e763', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:105|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_STARTTLS_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_EMAIL_STARTTLS_PASSWORDRESET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_passwordreset.php:539|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_STARTTLS_PASSWORDRESET'', (getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS_PASSWORDRESET'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS_PASS", "admin/mails_passwordreset.php:697|read|print yn(getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS_PASSWORDRESET''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_STARTTLS_TICKET', 'string', NULL, 'admin', 'Enables STARTTLS negotiation for SMTP connections used when sending ticket emails.', 'Written in admin/mails_ticket.php at line 105 and read/rendered at lines 246, 274, 534, and 672. Displayed as a yes/no select in the admin UI.', 'Enabling this constant causes the ticket email SMTP client to issue a STARTTLS command to upgrade the connection to TLS. Disabling it skips STARTTLS negotiation.', '1 = enable STARTTLS; 0 or empty = disable STARTTLS.', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, '32753620e867c26f81fd4d3189c813caa36d59a07917112e993b0cb557367494', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:105|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_STARTTLS_TICKET\", GETPOST(\"MAIN_MAIL_EMAIL_STARTTLS_TICKET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_ticket.php:534|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_STARTTLS_TICKET'', (getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS_TICKET'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_STARTTLS_TICKET'') : 0), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_TLS', 'string', NULL, 'admin', 'Enables SSL/TLS encryption for SMTP connections.', 'Read in admin/mails.php:553 as a yes/no select field and displayed at admin/mails.php:781. Written via admin/mails.php:119. Also referenced alongside MAIN_MAIL_EMAIL_STARTTLS in the debugbar at debugbar/class/DataCollector/DolibarrCollector.php:116.', 'Setting this to 1 enables TLS encryption on the SMTP connection; setting it to 0 disables it.', '1 = TLS enabled; 0 = TLS disabled.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '6ddb0bc93a5ddc051a442775018074add6f5dab19059c1dcdd750847b6c3f876', 'v2', '2026-04-21T11:16:15+00:00', '["admin/mails.php:553|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_TLS'', (getDolGlobalString(''MAIN_MAIL_EMAIL_TLS'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_TLS'') : 0), 1);", "admin/mails.php:119|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_TLS\", GETPOSTINT(\"MAIN_MAIL_EMAIL_TLS\"), ''chaine'', 0, '''', $conf->entity);", "debugbar/class/DataCollector/DolibarrCollector.php:116|read|$info .= $langs->trans(''TLS/STARTTLS'').'': <strong>''.getDolGlobalString(\"MAIN_MAIL_EMAIL_TLS\").''</strong> / <strong>''.getDolGlobalString(\"MAIN_MAIL_EMAIL_STARTTLS\").''</strong><br>'';", "admin/mails.php:781|read|print yn(getDolGlobalString(''MAIN_MAIL_EMAIL_TLS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_TLS_EMAILING', 'string', NULL, 'admin', 'Enables TLS encryption for SMTP connections used specifically for mass emailing.', 'Configured via admin/mails_emailing.php (dolibarr_set_const at line 106). Displayed as a yes/no selector (line 527) and summary (line 661). Also sets a JS variable at lines 243 and 271 for dynamic UI updates.', 'Enabling TLS encrypts the SMTP connection for mass emails; disabling sends without TLS encryption.', 'Yes/No (selectyesno); 1 = TLS enabled, 0 = TLS disabled.', 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, '161f4b977069ec5dda295009fb665bea161fb6c05b255c8f052628030680b56a', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_emailing.php:106|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_TLS_EMAILING\", GETPOST(\"MAIN_MAIL_EMAIL_TLS_EMAILING\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_emailing.php:527|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_TLS_EMAILING'', (getDolGlobalString(''MAIN_MAIL_EMAIL_TLS_EMAILING'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_TLS_EMAILING'') : 0), 1);", "admin/mails_emailing.php:661|read|print yn(getDolGlobalString(''MAIN_MAIL_EMAIL_TLS_EMAILING''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_TLS_PASSWORDRESET', 'string', NULL, 'admin', 'Enables TLS encryption for the SMTP connection used specifically for password reset emails.', 'Written at admin/mails_passwordreset.php:104 and read/displayed at :246, :274, :525, :680. Rendered as a yes/no selector in the admin UI. Enables TLS when truthy.', 'Enabling forces TLS on the password reset SMTP connection. Disabling sends without TLS on that specific connection.', '1/truthy = use TLS; 0/empty = no TLS for password reset SMTP.', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, '660424704f338e8b9adfa022a9cd933edde1532f44688bc750f019b24364089f', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:104|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_TLS_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_EMAIL_TLS_PASSWORDRESET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_passwordreset.php:525|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_TLS_PASSWORDRESET'', (getDolGlobalString(''MAIN_MAIL_EMAIL_TLS_PASSWORDRESET'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_TLS_PASSWORDRESET'') : 0", "admin/mails_passwordreset.php:680|read|print yn(getDolGlobalString(''MAIN_MAIL_EMAIL_TLS_PASSWORDRESET''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_EMAIL_TLS_TICKET', 'string', NULL, 'admin', 'Enables TLS encryption for SMTP connections used when sending ticket emails.', 'Written in admin/mails_ticket.php at line 104 and read/rendered at lines 244, 272, 521, and 655. Displayed as a yes/no select in the admin UI.', 'Enabling this constant activates TLS for ticket email SMTP connections. Disabling it sends mail without TLS encryption.', '1 = enable TLS; 0 or empty = disable TLS.', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, '9c064ec3b9fd7986c483b82bcfdd2f200f80c6368de35a22df68a8a5ddff2b5b', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:104|write|dolibarr_set_const($db, \"MAIN_MAIL_EMAIL_TLS_TICKET\", GETPOST(\"MAIN_MAIL_EMAIL_TLS_TICKET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_ticket.php:521|read|print $form->selectyesno(''MAIN_MAIL_EMAIL_TLS_TICKET'', (getDolGlobalString(''MAIN_MAIL_EMAIL_TLS_TICKET'') ? getDolGlobalString(''MAIN_MAIL_EMAIL_TLS_TICKET'') : 0), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_ENABLED_USER_DEST_SELECT', 'bool', NULL, 'core', 'Enables a user-selector UI in email composition forms, allowing users to be chosen as To/CC recipients.', 'Set via admin/mails.php:103 and displayed with a yes/no selector at line 667; checked in core/class/html.formmail.class.php:804 and 853 and in core/actions_sendmails.inc.php:266, 307, 464 to conditionally render and process user recipient selection.', 'When enabled, email forms show a user picker for To and CC fields; when disabled, the user picker is not shown and user IDs in recipient lists are not processed.', '0 or empty = user destination selector disabled; non-zero = enabled.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php', 1, 'f2d9e7c755d066f75a2240ac068ab68b76a3a2e8c1b08229a34c837d11f2a550', 'v2', '2026-04-21T11:16:15+00:00', '["admin/mails.php:103|write|dolibarr_set_const($db, \"MAIN_MAIL_ENABLED_USER_DEST_SELECT\", GETPOSTINT(\"MAIN_MAIL_ENABLED_USER_DEST_SELECT\"), ''chaine'', 0, '''', $conf->entity);", "core/class/html.formmail.class.php:804|check|if (!empty($this->withtouser) && is_array($this->withtouser) && getDolGlobalString(''MAIN_MAIL_ENABLED_USER_DEST_SELECT'')) {", "core/actions_sendmails.inc.php:266|check|if (getDolGlobalString(''MAIN_MAIL_ENABLED_USER_DEST_SELECT'')) {", "core/actions_sendmails.inc.php:464|check|if (is_array($sendtouserid) && count($sendtouserid) > 0 && getDolGlobalString(''MAIN_MAIL_ENABLED_USER_DEST_SELECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_ERRORS_TO', 'string', NULL, 'admin', 'Specifies the email address to which mail delivery errors are sent.', 'Configured via admin/mails.php:129 and read in multiple invoice and supplier invoice class files (compta/facture/class/facture-rec.class.php:1607, compta/facture/class/facture.class.php:6369, fourn/class/fournisseur.facture.class.php:3670) as ''$errors_to = getDolGlobalString(''MAIN_MAIL_ERRORS_TO'')''. Validated as a proper email at admin/mails.php:971.', 'When set to a valid email address, mail errors are forwarded to that address; when empty or invalid, error routing is not configured.', 'Empty/not set = no error email address configured; valid email string = address to receive mail delivery error notifications.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '7f41a8bf0546016a42c21a1d7658dbd2267694bbc7ff1ee30dd285db786984d4', 'v2', '2026-04-21T11:16:15+00:00', '["admin/mails.php:971|check|if (getDolGlobalString(''MAIN_MAIL_ERRORS_TO'') && !isValidEmail(getDolGlobalString(''MAIN_MAIL_ERRORS_TO''))) {", "compta/facture/class/facture-rec.class.php:1607|read|$errors_to = getDolGlobalString(''MAIN_MAIL_ERRORS_TO'');", "compta/facture/class/facture.class.php:6369|read|$errors_to = getDolGlobalString(''MAIN_MAIL_ERRORS_TO'');", "admin/mails.php:129|write|dolibarr_set_const($db, \"MAIN_MAIL_ERRORS_TO\", GETPOST(\"MAIN_MAIL_ERRORS_TO\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_FORCE_CONTENT_TYPE_TO_HTML', 'string', NULL, 'core', 'Forces all outgoing emails to be treated/sent as HTML content type, overriding auto-detection of the message body.', 'In core/class/CMailFile.class.php:318-320, after auto-detecting whether the message is HTML, `if (getDolGlobalString(''MAIN_MAIL_FORCE_CONTENT_TYPE_TO_HTML'')) { $this->msgishtml = 1; }` forces HTML mode regardless of detection, per the inline comment ''To force to send everything with content type html.''', 'Enabling it makes every email sent through CMailFile use HTML content-type, even plain-text messages, which could affect rendering in mail clients if body content isn''t actually HTML-formatted.', 'Boolean-like: set/non-empty forces msgishtml=1 (HTML) for every mail; unset (default) uses auto-detected content type.', 1, 0, NULL, 1, 'd60491abf7b3c450d527a5a83004a27f696143925340bf1231c78cb14feca5dd', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/CMailFile.class.php:318: if (getDolGlobalString(''MAIN_MAIL_FORCE_CONTENT_TYPE_TO_HTML'')) {", "core/class/CMailFile.class.php:319: $this->msgishtml = 1; // To force to send everything with content type html."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_FORCE_FROM', 'string', NULL, 'core', 'Forces the sender (From) address of all outgoing emails to a fixed value.', 'When set, the From header is overwritten with this constant''s value at core/class/CMailFile.class.php:477, overriding any dynamically computed sender address.', 'Changing this replaces the From address on all outgoing emails; removing it restores the default sender computation.', 'Any valid email address string.', 1, 0, NULL, 1, 'aa8ce390220fe1f8b28cedde00bd67e37e7deda4fa4d1c7e32756a4de78d4cb6', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:476|check|if (getDolGlobalString(''MAIN_MAIL_FORCE_FROM'')) {", "core/class/CMailFile.class.php:477|read|$from = getDolGlobalString(''MAIN_MAIL_FORCE_FROM'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_FORCE_NOT_SENDING_TO', 'string', NULL, 'core', 'Specifies a comma-separated list of email addresses that must be removed from To, CC, and BCC before sending.', 'When set, the value is parsed as a comma-separated list and used to strip matching addresses from all recipient fields. Described in core/class/CMailFile.class.php:422 as: parse To, CC and BCC to remove MAIN_MAIL_FORCE_NOT_SENDING_TO. Used at lines 421-423.', 'Setting this prevents emails from being delivered to the listed addresses; it is typically used in test environments to block accidental sends to real recipients.', 'Comma-separated list of email addresses to suppress from all outgoing mail.', 1, 0, NULL, 1, 'de8aa022442f654e2778f5f7137bd2fd53a7d015e83f5c1c90c572f9e533dc6e', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:422  // Parse to, cc and bcc to remove MAIN_MAIL_FORCE_NOT_SENDING_TO", "core/class/CMailFile.class.php:423|read|$listofemailstonotsendto = explode('','', getDolGlobalString(''MAIN_MAIL_FORCE_NOT_SENDING_TO''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_FORCE_NOT_SENDING_TO_REPLACE', 'string', NULL, 'core', 'Specifies a replacement email address that substitutes blocked recipients in To, CC, and BCC fields.', 'When a recipient is removed because it matches MAIN_MAIL_FORCE_NOT_SENDING_TO, this constant''s value is inserted in its place for To (line 436), CC (line 451), and BCC (line 466) in core/class/CMailFile.class.php. Requires the corresponding replace flag to be active.', 'Setting this redirects blocked recipients to a single address rather than simply dropping them, useful for capturing test emails.', 'A single email address string used as the replacement recipient.', 1, 0, NULL, 1, '845b2c2e3be1e69f5d2ff8632427ef054d5a156d8046527c6a787b33c1114c31', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:435|check|if ($replaceto && getDolGlobalString(''MAIN_MAIL_FORCE_NOT_SENDING_TO_REPLACE'')) {", "core/class/CMailFile.class.php:436|read|$tabto[] = getDolGlobalString(''MAIN_MAIL_FORCE_NOT_SENDING_TO_REPLACE'');", "core/class/CMailFile.class.php:451|read|$tabcc[] = getDolGlobalString(''MAIN_MAIL_FORCE_NOT_SENDING_TO_REPLACE'');", "core/class/CMailFile.class.php:466|read|$tabbcc[] = getDolGlobalString(''MAIN_MAIL_FORCE_NOT_SENDING_TO_REPLACE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_FORCE_SENDTO', 'string', NULL, 'admin', 'Forces all outgoing emails to be redirected to a specific email address, overriding the normal recipient.', 'When set to a valid email address, all outgoing emails are sent to this address instead of the intended recipient. Configured via the admin UI at admin/mails.php, which validates the value with isValidEmail(). Saved via dolibarr_set_const as type ''chaine''.', 'Changing this to a valid address redirects all system emails to that address, which is useful for testing. Clearing it restores normal email delivery.', 'Any valid email address string; empty string disables the override.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '608c614bc9efd8c6de66b45958fb2934a92e77f3477decdb60793b6d3ef5b6ad', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails.php:880|check|if (getDolGlobalString(''MAIN_MAIL_FORCE_SENDTO'')) {", "admin/mails.php:881|check|if (!isValidEmail(getDolGlobalString(''MAIN_MAIL_FORCE_SENDTO''))) {", "admin/mails.php:627|read|print ''<input class=\"flat width300\" name=\"MAIN_MAIL_FORCE_SENDTO\" value=\"''.getDolGlobalString(''MAIN_MAIL_FORCE_SENDTO'').''\" />'';", "admin/mails.php:102|write|dolibarr_set_const($db, \"MAIN_MAIL_FORCE_SENDTO\", GETPOST(\"MAIN_MAIL_FORCE_SENDTO\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_HIDE_CUSTOM_SENDING_METHOD_FOR_PASSWORD_RESET', 'bool', NULL, 'core', 'Hides the ''Outgoing email setup for password reset'' admin sub-tab that lets admins configure a distinct sending method for password-reset emails.', 'core/lib/admin.lib.php:2165: `if (!getDolGlobalString(''MAIN_MAIL_HIDE_CUSTOM_SENDING_METHOD_FOR_PASSWORD_RESET'')) { $head[$h][0] = DOL_URL_ROOT."/admin/mails_passwordreset.php"; ... }` — the tab is added unless this constant is truthy.', 'Setting it to a truthy value removes the ''OutGoingEmailSetupForEmailing/PasswordReset'' tab from the email admin section, preventing admins from configuring a separate sending profile for password-reset emails via that UI.', 'Truthy = hide the password-reset custom sending method tab; 0/unset = tab shown (default).', 0, 0, NULL, 1, 'd17374fb88cc6074ddc7aede344ee84bfe873d3bea51b592db2f7bbf0467d2a8', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/admin.lib.php:2165: if (!getDolGlobalString(''MAIN_MAIL_HIDE_CUSTOM_SENDING_METHOD_FOR_PASSWORD_RESET'')) {", "core/lib/admin.lib.php:2166: $head[$h][0] = DOL_URL_ROOT.\"/admin/mails_passwordreset.php\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_NO_FULL_EMAIL', 'string', NULL, 'core', 'Suppresses the display name portion of email addresses, keeping only the bare address.', 'When set, core/class/CMailFile.class.php:2361 returns null for the name component of an address, and line 2312 gates related formatting logic. Only the bare email address is used without an associated display name.', 'Enabling this strips display names from all email addresses in the system; disabling it preserves full name+address formatting.', 'Any non-empty string value suppresses display names; empty or unset preserves them.', 1, 0, NULL, 1, '01138cc3694d1c539c524755d2b227b7c8da49b97dfbcd91adb81bf79cf1cc39', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:2312|check|if (getDolGlobalString(''MAIN_MAIL_NO_FULL_EMAIL'')) {", "core/class/CMailFile.class.php:2361|read|$ret[$email] = getDolGlobalString(''MAIN_MAIL_NO_FULL_EMAIL'') ? null : $name;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_NO_RETURN_PATH_FOR_MODE_MAIL', 'string', NULL, 'core', 'Suppresses the ''Return-Path'' header when building raw mail headers for the PHP mail() sending mode.', 'In core/class/CMailFile.class.php:1685-1690 (write_smtpheaders-like header builder used for ''mail'' mode), the Return-Path header is only added if `!getDolGlobalString(''MAIN_MAIL_NO_RETURN_PATH_FOR_MODE_MAIL'')`; the comment explains Return-Path is important for SPF and bounce handling, and that some command-line MTAs overwrite it using their own guessed value (see MAIN_MAIL_ALLOW_SENDMAIL_F).', 'Setting it removes the Return-Path header from outgoing mail-mode emails; since the code comments state Return-Path affects SPF checks and bounce routing, omitting it can change bounce-handling/SPF behavior for messages sent via PHP mail().', 'Boolean-like: set/non-empty omits the Return-Path header; unset (default) adds Return-Path using the from address.', 1, 0, NULL, 1, '615f7b270d728ec677d12b65291ffdfca7d6fa3570cf9363c807bfdf04c57cc3', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/CMailFile.class.php:1685: if (!getDolGlobalString(''MAIN_MAIL_NO_RETURN_PATH_FOR_MODE_MAIL'')) {", "core/class/CMailFile.class.php:1686-1688: // Return-Path is important because it is used by SPF. Some command line MTA overwrites the Return-Path ... Return-Path is used for bounced emails. If not set (most cases), the From is used."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_NO_WITH_TO_SELECTED', 'string', NULL, 'admin', 'Prevents sending an email when no ''To'' recipient has been selected in the mail form.', 'Configurable via the admin UI at admin/mails.php (written at line 104, displayed at lines 671 and 1001). Checked in core/class/html.formmail.class.php:1258.', 'Enabling this blocks email sends when no recipient is selected; disabling it allows sending without a mandatory To address.', 'truthy (yes) = block send when no To selected; empty/no = allow send without To', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php', 1, 'ce93eb6c90ab4e59946765e78069ae7216232146c60e551f736ae19764c09851', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:104|write|dolibarr_set_const($db, ''MAIN_MAIL_NO_WITH_TO_SELECTED'', GETPOSTINT(''MAIN_MAIL_NO_WITH_TO_SELECTED''), ''chaine'', 0, '''', $conf->entity);", "admin/mails.php:671|read|print $form->selectyesno(''MAIN_MAIL_NO_WITH_TO_SELECTED'', getDolGlobalString(''MAIN_MAIL_NO_WITH_TO_SELECTED''), 1);", "core/class/html.formmail.class.php:1258|check|if (!getDolGlobalInt(''MAIN_MAIL_NO_WITH_TO_SELECTED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_OVERRIDE_AUTHORITATIVE_DNS', 'string', NULL, 'admin', 'Overrides which DNS server(s) are queried when the mail setup test page looks up SPF/DMARC TXT records.', 'Used at admin/mails.php:1130: `$authns = (getDolGlobalString(''MAIN_MAIL_OVERRIDE_AUTHORITATIVE_DNS'') ? explode('','', ...) : null);` then passed as the $authns argument to dns_get_record(), with inline comment ''eg 8.8.8.8, x.x.x.x''.', 'When set, the dns_get_record() SPF/DMARC lookup queries the specified DNS server(s) instead of the system default resolver, which can change or fix results in environments with unreliable local DNS.', 'String: comma-separated list of DNS server IPs, e.g. ''8.8.8.8, x.x.x.x''.', 1, 0, 'admin/mails.php', 1, '30352825974d8fd635238a0389481aeaca9b503e2d91a649e49cca93d33f0078', 'v2', '2026-07-24T07:05:23+00:00', '["admin/mails.php:1130|read|$authns = (getDolGlobalString(''MAIN_MAIL_OVERRIDE_AUTHORITATIVE_DNS'') ? explode('','', ...) : null); // eg 8.8.8.8, x.x.x.x"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_REPLACE_EVENT_TITLE_BY_EMAIL_SUBJECT', 'string', NULL, 'core', 'Replaces the agenda event title with the email subject when logging a sent email as an agenda event.', 'Checked in partnership/class/partnershiputils.class.php:229/453, core/actions_massactions.inc.php:712, and core/actions_sendmails.inc.php:459.', 'When enabled, the agenda event created for a sent email uses the email''s subject as its title instead of the default event title.', NULL, 1, 0, NULL, 1, '9d066e62d7789f73c817f951b4840476219f2d72e5e7edbbe98ff5121222d6de', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_MAIL_REPLACE_EVENT_TITLE_BY_EMAIL_SUBJECT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_REPLY_TO', 'string', NULL, 'comm', 'Global fallback ''Reply-To'' email address used when MAILING_EMAIL_REPLYTO is not set, pre-filled on the mass emailing card.', 'Read in comm/mailing/card.php:904 as the second-priority default for the ''replyto'' input field: getDolGlobalString(''MAILING_EMAIL_REPLYTO'', getDolGlobalString(''MAIN_MAIL_REPLY_TO'')).', 'Acts as a site-wide default Reply-To address for mailings when no mailing-specific MAILING_EMAIL_REPLYTO is configured.', 'An email address string.', 0, 0, NULL, 1, '79071ba5a73c24d483e175b7eca0370c44dfb417f82dcff06b497e270f31c5ee', 'v2', '2026-07-24T07:05:23+00:00', '["comm/mailing/card.php:904: getDolGlobalString(''MAILING_EMAIL_REPLYTO'', getDolGlobalStri..."]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SENDMAIL_FORCE_ADDPARAM', 'string', NULL, 'core', 'Adds a ''-U'' additional-parameters flag to the sendmail command line when sending mail via PHP mail()/sendmail mode.', 'In core/class/CMailFile.class.php:1025-1027, if getDolGlobalString(''MAIN_MAIL_SENDMAIL_FORCE_ADDPARAM'') is set, `$additionnalparam .= ''-U ''.$additionnalparam;` appends a -U flag (with the existing additional params) to the sendmail invocation, alongside sibling constants MAIN_MAIL_ALLOW_SENDMAIL_F and MAIN_MAIL_SENDMAIL_FORCE_BA that also modify this additionnalparam string.', 'Enabling it changes the command-line parameters passed to the system sendmail binary (adds -U), which can be required or cause errors depending on the specific sendmail/MTA implementation in use.', 'Boolean-like: set/non-empty appends ''-U <existing params>'' to the sendmail command-line params; unset (default) does not add this flag.', 1, 0, NULL, 1, '6a602204d2f5ac9e5b7b055a777a2b9e0a226b089e1524a7a4facb69593a28c0', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/CMailFile.class.php:1025: if (getDolGlobalString(''MAIN_MAIL_SENDMAIL_FORCE_ADDPARAM'')) {", "core/class/CMailFile.class.php:1026: $additionnalparam .= ($additionnalparam ? '' '' : '''').''-U ''.$additionnalparam; // Use -U to add additional params"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SENDMAIL_FORCE_BA', 'string', NULL, 'core', 'Forces sendmail to use the -ba option, which reads the From or Sender header to set the envelope sender.', 'Documented at core/class/CMailFile.class.php:1020: To force usage of -ba option. This option tells sendmail to read From: or Sender: to setup sender. Also mentioned at line 1014 as an alternative to MAIN_MAIL_ALLOW_SENDMAIL_F.', 'Enabling this instructs sendmail to derive the sender from the mail headers; disabling it leaves sendmail''s default sender determination in place.', 'Any non-empty string value forces the -ba sendmail option.', 1, 0, NULL, 1, 'da867d4f53853b535f1eb64b095b1218645d0b8e41f323881d723938d6fcf507', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CMailFile.class.php:1020|check|if (getDolGlobalString(''MAIN_MAIL_SENDMAIL_FORCE_BA'')) {    // To force usage of -ba option. This option tells sendmail to read From: or Sender: to setup sender", "core/class/CMailFile.class.php:1014  // You can try to set this option to have the command use the From. if it does not work, you can also try the MAIN_MAIL_SENDMAIL_FORCE_BA."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SENDMODE', 'string', NULL, 'admin', 'Selects the transport method used to send outgoing emails.', 'Read extensively throughout admin/mails.php (64 total occurrences) to determine which sending backend is active. The default fallback value used throughout the code is ''mail''. Accepted values include ''mail'', ''smtps'', and ''swiftmailer'', which govern which SMTP configuration sections are displayed and used.', 'Changing this value switches the email transport; setting it to ''smtps'' or ''swiftmailer'' requires valid SMTP server settings, while ''mail'' uses the PHP mail() function.', 'Values observed in code: ''mail'' (PHP mail function, default), ''smtps'', ''swiftmailer''.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_ingoing.php|admin/mails.php|admin/mails.php', 1, '2de779352d2a305250a2570a48ddeb45d05cd4bf36f396e7fbd5b0128be5b291', 'v2', '2026-04-21T11:16:15+00:00', '["admin/mails.php:405|check|if (!$conf->use_javascript_ajax && $linuxlike && getDolGlobalString(''MAIN_MAIL_SENDMODE'', ''mail'') == ''mail'') {", "admin/mails.php:467|check|if (!empty($conf->use_javascript_ajax) || (in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE'', ''mail''), array(''smtps'', ''swiftmailer'')))) {", "core/menus/standard/eldy.lib.php:1209|check|if (getDolGlobalString(''MAIN_MAIL_SENDMODE'') && in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE''), array(''smtps'', ''swiftmail'')) && !getDolGlobalString(''MAIN_MAIL_SMTP_SERVER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SENDMODE_', 'string', NULL, 'core', 'Sets the mail sending mode for a specific mail context, overriding the global send mode for that context.', 'This is a dynamic constant: the actual key is ''MAIN_MAIL_SENDMODE_'' + smtpContextKey. Read in core/class/CMailFile.class.php at lines 250, 507, 958, and 1980 to determine the sending mode for the current mail context. No admin UI write is present for the dynamic variant.', 'Setting a context-specific send mode overrides the global MAIN_MAIL_SENDMODE for that mail context (e.g. emailing, password reset).', 'String send mode identifier (e.g. ''mail'', ''smtps'', ''swiftmailer''); empty/unset = falls back to global MAIN_MAIL_SENDMODE.', 1, 0, NULL, 1, '91b81b75634f646b0e6cdf87ce70b63385a65132b0c5591423e74d21741fb73d', 'v2', '2026-04-21T13:50:40+00:00', '["CMailFile.class.php:250|read|$smtpContextSendMode = getDolGlobalString(''MAIN_MAIL_SENDMODE_''.$smtpContextKey);", "CMailFile.class.php:507|read|$smtpContextSendMode = getDolGlobalString(''MAIN_MAIL_SENDMODE_''.$smtpContextKey);", "CMailFile.class.php:958|read|$smtpContextSendMode = getDolGlobalString(''MAIN_MAIL_SENDMODE_''.$smtpContextKey);", "CMailFile.class.php:1980|read|$smtpContextSendMode = getDolGlobalString(''MAIN_MAIL_SENDMODE_''.$smtpContextKey);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SENDMODE_EMAILING', 'string', NULL, 'admin', 'Selects the mail transport backend used specifically for mass emailing campaigns, overriding the global send mode.', 'Written via admin/mails_emailing.php:95 and checked extensively (lines 445, 473, 488, 503, 525, 538, 551, 606) against values ''smtps'' and ''swiftmailer'' to show SMTP configuration fields. Line 606: if getDolGlobalString(''MAIN_MAIL_SENDMODE_EMAILING'') && != ''default''.', 'Changing this constant switches the mail transport for emailing campaigns independently of the global MAIN_MAIL_SENDMODE setting. Setting it to ''default'' or clearing it falls back to the global transport.', '''smtps'' = use SMTPS library; ''swiftmailer'' = use SwiftMailer; ''default'' or empty = use global MAIN_MAIL_SENDMODE.', 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, 'c19cdbdc722c20808a4b9e081dd9ae0424e081774521e298e75a7eaf7baa497c', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails_emailing.php:445|check|if (!empty($conf->use_javascript_ajax) || in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE_EMAILING''), array(''smtps'', ''swiftmailer''))) {", "admin/mails_emailing.php:606|check|if (getDolGlobalString(''MAIN_MAIL_SENDMODE_EMAILING'') && getDolGlobalString(''MAIN_MAIL_SENDMODE_EMAILING'') != ''default'') {", "admin/mails_emailing.php:95|write|dolibarr_set_const($db, \"MAIN_MAIL_SENDMODE_EMAILING\", GETPOST(\"MAIN_MAIL_SENDMODE_EMAILING\"), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SENDMODE_PASSWORDRESET', 'string', NULL, 'admin', 'Selects the mail sending method used specifically for password reset emails, overriding the default mail send mode.', 'Written and read extensively in admin/mails_passwordreset.php (31 occurrences). When set and not ''default'', a dedicated send mode is used for password reset emails. Supported values include ''mail'', ''smtps'', ''swiftmailer''.', 'Changing this value switches the transport used for password reset emails independently of the global mail mode. Setting to ''default'' or leaving unset falls back to the system default mail mode.', 'String: ''mail'' = PHP mail(); ''smtps'' = SMTP/S; ''swiftmailer'' = SwiftMailer; ''default'' or unset = use global MAIN_MAIL_SENDMODE.', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, '1fdc91f7c8137545dd4b9aa4af02e2471fd76a75634b6f093756648c8a13f7ac', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:625|check|if (getDolGlobalString(''MAIN_MAIL_SENDMODE_PASSWORDRESET'') && getDolGlobalString(''MAIN_MAIL_SENDMODE_PASSWORDRESET'') != ''default'') {", "admin/mails_passwordreset.php:627|check|if ($linuxlike && (getDolGlobalString(''MAIN_MAIL_SENDMODE_PASSWORDRESET'') == ''mail'')) {", "admin/mails_passwordreset.php:445|check|if (!empty($conf->use_javascript_ajax) || in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE_PASSWORDRESET''), array(''smtps'', ''swiftmailer''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SENDMODE_TICKET', 'string', NULL, 'admin', 'Specifies the mail sending method used for ticket-related emails, overriding the default global mail send mode.', 'Configured in admin/mails_ticket.php (31 occurrences including reads and checks); when set to a non-''default'' value, ticket emails use the specified transport. Values ''smtps'' and ''swiftmailer'' trigger additional SMTP configuration fields in the admin UI.', 'Changing this value switches the mail transport for ticket emails. Setting it to ''smtps'' or ''swiftmailer'' exposes SMTP host/port/credential fields; leaving it as ''default'' inherits the global mail send mode.', '''default'' = use global send mode; ''smtps'' = use SMTPS/PHPMailer; ''swiftmailer'' = use SwiftMailer.', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, 'b305a980ef58b0ea905ea7a7beed3ca9387821ffc3bc321d3477f663388c6cf0', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:600|check|if (getDolGlobalString(''MAIN_MAIL_SENDMODE_TICKET'') && getDolGlobalString(''MAIN_MAIL_SENDMODE_TICKET'') != ''default'') {", "admin/mails_ticket.php:442|check|if (!empty($conf->use_javascript_ajax) || in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE_TICKET''), array(''smtps'', ''swiftmailer''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_AUTH_TYPE', 'string', NULL, 'admin', 'Specifies the SMTP authentication method used when sending emails via SMTPS or Swiftmailer.', 'Controls which authentication protocol is used for outgoing SMTP connections. Default value if not defined is ''LOGIN'' (but login/pass may be empty and they won''t be provided in such a case). The value ''XOAUTH2'' triggers OAuth2-based authentication paths in both admin/mails.php and admin/mails_ingoing.php. Configurable via the admin UI at admin/mails.php.', 'Switching from ''LOGIN'' to ''XOAUTH2'' requires OAuth2 credentials to be configured; reverting disables OAuth2 and falls back to username/password authentication.', '''LOGIN'' (default), ''XOAUTH2''', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails_ingoing.php|admin/mails.php', 1, '8accbc1a3239b7386c4d4ae5866589402efd66d846c3c4754a5d4fa1b2019c1d', 'v2', '2026-04-21T13:50:40+00:00', '["// Note: Default value for MAIN_MAIL_SMTPS_AUTH_TYPE if not defined is ''LOGIN'' (but login/pass may be empty and they won''t be provided in such a case)", "admin/mails.php:761|check|if (in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE'', ''mail''), array(''smtps'', ''swiftmailer'')) && getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE'') != \"XOAUTH2\") {", "admin/mails.php:766|check|if (in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE'', ''mail''), array(''smtps'', ''swiftmailer'')) && getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE'') === \"XOAUTH2\") {", "core/class/smtps.class.php:671|check|if (!getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_AUTH_TYPE_EMAILING', 'string', NULL, 'admin', 'Sets the SMTP authentication type (e.g. LOGIN or XOAUTH2) used for mass emailing.', 'Configured via admin/mails_emailing.php (dolibarr_set_const at line 101). Read at line 623 with default ''LOGIN''. Checked at lines 641 and 646 to branch between credential-based and OAuth2 display in the admin summary.', 'Changing this to ''XOAUTH2'' switches mass emailing to OAuth2 authentication; ''LOGIN'' uses standard username/password credentials.', '''LOGIN'' = standard credential authentication; ''XOAUTH2'' = OAuth2 token authentication.', 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, '2ad49706fc8c609de5d3c266ec32c84fd025170a9052ffaf76c3c0d1e766d224', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_emailing.php:101|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_AUTH_TYPE_EMAILING\", GETPOST(\"MAIN_MAIL_SMTPS_AUTH_TYPE_EMAILING\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/mails_emailing.php:623|read|$authtype = getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_EMAILING'', ''LOGIN'');", "admin/mails_emailing.php:641|check|if (in_array(...) && getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_EMAILING'') != \"XOAUTH2\") {", "admin/mails_emailing.php:646|check|if (in_array(...) && getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_EMAILING'') === \"XOAUTH2\") {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_AUTH_TYPE_PASSWORDRESET', 'string', NULL, 'admin', 'Specifies the SMTP authentication method for the dedicated password-reset mail channel.', 'Configured via admin/mails_passwordreset.php (UI write at line 99). When the send mode is ''smtps'' or ''swiftmailer'', the value selects the authentication type; it defaults to ''LOGIN'' when not set (line 642). The value ''XOAUTH2'' triggers an alternative OAuth2 authentication path (line 665).', 'Setting this to ''XOAUTH2'' enables OAuth2-based SMTP auth for password-reset emails; any other value (or the default ''LOGIN'') uses standard login authentication. Mismatch with the SMTP server configuration will cause delivery failure.', '''LOGIN'' (default when unset), ''XOAUTH2''.', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, '564f28ec227827c8a526f19e5b550d5226aed13f71561030a05389b6e0a79c62', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:642|read|$authtype = getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_PASSWORDRESET'', ''LOGIN'');", "admin/mails_passwordreset.php:660|check|if (in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE_PASSWORDRESET''), array(''smtps'', ''swiftmailer'')) && getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_PASSWORDRESET'') != \"XOAUTH2\") {", "admin/mails_passwordreset.php:665|check|if (in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE_PASSWORDRESET''), array(''smtps'', ''swiftmailer'')) && getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_PASSWORDRESET'') === \"XOAUTH2\")", "admin/mails_passwordreset.php:99|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_AUTH_TYPE_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_SMTPS_AUTH_TYPE_PASSWORDRESET\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_AUTH_TYPE_TICKET', 'string', NULL, 'admin', 'Specifies the SMTP authentication type used for ticket emails (LOGIN or XOAUTH2).', 'Written in admin/mails_ticket.php at line 99 and read at lines 617, 635, and 640; defaults to ''LOGIN'' when unset. Checked to determine whether to display credential fields or OAuth service selector.', 'Setting this to ''XOAUTH2'' switches ticket email SMTP authentication to OAuth2, replacing the ID/password fields with the OAuth service selector. Setting it to ''LOGIN'' (or leaving unset) uses standard credential-based authentication.', '''LOGIN'' = standard username/password authentication (default); ''XOAUTH2'' = OAuth2 token authentication.', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, '4a6fcaf7d865a59fa9a2a669a2c86ef5d0ee7ded784ced487febc4a90cc42b13', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:617|read|$authtype = getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_TICKET'', ''LOGIN'');", "admin/mails_ticket.php:635|check|if (in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE_TICKET''), array(''smtps'', ''swiftmailer'')) && getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_TICKET'') != \"XOAUTH2\") {", "admin/mails_ticket.php:640|check|if (in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE_TICKET''), array(''smtps'', ''swiftmailer'')) && getDolGlobalString(''MAIN_MAIL_SMTPS_AUTH_TYPE_TICKET'') === \"XOAUTH2\") {", "admin/mails_ticket.php:99|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_AUTH_TYPE_TICKET\", GETPOST(\"MAIN_MAIL_SMTPS_AUTH_TYPE_TICKET\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_ID', 'string', NULL, 'admin', 'Stores the SMTP sender email address that overrides the From address on outgoing messages.', 'Read at admin/mails.php:499 and 506; written at line 109. Used in core/class/CMailFile.class.php:727-728 where, if the value is a valid email different from the message''s From address, it replaces the From header. Displayed in the mail configuration summary at line 757.', 'Setting this to a valid email address forces all outgoing mail to use it as the From address; leaving it empty uses the default sender.', 'Valid email address string to use as the SMTP From override; empty = no override', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, 'fe48a10ba8a089eddfd8baa176101ca534a09dccf067caebe1e390e4bba569f3', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:109|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_ID\", GETPOST(\"MAIN_MAIL_SMTPS_ID\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "core/class/CMailFile.class.php:727|check|if ($emailMatchs !== false && filter_var(getDolGlobalString(''MAIN_MAIL_SMTPS_ID''), FILTER_VALIDATE_EMAIL) && getDolGlobalString(''MAIN_MAIL_SMTPS_ID'') !== $adressEmailFrom[0]) {", "core/class/CMailFile.class.php:728|read|$this->message->setFrom(getDolGlobalString(''MAIN_MAIL_SMTPS_ID''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_IDT', 'string', NULL, 'debugbar', 'Read by the debugbar module to display an ''ID'' value in the mail configuration debug panel; appears to be an isolated/likely-mistyped reference (the real SMTP auth ID constant used elsewhere in Dolibarr is MAIN_MAIL_SMTPS_ID, without the trailing T).', 'Only occurrence found is debugbar/class/DataCollector/DolibarrCollector.php:114, where getDolGlobalString(''MAIN_MAIL_SMTPS_IDT'') is printed alongside MAIN_MAIL_SMTP_SERVER/PORT and MAIN_MAIL_SMTPS_PW in the debug bar''s mail info block; no admin UI or writer sets ''MAIN_MAIL_SMTPS_IDT'' anywhere in the tree (only ''MAIN_MAIL_SMTPS_ID'' is written by admin/mails.php).', 'Exact behavior unclear from code alone: since nothing writes this exact constant name, it likely always displays empty in the debugbar; setting it manually would just show the value in that debug panel with no other effect found.', 'No documented values found; free-form string intended to mirror an SMTP auth ID.', 1, 0, NULL, 1, '0f74622f394270d940916e9244a0e58bc3c64133f2c2acdd2535b6d31752a5cb', 'v2', '2026-07-24T07:05:23+00:00', '["debugbar/class/DataCollector/DolibarrCollector.php:114|read|$info .= $langs->trans(''ID'').'': <strong>''.getDolGlobalString(\"MAIN_MAIL_SMTPS_IDT\").''</strong><br>'';", "admin/mails.php:109|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_ID\", GETPOST(\"MAIN_MAIL_SMTPS_ID\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_ID_EMAILING', 'string', NULL, 'admin', 'Stores the SMTP authentication username (login ID) used for mass emailing.', 'Configured via admin/mails_emailing.php (dolibarr_set_const at line 96). Read at lines 474 and 481 for display and connection setup, and shown in the admin summary at line 637.', 'Changing this value updates the SMTP login credential for mass emailing; an incorrect value will cause authentication failures.', 'String (SMTP username / email address); empty = no authentication ID.', 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, '38c1a437ddbede4b089b3670222b19aff998fef4495061f15c2d05d23f6e99cb', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_emailing.php:96|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_ID_EMAILING\", GETPOST(\"MAIN_MAIL_SMTPS_ID_EMAILING\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_emailing.php:474|read|$mainstmpid = getDolGlobalString(''MAIN_MAIL_SMTPS_ID_EMAILING'');", "admin/mails_emailing.php:637|read|print ''<tr ...><td>''.getDolGlobalString(''MAIN_MAIL_SMTPS_ID_EMAILING'').''</td></tr>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_ID_PASSWORDRESET', 'string', NULL, 'admin', 'Stores the SMTP authentication username used specifically for password reset emails.', 'Written at admin/mails_passwordreset.php:94 and read at :474, :481, :656. Displayed (with superadmin tooltip) in the admin UI form.', 'Changing this value updates the SMTP login credential for password reset email sending. Leaving unset means no dedicated username is configured for this channel.', 'String: SMTP username/login; empty/unset = no dedicated credential for password reset emails.', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, '75a0c75c6ced75627d546596ce39651ab8c7560841c4ecada8b3e76798ae5d68', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:94|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_ID_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_SMTPS_ID_PASSWORDRESET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_passwordreset.php:474|read|$mainstmpid = getDolGlobalString(''MAIN_MAIL_SMTPS_ID_PASSWORDRESET'');", "admin/mails_passwordreset.php:656|read|print ''<tr class=\"oddeven hideifdefault\"><td>''.$langs->trans(\"MAIN_MAIL_SMTPS_ID\").''</td><td>'' . getDolGlobalString(''MAIN_MAIL_SMTPS_ID_PASSWORDRESET'').''</td></tr>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_ID_TICKET', 'string', NULL, 'admin', 'Specifies the SMTP authentication username used for sending ticket emails.', 'Written in admin/mails_ticket.php at line 94 and read at lines 471, 478, and 631. Displayed in the admin UI with a superadmin tooltip.', 'Setting this constant provides the login credential for SMTP authentication when sending ticket emails. If unset, no username is submitted to the SMTP server.', 'A string containing the SMTP login/username (e.g. an email address or account name).', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, '270927e8bb2b4681df298857d5604b860835bb31435ca70b5fd414e75a1d1686', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:94|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_ID_TICKET\", GETPOST(\"MAIN_MAIL_SMTPS_ID_TICKET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_ticket.php:471|read|$mainstmpid = getDolGlobalString(''MAIN_MAIL_SMTPS_ID_TICKET'');", "admin/mails_ticket.php:631|read|print ''<tr class=\"oddeven hideifdefault\"><td>''.$langs->trans(\"MAIN_MAIL_SMTPS_ID\").''</td><td>''.getDolGlobalString(''MAIN_MAIL_SMTPS_ID_TICKET'').''</td></tr>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_OAUTH_SERVICE', 'string', NULL, 'admin', 'Identifies the OAuth2 service provider used for SMTP authentication.', 'Written at admin/mails.php:117 and via admin/oauth.php:162 (renamed when a provider label changes). Read and displayed at admin/mails.php:536, 538, 544, 767, and admin/mails_ingoing.php:130 to select and show the active OAuth service for outgoing mail.', 'Changing this value switches the OAuth2 provider used for SMTP authentication; an incorrect value will prevent mail sending.', 'String in the format ''PROVIDER-label'' identifying the configured OAuth2 service (e.g. ''GOOGLE-myaccount''); empty = no OAuth service selected', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php|admin/oauth.php|admin/mails_ingoing.php|admin/mails.php|admin/oauth.php', 1, '09aac93666e7e5e98bea5d5fce391ba4ae95142e7e7fe34b49a4e5c6f1589b44', 'v2', '2026-04-21T13:29:58+00:00', '["admin/mails.php:117|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_OAUTH_SERVICE\", GETPOST(\"MAIN_MAIL_SMTPS_OAUTH_SERVICE\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/oauth.php:161|check|if (getDolGlobalString(''MAIN_MAIL_SMTPS_OAUTH_SERVICE'') == $oldname) {", "admin/oauth.php:162|write|if (!dolibarr_set_const($db, ''MAIN_MAIL_SMTPS_OAUTH_SERVICE'', strtoupper($oldprovider).''-''.$newlabel, ''chaine'', 0, '''', $conf->entity)) {", "admin/mails.php:536|read|print $form->selectarray(''MAIN_MAIL_SMTPS_OAUTH_SERVICE'', $oauthservices, getDolGlobalString(''MAIN_MAIL_SMTPS_OAUTH_SERVICE''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_OAUTH_SERVICE_EMAILING', 'string', NULL, 'admin', 'Selects the OAuth2 service used for SMTP authentication in mass emailing.', 'Configured via admin/mails_emailing.php (dolibarr_set_const at line 104). Displayed as a dropdown (selectarray at line 509) populated from available OAuth services. The selected key is also stored in a hidden input (line 517) and shown in the summary (line 647).', 'Changing this value switches the OAuth2 provider used for SMTP authentication in mass emailing; selecting an unconfigured service will prevent email delivery.', 'String key corresponding to an OAuth service name configured in Dolibarr; empty = no OAuth service.', 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, '91567f640c8809975e27d58cd68aaaf52476dc8d09d903f0c317f9240c9a06d6', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_emailing.php:104|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_OAUTH_SERVICE_EMAILING\", GETPOST(\"MAIN_MAIL_SMTPS_OAUTH_SERVICE_EMAILING\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/mails_emailing.php:509|read|print $form->selectarray(''MAIN_MAIL_SMTPS_OAUTH_SERVICE_EMAILING'', $oauthservices, getDolGlobalString(''MAIN_MAIL_SMTPS_OAUTH_SERVICE_EMAILING''));", "admin/mails_emailing.php:647|read|$text = $oauthservices[getDolGlobalString(''MAIN_MAIL_SMTPS_OAUTH_SERVICE_EMAILING'')];"]', 'high', NULL);
