INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_PW_PASSWORDRESET', 'string', NULL, 'admin', 'Stores the SMTP authentication password used specifically for password reset emails.', 'Written at admin/mails_passwordreset.php:96 (using ''password'' sanitization) and read at :489, :496, :661 (displayed masked with asterisks). Configurable via the admin UI.', 'Changing this value updates the SMTP password for the password reset email channel. The value is stored in the database; ensure the database is secured appropriately.', 'String: SMTP password (stored as-is, displayed masked); empty/unset = no dedicated password for password reset emails.', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, '21baefa0171425392b34faa81332bc4ee541b422ab5ab4e16de52396ae939ef3', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:96|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_PW_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_SMTPS_PW_PASSWORDRESET\", ''password''), ''chaine'', 0, '''', $conf->entity);", "admin/mails_passwordreset.php:489|read|$mainsmtppw = getDolGlobalString(''MAIN_MAIL_SMTPS_PW_PASSWORDRESET'');", "admin/mails_passwordreset.php:661|read|print ''<tr class=\"oddeven hideifdefault\"><td>''.$langs->trans(\"MAIN_MAIL_SMTPS_PW\").''</td><td>''.preg_replace(''/./'', ''*'', getDolGlobalString(''MAIN_MAIL_SMTPS_PW_PASSWORDRESET'')).''</t"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTPS_PW_TICKET', 'string', NULL, 'admin', 'Specifies the SMTP authentication password used for sending ticket emails.', 'Written in admin/mails_ticket.php at line 96 (with ''password'' sanitization) and read at lines 486, 493, and 636 where it is masked with asterisks in the display.', 'Setting this constant provides the password for SMTP authentication when sending ticket emails. The value is stored as plaintext in the database and should be treated as sensitive.', 'A plaintext password string for SMTP authentication.', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, '9d407d3a2759c7f6e280fc703a93793489443fb3ca9d5d195ec4dd9b5963d2f7', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:96|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTPS_PW_TICKET\", GETPOST(\"MAIN_MAIL_SMTPS_PW_TICKET\", ''password''), ''chaine'', 0, '''', $conf->entity);", "admin/mails_ticket.php:636|read|print ''<tr class=\"oddeven hideifdefault\"><td>''.$langs->trans(\"MAIN_MAIL_SMTPS_PW\").''</td><td>''.preg_replace(''/./'', ''*'', getDolGlobalString(''MAIN_MAIL_SMTPS_PW_TICKET'')).''</td></tr>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTP_PORT', 'string', '', 'admin', 'Specifies the TCP port used to connect to the SMTP server for sending emails.', 'Read in admin/mails.php:182 as an integer (falling back to PHP ini smtp_port) and displayed at admin/mails.php:736. Written via admin/mails.php:107 and shown in the debugbar at debugbar/class/DataCollector/DolibarrCollector.php:113.', 'Changing this value alters the port used for SMTP connections; incorrect values prevent email delivery.', 'Integer port number. Empty string means use PHP ini smtp_port setting as fallback.', 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, 'bfcb9eb9c9ee3cddd4a7616a2ecd160f14e805f578478ec6a0cd74b9d44eb1bc', 'v2', '2026-04-21T11:16:15+00:00', '["admin/mails.php:182|read|$port = getDolGlobalInt(''MAIN_MAIL_SMTP_PORT'', (int) ini_get(''smtp_port''));", "admin/mails.php:107|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTP_PORT\", GETPOSTINT(\"MAIN_MAIL_SMTP_PORT\"), ''chaine'', 0, '''', $conf->entity);", "debugbar/class/DataCollector/DolibarrCollector.php:113|read|$info .= $langs->trans(''Port'').'': <strong>''.getDolGlobalString(\"MAIN_MAIL_SMTP_PORT\").''</strong><br>'';", "admin/mails.php:444|read|$mainport = getDolGlobalString(''MAIN_MAIL_SMTP_PORT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTP_PORT_EMAILING', 'string', NULL, 'admin', 'Sets the SMTP port used specifically for mass emailing, overriding the global SMTP port.', 'Configured via admin/mails_emailing.php (dolibarr_set_const at line 94). Read as an int at line 152 with a fallback to the PHP ini smtp_port, and as a string at line 422 for connection setup. Displayed in the admin UI at line 618.', 'Changing this port number redirects mass-emailing SMTP connections to the specified port; an incorrect value will prevent email delivery.', 'Integer SMTP port number (e.g. 25, 465, 587); empty/unset = falls back to PHP ini smtp_port.', 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, 'ff69115597a354034565a263844c64a56dfd825a7a8821aea712698df17f08d6', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_emailing.php:94|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTP_PORT_EMAILING\", GETPOST(\"MAIN_MAIL_SMTP_PORT_EMAILING\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_emailing.php:152|read|$port = getDolGlobalInt(''MAIN_MAIL_SMTP_PORT_EMAILING'', (int) ini_get(''smtp_port''));", "admin/mails_emailing.php:422|read|$mainport = getDolGlobalString(''MAIN_MAIL_SMTP_PORT_EMAILING'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTP_PORT_PASSWORDRESET', 'string', NULL, 'admin', 'Sets the SMTP port used specifically for password reset email sending.', 'Written at admin/mails_passwordreset.php:92 and read at :154 (with fallback to php.ini smtp_port) and :422. Configurable via the admin UI at admin/mails_passwordreset.php.', 'Changing this value sets the TCP port for SMTP connections used only for password reset emails. Leaving unset falls back to the PHP ini smtp_port setting.', 'Integer port number (e.g. 25, 465, 587); unset = fallback to ini_get(''smtp_port'').', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, '1a4a78c5a6229b31d204d19b6c3afddfeea96bbdb3b4badc6569533d8b304683', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:92|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTP_PORT_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_SMTP_PORT_PASSWORDRESET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_passwordreset.php:154|read|$port = getDolGlobalInt(''MAIN_MAIL_SMTP_PORT_PASSWORDRESET'', (int) ini_get(''smtp_port''));", "admin/mails_passwordreset.php:422|read|$mainport = getDolGlobalString(''MAIN_MAIL_SMTP_PORT_PASSWORDRESET'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTP_PORT_TICKET', 'string', NULL, 'admin', 'Specifies the SMTP port used for sending ticket emails, overriding the global SMTP port.', 'Written in admin/mails_ticket.php at line 92 and read at lines 152 and 419; falls back to PHP ini smtp_port when unset. Configurable via admin/mails_ticket.php UI.', 'Setting this constant changes the TCP port used for SMTP connections when sending ticket emails. If unset, the PHP ini smtp_port value is used.', 'Integer port number (e.g. 25, 465, 587).', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, '89968c34a1d9d1a719ba3ef201146e51936d495515e7305e7b973991fe8b8ed0', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:92|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTP_PORT_TICKET\", GETPOST(\"MAIN_MAIL_SMTP_PORT_TICKET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_ticket.php:152|read|$port = getDolGlobalInt(''MAIN_MAIL_SMTP_PORT_TICKET'', (int) ini_get(''smtp_port''));", "admin/mails_ticket.php:419|read|$mainport = getDolGlobalString(''MAIN_MAIL_SMTP_PORT_TICKET'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTP_SERVER', 'string', '', 'comm', 'Stores the SMTP server hostname used for sending emails, defaulting to an empty string.', 'Set via admin/mails.php:108 and read in admin/mails.php (lines 186, 413, 728), core/menus/standard/eldy.lib.php:1214 (checked alongside MAIN_MAIL_SENDMODE), debugbar/class/DataCollector/DolibarrCollector.php:112, and comm/mailing/targetemailing.php:482/484.', 'When MAIN_MAIL_SENDMODE is ''smtps'' or ''swiftmail'' and this value is empty, a warning condition is triggered (core/menus/standard/eldy.lib.php:1214); otherwise this hostname is used as the SMTP server for sending mail.', NULL, 0, 0, 'admin/mails.php|admin/mails.php|admin/mails.php|admin/mails.php', 1, '0dd05bd4dbaa7544bdf6c24c8c167236aad23555870083aa83f9229e6f6b4503', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, \"MAIN_MAIL_SMTP_SERVER\", GETPOST(\"MAIN_MAIL_SMTP_SERVER\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''MAIN_MAIL_SENDMODE'') && in_array(getDolGlobalString(''MAIN_MAIL_SENDMODE''), array(''smtps'', ''swiftmail'')) && !getDolGlobalString(''MAIN_MAIL_SMTP_SERVER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTP_SERVER_EMAILING', 'string', NULL, 'admin', 'Overrides the SMTP server hostname used specifically for mass emailing campaigns.', 'Set via admin/mails_emailing.php:95 with dolibarr_set_const, and read with getDolGlobalString(''MAIN_MAIL_SMTP_SERVER_EMAILING'', ini_get(''SMTP'')) in admin/mails_emailing.php:156/390 and comm/mailing/card.php.', 'If set, the emailing module uses this SMTP server instead of the global MAIN_MAIL_SMTP_SERVER or the PHP ini SMTP setting for sending mass emailings.', NULL, 0, 0, 'admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php|admin/mails_emailing.php', 1, 'e2887d5f1e0140199e2a97fbf4475ec3c017d0b11f90aef7499f75146773f3f1', 'v2', '2026-07-24T06:41:12+00:00', '["admin/mails_emailing.php:95|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTP_SERVER_EMAILING\", GETPOST(\"MAIN_MAIL_SMTP_SERVER_EMAILING\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_emailing.php:156|read|$server = getDolGlobalString(''MAIN_MAIL_SMTP_SERVER_EMAILING'', ini_get(''SMTP''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTP_SERVER_PASSWORDRESET', 'string', NULL, 'admin', 'Sets the SMTP server hostname used specifically for password reset email sending.', 'Written at admin/mails_passwordreset.php:93 and read at :158 (with fallback to php.ini SMTP) and :390. Configurable via the admin UI at admin/mails_passwordreset.php.', 'Changing this value routes password reset emails through a different SMTP host. Leaving unset falls back to the PHP ini SMTP setting.', 'String: SMTP hostname (e.g. ''smtp.example.com''); unset = fallback to ini_get(''SMTP'').', 0, 0, 'admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php|admin/mails_passwordreset.php', 1, '18ba24be723fe531d10f7b68c9562a427f0197cd3347ba8eefd7ce70118ad1b5', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_passwordreset.php:93|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTP_SERVER_PASSWORDRESET\", GETPOST(\"MAIN_MAIL_SMTP_SERVER_PASSWORDRESET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_passwordreset.php:158|read|$server = getDolGlobalString(''MAIN_MAIL_SMTP_SERVER_PASSWORDRESET'', ini_get(''SMTP''));", "admin/mails_passwordreset.php:390|read|$mainserver = getDolGlobalString(''MAIN_MAIL_SMTP_SERVER_PASSWORDRESET'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_SMTP_SERVER_TICKET', 'string', NULL, 'admin', 'Specifies the SMTP server hostname used for sending ticket emails, overriding the global SMTP server.', 'Written in admin/mails_ticket.php at line 93 and read at lines 156 and 387; falls back to PHP ini SMTP value when unset. Configurable via admin/mails_ticket.php UI.', 'Setting this constant routes ticket email through the specified SMTP server. If unset, the PHP ini SMTP setting is used.', 'Hostname or IP address of the SMTP server (e.g. ''smtp.example.com'').', 0, 0, 'admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php|admin/mails_ticket.php', 1, '6de2e879cece7a00a0c5d511dd678e708688fd41b62863fd9cbf9e31066b9fee', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mails_ticket.php:93|write|dolibarr_set_const($db, \"MAIN_MAIL_SMTP_SERVER_TICKET\", GETPOST(\"MAIN_MAIL_SMTP_SERVER_TICKET\"), ''chaine'', 0, '''', $conf->entity);", "admin/mails_ticket.php:156|read|$server = getDolGlobalString(''MAIN_MAIL_SMTP_SERVER_TICKET'', ini_get(''SMTP''));", "admin/mails_ticket.php:387|read|$mainserver = getDolGlobalString(''MAIN_MAIL_SMTP_SERVER_TICKET'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAIL_USE_MULTI_PART', 'bool', NULL, 'core', 'Enables multipart/alternative email structure so both plain-text and HTML parts are sent together.', 'When set, core/class/smtps.class.php selects multipart encoding paths at lines 1782, 1803, 1703, and 1687; core/class/CMailFile.class.php adds plain-text parts at lines 1831 and 1845. The X-Dolibarr-Option header at smtps.class.php:1604 reflects the active state.', 'Enabling this sends emails with both HTML and plain-text parts; disabling it sends only the HTML part without a text alternative.', 'Any non-empty string value enables multipart/alternative structure.', 1, 0, NULL, 1, 'de9cfc108d036b8e18394a8f554b1eeed6e1f8d05c9ec41cde1bfdf7ad6663ff', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/smtps.class.php:1604|read|$_header .= ''X-Dolibarr-Option: ''.($conf->global->MAIN_MAIL_USE_MULTI_PART ? ''MAIN_MAIL_USE_MULTI_PART'' : ''No MAIN_MAIL_USE_MULTI_PART'').\"\\r\\n\";", "core/class/CMailFile.class.php:1831|check|if (!$this->atleastoneimage && $strContentAltText && getDolGlobalString(''MAIN_MAIL_USE_MULTI_PART'')) {    // Add plain text message part before html part", "core/class/smtps.class.php:1782|check|if (!array_key_exists(''image'', $this->_msgContent) && $_content[''dataText''] && getDolGlobalString(''MAIN_MAIL_USE_MULTI_PART'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MANIFEST_APPLI_BG_COLOR', 'string', NULL, 'theme', 'Sets the background_color field of the PWA web manifest (theme/manifest.json.php).', 'Read in theme/manifest.json.php:87 to build the web app manifest served for the Progressive Web App: `$manifest->background_color = getDolGlobalString(''MAIN_MANIFEST_APPLI_BG_COLOR'', "#ffffff");`. If the value does not match a 6-hex-digit color pattern it is normalized via colorStringToArray/colorArrayToHex.', 'Changing it changes the splash/background color shown when the Dolibarr PWA is installed and launched from a device home screen.', 'Any CSS-like color string; default is "#ffffff". Non-hex values are converted to hex via colorStringToArray/colorArrayToHex.', 0, 0, NULL, 1, '014d02902f8d41614c8ec7a5b43a2f33191816443861e3a1915357aeb998e69b', 'v2', '2026-07-24T07:05:23+00:00', '["theme/manifest.json.php:87: $manifest->background_color = getDolGlobalString(''MAIN_MANIFEST_APPLI_BG_COLOR'', \"#ffffff\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MANIFEST_APPLI_LOGO_URL', 'string', NULL, 'theme', 'Sets the URL of the icon used in the PWA web manifest, if defined.', 'Read in theme/manifest.json.php:98-100: only added to the manifest icons array if the getDolGlobalString call is truthy: `if (getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL'')) { $icon->src = getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL''); ... }`.', 'When set, it overrides the default application icon shown in the browser/PWA installer for the installed app icon.', 'A URL string pointing to an icon image; empty/unset means no custom icon entry is added.', 0, 0, NULL, 1, '348c3040151bff646f78b504bae8a9c5ad81a8ab7ef5ceea4426c383941881c2', 'v2', '2026-07-24T07:05:23+00:00', '["theme/manifest.json.php:98: if (getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL'')) {", "theme/manifest.json.php:100: $icon->src = getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MANIFEST_APPLI_LOGO_URL_SIZE', 'string', NULL, 'theme', 'Sets the pixel size (width=height) of the PWA manifest icon declared via MAIN_MANIFEST_APPLI_LOGO_URL.', 'Read in theme/manifest.json.php:101-102: used to build the manifest icon ''sizes'' attribute as a square: `$icon->sizes = getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL_SIZE'') . "x" . getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL_SIZE'');`. Only applied if truthy, alongside MAIN_MANIFEST_APPLI_LOGO_URL.', 'Sets the declared icon dimensions in the manifest; a mismatch with the actual icon file dimensions could cause browsers to reject or mis-render the icon.', 'A numeric pixel size string (e.g. "192"), used to build a "WxW" sizes attribute (e.g. "192x192").', 0, 0, NULL, 1, '7e2481612b51692bd4f204882b82c5808801b94b9559ceb975157051d85b89b8', 'v2', '2026-07-24T07:05:23+00:00', '["theme/manifest.json.php:101: if (getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL_SIZE'')) {", "theme/manifest.json.php:102: $icon->sizes = getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL_SIZE'') . \"x\" . getDolGlobalString(''MAIN_MANIFEST_APPLI_LOGO_URL_SIZE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MANIFEST_APPLI_THEME_COLOR', 'string', NULL, 'theme', 'Overrides the theme_color declared in the web app manifest (manifest.json) used for PWA/mobile browser chrome theming.', 'In theme/manifest.json.php:82, $manifest->theme_color is set from this constant, falling back to THEME_ELDY_TOPMENU_BACK1 and finally the hardcoded default ''#F05F40''.', 'Setting it changes the color of the browser/OS chrome (e.g. Android address bar, PWA splash) when the Dolibarr web app manifest is used; unset falls back to the top-menu background color or the default orange.', 'String color value (e.g. hex ''#F05F40'' as ultimate default).', 1, 0, NULL, 1, '0e1a36203e8f03ab19d92f72a2d2ccb8f339c0c40549f21cb6b073ba4d5ff5ee', 'v2', '2026-07-24T07:05:23+00:00', '["theme/manifest.json.php:82: $manifest->theme_color = getDolGlobalString(''MAIN_MANIFEST_APPLI_THEME_COLOR'', getDolGlobalString(''THEME_ELDY_TOPMENU_BACK1'', ''#F05F40''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MANIFEST_DISPLAY', 'string', NULL, 'theme', 'Sets the display field of the PWA web manifest (theme/manifest.json.php), controlling browser UI shown when installed.', 'Read in theme/manifest.json.php:92: `$manifest->display = getDolGlobalString(''MAIN_MANIFEST_DISPLAY'', "minimal-ui");`. This value is emitted verbatim into the manifest.json served to browsers/PWA installers.', 'Changing it changes how the installed Dolibarr PWA is displayed (e.g. with or without browser chrome); invalid values could produce a manifest not recognized by the browser''s PWA installer.', 'Web manifest ''display'' values (browser-defined), e.g. "minimal-ui" (default), "standalone", "fullscreen", "browser".', 0, 0, NULL, 1, '076a230d59585d7382c95d3a2f1f71a5c6966ff28fd60af9918b579dd7c98dda', 'v2', '2026-07-24T07:05:23+00:00', '["theme/manifest.json.php:92: $manifest->display = getDolGlobalString(''MAIN_MANIFEST_DISPLAY'', \"minimal-ui\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MASSACTION_CREATEBILLS_REDIRECT_IF_MANY', 'string', NULL, 'commande', 'After a mass ''create bills'' action on the order list creates multiple invoices, redirects directly to the invoice list instead of showing a summary message.', 'Checked in commande/list.php:737: if (getDolGlobalInt(''MAIN_MASSACTION_CREATEBILLS_REDIRECT_IF_MANY'') == 1) { header(''Location: .../compta/facture/list.php...''); exit; }, used in the else branch (nb_bills_created != 1).', 'When set to 1, creating multiple invoices via mass action immediately redirects the browser to the customer invoice list; when unset, a summary message with the count of created bills is shown instead.', 'Int: value == 1 triggers the redirect to the invoice list.', 0, 0, NULL, 1, 'bde222c561e283bd9e2004ad7406597d2bc1b6d3cf4132cb38a0adda662a5117', 'v2', '2026-07-24T07:05:23+00:00', '["commande/list.php:737: if (getDolGlobalInt(''MAIN_MASSACTION_CREATEBILLS_REDIRECT_IF_MANY'') == 1) { header(\"Location: \".../facture/list.php...); exit; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MASSACTION_CREATEBILLS_REDIRECT_IF_ONE', 'string', NULL, 'commande', 'After a mass ''create bills'' action on the order list creates exactly one invoice, redirects directly to that invoice''s card instead of showing a summary message.', 'Checked in commande/list.php:728: if ($nb_bills_created == 1) { if (getDolGlobalInt(''MAIN_MASSACTION_CREATEBILLS_REDIRECT_IF_ONE'') == 1) { header(''Location: .../compta/facture/card.php?id=''.$lastid); exit; } ... }.', 'When set to 1, creating a single invoice via mass action immediately redirects the browser to that invoice''s card page; when unset, a message with a link to the invoice is shown instead.', 'Int: value == 1 triggers the redirect to the created invoice.', 0, 0, NULL, 1, 'cbc9a96fb303b2d4d46f46f4fc28381cb0c56204fd605bb940d795fc1d6f2c92', 'v2', '2026-07-24T07:05:23+00:00', '["commande/list.php:728: if (getDolGlobalInt(''MAIN_MASSACTION_CREATEBILLS_REDIRECT_IF_ONE'') == 1) { header(''Location: ''.DOL_URL_ROOT.''/compta/facture/card.php?id=''.urlencode((string) $lastid)); exit; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MASSVALIDATE_', 'string', NULL, 'core', 'Per-object-class flag (MAIN_MASSVALIDATE_<OBJECTCLASS>_NO_GLOBAL_TRANSACTION) controlling whether mass validation wraps each record in its own transaction instead of one global transaction.', 'Read dynamically in core/actions_massactions.inc.php:1083 by concatenating the object class name; documented at line 1077.', 'When set to 1 for a given object class, mass validation wraps each record processed in its own transaction rather than a single global transaction.', '1 = wraps each record in its own transaction (per comment: MAIN_MASSVALIDATE_<OBJECTCLASS>_NO_GLOBAL_TRANSACTION = 1 wraps each)', 1, 0, NULL, 1, '40bd68e782425c3b81b1728559ccbde16b9433d3a77b1284800d024b8ee4e965', 'v2', '2026-07-24T06:41:12+00:00', '["// MAIN_MASSVALIDATE_<OBJECTCLASS>_NO_GLOBAL_TRANSACTION = 1 wraps each", "$perrecordtransaction = (int) getDolGlobalInt(''MAIN_MASSVALIDATE_''.strtoupper($objectclass).''_NO_GLOBAL_TRANSACTION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAXLIST_OVERLOAD', 'string', NULL, 'compta', 'Overrides the maximum number of draft/open records shown on module home/index dashboards (invoices, orders, accounting).', 'Read with getDolGlobalInt(''MAIN_MAXLIST_OVERLOAD'', 500) in fourn/facture/index.php:54/56, compta/index.php:82/83, compta/facture/index.php:56/57, and commande/index.php:67/69, across 21 occurrences.', 'Increasing the value raises the count cap used for draft/open record counters on these index pages; the default fallback used in most call sites is 500.', NULL, 0, 0, NULL, 1, '6d9dc01f842bf6e518973b607bdc7337a8123a20cb05ef3455d8fd03524ba844', 'v2', '2026-07-24T06:41:12+00:00', '["fourn/facture/index.php:54|read|$maxDraftCount = getDolGlobalInt(''MAIN_MAXLIST_OVERLOAD'', 500);", "commande/index.php:67|read|$maxDraftCount = !getDolGlobalString(''MAIN_MAXLIST_OVERLOAD'') ? 500 : $conf->global->MAIN_MAXLIST_OVERLOAD;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAXTABS_IN_CARD', 'string', NULL, 'core', 'Sets the maximum number of tabs displayed directly on an object card before remaining tabs are collapsed (e.g. into a ''more'' popup).', 'Read in core/lib/functions.lib.php:3180 as $limittoshow, defaulting to 99, only applied when the caller didn''t already pass an explicit $limittoshow (empty check); inline comment ''if =0 we don''t use the feature''. On smartphone layout ($conf->dol_optimize_smallscreen), the limit is forced to 1 regardless.', 'Lowering it reduces how many tabs are shown inline on object cards before overflow handling kicks in; setting it to 0 disables the tab-limiting feature per the inline comment. Smartphone view always overrides to 1 tab regardless of this setting.', 'Integer number of tabs; default 99; comment states ''0 = feature not used''.', 1, 0, NULL, 1, '89df0461766fd0e2f63282ac1894c3dff07994d680f227be0ab262e1a500fae1', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3180|read|$limittoshow = getDolGlobalInt(''MAIN_MAXTABS_IN_CARD'', 99);", "// if =0 we don''t use the feature"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAX_DECIMALS_CURRENCY_TOT', 'string', NULL, 'core', 'Sets the maximum decimal places for currency total amounts, falling back to MAIN_MAX_DECIMALS_TOT.', 'Read at core/lib/functions.lib.php:7965 with MAIN_MAX_DECIMALS_TOT as the default fallback. Also used in core/modules/facture/doc/pdf_sponge.modules.php:2147 to compute a maximum decimal bound for invoice PDF generation.', 'Adjusting this value changes decimal precision for totals in financial outputs including invoice PDFs.', 'Integer value representing decimal places; if unset, falls back to MAIN_MAX_DECIMALS_TOT', 1, 0, NULL, 1, '987193ea5dabc4bb7f106a7142c6667ed0cccb47e20c91eeb2e3d19cb2711119', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:7965|read|$nbofdectoround = getDolGlobalInt(''MAIN_MAX_DECIMALS_CURRENCY_TOT'', getDolGlobalInt(''MAIN_MAX_DECIMALS_TOT''));\t\t// TODO Use param of currency", "core/modules/facture/doc/pdf_sponge.modules.php:2147|read|$maxnbofdec = getDolGlobalInt(''MAIN_MAX_DECIMALS_TOT'') + getDolGlobalInt(''MAIN_MAX_DECIMALS_CURRENCY_TOT'', getDolGlobalInt(''MAIN_MAX_DECIMALS_TOT'')) + 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAX_DECIMALS_CURRENCY_UNIT', 'string', NULL, 'core', 'Sets the number of decimals used when rounding a currency-unit amount (rounding mode ''CU'') in the price()/amount formatting function.', 'In core/lib/functions.lib.php:7946, `getDolGlobalInt(''MAIN_MAX_DECIMALS_CURRENCY_UNIT'', getDolGlobalInt(''MAIN_MAX_DECIMALS_UNIT''))` is used when $rounding == ''CU''; falls back to MAIN_MAX_DECIMALS_UNIT if unset. A TODO comment notes it should use the currency''s own parameter instead.', 'Changing it controls the decimal precision applied to unit-currency amounts specifically, distinct from the general MAIN_MAX_DECIMALS_UNIT; if unset, behavior is identical to MAIN_MAX_DECIMALS_UNIT.', 'Integer number of decimal places; falls back to MAIN_MAX_DECIMALS_UNIT (commented ''usually 5'') if not set.', 1, 0, NULL, 1, 'c19a4e20ddd5749e877d0b578025baef05c59852b90bb376c468556600010080', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:7946|read|$nbofdectoround = getDolGlobalInt(''MAIN_MAX_DECIMALS_CURRENCY_UNIT'', getDolGlobalInt(''MAIN_MAX_DECIMALS_UNIT''));\t// TODO Use param of currency"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAX_DECIMALS_SHOWN', 'bool', NULL, 'core', 'Sets the maximum number of decimal places displayed for amounts in the Dolibarr interface.', 'Read in admin/limits.php:187,218 for the admin UI, core/lib/functions.lib.php:7789 for PHP formatting, and core/js/lib_head.js.php:1396,1475 for JavaScript formatting. The comment in core/lib/functions.lib.php:7725 notes: ''1=Truncate if there is more decimals than MAIN_MAX_DECIMALS_SHOWN (default), 0=Does not truncate.''', 'Reducing this value truncates displayed decimal precision across the interface; a value containing ''...'' triggers special truncation logic in the PHP formatter.', 'Integer number of decimal places to show; may also contain ''...'' to trigger truncation mode', 0, 0, 'admin/limits.php|admin/limits.php', 1, 'dde6684c12cb1a64cb32b7ea2fe3945fcc0da1df058d97234f4e172bfd4dd800', 'v2', '2026-04-21T13:29:58+00:00', '["1=Truncate if there is more decimals than MAIN_MAX_DECIMALS_SHOWN (default), 0=Does not truncate.", "$nbdecimalmaxshown = (int) str_replace(''...'', '''', getDolGlobalString(''MAIN_MAX_DECIMALS_SHOWN''));", "if (preg_match(''/\\.\\.\\./'', getDolGlobalString(''MAIN_MAX_DECIMALS_SHOWN''))) {", "var main_max_dec_shown = <?php echo (int) str_replace(''.'', '''', getDolGlobalString(''MAIN_MAX_DECIMALS_SHOWN'')); ?>;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAX_DECIMALS_STOCK', 'string', NULL, 'core', 'Sets the maximum number of decimal places used when rounding stock quantities.', 'Read via getDolGlobalInt at core/lib/functions.lib.php:7961 with a default of 5. The comment at line 7847 identifies it as the ''MS'' rounding mode: ''MS''=Round to Max for stock quantity (MAIN_MAX_DECIMALS_STOCK).', 'Reducing this value decreases precision for stock quantity display and calculations; increasing it allows finer-grained stock figures.', '''MS'' rounding mode uses this constant; integer value representing decimal places; default is 5', 1, 0, NULL, 1, '4d0d6d0cf5263bea4d970286e475128b95ea01dc4d4b9766b86f0b00d96658b8', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:7847  *                                                                  ''MS''=Round to Max for stock quantity (MAIN_MAX_DECIMALS_STOCK)", "core/lib/functions.lib.php:7961|read|$nbofdectoround = getDolGlobalInt(''MAIN_MAX_DECIMALS_STOCK'', 5);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAX_DECIMALS_TOT', 'string', NULL, 'core', 'Sets the maximum number of decimals used when displaying/rounding total amounts (prices, invoices).', 'Configured via admin/limits.php:188/221 (admin UI), and read/used in core/lib/price.lib.php:411/420/431, core/class/commonobject.class.php:4239, and core/modules/facture/doc/pdf_sponge.modules.php:2145.', 'Changing it affects the rounding precision applied to total amounts throughout price calculations, PDF generation, and the difference tolerance used when comparing paid vs. due totals.', NULL, 0, 0, 'admin/limits.php|admin/limits.php', 1, 'c8b56643fdb9914e49f1da96cfb9fa231c05d8a70a2ea14623696116ceca8cb8', 'v2', '2026-07-24T06:41:12+00:00', '["core/lib/functions.lib.php:7709|*  @param int<-1,max> $rounding MINIMUM number of decimal to show: 0=no change, -1=we use min(getDolGlobalString(''MAIN_MAX_DECIMALS_UNIT''), getDolGlobalString(''MAIN_MAX_DECIMALS_TOT''))", "core/class/commonobject.class.php:4239|read|$maxdiff = (10 * pow(10, -1 * getDolGlobalInt(''MAIN_MAX_DECIMALS_TOT'', 0)));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MAX_DECIMALS_UNIT', 'string', NULL, 'core', 'Sets the maximum number of decimals used when displaying/rounding unit prices.', 'Configured via admin/limits.php:184/217 (admin UI), read/used in core/lib/price.lib.php:419/430, and referenced in societe/price.php:410/418/519/531 for the ''PrecisionUnitIsLimitedToXDecimals'' message.', 'Changing it affects the rounding precision applied to unit prices; documented as usable together with MAIN_MAX_DECIMALS_TOT via min() when rounding=-1.', NULL, 0, 0, 'admin/limits.php|admin/limits.php', 1, '6e0f6600e626785c3c5c8e7328351cfbf8321ca117b06b6b65825c9239779dd8', 'v2', '2026-07-24T06:41:12+00:00', '["compta/facture/class/facture.class.php:6043|* @param int|string $rounding ... or -1, we use min($conf->global->MAIN_MAX_DECIMALS_UNIT,$conf->global->MAIN_MAX_DECIMALS_TOT)", "core/lib/functions.lib.php:7828|* ''MU''=Round to Max unit price (MAIN_MAX_DECIMALS_UNIT)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MEMBER_CODE_ALWAYS_REQUIRED', 'string', NULL, 'core', 'Forces a member (adherent) code to be required even for numbering modules that would otherwise allow a null code.', 'Checked in core/modules/member/modules_member.class.php:97 inside getToolTip(); when set and the module''s code_null flag is true, the tooltip shows the code marked as ''forced to'' required by strikethrough text (''ForcedToByAModule'').', 'Enabling it changes the member-numbering-module tooltip to indicate the code is forced required, overriding the module''s own code_null setting.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, '34e973a48947823dc52e2f7699172b13f76aaf552bac752fc6f09e152c3030f2', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/member/modules_member.class.php:97: if (getDolGlobalString(''MAIN_MEMBER_CODE_ALWAYS_REQUIRED'') && !empty($this->code_null)) {", "core/modules/member/modules_member.class.php:99: $strikeend = ''</strike> ''.yn(1, 1, 2).'' (''.$langs->trans(\"ForcedToByAModule\", $langs->transnoentities(\"yes\")).'')'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MEMORY_LIMIT_ARCHIVE_DATAROOT', 'string', NULL, 'admin', 'PHP memory_limit override applied while running the admin ''Export files/archive dataroot'' tool.', 'Used in admin/tools/export_files.php:112: `$MemoryLimit = getDolGlobalString(''MAIN_MEMORY_LIMIT_ARCHIVE_DATAROOT''); if (!empty($MemoryLimit)) { @ini_set(''memory_limit'', $MemoryLimit); }`. Comment notes: ''If value has been forced with a php_admin_value, this has no effect.''', 'Raises (or otherwise sets) the PHP memory limit for the duration of the archive/export of the data root directory, letting large archives be built without hitting PHP''s default memory limit; has no effect if the host''s php.ini/php_admin_value forces memory_limit.', 'A PHP memory_limit string, e.g. ''512M'' (per the inline code comment ''Example of value: 512M''); empty/unset leaves the current memory_limit untouched.', 0, 0, 'admin/tools/export_files.php', 1, '47ffc70b37c55384f1e6c59c2bd5ad70173c36b491d1b8e10bb0def4400f51d8', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/export_files.php:112: $MemoryLimit = getDolGlobalString(''MAIN_MEMORY_LIMIT_ARCHIVE_DATAROOT'');", "admin/tools/export_files.php: /* If value has been forced with a php_admin_value, this has no effect. Example of value: ''512M'' */"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MEMORY_LIMIT_DUMP', 'string', NULL, 'core', 'Overrides the PHP memory_limit ini setting specifically while running a database dump (backup) operation.', 'Read in core/class/utils.class.php:452 inside Utils::dumpDatabase(), just before the dump command is executed; if non-empty, it is passed to ini_set(''memory_limit'', ...). The inline comment notes this has no effect if memory_limit was locked via a php_admin_value in the web server/php-fpm config.', 'Setting it (e.g. ''512M'') raises or lowers the PHP memory limit for the duration of the dump process, letting large database dumps avoid memory-exhaustion errors; has no effect if the hosting environment enforces memory_limit via php_admin_value.', 'String: a PHP memory_limit value such as ''512M'' (per the inline example in code).', 1, 0, NULL, 1, 'eba71cf53d7cb80e132d0ecd94c34771e642e990ec50bd5f73df92119f30db5a', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/utils.class.php:452|read|$MemoryLimit = getDolGlobalString(''MAIN_MEMORY_LIMIT_DUMP'');", "/* If value has been forced with a php_admin_value, this has no effect. Example of value: ''512M'' */", "if (!empty($MemoryLimit)) { @ini_set(''memory_limit'', $MemoryLimit); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENUFRONT_SMARTPHONE', 'string', 'eldy_menu.php', 'admin', 'Specifies the menu handler file used for the smartphone front-office (public portal mobile) interface.', 'Written in admin/menus.php at line 82 and read at lines 206 and 209. Referenced in install/upgrade2.php at line 4524 alongside MAIN_MENUFRONT_STANDARD. Can be overridden by MAIN_MENUFRONT_SMARTPHONE_FORCED.', 'Changing this value switches the mobile menu theme for the public portal. An upgrade script checks for the deprecated ''auguria_menu'' value.', 'String filename of a menu handler module (default: ''eldy_menu.php'')', 0, 0, 'admin/menus.php|admin/menus.php|admin/menus.php', 1, '310284fab332d01547a29f07d35948b20b71a5879370d299725041347fcb21ae', 'v2', '2026-04-21T11:16:15+00:00', '["dolibarr_set_const($db, \"MAIN_MENUFRONT_SMARTPHONE\", GETPOST(''MAIN_MENUFRONT_SMARTPHONE'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "|| getDolGlobalString(''MAIN_MENUFRONT_STANDARD'') == ''auguria_menu'' || getDolGlobalString(''MAIN_MENUFRONT_SMARTPHONE'') == ''auguria_menu'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENUFRONT_SMARTPHONE_FORCED', 'string', NULL, 'admin', 'Forces a specific frontend smartphone menu module, overriding the user-selected frontend smartphone menu.', 'Read and checked in admin/menus.php at lines 206, 208, 209. When set to a value matching ''/smartphone/'', it is used as the forced frontend smartphone menu, overriding MAIN_MENUFRONT_SMARTPHONE.', 'When set, the forced frontend smartphone menu is always applied regardless of user selection. When unset, MAIN_MENUFRONT_SMARTPHONE is used.', 'A menu module identifier string containing ''smartphone''; empty or unset to use the user-selected frontend menu.', 0, 0, 'admin/menus.php|admin/menus.php|admin/menus.php', 1, 'd7dca1940d05418af4eea77961758f12ef6c743e4eb4fccf30bd9856c6693c05', 'v2', '2026-04-21T13:50:40+00:00', '["admin/menus.php:208|check|if (getDolGlobalString(''MAIN_MENU_SMARTPHONE_FORCED'') && preg_match(''/smartphone/'', getDolGlobalString(\"MAIN_MENUFRONT_SMARTPHONE_FORCED\"))", "admin/menus.php:206|read|$formadmin->select_menu(getDolGlobalString(''MAIN_MENUFRONT_SMARTPHONE_FORCED'', getDolGlobalString(''MAIN_MENUFRONT_SMARTPHONE'')), ''MAIN_MENUFRONT_SMARTPHONE'', array_merge($dirstanda", "admin/menus.php:209|read||| (!getDolGlobalString(''MAIN_MENUFRONT_SMARTPHONE_FORCED'') && getDolGlobalString(''MAIN_MENU_SMARTPHONE'') && preg_match(''/smartphone/'', getDolGlobalString(''MAIN_MENUFRONT_SMARTPHON'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENUFRONT_STANDARD', 'string', 'eldy_menu.php', 'core', 'Specifies the menu handler file used for the standard front-office (public portal) interface.', 'Written in admin/menus.php at line 81 and read in main.inc.php at line 1374 and core/get_menudiv.php at line 280. Defaults to ''eldy_menu.php'' when unset. Can be overridden by MAIN_MENUFRONT_STANDARD_FORCED.', 'Changing this value switches the menu theme for the public-facing portal. An upgrade script checks for the deprecated ''auguria_menu'' value.', 'String filename of a menu handler module (default: ''eldy_menu.php'')', 0, 0, 'admin/menus.php|admin/menus.php', 1, '2770130c9e3ff340d48cd828a49dd212a448e3af4c643b2b2e13f03fcf23cbcf', 'v2', '2026-04-21T11:16:15+00:00', '["dolibarr_set_const($db, \"MAIN_MENUFRONT_STANDARD\", GETPOST(''MAIN_MENUFRONT_STANDARD'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$conf->standard_menu = getDolGlobalString(''MAIN_MENUFRONT_STANDARD_FORCED'', getDolGlobalString(''MAIN_MENUFRONT_STANDARD'', ''eldy_menu.php''));", "|| getDolGlobalString(''MAIN_MENUFRONT_STANDARD'') == ''auguria_menu'' || getDolGlobalString(''MAIN_MENUFRONT_SMARTPHONE'') == ''auguria_menu'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENUFRONT_STANDARD_FORCED', 'string', NULL, 'core', 'Forces a specific front-office standard menu handler, overriding the user-configured front menu.', 'Read in main.inc.php:1374 and core/get_menudiv.php:280 as the authoritative front-office menu file, falling back to MAIN_MENUFRONT_STANDARD or ''eldy_menu.php''. Also presented in admin/menus.php:190.', 'When set, this overrides the admin-configured front-office menu; removing it restores the MAIN_MENUFRONT_STANDARD selection.', 'Any valid menu handler filename (e.g. ''eldy_menu.php''); empty/unset = MAIN_MENUFRONT_STANDARD or ''eldy_menu.php'' is used', 0, 0, 'admin/menus.php', 1, '1f21a351ce8c4590258464b64f7c6a333423b53510aad26c0d7b5127de3157b4', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1374|read|$conf->standard_menu = getDolGlobalString(''MAIN_MENUFRONT_STANDARD_FORCED'', getDolGlobalString(''MAIN_MENUFRONT_STANDARD'', ''eldy_menu.php''));", "core/get_menudiv.php:280|read|$conf->standard_menu = (!getDolGlobalString(''MAIN_MENUFRONT_STANDARD_FORCED'') ? (!getDolGlobalString(''MAIN_MENUFRONT_STANDARD'') ? ''eldy_menu.php'' : $conf->global->MAIN_MENUFRONT_ST", "admin/menus.php:190|read|$formadmin->select_menu(getDolGlobalString(''MAIN_MENUFRONT_STANDARD_FORCED'', getDolGlobalString(''MAIN_MENUFRONT_STANDARD'')), ''MAIN_MENUFRONT_STANDARD'', $dirstandard, !getDolGlobalS"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENU_CHEQUE_DEPOSIT_ON', 'string', NULL, 'core', 'Forces the ''Cheque deposits'' menu entry to appear even when the invoice module is disabled.', 'Checked in core/menus/standard/eldy.lib.php:2218, as an additional OR condition alongside isModEnabled(''invoice''): the check deposit menu is shown if BANK_DISABLE_CHECK_DEPOSIT is not set and (bank module enabled) and (invoice module enabled OR this constant is set).', 'Enabling it makes the cheque deposit menu entry visible even without the invoice module active, provided bank is enabled and BANK_DISABLE_CHECK_DEPOSIT is not set.', 'Truthy forces the cheque deposit menu to show regardless of the invoice module state; empty/0 leaves visibility tied only to the invoice module.', 1, 0, NULL, 1, '18d85cba1c187ce15a2eedaf9540d6cc86390b73df6bc183eb9e20df82e19a6a', 'v2', '2026-07-24T07:05:23+00:00', '["core/menus/standard/eldy.lib.php:2218: if (!getDolGlobalString(''BANK_DISABLE_CHECK_DEPOSIT'') && isModEnabled(''bank'') && (isModEnabled(''invoice'') || getDolGlobalString(''MAIN_MENU_CHEQUE_DEPOSIT_ON''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENU_HIDE_UNAUTHORIZED', 'bool', NULL, 'core', 'Hides menu entries for which the current user has no permission, instead of showing them disabled.', 'Checked in 8 occurrences across auguria.lib.php, eldy.lib.php, auguria_menu.php, eldy_menu.php, empty.php, and functions.lib.php. The admin/ihm.php write line is commented out, indicating the setting is not actively saved via the UI form. When set, menu items the user cannot access are hidden rather than greyed out.', 'Enabling this constant removes unauthorized menu entries from view entirely; disabling it shows them in a disabled state.', 'Non-empty = unauthorized menu items hidden; empty or unset = shown disabled', 0, 0, 'admin/ihm.php', 1, '363efe2c5a37d81a789178e26d229fca61fb5ef8f3da7a9250be39bfb31d5f54', 'v2', '2026-04-21T13:29:58+00:00', '["core/menus/standard/auguria.lib.php:558|check|if (getDolGlobalString(''MAIN_MENU_HIDE_UNAUTHORIZED'') && empty($menu_array[$i][''enabled''])) {", "core/menus/standard/eldy.lib.php:981|check|if (getDolGlobalString(''MAIN_MENU_HIDE_UNAUTHORIZED'') && empty($menu_array[$i][''enabled''])) {", "core/menus/standard/auguria.lib.php:747|check|if (!$menuentry[''perms''] && getDolGlobalString(''MAIN_MENU_HIDE_UNAUTHORIZED'')) {", "admin/ihm.php:281|write|//dolibarr_set_const($db, \"MAIN_MENU_HIDE_UNAUTHORIZED\", GETPOST(\"MAIN_MENU_HIDE_UNAUTHORIZED\", ''aZ09''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENU_INVERT', 'string', NULL, 'core', 'When enabled, inverts the top menu layout by swapping the logo and menu positions.', 'Checked in core/menus/standard/auguria.lib.php:162, core/menus/standard/eldy.lib.php:579, main.inc.php:2193, theme/eldy/global.inc.php:3295, theme/md/style.css.php:3360, and others. Read in auguria.lib.php:550 and eldy.lib.php:973 to append ''invert'' CSS class. Ten occurrences across multiple files. No admin UI write is present.', 'Enabling this constant applies an ''invert'' CSS class to the top menu container and suppresses logo display in the standard menu position.', 'Boolean flag; unset or 0 = standard menu layout; any truthy value = inverted menu layout.', 1, 0, NULL, 1, '7d1bd2072a796dfe7381fd8f40067d41c87ca97f776a62b56b2c0f19a1e4c2de', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:2193|read|print ''<div id=\"tmenu_tooltip''.(!getDolGlobalString(''MAIN_MENU_INVERT'') ? '''' : ''invert'').''\" class=\"tmenu\">''.\"\\n\";", "core/menus/standard/eldy.lib.php:973|read|$invert = !getDolGlobalString(''MAIN_MENU_INVERT'') ? \"\" : \"invert\";", "core/menus/standard/auguria.lib.php:162|check|if (!getDolGlobalString(''MAIN_MENU_INVERT'') && getDolGlobalString(''MAIN_SHOW_LOGO'') && !getDolGlobalString(''MAIN_OPTIMIZEFORTEXTBROWSER'')) {", "theme/eldy/global.inc.php:3295|check|<?php if (!getDolGlobalString(''MAIN_MENU_INVERT'')) { ?>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENU_LEFT_DROPDOWN', 'string', NULL, 'core', 'Switches the left navigation menu rendering mode from the standard vertical list to a dropdown-style menu.', 'In main.inc.php:3539, when truthy, $menumanager->showmenu() is called with mode ''leftdropdown'' instead of the default ''left'', changing how the left menu is displayed.', 'Setting it changes the left menu''s visual/interaction style to a dropdown variant instead of the standard expanded vertical menu.', 'Boolean-like (read via getDolGlobalInt): truthy selects ''leftdropdown'' menu mode, otherwise the standard ''left'' mode is used.', 0, 0, NULL, 1, '2870b88def80bcd3fa367dc646e59201be8bbcdca8cdaf8c92d68d7d1b8954d1', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:3539|check|if (getDolGlobalInt(''MAIN_MENU_LEFT_DROPDOWN'')) {"]', 'medium', NULL);
