INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENU_SMARTPHONE_FORCED', 'string', NULL, 'admin', 'Forces a specific backend smartphone menu module, overriding the user-selected smartphone menu.', 'Read and checked in admin/menus.php at lines 197, 199, 200. When set to a value matching ''/smartphone/'', it is used as the forced menu for the smartphone backend layout; it overrides MAIN_MENU_SMARTPHONE.', 'When set, administrators cannot override the smartphone menu through normal selection; the forced menu is always applied. When unset, the user-selected MAIN_MENU_SMARTPHONE value is used.', 'A menu module identifier string containing ''smartphone''; empty or unset to use the user-selected menu.', 0, 0, 'admin/menus.php|admin/menus.php|admin/menus.php|admin/menus.php', 1, '3f83bfe84da6d1b2cdbcea884435e07ee02f42a9574b4630c2d8ffca7f7f1540', 'v2', '2026-04-21T13:50:40+00:00', '["admin/menus.php:199|check|if (getDolGlobalString(''MAIN_MENU_SMARTPHONE_FORCED'') && preg_match(''/smartphone/'', getDolGlobalString(''MAIN_MENU_SMARTPHONE_FORCED''))", "admin/menus.php:197|read|$formadmin->select_menu(getDolGlobalString(''MAIN_MENU_SMARTPHONE_FORCED'', getDolGlobalString(''MAIN_MENU_SMARTPHONE'')), ''MAIN_MENU_SMARTPHONE'', array_merge($dirstandard, $dirsmartph", "admin/menus.php:200|read||| (!getDolGlobalString(''MAIN_MENU_SMARTPHONE_FORCED'') && getDolGlobalString(''MAIN_MENU_SMARTPHONE'') && preg_match(''/smartphone/'', getDolGlobalString(''MAIN_MENU_SMARTPHONE'')))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MENU_STANDARD', 'string', 'eldy_menu.php', 'core', 'Specifies the menu handler file used for the standard (back-office) interface.', 'Written in admin/menus.php at line 78 and read in main.inc.php at line 1371 and core/get_menudiv.php at line 278. Defaults to ''eldy_menu.php'' when unset. Can be overridden by MAIN_MENU_STANDARD_FORCED.', 'Changing this value switches the menu theme for all back-office users. An upgrade script at install/upgrade2.php checks for the deprecated ''auguria_menu'' value.', 'String filename of a menu handler module (default: ''eldy_menu.php'')', 0, 0, 'admin/menus.php|admin/menus/index.php|admin/menus/edit.php|admin/menus.php', 1, '9128c54044a39eacdc9f3c08708ee14e5acdd419347d7bf65bbe84d146d51e1f', 'v2', '2026-04-21T11:16:15+00:00', '["dolibarr_set_const($db, \"MAIN_MENU_STANDARD\", GETPOST(''MAIN_MENU_STANDARD'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$conf->standard_menu = getDolGlobalString(''MAIN_MENU_STANDARD_FORCED'', getDolGlobalString(''MAIN_MENU_STANDARD'', ''eldy_menu.php''));", "if (getDolGlobalString(''MAIN_MENU_STANDARD'') == ''auguria_menu'' || getDolGlobalString(''MAIN_MENU_SMARTPHONE'') == ''auguria_menu''"]', 'high', NULL);
