INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MESSAGE_INSTALL_MODULES_DISABLED_CONTACT_US', 'bool', NULL, 'website', 'Stores a language key displayed as a warning message when module installation or certain website/modulebuilder actions are disabled.', 'Checked in admin/modules.php:1510–1513 where its value is used as a translation key for an info_admin warning; also checked in website/index.php:616, 2756, 4671, modulebuilder/index.php:3259, and core/lib/website2.lib.php:1097 to gate restricted actions.', 'When set with a non-numeric translation key, a warning message is shown to administrators and certain module/website install actions are blocked.', 'Empty/unset = no restriction; a translation key string = warning displayed and actions disabled; a numeric value = numeric check applies.', 0, 0, 'admin/modules.php|admin/modules.php|admin/modules.php', 1, 'aed3e185a2d6a81f0b62b61d3ffd81dd821970d9e3748efca6c99f3db5f4a4c7', 'v2', '2026-04-21T11:16:15+00:00', '["admin/modules.php:1510|check|if (getDolGlobalString(''MAIN_MESSAGE_INSTALL_MODULES_DISABLED_CONTACT_US'')) {", "admin/modules.php:1512|check|if (!is_numeric(getDolGlobalString(''MAIN_MESSAGE_INSTALL_MODULES_DISABLED_CONTACT_US''))) {", "admin/modules.php:1513|read|$message = info_admin($langs->trans(getDolGlobalString(''MAIN_MESSAGE_INSTALL_MODULES_DISABLED_CONTACT_US'')), 0, 0, ''warning'');", "website/index.php:616|check|if (getDolGlobalString(''MAIN_MESSAGE_INSTALL_MODULES_DISABLED_CONTACT_US'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO', 'string', NULL, 'admin', 'Dynamic-suffix constant family (MAIN_METEO[_PERCENTAGE]_LEVEL0-3) storing the numeric thresholds used by the dashboard ''weather'' (meteo) indicator.', 'Written from admin/delais.php:213 inside a loop ''for ($i = 0; $i < 4; $i++)'' saving MAIN_METEO(_PERCENTAGE)_LEVEL0..3 from GETPOSTINT(), alongside related MAIN_DISABLE_METEO and MAIN_USE_METEO_WITH_PERCENTAGE toggles that select whether the ''_PERCENTAGE'' suffix variant is used. The plain ''MAIN_METEO'' name does not appear standalone in the code; it is a stem for these dynamic level constants.', 'Changing the level thresholds changes when the dashboard ''weather'' icon switches between its severity levels (e.g. based on counts or percentages of a KPI); MAIN_USE_METEO_WITH_PERCENTAGE controls whether percentage-based levels are used instead of absolute counts.', 'Integer threshold values (GETPOSTINT), 4 levels (index 0-3) per mode (count-based or percentage-based).', 0, 0, 'admin/delais.php', 1, 'f15de72036b158204402835270f5d93493d72125e72777a2d04d2c593ee0ea04', 'v2', '2026-07-24T07:05:23+00:00', '["admin/delais.php:213|write|dolibarr_set_const($db, ''MAIN_METEO''.$plus.''_LEVEL''.$i, GETPOSTINT(''MAIN_METEO''.$plus.''_LEVEL''.$i), ''chaine'', 0, '''', $conf->entity);", "admin/delais.php:207: dolibarr_set_const($db, \"MAIN_USE_METEO_WITH_PERCENTAGE\", GETPOST(\"MAIN_USE_METEO_WITH_PERCENTAGE\"), ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO_LEVEL0', 'string', NULL, 'admin', 'Specifies a custom label or value for the level-0 (lowest) threshold in the dashboard weather/meteo indicator.', 'Read in admin/delais.php lines 343-344: when non-empty the value overrides the default level-0 label ($level0) used in the meteo delay indicator display.', 'Changing this value alters the label shown for the best-performance band in the meteo dashboard widget.', 'Any non-empty string label for the level-0 threshold.', 0, 0, 'admin/delais.php|admin/delais.php', 1, 'ed394c585f7fbb42892cec98ef6b02cca75b33baa30366bd485d64df2b1a38c7', 'v2', '2026-04-21T13:50:40+00:00', '["admin/delais.php:343|check|if (getDolGlobalString(''MAIN_METEO_LEVEL0'')) {", "admin/delais.php:344|read|$level0 = getDolGlobalString(''MAIN_METEO_LEVEL0'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO_LEVEL1', 'string', NULL, 'admin', 'Specifies a custom label or value for the level-1 threshold in the dashboard weather/meteo indicator.', 'Read in admin/delais.php lines 347-348: when non-empty the value overrides the default level-1 label ($level1).', 'Changing this value alters the label shown for the level-1 performance band in the meteo dashboard widget.', 'Any non-empty string label for the level-1 threshold.', 0, 0, 'admin/delais.php|admin/delais.php', 1, 'daa085a79adc3c5586c6146a24713cfa39ea83cda9cafeb2d6b959d0f58c01ca', 'v2', '2026-04-21T13:50:40+00:00', '["admin/delais.php:347|check|if (getDolGlobalString(''MAIN_METEO_LEVEL1'')) {", "admin/delais.php:348|read|$level1 = getDolGlobalString(''MAIN_METEO_LEVEL1'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO_LEVEL2', 'string', NULL, 'admin', 'Specifies a custom label or value for the level-2 threshold in the dashboard weather/meteo indicator.', 'Read in admin/delais.php lines 351-352: when non-empty the value overrides the default level-2 label ($level2).', 'Changing this value alters the label shown for the level-2 performance band in the meteo dashboard widget.', 'Any non-empty string label for the level-2 threshold.', 0, 0, 'admin/delais.php|admin/delais.php', 1, '3fcb3e32cf0a1688416db649229e76ba11222128a068c644957c43c3742358fd', 'v2', '2026-04-21T13:50:40+00:00', '["admin/delais.php:351|check|if (getDolGlobalString(''MAIN_METEO_LEVEL2'')) {", "admin/delais.php:352|read|$level2 = getDolGlobalString(''MAIN_METEO_LEVEL2'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO_LEVEL3', 'string', NULL, 'admin', 'Specifies a custom label or value for the level-3 (highest) threshold in the dashboard weather/meteo indicator.', 'Read in admin/delais.php lines 355-356: when non-empty the value overrides the default level-3 label ($level3).', 'Changing this value alters the label shown for the worst-performance band in the meteo dashboard widget.', 'Any non-empty string label for the level-3 threshold.', 0, 0, 'admin/delais.php|admin/delais.php', 1, 'e2d5fd8d041149d9fd2380acb7ef31ce733c9b9a742d8aaf8f46e09a38ecd235', 'v2', '2026-04-21T13:50:40+00:00', '["admin/delais.php:355|check|if (getDolGlobalString(''MAIN_METEO_LEVEL3'')) {", "admin/delais.php:356|read|$level3 = getDolGlobalString(''MAIN_METEO_LEVEL3'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO_PERCENTAGE_LEVEL0', 'string', NULL, 'admin', 'Defines the upper percentage boundary for the level-0 band in the dashboard meteo delay indicator.', 'Displayed as an editable field in admin/delais.php:388 and shown read-only at line 435. The percentage value determines the upper limit of the best-performance band.', 'Changing this value shifts the boundary of the level-0 performance band in the meteo widget.', 'Integer percentage value (e.g. ''20'' means <= 20%).', 0, 0, 'admin/delais.php|admin/delais.php', 1, 'bd86acd907c31de9be6382a50f70c7b3e25ac12901fe229a39b113092293428a', 'v2', '2026-04-21T13:50:40+00:00', '["admin/delais.php:388|read|<input ... name=\"MAIN_METEO_PERCENTAGE_LEVEL0\" value=\"''.getDolGlobalString(...).''\"", "admin/delais.php:435|read|print '' &lt;= '' . getDolGlobalString(''MAIN_METEO_PERCENTAGE_LEVEL0'').''&nbsp;%</td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO_PERCENTAGE_LEVEL1', 'string', NULL, 'admin', 'Defines the upper percentage boundary for the level-1 band in the dashboard meteo delay indicator.', 'Displayed as an editable field in admin/delais.php:391 and shown read-only at line 438.', 'Changing this value shifts the boundary of the level-1 performance band in the meteo widget.', 'Integer percentage value (e.g. ''40'' means <= 40%).', 0, 0, 'admin/delais.php|admin/delais.php', 1, '8ea6ce92b788162159cea604069f5fda0a3ce8441ecfbbd6e5c1227131659353', 'v2', '2026-04-21T13:50:40+00:00', '["admin/delais.php:391|read|<input ... name=\"MAIN_METEO_PERCENTAGE_LEVEL1\" value=\"''.getDolGlobalString(...).''\"", "admin/delais.php:438|read|print '' &lt;= '' . getDolGlobalString(''MAIN_METEO_PERCENTAGE_LEVEL1'').''&nbsp;%</td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO_PERCENTAGE_LEVEL2', 'string', NULL, 'admin', 'Defines the upper percentage boundary for the level-2 band in the dashboard meteo delay indicator.', 'Displayed as an editable field in admin/delais.php:394 and shown read-only at line 441.', 'Changing this value shifts the boundary of the level-2 performance band in the meteo widget.', 'Integer percentage value (e.g. ''60'' means <= 60%).', 0, 0, 'admin/delais.php|admin/delais.php', 1, '2963de215ad5e10baa31ff8f0bb580a598281788afb1cbc9fbb2a4ad616ee813', 'v2', '2026-04-21T13:50:40+00:00', '["admin/delais.php:394|read|<input ... name=\"MAIN_METEO_PERCENTAGE_LEVEL2\" value=\"''.getDolGlobalString(...).''\"", "admin/delais.php:441|read|print '' &lt;= '' . getDolGlobalString(''MAIN_METEO_PERCENTAGE_LEVEL2'').''&nbsp;%</td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_METEO_PERCENTAGE_LEVEL3', 'string', NULL, 'admin', 'Defines the upper percentage boundary for the level-3 band in the dashboard meteo delay indicator; values above this fall into the worst band.', 'Displayed as an editable field in admin/delais.php:397, shown read-only at line 444, and used as the lower bound of the worst band at line 447.', 'Changing this value shifts the boundaries of both the level-3 and the worst-performance band in the meteo widget.', 'Integer percentage value (e.g. ''80'' means <= 80% for level-3; > 80% is the worst band).', 0, 0, 'admin/delais.php|admin/delais.php|admin/delais.php', 1, '075bbe2583e38df6d33d95aededb5c56d569ebd36aef06fff8d15420e8d1edc4', 'v2', '2026-04-21T13:50:40+00:00', '["admin/delais.php:397|read|<input ... name=\"MAIN_METEO_PERCENTAGE_LEVEL3\" value=\"''.getDolGlobalString(...).''\"", "admin/delais.php:444|read|print '' &lt;= '' . getDolGlobalString(''MAIN_METEO_PERCENTAGE_LEVEL3'').''&nbsp;%</td>'';", "admin/delais.php:447|read|print '' &gt; '' . getDolGlobalString(''MAIN_METEO_PERCENTAGE_LEVEL3'').''&nbsp;%</td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING', 'bool', NULL, 'core', 'Sets the minimum number of non-auto-enabled modules that must be active before setup-warning messages are suppressed.', 'Read via getDolGlobalInt with a default of 1 across admin/modules.php:727, admin/index.php:153, core/lib/admin.lib.php:780, imports/import.php:370, exports/export.php:488, categories/index.php:121, core/redirect_if_setup_not_complete.inc.php:45, and core/menus/standard/eldy.lib.php:1185. The inline comment on each occurrence reads ''If only minimal initial modules enabled''.', 'If the count of non-auto-enabled active modules falls below this threshold, setup-incomplete warnings are shown to admin users. Increasing the value raises the threshold, causing warnings to appear more often.', 'Integer; default is 1. Setting to 0 suppresses all such warnings regardless of active modules.', 0, 0, 'admin/modules.php|admin/index.php', 1, 'f76f2fbdd496e46331b928fed471587a8d28284a238a30518126776698556c87', 'v2', '2026-04-21T11:16:15+00:00', '["admin/modules.php:727|check|if (getDolGlobalInt(''MAIN_SETUP_MODULES_DESC'') || $nbmodulesnotautoenabled < getDolGlobalInt(''MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING'', 1)) {\t// If only minimal initial modules enab", "admin/index.php:153|check|if ($nbmodulesnotautoenabled < getDolGlobalInt(''MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING'', 1)) {\t// If only minimal initial modules enabled", "core/redirect_if_setup_not_complete.inc.php:45|check|if ($nbmodulesnotautoenabled < getDolGlobalInt(''MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING'', 1)) {", "core/menus/standard/eldy.lib.php:1185|check|if ($nbmodulesnotautoenabled < getDolGlobalInt(''MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING'', 1)) {\t// If only minimal initial modules enabled)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULES_FOR_EXTERNAL', 'string', NULL, 'product', 'Comma-separated list of module names enabled for external (portal) users.', 'The value is split by comma and used throughout the codebase to filter which modules are accessible to external users, appearing in security checks (core/lib/security.lib.php:603), menu generation (core/menus/standard/auguria.lib.php:52), and numerous dashboard boxes. Over 53 occurrences across multiple files.', 'Modules not listed here are hidden or restricted for external users. Adding or removing a module name from this list grants or revokes external user access to that module''s features.', 'Comma-separated module names (e.g. ''invoice,order,product''); empty = no modules enabled for external users', 1, 0, NULL, 1, 'f1de82e3d34ba4de111adeeb42e81e775a8dba5f22b07c790ff234d223f9a7c1', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/security.lib.php:603|read|$listofmodules = explode('','', getDolGlobalString(''MAIN_MODULES_FOR_EXTERNAL''));", "core/boxes/box_comptes.php:57|read|$listofmodulesforexternal = explode('','', getDolGlobalString(''MAIN_MODULES_FOR_EXTERNAL''));", "core/menus/standard/auguria.lib.php:52|read|$listofmodulesforexternal = explode('','', getDolGlobalString(''MAIN_MODULES_FOR_EXTERNAL''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULES_SHOW_LINENUMBERS', 'bool', NULL, 'admin', 'Adds a line-number column to the modules list table on the admin Modules setup page.', 'Checked in admin/modules.php:1278 in the per-module table row rendering; when true, a extra `<td>` with $linenum is printed before the module picto/name cell.', 'Enabling it only changes the visual layout of the module list by adding a numbering column; no other behavior is affected.', 'Boolean-like: any truthy value shows line numbers in the modules list.', 0, 0, 'admin/modules.php', 1, '0ea4c19cb08db355a961e9252c42196ddc8bcb9d96dbb9774b5abcf38bfcfabe', 'v2', '2026-07-24T07:05:23+00:00', '["admin/modules.php:1278: if (getDolGlobalString(''MAIN_MODULES_SHOW_LINENUMBERS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_', 'string', NULL, 'core', 'A prefix pattern used to check whether a named Dolibarr module is active or to retrieve its associated handler class.', 'Read at api/class/api_setup.class.php:3227 as ''$active = getDolGlobalString(''MAIN_MODULE_''.$moduleName)'' to check module activation status. Also used in core/class/CSMSFile.class.php:183 and core/class/html.formsms.class.php:261 with the pattern ''MAIN_MODULE_''.strtoupper($sendmode).''_SMS'', where the comment states: ''$conf->global->MAIN_MODULE_XXX_SMS looks like a value ''class@module''''.', 'The value for a specific MAIN_MODULE_X constant indicates whether module X is active and/or provides the handler class reference for that module''s functionality.', 'Not set = module not active; non-empty string = module active (for base module flags) or ''class@module'' string (for SMS/handler variants like MAIN_MODULE_XXX_SMS).', 1, 0, NULL, 1, '5ec0ad626ab173dacb07fd51443bfcc3bfb717cea7fe2aa06eab4f6b52d375d0', 'v2', '2026-04-21T11:16:15+00:00', '["api/class/api_setup.class.php:3227|read|$active = getDolGlobalString(''MAIN_MODULE_''.$moduleName);", "core/class/CSMSFile.class.php:183|read|$classmoduleofsender = getDolGlobalString(''MAIN_MODULE_''.strtoupper($sendmode).''_SMS'', $sendmode);\t// $conf->global->MAIN_MODULE_XXX_SMS looks like a value ''class@module''", "core/class/html.formsms.class.php:261|read|$classmoduleofsender = getDolGlobalString(''MAIN_MODULE_''.strtoupper($sendmode).''_SMS'', $sendmode);\t// $conf->global->MAIN_MODULE_XXX_SMS looks like a value ''class@module''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_CAN_OVERWRITE_COMMONICONS', 'string', NULL, 'core', 'Allows the active theme to override Dolibarr''s common (shared) icon images with its own versions.', 'In core/lib/functions.lib.php:6373 (img_picto_common), if getDolGlobalInt() is truthy, the code checks for a file at `theme/<conf->theme>/img/<picto>` and uses it instead of the default `theme/common/<picto>` icon when it exists.', 'Enabling it lets a custom theme silently replace Dolibarr''s generic/common icons by placing same-named PNG/GIF files in the theme''s own img folder.', 'Boolean-like: any truthy value enables theme-level override of common icon files.', 1, 0, NULL, 1, '8da169d7e38349be8bf0c7dcbb857b57c479ce48966113def814bb4331b03059', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:6373|check|if (getDolGlobalInt(''MAIN_MODULE_CAN_OVERWRITE_COMMONICONS'')) {", "$themepath = DOL_DOCUMENT_ROOT . ''/theme/'' . $conf->theme . ''/img/'' . $picto;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_DOLISTORE_API_KEY', 'string', NULL, 'admin', 'Sets the API key used to authenticate requests to the Dolistore API.', 'Read in admin/remotestore/class/externalModules.class.php:153 with a default of ''dolistorepublicapi''.', 'Changing this key authenticates Dolistore API requests under a different account or access level.', 'String, default ''dolistorepublicapi''.', 0, 0, 'admin/remotestore/class/externalModules.class.php', 1, '722055af16c916485abcfb38e63487acd347a32eced7aef1b03d3ea5797d6187', 'v2', '2026-04-21T13:50:40+00:00', '["admin/remotestore/class/externalModules.class.php:153|read|$this->dolistore_api_key = getDolGlobalString(''MAIN_MODULE_DOLISTORE_API_KEY'', ''dolistorepublicapi'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_DOLISTORE_API_SRV', 'string', NULL, 'admin', 'Sets the base URL of the Dolistore API server used to fetch available external modules.', 'Read in admin/remotestore/class/externalModules.class.php:152 with a default of ''https://www.dolistore.com/api/''; an inline comment lists alternative values including ''https://admin2.dolibarr.org/''.', 'Changing this URL redirects all Dolistore API requests to a different server, such as a staging or alternative store endpoint.', 'String URL, default ''https://www.dolistore.com/api/''.', 0, 0, 'admin/remotestore/class/externalModules.class.php', 1, 'f6ddc162e736d439d3898dac3fb9da3a6f962c020507703351005b177c8d9435', 'v2', '2026-04-21T13:50:40+00:00', '["admin/remotestore/class/externalModules.class.php:152|read|$this->dolistore_api_url = getDolGlobalString(''MAIN_MODULE_DOLISTORE_API_SRV'', ''https://www.dolistore.com/api/'');\t// ''https://www.dolistore.com/api/'', ''https://admin2.dolibarr.org/"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_DOLISTORE_BASIC_LOGIN', 'string', NULL, 'admin', 'Stores the HTTP Basic Authentication login used to access the Dolistore API.', 'Read in both admin/modules.php:1369 and admin/remotestore/class/externalModules.class.php:210 to build authenticated requests to the Dolistore remote store.', 'Setting this value enables authenticated access to Dolistore, which is required when the store enforces HTTP Basic Auth. Leaving it empty results in unauthenticated requests.', 'A username string for HTTP Basic Auth against the Dolistore API; empty = no Basic Auth login sent', 0, 0, 'admin/modules.php|admin/remotestore/class/externalModules.class.php', 1, 'bfdcce5a0ddf0382ef6310d7a4bc7d8c94edc8de1c9e5cf7539fa151f526d00d', 'v2', '2026-04-21T13:29:58+00:00', '["admin/modules.php:1369|read|$basicAuthLogin = getDolGlobalString(''MAIN_MODULE_DOLISTORE_BASIC_LOGIN'');", "admin/remotestore/class/externalModules.class.php:210|read|$basicAuthLogin = getDolGlobalString(''MAIN_MODULE_DOLISTORE_BASIC_LOGIN'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_DOLISTORE_BASIC_PASSWORD', 'string', NULL, 'admin', 'Stores the HTTP Basic Authentication password used to access the Dolistore API.', 'Read in both admin/modules.php:1370 and admin/remotestore/class/externalModules.class.php:211 alongside MAIN_MODULE_DOLISTORE_BASIC_LOGIN to authenticate requests to the Dolistore remote store.', 'Setting this value provides the password for authenticated Dolistore API access. It should be treated as a sensitive credential.', 'A password string for HTTP Basic Auth against the Dolistore API; empty = no Basic Auth password sent', 0, 0, 'admin/modules.php|admin/remotestore/class/externalModules.class.php', 1, '6a7e302d4926741d28f50888d0304b6310e6232a14f856677ec10f11084fb8b4', 'v2', '2026-04-21T13:29:58+00:00', '["admin/modules.php:1370|read|$basicAuthPassword = getDolGlobalString(''MAIN_MODULE_DOLISTORE_BASIC_PASSWORD'');", "admin/remotestore/class/externalModules.class.php:211|read|$basicAuthPassword = getDolGlobalString(''MAIN_MODULE_DOLISTORE_BASIC_PASSWORD'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_DOLISTORE_SHOP_URL', 'string', NULL, 'admin', 'Sets the base URL of the Dolistore shop used for module browsing links.', 'Read in admin/remotestore/class/externalModules.class.php:154 with a default of ''https://www.dolistore.com''.', 'Changing this URL redirects shop-browsing links to a different store endpoint.', 'String URL, default ''https://www.dolistore.com''.', 0, 0, 'admin/remotestore/class/externalModules.class.php', 1, '313645d48ddcf7be216fb280a0c0cc6d1c00f5562d25c5df896bf30aed44db2d', 'v2', '2026-04-21T13:50:40+00:00', '["admin/remotestore/class/externalModules.class.php:154|read|$this->shop_url  = getDolGlobalString(''MAIN_MODULE_DOLISTORE_SHOP_URL'', ''https://www.dolistore.com'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_MULTICOMPANY', 'string', NULL, 'core', 'Indicates whether the MultiCompany module is enabled.', 'Checked in core/modules/DolibarrModules.class.php:2346, main.inc.php:2517, and user/class/user.class.php:3167 to gate multi-entity logic.', 'When set, multi-company/entity features are activated across the application; unsetting it disables those code paths.', ''''' or unset = MultiCompany module disabled; any truthy value = MultiCompany module enabled', 1, 0, NULL, 1, 'b1b24fee94179fa1909143cfed4dafa677c108c27c2a63e54572fe451d7dfda4', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/DolibarrModules.class.php:2346|check|if (!getDolGlobalString(''MAIN_MODULE_MULTICOMPANY'') || $conf->entity == 1) {", "main.inc.php:2517|check|if (getDolGlobalString(''MAIN_MODULE_MULTICOMPANY'')) {", "user/class/user.class.php:3167|check|if (getDolGlobalString(''MAIN_MODULE_MULTICOMPANY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_PRELEVEMENT_CONCAT', 'string', NULL, 'compta', 'Legacy/dead flag intended to aggregate direct-debit lines when adding a payment line, but the source comments it out as unused and deprecated.', 'Read in BonPrelevement::addline(), compta/prelevement/class/bonprelevement.class.php:427, immediately followed by a developer comment questioning its purpose; the ''$concat==1'' branch is itself marked @deprecated and ''Not used. To remove.''', 'Setting it to 1 would trigger a code branch explicitly documented as broken/non-functional (''This code can''t work because code_... fields are empty'').', 'Int: 1 triggers the deprecated/non-functional aggregation branch; comment states ''Seems not used''.', 1, 0, NULL, 1, 'a0ba70d601d61f16db2c961408fb98b976f0666eab634625f0f2e6aba512d532', 'v2', '2026-07-24T07:05:23+00:00', '["compta/prelevement/class/bonprelevement.class.php:427|read|$concat = getDolGlobalInt(''MAIN_MODULE_PRELEVEMENT_CONCAT'');\t// ??? what is this for. Seems not used.", "compta/prelevement/class/bonprelevement.class.php:429-432|read|@deprecated. This code can''t work because code_... fields are empty. Not used. To remove."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_SETUP_ON_LIST_BY_DEFAULT', 'string', NULL, 'admin', 'Sets the default display mode of the modules list page (e.g. kanban or list view).', 'Written by admin/modules.php:194 when switching views. Read in both admin/modules.php:197 and core/lib/admin.lib.php:778 with a fallback of ''commonkanban''. The value drives the initial rendering mode of the module management UI.', 'Changing this value alters which view mode is shown by default when opening the modules list. The effect is immediate on the next page load.', 'String view mode identifier; ''commonkanban'' = kanban view (default); ''common'' = list view', 0, 0, 'admin/modules.php|admin/modules.php|admin/modules.php', 1, '1d6759ff7a248f095625d5d043eaf0400b513cbd9980a41217faa4df53829be2', 'v2', '2026-04-21T13:29:58+00:00', '["admin/modules.php:197|read|$mode = getDolGlobalString(''MAIN_MODULE_SETUP_ON_LIST_BY_DEFAULT'', ''commonkanban'');", "core/lib/admin.lib.php:778|read|$mode = getDolGlobalString(''MAIN_MODULE_SETUP_ON_LIST_BY_DEFAULT'', ''commonkanban'');", "admin/modules.php:193|check|if ($mode == ''common'' && !getDolGlobalString(''MAIN_MODULE_SETUP_ON_LIST_BY_DEFAULT'')) {", "admin/modules.php:194|write|dolibarr_set_const($db, \"MAIN_MODULE_SETUP_ON_LIST_BY_DEFAULT\", $mode, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_WEBSERVICES', 'string', NULL, 'webservices', 'Guards access to all legacy SOAP webservice endpoints; each server script rejects requests when this constant is not set.', 'Checked at entry of every webservice script including webservices/server_other.php:64, server_invoice.php:67, server_contact.php:62, server_supplier_invoice.php:63, server_project.php:66, server_order.php:65, server_user.php:65, and webservices/index.php:49.', 'Without this constant set, all SOAP webservice endpoints return an error and deny access; setting it enables the webservices module.', 'Non-empty = webservices enabled; empty/absent = webservices blocked', 1, 0, NULL, 1, '0a76577c0e598e76da48b46490e5e8d5255a8ef9c2e5fb58cb0587c05d7d092b', 'v2', '2026-04-21T11:16:15+00:00', '["webservices/server_other.php:64|check|if (!getDolGlobalString(''MAIN_MODULE_WEBSERVICES'')) {", "webservices/server_invoice.php:67|check|if (!getDolGlobalString(''MAIN_MODULE_WEBSERVICES'')) {", "webservices/server_contact.php:62|check|if (!getDolGlobalString(''MAIN_MODULE_WEBSERVICES'')) {", "webservices/index.php:49|check|if (!getDolGlobalString(''MAIN_MODULE_WEBSERVICES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MODULE_XXX_SMS', 'string', NULL, 'core', 'Stores the class@module identifier for the SMS sending provider module, where XXX is the uppercased send mode name.', 'Read in core/class/CSMSFile.class.php:183 and core/class/html.formsms.class.php:261 via getDolGlobalString. The constant name is built dynamically from the send mode. A code comment explains the expected value format.', 'Changing this constant redirects SMS sending to a different provider class and module.', 'A string in the format ''class@module'', e.g. ''MySmsSender@mymodule''.', 1, 0, NULL, 1, '0b36454f958faaa5d2733d79742ff5e69112a71e71b3cb778a26058970dfe856', 'v2', '2026-04-21T13:50:40+00:00', '["$classmoduleofsender = getDolGlobalString(''MAIN_MODULE_''.strtoupper($sendmode).''_SMS'', $sendmode);\t// $conf->global->MAIN_MODULE_XXX_SMS looks like a value ''class@module''", "$classmoduleofsender = getDolGlobalString(''MAIN_MODULE_''.strtoupper($sendmode).''_SMS'', $sendmode);\t// $conf->global->MAIN_MODULE_XXX_SMS looks like a value ''class@module''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MONNAIE', 'string', 'EUR', 'societe', 'Stores the default currency code used by the company.', 'Written in admin/company.php at line 127 via the company admin UI. Read in societe/class/societe.class.php at line 4797 and in intracommreport/class/intracommreport.class.php at line 333 for intracomm declarations.', 'Changing this constant updates the currency code applied to the company''s financial documents and intracomm reports.', 'ISO 4217 currency code string (default: ''EUR'')', 0, 0, 'admin/company.php', 1, 'dfaf4055005425f64a73a1f7e299abcb56651b018b2175dc7356906bc3becba3', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:127|write|dolibarr_set_const($db, \"MAIN_MONNAIE\", GETPOST(\"currency\", ''aZ09''), ''chaine'', 0, '''', $conf->entity);", "intracommreport/class/intracommreport.class.php:333|read|$declaration->addChild(''currencyCode'', $conf->global->MAIN_MONNAIE);", "societe/class/societe.class.php:4797|read|$this->currency_code = getDolGlobalString(''MAIN_MONNAIE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MOTD', 'string', NULL, 'admin', 'Holds the HTML ''message of the day'' text displayed on the Dolibarr login/home page.', 'Set via admin/ihm.php:263 with dolibarr_set_const, edited with a DolEditor in admin/ihm.php:581, and displayed in index.php:100/101 via getDolGlobalString(''MAIN_MOTD'').', 'If non-empty, the text is HTML-cleaned and displayed (with <br> normalization) at the top of the home page.', NULL, 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '988e5baf4cc737e3d830e4f1236956600276707cd322777026ebd6693c4630ef', 'v2', '2026-07-24T06:41:12+00:00', '["admin/ihm.php:263|write|dolibarr_set_const($db, \"MAIN_MOTD\", dol_htmlcleanlastbr(GETPOST(\"main_motd\", ''restricthtml'')), ''chaine'', 0, '''', $conf->entity);", "index.php:100|check|if (getDolGlobalString(''MAIN_MOTD'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MOTD_SETUPPAGE', 'string', NULL, 'admin', 'Defines a message-of-the-day (MOTD) text displayed on the Dolibarr admin setup/home page.', 'Read and processed in admin/index.php:61-77; HTML br tags are normalized and translation placeholders of the form __(...) __ are replaced with translated strings before display. Configurable via admin/index.php.', 'Setting this string displays a custom message on the admin home page. The message supports HTML br tags and Dolibarr translation key placeholders.', 'Empty = no MOTD displayed; any string = HTML content shown on the admin setup page (supports __( translationkey )__ placeholders)', 0, 0, 'admin/index.php|admin/index.php|admin/index.php|admin/index.php|admin/index.php|admin/index.php|admin/index.php|admin/index.php', 1, 'a7a48595cc576531d40b043addc12faab528b30d39835d650876581669ae0b7f', 'v2', '2026-04-21T13:50:40+00:00', '["admin/index.php:62|write|$conf->global->MAIN_MOTD_SETUPPAGE = preg_replace(''/<br(\\s[\\sa-zA-Z_=\"]*)?\\/?>/i'', ''<br>'', getDolGlobalString(''MAIN_MOTD_SETUPPAGE''));", "admin/index.php:66|read|while (preg_match(''/__\\(([a-zA-Z|@]+)\\)__/i'', getDolGlobalString(''MAIN_MOTD_SETUPPAGE''), $reg) && $i < 100) {", "admin/index.php:77|read|print dol_htmlentitiesbr(getDolGlobalString(''MAIN_MOTD_SETUPPAGE''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MULTILANGS', 'string', NULL, 'core', 'Enables the multi-language feature, allowing product/document/email content to be translated into multiple languages.', 'Configured in the admin UI (product/admin/product.php:778, admin/mails_templates.php multiple lines) and checked with getDolGlobalInt(''MAIN_MULTILANGS'') across 399 occurrences (e.g. product/ajax/products.php:123/134, fourn/class/paiementfourn.class.php:422).', 'Enabling it turns on language-selection options and multilingual text fields (e.g. for products and email templates) throughout the application.', NULL, 0, 0, 'product/admin/product.php|admin/mails_templates.php|admin/mails_templates.php|admin/mails_templates.php', 1, '4928b72d7a6fbd3cb435af83a3d0b507e9ad512606d32d4b2d7ce28578aae3ac', 'v2', '2026-07-24T06:41:12+00:00', '["product/admin/product.php:778|check|if (getDolGlobalInt(''MAIN_MULTILANGS'')) {", "core/class/html.formfile.class.php:403|* @param integer $forcenomultilang Do not show language option (even if MAIN_MULTILANGS defined)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MULTILANGS_ASK_LANG_IN_SEPARATE_COMBO', 'string', NULL, 'core', 'Hidden option that adds a separate language-selection combo box next to the email-template selector, instead of relying on per-template flag icons, when multilang is enabled.', 'Checked in core/class/html.formmail.class.php:641, nested inside a MAIN_MULTILANGS check; comment above (lines 637-639) explains this conflicts with the existing flag-icon template selection and is ''currently enable[d] ... on a hidden constant'' pending a better UX solution.', 'When enabled (and MAIN_MULTILANGS is on), an additional language dropdown (FormAdmin::select_language) is shown next to the model-mail selector so the user can pick the template language explicitly; this duplicates/conflicts with the existing per-template language-flag selection per the code comment.', 'Boolean-like: truthy shows the extra language combo; documented in code as a hidden/experimental constant.', 1, 0, NULL, 1, 'a16b9b2561d1f87f75b6b4c1437da237a74003c30343b1597305f475dc78b859', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:637-639: comment ''This feature is in conflict with the existing one ... currently enable this on a hidden constant''", "core/class/html.formmail.class.php:641: if (getDolGlobalInt(''MAIN_MULTILANGS_ASK_LANG_IN_SEPARATE_COMBO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MULTILANG_TRANSLATE_EVEN_IF_MODIFIED', 'string', NULL, 'core', 'Forces translation of product/service label, description and note on PDF documents even if the line text was manually modified from the product''s default.', 'Read in core/lib/pdf.lib.php:1977 inside the multilang block; by default (unset), if the label/description/note text differs from the product''s own field, translation is skipped and the modified text is kept as-is.', 'When set, manually edited line label/description/note text is replaced by the product''s translation for the output language, potentially discarding the user''s manual edits.', 'Boolean-like (set/unset); comment: ''By default if value was modified manually, we keep it (no translation because we don''t have it)''', 1, 0, NULL, 1, '3dcc8439bde339899b1c6e4097c77d08ac2335c8e3cff985ec6d4a74f954c059', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1977|read|$translatealsoifmodified = getDolGlobalString(''MAIN_MULTILANG_TRANSLATE_EVEN_IF_MODIFIED''); // By default if value was modified manually, we keep it (no translation because we don''t have it)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MYMODULE_SHOW_PAGE_OF_AGENDA', 'bool', NULL, 'modulebuilder', 'ModuleBuilder template placeholder flag controlling whether the generated custom object''s tab bar shows an Agenda/Events tab.', 'Read in modulebuilder/template/lib/mymodule_myobject.lib.php:47 inside myobjectPrepareHead(): `$showtabofpageagenda = getDolGlobalInt(''MAIN_MYMODULE_SHOW_PAGE_OF_AGENDA'');`, marked with ''BEGIN/END MODULEBUILDER TABFLAG AGENDA'' scaffold comments.', 'Only relevant in module-builder-generated boilerplate for the placeholder ''MyModule''/''MyObject''; toggles visibility of the Agenda tab on the object''s card until renamed by the developer.', 'Boolean-like integer (0/1) controlling tab visibility.', 1, 0, NULL, 1, '1d7d7992f39aa10fc740d6703cb76aca5723feb510b69152402c49d218c32d3a', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/template/lib/mymodule_myobject.lib.php:47|read|$showtabofpageagenda = getDolGlobalInt(''MAIN_MYMODULE_SHOW_PAGE_OF_AGENDA'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MYMODULE_SHOW_PAGE_OF_CONTACT', 'bool', NULL, 'modulebuilder', 'ModuleBuilder template placeholder flag controlling whether the generated custom object''s tab bar shows a Contacts tab.', 'Read in modulebuilder/template/lib/mymodule_myobject.lib.php:38 inside myobjectPrepareHead(): `$showtabofpagecontact = getDolGlobalInt(''MAIN_MYMODULE_SHOW_PAGE_OF_CONTACT'');`, marked with ''BEGIN/END MODULEBUILDER TABFLAG CONTACT'' scaffold comments.', 'Only relevant in module-builder-generated boilerplate for the placeholder ''MyModule''/''MyObject''; the real constant name is renamed by developers when they generate their own module, and the value toggles visibility of the Contacts tab on the object''s card.', 'Boolean-like integer (0/1) controlling tab visibility.', 1, 0, NULL, 1, 'f0c52612d5d9d897c0c743d679fc09b5f71a16b77ee083f4b4139836ee338440', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/template/lib/mymodule_myobject.lib.php:38|read|$showtabofpagecontact = getDolGlobalInt(''MAIN_MYMODULE_SHOW_PAGE_OF_CONTACT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MYMODULE_SHOW_PAGE_OF_DOCUMENT', 'bool', NULL, 'modulebuilder', 'ModuleBuilder template placeholder flag controlling whether the generated custom object''s tab bar shows a Documents tab.', 'Read in modulebuilder/template/lib/mymodule_myobject.lib.php:44 inside myobjectPrepareHead(): `$showtabofpagedocument = getDolGlobalInt(''MAIN_MYMODULE_SHOW_PAGE_OF_DOCUMENT'');`, marked with ''BEGIN/END MODULEBUILDER TABFLAG DOCUMENT'' scaffold comments.', 'Only relevant in module-builder-generated boilerplate for the placeholder ''MyModule''/''MyObject''; toggles visibility of the Documents tab on the object''s card until renamed by the developer.', 'Boolean-like integer (0/1) controlling tab visibility.', 1, 0, NULL, 1, '85eab52d71b1c025853b0c5334855bdf424c2cef3729c6632df456cd192ef197', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/template/lib/mymodule_myobject.lib.php:44|read|$showtabofpagedocument = getDolGlobalInt(''MAIN_MYMODULE_SHOW_PAGE_OF_DOCUMENT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_MYMODULE_SHOW_PAGE_OF_NOTE', 'bool', NULL, 'modulebuilder', 'ModuleBuilder template placeholder flag controlling whether the generated custom object''s tab bar shows a Notes tab.', 'Read in modulebuilder/template/lib/mymodule_myobject.lib.php:41 inside myobjectPrepareHead(): `$showtabofpagenote = getDolGlobalInt(''MAIN_MYMODULE_SHOW_PAGE_OF_NOTE'');`, marked with ''BEGIN/END MODULEBUILDER TABFLAG NOTE'' scaffold comments.', 'Only relevant in module-builder-generated boilerplate for the placeholder ''MyModule''/''MyObject''; toggles visibility of the Notes tab on the object''s card until renamed by the developer.', 'Boolean-like integer (0/1) controlling tab visibility.', 1, 0, NULL, 1, 'a5ca0a294e4bfd5953b2e0af453b00806b7ce5a4f74622cec19005f09fa7478c', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/template/lib/mymodule_myobject.lib.php:41|read|$showtabofpagenote = getDolGlobalInt(''MAIN_MYMODULE_SHOW_PAGE_OF_NOTE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NB_OF_YEAR_IN_MEMBERSHIP_WIDGET_GRAPH', 'string', NULL, 'core', 'Sets the number of years of data displayed in membership dashboard widgets and graphs.', 'Read as an integer at adherents/index.php:105, core/boxes/box_members_by_type.php:84, and core/boxes/box_members_by_tags.php:83. The value is passed to $numberyears for limiting the year range in membership charts. No admin UI is provided.', 'Changing this value increases or decreases the number of years shown in membership statistic widgets on the dashboard.', 'A positive integer representing the number of years to display; 0 or unset = no years shown (default behavior depends on widget code).', 1, 0, NULL, 1, 'b3dd2408e5c6aa105c2386979964bc1192ca0516cf013a8a66c9b3a4cea220b3', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/index.php:105|read|$numberyears = getDolGlobalInt(\"MAIN_NB_OF_YEAR_IN_MEMBERSHIP_WIDGET_GRAPH\");", "core/boxes/box_members_by_type.php:84|read|$numberyears = getDolGlobalInt(\"MAIN_NB_OF_YEAR_IN_MEMBERSHIP_WIDGET_GRAPH\");", "core/boxes/box_members_by_tags.php:83|read|$numberyears = getDolGlobalInt(\"MAIN_NB_OF_YEAR_IN_MEMBERSHIP_WIDGET_GRAPH\", 0);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NB_OF_YEAR_IN_WIDGET_GRAPH', 'string', NULL, 'core', 'Sets the number of years displayed in dashboard graph widgets.', 'Read as an integer with default fallbacks in six graph box files. Default is 3 years for per-month graphs (e.g. box_graph_orders_permonth.php:130, box_graph_invoices_permonth.php:128 with inline comment ''// Default is 3 years'') and 5 years for the per-year invoice graph (box_graph_invoices_peryear.php:121).', 'Increasing this value extends the historical range shown in dashboard graphs; decreasing it narrows the view to more recent years.', 'Integer; default 3 for per-month graphs, default 5 for per-year invoice graph when not set', 1, 0, NULL, 1, 'eeefc6c734310ff7bd4fa16d1a640d7a4b094ec2b663ef24189ce3380155fb53', 'v2', '2026-04-21T11:16:15+00:00', '["core/boxes/box_graph_orders_permonth.php:130|read|$startyear = $endyear - getDolGlobalInt(''MAIN_NB_OF_YEAR_IN_WIDGET_GRAPH'', 3) + 1;", "core/boxes/box_graph_invoices_peryear.php:121|read|$numberyears = getDolGlobalInt(''MAIN_NB_OF_YEAR_IN_WIDGET_GRAPH'', 5);", "core/boxes/box_graph_invoices_permonth.php:128|read|$startyear = $endyear - getDolGlobalInt(''MAIN_NB_OF_YEAR_IN_WIDGET_GRAPH'', 3) + 1;\t// Default is 3 years", "core/boxes/box_graph_invoices_supplier_permonth.php:128|read|$startyear = $endyear - getDolGlobalInt(''MAIN_NB_OF_YEAR_IN_WIDGET_GRAPH'', 3) + 1;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NEED_EXPORT_PERMISSION_TO_READ_STATISTICS', 'string', NULL, 'core', 'Requires the export permission before a user can view statistics pages.', 'Checked with getDolGlobalInt(''MAIN_NEED_EXPORT_PERMISSION_TO_READ_STATISTICS'') in core/menus/standard/eldy.lib.php:1446/1498, contrat/stats/index.php:58, commande/stats/index.php:57, and modulebuilder/template/stats/myobject_index.php:96.', 'When enabled, access to statistics/index pages is gated on the export permission rather than being open by default.', NULL, 0, 0, NULL, 1, '7289cc6f87d35dbf521928de7e008ee0b616f8e9425676d9ecfbecf955834db4', 'v2', '2026-07-24T06:41:12+00:00', '["core/menus/standard/eldy.lib.php:1446|check|if (getDolGlobalInt(''MAIN_NEED_EXPORT_PERMISSION_TO_READ_STATISTICS'')) {", "contrat/stats/index.php:58|check|if (getDolGlobalInt(''MAIN_NEED_EXPORT_PERMISSION_TO_READ_STATISTICS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NGINX_FIX', 'string', NULL, 'api', 'Works around some NGINX reverse-proxy setups where PHP''s PHP_SELF/PATH_INFO server variables are not populated correctly for the REST API entry point, by using $_SERVER[''SCRIPT_URI''] instead.', 'In api/index.php:140, a code comment (line 139) states ''Fix for some NGINX setups (this should not be required even with NGINX, however setup of NGINX are often mysterious and this may help in such cases)''; when set, $url is overridden to $_SERVER[''SCRIPT_URI''] if available, else falls back to PHP_SELF.', 'When set on servers where the API routing URL is misdetected under NGINX, this restores correct URL/method resolution for API calls; on servers where it isn''t needed it changes the source of the $url variable used for API route matching, which could break routing if SCRIPT_URI is populated with an unexpected value.', 'Not set/falsy (default): $url built from PHP_SELF/PATH_INFO/ORIG_PATH_INFO as usual. Truthy: $url forced to $_SERVER[''SCRIPT_URI''] (or PHP_SELF if SCRIPT_URI absent).', 1, 0, NULL, 1, '314caf5ea14c41ad596f51db0bc6e3c22ef2c7315804cd9dbff75ba31bd3d184', 'v2', '2026-07-24T07:05:23+00:00', '["api/index.php:139|comment|// Fix for some NGINX setups (this should not be required even with NGINX, however setup of NGINX are often mysterious and this may help is such cases)", "api/index.php:140-141|check|if (getDolGlobalString(''MAIN_NGINX_FIX'')) { $url = (isset($_SERVER[''SCRIPT_URI'']) && $_SERVER[\"SCRIPT_URI\"] !== null) ? $_SERVER[\"SCRIPT_URI\"] : $_SERVER[''PHP_SELF'']; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NON_WORKING_DAYS_INCLUDE_FRIDAY', 'string', NULL, 'core', 'Includes Friday as a non-working day in working-day calculations.', 'Read as an integer in core/lib/date.lib.php at lines 788 and 1051 to determine whether Friday should be excluded from working-day counts. Also controls display in admin/holiday.php:516.', 'Enabling this constant causes Friday to be treated as a weekend/holiday day in all deadline and working-day calculations, which is relevant for regions with a Friday–Saturday weekend.', '0 or unset = Friday is a working day; non-zero = Friday is excluded from working days.', 0, 0, 'admin/holiday.php', 1, 'f7d3e430eac9499d2544c9cc8f0ab302ed04729fc33e7310b16ec350e6705f53', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/date.lib.php:788|read|$includefriday = getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_FRIDAY'', 0);", "core/lib/date.lib.php:1051|read|$excludefriday = getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_FRIDAY'', 0);", "admin/holiday.php:516|check|if (getDolGlobalString(''MAIN_NON_WORKING_DAYS_INCLUDE_FRIDAY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NON_WORKING_DAYS_INCLUDE_MONDAY', 'string', NULL, 'core', 'Marks Monday as a non-working day for holiday and working-day calculations.', 'Checked by admin/holiday.php:500 to display Monday in the non-working days UI, and by projet/class/project.class.php:2698. Read in core/lib/date.lib.php:785 and :1048 as $includemonday/$excludemonday (both default 0).', 'Enabling this constant excludes Monday from working-day counts in leave and project duration calculations.', 'Non-zero = Monday treated as non-working; 0 or unset = Monday is a working day.', 0, 0, 'admin/holiday.php', 1, '200141ea117c086b1148fb58cdd8094152b26e72f9b638ace95c7f4e26e32ba0', 'v2', '2026-04-21T11:16:15+00:00', '["admin/holiday.php:500|check|if (getDolGlobalString(''MAIN_NON_WORKING_DAYS_INCLUDE_MONDAY'')) {", "core/lib/date.lib.php:785|read|$includemonday = getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_MONDAY'', 0);", "core/lib/date.lib.php:1048|read|$excludemonday = getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_MONDAY'', 0);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NON_WORKING_DAYS_INCLUDE_SATURDAY', 'string', NULL, 'holiday', 'Controls whether Saturday is treated as a non-working day in date/holiday calculations.', 'Configured in admin/holiday.php:532 (admin UI), read with getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_SATURDAY'', 1) in holiday/card.php:1437, holiday/document.php:220, core/lib/date.lib.php:793/1059, and checked in projet/class/project.class.php:2710.', 'When enabled (default 1), Saturdays are excluded/counted as non-working in holiday duration and date range calculations.', NULL, 0, 0, 'admin/holiday.php', 1, '7b6976887862ade8306698bd5d149cd4616c64dea3f45d5baa5b5845b5c7ce5a', 'v2', '2026-07-24T06:41:12+00:00', '["holiday/card.php:1437|read|$includesaturday = getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_SATURDAY'', 1);", "core/lib/date.lib.php:793|read|$includesaturday = getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_SATURDAY'', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NON_WORKING_DAYS_INCLUDE_SUNDAY', 'string', NULL, 'holiday', 'Controls whether Sunday is treated as a non-working day in date/holiday calculations.', 'Configured in admin/holiday.php:548 (admin UI), read with getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_SUNDAY'', 1) in holiday/card.php:1438, holiday/document.php:221, core/lib/date.lib.php:796/1062, and checked in projet/class/project.class.php:2714.', 'When enabled (default 1), Sundays are excluded/counted as non-working in holiday duration and date range calculations.', NULL, 0, 0, 'admin/holiday.php', 1, 'f04ca689f1d0965b8175bb7763662b7f8fb998e72933c2ba1982a38b870e1891', 'v2', '2026-07-24T06:41:12+00:00', '["holiday/card.php:1438|read|$includesunday   = getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_SUNDAY'', 1);", "core/lib/date.lib.php:796|read|$includesunday = getDolGlobalInt(''MAIN_NON_WORKING_DAYS_INCLUDE_SUNDAY'', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NON_WORKING_DAYS_INCLUDE_TUESDAY', 'string', NULL, 'projet', 'Marks Tuesday as a non-working day when computing the weekly working-hours report emailed to project/task users.', 'Checked in projet/class/project.class.php:2706 alongside sibling constants for Monday/Saturday/Sunday: when set, it decrements the computed number of public holidays for the week and increments $weekendEnabled, effectively treating Tuesday as an extra non-working day for that week''s timesheet report.', 'Enabling it changes the expected working-hours baseline used by the automatic weekly time-report email, treating Tuesday as a day off.', 'Boolean; used together with MAIN_NON_WORKING_DAYS_INCLUDE_MONDAY/SATURDAY/SUNDAY.', 1, 0, NULL, 1, 'cca35e1933a2e96604aab3e56334cd375f14414747cd9e694e7de3886af345a8', 'v2', '2026-07-24T07:05:23+00:00', '["projet/class/project.class.php:2706: if (getDolGlobalString(''MAIN_NON_WORKING_DAYS_INCLUDE_TUESDAY'')) {", "projet/class/project.class.php:2701: if (getDolGlobalString(''MAIN_NON_WORKING_DAYS_INCLUDE_MONDAY'')) { $numHolidays -= 1; $weekendEnabled += 1; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NOT_INCLUDE_ZERO_VAT_IN_REPORTS', 'string', NULL, 'core', 'Excludes VAT lines with a zero rate from tax reports and summaries.', 'Checked in at least 10 places in core/lib/tax.lib.php (lines 214, 272, 408, 454, 568, 765, 807, 945, and more) to skip zero-VAT entries when building report datasets.', 'Enabling this constant cleans up tax reports by omitting zero-rate VAT lines, which is useful for businesses that apply VAT exemptions and want simplified reporting.', 'Empty/unset = zero-rate VAT included in reports; truthy value = zero-rate VAT lines are excluded.', 1, 0, NULL, 1, '2a08fdde92ef1e4abbc4ff43e0621829c2b2e57a56ff04a16a78f97d4d926c46', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/tax.lib.php:214|check|if (getDolGlobalString(''MAIN_NOT_INCLUDE_ZERO_VAT_IN_REPORTS'')) {", "core/lib/tax.lib.php:272|check|if (getDolGlobalString(''MAIN_NOT_INCLUDE_ZERO_VAT_IN_REPORTS'')) {", "core/lib/tax.lib.php:408|check|if (getDolGlobalString(''MAIN_NOT_INCLUDE_ZERO_VAT_IN_REPORTS'')) {", "core/lib/tax.lib.php:454|check|if (getDolGlobalString(''MAIN_NOT_INCLUDE_ZERO_VAT_IN_REPORTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NOT_INSTALLED', 'string', '1', 'core', 'Flags that Dolibarr has not been fully installed, triggering a redirect to the installation wizard.', 'Checked in main.inc.php:306 alongside MAIN_NOT_UPGRADED to redirect users to the install process. Also checked in install/check.php:514. Default is ''1''. Two occurrences across two files. No admin UI write is present.', 'When this constant is set to a truthy value, all requests are redirected to the installation wizard. It is cleared upon successful installation.', 'String/integer; ''1'' or truthy = installation not complete (redirects to install); unset or ''0'' = installation complete.', 1, 1, NULL, 1, '1ee45f7c85c323f2a5a736cd349dcf04e8aca2f42d0cd4fa14a0d47c5ec56b06', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:306|check|if (getDolGlobalString(''MAIN_NOT_INSTALLED'') || getDolGlobalString(''MAIN_NOT_UPGRADED'')) {", "install/check.php:514|check|if (getDolGlobalInt(\"MAIN_NOT_INSTALLED\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NOT_UPGRADED', 'string', NULL, 'core', 'Flags that a Dolibarr install/upgrade process was not completed, forcing redirection to the install page.', 'Checked in main.inc.php:309 alongside MAIN_NOT_INSTALLED at every page load; if either is set truthy, the request is redirected to install/index.php instead of the normal application.', 'Setting it forces every page to redirect to the installer instead of loading the application, effectively locking users out until the install/upgrade is completed.', 'Boolean-like: any truthy value blocks normal access and forces redirect to install/index.php.', 0, 0, NULL, 1, 'a94f31aee9c12e9046502770039061b1feb3b363a325d6eb7798fb6805fbbebf', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:309|check|if (getDolGlobalString(''MAIN_NOT_INSTALLED'') || getDolGlobalString(''MAIN_NOT_UPGRADED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NO_BOOKMARKS_FOR_LANDING_PAGES', 'string', NULL, 'user', 'Disables the automatic listing of the user''s bookmarks as extra landing-page shortcuts on the personal IHM setup page.', 'Read in user/param_ihm.php:259, guarding a block that queries llx_bookmark for non-http bookmarks (own or global) to add to the list of possible home/landing pages a user can pick.', 'When set (truthy), the SQL query and resulting bookmark-derived landing page options are skipped entirely, so the landing-page selector only shows the built-in module pages (commercial, billing, accountancy, members, agenda, tickets).', 'Truthy value disables bookmark-based landing pages; empty/unset (default) includes them.', 1, 0, NULL, 1, 'c23887c045baaf83dbe5d277f476af0b6b7506f6c871cfc3e3a251152bcf1d55', 'v2', '2026-07-24T07:05:23+00:00', '["user/param_ihm.php:259: if (!getDolGlobalString(''MAIN_NO_BOOKMARKS_FOR_LANDING_PAGES'')) {", "user/param_ihm.php:260: // add bookmarks to available landing pages"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NO_INPUT_PRICE_WITH_TAX', 'string', NULL, 'core', 'Hidden option that disables the ''input price with tax'' column/input on document line editing templates.', 'Checked with getDolGlobalInt(''MAIN_NO_INPUT_PRICE_WITH_TAX'') in core/tpl/subtotal_view.tpl.php:112/188, core/tpl/objectline_view.tpl.php:470/488, and core/tpl/objectline_title.tpl.php:136/141; no admin UI page found in the payload.', 'When enabled, the colspan/columns for entering a price including tax are hidden or adjusted on line templates, per the ''Handling colspan if MAIN_NO_INPUT_PRICE_WITH_TAX conf is enabled'' comments.', NULL, 1, 0, NULL, 1, 'febdb22856f4396ce33f0710ea949ff3eb050f04bfc50a8791df929cd1f6d5fa', 'v2', '2026-07-24T06:41:12+00:00', '["core/tpl/subtotal_view.tpl.php:111|// Handling colspan if MAIN_NO_INPUT_PRICE_WITH_TAX conf is enabled", "fourn/facture/card.php:4174|// Show object lines (result may vary according to hidden option MAIN_NO_INPUT_PRICE_WITH_TAX)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NO_MULTIDIR_FOR_ODT', 'string', NULL, 'core', 'Disables multi-directory scanning when resolving ODT template paths for document generators.', 'Checked in modulebuilder/template/core/modules/mymodule/doc/doc_generic_myobject_odt.modules.php:187, core/modules/asset/doc/doc_generic_asset_odt.modules.php:160, core/modules/societe/doc/doc_generic_odt.modules.php:141, and core/modules/bom/doc/doc_generic_bom_odt.modules.php:173. No admin UI write was found; HIDDEN_GUESS is 1.', 'When set, the ODT document generators skip scanning additional directories and use only the primary template directory.', '0 (scan multiple dirs) or 1 (single dir only)', 1, 0, NULL, 1, '6a04df18775de624913149328f2d30583cdc6540c500c117d2de356329e2a93d', 'v2', '2026-04-21T11:16:15+00:00', '["modulebuilder/template/core/modules/mymodule/doc/doc_generic_myobject_odt.modules.php:187|check|if (!getDolGlobalString(''MAIN_NO_MULTIDIR_FOR_ODT'')) {", "core/modules/asset/doc/doc_generic_asset_odt.modules.php:160|check|if (!getDolGlobalString(''MAIN_NO_MULTIDIR_FOR_ODT'')) {", "core/modules/societe/doc/doc_generic_odt.modules.php:141|check|if (!getDolGlobalString(''MAIN_NO_MULTIDIR_FOR_ODT'')) {", "core/modules/bom/doc/doc_generic_bom_odt.modules.php:173|check|if (!getDolGlobalString(''MAIN_NO_MULTIDIR_FOR_ODT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NO_UPGRADE_REDIRECT_ON_LEVEL_3_CHANGE', 'string', NULL, 'core', 'Disables the forced redirect to the install/upgrade page when only the build-level (3rd version digit) has changed.', 'In main.inc.php:329, when the running program version is higher than the database version ($rescomp > 0), Dolibarr normally redirects to install/index.php; if this constant is set and $rescomp < 3 (i.e. only a build-number bump), the redirect is skipped.', 'Setting it lets the application keep running on a build-version mismatch without forcing the user through the upgrade page, but the comment notes upgrade is still forced for larger (level 3) version changes.', 'Truthy value suppresses the redirect only when $rescomp < 3 (minor/build version bump); larger version jumps still force redirect regardless of this constant.', 0, 0, NULL, 1, 'a700be7bc5c106345c43f68553178f84a05593dd70b0e71320446954e33f5d7e', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:329|check|if (!getDolGlobalString(''MAIN_NO_UPGRADE_REDIRECT_ON_LEVEL_3_CHANGE'') || $rescomp < 3) {", "main.inc.php: // We did not add \"&& $rescomp < 3\" because we want upgrade process for build upgrades"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NUMBERING_FILTER_ON_INT_ONLY', 'string', NULL, 'core', 'Restricts the SQL query that computes the next numbering counter to only consider rows where the counter substring is purely numeric.', 'In core/lib/functions2.lib.php:1168-1170, inside the get_next_value counter-lookup SQL, if this int is set the code appends a regexp condition (db->regexpsql) requiring the extracted counter value to match ''^[0-9]+$'', with a comment explaining this avoids bad MAX() detection when data is ''noised with non numeric values''.', 'Enabling it makes the next-number computation ignore existing records whose ref counter segment contains non-digit characters, preventing incorrect MAX() results from noisy/legacy data; unset/false includes all matching rows regardless of counter format.', 'true/1 (int) = add SQL filter requiring counter to be all-digits; false/unset (default) = no such filter.', 1, 0, NULL, 1, '0f3bb756138ffac35334b41964b3e5845537fc2d27d869a2eef1b88088609f0d', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions2.lib.php:1166: // To ensure that all variables within the MAX() brackets are integers", "core/lib/functions2.lib.php:1167: // This avoid bad detection of max when data are noised with non numeric values at the position of the numero", "core/lib/functions2.lib.php:1168|check|if (getDolGlobalInt(''MAIN_NUMBERING_FILTER_ON_INT_ONLY'')) {", "core/lib/functions2.lib.php:1170: $sql .= \" AND \". $db->regexpsql($sqlstring, ''^[0-9]+$'', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_NUMBERING_OFFSET_ONLY_FOR_FIRST', 'string', NULL, 'core', 'Prevents the numbering mask offset from being re-applied to every subsequent counter that falls below it, once the sequence has started.', 'In core/lib/functions2.lib.php:1202, after computing the last counter value, if the counter is below the mask''s offset the code normally resets $counter to $maskoffset; setting this bool skips that reset (so the offset behavior is effectively used only the first time / not forced again).', 'Enabling it stops the counter from being forced back up to the mask offset value on every computation once it has already progressed past it in some other way; unset/false keeps forcing the counter to at least the offset value whenever it is below it.', 'true/1 = do not force counter back to maskoffset when counter < maskoffset; false/unset (default) = force counter = maskoffset whenever counter < maskoffset.', 1, 0, NULL, 1, '408bd8f565c8f04eb968e2ee2a21c87ea1d7082b61b9da61f29ceb83ad960448', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions2.lib.php:1202|read|} elseif ($counter < $maskoffset && !getDolGlobalString(''MAIN_NUMBERING_OFFSET_ONLY_FOR_FIRST'')) {", "core/lib/functions2.lib.php:1203: $counter = $maskoffset;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OBJECTLINE_CREATE_EMPTY_QTY_BY_DEFAULT', 'string', NULL, 'core', 'Leaves the quantity field empty by default (instead of pre-filled with 1) when creating a new document line.', 'Used in core/tpl/objectline_create.tpl.php:532: $default_qty = (!getDolGlobalString(''MAIN_OBJECTLINE_CREATE_EMPTY_QTY_BY_DEFAULT'') ? 1 : '''') — i.e. default qty is 1 unless this constant is set, in which case it is an empty string.', 'Enabling it changes the default quantity shown in the new-line quantity input from 1 to blank, requiring the user to type a quantity explicitly.', 'Boolean-like: truthy makes the default line quantity empty ('''') instead of 1.', 0, 0, NULL, 1, 'b7f939d76f506c1f62f8ccba9f79b59a4f4e8c70de1afc14924507a583ba62f0', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:532|read|<?php $default_qty = (!getDolGlobalString(''MAIN_OBJECTLINE_CREATE_EMPTY_QTY_BY_DEFAULT'') ? 1 : ''''); ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ODF_ZIP_PROXY', 'string', NULL, 'core', 'Selects the ZIP proxy library used when creating ODT documents from templates.', 'Read across 23 occurrences in ODT generation modules as: ''ZIP_PROXY'' => getDolGlobalString(''MAIN_ODF_ZIP_PROXY'', ''PclZipProxy''), // PhpZipProxy or PclZipProxy. Got "bad compression method" error when using PhpZipProxy.', 'Changing this value switches the ZIP library used for ODT generation; PclZipProxy is the default due to compatibility issues with PhpZipProxy.', 'String: ''PclZipProxy'' (default) or ''PhpZipProxy''.', 1, 0, NULL, 1, 'bdbe16bef783759f8a5f7be1d2cd5101e363d2a94d86c7057e7cfdd1a913b2e6', 'v2', '2026-04-21T11:16:15+00:00', '["recruitment/core/modules/recruitment/doc/doc_generic_recruitmentjobposition_odt.modules.php:365|read|''ZIP_PROXY''\t\t  => getDolGlobalString(''MAIN_ODF_ZIP_PROXY'', ''PclZipProxy''), // PhpZipProxy or PclZipProxy. Got \"bad compression method\" error when using PhpZipProxy.", "core/modules/contract/doc/doc_generic_contract_odt.modules.php:365|read|''ZIP_PROXY''\t\t  => getDolGlobalString(''MAIN_ODF_ZIP_PROXY'', ''PclZipProxy''), // PhpZipProxy or PclZipProxy. Got \"bad compression method\" error when using PhpZipProxy.", "core/modules/member/doc/doc_generic_member_odt.class.php:322|read|''ZIP_PROXY''\t\t  => getDolGlobalString(''MAIN_ODF_ZIP_PROXY'', ''PclZipProxy''), // PhpZipProxy or PclZipProxy. Got \"bad compression method\" error when using PhpZipProxy."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ODT_ADD_SLASH_FOR_WINDOWS', 'string', NULL, 'core', 'Adds a leading ''///'' prefix to the LibreOffice UserInstallation path when converting ODT to PDF, needed for correct file:// URI formatting on Windows.', 'Used in includes/odtphp/odf.php:918 when building the ''soffice --headless -env:UserInstallation=file:...'' command line for ODT-to-PDF conversion via LibreOffice.', 'When set, the generated soffice command uses ''file:///<path>'' instead of ''file:<path>''; needed on Windows hosts so LibreOffice correctly parses the UserInstallation directory URI.', 'Truthy prefixes the UserInstallation path with ''///''; empty/0 omits the prefix (default, suited for Linux/Mac paths).', 1, 0, NULL, 1, '19ac971a49f01b5ec5e36ff3959cac46cf30359a0547637c7ea486498039bef4', 'v2', '2026-07-24T07:05:23+00:00', '["includes/odtphp/odf.php:918: $command =''soffice --headless -env:UserInstallation=file:''.escapeshellarg((getDolGlobalString(''MAIN_ODT_ADD_SLASH_FOR_WINDOWS'') ? ''///'' : '''').dol_sanitizePathName($conf->user->dir_temp).''/odtaspdf'')..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ODT_AS_PDF', 'string', NULL, 'core', 'Enables automatic conversion of generated ODT documents to PDF using an external converter command.', 'Checked across 29 occurrences in ODT generation modules; includes/odtphp/odf.php:892 checks for the specific value ''libreoffice''. A code comment at odf.php:910 documents the full usage: ''MAIN_ODT_AS_PDF should be "sudo -u unoconv /usr/bin/unoconv" and userunoconv must have sudo to be root by adding file /etc/sudoers.d/unoconv with content www-data ALL=(unoconv) NOPASSWD: /usr/bin/unoconv''.', 'Setting this to a command string (e.g. ''libreoffice'' or a unoconv sudo command) causes ODT files to be converted to PDF after generation.', 'String: empty or unset = ODT only; ''libreoffice'' = use LibreOffice; full command path (e.g. ''sudo -u unoconv /usr/bin/unoconv'') = use unoconv.', 1, 0, NULL, 1, '18bd8e58e1fc6cd5f1fb03a56eea9faa802e4dd66adc7b0992002031bb546782', 'v2', '2026-04-21T11:16:15+00:00', '["includes/odtphp/odf.php:892|check|if (getDolGlobalString(''MAIN_ODT_AS_PDF'') == ''libreoffice'') {", "includes/odtphp/odf.php:910  // MAIN_ODT_AS_PDF should be   \"sudo -u unoconv /usr/bin/unoconv\" and userunoconv must have sudo to be root by adding file /etc/sudoers.d/unoconv with content  www-data ALL=(unoconv) NOPASSWD: /usr/bin/unoconv .", "core/modules/contract/doc/doc_generic_contract_odt.modules.php:469|check|if (getDolGlobalString(''MAIN_ODT_AS_PDF'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ODT_AS_PDFA', 'string', NULL, 'core', 'Controls whether ODT-to-PDF export produces a PDF/A compliant file instead of a plain PDF.', 'Read once in includes/odtphp/odf.php:914, documented at line 908 explaining the default LibreOffice behavior.', 'By default LibreOffice exports a plain PDF; when MAIN_ODT_AS_PDFA is set, the export is changed to produce a PDF/A file per the comment.', NULL, 1, 0, NULL, 1, '7725170b279ead4f89d6d896b520d8159bdb94f256cb8929e7065e00338fc2cf', 'v2', '2026-07-24T06:41:12+00:00', '["// By default LibreOffice exports a plain PDF. If MAIN_ODT_AS_PDFA is set to", "$pdfaversion = getDolGlobalInt(''MAIN_ODT_AS_PDFA'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ODT_AS_PDF_DEL_SOURCE', 'string', NULL, 'core', 'Deletes the source ODT/ODX file after it has been converted and output as a PDF.', 'Checked in includes/odtphp/odf.php:1031, in the exportAsAttachedPDF() flow, right after the converted PDF has been sent for download (unlink($name) is called on the source file).', 'When enabled, the original ODT template output file is removed from disk right after conversion to PDF, freeing storage but making the ODT source unavailable afterward.', 'Truthy deletes the ODT source file post-conversion; empty/0 keeps it on disk (default).', 1, 0, NULL, 1, '49e63089695ee256ab64117f25d0e8de935c3fd71e68cce98b09be0d1f57636c', 'v2', '2026-07-24T07:05:23+00:00', '["includes/odtphp/odf.php:1031: if (getDolGlobalString(''MAIN_ODT_AS_PDF_DEL_SOURCE'')) {", "includes/odtphp/odf.php:1032: unlink($name);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ODT_AS_PDF_OMIT_TEMPLATE_NAME', 'string', NULL, 'core', 'Omits the ODT template''s base filename from the generated invoice document filename, using only the object reference.', 'In core/modules/facture/doc/doc_generic_invoice_odt.modules.php:274, when building the output filename for a generated ODT invoice, if this bool is set the filename is just $objectref; otherwise it is $objectref . ''_'' . $newfiletmp (the cleaned template filename).', 'Enabling it produces shorter invoice document filenames containing only the invoice reference, dropping the template name suffix; unset/false keeps the template name appended.', 'true/1 = filename = object reference only; false/unset (default) = filename = reference_templatename.', 1, 0, NULL, 1, '2eedd000df1d2db4e209cfa346bef9628a6e9272f08abb4df2c866005d61a8e8', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/doc_generic_invoice_odt.modules.php:274|check|if (getDolGlobalString(''MAIN_ODT_AS_PDF_OMIT_TEMPLATE_NAME'')) {", "core/modules/facture/doc/doc_generic_invoice_odt.modules.php:275: $newfiletmp = $objectref;", "core/modules/facture/doc/doc_generic_invoice_odt.modules.php:277: $newfiletmp = $objectref . ''_'' . $newfiletmp;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OLD_IMAGE_LINKS', 'string', NULL, 'core', 'Enables a backward-compatible photo filename fallback (id + ''.jpg'') for user/member photo display.', 'Checked twice in core/class/html.form.class.php (user photo block ~line 11829 and member photo block ~line 11849); when true, $altfile is set to $object->id . ''.jpg'' explicitly commented ''// For backward compatibility''.', 'Enabling it provides an alternate legacy filename ($object->id.''.jpg'') to fall back to when displaying user/member photos, for compatibility with older photo storage naming.', 'Boolean: truthy value sets $altfile = id.''.jpg'' as a backward-compatibility fallback filename.', 1, 0, NULL, 1, '3ff73b63a8e52622dc3a7c7c88a1614e4dea7381da2c7cff8c4b3c8611c6a5f2', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:11849|check|if (getDolGlobalString(''MAIN_OLD_IMAGE_LINKS'')) {", "core/class/html.form.class.php: $altfile = $object->id . \".jpg\"; // For backward compatibility"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ONLY_LOGIN_ALLOWED', 'bool', NULL, 'core', 'Restricts application login to the specified username(s), effectively locking the system to one user.', 'Written via admin/tools/listsessions.php (lines 89, 96). Checked in main.inc.php (lines 173, 187, 3496) to enforce login restriction and in user/card.php:2235. The comment at main.inc.php:172 states: ''If software has been locked. Only login getDolGlobalString(''MAIN_ONLY_LOGIN_ALLOWED'') is allowed.''', 'When set, any user whose login is not in the semicolon-separated list is rejected at authentication time, effectively locking the system.', 'String: semicolon-separated username(s) allowed to log in; empty/unset to allow all users.', 0, 0, 'admin/tools/listsessions.php|admin/tools/listsessions.php|admin/tools/listsessions.php', 1, 'fb0d56d3184b0cdd79cd76a28208679be6a7e4ba61fd2239cf8744b8f4a702a6', 'v2', '2026-04-21T11:16:15+00:00', '["// If software has been locked. Only login getDolGlobalString(''MAIN_ONLY_LOGIN_ALLOWED'') is allowed.", "main.inc.php:187|check|if (session_id() && isset($_SESSION[\"dol_login\"]) && !in_array($_SESSION[\"dol_login\"], explode('';'', getDolGlobalString(''MAIN_ONLY_LOGIN_ALLOWED'')))) {", "admin/tools/listsessions.php:89|write|if (dolibarr_set_const($db, ''MAIN_ONLY_LOGIN_ALLOWED'', $user->login, ''text'', 1, ''Logon is restricted to a particular user'', 0) < 0) {", "admin/tools/listsessions.php:254|check|if (!getDolGlobalString(''MAIN_ONLY_LOGIN_ALLOWED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OPENIDURL_PERUSER', 'string', NULL, 'user', 'Enables per-user OpenID URL support on user profile pages when OpenID authentication is active.', 'Checked in user/card.php at lines 1921 and 2804, conjunctively with a check that main_authentication contains ''openid''. When set, an OpenID URL field is shown on the user card.', 'Enabling this constant adds a per-user OpenID URL field to user profile pages when OpenID authentication is configured; leaving it unset suppresses this field.', 'Truthy value to enable per-user OpenID URL field; empty or unset to disable.', 1, 0, NULL, 1, 'e97b4f495b574c22780dd3c0e4c2eb9214d2d64ff99a0d9c8d55eed07c977280', 'v2', '2026-04-21T13:50:40+00:00', '["user/card.php:2804|check|if (isset($conf->file->main_authentication) && preg_match(''/openid/'', $conf->file->main_authentication) && getDolGlobalString(''MAIN_OPENIDURL_PERUSER'')) {", "user/card.php:1921|check|if (isset($conf->file->main_authentication) && preg_match(''/openid/'', $conf->file->main_authentication) && getDolGlobalString(''MAIN_OPENIDURL_PERUSER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OPENSURVEY_CSS_URL', 'string', NULL, 'public', 'URL of a custom CSS stylesheet injected into the public OpenSurvey page header.', 'Used in public/opensurvey/index.php:109-110: if set, a <link> tag pointing to this URL is added to the page head, appended with the current language as a query parameter.', 'Setting it lets an admin override the visual style of the public survey interface by pointing to an external stylesheet; leaving it empty means no extra CSS is loaded.', 'Any absolute or relative URL string to a CSS file.', 1, 0, NULL, 1, '8afca9732bb4d470015203f23629ae250cd233b794b76d2b87f2374e1f28fc48', 'v2', '2026-07-24T07:05:23+00:00', '["public/opensurvey/index.php:109: if (getDolGlobalString(''MAIN_OPENSURVEY_CSS_URL'')) {", "public/opensurvey/index.php:110: $head = ''<link rel=\"stylesheet\" type=\"text/css\" href=\"''.getDolGlobalString(''MAIN_OPENSURVEY_CSS_URL'').''?lang=''.$langs->defaultlang.''\">''.\"\\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OPTIMIZEFORCOLORBLIND', 'string', NULL, 'core', 'Activates a color-blind-optimized CSS class on the UI for the current user.', 'Set per-user at main.inc.php:1229 from the user preference, then checked at main.inc.php:1477-1478 to append a ''colorblind-<value>'' CSS class. Theme files theme/eldy/theme_vars.inc.php:38-39 and theme/md/theme_vars.inc.php:34-35 also branch on this value including the specific value ''flashy''.', 'Setting this changes the color palette applied via CSS for accessibility; the value ''flashy'' triggers a specific high-contrast variant.', ''''' or unset = no color-blind optimization; any non-empty string = colorblind CSS class suffix appended (e.g. ''flashy'' for flashy variant)', 1, 0, NULL, 1, '5bfe7c0ea9b0a00ad6a1b25135bf45ef7c694f11a908acbc6ef588eefb98816e', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1228  // set MAIN_OPTIMIZEFORCOLORBLIND for user", "main.inc.php:1478|read|$tmpcsstouse .= '' colorblind-''.strip_tags(getDolGlobalString(''MAIN_OPTIMIZEFORCOLORBLIND''));", "theme/eldy/theme_vars.inc.php:39|check|if (getDolGlobalString(''MAIN_OPTIMIZEFORCOLORBLIND'') == ''flashy'') {", "theme/md/theme_vars.inc.php:35|check|if (getDolGlobalString(''MAIN_OPTIMIZEFORCOLORBLIND'') == ''flashy'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OPTIMIZEFORTEXTBROWSER', 'string', NULL, 'core', 'Enables an optimized rendering mode for text-only/low-graphics browsers, disabling some UI elements across the application.', 'Set as a global before login in main.inc.php:244 (''Set global MAIN_OPTIMIZEFORTEXTBROWSER (must be before login part)'') and checked with getDolGlobalString/getDolGlobalInt(''MAIN_OPTIMIZEFORTEXTBROWSER'') across 231 occurrences, e.g. bookmarks/bookmarks.lib.php:113/166, product/class/product.class.php:5893.', 'When enabled, numerous UI features (bookmarks display, various pictos/icons) are conditionally shown or hidden across many modules to simplify rendering for text browsers.', NULL, 0, 0, NULL, 1, '4dadd30fb6143385df40ee52266ca626e0f5d709d1e8fbf2b6bd484ed246754f', 'v2', '2026-07-24T06:41:12+00:00', '["main.inc.php:244|// Set global MAIN_OPTIMIZEFORTEXTBROWSER (must be before login part)", "bookmarks/bookmarks.lib.php:113|check|if (!getDolGlobalString(''MAIN_OPTIMIZEFORTEXTBROWSER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OPTIMIZE_SPEED', 'string', NULL, 'core', 'Bitmask controlling performance optimizations such as APC/APCu shared memory caching.', 'Checked as a bitmask in core/lib/memory.lib.php:134 and 239 and core/class/translate.class.php:337 and 521 with ''& 0x02'' to enable APCu-based caching. The comment at memory.lib.php:134 notes: ''This is a really not reliable cache ! Use Memcached instead.'' Configurable via admin/system/dolibarr.php.', 'Setting bit 0x02 enables APCu shared memory caching for translations and other data, which is noted as unreliable; higher or other bit values may control additional optimizations.', 'Integer bitmask; 0x02 bit = enable APCu caching (unreliable, prefer Memcached); 0 or unset = no APCu caching.', 0, 0, 'admin/system/dolibarr.php', 1, '12a2650945d324252dfaf3b3f2aef32c0cab7ca2949e961e5a3545b3c0d37e07', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/memory.lib.php:134|read|} elseif (getDolGlobalInt(''MAIN_OPTIMIZE_SPEED'') & 0x02) {\t// This is a really not reliable cache ! Use Memcached instead.", "core/lib/memory.lib.php:239|read|} elseif (getDolGlobalInt(''MAIN_OPTIMIZE_SPEED'') & 0x02) {\t// This is a really not reliable cache ! Use Memcached instead.", "admin/system/dolibarr.php:260|check|if (getDolGlobalInt(''MAIN_OPTIMIZE_SPEED'') & 0x02) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ORDERLIST_CREATEBILLS_ONEBYTHIRD', 'string', NULL, 'commande', 'Sets the default value (''yes''/''no'') of the ''create one bill by third party'' checkbox shown in the mass ''create bills from orders'' confirmation form on the order list.', 'Read in commande/list.php:1689: print $form->selectyesno(''createbills_onebythird'', getDolGlobalString(''MAIN_ORDERLIST_CREATEBILLS_ONEBYTHIRD'', ''no''), 1); — default fallback is ''no'' if unset.', 'Changes only the default pre-selected value of the ''CreateOneBillByThird'' yes/no selector in the mass-create-bills confirmation dialog; the user can still change it before confirming.', 'String: ''yes'' or ''no'' (default ''no'' when the constant is unset, per the getDolGlobalString fallback argument).', 0, 0, NULL, 1, '0b198024ae1bebe85d86faa10e3daf83dc5ba0b6b72f40a7acb216f3c3a1d7ae', 'v2', '2026-07-24T07:05:23+00:00', '["commande/list.php:1689: print $form->selectyesno(''createbills_onebythird'', getDolGlobalString(''MAIN_ORDERLIST_CREATEBILLS_ONEBYTHIRD'', ''no''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ORGANIZATION_FOR_PING', 'string', NULL, 'blockedlog', 'Overrides the organization name sent in blockedlog registration/ping requests, defaulting to ''Association Dolibarr''.', 'Read at blockedlog/admin/registration.php:273, blockedlog/admin/documentation.php:143, and blockedlog/admin/blockedlog.php:146, all with the same default ''Association Dolibarr''. Configurable via admin UI on those pages.', 'Changing this value updates the organization name transmitted to the ping server in registration requests.', 'Any string; default is ''Association Dolibarr''.', 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/documentation.php|blockedlog/admin/blockedlog.php', 1, '95a618594727c330f74d369fad6479dde1317c0ee8134a4eba4620e70609b551', 'v2', '2026-04-21T11:16:15+00:00', '["$organization_for_ping = getDolGlobalString(''MAIN_ORGANIZATION_FOR_PING'', \"Association Dolibarr\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ORGANIZATION_URL_PRIVACY', 'string', NULL, 'blockedlog', 'Overrides the data privacy policy URL sent in blockedlog registration requests, defaulting to the Dolibarr GDPR page.', 'Read at blockedlog/admin/registration.php:274, blockedlog/admin/documentation.php:144, and blockedlog/admin/blockedlog.php:147, all with the default ''https://www.dolibarr.org/legal-privacy-gdpr.php''. Configurable via admin UI.', 'Changing this value updates the privacy policy URL included in blockedlog registration payloads.', 'A valid URL string; default is ''https://www.dolibarr.org/legal-privacy-gdpr.php''.', 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/documentation.php|blockedlog/admin/blockedlog.php', 1, '471027d9ba3a20a136c0dee9fba010adc302055bedac7837dec6b827fbe9ba3c', 'v2', '2026-04-21T11:16:15+00:00', '["$dataprivacy_url = getDolGlobalString(''MAIN_ORGANIZATION_URL_PRIVACY'', \"https://www.dolibarr.org/legal-privacy-gdpr.php\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OVERRIDE_TIME_LIMIT', 'string', NULL, 'core', 'Overrides the PHP execution time limit applied during the Dolibarr upgrade process (install/upgrade2.php).', 'Checked in install/upgrade2.php:95-96; if set, its value is passed directly to @set_time_limit(); otherwise the upgrade script falls back to a hardcoded 600 seconds.', 'Increasing it extends how long the upgrade script (upgrade2.php) is allowed to run before PHP''s time limit would normally stop it; has no effect where set_time_limit() is blocked (e.g. safe_mode-like restrictions).', 'Integer number of seconds for the upgrade script''s time limit; if unset, the script defaults to 600 seconds.', 1, 0, NULL, 1, '5a0fa302a80e29b31db6a78cdb3061dfc401a106a82ef8a6c483ba457907713a', 'v2', '2026-07-24T07:05:23+00:00', '["install/upgrade2.php:95: if (getDolGlobalInt(''MAIN_OVERRIDE_TIME_LIMIT'')) {", "install/upgrade2.php:96: @set_time_limit(getDolGlobalInt(''MAIN_OVERRIDE_TIME_LIMIT''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OVERWRITE_THEME_PATH', 'string', NULL, 'core', 'Overrides the base path used to locate the active theme''s files, letting an external module supply a differently-named theme directory.', 'In core/lib/functions.lib.php:6041-6042, if set, `$path = getDolGlobalString(''MAIN_OVERWRITE_THEME_PATH'') . ''/theme/'' . $theme` is used instead of the module''s own path, for cases where the theme directory name does not match the module name.', 'Setting it redirects theme asset/image resolution to a custom path, useful when packaging a theme whose directory name differs from the enabling module; takes precedence over MAIN_OVERWRITE_THEME_RES.', 'String: a filesystem/module path prefix under which ''/theme/<theme>'' is expected to exist.', 1, 0, NULL, 1, '52c7189e09d3c3ba8ac6539605fbaab59f1b9b18642e4709c469ea55302c3e2a', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:6041|check|if (getDolGlobalString(''MAIN_OVERWRITE_THEME_PATH'')) {", "core/lib/functions.lib.php:6042|read|$path = getDolGlobalString(''MAIN_OVERWRITE_THEME_PATH'') . ''/theme/'' . $theme; // If the theme does not have the same name as the module"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_OVERWRITE_THEME_RES', 'string', NULL, 'theme', 'Specifies an external module name whose resources (CSS, images) override the active theme''s assets.', 'Read in theme/eldy/style.css.php:182-183 and theme/md/style.css.php:189-190 to set $path and $theme for resource lookup. Also used in core/lib/functions.lib.php:6068 to construct the path for image resources from an external module. No admin UI is present.', 'Setting this value causes the theme to load CSS and image assets from the specified external module instead of the built-in theme directory.', 'String: name of the external module whose theme resources should be used (e.g. ''mybranding'').', 1, 0, NULL, 1, '5747de99912d13d9dce166f6485b5137444d6a7a1c83c70695def21795142b0d', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:182|read|$path = ''/'' . getDolGlobalString(''MAIN_OVERWRITE_THEME_RES'');", "theme/eldy/style.css.php:183|read|$theme = getDolGlobalString(''MAIN_OVERWRITE_THEME_RES'');", "core/lib/functions.lib.php:6068|read|$path = getDolGlobalString(''MAIN_OVERWRITE_THEME_RES'') . ''/theme/'' . getDolGlobalString(''MAIN_OVERWRITE_THEME_RES'');", "core/lib/functions.lib.php:6067|read|} elseif (getDolGlobalString(''MAIN_OVERWRITE_THEME_RES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PAGESIZE_CHOICES', 'string', NULL, 'core', 'Provides a custom comma-separated list of page-size options for pagination selectors.', 'Checked and read at core/lib/functions.lib.php:7596-7597. When set, its value is used directly as the available page-size choices in the pagination UI, overriding any default list.', 'Changing this value alters the page-size options users can select in all paginated list views.', 'A comma-separated string of integer values representing available page sizes (e.g. ''10,25,50,100''); empty/unset = default choices used', 1, 0, NULL, 1, '92c883550572636cb459c95b41ea0234be8ff94e7ab7e322bf71e8d2bd70ac5c', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:7596|check|if (getDolGlobalString(''MAIN_PAGESIZE_CHOICES'')) {", "core/lib/functions.lib.php:7597|read|$pagesizechoices = getDolGlobalString(''MAIN_PAGESIZE_CHOICES'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PAIMENTS_SHOW_ALL_INVOICE_TYPES', 'bool', NULL, 'fourn', 'Default value for whether the supplier/customer payment creation page displays invoices of all types, not just standard ones.', 'Read as the initial value of $displayAllInvoices in fourn/facture/paiement.php:80 and compta/paiement.php:67; can be overridden per-request by the ''display-all-invoices'' GET/POST parameter.', 'When set truthy, the invoice-to-pay selector on the payment page includes all invoice types (not filtered to type IN (0,1,3,5) or credit notes only) by default.', 'Bool: 0/unset = only standard invoice types shown by default; 1 = all invoice types shown by default.', 1, 0, NULL, 1, '9598a0a0cc3b1ec65697d805f302dfc0db69f1389016ca48af6e0fcd6faf1234', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/paiement.php:80|read|$displayAllInvoices = getDolGlobalInt(''MAIN_PAIMENTS_SHOW_ALL_INVOICE_TYPES'', 0);", "compta/paiement.php:67|read|$displayAllInvoices = getDolGlobalInt(''MAIN_PAIMENTS_SHOW_ALL_INVOICE_TYPES'', 0);", "fourn/facture/paiement.php:589|read|if (!$displayAllInvoices) { ... $sql .= '' AND f.type IN (0,1,3,5)''; ... } else { $sql .= '' AND f.type = 2''; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PASSWORD_FORGOTLINK', 'string', NULL, 'core', 'Overrides the target URL of the ''Password forgotten'' link on the login page.', 'In core/tpl/login.tpl.php:432-433, the login template defaults the forgot-password link to DOL_URL_ROOT.''/user/passwordforgotten.php'', but replaces it with this constant''s value if set, e.g. to point to an external password-reset service.', 'Setting it redirects users clicking ''Password forgotten'' to a custom URL instead of Dolibarr''s built-in passwordforgotten.php page.', 'String: a full URL to use instead of the default forgot-password page; empty/unset keeps the built-in page.', 1, 0, NULL, 1, '05b8d5cf1a552292d45735e14f9f10f6f3bf92b1d7add1d0c633816589a98ac5', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/login.tpl.php:432|check|if (getDolGlobalString(''MAIN_PASSWORD_FORGOTLINK'')) {", "core/tpl/login.tpl.php:433|read|$url = getDolGlobalString(''MAIN_PASSWORD_FORGOTLINK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PAYMENT_DONATION_REF_PREFIX', 'string', NULL, 'accountancy', 'Reference prefix used when generating/displaying donation payment references in the treasury accounting journal.', 'Read in accountancy/journal/treasuryjournal.php:777 with default ''D'', in the same pattern as the other MAIN_PAYMENT_*_REF_PREFIX constants used across payment types in the treasury journal.', 'Changing it changes the textual prefix shown/used for donation payment references in the treasury journal output; default is ''D'' if unset.', 'Any short string prefix; default ''D''.', 1, 0, NULL, 1, '727c5e538e37394171504393f0685ab1ad8cffc96d58419a16ec60dda3285ad4', 'v2', '2026-07-24T07:05:23+00:00', '["treasuryjournal.php:777: $prefix_ref = getDolGlobalString(''MAIN_PAYMENT_DONATION_REF_PREFIX'', ''D'');"]', 'medium', NULL);
