INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PAYMENT_SOCIALES_CONTRIBUTIONS_REF_PREFIX', 'string', NULL, 'accountancy', 'Reference prefix used when generating/displaying social-contributions payment references in the treasury accounting journal.', 'Read in accountancy/journal/treasuryjournal.php:642 with default ''SC'', in the ChargeSociales payment-handling block used to build bookkeeping entries.', 'Changing it changes the textual prefix shown/used for social contributions payment references in the treasury journal output; default is ''SC'' if unset.', 'Any short string prefix; default ''SC''.', 1, 0, NULL, 1, 'e3e4b7f6d7edea8d7e63f83163c3cb78e20a3e1c9ffd003b41e3b4dbfd997f66', 'v2', '2026-07-24T07:05:23+00:00', '["treasuryjournal.php:642: $prefix_ref = getDolGlobalString(''MAIN_PAYMENT_SOCIALES_CONTRIBUTIONS_REF_PREFIX'', ''SC'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PAYMENT_SUBSCRIPTION_REF_PREFIX', 'string', NULL, 'accountancy', 'Reference prefix used when generating/displaying member-subscription payment references in the treasury accounting journal.', 'Read in accountancy/journal/treasuryjournal.php:1000 with default ''SU'', in the same pattern as the other MAIN_PAYMENT_*_REF_PREFIX constants used across payment types in the treasury journal.', 'Changing it changes the textual prefix shown/used for subscription payment references in the treasury journal output; default is ''SU'' if unset.', 'Any short string prefix; default ''SU''.', 1, 0, NULL, 1, 'e916ca359f4437ef922cabc1ced11ab2e8355ea2d0aad793f2d46cc22dc1a2b3', 'v2', '2026-07-24T07:05:23+00:00', '["treasuryjournal.php:1000: $prefix_ref = getDolGlobalString(''MAIN_PAYMENT_SUBSCRIPTION_REF_PREFIX'', ''SU'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PAYMENT_TRANSFER_CASH_REF_PREFIX', 'string', NULL, 'accountancy', 'Reference prefix used when generating/displaying internal cash-transfer payment references in the treasury accounting journal.', 'Read in accountancy/journal/treasuryjournal.php:1066 with default ''T'', immediately after the ACCOUNTING_ACCOUNT_TRANSFER_CASH account lookup for the same transfer-cash journal block.', 'Changing it changes the textual prefix shown/used for internal cash transfer payment references in the treasury journal output; default is ''T'' if unset.', 'Any short string prefix; default ''T''.', 1, 0, NULL, 1, 'f2eacef0cd1814ee610e84042c15484c930b0db531027506a3bbd7394796167c', 'v2', '2026-07-24T07:05:23+00:00', '["treasuryjournal.php:1066: $prefix_ref = getDolGlobalString(''MAIN_PAYMENT_TRANSFER_CASH_REF_PREFIX'', ''T'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PAYMENT_VARIOUS_REF_PREFIX', 'string', NULL, 'accountancy', 'Reference prefix used when generating/displaying miscellaneous (''various'') payment references in the treasury accounting journal.', 'Read in accountancy/journal/treasuryjournal.php:931 with default ''PM'', in the same pattern as the other MAIN_PAYMENT_*_REF_PREFIX constants used across payment types in the treasury journal.', 'Changing it changes the textual prefix shown/used for miscellaneous payment references in the treasury journal output; default is ''PM'' if unset.', 'Any short string prefix; default ''PM''.', 1, 0, NULL, 1, '2161273c0e08f7b8ba8ca69e860ecdd09383bece46cc160f54cdf7b4c6f6cbb1', 'v2', '2026-07-24T07:05:23+00:00', '["treasuryjournal.php:931: $prefix_ref = getDolGlobalString(''MAIN_PAYMENT_VARIOUS_REF_PREFIX'', ''PM'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PAYMENT_VAT_REF_PREFIX', 'string', NULL, 'accountancy', 'Reference prefix used when generating/displaying VAT payment references in the treasury accounting journal.', 'Read in accountancy/journal/treasuryjournal.php:710 with default ''VAT'', in the same pattern as the other MAIN_PAYMENT_*_REF_PREFIX constants used across payment types in the treasury journal.', 'Changing it changes the textual prefix shown/used for VAT payment references in the treasury journal output; default is ''VAT'' if unset.', 'Any short string prefix; default ''VAT''.', 1, 0, NULL, 1, '1433964bd3671ef7caa62198eee03bbe23035b7e4b0af4190b1e27500640dd8d', 'v2', '2026-07-24T07:05:23+00:00', '["treasuryjournal.php:710: $prefix_ref = getDolGlobalString(''MAIN_PAYMENT_VAT_REF_PREFIX'', ''VAT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_ADDALSOTARGETDETAILS', 'string', NULL, 'core', 'Forces inclusion of the recipient''s phone, fax, email, and URL details in the target address block on PDF documents regardless of the rendering mode.', 'Checked across 10 occurrences in core/lib/pdf.lib.php and multiple PDF module files (e.g. :580, :595, :601, :607). When truthy it acts as an unconditional override equivalent to specifying ''targetwithdetails'' mode. No admin UI write is present.', 'Enabling this always adds contact details (phone, fax, email, URL) to the recipient address block, overriding default mode-based logic.', 'Truthy string (non-empty) = always show target contact details; absent/empty = details shown only when mode includes ''targetwithdetails''.', 1, 0, NULL, 1, '45190442ebf641d0f4da7eaf8752105b2c3f7fc2772c9547d6604b24953396fb', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:578|check|if (getDolGlobalString(''MAIN_PDF_ADDALSOTARGETDETAILS'') || preg_match(''/targetwithdetails/'', $mode)) {", "core/lib/pdf.lib.php:580|check|if (getDolGlobalString(''MAIN_PDF_ADDALSOTARGETDETAILS'') || $mode == ''targetwithdetails'' || preg_match(''/targetwithdetails_phone/'', $mode)) {", "core/lib/pdf.lib.php:595|check|if (getDolGlobalString(''MAIN_PDF_ADDALSOTARGETDETAILS'') || $mode == ''targetwithdetails'' || preg_match(''/targetwithdetails_fax/'', $mode)) {", "core/lib/pdf.lib.php:601|check|if (getDolGlobalString(''MAIN_PDF_ADDALSOTARGETDETAILS'') || $mode == ''targetwithdetails'' || preg_match(''/targetwithdetails_email/'', $mode)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_ADD_TERMSOFSALE_CONTRACT', 'string', NULL, 'admin', 'Determines whether and how terms-of-sale are appended to generated contract PDFs.', 'Read at admin/pdf_other.php:451 to conditionally display the file selector, and at core/modules/contract/doc/pdf_strato.modules.php:494 to decide whether to concatenate the terms file when both this constant and MAIN_INFO_CONTRACT_TERMSOFSALE are set. Also checked at contrat/card.php:2392 to show PDF model selection. Configurable via admin/pdf_other.php:127.', 'Setting this constant to a non-zero value causes the terms-of-sale file (defined by MAIN_INFO_CONTRACT_TERMSOFSALE) to be concatenated to contract PDFs.', '0 or unset = no terms appended; non-zero integer = terms-of-sale file appended to contract PDF.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, 'c00e800eb001b45d27cc1d15f88354f8beab2befb3093c0925b5dbf354d3c18e', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf_other.php:127|write|dolibarr_set_const($db, \"MAIN_PDF_ADD_TERMSOFSALE_CONTRACT\", GETPOST(\"MAIN_PDF_ADD_TERMSOFSALE_CONTRACT\", ''int''), ''chaine'', 0, '''', $conf->entity);", "core/modules/contract/doc/pdf_strato.modules.php:494|check|if (getDolGlobalString(''MAIN_INFO_CONTRACT_TERMSOFSALE'') && getDolGlobalInt(''MAIN_PDF_ADD_TERMSOFSALE_CONTRACT'')) {", "admin/pdf_other.php:451|check|if (getDolGlobalString(\"MAIN_PDF_ADD_TERMSOFSALE_CONTRACT\")) {", "contrat/card.php:2392|check|if (getDolGlobalString(''MAIN_PDF_ADD_TERMSOFSALE_CONTRACT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_ADD_TERMSOFSALE_INVOICE', 'string', NULL, 'admin', 'Controls whether and how a terms-of-sale document is appended to invoice PDFs.', 'Configurable via admin/pdf_other.php (written at line 130, read at line 526). Checked in core/modules/facture/doc/pdf_octopus.modules.php:1039 and pdf_sponge.modules.php:1109 to append the terms-of-sale file to generated invoice PDFs.', 'Setting this constant to a non-zero value causes the terms-of-sale file (specified by MAIN_INFO_INVOICE_TERMSOFSALE) to be concatenated to invoice PDFs during generation.', '0 or unset = no terms-of-sale appended; non-zero = terms-of-sale file is appended to invoice PDF.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, '93cd1fb1f6940ed45aeb31e2223ac9c31f663182dd0608263ba322bb8071fd57', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf_other.php:130|write|dolibarr_set_const($db, \"MAIN_PDF_ADD_TERMSOFSALE_INVOICE\", GETPOST(\"MAIN_PDF_ADD_TERMSOFSALE_INVOICE\", ''int''), ''chaine'', 0, '''', $conf->entity);", "admin/pdf_other.php:526|read|print $form->selectarray(\"MAIN_PDF_ADD_TERMSOFSALE_INVOICE\", $arrval, getDolGlobalString(''MAIN_PDF_ADD_TERMSOFSALE_INVOICE''));", "core/modules/facture/doc/pdf_octopus.modules.php:1039|check|if (getDolGlobalInt(''MAIN_PDF_ADD_TERMSOFSALE_INVOICE'') && $termsofsalefilename) {", "core/modules/facture/doc/pdf_sponge.modules.php:1109|check|if (getDolGlobalInt(''MAIN_PDF_ADD_TERMSOFSALE_INVOICE'') && $termsofsalefilename) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_ADD_TERMSOFSALE_ORDER', 'string', NULL, 'admin', 'Controls whether the terms-of-sale document is automatically appended to generated order PDFs.', 'Managed via the admin UI at admin/pdf_other.php (written by dolibarr_set_const, displayed as a select array). Checked in pdf_einstein.modules.php and pdf_eratosthene.modules.php combined with a non-empty $termsofsalefilename, and in commande/card.php for tooltip display.', 'Enabling this causes the file named in MAIN_INFO_ORDER_TERMSOFSALE to be concatenated to order PDFs. Disabling it prevents terms-of-sale concatenation even if the filename is configured.', '0 or empty = no terms-of-sale appended; non-zero = terms-of-sale PDF appended to order PDFs.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, '6f06467f738c2685310022bfc2000813e7e48e05eaf0a424a326995f80c3f377', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:124|dolibarr_set_const($db, \"MAIN_PDF_ADD_TERMSOFSALE_ORDER\", GETPOST(\"MAIN_PDF_ADD_TERMSOFSALE_ORDER\", ''int''), ''chaine'', 0, '''', $conf->entity);", "admin/pdf_other.php:404|print $form->selectarray(\"MAIN_PDF_ADD_TERMSOFSALE_ORDER\", $arrval, getDolGlobalString(''MAIN_PDF_ADD_TERMSOFSALE_ORDER''));", "pdf_einstein.modules.php:645|if (getDolGlobalInt(''MAIN_PDF_ADD_TERMSOFSALE_ORDER'') && $termsofsalefilename) {", "commande/card.php:3687|if (getDolGlobalString(''MAIN_PDF_ADD_TERMSOFSALE_ORDER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_ADD_TERMSOFSALE_PROPAL', 'string', NULL, 'admin', 'Controls whether a terms-of-sale document is appended to proposal PDFs.', 'When set, the PDF generation for proposals (azur, cyan templates) appends the file specified by MAIN_INFO_PROPAL_TERMSOFSALE. Configurable via admin/pdf_other.php. Seen in pdf_cyan.modules.php:946, pdf_azur.modules.php:775, and comm/propal/card.php:3760.', 'Enabling this automatically concatenates the terms-of-sale PDF to every proposal document; disabling it omits the attachment.', 'Empty/unset = no terms-of-sale appended; truthy value = terms-of-sale file is concatenated to the proposal PDF.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, '3bd33747ab940774ddf1e5353ab6c627486436ad0b23c3ede71b1707f334b872', 'v2', '2026-04-21T13:29:58+00:00', '["admin/pdf_other.php:121|write|dolibarr_set_const($db, \"MAIN_PDF_ADD_TERMSOFSALE_PROPAL\", GETPOST(\"MAIN_PDF_ADD_TERMSOFSALE_PROPAL\", ''int''), ''chaine'', 0, '''', $conf->entity);", "core/modules/propale/doc/pdf_cyan.modules.php:946|check|if (getDolGlobalInt(''MAIN_PDF_ADD_TERMSOFSALE_PROPAL'') && $termsofsalefilename) {", "core/modules/propale/doc/pdf_azur.modules.php:775|check|if (getDolGlobalInt(''MAIN_PDF_ADD_TERMSOFSALE_PROPAL'') && $termsofsalefilename) {", "admin/pdf_other.php:325|read|print $form->selectarray(\"MAIN_PDF_ADD_TERMSOFSALE_PROPAL\", $arrval, getDolGlobalString(''MAIN_PDF_ADD_TERMSOFSALE_PROPAL''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_DASH_BETWEEN_LINES', 'string', NULL, 'core', 'Draws a dashed separator line between PDF document line items.', 'Checked in 43 locations across stock, stocktransfer, expedition, commande, facture, and other PDF modules at positions such as core/modules/stocktransfer/doc/pdf_eagle.modules.php:679 and core/modules/commande/doc/pdf_einstein.modules.php:567. No admin UI write was found; HIDDEN_GUESS is 1.', 'Enabling this constant causes a dashed line to be drawn between each line item in generated PDFs, except after the last item.', '0 (no dash lines) or 1 (dash lines between items)', 1, 0, NULL, 1, '717c8e867bde92c2cee93107177e47a001ef4b2b2e62add4416be77d2016b0bf', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/stocktransfer/doc/pdf_eagle.modules.php:679|check|if (getDolGlobalString(''MAIN_PDF_DASH_BETWEEN_LINES'') && $i < ($nblines - 1)) {", "core/modules/commande/doc/pdf_einstein.modules.php:567|check|if (getDolGlobalString(''MAIN_PDF_DASH_BETWEEN_LINES'') && $i < ($nblines - 1)) {", "core/modules/expedition/doc/pdf_rouget.modules.php:619|check|if (getDolGlobalString(''MAIN_PDF_DASH_BETWEEN_LINES'') && $i < ($nblines - 1)) {", "modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:736|check|if (getDolGlobalInt(''MAIN_PDF_DASH_BETWEEN_LINES'') && $i < ($nblines - 1)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_DATA_ON_FIRST_PAGE', 'string', NULL, 'core', 'Forces line items data to start on the first page of generated PDFs rather than beginning on a subsequent page.', 'Checked across 48 occurrences in PDF generation modules (e.g. core/modules/contract/doc/pdf_strato.modules.php:413, core/modules/stock/doc/pdf_standard_stock.modules.php:361). A commented example is present at modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:566.', 'Enabling this displays data starting on the first page; disabling it allows the layout engine to defer data to subsequent pages.', '0 or unset = data placement determined by layout engine; 1 = data starts on first page.', 1, 0, NULL, 1, 'b2ad9e94ef8461fd1d092d9c0144cc4320ea7ca185f0b1defb8c6647a504eaf7', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:413|check|if (getDolGlobalString(''MAIN_PDF_DATA_ON_FIRST_PAGE'')) {", "core/modules/stock/doc/pdf_standard_stock.modules.php:361|check|if (getDolGlobalString(''MAIN_PDF_DATA_ON_FIRST_PAGE'')) {", "recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:518|check|if (getDolGlobalString(''MAIN_PDF_DATA_ON_FIRST_PAGE'')) {", "modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:566  // \t\tif (getDolGlobalInt(''MAIN_PDF_DATA_ON_FIRST_PAGE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_DATE_TEXT', 'string', NULL, 'core', 'Selects whether dates printed on Cyan and Azur proposal PDFs use numeric or textual (spelled-out) day format.', 'Checked identically in core/modules/propale/doc/pdf_cyan.modules.php:1805 and core/modules/propale/doc/pdf_azur.modules.php:1674, both setting $displaydate to ''daytext'' if true, else ''day'' — the same pattern as MAIN_PDF_DELIVERY_DATE_TEXT but applied to the general date field rather than only the delivery date.', 'Enabling it changes date formatting on these proposal PDFs from plain day format to textual day format.', 'Boolean: true/1 selects ''daytext'' format; false/unset selects plain ''day'' format.', 0, 0, NULL, 1, '5c1291fcdafb4f8041fb0ae0bc101e85e485a7feadeca80042ee1a71dfddbee9', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:1805|check|if (getDolGlobalString(''MAIN_PDF_DATE_TEXT'')) {", "core/modules/propale/doc/pdf_azur.modules.php:1674|check|if (getDolGlobalString(''MAIN_PDF_DATE_TEXT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_DELIVERY_DATE_TEXT', 'string', NULL, 'core', 'Selects whether the shipping/delivery date shown on Cyan and Azur proposal PDFs is printed in numeric or textual (spelled-out) day format.', 'Checked identically in core/modules/propale/doc/pdf_cyan.modules.php:1104 and core/modules/propale/doc/pdf_azur.modules.php:951, both setting $displaydate to ''daytext'' if true, else ''day''.', 'Enabling it changes the delivery date format on these PDFs from a plain day format to a textual day format.', 'Boolean: true/1 selects ''daytext'' format; false/unset selects plain ''day'' format.', 0, 0, NULL, 1, '9f066de1a2ec9b0db213da8b1771c66786dfd8e8378f5464bb86797327f822dd', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:1104|check|if (getDolGlobalString(''MAIN_PDF_DELIVERY_DATE_TEXT'')) {", "core/modules/propale/doc/pdf_azur.modules.php:951|check|if (getDolGlobalString(''MAIN_PDF_DELIVERY_DATE_TEXT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_DISABLESOURCEDETAILS', 'bool', NULL, 'core', 'When set, hides the source (issuer) company''s phone, mobile, fax, email and web address on generated PDF documents.', 'Checked in core/lib/pdf.lib.php:477 (function pdf_build_address); when true, the phone/mobile/fax/email/url block for the source company is skipped entirely.', 'Removes phone, phone_mobile, fax, email and url lines from the source company address block on invoices/orders/etc.', 'Boolean-like (set/unset); when set, source contact details are omitted', 1, 0, NULL, 1, '23b998bdac19acbc67a58f92121504c5f6a90f6a2debe5229186b6cf283ed8cf', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:477|check|if (!getDolGlobalString(''MAIN_PDF_DISABLESOURCEDETAILS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_DISABLE_COL_HEAD_TITLE', 'bool', NULL, 'core', 'Disables printing of column header titles in the line items table of generated PDF documents.', 'Read in 20 PDF generation modules; used as $hidetop = getDolGlobalInt(''MAIN_PDF_DISABLE_COL_HEAD_TITLE'') (e.g. core/modules/commande/doc/pdf_eratosthene.modules.php:202) and as a boolean check to skip header rendering.', 'Enabling this suppresses column titles on the line items table in all affected PDF document types.', '0 or unset = column headers shown; 1 = column headers hidden.', 1, 0, NULL, 1, '359115f15f53b27aa55748869aa2b3f35ad3b2c63312ee69c72f2019dc55958e', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/commande/doc/pdf_eratosthene.modules.php:202|read|$hidetop = getDolGlobalInt(''MAIN_PDF_DISABLE_COL_HEAD_TITLE'');", "core/modules/propale/doc/pdf_cyan.modules.php:195|read|$hidetop = getDolGlobalInt(''MAIN_PDF_DISABLE_COL_HEAD_TITLE'');", "core/modules/facture/doc/pdf_octopus.modules.php:303|check|if (getDolGlobalString(''MAIN_PDF_DISABLE_COL_HEAD_TITLE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_DONOTREPEAT_HEAD', 'string', NULL, 'core', 'Hidden option that prevents the PDF page header from being repeated on every page of generated documents.', 'Checked with getDolGlobalInt/getDolGlobalString(''MAIN_PDF_DONOTREPEAT_HEAD'') across 182 occurrences in PDF model templates, e.g. modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:385/429/487/509/779 and recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:331/375/433.', 'When enabled, the _pagehead() call that draws the repeated header is skipped on subsequent pages of the PDF.', NULL, 1, 0, NULL, 1, 'd65388e6ad4a61aac8301c20aad668e713ae2c0891dd448b24182900500907f9', 'v2', '2026-07-24T06:41:12+00:00', '["core/modules/accountancy/doc/pdf_bookkeeping.modules.php:370|//if (!getDolGlobalInt(''MAIN_PDF_DONOTREPEAT_HEAD'')) $this->_pagehead($pdf, $object, 0, $outputlangs);", "modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:385|check|if (!getDolGlobalInt(''MAIN_PDF_DONOTREPEAT_HEAD'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_ENABLE_COL_HEAD_TITLE_REPEAT', 'bool', NULL, 'core', 'When set, repeats column header titles on each page of multi-page PDF documents.', 'Checked in five locations across pdf_eratosthene.modules.php, pdf_cyan.modules.php, and pdf_sponge.modules.php. Two checks guard the initial header rendering and three guard repeated header rendering on subsequent pages.', 'Enabling this causes column headers to be re-drawn at the top of every page in multi-page PDFs. Disabling (or leaving unset) prints column headers only on the first page.', '0 or unset = column headers printed once; non-zero = column headers repeated on each PDF page.', 1, 0, NULL, 1, '2c72b0f16abaf769795f7ae4414736739f4c98bc76e012aed486b1bdc2a73f6b', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_eratosthene.modules.php:373|if (!$hidetop && getDolGlobalInt(''MAIN_PDF_ENABLE_COL_HEAD_TITLE_REPEAT'')) {", "pdf_cyan.modules.php:362|if (!$hidetop && getDolGlobalInt(''MAIN_PDF_ENABLE_COL_HEAD_TITLE_REPEAT'')) {", "pdf_eratosthene.modules.php:862|if (getDolGlobalInt(''MAIN_PDF_ENABLE_COL_HEAD_TITLE_REPEAT'')) {", "pdf_sponge.modules.php:1048|if (getDolGlobalInt(''MAIN_PDF_ENABLE_COL_HEAD_TITLE_REPEAT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_FORCE_FONT', 'string', NULL, 'core', 'Forces a specific font name to be used for all PDF generation instead of the language-driven default.', 'Checked and read in core/lib/pdf.lib.php:275-276, function pdf_getPDFFont(); when set it is returned immediately instead of falling back to Helvetica or the FONTFORPDF translation key.', 'Overrides the automatic font selection (Helvetica or a UTF8 font like DejaVuSans chosen per output language) for every PDF document.', 'Any TCPDF-supported font name string (e.g. ''DejaVuSans'', ''Helvetica'')', 1, 0, NULL, 1, '7c828bf92acf3a34e50b19fdcc4f092eea3e0ea1d1c0145e84bbbb8d092ac1c8', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:275|check|if (getDolGlobalString(''MAIN_PDF_FORCE_FONT'')) {", "core/lib/pdf.lib.php:276|read|return getDolGlobalString(''MAIN_PDF_FORCE_FONT'');", "core/lib/pdf.lib.php:279: $font = ''Helvetica''; // By default, for FPDI, or ISO language on TCPDF"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_FORCE_FONT_SIZE', 'string', NULL, 'core', 'Forces a specific base font size (in points) to be used for all PDF generation instead of the default size 10.', 'Checked and read in core/lib/pdf.lib.php:302-303, function pdf_getPDFFontSize(); overrides the default 10pt (or the FONTSIZEFORPDF translation value) when set.', 'Overrides the base font size used throughout generated PDF documents.', 'Integer point size (e.g. 10, 12)', 1, 0, NULL, 1, '2bd15698cda4c3b6572c503f372a864a96e0cd46eaaa3c016b13d12280c03b4c', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:302|check|if (getDolGlobalString(''MAIN_PDF_FORCE_FONT_SIZE'')) {", "core/lib/pdf.lib.php:303|read|$size = getDolGlobalString(''MAIN_PDF_FORCE_FONT_SIZE'');", "core/lib/pdf.lib.php:296: $size = 10; // By default, for FPDF or ISO language on TCPDF"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_FORMAT', 'string', NULL, 'core', 'Sets the default paper format (e.g. size) used to generate PDF documents.', 'Configured via admin/pdf.php:71 (dolibarr_set_const, admin UI) and read in core/lib/pdf.lib.php:91/98/102 by pdf_getFormat(), which uses it when mode isn''t ''auto''.', 'If set to a value other than ''auto'' (and mode isn''t ''auto''), this format is used directly instead of the automatic format-detection logic in pdf_getFormat().', NULL, 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'a3fb443291ae3378fdfda2410a431b1efe4ff1a2e345c136b1371b87ef2a7b4c', 'v2', '2026-07-24T06:41:12+00:00', '["core/lib/pdf.lib.php:98|check|if ($mode == ''auto'' || !getDolGlobalString(''MAIN_PDF_FORMAT'') || getDolGlobalString(''MAIN_PDF_FORMAT'') == ''auto'') {", "admin/pdf.php:71|write|dolibarr_set_const($db, \"MAIN_PDF_FORMAT\", GETPOST(\"MAIN_PDF_FORMAT\"), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_FRAME_CORNER_RADIUS', 'string', NULL, 'core', 'Sets the corner radius (in points) for frames and boxes in generated PDF documents.', 'Configured via admin/pdf.php:156 (write) and :540 (UI select). Read in 41 occurrences across all PDF module classes as $this->corner_radius. Defaults to 0 (square corners).', 'Changing this constant affects the corner rounding of all PDF document frames across all supported modules.', 'Integer in points (default: 0 = square corners); selectable values shown in admin/pdf.php', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '46f8d3f51a515857f286054e5ac98d095d725b184017496ac6c8101034d0e53f', 'v2', '2026-04-21T13:29:58+00:00', '["admin/pdf.php:156|write|dolibarr_set_const($db, \"MAIN_PDF_FRAME_CORNER_RADIUS\", GETPOSTINT(\"MAIN_PDF_FRAME_CORNER_RADIUS\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:540|read|print $form->selectarray(\"MAIN_PDF_FRAME_CORNER_RADIUS\", $arrval, getDolGlobalInt(''MAIN_PDF_FRAME_CORNER_RADIUS'', 0));", "core/modules/action/doc/pdf_standard_actions.class.php:160|read|$this->corner_radius = getDolGlobalInt(''MAIN_PDF_FRAME_CORNER_RADIUS'', 0);", "core/modules/asset/doc/pdf_standard_asset.modules.php:117|read|$this->corner_radius = getDolGlobalInt(''MAIN_PDF_FRAME_CORNER_RADIUS'', 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_FREETEXT_HEIGHT', 'string', NULL, 'core', 'Sets the height in millimetres reserved for free text output at the bottom of the last page of generated PDFs.', 'Read across 41 occurrences in PDF modules as: $heightforfreetext = getDolGlobalInt(''MAIN_PDF_FREETEXT_HEIGHT'', 5); // Height reserved to output the free text on last page.', 'Increasing this value reserves more vertical space for the free text zone; decreasing it reduces this space with a default of 5 mm.', 'Integer (millimetres). Default: 5.', 1, 0, NULL, 1, 'e9c7e2dd2e3b3e985e6a65e31389479d23fc29e3be72ce927061b848c7e1a083', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:348|read|$heightforfreetext = getDolGlobalInt(''MAIN_PDF_FREETEXT_HEIGHT'', 5); // Height reserved to output the free text on last page", "core/modules/contract/doc/pdf_strato.modules.php:227|read|$heightforfreetext = getDolGlobalInt(''MAIN_PDF_FREETEXT_HEIGHT'', 5); // Height reserved to output the free text on last page", "core/modules/expensereport/doc/pdf_standard_expensereport.modules.php:272|read|$heightforfreetext = getDolGlobalInt(''MAIN_PDF_FREETEXT_HEIGHT'', 5); // Height reserved to output the free text on last page"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_HIDE_CHQ_ADDRESS', 'bool', NULL, 'core', 'When set, suppresses the cheque/payment address block from generated PDF documents.', 'Checked across at least 16 occurrences in multiple PDF modules: pdf_eagle_proforma, pdf_einstein, pdf_eratosthene, pdf_octopus, and others, consistently guarding the rendering of a cheque address section.', 'Enabling this removes the cheque address block from all affected PDF types. Disabling (or leaving unset) causes the address block to be printed.', 'Empty/unset = show cheque address; any truthy value = hide cheque address.', 1, 0, NULL, 1, 'e5be54260918bc7f425ac9c835a4f4bd1a8171c5f1998194d13e24ebad96bae0', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_eagle_proforma.modules.php:984|if (!getDolGlobalString(''MAIN_PDF_HIDE_CHQ_ADDRESS'')) {", "pdf_einstein.modules.php:853|if (!getDolGlobalString(''MAIN_PDF_HIDE_CHQ_ADDRESS'')) {", "pdf_eratosthene.modules.php:1117|if (!getDolGlobalString(''MAIN_PDF_HIDE_CHQ_ADDRESS'')) {", "pdf_octopus.modules.php:1567|if (!getDolGlobalString(''MAIN_PDF_HIDE_CHQ_ADDRESS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_HIDE_CUSTOMER_ACCOUNTING_CODE', 'bool', NULL, 'core', 'Hides the customer accounting code from the recipient block in generated PDF documents.', 'Read via admin/pdf.php:570 (select UI) and checked in 12 locations including core/modules/contract/doc/pdf_strato.modules.php:738, core/modules/expedition/doc/pdf_rouget.modules.php:1005, and core/modules/facture/doc/pdf_octopus.modules.php:2171.', 'When enabled, the customer accounting code is not printed in the recipient section of PDFs across invoices, orders, contracts, and expedition documents.', '0 (show accounting code) or 1 (hide accounting code)', 0, 0, 'admin/pdf.php', 1, '5889a4ce9519d4fed507f981bb6be54a51eb26085ab58ad7fcfb8e049eed1446', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:570|read|print $form->selectarray(\"MAIN_PDF_HIDE_CUSTOMER_ACCOUNTING_CODE\", $arrval, getDolGlobalString(''MAIN_PDF_HIDE_CUSTOMER_ACCOUNTING_CODE''));", "core/modules/contract/doc/pdf_strato.modules.php:738|check|if (!getDolGlobalString(''MAIN_PDF_HIDE_CUSTOMER_ACCOUNTING_CODE'') && $object->thirdparty->code_compta_client) {", "core/modules/facture/doc/pdf_octopus.modules.php:2171|check|if (!getDolGlobalString(''MAIN_PDF_HIDE_CUSTOMER_ACCOUNTING_CODE'') && $object->thirdparty->code_compta_client) {", "core/modules/expedition/doc/pdf_rouget.modules.php:1005|check|if (!getDolGlobalString(''MAIN_PDF_HIDE_CUSTOMER_ACCOUNTING_CODE'') && !empty($object->thirdparty->code_compta_client)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_HIDE_CUSTOMER_CODE', 'bool', NULL, 'core', 'Hides the customer code from the recipient block in generated PDF documents.', 'Read via admin/pdf.php:559 (select UI) and checked in 12 locations including core/modules/contract/doc/pdf_strato.modules.php:731, core/modules/expedition/doc/pdf_rouget.modules.php:998, and core/modules/facture/doc/pdf_octopus.modules.php:2164.', 'When enabled, the customer code is not printed in the recipient section of PDFs across invoices, orders, contracts, and expedition documents.', '0 (show customer code) or 1 (hide customer code)', 0, 0, 'admin/pdf.php', 1, '0b918e25cd9e0279bad174d4fa9b4e6f8fa99010579c4c9bea4b48c169380dfb', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:559|read|print $form->selectarray(\"MAIN_PDF_HIDE_CUSTOMER_CODE\", $arrval, getDolGlobalString(''MAIN_PDF_HIDE_CUSTOMER_CODE''));", "core/modules/contract/doc/pdf_strato.modules.php:731|check|if (!getDolGlobalString(''MAIN_PDF_HIDE_CUSTOMER_CODE'') && $object->thirdparty->code_client) {", "core/modules/facture/doc/pdf_octopus.modules.php:2164|check|if (!getDolGlobalString(''MAIN_PDF_HIDE_CUSTOMER_CODE'') && $object->thirdparty->code_client) {", "core/modules/expedition/doc/pdf_rouget.modules.php:998|check|if (!getDolGlobalString(''MAIN_PDF_HIDE_CUSTOMER_CODE'') && !empty($object->thirdparty->code_client)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_HIDE_SENDER_NAME', 'bool', NULL, 'core', 'Hides the sender company name from the sender block in generated PDF documents.', 'Written via admin/pdf.php:114 and rendered in the admin UI at admin/pdf.php:356 with selectyesno. Checked in 13 locations including core/modules/contract/doc/pdf_strato.modules.php:784 and core/modules/commande/doc/pdf_einstein.modules.php:1541.', 'When enabled, the company name is omitted from the sender section of PDFs while other sender details remain.', '0 (sender name shown) or 1 (sender name hidden)', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '3a806653d7f181f49435a9abaca296e000a6ca7e3525b825a52859a4f2658d5c', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:113  /*if (GETPOSTISSET(''MAIN_PDF_HIDE_SENDER_NAME'')) {", "admin/pdf.php:114|write|dolibarr_set_const($db, \"MAIN_PDF_HIDE_SENDER_NAME\", GETPOST(\"MAIN_PDF_HIDE_SENDER_NAME\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:356|read|print $form->selectyesno(''MAIN_PDF_HIDE_SENDER_NAME'', getDolGlobalInt(''MAIN_PDF_HIDE_SENDER_NAME''), 1);", "core/modules/contract/doc/pdf_strato.modules.php:784|check|if (!getDolGlobalString(''MAIN_PDF_HIDE_SENDER_NAME'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_MAIN_HIDE_SECOND_TAX', 'bool', NULL, 'admin', 'Hides the second tax column in PDF documents.', 'Configurable via the admin UI at admin/pdf.php (written at line 173, displayed at line 467). When not set, the second tax is shown; when set, core/lib/pdf.lib.php:2415 skips the second tax output.', 'Enabling this removes the second tax from PDFs; disabling it shows the second tax.', 'truthy (yes) = hide second tax; empty/no = show second tax', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '966214f12cfd302a39af76e1ff50e8b0f37bc8250055e39fb388792fbad43bca', 'v2', '2026-04-21T13:29:58+00:00', '["admin/pdf.php:173|write|dolibarr_set_const($db, \"MAIN_PDF_MAIN_HIDE_SECOND_TAX\", GETPOST(\"MAIN_PDF_MAIN_HIDE_SECOND_TAX\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:467|read|$text .= $form->selectyesno(''MAIN_PDF_MAIN_HIDE_SECOND_TAX'', getDolGlobalInt(''MAIN_PDF_MAIN_HIDE_SECOND_TAX''), 1);", "core/lib/pdf.lib.php:2415|check|if (!getDolGlobalString(''MAIN_PDF_MAIN_HIDE_SECOND_TAX'')) {"]', 'high', NULL);
