INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_NO_CUSTOMER_CODE', 'string', NULL, 'admin', 'Intended to suppress display of the customer code on generated PDF documents, but no code path reads it.', 'Written from admin/pdf.php:165 via dolibarr_set_const() when the admin saves the PDF/documents setup form. A repo-wide search found no read of this constant (no getDolGlobal*/conf->global read anywhere) and no corresponding lang string, so its effect on PDF generation could not be confirmed.', 'Exact behavior unclear from code alone: the value is persisted from the admin form but no reader of it was found in the source tree, so setting it may currently have no observable effect on generated PDFs.', 'Not specified in the available evidence (submitted raw via GETPOST, likely intended as a 0/1 toggle per its name).', 0, 0, 'admin/pdf.php', 1, '685dba5c57e0a0beed5335cdcd55c7f3b0d2512f3518dcf6f9fd3038dfb7043d', 'v2', '2026-07-24T07:05:23+00:00', '["admin/pdf.php:165|write|dolibarr_set_const($db, \"MAIN_PDF_NO_CUSTOMER_CODE\", GETPOST(\"MAIN_PDF_NO_CUSTOMER_CODE\"), ''chaine'', 0, '''', $conf->entity);"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_NO_RECIPENT_FRAME', 'string', NULL, 'core', 'Removes the recipient address frame from generated PDF documents.', 'Written via admin/pdf.php:110 and rendered in the admin UI at admin/pdf.php:419. Checked in 13 locations including core/modules/contract/doc/pdf_strato.modules.php:834, core/modules/expedition/doc/pdf_rouget.modules.php:1146, and core/modules/commande/doc/pdf_einstein.modules.php:1587.', 'When enabled, the recipient address box is omitted from all affected PDF documents.', '0 (recipient frame shown) or 1 (recipient frame hidden)', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '1bc7e9ea0af9a9de6e82602979fea22f60120042aa8c23529a5f971840f61d5e', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:110|write|dolibarr_set_const($db, \"MAIN_PDF_NO_RECIPENT_FRAME\", GETPOST(\"MAIN_PDF_NO_RECIPENT_FRAME\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:419|read|print $form->selectarray(\"MAIN_PDF_NO_RECIPENT_FRAME\", $arrval, getDolGlobalString(''MAIN_PDF_NO_RECIPENT_FRAME''));", "core/modules/contract/doc/pdf_strato.modules.php:834|check|if (!getDolGlobalString(''MAIN_PDF_NO_RECIPENT_FRAME'')) {", "core/modules/commande/doc/pdf_einstein.modules.php:1587|check|if (!getDolGlobalString(''MAIN_PDF_NO_RECIPENT_FRAME'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_NO_SENDER_FRAME', 'string', NULL, 'core', 'Removes the sender address frame from generated PDF documents.', 'Written via admin/pdf.php:107 and rendered in the admin UI at admin/pdf.php:410. Checked in 13 locations including core/modules/contract/doc/pdf_strato.modules.php:773, core/modules/expedition/doc/pdf_rouget.modules.php:1089, and core/modules/commande/doc/pdf_einstein.modules.php:1529.', 'When enabled, the sender address box is omitted from all affected PDF documents.', '0 (sender frame shown) or 1 (sender frame hidden)', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'f359cc86a8f5e8e830868eb981dd5eb27d6588c1dfa53984bd19168249ed32f6', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:107|write|dolibarr_set_const($db, \"MAIN_PDF_NO_SENDER_FRAME\", GETPOST(\"MAIN_PDF_NO_SENDER_FRAME\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:410|read|print $form->selectarray(\"MAIN_PDF_NO_SENDER_FRAME\", $arrval, getDolGlobalString(''MAIN_PDF_NO_SENDER_FRAME''));", "core/modules/contract/doc/pdf_strato.modules.php:773|check|if (!getDolGlobalString(''MAIN_PDF_NO_SENDER_FRAME'')) {", "core/modules/commande/doc/pdf_einstein.modules.php:1529|check|if (!getDolGlobalString(''MAIN_PDF_NO_SENDER_FRAME'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_PROPAL_USE_ELECTRONIC_SIGNING', 'bool', NULL, 'admin', 'Enables electronic signing support in proposal PDF documents.', 'Written in admin/pdf_other.php at line 87 and displayed as a select array at line 278. Checked in core/modules/propale/doc/pdf_cyan.modules.php at line 2057 and pdf_azur.modules.php at line 1879 to conditionally include signing metadata.', 'Enabling this constant causes proposal PDFs to include electronic signing fields or metadata. Disabling it omits those elements from generated PDFs.', 'Truthy value to enable electronic signing in proposal PDFs; empty/unset to disable.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, 'd711317f151d1e39517fc92e938be7dcbf619fc3d77a0f3f53157bb981027b19', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:87|write|dolibarr_set_const($db, \"MAIN_PDF_PROPAL_USE_ELECTRONIC_SIGNING\", GETPOST(\"MAIN_PDF_PROPAL_USE_ELECTRONIC_SIGNING\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/propale/doc/pdf_cyan.modules.php:2057|check|if (getDolGlobalString(''MAIN_PDF_PROPAL_USE_ELECTRONIC_SIGNING'')) {", "core/modules/propale/doc/pdf_azur.modules.php:1879|check|if (getDolGlobalString(''MAIN_PDF_PROPAL_USE_ELECTRONIC_SIGNING'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_RECEPTION_DISPLAY_AMOUNT_HT', 'string', NULL, 'core', 'Controls whether the unit price (amount excl. tax) column is displayed on reception PDFs.', 'Displayed as a select in admin/pdf_other.php at line 778. Checked in pdf_squille.modules.php at lines 98, 579, 786, and 883 to conditionally render the amount HT column.', 'Enabling this constant adds a unit price (HT) column to reception PDFs. Disabling it (or leaving unset) omits the price column from receptions.', 'Truthy string to display amount HT column; empty/unset to hide it.', 0, 0, 'admin/pdf_other.php', 1, '19f30dd01bd444f7343d30e2d46127f035c02f606ea9d4d13fae745767cdf779', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:778|read|print $form->selectarray(\"MAIN_PDF_RECEPTION_DISPLAY_AMOUNT_HT\", $arrval, getDolGlobalString(''MAIN_PDF_RECEPTION_DISPLAY_AMOUNT_HT''));", "core/modules/reception/doc/pdf_squille.modules.php:98|check|if (getDolGlobalString(''MAIN_PDF_RECEPTION_DISPLAY_AMOUNT_HT'')) {", "core/modules/reception/doc/pdf_squille.modules.php:579|check|if (getDolGlobalString(''MAIN_PDF_RECEPTION_DISPLAY_AMOUNT_HT'')) {", "core/modules/reception/doc/pdf_squille.modules.php:786|check|if (getDolGlobalString(''MAIN_PDF_RECEPTION_DISPLAY_AMOUNT_HT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_REMOVE_BREAK_BEFORE_COUNTRY', 'string', NULL, 'core', 'Suppresses the newline inserted before the country name in PDF address blocks.', 'Checked at core/lib/pdf.lib.php:573 and :575; when truthy, the newline separator before the country string is omitted, causing the country to appear on the same line as the preceding address element. No admin UI write is present.', 'Enabling this removes the line break before the country, compacting the address layout on PDF documents.', 'Truthy string (non-empty) = no newline before country; absent/empty = newline inserted before country.', 1, 0, NULL, 1, '4e59f31da4554e4ba39c0edeefdbccfd6d43e5bbbda658c108782c69cceb618f', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:573|read|$stringaddress .= (($stringaddress && !getDolGlobalString(''MAIN_PDF_REMOVE_BREAK_BEFORE_COUNTRY'')) ? \"\\n\" : '''')...", "core/lib/pdf.lib.php:575|read|$stringaddress .= (($stringaddress && !getDolGlobalString(''MAIN_PDF_REMOVE_BREAK_BEFORE_COUNTRY'')) ? \"\\n\" : '''')..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_SHOW_SOURCE_PHONE_MOBILE', 'bool', NULL, 'core', 'Adds the source (issuer) company''s mobile phone number to the address block on generated PDF documents.', 'Checked in core/lib/pdf.lib.php:483 (function pdf_build_address); only applies when MAIN_PDF_DISABLESOURCEDETAILS is not set and $sourcecompany->phone_mobile is not empty.', 'Enables display of the source company''s mobile phone number line in the PDF address block, in addition to the landline phone if present.', 'Boolean-like (set/unset); when set, mobile phone number is printed', 1, 0, NULL, 1, '876a9936464c005a0728b76245dfb013db55fc839b935a61d456522dc4d1177c', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:483|check|if ($sourcecompany->phone_mobile && getDolGlobalString(''MAIN_PDF_SHOW_SOURCE_PHONE_MOBILE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_TITLE_BACKGROUND_COLOR', 'string', NULL, 'core', 'Sets the background colour of column title rows in generated PDF documents as a comma-separated RGB value.', 'Checked across 71 occurrences; code comments across multiple modules show the expected format: //$conf->global->MAIN_PDF_TITLE_BACKGROUND_COLOR=''230,230,230'';. No admin UI write is present.', 'Setting this value applies a background colour to column header rows in generated PDFs; leaving it unset uses no background colour.', 'String in ''R,G,B'' format (e.g. ''230,230,230''); empty or unset = no background colour.', 1, 0, NULL, 1, '56770bf0c6e29fa61bbc295b2fcc1e63db86fc322af103444cef48fe05ac8bb0', 'v2', '2026-04-21T11:16:15+00:00', '["core/modules/product/doc/pdf_standard.modules.php:646  //$conf->global->MAIN_PDF_TITLE_BACKGROUND_COLOR=''230,230,230'';", "core/modules/stock/doc/pdf_standard_stock.modules.php:648  //$conf->global->MAIN_PDF_TITLE_BACKGROUND_COLOR=''230,230,230'';", "recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:700|check|if (getDolGlobalString(''MAIN_PDF_TITLE_BACKGROUND_COLOR'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_TITLE_TEXT_COLOR', 'string', NULL, 'core', 'Sets the RGB color for title text in proposal PDF documents generated by the cyan template.', 'Checked and read in pdf_cyan.modules.php at lines 1659, 1660, and 1666. The value is parsed with explode('','', ...) to extract RGB components, applied to title text rendering. No admin UI write is present.', 'Setting this constant overrides the default title text color in the cyan proposal PDF template. Leaving it unset causes the template to use its built-in default color.', 'A comma-separated RGB string (e.g. ''255,0,0''); empty or unset = default color used.', 1, 0, NULL, 1, '7d641860601add5e8d845d7d7d689116eae4c08676b15400bf6c7d9fc6304377', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:1659|check|if (getDolGlobalString(''MAIN_PDF_TITLE_TEXT_COLOR'')) {", "core/modules/propale/doc/pdf_cyan.modules.php:1660|read|$arrayColorTextTitle = explode('','', getDolGlobalString(''MAIN_PDF_TITLE_TEXT_COLOR''));", "core/modules/propale/doc/pdf_cyan.modules.php:1666|check|if (getDolGlobalString(''MAIN_PDF_TITLE_TEXT_COLOR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_USE_ISO_LOCATION', 'bool', NULL, 'core', 'Toggles ISO-style positioning/layout (e.g. recipient box width and position) in generated PDF document templates.', 'Configured via admin/pdf.php:162 (dolibarr_set_const, admin UI with selectyesno at admin/pdf.php:439) and used across 67 occurrences to adjust coordinates, e.g. modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:1097/1105/1158.', 'Enabling it changes vertical position and width values (e.g. 92 vs 82/100, or a shifted posy) used to draw the recipient address box and related elements in PDF templates.', NULL, 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '57bb5d1f673a245bf49cf8dedd4a5dddbb0b9f503c6a9b74a7cccda31a3fb108', 'v2', '2026-07-24T06:41:12+00:00', '["modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:1105|read|$widthrecbox = getDolGlobalInt(''MAIN_PDF_USE_ISO_LOCATION'') ? 92 : 82;", "admin/pdf.php:439|read|print $form->selectyesno(''MAIN_PDF_USE_ISO_LOCATION'', getDolGlobalInt(''MAIN_PDF_USE_ISO_LOCATION''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PDF_USE_LARGE_LOGO', 'bool', NULL, 'core', 'Switches the company logo in PDF document headers to a larger version.', 'Checked across 20 occurrences in PDF generation modules using !getDolGlobalInt(''MAIN_PDF_USE_LARGE_LOGO'') to choose between standard and large logo rendering paths. No admin UI write is present.', 'Enabling this causes PDF modules to use the larger logo variant in document headers.', '0 or unset = standard logo; 1 = large logo.', 1, 0, NULL, 1, '2152118a73a87ac7fdcd78ee728d130ee314b816d3542e5f4d11eff78fdd72df', 'v2', '2026-04-21T11:16:15+00:00', '["recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:762|check|if (!getDolGlobalInt(''MAIN_PDF_USE_LARGE_LOGO'')) {", "core/modules/commande/doc/pdf_einstein.modules.php:1387|check|if (!getDolGlobalInt(''MAIN_PDF_USE_LARGE_LOGO'')) {", "core/modules/expedition/doc/pdf_rouget.modules.php:952|check|if (!getDolGlobalInt(''MAIN_PDF_USE_LARGE_LOGO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PHONE_SEPAR', 'string', NULL, 'core', 'Sets a custom separator character inserted between phone number segments in display output.', 'Checked and read in core/lib/functions.lib.php:4844-4845; when set, the separator string is used to format phone numbers. No admin UI write detected.', 'Changing this value alters the visual formatting of phone numbers throughout the application. Without it, the default phone number format is used.', 'Any string separator character or sequence (e.g., ''.'', ''-'', '' '').', 1, 0, NULL, 1, '1bfc7907692c68defb691567e976c6ea8b38e0ff1dbbaa918e524e265802c797', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:4844|check|if (getDolGlobalString(''MAIN_PHONE_SEPAR'')) {", "core/lib/functions.lib.php:4845|read|$separ = getDolGlobalString(''MAIN_PHONE_SEPAR'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_POPUP_CALENDAR', 'string', NULL, 'core', 'Selects the calendar/datepicker widget type used for date input fields throughout the application.', 'Read at core/class/html.form.class.php:7831. The comment at :7828 says ''You can set MAIN_POPUP_CALENDAR to "eldy" or "jquery"''. When unset or set to ''eldy'', jQuery datepicker is used; when set to ''none'', no popup is shown (javascript check at :7830). Any other value is used directly.', 'Setting to ''none'' disables the popup calendar on all date fields. Setting to ''eldy'' or leaving unset uses jQuery. Changing this affects UX on all date inputs across the application.', 'You can set MAIN_POPUP_CALENDAR to ''eldy'' or ''jquery''; ''none'' = no popup; unset or ''eldy'' = use jQuery datepicker.', 1, 0, NULL, 1, 'ba45c390a796fa297c925dbd5e515ba12d74ad84d76d1c0d736912b6d50ef28d', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:7828  // You can set MAIN_POPUP_CALENDAR to ''eldy'' or ''jquery''", "core/class/html.form.class.php:7830|check|if (!empty($conf->use_javascript_ajax) && (!getDolGlobalString(''MAIN_POPUP_CALENDAR'') || getDolGlobalString(''MAIN_POPUP_CALENDAR'') != \"none\")) {", "core/class/html.form.class.php:7831|read|$usecalendar = ((!getDolGlobalString(''MAIN_POPUP_CALENDAR'') || getDolGlobalString(''MAIN_POPUP_CALENDAR'') == ''eldy'') ? ''jquery'' : getDolGlobalString(\"MAIN_POPUP_CALENDAR\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_POPUP_CALENDAR_ON_FOCUS', 'string', NULL, 'core', 'Controls whether the jQuery UI datepicker calendar is triggered on field focus rather than only via its calendar button.', 'Checked in Form::select_date() in core/class/html.form.class.php:8475; when empty/false, the datepicker is configured with showOn:''button'' and a dedicated buttonImage, i.e. the calendar only opens via the button, not on focus.', 'Setting it to a truthy value removes the showOn:''button''/buttonImage configuration, so the datepicker''s default focus-triggered popup behavior applies instead of button-only triggering.', 'Boolean-like: empty/unset (default) forces button-only opening (showOn:''button''); truthy value skips that override.', 1, 0, NULL, 1, '1b1dfc09c9d4dcc5acf6db38bfec77425853b3f6abcd1c96fa415a782ac11909', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:8475|check|if (!getDolGlobalString(''MAIN_POPUP_CALENDAR_ON_FOCUS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PRINT_DISABLELINK', 'bool', NULL, 'core', 'Disables the ''print this page'' link/icon shown in the top-right menu.', 'In main.inc.php:2340, combined with MAIN_OPTIMIZEFORTEXTBROWSER, the print link (optioncss=print) is only rendered when both are falsy.', 'Setting it removes the print-page shortcut link from the UI header.', 'Boolean-like: truthy hides the print link; also hidden if MAIN_OPTIMIZEFORTEXTBROWSER is set.', 0, 0, NULL, 1, '1122b5724d50271e0d7782244b990a3ee11c3d8b90b67ea82792dcab42cf0c83', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:2340|check|if (!getDolGlobalString(''MAIN_PRINT_DISABLELINK'') && !getDolGlobalString(''MAIN_OPTIMIZEFORTEXTBROWSER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PRODUCT_DISABLE_CUSTOMCOUNTRYCODE', 'bool', NULL, 'compta', 'Suppresses display of a product''s customs code and country of origin on document line forms.', 'When unset, reception/card.php:1018, compta/facture/card.php:2691, commande/card.php:1306, comm/propal/card.php:1569, expedition/card.php:1281, compta/facture/card-rec.php:695, and fourn/facture/card-rec.php:632 display the product''s customcode/country_code. Setting this constant hides that information. No admin UI write path exists.', 'Enabling this constant hides customs tariff code and country-of-origin fields on all document line forms; disabling it shows those fields when the product has a customcode or country_code set.', 'Truthy string/bool=customs info hidden, empty/0=customs info shown', 1, 0, NULL, 1, 'f4309a08eddf5f741943fc599d230488e483116f82a8ea4a02cd257cc631ac7d', 'v2', '2026-04-21T11:16:15+00:00', '["reception/card.php:1018|check|if (!getDolGlobalString(''MAIN_PRODUCT_DISABLE_CUSTOMCOUNTRYCODE'') && (!empty($prod->customcode) || !empty($prod->country_code))) {", "compta/facture/card.php:2691|check|if (!getDolGlobalString(''MAIN_PRODUCT_DISABLE_CUSTOMCOUNTRYCODE'') && (!empty($prod->customcode) || !empty($prod->country_code))) {", "commande/card.php:1306|check|if (!getDolGlobalString(''MAIN_PRODUCT_DISABLE_CUSTOMCOUNTRYCODE'') && (!empty($prod->customcode) || !empty($prod->country_code))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PRODUCT_FORCE_INDEX', 'string', NULL, 'core', 'Names the MySQL index to force via USE INDEX(...) on the product search query, when MAIN_SEARCH_PRODUCT_FORCE_INDEX is enabled.', 'core/class/html.form.class.php:3699: `$sql .= " USE INDEX (" . $this->db->sanitize(getDolGlobalString(''MAIN_PRODUCT_FORCE_INDEX'')) . ")";` — the value is sanitized and directly injected as the index name in the SQL USE INDEX clause. It only takes effect when MAIN_SEARCH_PRODUCT_FORCE_INDEX is also truthy (see companion constant).', 'Setting this to a valid index name on the llx_product table forces MySQL to use that specific index for the product search query when MAIN_SEARCH_PRODUCT_FORCE_INDEX is enabled; an invalid/non-existent index name will cause the SQL query to fail.', 'String: name of an existing MySQL index on the product table (e.g. ''PRIMARY'' or a named index); only used if MAIN_SEARCH_PRODUCT_FORCE_INDEX is truthy.', 1, 0, NULL, 1, '4f56831d5c7b63da15528f0682b01d078ea14778224c885220b75de69b064d4f', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:3699: $sql .= \" USE INDEX (\" . $this->db->sanitize(getDolGlobalString(''MAIN_PRODUCT_FORCE_INDEX'')) . \")\";", "core/class/html.form.class.php:3698: if (getDolGlobalString(''MAIN_SEARCH_PRODUCT_FORCE_INDEX'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PRODUCT_PERENTITY_SHARED', 'string', NULL, 'accountancy', 'Controls whether product accounting account fields are shared across entities (multi-company) or kept per-entity.', 'Checked with getDolGlobalString(''MAIN_PRODUCT_PERENTITY_SHARED'') in accountancy/admin/index.php:563, accountancy/admin/productaccount.php (multiple lines), and product/class/product.class.php:1233, with admin UI at accountancy/admin/productaccount.php and accountancy/admin/index.php.', 'When enabled, queries and forms use the shared ''p.'' product accounting fields instead of the per-entity ''ppe.'' fields, per accountancy/admin/productaccount.php:356/651.', NULL, 0, 0, 'accountancy/admin/index.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php|accountancy/admin/productaccount.php', 1, '06471d2282b4a28202666fcfb151f41bf447550a0ca182e9ae145fc345b1c07c', 'v2', '2026-07-24T06:41:12+00:00', '["accountancy/admin/productaccount.php:356|read|$sql .= natural_search((!getDolGlobalString(''MAIN_PRODUCT_PERENTITY_SHARED'') ? \"p.\" : \"ppe.\") . $db->sanitize($accountancy_field_name), $search_current_account);", "product/inventory/inventory.php:266|// MULTICOMPANY_PMP_PER_ENTITY_ENABLED are both set. MAIN_PRODUCT_PERENTITY_SHARED"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PRODUCT_REF_NOT_EDITABLE', 'string', NULL, 'product', 'Makes the product reference (ref) field read-only when editing a product.', 'Checked in product/card.php:2079: if set, the ref input on the edit form is rendered readonly with the existing $object->ref value instead of an editable GETPOST-backed field.', 'When set, users can no longer change a product''s reference from the edit form (input has readonly="true").', 'Boolean: truthy makes ref read-only; falsy (default) leaves ref editable.', 0, 0, NULL, 1, '4b53e4e2eca907339613ed9a373d9d746440fb64e73524178974ecf25e571190', 'v2', '2026-07-24T07:05:23+00:00', '["product/card.php:2079|if (!getDolGlobalString(''MAIN_PRODUCT_REF_NOT_EDITABLE'')) {"]', 'low', NULL);
