INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROFID1_IN_SOURCE_ADDRESS', 'string', NULL, 'core', 'Adds the source (issuer) company''s professional ID 1 (idprof1) to the source address block on generated PDF documents.', 'Checked in core/lib/pdf.lib.php:507 (function pdf_build_address, mode ''source''); when set and $sourcecompany->idprof1 is not empty, an idprof1 line is appended using the localized ProfId1 label.', 'Enables display of the issuing company''s first professional identifier (e.g. SIREN in France) on PDF documents.', 'Boolean-like (set/unset); when set, source idprof1 is printed', 1, 0, NULL, 1, '5d3548deba914b68cb0e350893a43f5b59c34958b4b4b8bb7b27111146d4a8ba', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:507|check|if (getDolGlobalString(''MAIN_PROFID1_IN_SOURCE_ADDRESS'') && !empty($sourcecompany->idprof1)) {"]', 'medium', NULL);
