INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROFID_MAXLENGTH_PLUS', 'string', NULL, 'core', 'Adds extra characters to the computed max input length of the professional ID (SIREN/SIRET/idprof) field on the thirdparty form.', 'In core/class/html.formcompany.class.php:1019, the base max length is computed per idprof type (formlength, e.g. 5, 12, 32 digits) and then MAIN_PROFID_MAXLENGTH_PLUS is added: `$maxlength += getDolGlobalInt("MAIN_PROFID_MAXLENGTH_PLUS");`. This lets an admin widen the input field beyond the country-specific default (used, for example, when a custom prof-id format needs more characters than the built-in limit).', 'Increasing the value only widens the HTML input maxlength attribute for professional ID fields; it does not change validation logic elsewhere.', 'Integer number of extra characters allowed, added to the type-specific base length (e.g. 5/12/32 depending on idprof).', 1, 0, NULL, 1, '7c9eab3729424b323c9efcaa0308da0feae2df5b8d9c04370b52fd3e727d96f5', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formcompany.class.php:1019: $maxlength += getDolGlobalInt(\"MAIN_PROFID_MAXLENGTH_PLUS\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROPAGATE_CONTACTS_FROM_ORIGIN', 'string', NULL, 'compta', 'Enables automatic propagation of contacts from an origin document to a newly created document.', 'Checked in 6 locations: compta/facture/class/facture.class.php:819, compta/facture/card.php:2088, commande/card.php:553, contrat/class/contrat.class.php:1142, expedition/class/expedition.class.php:683, and commande/class/commande.class.php:1213. Each site copies contacts from the origin object when this constant is set. No admin UI is present.', 'Enabling this causes contacts associated with an origin document (order, proposal, etc.) to be automatically linked to the newly created document (invoice, contract, shipment, etc.).', '0 or unset = contacts not propagated; truthy value = contacts from origin document are copied to the new document.', 1, 0, NULL, 1, 'd20056caabb87d81919ecabfe90f72dafc728316942c3f3475c3a2be3cf7f5f7', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/class/facture.class.php:819|check|if (!$error && $this->id && getDolGlobalString(''MAIN_PROPAGATE_CONTACTS_FROM_ORIGIN'') && (!empty($this->origin_type) || !empty($this->origin)) && !empty($this->origin_id)) {", "commande/card.php:553|check|if (getDolGlobalString(''MAIN_PROPAGATE_CONTACTS_FROM_ORIGIN'')) {", "contrat/class/contrat.class.php:1142|check|if (!$error && $this->id && getDolGlobalString(''MAIN_PROPAGATE_CONTACTS_FROM_ORIGIN'') && !empty($this->origin) && !empty($this->origin_id)) {", "commande/class/commande.class.php:1213|check|if (!$error && getDolGlobalString(''MAIN_PROPAGATE_CONTACTS_FROM_ORIGIN'') && !empty($this->origin) && !empty($this->origin_id)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROPAL_CHOOSE_ODT_DOCUMENT', 'string', NULL, 'core', 'When set to a value greater than 0, enables the user to choose an ODT document template at generation time for proposals, users, and user groups.', 'Read as integer via getDolGlobalInt in core/modules/propale/doc/doc_generic_proposal_odt.modules.php:127, core/modules/user/doc/doc_generic_user_odt.modules.php:113, and core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:114. The boolean $odtChosen controls whether template selection UI is shown.', 'Setting to a positive integer enables runtime ODT template selection for the covered document types. Setting to 0 or leaving unset uses the default preconfigured template.', 'Integer > 0 = enable ODT template chooser; 0 or unset = use default template.', 1, 0, NULL, 1, '25c900d1ce6efc291de85f6e062fea5f9eee85867c26ddb477819380233a81cb', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/user/doc/doc_generic_user_odt.modules.php:113|read|$odtChosen = getDolGlobalInt(''MAIN_PROPAL_CHOOSE_ODT_DOCUMENT'') > 0;", "core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:114|read|$odtChosen = getDolGlobalInt(''MAIN_PROPAL_CHOOSE_ODT_DOCUMENT'') > 0;", "core/modules/propale/doc/doc_generic_proposal_odt.modules.php:127|read|$odtChosen = getDolGlobalInt(''MAIN_PROPAL_CHOOSE_ODT_DOCUMENT'') > 0;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROXY_HOST', 'string', NULL, 'admin', 'Stores the proxy server hostname used for outbound HTTP requests made by Dolibarr.', 'Configured via admin/proxy.php:69 (dolibarr_set_const, admin UI) and read in paypal/lib/paypalfunctions.lib.php:67, core/lib/geturl.lib.php:55, and core/lib/functions2.lib.php:2041.', 'When set, outbound requests (e.g. PayPal calls, generic URL fetches) are routed through this proxy host, provided proxy use is enabled.', NULL, 0, 0, 'admin/proxy.php|admin/proxy.php', 1, 'd4cadbc4b3159c142c68c64be846b41c3edb7b3bca56ab89413ebd3affd4cda0', 'v2', '2026-07-24T06:41:12+00:00', '["admin/proxy.php:69|write|$result += dolibarr_set_const($db, ''MAIN_PROXY_HOST'', GETPOST(\"MAIN_PROXY_HOST\"), ''chaine'', 0, '''', $conf->entity);", "core/lib/functions2.lib.php:2041|read|$proxyhost = (!$proxyuse ? false : getDolGlobalString(''MAIN_PROXY_HOST''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROXY_PASS', 'string', NULL, 'admin', 'Stores the proxy server password used for outbound HTTP requests made by Dolibarr.', 'Configured via admin/proxy.php:72 (dolibarr_set_const, admin UI, password input) and read in core/lib/functions2.lib.php:2044, paypal/lib/paypalfunctions.lib.php:70, and core/lib/geturl.lib.php:58.', 'When set, this password is used for proxy authentication on outbound requests, provided proxy use is enabled.', NULL, 0, 0, 'admin/proxy.php|admin/proxy.php', 1, '23a00dac74138baf199e0156061ab2790a6db71d7f4931a3dd1418beea81f8fe', 'v2', '2026-07-24T06:41:12+00:00', '["admin/proxy.php:72|write|$result += dolibarr_set_const($db, ''MAIN_PROXY_PASS'', GETPOST(\"MAIN_PROXY_PASS\"), ''chaine'', 0, '''', $conf->entity);", "core/lib/functions2.lib.php:2044|read|$proxypass = (!$proxyuse ? false : getDolGlobalString(''MAIN_PROXY_PASS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROXY_PORT', 'string', NULL, 'admin', 'Stores the proxy server port used for outbound HTTP requests made by Dolibarr.', 'Configured via admin/proxy.php:70 (dolibarr_set_const, admin UI) and read in paypal/lib/paypalfunctions.lib.php:68, core/lib/geturl.lib.php:56, and core/lib/functions2.lib.php:2042.', 'When set, outbound requests are routed to this proxy port, provided proxy use is enabled.', NULL, 0, 0, 'admin/proxy.php|admin/proxy.php', 1, '275715d07cc34c251abb20292c2f31501f617004d80d75a68a7dc9f2bcb13871', 'v2', '2026-07-24T06:41:12+00:00', '["admin/proxy.php:70|write|$result += dolibarr_set_const($db, ''MAIN_PROXY_PORT'', GETPOST(\"MAIN_PROXY_PORT\"), ''chaine'', 0, '''', $conf->entity);", "core/lib/functions2.lib.php:2042|read|$proxyport = (!$proxyuse ? false : getDolGlobalString(''MAIN_PROXY_PORT''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROXY_USE', 'string', NULL, 'admin', 'Master toggle that enables use of an HTTP proxy for outbound requests made by Dolibarr.', 'Configured via admin/proxy.php:68 (dolibarr_set_const, admin UI selectyesno at line 168) and read in core/lib/geturl.lib.php:54 and core/lib/functions2.lib.php:2040 as $proxyuse, and via getDolGlobalBool in paypal/lib/paypalfunctions.lib.php:71.', 'When enabled, MAIN_PROXY_HOST/PORT/USER/PASS are actually applied to outbound requests; when disabled, those proxy settings are ignored ($proxyhost/port/user set to false).', NULL, 0, 0, 'admin/proxy.php|admin/proxy.php', 1, 'ead1f9bf4881bb4c1139f85fc7259672520bd59979fa0e0788e4553723fd62bd', 'v2', '2026-07-24T06:41:12+00:00', '["admin/proxy.php:68|write|$result += dolibarr_set_const($db, ''MAIN_PROXY_USE'', GETPOST(\"MAIN_PROXY_USE\"), ''chaine'', 0, '''', $conf->entity);", "core/lib/functions2.lib.php:2040|read|$proxyuse = getDolGlobalString(''MAIN_PROXY_USE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PROXY_USER', 'string', NULL, 'admin', 'Stores the proxy server username used for outbound HTTP requests made by Dolibarr.', 'Configured via admin/proxy.php:71 (dolibarr_set_const, admin UI) and read in paypal/lib/paypalfunctions.lib.php:69, core/lib/functions2.lib.php:2043, and core/lib/geturl.lib.php:57.', 'When set, this username is used for proxy authentication on outbound requests, provided proxy use is enabled.', NULL, 0, 0, 'admin/proxy.php|admin/proxy.php', 1, 'd13f679d5464f728e7f31aee21b0207f7dc72575fd28cb541bedd022b68c8529', 'v2', '2026-07-24T06:41:12+00:00', '["admin/proxy.php:71|write|$result += dolibarr_set_const($db, ''MAIN_PROXY_USER'', GETPOST(\"MAIN_PROXY_USER\"), ''chaine'', 0, '''', $conf->entity);", "core/lib/functions2.lib.php:2043|read|$proxyuser = (!$proxyuse ? false : getDolGlobalString(''MAIN_PROXY_USER''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PUBLIC_NOTE_IN_ADDRESS', 'string', NULL, 'core', 'Adds the company''s public note to the address block (source or target) on generated PDF documents.', 'Checked in core/lib/pdf.lib.php:724 (function pdf_build_address); when set, note_public of the source company (mode ''source'') or target company (mode ''target''/''targetwithdetails'') is appended via dol_string_nohtmltag().', 'Enables display of the free-text public note field of the relevant thirdparty on PDF documents, stripped of HTML tags.', 'Boolean-like (set/unset); when set, note_public is printed for source and/or target address', 1, 0, NULL, 1, '2a4a00f1938b2b63c9104072f88f588ba580e0a390e0adbadfd39e2fde5856d3', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:724|check|if (getDolGlobalString(''MAIN_PUBLIC_NOTE_IN_ADDRESS'')) {", "core/lib/pdf.lib.php:725: if ($mode == ''source'' && !empty($sourcecompany->note_public)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_PURGE_ACCEPT_NBSECONDSOLD', 'string', NULL, 'admin', 'Enables an extra ''NbSecondsOld'' input field on the admin Purge page, letting the admin restrict purge to files older than N seconds.', 'Used in admin/tools/purge.php:134: `if (getDolGlobalInt(''MAIN_PURGE_ACCEPT_NBSECONDSOLD'')) { print ''NbSecondsOld = <input ... name="nbsecondsold" value="''.$nbsecondsold.''">''; }`. The value entered is later passed as $nbsecondsold to `$utils->purgeFiles($choice, $nbsecondsold)`.', 'When enabled, the Purge admin page exposes a field letting the admin restrict the purge/delete-all-files action to files older than a given age in seconds; when disabled the field (and that restriction) is not offered in the UI.', 'Boolean (getDolGlobalInt): 1/true shows the NbSecondsOld input field; 0/unset hides it.', 0, 0, 'admin/tools/purge.php', 1, 'a0bcb562d6f721d5c5786991d2f28bd96a2a250a2741879d25adb5d6d198fd61', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/purge.php:134: if (getDolGlobalInt(''MAIN_PURGE_ACCEPT_NBSECONDSOLD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_QUICKMEMO_SHOW_PAGE_OF_AGENDA', 'bool', NULL, 'quickmemo', 'Controls whether the Agenda/Events tab is shown on the QuickMemo card view.', 'Read in memoPrepareHead() (quickmemo/lib/quickmemo_memo.lib.php:40), same pattern as the other MAIN_QUICKMEMO_SHOW_PAGE_OF_* flags that toggle tabs on the memo card head.', 'Setting it enables an extra Agenda tab on the memo card; leaving it unset/0 hides that tab.', '0/unset = tab hidden (default); 1 = Agenda tab shown.', 0, 0, NULL, 1, '27cb2aa2122761d5baf9c2c3e0a743df32287350163c7b489f335a55f6669d41', 'v2', '2026-07-24T07:05:23+00:00', '["quickmemo/lib/quickmemo_memo.lib.php:40: $showtabofpageagenda = getDolGlobalInt(''MAIN_QUICKMEMO_SHOW_PAGE_OF_AGENDA'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_QUICKMEMO_SHOW_PAGE_OF_CONTACT', 'bool', NULL, 'quickmemo', 'Controls whether the Contacts tab is shown on the QuickMemo card view.', 'Read in memoPrepareHead() (quickmemo/lib/quickmemo_memo.lib.php:37), which builds the tab head array for a memo; when truthy it adds a ''Contacts'' tab linking to memo_contact.php.', 'Setting it enables an extra ''Contacts'' tab on the memo card; leaving it unset/0 hides that tab.', '0/unset = tab hidden (default); 1 = Contacts tab shown.', 0, 0, NULL, 1, '6a0afa1917807192fa60e00020ee3c0ce594bd61da608054587a5f6fcaf16693', 'v2', '2026-07-24T07:05:23+00:00', '["quickmemo/lib/quickmemo_memo.lib.php:37: $showtabofpagecontact = getDolGlobalInt(''MAIN_QUICKMEMO_SHOW_PAGE_OF_CONTACT'');", "quickmemo/lib/quickmemo_memo.lib.php:50-55: if ($showtabofpagecontact) { $head[$h][... ''Contacts'' ... ''contact'' }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_QUICKMEMO_SHOW_PAGE_OF_DOCUMENT', 'bool', NULL, 'quickmemo', 'Controls whether the Documents tab is shown on the QuickMemo card view.', 'Read in memoPrepareHead() (quickmemo/lib/quickmemo_memo.lib.php:39), same pattern as the other MAIN_QUICKMEMO_SHOW_PAGE_OF_* flags that toggle tabs on the memo card head.', 'Setting it enables an extra ''Documents'' tab on the memo card; leaving it unset/0 hides that tab.', '0/unset = tab hidden (default); 1 = Documents tab shown.', 0, 0, NULL, 1, 'd83596436a659e91348bbf092f6d1af6f0149db4c0fd6209a982facd5235fdf1', 'v2', '2026-07-24T07:05:23+00:00', '["quickmemo/lib/quickmemo_memo.lib.php:39: $showtabofpagedocument = getDolGlobalInt(''MAIN_QUICKMEMO_SHOW_PAGE_OF_DOCUMENT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_QUICKMEMO_SHOW_PAGE_OF_NOTE', 'bool', NULL, 'quickmemo', 'Controls whether the Notes tab is shown on the QuickMemo card view.', 'Read in memoPrepareHead() (quickmemo/lib/quickmemo_memo.lib.php:38); when truthy it adds a ''Notes'' tab (with a badge counting private/public notes) linking to memo_note.php.', 'Setting it enables an extra ''Notes'' tab on the memo card; leaving it unset/0 hides that tab.', '0/unset = tab hidden (default); 1 = Notes tab shown.', 0, 0, NULL, 1, '9fbbbd38ef13edfdd8455a4a1f995e89faf27706eaa0ba02b8971e2fa643f894', 'v2', '2026-07-24T07:05:23+00:00', '["quickmemo/lib/quickmemo_memo.lib.php:38: $showtabofpagenote = getDolGlobalInt(''MAIN_QUICKMEMO_SHOW_PAGE_OF_NOTE'');", "quickmemo/lib/quickmemo_memo.lib.php:57-70: if ($showtabofpagenote) { ... ''Notes'' ... }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_RECRUITMENT_CSS_URL', 'string', NULL, 'public', 'URL of a custom CSS stylesheet injected into the public recruitment pages.', 'Checked in public/recruitment/view.php:292 and public/recruitment/index.php:112; when set, the URL is used to build a `<link>` tag with a lang query parameter appended. No admin UI write path is present.', 'Setting this to a valid CSS URL applies a custom stylesheet to the public-facing recruitment list and job-view pages, overriding default styles.', 'Any valid CSS URL string', 1, 0, NULL, 1, '80306b60fc562b34947021e4af9374ef440b1775eb0164f162c5dcdf31c00789', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalString(''MAIN_RECRUITMENT_CSS_URL'')) {", "$head = ''<link rel=\"stylesheet\" type=\"text/css\" href=\"'' . getDolGlobalString(''MAIN_RECRUITMENT_CSS_URL'').''?lang=''.$langs->defaultlang.''\">''.\"\n\";", "public/recruitment/view.php:292|check", "public/recruitment/index.php:112|check"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_REMOTE_GITHUBREPO_CACHE_DELAY', 'string', NULL, 'admin', 'Sets the cache duration in seconds for GitHub repository data fetched by the remote store module.', 'Read in admin/remotestore/class/externalModules.class.php:178 as an integer with a default of 86400 (one day).', 'Increasing the value reduces API calls to GitHub; decreasing it causes more frequent refreshes of repository data.', 'Integer seconds, default 86400.', 0, 0, 'admin/remotestore/class/externalModules.class.php', 1, '1039d05a7622b9e227c729978ef42f2a127479e82dfa2e2e4197df86e5978205', 'v2', '2026-04-21T13:50:40+00:00', '["admin/remotestore/class/externalModules.class.php:178|read|$cachedelayforgithubrepo = getDolGlobalInt(''MAIN_REMOTE_GITHUBREPO_CACHE_DELAY'', 86400);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_REMOVE_DROPDOWN_CREATE_BUTTONS_ON_ORDER', 'string', NULL, 'commande', 'Disables the dropdown-style grouping of the ''Create'' action buttons on the sales order card and (via reuse) on the proposal card, showing them as separate buttons instead.', 'Read in commande/card.php:3620 and comm/propal/card.php:3735: "areDropdownButtons" => !getDolGlobalInt(''MAIN_REMOVE_DROPDOWN_CREATE_BUTTONS_ON_ORDER''), passed into $actionButtonsParameters for dolGetButtonAction rendering.', 'When enabled, the multiple ''Create X'' actions (invoice, purchase order, intervention, contract, etc.) are rendered as individual buttons instead of a single dropdown button, on both order and proposal cards.', 'Boolean: 1/true removes the dropdown grouping (areDropdownButtons becomes false).', 0, 0, NULL, 1, 'd86e82c69cd298f61b0f599d2512195ff6f6e92f0cd954fbb1dc7d1732efa309', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3620: \"areDropdownButtons\"\t=> !getDolGlobalInt(\"MAIN_REMOVE_DROPDOWN_CREATE_BUTTONS_ON_ORDER\")", "comm/propal/card.php:3735: \"areDropdownButtons\" => !getDolGlobalInt(\"MAIN_REMOVE_DROPDOWN_CREATE_BUTTONS_ON_ORDER\"),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_REMOVE_INSTALL_WARNING', 'string', NULL, 'index.php', 'Suppresses the post-installation security warning displayed on the Dolibarr home page.', 'Checked in index.php:130; when absent or falsy the install warning is displayed. Set to 1 automatically by install/step5.php:365 at the end of the installation wizard. No admin UI is present.', 'Setting this to 1 removes the install-directory warning from the home page; leaving it unset keeps the warning visible as a security reminder.', 'Integer: 1 = warning suppressed; 0 or unset = warning displayed.', 1, 0, NULL, 1, '7613ed94c18341e0149d082829cd238afec4088ec8f45f5ee6de600bfcea189b', 'v2', '2026-04-21T11:16:15+00:00', '["index.php:130|check|if (!getDolGlobalString(''MAIN_REMOVE_INSTALL_WARNING'')) {", "install/step5.php:365|write|$conf->global->MAIN_REMOVE_INSTALL_WARNING = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_REPEATTASKONEACHTAB', 'string', NULL, 'fourn', 'Displays agenda task widgets repeatedly on each tab of supplier order and commercial order cards.', 'When set together with the agenda module being enabled and the object being in status 1, fourn/card.php:1102 and comm/card.php:1817 render agenda task blocks per tab. A secondary check at fourn/card.php:1120 and comm/card.php:1833 also conditions task display on this constant.', 'Enabling this constant causes task blocks to appear on each card tab; disabling it suppresses that repetition.', 'Truthy value repeats task display on each tab; absent or falsy disables it.', 1, 0, NULL, 1, '06e48f64acf2fde190809dffca1fc598366c7a518e44f85ac120facc050ec993', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/card.php:1102|check|if (isModEnabled(''agenda'') && getDolGlobalString(''MAIN_REPEATTASKONEACHTAB'') && $object->status == 1) {", "comm/card.php:1817|check|if (isModEnabled(''agenda'') && getDolGlobalString(''MAIN_REPEATTASKONEACHTAB'') && $object->status == 1) {", "fourn/card.php:1120|check|if (getDolGlobalString(''MAIN_REPEATTASKONEACHTAB'')) {", "comm/card.php:1833|check|if (getDolGlobalString(''MAIN_REPEATTASKONEACHTAB'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_RESTRICTHTML_ONLY_VALID_HTML', 'string', NULL, 'admin', 'Enforces strict HTML validity checks on user-supplied HTML content during sanitization.', 'Managed via admin/system/security.php (read at lines 976, 1000; written at lines 979, 983, 1003, 1007). Checked in core/lib/functions.lib.php:9589 to apply strict HTML validation during the dol_htmlwithnojs sanitization pass. The security admin page tests compatibility of this setting before enabling.', 'Enabling this constant causes invalid HTML in user content to be rejected or sanitized more aggressively; disabling it allows lenient HTML through.', '0 or empty = HTML validity not strictly enforced; 1 = only valid HTML accepted during sanitization', 0, 0, 'admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php', 1, '06812979289cb14e8838e32139bfafb31d178df2627e6b7e80d4f4e8cad1c949', 'v2', '2026-04-21T13:29:58+00:00', '["admin/system/security.php:974  // Test compatibility of MAIN_RESTRICTHTML_ONLY_VALID_HTML", "admin/system/security.php:979|write|$conf->global->MAIN_RESTRICTHTML_ONLY_VALID_HTML = 1;", "core/lib/functions.lib.php:9589|check|if (!empty($out) && getDolGlobalInt(''MAIN_RESTRICTHTML_ONLY_VALID_HTML'') && $check != ''restricthtmlallowunvalid'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_RESTRICTHTML_ONLY_VALID_HTML_TIDY', 'string', NULL, 'admin', 'Enables the PHP Tidy extension to clean and validate HTML during content sanitization.', 'Managed via admin/system/security.php (read at lines 977, 995, 1001; written at lines 980, 984, 1004, 1008). Checked at core/lib/functions.lib.php:9702 during the sanitization pipeline when valid-HTML enforcement is active and link-script checks are not bypassed.', 'Enabling this constant invokes PHP Tidy on HTML content; if Tidy is unavailable the check will fail silently or produce errors.', '0 or empty = Tidy not used; 1 = PHP Tidy used to clean HTML during sanitization', 0, 0, 'admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php', 1, 'a0c1cb1980dab98260ce0f550a6e67929cae18cc3c14237b27049aa3ff413336', 'v2', '2026-04-21T13:29:58+00:00', '["admin/system/security.php:998  // Test compatibility of MAIN_RESTRICTHTML_ONLY_VALID_HTML_TIDY", "admin/system/security.php:1004|write|$conf->global->MAIN_RESTRICTHTML_ONLY_VALID_HTML_TIDY = 1;", "core/lib/functions.lib.php:9702|check|if (!empty($out) && getDolGlobalInt(''MAIN_RESTRICTHTML_ONLY_VALID_HTML_TIDY'') && !in_array($check, array(''restricthtmlallowunvalid'', ''restricthtmlallowlinkscript'')) && $outishtml)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_RESTRICTHTML_REMOVE_ALSO_BAD_ATTRIBUTES', 'string', NULL, 'admin', 'Enables removal of disallowed HTML attributes in addition to disallowed tags during HTML sanitization.', 'The comment at core/lib/functions.lib.php:9313 states ''This method is used for example by dol_htmlwithnojs() when option MAIN_RESTRICTHTML_REMOVE_ALSO_BAD_ATTRIBUTES is set to 1.'' Checked at line 9788. Also managed via admin/system/security.php (read, written, and displayed there).', 'Setting this to 1 makes the HTML sanitizer strip unsafe attributes (e.g. event handlers) from allowed tags; without it only disallowed tags are removed.', '0 or empty = only bad tags removed; 1 = bad attributes also removed during HTML sanitization', 0, 0, 'admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php', 1, 'da5e9ea6122c8b5fc574ff9c7b07c22177516e5d3742ea151de0573013c14a57', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:9313  *  This method is used for example by dol_htmlwithnojs() when option MAIN_RESTRICTHTML_REMOVE_ALSO_BAD_ATTRIBUTES is set to 1.", "core/lib/functions.lib.php:9788|check|if (getDolGlobalString(''MAIN_RESTRICTHTML_REMOVE_ALSO_BAD_ATTRIBUTES'')) {", "admin/system/security.php:978|write|$conf->global->MAIN_RESTRICTHTML_REMOVE_ALSO_BAD_ATTRIBUTES = 0;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ROUNDING_RULE_TOT', 'string', NULL, 'core', 'Sets the rounding rule applied to invoice/order totals during price calculation.', 'Configured via admin/limits.php (read at lines 191 and 222). Used in core/lib/price.lib.php: checked at line 388, saved/restored at lines 409 and 429 when a foreign rounding rule is temporarily applied, and logged at line 457. A comment in margin/lib/margins.lib.php:140 notes: ''Also we must not apply rounding on non decimal rule defined by option MAIN_ROUNDING_RULE_TOT''.', 'Changing this rule alters how line and total amounts are rounded in price calculations; switching between rules can cause small differences in computed totals.', 'Rounding rule identifier string; empty = no special rounding rule.', 0, 0, 'admin/limits.php|admin/limits.php', 1, '3ac8faf5ddd29b5e49e603f8a8d3f563ea46e660671f35afe3640763a7caac66', 'v2', '2026-04-21T13:50:40+00:00', '["margin/lib/margins.lib.php:140  // Also we must not apply rounding on non decimal rule defined by option MAIN_ROUNDING_RULE_TOT", "core/lib/price.lib.php:388|check|if (getDolGlobalString(''MAIN_ROUNDING_RULE_TOT'')) {", "core/lib/price.lib.php:409|read|$savMAIN_ROUNDING_RULE_TOT = getDolGlobalString(''MAIN_ROUNDING_RULE_TOT'');", "core/lib/price.lib.php:457|read|dol_syslog(''Price.lib::calcul_price_total MAIN_ROUNDING_RULE_TOT=''.getDolGlobalString(''MAIN_ROUNDING_RULE_TOT'')..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_ROUNDOFTOTAL_NOT_TOTALOFROUND_SUPPLIER', 'string', NULL, 'fourn', 'Selects the VAT/total calculation rounding rule for supplier invoices: round-the-total vs sum-of-rounded-lines.', 'Read in fourn/facture/card.php:3713, setting $calculationrule to ''roundoftotal'' when the constant is set (truthy), otherwise ''totalofround'' (the default).', 'Changing it switches how the displayed/recalculated VAT amount is computed for a supplier invoice: ''totalofround'' sums per-line rounded amounts, ''roundoftotal'' rounds the grand total instead.', 'Bool: unset/false = ''totalofround'' (default); truthy = ''roundoftotal''.', 1, 0, NULL, 1, '08f55f26d0374e10573545e5d8ab8cb014465d3a97da7951b8e8f1948f132b1d', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:3713|read|$calculationrule = (!getDolGlobalString(''MAIN_ROUNDOFTOTAL_NOT_TOTALOFROUND_SUPPLIER'') ? ''totalofround'' : ''roundoftotal'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SALETAX_AUTOSWITCH_I_CS_FOR_INDIA', 'string', NULL, 'core', 'Enables automatic switching between IGST and CGST/SGST tax types for Indian sellers based on buyer location.', 'Checked in core/lib/functions.lib.php:8656 when the seller country code is ''IN''; exposed as a boolean to JavaScript in core/tpl/objectline_create.tpl.php:687.', 'When enabled and the seller is Indian, the system switches between integrated and central/state GST tax codes automatically based on transaction parameters.', 'Truthy boolean = IGST/CGST-SGST auto-switch active; false/unset = no automatic switching.', 1, 0, NULL, 1, '7aa2d307f11d301aaec0b5b598266a7f23b6697acbbccd7d748909c9e39d3d2f', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/functions.lib.php:8656|check|if ($seller_country_code == ''IN'' && getDolGlobalString(''MAIN_SALETAX_AUTOSWITCH_I_CS_FOR_INDIA'')) {", "core/tpl/objectline_create.tpl.php:687|read|''MAIN_SALETAX_AUTOSWITCH_I_CS_FOR_INDIA'' => (bool) getDolGlobalInt(''MAIN_SALETAX_AUTOSWITCH_I_CS_FOR_INDIA''),", "core/tpl/objectline_create.tpl.php:764  * @property {boolean} conf.MAIN_SALETAX_AUTOSWITCH_I_CS_FOR_INDIA"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SAVE_FILE_CONTENT_AS_TEXT', 'string', NULL, 'ecm', 'Selects the text extraction engine used to index file content as plain text for full-text search.', 'Controls whether and how file content is extracted as text and stored for indexing. The inline comment states: ''Can be \''\'', \''pdftotext\'' or \''docling\''''. Used across core/lib/files.lib.php and multiple ecm/class/ecmfiles.class.php methods. No admin UI write; hidden setting.', 'Setting this to ''pdftotext'' or ''docling'' activates full-text indexation of uploaded files using the respective tool; leaving it empty disables text content extraction.', ''''' (disabled), ''pdftotext'', ''docling''', 1, 0, NULL, 1, 'a638820d664ec8cdde1d575d59b003a26abde3a382a6683f9fae7931189b91db', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/files.lib.php:2338|read|$useFullTextIndexation = getDolGlobalString(''MAIN_SAVE_FILE_CONTENT_AS_TEXT'');\t// Can be '''', ''pdftotext'' or ''docling''", "ecm/class/ecmfiles.class.php:321|check|if (getDolGlobalString(\"MAIN_SAVE_FILE_CONTENT_AS_TEXT\")) {", "core/class/html.formfile.class.php:275|check|if (getDolGlobalString(''MAIN_SAVE_FILE_CONTENT_AS_TEXT'')) {", "ecm/class/ecmfiles.class.php:433|check|if (getDolGlobalString(\"MAIN_SAVE_FILE_CONTENT_AS_TEXT\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SAVE_FILE_CONTENT_AS_TEXT_DOCLING', 'string', NULL, 'core', 'Specifies the command-line path or invocation for the docling binary used in full-text file indexation.', 'In core/lib/files.lib.php, when MAIN_SAVE_FILE_CONTENT_AS_TEXT is ''docling'', this constant overrides the default ''docling'' command. The inline comment labels it ''Command line for docling''. Default fallback is the string ''docling''. No admin UI write; hidden setting.', 'Setting this to a custom path or command allows a non-default docling installation to be used for text extraction; leaving it unset uses the default ''docling'' command.', 'A shell command string for docling; defaults to ''docling'' if not set.', 1, 0, NULL, 1, '09d849e03e55dc4477ccf84611ceba7642272d2b292a8139eb83977ef186d044', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/files.lib.php:2342|read|} elseif (getDolGlobalString(''MAIN_SAVE_FILE_CONTENT_AS_TEXT_DOCLING'')) {\t// Command line for docling", "core/lib/files.lib.php:4136|read|$cmd = getDolGlobalString(''MAIN_SAVE_FILE_CONTENT_AS_TEXT_DOCLING'', ''docling'').\" --from pdf --to text ''\"."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SAVE_FILE_CONTENT_AS_TEXT_PDFTOTEXT', 'string', NULL, 'core', 'Specifies the command-line path or invocation for the pdftotext binary used in full-text file indexation.', 'In core/lib/files.lib.php, when MAIN_SAVE_FILE_CONTENT_AS_TEXT is ''pdftotext'', this constant overrides the default ''pdftotext'' command. The default fallback is the string ''pdftotext''. No admin UI write; hidden setting.', 'Setting this to a custom path or command allows a non-default pdftotext installation to be used for text extraction; leaving it unset uses the default ''pdftotext'' command.', 'A shell command string for pdftotext; defaults to ''pdftotext'' if not set.', 1, 0, NULL, 1, '28ee4b2b2faae4030bc554e1e4335a333084b971215d6782f0ddaf39367f6414', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/files.lib.php:2340|check|if (getDolGlobalString(''MAIN_SAVE_FILE_CONTENT_AS_TEXT_PDFTOTEXT'')) {\t\t// Command line for pdftotext", "core/lib/files.lib.php:4104|read|$cmd = getDolGlobalString(''MAIN_SAVE_FILE_CONTENT_AS_TEXT_PDFTOTEXT'', ''pdftotext'') . \" \" . $params .\" ''\"."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHBOX_CONTENT_LOADED_BEFORE_KEY', 'string', NULL, 'core', 'Controls whether the top search box''s dropdown content is preloaded before or after the keyboard shortcut is available.', 'In main.inc.php:3475, its (truthy) value is passed as a flag argument to selectArrayFilter() for the ''searchselectcombo'' search box, affecting a parameter that toggles content pre-loading behavior.', 'Exact behavior unclear from code alone: the flag is forwarded into selectArrayFilter as one boolean-ish argument among several, and its precise UI effect on the search dropdown could not be determined from this snippet alone.', 'Boolean-like flag consumed by Form::selectArrayFilter as an argument controlling combo box content loading.', 0, 0, NULL, 1, '524de61cc9cc8c8043d412373a022aa312db0dd4ca95fd03a98045bcfe211c56', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:3475|read|$searchform .= $form->selectArrayFilter(''searchselectcombo'', $arrayresult, (string) $selected, ''accesskey=\"s\"'', 1, 0, (getDolGlobalString(''MAIN_SEARCHBOX_CONTENT_LOADED_BEFORE_KEY'') ? 0 : 1), ..."]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_ADHERENT_DISABLED', 'bool', NULL, 'core', 'Hides the ''search into members'' entry from the global quick-search box.', 'In core/ajax/selectsearchbox.php:84, part of a family of MAIN_SEARCHFORM_*_DISABLED flags that each toggle one entry (''searchintomember'') of the top quick-search dropdown, gated also on module-enabled and user rights.', 'Enabling it removes the members search shortcut from the quick-search box even if the member module is enabled and the user has rights to view members.', 'boolean: 1/true hides the ''search into members'' entry from the quick-search box; unset/0 = shown (subject to module/rights checks).', 1, 0, NULL, 1, 'd1c8c3f76d39a6d6be6357be7949d86be40a91eb8d7581b41b8e9580804d1594', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:84: if (isModEnabled(''member'') && !getDolGlobalString(''MAIN_SEARCHFORM_ADHERENT_DISABLED'') && $user->hasRight(''adherent'', ''lire'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_CONTACT', 'string', NULL, 'user', 'Legacy/deprecated constant that once held the contact permanent search box configuration; still read in a commented-out array in user/param_ihm.php but the active equivalent is MAIN_SEARCHFORM_CONTACT_DISABLED used by core/ajax/selectsearchbox.php and the menu code.', 'Appears only inside a PHP block comment in user/param_ihm.php:87-91 marked ''/* deprecated ... */''; the live, currently-used constant with similar purpose is MAIN_SEARCHFORM_CONTACT_DISABLED, set by core/menus/standard/eldy_menu.php:161 and auguria_menu.php:165 and checked in core/ajax/selectsearchbox.php:92 to hide the contact quick-search box.', 'The bare MAIN_SEARCHFORM_CONTACT constant itself has no active effect since its only reference is inside dead/commented-out code; the related active constant MAIN_SEARCHFORM_CONTACT_DISABLED controls whether the contact quick-search box is shown in the top search form.', 'Exact behavior unclear from code alone [SPECULATION] for the bare name; the sibling _DISABLED constant is a simple truthy flag that hides the search box.', 1, 0, NULL, 1, '3aeddf0e32091b70874cee8e0954007332ad6f6229ed261fb8b05878e5db0204', 'v2', '2026-07-24T07:05:23+00:00', '["user/param_ihm.php:87: /* deprecated", "user/param_ihm.php:89: $searchformconst=array($conf->global->MAIN_SEARCHFORM_SOCIETE,$conf->global->MAIN_SEARCHFORM_CONTACT,$conf->global->MAIN_SEARCHFORM_PRODUITSERVICE);", "core/ajax/selectsearchbox.php:92: if (isModEnabled(''societe'') && !getDolGlobalString(''MAIN_SEARCHFORM_CONTACT_DISABLED'') && $user->hasRight(''societe'', ''lire'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_CONTACT_DISABLED', 'bool', NULL, 'core', 'Disables the contact search entry in the global search box.', 'Checked in core/ajax/selectsearchbox.php:92. Also written to 1 by core/menus/standard/auguria_menu.php:165 and eldy_menu.php:161.', 'Setting this constant removes the contact search shortcut from the global search box; clearing it restores it for users with the societe read right.', 'Any non-empty value = disable contact search form entry; empty/unset = show entry', 1, 0, NULL, 1, 'ba5203211787627000074ed2210802bdcda8a08d3b45765b1cd1c1bcd2ba6110', 'v2', '2026-04-21T13:29:58+00:00', '["if (isModEnabled(''societe'') && !getDolGlobalString(''MAIN_SEARCHFORM_CONTACT_DISABLED'') && $user->hasRight(''societe'', ''lire'')) {", "$conf->global->MAIN_SEARCHFORM_CONTACT_DISABLED = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_CONTRACT_DISABLED', 'bool', NULL, 'core', 'Hides the "Search into contracts" entry from the top quick-search dropdown when set.', 'Checked in core/ajax/selectsearchbox.php:173: the searchintocontract entry is only added if !getDolGlobalString(''MAIN_SEARCHFORM_CONTRACT_DISABLED''), alongside the contract module and permission checks.', 'Setting this constant to any truthy value removes the contracts quick-search entry regardless of module status or user rights.', 'Boolean-like; truthy disables the search entry, empty/unset keeps it enabled.', 1, 0, NULL, 1, '7c9845b85420e6e15aac1de8c17cfdeb348bdaa09dc85dff6334db0b6366f667', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:173|check|if (isModEnabled(''contract'') && !getDolGlobalString(''MAIN_SEARCHFORM_CONTRACT_DISABLED'') && $user->hasRight(''contrat'', ''lire'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_CUSTOMER_INVOICE_DISABLED', 'bool', NULL, 'core', 'Disables the customer invoice entry in the global search form when set to a non-empty value.', 'Checked twice in core/ajax/selectsearchbox.php (lines 123 and 144) alongside module-enabled and user-rights checks; when truthy, the customer invoice search option is excluded from the search box.', 'Setting this to a non-empty value removes customer invoices from the global search dropdown for all users.', 'Empty/unset = enabled; any non-empty string = disabled.', 1, 0, NULL, 1, '3b748f925174db151bd6dc3d294fa874ab6cd020eb3e8e342ae758893f38203f', 'v2', '2026-04-21T13:29:58+00:00', '["core/ajax/selectsearchbox.php:144|check|if (isModEnabled(''invoice'') && !getDolGlobalString(''MAIN_SEARCHFORM_CUSTOMER_INVOICE_DISABLED'') && $user->hasRight(''facture'', ''lire'')) {", "core/ajax/selectsearchbox.php:123|check|if (isModEnabled(''invoice'') && !getDolGlobalString(''MAIN_SEARCHFORM_CUSTOMER_INVOICE_DISABLED'') && $user->hasRight(''facture'', ''lire'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_CUSTOMER_INVOICE_REC_DISABLED', 'bool', NULL, 'core', 'Hides the "Search into recurring customer invoice templates" entry from the top quick-search dropdown when set.', 'Checked in core/ajax/selectsearchbox.php:126: the searchintoinvoicerec entry is only added if !getDolGlobalString(''MAIN_SEARCHFORM_CUSTOMER_INVOICE_REC_DISABLED''), alongside module and permission checks.', 'Setting this constant to any truthy value removes the recurring-invoice-templates quick-search entry regardless of module status or user rights.', 'Boolean-like; truthy disables the search entry, empty/unset keeps it enabled.', 1, 0, NULL, 1, '0deea34659db50506aac72d240455a76c4581d7bea0f283885509ea5af61ed9e', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:126|check|if (isModEnabled(''invoice'') && !getDolGlobalString(''MAIN_SEARCHFORM_CUSTOMER_INVOICE_REC_DISABLED'') && $user->hasRight(''facture'', ''lire'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_CUSTOMER_ORDER_DISABLED', 'bool', NULL, 'core', 'Hides the "Search into customer orders" entry from the top quick-search dropdown when set.', 'Checked in core/ajax/selectsearchbox.php:117: the searchintoorder entry is only added if !getDolGlobalString(''MAIN_SEARCHFORM_CUSTOMER_ORDER_DISABLED''), alongside module and permission checks.', 'Setting this constant to any truthy value removes the customer-orders quick-search entry regardless of module status or user rights.', 'Boolean-like; truthy disables the search entry, empty/unset keeps it enabled.', 1, 0, NULL, 1, '2adc3e6e65da83bd0822ef1ad1eab9585814834bc3b49cb2eae8c6bc0045fd8b', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:117|check|if (isModEnabled(''order'') && !getDolGlobalString(''MAIN_SEARCHFORM_CUSTOMER_ORDER_DISABLED'') && $user->hasRight(''commande'', ''lire'')) {"]', 'medium', NULL);
