INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_PRODUITSERVICE', 'string', NULL, 'user', 'Legacy/deprecated constant that once held the product/service permanent search box configuration; still read in a commented-out array in user/param_ihm.php but the active equivalent is MAIN_SEARCHFORM_PRODUITSERVICE_DISABLED used by core/ajax/selectsearchbox.php.', 'Appears only inside a PHP block comment in user/param_ihm.php:87-91 marked ''/* deprecated ... */''; the live, currently-used constant with similar purpose is MAIN_SEARCHFORM_PRODUITSERVICE_DISABLED, checked in core/ajax/selectsearchbox.php:96 to hide the product/service quick-search box.', 'The bare MAIN_SEARCHFORM_PRODUITSERVICE constant itself has no active effect since its only reference is inside dead/commented-out code; the related active constant MAIN_SEARCHFORM_PRODUITSERVICE_DISABLED controls whether the product/service quick-search box is shown in the top search form.', 'Exact behavior unclear from code alone [SPECULATION] for the bare name; the sibling _DISABLED constant is a simple truthy flag that hides the search box.', 1, 0, NULL, 1, 'fb112f3959b5b2505fc9991a8d1c58e16372ad1b9ad1548f8b037cb390841a04', 'v2', '2026-07-24T07:05:23+00:00', '["user/param_ihm.php:87: /* deprecated", "user/param_ihm.php:89: $searchformconst=array($conf->global->MAIN_SEARCHFORM_SOCIETE,$conf->global->MAIN_SEARCHFORM_CONTACT,$conf->global->MAIN_SEARCHFORM_PRODUITSERVICE);", "core/ajax/selectsearchbox.php:96: if (...&& !getDolGlobalString(''MAIN_SEARCHFORM_PRODUITSERVICE_DISABLED'')) {"]', 'low', NULL);
