INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_TASK_DISABLED', 'bool', NULL, 'core', 'Hides the ''search into tasks'' entry from the global quick-search box.', 'In core/ajax/selectsearchbox.php:110, part of the MAIN_SEARCHFORM_*_DISABLED family; when set (or when PROJECT_HIDE_TASKS is set), the searchintotasks entry is not added even if the project module is enabled and the user has rights.', 'Enabling it removes the tasks search shortcut from the quick-search box even if the project module is enabled and the user has rights to view projects; PROJECT_HIDE_TASKS has the same suppressing effect.', 'boolean: 1/true hides the ''search into tasks'' entry from the quick-search box; unset/0 = shown (subject to module/rights checks and PROJECT_HIDE_TASKS).', 1, 0, NULL, 1, '7c8ba295d68e94a770db51fd891234766272b56cf35161789976cd396b5708ac', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:110: if (isModEnabled(''project'') && !getDolGlobalString(''MAIN_SEARCHFORM_TASK_DISABLED'') && !getDolGlobalString(''PROJECT_HIDE_TASKS'') && $user->hasRight(''projet'', ''lire'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_TICKET_DISABLED', 'bool', NULL, 'core', 'Hides the "Search into tickets" entry from the top quick-search dropdown when set.', 'Checked in core/ajax/selectsearchbox.php:182: the searchintotickets entry is only added if !getDolGlobalString(''MAIN_SEARCHFORM_TICKET_DISABLED''), alongside the ticket module and permission checks.', 'Setting this constant to any truthy value removes the tickets quick-search entry regardless of module status or user rights.', 'Boolean-like; truthy disables the search entry, empty/unset keeps it enabled.', 1, 0, NULL, 1, '95a5df25bca78e8380ece00a75d893477d967a3278b8d76c168fb9cdb10009e8', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:182|check|if (isModEnabled(''ticket'') && !getDolGlobalString(''MAIN_SEARCHFORM_TICKET_DISABLED'') && $user->hasRight(''ticket'', ''read'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCHFORM_USER_DISABLED', 'bool', NULL, 'core', 'Hides the "Search into users" entry from the top quick-search dropdown when set.', 'Checked in core/ajax/selectsearchbox.php:187: the searchintouser entry is only added if !getDolGlobalString(''MAIN_SEARCHFORM_USER_DISABLED''), alongside the user module and permission checks.', 'Setting this constant to any truthy value removes the users quick-search entry regardless of module status or user rights.', 'Boolean-like; truthy disables the search entry, empty/unset keeps it enabled.', 1, 0, NULL, 1, 'db084121c8539deb70f46730e3678203fd49ec450484d007652ddb44d7310283', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:187|check|if (isModEnabled(''user'') && !getDolGlobalString(''MAIN_SEARCHFORM_USER_DISABLED'') && $user->hasRight(''user'', ''user'', ''lire'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_CATEGORY_CUSTOMER_ON_CONTRACT_LIST', 'string', NULL, 'contrat', 'When enabled (and the category module/permission are available), shows a customer-category multiselect filter on the contracts list page.', 'Checked in contrat/list.php:883: `if (getDolGlobalString(''MAIN_SEARCH_CATEGORY_CUSTOMER_ON_CONTRACT_LIST'') && isModEnabled("category") && $user->hasRight(''categorie'', ''lire'')) { ... }`, which then renders a ''CustomersProspectsCategoriesShort'' multiselect filter box on the contracts list.', 'Adds an extra search filter box to the contract list allowing filtering contracts by their linked customer''s categories/tags; requires the category module enabled and the user to have category read permission.', 'Boolean-like: truthy (combined with category module enabled and user permission) shows the customer-category filter box on the contract list.', 1, 0, NULL, 1, 'a01e03ae1d203f3fe1359fec33046014802e4b2019060ea89715cb029a69c697', 'v2', '2026-07-24T07:05:23+00:00', '["contrat/list.php:883|check|if (getDolGlobalString(''MAIN_SEARCH_CATEGORY_CUSTOMER_ON_CONTRACT_LIST'') && isModEnabled(\"category\") && $user->hasRight(''categorie'', ''lire'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_CATEGORY_CUSTOMER_ON_PROJECT_LIST', 'string', NULL, 'projet', 'Adds a customer-category filter box to the project list page when enabled.', 'In projet/list.php:1384, if getDolGlobalString(''MAIN_SEARCH_CATEGORY_CUSTOMER_ON_PROJECT_LIST'') is set (and the category module is enabled and the user has read rights on categories), a FormCategory filter box for Categorie::TYPE_CUSTOMER is appended to $moreforfilter.', 'Enabling it adds an additional ''filter on customer categories'' search box to the project list UI, alongside the existing project-category filter box.', 'Boolean-like truthy check via getDolGlobalString(), combined with isModEnabled(''category'') and a permission check.', 1, 0, NULL, 1, 'f80c733a3d45a6f15f27883b25ba06e278c0ed818c4b4f823364938cc3c47903', 'v2', '2026-07-24T07:05:23+00:00', '["projet/list.php:1384: if (getDolGlobalString(''MAIN_SEARCH_CATEGORY_CUSTOMER_ON_PROJECT_LIST'') && isModEnabled(\"category\") && $user->hasRight(''categorie'', ''lire'')) {", "projet/list.php: // Filter on customer categories"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_CATEGORY_CUSTOMER_ON_TASK_LIST', 'string', NULL, 'projet', 'Adds a customer-category filter box to the project tasks list search form.', 'Checked in projet/tasks/list.php:831: `if (getDolGlobalString(''MAIN_SEARCH_CATEGORY_CUSTOMER_ON_TASK_LIST'') && isModEnabled("category") && $user->hasRight(''categorie'', ''lire'')) { ... $moreforfilter .= $formcategory->getFilterBox(Categorie::TYPE_CUSTOMER, ...`.', 'When enabled (and the category module is on and the user can read categories), the task list search form gains a filter box to narrow tasks by the linked thirdparty''s customer category; when disabled the filter box is not shown.', 'Boolean: truthy adds the customer-category filter box to the task list, subject to category module and permission.', 1, 0, NULL, 1, '730541a51511e5701172c043a70b581f35511d838860e838bc8c3a8d4dbda5b7', 'v2', '2026-07-24T07:05:23+00:00', '["projet/tasks/list.php:831|check|if (getDolGlobalString(''MAIN_SEARCH_CATEGORY_CUSTOMER_ON_TASK_LIST'') && isModEnabled(\"category\") && $user->hasRight(''categorie'', ''lire'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_CATEGORY_PRODUCT_ON_LISTS', 'string', NULL, 'product', 'Adds a product-category filter box to the product inventory list page''s search filters.', 'In product/inventory/list.php:487, when truthy and the category module is enabled and the user has ''categorie''/''lire'' permission, a FormCategory filter box for Categorie::TYPE_PRODUCT is appended to the list''s filter row ($moreforfilter).', 'Setting it exposes an additional category-selection filter on the product inventory list, letting users filter the list by product category; requires the category module enabled and read permission on categories.', 'Boolean-like: truthy shows the product category filter box (also requires category module enabled and ''categorie''/''lire'' right).', 0, 0, NULL, 1, '92f63fa689462879485509370899206446787669b0017108b1bcd1576c9a459b', 'v2', '2026-07-24T07:05:23+00:00', '["product/inventory/list.php:487|check|if (getDolGlobalString(''MAIN_SEARCH_CATEGORY_PRODUCT_ON_LISTS'') && isModEnabled(''category'') && $user->hasRight(''categorie'', ''lire'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_CAT_OR_BY_DEFAULT', 'string', NULL, 'projet', 'Sets the default logical operator (OR vs AND) used when filtering list searches by category.', 'Read with getDolGlobalString(''MAIN_SEARCH_CAT_OR_BY_DEFAULT'') across 35 occurrences, e.g. projet/list.php:145/146, knowledgemanagement/knowledgerecord_list.php:64/65, compta/facture/list.php:191, and supplier_proposal/list.php:116/117.', 'When set, the category search operator variable (e.g. $searchCategoryCustomerOperator) defaults to this value instead of the module''s default operator on list pages.', NULL, 1, 0, NULL, 1, 'edb9ea1d2827848f78a72287e35c933906fc8cb84cf762fe387b60dec9a6e5cf', 'v2', '2026-07-24T06:41:12+00:00', '["projet/list.php:146|read|$searchCategoryCustomerOperator = getDolGlobalString(''MAIN_SEARCH_CAT_OR_BY_DEFAULT'');", "knowledgemanagement/knowledgerecord_list.php:64|read|} elseif (getDolGlobalString(''MAIN_SEARCH_CAT_OR_BY_DEFAULT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_CAT_PROJECT_OR_BY_DEFAULT', 'string', NULL, 'projet', 'Sets the default operator (e.g. OR vs AND) used for the project-category filter on the project list when no explicit filter form value was submitted.', 'In projet/list.php:137-138, mirroring MAIN_SEARCH_CAT_USER_OR_BY_DEFAULT, $searchCategoryUserOperator is set from getDolGlobalString(''MAIN_SEARCH_CAT_PROJECT_OR_BY_DEFAULT'') as a fallback when the filter form was not submitted (GETPOSTISSET(''formfilteraction'') is false).', 'Setting it changes the default category-filter matching operator applied to the project-category search on the project list before any explicit filter submission.', 'Not documented in comments; used as the default value assigned to $searchCategoryUserOperator.', 1, 0, NULL, 1, '08df457a1d036647b1015b3ed06f94180edd331d8dd159fb27367ea3ef2a2080', 'v2', '2026-07-24T07:05:23+00:00', '["projet/list.php:137: } elseif (getDolGlobalString(''MAIN_SEARCH_CAT_PROJECT_OR_BY_DEFAULT'')) {", "projet/list.php:138: $searchCategoryUserOperator = getDolGlobalString(''MAIN_SEARCH_CAT_PROJECT_OR_BY_DEFAULT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_CAT_USER_OR_BY_DEFAULT', 'string', NULL, 'projet', 'Sets the default operator (e.g. OR vs AND) used for the user-category filter on the project list when no explicit filter form value was submitted.', 'In projet/list.php:130-131, $searchCategoryUserOperator is set from GETPOSTINT(''search_category_user_operator'') if the filter form was submitted (GETPOSTISSET(''formfilteraction'')); otherwise it falls back to getDolGlobalString(''MAIN_SEARCH_CAT_USER_OR_BY_DEFAULT'').', 'Setting it changes the default category-filter matching operator applied to the user-category search on the project list before the user submits any explicit filter choice.', 'Not documented in comments; used as the default value assigned to $searchCategoryUserOperator (an operator flag consumed elsewhere in the category filter logic).', 1, 0, NULL, 1, 'de51c62ae3698288eab5b261ffbcd3820b9742cb075dad8cc8863489966b8cfa', 'v2', '2026-07-24T07:05:23+00:00', '["projet/list.php:130: } elseif (getDolGlobalString(''MAIN_SEARCH_CAT_USER_OR_BY_DEFAULT'')) {", "projet/list.php:131: $searchCategoryUserOperator = getDolGlobalString(''MAIN_SEARCH_CAT_USER_OR_BY_DEFAULT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_DIRECT_OPEN_IF_ONLY_ONE', 'string', NULL, 'hrm', 'Enables automatically redirecting/opening the record directly when a global quick-search returns exactly one result on a list page.', 'Checked with getDolGlobalInt/getDolGlobalString(''MAIN_SEARCH_DIRECT_OPEN_IF_ONLY_ONE'') across 60 occurrences, e.g. admin/emailcollector_list.php:350, accountancy/admin/template/list.php:316, compta/cashcontrol/cashcontrol_list.php:383, projet/list.php:987.', 'When enabled and a search ($search_all) yields exactly one result ($num == 1) on the first page, the list page opens that record directly instead of showing the list.', NULL, 1, 0, 'admin/emailcollector_list.php|accountancy/admin/template/list.php', 1, '5e2f946f3cebdff998ebb66b032128d9c660883a4d71d10a95ed2ad2e672fb8f', 'v2', '2026-07-24T06:41:12+00:00', '["admin/emailcollector_list.php:350|check|if ($num == 1 && getDolGlobalInt(''MAIN_SEARCH_DIRECT_OPEN_IF_ONLY_ONE'') && $search_all && !$page) {", "projet/list.php:987|check|if ($num == 1 && getDolGlobalInt(''MAIN_SEARCH_DIRECT_OPEN_IF_ONLY_ONE'') && $search_all && !$page) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_FORM_ON_HOME_AREAS', 'string', NULL, 'product', 'Controls whether a legacy search form is displayed on module home/index pages.', 'Checked in product/index.php:120, reception/index.php:73, don/index.php:104, hrm/index.php:133, and product/stock/index.php:72. Code comments note it ''may be useless due to the global search combo''. No admin UI write path exists.', 'Enabling this constant causes additional search forms to appear on several module index pages; disabling or leaving it unset hides them.', 'Truthy string=search form shown, empty/unset=hidden', 1, 0, NULL, 1, '769c8387c6832f928f2f8c1bafbe70a92f7436b072a1d43c5abf9a209489dbe7', 'v2', '2026-04-21T11:16:15+00:00', '["product/index.php:120|check|if (getDolGlobalString(''MAIN_SEARCH_FORM_ON_HOME_AREAS'')) {     // This may be useless due to the global search combo", "hrm/index.php:133|check|if (getDolGlobalString(''MAIN_SEARCH_FORM_ON_HOME_AREAS'')) {     // This is useless due to the global search combo", "don/index.php:104|check|if (getDolGlobalString(''MAIN_SEARCH_FORM_ON_HOME_AREAS'')) {     // TODO Add a search into global search combo so we can remove this", "reception/index.php:73|check|if (getDolGlobalString(''MAIN_SEARCH_FORM_ON_HOME_AREAS'')) {     // This may be useless due to the global search combo"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_PRODUCT_BY_FOURN_REF', 'string', NULL, 'core', 'Extends product search to also match against the supplier''s product reference (ref_fourn).', 'core/class/html.form.class.php:3828-3831 and again at 3843-3848 in the product search query builder: when truthy, adds `pfp.ref_fourn LIKE ''%term%''` conditions and an `OR EXISTS (SELECT pfp.fk_product FROM ...product_fournisseur_price... WHERE p.rowid = pfp.fk_product AND (...))` subquery joining supplier prices.', 'Setting it to a truthy value lets users find products by typing a supplier reference in the product search box, at the cost of an extra EXISTS subquery against product_fournisseur_price for every search.', 'Truthy = also match supplier ref (pfp.ref_fourn) via EXISTS subquery on product_fournisseur_price; 0/unset = supplier ref not searched (default).', 1, 0, NULL, 1, '064de8b1cf5f270d94f05092b004845124b89ae27b854fb2804b34188c506a37', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:3828: if (getDolGlobalString(''MAIN_SEARCH_PRODUCT_BY_FOURN_REF'')) {", "core/class/html.form.class.php:3843: if (getDolGlobalString(''MAIN_SEARCH_PRODUCT_BY_FOURN_REF'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_PRODUCT_FORCE_INDEX', 'string', NULL, 'core', 'Toggles whether the product list/search SQL query should force a specific MySQL index, as named by MAIN_PRODUCT_FORCE_INDEX.', 'core/class/html.form.class.php:3698-3699: `if (getDolGlobalString(''MAIN_SEARCH_PRODUCT_FORCE_INDEX'')) { $sql .= " USE INDEX (" . $this->db->sanitize(getDolGlobalString(''MAIN_PRODUCT_FORCE_INDEX'')) . ")"; }` in the product search query builder (select_produits_list-style method).', 'Setting it to a truthy value adds a `USE INDEX (...)` SQL hint (naming the index from MAIN_PRODUCT_FORCE_INDEX) to the product search query, which can help or hurt performance depending on the database''s query planner and actual indexes present.', 'Truthy = enable the USE INDEX hint, actual index name taken from MAIN_PRODUCT_FORCE_INDEX; 0/unset = no index hint (default, planner decides).', 1, 0, NULL, 1, '23a27163a27a6222da051b5efc9cefc6498ffc751339105874f250446da1624b', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:3698: if (getDolGlobalString(''MAIN_SEARCH_PRODUCT_FORCE_INDEX'')) {", "core/class/html.form.class.php:3699: $sql .= \" USE INDEX (\" . $this->db->sanitize(getDolGlobalString(''MAIN_PRODUCT_FORCE_INDEX'')) . \")\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEARCH_PROJECT_USER_PROJECTSINDEX', 'string', NULL, 'projet', 'Default value of the ''search project user'' filter on the project activity index page when no explicit mode/user is selected.', 'Used identically in projet/activity/index.php:54 and projet/index.php:54: $search_project_user = getDolGlobalString(''MAIN_SEARCH_PROJECT_USER_PROJECTSINDEX'') is applied only when GETPOST ''mode'' isn''t ''mine'' and search_project_user was not already provided in the request.', 'Setting this pre-selects a default user filter on the project index/activity pages for users who have not explicitly chosen a filter mode.', 'String, expected to be a user id (compared later against $user->id to decide the ''mine'' toggle); empty/unset means no default filter is applied.', 1, 0, NULL, 1, 'f3e2167bc96430087ab0782f9f32cc766c71a78252aac3c2ad74213ff6156969', 'v2', '2026-07-24T07:05:23+00:00', '["projet/activity/index.php:54: $search_project_user = getDolGlobalString(''MAIN_SEARCH_PROJECT_USER_PROJECTSINDEX'');", "projet/index.php:54: $search_project_user = getDolGlobalString(''MAIN_SEARCH_PROJECT_USER_PROJECTSINDEX'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ALLOW_TOTP', 'bool', NULL, 'user', 'Enables two-factor authentication (2FA/TOTP) support on user profile pages.', 'Checked in user/card.php at line 2099. Per the code comment: ''MAIN_SECURITY_ALLOW_TOTP=1 to enabled 2FA''. When set along with appropriate permissions, the TOTP setup section is displayed.', 'Setting this to 1 enables the TOTP/2FA configuration section on user profile pages; leaving it unset hides 2FA options.', 'MAIN_SECURITY_ALLOW_TOTP=1 to enabled 2FA', 1, 0, NULL, 1, 'cd4d344a47b47952b194866c4d3362d64a137719532ae3a16eaf929d410c2a08', 'v2', '2026-04-21T13:50:40+00:00', '["user/card.php:2005  // MAIN_SECURITY_ALLOW_TOTP=1 to enabled 2FA", "user/card.php:2099|check|if (getDolGlobalString(''MAIN_SECURITY_ALLOW_TOTP'') && $permissiontoeditpasswordandsee) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ALLOW_UNSECURED_LABELS_WITH_HTML', 'bool', NULL, 'barcode', 'Switches product/barcode label security filter from ''alphanohtml'' (strip all HTML) to ''restricthtml'' (allow basic HTML).', 'Comments at product/card.php:136 and core/class/extrafields.class.php:2964 state: ''by default alphanohtml (better security); hidden conf MAIN_SECURITY_ALLOW_UNSECURED_LABELS_WITH_HTML allows basic html''. All three occurrences (barcode/printsheet.php:80, product/card.php:140, core/class/extrafields.class.php:2968) use a ternary to select the filter level.', 'Enabling this constant allows basic HTML markup in product and barcode labels; leaving it unset enforces the safer alphanohtml filter that strips all HTML.', 'Unset/0 = ''alphanohtml'' (no HTML allowed); non-empty = ''restricthtml'' (basic HTML allowed).', 1, 0, NULL, 1, 'bf7a5c8d48027624cb75cccef2f6f557fcb32cf43cd04d27bb4c600a46333e19', 'v2', '2026-04-21T11:16:15+00:00', '["// by default ''alphanohtml'' (better security); hidden conf MAIN_SECURITY_ALLOW_UNSECURED_LABELS_WITH_HTML allows basic html", "barcode/printsheet.php:80|read|$security_check = !getDolGlobalString(''MAIN_SECURITY_ALLOW_UNSECURED_LABELS_WITH_HTML'') ? ''alphanohtml'' : ''restricthtml'';", "product/card.php:140|read|$label_security_check = !getDolGlobalString(''MAIN_SECURITY_ALLOW_UNSECURED_LABELS_WITH_HTML'') ? ''alphanohtml'' : ''restricthtml'';", "core/class/extrafields.class.php:2968|read|$label_security_check = !getDolGlobalString(''MAIN_SECURITY_ALLOW_UNSECURED_LABELS_WITH_HTML'') ? ''alphanohtml'' : ''restricthtml'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ALLOW_UNSECURED_REF_LABELS', 'bool', NULL, 'product', 'Relaxes input sanitisation for product reference and label fields, allowing characters that would otherwise be rejected.', 'Checked in product/class/product.class.php:972, :1401, and :936, as well as product/card.php:113 and :137, core/class/extrafields.class.php:2965, and barcode/printsheet.php:71 and :77. When set, the stricter validation path for product refs/labels is bypassed.', 'Enabling this constant weakens input validation on product reference and label fields; disabling enforces the default strict sanitisation.', 'Non-empty = unsecured refs/labels allowed; 0 or unset = strict sanitisation enforced.', 1, 0, NULL, 1, '09816fe7d95f5e833a5277895765c42080f69e3b2b27de07417319ecfd8c814a', 'v2', '2026-04-21T11:16:15+00:00', '["product/class/product.class.php:972|check|if (getDolGlobalInt(''MAIN_SECURITY_ALLOW_UNSECURED_REF_LABELS'')) {", "product/card.php:113|check|if (getDolGlobalString(''MAIN_SECURITY_ALLOW_UNSECURED_REF_LABELS'')) {", "core/class/extrafields.class.php:2965|check|if (getDolGlobalString(''MAIN_SECURITY_ALLOW_UNSECURED_REF_LABELS'')) {", "barcode/printsheet.php:71|check|if (getDolGlobalString(''MAIN_SECURITY_ALLOW_UNSECURED_REF_LABELS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ANTI_SSRF_SERVER_IP', 'string', NULL, 'core', 'Sets a comma-separated list of allowed server IP addresses for the anti-SSRF (Server-Side Request Forgery) filter on outbound HTTP requests.', 'Displayed in admin/system/security.php:817 and checked in core/lib/geturl.lib.php at lines 450 and 461 to allow or block outbound requests to specific IPs. The inline comment at line 30 documents: ''you can set MAIN_SECURITY_ANTI_SSRF_SERVER_IP to set static ip of server''.', 'When set, outbound HTTP requests are checked against this list: requests to IPs in the list are blocked or allowed depending on the SSRF filter logic. Misconfiguration can block legitimate requests or leave SSRF vulnerabilities open.', 'Comma-separated list of IP address strings; empty or unset disables the static IP override for the anti-SSRF filter.', 0, 0, 'admin/system/security.php', 1, '88eb9ef296c1fd066c99570fcf0781ee813fd91f81cfd4b75c45689505fb459b', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/geturl.lib.php:30  * - you can set MAIN_SECURITY_ANTI_SSRF_SERVER_IP to set static ip of server", "core/lib/geturl.lib.php:450|check|if (getDolGlobalString(''MAIN_SECURITY_ANTI_SSRF_SERVER_IP'') && in_array($iptocheck, explode('','', getDolGlobalString(''MAIN_SECURITY_ANTI_SSRF_SERVER_IP'')))) {", "core/lib/geturl.lib.php:461|check|if (getDolGlobalString(''MAIN_SECURITY_ANTI_SSRF_SERVER_IP'') && !in_array($iptocheck, explode('','', getDolGlobalString(''MAIN_SECURITY_ANTI_SSRF_SERVER_IP'')))) {", "admin/system/security.php:817|read|print ''<strong>MAIN_SECURITY_ANTI_SSRF_SERVER_IP</strong> = ''.getDolGlobalString(''MAIN_SECURITY_ANTI_SSRF_SERVER_IP'', ''<span class=\"opacitymedium\">''.$langs->trans(\"Undefined\").''</s"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_CSRF_TOKEN_RENEWAL_ON_EACH_CALL', 'string', NULL, 'core', 'Controls whether the CSRF token is renewed on every page call instead of once per session.', 'When set to 1, a new CSRF token is generated on each page request rather than persisting for the full session. Referenced in main.inc.php:348 and documented in core/class/conf.class.php:1351.', 'Enabling this reduces the window for CSRF token replay attacks but is explicitly noted as not recommended; the comment at main.inc.php:349 warns it can cause issues if a user submits data from a cached page.', '0 or unset = renew token once per session (default); 1 = renew token on every page call (not recommended)', 0, 0, 'admin/system/security.php', 1, 'e39d6aa07490b86e4a72e72b2b7d24e57885f652b486a8ff851c5148e0731bdb', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/conf.class.php:1351  // Note: Set MAIN_SECURITY_CSRF_TOKEN_RENEWAL_ON_EACH_CALL=1 to have a renewal of token at each page call instead of each session (not recommended)", "main.inc.php:349  // Note: Using MAIN_SECURITY_CSRF_TOKEN_RENEWAL_ON_EACH_CALL is not recommended: if a user succeed in entering a data from", "main.inc.php:348|check|if (!isset($_SESSION[''newtoken'']) || getDolGlobalInt(''MAIN_SECURITY_CSRF_TOKEN_RENEWAL_ON_EACH_CALL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_CSRF_WITH_TOKEN', 'string', NULL, 'core', 'Controls the level of CSRF token enforcement applied to form submissions and actions.', 'Checked in main.inc.php:362 to activate token validation on requests, with stricter enforcement at values >= 2 (main.inc.php:372) and >= 3 (main.inc.php:366 for mass actions). Managed via admin/system/security.php and admin/modules.php. Module enable/disable operations detect changes to this value.', 'Higher values enforce stricter CSRF checking; setting it to 0 or leaving it unset disables token-based CSRF protection.', 'Integer level: 0 or unset = disabled; 1 = basic token check; 2 = stricter check; 3 = also enforces token on mass actions.', 0, 0, 'admin/modules.php|admin/modules.php|admin/system/security.php', 1, 'e37a2c768b3632e1f50c186dd3f1ee2872f1b4ee66395cab903ba51721cab2ae', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:362|check|if ((!defined(''NOCSRFCHECK'') && empty($dolibarr_nocsrfcheck) && getDolGlobalInt(''MAIN_SECURITY_CSRF_WITH_TOKEN'')) || defined(''CSRFCHECK_WITH_TOKEN'')) {", "main.inc.php:366|check|if ((GETPOSTISSET(''massaction'') || $tmpaction) && getDolGlobalInt(''MAIN_SECURITY_CSRF_WITH_TOKEN'') >= 3) {", "main.inc.php:372|read|} elseif (getDolGlobalInt(''MAIN_SECURITY_CSRF_WITH_TOKEN'') >= 2) {", "modulebuilder/template/myobject_agenda.php:32  //if (! defined(''NOTOKENRENEWAL''))           define(''NOTOKENRENEWAL'', ''1'');\t\t\t\t// Do not roll the Anti CSRF token (used if MAIN_SECURITY_CSRF_WITH_TOKEN is on)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_DISABLEFORGETPASSLINK', 'bool', NULL, 'admin', 'Disables the ''forgot password'' link on the Dolibarr login page.', 'Configurable via admin/security.php (write at line 152 to set ''1'', line 154 to delete). Checked at user/passwordforgotten.php line 51 (blocks access), admin/security.php lines 476, 480, 485, and core/lib/security2.lib.php lines 271-272 (controls link rendering).', 'Setting this constant hides and blocks the forgot-password link and page, preventing users from self-resetting their passwords. Clearing it restores the link.', '"1" = forgot-password link disabled; absent/deleted = forgot-password link enabled.', 0, 0, 'admin/security.php|admin/security.php|admin/security.php|admin/security.php|admin/security.php', 1, 'd9fba71d5be35f226f76156dcd562e236edd43d912b1e52d14b67d5d758e7523', 'v2', '2026-04-21T13:29:58+00:00', '["admin/security.php:152|write|dolibarr_set_const($db, \"MAIN_SECURITY_DISABLEFORGETPASSLINK\", ''1'', ''chaine'', 0, '''', $conf->entity);", "user/passwordforgotten.php:51|check|if (getDolGlobalString(''MAIN_SECURITY_DISABLEFORGETPASSLINK'')) {", "core/lib/security2.lib.php:271|check|if (!getDolGlobalString(''MAIN_SECURITY_DISABLEFORGETPASSLINK'') || getDolGlobalString(''MAIN_HELPCENTER_LINKTOUSE'')) {", "core/lib/security2.lib.php:272|check|if (!getDolGlobalString(''MAIN_SECURITY_DISABLEFORGETPASSLINK'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA', 'bool', NULL, 'admin', 'Enables CAPTCHA verification on the Dolibarr login form and other public-facing forms.', 'When set to a truthy value, CAPTCHA challenges are activated for login and other public forms. Managed via admin/security_captcha.php and reported in admin/system/security.php:507-508.', 'Enabling this adds bot-protection to the login process; disabling it removes the CAPTCHA challenge, making forms accessible without solving a CAPTCHA.', '0 or unset = CAPTCHA disabled; 1 (truthy) = CAPTCHA enabled', 0, 0, 'admin/security_captcha.php|admin/security_captcha.php|admin/system/security.php|admin/system/security.php', 1, 'c04c373aa4fa1e218167feedc9869eb368dfd4924b6d5371fb2914fc96b38123', 'v2', '2026-04-21T11:16:15+00:00', '["admin/security_captcha.php:230|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA'')) {", "main.inc.php:591|check|if ($test && GETPOST(''actionlogin'', ''aZ09'') == ''login'' && GETPOST(\"username\", \"alpha\", 2) && getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA'') && !isset($_SESSION[''dol_bypass_antis", "admin/system/security.php:508|read|print yn(!getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA'') ? 0 : 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA_DONATION', 'bool', NULL, 'public', 'Enables a CAPTCHA challenge on the public donation submission form.', 'Configured via admin/security_captcha.php:218/224 (admin UI) and checked in public/donations/new.php:109/226/565.', 'When enabled, the public donation form displays and validates a CAPTCHA before accepting a submission.', NULL, 0, 0, 'admin/security_captcha.php|admin/security_captcha.php', 1, 'fda91c6f38aa6752f13217d74e1afd4661368bf7b6a251025f0d8960ea682385', 'v2', '2026-07-24T06:41:12+00:00', '["admin/security_captcha.php:224|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_DONATION'')) {", "public/donations/new.php:109|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_DONATION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA_HANDLER', 'bool', NULL, 'public', 'Specifies the CAPTCHA handler/plugin to use when CAPTCHA is enabled.', 'Selects which CAPTCHA implementation is used across login (main.inc.php:596), ticket creation (public/ticket/create_ticket.php:117), donations (public/donations/new.php:111), membership (public/members/new.php:116), and recruitment (public/recruitment/view.php:117). Written via admin/security_captcha.php:74.', 'Changing this value switches the CAPTCHA provider used on all public-facing forms; if the named handler is unavailable, CAPTCHA rendering will fail.', '''standard'' (default if unset); any installed CAPTCHA handler identifier (e.g. ''standard'')', 0, 0, 'admin/security_captcha.php|admin/security_captcha.php', 1, '0e2c96fad1203910165a4f6b02bc0858610e643d90363c4e7352583828e979dd', 'v2', '2026-04-21T11:16:15+00:00', '["admin/security_captcha.php:74|write|if (!dolibarr_set_const($db, ''MAIN_SECURITY_ENABLECAPTCHA_HANDLER'', GETPOST(\"value\", \"aZ09\"), ''chaine'', 0, '''', $conf->entity)) {", "admin/security_captcha.php:246|read|$selectedcaptcha = getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_HANDLER'', ''standard'');", "main.inc.php:596|read|$captcha = getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_HANDLER'', ''standard'');", "core/class/html.formticket.class.php:801|read|$captcha = getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_HANDLER'', ''standard'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA_MEMBER', 'bool', NULL, 'admin', 'Enables a CAPTCHA challenge on the public member subscription/registration form.', 'Configured via admin/security_captcha.php:201/207 and admin/system/security.php:526/527 (admin UI/status display) and checked in public/members/new.php:113/393/1183.', 'When enabled, the public member registration form displays and validates a CAPTCHA before accepting a submission.', NULL, 0, 0, 'admin/security_captcha.php|admin/security_captcha.php|admin/system/security.php|admin/system/security.php', 1, '930ef28650ea74da86188193413582ee6228687c0ee4eef71e01e9139f73590a', 'v2', '2026-07-24T06:41:12+00:00', '["admin/security_captcha.php:207|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_MEMBER'')) {", "public/members/new.php:113|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_MEMBER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA_RECRUITMENT', 'bool', NULL, 'public', 'Enables a CAPTCHA challenge on the public recruitment/job application form.', 'Configured via admin/security_captcha.php:235/241 (admin UI) and checked in public/recruitment/view.php:115/186/501.', 'When enabled, the public recruitment application form displays and validates a CAPTCHA before accepting a submission.', NULL, 0, 0, 'admin/security_captcha.php|admin/security_captcha.php', 1, '8092e6ceb76d19879ac65d63783ad49163089b352643f2b2db81d39a69d21d5b', 'v2', '2026-07-24T06:41:12+00:00', '["admin/security_captcha.php:241|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_RECRUITMENT'')) {", "public/recruitment/view.php:115|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_RECRUITMENT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA_THIRDPARTY', 'bool', NULL, 'admin', 'Enables a CAPTCHA challenge on the public third-party (company) creation form.', 'Configured via admin/security_captcha.php:167/174 (admin UI) and checked in public/company/new.php:187/436.', 'When enabled, the public new-company form displays and validates a CAPTCHA before accepting a submission.', NULL, 0, 0, 'admin/security_captcha.php|admin/security_captcha.php', 1, '51bafeed2f3726eec98b54a79d31aab5b977a56d01d647ec0d781fe7438ebd8f', 'v2', '2026-07-24T06:41:12+00:00', '["admin/security_captcha.php:174|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_THIRDPARTY'')) {", "public/company/new.php:187|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_THIRDPARTY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA_THIRPARTY', 'bool', NULL, 'admin', 'Enables CAPTCHA verification on the third-party (contact/company) public forms.', 'Read in admin/system/security.php:519-520 to display the current CAPTCHA status for third-party forms as a tick icon and yes/no label.', 'When enabled, public third-party forms require CAPTCHA completion; when disabled no CAPTCHA is shown.', 'Bool-like string: empty/unset = CAPTCHA disabled; non-empty = CAPTCHA enabled.', 0, 0, 'admin/system/security.php|admin/system/security.php', 1, '9be3b972383e20ab4dc32d55f68cf98b2eb74768808ecba1de5e35aa49467503', 'v2', '2026-04-21T13:50:40+00:00', '["admin/system/security.php:519|read|print !getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_THIRPARTY'') ? '''' : img_picto('''', ''tick'').'' '';", "admin/system/security.php:520|read|print yn(!getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_THIRPARTY'') ? 0 : 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA_TICKET', 'bool', NULL, 'admin', 'Enables a CAPTCHA challenge on the public ticket creation form.', 'Configured via admin/security_captcha.php:184/190, admin/ticket_public.php:306, and admin/system/security.php:514/515 (admin UI/status display), and checked in public/ticket/create_ticket.php:115/288 and core/class/html.formticket.class.php:818.', 'When enabled, the public ticket creation form displays and validates a CAPTCHA before accepting a submission.', NULL, 0, 0, 'admin/security_captcha.php|admin/security_captcha.php|admin/ticket_public.php|admin/system/security.php|admin/system/security.php', 1, '1daa5442142bb76655c77c8e7fc370b4b8ad66f3c12d1bbcc37583d7adbef7da', 'v2', '2026-07-24T06:41:12+00:00', '["admin/security_captcha.php:190|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_TICKET'')) {", "public/ticket/create_ticket.php:115|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_TICKET'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLECAPTCHA_WEBPORTAL', 'bool', NULL, 'public', 'Enables CAPTCHA on the public web portal login page.', 'Toggled/checked in admin/security_captcha.php:253 and :259, and enforced in public/webportal/webportal.main.inc.php:184 and public/webportal/tpl/login.tpl.php:35.', 'When enabled, the web portal login template renders a CAPTCHA challenge; the admin security_captcha.php page manages turning it on/off.', NULL, 0, 0, 'admin/security_captcha.php|admin/security_captcha.php', 1, '98b0115fde643a06fd172a28daaa2c0d88940e9664129a117a08e107e3b94e04', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_WEBPORTAL'')) {", "<?php if (getDolGlobalString(''MAIN_SECURITY_ENABLECAPTCHA_WEBPORTAL'')) { ?>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_ENABLE_SENDPASSWORD', 'bool', NULL, 'user', 'Enables the ''send/reset forgotten password by e-mail'' feature on the login page.', 'Checked in user/passwordforgotten.php:258 (getDolGlobalString) to gate the password-forgotten/reset flow triggered from that page.', 'Enabling it activates the forgotten-password self-service flow (sending a reset link/new password by e-mail); disabling it removes that capability from the login page.', 'Boolean: true enables the send-password/forgotten-password flow; false/unset (default) disables it.', 1, 0, NULL, 1, '6e29abefd104374d88f419744fcba402452aa693f297b593d8a35c5cb870c640', 'v2', '2026-07-24T07:05:23+00:00', '["user/passwordforgotten.php:258|check|if (getDolGlobalString(''MAIN_SECURITY_ENABLE_SENDPASSWORD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_FORCECSP', 'string', NULL, 'admin', 'Stores the Content-Security-Policy header value to be sent on every response.', 'Written via admin/security_headers_http.php (lines 132, 205, 236) and read into $contentsecuritypolicy at main.inc.php:1600. Comments in template files show that setting it to ''none'' disables all Content Security Policies.', 'Setting this causes Dolibarr to emit an enforced Content-Security-Policy header, restricting which resources browsers may load.', 'Any valid CSP directive string; ''none'' = disable all Content Security Policies; empty/unset = header not sent', 0, 0, 'admin/security_headers_http.php|admin/security_headers_http.php|admin/system/security.php|admin/security_headers_http.php|admin/security_headers_http.php|admin/security_headers_http.php', 1, '5d87ef6c448c8549e9bf231b7d427cd583dc1fb72cff739bb5208ef1e98ac285', 'v2', '2026-04-21T11:16:15+00:00', '["//if (! defined(''MAIN_SECURITY_FORCECSP''))   define(''MAIN_SECURITY_FORCECSP'', ''none'');\t\t\t\t// Disable all Content Security Policies", "admin/security_headers_http.php:132|write|$res = dolibarr_set_const($db, ''MAIN_SECURITY_FORCECSP'', $securitycspstring, ''chaine'', 0, '''', $conf->entity);", "main.inc.php:1600|read|$contentsecuritypolicy = getDolGlobalString(''MAIN_SECURITY_FORCECSP'');", "admin/security_headers_http.php:50|read|$forceCSP = getDolGlobalString(\"MAIN_SECURITY_FORCECSP\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_FORCECSPRO', 'string', NULL, 'admin', 'Stores the Content-Security-Policy-Report-Only header value to be sent on every response.', 'Written via admin/security_headers_http.php:237 and read into $contentsecuritypolicy at main.inc.php:1560. Displayed in admin/system/security.php:689 and the headers admin page at :399.', 'Setting this causes Dolibarr to emit a Content-Security-Policy-Report-Only header, enabling CSP violation reporting without enforcement.', 'Any valid CSP directive string; empty/unset = header not sent', 0, 0, 'admin/security_headers_http.php|admin/security_headers_http.php|admin/system/security.php|admin/system/security.php|admin/security_headers_http.php', 1, '46017e879d564c1d09ba86ef32d1757e51e3c75e97297efd99d0a7971c1e26d0', 'v2', '2026-04-21T11:16:15+00:00', '["admin/security_headers_http.php:237|write|$res5 = dolibarr_set_const($db, ''MAIN_SECURITY_FORCECSPRO'', $securitycspro, ''chaine'', 0, '''', $conf->entity);", "main.inc.php:1560|read|$contentsecuritypolicy = getDolGlobalString(''MAIN_SECURITY_FORCECSPRO'');", "admin/security_headers_http.php:396|check|if (getDolGlobalString(\"MAIN_SECURITY_FORCECSPRO\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_FORCEPP', 'string', NULL, 'admin', 'Stores the Permissions-Policy HTTP header value to be sent on every response.', 'Written via admin/security_headers_http.php:235 and read at main.inc.php:1651 with an empty default. Displayed in the security summary at admin/system/security.php:684.', 'Setting this causes Dolibarr to emit a Permissions-Policy header, controlling which browser features and APIs are available to the page.', 'Any valid Permissions-Policy directive string; empty/unset = header not sent', 0, 0, 'admin/security_headers_http.php|admin/system/security.php|admin/security_headers_http.php', 1, '2a0201e6b60f177e380349f349e9e5dab2bced2ab3e4a960da9c7b5896c794bc', 'v2', '2026-04-21T11:16:15+00:00', '["admin/security_headers_http.php:235|write|$res3 = dolibarr_set_const($db, ''MAIN_SECURITY_FORCEPP'', $securitypp, ''chaine'', 0, '''', $conf->entity);", "main.inc.php:1651|read|$pp = getDolGlobalString(''MAIN_SECURITY_FORCEPP'', \"\");", "admin/system/security.php:684|read|print ''<strong>MAIN_SECURITY_FORCEPP</strong> = ''.getDolGlobalString(''MAIN_SECURITY_FORCEPP'', ''<span class=\"opacitymedium\">''.$langs->trans(\"Undefined\").''</span>'').'' &nbsp; <span cl"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_FORCERP', 'string', NULL, 'admin', 'Stores the Referrer-Policy HTTP header value to be sent on every response.', 'Written via admin/security_headers_http.php:233 and read at main.inc.php:1631 with a default of ''same-origin''. Displayed in the security summary at admin/system/security.php:678.', 'Changing this value alters the Referrer-Policy header sent to browsers, affecting how much referrer information is included in requests originating from Dolibarr pages.', 'Any valid Referrer-Policy directive string (e.g. ''same-origin'', ''no-referrer''); empty/unset = defaults to ''same-origin''', 0, 0, 'admin/security_headers_http.php|admin/system/security.php|admin/security_headers_http.php', 1, '93b5397181ac54218ad91adc54ed4493fd0d7bd70f91afe870d705866bed4ddd', 'v2', '2026-04-21T11:16:15+00:00', '["admin/security_headers_http.php:233|write|$res1 = dolibarr_set_const($db, ''MAIN_SECURITY_FORCERP'', $securityrp, ''chaine'', 0, '''', $conf->entity);", "main.inc.php:1631|read|$referrerpolicy = getDolGlobalString(''MAIN_SECURITY_FORCERP'', \"same-origin\");", "admin/system/security.php:678|read|print ''<strong>MAIN_SECURITY_FORCERP</strong> = ''.getDolGlobalString(''MAIN_SECURITY_FORCERP'', ''<span class=\"opacitymedium\">''.$langs->trans(\"Undefined\").''</span>'').'' &nbsp; <span cl"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_FORCESTS', 'string', NULL, 'admin', 'Stores the Strict-Transport-Security (HSTS) HTTP header value to be sent on every response.', 'Written via admin/security_headers_http.php:234 and read at main.inc.php:1641 with an empty default. Displayed in the security summary at admin/system/security.php:681.', 'Setting this causes Dolibarr to emit an HSTS header, instructing browsers to only access the site over HTTPS for the declared duration.', 'Any valid Strict-Transport-Security directive string (e.g. ''max-age=31536000''); empty/unset = header not sent', 0, 0, 'admin/security_headers_http.php|admin/system/security.php|admin/security_headers_http.php', 1, 'e2d7867a7b1161a95131e0ce9d8a34e60b148476a5d519ff818f1eee7384ef1a', 'v2', '2026-04-21T11:16:15+00:00', '["admin/security_headers_http.php:234|write|$res2 = dolibarr_set_const($db, ''MAIN_SECURITY_FORCESTS'', $securitysts, ''chaine'', 0, '''', $conf->entity);", "main.inc.php:1641|read|$sts = getDolGlobalString(''MAIN_SECURITY_FORCESTS'', \"\");", "admin/system/security.php:681|read|print ''<strong>MAIN_SECURITY_FORCESTS</strong> = ''.getDolGlobalString(''MAIN_SECURITY_FORCESTS'', ''<span class=\"opacitymedium\">''.$langs->trans(\"Undefined\").''</span>'').'' &nbsp; <span "]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_FORCE_ACCESS_CONTROL_ALLOW_ORIGIN', 'bool', NULL, 'core', 'Controls whether Dolibarr sends a forced Access-Control-Allow-Origin HTTP header.', 'Checked at main.inc.php:1536 to conditionally emit the CORS header. Displayed in the security summary at admin/system/security.php:699.', 'Enabling this sends an Access-Control-Allow-Origin header on responses, which affects cross-origin resource sharing behavior for browser clients.', '0 or unset = header not forced; any truthy value = Access-Control-Allow-Origin header is emitted', 0, 0, 'admin/system/security.php', 1, '4c0660e28d5e35f77836fce501a185a7c872e50de2eaa48f8c83ab0bc0a8433c', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1536|check|if (getDolGlobalString(''MAIN_SECURITY_FORCE_ACCESS_CONTROL_ALLOW_ORIGIN'')) {", "admin/system/security.php:699|read|print ''<strong>MAIN_SECURITY_FORCE_ACCESS_CONTROL_ALLOW_ORIGIN</strong> = ''.getDolGlobalString(''MAIN_SECURITY_FORCE_ACCESS_CONTROL_ALLOW_ORIGIN'', ''<span class=\"opacitymedium\">''.$la"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_HASH_ALGO', 'string', NULL, 'admin', 'Selects the password hashing algorithm used for user login credentials (e.g. ''password_hash'' vs. legacy algorithms).', 'Configured via admin/security.php and admin/system/security.php:841/842/845/851 (admin UI/status display), and read in blockedlog/lib/securitycore.lib.php:238/333 and adherents/class/adherent.class.php:3076.', 'If set to ''password_hash'', the recommended PHP password_hash()/password_verify() functions are used for hashing/verifying; otherwise legacy hashing (e.g. md5) is used per the code checks.', 'recommended value is ''password_hash''', 0, 0, 'admin/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php', 1, '80c0a7a8d2e9a41ed6ee4359a408d662d8c4fb88462e4d35ada0caccf69bb906', 'v2', '2026-07-24T06:41:12+00:00', '["blockedlog/lib/securitycore.lib.php:217|*  If constant MAIN_SECURITY_HASH_ALGO is defined, we use this function as hashing function (recommended value is ''password_hash'')", "blockedlog/lib/securitycore.lib.php:222|* ''auto'' or ''0'': will use MAIN_SECURITY_HASH_ALGO else md5"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_MAXFILESIZE_DOWNLOADED', 'string', NULL, 'admin', 'Sets the maximum file size (in bytes) allowed for file downloads.', 'Configured via admin/security_file.php:108 and read at webportal/controllers/document.controller.class.php:267, core/lib/geturl.lib.php:163, and webportal/controllers/viewimage.controller.class.php:278 as ''$fileSizeMax = getDolGlobalInt(''MAIN_SECURITY_MAXFILESIZE_DOWNLOADED'')''. Also displayed in admin/system/security.php:638.', 'Setting a positive integer limits file downloads to that size in bytes; setting to 0 or leaving empty disables the size check.', '0 or not set = no file size limit enforced; positive integer = maximum allowed download size in bytes.', 0, 0, 'admin/security_file.php|admin/system/security.php|admin/security_file.php', 1, '6d6248563eb1db4d0db8b2b26275b7f7a6fe7b02658e87881d0a8fd0d967ceb1', 'v2', '2026-04-21T11:16:15+00:00', '["webportal/controllers/document.controller.class.php:267|read|$fileSizeMax = getDolGlobalInt(''MAIN_SECURITY_MAXFILESIZE_DOWNLOADED'');", "core/lib/geturl.lib.php:163|read|$maxsize = getDolGlobalInt(''MAIN_SECURITY_MAXFILESIZE_DOWNLOADED'');", "admin/security_file.php:108|write|$res8 = dolibarr_set_const($db, \"MAIN_SECURITY_MAXFILESIZE_DOWNLOADED\", GETPOST(''MAIN_SECURITY_MAXFILESIZE_DOWNLOADED'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/system/security.php:638|read|print ''<strong>''.$langs->trans(\"MAIN_SECURITY_MAXFILESIZE_DOWNLOADED\").''</strong> = ''.getDolGlobalString(''MAIN_SECURITY_MAXFILESIZE_DOWNLOADED'',"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_MAX_ATTACHMENT_ON_FORMS', 'string', NULL, 'admin', 'Maximum number of file attachments permitted per form submission.', 'Written via admin/security_other.php:92 and displayed at line 204 and admin/system/security.php:552. Enforced in core/lib/files.lib.php:2029 where it is read with a fallback default of 10 into $maxfilesinform.', 'Lowering this value restricts the number of files a user can attach to a single form; raising it allows more attachments, defaulting to 10 if unset.', 'Integer count of attachments per form. Default fallback is 10.', 0, 0, 'admin/security_other.php|admin/system/security.php|admin/security_other.php', 1, '8dd246f8a5d217253e86f18a9ea68a342f0161ed2e65a11c5a204e1edd6ff920', 'v2', '2026-04-21T13:29:58+00:00', '["admin/security_other.php:92|write|$res5 = dolibarr_set_const($db, \"MAIN_SECURITY_MAX_ATTACHMENT_ON_FORMS\", GETPOST(\"MAIN_SECURITY_MAX_ATTACHMENT_ON_FORMS\", ''alphanohtml''), ''int'', 0, '''', $conf->entity);", "core/lib/files.lib.php:2029|read|$maxfilesinform = getDolGlobalInt(\"MAIN_SECURITY_MAX_ATTACHMENT_ON_FORMS\", 10);", "admin/security_other.php:204|read|print ''<input class=\"flat right width50\" name=\"MAIN_SECURITY_MAX_ATTACHMENT_ON_FORMS\" type=\"text\" value=\"''.getDolGlobalInt(\"MAIN_SECURITY_MAX_ATTACHMENT_ON_FORMS\", 10).''\">''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_MAX_IMG_IN_HTML_CONTENT', 'string', NULL, 'admin', 'Maximum number of images permitted in HTML content before the content is rejected for security reasons.', 'Written via admin/security_other.php:86, displayed in the security admin UI at line 188 and admin/system/security.php:544. Enforced in core/lib/functions.lib.php:9816 where $nblinks is compared against this constant with a fallback default of 1000.', 'Lowering this value restricts how many images can appear in user-submitted HTML, reducing the attack surface for image-based injection; raising it or leaving it unset allows up to 1000 images by default.', 'Integer count of images. Default fallback is 1000. 0 = no images allowed.', 0, 0, 'admin/security_other.php|admin/system/security.php|admin/security_other.php', 1, '35f17ccfd38a4a0e99b93cf4bea8fa6f417b1580aab803e5d984fa1cf1b16672', 'v2', '2026-04-21T13:29:58+00:00', '["admin/security_other.php:86|write|$res3 = dolibarr_set_const($db, \"MAIN_SECURITY_MAX_IMG_IN_HTML_CONTENT\", GETPOST(\"MAIN_SECURITY_MAX_IMG_IN_HTML_CONTENT\", ''alphanohtml''), ''int'', 0, '''', $conf->entity);", "core/lib/functions.lib.php:9816|check|if ($nblinks > getDolGlobalInt(\"MAIN_SECURITY_MAX_IMG_IN_HTML_CONTENT\", 1000)) {", "admin/security_other.php:188|read|print ''<input class=\"flat right width50\" name=\"MAIN_SECURITY_MAX_IMG_IN_HTML_CONTENT\" type=\"text\" value=\"''.getDolGlobalInt(''MAIN_SECURITY_MAX_IMG_IN_HTML_CONTENT'').''\">''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_MAX_NUMBER_FAILED_AUTH', 'string', NULL, 'admin', 'Sets the maximum number of consecutive failed authentication attempts before a login is blocked.', 'Written via admin/security_other.php:95 and read at line 212 with a default of 100. Checked in core/login/functions_dolibarr.php:73: if ($nbevents <= getDolGlobalInt(''MAIN_SECURITY_MAX_NUMBER_FAILED_AUTH'', 100)).', 'Lowering this value makes the brute-force lockout trigger sooner. Raising it allows more failed attempts before blocking. If unset, the default of 100 applies.', 'Integer. Default: 100 when unset.', 0, 0, 'admin/security_other.php|admin/security_other.php', 1, '21d8bd6a367fd315535709389efc5d1b7051cef45b2e1c66c49fd1df36eb4cd7', 'v2', '2026-04-21T13:29:58+00:00', '["core/login/functions_dolibarr.php:73|check|if ($nbevents <= getDolGlobalInt(\"MAIN_SECURITY_MAX_NUMBER_FAILED_AUTH\", 100)) {", "admin/security_other.php:95|write|$res6 = dolibarr_set_const($db, \"MAIN_SECURITY_MAX_NUMBER_FAILED_AUTH\", GETPOST(\"MAIN_SECURITY_MAX_NUMBER_FAILED_AUTH\", ''alphanohtml''), ''int'', 0, '''', $conf->entity);", "admin/security_other.php:212|read|print ''<input class=\"flat right width50\" name=\"MAIN_SECURITY_MAX_NUMBER_FAILED_AUTH\" type=\"text\" value=\"''.getDolGlobalInt(\"MAIN_SECURITY_MAX_NUMBER_FAILED_AUTH\", 100).''\">''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_MAX_POST_ON_PUBLIC_PAGES_BY_IP_ADDRESS', 'string', NULL, 'public', 'Maximum number of POST requests allowed per IP address on public-facing pages before the request is blocked.', 'Written via admin/security_other.php:89 and displayed at line 196 and admin/system/security.php:548. Read with a fallback default of 200 across multiple public pages: public/recruitment/view.php:233, public/eventorganization/attendee_new.php:325, public/company/new.php:222, public/opensurvey/studs.php:110/166. The COMMENTS note its purpose: ''Test MAIN_SECURITY_MAX_POST_ON_PUBLIC_PAGES_BY_IP_ADDRESS''.', 'Lowering this value tightens rate-limiting on public forms, reducing abuse risk; raising it or leaving unset defaults to 200 allowed POSTs per IP.', 'Integer count of POST requests per IP. Default fallback is 200.', 0, 0, 'admin/security_other.php|admin/system/security.php|admin/security_other.php', 1, 'b5e60986fb663b8ef5e64778006e6efc1264661e89c5d16465b3c1447c7be297', 'v2', '2026-04-21T13:29:58+00:00', '["// Test MAIN_SECURITY_MAX_POST_ON_PUBLIC_PAGES_BY_IP_ADDRESS", "admin/security_other.php:89|write|$res4 = dolibarr_set_const($db, \"MAIN_SECURITY_MAX_POST_ON_PUBLIC_PAGES_BY_IP_ADDRESS\", ...)", "public/recruitment/view.php:233|read|$nb_post_max = getDolGlobalInt(\"MAIN_SECURITY_MAX_POST_ON_PUBLIC_PAGES_BY_IP_ADDRESS\", 200);", "public/eventorganization/attendee_new.php:325|read|$nb_post_max = getDolGlobalInt(\"MAIN_SECURITY_MAX_POST_ON_PUBLIC_PAGES_BY_IP_ADDRESS\", 200);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_SALT', 'string', NULL, 'blockedlog', 'Holds the cryptographic salt value appended when hashing passwords with non-password_hash algorithms.', 'Set to a random value during installation in install/step5.php:287 (dol_print_date(dol_now(), ''dayhourlog'')), and read in blockedlog/lib/securitycore.lib.php:257/258 and displayed in admin/security.php:506 and admin/system/security.php:846.', 'Used only when the hashing algorithm is something other than ''password_hash''; the salt string is prepended to the value before hashing.', NULL, 0, 0, 'admin/security.php|admin/system/security.php', 1, 'ab8fd89206fccf5b9000da778ee13f9ccd19cc842c0a57295bdebaab1ba7256a', 'v2', '2026-07-24T06:41:12+00:00', '["blockedlog/lib/securitycore.lib.php:218|*  If constant MAIN_SECURITY_SALT is defined, we use it as a salt (used only if hashing algorithm is something else than ''password_hash'').", "install/step5.php:32|*         It creates the login admin and set the MAIN_SECURITY_SALT to a random value."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_SHOW_MORE_INFO', 'bool', NULL, 'admin', 'Shows extra PHP configuration details (auto_prepend_file, sendmail_path) on the Security diagnostics admin page.', 'Read at admin/system/security.php:152 (module admin, page admin/system/security.php); when true, two additional ''strong'' lines print the values of ini_get(''auto_prepend_file'') and ini_get(''sendmail_path'').', 'Enabling it reveals PHP auto_prepend_file and sendmail_path settings on the security info page, which can expose server configuration details to whoever can view that admin page.', 'Boolean: true/1 shows the extra PHP info lines, false/unset (default) hides them.', 0, 0, 'admin/system/security.php', 1, 'bbe57f66c00d81147adb7f10d0242bcb6769b818414fd8fe778f315fd80a09a0', 'v2', '2026-07-24T07:05:23+00:00', '["admin/system/security.php:152|check|if (getDolGlobalString(''MAIN_SECURITY_SHOW_MORE_INFO'')) { print \"<strong>PHP auto_prepend_file</strong> = \"..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_USE_DEFAULT_PERMISSIONS', 'bool', NULL, 'core', 'Shows/hides the ''Default Rights'' admin tab (admin/perms.php) under Security setup.', 'core/lib/admin.lib.php:931: `if (getDolGlobalString(''MAIN_SECURITY_USE_DEFAULT_PERMISSIONS'')) { $head[$h][0] = dolBuildUrl(DOL_URL_ROOT."/admin/perms.php"); $head[$h][1] = $langs->trans("DefaultRights"); ... }` — the tab is only added to the security admin page head array when this is truthy.', 'Setting it to a truthy value adds a ''Default Rights'' tab (listing default permission counts per group/user template) to the security settings pages; leaving it unset hides that tab.', 'Truthy = show ''Default Rights'' admin tab; 0/unset = tab hidden (default).', 0, 0, NULL, 1, '31dd4114b75c9689fd6e37c9fbf36108b44acfb3683192370a00d3ea341577bd', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/admin.lib.php:931: if (getDolGlobalString(''MAIN_SECURITY_USE_DEFAULT_PERMISSIONS'')) {", "core/lib/admin.lib.php:933: $head[$h][1] = $langs->trans(\"DefaultRights\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SECURITY_USE_SANDBOX_FOR_HTMLWITHNOJS', 'bool', NULL, 'core', 'Would enable iframe-sandbox based sanitizing of raw HTML shown without JS, but this feature is explicitly marked not-yet-working.', 'In core/lib/functions.lib.php:9547-9553 (dol_htmlwithnojs), the docblock states ''Allow use of option MAIN_SECURITY_USE_SANDBOX_FOR_HTMLWITHNOJS for html sanitizing (not yet working)''; the code path wraps content in a commented-out `<iframe sandbox>` block and currently just returns $stringtoencode unchanged with a ''TODO using sandbox on inline html content is not possible yet with current browsers'' comment.', 'Setting it currently has no functional effect beyond taking the early-return branch, since the actual sandbox iframe output is commented out; the feature is documented as not yet working.', 'Boolean-like flag intended to allow sandboxed HTML rendering, but non-functional per code comments (''not yet working'').', 1, 0, NULL, 1, 'cf06c58a9a7ab68bd2995ee861c99a683b600854b651d7ad82e4b3c4db897439', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:9547|comment|@param int $nouseofiframesandbox 0=Default, 1=Allow use of option MAIN_SECURITY_USE_SANDBOX_FOR_HTMLWITHNOJS for html sanitizing (not yet working)", "core/lib/functions.lib.php:9553|check|if (empty($nouseofiframesandbox) && getDolGlobalString(''MAIN_SECURITY_USE_SANDBOX_FOR_HTMLWITHNOJS'')) {", "// TODO using sandbox on inline html content is not possible yet with current browsers"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SEE_SUBORDINATES', 'string', NULL, 'core', 'Allows a manager to see records (interventions, orders, etc.) belonging to their subordinate users.', 'Checked across 7 occurrences in fichinter/list.php:73 and 362, core/lib/security.lib.php:1108 and 1219, core/class/commonobject.class.php:2609, and commande/list.php:86 and 1027. When enabled and $userschilds is populated, subordinates'' records are included in lists.', 'Enabling this constant expands list views so managers see records assigned to users below them in the hierarchy, in addition to their own.', 'Boolean/truthy: non-empty enables subordinate visibility.', 1, 0, NULL, 1, '32b291af0902ab9e8d3178b0e88d91287e4a1d8bee432240327f59c1c348991a', 'v2', '2026-04-21T11:16:15+00:00', '["if (getDolGlobalInt(''MAIN_SEE_SUBORDINATES'')) {", "if (getDolGlobalInt(''MAIN_SEE_SUBORDINATES'') && $userschilds) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SERVER_TZ', 'string', NULL, 'admin', 'Stores the server timezone identifier used by Dolibarr for date/time operations.', 'Displayed in admin/system/dolibarr.php:326 as a system information label. A commented example in core/class/conf.class.php:682 shows the expected format: //$this->global->MAIN_SERVER_TZ=''Europe/Paris'';', 'If not defined, the timezone is reported as ''NotDefined'' in the system information page.', 'String: a valid PHP timezone identifier, e.g. ''Europe/Paris''.', 0, 0, 'admin/system/dolibarr.php', 1, 'c91e082d9d1b789e80218ac20aef75573d0a3c5e8557ed1798564642ee87a02d', 'v2', '2026-04-21T13:50:40+00:00', '["admin/system/dolibarr.php:326|read|$txt .= $langs->trans(\"Dolibarr constant MAIN_SERVER_TZ\").'': ''.getDolGlobalString(''MAIN_SERVER_TZ'', $langs->trans(\"NotDefined\"));", "core/class/conf.class.php:682  //$this->global->MAIN_SERVER_TZ=''Europe/Paris'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SESSION_TIMEOUT', 'string', NULL, 'admin', 'Sets the user session timeout duration in seconds for the Dolibarr application.', 'Configurable via admin/security_other.php (write at lines 83, 168, 180) and admin/system/security.php (write at line 532, display at line 540). Enforced at admin/security_other.php line 83 with bounds: max(120, min(3600*24, value)). Also applied in public/webportal/webportal.main.inc.php line 228.', 'Changing this value alters how long inactive sessions remain valid; the minimum enforced value is 120 seconds and the maximum is 86400 seconds (24 hours).', 'Integer (seconds); minimum 120, maximum 86400. From admin/security_other.php:83: dolibarr_set_const($db, "MAIN_SESSION_TIMEOUT", max(120, min(3600 * 24, GETPOSTINT("MAIN_SESSION_TIMEOUT"))), ''chaine'', 0, '''', $conf->entity);', 0, 0, 'admin/security_other.php|admin/security_other.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/security_other.php|admin/security_other.php', 1, '0c9aa2418285b5a671f7dcf24baf8984ea7675df1ef4ba8d7069348581cfc294', 'v2', '2026-04-21T13:29:58+00:00', '["admin/security_other.php:83|write|$res2 = dolibarr_set_const($db, \"MAIN_SESSION_TIMEOUT\", max(120, min(3600 * 24, GETPOSTINT(\"MAIN_SESSION_TIMEOUT\"))), ''chaine'', 0, '''', $conf->entity);\t// Between 120 and 86400", "admin/security_other.php:180|read|print ''<input class=\"flat right width75\" name=\"MAIN_SESSION_TIMEOUT\" type=\"text\" value=\"''.getDolGlobalInt(''MAIN_SESSION_TIMEOUT'').''\">.strtolower($langs->trans(\"Seconds\"));", "admin/system/security.php:540|read|print '': ''.getDolGlobalInt(''MAIN_SESSION_TIMEOUT'').'' ''.strtolower($langs->trans(\"Seconds\"));", "public/webportal/webportal.main.inc.php:228|check|if (getDolGlobalString(''MAIN_SESSION_TIMEOUT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SETUP_MODULES_DESC', 'string', NULL, 'admin', 'Forces the descriptive help text/legend to be shown at the top of the Modules setup admin page.', 'Checked in admin/modules.php:761, combined via OR with a check that fewer than MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING modules are enabled; when either is true, the help block ($deschelp) explaining the enable/disable and setup icons is displayed.', 'Enabling it always shows the modules-page legend/help text, even when enough modules are already enabled (normally the legend only shows when few modules are enabled).', 'Boolean-like: any truthy value forces display of the modules setup description block.', 0, 0, 'admin/modules.php', 1, '9527e578eeae81ada320a1f9e1e5e455702f4939f006fda3afcad93d5eb7bddb', 'v2', '2026-07-24T07:05:23+00:00', '["admin/modules.php:761: if (getDolGlobalInt(''MAIN_SETUP_MODULES_DESC'') || $nbmodulesnotautoenabled < getDolGlobalInt(''MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING'', 1)) {\t// If only minimal initial modules enab"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SETUP_MODULES_INFO', 'string', NULL, 'admin', 'Defines a translation key for a custom informational message displayed on the modules setup page.', 'Read in admin/modules.php:730-731. The code comment states: ''Add a custom info message. A good usage for SaaS in combination with option MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING.'' The value is passed through $langs->trans() to produce the rendered message.', 'Setting this to a valid translation key causes a custom info banner to appear on the modules admin page, useful for SaaS deployments to guide users.', 'A translation key string whose translated value is shown as an info message; empty or unset = no custom message', 0, 0, 'admin/modules.php|admin/modules.php', 1, '59bbea8676fb2f62d6400be1fa7d423da5974f45fba31a103291ef179e340808', 'v2', '2026-04-21T13:29:58+00:00', '["admin/modules.php:730|check|if (getDolGlobalString(''MAIN_SETUP_MODULES_INFO'')) {  // Add a custom info message. A good usage for SaaS in combination with option MAIN_MIN_NB_ENABLED_MODULE_FOR_WARNING.", "admin/modules.php:731|read|$deschelp .= ''<div class=\"info\">''.$langs->trans(getDolGlobalString(''MAIN_SETUP_MODULES_INFO'')).\"<br></div>\\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOWDATABASENAMEINHELPPAGESLINK', 'bool', NULL, 'core', 'Shows the current database name next to the version/help info in the top-right menu.', 'In main.inc.php:2421, when set, Dolibarr appends ''Database: <db name>'' to the version/help tooltip text ($appli) shown in the header.', 'Setting it exposes the database name in the UI (visible near the help/version link), which is mainly a debugging/support aid but does disclose internal DB naming to anyone viewing the page.', 'Boolean-like: truthy displays the database name in the help/version area.', 0, 0, NULL, 1, 'e4aa3e534f33a1ed4dde84ee16fc2e77dcc665f96bb97201d60b5c1f28a93d81', 'v2', '2026-07-24T07:05:23+00:00', '["main.inc.php:2421|check|if (getDolGlobalString(''MAIN_SHOWDATABASENAMEINHELPPAGESLINK'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_ALL_FILES_ON_DOCUMENT_TOOLTIP', 'bool', NULL, 'webportal', 'When enabled, forces document tooltips to display all attached files rather than only a subset.', 'Checked in core/class/html.formfile.class.php:1182 and webportal/class/html.formwebportal.class.php:248. When the flag $allfiles is false, this constant can override it to show all files.', 'Enabling this constant causes all files to be included in document tooltips across the standard UI and the web portal.', 'Truthy (non-empty) to show all files; empty/unset to respect the default $allfiles flag.', 1, 0, NULL, 1, 'edaed58476222255daa4c11bf90ee599509faef8ffd18da78c609b14e40107f7', 'v2', '2026-04-21T11:16:15+00:00', '["webportal/class/html.formwebportal.class.php:248|check|if ($allfiles || getDolGlobalString(''MAIN_SHOW_ALL_FILES_ON_DOCUMENT_TOOLTIP'')) {", "core/class/html.formfile.class.php:1182|check|if ($allfiles || getDolGlobalString(''MAIN_SHOW_ALL_FILES_ON_DOCUMENT_TOOLTIP'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_COMPANY_NAME_IN_BANNER_ADDRESS', 'bool', NULL, 'core', 'Adds the linked thirdparty''s company name above a contact''s name/address in the object banner''s copy-to-clipboard address block.', 'Checked in core/class/commonpeople.class.php:212: `if ($this->element == ''contact'' && getDolGlobalString(''MAIN_SHOW_COMPANY_NAME_IN_BANNER_ADDRESS'')) { $namecoords .= $object->name.''<br>''; }`, only applied when the current element is a contact.', 'When set, the banner''s clipboard-copy address text for a contact includes the parent company''s name as a prefix line, in addition to the contact''s own name and coordinates.', 'Truthy/falsy flag; effective only for element == ''contact''.', 1, 0, NULL, 1, '2b60f2ef8f548b529145c1c97fe6ab69c23b4516e136ef3810dc806e23257dc2', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonpeople.class.php:212|check|if ($this->element == ''contact'' && getDolGlobalString(''MAIN_SHOW_COMPANY_NAME_IN_BANNER_ADDRESS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_ECOTAX_DICTIONNARY', 'bool', NULL, 'admin', 'Forces the Ecotax dictionary entry to show in Setup > Dictionaries even when the ecotax module is disabled.', 'Used in admin/dict.php:566 as part of the condition that decides whether the DICT_ECOTAXE dictionary tab is displayed: shown if the product module is enabled AND (ecotax module enabled OR this constant is set).', 'Setting it makes the Ecotax dictionary visible in the dictionaries list even without the ecotax module active; it does not enable ecotax calculation itself.', 'Boolean-like: truthy shows the DICT_ECOTAXE row in admin/dict.php regardless of the ecotax module state.', 0, 0, 'admin/dict.php', 1, 'e38f589b013e4e8475a5b67450972c81137f610b56f474b86253c241f16189a7', 'v2', '2026-07-24T07:05:23+00:00', '["admin/dict.php:566|read|$tabcond[DICT_ECOTAXE] = (isModEnabled(\"product\") && (isModEnabled(''ecotax'') || getDolGlobalString(''MAIN_SHOW_ECOTAX_DICTIONNARY'')));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_EXTREF', 'bool', NULL, 'compta', 'Shows an editable ''External reference'' (RefExt) field on the cheque deposit slip (RemiseCheque) card, otherwise hidden by default.', 'Read in compta/paiement/cheque/card.php:668, guarding a block that prints the RefExt row; the inline comment states ''Ext ref are not visible field on standard usage''.', 'When enabled, the cheque remittance card displays and allows editing of an external reference field that is otherwise not shown in standard usage.', 'Boolean-like: truthy shows the RefExt field/row on the cheque remittance card.', 1, 0, NULL, 1, '1470bf2c43ebab0a7f125e370ccb8a13c3bf883a0b572c01f0de0bccc8a12e9d', 'v2', '2026-07-24T07:05:23+00:00', '["compta/paiement/cheque/card.php:668: // External ref - Ext ref are not visible field on standard usage", "compta/paiement/cheque/card.php:668: if (getDolGlobalString(''MAIN_SHOW_EXTREF'')) { print ''<tr><td>''; ... }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_FACNUMBER_IN_DISCOUNT_LIST', 'bool', NULL, 'core', 'Appends the source invoice''s reference number to each entry of the discount/credit-note selection list.', 'core/class/html.form.class.php:2588: `if (getDolGlobalString(''MAIN_SHOW_FACNUMBER_IN_DISCOUNT_LIST'') && !empty($obj->fk_facture_source)) { $tmpfac = new Facture($this->db); if ($tmpfac->fetch($obj->fk_facture_source) > 0) { $desc = $desc . '' - '' . $tmpfac->ref; } }` in the discount/credit-note dropdown builder.', 'Setting it to a truthy value adds an extra database fetch of the source Facture per discount line and appends its ref to the displayed label, e.g. for excess-paid/excess-received discounts linked to an invoice.', 'Truthy = append '' - <invoice ref>'' to discount option labels when linked to a source invoice; 0/unset = label unchanged (default).', 0, 0, NULL, 1, '1b7eec7e243e017f89a051fd17a978b84c2cf87eb11a1b80f9fd082fbdc56f63', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:2588: if (getDolGlobalString(''MAIN_SHOW_FACNUMBER_IN_DISCOUNT_LIST'') && !empty($obj->fk_facture_source)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_GLOBAL_REF_CUSTOMER_SUPPLIER', 'bool', NULL, 'compta', 'Widens the customer-reference column in the invoice list to show the full reference instead of truncating it.', 'Used in compta/facture/list.php:2492: `$tdcss = (getDolGlobalInt(''MAIN_SHOW_GLOBAL_REF_CUSTOMER_SUPPLIER'') ? ''class="minwidth400 maxwidth400"'' : ''class="nowrap tdoverflowmax200"'');` applied to the customer ref (ref_client) table cell.', 'When enabled, the ''Customer ref'' column of the invoice list uses a wider (400px min/max) non-truncating layout instead of the default 200px overflow-truncated cell.', 'Boolean (getDolGlobalInt): 1/true widens the customer ref column (minwidth400/maxwidth400, no truncation); 0/unset uses the default narrower truncating column (nowrap tdoverflowmax200).', 1, 0, NULL, 1, '25aa1fec1158bf426997d00033ce97f083929444b07fe008e2fbde9ced750ed6', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/list.php:2492: $tdcss = (getDolGlobalInt(''MAIN_SHOW_GLOBAL_REF_CUSTOMER_SUPPLIER'') ? ''class=\"minwidth400 maxwidth400\"'' : ''class=\"nowrap tdoverflowmax200\"'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_HT_ON_SUMMARY', 'bool', NULL, 'core', 'Shows pre-tax (HT) amounts in addition to tax-inclusive amounts on the accounting summary dashboard.', 'Checked at 19 points in compta/index.php (e.g., lines 186, 258, 285, 335, 388, 416, 676, 736) to conditionally render HT columns or rows alongside standard totals. No admin UI is provided.', 'Enabling this constant adds pre-tax amount columns to the accounting summary dashboard, providing visibility into amounts before tax.', 'Non-empty/truthy = HT amounts shown on summary; empty/unset = only tax-inclusive amounts shown.', 1, 0, NULL, 1, 'e83c5c17702162f7678944b544a35220d514bbfb5a5f81992161bccde0e1a9e3', 'v2', '2026-04-21T11:16:15+00:00', '["compta/index.php:186|check|if (getDolGlobalString(''MAIN_SHOW_HT_ON_SUMMARY'')) {", "compta/index.php:258|check|if (getDolGlobalString(''MAIN_SHOW_HT_ON_SUMMARY'')) {", "compta/index.php:285|check|if (getDolGlobalString(''MAIN_SHOW_HT_ON_SUMMARY'')) {", "compta/index.php:335|check|if (getDolGlobalString(''MAIN_SHOW_HT_ON_SUMMARY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_INFO_ON_LINKED_ELEMENTS_OF_SITUATION_INVOICE', 'bool', NULL, 'core', 'Hidden option that shows, on the situation-invoice PDF, information about linked proposals/orders totals (workaround for split/merged situation invoices).', 'Used twice in core/modules/facture/doc/pdf_octopus.modules.php (lines 3478 and 3838) guarding a block that prints linked propal/order totals; the surrounding comment explains it is ''a hidden constant ... added to show it'' because the same proposal may be split across several invoices.', 'When enabled, the generated situation invoice PDF displays extra linked-proposal/order total lines that are otherwise omitted.', 'Truthy shows the linked-elements info block on the PDF; empty/0 hides it (default).', 1, 0, NULL, 1, 'e58d647bc3208f2073deed9a7ce40843b0d76297a37a82eaf5ccc1a14176acac', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/pdf_octopus.modules.php:3477: // TODO This part is bugged ... so a hidden constant is added to show it", "core/modules/facture/doc/pdf_octopus.modules.php:3478: if (getDolGlobalString(''MAIN_SHOW_INFO_ON_LINKED_ELEMENTS_OF_SITUATION_INVOICE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_INVALID_EMAIL_IN_LIST', 'bool', NULL, 'societe', 'Controls whether records with invalid-looking emails are shown/flagged in various list views.', 'Read across societe/list.php:2146, adherents/list.php:1527, user/list.php:1250, contrat/list.php:1200, resource/list.php:708, and contact/list.php:1807, with inline comments explaining performance and syntax-check intent.', 'When enabled (default 1 in several lists), lists check email syntax validity and show/hide the invalid marker; comments note this is done ''to avoid slow display'' or ''we check only syntax of emails''.', 'Default 1 in adherents/contrat/contact lists (checks only syntax of emails)', 0, 0, NULL, 1, 'a5f6ed79b317c80bcf9a03d30f462a2ddcb1bb32d486de4de7b958b359086b02', 'v2', '2026-07-24T06:41:12+00:00', '["$showinvalidemail = (int) !getDolGlobalInt(''MAIN_SHOW_INVALID_EMAIL_IN_LIST''); // to avoid slow display", "$showinvalidemail = getDolGlobalInt(''MAIN_SHOW_INVALID_EMAIL_IN_LIST'', 1); // in list, we check only syntax of emails"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_LANGUAGE_CODE', 'bool', NULL, 'core', 'Shows the language code (e.g. ''fr_FR'') alongside/instead of the translated language name in language selection dropdowns.', 'Checked in core/class/translate.class.php:954 inside the language list builder used to populate language combos; when $usecode==1 it''s forced anyway, but this constant lets code be shown even when $usecode!=1, producing labels like ''fr_FR: French''.', 'Enabling it changes how language options are labelled in language-picker dropdowns across the app, prefixing/showing the raw locale code instead of (or with) the plain language name.', 'Boolean-like: truthy shows ''code: Label'' format for languages; falsy/unset shows just the translated label (unless $usecode already forces code display).', 1, 0, NULL, 1, '7720072edc26265c0554c1b132dbb04ca2fd95b764904a9a5750a7ae7a947446', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/translate.class.php:954|check|if ($usecode == 1 || getDolGlobalString(''MAIN_SHOW_LANGUAGE_CODE'')) {", "$langs_available[$dir] = $dir . '': '' . dol_trunc($this->trans(''Language_'' . $dir), $maxlength);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_LOGIN', 'bool', NULL, 'core', 'Adds the user''s login name to the extra-info parentheses shown next to user names in user-selection dropdowns.', 'Confirmed in two files: core/class/html.form.class.php:2911 `if (getDolGlobalString(''MAIN_SHOW_LOGIN'')) { $moreinfo .= ($moreinfo ? '' - '' : '' (''); ... $moreinfo .= $obj->login; }` inside select_dolusers(), and core/class/html.formother.class.php:625 with the same pattern.', 'Setting it to a truthy value appends the user''s login (e.g. ''(jsmith)'') to the displayed label in user dropdowns/comboboxes across at least two form-building classes, in addition to full name.', 'Truthy = show login in the ''(...)'' extra-info suffix of user selection labels; 0/unset = login not shown (default).', 0, 0, NULL, 1, '7fd443a58b068119bf11f39a1813aae234fa03b7451f39f169a0d4bf632ada07', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:2911: if (getDolGlobalString(''MAIN_SHOW_LOGIN'')) {", "core/class/html.formother.class.php:625: if (getDolGlobalString(''MAIN_SHOW_LOGIN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_LOGO', 'bool', NULL, 'core', 'Controls whether the company logo is displayed in the menu header area.', 'Checked in core/menus/standard/eldy.lib.php:579, core/menus/standard/auguria.lib.php:162, and main.inc.php:3510 to display the logo. Set to 0 in menu files eldy_menu.php:179 and auguria_menu.php:179 under certain conditions.', 'Enabling this shows the company logo in the menu header alongside the navigation; disabling it hides it.', '0 = logo hidden; 1 (truthy) = logo shown (requires MAIN_INFO_SOCIETE_LOGO to be set)', 1, 0, NULL, 1, '7c9654edc14278b3fc2679ff36471772523fd9fa2e2126675c28ad2743db7299', 'v2', '2026-04-21T11:16:15+00:00', '["core/menus/standard/eldy.lib.php:579|check|if (!getDolGlobalString(''MAIN_MENU_INVERT'') && getDolGlobalString(''MAIN_SHOW_LOGO'') && !getDolGlobalString(''MAIN_OPTIMIZEFORTEXTBROWSER'')) {", "main.inc.php:3510|check|if (getDolGlobalString(''MAIN_SHOW_LOGO'') && !getDolGlobalString(''MAIN_OPTIMIZEFORTEXTBROWSER'') && getDolGlobalString(''MAIN_INFO_SOCIETE_LOGO'')) {", "core/menus/standard/eldy_menu.php:179|write|$conf->global->MAIN_SHOW_LOGO = 0;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_ONLY_CODE_MULTICURRENCY', 'bool', NULL, 'compta', 'Shows only the currency code (instead of code + localized currency name) in the multicurrency column of the invoice list.', 'Used in compta/facture/list.php:2927: `if (!getDolGlobalString(''MAIN_SHOW_ONLY_CODE_MULTICURRENCY'') && !empty($obj->multicurrency_code)) { $title = $obj->multicurrency_code.'' - ''.$langs->transnoentitiesnoconv(''Currency''.$obj->multicurrency_code); ... } else { ... }` (else branch, not captured in payload, presumably shows the code alone).', 'When enabled, the currency label displayed in the invoice list''s multicurrency column is reduced to just the currency code, omitting the translated currency name.', 'Boolean (getDolGlobalString truthiness): truthy shows only the currency code; falsy/unset shows ''CODE - Currency name''.', 1, 0, NULL, 1, '6a94e379732531ef1c13c5e9141a1c9fb2b7053c9ed20abfd6ee8ab327b1712b', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/list.php:2927: if (!getDolGlobalString(''MAIN_SHOW_ONLY_CODE_MULTICURRENCY'') && !empty($obj->multicurrency_code)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_PASSWORD_INTO_LOG', 'bool', NULL, 'core', 'Controls whether password values are redacted before being written to the application log.', 'Checked in the log-writing function in core/lib/functions.lib.php:2817; when falsy (default), any "password=''...''" pattern in the log message is replaced with "password=''hidden''" via preg_replace, with inline comment ''protection to avoid to have value of password in log''.', 'Enabling it disables the automatic redaction, so plaintext password values embedded in log messages (matching the password=''...'' pattern) would be written to the log as-is; this is a security-sensitive setting.', 'Boolean: falsy/default (recommended) redacts password=''...'' to password=''hidden'' in log messages; truthy value disables this redaction.', 1, 0, NULL, 1, 'a18ad0850f760c6080139fc9502a9fc914801b6dd0aa715b1ad087827eff2fc5', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:2817|check|if (!getDolGlobalString(''MAIN_SHOW_PASSWORD_INTO_LOG'')) {", "// protection to avoid to have value of password in log"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_PERMISSION', 'bool', NULL, 'admin', 'Enables a debug helper on the modules admin page that flags module permissions with missing language translations.', 'Checked in admin/system/modules.php:406, inside the permission-column rendering of the modules list: if set, and the translation key ''Permission<permission>'' is missing, a warning icon with tooltip ''Missing translation (key ... not found in admin.lang)'' is appended.', 'When enabled, admins see a warning icon next to any module permission whose translation string is missing, aiding translation debugging; has no effect on functional permissions themselves.', 'Boolean-like: truthy shows missing-translation warnings on the modules admin page.', 0, 0, 'admin/system/modules.php', 1, '095698a7d904f7926d469e3f72fdb8b45d672f7e56a447ba24ee777d605b9b37', 'v2', '2026-07-24T07:05:23+00:00', '["admin/system/modules.php:406: if (getDolGlobalString(''MAIN_SHOW_PERMISSION'')) {", "admin/system/modules.php:407-409: tooltip ''Missing translation (key ''.$translationKey.'' not found in admin.lang)''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_PREVIEW_PICTO_EVEN_ON_PHONE', 'bool', NULL, 'core', 'Forces the document preview picto/link to be shown even when the browser layout is detected as ''phone''.', 'In core/class/html.formfile.class.php:2437, showPreview() only builds the advanced preview link if `($conf->browser->layout != ''phone'' || getDolGlobalString(''MAIN_SHOW_PREVIEW_PICTO_EVEN_ON_PHONE'')) && !empty($conf->use_javascript_ajax)` — i.e. normally the preview picto is suppressed on phone layout, unless this constant is set.', 'Enabling it makes the file preview picto/link appear on phone-layout browsers too, where it is otherwise hidden by default; still requires JS/ajax to be enabled.', 'Boolean-like: set/non-empty shows the preview picto on phone layout as well; unset (default) hides preview picto when browser layout is ''phone''.', 1, 0, NULL, 1, 'b9d5458e15c73391c464ac8f9ab85957663aaedb9c8bc6eb3c3db7ee69bf8829', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formfile.class.php:2437: if (($conf->browser->layout != ''phone'' || getDolGlobalString(''MAIN_SHOW_PREVIEW_PICTO_EVEN_ON_PHONE'')) && !empty($conf->use_javascript_ajax)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_PRICE_WITH_TAX_IN_SUMMARIES', 'bool', NULL, 'comm', 'Shows prices inclusive of tax in order and supplier order summary sections.', 'When set, additional tax-inclusive price rows are rendered in the summary panels of fourn/card.php (lines 891, 938) and comm/card.php (lines 1510, 1560, 1615, 1710). No admin UI writes are present in the payload.', 'Enabling this constant adds tax-inclusive price display to order summaries; disabling it hides those rows.', 'Truthy value shows tax-inclusive prices; absent or falsy hides them.', 1, 0, NULL, 1, '6fc616fbed6193c9a8b099a2574be0bdd0afa5f45f2a0da2541c1400632cf588', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/card.php:891|check|if (getDolGlobalString(''MAIN_SHOW_PRICE_WITH_TAX_IN_SUMMARIES'')) {", "fourn/card.php:938|check|if (getDolGlobalString(''MAIN_SHOW_PRICE_WITH_TAX_IN_SUMMARIES'')) {", "comm/card.php:1510|check|if (getDolGlobalString(''MAIN_SHOW_PRICE_WITH_TAX_IN_SUMMARIES'')) {", "comm/card.php:1560|check|if (getDolGlobalString(''MAIN_SHOW_PRICE_WITH_TAX_IN_SUMMARIES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_PRODUCT_ACTIVITY_TRIM', 'bool', NULL, 'product', 'Shows a per-quarter (trimester) turnover/activity report block on the product module''s index (dashboard) page.', 'Checked in product/index.php:675 together with the invoice module being enabled and the ''facture''/''lire'' right; when true, activitytrim(0) and/or activitytrim(1) are called to build activity data for products and/or services.', 'Enabling it adds a per-trimester activity/turnover summary to the products dashboard; the surrounding TODO comment notes the counting method used may not match all turnover-report conventions elsewhere in the app.', 'Boolean-like: any truthy value enables the per-trimester product activity block.', 1, 0, NULL, 1, '9db796531a9beafdeb9fe34d6480b3e012535752757a1af69bf25bc1510b83f0', 'v2', '2026-07-24T07:05:23+00:00', '["product/index.php:675: if (isModEnabled(\"invoice\") && $user->hasRight(''facture'', ''lire'') && getDolGlobalString(''MAIN_SHOW_PRODUCT_ACTIVITY_TRIM'')) {", "product/index.php:671: // TODO Move this into a page that should be available into menu \"accountancy - report - turnover - per quarter\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_REF_CUSTOMER_INVOICES', 'bool', NULL, 'comm', 'Shows the customer reference column in the invoice list on the commercial (customer) card.', 'Checked in comm/card.php at lines 1618 and 1690 to conditionally include the customer reference column in the invoices tab.', 'Enabling this constant adds a customer reference column to the invoices table on customer cards.', 'Truthy value = customer reference column shown; empty/unset = column hidden.', 1, 0, NULL, 1, 'd2051e57285236a15a9a645c85ab94f816fdef81c3a3e6327a554c0d255d70f6', 'v2', '2026-04-21T11:16:15+00:00', '["comm/card.php:1618|check|if (getDolGlobalString(''MAIN_SHOW_REF_CUSTOMER_INVOICES'')) {", "comm/card.php:1690|check|if (getDolGlobalString(''MAIN_SHOW_REF_CUSTOMER_INVOICES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_REGION_IN_STATE_SELECT', 'bool', NULL, 'core', 'Controls whether the region is displayed alongside the state/province in address selection dropdowns.', 'Checked in societe/card.php, contact/card.php, resource/class/html.formresource.class.php:367, and webportal/class/webportalmember.class.php:474 across 18 occurrences in multiple files. Values 1 and 2 both trigger region display; value 1 also passes through to getFullAddress calls.', 'Setting to 1 or 2 causes the region name to appear in state/province selection widgets; the exact difference between 1 and 2 is not documented in the payload.', '0 or unset = no region shown; 1 = show region; 2 = show region (alternate mode)', 1, 0, NULL, 1, '2d34fda83495646415985bc0dca5cda5f0afa5169f4dc78f1c350613a921f108', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:1654|check|if ((getDolGlobalInt(''MAIN_SHOW_REGION_IN_STATE_SELECT'') == 1 || getDolGlobalInt(''MAIN_SHOW_REGION_IN_STATE_SELECT'') == 2)) {", "webportal/class/webportalmember.class.php:474|check|if (getDolGlobalInt(''MAIN_SHOW_REGION_IN_STATE_SELECT'') == 1 && $this->region) {", "resource/class/html.formresource.class.php:367|check|if (getDolGlobalInt(''MAIN_SHOW_REGION_IN_STATE_SELECT'') == 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_STATE_CODE', 'bool', NULL, 'resource', 'Controls whether state/province codes are shown in address dropdowns alongside or instead of the full state name.', 'Read in resource/class/html.formresource.class.php:364-365 and core/class/html.formcompany.class.php:335-336. When set, the code checks for values 1, 2, or ''all'' to determine display mode.', 'Changing this value alters how state/province selections are displayed in address forms; setting it to 1, 2, or ''all'' enables code display while leaving it unset hides codes.', '1=show code (mode 1), 2=show code (mode 2), ''all''=show all codes; empty/unset=do not show state code', 1, 0, NULL, 1, 'bf9f7a5169587b76af1d2d06de2c52d7687504a87b3698c04ce1b5796e0bd213', 'v2', '2026-04-21T13:29:58+00:00', '["getDolGlobalString(''MAIN_SHOW_STATE_CODE'') &&", "(getDolGlobalInt(''MAIN_SHOW_STATE_CODE'') == 1 || getDolGlobalInt(''MAIN_SHOW_STATE_CODE'') == 2 || getDolGlobalString(''MAIN_SHOW_STATE_CODE'') === ''all'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_TECHNICAL_ID', 'bool', NULL, 'hrm', 'Controls whether the internal technical row ID (rowid) is displayed for records that otherwise hide it (e.g. product attributes, skills, HRM records).', 'Checked with !getDolGlobalString(''MAIN_SHOW_TECHNICAL_ID'') across 59 occurrences, e.g. variants/class/ProductAttribute.class.php:173, product/class/productfournisseurprice.class.php:273, knowledgemanagement/class/knowledgerecord.class.php:224, hrm/class/skill.class.php:207.', 'When enabled, the technical rowid field is shown/exposed for these object classes instead of being hidden by default.', NULL, 0, 0, NULL, 1, 'ec33976910d015ee43d71c1ab90e5fa4c309ad39f800c1507e2748b100630e23', 'v2', '2026-07-24T06:41:12+00:00', '["variants/class/ProductAttribute.class.php:173|check|if (!getDolGlobalString(''MAIN_SHOW_TECHNICAL_ID'') && isset($this->fields[''rowid''])) {", "hrm/class/skill.class.php:207|check|if (!getDolGlobalString(''MAIN_SHOW_TECHNICAL_ID'') && isset($this->fields[''rowid''])) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_TUNING_INFO', 'bool', NULL, 'core', 'Enables display of performance tuning information in the page footer or debug output.', 'Checked at core/lib/functions.lib.php:13223 against both the environment variable and this global constant. The comment at main.inc.php:45 states ''For optional tuning. Enabled if environment variable MAIN_SHOW_TUNING_INFO is defined.'' The docblock at line 13032 also lists this constant alongside the env var.', 'Setting this constant activates tuning/profiling output in pages; it can also be enabled via the server environment variable of the same name.', '0 or empty (and env var unset) = tuning info hidden; any truthy value or env var set = tuning info displayed', 1, 0, NULL, 1, '24dd3ce6662f45c01b0a98f9adacc20436967daeb510e1fc743a3b3e602049d5', 'v2', '2026-04-21T13:29:58+00:00', '["main.inc.php:45  // For optional tuning. Enabled if environment variable MAIN_SHOW_TUNING_INFO is defined.", "core/lib/functions.lib.php:13032  * \t\tjs for conf->global->MAIN_SHOW_TUNING_INFO or $_SERVER[\"MAIN_SHOW_TUNING_INFO\"]", "core/lib/functions.lib.php:13223|check|if (!empty($_SERVER[''MAIN_SHOW_TUNING_INFO'']) || getDolGlobalString(''MAIN_SHOW_TUNING_INFO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_UNSELECTABLES_IN_SELECT_INTERVENTIONS', 'bool', NULL, 'core', 'Controls whether non-selectable (e.g. already-used or wrong-status) interventions are still shown (greyed out) in the intervention selection combo.', 'Read in core/class/html.formintervention.class.php:73 at the top of select_interventions(), where $hideunselectables is initialized directly from this constant before the intervention list SQL is built and the combo populated.', 'The value of $hideunselectables (driven by this constant) determines whether unselectable interventions are hidden from or shown (typically disabled) in the dropdown; exact downstream effect beyond this assignment not traced further.', 'Integer/boolean-like via getDolGlobalInt: value assigned directly to $hideunselectables flag.', 1, 0, NULL, 1, '9f0d75bd978d956e7670906feb6b60455489b4c6f3016dfe7283d9b3e9a99dd6', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formintervention.class.php:73|read|$hideunselectables = getDolGlobalInt(''MAIN_SHOW_UNSELECTABLES_IN_SELECT_INTERVENTIONS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SHOW_VERSION', 'bool', NULL, 'core', 'Displays the Dolibarr version number in the page footer, distinct from MAIN_HIDE_VERSION.', 'Checked at main.inc.php:3335 together with MAIN_BUGTRACK_ENABLELINK, and independently at :3341 to output the version string. The comment at :3341 notes the version is already on the help picto and login page.', 'Enabling this adds an explicit version display in the footer area.', '0 or unset = version not shown via this constant; 1 (truthy) = version shown in footer', 1, 0, NULL, 1, 'c65d8475d029dee2a50ad217ebc4923d89d570afdc1071e9e0ad179577212deb', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:3335|check|if (getDolGlobalString(''MAIN_SHOW_VERSION'') || getDolGlobalString(''MAIN_BUGTRACK_ENABLELINK'')) {", "main.inc.php:3341|check|if (getDolGlobalString(''MAIN_SHOW_VERSION'')) {    // Version is already on help picto and on login page."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SIGN_CSS_URL', 'string', NULL, 'public', 'URL of a custom CSS stylesheet injected into the public online-signature page header.', 'Used in public/onlinesign/newonlinesign.php:240-241: if set, a <link> tag pointing to this URL is added to the page head with the current language appended as a query parameter.', 'Setting it lets an admin restyle the public document-signing page via an external stylesheet; leaving it empty means no extra CSS is loaded.', 'Any absolute or relative URL string to a CSS file.', 1, 0, NULL, 1, '81a3e91f3c51768e49b6486d7d1e5c1ef905e5cf69d50d4abb1bd38b233d0b03', 'v2', '2026-07-24T07:05:23+00:00', '["public/onlinesign/newonlinesign.php:240: if (getDolGlobalString(''MAIN_SIGN_CSS_URL'')) {", "public/onlinesign/newonlinesign.php:241: $head = ''<link rel=\"stylesheet\" type=\"text/css\" href=\"'' . getDolGlobalString(''MAIN_SIGN_CSS_URL'').''?lang=''.$langs->defaultlang.''\">''.\"\\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SIZE_LISTE_LIMIT', 'string', '10', 'admin', 'Sets the default number of rows displayed per page on standard list views.', 'Configured via admin/ihm.php:272 (dolibarr_set_const), checked/read in admin/ihm.php:466/467/470, admin/system/perf.php:723/724/726 (warns if it exceeds a recommended maximum), and user/param_ihm.php:474.', 'Increasing the value shows more rows per list page; admin/system/perf.php warns when the value exceeds $MAXRECOMMENDED for performance reasons. Default is ''10''.', NULL, 0, 0, 'admin/ihm.php|admin/ihm.php|admin/ihm.php|admin/system/perf.php|admin/system/perf.php|admin/system/perf.php|admin/ihm.php', 1, '251adc16abdaef2543d63746066a5e9869affc0691fe662e4c17764a2af804da', 'v2', '2026-07-24T06:41:12+00:00', '["admin/system/perf.php:723|check|if (getDolGlobalInt(''MAIN_SIZE_LISTE_LIMIT'') > $MAXRECOMMENDED) {", "admin/system/perf.php:724|read|print img_picto('''', ''warning'', ''class=\"pictofixedwidth\"'').'' ''.$langs->trans(\"YouHaveALargeAmountOfRecordOnLists\", getDolGlobalInt(''MAIN_SIZE_LISTE_LIMIT''), $MAXRECOMMENDED);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SIZE_SHORTLIST_LIMIT', 'string', '3', 'fourn', 'Sets the number of rows shown in short/summary lists on dashboard-style pages (e.g. supplier invoices, projects, donations, knowledge management).', 'Configured via admin/ihm.php:273 (dolibarr_set_const, admin UI) and read with getDolGlobalInt(''MAIN_SIZE_SHORTLIST_LIMIT'', 5) in fourn/card.php:487/608, projet/index.php:63, knowledgemanagement/knowledgemanagementindex.php:160, don/index.php:214, and fourn/facture/index.php:52.', 'Increasing the value shows more rows in these short/summary list widgets; the fallback default used across call sites is 5. Default constant value is ''3''.', NULL, 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '02b1da8a75a3def139e3d95a864a34d4b32d74170b37025a122263a962fc7e27', 'v2', '2026-07-24T06:41:12+00:00', '["fourn/card.php:487|read|$MAXLIST = getDolGlobalInt(''MAIN_SIZE_SHORTLIST_LIMIT'', 5);", "projet/index.php:63|read|$max = getDolUserInt(''MAIN_SIZE_SHORTLIST_LIMIT'', getDolGlobalInt(''MAIN_SIZE_SHORTLIST_LIMIT'', 5));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SIZE_SHORTLIST_LIMIT_LAST_MODIFIED_TICKETS', 'string', NULL, 'ticket', 'Overrides the number of rows fetched/shown in the ''Latest tickets'' shortlist widget on the ticket index page.', 'Used in ticket/index.php:386: `$tmpmax = getDolGlobalInt(''MAIN_SIZE_SHORTLIST_LIMIT_LAST_MODIFIED_TICKETS'', $max);` — used both as the display count in the ''LatestNewTickets'' title and (via $max, used earlier in the SQL plimit) to size the query result.', 'Increasing/decreasing the value changes how many recently-modified tickets are shown in that widget on the ticket dashboard/index page; default is whatever $max was set to elsewhere in the page.', 'Integer row count; falls back to the page''s default $max value if unset.', 1, 0, NULL, 1, '025fa5d394a9ce03acbbc97fc91671883ec91a8f1a949dfbab8e8030899e79be', 'v2', '2026-07-24T07:05:23+00:00', '["ticket/index.php:386: $tmpmax = getDolGlobalInt(''MAIN_SIZE_SHORTLIST_LIMIT_LAST_MODIFIED_TICKETS'', $max);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SMS_DEBUG', 'string', NULL, 'core', 'Enables debug logging in the SMS sending class (CSMSFile).', 'Checked in core/class/CSMSFile.class.php at lines 175, 221, and 228; when truthy, the class executes additional debug code paths during SMS dispatch.', 'Enabling this constant activates debug branches in the SMS class, which may produce additional log output. Disabling it suppresses those branches.', 'Truthy string to enable debug mode; empty/unset to disable.', 1, 0, NULL, 1, 'f0f686e9f3cb5a6c02fde3b57ac5e33d9046adef1e083fe56c2791228e6ebfd7', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/CSMSFile.class.php:228|check|if (getDolGlobalString(''MAIN_SMS_DEBUG'')) {", "core/class/CSMSFile.class.php:175|check|if (getDolGlobalString(''MAIN_SMS_DEBUG'')) {", "core/class/CSMSFile.class.php:221|check|if (getDolGlobalString(''MAIN_SMS_DEBUG'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SMS_FROM', 'string', NULL, 'admin', 'Stores the default sender phone number used for outgoing SMS messages.', 'Defines the global SMS sender address. Configured via admin/sms.php where it is written with dolibarr_set_const and displayed in the settings form. It is also validated against isValidPhone and used as the default ''from'' address in actioncomm.class.php when sending SMS.', 'Changing this value alters the sender number shown to recipients of SMS messages. If set to an invalid phone number, a validation warning is triggered in the admin UI.', 'A valid phone number string; validated by isValidPhone.', 0, 0, 'admin/sms.php|admin/sms.php|admin/sms.php|admin/sms.php|admin/sms.php', 1, 'db54f6f3a665d1088ce3bf75cf2ffaaf6bde1b2b6ce3faf02fe8cea8b19b68fb', 'v2', '2026-04-21T13:29:58+00:00', '["admin/sms.php:66|write|dolibarr_set_const($db, \"MAIN_SMS_FROM\", GETPOST(\"MAIN_SMS_FROM\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/sms.php:245|check|if (getDolGlobalString(''MAIN_SMS_FROM'') && !isValidPhone(getDolGlobalString(''MAIN_SMS_FROM''))) {", "admin/sms.php:280|read|$formsms->fromsms = (GETPOSTISSET(''fromsms'') ? GETPOST(''fromsms'') : getDolGlobalString(''MAIN_SMS_FROM'', $user->user_mobile));", "comm/action/class/actioncomm.class.php:3007|read|$from = getDolGlobalString(''MAIN_SMS_FROM'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SMS_SENDMODE', 'string', NULL, 'core', 'Selects the SMS sending provider module used by Dolibarr.', 'Stores the identifier of the active SMS sending method (e.g. a module name). Written via admin/sms.php:64, read by core/class/CSMSFile.class.php:182 which uses it to load the appropriate SMS driver. The comment on that line reads: ''$conf->global->MAIN_SMS_SENDMODE looks like a value ''module''''.', 'Changing this value switches the SMS backend; clearing it disables SMS sending entirely as CSMSFile.class.php:138 returns early when the constant is empty.', 'String: identifier of the SMS module/provider; empty/unset = SMS sending disabled.', 0, 0, 'admin/sms.php|admin/sms.php|admin/sms.php|admin/sms.php', 1, '67ee5006aa631387a3fc20d74a4e14dff313e61c50eff26168d048286d5e0bf3', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/CSMSFile.class.php:182|read|$sendmode = getDolGlobalString(''MAIN_SMS_SENDMODE'');  // $conf->global->MAIN_SMS_SENDMODE looks like a value ''module''", "core/class/CSMSFile.class.php:138|check|if (!getDolGlobalString(''MAIN_SMS_SENDMODE'')) {", "admin/sms.php:64|write|dolibarr_set_const($db, \"MAIN_SMS_SENDMODE\", GETPOST(\"MAIN_SMS_SENDMODE\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/sms.php:202|read|print $form->selectarray(''MAIN_SMS_SENDMODE'', $listofmethods, getDolGlobalString(''MAIN_SMS_SENDMODE''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SMTPS_ADD_TLS_TO_HOST_FOR_HELO', 'string', NULL, 'core', 'Appends ''tls'' to the SMTP hostname used in the HELO/EHLO command when TLS is active.', 'Checked in core/class/smtps.class.php:562 and :749; when TLS is in use and this constant is set, the host string for HELO is modified.', 'Enabling this constant alters the HELO hostname sent during TLS SMTP sessions, which may be required by some mail servers.', 'Bool-like string: empty/unset = HELO host unchanged; non-empty = ''tls'' appended to HELO host.', 1, 0, NULL, 1, 'f2813418c58b6e6acc621e8f2386c385df419095d98aeb6a084b313b03926faa', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/smtps.class.php:562|check|if ($usetls && getDolGlobalString(''MAIN_SMTPS_ADD_TLS_TO_HOST_FOR_HELO'')) {", "core/class/smtps.class.php:749|check|if ($usetls && getDolGlobalString(''MAIN_SMTPS_ADD_TLS_TO_HOST_FOR_HELO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SOCIETE_SHOW_COMPLETE_NAME', 'bool', NULL, 'societe', 'Disables the truncating CSS class on the thirdparty name/ref column in the thirdparty list, showing the full company name.', 'Read in societe/list.php:1987, where it conditionally omits the ''tdoverflowmax200'' CSS class (which truncates long text) on the thirdparty name table cell.', 'When enabled, thirdparty names are displayed in full in the list view instead of being truncated/overflow-clipped at ~200px width.', 'Boolean-like: truthy removes the tdoverflowmax200 truncation class from the name cell.', 1, 0, NULL, 1, 'cdc4ab47e2d651c58a28497fc48dc68a977a62cda53718ffd6bf65777edead62', 'v2', '2026-07-24T07:05:23+00:00', '["societe/list.php:1987: print ''<td''.(getDolGlobalString(''MAIN_SOCIETE_SHOW_COMPLETE_NAME'') ? '''' : '' class=\"tdoverflowmax200\"'').'' data-key=\"ref\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_START_WEEK', 'string', NULL, 'core', 'Sets the first day of the week for calendars and date pickers (0 = Sunday, 1 = Monday).', 'Read in core/lib/date.lib.php:684 and core/datepicker.php:227 to determine the week start day. A comment at projet/activity/perday.php:665 clarifies: ''For monday, must be 0 for monday if MAIN_START_WEEK = 1, must be 1 for monday if MAIN_START_WEEK = 0''. The admin UI at admin/ihm.php:282 writes the value and admin/ihm.php:490 renders the selector.', 'Changing this value shifts the starting column of all calendar and date-picker widgets across the application.', '0 = Sunday is first day of week; 1 = Monday is first day of week.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'b63b56a795434fffe00563a9639e05426b346f345c321edda7c7301b2d9d1038', 'v2', '2026-04-21T11:16:15+00:00', '["// For monday, must be 0 for monday if MAIN_START_WEEK = 1, must be 1 for monday if MAIN_START_WEEK = 0", "// numstartworkingday and numendworkingday are default start and end date of working days (1 means sunday if MAIN_START_WEEK is 0, 1 means monday if MAIN_START_WEEK is 1)", "core/lib/date.lib.php:684|read|$start_week = getDolGlobalInt(''MAIN_START_WEEK'', 1);", "core/datepicker.php:227|read|$startday = getDolGlobalInt(''MAIN_START_WEEK'', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_STATISTICS_IN_MENU', 'string', NULL, 'core', 'Adds statistics entries/links into the standard eldy menu across many modules.', 'Checked pervasively (22 occurrences) in core/menus/standard/eldy.lib.php, e.g. lines 1421, 1445, 1466, 1497, 1525, 1537, 1585, 1621, and more not shown.', 'When enabled, the eldy menu displays additional statistics menu entries throughout the application''s module menus.', NULL, 0, 0, NULL, 1, 'c7023fb4e022361cc721f44f14b06f1d4ae365432d8fa7860a9d03ae3d89d15b', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_STATISTICS_IN_MENU'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_STATS_GRAPHS_SHOW_N_YEARS', 'bool', NULL, 'adherents', 'Sets the number of past years included/plotted in statistics graphs across various modules.', 'Read across 18 occurrences, e.g. projet/stats/index.php:62, projet/tasks/stats/index.php:63, contrat/stats/index.php:96, commande/stats/index.php:95, ticket/stats/index.php:67, and adherents/stats/geo.php:58, computed as $year - (value clamped with max(1, min(10, value)), default 2 if unset).', 'If set, the statistics start year is $year minus this value (clamped between 1 and 10); if unset, it defaults to 2 years back.', 'value is clamped to the range 1-10 via max(1, min(10, ...)); default is 2 years when unset', 1, 0, NULL, 1, 'fa968a0a9e5d5d5d61e5f8c735f29358effa944a708542ca6d7457f776421ff0', 'v2', '2026-07-24T06:41:12+00:00', '["projet/stats/index.php:62|read|$startyear = $year - (!getDolGlobalString(''MAIN_STATS_GRAPHS_SHOW_N_YEARS'') ? 2 : max(1, min(10, getDolGlobalString(''MAIN_STATS_GRAPHS_SHOW_N_YEARS''))));", "contrat/stats/index.php:96|read|$startyear = $year - (!getDolGlobalInt(''MAIN_STATS_GRAPHS_SHOW_N_YEARS'') ? 2 : max(1, min(10, getDolGlobalInt(''MAIN_STATS_GRAPHS_SHOW_N_YEARS''))));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_STATUS_USES_IMAGES', 'string', NULL, 'core', 'Switches status badge rendering from CSS-based labels to image-based icons.', 'Read at core/lib/functions.lib.php:14408 and 14456. When set, the status rendering function selects an image-based output path; when unset and $displayMode is set, a CSS label path is used instead.', 'Enabling this constant replaces CSS status badges with image icons throughout the UI; disabling it uses the modern CSS-based status display.', '0 or empty = CSS-based status labels; any truthy value = image-based status icons', 1, 0, NULL, 1, '787f1deed3e544b08073e162767387a828a5de6b206d72053946e044d295128c', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:14408|read|} elseif (getDolGlobalString(''MAIN_STATUS_USES_IMAGES'')) {", "core/lib/functions.lib.php:14456|read|} elseif (!getDolGlobalString(''MAIN_STATUS_USES_IMAGES'') && !empty($displayMode)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_STORE_COMPUTED_EXTRAFIELDS', 'string', NULL, 'core', 'Controls whether computed extrafield values are persisted to the database instead of always being recalculated on display.', 'Checked with getDolGlobalString(''MAIN_STORE_COMPUTED_EXTRAFIELDS'') in core/tpl/extrafields_list_print_fields.tpl.php:82, core/class/commonobject.class.php:7013/7503, and core/tpl/admin_extrafields_edit.tpl.php:306 / admin_extrafields_add.tpl.php:231.', 'When enabled, the database-stored value of a computed extrafield is used instead of recomputing it on the fly for display.', NULL, 1, 0, NULL, 1, '761144751d1ed8c4c716243e8fbfec6c4078825c48489300d93dc14daa0a52e4', 'v2', '2026-07-24T06:41:12+00:00', '["core/tpl/extrafields_list_print_fields.tpl.php:80|// But when MAIN_STORE_COMPUTED_EXTRAFIELDS is enabled, the value stored in database is used instead,", "core/class/commonobject.class.php:7503|check|if (getDolGlobalString(''MAIN_STORE_COMPUTED_EXTRAFIELDS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_STORE_FULL_EVENT_IN_GMT', 'string', NULL, 'comm', 'Controls whether full-day agenda events are stored in GMT instead of local time.', 'Read into $tzforfullday in comm/action/peruser.php:896, comm/action/index.php:963, comm/action/card.php at lines 91, 374, 925, core/lib/xcal.lib.php:211, and comm/action/document.php at lines 250 and 264. The comment at core/lib/xcal.lib.php:209 states: ''Using option MAIN_STORE_FULL_EVENT_IN_GMT=1 change the behaviour to store in GMT for full day event.''', 'Setting this constant to 1 changes full-day event storage to use GMT, which affects how events are exported and displayed across timezones.', '1 = store full-day events in GMT; empty/unset = local time used.', 1, 0, NULL, 1, 'bdc0aae1fab0d2c5b93e889d53c3ecf7721b263435090ba2c9471786818aa0ad', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/xcal.lib.php:209  // Using option MAIN_STORE_FULL_EVENT_IN_GMT=1 change the behaviour to store in GMT for full day event. This must become", "comm/action/peruser.php:896|read|$tzforfullday = getDolGlobalString(''MAIN_STORE_FULL_EVENT_IN_GMT'');", "comm/action/index.php:963|read|$tzforfullday = getDolGlobalString(''MAIN_STORE_FULL_EVENT_IN_GMT'');", "comm/action/card.php:91|read|$tzforfullday = getDolGlobalString(''MAIN_STORE_FULL_EVENT_IN_GMT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SUBMODULE_DELIVERY', 'string', NULL, 'core', 'Enables the delivery submodule/permission group used for delivery receipts, distinct from the shipment (expedition) submodule.', 'Set/removed via admin/delivery.php:81 (dolibarr_set_const) / :85 (dolibarr_del_const), checked in admin/delivery.php:220/232, commande/card.php:3581, and core/lib/sendings.lib.php:59/373/525.', 'Enabling it activates delivery-related rights/UI (e.g. delivery creation rights checked alongside MAIN_SUBMODULE_EXPEDITION); a comment notes MAIN_SUBMODULE_EXPEDITION is force-enabled for backward compatibility and should eventually be replaced by this constant.', NULL, 0, 0, 'admin/delivery.php|admin/delivery.php|admin/delivery.php|admin/delivery.php', 1, '5036d9c2e9c23bec2ae9bab6ce8d1577dffccef492a2739e1fc66e5a2cb24fe7', 'v2', '2026-07-24T06:41:12+00:00', '["admin/delivery.php:72|// Shipment note. We force MAIN_SUBMODULE_EXPEDITION to on because this var is still used. TODO We should remove it, only MAIN_SUBMODULE_DELIVERY must be used.", "admin/delivery.php:81|write|dolibarr_set_const($db, \"MAIN_SUBMODULE_DELIVERY\", \"1\", ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SUBMODULE_EXPEDITION', 'string', NULL, 'core', 'Enables the shipment submodule; a legacy flag kept because it is still used alongside MAIN_SUBMODULE_DELIVERY.', 'Forced to ''1'' in admin/delivery.php:75 and :80 when the shipping module is enabled. The comment at admin/delivery.php:72 notes this variable should eventually be removed in favour of MAIN_SUBMODULE_DELIVERY. Checked in 18+ locations across delivery and order code.', 'If not set, certain shipment creation and stock movement paths in delivery/class/delivery.class.php are blocked. Enabling it re-activates shipment-related UI and logic.', '''1'' = shipment submodule active; empty/unset = inactive.', 0, 0, 'admin/delivery.php|admin/delivery.php|admin/delivery.php', 1, '0c257f38d28151f23c52aefc188336951a6ed23691d7edbd9a61160db4bbc5ef', 'v2', '2026-04-21T11:16:15+00:00', '["admin/delivery.php:72  // Shipment note. We force MAIN_SUBMODULE_EXPEDITION to on because this var is still used. TODO We should remove it, only MAIN_SUBMODULE_DELIVERY must be used.", "admin/delivery.php:75|write|dolibarr_set_const($db, \"MAIN_SUBMODULE_EXPEDITION\", \"1\", ''chaine'', 0, '''', $conf->entity);", "delivery/class/delivery.class.php:219|check|if (!getDolGlobalInt(''MAIN_SUBMODULE_EXPEDITION'')) {", "core/lib/expedition.lib.php:95|check|if (getDolGlobalString(''MAIN_SUBMODULE_EXPEDITION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SUBMODULE_RECEPTION', 'string', NULL, 'admin', 'Enables the reception submodule, activated automatically when the reception module itself is enabled.', 'Set via admin/reception_setup.php:64 (dolibarr_set_const) when isModEnabled(''reception'') and the constant isn''t already set (admin/reception_setup.php:62), and checked in core/lib/reception.lib.php:138/149.', 'Once set, reception-related logic in core/lib/reception.lib.php is enabled/branches based on this flag.', NULL, 0, 0, 'admin/reception_setup.php|admin/reception_setup.php', 1, '2f9cb4054fbb9e47f04d1de621d13c0bc91e6e01523ab71a4a1e60e62ef7ebb4', 'v2', '2026-07-24T06:41:12+00:00', '["admin/reception_setup.php:62|check|if (isModEnabled(''reception'') && !getDolGlobalString(''MAIN_SUBMODULE_RECEPTION'')) {", "admin/reception_setup.php:64|write|dolibarr_set_const($db, \"MAIN_SUBMODULE_RECEPTION\", \"1\", ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SUPPLIER_PROPOSAL_CHOOSE_ODT_DOCUMENT', 'string', NULL, 'core', 'Enables per-status ODT template selection (default/to bill/closed) in the supplier proposal ODT document model setup form.', 'Read in core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:114: when > 0, the module setup form adds param2/3/4 hidden fields so SUPPLIER_PROPOSAL_ADDON_PDF_ODT_DEFAULT/TOBILL/CLOSED can be configured per status.', 'Without it only the generic SUPPLIER_PROPOSAL_ADDON_PDF_ODT_PATH template list is configurable; enabling it exposes the three per-status template selectors.', '0 or unset = default ODT template used; positive integer = alternative ODT template selected.', 1, 0, NULL, 1, '72248e476bbde72c7db0d525dc8fa556492a947eed4e67f7e51c20f796c60176', 'v2', '2026-07-24 07:06:30', '["doc_generic_supplier_proposal_odt.modules.php:114: $odtChosen = getDolGlobalInt(''MAIN_SUPPLIER_PROPOSAL_CHOOSE_ODT_DOCUMENT'') > 0;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SUPPORT_SHARED_CONTACT_BETWEEN_THIRDPARTIES', 'string', NULL, 'core', 'Enables an unstable experimental feature allowing contacts to be shared across multiple third-parties.', 'Checked in core/lib/company.lib.php:97; documented at societe/societecontact.php:28 as ''Used when the unstable option MAIN_SUPPORT_SHARED_CONTACT_BETWEEN_THIRDPARTIES is on.'' No admin UI write path is present in the payload.', 'Enabling this option activates contact-sharing behaviour across third-parties; it is explicitly labelled unstable and may produce unexpected results.', 'Any truthy value activates the shared-contact feature; unset disables it.', 1, 0, NULL, 1, '1c325fb4a421cfac27a62d18bfcd21d11ea88f4ea960b466d49d41566b7a90b0', 'v2', '2026-04-21T13:29:58+00:00', '["societe/societecontact.php:28  *     \t\t\t\tUsed when the unstable option MAIN_SUPPORT_SHARED_CONTACT_BETWEEN_THIRDPARTIES is on.", "core/lib/company.lib.php:97|check|if (getDolGlobalString(''MAIN_SUPPORT_SHARED_CONTACT_BETWEEN_THIRDPARTIES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SUSPEND_FACTURE_REC_ON_MAX_GEN_REACHED', 'string', NULL, 'compta', 'When enabled, automatically suspends a recurring invoice template once its maximum number of generations has been reached.', 'Read in FactureRec::setNextDate() (compta/facture/class/facture-rec.class.php:2340), invoked right after incrementing nb_gen_done, checking isMaxNbGenReached() and if true, calling setValueFrom(''suspended'', 1) to flag the template as suspended.', 'Enabling it stops a recurring invoice template from continuing to auto-generate invoices once its generation cap is hit, by setting its ''suspended'' field to 1; without it the template''s max-gen limit is not enforced this way.', 'Boolean-like: enabled = auto-suspend the recurring template when max nb of generations is reached; unset/0 = no automatic suspension.', 0, 0, NULL, 1, '10d7ee664ad5c9e86a09efc8b36960a0e3652d6ea2604d4027ce2c21f299163d', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/class/facture-rec.class.php:2340: if (getDolGlobalInt(''MAIN_SUSPEND_FACTURE_REC_ON_MAX_GEN_REACHED'') && $this->isMaxNbGenReached()) {", "compta/facture/class/facture-rec.class.php:2341: $resSuspend = $this->setValueFrom(''suspended'', 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SYSLOG_DISABLE_FILE', 'bool', NULL, 'core', 'Globally disables output of the file syslog handler at export time (secondary/redundant kill-switch to SYSLOG_DISABLE_LOGHANDLER_FILE).', 'core/modules/syslog/mod_syslog_file.php:167, inside the export() method: `if (getDolGlobalString(''MAIN_SYSLOG_DISABLE_FILE'')) { return; // Global option to disable output of this handler }` — this check happens before any message is written to the log file, in addition to the isActive() check driven by SYSLOG_DISABLE_LOGHANDLER_FILE.', 'Setting it to a truthy value makes every call to export() return immediately without writing the log message, effectively silencing the file log handler''s output.', 'Truthy = disable file handler output (return early before writing); 0/unset = normal logging.', 0, 0, NULL, 1, '41ba4553b31345c9764e8b9a051c6ece773285d56f38d1b071e6c76f1e6d1246', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/syslog/mod_syslog_file.php:167: if (getDolGlobalString(''MAIN_SYSLOG_DISABLE_FILE'')) { return; // Global option to disable output of this handler }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SYSLOG_DISABLE_SYSLOG', 'bool', NULL, 'core', 'Globally disables output to the syslog handler, even if syslog is configured as a log destination.', 'Checked in ModSyslogSyslog::export() in core/modules/syslog/mod_syslog_syslog.php:116; when set, the export() method returns immediately, with inline comment ''Global option to disable output of this handler''.', 'Enabling it silences all messages that would otherwise be sent via the syslog log handler, without needing to remove syslog from the configured log handlers.', 'Boolean: truthy value makes export() a no-op (comment: ''Global option to disable output of this handler'').', 1, 0, NULL, 1, 'e7ffe79baf0cd529ebad71883f1f3202898dfb5ad8273478473f856f1cc20391', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/syslog/mod_syslog_syslog.php:116|check|if (getDolGlobalString(''MAIN_SYSLOG_DISABLE_SYSLOG'')) {", "return; // Global option to disable output of this handler"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_SYSLOG_SHOW_DELAY', 'bool', NULL, 'core', 'Adds a per-log-line timing delay (in seconds, since the previous log line) to file syslog output, useful for profiling.', 'core/modules/syslog/mod_syslog_file.php:175-179: when truthy, `$now = microtime(true); $delay = " ".sprintf("%05.3f", $this->lastTime != 0 ? $now - $this->lastTime : 0); $this->lastTime = $now;` and $delay is then prepended into each log message.', 'Setting it to a truthy value inserts a formatted elapsed-time-since-last-log field into each line written to the file log handler, which helps diagnose slow requests but adds extra text to every log line.', 'Truthy = show per-line delay in log output; 0/unset = no delay shown (default).', 0, 0, NULL, 1, '8f0f1994bb3144d59bec7709a674419227011ff41c0834c2dba443a453fa24a5', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/syslog/mod_syslog_file.php:175: if (getDolGlobalString(''MAIN_SYSLOG_SHOW_DELAY'')) {", "core/modules/syslog/mod_syslog_file.php:177: $delay = \" \".sprintf(\"%05.3f\", $this->lastTime != 0 ? $now - $this->lastTime : 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_ACTION_CODE', 'string', NULL, 'admin', 'Developer/test-page setting used to preset the ''action code'' filter value on the internal UI component test page (agenda/actioncode widget demo).', 'Used in admin/tools/ui/components/test_arrays.php:194: `$actioncode = getDolGlobalString(''MAIN_TEST_UI_ACTION_CODE''); // '''' by default`, feeding a demo of a Product object / list filter widgets on that test page.', 'Only affects the pre-filled action-code value shown on this internal developer UI test page; has no effect elsewhere.', 'Any string; '''' (empty) by default per inline comment.', 0, 0, 'admin/tools/ui/components/test_arrays.php', 1, '16dce3a14a1910dcdbafc57f0699ed45341bc1546f2116ff6801d8b662a47d5c', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:194: $actioncode = getDolGlobalString(''MAIN_TEST_UI_ACTION_CODE''); // '''' by default"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_FILTER', 'string', NULL, 'admin', 'Presets the filter value used by the internal UI component test/demo page.', 'Read in admin/tools/ui/components/test_arrays.php:196 to preset a filter parameter for the array/list rendering demo used to test core UI components. Not exposed in any admin UI, only set programmatically or manually for debugging.', 'Changing it only affects the developer-facing UI test page output, not any production feature.', 'String, empty string by default (per inline comment).', 1, 0, 'admin/tools/ui/components/test_arrays.php', 1, '1dfca661f3340d6659579e20f96f4e61daaedfb753ebd5bbabadc604514dd7ef', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:196|read|$filter = getDolGlobalString(''MAIN_TEST_UI_FILTER''); // '''' by default;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_FILTERT', 'string', NULL, 'admin', 'Presets a secondary filter value ($filtert) for the internal UI component test/demo page.', 'Read in admin/tools/ui/components/test_arrays.php:197, alongside MAIN_TEST_UI_FILTER, to preset the second filter variable used by the array/list rendering demo for testing core UI components.', 'Changing it only affects the developer-facing UI test page output, not any production feature.', 'String, empty string by default (per inline comment).', 1, 0, 'admin/tools/ui/components/test_arrays.php', 1, 'f62a03c8ee4676e5f32868ed92f8deb8db630cc6954daf928ba4a9c2c78049ba', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:197|read|$filtert = getDolGlobalString(''MAIN_TEST_UI_FILTERT''); // '''' by default;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_IN_DOLIBARR_PAGE', 'string', NULL, 'admin', 'Developer/test-page setting controlling whether the UI component test page renders inside a full Dolibarr page (with header/menu) or a bare hard-coded header.', 'Used in admin/tools/ui/components/test_arrays.php:50: `$usedolheader = getDolGlobalInt(''MAIN_TEST_UI_IN_DOLIBARR_PAGE'', 1);` with the inline comment ''1 = Test inside a dolibarr page, 0 = Use hard coded header. Using a dolibarr constant avoid phpstan hardcoded value always true or false''.', 'Toggles the rendering mode of this internal UI test/demo page only; has no effect outside that developer test page.', '1 = Test inside a dolibarr page (default); 0 = Use hard coded header (per inline code comment).', 0, 0, 'admin/tools/ui/components/test_arrays.php', 1, '8a87da7db93598810c5daf126e8c1d9fb4fbd0cc9c8ac3312e7270ddcbfece6d', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:50: $usedolheader = getDolGlobalInt(''MAIN_TEST_UI_IN_DOLIBARR_PAGE'', 1);", "admin/tools/ui/components/test_arrays.php: // 1 = Test inside a dolibarr page, 0 = Use hard coded header"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_SOCID', 'string', NULL, 'admin', 'Presets the third-party (socid) id used by the internal UI component test/demo page.', 'Read in admin/tools/ui/components/test_arrays.php:198 to preset the $socid variable for the array/list rendering demo used to test core UI components.', 'Changing it only affects the developer-facing UI test page output, not any production feature.', 'Integer, 0 by default (per inline comment).', 1, 0, 'admin/tools/ui/components/test_arrays.php', 1, '7a8dbec9565488b386d2fd34991606fdc6f367c26d1159f1374ba72ffabb0cfb', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:198|read|$socid = getDolGlobalInt(''MAIN_TEST_UI_SOCID'', 0); // 0 by default;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_SORTFIELD', 'string', NULL, 'admin', 'Presets the sort field used by the internal UI component test/demo page.', 'Read in admin/tools/ui/components/test_arrays.php:201 to preset the $sortfield variable (default ''aaa'') for the array/list rendering demo used to test core UI components.', 'Changing it only affects the developer-facing UI test page output, not any production feature.', 'String, ''aaa'' by default (per inline comment).', 1, 0, 'admin/tools/ui/components/test_arrays.php', 1, '41ba47f8a0faf5fd7a63b5c6938dab807b3319d8fc67580ca6efd91036bff589', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:201|read|$sortfield = getDolGlobalString(''MAIN_TEST_UI_SORTFIELD'', ''aaa''); // ''aaa'' by default;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_STATUS', 'string', NULL, 'admin', 'Developer/test-page setting used to preset the ''status'' filter value on the internal UI component test page.', 'Used in admin/tools/ui/components/test_arrays.php:195: `$status = getDolGlobalString(''MAIN_TEST_UI_STATUS''); // '''' by default;`, alongside sibling test constants (MAIN_TEST_UI_ACTION_CODE, MAIN_TEST_UI_FILTER, MAIN_TEST_UI_FILTERT, MAIN_TEST_UI_SOCID, MAIN_TEST_UI_TYPE, MAIN_TEST_UI_USERGROUP) that seed demo filter widgets on that page.', 'Only affects the pre-filled status value shown on this internal developer UI test page; has no effect elsewhere.', 'Any string; '''' (empty) by default per inline comment.', 0, 0, 'admin/tools/ui/components/test_arrays.php', 1, '65b41fd8604ef127da0d547fbbfef56a76da3cd0755103b1de8a5600d4f1515a', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:195: $status = getDolGlobalString(''MAIN_TEST_UI_STATUS''); // '''' by default;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_TYPE', 'string', NULL, 'admin', 'Presets the $type variable used by the internal UI component test/demo page.', 'Read in admin/tools/ui/components/test_arrays.php:199 to preset the $type variable for the array/list rendering demo used to test core UI components.', 'Changing it only affects the developer-facing UI test page output, not any production feature.', 'Integer, 0 by default (per inline comment).', 1, 0, 'admin/tools/ui/components/test_arrays.php', 1, '2a710055393feb45be5e1f8f3b2c7cf187943561ec5fcc81e0a83558ca3f0eb1', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:199|read|$type = getDolGlobalInt(''MAIN_TEST_UI_TYPE'', 0); // 0 by default;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TEST_UI_USERGROUP', 'string', NULL, 'admin', 'Presets the $usergroup variable used by the internal UI component test/demo page.', 'Read in admin/tools/ui/components/test_arrays.php:200 to preset the $usergroup variable for the array/list rendering demo used to test core UI components.', 'Changing it only affects the developer-facing UI test page output, not any production feature.', 'Integer, 0 by default (per inline comment).', 1, 0, 'admin/tools/ui/components/test_arrays.php', 1, '9485f4fcea2cf9cd79fd3c910fe2e03fb4d1f39dad82af8ae6bb2e025f31eb80', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/ui/components/test_arrays.php:200|read|$usergroup = getDolGlobalInt(''MAIN_TEST_UI_USERGROUP'', 0); // 0 by default;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TE_PRIVATE_FIRST_AND_LASTNAME_TO_UPPER', 'string', NULL, 'core', 'Normalizes first/last name (and alias) casing to ucwords/uppercase-lastname style, skipping the company-name field for individual (''TE_PRIVATE'') thirdparties.', 'Checked in core/class/commonpeople.class.php:379 inside setUpperOrLowerCase(): when set, lastname/firstname are put through dol_ucwords(dol_strtolower(...)), name is also normalized unless typent_code is ''TE_PRIVATE'', and lastname is additionally forced to uppercase if a firstname is present.', 'When set, applies a specific name-casing normalization on save: lastname/firstname become Title Case then lastname is upper-cased (if firstname present); the thirdparty ''name'' field is left untouched for individual-type thirdparties.', 'Truthy/falsy flag; behaves differently from the plain MAIN_FIRST_TO_UPPER by excluding TE_PRIVATE typent_code from the ''name'' normalization and forcing lastname to full uppercase.', 1, 0, NULL, 1, '5b103d6b4c3f0bb264c179a1c1768c81639dbd1e2be3f102a15cd0685b9f039a', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonpeople.class.php:379|check|if (getDolGlobalString(''MAIN_TE_PRIVATE_FIRST_AND_LASTNAME_TO_UPPER'')) {", "core/class/commonpeople.class.php|if (empty($this->typent_code) || $this->typent_code != \"TE_PRIVATE\") { $this->name = dol_ucwords(dol_strtolower($this->name)); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_THEME', 'string', NULL, 'core', 'Sets the active visual theme (skin) for the Dolibarr interface.', 'Written via admin/ihm.php:118 with dolibarr_set_const. Read in core/lib/usergroups.lib.php:373 as $selected_theme and displayed at line 409. Checked at line 467 to identify the currently selected theme directory. Comment at admin/ihm.php:116: ''To be sure we don''t have this constant set for all entities''.', 'Changing this constant switches the UI theme for all users in the entity. The theme name must correspond to a valid theme directory on disk.', 'String: name of the theme directory (e.g. ''eldy''). Must match an available theme.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'a2d3d6b32ed493df02872642023961e5a4d2ee3994768ee4b6993a8e42b326da', 'v2', '2026-04-21T13:29:58+00:00', '["admin/ihm.php:118|write|dolibarr_set_const($db, \"MAIN_THEME\", GETPOST(\"main_theme\", ''aZ09''), ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:373|read|$selected_theme = getDolGlobalString(''MAIN_THEME'');", "core/lib/usergroups.lib.php:467|check|if ($subdir == getDolGlobalString(''MAIN_THEME'')) {", "admin/ihm.php:116  //dolibarr_del_const($db, \"MAIN_THEME\", 0);\t// To be sure we don''t have this constant set for all entities"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TOOLTIP_PRICELOG_HISTORY_LIMIT', 'string', NULL, 'fourn', 'Maximum number of supplier buy-price history entries fetched for display in the price-log tooltip.', 'Used in fourn/class/fournisseur.product.class.php:1440 as the limit parameter passed to listProductFournisseurPriceLog(), with a code default of 10, sorted by ''pfpl.datec'' DESC.', 'Increasing it shows more historical price entries in the supplier price tooltip; decreasing it shows fewer.', 'Integer count of history rows to fetch; code default is 10.', 0, 0, NULL, 1, '2d107ee9ab1cae257ddf9cab56ece63fcaea711d5112eef2a90e28c1dfa7f33b', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/class/fournisseur.product.class.php:1440: $logPrices = $this->listProductFournisseurPriceLog($this->product_fourn_price_id, ''pfpl.datec'', ''DESC'', getDolGlobalInt(''MAIN_TOOLTIP_PRICELOG_HISTORY_LIMIT'', 10)); // set sort ord"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TRIGGER_DEBUG', 'string', NULL, 'core', 'Enables extra debug-level syslog logging each time Interfaces::run_triggers() is invoked.', 'In core/class/interfaces.class.php:82-85, if this int is set, run_triggers() logs a LOG_DEBUG syslog line with the action name; the inline comment notes ''This his too much verbose, enabled if const enabled only''.', 'Enabling it adds a verbose debug log line on every triggered business event, useful for debugging trigger execution but noisy in normal operation.', 'true/1 (or any non-zero int) = log debug line on every run_triggers call; false/unset (default) = no extra logging.', 1, 0, NULL, 1, 'b0d7ebcaac279647df3c84c4a7050f5ddfe7263a8531ac38d53f8afb5384ec40', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/interfaces.class.php:82|check|if (getDolGlobalInt(''MAIN_TRIGGER_DEBUG'')) {", "core/class/interfaces.class.php:83: // This his too much verbose, enabled if const enabled only", "core/class/interfaces.class.php:84: dol_syslog(get_class($this).\"::run_triggers action=\".$action.\" Launch run_triggers\", LOG_DEBUG);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TRUNCATE_TIMELINE_MESSAGE', 'string', NULL, 'core', 'Sets the number of lines shown before truncating a message body on the agenda/event timeline, with a ''read more'' expander.', 'In core/lib/functions.lib.php:17173, $truncateLines = getDolGlobalInt(''MAIN_TRUNCATE_TIMELINE_MESSAGE'', 3) sets the truncation threshold (default 3) for event messages rendered on the timeline; if the truncated text is shorter than the original, a ''readmore-block'' UI toggle is rendered.', 'Controls how many lines of an event/message are shown by default on timelines before requiring a click to expand; setting to 0 or a negative value disables truncation per the surrounding check `if ($truncateLines > 0 ...)`.', 'Integer number of lines to show before truncation; default 3 if unset. 0 or negative effectively shows full text (per the `$truncateLines > 0` guard).', 1, 0, NULL, 1, 'cc15a55da2f0ff620cd7b61c9f07cf2910e378571ab1d273f12beaaeb1a65ecd', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:17173: $truncateLines = getDolGlobalInt(''MAIN_TRUNCATE_TIMELINE_MESSAGE'', 3);", "core/lib/functions.lib.php:17174: if ($truncateLines > 0 && strlen($newmess) > strlen($truncatedText)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TVAINTRA_IN_SOURCE_ADDRESS', 'string', NULL, 'core', 'Adds the source (issuer) company''s intra-community VAT number to the source address block on generated PDF documents.', 'Checked in core/lib/pdf.lib.php:500 (function pdf_build_address, mode ''source''); when set and $sourcecompany->tva_intra is not empty, a VAT-intra line is appended.', 'Enables display of the issuing company''s intra-community VAT number on PDF documents such as invoices.', 'Boolean-like (set/unset); when set, source VAT-intra number is printed', 1, 0, NULL, 1, '621001afd160535d70520f56c4e6daf2601cdeae68ab66a92e02be65b86712eb', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:500|check|if (getDolGlobalString(''MAIN_TVAINTRA_IN_SOURCE_ADDRESS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TVAINTRA_NOT_IN_ADDRESS', 'string', NULL, 'admin', 'Controls whether the recipient''s intra-community VAT number is excluded from the address block on PDF documents.', 'Configured via admin/pdf.php (written with dolibarr_set_const at line 122, rendered as a yes/no selector at line 367). Checked at core/lib/pdf.lib.php:662: when truthy, the VAT number is omitted from the target address.', 'Enabling this removes the recipient''s VAT intra number from the address block on generated PDFs; disabling it (default) includes the number.', '1 = exclude VAT intra from address; 0 or absent = include VAT intra in address.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '257db023de92b817324aa37f9f003b01e4a79ee48c548a105bae121c5338a7e7', 'v2', '2026-04-21T13:29:58+00:00', '["admin/pdf.php:122|write|dolibarr_set_const($db, \"MAIN_TVAINTRA_NOT_IN_ADDRESS\", GETPOST(\"MAIN_TVAINTRA_NOT_IN_ADDRESS\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:367|read|print $form->selectyesno(''MAIN_TVAINTRA_NOT_IN_ADDRESS'', getDolGlobalInt(''MAIN_TVAINTRA_NOT_IN_ADDRESS''), 1);", "core/lib/pdf.lib.php:662|check|if (!getDolGlobalString(''MAIN_TVAINTRA_NOT_IN_ADDRESS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_TYPES_TO_SHOW_PICTO', 'bool', NULL, 'core', 'Defines the comma-separated list of extrafield types for which a picto icon is shown.', 'Read twice in core/class/commonobject.class.php:9803 and 9811, split by comma to build the list of types. Defaults to ''email,phone,ip,password''.', 'Modifying this constant changes which extrafield types display a picto icon next to their value.', 'Comma-separated string of type names (default: ''email,phone,ip,password'')', 1, 0, NULL, 1, '1671598c60bf25ffeeac3d7f1acffb8848916e474ca88adfe2151e7d4fcfb769', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:9803|read|$listoftypestoshowpicto = explode('','', getDolGlobalString(''MAIN_TYPES_TO_SHOW_PICTO'', ''email,phone,ip,password''));", "core/class/commonobject.class.php:9811|read|$listoftypestoshowpicto = explode('','', getDolGlobalString(''MAIN_TYPES_TO_SHOW_PICTO'', ''email,phone,ip,password''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_UMASK', 'string', NULL, 'core', 'Sets the file permission mask (umask, e.g. ''0666'') applied when Dolibarr creates new files.', 'Configured via admin/security_file.php:105 (dolibarr_set_const, admin UI at line 208) and read in core/lib/files.lib.php:840/957/1059 and core/filemanagerdol/connectors/php/config.inc.php:109/118.', 'If set, new files created by Dolibarr use this permission mask instead of the function-specific default mask.', 'Example format: ''0666''', 0, 0, 'admin/security_file.php|admin/system/security.php|admin/security_file.php', 1, '4ade83caec5c55f9f36f2028a15b2592cfa569df2369d18197f674cfa2e3cf6d', 'v2', '2026-07-24T06:41:12+00:00', '["core/lib/files.lib.php:769|* @param string $newmask Mask for new file. ''0'' by default means getDolGlobalString(''MAIN_UMASK''). Example: ''0666''.", "admin/security_file.php:105|write|$res4 = dolibarr_set_const($db, \"MAIN_UMASK\", $tmpumask, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_UNACCENT_USE_TRANSLITERATOR', 'bool', NULL, 'core', 'Switches dol_string_unaccent() to use PHP''s intl Transliterator class instead of the built-in manual replacement table.', 'Checked in dol_string_unaccent() in core/lib/functions.lib.php:2088; requires the ''intl'' PHP extension to be loaded, and when both conditions hold, uses Transliterator::createFromRules() with an Any-Latin/Latin-ASCII/NFD/remove-nonspacing-marks/NFC rule chain instead of the hardcoded UTF-8 replacement map used otherwise.', 'Enabling it (with intl loaded) changes the accent-removal algorithm from a fixed character-substitution table to ICU transliteration rules, which can handle a broader range of Unicode characters/scripts than the manual table.', 'Boolean: truthy value (with ''intl'' extension loaded) uses Transliterator-based unaccenting; otherwise falls back to the manual UTF-8 replacement table.', 1, 0, NULL, 1, 'e43053e6d23fda7536d930f0ebaec6f3a3f55e3ba86a38e66305d25bfe5cc4ed', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:2088|check|if (extension_loaded(''intl'') && getDolGlobalString(''MAIN_UNACCENT_USE_TRANSLITERATOR'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_UNIT_PRICE_WITH_TAX_IS_FOR_ALL_TAXES', 'string', NULL, 'comm', 'Intended to enable unit price entry inclusive of all taxes; currently a work-in-progress feature.', 'Checked in core/tpl/objectline_edit.tpl.php:270. Code comments in api/class/api_access.class.php:203, master.inc.php:357, comm/propal/class/propal.class.php:978, and comm/propal/card.php:1242 indicate this is ''Work In Progress'' and ''TODO Implement''.', 'The feature is not fully implemented; enabling this constant activates only partial support for all-tax unit price entry.', 'Truthy integer = all-taxes-inclusive unit price mode (partial implementation); empty/unset = disabled.', 1, 0, NULL, 1, 'f07f6d5bc9b6c5b800b6d6a7827b73564699456be500f710d410bb2cdd837cf5', 'v2', '2026-04-21T11:16:15+00:00', '["api/class/api_access.class.php:203  // Work In Progress to support all taxes into unit price entry when MAIN_UNIT_PRICE_WITH_TAX_IS_FOR_ALL_TAXES is set.", "master.inc.php:357  // Work In Progress to support all taxes into unit price entry when MAIN_UNIT_PRICE_WITH_TAX_IS_FOR_ALL_TAXES is set.", "comm/propal/class/propal.class.php:978  // TODO Implement  if (getDolGlobalInt(''MAIN_UNIT_PRICE_WITH_TAX_IS_FOR_ALL_TAXES'')) ?", "comm/propal/card.php:1242  // TODO Implement  if (getDolGlobalInt(''MAIN_UNIT_PRICE_WITH_TAX_IS_FOR_ALL_TAXES''))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_UNKNOWN_CUSTOMERS_ARE_COMPANIES', 'string', NULL, 'societe', 'Default assumption (company vs individual) used by isACompany() when the thirdparty''s nature cannot otherwise be determined.', 'Read in societe/class/societe.class.php inside isACompany() as getDolGlobalInt(''MAIN_UNKNOWN_CUSTOMERS_ARE_COMPANIES'', $defaultvalue) with a code default of 0 (individual); this initial guess can then be overridden by other heuristics (VAT-intra present, idprof/euid present, or MAIN_CUSTOMERS_ARE_COMPANIES_EVEN_IF_SET_AS_INDIVIDUAL).', 'Changing it flips the fallback classification (company vs. individual) applied to thirdparties whose nature cannot be inferred from other fields, which can affect invoice/legal document rendering that differs by company/individual.', 'Integer used as boolean-like default: 0 = treat as individual by default (code default), non-zero = treat as company by default.', 1, 0, NULL, 1, '4768ea912174b8484a6c1a8eeffeadd638fdcb7ef9aefbfd0fc282222d4da969', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php: // Define if third party is treated as company (or not) when nature is unknown", "societe/class/societe.class.php:4435|read|$isACompany = getDolGlobalInt(''MAIN_UNKNOWN_CUSTOMERS_ARE_COMPANIES'', $defaultvalue);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_UPLOAD_DOC', 'string', '2048', 'core', 'Sets the maximum allowed file upload size in kilobytes for document uploads across Dolibarr.', 'Written via admin/security_file.php:102 and configurable in the admin security UI. Read in admin/modules.php:1560 and admin/geoipmaxmind.php:202 as $max (in Kb). The comment in core/class/conf.class.php:1131 confirms the unit: ''$this->maxfilesize = ... (int) $this->global->MAIN_UPLOAD_DOC * 1024''. Also analyzed alongside PHP upload_max_filesize and post_max_size per core/lib/security.lib.php:1418.', 'Reducing the value restricts the maximum uploadable file size across the application. Increasing it allows larger uploads, subject to PHP server-side limits.', 'Integer (in kilobytes); default is 2048. Empty or 0 disables upload size enforcement by this constant.', 0, 0, 'admin/security_file.php|admin/security_file.php|admin/modules.php|admin/modules.php|admin/geoipmaxmind.php|admin/geoipmaxmind.php|admin/security_file.php', 1, '18204848f166da44bb92d76d5f02fd02d14643bb3a2419b148ab062633d1891b', 'v2', '2026-04-21T11:16:15+00:00', '["admin/modules.php:1560|read|$max = getDolGlobalString(''MAIN_UPLOAD_DOC''); // In Kb", "core/class/conf.class.php:1131  //$this->maxfilesize = (empty($this->global->MAIN_UPLOAD_DOC) ? 0 : (int) $this->global->MAIN_UPLOAD_DOC * 1024);", "core/lib/security.lib.php:1418  *  Analyze among: upload_max_filesize, post_max_size, MAIN_UPLOAD_DOC", "admin/security_file.php:102|write|$res3 = dolibarr_set_const($db, ''MAIN_UPLOAD_DOC'', GETPOST(''MAIN_UPLOAD_DOC'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_URL_FOR_PING', 'string', NULL, 'blockedlog', 'Overrides the URL used by Dolibarr''s blocked-log registration/ping feature to contact the ping service.', 'Read with getDolGlobalString(''MAIN_URL_FOR_PING'', "https://ping.dolibarr.org/") in blockedlog/admin/registration.php:286, blockedlog/admin/blockedlog_list.php:621, blockedlog/admin/blockedlog_archives.php:537, and core/lib/functions2.lib.php:3153.', 'If set, blocked-log registration/ping requests are sent to this URL instead of the default https://ping.dolibarr.org/.', NULL, 0, 0, 'blockedlog/admin/registration.php|blockedlog/admin/blockedlog_list.php|blockedlog/admin/blockedlog_archives.php', 1, '2914fb81f13c89bc0e98b3c7f175c71c52cb09e085a06cfe7385b35da9bb6629', 'v2', '2026-07-24T06:41:12+00:00', '["blockedlog/admin/registration.php:286|read|$url_for_ping = getDolGlobalString(''MAIN_URL_FOR_PING'', \"https://ping.dolibarr.org/\");", "core/lib/functions2.lib.php:3153|read|$url_for_ping = getDolGlobalString(''MAIN_URL_FOR_PING'', \"https://ping.dolibarr.org/\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USER_PROFILE_CSS_URL', 'string', NULL, 'public', 'URL of a custom CSS stylesheet to load on the public user profile page.', 'Checked in public/users/view.php:237-238; if set, a <link rel="stylesheet"> tag pointing to this URL (with a ?lang= query string appended) is injected into the page head.', 'Setting it lets the public user profile page load custom CSS from an external or local URL, allowing visual customization of that public page.', 'String: a URL to a CSS file.', 1, 0, NULL, 1, 'bc98ef8bdb7c7719afc03d56a32d07ad4de2074cd1d753f2d064137d6c298c61', 'v2', '2026-07-24T07:05:23+00:00', '["public/users/view.php:237: if (getDolGlobalString(''MAIN_USER_PROFILE_CSS_URL'')) {", "public/users/view.php:238: $head = ''<link rel=\"stylesheet\" type=\"text/css\" href=\"'' . getDolGlobalString(''MAIN_USER_PROFILE_CSS_URL'').''?lang=''.$langs->defaultlang.''\">''.\"\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USER_SEPARATOR_CHAR_FOR_GENERATED_LOGIN', 'string', NULL, 'user', 'Sets the separator character used between name parts when auto-generating a user login.', 'In core/lib/functions2.lib.php:2006 (function dol_buildlogin, also called from user/card.php:1120), this string constant supplies the separator character used to join lastname/firstname parts of an auto-generated login; default is ''.''.', 'Changing the value changes the character inserted between name components in auto-generated logins (e.g. ''j.dupont''); setting it to the literal string ''none'' removes the separator entirely.', 'any single character (default ''.''); special value ''none'' = no separator character used.', 1, 0, NULL, 1, '0cdacb0dc1d6a7f7f8d2f04154a4ffc1fba4e296e2cd7bf28e6f13345169c431', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions2.lib.php:2006: $charforseparator = getDolGlobalString(\"MAIN_USER_SEPARATOR_CHAR_FOR_GENERATED_LOGIN\", ''.'');", "core/lib/functions2.lib.php:2007: if ($charforseparator == ''none'') { $charforseparator = ''''; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_ADVANCED_PERMS', 'bool', NULL, 'hrm', 'Enables advanced/granular permissions mode, changing how object create/write rights are checked across many modules.', 'Configured via admin UI (admin/security_other.php:144, admin/perms.php:153/275) and checked with getDolGlobalString/getDolGlobalInt(''MAIN_USE_ADVANCED_PERMS'') across 335 occurrences, e.g. reception/class/reception.class.php:640/2337 and fourn/class/fournisseur.commande.class.php:810.', 'When enabled, object permission checks switch to advanced granular rights (e.g. distinguishing ''creer'' from other advanced rights) instead of the simpler default rights model; the admin/perms.php UI also shows advanced permission labels when enabled.', NULL, 0, 0, 'admin/security_other.php|admin/perms.php|admin/perms.php|admin/perms.php|admin/perms.php', 1, '79a98a92fb699c222c61f9bb8e531d7c7869826e593770a271769595c4d254e4', 'v2', '2026-07-24T06:41:12+00:00', '["admin/perms.php:266|read|$permlabel = (getDolGlobalString(''MAIN_USE_ADVANCED_PERMS'') && ($langs->trans(\"PermissionAdvanced\".$obj->id) != \"PermissionAdvanced\".$obj->id) ? $langs->trans(\"PermissionAdvanced\".", "reception/class/reception.class.php:640|check|if (!((!getDolGlobalInt(''MAIN_USE_ADVANCED_PERMS'') && $user->hasRight(''reception'', ''creer''))"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_ALTERNATE_TRANSLATION_FOR', 'bool', NULL, 'core', 'Specifies which object fields use alternate (extra-language) translations instead of the default language.', 'COMMENTS at core/class/extralanguages.class.php lines 75-76 define the format: ''elementA:fieldname,fieldname2;elementB:...'' with example ''societe:name,town;contact:firstname,lastname''. Checked at line 103 and parsed via explode at line 104.', 'Setting this constant causes the listed fields on the specified objects to be displayed using alternate-language values from the extra-languages system. Clearing it disables alternate translation for all objects.', 'You must set variable MAIN_USE_ALTERNATE_TRANSLATION_FOR=elementA:fieldname,fieldname2;elementB:... Example: MAIN_USE_ALTERNATE_TRANSLATION_FOR=societe:name,town;contact:firstname,lastname', 1, 0, NULL, 1, 'fea15e8b35634e34a2b12abb7c21a39ef715fa080a89a19739894606e912e746', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/extralanguages.class.php:75  *  You must set variable MAIN_USE_ALTERNATE_TRANSLATION_FOR=elementA:fieldname,fieldname2;elementB:...", "core/class/extralanguages.class.php:76  *  Example: MAIN_USE_ALTERNATE_TRANSLATION_FOR=societe:name,town;contact:firstname,lastname", "core/class/extralanguages.class.php:103|check|if (getDolGlobalString(''MAIN_USE_ALTERNATE_TRANSLATION_FOR'')) {", "core/class/extralanguages.class.php:104|read|$tmpelement = explode('';'', getDolGlobalString(''MAIN_USE_ALTERNATE_TRANSLATION_FOR''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_AUTOWRAP_ON_FREETEXT', 'bool', NULL, 'core', 'Enables automatic text wrapping (instead of manual line breaks) for the PDF footer free text.', 'Checked in core/lib/pdf.lib.php:1624 inside the footer-building code; changes the width used for $pdf->getStringHeight() from 20000 (no auto-wrap, forces manual CR) to 200, and alignment from ''L'' to ''C''.', 'When enabled, the free text configured for document footers auto-wraps and is centered; when disabled (default), the text requires manual line breaks and is left-aligned.', 'Boolean-like (set/unset); when set, width=200/align=''C'' (auto-wrap); when unset, width=20000/align=''L'' (manual break required)', 1, 0, NULL, 1, 'd96c85a6ac19233a84ed41a948e1594b7c446890f1fdd99917fd9464a5ea783d', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1624|check|if (getDolGlobalString(''MAIN_USE_AUTOWRAP_ON_FREETEXT'')) {", "core/lib/pdf.lib.php:1622: $align = ''L''; // By default, ask a manual break: We use a large value 20000, to not have automatic wrap."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_BACKGROUND_ON_PDF', 'bool', NULL, 'core', 'Specifies the filename of a background image (from the company logos directory) to overlay on PDF documents.', 'Checked at core/lib/pdf.lib.php:752; when set to a non-empty value other than ''-1'', the file path is constructed as $conf->mycompany->dir_output.''/logos/'' + the constant value (line 753). An inline comment warns this option can make TCPDF generation unstable. No admin UI write is present.', 'Setting this to a valid logo filename adds a background image to all generated PDFs; setting it to ''-1'' or leaving it empty disables the background.', 'Non-empty string (not ''-1'') = filename of background image; ''-1'' or absent = no background image.', 1, 0, NULL, 1, 'fb063bf689cfd9a7a9a4337bf7c8d97eb33a001991b93a8c622d0497cf7f589d', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:752|check|if (getDolGlobalString(''MAIN_USE_BACKGROUND_ON_PDF'') && (getDolGlobalString(''MAIN_USE_BACKGROUND_ON_PDF'') != ''-1'')) {\t\t// Warning, this option make TCPDF generation being crazy and", "core/lib/pdf.lib.php:753|read|$filepath = $conf->mycompany->dir_output.''/logos/'' . getDolGlobalString(''MAIN_USE_BACKGROUND_ON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_BACKGROUND_ON_PDF_ALPHA', 'bool', NULL, 'core', 'Sets the opacity (alpha) of the background image used on PDF documents.', 'Checked/read in core/lib/pdf.lib.php:756-757 (function pdf_pagehead); when set, getDolGlobalFloat() value is passed to $pdf->SetAlpha() before drawing the background image configured via MAIN_USE_BACKGROUND_ON_PDF.', 'Changes the transparency of the background/watermark image placed on generated PDF pages; only takes effect when a background image is configured.', 'Float alpha value accepted by TCPDF SetAlpha() (comment: ''Option for change opacity of background'')', 1, 0, NULL, 1, 'cc04814d625d6a0525a804db4866e991f4888c280bd2ff6229313e261316582d', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:756|check|if (getDolGlobalString(''MAIN_USE_BACKGROUND_ON_PDF_ALPHA'')) {", "core/lib/pdf.lib.php:757: $pdf->SetAlpha(getDolGlobalFloat(''MAIN_USE_BACKGROUND_ON_PDF_ALPHA'')); } // Option for change opacity of background"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_CACHE_FOR_TRANSLATION', 'bool', NULL, 'admin', 'Enables (or signals) caching of translation strings, shown as a warning trigger on the admin translation-override page.', 'Checked in admin/translation.php:382 alongside isModEnabled(''memcached''); when true, an admin warning (''CacheForTranslationIsUsed'') is displayed telling the admin that translation overrides may not take effect immediately due to caching.', 'Setting it to true (or having memcached enabled) causes the admin UI to warn that translation-string overrides configured there might be served from a cache instead of applying immediately.', 'Boolean-like/int: true/1 signals translation caching is active (same effect as isModEnabled(''memcached'')).', 0, 0, 'admin/translation.php', 1, 'e90a82c8294894247d7fcbfce80aced0dbb6f7fd7e1065261b9009409397135d', 'v2', '2026-07-24T07:05:23+00:00', '["admin/translation.php:382|check|if (isModEnabled(''memcached'') || getDolGlobalInt(''MAIN_USE_CACHE_FOR_TRANSLATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_COMPANY_NAME_OF_CONTACT', 'bool', NULL, 'core', 'Controls whether the contact''s own company name is used in place of the thirdparty name when the contact belongs to a different company.', 'Checked across 86 occurrences in ODT and PDF generation modules; the guard condition is: $object->contact->socid != $object->thirdparty->id && (!isset($conf->global->MAIN_USE_COMPANY_NAME_OF_CONTACT) || getDolGlobalString(''MAIN_USE_COMPANY_NAME_OF_CONTACT'')).', 'Enabling this causes generated documents to display the contact''s own company name when the contact is linked to a different thirdparty; disabling it always uses the document''s thirdparty name.', '0 = always use thirdparty name; 1 or unset = use contact''s company name when contact belongs to a different company.', 1, 0, NULL, 1, '7f2e816d45a784b16734952af5145ba3ed0471c5619cae0cdb01a41bdd010d81', 'v2', '2026-04-21T11:16:15+00:00', '["recruitment/core/modules/recruitment/doc/doc_generic_recruitmentjobposition_odt.modules.php:325|check|if ($object->contact->socid != $object->thirdparty->id && (!isset($conf->global->MAIN_USE_COMPANY_NAME_OF_CONTACT) || getDolGlobalString(''MAIN_USE_COMPANY_NAME_OF_CONTACT''))) {", "core/lib/pdf.lib.php:663|check|if ($usecontact && is_object($targetcontact) && getDolGlobalInt(''MAIN_USE_COMPANY_NAME_OF_CONTACT'')) {", "core/modules/contract/doc/pdf_strato.modules.php:807|check|if ($usecontact && ($object->contact->socid != $object->thirdparty->id) && (!isset($conf->global->MAIN_USE_COMPANY_NAME_OF_CONTACT) || getDolGlobalString(''MAIN_USE_COMPANY_NAME_OF_CONTACT''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_CONNECT_TIMEOUT', 'bool', NULL, 'admin', 'Sets the cURL connection timeout in seconds for outbound HTTP and email collector connections.', 'Configured via admin/proxy.php:66 and read by core/lib/functions2.lib.php:2044, core/lib/geturl.lib.php:149, admin/emailcollector_card.php:572, emailcollector/class/emailcollector.class.php:1194, and paypal/lib/paypal.lib.php:506 with varying defaults of 5 or 10 seconds.', 'Increasing this value allows slower servers more time to accept connections; decreasing it causes faster failure on unresponsive hosts.', 'Integer (seconds). Defaults to 5 or 10 depending on context if unset.', 0, 0, 'admin/emailcollector_card.php|admin/proxy.php|admin/proxy.php', 1, '5f7a6649c76bd911464d97a92a269c2cc13826f5a3fdff53ff682428a398cf96', 'v2', '2026-04-21T11:16:15+00:00', '["admin/emailcollector_card.php:572|read|$timeoutconnect = getDolGlobalInt(''MAIN_USE_CONNECT_TIMEOUT'', 5);", "core/lib/functions2.lib.php:2044|read|$timeout = getDolGlobalInt(''MAIN_USE_CONNECT_TIMEOUT'', 10); // Connection timeout", "paypal/lib/paypal.lib.php:506|read|curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, getDolGlobalInt(''MAIN_USE_CONNECT_TIMEOUT'', 5));", "admin/proxy.php:66|write|$result += dolibarr_set_const($db, ''MAIN_USE_CONNECT_TIMEOUT'', GETPOST(\"MAIN_USE_CONNECT_TIMEOUT\"), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_DOL_EVAL_NEW', 'bool', NULL, 'core', 'Switches the dol_eval() sandbox to use the newer dol_eval_new() evaluator instead of dol_eval_standard().', 'In core/lib/functions.lib.php:11975-11979, dol_eval() checks getDolGlobalString(''MAIN_USE_DOL_EVAL_NEW''); if set, it calls dol_eval_new($s), otherwise it falls back to dol_eval_standard($s, $hideerrors, $onlysimplestring). dol_eval() is the security-hardened replacement for PHP eval used by verifCond() and trans().', 'When enabled, expression evaluation (used for conditional visibility of menus/fields, computed extrafields, etc.) goes through a different parser implementation; this changes what expressions are accepted/rejected but the exact differences are not shown in the code read.', 'Boolean-like: true/non-empty selects dol_eval_new(); empty/unset (default) uses dol_eval_standard().', 1, 0, NULL, 1, '3e118cb9cd70404c54a09e720b8aaf6860b418fb0ef8afab211ed727797cecda', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:11975: if (getDolGlobalString(\"MAIN_USE_DOL_EVAL_NEW\")) {", "core/lib/functions.lib.php:11976: return dol_eval_new($s);", "core/lib/functions.lib.php:11977: } else { return dol_eval_standard(...); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_EDIT_IN_PLACE', 'bool', NULL, 'core', 'Legacy option that enabled inline ''Edit In Place'' editing of fields via jQuery jEditable/ajax.', 'Checked in core/ajax/loadinplace.php:80, core/ajax/saveinplace.php:97, core/class/html.form.class.php:179/307, with commented-out/deprecated usages in fourn/card.php:441, comm/card.php:567, and main.inc.php:2036 noting ''Was used in past when option "Edit In Place" is set''.', 'When enabled, loadinplace.php/saveinplace.php ajax endpoints and html.form.class.php permit inline field editing; comments indicate this feature is legacy/deprecated (''Was used in past'').', NULL, 1, 0, NULL, 1, '9b1f7fdfd6c2ffe83514b6eb308080acde88da61f65dd9b1cfbeb0b37069d0af', 'v2', '2026-07-24T06:41:12+00:00', '["*       \t\t\tWas used in past when option \"Edit In Place\" is set (MAIN_USE_EDIT_IN_PLACE).", "if (!getDolGlobalString(''MAIN_USE_EDIT_IN_PLACE'')) {", "//$limit_field_type = (getDolGlobalString(''MAIN_USE_EDIT_IN_PLACE'')) ? ''numeric'' : ''amount''; // TODO deprecated ?"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_EXIF_ROTATION', 'bool', NULL, 'document.php', 'Enables automatic image rotation based on EXIF orientation metadata when handling uploaded images.', 'Checked with getDolGlobalString(''MAIN_USE_EXIF_ROTATION'') in document.php:464 (alongside image_format_supported check) and core/lib/images.lib.php:687.', 'When enabled, images are auto-rotated according to their EXIF orientation tag during document/image processing.', NULL, 0, 0, NULL, 1, '0984467d4cc0df9ce3fc011de1c8c7675838c2c3825e7a38e88da609a732abc3', 'v2', '2026-07-24T06:41:12+00:00', '["document.php:464|check|if (!$attachment && getDolGlobalString(''MAIN_USE_EXIF_ROTATION'') && image_format_supported($fullpath_original_file_osencoded) == 1) {", "core/lib/images.lib.php:687|check|if ($ort && getDolGlobalString(''MAIN_USE_EXIF_ROTATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_EXPENSE_IK', 'bool', NULL, 'expensereport', 'Enables the expense report kilometric indemnity (IK) feature, including IK tax categories and ranges in the dictionary.', 'Read in admin/dict.php:588-589 to conditionally show DICT_EXP_TAX_CAT and DICT_EXP_TAX_RANGE dictionary tabs. Checked across expensereport/card.php, expensereport/class/expensereport.class.php, user/bank.php, and core/lib/expensereport.lib.php. The comment in admin/expensereport_ik.php:26 states: ''Page to display expense tax ik. Used when MAIN_USE_EXPENSE_IK is set.''', 'Enabling this constant activates the IK indemnity workflow for expense reports, adds dictionary entries for tax categories and ranges, and shows related UI on user bank and expense card pages.', 'Any non-empty value = enable expense IK feature; empty/unset = IK feature disabled', 0, 0, 'admin/dict.php|admin/dict.php', 1, '48a64c3e79e4e623d7b96885023e70e616e7a13edb1163d2803770e27556a78a', 'v2', '2026-04-21T13:29:58+00:00', '["Page to display expense tax ik. Used when MAIN_USE_EXPENSE_IK is set.", "$tabcond[DICT_EXP_TAX_CAT] = isModEnabled(''expensereport'') && getDolGlobalString(''MAIN_USE_EXPENSE_IK'');", "if (getDolGlobalString(''MAIN_USE_EXPENSE_IK'')) {", "if (!getDolGlobalString(''MAIN_USE_EXPENSE_IK'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_EXTRAFIELDS_ICON', 'bool', NULL, 'core', 'Enables the ''icon'' type as a selectable extrafield type in the extrafield type list.', 'Checked in core/class/extrafields.class.php:3261 inside ExtraFields::getListOfTypesLabels(); if not set, the ''icon'' entry is removed (unset) from the returned array of type => label used to populate the extrafield-type dropdown in extrafield admin setup.', 'Enabling it adds ''icon'' as a choice when defining a new extrafield''s type via the extrafields admin UI; without it the icon type is hidden from that selector (though presumably still usable if already configured on existing fields).', 'Boolean-like: truthy keeps ''icon'' in the list of selectable extrafield types; falsy/unset removes it from the list.', 1, 0, NULL, 1, 'b1cd6d83434bc97bd601f94339d758a9ff91c2943110b2fb97c6d39af2e1cf39', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/extrafields.class.php:3261|check|if (!getDolGlobalString(''MAIN_USE_EXTRAFIELDS_ICON'')) { unset($arraytype2label[''icon'']); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_FPDF', 'bool', NULL, 'core', 'Forces PDF document generators to use the FPDF library instead of the default TCPDF library.', 'Checked with getDolGlobalString(''MAIN_USE_FPDF'') across many PDF model classes, e.g. core/modules/contract/doc/pdf_strato.modules.php:159 and core/modules/member/doc/pdf_standard_member.class.php:403.', 'When enabled, PDF document models switch their rendering engine to FPDF instead of TCPDF for generated documents.', NULL, 0, 0, NULL, 1, 'ea0350970d5522ac257b55759226d8ab971712d82dea460e643feb72f7701607', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MAIN_USE_FPDF'')) {", "core/modules/contract/doc/pdf_strato.modules.php:159|check"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_GEOPHP', 'bool', NULL, 'core', 'Enables loading of the geoPHP library for geographic/map data processing.', 'Checked at main.inc.php:1923 and :2082 to include the geoPHP library, and at core/class/extrafields.class.php:3176 to conditionally skip geo-field rendering.', 'Enabling this makes geoPHP available for geographic extra fields; disabling it suppresses geo-related features.', '0 or unset = geoPHP not loaded; 1 (truthy) = geoPHP loaded', 1, 0, NULL, 1, '7a51178972c270b39db9a28f83dd90237b67743378107e48510edbf27170ca05', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1923|check|if (getDolGlobalString(''MAIN_USE_GEOPHP'')) {", "main.inc.php:2082|check|if (getDolGlobalString(''MAIN_USE_GEOPHP'')) {", "core/class/extrafields.class.php:3176|check|if (!getDolGlobalString(''MAIN_USE_GEOPHP'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_HOURMIN_IN_DATE_RANGE', 'bool', NULL, 'core', 'Enables hour and minute selection in date range inputs on contract lines and object line templates.', 'When set to a non-zero integer, date range pickers in core/tpl/objectline_create.tpl.php:625 and objectline_view.tpl.php:185 switch from ''day'' format to ''dayhour'' format. Also read at contrat/card.php:95 and core/tpl/objectline_edit.tpl.php:436. No admin UI is provided.', 'Enabling this constant causes date range fields on contract lines to display and require hour/minute entry in addition to the date.', '0 or unset = date only (''day'' format); non-zero integer = date with hour and minute (''dayhour'' format).', 1, 0, NULL, 1, '66668d659bd790f046215712b076cde1e1c2172828f3c47ab55c7ae9c749f3bf', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_view.tpl.php:185|read|$format = (getDolGlobalInt(''MAIN_USE_HOURMIN_IN_DATE_RANGE'') ? ''dayhour'' : ''day'');", "core/tpl/objectline_create.tpl.php:625|read|print $form->selectDate($date_start, ''date_start'', getDolGlobalInt(''MAIN_USE_HOURMIN_IN_DATE_RANGE''), getDolGlobalInt(''MAIN_USE_HOURMIN_IN_DATE_RANGE''), 1, \"addproduct\", 1, 0);", "contrat/card.php:95|read|$usehm = getDolGlobalInt(''MAIN_USE_HOURMIN_IN_DATE_RANGE'');", "core/tpl/objectline_edit.tpl.php:436|read|$hourmin = getDolGlobalInt(''MAIN_USE_HOURMIN_IN_DATE_RANGE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_HTML5_COLOR_SELECTOR', 'bool', NULL, 'core', 'Disables the JS jPicker color-picker widget (jPicker CSS/JS assets), presumably to fall back to a native HTML5 color input, when set.', 'In core/class/html.formother.class.php:888, the jPicker stylesheet/script are only loaded if `!getDolGlobalInt(''MAIN_USE_HTML5_COLOR_SELECTOR'')` (and not jmobile, and javascript_ajax enabled); i.e. setting the constant skips loading the jPicker plugin.', 'Setting it stops the jPicker color-picker plugin assets from being loaded on pages using the color selector, presumably relying on native browser HTML5 color inputs instead [SPECULATION reasoning only, not confirmed by code shown].', 'Boolean-like (int): set/non-empty skips loading jPicker plugin assets; unset (default, 0) loads jPicker.', 1, 0, NULL, 1, '969dfd97ec4d7c9623d9aea01ca8913a06dea87b0f6544699a135bc8a5f503d7', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formother.class.php:888: if (empty($conf->dol_use_jmobile) && !empty($conf->use_javascript_ajax) && !getDolGlobalInt(''MAIN_USE_HTML5_COLOR_SELECTOR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_HTML5_LIMIT_SELECTOR', 'bool', NULL, 'core', 'Switches the page-size selector to use an HTML5 number input instead of a select dropdown.', 'Checked at core/lib/functions.lib.php:7600 and 7630. When truthy, the pagination widget renders an HTML5 limit input; otherwise the default select-based widget is rendered.', 'Enabling this constant replaces the dropdown page-size selector with a free-form number input, affecting usability of pagination controls.', '0 or empty = select-based page-size selector; any truthy value = HTML5 number input selector', 1, 0, NULL, 1, 'eb092e1bf956335a9f658f2dae82586f084beafca4c8c2e64b1ffc35ce12e0a8', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:7600|check|if (getDolGlobalString(''MAIN_USE_HTML5_LIMIT_SELECTOR'')) {", "core/lib/functions.lib.php:7630|check|if (getDolGlobalString(''MAIN_USE_HTML5_LIMIT_SELECTOR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_JQUERY_MULTISELECT', 'bool', NULL, 'core', 'Enables and specifies the jQuery multi-select plugin (e.g. Select2) to load globally.', 'Checked in main.inc.php:1885 and :2023 alongside the REQUIRE_JQUERY_MULTISELECT constant to decide whether to load the plugin. Read in main.inc.php:2025 and core/class/html.form.class.php:10032 to determine which plugin variant to use, defaulting to ''select2''.', 'Enabling this loads the multi-select widget globally; the value determines which plugin variant is used.', ''''' or unset = plugin not loaded globally (only per-page via REQUIRE_JQUERY_MULTISELECT); any valid plugin name = that plugin is loaded (e.g. ''select2'')', 1, 0, NULL, 1, 'b43c086fd859869c5de24c583adf9f98ee51ae874efc933c3adc70d4bcfcc64d', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1885|check|if (!defined(''DISABLE_SELECT2'') && (getDolGlobalString(''MAIN_USE_JQUERY_MULTISELECT'') || defined(''REQUIRE_JQUERY_MULTISELECT''))) {     // jQuery plugin \"mutiselect\", \"multiple-sele", "main.inc.php:2025|read|$tmpplugin = !getDolGlobalString(''MAIN_USE_JQUERY_MULTISELECT'') ? constant(''REQUIRE_JQUERY_MULTISELECT'') : getDolGlobalString(''MAIN_USE_JQUERY_MULTISELECT'');", "core/class/html.form.class.php:10032|read|$tmpplugin = getDolGlobalString(''MAIN_USE_JQUERY_MULTISELECT'', (defined(''REQUIRE_JQUERY_MULTISELECT'') ? constant(''REQUIRE_JQUERY_MULTISELECT'') : ''select2''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_JQUERY_THEME', 'bool', NULL, 'core', 'Specifies a custom jQuery UI theme to load instead of the default.', 'Checked and read in main.inc.php:1873-1874 and core/lib/security2.lib.php:306-307 to set the $jquerytheme variable used when loading jQuery UI CSS.', 'Setting this replaces the default jQuery UI theme with the named theme; unsetting it reverts to the default.', 'Any valid jQuery UI theme name string; empty/unset = default jQuery UI theme is used', 1, 0, NULL, 1, '6ac38bf65e0e47aad881639e22ed315824c5a09eae462fa66ca292121d35e8c7', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:1873|check|if (getDolGlobalString(''MAIN_USE_JQUERY_THEME'')) {", "main.inc.php:1874|read|$jquerytheme = getDolGlobalString(''MAIN_USE_JQUERY_THEME'');", "core/lib/security2.lib.php:307|read|$jquerytheme = getDolGlobalString(''MAIN_USE_JQUERY_THEME'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_LOCATION_INCOTERMS_DICTIONNARY', 'bool', NULL, 'core', 'Enables use of the c_location_incoterms dictionary table for the incoterms location autocomplete/ajax lookup.', 'Checked in core/ajax/locationincoterms.php:85 to decide whether the ajax endpoint queries the c_location_incoterms table for matching locations; also logged via dol_syslog at line 76.', 'When enabled, the location_incoterms ajax search queries the c_location_incoterms dictionary table (filtered by ''location LIKE %term%''); when disabled, this dictionary-based lookup is skipped.', 'Boolean-like: truthy enables querying the c_location_incoterms dictionary table.', 0, 0, NULL, 1, 'fd6e34a147a916bca79c8693bc6c011e1bb58333eb223f8e8eda3b34fd6dd941', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/locationincoterms.php:85: if (getDolGlobalString(''MAIN_USE_LOCATION_INCOTERMS_DICTIONNARY'')) {   // Use location_incoterms", "core/ajax/locationincoterms.php:76: dol_syslog(''location_incoterms call with MAIN_USE_LOCATION_INCOTERMS_DICTIONNARY=''.getDolGlobalString(...))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_METEO_WITH_PERCENTAGE', 'bool', NULL, 'admin', 'Switches the dashboard weather/health indicator between an absolute-value mode and a percentage-based calculation mode.', 'Checked throughout admin/delais.php to toggle between two display sections (''standard'' and ''percentage'') and their corresponding threshold configuration forms. When enabled, percentage-based thresholds are used; otherwise absolute values are used. Configurable via admin/delais.php.', 'Changing this setting alters how the dashboard health indicator is calculated and displayed, and which threshold configuration UI is shown in the admin panel.', 'Boolean flag: truthy = percentage mode; 0 or unset = absolute/standard mode.', 0, 0, 'admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php|admin/delais.php', 1, '0a0de4d0109a099ac7999ca85d2473fc3d2c723fd02ddf0e8e71d5b58db6185c', 'v2', '2026-04-21T11:16:15+00:00', '["admin/delais.php:363|read|print ''<div id=\"standard\" ''.(!getDolGlobalString(''MAIN_USE_METEO_WITH_PERCENTAGE'') ? '''' : ''style=\"display:none;\").''>'';", "admin/delais.php:383|read|print ''<div id=\"percentage\" ''.(!getDolGlobalString(''MAIN_USE_METEO_WITH_PERCENTAGE'') ? ''style=\"display:none;\"'' : '''').''>'';", "admin/delais.php:203|write|dolibarr_set_const($db, \"MAIN_USE_METEO_WITH_PERCENTAGE\", GETPOST(\"MAIN_USE_METEO_WITH_PERCENTAGE\"), ''chaine'', 0, '''', $conf->entity);", "admin/delais.php:207|check|if (getDolGlobalString(''MAIN_USE_METEO_WITH_PERCENTAGE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_NEW_SUPPLIERMOD', 'bool', NULL, 'core', 'Switches supplier invoice/payment permission and UI descriptors between the old and new supplier module implementations.', 'Read via getDolGlobalString(''MAIN_USE_NEW_SUPPLIERMOD'') in supplier_invoice/admin/supplier_payment.php:42 and supplier_invoice/admin/supplier_invoice.php:48; described in user/class/user.class.php:945 as a ''Compatibility layer for the supplier module split transition''.', 'Toggling it changes which old/new supplier permission descriptors are excluded, per user/perms.php:189 (''Exclude old/new supplier descriptors depending on MAIN_USE_NEW_SUPPLIERMOD'').', NULL, 0, 0, 'supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplier_invoice.php|supplier_invoice/admin/supplierinvoicedet_extrafields.php|supplier_invoice/admin/supplierinvoicedet_extrafields.php|supplier_invoice/admin/supplierinvoice_extrafields.php|supplier_invoice/admin/supplierinvoice_extrafields.php|supplier_invoice/admin/supplierinvoice_rec_extrafields.php|supplier_invoice/admin/supplierinvoice_rec_extrafields.php|supplier_invoice/admin/supplierinvoicedet_rec_extrafields.php|supplier_invoice/admin/supplierinvoicedet_rec_extrafields.php|supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php|supplier_order/admin/supplierorder_extrafields.php|supplier_order/admin/supplierorder_extrafields.php|supplier_order/admin/supplierorderdet_extrafields.php|supplier_order/admin/supplierorderdet_extrafields.php', 1, 'b24ecb3e11f78178e14ba31807d75aa8d38b31b82a891a72d411df9985ac987c', 'v2', '2026-07-24T06:41:12+00:00', '["// Exclude old/new supplier descriptors depending on MAIN_USE_NEW_SUPPLIERMOD", "// Compatibility layer for the supplier module split transition (MAIN_USE_NEW_SUPPLIERMOD)."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_OLD_SEARCH_FORM', 'bool', NULL, 'core', 'Forces the legacy search form instead of the modern AJAX search box.', 'Written programmatically at main.inc.php:3252 and checked at :3259 and :3285 to switch between the old and new search form implementations.', 'Enabling this reverts the top search box to the legacy form; disabling or unsetting it uses the modern AJAX search.', '0 or unset = modern AJAX search used; 1 = legacy search form used', 1, 0, NULL, 1, 'e124c9cb3c888f7cf91eee5834b806a7d74f8d2e5dfd7b60c011db6cec9bebd3', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:3252|write|$conf->global->MAIN_USE_OLD_SEARCH_FORM = 1;", "main.inc.php:3259|check|if (!empty($conf->use_javascript_ajax) && !getDolGlobalString(''MAIN_USE_OLD_SEARCH_FORM'')) {", "main.inc.php:3285|read|} elseif ($conf->use_javascript_ajax && getDolGlobalString(''MAIN_USE_OLD_SEARCH_FORM'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_PROPAL_REFCLIENT_FOR_ORDER', 'bool', NULL, 'commande', 'When creating an order from a proposal (origin), reuses/shows the proposal''s customer reference as the order''s ref_client field instead of a blank input.', 'Checked in commande/card.php:2345 and :2347; when true and origin/originid are set, the label shown becomes ''RefProposal'' and the ref_client input is prefilled from the source proposal''s ref_client.', 'When enabled, the order creation form (when created from a proposal) labels and prefills the reference field with the proposal''s customer reference; when disabled, a plain ''RefCustomer'' input is shown instead.', 'Boolean: 1/true reuses the proposal ref_client for the order ref field.', 0, 0, NULL, 1, '86bb05d8cff88ca28e591059f57219eb44187c40a0ef2a999ec82d2cbd18691b', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:2345: if (getDolGlobalString(''MAIN_ASK_CUSTOMER_REF_OF_SALE_ORDER_AT_CREATION'') || getDolGlobalString(''MAIN_USE_PROPAL_REFCLIENT_FOR_ORDER'')) {", "commande/card.php:2347: if (getDolGlobalString(''MAIN_USE_PROPAL_REFCLIENT_FOR_ORDER'') && !empty($origin) && !empty($originid)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_RESPONSE_TIMEOUT', 'bool', NULL, 'admin', 'Sets the cURL response (read) timeout in seconds for outbound HTTP and email collector connections.', 'Configured via admin/proxy.php:67 and overridden in-memory at admin/system/dolibarr.php:133 and admin/tools/update.php:103. Read by core/lib/functions2.lib.php:2045, core/lib/geturl.lib.php:150, admin/emailcollector_card.php:573, and paypal/lib/paypal.lib.php:507 with a default of 20–30 seconds.', 'Increasing this value allows more time for slow responses; decreasing it may cause premature timeouts on long-running requests.', 'Integer (seconds). Defaults to 20 or 30 depending on context if unset.', 0, 0, 'admin/emailcollector_card.php|admin/proxy.php|admin/system/dolibarr.php|admin/tools/update.php|admin/proxy.php', 1, '1c75997563e87298be2d7c24d3c4b6a3387937c28df6c70f168c4c108a5aadc0', 'v2', '2026-04-21T11:16:15+00:00', '["admin/system/dolibarr.php:133|write|$conf->global->MAIN_USE_RESPONSE_TIMEOUT = 10;", "core/lib/functions2.lib.php:2045|read|$response_timeout = getDolGlobalInt(''MAIN_USE_RESPONSE_TIMEOUT'', 30); // Response timeout", "paypal/lib/paypal.lib.php:507|read|curl_setopt($ch, CURLOPT_TIMEOUT, getDolGlobalInt(''MAIN_USE_RESPONSE_TIMEOUT'', 30));", "admin/emailcollector_card.php:573|read|$timeoutread = getDolGlobalInt(''MAIN_USE_RESPONSE_TIMEOUT'', 20);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_TITLE_FOR_CONTACT', 'bool', NULL, 'contact', 'Enables display and editing of a civility/title (M., Mme, etc.) field on the contact card.', 'Read twice in contact/card.php (lines 710 and 1020), guarding the display of a ''Civility'' row with a select_civility form field on both the create/edit form and (at line 1020) presumably the view mode.', 'Enabling it adds a civility/title selector field to the contact creation and edit forms; disabled/unset hides that field entirely.', 'Boolean-like: enabled = show civility/title field on contact card; unset/0 = hide it.', 0, 0, NULL, 1, '3148ce4240c272faf8f4463d20948133d9c9c931dacc39fc7d52a9612365f04b', 'v2', '2026-07-24T07:05:23+00:00', '["contact/card.php:710: if (getDolGlobalString(''MAIN_USE_TITLE_FOR_CONTACT'')) {", "contact/card.php:711: print $formcompany->select_civility(... ''civility_code'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_TITLE_FOR_MEMBER', 'bool', NULL, 'adherents', 'Shows the civility/title (Mr, Mrs, etc.) field on the member creation/edit form when enabled.', 'Checked in adherents/card.php:1192 and :1429 with if (getDolGlobalString(''MAIN_USE_TITLE_FOR_MEMBER'')) to conditionally print the UserTitle row with a civility selector.', 'When enabled, the member form displays a civility/title selection field; when disabled, this field is omitted entirely.', 'Boolean: 1/true enables the civility field, unset/0 hides it.', 0, 0, NULL, 1, 'a6e794e985a01ba7e4654dcff6da7012be25044117246c0e5ca080948fe8868a', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/card.php:1192: if (getDolGlobalString(''MAIN_USE_TITLE_FOR_MEMBER'')) {", "adherents/card.php:1429: if (getDolGlobalString(''MAIN_USE_TITLE_FOR_MEMBER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_TITLE_FOR_USER', 'bool', NULL, 'user', 'Enables the display and editing of a title/civility field on user profile pages.', 'Checked in user/card.php at lines 1032 and 2619. When set, the title field is rendered in user creation and editing forms.', 'Enabling this constant adds a title/civility input to user profile forms; leaving it unset hides the title field.', 'Truthy value to show title field; empty or unset to hide it.', 1, 0, NULL, 1, '9f6847de759cd5827f48c22798ed6a5d18ae76657bc3e8409b586620ccbf74a7', 'v2', '2026-04-21T13:50:40+00:00', '["user/card.php:1032|check|if (getDolGlobalString(''MAIN_USE_TITLE_FOR_USER'')) {", "user/card.php:2619|check|if (getDolGlobalString(''MAIN_USE_TITLE_FOR_USER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_TOP_MENU_IMPORT_FILE', 'bool', NULL, 'core', 'Enables or specifies a file-import button/URL in the top navigation menu bar.', 'Checked at main.inc.php:2250 and core/upload_page.php:90. When the value is a non-numeric string, it is used directly as the upload page URL (main.inc.php:2781, core/upload_page.php:91). The comment at main.inc.php:2763 documents the function called when set to 1 or a URL string.', 'Setting to 1 enables the default import page; setting to a URL string uses that URL as the import destination; unsetting hides the button.', '0 or unset = import button hidden; 1 = default import page used; non-numeric string = URL used as the import page', 1, 0, NULL, 1, '36a6aa9c145c01d5a2df2b5c17de237741806bbdfb620a6a30f3dbb4c763654a', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:2763  * Called when MAIN_USE_TOP_MENU_IMPORT_FILE is set to 1 or to an URL string.", "main.inc.php:2780|check|if (!is_numeric(getDolGlobalString(''MAIN_USE_TOP_MENU_IMPORT_FILE''))) {", "main.inc.php:2781|read|$urlforuploadpage = getDolGlobalString(''MAIN_USE_TOP_MENU_IMPORT_FILE'');", "core/upload_page.php:90|check|if (getDolGlobalString(''MAIN_USE_TOP_MENU_IMPORT_FILE'') && !is_numeric(getDolGlobalString(''MAIN_USE_TOP_MENU_IMPORT_FILE''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_TOP_MENU_QUICKADD_DROPDOWN', 'bool', NULL, 'core', 'Enables a quick-add dropdown button in the top navigation menu bar.', 'Checked at main.inc.php:2242 to include the quick-add dropdown, and at theme/eldy/style.css.php:374 for related CSS. The comment at main.inc.php:2693 documents the function called when this option is set.', 'Enabling this adds a quick-add dropdown to the top menu; disabling or unsetting it hides it.', '0 or unset = quick-add dropdown hidden; 1 (truthy) = quick-add dropdown shown', 1, 0, NULL, 1, '64ab8243f0d6357cf3793131eb19885587d34f83d5f8efe8068dc067137a779f', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:2693  * Called when option MAIN_USE_TOP_MENU_QUICKADD_DROPDOWN is set", "main.inc.php:2242|check|if (getDolGlobalString(''MAIN_USE_TOP_MENU_QUICKADD_DROPDOWN'')) {", "theme/eldy/style.css.php:374|check|if (getDolGlobalString(''MAIN_USE_TOP_MENU_QUICKADD_DROPDOWN'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_TOP_MENU_SEARCH_DROPDOWN', 'bool', NULL, 'theme', 'When enabled, replaces the default search bar with a dropdown search widget in the top menu.', 'Checked in main.inc.php:2237, :3249, theme/eldy/global.inc.php:2595, theme/eldy/style.css.php:377, and theme/md/style.css.php:4116 to conditionally render the dropdown search UI. Five occurrences across four files. No admin UI write is present.', 'Enabling this constant activates a dropdown search widget in the top navigation menu and suppresses the standard inline search.', 'Boolean flag; unset or 0 = standard search bar; any truthy value = dropdown search widget.', 1, 0, NULL, 1, 'b07e7c862d86a4b8f66a1ef80e8431e5ec2ccef7c10dcd893f0b1cc4e1a3860b', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:2237|check|if (getDolGlobalString(''MAIN_USE_TOP_MENU_SEARCH_DROPDOWN'')) {", "main.inc.php:3249|check|if (!getDolGlobalString(''MAIN_USE_TOP_MENU_SEARCH_DROPDOWN'')) {", "theme/eldy/global.inc.php:2595|check|<?php if (getDolGlobalString(''MAIN_USE_TOP_MENU_SEARCH_DROPDOWN'')) { ?>", "theme/eldy/style.css.php:377|check|if (getDolGlobalString(''MAIN_USE_TOP_MENU_SEARCH_DROPDOWN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_VAT_OF_PRODUCT_FOR_INDIVIDUAL_CUSTOMER_OUT_OF_EEC', 'bool', NULL, 'core', 'Applies the product''s own VAT rate to individual (non-company) customers located outside the EEC.', 'Checked at core/lib/functions.lib.php:8703. The comment at line 8702 states ''I don''t see any use case that need this rule, this case is on only if MAIN_USE_VAT_OF_PRODUCT_FOR_INDIVIDUAL_CUSTOMER_OUT_OF_EEC set''.', 'Enabling this constant activates an otherwise-unused VAT rule that applies the product''s VAT rate to non-EEC individual customers; without it the standard out-of-EEC VAT logic applies.', '0 or empty = standard VAT logic for individual customers outside EEC; any truthy value = product VAT rate applied for those customers', 1, 0, NULL, 1, 'ec65d43d1e358cdecfeb110ce1accd43703e518dc4206c5ccb05742f7b12159d', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:8702  // I don''t see any use case that need this rule, this case is on only if MAIN_USE_VAT_OF_PRODUCT_FOR_INDIVIDUAL_CUSTOMER_OUT_OF_EEC set", "core/lib/functions.lib.php:8703|check|if (empty($vatrule) && getDolGlobalString(''MAIN_USE_VAT_OF_PRODUCT_FOR_INDIVIDUAL_CUSTOMER_OUT_OF_EEC'') && empty($buyer_in_cee)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_VAT_ZERO_FOR_COMPANIES_IN_EEC_EVEN_IF_VAT_ID_UNKNOWN', 'bool', NULL, 'core', 'Forces VAT rate to zero for EEC companies even when their VAT ID is unknown or unverified.', 'Checked at core/lib/functions.lib.php:8601 and 8680. When this constant is absent or falsy, EEC companies without a known VAT ID are subject to normal VAT rules; when truthy, zero VAT is applied regardless.', 'Enabling this constant reduces VAT charged to EEC companies lacking a verified VAT ID; disabling it ensures VAT is applied normally in those cases.', '0 or empty = standard VAT rules apply for EEC companies without VAT ID; any truthy value = zero VAT forced for EEC companies even without VAT ID', 1, 0, NULL, 1, '41a6d370e80623c8e64760586fa3f1f35b23186e19aa7dad3ca29f2435ca1927', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:8601|check|if ($isacompany && !getDolGlobalString(''MAIN_USE_VAT_ZERO_FOR_COMPANIES_IN_EEC_EVEN_IF_VAT_ID_UNKNOWN'')) {", "core/lib/functions.lib.php:8680|check|if ($isacompany && !getDolGlobalString(''MAIN_USE_VAT_ZERO_FOR_COMPANIES_IN_EEC_EVEN_IF_VAT_ID_UNKNOWN'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_ZIPARCHIVE_FOR_ZIP_COMPRESS', 'bool', NULL, 'core', 'Selects PHP''s ZipArchive class (instead of the default compression path) when Dolibarr compresses a file/dir to .zip.', 'Used in core/lib/files.lib.php:2639 inside dol_compress_file(); for mode == ''zip'', ZipArchive is only used if the class exists AND this constant is set, otherwise another zip handler is used. A commented-out duplicate check exists at files.lib.php:2914.', 'Enabling it (with the ZipArchive PHP extension installed) switches zip creation to use ZipArchive rather than the fallback handler; effect is limited to how .zip files are produced internally.', 'Boolean-like: truthy (with ZipArchive class available) selects ZipArchive as the compression handler for zip mode.', 1, 0, NULL, 1, '008f9370bf3b56cf5976d0a9e36ea170c1716ce03b86d6607acfcc9ee630fd16', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/files.lib.php:2639|check|if (class_exists(''ZipArchive'') && getDolGlobalString(''MAIN_USE_ZIPARCHIVE_FOR_ZIP_COMPRESS'')) {", "core/lib/files.lib.php:2914  //if (class_exists(''ZipArchive'') && !empty($conf->global->MAIN_USE_ZIPARCHIVE_FOR_ZIP_COMPRESS))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_ZIPARCHIVE_FOR_ZIP_UNCOMPRESS', 'bool', NULL, 'core', 'When PclZip (ODTPHP_PATHTOPCLZIP) is configured, forces uncompression of .zip files to use ZipArchive instead of PclZip.', 'Used in core/lib/files.lib.php:2756 inside dol_uncompress(); PclZip is only chosen when ODTPHP_PATHTOPCLZIP is defined AND this constant is NOT set, so setting it truthy skips the PclZip branch even if that constant is defined.', 'Enabling it, on a system where ODTPHP_PATHTOPCLZIP is also configured, bypasses the PclZip unzip path (which otherwise logs ''so we use Pclzip to unzip'') in favor of another handler (ZipArchive) for .zip extraction.', 'Boolean-like: truthy skips the PclZip uncompression branch for .zip files, even when ODTPHP_PATHTOPCLZIP is defined.', 1, 0, NULL, 1, 'bd33552cb5ffa129101119cafe2d1daacd510a885741c13cf2c259afdbf866df', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/files.lib.php:2756|check|if (defined(''ODTPHP_PATHTOPCLZIP'') && !getDolGlobalString(''MAIN_USE_ZIPARCHIVE_FOR_ZIP_UNCOMPRESS'')) {", "dol_syslog(\"Constant ODTPHP_PATHTOPCLZIP for pclzip library is set to \".ODTPHP_PATHTOPCLZIP.\", so we use Pclzip to unzip into \".$outputdir);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_USE_ZIPTOWN_DICTIONNARY', 'bool', NULL, 'core', 'Controls whether zip/town lookups use the official public zip-town dictionary or company address data.', 'Checked and logged in core/ajax/ziptown.php (lines 55, 67, 80, 94). The comment at line 56 states verbatim: ''If MAIN_USE_ZIPTOWN_DICTIONNARY is set, we make a search into public data (official list of zip/town). If not we search into company data, so we must check we have read permission.''', 'Setting this switches the zip/town autocomplete source from company records (requiring read permission) to the public official dictionary.', 'Empty/unset = search company address data (requires read permission); any non-empty string = search official public zip/town dictionary.', 1, 0, NULL, 1, '6e111613946eff0e0f82ebd7cf8e9f6a4a1d0cea5c3f109e31d12ab9870dc801', 'v2', '2026-04-21T13:29:58+00:00', '["core/ajax/ziptown.php:56  // If MAIN_USE_ZIPTOWN_DICTIONNARY is set, we make a search into public data (official list of zip/town). If not we search into company data, so we must check we have read permission.", "core/ajax/ziptown.php:55|check|if (!getDolGlobalString(''MAIN_USE_ZIPTOWN_DICTIONNARY'')) {", "core/ajax/ziptown.php:80|check|if (getDolGlobalString(''MAIN_USE_ZIPTOWN_DICTIONNARY'')) {   // Use zip-town table"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VAT_DEFAULT', 'string', NULL, 'ai', 'Default VAT rate (as a float percentage) used by the AI CRUD tools helper when creating objects that need a VAT rate and none is otherwise specified.', 'Read in ai/tools/crud_objects.class.php:547-548: if non-empty, it is cast to float and used as $companyDefaultVAT; this is distinct from the more widely used MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS constant used elsewhere (functions.lib.php, html.form.class.php, comm/remx.php) for VAT autodetection fallback.', 'Setting it provides a default VAT percentage consumed specifically by the AI tools'' object-creation helper; it does not appear to affect the standard VAT autodetection fallback path (that uses the differently-named MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS).', 'Float, VAT rate percentage (e.g. 20 for 20%).', 1, 0, NULL, 1, '8642f102e52bac38fad99b4f0b1a0ddb9eb9194dde9f1b6b2bc6bef85ebe7d11', 'v2', '2026-07-24T07:05:23+00:00', '["ai/tools/crud_objects.class.php:547: if (! empty($conf->global->MAIN_VAT_DEFAULT)) {", "ai/tools/crud_objects.class.php:548: $companyDefaultVAT = (float) $conf->global->MAIN_VAT_DEFAULT;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS', 'string', NULL, 'core', 'Sets the fallback VAT rate used when automatic VAT detection cannot determine the correct rate.', 'When VAT auto-detection fails, the system reads this constant to supply a default tax rate (core/lib/functions.lib.php:8471). Setting it to ''none'' suppresses any default rate, as forced in expense reports (expensereport/card.php:2666). Used in both the form helper (core/class/html.form.class.php:7565) and AJAX product lookups (comm/remx.php:476).', 'Setting to ''none'' prevents any VAT from being pre-filled when detection fails. Setting to a numeric rate string causes that rate to be applied automatically across invoices, proposals, and expense reports.', '''none'' = no default VAT applied; a numeric string (e.g. ''20'') = that rate is used as fallback', 1, 0, NULL, 1, 'e602fd6a6d41aba5ad84ea99cb8033e798424794cf6ea364ffa3066cb8169fc0', 'v2', '2026-04-21T11:16:15+00:00', '["expensereport/card.php:2665  // If option to have no default VAT on expense report is on, we force MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS", "core/lib/functions.lib.php:8466  // Forced value if autodetect fails. MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS can be", "core/class/html.form.class.php:7562  // We will use the rate defined into MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS", "expensereport/card.php:2666|write|$conf->global->MAIN_VAT_DEFAULT_IF_AUTODETECT_FAILS = ''none'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VAT_LABEL_IS_POSITIVE_RATES', 'string', NULL, 'core', 'Forces VAT rate dropdowns to show the detailed ''positive rates'' label (combined local taxes and code) instead of the simple rate label, even outside India.', 'core/class/html.form.class.php:8187: `if ($mysoc->country_code == ''IN'' || getDolGlobalString(''MAIN_VAT_LABEL_IS_POSITIVE_RATES'')) { // Label with all localtax and code. For example: x.y / a.b / c.d (CODE)'' $return .= $rate[''labelpositiverates'']; } else { // Simple label $return .= vatrate($rate[''label'']); }`.', 'Setting it to a truthy value makes the VAT rate selector display the combined ''x.y / a.b / c.d (CODE)'' style label (normally reserved for India, country_code==''IN'') for all companies, regardless of country.', 'Truthy = use $rate[''labelpositiverates''] format ''x.y / a.b / c.d (CODE)'' (same as forced for country_code==''IN''); 0/unset = simple vatrate() label (default for non-Indian companies).', 0, 0, NULL, 1, 'e3587e60256bbd13640c940492d822ed7661639e6b3547d270ad1b21b4639c71', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:8187: if ($mysoc->country_code == ''IN'' || getDolGlobalString(''MAIN_VAT_LABEL_IS_POSITIVE_RATES'')) {", "core/class/html.form.class.php:8188: // Label with all localtax and code. For example:  x.y / a.b / c.d (CODE)''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VERSION_FIRST_INSTALL', 'string', NULL, 'core', 'Records the Dolibarr version at which this instance was first installed.', 'Written in install/step5.php at line 333 during first install inside a dedicated transaction (comment: ''Insert MAIN_VERSION_FIRST_INSTALL in a dedicated transaction. So if it fails (when first install was already done), we can do other following requests.''). Read in install/upgrade2.php at line 5400 with DOL_VERSION as fallback.', 'This constant is set once at installation and used by upgrade logic to determine the original install version. Modifying it manually could affect upgrade path decisions.', 'Dolibarr version string (e.g. ''17.0.0'') set at first installation', 1, 0, NULL, 1, '26048b562d4f84f2f2dbffb1d0c8bcf1cd94a983238711f394562dde6d21621e', 'v2', '2026-04-21T11:16:15+00:00', '["// Insert MAIN_VERSION_FIRST_INSTALL in a dedicated transaction. So if it fails (when first install was already done), we can do other following requests.", "$conf->global->MAIN_VERSION_FIRST_INSTALL = $targetversion;", "$firstInstallVersion = getDolGlobalString(''MAIN_VERSION_FIRST_INSTALL'', DOL_VERSION);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VERSION_LAST_INSTALL', 'string', NULL, 'core', 'Stores the Dolibarr version string at the time of the last fresh installation.', 'Set by install/step5.php during first install as documented in comments at lines 32 and 87. Read extensively across admin/system/dolibarr.php, blockedlog/admin/filecheck.php, and install/check.php (18+ occurrences) to detect version mismatches and warn when an update process may be required.', 'If this value does not match DOL_VERSION, admin pages display a warning that the update process may need to be run. It is used by filecheck to compare against the running version.', 'A Dolibarr version string (e.g. ''18.0.1''); set automatically during installation.', 0, 0, 'blockedlog/admin/filecheck.php|blockedlog/admin/filecheck.php|blockedlog/admin/filecheck.php|admin/system/dolibarr.php|admin/system/dolibarr.php|admin/system/dolibarr.php|admin/system/dolibarr.php', 1, 'd5090bfc9725562015d50dad4ab4e4fb7e9e3499df8a68bacf357434723a4226', 'v2', '2026-04-21T11:16:15+00:00', '["*         It set the value for MAIN_VERSION_LAST_INSTALL", "// Define targetversion used to update MAIN_VERSION_LAST_INSTALL for first install", "if (DOL_VERSION != getDolGlobalString(''MAIN_VERSION_LAST_INSTALL'')) {", "print '' ''.img_warning($langs->trans(\"RunningUpdateProcessMayBeRequired\", DOL_VERSION, getDolGlobalString(''MAIN_VERSION_LAST_INSTALL'')));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VERSION_LAST_UPGRADE', 'string', NULL, 'core', 'Records the Dolibarr version string at which the last database upgrade was successfully completed.', 'Written by install/step5.php during installation and upgrade processes. Checked in admin/system/dolibarr.php:108/:115 and blockedlog/admin/filecheck.php:90/:97 to detect version mismatches requiring an upgrade run. COMMENTS confirm: ''It updates the value for MAIN_VERSION_LAST_UPGRADE'' and ''Current version is $conf->global->MAIN_VERSION_LAST_UPGRADE''.', 'If this value does not match DOL_VERSION, the admin UI displays a warning that the upgrade process must be run; it is set automatically by the installer and should not be changed manually.', 'Version string matching Dolibarr release format (e.g., ''19.0.0''); set automatically by install/upgrade process', 0, 0, 'blockedlog/admin/filecheck.php|blockedlog/admin/filecheck.php|blockedlog/admin/filecheck.php|blockedlog/admin/filecheck.php|admin/system/dolibarr.php|admin/system/dolibarr.php|admin/system/dolibarr.php|admin/system/dolibarr.php|admin/system/dolibarr.php', 1, 'e72e9a4c12045620bc4d63c28c67518e59d5ae388ebf823c03c59ad78bb6422b', 'v2', '2026-04-21T11:16:15+00:00', '["install/step5.php:36  *         It updates the value for MAIN_VERSION_LAST_UPGRADE.", "install/upgrade2.php:329  // Current version is $conf->global->MAIN_VERSION_LAST_UPGRADE", "admin/system/dolibarr.php:115|check|if (DOL_VERSION != getDolGlobalString(''MAIN_VERSION_LAST_UPGRADE'')) {", "blockedlog/admin/filecheck.php:97|check|if (in_array(versioncompare(versiondolibarrarray(), preg_split(''/[\\-\\.]/'', getDolGlobalString(''MAIN_VERSION_LAST_UPGRADE''))), array(-2, -1, 1, 2))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VIEW_LINE_NUMBER', 'string', NULL, 'core', 'Adds a line-number column to document and list line item tables.', 'Checked in 48 locations across template files and card pages (e.g. reception/tpl/objectline_title.tpl.php:69, reception/card.php:2425, variants/tpl/productattributevalueline_title.tpl.php:49). A comment at core/class/commonobject.class.php:9790 notes that an additional td column is output when this constant is set.', 'Enabling this constant prepends a row-number column to line item tables on cards and templates throughout the application.', 'Non-empty = line number column shown; 0 or unset = no line number column.', 1, 0, NULL, 1, '07e3b67a71a5f2e5769e1eca9038ff637aef04f15fe50f95fea9dae081093e35', 'v2', '2026-04-21T11:16:15+00:00', '["reception/tpl/objectline_title.tpl.php:69|check|if (getDolGlobalString(''MAIN_VIEW_LINE_NUMBER'')) {", "reception/card.php:2425|check|if (getDolGlobalString(''MAIN_VIEW_LINE_NUMBER'')) {", "variants/tpl/productattributevalueline_title.tpl.php:49|check|if (getDolGlobalString(''MAIN_VIEW_LINE_NUMBER'')) {", "// a first td column was already output (and may be another on before if MAIN_VIEW_LINE_NUMBER set), so this td is the next one"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VIEW_LINE_NUMBER_IN_LIST', 'string', NULL, 'compta', 'Displays a line number column in list views throughout Dolibarr.', 'Checked in 20 occurrences across compta/tva/list.php, fourn/paiement/list.php, compta/facture/list.php, compta/sociales/list.php, and compta/bank/various_payment/list.php among others. Each check gates the rendering of a line number column.', 'When enabled, list pages show an additional column with the sequential row number, aiding navigation in long lists.', '0 or unset = no line numbers; non-empty = line numbers shown', 1, 0, NULL, 1, '2b4a4db123db5b111315e8a6d1fb7712f2fc15b86bf9a8c4c9398bd08c16ed05', 'v2', '2026-04-21T11:16:15+00:00', '["compta/tva/list.php:431|check|if (getDolGlobalString(''MAIN_VIEW_LINE_NUMBER_IN_LIST'')) {", "fourn/paiement/list.php:429|check|if (getDolGlobalString(''MAIN_VIEW_LINE_NUMBER_IN_LIST'')) {", "compta/facture/list.php:2444|check|if (getDolGlobalString(''MAIN_VIEW_LINE_NUMBER_IN_LIST'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VOLUME_DEFAULT_ROUND', 'string', NULL, 'expedition', 'Sets the default rounding precision for volume display in dimension summary sections.', 'Passed as the rounding parameter to showDimensionInBestUnit() in reception/card.php:2269 and 2260, expedition/card.php:3024 and 3015, expedition/shipment.php:512, comm/propal/card.php:3326, and commande/card.php:3235. The default fallback is -1. No admin UI write path exists.', 'Changing this value alters how many decimal places are shown for volume totals on reception, shipment, proposal, and order pages.', 'Integer precision value passed to showDimensionInBestUnit(); default fallback is -1', 1, 0, NULL, 1, '2ed8b85933820a595e89d7bd1eea9dc5cb20a0b23dd33c013f31599b1f20d23b', 'v2', '2026-04-21T11:16:15+00:00', '["reception/card.php:2269|read|print showDimensionInBestUnit($totalVolume, 0, \"volume\", $langs, getDolGlobalInt(''MAIN_VOLUME_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_VOLUME_DEFAULT_UNIT'', ''no''));", "expedition/card.php:3024|read|print showDimensionInBestUnit($totalVolume, 0, \"volume\", $langs, getDolGlobalInt(''MAIN_VOLUME_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_VOLUME_DEFAULT_UNIT'', ''no''));", "commande/card.php:3235|read|print showDimensionInBestUnit($totalVolume, 0, \"volume\", $langs, getDolGlobalInt(''MAIN_VOLUME_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_VOLUME_DEFAULT_UNIT'', ''no''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_VOLUME_DEFAULT_UNIT', 'string', NULL, 'expedition', 'Sets the default unit for volume display in dimension summary sections.', 'Passed as the forceunitoutput parameter to showDimensionInBestUnit() across reception, expedition, proposals, and orders (7 occurrences). The default fallback is ''no''. No admin UI write path exists.', 'Changing this value forces volume totals to be displayed in a specific unit; ''no'' lets the function select the most appropriate unit.', '''no'' or numeric string (-3, -6, ...) compared to $unit; default fallback is ''no''', 1, 0, NULL, 1, 'c304304a6a37ed0803b08d40e67063dcaed4bbc26a09a3a19f15d9c144a26fd7', 'v2', '2026-04-21T11:16:15+00:00', '["reception/card.php:2269|read|print showDimensionInBestUnit($totalVolume, 0, \"volume\", $langs, getDolGlobalInt(''MAIN_VOLUME_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_VOLUME_DEFAULT_UNIT'', ''no''));", "expedition/card.php:3024|read|print showDimensionInBestUnit($totalVolume, 0, \"volume\", $langs, getDolGlobalInt(''MAIN_VOLUME_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_VOLUME_DEFAULT_UNIT'', ''no''));", "commande/card.php:3235|read|print showDimensionInBestUnit($totalVolume, 0, \"volume\", $langs, getDolGlobalInt(''MAIN_VOLUME_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_VOLUME_DEFAULT_UNIT'', ''no''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_WAREHOUSE_LIST_DISPLAY_MODE', 'bool', NULL, 'product', 'Controls the display mode of the warehouse list in the product warehouse selector.', 'Checked in product/class/html.formproduct.class.php:262 and :266 to determine whether warehouses are shown flat or filtered by parent. The comment at line 247 states: ''Set Hidden conf MAIN_WAREHOUSE_LIST_DISPLAY_MODE at 0 || 1 || 2 to unlock display''.', 'Changing this constant alters how warehouses are presented in the selector: flat listing, hierarchical, or filtered by parent.', 'Set Hidden conf MAIN_WAREHOUSE_LIST_DISPLAY_MODE at 0 || 1 || 2 to unlock display', 1, 0, NULL, 1, '3429c72179a5d4a274f00179f323f502b9a8f4adfa1513c7d740805453c349fe', 'v2', '2026-04-21T11:16:15+00:00', '["product/class/html.formproduct.class.php:247  * Set Hidden conf MAIN_WAREHOUSE_LIST_DISPLAY_MODE at 0 || 1 || 2 to unlock display", "product/class/html.formproduct.class.php:262|check|if (empty($tab[''parent_id'']) || getDolGlobalInt(''MAIN_WAREHOUSE_LIST_DISPLAY_MODE'') === 1) {", "product/class/html.formproduct.class.php:266|check|if (getDolGlobalInt(''MAIN_WAREHOUSE_LIST_DISPLAY_MODE'') !== 2 || (getDolGlobalInt(''MAIN_WAREHOUSE_LIST_DISPLAY_MODE'') === 2 && empty($this->cache_warehouses[$tab[''parent_id'']][''par"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_WEIGHT_DEFAULT_ROUND', 'string', NULL, 'expedition', 'Sets the default rounding precision for weight display in dimension summary sections.', 'Passed as the rounding parameter to showDimensionInBestUnit() in reception/card.php:2208, comm/propal/card.php:3320, expedition/shipment.php:508, expedition/card.php:2963, expedition/list.php:1630, and commande/card.php:3229. The default fallback is -1. No admin UI write path exists.', 'Changing this value alters how many decimal places are shown for weight totals on reception, shipment, proposal, and order pages.', 'Integer precision value passed to showDimensionInBestUnit(); default fallback is -1', 1, 0, NULL, 1, '199f51e564c85e95e7bda297d2c0a55fc9f5292d3c2a0497a52ec8bb26cb67fc', 'v2', '2026-04-21T11:16:15+00:00', '["reception/card.php:2208|read|print showDimensionInBestUnit($totalWeight, 0, \"weight\", $langs, getDolGlobalInt(''MAIN_WEIGHT_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_WEIGHT_DEFAULT_UNIT'', ''no''));", "expedition/card.php:2963|read|print showDimensionInBestUnit($totalWeight, 0, \"weight\", $langs, getDolGlobalInt(''MAIN_WEIGHT_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_WEIGHT_DEFAULT_UNIT'', ''no''));", "commande/card.php:3229|read|print showDimensionInBestUnit($totalWeight, 0, \"weight\", $langs, getDolGlobalInt(''MAIN_WEIGHT_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_WEIGHT_DEFAULT_UNIT'', ''no''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_WEIGHT_DEFAULT_UNIT', 'string', NULL, 'expedition', 'Sets the default unit for weight display in dimension summary sections.', 'Passed as the forceunitoutput parameter to showDimensionInBestUnit() across reception, expedition, proposals, and orders. Documented in core/lib/functions.lib.php:8013 as ''no'' or a numeric exponent (-3, -6, ...) relative to the base unit. The default fallback is ''no''.', 'Changing this value forces weight totals to be displayed in a specific unit rather than automatically chosen; ''no'' lets the function select the most appropriate unit.', '''no'' or numeric string (-3, -6, ...) compared to $unit (as documented in core/lib/functions.lib.php:8013); default fallback is ''no''', 1, 0, NULL, 1, '9b6194d318bc8e15147632cf282f4c3bdd663744ce36ec0176246fcb2e5b49a7', 'v2', '2026-04-21T11:16:15+00:00', '["* @param   string      $forceunitoutput    ''no'' or numeric (-3, -6, ...) compared to $unit (In most case, this value is value defined into $conf->global->MAIN_WEIGHT_DEFAULT_UNIT)", "reception/card.php:2208|read|print showDimensionInBestUnit($totalWeight, 0, \"weight\", $langs, getDolGlobalInt(''MAIN_WEIGHT_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_WEIGHT_DEFAULT_UNIT'', ''no''));", "expedition/card.php:2963|read|print showDimensionInBestUnit($totalWeight, 0, \"weight\", $langs, getDolGlobalInt(''MAIN_WEIGHT_DEFAULT_ROUND'', -1), getDolGlobalString(''MAIN_WEIGHT_DEFAULT_UNIT'', ''no''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAIN_WORKBOARD_SHOW_TOTAL_WO_TAX', 'bool', NULL, 'index.php', 'Shows the total amount (without tax) next to the pending-item count on dashboard workboard indicators.', 'Used twice in index.php (lines 700 and 816) to conditionally append a formatted price total (via price($board->total,...)) after the todo count for each workboard line.', 'Setting it to true displays an extra amount-without-tax figure alongside each dashboard workboard indicator when that board has a total > 0.', 'Boolean-like: true/1 shows the total-without-tax amount next to the count.', 1, 0, NULL, 1, 'd196202e21cb229d04a0a757584f0ec9039d699ffb07ba6459fbda9776e79adc', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:816|check|if ($board->total > 0 && getDolGlobalString(''MAIN_WORKBOARD_SHOW_TOTAL_WO_TAX'')) {", "index.php:700|check|if ($board->total > 0 && getDolGlobalString(''MAIN_WORKBOARD_SHOW_TOTAL_WO_TAX'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MARGIN_METHODE_FOR_DISCOUNT', 'string', NULL, 'core', 'Selects how a global discount is accounted for in margin calculations.', 'Set via admin UI at margin/admin/margin.php:75/214, and read in core/class/html.formmargin.class.php:132/144/154 with inline comments distinguishing the modes.', 'Changing the value changes how global discounts are treated in margin computation: as a product, as a service, or only applied on the total.', '''1'' = global discount treated as product; ''2'' = global discount treated as service; ''3'' = remise globale prise en compte uniqt sur total', 0, 0, 'margin/admin/margin.php|margin/admin/margin.php', 1, 'a590fd278d15a4bde24a678aeeb850ca87a0c1b501b303bdd64c11a85e8b70e2', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''MARGIN_METHODE_FOR_DISCOUNT'') == ''1'') { // global discount treated as product", "} elseif (getDolGlobalString(''MARGIN_METHODE_FOR_DISCOUNT'') == ''2'') { // global discount treated as service", "} elseif (getDolGlobalString(''MARGIN_METHODE_FOR_DISCOUNT'') == ''3'') { // remise globale prise en compte uniqt sur total"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MARGIN_SHOW_MARGIN_ON_PAYMENT', 'bool', NULL, 'compta', 'Shows margin information on the payment card when the margin module is enabled.', 'Checked with getDolGlobalInt(''MARGIN_SHOW_MARGIN_ON_PAYMENT'') in compta/paiement/card.php at lines 523, 547, and 581 (combined with isModEnabled(''margin'')).', 'When enabled (and the margin module active), the payment card displays margin info such as $marginInfo.', NULL, 0, 0, NULL, 1, '2ca84098c0fd735e76de8418c2729e4036ffd2db068818dcc4d1772c3882458d', 'v2', '2026-07-24T06:41:12+00:00', '["if (isModEnabled(''margin'') && getDolGlobalInt(''MARGIN_SHOW_MARGIN_ON_PAYMENT'')) {", "if (isModEnabled(''margin'') && getDolGlobalInt(''MARGIN_SHOW_MARGIN_ON_PAYMENT'') && $marginInfo !== null) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MARGIN_SHOW_ON_CONTRACT', 'bool', NULL, 'contrat', 'Enables display of margin information on the contract card when the Margin module is active.', 'All five occurrences in contrat/card.php check both isModEnabled(''margin'') and this constant before rendering margin-related sections (e.g., at lines 1756, 1653, 1786, 1920, 1961). No admin UI is provided.', 'Setting this constant causes margin data to appear on the contract detail page, provided the Margin module is also enabled.', 'Non-empty/truthy = margin sections shown on contract card; empty/unset = margin sections hidden.', 1, 0, NULL, 1, '0f1e7b89772065245ee8dfcbcd9ae327b792144cb0104977d875d3ec7c2ce319', 'v2', '2026-04-21T11:16:15+00:00', '["contrat/card.php:1756|check|if (isModEnabled(''margin'') && getDolGlobalString(''MARGIN_SHOW_ON_CONTRACT'')) {", "contrat/card.php:1653|check|if (isModEnabled(''margin'') && getDolGlobalString(''MARGIN_SHOW_ON_CONTRACT'')) {", "contrat/card.php:1786|check|if (isModEnabled(''margin'') && getDolGlobalString(''MARGIN_SHOW_ON_CONTRACT'')) {", "contrat/card.php:1920|check|if (isModEnabled(''margin'') && getDolGlobalString(''MARGIN_SHOW_ON_CONTRACT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MARGIN_TOP_ZERO_UL', 'string', NULL, 'core', 'Reduces the vertical spacing (margins) applied to HTML <ul>/<li> lists rendered inside PDF line descriptions.', 'Checked in core/lib/pdf.lib.php:1879; when set, list indent width is set to 5 and a custom $TMarginList array (h=0.1 for ul/li) is passed to $pdf->setHtmlVSpace(), tightening the default TCPDF list margins/indentation.', 'Makes HTML bullet/numbered lists in product/service descriptions render with near-zero top margin and a narrower indent instead of TCPDF''s default spacing.', 'Boolean-like (set/unset); when set, list indent width=5 and vertical spacing (h)=0.1 for ul and li', 1, 0, NULL, 1, '3b9e811b7eb1156e2000f62e2d55ffc0689ddb3f112cddb7f87d62e90d3fa90b', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1879|check|if (getDolGlobalString(''MARGIN_TOP_ZERO_UL'')) {", "core/lib/pdf.lib.php:1880: $pdf->setListIndentWidth(5);", "core/lib/pdf.lib.php:1881: $TMarginList = [''ul'' => [[''h'' => 0.1, ],[''h'' => 0.1, ]], ''li'' => [[''h'' => 0.1, ],],];"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MARGIN_TYPE', 'string', NULL, 'margin', 'Determines the cost basis used for margin calculations across invoices, orders, and proposals.', 'Set via margin/admin/margin.php:80 and checked in 27+ locations. Comments at core/class/commonobject.class.php:10017-10018 and margin/admin/margin.php describe the values: ''1'' uses the buy price, ''pmp'' uses the weighted average price (prix moyen pondere), and ''costprice'' uses the product''s defined cost price. Admin UI available at margin/admin/margin.php.', 'Changing this value switches the cost reference used for margin computation across all document types; incorrect configuration leads to inaccurate margin reporting.', '''1'' = use buy price; ''pmp'' = use weighted average price (pmp); ''costprice'' = use product cost price.', 0, 0, 'margin/admin/margin.php|margin/admin/margin.php|margin/admin/margin.php|margin/admin/margin.php', 1, '435302d150211426b4445805d6859d5488eee92e0ca515f0c3a9291e99254263', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/commonobject.class.php:10017  *   elseif calculation MARGIN_TYPE = ''costprice'' and costprice is defined, use costprice as buyprice", "core/class/commonobject.class.php:10018  *\t elseif calculation MARGIN_TYPE = ''pmp'' and pmp is calculated, use pmp as buyprice", "margin/admin/margin.php:128|check|if (getDolGlobalString(''MARGIN_TYPE'') == ''1'') {", "margin/admin/margin.php:135|check|if (getDolGlobalString(''MARGIN_TYPE'') == ''pmp'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MASS_ACTION_EMAIL_ON_DIFFERENT_THIRPARTIES_ADD_CUSTOM_EMAIL', 'string', NULL, 'core', 'Adds an extra free-text email input next to the ''group emails / one email per recipient'' option on mass-email forms, letting the sender add a custom recipient.', 'Checked in core/class/html.formmail.class.php:862, inside the ''one email per recipient'' checkbox block (abs($this->withoptiononeemailperrecipient) == 1): if set and $this->withto is a non-array value, an extra ''<input type="email" name="emailto">'' field is shown alongside an ''or'' label.', 'When enabled, users composing a mass email with the one-email-per-recipient option see an additional free-text email field to add a custom recipient address; has no effect if withto is empty or already an array.', 'Boolean-like: truthy shows the extra custom-email input field.', 1, 0, NULL, 1, '834d413d2b23ae6da7f36349a5a55cb826dc3d51b20fc4239105fd1d8dc1fe4d', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formmail.class.php:862: if (getDolGlobalString(''MASS_ACTION_EMAIL_ON_DIFFERENT_THIRPARTIES_ADD_CUSTOM_EMAIL'')) {", "core/class/html.formmail.class.php:863-865: if (!empty($this->withto) && !is_array($this->withto)) { ... <input type=\"email\" name=\"emailto\"...}"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAXREFONDOC', 'string', NULL, 'commande', 'Sets the maximum number of linked order references displayed on documents and list views.', 'Checked in fourn/commande/list.php:601, core/lib/pdf.lib.php:3002, and commande/list.php:462 and :668 via getDolGlobalInt with a default of 10. No admin UI is configured.', 'Increasing this value allows more linked order references to be shown on PDFs and list views. Setting to 0 or a negative value suppresses linked-order display.', 'Integer; default is 10.', 1, 0, NULL, 1, '9feceee99ba42a7c4f7585d7e1a47d504bd69ea5dd57133086838646c591d82e', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/commande/list.php:601|check|if ($currentIndex <= (getDolGlobalInt(\"MAXREFONDOC\") ? getDolGlobalInt(\"MAXREFONDOC\") : 10)) {", "core/lib/pdf.lib.php:3002|check|if (count($objects) > 1 && count($objects) <= getDolGlobalInt(\"MAXREFONDOC\", 10) && !getDolGlobalString($optiontohidelinkedorders)) {", "commande/list.php:668|check|if ($currentIndex <= getDolGlobalInt(\"MAXREFONDOC\", 10)) {", "commande/list.php:462|check|if (empty($objecttmp->note_public) && getDolGlobalInt(\"MAXREFONDOC\", 10)>0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAX_EXTRAFIELDS_TO_SHOW_IN_TOOLTIP', 'bool', NULL, 'core', 'Maximum number of extrafields displayed in an object''s hover tooltip before the rest are omitted.', 'Read in core/class/commonobject.class.php:1054 inside getTooltipContent(): `$MAX_EXTRAFIELDS_TO_SHOW_IN_TOOLTIP = getDolGlobalInt(''MAX_EXTRAFIELDS_TO_SHOW_IN_TOOLTIP'', 3);` with a default of 3, preceded by comment ''If there is too much extrafields, we do not include them into tooltip''.', 'Raising the value shows more extrafields in tooltips; lowering it (or leaving the default of 3) truncates the extrafield list shown when hovering an object reference.', 'Integer count; default is 3 when unset (per getDolGlobalInt second argument).', 1, 0, NULL, 1, '4009eac9e316e0311619994c246a623aec5587eee229d6e08bae4151c45697fa', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonobject.class.php:1054|read|$MAX_EXTRAFIELDS_TO_SHOW_IN_TOOLTIP = getDolGlobalInt(''MAX_EXTRAFIELDS_TO_SHOW_IN_TOOLTIP'', 3);", "// If there is too much extrafields, we do not include them into tooltip"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAX_FOR_TEST_EXPORT', 'string', NULL, 'exports', 'Developer/debug constant intended to cap the number of exported rows for testing on large databases; the code that reads and enforces it is currently commented out.', 'In exports/class/export.class.php:763 both the getDolGlobalInt() call and its only usage are commented out: `//$MAXFORTEST = getDolGlobalInt(''MAX_FOR_TEST_EXPORT''); // For test on large database, we can set it to a non zero value and uncomment code that use it later to limit the export size`.', 'Currently has no effect on export behavior in this codebase since both the read and the limiting logic are commented out; a developer would need to uncomment the code for this constant to do anything.', 'For test on large database, we can set it to a non zero value and uncomment code that use it later to limit the export size', 1, 0, NULL, 1, 'ac99ca10f6d0079990a8087c1f2925e350dad5d67387ec359d41c153d3d96eaf', 'v2', '2026-07-24T07:05:23+00:00', '["exports/class/export.class.php:763  //$MAXFORTEST = getDolGlobalInt(''MAX_FOR_TEST_EXPORT'');\t// For test on large database, we can set it to a non zero value and uncomment code that use it later to limit the export size"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MAX_YEAR_SELECT_DATE', 'string', NULL, 'core', 'Sets the latest year offered in the jQuery datepicker''s year range for date fields.', 'Read in Form::select_date() in core/class/html.form.class.php:8456, used to build the datepicker() ''yearRange'' option; defaults to current year plus 100.', 'Raising it extends the selectable year range forward in the JS datepicker widget; lowering it restricts how far forward a user can pick a year.', 'Integer year; default is idate(''Y'') + 100 (current year plus 100).', 1, 0, NULL, 1, '0f5c205425d6e80dcb2b62ef01aabb9741ea92939da4d3544b339757acf68d03', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:8456|read|$maxYear = getDolGlobalInt(''MAX_YEAR_SELECT_DATE'', (idate(''Y'') + 100));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_ADDON', 'string', NULL, 'core', 'Defines which member reference numbering module class is used to generate member references.', 'Read via getDolGlobalString(''MEMBER_ADDON'', ''mod_member_simple'') in core/modules/modAdherent.class.php:366-367, used to build both the class name and the file path.', 'Changing it selects a different numbering module class/file under core/modules/member/ for generating member references; defaults to ''mod_member_simple'' if unset.', 'default fallback: ''mod_member_simple''', 0, 0, NULL, 1, '0747b5393710733e369eed510582637ec3d44cc178264b200cf99e88ce2a4e47', 'v2', '2026-07-24T06:41:12+00:00', '["''class'' => getDolGlobalString(''MEMBER_ADDON'', ''mod_member_simple''),", "''path'' => \"/core/modules/member/\".getDolGlobalString(''MEMBER_ADDON'', ''mod_member_simple'').''.php''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_ADDON_PDF_ODT', 'string', NULL, 'adherents', 'Stores the name of the ODT template selected for generating member PDF documents.', 'Managed via the admin UI at adherents/admin/member.php. The value is written with dolibarr_set_const (:148) and deleted when a different template is chosen (:142). It is checked against available template names to mark the active selection (:501).', 'Changing or clearing this value switches or removes the ODT template used when generating member card PDF documents.', 'String name of the ODT template file; empty = no ODT template selected', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php|adherents/admin/member.php|adherents/admin/member.php', 1, '116135690fddfc3c97e21aa8b93862a8b98aca3f45e77544b2fce64ffb7ecd42', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:501|check|if (getDolGlobalString(''MEMBER_ADDON_PDF_ODT'') == $name) {", "adherents/admin/member.php:148|write|dolibarr_set_const($db, \"MEMBER_ADDON_PDF_ODT\", $value, ''chaine'', 0, '''', $conf->entity);", "adherents/admin/member.php:141|check|if (getDolGlobalString(''MEMBER_ADDON_PDF_ODT'') == \"$value\") {", "adherents/admin/member.php:142|write|dolibarr_del_const($db, ''MEMBER_ADDON_PDF_ODT'', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Comma/newline-separated list of directories to scan for ODT/ODS member document templates, configurable from the module''s own admin options screen.', 'Read in core/modules/member/doc/doc_generic_member_odt.class.php:123 to build the directory list (split on commas/newlines, DOL_DATA_ROOT token substituted, scanned for .ods/.odt files), and again at line 150 to prefill the editable textarea in the settings form (setModuleOptions action with param1=MEMBER_ADDON_PDF_ODT_PATH).', 'Setting it adds extra directories that are scanned for member ODT/ODS templates in addition to the module''s defaults; each directory is validated with is_dir() and a warning is shown if not found.', 'Free-text path list; comma or newline separated; may contain the literal token ''DOL_DATA_ROOT'' which is substituted with the real data root path.', 0, 0, NULL, 1, '801a8b422ccfc1e4a654f990a2a91a95ad52d2f808050badee349f3f88b98c89', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/member/doc/doc_generic_member_odt.class.php:123: $listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''MEMBER_ADDON_PDF_ODT_PATH''))));", "core/modules/member/doc/doc_generic_member_odt.class.php: <input type=\"hidden\" name=\"param1\" value=\"MEMBER_ADDON_PDF_ODT_PATH\">", "core/modules/member/doc/doc_generic_member_odt.class.php:150: $texte .= getDolGlobalString(''MEMBER_ADDON_PDF_ODT_PATH'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_ALLOW_CHANGE_OF_TYPE', 'bool', NULL, 'public', 'Controls whether a member''s type can be changed during the public payment/subscription process.', 'Rendered as a yes/no selector (with inverted logic) in adherents/admin/member.php:620. Checked twice in public/payment/newpayment.php:1771 and :1778 to conditionally display or allow type-change options.', 'Enabling this allows members to select a different membership type during payment; disabling locks the type.', '0 = type change not allowed; 1 = type change allowed during payment', 0, 0, 'adherents/admin/member.php', 1, '45fba1181d6a537391edc6ce4d4200cd9d08f9fe1e74be28e0a63561dd037abc', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:620|read|print $form->selectyesno(''MEMBER_ALLOW_CHANGE_OF_TYPE'', (getDolGlobalInt(''MEMBER_ALLOW_CHANGE_OF_TYPE'') ? 0 : 1), 1);", "public/payment/newpayment.php:1778|check|if (getDolGlobalString(''MEMBER_ALLOW_CHANGE_OF_TYPE'')) {", "public/payment/newpayment.php:1771|check|if (getDolGlobalString(''MEMBER_ALLOW_CHANGE_OF_TYPE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_CAN_CONVERT_CUSTOMERS_TO_MEMBERS', 'string', NULL, 'societe', 'Shows a ''New member'' action button on a third-party (customer/prospect) card, allowing that third-party to be converted/linked into an association member.', 'Checked in societe/card.php:3567: when the member module is enabled, the third-party has no existing linked member ($result==0), the third-party is customer or prospect (client==1 or 3), and this constant is set, a button linking to adherents/card.php?action=create&socid=... is displayed.', 'When set, users with rights can create a member record directly from a customer/prospect''s card; when unset, that shortcut button is not shown.', 'Not set/falsy (default): ''New member'' button not shown on third-party card. Truthy: button shown (for customers/prospects without an existing linked member, when module member is enabled).', 1, 0, NULL, 1, '04f5dfd45ff732910740beaf73bb682b3d440b65ec4c92ee39168dcb416dcb05', 'v2', '2026-07-24T07:05:23+00:00', '["societe/card.php:3567|check|if ($result == 0 && ($object->client == 1 || $object->client == 3) && getDolGlobalString(''MEMBER_CAN_CONVERT_CUSTOMERS_TO_MEMBERS'')) {", "societe/card.php:3568|code|print ''<a class=\"butAction\" href=\"''.DOL_URL_ROOT.''/adherents/card.php?&action=create&socid=''.$object->id..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_CODEMEMBER_ADDON', 'string', NULL, 'adherents', 'Selects the module used to generate member reference codes, defaulting to mod_member_simple.', 'Stores the name of the active member code generation module. Read in adherents/class/adherent.class.php to load the appropriate module class. Configured via adherents/admin/member.php.', 'Changing this value switches the algorithm used to auto-generate member reference numbers. The default is mod_member_simple.', 'Module name string, e.g. ''mod_member_simple'' (default)', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, '145baeb4fd300bfa7410d8533a7e900f5fc06750ca94267e14d5f13535c42cec', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/class/adherent.class.php:715|read|$modulenum = getDolGlobalString(''MEMBER_CODEMEMBER_ADDON'', ''mod_member_simple'');", "adherents/admin/member.php:369|check|if (getDolGlobalString(''MEMBER_CODEMEMBER_ADDON'', ''mod_member_simple'') == \"$file\") {", "adherents/admin/member.php:230|write|$result = dolibarr_set_const($db, \"MEMBER_CODEMEMBER_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_COUNTERS_ARE_PUBLIC', 'string', NULL, 'adherents', 'Controls whether member count statistics are displayed publicly on the member registration page.', 'Written via adherents/admin/website.php:94, read in public/members/new.php:1337 to set the $publiccounters variable. Admin UI at adherents/admin/website.php:292 uses selectyesno.', 'Enabling this constant makes member count information visible on the public registration page.', '0 (counters hidden) or 1 (counters public)', 0, 0, 'adherents/admin/website.php|adherents/admin/website.php', 1, '190718ff4717a731adb0db89279b585b6d55c47ab809891375620df470078595', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/website.php:94|write|$res = dolibarr_set_const($db, \"MEMBER_COUNTERS_ARE_PUBLIC\", $publiccounters, ''chaine'', 0, '''', $conf->entity);", "adherents/admin/website.php:292|read|print $form->selectyesno(\"MEMBER_COUNTERS_ARE_PUBLIC\", getDolGlobalInt(''MEMBER_COUNTERS_ARE_PUBLIC''), 1, false, 0, 1);", "public/members/new.php:1337|read|$publiccounters = getDolGlobalString(\"MEMBER_COUNTERS_ARE_PUBLIC\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_CUSTOM_MASK', 'string', NULL, 'core', 'Stores the numbering mask pattern used by the custom member reference numbering module.', 'Used in core/modules/member/mod_member_custom.php in two locations (lines 91 and 139) where the mask is retrieved and used to generate member reference numbers.', 'Changing the mask pattern alters how new member references are formatted. Clearing it causes the custom numbering module to have no mask to apply.', 'Any string = mask pattern for member reference generation; empty/unset = no mask pattern.', 1, 0, NULL, 1, '8304ddd5e26e2e6df65804fa4d6bae6b499f024321e599176f02b8b6650739c3', 'v2', '2026-04-21T13:50:40+00:00', '["mod_member_custom.php:91|$mask = getDolGlobalString(''MEMBER_CUSTOM_MASK'');", "mod_member_custom.php:139|$mask = getDolGlobalString(''MEMBER_CUSTOM_MASK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_DISABLE_STATE', 'bool', NULL, 'adherents', 'Disables the state/province field for member records.', 'Checked in adherents/card.php:1249 and :1506 to conditionally show state-related UI. Also used in webportal/class/webportalmember.class.php:126 to control field visibility with enabled=''!getDolGlobalString("MEMBER_DISABLE_STATE")''.', 'When enabled, the state/province field is hidden and not processed for member records including in the web portal.', '0 or unset = state field enabled; non-empty = state field disabled', 1, 0, NULL, 1, '86810b4ea4cf5642a48f1b74e5c9b899bcb480a57cb683b592100367212f0c1b', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/card.php:1249|check|if (!getDolGlobalString(''MEMBER_DISABLE_STATE'')) {", "webportal/class/webportalmember.class.php:126|read|''state_id'' => array(''type'' => ''integer'', ''label'' => ''State id'', ''enabled'' => ''!getDolGlobalString(\"MEMBER_DISABLE_STATE\")'', ''visible'' => -5, ''position'' => 90, ''showonheader'' => 1,)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_DONOTSEARCH_ANYWHERE', 'string', NULL, 'core', 'Controls whether member (adherent) quick-search matches only the start of ref/name fields (index-friendly) or anywhere within them.', 'Checked in core/class/html.form.class.php:9458 to decide the SQL LIKE prefix wildcard (''%'' vs '''') used when searching adherent ref/firstname/lastname; comment notes ''Can use index if PRODUCT_DONOTSEARCH_ANYWHERE is on'' (copy-pasted comment referencing the analogous PRODUCT_ constant).', 'Enabling it removes the leading ''%'' wildcard so searches only match from the start of the field, which can use a DB index (faster) but no longer matches substrings occurring mid-string.', 'Boolean: unset/false (default) searches anywhere via leading ''%'' wildcard; true restricts to prefix match for better index use.', 1, 0, NULL, 1, 'ca31eee2bbe5d308207c439470a9c6d8e9f64bac8334dbaa6eba80eedc24cf09', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:9458|read|$prefix = !getDolGlobalString(''MEMBER_DONOTSEARCH_ANYWHERE'') ? ''%'' : ''''; // Can use index if PRODUCT_DONOTSEARCH_ANYWHERE is on"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_ENABLE_PUBLIC', 'bool', NULL, 'adherents', 'Enables the public membership subscription page and related public features for the Members module.', 'Written via adherents/admin/website.php:70-91 and checked in core/class/html.formmail.class.php:2139 and comm/mailing/card.php:337. The admin UI at adherents/admin/website.php reads and writes this constant. It controls access to public member-facing features.', 'Disabling this constant hides the public membership form and prevents public-facing member subscription flows from operating.', '0 (public page disabled) or 1 (public page enabled)', 0, 0, 'adherents/admin/website.php|adherents/admin/website.php|adherents/admin/website.php|adherents/admin/website.php|adherents/admin/website.php|adherents/admin/website.php', 1, '2bdd2db1b08fab94c94936a66f9e4f7d5114390fa633e7b7fda5896abdf137e4', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/website.php:70|write|dolibarr_set_const($db, ''MEMBER_ENABLE_PUBLIC'', 1, ''chaine'', 0, '''', $conf->entity);", "adherents/admin/website.php:72|write|dolibarr_set_const($db, ''MEMBER_ENABLE_PUBLIC'', 0, ''chaine'', 0, '''', $conf->entity);", "core/class/html.formmail.class.php:2139|check|if (getDolGlobalString(''MEMBER_ENABLE_PUBLIC'')) {", "comm/mailing/card.php:337|check|if (getDolGlobalString(''MEMBER_ENABLE_PUBLIC'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_EXT_URL_SUBSCRIPTION_INFO', 'string', NULL, 'public', 'Specifies an external URL linked as an information icon on the public member subscription and payment forms.', 'Checked and read at public/payment/newpayment.php:1987-1988 and public/members/new.php:1137-1139; when set, a link with an icon is rendered pointing to this URL with target=_blank.', 'When set, users on the member or payment form can follow this link for additional subscription information.', 'An external URL string; empty/unset means no info link is shown.', 1, 0, NULL, 1, '33ce95b03efaa5a337c79a5490c263b566d2a8122ace63522767a917b7e30200', 'v2', '2026-04-21T13:50:40+00:00', '["public/payment/newpayment.php:1987|check|if (getDolGlobalString(''MEMBER_EXT_URL_SUBSCRIPTION_INFO'')) {", "public/payment/newpayment.php:1988|read|print '' - <a href=\"'' . getDolGlobalString(''MEMBER_EXT_URL_SUBSCRIPTION_INFO'').''\" rel=\"external\" target=\"_blank\"", "public/members/new.php:1137|check|if (getDolGlobalString(''MEMBER_EXT_URL_SUBSCRIPTION_INFO'')) {", "public/members/new.php:1139|read|print ''<a href=\"'' . getDolGlobalString(''MEMBER_EXT_URL_SUBSCRIPTION_INFO'').''\" rel=\"external\" target=\"_blank\" rel=\"noopener noreferrer\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_HIDE_VOTE_ALLOWED', 'bool', NULL, 'adherents', 'Controls whether the ''vote allowed'' field is hidden on the public member registration form.', 'Written at adherents/admin/website.php:97 with inverted logic for retrocompatibility. Read at adherents/admin/website.php:240 and public/members/new.php:1338.', 'Setting this to 1 hides the vote-allowed field on the public member form. Note: logic is reversed for retrocompatibility: ''hide -> show''.', '0 (vote allowed field shown) or 1 (vote allowed field hidden) — logic inverted for retrocompatibility', 0, 0, 'adherents/admin/website.php|adherents/admin/website.php', 1, '81d36971be96c894fcaa58912cb52707adb87c8b9a4eb6e359fa978a02ef98af', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/website.php:97|write|$res = dolibarr_set_const($db, \"MEMBER_HIDE_VOTE_ALLOWED\", $showvoteallowed ? 0 : 1, ''chaine'', 0, '''', $conf->entity); // Logic is reversed for retrocompatibility: \"hide -> show\"", "adherents/admin/website.php:240|read|$hidevoteallowed = getDolGlobalInt(''MEMBER_HIDE_VOTE_ALLOWED'');", "public/members/new.php:1338|read|$hidevoteallowed = getDolGlobalString(\"MEMBER_HIDE_VOTE_ALLOWED\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_MIN_AMOUNT', 'string', NULL, 'public', 'Sets the minimum subscription amount accepted on the public member subscription form and online payment validation.', 'Set via admin UI at adherents/admin/website.php:88/277, documented in public/members/new.php:33 as ''Minimum amount'', and enforced in public/members/new.php:597 and public/payment/paymentok.php:637-638.', 'Raising the value increases the minimum amount enforced when a public visitor submits a new member subscription or online payment; payments below it are rejected per the check at public/payment/paymentok.php:638.', NULL, 0, 0, 'adherents/admin/website.php|adherents/admin/website.php', 1, '5e553028a1d8ad306255412c258d5b244610ceced72b0fbb948999c829f720b6', 'v2', '2026-07-24T06:41:12+00:00', '["*  MEMBER_MIN_AMOUNT                   Minimum amount", "if ($amount < max(getDolGlobalInt(\"MEMBER_MIN_AMOUNT\"), $minimumamount)) {", "if ($FinalPaymentAmt < getDolGlobalInt(''MEMBER_MIN_AMOUNT'') || $FinalPaymentAmt < $minimumamount) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_MOD_SIMPLE_LPAD', 'string', NULL, 'core', 'Sets the left-padding width (number of digits) used to zero-pad the auto-incremented member reference generated by the ''simple'' member numbering module.', 'Used in core/modules/member/mod_member_simple.php:148: $max = str_pad((string) $max, getDolGlobalInt(''MEMBER_MOD_SIMPLE_LPAD''), "0", STR_PAD_LEFT), applied to the next sequential integer ref computed from MAX(CAST(ref AS SIGNED)).', 'Setting it to a value larger than the number''s natural digit count left-pads the generated member reference with zeros to reach that total width; if 0/unset, str_pad performs no meaningful padding beyond the number''s own length.', 'Integer: target total string length for zero-padding.', 1, 0, NULL, 1, '79856496ba10b5d870e0a8c9f3f723b8be0f7f1d184a2e03a0a98808241cfc0c', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/member/mod_member_simple.php:148: $max = str_pad((string) $max, getDolGlobalInt(''MEMBER_MOD_SIMPLE_LPAD''), \"0\", STR_PAD_LEFT);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NEWFORM_ASK_TITLE', 'string', NULL, 'public', 'Adds a civility/title selection field to the public new-member subscription form.', 'Checked in public/members/new.php:870: if set, the form prints a UserTitle row with $formcompany->select_civility(...); otherwise the title field is omitted.', 'Enabling it adds a mandatory-looking civility (''title'') selector to the public subscription form; not set means no title field is shown.', 'Boolean-like (getDolGlobalString): non-empty shows the title/civility field; empty/unset (default) hides it.', 1, 0, NULL, 1, '07b9146f241234832c0ac9f1aa0e931315b9a6d64044ab447ae53a5f4919477d', 'v2', '2026-07-24T07:05:23+00:00', '["public/members/new.php:870: if (getDolGlobalString(''MEMBER_NEWFORM_ASK_TITLE'')) {", "public/members/new.php:871-872: print $langs->trans(''UserTitle'')...select_civility(GETPOST(''civility_id''), ''civility_id'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NEWFORM_DOLIBARRTURNOVER', 'string', NULL, 'public', 'Shows a turnover field on the public member registration form, specific to the Dolibarr foundation.', 'Checked at public/members/new.php:379, :1013, :1156, :1172 and public/payment/newpayment.php:1821 to show or hide the turnover field and adjust amount defaults. The comment at new.php:36 describes it as ''Show field turnover (specific for dolibarr foundation)''.', 'When enabled, the turnover field is shown on the member form and default amounts from MEMBER_NEWFORM_AMOUNT are suppressed.', 'Show field turnover (specific for dolibarr foundation)', 1, 0, NULL, 1, 'd296cc96e395ab35cb9d0673d1cd266c9a2cd7ce2020f77b360cc2beed74ccde', 'v2', '2026-04-21T13:50:40+00:00', '["public/members/new.php:36  *  MEMBER_NEWFORM_DOLIBARRTURNOVER     Show field turnover (specific for dolibarr foundation)", "public/members/new.php:1014  // Do not set a default amount MEMBER_NEWFORM_AMOUNT if you use MEMBER_NEWFORM_DOLIBARRTURNOVER", "public/payment/newpayment.php:1839  // Do not set a default amount MEMBER_NEWFORM_AMOUNT if you use MEMBER_NEWFORM_DOLIBARRTURNOVER", "public/members/new.php:379|check|if (getDolGlobalString(''MEMBER_NEWFORM_DOLIBARRTURNOVER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NEWFORM_FORCECOUNTRYCODE', 'string', NULL, 'public', 'Forces a specific country to be pre-selected/used on public member and event registration forms.', 'Documented in public/members/new.php:39 as ''Force country'', read via getDolGlobalString(''MEMBER_NEWFORM_FORCECOUNTRYCODE'') in public/members/new.php:312/915-916 and also used in public/project/suggestbooth.php:682-683 and public/eventorganization/attendee_new.php:900.', 'When set, the country field on the public new-member/attendee/booth/conference forms is forced to the configured country code instead of being left to the visitor''s choice.', NULL, 0, 0, NULL, 1, '2e4bf7a464d290348c7bf3695dbf7b6bcffdc177006bbd175a52dcca57d62750', 'v2', '2026-07-24T06:41:12+00:00', '["*  MEMBER_NEWFORM_FORCECOUNTRYCODE     Force country", "if (!$country_id && getDolGlobalString(''MEMBER_NEWFORM_FORCECOUNTRYCODE'')) {", "$country_id = (int) getCountry(getDolGlobalString(''MEMBER_NEWFORM_FORCECOUNTRYCODE''), ''3'', $db, $langs);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NEWFORM_FORCEMORPHY', 'string', NULL, 'public', 'Forces a specific legal nature (physical/moral) on the public member registration form.', 'Documented at public/members/new.php:39 as ''Force nature of member (mor/phy)''. Written via adherents/admin/website.php:106-108 and read at public/members/new.php:429 and :851.', 'When set, the registration form pre-fills and locks the member''s nature to the specified value, preventing user selection.', 'Force nature of member (mor/phy) — ''phy'' for physical person, ''mor'' for moral/legal entity; empty/unset allows user selection', 0, 0, 'adherents/admin/website.php|adherents/admin/website.php|adherents/admin/website.php', 1, '77c470b8157792798bb4855da5289faed7830085b283fabe4e11eac65c41e622', 'v2', '2026-04-21T11:16:15+00:00', '["public/members/new.php:39  *  MEMBER_NEWFORM_FORCEMORPHY          Force nature of member (mor/phy)", "adherents/admin/website.php:268|read|$forcenature = getDolGlobalString(''MEMBER_NEWFORM_FORCEMORPHY''); // ''phy'' or ''mor''", "public/members/new.php:429|read|$adh->morphy      = getDolGlobalString(\"MEMBER_NEWFORM_FORCEMORPHY\", GETPOST(''morphy''));", "public/members/new.php:755|check|if (!getDolGlobalString(''MEMBER_NEWFORM_FORCEMORPHY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NEWFORM_FORCETYPE', 'string', NULL, 'public', 'Forces a specific member type on the public member registration form instead of letting the user choose.', 'Documented at public/members/new.php:38 as ''Force type of member''. Written via adherents/admin/website.php:101-103 and read at public/members/new.php:427, :972, :1206 to set the member type ID.', 'When set, the public registration form pre-selects and locks the member type to the given ID, overriding user selection.', 'Force type of member — integer ID of the member type to force; empty/unset allows user selection', 0, 0, 'adherents/admin/website.php|adherents/admin/website.php|adherents/admin/website.php', 1, 'c7e00d169a7e7e8d23364a6e34673869098dd1718e61b768f3e05bda9d4dce52', 'v2', '2026-04-21T11:16:15+00:00', '["public/members/new.php:38  *  MEMBER_NEWFORM_FORCETYPE            Force type of member", "adherents/admin/website.php:103|write|$res = dolibarr_set_const($db, \"MEMBER_NEWFORM_FORCETYPE\", $forcetype, ''chaine'', 0, '''', $conf->entity);", "public/members/new.php:972|read|$typeid = getDolGlobalInt(''MEMBER_NEWFORM_FORCETYPE'', GETPOSTINT(''typeid''));", "public/members/new.php:685|check|if (getDolGlobalString(''MEMBER_SKIP_TABLE'') || getDolGlobalString(''MEMBER_NEWFORM_FORCETYPE'') || in_array($action, array(''create'', ''subscription''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NEWFORM_PAYONLINE', 'string', NULL, 'public', 'Specifies which online payment method to suggest on the public member registration form after subscription.', 'Documented at public/members/new.php:35 as ''Suggest payment with all, paypal, paybox, stripe, ...''. Written via adherents/admin/website.php:99 and checked in public/members/new.php:582, :600, :1135.', 'When set, the registration form redirects to the online payment flow for the specified payment provider after subscription. ''-1'' disables the online payment suggestion.', 'Suggest payment with ''all'', ''paypal'', ''paybox'', ''stripe'', ... — ''-1'' disables; empty/unset means no payment suggestion', 0, 0, 'adherents/admin/website.php|adherents/admin/website.php', 1, 'f730b233570793f5aa626ea8c261df4e380593e6c956718e83a074f8f0efa943', 'v2', '2026-04-21T11:16:15+00:00', '["public/members/new.php:35  *  MEMBER_NEWFORM_PAYONLINE            Suggest payment with ''all'', ''paypal'', ''paybox'', ''stripe'', ...", "public/members/new.php:1135|check|if (getDolGlobalString(''MEMBER_NEWFORM_PAYONLINE'')) {\t// Can be ''all'', ''paypal'', ''paybox'', ''stripe''...", "public/members/new.php:600|check|if (getDolGlobalString(''MEMBER_NEWFORM_PAYONLINE'') != ''-1'' && getDolGlobalString(''MEMBER_NEWFORM_PAYONLINE'') != ''all'') {", "adherents/admin/website.php:99|write|$res = dolibarr_set_const($db, \"MEMBER_NEWFORM_PAYONLINE\", $payonline, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NEWFORM_TEXT', 'string', NULL, 'public', 'Custom introductory text shown on the public new-member subscription form, replacing the default ''NewSubscriptionDesc'' text.', 'Checked and printed in public/members/new.php:669-670: if set, $langs->trans(getDolGlobalString(''MEMBER_NEWFORM_TEXT'')) is printed instead of the default translated NewSubscriptionDesc message.', 'Setting this replaces the default explanatory paragraph on the public subscription form with a custom (translation-key-resolved) text.', 'String, treated as a translation key/text passed through $langs->trans(); empty/unset falls back to the default ''NewSubscriptionDesc'' message.', 1, 0, NULL, 1, '47158004008c5539e843ad4619fff79988f09c662a9c593b6332f39aa7e4a468', 'v2', '2026-07-24T07:05:23+00:00', '["public/members/new.php:669: if (getDolGlobalString(''MEMBER_NEWFORM_TEXT'')) {", "public/members/new.php:670: print $langs->trans(getDolGlobalString(''MEMBER_NEWFORM_TEXT'')).\"<br>\\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NO_DEFAULT_LABEL', 'string', NULL, 'adherents', 'Suppresses the default auto-generated ''Subscription <year>'' label text pre-filled in the Note field of the member subscription form.', 'Used in adherents/subscription.php:1060: the note/label input is normally pre-filled with $langs->trans(''Subscription'').'' ''.year via dol_print_date, but this print is skipped when the constant is truthy, leaving the field empty.', 'Enabling it leaves the subscription note/label field blank by default instead of pre-filled with ''Subscription <year>'', requiring the user to type a label manually if desired.', 'Boolean-like: truthy suppresses the default subscription label text.', 0, 0, NULL, 1, '2e32610c6388fbf5defd4b302f1ca96f607bc5d6b08b491ea9480e782ef9bfe0', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/subscription.php:1060|check|if (!getDolGlobalString(''MEMBER_NO_DEFAULT_LABEL'')) {", "adherents/subscription.php:1061|print $langs->trans(\"Subscription\").'' ''.dol_print_date(($datefrom ? $datefrom : time()), \"%Y\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_NO_SYNC_LINKED_THIRDPARTY', 'string', NULL, 'adherents', 'Disables synchronization of member data changes to the linked third-party (Societe) record when a member is updated.', 'In adherents/card.php:421, $nosyncthirdparty = getDolGlobalInt(''MEMBER_NO_SYNC_LINKED_THIRDPARTY'') is passed as the corresponding argument to $object->update($user, 0, $nosyncuser, $nosyncuserpass, $nosyncthirdparty).', 'Enabling it (non-zero) stops member field updates from propagating to the linked thirdparty/company record on member update; default 0 keeps the sync enabled.', 'Integer/boolean: non-zero disables thirdparty sync on member update, 0 (default) keeps it enabled.', 1, 0, NULL, 1, 'ad2630cdfb0d11cafdd04f29e2bbdb60286b763de0f830a270362b26af665291', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/card.php:421|read|$nosyncthirdparty = getDolGlobalInt(''MEMBER_NO_SYNC_LINKED_THIRDPARTY'');", "adherents/card.php: $result = $object->update($user, 0, $nosyncuser, $nosyncuserpass, $nosyncthirdparty);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_PHOTO_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'adherents', 'Allows a member''s uploaded photo to be indexed in the database file index so it can be downloaded/served externally.', 'In adherents/card.php:458, after a member photo upload succeeds, if this boolean is set the code calls deleteFilesIntoDatabaseIndex() then addFileIntoDatabaseIndex() to register the uploaded photo file in the ECM/file database index.', 'Enabling it causes uploaded member photos to be indexed into the file database (making them discoverable/servable via the document index), whereas by default (unset) the photo is saved to disk but not added to that index.', 'Boolean/truthy: when set, the uploaded photo is indexed into the database file index after upload.', 1, 0, NULL, 1, 'fe7f205950dd71eb7791b3daa960c401e47d5eadb158b73f1d59fca4c3aa11bd', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/card.php:458|check|if (getDolGlobalString(''MEMBER_PHOTO_ALLOW_EXTERNAL_DOWNLOAD'')) {", "adherents/card.php: deleteFilesIntoDatabaseIndex(dirname($newfile), '''', '''', $object); ... addFileIntoDatabaseIndex(dirname($newfile), basename($newfile), '''', ''uploaded'', 1, $object);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_PUBLIC_CSS', 'string', NULL, 'public', 'Specifies a custom CSS URL injected into the public member card and list pages.', 'Checked and read at public/members/public_card.php:92-93 and public/members/public_list.php:135-136; when set, a link element pointing to this URL is added to the page head. No admin UI write found.', 'When set, the specified CSS file is loaded on public member pages, allowing visual customization of those pages.', 'A URL string pointing to a CSS file; empty/unset means no extra stylesheet is loaded.', 1, 0, NULL, 1, 'b15251467e63e122c9c172cc38287a9c3b97476887ef3cd0ed364daf2243fced', 'v2', '2026-04-21T13:50:40+00:00', '["public/members/public_card.php:92|check|if (getDolGlobalString(''MEMBER_PUBLIC_CSS'')) {", "public/members/public_card.php:93|read|$morehead = ''<link rel=\"stylesheet\" type=\"text/css\" href=\"'' . getDolGlobalString(''MEMBER_PUBLIC_CSS'').''\">'';", "public/members/public_list.php:135|check|if (getDolGlobalString(''MEMBER_PUBLIC_CSS'')) {", "public/members/public_list.php:136|read|$morehead = ''<link rel=\"stylesheet\" type=\"text/css\" href=\"'' . getDolGlobalString(''MEMBER_PUBLIC_CSS'').''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_PUBLIC_ENABLED', 'bool', NULL, 'public', 'Enables or disables the public-facing member pages (public card, public list, and public subscription form).', 'Set via the admin UI at adherents/admin/member.php:181 and rendered as a yes/no selector at :613. The three public pages (public_card.php:87, public_list.php:128, new.php:954) gate their output on this constant.', 'Disabling this constant blocks public access to member directory and subscription pages. Enabling makes them accessible without login.', '0 = public member pages disabled; 1 = public member pages enabled', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, 'a172b579477c10467a7993184e05690e3528f6b786d9ba8f185e2c1eaec6964a', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/member.php:613|read|print $form->selectyesno(''MEMBER_PUBLIC_ENABLED'', getDolGlobalInt(''MEMBER_PUBLIC_ENABLED''), 1, false, 0, 1);", "public/members/public_card.php:87|check|if (!getDolGlobalString(''MEMBER_PUBLIC_ENABLED'')) {", "public/members/public_list.php:128|check|if (!getDolGlobalString(''MEMBER_PUBLIC_ENABLED'')) {", "public/payment/newpayment.php:954 (via new.php)|check|if (getDolGlobalString(''MEMBER_PUBLIC_ENABLED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_PUBLIC_INTERFACE', 'string', NULL, 'public', 'Alternative alt-text/header label passed to the public online header shown on the public member subscription page.', 'Used in public/members/new.php:186 as the $alttext argument of htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''MEMBER_PUBLIC_INTERFACE''), ''MEMBER_IMAGE_PUBLIC_REGISTRATION''), whose PHP-doc defines that parameter as ''Text to show in header''.', 'Changing the value changes the text displayed in the header of the public member registration page.', 'Free-form string used as header alt text; empty/unset means no custom text is shown.', 1, 0, NULL, 1, 'f6af56982c63d9d50097b58dd1f08780e491a0e2e47fc9c725bd274f65c60599', 'v2', '2026-07-24T07:05:23+00:00', '["public/members/new.php:186: htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''MEMBER_PUBLIC_INTERFACE''), ''MEMBER_IMAGE_PUBLIC_REGISTRATION'');", "core/lib/company.lib.php:2891: * @param string $alttext Text to show in header"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_REMINDER_EMAIL', 'string', NULL, 'adherents', 'Master on/off switch enabling the automatic reminder-email feature for expiring member subscriptions.', 'Has an admin UI entry in adherents/admin/member_emails.php (type ''yesno'', label/help via lang keys MEMBER_REMINDER_EMAIL/MEMBER_REMINDER_EMAILHelp). The cron job in adherents/class/adherent.class.php:3252 aborts immediately (output ''EventRemindersByEmailNotEnabled'') if this is not set, and member_emails.php:202 hides the ADHERENT_EMAIL_TEMPLATE_REMIND_EXPIRATION template row unless it is set.', 'Enabling it activates the scheduled job that sends expiration-reminder emails to members and reveals the related email-template setting in the admin UI; disabled (default) means the reminder cron does nothing.', 'Boolean (yesno admin field): 1 enables the reminder-email cron feature, 0/unset (default) disables it.', 0, 0, 'adherents/admin/member_emails.php', 1, '39a7d47bb69c9ea3ff8c4f5bed7522e3934da1e4e707c20eda4bdedff49933e4', 'v2', '2026-07-24T07:05:23+00:00', '["adherents/admin/member_emails.php:68|''MEMBER_REMINDER_EMAIL'' => array(''type'' => ''yesno'', ...)", "adherents/class/adherent.class.php:3252|check|if (!getDolGlobalString(''MEMBER_REMINDER_EMAIL'')) { ... $this->output = $langs->trans(''EventRemindersByEmailNotEnabled'', ...); return 0; }", "adherents/admin/member_emails.php:202|check|if ($const == ''ADHERENT_EMAIL_TEMPLATE_REMIND_EXPIRATION'' && !getDolGlobalString(''MEMBER_REMINDER_EMAIL'')) { continue; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_SEARCH_MEMBER_PUBLIC_FORM_CREATE', 'string', NULL, 'adherents', 'Controls whether the public member creation form searches for/reuses an existing member account instead of always creating a new one.', 'Set via admin UI at adherents/admin/website.php:106/316 (yes/no select with reversed hide/show logic for retrocompat) and checked in public/members/new.php:231.', 'When enabled, the public form at public/members/new.php checks for an existing account on submission; comment at public/members/new.php:236 notes that when this option was off, users get the same error on trying to reuse an account.', 'yes -> stored as 1, no -> stored as 0 (see GETPOST(...) == ''yes'' ? 1 : 0)', 0, 0, 'adherents/admin/website.php|adherents/admin/website.php', 1, 'ce8d0ef2992175bc2568d9191a0dd7184229b4331628a3483c733d76c248f434', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"MEMBER_SEARCH_MEMBER_PUBLIC_FORM_CREATE\", GETPOST(''MEMBER_SEARCH_MEMBER_PUBLIC_FORM_CREATE'') == ''yes'' ? 1 : 0, ''chaine'', 0, '''', $conf->entity);", "// If we try to new account and option MEMBER_SEARCH_MEMBER_PUBLIC_FORM_CREATE was off, we also get the same error."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_SKIP_TABLE', 'string', NULL, 'adherents', 'Controls whether the membership type table is skipped (hidden) on the public member registration form.', 'Written at adherents/admin/website.php:95 with inverted logic for retrocompatibility (''skip -> show''). Read at adherents/admin/website.php:231 and checked at public/members/new.php:685.', 'Setting this to 1 skips (hides) the membership type selection table on the public form. Note: logic is reversed for retrocompatibility: ''skip -> show''.', '0 (table shown) or 1 (table skipped/hidden) — logic inverted for retrocompatibility', 0, 0, 'adherents/admin/website.php|adherents/admin/website.php', 1, '497182b205cbf350cce7feda9766b021c99fe8a7ca512722a5b2192282ec7e22', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/admin/website.php:95|write|$res = dolibarr_set_const($db, \"MEMBER_SKIP_TABLE\", $showtable ? 0 : 1, ''chaine'', 0, '''', $conf->entity); // Logic is reversed for retrocompatibility: \"skip -> show\"", "public/members/new.php:685|check|if (getDolGlobalString(''MEMBER_SKIP_TABLE'') || getDolGlobalString(''MEMBER_NEWFORM_FORCETYPE'') || in_array($action, array(''create'', ''subscription''))) {", "adherents/admin/website.php:231|read|$skiptable = getDolGlobalInt(''MEMBER_SKIP_TABLE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_SUBSCRIPTION_START_AFTER', 'string', NULL, 'adherents', 'Defines a duration offset to add to the current date when computing the start date of a new member subscription.', 'The value is parsed as a duration string (numeric prefix + unit suffix, e.g., ''1m'', ''3m'', ''1Y'') using substr at adherents/subscription.php:988 and public/payment/paymentok.php:676, passed to dol_time_plus_duree. Also used in stats at adherents/stats/index.php:66. Configurable via adherents/admin/member.php:184.', 'Setting this constant shifts the subscription start date forward by the specified duration from today instead of using the current date directly.', 'A duration string with a numeric part and a unit character (e.g., ''1m'' = 1 month, ''3m'' = 3 months, ''1Y'' = 1 year); empty/unset = subscription starts on current date.', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, '7d5eb97361fd88d49638b00f517eb031bce99e9935e4c8032a29426038faa155', 'v2', '2026-04-21T11:16:15+00:00', '["public/payment/paymentok.php:676|read|$datesubscription = dol_time_plus_duree($now, (int) substr(getDolGlobalString(''MEMBER_SUBSCRIPTION_START_AFTER''), 0, -1), substr(getDolGlobalString(''MEMBER_SUBSCRIPTION_START_AFTER'')", "adherents/subscription.php:988|read|$datefrom = dol_time_plus_duree($now, (int) substr(getDolGlobalString(''MEMBER_SUBSCRIPTION_START_AFTER''), 0, -1), substr(getDolGlobalString(''MEMBER_SUBSCRIPTION_START_AFTER''), -1))", "adherents/subscription.php:987|check|if (getDolGlobalString(''MEMBER_SUBSCRIPTION_START_AFTER'')) {", "adherents/admin/member.php:184|write|$res9 = dolibarr_set_const($db, ''MEMBER_SUBSCRIPTION_START_AFTER'', GETPOST(''MEMBER_SUBSCRIPTION_START_AFTER'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_SUBSCRIPTION_START_FIRST_DAY_OF', 'string', NULL, 'adherents', 'Snaps the subscription start date to the first day of the specified period (month, quarter, or year).', 'After the start date is computed, adherents/subscription.php:993-998 and public/payment/paymentok.php:679-684 check this constant and snap the date to the first day of the month (''m''), first day of the quarter (''3m''), or first day of the year (''Y''). Configurable via adherents/admin/member.php:183.', 'Setting this constant causes subscription start dates to be rounded down to the first day of the chosen period, which affects billing alignment.', '''m'' = first day of current month; ''3m'' = first day of current quarter; ''Y'' = first day of current year; empty/0 = no snapping.', 0, 0, 'adherents/admin/member.php|adherents/admin/member.php', 1, '0e5952f4ef3455423ffe0d15789a006a6d48b70b5b12ce02e16dbad703909fb1', 'v2', '2026-04-21T11:16:15+00:00', '["adherents/subscription.php:993|check|if (getDolGlobalString(''MEMBER_SUBSCRIPTION_START_FIRST_DAY_OF'') === \"m\") {", "adherents/subscription.php:995|read|} elseif (getDolGlobalString(''MEMBER_SUBSCRIPTION_START_FIRST_DAY_OF'') === \"3m\") {", "adherents/subscription.php:998|read|} elseif (getDolGlobalString(''MEMBER_SUBSCRIPTION_START_FIRST_DAY_OF'') === \"Y\") {", "adherents/admin/member.php:183|write|$res8 = dolibarr_set_const($db, ''MEMBER_SUBSCRIPTION_START_FIRST_DAY_OF'', GETPOST(''MEMBER_SUBSCRIPTION_START_FIRST_DAY_OF'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_SUBSCRIPTION_SUGGEST_END_OF_MONTH', 'string', NULL, 'adherents', 'Suggests the end of the current month as the subscription end date when creating/listing member subscriptions.', 'Checked with getDolGlobalInt(''MEMBER_SUBSCRIPTION_SUGGEST_END_OF_MONTH'') in adherents/subscription.php:1040 and adherents/list.php:375, referenced by comment at adherents/list.php:369 (''Honour MEMBER_SUBSCRIPTION_SUGGEST_END_OF_MONTH and'').', 'When enabled, the suggested subscription end date is adjusted to the end of the month rather than a plain date offset.', NULL, 0, 0, NULL, 1, '2c18e485e57c67f1a77f7a5e707b104f38d9faec22d23c98a52fa363841ba6c1', 'v2', '2026-07-24T06:41:12+00:00', '["// Honour MEMBER_SUBSCRIPTION_SUGGEST_END_OF_MONTH and", "if (getDolGlobalInt(''MEMBER_SUBSCRIPTION_SUGGEST_END_OF_MONTH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_SUBSCRIPTION_SUGGEST_END_OF_YEAR', 'string', NULL, 'adherents', 'Suggests the end of the current year as the subscription end date when creating/listing member subscriptions.', 'Checked with getDolGlobalInt(''MEMBER_SUBSCRIPTION_SUGGEST_END_OF_YEAR'') in adherents/subscription.php:1042 and adherents/list.php:377, as an elseif alternative to MEMBER_SUBSCRIPTION_SUGGEST_END_OF_MONTH; referenced by comment at adherents/list.php:370.', 'When enabled (and the end-of-month option is not), the suggested subscription end date is adjusted to the end of the year.', NULL, 0, 0, NULL, 1, '7b5b5948042efaaab114c2d9272b18d346e077673f7dce60f12bf1b15bf97c03', 'v2', '2026-07-24T06:41:12+00:00', '["// MEMBER_SUBSCRIPTION_SUGGEST_END_OF_YEAR the same way as the", "} elseif (getDolGlobalInt(''MEMBER_SUBSCRIPTION_SUGGEST_END_OF_YEAR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMBER_URL_REDIRECT_SUBSCRIPTION', 'string', NULL, 'public', 'Specifies a URL to redirect to after a member registration or company subscription form is submitted.', 'Read at public/company/new.php:237-238 and public/members/new.php:575-576 as the redirect target after form submission. The comment in new.php:37 describes it as a ''hidden option, by default we just show a message on same page or redirect to the payment page''.', 'If set, submitting the registration form redirects the user to this URL instead of showing an inline message or the payment page.', 'Url to redirect once registration form has been submitted (hidden option, by default we just show a message on same page or redirect to the payment page)', 1, 0, NULL, 1, '4834a8d4297a353e20d07ab830c2ce23e48dc948d0814bad1701b4389b9fc762', 'v2', '2026-04-21T13:50:40+00:00', '["public/members/new.php:37  *  MEMBER_URL_REDIRECT_SUBSCRIPTION    Url to redirect once registration form has been submitted (hidden option, by default we just show a message on same page or redirect to the payment page)", "public/company/new.php:237|read|} elseif (getDolGlobalString(''MEMBER_URL_REDIRECT_SUBSCRIPTION'')) {", "public/members/new.php:575|read|} elseif (getDolGlobalString(''MEMBER_URL_REDIRECT_SUBSCRIPTION'')) {", "public/company/new.php:262  // If MEMBER_URL_REDIRECT_SUBSCRIPTION is set to an url, we never go here because a redirect was done to this url."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MEMCACHED_SERVER', 'string', NULL, 'core', 'Specifies the Memcached server address (host:port) used for distributed caching.', 'Read in core/lib/memory.lib.php (lines 88, 118, 195, 221) via explode('':'', ...) to connect to the Memcached server; checked in core/class/translate.class.php and core/lib/functions.lib.php when the memcached module is enabled. Configurable via admin/system/perf.php.', 'Setting this enables Memcached-backed caching for translations and other shared data; leaving it unset disables Memcached even if the module is enabled.', '''host:port'' string (e.g. ''127.0.0.1:11211''); empty/unset = Memcached not used.', 0, 0, 'admin/system/perf.php', 1, 'd2b9d53fcd3c6db83713ee28c15e580ee3db2abd0f4ea5d80eb5db7fcd59801b', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/memory.lib.php:88|read|$tmparray = explode('':'', getDolGlobalString(''MEMCACHED_SERVER''));", "core/class/translate.class.php:335|check|if (isModEnabled(''memcached'') && getDolGlobalString(''MEMCACHED_SERVER'')) {", "core/lib/functions.lib.php:13227|check|if (getDolGlobalString(''MEMCACHED_SERVER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MENU_HIDE_EMAIL_TEMPLATES', 'bool', NULL, 'core', 'Hides the ''Email templates'' entry from the Tools left menu for internal users.', 'Checked in core/menus/standard/eldy.lib.php:2624 (comment ''limit to internal users''); when not set and the current user has no socid (i.e. is internal, not an external/customer user), the EMailTemplates menu entry linking to admin/mails_templates.php is added.', 'Enabling it removes the Email Templates shortcut from the Tools menu for internal users; external users never see it regardless.', 'Truthy hides the Email Templates menu entry; empty/0 shows it for internal users (default).', 1, 0, NULL, 1, '1bb9d7812c84c45a01086202f1195c7768d6f970b8d36d5ba37436c9c67b8633', 'v2', '2026-07-24T07:05:23+00:00', '["core/menus/standard/eldy.lib.php:2624: if (!getDolGlobalInt(''MENU_HIDE_EMAIL_TEMPLATES'') && empty($user->socid)) { // limit to internal users"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MIGRATION_FLAG_INVOICE_MODELS_V20', 'string', NULL, 'core', 'Flags that the invoice template migration for version 20 has been completed, preventing the migration from running again.', 'Written twice in install/upgrade2.php (lines 5409 and 5456) after completing the invoice model upgrade, and read at line 5398 to check whether to skip the migration. The write comment states: ''To flag the upgrade of invoice template has been set''.', 'If this flag is absent the migration script will re-run the invoice template upgrade. Once set it acts as an idempotency guard.', '0 or unset = migration not yet done; 1 = migration completed', 1, 0, NULL, 1, '69176f99d9dea3aebdeb791501d26e27a889049f7d2d24150d977f8ccdc42925', 'v2', '2026-04-21T11:16:15+00:00', '["dolibarr_set_const($db, ''MIGRATION_FLAG_INVOICE_MODELS_V20'', 1, ''chaine'', 0, ''To flag the upgrade of invoice template has been set'', 0);", "$lock = getDolGlobalInt(''MIGRATION_FLAG_INVOICE_MODELS_V20'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MIN_DELAY_EXPENSEREPORTS_TO_PAY', 'string', NULL, 'core', 'Number of days used to trigger the ''approved expense report awaiting payment'' warning/alert; effectively unused in the admin UI (a similarly named but differently-cased constant is present there, commented out).', 'Read in core/class/conf.class.php:1292 and :1296 as `getDolGlobalInt(''MIN_DELAY_EXPENSEREPORTS_TO_PAY'') * 86400`, stored into $this->warning_delays[''expense_report_payment''] and $this->expensereport->payment->warning_delay. A comment at expensereport/class/expensereport.class.php:2663 references it by this exact name: ''No delay configured (MAIN_DELAY_EXPENSEREPORTS / MIN_DELAY_EXPENSEREPORTS_TO_PAY not set), so nothing is late.'' admin/delais.php only has a commented-out block for ''MAIN_DELAY_EXPENSEREPORTS_TO_PAY'' (different name, no MIN_ prefix, wrapped in ''/* TODO Enable this ... */''), so this constant has no admin UI exposure under its actual name.', 'Changing it raises/lowers the day-count tolerance before an approved-but-unpaid expense report is flagged as late; since there is no admin field for its exact name, it can only be set manually (e.g. via conf.php or direct database edit of llx_const).', 'Integer number of days; multiplied by 86400 to get a warning delay in seconds.', 1, 0, NULL, 1, '0c066c69f6eab18e05370ecbd3fbffec3ca6a33e36be531c994fe6b6d3a94ade', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/conf.class.php:1292: $this->warning_delays[''expense_report_payment''] = getDolGlobalInt(''MIN_DELAY_EXPENSEREPORTS_TO_PAY'') * 86400;", "expensereport/class/expensereport.class.php:2663: // No delay configured (MAIN_DELAY_EXPENSEREPORTS / MIN_DELAY_EXPENSEREPORTS_TO_PAY not set), so nothing is late.", "admin/delais.php: /* TODO Enable this array( ''code'' => ''MAIN_DELAY_EXPENSEREPORTS_TO_PAY'', ''img'' => ''trip'' ) */"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MIN_YEAR_SELECT_DATE', 'string', NULL, 'core', 'Sets the earliest year offered in the jQuery datepicker''s year range for date fields.', 'Read in Form::select_date() in core/class/html.form.class.php:8455, used to build the datepicker() ''yearRange'' option; defaults to current year minus 100.', 'Lowering it extends the selectable year range backward in the JS datepicker widget; raising it restricts how far back a user can pick a year.', 'Integer year; default is idate(''Y'') - 100 (current year minus 100).', 1, 0, NULL, 1, '54a1854456717db96e12f7cc06e137a33a710fa1b901ef1aad6aa93baa27220c', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:8455|read|$minYear = getDolGlobalInt(''MIN_YEAR_SELECT_DATE'', (idate(''Y'') - 100));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODEL_FAC_REC_AUTHOR', 'string', NULL, 'compta', 'When creating a real invoice from a recurring invoice template, makes the new invoice''s author the original author of the recurring template instead of the current user performing the generation.', 'Checked in Facture::create() (compta/facture/class/facture.class.php:565), with an explicit inline comment at line 566 explaining the intent, overriding $origin_user_author_id with $_facrec->user_creation_id when set.', 'Enabling it changes invoice authorship attribution on auto/manually generated invoices from templates to the recurring template''s original creator rather than whoever triggers the generation (e.g. a cron/batch user).', 'Boolean-like: enabled = use recurring invoice template''s original author as the new invoice''s author; unset/0 = use the current user generating the invoice (default).', 0, 0, NULL, 1, '41e78b0657f551300a326c982e84a15c4e029c8d03a9c338358290093a912a8b', 'v2', '2026-07-24T07:05:23+00:00', '["compta/facture/class/facture.class.php:565: if (getDolGlobalString(''MODEL_FAC_REC_AUTHOR'')) {", "compta/facture/class/facture.class.php:566: // If option MODEL_FAC_REC_AUTHOR is set, we want the same author than the author of recurring invoice instead of current user"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_ADD_DOCUMENT_ROOT', 'string', NULL, 'modulebuilder', 'Adds DOL_DOCUMENT_ROOT as an additional module search path in the Module Builder.', 'Checked in modulebuilder/index.php:147 alongside MAIN_FEATURES_LEVEL >= 2 to include DOL_DOCUMENT_ROOT as a readable path, and at line 226 to conditionally add it as a module directory. No admin UI.', 'When set, the Module Builder scans DOL_DOCUMENT_ROOT for modules in addition to the standard custom directories.', 'Truthy string (DOL_DOCUMENT_ROOT added) or empty/unset (not added unless MAIN_FEATURES_LEVEL >= 2).', 1, 0, NULL, 1, 'fd329a14a12fd9bc4253b1db9311b0d67d0fefe42b5ad9d0ca384196e2f7a5f2', 'v2', '2026-04-21T13:29:58+00:00', '["modulebuilder/index.php:147|check|if ($dirread != DOL_DOCUMENT_ROOT && (getDolGlobalInt(''MAIN_FEATURES_LEVEL'') >= 2 || getDolGlobalString(''MODULEBUILDER_ADD_DOCUMENT_ROOT''))) {", "modulebuilder/index.php:226|check|if (getDolGlobalString(''MODULEBUILDER_ADD_DOCUMENT_ROOT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_ASCIIDOCTOR', 'string', NULL, 'modulebuilder', 'Stores the path to the asciidoctor binary used to generate HTML documentation for modules.', 'Configured via modulebuilder/admin/setup.php:53 (written with dolibarr_set_const) and rendered as a text input at line 194. Used in core/class/utils.class.php:949 to build the asciidoctor command, and checked at line 856 to determine if documentation generation is available.', 'When set, module documentation can be generated as HTML using asciidoctor. When unset (and MODULEBUILDER_ASCIIDOCTORPDF is also unset), documentation generation is unavailable.', 'Absolute path string to the asciidoctor executable; empty/unset disables HTML doc generation.', 0, 0, 'modulebuilder/admin/setup.php|modulebuilder/admin/setup.php', 1, 'd176dfc337bc87f0260386fc203f2d1f048947e9f03bd361a7eebffea2f584e2', 'v2', '2026-04-21T13:29:58+00:00', '["modulebuilder/admin/setup.php:53|write|$res2 = dolibarr_set_const($db, ''MODULEBUILDER_ASCIIDOCTOR'', GETPOST(''MODULEBUILDER_ASCIIDOCTOR'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "core/class/utils.class.php:949|read|$command = getDolGlobalString(''MODULEBUILDER_ASCIIDOCTOR'') . '' ''.$destfile.'' -n -o ''.$dirofmoduledoc.''/''.$FILENAMEDOC;", "core/class/utils.class.php:856|check|if (!getDolGlobalString(''MODULEBUILDER_ASCIIDOCTOR'') && !getDolGlobalString(''MODULEBUILDER_ASCIIDOCTORPDF'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_ASCIIDOCTORPDF', 'string', NULL, 'modulebuilder', 'Stores the path to the asciidoctor-pdf binary used to generate PDF documentation for modules.', 'Configured via modulebuilder/admin/setup.php:54 (written with dolibarr_set_const) and rendered as a text input at line 202. Used in core/class/utils.class.php:964 to build the asciidoctor-pdf command, and checked at line 856 alongside MODULEBUILDER_ASCIIDOCTOR.', 'When set, module documentation can be generated as PDF using asciidoctor-pdf. When both this and MODULEBUILDER_ASCIIDOCTOR are unset, documentation generation is unavailable.', 'Absolute path string to the asciidoctor-pdf executable; empty/unset disables PDF doc generation.', 0, 0, 'modulebuilder/admin/setup.php|modulebuilder/admin/setup.php', 1, '89f3b53c30b687de1925a9f9e39f6dab5368dc06ada591c5479feca4581eec7f', 'v2', '2026-04-21T13:29:58+00:00', '["modulebuilder/admin/setup.php:54|write|$res3 = dolibarr_set_const($db, ''MODULEBUILDER_ASCIIDOCTORPDF'', GETPOST(''MODULEBUILDER_ASCIIDOCTORPDF'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "core/class/utils.class.php:964|read|$command = getDolGlobalString(''MODULEBUILDER_ASCIIDOCTORPDF'') . '' ''.$destfile.'' -n -o ''.$dirofmoduledoc.''/''.$FILENAMEDOCPDF;", "core/class/utils.class.php:856|check|if (!getDolGlobalString(''MODULEBUILDER_ASCIIDOCTOR'') && !getDolGlobalString(''MODULEBUILDER_ASCIIDOCTORPDF'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_DEFAULTPICTO', 'string', NULL, 'modulebuilder', 'Default FontAwesome picto code pre-filled in the ModuleBuilder''s ''new object'' form when no picto value is submitted.', 'Read in modulebuilder/index.php:3701: `getDolGlobalString(''MODULEBUILDER_DEFAULTPICTO'', ''fa-file'')`, used as the value attribute of the ''idpicto'' text input when GETPOSTISSET(''idpicto'') is false, on the developer-facing ModuleBuilder object creation form.', 'Only affects the pre-filled default value shown in the ModuleBuilder picto input field; falls back to ''fa-file'' if unset.', 'Free-text string, a FontAwesome picto code such as ''fa-file'', ''fa-globe'', or advanced syntax ''fa-fakey[_faprefix[_facolor[_fasize]]]''; default ''fa-file''.', 1, 0, NULL, 1, 'e1dea8ee02bf883c2039c430aae8c44cdc758f2e314a36b4510c0c01ee8e5014', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/index.php:3701|read|print ''<input type=\"text\" name=\"idpicto\" value=\"''.(GETPOSTISSET(''idpicto'') ? GETPOST(''idpicto'') : getDolGlobalString(''MODULEBUILDER_DEFAULTPICTO'', ''fa-file'')).''\" placeholder=\"''.dol"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_SPECIFIC_AUTHOR', 'string', NULL, 'modulebuilder', 'Sets a custom author/copyright name used by ModuleBuilder when generating boilerplate code and license headers.', 'Set via admin UI at modulebuilder/admin/setup.php:58/172 and read in modulebuilder/index.php:448-449, 1791-1792, and 1823-1824 to build copyright replacement text.', 'When set, ModuleBuilder-generated files use this value instead of the default copyright/developer placeholder text.', NULL, 0, 0, 'modulebuilder/admin/setup.php|modulebuilder/admin/setup.php', 1, 'f784fe6386b6c380a5819ee8176c9829272df73ffda49d0f0c09d6e69398435c', 'v2', '2026-07-24T06:41:12+00:00', '["$arrayreplacement[''---Replace with your own copyright and developer email---''] = dol_print_date($now, ''%Y'').\"\\t\\t\" . getDolGlobalString(''MODULEBUILDER_SPECIFIC_AUTHOR'');", "if (getDolGlobalString(''MODULEBUILDER_SPECIFIC_AUTHOR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_SPECIFIC_EDITOR_NAME', 'string', NULL, 'modulebuilder', 'Sets a default editor/publisher name pre-filled in ModuleBuilder''s module descriptor form.', 'Set via admin UI at modulebuilder/admin/setup.php:55/150 and used as a default value in modulebuilder/index.php:3715 for the ''editorname'' field.', 'When set, it becomes the default value pre-filled in the ModuleBuilder editor name input field unless overridden by GETPOST(''editorname'').', NULL, 0, 0, 'modulebuilder/admin/setup.php|modulebuilder/admin/setup.php', 1, '3acd236265308af7e23c29b55cd42be2f65049042b98a51a70ba81d739877b14', 'v2', '2026-07-24T06:41:12+00:00', '["$res4 = dolibarr_set_const($db, ''MODULEBUILDER_SPECIFIC_EDITOR_NAME'', GETPOST(''MODULEBUILDER_SPECIFIC_EDITOR_NAME'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "print ''<input type=\"text\" name=\"editorname\" value=\"''.(GETPOSTISSET(''editorname'') ? GETPOST(''editorname'') : getDolGlobalString(''MODULEBUILDER_SPECIFIC_EDITOR_NAME'', $mysoc->name)).''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_SPECIFIC_EDITOR_URL', 'string', NULL, 'modulebuilder', 'Sets a default editor/publisher URL pre-filled in ModuleBuilder''s module descriptor form.', 'Set via admin UI at modulebuilder/admin/setup.php:56/157 and used as a default value in modulebuilder/index.php:3721 for the ''editorurl'' field.', 'When set, it becomes the default value pre-filled in the ModuleBuilder editor URL input field unless overridden by GETPOST(''editorurl'').', NULL, 0, 0, 'modulebuilder/admin/setup.php|modulebuilder/admin/setup.php', 1, 'd2549f8e2653603f9e42fd6df569e53fadcdc399e0dd70f14a8571d5cc763013', 'v2', '2026-07-24T06:41:12+00:00', '["$res5 = dolibarr_set_const($db, ''MODULEBUILDER_SPECIFIC_EDITOR_URL'', GETPOST(''MODULEBUILDER_SPECIFIC_EDITOR_URL'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "print ''<input type=\"text\" name=\"editorurl\" value=\"''.(GETPOSTISSET(''editorurl'') ? GETPOST(''editorurl'') : getDolGlobalString(''MODULEBUILDER_SPECIFIC_EDITOR_URL'', $mysoc->url)).''\" pla"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_SPECIFIC_FAMILY', 'string', NULL, 'modulebuilder', 'Stores the default module family pre-selected when creating a new module in Module Builder.', 'Configured via modulebuilder/admin/setup.php:57 (written with dolibarr_set_const) and rendered as a text input at line 165. Used in modulebuilder/index.php:3476 as the selected value for the family dropdown, falling back to ''other''.', 'When set, the module family dropdown is pre-selected with this value when creating new modules.', 'String family key (e.g. ''hr'', ''other''); defaults to ''other'' if unset.', 0, 0, 'modulebuilder/admin/setup.php|modulebuilder/admin/setup.php', 1, '3a4f19309053bffa2d6aa05399e4c0d4321a1b8c9514636841a72fdf3339a5bd', 'v2', '2026-04-21T13:29:58+00:00', '["modulebuilder/admin/setup.php:57|write|$res6 = dolibarr_set_const($db, ''MODULEBUILDER_SPECIFIC_FAMILY'', GETPOST(''MODULEBUILDER_SPECIFIC_FAMILY'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "modulebuilder/admin/setup.php:165|read|print ''<input id=\"MODULEBUILDER_SPECIFIC_FAMILY\" type=\"text\" name=\"MODULEBUILDER_SPECIFIC_FAMILY\" value=\"''.getDolGlobalString(''MODULEBUILDER_SPECIFIC_FAMILY'').''\">'';", "modulebuilder/index.php:3476|read|print ''<option value=\"hr\"''.($key == getDolGlobalString(''MODULEBUILDER_SPECIFIC_FAMILY'', ''other'') ? '' selected=\"selected\"'' : '''')."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_SPECIFIC_README', 'string', NULL, 'modulebuilder', 'Stores the README content written to generated module README.md files.', 'Configured via modulebuilder/admin/setup.php:52 (written with dolibarr_set_const) and rendered as a textarea at line 187. Used in modulebuilder/index.php:431 to write the content directly to the module''s README.md.', 'When set, generated modules receive a README.md with this content. When unset, the default README behaviour applies.', 'Free-form string (README markdown content); empty/unset means no custom README is written.', 0, 0, 'modulebuilder/admin/setup.php|modulebuilder/admin/setup.php', 1, 'b514feb872adfeb15b57efb2fc6259a35cd04c11e8ff7c58ee95fa35c206323d', 'v2', '2026-04-21T13:29:58+00:00', '["modulebuilder/admin/setup.php:52|write|$res1 = dolibarr_set_const($db, ''MODULEBUILDER_SPECIFIC_README'', GETPOST(''MODULEBUILDER_SPECIFIC_README'', ''restricthtml''), ''chaine'', 0, '''', $conf->entity);", "modulebuilder/index.php:428|check|if (getDolGlobalString(''MODULEBUILDER_SPECIFIC_README'')) {", "modulebuilder/index.php:431|read|file_put_contents($destdir.''/README.md'', getDolGlobalString(\"MODULEBUILDER_SPECIFIC_README\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_SPECIFIC_VERSION', 'string', NULL, 'modulebuilder', 'Stores the default version string pre-filled when creating a new module in Module Builder.', 'Configured via modulebuilder/admin/setup.php:59 (written with dolibarr_set_const) and rendered as a text input at line 179. Used in modulebuilder/index.php:3454 as the default value for the version field, falling back to ''1.0''.', 'When set, new modules created in Module Builder are pre-populated with this version string.', 'Version string (e.g. ''1.0''); defaults to ''1.0'' if unset.', 0, 0, 'modulebuilder/admin/setup.php|modulebuilder/admin/setup.php', 1, 'a43cb1b5491d5b8d8dbb88a25003b0da326f00da485244712aa1830602551d37', 'v2', '2026-04-21T13:29:58+00:00', '["modulebuilder/admin/setup.php:59|write|$res8 = dolibarr_set_const($db, ''MODULEBUILDER_SPECIFIC_VERSION'', GETPOST(''MODULEBUILDER_SPECIFIC_VERSION'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "modulebuilder/admin/setup.php:179|read|print ''<input id=\"MODULEBUILDER_SPECIFIC_VERSION\" type=\"text\" name=\"MODULEBUILDER_SPECIFIC_VERSION\" value=\"''.getDolGlobalString(''MODULEBUILDER_SPECIFIC_VERSION'').''\">'';", "modulebuilder/index.php:3454|read|print ''<input type=\"text\" name=\"version\" class=\"width75\" value=\"''.(GETPOSTISSET(''version'') ? GETPOST(''version'') : getDolGlobalString(''MODULEBUILDER_SPECIFIC_VERSION'', ''1.0'')).''\""]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_SUPPORT_COMPATIBILITY_V16', 'string', NULL, 'modulebuilder', 'When enabled, makes the ModuleBuilder tool also copy a backported html.formsetup.class.php into the generated module''s backport/v16/core/class folder for Dolibarr v16 compatibility.', 'Checked in modulebuilder/index.php:339-344: `if (getDolGlobalInt(''MODULEBUILDER_SUPPORT_COMPATIBILITY_V16'')) { $tryToCopyFromSetupClass = true; $backportDest = $destdir .''/backport/v16/core/class''; ... }`, during the module scaffold/copy step of the ModuleBuilder tool.', 'Affects only the developer-facing ModuleBuilder tool: when enabled, an extra backport copy of html.formsetup.class.php is created in the generated module tree to support running on Dolibarr v16.', 'Boolean-like integer; truthy enables the v16 backport file copy step.', 1, 0, NULL, 1, 'c7f4db6a9644cd9b9a6233eee10633bfa929ee49546b9daa6339026da3d4ca65', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/index.php:339|check|if (getDolGlobalInt(''MODULEBUILDER_SUPPORT_COMPATIBILITY_V16'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULEBUILDER_USE_ABOUT', 'bool', NULL, 'modulebuilder', 'Controls whether the Module Builder includes an ''About'' page scaffold for new modules.', 'Checked in modulebuilder/admin/setup.php:138 and modulebuilder/index.php:335. Configurable via modulebuilder/admin/setup.php.', 'When enabled, the Module Builder generates an About page for new modules. When disabled, the About page scaffold is omitted.', 'Truthy string (About page included) or empty/unset (About page omitted).', 0, 0, 'modulebuilder/admin/setup.php', 1, 'a0955c627e48b1c564a81e5b64213468846f9ae71483e6bd1dc80fab1a594d04', 'v2', '2026-04-21T13:29:58+00:00', '["modulebuilder/admin/setup.php:138|check|if (!getDolGlobalString(''MODULEBUILDER_USE_ABOUT'')) {", "modulebuilder/index.php:335|check|if (getDolGlobalString(''MODULEBUILDER_USE_ABOUT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULE_COLLAB_DISABLED', 'bool', NULL, 'core', 'When set, forces the Collaboration (Collab) module to report itself as hidden, effectively disabling/hiding it regardless of normal activation state.', 'Read in core/modules/modCollab.class.php:67 into $this->hidden with the inline comment ''A condition to disable module'', the same pattern used by MODULE_CRON_DISABLED.', 'Setting it truthy hides the Collab module from the module list/menus, effectively disabling it.', 'Boolean/int: truthy hides (disables) the module.', 1, 0, NULL, 1, 'ea4ae6c8c7e97352db03191a85ac0a17eaffd6a6eb9e80ee0d3e7846f1788dc4', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modCollab.class.php:67|read|$this->hidden = getDolGlobalInt(''MODULE_COLLAB_DISABLED''); // A condition to disable module"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULE_CRON_DISABLED', 'bool', NULL, 'core', 'When set, forces the Cron (scheduled jobs) module to report itself as hidden, effectively disabling/hiding it regardless of normal activation state.', 'Read in core/modules/modCron.class.php:67 into $this->hidden with the inline comment ''A condition to disable module'', following the same pattern used by other core modules (e.g. MODULE_COLLAB_DISABLED).', 'Setting it truthy hides the Cron module from the module list/menus, effectively disabling scheduled-job functionality exposure.', 'Boolean/int: truthy hides (disables) the module.', 1, 0, NULL, 1, '9f6d5cdc3839f52ada9092f747c4d737dd9ddffc92e26e53bb6efaba97566563', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modCron.class.php:67|read|$this->hidden = getDolGlobalInt(''MODULE_CRON_DISABLED''); // A condition to disable module"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULE_MYMODULE_DISABLED', 'bool', NULL, 'modulebuilder', 'ModuleBuilder template flag used as a placeholder condition to hide/disable the generated MyModule module.', 'Read in modMyModule.class.php:160, assigned directly to $this->hidden in the module descriptor''s constructor, per the inline comment ''A condition to disable module''.', 'In generated module skeletons, if this constant is truthy, the module is reported as hidden ($this->hidden set) in the module list; this is boilerplate meant to be customized by the module author.', 'Any truthy value hides the module (sets $this->hidden); this is placeholder/example code in the module builder template, not a shipped Dolibarr behavior.', 0, 0, NULL, 1, 'aef6d4afc2f30111880f9e19b00d2c5678d6349d33922e2f75754341b2ef6e39', 'v2', '2026-07-24T07:05:23+00:00', '["modMyModule.class.php:160: $this->hidden = getDolGlobalInt(''MODULE_MYMODULE_DISABLED''); // A condition to disable module;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULE_NAME', 'string', NULL, 'core', 'Documentation placeholder for the per-module activation flag (the real constant is each module''s declared const_name, e.g. MAIN_MODULE_<MODULENAME>) checked by activateModule() to skip re-running module init if already enabled.', 'Documented in the docblock of activateModule() in core/lib/admin.lib.php:1189 (''Remove verification of $conf->global->MODULE_NAME variable for module''); the actual code at line 1249-1253 reads $const_name = $objMod->const_name and, unless $noconfverification is set, returns early if getDolGlobalString($const_name) is already true.', 'This is a placeholder name in the docblock, not a literal constant; the real per-module const_name constant being already set causes activateModule() to skip re-initializing the module, unless the caller passes $noconfverification=1 to force re-init.', 'N/A - MODULE_NAME is a doc placeholder; the real constant is module-specific (module''s $objMod->const_name property).', 1, 0, NULL, 1, '7fe5550c8fe44672f902af0828759d9cc83253b125978fcad1dabe7f5a0c8249', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/admin.lib.php:1189: * \t@param\t\tint\t\t\t$noconfverification\t\tRemove verification of $conf->global->MODULE_NAME variable for module", "core/lib/admin.lib.php:1249: $const_name = $objMod->const_name;", "core/lib/admin.lib.php:1251: if (getDolGlobalString($const_name)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULE_QUICKMEMO_DISABLED', 'bool', NULL, 'core', 'Hides/disables the QuickMemo core module when set.', 'Read in core/modules/modQuickMemo.class.php:157: `$this->hidden = getDolGlobalInt(''MODULE_QUICKMEMO_DISABLED''); // A condition to disable module;`, the standard Dolibarr module-hiding pattern.', 'Setting it truthy hides the QuickMemo module from the module list/admin, making it unavailable to enable.', 'Boolean-like: truthy hides the module (sets $this->hidden).', 1, 0, NULL, 1, '59f7108a6c0c485861421d657825c6e8c980b56ef4d204277ed7f153cd64d914', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modQuickMemo.class.php:157: $this->hidden = getDolGlobalInt(''MODULE_QUICKMEMO_DISABLED''); // A condition to disable module;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULE_SOCIALNETWORKS_DISABLED', 'bool', NULL, 'core', 'Hides/disables the Social Networks core module when set.', 'Read in core/modules/modSocialNetworks.class.php:65: `$this->hidden = getDolGlobalInt(''MODULE_SOCIALNETWORKS_DISABLED''); // A condition to hide module`, the standard Dolibarr module-hiding pattern used by module descriptor classes.', 'Setting it truthy hides the Social Networks module from the module list/admin, making it unavailable to enable.', 'Boolean-like: truthy hides the module (sets $this->hidden).', 1, 0, NULL, 1, '1edb96551b5a236458f44f3b55fe2259c79519c3d898ddbdc7e695c2d7ee8b66', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modSocialNetworks.class.php:65: $this->hidden = getDolGlobalInt(''MODULE_SOCIALNETWORKS_DISABLED''); // A condition to hide module"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULE_UPLOAD_MAX_EXECUTION_TIME', 'string', NULL, 'admin', 'PHP execution time limit (in seconds) applied while deploying/uploading an external module from the admin Modules page.', 'Read in admin/modules.php:146 with a default of 300 (comment ''5mn if not defined''), then passed to @set_time_limit() to extend the time allowed for the module deployment operation.', 'Increasing it allows longer module-upload/deploy operations before PHP''s execution time limit kills the request; has no effect if PHP safe_mode-like restrictions block set_time_limit().', 'Integer number of seconds; defaults to 300 if not defined.', 0, 0, 'admin/modules.php', 1, '845f604c0ddc87e41db1cf2faeb5665b3e3b8cafdbae43179dac4cf9a9ff5a90', 'v2', '2026-07-24T07:05:23+00:00', '["admin/modules.php:146: $max_execution_time_for_deploy = getDolGlobalInt(''MODULE_UPLOAD_MAX_EXECUTION_TIME'', 300); // 5mn if not defined"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MODULE_WEBSITE_DISABLED', 'bool', NULL, 'core', 'Hides the Website module from the module list/admin by marking it as a hidden module.', 'Read directly in the module descriptor at core/modules/modWebsite.class.php:65, with the inline comment ''A condition to disable module'', assigned to $this->hidden.', 'Setting it truthy sets modWebsite''s $this->hidden flag, which Dolibarr''s module framework uses to keep the module out of the visible modules admin list.', 'Boolean-like (int via getDolGlobalInt).', 1, 0, NULL, 1, '249d464a9299eab8ec0cb2728f1f974740739ade3b6b7de8d09f7080f646f300', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modWebsite.class.php:65: $this->hidden = getDolGlobalInt(''MODULE_WEBSITE_DISABLED''); // A condition to disable module"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MOUVEMENT_ADDON_PDF', 'string', NULL, 'product', 'Selects which PDF document model/template is used to generate stock movement documents.', 'Registered as a module constant with default ''standard_movement_stock'' in core/modules/modStock.class.php:93-97 (''Name of PDF model of stock movement''), and read in MouvementStock::generateDocument() (product/stock/class/mouvementstock.class.php:1277-1278) as a fallback when no model is explicitly passed and $this->model_pdf is empty.', 'Changing it selects a different PDF template (module name under core/modules/stock/doc/) to render when generating a stock movement PDF document.', 'String: name of a PDF model module for stock movements; default ''standard_movement_stock''.', 0, 0, NULL, 1, 'c91d175f092a48d7ef7ec8dc6b4b0f134392bbcfbd22bf41923014b404237710', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modStock.class.php:93-96: \"MOUVEMENT_ADDON_PDF\", \"chaine\", \"standard_movement_stock\", ''Name of PDF model of stock movement'',", "product/stock/class/mouvementstock.class.php:1277-1278: } elseif (getDolGlobalString(''MOUVEMENT_ADDON_PDF'')) { $modele = getDolGlobalString(''MOUVEMENT_ADDON_PDF''); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MO_ALSO_CANCEL_CONSUMED_AND_PRODUCED_LINES_BY_DEFAULT', 'string', NULL, 'mrp', 'Sets the default checkbox state (checked/unchecked) for the ''also cancel consumed and produced lines'' option shown on the Manufacturing Order delete confirmation dialog.', 'Read via getDolGlobalString() in mrp/mo_card.php:602 and mrp/mo_production.php:678 to preselect the ''alsoCancelConsumedAndProducedLines'' checkbox value on the MO deletion confirmation form.', 'When set (truthy), the delete-confirmation checkbox defaults to checked (1), so consumed/produced lines are cancelled by default when a manufacturing order is deleted, unless the user unchecks it.', 'Not set/falsy: checkbox defaults to unchecked (0). Truthy: checkbox defaults to checked (1).', 1, 0, NULL, 1, '263aa7f4c751cddc3e7bfa3a8677c7bc2ffdbd9b779521df3e886357e6ae3006', 'v2', '2026-07-24T07:05:23+00:00', '["mrp/mo_card.php:602|read|''value'' => !getDolGlobalString(''MO_ALSO_CANCEL_CONSUMED_AND_PRODUCED_LINES_BY_DEFAULT'') ? 0 : 1", "mrp/mo_production.php:678|read|''value'' => !getDolGlobalString(''MO_ALSO_CANCEL_CONSUMED_AND_PRODUCED_LINES_BY_DEFAULT'') ? 0 : 1"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_AUTO_SET_REMAINING_QUANTITIES_TO_BE_CONSUMED', 'string', NULL, 'mrp', 'Controls whether the ''quantity to consume'' field on the MO consume/produce screen is pre-filled with the remaining expected quantity or left at 0.', 'Read in mrp/mo_production.php:1470: during a ''consumeorproduce'' action, if this constant is not set and no quantity was already posted for the line, the preselected quantity is forced to 0 instead of the default remaining-to-consume value.', 'Not set (default): quantity input for consumption is preselected to 0 for lines without a posted value. Set: quantity input keeps the calculated remaining quantity (max(0, $line->qty - $alreadyconsumed)) as default.', 'Not set/falsy (default behavior): preselect 0. Truthy: preselect remaining quantity to consume.', 1, 0, NULL, 1, '4195d0c94acf534cdf33297350b2bd94a4089a330fccc72dd23c7bbba39aa9ce', 'v2', '2026-07-24T07:05:23+00:00', '["mrp/mo_production.php:1470|check|if ($action == ''consumeorproduce'' && !getDolGlobalString(''MRP_AUTO_SET_REMAINING_QUANTITIES_TO_BE_CONSUMED'') && !GETPOSTISSET(''qty-''.$line->id.''-''.$i)) {", "mrp/mo_production.php:1471|code|$preselected = 0;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_BOX_LAST_MOS_SHOW_VALIDATE_USER', 'bool', NULL, 'core', 'Adds a ''validated by'' user column to the ''last manufacturing orders'' home dashboard box.', 'Checked at core/boxes/box_mos.php:128; when true, the box fetches and displays the user who validated the manufacturing order (fk_user_valid) as an extra column.', 'Setting it to true shows the validating user''s name in the last-MOs box; leaving it unset omits that column''s content.', 'Boolean-like: true/1 shows the validating-user column.', 1, 0, NULL, 1, '3d0d2c71a7d00496c181488457de2457f3055fe1f40c087717a37d29248da588', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_mos.php:128|check|if (getDolGlobalString(''MRP_BOX_LAST_MOS_SHOW_VALIDATE_USER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_MO_ADDON', 'string', NULL, 'mrp', 'Specifies the numbering module class used to generate Manufacturing Order reference numbers.', 'Written in admin/mrp.php at line 147 and read in mrp/class/mo.class.php at lines 1071-1075. The value is the class name of the addon; the corresponding PHP file is loaded to call the numbering logic. The source comment states the number is ''defined into MRP_MO_ADDON''.', 'Changing this constant switches the MO reference numbering scheme. If the specified class file does not exist, MO number generation will fail.', 'String class name of a numbering module (e.g. ''mod_mo_simple'')', 0, 0, 'admin/mrp.php|admin/mrp.php', 1, '8db5f612229a74df06a591f8b1c0c6e075c81a03ddafb0d03257643e4a73b5e9', 'v2', '2026-04-21T11:16:15+00:00', '["*  defined into MRP_MO_ADDON", "$classname = getDolGlobalString(''MRP_MO_ADDON'');", "$file = getDolGlobalString(''MRP_MO_ADDON'') . \".php\";", "if (getDolGlobalString(''MRP_MO_ADDON'') == $file) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_MO_ADDON_PDF', 'string', NULL, 'admin', 'Specifies the PDF model used to generate Manufacturing Order documents.', 'Written and read in admin/mrp.php (lines 126, 132, 135, 402) and read in mrp/class/mo.class.php at lines 1743-1744. A module comment describes it as ''Name of default PDF model of MO'' with default value ''vinci''.', 'Changing this value switches which PDF template is used when printing or downloading a Manufacturing Order.', 'String name of a PDF model module (e.g. ''vinci'')', 0, 0, 'admin/mrp.php|admin/mrp.php|admin/mrp.php|admin/mrp.php|admin/mrp.php', 1, 'a09e84b4e82fc786c1a9360f361dff79e0d411091eab0a17f643f25f2ff1e5f1', 'v2', '2026-04-21T11:16:15+00:00', '["//1=>array(''MRP_MO_ADDON_PDF'', ''chaine'', ''vinci'', ''Name of default PDF model of MO'', 0),", "$modele = getDolGlobalString(''MRP_MO_ADDON_PDF'');", "if (getDolGlobalString(\"MRP_MO_ADDON_PDF\") == $name) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_MO_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies the directory path(s) for ODT document templates used by the generic MRP manufacturing order ODT module.', 'Read in doc_generic_mo_odt.modules.php at line 126 (split into a list of dirs), line 153 (display in UI), and line 161 (checked for existence). No admin UI write via dolibarr_set_const is present in the payload.', 'Changing this path redirects the module to a different set of ODT template directories; setting it to a non-existent path disables ODT template loading.', 'Comma-separated directory path(s); empty = no custom ODT path.', 1, 0, NULL, 1, '47518f1d11d2831220c9f2e1598b587b1f27a59712a935d835b7b69b7aa2b3b4', 'v2', '2026-04-21T13:50:40+00:00', '["doc_generic_mo_odt.modules.php:126|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim($conf->global->MRP_MO_ADDON_PDF_ODT_PATH)));", "doc_generic_mo_odt.modules.php:153|read|$texte .= getDolGlobalString(''MRP_MO_ADDON_PDF_ODT_PATH'');", "doc_generic_mo_odt.modules.php:161|check|if (getDolGlobalString(''MRP_MO_ADDON_PDF_ODT_PATH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_MO_ADVANCED_MASK', 'string', NULL, 'core', 'Numbering mask (pattern) used by the ''Advanced'' manufacturing-order (Mo) reference generator to build new MO references.', 'Read/written in core/modules/mrp/mod_mo_advanced.php:89 (admin form input ''maskMo'') and used at line 142 inside getNextValue() to compute the next MO reference; if empty, getNextValue() returns an error ''NotConfigured''.', 'Changing the mask changes the format of newly generated manufacturing order references going forward; an empty/unset mask makes MO numbering fail with ''NotConfigured''.', 'A generic Dolibarr numbering mask string (per GenericMaskCodes rules, e.g. placeholders for year/month/counter); required to be non-empty for numbering to work.', 0, 0, NULL, 1, 'c2c1809dd66a8a2573ba6cac7bcd9d43232efb7fbe424f0b586b49c2283686ad', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/mrp/mod_mo_advanced.php:89|read|value=\"''.getDolGlobalString(''MRP_MO_ADVANCED_MASK'').''\">", "core/modules/mrp/mod_mo_advanced.php:142|read|$mask = getDolGlobalString(''MRP_MO_ADVANCED_MASK'');", "core/modules/mrp/mod_mo_advanced.php: if (!$mask) { $this->error = ''NotConfigured'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_MO_DRAFT_WATERMARK', 'string', NULL, 'admin', 'Sets the watermark text displayed on draft Manufacturing Orders (MO) PDF documents.', 'Written at admin/mrp.php:150 via dolibarr_set_const and read at admin/mrp.php:494 into a text input in the admin UI, making it configurable through the admin panel.', 'Changing this value updates the watermark string shown on draft MO documents; an empty value removes the watermark.', 'Any string = used as the draft watermark text; empty = no watermark.', 0, 0, 'admin/mrp.php|admin/mrp.php', 1, '1f9aec014c877b249ee29731aac3f5a61eb913bec6faab7eb36ac930166006d4', 'v2', '2026-04-21T13:50:40+00:00', '["admin/mrp.php:150|write|$res = dolibarr_set_const($db, \"MRP_MO_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "admin/mrp.php:494|read|print ''<input class=\"flat minwidth200\" type=\"text\" name=\"MRP_MO_DRAFT_WATERMARK\" value=\"''.dol_escape_htmltag(getDolGlobalString(''MRP_MO_DRAFT_WATERMARK'')).''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_MO_FREE_TEXT', 'string', NULL, 'admin', 'Free text saved from the MRP (Manufacturing Order) module admin setup and printed in the footer of manufacturing order PDF/ODT documents.', 'Set via admin/mrp.php:164 (action ''set_MRP_MO_FREE_TEXT'', dolibarr_set_const) and read by ODT model core/modules/mrp/doc/doc_generic_mo_odt.modules.php:334 as $paramfreetext for manufacturing order documents.', 'Changing the value changes the free text block printed at the bottom of generated manufacturing order documents; no other effect found.', 'Any HTML/restricted-HTML string entered by the admin (GETPOST ''restricthtml'' filter); empty means no free text.', 0, 0, 'admin/mrp.php', 1, '1791c903a127b49893285ff3f87d8fbe1a1e20ce40e0a70fa414b2561e1b646f', 'v2', '2026-07-24T07:05:23+00:00', '["admin/mrp.php:164|write|$res = dolibarr_set_const($db, \"MRP_MO_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);", "admin/mrp.php:162: $freetext = GETPOST(\"MRP_MO_FREE_TEXT\", ''restricthtml''); // No alpha here, we want exact string", "core/modules/mrp/doc/doc_generic_mo_odt.modules.php:334: $paramfreetext = ''MRP_MO_FREE_TEXT'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_NEVER_CONSUME_MORE_THAN_EXPECTED', 'string', NULL, 'mrp', 'Disables (grays out) the quantity-to-consume input on the MO consume/produce screen once the expected quantity for a line has already been fully consumed.', 'Checked in mrp/mo_production.php:1475: if set and the remaining quantity to consume for a line ($line->qty - $alreadyconsumed) is <= 0, the input field is rendered with the ''disabled'' HTML attribute.', 'When set, users cannot enter additional consumption quantity for a line once its expected quantity has already been consumed, preventing over-consumption beyond what the MO line expects.', 'Not set/falsy (default): input remains enabled, allowing consumption beyond expected quantity. Truthy: input disabled once expected quantity is reached.', 1, 0, NULL, 1, 'c24ecaed8c45d5f627ee360ba4bea62392837d814836941eaceb2ad812c420c1', 'v2', '2026-07-24T07:05:23+00:00', '["mrp/mo_production.php:1475|check|if (getDolGlobalString(''MRP_NEVER_CONSUME_MORE_THAN_EXPECTED'') && ($line->qty - $alreadyconsumed) <= 0) {", "mrp/mo_production.php:1476|code|$disable = ''disabled'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MRP_SHOW_COST_FOR_CONSUMPTION', 'bool', NULL, 'mrp', 'Shows cost/price fields on production consumption lines for users with the cost-update permission.', 'Checked in mrp/mo_production.php at six locations (lines 894, 971, 1117, 1207, 1351, 1446), always combined with the permissiontoupdatecost check.', 'When enabled, users who have the cost-update permission see cost input fields on each consumption line during production. When disabled, those fields are hidden.', '0 or unset = cost fields hidden on consumption lines; 1 = cost fields shown for authorized users', 1, 0, NULL, 1, '735635ee2a4ab9de38750150aec0363ffed6cfa70b01a997b761553825418c49', 'v2', '2026-04-21T11:16:15+00:00', '["if ($permissiontoupdatecost && getDolGlobalString(''MRP_SHOW_COST_FOR_CONSUMPTION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICOMPANY_ALLOW_EXPORT_ACCOUNTING_DOC_FOR_ALL_ENTITIES', 'bool', NULL, 'compta', 'Allows exporting accounting documents across all entities in a multi-company setup.', 'When set, compta/accounting-files.php enables cross-entity export when no specific entity is selected (line 138) and shows an otherwise greyed-out export option (lines 661-662).', 'Enabling this grants users the ability to export accounting files for all entities at once, which may expose financial data from entities the user would not normally access.', 'Empty/unset = export limited to the current entity; truthy value = cross-entity export enabled.', 1, 0, NULL, 1, 'f927378ea4267d41053596bfd1eae4e95bf940a497d0063e59d0b9d280151513', 'v2', '2026-04-21T13:29:58+00:00', '["compta/accounting-files.php:138|check|if (empty($entity) && getDolGlobalString(''MULTICOMPANY_ALLOW_EXPORT_ACCOUNTING_DOC_FOR_ALL_ENTITIES'')) {", "compta/accounting-files.php:662|check|if (getDolGlobalString(''MULTICOMPANY_ALLOW_EXPORT_ACCOUNTING_DOC_FOR_ALL_ENTITIES'')) {", "compta/accounting-files.php:661|read|print '' &nbsp; <span class=\"marginleftonly marginrightonly''.(!getDolGlobalString(''MULTICOMPANY_ALLOW_EXPORT_ACCOUNTING_DOC_FOR_ALL_ENTITIES'') ? '' opacitymedium'' : '''').''\">''.$langs->"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICOMPANY_BACKWARD_COMPATIBILITY', 'string', NULL, 'user', 'Enables a legacy (backward-compatibility) code path for multi-company user queries, flagged as a questionable business rule by developers.', 'Checked at user/class/user.class.php:1382 and :1447. Both locations carry the comment: ''@FIXME Test on MULTICOMPANY_BACKWARD_COMPATIBILITY is a very strange business rules because the select should be always the [same]''.', 'Enabling this constant activates a non-standard user-selection code path for multi-company setups; the code itself flags this as a design issue.', 'Empty/unset = standard code path; any truthy value = legacy backward-compatible code path.', 1, 0, NULL, 1, 'd830c60cbb733454406d501706045f42d4993510ac52ed5b831f3b5fde73e1eb', 'v2', '2026-04-21T13:50:40+00:00', '["// @FIXME Test on MULTICOMPANY_BACKWARD_COMPATIBILITY is a very strange business rules because the select should be always the", "user/class/user.class.php:1382|check|if (getDolGlobalString(''MULTICOMPANY_BACKWARD_COMPATIBILITY'')) {", "user/class/user.class.php:1447|check|if (getDolGlobalString(''MULTICOMPANY_BACKWARD_COMPATIBILITY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICOMPANY_ENTITY_IN_EXPORT_IF_SHARED', 'string', NULL, 'core', 'Adds an entity field to export definitions for shared objects in multi-company mode.', 'When set, multiple module export definitions (modSociete, modFacture, modPropale, modCommande, modAgenda, modProjet) include an entity column in their export field lists. Used across 8 occurrences in core/modules/. No admin UI write; hidden setting.', 'Enabling this constant adds an entity discriminator column to exports for shared records in multi-company setups; disabling it omits that column.', 'Non-empty (truthy) includes entity field in exports; empty or undefined excludes it.', 1, 0, NULL, 1, 'fdbefe8d1e6c19720c61b5aa13501dbf1eaaa5e3ffd66aef9c2443a679b1300b', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/modSociete.class.php:295|check|if (getDolGlobalString(''MULTICOMPANY_ENTITY_IN_EXPORT_IF_SHARED'')) {", "core/modules/modFacture.class.php:559|check|if (getDolGlobalString(''MULTICOMPANY_ENTITY_IN_EXPORT_IF_SHARED'')) {", "core/modules/modPropale.class.php:235|check|if (getDolGlobalString(''MULTICOMPANY_ENTITY_IN_EXPORT_IF_SHARED'')) {", "core/modules/modAgenda.class.php:455|check|if (getDolGlobalString(''MULTICOMPANY_ENTITY_IN_EXPORT_IF_SHARED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICOMPANY_INVOICE_SHARING_ENABLED', 'bool', NULL, 'compta', 'Enables sharing of invoices and treasury data across entities in a multi-company setup.', 'Checked in compta/paiement/card.php:519, :572 and compta/bank/treso.php:223, :237, :353. All checks require isModEnabled(''multicompany''). No admin UI write was found; HIDDEN_GUESS is 1.', 'Enabling this constant allows invoice payment and treasury views to include data from other entities when the multicompany module is active.', '0 (sharing disabled) or 1 (sharing enabled)', 1, 0, NULL, 1, '80b0231e9d0173efbe12e4309e9acf89308241a018b5bbed453ef7fa8de4577f', 'v2', '2026-04-21T11:16:15+00:00', '["compta/paiement/card.php:519|check|if (isModEnabled(''multicompany'') && getDolGlobalString(''MULTICOMPANY_INVOICE_SHARING_ENABLED'')) {", "compta/bank/treso.php:223|check|if (getDolGlobalInt(''MULTICOMPANY_INVOICE_SHARING_ENABLED'')) {", "compta/bank/treso.php:353|check|if (isModEnabled(''multicompany'') && isset($mc) && getDolGlobalString(\"MULTICOMPANY_INVOICE_SHARING_ENABLED\")) {", "compta/paiement/card.php:572|check|if (isModEnabled(''multicompany'') && isset($mc) && getDolGlobalString(''MULTICOMPANY_INVOICE_SHARING_ENABLED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICOMPANY_PMP_PER_ENTITY_ENABLED', 'bool', NULL, 'product', 'Enables per-entity weighted average price (PMP) tracking for products when combined with product sharing across multicompany entities.', 'Checked with getDolGlobalString(''MULTICOMPANY_PMP_PER_ENTITY_ENABLED'') in product/class/product.class.php:3086 and always together with MULTICOMPANY_PRODUCT_SHARING_ENABLED in product/inventory/inventory.php:269, product/stock/list.php:239, product/stock/class/entrepot.class.php:721 and product/stock/card.php:708.', 'When both this and MULTICOMPANY_PRODUCT_SHARING_ENABLED are set, per-entity data (llx_product_perentity) is used, per the comment at product/inventory/inventory.php:265-266.', NULL, 0, 0, NULL, 1, 'dec797bd5a8d98ff9d4702b5a5bc731b9471ead000bb3eb4985d036c79521c2a', 'v2', '2026-07-24T06:41:12+00:00', '["// MULTICOMPANY_PMP_PER_ENTITY_ENABLED are both set. MAIN_PRODUCT_PERENTITY_SHARED", "if (getDolGlobalString(''MULTICOMPANY_PRODUCT_SHARING_ENABLED'') && getDolGlobalString(''MULTICOMPANY_PMP_PER_ENTITY_ENABLED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICOMPANY_PRODUCT_SHARING_ENABLED', 'bool', NULL, 'product', 'Enables sharing of product data across entities in a multicompany setup.', 'Checked with getDolGlobalString(''MULTICOMPANY_PRODUCT_SHARING_ENABLED'') in product/class/product.class.php:3085, product/stock/replenish.php:95, and together with MULTICOMPANY_PMP_PER_ENTITY_ENABLED in product/inventory/inventory.php:269, product/stock/list.php:239, product/stock/class/entrepot.class.php:721 and product/stock/card.php:708.', 'When enabled, product-related code paths use the llx_product_perentity table per the comment at product/inventory/inventory.php:265 (''llx_product_perentity only when MULTICOMPANY_PRODUCT_SHARING_ENABLED and'').', NULL, 0, 0, NULL, 1, '95792f9e51e67ecd2371f5e161f747e8d61f3b069af09ddbd6bff865857f900e', 'v2', '2026-07-24T06:41:12+00:00', '["// llx_product_perentity only when MULTICOMPANY_PRODUCT_SHARING_ENABLED and", "if (getDolGlobalString(''MULTICOMPANY_PRODUCT_SHARING_ENABLED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICOMPANY_TRANSVERSE_MODE', 'string', NULL, 'user', 'Enables transverse mode in the Multicompany module, allowing cross-entity access to shared data such as suppliers, holidays, and user permissions.', 'Checked with isModEnabled(''multicompany'') && getDolGlobalString(''MULTICOMPANY_TRANSVERSE_MODE'') across many files, e.g. fourn/commande/index.php:242/247, societe/class/societe.class.php:2878 and holiday/class/holiday.class.php:1936/1942/2026/2032; noted in comments at user/perms.php:344 and user/class/user.class.php:1494 about duplicate record issues.', 'When enabled with the multicompany module active, code paths treat entities transversally, which per the comments ''may have inserted record that make rubbish result here due to the duplicate record''.', NULL, 0, 0, NULL, 1, 'a5df026167ed63312284cb3ab6fb85c5d08329b0e5fdc7774d088844d61d2f34', 'v2', '2026-07-24T06:41:12+00:00', '["// but when using MULTICOMPANY_TRANSVERSE_MODE, we may have inserted record that make rubbish result here due to the duplicate record of", "if (isModEnabled(''multicompany'') && getDolGlobalString(''MULTICOMPANY_TRANSVERSE_MODE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICOMPANY_TRANSVERSE_MODE_FIX_WHEN_GU_CONTAINS_0', 'string', NULL, 'user', 'Fixes a permission query join to also match group-user rows recorded with entity=0 when multi-company transverse mode is used.', 'In user/perms.php:346, while building the SQL to read a user''s permissions inherited from groups, this bool switches the filter on gu.entity from an exact match on the current entity to ''IN (0, entity)''; the surrounding comment explains this handles duplicate records inserted for other entities when using MULTICOMPANY_TRANSVERSE_MODE.', 'Enabling it changes the SQL WHERE clause to also include usergroup_user rows with entity=0, fixing rubbish/duplicate permission results seen with MULTICOMPANY_TRANSVERSE_MODE; leaving it off keeps the strict entity match.', 'true/1 = filter gu.entity IN (0, current entity); false/unset (default) = filter gu.entity = current entity only.', 1, 0, NULL, 1, '734b8c5958c37abe8b4a6c7fa6576ead04af684cf213bcc85066f4ef6724ae7e', 'v2', '2026-07-24T07:05:23+00:00', '["user/perms.php:344: // but when using MULTICOMPANY_TRANSVERSE_MODE, we may have inserted record that make rubbish result here due to the duplicate record of", "user/perms.php:346|check|if (getDolGlobalString(\"MULTICOMPANY_TRANSVERSE_MODE_FIX_WHEN_GU_CONTAINS_0\")) {", "user/perms.php:347: $sql .= \" AND gu.entity IN (0,\". ((int) $entity).\")\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_ALTERNATE_SOURCE', 'string', NULL, 'admin', 'Specifies an alternate source currency code used as a reference when computing multicurrency exchange rates.', 'Read in admin/multicurrency.php:414 via a text input with placeholder ''EUR''. The write line at :148 is commented out. The admin comment clarifies the example value.', 'Setting this constant changes the reference currency used in alternate rate computations; the write path is currently commented out.', 'Currency code string, e.g. ''EUR''.', 0, 0, 'admin/multicurrency.php|admin/multicurrency.php', 1, '9157179aa6a61a77d28ab5c6119ffd8fd6c4b6149d1d434792493e896cfd559c', 'v2', '2026-04-21T13:50:40+00:00', '["//dolibarr_set_const($db, ''MULTICURRENCY_ALTERNATE_SOURCE'', GETPOST(''MULTICURRENCY_ALTERNATE_SOURCE'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "print ''<input type=\"text\" name=\"MULTICURRENCY_ALTERNATE_SOURCE\" value=\"''.$conf->global->MULTICURRENCY_ALTERNATE_SOURCE.''\" size=\"10\" placeholder=\"EUR\" />&nbsp;''; // Example: EUR"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_APP_ENDPOINT', 'string', NULL, 'admin', 'Stores the URL endpoint of the external currency rate API used for fetching exchange rates.', 'Set via admin/multicurrency.php:147 and read at multicurrency/class/multicurrency.class.php:116 as `$urlendpoint = getDolGlobalString(''MULTICURRENCY_APP_ENDPOINT'', self::MULTICURRENCY_APP_ENDPOINT_DEFAULT)`. The admin UI at admin/multicurrency.php:408 shows the current value with the class default as placeholder. 3 occurrences across 2 files.', 'When unset, the class-defined default endpoint URL is used. When set, requests for exchange rate data are sent to the specified URL.', 'String (URL); unset = MultiCurrency::MULTICURRENCY_APP_ENDPOINT_DEFAULT (class constant).', 0, 0, 'admin/multicurrency.php|admin/multicurrency.php', 1, '32353dc2fda0362aad358e7e2064c7c1c2bb69b0c83ff8f0445ec9d1d965b22e', 'v2', '2026-04-21T11:16:15+00:00', '["admin/multicurrency.php:147|write|dolibarr_set_const($db, ''MULTICURRENCY_APP_ENDPOINT'', GETPOST(''MULTICURRENCY_APP_ENDPOINT'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "multicurrency/class/multicurrency.class.php:116|read|$urlendpoint = getDolGlobalString(\"MULTICURRENCY_APP_ENDPOINT\", self::MULTICURRENCY_APP_ENDPOINT_DEFAULT);", "admin/multicurrency.php:408|read|... value=\"'' . getDolGlobalString(''MULTICURRENCY_APP_ENDPOINT'', MultiCurrency::MULTICURRENCY_APP_ENDPOINT_DEFAULT)..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_APP_KEY', 'string', NULL, 'admin', 'Stores the API key used to authenticate requests to the external currency rate provider.', 'Set via admin/multicurrency.php:145 and read at multicurrency/class/multicurrency.class.php:114 and :686 where it is sent as an ''apikey'' HTTP header. The admin UI at admin/multicurrency.php:387 checks for its presence before allowing rate synchronization. 5 occurrences across 2 files.', 'When not set, currency rate synchronization from the external provider is blocked. When set, the key is included in API requests for fetching exchange rates.', 'String (API key); empty/unset = rate sync blocked.', 0, 0, 'admin/multicurrency.php|admin/multicurrency.php|admin/multicurrency.php', 1, 'eb90977d76b537bbd65cd96ef7868cffd046edb4246ddb2e4734d3303f95ee70', 'v2', '2026-04-21T11:16:15+00:00', '["admin/multicurrency.php:145|write|dolibarr_set_const($db, ''MULTICURRENCY_APP_KEY'', GETPOST(''MULTICURRENCY_APP_KEY'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/multicurrency.php:387|check|if (!getDolGlobalString(''MULTICURRENCY_APP_KEY'')) {", "multicurrency/class/multicurrency.class.php:114|read|$key = getDolGlobalString(\"MULTICURRENCY_APP_KEY\");", "multicurrency/class/multicurrency.class.php:686|read|$addheaders = array(''apikey: ''.getDolGlobalString(''MULTICURRENCY_APP_KEY''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_APP_SOURCE', 'string', NULL, 'admin', 'Defines the source/reference currency code used by the multicurrency conversion logic.', 'Set via admin UI at admin/multicurrency.php:146/402 (default placeholder USD) and read in multicurrency/class/multicurrency.class.php:115 (default ''USD'') and compared in multicurrency.class.php:641.', 'Changing it changes which currency code is treated as the application''s source currency for conversion comparisons; defaults to USD if unset.', 'default: ''USD'' (see placeholder=''USD'' and getDolGlobalString(''MULTICURRENCY_APP_SOURCE'', ''USD''))', 0, 0, 'admin/multicurrency.php|admin/multicurrency.php', 1, '4d7eb2e7fdcffcd4edda2f717c2d71d9f0be4e4bc7369b4df0a807f775923446', 'v2', '2026-07-24T06:41:12+00:00', '["print ''<input type=\"text\" name=\"MULTICURRENCY_APP_SOURCE\" value=\"'' . getDolGlobalString(''MULTICURRENCY_APP_SOURCE'').''\" size=\"10\" placeholder=\"USD\" />&nbsp;''; // Default: USD", "$source = getDolGlobalString(''MULTICURRENCY_APP_SOURCE'', ''USD'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_BUY_PRICE_IN_CURRENCY', 'string', NULL, 'admin', 'Yes/no admin setting for the multicurrency module controlling whether buy prices are entered/stored in the foreign currency (vs. the company''s default currency).', 'Set via a yes/no form field in admin/multicurrency.php:260-261 (action ''set_MULTICURRENCY_BUY_PRICE_IN_CURRENCY''), configured through the Multicurrency module setup page.', 'Toggling it changes whether buy price entry fields are interpreted/stored in the foreign currency versus the local default currency for multicurrency-enabled purchases.', 'Boolean (yes/no) via $form->selectyesno.', 0, 0, 'admin/multicurrency.php', 1, 'cd24247a799de6baf22110731468cda9478f507b6668ae7ae184e435aef2baa6', 'v2', '2026-07-24T07:05:23+00:00', '["admin/multicurrency.php:260: print ''<input type=\"hidden\" name=\"action\" value=\"set_MULTICURRENCY_BUY_PRICE_IN_CURRENCY\">'';", "admin/multicurrency.php:261: print $form->selectyesno(\"MULTICURRENCY_BUY_PRICE_IN_CURRENCY\",$conf->global->MULTICURRENCY_BUY_PRICE_IN_CURRENCY,1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_DISABLE_SYNC_CURRENCYLAYER', 'bool', NULL, 'admin', 'Disables automatic/manual synchronization of currency exchange rates via the CurrencyLayer API.', 'In admin/multicurrency.php:361 the admin page only shows the manual sync form/button when this constant is not set; in multicurrency/class/multicurrency.class.php:671, syncRates() (called by the admin page and the autoupdate cron job) returns an error immediately if the constant is set.', 'Setting it to true blocks both the manual ''sync rates'' button and the automatic cron-based rate synchronization from calling the CurrencyLayer API, returning an error/event message instead.', 'boolean: 1/true disables CurrencyLayer sync (manual button hidden, cron sync fails with error); unset/0 = sync allowed.', 0, 0, 'admin/multicurrency.php', 1, '82846a92e2fbc6be4ed00acd748bab38ef1fed0c904596b0a97dd6cfa788326c', 'v2', '2026-07-24T07:05:23+00:00', '["admin/multicurrency.php:361: if (!getDolGlobalString(''MULTICURRENCY_DISABLE_SYNC_CURRENCYLAYER'')) {", "multicurrency/class/multicurrency.class.php:671: if (getDolGlobalString(''MULTICURRENCY_DISABLE_SYNC_CURRENCYLAYER'')) {", "multicurrency/class/multicurrency.class.php:673: $this->output = $langs->trans(''Use of API for currency update is disabled by option MULTICURRENCY_DISABLE_SYNC_CURRENCYLAYER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_MODIFY_RATE_APPLICATION', 'string', NULL, 'admin', 'Admin setting for the multicurrency module choosing whether editing an exchange rate applies to prices expressed in Dolibarr''s base currency or in the foreign currency.', 'Set via a select list in admin/multicurrency.php:274-275 (action ''set_MULTICURRENCY_MODIFY_RATE_APPLICATION'') with the two allowed values ''PU_DOLIBARR'' and ''PU_CURRENCY''.', 'Choosing ''PU_DOLIBARR'' vs ''PU_CURRENCY'' changes which price basis is recalculated when a multicurrency exchange rate is modified.', '''PU_DOLIBARR'' = apply rate change to price in Dolibarr currency; ''PU_CURRENCY'' = apply rate change to price in foreign currency (values verbatim from the selectarray call).', 0, 0, 'admin/multicurrency.php', 1, '7724ca1fff28ec046c3cb4b8c92728d9f8b51b86b31c44626b2cbe1f9a5c2490', 'v2', '2026-07-24T07:05:23+00:00', '["admin/multicurrency.php:275: print $form->selectarray(''MULTICURRENCY_MODIFY_RATE_APPLICATION'', array(''PU_DOLIBARR'' => ''PU_DOLIBARR'', ''PU_CURRENCY'' => ''PU_CURRENCY''), ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_SHOW_ALSO_MAIN_CURRENCY_ON_PDF', 'bool', NULL, 'core', 'Controls whether the main currency totals are also displayed alongside multicurrency totals on PDF documents.', 'Checked across 8 occurrences in core/lib/pdf.lib.php and multiple invoice/order/proposal PDF modules. The commented-out line at pdf.lib.php:1061 shows the conditional: when value is 0, multicurrency details are skipped. No admin UI write is present.', 'Setting this to 0 hides main currency totals when multicurrency is active and the exchange rate is not 1; non-zero values show both currencies.', '0 = do not show main currency alongside multicurrency; non-zero or absent = show main currency totals as well.', 1, 0, NULL, 1, '433eb94cd8bdf2346babc19da52e5cb9557d923f0547ce09b04acc8ec04c326b', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:1061  //if (!isModEnabled(\"multicurrency\") || $object->multicurrency_tx == 1 || getDolGlobalInt(''MULTICURRENCY_SHOW_ALSO_MAIN_CURRENCY_ON_PDF'') == 0) {", "core/modules/facture/doc/pdf_octopus.modules.php:1796|check|if (!isModEnabled(\"multicurrency\") || $object->multicurrency_tx == 1 || getDolGlobalInt(''MULTICURRENCY_SHOW_ALSO_MAIN_CURRENCY_ON_PDF'') == 0) {", "core/modules/facture/doc/pdf_sponge.modules.php:2047|check|if (!isModEnabled(\"multicurrency\") || $object->multicurrency_tx == 1 || getDolGlobalInt(''MULTICURRENCY_SHOW_ALSO_MAIN_CURRENCY_ON_PDF'') == 0) {", "core/modules/propale/doc/pdf_cyan.modules.php:1530|check|if (!isModEnabled(\"multicurrency\") || $object->multicurrency_tx == 1 || getDolGlobalInt(''MULTICURRENCY_SHOW_ALSO_MAIN_CURRENCY_ON_PDF'') == 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_USE_CURRENCY_ON_DOCUMENT', 'bool', NULL, 'admin', 'Enables using the document''s own currency (instead of company currency) for online payments on that document.', 'In admin/multicurrency.php:239-249, gated behind MAIN_FEATURES_LEVEL >= 2 (experimental), the admin page renders an on/off toggle (ajax_constantonoff) for this constant; a comment says ''Online payment with currency on document. This option should be on by default.''', 'Enabling it makes online payment pages use the multicurrency amount/currency of the document rather than the company''s main currency; it is only exposed in the admin UI when MAIN_FEATURES_LEVEL is 2 or higher.', 'boolean: 1/Yes = use document currency for online payment; 0/No = use company currency. Comment notes it ''should be on by default''.', 0, 0, 'admin/multicurrency.php', 1, '459a0f32b2f67df75c29a46721830dd9711e1b967efbac697c27e694efdaa8d9', 'v2', '2026-07-24T07:05:23+00:00', '["admin/multicurrency.php:239: // Online payment with currency on document. This option should be on by default.", "admin/multicurrency.php:248: print $form->selectarray(\"MULTICURRENCY_USE_CURRENCY_ON_DOCUMENT\", $arrval, getDolGlobalInt(\"MULTICURRENCY_USE_CURRENCY_ON_DOCUMENT\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_USE_LIMIT_BY_CURRENCY', 'bool', NULL, 'admin', 'When enabled (with the multicompany module), forces credit-limit checks to use a defined currency code instead of an empty default.', 'Checked at admin/limits.php:48, 142, 169, and 232 in combination with isModEnabled(''multicompany''). A COMMENT at admin/limits.php:49 states: ''When MULTICURRENCY_USE_LIMIT_BY_CURRENCY is on, we use always a defined currency code instead of '''' even for default.''', 'Enabling this constant changes limit calculations to always use an explicit currency code; disabling it falls back to an empty currency code for the default entity.', 'Empty/unset = use empty string for default currency in limit checks; any truthy value = use a defined currency code.', 0, 0, 'admin/limits.php|admin/limits.php|admin/limits.php|admin/limits.php', 1, '368b8cc4aa3163b603fcc03e65b304f7ab8ff624cc0f6586bf4de38dd16e7306', 'v2', '2026-04-21T13:50:40+00:00', '["// When MULTICURRENCY_USE_LIMIT_BY_CURRENCY is on, we use always a defined currency code instead of '''' even for default.", "admin/limits.php:48|check|if (isModEnabled(''multicompany'') && getDolGlobalString(''MULTICURRENCY_USE_LIMIT_BY_CURRENCY'')) {", "admin/limits.php:142|check|if (isModEnabled(''multicompany'') && getDolGlobalString(''MULTICURRENCY_USE_LIMIT_BY_CURRENCY'')) {", "admin/limits.php:232|check|if (isModEnabled(''multicompany'') && getDolGlobalString(''MULTICURRENCY_USE_LIMIT_BY_CURRENCY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_USE_ORIGIN_TX', 'bool', NULL, 'fourn', 'When creating a document from a source document, reuses the original multicurrency exchange rate instead of fetching the current rate.', 'Shown as a select array in admin/multicurrency.php (line 235). Checked across at least 10 files including supplier_proposal/card.php:1519, fourn/commande/card.php:1930, compta/facture/card.php:3808, and expedition/class/expedition.class.php:954 (`if (getDolGlobalString(''MULTICURRENCY_USE_ORIGIN_TX'') && !empty($objectsrc->multicurrency_tx))`).', 'Enabling this setting preserves the exchange rate from the source document when creating derived documents, ensuring currency consistency across linked records.', '0 = use current exchange rate; 1 = reuse origin document exchange rate.', 0, 0, 'admin/multicurrency.php', 1, '6c94e15f13fc4858823733ec269000f4155bb3fc1471fdf07a883f813786c396', 'v2', '2026-04-21T11:16:15+00:00', '["admin/multicurrency.php:235|read|print $form->selectarray(\"MULTICURRENCY_USE_ORIGIN_TX\", $arrval, getDolGlobalInt(\"MULTICURRENCY_USE_ORIGIN_TX\"));", "supplier_proposal/card.php:1519|check|if (getDolGlobalString(''MULTICURRENCY_USE_ORIGIN_TX'') && !empty($objectsrc->multicurrency_tx)) {", "fourn/commande/card.php:1930|check|if (getDolGlobalString(''MULTICURRENCY_USE_ORIGIN_TX'') && !empty($objectsrc->multicurrency_tx)) {", "expedition/class/expedition.class.php:954|check|if (getDolGlobalString(''MULTICURRENCY_USE_ORIGIN_TX'') && !empty($this->thirdparty->multicurrency_tx)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_USE_RATE_DIRECT', 'bool', NULL, 'multicurrency', 'Enables display and use of the direct exchange rate column in the multicurrency rate management page.', 'When set, multicurrency/multicurrency_rate.php:321 applies direct-rate logic and the ''RateDirect'' column is enabled in the rate list (multicurrency_rate.php:121). Also affects the HTML form at core/class/html.form.class.php:6966. Only 3 occurrences across 2 files.', 'When unset, the direct rate column is hidden and direct-rate logic is skipped. When set, the direct rate field is shown and used.', 'Truthy value = direct rate column enabled; empty/unset = hidden.', 1, 0, NULL, 1, 'cbd19f61d5792350b5b413796b8f51bbb1f952840f34d2e6aaf8c102eb86a37b', 'v2', '2026-04-21T11:16:15+00:00', '["multicurrency/multicurrency_rate.php:321|check|if (getDolGlobalString(''MULTICURRENCY_USE_RATE_DIRECT'')) {", "core/class/html.form.class.php:6966|check|if (getDolGlobalString(''MULTICURRENCY_USE_RATE_DIRECT'')) {", "multicurrency/multicurrency_rate.php:121|read|''cr.rate_direct'' => array(''label'' => ''RateDirect'', ''checked'' => ''0'', ''enabled'' => (!getDolGlobalString(''MULTICURRENCY_USE_RATE_DIRECT'') ? ''0'' : ''1'')),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_USE_RATE_INDIRECT', 'bool', NULL, 'multicurrency', 'Deprecated constant intended to show an indirect currency-rate input field on the multicurrency rate entry page; the code path is commented out.', 'The only executable reference is inside a commented-out PHP block (/* ... */) in multicurrency/multicurrency_rate.php:338, and an explicit inline comment at line 319 states ''MULTICURRENCY_USE_RATE_INDIRECT <-- is deprecated''. The active counterpart is MULTICURRENCY_USE_RATE_DIRECT.', 'Has no effect: the code that would read this constant is commented out, so setting it does nothing in the current codebase.', 'Deprecated; no longer has an effect (per inline comment ''is deprecated'').', 1, 0, NULL, 1, '42fe18e8b19a6b25d9d9d5506f91c67bde65574242256c92c72db54dbed90942', 'v2', '2026-07-24T07:05:23+00:00', '["multicurrency/multicurrency_rate.php:319: * MULTICURRENCY_USE_RATE_INDIRECT <-- is deprecated", "multicurrency/multicurrency_rate.php:338|check|/* if (getDolGlobalString(''MULTICURRENCY_USE_RATE_INDIRECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MULTICURRENCY_USE_RATE_ON_DOCUMENT_DATE', 'bool', NULL, 'multicurrency', 'Controls whether the exchange rate closest to the document date is used instead of the current rate.', 'Set via admin/multicurrency.php:222 as a select array value. Checked at multicurrency/class/multicurrency.class.php:552 (`if (getDolGlobalString(''MULTICURRENCY_USE_RATE_ON_DOCUMENT_DATE'') && !empty($date_document))`) and :564. 3 occurrences across 2 files.', 'When unset, the current exchange rate is applied to documents. When set, the system looks up the rate that was in effect on the document''s date.', 'Integer/string: truthy = use rate on document date; 0 or unset = use current rate.', 0, 0, 'admin/multicurrency.php', 1, '01afef9f104006c65bc9a3f85724716460045239646a695803ae99f2d243d26e', 'v2', '2026-04-21T11:16:15+00:00', '["admin/multicurrency.php:222|read|print $form->selectarray(\"MULTICURRENCY_USE_RATE_ON_DOCUMENT_DATE\", $arrval, getDolGlobalInt(\"MULTICURRENCY_USE_RATE_ON_DOCUMENT_DATE\"));", "multicurrency/class/multicurrency.class.php:552|check|if (getDolGlobalString(''MULTICURRENCY_USE_RATE_ON_DOCUMENT_DATE'') && !empty($date_document)) {\t// Use last known rate compared to document date", "multicurrency/class/multicurrency.class.php:564|check|if (getDolGlobalString(''MULTICURRENCY_USE_RATE_ON_DOCUMENT_DATE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYDATA_AADE_KEY', 'string', NULL, 'admin', 'Stores the AADE (Greek tax authority) API subscription key for MyData e-invoicing integration.', 'Written at admin/company.php:281 from POST ''MYDATA_AADE_KEY''. Displayed as a password input at admin/company.php:920. Managed via the admin company setup UI.', 'Changing this value updates the AADE API key used to authenticate MyData e-invoicing submissions.', 'String representing the AADE API subscription key; empty = no MyData key configured', 0, 0, 'admin/company.php|admin/company.php', 1, 'f89182567ff1c6dd7ba57742a1b1a42ea30d4a7b052856fd2f05f0443fefb0c0', 'v2', '2026-04-21T13:29:58+00:00', '["admin/company.php:281|write|dolibarr_set_const($db, \"MYDATA_AADE_KEY\", GETPOST(\"MYDATA_AADE_KEY\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/company.php:920|read|print ''<input class=\"minwidth300\" type=\"password\" name=\"MYDATA_AADE_KEY\" value=\"''.getDolGlobalString(''MYDATA_AADE_KEY'').''\"'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYDATA_AADE_USER', 'string', NULL, 'admin', 'Stores the AADE (Greek tax authority) API username for MyData e-invoicing integration.', 'Written at admin/company.php:280 from POST ''MYDATA_AADE_USER''. Displayed as a text input at admin/company.php:915. Managed via the admin company setup UI.', 'Changing this value updates the AADE API username used for MyData e-invoicing submissions to the Greek tax authority.', 'String representing the AADE API username; empty = no MyData user configured', 0, 0, 'admin/company.php|admin/company.php', 1, '56008c9f38aefe4d9608534e9ccb0f7040c5a10c7962d98580e53ac578a1eec2', 'v2', '2026-04-21T13:29:58+00:00', '["admin/company.php:280|write|dolibarr_set_const($db, \"MYDATA_AADE_USER\", GETPOST(\"MYDATA_AADE_USER\", ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/company.php:915|read|print ''<input class=\"minwidth300\" type=\"text\" name=\"MYDATA_AADE_USER\" value=\"''.getDolGlobalString(''MYDATA_AADE_USER'').''\"'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYMODULE_DRAFT_WATERMARK', 'string', NULL, 'modulebuilder', 'Text watermark printed on the PDF of a draft-status document generated by the ModuleBuilder template object.', 'Read in the generated PDF class _pagehead() at modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:949-950, where it gates a call to pdf_watermark() when the object status is STATUS_DRAFT.', 'When set, its string value is drawn as a watermark on the PDF while the document is in draft status; when empty, no watermark is added.', 'Any non-empty string is used verbatim as the watermark text (escaped via dol_escape_htmltag).', 1, 0, NULL, 1, 'c49109728d5d64cb3ff84741637a766f32a60f37ae58803c9c05e71de2433611', 'v2', '2026-07-24T07:05:23+00:00', '["pdf_standard_myobject.modules.php:949: if (getDolGlobalString(''MYMODULE_DRAFT_WATERMARK'') && $object->status == $object::STATUS_DRAFT) {", "pdf_standard_myobject.modules.php:950: pdf_watermark($pdf, $outputlangs, ..., getDolGlobalString(''MYMODULE_DRAFT_WATERMARK''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYMODULE_ENABLE_PERMISSION_CHECK', 'bool', NULL, 'modulebuilder', 'Enables permission checks in ModuleBuilder-generated module template pages (card, list, agenda, contact, document, note, stats).', 'Read via getDolGlobalInt(''MYMODULE_ENABLE_PERMISSION_CHECK'') in ModuleBuilder templates: modulebuilder/template/myobject_card.php:148, myobject_list.php:215, myobject_contact.php:95, myobject_document.php:143, myobject_note.php:120, myobject_agenda.php:153 and stats/myobject_index.php:93.', 'When enabled in a generated module''s template code, the generated pages perform additional permission checks ($enablepermissioncheck).', NULL, 0, 0, NULL, 1, '44130be2e133fdff7c9b3f97e4459d3acaff5557c919e149240bc71c4b452be8', 'v2', '2026-07-24T06:41:12+00:00', '["$enablepermissioncheck = getDolGlobalInt(''MYMODULE_ENABLE_PERMISSION_CHECK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYMODULE_MYOBJECT_ADDON', 'string', NULL, 'modulebuilder', 'Specifies the numbering module class to use for MyObject reference generation in the module builder template.', 'Checked and read in modulebuilder/template/class/myobject.class.php at lines 1140–1148; defaults to ''mod_myobject_standard'' when unset. Also referenced in modulebuilder/template/core/modules/modMyModule.class.php:447–448 for the module class and path configuration.', 'Changing this value switches the active numbering module for MyObject; if unset, the system falls back to ''mod_myobject_standard''.', 'A class name string matching a numbering module under /core/modules/mymodule/, e.g. ''mod_myobject_standard'' or ''mod_myobject_advanced''.', 1, 0, NULL, 1, 'ffb5719b9456784bf6f16c103cbf273fe878ed67f200b1cac9a4cdddf3a230c4', 'v2', '2026-04-21T11:16:15+00:00', '["modulebuilder/template/class/myobject.class.php:1140|check|if (!getDolGlobalString(''MYMODULE_MYOBJECT_ADDON'')) {", "modulebuilder/template/class/myobject.class.php:1141|write|$conf->global->MYMODULE_MYOBJECT_ADDON = ''mod_myobject_standard'';", "modulebuilder/template/class/myobject.class.php:1147|read|$file = getDolGlobalString(''MYMODULE_MYOBJECT_ADDON'').\".php\";", "modulebuilder/template/core/modules/modMyModule.class.php:447|read|''class''=>(!getDolGlobalString(''MYMODULE_MYOBJECT_ADDON'') ? ''mod_myobject_standard'' : getDolGlobalString(''MYMODULE_MYOBJECT_ADDON'')),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYMODULE_MYOBJECT_ADDON_PDF_ODT_PATH', 'string', NULL, 'modulebuilder', 'Template placeholder constant (in modulebuilder''s ODT document-generator skeleton) meant to hold a custom directory path for ODT model files, to be renamed per generated module/object.', 'In modulebuilder/template/core/modules/mymodule/doc/doc_generic_myobject_odt.modules.php:128, the info() method reads and trims this constant''s value into $odtPath, and the surrounding admin form lets a user set/save it via a ''setModuleOptions'' POST action with param1=''MYMODULE_MYOBJECT_ADDON_PDF_ODT_PATH''.', 'This is boilerplate code from the Module Builder template, generated modules replace MYMODULE_MYOBJECT with the real module/object name; setting it points the ODT document generator at a custom directory for ODT template files.', 'String: a filesystem directory path where custom ODT model files are stored.', 0, 0, NULL, 1, '2b66b503337acf71d05ca04d32110dafa602336d972478e735cc1b13c35f080c', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/template/core/modules/mymodule/doc/doc_generic_myobject_odt.modules.php:128|read|$odtPath = trim(getDolGlobalString(''MYMODULE_MYOBJECT_ADDON_PDF_ODT_PATH''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYMODULE_MYOBJECT_ADVANCED_MASK', 'string', NULL, 'modulebuilder', 'Numbering mask/template string used by the ModuleBuilder ''advanced'' numbering model to generate references for MyObject.', 'Read/written via an admin form input (name="maskvalue") in mod_myobject_advanced.php:94, and consumed in getNextValue() at mod_myobject_advanced.php:145 to compute the next reference; if empty, numbering fails with error ''NotConfigured''.', 'Setting this defines the reference mask pattern used to generate new MyObject numbers; leaving it empty disables numbering for the object (getNextValue returns 0 with error NotConfigured).', 'Any mask string following Dolibarr''s generic mask syntax (documented via GenericMaskCodes* translation strings); empty/unset = not configured.', 0, 0, NULL, 1, '28607ebdbc51ed0c1c0350cf5a8880594c462a809c98034f84314ae8acb27857', 'v2', '2026-07-24T07:05:23+00:00', '["mod_myobject_advanced.php:94: name=\"maskvalue\" value=\".getDolGlobalString(''MYMODULE_MYOBJECT_ADVANCED_MASK'').\"", "mod_myobject_advanced.php:145: $mask = getDolGlobalString(''MYMODULE_MYOBJECT_ADVANCED_MASK''); if (!$mask) { $this->error = ''NotConfigured''; return 0; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYOBJECT_ADDON_PDF', 'string', NULL, 'modulebuilder', 'ModuleBuilder template placeholder constant naming the default PDF model used to generate documents for a generated ''MyObject'' custom object.', 'Read in modulebuilder/template/class/myobject.class.php:1218 (`$modele = getDolGlobalString(''MYOBJECT_ADDON_PDF'', ''standard_myobject'')`), part of the ModuleBuilder scaffold code copied into new custom modules; the real constant name changes once a developer renames MyObject/MyModule.', 'Only relevant inside module-builder-generated boilerplate; selects which PDF document model class is used by default for the scaffolded object''s generateDocument() method until the developer customizes it.', 'String, default fallback is the literal ''standard_myobject'' model name.', 1, 0, NULL, 1, '0919e4ff4da3d77389d55543bc05e11988122336b2d9553e64d0af6374a8b2b6', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/template/class/myobject.class.php:1218|read|$modele = getDolGlobalString(''MYOBJECT_ADDON_PDF'', ''standard_myobject'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYOBJECT_DRAFT_WATERMARK', 'string', NULL, 'modulebuilder', 'Template placeholder constant (in modulebuilder''s PDF generator skeleton) that sets watermark text printed on draft-status PDF documents for a generated module''s object.', 'In modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:191-192, when set and the object''s status equals STATUS_DRAFT, $this->watermark is assigned this constant''s string value, which is later used when rendering the PDF.', 'In generated modules (after renaming MYOBJECT to the real object name), setting it prints the given text as a watermark on PDF documents while the related object is still in draft status.', 'String: watermark text to display on draft PDFs.', 0, 0, NULL, 1, '097677d4a1959efbdf5be63c2bc3cededb514caf6724fbe71c13761b5e1f14cb', 'v2', '2026-07-24T07:05:23+00:00', '["modulebuilder/template/core/modules/mymodule/doc/pdf_standard_myobject.modules.php:191|check|if (getDolGlobalString(''MYOBJECT_DRAFT_WATERMARK'') && $object->status == $object::STATUS_DRAFT) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MYSQL_OLD_OPTION_DISABLE_FK', 'bool', NULL, 'admin', 'Shows an extra checkbox on the database export tool page to include commands disabling foreign-key checks in the SQL dump, for compatibility with old MySQL export options.', 'Checked twice in admin/tools/dolibarr_export.php (lines 261 and 382): if (getDolGlobalString(''MYSQL_OLD_OPTION_DISABLE_FK'')) prints a checked ''disable_fk''/''nobin_disable_fk'' checkbox with a warning tooltip (CommandsToDisableForeignKeysForImportWarning). No admin UI write (set_const) for this constant was found; it is only ever read to conditionally reveal the checkbox.', 'When enabled, the DB export screen exposes a checkbox (pre-checked) to add MySQL commands disabling foreign key checks around the dump/import; when disabled (default), that option/checkbox is hidden entirely.', 'Boolean: 1/true reveals the ''disable foreign keys'' export checkbox.', 1, 0, 'admin/tools/dolibarr_export.php|admin/tools/dolibarr_export.php', 1, '9b8795a0b9292d7ea513a575ff7fa2f15152e95c26f2c3d0ef0501627d996fbb', 'v2', '2026-07-24T07:05:23+00:00', '["admin/tools/dolibarr_export.php:261: if (getDolGlobalString(''MYSQL_OLD_OPTION_DISABLE_FK'')) { print ''<input type=\"checkbox\" name=\"disable_fk\" value=\"yes\" id=\"checkbox_disable_fk\" checked>'';", "admin/tools/dolibarr_export.php:382: if (getDolGlobalString(''MYSQL_OLD_OPTION_DISABLE_FK'')) { print ''<input type=\"checkbox\" name=\"nobin_disable_fk\" value=\"yes\" id=\"checkbox_disable_fk\" checked />'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('MY_SETUP_PARAM', 'string', NULL, 'product', 'Not a real constant: a placeholder name used in PHPDoc examples for the ''enabled'' key of $fields array definitions in ORM classes.', 'Appears only inside PHPDoc comment blocks (e.g. asset/class/assetdepreciationoptions.class.php:44, core/class/defaultvalues.class.php:56) illustrating how a developer could write "''enabled'' is a condition when the field must be managed (Example: 1 or ''getDolGlobalString(\"MY_SETUP_PARAM\")'')". It is never actually read via getDolGlobal* in executable code.', 'Setting this constant has no effect anywhere in the codebase; it is purely documentation boilerplate copy-pasted across many entity classes.', 'N/A - documentation placeholder, not a functional constant.', 1, 0, NULL, 1, '625c85d887f8c870b3a0f769967d7d56389c33ce7611556663c69586eb265940', 'v2', '2026-07-24T07:05:23+00:00', '["asset/class/assetdepreciationoptions.class.php:44: *  ''enabled'' is a condition when the field must be managed (Example: 1 or ''getDolGlobalString(\"MY_SETUP_PARAM\")''", "core/class/defaultvalues.class.php:56: *  ''enabled'' is a condition when the field must be managed (Example: 1 or ''getDolGlobalString(\"MY_SETUP_PARAM\")''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NBLINES_TO_DUPLICATE_TOTAL_TIMESPENT_ON_TOP', 'string', NULL, 'projet', 'Minimum number of task lines in a per-week/per-day timesheet before a duplicate ''Total'' summary row is also shown at the top of the list.', 'Used identically in projet/activity/perweek.php:720 and projet/activity/perday.php:697: if ($conf->use_javascript_ajax && count($tasksarray) >= getDolGlobalInt(''NBLINES_TO_DUPLICATE_TOTAL_TIMESPENT_ON_TOP'', 10)) prints a repeated total row.', 'Lowering the threshold makes the duplicated top total row appear with fewer task lines; raising it requires more lines before the row is duplicated at the top (only relevant when javascript/ajax is enabled).', 'Integer, line-count threshold; default 10 when unset (getDolGlobalInt(..., 10)).', 1, 0, NULL, 1, 'b261ef0b56780159f3410b29f11e445464addda06982928d175b15fe2a9345e5', 'v2', '2026-07-24T07:05:23+00:00', '["projet/activity/perweek.php:720: if ($conf->use_javascript_ajax && count($tasksarray) >= getDolGlobalInt(''NBLINES_TO_DUPLICATE_TOTAL_TIMESPENT_ON_TOP'', 10)) {", "projet/activity/perday.php:697: if ($conf->use_javascript_ajax && count($tasksarray) >= getDolGlobalInt(''NBLINES_TO_DUPLICATE_TOTAL_TIMESPENT_ON_TOP'', 10)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NB_REC_FACT_GEN_BY_CALL', 'string', NULL, 'fourn', 'Limits the number of recurring supplier invoices generated per call of the recurring-invoice generation routine.', 'In fourn/class/fournisseur.facture-rec.class.php:1384-1385, createRecurringInvoices() applies $this->db->plimit(getDolGlobalInt(''NB_REC_FACT_GEN_BY_CALL'')) to the SQL SELECT of due recurring supplier invoices when the constant is set.', 'Setting it caps how many recurring supplier invoices (facture_fourn_rec rows due for generation) are processed in a single execution of the cron/generation routine, useful to batch large runs.', 'Integer; used directly as a SQL LIMIT value when > 0 (falsy/0/unset means no limit applied).', 1, 0, NULL, 1, '3061f2ee424822e28c1d35cf33776bfef4782581fb575c3889c1387d9f4857ce', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/class/fournisseur.facture-rec.class.php:1384: if (getDolGlobalInt(''NB_REC_FACT_GEN_BY_CALL'')) {", "fourn/class/fournisseur.facture-rec.class.php:1385: $sql .= $this->db->plimit(getDolGlobalInt(''NB_REC_FACT_GEN_BY_CALL''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NDF_CC_EMAILS', 'string', NULL, 'expensereport', 'Email address(es) placed in CC when an expense-report notification email is sent, and used as fallback recipient if the author has no email.', 'Read in expensereport/card.php:669 into $emailCC; if the primary recipient ($emailTo, the report author) has no email set, $emailCC is used as $emailTo instead.', 'Setting it adds the given address(es) as CC on expense report notification emails and provides a fallback destination when the author lacks an email address.', 'Exact behavior unclear from code alone regarding multi-address format (not shown in code).', 0, 0, NULL, 1, '8d2378ceedb0cd0fe8d7b87e585842fde2aa319b9d9836992b44f97a4172363c', 'v2', '2026-07-24T07:05:23+00:00', '["expensereport/card.php:669|read|$emailCC = getDolGlobalString(''NDF_CC_EMAILS'');", "expensereport/card.php: if (empty($emailTo)) { $emailTo = $emailCC; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NDF_EXPLODE_CHAR', 'string', NULL, 'core', 'Separator character used between segments (username, prefix+number, date) when building the legacy expense report reference.', 'Read in core/modules/expensereport/mod_expensereport_jade.php:141, only inside the EXPENSEREPORT_USE_OLD_NUMBERING_RULE branch: $expld_car = (!getDolGlobalString(''NDF_EXPLODE_CHAR'')) ? ''-'' : $conf->global->NDF_EXPLODE_CHAR; used to join username, prefix+number and date in the generated ref.', 'Changing this value changes the separator character used between the username, prefix/number and date segments of legacy-format expense report references; only takes effect when EXPENSEREPORT_USE_OLD_NUMBERING_RULE is enabled.', 'Any character string used as separator; default ''-'' if unset.', 1, 0, NULL, 1, '69ce56ead0dbcf56faeb0cff676a8326070416eb36d55cd52dc31d63c55dbc56', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expensereport/mod_expensereport_jade.php:141: $expld_car = (!getDolGlobalString(''NDF_EXPLODE_CHAR'')) ? \"-\" : $conf->global->NDF_EXPLODE_CHAR;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NDF_NUM_CAR_REF', 'string', NULL, 'core', 'Minimum digit-width (zero-padding length) of the numeric counter used when building the legacy expense report reference.', 'Read in core/modules/expensereport/mod_expensereport_jade.php:142, only inside the EXPENSEREPORT_USE_OLD_NUMBERING_RULE branch: $num_car = (!getDolGlobalString(''NDF_NUM_CAR_REF'')) ? ''5'' : $conf->global->NDF_NUM_CAR_REF; used to left-pad the MAX(ref_number_int)+1 counter with zeros.', 'Changing this value changes how many digits the numeric counter in a legacy-format expense report reference is zero-padded to; only takes effect when EXPENSEREPORT_USE_OLD_NUMBERING_RULE is enabled.', 'Integer (as string) digit count; default ''5'' if unset.', 1, 0, NULL, 1, 'a26193965bc53f45d344ec9457f185d8f97dec9e46aea4fdb6cb6449a6aa5244', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expensereport/mod_expensereport_jade.php:142: $num_car = (!getDolGlobalString(''NDF_NUM_CAR_REF'')) ? \"5\" : $conf->global->NDF_NUM_CAR_REF;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE', 'bool', NULL, 'admin', 'Controls whether the confirmation message is disabled when sending manual notification emails.', 'Written from admin/notification.php:109 via dolibarr_set_const() from GETPOST(''notif_disable'', ''alphawithlgt'') when the admin saves the Notification module setup form.', 'Changing it toggles whether a confirmation message is shown/skipped for manual email notifications; type bool suggests a 0/1 toggle.', 'Not specified beyond the bool type and ''notif_disable'' POST field name; likely 0/1.', 0, 0, 'admin/notification.php', 1, '79f156f54a1cf3c005f03fa41a980a8673f4bfeeb5fa27231b58fcd09e1f8ab1', 'v2', '2026-07-24T07:05:23+00:00', '["admin/notification.php:109|write|$result = dolibarr_set_const($db, \"NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE\", GETPOST(\"notif_disable\", \"alphawithlgt\"), ''chaine'', 0, '''', $conf->entity);"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_CONTACT', 'bool', NULL, 'admin', 'Disables the notification confirmation message/entry for contacts (''tocontact'' type) in the notify module.', 'Set via admin/notification.php:240 (labeled ''NotificationDisableConfirmMessageContact'') and read in core/class/notify.class.php:216 inside confirmMessage(), where matching ''tocontact'' entries are removed from the notification list.', 'Setting it to true suppresses the confirmation-message listing of contact notification recipients when an action triggers a notification.', 'Boolean: 0=No (show), 1=Yes (disable/hide), per the admin UI''s selectarray with array(''0''=>No,''1''=>Yes).', 0, 0, 'admin/notification.php', 1, '598f95b858288ab898606d44229320f4c819df9e98a6f67fd52e972c471e6628', 'v2', '2026-07-24T07:05:23+00:00', '["admin/notification.php:240|read|print $form->selectarray(\"NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_CONTACT\", $arrval, getDolGlobalString(''NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_CONTACT''));", "core/class/notify.class.php:216|check|if (getDolGlobalString(''NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_CONTACT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_FIX', 'bool', NULL, 'admin', 'Disables the notification confirmation message/entry for fixed email addresses (''tofixedemail'' type) in the notify module.', 'Set via admin/notification.php:253 (labeled ''NotificationDisableConfirmMessageFix'') and read in core/class/notify.class.php:224 inside confirmMessage(), where matching ''tofixedemail'' entries are removed from the notification list.', 'Setting it to true suppresses the confirmation-message listing of fixed-email notification recipients when an action triggers a notification.', 'Boolean: 0=No (show), 1=Yes (disable/hide), per the admin UI''s selectarray with array(''0''=>No,''1''=>Yes).', 0, 0, 'admin/notification.php', 1, 'b33cbb7c368180ba89a45b77b2ccd30bdbc293dc3d9a977ca17e6adf88ee96a9', 'v2', '2026-07-24T07:05:23+00:00', '["admin/notification.php:253|read|print $form->selectarray(\"NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_FIX\", $arrval, getDolGlobalString(''NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_FIX''));", "core/class/notify.class.php:224|check|if (getDolGlobalString(''NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_FIX'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_USER', 'bool', NULL, 'admin', 'Disables the notification confirmation message/entry for internal users (''touser'' type) in the notify module.', 'Set via admin/notification.php:227 (labeled ''NotificationDisableConfirmMessageUser'' in the UI) and read in core/class/notify.class.php:208 inside confirmMessage(), where matching ''touser'' entries are removed from the notification list shown to the user.', 'Setting it to true suppresses the confirmation-message listing of internal-user notification recipients when an action triggers a notification.', 'Boolean: 0=No (show), 1=Yes (disable/hide), per the admin UI''s selectarray with array(''0''=>No,''1''=>Yes).', 0, 0, 'admin/notification.php', 1, '5c58a7c39b81a043792aef9691fb81ae28ce8aadcf7ac1788aa23df1472fc5ca', 'v2', '2026-07-24T07:05:23+00:00', '["admin/notification.php:227|read|print $form->selectarray(\"NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_USER\", $arrval, getDolGlobalString(''NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_USER''));", "core/class/notify.class.php:208|check|if (getDolGlobalString(''NOTIFICATION_EMAIL_DISABLE_CONFIRM_MESSAGE_USER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NOTIFICATION_EMAIL_FROM', 'string', NULL, 'admin', 'Specifies the sender email address used for notification emails dispatched by the notification system.', 'Written in admin/notification.php:105 and validated as a proper email at :214. Read in core/class/notify.class.php:665 as the $from address when sending notifications.', 'Setting a valid email address overrides the default sender for all notification emails. An invalid address is rejected by the admin UI; leaving empty uses the system default.', 'Valid email address string; empty = system default sender used', 0, 0, 'admin/notification.php|admin/notification.php|admin/notification.php', 1, '68d39b0fc27909c635bdfa8cb9ab907cf897bba769e234ba7a1cbc8ac8bb84f3', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/notify.class.php:665|read|$from = getDolGlobalString(''NOTIFICATION_EMAIL_FROM'');", "admin/notification.php:105|write|$result = dolibarr_set_const($db, \"NOTIFICATION_EMAIL_FROM\", GETPOST(\"email_from\", \"alphawithlgt\"), ''chaine'', 0, '''', $conf->entity);", "admin/notification.php:214|check|if (getDolGlobalString(''NOTIFICATION_EMAIL_FROM'') && !isValidEmail(getDolGlobalString(''NOTIFICATION_EMAIL_FROM''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NOTIFICATION_FIXEDEMAIL_', 'string', NULL, 'admin', 'Per-event, per-threshold fixed notification email list, dynamic constant NOTIFICATION_FIXEDEMAIL_<eventcode>_THRESHOLD_HIGHER_<amount> storing comma-separated recipient emails for a notification triggered when an amount exceeds <amount>.', 'Deleted by admin/notification.php:143 (dolibarr_del_const) when a threshold row is removed, and written/looped over in admin/notification.php:145/150/478/482/513 and core/class/notify.class.php:575/579/1078, which iterate $conf->global entries matching the regex NOTIFICATION_FIXEDEMAIL_<code>_THRESHOLD_HIGHER_(.*) to find configured fixed-email notifications for each triggering event.', 'Setting/removing entries changes which fixed email addresses receive notifications for a given event code once the associated amount threshold is exceeded; value can also use special keywords instead of a literal email.', 'Comma-separated list of email addresses, or the special keywords ''__SUPERVISOREMAIL__'' or ''__AUTHOREMAIL__'' (per admin/notification.php around line 490, values compared against these literals).', 0, 0, 'admin/notification.php', 1, 'fa3421c5cf1dbf20b62699305d91e1ed908cb1881768b6e07c347500cabb56a2', 'v2', '2026-07-24T07:05:23+00:00', '["admin/notification.php:143|write|dolibarr_del_const($db, ''NOTIFICATION_FIXEDEMAIL_''.$reg[1].''_THRESHOLD_HIGHER_''.$reg[2], $conf->entity);", "core/class/notify.class.php:575: if ($val == '''' || !preg_match(''/^NOTIFICATION_FIXEDEMAIL_''.$notifcode.''_THRESHOLD_HIGHER_(.*)$/'', $key, $reg)) {", "admin/notification.php:489: if (!empty($valuedet) && $valuedet != ''__SUPERVISOREMAIL__'' && $valuedet != ''__AUTHOREMAIL__'' && !isValidEmail($valuedet, 1)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('NW_RECEIPTNUMBERFORMAT', 'string', NULL, 'compta', 'Switches the bank statement/receipt number input on the bank entries reconciliation screen from a guided placeholder-based text field to a plain free-text input with autocomplete list.', 'Checked (as int) in compta/bank/bankentries_list.php:970: when set, a simple ''<input>'' with a datalist (num_releve_list) is shown for entering the receipt number; when unset, a more guided input with a computed YYYY/MM placeholder format is shown instead (lines 974-980).', 'When set, users get a plain free-text/autocomplete field for the reconciliation receipt number instead of the default placeholder-guided format input.', 'Not set/0 (default): guided placeholder-format input shown. Truthy int: plain free-text input with datalist shown instead.', 1, 0, NULL, 1, '199d2bcc04649fc92064e1903a3aa75a1098a500d2a02ffc16f26c5a0355e646', 'v2', '2026-07-24T07:05:23+00:00', '["compta/bank/bankentries_list.php:970|check|if (getDolGlobalInt(''NW_RECEIPTNUMBERFORMAT'')) {", "compta/bank/bankentries_list.php:971-972|code|print ''<strong>''.$langs->trans(\"InputReceiptNumber\").''</strong>: ''; print ''<input class=\"flat width100 center\" id=\"num_releve\" list=\"num_releve_list\" ...>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_', 'string', NULL, 'core', 'Family of dynamic constants prefixed OAUTH_ storing OAuth2 provider credentials (ID, SECRET, URLCALLBACK, SCOPE, TENANT) keyed by provider name.', 'Read dynamically across admin/oauthlogintokens.php (lines 170-172, 186), admin/emailcollector_card.php (lines 457-459), and admin/oauth.php:451 using patterns like OAUTH_{PROVIDER}_ID, OAUTH_{PROVIDER}_SECRET, OAUTH_{PROVIDER}_URLCALLBACK, OAUTH_{PROVIDER}_SCOPE, OAUTH_{PROVIDER}_TENANT. Stored and displayed via the admin OAuth configuration UI.', 'Setting the correct ID, SECRET, and URLCALLBACK constants for a provider enables OAuth2 authentication and token management for that service; incorrect values will cause authentication failures.', 'String; values are provider-specific client IDs, secrets, callback URLs, scope lists, and tenant IDs supplied by the OAuth2 provider.', 0, 0, 'admin/emailcollector_card.php|admin/emailcollector_card.php|admin/emailcollector_card.php|admin/oauthlogintokens.php|admin/oauthlogintokens.php|admin/oauthlogintokens.php|admin/oauthlogintokens.php|admin/oauth.php', 1, '45b53d6cf3a4c5788e55bd9014a1f9c904bd252b49433dfd71a58e560afe81c0', 'v2', '2026-04-21T13:29:58+00:00', '["admin/oauthlogintokens.php:170|read|getDolGlobalString(''OAUTH_''.$keyforoauthservice.''_ID''),", "admin/oauthlogintokens.php:171|read|getDolGlobalString(''OAUTH_''.$keyforoauthservice.''_SECRET''),", "admin/oauthlogintokens.php:186|read|$scopes = explode('','', getDolGlobalString(''OAUTH_''.strtoupper($tmp[0]).(empty($tmp[1]) ? '''' : ''-''.$tmp[1]).''_SCOPE''));", "admin/oauth.php:451|read|print ''<td><input type=\"text\" size=\"100\" id=\"OAUTH_''.$keybeforeprovider.($keyforprovider ? ''-''.$keyforprovider : '''').''_TENANT\" name=\"OAUTH_''.$keybeforeprovider.($keyforprovider ? ''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_ADD_SCOPE_AND_TENANT_IN_REFRESH_MESSAGE', 'string', NULL, 'core', 'Adds scope and tenant information to the OAuth2 token refresh message for debugging purposes.', 'Checked at includes/OAuth/OAuth2/Service/AbstractService.php:223. The payload also shows the activation pattern at line 222 as a commented example: ''//global $conf; $conf->global->OAUTH_ADD_SCOPE_AND_TENANT_IN_REFRESH_MESSAGE = 1;'', indicating it is set directly in code for debugging.', 'Enabling this constant enriches OAuth2 refresh-related messages with scope and tenant details, aiding diagnostics of token refresh failures.', 'Integer 1 to enable; unset or 0 to disable.', 1, 0, NULL, 1, '40fdc5003884394a6825663718a35c47c711bedf8eff9c9956cd070493a9514c', 'v2', '2026-04-21T13:29:58+00:00', '["includes/OAuth/OAuth2/Service/AbstractService.php:222  //global $conf; $conf->global->OAUTH_ADD_SCOPE_AND_TENANT_IN_REFRESH_MESSAGE = 1;", "includes/OAuth/OAuth2/Service/AbstractService.php:223|check|if (getDolGlobalString(''OAUTH_ADD_SCOPE_AND_TENANT_IN_REFRESH_MESSAGE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_DEBUG', 'string', NULL, 'core', 'Enables debug logging for OAuth HTTP client requests (cURL and stream clients).', 'Checked in includes/OAuth/Common/Http/Client/CurlClient.php:126 and includes/OAuth/Common/Http/Client/StreamClient.php:93, with a function_exists guard ensuring safety outside full Dolibarr context.', 'Enabling this activates OAuth request debug output; disabling it suppresses debug logging.', 'truthy = enable OAuth debug logging; empty/not set = no debug output', 1, 0, NULL, 1, 'e466f464fc0efda0490d00b527245a744f0833f9a1b45156af833b137a4adec2', 'v2', '2026-04-21T13:29:58+00:00', '["includes/OAuth/Common/Http/Client/CurlClient.php:126|check|if (function_exists(''getDolGlobalString'') && getDolGlobalString(''OAUTH_DEBUG'')) {", "includes/OAuth/Common/Http/Client/StreamClient.php:93|check|if (function_exists(''getDolGlobalString'') && getDolGlobalString(''OAUTH_DEBUG'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_GOOGLE_FORCE_PROMPT_ON_LOGIN', 'string', NULL, 'core', 'Controls the OAuth2 ''approval_prompt'' parameter sent to Google when a user logs in to Dolibarr via Google OAuth.', 'core/modules/oauth/google_oauthcallback.php:199 reads it with a default of ''auto'': `$approval_prompt = getDolGlobalString(''OAUTH_GOOGLE_FORCE_PROMPT_ON_LOGIN'', ''auto''); // Can be ''force''`, then calls `$apiService->setApprouvalPrompt($approval_prompt)`. The comment above explains a refresh token is only provided by Google if the prompt is actually shown.', 'Setting it to ''force'' makes Google always re-display the consent/approval screen on login (needed to guarantee a refresh token is issued); default ''auto'' lets Google decide whether to skip the prompt for already-approved users.', '''auto'' (default) or ''force'' (forces the consent prompt every login), per inline comment ''// Can be \''force\''''.', 1, 0, NULL, 1, 'aed609d95c20306bfcfc6d61db6903ef286fbd15a55397a94e788bac86801169', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/oauth/google_oauthcallback.php:199: $approval_prompt = getDolGlobalString(''OAUTH_GOOGLE_FORCE_PROMPT_ON_LOGIN'', ''auto'');\t// Can be ''force''", "core/modules/oauth/google_oauthcallback.php:197: // Set approval_prompt. Note: A refresh token will be provided only if prompt is done."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_GOOGLE_ID', 'string', NULL, 'core', 'OAuth2 client ID used by the Google Cloud Print (printgcp) printing driver.', 'Read in core/modules/printing/printgcp.modules.php:114 into $this->google_id, used to configure the OAuth request when the ''oauth'' module is enabled; the driver''s $this->conf[] array declares configurable fields shown in the printing driver setup page (printing/admin/printing.php).', 'Setting it (together with OAUTH_GOOGLE_SECRET) configures which Google OAuth application is used for the Google Cloud Print integration; without it, or without the oauth module enabled, printing via this driver cannot authenticate.', 'String: Google OAuth2 client ID.', 0, 0, NULL, 1, '380e67e44bac9faeaf9be2b6692d70c1d3409dde3783f70ff4491c5c9a6a7767', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/printing/printgcp.modules.php:114: $this->google_id = getDolGlobalString(''OAUTH_GOOGLE_ID'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_GOOGLE_SECRET', 'string', NULL, 'core', 'OAuth2 client secret used by the Google Cloud Print (printgcp) printing driver.', 'Read in core/modules/printing/printgcp.modules.php:115 into $this->google_secret, used alongside OAUTH_GOOGLE_ID to configure OAuth for the printgcp driver, exposed via the driver''s printing setup page (printing/admin/printing.php).', 'Setting it (with OAUTH_GOOGLE_ID) configures the OAuth client secret for the Google Cloud Print integration; missing/incorrect value prevents successful OAuth authentication for that print driver.', 'String: Google OAuth2 client secret.', 0, 0, NULL, 1, 'de1d9f294009c43c23fc0e5e9fc11bf9bf1adcea676c58b4a73114c4a69b4e3d', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/printing/printgcp.modules.php:115: $this->google_secret = getDolGlobalString(''OAUTH_GOOGLE_SECRET'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_MICROSOFT', 'string', NULL, 'core', 'Referenced as a base name for building per-provider OAuth Microsoft config keys (e.g. a commented-out ''_TENANT'' suffixed lookup); the actual live constants are OAUTH_MICROSOFT_NAME/_ID/_SECRET (and OAUTH_MICROSOFT2/3 variants) managed via admin/oauth.php.', 'The only direct read of the bare name OAUTH_MICROSOFT is a commented-out line in includes/OAuth/Common/Storage/DoliStorage.php:399 building a ''_TENANT'' suffixed key; core/lib/oauth.lib.php and admin/oauth.php instead define/use OAUTH_MICROSOFT_NAME, OAUTH_MICROSOFT_ID, OAUTH_MICROSOFT_SECRET as the actual admin-configured constants.', 'The bare OAUTH_MICROSOFT constant itself has no active effect since its only reference is commented out; the real Microsoft OAuth configuration is stored under the *_NAME/_ID/_SECRET suffixed constants set via the OAuth admin page.', 'Not directly settable in the UI under this exact name; real values are set as OAUTH_MICROSOFT_NAME/_ID/_SECRET strings via admin/oauth.php.', 0, 0, NULL, 1, '2a29fd6bc71dcff468e602b3fad0fd04e027f2a071df614bb73824310c343a04', 'v2', '2026-07-24T07:05:23+00:00', '["includes/OAuth/Common/Storage/DoliStorage.php:399: //$this->tenant = getDolGlobalString(''OAUTH_MICROSOFT''.($this->keyforprovider ? ''-''.$this->keyforprovider : '''').''_TENANT'');", "core/lib/oauth.lib.php:151: ''OAUTH_MICROSOFT_NAME'',", "admin/oauth.php:197: } elseif ($label == ''OAUTH_MICROSOFT'') {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_SERVICE_SOCIAL_NETWORK', 'string', NULL, 'admin', 'Selects the OAuth service used for social network (Fediverse) integration.', 'Configured via admin/fediverse.php (dolibarr_set_const at line 96). Displayed as a dropdown (selectarray at line 355) and read at line 357 for the currently selected OAuth key.', 'Changing this value switches which OAuth provider is used for social network posting; selecting an unconfigured service will break Fediverse integration.', 'String key corresponding to a configured OAuth service; empty = no OAuth service selected.', 0, 0, 'admin/fediverse.php|admin/fediverse.php|admin/fediverse.php', 1, 'fc47f370c5acaf28ccbe7634533fa9664a1bc43b8cbed376a2d9c21cf93e50c2', 'v2', '2026-04-21T13:50:40+00:00', '["admin/fediverse.php:96|write|dolibarr_set_const($db, \"OAUTH_SERVICE_SOCIAL_NETWORK\", GETPOST(\"OAUTH_SERVICE_SOCIAL_NETWORK\", ''alphanohtml''), ''chaine'', 0, '''', $conf->entity);", "admin/fediverse.php:355|read|print $form->selectarray(''OAUTH_SERVICE_SOCIAL_NETWORK'', $oauthservicesStringKeys, (string) getDolGlobalString(\"OAUTH_SERVICE_SOCIAL_NETWORK\"));", "admin/fediverse.php:357|read|$selectedKey = (string) getDolGlobalString(''OAUTH_SERVICE_SOCIAL_NETWORK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OAUTH_WORDPRESS_AUTHORIZATION_METHOD_QUERY_STRING', 'string', NULL, 'core', 'Selects whether the WordPress OAuth2 service authorizes requests using a query-string token instead of the default HTTP Authorization Bearer header.', 'Used once in includes/OAuth/OAuth2/Service/WordPress.php:76: if empty, the method returns static::AUTHORIZATION_METHOD_HEADER_BEARER (default); if set, it returns static::AUTHORIZATION_METHOD_QUERY_STRING.', 'Enabling it switches the WordPress OAuth2 client from sending the access token as a Bearer Authorization header to sending it as a query string parameter.', 'Boolean-like (empty vs non-empty): empty/unset = AUTHORIZATION_METHOD_HEADER_BEARER; non-empty = AUTHORIZATION_METHOD_QUERY_STRING (constants named verbatim in the code).', 1, 0, NULL, 1, '57c8006c3d688e2ded351d70b4fcc609911e2681db033e0d49ddb001507015f0', 'v2', '2026-07-24T07:05:23+00:00', '["includes/OAuth/OAuth2/Service/WordPress.php:76: return empty($conf->global->OAUTH_WORDPRESS_AUTHORIZATION_METHOD_QUERY_STRING) ? static::AUTHORIZATION_METHOD_HEADER_BEARER : static::AUTHORIZATION_METHOD_QUERY_STRING;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OBJECTELEMENT_FIELDNAME', 'string', NULL, 'core', 'Documents a naming convention: setting a constant named ''<ELEMENT>ELEMENT_FIELDNAME''-style (i.e. OBJECTELEMENT_FIELDNAME, with OBJECTELEMENT replaced by the actual element name) lets CommonObject fall back to a specified field name for extrafields/table linkage when no dedicated table exists.', 'Documented only in a docblock comment in core/class/commonobject.class.php:6531, item 3 of a 3-step resolution order: ''3) If not but a constant $conf->global->OBJECTELEMENT_FIELDNAME is set, we return it (It is better to use the dedicated table).''', 'This is a generic/placeholder name in documentation (OBJECTELEMENT is a stand-in for a real object element name); setting the real per-object constant changes which fieldname CommonObject resolves to when no dedicated table is used, per the docblock.', 'Exact behavior unclear from code alone [SPECULATION] beyond the docblock description; no active code reference to the literal name OBJECTELEMENT_FIELDNAME was found.', 1, 0, NULL, 1, '6a0f8fc2a75965c15ab81b330519695acb402f43dc86ed7b7c3694661f8d6b4f', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commonobject.class.php:6531: * 3) If not but a constant $conf->global->OBJECTELEMENT_FIELDNAME is set, we return it (It is better to use the dedicated table)."]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ODT_ADD_DOLIBARR_ID', 'string', NULL, 'core', 'Embeds the Dolibarr object id and element type as ODT document user-defined metadata.', 'In core/modules/societe/doc/doc_generic_odt.modules.php:442, when saving a generated ODT (not exported as PDF), if this bool is set the code writes $odfHandler->userdefined[''dol_id''] and [''dol_element''] with the object''s id and element type.', 'Setting it to true embeds Dolibarr''s internal object id/element into the ODT file''s custom metadata fields; unset/false skips this metadata.', 'true/1 = add dol_id/dol_element userdefined metadata to the ODT; false/unset (default) = do not add it.', 1, 0, NULL, 1, 'd375d5d62ebabe5349b2e3f558dc7fa2f331ce7cbfda085426dd372f478d5640', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/societe/doc/doc_generic_odt.modules.php:442|check|if (getDolGlobalString(''ODT_ADD_DOLIBARR_ID'')) {", "core/modules/societe/doc/doc_generic_odt.modules.php:443: $odfHandler->userdefined[''dol_id''] = $object->id;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ODT_ENABLE_ALL_TAGS_IN_SUBSTITUTIONS', 'bool', NULL, 'core', 'Adds a special __ALL_TAGS__ substitution variable listing every available ODT/document merge tag and its current value, for use in ODT templates.', 'In core/lib/functions.lib.php:11258, after building the substitution array for document generation, if this constant is set the code builds a string of all `{key} => value` pairs and merges it into the array as `__ALL_TAGS__`, intended ''to list all tags in odt template''.', 'Enabling it lets an ODT template include a special {__ALL_TAGS__} tag that dumps every available substitution tag and its value, useful for discovering available tags when building custom templates.', 'Boolean-like: any truthy value enables generation of the __ALL_TAGS__ debug/discovery substitution.', 1, 0, NULL, 1, '6e2fecf1e627b20aca9f538be0aeda258bc29fb544171b9a88e502af72a45f65', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:11258|check|if (getDolGlobalString(''ODT_ENABLE_ALL_TAGS_IN_SUBSTITUTIONS'')) {", "// to list all tags in odt template", "$tags .= ''{'' . $key . ''} => '' . $value . \"\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_CREDITOR', 'string', NULL, 'stripe', 'Sets the creditor name displayed/used on the online payment pages for PayPal and Stripe.', 'Set via admin UI in paypal/admin/paypal.php:75/249 and stripe/admin/stripe.php:115/404.', 'Changing it changes the creditor text shown on the online payment input forms for both PayPal and Stripe modules.', NULL, 0, 0, 'stripe/admin/stripe.php|paypal/admin/paypal.php|paypal/admin/paypal.php|stripe/admin/stripe.php', 1, '7346a324ed5e68ef525ebdc41ba09d60d2a91b70eaa0915634d3dc790f348645', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"ONLINE_PAYMENT_CREDITOR\", GETPOST(''ONLINE_PAYMENT_CREDITOR'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "print ''<input class=\"minwidth300\" type=\"text\" name=\"ONLINE_PAYMENT_CREDITOR\" value=\"''.getDolGlobalString(''ONLINE_PAYMENT_CREDITOR'').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_CSS_URL', 'string', NULL, 'public', 'Sets a custom CSS stylesheet URL applied to the public online payment pages.', 'Set via admin UI in paypal/admin/paypal.php:87/263 and stripe/admin/stripe.php:137/571, checked in multiple public pages e.g. public/payment/paymentok.php:220, public/project/index.php:213, public/project/viewandvote.php:226 and public/eventorganization/subscriptionok.php:176.', 'When set, the referenced CSS file is applied to style the public online payment/voting/subscription pages.', NULL, 0, 0, 'stripe/admin/stripe.php|paypal/admin/paypal.php|paypal/admin/paypal.php|stripe/admin/stripe.php', 1, '7f073b6f6799b4a129510ec44c7efaec8ac72a313a077a42a621bb88550de33c', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"ONLINE_PAYMENT_CSS_URL\", GETPOST(''ONLINE_PAYMENT_CSS_URL'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''ONLINE_PAYMENT_CSS_URL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_LOGO', 'string', NULL, 'public', 'Specifies the URL of a small logo image to display on public payment and voting pages.', 'Used across public/payment/newpayment.php, public/payment/paymentok.php, public/payment/paymentko.php, and public/project/viewandvote.php; each reads the value into $logosmall for conditional display. No admin UI write path is present.', 'Setting this causes a custom logo to appear on all public payment and vote pages; leaving it unset uses the default display.', 'String: URL of the logo image to display on online payment and voting pages', 1, 0, NULL, 1, '430f5cef251add4ba661404e4794e1c79999c8dd59c6bcf9adf458609f79d785', 'v2', '2026-04-21T13:50:40+00:00', '["public/payment/newpayment.php:1015|read|} elseif (getDolGlobalString(''ONLINE_PAYMENT_LOGO'')) {", "public/payment/newpayment.php:1016|read|$logosmall = getDolGlobalString(''ONLINE_PAYMENT_LOGO'');", "public/payment/paymentok.php:246|read|} elseif (getDolGlobalString(''ONLINE_PAYMENT_LOGO'')) {", "public/project/viewandvote.php:255|read|$logosmall = getDolGlobalString(''ONLINE_PAYMENT_LOGO'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_MESSAGE_FORM', 'string', NULL, 'stripe', 'Sets a custom HTML message displayed on the online payment form page.', 'Set via admin UI (DolEditor) in paypal/admin/paypal.php:95/276 and stripe/admin/stripe.php:141/577, and printed in core/lib/company.lib.php:3038-3039.', 'When non-empty, the configured message text is printed on the payment form instead of/along with default content, per the check at core/lib/company.lib.php:3038.', NULL, 0, 0, 'stripe/admin/stripe.php|paypal/admin/paypal.php|paypal/admin/paypal.php|stripe/admin/stripe.php', 1, 'ffcd454262a403a9ea5dafec56b048ac81b09376977773e66b59fe46a8ed1602', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"ONLINE_PAYMENT_MESSAGE_FORM\", GETPOST(''ONLINE_PAYMENT_MESSAGE_FORM'', ''restricthtml''), ''chaine'', 0, '''', $conf->entity);", "} elseif (getDolGlobalString(''ONLINE_PAYMENT_MESSAGE_FORM'')  !== '''') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_MESSAGE_FORMIFVAT', 'string', NULL, 'core', 'Stores a custom message translation key to display a VAT-related notice on online payment forms.', 'Read at core/lib/company.lib.php:2979-2980; when the value is a non-empty string it is passed to transnoentities for translation and printed. No comment is present in the payload.', 'Setting this constant causes a custom translated message to appear on payment forms in place of the default VAT notice; an empty or unset value suppresses that custom message.', 'String; a translation key resolvable by Dolibarr''s lang system, or empty to suppress.', 1, 0, NULL, 1, '4ba67f6d91e44ad706adf1139545ec952120dd68fd2f80f3312020341d13fa16', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/company.lib.php:2979|read|} elseif (getDolGlobalString(''ONLINE_PAYMENT_MESSAGE_FORMIFVAT'') !== '''') {", "core/lib/company.lib.php:2980|read|print $langs->transnoentities(getDolGlobalString(''ONLINE_PAYMENT_MESSAGE_FORMIFVAT''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_MESSAGE_KO', 'string', NULL, 'stripe', 'Sets a custom HTML message displayed on the online payment page when a payment fails (KO).', 'Set via admin UI (DolEditor) in paypal/admin/paypal.php:103/290 and stripe/admin/stripe.php:149/589.', 'When set, this message text is shown to the payer on the online payment failure/KO page.', NULL, 0, 0, 'stripe/admin/stripe.php|paypal/admin/paypal.php|paypal/admin/paypal.php|stripe/admin/stripe.php', 1, 'bb796c06957c40b59939b8d2b2076ce5e5d088c668c7f516923d621e24f5961a', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"ONLINE_PAYMENT_MESSAGE_KO\", GETPOST(''ONLINE_PAYMENT_MESSAGE_KO'', ''restricthtml''), ''chaine'', 0, '''', $conf->entity);", "$doleditor = new DolEditor(''ONLINE_PAYMENT_MESSAGE_KO'', getDolGlobalString(\"ONLINE_PAYMENT_MESSAGE_KO\"), '''', 100, ''dolibarr_details'', ''In'', false, true, true, ROWS_2, ''90%'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_MESSAGE_OK', 'string', NULL, 'stripe', 'Sets a custom HTML message displayed on the online payment page when a payment succeeds (OK).', 'Set via admin UI (DolEditor) in paypal/admin/paypal.php:99/283 and stripe/admin/stripe.php:145/583.', 'When set, this message text is shown to the payer on the online payment success/OK page.', NULL, 0, 0, 'stripe/admin/stripe.php|paypal/admin/paypal.php|paypal/admin/paypal.php|stripe/admin/stripe.php', 1, 'a2787ff310897000e7c88f6ce9e3f419913037d2b38c0affeaa242ba5fea8992', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"ONLINE_PAYMENT_MESSAGE_OK\", GETPOST(''ONLINE_PAYMENT_MESSAGE_OK'', ''restricthtml''), ''chaine'', 0, '''', $conf->entity);", "$doleditor = new DolEditor(''ONLINE_PAYMENT_MESSAGE_OK'', getDolGlobalString(\"ONLINE_PAYMENT_MESSAGE_OK\"), '''', 100, ''dolibarr_details'', ''In'', false, true, true, ROWS_2, ''90%'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_SENDEMAIL', 'string', NULL, 'public', 'Sets the email address used as sender or notified when an online payment completes.', 'Set via admin UI in paypal/admin/paypal.php:107/297 and stripe/admin/stripe.php:153/596, and read for sending purposes in public/stripe/ipn.php:333, public/payment/paymentok.php:2142/2246 and public/payment/paymentko.php:209.', 'When set, this email address is used by the online payment result pages (paymentok.php, paymentko.php, stripe ipn.php) as $sendemail for outgoing notification.', NULL, 0, 0, 'stripe/admin/stripe.php|paypal/admin/paypal.php|paypal/admin/paypal.php|stripe/admin/stripe.php', 1, 'f57734f9d855028b4614a53c37348f6eeea07a6f2b1ec90b66e4bd8fe32260ab', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''ONLINE_PAYMENT_SENDEMAIL'')) {", "$sendemail = getDolGlobalString(''ONLINE_PAYMENT_SENDEMAIL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_PAYMENT_WAREHOUSE', 'string', NULL, 'stripe', 'Would select the warehouse used for stock decrease when an online payment (Stripe) is completed, but the write path is currently disabled.', 'The write in stripe/admin/stripe.php:158 is commented out (''Stock decrement'' section), so the admin form no longer saves this constant. The English lang string (langs/en_US/stripe.lang:45) still documents it: ''Stock to use for stock decrease when online payment is done (TODO When option to decrease stock is done on an action on invoice and the online payment generate itself the invoice ?)'', indicating unfinished/TODO functionality.', 'Currently has no effect via the admin UI since the corresponding dolibarr_set_const() call is commented out; the feature it was meant to support (auto stock decrease on online payment) is marked TODO/incomplete.', 'Intended to hold a warehouse ID (per the lang string, ''stock to use for stock decrease''); not enforced anywhere active in code.', 1, 0, 'stripe/admin/stripe.php', 1, '830e01d99754b20d327f59e93c18036d7af2852f42ad8bd8ba697be93a293bc0', 'v2', '2026-07-24T07:05:23+00:00', '["stripe/admin/stripe.php:158|write|//$result = dolibarr_set_const($db, \"ONLINE_PAYMENT_WAREHOUSE\", ...", "langs/en_US/stripe.lang:45: ONLINE_PAYMENT_WAREHOUSE=Stock to use for stock decrease when online payment is done<br>(TODO When option to decrease stock is done on an action on invoice and the online payment generate itself the invoice ?)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_RECRUITMENT_LOGO', 'string', NULL, 'public', 'Path or URL of a custom logo displayed on the public recruitment pages.', 'Read in public/recruitment/view.php:332-333 and public/recruitment/index.php:152 where it is fetched into `$logosmall` for rendering. No admin UI write path is present.', 'When set, the specified logo image is shown on public recruitment pages instead of the default Dolibarr logo.', 'File path or URL string pointing to an image', 1, 0, NULL, 1, '1eeb9ac8ca6718186f0289056be13f85f3069b8b0365ccf0a09947ddee85375e', 'v2', '2026-04-21T13:50:40+00:00', '["} elseif (getDolGlobalString(''ONLINE_RECRUITMENT_LOGO'')) {", "$logosmall = getDolGlobalString(''ONLINE_RECRUITMENT_LOGO'');", "public/recruitment/view.php:332|read"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_RECRUITMENT_LOGO_', 'string', NULL, 'public', 'Sets a custom small logo filename for the public online recruitment candidacy pages, used as fallback when no suffixed logo is defined.', 'In public/recruitment/index.php, $paramlogo is built as ''ONLINE_RECRUITMENT_LOGO_''.$suffix (suffix defaults to empty string at line 66), and at line 152-153 if that suffixed value is empty, the code falls back to getDolGlobalString(''ONLINE_RECRUITMENT_LOGO'') and then reads getDolGlobalString(''ONLINE_RECRUITMENT_LOGO_'') as the logo filename to use.', 'Setting it replaces the default company logo shown on the public recruitment page header with the referenced logo file (looked up under logos/thumbs/ of mycompany).', 'String; expected to be a logo filename readable under the mycompany logos/thumbs directory.', 1, 0, NULL, 1, '94acd3469347c894bb3b279a888b23e403f277b55cc2aecc8fd496e61d7e7b5b', 'v2', '2026-07-24T07:05:23+00:00', '["public/recruitment/index.php:149: $paramlogo = ''ONLINE_RECRUITMENT_LOGO_''.$suffix;", "public/recruitment/index.php:153: $logosmall = getDolGlobalString(''ONLINE_RECRUITMENT_LOGO_'');", "public/recruitment/index.php:66: $suffix = \"\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_SIGN_NEWFORM_TEXT', 'string', NULL, 'public', 'Stores custom introductory text displayed on the public online signature form.', 'Checked at public/onlinesign/newonlinesign.php:290; the value is appended to $text at line 295 and also matched against a parenthesis pattern via preg_match at line 292 to extract inner content. No admin UI write is present.', 'Setting this constant injects custom text into the signature form header; leaving it unset shows no custom text.', 'String text to display; if wrapped in parentheses like ''(text)'', inner content is extracted; unset/empty = no custom text.', 1, 0, NULL, 1, 'aa89733d843595f06ddb9fe10a5cf6d0d3cec28e1be34b300606a654b6b39d5d', 'v2', '2026-04-21T13:50:40+00:00', '["public/onlinesign/newonlinesign.php:290|check|if (getDolGlobalString(''ONLINE_SIGN_NEWFORM_TEXT'')) {", "public/onlinesign/newonlinesign.php:292|read|if (preg_match(''/^\\((.*)\\)$/'', $conf->global->ONLINE_SIGN_NEWFORM_TEXT, $reg)) {", "public/onlinesign/newonlinesign.php:295|read|$text .= getDolGlobalString(''ONLINE_SIGN_NEWFORM_TEXT'') . \"<br>\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ONLINE_USER_LOGO', 'string', NULL, 'public', 'Default logo image (URL/path) used on the public user online-signature/profile page when no per-suffix logo override is defined.', 'Used in public/users/view.php:478-479 as a fallback: the code first checks ONLINE_USER_LOGO_<suffix> (a per-context variant), and if that is not set, falls back to ONLINE_USER_LOGO for $logosmall; otherwise it falls back further to the company logos.', 'Setting it changes the small logo shown on the public user page whenever no more specific ONLINE_USER_LOGO_<suffix> constant is defined for the current context.', 'String: a URL or path to a logo image, used as fallback before the company''s own logo.', 1, 0, NULL, 1, '43b6b751a17e185e7cf489758469c375e4c73e68b7c79f5e9f3a6fda676e448d', 'v2', '2026-07-24T07:05:23+00:00', '["public/users/view.php:478: } elseif (getDolGlobalString(''ONLINE_USER_LOGO'')) {", "public/users/view.php:479: $logosmall = getDolGlobalString(''ONLINE_USER_LOGO'');", "public/users/view.php:471: // Show logo (search order: logo defined by ONLINE_SIGN_LOGO_suffix, then ONLINE_SIGN_LOGO_, then small company logo, large company logo, theme logo, common logo)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OPENSTREETMAP_ENABLE_MAPS', 'bool', NULL, 'core', 'Enables display of an OpenStreetMap link/widget for a thirdparty''s (company''s) address.', 'In core/lib/functions.lib.php:5358, mirrors GOOGLE_ENABLE_GMAPS but for the ''openstreetmap'' module: for thirdparty/societe elements, if the openstreetmap module is enabled and this constant is set, the map is shown ($showomap = 1).', 'Enabling it (with the OpenStreetMap module active) adds an OpenStreetMap view/link below a thirdparty''s printed address.', 'Boolean-like: any truthy value enables the OSM map link, requires the ''openstreetmap'' module to also be enabled.', 1, 0, NULL, 1, '838261f31cf07200a7ac372411a47889d4ac1396415998d3768226f464308e30', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5358|check|if (($element == ''thirdparty'' || $element == ''societe'') && isModEnabled(''openstreetmap'') && getDolGlobalString(''OPENSTREETMAP_ENABLE_MAPS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OPENSTREETMAP_ENABLE_MAPS_CONTACTS', 'bool', NULL, 'core', 'Enables display of an OpenStreetMap link/widget for a contact''s address.', 'In core/lib/functions.lib.php:5361, same OSM pattern restricted to elements of type ''contact''.', 'Enabling it (with the OpenStreetMap module active) adds an OpenStreetMap view/link below a contact''s printed address.', 'Boolean-like: any truthy value enables the OSM map link for contacts.', 1, 0, NULL, 1, 'bf52f560e8ee489ab0ae47658e1ec0770c5965d162252c663038cda2a7df7ee9', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5361|check|if ($element == ''contact'' && isModEnabled(''openstreetmap'') && getDolGlobalString(''OPENSTREETMAP_ENABLE_MAPS_CONTACTS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OPENSTREETMAP_ENABLE_MAPS_MEMBERS', 'bool', NULL, 'core', 'Enables display of an OpenStreetMap link/widget for a foundation member''s address.', 'In core/lib/functions.lib.php:5364, same OSM pattern restricted to elements of type ''member''.', 'Enabling it (with the OpenStreetMap module active) adds an OpenStreetMap view/link below a member''s printed address.', 'Boolean-like: any truthy value enables the OSM map link for members.', 1, 0, NULL, 1, 'c6c3b80f1aeb426f7358891f64c4f1961bb5a62430fd40ff8afc9ce90d9872aa', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5364|check|if ($element == ''member'' && isModEnabled(''openstreetmap'') && getDolGlobalString(''OPENSTREETMAP_ENABLE_MAPS_MEMBERS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OPENSTREETMAP_ENABLE_MAPS_USERS', 'bool', NULL, 'core', 'Enables display of an OpenStreetMap link/widget for a Dolibarr user''s address.', 'In core/lib/functions.lib.php:5367, same OSM pattern restricted to elements of type ''user''.', 'Enabling it (with the OpenStreetMap module active) adds an OpenStreetMap view/link below a user''s printed address.', 'Boolean-like: any truthy value enables the OSM map link for users.', 1, 0, NULL, 1, 'eeffadc829f914176b08c3b73da5a5289d0b7377a8ab0b1c8fcb7d3b04db47f3', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:5367|check|if ($element == ''user'' && isModEnabled(''openstreetmap'') && getDolGlobalString(''OPENSTREETMAP_ENABLE_MAPS_USERS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OPENSURVEY_ENABLE_PUBLIC_INTERFACE', 'bool', NULL, 'public', 'Gate flag intended to enable the public (unauthenticated) OpenSurvey interface.', 'Checked in public/opensurvey/index.php:118, but the same file unconditionally sets $conf->global->OPENSURVEY_ENABLE_PUBLIC_INTERFACE = 1 at line 116 immediately before the check, so on this code path the check always passes regardless of any stored value.', 'As currently coded, the guard at line 118 cannot block access since the value is force-set to 1 just above it in the same file; the constant''s practical effect on this page is neutralized in the reviewed version.', 'Boolean (1 = interface considered enabled).', 1, 0, NULL, 1, '277781965d1b64c2a8d000d94e57656d7a99249525250052aabb17095e94b54c', 'v2', '2026-07-24T07:05:23+00:00', '["public/opensurvey/index.php:116: $conf->global->OPENSURVEY_ENABLE_PUBLIC_INTERFACE = 1;", "public/opensurvey/index.php:118: if (!getDolGlobalString(''OPENSURVEY_ENABLE_PUBLIC_INTERFACE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OPENSURVEY_PUBLIC_INTERFACE_TOPIC', 'string', NULL, 'public', 'Alt-text/topic string passed to the public OpenSurvey page header banner.', 'Used in public/opensurvey/index.php:133 as the $alttext argument to htmlPrintOnlineHeader(), which prints the company logo/header block for public pages.', 'Changing it changes the alt text or topic label shown in the header banner of the public survey page; other header behavior (logo selection) is controlled by separate constants.', 'Any string used as header alt text.', 1, 0, NULL, 1, '886ed0202e68357a0d74447b306ec90d2340ec423518c7dcb285712787712ce4', 'v2', '2026-07-24T07:05:23+00:00', '["public/opensurvey/index.php:133: htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''OPENSURVEY_PUBLIC_INTERFACE_TOPIC''), ''OPENSURVEY_IMAGE_PUBLIC_INTERFACE'', ...)"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('OPTIMIZEFORTEXTBROWSER', 'string', NULL, 'core', 'Adds explicit text labels next to form fields (URL/Label inputs) on the link-a-file form, for compatibility with text-only/screen-reader browsers.', 'In core/class/html.formfile.class.php:346 and 352, `<label>` elements for ''URLToLink'' and ''Label'' are only printed if getDolGlobalString(''OPTIMIZEFORTEXTBROWSER'') is set, in the form used to attach a URL link to a document/object (addlink block).', 'Enabling it adds visible text labels before the link-URL and label input fields on the ''link to URL'' form, improving usability for text-mode/non-JS/screen-reader browsers that may not render placeholder-only inputs well.', 'Boolean-like: set/non-empty prints explicit <label> tags for URL/Label fields; unset (default) relies on placeholder text only.', 1, 0, NULL, 1, 'fb8fd0d91e65dda836643adae24c329c0ab96954242c46c4eec0a990c36246d0', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formfile.class.php:346: if (getDolGlobalString(''OPTIMIZEFORTEXTBROWSER'')) { $out2 .= ''<label for=\"link\">''.$langs->trans(\"URLToLink\").'':</label> ''; }", "core/class/html.formfile.class.php:352: if (getDolGlobalString(''OPTIMIZEFORTEXTBROWSER'')) { $out2 .= ''<label for=\"label\">''.$langs->trans(\"Label\").'':</label> ''; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'core', 'Enables generation of a direct external download link (__DIRECTDOWNLOAD_URL_ORDER__) for a customer order''s PDF in email substitutions, and is exposed as an admin on/off toggle.', 'In core/lib/functions.lib.php:10737, if set and the object is a ''commande'', `$substitutionarray[''__DIRECTDOWNLOAD_URL_ORDER__'']` is filled with `$object->getLastMainDocLink()`; it is exposed in admin/order.php:704 via `ajax_constantonoff(''ORDER_ALLOW_EXTERNAL_DOWNLOAD'', ...)`.', 'Enabling it makes the __DIRECTDOWNLOAD_URL_ORDER__ substitution tag resolve to a shareable direct download link to the order''s last generated document, usable in email templates; otherwise the tag is empty.', 'Boolean-like toggle, set via the order module''s admin setup page (ajax on/off).', 0, 0, NULL, 1, '0b6adb969c24016bf497bf87641435bc15dd0f546f1e05f5cda6bb5585799130', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:10737|check|if (getDolGlobalString(''ORDER_ALLOW_EXTERNAL_DOWNLOAD'') && is_object($object) && $object->element == ''commande'') {", "admin/order.php:704: print ajax_constantonoff(''ORDER_ALLOW_EXTERNAL_DOWNLOAD'', array(), null, 0, 0, 0, 2, 0, 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_ALLOW_POS_SOURCE_EDIT', 'bool', NULL, 'commande', 'Forces display of the POS (Point of Sale) source field on the order view even when the takepos module is disabled and the order didn''t originate from POS.', 'Checked in commande/card.php:3000: if (isModEnabled(''takepos'') || $object->module_source || getDolGlobalString(''ORDER_ALLOW_POS_SOURCE_EDIT'')) gates display of the POS info row.', 'When enabled, the POS field row is shown on the order card regardless of whether the takepos module is active or the order''s module_source is set.', 'Boolean: 1/true forces the POS field to display.', 0, 0, NULL, 1, '58be3b2007156e71c7a91208a9656978b5b9285a23e871fa9a58990d1dc95d09', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3000: if (isModEnabled(''takepos'') || $object->module_source || getDolGlobalString(''ORDER_ALLOW_POS_SOURCE_EDIT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_BILLING_ALL_CUSTOMER', 'string', NULL, 'commande', 'Enables a billing action that creates invoices for all orders of a customer at once.', 'Checked in commande/list.php:2549 and commande/list_det.php:1715: the bulk-bill-all-customer option is shown or executed only when the invoice module is enabled and this constant is non-empty.', 'Enabling this constant adds a billing action that processes all customer orders together; leaving it empty hides that option.', 'Empty = per-order billing only (default); any non-empty value = bulk all-customer billing enabled.', 1, 0, NULL, 1, '64693f712ca9fcfa2ada2710ae72737caf6988949643bbb63112255b6a5b9a1a', 'v2', '2026-04-21T13:50:40+00:00', '["commande/list.php:2549|check|if (isModEnabled(''invoice'') && getDolGlobalString(''ORDER_BILLING_ALL_CUSTOMER'')) {", "commande/list_det.php:1715|check|if (isModEnabled(''invoice'') && getDolGlobalString(''ORDER_BILLING_ALL_CUSTOMER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_BILL_AFTER_VALIDATION', 'string', NULL, 'index.php', 'Controls whether the home dashboard shows a "customer orders to be billed" workboard line (a count not visible by default).', 'In index.php:271, if getDolGlobalInt(''ORDER_BILL_AFTER_VALIDATION'') is truthy, the dashboard adds the ''_tobill'' board line; the preceding comment notes it is ''not visible by default, does not match a lot of organization''.', 'Enabling this constant adds an extra dashboard counter for customer orders to be billed after validation, on top of the always-shown ''to ship'' and ''shipped to bill'' lines.', 'Integer/boolean-like; truthy shows the extra ''to be billed (validated)'' board line, empty/unset (default) hides it.', 1, 0, NULL, 1, '1429b5da174d2a4d7b56534471ef83a06e0edf819271395bf23c582603e7f8c7', 'v2', '2026-07-24T07:05:23+00:00', '["index.php:271|check|if (getDolGlobalInt(''ORDER_BILL_AFTER_VALIDATION'')) {", "index.php:270|comment|// Number of customer orders to be billed (not visible by default, does not match a lot of organization)."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_BOX_LAST_ORDERS_SHOW_VALIDATE_USER', 'bool', NULL, 'core', 'Shows the validating user column in the ''Last orders'' dashboard box.', 'In core/boxes/box_commandes.php:174, when set, the box adds a column showing the user who validated the order (fk_user_valid), the same pattern as BOM_BOX_LAST_BOMS_SHOW_VALIDATE_USER.', 'When enabled, the last-orders dashboard widget displays an extra column with the validating user''s link; when unset, the column is omitted.', 'boolean: 1/true adds the validate-user column to the box; unset/0 = column not shown.', 1, 0, NULL, 1, '5ee744939701c5f997a8374962e165b8bd6e7f45485ffc210f8692b50a9215ee', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_commandes.php:174: if (getDolGlobalString(''ORDER_BOX_LAST_ORDERS_SHOW_VALIDATE_USER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_BOX_LAST_ORDERS_VALIDATED_ONLY', 'string', NULL, 'core', 'Restricts the ''Last orders'' dashboard box to only show validated orders.', 'In core/boxes/box_commandes.php:105, when set, the SQL query adds ''AND c.fk_statut = 1'' filtering out draft orders (status 0) from the last-orders box listing.', 'Enabling it hides draft orders (status 0) from the last-orders dashboard widget, showing only validated (status 1) orders and beyond.', 'boolean: 1/true adds ''fk_statut = 1'' filter (validated orders only); unset/0 = all statuses shown in the box.', 1, 0, NULL, 1, 'fa3cbda04afd65a71d83301fe05f2fff9ef15ed187bc967342b9b5cf983daa40', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_commandes.php:104-105: if (getDolGlobalString(''ORDER_BOX_LAST_ORDERS_VALIDATED_ONLY'')) {\\n\\t$sql .= \" AND c.fk_statut = 1\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_BOX_LAST_SHIPMENTS_VALIDATED_ONLY', 'string', NULL, 'core', 'Restricts the "Last shipments" home dashboard box to show only validated shipments (status = 1).', 'In core/boxes/box_shipments.php:103, when getDolGlobalString(''ORDER_BOX_LAST_SHIPMENTS_VALIDATED_ONLY'') is truthy the SQL query adds "AND e.fk_statut = 1" to filter the shipment list.', 'Setting this constant hides draft/other-status shipments from the box, showing only validated (fk_statut=1) ones.', 'Boolean-like; truthy restricts to validated shipments (fk_statut=1), empty/unset shows all shipments.', 1, 0, NULL, 1, '60718ff607f3fe9146c2b6898e2387715e26b87982841bb16a750e46d75d2c6b', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_shipments.php:103|check|if (getDolGlobalString(''ORDER_BOX_LAST_SHIPMENTS_VALIDATED_ONLY'')) {", "core/boxes/box_shipments.php:104|code|$sql .= \" AND e.fk_statut = 1\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_CLOSE_TEMPLATE', 'string', NULL, 'core', 'Overrides the email template used to notify when a sales order is closed (ORDER_CLOSE notification event).', 'Read in core/class/notify.class.php:799 in the Notify class''s per-event-code switch; when the current notification code is ''ORDER_CLOSE'', $labeltouse is set from this constant and later passed to $formmail->getEMailTemplate() to fetch a specific template instead of the built-in message.', 'Setting it to the label/ref of an existing email template (created via Setup > Emails Templates) makes Dolibarr use that custom template''s subject/body for the ORDER_CLOSE notification instead of the hardcoded EMailTextOrderClose text.', 'String: the label/ref of an email template record (as used by FormMail::getEMailTemplate); empty/unset falls back to the default built-in message.', 1, 0, NULL, 1, '6f9413f68881f9eb8a38a09f4db50e82a7194a618cc42175cdb2419f655e7716', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/notify.class.php:799|read|$labeltouse = getDolGlobalString(''ORDER_CLOSE_TEMPLATE'');", "case ''ORDER_CLOSE'': ... $labeltouse = getDolGlobalString(''ORDER_CLOSE_TEMPLATE''); $mesg = $outputlangs->transnoentitiesnoconv(\"EMailTextOrderClose\", $link);", "$labeltouse = getDolGlobalString($template); if (!empty($labeltouse)) { $arraydefaultmessage = $formmail->getEMailTemplate($this->db, $object_type, $user, $outputlangs, 0, 1, $labeltouse); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_DISABLE_CLASSIFY_BILLED_FROM_ORDER', 'bool', NULL, 'commande', 'Hides the ''Classify billed'' / ''Classify unbilled'' action buttons on the sales order card.', 'Checked in commande/card.php:3637 and :3642: the ClassifyBilled/ClassifyUnBilled buttons are shown only if $usercancreate && status >= VALIDATED && !getDolGlobalString(''ORDER_DISABLE_CLASSIFY_BILLED_FROM_ORDER'') && !getDolGlobalString(''WORKFLOW_BILL_ON_SHIPMENT'').', 'When enabled, users can no longer manually toggle an order''s billed/unbilled status from the order card button (independent of the WORKFLOW_BILL_ON_SHIPMENT setting, which also disables it).', 'Boolean: 1/true disables the manual classify billed/unbilled buttons on the order.', 0, 0, NULL, 1, '57a73ec94445a2a434193a0a01d413bb32e818b42e6040a6d763226818d0bfef', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3637: if ($usercancreate && status>=VALIDATED && !getDolGlobalString(''ORDER_DISABLE_CLASSIFY_BILLED_FROM_ORDER'') && !getDolGlobalString(''WORKFLOW_BILL_ON_SHIPMENT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_DISABLE_DELIVERY_DATE', 'bool', NULL, 'commande', 'Disables the delivery date field on customer orders.', 'Checked at commande/list.php:1068 to conditionally include the delivery date column, and used in fourn/class/fournisseur.commande.class.php:393 to set the ''enabled'' attribute of the ''date_livraison'' field definition. Also controls column visibility in commande/list.php:240 and commande/list_det.php:210.', 'When enabled, the delivery date field is hidden and disabled across order lists and detail views; when disabled or not set, the delivery date is shown.', '0 or not set = delivery date field visible and enabled; non-zero = delivery date field hidden and disabled.', 1, 0, NULL, 1, '1dcef07f0c4b6cae2e5997d31aeda17e38e6906e25ff4167bd3ddb6a6c52b0cb', 'v2', '2026-04-21T11:16:15+00:00', '["commande/list.php:1068|check|if (!getDolGlobalString(''ORDER_DISABLE_DELIVERY_DATE'')) {", "fourn/class/fournisseur.commande.class.php:393|read|''date_livraison'' => array(''type'' => ''datetime'', ''label'' => ''DeliveryDate'', ''enabled'' => ''getDolGlobalInt(\"ORDER_DISABLE_DELIVERY_DATE\") ? 0 : 1'', ''visible'' => 1, ''position'' => 74),", "commande/list.php:240|read|''c.delivery_date'' => array(''label'' => \"DateDeliveryPlanned\", ''checked'' => ''1'', ''enabled'' => (string) (int) !getDolGlobalString(''ORDER_DISABLE_DELIVERY_DATE''), ''position'' => 65,"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_DISABLE_SHIPPABLE_ICON_ON_CARD', 'bool', NULL, 'core', 'Disables the shippable status icon displayed on sales order line views and edit forms.', 'Checked in core/tpl/objectline_view.tpl.php:477, core/tpl/objectline_title.tpl.php:141, core/tpl/objectline_edit.tpl.php:307, and commande/card.php:3112. The icon appears only when stock and shipping modules are enabled and the constant is not set.', 'Setting this constant removes the shippable icon from order line displays, regardless of stock or shipping module state.', '0 (icon shown) or 1 (icon hidden)', 1, 0, NULL, 1, 'c198d635641437619d65523922db821ca7b3e404b06cb2b4fed2d91464baeb62', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_view.tpl.php:477|check|if ($object->element == ''commande'' && isModEnabled(''stock'') && isModEnabled(''shipping'') && !getDolGlobalString(''ORDER_DISABLE_SHIPPABLE_ICON_ON_CARD'')", "core/tpl/objectline_title.tpl.php:141|check|if ($object->element == ''commande'' && isModEnabled(''stock'') && isModEnabled(''shipping'') && !getDolGlobalString(''ORDER_DISABLE_SHIPPABLE_ICON_ON_CARD'')", "commande/card.php:3112|check|if (isModEnabled(''stock'') && isModEnabled(''shipping'') && !getDolGlobalString(''ORDER_DISABLE_SHIPPABLE_ICON_ON_CARD'') && !empty($object->delivery_date)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_DONT_REOPEN_BILLED', 'string', NULL, 'commande', 'Hides the ''Reopen'' button on a closed/canceled order once it has been marked billed.', 'Checked in commande/card.php:3473: the ReOpen button is shown only if (!$object->billed || !getDolGlobalInt(''ORDER_DONT_REOPEN_BILLED'')), i.e. always shown unless the order is billed and this constant is set.', 'When enabled, a billed order that is closed or canceled no longer offers the Reopen action button; when disabled (default), billed orders can still be reopened.', 'Boolean: 1/true prevents reopening of billed orders.', 0, 0, NULL, 1, 'ec87421796ffd35af01036a4bf5e232d5174d0715d0a045d570ed6cbfc066339', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3473: if ((...STATUS_CLOSED || ...STATUS_CANCELED) && $usercancreate && (!$object->billed || !getDolGlobalInt(''ORDER_DONT_REOPEN_BILLED''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_ENABLE_NEGATIVE', 'bool', NULL, 'commande', 'Allows validating a draft sales order whose total is negative.', 'Checked in commande/card.php:3514: the Validate button is shown/enabled if ($object->status == Commande::STATUS_DRAFT && ($object->total_ttc >= 0 || getDolGlobalString(''ORDER_ENABLE_NEGATIVE'')) && $usercanvalidate).', 'When enabled, orders with a negative total_ttc can be validated; when disabled (default), only orders with total_ttc >= 0 can be validated.', 'Boolean: 1/true permits validation of orders with negative total.', 0, 0, NULL, 1, 'a31b63f533ac9d104a79c5a63274ad240364bd47eb63b8b6dfeef64246ac8af8', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3514: if ($object->status == Commande::STATUS_DRAFT && ($object->total_ttc >= 0 || getDolGlobalString(''ORDER_ENABLE_NEGATIVE'')) && $usercanvalidate) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_ENABLE_NEGATIVE_QTY', 'bool', NULL, 'commande', 'Allows negative line quantities when adding/editing a free product line on a sales order.', 'Checked twice in commande/card.php (lines 1035 and 1705): if ($qty < 0 && !getDolGlobalString(''ORDER_ENABLE_NEGATIVE_QTY'')) triggers the ''FieldCannotBeNegative'' error and blocks the line save.', 'When enabled, users can enter negative quantities on order lines without an error; when disabled (default), a negative quantity is rejected with an error message.', 'Boolean: 1/true allows negative quantity; unset/0 blocks it.', 0, 0, NULL, 1, 'ebba27119bf98b292afea713a4b53253144d73697ae380d6654f6eb1ba1af32b', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:1035/1705: if ($qty < 0 && !getDolGlobalString(''ORDER_ENABLE_NEGATIVE_QTY'')) { setEventMessages($langs->trans(''FieldCannotBeNegative'', ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated customer order documents.', 'Written from admin/order.php:173 via dolibarr_set_const() when the admin saves the customer order module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated customer order documents/PDFs; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/order.php', 1, '2678e1106526e92fd6eb20cffbf2b75bf5b0f626078d67eafccf81c2c90c5aa0', 'v2', '2026-07-24T07:05:23+00:00', '["admin/order.php:173|write|$res = dolibarr_set_const($db, \"ORDER_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_HIDE_ONLINE_PAYMENT_ON_ORDER', 'bool', NULL, 'commande', 'Hides the online payment link/button shown on the sales order card even if online payment methods are otherwise available.', 'Checked in commande/card.php:3713: if (getDolGlobalString(''ORDER_HIDE_ONLINE_PAYMENT_ON_ORDER'')) { $useonlinepayment = 0; } forces the online payment count to zero, suppressing the showOnlinePaymentUrl() link.', 'When enabled, the ''pay online'' link is never displayed on the order card regardless of configured online payment methods.', 'Boolean: 1/true hides the online payment link on the order.', 0, 0, NULL, 1, 'ef519addef5ea8d8e58c6d4a8cea7f7235292893cfbd70561331b52cc3d2743e', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:3713: if (getDolGlobalString(''ORDER_HIDE_ONLINE_PAYMENT_ON_ORDER'')) { $useonlinepayment = 0; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_MANAGE_MIN_AMOUNT', 'string', NULL, 'fourn', 'Enables minimum order amount enforcement for both customer and supplier orders.', 'Checked across 6 occurrences in fourn/commande/card.php:2737, fourn/card.php:438, comm/card.php:574, commande/card.php:3312, and societe/class/societe.class.php:243-244. When enabled, the order_min_amount and supplier_order_min_amount fields become active on third-party records.', 'Enabling this activates minimum order amount fields on third-party records and blocks order validation when the order total is below the configured minimum.', 'Empty/0 = no minimum amount enforced; truthy = minimum amount enforcement active', 1, 0, NULL, 1, '5b66d7df6c637729489a1a502893b43642d189e2b374d19bbb3161b9e2182ce8', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/commande/card.php:2737|check|if (getDolGlobalString(''ORDER_MANAGE_MIN_AMOUNT'') && $object->total_ht < $object->thirdparty->supplier_order_min_amount) {", "commande/card.php:3312|check|if (getDolGlobalString(''ORDER_MANAGE_MIN_AMOUNT'') && $object->total_ht < $object->thirdparty->order_min_amount) {", "societe/class/societe.class.php:243|read|''order_min_amount'' => array(''type'' => ''double(24,8)'', ''label'' => ''Order min amount'', ''enabled'' => ''isModEnabled(\"order\") && getDolGlobalInt(\"ORDER_MANAGE_MIN_AMOUNT\")''", "societe/class/societe.class.php:244|read|''supplier_order_min_amount'' => array(''type'' => ''double(24,8)'', ''label'' => ''Supplier order min amount'', ''enabled'' => ''isModEnabled(\"order\") && getDolGlobalInt(\"ORDER_MANAGE_MIN_AMOU"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_MASS_ACTION_BILLED_LINK_EXPEDITIONS', 'string', NULL, 'commande', 'During the mass action ''create bills from orders'', also links the created invoice to the shipments (expeditions) linked to the source order.', 'Checked in commande/list.php:511: if (getDolGlobalString(''ORDER_MASS_ACTION_BILLED_LINK_EXPEDITIONS'')) { $cmd->fetchObjectLinked(); ... adds shipping links to the new invoice/object }.', 'When enabled, invoices generated via the order-list mass ''create bills'' action are also linked to the shipments associated with the originating order; when disabled, only the order link is added.', 'Boolean: 1/true also links shipments (expeditions) when mass-creating bills from orders.', 0, 0, NULL, 1, 'e86b65a963a6261fad09c687ca5b5b7a7ddaa2a5fc8f476859c8c11fe9210eea', 'v2', '2026-07-24T07:05:23+00:00', '["commande/list.php:511: if (getDolGlobalString(''ORDER_MASS_ACTION_BILLED_LINK_EXPEDITIONS'')) {", "commande/list.php: // Linked Expeditions ... if (!$error && $cmd->id && !empty($cmd->linkedObjectsIds[''shipping'']) ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_NOCHECK_ONSALE_PRODUCTS_ONVALID', 'string', NULL, 'commande', 'Skips the check that all product lines on a sales order are still on sale (''active'') at order validation time.', 'In commande/class/commande.class.php:538, Commande::valid() normally calls $this->checkActiveProductInLines() and blocks validation if a line''s product is no longer active; setting this boolean bypasses that check.', 'When enabled, orders can be validated even if they contain lines referencing products/services that are no longer marked as on sale.', 'Boolean: true/1 disables the active-product check on validation, false/0 (default) keeps the check enforced.', 1, 0, NULL, 1, '7ea064b231c848238a9a813389983a5b0abd2b497a8bf9e9a9a38bc1c26798e4', 'v2', '2026-07-24T07:05:23+00:00', '["commande/class/commande.class.php:538|check|if (!getDolGlobalBool(''ORDER_NOCHECK_ONSALE_PRODUCTS_ONVALID'') && !$this->checkActiveProductInLines()) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_REOPEN_TO_DRAFT', 'string', NULL, 'commande', 'Controls whether a validated or closed customer order can be reopened back to draft status.', 'Checked in commande/class/commande.class.php:690 to block reopening when the constant is absent, and in commande/card.php:265 to show the reopen-to-draft action in the UI.', 'When enabled, users can revert a non-draft order to draft status; when disabled or unset, this action is blocked.', 'Int-like: 0 or unset = reopening blocked; non-zero = reopening allowed.', 1, 0, NULL, 1, 'a5cae25ce6cf9533bd4b2ba3ee190bc18261656d384ebba58f497aa2ad0d33e1', 'v2', '2026-04-21T13:50:40+00:00', '["commande/class/commande.class.php:690|check|if ($this->status <= self::STATUS_DRAFT && !getDolGlobalInt(''ORDER_REOPEN_TO_DRAFT'')) {", "commande/card.php:265|check|if (getDolGlobalInt(''ORDER_REOPEN_TO_DRAFT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_REQUIRE_SOURCE', 'string', NULL, 'commande', 'Makes the order ''Source'' field mandatory when creating a sales order.', 'In commande/class/commande.class.php:1028, Commande::create() raises an ErrorFieldRequired error for the Source field if this constant is set and $this->source is negative (unset).', 'Enabling it blocks creation of any sales order that does not have a Source value set, forcing callers/users to always provide one.', 'Boolean/truthy: when set (non-empty), Source becomes required at order creation.', 1, 0, NULL, 1, '5fd35ff917fcb82dbc24e1d445caf83397ff41a2f9be82657306798a8f9211be', 'v2', '2026-07-24T07:05:23+00:00', '["commande/class/commande.class.php:1028|check|if (getDolGlobalString(''ORDER_REQUIRE_SOURCE'') && $this->source < 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_SHIPABLE_STATUS_DISABLED_BY_DEFAULT', 'bool', NULL, 'commande', 'Disables the ''shippable'' status filter in the order list by default when set.', 'Checked in commande/list.php:2056 and commande/list_det.php:1271: when non-empty, the shippable-status filter is not applied by default.', 'Enabling this constant suppresses the default shippable-status filter, showing all orders regardless of shippability.', 'Empty = shippable filter active by default; any non-empty value = filter disabled by default.', 1, 0, NULL, 1, '4053d6294d9ed93384915cfd30ade7b43d203d95dab5287ceb0beb5dd36a20c4', 'v2', '2026-04-21T13:50:40+00:00', '["commande/list.php:2056|check|if (getDolGlobalString(''ORDER_SHIPABLE_STATUS_DISABLED_BY_DEFAULT'')) {", "commande/list_det.php:1271|check|if (getDolGlobalString(''ORDER_SHIPABLE_STATUS_DISABLED_BY_DEFAULT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_SHOW_POS', 'bool', NULL, 'commande', 'Forces display of POS-related fields/columns in the order list even when the cashdesk/takepos modules are not enabled.', 'Read in commande/list.php:221 with inline comment: $showpos = (isModEnabled(''cashdesk'') || isModEnabled(''takepos'') || getDolGlobalInt(''ORDER_SHOW_POS'')) ? ''1'' : ''0''; // Show POS fields if cashdesk or takepos module enabled or if global configuration to show POS fields on order list is enabled.', 'When enabled, the order list shows POS-specific fields/columns regardless of whether the cashdesk or takepos modules are active.', 'Boolean: 1/true forces POS fields to show in the order list, per inline comment ''or if global configuration to show POS fields on order list is enabled''.', 0, 0, NULL, 1, 'f33536468b11134274232ca85041297793cc374f6e099ae314df51a50100a7d5', 'v2', '2026-07-24T07:05:23+00:00', '["commande/list.php:221: $showpos = (isModEnabled(''cashdesk'') || isModEnabled(''takepos'') || getDolGlobalInt(''ORDER_SHOW_POS'')) ? ''1'' : ''0'';", "commande/list.php: // Show POS fields if cashdesk or takepos module enabled or if global configuration to show POS fields on order list is enabled"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_SUPPLIER_APPROVE_TEMPLATE', 'string', NULL, 'core', 'Overrides the email template used to notify when a supplier (purchase) order is approved (ORDER_SUPPLIER_APPROVE event).', 'Read in core/class/notify.class.php:873 in the same Notify per-event-code switch; sets $labeltouse for the ORDER_SUPPLIER_APPROVE case, later resolved via $formmail->getEMailTemplate().', 'Setting it to an existing email template label/ref replaces the default EMailTextSupplierOrderApprovedBy text with that custom template for this notification event.', 'String: label/ref of an email template record; empty/unset falls back to the default built-in message.', 1, 0, NULL, 1, '6b38e8935c2135b63ab07ff2581bc08e26cf511b98cfa23c4f465047aa7517d6', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/notify.class.php:873|read|$labeltouse = getDolGlobalString(''ORDER_SUPPLIER_APPROVE_TEMPLATE'');", "case ''ORDER_SUPPLIER_APPROVE'': ... $labeltouse = getDolGlobalString(''ORDER_SUPPLIER_APPROVE_TEMPLATE''); $mesg .= $outputlangs->transnoentitiesnoconv(\"EMailTextSupplierOrderApprovedBy\", $link, ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_SUPPLIER_EMAIL_SENDER', 'string', NULL, 'core', 'Sets the ''From'' email address used when pre-filling the send-by-email form for supplier orders.', 'Used in core/tpl/card_presend.tpl.php:211-212: when $object->element === ''order_supplier'' and this constant is truthy, $formmail->frommail is set to its value and fromtype forced to ''special''.', 'Setting it overrides the default sender email address specifically for outgoing supplier order emails.', 'Free-text email address string; when non-empty, activates the supplier-order sender override branch.', 0, 0, NULL, 1, '3ac876cdd994b4cb62040d0d04c7e9725071929af7ac71fabfd09434bd94572b', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:211|check|if ($object->element === ''order_supplier'' && getDolGlobalString(''ORDER_SUPPLIER_EMAIL_SENDER'')) {", "core/tpl/card_presend.tpl.php:212|read|$formmail->frommail = getDolGlobalString(''ORDER_SUPPLIER_EMAIL_SENDER'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_SUPPLIER_EMAIL_SENDER_NAME', 'string', NULL, 'core', 'Sets the ''From'' display name used when pre-filling the send-by-email form for supplier orders.', 'Used in core/tpl/card_presend.tpl.php:213 to set $formmail->fromname within the supplier-order sender branch guarded by ORDER_SUPPLIER_EMAIL_SENDER (line 211), defaulting to empty string.', 'Setting it customizes the sender display name on supplier order emails; only applies when ORDER_SUPPLIER_EMAIL_SENDER is also set.', 'Free-text sender display name string; defaults to '''' if unset.', 0, 0, NULL, 1, '4545cb96f461536b0236af9f1924a216123bbf5ae0d7d921d9396a209f2f8508', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:213|read|$formmail->fromname = getDolGlobalString(''ORDER_SUPPLIER_EMAIL_SENDER_NAME'', '''');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_SUPPLIER_REFUSE_TEMPLATE', 'bool', NULL, 'core', 'Overrides the email template used to notify when a supplier (purchase) order is refused (ORDER_SUPPLIER_REFUSE event).', 'Read in core/class/notify.class.php:890 in the same Notify per-event-code switch; sets $labeltouse for the ORDER_SUPPLIER_REFUSE case, later resolved via $formmail->getEMailTemplate(). Note: payload TYPE says ''bool'' but this constant is used as a string template label like its siblings, so the TYPE field appears mistaken.', 'Setting it to an existing email template label/ref replaces the default EMailTextSupplierOrderRefusedBy text with that custom template for this notification event.', 'String: label/ref of an email template record; empty/unset falls back to the default built-in message.', 1, 0, NULL, 1, '993f8dd909fecc319c1de7b31cddf6987789df51ce39b45b3b4138bc27c74ad9', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/notify.class.php:890|read|$labeltouse = getDolGlobalString(''ORDER_SUPPLIER_REFUSE_TEMPLATE'');", "case ''ORDER_SUPPLIER_REFUSE'': ... $labeltouse = getDolGlobalString(''ORDER_SUPPLIER_REFUSE_TEMPLATE''); $mesg .= $outputlangs->transnoentitiesnoconv(\"EMailTextSupplierOrderRefusedBy\", $link, ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_SUPPLIER_VALIDATE_TEMPLATE', 'string', NULL, 'core', 'Overrides the email template used to notify when a supplier (purchase) order is validated (ORDER_SUPPLIER_VALIDATE event).', 'Read in core/class/notify.class.php:856 in the same Notify per-event-code switch; sets $labeltouse for the ORDER_SUPPLIER_VALIDATE case, later resolved via $formmail->getEMailTemplate().', 'Setting it to an existing email template label/ref replaces the default EMailTextSupplierOrderValidatedBy text with that custom template for this notification event.', 'String: label/ref of an email template record; empty/unset falls back to the default built-in message.', 1, 0, NULL, 1, '9729b07048f5589c4bfca1fccf53e5682e5a68c2932b159e49875e1696c44587', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/notify.class.php:856|read|$labeltouse = getDolGlobalString(''ORDER_SUPPLIER_VALIDATE_TEMPLATE'');", "case ''ORDER_SUPPLIER_VALIDATE'': ... $labeltouse = getDolGlobalString(''ORDER_SUPPLIER_VALIDATE_TEMPLATE''); $mesg .= $outputlangs->transnoentitiesnoconv(\"EMailTextSupplierOrderValidatedBy\", $link, ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_TYPE_CONTACT_DEFAULT', 'string', NULL, 'commande', 'Overrides the default contact type code preselected when adding a contact to a sales order.', 'Read in commande/card.php:110: $type_contact_code = (getDolGlobalString(''ORDER_TYPE_CONTACT_DEFAULT'') ? getDolGlobalString(''ORDER_TYPE_CONTACT_DEFAULT'') : ''CUSTOMER'');', 'If set, the given contact type code becomes the default instead of ''CUSTOMER'' when the contact-add form on an order is opened.', 'String: a contact type code (default fallback is ''CUSTOMER'').', 0, 0, NULL, 1, '10be4f8b3092ae15b722a988c67d2e4c7a594d1c7645c787e85fd883239667b2', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:110: $type_contact_code = (getDolGlobalString(''ORDER_TYPE_CONTACT_DEFAULT'') ? getDolGlobalString(''ORDER_TYPE_CONTACT_DEFAULT'') : ''CUSTOMER'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('ORDER_VALID_AFTER_CLOSE_PROPAL', 'string', NULL, 'commande', 'Automatically validates a sales order right after it is created from a closed/accepted proposal.', 'In commande/class/commande.class.php:1547, inside the createFromProposal-like flow, if this constant is set the newly created order is immediately validated via $this->valid($user) instead of staying in draft.', 'Enabling it removes the manual validation step for orders generated from a proposal; the order becomes ''validated'' immediately upon creation.', 'Boolean/truthy: when set, the created order is auto-validated after creation from the proposal.', 1, 0, NULL, 1, '42706b8e277be2b6ccbb6777beefd3fdee16667aba9dc568d5ebaaa41416a56c', 'v2', '2026-07-24T07:05:23+00:00', '["commande/class/commande.class.php:1547|check|if (getDolGlobalString(''ORDER_VALID_AFTER_CLOSE_PROPAL'')) {", "commande/class/commande.class.php:1547-1550: // Validate immediately the order ... $result = $this->valid($user);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_ADDON', 'string', NULL, 'partnership', 'Specifies the numbering module class name used to generate partnership reference numbers.', 'Checked and read in partnership/class/partnership.class.php:1280–1288. When absent, it is defaulted to ''mod_partnership_standard'' (line 1281) and then the class file is loaded from that name (line 1287–1288). No admin UI write path is present in the payload.', 'Changing this value switches the partnership numbering module; the named class file must exist under the partnership modules directory.', 'String class name of the numbering addon (default: ''mod_partnership_standard'')', 1, 0, NULL, 1, 'aaddd992a39a3c3e35dd6ae7b5de71b97d3e6ec8482b31f34ee9855406d55301', 'v2', '2026-04-21T11:16:15+00:00', '["partnership/class/partnership.class.php:1281|write|$conf->global->PARTNERSHIP_ADDON = ''mod_partnership_standard'';", "partnership/class/partnership.class.php:1284|check|if (getDolGlobalString(''PARTNERSHIP_ADDON'')) {", "partnership/class/partnership.class.php:1287|read|$file = getDolGlobalString(''PARTNERSHIP_ADDON'') . \".php\";", "partnership/class/partnership.class.php:1288|read|$classname = getDolGlobalString(''PARTNERSHIP_ADDON'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_ADDON_PDF', 'string', NULL, 'partnership', 'Sets the default PDF document model (template) used to generate a partnership''s PDF document.', 'In partnership/class/partnership.class.php:1359-1360, generateDocument() falls back to this string constant''s value for $modele when no model is set on the object instance and no model was passed explicitly, defaulting otherwise to ''standard_partnership''.', 'Setting it to a valid partnership PDF model name changes which PDF template is used by default when generating partnership documents.', 'string = name of a partnership PDF model/template (e.g. ''standard_partnership'').', 1, 0, NULL, 1, '867254f73d2497668cd5861bf2e40586875199c951a929b46f4bed44b5d712bb', 'v2', '2026-07-24T07:05:23+00:00', '["partnership/class/partnership.class.php:1355: $modele = ''standard_partnership'';", "partnership/class/partnership.class.php:1359|read|} elseif (getDolGlobalString(''PARTNERSHIP_ADDON_PDF'')) {", "partnership/class/partnership.class.php:1360|read|$modele = getDolGlobalString(''PARTNERSHIP_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_ADVANCED_MASK', 'string', NULL, 'partnership', 'Holds the numbering mask pattern for the ''Advanced'' partnership reference numbering model.', 'Used in partnership/core/modules/partnership/mod_partnership_advanced.php: the admin info() form (line 86) renders an editable text input named ''maskPartnership'' pre-filled with getDolGlobalString(''PARTNERSHIP_ADVANCED_MASK''), and getNextValue() (line 139) reads it to compute the next partnership reference.', 'Changing the mask string changes the format of generated partnership reference numbers (prefix/date/counter placeholders per Dolibarr''s generic mask syntax).', 'String: a Dolibarr numbering mask (e.g. containing placeholders for year, counter, etc.), edited via the module''s admin form input ''maskPartnership''.', 0, 0, NULL, 1, '5723abc070fb5558dab3502cce712cdf0f6e485c400b85cb0fbace59888f5843', 'v2', '2026-07-24T07:05:23+00:00', '["partnership/core/modules/partnership/mod_partnership_advanced.php:86|read|value=\"''.getDolGlobalString(''PARTNERSHIP_ADVANCED_MASK'').''\"", "partnership/core/modules/partnership/mod_partnership_advanced.php:139|read|$mask = getDolGlobalString(''PARTNERSHIP_ADVANCED_MASK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_AUTOREGISTER_NOTIF_MAIL', 'string', NULL, 'public', 'Email body template used to notify the foundation/admin when a new partnership autoregisters (feature currently disabled in code).', 'Only referenced inside a block comment (/* ... */ spanning public/partnership/new.php:374-411); the surrounding code that would send this notification via CMailFile is commented out and not executed.', 'Currently has no runtime effect: the only code path that reads it is commented out in public/partnership/new.php.', 'Free-form string passed through makeSubstitution() for placeholder replacement in the (dead) code.', 0, 0, NULL, 1, '855bcefa281f39bb513e59981f260be43705f9386cc9104c43103bc1a1382a6d', 'v2', '2026-07-24T07:05:23+00:00', '["public/partnership/new.php:374: /*", "public/partnership/new.php:398: $partnership->makeSubstitution(getDolGlobalString(''PARTNERSHIP_AUTOREGISTER_NOTIF_MAIL'')),", "public/partnership/new.php:411: }*/"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_AUTOREGISTER_NOTIF_MAIL_SUBJECT', 'string', NULL, 'public', 'Email subject used to notify the foundation/admin when a new partnership autoregisters (feature currently disabled in code).', 'Only referenced inside a block comment (/* ... */ spanning public/partnership/new.php:374-411) in public/partnership/new.php, meaning the notification-email code that reads this constant is commented out and not executed.', 'Currently has no runtime effect: the only code path that reads it is commented out in public/partnership/new.php.', 'Free-form string; code default when unset (in the dead code) is ''Partnership request''.', 0, 0, NULL, 1, 'c41ad26a9b24d18cc83d2ac92a749c26de25151043bf937335c0a9c2784ef6c1', 'v2', '2026-07-24T07:05:23+00:00', '["public/partnership/new.php:374: /*", "public/partnership/new.php:395: ''[''.$appli.''] ''.getDolGlobalString(''PARTNERSHIP_AUTOREGISTER_NOTIF_MAIL_SUBJECT'', ''Partnership request''),", "public/partnership/new.php:411: }*/"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_BACKLINKS_TO_CHECK', 'string', NULL, 'partnership', 'Stores a pipe-separated list of URL patterns (regex) that must be present on a partner''s website as backlinks.', 'Set via partnership/admin/setup.php:80 and read at setup.php:178. Used in partnership/class/partnershiputils.class.php:569 in a preg_match call against fetched web content. Also controls visibility of url_to_check, count_last_url_check_error, and last_check_backlink fields in partnership.class.php. In public/partnership/new.php:620, the value is exploded by ''|'' to get the list of patterns.', 'When unset, backlink checking is inactive and related fields are hidden. When set, the scheduler checks partner websites for matching content and triggers warnings or cancellations on failure.', 'String: pipe-separated list of regex patterns to match against partner website content; empty/unset = backlink checking disabled.', 0, 0, 'partnership/admin/setup.php|partnership/admin/setup.php', 1, '164d03d029af42cbba7455e2d65b6231f556d9343e7bca9af1bb2b4f28541720', 'v2', '2026-04-21T11:16:15+00:00', '["partnership/admin/setup.php:80|write|dolibarr_set_const($db, \"PARTNERSHIP_BACKLINKS_TO_CHECK\", GETPOST(\"PARTNERSHIP_BACKLINKS_TO_CHECK\"), ''chaine'', 0, '''', $conf->entity);", "partnership/class/partnershiputils.class.php:569|check|if ($webcontent && getDolGlobalString(''PARTNERSHIP_BACKLINKS_TO_CHECK'') && preg_match(''/'' . getDolGlobalString(''PARTNERSHIP_BACKLINKS_TO_CHECK'').''/'', $webcontent)) {", "public/partnership/new.php:620|read|$listofkeytocheck = explode(''|'', getDolGlobalString(''PARTNERSHIP_BACKLINKS_TO_CHECK''));", "partnership/class/partnership.class.php:123|read|''url_to_check'' => array(''type'' => ''url'', ''label'' => ''UrlToCheck'', ''enabled'' => ''getDolGlobalString(\"PARTNERSHIP_BACKLINKS_TO_CHECK\")'', ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_EMAIL_TEMPLATE_AUTOREGISTER', 'string', NULL, 'public', 'Selects the email template label used to notify a member after self-registering as a partner.', 'Read in public/partnership/new.php:349 to build $labeltouse, which is passed to FormMail->getEMailTemplate() to fetch the email template used for the auto-registration confirmation mail. The actual send code that uses it is inside a commented-out block in this file, so on develop this constant is currently not wired to an active email send.', 'Setting it selects which stored email template (by label) is used for the partnership self-registration confirmation email; since the surrounding code is commented out, changing it currently has no visible effect until that code path is re-enabled.', 'Not specified in code; expected to be a template label string matching an email template stored via FormMail (module ''member'').', 1, 0, NULL, 1, '624cff83af5da4a8cf8559226c01e558ee62ee6813a11ed07fcda224bd2c25d7', 'v2', '2026-07-24T07:05:23+00:00', '["public/partnership/new.php:349|read|$labeltouse = $conf->global->PARTNERSHIP_EMAIL_TEMPLATE_AUTOREGISTER;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_ENABLE_PUBLIC', 'bool', NULL, 'partnership', 'Enables the public partnership registration page.', 'Configured via partnership/admin/website.php (multiple write occurrences). Checked in partnership/admin/website.php:152, :171, :224 to control UI display, and in public/partnership/new.php:87 to gate the public form — returning an error if the constant is not set.', 'When enabled, the public URL for partnership applications is activated; when disabled or unset, the public page is inaccessible.', '0 = public page disabled; 1 = public page enabled', 0, 0, 'partnership/admin/website.php|partnership/admin/website.php|partnership/admin/website.php|partnership/admin/website.php|partnership/admin/website.php|partnership/admin/website.php|partnership/admin/website.php', 1, 'ef7c91c46686e1361baa281e106ad077f6435bb47014465ad99ca7a4b67d05a9', 'v2', '2026-04-21T11:16:15+00:00', '["public/partnership/new.php:87|check|if (!getDolGlobalString(''PARTNERSHIP_ENABLE_PUBLIC'')) {", "partnership/admin/website.php:64|write|dolibarr_set_const($db, ''PARTNERSHIP_ENABLE_PUBLIC'', 1, ''chaine'', 0, '''', $conf->entity);", "partnership/admin/website.php:66|write|dolibarr_set_const($db, ''PARTNERSHIP_ENABLE_PUBLIC'', 0, ''chaine'', 0, '''', $conf->entity);", "partnership/admin/website.php:164|read|print ''<input type=\"hidden\" id=\"PARTNERSHIP_ENABLE_PUBLIC\" name=\"PARTNERSHIP_ENABLE_PUBLIC\" value=\"''.(!getDolGlobalString(''PARTNERSHIP_ENABLE_PUBLIC'') ? 0 : 1).''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_IS_MANAGED_FOR', 'string', NULL, 'partnership', 'Determines whether the partnership module links partnerships to third-party companies or to members.', 'Written by partnership/admin/setup.php:66. The selector at partnership/admin/setup.php:136-137 offers ''thirdparty'' and ''member'' options, defaulting to ''thirdparty''. Read in partnership/partnership_card.php:93, partnership/partnership_contact.php:66, partnership/partnership_agenda.php:99, and public/partnership/new.php:207 to switch object linkage and UI behaviour.', 'Changing this value switches partnership records to link to either third-party companies (''thirdparty'') or member records (''member''), affecting all partnership creation, display, and navigation pages.', '''thirdparty'' = partnerships linked to third-party companies (default); ''member'' = partnerships linked to member records.', 0, 0, 'partnership/admin/setup.php|partnership/admin/setup.php|partnership/admin/setup.php|partnership/admin/setup.php', 1, '0ee81ec4cc09cf28d8090f7dbfcb73fce92945db3cfdffaddf16e9e017d45dc7', 'v2', '2026-04-21T11:16:15+00:00', '["partnership/admin/setup.php:136|read|print ''<option value=\"thirdparty\" ''.((getDolGlobalString(''PARTNERSHIP_IS_MANAGED_FOR'', ''thirdparty'') == ''thirdparty'') ? ''selected'' : '''').''>''.$langs->trans(\"ThirdParty\").''</option>''", "partnership/admin/setup.php:137|read|print ''<option value=\"member\" ''.((getDolGlobalString(''PARTNERSHIP_IS_MANAGED_FOR'', ''thirdparty'') == ''member'') ? ''selected'' : '''').''>''.$langs->trans(\"Members\").''</option>'';", "public/partnership/new.php:207|check|if (getDolGlobalString(''PARTNERSHIP_IS_MANAGED_FOR'', ''thirdparty'') == ''thirdparty'') {", "partnership/partnership_card.php:93|read|$managedfor \t\t\t= getDolGlobalString(''PARTNERSHIP_IS_MANAGED_FOR'', ''thirdparty'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_MAIL_FROM', 'string', NULL, 'public', '''From'' email address used when sending the (currently disabled) partnership autoregistration notification email.', 'Only referenced inside a block comment (/* ... */ spanning public/partnership/new.php:374-411) in public/partnership/new.php, as the $from value passed to CMailFile; that whole code path is commented out and not executed.', 'Currently has no runtime effect: the only code path that reads it is commented out in public/partnership/new.php.', 'Free-form email address string.', 0, 0, NULL, 1, '267a1d9bdac57ac30caad1e747e179eccfacb92c05a8d4262e80b8e702e15520', 'v2', '2026-07-24T07:05:23+00:00', '["public/partnership/new.php:374: /*", "public/partnership/new.php:393: $from = getDolGlobalString(''PARTNERSHIP_MAIL_FROM'');", "public/partnership/new.php:411: }*/"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_MAX_BACKLINK_ERROR_FOR_CANCEL', 'string', NULL, 'partnership', 'Upper bound of consecutive backlink-check failures during which the warning email window stays open, before actual cancellation logic proceeds.', 'In partnership/class/partnershiputils.class.php:386, doWarningOfPartnershipIfDolibarrBacklinkNotfound() reads this int (default = PARTNERSHIP_MIN_BACKLINK_ERROR_FOR_CANCEL + 2) as $nbmaxbacklinkerrorforcancel, used together with the min threshold to bound the range of failure counts ($tmpcount) for which a warning email is sent (line 390).', 'Raising the value widens the window (number of consecutive failures) during which a warning email can still be sent for a partnership; it works in tandem with PARTNERSHIP_MIN_BACKLINK_ERROR_FOR_CANCEL.', 'integer = max consecutive backlink-check errors for warning window (default = min value + 2).', 1, 0, NULL, 1, 'f7428c1bee6d074e317e2c7b1527ca4826420ce3c306a4747dd1b15464c045e3', 'v2', '2026-07-24T07:05:23+00:00', '["partnership/class/partnershiputils.class.php:386|read|$nbmaxbacklinkerrorforcancel = (int) getDolGlobalString(''PARTNERSHIP_MAX_BACKLINK_ERROR_FOR_CANCEL'', (int) $nbminbacklinkerrorforcancel + 2);", "partnership/class/partnershiputils.class.php:390: if ($tmpcount > $nbminbacklinkerrorforcancel && $tmpcount <= $nbmaxbacklinkerrorforcancel) { // Send Warning Email"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_MAX_EXPIRATION_CANCEL_PER_CALL', 'string', NULL, 'partnership', 'Sets the maximum number of partnership expiration cancellations processed per scheduler call; defaults to 25 if unset.', 'Read at partnership/class/partnershiputils.class.php:89 with fallback: `$MAXPERCALL = (!getDolGlobalString(''PARTNERSHIP_MAX_EXPIRATION_CANCEL_PER_CALL'') ? 25 : $conf->global->PARTNERSHIP_MAX_EXPIRATION_CANCEL_PER_CALL)`. The docblock at line 72 documents this as the batch size for the scheduled cancellation action.', 'When unset, the scheduler processes at most 25 partnership expirations per call. Setting a higher or lower value changes the batch size for the auto-cancel scheduled task.', 'Integer; unset or 0 = 25 (default limit per call); any positive integer = custom batch limit.', 1, 0, NULL, 1, '702ac184b65cf176e69378666c3604e9421c650cfab9f872fd78bff0db0b3355', 'v2', '2026-04-21T11:16:15+00:00', '["* Action executed by scheduler to cancel status of partnership when subscription is expired + x days. (Max number of action batch per call = $conf->global->PARTNERSHIP_MAX_EXPIRATION_CANCEL_PER_CALL)", "$MAXPERCALL = (!getDolGlobalString(''PARTNERSHIP_MAX_EXPIRATION_CANCEL_PER_CALL'') ? 25 : $conf->global->PARTNERSHIP_MAX_EXPIRATION_CANCEL_PER_CALL); // Limit to 25 per call"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_MAX_WARNING_BACKLINK_PER_CALL', 'string', NULL, 'partnership', 'Caps the number of partnerships processed per scheduler call when checking for missing Dolibarr backlinks.', 'In partnership/class/partnershiputils.class.php:300, doWarningOfPartnershipIfDolibarrBacklinkNotfound() (a cron-callable method) reads this int (default 10) as $maxpercall, and the method''s docblock (line 285) explicitly documents it as ''Max number of action batch per call''; the loop breaks once this many partnerships have been processed (line 358-360).', 'Raising the value lets more partnerships be checked/warned-or-cancelled per scheduler run (at the cost of more emails/queries per batch); lowering it throttles the batch size, e.g. to avoid hitting email sending quotas.', 'integer = max partnerships processed per call (default 10).', 1, 0, NULL, 1, '211f4c1ee2d58fa7cc5842184cae8c07c95fe3556498dc71764f66ea452ed527', 'v2', '2026-07-24T07:05:23+00:00', '["partnership/class/partnershiputils.class.php:285  * (Max number of action batch per call = $conf->global->PARTNERSHIP_MAX_WARNING_BACKLINK_PER_CALL)", "partnership/class/partnershiputils.class.php:300|read|$maxpercall = getDolGlobalInt(''PARTNERSHIP_MAX_WARNING_BACKLINK_PER_CALL'', 10);", "partnership/class/partnershiputils.class.php:359: dol_syslog(\"We reach the limit of \".$maxpercall.\" partnership processed... to avoid to reach email quota.\", LOG_WARNING);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_MIN_BACKLINK_ERROR_FOR_CANCEL', 'string', NULL, 'partnership', 'Minimum consecutive backlink-check failures before a warning email is sent about an at-risk partnership (0 disables auto-email).', 'In partnership/class/partnershiputils.class.php:385, doWarningOfPartnershipIfDolibarrBacklinkNotfound() reads this int (default 3) as $nbminbacklinkerrorforcancel; the code comment at line 388 states ''If $nbminbacklinkerrorforemail = 0, no autoemail'', and it is only used to trigger a warning email when the failure count exceeds it but is still below PARTNERSHIP_MAX_BACKLINK_ERROR_FOR_CANCEL.', 'Raising the value delays the point at which the warning email is sent (partnership tolerates more missed backlink checks first); setting it to 0 disables the automatic warning email entirely per the code comment.', 'integer = min consecutive backlink-check errors before warning email (default 3); 0 = no autoemail.', 1, 0, NULL, 1, '958f87e325e2da74d5103ce54050dab5cde9a6a2483e67fa2d8fad3d39210682', 'v2', '2026-07-24T07:05:23+00:00', '["partnership/class/partnershiputils.class.php:385|read|$nbminbacklinkerrorforcancel = (int) getDolGlobalString(''PARTNERSHIP_MIN_BACKLINK_ERROR_FOR_CANCEL'', 3);", "partnership/class/partnershiputils.class.php:388: // If $nbminbacklinkerrorforemail = 0, no autoemail", "partnership/class/partnershiputils.class.php:390: if ($tmpcount > $nbminbacklinkerrorforcancel && $tmpcount <= $nbmaxbacklinkerrorforcancel) { // Send Warning Email"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_NBDAYS_AFTER_MEMBER_EXPIRATION_BEFORE_CANCEL', 'string', NULL, 'partnership', 'Defines the number of grace days after member subscription expiration before a partnership is automatically cancelled.', 'Set via partnership/admin/setup.php:77 and read at setup.php:149 and partnership/class/partnershiputils.class.php:99 as $gracedelay. A commented-out reference at partnershiputils.class.php:313 also shows its use as an integer grace delay.', 'When set, partnerships are cancelled only after the specified number of days past member expiration. Changing this value lengthens or shortens the grace period before auto-cancellation.', 'Integer (number of days); unset = implementation-defined default delay.', 0, 0, 'partnership/admin/setup.php|partnership/admin/setup.php|partnership/admin/setup.php', 1, '34c90f872d1990fc2a8e6e4edf03904cc31c02806b80cb3a284015b5250f8d57', 'v2', '2026-04-21T11:16:15+00:00', '["partnership/class/partnershiputils.class.php:99|read|$gracedelay = getDolGlobalString(''PARTNERSHIP_NBDAYS_AFTER_MEMBER_EXPIRATION_BEFORE_CANCEL'');", "partnership/admin/setup.php:77|write|dolibarr_set_const($db, \"PARTNERSHIP_NBDAYS_AFTER_MEMBER_EXPIRATION_BEFORE_CANCEL\", GETPOSTINT(\"PARTNERSHIP_NBDAYS_AFTER_MEMBER_EXPIRATION_BEFORE_CANCEL\"), ''chaine'', 0, '''', $conf->entity);", "/*$gracedelay = getDolGlobalInt(''PARTNERSHIP_NBDAYS_AFTER_MEMBER_EXPIRATION_BEFORE_CANCEL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_NEWFORM_AMOUNT', 'string', NULL, 'partnership', 'Sets the amount value pre-filled/displayed in the partnership request form field on the module''s public website configuration page.', 'Set via a plain text input in partnership/admin/website.php:186 with id/name ''PARTNERSHIP_NEWFORM_AMOUNT'', defaulting to empty string when unset.', 'Changing it alters the amount value shown/stored for the partnership new-form-amount field used by the Partnership module''s website form setup.', 'Free-text/numeric string, no explicit meaning comment found beyond the field label.', 0, 0, 'partnership/admin/website.php', 1, 'ec55c589c7fe5af605dc8ddcacff4f7b5f0ea49f609204a905f24eecaabb4e9c', 'v2', '2026-07-24T07:05:23+00:00', '["partnership/admin/website.php:186: print ''<input type=\"text\" class=\"right width75\" id=\"PARTNERSHIP_NEWFORM_AMOUNT\" name=\"PARTNERSHIP_NEWFORM_AMOUNT\" value=\"''.(!empty($conf->global->PARTNERSHIP_NEWFORM_AMOUNT) ? $conf->global->PARTNERSHIP_NEWFORM_AMOUNT : '''').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_NEWFORM_FORCECOUNTRYCODE', 'string', NULL, 'public', 'Forces a specific country to be pre-selected on the public new-partnership request form when no country was already posted.', 'Checked in public/partnership/new.php:628-629: if no $country_id was submitted and this constant is set, getCountry() is called with its value (interpreted as a 2-letter country code) to resolve the country id, taking priority over GeoIP-based detection.', 'Setting it forces a default country on the public partnership form instead of leaving it empty or relying on GeoIP detection.', '2-letter ISO country code string, passed as the ''2'' code-type argument to getCountry().', 0, 0, NULL, 1, '5c2a538b49521087e071d8951d708d99be28f0c165a7118cda7172f8181ac9c0', 'v2', '2026-07-24T07:05:23+00:00', '["public/partnership/new.php:628: if (!$country_id && getDolGlobalString(''PARTNERSHIP_NEWFORM_FORCECOUNTRYCODE'')) {", "public/partnership/new.php:629: $country_id = getCountry($conf->global->PARTNERSHIP_NEWFORM_FORCECOUNTRYCODE, ''2'', $db, $langs);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_NEWFORM_FORCETYPE', 'string', NULL, 'public', 'Forces a specific partnership type on the public registration form, hiding the type selector and pre-filling the value.', 'In public/partnership/new.php at lines 593-595, when set the type name is printed and a hidden input is injected; when not set the type selector is shown (line 599). The COMMENT at line 220 shows the intended usage: ''$partnership->typeid = $conf->global->PARTNERSHIP_NEWFORM_FORCETYPE ? $conf->global->PARTNERSHIP_NEWFORM_FORCETYPE : GETPOST(''typeid'', ''int'')''.', 'Setting this locks the partnership type to the specified ID on the public form; leaving it unset allows the user to choose.', 'Integer: ID of the partnership type to force; 0 or unset = user selects type', 1, 0, NULL, 1, '7448dce44069a668d18b05634943bf3fa0b066cc951dda1ff5ec4273f94bcda2', 'v2', '2026-04-21T13:50:40+00:00', '["public/partnership/new.php:220  //$partnership->typeid               = $conf->global->PARTNERSHIP_NEWFORM_FORCETYPE ? $conf->global->PARTNERSHIP_NEWFORM_FORCETYPE : GETPOST(''typeid'', ''int'');", "public/partnership/new.php:593|check|if (getDolGlobalInt(''PARTNERSHIP_NEWFORM_FORCETYPE'')) {", "public/partnership/new.php:594|read|print $listofpartnership[getDolGlobalInt(''PARTNERSHIP_NEWFORM_FORCETYPE'')];", "public/partnership/new.php:595|read|print ''<input type=\"hidden\" id=\"partnershiptype\" name=\"partnershiptype\" value=\"'' . getDolGlobalInt(''PARTNERSHIP_NEWFORM_FORCETYPE'').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_NEWFORM_PAYONLINE', 'string', NULL, 'public', 'Controls which online payment provider is offered to users after completing the public partnership registration form.', 'Configured via partnership/admin/website.php (line 205) with a selectarray of payment provider values. In public/partnership/new.php at lines 422-468, the value selects among ''all'', ''paybox'', ''paypal'', ''stripe'', or ''-1'' (none).', 'Changing this determines whether and which payment provider link is shown after partnership registration; ''-1'' suppresses online payment.', ''''' or unset = no payment link; ''-1'' = disabled; ''all'' = all providers; ''paybox'' = Paybox; ''paypal'' = PayPal; ''stripe'' = Stripe', 0, 0, 'partnership/admin/website.php', 1, '82b3ebb071ab5db88ace3e5f23b2097f37d25fafe762e423be205acfd553dc81', 'v2', '2026-04-21T13:50:40+00:00', '["partnership/admin/website.php:205|read|print $form->selectarray(\"PARTNERSHIP_NEWFORM_PAYONLINE\", $listofval, ...", "public/partnership/new.php:423|check|if (getDolGlobalString(''PARTNERSHIP_NEWFORM_PAYONLINE'') == ''all'') {", "public/partnership/new.php:438|read|} elseif (getDolGlobalString(''PARTNERSHIP_NEWFORM_PAYONLINE'') == ''paybox'') {", "public/partnership/new.php:453|read|} elseif (getDolGlobalString(''PARTNERSHIP_NEWFORM_PAYONLINE'') == ''paypal'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_NEWFORM_TEXT', 'string', NULL, 'public', 'Custom introductory text shown on the public new-partnership request form, overriding the default description.', 'Checked in public/partnership/new.php:535-536: if set, its value is passed through $langs->trans() and printed; otherwise the default ''NewPartnershipRequestDesc'' translated string (with MAIN_INFO_SOCIETE_MAIL) is shown.', 'Setting it replaces the default explanatory text on the public partnership request form with custom (translatable) text.', 'Free-form string, typically a language key or translatable text resolved via $langs->trans().', 0, 0, NULL, 1, '49a81ab9b15734287b3b31eaf0656356e9d634a25cc2f6f5a4555067836d7a01', 'v2', '2026-07-24T07:05:23+00:00', '["public/partnership/new.php:535: if (getDolGlobalString(''PARTNERSHIP_NEWFORM_TEXT'')) {", "public/partnership/new.php:536: print $langs->trans(getDolGlobalString(''PARTNERSHIP_NEWFORM_TEXT'')).\"<br>\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_PUBLIC_INTERFACE_TOPIC', 'string', NULL, 'public', 'Topic/subject text shown in the header of the public partnership request page.', 'Passed as the topic argument to htmlPrintOnlineHeader() in public/partnership/new.php:127 (llxHeaderVierge function), alongside the PARTNERSHIP_IMAGE_PUBLIC_REGISTRATION image constant.', 'Setting it changes the topic text displayed in the header banner of the public new-partnership form.', 'Free-form string used directly as the online header topic text.', 0, 0, NULL, 1, '1a2a6186c83ce655667145bd58923f906d4b13631f529a15715cd42cfd0db236', 'v2', '2026-07-24T07:05:23+00:00', '["public/partnership/new.php:127: htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''PARTNERSHIP_PUBLIC_INTERFACE_TOPIC''), ''PARTNERSHIP_IMAGE_PUBLIC_REGISTRATION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_SENDMAIL_IF_AUTO_CANCEL', 'string', NULL, 'partnership', 'Names the email template label used to notify a member when their partnership is auto-cancelled.', 'In partnership/class/partnershiputils.class.php:169, after a partnership is auto-cancelled, this string constant (default ''SendingEmailOnPartnershipCanceled'') is used as the email template label to send a notification to the member.', 'Setting it to a different template label changes which email template is used to notify the member of the auto-cancellation.', 'string = email template label to use (default ''SendingEmailOnPartnershipCanceled'').', 1, 0, NULL, 1, 'e14e9f32c5e4c4bb23829de4e9d2205b8c4502be16c2677869aaf468a0ff8995', 'v2', '2026-07-24T07:05:23+00:00', '["partnership/class/partnershiputils.class.php:169|read|$labeltemplate = ''(''.getDolGlobalString(''PARTNERSHIP_SENDMAIL_IF_AUTO_CANCEL'', ''SendingEmailOnPartnershipCanceled'').'')'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_SENDMAIL_IF_NO_LINK', 'string', NULL, 'partnership', 'Names the email template label used to warn a partner that their partnership will soon be cancelled due to a missing Dolibarr backlink.', 'In partnership/class/partnershiputils.class.php:395, inside doWarningOfPartnershipIfDolibarrBacklinkNotfound(), this string constant (default ''SendingEmailOnPartnershipWillSoonBeCanceled'') is used as the email template label sent to the partner when their backlink check has failed enough times to warrant a warning but not yet a cancellation.', 'Setting it to a different template label changes which email template is used for the ''will soon be cancelled'' warning message.', 'string = email template label to use (default ''SendingEmailOnPartnershipWillSoonBeCanceled'').', 1, 0, NULL, 1, '70e215dc6896ecd0fec8af89f3dda9020cbcf75a923c7aecd9821cbf4358afa0', 'v2', '2026-07-24T07:05:23+00:00', '["partnership/class/partnershiputils.class.php:395|read|$labeltemplate = ''(''.getDolGlobalString(''PARTNERSHIP_SENDMAIL_IF_NO_LINK'', ''SendingEmailOnPartnershipWillSoonBeCanceled'').'')'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PARTNERSHIP_URL_REDIRECT_SUBSCRIPTION', 'string', NULL, 'public', 'Defines the URL to redirect the user to after a partnership registration is successfully submitted.', 'The COMMENT in public/partnership/new.php:513 states ''If PARTNERSHIP_URL_REDIRECT_SUBSCRIPTION is set to url we never go here because a redirect was done to this url.'' At lines 414-415, when set the user is redirected to this URL. No admin UI write path is present.', 'Setting this redirects submitters to a custom URL on successful partnership registration; leaving it unset uses the default post-submission behavior.', 'String: absolute URL for post-submission redirect; when set, the default confirmation page is never shown', 1, 0, NULL, 1, 'dca2d6e8befc08573e2eb9e2afd54f27c396da860fb79553833cb254fb069cbf', 'v2', '2026-04-21T13:50:40+00:00', '["public/partnership/new.php:513  // If PARTNERSHIP_URL_REDIRECT_SUBSCRIPTION is set to url we never go here because a redirect was done to this url.", "public/partnership/new.php:414|read|} elseif (getDolGlobalString(''PARTNERSHIP_URL_REDIRECT_SUBSCRIPTION'')) {", "public/partnership/new.php:415|read|$urlback = getDolGlobalString(''PARTNERSHIP_URL_REDIRECT_SUBSCRIPTION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYBOX_BANK_ACCOUNT_FOR_PAYMENTS', 'string', NULL, 'public', 'Defines the bank account ID used to record Paybox online payments.', 'Read via getDolGlobalString(''PAYBOX_BANK_ACCOUNT_FOR_PAYMENTS'') repeatedly in public/payment/paymentok.php (lines 708, 1103, 1253, 1398, 1534, 1773, 1995).', 'Changing the account ID changes which bank account Paybox payments are recorded against in $accountid/$bankaccountid.', NULL, 0, 0, NULL, 1, 'cc7ac1b1e06aadb7c4040ef3d9cbd136b71b2e22fe0c13021c2fb453d8bdf47c', 'v2', '2026-07-24T06:41:12+00:00', '["$accountid = getDolGlobalString(''PAYBOX_BANK_ACCOUNT_FOR_PAYMENTS'');", "$bankaccountid = getDolGlobalString(''PAYBOX_BANK_ACCOUNT_FOR_PAYMENTS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYBOX_PAYMENT_MODE_FOR_PAYMENTS', 'string', NULL, 'public', 'Specifies the payment mode ID used to record Paybox payments in the Dolibarr payment system.', 'Read as an integer at public/payment/paymentok.php at lines 579, 1022, 1168, 1323, 1462, 1701, and 1919 and assigned to $paymentTypeId for recording payments. No admin UI write found in this file.', 'Setting this to a valid payment mode ID ensures Paybox payments are recorded with the correct payment type.', 'An integer payment mode ID.', 1, 0, NULL, 1, '71d39d1c26f5ddf9cedcdadb9d9c121cd0055b7ce17c0ee05e2964a63d03813e', 'v2', '2026-04-21T13:50:40+00:00', '["public/payment/paymentok.php:579|read|$paymentTypeId = getDolGlobalInt(''PAYBOX_PAYMENT_MODE_FOR_PAYMENTS'');", "public/payment/paymentok.php:1022|read|$paymentTypeId = getDolGlobalInt(''PAYBOX_PAYMENT_MODE_FOR_PAYMENTS'');", "public/payment/paymentok.php:1168|read|$paymentTypeId = getDolGlobalInt(''PAYBOX_PAYMENT_MODE_FOR_PAYMENTS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_ADDDAYS', 'string', NULL, 'admin', 'Number of days added to the current date to compute the execution date for bank transfer (credit transfer) orders.', 'Set via admin/paymentbybanktransfer.php:115, read as an integer default 0 at :210, and used in compta/prelevement/create.php:332 as $delayindays for credit transfer creation.', 'Increasing this value delays the execution date of bank transfer orders by the specified number of days.', 'Integer number of days (default 0 = no additional delay).', 0, 0, 'admin/paymentbybanktransfer.php|admin/paymentbybanktransfer.php', 1, 'ffd6418a96c59ffdc7a4f6516c71b23077ae560db8ed2a672edf92cf2a7a175f', 'v2', '2026-04-21T11:16:15+00:00', '["admin/paymentbybanktransfer.php:115|write|$res = dolibarr_set_const($db, \"PAYMENTBYBANKTRANSFER_ADDDAYS\", GETPOST(\"PAYMENTBYBANKTRANSFER_ADDDAYS\"), ''chaine'', 0, '''', $conf->entity);", "admin/paymentbybanktransfer.php:210|read|$addDaysValue = getDolGlobalInt(''PAYMENTBYBANKTRANSFER_ADDDAYS'', 0);", "compta/prelevement/create.php:332|read|$delayindays = getDolGlobalInt(''PAYMENTBYBANKTRANSFER_ADDDAYS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_CUSTOM_CATEGORY_PURPOSE', 'string', NULL, 'compta', 'Overrides the SEPA credit-transfer XML CategoryPurpose code (CtgyPurp) sent in the ISO20022 payment file.', 'Read in compta/prelevement/class/bonprelevement.class.php:2573 with default ''CORE''; the preceding comment lists example category codes.', 'Changing it changes the CtgyPurp/Cd value written into the generated SEPA credit-transfer XML, which banks use to categorize the payment purpose.', 'String: default ''CORE''; comment lists examples ''CORE, TREA, SUPP, ...''.', 1, 0, NULL, 1, '5b1ef7e8497aff9e59e018291c9d51ea02216827c9dfd1d104295085d2f0339d', 'v2', '2026-07-24T07:05:23+00:00', '["compta/prelevement/class/bonprelevement.class.php:2572|read|// Set $categoryPurpose: CORE, TREA, SUPP, ...", "compta/prelevement/class/bonprelevement.class.php:2573|read|$categoryPurpose = getDolGlobalString(''PAYMENTBYBANKTRANSFER_CUSTOM_CATEGORY_PURPOSE'', ''CORE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_CUSTOM_LOCAL_INSTRUMENT', 'string', NULL, 'compta', 'Overrides the SEPA credit-transfer ''LocalInstrument'' code used when building the direct-debit/credit-transfer XML.', 'Read in compta/prelevement/class/bonprelevement.class.php:2766 with default ''CORE'', alongside related PAYMENTBYBANKTRANSFER_* constants controlling SEPA XML generation.', 'Changing it changes the LclInstrm/Cd value in the generated SEPA XML, affecting which local clearing scheme the bank applies.', 'String: default ''CORE'' (SEPA core scheme).', 1, 0, NULL, 1, '37515c3c4582404c1aa9ee1942fcb7a59cd277a89551749955ddc7d019d6a4f6', 'v2', '2026-07-24T07:05:23+00:00', '["compta/prelevement/class/bonprelevement.class.php:2766|read|$localInstrument = getDolGlobalString(''PAYMENTBYBANKTRANSFER_CUSTOM_LOCAL_INSTRUMENT'', ''CORE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_END_TO_END', 'string', NULL, 'admin', 'Would store the SEPA ''End to End'' reference field for bank-transfer payments, but the write path is currently disabled.', 'The occurrence in admin/paymentbybanktransfer.php:105 is inside a /* ... */ commented-out block (confirmed lines 100-112), alongside the related PAYMENTBYBANKTRANSFER_USTRD constant, so the admin setup form does not currently save this value.', 'Currently has no effect via the admin UI since the corresponding dolibarr_set_const() call is commented out.', 'Not specified beyond the constant name suggesting a SEPA ''End to End'' reference string.', 1, 0, 'admin/paymentbybanktransfer.php', 1, '1b54f0bd82f1024ce89a96e1fc9957582ee7051e8553b3b148f6e7b177eceafb', 'v2', '2026-07-24T07:05:23+00:00', '["admin/paymentbybanktransfer.php:105|write (in commented block)|$res = dolibarr_set_const($db, \"PAYMENTBYBANKTRANSFER_END_TO_END\", GETPOST(\"PAYMENTBYBANKTRANSFER_END_TO_END\"), ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_FORCE_HIGH_PRIORITY', 'string', NULL, 'compta', 'Forces the SEPA credit-transfer XML instruction priority (InstrPrty) to ''HIGH'' instead of the default ''NORM''.', 'Checked in compta/prelevement/class/bonprelevement.class.php:2566, directly above the code comment documenting the two possible values.', 'When set, generated SEPA credit-transfer XML files declare InstrPrty as HIGH instead of NORM, which affects how the bank processes payment priority.', 'Bool: comment states ''Can be NORM for normal or HIGH for high priority level''; truthy sets InstrPrty to HIGH, otherwise NORM.', 1, 0, NULL, 1, 'ecc145486465147b7c6166b8004158156e66c153056fef1fc87094aa6172dec5', 'v2', '2026-07-24T07:05:23+00:00', '["compta/prelevement/class/bonprelevement.class.php:2565|read|// Can be ''NORM'' for normal or ''HIGH'' for high priority level", "compta/prelevement/class/bonprelevement.class.php:2566|check|if (getDolGlobalString(''PAYMENTBYBANKTRANSFER_FORCE_HIGH_PRIORITY'')) { $instrprty = ''HIGH''; } else { $instrprty = ''NORM''; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_ICS', 'string', NULL, 'admin', 'Stores the ICS (Identifiant Créancier SEPA) code used for direct debit / bank transfer payment orders.', 'Written and read in admin/paymentbybanktransfer.php:92 and :183. The value is saved via dolibarr_set_const and displayed in an admin text input, confirming it is configured through the admin UI.', 'Changing this value updates the SEPA creditor identifier embedded in generated direct debit files, which is required to be correct for bank processing.', 'String; a valid SEPA ICS/creditor identifier code.', 0, 0, 'admin/paymentbybanktransfer.php|admin/paymentbybanktransfer.php', 1, '660124ffd0ac03a5932f5f01c1b3b003c9e02c368be0acab3cf0b62d3977b4fc', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"PAYMENTBYBANKTRANSFER_ICS\", GETPOST(\"PAYMENTBYBANKTRANSFER_ICS\"), ''chaine'', 0, '''', $conf->entity);", "print ''<input type=\"text\" name=\"PAYMENTBYBANKTRANSFER_ICS\" value=\"''.$conf->global->PAYMENTBYBANKTRANSFER_ICS.''\" size=\"15\" ></td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_ID_BANKACCOUNT', 'string', NULL, 'compta', 'Defines the bank account ID used for bank-transfer type payment orders (prelevement ''bon'').', 'Set via admin UI at admin/paymentbybanktransfer.php:68/176, guarded in core/lib/prelevement.lib.php:108, and read in compta/prelevement/class/bonprelevement.class.php:624/1122/1899/2735 to pick between this and PRELEVEMENT_ID_BANKACCOUNT based on type == ''bank-transfer''.', 'When set, bank-transfer type payment orders use this bank account instead of PRELEVEMENT_ID_BANKACCOUNT (used for direct debit type).', NULL, 0, 0, 'admin/paymentbybanktransfer.php|admin/paymentbybanktransfer.php', 1, '2351b2ea76d3c5bdd65a813e849d3275c97fc266ac324c73088d92032829ab34', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''PAYMENTBYBANKTRANSFER_ID_BANKACCOUNT'')) {", "$fk_bank_account = ($this->type == ''bank-transfer'' ? getDolGlobalInt(''PAYMENTBYBANKTRANSFER_ID_BANKACCOUNT'') : getDolGlobalInt(''PRELEVEMENT_ID_BANKACCOUNT''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_USER', 'string', NULL, 'admin', 'Stores the Dolibarr user ID responsible for generating bank transfer (credit transfer) files.', 'Set via admin/paymentbybanktransfer.php and read as a user selector. Checked in core/lib/prelevement.lib.php:112 to block file generation if absent.', 'If unset, bank transfer file generation is blocked; the designated user receives related notifications or responsibilities.', 'A valid Dolibarr user ID (integer stored as string). Empty string means no user assigned.', 0, 0, 'admin/paymentbybanktransfer.php|admin/paymentbybanktransfer.php', 1, '935003ed9f0f829bfa977c5bd497de47d6f0ea206eaeebe24ca5f8e82477673b', 'v2', '2026-04-21T13:29:58+00:00', '["admin/paymentbybanktransfer.php:97|write|$res = dolibarr_set_const($db, \"PAYMENTBYBANKTRANSFER_USER\", GETPOST(\"PAYMENTBYBANKTRANSFER_USER\"), ''chaine'', 0, '''', $conf->entity);", "core/lib/prelevement.lib.php:112|check|if (!getDolGlobalString(''PAYMENTBYBANKTRANSFER_USER'')) {", "admin/paymentbybanktransfer.php:191|read|print $form->select_dolusers(getDolGlobalString(''PAYMENTBYBANKTRANSFER_USER''), ''PAYMENTBYBANKTRANSFER_USER'', 1, null, 0, '''', '''', ''0'', 0, 0, '''', 0, '''', ''minwidth200 maxwidth500'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTBYBANKTRANSFER_USTRD', 'string', NULL, 'admin', 'Would store the SEPA ''Unstructured Remittance Information'' (USTRD) field for bank-transfer payments, but the write path is currently disabled.', 'The occurrence in admin/paymentbybanktransfer.php:110 is inside the same /* ... */ commented-out block as PAYMENTBYBANKTRANSFER_END_TO_END (confirmed lines 100-112), so the admin setup form does not currently save this value.', 'Currently has no effect via the admin UI since the corresponding dolibarr_set_const() call is commented out.', 'Not specified beyond the constant name suggesting a SEPA unstructured remittance/reference string.', 1, 0, 'admin/paymentbybanktransfer.php', 1, '54ad6e69ff80d99a74580f3c943c270e3dbf33b11e475f79b2419726f6ee3f59', 'v2', '2026-07-24T07:05:23+00:00', '["admin/paymentbybanktransfer.php:110|write (in commented block)|$res = dolibarr_set_const($db, \"PAYMENTBYBANKTRANSFER_USTRD\", GETPOST(\"PAYMENTBYBANKTRANSFER_USTRD\"), ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTORDER_ADDON_PDF', 'string', NULL, 'admin', 'Name of the PDF document template used to generate payment order (bank transfer / direct debit) documents.', 'Checked in admin/paymentbybanktransfer.php:329 and admin/prelevement.php:342 to mark which installed PDF model is currently selected/active for payment orders on the corresponding setup screens.', 'Changing it selects a different PDF template class for generating payment order (prelevement/virement) documents.', 'String matching the name of an installed PaymentOrder PDF model/template.', 0, 0, 'admin/paymentbybanktransfer.php|admin/prelevement.php', 1, '9c913d3d2062d9b9e8cf558807ad9a3671a8adda2b93677bed28f6086db94505', 'v2', '2026-07-24T07:05:23+00:00', '["admin/paymentbybanktransfer.php:329: if (getDolGlobalString(''PAYMENTORDER_ADDON_PDF'') == $name)", "admin/prelevement.php:342: if (getDolGlobalString(''PAYMENTORDER_ADDON_PDF'') == $name)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTS_FOURN_REPORT_GROUP_BY_MOD', 'string', NULL, 'core', 'Groups supplier payment report lines by payment mode in the generated payment report PDF.', 'Set via admin UI at supplier_invoice/admin/supplier_payment.php:153/476, checked in core/modules/rapport/pdf_paiement.class.php:341/545/592/619, with comment at line 340: ''If global param PAYMENTS_FOURN_REPORT_GROUP_BY_MOD is set, payment fourn are ordered by paiement_code''.', 'When enabled, supplier payment rows in the report PDF are ordered/grouped by paiement_code instead of the default ordering.', NULL, 0, 0, 'supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php', 1, '7ccf8dd690ca742189428407713670759145eb70d819ec15a7b12f2e39b9c438', 'v2', '2026-07-24T06:41:12+00:00', '["// If global param PAYMENTS_FOURN_REPORT_GROUP_BY_MOD is set, payment fourn are ordered by paiement_code", "if (getDolGlobalString(''PAYMENTS_FOURN_REPORT_GROUP_BY_MOD'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENTS_REPORT_GROUP_BY_MOD', 'string', NULL, 'core', 'When enabled, groups and orders payments by payment mode (paiement_code) in the payments PDF report.', 'Comment in core/modules/rapport/pdf_paiement.class.php:298: ''If global param PAYMENTS_REPORT_GROUP_BY_MOD is set, payment are ordered by paiement_code''. Checked at lines 299, 545, 592, and 619 of pdf_paiement.class.php. Written via admin/payment.php:97.', 'Enabling this constant reorders payments in the PDF report by payment mode. Disabling it reverts to the default ordering.', 'Non-empty/non-zero = group by payment mode. 0 or empty = default ordering.', 0, 0, 'admin/payment.php|admin/payment.php', 1, '0c1b6a8a315cbc78a9f8853d0923acc76a3b889a28b9fa5b1e5da867d927c6ab', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/rapport/pdf_paiement.class.php:298  // If global param PAYMENTS_REPORT_GROUP_BY_MOD is set, payment are ordered by paiement_code", "core/modules/rapport/pdf_paiement.class.php:299|check|if (getDolGlobalString(''PAYMENTS_REPORT_GROUP_BY_MOD'')) {", "admin/payment.php:97|write|$res = dolibarr_set_const($db, \"PAYMENTS_REPORT_GROUP_BY_MOD\", GETPOSTINT(''PAYMENTS_REPORT_GROUP_BY_MOD''), ''chaine'', 0, '''', $conf->entity);", "admin/payment.php:294|read|print $form->selectyesno(\"PAYMENTS_REPORT_GROUP_BY_MOD\", getDolGlobalInt(''PAYMENTS_REPORT_GROUP_BY_MOD''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENT_ADDON', 'string', NULL, 'compta', 'Defines which numbering module class generates customer payment references, and is used to identify the active payment numbering submodule.', 'Set via admin UI at admin/payment.php:56/87 (default ''mod_payment_cicada.php'') and checked in admin/payment.php:55/222/251, supplier_invoice/admin/supplier_payment.php:323 and compta/paiement/class/paiement.class.php:1273/1281.', 'Changing it selects a different reference-numbering module for customer payments; the admin page uses it to identify which module file is ''the one used'' when listing errors.', 'default: ''mod_payment_cicada.php''', 0, 0, 'admin/payment.php|admin/payment.php|admin/payment.php|supplier_invoice/admin/supplier_payment.php|admin/payment.php|admin/payment.php', 1, '673282217c58b01342d2ceda84374bdfd5838269a6a9dc5cdb20718517a6c9ff', 'v2', '2026-07-24T06:41:12+00:00', '["$conf->global->PAYMENT_ADDON = ''mod_payment_cicada.php'';", "if (getDolGlobalString(''PAYMENT_ADDON'') == $file || getDolGlobalString(''PAYMENT_ADDON'') . ''.php'' == $file) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENT_ANT_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the ''Ant'' automatic numbering module for payment references.', 'Used exclusively within core/modules/payment/mod_payment_ant.php. At line 99 it is shown in a configuration input; at line 145 it is loaded as the active mask for payment reference generation.', 'Changing the mask alters the format of newly generated payment reference numbers; existing references are unaffected.', 'Any mask string accepted by the payment numbering module.', 1, 0, NULL, 1, 'b8e536b8d547ca91249c090729a936b5792a6050bfd3bafc629163d1f1a69ad9', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/payment/mod_payment_ant.php:99|read|value=\"''.getDolGlobalString(''PAYMENT_ANT_MASK'').''\"", "core/modules/payment/mod_payment_ant.php:145|read|$mask = getDolGlobalString(''PAYMENT_ANT_MASK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENT_NEWFORM_TEXT', 'string', NULL, 'public', 'Sets a text (or translation key in parentheses) displayed at the bottom of the public payment form.', 'Checked at public/payment/newpayment.php:1088, :1091, and :1094; if the value is wrapped in parentheses it is treated as a translation key, otherwise it is printed as-is. No admin UI write found.', 'When set, the specified text or its translation appears at the bottom of the public payment form.', 'A plain text string, or a translation key wrapped in parentheses e.g. ''(MyKey)''.', 1, 0, NULL, 1, '5f402f57a572444f3f4367d1ca65d6854842b3585a990c3df4c7b0fa089dca6a', 'v2', '2026-04-21T13:50:40+00:00', '["public/payment/newpayment.php:1088|check|if (getDolGlobalString(''PAYMENT_NEWFORM_TEXT'')) {", "public/payment/newpayment.php:1091|check|if (preg_match(''/^\\((.*)\\)$/'', getDolGlobalString(''PAYMENT_NEWFORM_TEXT''), $reg)) {", "public/payment/newpayment.php:1094|read|$text .= getDolGlobalString(''PAYMENT_NEWFORM_TEXT'') . \"<br>\\n\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENT_SECURITY_ACCEPT_ANY_TOKEN', 'string', NULL, 'public', 'Allows the online payment page to accept any security token instead of validating against PAYMENT_SECURITY_TOKEN.', 'Checked with getDolGlobalString(''PAYMENT_SECURITY_ACCEPT_ANY_TOKEN'') in stripe/admin/stripe.php:661, paypal/admin/paypal.php:321 and enforced in public/payment/newpayment.php:381 as a negated guard.', 'When enabled, the token check normally performed in public/payment/newpayment.php is bypassed, per the negated condition ''!getDolGlobalString(...)'' guarding the strict check.', NULL, 0, 0, 'stripe/admin/stripe.php|paypal/admin/paypal.php', 1, 'a3e675620e3bf803b6678d11dfc62bf547e56cd0ee3fe003acca8dfcdfab254b', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''PAYMENT_SECURITY_ACCEPT_ANY_TOKEN'')) {", "if (!getDolGlobalString(''PAYMENT_SECURITY_ACCEPT_ANY_TOKEN'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENT_SECURITY_TOKEN', 'string', NULL, 'core', 'Sets the security token required to validate access to public online payment pages.', 'Set via admin UI in paypal/admin/paypal.php:112/317 and stripe/admin/stripe.php:163/657, checked across many public pages including public/payment/newpayment.php:369, public/project/suggestbooth.php:488, public/eventorganization/attendee_new.php:640 and core/tpl/onlinepaymentlinks.tpl.php:45.', 'Changing it invalidates previously generated payment links relying on the old token value, since it is checked as a match/presence condition wherever online payment links are validated.', NULL, 0, 0, 'stripe/admin/stripe.php|paypal/admin/paypal.php|paypal/admin/paypal.php|stripe/admin/stripe.php', 1, 'b9953bc46b6f98c87550ae4ad3a7031c5bb35f76a922b3317ef6c3cc5da123fd', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"PAYMENT_SECURITY_TOKEN\", GETPOST(''PAYMENT_SECURITY_TOKEN'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''PAYMENT_SECURITY_TOKEN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENT_SECURITY_TOKEN_UNIQUE', 'string', NULL, 'admin', 'Constant referenced only inside commented-out (dead) code on the Security admin page that would have flagged whether Stripe/Paypal ''unique security token'' option is enabled.', 'Both occurrences at admin/system/security.php:751 and :763 sit inside a /* ... */ PHP comment block (module admin, page admin/system/security.php); the surrounding logic is entirely disabled and not executed.', 'No effect: the code paths reading this constant are commented out, so setting it currently changes nothing in the running application.', 'Exact behavior unclear from code alone [SPECULATION] — no live usage found; the constant appears vestigial/dead code.', 0, 0, 'admin/system/security.php|admin/system/security.php', 1, '39b17ca2131eb99c6723fda56b47899182dd55d6ad3fc1448293b3d9216e7424', 'v2', '2026-07-24T07:05:23+00:00', '["admin/system/security.php:751|check|if (!getDolGlobalString(''PAYMENT_SECURITY_TOKEN_UNIQUE'')) {", "admin/system/security.php:763|check|if (!getDolGlobalString(''PAYMENT_SECURITY_TOKEN_UNIQUE'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYMENT_USE_NEW_PRICE_FOR_CONTRACTLINES', 'bool', NULL, 'public', 'When paying a contract line online, recomputes the amount from the linked product''s current price instead of using the contract line''s stored total.', 'Checked in public/payment/newpayment.php:1444; when the contract line has a linked product ($contractline->fk_product) and this constant is set, the code fetches the Product and recalculates pu_ht/pu_ttc/price_base_type from it (using multiprices if PRODUIT_MULTIPRICES is active) instead of using $contractline->total_ttc.', 'Enabling it makes the public online payment page use the product''s current price (or the customer''s multiprice tier) for contract line payments rather than the amount stored on the contract line, which can change the amount charged if product prices changed since the contract line was created.', 'Boolean-like: truthy recomputes the payment amount from the linked product''s current price instead of the contract line''s stored total.', 1, 0, NULL, 1, 'fc6808430891f8eec815048cb21a870c47aab9bc4e4700ab6fb2839266729341', 'v2', '2026-07-24T07:05:23+00:00', '["public/payment/newpayment.php:1444|check|if ($contractline->fk_product && getDolGlobalString(''PAYMENT_USE_NEW_PRICE_FOR_CONTRACTLINES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_ADD_PAYMENT_URL', 'string', NULL, 'paypal', 'Controls whether a payment URL is added to PayPal-related pages or emails.', 'Written at paypal/admin/paypal.php line 91 and rendered as a yes/no selector at line 276. It is a boolean-style string constant set through the PayPal admin configuration page.', 'When enabled, a payment URL is included in the relevant context; when disabled it is omitted.', '0 = do not add payment URL; 1 = add payment URL', 0, 0, 'paypal/admin/paypal.php|paypal/admin/paypal.php', 1, '818220520da578b306fd011df3797ae492f857c7dd4e33d1440cb57e46b85981', 'v2', '2026-04-21T11:16:15+00:00', '["$result = dolibarr_set_const($db, \"PAYPAL_ADD_PAYMENT_URL\", GETPOST(''PAYPAL_ADD_PAYMENT_URL'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "print $form->selectyesno(\"PAYPAL_ADD_PAYMENT_URL\", getDolGlobalString(''PAYPAL_ADD_PAYMENT_URL''), 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_ALLOW_NOTES', 'bool', NULL, 'paypal', 'When enabled, allows buyers to add a note during PayPal checkout by setting ALLOWNOTE=0 in the PayPal NVP payment request.', 'Checked in paypal/lib/paypal.lib.php:218-220: `if (getDolGlobalString(''PAYPAL_ALLOW_NOTES'')) { $nvpstr .= "&ALLOWNOTE=0"; }`, part of building the PayPal SetExpressCheckout NVP API request string. No admin/*.php write found for this constant.', 'Toggles the ALLOWNOTE parameter sent to PayPal''s Express Checkout API; the parameter is only added to the request when this constant is truthy.', 'Boolean-like: truthy value adds ''&ALLOWNOTE=0'' to the PayPal NVP request string.', 1, 0, NULL, 1, 'e5ba33282b35b89e153d040584bde6079d553bb2d3e709913f2537c657a248ca', 'v2', '2026-07-24T07:05:23+00:00', '["paypal/lib/paypal.lib.php:218|check|if (getDolGlobalString(''PAYPAL_ALLOW_NOTES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_API_EXPRESS', 'string', NULL, 'paypal', 'Yes/no admin setting for the PayPal module enabling PayPal Express Checkout in the API integration.', 'Set via a yes/no form field in paypal/admin/paypal.php:241-242 on the PayPal module setup page, labeled with the langs key ''PAYPAL_API_EXPRESS''.', 'Toggling it switches the PayPal integration to use (or not use) the Express Checkout API flow.', 'Boolean (yes/no) via $form->selectyesno.', 0, 0, 'paypal/admin/paypal.php', 1, 'fdfbd0e1d8e9aa6ffb5270a1aa6c69a7726b8977cf8fac6de474487a46837e01', 'v2', '2026-07-24T07:05:23+00:00', '["paypal/admin/paypal.php:241: print ''<span class=\"fieldrequired\">''.$langs->trans(\"PAYPAL_API_EXPRESS\").''</span></td><td>'';", "paypal/admin/paypal.php:242: print $form->selectyesno(\"PAYPAL_API_EXPRESS\",$conf->global->PAYPAL_API_EXPRESS);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_API_INTEGRAL_OR_PAYPALONLY', 'string', NULL, 'paypal', 'Selects the PayPal payment mode: integral checkout (hosted form), PayPal-only button, or credit-card-only mode.', 'Written via paypal/admin/paypal.php:83 and read at line 242 in a select array with keys ''integral'' and ''paypalonly''. Checked in paypal/lib/paypal.lib.php at lines 87, 94, 99, and 104 for '''', ''paypalonly'', ''integral'', and ''cconly'' respectively. Also checked in public/payment/newpayment.php.', 'The chosen mode determines which PayPal checkout flow is invoked; an unrecognized or empty value falls back to a default branch at paypal.lib.php:87.', '''integral'' = full hosted PayPal checkout; ''paypalonly'' = PayPal button only; ''cconly'' = credit card only; empty = default fallback.', 0, 0, 'paypal/admin/paypal.php|paypal/admin/paypal.php', 1, '29ed555009d3934e03673a72f74253190a3c0df6c52b710faa90a7b3abc841a5', 'v2', '2026-04-21T11:16:15+00:00', '["print $form->selectarray(\"PAYPAL_API_INTEGRAL_OR_PAYPALONLY\", array(''integral''=> $langs->trans(''PaypalModeIntegral''), ''paypalonly''=> $langs->trans(''PaypalModeOnlyPaypal'')), getDolG...", "if (getDolGlobalString(''PAYPAL_API_INTEGRAL_OR_PAYPALONLY'') == ''paypalonly'') {", "if (getDolGlobalString(''PAYPAL_API_INTEGRAL_OR_PAYPALONLY'') == ''integral'') {", "if (getDolGlobalString(''PAYPAL_API_INTEGRAL_OR_PAYPALONLY'') == ''cconly'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_API_PASSWORD', 'string', NULL, 'paypal', 'Stores the PayPal API password credential used for authenticating PayPal NVP API calls.', 'Configured via the admin UI at paypal/admin/paypal.php and read by paypal/lib/paypal.lib.php:472, paypalfunctions.lib.php:62, and public/payment/paymentok.php:94 to authenticate PayPal API requests.', 'Without a valid API password, PayPal payment processing will fail. Changing this to an incorrect value breaks all PayPal-related transactions.', 'String (PayPal API password credential).', 0, 0, 'paypal/admin/paypal.php|paypal/admin/paypal.php', 1, '95e05cdac70cfacd5d53485bb44415691d9cbedd53f4144f5cc3194ae61f8187', 'v2', '2026-04-21T11:16:15+00:00', '["paypal/admin/paypal.php:63|write|$result = dolibarr_set_const($db, \"PAYPAL_API_PASSWORD\", GETPOST(''PAYPAL_API_PASSWORD'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "paypal/lib/paypal.lib.php:472|read|$PAYPAL_API_PASSWORD = getDolGlobalString(''PAYPAL_API_PASSWORD'');", "paypal/lib/paypalfunctions.lib.php:62|read|$PAYPAL_API_PASSWORD = getDolGlobalString(''PAYPAL_API_PASSWORD'');", "public/payment/paymentok.php:94|read|$PAYPAL_API_PASSWORD = getDolGlobalString(''PAYPAL_API_PASSWORD'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_API_SANDBOX', 'string', NULL, 'paypal', 'Switches the PayPal payment integration between sandbox (test) and live mode.', 'Configured via paypal/admin/paypal.php. When set, sandbox API endpoints are used in paypal/lib/paypal.lib.php:462 and paypal/lib/paypalfunctions.lib.php:52. Read and written in 10 occurrences. The commented-out check in societe/paymentmodes.php:908 confirms the sandbox intent.', 'When set, PayPal operates in test/sandbox mode using test credentials; when unset, live PayPal API calls are made.', '0 or unset = live mode; non-empty = sandbox/test mode', 0, 0, 'paypal/admin/paypal.php|paypal/admin/paypal.php', 1, 'b9d6b77c34b3a32f84dd35410e5e104c99e7a250ee8b556df1bd881bd24caf90', 'v2', '2026-04-21T11:16:15+00:00', '["paypal/lib/paypal.lib.php:462|check|if (getDolGlobalString(''PAYPAL_API_SANDBOX'')/* || GETPOST(''forcesandbox'', ''alpha'') */) {\t\t// We can force sand box with param ''forcesandbox''", "paypal/lib/paypalfunctions.lib.php:52|check|if (getDolGlobalString(''PAYPAL_API_SANDBOX'')/* || GETPOST(''forcesandbox'', ''alpha'') */) {\t\t// We can force sand box with param ''forcesandbox''", "paypal/admin/paypal.php:134|write|$res = dolibarr_set_const($db, \"PAYPAL_API_SANDBOX\", $liveenable, ''yesno'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_API_SIGNATURE', 'string', NULL, 'paypal', 'Stores the PayPal API signature credential used for authenticating PayPal NVP API calls.', 'Configured via the admin UI at paypal/admin/paypal.php and read by paypal/lib/paypal.lib.php:473, paypalfunctions.lib.php:63, and public/payment/paymentok.php:95 to authenticate PayPal API requests.', 'Without a valid API signature, PayPal payment processing will fail. Changing this to an incorrect value breaks all PayPal-related transactions.', 'String (PayPal API signature credential).', 0, 0, 'paypal/admin/paypal.php|paypal/admin/paypal.php', 1, '3581b421665bc932b342fa695c243d4a62f9e9fd2cbf2c94b22a0f742ef6a572', 'v2', '2026-04-21T11:16:15+00:00', '["paypal/admin/paypal.php:67|write|$result = dolibarr_set_const($db, \"PAYPAL_API_SIGNATURE\", GETPOST(''PAYPAL_API_SIGNATURE'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "paypal/lib/paypal.lib.php:473|read|$PAYPAL_API_SIGNATURE = getDolGlobalString(''PAYPAL_API_SIGNATURE'');", "paypal/lib/paypalfunctions.lib.php:63|read|$PAYPAL_API_SIGNATURE = getDolGlobalString(''PAYPAL_API_SIGNATURE'');", "public/payment/paymentok.php:95|read|$PAYPAL_API_SIGNATURE = getDolGlobalString(''PAYPAL_API_SIGNATURE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_API_USER', 'string', NULL, 'paypal', 'Stores the PayPal API username credential used for authenticating PayPal NVP API calls.', 'Configured via the admin UI at paypal/admin/paypal.php and read by paypal/lib/paypal.lib.php:471, paypalfunctions.lib.php:61, and public/payment/paymentok.php:93 to authenticate PayPal API requests.', 'Without a valid API username, PayPal payment processing will fail. Changing this to an incorrect value breaks all PayPal-related transactions.', 'String (PayPal API username credential).', 0, 0, 'paypal/admin/paypal.php|paypal/admin/paypal.php', 1, 'a7d524a9a6bf1c3535c50e42cd544251d3ac90e023b4587d0363d403802ff8df', 'v2', '2026-04-21T11:16:15+00:00', '["paypal/admin/paypal.php:59|write|$result = dolibarr_set_const($db, \"PAYPAL_API_USER\", GETPOST(''PAYPAL_API_USER'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "paypal/lib/paypal.lib.php:471|read|$PAYPAL_API_USER = getDolGlobalString(''PAYPAL_API_USER'');", "paypal/lib/paypalfunctions.lib.php:61|read|$PAYPAL_API_USER = getDolGlobalString(''PAYPAL_API_USER'');", "public/payment/paymentok.php:93|read|$PAYPAL_API_USER = getDolGlobalString(''PAYPAL_API_USER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_BANK_ACCOUNT', 'string', NULL, 'compta', 'Specifies the bank account ID to associate with PayPal payments when recording them in Dolibarr.', 'Checked and read in compta/paiement.php:383 and :384. When the constant is set, its value is used as the $accountid for the PayPal payment entry. No admin UI is configured.', 'Setting this constant directs PayPal payments to a specific bank account record; leaving it unset causes the PayPal payment path to skip the account assignment.', 'Integer or string bank account identifier; empty = no PayPal bank account configured.', 1, 0, NULL, 1, 'eb2e3b7c15b0176741e3588289644abfc28cef791e5606b89976cd470d517718', 'v2', '2026-04-21T11:16:15+00:00', '["compta/paiement.php:383|check|if (getDolGlobalString(''PAYPAL_BANK_ACCOUNT'')) {", "compta/paiement.php:384|read|$accountid = getDolGlobalString(''PAYPAL_BANK_ACCOUNT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_BANK_ACCOUNT_FOR_PAYMENTS', 'string', NULL, 'public', 'Specifies the Dolibarr bank account ID into which PayPal payments are recorded.', 'Written via the admin UI at paypal/admin/paypal.php and read in public/payment/paymentok.php at multiple points (lines 713, 1107, 1257, 1402, 1538, 1777) to identify the target bank account when recording incoming PayPal payments.', 'If unset or invalid, PayPal payment confirmation pages cannot link the received payment to a bank account entry. Setting a valid account ID ensures automatic reconciliation.', 'Integer bank account ID as stored in Dolibarr''s bank account table', 0, 0, 'paypal/admin/paypal.php|paypal/admin/paypal.php', 1, '55c979145d57ce9224e5731dd48795140571ef6097bc3b5e286cba9e9fa7abf8', 'v2', '2026-04-21T11:16:15+00:00', '["$result = dolibarr_set_const($db, \"PAYPAL_BANK_ACCOUNT_FOR_PAYMENTS\", GETPOSTINT(''PAYPAL_BANK_ACCOUNT_FOR_PAYMENTS''), ''chaine'', 0, '''', $conf->entity);", "$form->select_comptes(getDolGlobalString(''PAYPAL_BANK_ACCOUNT_FOR_PAYMENTS''), ''PAYPAL_BANK_ACCOUNT_FOR_PAYMENTS'', 0, '''', 1);", "$accountid = getDolGlobalString(''PAYPAL_BANK_ACCOUNT_FOR_PAYMENTS'');", "$bankaccountid = getDolGlobalString(''PAYPAL_BANK_ACCOUNT_FOR_PAYMENTS'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_BRANDNAME', 'string', NULL, 'paypal', 'Stores a custom brand name passed to PayPal as the BRANDNAME parameter on the checkout page.', 'Checked at paypal/lib/paypal.lib.php:277 and read at line 278, appended to the NVP string as BRANDNAME. Only 2 occurrences and no admin UI.', 'Setting this constant overrides the default brand name shown on the PayPal-hosted checkout page.', 'A string brand name.', 1, 0, NULL, 1, 'eeacd84f3164fe0ca9b5891a15ca5bfedf161ff73bf3d8b054f48235c64fae5c', 'v2', '2026-04-21T11:16:15+00:00', '["if (getDolGlobalString(''PAYPAL_BRANDNAME'')) {", "$nvpstr = $nvpstr.\"&BRANDNAME=\".urlencode(getDolGlobalString(''PAYPAL_BRANDNAME'')); // BRANDNAME"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_CUSTOMER_SERVICE_NUMBER', 'string', NULL, 'paypal', 'Stores the customer service hotline phone number passed to PayPal as the CUSTOMERSERVICENUMBER parameter.', 'Checked at paypal/lib/paypal.lib.php:228 and read at line 229 with the comment ''// Hotline phone number'', appended to the NVP string as CUSTOMERSERVICENUMBER.', 'Setting this constant includes the phone number in PayPal API requests, which PayPal may display to customers during checkout.', 'A string phone number.', 1, 0, NULL, 1, '983ff9836c209d89e973e413152c1f50d6bd30d269e4543c9dec958c603d77f2', 'v2', '2026-04-21T11:16:15+00:00', '["if (getDolGlobalString(''PAYPAL_CUSTOMER_SERVICE_NUMBER'')) {", "$nvpstr .= \"&CUSTOMERSERVICENUMBER=\".urlencode(getDolGlobalString(''PAYPAL_CUSTOMER_SERVICE_NUMBER'')); // Hotline phone number"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_ENABLE_TRANSACTION_MANAGEMENT', 'bool', NULL, 'compta', 'Enables display/handling of PayPal transaction information when entering a payment on an invoice paid via the PayPal Plus module.', 'Checked in compta/paiement.php:382 together with isModEnabled(''paypalplus'') and a non-empty $facture->ref_ext; when true, the code pulls in the PayPal bank account (PAYPAL_BANK_ACCOUNT) and uses $facture->ref_ext as the payment number.', 'Enabling it (with the PayPal Plus module active) auto-fills the payment entry form with PayPal-specific transaction reference and bank account information for invoices that carry a PayPal external reference.', 'Boolean-like: any truthy value enables PayPal transaction management on the payment entry page.', 1, 0, NULL, 1, 'cfd3546a0834c0bd690315a83d9f1bbec023601e16617c77bcdc92b0b2eb4383', 'v2', '2026-07-24T07:05:23+00:00', '["compta/paiement.php:382: if (isModEnabled(''paypalplus'') && getDolGlobalString(''PAYPAL_ENABLE_TRANSACTION_MANAGEMENT'') && !empty($facture->ref_ext)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_LOGOIMG', 'string', NULL, 'paypal', 'When enabled together with a company logo, sends the company logo image URL to PayPal to brand the checkout page.', 'Checked in paypal/lib/paypal.lib.php:266-273: `if (getDolGlobalString(''PAYPAL_LOGOIMG'') && $mysoc->logo) { ... $nvpstr = $nvpstr."&LOGOIMG=".urlencode($urllogo); }`, building a viewimage.php URL to mycompany logo file. No admin/*.php write found.', 'When truthy and a company logo is configured, adds a LOGOIMG parameter (URL to the company logo via viewimage.php) to the PayPal Express Checkout NVP request, displaying the logo on PayPal''s hosted checkout page.', 'Boolean-like: truthy (combined with $mysoc->logo being set) triggers the LOGOIMG parameter to be added.', 1, 0, NULL, 1, '295c026d9bfbc48b00c618d8a5a78fef94c7d0968afebe5a22a441221c9d57ed', 'v2', '2026-07-24T07:05:23+00:00', '["paypal/lib/paypal.lib.php:266|check|if (getDolGlobalString(''PAYPAL_LOGOIMG'') && $mysoc->logo) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_NOTETOBUYER', 'string', NULL, 'paypal', 'Custom note text sent to the buyer during PayPal Express Checkout.', 'Checked and read in paypal/lib/paypal.lib.php:280-282: `if (getDolGlobalString(''PAYPAL_NOTETOBUYER'')) { $nvpstr = $nvpstr."&NOTETOBUYER=".urlencode(getDolGlobalString(''PAYPAL_NOTETOBUYER'')); }`. No admin/*.php write found.', 'When set, its text value is URL-encoded and sent as the NOTETOBUYER parameter in the PayPal NVP payment request, displayed to the buyer during checkout.', 'Free-text string, sent verbatim (URL-encoded) as the NOTETOBUYER parameter; no effect if empty/unset.', 1, 0, NULL, 1, '2106146e60793b33dc714c7406d749b062b7045f4ce22c803308b049135cfdba', 'v2', '2026-07-24T07:05:23+00:00', '["paypal/lib/paypal.lib.php:280|check|if (getDolGlobalString(''PAYPAL_NOTETOBUYER'')) {", "paypal/lib/paypal.lib.php:281|read|$nvpstr = $nvpstr.\"&NOTETOBUYER=\".urlencode(getDolGlobalString(''PAYPAL_NOTETOBUYER'')); // PAYPAL_NOTETOBUYER"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_PAYMENT_MODE_FOR_PAYMENTS', 'string', NULL, 'public', 'Defines the payment type ID recorded for PayPal online payments.', 'Read via getDolGlobalInt(''PAYPAL_PAYMENT_MODE_FOR_PAYMENTS'') repeatedly in public/payment/paymentok.php (lines 584, 1023, 1169, 1324, 1463, 1702, 1920).', 'Changing the value changes which payment type ID ($paymentTypeId) is recorded for PayPal-originated payments.', NULL, 0, 0, NULL, 1, '85b6a0e9a38746c95e64d8cd116633986f0af23634024e5ca1e1ceeefd7f8843', 'v2', '2026-07-24T06:41:12+00:00', '["$paymentTypeId = getDolGlobalInt(''PAYPAL_PAYMENT_MODE_FOR_PAYMENTS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_REQUIRE_VALID_SHIPPING_ADDRESS', 'string', NULL, 'paypal', 'Controls whether PayPal Express Checkout requires a complete, valid shipping address from the buyer.', 'Checked in paypal/lib/paypal.lib.php:221-225: if unset/false, `$nvpstr .= "&NOSHIPPING=1";` (an empty or incomplete shipping address is accepted); if truthy, `&NOSHIPPING=0` (a valid shipping address is required). An error message at line 150 tells admins to unset it if payments fail due to incomplete addresses: ''Ask system administrator to fix address or to setup Paypal module to accept payments even on not complete addresses (remove option PAYPAL_REQUIRE_VALID_SHIPPING_ADDRESS)''.', 'When enabled, PayPal will reject or fail payments for third parties whose address is incomplete (e.g. missing State); when disabled, incomplete shipping addresses are accepted (NOSHIPPING=1).', 'Boolean-like: truthy sets NOSHIPPING=0 (valid address required); falsy/unset sets NOSHIPPING=1 (incomplete address accepted).', 1, 0, NULL, 1, '8f40cc9f69c110216074d08ac7f489ea41a40edb4ad870ad5bd31704b852d3bd', 'v2', '2026-07-24T07:05:23+00:00', '["paypal/lib/paypal.lib.php:221|check|if (!getDolGlobalString(''PAYPAL_REQUIRE_VALID_SHIPPING_ADDRESS'')) {", "paypal/lib/paypal.lib.php:150: ...Ask system administrator to fix address or to setup Paypal module to accept payments even on not complete addresses (remove option PAYPAL_REQUIRE_VALID_SHIPPING_ADDRESS)."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_SECURITY_TOKEN', 'string', NULL, 'comm', 'Shared secret token used to generate hashed secure keys for PayPal payment links in mass mailings.', 'Used exclusively in comm/mailing/card.php. The token is hashed via dol_hash() to produce __SECUREKEYPAYPAL__, __SECUREKEYPAYPAL_MEMBER__, __SECUREKEYPAYPAL_ORDER__, and __SECUREKEYPAYPAL_INVOICE__ substitution values for mailing templates.', 'Setting this token enables PayPal payment link generation in mailing campaigns. Clearing it disables PayPal link substitution variables.', 'A secret string used as the base for SHA-based hashing; empty = PayPal secure keys not generated', 1, 0, NULL, 1, '8ec846491567a13efa5045dfe8433486e27f6b186d78642d93895816b14f5ef1', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/card.php:341|check|if (isModEnabled(''paypal'') && getDolGlobalString(''PAYPAL_SECURITY_TOKEN'')) {", "comm/mailing/card.php:342|read|$substitutionarray[''__SECUREKEYPAYPAL__''] = dol_hash(getDolGlobalString(''PAYPAL_SECURITY_TOKEN''), ''2'');", "comm/mailing/card.php:345|read|$substitutionarray[''__SECUREKEYPAYPAL_MEMBER__''] = dol_hash(getDolGlobalString(''PAYPAL_SECURITY_TOKEN''), ''2'');", "comm/mailing/card.php:351|read|$substitutionarray[''__SECUREKEYPAYPAL_ORDER__''] = dol_hash(getDolGlobalString(''PAYPAL_SECURITY_TOKEN''), ''2'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_SECURITY_TOKEN_UNIQUE', 'string', NULL, 'comm', 'Controls whether a unique per-record token is used for PayPal secure key generation in mailing substitution.', 'Checked four times in comm/mailing/card.php (lines 344, 350, 356, 362). When not set, the token is combined with a record-specific identifier (source_id) to produce unique per-record hashes for member, order, and invoice payment links.', 'When this constant is empty/unset, each PayPal link hash is unique per record (source_id appended). When set, a single shared hash is used for all records of each type.', 'Empty/unset = per-record unique token (source_id appended); non-empty = shared token (no source_id appended)', 1, 0, NULL, 1, '8e65cbff7fcb3334aea1cb0586551ee588dd34d613e345602bc08f2cf307e855', 'v2', '2026-04-21T13:29:58+00:00', '["comm/mailing/card.php:344|check|if (!getDolGlobalString(''PAYPAL_SECURITY_TOKEN_UNIQUE'')) {", "comm/mailing/card.php:350|check|if (!getDolGlobalString(''PAYPAL_SECURITY_TOKEN_UNIQUE'')) {", "comm/mailing/card.php:356|check|if (!getDolGlobalString(''PAYPAL_SECURITY_TOKEN_UNIQUE'')) {", "comm/mailing/card.php:362|check|if (!getDolGlobalString(''PAYPAL_SECURITY_TOKEN_UNIQUE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PAYPAL_SSLVERSION', 'string', NULL, 'paypal', 'Sets the SSL/TLS version used for cURL connections to the PayPal API.', 'Configured via a select dropdown in paypal/admin/paypal.php:221. Applied at paypal/lib/paypal.lib.php:489 via curl_setopt CURLOPT_SSLVERSION; defaults to 1 (TLSv1) if unset.', 'Changing this value changes the TLS protocol version used for PayPal API communications; an incompatible value may cause connection failures.', '1 = TLSv1, 6 = TLSv1.2', 0, 0, 'paypal/admin/paypal.php|paypal/admin/paypal.php', 1, 'df1029b8a46b89728ab08ee9a34094f7330f676d58ec20ce78554bd0b45beb32', 'v2', '2026-04-21T11:16:15+00:00', '["paypal/admin/paypal.php:221|read|print $form->selectarray(\"PAYPAL_SSLVERSION\", array(''1''=> $langs->trans(''TLSv1''), ''6''=> $langs->trans(''TLSv1.2'')), getDolGlobalString(''PAYPAL_SSLVERSION''));", "paypal/lib/paypal.lib.php:489|read|curl_setopt($ch, CURLOPT_SSLVERSION, (!getDolGlobalString(''PAYPAL_SSLVERSION'') ? 1 : $conf->global->PAYPAL_SSLVERSION));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ACCOUNTANCY_BALANCE_ADD_POSITION', 'string', NULL, 'core', 'Enables a ''position'' (line rank) column in the accountancy balance PDF template.', 'core/modules/accountancy/doc/pdf_balance.modules.php:755 sets the position column''s status directly from this constant: `''status'' => (bool) getDolGlobalInt(''PDF_ACCOUNTANCY_BALANCE_ADD_POSITION'')`. Unlike PDF_CORNAS_ADD_POSITION it has no fallback to a generic PDF_ADD_POSITION constant here.', 'Setting it to 1 shows the line-position/rank column in the accountancy balance PDF; 0/unset hides it.', '0/unset = column hidden (false); 1 = column shown (cast to bool).', 0, 0, NULL, 1, '91176d655c293a92edd008132e75c51b75015d95c7a885d6a4b5ef08e3fd3059', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/accountancy/doc/pdf_balance.modules.php:755: ''status'' => (bool) getDolGlobalInt(''PDF_ACCOUNTANCY_BALANCE_ADD_POSITION''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ACCOUNTANCY_LEDGER_ADD_POSITION', 'string', NULL, 'core', 'Controls whether positional/layout data is added to the accountancy ledger and bookkeeping PDF exports.', 'Read as a boolean integer in core/modules/accountancy/doc/pdf_ledger.modules.php:795 and core/modules/accountancy/doc/pdf_bookkeeping.modules.php:737, used as the ''status'' field in the position configuration array for both modules.', 'Enabling this activates position metadata in ledger and bookkeeping PDF outputs; disabling it omits it.', 'Non-zero integer value enables position addition; 0 or unset disables it.', 1, 0, NULL, 1, '2945c32051399de9dbb2e6f4ba0061a0f9b1a231051a3699e172ed2fd5164bef', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/accountancy/doc/pdf_ledger.modules.php:795|read|''status'' => (bool) getDolGlobalInt(''PDF_ACCOUNTANCY_LEDGER_ADD_POSITION''),", "core/modules/accountancy/doc/pdf_bookkeeping.modules.php:737|read|''status'' => (bool) getDolGlobalInt(''PDF_ACCOUNTANCY_LEDGER_ADD_POSITION''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ADD_MORE_AFTER_SOURCE_ADDRESS', 'string', NULL, 'core', 'Appends custom text to the source address block on PDF documents.', 'The value of this constant is read and concatenated directly to the address string in core/lib/pdf.lib.php:550, preceded by a newline if the address is non-empty. No admin UI write is present; must be set manually.', 'Setting this constant injects arbitrary text after the issuing company''s address on all generated PDFs.', 'Any non-empty string = text appended after source address; absent/empty = nothing appended.', 1, 0, NULL, 1, '637b458bd525e9ef7d9796974898f96c3569b9fd1d11fb4bde3812916054d655', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:549|check|if (getDolGlobalString(''PDF_ADD_MORE_AFTER_SOURCE_ADDRESS'')) {", "core/lib/pdf.lib.php:550|read|$stringaddress .= ($stringaddress ? \"\\n\" : '''') . getDolGlobalString(''PDF_ADD_MORE_AFTER_SOURCE_ADDRESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ADD_POSITION', 'string', NULL, 'core', 'Controls whether a position (line number) column is included in PDF documents across multiple templates as a global fallback.', 'Used in six locations across pdf_espadon, pdf_eratosthene, pdf_octopus, pdf_sponge, pdf_cornas, and pdf_cyan modules. In each case it serves as a fallback when the template-specific position constant (e.g., PDF_ESPADON_ADD_POSITION) is falsy.', 'Setting this to a truthy value enables the position column in all supported PDF templates that do not have a template-specific override. Clearing it disables the position column globally as a fallback.', '0 or unset = no position column (as fallback); non-zero = position column enabled in all templates that check it.', 1, 0, NULL, 1, '3e20dc934bd2f71b8bd97252cf23d305b148ae908bef36650533de6ed6e682c4', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_espadon.modules.php:1375|''status'' => getDolGlobalInt(''PDF_ESPADON_ADD_POSITION'') ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),", "pdf_eratosthene.modules.php:1983|''status'' => (getDolGlobalInt(''PDF_ERATOSTHENE_ADD_POSITION'') || getDolGlobalInt(''PDF_ERATOSHTENE_ADD_POSITION'')) ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),", "pdf_octopus.modules.php:2424|''status'' => getDolGlobalInt(''PDF_SPONGE_ADD_POSITION'') ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),", "pdf_cornas.modules.php:1578|''status'' => getDolGlobalInt(''PDF_CORNAS_ADD_POSITION'') ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ALLOW_DISPLAY_LINKED_OBJECT_FOR_OTHER_SOC', 'bool', NULL, 'core', 'Bypasses the third-party privacy check that normally prevents showing linked-object references (e.g. linked orders) on a PDF when the linked object belongs to a different third party.', 'Used in the canDisplayLinkedObjectInPDF() function in core/lib/pdf.lib.php:2960-2974: if the constant is true, the function returns true immediately, skipping the objectSocId != elementSocId comparison documented in the function''s docblock.', 'Enabling it allows linked-object data (e.g. a related order''s reference) to appear on a document even when the linked object''s third party differs from the main object''s third party, which the docblock says exists to avoid leaking customer data to suppliers or vice versa.', 'Boolean via getDolGlobalBool: true disables the privacy restriction described in the function docblock (''prevents displaying customer data to suppliers or supplier data to customers'').', 1, 0, NULL, 1, 'ba813a67306e1ab679b133c652569aa3a53cbe7a183378e6c3f80c38c521a81a', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:2953: * according to the configuration and the socid of the main object and the linked object.", "core/lib/pdf.lib.php:2965: if (getDolGlobalBool(\"PDF_ALLOW_DISPLAY_LINKED_OBJECT_FOR_OTHER_SOC\")) {", "core/lib/pdf.lib.php:2969: if (!empty($objectSocId) && !empty($elementSocId) && $objectSocId != $elementSocId) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ALLOW_HTML_FOR_FREE_TEXT', 'bool', NULL, 'admin', 'Allows HTML formatting to be used in the free-text field of generated PDF documents.', 'Set via admin UI across many document type pages (admin/bom.php:520, admin/expensereport.php:485, admin/holiday.php:586, admin/contract.php:515, admin/propal.php, supplier_proposal/admin/supplier_proposal.php:535, supplier_invoice/admin/supplier_invoice.php:502, takepos/admin/terminal.php:552/568).', 'When disabled (negated check ''!getDolGlobalString(...)''), HTML is not allowed in the free-text field of these document/PDF setup pages.', NULL, 0, 0, 'admin/bom.php|admin/expensereport.php|supplier_proposal/admin/supplier_proposal.php|supplier_invoice/admin/supplier_invoice.php|admin/delivery.php|admin/propal.php|admin/holiday.php|admin/contract.php|admin/chequereceipts.php|supplier_order/admin/supplier_order.php|admin/fichinter.php|admin/mrp.php|admin/invoice.php|admin/expedition.php|admin/order.php|takepos/admin/receipt.php|takepos/admin/receipt.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'f1c246cae08a1bcd5dc5b996888dead4832bf350748584ae7caacaeab67c240e', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''PDF_ALLOW_HTML_FOR_FREE_TEXT'')) {", "if (!getDolGlobalInt(''PDF_ALLOW_HTML_FOR_FREE_TEXT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_BANK_HIDE_NUMBER_SHOW_ONLY_BICIBAN', 'bool', NULL, 'core', 'Hides the detailed bank/desk/account/key numbers on PDF documents, showing only BIC/IBAN.', 'Checked in core/lib/pdf.lib.php:1275 (function pdf_bank); when set, the block that prints bank code, desk code, account number and control key is skipped.', 'Simplifies the printed bank account block to BIC/IBAN only; the inline comment warns some countries still require the detailed bank number since BIC/IBAN alone is not enough for them.', 'Boolean-like (set/unset); when set, only BIC/IBAN shown, detailed bank number hidden', 1, 0, NULL, 1, 'd96acea353b2b2b2d3d123d76fbd515647ddf93838098aeb6011b35814aec7f8', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1275|check|if (!getDolGlobalString(''PDF_BANK_HIDE_NUMBER_SHOW_ONLY_BICIBAN'')) {    // Note that some countries still need bank number, BIC/IBAN not enough for them"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_BOLD_PRODUCT_LABEL', 'string', NULL, 'admin', 'Controls whether the product label is rendered in bold in PDF line item blocks.', 'Configured via admin/pdf.php (written at line 202, rendered as a yes/no selector at line 621). Checked at core/lib/pdf.lib.php:2009; when truthy and a label is present, bold formatting is applied.', 'Enabling this makes product labels bold in generated PDF documents.', '1 = bold product label; 0 or absent = normal weight product label.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'b52b278f67945c1f669acbdec5ebfe3d0edc7dabc3b57878d5bf753a9b9c4aa4', 'v2', '2026-04-21T13:29:58+00:00', '["admin/pdf.php:202|write|dolibarr_set_const($db, \"PDF_BOLD_PRODUCT_LABEL\", GETPOST(''PDF_BOLD_PRODUCT_LABEL'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:621|read|print $form->selectyesno(''PDF_BOLD_PRODUCT_LABEL'', getDolGlobalInt(''PDF_BOLD_PRODUCT_LABEL''), 1);", "core/lib/pdf.lib.php:2009|check|if (!empty($libelleproduitservice) && getDolGlobalString(''PDF_BOLD_PRODUCT_LABEL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_BOLD_PRODUCT_REF_AND_PERIOD', 'string', NULL, 'admin', 'Makes the product reference and period bold in generated PDF documents.', 'Set via admin UI at admin/pdf.php:205/632 (yes/no select) and checked in core/lib/pdf.lib.php:2189/2227.', 'When enabled, the product reference (when $ref_prodserv is non-empty) and period text are rendered in bold in the PDF.', NULL, 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '910976751c66305095e7d2832f021516a767f99c44397130c256c5b7ddbc8f53', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, \"PDF_BOLD_PRODUCT_REF_AND_PERIOD\", GETPOST(''PDF_BOLD_PRODUCT_REF_AND_PERIOD'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "if (!empty($ref_prodserv) && getDolGlobalString(''PDF_BOLD_PRODUCT_REF_AND_PERIOD'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_CORNAS_ADD_POSITION', 'string', NULL, 'core', 'Enables a ''position'' (line rank) column in the Cornas PDF template for supplier orders, overriding the generic PDF_ADD_POSITION setting for that template.', 'In core/modules/supplier_order/doc/pdf_cornas.modules.php:1578, the position column''s ''status'' is set to true if PDF_CORNAS_ADD_POSITION is truthy, else it falls back to the generic PDF_ADD_POSITION: `getDolGlobalInt(''PDF_CORNAS_ADD_POSITION'') ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false)`.', 'Setting it to 1 shows a line-position/rank column specifically in the Cornas supplier order PDF model, independent of the global PDF_ADD_POSITION setting.', '0/unset = fall back to PDF_ADD_POSITION; 1 = force-enable the position column for this template.', 0, 0, NULL, 1, '898c31cc523957a116d481ec73f74db8160f0b93d1adaf3bd4f19864d1fe3adc', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_order/doc/pdf_cornas.modules.php:1578: ''status'' => getDolGlobalInt(''PDF_CORNAS_ADD_POSITION'') ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_CYAN_ADD_POSITION', 'string', NULL, 'core', 'Enables a ''#'' position/rank column in the Cyan proposal PDF template''s line table, overriding the generic PDF_ADD_POSITION setting for this model only.', 'Read in core/modules/propale/doc/pdf_cyan.modules.php:2123, where the ''position'' column''s status is true if this constant is set, else falls back to the generic PDF_ADD_POSITION constant, else false — same pattern as PDF_ESPADON_ADD_POSITION, PDF_SPONGE_ADD_POSITION, etc.', 'Enabling it shows a row-position/index column specifically on proposal documents generated with the Cyan model, independent of the global PDF_ADD_POSITION setting.', 'Boolean/int: truthy value enables the position column for the Cyan proposal PDF model.', 0, 0, NULL, 1, '520fccdac8422b0c0c64d9e32d42817a4d7d537e441888d4cc38945ea9374d0b', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:2123|read|''status'' => getDolGlobalInt(''PDF_CYAN_ADD_POSITION'') ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_DIFFSIZE_CONTENT', 'string', NULL, 'core', 'Number of points subtracted from the default font size to render bank account detail content on PDF documents.', 'Read in core/lib/pdf.lib.php:1244 (function pdf_bank) as getDolGlobalInt(''PDF_DIFFSIZE_CONTENT'', 4); used alongside PDF_DIFFSIZE_TITLE (default 3) to compute font sizes smaller than $default_font_size for the bank account block.', 'Controls how much smaller the bank account number/details text is compared to the base PDF font size; larger values shrink the text further.', 'Integer, default 4 (points subtracted from default_font_size)', 1, 0, NULL, 1, '0ed446c96d3a86132a99de21363782a897c1cdd0db7545ca693493584468d2c9', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1244|read|$diffsizecontent = getDolGlobalInt(''PDF_DIFFSIZE_CONTENT'', 4);", "core/lib/pdf.lib.php:1269: $pdf->SetFont('''', '''', $default_font_size - $diffsizecontent);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_DIFFSIZE_TITLE', 'string', NULL, 'core', 'Sets the font size offset (relative to base font size) used for column title rows in PDF line item tables.', 'Read across 15 occurrences in multiple PDF module files (commande, facture, supplier_order, propale, etc.) using getDolGlobalInt with a default of 3 (e.g. core/modules/commande/doc/pdf_einstein.modules.php:733). No admin UI write is present.', 'Changing this value alters the font size of header/title rows in PDF line item tables across all document types.', 'Integer offset value; default = 3 (added to base font size). Any integer is accepted.', 1, 0, NULL, 1, '0f6eac6ee8507fa40220204db63774d25def757fabdec21ecf07417d5d7be0cf', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/commande/doc/pdf_einstein.modules.php:733|read|$diffsizetitle = getDolGlobalInt(''PDF_DIFFSIZE_TITLE'', 3);", "core/modules/commande/doc/pdf_eratosthene.modules.php:998|read|$diffsizetitle = getDolGlobalInt(''PDF_DIFFSIZE_TITLE'', 3);", "core/modules/facture/doc/pdf_octopus.modules.php:1556|read|$diffsizetitle = getDolGlobalInt(''PDF_DIFFSIZE_TITLE'', 3);", "core/modules/facture/doc/pdf_sponge.modules.php:1622|read|$diffsizetitle = getDolGlobalInt(''PDF_DIFFSIZE_TITLE'', 3);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_DISABLE_MYCOMPANY_LOGO', 'bool', NULL, 'core', 'Disables printing of the company logo in the header of generated PDF documents.', 'Checked across 16 occurrences in PDF generation modules using !getDolGlobalInt(''PDF_DISABLE_MYCOMPANY_LOGO'') to conditionally skip logo rendering. No admin UI write is present.', 'Enabling this removes the company logo from all generated PDF document headers.', '0 or unset = company logo shown; 1 = company logo hidden.', 1, 0, NULL, 1, '46858446f17a975b39d37237799e7a8e8c994bb5b084db470fddd726e34b91db', 'v2', '2026-04-21T11:16:15+00:00', '["recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:756|check|if (!getDolGlobalInt(''PDF_DISABLE_MYCOMPANY_LOGO'')) {", "core/modules/commande/doc/pdf_einstein.modules.php:1381|check|if (!getDolGlobalInt(''PDF_DISABLE_MYCOMPANY_LOGO'')) {", "core/modules/facture/doc/pdf_octopus.modules.php:1981|check|if (!getDolGlobalInt(''PDF_DISABLE_MYCOMPANY_LOGO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ERATOSHTENE_ADD_POSITION', 'string', NULL, 'core', 'Misspelled fallback variant of PDF_ERATOSTHENE_ADD_POSITION, checked via OR in the same expression for the Eratosthene order PDF model''s position column.', 'Only occurrence found is core/modules/commande/doc/pdf_eratosthene.modules.php:1991, the same line as PDF_ERATOSTHENE_ADD_POSITION: `(getDolGlobalInt(''PDF_ERATOSTHENE_ADD_POSITION'') || getDolGlobalInt(''PDF_ERATOSHTENE_ADD_POSITION'')) ? true : ...`. This looks like a typo of the correctly spelled constant kept for backward compatibility.', 'Setting it truthy has the same effect as setting PDF_ERATOSTHENE_ADD_POSITION: it enables the position column status on the Eratosthene order PDF, since the two are OR-ed together.', 'Boolean-like: truthy enables the position column status (same effect as PDF_ERATOSTHENE_ADD_POSITION).', 0, 0, NULL, 1, '0b3ca47db1bece480eb08a03c3b36c3407b9b5cd8cfba0ef6962c4cff4cb9a41', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/commande/doc/pdf_eratosthene.modules.php:1991: ''status'' => (getDolGlobalInt(''PDF_ERATOSTHENE_ADD_POSITION'') || getDolGlobalInt(''PDF_ERATOSHTENE_ADD_POSITION'')) ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ERATOSTHENE_ADD_POSITION', 'string', NULL, 'core', 'Enables display of a line-position column/value on the Eratosthene order PDF model.', 'Read in core/modules/commande/doc/pdf_eratosthene.modules.php:1991: `''status'' => (getDolGlobalInt(''PDF_ERATOSTHENE_ADD_POSITION'') || getDolGlobalInt(''PDF_ERATOSHTENE_ADD_POSITION'')) ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),` — it is OR-ed with the misspelled variant PDF_ERATOSHTENE_ADD_POSITION and falls back to the generic PDF_ADD_POSITION constant.', 'Enabling it (or the misspelled twin, or the generic PDF_ADD_POSITION) turns on the ''position'' column status for that PDF column definition.', 'Boolean-like: truthy enables the position column status for the Eratosthene order PDF model.', 0, 0, NULL, 1, 'bbf254a1e32c46a89f55c5dac1d306345e4d97cfb3c907402bd6408c71814f46', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/commande/doc/pdf_eratosthene.modules.php:1991: ''status'' => (getDolGlobalInt(''PDF_ERATOSTHENE_ADD_POSITION'') || getDolGlobalInt(''PDF_ERATOSHTENE_ADD_POSITION'')) ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ESPADON_ADD_POSITION', 'string', NULL, 'core', 'Enables a ''#'' position/rank column in the Espadon shipment PDF template''s line table, overriding the generic PDF_ADD_POSITION setting for this model only.', 'Read in core/modules/expedition/doc/pdf_espadon.modules.php:1375, where the ''position'' column''s status is true if this constant is set, else falls back to the generic PDF_ADD_POSITION constant, else false.', 'Enabling it shows a row-position/index column specifically on shipment documents generated with the Espadon model, independent of the global PDF_ADD_POSITION setting.', 'Boolean/int: truthy value enables the position column for the Espadon shipment PDF model.', 0, 0, NULL, 1, 'b748dd1d86f8dd2f65bf8aff59b16ea698abeabe27a948c83ed4ddfb9b1bfaf6', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expedition/doc/pdf_espadon.modules.php:1375|read|''status'' => getDolGlobalInt(''PDF_ESPADON_ADD_POSITION'') ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_EXPENSEREPORT_NO_PAYMENT_DETAILS', 'string', NULL, 'core', 'Suppresses the payment details table on the generated expense report PDF even when payments exist.', 'Checked in core/modules/expensereport/doc/pdf_standard_expensereport.modules.php:529: if ($sumPayments > 0 && !getDolGlobalString(''PDF_EXPENSEREPORT_NO_PAYMENT_DETAILS'')) the payments table is printed via $this->tablePayments(...).', 'When set/true, the expense report PDF omits the payments detail table (tablePayments) even if the expense report has recorded payments.', 'Boolean-like: truthy suppresses the payment-details table on the PDF.', 1, 0, NULL, 1, '05359487bc2650dee32c12a94a6964edb1233225b4ac89f2f152b11d25f26331', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/expensereport/doc/pdf_standard_expensereport.modules.php:529: if ($sumPayments > 0 && !getDolGlobalString(''PDF_EXPENSEREPORT_NO_PAYMENT_DETAILS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_FOOTER_BACKGROUND_COLOR', 'string', NULL, 'core', 'Sets the RGB background color of the PDF document footer.', 'Checked and parsed with sscanf(getDolGlobalString(''PDF_FOOTER_BACKGROUND_COLOR''), ''%d, %d, %d'') in core/lib/pdf.lib.php at lines 1649-1650 and 1704-1705.', 'Changing the value (expected as ''R, G, B'' string) changes the footer background color rendered in generated PDF documents.', 'format: ''R, G, B'' (parsed via sscanf with ''%d, %d, %d'')', 0, 0, NULL, 1, '63da7ad220603cd46364a11ed664608d2626998cd57c3dbfe8aab371ef71bf1b', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''PDF_FOOTER_BACKGROUND_COLOR'')) {", "$tmparray = sscanf(getDolGlobalString(''PDF_FOOTER_BACKGROUND_COLOR''), ''%d, %d, %d'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_FOOTER_DISABLE_PAGEBREAK', 'bool', NULL, 'core', 'Disables automatic page breaks within the footer block on PDF documents.', 'Checked at core/lib/pdf.lib.php:1681 and :1685 using strict comparison to integer 1. No admin UI write is present; must be set manually.', 'Setting this to 1 prevents page breaks from being inserted inside the PDF footer block.', '1 = disable page breaks in footer; 0 or absent = page breaks allowed.', 1, 0, NULL, 1, 'ce782249f9f5e1d6de4d203f3489b4ea8dd0ba757c64da69f25fcc7a4551f6b3', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:1681|check|if (getDolGlobalInt(''PDF_FOOTER_DISABLE_PAGEBREAK'') === 1) {", "core/lib/pdf.lib.php:1685|check|if (getDolGlobalInt(''PDF_FOOTER_DISABLE_PAGEBREAK'') === 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_FOOTER_HIDDEN', 'string', NULL, 'core', 'Hides the entire default footer content (lines 1-4 and separator line) on PDF documents, while keeping the page number visible.', 'Checked in core/lib/pdf.lib.php:1733 inside the default-footer branch (used when no hook-based custom footer is set); when true, the block that draws the footer line and line1-line4 text is skipped.', 'Removes company footer lines from PDF documents entirely; the inline comment confirms page numbering is still shown.', 'Boolean-like/int (set/unset); when set, footer content hidden but page number still shown', 1, 0, NULL, 1, 'fc73d8a7c7d549d05bf763d1246713854ffaa8858af3cd9f87074e27f37eb714', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1733|check|if (!getDolGlobalInt(''PDF_FOOTER_HIDDEN'')) {", "core/lib/pdf.lib.php:1732: // Option for hide all footer (page number will no hidden)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_FOOTER_PAGE_NUMBER_X', 'string', NULL, 'core', 'Horizontal offset (in the PDF unit, subtracted from the right margin) applied to the page-number position in the footer.', 'Read in core/lib/pdf.lib.php:1777 as getDolGlobalInt(''PDF_FOOTER_PAGE_NUMBER_X'', 0), subtracted from the computed X position before drawing the ''page N / M'' text.', 'Shifts the page-number text horizontally on the page footer; positive values move it further left from its default position.', 'Integer offset, default 0', 1, 0, NULL, 1, 'bcbe8f8b7facef9e8cf3afc3059b511859f5f41158adac64b028d888554f29dd', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1777|read|$pdf->SetXY($dims[''wk''] - $dims[''rm''] - 18 - getDolGlobalInt(''PDF_FOOTER_PAGE_NUMBER_X'', 0), -$posy - getDolGlobalInt(''PDF_FOOTER_PAGE_NUMBER_Y'', 0));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_FOOTER_PAGE_NUMBER_Y', 'string', NULL, 'core', 'Vertical offset applied to the page-number position in the PDF footer.', 'Read in core/lib/pdf.lib.php:1777 as getDolGlobalInt(''PDF_FOOTER_PAGE_NUMBER_Y'', 0), subtracted from -$posy before drawing the ''page N / M'' text.', 'Shifts the page-number text vertically on the page footer relative to its default computed position.', 'Integer offset, default 0', 1, 0, NULL, 1, 'bf6bccc141e6657c17b8372f92bee0914d0fba5d57173b47ac4ed7b59a5236fd', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1777|read|$pdf->SetXY($dims[''wk''] - $dims[''rm''] - 18 - getDolGlobalInt(''PDF_FOOTER_PAGE_NUMBER_X'', 0), -$posy - getDolGlobalInt(''PDF_FOOTER_PAGE_NUMBER_Y'', 0));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_FOOTER_TEXT_COLOR', 'string', NULL, 'core', 'Sets the RGB text color used for the footer text on generated PDF documents.', 'Checked/read in core/lib/pdf.lib.php:1608-1609; the value is parsed with sscanf(''%d, %d, %d'') into r/g/b components passed to $pdf->SetTextColor().', 'Changes the color of the footer text (company info lines) on PDF documents; must be a valid ''r, g, b'' string or the color will not be applied correctly.', 'String ''r, g, b'' with integer 0-255 components, e.g. ''128, 128, 128''', 1, 0, NULL, 1, '360e50b57edb78432948ed8898995fbd4d882cdd708330339a08a781bcf6b75d', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:1608|check|if (getDolGlobalString(''PDF_FOOTER_TEXT_COLOR'')) {", "core/lib/pdf.lib.php:1609|read|$tmparray = sscanf(getDolGlobalString(''PDF_FOOTER_TEXT_COLOR''), ''%d, %d, %d'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_FOOTER_TOP_MARGIN', 'string', NULL, 'core', 'Sets the top margin (in PDF units) for the footer block on PDF documents.', 'Checked and read across 4 occurrences in core/lib/pdf.lib.php (:1675, :1676, :1729, :1730); the value is cast to float and subtracted from the y-position to determine footer placement.', 'Changing this value adjusts the vertical gap between the document body and the footer on generated PDFs.', 'Numeric value (float, in PDF units); 0 = no margin; absent = default footer position used.', 1, 0, NULL, 1, '6c3b42be8e2e6e1358d2703f477d96d0c77d25689307a3ecf80d8084eadb4111', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:1675|check|if (getDolGlobalString(''PDF_FOOTER_TOP_MARGIN'') || getDolGlobalInt(''PDF_FOOTER_TOP_MARGIN'') === 0) {", "core/lib/pdf.lib.php:1676|read|$posy -= (float) getDolGlobalString(''PDF_FOOTER_TOP_MARGIN'');", "core/lib/pdf.lib.php:1729|check|if (getDolGlobalString(''PDF_FOOTER_TOP_MARGIN'') || getDolGlobalInt(''PDF_FOOTER_TOP_MARGIN'') === 0) {", "core/lib/pdf.lib.php:1730|read|$posy -= (float) getDolGlobalString(''PDF_FOOTER_TOP_MARGIN'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_FREETEXT_DISABLE_PAGEBREAK', 'bool', NULL, 'core', 'Disables automatic page breaks within the free text block on PDF documents.', 'Checked across 4 occurrences in core/lib/pdf.lib.php (:1651, :1663, :1703, :1715) using strict comparison to integer 1. No admin UI write is present; must be set manually.', 'Setting this to 1 prevents page breaks from being inserted inside the free text block, keeping it on a single page regardless of length.', '1 = disable page breaks in free text block; 0 or absent = page breaks allowed.', 1, 0, NULL, 1, 'e304c865765455c64f055eb674a180034443b9e673ef271e171cd10bdffdc9d9', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:1651|check|if (getDolGlobalInt(''PDF_FREETEXT_DISABLE_PAGEBREAK'') === 1) {", "core/lib/pdf.lib.php:1663|check|if (getDolGlobalInt(''PDF_FREETEXT_DISABLE_PAGEBREAK'') === 1) {", "core/lib/pdf.lib.php:1703|check|if (getDolGlobalInt(''PDF_FREETEXT_DISABLE_PAGEBREAK'') === 1) {", "core/lib/pdf.lib.php:1715|check|if (getDolGlobalInt(''PDF_FREETEXT_DISABLE_PAGEBREAK'') === 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_HIDE_LINKED_OBJECT_IN_PUBLIC_NOTE', 'bool', NULL, 'core', 'Suppresses the automatic appending of linked-object reference lists (e.g. related order refs) into an object''s public note used on PDF documents.', 'Used once in core/lib/pdf.lib.php:3095: when set, the function pdf_getLinkedObjects (context of the surrounding code) skips concatenating $refListsTxt onto $object->note_public.', 'When enabled, the list of linked object references that would otherwise be added to the public note (and thus appear on the PDF) is not appended, avoiding repeated data as noted in the inline comment.', 'Boolean via getDolGlobalString: truthy disables appending linked-object refs to the public note.', 1, 0, NULL, 1, 'dc073f9718444d8df80e22e2bdc09772677640f38b608a3a61c69d4ee10dd1f4', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:3095: if (empty($object->context[''DolPublicNoteAppendedGetLinkedObjects'']) && !getDolGlobalString(\"PDF_HIDE_LINKED_OBJECT_IN_PUBLIC_NOTE\")) { // Check if already appended before add to avoid repeat data", "core/lib/pdf.lib.php:3096: $object->note_public = dol_concatdesc($object->note_public, $refListsTxt);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_HIDE_PRODUCT_LABEL_IN_SUPPLIER_LINES', 'bool', NULL, 'core', 'Hides the product/service label (keeping only the description) on PDF document lines, despite its name suggesting supplier-only scope.', 'Checked in core/lib/pdf.lib.php:2017 (function pdf_getlinedesc or equivalent); when set, $libelleproduitservice is left empty instead of being set to $label, regardless of whether the line is a supplier line.', 'Removes the short product/service label text from printed lines, leaving only the free-text description (if any) via later dol_concatdesc() calls.', 'Boolean-like (set/unset); when set, product/service label is omitted from the line', 1, 0, NULL, 1, 'e4a74d31015f4522d0688695f1ca60e770e46a71f201e1743ba530cba6cc64bb', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:2017|check|if (!getDolGlobalString(''PDF_HIDE_PRODUCT_LABEL_IN_SUPPLIER_LINES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_HIDE_PRODUCT_REF_IN_SUPPLIER_LINES', 'bool', NULL, 'core', 'Controls whether and how the product reference is hidden or replaced in supplier document lines on PDFs.', 'Checked in core/lib/pdf.lib.php at lines 2123, 2128, and 2130. When not set, the common case applies (ref shown). Value 1 and value 2 trigger distinct alternate display paths.', 'Setting to 0 or empty shows the product reference (common case). Setting to 1 or 2 activates alternate display modes for supplier line references.', '0 or empty = show product ref (common case); 1 = first alternate mode; 2 = second alternate mode', 1, 0, NULL, 1, 'fd9e33b35c5846a0bd7fc87e7afa0d785306b69b3d06f2fb4d628a680c4a3ead', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:2123|check|if (!getDolGlobalString(''PDF_HIDE_PRODUCT_REF_IN_SUPPLIER_LINES'')) {  // Common case", "core/lib/pdf.lib.php:2128|read|} elseif (getDolGlobalInt(''PDF_HIDE_PRODUCT_REF_IN_SUPPLIER_LINES'') == 1) {", "core/lib/pdf.lib.php:2130|read|} elseif (getDolGlobalInt(''PDF_HIDE_PRODUCT_REF_IN_SUPPLIER_LINES'') == 2) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_INCLUDE_ALIAS_IN_THIRDPARTY_NAME', 'string', NULL, 'core', 'Controls whether and how the third-party alias is appended to the company name in PDFs.', 'Written in admin/pdf.php:195 and read in core/lib/pdf.lib.php:400-412. Value 2 places the alias on a separate line; any truthy value appends the alias to the name.', 'Changing this value alters how third-party names are displayed in all generated PDFs that include company names.', '0 = do not include alias; 1 = append alias to name; 2 = alias on separate line.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'e4ae12eb4068f21236d34c69dd58597711c992d6458d8246f710e5da15ed81b0', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:400|check|if (($includealias || getDolGlobalInt(''PDF_INCLUDE_ALIAS_IN_THIRDPARTY_NAME'')) && !empty($thirdparty->name_alias)) {", "core/lib/pdf.lib.php:401|check|if (getDolGlobalInt(''PDF_INCLUDE_ALIAS_IN_THIRDPARTY_NAME'') == 2) {", "admin/pdf.php:195|write|dolibarr_set_const($db, \"PDF_INCLUDE_ALIAS_IN_THIRDPARTY_NAME\", GETPOST(''PDF_INCLUDE_ALIAS_IN_THIRDPARTY_NAME'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:447|read|print $form->selectarray(\"PDF_INCLUDE_ALIAS_IN_THIRDPARTY_NAME\", $arrval, getDolGlobalInt(''PDF_INCLUDE_ALIAS_IN_THIRDPARTY_NAME''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_INVOICE_HIDE_PRICE_EXCL_TAX', 'bool', NULL, 'core', 'Hides the ''total excl. tax'' column on the Sponge PDF invoice line table.', 'Read at core/modules/facture/doc/pdf_sponge.modules.php:2805 to compute the ''totalexcltax'' column status, combined with PDF_PURCHASE_INVOICE_HIDE_PRICE_EXCL_TAX.', 'When truthy, the total-excl-tax column is hidden from the invoice line table PDF (unless overridden per-line by other logic).', 'Truthy hides the column; empty/0 shows it (default visible).', 1, 0, NULL, 1, '59a0cc909a1517f75fb6bef746638a0de8752e7270cce1ab1e700a5dac209726', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/pdf_sponge.modules.php:2805: ''status'' => !getDolGlobalBool(''PDF_INVOICE_HIDE_PRICE_EXCL_TAX'') && !getDolGlobalBool(''PDF_PURCHASE_INVOICE_HIDE_PRICE_EXCL_TAX''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_INVOICE_SHOW_BALANCE_SUMMARY', 'bool', NULL, 'admin', 'Controls whether a balance summary section is shown on invoice PDFs for non-draft invoices.', 'Written in admin/pdf_other.php at lines 162 and 163 (set/del) and displayed as a select at line 615. Checked in pdf_octopus.modules.php at line 1355 and pdf_sponge.modules.php at line 1421, both requiring invoice status > STATUS_DRAFT.', 'Enabling this constant adds a balance summary block to invoice PDFs when the invoice is not in draft status. Disabling it omits the balance summary.', 'Non-zero integer to show balance summary on non-draft invoices; 0 or unset to hide it.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, '4dc4f81513efd545b4fd2eb84faf48f31cfdefcbf8ce0af519ac0762a9b9827d', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:162|write|dolibarr_set_const($db, \"PDF_INVOICE_SHOW_BALANCE_SUMMARY\", GETPOSTINT(\"PDF_INVOICE_SHOW_BALANCE_SUMMARY\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/facture/doc/pdf_octopus.modules.php:1355|check|if ($object->status > Facture::STATUS_DRAFT && getDolGlobalInt(''PDF_INVOICE_SHOW_BALANCE_SUMMARY'')) {", "core/modules/facture/doc/pdf_sponge.modules.php:1421|check|if ($object->status > Facture::STATUS_DRAFT && getDolGlobalInt(''PDF_INVOICE_SHOW_BALANCE_SUMMARY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_INVOICE_SHOW_PRICE_INCL_TAX', 'bool', NULL, 'admin', 'Controls whether invoice PDF templates show a total price column including tax.', 'Toggled via admin/pdf_other.php:492 with the same ajax on/off pattern, and read in core/modules/facture/doc/pdf_sponge.modules.php:2816 to enable the ''totalincltax'' PDF column, but only if PDF_PURCHASE_INVOICE_SHOW_PRICE_INCL_TAX is not also set.', 'Enabling it adds a total-including-tax column to the pdf_sponge invoice PDF model, unless the purchase-invoice variant of the option overrides it.', '0 = No (hide column), 1 = Yes (show column with tax included total).', 0, 0, 'admin/pdf_other.php', 1, '5eed4239c5e0566439a18d815320ed58ee2f4c89359b26f46b7ea771dfd7eaee', 'v2', '2026-07-24T07:05:23+00:00', '["admin/pdf_other.php:492|print $form->selectarray(\"PDF_INVOICE_SHOW_PRICE_INCL_TAX\", $arrval, getDolGlobalString(''PDF_INVOICE_SHOW_PRICE_INCL_TAX''));", "core/modules/facture/doc/pdf_sponge.modules.php:2816|''status'' => getDolGlobalBool(''PDF_INVOICE_SHOW_PRICE_INCL_TAX'') && !getDolGlobalBool(''PDF_PURCHASE_INVOICE_SHOW_PRICE_INCL_TAX''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_INVOICE_SHOW_VAT_ANALYSIS', 'bool', NULL, 'core', 'Controls whether a VAT analysis section is shown on invoice PDFs, overriding the default behavior of showing VAT detail.', 'Configured via admin/pdf_other.php (written at line 158/159, rendered as a select array at line 603). Checked across 10 occurrences in core/lib/pdf.lib.php and invoice PDF modules. The comment at line 915 states: ''by default, we show detail of vat here''.', 'Changing this value toggles whether the VAT analysis breakdown section is included in generated invoice PDFs.', '0 or absent = show VAT detail by default; non-zero = alter VAT analysis display as per selected value.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, 'c588b84be5b153cdc9d27705062bc42b8628f8a133112aeec41cc0f0edf5556b', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:915|check|if (!getDolGlobalInt(''PDF_INVOICE_SHOW_VAT_ANALYSIS'')) {\t// by default, we show detail of vat here", "admin/pdf_other.php:158|write|dolibarr_set_const($db, \"PDF_INVOICE_SHOW_VAT_ANALYSIS\", GETPOSTINT(\"PDF_INVOICE_SHOW_VAT_ANALYSIS\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf_other.php:603|read|print $form->selectarray(\"PDF_INVOICE_SHOW_VAT_ANALYSIS\", $arrval, getDolGlobalInt(''PDF_INVOICE_SHOW_VAT_ANALYSIS''));", "core/modules/facture/doc/pdf_octopus.modules.php:1266|check|if ($object->total_tva != 0 && getDolGlobalInt(''PDF_INVOICE_SHOW_VAT_ANALYSIS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_LOCALTAX1_LABEL_IS_CODE_OR_RATE', 'string', NULL, 'core', 'Controls whether the local tax 1 label in PDF tax summaries shows the tax code, rate, or neither.', 'Checked across 8 occurrences in core/lib/pdf.lib.php and PDF modules (commande, propale). The only documented value is ''nocodenorate'', which suppresses both code and rate from the label. No admin UI write is present.', 'Setting this to ''nocodenorate'' removes the tax code and rate from local tax 1 labels in PDF documents.', '''nocodenorate'' = show neither code nor rate in local tax 1 label; other values or absent = default label behavior.', 1, 0, NULL, 1, '41811f55922678eecf340e81da8801726f39861ac47f094af2b1407802d61b38', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:838|check|if (getDolGlobalString(''PDF_LOCALTAX1_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {", "core/modules/commande/doc/pdf_einstein.modules.php:1022|check|if (getDolGlobalString(''PDF_LOCALTAX1_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {", "core/modules/commande/doc/pdf_eratosthene.modules.php:1283|check|if (getDolGlobalString(''PDF_LOCALTAX1_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {", "core/modules/propale/doc/pdf_azur.modules.php:1219|check|if (getDolGlobalString(''PDF_LOCALTAX1_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_LOCALTAX2_LABEL_IS_CODE_OR_RATE', 'string', NULL, 'core', 'Controls whether the local tax 2 label in PDF tax summaries shows the tax code, rate, or neither.', 'Checked across 9 occurrences in core/lib/pdf.lib.php and PDF modules (commande, propale). The only documented value is ''nocodenorate'', which suppresses both code and rate from the label. No admin UI write is present.', 'Setting this to ''nocodenorate'' removes the tax code and rate from local tax 2 labels in PDF documents.', '''nocodenorate'' = show neither code nor rate in local tax 2 label; other values or absent = default label behavior.', 1, 0, NULL, 1, '6887155dbe2d04842776af5768ac9c647beb5a786bd470566f2197aca3d45a89', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:875|check|if (getDolGlobalString(''PDF_LOCALTAX2_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {", "core/modules/commande/doc/pdf_einstein.modules.php:1058|check|if (getDolGlobalString(''PDF_LOCALTAX2_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {", "core/modules/commande/doc/pdf_eratosthene.modules.php:1319|check|if (getDolGlobalString(''PDF_LOCALTAX2_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {", "core/modules/propale/doc/pdf_azur.modules.php:1255|check|if (getDolGlobalString(''PDF_LOCALTAX2_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ORDER_HIDE_PRICE_EXCL_TAX', 'bool', NULL, 'core', 'Hides the ''total excl. tax'' column on the order PDF model when set.', 'Read in core/modules/commande/doc/pdf_eratosthene.modules.php:2123: `$this->cols[''totalexcltax''] = array(... ''status'' => !getDolGlobalString(''PDF_ORDER_HIDE_PRICE_EXCL_TAX''), ...);` — the column''s displayed status is the negation of the constant.', 'Enabling it hides the total-excluding-tax column from the generated order PDF; disabled/unset (default) shows the column.', 'Boolean-like: truthy hides the totalexcltax column (status becomes false).', 0, 0, NULL, 1, 'f7708c07f512b8e5a3006ac3c30a3d9a324e047f2823207daf09b4a1a6737bc0', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/commande/doc/pdf_eratosthene.modules.php:2123: ''status'' => !getDolGlobalString(''PDF_ORDER_HIDE_PRICE_EXCL_TAX''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_ORDER_SHOW_PRICE_INCL_TAX', 'bool', NULL, 'admin', 'Controls whether sales order PDF templates show a total price column including tax.', 'Toggled via admin/pdf_other.php:370 with the same ajax on/off pattern as PDF_PROPAL_SHOW_PRICE_INCL_TAX, and read in core/modules/commande/doc/pdf_eratosthene.modules.php:2134 to enable the ''totalincltax'' PDF column.', 'Enabling it adds a total-including-tax column to the pdf_eratosthene order PDF model.', '0 = No (hide column), 1 = Yes (show column with tax included total).', 0, 0, 'admin/pdf_other.php', 1, '66a4f863c3274c713bedfdf0177532cc2d94f845a4fd30c4c20ad529cb064cef', 'v2', '2026-07-24T07:05:23+00:00', '["admin/pdf_other.php:370|print $form->selectarray(\"PDF_ORDER_SHOW_PRICE_INCL_TAX\", $arrval, getDolGlobalString(''PDF_ORDER_SHOW_PRICE_INCL_TAX''));", "core/modules/commande/doc/pdf_eratosthene.modules.php:2134|''status'' => getDolGlobalBool(''PDF_ORDER_SHOW_PRICE_INCL_TAX''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_PROPAL_HIDE_PRICE_EXCL_TAX', 'bool', NULL, 'core', 'When enabled, hides the ''total excl. tax'' column from the Cyan proposal PDF line table.', 'Read in core/modules/propale/doc/pdf_cyan.modules.php:2257, negated directly into the ''totalexcltax'' column''s status field.', 'Enabling it removes the excl.-tax total column from generated Cyan proposal PDFs.', 'Boolean: true/1 hides the excl.-tax price column (status becomes false when the constant is true).', 0, 0, NULL, 1, 'e3fea2c00167f0d00f40031bbde374ca743b30e03c4448e9a817fd91a51e8acd', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:2257|read|''status'' => !getDolGlobalString(''PDF_PROPAL_HIDE_PRICE_EXCL_TAX''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_PROPAL_SHOW_PRICE_INCL_TAX', 'bool', NULL, 'admin', 'Controls whether commercial proposal PDF templates show a total price column including tax.', 'Toggled via admin/pdf_other.php:290 using an ajax on/off control (PDF_XXX_SHOW_PRICE_INCL_TAX label), and read in core/modules/propale/doc/pdf_cyan.modules.php:2268 to enable the ''totalincltax'' PDF column.', 'Enabling it adds a total-including-tax column to the pdf_cyan proposal PDF model; the admin page notes it is only ''AvailableWithSomePDFTemplatesOnly''.', '0 = No (hide column), 1 = Yes (show column with tax included total).', 0, 0, 'admin/pdf_other.php', 1, '6112739babd1dbdf78a0d1ce61417293dccb1543516871dc14f455113801918b', 'v2', '2026-07-24T07:05:23+00:00', '["admin/pdf_other.php:290|print $form->selectarray(\"PDF_PROPAL_SHOW_PRICE_INCL_TAX\", $arrval, getDolGlobalString(''PDF_PROPAL_SHOW_PRICE_INCL_TAX''));", "core/modules/propale/doc/pdf_cyan.modules.php:2268|''status'' => getDolGlobalBool(''PDF_PROPAL_SHOW_PRICE_INCL_TAX''),", "admin/pdf_other.php: $arrval = array(''0'' => $langs->trans(\"No\"), ''1'' => $langs->trans(\"Yes\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_PURCHASE_INVOICE_HIDE_PRICE_EXCL_TAX', 'bool', NULL, 'core', 'Hides the ''total excl. tax'' column on the Sponge PDF for purchase invoices specifically.', 'Read at core/modules/facture/doc/pdf_sponge.modules.php:2805 alongside PDF_INVOICE_HIDE_PRICE_EXCL_TAX to compute the ''totalexcltax'' column status.', 'When truthy, the total-excl-tax column is hidden from the (purchase) invoice line table PDF.', 'Truthy hides the column; empty/0 leaves visibility to PDF_INVOICE_HIDE_PRICE_EXCL_TAX.', 1, 0, NULL, 1, '0c96d3c8dc3712fd5a3c3f8dca713ac116e5232fdb4c33630ec238f31696fc72', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/pdf_sponge.modules.php:2805: ''status'' => !getDolGlobalBool(''PDF_INVOICE_HIDE_PRICE_EXCL_TAX'') && !getDolGlobalBool(''PDF_PURCHASE_INVOICE_HIDE_PRICE_EXCL_TAX''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_PURCHASE_INVOICE_SHOW_PRICE_INCL_TAX', 'bool', NULL, 'core', 'Overrides PDF_INVOICE_SHOW_PRICE_INCL_TAX to hide the ''total incl. tax'' column specifically for purchase invoices.', 'Read at core/modules/facture/doc/pdf_sponge.modules.php:2816 to compute the ''totalincltax'' column status: shown only if PDF_INVOICE_SHOW_PRICE_INCL_TAX is set AND this constant is NOT set.', 'When truthy, it suppresses the total-incl-tax column on purchase invoice PDFs even if PDF_INVOICE_SHOW_PRICE_INCL_TAX is enabled globally.', 'Truthy disables (negates) the incl-tax column for purchase invoices; empty/0 defers to PDF_INVOICE_SHOW_PRICE_INCL_TAX.', 1, 0, NULL, 1, '50263224ec205c84e6be1460cd85407fd8be32bcf5cbe9a3ee3a1c4cd831262b', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/pdf_sponge.modules.php:2816: ''status'' => getDolGlobalBool(''PDF_INVOICE_SHOW_PRICE_INCL_TAX'') && !getDolGlobalBool(''PDF_PURCHASE_INVOICE_SHOW_PRICE_INCL_TAX''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SECURITY_ENCRYPTION', 'string', NULL, 'admin', 'Enables TCPDF password protection/encryption of generated PDFs; explicitly documented as an unsupported, hidden option that breaks other PDF features.', 'Read in admin/pdf.php:294 (prints a warning banner) and core/lib/pdf.lib.php:199 (actually applies $pdf->SetProtection() with rights/passwords/strength/pubkeys from PDF_SECURITY_ENCRYPTION_RIGHTS, _USERPASS, _OWNERPASS, _STRENGTH, _PUBKEYS). No admin UI form field sets it (ADMIN_UI blank); it is only surfaced as a warning if already set.', 'Enabling it makes Dolibarr call SetProtection on every generated PDF, which per the code''s own warning breaks mass PDF generation and online PDF signature; the admin page explicitly recommends disabling it.', 'Truthy = encryption enabled (hidden/unsupported); falsy/unset = normal PDF generation. Related keys PDF_SECURITY_ENCRYPTION_STRENGTH: 0=RC4 40 bit, 1=RC4 128 bit, 2=AES 128 bit, 3=AES 256 bit.', 1, 0, 'admin/pdf.php', 1, 'fa592e23c3c86be4cb00f7e86f7b1030442bc3c4ca81c6590244b9e2934439e7', 'v2', '2026-07-24T07:05:23+00:00', '["admin/pdf.php:296|The not supported and hidden option PDF_SECURITY_ENCRYPTION has been enabled. This means a lof of feature related to PDF will be broken, like mass PDF generation...", "core/lib/pdf.lib.php:199|if (getDolGlobalString(''PDF_SECURITY_ENCRYPTION'')) {", "core/lib/pdf.lib.php:221|// For encryption strength: 0 = RC4 40 bit; 1 = RC4 128 bit; 2 = AES 128 bit; 3 = AES 256 bit"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SECURITY_ENCRYPTION_OWNERPASS', 'string', NULL, 'core', 'Sets the owner password for generated PDFs (controls who can change permissions/encryption), when PDF encryption (PDF_SECURITY_ENCRYPTION) is enabled.', 'Read in core/lib/pdf.lib.php:219, only consulted when PDF_SECURITY_ENCRYPTION is set; if non-empty it is used as $pdfownerpass, otherwise null is passed to $pdf->SetProtection(), letting TCPDF generate a random owner password.', 'Setting it fixes a known owner password on generated PDFs (needed to later change permissions/encryption); leaving it unset lets TCPDF create the owner password randomly per the inline comment.', 'String: plaintext owner password; empty/unset lets TCPDF create one randomly.', 1, 0, NULL, 1, '018558b3adfa4b357a2e12637d76408adabf0ac6ba6b4b5b07c93fa05095d41e', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:219|read|$pdfownerpass = (getDolGlobalString(''PDF_SECURITY_ENCRYPTION_OWNERPASS'') ? getDolGlobalString(''PDF_SECURITY_ENCRYPTION_OWNERPASS'') : null);", "// Password of the owner, created randomly if not defined"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SECURITY_ENCRYPTION_PUBKEYS', 'string', NULL, 'core', 'JSON-encoded array of public-key certificates and permissions used for public-key PDF encryption.', 'Read in core/lib/pdf.lib.php:226, json_decode()''d and passed as the $pubkeys argument to TCPDF''s SetProtection() for certificate-based encryption.', 'When set, PDF is encrypted for specific recipients identified by X.509 certificates instead of (or in addition to) password-based protection.', 'JSON array of objects with ''c'' (path to certificate file, e.g. file://../examples/data/cert/tcpdf.crt) and ''p'' (array of permissions, e.g. array(''print'')); stored as JSON in llx_const', 1, 0, NULL, 1, 'e247606fcb974ad0bf194f6b22bd8bc0658cb3e87a05058ed12f731e6e575edb', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:226|read|$pubkeys = (getDolGlobalString(''PDF_SECURITY_ENCRYPTION_PUBKEYS'') ? json_decode(...) : null); // Json format in llx_const", "core/lib/pdf.lib.php:224: // Array of recipients containing public-key certificates (''c'') and permissions (''p'').", "core/lib/pdf.lib.php:225: // For example: array(array(''c'' => ''file://../examples/data/cert/tcpdf.crt'', ''p'' => array(''print'')))"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SECURITY_ENCRYPTION_RIGHTS', 'string', NULL, 'core', 'Sets the list of PDF permissions to restrict (block) when TCPDF-based PDF encryption (PDF_SECURITY_ENCRYPTION) is enabled.', 'Read in core/lib/pdf.lib.php:213, only consulted when PDF_SECURITY_ENCRYPTION is set; the value is JSON-decoded into $pdfrights and passed to $pdf->SetProtection(). Default when unset is array(''modify'', ''copy''). A block comment above lists all TCPDF-supported permission keywords (print, modify, copy, annot-forms, fill-forms, extract, assemble, print-high, owner).', 'Setting it (as a JSON array of permission keywords) changes which actions are blocked on generated PDFs when PDF encryption is active; leaving it unset blocks only ''modify'' and ''copy'' by default.', 'JSON array string of TCPDF permission keywords: print, modify, copy, annot-forms, fill-forms, extract, assemble, print-high, owner. Default if unset: [''modify'',''copy''].', 1, 0, NULL, 1, '6f9fbf051dacb4e2b29be78e8e3c6406d3c873b8a9f7bc8ab2f48820b3cd6c8e', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:213|read|$pdfrights = (getDolGlobalString(''PDF_SECURITY_ENCRYPTION_RIGHTS'') ? json_decode(getDolGlobalString(''PDF_SECURITY_ENCRYPTION_RIGHTS''), true) : array(''modify'', ''copy'')); // Json format in llx_const", "- print : Print the document; - modify : Modify the contents...; - copy : Copy or otherwise extract text and graphics from the document;", "// For TCPDF, we specify permission we want to block"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SECURITY_ENCRYPTION_STRENGTH', 'string', NULL, 'core', 'Sets the RC4/AES encryption strength used when PDF security/encryption is enabled.', 'Read in core/lib/pdf.lib.php:222 via getDolGlobalInt(''PDF_SECURITY_ENCRYPTION_STRENGTH'', 0) to build the $encstrength argument passed to TCPDF''s SetProtection().', 'Changes the cipher and key length used to encrypt generated PDFs; higher values give stronger encryption but require compatible PDF readers.', '0 = RC4 40 bit; 1 = RC4 128 bit; 2 = AES 128 bit; 3 = AES 256 bit (comment above the code, default 0)', 1, 0, NULL, 1, '588cbb2a1c59cbae668fccfc7c73abeb8fc523526d2d48202854a11150a60d1d', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:222|read|$encstrength = getDolGlobalInt(''PDF_SECURITY_ENCRYPTION_STRENGTH'', 0);", "core/lib/pdf.lib.php:221: // For encryption strength: 0 = RC4 40 bit; 1 = RC4 128 bit; 2 = AES 128 bit; 3 = AES 256 bit"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SECURITY_ENCRYPTION_USERPASS', 'string', NULL, 'core', 'Sets the end-user (open) password required to open generated PDFs, when PDF encryption (PDF_SECURITY_ENCRYPTION) is enabled.', 'Read in core/lib/pdf.lib.php:216, only consulted when PDF_SECURITY_ENCRYPTION is set; passed directly as the userpass argument to $pdf->SetProtection($pdfrights, $pdfuserpass, ...).', 'Setting it requires anyone opening the generated PDF to enter this password; leaving it unset/empty produces PDFs with no open password (only owner-permission restrictions apply, if any).', 'String: plaintext password used as the PDF user/open password.', 1, 0, NULL, 1, '5f4187052febf0f280beffacda9a6f169bff1b5aa77edf9b2f5e34f6f6c15eb4', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:216|read|$pdfuserpass = getDolGlobalString(''PDF_SECURITY_ENCRYPTION_USERPASS'');", "// Password for the end user", "$pdf->SetProtection($pdfrights, $pdfuserpass, $pdfownerpass, $encstrength, $pubkeys);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SHOW_EMAIL_AFTER_USER_CONTACT', 'bool', NULL, 'core', 'Shows the contact user''s email address in parentheses after their name in PDF issuer blocks.', 'Used in 60 occurrences across all PDF module files. The email is appended in the carac_emetteur string when this constant is set and the user email is available. Works in combination with PDF_SHOW_PHONE_AFTER_USER_CONTACT.', 'Setting this constant adds the contact user''s email address to the issuer block in all PDF documents.', 'Non-zero = email shown after contact name; 0 or unset = email not shown', 1, 0, NULL, 1, 'f0e78ac528e898813b416f583422c0752b94214531b98270ceed8e1377cc2636', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:754|read|$carac_emetteur .= (getDolGlobalInt(''PDF_SHOW_PHONE_AFTER_USER_CONTACT'') || getDolGlobalInt(''PDF_SHOW_EMAIL_AFTER_USER_CONTACT'')) ? '' ('' : '''';", "core/modules/contract/doc/pdf_strato.modules.php:757|read|$carac_emetteur .= (getDolGlobalInt(''PDF_SHOW_EMAIL_AFTER_USER_CONTACT'') && !empty($object->user->email)) ? $object->user->email : '''';", "core/modules/expedition/doc/pdf_rouget.modules.php:1071|read|$carac_emetteur .= (getDolGlobalInt(''PDF_SHOW_EMAIL_AFTER_USER_CONTACT'') && !empty($object->user->email)) ? $object->user->email : '''';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SHOW_LINK_TO_ONLINE_PAYMENT', 'bool', NULL, 'admin', 'Shows a link to the online payment page on generated invoice PDF documents.', 'Set via admin UI at admin/pdf.php:187/671 (yes/no select) and checked in core/modules/facture/doc/pdf_sponge.modules.php:1591 and core/modules/facture/doc/pdf_octopus.modules.php:1576.', 'When enabled, the invoice PDF models (pdf_sponge, pdf_octopus) display a link/reference to the online payment page.', NULL, 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'b4816da33465720149d4d4eb789db1d4072506a510da35d2b7ea49f6df453a18', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, \"PDF_SHOW_LINK_TO_ONLINE_PAYMENT\", GETPOST(''PDF_SHOW_LINK_TO_ONLINE_PAYMENT'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''PDF_SHOW_LINK_TO_ONLINE_PAYMENT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SHOW_PHONE_AFTER_USER_CONTACT', 'bool', NULL, 'core', 'Shows the contact user''s phone number in parentheses after their name in PDF issuer blocks.', 'Used in 60 occurrences across all PDF module files. The phone is appended in the carac_emetteur string when this constant is set and office_phone is available. Works in combination with PDF_SHOW_EMAIL_AFTER_USER_CONTACT.', 'Setting this constant adds the contact user''s phone number to the issuer block in all PDF documents.', 'Non-zero = phone shown after contact name; 0 or unset = phone not shown', 1, 0, NULL, 1, 'c813725d6360c6bc74c80693c6ccd913f7f043671544515a2e09ee262f7022af', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/contract/doc/pdf_strato.modules.php:754|read|$carac_emetteur .= (getDolGlobalInt(''PDF_SHOW_PHONE_AFTER_USER_CONTACT'') || getDolGlobalInt(''PDF_SHOW_EMAIL_AFTER_USER_CONTACT'')) ? '' ('' : '''';", "core/modules/contract/doc/pdf_strato.modules.php:755|read|$carac_emetteur .= (getDolGlobalInt(''PDF_SHOW_PHONE_AFTER_USER_CONTACT'') && !empty($object->user->office_phone)) ? $object->user->office_phone : '''';", "core/modules/expedition/doc/pdf_rouget.modules.php:1069|read|$carac_emetteur .= (getDolGlobalInt(''PDF_SHOW_PHONE_AFTER_USER_CONTACT'') && !empty($object->user->office_phone)) ? $object->user->office_phone : '''';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SHOW_PROJECT', 'bool', NULL, 'core', 'Controls whether the linked project reference is shown on generated PDF documents.', 'Written via admin/pdf.php:130 (set when user selects ''showprojectref'') and read at admin/pdf.php:547 in combination with PDF_SHOW_PROJECT_TITLE: $showprojectref = !getDolGlobalString(''PDF_SHOW_PROJECT'') ? (!getDolGlobalString(''PDF_SHOW_PROJECT_TITLE'') ? ''no'' : ''showprojectlabel'') : ''showprojectref''. Checked across 21 occurrences in PDF modules.', 'Setting this causes PDF documents to display the linked project reference number; it takes precedence over PDF_SHOW_PROJECT_TITLE.', '0 or unset = project reference not shown; 1 = project reference shown.', 0, 0, 'admin/pdf.php|admin/pdf.php|admin/pdf.php|admin/pdf.php', 1, 'a8785b8d36efa7a0f28923f6c3bc071250ab1d2e2e7c45431af5d8784394de1b', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:130|write|dolibarr_set_const($db, \"PDF_SHOW_PROJECT\", GETPOST(\"PDF_SHOW_PROJECT_REF_OR_LABEL\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:547|read|$showprojectref = !getDolGlobalString(''PDF_SHOW_PROJECT'') ? (!getDolGlobalString(''PDF_SHOW_PROJECT_TITLE'') ? ''no'' : ''showprojectlabel'') : ''showprojectref'';", "recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:830|check|if (getDolGlobalString(''PDF_SHOW_PROJECT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SHOW_PROJECT_TITLE', 'bool', NULL, 'core', 'Controls whether the linked project label is shown on generated PDF documents.', 'Written via admin/pdf.php:134 (set when user selects ''showprojectlabel'') and read at admin/pdf.php:547 in combination with PDF_SHOW_PROJECT: $showprojectref = !getDolGlobalString(''PDF_SHOW_PROJECT'') ? (!getDolGlobalString(''PDF_SHOW_PROJECT_TITLE'') ? ''no'' : ''showprojectlabel'') : ''showprojectref''. Checked across 22 occurrences in PDF modules.', 'Setting this causes PDF documents to display the linked project label; it takes effect only when PDF_SHOW_PROJECT is not set.', '0 or unset = project label not shown; 1 = project label shown (when PDF_SHOW_PROJECT is unset).', 0, 0, 'admin/pdf.php|admin/pdf.php|admin/pdf.php|admin/pdf.php', 1, '2675f677526a03f630033ddff87c9bd91568895768dcc67175924106e81e85f4', 'v2', '2026-04-21T11:16:15+00:00', '["admin/pdf.php:134|write|dolibarr_set_const($db, \"PDF_SHOW_PROJECT_TITLE\", GETPOST(\"PDF_SHOW_PROJECT_REF_OR_LABEL\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:547|read|$showprojectref = !getDolGlobalString(''PDF_SHOW_PROJECT'') ? (!getDolGlobalString(''PDF_SHOW_PROJECT_TITLE'') ? ''no'' : ''showprojectlabel'') : ''showprojectref'';", "core/modules/asset/doc/pdf_standard_asset.modules.php:890|check|if (getDolGlobalString(''PDF_SHOW_PROJECT_TITLE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SPONGE_ADD_POSITION', 'string', NULL, 'core', 'Shows a line-position (''#'') column on the Sponge/Octopus PDF invoice line table.', 'Used in core/modules/facture/doc/pdf_sponge.modules.php:2657 and pdf_octopus.modules.php:2472 to set the ''status'' (visibility) of the ''position'' column, falling back to PDF_ADD_POSITION if unset.', 'When set truthy, the invoice PDF line table gains a leading position/rank column; otherwise it falls back to PDF_ADD_POSITION or is hidden.', 'Truthy (1) shows the position column; empty/0 falls back to PDF_ADD_POSITION.', 1, 0, NULL, 1, '15ad5f644fd33416a09dc663d1c8ea755e1ef152b394dfded26b9d6ab23ad3e5', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/facture/doc/pdf_sponge.modules.php:2657: ''status'' => getDolGlobalInt(''PDF_SPONGE_ADD_POSITION'') ? true : (getDolGlobalInt(''PDF_ADD_POSITION'') ? true : false),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_SWISS_QRCODE_USE_OWNER_OF_ACCOUNT_AS_CREDITOR', 'bool', NULL, 'core', 'On Swiss QR-bill (SPC) invoice PDFs, use the bank account''s owner name/address as the QR creditor instead of the company (mysoc) identity.', 'Used in core/class/commoninvoice.class.php:2402 in the Swiss QR-code payload generator; when a bank account is set on the invoice and this constant is truthy, the code writes $bankaccount->owner_name/owner_address into the ''S'' (creditor) section of the QR string instead of $mysoc->name/address/zip/town.', 'Enabling it changes who appears as the payment creditor on generated Swiss QR-bills, from the company identity to the linked bank account''s registered owner; only applies when a bank account is set on the invoice.', 'Boolean-like: truthy uses bank account owner_name/owner_address as creditor in the QR-bill; falsy/unset (default) uses $mysoc (company) name/address/zip/town.', 1, 0, NULL, 1, '3fa53d71083c36a7210d50d69b6acd4a5b551ecd4b1bef3301c852e6e4b22934', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commoninvoice.class.php:2402|check|if ($bankaccount->id > 0 && getDolGlobalString(''PDF_SWISS_QRCODE_USE_OWNER_OF_ACCOUNT_AS_CREDITOR'')) {", "// If a bank account is provided and we ask to use it as creditor, we use the bank address", "$s .= dol_trunc($bankaccount->owner_name, 70, ''right'', ''UTF-8'', 1).\"\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_USE_A', 'bool', NULL, 'admin', 'Selects the PDF/A compliance level (PDF/A-1 or PDF/A-3) for generated PDF documents.', 'Written in admin/pdf.php:198 and read in admin/pdf.php:678 and core/lib/pdf.lib.php:190 with inline comment ''// PDF/A-1 ou PDF/A-3''. Default is 0 (no PDF/A).', 'Setting a non-zero value enables PDF/A archival compliance mode; setting to 0 disables it.', 'Integer: 0 = no PDF/A compliance (default); 1 = PDF/A-1; 3 = PDF/A-3.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'ef01e278716dd0656cd2e6b3e7322582e235099dff6b0f474e88956d49f41354', 'v2', '2026-04-21T13:29:58+00:00', '["admin/pdf.php:678|read|$pdfa = getDolGlobalInt(''PDF_USE_A'', 0); \t// PDF/A-1 ou PDF/A-3", "core/lib/pdf.lib.php:190|read|$pdfa = getDolGlobalInt(''PDF_USE_A'', 0); \t// PDF/A-1 ou PDF/A-3", "admin/pdf.php:198|write|dolibarr_set_const($db, \"PDF_USE_A\", GETPOST(''PDF_USE_A'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_USE_ALSO_LANGUAGE_CODE', 'bool', NULL, 'core', 'Specifies a secondary language code to use when generating PDFs, e.g. for translating third-party names.', 'Configured via admin/pdf.php. Read in 78 occurrences across many modules. Comments in core/class/commonobject.class.php:6577, :6646, :7281 describe it as used for the name of a thirdparty when a secondary language is needed in PDFs.', 'When set, PDF generation uses a second language (e.g. for bilingual PDFs or when the third-party''s preferred language differs from the system default).', 'Language code string (e.g. ''de_DE'') or empty/unset to use only the default language', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, '6f172f5598379fb4c756049d6afdb469ae806e40286adcd27f57071759ecd2e3', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/commonobject.class.php:6577  *  Used for example when PDF_USE_ALSO_LANGUAGE_CODE is set to a language for the name of a thirdparty.", "admin/pdf.php:180|write|dolibarr_set_const($db, \"PDF_USE_ALSO_LANGUAGE_CODE\", GETPOST(''PDF_USE_ALSO_LANGUAGE_CODE'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:216|check|if (getDolGlobalString(''PDF_USE_ALSO_LANGUAGE_CODE'') && $outputlangs->defaultlang != getDolGlobalString(''PDF_USE_ALSO_LANGUAGE_CODE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PDF_VAT_LABEL_IS_CODE_OR_RATE', 'string', NULL, 'core', 'Controls whether the VAT label in PDF tax summaries shows the rate only, code only, or neither.', 'Checked across 12 occurrences in core/lib/pdf.lib.php and PDF modules (commande, propale). Documented values are ''rateonly'', ''codeonly'', and ''nocodenorate'' as seen at lines 931, 933, 935. No admin UI write is present.', 'Setting this value changes how VAT is identified in tax summary labels across all PDF document types.', '''rateonly'' = show rate only; ''codeonly'' = show code only; ''nocodenorate'' = show neither code nor rate; absent = show both code and rate.', 1, 0, NULL, 1, '40bedbd47a690569ce8bfb1aa2cd8b8167d22ec43a58abe997997ea70e4a0164', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:931|check|if (getDolGlobalString(''PDF_VAT_LABEL_IS_CODE_OR_RATE'') == ''rateonly'') {", "core/lib/pdf.lib.php:933|read|} elseif (getDolGlobalString(''PDF_VAT_LABEL_IS_CODE_OR_RATE'') == ''codeonly'') {", "core/lib/pdf.lib.php:935|read|} elseif (getDolGlobalString(''PDF_VAT_LABEL_IS_CODE_OR_RATE'') == ''nocodenorate'') {", "core/modules/commande/doc/pdf_einstein.modules.php:1089|check|if (getDolGlobalString(''PDF_VAT_LABEL_IS_CODE_OR_RATE'') == ''rateonly'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('POSITION_ADDON_PDF', 'string', NULL, 'hrm', 'Name of the PDF document model (template) used to generate PDFs for HRM job-position objects.', 'Used as fallback model name in Position''s document-generation method when $this->model_pdf is empty, hrm/class/position.class.php:1102-1103, same pattern as SKILL_ADDON_PDF.', 'Changing it selects which PDF generation model class is used to build the position PDF document.', 'Name of a position PDF doc-generation model.', 1, 0, NULL, 1, '3774eba8a24980bfcc6c81f367b334406881655012f9444d984d45841793ccb1', 'v2', '2026-07-24T07:05:23+00:00', '["hrm/class/position.class.php:1102|read|} elseif (getDolGlobalString(''POSITION_ADDON_PDF'')) {", "hrm/class/position.class.php:1103|read|$modele = getDolGlobalString(''POSITION_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_ADDDAYS', 'string', NULL, 'admin', 'Number of days added to the current date to compute the execution date for direct debit orders.', 'Set via admin/prelevement.php:115 and displayed as an input field at :226. Defaulted to 0 at :224 when unset. Read as an integer at compta/prelevement/create.php:330 and stored in $delayindays.', 'Increasing this value delays the execution date of direct debit orders by the specified number of days.', 'Integer number of days (default 0 = no additional delay).', 0, 0, 'admin/prelevement.php|admin/prelevement.php|admin/prelevement.php|admin/prelevement.php', 1, '643c6956e7b17440d8e10491288dd925e44212ba59d6f809b888e99d8ab48ceb', 'v2', '2026-04-21T11:16:15+00:00', '["admin/prelevement.php:223|check|if (!getDolGlobalString(''PRELEVEMENT_ADDDAYS'')) {", "admin/prelevement.php:224|write|$conf->global->PRELEVEMENT_ADDDAYS = 0;", "admin/prelevement.php:226|read|print ''<input type=\"text\" name=\"PRELEVEMENT_ADDDAYS\" value=\"''.getDolGlobalString(''PRELEVEMENT_ADDDAYS'').''\"  class=\"width50\"></td>'';", "compta/prelevement/create.php:330|read|$delayindays = getDolGlobalInt(''PRELEVEMENT_ADDDAYS'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_BIC', 'string', NULL, 'admin', 'Stores the BIC/SWIFT code for the bank used in SEPA direct debit and bank transfer operations.', 'Written in admin/prelevement.php:83 and admin/paymentbybanktransfer.php:83 via dolibarr_set_const, sourced from $account->bic.', 'Changing this value updates the BIC code in generated SEPA files; an incorrect BIC will cause bank rejection.', 'String BIC/SWIFT code.', 0, 0, 'admin/paymentbybanktransfer.php|admin/prelevement.php', 1, '9d54c0225b3312cbd2229a4a8c421cc863f4dfecabf15ccf535e6a710d0a78a2', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"PRELEVEMENT_BIC\", $account->bic,''chaine'',0,'''',$conf->entity);", "$res = dolibarr_set_const($db, \"PRELEVEMENT_BIC\", $account->bic,''chaine'',0,'''',$conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_CODE_BANQUE', 'string', NULL, 'compta', 'Stores the bank code used in direct debit file generation (now deprecated and expected to be empty).', 'Written by admin/prelevement.php:73 and admin/paymentbybanktransfer.php:73 from the bank account''s code_banque. The comment at compta/prelevement/create.php:145 explicitly states this should be empty as it is no longer used.', 'This constant is a legacy field; according to the source comment it should be empty and is no longer used in modern direct debit file generation.', '// getDolGlobalString(''PRELEVEMENT_CODE_BANQUE'') and getDolGlobalString(''PRELEVEMENT_CODE_GUICHET'') should be empty (we don''t use them anymore)', 0, 0, 'admin/paymentbybanktransfer.php|admin/prelevement.php', 1, '4f41953d02371e26368d57ce99fbc5d32bbe18ad9e8f675c53bc3d6f14a6331d', 'v2', '2026-04-21T11:16:15+00:00', '["compta/prelevement/create.php:145  // getDolGlobalString(''PRELEVEMENT_CODE_BANQUE'') and getDolGlobalString(''PRELEVEMENT_CODE_GUICHET'') should be empty (we don''t use them anymore)", "admin/prelevement.php:73|write|$res = dolibarr_set_const($db, \"PRELEVEMENT_CODE_BANQUE\", $account->code_banque,''chaine'',0,'''',$conf->entity);", "compta/prelevement/create.php:146|read|$result = $bprev->create(getDolGlobalString(''PRELEVEMENT_CODE_BANQUE''), getDolGlobalString(''PRELEVEMENT_CODE_GUICHET''), $mode, $format, ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_CODE_GUICHET', 'string', NULL, 'compta', 'Stores the branch/counter code used in direct debit file generation (now deprecated and expected to be empty).', 'Written by admin/prelevement.php:75 and admin/paymentbybanktransfer.php:75 from the bank account''s code_guichet. The comment at compta/prelevement/create.php:145 explicitly states this should be empty as it is no longer used.', 'This constant is a legacy field; according to the source comment it should be empty and is no longer used in modern direct debit file generation.', '// getDolGlobalString(''PRELEVEMENT_CODE_BANQUE'') and getDolGlobalString(''PRELEVEMENT_CODE_GUICHET'') should be empty (we don''t use them anymore)', 0, 0, 'admin/paymentbybanktransfer.php|admin/prelevement.php', 1, '29f365343971841a1667b131da539d77f12a861282a5d1ef876c2bc3b5c9dfe8', 'v2', '2026-04-21T11:16:15+00:00', '["compta/prelevement/create.php:145  // getDolGlobalString(''PRELEVEMENT_CODE_BANQUE'') and getDolGlobalString(''PRELEVEMENT_CODE_GUICHET'') should be empty (we don''t use them anymore)", "admin/prelevement.php:75|write|$res = dolibarr_set_const($db, \"PRELEVEMENT_CODE_GUICHET\", $account->code_guichet,''chaine'',0,'''',$conf->entity);", "compta/prelevement/create.php:146|read|$result = $bprev->create(getDolGlobalString(''PRELEVEMENT_CODE_BANQUE''), getDolGlobalString(''PRELEVEMENT_CODE_GUICHET''), $mode, $format, ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_END_TO_END', 'string', NULL, 'compta', 'Sets a custom static EndToEndId value in SEPA direct debit XML, overriding the auto-generated invoice-based identifier.', 'When non-empty, bonprelevement.class.php:2426 inserts this value as <EndToEndId> for debit entries instead of the auto-generated ''DD-<ref>'' pattern; similarly bonprelevement.class.php:2487 for credit transfer (''CT-<ref>'' fallback). Configured via admin/prelevement.php and admin/paymentbybanktransfer.php.', 'Setting a non-empty value replaces the per-invoice EndToEndId in SEPA XML with this fixed string; leaving it empty causes the system to generate unique IDs from invoice references.', 'Non-empty string=fixed EndToEndId used in SEPA XML, empty=auto-generated ''DD-<ref>'' or ''CT-<ref>''', 0, 0, 'admin/prelevement.php|admin/paymentbybanktransfer.php|admin/prelevement.php', 1, 'da0012ead005dd5798b5bd4a7e8f73743826b1157538b5404838ffa310ce501f', 'v2', '2026-04-21T11:16:15+00:00', '["compta/prelevement/class/bonprelevement.class.php:2426|read|$XML_DEBITOR .= ''\t\t\t\t\t<EndToEndId>'' . ((getDolGlobalString(''PRELEVEMENT_END_TO_END'') != \"\") ? $conf->global->PRELEVEMENT_END_TO_END : (''DD-'' . dol_trunc($row_idfac . ''-'' . $row_ref", "compta/prelevement/class/bonprelevement.class.php:2487|read|$XML_CREDITOR .= ''\t\t\t\t\t<EndToEndId>'' . ((getDolGlobalString(''PRELEVEMENT_END_TO_END'') != \"\") ? getDolGlobalString(\"PRELEVEMENT_END_TO_END\") : (''CT-'' . dol_trunc($row_idfac . ''-'' .", "admin/prelevement.php:208|read|print ''<input type=\"text\" name=\"PRELEVEMENT_END_TO_END\" value=\"''.getDolGlobalString(''PRELEVEMENT_END_TO_END'').''\" class=\"width100\"></td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_IBAN', 'string', NULL, 'admin', 'Stores the IBAN for the bank account used in SEPA direct debit and bank transfer operations.', 'Written in admin/prelevement.php:81 and admin/paymentbybanktransfer.php:81 via dolibarr_set_const, sourced from $account->iban.', 'Changing this value updates the IBAN included in generated SEPA files; an incorrect IBAN will cause bank rejection.', 'String IBAN value.', 0, 0, 'admin/paymentbybanktransfer.php|admin/prelevement.php', 1, 'cebefb104cc7f81f1fa395a0ea115d48d58ca98a8a214b98517de56cfb193c9e', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"PRELEVEMENT_IBAN\", $account->iban,''chaine'',0,'''',$conf->entity);", "$res = dolibarr_set_const($db, \"PRELEVEMENT_IBAN\", $account->iban,''chaine'',0,'''',$conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_ICS', 'string', NULL, 'core', 'Stores the Creditor Identifier (ICS) used in SEPA direct-debit mandate documents and standing-order processing.', 'Configured via admin/prelevement.php (write at line 93, displayed at line 189). It is also read in core/modules/bank/doc/pdf_sepamandate.modules.php:280 to populate the ICS field of generated SEPA mandate PDFs when the object-level ICS is empty.', 'Removing or changing this value affects the ICS printed on SEPA mandate PDFs and potentially on direct-debit file generation; an absent value leaves the ICS field blank.', 'Any valid SEPA Creditor Identifier string.', 0, 0, 'admin/prelevement.php|admin/prelevement.php', 1, 'a043f1fc6dc021a1dec8bd82807d8f8de4581e82d10918f11b735787c27e046e', 'v2', '2026-04-21T13:50:40+00:00', '["admin/prelevement.php:189|read|print ''<input type=\"text\" name=\"PRELEVEMENT_ICS\" value=\"''.$conf->global->PRELEVEMENT_ICS.''\"", "core/modules/bank/doc/pdf_sepamandate.modules.php:279|check|if (empty($ics) && getDolGlobalString(''PRELEVEMENT_ICS'')) {", "core/lib/prelevement.lib.php:111  //if (empty($conf->global->PRELEVEMENT_ICS)) return -1;", "core/lib/prelevement.lib.php:119  //if (empty($conf->global->PRELEVEMENT_ICS)) return -1;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_ID_BANKACCOUNT', 'string', NULL, 'compta', 'Defines the bank account ID used for direct-debit type payment orders (prelevement ''bon'').', 'Set via admin UI at admin/prelevement.php:68/176, guarded in core/lib/prelevement.lib.php:116, and read in compta/prelevement/class/bonprelevement.class.php:624/1122/1899/2735 as the fallback when type is not ''bank-transfer''.', 'When set, direct-debit type payment orders use this bank account; bank-transfer type orders use PAYMENTBYBANKTRANSFER_ID_BANKACCOUNT instead.', NULL, 0, 0, 'admin/prelevement.php|admin/prelevement.php', 1, 'e374173d4bfe51dead4937872c61aae79ea848be9b82ff8f445abc3b5555355e', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''PRELEVEMENT_ID_BANKACCOUNT'')) {", "$fk_bank_account = ($this->type == ''bank-transfer'' ? getDolGlobalInt(''PAYMENTBYBANKTRANSFER_ID_BANKACCOUNT'') : getDolGlobalInt(''PRELEVEMENT_ID_BANKACCOUNT''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_NUMBER_KEY', 'string', NULL, 'admin', 'Stores the RIB key (clé RIB) for the bank account used in direct debit operations.', 'Written in admin/prelevement.php:79 and admin/paymentbybanktransfer.php:79 via dolibarr_set_const, sourced from $account->cle_rib.', 'Changing this value updates the RIB key included in direct debit files, which is required for French bank account validation.', 'String RIB key value.', 0, 0, 'admin/paymentbybanktransfer.php|admin/prelevement.php', 1, 'ba17bb00995d0a9e2b3dc8a648694f9a073c607631cb09a9603510adc215adb4', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"PRELEVEMENT_NUMBER_KEY\", $account->cle_rib,''chaine'',0,'''',$conf->entity);", "$res = dolibarr_set_const($db, \"PRELEVEMENT_NUMBER_KEY\", $account->cle_rib,''chaine'',0,'''',$conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_NUMERO_COMPTE', 'string', NULL, 'admin', 'Stores the bank account number used for direct debit (prélèvement) operations.', 'Written in admin/prelevement.php:77 and admin/paymentbybanktransfer.php:77 via dolibarr_set_const, sourced from $account->number.', 'Changing this value updates the account number embedded in generated direct debit files.', 'String bank account number.', 0, 0, 'admin/paymentbybanktransfer.php|admin/prelevement.php', 1, '273782b7fff4ec493245e3b3c02c5b24a5de68703bdc5110c1bc3e4c0c519b1e', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"PRELEVEMENT_NUMERO_COMPTE\", $account->number,''chaine'',0,'''',$conf->entity);", "$res = dolibarr_set_const($db, \"PRELEVEMENT_NUMERO_COMPTE\", $account->number,''chaine'',0,'''',$conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_RAISON_SOCIALE', 'string', NULL, 'admin', 'Stores the owner address (raison sociale / company name and address) for the bank account used in direct debit operations.', 'Written in admin/prelevement.php:85 and admin/paymentbybanktransfer.php:85 via dolibarr_set_const, sourced from $account->owner_address.', 'Changing this value updates the creditor name/address in generated direct debit files.', 'String owner address or company name.', 0, 0, 'admin/paymentbybanktransfer.php|admin/prelevement.php', 1, '5d760e10d96ad47585ace6c9dbfae5cff981572d7540809d005ed680891097c2', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"PRELEVEMENT_RAISON_SOCIALE\", $account->owner_address,''chaine'',0,'''',$conf->entity);", "$res = dolibarr_set_const($db, \"PRELEVEMENT_RAISON_SOCIALE\", $account->owner_address,''chaine'',0,'''',$conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_SEPA_SHOW_REQUESTS', 'bool', NULL, 'core', 'When enabled, adds a ''Requests'' tab to the SEPA direct-debit/prelevement card (for types other than bank-transfer and salary).', 'Checked in core/lib/prelevement.lib.php:56 inside the tab-building function for the prelevement card; the tab is only added when the object type is neither ''bank-transfer'' nor ''salary''.', 'Setting it true reveals an additional ''Requests'' tab (linking to compta/prelevement/requests.php) on applicable SEPA prelevement records.', 'Boolean: true/1 shows the Requests tab.', 0, 0, NULL, 1, 'de5551176f269d44661521a05659ed5b9acbe8277a2bfd05f67a203446795c4f', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/prelevement.lib.php:56|check|if (getDolGlobalString(''PRELEVEMENT_SEPA_SHOW_REQUESTS'') && $object->type != ''bank-transfer'' && $object->type != ''salary'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_USER', 'string', NULL, 'admin', 'Stores the Dolibarr user ID responsible for generating direct debit (prelevement) files.', 'Set via admin/prelevement.php and displayed as a user selector. Checked in core/lib/prelevement.lib.php:120 to block direct debit file generation if absent.', 'If unset, direct debit file generation is blocked; the assigned user carries responsibility for direct debit operations.', 'A valid Dolibarr user ID (integer stored as string). Empty string means no user assigned.', 0, 0, 'admin/prelevement.php|admin/prelevement.php', 1, '4fcaac42899a5da8f4434e40116e03708caa49224397c1a67bd0514b92fbdd9f', 'v2', '2026-04-21T13:29:58+00:00', '["admin/prelevement.php:97|write|$res = dolibarr_set_const($db, \"PRELEVEMENT_USER\", GETPOST(\"PRELEVEMENT_USER\"), ''chaine'', 0, '''', $conf->entity);", "core/lib/prelevement.lib.php:120|check|if (!getDolGlobalString(''PRELEVEMENT_USER'')) {", "admin/prelevement.php:198|read|print $form->select_dolusers(getDolGlobalInt(''PRELEVEMENT_USER''), ''PRELEVEMENT_USER'', 1, null, 0, '''', '''', ''0'', 0, 0, '''', 0, '''', ''minwidth200 maxwidth500'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRELEVEMENT_USTRD', 'string', NULL, 'admin', 'Sets a custom unstructured remittance information (Ustrd) string in SEPA direct debit XML.', 'When non-empty, bonprelevement.class.php:2475 inserts this value as <Ustrd> instead of the auto-generated reference+comment string. Configured via admin/prelevement.php (lines 109 and 217).', 'Setting a non-empty value replaces the per-invoice remittance information in SEPA direct debit XML with this fixed string; leaving it empty causes the system to generate the Ustrd from the invoice reference and comment.', 'Non-empty string=fixed Ustrd used, empty=auto-generated from invoice ref and comment', 0, 0, 'admin/prelevement.php|admin/prelevement.php', 1, 'b62aa6f3eb598e2bb2a53e79ac4f993e5ba3efbf737ae1437fd700fecb43d12c', 'v2', '2026-04-21T11:16:15+00:00', '["admin/prelevement.php:109|write|$res = dolibarr_set_const($db, \"PRELEVEMENT_USTRD\", GETPOST(\"PRELEVEMENT_USTRD\"), ''chaine'', 0, '''', $conf->entity);", "compta/prelevement/class/bonprelevement.class.php:2475|read|$XML_DEBITOR .= ''\t\t\t\t\t<Ustrd>'' . getDolGlobalString(''PRELEVEMENT_USTRD'', dolEscapeXML(dol_trunc(dol_string_nospecial(dol_string_unaccent($row_ref . ($row_comment ? '' - '' . $row_com", "admin/prelevement.php:217|read|print ''<input type=\"text\" name=\"PRELEVEMENT_USTRD\" value=\"''.getDolGlobalString(''PRELEVEMENT_USTRD'').''\" class=\"width100\"></td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PREVIEW_PICTO_ON_LEFT_OF_NAME', 'string', NULL, 'core', 'Controls whether the file preview picto/icon is placed to the left or right of the file name in document list rows.', 'In core/class/html.formfile.class.php:987 and 1012, when getDolGlobalInt(''PREVIEW_PICTO_ON_LEFT_OF_NAME'') is truthy, the preview picto ($imgpreview) is printed before the file link/name; otherwise (the `!getDolGlobalInt(...)` branch) it is printed after, i.e. to the right of the name.', 'Enabling it moves the small preview/thumbnail icon to appear before (left of) the file name instead of after (right of) it in document listing tables — a purely cosmetic layout change.', 'Boolean-like (int): set/non-empty places preview picto to the left of the file name; unset (default, 0) places it to the right.', 1, 0, NULL, 1, '1896d19e597ef6516e9425b1faa4aafecbd98daea5209b1cde83de508ed6254e', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formfile.class.php:987: if (getDolGlobalInt(''PREVIEW_PICTO_ON_LEFT_OF_NAME'')) { $tmpout .= $imgpreview; }", "core/class/html.formfile.class.php:1012: if (!getDolGlobalInt(''PREVIEW_PICTO_ON_LEFT_OF_NAME'')) { $tmpout .= $imgpreview; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRINTING_GCP_DEFAULT', 'string', NULL, 'core', 'Stores the ID of the default Google Cloud Print printer to use for print jobs.', 'Used in core/modules/printing/printgcp.modules.php in three locations: line 245 to mark a printer as selected in the list, line 370 to check if a default is configured, and line 371 to assign the printer ID for job submission.', 'Setting this to a valid GCP printer ID causes print jobs to be sent to that printer by default. Clearing it requires the user to select a printer each time.', 'Any non-empty string matching a GCP printer ID = default printer; empty/unset = no default printer configured.', 1, 0, NULL, 1, 'd3f47c10b60c0a56704e5e8911f7147ef9b929538cf3a054f34479aa74466231', 'v2', '2026-04-21T13:50:40+00:00', '["printgcp.modules.php:245|if (getDolGlobalString(''PRINTING_GCP_DEFAULT'') == $printer_det[''id'']) {", "printgcp.modules.php:370|if (getDolGlobalString(''PRINTING_GCP_DEFAULT'')) {", "printgcp.modules.php:371|$printer_id = getDolGlobalString(''PRINTING_GCP_DEFAULT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRINTIPP_HOST', 'string', NULL, 'core', 'CUPS/IPP server hostname used by the IPP printing driver (printipp).', 'Read in core/modules/printing/printipp.modules.php:100 into $this->host; declared as a required text field (''example'' => ''localhost'') in the driver''s $this->conf[] array shown on the printing driver setup page (printing/admin/printing.php).', 'Setting it configures which CUPS/IPP server the IPP printing driver connects to for sending print jobs; required for the driver to function.', 'String: hostname or IP of the CUPS/IPP server, example ''localhost''.', 0, 0, NULL, 1, 'f667b2da54e7d9a7b1e4a3c1aef6f4c7d3559179b64778d1c3a4ef0bc86d57d1', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/printing/printipp.modules.php:100: $this->host = getDolGlobalString(''PRINTIPP_HOST'');", "core/modules/printing/printipp.modules.php:105: $this->conf[] = array(''varname'' => ''PRINTIPP_HOST'', ''required'' => 1, ''example'' => ''localhost'', ''type'' => ''text'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRINTIPP_PASSWORD', 'string', NULL, 'core', 'IPP printer driver password used to authenticate to the IPP print server.', 'Read in core/modules/printing/printipp.modules.php:103 as `$this->password = getDolGlobalString(''PRINTIPP_PASSWORD'')`, paired with PRINTIPP_USER/HOST/PORT/SSL for the same IPP connection, and listed as a config field (''varname'' => ''PRINTIPP_PASSWORD'').', 'Changing it changes the password used for IPP server authentication; a wrong value breaks the print connection.', 'Free-form string: IPP server password.', 0, 0, NULL, 1, '554f841c09e9b391df9d3c6c43b29eded107053b3dc0253b97384f68120224a8', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/printing/printipp.modules.php:103: $this->password = getDolGlobalString(''PRINTIPP_PASSWORD'');", "core/modules/printing/printipp.modules.php:108: ...[''varname'' => ''PRINTIPP_PASSWORD'', ''required'' => 0, ''example'' => '''', ...''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRINTIPP_PORT', 'string', NULL, 'core', 'CUPS/IPP server port used by the IPP printing driver (printipp).', 'Read in core/modules/printing/printipp.modules.php:101 into $this->port; declared as a required text field (''example'' => ''631'') in the driver''s $this->conf[] array shown on the printing driver setup page (printing/admin/printing.php).', 'Setting it configures which port the IPP printing driver uses to connect to the CUPS/IPP server (default CUPS/IPP port is 631); required for the driver to function.', 'String/int: TCP port of the CUPS/IPP server, example ''631''.', 0, 0, NULL, 1, 'a16fa56e35312064a384d0046da1c3d0472def091c102d867a2c501672b89ef3', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/printing/printipp.modules.php:101: $this->port = getDolGlobalString(''PRINTIPP_PORT'');", "core/modules/printing/printipp.modules.php:106: $this->conf[] = array(''varname'' => ''PRINTIPP_PORT'', ''required'' => 1, ''example'' => ''631'', ''type'' => ''text'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRINTIPP_SSL', 'string', NULL, 'core', 'Toggles whether the IPP printing driver connects to the print server over SSL.', 'Read in core/modules/printing/printipp.modules.php:104 as `$this->ssl = getDolGlobalInt(''PRINTIPP_SSL'')`, one of the connection parameters (with HOST/PORT/USER/PASSWORD) for the printipp driver, and listed as a config field (''varname'' => ''PRINTIPP_SSL'').', 'Enabling it makes the driver use SSL for its IPP connection instead of plain connection.', 'Integer/boolean flag (0/1): whether to use SSL for the IPP connection.', 0, 0, NULL, 1, 'e78f5d52633bf8c164ccb97ad5df2de5b4093fb0bb2966148f007a0a14fc0644', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/printing/printipp.modules.php:104: $this->ssl = getDolGlobalInt(''PRINTIPP_SSL'');", "core/modules/printing/printipp.modules.php:109: ...[''varname'' => ''PRINTIPP_SSL'', ''required'' => 0, ''example'' => '''', ''type''..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRINTIPP_URI_DEFAULT', 'string', NULL, 'core', 'Specifies the default printer URI used by the PrintIPP module when no specific printer is selected.', 'Checked and read in core/modules/printing/printipp.modules.php at lines 153, 154, 155, and 224. When set, the module uses this URI as the default printer and logs it; it is also compared against available printer values in the selection UI at line 224.', 'Setting this constant causes the PrintIPP module to route print jobs to the specified printer URI by default. If unset, no default printer is pre-selected.', 'A URI string identifying the default IPP printer (e.g. ''ipp://printserver/printers/myprinter'').', 1, 0, NULL, 1, '5aff199b731c9c98eb85c63f0e36eefc89e808c4fc9f045b6c60764fe2ac285a', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/printing/printipp.modules.php:153|check|if (getDolGlobalString(''PRINTIPP_URI_DEFAULT'')) {", "core/modules/printing/printipp.modules.php:154|read|dol_syslog(\"Will use default printer conf->global->PRINTIPP_URI_DEFAULT = \".getDolGlobalString(''PRINTIPP_URI_DEFAULT''));", "core/modules/printing/printipp.modules.php:155|read|$ipp->setPrinterURI(getDolGlobalString(''PRINTIPP_URI_DEFAULT''));", "core/modules/printing/printipp.modules.php:224|check|if (getDolGlobalString(''PRINTIPP_URI_DEFAULT'') == $value) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRINTIPP_USER', 'string', NULL, 'core', 'IPP printer driver username used to authenticate to the IPP print server.', 'Read in the printipp printing driver at core/modules/printing/printipp.modules.php:102 as `$this->user = getDolGlobalString(''PRINTIPP_USER'')`, alongside sibling constants PRINTIPP_HOST/PORT/PASSWORD/SSL that configure the same IPP connection, and exposed as a setup field (''varname'' => ''PRINTIPP_USER'') in the module''s config array.', 'Changing it changes which user account is used when Dolibarr connects to the configured IPP print server; an incorrect value would break IPP printing authentication.', 'Free-form string: IPP server username.', 0, 0, NULL, 1, '8745a3de12002b03c309ecc8a54635ce159cd6b8f9a4bf3ff0183c606352dd75', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/printing/printipp.modules.php:102: $this->user = getDolGlobalString(''PRINTIPP_USER'');", "core/modules/printing/printipp.modules.php:107: ...[''varname'' => ''PRINTIPP_USER'', ''required'' => 0, ''example'' => '''', ''typ''..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCTBATCH_LOT_ADDON', 'string', NULL, 'product', 'Specifies the lot numbering add-on module for batch-tracked products, e.g. ''mod_lot_advanced''.', 'Configurable via the admin UI at product/admin/product_lot.php (written at lines 97 and 103, checked at line 254). Read in product/card.php at lines 1559, 1575, 2173, 2204, and 2717 to conditionally enable advanced lot mask features.', 'Setting this to ''mod_lot_advanced'' activates advanced lot numbering with product-specific masks; other values use the corresponding add-on module.', 'string module name, e.g. ''mod_lot_advanced''; default set to ''mod_lot_advanced'' on reset', 0, 0, 'product/admin/product_lot.php|product/admin/product_lot.php|product/admin/product_lot.php', 1, '6d5aac094db9ab3b8e9634125846c748e453e6ff5f703a54b459abf62298c379', 'v2', '2026-04-21T13:29:58+00:00', '["product/admin/product_lot.php:97|write|dolibarr_set_const($db, \"PRODUCTBATCH_LOT_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "product/admin/product_lot.php:103|write|dolibarr_set_const($db, \"PRODUCTBATCH_LOT_ADDON\", ''mod_lot_advanced'', ''chaine'', 0, '''', $conf->entity);", "product/card.php:1559|check|if ((getDolGlobalString(''PRODUCTBATCH_LOT_ADDON'') == ''mod_lot_advanced'')", "product/card.php:1575|check|if (getDolGlobalString(''PRODUCTBATCH_LOT_USE_PRODUCT_MASKS'') && getDolGlobalString(''PRODUCTBATCH_LOT_ADDON'') == ''mod_lot_advanced'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCTBATCH_LOT_ADDONS', 'string', NULL, 'product', 'Stores the currently selected numbering module (addon) used to generate lot/batch numbers for products, e.g. ''mod_lot_advanced''.', 'In product/admin/product_lot.php:101, within the ''setmaskslot'' admin action, when the advanced lot mask option is enabled and this constant isn''t already ''mod_lot_advanced'', the code calls dolibarr_set_const() to switch PRODUCTBATCH_LOT_ADDON to ''mod_lot_advanced''; the related admin page writes to PRODUCTBATCH_LOT_ADDON via dolibarr_set_const.', 'Its value selects which lot-numbering addon module generates batch/lot references; enabling the ''advanced mask'' option in the admin UI forces it to ''mod_lot_advanced''.', 'String: name of a lot-numbering addon module, e.g. ''mod_lot_advanced'' when advanced masks are enabled.', 0, 0, 'product/admin/product_lot.php', 1, 'a01c68b2b703fdec6526ce7a2978f5d08068b57172c3af1e9945fdfbf388ed5b', 'v2', '2026-07-24T07:05:23+00:00', '["product/admin/product_lot.php:101|check|if ($value == ''1'' && getDolGlobalString(''PRODUCTBATCH_LOT_ADDONS'') !== ''mod_lot_advanced'') {", "product/admin/product_lot.php:97  dolibarr_set_const($db, \"PRODUCTBATCH_LOT_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCTBATCH_LOT_USE_PRODUCT_MASKS', 'bool', NULL, 'product', 'Controls whether lot-number generation uses the mask defined on the individual product rather than the global lot-number addon mask.', 'Configurable via product/admin/product_lot.php (line 101 write). Checked in core/modules/product_batch/mod_lot_advanced.php and multiple locations in product/card.php to decide whether to apply the per-product mask when PRODUCTBATCH_LOT_ADDON is ''mod_lot_advanced''.', 'Enabling this constant causes lot numbers to follow the mask configured per product instead of the global addon mask. It only has effect when PRODUCTBATCH_LOT_ADDON equals ''mod_lot_advanced''.', 'Enabled or disabled via admin UI; stored as bool. No explicit value enumeration in COMMENTS.', 0, 0, 'product/admin/product_lot.php', 1, '8cb432fc90c4dc5ea12aaa3bbb07eec9856311afc6f59fe77e97a21143b3a8a0', 'v2', '2026-04-21T13:29:58+00:00', '["product/admin/product_lot.php:101|write|dolibarr_set_const($db, \"PRODUCTBATCH_LOT_USE_PRODUCT_MASKS\", $value, ''bool'', 0, '''', $conf->entity);", "product/card.php:1575|check|if (getDolGlobalString(''PRODUCTBATCH_LOT_USE_PRODUCT_MASKS'') && getDolGlobalString(''PRODUCTBATCH_LOT_ADDON'') == ''mod_lot_advanced'') {", "core/modules/product_batch/mod_lot_advanced.php:100|check|if (getDolGlobalString(''PRODUCTBATCH_LOT_USE_PRODUCT_MASKS'')) {", "core/modules/product_batch/mod_lot_advanced.php:155|check|if (getDolGlobalString(''PRODUCTBATCH_LOT_USE_PRODUCT_MASKS'') && !empty($object->fk_product)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCTBATCH_SHOW_WAREHOUSE_ON_SHIPMENT', 'bool', NULL, 'core', 'Shows the warehouse information on shipment PDFs for batch-tracked product lines.', 'Checked in core/lib/pdf.lib.php at lines 2254 and 2267. Applies only when the document is a shipping object and the origin stock reference is set.', 'Enabling this causes the warehouse to be displayed on shipment PDF lines for batch products; disabling it omits warehouse information.', 'truthy = show warehouse on shipment PDF; 0/empty = hide warehouse', 1, 0, NULL, 1, '83cd6edd2d43a01e26559dfc0dc6d44ff1e13b408f4cc38482b549e743791375', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:2254|check|if ($object->element == ''shipping'' && $detail->fk_origin_stock > 0 && getDolGlobalInt(''PRODUCTBATCH_SHOW_WAREHOUSE_ON_SHIPMENT'')) {", "core/lib/pdf.lib.php:2267|check|if (getDolGlobalInt(''PRODUCTBATCH_SHOW_WAREHOUSE_ON_SHIPMENT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCTBATCH_SN_ADDON', 'string', NULL, 'product', 'Specifies the serial number add-on module for batch-tracked products, e.g. ''mod_sn_advanced''.', 'Configurable via the admin UI at product/admin/product_lot.php (written at lines 99 and 108, checked at line 356). Read in product/card.php at lines 1560, 1583, 2176, 2212, and 2718 to enable advanced serial number mask features.', 'Setting this to ''mod_sn_advanced'' activates advanced serial numbering with product-specific masks; other values use the corresponding add-on module.', 'string module name, e.g. ''mod_sn_advanced''; default set to ''mod_sn_advanced'' on reset', 0, 0, 'product/admin/product_lot.php|product/admin/product_lot.php|product/admin/product_lot.php', 1, '1e585a77d3bf45748741f97ddb6a55e3b5b1f0373042726b337818c4d12a94e8', 'v2', '2026-04-21T13:29:58+00:00', '["product/admin/product_lot.php:99|write|dolibarr_set_const($db, \"PRODUCTBATCH_SN_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "product/admin/product_lot.php:108|write|dolibarr_set_const($db, \"PRODUCTBATCH_SN_ADDON\", ''mod_sn_advanced'', ''chaine'', 0, '''', $conf->entity);", "product/card.php:1583|check|if (getDolGlobalString(''PRODUCTBATCH_SN_USE_PRODUCT_MASKS'') && getDolGlobalString(''PRODUCTBATCH_SN_ADDON'') == ''mod_sn_advanced'') {", "product/card.php:1560|read||| (getDolGlobalString(''PRODUCTBATCH_SN_ADDON'') == ''mod_sn_advanced'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCTBATCH_SN_ADDONS', 'string', NULL, 'product', 'Stores the currently selected numbering module (addon) used to generate serial-number (SN) references for products, e.g. ''mod_sn_advanced''.', 'In product/admin/product_lot.php:106, within the ''setmaskssn'' admin action, when the advanced SN mask option is enabled and this constant isn''t already ''mod_sn_advanced'', the code calls dolibarr_set_const() to switch PRODUCTBATCH_SN_ADDON to ''mod_sn_advanced''.', 'Its value selects which serial-number addon module generates SN references; enabling the ''advanced mask'' option in the admin UI forces it to ''mod_sn_advanced''.', 'String: name of a serial-number addon module, e.g. ''mod_sn_advanced'' when advanced masks are enabled.', 0, 0, 'product/admin/product_lot.php', 1, '7e25cbb03ac36b700c767b3d83f446d43a73fd73ac910fc7eb41d52b621702bf', 'v2', '2026-07-24T07:05:23+00:00', '["product/admin/product_lot.php:106|check|if ($value == ''1'' && getDolGlobalString(''PRODUCTBATCH_SN_ADDONS'') !== ''mod_sn_advanced'') {", "product/admin/product_lot.php:103  dolibarr_set_const($db, \"PRODUCTBATCH_SN_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCTBATCH_SN_USE_PRODUCT_MASKS', 'bool', NULL, 'product', 'Controls whether serial-number generation uses the mask defined on the individual product rather than the global serial-number addon mask.', 'Configurable via product/admin/product_lot.php (line 106 write). Checked in core/modules/product_batch/mod_sn_advanced.php and multiple locations in product/card.php to decide whether to apply the per-product mask when PRODUCTBATCH_SN_ADDON is ''mod_sn_advanced''.', 'Enabling this constant causes serial numbers to follow the mask configured per product instead of the global addon mask. It only has effect when PRODUCTBATCH_SN_ADDON equals ''mod_sn_advanced''.', 'Enabled or disabled via admin UI; stored as bool. No explicit value enumeration in COMMENTS.', 0, 0, 'product/admin/product_lot.php', 1, '5253d57b9230ceeca3f0d144e662027271e262c96761f0b5cd8b7b91c4934f0e', 'v2', '2026-04-21T13:29:58+00:00', '["product/admin/product_lot.php:106|write|dolibarr_set_const($db, \"PRODUCTBATCH_SN_USE_PRODUCT_MASKS\", $value, ''bool'', 0, '''', $conf->entity);", "product/card.php:1583|check|if (getDolGlobalString(''PRODUCTBATCH_SN_USE_PRODUCT_MASKS'') && getDolGlobalString(''PRODUCTBATCH_SN_ADDON'') == ''mod_sn_advanced'') {", "core/modules/product_batch/mod_sn_advanced.php:100|check|if (getDolGlobalString(''PRODUCTBATCH_SN_USE_PRODUCT_MASKS'')) {", "core/modules/product_batch/mod_sn_advanced.php:155|check|if (getDolGlobalString(''PRODUCTBATCH_SN_USE_PRODUCT_MASKS'') && !empty($object->fk_product)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCTFOURNISSEURPRICE_ADDON_PDF', 'string', NULL, 'product', 'Sets the default PDF document model (template) used to generate supplier price documents when none is set on the object.', 'In product/class/productfournisseurprice.class.php:994-995, if $modele is empty and $this->model_pdf is not set, the code falls back to getDolGlobalString(''PRODUCTFOURNISSEURPRICE_ADDON_PDF'') as the model name; otherwise the hardcoded default ''standard_productfournisseurprice'' is used.', 'Setting it changes which PDF template is used by default to generate ProductFournisseurPrice documents, overriding the built-in ''standard_productfournisseurprice'' default.', 'String; should be the name of an existing productfournisseurprice PDF model/template.', 1, 0, NULL, 1, 'fafb792af4d63c012754e7fe687636125537297abd5aa42400cfa00d8b7a50ee', 'v2', '2026-07-24T07:05:23+00:00', '["product/class/productfournisseurprice.class.php:994: } elseif (getDolGlobalString(''PRODUCTFOURNISSEURPRICE_ADDON_PDF'')) {", "product/class/productfournisseurprice.class.php:995: $modele = getDolGlobalString(''PRODUCTFOURNISSEURPRICE_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ADDON_PDF', 'string', NULL, 'product', 'Selects the default PDF generation module for product data sheets.', 'Configured via product/admin/product.php (written and deleted with dolibarr_set_const/dolibarr_del_const at lines 239 and 232). Read in product/class/product.class.php:6039 to determine the PDF model, defaulting to ''strato''.', 'Changing this value switches the PDF template used for product data sheet generation.', 'String name of a PDF model module; defaults to ''strato''.', 0, 0, 'product/admin/product.php|product/admin/product.php|product/admin/product.php|product/admin/product.php|product/admin/product.php', 1, '3d139e7784d3cc1bdd122faab42a2765b34d87287c9b09b3f1f5e1cb1238f384', 'v2', '2026-04-21T13:29:58+00:00', '["product/admin/product.php:239|write|if (dolibarr_set_const($db, \"PRODUCT_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "product/admin/product.php:232|write|dolibarr_del_const($db, ''PRODUCT_ADDON_PDF'', $conf->entity);", "product/class/product.class.php:6039|read|$modele = getDolGlobalString(''PRODUCT_ADDON_PDF'', ''strato'');", "product/admin/product.php:503|check|if (getDolGlobalString(''PRODUCT_ADDON_PDF'') == $name) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ADDON_PDF_ODT_PATH', 'string', 'DOL_DATA_ROOT/doctemplates/products', 'core', 'Specifies one or more directory paths where ODT templates for product documents are searched.', 'Read in core/modules/product/doc/doc_generic_product_odt.modules.php:125 where it is split into a list of directories, displayed at line 152, and checked at line 160. The default value is ''DOL_DATA_ROOT/doctemplates/products''.', 'If set, additional directories beyond the default are scanned for product ODT templates.', 'String: comma- or newline-separated directory paths; default ''DOL_DATA_ROOT/doctemplates/products''.', 1, 1, NULL, 1, '545c00cb8643d73c5cb203eee7a1e2093c81e68c45f39e7f88e1b548ed5e7e07', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/product/doc/doc_generic_product_odt.modules.php:125|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''PRODUCT_ADDON_PDF_ODT_PATH''))));", "core/modules/product/doc/doc_generic_product_odt.modules.php:152|read|$texte .= getDolGlobalString(''PRODUCT_ADDON_PDF_ODT_PATH'');", "core/modules/product/doc/doc_generic_product_odt.modules.php:160|check|if (getDolGlobalString(''PRODUCT_ADDON_PDF_ODT_PATH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ADD_FORM_ADD_TO', 'string', NULL, 'product', 'Enables ''Add to object'' areas on the product card, allowing the product to be added directly to other objects from the product view.', 'COMMENTS in product/card.php at lines 1109 and 3164 document its purpose. Checked at line 3167 in product/card.php; the ''Add to'' areas are rendered only when this constant is set, the product has an id, the action is view/empty, and the product has a sell status.', 'Setting this constant shows ''Add to'' form sections on the product card for active products. Clearing it removes those sections.', 'From COMMENTS: ''// Add product into object (when PRODUCT_ADD_FORM_ADD_TO is set)'' and ''* All the "Add to" areas if PRODUCT_ADD_FORM_ADD_TO is set''. Truthy = sections shown; absent/falsy = sections hidden.', 1, 0, NULL, 1, '38d7a2fc5b2a7765ef7ac8918491e9dcef479dbaf0309cc547077906350b2e68', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:1109  // Add product into object (when PRODUCT_ADD_FORM_ADD_TO is set)", "product/card.php:3164  * All the \"Add to\" areas if PRODUCT_ADD_FORM_ADD_TO is set", "product/card.php:3167|check|if (getDolGlobalString(''PRODUCT_ADD_FORM_ADD_TO'') && $object->id && ($action == '''' || $action == ''view'') && $object->status) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ADD_NET_MEASURE', 'string', NULL, 'product', 'Enables a net-measure field on the product card, corresponding to the ''net_measure'' measuring style.', 'Checked at product/card.php lines 1762, 2404, and 2972; the net-measure block is rendered only when this constant is set. The COMMENT in core/lib/product.lib.php:974 documents '''' (empty string) as the style identifier for the net_measure option tied to this constant.', 'Setting this constant adds a net-measure field to the product card. Clearing it removes that field.', ''''' = ''net_measure'' for option PRODUCT_ADD_NET_MEASURE (from COMMENT: core/lib/product.lib.php:974 @param string $measuring_style Style of unit: ''weight'', ''volume'', ..., '''' = ''net_measure'' for option PRODUCT_ADD_NET_MEASURE)', 1, 0, NULL, 1, '96a5ca903cae5a903c475ddd2a65218238dc97a3e922541d815f34d0b6969980', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/product.lib.php:974  *\t@param  string\t\t$measuring_style    Style of unit: ''weight'', ''volume'', ..., '''' = ''net_measure'' for option PRODUCT_ADD_NET_MEASURE", "product/card.php:1762|check|if (getDolGlobalString(''PRODUCT_ADD_NET_MEASURE'')) {", "product/card.php:2404|check|if (getDolGlobalString(''PRODUCT_ADD_NET_MEASURE'')) {", "product/card.php:2972|check|if (getDolGlobalString(''PRODUCT_ADD_NET_MEASURE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ADD_TYPE_IN_DOCUMENTS', 'string', NULL, 'core', 'Adds the product type information into generated documents (PDF and doc outputs).', 'When set, the product type is included in document lines. The comment in both core/lib/pdf.lib.php:2113 and core/lib/doc.lib.php:118 reads: ''In standard mode, we do not show this'', indicating this overrides the default hidden behaviour.', 'Enabling this causes the product type to appear in generated documents; by default (not set) it is not shown.', 'truthy = add product type in documents; empty/not set = do not show (standard mode)', 1, 0, NULL, 1, 'b0d20a13fe963037b5d4b39f75e7637f51b134be7ad86530823e3c9adbe47b94', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/pdf.lib.php:2113|check|if (getDolGlobalString(''PRODUCT_ADD_TYPE_IN_DOCUMENTS'')) {   // In standard mode, we do not show this", "core/lib/doc.lib.php:118|check|if (getDolGlobalString(''PRODUCT_ADD_TYPE_IN_DOCUMENTS'')) {   // In standard mode, we do not show this"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_AJAX_SEARCH_ON_DESCRIPTION', 'string', NULL, 'core', 'Extends the product ajax/autocomplete search to also match against the product description field (and its translation), not just ref/label.', 'core/class/html.form.class.php:3820-3824: `if (getDolGlobalString(''PRODUCT_AJAX_SEARCH_ON_DESCRIPTION'')) { $sql .= " OR p.description LIKE ''...'' "; if (getDolGlobalInt(''MAIN_MULTILANGS'')) { $sql .= " OR pl.description LIKE ''...'' "; } }` appended to the product search WHERE clause that already matches ref/label (and multilang label).', 'Setting it to a truthy value adds `p.description LIKE ''%term%''` (and translated description if MAIN_MULTILANGS is on) to the product search OR-conditions, broadening matches but potentially slowing the query on large description text and increasing false-positive matches.', 'Truthy = also search in product description (and pl.description if multilang); 0/unset = search limited to ref/label/barcode/etc (default).', 1, 0, NULL, 1, 'a28627b85ba6c569629f3023d0a9681c9bd6ba9f860f3f919cc31d52c6d5fffc', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:3820: if (getDolGlobalString(''PRODUCT_AJAX_SEARCH_ON_DESCRIPTION'')) {", "core/class/html.form.class.php:3821: $sql .= \" OR p.description LIKE ''\" . $this->db->escape($prefix . $crit) . \"%''\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'core', 'Allows uploaded PDF files linked to a product page to be marked shareable (externally downloadable) in the ECM file index.', 'Used in core/lib/files.lib.php:2197 during file upload indexing (addFileIntoDatabaseIndex); when the uploaded file is a PDF, the current request URI contains ''product'', and this constant is set, $sharefile is forced to 1 for that ECM file entry.', 'Enabling it lets product-related PDF uploads automatically get a public/share flag in the ECM file index, exposing them for external download; without it, sharefile stays 0 for these uploads.', 'Boolean-like: truthy sets sharefile=1 for PDF uploads made from a product-context request.', 1, 0, NULL, 1, '2ba7c7bf4b1a7bb82b7603cd4ac65fb4e5f4eca8a3dc1428584dcb0bbeefab89', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/files.lib.php:2197|check|if ($TFile[''type''][$i] == ''application/pdf'' && strpos($_SERVER[\"REQUEST_URI\"], ''product'') !== false && getDolGlobalString(''PRODUCT_ALLOW_EXTERNAL_DOWNLOAD'')) {", "$sharefile = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_BATCH_ADDON_PDF', 'string', NULL, 'product', 'Name of the PDF document template model used for product lot/batch documents.', 'Written by product/admin/product_lot.php:158-161 via dolibarr_set_const and $conf->global assignment. Read at product/stock/class/productlot.class.php:1324-1325 to select the PDF model. Checked for match against available model names at product/admin/product_lot.php:496.', 'Changing this value switches the PDF template used when generating documents for product lots; an invalid value will cause document generation to fail.', 'String name of a PDF model class available in the product lot module.', 0, 0, 'product/admin/product_lot.php|product/admin/product_lot.php|product/admin/product_lot.php', 1, 'c8a55276f12394d14eb3d7662b744b9e35db50271f9d881afa2efd0a3f9a2dda', 'v2', '2026-04-21T13:29:58+00:00', '["product/admin/product_lot.php:158|write|if (dolibarr_set_const($db, \"PRODUCT_BATCH_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "product/stock/class/productlot.class.php:1324|read|} elseif (getDolGlobalString(''PRODUCT_BATCH_ADDON_PDF'')) {", "product/stock/class/productlot.class.php:1325|read|$modele = getDolGlobalString(''PRODUCT_BATCH_ADDON_PDF'');", "product/admin/product_lot.php:496|check|if (getDolGlobalString(''PRODUCT_BATCH_ADDON_PDF'') == $name) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_BEST_SUPPLIER_PRICE_PRESELECTED', 'string', NULL, 'core', 'Changes the ordering/preselection of supplier prices in the supplier-price selection dropdown to preselect the cheapest (best) price instead of the first alphabetical supplier.', 'core/class/html.form.class.php:4956-4960: `if (!getDolGlobalString(''PRODUCT_BEST_SUPPLIER_PRICE_PRESELECTED'')) { $sql .= " ORDER BY s.nom, pfp.ref_fourn DESC"; } else { $sql .= " ORDER BY pfp.unitprice - pfp.unitprice * pfp.remise_percent / 100 ASC"; }`, and line 4982 preselects the first row (`$i == 0`) as ''selected'' when the constant is truthy: `if ($num == 1 || ... || ($i == 0 && getDolGlobalString(''PRODUCT_BEST_SUPPLIER_PRICE_PRESELECTED''))) { $opt .= '' selected''; }`.', 'Setting it to a truthy value reorders the supplier-price dropdown by net unit price ascending (cheapest first, after discount) and preselects that cheapest option; unset keeps the default alphabetical-by-supplier-name ordering with no auto-preselection of the best price.', 'Truthy = sort by net unit price ascending (unitprice - unitprice*remise_percent/100) and preselect the first/cheapest row; 0/unset = sort by supplier name then ref_fourn DESC (default), no best-price preselection.', 0, 0, NULL, 1, 'b6c90d9c46f64b4a1a46a967d03d9ec70c4199282c3420235707c6385801e452', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:4956: if (!getDolGlobalString(''PRODUCT_BEST_SUPPLIER_PRICE_PRESELECTED'')) { $sql .= \" ORDER BY s.nom, pfp.ref_fourn DESC\"; } else { $sql .= \" ORDER BY pfp.unitprice - pfp.unitprice * pfp.remise_percent / 100 ASC\"; }", "core/class/html.form.class.php:4982: if ($num == 1 || ... || ($i == 0 && getDolGlobalString(''PRODUCT_BEST_SUPPLIER_PRICE_PRESELECTED''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_CANVAS_ABILITY', 'string', NULL, 'product', 'Enables the product ''canvas'' feature in the product module admin setup page, adding a canvas-related settings section.', 'In product/admin/product.php:788, when truthy, the admin page renders an extra table section (looking under DOL_DOCUMENT_ROOT.''/product/canvas/'') with a ''ProductSpecial'' title row for canvas configuration.', 'Setting it reveals an additional canvas configuration section on the product admin setup page; without it that section is not shown.', 'Boolean-like: truthy shows the product canvas admin section.', 0, 0, 'product/admin/product.php', 1, 'bd7115bc09ae1bad3cced922ee0f6af974c26c82b88ef5b39f9ac40bf3c850b1', 'v2', '2026-07-24T07:05:23+00:00', '["product/admin/product.php:788|check|if (getDolGlobalString(''PRODUCT_CANVAS_ABILITY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_CAN_EDIT_WAP', 'string', NULL, 'product', 'Allows manual editing of a product''s PMP (average unit price / ''weighted average price'') field on the supplier price page.', 'Checked in product/price_suppliers.php:443: $usercaneditpmp is set to $usercancreate only if getDolGlobalString(''PRODUCT_CAN_EDIT_WAP'') is true; otherwise the PMP field stays non-editable regardless of user permissions.', 'Enabling it lets users who can otherwise create/edit the product manually edit the computed PMP value; when disabled (default) the PMP field is always read-only on this page even for users with create rights.', 'Boolean-like (getDolGlobalString): non-empty allows PMP edition for users with create rights; empty/unset (default) keeps PMP read-only.', 1, 0, NULL, 1, '23880c1bcedee48fa29149f2e28516cae7e93619f4ca8e6744f796fa5d98e260', 'v2', '2026-07-24T07:05:23+00:00', '["product/price_suppliers.php:443: if (getDolGlobalString(''PRODUCT_CAN_EDIT_WAP'')) {", "product/price_suppliers.php: $usercaneditpmp = $usercancreate;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_CHARGES', 'string', NULL, 'product', 'Enables display and use of supplier product ''charges'' (additional costs) in product/supplier price screens and TakePOS.', 'Checked with getDolGlobalString(''PRODUCT_CHARGES'') in product/price_suppliers.php:795/1244/976, takepos/invoice.php:988, and fourn/class/fournisseur.product.class.php:151/765/877/1050 which set/read the ''fourn_charges'' property when it is set.', 'When enabled, the ''Charges'' column is shown/enabled on the supplier price list and TakePOS uses fourn_charges (per takepos/invoice.php:988 guard ''$pf->fourn_charges > 0'').', NULL, 0, 0, NULL, 1, '6e2fbdddfa3a747bd0f5b835913694c65b3a1bb4606b301f1e36e66450021ac4', 'v2', '2026-07-24T06:41:12+00:00', '["''pfp.charges'' => array(''label'' => $langs->trans(\"Charges\"), ''enabled'' => getDolGlobalString(''PRODUCT_CHARGES''), ''checked'' => ''0'', ''position'' => 11),", "public $fourn_charges;\t// when getDolGlobalString(''PRODUCT_CHARGES'') is set"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_CODEPRODUCT_ADDON', 'string', NULL, 'product', 'Selects the module class used to generate or validate product reference codes.', 'Configured via product/admin/product.php (written with dolibarr_set_const). Read in product/class/product.class.php:1075 and product/card.php:148 and :1461 to load the product code module, defaulting to ''mod_codeproduct_leopard'' when unset.', 'Changing this value switches the product code generation algorithm. New product codes will be generated by the selected module.', 'String class name of the product code module; defaults to ''mod_codeproduct_leopard''.', 0, 0, 'product/admin/product.php|product/admin/product.php', 1, '9edfa72060ad61c42f9be02e4a471d84b4ef69f29e499f37a757aafd9baa2c37', 'v2', '2026-04-21T13:29:58+00:00', '["product/admin/product.php:102|write|if (dolibarr_set_const($db, \"PRODUCT_CODEPRODUCT_ADDON\", $value, ''chaine'', 0, '''', $conf->entity) > 0) {", "product/class/product.class.php:1075|read|$module = getDolGlobalString(''PRODUCT_CODEPRODUCT_ADDON'', ''mod_codeproduct_leopard'');", "product/card.php:148|read|$module = getDolGlobalString(''PRODUCT_CODEPRODUCT_ADDON'', ''mod_codeproduct_leopard'');", "product/card.php:1461|read|$module = getDolGlobalString(''PRODUCT_CODEPRODUCT_ADDON'', ''mod_codeproduct_leopard'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DENY_CHANGE_PRODUCT_TYPE', 'string', NULL, 'product', 'Prevents changing a product''s type (product vs service) once created, across multiple product edit screens.', 'Checked with !getDolGlobalString(''PRODUCT_DENY_CHANGE_PRODUCT_TYPE'') as a guard in product/card.php:2626, product/price.php:1056/1135/1150/1377, product/price_suppliers.php:425, product/composition/card.php:267 and variants/combinations.php:442.', 'When enabled, the product ''Type'' field becomes read-only (displayed as plain text via $langs->trans) instead of an editable field on these pages.', NULL, 0, 0, NULL, 1, '1e7372118e5c8b6449a914a6089d79b1c4b78f02aa3b8eb14bd5d6c191d0ac81', 'v2', '2026-07-24T06:41:12+00:00', '["print (!getDolGlobalString(''PRODUCT_DENY_CHANGE_PRODUCT_TYPE'')) ? $form->editfieldkey(\"Type\", ''fk_product_type'', (string) $object->type, $object, 0, $typeformat) : $langs->trans(''T"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DESC_IN_LIST', 'string', NULL, 'contrat', 'Shows the product/service description text under its label in the contract services list page.', 'In contrat/services_list.php:887, when the row has a linked product ($obj->pid > 0) and this constant is truthy, the description is printed in a small div below the product name/label.', 'Setting it adds an extra description line under each product/service row in the contract services list, which can lengthen each row''s display.', 'Boolean-like: truthy displays the product description under the label in the list.', 0, 0, NULL, 1, 'c27af4e3775cf5062a635c7754f8a705e77c1462cb127d6a7ca0e3157aea441c', 'v2', '2026-07-24T07:05:23+00:00', '["contrat/services_list.php:887|check|if (!empty($obj->description) && getDolGlobalString(''PRODUCT_DESC_IN_LIST'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_ACCOUNTING', 'bool', NULL, 'product', 'Disables accounting-code fields on the product card and removes accounting columns from the product list.', 'Checked at product/card.php lines 1889, 2483, and 2730 with negated conditions. Also used in product/list.php lines 301-305 to control the enabled state of accountancy sell, sell-intra, sell-export, buy, and buy-intra code columns.', 'Setting this constant hides all accountancy code fields from the product card and disables those columns in the product list. Clearing it restores them.', 'Boolean flag; absent/falsy = accounting fields shown; truthy = accounting fields hidden.', 1, 0, NULL, 1, 'aa28bfb7d4e591d166f5fbf3cea281760a8028aa0f86c66e4286c0ffcaf4fa37', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:1889|check|if (!getDolGlobalString(''PRODUCT_DISABLE_ACCOUNTING'')) {", "product/list.php:301|read|$alias_product_perentity . ''.accountancy_code_sell'' => array(''label'' => \"ProductAccountancySellCode\", ''checked'' => ''0'', ''enabled'' => (string) (int) !getDolGlobalString(''PRODUCT_DIS", "product/list.php:304|read|$alias_product_perentity . ''.accountancy_code_buy'' => array(''label'' => \"ProductAccountancyBuyCode\", ''checked'' => ''0'', ''enabled'' => (string) (int) !getDolGlobalString(''PRODUCT_DISAB", "product/card.php:2730|check|if (!getDolGlobalString(''PRODUCT_DISABLE_ACCOUNTING'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_CUSTOMS_INFO', 'bool', NULL, 'product', 'Disables the customs information section on the product card for physical (non-service) products.', 'Checked at product/card.php lines 1780, 2421, and 2994 with negated conditions combined with a check that the product is not a service; the customs info block is rendered only when this constant is not set.', 'Setting this constant hides customs-related fields from physical product cards. It has no effect on service products, which already exclude customs info.', 'Boolean flag; absent/falsy = customs info shown for non-services; truthy = customs info hidden.', 1, 0, NULL, 1, '2475efc1f03a5352739747a96c4c3445c7b1164886d19ecfd0b76db6e2e7d588', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:1780|check|if (!getDolGlobalString(''PRODUCT_DISABLE_CUSTOMS_INFO'') && empty($type)) {", "product/card.php:2421|check|if (!$object->isService() && !getDolGlobalString(''PRODUCT_DISABLE_CUSTOMS_INFO'')) {", "product/card.php:2994|check|if (!$object->isService() && !getDolGlobalString(''PRODUCT_DISABLE_CUSTOMS_INFO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_EATBY', 'bool', NULL, 'product', 'Disables the ''eat-by (best before) date'' field for product lot/serial tracking.', 'Checked in 53 occurrences across product/stock/tpl/stockcorrection.tpl.php, product/stock/productlot_card.php, product/stock/class/productlot.class.php:1167, reception/dispatch.php, and many others. Commented-out references in takepos/invoice.php:833 confirm field-hiding intent.', 'When enabled, the eat-by/best-before date field is hidden from product lot forms, stock correction templates, and reception dispatch pages.', '0 or unset = eat-by date field shown; non-empty = eat-by date field hidden', 1, 0, NULL, 1, 'bf9a13633eb0f8f5638ae8d84f442919fc1690a414a96eaf6744e3c0c3f9c463', 'v2', '2026-04-21T11:16:15+00:00', '["product/stock/tpl/stockcorrection.tpl.php:235|check|if (!getDolGlobalString(''PRODUCT_DISABLE_EATBY'')) {", "product/stock/productlot_card.php:406|check|if (!getDolGlobalString(''PRODUCT_DISABLE_EATBY'')) {", "product/stock/class/productlot.class.php:1167|check|if (isDolTms($this->eatby) && !getDolGlobalString(''PRODUCT_DISABLE_EATBY'')) {", "takepos/invoice.php:833  //if (!getDolGlobalString(''PRODUCT_DISABLE_EATBY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_NATURE', 'bool', NULL, 'product', 'Hides the product nature field (product type/composition selector) from product cards and composition pages.', 'Checked in product/card.php:1719,2355,2909 and product/composition/card.php:304. When set, the nature field is not rendered on the product form.', 'Enabling this constant hides the nature field entirely; disabling it restores the field on product edit and view pages.', 'Any non-empty value = disable (hide) nature field; empty/unset = show nature field', 1, 0, NULL, 1, '71a896fc328998a398ec3ac20ba1928044c82efffaf8c32035b13b9426f3ed07', 'v2', '2026-04-21T13:29:58+00:00', '["if (!getDolGlobalString(''PRODUCT_DISABLE_NATURE'')) {", "product/composition/card.php:304|check|if (!getDolGlobalString(''PRODUCT_DISABLE_NATURE'')) {", "product/card.php:1719|check|if (!getDolGlobalString(''PRODUCT_DISABLE_NATURE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_PRICES', 'bool', NULL, 'product', 'Hides the price/VAT block on the product creation form.', 'Checked in product/card.php:1843, guarding the block that prints the VAT rate and price table (including the multiprice table when PRODUIT_MULTIPRICES or PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES is enabled).', 'When set, no price fields are shown at product creation time, so prices must be set elsewhere (e.g. Prices tab) or are simply not managed.', 'Boolean: truthy hides the price/VAT block; falsy (default) shows it.', 0, 0, NULL, 1, 'ad5b8dc6b9d2b565c06df4276c064294594f7a0d44fb4d125083a769aba5f55c', 'v2', '2026-07-24T07:05:23+00:00', '["product/card.php:1843|if (!getDolGlobalString(''PRODUCT_DISABLE_PRICES'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_PROPAGATE_CUSTOMER_PRICES_ON_CHILD_COMPANIES', 'bool', NULL, 'product', 'Disables automatic propagation of a parent company''s customer product prices down to its subsidiary/child companies.', 'In product/class/productcustomerprice.class.php:1003, setPriceOnAffiliateThirdparty() returns 0 immediately (action disabled) if getDolGlobalString(''PRODUCT_DISABLE_PROPAGATE_CUSTOMER_PRICES_ON_CHILD_COMPANIES'') is set, per the method docblock ''Force update price on child companies so child company has same prices than parent''.', 'Enabling it disables the feature that copies a thirdparty''s customer prices onto its subsidiary companies; the update is skipped entirely (returns 0 = action disabled).', 'Boolean-like truthy check via getDolGlobalString().', 1, 0, NULL, 1, 'dc38fc0b169d7bb374c4a48122b321118f6853b0e96ab3b50f3d3efa284ebf10', 'v2', '2026-07-24T07:05:23+00:00', '["product/class/productcustomerprice.class.php:1003: if (getDolGlobalString(''PRODUCT_DISABLE_PROPAGATE_CUSTOMER_PRICES_ON_CHILD_COMPANIES'')) { return 0; }", "product/class/productcustomerprice.class.php: * Force update price on child companies so child company has same prices than parent."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_PUBLIC_URL', 'bool', NULL, 'product', 'Disables the public URL section on the product card so it is not shown to users.', 'Checked at three locations in product/card.php (lines 1648, 2282, 2837) using a negated condition; the public URL block is rendered only when this constant is not set.', 'Setting this constant hides the public URL field on the product card. Clearing it restores the display of the public URL.', 'Boolean flag; absent/falsy = public URL shown; truthy = public URL hidden.', 1, 0, NULL, 1, 'af4f57759b89109aa722fd2730d62cc6962ad7d594b55fc269c7b23ca15058a7', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:1648|check|if (!getDolGlobalString(''PRODUCT_DISABLE_PUBLIC_URL'')) {", "product/card.php:2282|check|if (!getDolGlobalString(''PRODUCT_DISABLE_PUBLIC_URL'')) {", "product/card.php:2837|check|if (!getDolGlobalString(''PRODUCT_DISABLE_PUBLIC_URL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_SELLBY', 'bool', NULL, 'product', 'Disables the ''sell-by date'' field for product lot/serial tracking.', 'Checked in 53 occurrences across reception/card.php, mrp/mo_movements.php, product/reassortlot.php, product/stock/tpl/stockcorrection.tpl.php, product/stock/productlot_card.php, and many others. The read at product/stock/tpl/stockcorrection.tpl.php:93 assigns it to $disableSellBy. Commented-out references in product/stock/stats and product/stock/index.php confirm field-hiding intent.', 'When enabled, the sell-by date field is hidden from product lot forms, stock correction templates, and reception cards throughout the application.', '0 or unset = sell-by date field shown; non-empty = sell-by date field hidden', 1, 0, NULL, 1, 'b7f0ff405fe57c3c9155453c73d322de3e0839af85d2dbb2807cc85f521e4b33', 'v2', '2026-04-21T11:16:15+00:00', '["reception/card.php:2758|check|if (!getDolGlobalString(''PRODUCT_DISABLE_SELLBY'')) {", "product/stock/tpl/stockcorrection.tpl.php:93|read|$disableSellBy = getDolGlobalInt(''PRODUCT_DISABLE_SELLBY'');", "product/stock/productlot_card.php:396|check|if (!getDolGlobalString(''PRODUCT_DISABLE_SELLBY'')) {", "mrp/mo_movements.php:152|check|if (getDolGlobalString(''PRODUCT_DISABLE_SELLBY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_SIZE', 'bool', NULL, 'product', 'Disables size-related fields (length, width, height) on the product card and list columns.', 'Checked at product/card.php lines 1738, 2380, and 2939, and used in product/list.php (lines 276-280) to control the enabled state of length, length_units, width, width_units, and height columns.', 'Setting this constant hides size fields (length, width, height) from the product card and removes those columns from the product list. Clearing it restores them.', 'Boolean flag; absent/falsy = size fields shown; truthy = size fields hidden.', 1, 0, NULL, 1, '8ac6bf3d0654ccf071709991aa2ab5067ac8a6e6486a77ba573fee302093d353', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:1738|check|if (!getDolGlobalString(''PRODUCT_DISABLE_SIZE'')) {", "product/list.php:276|read|''p.length'' => array(''label'' => ''Length'', ''checked'' => ''0'', ''enabled'' => (string) (int) (isModEnabled(\"product\") && !getDolGlobalString(''PRODUCT_DISABLE_SIZE'') && $type != ''1'')", "product/list.php:278|read|''p.width'' => array(''label'' => ''Width'', ''checked'' => ''0'', ''enabled'' => (string) (int) (isModEnabled(\"product\") && !getDolGlobalString(''PRODUCT_DISABLE_SIZE'') && $type != ''1'')", "product/list.php:280|read|''p.height'' => array(''label'' => ''Height'', ''checked'' => ''0'', ''enabled'' => (string) (int) (isModEnabled(\"product\") && !getDolGlobalString(''PRODUCT_DISABLE_SIZE'') && $type != ''1'')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_STATE', 'bool', NULL, 'product', 'Hides the State/Province (origin) field on the product card.', 'Checked in product/card.php:1795 and 2432, both guarding the ''State'' block (state_id select, with region variant if MAIN_SHOW_REGION_IN_STATE_SELECT is set) on the product edit/view form.', 'When set, the state/province origin selector is not displayed on the product form.', 'Boolean: truthy hides the State field; falsy (default) shows it.', 0, 0, NULL, 1, 'ddafc1a9d1fbdc8924ba2f40bbe99d0a15161d9ce5c63faff94f6cde8b9c4cf3', 'v2', '2026-07-24T07:05:23+00:00', '["product/card.php:1795|if (!getDolGlobalString(''PRODUCT_DISABLE_STATE'')) {", "product/card.php:2432|if (!getDolGlobalString(''PRODUCT_DISABLE_STATE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_STOCK_LEVELS', 'bool', NULL, 'product', 'Hides the stock minimum alert level and desired stock level fields on the product card.', 'Checked twice in product/card.php:1669 and 1682 around the ''seuil_stock_alerte'' and ''desiredstock'' input fields on the product create/edit form.', 'When set, the stock alert threshold and desired stock inputs are not shown (and forced to hidden value 0 for services), removing the ability to configure per-product stock thresholds from the UI.', 'Boolean: truthy hides the stock level fields; falsy (default) shows them.', 0, 0, NULL, 1, 'ba6cbac12dd9a3e8c2c3c0fdd973ec86f4fb2a33a2f88430a25fd605f3cf737f', 'v2', '2026-07-24T07:05:23+00:00', '["product/card.php:1669|if (!getDolGlobalString(''PRODUCT_DISABLE_STOCK_LEVELS'')) {", "product/card.php:1682|if (!getDolGlobalString(''PRODUCT_DISABLE_STOCK_LEVELS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_SURFACE', 'bool', NULL, 'product', 'Hides the surface (area) field and column for products.', 'Checked with !getDolGlobalString(''PRODUCT_DISABLE_SURFACE'') in product/card.php:1748/2386/3007/3010/3011/3013 and product/list.php:289.', 'When enabled, the Surface field/label is hidden on the product card and the ''p.surface'' column is disabled in the product list.', NULL, 0, 0, NULL, 1, '8ac9e382de2beddffc0a921f16c6707c4d45836113f486f8bdecb9347b2f6dad', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''PRODUCT_DISABLE_SURFACE'')) {", "print(getDolGlobalString(''PRODUCT_DISABLE_SURFACE'') ? '''' : $langs->trans(\"Surface\"));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_VOLUME', 'bool', NULL, 'product', 'Disables the volume field on the product card and list view.', 'Checked at product/card.php lines 1754, 2396, 2956, 2960, 2961, 2965, and 2966, and in product/list.php line 284 to control the enabled state of the volume column.', 'Setting this constant hides the volume field from the product card and removes the volume column from the product list. It also suppresses the separator between surface and volume when both are disabled.', 'Boolean flag; absent/falsy = volume field shown; truthy = volume field hidden.', 1, 0, NULL, 1, '6e70f03e37417d0d63b1705009f47d04b462970b39d1a5d7ce09002243b868d8', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:1754|check|if (!getDolGlobalString(''PRODUCT_DISABLE_VOLUME'')) {", "product/card.php:2961|read|print (getDolGlobalString(''PRODUCT_DISABLE_VOLUME'') ? '''' : $langs->trans(\"Volume\")).''</td><td>'';", "product/card.php:2956|check|if (!getDolGlobalString(''PRODUCT_DISABLE_SURFACE'') || !getDolGlobalString(''PRODUCT_DISABLE_VOLUME'')) {", "product/list.php:284|read|''p.volume'' => array(''label'' => ''Volume'', ''checked'' => ''0'', ''enabled'' => (string) (int) (isModEnabled(\"product\") && !getDolGlobalString(''PRODUCT_DISABLE_VOLUME'') && $type != ''1'')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISABLE_WEIGHT', 'bool', NULL, 'product', 'Disables the weight field on the product card and list views.', 'Checked at product/card.php lines 1728, 2372, and 2929 with negated conditions; the weight input/display block is rendered only when this constant is not set.', 'Setting this constant hides the weight field on the product card. Removing it restores the weight field.', 'Boolean flag; absent/falsy = weight field shown; truthy = weight field hidden.', 1, 0, NULL, 1, '97ddf6db5f62b889250b19a1cbc2b2fbda4342ffa93ca5a090837d6c87a9729c', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:1728|check|if (!getDolGlobalString(''PRODUCT_DISABLE_WEIGHT'')) {", "product/card.php:2372|check|if (!getDolGlobalString(''PRODUCT_DISABLE_WEIGHT'')) {", "product/card.php:2929|check|if (!getDolGlobalString(''PRODUCT_DISABLE_WEIGHT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DISPLAY_VAT_INCL_PRICES', 'string', NULL, 'product', 'Enables display of VAT-inclusive (TTC) prices alongside the normal price fields on the product price page.', 'Read twice in product/price.php (lines 1414 and 1427), each time guarding a display of $object->price_ttc or $object->price_min_ttc only when the corresponding value is not empty.', 'Enabling it shows the TTC (tax-inclusive) sale price and minimum TTC price on the product card price tab; disabled/unset hides those TTC displays.', 'Boolean-like: enabled = show VAT-included price fields when set on the product; unset/0 = hide them.', 0, 0, NULL, 1, '6d1ae0b07e3f22f8ec780726ac76f543a41c51070f687543a360deab4f12be15', 'v2', '2026-07-24T07:05:23+00:00', '["product/price.php:1414: if (getDolGlobalString(''PRODUCT_DISPLAY_VAT_INCL_PRICES'') && !empty($object->price_ttc)) {", "product/price.php:1427: if (getDolGlobalString(''PRODUCT_DISPLAY_VAT_INCL_PRICES'') && !empty($object->price_min_ttc)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DONOTSEARCH_ANYWHERE', 'string', NULL, 'admin', 'Disables searching product reference/label with a leading wildcard, improving search performance by allowing index use.', 'Checked with !getDolGlobalString(''PRODUCT_DONOTSEARCH_ANYWHERE'') in admin/system/perf.php:685/689 and core/class/html.form.class.php:3802/4536, with comment ''Can use index if PRODUCT_DONOTSEARCH_ANYWHERE is on''.', 'When enabled, the search prefix wildcard ''%'' is omitted ($prefix = '''' instead of ''%''), allowing SQL to use an index for product searches instead of a full scan.', NULL, 0, 0, 'admin/system/perf.php|admin/system/perf.php', 1, '004cbb6a0abf7ad5be6bd4cda70a1c56934ec2550b5549955447991308dd7a2c', 'v2', '2026-07-24T06:41:12+00:00', '["$prefix = getDolGlobalString(''PRODUCT_DONOTSEARCH_ANYWHERE'') ? '''' : ''%''; // Can use index if PRODUCT_DONOTSEARCH_ANYWHERE is on"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_DRAFT_WATERMARK', 'string', NULL, 'core', 'Enables a draft watermark on the PDF sheet generated for a Product/Service that is still in draft status.', 'Checked in core/modules/product/doc/pdf_standard.modules.php:744: `if ($object->status == 0 && getDolGlobalString(''PRODUCT_DRAFT_WATERMARK''))` before calling pdf_watermark(); the watermark text actually drawn is taken from the separate constant COMMANDE_DRAFT_WATERMARK.', 'When set (truthy) and the product/service is in draft status (status==0), the PDF sheet is stamped with a watermark; when unset, no watermark is shown for draft products.', 'Truthy/falsy flag; no enumerated values found in payload. Note: the actual watermark text is read from COMMANDE_DRAFT_WATERMARK, not from this constant itself.', 0, 0, NULL, 1, '25216ab8c121549742e161f3cfb0d0a79bc2cd7e4b7666621382969b4b00198a', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/product/doc/pdf_standard.modules.php:744|check|if ($object->status == 0 && getDolGlobalString(''PRODUCT_DRAFT_WATERMARK'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ELEPHANT_ADD_WHERE', 'string', NULL, 'core', 'Provides an additional SQL WHERE clause fragment appended during product-code uniqueness checks in the Elephant numbering module.', 'Checked and applied in core/modules/product/mod_codeproduct_elephant.php lines 211-212: when non-empty, the value is sanitised with dol_string_nospecial/dol_string_unaccent and appended to the uniqueness query.', 'Setting this constant restricts the product-code uniqueness check to a subset of products matching the extra condition; incorrect SQL syntax will break code generation.', 'Any valid SQL WHERE sub-expression (without leading AND/OR; e.g. ''entity=1'').', 1, 0, NULL, 1, '9ddf6cfc26e34a77afdd32601587da2a545a9148e5f82b452881314d525a9acd', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/product/mod_codeproduct_elephant.php:211|check|if (getDolGlobalString(''PRODUCT_ELEPHANT_ADD_WHERE'')) {", "core/modules/product/mod_codeproduct_elephant.php:212|read|$where = '' AND (''.dol_string_nospecial(dol_string_unaccent(getDolGlobalString(''PRODUCT_ELEPHANT_ADD_WHERE'')), ''_'', array('','', ''@'', ''\"'', \"|\", \";\", \":\")).'')''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ELEPHANT_MASK_PRODUCT', 'string', NULL, 'core', 'Defines the numbering mask for products (type=0) in the ''Elephant'' product-code numbering module.', 'Used in core/modules/product/mod_codeproduct_elephant.php: displayed in a configuration field (line 107) and applied as the active mask for product-code generation (lines 187, 232, 277). Activated only when $type == 0 and the constant is non-empty (line 186).', 'Changing this mask alters the auto-generated codes for new products; existing product codes are not retroactively changed.', 'Any mask string accepted by the Elephant numbering module.', 1, 0, NULL, 1, '17fd25fc339b2a0c28b2e57f582ae357b9e3d80310cb89f4acded9cca3c0bf75', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/product/mod_codeproduct_elephant.php:186|check|if ($type == 0 && getDolGlobalString(''PRODUCT_ELEPHANT_MASK_PRODUCT'')) {", "core/modules/product/mod_codeproduct_elephant.php:187|read|$mask = getDolGlobalString(''PRODUCT_ELEPHANT_MASK_PRODUCT'');", "core/modules/product/mod_codeproduct_elephant.php:232|read|$mask = getDolGlobalString(''PRODUCT_ELEPHANT_MASK_PRODUCT'');", "core/modules/product/mod_codeproduct_elephant.php:277|read|$mask = getDolGlobalString(''PRODUCT_ELEPHANT_MASK_PRODUCT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ELEPHANT_MASK_SERVICE', 'string', NULL, 'core', 'Defines the numbering mask for services (type=1) in the ''Elephant'' product-code numbering module.', 'Used in core/modules/product/mod_codeproduct_elephant.php: displayed in a configuration field (line 115) and applied as the active mask for service-code generation (lines 189, 237, 280). Activated only when $type == 1 and the constant is non-empty (line 188).', 'Changing this mask alters the auto-generated codes for new services; existing service codes are not retroactively changed.', 'Any mask string accepted by the Elephant numbering module.', 1, 0, NULL, 1, '9e94db1780ea904f47fd7be26485e65ff3504ce66556a6e39c8770fbf700d1b4', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/product/mod_codeproduct_elephant.php:188|read|} elseif ($type == 1 && getDolGlobalString(''PRODUCT_ELEPHANT_MASK_SERVICE'')) {", "core/modules/product/mod_codeproduct_elephant.php:189|read|$mask = getDolGlobalString(''PRODUCT_ELEPHANT_MASK_SERVICE'');", "core/modules/product/mod_codeproduct_elephant.php:237|read|$mask = getDolGlobalString(''PRODUCT_ELEPHANT_MASK_SERVICE'');", "core/modules/product/mod_codeproduct_elephant.php:280|read|$mask = getDolGlobalString(''PRODUCT_ELEPHANT_MASK_SERVICE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_GENERATE_REF_AFTER_FORM', 'string', NULL, 'product', 'Defers automatic product reference generation until after the creation form is submitted rather than pre-filling it.', 'Checked in product/card.php at lines 534, 736, 798, and 1512. When not set, the ref is pre-filled before form display; when set, generation is skipped pre-form and triggered post-submission.', 'Enabling this means the product reference is not shown in the creation form and is generated on save; disabling it pre-fills the reference in the form.', 'truthy = generate ref after form submit; empty/not set = pre-fill ref in form', 1, 0, NULL, 1, '30b8079fa0bdd916b78d855ef5c20d067cb1ac26061e4ce4c8b2e5de4e23e442', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:736|check|if (!$ref && getDolGlobalString(''PRODUCT_GENERATE_REF_AFTER_FORM'')) {", "product/card.php:534|check|if (!getDolGlobalString(''PRODUCT_GENERATE_REF_AFTER_FORM'')) {", "product/card.php:798|check|if (!getDolGlobalString(''PRODUCT_GENERATE_REF_AFTER_FORM'')) {", "product/card.php:1512|check|if (!getDolGlobalString(''PRODUCT_GENERATE_REF_AFTER_FORM'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_HIDE_ADD_CONTACT_THIPARTY', 'bool', NULL, 'product', 'Hides the ''add thirdparty as contact'' option on the product/service contact tab (note: constant name has a typo, ''THIPARTY'' instead of ''THIRDPARTY'', matching the source code exactly).', 'Checked in product/contact.php:171, setting $hideaddcontactforthirdparty = 1 which is then passed to the shared contacts.tpl.php template that renders the contact-adding UI.', 'Enabling it removes the ability to add a thirdparty as a contact on a product/service card''s Contacts tab.', 'Boolean: 0/unset = add-thirdparty-contact option shown (default); 1 = hidden.', 0, 0, NULL, 1, 'de0c58bcab550bf5d46276bc68be6c50bbb172dd06f51a05e24d411eeaa3e876', 'v2', '2026-07-24T07:05:23+00:00', '["product/contact.php:171: if (getDolGlobalString(''PRODUCT_HIDE_ADD_CONTACT_THIPARTY'')) {", "product/contact.php:172: $hideaddcontactforthirdparty = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_HIDE_ADD_CONTACT_USER', 'bool', NULL, 'product', 'Hides the ''add internal user as contact'' option on the product/service contact tab.', 'Checked in product/contact.php:168, setting $hideaddcontactforuser = 1 which is then passed to the shared contacts.tpl.php template that renders the contact-adding UI.', 'Enabling it removes the ability to add an internal user as a contact on a product/service card''s Contacts tab.', 'Boolean: 0/unset = add-user-contact option shown (default); 1 = hidden.', 0, 0, NULL, 1, 'a663c54f47fffad7be31ea8ea214f7b011a74d44049947a63604d9169b0b978c', 'v2', '2026-07-24T07:05:23+00:00', '["product/contact.php:168: if (getDolGlobalString(''PRODUCT_HIDE_ADD_CONTACT_USER'')) {", "product/contact.php:169: $hideaddcontactforuser = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_ID_FOR_FREE_AMOUNT_INVOICE', 'string', NULL, 'public', 'Specifies the product ID used as the line item when creating a free-amount public invoice.', 'Checked at public/invoice/new.php:99 to gate the free-amount invoice feature, and read at :201 as the integer product ID assigned to the invoice line. Described in the file header comment as ''Product ID used for free amount invoice line''.', 'If not set, the free-amount invoice flow is blocked. If set, the specified product is used for the invoice line item.', 'Product ID used for free amount invoice line', 1, 0, NULL, 1, 'b2c59c72c9f314d33c6d19178956684c2ff2ffd6771e1b614fc6e7811797f635', 'v2', '2026-04-21T13:50:40+00:00', '["public/invoice/new.php:34  *  PRODUCT_ID_FOR_FREE_AMOUNT_INVOICE            Product ID used for free amount invoice line", "public/invoice/new.php:99|check|if (!getDolGlobalString(''PRODUCT_ID_FOR_FREE_AMOUNT_INVOICE'')) {", "public/invoice/new.php:201|read|$productIdForFreeAmountInvoice = (int) getDolGlobalString(''PRODUCT_ID_FOR_FREE_AMOUNT_INVOICE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_LOAD_EXTRAFIELD_INTO_OBJECTLINES', 'string', NULL, 'core', 'When selecting a predefined product on a document line, also loads the product''s extrafield values into the corresponding extrafield inputs of that line.', 'Read in core/tpl/objectline_create.tpl.php:693 into the JS config object, documented at line 767 as ''@property {boolean} conf.PRODUCT_LOAD_EXTRAFIELD_INTO_OBJECTLINES'', and used at JS line 1166 in the AJAX product-selection callback to copy data.array_options values into matching ''_extras_'' input fields.', 'Enabling it auto-populates line-level extrafield inputs from the selected product''s extrafield values via AJAX when a predefined product is picked on a document line.', 'Boolean, read via getDolGlobalInt cast to (bool); truthy enables copying product extrafield values into the object line''s extrafields on product selection.', 0, 0, NULL, 1, 'bd638b67cec2e8e2bfd80f6bda0ddad77eb3fb134af817e41d4a650a8e46839b', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_create.tpl.php:693|read|''PRODUCT_LOAD_EXTRAFIELD_INTO_OBJECTLINES'' => (bool) getDolGlobalInt(''PRODUCT_LOAD_EXTRAFIELD_INTO_OBJECTLINES''),", "core/tpl/objectline_create.tpl.php:767|* @property {boolean} conf.PRODUCT_LOAD_EXTRAFIELD_INTO_OBJECTLINES", "core/tpl/objectline_create.tpl.php:1166|if (jsConf.conf.PRODUCT_LOAD_EXTRAFIELD_INTO_OBJECTLINES) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_LOT_ENABLE_QUALITY_CONTROL', 'bool', NULL, 'product', 'Enables quality-control fields (including end-of-life date) on product lot records.', 'Checked at product/card.php lines 1809, 2451, and 3006, and at product/stock/productlot_card.php line 428. Also controls the enabled state of the ''eol_date'' field in product/stock/class/productlot.class.php line 157 via getDolGlobalInt. Commented-out usage in stats files (commande_fournisseur.php, expedition.php, reception.php) indicates planned but inactive extensions.', 'Enabling this constant activates quality-control fields such as the end-of-life date on lot cards and the product card lot section. Disabling it hides those fields.', 'Boolean flag; absent/falsy = quality control disabled; truthy = quality control enabled. COMMENTS show the constant is referenced but currently inactive in several stats files.', 1, 0, NULL, 1, 'd296e0f184b16aace0feee1c4966f47b99477a7063c74f21d579a109bc7b6304', 'v2', '2026-04-21T13:29:58+00:00', '["product/stock/class/productlot.class.php:157|read|''eol_date'' => array(''type'' => ''date'', ''label'' => ''EndOfLife'', ''enabled'' => ''getDolGlobalInt(\"PRODUCT_LOT_ENABLE_QUALITY_CONTROL\") ? 1 : 0 ''", "product/card.php:1809|check|if (getDolGlobalString(''PRODUCT_LOT_ENABLE_QUALITY_CONTROL'')) {", "product/stock/productlot_card.php:428|check|if (getDolGlobalString(''PRODUCT_LOT_ENABLE_QUALITY_CONTROL'')) {", "product/stock/stats/commande_fournisseur.php:200  //      if (getDolGlobalString(''PRODUCT_LOT_ENABLE_QUALITY_CONTROL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_LOT_ENABLE_TRACEABILITY', 'bool', NULL, 'product', 'Enables traceability fields (manufacturing date, destruction date) on product lot records.', 'When enabled, the ''manufacturing_date'' and ''scrapping_date'' fields on productlot objects become active (enabled condition returns 1). Several stat pages have traceability-related code commented out pending this flag. Used in product/stock/class/productlot.class.php and product/stock/productlot_card.php. No admin UI write; hidden setting.', 'Enabling this constant activates traceability date fields on lot records; disabling it hides those fields.', 'Non-zero integer (truthy) enables traceability; 0 or undefined disables it.', 1, 0, NULL, 1, '76be692851905db15c8236576624c6fac1700a98511ef477e49ac20d459faade', 'v2', '2026-04-21T13:50:40+00:00', '["product/stock/class/productlot.class.php:158|read|''scrapping_date'' => array(''type'' => ''date'', ''label'' => ''DestructionDate'', ''enabled'' => ''getDolGlobalInt(\"PRODUCT_LOT_ENABLE_TRACEABILITY\") ? 1 : 0''", "product/stock/class/productlot.class.php:154|read|''manufacturing_date'' => array(''type'' => ''date'', ''label'' => ''ManufacturingDate'', ''enabled'' => ''getDolGlobalInt(\"PRODUCT_LOT_ENABLE_TRACEABILITY\") ? 1 : 0''", "product/stock/productlot_card.php:415|check|if (getDolGlobalString(''PRODUCT_LOT_ENABLE_TRACEABILITY'')) {", "//      if (getDolGlobalString(''PRODUCT_LOT_ENABLE_TRACEABILITY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_MAX_LENGTH_COMBO', 'string', NULL, 'core', 'Sets the maximum character length for product labels displayed in product combobox/selector widgets.', 'In core/class/html.form.class.php, getDolGlobalInt(''PRODUCT_MAX_LENGTH_COMBO'', 48) is used to truncate product labels in two selector methods. The default fallback is 48 characters. No admin UI write; hidden setting.', 'Increasing this value shows longer product labels in selectors; decreasing it truncates labels more aggressively; the default is 48 characters.', 'Integer character count; default is 48.', 1, 0, NULL, 1, '6231537cb0ebe384f0a3cffd9fdc057452fbf64e5b7c10ba69064639998b37dc', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:3595|read|$maxlengtharticle = getDolGlobalInt(''PRODUCT_MAX_LENGTH_COMBO'', 48);", "core/class/html.form.class.php:4016|read|$maxlengtharticle = getDolGlobalInt(''PRODUCT_MAX_LENGTH_COMBO'', 48);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_MAX_VISIBLE_PHOTO', 'string', NULL, 'core', 'Sets the maximum number of product photos shown in the product photo block on the object card.', 'In core/lib/functions.lib.php:3415, used as `getDolGlobalInt(''PRODUCT_MAX_VISIBLE_PHOTO'', 5)` to cap the number of photos passed to show_photos() for a product; default is 5, and it is forced to 1 on phone layout.', 'Increasing/decreasing the value changes how many product photos are displayed at once in the card header photo block.', 'Integer count of photos to display; default 5 if unset.', 1, 0, NULL, 1, '2c7a808e2301528c8b2d74a008ad7512ea8df67c820a155df20c0f0966fe2cfc', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3415|read|$maxvisiblephotos = getDolGlobalInt(''PRODUCT_MAX_VISIBLE_PHOTO'', 5);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_MINIMUM_RECOMMENDED_PRICE', 'string', NULL, 'product', 'Enforces a minimum recommended price based on the highest supplier price multiplied by this constant.', 'Checked in product/class/product.class.php:7083 and extensively in product/price.php (lines 516, 806, 956, 1719, 1807, 1879, 2033). The docblock comment at product/class/product.class.php:7076 states: ''Minimum recommended price that is higher price among all suppliers * PRODUCT_MINIMUM_RECOMMENDED_PRICE''.', 'When set, saving a product price below the computed minimum triggers an error or warning. This prevents selling below the supplier cost threshold.', 'Numeric string used as a multiplier against the highest supplier price; empty/unset disables the minimum price check.', 1, 0, NULL, 1, '40f8513e6c053654b9e6696d6f3fab2b2011c363fa2105c8ba6f718109f217b1', 'v2', '2026-04-21T13:29:58+00:00', '["product/class/product.class.php:7076  * @return int            Minimum recommended price that is higher price among all suppliers * PRODUCT_MINIMUM_RECOMMENDED_PRICE", "product/class/product.class.php:7083|check|if (getDolGlobalString(''PRODUCT_MINIMUM_RECOMMENDED_PRICE'')) {", "product/price.php:516|check|if (getDolGlobalString(''PRODUCT_MINIMUM_RECOMMENDED_PRICE'') && $newprice_min < $maxpricesupplier) {", "product/price.php:806|check|if (getDolGlobalString(''PRODUCT_MINIMUM_RECOMMENDED_PRICE'') && $prodcustprice->price_min < (float) $maxpricesupplier) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_NODISPLAYIFNOPHOTO', 'string', NULL, 'core', 'Suppresses the ''no photo'' placeholder image on the product card when the product has no photo.', 'In core/lib/functions.lib.php:3423, if the product has no available photo and this constant is set, the code leaves an empty div instead of rendering the nophoto.png placeholder with its upload-hint tooltip.', 'Enabling it hides the generic ''no photo'' placeholder for products without photos, showing an empty block instead.', 'Boolean-like: any truthy value suppresses the no-photo placeholder.', 1, 0, NULL, 1, '60153e81bbc522771414f5f6b3852e67c8d6aa73cb032a25960f37e9d8628c80', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3423|check|if (getDolGlobalString(''PRODUCT_NODISPLAYIFNOPHOTO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_PRICE_BASE_TYPE', 'string', 'HT', 'product', 'Sets the default price base type (tax-excluded or tax-included) for products.', 'Configured via product/admin/product.php (written with dolibarr_set_const). Read in product/class/product.class.php:1003-1004 to set the product''s price_base_type when it is empty, and rendered as a select in product/admin/product.php:639 and product/card.php:1863. Default value is ''HT''.', 'Changing this value alters the default pricing mode offered when creating or editing products.', '''HT'' (tax-excluded, default) or ''TTC'' (tax-included).', 0, 0, 'product/admin/product.php|product/admin/product.php', 1, 'c67c3c2aec3640ed47a88316a2012bfa250e353a93675041acd157dcaa315c32', 'v2', '2026-04-21T13:29:58+00:00', '["product/admin/product.php:148|write|$res = dolibarr_set_const($db, \"PRODUCT_PRICE_BASE_TYPE\", $value, ''chaine'', 0, '''', $conf->entity);", "product/class/product.class.php:1003|check|if (empty($this->price_base_type) && getDolGlobalString(''PRODUCT_PRICE_BASE_TYPE'')) {", "product/class/product.class.php:1004|read|$this->price_base_type = getDolGlobalString(''PRODUCT_PRICE_BASE_TYPE'');", "product/admin/product.php:639|read|print $form->selectPriceBaseType(getDolGlobalString(''PRODUCT_PRICE_BASE_TYPE''), \"price_base_type\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_PRICE_SUPPLIER_NO_LOG', 'string', NULL, 'fourn', 'Disables logging of supplier buy-price history when a supplier product price is updated.', 'Checked (negated) in fourn/class/fournisseur.product.class.php:596 and :689, both right after the PRODUCT_BUYPRICE_MODIFY trigger call, guarding the call to $this->logPrice() that records the price change history.', 'Enabling it stops new supplier buy-price changes from being recorded in the price log/history, so past-price tooltips and history lists will be incomplete going forward.', 'Boolean: 0/unset = price changes are logged (default); 1 = price change logging is skipped.', 0, 0, NULL, 1, '251055e58d7ec14d8291bc117a9b16b9a693e384bd226e10fe300ea100609a8c', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/class/fournisseur.product.class.php:596: if (!$error && !getDolGlobalString(''PRODUCT_PRICE_SUPPLIER_NO_LOG'')) {", "fourn/class/fournisseur.product.class.php:689: if (!$error && !getDolGlobalString(''PRODUCT_PRICE_SUPPLIER_NO_LOG'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_PRICE_UNIQ', 'string', NULL, 'product', 'Enforces a single unique price per product, disabling per-customer or multi-level pricing.', 'Written to value 1 in product/admin/product.php:133 and checked in product/class/api_products.class.php:442, product/list.php:969, and core/actions_massactions.inc.php:1384 to gate price-related actions.', 'Enabling this enforces a single price per product; it blocks mass-action and API operations that would set per-customer prices when combined with related pricing constants.', '0 or not set = multiple prices allowed; 1 = unique price enforced', 0, 0, 'product/admin/product.php', 1, 'bde9bf476b6f204e6e924d3650f670c1385f77494d370476ad0bd62d151574ee', 'v2', '2026-04-21T11:16:15+00:00', '["product/admin/product.php:133|write|dolibarr_set_const($db, ''PRODUCT_PRICE_UNIQ'', 1, ''chaine'', 0, '''', $conf->entity);", "product/class/api_products.class.php:442|check|if ($result > 0 && (getDolGlobalString(''PRODUCT_PRICE_UNIQ'') || getDolGlobalString(''PRODUIT_CUSTOMER_PRICES''))) {", "product/list.php:969|check|if (getDolGlobalString(''PRODUCT_PRICE_UNIQ'')", "core/actions_massactions.inc.php:1384|check|if (getDolGlobalString(''PRODUCT_PRICE_UNIQ'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_QUICKSEARCH_ON_FIELDS', 'string', NULL, 'product', 'Defines a custom set of database fields to search when performing a quick search on the product list.', 'COMMENT at product/list.php:243 documents the format: ''p.ref=ProductRef;p.label=ProductLabel;p.description=Description;p.note=Note;''. Checked at line 244; if set, the value is parsed via dolExplodeIntoArray at line 245 to override the default search fields.', 'Setting this constant replaces the default product quick-search fields with the specified set. Clearing it restores the default fields.', 'From COMMENT: getDolGlobalString(''PRODUCT_QUICKSEARCH_ON_FIELDS'') = ''p.ref=ProductRef;p.label=ProductLabel;p.description=Description;p.note=Note;''. Format: ''db_field=LangKey;...''', 1, 0, NULL, 1, '5c6d09d98648f18783555c4f3e5192a391c912efff948a5714e2e40b308cda75', 'v2', '2026-04-21T13:29:58+00:00', '["product/list.php:243  // Personalized search criteria. Example: getDolGlobalString(''PRODUCT_QUICKSEARCH_ON_FIELDS'') = ''p.ref=ProductRef;p.label=ProductLabel;p.description=Description;p.note=Note;''", "product/list.php:244|check|if (getDolGlobalString(''PRODUCT_QUICKSEARCH_ON_FIELDS'')) {", "product/list.php:245|read|$fieldstosearchall = dolExplodeIntoArray(getDolGlobalString(''PRODUCT_QUICKSEARCH_ON_FIELDS''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_SEARCH_AUTOFOCUS', 'string', NULL, 'core', 'Enables autofocus on the product search input field in product selection comboboxes.', 'In core/class/html.form.class.php, the autofocus HTML attribute on the product search input is controlled by this constant. Present in four read occurrences across multiple product selector methods. No admin UI write; hidden setting.', 'Enabling this constant causes the product search field to receive focus automatically when the selector opens; disabling it leaves focus management to the browser default.', 'Non-empty (truthy) enables autofocus on product search input; empty or undefined disables it.', 1, 0, NULL, 1, 'd590cb6d3b6c81f6e0beeb485eb562fd49043099c9da6621c34ab08e50e75f57', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:2946|read|$out .= ''<input type=\"text\" class=\"minwidth100\" name=\"search_'' . $htmlname . ''\" id=\"search_'' . $htmlname . ''\" value=\"'' . $selected_input_val", "core/class/html.form.class.php:8383|read|$out .= ''<input type=\"text\" class=\"minwidth100\" name=\"search_'' . $htmlname . ''\" id=\"search_'' . $htmlname . ''\" value=\"'' . $selected_input_value . ''\"''", "core/class/html.form.class.php:8609|read|$out .= ''<input type=\"text\" class=\"minwidth100\" name=\"search_'' . $htmlname . ''\" id=\"search_'' . $htmlname . ''\" value=\"'' . $selected_input_value . ''\"''", "core/class/html.form.class.php:8842|read|$out .= ''<input type=\"text\" class=\"minwidth100\" name=\"search_'' . $htmlname . ''\" id=\"search_'' . $htmlname . ''\" value=\"'' . $selected_input_value . ''\"''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_SEARCH_AUTO_SELECT_IF_ONLY_ONE', 'string', NULL, 'core', 'Controls whether the product ajax autocompleter auto-selects the single result when only one product match is found.', 'core/class/html.form.class.php:3407: `$out .= ajax_autocompleter((string) $selected, $htmlname, DOL_URL_ROOT . ''/product/ajax/products.php'', $urloption, getDolGlobalInt(''PRODUIT_USE_SEARCH_TO_SELECT''), getDolGlobalInt(''PRODUCT_SEARCH_AUTO_SELECT_IF_ONLY_ONE'', 1), $ajaxoptions);` — note the default value passed is 1 (auto-select enabled by default).', 'Setting it to 0 disables the auto-select-if-unique behavior of the product ajax autocompleter, requiring the user to manually pick the single suggested product; default (unset) behaves as 1 (auto-select).', 'Default is 1 (auto-select the only match); 0 disables auto-select, per the getDolGlobalInt(..., 1) default argument in code.', 1, 0, NULL, 1, '89267f855a50e4f539fdb6068cbc12fe8344f60bdf907c1c80ef647feaf728eb', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:3407: getDolGlobalInt(''PRODUCT_SEARCH_AUTO_SELECT_IF_ONLY_ONE'', 1), $ajaxoptions);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_SHOW_DESCRIPTION_IN_TOOLTIP', 'bool', NULL, 'product', 'Shows the product description inside the product tooltip/hover popup when enabled.', 'Checked in product/class/product.class.php:5930, only when the product''s description is not empty, to decide whether to include it in the generated tooltip HTML.', 'Enabling it adds the product description text to tooltips shown across the application wherever product tooltips are rendered.', 'Boolean: 0/unset = description not shown in tooltip, 1 = shown.', 0, 0, NULL, 1, '024252071448db45bd176e84171a35d6469197fd892cd95ec1ee4599241c9146', 'v2', '2026-07-24T07:05:23+00:00', '["product/class/product.class.php:5930: if (!empty($this->description) && getDolGlobalString(''PRODUCT_SHOW_DESCRIPTION_IN_TOOLTIP'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_SHOW_DIMENSIONS_IN_COMBO', 'bool', NULL, 'core', 'Appends product weight/dimensions/surface/volume info to the label shown in product selection comboboxes.', 'core/class/html.form.class.php:4090-4099: `if (getDolGlobalString(''PRODUCT_SHOW_DIMENSIONS_IN_COMBO'')) { if (!empty($objp->weight) ...) { $unitToShow = showDimensionInBestUnit(...); $outvalUnits .= '' - '' . $unitToShow; } if ((!empty($objp->length) || ...) ...) { ... } if (!empty($objp->surface) ...) { ... } }`.', 'Setting it to a truthy value adds extra text (weight, length x width x height, surface, etc., each in their best-fit unit) to product combobox option labels, making the dropdown more informative but longer.', 'Truthy = append weight/dimensions/surface (each shown via showDimensionInBestUnit/measuringUnitString) to the product option label; 0/unset = dimensions not shown (default).', 0, 0, NULL, 1, 'cb07a239ea86a8fa6b60f35d63799bfe968a630d882efcb51a0569891faac8e7', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:4090: if (getDolGlobalString(''PRODUCT_SHOW_DIMENSIONS_IN_COMBO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_SHOW_ORIGIN_IN_COMBO', 'bool', NULL, 'core', 'Displays the product''s country of origin alongside the product label in combobox selectors.', 'When set and an origin value is present ($outorigin), core/class/html.form.class.php appends the origin to the product label in three distinct selector rendering locations. No admin UI write; hidden setting.', 'Enabling this constant adds the origin country/region to product labels in selectors; disabling it (or leaving unset) shows only the standard label.', 'Non-empty (truthy) shows origin in product combo; empty or undefined hides it.', 1, 0, NULL, 1, 'f24ca2fc177bc93165ef389191f10dc6f00e33350b4eb1b620b6eb8f75e46238', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:3622|check|if ($outorigin && getDolGlobalString(''PRODUCT_SHOW_ORIGIN_IN_COMBO'')) {", "core/class/html.form.class.php:3686|check|if ($outorigin && getDolGlobalString(''PRODUCT_SHOW_ORIGIN_IN_COMBO'')) {", "core/class/html.form.class.php:3703|check|if ($outorigin && getDolGlobalString(''PRODUCT_SHOW_ORIGIN_IN_COMBO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_SHOW_SUB_SUB_PRODUCTS', 'bool', NULL, 'product', 'Controls whether nested sub-sub-products (products-of-a-subproduct) are shown by default in the product composition/kit view.', 'Checked in product/composition/card.php:705; the inline comment explains the row is hidden by default (''By default, we do not show this. It makes screen very difficult to understand'') via an added ''hideobject'' CSS class when the constant is not set.', 'Enabling it removes the ''hideobject'' CSS class from nested sub-product rows, making deeper levels of product composition visible in the kit/composition table instead of hidden.', 'Boolean-like: falsy (default) hides sub-sub-product rows with CSS class ''hideobject''; truthy shows them.', 1, 0, NULL, 1, '20363fba77fb573ae1906f258602e27bbeea378dfb53218f8771af4d244b62f6', 'v2', '2026-07-24T07:05:23+00:00', '["product/composition/card.php:705|check|if (!getDolGlobalString(''PRODUCT_SHOW_SUB_SUB_PRODUCTS'')) {", "$hide = '' hideobject''; // By default, we do not show this. It makes screen very difficult to understand"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_SORT_BY_CATEGORY', 'string', NULL, 'core', 'Sorts the product list in comboboxes by product category rather than by the default order.', 'When set, core/class/html.form.class.php adds an ORDER BY clause on categorie_product_id. The value 1 sorts ascending; any other truthy value sorts descending. Three occurrences in the file. No admin UI write; hidden setting.', 'Setting this to 1 sorts products by category ascending in selectors; setting it to another truthy value sorts descending; leaving it unset uses the default sort order.', '1 = sort by category ASC; other non-empty value = sort by category DESC; empty or undefined = default order.', 1, 0, NULL, 1, 'f3b16737d21f4b3caa8f2d4bafb29e8917d23423798cc1006e5174e37cade7e1', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:3193|check|if (getDolGlobalString(''PRODUCT_SORT_BY_CATEGORY'')) {", "core/class/html.form.class.php:3402|read|$sql .= \" ORDER BY categorie_product_id \".(getDolGlobalInt(''PRODUCT_SORT_BY_CATEGORY'') == 1 ? \"ASC\" : \"DESC\");", "core/class/html.form.class.php:3401|check|if (getDolGlobalString(''PRODUCT_SORT_BY_CATEGORY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_STATS_WITH_PARENT_PROD_IF_INCDEC', 'string', NULL, 'product', 'Includes parent product statistics when a product''s stock is set to increment/decrement.', 'Checked in product/class/product.class.php at lines 3548, 3679, 3896, 4149, 4220, 4292. Also appears commented-out in product/stock/class/productlot.class.php:879, :954, :1027, indicating the feature is not yet active for lot-level stats.', 'When enabled, product usage statistics aggregate data from the parent product where applicable. The commented-out occurrences in productlot.class.php indicate lot-level aggregation is not yet implemented.', 'Truthy string (parent stats included) or empty/unset (no parent aggregation).', 1, 0, NULL, 1, 'd361f5ab23843d9b3733cfbd3ea902456e56e3c5f96602b4acfc005f2ea44b98', 'v2', '2026-04-21T13:29:58+00:00', '["product/class/product.class.php:3548|check|if (getDolGlobalString(''PRODUCT_STATS_WITH_PARENT_PROD_IF_INCDEC'')) {", "product/class/product.class.php:3679|check|if (getDolGlobalString(''PRODUCT_STATS_WITH_PARENT_PROD_IF_INCDEC'')) {", "product/stock/class/productlot.class.php:879  //          if (getDolGlobalString(''PRODUCT_STATS_WITH_PARENT_PROD_IF_INCDEC'')) {", "product/stock/class/productlot.class.php:954  //          if (getDolGlobalString(''PRODUCT_STATS_WITH_PARENT_PROD_IF_INCDEC'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_STOCK_LIST_SHOW_VIRTUAL_WITH_NO_PHYSICAL', 'bool', NULL, 'product', 'In the product stock/reassort list, also shows products that have virtual (supplier-order-based) stock but zero physical stock in any warehouse.', 'Used in product/reassort.php:196-198: when PRODUCT_STOCK_LIST_SHOW_WITH_PRECALCULATED_DENORMALIZED_PHYSICAL_STOCK is off and this constant is falsy, the SQL restricts results to rows with an existing physical warehouse entry; when this constant is truthy, the SQL is widened with an OR clause including a subquery summing supplier-order quantities (cd1/commande_fournisseurdet), so products with only virtual/incoming stock also appear.', 'Enabling it widens the reassort/stock list to include products with no physical warehouse stock line but pending supplier-order quantities, which otherwise would be excluded from the list.', 'Boolean-like: any truthy value includes products with virtual-only (no physical) stock in the reassort list.', 1, 0, NULL, 1, 'cafcd95a1c8c86442daad05ebcf6b32b4392b8f074da608151d1648f1d7519e0', 'v2', '2026-07-24T07:05:23+00:00', '["product/reassort.php:197: if (!getDolGlobalString(''PRODUCT_STOCK_LIST_SHOW_VIRTUAL_WITH_NO_PHYSICAL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_STOCK_LIST_SHOW_WITH_PRECALCULATED_DENORMALIZED_PHYSICAL_STOCK', 'bool', NULL, 'product', 'Switches the product stock reassort list to use pre-calculated denormalized physical stock values instead of real-time computation.', 'Checked at multiple points in product/reassort.php (lines 156, 169, 196, 268, 280, 291) to branch between denormalized and live stock data paths.', 'Enabling uses pre-calculated stock figures, which is faster but reflects a snapshot; disabling computes stock in real time.', 'Truthy value to use denormalized physical stock; absent or falsy to use real-time stock computation.', 1, 0, NULL, 1, 'da930a224c4cc1af2307dcf1703282c1e54baae2c7a3d3fcea0c672d7974d211', 'v2', '2026-04-21T13:29:58+00:00', '["product/reassort.php:156|check|if (getDolGlobalString(''PRODUCT_STOCK_LIST_SHOW_WITH_PRECALCULATED_DENORMALIZED_PHYSICAL_STOCK'')) {", "product/reassort.php:169|check|if (!getDolGlobalString(''PRODUCT_STOCK_LIST_SHOW_WITH_PRECALCULATED_DENORMALIZED_PHYSICAL_STOCK'')) {", "product/reassort.php:268|check|if (getDolGlobalString(''PRODUCT_STOCK_LIST_SHOW_WITH_PRECALCULATED_DENORMALIZED_PHYSICAL_STOCK'')) {", "product/reassort.php:280|check|if (!getDolGlobalString(''PRODUCT_STOCK_LIST_SHOW_WITH_PRECALCULATED_DENORMALIZED_PHYSICAL_STOCK'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_USE_CUSTOMER_PACKAGING', 'bool', NULL, 'product', 'Enables a customer-specific packaging quantity field on product prices.', 'Configured via product/admin/product.php:180. Checked in product/price.php:501, :1433, :1726, and compta/facture/class/facture.class.php:4339. A COMMENT notes it is not implemented/supported in certain customer price modes and is disabled there.', 'When enabled, a packaging field appears on customer price forms and is used during invoice line processing. Enabling it in unsupported customer price modes has no effect as the system disables it.', 'Empty/0 = customer packaging disabled; truthy = customer packaging enabled', 0, 0, 'product/admin/product.php', 1, 'd6592f8b35145d9298cd1578c97d22b5f975bb27a1ea9db4cc90b77d61ae4890', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/conf.class.php:1387  // In on of this customer price modes, option PRODUCT_USE_CUSTOMER_PACKAGING is not implemented/supported, so we disable it", "product/admin/product.php:180|write|$res = dolibarr_set_const($db, \"PRODUCT_USE_CUSTOMER_PACKAGING\", $value, ''chaine'', 0, '''', $conf->entity);", "product/price.php:298|read|$packaging = getDolGlobalString(''PRODUCT_USE_CUSTOMER_PACKAGING'') ? price2num(GETPOST(''packaging'', ''alpha''), ''MS'') : null;", "compta/facture/class/facture.class.php:4339|check|if (getDolGlobalString(''PRODUCT_USE_CUSTOMER_PACKAGING'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_USE_DEPRECATED_ASSEMBLY_AND_STOCK_KIT_TYPE', 'bool', NULL, 'product', 'Re-enables the deprecated product types ''assembly'' (2) and ''stock kit'' (3) in the product composition/sub-product parent-check logic.', 'Checked in product/composition/card.php:481; the inline comment states ''This type is not supported (not required to have virtual products working)'', and the guarded code only runs when the constant is set, checking $prod_arbo->type == 2 || $prod_arbo->type == 3.', 'Enabling it re-activates legacy handling for parent-check on product types 2 (assembly) and 3 (stock kit), which the code comment marks as deprecated/unsupported and not required for virtual products to work.', 'Boolean-like: truthy re-enables deprecated handling of product types 2 (assembly) and 3 (stock kit) in the composition parent-product check.', 1, 0, NULL, 1, 'f951e2725ccc5035fa80929de39c2b17d85b196309f2ec666de708a07872005d', 'v2', '2026-07-24T07:05:23+00:00', '["product/composition/card.php:481|check|if (getDolGlobalString(''PRODUCT_USE_DEPRECATED_ASSEMBLY_AND_STOCK_KIT_TYPE'')) {", "// This type is not supported (not required to have virtual products working)."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_USE_LINK_PATH_FOR_PHOTO', 'bool', NULL, 'core', 'Enables use of a symbolic link path instead of the direct path for product photos.', 'Checked in core/class/commonobject.class.php:10172 and read in core/lib/functions.lib.php:3431. When set, photo URLs are constructed using the link path variant.', 'Setting this constant changes how product photo URLs are resolved, switching from direct file paths to link-based paths.', 'Non-zero = use link path for photo; 0 or unset = use direct path', 1, 0, NULL, 1, '17798793c1edaf658f420e4ebed6aa4823bc28a33ec3efdd2452928d590dbecb', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:10172|check|if (getDolGlobalInt(''PRODUCT_USE_LINK_PATH_FOR_PHOTO'')) {", "core/lib/functions.lib.php:3431|read|$useLinkPathPhoto = getDolGlobalInt(''PRODUCT_USE_LINK_PATH_FOR_PHOTO'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_USE_OLD_PATH_FOR_PHOTO', 'bool', NULL, 'core', 'Forces product photo resolution to use the legacy directory path structure.', 'Checked in 32 locations across core/class/commonobject.class.php:10135, core/lib/functions.lib.php:8923, core/lib/files.lib.php:442, and numerous PDF modules. A TODO comment at core/lib/files.lib.php:443 notes this will be removed once deprecated.', 'Enabling this constant routes photo lookups to the old path structure instead of the current one; disabling it uses the modern path. Marked for future removal.', '0 (modern path, default) or 1 (legacy path)', 1, 0, NULL, 1, '244f24eaa749782db8bdfd0b51a50e780199c2e7bdbc27fa6cf21cd83bc0aa97', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/files.lib.php:443  // TODO Remove this when PRODUCT_USE_OLD_PATH_FOR_PHOTO will be removed", "core/class/commonobject.class.php:10161  /*if (getDolGlobalInt(''PRODUCT_USE_OLD_PATH_FOR_PHOTO''))    // For backward compatibility, we scan also old dirs", "core/lib/files.lib.php:442|check|if ($modulepart == ''produit'' && getDolGlobalInt(''PRODUCT_USE_OLD_PATH_FOR_PHOTO'')) {", "core/class/commonobject.class.php:10135|check|if (getDolGlobalInt(''PRODUCT_USE_OLD_PATH_FOR_PHOTO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_USE_OTHER_FIELD_IN_TRANSLATION', 'bool', NULL, 'product', 'Enables use of an additional ''other'' field in product translations.', 'Checked extensively in product/class/product.class.php (lines 2041, 2047, 2053, 2081, 2088, 2094) and product/traduction.php (lines 280, 352). The class comment at product/class/product.class.php:145 documents ''Product other fields PRODUCT_USE_OTHER_FIELD_IN_TRANSLATION''. No admin UI.', 'When enabled, the product translation interface and logic include an additional field, extending the data stored per language.', 'Truthy string (other field active) or empty/unset (other field not used).', 1, 0, NULL, 1, 'ac50773247dd557b252f87df68609097896b382c91940e9832ed8460c9122bee', 'v2', '2026-04-21T13:29:58+00:00', '["product/class/product.class.php:145  * Product other fields PRODUCT_USE_OTHER_FIELD_IN_TRANSLATION", "product/class/product.class.php:2041|check|if (getDolGlobalString(''PRODUCT_USE_OTHER_FIELD_IN_TRANSLATION'')) {", "product/traduction.php:280|check|if (getDolGlobalString(''PRODUCT_USE_OTHER_FIELD_IN_TRANSLATION'')) {", "product/traduction.php:352|check|if (getDolGlobalString(''PRODUCT_USE_OTHER_FIELD_IN_TRANSLATION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_USE_SUB_COST_PRICES_IF_COST_PRICE_EMPTY', 'bool', NULL, 'fourn', 'Makes the supplier price ajax fallback to sub-product cost prices when the main cost price is empty.', 'Used twice in fourn/ajax/getSupplierPrices.php (lines 159 and 178), both guarding a fallback branch executed only if ($price) is empty.', 'When enabled and the computed price is empty, the code falls back to using cost prices of sub-products instead of leaving the price empty.', 'Boolean-like (getDolGlobalString): non-empty enables the sub cost price fallback; empty/unset (default) leaves $price empty in that case.', 1, 0, NULL, 1, 'c59860b8a2ecf83d77a874e56ff9b70a44b1d4bdd8d1cef1b5f1d9442b7b7f4b', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/ajax/getSupplierPrices.php:159: if (empty($price) && getDolGlobalString(''PRODUCT_USE_SUB_COST_PRICES_IF_COST_PRICE_EMPTY'')) {", "fourn/ajax/getSupplierPrices.php:178: if (empty($price) && getDolGlobalString(''PRODUCT_USE_SUB_COST_PRICES_IF_COST_PRICE_EMPTY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_USE_SUPPLIER_PACKAGING', 'bool', NULL, 'fourn', 'Enables the use of supplier-defined packaging quantities on supplier order lines.', 'Configured via product/admin/product.php:175 and checked in multiple supplier order and product class files (fourn/class/fournisseur.commande.class.php:720, :2157, :3213; fourn/class/fournisseur.orderline.class.php:220; fourn/class/fournisseur.product.class.php:563, :626; product/price_suppliers.php:612) to apply packaging logic.', 'When enabled, supplier order quantities are constrained or adjusted according to supplier packaging units; when disabled, no packaging logic is applied.', '0 or not set = supplier packaging not used; non-zero = supplier packaging quantities enforced on order lines.', 0, 0, 'product/admin/product.php', 1, 'f9a6eb2674a4bedcd6af47a224bf0eee83692e4878c7b9848183cd459f1ef959', 'v2', '2026-04-21T11:16:15+00:00', '["product/admin/product.php:175|write|$res = dolibarr_set_const($db, \"PRODUCT_USE_SUPPLIER_PACKAGING\", $value, ''chaine'', 0, '''', $conf->entity);", "fourn/class/fournisseur.commande.class.php:720|check|if (getDolGlobalString(''PRODUCT_USE_SUPPLIER_PACKAGING'')) {", "fourn/class/fournisseur.orderline.class.php:220|check|if (getDolGlobalInt(''PRODUCT_USE_SUPPLIER_PACKAGING'')) {", "fourn/class/fournisseur.product.class.php:563|check|if (getDolGlobalString(''PRODUCT_USE_SUPPLIER_PACKAGING'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUCT_USE_UNITS', 'bool', NULL, 'core', 'Enables display and use of a measurement unit field on products/services.', 'Set via product/admin/product.php:772 (selectyesno on ''activate_units''), and checked with getDolGlobalInt/getDolGlobalString across reception templates, price_suppliers.php, and subtotal templates. The admin page comment marks it as a hidden/legacy feature.', 'When enabled, unit is shown for products in reception lines and elsewhere; the admin page comment states it is kept as a hidden feature because it may duplicate an already-existing field for storing the product unit.', NULL, 0, 0, 'product/admin/product.php', 1, '6e2e44692ab6eea0e3bd5a61359810542694e81cc6dd9adc9e0249c378a3810d', 'v2', '2026-07-24T06:41:12+00:00', '["/* Kept as hidden feature only. PRODUIT_USE_UNITS is hidden for the moment. Because it seems to be a duplicated feature with already existing field to store unit of product", "// Handling colspan if PRODUCT_USE_UNITS conf is enabled", "if (getDolGlobalInt(''PRODUCT_USE_UNITS'')) {\t\t// For product, unit is shown only if option PRODUCT_USE_UNITS is on"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_ATTRIBUTES_HIDECHILD', 'bool', NULL, 'variants', 'Hides child variant products from product lists and selection forms when enabled.', 'Set via variants/admin/admin.php:53 and read at variants/admin/admin.php:95. Checked at accountancy/admin/productaccount.php:572 and core/class/html.form.class.php:3301 to suppress child variants from appearing in product selectors and accounting product lists.', 'When enabled, child product variants are hidden from product lists and form selectors. When disabled, all variants including children are shown.', 'Truthy value = child variants hidden; empty/unset = child variants shown.', 0, 0, 'variants/admin/admin.php|accountancy/admin/productaccount.php|variants/admin/admin.php', 1, '3fa4e67099db06ecaefaf3c1ea903c8cdf0e6f02f0de84648108abe0f8ccd3e2', 'v2', '2026-04-21T11:16:15+00:00', '["variants/admin/admin.php:53|write|if (!dolibarr_set_const($db, ''PRODUIT_ATTRIBUTES_HIDECHILD'', $value, ''chaine'', 0, '''', $conf->entity)) {", "accountancy/admin/productaccount.php:572|check|if (isModEnabled(''variants'') && getDolGlobalInt(''PRODUIT_ATTRIBUTES_HIDECHILD'')) {", "core/class/html.form.class.php:3301|check|if (getDolGlobalString(''PRODUIT_ATTRIBUTES_HIDECHILD'')) {", "variants/admin/admin.php:95|read|print $form->selectyesno(\"PRODUIT_ATTRIBUTES_HIDECHILD\", getDolGlobalString(''PRODUIT_ATTRIBUTES_HIDECHILD''), 1).''</td></tr>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_ATTRIBUTES_HIDECHILD_BUT_ALLOW_SEARCH_IN_EAN13', 'bool', NULL, 'core', 'Refines PRODUIT_ATTRIBUTES_HIDECHILD so that product variants (children of a combination) are still searchable/matchable when the search term looks like a 13-digit EAN barcode.', 'core/class/html.form.class.php:3757-3761: when PRODUIT_ATTRIBUTES_HIDECHILD is set, variant children are normally excluded from product search results via `AND NOT EXISTS (SELECT pac.rowid FROM ...product_attribute_combination... WHERE pac.fk_product_child = p.rowid)`; but if PRODUIT_ATTRIBUTES_HIDECHILD_BUT_ALLOW_SEARCH_IN_EAN13 is also set, that exclusion is skipped when `strlen($filterkey) != 13` is false, i.e. when the search string is exactly 13 characters (an EAN13-length barcode).', 'Only relevant when PRODUIT_ATTRIBUTES_HIDECHILD is enabled: setting this secondary constant allows a search string of exactly 13 characters to still match hidden variant/child products by EAN13, bypassing the child-hiding exclusion for that one case.', 'Truthy = allow child/variant products to appear in results when filterkey is exactly 13 chars long (EAN13 search); only meaningful combined with PRODUIT_ATTRIBUTES_HIDECHILD being set.', 0, 0, NULL, 1, '065b4dfc19bee5cfd402ab4b5f6e5d66c8ca278007c74859c08ed1f1b970705d', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:3757: if (getDolGlobalString(''PRODUIT_ATTRIBUTES_HIDECHILD'')) {", "core/class/html.form.class.php:3758: if (getDolGlobalString(''PRODUIT_ATTRIBUTES_HIDECHILD_BUT_ALLOW_SEARCH_IN_EAN13'')) {", "core/class/html.form.class.php:3759: if (strlen($filterkey) != 13) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_ATTRIBUTES_SEPARATOR', 'string', NULL, 'variants', 'Defines the separator character used between attribute value references when building product variant reference codes.', 'Written by variants/admin/admin.php:58 and read in variants/admin/admin.php:99 (defaulting to ''_'') and variants/class/ProductCombination.class.php:862 where it is appended between the base product ref and the attribute value ref.', 'Changing this value alters the separator character between attribute codes in automatically generated variant product references.', 'Any string; default ''_''.', 0, 0, 'variants/admin/admin.php|variants/admin/admin.php', 1, '5ca7a3ad7d23c8e11d6126107d7db55d1c13cedff310b94b3b37f7e91b864047', 'v2', '2026-04-21T11:16:15+00:00', '["variants/admin/admin.php:99|read|$separator = getDolGlobalString(''PRODUIT_ATTRIBUTES_SEPARATOR'', ''_'');", "variants/class/ProductCombination.class.php:862|read|$newproduct->ref .= getDolGlobalString(''PRODUIT_ATTRIBUTES_SEPARATOR'', ''_'') . $prodattrval->ref;", "variants/admin/admin.php:58|write|if (!dolibarr_set_const($db, ''PRODUIT_ATTRIBUTES_SEPARATOR'', GETPOST(''PRODUIT_ATTRIBUTES_SEPARATOR''), ''chaine'', 0, '''', $conf->entity)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_AUTOFILL_DESC', 'string', NULL, 'fourn', 'Controls whether the product description field is automatically filled from the product record when adding a line to a document.', 'Written via product/admin/product.php (line 166) and displayed as a selector (line 731). Checked across at least 12 files including supplier_proposal/card.php:886, fourn/commande/card.php:710, comm/propal/card.php:1560 (`if (getDolGlobalInt(''PRODUIT_AUTOFILL_DESC'') == 0)`). COMMENT: `@property {int} conf.PRODUIT_AUTOFILL_DESC`.', 'When set to 0, the description is not auto-filled from the product, allowing manual entry; other values enable automatic description filling.', 'Integer; 0 = do not auto-fill description; other values = auto-fill description from product record.', 0, 0, 'product/admin/product.php|product/admin/product.php', 1, '197fef139b9f123067b3936e019402701f4d92a3dbcb644a1d37ec5e70d66ae1', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:771  * @property {int} conf.PRODUIT_AUTOFILL_DESC", "supplier_proposal/card.php:886|check|if (getDolGlobalInt(''PRODUIT_AUTOFILL_DESC'') == 0) {", "fourn/commande/card.php:710|check|if (getDolGlobalInt(''PRODUIT_AUTOFILL_DESC'') == 0) {", "product/admin/product.php:166|write|$res = dolibarr_set_const($db, \"PRODUIT_AUTOFILL_DESC\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_CUSTOMER_PRICES', 'string', NULL, 'product', 'Enables per-customer specific prices for products, distinct from multiprices levels.', 'Set to 0 by product/admin/product.php:128 via dolibarr_set_const, and checked in product/admin/product.php:613, product/ajax/products.php, product/class/api_products.class.php, product/list.php, and societe/price.php.', 'When enabled, customer-specific price lookups (e.g. in product/ajax/products.php and societe/price.php) are activated alongside or instead of the multiprices system.', NULL, 0, 0, 'product/admin/product.php|product/admin/product.php', 1, 'e0d2d6c0602c2f710db757967908cd85f4a8b147cb454b7f1fe3899e30c38a32', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, ''PRODUIT_CUSTOMER_PRICES'', 0, ''chaine'', 0, '''', $conf->entity);", "if ((getDolGlobalString(''PRODUIT_CUSTOMER_PRICES'') || getDolGlobalString(''PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES'')) && !empty($socid)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES', 'string', NULL, 'product', 'Enables combined use of customer-specific prices together with multiprices levels.', 'Set to 0 by product/admin/product.php:129 via dolibarr_set_const, and checked alongside PRODUIT_MULTIPRICES and PRODUIT_CUSTOMER_PRICES_BY_QTY_MULTIPRICES in product/admin/product.php, product/ajax/products.php, product/list.php, and societe/price.php.', 'When enabled, price selection logic in product/ajax/products.php and related pages combines customer-price and multiprice-level behavior instead of treating them as mutually exclusive.', NULL, 0, 0, 'product/admin/product.php|product/admin/product.php|product/admin/product.php|product/admin/product.php', 1, '8d7c7f0a92b04d2e977e5de044904283f4f783e76484dffe915e3d594ffd7491', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, ''PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES'', 0, ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''PRODUIT_MULTIPRICES'') || getDolGlobalString(''PRODUIT_CUSTOMER_PRICES_BY_QTY_MULTIPRICES'') || getDolGlobalString(''PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES''))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_CUSTOMER_PRICES_BY_QTY', 'string', NULL, 'product', 'Enables quantity-based customer pricing for products.', 'Managed via product/admin/product.php (read and write). Checked across product/price.php, core/lib/ajax.lib.php, product/ajax/products.php, and line templates to activate quantity-tier price lookups. Comment at core/tpl/objectline_create.tpl.php:1251 notes it works only if the product combo is not AJAX-based.', 'Enabling this activates quantity-break price tables for products, affecting price resolution in proposals, orders, and invoices. Disabling it hides quantity-based pricing controls.', '0 or not set = disabled; any truthy string = enabled', 0, 0, 'product/admin/product.php|product/admin/product.php', 1, '9600d8b3892b216f0904cafccb7545961de371c2255181cf47a1d9ddd76af855', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/ajax.lib.php:222  // For customer price when PRODUIT_CUSTOMER_PRICES_BY_QTY is on", "core/tpl/objectline_create.tpl.php:1251  /* To process customer price per quantity (PRODUIT_CUSTOMER_PRICES_BY_QTY works only if combo product is not an ajax after x key pressed) */", "product/admin/product.php:130|write|$res = dolibarr_set_const($db, ''PRODUIT_CUSTOMER_PRICES_BY_QTY'', 0, ''chaine'', 0, '''', $conf->entity);", "product/admin/product.php:610|check|if (getDolGlobalString(''PRODUIT_CUSTOMER_PRICES_BY_QTY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_CUSTOMER_PRICES_BY_QTY_MULTIPRICES', 'string', NULL, 'product', 'Enables quantity-based pricing combined with multi-level price lists for products.', 'Written via product/admin/product.php:131 (reset to 0) and checked in 51+ locations including product/admin/product.php, societe/class/societe.class.php:2245, and product/ajax/products.php. Often tested alongside PRODUIT_MULTIPRICES and PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES to determine the active pricing mode. The JS comment at core/tpl/objectline_create.tpl.php:766 confirms the constant is exposed as a boolean config.', 'Enabling this constant activates a pricing mode that combines quantity-break prices with multi-level price lists; it is mutually exclusive with other pricing modes and is reset to 0 when conflicting modes are activated.', 'Any non-empty/non-zero value = enabled; ''0'' or empty = disabled', 0, 0, 'product/admin/product.php|product/admin/product.php|product/admin/product.php|product/admin/product.php', 1, 'bd6a3dc3d415e6f39022da6d656ca17c88e34839781a8df136bb3c488c831759', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:766  * @property {boolean} conf.PRODUIT_CUSTOMER_PRICES_BY_QTY_MULTIPRICES", "product/admin/product.php:131|write|$res = dolibarr_set_const($db, ''PRODUIT_CUSTOMER_PRICES_BY_QTY_MULTIPRICES'', 0, ''chaine'', 0, '''', $conf->entity);", "product/admin/product.php:628|check|if (getDolGlobalString(''PRODUIT_MULTIPRICES'') || getDolGlobalString(''PRODUIT_CUSTOMER_PRICES_BY_QTY_MULTIPRICES'') || getDolGlobalString(''PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES''))", "societe/class/societe.class.php:2245|check|if ((getDolGlobalString(''PRODUIT_MULTIPRICES'') || getDolGlobalString(''PRODUIT_CUSTOMER_PRICES_BY_QTY_MULTIPRICES'') || getDolGlobalString(''PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES''))"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_CUSTOMER_PRICES_PDF_REF_MODE', 'string', NULL, 'core', 'Controls how the customer-specific product reference is displayed on PDF lines when per-customer prices/refs are enabled.', 'Read in core/lib/pdf.lib.php:2166 as getDolGlobalInt(), used in a switch statement (lines ~2167-2178) only reached when PRODUIT_CUSTOMER_PRICES or PRODUIT_CUSTOMER_PRICES_AND_MULTIPRICES is enabled and a matching customer price with ref_customer exists.', 'Determines whether the customer''s own product reference replaces, is combined with, or is appended to the internal product reference on PDF lines.', '1 = show only customer ref_customer; 2 = customer ref_customer followed by ''(InternalRef ref_prodserv)''; default/other = internal ref followed by ''(RefCustomer ref_customer)''', 1, 0, NULL, 1, '355e87eec0158abade381a84f21c5d79cf8287612f5aa9c48a40b27118c09542', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:2166|read|$idcustprice = getDolGlobalInt(''PRODUIT_CUSTOMER_PRICES_PDF_REF_MODE'');", "core/lib/pdf.lib.php:2168: case 1: $ref_prodserv = $productCustomerPrice->ref_customer; break;", "core/lib/pdf.lib.php:2172: case 2: $ref_prodserv = $productCustomerPrice->ref_customer . '' ('' . ... ''InternalRef'' ... '')''; break;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_DEFAULT_BARCODE_TYPE', 'string', NULL, 'product', 'Stores the default barcode type (format) used when generating barcodes for products.', 'Written by admin/barcode.php:97 and displayed as a selector at admin/barcode.php:537. Read in core/modules/barcode/mod_barcode_product_standard.php:192 to determine the barcode type for automatic numbering, and consulted in barcode/printsheet.php:130 and product/card.php:1619 when no explicit type is set on the record.', 'Setting this value changes the barcode format applied to products when no per-product override exists; clearing it disables the default.', 'Stores a barcode type ID (integer as string) referencing the selected format; empty = no default.', 0, 0, 'admin/barcode.php|admin/barcode.php', 1, '78ecabd7576941fd8548708bed363c447c79b75f4f09a547f922eae2aabe1bc0', 'v2', '2026-04-21T11:16:15+00:00', '["admin/barcode.php:97|write|$res = dolibarr_set_const($db, \"PRODUIT_DEFAULT_BARCODE_TYPE\", $coder_id, ''chaine'', 0, '''', $conf->entity);", "core/modules/barcode/mod_barcode_product_standard.php:192|read|$type = getDolGlobalString(''PRODUIT_DEFAULT_BARCODE_TYPE'');", "barcode/printsheet.php:130|check|if (empty($fk_barcode_type) && getDolGlobalString(''PRODUIT_DEFAULT_BARCODE_TYPE'')) {", "product/card.php:1619|check|if (empty($fk_barcode_type) && getDolGlobalString(''PRODUIT_DEFAULT_BARCODE_TYPE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_DESC_IN_FORM', 'string', NULL, 'core', 'Controls whether and how product descriptions are displayed in document line-item forms.', 'Written by product/admin/product.php:154 and read as an integer in multiple files including main.inc.php:1260, contrat/card.php:1716, and core/tpl/objectline_view.tpl.php:190. The value is also mirrored to PRODUIT_DESC_IN_FORM_ACCORDING_TO_DEVICE in core/class/conf.class.php:1048.', 'Changing this value alters whether product descriptions appear inline on forms such as contract lines and order lines.', '0 = description not shown; 1 = description shown in form', 0, 0, 'product/admin/product.php|product/admin/product.php', 1, 'efa7d705fa5509da05ed15dac0d1c8b122e280efed1e18676b97dc286fddb428', 'v2', '2026-04-21T11:16:15+00:00', '["product/admin/product.php:154|write|$res = dolibarr_set_const($db, \"PRODUIT_DESC_IN_FORM\", $value, ''chaine'', 0, '''', $conf->entity);", "main.inc.php:1260|check|if (getDolGlobalInt(''PRODUIT_DESC_IN_FORM'') == 1) {", "contrat/card.php:1716|check|if (!getDolGlobalInt(''PRODUIT_DESC_IN_FORM'')) {", "core/tpl/objectline_view.tpl.php:190|check|if (!getDolGlobalInt(''PRODUIT_DESC_IN_FORM'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_DESC_IN_FORM_ACCORDING_TO_DEVICE', 'string', NULL, 'core', 'Adapts how product/service descriptions are shown in forms depending on the device (e.g. browser detection).', 'Referenced from admin/fckeditor.php:109 and checked with getDolGlobalInt in reception/card.php, societe/consumption.php, delivery/card.php, contrat/card.php, and contact/consumption.php. core/class/conf.class.php:1051 sets it automatically (''may be modified later according to browser'').', 'When enabled, product description fields in reception, delivery, contract, and consumption pages render differently based on device/browser detection performed by the core conf class.', NULL, 0, 0, 'admin/fckeditor.php', 1, '2afbf9f1fb508ada179ec725b3e40c02e5ca24dfcc23c8a29c84a3dc0ade7749', 'v2', '2026-07-24T06:41:12+00:00', '["// Set PRODUIT_DESC_IN_FORM_ACCORDING_TO_DEVICE, may be modified later according to browser", "if ($const == ''PRODUCTDESC'' && getDolGlobalInt(''PRODUIT_DESC_IN_FORM_ACCORDING_TO_DEVICE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_FOURN_TEXTS', 'string', NULL, 'product', 'Enables use of supplier-specific product descriptions on supplier documents instead of the standard product description.', 'Written via product/admin/product.php (line 170). Checked across 8 files including supplier_proposal/card.php:882 (`if (!empty($productsupplier->desc_supplier) && getDolGlobalString(''PRODUIT_FOURN_TEXTS''))`), fourn/commande/card.php:706, fourn/facture/card.php:1775, and core/class/html.form.class.php (lines 4030, 4090).', 'Enabling this setting causes supplier-specific descriptions to replace standard product descriptions on supplier proposals, orders, and invoices.', 'Truthy string (non-empty) = use supplier description when available; empty/not set = always use standard product description.', 0, 0, 'product/admin/product.php', 1, '3c02578027e06dbb85d06b818a52163337fe1a7dc90965b9763b6ff3a41a6340', 'v2', '2026-04-21T11:16:15+00:00', '["supplier_proposal/card.php:882|check|if (!empty($productsupplier->desc_supplier) && getDolGlobalString(''PRODUIT_FOURN_TEXTS'')) {", "fourn/commande/card.php:706|check|if (!empty($productsupplier->desc_supplier) && getDolGlobalString(''PRODUIT_FOURN_TEXTS'')) {", "fourn/facture/card.php:1775|check|if (!empty($productsupplier->desc_supplier) && getDolGlobalString(''PRODUIT_FOURN_TEXTS'')) {", "product/admin/product.php:170|write|$res = dolibarr_set_const($db, \"PRODUIT_FOURN_TEXTS\", $value, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_LIMIT_SIZE', 'string', NULL, 'product', 'Sets the maximum number of products returned in product selection dropdowns.', 'Defines the numeric limit passed to select_produits() and select_produits_list() calls across line-creation templates and Ajax product search. Default value of 1000 is set in core/class/conf.class.php when the constant is not defined. Configured via product/admin/product.php.', 'Reducing this value limits the number of products loaded in selectors, which can improve performance on large catalogues. Setting it to 0 or a non-positive value bypasses the limit in stock transfer views.', 'Positive integer = maximum products returned (default 1000); 0 or negative = no cap applied in some contexts', 0, 0, 'product/admin/product.php|product/admin/product.php', 1, 'dddfa705965ec9577580134037f66afeaa307616ef5e296f9c4772bdabde920c', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/conf.class.php:1042  // Set PRODUIT_LIMIT_SIZE if never defined", "product/admin/product.php:719|read|print ''<td class=\"right\"><input size=\"3\" type=\"text\" class=\"flat\" name=\"value_PRODUIT_LIMIT_SIZE\" value=\"'' . getDolGlobalString(''PRODUIT_LIMIT_SIZE'', 1000).''\">''", "product/stock/massstockmove.php:700|check|if (getDolGlobalInt(''PRODUIT_LIMIT_SIZE'') <= 0) {", "product/ajax/products.php:339|read|$arrayresult = $form->select_produits_list(0, $htmlname, $type, getDolGlobalInt(''PRODUIT_LIMIT_SIZE'', 1000), ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_MULTIPRICES', 'string', NULL, 'product', 'Enables multiple price levels (segments) per product/service.', 'Set to 0 by product/admin/product.php:127 via dolibarr_set_const, and checked extensively in product/admin/product.php, product/ajax/products.php, variants/combinations.php, and variants/class/ProductCombination.class.php.', 'When set, price is treated as an array per price level/segment: ProductCombination.class.php notes price variation values become arrays ''if global constant PRODUIT_MULTIPRICES is on'', affecting product combination price impact calculations.', NULL, 0, 0, 'product/admin/product.php|product/admin/product.php|product/admin/product.php|product/admin/product.php|product/admin/product.php', 1, 'd106276414d9cf918d406c6d02378c7f3548e415cbd378e4682d73c0ca1ceb81', 'v2', '2026-07-24T06:41:12+00:00', '["* if PRODUIT_MULTIPRICES is set (1 price per segment)", "(it is an array if global constant \"PRODUIT_MULTIPRICES\" is on)", "$res = dolibarr_set_const($db, ''PRODUIT_MULTIPRICES'', 0, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_MULTIPRICES_ALLOW_AUTOCALC_PRICELEVEL', 'bool', NULL, 'product', 'Allows automatic calculation of price levels when PRODUIT_MULTIPRICES is active.', 'Checked at core/lib/product.lib.php:402 together with PRODUIT_MULTIPRICES, and configured on a setup tab described in product/admin/price_rules.php:21 as shown only ''if option PRODUIT_MULTIPRICES_ALLOW_AUTOCALC_PRICELEVEL is set''.', 'When enabled together with PRODUIT_MULTIPRICES, price levels can be auto-calculated per the rules configured in product/admin/price_rules.php rather than entered manually.', NULL, 0, 0, NULL, 1, '36e6de9b97d0272319af064e624949e1f3b07ed39c05fd8a03e2548bfe7e3ee9', 'v2', '2026-07-24T06:41:12+00:00', '["* This page is a tab in the setup of module Product if option PRODUIT_MULTIPRICES_ALLOW_AUTOCALC_PRICELEVEL is set.", "if (getDolGlobalString(''PRODUIT_MULTIPRICES'') && getDolGlobalString(''PRODUIT_MULTIPRICES_ALLOW_AUTOCALC_PRICELEVEL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_MULTIPRICES_LIMIT', 'string', NULL, 'product', 'Sets the number of price levels available when the multi-price feature is enabled.', 'Written by product/admin/product.php:88 (auto-set to 5 when PRODUIT_MULTIPRICES is enabled without a limit) and :117 (user-defined value). Read in product/admin/price_rules.php:59 and :159 as $produit_multiprices_limit, and in product/price.php:95 where it is reset to 5 when not set.', 'Changing this value controls how many distinct price levels are available per product when multi-pricing is active.', 'Integer string; default 5 when auto-set. Represents the count of price levels.', 0, 0, 'product/admin/product.php|product/admin/product.php|product/admin/price_rules.php|product/admin/price_rules.php|product/admin/product.php|product/admin/product.php', 1, 'bb5ad597ec1e47163fb0c99cdcb8d9d29ad1eb8790f3bdde87d3902f5712e179', 'v2', '2026-04-21T11:16:15+00:00', '["product/admin/product.php:88|write|dolibarr_set_const($db, ''PRODUIT_MULTIPRICES_LIMIT'', 5, ''chaine'', 0, '''', $conf->entity);", "product/admin/product.php:117|write|$res = dolibarr_set_const($db, \"PRODUIT_MULTIPRICES_LIMIT\", GETPOST(''value_PRODUIT_MULTIPRICES_LIMIT''), ''chaine'', 0, '''', $conf->entity);", "product/admin/price_rules.php:59|read|$produit_multiprices_limit = getDolGlobalInt(''PRODUIT_MULTIPRICES_LIMIT'');", "* @param \tint \t$clean \t\tLevels of PRODUIT_MULTIPRICES_LIMIT"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_MULTIPRICES_USE_VAT_PER_LEVEL', 'bool', NULL, 'product', 'Enables per-price-level VAT rates when multi-price levels are active; kept for backward compatibility only.', 'Checked in product/price.php:1087 and product/price.php:1129 with the explicit comment ''using this option is a bug. kept for backward compatibility''. Also checked in comm/propal/class/propal.class.php:1536 and product/class/product.class.php:2443. Affects which VAT fields are stored per price level.', 'Enabling this activates a legacy behaviour where each multi-price level can carry its own VAT rate, which is documented in the code as a bug kept only for backward compatibility.', '0 or not set = single VAT rate across all price levels; 1 = per-level VAT (legacy/deprecated behavior)', 1, 0, NULL, 1, '83c08fe1a122ff54b4f6ca536bc357b1eb9dfa63b2f3bd18af46e715d1c94064', 'v2', '2026-04-21T11:16:15+00:00', '["product/price.php:1087|check|if (getDolGlobalString(''PRODUIT_MULTIPRICES_USE_VAT_PER_LEVEL'')) {  // using this option is a bug. kept for backward compatibility", "product/class/product.class.php:3195  // Next two fields are used only if PRODUIT_MULTIPRICES_USE_VAT_PER_LEVEL is on", "comm/propal/class/propal.class.php:1536|check|if (getDolGlobalString(''PRODUIT_MULTIPRICES_USE_VAT_PER_LEVEL'')) {  // using this option is a bug. kept for backward compatibility", "product/class/product.class.php:2443|check|if (getDolGlobalString(''PRODUIT_MULTIPRICES_USE_VAT_PER_LEVEL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_PDF_MERGE_PROPAL', 'string', NULL, 'product', 'When enabled, merges the product data sheet PDF into proposal (quote) PDF documents.', 'COMMENTS state: ''Kept as hidden feature only. PRODUIT_PDF_MERGE_PROPAL can be added manually. Still did not understand how this feature works.'' Written via product/admin/product.php:160 and read/checked in product/document.php:42/143/307 and core/modules/propale/doc/pdf_cyan.modules.php:967 and pdf_azur.modules.php:796.', 'Enabling this constant causes proposal PDF generation to append product data sheet PDFs; behavior is noted as a hidden feature that is not fully understood per the source comments.', '1 or any truthy value = merge product PDF into proposal PDF; 0 or unset = no merge.', 0, 0, 'product/admin/product.php|product/admin/product.php', 1, 'b81e4f77adf6026e1f6a11f4a350b2c9a8046cc2c8c3b8a58ad4491b9f64dab6', 'v2', '2026-04-21T13:29:58+00:00', '["/* Kept as hidden feature only. PRODUIT_PDF_MERGE_PROPAL can be added manually. Still did not understand how this feature works.", "product/admin/product.php:160|write|$res = dolibarr_set_const($db, \"PRODUIT_PDF_MERGE_PROPAL\", $value, ''chaine'', 0, '''', $conf->entity);", "core/modules/propale/doc/pdf_cyan.modules.php:967|check|if (getDolGlobalString(''PRODUIT_PDF_MERGE_PROPAL'')) {", "product/document.php:143|check|if (getDolGlobalString(''PRODUIT_PDF_MERGE_PROPAL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_RESTRICT_STOCK_INCDEC_IF_SUBPRODUCTS_ENABLED', 'bool', NULL, 'admin', 'When virtual/kit sub-products (PRODUIT_SOUSPRODUITS) are enabled, forces some stock increase/decrease trigger options (invoice validation, supplier invoice/order validation) to be disabled.', 'Read in the stock admin setup page (admin/stock.php:235), guarded by an inline comment saying the reason for this restriction is unclear (''Why this ? As i don''t see why, i comment this code by a hidden option'') and is only kept as a hidden option; only active if PRODUIT_SOUSPRODUITS is also enabled.', 'Enabling it removes BILL, VALIDATE_ORDER, SUPPLIER_BILL and SUPPLIER_VALIDATE_ORDER from the choices of stock-change triggers on the stock setup page (shipment-based options remain available).', 'Boolean-like: enabled = forces stock inc/dec to only trigger on shipment (not on bill/order validation) when sub-products are enabled.', 0, 0, 'admin/stock.php', 1, '8378f053e1618afe3501ca7b44f666a68f5d95071c418535df62b3510b90b889', 'v2', '2026-07-24T07:05:23+00:00', '["admin/stock.php:234: // Why this ? As i don''t see why, i comment this code by a hidden option", "admin/stock.php:235: if (getDolGlobalString(''PRODUIT_RESTRICT_STOCK_INCDEC_IF_SUBPRODUCTS_ENABLED'')) {", "admin/stock.php:236-242: $disableStockCalculateOn[] = ''BILL''; ... ''VALIDATE_ORDER''; ... ''SUPPLIER_BILL''; ... ''SUPPLIER_VALIDATE_ORDER'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_SOUSPRODUITS', 'string', NULL, 'expedition', 'Enables the sub-products (kits/bill-of-components) feature on products.', 'Referenced in admin/stock.php:232, product/admin/product.php (write code commented out at line 150-151), product/card.php:3125, mrp/class/mo.class.php, product/stock/class/mouvementstock.class.php, and compta/facture/class/facture.class.php.', 'When enabled, product cards show sub-product/kit management, and stock movement logic (mouvementstock.class.php) and invoice logic factor in the parent/child product relationship, unless further restricted by PRODUIT_SOUSPRODUITS_ALWAYS_DISABLE_CHILDREN_STOCK_MOVE.', NULL, 0, 0, 'admin/stock.php|product/admin/product.php', 1, '463ec55b6b487091a2f11b6664d60e70ff632701125f79f36a6abb2326954d04', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''PRODUIT_SOUSPRODUITS'')) {", "/*$value = GETPOST(''PRODUIT_SOUSPRODUITS'', ''alpha'');", "if (!$error && getDolGlobalString(''PRODUIT_SOUSPRODUITS'') && !getDolGlobalString(''PRODUIT_SOUSPRODUITS_ALWAYS_DISABLE_CHILDREN_STOCK_MOVE'') && empty($disablestockchangeforsubproduc"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_SOUSPRODUITS_ALSO_ENABLE_PARENT_STOCK_MOVE', 'bool', NULL, 'expedition', 'Also triggers stock movement on the parent (kit) product, not only its sub-products/children, when kits are used.', 'Checked with getDolGlobalInt across product/stock/class/mouvementstock.class.php, product/stock/product.php, expedition/class/expedition.class.php, and product/class/product.class.php.', 'When enabled, kit parent products get stock decremented/incremented in addition to their children; a code comment notes stock move for kit parents is normally disabled unless this constant is set.', NULL, 0, 0, NULL, 1, 'c857b37fe26ca577c571a06fe92d2fdeab74061aa4874218976747722abd5372', 'v2', '2026-07-24T06:41:12+00:00', '["if ($product->isStockManaged() && ($productChildrenNb == 0 || getDolGlobalInt(''PRODUIT_SOUSPRODUITS_ALSO_ENABLE_PARENT_STOCK_MOVE''))) { // For kit parent, we disable stock move, ex"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_SOUSPRODUITS_ALWAYS_DISABLE_CHILDREN_STOCK_MOVE', 'bool', NULL, 'product', 'When enabled, prevents stock movements on a kit/parent product from cascading down to create matching stock movements on its sub-products (children), even though sub-products (PRODUIT_SOUSPRODUITS) is enabled.', 'Checked in MouvementStock (product/stock/class/mouvementstock.class.php:672) as part of the condition guarding the recursive call to _createSubProduct() that propagates a parent''s stock movement to its children.', 'Enabling it disables the automatic recursive stock movement on sub-products whenever a movement is recorded on the parent kit product; without it (and with PRODUIT_SOUSPRODUITS on), children stock is updated recursively.', 'Boolean-like: enabled = do NOT propagate stock moves to sub-products; unset/0 = propagate (when PRODUIT_SOUSPRODUITS is enabled and $disablestockchangeforsubproduct is empty).', 0, 0, NULL, 1, 'd50aeb3e8cb8e5a78428e844f2546612351012ed1da49ccb19ab6b1fa34309db', 'v2', '2026-07-24T07:05:23+00:00', '["product/stock/class/mouvementstock.class.php:672: if (!$error && getDolGlobalString(''PRODUIT_SOUSPRODUITS'') && !getDolGlobalString(''PRODUIT_SOUSPRODUITS_ALWAYS_DISABLE_CHILDREN_STOCK_MOVE'') && empty($disablestockchangeforsubproduct)) {", "product/stock/class/mouvementstock.class.php:673: $error = $this->_createSubProduct($user, $fk_product, $entrepot_id, $qty, $type, 0, $label, $inventorycode, $datem);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_TEXTS_IN_THIRDPARTY_LANGUAGE', 'string', NULL, 'core', 'Enables display of product labels and descriptions in the language of the associated third party rather than the interface language.', 'Written via product/admin/product.php (line 157) and shown as a yes/no selector (line 782). Checked across at least 36 files in conjunction with `MAIN_MULTILANGS` (e.g. supplier_proposal/card.php:864: `if (getDolGlobalInt(''MAIN_MULTILANGS'') && getDolGlobalString(''PRODUIT_TEXTS_IN_THIRDPARTY_LANGUAGE''))`). COMMENT: `@property {boolean} conf.PRODUIT_TEXTS_IN_THIRDPARTY_LANGUAGE`.', 'Enabling this setting causes product texts to be fetched and displayed in the third party''s configured language when multilingual mode is active.', '0 or empty = product texts shown in interface language; 1 = product texts shown in third-party language (requires MAIN_MULTILANGS).', 0, 0, 'product/admin/product.php|product/admin/product.php', 1, '45a5bd7cf274bc40a1f4b5d6c0c82d7e4860d0898a1c038cb3f148bbfeb73769', 'v2', '2026-04-21T11:16:15+00:00', '["core/tpl/objectline_create.tpl.php:770  * @property {boolean} conf.PRODUIT_TEXTS_IN_THIRDPARTY_LANGUAGE", "supplier_proposal/card.php:864|check|if (getDolGlobalInt(''MAIN_MULTILANGS'') && getDolGlobalString(''PRODUIT_TEXTS_IN_THIRDPARTY_LANGUAGE'')) {", "product/admin/product.php:157|write|$res = dolibarr_set_const($db, \"PRODUIT_TEXTS_IN_THIRDPARTY_LANGUAGE\", $value, ''chaine'', 0, '''', $conf->entity);", "product/admin/product.php:782|read|print $form->selectyesno(\"activate_viewProdTextsInThirdpartyLanguage\", getDolGlobalInt(''PRODUIT_TEXTS_IN_THIRDPARTY_LANGUAGE''), 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PRODUIT_USE_SEARCH_TO_SELECT', 'bool', NULL, 'core', 'Controls whether an AJAX search-to-select widget is used instead of a dropdown list when selecting products/services.', 'Written via product/admin/product.php:163 and read/checked extensively across admin/system/perf.php, core/class/html.form.class.php (lines 2835, 2951, 3451, 3961), and product/admin/product.php:711. The perf page displays recommendations based on the product count and this setting.', 'Enabling this constant replaces the full product dropdown with an AJAX autocomplete field, which is strongly recommended for large product catalogs to avoid performance issues.', 'Integer value: 0 = dropdown list; 1 = search-to-select with AJAX (threshold-based); higher values adjust search behavior. Configured via product admin UI.', 0, 0, 'product/admin/product.php|admin/system/perf.php|admin/system/perf.php|product/admin/product.php', 1, '33936d44885942c7b434573ba11d21d1a4ced8ec9f160957b09aea5934a6da2f', 'v2', '2026-04-21T13:29:58+00:00', '["admin/system/perf.php:544|check|if (!getDolGlobalString(''PRODUIT_USE_SEARCH_TO_SELECT'')) {", "product/admin/product.php:163|write|$res = dolibarr_set_const($db, \"PRODUIT_USE_SEARCH_TO_SELECT\", $value, ''chaine'', 0, '''', $conf->entity);", "core/class/html.form.class.php:2835|check|if (!empty($conf->use_javascript_ajax) && getDolGlobalString(''PRODUIT_USE_SEARCH_TO_SELECT'')) {", "core/class/html.form.class.php:2951|read|$out .= ajax_autocompleter((string) $selected, $htmlname, DOL_URL_ROOT . ''/product/ajax/products.php'', $urloption, getDolGlobalInt(''PRODUIT_USE_SEARCH_TO_SELECT''), getDolGlobalInt("]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROFORMA_PDF_WITH_SUFFIX', 'string', NULL, 'core', 'Stores a suffix string appended to the filename of proforma PDF documents generated from orders.', 'Checked in core/modules/commande/doc/pdf_einstein.modules.php:227-228. When the requested model is ''proforma'' and this constant is set, its value is used as the $suffix variable for the generated PDF filename.', 'Setting a non-empty value causes proforma PDFs to include the specified suffix in their filename. Clearing it results in no suffix being added.', 'Any non-empty string = suffix appended to proforma PDF filename; empty/unset = no suffix.', 1, 0, NULL, 1, 'c2b5212779eccd5ac836b23c982a37258e8f30625614cb6a146b82b71ea2837d', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_einstein.modules.php:227|if (getDolGlobalString(''PROFORMA_PDF_WITH_SUFFIX'')) {", "pdf_einstein.modules.php:228|$suffix = (GETPOST(''model'') == ''proforma'') ? getDolGlobalString(''PROFORMA_PDF_WITH_SUFFIX'') : '''';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ADDON', 'string', NULL, 'projet', 'Selects the numbering module used to generate project reference numbers.', 'Written by projet/admin/project.php:229 and used in 9 locations. projet/class/project.class.php:1796 and projet/card.php:683 load the module name with default ''mod_project_simple''. emailcollector/class/emailcollector.class.php:3514 and projet/class/api_projects.class.php:355 also read it for ref generation.', 'Changing this value switches the project reference numbering algorithm to the specified module; using an invalid module name prevents reference generation.', 'Module class name string, e.g. ''mod_project_simple''; default ''mod_project_simple''.', 0, 0, 'projet/admin/project.php|projet/admin/project.php', 1, '4ffe6a8117b8287e5fb3e9f1fcf8bb7d7188a0323f2d420abe2d64a48d749653', 'v2', '2026-04-21T11:16:15+00:00', '["projet/admin/project.php:229|write|dolibarr_set_const($db, \"PROJECT_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "projet/class/project.class.php:1796|read|$obj = getDolGlobalString(''PROJECT_ADDON'', ''mod_project_simple'');", "projet/card.php:683|read|$modele = getDolGlobalString(''PROJECT_ADDON'', ''mod_project_simple'');", "core/modules/modProjet.class.php:323|read|''class'' => getDolGlobalString(''PROJECT_ADDON'', ''mod_project_simple''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ADDON_PDF', 'string', NULL, 'projet', 'Selects the PDF document generation template used for project documents.', 'A comment at projet/class/project.class.php:2106 states ''Create an intervention document on disk using template defined into PROJECT_ADDON_PDF''. Written by projet/admin/project.php:200 (set) and :188/:209 (delete). Read in projet/class/project.class.php:2126-2127 to load the PDF model; core/tpl/card_presend.tpl.php:130 disables PDF sending when no template is set.', 'Setting this constant designates the PDF template for project document generation; clearing it disables PDF generation for projects.', 'PDF template name string; empty = no PDF template selected.', 0, 0, 'projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php', 1, '89b266f6995a3d65b2be850a23c5ee8be091fa5566347dea22c201e7a7760c65', 'v2', '2026-04-21T11:16:15+00:00', '["*  Create an intervention document on disk using template defined into PROJECT_ADDON_PDF", "projet/admin/project.php:200|write|dolibarr_set_const($db, \"PROJECT_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity);", "projet/class/project.class.php:2126|read|} elseif (getDolGlobalString(''PROJECT_ADDON_PDF'')) {", "core/tpl/card_presend.tpl.php:130|check|if ($object->element == ''project'' && !getDolGlobalString(''PROJECT_ADDON_PDF'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies the directory path(s) for ODT document templates used by the generic project ODT module.', 'Read in doc_generic_project_odt.modules.php at line 413 (split into list of dirs), line 440 (display in UI), and line 448 (existence check). No admin UI write via dolibarr_set_const is present in the payload.', 'Changing this path redirects the module to a different set of ODT template directories; an invalid path disables ODT template loading.', 'Comma-separated directory path(s); empty = no custom ODT path.', 1, 0, NULL, 1, 'f2f828bcdb9fc32d0398fa60f313a55df10dac97237f39d9366810c427c32d77', 'v2', '2026-04-21T13:50:40+00:00', '["doc_generic_project_odt.modules.php:413|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''PROJECT_ADDON_PDF_ODT_PATH''))));", "doc_generic_project_odt.modules.php:440|read|$texte .= getDolGlobalString(''PROJECT_ADDON_PDF_ODT_PATH'');", "doc_generic_project_odt.modules.php:448|check|if (getDolGlobalString(''PROJECT_ADDON_PDF_ODT_PATH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ADD_SUBTOTAL_LINES', 'string', NULL, 'projet', 'Enables grouping by customer/supplier with a sub-total when listing supplier invoices/orders linked to a project.', 'Read in projet/element.php inside function canApplySubtotalOn($tablename), which returns false immediately if the constant is not set, else allows sub-totals for tables ''facture_fourn'' and ''commande_fournisseur''.', 'When enabled, the project element list applies a group-by with sub-total lines restricted to supplier invoices and supplier orders; when disabled, no sub-totaling is applied.', 'Boolean-like: truthy enables sub-total grouping for facture_fourn/commande_fournisseur tables only.', 1, 0, NULL, 1, '0861a28e7f395fef2a82b876819a25d92ae6e400693f2901c490a0e09c7f40cf', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php: if (!getDolGlobalString(''PROJECT_ADD_SUBTOTAL_LINES'')) { return false; }", "projet/element.php: return in_array($tablename, array(''facture_fourn'', ''commande_fournisseur''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ALLOW_COMMENT_ON_PROJECT', 'bool', NULL, 'projet', 'Enables the comments section on project-level pages when set to a truthy value.', 'When enabled, the project card and task sub-pages fetch and display comments on the project object itself. Checked at core/lib/project.lib.php:331 and projet/contact.php:333 among 27 total occurrences. Several occurrences are commented-out, indicating the feature was partially rolled back in some modules.', 'When disabled, no comment blocks are shown on project-level views. When enabled, comments are loaded and displayed for the project object across task sub-pages.', 'Truthy value (non-empty string) = project comments shown; empty/unset = project comments hidden.', 1, 0, NULL, 1, 'b7024384cd87f0db4f4867a42ae5897d2122ccf5ba24be44fffaff2ed5cca333', 'v2', '2026-04-21T11:16:15+00:00', '["projet/contact.php:333|check|if (getDolGlobalString(''PROJECT_ALLOW_COMMENT_ON_PROJECT'') && empty($object->comments)) {", "core/lib/project.lib.php:331|check|if (getDolGlobalString(''PROJECT_ALLOW_COMMENT_ON_PROJECT'')) {", "projet/tasks/task.php:324|check|if (getDolGlobalString(''PROJECT_ALLOW_COMMENT_ON_PROJECT'') && method_exists($projectstatic, ''fetchComments'') && empty($projectstatic->comments)) {", "// if (getDolGlobalString(''PROJECT_ALLOW_COMMENT_ON_PROJECT'') && method_exists($object, ''fetchComments'') && empty($object->comments)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ALLOW_COMMENT_ON_TASK', 'bool', NULL, 'projet', 'Enables the comments section on project task pages when set to a truthy value.', 'When enabled, task sub-pages (task.php, contact.php, time.php, note.php, document.php) fetch and display comments on tasks. Checked at core/lib/project.lib.php:481 and across multiple projet/tasks/ pages.', 'When disabled (or not set), the comments section is not rendered on any task sub-page. When enabled, comment blocks appear on all task-related views.', 'Truthy value (non-empty string) = comments shown; empty/unset = comments hidden.', 1, 0, NULL, 1, 'f27231265022a5ad343882dbecd7139879c3815645a5a88b06347a4cc93bdfee', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/project.lib.php:481|check|if (getDolGlobalString(''PROJECT_ALLOW_COMMENT_ON_TASK'')) {", "projet/tasks/task.php:320|check|if (getDolGlobalString(''PROJECT_ALLOW_COMMENT_ON_TASK'') && empty($object->comments)) {", "projet/tasks/time.php:946|check|if (getDolGlobalString(''PROJECT_ALLOW_COMMENT_ON_TASK'') && empty($object->comments)) {", "projet/tasks/note.php:65|check|if (getDolGlobalString(''PROJECT_ALLOW_COMMENT_ON_TASK'') && method_exists($object, ''fetchComments'') && empty($object->comments)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ALLOW_SPLIT_TIMESPENT', 'bool', NULL, 'projet', 'Shows a ''split'' action icon on each time-spent line of a project task, allowing a time entry to be split.', 'Checked in projet/tasks/time.php at lines 2220 and 2608, inside the per-line action-column rendering; when true, a link with img_split() and action=splitline is printed next to the edit/delete icons for that time-spent line.', 'Enabling it adds a split-line action button to time-spent entries, letting users divide a single recorded time entry (e.g. into two lines); no other behavior is documented.', 'Boolean-like: any truthy value shows the split-timespent action icon.', 1, 0, NULL, 1, 'de1f7108cc082e07c5403bb60214789dc450710086fe876f875d77998935a395', 'v2', '2026-07-24T07:05:23+00:00', '["projet/tasks/time.php:2220: if (getDolGlobalString(''PROJECT_ALLOW_SPLIT_TIMESPENT'')) {", "projet/tasks/time.php:2608: if (getDolGlobalString(''PROJECT_ALLOW_SPLIT_TIMESPENT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ALLOW_TO_LINK_FROM_OTHER_COMPANY', 'bool', NULL, 'core', 'Controls which third-party companies'' projects can be linked to a document — empty means only the document''s own third-party, ''all'' means all companies, or a comma-separated list of third-party IDs.', 'When empty, only projects belonging to the document''s third-party are shown. When set to ''all'' or a list of IDs, cross-company project linking is permitted. Logic in core/class/html.formprojet.class.php:198 reads: ''PROJECT_ALLOW_TO_LINK_FROM_OTHER_COMPANY is "all" or a list of ids separated by coma''. Written via projet/admin/project.php:244 with comment ''Allow to disable this configuration if empty value''.', 'Setting to ''all'' enables linking projects from any third-party; setting to a comma-separated list of IDs restricts linking to those specific third parties; leaving empty restricts linking to the document''s own third-party.', 'Empty = only document''s own third-party projects shown; ''all'' = all companies'' projects available; comma-separated integer IDs = projects from those specific third-party IDs are also available.', 0, 0, 'projet/admin/project.php|projet/admin/project.php', 1, 'b188095fa3b5a7eb082a2e2f418ed2a339d144faefde47ac7daacd4cdc3b1358', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.formprojet.class.php:198|read|} elseif (getDolGlobalString(''PROJECT_ALLOW_TO_LINK_FROM_OTHER_COMPANY'') != ''all'') {    // PROJECT_ALLOW_TO_LINK_FROM_OTHER_COMPANY is ''all'' or a list of ids separated by coma.", "projet/admin/project.php:244|write|dolibarr_set_const($db, ''PROJECT_ALLOW_TO_LINK_FROM_OTHER_COMPANY'', $projectToSelect, ''chaine'', 0, '''', $conf->entity); //Allow to disable this configuration if empty value", "core/class/html.formprojet.class.php:196|check|if (!getDolGlobalString(''PROJECT_ALLOW_TO_LINK_FROM_OTHER_COMPANY'')) {", "core/class/html.formprojet.class.php:259|read|} elseif (!getDolGlobalString(''PROJECT_ALLOW_TO_LINK_FROM_OTHER_COMPANY'') && $socid > 0 && (!empty($obj->fk_soc) && $obj->fk_soc != $socid)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ALWAYS_DISCARD_CLOSED_PROJECTS_IN_SELECT', 'string', NULL, 'core', 'Forces the project select list to always exclude closed projects.', 'Read in core/class/html.formprojet.class.php:175 inside the select_projects()-style project combo builder, right next to the PROJECT_HIDE_UNSELECTABLES check; when set it forces $discard_closed = 1 so closed projects are dropped from the SQL result before the list is built.', 'Enabling it removes closed projects from project selection dropdowns everywhere this combo is used, regardless of the caller''s own discard_closed argument.', 'Boolean-like: any truthy value forces discard of closed projects in the select.', 1, 0, NULL, 1, '4f3fce440f5e394b38ef6df2a56e414bec7c41852c376ba0f42d667d8828e053', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formprojet.class.php:175|check|if (getDolGlobalInt(''PROJECT_ALWAYS_DISCARD_CLOSED_PROJECTS_IN_SELECT'')) {", "if (getDolGlobalInt(''PROJECT_ALWAYS_DISCARD_CLOSED_PROJECTS_IN_SELECT'')) { $discard_closed = 1; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_BILL_TIME_SPENT', 'string', NULL, 'projet', 'Enables billing of time spent on project tasks, showing invoicing-related columns and actions.', 'When set alongside PROJECT_HIDE_TASKS being unset, time-tracking pages (projet/tasks/time.php, task.php, contact.php, note.php) display invoicing columns and actions for time entries. Referenced in at least 24 occurrences across the projet module.', 'Without this constant set, billing columns and actions for time entries are not displayed. Enabling it activates time-invoicing workflows on task pages.', 'Truthy value (non-empty string) = billing of time spent enabled; empty/unset = billing disabled.', 1, 0, NULL, 1, '5b2010a2592de6508842cf523a5d48ddb142c21caa5fa0b3f15a263b9a94ebcd', 'v2', '2026-04-21T11:16:15+00:00', '["projet/tasks/time.php:1890|check|if (!getDolGlobalString(''PROJECT_HIDE_TASKS'') && getDolGlobalString(''PROJECT_BILL_TIME_SPENT'')) {", "projet/tasks/task.php:388|check|if (!getDolGlobalString(''PROJECT_HIDE_TASKS'') && getDolGlobalString(''PROJECT_BILL_TIME_SPENT'')) {", "projet/tasks/contact.php:257|check|if (!getDolGlobalString(''PROJECT_HIDE_TASKS'') && getDolGlobalString(''PROJECT_BILL_TIME_SPENT'')) {", "projet/tasks/note.php:195|check|if (!getDolGlobalString(''PROJECT_HIDE_TASKS'') && getDolGlobalString(''PROJECT_BILL_TIME_SPENT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_CAN_ALWAYS_LINK_TO_ALL_CUSTOMERS', 'string', NULL, 'compta', 'When enabled, allows a project to be linked to any customer when selecting it on invoices, proposals, and orders, regardless of the current third-party context.', 'Checked in compta/facture/card.php:4571, comm/propal/card.php:2537, and commande/card.php:2456 in the project selector call. Without this constant, the project list is filtered to the current third-party.', 'Enabling this constant removes the third-party filter from the project selector on invoice, proposal, and order forms.', '0 or unset = project selector filtered to current third-party; truthy = all projects shown regardless of third-party.', 1, 0, NULL, 1, '9a263a840e5d5c9700334d85c48b7961227794dfd24f4dcee448157aad02207a', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:4571|read|print $formproject->select_projects((($socid > 0 && !getDolGlobalString(''PROJECT_CAN_ALWAYS_LINK_TO_ALL_CUSTOMERS'')) ? $socid : -1), (string) $projectid, ''projectid'', 0, 0, 1, 1, 0", "comm/propal/card.php:2537|read|print img_picto('''', ''project'', ''class=\"pictofixedwidth\"'').$formproject->select_projects((($soc->id > 0 && !getDolGlobalString(''PROJECT_CAN_ALWAYS_LINK_TO_ALL_CUSTOMERS'')) ? $soc->i", "commande/card.php:2456|read|print img_picto('''', ''project'', ''class=\"pictofixedwidth\"'').$formproject->select_projects((($soc->id > 0  && !getDolGlobalString(''PROJECT_CAN_ALWAYS_LINK_TO_ALL_CUSTOMERS'')) ? $soc->"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_CAN_ALWAYS_LINK_TO_ALL_SUPPLIERS', 'string', NULL, 'fourn', 'Allows linking a project to any supplier/thirdparty rather than restricting the choice to the project''s own thirdparty.', 'Checked with getDolGlobalString in projet/card.php (lines 848, 1263), reception/dispatch.php, reception/card.php, reception/note.php, reception/document.php, reception/contact.php, and supplier_proposal/info.php, controlling the socid filter passed to form_project/select_projects.', 'When enabled, project selection widgets in reception and supplier proposal pages pass -1 (no restriction) instead of the object''s socid, allowing selection of projects tied to any thirdparty.', NULL, 0, 0, NULL, 1, '92d2a2e445637502b8d153a8b37c20697690faae6160e8e8ca5bb45d0e8d4d44', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''PROJECT_CAN_ALWAYS_LINK_TO_ALL_SUPPLIERS'') && empty($conf->dol_use_jmobile)) {", "(getDolGlobalString(''PROJECT_CAN_ALWAYS_LINK_TO_ALL_SUPPLIERS'') ? $object->socid : -1)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_CAN_OVERWRITE_TIMESTPENT_HOURLY_RATE_WITH_LASTONE', 'string', NULL, 'projet', 'Shows a link on project time-spent lines letting the user overwrite the hourly rate with the last used rate.', 'Used in projet/element.php:1808 and :1876 in the display of the time-spent list for a project/task, guarding a link that triggers action=updateallwithlasthourlyrate.', 'When set, an extra icon/link is shown on each time-spent line allowing bulk overwrite of the hourly rate with the last one used; when unset the link is hidden.', 'Boolean-like: any truthy value enables the feature (checked with getDolGlobalString, no explicit accepted values documented in code).', 1, 0, NULL, 1, 'e463a2cfbc30f1d11634743e3047a0b7fd2d55869295f987d2a932c80b384e1f', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:1808|check|if (getDolGlobalString(''PROJECT_CAN_OVERWRITE_TIMESTPENT_HOURLY_RATE_WITH_LASTONE'')) {", "projet/element.php:1876|check|if (getDolGlobalString(''PROJECT_CAN_OVERWRITE_TIMESTPENT_HOURLY_RATE_WITH_LASTONE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_CLASSIFY_CLOSED_WHEN_ALL_TASKS_DONE', 'string', NULL, 'projet', 'Automatically closes a validated project once all of its tasks reach 100% progress.', 'Checked in projet/class/task.class.php:717, right after a task update, triggering logic that fetches the parent project and, if it is Project::STATUS_VALIDATED, checks whether all task lines are completed (array_reduce over $project->lines).', 'Enabling this makes project status change automatically to closed as soon as the last remaining task of a validated project is marked 100% done, without manual intervention.', 'Boolean-like (getDolGlobalString): non-empty enables auto-closing of the project when all tasks are done; empty/unset (default) leaves the project open until manually closed.', 1, 0, NULL, 1, '02e6cc26fef1df877410142be9eb3acdaa23e2114e88b991c7bfb360f84e2ee7', 'v2', '2026-07-24T07:05:23+00:00', '["projet/class/task.class.php:717: if (!$error && getDolGlobalString(''PROJECT_CLASSIFY_CLOSED_WHEN_ALL_TASKS_DONE'')) {", "projet/class/task.class.php: // Close the parent project if it is open (validated) and its tasks are 100% completed"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_CREATE_NO_DRAFT', 'string', NULL, 'projet', 'When set, newly created projects skip the draft status and are created directly as validated.', 'In projet/card.php:215, during project creation, if getDolGlobalString(''PROJECT_CREATE_NO_DRAFT'') is true and there is no error, $status is set to Project::STATUS_VALIDATED instead of the default draft status.', 'Enabling it removes the draft step for new projects, creating them already validated.', 'Boolean-like truthy check via getDolGlobalString().', 1, 0, NULL, 1, '640ce8f0caf52a1822e6bcee02ff5e743e58767b6ce66dc89be92c3d77ba03e4', 'v2', '2026-07-24T07:05:23+00:00', '["projet/card.php:215: if (getDolGlobalString(''PROJECT_CREATE_NO_DRAFT'') && !$error) {", "projet/card.php: // Create with status validated immediately"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_CREATE_ON_OVERVIEW_DISABLED', 'bool', NULL, 'projet', 'Hides the ''create new element'' shortcut button/link on the project overview page for a given linkable element type.', 'In projet/element.php:1271: `if (!getDolGlobalString(''PROJECT_CREATE_ON_OVERVIEW_DISABLED'') && $urlnew) { $addform .= ''<div class="inline-block valignmiddle">''; ... ''<a class="buttonxxx ...'' ... }`.', 'When enabled, the create-new-element button (e.g. quick-create links for invoices, orders, etc.) is not added to the project overview, even if a create URL ($urlnew) would otherwise be available.', 'Boolean: truthy disables the create-new-element button on the project overview.', 1, 0, NULL, 1, '21d599548c04d5a50d66c27f034810c12b4787fa4999d0e8ad4868030353206d', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:1271|check|if (!getDolGlobalString(''PROJECT_CREATE_ON_OVERVIEW_DISABLED'') && $urlnew) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_DEFAULT_OPPORTUNITY_STATUS_FOR_ONLINE_LEAD', 'string', NULL, 'projet', 'Sets the default opportunity status assigned to projects created via the public online lead form.', 'Written via projet/admin/website.php:80 and read in both projet/admin/website.php:51 and public/project/new.php:185 to pre-set the opportunity status on new leads.', 'Changing this value alters the initial opportunity status applied to projects submitted through the public lead form.', 'Integer: ID of an opportunity status. Empty = no default status pre-assigned.', 0, 0, 'projet/admin/website.php|projet/admin/website.php', 1, '22d1d39a7aee742769e8cfe1b949e5eb30e2046c1efd43d3f3685846201f2932', 'v2', '2026-04-21T11:16:15+00:00', '["projet/admin/website.php:80|write|$res = dolibarr_set_const($db, \"PROJECT_DEFAULT_OPPORTUNITY_STATUS_FOR_ONLINE_LEAD\", $defaultoppstatus, ''chaine'', 0, '''', $conf->entity);", "projet/admin/website.php:51|read|$defaultoppstatus = getDolGlobalInt(''PROJECT_DEFAULT_OPPORTUNITY_STATUS_FOR_ONLINE_LEAD'');", "public/project/new.php:185|read|$defaultoppstatus = getDolGlobalInt(''PROJECT_DEFAULT_OPPORTUNITY_STATUS_FOR_ONLINE_LEAD'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_DISABLE_PRIVATE_PROJECT', 'bool', NULL, 'projet', 'Hides the ''Private project'' visibility option from the project creation/edit form.', 'In projet/card.php:941 and :1356, the visibility selector only adds the ''PrivateProject'' option to the array if !getDolGlobalString(''PROJECT_DISABLE_PRIVATE_PROJECT'').', 'Enabling it removes the private-visibility choice from the UI, so users can no longer select/see ''private project'' as an option (works together with PROJECT_DISABLE_PUBLIC_PROJECT).', 'Boolean-like truthy check via getDolGlobalString().', 1, 0, NULL, 1, '6b3ddcc6fa793b8001a39fb9b749da1002d89d13a12737ba2dffcecd88f9114b', 'v2', '2026-07-24T07:05:23+00:00', '["projet/card.php:941: if (!getDolGlobalString(''PROJECT_DISABLE_PRIVATE_PROJECT'')) { $array[0] = $langs->trans(\"PrivateProject\"); }", "projet/card.php:1356: if (!getDolGlobalString(''PROJECT_DISABLE_PRIVATE_PROJECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_DISABLE_PUBLIC_PROJECT', 'bool', NULL, 'projet', 'Hides the ''Shared/public project'' visibility option from the project creation/edit form.', 'In projet/card.php:944 and :1359, the visibility selector only adds the ''SharedProject'' option to the array if !getDolGlobalString(''PROJECT_DISABLE_PUBLIC_PROJECT'').', 'Enabling it removes the shared/public-visibility choice from the UI (works together with PROJECT_DISABLE_PRIVATE_PROJECT); if both are set, the visibility selector is not shown at all.', 'Boolean-like truthy check via getDolGlobalString().', 1, 0, NULL, 1, 'ae86e615b3eedefec1d16d47259fe30027f80149b687d5880eac71c7ac869bf8', 'v2', '2026-07-24T07:05:23+00:00', '["projet/card.php:944: if (!getDolGlobalString(''PROJECT_DISABLE_PUBLIC_PROJECT'')) { $array[1] = $langs->trans(\"SharedProject\"); }", "projet/card.php:1359: if (!getDolGlobalString(''PROJECT_DISABLE_PUBLIC_PROJECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_DISABLE_TIMESHEET_PERMONTH', 'bool', NULL, 'core', 'Disables/hides the ''per month'' timesheet input tab on the project timesheet screens.', 'In core/lib/project.lib.php:554-559, project_timesheet_prepare_head() only adds the ''InputPerMonth'' tab (permonth.php) if !getDolGlobalString(''PROJECT_DISABLE_TIMESHEET_PERMONTH''); this is one of three sibling constants (PERWEEK, PERTIME) for the other timesheet-entry modes.', 'Setting it removes the per-month time-entry tab from the timesheet interface, leaving only whichever of per-week/per-day remain enabled.', 'Boolean-like: set/non-empty hides the per-month tab; unset (default) shows it.', 1, 0, NULL, 1, 'a075268353ecf89298637cf80c1041c6376851c343a13c9b8c1421b7355c667e', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/project.lib.php:554: if (!getDolGlobalString(''PROJECT_DISABLE_TIMESHEET_PERMONTH'')) {", "core/lib/project.lib.php:555: $head[$h][1] = $langs->trans(\"InputPerMonth\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_DISABLE_TIMESHEET_PERTIME', 'bool', NULL, 'core', 'Disables/hides the ''per day'' timesheet input tab on the project timesheet screens.', 'In core/lib/project.lib.php:568-573, project_timesheet_prepare_head() only adds the ''InputPerDay'' tab (perday.php) if !getDolGlobalString(''PROJECT_DISABLE_TIMESHEET_PERTIME''); sibling of PROJECT_DISABLE_TIMESHEET_PERMONTH/PERWEEK.', 'Setting it removes the per-day time-entry tab from the timesheet interface.', 'Boolean-like: set/non-empty hides the per-day tab; unset (default) shows it.', 1, 0, NULL, 1, '302b8375206052735483cc8d27a8ea516da6002457a760d2c0f7bdfd4e038410', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/project.lib.php:568: if (!getDolGlobalString(''PROJECT_DISABLE_TIMESHEET_PERTIME'')) {", "core/lib/project.lib.php:569: $head[$h][1] = $langs->trans(\"InputPerDay\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_DISABLE_TIMESHEET_PERWEEK', 'bool', NULL, 'core', 'Disables/hides the ''per week'' timesheet input tab on the project timesheet screens.', 'In core/lib/project.lib.php:561-566, project_timesheet_prepare_head() only adds the ''InputPerWeek'' tab (perweek.php) if !getDolGlobalString(''PROJECT_DISABLE_TIMESHEET_PERWEEK''); sibling of PROJECT_DISABLE_TIMESHEET_PERMONTH/PERTIME.', 'Setting it removes the per-week time-entry tab from the timesheet interface.', 'Boolean-like: set/non-empty hides the per-week tab; unset (default) shows it.', 1, 0, NULL, 1, 'e777776a344460477f3c62cbb22c944ff0b797c2d48fc2a109dfa62c8c520b23', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/project.lib.php:561: if (!getDolGlobalString(''PROJECT_DISABLE_TIMESHEET_PERWEEK'')) {", "core/lib/project.lib.php:562: $head[$h][1] = $langs->trans(\"InputPerWeek\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_DISABLE_UNLINK_FROM_OVERVIEW', 'bool', NULL, 'projet', 'Hides the ''unlink element'' action/icon on the project overview''s linked-elements table for non-admin users.', 'In projet/element.php:1523: `if (!getDolGlobalString(''PROJECT_DISABLE_UNLINK_FROM_OVERVIEW'') || $user->admin) { print ''<a href=...action=unlink...''; print img_picto(...''Unlink''...); }`, with inline comment ''PROJECT_DISABLE_UNLINK_FROM_OVERVIEW is empty by default, so this test true''. Not applied to tablename ''projet_task'' or ''stock_mouvement''.', 'When enabled, regular (non-admin) users no longer see the unlink icon/link on elements listed in the project overview table; administrators can still unlink regardless of the setting.', 'Boolean: truthy hides the unlink action for non-admin users; empty/default (unset) shows it for everyone.', 1, 0, NULL, 1, '712c17aac591dc8775a060738a5b037d61563986f2eb145e5cff0ed6a776a06e', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:1523|check|if (!getDolGlobalString(''PROJECT_DISABLE_UNLINK_FROM_OVERVIEW'') || $user->admin) {\t\t// PROJECT_DISABLE_UNLINK_FROM_OVERVIEW is empty by default, so this test true"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_DISPLAY_LINKED_BY_CONTACT', 'string', NULL, 'core', 'Shows an extra list on the thirdparty''s Project tab of all projects linked to that thirdparty via a shared contact relationship.', 'Has an admin UI toggle in projet/admin/project.php:877-880 (ajax_constantonoff), and is checked in core/lib/company.lib.php:1160 which, if set, queries and prints a section titled ''ProjectsLinkedToThisThirdParty'' listing projects linked via a contact relation.', 'Enabling it adds an additional table/list on the thirdparty Project tab showing projects connected only through a common contact person (not directly to the thirdparty), which can increase page load/query count on that tab.', 'Boolean-like, toggled from admin UI: en_US label ''Display projects linked to the thirdparty by a common contact''.', 0, 0, NULL, 1, '169fdf9ea336414e5ff3a5600bfc40d968f99a349b652c1bc6e546fc90dcea03', 'v2', '2026-07-24T07:05:23+00:00', '["projet/admin/project.php:877: print $form->textwithpicto($langs->transnoentities(''PROJECT_DISPLAY_LINKED_BY_CONTACT''), ...help...);", "projet/admin/project.php:880: print ajax_constantonoff(''PROJECT_DISPLAY_LINKED_BY_CONTACT'');", "core/lib/company.lib.php:1160: if (getDolGlobalString(''PROJECT_DISPLAY_LINKED_BY_CONTACT'')) {", "langs/en_US/admin.lang:98: PROJECT_DISPLAY_LINKED_BY_CONTACT_help=This option adds a new list on the Project tab of each third party, with all projects linked to the third party via a contact relationship"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ELEMENTS_FOR_MINUS_MARGIN', 'string', NULL, 'projet', 'Overrides which linked element types count as ''minus'' (negative) margin contributors in the project profit/benefit calculation.', 'In projet/element.php:813-819, mirrors PROJECT_ELEMENTS_FOR_PLUS_MARGIN but flags listed elements as margin==''minus''. A later comment at projet/element.php:1081 references this constant with example usage ''PROJECT_ELEMENTS_FOR_MINUS_MARGIN=order_supplier''. The interventions.lang help string also documents it: elements listed here (together with PROJECT_ELEMENTS_FOR_ADD_MARGIN) via Home-Setup-Other complete the list of elements included in profit.', 'Changing the value changes which linked-element types are treated as reducing (subtracting from) the project''s calculated margin/profit, e.g. supplier orders can be flagged as a cost via ''order_supplier''.', 'String: comma-separated list of element keys (e.g. ''order_supplier'') to flag as negative-margin elements.', 1, 0, NULL, 1, 'bcec68203e2f5e4190f14374e411a49e5622088410e9f3fb9f0d5d92c7971a6a', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:813|check|if (getDolGlobalString(''PROJECT_ELEMENTS_FOR_MINUS_MARGIN'')) {", "projet/element.php:819|read|$newelementforminusmargin = explode('','', getDolGlobalString(''PROJECT_ELEMENTS_FOR_MINUS_MARGIN''));", "projet/element.php:1081  // back to positive - see PROJECT_ELEMENTS_FOR_MINUS_MARGIN=order_supplier in #34684)."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ELEMENTS_FOR_PLUS_MARGIN', 'string', NULL, 'projet', 'Overrides which linked element types count as ''add'' (positive) margin contributors in the project profit/benefit calculation.', 'In projet/element.php:802-809: if set, any element previously flagged margin==''add'' is cleared, then the comma-separated list from this constant is exploded and each named element key is (re)flagged $listofreferent[key][''margin''] = ''add''.', 'Changing the value changes which linked-element types (e.g. order_supplier, invoice, etc., keyed by their $listofreferent keys) are treated as contributing positively to the project''s calculated margin/profit.', 'String: comma-separated list of element keys (e.g. ''order_supplier'') to flag as positive-margin elements.', 1, 0, NULL, 1, '0e881ca4acdebbaeaa03816390408e2dd3f6d86422824246cfbd50db8f7c5ec2', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:802|check|if (getDolGlobalString(''PROJECT_ELEMENTS_FOR_PLUS_MARGIN'')) {", "projet/element.php:808|read|$newelementforplusmargin = explode('','', getDolGlobalString(''PROJECT_ELEMENTS_FOR_PLUS_MARGIN''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_EMAIL_TEMPLATE_AUTOLEAD', 'string', NULL, 'public', 'Email template label used to send an automatic confirmation email when a public lead/project is created via public/project/new.php.', 'Read in public/project/new.php:351 as $labeltouse; if set, FormMail::getEMailTemplate() loads the named template to build the subject/body of the confirmation email sent to the lead''s contact.', 'Setting it to a valid email-template label customizes the confirmation email sent to new public leads; if unset or the template is not found, a generic fallback subject/message is used instead.', 'Label (string) of an existing email template of type ''project''.', 1, 0, NULL, 1, '9d002329b4a34ffd1146eb323c1a1a96450be266d349b07dc50be0d7eec09f55', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/new.php:351: $labeltouse = getDolGlobalString(''PROJECT_EMAIL_TEMPLATE_AUTOLEAD'');", "public/project/new.php:356: $arraydefaultmessage = $formmail->getEMailTemplate($db, ''project'', $user, $outputlangs, 0, 1, $labeltouse);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ENABLE_PUBLIC', 'bool', NULL, 'projet', 'Enables the public project submission feature, allowing external users to submit leads via a public URL.', 'Toggled via projet/admin/website.php (lines 68, 70, 79) between 0 and 1. Checked at projet/admin/website.php:125, 141, 181 to control UI display and at public/project/new.php:79 to gate access to the public form.', 'Enabling this setting activates the public project/lead submission page; disabling it blocks access to the public form.', '0 = public submission disabled; 1 = public submission enabled.', 0, 0, 'projet/admin/website.php|projet/admin/website.php|projet/admin/website.php|projet/admin/website.php|projet/admin/website.php|projet/admin/website.php|projet/admin/website.php', 1, '6b3f4e8fbaa11d940720257a907fefbfeebac2a70fbda545d716b42eb6a08408', 'v2', '2026-04-21T11:16:15+00:00', '["projet/admin/website.php:68|write|dolibarr_set_const($db, ''PROJECT_ENABLE_PUBLIC'', 1, ''chaine'', 0, '''', $conf->entity);", "projet/admin/website.php:70|write|dolibarr_set_const($db, ''PROJECT_ENABLE_PUBLIC'', 0, ''chaine'', 0, '''', $conf->entity);", "public/project/new.php:79|check|if (!getDolGlobalString(''PROJECT_ENABLE_PUBLIC'')) {", "projet/admin/website.php:125|check|if (!getDolGlobalString(''PROJECT_ENABLE_PUBLIC'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ENABLE_SUB_PROJECT', 'bool', NULL, 'projet', 'Enables sub-project (nested project) support within the project module.', 'Checked at 7 locations across projet/card.php (lines 725, 1127, 1405, 1795) and projet/list.php (lines 152, 823, 1388) to conditionally render and process sub-project UI elements.', 'Enabling this setting activates the sub-project feature, allowing projects to be nested under parent projects.', 'Empty/0 = sub-projects disabled (default); non-zero = sub-projects enabled.', 1, 0, NULL, 1, 'bad8a7b99770711db6bf677cf7de7878ce8ebd50e273f4661fa443126e763903', 'v2', '2026-04-21T11:16:15+00:00', '["projet/card.php:725|check|if (getDolGlobalInt(''PROJECT_ENABLE_SUB_PROJECT'')) {", "projet/card.php:1127|check|if (getDolGlobalInt(''PROJECT_ENABLE_SUB_PROJECT'')) {", "projet/list.php:1388|check|if (getDolGlobalInt(''PROJECT_ENABLE_SUB_PROJECT'')) {", "projet/list.php:152|check|if (getDolGlobalInt(''PROJECT_ENABLE_SUB_PROJECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_FILTER_FOR_THIRDPARTY_LIST', 'string', NULL, 'projet', 'Applies a custom SQL filter when loading the third-party list in project context.', 'Read in projet/card.php at lines 842 and 1256 into a $filter variable, which is then used in the third-party selector query. The filter string is only applied when the constant is non-empty (checked at lines 841 and 1255).', 'Setting this constant restricts the third-party list displayed on project cards to those matching the supplied filter expression.', 'String: a SQL filter expression for the third-party list. Empty = no additional filter applied.', 1, 0, NULL, 1, '81b5565dcdc3a2688d4eafe5ccedac6313c08542a7be3fb4b515135ff4b1fece', 'v2', '2026-04-21T11:16:15+00:00', '["projet/card.php:841|check|if (getDolGlobalString(''PROJECT_FILTER_FOR_THIRDPARTY_LIST'')) {", "projet/card.php:842|read|$filter = getDolGlobalString(''PROJECT_FILTER_FOR_THIRDPARTY_LIST'');", "projet/card.php:1255|check|if (getDolGlobalString(''PROJECT_FILTER_FOR_THIRDPARTY_LIST'')) {", "projet/card.php:1256|read|$filter = getDolGlobalString(''PROJECT_FILTER_FOR_THIRDPARTY_LIST'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_HIDE_CREATE_OBJECT_BUTTON', 'bool', NULL, 'projet', 'Hides the ''Create object'' action buttons (e.g. create invoice/order/etc from project) on the project card.', 'In projet/card.php:1745, the block building $arrayforbutaction (buttons to create related objects from the project) is only rendered if !getDolGlobalString(''PROJECT_HIDE_CREATE_OBJECT_BUTTON'').', 'Enabling it removes the create-object action buttons from the project card UI.', 'Boolean-like truthy check via getDolGlobalString().', 1, 0, NULL, 1, 'e3b319af7df769af0030fb160f91576d2089a71674ebf653dcd18bd3f9d8cb1f', 'v2', '2026-07-24T07:05:23+00:00', '["projet/card.php:1745: if (!getDolGlobalString(''PROJECT_HIDE_CREATE_OBJECT_BUTTON'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_HIDE_OPEN_PROJECTS_LIST_ON_PROJECT_AREA', 'bool', NULL, 'projet', 'Hides the list of open projects/tasks on the project home area unconditionally.', 'Combined with PROJECT_USE_OPPORTUNITIES and PROJECT_SHOW_OPEN_PROJECTS_LIST_ON_PROJECT_AREA in projet/index.php:456 to gate rendering of print_projecttasks_array(); this flag takes precedence and suppresses the list even if the show flag is set.', 'Enabling it removes the open projects/tasks list block from the project home page regardless of the other two related options.', 'Boolean: 0/unset = list shown per the other options'' logic (default); 1 = list always hidden.', 0, 0, NULL, 1, '556684a4579239f000bc2c4378a21d5f29c74a8afe2fc0809b197eed41657bcb', 'v2', '2026-07-24T07:05:23+00:00', '["projet/index.php:456: if ((!getDolGlobalInt(''PROJECT_USE_OPPORTUNITIES'') || getDolGlobalInt(''PROJECT_SHOW_OPEN_PROJECTS_LIST_ON_PROJECT_AREA'')) && !getDolGlobalInt(''PROJECT_HIDE_OPEN_PROJECTS_LIST_ON_PROJECT_AREA'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_HIDE_TASKS', 'bool', NULL, 'projet', 'Hides the task management tabs and features within the project module when enabled.', 'Written and checked by projet/admin/project.php:414 and :665. Checked in 82 locations: projet/tasks/task.php:371, projet/tasks/time.php:1004 and :1890, projet/element.php:379, among others. The constant is typically combined with PROJECT_USE_OPPORTUNITIES to allow projects to be used solely as CRM opportunities.', 'Enabling this constant hides all task-related tabs and billing-time features on project records; disabling restores full task management.', 'Non-empty = task tabs hidden; 0 or unset = task management visible.', 0, 0, 'projet/admin/project.php|projet/admin/project.php', 1, 'bd926382f91eea8334d9449e80bd811ee49aca660035d7b1b21a7faa92705c8a', 'v2', '2026-04-21T11:16:15+00:00', '["projet/admin/project.php:414|check|if (!getDolGlobalString(''PROJECT_HIDE_TASKS'')) {", "projet/tasks/task.php:371|check|if (getDolGlobalString(''PROJECT_USE_OPPORTUNITIES'') || !getDolGlobalString(''PROJECT_HIDE_TASKS'') || isModEnabled(''eventorganization'')) {", "projet/tasks/time.php:1890|check|if (!getDolGlobalString(''PROJECT_HIDE_TASKS'') && getDolGlobalString(''PROJECT_BILL_TIME_SPENT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_HIDE_UNSELECTABLES', 'bool', NULL, 'core', 'Hides projects that cannot be selected (e.g. closed or restricted) from project selection dropdowns.', 'When set, core/class/html.formprojet.class.php filters out unselectable projects at both line 172 and line 361 in project selection form helpers.', 'Enabling this removes unselectable projects from the UI lists; disabling it shows them (typically grayed out or disabled).', 'Any non-empty string value hides unselectable projects.', 1, 0, NULL, 1, '4eb196ae4f2a1a90c012643440c43fa3248ea5aea58208e9277b16e877a274fe', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.formprojet.class.php:172|check|if (getDolGlobalString(''PROJECT_HIDE_UNSELECTABLES'')) {", "core/class/html.formprojet.class.php:361|check|if (getDolGlobalString(''PROJECT_HIDE_UNSELECTABLES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_IMAGE_PUBLIC_ORGANIZEDEVENT', 'string', NULL, 'public', 'URL/path of an image shown on the public ''organize an event'' project listing page.', 'Used in public/project/index.php:159-161: when set, an <img> tag with this value as src is printed on the page.', 'Setting it displays a custom banner/image on the public event-organization landing page; leaving it empty shows no such image.', 'Any string usable as an image src URL.', 1, 0, NULL, 1, 'c40a2169e65f530d1c177f4be6e9ea6e14f668244f4f989df676f22905980aec', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/index.php:159: if (getDolGlobalString(''PROJECT_IMAGE_PUBLIC_ORGANIZEDEVENT'')) {", "public/project/index.php:161: print ''<img id=\"idPROJECT_IMAGE_PUBLIC_ORGANIZEDEVENT\" src=\"'' . getDolGlobalString(''PROJECT_IMAGE_PUBLIC_ORGANIZEDEVENT'').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_IMAGE_PUBLIC_SUGGEST_BOOTH', 'string', NULL, 'public', 'Specifies the URL of an image to display on the public suggest-a-booth and view-and-vote pages.', 'Used in public/project/suggestbooth.php at lines 173 and 175, and in public/project/viewandvote.php at lines 282 and 284, rendering an img tag when the value is set. No admin UI write path is present.', 'Setting this displays a header image on both the booth suggestion and vote-viewing public pages.', 'String: URL of the image to display on the suggest-booth and view-and-vote pages', 1, 0, NULL, 1, '869c7dd8dfe076490aeb64ea2c6f45448597b93b21c90de5bb64f9eee8dbae57', 'v2', '2026-04-21T13:50:40+00:00', '["public/project/suggestbooth.php:173|check|if (getDolGlobalString(''PROJECT_IMAGE_PUBLIC_SUGGEST_BOOTH'')) {", "public/project/suggestbooth.php:175|read|print ''<img id=\"idPROJECT_IMAGE_PUBLIC_SUGGEST_BOOTH\" src=\"'' . getDolGlobalString(''PROJECT_IMAGE_PUBLIC_SUGGEST_BOOTH'').''\">'';", "public/project/viewandvote.php:282|check|if (getDolGlobalString(''PROJECT_IMAGE_PUBLIC_SUGGEST_BOOTH'')) {", "public/project/viewandvote.php:284|read|print ''<img id=\"idPROJECT_IMAGE_PUBLIC_SUGGEST_BOOTH\" src=\"'' . getDolGlobalString(''PROJECT_IMAGE_PUBLIC_SUGGEST_BOOTH'').''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_IMAGE_PUBLIC_SUGGEST_CONFERENCE', 'string', NULL, 'public', 'URL/path of an image shown on the public ''suggest a conference'' event-organization page.', 'Used in public/project/suggestconference.php:172-174: when set, an <img> tag with this value as src is printed on the page.', 'Setting it displays a custom banner/image on the public conference-suggestion landing page; leaving it empty shows no such image.', 'Any string usable as an image src URL.', 1, 0, NULL, 1, 'd7f95d4ec9c457dcc09d9807e9ebc20c4599c7d0f2180ffef90a1572a40984a4', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/suggestconference.php:172: if (getDolGlobalString(''PROJECT_IMAGE_PUBLIC_SUGGEST_CONFERENCE'')) {", "public/project/suggestconference.php:174: print ''<img id=\"idPROJECT_IMAGE_PUBLIC_SUGGEST_CONFERENCE\" src=\"'' . getDolGlobalString(''PROJECT_IMAGE_PUBLIC_SUGGEST_CONFERENCE'').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_LIMIT_TASK_PROJECT_AREA', 'string', NULL, 'projet', 'Caps the number of task/resource/time-spent rows fetched for the ''all tasks of all open projects'' list on the project task area.', 'Read in projet/activity/index.php:448 as $max = getDolGlobalInt(''PROJECT_LIMIT_TASK_PROJECT_AREA'', 1000), following the comment ''This list can be very long, so we don''t show it by default on task area.''', 'Raising the limit allows more task/resource rows to be listed on the task project area at the cost of a heavier query; lowering it truncates the list sooner.', 'Integer row limit; default 1000 when unset (getDolGlobalInt(..., 1000)).', 1, 0, NULL, 1, 'eb24413af9294d0199ab323ae64fe3c82a13c196ae8b3b9d9ac9e4906348a49e', 'v2', '2026-07-24T07:05:23+00:00', '["projet/activity/index.php:448: $max = getDolGlobalInt(''PROJECT_LIMIT_TASK_PROJECT_AREA'', 1000);", "projet/activity/index.php: // This list can be very long, so we don''t show it by default on task area. We prefer to use the list page."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_LIMIT_YEAR_RANGE', 'string', NULL, 'core', 'Enables a year filter on project/task lists, restricting displayed projects to those overlapping a chosen year, with a year input field shown to the user.', 'In core/lib/project.lib.php:2703-2712 and 2963-2971, when getDolGlobalString(''PROJECT_LIMIT_YEAR_RANGE'') is set, the SQL query is filtered by project start/end dates against a $project_year_filter (from GETPOST, defaulting to current year, or ''*'' for no filter), and a year input form field is rendered after the list.', 'Enabling it adds a year-based date filter to project/task listing queries and displays a year filter input box; the special value ''*'' for the submitted filter disables the date restriction for that request.', 'Boolean-like to enable the feature; the runtime filter value itself accepts a year (integer) or ''*'' (wildcard/no filter), per code: ''Check if empty or invalid year. Wildcard ignores the sql check''.', 1, 0, NULL, 1, '063335923d18bccb1beb0a9194cb8fae4238ee37bce9203e08c48bdfc94d97cc', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/project.lib.php:2703: if (getDolGlobalString(''PROJECT_LIMIT_YEAR_RANGE'')) {", "core/lib/project.lib.php:2705: //Check if empty or invalid year. Wildcard ignores the sql check", "core/lib/project.lib.php:2704: $project_year_filter = GETPOST(\"project_year_filter\", ''alpha''); // ''*'' seems allowed"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_LINKED_ELEMENT_DEFAULT_FILTER_YEAR', 'string', NULL, 'projet', 'Defaults the project overview''s linked-elements date filter to the current calendar year when no explicit date filter was submitted.', 'In projet/element.php:170: `if (!GETPOSTISSET(''datesrfc'') && !GETPOSTISSET(''datesday'') && getDolGlobalString(''PROJECT_LINKED_ELEMENT_DEFAULT_FILTER_YEAR'')) { $new = dol_now(); $tmp = dol_getdate($new); $dates = dol_get_first_day($tmp[''year''], 1);` (start date set to Jan 1 of current year).', 'When enabled, visiting the project overview without any date filter parameters implicitly filters linked elements to the current year starting from the first day of January, instead of showing all dates.', 'Boolean: truthy applies a default ''current year starting Jan 1'' filter to linked elements when no date filter is explicitly set in the request.', 1, 0, NULL, 1, 'b0f3b084a192a9cccc9f1d19d1a20fec9bd1ae23990acab6e56eff6802060a0d', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:170|check|if (!GETPOSTISSET(''datesrfc'') && !GETPOSTISSET(''datesday'') && getDolGlobalString(''PROJECT_LINKED_ELEMENT_DEFAULT_FILTER_YEAR'')) {", "$dates = dol_get_first_day($tmp[''year''], 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_LINK_ON_OVERWIEW_DISABLED', 'bool', NULL, 'projet', 'Hides the ''select element to link'' combo/form used to attach existing elements to a project from the project overview page.', 'In projet/element.php:1249: `if (!getDolGlobalString(''PROJECT_LINK_ON_OVERWIEW_DISABLED'') && $idtofilterthirdparty && !in_array($tablename, $exclude_select_element)) { $selectList = $formproject->select_element(...); ... }`.', 'When enabled, the dropdown/form to link existing elements (of a given tablename) to the project is not built/shown on the overview page, removing that linking capability from the UI (note: constant name has a typo, ''OVERWIEW'').', 'Boolean: truthy disables the element-linking select form on the project overview.', 1, 0, NULL, 1, 'bc69baef774793f1d8c9ce9450b697c545f11ac3f83f9700c665a3fc27359148', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:1249|check|if (!getDolGlobalString(''PROJECT_LINK_ON_OVERWIEW_DISABLED'') && $idtofilterthirdparty && !in_array($tablename, $exclude_select_element)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_NEWFORM_FORCECOUNTRYCODE', 'string', NULL, 'public', 'Forces a default country on the public new-project/lead form when no country was already selected or detected.', 'Read in public/project/new.php:509-510: used only if $country_id is empty, passed to getCountry() as a 2-letter code to pre-fill the country field; GeoIP detection is tried afterward if this and $country_id are both empty.', 'Setting it pre-selects a fixed country on the public lead form instead of leaving it blank or relying on GeoIP detection.', 'A country code string (2-letter ISO code, per getCountry() 2nd argument ''2'').', 1, 0, NULL, 1, '3ffac5e2fccf68cd7362e581a130e46a4893dfa17dab18e8b5564310dde6df2f', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/new.php:509: if (!$country_id && getDolGlobalString(''PROJECT_NEWFORM_FORCECOUNTRYCODE'')) {", "public/project/new.php:510: $country_id = getCountry($conf->global->PROJECT_NEWFORM_FORCECOUNTRYCODE, ''2'', $db, $langs);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_NEWFORM_TEXT', 'string', NULL, 'public', 'Custom introductory text (translation key) displayed above the public new-project/lead submission form.', 'Read in public/project/new.php:453-454: if set, its value is passed through $langs->trans() and printed; otherwise a default ''FormForNewLeadDesc'' translated message is shown.', 'Setting it replaces the default help text shown to visitors on the public lead-creation form with a custom (translatable) message.', 'A string, typically a translation key resolved via $langs->trans().', 1, 0, NULL, 1, '139cd9f91b1d7faaff22cd21aca490dc77084b21d7b44c1ee0cb3f6e05709308', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/new.php:453: if (getDolGlobalString(''PROJECT_NEWFORM_TEXT'')) {", "public/project/new.php:454: print $langs->trans(getDolGlobalString(''PROJECT_NEWFORM_TEXT''))).\"<br>\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_ONLY_PAYED_INVOICE_ON_PROFIT', 'string', NULL, 'projet', 'Restricts the project profit/margin total to only include invoices that are fully paid (closed), excluding unpaid or partially paid invoices.', 'In projet/element.php:989: `if (getDolGlobalString(''PROJECT_ONLY_PAYED_INVOICE_ON_PROFIT'') && $element->status != Facture::STATUS_CLOSED) { $qualifiedfortotal = false; // Only paid invoices qualify }`.', 'When enabled, invoices linked to the project that are not in STATUS_CLOSED (fully paid) are excluded from the project''s profit/total calculation, instead of counting all validated invoices regardless of payment status.', 'Boolean: truthy restricts profit totals to fully-paid (STATUS_CLOSED) invoices only.', 1, 0, NULL, 1, '5a1bf9f1acd9ff9b768c0df1eadd7678fe81d951c43b30e46cf1a4392859a0e7', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:989|check|if (getDolGlobalString(''PROJECT_ONLY_PAYED_INVOICE_ON_PROFIT'') && $element->status != Facture::STATUS_CLOSED) {", "// Only paid invoices qualify"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_OPEN_ALWAYS_ON_TAB', 'string', NULL, 'projet', 'Forces the project''s clickable link (getNomUrl) to always open on a specific tab/option instead of the default overview tab.', 'Read in projet/class/project.class.php:1436-1437 inside Project::getNomUrl(): if set, its value overrides the $option parameter that controls which tab the generated URL points to.', 'Setting it changes which project sub-tab is opened whenever a project link/name is clicked throughout the application.', 'A tab/option code string accepted by Project::getNomUrl()''s $option parameter (exact accepted codes not detailed in the reviewed excerpt).', 1, 0, NULL, 1, 'cf43abd03c25318877aab6b07b9634746ecd860e295b3c5992c7d14b1d2ce614', 'v2', '2026-07-24T07:05:23+00:00', '["projet/class/project.class.php:1436: if (getDolGlobalString(''PROJECT_OPEN_ALWAYS_ON_TAB'')) {", "projet/class/project.class.php:1437: $option = getDolGlobalString(''PROJECT_OPEN_ALWAYS_ON_TAB'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_OPEN_ALWAYS_ON_TIMESHEET', 'string', NULL, 'core', 'Sets the default timesheet view mode for projects, defaulting to ''perweek'' if not defined.', 'Read at core/menus/standard/eldy.lib.php:2430 and 2541 with a default of ''perweek''. No admin UI write detected.', 'Changing this value alters the timesheet view that is preselected for project time entry. The fallback default is ''perweek''.', 'String value; default ''perweek''. Other values depend on available timesheet view modes.', 1, 0, NULL, 1, 'c8d4974627c3949d0379ed6eaf2ba47bfb7f382b4d9fa5b51141cf52babf3e9e', 'v2', '2026-04-21T13:29:58+00:00', '["core/menus/standard/eldy.lib.php:2430|read|$optionTimesheet = getDolGlobalString(''PROJECT_OPEN_ALWAYS_ON_TIMESHEET'', \"perweek\");", "core/menus/standard/eldy.lib.php:2541|read|$optionTimesheet = getDolGlobalString(''PROJECT_OPEN_ALWAYS_ON_TIMESHEET'', \"perweek\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_OPPORTUNITIES_CUMULATIVE_MODE', 'string', NULL, 'core', 'Enables cumulative mode in the funnel of prospection dashboard box.', 'Checked in core/boxes/box_funnel_of_prospection.php at lines 217 and 239 to alter how opportunity amounts are aggregated.', 'Enabling this constant changes the funnel box to accumulate opportunity values cumulatively rather than per-stage.', 'Truthy value = cumulative mode; empty/unset = per-stage mode.', 1, 0, NULL, 1, 'f37d798c89794c6d2bbab60f1d20134178bbb36cccc59873703cf4b7d016f836', 'v2', '2026-04-21T11:16:15+00:00', '["core/boxes/box_funnel_of_prospection.php:217|check|if (getDolGlobalString(''PROJECT_OPPORTUNITIES_CUMULATIVE_MODE'')) {", "core/boxes/box_funnel_of_prospection.php:239|check|if (getDolGlobalString(''PROJECT_OPPORTUNITIES_CUMULATIVE_MODE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_OTHER_THIRDPARTY_ID_TO_ADD_ELEMENTS', 'string', NULL, 'projet', 'Adds one or more extra thirdparty IDs to the filter used when selecting elements available to link to a project, in addition to the project''s own thirdparty.', 'In projet/element.php:1241-1242: `$idtofilterthirdparty = ...object->thirdparty->id; if (getDolGlobalString(''PROJECT_OTHER_THIRDPARTY_ID_TO_ADD_ELEMENTS'')) { $idtofilterthirdparty .= '','' . getDolGlobalString(''PROJECT_OTHER_THIRDPARTY_ID_TO_ADD_ELEMENTS''); }` before calling $formproject->select_element().', 'When set, the ''select element to link'' dropdown on the project overview also includes elements belonging to the extra thirdparty ID(s) listed here, not only the project''s own linked thirdparty.', 'String: comma-separated thirdparty (societe) IDs to add to the filter.', 1, 0, NULL, 1, '15486f0fe32547058cfe6792a3371d3171da1ff8eb9684709c92df174e436c29', 'v2', '2026-07-24T07:05:23+00:00', '["projet/element.php:1241|check|if (getDolGlobalString(''PROJECT_OTHER_THIRDPARTY_ID_TO_ADD_ELEMENTS'')) {", "projet/element.php:1242|read|$idtofilterthirdparty .= '','' . getDolGlobalString(''PROJECT_OTHER_THIRDPARTY_ID_TO_ADD_ELEMENTS'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_PLANNED_WORKLOAD_FORMAT', 'string', NULL, 'core', 'Sets the output format for the planned workload display in project and task list views.', 'When set, the value is assigned to $plannedworkloadoutputformat at projet/tasks/list.php:1143, core/lib/project.lib.php:821, and core/lib/project.lib.php:2958. 6 occurrences across 2 files.', 'When unset, the default workload format is used. When set, the specified format string controls how planned workload durations are rendered.', 'String (format identifier); empty/unset = default format.', 1, 0, NULL, 1, 'cddeacaa7a8540d1f621e3a5c96197880fdd9334a307c625031cb384db1fe639', 'v2', '2026-04-21T11:16:15+00:00', '["projet/tasks/list.php:1142|check|if (getDolGlobalString(''PROJECT_PLANNED_WORKLOAD_FORMAT'')) {", "projet/tasks/list.php:1143|read|$plannedworkloadoutputformat = getDolGlobalString(''PROJECT_PLANNED_WORKLOAD_FORMAT'');", "core/lib/project.lib.php:820|check|if (getDolGlobalString(''PROJECT_PLANNED_WORKLOAD_FORMAT'')) {", "core/lib/project.lib.php:821|read|$plannedworkloadoutputformat = getDolGlobalString(''PROJECT_PLANNED_WORKLOAD_FORMAT'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_PUBLIC_INTERFACE_TOPIC', 'string', NULL, 'public', 'Alt-text/topic string passed to the public ''new project/lead'' page header banner.', 'Used in public/project/new.php:122 as the $alttext argument to htmlPrintOnlineHeader(), which prints the company logo/header block for the public lead-creation form.', 'Changing it changes the alt text/topic shown in the header banner of the public new-project (lead) page.', 'Any string used as header alt text.', 1, 0, NULL, 1, '5317d885b2daf1a55198bc1a2d5f4d6178e9861225c6c05e93dac43f884e6ec8', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/new.php:122: htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''PROJECT_PUBLIC_INTERFACE_TOPIC''), ''PROJECT_IMAGE_PUBLIC_NEWLEAD'');"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_SHOW_CONTACTS_IN_LIST', 'bool', NULL, 'core', 'Adds a legacy/backward-compatibility empty column for task contacts in the project task list.', 'In core/lib/project.lib.php:1209-1212, an extra empty `<td></td>` cell is printed in the task list table if getDolGlobalString(''PROJECT_SHOW_CONTACTS_IN_LIST'') is set; the inline comment marks this as ''Contacts of task for backward compatibility''.', 'Enabling it inserts an additional (currently empty) table cell into the project task list, kept only for backward compatibility with older column layouts.', 'Boolean-like: set/non-empty adds the extra placeholder column; unset (default) omits it.', 1, 0, NULL, 1, '48535fcaed50f8311ec6be9a4c52313b9e756b3f66aaaf059bd986c3e1841766', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/project.lib.php:1209: // Contacts of task for backward compatibility,", "core/lib/project.lib.php:1210: if (getDolGlobalString(''PROJECT_SHOW_CONTACTS_IN_LIST'')) { print ''<td></td>''; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_SHOW_OPEN_PROJECTS_LIST_ON_PROJECT_AREA', 'bool', NULL, 'projet', 'Forces the list of open projects/tasks to be shown on the project home area even when opportunities are in use.', 'Combined with PROJECT_USE_OPPORTUNITIES and PROJECT_HIDE_OPEN_PROJECTS_LIST_ON_PROJECT_AREA in projet/index.php:456; the surrounding comment explains the list is normally hidden when opportunities are used because it would be ''very long and useless'', but this option restores it ''for interface backward compatibility''.', 'Enabling it re-displays the open projects/tasks list block on the project home page in setups that use opportunities, where it would otherwise be hidden by default.', 'Boolean: 0/unset = list hidden when PROJECT_USE_OPPORTUNITIES is on (default); 1 = list shown regardless.', 0, 0, NULL, 1, 'ae50bcc573decaa4c63fecb7269de525e34eeef90d74a471df3157061481d52a', 'v2', '2026-07-24T07:05:23+00:00', '["projet/index.php:456: if ((!getDolGlobalInt(''PROJECT_USE_OPPORTUNITIES'') || getDolGlobalInt(''PROJECT_SHOW_OPEN_PROJECTS_LIST_ON_PROJECT_AREA'')) && !getDolGlobalInt(''PROJECT_HIDE_OPEN_PROJECTS_LIST_ON_PROJECT_AREA'')) {", "projet/index.php:457: // This list is surely very long and useless when we are using opportunities, so we hide it for this use case, but we allow to show it if", "projet/index.php:458: // we really want it and to allow interface backward compatibility."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_SHOW_TASK_LIST_ON_PROJECT_AREA', 'bool', NULL, 'projet', 'Shows a task list section on the project activity area index page.', 'The comment at projet/activity/index.php:446 states ''Add constant PROJECT_SHOW_TASK_LIST_ON_PROJECT_AREA to show this list''. Checked at projet/activity/index.php:409 in conjunction with PROJECT_HIDE_TASKS.', 'Enabling this constant causes a task list to be rendered on the project area index; it has no effect if PROJECT_HIDE_TASKS is also set.', 'Empty/0 = task list not shown on project area (default); non-empty = task list displayed.', 1, 0, NULL, 1, '725e1a08ff44be52a7d0fff2846cfbbfaa4cb6c8ec9f116454e00298849dddc7', 'v2', '2026-04-21T11:16:15+00:00', '["projet/activity/index.php:446  // Add constant PROJECT_SHOW_TASK_LIST_ON_PROJECT_AREA to show this list", "projet/activity/index.php:409|check|if (!getDolGlobalString(''PROJECT_HIDE_TASKS'') && getDolGlobalString(''PROJECT_SHOW_TASK_LIST_ON_PROJECT_AREA'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TASK_ADDON', 'string', NULL, 'projet', 'Selects the numbering module (addon) used to generate project task references.', 'Set via projet/admin/project.php:235 dolibarr_set_const, checked at projet/admin/project.php:475, and read in projet/class/task.class.php:2355, core/actions_massactions.inc.php, and core/modules/modProjet.class.php where it is used as the class/path for the task ref-numbering rule, defaulting to ''mod_task_simple'' if unset.', 'Changing it swaps the numbering module class used to compute task references (via getrefifauto rule), loaded from core/modules/project/task/<value>.php.', NULL, 0, 0, 'projet/admin/project.php|projet/admin/project.php', 1, '18c1f9c7890dec3c9f42f844b6ed07f56375ac1444ce64acf13c1b745f90201c', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, \"PROJECT_TASK_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "''t.ref'' => array(''rule'' => ''getrefifauto'', ''class'' => (!getDolGlobalString(''PROJECT_TASK_ADDON'') ? ''mod_task_simple'' : $conf->global->PROJECT_TASK_ADDON), ''path'' => \"/core/modules/"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TASK_ADDON_PDF', 'string', NULL, 'projet', 'Specifies the PDF template module used to generate PDF documents for project tasks.', 'According to the comment at projet/class/task.class.php:2592: ''Create an intervention document on disk using template defined into PROJECT_TASK_ADDON_PDF''. The value is read at projet/class/task.class.php:2610 and managed via projet/admin/project.php (multiple write operations). core/tpl/card_presend.tpl.php:133 checks for its absence.', 'Setting this constant selects the PDF template for project task documents; leaving it empty suppresses task PDF generation in some paths.', 'String: name of a PDF template module. Empty = no PDF template selected (PDF generation suppressed or uses default).', 0, 0, 'projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php|projet/admin/project.php', 1, '0e62846a128244c3e7a2cf3aa7729257215b8458c7b46ac684988b10800f8933', 'v2', '2026-04-21T11:16:15+00:00', '["projet/class/task.class.php:2592  *  Create an intervention document on disk using template defined into PROJECT_TASK_ADDON_PDF", "projet/class/task.class.php:2610|read|} elseif (getDolGlobalString(''PROJECT_TASK_ADDON_PDF'')) {", "core/tpl/card_presend.tpl.php:133|check|if ($object->element == ''project_task'' && !getDolGlobalString(''PROJECT_TASK_ADDON_PDF'')) {", "projet/admin/project.php:211|write|if (dolibarr_set_const($db, \"PROJECT_TASK_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TASK_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies one or more directory paths where ODT templates for project task documents are searched.', 'Read in core/modules/project/task/doc/doc_generic_task_odt.modules.php; the value is split by comma and newline into a list of directories (line 383), appended to the template path display (line 410), and checked for existence (line 418).', 'If unset, only the default template directory is used; if set, additional directories are scanned for ODT templates.', 'String: comma- or newline-separated directory paths.', 1, 0, NULL, 1, '0b0e286f5a7b379d3c3c4a526f90dfcf62f9686c0ebd7da068a005c7044d2b6e', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/project/task/doc/doc_generic_task_odt.modules.php:383|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim($conf->global->PROJECT_TASK_ADDON_PDF_ODT_PATH)));", "core/modules/project/task/doc/doc_generic_task_odt.modules.php:410|read|$texte .= getDolGlobalString(''PROJECT_TASK_ADDON_PDF_ODT_PATH'');", "core/modules/project/task/doc/doc_generic_task_odt.modules.php:418|check|if (getDolGlobalString(''PROJECT_TASK_ADDON_PDF_ODT_PATH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TASK_TIME_MONTH', 'string', NULL, 'projet', 'Enables display of the ''projects active this month'' time-spent summary table on the project activity index page.', 'Checked in projet/activity/index.php:313: if set, prints a table titled with $langs->trans(''ActivityOnProjectThisMonth'') showing time spent for the current month.', 'Enabling it adds an extra summary table of monthly project activity to the activity index page; when unset the table is not shown.', 'Boolean-like (getDolGlobalString): non-empty shows the ''this month'' activity table; empty/unset (default) hides it.', 1, 0, NULL, 1, '345a0c7384ce9b33f2186984fb5567be1ab288500e4080cb4234d22b0709b0f9', 'v2', '2026-07-24T07:05:23+00:00', '["projet/activity/index.php:313: if (getDolGlobalString(''PROJECT_TASK_TIME_MONTH'')) {", "projet/activity/index.php: print ''<td>''.$langs->trans(\"ActivityOnProjectThisMonth\").'': ''.dol_print_date($now, \"%B %Y\").''</td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TASK_TIME_YEAR', 'string', NULL, 'projet', 'Enables display of the ''projects active this year'' time-spent summary table on the project activity index page.', 'Checked in projet/activity/index.php:361: if set, prints a table titled with $langs->trans(''ActivityOnProjectThisYear'') showing time spent for the current year.', 'Enabling it adds an extra summary table of yearly project activity to the activity index page; when unset the table is not shown.', 'Boolean-like (getDolGlobalString): non-empty shows the ''this year'' activity table; empty/unset (default) hides it.', 1, 0, NULL, 1, '59528b9bb71e6fbf84fdeffd980d96be48641adfa75c51af33cfb44e49a9c7ae', 'v2', '2026-07-24T07:05:23+00:00', '["projet/activity/index.php:361: if (getDolGlobalString(''PROJECT_TASK_TIME_YEAR'')) {", "projet/activity/index.php: print ''<td>''.$langs->trans(\"ActivityOnProjectThisYear\").'': ''.dol_print_date($now, \"%Y\").''</td>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TASK_UNIVERSAL_MASK', 'string', NULL, 'core', 'Defines the numbering mask pattern used by the ''universal'' task reference generator for project tasks.', 'Read at core/modules/project/task/mod_task_universal.php:95 (UI display) and :140 (mask application). No admin UI file listed; hidden setting.', 'Changing the mask alters how task reference numbers are generated for new tasks when the universal numbering module is active.', 'String mask pattern following Dolibarr mask syntax (e.g. ''{YYYY}{MM}{0000}''); empty = no mask configured', 1, 0, NULL, 1, '404a4b85fd46681e754e8374a89aadd7fac6db05cf14133901885a0f1001b6d5', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/project/task/mod_task_universal.php:140|read|$mask = getDolGlobalString(''PROJECT_TASK_UNIVERSAL_MASK'');", "core/modules/project/task/mod_task_universal.php:95|read|$texte .= ''<td class=\"right\">''.$form->textwithpicto(''<input type=\"text\" class=\"flat minwidth175\" name=\"masktask\" value=\"''.getDolGlobalString(''PROJECT_TASK_UNIVERSAL_MASK'').''\">'',"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_THIRDPARTY_REQUIRED', 'string', NULL, 'projet', 'Makes the third-party (customer) field mandatory when creating or editing a project.', 'Checked in 5 locations. projet/class/project.class.php:473 returns an error when the constant is set and no socid is provided. projet/card.php:836, :838, :1250, :1252 wrap the third-party label in a ''fieldrequired'' span when this constant is non-empty.', 'Setting this constant forces users to link a project to a third-party record; leaving it unset makes the third-party field optional.', 'Non-empty = third-party field required; 0 or unset = optional.', 1, 0, NULL, 1, '05653b61c10c4c0c7aa75cc8912f779e0623a894a6ae92faae8713644d2e5c42', 'v2', '2026-04-21T11:16:15+00:00', '["projet/class/project.class.php:473|check|if (getDolGlobalString(''PROJECT_THIRDPARTY_REQUIRED'') && !($this->socid > 0)) {", "projet/card.php:836|read|print(!getDolGlobalString(''PROJECT_THIRDPARTY_REQUIRED'') ? '''' : ''<span class=\"fieldrequired\">'');", "projet/card.php:838|read|print(!getDolGlobalString(''PROJECT_THIRDPARTY_REQUIRED'') ? '''' : ''</span>'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TIMESHEET_DISABLEBREAK_ON_PROJECT', 'bool', NULL, 'projet', 'Removes the break/pause columns from timesheet views, collapsing the timesheet display to contiguous time blocks.', 'When set, break-related columns are removed and colspan values are increased by 2 in timesheet tables, as seen in projet/activity/perweek.php:717 (''$colspan = 1 + (!getDolGlobalString(...) ? 0 : 2)'') and core/lib/project.lib.php:1570. Checked across 27 occurrences in core/lib/project.lib.php and projet/activity/* files.', 'Enabling this setting hides break/pause time columns from the timesheet per-day, per-week, and per-month views.', 'Empty/0 = break columns shown (default); non-empty = break columns hidden, colspan adjusted.', 1, 0, NULL, 1, '16a4b5f003c0c293c9bf0b1280b19a707e94713af574317f5a7dcfed0d2ad1b6', 'v2', '2026-04-21T11:16:15+00:00', '["projet/activity/perweek.php:717|read|$colspan = 1 + (!getDolGlobalString(''PROJECT_TIMESHEET_DISABLEBREAK_ON_PROJECT'') ? 0 : 2);", "core/lib/project.lib.php:1570|read|$colspan=5+(empty($conf->global->PROJECT_TIMESHEET_DISABLEBREAK_ON_PROJECT)?0:2);", "core/lib/project.lib.php:1648|check|if (getDolGlobalString(''PROJECT_TIMESHEET_DISABLEBREAK_ON_PROJECT'')) {", "projet/activity/permonth.php:545|check|if (!getDolGlobalString(''PROJECT_TIMESHEET_DISABLEBREAK_ON_PROJECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TIMESHEET_PREVENT_AFTER_MONTHS', 'string', NULL, 'projet', 'Freezes timesheet entry after a configurable number of months, preventing edits to old time records.', 'An integer value representing the number of months after which timesheet entries are locked. Set via projet/admin/project.php:248 with the note ''Allow to disable this configuration if empty''. Checked extensively in projet/class/task.class.php and core/lib/project.lib.php (17+ occurrences across multiple files).', 'Setting a positive integer locks timesheet entries older than that many months; setting it to empty or zero disables the freeze.', 'Integer >= 1 = number of months after which timesheets are frozen; empty or 0 = no freeze (disabled).', 0, 0, 'projet/admin/project.php|projet/admin/project.php', 1, '36fad7b14f50f3819607ade1e7fed29476a0ccfef7d757b427325c1222a88f59', 'v2', '2026-04-21T11:16:15+00:00', '["projet/admin/project.php:248|write|dolibarr_set_const($db, ''PROJECT_TIMESHEET_PREVENT_AFTER_MONTHS'', intval($timesheetFreezeDuration), ''chaine'', 0, '''', $conf->entity); //Allow to disable this configuration if empty", "projet/class/task.class.php:1643|check|if (getDolGlobalInt(''PROJECT_TIMESHEET_PREVENT_AFTER_MONTHS'')) {", "core/lib/project.lib.php:1492|check|if (getDolGlobalInt(''PROJECT_TIMESHEET_PREVENT_AFTER_MONTHS'')) {", "projet/admin/project.php:868|read|print ''<input type=\"number\" class=\"width50\" id=\"timesheetFreezeDuration\" name=\"timesheetFreezeDuration\" min=\"0\" step=\"1\""]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TIMES_SPENT_FORMAT', 'string', NULL, 'core', 'Sets the output format for the total times-spent display in project and task list views.', 'Checked at projet/tasks/list.php:1145, core/lib/project.lib.php:823, and core/lib/project.lib.php:2960. 3 occurrences across 2 files.', 'When unset, the default time format is used for times-spent totals. When set, the specified format overrides the default rendering.', 'String (format identifier); empty/unset = default format.', 1, 0, NULL, 1, '961b3b1dfbb17de1cdf55da058b43507afd24292c34819046887011a9e2dd9a2', 'v2', '2026-04-21T11:16:15+00:00', '["projet/tasks/list.php:1145|check|if (getDolGlobalString(''PROJECT_TIMES_SPENT_FORMAT'')) {", "core/lib/project.lib.php:823|check|if (getDolGlobalString(''PROJECT_TIMES_SPENT_FORMAT'')) {", "core/lib/project.lib.php:2960|check|if (getDolGlobalString(''PROJECT_TIMES_SPENT_FORMAT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TIME_SHOW_TASK_NOT_ASSIGNED', 'bool', NULL, 'projet', 'Controls the visibility of tasks not assigned to the current user on timesheet views; defaults to 2 when not set.', 'Read in projet/activity/permonth.php:667, projet/activity/perday.php:636, and projet/activity/perweek.php:756 into $restrictviewformytask with a code-level default of 2.', 'Changing this value alters which tasks are shown to the current user on timesheet pages (assigned-only vs. all tasks).', 'Integer: controls task visibility filter on timesheet views. Defaults to 2 when not set.', 1, 0, NULL, 1, 'd0c9f69e7883326d53877dc865a6a03cae991719a38bb442bef68c88cc003b56', 'v2', '2026-04-21T11:16:15+00:00', '["projet/activity/permonth.php:667|read|$restrictviewformytask = getDolGlobalInt(''PROJECT_TIME_SHOW_TASK_NOT_ASSIGNED'', 2);", "projet/activity/perday.php:636|read|$restrictviewformytask = getDolGlobalInt(''PROJECT_TIME_SHOW_TASK_NOT_ASSIGNED'', 2);", "projet/activity/perweek.php:756|read|$restrictviewformytask = getDolGlobalInt(''PROJECT_TIME_SHOW_TASK_NOT_ASSIGNED'', 2);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TIME_SPEND_WARNING_PERCENT', 'string', NULL, 'core', 'Sets the percentage over the planned time budget at which a warning is triggered on project timesheets.', 'Read at core/lib/project.lib.php lines 1102, 2979, and 3096 (each occurrence is identical). The warning ratio is computed as (1 + PROJECT_TIME_SPEND_WARNING_PERCENT / 100); if not set, a default of 1.10 (10% over budget) is used.', 'Setting this constant adjusts the threshold at which time-overspend warnings appear on project timesheets. If unset, the default is 10% over the planned time.', 'Numeric percentage; e.g. ''20'' means warnings trigger at 120% of planned time. Default effective value when unset: 10 (1.10 ratio).', 1, 0, NULL, 1, 'ca236399e3e6bbc3ac734cb57ba7997a761204be6bace3cadce01ce2148e0b9e', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/project.lib.php:1102|read|$warningRatio = getDolGlobalString(''PROJECT_TIME_SPEND_WARNING_PERCENT'') ? (1 + $conf->global->PROJECT_TIME_SPEND_WARNING_PERCENT / 100) : 1.10;", "core/lib/project.lib.php:2979|read|$warningRatio = getDolGlobalString(''PROJECT_TIME_SPEND_WARNING_PERCENT'') ? (1 + $conf->global->PROJECT_TIME_SPEND_WARNING_PERCENT / 100) : 1.10;", "core/lib/project.lib.php:3096|read|$warningRatio = getDolGlobalString(''PROJECT_TIME_SPEND_WARNING_PERCENT'') ? (1 + $conf->global->PROJECT_TIME_SPEND_WARNING_PERCENT / 100) : 1.10;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TIME_SPENT_FORMAT', 'string', NULL, 'core', 'Sets the output format for individual time-spent entries in project task list views.', 'The value is read into $timespentoutputformat at projet/tasks/list.php:1146, core/lib/project.lib.php:824, and core/lib/project.lib.php:2961. 3 occurrences across 2 files.', 'When unset, the default time format is used for individual time-spent entries. When set, the specified format controls their rendering.', 'String (format identifier); empty/unset = default format.', 1, 0, NULL, 1, '2bc0dc79a54d147c5c965ed39f642d9243ed2d8040e87d380e77f084ed4c501a', 'v2', '2026-04-21T11:16:15+00:00', '["projet/tasks/list.php:1146|read|$timespentoutputformat = getDolGlobalString(''PROJECT_TIME_SPENT_FORMAT'');", "core/lib/project.lib.php:824|read|$timespentoutputformat = getDolGlobalString(''PROJECT_TIME_SPENT_FORMAT'');", "core/lib/project.lib.php:2961|read|$timespentoutputformat = getDolGlobalString(''PROJECT_TIME_SPENT_FORMAT'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_TIME_SPENT_INTO_INVOICE_USE_VALUE', 'bool', NULL, 'projet', 'Reuses the monetary value of recorded time spent (cost price) as the unit price when generating an invoice line from a task''s time spent.', 'Checked twice in projet/tasks/time.php (781, 789) in the invoice-line-building logic for time spent on a task, both guarded by the comment ''If we want to reuse the value of timespent (so use same price than cost price)''; when true, $pu_ht_for_task is computed from the accumulated timespent value instead of the product/task''s normal unit price.', 'Enabling it makes generated invoice lines for time spent price at the same rate as the recorded cost/time value, rather than at the product''s or task''s configured selling price.', 'Boolean-like: any truthy value makes invoicing reuse the time-spent value as the unit price.', 1, 0, NULL, 1, 'de3f6ed6ef22a4b27b79b1368e99a754680e2195882cf1a8b08c205fd6d16cab', 'v2', '2026-07-24T07:05:23+00:00', '["projet/tasks/time.php:781: if (getDolGlobalString(''PROJECT_TIME_SPENT_INTO_INVOICE_USE_VALUE'')) {", "projet/tasks/time.php:780: // If we want to reuse the value of timespent (so use same price than cost price)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_UNIVERSAL_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the ''Universal'' automatic numbering module for project references.', 'Used exclusively within core/modules/project/mod_project_universal.php. At line 98 it is displayed in a configuration input; at line 150 it is loaded as the active mask for project reference generation.', 'Changing the mask alters the format of newly generated project reference numbers; existing references are unaffected.', 'Any mask string accepted by the Universal project numbering module.', 1, 0, NULL, 1, '3dafd6cd10d38b5fc076531485fc25f230ad6062337dc266fb1234c816636c41', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/project/mod_project_universal.php:98|read|value=\"''.getDolGlobalString(''PROJECT_UNIVERSAL_MASK'').''\"", "core/modules/project/mod_project_universal.php:150|read|$mask = getDolGlobalString(''PROJECT_UNIVERSAL_MASK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_URL_REDIRECT_LEAD', 'string', NULL, 'public', 'URL to redirect the visitor to after successfully submitting the public new-project/lead form.', 'Read in public/project/new.php:385-386: used as $urlback when set and no backtopage parameter was provided; otherwise the page redirects back to itself with action=added.', 'Setting it sends visitors to a custom thank-you/redirect page after lead creation instead of the default self-redirect; a TODO in the code notes that substitution tags like __AMOUNT__ are not yet implemented for this URL.', 'Any URL string; a TODO comment notes planned substitution tag support (__AMOUNT__ etc.) not yet implemented.', 1, 0, NULL, 1, '42b4e69bfea4d10602dfbdecd33106efb61d19e8b7e17f5ccd12ca0547a185b3', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/new.php:385: } elseif (getDolGlobalString(''PROJECT_URL_REDIRECT_LEAD'')) {", "public/project/new.php:386: $urlback = getDolGlobalString(''PROJECT_URL_REDIRECT_LEAD''); // TODO Make replacement of __AMOUNT__, etc..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_USE_OPPORTUNITIES', 'bool', NULL, 'projet', 'Enables the commercial opportunity fields/tab (usage_opportunity) on projects.', 'Checked with getDolGlobalString across projet/class/project.class.php, projet/graph_opportunities.inc.php, projet/contact.php, projet/activity/index.php, and projet/card.php.', 'When enabled, project cards and activity/opportunity graphs show and use opportunity-related fields such as usage_opportunity.', NULL, 0, 0, NULL, 1, 'fc39f28f4c60844ed3e70e3c6bda3f82ae627ced7e9a1d681b697e9f05eb4b91', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''PROJECT_USE_OPPORTUNITIES'') && $object->usage_opportunity) {", "if (getDolGlobalString(''PROJECT_USE_OPPORTUNITIES'') || !getDolGlobalString(''PROJECT_HIDE_TASKS'') || isModEnabled(''eventorganization'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_USE_REAL_COST_FOR_TIME_INVOICING', 'bool', NULL, 'projet', 'Forces invoice lines generated from project time-spent to use the actual recorded hourly cost rate rather than a fixed unit price.', 'Checked in projet/tasks/time.php:533 when building invoice lines from time spent: if true, the unit price ($pu_ht) is set to 0 to force use of the rate saved at the time the time-spent entry was recorded, per the inline comment.', 'Enabling it changes how invoice lines are priced when generating invoices from time spent: instead of using the user''s current/last hourly rate, the historical per-entry rate is used.', 'Boolean-like: any truthy value forces use of the real/recorded cost rate for time-spent invoicing.', 1, 0, NULL, 1, '163b7a6c021a0ff16cb8c16c331b630a4f19d036790c1d62d5a9af154847dafe', 'v2', '2026-07-24T07:05:23+00:00', '["projet/tasks/time.php:533: if (getDolGlobalInt(''PROJECT_USE_REAL_COST_FOR_TIME_INVOICING'')) {\n\t\t\t\t\t\t// We set unit price to 0 to force the use of the rate saved during recording"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJECT_USE_SEARCH_TO_SELECT', 'bool', NULL, 'core', 'Enables an autocomplete search input instead of a dropdown for selecting projects on forms.', 'Checked in core/class/html.form.class.php at lines 8702 and 8943, and in core/class/html.formprojet.class.php:101. Written via projet/admin/project.php:238. Also referenced in admin/system/perf.php:607 which shows a performance note when the option is enabled.', 'Enabling this setting replaces project dropdowns with a search-to-select autocomplete input, which improves performance when there are many projects.', 'Empty/0 = dropdown selector (default); non-empty = autocomplete search input.', 0, 0, 'projet/admin/project.php|admin/system/perf.php|admin/system/perf.php|projet/admin/project.php|projet/admin/project.php', 1, 'cff51385307cfdb3f1393ecbb79a86cf8f69c9a7591f24353c74ed314b875ff0', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.form.class.php:8702|check|if (getDolGlobalString(''PROJECT_USE_SEARCH_TO_SELECT'')) {", "core/class/html.formprojet.class.php:101|check|if (!empty($conf->use_javascript_ajax) && getDolGlobalString(''PROJECT_USE_SEARCH_TO_SELECT'')) {", "admin/system/perf.php:607|check|if (!getDolGlobalString(''PROJECT_USE_SEARCH_TO_SELECT'')) {", "projet/admin/project.php:238|write|if (dolibarr_set_const($db, \"PROJECT_USE_SEARCH_TO_SELECT\", $companysearch, ''chaine'', 0, '''', $conf->entity)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROJET_VISIBILITY', 'string', NULL, 'projet', 'Sets the default visibility scope for projects submitted via the public lead form.', 'Written via projet/admin/website.php:77 and read in the admin UI at projet/admin/website.php:165 (as a selectarray) and in public/project/new.php:192.', 'Changing this value alters the visibility attribute applied to projects created through the public lead form.', 'String: a visibility scope value (options populated via a selectarray in the admin UI). Empty = no default visibility set.', 0, 0, 'projet/admin/website.php|projet/admin/website.php', 1, 'c2803b84f5f09151dd35387b509a63fc6b373ead145f82ba45244921908e78c6', 'v2', '2026-04-21T11:16:15+00:00', '["projet/admin/website.php:77|write|$res = dolibarr_set_const($db, \"PROJET_VISIBILITY\", $visibility, ''chaine'', 0, '''', $conf->entity);", "projet/admin/website.php:165|read|print $form->selectarray(''PROJET_VISIBILITY'', $arrayofchoices, getDolGlobalInt(''PROJET_VISIBILITY''), 0);", "public/project/new.php:192|read|$visibility = getDolGlobalString(''PROJET_VISIBILITY'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_ADDON', 'string', NULL, 'core', 'Selects the numbering module (addon) used to generate commercial proposal (quote) references.', 'Set via admin/propal.php:219 dolibarr_set_const, checked at admin/propal.php:334, and read in comm/propal/class/propal.class.php:3782 and core/modules/modPropale.class.php, which uses it as class/path for the ref-numbering rule, defaulting to ''mod_propale_marbre'' if unset.', 'Changing it swaps the numbering module class used to compute proposal references, loaded from core/modules/propale/<value>.php.', NULL, 0, 0, 'admin/propal.php|admin/propal.php', 1, '7435ce6aa4e0b5de32db25dab3c3b87e6ba3739bc8f97f70ac04a01b100ca6c7', 'v2', '2026-07-24T06:41:12+00:00', '["*  defined into PROPALE_ADDON", "''class'' => (!getDolGlobalString(''PROPALE_ADDON'') ? ''mod_propale_marbre'' : $conf->global->PROPALE_ADDON),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_ADDON_PDF', 'string', NULL, 'admin', 'Selects the default PDF template (model) used to generate commercial proposal documents.', 'Set/deleted via admin/propal.php:206-207 (dolibarr_set_const/dolibarr_del_const and direct $conf->global assignment), checked at admin/propal.php:201 and 479, and read in comm/propal/class/propal.class.php:4058 and comm/propal/card.php:2615 as the fallback for PROPALE_ADDON_PDF_ODT_DEFAULT.', 'Changing it changes which PDF model (''cyan'' is the code default per getDolGlobalString fallback) is used to build proposal PDFs.', NULL, 0, 0, 'admin/propal.php|admin/propal.php|admin/propal.php|admin/propal.php|admin/propal.php', 1, '020fa0b4f13969e6b7723e21188ba9fb409f16000775e2f974f0cd2df00ff329', 'v2', '2026-07-24T06:41:12+00:00', '["$modele = getDolGlobalString(''PROPALE_ADDON_PDF'', ''cyan'');", "if (dolibarr_set_const($db, \"PROPALE_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_ADDON_PDF_ODT_CLOSED', 'string', NULL, 'comm', 'Specifies the ODT PDF model to use for closed (signed/refused) proposals.', 'Read in comm/propal/class/propal.class.php:2688 and :2797 to select the PDF model when a proposal is in a closed state; also exposed in core/modules/propale/doc/doc_generic_proposal_odt.modules.php for configuration. Falls back to the proposal''s default model if unset.', 'Changing this value changes the document template applied when generating PDFs for closed proposals.', 'String name of an ODT module class; falls back to $this->model_pdf if unset.', 1, 0, NULL, 1, 'c3a64f6f3abaed8dbbacb6072dbf3b81064ec7b8ba71fd8f871751e35f6456f4', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/class/propal.class.php:2688|read|$modelpdf = getDolGlobalString(''PROPALE_ADDON_PDF_ODT_CLOSED'', $this->model_pdf);", "comm/propal/class/propal.class.php:2797|read|$modelpdf = getDolGlobalString(''PROPALE_ADDON_PDF_ODT_CLOSED'', $this->model_pdf);", "core/modules/propale/doc/doc_generic_proposal_odt.modules.php:211|read|$texte .= $form->selectarray(''value4'', $list, getDolGlobalString(''PROPALE_ADDON_PDF_ODT_CLOSED''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_ADDON_PDF_ODT_DEFAULT', 'string', NULL, 'comm', 'Specifies the default ODT document template to use when generating proposal PDF/ODT documents.', 'This constant stores the name of the default ODT template for proposals. It is read in comm/propal/card.php:2564 and in the ODT module setup at core/modules/propale/doc/doc_generic_proposal_odt.modules.php:199. Falls back to PROPALE_ADDON_PDF if unset.', 'Changing this value alters which ODT template is pre-selected when generating proposal documents.', 'String: name of the ODT template file; empty/unset = falls back to PROPALE_ADDON_PDF value.', 1, 0, NULL, 1, 'f198afccf06bbe8161ac4bb0c3f245026a7039bcffea46be0ab14fbb6f870720', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/card.php:2564|read|$preselected = getDolGlobalString(''PROPALE_ADDON_PDF_ODT_DEFAULT'', getDolGlobalString(\"PROPALE_ADDON_PDF\"));", "core/modules/propale/doc/doc_generic_proposal_odt.modules.php:199|read|$texte .= $form->selectarray(''value2'', $list, getDolGlobalString(''PROPALE_ADDON_PDF_ODT_DEFAULT''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Filesystem path to the directory containing ODT template files used to generate commercial proposal documents.', 'Read in core/modules/propale/doc/doc_generic_proposal_odt.modules.php:128 (`$odtPath = trim(getDolGlobalString(''PROPALE_ADDON_PDF_ODT_PATH''));`) inside the module''s info() method, which builds the admin setup form for the generic ODT proposal document generator.', 'Setting this path tells the ODT document generator where to look for proposal ODT templates; it is displayed/edited through the module''s own setup form (setModuleOptions action) rather than a generic admin page.', 'Free-form filesystem path string; no enum given in payload.', 0, 0, NULL, 1, '310ac9c3adbd63c17f09ade563fa1088622bd4eb5d865a9f68f651a3312b7fb9', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/propale/doc/doc_generic_proposal_odt.modules.php:128|read|$odtPath = trim(getDolGlobalString(''PROPALE_ADDON_PDF_ODT_PATH''));", "core/modules/propale/doc/doc_generic_proposal_odt.modules.php|param1 value=\"PROPALE_ADDON_PDF_ODT_PATH\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_ADDON_PDF_ODT_TOBILL', 'string', NULL, 'comm', 'Names the PDF/ODT document model used to regenerate a proposal''s document when it is closed as signed (about to be billed).', 'Read in comm/propal/class/propal.class.php:2705 (assigned to $modelpdf when status becomes self::STATUS_SIGNED inside closeProposal) and again in core/modules/propale/doc/doc_generic_proposal_odt.modules.php:205 where it is offered as a selectable value in an ODT template''s UI.', 'Setting it selects which document model is used to (re)generate the proposal''s PDF specifically when the proposal is closed with the ''signed'' status, overriding the object''s default model_pdf.', 'String: name of a registered proposal PDF/ODT document model.', 1, 0, NULL, 1, 'e6a573f8ddd3a3d7079411aa14d88e8fbabacdb396dae8ea5cf737f427209a5a', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/class/propal.class.php:2705|read|$modelpdf = getDolGlobalString(''PROPALE_ADDON_PDF_ODT_TOBILL'', $this->model_pdf);", "core/modules/propale/doc/doc_generic_proposal_odt.modules.php:205|read|$texte .= $form->selectarray(''value3'', $list, getDolGlobalString(''PROPALE_ADDON_PDF_ODT_TOBILL''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_DRAFT_WATERMARK', 'string', NULL, 'core', 'Defines the watermark text printed on draft proposal PDF documents.', 'Written at admin/propal.php:153. Read and applied in core/modules/propale/doc/pdf_cyan.modules.php:181-182 and pdf_azur.modules.php:214-215 where it is assigned to $this->watermark when the proposal is in draft status. The commented module definition at core/modules/modPropale.class.php:116 also references this constant.', 'Setting this value stamps the specified text as a watermark on all draft proposal PDFs; clearing it removes the watermark.', 'Any string to use as the watermark text on draft proposals; empty = no watermark', 0, 0, 'admin/propal.php|admin/propal.php', 1, '5fa8382054d5917d62967f76762024345d805bb31e5dbab7c360a9ad6caf2795', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:181|check|if ($object->status == $object::STATUS_DRAFT && getDolGlobalString(''PROPALE_DRAFT_WATERMARK'')) {", "core/modules/propale/doc/pdf_cyan.modules.php:182|read|$this->watermark = getDolGlobalString(''PROPALE_DRAFT_WATERMARK'');", "admin/propal.php:153|write|$res = dolibarr_set_const($db, \"PROPALE_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "core/modules/modPropale.class.php:116  /*$this->const[$r][0] = \"PROPALE_DRAFT_WATERMARK\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_KEEP_OLD_SIGNATURE_INFO', 'string', NULL, 'comm', 'Preserves the original signature date/user of a proposal instead of overwriting it each time the proposal is closed.', 'Checked in comm/propal/class/propal.class.php:2676 inside closeProposal(); when set, the existing date_signature/user_signature are kept (unless unset, in which case they are still initialized to now/current user), instead of always resetting them to the current date/user.', 'Setting it to true prevents the signature date and signing user from being overwritten on subsequent close/re-close operations, keeping the original signature record intact.', 'Boolean-like: true/1 keeps the old date_signature/fk_user_signature values instead of resetting them to now/current user.', 1, 0, NULL, 1, 'aab45a3877ba459dec08562ecc0d9fd3ac682ec8afd45e20fc78670dbf76741e', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/class/propal.class.php:2676|check|if (!getDolGlobalString(''PROPALE_KEEP_OLD_SIGNATURE_INFO'')) { $date_signature = $now; $fk_user_signature = $user->id; } else { ... }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_NOCHECK_ONSALE_PRODUCTS_ONVALID', 'string', NULL, 'comm', 'Skips the ''active/on-sale product'' check when validating a commercial proposal.', 'Checked in comm/propal/class/propal.class.php:2108 inside the valid() method; when not set, checkActiveProductInLines() is called and validation is blocked (return -1) if it fails.', 'Setting it to true bypasses the check that all product lines reference currently on-sale/active products, allowing validation of proposals containing discontinued/inactive products.', 'Boolean-like: true/1 disables the on-sale product check on validation.', 1, 0, NULL, 1, 'a8d3ab2d87821f5f279b810d25e9558ed08e4c02e6520a0b8d2e44f4d28aac0d', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/class/propal.class.php:2108|check|if (!getDolGlobalBool(''PROPALE_NOCHECK_ONSALE_PRODUCTS_ONVALID'') && !$this->checkActiveProductInLines()) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_SAPHIR_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the Saphir module for commercial proposal references.', 'Read in core/modules/propale/mod_propale_saphir.php at lines 95 and 147 to determine the mask string for generating proposal reference numbers. If unset or empty, an empty string is used as the mask.', 'Changing this value alters the format of commercial proposal reference numbers generated by the Saphir module; leaving it unset results in an empty mask.', 'Any valid mask string for proposal numbering; empty string if unset.', 1, 0, NULL, 1, 'df47c090d4327a7e7de6b725c7ebd471dee081d76678d3fb15f618757470be4d', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/propale/mod_propale_saphir.php:95|read|$mask = !getDolGlobalString(''PROPALE_SAPHIR_MASK'') ? '''' : $conf->global->PROPALE_SAPHIR_MASK;", "core/modules/propale/mod_propale_saphir.php:147|read|$mask = !getDolGlobalString(''PROPALE_SAPHIR_MASK'') ? '''' : $conf->global->PROPALE_SAPHIR_MASK;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPALE_VALIDITY_DURATION', 'string', NULL, 'admin', 'Sets the default validity duration (in days) applied to new commercial proposals.', 'Set via admin/propal.php:146 dolibarr_set_const, edited through the admin form input at admin/propal.php:653, and read in comm/propal/class/propal.class.php:464 into $this->duree_validite via getDolGlobalInt.', 'Changing it changes the default duree_validite value assigned to newly created proposals.', NULL, 0, 0, 'admin/propal.php|admin/propal.php', 1, '6c30d53fd3c7dd35f3eef9c2deca016d677cc0a80150b7176563150927be5a39', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"PROPALE_VALIDITY_DURATION\", $value, ''chaine'', 0, '''', $conf->entity);", "$this->duree_validite = getDolGlobalInt(''PROPALE_VALIDITY_DURATION'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_CLONE_DATE_DELIVERY', 'string', NULL, 'comm', 'Controls whether the delivery date is copied when cloning a proposal.', 'Checked in comm/propal/card.php at lines 220 and 2760; when set and a delivery date exists on the source proposal, the date is carried over to the clone.', 'Enabling this preserves the original delivery date on cloned proposals; leaving it unset means clones start without a delivery date.', 'Empty/unset = delivery date not cloned; any non-empty string = delivery date cloned if present.', 1, 0, NULL, 1, 'c9f98951ba124126eb813911d50953d9a6c80f43355fbde809bfa84f6c882c83', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/card.php:220|check|if (getDolGlobalString(''PROPAL_CLONE_DATE_DELIVERY'')) {", "comm/propal/card.php:2760|check|if (getDolGlobalString(''PROPAL_CLONE_DATE_DELIVERY'') && !empty($object->delivery_date)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_CLONE_ON_CREATE_PAGE', 'string', NULL, 'comm', 'Enables an option on the proposal creation page to select an existing proposal to clone.', 'When active, the proposal creation page displays a field allowing the user to pick an existing proposal to clone. Referenced in comm/propal/card.php at lines 518, 2664, and 2668.', 'Enabling this changes the creation workflow to offer a clone-from option; disabling it hides the clone selector and goes directly to a blank new proposal.', 'Empty/unset = standard creation page; truthy value = shows clone-selection field during creation.', 1, 0, NULL, 1, '79581f4c05d49a3e36ae5681320f226885d216e11a5991d5c39c1c17a8ec49b7', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/card.php:518  // If we select proposal to clone during creation (when option PROPAL_CLONE_ON_CREATE_PAGE is on)", "comm/propal/card.php:2664|check|if (!getDolGlobalString(''PROPAL_CLONE_ON_CREATE_PAGE'')) {", "comm/propal/card.php:2668|check|if (getDolGlobalString(''PROPAL_CLONE_ON_CREATE_PAGE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_CLOSE_REFUSED_TEMPLATE', 'string', NULL, 'core', 'Overrides the email template used to notify when a commercial proposal is closed as refused (PROPAL_CLOSE_REFUSED event).', 'Read in core/class/notify.class.php:812 in the same per-event-code switch as ORDER_CLOSE_TEMPLATE; sets $labeltouse for the PROPAL_CLOSE_REFUSED case, later resolved via $formmail->getEMailTemplate().', 'Setting it to an existing email template label/ref replaces the default EMailTextProposalClosedRefused text with that custom template for this notification event.', 'String: label/ref of an email template record; empty/unset falls back to the default built-in message.', 1, 0, NULL, 1, 'b67893c866902c0d69f6632d48b7a85c1a5b03480280979ce950b5c9f71d6ce6', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/notify.class.php:812|read|$labeltouse = getDolGlobalString(''PROPAL_CLOSE_REFUSED_TEMPLATE'');", "case ''PROPAL_CLOSE_REFUSED'': ... $labeltouse = getDolGlobalString(''PROPAL_CLOSE_REFUSED_TEMPLATE''); $mesg = $outputlangs->transnoentitiesnoconv(\"EMailTextProposalClosedRefused\", $link);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_DISABLE_AUTOUPDATE_ON_CLOSE', 'bool', NULL, 'comm', 'Disables automatic PDF regeneration of a proposal document when the proposal is closed (signed or refused).', 'Checked in comm/propal/class/propal.class.php:2719 inside closeProposal(), combined with MAIN_DISABLE_PDF_AUTOUPDATE; when neither is set, the code proceeds to rebuild the PDF using the previously selected model (see PROPALE_ADDON_PDF_ODT_TOBILL/ODT_CLOSED).', 'Setting it to true prevents the automatic document regeneration step that normally runs right after a proposal is closed, leaving the existing generated document unchanged.', 'Boolean-like: true/1 disables PDF auto-update on close (inferred from negation in the if-condition, alongside MAIN_DISABLE_PDF_AUTOUPDATE).', 1, 0, NULL, 1, '9dc2c728b0107ca16dac8a95222d11c5e0fbf446e09177bb993a6cd0bb090646', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/class/propal.class.php:2719|check|if (!getDolGlobalString(''MAIN_DISABLE_PDF_AUTOUPDATE'') && !getDolGlobalInt(''PROPAL_DISABLE_AUTOUPDATE_ON_CLOSE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_DISABLE_SIGNATURE', 'bool', NULL, 'core', 'Disables the customer signature block on proposal PDF documents.', 'Checked in four locations across pdf_cyan.modules.php and pdf_azur.modules.php. When set, the signature section height is forced to 0 and the signature block rendering is skipped (lines 347, 378, 931, 759). No admin UI write is present.', 'Setting this constant removes the customer signature area from proposal PDFs in both cyan and azur templates. Unsetting it restores the signature block with calculated height.', 'Truthy = signature block hidden; falsy or unset = signature block shown.', 1, 0, NULL, 1, '62604434ca45ffbf186b690a084f404a1706feef980176a4552d37d75d7ff984', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:931|check|if (!getDolGlobalString(''PROPAL_DISABLE_SIGNATURE'')) {", "core/modules/propale/doc/pdf_azur.modules.php:759|check|if (!getDolGlobalString(''PROPAL_DISABLE_SIGNATURE'')) {", "core/modules/propale/doc/pdf_cyan.modules.php:347|read|$heightforsignature = !getDolGlobalString(''PROPAL_DISABLE_SIGNATURE'') ? (pdfGetHeightForHtmlContent($pdf, $outputlangs->transnoentities(\"ProposalCustomerSignature\")) + 10) : 0;", "core/modules/propale/doc/pdf_azur.modules.php:378|read|$heightforsignature = !getDolGlobalString(''PROPAL_DISABLE_SIGNATURE'') ? (pdfGetHeightForHtmlContent($pdf, $outputlangs->transnoentities(\"ProposalCustomerSignature\")) + 10) : 0;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_DISALLOW_REOPEN', 'bool', NULL, 'comm', 'Forbids reopening a closed/signed commercial proposal even if the user would otherwise have permission to do so.', 'Checked in comm/propal/card.php:150, right after computing $usercanreopen from MAIN_USE_ADVANCED_PERMS and the propal_advance/reopen permission; if set it forces $usercanreopen = false.', 'Setting it to true removes the ReOpen action/button entirely for all users on proposals, regardless of their propal_advance rights.', 'Boolean; truthy disables reopening.', 1, 0, NULL, 1, '4940841366f7b900b1fe103b59c7c98c5f6d480c1f64d320020fe221d805c109', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:150: if (getDolGlobalBool(''PROPAL_DISALLOW_REOPEN'')) {", "comm/propal/card.php:151: $usercanreopen = false;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_ENABLE_NEGATIVE', 'bool', NULL, 'comm', 'Allows validating a draft proposal whose total_ttc is negative (in addition to the default rule requiring total_ttc >= 0).', 'Checked in comm/propal/card.php:3622, as an alternate OR-condition alongside the default ''$object->total_ttc >= 0'' check that gates display of the Validate button.', 'Enabling it lets proposals with a negative total (e.g. pure-credit/rebate proposals) be validated, which is otherwise blocked.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, '27395bb7418f95dbc74c467de480a4e78741c441083c6091855f5e6d86977b95', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:3622: || ($object->status == Propal::STATUS_DRAFT && getDolGlobalString(''PROPAL_ENABLE_NEGATIVE'') && count($object->lines) > 0)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_ENABLE_NEGATIVE_QTY', 'bool', NULL, 'comm', 'Allows negative quantities on proposal lines, bypassing the default validation error.', 'Checked in comm/propal/card.php:1326, in the line-add/update validation block, right after a comment noting unit price can already be negative for proposals.', 'When unset (default), a line with $qty < 0 triggers a ''FieldCannotBeNegative'' error and blocks the action; when set, negative quantities are accepted.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, 'f714edfab417a3e0286134cdaabf4334ea46985a58955cd30d87b57a1a6598f5', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:1326: if ($qty < 0 && !getDolGlobalString(''PROPAL_ENABLE_NEGATIVE_QTY'')) {", "comm/propal/card.php:1327: setEventMessages($langs->trans(''FieldCannotBeNegative'', $langs->transnoentitiesnoconv(''Qty'')), null, ''errors'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_LIST_SHOW_NOTES', 'bool', NULL, 'comm', 'Shows note icons/indicators next to the reference in the commercial proposal list.', 'Read in comm/propal/list.php:1945 as the last argument to $object->getNomUrl(), which controls whether note indicators are shown next to the proposal reference; default is 1 (shown) via getDolGlobalInt(''...'', 1).', 'Setting it to 0 hides the note indicator/icon next to each proposal''s reference in the list view; it is shown by default.', 'Integer flag passed to getNomUrl()''s notion-of-notes parameter; default 1 (show notes) per getDolGlobalInt(''PROPAL_LIST_SHOW_NOTES'', 1).', 1, 0, NULL, 1, '0a2d12df9a42d6f6d28e5f0e510268de7026b488e4fe541c20f65128d76f8d3b', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/list.php:1945|read|print $object->getNomUrl(1, '''', '''', 0, 1, getDolGlobalInt(''PROPAL_LIST_SHOW_NOTES'', 1));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_REOPEN_UNSIGNED_ONLY', 'string', NULL, 'comm', 'Restricts the ReOpen action on a proposal to only the STATUS_NOTSIGNED case, instead of also allowing reopen from signed/billed/canceled states.', 'Checked in comm/propal/card.php:3641: when set, ReOpen is only offered if status==STATUS_NOTSIGNED; when unset, ReOpen is offered for STATUS_SIGNED, STATUS_NOTSIGNED, STATUS_BILLED, or STATUS_CANCELED.', 'Enabling it narrows which proposal statuses can be reopened, hiding the ReOpen button for signed/billed/canceled proposals.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, '01d98d7b74a6340a69fb0d79368d6a7ab3ad06a7199b5e83a41c37adb6e8aeda', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:3641: if (((getDolGlobalString(''PROPAL_REOPEN_UNSIGNED_ONLY'') && $object->status == Propal::STATUS_NOTSIGNED) || (!getDolGlobalString(''PROPAL_REOPEN_UNSIGNED_ONLY'') && ($object->status ="]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_SIGNATURE_ON_ALL_PAGES', 'string', NULL, 'core', 'Stamps the online-signature image on every page of the proposal PDF instead of only the last page or the page detected via PROPAL_SIGNATURE_ON_SPECIFIC_PAGE/metadata.', 'Read twice in core/ajax/onlineSign.php: line 219 (inside the per-page loop, drawing the signature on each page if set or if it''s the specific page) and line 248 (fallback: if unset and no specific page was found, the signature is added once on the last page).', 'When set, dolPrintSignatureImage() is called for every page of the PDF; when unset, the signature is placed only once, either on the page resolved by PROPAL_SIGNATURE_ON_SPECIFIC_PAGE/metadata or, failing that, on the last processed page.', 'Truthy string = stamp signature on all pages; empty/unset = stamp once (specific page, metadata page, or last page).', 1, 0, NULL, 1, '1445468e48b7c8f99802f9f79e4629defce65baa5cb5fc2d752151589b7a9179', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:219: if (getDolGlobalString(\"PROPAL_SIGNATURE_ON_ALL_PAGES\") || $propalsignonspecificpage == $i) {", "core/ajax/onlineSign.php:248: if (!getDolGlobalString(\"PROPAL_SIGNATURE_ON_ALL_PAGES\") && !$propalsignonspecificpage) { // We do not found specific instruction or page for the signature, so we add it now we are on the last page."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_SIGNATURE_ON_SPECIFIC_PAGE', 'string', NULL, 'core', 'Forces the online-signature image to be stamped on one specific page (or, if negative, counted from the last page) of a proposal''s PDF instead of auto-detecting the page.', 'Read in core/ajax/onlineSign.php:196 as $propalsignonspecificpage = getDolGlobalInt(...); if negative, resolved to pagecount - abs(value) at line 205-207; if 0/empty, the page is instead auto-detected from a ''PAGESIGN=x'' PDF Keywords metadata tag.', 'Setting a positive integer N forces the signature onto page N; a negative integer counts back from the last page; leaving it empty falls back to metadata-based or last-page placement.', 'Positive int = explicit page number; negative int = offset from last page (pagecount - abs(value)); 0/unset = auto-detect via PDF Keywords ''PAGESIGN=x'' or last page.', 1, 0, NULL, 1, '07b845ca4fdd4efc7dd4efbb2263c9ff6e5d82325d6c16e6974df379fddb1a85', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:196: $propalsignonspecificpage = getDolGlobalInt(\"PROPAL_SIGNATURE_ON_SPECIFIC_PAGE\");", "core/ajax/onlineSign.php:205-206: if ($propalsignonspecificpage < 0) { $propalsignonspecificpage = $pagecount - abs($propalsignonspecificpage); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_SIGNATURE_WFORIMG', 'string', NULL, 'core', 'Overrides the width, in PDF units, of the online-signature image stamped on proposal PDFs.', 'Read in core/ajax/onlineSign.php at lines 233-234 and 261-262, used as $param[''wforimg''] passed to dolPrintSignatureImage(); if unset, it defaults to the remaining horizontal space (page width - 20 - xforimgstart).', 'Setting a value forces the signature image to a specific width; leaving it unset scales it to fill the remaining space to the right margin.', 'Numeric value = explicit width; unset = computed default ($s[''w''] - 20 - $param[''xforimgstart'']).', 1, 0, NULL, 1, 'd4f1f65a58173c8af98d96bd41e81e2b1aebce4262fe2862bb2b0864210cd4d5', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:233-236: if (getDolGlobalString(\"PROPAL_SIGNATURE_WFORIMG\")) { $param[''wforimg''] = getDolGlobalString(...); } else { $param[''wforimg''] = $s[''w''] - 20 - $param[''xforimgstart'']; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_SIGNATURE_XFORIMGSTART', 'string', NULL, 'core', 'Overrides the horizontal (X) start position, in PDF units, of the online-signature image stamped on proposal PDFs.', 'Read in core/ajax/onlineSign.php at lines 223-224 and 251-252, used as $param[''xforimgstart''] passed to dolPrintSignatureImage(); if unset, it defaults to (page width / 2) + 15, or 120 if width is unknown.', 'Setting a value repositions the signature image horizontally on the page; leaving it unset uses the computed default based on the page''s width.', 'Numeric value = explicit X start coordinate; unset = computed default (round($s[''w'']/2) + 15, or 120 if page width unknown).', 1, 0, NULL, 1, '0f6063d8f8ed0a1e09d86486beb641c942204e71f4967181c4a46c3780078ed4', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:223-226: if (getDolGlobalString(\"PROPAL_SIGNATURE_XFORIMGSTART\")) { $param[''xforimgstart''] = getDolGlobalString(...); } else { $param[''xforimgstart''] = (empty($s[''w'']) ? 120 : round($s[''w''] / 2) + 15); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_SIGNATURE_YFORIMGSTART', 'string', NULL, 'core', 'Overrides the vertical (Y) start position, in PDF units, of the online-signature image stamped on proposal PDFs.', 'Read in core/ajax/onlineSign.php at lines 228-229 and 256-257, used as $param[''yforimgstart''] passed to dolPrintSignatureImage(); if unset, it defaults to (page height - 60), or 240 if height is unknown.', 'Setting a value repositions the signature image vertically on the page; leaving it unset uses the computed default based on the page''s height.', 'Numeric value = explicit Y start coordinate; unset = computed default ($s[''h''] - 60, or 240 if page height unknown).', 1, 0, NULL, 1, '9d1f3682da4e376023f8b4806c0404879449b982a35eb4151ff1e572c38e4869', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:228-231: if (getDolGlobalString(\"PROPAL_SIGNATURE_YFORIMGSTART\")) { $param[''yforimgstart''] = getDolGlobalString(...); } else { $param[''yforimgstart''] = (empty($s[''h'']) ? 240 : $s[''h''] - 60); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPAL_SKIP_ACCEPT_REFUSE', 'string', NULL, 'comm', 'Bypasses the accept/refuse step in the proposal workflow, allowing direct transition from draft or validated to signed/refused.', 'Checked 8 times across comm/propal/card.php and comm/propal/list.php; when set, the status check at card.php:833 allows sign action from draft, card.php:915 sets new status to STATUS_DRAFT instead of STATUS_VALIDATED on reopen, and the accept/refuse buttons at card.php:2783, 2929, 3706 are hidden.', 'Setting this simplifies the proposal workflow by removing the intermediate accept/refuse status, which changes available actions and button labels.', 'Empty/unset = standard accept/refuse workflow; any non-empty string = skip accept/refuse step.', 1, 0, NULL, 1, '4760d8a50933dbab89f553aae3a7a3f5a948af07fe83cde42f3e4d6ef83b4d60', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/card.php:833|check|if ($object->status == $object::STATUS_VALIDATED || (getDolGlobalString(''PROPAL_SKIP_ACCEPT_REFUSE'') && $object->status == $object::STATUS_DRAFT)) {", "comm/propal/card.php:915|read|$newstatus = (getDolGlobalInt(''PROPAL_SKIP_ACCEPT_REFUSE'') ? Propal::STATUS_DRAFT : Propal::STATUS_VALIDATED);", "comm/propal/card.php:2783|check|if (!getDolGlobalString(''PROPAL_SKIP_ACCEPT_REFUSE'')) {", "comm/propal/list.php:507|check|if ($tmpproposal->status == $tmpproposal::STATUS_VALIDATED || (getDolGlobalString(''PROPAL_SKIP_ACCEPT_REFUSE'') && $tmpproposal->status == $tmpproposal::STATUS_DRAFT)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'core', 'Enables an external download link for commercial proposal documents.', 'Checked in core/class/commonobject.class.php:6376 and core/lib/functions.lib.php:10728. When set, a public download link is generated for proposal (propal) objects.', 'Enabling this constant exposes proposal documents via a public URL; disabling it removes the external download option.', 'Non-zero/non-empty = external download enabled; 0 or unset = disabled', 1, 0, NULL, 1, '1d3a9171ec64722a5c93f0799dc2821481dd5cc15665cbdbef757b76f3b2985e', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:6376|check|if (getDolGlobalInt(\"PROPOSAL_ALLOW_EXTERNAL_DOWNLOAD\")) {", "core/lib/functions.lib.php:10728|check|if (getDolGlobalString(''PROPOSAL_ALLOW_EXTERNAL_DOWNLOAD'') && is_object($object) && $object->element == ''propal'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_ALLOW_ONLINESIGN', 'bool', NULL, 'admin', 'Enables the online electronic signature feature for commercial proposals.', 'Set via admin/propal.php:166 dolibarr_set_const (from GETPOST alpha), checked at admin/propal.php:701, core/class/commonobject.class.php:6384, and read in comm/propal/card.php:3829 into $useonlinesignature, plus used to enable a ''signature_link'' field in webportal/class/html.formlistwebportal.class.php.', 'When enabled, proposal cards and the web portal show the online-signature link/feature ($useonlinesignature) for proposals.', NULL, 0, 0, 'admin/propal.php|admin/propal.php', 1, '2388fde0b85c1152c7fc506167453e4d9825ae92abfda00f48f4a237c9d2388d', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"PROPOSAL_ALLOW_ONLINESIGN\", GETPOST(''PROPOSAL_ALLOW_ONLINESIGN'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$useonlinesignature = getDolGlobalInt(''PROPOSAL_ALLOW_ONLINESIGN'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_ARE_NOT_BILLABLE', 'string', NULL, 'comm', 'Prevents the creation of invoices from signed proposals.', 'When set, the ''create invoice'' action is hidden on signed proposals. The check appears twice in comm/propal/card.php (lines 3671 and 3695), covering both standard and deposit invoice buttons.', 'Enabling this constant blocks the billing workflow from proposals, forcing invoices to be created independently.', 'Empty/unset = signed proposals can generate invoices; truthy value = invoice creation from proposals is disabled.', 1, 0, NULL, 1, '0345cf025d8cf05555af3c83673887d8126367c85f419ebe56074a17db6a6b5c', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/card.php:3671|check|if ($object->status == Propal::STATUS_SIGNED && !getDolGlobalString(''PROPOSAL_ARE_NOT_BILLABLE'')) {", "comm/propal/card.php:3695|check|if ($object->status == Propal::STATUS_SIGNED && !getDolGlobalString(''PROPOSAL_ARE_NOT_BILLABLE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_AUTO_ADD_AUTHOR_AS_CONTACT', 'string', NULL, 'comm', 'When creating a commercial proposal, automatically adds the creating user as an internal ''SALESREPFOLL'' (sales rep following) contact on the proposal.', 'Checked in comm/propal/card.php:764, right after the explicit contact from GETPOST(''contactid'') is added; if set, calls $object->add_contact($user->id, ''SALESREPFOLL'', ''internal'').', 'Enabling it ensures every new proposal automatically gets its creator attached as a following sales rep contact, without manual selection.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, 'f1016fe22d1939c6636e31cd30851d27cd216781d05b775649662ccfc09862e8', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:764: if (getDolGlobalString(''PROPOSAL_AUTO_ADD_AUTHOR_AS_CONTACT'')) {", "comm/propal/card.php:765: $result = $object->add_contact($user->id, ''SALESREPFOLL'', ''internal'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated commercial proposal documents.', 'Written from admin/propal.php:160 via dolibarr_set_const() when the admin saves the commercial proposal module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated proposal documents/PDFs; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/propal.php', 1, 'ab0ab583b2785ec547cf319bdfefc466ded981f499b9e4fb3968a009d2fd5bc1', 'v2', '2026-07-24T07:05:23+00:00', '["admin/propal.php:160|write|$res = dolibarr_set_const($db, \"PROPOSAL_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_HIDE_CALCULATED_WEIGHT_VOLUME', 'bool', NULL, 'comm', 'Hides the calculated total weight/volume rows on the proposal view page.', 'Checked in comm/propal/card.php:3363 (negated); when unset (default), $object->getTotalWeightVolume() results are printed as extra rows on the card.', 'Enabling it removes the CalculatedWeight/CalculatedVolume display rows from the proposal card view.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, 'cfb4bd132ab118bd0ccb269ddf703c54cde52c101389cd374c09e381c9f56c7e', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:3363: if (!getDolGlobalString(''PROPOSAL_HIDE_CALCULATED_WEIGHT_VOLUME'')) {", "comm/propal/card.php:3364: $tmparray = $object->getTotalWeightVolume();"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_IMAGE_PUBLIC_SIGN', 'string', NULL, 'public', 'URL/path of an image shown on the public online-signature page when signing a commercial proposal.', 'Used in public/onlinesign/newonlinesign.php:283-285: when $source == ''proposal'' and the constant is set, an <img> tag with this value as src is printed on the page.', 'Setting it displays a custom image (e.g. banner/logo) on the public proposal-signature page; leaving it empty shows no such image.', 'Any string usable as an image src URL.', 1, 0, NULL, 1, '2a5af582a975eb9d5f346b059407a9766d6388d441b046d1a870f6ec8deec861', 'v2', '2026-07-24T07:05:23+00:00', '["public/onlinesign/newonlinesign.php:283: if ($source == ''proposal'' && getDolGlobalString(''PROPOSAL_IMAGE_PUBLIC_SIGN'')) {", "public/onlinesign/newonlinesign.php:285: print ''<img id=\"idPROPOSAL_IMAGE_PUBLIC_INTERFACE\" src=\"'' . getDolGlobalString(''PROPOSAL_IMAGE_PUBLIC_SIGN'').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_ONLINE_SIGNATURE_SECURITY_TOKEN', 'string', NULL, 'admin', 'Security token/salt seed used to secure the online proposal signature process.', 'Set via admin/propal.php:172 dolibarr_set_const (from GETPOST alpha), edited via the input field at admin/propal.php:704, and read as $securekeyseed (with a default salt fallback) in public/onlinesign/newonlinesign.php, core/ajax/onlineSign.php, and core/lib/signature.lib.php.', 'Changing it changes the seed used to compute the secure key for online signature links; a value must match across all these consuming files to keep existing signature links valid.', NULL, 0, 0, 'admin/propal.php|admin/propal.php', 1, 'e6ddadd994ee1854d4dd40fa7a5dee3823bd6f70b58b40cf27f206559bbea832', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"PROPOSAL_ONLINE_SIGNATURE_SECURITY_TOKEN\", GETPOST(''PROPOSAL_ONLINE_SIGNATURE_SECURITY_TOKEN'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$securekeyseed = getDolGlobalString(''PROPOSAL_ONLINE_SIGNATURE_SECURITY_TOKEN'', $defaultsalt);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_PDF_HIDE_DELIVERYMODE', 'bool', NULL, 'core', 'When enabled, hides the delivery/shipping mode line from generated Cyan and Azur proposal PDFs.', 'Checked identically in core/modules/propale/doc/pdf_cyan.modules.php:1139 and core/modules/propale/doc/pdf_azur.modules.php:986, both gating the block that prints the shipping method availability text (only shown when $object->shipping_method_id > 0).', 'Enabling it removes the delivery-mode/shipping-method line that would otherwise print on these proposal PDFs when a shipping method is set on the proposal.', 'Boolean: true/1 hides the delivery mode line on the PDF.', 0, 0, NULL, 1, '64425c7ae00dced32d3cf941df4c5f23f9906d6cb43aafb5325224c1cbfdce70', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/propale/doc/pdf_cyan.modules.php:1139|check|if (!getDolGlobalString(''PROPOSAL_PDF_HIDE_DELIVERYMODE'') && $object->shipping_method_id > 0) {", "core/modules/propale/doc/pdf_azur.modules.php:986|check|if (!getDolGlobalString(''PROPOSAL_PDF_HIDE_DELIVERYMODE'') && $object->shipping_method_id > 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_PDF_HIDE_PAYMENTMODE', 'bool', NULL, 'core', 'Hides the payment mode section on proposal PDF documents.', 'Written in admin/pdf_other.php:93 via dolibarr_set_const, and checked in pdf_cyan.modules.php:1178 and pdf_azur.modules.php:1026. The admin UI is admin/pdf_other.php.', 'Setting this constant removes the payment mode block from proposal PDFs in both cyan and azur templates. Unsetting it allows the section to render.', 'Truthy = payment mode hidden on proposal PDF; falsy or unset = payment mode shown.', 0, 0, 'admin/pdf_other.php', 1, 'e5649330e92866794ee3c17523f913d5d3841472aaba4dc09c92a11789b19fc8', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:93|write|dolibarr_set_const($db, \"PROPOSAL_PDF_HIDE_PAYMENTMODE\", GETPOST(\"PROPOSAL_PDF_HIDE_PAYMENTMODE\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/propale/doc/pdf_cyan.modules.php:1178|check|if (!getDolGlobalString(''PROPOSAL_PDF_HIDE_PAYMENTMODE'')) {", "core/modules/propale/doc/pdf_azur.modules.php:1026|check|if (!getDolGlobalString(''PROPOSAL_PDF_HIDE_PAYMENTMODE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_PDF_HIDE_PAYMENTTERM', 'bool', NULL, 'core', 'Hides the payment terms section on proposal PDF documents.', 'Written in admin/pdf_other.php:90 via dolibarr_set_const, and checked in pdf_cyan.modules.php:1160 and pdf_azur.modules.php:1008. The admin UI is admin/pdf_other.php.', 'Setting this constant removes the payment terms block from proposal PDFs in both cyan and azur templates. Unsetting it restores the section when a payment condition code is present.', 'Truthy = payment terms hidden on proposal PDF; falsy or unset = payment terms shown when applicable.', 0, 0, 'admin/pdf_other.php', 1, '60f43f3625a2e3b687ed4f118b563ca5cf3e1e3ac5577a819ad04c6d115d5fe2', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:90|write|dolibarr_set_const($db, \"PROPOSAL_PDF_HIDE_PAYMENTTERM\", GETPOST(\"PROPOSAL_PDF_HIDE_PAYMENTTERM\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/propale/doc/pdf_cyan.modules.php:1160|check|if (!getDolGlobalString(''PROPOSAL_PDF_HIDE_PAYMENTTERM'') && $object->cond_reglement_code) {", "core/modules/propale/doc/pdf_azur.modules.php:1008|check|if (!getDolGlobalString(''PROPOSAL_PDF_HIDE_PAYMENTTERM'') && $object->cond_reglement_code) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_SENDBYEMAIL_FOR_ALL_STATUS', 'string', NULL, 'comm', 'Allows sending a proposal by email regardless of its status, including drafts, instead of only VALIDATED/SIGNED proposals.', 'Checked in comm/propal/card.php:3652 (card Send button visibility) and again in core/actions_massactions.inc.php:342, whose comment says it exists to ''honour the same per-object hidden constants used by the Send by email button on the card pages... so the behaviour is consistent between the single-object action and the mass action''.', 'Enabling it exposes the Send-by-email button/action for draft proposals too, both on the single-object card and in mass actions; disabled (default) blocks draft proposals from being mass-emailed.', 'Boolean-like (truthy/falsy).', 0, 0, NULL, 1, '586d2751253dc152236f84b41b914555446522fa3df9582a22dcaac50111bb8f', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:3652: if ($object->status == Propal::STATUS_VALIDATED || $object->status == Propal::STATUS_SIGNED || getDolGlobalString(''PROPOSAL_SENDBYEMAIL_FOR_ALL_STATUS'')) {", "core/actions_massactions.inc.php: // Honour the same per-object hidden constants used by the \"Send by email\" button on the card pages (comm/propal/card.php, commande/card.php, compta/facture/card.php)", "core/actions_massactions.inc.php:342: if ($objectclass == ''Propal'' && $objectobj->status == Propal::STATUS_DRAFT && !getDolGlobalString(''PROPOSAL_SENDBYEMAIL_FOR_ALL_STATUS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_SHOW_INVOICED_AMOUNT', 'bool', NULL, 'comm', 'Enables the display of invoiced HT and TTC amount columns in the proposals list view.', 'Read in comm/propal/list.php:258-266. When set, the columns p.total_ht_invoiced (AmountInvoicedHT) and p.total_invoiced (AmountInvoicedTTC), as well as their multicurrency equivalents, are made available in the proposals list.', 'If enabled, users can see how much of each proposal has been invoiced directly from the list. If unset, those columns are not rendered.', 'Non-empty string = enabled (columns available). Empty/unset = columns hidden.', 1, 0, NULL, 1, '4990ccd11b431e00c9d3b45fd64b755d755ba32ef5b8c380c4e8ea8236f223a2', 'v2', '2026-04-21T13:29:58+00:00', '["comm/propal/list.php:258|read|''p.total_ht_invoiced'' => array(''label'' => \"AmountInvoicedHT\", ''checked'' => ''0'', ''enabled'' => getDolGlobalString(''PROPOSAL_SHOW_INVOICED_AMOUNT'')),", "comm/propal/list.php:259|read|''p.total_invoiced'' => array(''label'' => \"AmountInvoicedTTC\", ''checked'' => ''0'', ''enabled'' => getDolGlobalString(''PROPOSAL_SHOW_INVOICED_AMOUNT'')),", "comm/propal/list.php:265|read|''p.multicurrency_total_ht_invoiced'' => array(''label'' => ''MulticurrencyAmountInvoicedHT'', ..., ''enabled'' => ... getDolGlobalString(''PROPOSAL_SHOW_INVOICED_AMOUNT'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_SHOW_SHIPPING_ADDRESS', 'bool', NULL, 'admin', 'Controls whether the shipping address is printed on proposal PDFs.', 'Written in admin/pdf_other.php at line 99 and displayed as a select at line 313. Checked in core/modules/propale/doc/pdf_cyan.modules.php at line 1968 via getDolGlobalInt to conditionally render the shipping address block.', 'Enabling this constant causes proposal PDFs to include the customer''s shipping address. Disabling it omits the shipping address from proposals.', 'Non-zero integer to show shipping address; 0 or unset to hide it.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php', 1, '0283a7553beeba5d5c757b63e8d7873039a90263bc73a3b9b378bb88fc56c0ca', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:99|write|dolibarr_set_const($db, \"PROPOSAL_SHOW_SHIPPING_ADDRESS\", GETPOSTINT(\"PROPOSAL_SHOW_SHIPPING_ADDRESS\"), ''chaine'', 0, '''', $conf->entity);", "core/modules/propale/doc/pdf_cyan.modules.php:1968|check|if (getDolGlobalInt(''PROPOSAL_SHOW_SHIPPING_ADDRESS'')) {", "admin/pdf_other.php:313|read|print $form->selectarray(\"PROPOSAL_SHOW_SHIPPING_ADDRESS\", $arrval, getDolGlobalString(''PROPOSAL_SHOW_SHIPPING_ADDRESS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PROPOSAL_SUGGEST_DOWN_PAYMENT_INVOICE_CREATION', 'string', NULL, 'comm', 'Offers to create a down-payment invoice automatically when closing a proposal as signed, based on the payment terms'' deposit percentage.', 'Checked in comm/propal/card.php:2838, with an explicit comment: ''This is a hidden option: Suggestion to create invoice during proposal signature is not enabled by default... may also break step of creating an order when invoicing must be done from orders and not from proposal''.', 'Enabling it can trigger deposit-invoice creation prompts at signature time, which the code comment warns may conflict with workflows that expect invoicing only from orders.', 'Boolean-like (int via getDolGlobalInt); documented as a hidden/non-default option.', 1, 0, NULL, 1, '0ceb4a8a06b6928c8bddd304be018bb3621e18521d678e3370972b3f7aa54842', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:2836: // This is a hidden option:", "comm/propal/card.php:2837: // Suggestion to create invoice during proposal signature is not enabled by default.", "comm/propal/card.php:2838: // Such choice should be managed by the workflow module and trigger. This option generates conflicts with some setup.", "comm/propal/card.php:2839: // It may also break step of creating an order when invoicing must be done from orders and not from proposal"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('PSQL_USE_UNACCENT', 'bool', NULL, 'core', 'On PostgreSQL, wraps LIKE-converted (ILIKE) query fields with the unaccent() SQL function so LIKE searches ignore accents.', 'Used in core/db/pgsql.class.php:331 inside convertSQLFromMysql(): after MySQL ''LIKE'' is rewritten to PostgreSQL ''ILIKE'', if this constant is set and at least one such replacement occurred, the field before ILIKE is wrapped in unaccent(...).', 'Enabling it makes case-insensitive LIKE searches on PostgreSQL also accent-insensitive, but requires the PostgreSQL ''unaccent'' extension to be installed first, per the code''s own reference comment.', 'Boolean-like: truthy enables wrapping ILIKE search fields with unaccent(); only relevant when using the PostgreSQL database driver.', 1, 0, NULL, 1, '260f9ec72a62977c24c6c090025f7e0db8e64a91c23d0fb4c36fde48fb22feac', 'v2', '2026-07-24T07:05:23+00:00', '["core/db/pgsql.class.php:331|check|if (getDolGlobalString(''PSQL_USE_UNACCENT'') && $count_like > 0) {", "core/db/pgsql.class.php:332|// @see https://docs.PostgreSQL.fr/11/unaccent.html : ''unaccent()'' function must be installed before"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('QUICKMEMO_AUTO_RESIZE_MAX_FONT_SIZE', 'string', NULL, 'quickmemo', 'Sets the maximum font size (in em, scale factor) used when QuickMemo auto-resizes memo text to fit its box.', 'Defined and edited via the QuickMemo admin setup page (quickmemo/admin/setup.php:138-154, a FormSetup item with a numeric input defaulting to 1.4) and consumed as a float in Memo''s auto-resize logic (quickmemo/class/memo.class.php:1646).', 'Raising the value allows memo text to grow larger before the auto-resize algorithm caps it; the default is 1.4 if unset.', 'Numeric (float), default 1.4 (per getDolGlobalFloat(''QUICKMEMO_AUTO_RESIZE_MAX_FONT_SIZE'', 1.4)).', 0, 0, 'quickmemo/admin/setup.php', 1, 'c28ef9c48021daf117dba7f9ba96ebbaca08b6901b919bc6b04697cde9b40126', 'v2', '2026-07-24T07:05:23+00:00', '["quickmemo/class/memo.class.php:1646: $autoResizeFontMax = getDolGlobalFloat(''QUICKMEMO_AUTO_RESIZE_MAX_FONT_SIZE'', 1.4);", "quickmemo/admin/setup.php:154: value=\"'' . getDolGlobalString(''QUICKMEMO_AUTO_RESIZE_MAX_FONT_SIZE'', 1.4) . ''\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('QUICKMEMO_AUTO_RESIZE_MIN_FONT_SIZE', 'string', NULL, 'quickmemo', 'Sets the minimum font size (in em, scale factor) used when QuickMemo auto-resizes memo text to fit its box.', 'Defined and edited via the QuickMemo admin setup page (quickmemo/admin/setup.php:115-131, a FormSetup item with a numeric input defaulting to 1) and consumed as a float in Memo''s auto-resize logic (quickmemo/class/memo.class.php:1645).', 'Lowering the value allows memo text to shrink further before the auto-resize algorithm stops; the default is 1 if unset.', 'Numeric (float), default 1 (per getDolGlobalFloat(''QUICKMEMO_AUTO_RESIZE_MIN_FONT_SIZE'', 1)).', 0, 0, 'quickmemo/admin/setup.php', 1, 'b70afbe36874adad02c389acc99e58a7b0dcc5c2a6f5234dc5abe690bed76508', 'v2', '2026-07-24T07:05:23+00:00', '["quickmemo/class/memo.class.php:1645: $autoResizeFontMin = getDolGlobalFloat(''QUICKMEMO_AUTO_RESIZE_MIN_FONT_SIZE'', 1);", "quickmemo/admin/setup.php:131: value=\"'' . getDolGlobalString(''QUICKMEMO_AUTO_RESIZE_MIN_FONT_SIZE'', 1) . ''\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('QUICKMEMO_COLORS_PRESET', 'string', NULL, 'quickmemo', 'Stores the user-customized comma-separated list of hex colors offered in the QuickMemo color picker.', 'Set via the QuickMemo admin setup page (quickmemo/admin/setup.php:75-105, a color-manager widget writing a hidden input named QUICKMEMO_COLORS_PRESET) and read in Memo::getColorPreset() (quickmemo/class/memo.class.php:1258) which explodes it on commas and validates each entry as a 6-digit hex color.', 'Changing it customizes the palette of memo colors proposed to users; invalid (non 6-digit-hex) entries are silently dropped, and if the result is empty the code falls back to a hardcoded default palette.', 'Comma-separated list of 6-digit hex colors (e.g. ''#fff8a6,#ffd6d6,...''); entries not matching /^#[a-f0-9]{6}$/i are discarded.', 0, 0, NULL, 1, '268b0be5d661b5e7c43d36c0f509810f83bbdfdc466ecac44628c7a0af43e8f9', 'v2', '2026-07-24T07:05:23+00:00', '["quickmemo/class/memo.class.php:1258: $colorsConf = getDolGlobalString(''QUICKMEMO_COLORS_PRESET'');", "quickmemo/admin/setup.php:105: <input type=\"hidden\" name=\"QUICKMEMO_COLORS_PRESET\" id=\"colorsInput\">", "quickmemo/class/memo.class.php:1262: if (!preg_match(''/^#[a-f0-9]{6}$/i'', $color)) { unset($colors[$iColor]); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('QUICKMEMO_DISABLE_AUTO_RESIZE_FONT_SIZE', 'bool', NULL, 'quickmemo', 'Disables the automatic font-size resizing feature in QuickMemo notes.', 'Set via quickmemo/admin/setup.php:331 (exposed as a JS const) and read in quickmemo/class/memo.class.php:1668 to compute the ''autoResizeFontSize'' flag as its negation.', 'When enabled, QuickMemo''s autoResizeFontSize behavior is turned off (the memo editor will not auto-resize font size).', NULL, 0, 0, 'quickmemo/admin/setup.php', 1, '2cd0a40c77226758a4dbd9bed11b62e47ee2919412442cf5332ef31cbdbd3abd', 'v2', '2026-07-24T06:41:12+00:00', '["const QUICKMEMO_DISABLE_AUTO_RESIZE_FONT_SIZE = <?php print json_encode(getDolGlobalInt(''QUICKMEMO_DISABLE_AUTO_RESIZE_FONT_SIZE'')); ?>;", "''autoResizeFontSize'' => !getDolGlobalInt(''QUICKMEMO_DISABLE_AUTO_RESIZE_FONT_SIZE''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEIPT_PRINTER_NB_CHARACT_BY_LINE', 'string', NULL, 'takepos', 'Sets the number of characters per line used when formatting tickets for a physical receipt printer in TakePOS.', 'Read in takepos/class/dolreceiptprinter.class.php:787 with default 48, used right before parsing/printing the receipt template (xml_parse_into_struct) to lay out ticket text.', 'Changing the value reflows the printed receipt text to fit a printer with a different character width per line; default is 48 characters if unset.', 'Integer character count per line; default 48.', 1, 0, NULL, 1, 'b8da37381790b8c84810225d1db5e84368d7607c34bb7f7504d67750febfe02c', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/class/dolreceiptprinter.class.php:787: $nbcharactbyline = getDolGlobalInt(''RECEIPT_PRINTER_NB_CHARACT_BY_LINE'', 48);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_ADDON_NUMBER', 'string', NULL, 'admin', 'Specifies the numbering module class used to generate reception reference numbers.', 'Written via admin/reception_setup.php (lines 68, 171). Read in reception/class/reception.class.php (lines 241-245) to load the class file (`$file = getDolGlobalString(''RECEPTION_ADDON_NUMBER'') . ".php"`) and instantiate the numbering module.', 'Changing this value switches the numbering algorithm for reception records; the default is `mod_reception_beryl`.', 'String (module class name, e.g. ''mod_reception_beryl''); empty triggers a fallback to the default module.', 0, 0, 'admin/reception_setup.php|admin/reception_setup.php|admin/reception_setup.php|admin/reception_setup.php', 1, 'bd3eb79ba85c83f8de4dcddbae9385daea956f878c5ac004f91937cbef4d21e0', 'v2', '2026-04-21T11:16:15+00:00', '["admin/reception_setup.php:68|write|$conf->global->RECEPTION_ADDON_NUMBER = ''mod_reception_beryl'';", "admin/reception_setup.php:171|write|dolibarr_set_const($db, \"RECEPTION_ADDON_NUMBER\", $value, ''chaine'', 0, '''', $conf->entity);", "reception/class/reception.class.php:244|read|$file = getDolGlobalString(''RECEPTION_ADDON_NUMBER'') . \".php\";", "reception/class/reception.class.php:245|read|$classname = getDolGlobalString(''RECEPTION_ADDON_NUMBER'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_ADDON_PDF', 'string', NULL, 'admin', 'Specifies the PDF template module used to generate reception documents.', 'Set via admin/reception_setup.php (multiple read/write occurrences). The value is read in reception/class/reception.class.php:2486-2487 to select the PDF model, and displayed in a dropdown in reception/card.php:1304.', 'Changing this value switches the PDF template used for all reception document generation; an unset value falls back to a default template.', 'String: name of the PDF addon module (e.g. ''reception_rouget''); empty = use default', 0, 0, 'admin/reception_setup.php|admin/reception_setup.php|admin/reception_setup.php|admin/reception_setup.php|admin/reception_setup.php', 1, '41041560e88cd3bbc342ff83342d62ae17b1ac79c0e2b440ebc049c9dbc49a7f', 'v2', '2026-04-21T11:16:15+00:00', '["reception/class/reception.class.php:2486|read|} elseif (getDolGlobalString(''RECEPTION_ADDON_PDF'')) {", "reception/class/reception.class.php:2487|read|$modele = getDolGlobalString(''RECEPTION_ADDON_PDF'');", "admin/reception_setup.php:159|write|if (dolibarr_set_const($db, \"RECEPTION_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "reception/card.php:1304|read|print $form->selectarray(''model'', $list, getDolGlobalString(''RECEPTION_ADDON_PDF''), 0, 0, 0, '''', 0, 0, 0, '''', ''maxwidth200 widthcentpercentminusx'', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Stores the directory path(s) to scan for the ODT template used to generate reception documents.', 'Registered as a module constant name in core/modules/modReception.class.php:94 and used as the ODT template scan-directory setting in core/modules/reception/doc/doc_generic_reception_odt.modules.php:61,111,118,163,187 (also referenced as `keyforuploaddir` for the doc-template upload/delete UI at document.php).', 'Setting/changing it changes which directory Dolibarr scans to find the ODT template(s) used for reception (goods-receipt) document generation; managed through the module''s document-template admin UI (upload/delete file actions reference this constant as keyforuploaddir).', 'Path string: directory path(s) to scan for reception ODT templates; managed via file upload UI, not free-typed.', 0, 0, NULL, 1, '9aa9ae7cca21e360bf1cb9277597ca2ddb90b7727389b35ab70e292750f94785', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/reception/doc/doc_generic_reception_odt.modules.php:61: $this->scandir = ''RECEPTION_ADDON_PDF_ODT_PATH''; // Name of constant that is used to save list of directories to scan", "core/modules/reception/doc/doc_generic_reception_odt.modules.php:111: $odtPath = trim(getDolGlobalString(''RECEPTION_ADDON_PDF_ODT_PATH''));", "core/modules/reception/doc/doc_generic_reception_odt.modules.php:187: ''<input type=\"hidden\" value=\"RECEPTION_ADDON_PDF_ODT_PATH\" name=\"keyforuploaddir\">''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_ADD_CONTACTS_IN_EXPORT', 'string', NULL, 'core', 'Includes contact records in the data export for the Reception module.', 'When set, core/modules/modReception.class.php adds contact-related rows to the export definition at lines 191, 208, 212, and 240, conditioned on both the presence of contact IDs and this constant.', 'Enabling this adds contact data columns to reception exports; disabling it limits exports to reception records without contact details.', 'Any non-empty string value enables contact inclusion in reception exports.', 1, 0, NULL, 1, '9b9143936803f761f4fd7e14dbbf9d53300d949fb1517dd75b7491aaf60badcd', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/modReception.class.php:191|check|if ($idcontacts && getDolGlobalString(''RECEPTION_ADD_CONTACTS_IN_EXPORT'')) {", "core/modules/modReception.class.php:208|check|if ($idcontacts && getDolGlobalString(''RECEPTION_ADD_CONTACTS_IN_EXPORT'')) {", "core/modules/modReception.class.php:212|check|if ($idcontacts && getDolGlobalString(''RECEPTION_ADD_CONTACTS_IN_EXPORT'')) {", "core/modules/modReception.class.php:240|check|if ($idcontacts && getDolGlobalString(''RECEPTION_ADD_CONTACTS_IN_EXPORT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_ALLOW_NEGATIVE_QTY', 'bool', NULL, 'reception', 'Allows negative quantities to be entered on reception lines.', 'Checked in reception/class/reception.class.php:706: `if ($qty == 0 || ($qty < 0 && !getDolGlobalInt(''RECEPTION_ALLOW_NEGATIVE_QTY'')))`. Also referenced in a commented-out condition in reception/card.php:466.', 'Enabling this setting permits recording negative received quantities; by default, negative quantities are rejected.', '0 or empty = negative quantities rejected; 1 = negative quantities allowed.', 1, 0, NULL, 1, 'a42ee74a4d5703f59b387f4b24a97c29df62910dd8213281ca75c7af62cc0d9a', 'v2', '2026-04-21T11:16:15+00:00', '["reception/class/reception.class.php:706|check|if ($qty == 0 || ($qty < 0 && !getDolGlobalInt(''RECEPTION_ALLOW_NEGATIVE_QTY''))) {", "reception/card.php:466  //if (GETPOST($qty, ''int'') > 0 || (GETPOST($qty, ''int'') == 0 && getDolGlobalString(''RECEPTION_GETS_ALL_ORDER_PRODUCTS'')) || (GETPOST($qty, ''int'') < 0 && getDolGlobalString(''RECEPTION_ALLOW_NEGATIVE_QTY''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_DRAFT_WATERMARK', 'string', NULL, 'core', 'Sets the watermark text printed on draft reception PDF documents.', 'Written via admin/reception_setup.php:102 and read in core/modules/reception/doc/pdf_squille.modules.php:164-165 to apply the watermark when the reception is in draft status.', 'Setting this constant causes draft reception PDFs to display the specified watermark text; clearing it removes the watermark.', 'String: watermark text to overlay on draft reception PDFs.', 0, 0, 'admin/reception_setup.php', 1, 'e744844035d80f50245ff44035ed4175aa8f2fcd21543381079f5125ba2bcc51', 'v2', '2026-04-21T13:50:40+00:00', '["admin/reception_setup.php:102|write|$res = dolibarr_set_const($db, \"RECEPTION_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "core/modules/reception/doc/pdf_squille.modules.php:164|check|if ($object->status == $object::STATUS_DRAFT && (getDolGlobalString(''RECEPTION_DRAFT_WATERMARK''))) {", "core/modules/reception/doc/pdf_squille.modules.php:165|read|$this->watermark = getDolGlobalString(''RECEPTION_DRAFT_WATERMARK'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated reception documents.', 'Written from admin/reception_setup.php:95 via dolibarr_set_const() when the admin saves the reception module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated reception documents; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/reception_setup.php', 1, '60b7b740f8f210c05567152b85dbf889bd8d4bd8ec8a45ca37c2fe8c75279332', 'v2', '2026-07-24T07:05:23+00:00', '["admin/reception_setup.php:95|write|$res = dolibarr_set_const($db, \"RECEPTION_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_GETS_ALL_ORDER_PRODUCTS', 'string', NULL, 'reception', 'When set, a reception line with quantity 0 entered is still processed/accepted (treated as if all remaining ordered quantity should be received), instead of being skipped.', 'In reception/card.php:488, the line-processing condition is GETPOSTFLOAT($qty) > 0 || (GETPOSTFLOAT($qty) == 0 && getDolGlobalString(''RECEPTION_GETS_ALL_ORDER_PRODUCTS'')), so a qty of exactly 0 only passes the check when this constant is set.', 'Enabling it changes which reception lines are accepted for processing when the entered quantity field is 0, allowing zero-quantity lines to still be taken into account (paired with a related, separate constant RECEPTION_ALLOW_NEGATIVE_QTY for negative quantities, seen in a commented-out older version of the same line).', 'Boolean-like truthy check via getDolGlobalString().', 1, 0, NULL, 1, '64146e7388b0e78d774887f7fd1218c6db9c5d3a6161ee35e9975c92d8ec4de0', 'v2', '2026-07-24T07:05:23+00:00', '["reception/card.php:488: if (GETPOSTFLOAT($qty) > 0 || (GETPOSTFLOAT($qty) == 0 && getDolGlobalString(''RECEPTION_GETS_ALL_ORDER_PRODUCTS''))) {", "reception/card.php:487: //if (GETPOST($qty, ''int'') > 0 || (GETPOST($qty, ''int'') == 0 && getDolGlobalString(''RECEPTION_GETS_ALL_ORDER_PRODUCTS'')) || (GETPOST($qty, ''int'') < 0 && getDolGlobalString(''RECEPTION_ALLOW_NEGATIVE_QTY''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_MOONSTONE_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the Moonstone reception numbering module.', 'Read in core/modules/reception/mod_reception_moonstone.php:75 to populate the mask input field in the module configuration form, and at line 120 to apply the mask when generating reception reference numbers.', 'Changing the mask alters the format of auto-generated reception reference numbers for new receptions.', 'String: a numbering mask pattern, e.g. ''{YYYY}{MM}{DD}-{####}''.', 1, 0, NULL, 1, '132d40a4cde16b58c4e79ccc4c00ccb85280e245266b2aff2df89cc3f1e4a56a', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/reception/mod_reception_moonstone.php:75|read|... value=\"''.getDolGlobalString(\"RECEPTION_MOONSTONE_MASK\").''\"...", "core/modules/reception/mod_reception_moonstone.php:120|read|$mask = getDolGlobalString(\"RECEPTION_MOONSTONE_MASK\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_PDF_HIDE_ORDERED', 'bool', NULL, 'core', 'Hides the ordered quantity column in reception PDF documents when enabled.', 'Displayed as a select in admin/pdf_other.php at line 767. Checked (negated) in pdf_squille.modules.php at lines 565, 720, 776, and 856; checked positively at line 116 to conditionally hide the ordered column header.', 'Enabling this constant removes the ordered quantity column from reception PDFs. Disabling it (or leaving unset) shows the ordered quantity column.', 'Truthy string to hide ordered column; empty/unset to show ordered column.', 0, 0, 'admin/pdf_other.php', 1, 'b5099366cfedc201f3078d2fb6b26790f0ba5012a13c5ec545f1cd0cbdb2572f', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:767|read|print $form->selectarray(\"RECEPTION_PDF_HIDE_ORDERED\", $arrval, getDolGlobalString(''RECEPTION_PDF_HIDE_ORDERED''));", "core/modules/reception/doc/pdf_squille.modules.php:116|check|if (getDolGlobalString(''RECEPTION_PDF_HIDE_ORDERED'')) {", "core/modules/reception/doc/pdf_squille.modules.php:565|check|if (!getDolGlobalString(''RECEPTION_PDF_HIDE_ORDERED'')) {", "core/modules/reception/doc/pdf_squille.modules.php:776|check|if (!getDolGlobalString(''RECEPTION_PDF_HIDE_ORDERED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_PDF_HIDE_WEIGHT_AND_VOLUME', 'bool', NULL, 'core', 'Hides the weight/volume column content on the reception (Squille) PDF template.', 'Read in core/modules/reception/doc/pdf_squille.modules.php:559 during line rendering; when set, the code skips writing the weighttxt/voltxt cell that would otherwise show computed weight and volume per line.', 'Enabling it removes the weight and volume text from the printed reception PDF lines produced by the ''squille'' model; only affects this specific PDF template.', 'Boolean-like: truthy hides the weight/volume cell content in the PDF.', 1, 0, NULL, 1, '9685a5c7616a17c9d67899c9f27f2617d9cc964b0578f7541d2c46dec084fde9', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/reception/doc/pdf_squille.modules.php:559|check|if (!getDolGlobalString(''RECEPTION_PDF_HIDE_WEIGHT_AND_VOLUME'')) {", "$weighttxt = round($object->lines[$i]->product->weight * $object->lines[$i]->qty, 5).'' ''.measuringUnitString(...)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECEPTION_STANDALONE', 'string', NULL, 'reception', 'Allows creating standalone receptions that are not linked to (originated from) a supplier order.', 'Checked with getDolGlobalString across reception/card.php (multiple lines: 340, 784, 1163, 1177, 2409, 2960, 2120) and ai/tools/crud_objects.class.php:667, gating behavior when $origin is empty.', 'When enabled, reception creation/behavior in reception/card.php no longer requires an $origin (e.g. a supplier order); without it, reception creation is otherwise tied to an origin document.', NULL, 0, 0, NULL, 1, '77e5ecc102b4c71b80e7b1527367ec43355f942c01ac2825c19828bd8fd2a83e', 'v2', '2026-07-24T06:41:12+00:00', '["if (!$error && !$origin && getDolGlobalString(''RECEPTION_STANDALONE'')) {", "if ($action == ''create'' && $origin != ''supplierorder'' && !getDolGlobalString(''RECEPTION_STANDALONE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENTCANDIDATURE_ADDON_PDF', 'string', NULL, 'recruitment', 'Selects the default PDF document model (template) used to generate PDFs for job candidature (candidate application) records.', 'In recruitment/class/recruitmentcandidature.class.php:1091-1092, generateDocument() uses this constant as the default $modele name when no model is explicitly passed; if unset, no default model is used and PDF generation for candidatures is effectively disabled (''No default value... we allow to disable all PDF generation'').', 'Setting it selects which PDF template (matching a core/modules/recruitment/doc/ model) is used to generate candidature documents; leaving it unset disables PDF generation for this object type.', 'String: name of a recruitment candidature PDF doc model; empty/unset means PDF generation is disabled for candidatures.', 1, 0, NULL, 1, 'a18bea0a8ba49f0e786d83987f4fa93041e028307876d5a91083492c1cbd49c9', 'v2', '2026-07-24T07:05:23+00:00', '["recruitment/class/recruitmentcandidature.class.php:1091|check|if (getDolGlobalString(''RECRUITMENTCANDIDATURE_ADDON_PDF'')) {", "recruitment/class/recruitmentcandidature.class.php: } else { $modele = ''''; // No default value. For job application, we allow to disable all PDF generation"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENTJOBPOSITION_ADDON_PDF', 'string', NULL, 'recruitment', 'Selects the default PDF document model (template) used to generate PDFs for recruitment job position records.', 'In recruitment/class/recruitmentjobposition.class.php:1137-1138, generateDocument() uses this constant as the default $modele name when no model is passed; if unset, no default model is used (''No default value... we allow to disable all PDF generation'').', 'Setting it selects which PDF template (matching a core/modules/recruitment/doc/ model) is used to generate job position documents; leaving it unset disables PDF generation for this object type.', 'String: name of a recruitment job position PDF doc model; empty/unset means PDF generation is disabled for job positions.', 1, 0, NULL, 1, '284db01ee0ce671fd20b49d7b0931307db86b1f1c40823ad4b774840676a3c51', 'v2', '2026-07-24T07:05:23+00:00', '["recruitment/class/recruitmentjobposition.class.php:1137|check|if (getDolGlobalString(''RECRUITMENTJOBPOSITION_ADDON_PDF'')) {", "recruitment/class/recruitmentjobposition.class.php: } else { $modele = ''''; // No default value. For job position, we allow to disable all PDF generation"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_EMAIL_SENDER', 'string', NULL, 'core', 'Sets the ''From'' email address used when pre-filling the send-by-email form for recruitment candidatures, falling back to the recruiter''s own email.', 'Used in core/tpl/card_presend.tpl.php:217, unconditionally for $object->element === ''recruitmentcandidature'': $formmail->frommail = getDolGlobalString(''RECRUITMENT_EMAIL_SENDER'', $recruitermail or '''').', 'Setting it overrides the sender email for recruitment candidature emails; if left unset, the recruiter''s own email ($recruitermail) is used instead.', 'Free-text email address string; default fallback is $recruitermail if set, else empty string.', 0, 0, NULL, 1, '97aef31715aa9e68781da52c18551d3b9d984b214adf137e55effe60992d1beb', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:216|if ($object->element === ''recruitmentcandidature'') {", "core/tpl/card_presend.tpl.php:217|read|$formmail->frommail = getDolGlobalString(''RECRUITMENT_EMAIL_SENDER'', (!empty($recruitermail) ? $recruitermail : ''''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_EMAIL_SENDER_NAME', 'string', NULL, 'core', 'Sets the ''From'' display name used when pre-filling the send-by-email form for recruitment candidatures, falling back to the recruiter''s own name.', 'Used in core/tpl/card_presend.tpl.php:218: $formmail->fromname = getDolGlobalString(''RECRUITMENT_EMAIL_SENDER_NAME'', $recruitername or ''''), for element ''recruitmentcandidature''.', 'Setting it overrides the sender display name for recruitment candidature emails; if left unset, the recruiter''s own name ($recruitername) is used instead.', 'Free-text sender display name string; default fallback is $recruitername if set, else empty string.', 0, 0, NULL, 1, 'fcc9515c6fa2c34356bac32bd5e51fcdbc4e8afa83991694c0858183678eb5f6', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:218|read|$formmail->fromname = getDolGlobalString(''RECRUITMENT_EMAIL_SENDER_NAME'', (!empty($recruitername) ? $recruitername : ''''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_ENABLE_PUBLIC_INTERFACE', 'bool', NULL, 'recruitment', 'Enables the public-facing recruitment interface that allows external candidates to view and apply for job positions.', 'Written in recruitment/admin/public_interface.php at lines 60, 62, and 69. Checked at lines 113, 131, and 154 of the same file and in public/recruitment/view.php at line 299, which blocks access when the flag is not set.', 'Disabling this constant blocks all access to the public recruitment pages. Enabling it allows anonymous users to browse open positions and submit applications.', '0 = public interface disabled; 1 = public interface enabled', 0, 0, 'recruitment/admin/public_interface.php|recruitment/admin/public_interface.php|recruitment/admin/public_interface.php|recruitment/admin/public_interface.php|recruitment/admin/public_interface.php|recruitment/admin/public_interface.php|recruitment/admin/public_interface.php', 1, '0e662bf4b4eccfecfe72f3cb15c9b9504ccce17bb11c437e87572651476c0769', 'v2', '2026-04-21T11:16:15+00:00', '["dolibarr_set_const($db, ''RECRUITMENT_ENABLE_PUBLIC_INTERFACE'', 1, ''chaine'', 0, '''', $conf->entity);", "if (!getDolGlobalString(''RECRUITMENT_ENABLE_PUBLIC_INTERFACE'')) {", "if (!getDolGlobalInt(''RECRUITMENT_ENABLE_PUBLIC_INTERFACE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_IMAGE_PUBLIC_INTERFACE', 'string', NULL, 'public', 'URL or path of a banner image displayed on the public recruitment interface pages.', 'Checked in public/recruitment/view.php:364 and public/recruitment/index.php:178; when set, an `<img>` tag is rendered with this value as its src. No admin UI write path is present.', 'When set, the image is displayed as a banner on both the recruitment index and job-view public pages.', 'URL or file path string pointing to an image', 1, 0, NULL, 1, '9a7c2d677a7d646c57be8309b4ca6825b0bbf6dd309d20003be315c945d7ce60', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalString(''RECRUITMENT_IMAGE_PUBLIC_INTERFACE'')) {", "print ''<img id=\"idRECRUITMENT_IMAGE_PUBLIC_INTERFACE\" src=\"'' . getDolGlobalString(''RECRUITMENT_IMAGE_PUBLIC_INTERFACE'').''\">'';", "print ''<img id=\"idPROJECT_IMAGE_PUBLIC_SUGGEST_BOOTH\" src=\"'' . getDolGlobalString(''RECRUITMENT_IMAGE_PUBLIC_INTERFACE'').''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_NEWFORM_TEXT', 'string', NULL, 'public', 'Custom introductory text shown above the new-application form on public recruitment pages.', 'Checked and read in public/recruitment/view.php and public/recruitment/index.php. When the value matches a regex for a translation key wrapped in parentheses (`/^\((.*)\)$/`), it is treated as a translation key; otherwise the raw string is appended to the page output.', 'Changing this value alters the introductory text displayed to job applicants; wrapping the value in parentheses allows using a Dolibarr language translation key.', 'Plain text string, or a Dolibarr language key wrapped in parentheses e.g. ''(MyTranslationKey)''', 1, 0, NULL, 1, 'a25db54682eae31c617c4eb3b740b4c876aedf7b819bf0c8bf564001497a7370', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalString(''RECRUITMENT_NEWFORM_TEXT'')) {", "if (preg_match(''/^\\((.*)\\)$/'', getDolGlobalString(''RECRUITMENT_NEWFORM_TEXT''), $reg)) {", "$text .= getDolGlobalString(''RECRUITMENT_NEWFORM_TEXT'') . \"<br>\n\";", "if (preg_match(''/^\\((.*)\\)$/'', $conf->global->RECRUITMENT_NEWFORM_TEXT, $reg)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_RECRUITMENTCANDIDATURE_ADDON', 'string', NULL, 'recruitment', 'Specifies the numbering module class name used to generate reference numbers for recruitment candidatures.', 'Read at recruitment/class/recruitmentcandidature.class.php:1031 and 1030 to load the addon class and file. If not set (line 1023–1024), it defaults to ''mod_recruitmentcandidature_standard'' at runtime without persisting to the database.', 'Changing this value to a different addon class name changes the reference numbering scheme applied to new candidature records.', 'A string class name of a numbering module (e.g. ''mod_recruitmentcandidature_standard'' or a custom module name).', 1, 0, NULL, 1, 'ccb70632bbc9ec34cad6b6aa0c8a2adf1962b1d907cefb11e1a8269770cc898e', 'v2', '2026-04-21T11:16:15+00:00', '["if (!getDolGlobalString(''RECRUITMENT_RECRUITMENTCANDIDATURE_ADDON'')) {", "$conf->global->RECRUITMENT_RECRUITMENTCANDIDATURE_ADDON = ''mod_recruitmentcandidature_standard'';", "$classname = getDolGlobalString(''RECRUITMENT_RECRUITMENTCANDIDATURE_ADDON'');", "$file = getDolGlobalString(''RECRUITMENT_RECRUITMENTCANDIDATURE_ADDON'') . \".php\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_RECRUITMENTCANDIDATURE_ADVANCED_MASK', 'string', NULL, 'recruitment', 'Stores the numbering mask (ref pattern) used by the ''advanced'' numbering module for recruitment candidatures.', 'Read/written via the recruitment candidature numbering model (recruitment/core/modules/recruitment/mod_recruitmentcandidature_advanced.php:129) and displayed/edited through recruitment/admin/setup_candidatures.php (action ''updateMask'', field maskconstcand). getNextValue() uses `get_next_value($db, $mask, ''recruitment_recruitmentcandidature'', ''ref'', '''', '''', $date)` to compute the next reference; if empty, numbering fails with error ''NotConfigured''.', 'Changing the mask changes the format of newly generated candidature references; an invalid or empty mask makes getNextValue() return 0/error (''NotConfigured'').', 'A Dolibarr generic numbering mask string (same syntax as other ''Advanced'' ref mask modules, e.g. with {yyyy}{mm}{tttt} placeholders); empty means not configured.', 0, 0, NULL, 1, 'd5545f16503b2e3090ef9175ea49797fc420b7024e8766a31cea365f5b6ffaf6', 'v2', '2026-07-24T07:05:23+00:00', '["recruitment/core/modules/recruitment/mod_recruitmentcandidature_advanced.php:129: $mask = getDolGlobalString(''RECRUITMENT_RECRUITMENTCANDIDATURE_ADVANCED_MASK'');", "recruitment/admin/setup_candidatures.php:81: $maskconst = GETPOST(''maskconstcand'', ''aZ09'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON', 'string', NULL, 'recruitment', 'Specifies the numbering module class name used to generate reference numbers for recruitment job positions.', 'Read at recruitment/class/recruitmentjobposition.class.php:1078 and 1077 to load the addon class and file. If not set (line 1070–1071), it defaults to ''mod_recruitmentjobposition_standard'' at runtime without persisting to the database.', 'Changing this value to a different addon class name changes the reference numbering scheme applied to new job position records.', 'A string class name of a numbering module (e.g. ''mod_recruitmentjobposition_standard'' or a custom module name).', 1, 0, NULL, 1, '99aab9ef6123e08bcc3c8129fbf0d1af9b0e140175c723823e0d7ee5db9005c8', 'v2', '2026-04-21T11:16:15+00:00', '["if (!getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON'')) {", "$conf->global->RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON = ''mod_recruitmentjobposition_standard'';", "$classname = getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON'');", "$file = getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON'') . \".php\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON_PDF_ODT_PATH', 'string', NULL, 'recruitment', 'Specifies one or more directories (comma-separated) where custom ODT templates for recruitment job position documents are stored.', 'Read at recruitment/core/modules/recruitment/doc/doc_generic_recruitmentjobposition_odt.modules.php:139 using explode('','', ...) and checked at line 165; the value is also displayed in the module UI at line 188.', 'Setting this to a valid directory path makes custom ODT templates available for recruitment position document generation.', 'String (comma-separated directory paths); empty = only default template directories are searched.', 1, 0, NULL, 1, 'ebbc6157ae3d238d391ceaf42e2aa152edf502ac2306c020ba39c6cc178ed1b4', 'v2', '2026-04-21T11:16:15+00:00', '["recruitment/core/modules/recruitment/doc/doc_generic_recruitmentjobposition_odt.modules.php:139|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON_PDF_ODT_PATH''))));", "recruitment/core/modules/recruitment/doc/doc_generic_recruitmentjobposition_odt.modules.php:165|check|if (getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON_PDF_ODT_PATH'')) {", "recruitment/core/modules/recruitment/doc/doc_generic_recruitmentjobposition_odt.modules.php:188|read|$texte .= getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_ADDON_PDF_ODT_PATH'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_RECRUITMENTJOBPOSITION_ADVANCED_MASK', 'string', NULL, 'recruitment', 'Stores the numbering mask (ref pattern) used by the ''advanced'' numbering module for recruitment job positions.', 'Read in the job-position numbering model (recruitment/core/modules/recruitment/mod_recruitmentjobposition_advanced.php:129: `$mask = getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_ADVANCED_MASK'');`) and written through recruitment/admin/setup.php (action ''updateMask'', field maskconstjob). getNextValue() calls get_next_value() with this mask to compute the next reference; empty mask makes numbering return 0/''NotConfigured''.', 'Changing the mask changes the format of newly generated job-position references; an invalid or empty mask makes getNextValue() return 0/error (''NotConfigured'').', 'A Dolibarr generic numbering mask string (same syntax as other ''Advanced'' ref mask modules); empty means not configured.', 0, 0, NULL, 1, '2569221d587435a6db30480c00d702d472d47f45daf3bed5ac484bf6650dff74', 'v2', '2026-07-24T07:05:23+00:00', '["recruitment/core/modules/recruitment/mod_recruitmentjobposition_advanced.php:129: $mask = getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_ADVANCED_MASK'');", "recruitment/admin/setup.php:85: $maskconst = GETPOST(''maskconstjob'', ''alpha'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_RECRUITMENTJOBPOSITION_DRAFT_WATERMARK', 'string', NULL, 'recruitment', 'Text used as a watermark printed on draft job-position PDF documents.', 'Used in recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:741-742: `if ($object->status == STATUS_DRAFT && getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_DRAFT_WATERMARK'')) { pdf_watermark($pdf, ..., getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_DRAFT_WATERMARK'')); }`.', 'When set to a non-empty string, that text is stamped as a watermark on job-position PDFs while the job position is still in draft status; unset/empty means no watermark is printed.', 'Any free-text string used as watermark text (e.g. "DRAFT"); empty/unset disables the watermark.', 1, 0, NULL, 1, '8cd1c52924e700336ec4c03cd3efb4d826a93e2b3dd57de1007914bb0079ce68', 'v2', '2026-07-24T07:05:23+00:00', '["recruitment/core/modules/recruitment/doc/pdf_standard_recruitmentjobposition.modules.php:741: if ($object->status == $object::STATUS_DRAFT && getDolGlobalString(''RECRUITMENT_RECRUITMENTJOBPOSITION_DRAFT_WATERMARK'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RECRUITMENT_SECURITY_TOKEN', 'string', NULL, 'recruitment', 'Was intended to append a hashed ''securekey'' parameter to public job-position URLs, but that code is entirely commented out (dead/disabled feature).', 'Found only inside a commented-out block in recruitment/lib/recruitment_recruitmentjobposition.lib.php:141-144 (`/*if (getDolGlobalString(''RECRUITMENT_SECURITY_TOKEN'')) { ... $out .= ''&securekey=''.urlencode(dol_hash(getDolGlobalString(''RECRUITMENT_SECURITY_TOKEN''), ''2'')); ... }*/`) inside getPublicJobPositionUrl(); the active code path does not read this constant at all.', 'Setting this constant currently has no effect, since the only code referencing it is commented out in the develop source tree.', 'N/A — the referencing code is commented out and never executes.', 1, 0, NULL, 1, '94c5c46682791ee61f014bdda5528a2b52b4a2605b49293b590f2851ca1a62b4', 'v2', '2026-07-24T07:05:23+00:00', '["recruitment/lib/recruitment_recruitmentjobposition.lib.php:141: /*if (getDolGlobalString(''RECRUITMENT_SECURITY_TOKEN'')) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RELOAD_PAGE_ON_CUSTOMER_CHANGE_DISABLED', 'bool', NULL, 'reception', 'Disables the automatic page reload triggered when the customer/third-party is changed on document forms.', 'Checked in reception/card.php:1183, compta/facture/card.php:3955, comm/propal/card.php:2410, expedition/card.php:1500, and commande/card.php:2342 — when unset, the page reloads on customer change. Also checked positively in don/card.php:440. No admin UI write path exists.', 'Setting this constant prevents the page from reloading when the customer field changes on invoices, orders, proposals, shipments, and receptions; the customer-context update then relies on other mechanisms.', 'Truthy string/bool=reload disabled, empty/0=reload enabled', 1, 0, NULL, 1, 'c0729ecc5bbea8b880fd63e19a4f4732032e418aa49389d6ff91fc972048a61c', 'v2', '2026-04-21T11:16:15+00:00', '["reception/card.php:1183|check|if (!getDolGlobalString(''RELOAD_PAGE_ON_CUSTOMER_CHANGE_DISABLED'')) {", "compta/facture/card.php:3955|check|if (!getDolGlobalString(''RELOAD_PAGE_ON_CUSTOMER_CHANGE_DISABLED'')) {", "don/card.php:440|check|if (getDolGlobalString(''RELOAD_PAGE_ON_CUSTOMER_CHANGE_DISABLED'')) {", "commande/card.php:2342|check|if (!getDolGlobalString(''RELOAD_PAGE_ON_CUSTOMER_CHANGE_DISABLED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RELOAD_PAGE_ON_SUPPLIER_CHANGE_DISABLED', 'bool', NULL, 'fourn', 'Disables automatic page reload when the supplier is changed on purchase documents.', 'Checked in 3 files: supplier_proposal/card.php:1571, fourn/commande/card.php:2006, and fourn/facture/card.php:2403, always as `if (!getDolGlobalString(''RELOAD_PAGE_ON_SUPPLIER_CHANGE_DISABLED''))`.', 'Setting this value suppresses the automatic page reload triggered by a supplier change, keeping the current page state intact.', 'Truthy string (non-empty) = page reload on supplier change is disabled; empty/not set = page reloads on supplier change.', 1, 0, NULL, 1, '52b66b75e71f70c72384dacfc019c40375b4f19312a8f278534a326d03b8f16c', 'v2', '2026-04-21T11:16:15+00:00', '["supplier_proposal/card.php:1571|check|if (!getDolGlobalString(''RELOAD_PAGE_ON_SUPPLIER_CHANGE_DISABLED'')) {", "fourn/commande/card.php:2006|check|if (!getDolGlobalString(''RELOAD_PAGE_ON_SUPPLIER_CHANGE_DISABLED'')) {", "fourn/facture/card.php:2403|check|if (!getDolGlobalString(''RELOAD_PAGE_ON_SUPPLIER_CHANGE_DISABLED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RELOAD_PAGE_ON_TEMPLATE_CHANGE_DISABLED', 'bool', NULL, 'fourn', 'Disables the automatic page reload (via JS) that normally occurs when the user changes the selected recurring-invoice template on an invoice creation form.', 'Checked in fourn/facture/card.php:2487 and compta/facture/card.php:4117; when not set, JS is emitted to submit/reload the form when the ''#fac_rec'' select changes, to refresh customer info.', 'When set, changing the template invoice (''fac_rec'') dropdown will no longer auto-reload the page to retrieve customer information; the comment notes reloading ''clear[s] other input''.', 'Bool: truthy disables the auto-reload-on-template-change JS behavior.', 1, 0, NULL, 1, 'f064ccd04ca2807022c1d6c1ae0ef15f3e593b35c7f49ef4f16928874428f339', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:2486|read|// Option to reload page to retrieve customer information. Note, this clear other input", "fourn/facture/card.php:2487|check|if (!getDolGlobalString(''RELOAD_PAGE_ON_TEMPLATE_CHANGE_DISABLED'')) {", "compta/facture/card.php:4117|check|if (!getDolGlobalString(''RELOAD_PAGE_ON_TEMPLATE_CHANGE_DISABLED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('REPLENISH_ALLOW_VARIABLESIZELIST', 'bool', NULL, 'product', 'Switches the replenishment list''s pagination bar (print_barre_liste) to a variant that accepts a variable page-size limit parameter.', 'In product/stock/replenish.php:765, if this constant is truthy, print_barre_liste is called with an extra $limit argument (variable-size list bar); otherwise the simpler fixed call (without $limit) is used.', 'Enabling it changes the replenishment list''s list-size/pagination bar to support a configurable/variable page size instead of the default fixed pagination.', 'Boolean-like flag (truthy enables the variable-size list bar variant).', 1, 0, NULL, 1, 'ece277534c180c3fd160d49a10e2630c8e010ca77912dcfd96023f5ccc87a179', 'v2', '2026-07-24T07:05:23+00:00', '["product/stock/replenish.php:765: if (getDolGlobalString(''REPLENISH_ALLOW_VARIABLESIZELIST'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RESOURCE_HIDE_ADD_CONTACT_THIPARTY', 'bool', NULL, 'resource', 'Hides the ''add third-party contact'' action on the resource contact page when set.', 'Checked in resource/contact.php:167 to suppress the add-thirdparty-contact UI, and in core/lib/resource.lib.php:45 to conditionally show the contacts tab. The comment in admin/resource.php:154 references this constant by name.', 'Setting this hides the ability to link third-party contacts to a resource, which may also affect whether the contacts tab is visible depending on RESOURCE_HIDE_ADD_CONTACT_USER.', 'Empty/unset = show; any non-empty string = hide.', 1, 0, NULL, 1, '92b2528eb685708f8a1f6f3e5d108930ac6ba1697e789b75ba04e1f6928c49b1', 'v2', '2026-04-21T13:29:58+00:00', '["resource/contact.php:167|check|if (getDolGlobalString(''RESOURCE_HIDE_ADD_CONTACT_THIPARTY'')) {", "core/lib/resource.lib.php:45|check|if (!getDolGlobalString(''MAIN_DISABLE_CONTACTS_TAB'') && (!getDolGlobalString(''RESOURCE_HIDE_ADD_CONTACT_USER'') || !getDolGlobalString(''RESOURCE_HIDE_ADD_CONTACT_THIPARTY''))) {", "admin/resource.php:154  //RESOURCE_HIDE_ADD_CONTACT_THIPARTY"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RESOURCE_HIDE_ADD_CONTACT_USER', 'bool', NULL, 'resource', 'Hides the ''add user contact'' action on the resource contact page when set.', 'Checked in resource/contact.php:164 to suppress the add-user-contact UI, and in core/lib/resource.lib.php:45 to conditionally show the contacts tab. The comment in admin/resource.php:153 references this constant by name.', 'Setting this hides the ability to link user contacts to a resource, which may also affect whether the contacts tab is visible depending on RESOURCE_HIDE_ADD_CONTACT_THIPARTY.', 'Empty/unset = show; any non-empty string = hide.', 1, 0, NULL, 1, '1b415c9ce33b5cdee6a63446726a98e1ef9ec3d77f9cff713249a150c3bf543d', 'v2', '2026-04-21T13:29:58+00:00', '["resource/contact.php:164|check|if (getDolGlobalString(''RESOURCE_HIDE_ADD_CONTACT_USER'')) {", "core/lib/resource.lib.php:45|check|if (!getDolGlobalString(''MAIN_DISABLE_CONTACTS_TAB'') && (!getDolGlobalString(''RESOURCE_HIDE_ADD_CONTACT_USER'') || !getDolGlobalString(''RESOURCE_HIDE_ADD_CONTACT_THIPARTY''))) {", "admin/resource.php:153  //RESOURCE_HIDE_ADD_CONTACT_USER"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RESOURCE_ON_PRODUCTS', 'string', NULL, 'core', 'Enables display of the ''Resources'' tab on product cards, letting resources be linked to products.', 'In core/lib/product.lib.php:162, when the resource module is enabled and the current object is a product ($object->isProduct()), this bool gates whether the Resources tab (linking to resource/element_resource.php with element=''product'') is added to the product''s tab list.', 'Enabling it (with the resource module active) adds a Resources tab to product cards allowing resource-to-product links; disabled/unset hides that tab for products.', 'true/1 = show Resources tab on products; false/unset (default) = tab hidden.', 1, 0, NULL, 1, 'cc93cd3cb0e51b7ebe97b8f57c1118a3006f6cfd623c5bab34bcbd0e314d00e4', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/product.lib.php:161: if (isModEnabled(''resource'')) {", "core/lib/product.lib.php:162|check|if ($object->isProduct() && getDolGlobalString(''RESOURCE_ON_PRODUCTS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RESOURCE_ON_SERVICES', 'string', NULL, 'core', 'Enables display of the ''Resources'' tab on service cards, letting resources be linked to services.', 'In core/lib/product.lib.php:168, when the resource module is enabled and the current object is a service ($object->isService()), this bool gates whether the Resources tab (linking to resource/element_resource.php with element=''service'') is added to the service''s tab list.', 'Enabling it (with the resource module active) adds a Resources tab to service cards allowing resource-to-service links; disabled/unset hides that tab for services.', 'true/1 = show Resources tab on services; false/unset (default) = tab hidden.', 1, 0, NULL, 1, '11f0270cf92dd7f31f6fc657b65015d8e9624b5a7b7e331bd500e424524f07eb', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/product.lib.php:161: if (isModEnabled(''resource'')) {", "core/lib/product.lib.php:168|check|if ($object->isService() && getDolGlobalString(''RESOURCE_ON_SERVICES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RESOURCE_ON_THIRDPARTIES', 'string', NULL, 'core', 'Enables display of a ''Resources'' tab on thirdparty (company) cards when the Resource module is active.', 'In core/lib/company.lib.php:198-203, the thirdparty tab list adds a ''Resources'' tab (linking to resource/element_resource.php) only if isModEnabled(''resource'') is true AND getDolGlobalString(''RESOURCE_ON_THIRDPARTIES'') is set.', 'Enabling it, together with the Resource module, exposes a resources tab on every thirdparty record; without it the tab does not appear even if the Resource module is active.', 'Boolean-like: set/non-empty shows the Resources tab on thirdparties; unset (default) hides it.', 1, 0, NULL, 1, '7f7cde07df85f178d8cf71fd6644ea2384e7f07274709086daa17af43769ac3c', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/company.lib.php:199: if (isModEnabled(''resource'') && getDolGlobalString(''RESOURCE_ON_THIRDPARTIES'')) {", "core/lib/company.lib.php:200: $head[$h][1] = $langs->trans(\"Resources\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RESOURCE_USED_IN_EVENT_CHECK', 'string', NULL, 'comm', 'Enables availability checking of resources linked to agenda events to prevent double-booking of busy resources.', 'Checked in resource/element_resource.php:144 and comm/action/card.php:607,1076,1264. When set, the code verifies that a dolresource assigned to an action (event) is not already marked busy before allowing the assignment.', 'Enabling this constant adds a busy-resource guard on event creation and update; disabling it removes that check, allowing resources to be assigned to overlapping events without warning.', 'Any non-empty string = enable resource-in-event busy check; empty/unset = no check', 1, 0, NULL, 1, '2cf586fdd082b98b427468ef898969c0d7f61ba2dc5741e791df701369eccc9d', 'v2', '2026-04-21T13:29:58+00:00', '["if (getDolGlobalString(''RESOURCE_USED_IN_EVENT_CHECK'') && $objstat->element == ''action'' && $resource_type == ''dolresource'' && intval($busy) == 1) {", "if (getDolGlobalString(''RESOURCE_USED_IN_EVENT_CHECK'')) {", "if (getDolGlobalString(''RESOURCE_USED_IN_EVENT_CHECK'') && $object->element == ''action'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('RESOURCE_USE_SEARCH_TO_SELECT', 'bool', NULL, 'resource', 'Enables Ajax autocomplete search instead of a static combo box for resource selection.', 'Configured via admin/resource.php:60 (written with dolibarr_set_const) and rendered as a select at line 111. Checked in resource/class/html.formresource.class.php:152 to activate ajax_combobox, and used at line 154 to pass the threshold value to the Ajax call. A commented line at 153 shows the intended minLength usage.', 'When enabled, resource selection fields use an Ajax-powered search box. When disabled or unset, a static dropdown is used.', 'Numeric string used as the minimum character threshold for Ajax search; truthy enables search-to-select. Empty/unset uses static combo box.', 0, 0, 'admin/resource.php|admin/resource.php', 1, '74fae3ea6e0250945d3a5a878e202f71ad25947eb8f05be8bbd87309c1ca278e', 'v2', '2026-04-21T13:29:58+00:00', '["admin/resource.php:60|write|if (dolibarr_set_const($db, \"RESOURCE_USE_SEARCH_TO_SELECT\", GETPOST(''activate_RESOURCE_USE_SEARCH_TO_SELECT''), ''chaine'', 0, '''', $conf->entity)) {", "resource/class/html.formresource.class.php:152|check|if (!empty($conf->use_javascript_ajax) && getDolGlobalString(''RESOURCE_USE_SEARCH_TO_SELECT'') && !$forcecombo) {", "resource/class/html.formresource.class.php:154|read|$out .= ajax_combobox($htmlname, $event, $conf->global->RESOURCE_USE_SEARCH_TO_SELECT);", "resource/class/html.formresource.class.php:153  //$minLength = (is_numeric($conf->global->RESOURCE_USE_SEARCH_TO_SELECT)?$conf->global->RESOURCE_USE_SEARCH_TO_SELECT:2);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SALARIES_ACCOUNTING_ACCOUNT_PAYMENT', 'string', NULL, 'accountancy', 'Stores the general ledger account number used for salary payment entries in accounting journals.', 'Read in accountancy/journal/variousjournal.php (lines 195, 211, 215, 216), accountancy/journal/bankjournal.php:271 and :726, and accountancy/journal/treasuryjournal.php:574 (12+ occurrences). Checked against '''' and ''-1''; ''NotDefined'' is used as a fallback reserved word. No admin UI write found; HIDDEN_GUESS is 1.', 'If not set or set to ''-1'', salary payment entries cannot be posted in the various journal and bank journal, blocking payroll accounting.', 'String: general ledger account number; '''' or ''-1'' = not configured (treated as setup error)', 1, 0, NULL, 1, '03c02571c08c904addd6b0a8deacc99085a4ddcebece647925e9e1a395038b1f', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/journal/bankjournal.php:271|read|$account_employee = getDolGlobalString(''SALARIES_ACCOUNTING_ACCOUNT_PAYMENT'', ''NotDefined''); // NotDefined is a reserved word", "accountancy/journal/variousjournal.php:215|read|$some_mandatory_steps_of_setup_were_not_done = !getDolGlobalString(''SALARIES_ACCOUNTING_ACCOUNT_PAYMENT'') || getDolGlobalString(''SALARIES_ACCOUNTING_ACCOUNT_PAYMENT'') == ''-1'';", "accountancy/journal/variousjournal.php:195|read||| !getDolGlobalString(''SALARIES_ACCOUNTING_ACCOUNT_PAYMENT'') || getDolGlobalString(''SALARIES_ACCOUNTING_ACCOUNT_PAYMENT'') == ''-1''", "accountancy/journal/bankjournal.php:726|read|$accountingaccountpayment->fetch(0, getDolGlobalString(''SALARIES_ACCOUNTING_ACCOUNT_PAYMENT''), true);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SALARY_MANAGEMENT_PER_WEEK', 'string', NULL, 'salaries', 'Adds weekly quick-navigation buttons (previous/current week) next to the monthly ones on the salary clone date-picker.', 'Checked in salaries/card.php:804 inside the clone-confirmation form JS, adding ''start_prev_week''/''start_curr_week'' buttons alongside the always-present month buttons.', 'When set, users seee extra ''PreviousWeekShort''/''CurrentWeekShort'' quick-date buttons on the salary clone dialog in addition to the month buttons.', 'Bool: truthy adds week-based quick-date buttons to the salary clone date fields.', 1, 0, NULL, 1, 'b7b709541f053ec1b4403aa5a81e33c757740146cc87d78cc7b0917461b62880', 'v2', '2026-07-24T07:05:23+00:00', '["salaries/card.php:804|check|if (getDolGlobalString(''SALARY_MANAGEMENT_PER_WEEK'')) {", "salaries/card.php:805-807|read|.add(''<button id=\"start_prev_week\" ...>PreviousWeekShort</button>'').add(''<button id=\"start_curr_week\" ...>CurrentWeekShort</button>'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SALES_ORDER_SHOW_SHIPPING_ADDRESS', 'bool', NULL, 'admin', 'When set, includes the shipping address section in generated sales order PDF documents.', 'Managed via the admin UI at admin/pdf_other.php (written by dolibarr_set_const with delete fallback, displayed as a select array). Checked in pdf_einstein.modules.php and pdf_eratosthene.modules.php before rendering the shipping address block.', 'Enabling this adds the shipping address to sales order PDFs. Disabling (or leaving unset) omits the shipping address from those documents.', '0 or empty = no shipping address on order PDF; non-zero = shipping address shown.', 0, 0, 'admin/pdf_other.php|admin/pdf_other.php|admin/pdf_other.php', 1, '5c77de31114bac743599bfa3f43dc3ef9cfc8942d2e52fadb72ee76e26f1bd47', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:102|dolibarr_set_const($db, \"SALES_ORDER_SHOW_SHIPPING_ADDRESS\", GETPOSTINT(\"SALES_ORDER_SHOW_SHIPPING_ADDRESS\"), ''chaine'', 0, '''', $conf->entity);", "admin/pdf_other.php:392|print $form->selectarray(\"SALES_ORDER_SHOW_SHIPPING_ADDRESS\", $arrval, getDolGlobalString(''SALES_ORDER_SHOW_SHIPPING_ADDRESS''));", "pdf_einstein.modules.php:1610|if (getDolGlobalInt(''SALES_ORDER_SHOW_SHIPPING_ADDRESS'')) {", "pdf_eratosthene.modules.php:1867|if (getDolGlobalInt(''SALES_ORDER_SHOW_SHIPPING_ADDRESS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SALE_ORDER_SUGGEST_DOWN_PAYMENT_INVOICE_CREATION', 'string', NULL, 'commande', 'Enables an optional suggestion to create a down-payment invoice automatically during sales order validation.', 'Checked in commande/card.php:2714 with getDolGlobalInt(...); the surrounding comment states this is a hidden option not enabled by default, since such workflow should normally be handled by the workflow module/trigger.', 'When enabled, validating an order with a deposit_percent from payment terms triggers automatic down-payment invoice creation logic; the code comments warn this can conflict with other setups and may break invoicing-from-proposal workflows.', 'Boolean/int: 1 enables the suggestion; not documented as user-configurable via UI (comment: ''This is a hidden option'').', 1, 0, NULL, 1, '0b343a6e73d1cd6f14ced6c51a8df5749d9eee467611bf0f3ce5078ce47dbaae', 'v2', '2026-07-24T07:05:23+00:00', '["commande/card.php:2714: if (getDolGlobalInt(''SALE_ORDER_SUGGEST_DOWN_PAYMENT_INVOICE_CREATION'')) {", "commande/card.php: // This is a hidden option: Suggestion to create invoice during order validation is not enabled by default.", "commande/card.php: // Such choice should be managed by the workflow module and trigger. This option generates conflicts with some setup."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCHFORM_POSITION_CONTACT', 'string', NULL, 'core', 'Sets the sort position of the ''search into contacts'' entry in the global quick-search box.', 'In core/ajax/selectsearchbox.php:93, the value (default 25) is used as the ''position'' key for the searchintocontact array entry in the quick-search dropdown, part of the same SEARCHFORM_POSITION_* family.', 'Changing the value re-orders where the contacts search shortcut appears relative to other quick-search entries; default is 25.', 'int: sort position of the entry; default 25 if unset.', 1, 0, NULL, 1, '2433b7d60db485217d21c8175aba3c5a64a7f24a75a469cd0d732d265df89ba2', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:93: $arrayresult[''searchintocontact''] = array(''position'' => getDolGlobalInt(''SEARCHFORM_POSITION_CONTACT'', 25), ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCHFORM_POSITION_INVOICE', 'string', NULL, 'core', 'Sets the numeric sort position of the customer invoice entry in the global search form dropdown.', 'Read in core/ajax/selectsearchbox.php:124 to set the ''position'' key for the ''searchintoinvoice'' result array, defaulting to 90 when not set.', 'Changing the value alters the display order of the invoice search option relative to other entities in the search box.', 'Integer position value; default 90.', 1, 0, NULL, 1, '2d30c4f7d79cb16640f6aa32aead6bdde13e44c75da2c0cc05b440097ef6c95e', 'v2', '2026-04-21T13:29:58+00:00', '["core/ajax/selectsearchbox.php:124|read|$arrayresult[''searchintoinvoice''] = array(''position'' => getDolGlobalInt(''SEARCHFORM_POSITION_INVOICE'', 90), ''img'' => ''object_bill''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCHFORM_POSITION_INVOICEREC', 'string', NULL, 'core', 'Sets the numeric sort position of the recurring customer invoice entry in the global search form dropdown.', 'Read in core/ajax/selectsearchbox.php:127 to set the ''position'' key for the ''searchintoinvoicerec'' result array, defaulting to 95 when not set.', 'Changing the value alters the display order of the recurring invoice search option relative to other entities.', 'Integer position value; default 95.', 1, 0, NULL, 1, '5829c49ec56e15f1df9ae6830eb56d16a562f8b82154e9d2019b22352d723781', 'v2', '2026-04-21T13:29:58+00:00', '["core/ajax/selectsearchbox.php:127|read|$arrayresult[''searchintoinvoicerec''] = array(''position'' => getDolGlobalInt(''SEARCHFORM_POSITION_INVOICEREC'', 95), ''img'' => ''object_bill''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCHFORM_POSITION_MEMBER', 'string', NULL, 'core', 'Sets the sort position of the ''search into members'' entry in the global quick-search box.', 'In core/ajax/selectsearchbox.php:85, the value (default 10) is used as the ''position'' key for the searchintomember array entry, which orders entries in the quick-search dropdown alongside siblings like SEARCHFORM_POSITION_PROSPCUST (20), SEARCHFORM_POSITION_CONTACT (25), etc.', 'Changing the value re-orders where the members search shortcut appears relative to other entries (thirdparty, contact, product...) in the quick-search dropdown; default is 10 (near the top).', 'int: sort position of the entry; default 10 if unset.', 1, 0, NULL, 1, '4f183fdc22861af57fcd8eafe7fc715ee3298c9b439836bd692c697bc31268b9', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:85: $arrayresult[''searchintomember''] = array(''position'' => getDolGlobalInt(''SEARCHFORM_POSITION_MEMBER'', 10), ..."]', 'high', NULL);
