INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCHFORM_POSITION_ORDER', 'string', NULL, 'core', 'Sets the display order (sort weight) of the "Search into customer orders" entry in the top quick-search dropdown.', 'Read in core/ajax/selectsearchbox.php:118 via getDolGlobalInt(''SEARCHFORM_POSITION_ORDER'', 70) to set the ''position'' key of the searchintoorder entry; default is 70 when unset.', 'Changing the value only reorders where the entry appears among other quick-search entries; it does not enable or disable it.', 'Integer sort position; default 70 if not set.', 1, 0, NULL, 1, '9788ab8db38b297259608a0c817ebd8168068469443d027dfed4c7d25847e0fe', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:118|read|$arrayresult[''searchintoorder''] = array(''position'' => getDolGlobalInt(''SEARCHFORM_POSITION_ORDER'', 70), ''img'' => ''object_order'', ''label'' => $langs->trans(\"SearchIntoCustomerOrders\""]', 'medium', NULL);
