INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCHFORM_POSITION_SHIPMENT', 'string', NULL, 'core', 'Sets the numeric sort position of the shipment entry in the global search form dropdown.', 'Read in core/ajax/selectsearchbox.php:121 to set the ''position'' key for the ''searchintoshipment'' result array, defaulting to 80 when not set.', 'Changing the value alters the display order of the shipment search option relative to other entities in the search box.', 'Integer position value; default 80.', 1, 0, NULL, 1, '17f98e47a5727b0bb69895f43a6a1e28e9f9f9eb4e23faa933655beab254792a', 'v2', '2026-04-21T13:29:58+00:00', '["core/ajax/selectsearchbox.php:121|read|$arrayresult[''searchintoshipment''] = array(''position'' => getDolGlobalInt(''SEARCHFORM_POSITION_SHIPMENT'', 80), ''img'' => ''object_shipment''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCHFORM_POSITION_SUPPLIER_PROPOSAL', 'string', NULL, 'core', 'Sets the numeric sort position of the supplier proposal entry in the global search form dropdown.', 'Read in core/ajax/selectsearchbox.php:131 to set the ''position'' key for the ''searchintosupplierpropal'' result array, defaulting to 100 when not set.', 'Changing the value alters the display order of the supplier proposal search option relative to other entities.', 'Integer position value; default 100.', 1, 0, NULL, 1, '3a27566d59ef72a09ebf299e046e359a2d754ce543680f9617e400e902071a4a', 'v2', '2026-04-21T13:29:58+00:00', '["core/ajax/selectsearchbox.php:131|read|$arrayresult[''searchintosupplierpropal''] = array(''position'' => getDolGlobalInt(''SEARCHFORM_POSITION_SUPPLIER_PROPOSAL'', 100), ''img'' => ''object_supplier_proposal''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCHFORM_POSITION_TASK', 'string', NULL, 'core', 'Sets the display order (sort weight) of the "Search into tasks" entry in the top quick-search dropdown.', 'Read in core/ajax/selectsearchbox.php:111 via getDolGlobalInt(''SEARCHFORM_POSITION_TASK'', 45) to set the ''position'' key of the searchintotasks entry; default is 45 when unset.', 'Changing the value only reorders where the "Search into tasks" choice appears among other quick-search entries; it does not enable or disable the entry.', 'Integer sort position; default 45 if not set.', 1, 0, NULL, 1, '7b3707ab28759944bb243df6772465ab9d2b8cb4ea50789168d58ac08c256906', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/selectsearchbox.php:111|read|$arrayresult[''searchintotasks''] = array(''position'' => getDolGlobalInt(''SEARCHFORM_POSITION_TASK'', 45), ''img'' => ''object_projecttask'', ''label'' => $langs->trans(\"SearchIntoTasks\", $s"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCH_FOR_NEXT_VAL_ON_START_ONLY', 'string', NULL, 'core', 'Controls whether the SQL query for the next sequence value searches with a trailing wildcard (prefix match) or exact match.', 'Used three times in core/lib/functions2.lib.php (lines 1163, 1232, 1295): when set, a ''%'' wildcard is appended to the LIKE pattern, making the search match any record whose key starts with the mask prefix rather than requiring an exact match.', 'Enabling this can cause the sequence engine to consider records from unrelated series when computing the next number, which risks gaps or skips in numbering.', 'Empty/unset = exact LIKE match (no trailing wildcard); any non-empty string = prefix match (trailing ''%'' appended).', 1, 0, NULL, 1, '43498d2de30944425366a25d6caf218154d3d0af02ccd411e0326a4090e5ebb1', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:1163|read|$sql .= \" WHERE \".$db->sanitize($field).\" LIKE ''\".$db->escape($maskLike) . (getDolGlobalString(''SEARCH_FOR_NEXT_VAL_ON_START_ONLY'') ? \"%\" : \"\") . \"''\";", "core/lib/functions2.lib.php:1232|read|$sql .= \" WHERE \".$db->sanitize($field).\" LIKE ''\".$db->escape($maskLike) . (getDolGlobalString(''SEARCH_FOR_NEXT_VAL_ON_START_ONLY'') ? \"%\" : \"\") . \"''\";", "core/lib/functions2.lib.php:1295|read|$maskrefclient_sql .= \" WHERE \".$db->sanitize($field).\" LIKE ''\".$db->escape($maskrefclient_maskLike) . (getDolGlobalString(''SEARCH_FOR_NEXT_VAL_ON_START_ONLY'') ? \"%\" : \"\") . \"''\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEARCH_LIMIT_AJAX', 'string', NULL, 'societe', 'Sets the maximum number of results returned by AJAX autocomplete searches, overriding module-specific limits.', 'Read in societe/ajax/ajaxcompanies.php:142: `$limit = getDolGlobalInt(''SEARCH_LIMIT_AJAX'') ?: 1000; // SEARCH_LIMIT_AJAX is a hidden option that has priority on option THIRDPARTY_LIMIT_SIZE if set.` Also read in core/class/html.form.class.php:3407: `$limit = getDolGlobalInt(''SEARCH_LIMIT_AJAX'') ?: $limit; // SEARCH_LIMIT_AJAX is a hidden option that has priority on visible option PRODUIT_LIMIT_SIZE if set.`', 'Setting this value caps the number of results in AJAX search dropdowns, overriding both THIRDPARTY_LIMIT_SIZE and PRODUIT_LIMIT_SIZE.', 'Integer (maximum result count); 0 or empty means the module-specific limit (e.g. THIRDPARTY_LIMIT_SIZE or PRODUIT_LIMIT_SIZE) applies, defaulting to 1000 for company search.', 1, 0, NULL, 1, '7f0da7695734e6a050879072aed002c0b4449fcea581fbb25929060cc91c7d19', 'v2', '2026-04-21T11:16:15+00:00', '["societe/ajax/ajaxcompanies.php:142|read|$limit = getDolGlobalInt(''SEARCH_LIMIT_AJAX'') ?: 1000;\t\t// SEARCH_LIMIT_AJAX is a hidden option that has priority on option THIRDPARTY_LIMIT_SIZE if set.", "core/class/html.form.class.php:3407|read|$limit = getDolGlobalInt(''SEARCH_LIMIT_AJAX'') ?: $limit;\t\t// SEARCH_LIMIT_AJAX is a hidden option that has priority on visible option PRODUIT_LIMIT_SIZE if set."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SECURITY_DISABLE_TEST_ON_OBFUSCATED_CONF', 'bool', NULL, 'admin', 'Disables the Security page''s warning check for whether the database password in conf.php is stored obfuscated/encrypted.', 'Read at admin/system/security.php:448 (module admin, page admin/system/security.php); when set, the block checking $dolibarr_main_db_pass vs $dolibarr_main_db_encrypted_pass and printing a warning is skipped entirely.', 'Enabling it suppresses the ''DatabasePasswordNotObfuscated'' warning on the Security diagnostics page even if the DB password is stored in clear text in conf.php, hiding a legitimate security recommendation.', 'Boolean: true/1 disables the obfuscated-password test/warning display, false/unset (default) keeps the check active.', 0, 0, 'admin/system/security.php', 1, 'c2ce8514ec3b5adbcd03b8aaeb59d129cd666ffed9d5d98567036a7530278cf7', 'v2', '2026-07-24T07:05:23+00:00', '["admin/system/security.php:448|check|if (!getDolGlobalString(''SECURITY_DISABLE_TEST_ON_OBFUSCATED_CONF'')) { print ''<strong>$dolibarr_main_db_pass</strong>: ''; ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SELLYOURSAAS_MAIN_EMAIL', 'string', NULL, 'core', 'Would hold a support contact email address to include in a Stripe payment-failure message, for the (third-party) SellYourSaaS integration.', 'Referenced only in a trailing comment in core/class/commoninvoice.class.php:1941, appended (commented out) to a hardcoded string ''Action required. Contact the support at ''; the active code does not append this value.', 'Since the reference is commented out, this constant currently has no effect; the live code uses only the static string without the support email appended.', 'Exact behavior unclear from code alone [SPECULATION] - intended to be an email address string.', 1, 0, NULL, 1, 'f8af21a2741b96d6e67c0507efa23c32f44aa99246420372104fcf3ae0c7e2c4', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commoninvoice.class.php:1941: $stripefailuremessage = ''Action required. Contact the support at '';// . $conf->global->SELLYOURSAAS_MAIN_EMAIL;"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SELLYOURSAAS_NBDAYSBEFOREENDOFTRIES', 'string', NULL, 'core', 'Would configure the number of days after which retrying a failed SaaS subscription payment stops, for the (third-party) SellYourSaaS module''s invoice retry logic.', 'Referenced only inside a commented-out code block in core/class/commoninvoice.class.php:1895, where it would default to 35 days if unset; the surrounding retry logic is not active PHP code.', 'Since the only reference is commented out, this constant currently has no effect in this codebase; the comment documents an intended default of 35 days before retries end.', 'Integer, days; comment default is 35 if empty/unset.', 1, 0, NULL, 1, 'ee05546518b0c69719e9d303aeeb2a233c47597dd6a2969a8f8252cf2433abbf', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commoninvoice.class.php:1895: // $nbdaysbeforeendoftries = (empty($conf->global->SELLYOURSAAS_NBDAYSBEFOREENDOFTRIES) ? 35 : $conf->global->SELLYOURSAAS_NBDAYSBEFOREENDOFTRIES);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SELLYOURSAAS_NBHOURSBETWEENTRIES', 'string', NULL, 'core', 'Would configure the minimum number of hours between automatic retry attempts of a failed SaaS subscription payment, for the (third-party) SellYourSaaS module''s invoice retry logic.', 'Referenced only inside a commented-out code block in core/class/commoninvoice.class.php:1894, where it would default to 49 hours if unset; the surrounding retry logic is not active PHP code.', 'Since the only reference is commented out, this constant currently has no effect in this codebase; the comment documents an intended default of 49 hours, described as needing to be ''more that 48 hours + 1 between each try (so 1 try every 3 daily batch)''.', 'Integer, hours; comment default is 49 if empty/unset.', 1, 0, NULL, 1, '5862a4f60177a14a269963b74d7bb8f313256227d7efb940d4967cb8e5fdc329', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/commoninvoice.class.php:1894: // $nbhoursbetweentries = (empty($conf->global->SELLYOURSAAS_NBHOURSBETWEENTRIES) ? 49 : $conf->global->SELLYOURSAAS_NBHOURSBETWEENTRIES); // Must have more that 48 hours + 1 between each try (so 1 try every 3 daily batch)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SENDING_DRAFT_WATERMARK', 'string', NULL, 'core', 'Stores the watermark text to overlay on draft sending (merou template) PDFs.', 'Checked and applied in core/modules/expedition/doc/pdf_merou.modules.php:520-521. When the object status is 0 (draft) and this constant is set, pdf_watermark() is called with the constant''s value from $conf->global->SENDING_DRAFT_WATERMARK.', 'Setting a non-empty value causes draft merou shipping PDFs to display the specified watermark. Clearing the value removes the watermark from those PDFs.', 'Any non-empty string = watermark text displayed on draft merou PDFs; empty/unset = no watermark.', 1, 0, NULL, 1, 'f7bcfa345032f7486ec396542b9dd7b76a62291804ea5244e97df88cc93780f8', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_merou.modules.php:520|if ($object->statut == 0 && (getDolGlobalString(''SENDING_DRAFT_WATERMARK''))) {", "pdf_merou.modules.php:521|pdf_watermark($pdf, $outputlangs, $this->page_hauteur, $this->page_largeur, ''mm'', $conf->global->SENDING_DRAFT_WATERMARK);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEPA_FORCE_TWO_DECIMAL', 'string', NULL, 'compta', 'Forces amounts in SEPA XML files to always be formatted with exactly two decimal places.', 'Checked in bonprelevement.class.php at lines 2004, 2151, 2387, and 2695 during XML amount formatting for both direct debit and credit transfer SEPA files. No admin UI write path exists.', 'Enabling this constant overrides the default amount formatting in SEPA XML to always use two decimals; without it the standard formatting is applied.', 'Truthy string/bool=two-decimal forced, empty/0=default formatting', 1, 0, NULL, 1, 'f45d493c8b7a958ddd65994578a56d72ea52d8a43ef62de64a14005514c37f2d', 'v2', '2026-04-21T11:16:15+00:00', '["compta/prelevement/class/bonprelevement.class.php:2004|check|if (getDolGlobalString(''SEPA_FORCE_TWO_DECIMAL'')) {", "compta/prelevement/class/bonprelevement.class.php:2151|check|if (getDolGlobalString(''SEPA_FORCE_TWO_DECIMAL'')) {", "compta/prelevement/class/bonprelevement.class.php:2387|check|if (getDolGlobalString(''SEPA_FORCE_TWO_DECIMAL'')) {", "compta/prelevement/class/bonprelevement.class.php:2695|check|if (getDolGlobalString(''SEPA_FORCE_TWO_DECIMAL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SEPA_USE_IDS', 'bool', NULL, 'compta', 'Switches the SEPA bank transfer ICS field to use the account''s ics_transfer value instead of the standard ics.', 'Checked in compta/bank/card.php:869 and 1218, and used in bonprelevement.class.php:1558 and 2676 to select between $account->ics_transfer and $account->ics when generating SEPA XML. No admin UI write path exists.', 'Enabling this constant causes bank transfer SEPA files to use the dedicated ics_transfer identifier; without it the standard ICS is used for both direct debits and transfers.', 'Truthy string/bool=ics_transfer used for bank transfers, empty/0=standard ics used', 1, 0, NULL, 1, 'a5b6a6b1bf71f0af341d121ee804aae00cd218ecbd0d7e83750ab6ef7f7ef3e8', 'v2', '2026-04-21T11:16:15+00:00', '["compta/bank/card.php:869|check|if (getDolGlobalString(\"SEPA_USE_IDS\")) {\t// Use another ICS for bank transfer", "compta/bank/card.php:1218|check|if (getDolGlobalString(\"SEPA_USE_IDS\")) {\t// ICS is not used with bank transfer !", "compta/prelevement/class/bonprelevement.class.php:1558|read|$this->emetteur_ics = (($type == ''bank-transfer'' && getDolGlobalString(\"SEPA_USE_IDS\")) ? $account->ics_transfer : $account->ics);\t// Example \"FR78ZZZ123456\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SERVICE_ARE_ECOMMERCE_200238EC', 'string', NULL, 'core', 'Controls VAT rate combo behavior for services under EU e-commerce directive 2008/8/EC rules, based on buyer/seller country.', 'Checked with getDolGlobalString in accountancy/journal/cashsellsjournal.php, accountancy/journal/sellsjournal.php, core/class/html.form.class.php:8051, and core/lib/functions.lib.php, with explicit mode comments at html.form.class.php:8053-8054.', 'Value 1 makes the VAT rate combo list show rates of both purchaser and seller countries; value 2 makes it list only the purchaser country''s VAT rate; it also affects accountancy code selection based on buyer country per the sellsjournal.php comment.', '1=combo list vat rate of purchaser and seller countries; 2=combo list only the vat rate of the purchaser country', 0, 0, NULL, 1, 'f513601395574062c366fb1c5b5f9b77dee26faebc38b981a37ec83524741abe', 'v2', '2026-07-24T06:41:12+00:00', '["// If SERVICE_ARE_ECOMMERCE_200238EC=1 combo list vat rate of purchaser and seller countries", "// If SERVICE_ARE_ECOMMERCE_200238EC=2 combo list only the vat rate of the purchaser country", "// SERVICE_ARE_ECOMMERCE_200238EC makes the chosen accountancy code depend on the buyer country,"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SERVICE_BOOTH_LOCATION', 'string', NULL, 'public', 'Product/service used to invoice the booth location fee when a booth is a paying one on the public suggest-a-booth form.', 'Read in public/project/suggestbooth.php:443 as a product ID, fetched via Product::fetch() and used to build the invoice line when $project->price_booth is non-empty. Configurable in admin/eventorganization.php as a ''product'' type setting.', 'Setting it determines which product/service line is billed to exhibitors when the event''s booth price is set; without a valid product the invoice creation fails.', 'A product ID, selected via admin UI (type ''product'').', 0, 0, NULL, 1, 'f29f8df22fac34d5a438d5a03dafd47068a207e75735a6d374aa9076532cbd20', 'v2', '2026-07-24T07:05:23+00:00', '["public/project/suggestbooth.php:443: $resultprod = $productforinvoicerow->fetch(getDolGlobalInt(''SERVICE_BOOTH_LOCATION''));", "admin/eventorganization.php:73: ''SERVICE_BOOTH_LOCATION'' => array(''type'' => ''product'', ''enabled'' => 1, ''css'' => ''maxwidth500''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SERVICE_CONFERENCE_ATTENDEE_SUBSCRIPTION', 'string', NULL, 'public', 'Holds the product id of the service/product used to invoice attendee registration/subscription for event organization (conference/booth).', 'In public/eventorganization/attendee_new.php:553-554, if getDolGlobalInt(''SERVICE_CONFERENCE_ATTENDEE_SUBSCRIPTION'') > 0, that value is used as a product id to fetch() the Product object used to generate the attendee''s invoice.', 'Setting it to a valid product id makes the online attendee registration flow generate a draft invoice using that product as the line item for the registration/subscription fee.', 'Integer product id (rowid in llx_product); 0 or unset disables automatic invoice product lookup.', 1, 0, NULL, 1, '0b4df38f32ee88533bd48d79b9d87bf4fb4b2f7a10a1edd04fc9395eb6880bfe', 'v2', '2026-07-24T07:05:23+00:00', '["public/eventorganization/attendee_new.php:553: if (getDolGlobalInt(''SERVICE_CONFERENCE_ATTENDEE_SUBSCRIPTION'') > 0) {", "public/eventorganization/attendee_new.php:554: $resultprod = $productforinvoicerow->fetch(getDolGlobalInt(''SERVICE_CONFERENCE_ATTENDEE_SUBSCRIPTION''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SERVICE_STRICT_MANDATORY_PERIOD', 'string', NULL, 'product', 'When enabled, makes the service period (start and end dates) a strictly mandatory field when adding a service line to invoices, proposals, and orders.', 'Checked in compta/facture/card.php:5020, comm/propal/card.php:2993, and commande/card.php:2710 to enforce period entry. Also checked in product/card.php at lines 1709, 2347, and 2898 to conditionally allow or block period optionality.', 'Enabling this constant blocks submission of service lines without a defined period on invoices, proposals, and orders.', '0 or unset = service period optional; truthy = service period strictly required.', 1, 0, NULL, 1, 'a0ad10e45215343f4e7c8e5d279edc7fb635f7e7c0488f2a128b0df11fa6e642', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:5020|check|if (getDolGlobalString(''SERVICE_STRICT_MANDATORY_PERIOD'')) {", "comm/propal/card.php:2993|check|if (getDolGlobalString(''SERVICE_STRICT_MANDATORY_PERIOD'')) {", "commande/card.php:2710|check|if (getDolGlobalString(''SERVICE_STRICT_MANDATORY_PERIOD'')) {", "product/card.php:2898|check|if (!getDolGlobalString(''SERVICE_STRICT_MANDATORY_PERIOD'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_ADD_CONTACTS_IN_EXPORT', 'string', NULL, 'core', 'When enabled, includes shipment contact records in shipment export data sets.', 'Checked four times in core/modules/modExpedition.class.php (lines 257, 281, 285, 318); in each case the condition is ''if ($idcontacts && getDolGlobalString(...))'', meaning contact data is appended to the export only when the constant is set. No admin UI page is listed.', 'Enabling this constant causes contact-related fields to be added to shipment exports; leaving it unset omits contact data from those exports.', '1 or any truthy value = include contacts in export; 0 or unset = contacts excluded.', 1, 0, NULL, 1, 'aacd05bdac5ff870d929d9e71a7999690435dc1b9a911ed6e884b31335243e73', 'v2', '2026-04-21T13:29:58+00:00', '["core/modules/modExpedition.class.php:257|check|if ($idcontacts && getDolGlobalString(''SHIPMENT_ADD_CONTACTS_IN_EXPORT'')) {", "core/modules/modExpedition.class.php:281|check|if ($idcontacts && getDolGlobalString(''SHIPMENT_ADD_CONTACTS_IN_EXPORT'')) {", "core/modules/modExpedition.class.php:285|check|if ($idcontacts && getDolGlobalString(''SHIPMENT_ADD_CONTACTS_IN_EXPORT'')) {", "core/modules/modExpedition.class.php:318|check|if ($idcontacts && getDolGlobalString(''SHIPMENT_ADD_CONTACTS_IN_EXPORT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_ALLOW_NEGATIVE_QTY', 'bool', NULL, 'expedition', 'Allows stock movements with a negative quantity to be processed when validating a shipment, instead of being skipped.', 'Checked once in expedition/class/expedition.class.php:3064 inside the shipment validation loop that creates stock movements: rows with qty <= 0 are normally skipped (''continue''), and a negative qty is only skipped unless this constant is set.', 'Enabling it lets validate() process stock movement rows with a negative quantity (rather than silently skipping them), which affects stock movement history/quantities created on shipment validation.', 'Boolean via getDolGlobalInt: truthy allows negative-quantity rows to be processed instead of skipped.', 1, 0, NULL, 1, 'b1cbae4ae907fa79760418470b0a817f4cfc12a9793f77835850f4d7840dc857', 'v2', '2026-07-24T07:05:23+00:00', '["expedition/class/expedition.class.php:3064: if ($qty <= 0 || ($qty < 0 && !getDolGlobalInt(''SHIPMENT_ALLOW_NEGATIVE_QTY''))) {", "expedition/class/expedition.class.php:3065: continue;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_DONT_PREFILL_QTY', 'string', NULL, 'expedition', 'Prevents automatic pre-filling of shipment line quantities when creating a shipment from an order.', 'Checked in expedition/card.php at lines 2124, 2267, 2384, and 2515 using getDolGlobalBool with a default of false; when true, quantity fields are not pre-populated.', 'Enabling this constant requires users to manually enter quantities on each shipment line. Disabling it (or leaving unset) causes quantities to be pre-filled from the source order.', 'true/1 = do not pre-fill quantities; false/0 or unset = pre-fill quantities (default false).', 1, 0, NULL, 1, 'cf63aa2988774eb06bfcba4e5ce4a9e2b31594fabdc3a1893078296b1f8e92d0', 'v2', '2026-04-21T13:50:40+00:00', '["expedition/card.php:2124|check|if (getDolGlobalBool(''SHIPMENT_DONT_PREFILL_QTY'', false)) {", "expedition/card.php:2267|check|if (getDolGlobalBool(''SHIPMENT_DONT_PREFILL_QTY'', false)) {", "expedition/card.php:2384|check|if (getDolGlobalBool(''SHIPMENT_DONT_PREFILL_QTY'', false)) {", "expedition/card.php:2515|check|if (getDolGlobalBool(''SHIPMENT_DONT_PREFILL_QTY'', false)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_GETS_ALL_ORDER_PRODUCTS', 'string', NULL, 'expedition', 'When enabled, includes order lines with zero quantity in shipments, ensuring all ordered products appear even when none have been shipped.', 'Checked across expedition/card.php, expedition/class/expedition.class.php, and compta/facture/card.php at multiple lines. Controls whether zero-quantity lines are included in shipment creation and invoice generation from shipments.', 'Enabling this constant causes shipments to include all order lines regardless of quantity, which affects both shipment records and invoices generated from those shipments.', '0 or unset = only lines with qty > 0 are included in shipments; truthy = zero-quantity lines are also included.', 1, 0, NULL, 1, '899675052c9b4d3a28d6bfb635ad359ce224ce95c10397fb68d2dc28fdca4676', 'v2', '2026-04-21T11:16:15+00:00', '["expedition/class/expedition.class.php:1544|check|if ($value[''q''] > 0 || ($value[''q''] == 0 && getDolGlobalString(''SHIPMENT_GETS_ALL_ORDER_PRODUCTS''))) {", "expedition/card.php:512|check|if (($totalqty > 0 || getDolGlobalString(''SHIPMENT_GETS_ALL_ORDER_PRODUCTS'')) && !$error) {\t\t// There is at least one thing to ship and no error", "compta/facture/card.php:1918|check|if ($srcobject->element == ''shipping'' && getDolGlobalString(''SHIPMENT_GETS_ALL_ORDER_PRODUCTS'') && $lines[$i]->qty == 0) {", "expedition/class/expedition.class.php:1556|check|if ($linebatch->qty == 0 && getDolGlobalString(''SHIPMENT_GETS_ALL_ORDER_PRODUCTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_ROUND_VOLUME_ON_PDF', 'string', NULL, 'core', 'Sets the number of decimal places used when rounding line-item volume on shipment PDFs.', 'Used in pdf_rouget.modules.php and pdf_espadon.modules.php as the precision argument of PHP''s round() when computing volume text per line. Defaults to 5 when unset via getDolGlobalInt(''SHIPMENT_ROUND_VOLUME_ON_PDF'', 5).', 'Changing this value alters the displayed precision of per-line volume figures on shipment PDFs. The default precision is 5 decimal places when the constant is absent.', 'Integer = number of decimal places for rounding (default 5 when unset).', 1, 0, NULL, 1, 'bb20bdec5721d35be69c28dd6486873c3f734287c8dad216e9129739067fe71c', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_rouget.modules.php:587|$voltxt = round($object->lines[$i]->volume * $object->lines[$i]->qty_shipped, getDolGlobalInt(''SHIPMENT_ROUND_VOLUME_ON_PDF'', 5))", "pdf_espadon.modules.php:715|$voltxt = round($object->lines[$i]->volume * $object->lines[$i]->qty_shipped, getDolGlobalInt(''SHIPMENT_ROUND_VOLUME_ON_PDF'', 5))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_ROUND_WEIGHT_ON_PDF', 'string', NULL, 'core', 'Sets the number of decimal places used when rounding line-item weight on shipment PDFs.', 'Used in pdf_rouget.modules.php and pdf_espadon.modules.php as the precision argument of PHP''s round() when computing weight text per line. Defaults to 5 when unset via getDolGlobalInt(''SHIPMENT_ROUND_WEIGHT_ON_PDF'', 5).', 'Changing this value alters the displayed precision of per-line weight figures on shipment PDFs. The default precision is 5 decimal places when the constant is absent.', 'Integer = number of decimal places for rounding (default 5 when unset).', 1, 0, NULL, 1, '0f35a6626e9ef7fe04af057809c3e46954d15e8636a3d93b7b3aaf2431b57bdb', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_rouget.modules.php:583|$weighttxt = round($object->lines[$i]->weight * $object->lines[$i]->qty_shipped, getDolGlobalInt(''SHIPMENT_ROUND_WEIGHT_ON_PDF'', 5))", "pdf_espadon.modules.php:711|$weighttxt = round($object->lines[$i]->weight * $object->lines[$i]->qty_shipped, getDolGlobalInt(''SHIPMENT_ROUND_WEIGHT_ON_PDF'', 5))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_SIGNATURE_ON_ALL_PAGES', 'string', NULL, 'core', 'Controls whether the online signature image is stamped on every page of a shipment (expedition) PDF or only the last one.', 'Checked in core/ajax/onlineSign.php:918 inside the PDF page loop, and again at line 935 (negated) after the loop. Unlike the fichinter variant, the shipment signature position is always hardcoded ($param[''xforimgstart''] = 111).', 'When set, the signature image is drawn on each imported PDF page; when unset, it is drawn once after all pages, at the same fixed coordinates in both cases.', 'Boolean-like (truthy/falsy), no explicit value list in code.', 1, 0, NULL, 1, 'b7c15c5174cac37586a9fe0717a5a97ec1f69ec271ee54040837757b949084e3', 'v2', '2026-07-24T07:05:23+00:00', '["core/ajax/onlineSign.php:918: if (getDolGlobalString(\"SHIPMENT_SIGNATURE_ON_ALL_PAGES\")) {", "core/ajax/onlineSign.php:935: if (!getDolGlobalString(\"SHIPMENT_SIGNATURE_ON_ALL_PAGES\")) {", "core/ajax/onlineSign.php:920: $param[''xforimgstart''] = 111;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_STANDALONE', 'string', NULL, 'expedition', 'Allows creating standalone shipments that are not linked to (originated from) a sales order.', 'Checked with getDolGlobalString across expedition/card.php (multiple lines: 861, 1451, 1466, 3137, 2851, 319, 1176) and ai/tools/crud_objects.class.php:659, gating behavior when $origin is empty.', 'When enabled, shipment creation and the ''addline'' action in expedition/card.php no longer require an $origin document such as a sales order.', NULL, 0, 0, NULL, 1, '68a89d042266fbcb38dbd07ab00717eec6afe3250164a4f536f1ff3001bb791c', 'v2', '2026-07-24T06:41:12+00:00', '["if (!$origin && getDolGlobalString(''SHIPMENT_STANDALONE'')) {", "if (!$origin && $action == ''create'' && !getDolGlobalString(''SHIPMENT_STANDALONE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPMENT_SUPPORTS_SERVICES', 'string', NULL, 'expedition', 'Allows service-type products to be included in shipment/expedition lines when enabled.', 'Checked extensively across expedition/class/expedition.class.php and expedition/card.php. When set, service products are permitted in shipment lines; when not set, only physical products are allowed by default unless STOCK_SUPPORTS_SERVICES is also set.', 'Enabling this constant allows service lines to be added to shipments, affecting stock movement logic and shipment line validation across multiple files.', 'Truthy value (e.g. 1) to allow services in shipments; empty or 0 to restrict to physical products.', 1, 0, NULL, 1, 'a40edc78b14c8215e8dbf004befbc76a5cdcdeff63a1e17b5b1b13bee2a31088', 'v2', '2026-04-21T13:50:40+00:00', '["expedition/class/expedition.class.php:538|check|if (empty($this->lines[$i]->product_type) || getDolGlobalString(''STOCK_SUPPORTS_SERVICES'') || getDolGlobalString(''SHIPMENT_SUPPORTS_SERVICES'')) {", "expedition/card.php:2092|check|if ($line->product_type == Product::TYPE_SERVICE && !getDolGlobalString(''STOCK_SUPPORTS_SERVICES'') && !getDolGlobalString(''SHIPMENT_SUPPORTS_SERVICES'')) {", "expedition/card.php:2107|check|if (($line->product_type == Product::TYPE_SERVICE && getDolGlobalString(''SHIPMENT_SUPPORTS_SERVICES'')) || $product->stockable_product == Product::DISABLED_STOCK) {", "expedition/class/expedition.class.php:1282|check|if (!($entrepot_id > 0) && !getDolGlobalString(''STOCK_WAREHOUSE_NOT_REQUIRED_FOR_SHIPMENTS'') && !(getDolGlobalString(''SHIPMENT_SUPPORTS_SERVICES'') && $line->product_type == Product"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPABLE_ORDER_ICON_IN_LIST', 'string', NULL, 'commande', 'Controls whether a shippable-order icon is displayed in the customer order list view.', 'Checked in commande/class/commande.class.php:4397 and commande/list_det.php:2152; the default branch (no icon) is taken when the constant is empty, as noted by the inline comment ''Default code. Default should be this case.''', 'When set, an alternative icon display path is used in order lists; when unset the default (no icon) is used.', 'Bool-like string: empty/unset = default (no icon); non-empty = show shippable icon.', 1, 0, NULL, 1, '4a219818ba99a335b44bc178a2d860d5938a0ff6ff0774ad138db991b4cd646b', 'v2', '2026-04-21T13:50:40+00:00', '["commande/class/commande.class.php:4397|check|if (!getDolGlobalString(''SHIPPABLE_ORDER_ICON_IN_LIST'')) {", "commande/list_det.php:2152|check|if (!getDolGlobalString(''SHIPPABLE_ORDER_ICON_IN_LIST'')) {  // Default code. Default should be this case."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_DISPLAY_STOCK_ENTRY_DATE', 'string', NULL, 'expedition', 'Displays stock entry date columns in shipment and product batch selection interfaces.', 'Checked in product/class/productbatch.class.php at lines 499, 512, 520, 528, 555 and in expedition/card.php at lines 1937, 2175, 2205, with additional occurrences. Controls conditional rendering of stock entry date data in shipment line picking.', 'When enabled, the stock entry date is shown alongside batch/lot information during shipment preparation, aiding FIFO/FEFO picking decisions.', 'Truthy string (entry date column shown) or empty/unset (column hidden).', 1, 0, NULL, 1, '4a7f21a58fbf97485c5b7e487af4a9e84a353597d3f0db348098cc6a1943e99d', 'v2', '2026-04-21T13:29:58+00:00', '["product/class/productbatch.class.php:499|check|if (getDolGlobalString(''SHIPPING_DISPLAY_STOCK_ENTRY_DATE'')) {", "product/class/productbatch.class.php:512|check|if (getDolGlobalString(''SHIPPING_DISPLAY_STOCK_ENTRY_DATE'')) {", "expedition/card.php:1937|check|if (getDolGlobalString(''SHIPPING_DISPLAY_STOCK_ENTRY_DATE'')) {", "expedition/card.php:2205|check|if (getDolGlobalString(''SHIPPING_DISPLAY_STOCK_ENTRY_DATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_DRAFT_WATERMARK', 'string', NULL, 'core', 'Stores the watermark text to overlay on draft shipping PDFs.', 'Configurable via the admin UI at admin/expedition.php. When a shipping object is in draft status and this constant is set, its value is assigned to $this->watermark and rendered as a PDF watermark in pdf_rouget.modules.php and pdf_espadon.modules.php. Also used by pdf_eagle.modules.php for stock transfers.', 'Setting a non-empty value causes draft shipment PDFs to display the specified watermark text. Clearing the value removes the watermark from draft PDFs.', 'Any non-empty string = watermark text displayed on draft PDFs; empty/unset = no watermark.', 0, 0, 'admin/expedition.php|admin/expedition.php', 1, '4da7713a173f3aa6043be7c4d16c45c9bb56f367892efb1aebe28e201720036b', 'v2', '2026-04-21T13:50:40+00:00', '["admin/expedition.php:99|$res = dolibarr_set_const($db, \"SHIPPING_DRAFT_WATERMARK\", trim($draft), ''chaine'', 0, '''', $conf->entity);", "pdf_rouget.modules.php:194|if ($object->statut == $object::STATUS_DRAFT && (getDolGlobalString(''SHIPPING_DRAFT_WATERMARK''))) {", "pdf_rouget.modules.php:195|$this->watermark = getDolGlobalString(''SHIPPING_DRAFT_WATERMARK'');", "pdf_eagle.modules.php:1034|pdf_watermark($pdf, $outputlangs, $this->page_hauteur, $this->page_largeur, ''mm'', $conf->global->SHIPPING_DRAFT_WATERMARK);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_EMAIL_SENDER', 'string', NULL, 'core', 'Sets the ''From'' email address used when pre-filling the send-by-email form for shipments.', 'Used in core/tpl/card_presend.tpl.php:201-202: when $object->element === ''shipping'' and this constant is truthy, $formmail->frommail is set to its value (and fromtype forced to ''special'').', 'Setting it overrides the default sender email address specifically for outgoing shipment notification emails.', 'Free-text email address string; when non-empty, activates the shipping-specific sender override branch.', 0, 0, NULL, 1, '73d810c232380f46125cb317ca200d10c7da9cae8c11d4ab5eb768a37b19b3fb', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:201|check|if ($object->element === ''shipping'' && getDolGlobalString(''SHIPPING_EMAIL_SENDER'')) {", "core/tpl/card_presend.tpl.php:202|read|$formmail->frommail = getDolGlobalString(''SHIPPING_EMAIL_SENDER'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_EMAIL_SENDER_NAME', 'string', NULL, 'core', 'Sets the ''From'' display name used when pre-filling the send-by-email form for shipments.', 'Used in core/tpl/card_presend.tpl.php:203 to set $formmail->fromname when the shipping sender branch is active (guarded by SHIPPING_EMAIL_SENDER at line 201), defaulting to empty string.', 'Setting it customizes the sender display name on shipment emails; only applies within the shipping branch guarded by SHIPPING_EMAIL_SENDER.', 'Free-text sender display name string; defaults to '''' if unset.', 0, 0, NULL, 1, '59749fa5720fd8d7075349b559837239714bf7bd725cffb8b6458c7169aa6470', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:203|read|$formmail->fromname = getDolGlobalString(''SHIPPING_EMAIL_SENDER_NAME'', '''');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_FREE_TEXT', 'string', NULL, 'admin', 'Stores free/custom footer text to include on generated shipment documents.', 'Written from admin/expedition.php:92 via dolibarr_set_const() when the admin saves the shipment (expedition) module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated shipment documents; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'admin/expedition.php', 1, 'daa1e8148fab760b79569038634ba0cd8cd0fc72d402e2d28b7e40053479b925', 'v2', '2026-07-24T07:05:23+00:00', '["admin/expedition.php:92|write|$res = dolibarr_set_const($db, \"SHIPPING_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_PDF_DISPLAY_AMOUNT_HT', 'string', NULL, 'core', 'Enables display of pre-tax unit amounts (prices) on shipping PDF documents when set.', 'Checked in core/modules/expedition/doc/pdf_rouget.modules.php at lines 123 (with comment ''// Show also the prices''), 605, 799, and 899. Also read in core/modules/expedition/doc/pdf_espadon.modules.php at lines 1443 and 1454 to set column status. No admin UI write is present.', 'When set, price columns are rendered in shipping PDF output across multiple templates. When unset, price columns are hidden.', 'Truthy value (e.g. 1) to show prices on shipping PDFs; 0 or empty to hide them.', 1, 0, NULL, 1, 'e20ff780d9f05500396bd72dff1c8bedfd359dfd7ff301aae5e9fbf92ce101b3', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/expedition/doc/pdf_rouget.modules.php:123|check|if (getDolGlobalString(''SHIPPING_PDF_DISPLAY_AMOUNT_HT'')) {\t// Show also the prices", "core/modules/expedition/doc/pdf_rouget.modules.php:605|check|if (getDolGlobalString(''SHIPPING_PDF_DISPLAY_AMOUNT_HT'')) {", "core/modules/expedition/doc/pdf_espadon.modules.php:1443|read|''status'' => getDolGlobalString(''SHIPPING_PDF_DISPLAY_AMOUNT_HT'') ? 1 : 0,", "core/modules/expedition/doc/pdf_espadon.modules.php:1454|read|''status'' => getDolGlobalString(''SHIPPING_PDF_DISPLAY_AMOUNT_HT'') ? 1 : 0,"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_PDF_HIDE_ORDERED', 'bool', NULL, 'core', 'When set, hides the ordered-quantity column from shipping PDF documents across multiple templates.', 'Controls whether the ordered quantity column is rendered in shipping PDFs. Checked in pdf_rouget.modules.php, pdf_espadon.modules.php, and pdf_merou.modules.php across 9 occurrences.', 'Enabling this removes the ordered quantity from printed shipment documents. Disabling (or leaving unset) causes ordered quantity to be shown.', 'Empty/unset = show ordered quantity; any truthy value = hide ordered quantity.', 1, 0, NULL, 1, '98e5a21d21359c4740afa1246c47be505130cffa4130a8bc988f30bfbffd2457', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_rouget.modules.php:145|if (getDolGlobalString(''SHIPPING_PDF_HIDE_ORDERED'')) {", "pdf_rouget.modules.php:595|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_ORDERED'')) {", "pdf_espadon.modules.php:900|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_ORDERED'')) {", "pdf_merou.modules.php:329|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_ORDERED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_PDF_HIDE_QTYTOSHIP', 'bool', NULL, 'core', 'When set, hides the quantity-to-ship column from shipping PDF documents.', 'Checked in pdf_rouget.modules.php, pdf_merou.modules.php, and pdf_espadon.modules.php before rendering or exposing the qty-to-ship column. In pdf_espadon.modules.php the value is mapped to a column status flag.', 'Enabling this removes the quantity-to-ship column from shipping PDFs. Disabling (or leaving unset) shows the column.', 'Empty/unset = show qty-to-ship column; any truthy value = hide qty-to-ship column.', 1, 0, NULL, 1, '81c1fa035d917a58b851327e562307ea0a17c969d276e62f45ef10aaf990d75f', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_rouget.modules.php:600|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_QTYTOSHIP'')) {", "pdf_rouget.modules.php:794|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_QTYTOSHIP'')) {", "pdf_merou.modules.php:334|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_QTYTOSHIP'')) {", "pdf_espadon.modules.php:1493|''status'' => !getDolGlobalString(''SHIPPING_PDF_HIDE_QTYTOSHIP''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_PDF_HIDE_VOLUME', 'bool', NULL, 'core', 'When set, suppresses volume data from line items and totals in shipping PDF documents.', 'Checked in pdf_rouget.modules.php and pdf_espadon.modules.php before rendering per-line volume text and total volume sections. The guard combines checks on non-empty volume values with the negation of this constant.', 'Enabling this hides all volume information (per-line and totals) from shipping PDFs. Disabling (or leaving unset) allows volume to be rendered wherever non-zero values exist.', 'Empty/unset = show volume; any truthy value = hide volume.', 1, 0, NULL, 1, 'a3bd4edb174ffb4597eaea24d39144a319c15f25dc64ec141af1e3ec53e83b46', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_rouget.modules.php:586|if (empty($object->lines[$i]->fk_product_type) && $object->lines[$i]->volume && !getDolGlobalString(''SHIPPING_PDF_HIDE_VOLUME'')) {", "pdf_rouget.modules.php:775|if (!empty($totalVolume) && !getDolGlobalString(''SHIPPING_PDF_HIDE_VOLUME'')) {", "pdf_espadon.modules.php:714|if (empty($object->lines[$i]->fk_product_type) && $object->lines[$i]->volume && !getDolGlobalString(''SHIPPING_PDF_HIDE_VOLUME'')", "pdf_espadon.modules.php:927|if (!empty($totalVolume) && !getDolGlobalString(''SHIPPING_PDF_HIDE_VOLUME'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_PDF_HIDE_WEIGHT_AND_VOLUME', 'bool', NULL, 'core', 'When set, suppresses the weight and volume columns from shipping PDF documents.', 'Controls whether weight and volume data appear in shipping PDFs generated by the rouget template. All four occurrences are in core/modules/expedition/doc/pdf_rouget.modules.php, checked before rendering weight/volume cells.', 'Enabling this hides weight and volume information from printed shipment documents. Disabling (or leaving unset) causes weight and volume to be rendered in the PDF.', 'Empty/unset = show weight and volume; any truthy value = hide weight and volume.', 1, 0, NULL, 1, 'e1c2728ca67239ea365a956fcf4f69b025c232ec8f4885ba0d88237d8f336b74', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_rouget.modules.php:590|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_WEIGHT_AND_VOLUME'')) {", "pdf_rouget.modules.php:807|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_WEIGHT_AND_VOLUME'')) {", "pdf_rouget.modules.php:131|if (getDolGlobalString(''SHIPPING_PDF_HIDE_WEIGHT_AND_VOLUME'')) {", "pdf_rouget.modules.php:875|if (!getDolGlobalString(''SHIPPING_PDF_HIDE_WEIGHT_AND_VOLUME'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHIPPING_USE_ITS_OWN_CONTACTS', 'bool', NULL, 'core', 'Enables shipments to maintain their own independent contact list instead of inheriting contacts from the source order.', 'Checked across core/class/commonobject.class.php:1870, expedition/contact.php:70, api/class/api_setup.class.php:1211, core/tpl/contacts.tpl.php:159/:204/:233, and core/lib/sendings.lib.php:75. When not set, shipping contacts are inherited from the source order; when set, the shipment manages its own contacts. Also used at expedition/class/expedition.class.php:683 to propagate contacts from origin when enabled.', 'When enabled, shipments have their own contact management independent of the source order; when disabled, contacts are inherited from the originating order.', '0 or not set = shipping contacts inherited from source order; non-zero = shipment uses its own independent contact list.', 1, 0, NULL, 1, '84e6a1f7c43f62baa6e16aafe3a0c4deb0ba31c946df5787e5fbdebb8161ef14', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/commonobject.class.php:1870|check|if (!getDolGlobalInt(''SHIPPING_USE_ITS_OWN_CONTACTS'') && $this->element == ''shipping'' && $this->origin_id != 0) {", "expedition/contact.php:70|check|if (!getDolGlobalInt(''SHIPPING_USE_ITS_OWN_CONTACTS'') && $typeobject == ''commande'' && $object->origin_object->id && isModEnabled(''order'')) {", "api/class/api_setup.class.php:1211|check|if ($type == ''expedition'' && !getDolGlobalInt(''SHIPPING_USE_ITS_OWN_CONTACTS'')) {", "expedition/class/expedition.class.php:683|check|if (!$error && $this->id && getDolGlobalInt(''SHIPPING_USE_ITS_OWN_CONTACTS'') && getDolGlobalString(''MAIN_PROPAGATE_CONTACTS_FROM_ORIGIN'') && !empty($this->origin_type)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHOW_DIALOG_HOMEPAGE', 'bool', NULL, 'core', 'Controls whether a dialog popup is shown on the homepage and, if so, its auto-close delay in milliseconds.', 'Checked in core/boxes/box_actions_future.php:218 and core/boxes/box_actions.php:217 for presence, and as an integer >1 at lines 260/259 for the auto-close feature. The value is multiplied by 1000 at lines 263/262 to convert to milliseconds.', 'Setting this to 1 shows the dialog without auto-close; setting it to a value greater than 1 shows the dialog and auto-closes it after (value × 1000) milliseconds.', '0 or not set = no dialog; 1 = dialog shown, no auto-close; integer > 1 = dialog shown, auto-closes after value×1000 ms', 1, 0, NULL, 1, 'ccaba27c5eb917442b035cba847826e58ca731a5e0ea302bc14db9ca581f7967', 'v2', '2026-04-21T11:16:15+00:00', '["core/boxes/box_actions_future.php:218|check|if (getDolGlobalString(''SHOW_DIALOG_HOMEPAGE'')) {", "core/boxes/box_actions_future.php:260|check|if (getDolGlobalInt(''SHOW_DIALOG_HOMEPAGE'') > 1) {    // autoclose after this delay", "core/boxes/box_actions_future.php:263|read|$out .= ''}, ''.($conf->global->SHOW_DIALOG_HOMEPAGE * 1000).'');'';", "core/boxes/box_actions.php:262|read|$out .= ''}, ''.($conf->global->SHOW_DIALOG_HOMEPAGE * 1000).'');'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHOW_SOCINFO_ON_PRINT', 'bool', NULL, 'core', 'Adds company information to the page when printing, if the print CSS option is active.', 'Checked at main.inc.php:3501 when optioncss=''print'' is set and disable_show_socinfo_on_print is not passed. The comment at :3500 documents this behavior.', 'Enabling this inserts company information into the printed view of any page.', '0 or unset = company info not added on print; 1 (truthy) = company info injected when printing', 1, 0, NULL, 1, '0b4bcc77b6bc1befae73a6257846ce585d73a44fa7d5087abd33a02482df0f05', 'v2', '2026-04-21T11:16:15+00:00', '["main.inc.php:3500  // Permit to add user company information on each printed document by setting SHOW_SOCINFO_ON_PRINT", "main.inc.php:3501|check|if (getDolGlobalString(''SHOW_SOCINFO_ON_PRINT'') && GETPOST(''optioncss'', ''aZ09'') == ''print'' && empty(GETPOST(''disable_show_socinfo_on_print'', ''aZ09''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHOW_SUBPRODUCT_REF_IN_PDF', 'bool', NULL, 'admin', 'Controls whether the product reference of sub-products (kit components) is displayed in PDF line items.', 'Configured via admin/pdf.php (written at line 183, rendered as a yes/no selector at line 643). Checked at core/lib/pdf.lib.php:2021. The payload comment states: ''SHOW_SUBPRODUCT_REF_IN_PDF - Option to show the detail of product ref for kits.''', 'Enabling this shows the individual component references for kit/bundle products in generated PDFs.', 'SHOW_SUBPRODUCT_REF_IN_PDF - Option to show the detail of product ref for kits. 1 = show sub-product ref; 0 or absent = hide sub-product ref.', 0, 0, 'admin/pdf.php|admin/pdf.php', 1, 'dff04c01cddb948a5b11e8177cb0dbce670450d069f2392c478863695c5c9a21', 'v2', '2026-04-21T13:29:58+00:00', '["admin/pdf.php:637  // SHOW_SUBPRODUCT_REF_IN_PDF - Option to show the detail of product ref for kits.", "admin/pdf.php:183|write|dolibarr_set_const($db, \"SHOW_SUBPRODUCT_REF_IN_PDF\", GETPOST(''SHOW_SUBPRODUCT_REF_IN_PDF'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "admin/pdf.php:643|read|print $form->selectyesno(''SHOW_SUBPRODUCT_REF_IN_PDF'', getDolGlobalInt(''SHOW_SUBPRODUCT_REF_IN_PDF''), 1);", "core/lib/pdf.lib.php:2021|check|if (getDolGlobalString(''SHOW_SUBPRODUCT_REF_IN_PDF'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SHOW_TOTAL_OF_PREVIOUS_LISTS_IN_LIN_PAGE', 'bool', NULL, 'accountancy', 'When enabled, shows a totals section from previous lists on the accounting line-binding (LIN) pages.', 'Checked in accountancy/expensereport/index.php:438, accountancy/customer/index.php:577, and accountancy/supplier/index.php:561. The inline comment on each check reads: ''This part of code looks strange. Why showing a report that should rely on result of this step?''', 'Enabling this constant causes an additional totals block (from a prior step''s report) to appear on binding pages; the code comment indicates this behaviour is considered questionable.', 'Non-empty/truthy = show previous-list totals on LIN pages; empty/unset = hide (default)', 1, 0, NULL, 1, 'd27e021735c7932d2219793c449346d0a301863652e351b9620d14ae8a439a00', 'v2', '2026-04-21T11:16:15+00:00', '["accountancy/expensereport/index.php:438|check|if (getDolGlobalString(''SHOW_TOTAL_OF_PREVIOUS_LISTS_IN_LIN_PAGE'')) { // This part of code looks strange. Why showing a report that should rely on result of this step ?", "accountancy/customer/index.php:577|check|if (getDolGlobalString(''SHOW_TOTAL_OF_PREVIOUS_LISTS_IN_LIN_PAGE'')) { // This part of code looks strange. Why showing a report that should rely on result of this step ?", "accountancy/supplier/index.php:561|check|if (getDolGlobalString(''SHOW_TOTAL_OF_PREVIOUS_LISTS_IN_LIN_PAGE'')) { // This part of code looks strange. Why showing a report that should rely on result of this step ?"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SINVOICE_EMAIL_SENDER', 'string', NULL, 'core', 'Salary-slip email ''from'' address, but only used under a guard that tests the unrelated constant INVOICE_EMAIL_SENDER (naming inconsistency in card_presend.tpl.php).', 'In core/tpl/card_presend.tpl.php:191-193, when $object->element == ''salary'' and getDolGlobalString(''INVOICE_EMAIL_SENDER'') is truthy, the code sets $formmail->frommail = getDolGlobalString(''SINVOICE_EMAIL_SENDER'') (not INVOICE_EMAIL_SENDER as the guard would suggest). This means SINVOICE_EMAIL_SENDER only takes effect if the unrelated constant INVOICE_EMAIL_SENDER is also set.', 'Setting SINVOICE_EMAIL_SENDER alone has no effect on the salary-email sender field unless INVOICE_EMAIL_SENDER is also non-empty, due to the guard/read mismatch in the template.', 'Free-text email address string; only takes effect when the ''from'' guard condition (INVOICE_EMAIL_SENDER, non-empty) is also true.', 0, 0, NULL, 1, '3fdf1d6f3a139768387288a0b16d027665fcde814bee8ec3bd8c4280e346fa6a', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/card_presend.tpl.php:191|if ($object->element == ''salary'' && getDolGlobalString(''INVOICE_EMAIL_SENDER'')) {", "core/tpl/card_presend.tpl.php:192|$formmail->frommail = getDolGlobalString(''SINVOICE_EMAIL_SENDER'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SITUATION_DISPLAY_DIFF_ON_PDF', 'string', NULL, 'core', 'Controls whether situation invoice PDF lines show the incremental delta percentage or the cumulative percentage.', 'Read once in core/lib/pdf.lib.php:2825 as $showDelta, combined via xor with whether INVOICE_USE_SITUATION equals 1 (old cumulative mode) to decide which situation_percent value (delta vs cumulative) is printed on the line.', 'Toggling it changes whether situation invoice PDF lines display the non-cumulative delta of the current situation or the cumulative state, per the inline comments describing modes 1 and 2.', 'Boolean via getDolGlobalInt: comments describe ''2 = situation_percent is non-cumulative (delta of current situation)'' and ''1 = (old mode): situation_percent is cumulative (state at situation)''.', 1, 0, NULL, 1, '5ea6f60ab8efa587126b773d315462b8f9aafbd7bea32e895e2205a0934f70e2', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/pdf.lib.php:2822: // 2 = situation_percent is non-cumulative (delta of current situation)", "core/lib/pdf.lib.php:2823: // 1 = (old mode): situation_percent is cumulative (state at situation)", "core/lib/pdf.lib.php:2825: $showDelta = (bool) getDolGlobalInt(''SITUATION_DISPLAY_DIFF_ON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SKILLDET_ADDON_PDF', 'string', NULL, 'hrm', 'Default document/PDF model name used to generate a skill-detail (skilldet) document when none is otherwise specified.', 'Used in hrm/class/skilldet.class.php:960-961 inside generateDocument(): if no model is passed and the object has no model_pdf, the code falls back first to ''standard_skilldet'' then, if this constant is set, overrides $modele with its value.', 'Setting it changes the default PDF/document model used for skill-detail documents when none is specified elsewhere; if unset, ''standard_skilldet'' is used.', 'String: a document model code recognized by the hrm skilldet document generators. Default fallback: ''standard_skilldet''.', 1, 0, NULL, 1, '64a5ce9b45d0e3ac8e5b16eafa9964f845c5fe5ade6b0806ed5c7924febe8c8b', 'v2', '2026-07-24T07:05:23+00:00', '["hrm/class/skilldet.class.php:960|read|} elseif (getDolGlobalString(''SKILLDET_ADDON_PDF'')) {", "hrm/class/skilldet.class.php:961|read|$modele = getDolGlobalString(''SKILLDET_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SKILLRANK_ADDON_PDF', 'string', NULL, 'hrm', 'Name of the PDF document model (template) used to generate PDFs for HRM skill-rank objects.', 'Used as fallback model name in SkillRank''s document-generation method when $this->model_pdf is empty, hrm/class/skillrank.class.php:1000-1001, same pattern as SKILL_ADDON_PDF.', 'Changing it selects which PDF generation model class is used to build the skill-rank PDF document.', 'Name of a skillrank PDF doc-generation model.', 1, 0, NULL, 1, '37cf76ebf765fc5144d84f2e697ec1d1a1ec92aa3b9d1cb175fd265e3bb3a7ea', 'v2', '2026-07-24T07:05:23+00:00', '["hrm/class/skillrank.class.php:1000|read|} elseif (getDolGlobalString(''SKILLRANK_ADDON_PDF'')) {", "hrm/class/skillrank.class.php:1001|read|$modele = getDolGlobalString(''SKILLRANK_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SKILL_ADDON_PDF', 'string', NULL, 'hrm', 'Name of the PDF document model (template) used to generate PDFs for HRM skill objects.', 'Used as fallback model name in Skill::generateDocument() when $this->model_pdf is empty, hrm/class/skill.class.php:1093-1094. Falls back to ''standard_skill'' if unset.', 'Changing it selects which PDF generation model class is used to build the skill PDF document.', 'Name of a skill PDF doc-generation model (default ''standard_skill'' if unset).', 1, 0, NULL, 1, '9f1d1ff007164f579ce1e660c6506e367d164255c1bce04d95dd7169758ecf61', 'v2', '2026-07-24T07:05:23+00:00', '["hrm/class/skill.class.php:1093|read|} elseif (getDolGlobalString(''SKILL_ADDON_PDF'')) {", "hrm/class/skill.class.php:1094|read|$modele = getDolGlobalString(''SKILL_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SMTPS_CAPTURE_PEER_CERT', 'string', NULL, 'core', 'Enables capturing the SMTP server''s TLS peer certificate details when sending mail via SMTPS.', 'In core/class/CMailFile.class.php:643-649, if getDolGlobalString(''SMTPS_CAPTURE_PEER_CERT'') is set, the SSL stream context options are merged with capture_peer_cert=true and capture_peer_cert_chain=true; commented-out example code shows retrieving cert subject/issuer/validity via stream_context_get_params().', 'Enabling it makes Dolibarr capture the SMTP server''s TLS certificate into the PHP stream context for inspection/debugging (e.g. subject, issuer, validity dates), which is otherwise not captured.', 'Boolean-like: set/non-empty adds ssl capture_peer_cert + capture_peer_cert_chain options to the SMTPS connection; unset (default) does not capture.', 1, 0, NULL, 1, '2e3ef015ff9ceeaf4563495878f5a20944db6796a0588141f429f7278ea25c30', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/CMailFile.class.php:643: if (getDolGlobalString(''SMTPS_CAPTURE_PEER_CERT'')) {", "core/class/CMailFile.class.php:644: $options = array_merge($options, array(''ssl'' => array(''capture_peer_cert'' => true, ''capture_peer_cert_chain'' => true)));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SMTPS_FORCE_IP_V4', 'string', NULL, 'core', 'Forces the SMTPS socket connection to bind using IPv4 instead of allowing IPv6.', 'In core/class/CMailFile.class.php:653-655, if getDolGlobalString(''SMTPS_FORCE_IP_V4'') is set, the stream socket options add `''socket'' => [''bindto'' => ''0.0.0.0:0'']`, with inline comment ''Forces IPv4 (IPv6 would be \''::0\'')''.', 'Enabling it forces outgoing SMTPS connections to bind to an IPv4 address, useful on hosts where IPv6 SMTP connectivity is broken or undesired.', 'Boolean-like: set/non-empty binds socket to ''0.0.0.0:0'' (IPv4); unset (default) uses default socket binding (may use IPv6).', 1, 0, NULL, 1, '22bff56b2da29b0cf0c1d60900cfead96b5861c6393b973d73d002acc7fb1c57', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/CMailFile.class.php:653: if (getDolGlobalString(''SMTPS_FORCE_IP_V4'')) {", "core/class/CMailFile.class.php:654: $options = array_merge($options, array(''socket'' => [''bindto'' => ''0.0.0.0:0''])); // Forces IPv4 (IPv6 would be ''::0'')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SN_ADVANCED_MASK', 'string', NULL, 'product', 'Defines the serial-number format mask used by the advanced serial-number module when generating serial numbers for products.', 'Read in core/modules/product_batch/mod_sn_advanced.php at lines 71 and 152 as the primary mask for serial-number generation. Also read in product/card.php at lines 1563, 2177, and 2180 as a fallback when the product-level batch_mask is not set.', 'Changing this value alters how new serial numbers are formatted; existing serial numbers are not renamed. Removing the value causes the module to fall back to the product-level mask if available.', 'No COMMENTS in payload; value is a format mask string. Exact token syntax is not documented in the payload.', 1, 0, NULL, 1, '423532cd065939b9ed3dae250bd672777e880f2e756f3825ffca1ec3d9aad7ca', 'v2', '2026-04-21T13:29:58+00:00', '["product/card.php:2177|check|$mask = !empty($object->batch_mask) ? $object->batch_mask : getDolGlobalString(''SN_ADVANCED_MASK'');", "core/modules/product_batch/mod_sn_advanced.php:71|read|$mask = getDolGlobalString(''SN_ADVANCED_MASK'');", "core/modules/product_batch/mod_sn_advanced.php:152|read|$mask = getDolGlobalString(''SN_ADVANCED_MASK'');", "product/card.php:1563|read|$inherited_mask_sn = getDolGlobalString(''SN_ADVANCED_MASK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIAL_NETWORKS_DATA_', 'string', NULL, 'admin', 'Stores JSON configuration data for a specific social network integration, keyed by network name suffix.', 'This is a dynamic constant: the actual key is ''SOCIAL_NETWORKS_DATA_'' + socialNetworkName. Set and deleted via admin/fediverse.php (dolibarr_set_const at lines 131, 228, 256; dolibarr_del_const at line 176). Read at lines 196, 249, 473 to retrieve network-specific JSON data.', 'Setting or clearing this key adds, updates, or removes the stored configuration for the named social network integration.', 'JSON string containing social network configuration data; empty/deleted = no configuration for that network.', 0, 0, 'admin/fediverse.php|admin/fediverse.php|admin/fediverse.php|admin/fediverse.php|admin/fediverse.php|admin/fediverse.php|admin/fediverse.php', 1, '5e3a0c0a769538a1d8682f14c09ba10303ce9733a86b9caf8f518351866e59db', 'v2', '2026-04-21T13:50:40+00:00', '["admin/fediverse.php:131|write|$result = dolibarr_set_const($db, \"SOCIAL_NETWORKS_DATA_\".$socialNetworkName, $jsonData, ''chaine'', 0, '''', $conf->entity);", "admin/fediverse.php:176|write|$result = dolibarr_del_const($db, \"SOCIAL_NETWORKS_DATA_\".$name, $conf->entity);", "admin/fediverse.php:196|read|$result = getDolGlobalString(\"SOCIAL_NETWORKS_DATA_\".$name);", "admin/fediverse.php:473|read|$jsonData = getDolGlobalString(\"SOCIAL_NETWORKS_DATA_\".$obj->note);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ACCOUNTANCY_CODE_CUSTOMER_INVOICE_MANDATORY', 'string', NULL, 'compta', 'Blocks customer invoice validation when the third party does not have a customer accountancy code defined.', 'Set via societe/admin/societe.php:181 as a yesno type and checked in compta/facture/class/facture.class.php:3619 to raise a validation error when the third party''s code_compta_client is empty. Admin UI at societe/admin/societe.php.', 'Enabling this prevents customer invoices from being validated when the associated third party has no customer accountancy code configured.', '0/no = accountancy code not required; 1/yes = customer accountancy code is mandatory for invoice validation.', 0, 0, 'societe/admin/societe.php', 1, '2bb94896846b44c49ea42d74f3069184cebfb771559d94e1028fe8a1956231d5', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:181|write|$res = dolibarr_set_const($db, \"SOCIETE_ACCOUNTANCY_CODE_CUSTOMER_INVOICE_MANDATORY\", $setaccountancycodecustomerinvoicemandatory, ''yesno'', 0, '''', $conf->entity);", "compta/facture/class/facture.class.php:3619|check|if (getDolGlobalString(''SOCIETE_ACCOUNTANCY_CODE_CUSTOMER_INVOICE_MANDATORY'') && empty($this->thirdparty->code_compta_client)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ACCOUNTANCY_CODE_CUSTOMER_MANDATORY', 'string', NULL, 'societe', 'Makes the customer accountancy code mandatory for thirdparties marked as customer when set.', 'Checked in societe/class/societe.class.php:1403; if set and the accountancy code value is empty/unset, error ''ErrorFieldRequired'' for CustomerAccountancyCodeShort is raised.', 'Enabling it blocks saving a customer thirdparty that has no accountancy code filled in.', 'Boolean-like: truthy makes the customer accountancy code field mandatory.', 1, 0, NULL, 1, '7a66fa5372acd1ab3e97595684568b71c81bb45e3dc5168632eb92479d9f0de7', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:1403|check|if (getDolGlobalString(''SOCIETE_ACCOUNTANCY_CODE_CUSTOMER_MANDATORY'') && (!isset($vallabel) || trim($vallabel) === '''')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ACCOUNTANCY_CODE_CUSTOMER_UNIQUE', 'string', NULL, 'societe', 'Enforces uniqueness of the customer accountancy code across thirdparties marked as customer when set.', 'Checked in societe/class/societe.class.php:1394, guarded by !empty($this->client); if set and the code is not empty, id_prof_exists() checks for a duplicate customer accountancy code.', 'Enabling it blocks saving a customer thirdparty whose accountancy code already exists on another customer record.', 'Boolean-like: truthy enables the uniqueness check for customer thirdparties only.', 1, 0, NULL, 1, '117ab7fed20036b6aec5dd01e42a7814de67eb574d9a43b38e52d39e641ace1d', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:1394|check|if ($vallabel && getDolGlobalString(''SOCIETE_ACCOUNTANCY_CODE_CUSTOMER_UNIQUE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ACCOUNTANCY_CODE_SUPPLIER_INVOICE_MANDATORY', 'string', NULL, 'fourn', 'Requires the supplier thirdparty to have an accountancy code before a supplier invoice can be validated.', 'Checked in fourn/class/fournisseur.facture.class.php:1885, guarding a validation error raised when $this->thirdparty->code_compta_fournisseur is empty.', 'Enabling it blocks supplier invoice validation whenever the linked supplier thirdparty has no accountancy code set.', 'Boolean: 0/unset = accountancy code not required; 1 = supplier accountancy code is mandatory to validate the invoice.', 0, 0, NULL, 1, '861420d81820d1f8b54cfdaebeb6741c0627b3f8c2fe6804653032155f0ffc30', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/class/fournisseur.facture.class.php:1885: if (getDolGlobalString(''SOCIETE_ACCOUNTANCY_CODE_SUPPLIER_INVOICE_MANDATORY'') && empty($this->thirdparty->code_compta_fournisseur)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ACCOUNTANCY_CODE_SUPPLIER_MANDATORY', 'string', NULL, 'societe', 'Makes the supplier accountancy code mandatory for thirdparties marked as supplier when set.', 'Checked in societe/class/societe.class.php:1419; if set and the accountancy code value is empty/unset, error ''ErrorFieldRequired'' for SupplierAccountancyCodeShort is raised.', 'Enabling it blocks saving a supplier thirdparty that has no accountancy code filled in.', 'Boolean-like: truthy makes the supplier accountancy code field mandatory.', 1, 0, NULL, 1, '9d3e967235e66a7aa57e85a459042af2c3cb252d41ded767f636af2013e0b911', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:1419|check|if (getDolGlobalString(''SOCIETE_ACCOUNTANCY_CODE_SUPPLIER_MANDATORY'') && (!isset($vallabel) || trim($vallabel) === '''')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ACCOUNTANCY_CODE_SUPPLIER_UNIQUE', 'string', NULL, 'societe', 'Enforces uniqueness of the supplier accountancy code across thirdparties marked as supplier when set.', 'Checked in societe/class/societe.class.php:1410, guarded by !empty($this->fournisseur); if set and the code is not empty, id_prof_exists() checks for a duplicate supplier accountancy code.', 'Enabling it blocks saving a supplier thirdparty whose accountancy code already exists on another supplier record.', 'Boolean-like: truthy enables the uniqueness check for supplier thirdparties only.', 1, 0, NULL, 1, '21c6e2b540be729a9fd9ab94ff4de291840e1cdc573b50834ec40e566829572b', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:1410|check|if ($vallabel && getDolGlobalString(''SOCIETE_ACCOUNTANCY_CODE_SUPPLIER_UNIQUE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ADDRESSES_MANAGEMENT', 'string', NULL, 'contact', 'Switches the contact/address module terminology and behavior between a contacts-only mode and a combined contacts-and-addresses mode.', 'Read in 19 locations including core/menus/standard/eldy.lib.php:1360, fourn/contact.php:118, contact/messaging.php:222, and contact/canvas/default/actions_contactcard_default.class.php:64, :67, :70. When set, UI labels use ''Contacts''/''Contact''/''EditContact''/''NewContact''; when unset, labels use ''ContactsAddresses''/''ContactAddress''/''EditContactAddress''/''NewContactAddress''.', 'Enabling this constant changes menu labels, page titles, and UI strings throughout the contacts subsystem from address-oriented to contact-oriented terminology.', 'Truthy (non-empty / 1) = contacts-only mode (labels: ''Contacts'', ''Contact''); falsy (empty / 0) = contacts-and-addresses mode (labels: ''ContactsAddresses'', ''ContactAddress'').', 1, 0, NULL, 1, '763ad91687ddeac824d559e30f44a5cbe48443d02b282a9255cc433fd17941ab', 'v2', '2026-04-21T11:16:15+00:00', '["core/menus/standard/eldy.lib.php:1360|read|$newmenu->add(\"/societe/index.php?leftmenu=thirdparties\", (getDolGlobalString(''SOCIETE_ADDRESSES_MANAGEMENT'') ? $langs->trans(\"Contacts\") : $langs->trans(\"ContactsAddresses\"))", "fourn/contact.php:118|read|$title = (getDolGlobalString(''SOCIETE_ADDRESSES_MANAGEMENT'') ? $langs->trans(\"ListOfContacts\") : $langs->trans(\"ListOfContactsAddresses\"));", "contact/messaging.php:222|read|$title = (getDolGlobalString(''SOCIETE_ADDRESSES_MANAGEMENT'') ? $langs->trans(\"Contacts\") : $langs->trans(\"ContactsAddresses\"));", "contact/canvas/default/actions_contactcard_default.class.php:64|read|$out .= (getDolGlobalString(''SOCIETE_ADDRESSES_MANAGEMENT'') ? $langs->trans(\"Contact\") : $langs->trans(\"ContactAddress\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ADD_REF_IN_LIST', 'string', NULL, 'societe', 'Controls whether and which customer/supplier reference codes are appended to the company name in selection lists.', 'Written via societe/admin/societe.php (line 195). Checked in societe/class/societe.class.php (lines 3274, 3276, 3280, 3285) with specific integer comparisons. COMMENT: `// Search in ''code_client'' when SOCIETE_ADD_REF_IN_LIST is set to 1` (comm/propal/list.php:684).', 'Setting this value to 1 shows both customer and supplier codes; 2 shows only customer code; 3 shows only supplier code; 0 shows no codes.', '0 = no reference codes shown; 1 = show both customer and supplier codes; 2 = show customer code only; 3 = show supplier code only.', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, '070856ed38d9034c91f4082396cf14c77805756cabd637203590268dda833e77', 'v2', '2026-04-21T11:16:15+00:00', '["comm/propal/list.php:684  // Search in ''code_client'' when SOCIETE_ADD_REF_IN_LIST is set to 1", "societe/class/societe.class.php:3276|check|if (($this->client) && (!empty($this->code_client)) && (getDolGlobalInt(''SOCIETE_ADD_REF_IN_LIST'') == 1 || getDolGlobalInt(''SOCIETE_ADD_REF_IN_LIST'') == 2)) {", "societe/class/societe.class.php:3280|check|if (($this->fournisseur) && (!empty($this->code_fournisseur)) && (getDolGlobalInt(''SOCIETE_ADD_REF_IN_LIST'') == 1 || getDolGlobalInt(''SOCIETE_ADD_REF_IN_LIST'') == 3)) {", "societe/admin/societe.php:195|write|$res = dolibarr_set_const($db, \"SOCIETE_ADD_REF_IN_LIST\", $setaddrefinlist, ''yesno'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ALLOW_SEARCH_ON_ROWID', 'bool', NULL, 'societe', 'Allows the third-party (company) autocomplete search to also match by the internal database row ID, in addition to name/code fields.', 'Checked in societe/ajax/ajaxcompanies.php:127, appended to a WHERE clause already matching on s.nom, s.name_alias, s.code_client, s.code_fournisseur; when true, an additional ''s.rowid = <search>'' OR-condition is added.', 'Enabling it lets users find a third party by typing its numeric database ID in the company search/autocomplete box, in addition to normal name/code search.', 'Boolean-like: any truthy value adds a rowid match to the company search query.', 1, 0, NULL, 1, '9c22bc3168954bc1cb9e6476dd1ac6fe4d515b09b00f368e90cc8265cace8abb', 'v2', '2026-07-24T07:05:23+00:00', '["societe/ajax/ajaxcompanies.php:127: if (getDolGlobalString(''SOCIETE_ALLOW_SEARCH_ON_ROWID'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ASK_FOR_SHIPPING_METHOD', 'string', NULL, 'comm', 'Enables the shipping method field on third-party records and propagates it to proposals and PDF documents.', 'When enabled, a shipping method field is displayed on third-party (societe) cards and is carried over to commercial proposals. Configured via societe/admin/societe.php. PDF modules (pdf_cyan, pdf_azur) also render the shipping method when this constant is set.', 'Enabling this allows capturing a preferred shipping method per third party, which then appears on proposals and generated PDF documents. Disabling hides the field entirely.', 'Truthy = shipping method field enabled; empty/falsy = disabled', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, '4e4d14fe6da2d14a6e78e2fbdacb18ee9f7984513acf8ff52ceb56534fcca413', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:251|write|$res = dolibarr_set_const($db, \"SOCIETE_ASK_FOR_SHIPPING_METHOD\", $setaskforshippingmet, ''yesno'', 0, '''', $conf->entity);", "comm/propal/card.php:2487|check|if (getDolGlobalString(''SOCIETE_ASK_FOR_SHIPPING_METHOD'') && !empty($soc->shipping_method_id)) {", "core/modules/propale/doc/pdf_cyan.modules.php:1139|check|if (getDolGlobalString(''SOCIETE_ASK_FOR_SHIPPING_METHOD'') && !empty($this->emetteur->shipping_method_id)) {", "comm/card.php:629|check|if (getDolGlobalString(''SOCIETE_ASK_FOR_SHIPPING_METHOD'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ASK_FOR_WAREHOUSE', 'string', NULL, 'societe', 'When enabled, displays a warehouse selection field on third-party and sales order cards.', 'Configured via admin/stock.php:823 using a select array. Checked in societe/card.php:3263 and comm/card.php:608 when the stock module is active. Three occurrences across three files.', 'Enabling this constant adds a warehouse selector to the third-party and commercial card interfaces when the stock module is enabled.', 'String value from a predefined array; unset or empty = warehouse not shown.', 0, 0, 'admin/stock.php', 1, 'a7da542d52928a45e487b5ae93b86d7b28c4eb5366fab2b447c0c6b14987edcc', 'v2', '2026-04-21T11:16:15+00:00', '["admin/stock.php:823|read|print $form->selectarray(\"SOCIETE_ASK_FOR_WAREHOUSE\", $arrval, getDolGlobalString(''SOCIETE_ASK_FOR_WAREHOUSE''));", "societe/card.php:3263|check|if (isModEnabled(''stock'') && getDolGlobalString(''SOCIETE_ASK_FOR_WAREHOUSE'')) {", "comm/card.php:608|check|if (isModEnabled(''stock'') && getDolGlobalString(''SOCIETE_ASK_FOR_WAREHOUSE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_CODECLIENT_ADDON', 'string', NULL, 'societe', 'Specifies the name of the add-on module used to generate customer codes for third parties.', 'Set via the societe admin UI (societe/admin/societe.php line 69 write, line 419 check). The value selects which code-generation module file is active. Checked extensively in societe/class/societe.class.php (lines 3813, 3847, 3878, 3919, 3966, 4008) to decide whether to invoke the add-on.', 'Changing this constant switches the customer code generation algorithm; all subsequent customer code assignments will use the newly selected add-on.', 'Name of a valid customer code add-on module (e.g. ''mod_codeclient_leopard'')', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, 'c1e1d082577dbe1f14cd0f0b6859ffd800b026b1ada06c928376c16b88aad3da', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:69|write|$result = dolibarr_set_const($db, \"SOCIETE_CODECLIENT_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "societe/admin/societe.php:419|check|if (getDolGlobalString(''SOCIETE_CODECLIENT_ADDON'') == (string) $file) {", "societe/class/societe.class.php:3813|check|if (getDolGlobalString(''SOCIETE_CODECLIENT_ADDON'')) {", "societe/class/societe.class.php:3847|check|if (getDolGlobalString(''SOCIETE_CODECLIENT_ADDON'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_CODECOMPTA_ADDON', 'string', NULL, 'societe', 'Specifies the name of the add-on module used to generate accounting codes for third parties.', 'Set via the societe admin UI (societe/admin/societe.php line 76 write, line 501 check). Read in societe/class/societe.class.php at line 4049 to load the accounting code module.', 'Changing this constant switches the accounting code generation module used when creating or updating third parties.', 'Name of a valid accounting code add-on module', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, '140d0b8f2a8b9b53ce550c8e747e89377ed71f9592a2204c2be543f11684519d', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:76|write|$result = dolibarr_set_const($db, \"SOCIETE_CODECOMPTA_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "societe/admin/societe.php:501|check|if (getDolGlobalString(''SOCIETE_CODECOMPTA_ADDON'') == \"$file\") {", "societe/class/societe.class.php:4048|check|if (getDolGlobalString(''SOCIETE_CODECOMPTA_ADDON'')) {", "societe/class/societe.class.php:4049|read|$module = getDolGlobalString(''SOCIETE_CODECOMPTA_ADDON'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_BANKACCOUNT', 'bool', NULL, 'societe', 'Disables the bank account (RIB) tab and related functionality for third-party records.', 'Configured via admin/bank.php (admin/bank.php:540). Checked in 6 occurrences: admin/bank.php, societe/paymentmodes.php (three times), and core/lib/company.lib.php:214. Gates both the display of bank account sections and online signing functionality.', 'When enabled, the bank account section is hidden from company/contact records and online signing options for RIB are also suppressed.', '0 or unset = bank account section enabled; non-zero = bank account section disabled', 0, 0, 'admin/bank.php', 1, '0fa427f30cd0ed2639ecac266aef47cf22f86c3f6b8eb41b7be3b7f74952daca', 'v2', '2026-04-21T11:16:15+00:00', '["admin/bank.php:540|check|if (!getDolGlobalInt(''SOCIETE_DISABLE_BANKACCOUNT'')) {", "core/lib/company.lib.php:214|check|if (!getDolGlobalInt(''SOCIETE_DISABLE_BANKACCOUNT'')) {", "societe/paymentmodes.php:1758|check|if (!getDolGlobalInt(''SOCIETE_DISABLE_BANKACCOUNT'') && getDolGlobalInt(\"SOCIETE_RIB_ALLOW_ONLINESIGN\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_BUILDDOC', 'bool', NULL, 'societe', 'Hides the ''generated documents'' block (document builder/list) on the thirdparty payment modes and card pages.', 'Guards the documents section in societe/paymentmodes.php:1935 and societe/card.php:3594 with `if (!getDolGlobalString(''SOCIETE_DISABLE_BUILDDOC''))`; a related commented-out check also exists in hrm/position_card.php:356.', 'When set (truthy), the generated-documents/showdocuments block is not displayed on the thirdparty card and payment modes tab.', 'Boolean: truthy disables/hides the document generation block; empty/unset (default) shows it.', 1, 0, NULL, 1, '06d8076f8b9cbf0a2d0842f262b1816cf005c059aece556a63614a95a56c5529', 'v2', '2026-07-24T07:05:23+00:00', '["societe/paymentmodes.php:1935|check|if (!getDolGlobalString(''SOCIETE_DISABLE_BUILDDOC'')) {", "societe/card.php:3594|check|if (!getDolGlobalString(''SOCIETE_DISABLE_BUILDDOC'')) {", "hrm/position_card.php:356  //\tif (empty($conf->global->SOCIETE_DISABLE_BUILDDOC)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_CONTACTS', 'bool', NULL, 'contact', 'When enabled, hides and disables the contacts management feature on third-party cards.', 'Checked across societe/card.php, societe/contact.php, contact/card.php, contact/class/contact.class.php, and contact/perso.php in 19 occurrences to gate contact-related UI and logic. No admin UI write is present.', 'Enabling this constant removes contact tabs and contact-related actions from third-party views throughout the application.', 'Boolean flag; unset or 0 = contacts enabled; any truthy value = contacts disabled.', 1, 0, NULL, 1, '0f2c6fc5a0be57cd490744d8658808ea111f2e580425e647de97e9d869c4911d', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:3607|check|if (!getDolGlobalString(''SOCIETE_DISABLE_CONTACTS'')) {", "societe/contact.php:221|check|if (!getDolGlobalString(''SOCIETE_DISABLE_CONTACTS'')) {", "contact/class/contact.class.php:398|check|if (!getDolGlobalString(''SOCIETE_DISABLE_CONTACTS'')) {", "contact/card.php:695|check|if (!getDolGlobalString(''SOCIETE_DISABLE_CONTACTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_CUSTOMERS', 'bool', NULL, 'core', 'Disables the customer feature across Dolibarr, hiding customer-related menus, boxes, and statistics.', 'When set, customer menus and dashboard boxes are hidden and customer-related stats on the societe index are suppressed. Checked in core menus, boxes, and societe/class/societe.class.php at line 3427.', 'Enabling this constant removes customer menus and boxes from the interface and prevents customer-type logic from executing in societe.class.php.', '0 or empty = customers enabled; any truthy value = customers disabled', 1, 0, NULL, 1, '5a027db650d80b5476bb9c80473215a1db33fa116770af0c8b66188a57986de2', 'v2', '2026-04-21T11:16:15+00:00', '["core/menus/standard/eldy.lib.php:1318|check|if (isModEnabled(''societe'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS'')) {", "societe/class/societe.class.php:3427|check|if (($this->client == 1 || $this->client == 3) && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS'')) {", "core/boxes/box_clients.php:56|check|if (getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS'')) {", "societe/index.php:139|check|if (isModEnabled(''societe'') && $user->hasRight(''societe'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS_STATS'') && ("]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_CUSTOMERS_STATS', 'bool', NULL, 'societe', 'When enabled, suppresses the customers statistics section on the thirdparty dashboard and the global state board.', 'Checked in societe/index.php:139, :168, :194 and core/boxes/box_dolibarr_state_board.php:109 in conjunction with SOCIETE_DISABLE_CUSTOMERS to gate display of customer statistics. No admin UI write path is present in the payload.', 'Enabling this constant hides customer count and statistics from the thirdparty dashboard and the global state board box.', 'Truthy value to hide customers stats; unset or 0 to show.', 1, 0, NULL, 1, 'ccb5f1d450658038e540f95b72baa5f566de941e74a909a8347d2dbe6aa63939', 'v2', '2026-04-21T11:16:15+00:00', '["societe/index.php:139|check|if (isModEnabled(''societe'') && $user->hasRight(''societe'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS_STATS'') && (", "societe/index.php:168|check|if (isModEnabled(''societe'') && $user->hasRight(''societe'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS_STATS'')) {", "core/boxes/box_dolibarr_state_board.php:109|read|''customers'' => isModEnabled(''societe'') && $user->hasRight(''societe'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS'') && !getDolGlobalString(''SOCIETE_DISABLE_CUSTOMERS_S"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_DEFAULT_SALESREPRESENTATIVE', 'bool', NULL, 'core', 'Disables the default behavior of preselecting the current logged-in user as the sales representative in user-selection dropdowns.', 'core/class/html.form.class.php:2677, in select_dolusers(): `if ((is_numeric($selected) && ((int) $selected < -4 || empty($selected))) && !getDolGlobalString(''SOCIETE_DISABLE_DEFAULT_SALESREPRESENTATIVE'')) { $selected = $user->id; }` — when no explicit selection is provided, the current user is auto-selected unless this constant is set.', 'Setting it to a truthy value stops the current user from being auto-preselected as sales representative when no other selection value is passed to select_dolusers(); the dropdown then falls back to no preselection.', 'Truthy = disable auto-preselection of current user as sales rep; 0/unset = current user preselected by default when no value given.', 0, 0, NULL, 1, '4eaaefa6a77aa08c426d3bc30664f8f8422d6caf92239934bddfcb490e0cf901', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:2677: if ((is_numeric($selected) && ((int) $selected < -4 || empty($selected))) && !getDolGlobalString(''SOCIETE_DISABLE_DEFAULT_SALESREPRESENTATIVE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_PARENTCOMPANY', 'bool', NULL, 'societe', 'Disables the parent company feature on thirdparty (societe) records.', 'Checked (negated) with getDolGlobalString in societe/class/societe.class.php:5922 and societe/card.php (lines 2004, 2868, 3467, 3609).', 'When enabled, parent-company related fields/logic in the thirdparty card are hidden or skipped; line 3609 also shows it interacts with SOCIETE_DISABLE_SHOW_SUBSIDIARIES for subsidiary display.', NULL, 1, 0, NULL, 1, 'd9aefda6a8a06459bd310b6dc737fb0eb6612f1c62fb6844ef678e71a8a36ce7', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''SOCIETE_DISABLE_PARENTCOMPANY'')) {", "if (!getDolGlobalString(''SOCIETE_DISABLE_PARENTCOMPANY'') && !getDolGlobalString(''SOCIETE_DISABLE_SHOW_SUBSIDIARIES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_PROSPECTS', 'bool', NULL, 'core', 'Disables the prospect status and all prospect-related features across the application.', 'Checked in 30+ locations including admin/dict.php:569, core/menus/standard/eldy.lib.php:1310, :1336, :1339, core/boxes/box_prospect.php:58, contact/class/contact.class.php:404, and societe/class/societe.class.php:3420. Configured via admin/dict.php. When set, prospect menu items, dictionary entries, and prospect fields are hidden.', 'Enabling this constant removes prospect-related UI elements, menu entries, and dictionary conditions throughout the application; disabling re-enables the full prospect workflow.', 'Any non-empty value = prospects disabled; empty = prospects enabled', 0, 0, 'admin/dict.php|admin/dict.php', 1, '49dac4285030bf91c6d29e54a9ce75bb9c6973622450952ea55129d43776cc76', 'v2', '2026-04-21T11:16:15+00:00', '["admin/dict.php:569|read|$tabcond[DICT_PROSPECTLEVEL] = (isModEnabled(\"societe\") && !getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS''));", "core/menus/standard/eldy.lib.php:1310|check|if (isModEnabled(''societe'') && !getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS'')) {", "core/boxes/box_prospect.php:58|check|if (getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS'')) {", "contact/class/contact.class.php:404|check|if (getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS'') || !getDolGlobalString(''THIRDPARTY_ENABLE_PROSPECTION_ON_ALTERNATIVE_ADRESSES'')) {\t// Default behaviour"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_PROSPECTSCUSTOMERS', 'bool', NULL, 'societe', 'Disables the combined ''prospect/customer'' thirdparty type option, forcing separate prospect and customer classification.', 'Set via societe/admin/societe.php:265 dolibarr_set_const (yesno type), checked at societe/admin/societe.php:939/949, societe/class/societe.class.php:2577, societe/card.php:1504/1069, and combined with SOCIETE_DISABLE_PROSPECTS/SOCIETE_DISABLE_CUSTOMERS in core/modules/mailings/thirdparties.modules.php and core/class/html.formcompany.class.php.', 'When enabled, thirdparty client type 2 or 3 (prospect/customer combined) handling is skipped/disabled, e.g. in societe.class.php''s client-type check and mailing segmentation logic.', NULL, 0, 0, 'societe/admin/societe.php|societe/admin/societe.php|societe/admin/societe.php', 1, 'e2d0f93ab8f0c8d130d404cf8e92ce0e6edcf657eefe1b2c66a005462d0d2d7c', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, \"SOCIETE_DISABLE_PROSPECTSCUSTOMERS\", $setdisableprospectcustomer, ''yesno'', 0, '''', $conf->entity);", "if (($this->client == 2 || $this->client == 3) && !getDolGlobalInt(''SOCIETE_DISABLE_PROSPECTSCUSTOMERS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_PROSPECTS_STATS', 'bool', NULL, 'societe', 'When enabled, suppresses the prospects statistics section on the thirdparty dashboard and the global state board.', 'Checked in societe/index.php:135, :165, :189 and core/boxes/box_dolibarr_state_board.php:110 always in conjunction with SOCIETE_DISABLE_PROSPECTS to gate the display of prospect statistics. No admin UI write path is present in the payload.', 'Enabling this constant hides prospect count and statistics from the thirdparty dashboard and the global state board box.', 'Truthy value to hide prospects stats; unset or 0 to show.', 1, 0, NULL, 1, '5cb01f73f075cbee0df77bea1e11ccca89f211be790909a198298c7c21505682', 'v2', '2026-04-21T11:16:15+00:00', '["societe/index.php:135|check|if (isModEnabled(''societe'') && $user->hasRight(''societe'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS'') && !getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS_STATS'') && (", "societe/index.php:165|check|if (isModEnabled(''societe'') && $user->hasRight(''societe'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS'') && !getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS_STATS'')) {", "core/boxes/box_dolibarr_state_board.php:110|read|''prospects'' => isModEnabled(''societe'') && $user->hasRight(''societe'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS'') && !getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS_S"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_SHOW_SUBSIDIARIES', 'bool', NULL, 'societe', 'Hides the ''Subsidiaries'' list block on a third-party''s card, which is otherwise shown (unless subsidiaries are globally disabled via SOCIETE_DISABLE_PARENTCOMPANY).', 'Checked in societe/card.php:3609 alongside SOCIETE_DISABLE_PARENTCOMPANY: the subsidiaries list (via show_subsidiaries()) is printed only if both constants are NOT set.', 'When set, the subsidiaries list section is omitted from the third-party card display even if the parent-company feature itself remains enabled.', 'Not set/falsy (default): subsidiaries list shown (if SOCIETE_DISABLE_PARENTCOMPANY also unset). Truthy: subsidiaries list hidden.', 1, 0, NULL, 1, '9eabdb5ba0485affe4677b5f6bfb6b278133d9736139db6ef9a6f8a301846507', 'v2', '2026-07-24T07:05:23+00:00', '["societe/card.php:3609|check|if (!getDolGlobalString(''SOCIETE_DISABLE_PARENTCOMPANY'') && !getDolGlobalString(''SOCIETE_DISABLE_SHOW_SUBSIDIARIES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_STATE', 'bool', NULL, 'public', 'Disables the state/province field for third-party (company/contact) records.', 'Checked in 15 occurrences across societe/card.php, contact/card.php, resource/card.php, and public project pages. Each check gates the rendering or processing of the state field.', 'When enabled, the state/province field is hidden and not processed for companies, contacts, resources, and public-facing forms.', '0 or unset = state field enabled; non-empty = state field disabled', 1, 0, NULL, 1, '9c48cf9adf6e2b7ffcc3ef1f1c2c4f1c0a4921c9ef94829e2ca14ffc98110af6', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:1653|check|if (!getDolGlobalString(''SOCIETE_DISABLE_STATE'')) {", "contact/card.php:770|check|if (!getDolGlobalString(''SOCIETE_DISABLE_STATE'')) {", "resource/card.php:331|check|if (!getDolGlobalString(''SOCIETE_DISABLE_STATE'') && $countryid > 0) {", "public/project/new.php:526|check|if (!getDolGlobalString(''SOCIETE_DISABLE_STATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_SUPPLIERS_INVOICES_STATS', 'bool', NULL, 'core', 'Hides the supplier-invoices statistics entry from the Dolibarr state/statistics board (home dashboard).', 'Checked in core/boxes/box_dolibarr_state_board.php:127, ANDed with isModEnabled(''supplier_invoice'') and the user''s read permission, to decide whether the ''supplier_invoices'' stat block is included on the board.', 'When set/true, the supplier invoices count/stat block is removed from the state board dashboard regardless of module activation or permissions.', 'Boolean-like: truthy disables the supplier-invoices stats block.', 1, 0, NULL, 1, 'bf411b90abdd2c0f3e20d7375e08ee52753170216fdcbdeeb8d25a497bad8ab1', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_dolibarr_state_board.php:127: ''supplier_invoices'' => isModEnabled(''supplier_invoice'') && $user->hasRight(''fournisseur'', ''facture'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_SUPPLIERS_INVOICES_STATS''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_SUPPLIERS_ORDERS_STATS', 'bool', NULL, 'core', 'Hides the supplier-orders statistics entry from the Dolibarr state/statistics board (home dashboard).', 'Checked in core/boxes/box_dolibarr_state_board.php:126, ANDed with isModEnabled(''supplier_order'') and the user''s read permission, to decide whether the ''supplier_orders'' stat block is included on the board.', 'When set/true, the supplier orders count/stat block is removed from the state board dashboard regardless of module activation or permissions.', 'Boolean-like: truthy disables the supplier-orders stats block.', 1, 0, NULL, 1, 'f3904e6db9c280ba5e0cc489545303297672da6a3d9f9c4926784fa042d19ef2', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_dolibarr_state_board.php:126: ''supplier_orders'' => isModEnabled(''supplier_order'') && $user->hasRight(''fournisseur'', ''commande'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_SUPPLIERS_ORDERS_STATS''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_SUPPLIERS_PROPOSAL_STATS', 'bool', NULL, 'core', 'Hides the supplier-proposals (price requests) statistics entry from the Dolibarr state/statistics board (home dashboard).', 'Checked in core/boxes/box_dolibarr_state_board.php:128, ANDed with isModEnabled(''supplier_proposal'') and the user''s read permission, to decide whether the ''supplier_proposals'' stat block is included on the board.', 'When set/true, the supplier proposals count/stat block is removed from the state board dashboard regardless of module activation or permissions.', 'Boolean-like: truthy disables the supplier-proposals stats block.', 1, 0, NULL, 1, 'cc8c046e4cd4ba013bbbfb18411428bcad639e9286d3c6a98de7ed317c8b0e45', 'v2', '2026-07-24T07:05:23+00:00', '["core/boxes/box_dolibarr_state_board.php:128: ''supplier_proposals'' => isModEnabled(''supplier_proposal'') && $user->hasRight(''supplier_proposal'', ''lire'') && !getDolGlobalString(''SOCIETE_DISABLE_SUPPLIERS_PROPOSAL_STATS''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_SUPPLIERS_STATS', 'bool', NULL, 'societe', 'When enabled, suppresses the suppliers statistics section on the thirdparty dashboard and the global state board.', 'Checked in societe/index.php:143, :171, :200 and core/boxes/box_dolibarr_state_board.php:116 in conjunction with supplier module checks to gate display of supplier statistics. No admin UI write path is present in the payload.', 'Enabling this constant hides supplier count and statistics from the thirdparty dashboard and global state board box.', 'Truthy value to hide suppliers stats; unset or 0 to show.', 1, 0, NULL, 1, 'f31200386ba992c58e04075509559d3c80ac7e68c00c76cf4a52c35bd9359f71', 'v2', '2026-04-21T11:16:15+00:00', '["societe/index.php:143|check|if (((isModEnabled(''fournisseur'') && $user->hasRight(''fournisseur'', ''lire'') && !getDolGlobalString(''MAIN_USE_NEW_SUPPLIERMOD'')) || (isModEnabled(''supplier_order'') && $user->hasRigh", "societe/index.php:171|check|if (((isModEnabled(''fournisseur'') && $user->hasRight(''fournisseur'', ''lire'') && !getDolGlobalString(''MAIN_USE_NEW_SUPPLIERMOD'')) || (isModEnabled(''supplier_order'') && $user->hasRigh", "core/boxes/box_dolibarr_state_board.php:116|read|&& !getDolGlobalString(''SOCIETE_DISABLE_SUPPLIERS_STATS''),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_DISABLE_WORKFORCE', 'bool', NULL, 'societe', 'When enabled, hides the workforce (number of employees) field on third-party cards.', 'Checked in societe/card.php:3324 and :1894, :2773 to conditionally render the workforce field alongside the third-party type field. Five occurrences in one file. No admin UI write is present.', 'Enabling this constant removes the workforce input field from third-party creation and edit forms.', 'Boolean flag; unset or 0 = workforce field shown; any truthy value = workforce field hidden.', 1, 0, NULL, 1, 'fb9c6baa3882a9c7a0c5d01b9018dcde8898e92deb974edce4a38ecc48864f38', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:3324|check|if (!getDolGlobalString(''SOCIETE_DISABLE_WORKFORCE'')) {", "societe/card.php:1894|check|if (!getDolGlobalString(''SOCIETE_DISABLE_WORKFORCE'')) {", "societe/card.php:2773|check|if (!getDolGlobalString(''SOCIETE_DISABLE_WORKFORCE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_EMAIL_INVOICE_MANDATORY', 'string', NULL, 'fourn', 'Requires the thirdparty to have a valid email address before an invoice can be validated.', 'Checked in fourn/class/fournisseur.facture.class.php:1877 and compta/facture/class/facture.class.php:3645, both guarding a validation error raised when isValidEmail($this->thirdparty->email) fails.', 'Enabling it blocks invoice validation (both customer and supplier invoices) whenever the linked thirdparty has no valid email address on file.', 'Boolean: 0/unset = email not required to validate an invoice; 1 = a valid thirdparty email is mandatory to validate.', 0, 0, NULL, 1, '839c4e8176a6c62ccf3be32ef83d9cc10df0961ec8a6c68f3f6319fc839aae6a', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/class/fournisseur.facture.class.php:1877: if (getDolGlobalString(''SOCIETE_EMAIL_INVOICE_MANDATORY'') && !isValidEmail($this->thirdparty->email)) {", "compta/facture/class/facture.class.php:3645: if (getDolGlobalString(''SOCIETE_EMAIL_INVOICE_MANDATORY'') && !isValidEmail($this->thirdparty->email)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_EMAIL_MANDATORY', 'string', NULL, 'societe', 'Makes the email field mandatory when creating or editing a third party (company or contact).', 'Checked in societe/class/societe.class.php:1373 during validation and used in societe/card.php:1691 and :2562, contact/card.php:1098, public/company/new.php:405, and societe/class/api_thirdparties.class.php:67 (11 occurrences across multiple files). No admin UI write found; HIDDEN_GUESS is 1.', 'When enabled, saving a third party or contact without a valid email address raises a validation error; the email field is marked as required in forms.', 'Any non-empty value = email mandatory; empty = optional', 1, 0, NULL, 1, 'f5a81ab1d0c7065c974f5637c5911856ad80ddc0684be867c894301411d0eb8b', 'v2', '2026-04-21T11:16:15+00:00', '["societe/class/societe.class.php:1373|check|if (getDolGlobalString(''SOCIETE_EMAIL_MANDATORY'') && !isValidEmail($this->email)) {", "societe/card.php:1691|read|print ''<tr><td>''.$form->editfieldkey(''EMail'', ''email'', '''', $object, 0, ''string'', '''', getDolGlobalInt(''SOCIETE_EMAIL_MANDATORY'')).''</td>'';", "societe/class/api_thirdparties.class.php:67|check|if (getDolGlobalString(''SOCIETE_EMAIL_MANDATORY'')) {", "societe/canvas/company/tpl/card_create.tpl.php:153|read|<td><?php echo $langs->trans(''EMail'').($conf->global->SOCIETE_EMAIL_MANDATORY ? ''*'' : ''''); ?></td>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_EMAIL_UNIQUE', 'string', NULL, 'societe', 'Enforces uniqueness of the thirdparty email address across all thirdparties when set.', 'Checked in societe/class/societe.class.php:1355 inside the verify()-style professional-id/email validation block; if set and the email is not empty, id_prof_exists() is called to check for duplicates and raises an error if found.', 'Enabling it blocks creation/update of a thirdparty whose email already exists on another thirdparty record.', 'Boolean-like: truthy enables the uniqueness check.', 1, 0, NULL, 1, '48c7757b5fcdf050500cc904baef2b06578bc1dc2a8403403fca46a0c336a33c', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:1355|check|if (!$error && $vallabel && getDolGlobalString(''SOCIETE_EMAIL_UNIQUE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ENABLE_PUBLIC', 'bool', NULL, 'societe', 'Enables the public-facing company self-registration interface.', 'Written in societe/admin/public_interface.php (lines 62, 64, 71) to toggle the feature, and checked at :115, :138, and public/company/new.php:89 to gate access to the public form.', 'Enabling this opens a public URL where external users can register a company; disabling it blocks access to that URL.', '0 = public interface disabled; 1 = public interface enabled', 0, 0, 'societe/admin/public_interface.php|societe/admin/public_interface.php|societe/admin/public_interface.php|societe/admin/public_interface.php|societe/admin/public_interface.php|societe/admin/public_interface.php', 1, '060a176bba58818150b4ecdaf1427d9f2e0ae546bfd93f6d2236aa42eb5856b5', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/public_interface.php:62|write|dolibarr_set_const($db, ''SOCIETE_ENABLE_PUBLIC'', 1, ''chaine'', 0, '''', $conf->entity);", "societe/admin/public_interface.php:64|write|dolibarr_set_const($db, ''SOCIETE_ENABLE_PUBLIC'', 0, ''chaine'', 0, '''', $conf->entity);", "public/company/new.php:89|check|if (!getDolGlobalString(''SOCIETE_ENABLE_PUBLIC'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_EUID_MANDATORY', 'string', NULL, 'societe', 'Makes the thirdparty EUID (European Unique Identifier) field mandatory when set.', 'Checked in societe/class/societe.class.php:1387; if set and the EUID value is empty/unset, an error ''ErrorProdIdIsMandatory'' is raised.', 'Enabling it blocks saving a thirdparty that has no EUID value filled in.', 'Boolean-like: truthy makes the EUID field mandatory.', 1, 0, NULL, 1, '0e3e0645701e3cb78f7f0fe87160de85e7539e28f9683e88c78e327b5cb6ae01', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:1387|check|if (getDolGlobalString(''SOCIETE_EUID_MANDATORY'') && (!isset($vallabel) || trim($vallabel) === '''')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_EUID_UNIQUE', 'string', NULL, 'societe', 'Enforces uniqueness of the thirdparty EUID (European Unique Identifier) across thirdparties when set.', 'Checked in societe/class/societe.class.php:1378; if set and the EUID value is not empty, id_prof_exists() checks for a duplicate on another thirdparty and raises an error if found.', 'Enabling it blocks saving a thirdparty whose EUID already exists on another record.', 'Boolean-like: truthy enables the uniqueness check.', 1, 0, NULL, 1, 'd351e5834a7b4536a452d86fb391b1a152006e1af16786ac7689e4dc09b71b73', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:1378|check|if ($vallabel && getDolGlobalString(''SOCIETE_EUID_UNIQUE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_EXPORT_SUBORDINATES_CHILDS', 'string', NULL, 'core', 'When a user without full ''view all thirdparties'' rights runs a Societe/contact export, this includes thirdparties/contacts assigned to that user''s subordinates as well as the user themself.', 'Checked in core/modules/modSociete.class.php at lines 355, 445 and 528, in export SQL builders: when the user lacks $user->hasRight(''societe'',''client'',''voir''), the WHERE clause is restricted to sc.fk_user = user id, and this constant additionally OR''s in sc.fk_user IN (subordinates ids) via $user->getAllChildIds().', 'Enabling it widens Societe/contact exports for restricted users to also include records owned by their hierarchical subordinates, not just their own.', 'Boolean: true/1 includes subordinates'' thirdparties/contacts in the restricted export scope.', 0, 0, NULL, 1, '91f2fdb8fddc7d60375f8343f6265bc8a15c8cd5890dc9a4aa832e20615fc927', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/modSociete.class.php:355|check|if (getDolGlobalString(''SOCIETE_EXPORT_SUBORDINATES_CHILDS'')) {", "core/modules/modSociete.class.php: $subordinatesids = $user->getAllChildIds();"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_FISCAL_MONTH_START', 'string', NULL, 'accountancy', 'Defines the starting month of the company''s fiscal year (1=January … 12=December).', 'Configured via admin/company.php:747 (month selector) and saved at admin/company.php:242. Read extensively across accounting and result pages including accountancy/tpl/export_journal.tpl.php:72, compta/resultat/result.php:98, and accountancy/expensereport/index.php:286 with a fallback default of 1.', 'Changing this month shifts the fiscal-year boundaries used in all financial result reports, journal exports, VAT, and expense-report period calculations.', 'Integer 1–12 representing the first month of the fiscal year (default 1 = January); example from comments: 7 = July start', 0, 0, 'admin/company.php|admin/company.php', 1, 'c280f5c6f04e91f3d6072eb6f1c4bab01ff06280e5201d4a1e801659655c9878', 'v2', '2026-04-21T11:16:15+00:00', '["admin/company.php:747|read|print $formother->select_month(getDolGlobalString(''SOCIETE_FISCAL_MONTH_START''), ''SOCIETE_FISCAL_MONTH_START'', 0, 1, ''maxwidth100'').''</td></tr>'';", "accountancy/tpl/export_journal.tpl.php:72|read|$fiscalmonth = getDolGlobalInt(''SOCIETE_FISCAL_MONTH_START'', 1);", "compta/resultat/result.php:76  //$conf->global->SOCIETE_FISCAL_MONTH_START = 7;", "compta/resultat/index.php:58  //$conf->global->SOCIETE_FISCAL_MONTH_START = 7;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_IDPROF1_UNIQUE', 'string', NULL, 'societe', 'Enforces uniqueness of the thirdparty professional identifier #1 (idprof1, e.g. SIREN in France) across thirdparties.', 'Read in societe/class/societe.class.php inside id_prof_verifiable($idprof), case 1, returning getDolGlobalBool(''SOCIETE_IDPROF1_UNIQUE'') as the flag telling whether idprof1 must be unique.', 'Enabling it causes idprof1 duplicate checks to be applied when saving a thirdparty.', 'Boolean: true means idprof1 must be unique across thirdparties.', 1, 0, NULL, 1, '052b1aa96587393bc7cc26c8f423f8690a8c562e7745499dd172e2641c689ff7', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4209|read|$ret = getDolGlobalBool(''SOCIETE_IDPROF1_UNIQUE'');"]', 'medium', NULL);
