INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_IDPROF6_UNIQUE', 'string', NULL, 'societe', 'Enforces uniqueness of the thirdparty professional identifier #6 (idprof6) across thirdparties.', 'Read in societe/class/societe.class.php inside id_prof_verifiable($idprof), case 6, returning getDolGlobalBool(''SOCIETE_IDPROF6_UNIQUE'') as the flag telling whether idprof6 must be unique.', 'Enabling it causes idprof6 duplicate checks to be applied when saving a thirdparty.', 'Boolean: true means idprof6 must be unique across thirdparties.', 1, 0, NULL, 1, 'b2cc747fcd7c48300918e682150439d84f43dbaa6bc0daa765f1783478fbe406', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4224|read|$ret = getDolGlobalBool(''SOCIETE_IDPROF6_UNIQUE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_NO_SYNC_LINKED_MEMBER', 'string', NULL, 'societe', 'Controls whether updating a third-party''s data also synchronizes data to a linked member (Adherent) record.', 'In societe/card.php:701, $nosyncmember = getDolGlobalInt(''SOCIETE_NO_SYNC_LINKED_MEMBER'') is read and passed as the $nosyncmember argument to $object->update(), which conditionally skips syncing linked member data.', 'When set (truthy), updates to a third-party''s record are not propagated to any linked member record; when unset, third-party updates continue to sync to a linked member as before.', 'Not set/0 (default): sync to linked member occurs. Truthy: sync to linked member is skipped (per the parameter name ''nosyncmember'').', 1, 0, NULL, 1, '0074132832b45911c15792331205096cc295cc45a8cbfb7f4fb2a67f879a4811', 'v2', '2026-07-24T07:05:23+00:00', '["societe/card.php:701|read|$nosyncmember = getDolGlobalInt(''SOCIETE_NO_SYNC_LINKED_MEMBER'');", "societe/card.php:703|code|$result = $object->update($socid, $user, 1, ..., ''update'', $nosyncmember);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_ON_SEARCH_AND_LIST_GO_ON_CUSTOMER_OR_SUPPLIER_CARD', 'string', NULL, 'societe', 'When clicking a third party in search results or lists, redirects directly to the customer or supplier card instead of the generic third-party card.', 'Written via societe/admin/societe.php:322 and admin/mailing.php:121 as a ''yesno'' constant. Checked in societe/class/societe.class.php:3265 and societe/list.php:934 to alter the navigation target URL.', 'Enabling this constant changes the click behaviour on third-party lists to open the role-specific card (customer or supplier); disabling opens the generic third-party card.', 'yesno: ''1'' or ''yes'' = go to customer/supplier card; ''0'' or empty = go to generic third-party card', 0, 0, 'societe/admin/societe.php|admin/mailing.php', 1, '0e33cc6268dd78f90b32c2446c06510f017797ca04e5d75694843828c73695ec', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:322|write|$res = dolibarr_set_const($db, \"SOCIETE_ON_SEARCH_AND_LIST_GO_ON_CUSTOMER_OR_SUPPLIER_CARD\", $setonsearchandlistgooncustomerorsuppliercard, ''yesno'', 0, '''', $conf->entity);", "admin/mailing.php:121|write|$res = dolibarr_set_const($db, \"SOCIETE_ON_SEARCH_AND_LIST_GO_ON_CUSTOMER_OR_SUPPLIER_CARD\", $setonsearchandlistgooncustomerorsuppliercard, ''yesno'', 0, '''', $conf->entity);", "societe/class/societe.class.php:3265|check|if (getDolGlobalString(''SOCIETE_ON_SEARCH_AND_LIST_GO_ON_CUSTOMER_OR_SUPPLIER_CARD'')) {", "societe/list.php:934|check|if (getDolGlobalString(''SOCIETE_ON_SEARCH_AND_LIST_GO_ON_CUSTOMER_OR_SUPPLIER_CARD'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_RIB_ALLOW_ONLINESIGN', 'bool', NULL, 'societe', 'Enables online signing of RIB (bank account) documents for third-party records.', 'Checked in 5 occurrences in societe/paymentmodes.php and core/class/commonobject.class.php:6398. Always used in conjunction with SOCIETE_DISABLE_BANKACCOUNT check; core/class/commonobject.class.php:6398 checks it specifically for the ''societe_rib'' element.', 'When enabled (and bank account is not disabled), online signing links/actions are displayed for RIB documents on third-party payment modes pages.', '0 or unset = online signing disabled; non-zero = online signing enabled', 1, 0, NULL, 1, '8367a00f714046100ff3c1adec42dd6b4373d0805e3779c23076b4bce50e2016', 'v2', '2026-04-21T11:16:15+00:00', '["societe/paymentmodes.php:1758|check|if (!getDolGlobalInt(''SOCIETE_DISABLE_BANKACCOUNT'') && getDolGlobalInt(\"SOCIETE_RIB_ALLOW_ONLINESIGN\")) {", "core/class/commonobject.class.php:6398|check|if ($this->element == ''societe_rib'' && getDolGlobalInt(\"SOCIETE_RIB_ALLOW_ONLINESIGN\")) {", "societe/paymentmodes.php:1908|check|if (!getDolGlobalInt(''SOCIETE_DISABLE_BANKACCOUNT'') && getDolGlobalInt(\"SOCIETE_RIB_ALLOW_ONLINESIGN\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_RIB_ONLINE_SIGNATURE_SECURITY_TOKEN', 'string', NULL, 'public', 'Secret salt used to verify the security key on public online-signature links for third-party bank account (RIB) mandates.', 'Read in public/onlinesign/newonlinesign.php:156 as $securekeyseed when $source == ''societe_rib'', falling back to a hash of the instance unique ID; combined with type/ref via dol_verifyHash() to validate the SECUREKEY query parameter.', 'Changing this value invalidates all previously generated online RIB-signature links, since the verification hash depends on it.', 'Any string used as a hash salt; falls back to substr(dol_hash(''dolibarr''.$dolibarr_main_instance_unique_id,''sha256''),0,32) if not set.', 1, 0, NULL, 1, 'fbb3cd3b1597c5157da0d01bdc065189daea4493fa79e8bbfdf00f698beb6a03', 'v2', '2026-07-24T07:05:23+00:00', '["public/onlinesign/newonlinesign.php:156: $securekeyseed = getDolGlobalString(''SOCIETE_RIB_ONLINE_SIGNATURE_SECURITY_TOKEN'', $defaultsalt);", "public/onlinesign/newonlinesign.php:159: if (!dol_verifyHash($securekeyseed.$type.$ref...(...), $SECUREKEY, ''hash'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_SHOW_FIELD_IN_TOOLTIP', 'bool', NULL, 'societe', 'Specifies which additional third-party fields (e.g. VAT number, EUID, profid1-3) are shown in the company tooltip.', 'Read in societe/class/societe.class.php at lines 3179, 3183, 3187, 3188, 3191, 3194, and more (11 occurrences). The value is checked with strpos() for keywords ''vatnumber'', ''euid'', ''profid1'', ''profid2'', ''profid3'' to conditionally include each field in the tooltip HTML. No admin UI write found; HIDDEN_GUESS is 1.', 'Setting this to a comma-separated or space-separated string of field keys causes those fields to appear in the third-party hover tooltip; leaving it empty shows only the default tooltip content.', 'String: space/comma-separated field keys (e.g. ''vatnumber euid profid1 profid2 profid3''); empty = no extra fields shown', 1, 0, NULL, 1, '10a286cb963cfa295cf9203a2bb809bdb66eb1fa520bdead19dad028e3e104ae', 'v2', '2026-04-21T11:16:15+00:00', '["societe/class/societe.class.php:3179|check|if (!empty($this->tva_intra) || (getDolGlobalString(''SOCIETE_SHOW_FIELD_IN_TOOLTIP'') && strpos($conf->global->SOCIETE_SHOW_FIELD_IN_TOOLTIP, ''vatnumber'') !== false)) {", "societe/class/societe.class.php:3183|check|if (!empty($this->euid) || (getDolGlobalString(''SOCIETE_SHOW_FIELD_IN_TOOLTIP'') && strpos($conf->global->SOCIETE_SHOW_FIELD_IN_TOOLTIP, ''euid'') !== false)) {", "societe/class/societe.class.php:3188|read|if (strpos($conf->global->SOCIETE_SHOW_FIELD_IN_TOOLTIP, ''profid1'') !== false && $langs->trans(''ProfId1''.$this->country_code) != ''-'') {", "societe/class/societe.class.php:3187|check|if (getDolGlobalString(''SOCIETE_SHOW_FIELD_IN_TOOLTIP'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_SHOW_VAT_IN_LIST', 'bool', NULL, 'societe', 'Shows the intra-community VAT number column in the third-party list view.', 'When enabled, the intra-community VAT number (tva_intra) is displayed alongside the company name in the third-party selector dropdown. Configured via societe/admin/societe.php.', 'Enabling this adds the VAT number to the company selector list display. Disabling it hides that field from the list.', 'Truthy = show VAT number in list; empty/falsy = hide', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, 'c879c4df42bc21164d82f36d7ba1d57a8e694423834266287a8fb1a349fc184f', 'v2', '2026-04-21T11:16:15+00:00', '["societe/admin/societe.php:879|check|if (getDolGlobalString(''SOCIETE_SHOW_VAT_IN_LIST'')) {", "core/class/html.form.class.php:1724|check|if (getDolGlobalString(''SOCIETE_SHOW_VAT_IN_LIST'') && !empty($obj->tva_intra)) {", "societe/admin/societe.php:209|write|$res = dolibarr_set_const($db, \"SOCIETE_SHOW_VAT_IN_LIST\", $setvatinlist, ''yesno'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_SORT_ON_TYPEENT', 'string', NULL, 'commande', 'Adds sorting by ''position'' field for the thirdparty type dictionary (typent) instead of only country/label.', 'Checked with getDolGlobalString in admin/dict.php (lines 323, 370, 417, 464) affecting sort/field/insert clauses for DICT_TYPENT, and used as a default sort direction fallback in reception/list.php, supplier_proposal/list.php, don/stats/index.php, and fourn/facture/list.php.', 'When enabled, the thirdparty type dictionary list and related search selects (search_type_thirdparty) are sorted/ordered by an added ''position'' column instead of the default order.', NULL, 0, 0, 'admin/dict.php|admin/dict.php|admin/dict.php|admin/dict.php', 1, '0603a7bdd699a5cf7bc27b5d5b8525ccaf325cdca33379b0bf538ff428e67441', 'v2', '2026-07-24T06:41:12+00:00', '["$tabsqlsort[DICT_TYPENT] = \"country DESC,\".(getDolGlobalString(''SOCIETE_SORT_ON_TYPEENT'') ? '' t.position ASC,'' : '''').\" libelle ASC\";", "getDolGlobalString(''SOCIETE_SORT_ON_TYPEENT'', ''ASC'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_USE_SEARCH_TO_SELECT', 'bool', NULL, 'societe', 'Minimum number of characters required in the third-party search filter before the AJAX company-search endpoint will run the query, used as an anti-DOS protection.', 'Used in societe/ajax/company.php:132: if dol_strlen($filter) is less than getDolGlobalInt(''SOCIETE_USE_SEARCH_TO_SELECT''), the request is rejected with httponly_accessforbidden(''Call the societe/ajax/company file with a too short filter'', 400).', 'Setting a higher value forces users to type more characters before the third-party AJAX search executes, reducing search-triggered database load; despite TYPE:bool in the payload, the code treats it as an integer minimum-length threshold, not a boolean flag.', 'Integer: minimum character length of the search filter required to run the AJAX company search (anti-DOS threshold), compared via dol_strlen($filter) < value.', 1, 0, NULL, 1, '01626df03510d4036dfff693b0c57e1f73c091e4f10e8510adeac94c4676372c', 'v2', '2026-07-24T07:05:23+00:00', '["societe/ajax/company.php:132: if (dol_strlen($filter) < getDolGlobalInt(''SOCIETE_USE_SEARCH_TO_SELECT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_VAT_INTRA_INVOICE_MANDATORY', 'string', NULL, 'societe', 'Makes the intra-community VAT number mandatory on invoices, optionally restricted to EU-only thirdparties.', 'Checked with getDolGlobalString in societe/admin/societe.php:763/772 and compta/facture/class/facture.class.php:3663/3670, testing for value ''eeconly'' as a special case.', 'Value ''eeconly'' restricts the mandatory VAT-intra check to companies in the EU (tva_assuj and empty tva_intra); any other truthy value makes it mandatory more broadly per the elseif branch.', '''eeconly'' = mandatory only for EU (intra-community) thirdparties', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, '4cb1b16f0391e445a10f4f222ef800759718e47d17acdd853b4bcdb272c01e97', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''SOCIETE_VAT_INTRA_INVOICE_MANDATORY'') == ''eeconly'') {", "} elseif (getDolGlobalString(''SOCIETE_VAT_INTRA_INVOICE_MANDATORY'') && ($this->thirdparty->tva_assuj) && empty($this->thirdparty->tva_intra)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_VAT_INTRA_MANDATORY', 'string', NULL, 'societe', 'Makes the intra-community VAT number mandatory for VAT-liable thirdparties when set.', 'Checked in societe/class/societe.class.php:1371 and configurable through the admin page societe/admin/societe.php:753; if the thirdparty is VAT-liable ($this->tva_assuj) and the VAT-intra value is empty, an error is raised.', 'Enabling it blocks saving a VAT-liable thirdparty that has no VAT-intra number filled in.', 'Boolean-like: truthy makes the field mandatory for VAT-liable thirdparties.', 0, 0, 'societe/admin/societe.php', 1, '04c726c39abc7a81c7254d78641b70283bbc35d49f8a53ec7092e45732059d81', 'v2', '2026-07-24T07:05:23+00:00', '["societe/admin/societe.php:753|check|if (getDolGlobalString(''SOCIETE_VAT_INTRA_MANDATORY'')) {", "societe/class/societe.class.php:1371|check|if ($this->tva_assuj && !$vallabel && getDolGlobalString(''SOCIETE_VAT_INTRA_MANDATORY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SOCIETE_VAT_INTRA_UNIQUE', 'string', NULL, 'societe', 'Enforces uniqueness of the intra-community VAT number across thirdparties when set.', 'Checked in societe/class/societe.class.php:1364 and configurable through the admin page societe/admin/societe.php:744; when set and the VAT number is not empty, id_prof_exists() checks for a duplicate on another thirdparty.', 'Enabling it prevents saving a thirdparty with a VAT-intra number already used by another thirdparty.', 'Boolean-like: truthy enables the uniqueness check.', 0, 0, 'societe/admin/societe.php', 1, '309b93bd4cce095626b5f2944e7dea92bbefd582ad785325c002a8899afd7d39', 'v2', '2026-07-24T07:05:23+00:00', '["societe/admin/societe.php:744|check|if (getDolGlobalString(''SOCIETE_VAT_INTRA_UNIQUE'')) {", "societe/class/societe.class.php:1364|check|if ($vallabel && getDolGlobalString(''SOCIETE_VAT_INTRA_UNIQUE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFERLINE_ADDON_PDF', 'string', NULL, 'product', 'Selects the default PDF document model (template) used to generate PDFs for stock transfer lines when no model is otherwise specified.', 'In product/stock/stocktransfer/class/stocktransferline.class.php:986-987 (generateDocument), if $this->model_pdf is empty, the code falls back to this constant as the $modele name (defaulting to ''standard_stocktransferline'' if unset).', 'Setting it changes which PDF template code is used to render stock transfer line documents when the object itself has no model_pdf assigned.', 'String: name of a stocktransferline PDF document model (e.g. ''standard_stocktransferline'').', 0, 0, NULL, 1, '14e4d924bc7f6e51cbf7bec124793284c436ca98a4ef67323a5f45e658ae2406', 'v2', '2026-07-24T07:05:23+00:00', '["product/stock/stocktransfer/class/stocktransferline.class.php:986: } elseif (getDolGlobalString(''STOCKTRANSFERLINE_ADDON_PDF'')) {", "product/stock/stocktransfer/class/stocktransferline.class.php:987: $modele = getDolGlobalString(''STOCKTRANSFERLINE_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFER_ADDON_PDF', 'string', NULL, 'product', 'Specifies the PDF template module name used to generate stock transfer documents.', 'Read at product/stock/stocktransfer/class/stocktransfer.class.php:1050–1051 to select the PDF generation module, and at product/stock/stocktransfer/stocktransfer_card.php:489 as the pre-selected template in the document generation UI.', 'Changing this value switches the PDF template used for stock transfer documents. Leaving it unset causes no specific template to be pre-selected via this constant.', 'String: PDF module name (e.g. ''pdf_eagle''); empty/unset = no pre-selection via this constant.', 1, 0, NULL, 1, '9a7bd5bc5188a3ade96179dfc76b638ffdcbe90d554f5dce82955ffca1550fe4', 'v2', '2026-04-21T13:50:40+00:00', '["product/stock/stocktransfer/class/stocktransfer.class.php:1050|read|} elseif (getDolGlobalString(''STOCKTRANSFER_ADDON_PDF'')) {", "product/stock/stocktransfer/class/stocktransfer.class.php:1051|read|$modele = getDolGlobalString(''STOCKTRANSFER_ADDON_PDF'');", "product/stock/stocktransfer/stocktransfer_card.php:489|read|$preselected = getDolGlobalString(''STOCKTRANSFER_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFER_DRAFT_WATERMARK', 'string', NULL, 'core', 'Defines the watermark text printed on stock-transfer PDF documents that are in draft status.', 'Checked in core/modules/stocktransfer/doc/pdf_eagle.modules.php:1033 and core/modules/stocktransfer/doc/pdf_eagle_proforma.modules.php:1213, both conditioned on the document being in status 0 (draft). When set, the watermark text is applied.', 'When set, draft stock-transfer PDFs display the specified watermark string. When unset, no watermark is applied to draft documents.', 'Arbitrary watermark text string; empty or unset means no watermark on drafts.', 1, 0, NULL, 1, 'f261aa26e5faa8f49cef3304f6579b6d40d92e35b675f8940657a59899d53515', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/stocktransfer/doc/pdf_eagle.modules.php:1033|check|if ($object->statut == 0 && (getDolGlobalString(''STOCKTRANSFER_DRAFT_WATERMARK''))) {", "core/modules/stocktransfer/doc/pdf_eagle_proforma.modules.php:1213|check|if ($object->status == 0 && getDolGlobalString(''STOCKTRANSFER_DRAFT_WATERMARK'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFER_PDF_DISPLAY_AMOUNT_HT', 'string', NULL, 'core', 'Enables display of pre-tax unit amounts (prices) on stock-transfer PDF documents when set.', 'Checked in core/modules/stocktransfer/doc/pdf_eagle.modules.php at lines 132 (commented block), 665, 857, and 968 (commented block). Lines 132 and 968 are commented-out code; lines 665 and 857 are active checks that conditionally render price columns. The COMMENTS show: ''// Show also the prices''.', 'When set, price columns are shown in stock-transfer PDF output. Note: some price-display blocks are currently commented out in the code.', 'Truthy value (e.g. 1) to show prices on PDF; 0 or empty to hide them.', 1, 0, NULL, 1, 'b39038bb35d75049edab7c0bb2d54d373eb498bc6bcb0583ce1007242c193739', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/stocktransfer/doc/pdf_eagle.modules.php:132  /*if (getDolGlobalString(''STOCKTRANSFER_PDF_DISPLAY_AMOUNT_HT'')) {\t// Show also the prices", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:665|check|if (getDolGlobalString(''STOCKTRANSFER_PDF_DISPLAY_AMOUNT_HT'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:857|check|if (getDolGlobalString(''STOCKTRANSFER_PDF_DISPLAY_AMOUNT_HT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFER_PDF_HIDE_ORDERED', 'bool', NULL, 'core', 'Hides the ''ordered'' quantity column from stock-transfer PDF documents when enabled.', 'Checked in core/modules/stocktransfer/doc/pdf_eagle.modules.php at lines 155 (commented block), 803, and 852. Active checks at lines 803 and 852 suppress the ordered-quantity column when the constant is set.', 'Enabling this constant removes the ordered quantity column from stock-transfer PDFs.', 'Truthy value (e.g. 1) to hide the ordered column; 0 or empty to show it.', 1, 0, NULL, 1, 'e43cbf3ac8e3deabcad76f491b0f8d23aee5f50596b8e398a18a20e8b6ab6d3c', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/stocktransfer/doc/pdf_eagle.modules.php:803|check|if (!getDolGlobalString(''STOCKTRANSFER_PDF_HIDE_ORDERED'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:852|check|if (!getDolGlobalString(''STOCKTRANSFER_PDF_HIDE_ORDERED'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:155  /*if (getDolGlobalString(''STOCKTRANSFER_PDF_HIDE_ORDERED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFER_PDF_HIDE_WEIGHT_AND_VOLUME', 'bool', NULL, 'core', 'Hides weight and volume columns from stock-transfer PDF documents when enabled.', 'Checked in core/modules/stocktransfer/doc/pdf_eagle.modules.php at lines 140, 528, 633, 865, and 941. When set, weight/volume sections are skipped; when not set, they are rendered.', 'Enabling this constant removes weight and volume data from generated stock-transfer PDFs, which simplifies the document layout.', 'Truthy value (e.g. 1) to hide weight/volume; 0 or empty to show them.', 1, 0, NULL, 1, 'c4ca32f65bc1962d169f7c858ab8b717d6a684276ba14e34cf4a48a2086c2857', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/stocktransfer/doc/pdf_eagle.modules.php:633|check|if (!getDolGlobalString(''STOCKTRANSFER_PDF_HIDE_WEIGHT_AND_VOLUME'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:865|check|if (!getDolGlobalString(''STOCKTRANSFER_PDF_HIDE_WEIGHT_AND_VOLUME'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:140|check|if (getDolGlobalString(''STOCKTRANSFER_PDF_HIDE_WEIGHT_AND_VOLUME'')) {", "core/modules/stocktransfer/doc/pdf_eagle.modules.php:941|check|if (!getDolGlobalString(''STOCKTRANSFER_PDF_HIDE_WEIGHT_AND_VOLUME'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFER_STOCKTRANSFERLINE_ADDON', 'string', NULL, 'product', 'Selects the active numbering module for stock-transfer line references.', 'Read and conditionally set in product/stock/stocktransfer/class/stocktransferline.class.php. If not set, it defaults to ''mod_stocktransferline_standard'' (line 916). The value is used to load the corresponding module file (line 922) and class (line 923).', 'Changing this constant switches the numbering module for stock-transfer lines; the chosen module file must exist.', 'Name of a valid stock-transfer-line numbering module; default is ''mod_stocktransferline_standard''.', 1, 0, NULL, 1, '387b596a94cfd3a1c6d4277a363887af789ded942875c03681510da7c928afe7', 'v2', '2026-04-21T13:50:40+00:00', '["product/stock/stocktransfer/class/stocktransferline.class.php:915|check|if (!getDolGlobalString(''STOCKTRANSFER_STOCKTRANSFERLINE_ADDON'')) {", "product/stock/stocktransfer/class/stocktransferline.class.php:916|write|$conf->global->STOCKTRANSFER_STOCKTRANSFERLINE_ADDON = ''mod_stocktransferline_standard'';", "product/stock/stocktransfer/class/stocktransferline.class.php:922|read|$file = getDolGlobalString(''STOCKTRANSFER_STOCKTRANSFERLINE_ADDON'') . \".php\";", "product/stock/stocktransfer/class/stocktransferline.class.php:923|read|$classname = getDolGlobalString(''STOCKTRANSFER_STOCKTRANSFERLINE_ADDON'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFER_STOCKTRANSFER_ADDON', 'string', NULL, 'product', 'Specifies the numbering module class name used to generate stock transfer reference numbers.', 'Checked and read at product/stock/stocktransfer/class/stocktransfer.class.php:982–990. When unset, the code defaults to ''mod_stocktransfer_standard'' (written to conf->global at :983). When set, the stored value is used as $classname and $file to load the numbering module.', 'Changing this value switches the reference numbering module for stock transfers. Leaving unset uses ''mod_stocktransfer_standard'' as the default.', 'String: PHP class name of the numbering module (e.g. ''mod_stocktransfer_standard''); unset = defaults to ''mod_stocktransfer_standard''.', 1, 0, NULL, 1, '41e1dce0ccd09c762dd54ffa91c4089fc588e269c411e575e139367015ccd9b5', 'v2', '2026-04-21T13:50:40+00:00', '["product/stock/stocktransfer/class/stocktransfer.class.php:982|check|if (!getDolGlobalString(''STOCKTRANSFER_STOCKTRANSFER_ADDON'')) {", "product/stock/stocktransfer/class/stocktransfer.class.php:983|write|$conf->global->STOCKTRANSFER_STOCKTRANSFER_ADDON = ''mod_stocktransfer_standard'';", "product/stock/stocktransfer/class/stocktransfer.class.php:990|read|$classname = getDolGlobalString(''STOCKTRANSFER_STOCKTRANSFER_ADDON'');", "product/stock/stocktransfer/class/stocktransfer.class.php:989|read|$file = getDolGlobalString(''STOCKTRANSFER_STOCKTRANSFER_ADDON'') . \".php\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCKTRANSFER_STOCKTRANSFER_ADVANCED_MASK', 'string', NULL, 'core', 'Numbering mask pattern for the ''Advanced'' StockTransfer numbering module, defining the auto-generated reference format for stock transfers.', 'Set via a text input on admin/stocktransfer.php (core/modules/stocktransfer/mod_stocktransfer_advanced.php:96), and read at line 149 by getNextValue() to build the next stock transfer reference; if empty, getNextValue() returns 0 with error ''NotConfigured''.', 'Changing the mask changes the format of newly generated StockTransfer references; if left empty, reference generation fails (getExample()/getNextValue() report ''NotConfigured'').', 'Free-form numbering mask string (Dolibarr generic mask codes, e.g. {yyyy}{mm}-{0000}); empty/unset disables numbering (NotConfigured).', 0, 0, NULL, 1, '0e291ed5bd70de8191a72e8f9616679d9bbde6a7ceabd0449cc3449db957d52e', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/stocktransfer/mod_stocktransfer_advanced.php:96|read|...name=\"maskStockTransfer\" value=\"''.getDolGlobalString(''STOCKTRANSFER_STOCKTRANSFER_ADVANCED_MASK'').''\"", "core/modules/stocktransfer/mod_stocktransfer_advanced.php:149|read|$mask = getDolGlobalString(''STOCKTRANSFER_STOCKTRANSFER_ADVANCED_MASK'');", "core/modules/stocktransfer/mod_stocktransfer_advanced.php|if (!$mask) { $this->error = ''NotConfigured''; return 0; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_ADDON_PDF', 'string', NULL, 'admin', 'Selects the PDF generation module (addon) used for warehouse/stock movement documents.', 'Written at admin/stock.php:196 and 199; read at admin/stock.php:718, 190, and product/stock/class/entrepot.class.php:1037-1038. The value is matched against available PDF module names to select the active one for stock document generation.', 'Changing this value switches the PDF template used when generating stock/warehouse documents.', 'String matching the name of the installed stock PDF addon module; empty = no addon selected', 0, 0, 'admin/stock.php|admin/stock.php|admin/stock.php|admin/stock.php|admin/stock.php', 1, '8f7ac1377176097b4b7393e46584d2be634161d0ecfced6fefeefa7daacfa1d6', 'v2', '2026-04-21T13:29:58+00:00', '["admin/stock.php:196|write|if (dolibarr_set_const($db, \"STOCK_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "admin/stock.php:718|check|if (getDolGlobalString(''STOCK_ADDON_PDF'') == $name) {", "product/stock/class/entrepot.class.php:1037|read|} elseif (getDolGlobalString(''STOCK_ADDON_PDF'')) {", "product/stock/class/entrepot.class.php:1038|read|$modele = getDolGlobalString(''STOCK_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies one or more comma/newline-separated directory paths where ODT stock document templates are searched.', 'Read and checked at core/modules/stock/doc/doc_generic_stock_odt.modules.php:123, :150, :158. The value is split by commas/newlines into a list of directories; when non-empty the configured paths are used instead of or alongside defaults.', 'Changing this value redirects the ODT template search to the specified directories. Leaving it unset causes the module to use its built-in default template location.', 'String: comma or newline-separated directory paths; empty/unset = use module default template path.', 1, 0, NULL, 1, 'a5c3bfe40d0319b2f117ceda566b234e1ceb42cc02d47b0f4b3feed5788292f1', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/stock/doc/doc_generic_stock_odt.modules.php:123|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''STOCK_ADDON_PDF_ODT_PATH''))));", "core/modules/stock/doc/doc_generic_stock_odt.modules.php:158|check|if (getDolGlobalString(''STOCK_ADDON_PDF_ODT_PATH'')) {", "core/modules/stock/doc/doc_generic_stock_odt.modules.php:150|read|$texte .= getDolGlobalString(''STOCK_ADDON_PDF_ODT_PATH'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_ALLOW_ADD_LIMIT_STOCK_BY_WAREHOUSE', 'bool', NULL, 'product', 'Enables per-warehouse minimum and desired stock level limits in replenishment.', 'Configured via admin/stock.php:888 and checked in 21 occurrences across product/stock/replenish.php and core/modules/modProduct.class.php. When set with a warehouse filter active, per-warehouse stock thresholds are used instead of global product thresholds.', 'Enabling this constant activates per-warehouse stock limit fields in replenishment; disabling it uses global product-level stock thresholds.', 'Non-empty = per-warehouse limits enabled; empty or unset = global limits used', 0, 0, 'admin/stock.php', 1, 'f1a7b6a53810a11e1c03744403450941c68190b93b452eddd917a90fcb620f41', 'v2', '2026-04-21T13:29:58+00:00', '["admin/stock.php:888|read|print $form->selectarray(\"STOCK_ALLOW_ADD_LIMIT_STOCK_BY_WAREHOUSE\", $arrval, getDolGlobalString(''STOCK_ALLOW_ADD_LIMIT_STOCK_BY_WAREHOUSE''));", "product/stock/replenish.php:404|check|if (getDolGlobalString(''STOCK_ALLOW_ADD_LIMIT_STOCK_BY_WAREHOUSE'') && $fk_entrepot > 0) {", "product/stock/replenish.php:633|check|if (empty($fk_entrepot) && getDolGlobalString(''STOCK_ALLOW_ADD_LIMIT_STOCK_BY_WAREHOUSE'')) {", "core/modules/modProduct.class.php:820|check|if (getDolGlobalString(''STOCK_ALLOW_ADD_LIMIT_STOCK_BY_WAREHOUSE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_ALLOW_DELETE_OF_MOVEMENT', 'bool', NULL, 'product', 'Allows deletion of stock movement records from the stock movement list via mass action.', 'Read in product/stock/movement_list.php:1128, guarding whether the ''predelete'' mass action (Delete) is added to the list''s available mass actions; preceded by the comment ''By default, we should never accept deletion of stock movement''.', 'Enabling it (together with delete permission) exposes a mass-delete action for stock movement lines in the list; unset/0 keeps deletion of stock movements unavailable, which is the default/recommended behavior since movements should normally be reversed, not deleted.', 'Boolean-like: enabled = allow mass deletion of stock movements (if $permissiontodelete is also true); unset/0 = deletion not offered (default).', 0, 0, NULL, 1, 'dc9fb3175c115066fb6cf9d4c61e2a6f3f7b35883dacfc62e856ad73b2b488f5', 'v2', '2026-07-24T07:05:23+00:00', '["product/stock/movement_list.php:1127: // By default, we should never accept deletion of stock movement", "product/stock/movement_list.php:1128: if (getDolGlobalString(''STOCK_ALLOW_DELETE_OF_MOVEMENT'') && $permissiontodelete) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_ALLOW_VIRTUAL_STOCK_PER_WAREHOUSE', 'bool', NULL, 'product', 'Enables per-warehouse virtual stock calculation.', 'Checked in product/class/product.class.php:6511 alongside $this->stock_warehouse, and in product/stock/replenish.php:894. No admin UI.', 'When enabled, virtual stock figures are computed and displayed per warehouse rather than globally across all warehouses.', 'Truthy string (per-warehouse virtual stock active) or empty/unset (global virtual stock only).', 1, 0, NULL, 1, 'ec3c63cbb76479a039121690f61ea14b271a5e5bb3686ee2a74b4be47e5854d3', 'v2', '2026-04-21T13:29:58+00:00', '["product/class/product.class.php:6511|check|if (!empty($this->stock_warehouse) && getDolGlobalString(''STOCK_ALLOW_VIRTUAL_STOCK_PER_WAREHOUSE'')) {", "product/stock/replenish.php:894|check|if (getDolGlobalString(''STOCK_ALLOW_VIRTUAL_STOCK_PER_WAREHOUSE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_ALWAYS_SHOW_FULL_ARBO', 'bool', NULL, 'product', 'Forces the warehouse tree/path to always display the full hierarchy rather than just the label.', 'Read at admin/stock.php:900 in a select array form. Used at product/stock/class/entrepot.class.php:902 where the full path is shown if either $showfullpath is set or this constant is truthy.', 'Enabling this constant makes warehouse labels always show their full hierarchical path; disabling it shows only the immediate label unless the caller requests the full path.', '0 or empty = show warehouse label only by default; any truthy value = always show full warehouse hierarchy path', 0, 0, 'admin/stock.php', 1, '6fedf5f61c4721c012f990a7b77d13362014138faa7e4646dd3216b85ac7b6fa', 'v2', '2026-04-21T13:29:58+00:00', '["product/stock/class/entrepot.class.php:902|read|$result .= (($showfullpath || getDolGlobalString(''STOCK_ALWAYS_SHOW_FULL_ARBO'')) ? $this->get_full_arbo() : $this->label);", "admin/stock.php:900|read|print $form->selectarray(\"STOCK_ALWAYS_SHOW_FULL_ARBO\", $arrval, getDolGlobalString(''STOCK_ALWAYS_SHOW_FULL_ARBO''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_BILL', 'string', NULL, 'compta', 'Decrements/increments stock at the time an invoice is validated, rather than at another stock-triggering event.', 'Deleted via admin/stock.php:90 dolibarr_del_const, set through the select at admin/stock.php:303, and checked with getDolGlobalString in product/class/product.class.php:3805, compta/facture/class/facture.class.php (lines 3240, 3779, 4117), and compta/facture/card.php.', 'When active, stock for the main product and its components is decremented at invoice validation, per the explicit comment in facture.class.php; it is mutually exclusive with other STOCK_CALCULATE_ON_* triggers per the DELETE comment in modExpedition.class.php.', NULL, 0, 0, 'admin/stock.php|admin/stock.php', 1, 'ac863a01c4256e4c6188f09a0c11c8204c3e432cc56c7b7fe64ce0c0d15b9588', 'v2', '2026-07-24T06:41:12+00:00', '["// If active (STOCK_CALCULATE_ON_BILL), we decrement the main product and its components at invoice validation", "//\"DELETE FROM \".MAIN_DB_PREFIX.\"const WHERE name IN (''STOCK_CALCULATE_ON_BILL'', ''STOCK_CALCULATE_ON_VALIDATE_ORDER'', ''STOCK_CALCULATE_ON_SHIPMENT'', ''STOCK_CALCULATE_ON_SHIPMENT_CLOSE'') AND entity = \".((int) $conf->entity),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_RECEPTION', 'string', NULL, 'reception', 'Decrements/increments stock at the time a reception is created/processed, rather than at another stock-triggering event.', 'Deleted via admin/stock.php:98 dolibarr_del_const, set through the select at admin/stock.php:452, and checked with getDolGlobalInt in reception/class/reception.class.php (lines 682, 1429, 1729, 2352) and reception/dispatch.php:459.', 'When active, stock is recalculated on the reception itself; the DELETE comment in modReception.class.php shows it is one of several mutually exclusive STOCK_CALCULATE_ON_* triggers (supplier bill, validate order, dispatch order, reception, reception close).', NULL, 0, 0, 'admin/stock.php|admin/stock.php|admin/stock.php', 1, '4610142a297ac30ccd85f3f9053ad95cfe20bbce94cc8f145b66cd59e7421463', 'v2', '2026-07-24T06:41:12+00:00', '["if (!$error && isModEnabled(''stock'') && getDolGlobalInt(''STOCK_CALCULATE_ON_RECEPTION'')) {", "//\"DELETE FROM \".MAIN_DB_PREFIX.\"const WHERE name IN (''STOCK_CALCULATE_ON_SUPPLIER_BILL'', ''STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER'', ''STOCK_CALCULATE_ON_SUPPLIER_DISPATCH_ORDER'', ''STOCK_CALCULATE_ON_RECEPTION'', ''STOCK_CALCULATE_ON_RECEPTION_CLOSE'') AND enti"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_RECEPTION_CLOSE', 'string', NULL, 'reception', 'Decrements/increments stock at the time a reception is closed, rather than at another stock-triggering event.', 'Deleted via admin/stock.php:99 dolibarr_del_const, set through the select at admin/stock.php:471 (see also comment at line 264), and checked with getDolGlobalInt in reception/class/reception.class.php (lines 1732, 2054, 2215) and reception/card.php.', 'When active, stock is recalculated when the reception is closed rather than at creation; core/class/conf.class.php:963 notes that enabling the lot/serial module forces the inc/dec mode to this constant and STOCK_CALCULATE_ON_SHIPMENT_CLOSE.', NULL, 0, 0, 'admin/stock.php|admin/stock.php|admin/stock.php', 1, 'c226d2d85f6fb23e0cf1c49fda61875785a66cd60fbc9f41020c383953c02305', 'v2', '2026-07-24T06:41:12+00:00', '["// If module lot/serial enabled, we force the inc/dec mode to STOCK_CALCULATE_ON_SHIPMENT_CLOSE and STOCK_CALCULATE_ON_RECEPTION_CLOSE", "if (getDolGlobalInt(\"STOCK_CALCULATE_ON_RECEPTION_CLOSE\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_SHIPMENT', 'string', NULL, 'product', 'Triggers stock movements (decrease) when a shipment is validated.', 'Written (deleted) in admin/stock.php at line 92 and rendered as a select at line 349. Checked in expedition/class/expedition.class.php at line 1055 and in product/class/product.class.php at line 6469 to trigger the stock decrement on shipment validation. Admin comments confirm ''STOCK_CALCULATE_ON_SHIPMENT is ok so not disable''.', 'Enabling this constant causes stock levels to be decremented at shipment validation time. It is mutually exclusive with other STOCK_CALCULATE_ON_* modes.', '0 or unset = no stock movement on shipment validation; 1 = stock decremented on shipment validation', 0, 0, 'admin/stock.php|admin/stock.php|admin/stock.php', 1, 'd4a2a21a4031923133b19c04ea90dba95c981ec41fc198f67e389473cb885429', 'v2', '2026-04-21T11:16:15+00:00', '["// STOCK_CALCULATE_ON_SHIPMENT is ok so not disable", "if (!$error && isModEnabled(''stock'') && getDolGlobalString(''STOCK_CALCULATE_ON_SHIPMENT'')) {", "if (getDolGlobalString(''STOCK_CALCULATE_ON_SHIPMENT'') || getDolGlobalString(''STOCK_CALCULATE_ON_SHIPMENT_CLOSE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_SHIPMENT_CLOSE', 'string', NULL, 'product', 'Triggers stock movements (decrease) when a shipment is closed rather than when it is validated.', 'Written (deleted/inserted) in admin/stock.php and referenced in core/modules/modExpedition.class.php and core/class/conf.class.php. Checked in expedition/class/expedition.class.php at lines 2996 and 3207, and in expedition/card.php at line 2679. A conf.class.php comment states: ''If module lot/serial enabled, we force the inc/dec mode to STOCK_CALCULATE_ON_SHIPMENT_CLOSE and STOCK_CALCULATE_ON_RECEPTION_CLOSE''.', 'When the lot/serial module is active this mode is forced automatically. Enabling it defers stock decrements to shipment closure instead of validation.', '0 or unset = no stock movement on shipment close; 1 = stock decremented on shipment close', 0, 0, 'admin/stock.php|admin/stock.php|admin/stock.php', 1, '23ddc0d0cb95e4591842ce95476003a457ae89780f5ee7d9d241f7238a8b32c7', 'v2', '2026-04-21T11:16:15+00:00', '["// If module lot/serial enabled, we force the inc/dec mode to STOCK_CALCULATE_ON_SHIPMENT_CLOSE and STOCK_CALCULATE_ON_RECEPTION_CLOSE", "// STOCK_CALCULATE_ON_SHIPMENT_CLOSE is ok so not disabled", "if (isModEnabled(''stock'') && getDolGlobalString(''STOCK_CALCULATE_ON_SHIPMENT_CLOSE'')) {", "/\"INSERT INTO \".MAIN_DB_PREFIX.\"const (name, value, entity) VALUES (''STOCK_CALCULATE_ON_SHIPMENT_CLOSE'', 1, \".((int) $conf->entity).\")\""]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_SHIPMENT_DISPATCH_ORDER', 'string', NULL, 'expedition', 'Would trigger an immediate stock movement when a quantity is entered/edited directly on the shipment dispatch order page; the only reference is inside a commented-out (dead) code block.', 'Found in expedition/dispatch.php:322, opening a large commented-out block (starting with ''/*'' before it) that would create a MouvementStock and adjust stock based on the difference between the posted quantity and $qtystart, guarded by isModEnabled(''stock'') and this constant.', 'This constant currently has no active effect, since the code path referencing it is commented out in this version of dispatch.php.', 'Boolean-like (checked with !empty()); exact intended values unclear from code alone [SPECULATION] since the block is dead code.', 1, 0, NULL, 1, '89ec41c2c636034c19fbc18ba2d30298734a331b4af5b8c7bf44f6049bd6034c', 'v2', '2026-07-24T07:05:23+00:00', '["expedition/dispatch.php:320: // If module stock is enabled and the stock decrease is done on edition of this page", "expedition/dispatch.php:322: if (!$error && GETPOST($ent, ''int'') > 0 && isModEnabled(''stock'') && !empty($conf->global->STOCK_CALCULATE_ON_SHIPMENT_DISPATCH_ORDER)) {"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_SUPPLIER_BILL', 'string', NULL, 'fourn', 'Controls whether and how stock movements are triggered automatically when a supplier invoice is validated or unvalidated.', 'Configured via admin/stock.php and checked across fourn/class/fournisseur.facture.class.php and fourn/facture/card.php (16+ occurrences). The admin page at admin/stock.php:408 presents a select array of values for this constant.', 'When set, validating or unvalidating a supplier invoice automatically updates stock levels; unsetting it disables automatic stock movements on supplier billing.', 'Selected value from admin UI array (e.g. specific stock movement type codes); empty = disabled', 0, 0, 'admin/stock.php|admin/stock.php', 1, '2a497cac9d8ba134cafd3cf0788f3b57ba7764f4888b6fede47d3160a80bcb90', 'v2', '2026-04-21T11:16:15+00:00', '["admin/stock.php:408|read|print $form->selectarray(\"STOCK_CALCULATE_ON_SUPPLIER_BILL\", $arrval, getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_BILL''));", "fourn/class/fournisseur.facture.class.php:1910|check|if (isModEnabled(''stock'') && getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_BILL'')) {", "fourn/facture/card.php:238|check|if (isModEnabled(''stock'') && getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_BILL'') && $qualified_for_stock_change) {", "core/modules/modReception.class.php:289  //\"DELETE FROM \".MAIN_DB_PREFIX.\"const WHERE name IN (''STOCK_CALCULATE_ON_SUPPLIER_BILL'', ...) AND enti"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_SUPPLIER_DISPATCH_ORDER', 'string', NULL, 'product', 'Decrements/increments stock at the time a supplier order dispatch (stock allocation) is performed, rather than at another stock-triggering event.', 'Deleted via admin/stock.php:100 dolibarr_del_const (see comment at line 261), set through the select at admin/stock.php:490, and checked with getDolGlobalString in fourn/class/fournisseur.commande.class.php:2416 and fourn/commande/dispatch.php (lines 453, 501).', 'When active, stock is recalculated at supplier order dispatch time; the DELETE comment in modReception.class.php confirms it is one of several mutually exclusive STOCK_CALCULATE_ON_* triggers.', NULL, 0, 0, 'admin/stock.php|admin/stock.php|admin/stock.php', 1, '594cc5b8f66b551d3f84efd32715da046ee4014921a954803a53c2d1956b8b15', 'v2', '2026-07-24T06:41:12+00:00', '["// STOCK_CALCULATE_ON_SUPPLIER_DISPATCH_ORDER", "if (!$error && $entrepot > 0 && isModEnabled(''stock'') && getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_DISPATCH_ORDER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER', 'string', NULL, 'fourn', 'Specifies the stock movement type triggered when a supplier order is validated/approved.', 'Configured via admin/stock.php:97 (deleted when reset) and :430 (select form). Checked in fourn/class/fournisseur.commande.class.php:1359, fourn/commande/card.php:1215, :1239, :2312, and product/stock/lib/replenishment.lib.php:123 to trigger stock changes on approval. Also referenced in modReception.class.php:289 as part of the stock calculation constant family.', 'When set, approving a supplier order triggers a stock movement of the specified type; when not set, no stock is moved on validation.', 'Not set = no stock movement on supplier order validation; numeric value = stock movement type to apply on validation.', 0, 0, 'admin/stock.php|admin/stock.php', 1, 'e42325ea54c3b2c6a63ce6f61f4a6ee174b3ea681df3dc5defa12ae8c011d324', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/class/fournisseur.commande.class.php:1359|check|if (!$error && $movetoapprovestatus && isModEnabled(''stock'') && getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER'')) {", "admin/stock.php:430|read|print $form->selectarray(\"STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER\", $arrval, getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER''));", "fourn/commande/card.php:1239|check|if (isModEnabled(''stock'') && getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER'') && $qualified_for_stock_change) {", "admin/stock.php:97|write|dolibarr_del_const($db, ''STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER'', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER_INCLUDE_DRAFT', 'string', NULL, 'product', 'When virtual stock is calculated on supplier order validation/approval, also include draft supplier orders in the count.', 'Checked in product/class/product.class.php:6602, nested inside the STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER branch (itself noted as changing stock ''on approval'', not on validation); same comment pattern as the customer-order equivalent: draft orders are excluded by default unless this option is on, in which case load_stats_commande_fournisseur(0, ''0'', 1) quantities are added.', 'Enabling it makes draft supplier orders contribute to the virtual stock figure, which otherwise ignores drafts entirely.', 'Boolean: unset/0 = draft supplier orders excluded (default behavior); 1 = draft supplier orders included in virtual stock.', 0, 0, NULL, 1, '9d02bbc7845c28bbe56cedc2b5476ee9803e8dfa98f2198d5bc1e9bdf06ed013', 'v2', '2026-07-24T07:05:23+00:00', '["product/class/product.class.php:6601: } elseif (getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER'')) {\t// Warning: stock change \"on approval\", not on validation !", "product/class/product.class.php:6602: if (getDolGlobalString(''STOCK_CALCULATE_ON_SUPPLIER_VALIDATE_ORDER_INCLUDE_DRAFT'')) {\t// By default, draft means \"does not exist\", so we do not include them by default, except if option is on"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_VALIDATE_ORDER', 'string', NULL, 'commande', 'Triggers stock movements (decrease) when a customer order is validated.', 'Written (deleted) in admin/stock.php at line 91 and rendered as a select at line 325. Checked in commande/class/commande.class.php at lines 579, 713, and 919 with the condition getDolGlobalInt == 1. A phpdoc comment confirms: ''Warehouse ID to use for stock change (Used only if option STOCK_CALCULATE_ON_VALIDATE_ORDER is on)''.', 'Enabling this constant causes inventory to be decremented at order validation. It is mutually exclusive with other STOCK_CALCULATE_ON_* modes.', '0 or unset = no stock movement on order validation; 1 = stock decremented on order validation', 0, 0, 'admin/stock.php|admin/stock.php', 1, 'ac23ad57e7d9ac018d761ce57b8d3f9cb53c8c9b5c769bea3050d1bac51b4fd7', 'v2', '2026-04-21T11:16:15+00:00', '["@param\tint\t\t$idwarehouse\tWarehouse ID to use for stock change (Used only if option STOCK_CALCULATE_ON_VALIDATE_ORDER is on)", "if ($result >= 0 && isModEnabled(''stock'') && getDolGlobalInt(''STOCK_CALCULATE_ON_VALIDATE_ORDER'') == 1) {", "if (isModEnabled(''stock'') && getDolGlobalString(''STOCK_CALCULATE_ON_VALIDATE_ORDER'') && $qualified_for_stock_change) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_ON_VALIDATE_ORDER_INCLUDE_DRAFT', 'string', NULL, 'product', 'When virtual stock is calculated on customer order validation, also include draft (not-yet-validated) customer orders in the count.', 'Checked in product/class/product.class.php:6585, nested inside the STOCK_CALCULATE_ON_VALIDATE_ORDER branch; the inline comment states ''By default, draft means "does not exist", so we do not include them by default, except if option is on''. When active it adds quantities from draft orders via load_stats_commande(0, ''0'', 1).', 'Enabling it makes draft customer orders contribute to the virtual stock figure, which otherwise ignores drafts entirely.', 'Boolean: unset/0 = draft orders excluded (default behavior); 1 = draft orders included in virtual stock.', 0, 0, NULL, 1, '490ca4ecd600b81e250a86e9926f5b9f1b4b7639701c70585f2c993958d59281', 'v2', '2026-07-24T07:05:23+00:00', '["product/class/product.class.php:6585: if (getDolGlobalString(''STOCK_CALCULATE_ON_VALIDATE_ORDER_INCLUDE_DRAFT'')) {\t// By default, draft means \"does not exist\", so we do not include them by default, except if option is on"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CALCULATE_VIRTUAL_STOCK_TRANSVERSE_MODE', 'string', NULL, 'product', 'Switches virtual stock calculation to use the ''stock'' entity scope across all entities instead of the module-specific entity scope.', 'Checked in product/class/product.class.php at multiple points (lines 3655, 3810, 3871, 3951, 4011) and in product/stock/replenish.php (lines 457, 470, 484): when truthy and forVirtualStock is active, getEntity is called with ''stock'' instead of ''commande'', ''supplier_order'', ''expedition'', or ''mrp''.', 'Enabling this constant causes virtual stock queries to span all entities sharing the stock entity scope rather than being restricted to the per-module entity scope.', 'Truthy string (transverse/stock entity scope used) or empty/unset (module-specific entity scope used).', 1, 0, NULL, 1, 'b43c3f7d40c0e535f4f5fdcd47d6f2dbe04a3497c03e36f188dc618fb94df2a7', 'v2', '2026-04-21T13:29:58+00:00', '["product/class/product.class.php:3655|read|$sql .= \" AND c.entity IN (\".getEntity($forVirtualStock && getDolGlobalString(''STOCK_CALCULATE_VIRTUAL_STOCK_TRANSVERSE_MODE'') ? ''stock'' : ''commande'').\")\"", "product/class/product.class.php:3810|read|$sql .= \" AND c.entity IN (\".getEntity($forVirtualStock && getDolGlobalString(''STOCK_CALCULATE_VIRTUAL_STOCK_TRANSVERSE_MODE'') ? ''stock'' : ''supplier_order'').\")\"", "product/stock/replenish.php:457|read|$sqlCommandesCli .= \" WHERE c1.rowid = cd1.fk_commande AND c1.entity IN (\".getEntity(getDolGlobalString(''STOCK_CALCULATE_VIRTUAL_STOCK_TRANSVERSE_MODE'') ? ''stock'' : ''commande'').\")", "product/stock/replenish.php:484|read|$sqlCommandesFourn .= \" AND c3.entity IN (\".getEntity(getDolGlobalString(''STOCK_CALCULATE_VIRTUAL_STOCK_TRANSVERSE_MODE'') ? ''stock'' : ''supplier_order'').\")\""]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CONSUMPTION_FROM_MANUFACTURING_WAREHOUSE', 'string', NULL, 'mrp', 'Forces material consumption during production to use the warehouse assigned to the Manufacturing Order instead of a separately selected warehouse.', 'Checked in mrp/mo_production.php at lines 560, 1247, 1271, and 1531. A source comment states: ''When STOCK_CONSUMPTION_FROM_MANUFACTURING_WAREHOUSE is set, we always use the warehouse of the MO, the same than production.''', 'When enabled, the production consumption form ignores the per-line warehouse selector and always applies movements against the MO''s warehouse. When disabled, operators can choose a different warehouse per consumption line.', '0 or unset = operator selects warehouse per line; 1 = MO warehouse is always used for consumption', 1, 0, NULL, 1, '5adceb0cfda360823eac02a60f10c51a395713e5a3ef36b1bfc5e3218946b0a8', 'v2', '2026-04-21T11:16:15+00:00', '["// When STOCK_CONSUMPTION_FROM_MANUFACTURING_WAREHOUSE is set, we always use the warehouse of the MO, the same than production.", "if (getDolGlobalString(''STOCK_CONSUMPTION_FROM_MANUFACTURING_WAREHOUSE'') && $tmpwarehouse->id > 0) {", "if (!getDolGlobalString(''STOCK_CONSUMPTION_FROM_MANUFACTURING_WAREHOUSE'') || empty($tmpwarehouse->id)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_CORRECT_STOCK_IN_SHIPMENT', 'string', NULL, 'expedition', 'Shows a ''Correct stock'' quick link on the shipment dispatch screen when real stock is lower than the quantity being shipped.', 'Used once in expedition/shipment.php:806: when real stock ($product->stock_reel) is below the quantity to be shipped, a warning icon is shown, and if this constant is set, an additional link to product/stock/product.php with a pre-filled correction quantity is displayed.', 'Enabling it adds a convenience link letting the user jump directly to a stock correction screen (pre-filled with the missing quantity) from the shipment screen when stock is insufficient; it does not itself alter stock.', 'Boolean via getDolGlobalString: truthy shows the ''CorrectStock'' link.', 1, 0, NULL, 1, 'd7600f0fe891252d580b7713741eb0b9c226582ef237f034630e4438979a3e5c', 'v2', '2026-07-24T07:05:23+00:00', '["expedition/shipment.php:805: print '' '' . img_warning($langs->trans(\"StockTooLow\"));", "expedition/shipment.php:806: if (getDolGlobalString(''STOCK_CORRECT_STOCK_IN_SHIPMENT'')) {", "expedition/shipment.php:808: ...$langs->trans(\"CorrectStock\") . ''</a>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_DEFAULT_BATCH', 'string', NULL, 'product', 'Default lot/batch label used when creating missing product_batch records for a product that just had batch tracking activated.', 'In product/class/product.class.php:1547-1554, when batch management is turned on for a product that did not have it before, existing stock lines are migrated into product_batch; the placeholder batch label defaults to ''000000'' but is overridden by STOCK_DEFAULT_BATCH if set.', 'Changing it changes the label given to stock quantities that existed before batch tracking was enabled and have no real lot number.', 'Free-form string used as the lot/batch code; code default (when unset) is ''000000''.', 0, 0, NULL, 1, 'e8e757a803d7e6247d2bb19836b9dcfcb0026837f4597104ccb7ff6695c48b1e', 'v2', '2026-07-24T07:05:23+00:00', '["product/class/product.class.php:1549: $valueforundefinedlot = ''000000'';", "product/class/product.class.php:1550: if (getDolGlobalString(''STOCK_DEFAULT_BATCH'')) {", "product/class/product.class.php:1551: $valueforundefinedlot = getDolGlobalString(''STOCK_DEFAULT_BATCH'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_DETAIL_ON_WAREHOUSE', 'string', NULL, 'product', 'Enables per-warehouse stock detail columns in the product stock reassort list.', 'Checked in product/reassort.php at lines 448, 531, and 612. An inline TODO comment notes this feature should eventually move to product/list page field selection.', 'Enabling adds warehouse-level stock breakdown columns to the reassort view; disabling shows only aggregate stock.', 'Truthy value to show per-warehouse stock detail; absent or falsy to show aggregate only.', 1, 0, NULL, 1, 'c29b2d38a0cb25c32e86ae3e2022c184b84b309404684a72749d8977abbf7423', 'v2', '2026-04-21T13:29:58+00:00', '["product/reassort.php:531|check|if (getDolGlobalString(''STOCK_DETAIL_ON_WAREHOUSE'')) {\t// TODO This should be moved into the selection of fields on page product/list", "product/reassort.php:612|check|if (getDolGlobalString(''STOCK_DETAIL_ON_WAREHOUSE'')) {\t// TODO This should be moved into the selection of fields on page product/list", "product/reassort.php:448|check|if (getDolGlobalString(''STOCK_DETAIL_ON_WAREHOUSE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_DISABLE_OPTIM_LOAD', 'bool', NULL, 'product', 'Forces load_stock to run regardless of user stock permissions, overriding the default optimization that skips it.', 'When set, bypasses the permission check that normally gates the load_stock call in product/list.php:1738. Documented at product/list.php:1737 with the comment that this constant forces load_stock whatever the permissions on stock.', 'Disabling the optimization causes stock data to be loaded unconditionally on product lists, which increases database load but ensures stock information is always present.', 'Any truthy value forces load_stock; unset or empty uses permission-based optimization.', 1, 0, NULL, 1, '4ca83f52f90794b436d7186384001999debc218116563e42aea411e8f4940b5f', 'v2', '2026-04-21T13:29:58+00:00', '["product/list.php:1737  // STOCK_DISABLE_OPTIM_LOAD can be set to force load_stock whatever is permissions on stock.", "product/list.php:1738|check|if ((isModEnabled(''stock'') && $user->hasRight(''stock'', ''lire'') && $search_type != 1) || getDolGlobalString(''STOCK_DISABLE_OPTIM_LOAD'')) {\t// To optimize call of load_stock"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_DISALLOW_NEGATIVE_TRANSFER', 'bool', NULL, 'expedition', 'Prevents stock movements that would result in negative warehouse stock levels.', 'Configured via admin/stock.php:519 and checked in product/stock/class/mouvementstock.class.php:461, compta/facture/class/facture.class.php:3827, and expedition/card.php:2150. When enabled, stock transfers are blocked if the warehouse quantity would go below zero.', 'Enabling this setting blocks shipment and invoice stock deductions when available warehouse stock is zero or less, preventing negative inventory balances.', '0 = allow negative stock transfers; 1 = disallow negative stock transfers', 0, 0, 'admin/stock.php', 1, 'b6dfece096c41613353962cf185bedf89fd3a63f6ce68dd9792c1c0d3e5b2a9f', 'v2', '2026-04-21T11:16:15+00:00', '["admin/stock.php:519|read|print $form->selectarray(\"STOCK_DISALLOW_NEGATIVE_TRANSFER\", $arrval, getDolGlobalInt(''STOCK_DISALLOW_NEGATIVE_TRANSFER''));", "product/stock/class/mouvementstock.class.php:461|check|if ($movestock && $qty < 0 && getDolGlobalInt(''STOCK_DISALLOW_NEGATIVE_TRANSFER'')) {", "expedition/card.php:2150|check|if (getDolGlobalInt(''STOCK_DISALLOW_NEGATIVE_TRANSFER'')) {", "expedition/card.php:2334|check|if ($stock_warehouse->real > 0 || !getDolGlobalInt(''STOCK_DISALLOW_NEGATIVE_TRANSFER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_DO_WE_BILL_ORDER_OR_SHIPMENTECEPTION_FOR_VIRTUALSTOCK', 'string', NULL, 'product', 'Chooses whether virtual stock billing-based adjustments are computed from orders or from shipments/receptions.', 'Read in product/class/product.class.php:6579 with default ''order''; the comment at line 6577-6578 explains it is used to know how to make the virtual stock calculation when stock increases/decreases on billing (STOCK_CALCULATE_ON_BILL / STOCK_CALCULATE_ON_SUPPLIER_BILL branches at lines 6590-6611).', 'Switching between ''order'' and ''shipmentreception'' changes which quantities (ordered vs actually shipped/received) are subtracted or added to virtual stock when the corresponding *_ON_BILL options are active.', '''order'' = use order quantities (code default); ''shipmentreception'' = use shipment/reception quantities.', 0, 0, NULL, 1, '81bd7a52746f7542ec4fc950d10831b38c7a3be45eac8136faef13882275bb9b', 'v2', '2026-07-24T07:05:23+00:00', '["product/class/product.class.php:6577: // $weBillOrderOrShipmentReception is set to ''order'' or ''shipmentreception''. it will be used to know how to make virtual stock", "product/class/product.class.php:6579: $weBillOrderOrShipmentReception = getDolGlobalString(''STOCK_DO_WE_BILL_ORDER_OR_SHIPMENTECEPTION_FOR_VIRTUALSTOCK'', ''order'');", "product/class/product.class.php:6590: } elseif (getDolGlobalString(''STOCK_CALCULATE_ON_BILL'') && $weBillOrderOrShipmentReception == ''order'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_DRAFT_WATERMARK', 'string', NULL, 'core', 'Specifies the watermark text printed on PDF stock documents that are in draft status.', 'Checked and read at core/modules/stock/doc/pdf_standard_stock.modules.php:742–743. When the stock object is in draft status (statut == 0) and this constant is non-empty, pdf_watermark() is called with the constant''s value as the watermark text.', 'Setting a value causes draft stock PDFs to display that text as a watermark. Leaving it empty or unset disables the draft watermark feature.', 'String: watermark text to display (e.g. ''DRAFT''); empty/unset = no watermark on draft stock PDFs.', 1, 0, NULL, 1, '1f7166c6fdeb753fb32ba7495e3a022263cfc8a88cb5f1de44d9931d40e63cfe', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/stock/doc/pdf_standard_stock.modules.php:742|check|if ($object->statut == 0 && (getDolGlobalString(''STOCK_DRAFT_WATERMARK''))) {", "core/modules/stock/doc/pdf_standard_stock.modules.php:743|read|pdf_watermark($pdf, $outputlangs, $this->page_hauteur, $this->page_largeur, ''mm'', $conf->global->STOCK_DRAFT_WATERMARK);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_EXCLUDE_DISCOUNT_FOR_PMP', 'string', NULL, 'fourn', 'Excludes line discounts from the purchase price used for average weighted cost (PMP) calculation.', 'Documented in reception/dispatch.php:241: ''$price should take into account discount (except if option STOCK_EXCLUDE_DISCOUNT_FOR_PMP is on)''. Same comment in expedition/dispatch.php:341 and fourn/class/fournisseur.commande.class.php:2388. Checked in 5 occurrences across reception, expedition, and supplier order/invoice classes.', 'When enabled, discounts are excluded when computing the average cost price (PMP); when disabled (default), discounts reduce the price used for PMP calculation.', '0 or unset = discounts included in PMP calculation; non-empty = discounts excluded', 1, 0, NULL, 1, 'c3fcdbf3936d98b9a8b9c99fff2ddd9e32df0fab9f7536c30dab2c876a0aa057', 'v2', '2026-04-21T11:16:15+00:00', '["reception/dispatch.php:241  // $price should take into account discount (except if option STOCK_EXCLUDE_DISCOUNT_FOR_PMP is on)", "expedition/dispatch.php:341  // $price should take into account discount (except if option STOCK_EXCLUDE_DISCOUNT_FOR_PMP is on)", "fourn/class/fournisseur.commande.class.php:2388  // $price should take into account discount (except if option STOCK_EXCLUDE_DISCOUNT_FOR_PMP is on)", "reception/dispatch.php:684|check|if (!empty($objp->remise_percent) && !getDolGlobalString(''STOCK_EXCLUDE_DISCOUNT_FOR_PMP'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_EXCLUDE_VIRTUAL_PRODUCTS', 'string', NULL, 'expedition', 'Excludes kit/virtual products from stock management in shipment processing when set.', 'Read in expedition/class/expedition.class.php:1329 via getDolGlobalInt. The inline comment at line 1331 documents: ''If STOCK_EXCLUDE_VIRTUAL_PRODUCTS is set, we do not manage stock for kits/virtual products.'' No admin UI write is present.', 'Enabling this constant causes the shipment code to skip stock movements for virtual/kit products, which affects inventory accuracy for bundled items.', 'Truthy integer (e.g. 1) to exclude virtual products from stock management; 0 or unset to include them.', 1, 0, NULL, 1, '09fb82785222388cdfc6ca9527eaba0eead35f5a2858239d00395181d8e305c9', 'v2', '2026-04-21T13:50:40+00:00', '["expedition/class/expedition.class.php:1331  // If STOCK_EXCLUDE_VIRTUAL_PRODUCTS is set, we do not manage stock for kits/virtual products.", "expedition/class/expedition.class.php:1329|read||| ($isavirtualproduct && !getDolGlobalInt(''STOCK_EXCLUDE_VIRTUAL_PRODUCTS''))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_EXPEDITION_NO_MORE_THAN_ORDER', 'string', NULL, 'expedition', 'Prevents shipping lines from exceeding the ordered quantity on the corresponding order line.', 'Checked at expedition/class/expeditionligne.class.php:409 and :687. When truthy and a source order line (fk_elementdet) and expedition exist, the shipped quantity is validated against the ordered quantity.', 'Enabling enforces strict quantity control on shipments, preventing over-shipment. Disabling allows shipping more than ordered.', 'Truthy = block shipment quantities exceeding the order line quantity; empty/unset = no quantity cap enforced.', 1, 0, NULL, 1, '021d7e7ef865e334277616e7a39a9afb0bee2fcf0636f8579b2d951a1a2958ac', 'v2', '2026-04-21T13:50:40+00:00', '["expedition/class/expeditionligne.class.php:409|check|if (getDolGlobalString(''STOCK_EXPEDITION_NO_MORE_THAN_ORDER'') && !empty($this->fk_elementdet) && !empty($this->fk_expedition)) {", "expedition/class/expeditionligne.class.php:687|check|if (getDolGlobalString(''STOCK_EXPEDITION_NO_MORE_THAN_ORDER'') && !empty($this->fk_elementdet)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_INVENTORY_ADD_A_VALUE_DATE', 'string', NULL, 'product', 'Enables the ''date_inventory'' (DateValue) column/field on the stock inventory extrafields-like field list, which is otherwise disabled.', 'Used as the ''enabled'' condition string ''getDolGlobalInt("STOCK_INVENTORY_ADD_A_VALUE_DATE")'' for the date_inventory field definition in product/inventory/class/inventory.class.php:99; the inline comment states the date field is not used so it is disabled by default.', 'When set to a truthy int, the DateValue field becomes visible/usable on inventory records; otherwise it stays hidden as per the code comment.', 'Not set/0 (default): DateValue field disabled/hidden (''This date is not used so disabled by default''). Truthy int: field enabled.', 1, 0, NULL, 1, '0809cb31b6fcb2e30ae9423f7ecdfb4dc2bb5c4d2da594f06731904ff4c4ede7', 'v2', '2026-07-24T07:05:23+00:00', '["product/inventory/class/inventory.class.php:99|read|''date_inventory'' => array(... ''enabled'' => ''getDolGlobalInt(\"STOCK_INVENTORY_ADD_A_VALUE_DATE\")'', ...),\t// This date is not used so disabled by default."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_MOVEMENT_INTO_PROJECT_OVERVIEW', 'string', NULL, 'projet', 'Enables display of stock movement data on the project elements overview page and in project ODT documents.', 'Read at projet/element.php:754 and core/modules/project/doc/doc_generic_project_odt.modules.php:1032 as the ''test'' condition for including stock movement sections. 2 occurrences across 2 files.', 'When unset, stock movements are not shown in the project elements overview or ODT export. When set and the stock module is enabled, stock movements are included.', 'Truthy value = stock movements shown in project overview and ODT; empty/unset = hidden.', 1, 0, NULL, 1, '987c6b1c299c4cbeec47e357b2782e7ad0200b16a834f1fc86d747b326083afd', 'v2', '2026-04-21T11:16:15+00:00', '["projet/element.php:754|read|''test'' => isModEnabled(''stock'') && $user->hasRight(''stock'', ''mouvement'', ''lire'') && getDolGlobalString(''STOCK_MOVEMENT_INTO_PROJECT_OVERVIEW'')", "core/modules/project/doc/doc_generic_project_odt.modules.php:1032|read|''test'' => (isModEnabled(''stock'') && $user->hasRight(''stock'', ''mouvement'', ''lire'') && getDolGlobalString(''STOCK_MOVEMENT_INTO_PROJECT_OVERVIEW''))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_MOVEMENT_LIST_HIDE_UNIT_PRICE', 'bool', NULL, 'product', 'Hides the unit purchase value (price) column from the stock movement list page.', 'Read in product/stock/movement_list.php:154, negated to set the ''enabled'' flag of the ''m.price'' (UnitPurchaseValue) column definition in the list''s $arrayfields configuration.', 'Enabling it removes the unit purchase value column from being selectable/shown in the stock movement list; unset/0 leaves the column selectable as normal (still unchecked by default).', 'Boolean-like: enabled = hide UnitPurchaseValue column entirely; unset/0 = column available (unchecked by default, ''checked'' => ''0'').', 0, 0, NULL, 1, 'a977f495f40c5419719f57a7de6e6fc1591e703eed033e483d7b9253b34fc501', 'v2', '2026-07-24T07:05:23+00:00', '["product/stock/movement_list.php:154: ''m.price'' => array(''label'' => \"UnitPurchaseValue\", ''checked'' => ''0'', ''position'' => 210, ''enabled'' => (string) (int) (!getDolGlobalInt(''STOCK_MOVEMENT_LIST_HIDE_UNIT_PRICE'')))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_MUST_BE_ENOUGH_FOR_INVOICE', 'string', NULL, 'compta', 'Requires sufficient stock to be available before an invoice line can trigger a stock movement.', 'Configured via admin/stock.php:533 and checked in compta/facture/class/facture.class.php:4307 and :4659. When set and the product is stock-managed, the system verifies adequate stock before allowing the invoice stock deduction.', 'When enabled, invoicing a stock-managed product without sufficient available stock will be blocked or trigger an error.', 'Empty/0 = no stock check enforced; truthy = stock must be sufficient before invoice stock deduction', 0, 0, 'admin/stock.php', 1, 'f68315203c434e536c0c91dca74696e1880741f96192745b3d43ba43641b4115', 'v2', '2026-04-21T11:16:15+00:00', '["admin/stock.php:533|read|print $form->selectarray(\"STOCK_MUST_BE_ENOUGH_FOR_INVOICE\", $arrval, getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_INVOICE''));", "compta/facture/class/facture.class.php:4307|check|if (getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_INVOICE'') && $product->isStockManaged()) {", "compta/facture/class/facture.class.php:4659|check|if (getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_INVOICE'') && $product->isStockManaged()) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_MUST_BE_ENOUGH_FOR_ORDER', 'string', NULL, 'commande', 'Requires sufficient stock before a sales order can be validated, blocking orders when stock is insufficient for managed products.', 'When set, order validation checks stock levels for managed products at commande/class/commande.class.php:1680 and :3238. Configurable via admin/stock.php using a select array.', 'If enabled, orders for products with insufficient stock will be blocked at validation time. Disabling allows orders regardless of available stock.', 'Empty = no stock check enforced; non-empty truthy value = stock must be sufficient for order validation', 0, 0, 'admin/stock.php', 1, '5ec833ea401ca8b646a11ce8710cf0dd7e97178a1c37e35c91eddad8b9201c32', 'v2', '2026-04-21T13:50:40+00:00', '["commande/class/commande.class.php:1680|check|if (getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_ORDER'') && $product->isStockManaged()) {", "commande/class/commande.class.php:3238|check|if (getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_ORDER'') && $product->isStockManaged()) {", "admin/stock.php:547|read|print $form->selectarray(\"STOCK_MUST_BE_ENOUGH_FOR_ORDER\", $arrval, getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_ORDER''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_MUST_BE_ENOUGH_FOR_PROPOSAL', 'string', NULL, 'comm', 'Blocks adding a stock-managed product line to a commercial proposal when real stock is insufficient for the requested quantity.', 'Checked in comm/propal/class/propal.class.php:735 inside the add-line logic; when the product is stock-managed, stock_reel < requested qty, and this constant is set, the method returns -3 with error ''ErrorStockIsNotEnoughToAddProductOnProposal''.', 'Setting it to true prevents users from adding proposal lines for stock-managed products whose available quantity (stock_reel) is less than the requested quantity, returning an error instead.', 'Boolean-like: true/1 enforces the stock-sufficiency check on proposal lines.', 1, 0, NULL, 1, 'b145cc30c90722f62e0a93b6da3220f942f29c36aa5f0109994e85c7ce1eab69', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/class/propal.class.php:735|check|if ($product->isStockManaged() && $product->stock_reel < $qty && getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_PROPOSAL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_MUST_BE_ENOUGH_FOR_SHIPMENT', 'string', NULL, 'expedition', 'Controls whether sufficient stock is required before a shipment line can be added.', 'Checked in expedition/class/expedition.class.php at lines 1288 and 1561, and exposed in admin/stock.php via a select array (line 561). The inline comment at line 1242 states: ''If STOCK_MUST_BE_ENOUGH_FOR_SHIPMENT is not set, you can add a shipment line, even if not enough into stock''.', 'When set, the system enforces stock availability for shipment lines, blocking lines where stock is insufficient. When not set, shipment lines can be added regardless of stock levels.', 'Value from the configured select array in admin/stock.php; default (''0'' or unset) means no stock check enforced.', 0, 0, 'admin/stock.php', 1, '5bd70ca04075ebea105d1525f5670803fdfc1d868a21d0ef4f4848d1ce4f0126', 'v2', '2026-04-21T13:50:40+00:00', '["expedition/class/expedition.class.php:1242  * If STOCK_MUST_BE_ENOUGH_FOR_SHIPMENT is not set, you can add a shipment line, even if not enough into stock", "admin/stock.php:561|read|print $form->selectarray(\"STOCK_MUST_BE_ENOUGH_FOR_SHIPMENT\", $arrval, getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_SHIPMENT''));", "expedition/class/expedition.class.php:1288|check|if (getDolGlobalString(''STOCK_MUST_BE_ENOUGH_FOR_SHIPMENT'')) {", "expedition/class/expedition.class.php:1561|check|if (getDolGlobalString(\"STOCK_MUST_BE_ENOUGH_FOR_SHIPMENT\", ''0'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_REPLENISH_ADD_CHECKBOX_INCLUDE_DRAFT_ORDER', 'string', NULL, 'product', 'Adds an ''Include also draft orders'' checkbox to the stock replenishment list filter bar.', 'In product/stock/replenish.php:816, if this constant is truthy, a checkbox named ''draftorder'' with label ''IncludeAlsoDraftOrders'' is printed in the list header, pre-checked from $draftchecked.', 'Enabling it lets users filter the replenishment list to also include quantities from draft (unvalidated) purchase orders via a new checkbox.', 'Boolean-like flag (truthy shows the draft-order checkbox).', 1, 0, NULL, 1, '07df3476a4112ba870c93b4efd47d26f629a16fc48d31b4bb61628a4d56be171', 'v2', '2026-07-24T07:05:23+00:00', '["product/stock/replenish.php:816: if (getDolGlobalString(''STOCK_REPLENISH_ADD_CHECKBOX_INCLUDE_DRAFT_ORDER'')) {", "product/stock/replenish.php:817: print $langs->trans(''IncludeAlsoDraftOrders'').''&nbsp;<input type=\"checkbox\" id=\"draftorder\" name=\"draftorder\" ''.(!empty($draftchecked) ? $draftchecked : '''').''>'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_SHOW_ALL_BATCH_BY_DEFAULT', 'bool', NULL, 'product', 'Shows all batch/lot rows expanded by default in the warehouse stock view.', 'Read in product/stock/product.php:1132 and :1246. When set, batch rows are rendered visible by default; when not set, they are collapsed and a ''(+)'' toggle is shown.', 'Enabling this constant expands all batch detail rows on page load; disabling it collapses them, requiring user interaction to expand.', 'Non-empty = all batch rows visible by default; empty or unset = batch rows collapsed', 1, 0, NULL, 1, 'ff22029b3533a35361558c69e39fe2698e69134682a11f0e3007c924c2372da3', 'v2', '2026-04-21T13:29:58+00:00', '["product/stock/product.php:1132|read|print(!getDolGlobalString(''STOCK_SHOW_ALL_BATCH_BY_DEFAULT'') ? ''(+)'' : ''(-)'');", "product/stock/product.php:1246|read|print \"\\n\".''<tr style=\"display:''.(!getDolGlobalString(''STOCK_SHOW_ALL_BATCH_BY_DEFAULT'') ? ''none'' : ''visible'').''\" class=\"batch_warehouse''.$entrepotstatic->id.''\"><td class=\"left\">''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_SHOW_VIRTUAL_STOCK_IN_PRODUCTS_COMBO', 'bool', NULL, 'core', 'When enabled, shows virtual stock levels alongside physical stock in product combo/select lists.', 'Checked at core/class/html.form.class.php:3722 and :4312 inside product combo-generation functions. The comment at :3569 explicitly warns this is a ''slow option''. When the $novirtualstock parameter is empty AND this constant is set, virtual stock is loaded and displayed.', 'Enabling this option slows down combo list generation. Disabling it (or leaving unset) skips virtual stock loading and keeps combo rendering fast.', 'Truthy (non-empty/non-zero) = show virtual stock; empty/unset = do not show virtual stock.', 1, 0, NULL, 1, 'a2ac00c8a2630c46bf05b9f07d8c868d48ab3bdf13bff0484f69047d962126e6', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:3569  * @param int<0,1>\t$novirtualstock Do not load virtual stock, even if slow option STOCK_SHOW_VIRTUAL_STOCK_IN_PRODUCTS_COMBO is on.", "core/class/html.form.class.php:3722|check|if (empty($novirtualstock) && getDolGlobalString(''STOCK_SHOW_VIRTUAL_STOCK_IN_PRODUCTS_COMBO'')) {  // Warning, this option may slow down combo list generation"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_SUPPORTS_SERVICES', 'string', NULL, 'product', 'Enables stock tracking/management for service-type products, not only physical products.', 'Set through the select at admin/stock.php:875, and checked with getDolGlobalInt/getDolGlobalString in reception/class/reception.class.php:904, fourn/class/fournisseur.commande.class.php:3820, reception/dispatch.php:517, reception/card.php (multiple lines), and product/class/product.class.php:5602.', 'When enabled, service-type lines (product_type == 1) and their stock are treated as stockable in reception, dispatch, and stock-loading logic that would otherwise skip services.', NULL, 0, 0, 'admin/stock.php', 1, 'ccb902c79e1ee47ff41267209037f855bff61d8c69f4e853fa1bb5c530092c09', 'v2', '2026-07-24T06:41:12+00:00', '["if ($line->product_type == 1 && !getDolGlobalString(''STOCK_SUPPORTS_SERVICES'')) {", "if (empty($ignore_stock_load) && ($tmpproduct->isProduct() || getDolGlobalString(''STOCK_SUPPORTS_SERVICES''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_SUPPORT_SERVICES', 'string', NULL, 'product', 'Enables stock tracking/support-price permission checks to also apply to services, not just physical products.', 'Read in product/stock/movement_list.php:168-174, where it changes which advanced permission (product-only vs product+service) is checked for $usercanreadsupplierprice, and in bom/tpl/objectline_create.tpl.php:62 to gate behavior for ''contrat'' (contract) elements.', 'Enabling it extends supplier-price-read permission checks and related stock/BOM line behavior to services in addition to products; unset/0 restricts that logic to products only.', 'Boolean-like: enabled = treat services like products for the affected stock/permission logic; unset/0 = products only.', 0, 0, NULL, 1, 'b567eb2bb7fd6cbb9dbaad299d8a9378dc11d2907f71d1d969189533f5ca226d', 'v2', '2026-07-24T07:05:23+00:00', '["product/stock/movement_list.php:168: if (!getDolGlobalString(''STOCK_SUPPORT_SERVICES'')) { $usercanreadsupplierprice = ... hasRight(''product'', ''lire''); }", "product/stock/movement_list.php:172-173: } else { $usercanreadsupplierprice = ... hasRight(''product'', ''lire'') || $user->hasRight(''service'', ''lire''); }", "bom/tpl/objectline_create.tpl.php:62: if (!empty($object->element) && $object->element == ''contrat'' && !getDolGlobalString(''STOCK_SUPPORT_SERVICES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_UPDATE_AWP_EVEN_WHEN_ENTRY_PRICE_IS_NULL', 'string', NULL, 'product', 'Allows the weighted average price (AWP/PMP) of a product to be recalculated on a stock increase even when the entry price is 0, for supplier-order/supplier-invoice originated movements.', 'Read in MouvementStock (product/stock/class/mouvementstock.class.php:583) as part of the condition deciding whether to recompute newpmp on a stock-increase movement (type 0 or 3); normally a zero price is treated as ''do not update AWP'', but this option relaxes that for origin_type ''order_supplier'' or ''invoice_supplier''.', 'Enabling it means a stock entry with price=0 coming from a supplier order/invoice will still be factored into the AWP calculation, potentially averaging in a zero price for that origin; without it, zero-price supplier entries are skipped for AWP purposes (comment: PMP should always be >0, calculated on input).', 'Boolean-like: enabled = recompute AWP even with price=0 for order_supplier/invoice_supplier origin; unset/0 = skip AWP recompute when price is 0 (default).', 0, 0, NULL, 1, 'd162225bd896c8dd1941c5885a050dea9d5d46ae535608135a46aaba3f3d45a0', 'v2', '2026-07-24T07:05:23+00:00', '["product/stock/class/mouvementstock.class.php:583: if ($price > 0 || (getDolGlobalString(''STOCK_UPDATE_AWP_EVEN_WHEN_ENTRY_PRICE_IS_NULL'') && $price == 0 && in_array($this->origin_type, array(''order_supplier'', ''invoice_supplier''))))", "product/stock/class/mouvementstock.class.php:585: // Note: Price should always be >0 or 0. PMP should be always >0 (calculated on input)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_USERSTOCK_AUTOCREATE', 'string', NULL, 'admin', 'Controls automatic creation of a personal warehouse for a user when MAIN_DEFAULT_WAREHOUSE_USER is also set.', 'When both MAIN_DEFAULT_WAREHOUSE_USER and STOCK_USERSTOCK_AUTOCREATE are set, user/class/user.class.php:1909 auto-creates the user''s personal stock warehouse. Configurable via admin/stock.php.', 'Enabling auto-creation ensures each user has a personal warehouse created automatically; disabling requires manual warehouse assignment.', 'Empty = no auto-creation; non-empty = automatically create user warehouse when MAIN_DEFAULT_WAREHOUSE_USER is set', 0, 0, 'admin/stock.php', 1, 'ec7791809e1c73481d9646d12dc7683a3b9ca49807b142268f496fb00990f594', 'v2', '2026-04-21T13:50:40+00:00', '["user/class/user.class.php:1909|check|if (getDolGlobalString(''MAIN_DEFAULT_WAREHOUSE_USER'') && getDolGlobalString(''STOCK_USERSTOCK_AUTOCREATE'')) {", "admin/stock.php:810|read|print $form->selectarray(\"STOCK_USERSTOCK_AUTOCREATE\", $arrval, getDolGlobalString(''STOCK_USERSTOCK_AUTOCREATE''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_USE_REAL_STOCK_BY_DEFAULT_FOR_REPLENISHMENT', 'bool', NULL, 'admin', 'Sets whether replenishment calculations use real (physical) stock or virtual stock by default.', 'Set through the select at admin/stock.php:598, and read at product/stock/replenish.php:134 where it determines $usevirtualstock (inverted: enabling real stock sets $usevirtualstock to 0).', 'When enabled, the replenishment page defaults to using real stock quantities ($usevirtualstock = 0) instead of virtual stock ($usevirtualstock = 1).', NULL, 0, 0, 'admin/stock.php', 1, '60b663e659d6958cd0c922bb3fcdb41d420baa49f0bfdea55b09d70221219ade', 'v2', '2026-07-24T06:41:12+00:00', '["$usevirtualstock = getDolGlobalString(''STOCK_USE_REAL_STOCK_BY_DEFAULT_FOR_REPLENISHMENT'') ? 0 : 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_USE_WAREHOUSE_BY_USER', 'bool', NULL, 'core', 'Would show a per-user ''Users'' stock tab on the warehouse product card, but the feature is disabled/never finished.', 'In core/lib/stock.lib.php:59 the whole block is wrapped in a PHP comment: ''Disabled because will never be implemented. Table always empty. Should not be enabled by default because does not work yet correctly because personal stocks are not tagged into table llx_entrepot.'' The code checking getDolGlobalString(''STOCK_USE_WAREHOUSE_BY_USER'') is dead/commented-out code.', 'Setting this constant currently has no effect since the code path that reads it is commented out in the source.', 'Not applicable: the reading code is disabled (wrapped in a /* ... */ comment) in this version of Dolibarr.', 1, 0, NULL, 1, 'e51c5fd9d3ef61ef134012555173ee55e9cd338e2817a937d0edc22c7017ed15', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/stock.lib.php: /* Disabled because will never be implemented. Table always empty.", "core/lib/stock.lib.php:59: if (getDolGlobalString(''STOCK_USE_WAREHOUSE_BY_USER'')) {", "core/lib/stock.lib.php: Should not be enabled by default because does not work yet correctly because personal stocks are not tagged into table llx_entrepot."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_USE_WAREHOUSE_USAGE', 'bool', NULL, 'product', 'Enables the warehouse_usage field on warehouse records to classify warehouse purpose.', 'Checked via getDolGlobalInt at product/stock/card.php:532 and used as the ''enabled'' condition for the ''warehouse_usage'' field definition in product/stock/class/entrepot.class.php:191.', 'Enabling this constant activates the warehouse usage/classification field in the warehouse entity; disabling it hides that field.', '0 or empty = warehouse_usage field disabled; any non-zero integer = warehouse_usage field enabled', 1, 0, NULL, 1, 'fa4705796cdf7af461029ccad31cbe30b2ed1c5800b2825d419a14525535e32c', 'v2', '2026-04-21T13:29:58+00:00', '["product/stock/card.php:532|check|if (getDolGlobalInt(\"STOCK_USE_WAREHOUSE_USAGE\")) {", "product/stock/class/entrepot.class.php:191|read|''warehouse_usage'' => array(''type'' => ''integer'', ''label'' => ''WarehouseUsage'', ''enabled'' => ''getDolGlobalInt(\"STOCK_USE_WAREHOUSE_USAGE\")'', ''visible'' => 1, ''position'' => 400, ''defaul"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_WAREHOUSE_NOT_REQUIRED_FOR_RECEPTIONS', 'bool', NULL, 'reception', 'Allows adding a reception line without specifying a warehouse (stock source).', 'Documented directly in the code comment at reception/class/reception.class.php:949: ''If STOCK_WAREHOUSE_NOT_REQUIRED_FOR_RECEPTIONS is set, you can add a reception line, with no stock source defined''. Enforced by the check at line 985.', 'When set, reception lines can be created/validated even if no warehouse (entrepot_id) was chosen, bypassing the normal warehouse requirement.', 'Boolean-like; when truthy, disables the warehouse-required check for reception lines.', 1, 0, NULL, 1, 'd0f8029e81c0aefb3daa940daae63e0cf3ee416902ceda156b44fbb09570d046', 'v2', '2026-07-24T07:05:23+00:00', '["reception/class/reception.class.php:949: * If STOCK_WAREHOUSE_NOT_REQUIRED_FOR_RECEPTIONS is set, you can add a reception line, with no stock source defined", "reception/class/reception.class.php:985: if (!($entrepot_id > 0) && !getDolGlobalInt(''STOCK_WAREHOUSE_NOT_REQUIRED_FOR_RECEPTIONS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STOCK_WAREHOUSE_NOT_REQUIRED_FOR_SHIPMENTS', 'bool', NULL, 'expedition', 'Allows shipment lines to be saved without a source warehouse when enabled.', 'Checked in expedition/class/expedition.class.php:1282. The inline comment at line 1241 documents the behavior: ''If STOCK_WAREHOUSE_NOT_REQUIRED_FOR_SHIPMENTS is set, you can add a shipment line, with no stock source defined''. No admin UI write is present.', 'Enabling this constant removes the warehouse validation requirement for shipment lines, allowing shipments without a defined source warehouse.', 'Truthy value (e.g. 1) to skip warehouse requirement; empty or 0 to require a warehouse.', 1, 0, NULL, 1, '00f6c8446698f6b2d0a40b88a47059578681d3af59e1c35391cd1fd2352aa582', 'v2', '2026-04-21T13:50:40+00:00', '["expedition/class/expedition.class.php:1241  * If STOCK_WAREHOUSE_NOT_REQUIRED_FOR_SHIPMENTS is set, you can add a shipment line, with no stock source defined", "expedition/class/expedition.class.php:1282|check|if (!($entrepot_id > 0) && !getDolGlobalString(''STOCK_WAREHOUSE_NOT_REQUIRED_FOR_SHIPMENTS'') && !(getDolGlobalString(''SHIPMENT_SUPPORTS_SERVICES'') && $line->product_type == Product"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPECONNECT_PRINCIPAL', 'string', NULL, 'stripe', 'Entity ID of the principal (main) entity in a Stripe Connect multi-entity setup, used to decide when to charge an application fee.', 'Used in stripe/class/stripe.class.php:570 when building the Stripe PaymentIntent: the application fee is only added if the current entity is not the one designated as principal.', 'If set to the current entity''s ID, no Stripe application fee is charged for payments made from that entity; if set to another entity''s ID (or left unset, defaulting to 0), the fee is applied whenever $stripefee > 0.', 'Integer entity ID of the principal entity in a Stripe Connect setup.', 1, 0, NULL, 1, 'e0167116db92c61d312594c25d12adf98b60632339fbfe7d8dd7e92f192c248e', 'v2', '2026-07-24T07:05:23+00:00', '["stripe/class/stripe.class.php:570: if ($conf->entity != getDolGlobalInt(''STRIPECONNECT_PRINCIPAL'') && $stripefee > 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_ALLOW_LOCAL_CARD', 'bool', NULL, 'societe', 'Enables display and management of locally-stored (non-Stripe-remote) credit card payment sources on the thirdparty payment modes page.', 'Checked 3 times in societe/paymentmodes.php (lines 1215, 1246, 1510) to decide whether to show the ''Add'' button for local cards, whether to list local card sources from societe_rib, and to size the results table colspan accordingly.', 'When enabled, users can add and see locally stored card records in addition to remote Stripe-registered cards; when disabled only remote Stripe cards are shown.', 'Boolean: true/1 shows local card add button and local card sources; false/unset hides them.', 1, 0, NULL, 1, '5a9e22c8d3110c449443d38e7f8bd2b8e54c7101b7f9f3cb304de5d167373fe5', 'v2', '2026-07-24T07:05:23+00:00', '["societe/paymentmodes.php:1215|check|if (getDolGlobalString(''STRIPE_ALLOW_LOCAL_CARD'')) {", "societe/paymentmodes.php:1510|read|$colspan = (getDolGlobalString(''STRIPE_ALLOW_LOCAL_CARD'') ? 10 : 9);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_APPLICATION_FEE', 'string', NULL, 'stripe', 'Sets a fixed monetary application fee added to Stripe payment transactions.', 'Displayed in stripe/admin/stripe.php:320 and used in stripe/class/stripe.class.php:408 in the fee formula alongside the percentage fee. Admin UI available at stripe/admin/stripe.php.', 'Changing this value directly changes the fixed component of the computed Stripe application fee for each transaction.', 'Numeric monetary amount in the account currency (e.g. ''0.30''); 0 or unset = no fixed fee.', 0, 0, 'stripe/admin/stripe.php', 1, '9dccc43fba23119b47c9c1d8c6172642189fe12f3b0bd2e2031920c5feef77ab', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:320|read|print price(getDolGlobalString(''STRIPE_APPLICATION_FEE''));", "stripe/class/stripe.class.php:408|read|$fee = $amount * ((float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_PERCENT\", ''0'') / 100) + (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE\", ''0'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_APPLICATION_FEE_MAXIMAL', 'string', NULL, 'stripe', 'Sets the maximum application fee (in currency units) charged on a Stripe payment via Dolibarr''s Stripe Connect integration.', 'Read multiple times in stripe/class/stripe.class.php:410-413; the computed $fee (from STRIPE_APPLICATION_FEE_PERCENT/STRIPE_APPLICATION_FEE) is capped at this value if it exceeds it and if the maximal exceeds STRIPE_APPLICATION_FEE_MINIMAL.', 'When set higher than STRIPE_APPLICATION_FEE_MINIMAL, it caps the computed Stripe application fee at this amount; if unset (defaults to ''0''), the cap logic effectively does not raise the fee ceiling above 0 relative to the minimal check.', 'Float/string numeric value: maximum fee amount, default ''0''.', 1, 0, NULL, 1, 'b8207e3bb0c31761576b565b758b18b1c7f2241a027039151991e35a3906fa70', 'v2', '2026-07-24T07:05:23+00:00', '["stripe/class/stripe.class.php:410|check|if ($fee >= (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_MAXIMAL\", ''0'') && (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_MAXIMAL\", ''0'') > (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_MINIMAL\", ''0'')) {", "stripe/class/stripe.class.php:411|read|$fee = (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_MAXIMAL\", ''0'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_APPLICATION_FEE_MINIMAL', 'string', NULL, 'stripe', 'Sets a minimum monetary floor for the computed Stripe application fee.', 'Read in stripe/class/stripe.class.php:412-413 and displayed in stripe/admin/stripe.php:321. If the computed fee falls below this value, the fee is set to this minimum. Admin UI is available at stripe/admin/stripe.php.', 'Setting a minimal fee ensures the application fee is never below the configured floor, regardless of transaction amount.', 'Numeric monetary amount in the account currency; 0 or unset = no minimum floor applied.', 0, 0, 'stripe/admin/stripe.php', 1, '7f2e0efeb5d1c1987969deba897a7c0f47f1fb72eb9fadf419317e56032f493c', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:321|read|print '' ''.$langs->getCurrencySymbol(getDolCurrency()).'' ''.$langs->trans(\"minimum\").'' ''.price(getDolGlobalString(''STRIPE_APPLICATION_FEE_MINIMAL''))...", "stripe/class/stripe.class.php:412|read|} elseif ($fee < (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_MINIMAL\", ''0'')) {", "stripe/class/stripe.class.php:413|read|$fee = (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_MINIMAL\", ''0'');", "stripe/class/stripe.class.php:410|check|if ($fee >= (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_MAXIMAL\", ''0'') && (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_MAXIMAL\", ''0'') > (float) getDolGlobalString(\"STR..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_APPLICATION_FEE_PERCENT', 'string', NULL, 'stripe', 'Sets the percentage-based application fee deducted from Stripe payments.', 'Displayed in stripe/admin/stripe.php:318 and used in stripe/class/stripe.class.php:408 in the formula: fee = amount * (STRIPE_APPLICATION_FEE_PERCENT / 100) + STRIPE_APPLICATION_FEE. Admin UI available at stripe/admin/stripe.php.', 'Changing the percentage directly changes the application fee computed for each Stripe transaction; combined with the fixed fee and bounded by minimal/maximal constants.', 'Decimal number representing a percentage (e.g. ''2.5'' = 2.5%); 0 or unset = no percentage fee.', 0, 0, 'stripe/admin/stripe.php', 1, '205f498d72e6881cc5662d69ca1b46c174878583dad1d6fb76b76386e4d899cf', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:318|read|print price(getDolGlobalString(''STRIPE_APPLICATION_FEE_PERCENT''));", "stripe/class/stripe.class.php:408|read|$fee = $amount * ((float) getDolGlobalString(\"STRIPE_APPLICATION_FEE_PERCENT\", ''0'') / 100) + (float) getDolGlobalString(\"STRIPE_APPLICATION_FEE\", ''0'');", "stripe/class/stripe.class.php:407|check|if (getDolGlobalString(\"STRIPE_APPLICATION_FEE_PERCENT\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_AUTO_RECORD_PAYOUT', 'string', NULL, 'stripe', 'Enables automatic recording of Stripe payout events (payout.created and payout.paid) received via webhook.', 'Configured via stripe/admin/stripe.php:630. The payout.create and payout.paid webhook hooks are registered as active only when this constant is truthy (stripe/admin/stripe.php:47-48). Processing occurs in public/stripe/ipn.php:207 and :253.', 'Enabling this causes Dolibarr to automatically record bank payout entries when Stripe sends payout webhook events; disabling it means those events are ignored.', '0 = payout auto-recording disabled; truthy = payout.created and payout.paid webhooks are processed and recorded', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '02b3b447355580e6b460f068bce89b4d607f3ea105c50249e3caddd04d7b52c9', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:47|read|$listofsupportedhooks[] = array(''code'' => ''payout.create'', ''status'' => getDolGlobalString(''STRIPE_AUTO_RECORD_PAYOUT'') ? 1 : 0);", "stripe/admin/stripe.php:48|read|$listofsupportedhooks[] = array(''code'' => ''payout.paid'', ''status'' => getDolGlobalString(''STRIPE_AUTO_RECORD_PAYOUT'') ? 1 : 0);", "public/stripe/ipn.php:207|check|if ($event->type == ''payout.created'' && getDolGlobalString(''STRIPE_AUTO_RECORD_PAYOUT'')) {", "public/stripe/ipn.php:253|read|} elseif ($event->type == ''payout.paid'' && getDolGlobalString(''STRIPE_AUTO_RECORD_PAYOUT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_AUTO_RECORD_PAYOUT_LABEL', 'string', NULL, 'public', 'Custom label text used for bank transfer records auto-created when a Stripe payout is recorded via IPN.', 'Used in public/stripe/ipn.php:266 as the label suffix appended to the event description when Dolibarr auto-records a bank transfer for a Stripe payout notification.', 'Setting it changes the label text stored on the auto-created bank transfer/payment record; if unset, the default fallback text ''autorecord by IPN, see Stripe setup'' is used.', 'String: free-text label. Default fallback (if constant unset): ''autorecord by IPN, see Stripe setup''.', 1, 0, NULL, 1, 'd43c8fa5040e37277c4600722cd4473a6429f349fa52013cef5f1479295fdd12', 'v2', '2026-07-24T07:05:23+00:00', '["public/stripe/ipn.php:266|read|$label = $event->data->object->description.'' - ''.getDolGlobalString(''STRIPE_AUTO_RECORD_PAYOUT_LABEL'', ''autorecord by IPN, see Stripe setup'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_BANCONTACT', 'string', NULL, 'stripe', 'Enables the Bancontact payment method option in Stripe payment processing.', 'Selected via admin UI at stripe/admin/stripe.php:527 and checked in stripe/class/stripe.class.php:493 and :768 to include Bancontact as a payment method type.', 'Enabling this adds Bancontact to the list of Stripe payment method types offered during checkout.', '0 or unset = Bancontact disabled; truthy value = Bancontact enabled.', 0, 0, 'stripe/admin/stripe.php', 1, 'e3cfb33df680e1f42a126e59491be29acad7329b11849685cd8a8176c86eb766', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:527|read|print $form->selectarray(\"STRIPE_BANCONTACT\", $arrval, $conf->global->STRIPE_BANCONTACT);", "stripe/class/stripe.class.php:493|check|if (getDolGlobalInt(''STRIPE_BANCONTACT'')) {", "stripe/class/stripe.class.php:768|check|if (getDolGlobalString(''STRIPE_BANCONTACT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_BANK_ACCOUNT_FOR_BANKTRANSFERS', 'string', NULL, 'stripe', 'Specifies the Dolibarr bank account ID used as the destination account when recording Stripe bank transfer payouts.', 'Configured via stripe/admin/stripe.php:127. Used in public/stripe/ipn.php:275 to fetch the destination account for bank transfer IPN events.', 'Setting this to the correct bank account ensures Stripe payout transfers are booked to the right Dolibarr account; leaving it unset will cause the account fetch to fail.', 'Integer ID of a Dolibarr bank account', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '1c3f2f762687bda48b1560bf9f4e3de9c4b9fab655bd32b437367b3e2d60158c', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:127|write|$result = dolibarr_set_const($db, \"STRIPE_BANK_ACCOUNT_FOR_BANKTRANSFERS\", GETPOSTINT(''STRIPE_BANK_ACCOUNT_FOR_BANKTRANSFERS''), ''chaine'', 0, '''', $conf->entity);", "stripe/admin/stripe.php:643|read|$form->select_comptes(getDolGlobalString(''STRIPE_BANK_ACCOUNT_FOR_BANKTRANSFERS''), ''STRIPE_BANK_ACCOUNT_FOR_BANKTRANSFERS'', 0, '''', 1);", "public/stripe/ipn.php:275|read|$accountto->fetch(getDolGlobalInt(''STRIPE_BANK_ACCOUNT_FOR_BANKTRANSFERS''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_BANK_ACCOUNT_FOR_PAYMENTS', 'string', NULL, 'public', 'Specifies the Dolibarr bank account ID used to record incoming Stripe payments and SEPA transactions.', 'Configured via stripe/admin/stripe.php:119 and used in public/stripe/ipn.php:605, :272, :1198 and core/class/commoninvoice.class.php:1714. A comment at commoninvoice.class.php:1714 states: ''Bank account used for SEPA direct debit or credit transfer. Must be the Stripe account in Dolibarr.''', 'Setting this to the correct bank account ID ensures Stripe payment receipts and SEPA operations are recorded against the right Dolibarr account; an incorrect ID will misdirect payment entries.', 'Integer ID of a Dolibarr bank account', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '02cf44513c942aadff37074aab0cfd223ffeafb71b6724aeeb58a50e5d8d560d', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/commoninvoice.class.php:1714|read|$fk_bank_account = getDolGlobalInt(''STRIPE_BANK_ACCOUNT_FOR_PAYMENTS'');\t\t// Bank account used for SEPA direct debit or credit transfer. Must be the Stripe account in Dolibarr.", "stripe/admin/stripe.php:119|write|$result = dolibarr_set_const($db, \"STRIPE_BANK_ACCOUNT_FOR_PAYMENTS\", GETPOSTINT(''STRIPE_BANK_ACCOUNT_FOR_PAYMENTS''), ''chaine'', 0, '''', $conf->entity);", "public/stripe/ipn.php:605|read|$bankaccountid = getDolGlobalInt(\"STRIPE_BANK_ACCOUNT_FOR_PAYMENTS\");", "public/stripe/ipn.php:1198|read|$accountfrom->fetch(getDolGlobalInt(''STRIPE_BANK_ACCOUNT_FOR_PAYMENTS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_CARD_PRESENT', 'string', NULL, 'stripe', 'Enables Stripe card-present (in-person/terminal) payment mode for point-of-sale integration.', 'Checked across stripe/class/stripe.class.php, takepos/admin/terminal.php:251, takepos/pay.php:630 and :741 to activate terminal-specific payment flows. Selected in admin UI at stripe/admin/stripe.php:428 and takepos/admin/terminal.php.', 'Enabling this switches Stripe payment processing to terminal/card-present mode; online payment intent reuse is disabled when this flag is active.', '0 or unset = online payment mode; truthy value = card-present terminal mode.', 0, 0, 'takepos/admin/terminal.php|stripe/admin/stripe.php', 1, '5431a97c6fc7822268f58b3df0085111acb8b8c862ae5034ba6e28b11fe05564', 'v2', '2026-04-21T11:16:15+00:00', '["takepos/admin/terminal.php:251|check|if (isModEnabled(''stripe'') && getDolGlobalString(''STRIPE_CARD_PRESENT'')) {", "stripe/admin/stripe.php:428|read|print $form->selectarray(\"STRIPE_CARD_PRESENT\", $arrval, $conf->global->STRIPE_CARD_PRESENT);", "stripe/class/stripe.class.php:506|check|if (getDolGlobalInt(''STRIPE_CARD_PRESENT'')) {", "stripe/class/stripe.class.php:557|check|if (getDolGlobalInt(''STRIPE_CARD_PRESENT'') && $mode == ''terminal'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_DEBUG', 'string', NULL, 'public', 'Enables debug logging of raw Stripe IPN payloads to a file.', 'Checked in public/stripe/ipn.php:121; when true, the raw IPN payload and HTTP_STRIPE_SIGNATURE header are written to DOL_DATA_ROOT/dolibarr_stripeipn_payload.log for troubleshooting.', 'Enabling it causes every Stripe IPN call to append its full payload to a log file on disk, which can grow large and may expose payment payload data to anyone with file access.', 'Boolean-like: any truthy value enables writing the IPN payload log; unset/false disables it.', 1, 0, NULL, 1, '0fc8e2f4891d9f40e86821e26ff413ac3b55b848f8f9a6dd86c428dceab18112', 'v2', '2026-07-24T07:05:23+00:00', '["public/stripe/ipn.php:121|check|if (getDolGlobalString(''STRIPE_DEBUG'')) {", "$fh = fopen(DOL_DATA_ROOT.''/dolibarr_stripeipn_payload.log'', ''w+'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_DELETE_STRIPE_ACCOUNT_WHEN_DELETING_THIRDPARTY', 'string', NULL, 'core', 'Controls whether the linked Stripe customer account is deleted when a third-party (Societe) is deleted.', 'Checked in core/triggers/interface_80_modStripe_Stripe.class.php:189 on the COMPANY_DELETE trigger; the surrounding comment states that by default the Stripe account is NOT deleted, to allow reuse (e.g. for thirdparty merges).', 'Setting it to true causes the associated Stripe customer object to be deleted via the Stripe API whenever the corresponding Dolibarr thirdparty is deleted; leaving it unset preserves the Stripe customer for potential reuse.', 'Boolean-like: true/1 deletes the Stripe customer on thirdparty deletion; comment: ''By default, we do not delete the stripe account. We may need to reuse it with its payment_intent, for example if delete is for a merge of thirdparties.''', 1, 0, NULL, 1, '3ce9c20bb3aace70016811d2e2ff987b041d877b43612aefaa57509b4780e414', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_80_modStripe_Stripe.class.php:189|check|if (getDolGlobalString(''STRIPE_DELETE_STRIPE_ACCOUNT_WHEN_DELETING_THIRDPARTY'')) { // By default, we do not delete the stripe account..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_FORCE_VERSION', 'string', NULL, 'stripe', 'Forces the Stripe API version string sent to the Stripe PHP SDK, overriding the default hardcoded version.', 'Read in stripe/config.php:53, `\Stripe\Stripe::setApiVersion(getDolGlobalString(''STRIPE_FORCE_VERSION'', "2022-11-15"))`, with an inline comment ''force version API''.', 'Changing it changes which Stripe API version is used for all Stripe SDK calls, which can change request/response schemas and behavior versus Stripe''s default ''2022-11-15''.', 'String: a Stripe API version date string, e.g. ''2022-11-15'' (default if unset).', 1, 0, NULL, 1, 'f322414fcd4f5b39f1e6b0cf1b9838fed5b5539072fadc2b980b84d06f3b7b5b', 'v2', '2026-07-24T07:05:23+00:00', '["stripe/config.php:53|read|\\Stripe\\Stripe::setApiVersion(getDolGlobalString(''STRIPE_FORCE_VERSION'', \"2022-11-15\")); // force version API"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_GIROPAY', 'string', NULL, 'stripe', 'Enables the Giropay payment method option in Stripe payment processing.', 'Selected via admin UI at stripe/admin/stripe.php:555 and checked in stripe/class/stripe.class.php:499 and :551 to include Giropay as a payment method type.', 'Enabling this adds Giropay to the list of Stripe payment method types offered during checkout.', '0 or unset = Giropay disabled; truthy value = Giropay enabled.', 0, 0, 'stripe/admin/stripe.php', 1, '13b1c5ee65295dc6e925e2b7ea30e231989b4462164f4d2288acf2a32d78a081', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:555|read|print $form->selectarray(\"STRIPE_GIROPAY\", $arrval, $conf->global->STRIPE_GIROPAY);", "stripe/class/stripe.class.php:499|check|if (getDolGlobalInt(''STRIPE_GIROPAY'')) {", "stripe/class/stripe.class.php:551|check|if (getDolGlobalInt(''STRIPE_GIROPAY'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_IDEAL', 'string', NULL, 'stripe', 'Enables the iDEAL payment method as an option in Dolibarr''s Stripe payment integration.', 'Checked in stripe/class/stripe.class.php:774 and :497; when set, ''ideal'' is appended to the $paymentmethodtypes array alongside other methods like sepa_debit, bancontact, sofort, klarna, giropay.', 'When set, customers are offered the iDEAL payment method (in addition to whichever other STRIPE_* method flags are enabled) during Stripe checkout/payment.', 'Bool: truthy adds ''ideal'' to the list of accepted Stripe payment method types.', 1, 0, NULL, 1, '45f80676fa4d4c2bbd431c22f57ce912507bbfb70267f875fb7cc4daeb6b0e00', 'v2', '2026-07-24T07:05:23+00:00', '["stripe/class/stripe.class.php:774|check|if (getDolGlobalString(''STRIPE_IDEAL'')) { $paymentmethodtypes[] = \"ideal\"; }", "stripe/class/stripe.class.php:497|check|if (getDolGlobalInt(''STRIPE_IDEAL'')) { $paymentmethodtypes[] = \"ideal\"; }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_IPN_SEND_EMAIL_ON_DIRECT_DEBIT_CONFIRMATION', 'string', NULL, 'public', 'Enables sending a confirmation email using a named email template after a Stripe direct debit payment is confirmed via IPN.', 'Checked and read in public/stripe/ipn.php:692-696; when set, its string value is used directly as the email template label to load for the invoice payment success notification.', 'Setting it to a template code enables an automatic confirmation email after direct-debit IPN confirmation, but the code comment notes ''template must exist'' — if the named template is missing, the email will not be built correctly.', 'String: the code/label of an existing email template (example given in code: ''InvoicePaymentSuccess''). Empty/unset disables the email.', 1, 0, NULL, 1, '8d6634af16c84d50ce2902a9cd2c0f0b3d31f58c53767cfcb44c76596651d0c0', 'v2', '2026-07-24T07:05:23+00:00', '["public/stripe/ipn.php:692|check|if (getDolGlobalString(''STRIPE_IPN_SEND_EMAIL_ON_DIRECT_DEBIT_CONFIRMATION'')) {", "// If option to send email after confirmation of direct debit is on, we send the email (template must exists", "// Example: $labeltouse = ''InvoicePaymentSuccess'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_KLARNA', 'string', NULL, 'stripe', 'Enables the Klarna payment method option in Stripe payment processing.', 'Selected via admin UI at stripe/admin/stripe.php:514 and checked in stripe/class/stripe.class.php:490 and :554 to include Klarna as a payment method type.', 'Enabling this adds Klarna to the list of Stripe payment method types offered during checkout.', '0 or unset = Klarna disabled; truthy value = Klarna enabled.', 0, 0, 'stripe/admin/stripe.php', 1, '1a8da9b8c4269371d7e0ec725cb6ac8e554003fc183763c40b94697c831ac7e5', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:514|read|print $form->selectarray(\"STRIPE_KLARNA\", $arrval, $conf->global->STRIPE_KLARNA);", "stripe/class/stripe.class.php:490|check|if (getDolGlobalInt(''STRIPE_KLARNA'')) {", "stripe/class/stripe.class.php:554|check|if (getDolGlobalInt(''STRIPE_KLARNA'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_LIVE', 'string', NULL, 'stripe', 'Switches the Stripe payment integration between live (production) and sandbox (test) mode.', 'Configured via stripe/admin/stripe.php and takepos/admin/terminal.php. When set, live Stripe credentials and endpoints are used (stripe/admin/stripe.php:439); when unset, sandbox mode is active (stripe/admin/stripe.php:450). Read in 29 occurrences across stripe and payment modules.', 'Setting to live mode enables real payment processing; unsetting or setting to 0 keeps the integration in sandbox/test mode where no real charges are made.', '0 or unset = sandbox/test mode; non-empty = live/production mode', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|takepos/admin/terminal.php|takepos/admin/terminal.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '3c973fb117b2e72005efe1807aed5a40e1883e0896d9aa3289eef1f25d6b71a4', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:439|check|if (getDolGlobalString(''STRIPE_LIVE'')/* && !GETPOST(''forcesandbox'', ''alpha'') */) {", "stripe/admin/stripe.php:450|check|if (isModEnabled(''stripe'') && (!getDolGlobalString(''STRIPE_LIVE'')/* || GETPOST(''forcesandbox'', ''alpha'') */)) {", "stripe/admin/stripe.php:185|write|$res = dolibarr_set_const($db, \"STRIPE_LIVE\", $liveenable, ''yesno'', 0, '''', $conf->entity);", "stripe/admin/stripe.php:238|read|print $form->selectarray(\"STRIPE_LIVE\", $arrval, $conf->global->STRIPE_LIVE);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_LIVE_PUBLISHABLE_KEY', 'string', NULL, 'stripe', 'Stores the Stripe live-mode publishable API key used for client-side Stripe integration in production.', 'Configured via stripe/admin/stripe.php:98 and read at stripe/config.php:40. A commented-out line at stripe/admin/stripe.php:346 shows it was previously considered for security hashing: ''//$url .= ''?securitykey=''.dol_hash(''stripeipn-''.$dolibarr_main_instance_unique_id.''-''.getDolGlobalString(''STRIPE_LIVE_PUBLISHABLE_KEY''), ''md5'');''.', 'Setting a valid live publishable key enables client-side Stripe live-mode elements; an absent key disables them.', 'Empty/not set = Stripe live publishable key not configured; string starting with ''pk_live_' || ''' = valid Stripe live publishable key.', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '7950f676a46bcea811cf1550f24c3e1c00a1517b0873d626ecda27d41da6394a', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/config.php:40|read|\"publishable_key\" => getDolGlobalString(''STRIPE_LIVE_PUBLISHABLE_KEY'')", "stripe/admin/stripe.php:98|write|$result = dolibarr_set_const($db, \"STRIPE_LIVE_PUBLISHABLE_KEY\", GETPOST(''STRIPE_LIVE_PUBLISHABLE_KEY'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "stripe/admin/stripe.php:346  //$url .= ''?securitykey=''.dol_hash(''stripeipn-''.$dolibarr_main_instance_unique_id.''-''.getDolGlobalString(''STRIPE_LIVE_PUBLISHABLE_KEY''), ''md5'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_LIVE_SECRET_KEY', 'string', NULL, 'stripe', 'Stores the Stripe live-mode secret API key used to authenticate server-side Stripe API calls in production.', 'Configured via stripe/admin/stripe.php:102 and read at stripe/config.php:39 and stripe/admin/stripe.php:364, where it is passed to \Stripe\Stripe::setApiKey(). Used alongside STRIPE_LIVE_WEBHOOK_KEY and STRIPE_LIVE_WEBHOOK_ID.', 'Setting a valid live secret key enables Stripe live-mode payment processing; an invalid or absent key disables live Stripe integration.', 'Empty/not set = Stripe live mode not configured; string starting with ''sk_live_' || ''' = valid Stripe live secret key.', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, 'd14257aa67fb5a8d8ac8c5b2b078b94fe7ccca3b26d2cf7198799c157c6298c4', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/config.php:39|read|\"secret_key\"      => getDolGlobalString(''STRIPE_LIVE_SECRET_KEY''),", "stripe/admin/stripe.php:364|read|\\Stripe\\Stripe::setApiKey(getDolGlobalString(''STRIPE_LIVE_SECRET_KEY''));", "stripe/admin/stripe.php:361|check|if (getDolGlobalString(''STRIPE_LIVE_WEBHOOK_KEY'') && getDolGlobalString(''STRIPE_LIVE_SECRET_KEY'') && getDolGlobalString(''STRIPE_LIVE_WEBHOOK_ID'')) {", "stripe/admin/stripe.php:102|write|$result = dolibarr_set_const($db, \"STRIPE_LIVE_SECRET_KEY\", GETPOST(''STRIPE_LIVE_SECRET_KEY'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_LIVE_WEBHOOK_CONNECT_KEY', 'string', NULL, 'public', 'Stripe webhook signing secret used to validate IPN calls for Stripe Connect in live mode.', 'Read in public/stripe/ipn.php:74 as the endpoint secret used to verify the Stripe webhook signature when the IPN call has the ''connect'' GET parameter set and is not in test mode.', 'If unset or wrong, Stripe Connect live webhook signature verification will fail or use an empty/incorrect secret, so live IPN events for connected accounts may be rejected or unverifiable.', 'String: the Stripe webhook signing secret (whsec_...) copied from the Stripe Connect webhook settings.', 1, 0, NULL, 1, '2ba343f5e55471fbbd662ed04ebe10ec5f62155ed9a16f4a85f1b8bdb161e52c', 'v2', '2026-07-24T07:05:23+00:00', '["public/stripe/ipn.php:74|read|$endpoint_secret = getDolGlobalString(''STRIPE_LIVE_WEBHOOK_CONNECT_KEY'');", "// You can find your endpoint''s secret in your webhook settings"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_LIVE_WEBHOOK_ID', 'string', NULL, 'stripe', 'Stores the Stripe live-mode webhook endpoint ID used to verify and retrieve the live webhook configuration.', 'Configured via stripe/admin/stripe.php:106 and read/checked at :339, :361, :365, :367. Used together with STRIPE_LIVE_WEBHOOK_KEY and STRIPE_LIVE_SECRET_KEY to validate the live webhook endpoint via the Stripe API.', 'Changing this value changes which Stripe live webhook endpoint Dolibarr validates and uses for live-mode IPN processing.', 'String Stripe webhook endpoint ID for live mode (e.g., ''we_x...'')', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '2a6db89b04da2097bdab6c9ce9c0687101f6ec3c8854a87e240828c3ea11e07f', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:106|write|$result = dolibarr_set_const($db, \"STRIPE_LIVE_WEBHOOK_ID\", GETPOST(''STRIPE_LIVE_WEBHOOK_ID'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "stripe/admin/stripe.php:361|check|if (getDolGlobalString(''STRIPE_LIVE_WEBHOOK_KEY'') && getDolGlobalString(''STRIPE_LIVE_SECRET_KEY'') && getDolGlobalString(''STRIPE_LIVE_WEBHOOK_ID'')) {", "stripe/admin/stripe.php:365|read|$endpoint = \\Stripe\\WebhookEndpoint::retrieve(getDolGlobalString(''STRIPE_LIVE_WEBHOOK_ID''));", "stripe/admin/stripe.php:367|check|if (GETPOST(''webhook'', ''alpha'') == getDolGlobalString(''STRIPE_LIVE_WEBHOOK_ID'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_LIVE_WEBHOOK_KEY', 'string', NULL, 'stripe', 'Stores the Stripe live-mode webhook signing secret used to verify incoming live webhook request signatures.', 'Configured via stripe/admin/stripe.php:110 and used in public/stripe/ipn.php:84 as the endpoint_secret for live signature verification. Also checked at stripe/admin/stripe.php:361 alongside STRIPE_LIVE_SECRET_KEY and STRIPE_LIVE_WEBHOOK_ID.', 'Changing or clearing this value breaks webhook signature validation for live-mode Stripe events, causing all live webhook events to fail verification.', 'String Stripe webhook signing secret for live mode (e.g., ''whsec_...'')', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, 'ec59ef5c625b554daeccef70f73473eb57d0595ccb48767e5e374a75eb400daa', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:110|write|$result = dolibarr_set_const($db, \"STRIPE_LIVE_WEBHOOK_KEY\", GETPOST(''STRIPE_LIVE_WEBHOOK_KEY'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "public/stripe/ipn.php:84|read|$endpoint_secret = getDolGlobalString(''STRIPE_LIVE_WEBHOOK_KEY'');", "stripe/admin/stripe.php:361|check|if (getDolGlobalString(''STRIPE_LIVE_WEBHOOK_KEY'') && getDolGlobalString(''STRIPE_LIVE_SECRET_KEY'') && getDolGlobalString(''STRIPE_LIVE_WEBHOOK_ID'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_LOCATION', 'string', NULL, 'takepos', 'Stores the Stripe Terminal location ID used to filter readers for in-person payment processing.', 'Configured via stripe/admin/stripe.php:132 and read in takepos/admin/terminal.php:274-276 to filter Stripe Terminal readers by location. Also checked at takepos/pay.php:142 and :193 to include the location parameter in the Stripe Terminal client-side integration.', 'Setting this to a valid Stripe location ID enables Stripe Terminal reader filtering by location; leaving it empty retrieves all readers.', 'Empty/not set = no location filter applied; Stripe location ID string = only readers at that location are listed and used.', 0, 0, 'stripe/admin/stripe.php|takepos/admin/terminal.php|takepos/admin/terminal.php|stripe/admin/stripe.php', 1, '95ee0f48b533a4ceea995158594f9a662f5b635804692b0f68814d35bbaca526', 'v2', '2026-04-21T11:16:15+00:00', '["takepos/admin/terminal.php:274|read|$readers = \\Stripe\\Terminal\\Reader::all(null, array(\"location\" => getDolGlobalString(''STRIPE_LOCATION''), \"stripe_account\" => $stripeacc));", "stripe/admin/stripe.php:132|write|$result = dolibarr_set_const($db, \"STRIPE_LOCATION\", GETPOST(''STRIPE_LOCATION'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/pay.php:142|check|if (getDolGlobalString(''STRIPE_LOCATION'')) {", "stripe/ajax/ajax.php:70|read|$usestripeterminals = getDolGlobalString(''STRIPE_LOCATION'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_NO_DUPLICATE_CHECK', 'string', NULL, 'public', 'Guard flag that (per a TODO comment) is meant to gate creation of a Stripe payment mode record, intended to prevent duplicate card/payment-mode entries.', 'Checked in public/stripe/ipn.php:953 around creation of a CompanyPaymentMode from an incoming Stripe card event; the preceding TODO comment at line 952 states the actual duplicate check (''Check that a payment mode ... does not exists yet'') is not implemented yet and this constant is only a placeholder to remove the test once it is.', 'Exact behavior unclear from code alone [SPECULATION] — the surrounding TODO indicates the real duplicate-detection logic is not yet implemented, so this constant currently just gates whether the payment mode creation code runs at all.', 'Boolean-like: truthy enables the code block that creates the CompanyPaymentMode record (per current code, no duplicate check is actually performed).', 1, 0, NULL, 1, 'd3828c0170d25e539e96c9506b0b9770bc4fa5d01d6ec7afa86b15fd86ed4b62', 'v2', '2026-07-24T07:05:23+00:00', '["public/stripe/ipn.php:953|check|if (getDolGlobalString(''STRIPE_NO_DUPLICATE_CHECK'')) {", "// TODO Check that a payment mode $companypaymentmode->stripe_card_ref does not exists yet to avoid to create duplicates", "// so we can remove the test on STRIPE_NO_DUPLICATE_CHECK"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_PAYMENT_MODE_FOR_PAYMENTS', 'string', NULL, 'public', 'Specifies the payment mode ID used to record Stripe payments in the Dolibarr payment system.', 'Read as an integer at public/payment/paymentok.php at lines 585, 1028, 1174, 1329, 1468, 1707, and 1925 and assigned to $paymentTypeId for recording payments. No admin UI write found.', 'Setting this to a valid payment mode ID ensures Stripe payments are recorded with the correct payment type.', 'An integer payment mode ID.', 1, 0, NULL, 1, '8cbd54ce5abe885b0fb9be8b67165b1e0a587d857545acbc88b28175cc6bbb05', 'v2', '2026-04-21T13:50:40+00:00', '["public/payment/paymentok.php:585|read|$paymentTypeId = getDolGlobalInt(''STRIPE_PAYMENT_MODE_FOR_PAYMENTS'');", "public/payment/paymentok.php:1028|read|$paymentTypeId = getDolGlobalInt(''STRIPE_PAYMENT_MODE_FOR_PAYMENTS'');", "public/payment/paymentok.php:1174|read|$paymentTypeId = getDolGlobalInt(''STRIPE_PAYMENT_MODE_FOR_PAYMENTS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_REUSE_EXISTING_INTENT_IF_FOUND', 'bool', NULL, 'stripe', 'Controls whether Dolibarr''s Stripe integration reuses an existing (previously created) Stripe payment intent for an object instead of always creating a new one.', 'Checked in stripe/class/stripe.class.php:419, guarded by ''is_object($object)'' and ''not STRIPE_CARD_PRESENT'', with a long comment explaining the tradeoffs of reusing vs recreating payment intents.', 'When set, a failed/previous payment intent tied to the object may be reused; the code comment warns this is not recommended if amount or other idempotency-affecting fields changed, since Stripe would then reject reuse.', 'Bool/int: truthy enables reusing an existing payment intent found for the object (only when STRIPE_CARD_PRESENT is not set).', 1, 0, NULL, 1, '0f1597832255477c14e016b7cfb7c01b7bedfce563a96173db4fdef8efb2caac', 'v2', '2026-07-24T07:05:23+00:00', '["stripe/class/stripe.class.php:419|check|if (is_object($object) && getDolGlobalInt(''STRIPE_REUSE_EXISTING_INTENT_IF_FOUND'') && !getDolGlobalInt(''STRIPE_CARD_PRESENT'')) {", "stripe/class/stripe.class.php:420-424|read|// Warning. If a payment was tried and failed, a payment intent was created. But if we change something on object to pay ... reusing same payment intent, is not allowed by Stripe."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_SAVE_TAX_IDS', 'string', NULL, 'public', 'Enables saving the customer''s tax ID information on the Stripe side when processing payments.', 'Checked with getDolGlobalString in public/payment/newpayment.php:660, stripe/class/stripe.class.php:254, and core/triggers/interface_80_modStripe_Stripe.class.php:156, each with an identical inline comment warning about the effect.', 'When enabled, tax info is saved on the Stripe customer object; the code comments warn this ''may result in error when saving customer'' in some cases.', NULL, 0, 0, NULL, 1, 'a0fe23132c16705e297bfb1a154dfce37a4c5cf3020e7f781eefa5c2f22dd8d6', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''STRIPE_SAVE_TAX_IDS'')) {\t// We setup to save Tax info on Stripe side. Warning: This may result in error when saving customer"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_SEPA_CREDIT_TRANSFER', 'string', NULL, 'salaries', 'Enables Stripe SEPA Credit Transfer payment mode for supplier payments and customer invoices.', 'Configured via stripe/admin/stripe.php:501. Checked in salaries/virement_request.php:651, compta/facture/prelevement.php:1061, and core/class/commoninvoice.class.php:1628 where credit transfer availability is conditioned on this constant.', 'When set, SEPA Credit Transfer options appear on salary transfer request and invoice pre-levy pages; when absent, the credit-transfer path is suppressed.', 'Non-empty string = SEPA Credit Transfer enabled; empty = disabled', 0, 0, 'stripe/admin/stripe.php', 1, 'b3b9c1a615f13ad04a97872883ece31921d12e23163cf6a0ba0754361d5a8a8b', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:501|read|print $form->selectarray(\"STRIPE_SEPA_CREDIT_TRANSFER\", $arrval, getDolGlobalString(''STRIPE_SEPA_CREDIT_TRANSFER''));", "salaries/virement_request.php:651|check|if (getDolGlobalString(''STRIPE_SEPA_CREDIT_TRANSFER'')) {", "compta/facture/prelevement.php:1061|check|if (getDolGlobalString(''STRIPE_SEPA_CREDIT_TRANSFER'')) {", "core/class/commoninvoice.class.php:1628|check|if ($type != ''direct-debit'' && !getDolGlobalString(''STRIPE_SEPA_CREDIT_TRANSFER'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_SEPA_DIRECT_DEBIT', 'string', NULL, 'stripe', 'Enables and configures Stripe SEPA Direct Debit payment mode in Dolibarr.', 'Configured via stripe/admin/stripe.php (select array at line 491). Checked in stripe/class/stripe.class.php:487 and :765 to gate SEPA debit processing, and in compta/facture/prelevement.php:915 and :922 when the Stripe module is active.', 'When set, SEPA Direct Debit flows become available on supplier salary requests and customer invoice pre-levy pages; when unset those flows are suppressed.', 'Non-empty string value = SEPA Direct Debit enabled; empty = disabled', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, 'b143aa4b4bc833282f0d5212705908018200461ed41cde7e45f4b0caf5967cdb', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:491|read|print $form->selectarray(\"STRIPE_SEPA_DIRECT_DEBIT\", $arrval, getDolGlobalString(''STRIPE_SEPA_DIRECT_DEBIT''));", "stripe/class/stripe.class.php:487|check|if (getDolGlobalInt(''STRIPE_SEPA_DIRECT_DEBIT'')) {", "compta/facture/prelevement.php:915|check|if (isModEnabled(''stripe'') && getDolGlobalString(''STRIPE_SEPA_DIRECT_DEBIT'')) {", "salaries/virement_request.php:643|check|if (getDolGlobalString(''STRIPE_SEPA_DIRECT_DEBIT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_SEPA_DIRECT_DEBIT_SHOW_OLD_BUTTON', 'bool', NULL, 'salaries', 'When enabled, shows a legacy SEPA direct-debit button that is otherwise hidden in favour of the STRIPE_SEPA_DIRECT_DEBIT mode.', 'Checked in salaries/virement_request.php:515 and compta/facture/prelevement.php:869. The inline comments in both locations state: ''This is hidden, prefer to use mode enabled with STRIPE_SEPA_DIRECT_DEBIT''.', 'Enabling this constant re-exposes the old SEPA direct-debit UI button; leaving it disabled keeps that button hidden.', 'Non-empty/truthy = show old button; empty/falsy = hide (default)', 1, 0, NULL, 1, '32fcb4d1ba2c0b88ea8b99245c1352f1d366d5f473e8edbadcb0c3631147c3d2', 'v2', '2026-04-21T11:16:15+00:00', '["salaries/virement_request.php:515|check|if (getDolGlobalString(''STRIPE_SEPA_DIRECT_DEBIT_SHOW_OLD_BUTTON'')) {\t// This is hidden, prefer to use mode enabled with STRIPE_SEPA_DIRECT_DEBIT", "compta/facture/prelevement.php:869|check|if (getDolGlobalString(''STRIPE_SEPA_DIRECT_DEBIT_SHOW_OLD_BUTTON'')) {\t// This is hidden, prefer to use mode enabled with STRIPE_SEPA_DIRECT_DEBIT"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_SOFORT', 'string', NULL, 'stripe', 'Enables the Sofort payment method option in Stripe payment processing.', 'Selected via admin UI at stripe/admin/stripe.php:569 and checked in stripe/class/stripe.class.php:502 and :775 to include Sofort as a payment method type.', 'Enabling this adds Sofort to the list of Stripe payment method types offered during checkout.', '0 or unset = Sofort disabled; truthy value = Sofort enabled.', 0, 0, 'stripe/admin/stripe.php', 1, 'e86818711267fbcd5baf77542594b284d24dd22cc58e3ce089a02aa1ebd95c97', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:569|read|print $form->selectarray(\"STRIPE_SOFORT\", $arrval, $conf->global->STRIPE_SOFORT);", "stripe/class/stripe.class.php:502|check|if (getDolGlobalInt(''STRIPE_SOFORT'')) {", "stripe/class/stripe.class.php:775|check|if (getDolGlobalString(''STRIPE_SOFORT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_TERMINAL_SIMULATED', 'string', NULL, 'takepos', 'Provides the test card number used to enable Stripe Terminal simulation mode in TakePos.', 'Read at takepos/pay.php:192, :448, and :449; when set and $servicestatus is empty, the Stripe Terminal is configured in simulated mode using the constant''s value as the test card number.', 'Setting this constant activates Stripe Terminal simulation with the specified test card number; leaving it unset disables simulation mode.', 'Empty/unset = live Stripe Terminal mode; a Stripe test card number string = simulated terminal with that card.', 1, 0, NULL, 1, 'c4518d8d7cb35acbbb92f734e8e1d1fb97c9967555337e258867549213a6c080', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/pay.php:192|check|simulated: <?php if (empty($servicestatus) && getDolGlobalString(''STRIPE_TERMINAL_SIMULATED'')) { ?> true <?php } else { ?> false <?php } ?>", "takepos/pay.php:449|read|terminal.setSimulatorConfiguration({testCardNumber: ''<?php echo dol_escape_js(getDolGlobalString(''STRIPE_TERMINAL_SIMULATED'')); ?>''});"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_TEST_PUBLISHABLE_KEY', 'string', NULL, 'stripe', 'Stores the Stripe test-mode publishable API key used for client-side Stripe integration in test mode.', 'Configured via stripe/admin/stripe.php:82 and read at stripe/config.php:36. A commented-out line at stripe/admin/stripe.php:264 shows it was previously considered for security hashing: ''//$url .= ''&securitykey=''.dol_hash(''stripeipn-''.$dolibarr_main_instance_unique_id.''-''.getDolGlobalString(''STRIPE_TEST_PUBLISHABLE_KEY''), ''md5'');''.', 'Setting a valid test publishable key enables client-side Stripe test-mode elements; an absent key disables them.', 'Empty/not set = Stripe test publishable key not configured; string starting with ''pk_test_' || ''' = valid Stripe test publishable key.', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '0017075fc5e08d24513b557ea5b61622b0134e306e1bec8ffe13b6f38f500764', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/config.php:36|read|\"publishable_key\" => getDolGlobalString(''STRIPE_TEST_PUBLISHABLE_KEY'')", "stripe/admin/stripe.php:82|write|$result = dolibarr_set_const($db, \"STRIPE_TEST_PUBLISHABLE_KEY\", GETPOST(''STRIPE_TEST_PUBLISHABLE_KEY'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "stripe/admin/stripe.php:264  //$url .= ''&securitykey=''.dol_hash(''stripeipn-''.$dolibarr_main_instance_unique_id.''-''.getDolGlobalString(''STRIPE_TEST_PUBLISHABLE_KEY''), ''md5'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_TEST_SECRET_KEY', 'string', NULL, 'stripe', 'Stores the Stripe test-mode secret API key used to authenticate server-side Stripe API calls in test mode.', 'Configured via stripe/admin/stripe.php:86 and read at stripe/config.php:35 and stripe/admin/stripe.php:282, where it is passed to \Stripe\Stripe::setApiKey(). It is also validated for UTF-8 correctness before use.', 'Setting a valid test secret key enables Stripe test-mode payment processing; an invalid or absent key disables Stripe test integration.', 'Empty/not set = Stripe test mode not configured; string starting with ''sk_test_' || ''' = valid Stripe test secret key.', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '6551e29d08142bfc7471cf0adca11789b4af627761342433d00dd12b0a4c94ef', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/config.php:35|read|\"secret_key\"      => getDolGlobalString(''STRIPE_TEST_SECRET_KEY''),", "stripe/admin/stripe.php:282|read|\\Stripe\\Stripe::setApiKey(getDolGlobalString(''STRIPE_TEST_SECRET_KEY''));", "stripe/admin/stripe.php:280|check|if (utf8_check(getDolGlobalString(''STRIPE_TEST_SECRET_KEY''))) {", "stripe/admin/stripe.php:86|write|$result = dolibarr_set_const($db, \"STRIPE_TEST_SECRET_KEY\", GETPOST(''STRIPE_TEST_SECRET_KEY'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_TEST_WEBHOOK_CONNECT_KEY', 'string', NULL, 'public', 'Stripe Connect webhook signing secret used to verify test-mode webhook events received via Stripe Connect.', 'Read in public/stripe/ipn.php:70 when the incoming request has both ''connect'' and ''test'' GET parameters set, used as $endpoint_secret for the ''StripeTest'' service in the IPN handler.', 'Setting it (with the matching value from the Stripe Connect webhook configuration) is required for the endpoint to validate test-mode Stripe Connect webhook signatures; a wrong value causes webhook verification to fail.', 'Secret string copied from the Stripe Connect webhook settings (test mode endpoint secret).', 0, 0, NULL, 1, 'ffa18a8f1b3f09e88b8d965abcee82f2882ae88298e9f483b96f68112679e131', 'v2', '2026-07-24T07:05:23+00:00', '["public/stripe/ipn.php:67: // You can find your endpoint''s secret in your webhook settings", "public/stripe/ipn.php:70: $endpoint_secret = getDolGlobalString(''STRIPE_TEST_WEBHOOK_CONNECT_KEY'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_TEST_WEBHOOK_ID', 'string', NULL, 'stripe', 'Stores the Stripe test-mode webhook endpoint ID used to verify and retrieve the webhook configuration.', 'Configured via stripe/admin/stripe.php:90 and read/checked at :256, :279, :283, :285. Used together with STRIPE_TEST_WEBHOOK_KEY and STRIPE_TEST_SECRET_KEY to validate the test webhook endpoint via the Stripe API.', 'Changing this value changes which Stripe test webhook endpoint Dolibarr validates and uses for test-mode IPN processing.', 'String Stripe webhook endpoint ID (e.g., ''we_x...'')', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '836b9bbf9b618f075b2ad77f8a3d4bc6b0d8ab90c2eadaec2d2909d5719e7be3', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:90|write|$result = dolibarr_set_const($db, \"STRIPE_TEST_WEBHOOK_ID\", GETPOST(''STRIPE_TEST_WEBHOOK_ID'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "stripe/admin/stripe.php:279|check|if (getDolGlobalString(''STRIPE_TEST_WEBHOOK_KEY'') && getDolGlobalString(''STRIPE_TEST_SECRET_KEY'') && getDolGlobalString(''STRIPE_TEST_WEBHOOK_ID'')) {", "stripe/admin/stripe.php:283|read|$endpoint = \\Stripe\\WebhookEndpoint::retrieve(getDolGlobalString(''STRIPE_TEST_WEBHOOK_ID''));", "stripe/admin/stripe.php:285|check|if (GETPOST(''webhook'', ''alpha'') == getDolGlobalString(''STRIPE_TEST_WEBHOOK_ID'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_TEST_WEBHOOK_KEY', 'string', NULL, 'stripe', 'Stores the Stripe test-mode webhook signing secret used to verify incoming webhook request signatures.', 'Configured via stripe/admin/stripe.php:94 and used in public/stripe/ipn.php:80 as the endpoint_secret for signature verification. Also checked at stripe/admin/stripe.php:279 alongside STRIPE_TEST_SECRET_KEY and STRIPE_TEST_WEBHOOK_ID.', 'Changing or clearing this value breaks webhook signature validation for test-mode Stripe events, causing all test webhook events to fail verification.', 'String Stripe webhook signing secret for test mode (e.g., ''whsec_...'')', 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '394b188e641b8aa2a16b4a535305eadc97ee95866d27b58493616285ca3ab1eb', 'v2', '2026-04-21T11:16:15+00:00', '["stripe/admin/stripe.php:94|write|$result = dolibarr_set_const($db, \"STRIPE_TEST_WEBHOOK_KEY\", GETPOST(''STRIPE_TEST_WEBHOOK_KEY'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "public/stripe/ipn.php:80|read|$endpoint_secret = getDolGlobalString(''STRIPE_TEST_WEBHOOK_KEY'');", "stripe/admin/stripe.php:279|check|if (getDolGlobalString(''STRIPE_TEST_WEBHOOK_KEY'') && getDolGlobalString(''STRIPE_TEST_SECRET_KEY'') && getDolGlobalString(''STRIPE_TEST_WEBHOOK_ID'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_USER_ACCOUNT_FOR_ACTIONS', 'string', NULL, 'public', 'Selects the Dolibarr user account under which Stripe-related actions (e.g. IPN processing) are performed.', 'Set via stripe/admin/stripe.php:123 dolibarr_set_const, configured via select_dolusers at stripe/admin/stripe.php:630, and used in public/stripe/ipn.php:98/101 to fetch the acting user.', 'When set, the Stripe IPN handler fetches and acts as the specified user ID instead of running without an associated user context.', NULL, 0, 0, 'stripe/admin/stripe.php|stripe/admin/stripe.php', 1, '2215829d1b8b1ef45610d0c04c497a0583ad8404ddc06232fba7e5120719b3e5', 'v2', '2026-07-24T06:41:12+00:00', '["$result = dolibarr_set_const($db, \"STRIPE_USER_ACCOUNT_FOR_ACTIONS\", GETPOSTINT(''STRIPE_USER_ACCOUNT_FOR_ACTIONS''), ''chaine'', 0, '''', $conf->entity);", "$user->fetch(getDolGlobalInt(''STRIPE_USER_ACCOUNT_FOR_ACTIONS''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_USE_IDEMPOTENCY_BY_DEFAULT', 'bool', NULL, 'public', 'When enabled, adds an idempotency key to Stripe payment requests by default, requiring a unique tag/ref per payment.', 'Read at public/payment/newpayment.php:2479 and :2672 to determine whether to set noidempotency_key=0. The comments at :2478 and :2671 state: ''If STRIPE_USE_IDEMPOTENCY_BY_DEFAULT is set or param noidempotency=0 is added, then with add an idempotent key, so we must use a different tag/ref for each payment (if not we will get an error)''.', 'When enabled, each Stripe payment must use a unique tag/ref; reusing the same ref with idempotency enabled will result in an error.', '0 or unset = no idempotency key by default; non-zero = idempotency key used by default (requires unique tag/ref per payment)', 1, 0, NULL, 1, '2eb4d31258b3ede0093773739f3e467dc9882b1844d61926f89b23a9a845ace4', 'v2', '2026-04-21T13:50:40+00:00', '["public/payment/newpayment.php:2478  // If STRIPE_USE_IDEMPOTENCY_BY_DEFAULT is set or param noidempotency=0 is added, then with add an idempotent key, so we must use a different tag/ref for each payment (if not we will get an error).", "public/payment/newpayment.php:2479|read|$noidempotency_key = (GETPOSTISSET(''noidempotency'') ? GETPOSTINT(''noidempotency'') : (getDolGlobalInt(''STRIPE_USE_IDEMPOTENCY_BY_DEFAULT'') ? 0 : 1));", "public/payment/newpayment.php:2671  // If STRIPE_USE_IDEMPOTENCY_BY_DEFAULT is set or param noidempotency=0 is added, then with add an idempotent key, so we must use a different tag/ref for each payment (if not we will get an error)."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_USE_INTENT_WITH_AUTOMATIC_CONFIRMATION', 'bool', NULL, 'public', 'Switches Stripe payment processing to use the PaymentIntent API with automatic confirmation, with a mode value of 2 for automatic payment methods.', 'Checked extensively with getDolGlobalInt/getDolGlobalString in public/payment/newpayment.php, stripe/class/stripe.class.php, and public/payment/paymentok.php, with explicit comments describing modes 1 (default) and 2.', 'When on, payments use the new PaymentIntent API per the header comment in newpayment.php; value 2 specifically enables ''automatic_payment_methods'' in stripe.class.php and bypasses the session check on return in paymentok.php.', '1 = default PaymentIntent with automatic confirmation; 2 = automatic_payment_methods mode (bypasses session check on return)', 0, 0, NULL, 1, '9f6054ab040e893a22ca709a3fc77909e6af7dc08d169bab7ed1e1837d9db6bc', 'v2', '2026-07-24T06:41:12+00:00', '["* - When option STRIPE_USE_INTENT_WITH_AUTOMATIC_CONFIRMATION is on, we use the new PaymentIntent API", "// When STRIPE_USE_INTENT_WITH_AUTOMATIC_CONFIRMATION=2, use automatic_payment_methods", "// Bypass session check when returning from Stripe confirmPayment() (mode STRIPE_USE_INTENT_WITH_AUTOMATIC_CONFIRMATION=2)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('STRIPE_USE_NEW_CHECKOUT', 'bool', NULL, 'public', 'Enables the new Stripe Checkout API for payment processing instead of the older payment intent flow.', 'Multiple comments confirm the semantics: ''When option STRIPE_USE_NEW_CHECKOUT is on, we use the new checkout API'' (public/payment/newpayment.php:31) and ''but not when using the STRIPE_USE_NEW_CHECKOUT'' (stripe/class/stripe.class.php:371, 723). Also activates SCA-ready checkout when combined with amount checks (newpayment.php:2651).', 'Enabling this constant switches Stripe payments to the Checkout session flow. Disabling uses the Payment Intent with automatic confirmation flow instead.', 'Empty/unset = Payment Intent flow; non-empty = new Stripe Checkout API flow', 1, 0, NULL, 1, '98126ab29ea73a22b00d7ff5506df6e0bd23a651d83662d97b3094b5fb75b5b7', 'v2', '2026-04-21T13:29:58+00:00', '["public/payment/newpayment.php:31  * - When option STRIPE_USE_NEW_CHECKOUT is on, we use the new checkout API", "stripe/class/stripe.class.php:371  * but not when using the STRIPE_USE_NEW_CHECKOUT.", "public/payment/newpayment.php:2651|check|if ($checkamount && (getDolGlobalString(''STRIPE_USE_INTENT_WITH_AUTOMATIC_CONFIRMATION'') || getDolGlobalString(''STRIPE_USE_NEW_CHECKOUT''))) {", "public/payment/newpayment.php:2748|check|if (getDolGlobalString(''STRIPE_USE_NEW_CHECKOUT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUBTOTAL_', 'string', NULL, 'compta', 'Prefix for a family of per-document-type constants (SUBTOTAL_<TYPE> and SUBTOTAL_<TYPE>_MAX_DEPTH / SUBTOTAL_TITLE_<TYPE>) enabling subtotal/title lines and controlling their nesting depth on documents (proposals, orders, invoices, etc).', 'Configured via admin UI admin/subtotals.php, which toggles SUBTOTAL_<TYPE> and SUBTOTAL_TITLE_<TYPE> per module (e.g. PROPAL, COMMANDE, FACTURE) and lets the max nesting depth SUBTOTAL_<TYPE>_MAX_DEPTH (default 2) be edited; consumed at document-line level in compta/facture/card.php:6741, commande/card.php:3490, comm/propal/card.php:3596 and subtotals/class/commonsubtotal.class.php:840.', 'Enabling SUBTOTAL_<TYPE> or SUBTOTAL_TITLE_<TYPE> for a document type exposes subtotal/title line insertion on that document''s line list; SUBTOTAL_<TYPE>_MAX_DEPTH caps how many nested subtotal levels can be created (default 2), and per admin/subtotals.php the max depth field is only editable when at least one of the two toggles is enabled.', 'SUBTOTAL_<TYPE> / SUBTOTAL_TITLE_<TYPE>: 0=disabled, 1=enabled (toggled via admin UI switch). SUBTOTAL_<TYPE>_MAX_DEPTH: integer nesting depth, default 2.', 0, 0, 'admin/subtotals.php|admin/subtotals.php', 1, 'afdac85f7c2f634bc8f829e79ac2f0a90b1ce60f1e488a81f8e7277167416bce', 'v2', '2026-07-24T07:05:23+00:00', '["admin/subtotals.php:96: $const_depth = getDolGlobalString(''SUBTOTAL_'' . $const . ''_MAX_DEPTH'', 2);", "admin/subtotals.php:205: print ''name=\"SUBTOTAL_'' . $const . ''_MAX_DEPTH\" value=\"'' . getDolGlobalString(''SUBTOTAL_'' . $const . ''_MAX_DEPTH'', $can_modify ? 2 : 0) . ''\">'';", "subtotals/class/commonsubtotal.class.php:840: $max_depth = getDolGlobalString(''SUBTOTAL_''.strtoupper($this->element).''_MAX_DEPTH'', 2);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUBTOTAL_BACK_COLOR_LEVEL_', 'string', NULL, 'core', 'Prefix for per-level constants (SUBTOTAL_BACK_COLOR_LEVEL_<n>) defining the background color used for each subtotal nesting level.', 'Read as a dynamic key in admin/subtotals.php:108 and subtotals/class/commonsubtotal.class.php:805, and used in PDF model templates (core/modules/expedition/doc/pdf_espadon.modules.php, core/modules/facture/doc/pdf_sponge.modules.php, core/modules/commande/doc/pdf_eratosthene.modules.php, core/modules/propale/doc/pdf_cyan.modules.php) with a default fallback of ''ffffff''.', 'Changing SUBTOTAL_BACK_COLOR_LEVEL_<n> changes the background color used for subtotal rows at that nesting level, both on screen and in generated PDFs (default white ''ffffff'' if unset).', NULL, 0, 0, 'admin/subtotals.php', 1, '76d26f11dfa963ed09e3b1881320417fdbfc2fe7d4c2ed03353464383c327d09', 'v2', '2026-07-24T06:41:12+00:00', '["$colors[''SUBTOTAL_BACK_COLOR_LEVEL_'' . ($i + 1)] = array(''level'' => $i + 1, ''color'' => getDolGlobalString(''SUBTOTAL_BACK_COLOR_LEVEL_'' . ($i + 1), $default));", "$bg_color = colorStringToArray(getDolGlobalString(\"SUBTOTAL_BACK_COLOR_LEVEL_\".abs($object->lines[$i]->qty), ''ffffff''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUBTOTAL_TITLE_', 'string', NULL, 'compta', 'Per-element flag (e.g. SUBTOTAL_TITLE_PROPAL) that enables subtotal title lines on document line forms for the subtotals module.', 'The constant name is constructed dynamically as `''SUBTOTAL_TITLE_''.strtoupper($object->element)`. Checked across 12 occurrences including supplier_proposal/card.php:2315, fourn/commande/card.php:2856, compta/facture/card.php:6646, and comm/propal/card.php:3546, all requiring `isModEnabled(''subtotals'')` as well.', 'Enabling the element-specific constant activates the subtotal title line feature for that document type when the subtotals module is active.', 'Truthy string (non-empty) = subtotal title lines enabled for this element; empty/not set = feature disabled.', 1, 0, NULL, 1, 'de488f2fda9b5f79f010c93a77803413a3b88def6ec0af871dd95926a49cf946', 'v2', '2026-04-21T11:16:15+00:00', '["supplier_proposal/card.php:2315|check|if ($object->status == SupplierProposal::STATUS_DRAFT && isModEnabled(''subtotals'') && getDolGlobalString(''SUBTOTAL_TITLE_''.strtoupper($object->element))) {", "fourn/commande/card.php:2856|check|if ($object->status == CommandeFournisseur::STATUS_DRAFT && isModEnabled(''subtotals'') && getDolGlobalString(''SUBTOTAL_TITLE_''.strtoupper($object->element))) {", "compta/facture/card.php:6646|read|&& (getDolGlobalInt(''SUBTOTAL_TITLE_''.strtoupper($object->element)) || getDolGlobalInt(''SUBTOTAL_''.strtoupper($object->element)))) {", "comm/propal/card.php:3546|read|&& (getDolGlobalInt(''SUBTOTAL_TITLE_''.strtoupper($object->element)) || getDolGlobalInt(''SUBTOTAL_''.strtoupper($object->element)))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_CREDIT_TULIP_MASK', 'string', NULL, 'core', 'Numbering mask used for supplier credit-note references generated by the ''Tulip'' supplier invoice numbering model.', 'In core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php, the admin form (info(), line 113) shows/edits this value as input ''maskcredit'', and getNextValue() (lines 176-177) reads it via getDolGlobalString to build the next reference when the object type is a credit note (object->type == 2).', 'Changing this mask changes the format of generated supplier credit-note references; if empty, getNextValue() falls back to error ''NotConfigured'' for credit notes since no fallback mask is used for that type in this branch.', 'String: a Dolibarr numbering mask, editable via admin form field ''maskcredit''; empty means credit-note numbering is not configured for this model.', 0, 0, NULL, 1, 'ecd3ccd3beb28e8462374f8565cedf0dcfae107a33116cdd093c88fc2dd7891f', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:113|read|name=\"maskcredit\" value=''.getDolGlobalString(\"SUPPLIER_CREDIT_TULIP_MASK\").''", "core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:176|read|$mask = getDolGlobalString(\"SUPPLIER_CREDIT_TULIP_MASK\");", "core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:177| elseif (is_object($object) && $object->type == 2) { $mask = getDolGlobalString(\"SUPPLIER_CREDIT_TULIP_MASK\"); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_DEPOSIT_TULIP_MASK', 'string', NULL, 'core', 'Numbering mask used for supplier deposit-invoice references generated by the ''Tulip'' supplier invoice numbering model.', 'In core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php, the admin form (line 125) shows/edits it as input ''maskdeposit'', and getNextValue() (lines 178-179) reads it for deposit-type invoices (object->type == 3).', 'Changing this mask changes the format of generated supplier deposit-invoice references.', 'String: a Dolibarr numbering mask, editable via admin form field ''maskdeposit''.', 0, 0, NULL, 1, '1b7c065b858e3affe4a5acf967135c6818f2a6a45269a79c8b5b1e392c1dbd34', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:125|read|name=\"maskdeposit\" value=''.getDolGlobalString(\"SUPPLIER_DEPOSIT_TULIP_MASK\").''", "core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:178|read|$mask = getDolGlobalString(\"SUPPLIER_DEPOSIT_TULIP_MASK\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_HIDE_SUPPLIER_OBJECTLINES', 'bool', NULL, 'core', 'Hides the supplier/purchase-price detail block shown under object lines (e.g. order/invoice lines) that reference a supplier price.', 'In core/tpl/objectline_view.tpl.php:331, the block that fetches and prints supplier product pricing (via ProductFournisseur) for a line is only shown if the user has supplier read rights AND this boolean is not set; setting it suppresses that supplier-price display even for authorized users.', 'Enabling it removes the supplier/purchase price sub-block from object line views, even for users who otherwise have rights to see supplier pricing.', 'Boolean: true/1 hides the supplier object line info block; false/0 (default) shows it when the user has fournisseur/lire rights and the line has a linked supplier price.', 1, 0, NULL, 1, '7faf0c45c957edcabff41a035879d46eb14b7d45732f69bfa45d6df990db85bf', 'v2', '2026-07-24T07:05:23+00:00', '["core/tpl/objectline_view.tpl.php:331|check|if ($user->hasRight(''fournisseur'', ''lire'') && isset($line->fk_fournprice) && $line->fk_fournprice > 0 && !getDolGlobalString(''SUPPLIER_HIDE_SUPPLIER_OBJECTLINES'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Sets the directory path(s) where ODT templates for supplier invoice documents are stored.', 'Read in core/modules/supplier_invoice/doc/doc_generic_supplier_invoice_odt.modules.php:133, where the value is split by comma and newline to build a list of template directories. Also read at line 163 to display the configured path. Checked at line 171. No admin UI write is present.', 'Changing this constant redirects the supplier invoice ODT module to scan the specified directory (or directories, comma-separated) for templates. Leaving it unset causes the module to use its default template location.', 'A comma- or newline-separated list of filesystem paths; empty or unset = default path used.', 1, 0, NULL, 1, '31883c43bde6fb4e314713bfcb5fe7efca60596be34e518d0125cd9d5075888c', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/supplier_invoice/doc/doc_generic_supplier_invoice_odt.modules.php:133|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''SUPPLIER_INVOICE_ADDON_PDF_ODT_PATH''))));", "core/modules/supplier_invoice/doc/doc_generic_supplier_invoice_odt.modules.php:163|read|$texte .= getDolGlobalString(''SUPPLIER_INVOICE_ADDON_PDF_ODT_PATH'');", "core/modules/supplier_invoice/doc/doc_generic_supplier_invoice_odt.modules.php:171|check|if (getDolGlobalString(''SUPPLIER_INVOICE_ADDON_PDF_ODT_PATH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'core', 'Enables an external download link for supplier invoice documents.', 'Checked in core/class/commonobject.class.php:6395 and core/lib/functions.lib.php:10763. When set, a public download link is generated for invoice_supplier objects.', 'Enabling this constant exposes supplier invoice documents via a public URL; disabling it removes the external download option.', 'Non-zero/non-empty = external download enabled; 0 or unset = disabled', 1, 0, NULL, 1, '23da2b8f5658b5ed2f582740b64ee21ccb8b992723ddb8682986a5039e5fea20', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:6395|check|if ($this->element == ''invoice_supplier'' && getDolGlobalInt(\"SUPPLIER_INVOICE_ALLOW_EXTERNAL_DOWNLOAD\")) {", "core/lib/functions.lib.php:10763|check|if (getDolGlobalString(''SUPPLIER_INVOICE_ALLOW_EXTERNAL_DOWNLOAD'') && is_object($object) && $object->element == ''invoice_supplier'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_ALLOW_REUSE_OF_CREDIT_WHEN_PARTIALLY_REFUNDED', 'bool', NULL, 'fourn', 'Allows creating/converting a supplier credit note to a reduction even when it has been only partially refunded/paid.', 'Checked in fourn/facture/card.php:655 (prorates remaining amounts to reuse) and fourn/facture/card.php:4335 (gates the ''ConvertToReduc'' button) for FactureFournisseur::TYPE_CREDIT_NOTE invoices.', 'When set, a supplier credit note that already has a partial payment can still be converted to a reduction/reused, with the code comment noting ''This can be not 0 if we allow to create credit to reuse from credit notes partially refunded.''', 'Bool: truthy allows reuse/conversion of partially-refunded credit notes; otherwise the button/logic only applies when getSommePaiement() == 0.', 1, 0, NULL, 1, 'a01434370f0a818031887b34f9f175646939bc4d59a022512f7a16d8d8d7f6d0', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:655|check|if (getDolGlobalString(''SUPPLIER_INVOICE_ALLOW_REUSE_OF_CREDIT_WHEN_PARTIALLY_REFUNDED'') && $object->type == FactureFournisseur::TYPE_CREDIT_NOTE) {", "fourn/facture/card.php:656|read|$alreadypaid = $object->getSommePaiement(); // This can be not 0 if we allow to create credit to reuse from credit notes partially refunded.", "fourn/facture/card.php:4335|read|&& (getDolGlobalString(''SUPPLIER_INVOICE_ALLOW_REUSE_OF_CREDIT_WHEN_PARTIALLY_REFUNDED'') || $object->getSommePaiement() == 0)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_CAN_SET_PAID_EVEN_IF_PARTIALLY_PAID', 'string', NULL, 'fourn', 'Allows marking a supplier invoice as paid even when the remaining balance equals the full invoice total (i.e., no payment has been recorded).', 'Checked in fourn/facture/card.php at lines 3198, 3202, 4326, 4328, and 4335. The flag unlocks the ''paid'' action and the corresponding UI button when resteapayer equals total_ttc, which would normally be blocked.', 'Without this flag, the paid action requires resteapayer to be zero or negative. Enabling it permits closing an invoice as paid before any payment is entered.', '0 or unset = can only mark paid when fully settled; 1 = can mark paid even with full outstanding balance', 1, 0, NULL, 1, 'e5145c284859f527cbc99ab41b655ebfd88713b27fb74f1e3f221b5988c9430d', 'v2', '2026-04-21T11:16:15+00:00', '["if ($action == ''paid'' && ($resteapayer <= 0 || (getDolGlobalString(''SUPPLIER_INVOICE_CAN_SET_PAID_EVEN_IF_PARTIALLY_PAID'') && $resteapayer == $object->total_ttc))) {", "if ($action == ''paid'' && $resteapayer > 0 && (!getDolGlobalString(''SUPPLIER_INVOICE_CAN_SET_PAID_EVEN_IF_PARTIALLY_PAID'') || $resteapayer != $object->total_ttc)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_ENABLE_NEGATIVE', 'bool', NULL, 'fourn', 'Allows validating a supplier standard/replacement/deposit/proforma/situation invoice with a negative total (total_ttc < 0).', 'Checked in fourn/facture/card.php:4271 as part of the ''Validate'' button condition, which otherwise requires total_ttc >= 0 for those invoice types (credit notes separately require total_ttc <= 0).', 'When set, the Validate action becomes available for supplier invoices with a negative total_ttc that would otherwise be blocked by the default total_ttc >= 0 requirement.', 'Bool: truthy allows validating supplier invoices (non credit-note types) with a negative total.', 1, 0, NULL, 1, '7c095b6efe8814629fe05fa01aafcf4b8645b0a310b6ea5b99bb3204a15fd2b0', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:4271|read|(($object->type == FactureFournisseur::TYPE_STANDARD || ... TYPE_SITUATION) && (getDolGlobalString(''SUPPLIER_INVOICE_ENABLE_NEGATIVE'') || $object->total_ttc >= 0))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_ENABLE_NEGATIVE_LINES', 'bool', NULL, 'fourn', 'Allows negative-price lines to be added on supplier invoices.', 'Checked in fourn/facture/card.php at lines 1679-1684. When the flag is absent, adding a line with a negative unit price (HT or TTC, in any currency) is blocked and raises an error.', 'Disabling this constant prevents entry of negative-value lines on supplier invoices. Enabling it permits credit-style lines directly on a supplier invoice.', '0 or unset = negative lines blocked; 1 = negative lines allowed', 1, 0, NULL, 1, '5f30345ed5812739b354e4e75c08c139425a67bf7fb5660ab484cab77fb383ac', 'v2', '2026-04-21T11:16:15+00:00', '["&& (((float) $price_ht < 0 && !getDolGlobalString(''SUPPLIER_INVOICE_ENABLE_NEGATIVE_LINES'')) || $price_ht === '''')", "if (((float) $price_ht < 0 || (float) $price_ttc < 0) && !getDolGlobalString(''SUPPLIER_INVOICE_ENABLE_NEGATIVE_LINES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_FREE_TEXT', 'string', NULL, 'supplier_invoice', 'Stores free/custom footer text to include on generated supplier invoice documents.', 'Written from supplier_invoice/admin/supplier_invoice.php:192 via dolibarr_set_const() when the admin saves the supplier invoice module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated supplier invoice documents/PDFs; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'supplier_invoice/admin/supplier_invoice.php', 1, 'eb703a7811c63624687c3d080f7179f4d6d791b700cc9f0570b8b40a157bab38', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_invoice/admin/supplier_invoice.php:192|write|$res = dolibarr_set_const($db, \"SUPPLIER_INVOICE_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_MENU_DISABLED', 'bool', NULL, 'core', 'Hides the entire ''Supplier invoices'' left-menu section.', 'Checked in core/menus/standard/eldy.lib.php:1597, guarding the whole supplier-invoice menu block that is otherwise built when the societe and supplier_invoice modules are enabled.', 'Enabling it removes supplier invoice navigation entries from the left menu even though the supplier_invoice module remains active; pages must be reached by direct URL.', 'Truthy disables/hides the supplier invoices menu section; empty/0 shows it (default) when the module is enabled.', 1, 0, NULL, 1, 'bc1d585934b87c96dbb8e0e164a3cbe92262c0a408a40d8e18259c039bae9f3b', 'v2', '2026-07-24T07:05:23+00:00', '["core/menus/standard/eldy.lib.php:1597: if (isModEnabled(''societe'') && isModEnabled(''supplier_invoice'') && !getDolGlobalString(''SUPPLIER_INVOICE_MENU_DISABLED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_NO_PAYMENT_DETAILS', 'string', NULL, 'core', 'Suppresses the payments-already-made details block on the Canelle supplier-invoice PDF template.', 'In core/modules/supplier_invoice/doc/pdf_canelle.modules.php:602, the payments area ($this->_tableau_versements(...)) is only printed if there is a payment/credit-note/deposit already applied AND getDolGlobalString(''SUPPLIER_INVOICE_NO_PAYMENT_DETAILS'') is false.', 'Setting it to true hides the ''already paid'' payment details table on this PDF model even when payments exist.', 'Boolean: true hides the payment-details block on the PDF; false/unset (default) shows it when relevant payments exist.', 1, 0, NULL, 1, 'b3aff479ccf037e8718fc070cdfcf7a7a0f0d3008dcf7bdad85da1577d5e9aa6', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_invoice/doc/pdf_canelle.modules.php:602|check|if (($deja_regle || $amount_credit_notes_included || $amount_deposits_included) && !getDolGlobalString(''SUPPLIER_INVOICE_NO_PAYMENT_DETAILS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_PRODUCTID_DEPOSIT', 'string', NULL, 'fourn', 'Product ID used for the auto-generated deposit line on supplier invoices created from a source document.', 'Read in fourn/facture/card.php:1298 as the fk_product parameter of addline() for the deposit line, falling back to the generic INVOICE_PRODUCTID_DEPOSIT if unset.', 'Setting it changes which product record is attached to the deposit line added to a new supplier deposit invoice; if unset, falls back to INVOICE_PRODUCTID_DEPOSIT.', 'Int: product rowid to use as fk_product for supplier deposit lines.', 1, 0, NULL, 1, '2f69b9a562804d8b67845ab2c6d9986709397fbf5f8d7e1aeda4c380dc1ea79d', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/facture/card.php:1298|read|getDolGlobalInt(''SUPPLIER_INVOICE_PRODUCTID_DEPOSIT'', getDolGlobalInt(''INVOICE_PRODUCTID_DEPOSIT'')), // fk_product"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_TULIP_MASK', 'string', NULL, 'core', 'Defines the number mask pattern used by the Tulip module to generate supplier invoice reference numbers.', 'Read in mod_facture_fournisseur_tulip.php at lines 105 (displayed in a configuration input), 173, and 180 (used as the $mask variable for number generation). No admin UI write outside the module configuration form is present.', 'Setting this constant controls the format of auto-generated supplier invoice numbers in the Tulip numbering module. Leaving it unset causes the module to use an empty or default mask.', 'A mask pattern string (e.g. ''{YYYY}{MM}-{0000}''); empty or unset = no mask configured.', 1, 0, NULL, 1, '3756bab7db74a3d32d1b1d67a8b88001e470e0aa727ee5c02904c49a278c94b6', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:105|read|$texte .= ''<td class=\"right\">''.$form->textwithpicto(''<input type=\"text\" class=\"flat minwidth175\" name=\"maskinvoice\" value=\"''.getDolGlobalString(\"SUPPLIER_INVOICE_TULIP_MASK\").''\">''", "core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:173|read|$mask = getDolGlobalString(\"SUPPLIER_INVOICE_TULIP_MASK\");", "core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:180|read|$mask = getDolGlobalString(\"SUPPLIER_INVOICE_TULIP_MASK\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_INVOICE_WITH_PREDEFINED_PRICES_ONLY', 'string', NULL, 'fourn', 'Restricts supplier invoice lines to products with predefined supplier prices only.', 'Checked in fourn/class/fournisseur.facture.class.php:2176 and fourn/facture/card.php at lines 1488, 4149, and 4150. The inline comment ''Not the common case'' at lines 2176 and 1488 indicates this is a non-default restriction. No admin UI write found; HIDDEN_GUESS is 1.', 'When set to 1, only products with existing predefined prices can be added to supplier invoices; other products are rejected or restricted.', '1 = only predefined prices allowed; 0 or not set = free price entry allowed', 1, 0, NULL, 1, 'b0c98db12e5b67297866744bdba56ee13f3e5a6b275a76d7baaae0b1883ad922', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/class/fournisseur.facture.class.php:2176|check|if (getDolGlobalInt(''SUPPLIER_INVOICE_WITH_PREDEFINED_PRICES_ONLY'') == 1) {\t\t// Not the common case", "fourn/facture/card.php:1488|check|if (getDolGlobalInt(''SUPPLIER_INVOICE_WITH_PREDEFINED_PRICES_ONLY'') == 1) {\t\t// Not the common case", "fourn/facture/card.php:4149|check|if (getDolGlobalInt(''SUPPLIER_INVOICE_WITH_PREDEFINED_PRICES_ONLY'')) {", "fourn/facture/card.php:4150|read|$senderissupplier = getDolGlobalInt(''SUPPLIER_INVOICE_WITH_PREDEFINED_PRICES_ONLY'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_MENU_ORDER_RECEIVED_INTO_INVOICE', 'string', NULL, 'core', 'Adds a ''Supplier orders to bill'' shortcut menu entry (received orders not yet billed).', 'Checked in core/menus/standard/eldy.lib.php:1643; when truthy, a menu entry linking to fourn/commande/list.php filtered on status=5 (received) and search_billed=0 is added under the supplier_invoice module.', 'Enabling it surfaces a dedicated left-menu shortcut listing received supplier orders that are not yet invoiced, easing the order-to-invoice workflow.', 'Truthy adds the ''orders to bill'' menu shortcut; empty/0 omits it (default).', 1, 0, NULL, 1, '78e72d7220825579926fd2b514eb5ea4b4ce38beacb637eab7314addb25da8a0', 'v2', '2026-07-24T07:05:23+00:00', '["core/menus/standard/eldy.lib.php:1643: if (getDolGlobalString(''SUPPLIER_MENU_ORDER_RECEIVED_INTO_INVOICE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_3_STEPS_TO_BE_APPROVED', 'string', NULL, 'fourn', 'Sets an amount threshold above which supplier orders require a second (double) approval step.', 'Set via supplier_order/admin/supplier_order.php:181 dolibarr_set_const, edited via the input at line 501, and checked in fourn/class/fournisseur.commande.class.php:1334 and fourn/commande/card.php (lines 2914, 2925, 2967) comparing against $object->total_ht via getDolGlobalFloat.', 'When set to a nonzero threshold, supplier orders whose total_ht is greater than or equal to this value require a second-level approval, per the explicit comments referencing ''Second approval'' and ''Second level approval''.', NULL, 0, 0, 'supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php|supplier_order/admin/supplier_order.php', 1, '2b66d83e9ec1058c65b88b5fa0cada9b35a514726659b6ef507dcaba8d3925e8', 'v2', '2026-07-24T06:41:12+00:00', '["* Used when SUPPLIER_ORDER_3_STEPS_TO_BE_APPROVED is set", "*  @param\tint\t\t$secondlevel\t0=Standard approval, 1=Second level approval (used when option SUPPLIER_ORDER_3_STEPS_TO_BE_APPROVED is set)", "// Second approval (if option SUPPLIER_ORDER_3_STEPS_TO_BE_APPROVED is set)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies the directory path(s) for ODT document templates used by the generic supplier order ODT module.', 'Read in doc_generic_supplier_order_odt.modules.php at line 133 (split into list of dirs), line 160 (display in UI), and line 168 (existence check). No admin UI write via dolibarr_set_const is present in the payload.', 'Changing this path redirects the module to a different set of ODT template directories; an invalid path disables ODT template loading.', 'Comma-separated directory path(s); empty = no custom ODT path.', 1, 0, NULL, 1, '6e6ade51fba32d0e934ee188776ca8c7da1faeecd572aa1cf2413d4436758809', 'v2', '2026-04-21T13:50:40+00:00', '["doc_generic_supplier_order_odt.modules.php:133|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''SUPPLIER_ORDER_ADDON_PDF_ODT_PATH''))));", "doc_generic_supplier_order_odt.modules.php:160|read|$texte .= getDolGlobalString(''SUPPLIER_ORDER_ADDON_PDF_ODT_PATH'');", "doc_generic_supplier_order_odt.modules.php:168|check|if (getDolGlobalString(''SUPPLIER_ORDER_ADDON_PDF_ODT_PATH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'core', 'Enables an external download link for supplier order documents.', 'Checked in core/class/commonobject.class.php:6392 and core/lib/functions.lib.php:10758. When set, a public download link is generated for order_supplier objects.', 'Enabling this constant exposes supplier order documents via a public URL; disabling it removes the external download option.', 'Non-zero/non-empty = external download enabled; 0 or unset = disabled', 1, 0, NULL, 1, 'e16bd9399ca1de20e94853e37d9eb95359584a7f714ac4b6212e7690dd2d452a', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:6392|check|if ($this->element == ''order_supplier'' && getDolGlobalInt(\"SUPPLIER_ORDER_ALLOW_EXTERNAL_DOWNLOAD\")) {", "core/lib/functions.lib.php:10758|check|if (getDolGlobalString(''SUPPLIER_ORDER_ALLOW_EXTERNAL_DOWNLOAD'') && is_object($object) && $object->element == ''order_supplier'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_ALLOW_NEGATIVE_QTY_FOR_SUPPLIER_ORDER_RETURN', 'bool', NULL, 'fourn', 'Allows negative quantities on supplier order lines to represent returns.', 'Checked with getDolGlobalString in fourn/class/fournisseur.commande.class.php:2424, reception/dispatch.php (lines 246, 618), fourn/commande/dispatch.php:833, and expedition/dispatch.php (lines 345, 720).', 'When enabled, negative quantities ($qty < 0 / $qtymouv < 0) are permitted in supplier order dispatch/reception flows to represent a return; otherwise a negative remaining-to-dispatch quantity blocks the action.', NULL, 0, 0, NULL, 1, 'cdd4592000de1fd791b546b072a0d4e9cca0d2e1f22993d1988cae4740841a8b', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''SUPPLIER_ORDER_ALLOW_NEGATIVE_QTY_FOR_SUPPLIER_ORDER_RETURN'') && $qty < 0) {", "if ($remaintodispatch < 0 && !getDolGlobalString(''SUPPLIER_ORDER_ALLOW_NEGATIVE_QTY_FOR_SUPPLIER_ORDER_RETURN'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_AUTOADD_USER_CONTACT', 'string', NULL, 'fourn', 'When set, automatically adds the approving user as a ''SALESREPFOLL'' internal contact on the supplier order once it moves to validated/accepted status.', 'In fourn/class/fournisseur.commande.class.php:1358, after the SQL status update succeeds, if getDolGlobalString(''SUPPLIER_ORDER_AUTOADD_USER_CONTACT'') is true, add_contact($user->id, ''SALESREPFOLL'', ''internal'', 1) is called.', 'Enabling it auto-populates the internal follow-up contact list of the supplier order with the validating/approving user.', 'Boolean-like truthy check via getDolGlobalString().', 1, 0, NULL, 1, 'b776cc32400a1e5fdacc12885e366e6f7d4770b59b0a2f95097fb4ae2460a1d4', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/class/fournisseur.commande.class.php:1358: if (getDolGlobalString(''SUPPLIER_ORDER_AUTOADD_USER_CONTACT'')) {", "fourn/class/fournisseur.commande.class.php: $result = $this->add_contact($user->id, ''SALESREPFOLL'', ''internal'', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_CAN_UPDATE_BUYINGPRICE_DURING_RECEIPT', 'string', NULL, 'fourn', 'Allows updating the buying price of a product automatically during supplier order receipt/dispatch.', 'Checked in 12 occurrences in reception/dispatch.php, fourn/commande/dispatch.php (multiple lines), and also at reception/dispatch.php:268 and fourn/commande/dispatch.php:287 where actual price update logic executes when the constant is set.', 'When enabled, the buying price for products is updated during the dispatch/receipt process; without it, prices remain unchanged at receipt time.', '0 or unset = buying price not updated during receipt; non-empty = buying price updated during receipt', 1, 0, NULL, 1, '91be7260b5dbe4d24fada47096704b9b5215896eb61507be800bcae331196af4', 'v2', '2026-04-21T11:16:15+00:00', '["reception/dispatch.php:834|check|if (getDolGlobalString(''SUPPLIER_ORDER_CAN_UPDATE_BUYINGPRICE_DURING_RECEIPT'')) {", "reception/dispatch.php:268|check|if (!$error && getDolGlobalString(''SUPPLIER_ORDER_CAN_UPDATE_BUYINGPRICE_DURING_RECEIPT'')) {", "fourn/commande/dispatch.php:287|check|if (!$error && getDolGlobalString(''SUPPLIER_ORDER_CAN_UPDATE_BUYINGPRICE_DURING_RECEIPT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_DEFAULT_PAYMENT_MODE_ID', 'string', NULL, 'fourn', 'Provides a fallback default payment mode (mode_reglement_id) for a new supplier order when the thirdparty has none configured.', 'Used in fourn/commande/card.php:1954-1955, the same pattern as SUPPLIER_ORDER_DEFAULT_PAYMENT_TERM_ID: applied only if $mode_reglement_id (initialized from societe->mode_reglement_supplier_id) is still empty.', 'When set, supplier orders created for a thirdparty without a specific payment mode default to this value instead of remaining empty/0.', 'Integer/string: a payment mode (mode_reglement) row id; unset means no override is applied.', 1, 0, NULL, 1, '401a9010456efae5b5332b3f6cd4f778e2003830b8feb0526ded9d29e6c67650', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:1954|check|if (empty($mode_reglement_id) && getDolGlobalString(''SUPPLIER_ORDER_DEFAULT_PAYMENT_MODE_ID'')) {", "fourn/commande/card.php:1955|read|$mode_reglement_id = getDolGlobalString(''SUPPLIER_ORDER_DEFAULT_PAYMENT_MODE_ID'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_DEFAULT_PAYMENT_TERM_ID', 'string', NULL, 'fourn', 'Provides a fallback default payment term (cond_reglement_id) for a new supplier order when the thirdparty has none configured.', 'Used in fourn/commande/card.php:1951-1952: `if (empty($cond_reglement_id) && getDolGlobalString(''SUPPLIER_ORDER_DEFAULT_PAYMENT_TERM_ID'')) { $cond_reglement_id = getDolGlobalString(...); }`, applied only after the thirdparty''s own cond_reglement_supplier_id is checked and found empty.', 'When set, supplier orders created for a thirdparty without a specific payment term default to this value instead of remaining empty/0.', 'Integer/string: a payment term (cond_reglement) row id; unset means no override is applied.', 1, 0, NULL, 1, '0df98476d01221628459ea11abaa032dd29dd08b806a66b36984bee8d8b0af2f', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:1951|check|if (empty($cond_reglement_id) && getDolGlobalString(''SUPPLIER_ORDER_DEFAULT_PAYMENT_TERM_ID'')) {", "fourn/commande/card.php:1952|read|$cond_reglement_id = getDolGlobalString(''SUPPLIER_ORDER_DEFAULT_PAYMENT_TERM_ID'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_DISABLE_CLASSIFY_BILLED_FROM_SUPPLIER_ORDER', 'bool', NULL, 'fourn', 'Disallows manually classifying a supplier order as billed directly from the order card when it has no linked supplier invoice.', 'Has an admin UI toggle in supplier_order/admin/supplier_order.php:550 (`print ajax_constantonoff(''SUPPLIER_ORDER_DISABLE_CLASSIFY_BILLED_FROM_SUPPLIER_ORDER'');`), labeled ''SupplierOrderClassifyBilledWithoutInvoice''. Checked in fourn/commande/card.php:3046 to decide whether the ''ClassifyBilled'' button is shown when there''s no linked invoice_supplier.', 'When enabled, the ''Classify billed'' button/action is hidden on supplier orders lacking a linked supplier invoice, forcing billing status to be set only via an actual linked invoice; when disabled (default) users can manually mark such orders billed.', 'Boolean: on/off via ajax_constantonoff; truthy disables manual classify-billed for orders without a linked invoice.', 0, 0, NULL, 1, '4503ece887f3cfac6035abbc5d92ab5c681583e42260454350f2ca7e92d03cb3', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_order/admin/supplier_order.php:550|print ajax_constantonoff(''SUPPLIER_ORDER_DISABLE_CLASSIFY_BILLED_FROM_SUPPLIER_ORDER'');", "fourn/commande/card.php:3046|check|if (!empty($object->linkedObjectsIds[''invoice_supplier'']) || (empty(...) && !getDolGlobalInt(''SUPPLIER_ORDER_DISABLE_CLASSIFY_BILLED_FROM_"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_DISABLE_STOCK_DISPATCH_WHEN_TOTAL_REACHED', 'bool', NULL, 'reception', 'Hides dispatch input rows for lines where the ordered quantity has already been fully received.', 'Documented in fourn/commande/dispatch.php:743-744: ''Nb of predefined product lines to dispatch (already done or not) if SUPPLIER_ORDER_DISABLE_STOCK_DISPATCH_WHEN_TOTAL_REACHED is off (default) or nb of line that remain to dispatch if SUPPLIER_ORDER_DISABLE_STOCK_DISPATCH_WHEN_TOTAL_REACHED is on.'' Also in reception/dispatch.php:604 and expedition/dispatch.php:568. 6 occurrences.', 'When enabled, only lines with remaining quantity to dispatch are shown, hiding fully-received lines; when disabled (default), all lines are shown.', '0 or unset = all lines shown (default); non-empty = only lines with remaining quantity shown', 1, 0, NULL, 1, 'd9f4693741775621f03bdbc18f92936a4d4ec17c6841a639226bae6efc23c6bd', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/commande/dispatch.php:743  // Nb of predefined product lines to dispatch (already done or not) if SUPPLIER_ORDER_DISABLE_STOCK_DISPATCH_WHEN_TOTAL_REACHED is off (default)", "fourn/commande/dispatch.php:744  // or nb of line that remain to dispatch if SUPPLIER_ORDER_DISABLE_STOCK_DISPATCH_WHEN_TOTAL_REACHED is on.", "reception/dispatch.php:604  // or nb of line that remain to dispatch if SUPPLIER_ORDER_DISABLE_STOCK_DISPATCH_WHEN_TOTAL_REACHED is on.", "reception/dispatch.php:622|check|if ($remaintodispatch || !getDolGlobalString(''SUPPLIER_ORDER_DISABLE_STOCK_DISPATCH_WHEN_TOTAL_REACHED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_DISPATCH_FORCE_QTY_INPUT_TO_ZERO', 'string', NULL, 'reception', 'Forces the default quantity input to zero in supplier order dispatch forms instead of pre-filling the remaining quantity.', 'Checked in 3 occurrences in expedition/dispatch.php:1232, reception/dispatch.php:994, and fourn/commande/dispatch.php:1018. When set, the default value for qty inputs is 0; when unset, inputs are pre-filled with $remaintodispatch.', 'When enabled, operators must manually enter all quantities during dispatch (inputs default to 0); when disabled, inputs are pre-filled with the remaining quantity to dispatch.', '0 or unset = qty inputs pre-filled with remaining quantity; non-empty = qty inputs default to 0', 1, 0, NULL, 1, '7bb1e45274c1b55d4acc96930f2ac72b19af7d20bafdb2741a2a56ee3631f747', 'v2', '2026-04-21T11:16:15+00:00', '["expedition/dispatch.php:1232|read|$amounttosuggest = (GETPOSTISSET(''qty''.$suffix) ? GETPOSTINT(''qty''.$suffix) : (!getDolGlobalString(''SUPPLIER_ORDER_DISPATCH_FORCE_QTY_INPUT_TO_ZERO'') ? $remaintodispatch : 0));", "reception/dispatch.php:994|read|print ''<input id=\"qty''.$suffix.''\" onchange=\"onChangeDispatchLineQty($(this))\" name=\"qty''.$suffix.''\" data-index=\"''.$i.''\" data-type=\"text\" class=\"width50 right qtydispatchinput\" valu", "fourn/commande/dispatch.php:1018|read|print ''<input id=\"qty''.$suffix.''\" name=\"qty''.$suffix.''\" type=\"number\" step=\"any\" class=\"width50 right qtydispatchinput\" value=\"''.(GETPOSTISSET(''qty''.$suffix) ? GETPOSTINT(''qty''.$su"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_EDIT_BUYINGPRICE_DURING_RECEIPT', 'string', NULL, 'reception', 'Enables an editable buying price field during the supplier order receipt/dispatch process.', 'Checked in 6 occurrences exclusively in reception/dispatch.php and fourn/commande/dispatch.php. All occurrences include the developer note ''// Not tested !'' indicating this feature is not fully verified in code.', 'When enabled, a buying price input field is shown during dispatch so operators can edit the buying price at receipt time; the feature is marked ''Not tested'' in the source code.', '0 or unset = buying price not editable during receipt; non-empty = buying price editable during receipt', 1, 0, NULL, 1, '5125f9e259d56833079c0d2020fd7ba14f7d31275bb4af8371d568a3672aae76', 'v2', '2026-04-21T11:16:15+00:00', '["reception/dispatch.php:751|check|if (getDolGlobalString(''SUPPLIER_ORDER_EDIT_BUYINGPRICE_DURING_RECEIPT'')) { // Not tested !", "reception/dispatch.php:810|check|if (getDolGlobalString(''SUPPLIER_ORDER_EDIT_BUYINGPRICE_DURING_RECEIPT'')) { // Not tested !", "fourn/commande/dispatch.php:940|check|if (getDolGlobalString(''SUPPLIER_ORDER_EDIT_BUYINGPRICE_DURING_RECEIPT'')) { // Not tested !"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_FORBID_EDIT_PROJECT', 'string', NULL, 'fourn', 'Forbids editing the linked project on a supplier (purchase) order once it is no longer in draft/provisional status.', 'Used in fourn/commande/card.php:185: `$caneditproject = !getDolGlobalString(''SUPPLIER_ORDER_FORBID_EDIT_PROJECT'') || ($object->status == CommandeFournisseur::STATUS_DRAFT && preg_match(''/^[\(]?PROV/i'', $object->ref));`.', 'When set, the project field becomes non-editable on supplier orders except while the order is still a draft with a provisional ref (PROV...); when unset the project can always be edited (subject to other permissions).', 'Boolean: truthy forbids editing project on non-draft supplier orders; unset/false allows editing at any status.', 1, 0, NULL, 1, '7a24bea6b785911e4e31e09feb61a05602b4d711d2a9a53167fd2259e21d8adc', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:185|read|$caneditproject = !getDolGlobalString(''SUPPLIER_ORDER_FORBID_EDIT_PROJECT'') || ($object->status == CommandeFournisseur::STATUS_DRAFT && preg_match(...));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_FREE_TEXT', 'string', NULL, 'supplier_order', 'Stores free/custom footer text to include on generated supplier order documents.', 'Written from supplier_order/admin/supplier_order.php:180 via dolibarr_set_const() when the admin saves the supplier order module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated supplier order documents/PDFs; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'supplier_order/admin/supplier_order.php', 1, '9053fbe46d5f724831334f39b32dc017edd4854479782933a020139b6aef7f2e', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_order/admin/supplier_order.php:180|write|$res1 = dolibarr_set_const($db, \"SUPPLIER_ORDER_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_HIDE_VALIDATED', 'bool', NULL, 'core', 'Hides the ''Validated'' status entry from the supplier orders left-menu status submenu.', 'Checked in core/menus/standard/eldy.lib.php:1485; when truthy, the menu entry for StatusSupplierOrderValidated is skipped while other statuses (draft, approved, in process, received, canceled, refused) remain.', 'Enabling it removes the ''Validated'' status shortcut from the supplier orders left menu, reducing menu clutter but not affecting actual order data or list filtering elsewhere.', 'Truthy hides the Validated status menu entry; empty/0 shows it (default).', 1, 0, NULL, 1, 'bb95ac391b4a6d1f0e8d8d46c93c2ddb22868a4cf3bcc067bcac7af620fbe4a5', 'v2', '2026-07-24T07:05:23+00:00', '["core/menus/standard/eldy.lib.php:1485: if (!getDolGlobalString(''SUPPLIER_ORDER_HIDE_VALIDATED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_MODE_OPTIONAL', 'string', NULL, 'fourn', 'Makes the order method (methodecommande, e.g. by fax/mail/EDI) optional when validating/creating a supplier order, instead of mandatory.', 'Checked in fourn/commande/card.php:1298: `} elseif ($methodecommande <= 0 && !getDolGlobalInt(''SUPPLIER_ORDER_MODE_OPTIONAL'')) { setEventMessages($langs->trans("ErrorFieldRequired", ..."OrderMode"...` — without this constant set, an unselected order method blocks the ''commande'' action with a required-field error.', 'When enabled, users can submit/create the supplier order action without choosing an order method; when unset (default) the order method field is mandatory and its absence blocks the action with an error message.', 'Boolean/int: truthy makes the order-mode field optional; unset/0 (default) makes it required.', 1, 0, NULL, 1, 'd3b3339d77d05272c8ee25f930d2977f8a5b1442da9b9edecc5c1af40190ecc4', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:1298|read|} elseif ($methodecommande <= 0 && !getDolGlobalInt(''SUPPLIER_ORDER_MODE_OPTIONAL'')) {", "setEventMessages($langs->trans(\"ErrorFieldRequired\", $langs->transnoentities(\"OrderMode\")), null, ''errors'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_MORE_THAN_WISHED', 'string', NULL, 'reception', 'When set, allows a supplier order/reception to be marked fully received even if more products were received than ordered.', 'Checked in reception/class/reception.class.php:921 and fourn/class/fournisseur.commande.class.php:3858: if quantities differ, the elseif branch sets the order/reception status to totally received when getDolGlobalInt/String(''SUPPLIER_ORDER_MORE_THAN_WISHED'') is true.', 'Enabling it lets receptions close as fully received despite over-delivery instead of only partial reception status.', 'Not documented in comments; used as a boolean truthy check.', 1, 0, NULL, 1, '6d2e0c8ceca9ea45b7ff353f3b5b2e016f879b592d83f9a61e6c74b2c84cb58e', 'v2', '2026-07-24T07:05:23+00:00', '["reception/class/reception.class.php:921: } elseif (getDolGlobalInt(''SUPPLIER_ORDER_MORE_THAN_WISHED'')) {", "fourn/class/fournisseur.commande.class.php:3858: } elseif (getDolGlobalString(''SUPPLIER_ORDER_MORE_THAN_WISHED'')) {", "fourn/class/fournisseur.commande.class.php: //set livraison to ''tot'' if more products received than wished."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_NOCHECK_ONBUY_PRODUCTS_ONVALID', 'string', NULL, 'fourn', 'Skips the check that all product lines on a supplier order are active/buyable when validating the order.', 'In fourn/class/fournisseur.commande.class.php:814, valid() normally calls $this->checkActiveProductInLines(''onbuy'') and aborts if it fails; setting this constant bypasses that check.', 'Enabling it allows validating supplier orders that contain products not flagged as active for purchase (onbuy), removing a safety check.', 'Boolean-like truthy check via getDolGlobalBool().', 1, 0, NULL, 1, '7127b0f1f33bec1b89c73805d7bae9b05d532e69f37c42381036d669caf3d9af', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/class/fournisseur.commande.class.php:814: if (!getDolGlobalBool(''SUPPLIER_ORDER_NOCHECK_ONBUY_PRODUCTS_ONVALID'') && !$this->checkActiveProductInLines(''onbuy'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_NO_DIRECT_APPROVE', 'string', NULL, 'fourn', 'Disables the direct approval button on supplier orders, requiring a separate approval workflow step.', 'Checked across 4 occurrences in fourn/commande/card.php:1215, :2883 and fourn/commande/list.php:378, :1291. When set, the direct approve action is hidden from both the order card and the list view.', 'Enabling this forces approvers to go through a dedicated approval step rather than using a single-click approval on the order.', 'Empty/0 = direct approval button visible; truthy = direct approval button hidden', 1, 0, NULL, 1, '498f86b26206122ff7847e81c76c79a4c3068f19bffd8f0d0ba46d28f29cbc10', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/commande/card.php:1215|check|if (!$error && !getDolGlobalString(''SUPPLIER_ORDER_NO_DIRECT_APPROVE'') && $usercanapprove && ...) {", "fourn/commande/card.php:2883|check|if ($usercanapprove && !getDolGlobalString(''SUPPLIER_ORDER_NO_DIRECT_APPROVE'')) {", "fourn/commande/list.php:378|check|if (!getDolGlobalString(''SUPPLIER_ORDER_NO_DIRECT_APPROVE'') && $permissiontoapprove && ...) {", "fourn/commande/list.php:1291|check|if ($permissiontoapprove && !getDolGlobalString(''SUPPLIER_ORDER_NO_DIRECT_APPROVE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_REOPEN_BY_APPROVER2_ONLY', 'string', NULL, 'fourn', 'Restricts the ''reopen/disapprove'' button on a two/three-step-approved supplier order so only the second-level approver can reopen it.', 'In fourn/commande/card.php:2968-2969, mirrors SUPPLIER_ORDER_REOPEN_BY_APPROVER_ONLY but applies to $usercanapprovesecond and $object->user_approve_id2, gated behind SUPPLIER_ORDER_3_STEPS_TO_BE_APPROVED being enabled.', 'When set, only the recorded second-level approver ($object->user_approve_id2) can reopen the order via this path; otherwise any user with the second-approve right can.', 'Boolean: truthy restricts reopening (second approval level) to the recorded second approver only.', 1, 0, NULL, 1, '1f539f486cfa2f6c3f08f865ed9e25e8421632beba9178d40a3a4d2e7a407dc8', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:2968|check|if (!getDolGlobalString(''SUPPLIER_ORDER_REOPEN_BY_APPROVER2_ONLY'')", "fourn/commande/card.php:2969|read||| (getDolGlobalString(''SUPPLIER_ORDER_REOPEN_BY_APPROVER2_ONLY'') && $user->id == $object->user_approve_id2)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_REOPEN_BY_APPROVER_ONLY', 'string', NULL, 'fourn', 'Restricts the ''reopen/disapprove'' button on an accepted supplier order so only the specific user who approved it (first approval level) can reopen it.', 'In fourn/commande/card.php:2961-2962: `if (!getDolGlobalString(''SUPPLIER_ORDER_REOPEN_BY_APPROVER_ONLY'') || (getDolGlobalString(''SUPPLIER_ORDER_REOPEN_BY_APPROVER_ONLY'') && $user->id == $object->user_approve_id)) { print ''<a ...Disapprove...` shown to users with $usercanapprove right.', 'When set, only the user recorded as $object->user_approve_id can see/use the reopen (disapprove) button on the order, even if other users hold the approve permission; when unset any user with approve rights can reopen it.', 'Boolean: truthy restricts reopening to the recorded first-level approver only.', 1, 0, NULL, 1, 'be0165ef8bef5bf89fc6fd6171f5ab742d6de6d2c024ed7be88a31edf49aa275', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:2961|check|if (!getDolGlobalString(''SUPPLIER_ORDER_REOPEN_BY_APPROVER_ONLY'')", "fourn/commande/card.php:2962|read||| (getDolGlobalString(''SUPPLIER_ORDER_REOPEN_BY_APPROVER_ONLY'') && $user->id == $object->user_approve_id)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_SENDBYEMAIL_FOR_ALL_STATUS', 'string', NULL, 'fourn', 'Allows the ''Send by email'' action button on a supplier order to appear regardless of order status, not just for accepted/approved statuses.', 'In fourn/commande/card.php:2950: `if (in_array($object->status, array(CommandeFournisseur::STATUS_ACCEPTED, 3, 4, 5)) || getDolGlobalString(''SUPPLIER_ORDER_SENDBYEMAIL_FOR_ALL_STATUS'')) { ... print dolGetButtonAction(...''SendMail''...`.', 'When enabled, the send-by-email button is shown for supplier orders in any status, not only STATUS_ACCEPTED (and statuses 3/4/5); the underlying send permission (usercanorder) is still required.', 'Boolean: truthy shows the send-by-email button for all order statuses; unset restricts it to statuses ACCEPTED/3/4/5.', 1, 0, NULL, 1, '42e0d135c55e5828ea82789101457c4d7c24fd260bc8adf5f4be67b0002c96e1', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:2950|check|if (in_array($object->status, array(CommandeFournisseur::STATUS_ACCEPTED, 3, 4, 5)) || getDolGlobalString(''SUPPLIER_ORDER_SENDBYEMAIL_FOR_ALL_STATUS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_STATUS_FOR_VIRTUAL_STOCK', 'string', NULL, 'product', 'List of supplier order status codes counted as ''ordered'' when computing a product''s virtual (theoretical) stock.', 'Used in product/class/product.class.php:6544 with default ''3,4'' to filter which CommandeFournisseur statuses are included via load_stats_commande_fournisseur() when isModEnabled(''supplier_order'') in the virtual stock computation block (lines 6542-6553).', 'Changing the status list changes which supplier orders (by status) are counted as incoming stock in the virtual stock calculation.', 'Comma-separated list of supplier order status codes; code default is ''3,4''.', 0, 0, NULL, 1, '73551d088d16a74ceef6a922e52aee57deba8c1b36f58049ec72fee7f1efce7f', 'v2', '2026-07-24T07:05:23+00:00', '["product/class/product.class.php:6544: $filterStatus = getDolGlobalString(''SUPPLIER_ORDER_STATUS_FOR_VIRTUAL_STOCK'', ''3,4'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_TO_INVOICE_STATUS', 'string', NULL, 'fourn', 'List of supplier order status codes eligible to be shown/selected for creating a supplier invoice from a thirdparty''s billable orders.', 'Used in fourn/card.php:769-773; if unset, the query filters on CommandeFournisseur::STATUS_RECEIVED_COMPLETELY only (matching htdocs/fourn/commande/list.php), otherwise it filters on the comma-separated status list given by this constant.', 'Setting it broadens or narrows which supplier order statuses (e.g. ordered/partially received/fully received) are considered billable on the thirdparty card, instead of only fully-received orders.', 'Comma-separated list of CommandeFournisseur status codes; code default when unset is STATUS_RECEIVED_COMPLETELY only.', 0, 0, NULL, 1, 'da63edb869c464bc9773123f93abfad3c478c0b18bcfbfb5960009fe4caccfb6', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/card.php:769: if (!getDolGlobalString(''SUPPLIER_ORDER_TO_INVOICE_STATUS'')) {", "fourn/card.php:770: $sql2 .= \" AND c.fk_statut IN (\".$db->sanitize((string) CommandeFournisseur::STATUS_RECEIVED_COMPLETELY).\")\"; //  Must match filter in htdocs/fourn/commande/list.php", "fourn/card.php:773: $sql2 .= \" AND c.fk_statut IN (\".$db->sanitize(getDolGlobalString(''SUPPLIER_ORDER_TO_INVOICE_STATUS'')).\")\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_USE_DISPATCH_STATUS', 'bool', NULL, 'fourn', 'Enables tracking a separate dispatch/reception status for supplier orders, distinct from the order''s own status.', 'Set through the select at supplier_order/admin/supplier_order.php:539, and checked with getDolGlobalInt/getDolGlobalString in reception/class/reception.class.php:883, fourn/class/fournisseur.commande.class.php (lines 950, 2381, 2749, 3796), and fourn/commande/dispatch.php.', 'When enabled, order status logic checks that all receptions are approved before allowing a ''total/done'' status, per the explicit comment in fournisseur.commande.class.php:2750.', NULL, 0, 0, 'supplier_order/admin/supplier_order.php', 1, '810d2bf45d7e261349099b332c943bcf202d34eaa059323ca09b87d430cc45b7', 'v2', '2026-07-24T06:41:12+00:00', '["// If option SUPPLIER_ORDER_USE_DISPATCH_STATUS is on, we check all reception are approved to allow status \"total/done\"", "if (getDolGlobalString(''SUPPLIER_ORDER_USE_DISPATCH_STATUS'') && !isModEnabled(\"reception\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_USE_DISPATCH_STATUS_NEED_APPROVE', 'bool', NULL, 'fourn', 'When the dispatch-status workflow (SUPPLIER_ORDER_USE_DISPATCH_STATUS) is active, additionally blocks marking a reception as fully done if any dispatched line was denied/refused.', 'In fourn/class/fournisseur.commande.class.php:2760, nested inside a getDolGlobalString(''SUPPLIER_ORDER_USE_DISPATCH_STATUS'') block, when type==''tot'' and this constant is set, lines with dispatch status ''denied'' (getDispachedLines(2)) block the total/done transition with error ''ErrorCantSetReceptionToTotalDoneWithReceptionDenied''.', 'Enabling it (together with SUPPLIER_ORDER_USE_DISPATCH_STATUS) prevents closing a reception as fully received while any line dispatch was refused/denied.', 'Boolean-like truthy check; only effective when SUPPLIER_ORDER_USE_DISPATCH_STATUS is also enabled.', 1, 0, NULL, 1, '458306e8593ff91014522080a3309650b0f33df2d44fed93157f4ad647061b58', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/class/fournisseur.commande.class.php:2760: if (!$error && getDolGlobalString(''SUPPLIER_ORDER_USE_DISPATCH_STATUS_NEED_APPROVE'') && ($type == ''tot'')) {\t// Accept to move to reception done, only if status of all line are ok (refuse denied)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_USE_HOUR_FOR_DELIVERY_DATE', 'bool', NULL, 'fourn', 'Enables time (hour) input in addition to date for the supplier order delivery date field.', 'Checked across 7 occurrences in fourn/commande/card.php:2059, :2494, :2615, :2623 and PDF modules core/modules/supplier_order/doc/pdf_cornas.modules.php:1366, pdf_muscadet.modules.php:1233, and core/modules/mrp/doc/pdf_vinci.modules.php:1142.', 'Enabling this adds an hour picker to the delivery date field on supplier orders and includes the time in generated PDF documents.', 'Empty/0 = date only for delivery date; truthy = date and time for delivery date', 1, 0, NULL, 1, '6e4bff23b61b901d43babb7094ec73636cf457dc2572e2cf6e5edb27566e70d3', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/commande/card.php:2059|check|if (getDolGlobalString(''SUPPLIER_ORDER_USE_HOUR_FOR_DELIVERY_DATE'')) {", "fourn/commande/card.php:2494|check|if (getDolGlobalString(''SUPPLIER_ORDER_USE_HOUR_FOR_DELIVERY_DATE'')) {", "core/modules/supplier_order/doc/pdf_cornas.modules.php:1366|check|if (getDolGlobalString(''SUPPLIER_ORDER_USE_HOUR_FOR_DELIVERY_DATE'')) {", "core/modules/mrp/doc/pdf_vinci.modules.php:1142|check|if (getDolGlobalString(''SUPPLIER_ORDER_USE_HOUR_FOR_DELIVERY_DATE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_ORDER_WITH_PREDEFINED_PRICES_ONLY', 'string', NULL, 'fourn', 'Restricts supplier orders to use only products with predefined supplier prices.', 'Checked at fourn/class/fournisseur.commande.class.php:2105 and fourn/commande/card.php:999 with comment ''// Not the common case''. Also read at fourn/commande/card.php:2809: ''$senderissupplier = getDolGlobalInt(''SUPPLIER_ORDER_WITH_PREDEFINED_PRICES_ONLY'')''. No admin UI write path is present.', 'When set to 1, only products with pre-configured supplier prices can be added to supplier orders; when not set or 0, any product can be added.', '0 or not set = any product can be added (common case); 1 = only products with predefined supplier prices allowed (not the common case).', 1, 0, NULL, 1, '759b2a7557bc7f3e140c652557500d396804b0b2292eb5f32877cc00683cb54a', 'v2', '2026-04-21T11:16:15+00:00', '["fourn/class/fournisseur.commande.class.php:2105|check|if (getDolGlobalInt(''SUPPLIER_ORDER_WITH_PREDEFINED_PRICES_ONLY'') == 1) {\t// Not the common case", "fourn/commande/card.php:999|check|if (getDolGlobalInt(''SUPPLIER_ORDER_WITH_PREDEFINED_PRICES_ONLY'') == 1) {\t\t// Not the common case", "fourn/commande/card.php:2809|read|$senderissupplier = getDolGlobalInt(''SUPPLIER_ORDER_WITH_PREDEFINED_PRICES_ONLY'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PAYMENT_ADDON', 'string', NULL, 'fourn', 'Selects the numbering module (addon) used to generate supplier payment references.', 'Set via supplier_invoice/admin/supplier_payment.php:91 dolibarr_set_const, checked at line 294, and read/assigned in fourn/class/paiementfourn.class.php:815/823 with fallback assignments to ''mod_supplier_payment_bronan'' or ''mod_supplier_payment_brodator''.', 'Changing it swaps which numbering module class is used to compute supplier payment references, per the explicit class-doc comment ''according to numbering module defined into constant SUPPLIER_PAYMENT_ADDON''.', NULL, 0, 0, 'supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php', 1, 'c434de57d4eed39bd8f16b3b6392e9475c3bb99eaa0c3b3097c9e8f56bdd6c00', 'v2', '2026-07-24T06:41:12+00:00', '["*      according to numbering module defined into constant SUPPLIER_PAYMENT_ADDON", "$conf->global->SUPPLIER_PAYMENT_ADDON = ''mod_supplier_payment_bronan'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PAYMENT_ADDON_PDF', 'string', NULL, 'supplier_invoice', 'Selects the default PDF template (model) used to generate supplier payment documents.', 'Set/deleted via supplier_invoice/admin/supplier_payment.php (dolibarr_set_const at line 104, dolibarr_del_const at lines 99/116), checked at line 417, and read in fourn/class/paiementfourn.class.php:902/903 and fourn/paiement/card.php:418 as fallback for $modelpdf.', 'Changing it changes which PDF model is used by default to build supplier payment PDFs when the payment object has no specific model_pdf set.', NULL, 0, 0, 'supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php|supplier_invoice/admin/supplier_payment.php', 1, '994a346eb6ad1c82d22a3d42d4e949acd1c19e3ce65c57332125d4cac15a03de', 'v2', '2026-07-24T06:41:12+00:00', '["if (dolibarr_set_const($db, \"SUPPLIER_PAYMENT_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "$modelpdf = (!empty($object->model_pdf) ? $object->model_pdf : getDolGlobalString(''SUPPLIER_PAYMENT_ADDON_PDF''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PAYMENT_BRODATOR_MASK', 'string', NULL, 'core', 'Stores the numbering mask (template) used by the ''brodator'' numbering module for supplier payment references.', 'Read/written via the admin mask-editing form in core/modules/supplier_payment/mod_supplier_payment_brodator.php:94 (input field ''masksupplierpayment'') and consumed in getNextValue() at line 140 to compute the next supplier payment reference; if empty, getNextValue() returns an error ''NotConfigured''.', 'Changing the mask changes the format of newly generated supplier payment references; an empty/invalid mask prevents generating any new reference.', 'A Dolibarr generic numbering mask string (same syntax as other ''Generic'' numbering modules, e.g. containing {000000} placeholders); no explicit example given in the excerpt.', 0, 0, NULL, 1, 'fa8b140af3a2f89a7cc73c6486280b32ae279a6905c60ae313153fe1d90604ac', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_payment/mod_supplier_payment_brodator.php:94: value=\"''.getDolGlobalString(\"SUPPLIER_PAYMENT_BRODATOR_MASK\")", "core/modules/supplier_payment/mod_supplier_payment_brodator.php:140: $mask = getDolGlobalString(\"SUPPLIER_PAYMENT_BRODATOR_MASK\");"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_ADDON', 'string', NULL, 'supplier_proposal', 'Selects the numbering module (addon) used to generate supplier proposal (request for quote) references.', 'Set via supplier_proposal/admin/supplier_proposal.php:200 dolibarr_set_const, checked at line 314, and read in supplier_proposal/class/supplier_proposal.class.php (lines 1231, 1242, 1243, 2479, 2482, 2483) as class/path for ref-numbering, per the explicit comment ''defined into SUPPLIER_PROPOSAL_ADDON''.', 'Changing it swaps the numbering module class used to compute supplier proposal references, loaded from core/modules/supplier_proposal/<value>.php.', NULL, 0, 0, 'supplier_proposal/admin/supplier_proposal.php|supplier_proposal/admin/supplier_proposal.php', 1, '2b36225e7964dac627b524916eb9ce158373de905cb9d52fa22a9ba9b410712e', 'v2', '2026-07-24T06:41:12+00:00', '["*  defined into SUPPLIER_PROPOSAL_ADDON", "if (!getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON'') || !is_readable(DOL_DOCUMENT_ROOT.\"/core/modules/supplier_proposal/\" . getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON'').\".php\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_ADDON_PDF', 'string', NULL, 'supplier_proposal', 'Selects the default PDF template (model) used to generate supplier proposal documents.', 'Set/deleted via supplier_proposal/admin/supplier_proposal.php (dolibarr_set_const at line 189, dolibarr_del_const at line 185), checked at lines 184/456, and read in supplier_proposal/class/supplier_proposal.class.php:2774/2775 and supplier_proposal/card.php:1655 as fallback for SUPPLIER_PROPOSAL_ADDON_PDF_ODT_DEFAULT.', 'Changing it changes which PDF model is used by default to build supplier proposal PDFs.', NULL, 0, 0, 'supplier_proposal/admin/supplier_proposal.php|supplier_proposal/admin/supplier_proposal.php|supplier_proposal/admin/supplier_proposal.php|supplier_proposal/admin/supplier_proposal.php', 1, '7bdd8c9e103a5e7f4aa215e38802805018082688733389a6693b52214b3a3b6c', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, \"SUPPLIER_PROPOSAL_ADDON_PDF\", empty($value) ? '''' : $value, ''chaine'', 0, '''', $conf->entity);", "} elseif (getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_ADDON_PDF_ODT_CLOSED', 'string', NULL, 'supplier_proposal', 'Default ODT document model to use for a supplier proposal''s PDF/document when the proposal is closed as refused (or otherwise closed, non-signed).', 'Used in supplier_proposal/class/supplier_proposal.class.php:1741 as the fallback model when closing the proposal, and offered as a selectable ODT model in the admin document-model config UI at core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:205 (field ''value4'', label ''DefaultModelSupplierProposalClosed'').', 'Setting it selects which document/PDF model is used to generate the document when a supplier proposal is closed (refused); if unset it falls back to the proposal''s own model_pdf.', 'String: an ODT model code from the list of models returned by ModelePDFSupplierProposal::liste_modeles().', 0, 0, NULL, 1, 'dff7ab8ce746d05845f463ab4e7ec7cde6ffbb036d7a5eaec0f7b97ea493a805', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_proposal/class/supplier_proposal.class.php:1741|read|$modelpdf = getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF_ODT_CLOSED'', (empty($this->model_pdf) ? '''' : $this->model_pdf));", "core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:205|read|$texte .= $form->selectarray(''value4'', $list, getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF_ODT_CLOSED''));", "''<td width=\"60%;\">''.$langs->trans(\"DefaultModelSupplierProposalClosed\").''</td>''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_ADDON_PDF_ODT_DEFAULT', 'string', NULL, 'supplier_proposal', 'Default ODT document model preselected for generating a supplier proposal''s document/PDF.', 'Used in supplier_proposal/card.php:1655 as the preselected model (falling back to SUPPLIER_PROPOSAL_ADDON_PDF if unset), and offered as a selectable ODT model in the admin config UI at core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:193 (field ''value2'', label ''DefaultModelSupplierProposalCreate'').', 'Setting it changes which ODT model is preselected in the model dropdown when creating/viewing a supplier proposal''s document; if unset it falls back to the SUPPLIER_PROPOSAL_ADDON_PDF constant.', 'String: an ODT model code from the list of models returned by ModelePDFSupplierProposal::liste_modeles().', 0, 0, NULL, 1, '8d5b8336ebddca9ba717e969f8cfc3d41e4472e7659bea13602f42bb51a7fa6a', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_proposal/card.php:1655|read|$preselected = getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF_ODT_DEFAULT'', getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF''));", "core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:193|read|$texte .= $form->selectarray(''value2'', $list, getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF_ODT_DEFAULT''));", "''<td width=\"60%;\">''.$langs->trans(\"DefaultModelSupplierProposalCreate\").''</td>''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Filesystem path to the directory containing ODT template files used to generate supplier proposal documents.', 'Read in core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:115 (`$odtPath = trim(getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF_ODT_PATH''));`) inside the module''s info() method, which builds the admin setup form for the generic ODT supplier-proposal document generator.', 'Setting this path tells the ODT document generator where to look for supplier-proposal ODT templates; edited through the module''s own setup form (setModuleOptions action).', 'Free-form filesystem path string; no enum given in payload.', 0, 0, NULL, 1, 'ef35f403909c66bbb87d216d7bd83a818e89217ce6e15154d9f3afea819e8c7a', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:115|read|$odtPath = trim(getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF_ODT_PATH''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_ADDON_PDF_ODT_TOBILL', 'string', NULL, 'supplier_proposal', 'Default ODT document model to use for a supplier proposal''s PDF/document when the proposal is closed as signed/to-bill.', 'Used in supplier_proposal/class/supplier_proposal.class.php:1746 as the fallback model when the proposal status is closed as signed ($status == 2), and offered as a selectable ODT model in the admin document-model config UI at core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:199 (field ''value3'', label ''DefaultModelSupplierProposalToBill'').', 'Setting it selects which document/PDF model is used to generate the document when a supplier proposal is validated/closed as signed and ready to bill; if unset it falls back to the proposal''s own model_pdf.', 'String: an ODT model code from the list of models returned by ModelePDFSupplierProposal::liste_modeles().', 0, 0, NULL, 1, '3212ff280d09d3d0ad27b175c7cad6b83fa046bfbd92e1f2ec079a7ad9fb2cb2', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_proposal/class/supplier_proposal.class.php:1746|read|$modelpdf = getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF_ODT_TOBILL'', (empty($this->model_pdf) ? '''' : $this->model_pdf));", "core/modules/supplier_proposal/doc/doc_generic_supplier_proposal_odt.modules.php:199|read|$texte .= $form->selectarray(''value3'', $list, getDolGlobalString(''SUPPLIER_PROPOSAL_ADDON_PDF_ODT_TOBILL''));", "''<td width=\"60%;\">''.$langs->trans(\"DefaultModelSupplierProposalToBill\").''</td>''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_ADD_BILLING_CONTACT', 'string', NULL, 'core', 'Controls whether a billing contact is added to supplier proposal PDFs.', 'Displayed as a select array in admin/pdf_other.php at line 627. Checked (negated) in pdf_zenith.modules.php at line 1431 and pdf_aurore.modules.php at line 1372; when falsy, a billing contact is included.', 'Setting this constant to a non-zero value suppresses the billing contact section in supplier proposal PDFs. Leaving it unset or zero includes the billing contact.', '0 or unset = include billing contact; non-zero = suppress billing contact.', 0, 0, 'admin/pdf_other.php', 1, 'c54998ac22bbf70b02692b7adc3261b459f2149a18b5a39ded4f8233b1bbd1d0', 'v2', '2026-04-21T13:50:40+00:00', '["admin/pdf_other.php:627|read|print $form->selectarray(\"SUPPLIER_PROPOSAL_ADD_BILLING_CONTACT\", $arrval, getDolGlobalInt(''SUPPLIER_PROPOSAL_ADD_BILLING_CONTACT''));", "core/modules/supplier_proposal/doc/pdf_zenith.modules.php:1431|check|if (!getDolGlobalInt(''SUPPLIER_PROPOSAL_ADD_BILLING_CONTACT'')) {", "core/modules/supplier_proposal/doc/pdf_aurore.modules.php:1372|check|if (!getDolGlobalInt(''SUPPLIER_PROPOSAL_ADD_BILLING_CONTACT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'core', 'Enables an external download link for supplier proposal documents.', 'Checked in core/class/commonobject.class.php:6389 and core/lib/functions.lib.php:10753. When set, a public download link is generated for supplier_proposal objects.', 'Enabling this constant exposes supplier proposal documents via a public URL; disabling it removes the external download option.', 'Non-zero/non-empty = external download enabled; 0 or unset = disabled', 1, 0, NULL, 1, '2f04e53db7d0aa5b5e2450f6faf10186d6b2be66e0720733b7aa15b9aaadadd8', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/commonobject.class.php:6389|check|if ($this->element == ''supplier_proposal'' && getDolGlobalInt(\"SUPPLIER_PROPOSAL_ALLOW_EXTERNAL_DOWNLOAD\")) {", "core/lib/functions.lib.php:10753|check|if (getDolGlobalString(''SUPPLIER_PROPOSAL_ALLOW_EXTERNAL_DOWNLOAD'') && is_object($object) && $object->element == ''supplier_proposal'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_AUTOADD_USER_CONTACT', 'string', NULL, 'supplier_proposal', 'Automatically adds the validating user as a ''SALESREPFOLL'' internal contact on a supplier proposal when it is validated.', 'Checked in supplier_proposal/class/supplier_proposal.class.php:1591 inside the valid() method; when set, it calls add_contact($user->id, ''SALESREPFOLL'', ''internal'', 1) right after marking the proposal validated.', 'Setting it causes the validating user to be automatically linked as a follow-up sales rep contact on every validated supplier proposal, without manual contact assignment.', 'Boolean-like: truthy triggers automatic add_contact() call with role ''SALESREPFOLL''.', 1, 0, NULL, 1, '73bfde5bc7ebe400343dba6670788b77ec3f91770509ddcc71155a20df71a892', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_proposal/class/supplier_proposal.class.php:1591|read|if (getDolGlobalString(''SUPPLIER_PROPOSAL_AUTOADD_USER_CONTACT'')) {", "$result = $this->add_contact($user->id, ''SALESREPFOLL'', ''internal'', 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_CLONE_ON_CREATE_PAGE', 'string', NULL, 'supplier_proposal', 'Controls whether the supplier proposal creation page shows a clone option instead of the standard creation form.', 'Checked 3 times in supplier_proposal/card.php (lines 1752, 1756, 1795) to toggle between the clone and standard creation page behaviour.', 'Enabling this setting alters the supplier proposal creation workflow to present cloning behaviour.', 'Truthy string (non-empty) = show clone-based creation; empty/not set = show standard creation form.', 1, 0, NULL, 1, '015f7583734d3f81795dbdc641022859cd39834f731694c72fd001bc283b7a6d', 'v2', '2026-04-21T11:16:15+00:00', '["supplier_proposal/card.php:1752|check|if (!getDolGlobalString(''SUPPLIER_PROPOSAL_CLONE_ON_CREATE_PAGE'')) {", "supplier_proposal/card.php:1756|check|if (getDolGlobalString(''SUPPLIER_PROPOSAL_CLONE_ON_CREATE_PAGE'')) {", "supplier_proposal/card.php:1795|check|if (getDolGlobalString(''SUPPLIER_PROPOSAL_CLONE_ON_CREATE_PAGE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_DRAFT_WATERMARK', 'string', NULL, 'supplier_proposal', 'Sets a watermark string printed on supplier proposal PDF documents that are still in draft status.', 'Configured via admin/supplier_proposal/admin/supplier_proposal.php (write at line 135, read at line 554). The PDF model core/modules/supplier_proposal/doc/pdf_aurore.modules.php checks it at line 190 and applies it as $this->watermark at line 191 when the proposal status is STATUS_DRAFT.', 'When set, draft supplier proposals get a visible watermark on their generated PDF; when empty, no watermark is applied.', NULL, 0, 0, 'supplier_proposal/admin/supplier_proposal.php|supplier_proposal/admin/supplier_proposal.php', 1, '6eb86efcd762a9d14f331568dd8ce47c30eac766f612c2bd07c6f4a4c7ccbb82', 'v2', '2026-07-24T06:41:12+00:00', '["if ($object->status == $object::STATUS_DRAFT && (getDolGlobalString(''SUPPLIER_PROPOSAL_DRAFT_WATERMARK''))) {", "$this->watermark = getDolGlobalString(''SUPPLIER_PROPOSAL_DRAFT_WATERMARK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_FREE_TEXT', 'string', NULL, 'supplier_proposal', 'Stores free/custom footer text to include on generated supplier proposal (price request) documents.', 'Written from supplier_proposal/admin/supplier_proposal.php:150 via dolibarr_set_const() when the admin saves the supplier proposal module setup form (a free-text field submitted by the user).', 'Changing it changes the custom text block rendered on generated supplier proposal documents/PDFs; no other effects are indicated by the code.', 'Free-form string entered by the admin in the setup page; no fixed value list.', 0, 0, 'supplier_proposal/admin/supplier_proposal.php', 1, 'b88b2f66949c708f6851a2d53e10d241a96b7a50e9d0faf37c332a9be7240f7f', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_proposal/admin/supplier_proposal.php:150|write|$res = dolibarr_set_const($db, \"SUPPLIER_PROPOSAL_FREE_TEXT\", $freetext, ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_NOCHECK_ONBUY_PRODUCTS_ONVALID', 'string', NULL, 'supplier_proposal', 'Disables the check that all product lines on a supplier proposal are active ''on buy'' products when validating the proposal.', 'Checked in supplier_proposal/class/supplier_proposal.class.php:1507 in the valid() method; when set, the call to checkActiveProductInLines(''onbuy'') is skipped, allowing validation even if some lines reference inactive/non-purchasable products.', 'Setting it bypasses a data-integrity check, letting users validate supplier proposals containing products not flagged as purchasable; without it, validation fails if any line has an inactive-for-buy product.', 'Boolean-like: truthy skips the checkActiveProductInLines(''onbuy'') validation check.', 1, 0, NULL, 1, 'eaca5b22da7c1bb8b1190ac066e7d5070c981be0aa11b81d22ae21e52f41bbbf', 'v2', '2026-07-24T07:05:23+00:00', '["supplier_proposal/class/supplier_proposal.class.php:1507|check|if (!getDolGlobalBool(''SUPPLIER_PROPOSAL_NOCHECK_ONBUY_PRODUCTS_ONVALID'') && !$this->checkActiveProductInLines(''onbuy'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_PDF_HIDE_PAYMENTTERMCOND', 'bool', NULL, 'core', 'Hides the ''Payment conditions'' block on the supplier proposal PDF document.', 'Checked in core/modules/supplier_proposal/doc/pdf_aurore.modules.php:786: `if (!getDolGlobalString(''SUPPLIER_PROPOSAL_PDF_HIDE_PAYMENTTERMCOND'') && ($object->cond_reglement_code || $object->cond_reglement)) { ... }` — the payment-conditions title and text are only printed when this constant is falsy and the proposal has payment condition data.', 'Setting this constant suppresses the payment-conditions section of the supplier proposal PDF even if the proposal has cond_reglement data; unset (default) shows it when data is present.', 'Truthy/falsy flag; truthy = hide the payment conditions block.', 0, 0, NULL, 1, '828870bd48e6c498ff4eb85dbb226328b5f883a4eb496372a3769dad46e30b67', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_proposal/doc/pdf_aurore.modules.php:786|check|if (!getDolGlobalString(''SUPPLIER_PROPOSAL_PDF_HIDE_PAYMENTTERMCOND'') && ($object->cond_reglement_code"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_PDF_SHOW_PAYMENTTERMMODE', 'bool', NULL, 'core', 'Shows the payment mode (method) block on the supplier proposal PDF document, in addition to payment conditions.', 'Checked in core/modules/supplier_proposal/doc/pdf_aurore.modules.php:804: `if (getDolGlobalString(''SUPPLIER_PROPOSAL_PDF_SHOW_PAYMENTTERMMODE'')) { // Show payment mode ... }`, followed by logic that prints the mode_reglement_code label unless it is CHQ or VIR.', 'Setting this constant adds a ''payment mode'' section to the supplier proposal PDF (for modes other than cheque/wire transfer); unset (default) omits this section.', 'Truthy/falsy flag; truthy = show the payment mode block.', 0, 0, NULL, 1, 'abd06eea9204f4ff7cecc393400d24bbdb24d775d3e35f8b54b0b55c47969cdf', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_proposal/doc/pdf_aurore.modules.php:804|check|if (getDolGlobalString(''SUPPLIER_PROPOSAL_PDF_SHOW_PAYMENTTERMMODE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_SAPHIR_MASK', 'string', NULL, 'core', 'Defines the numbering mask pattern used by the ''saphir'' module for generating supplier proposal reference numbers.', 'Read at core/modules/supplier_proposal/mod_supplier_proposal_saphir.php:95 and :145 to obtain the mask for reference generation. No admin UI; hidden setting.', 'Changing the mask alters how supplier proposal reference numbers are generated. An empty mask results in an empty reference number from this module.', 'String mask pattern following Dolibarr mask syntax; empty = no mask configured (reference generation returns empty string)', 1, 0, NULL, 1, '74ea647d30f9e2d7eb4e441c990101b11e03cebb72fcb420e8b1e361cd65c90e', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/supplier_proposal/mod_supplier_proposal_saphir.php:95|read|$mask = getDolGlobalString(''SUPPLIER_PROPOSAL_SAPHIR_MASK'');", "core/modules/supplier_proposal/mod_supplier_proposal_saphir.php:145|read|$mask = !getDolGlobalString(''SUPPLIER_PROPOSAL_SAPHIR_MASK'') ? '''' : $conf->global->SUPPLIER_PROPOSAL_SAPHIR_MASK;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_USE_HOUR_FOR_DELIVERY_DATE', 'bool', NULL, 'core', 'Includes the time-of-day (not just the date) when printing the planned delivery date on a supplier proposal PDF.', 'Checked in core/modules/supplier_proposal/doc/pdf_zenith.modules.php:1338: `$usehourmin = ''day''; if (getDolGlobalString(''SUPPLIER_PROPOSAL_USE_HOUR_FOR_DELIVERY_DATE'')) { $usehourmin = ''dayhour''; }`, then passed to dol_print_date() for the delivery_date field.', 'When set, the supplier proposal PDF prints the delivery date with hour/minute included (''dayhour'' format) instead of date-only (''day'' format).', 'Truthy/falsy flag; controls dol_print_date() format argument: ''day'' (default) vs ''dayhour'' (when set).', 0, 0, NULL, 1, '036ac4c3feff763a3fea0cee9cb26f1f02128f39ce7cdcfdcecfd948bcf5205d', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_proposal/doc/pdf_zenith.modules.php:1338|check|if (getDolGlobalString(''SUPPLIER_PROPOSAL_USE_HOUR_FOR_DELIVERY_DATE'')) {", "core/modules/supplier_proposal/doc/pdf_zenith.modules.php|$usehourmin = ''day''; ... $usehourmin = ''dayhour'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_PROPOSAL_WITH_PREDEFINED_PRICES_ONLY', 'string', NULL, 'supplier_proposal', 'When set to 1, restricts supplier proposal lines to products with predefined purchase prices only.', 'Checked in supplier_proposal/class/supplier_proposal.class.php:511 and supplier_proposal/card.php:1272 with the comment ''Not the common case''. Also checked at card.php:2244 and its value read at card.php:2245 into $senderissupplier.', 'Setting this to 1 limits supplier proposal line additions to products that have predefined purchase prices; the code notes this is not the common use case.', '1 = only predefined-price products allowed on supplier proposals; 0 or unset = no restriction (default)', 1, 0, NULL, 1, '9ef9582d0a344e43e795d3893fbae8bd674ae2f75f56cd9b880c57950777610b', 'v2', '2026-04-21T11:16:15+00:00', '["supplier_proposal/class/supplier_proposal.class.php:511|check|if (getDolGlobalInt(''SUPPLIER_PROPOSAL_WITH_PREDEFINED_PRICES_ONLY'') == 1) {\t// Not the common case", "supplier_proposal/card.php:1272|check|if (getDolGlobalInt(''SUPPLIER_PROPOSAL_WITH_PREDEFINED_PRICES_ONLY'') == 1) {\t// Not the common case", "supplier_proposal/card.php:2244|check|if (getDolGlobalInt(''SUPPLIER_PROPOSAL_WITH_PREDEFINED_PRICES_ONLY'')) {", "supplier_proposal/card.php:2245|read|$senderissupplier = getDolGlobalInt(''SUPPLIER_PROPOSAL_WITH_PREDEFINED_PRICES_ONLY'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_REF_IN_NAME', 'string', NULL, 'core', 'Controls whether the supplier reference is included in the name field on supplier PDF documents.', 'Checked across multiple supplier document generators (orders, proposals, invoices, ODT) in core/modules/supplier_order, supplier_proposal, and supplier_invoice; one occurrence in supplier_payment is commented out. When truthy, document templates include the supplier reference in the name. The COMMENTS entry shows: //if (getDolGlobalString(''SUPPLIER_REF_IN_NAME'')) {', 'Enabling this constant causes supplier reference to appear in the name field of generated supplier PDFs; disabling it omits it.', 'Truthy string to include supplier reference in name; empty/unset to omit.', 1, 0, NULL, 1, '5140ef44e6727d9ce3d7f057947ea948c45872bb8ca63d71145ead08d533cc53', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/supplier_payment/doc/pdf_standard_supplierpayment.modules.php:284  //if (getDolGlobalString(''SUPPLIER_REF_IN_NAME'')) {", "core/modules/supplier_order/doc/pdf_cornas.modules.php:251|check|if (getDolGlobalString(''SUPPLIER_REF_IN_NAME'')) {", "core/modules/supplier_invoice/doc/pdf_canelle.modules.php:208|check|if (getDolGlobalString(''SUPPLIER_REF_IN_NAME'')) {", "core/modules/supplier_proposal/doc/pdf_zenith.modules.php:245|check|if (getDolGlobalString(''SUPPLIER_REF_IN_NAME'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_REPLACEMENT_TULIP_MASK', 'string', NULL, 'core', 'Numbering mask used for supplier ''replacement'' invoice references generated by the ''Tulip'' supplier invoice numbering model.', 'In core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php, shown/edited in the admin form as input ''maskreplacement'' (only when INVOICE_DISABLE_REPLACEMENT is off and MAIN_FEATURES_LEVEL>=2, per line 116-119), and read by getNextValue() (line 171) for replacement-type invoices (object->type == 1), with fallback to SUPPLIER_INVOICE_TULIP_MASK if empty.', 'Changing this mask changes the numbering format for supplier replacement invoices; if left empty, the model falls back to the standard SUPPLIER_INVOICE_TULIP_MASK.', 'String: a Dolibarr numbering mask, editable via admin form field ''maskreplacement''; empty falls back to SUPPLIER_INVOICE_TULIP_MASK.', 0, 0, NULL, 1, 'c53d6dc0fa38dda5ad10dbf339f69694b8aaeda159e61185dd4098ae86d463ac', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:171|read|$mask = getDolGlobalString(\"SUPPLIER_REPLACEMENT_TULIP_MASK\");", "core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:172| if (!$mask) { $mask = getDolGlobalString(\"SUPPLIER_INVOICE_TULIP_MASK\"); }", "core/modules/supplier_invoice/mod_facture_fournisseur_tulip.php:119|read|name=\"maskreplacement\" value=''.getDolGlobalString(\"SUPPLIER_REPLACEMENT_TULIP_MASK\").''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_SHOW_STOCK_IN_PRODUCTS_COMBO', 'bool', NULL, 'product', 'Controls whether stock levels are shown in the supplier-product selection combo/autocomplete list.', 'Read via getDolGlobalInt() and passed as a parameter into select_produits_fournisseurs_list() in core/class/html.form.class.php:4437, which builds the supplier product combo used by product/ajax/products.php:342.', 'Changing the value alters what is passed as the stock-display flag to select_produits_fournisseurs_list(), affecting whether stock info is rendered in the supplier product picker.', 'Not documented in code comments; used as a boolean/flag argument to select_produits_fournisseurs_list().', 1, 0, NULL, 1, '76ae6e94023a76ac4914993832653b0e1911212566fe45fd3ceb4b6099c4eba6', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:4437: getDolGlobalInt(''SUPPLIER_SHOW_STOCK_IN_PRODUCTS_COMBO'')", "product/ajax/products.php:342: select_produits_fournisseurs_list(...)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SUPPLIER_TAKE_FIRST_PRICE_IF_NO_PRICE_FOR_CURRENT_SUPPLIER', 'string', NULL, 'fourn', 'When no supplier-specific price exists for the selected supplier, uses the first available supplier price instead.', 'Checked across 4 files: supplier_proposal/card.php:843, fourn/commande/card.php:667, fourn/facture/card.php:1737, and fourn/facture/card-rec.php:523.', 'Enabling this setting ensures a price is always pre-filled on supplier documents even when the current supplier has no specific price defined.', 'Truthy string (non-empty) = use first available price as fallback; empty/not set = no fallback price applied.', 1, 0, NULL, 1, '4c1773ca43d0e64130ab18ff10b0e81a6fceffcd4a1321d81c6e67943a940c78', 'v2', '2026-04-21T11:16:15+00:00', '["supplier_proposal/card.php:843|check|if (getDolGlobalString(''SUPPLIER_TAKE_FIRST_PRICE_IF_NO_PRICE_FOR_CURRENT_SUPPLIER'')) {", "fourn/commande/card.php:667|check|if (getDolGlobalString(''SUPPLIER_TAKE_FIRST_PRICE_IF_NO_PRICE_FOR_CURRENT_SUPPLIER'')) {", "fourn/facture/card.php:1737|check|if (getDolGlobalString(''SUPPLIER_TAKE_FIRST_PRICE_IF_NO_PRICE_FOR_CURRENT_SUPPLIER'')) {", "fourn/facture/card-rec.php:523|check|if (getDolGlobalString(''SUPPLIER_TAKE_FIRST_PRICE_IF_NO_PRICE_FOR_CURRENT_SUPPLIER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSLOG_DISABLE_LOGHANDLER_FILE', 'bool', NULL, 'core', 'Disables the ''file'' syslog log handler (writing to a local log file) entirely.', 'core/modules/syslog/mod_syslog_file.php:75, in the isActive() method of the file log handler class: `return !getDolGlobalString(''SYSLOG_DISABLE_LOGHANDLER_FILE'') ? 1 : 0; // Set SYSLOG_DISABLE_LOGHANDLER_FILE to 1 to disable this loghandler`.', 'Setting it to 1 makes the file log handler report itself inactive, so Dolibarr no longer writes log entries to the local file handler (e.g. dolibarr.log), even if configured as an active handler.', '1 = disable this loghandler; 0/unset = handler active (default), per inline comment.', 0, 0, NULL, 1, '68669c852c5b77896781703ab01cd8341da84269c941e592fd3645e4127744c0', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/syslog/mod_syslog_file.php:75: return !getDolGlobalString(''SYSLOG_DISABLE_LOGHANDLER_FILE'') ? 1 : 0; // Set SYSLOG_DISABLE_LOGHANDLER_FILE to 1 to disable this loghandler"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSLOG_DISABLE_LOGHANDLER_SYSLOG', 'bool', NULL, 'core', 'Disables the syslog log handler module in Dolibarr''s logging system.', 'Read in core/modules/syslog/mod_syslog_syslog.php:59; the handler''s isActive() method returns 0 (inactive) when this constant is set, as noted by the inline comment ''Set SYSLOG_DISABLE_LOGHANDLER_SYSLOG to 1 to disable this loghandler''.', 'Setting this constant to 1 disables syslog-based logging; leaving it unset keeps the syslog handler active.', 'Bool-like: unset/0 = handler active; 1 = handler disabled.', 1, 0, NULL, 1, '8e322eb78fad1e40582f79e7f4222a83354693859b4b6bd9ab083d33c5010775', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/syslog/mod_syslog_syslog.php:59|read|return !getDolGlobalString(''SYSLOG_DISABLE_LOGHANDLER_SYSLOG'') ? 1 : 0; // Set SYSLOG_DISABLE_LOGHANDLER_SYSLOG to 1 to disable this loghandler"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSLOG_FACILITY', 'string', NULL, 'core', 'Sets the syslog facility constant name used when writing log entries to the system syslog.', 'Used in core/modules/syslog/mod_syslog_syslog.php to resolve the PHP syslog facility via defined()/constant(). The COMMENTS note: ''SYSLOG_HANDLERS = ["mod_syslog_syslog"]  facility is then defined by SYSLOG_FACILITY''. An inline comment gives ''Example LOG_USER''.', 'If set to an unknown constant name, an error is recorded; if unset the facility defaults to null.', 'String: a valid PHP syslog facility constant name, e.g. ''LOG_USER''.', 1, 0, NULL, 1, '092565f26c865744be701806aadb73b565e44b360c25926845d1d442efc0f8f1', 'v2', '2026-04-21T13:50:40+00:00', '["core/lib/functions.lib.php:2767  *\tSYSLOG_HANDLERS = [\"mod_syslog_syslog\"]  \tfacility is then defined by SYSLOG_FACILITY", "core/modules/syslog/mod_syslog_syslog.php:120|check|if (getDolGlobalString(''SYSLOG_FACILITY'') && defined(getDolGlobalString(''SYSLOG_FACILITY''))) {  // Example LOG_USER", "core/modules/syslog/mod_syslog_syslog.php:100|read|$this->errors[] = $langs->trans(\"ErrorUnknownSyslogConstant\", getDolGlobalString(''SYSLOG_FACILITY''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSLOG_FILE', 'string', 'DOL_DATA_ROOT/dolibarr.log', 'core', 'Specifies the file path for the Dolibarr system log file.', 'Default value is ''DOL_DATA_ROOT/dolibarr.log''. Set during installation and upgrade in install/step5.php:261, install/upgrade2.php:314, and install/repair.php:326 from the SYSLOG_FILE constant. Read in admin/tools/purge.php:53 for log file management. Commented examples in modulebuilder templates show usage like ''DOL_DATA_ROOT/dolibarr_mydedicatedlogfile.log''.', 'Changing this redirects all system log output to the specified file path; the path must be writable by the web server.', 'File path string; default ''DOL_DATA_ROOT/dolibarr.log''.', 0, 0, 'admin/tools/purge.php', 1, 'ad5343bfbd1aa588d55fdcd3cef32fed7062c5eb6b6263b011b1aef22390a812', 'v2', '2026-04-21T13:50:40+00:00', '["install/repair.php:326|write|$conf->global->SYSLOG_FILE = constant(''SYSLOG_FILE'');", "admin/tools/purge.php:53|read|$filelog = getDolGlobalString(''SYSLOG_FILE'');", "modulebuilder/template/class/myobject.class.php:1251|write|//$conf->global->SYSLOG_FILE = ''DOL_DATA_ROOT/dolibarr_mydedicatedlogfile.log'';", "install/step5.php:261|write|$conf->global->SYSLOG_FILE = constant(''SYSLOG_FILE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSLOG_FILE_ONEPERSESSION', 'string', NULL, 'core', 'Controls whether syslog output is split into per-session or per-user log files instead of a single shared log file.', 'Checked at core/modules/syslog/mod_syslog_file.php:134-143; value 1 creates a file per instance session key, value 2 creates a file per session key plus IP (near per-user). No admin UI; hidden setting.', 'Setting to 1 separates logs by session, to 2 separates by session and IP. Leaving unset writes all logs to the shared log file.', '0 or empty = single shared log file; 1 = file per instance session key name; 2 = file per instance session key name + IP (near per-user); other string = appended as suffix to log filename', 1, 0, NULL, 1, '7d81d88dc093a625809f006b09b69e1039aef9992b308f9607d60f16c76eba92', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/syslog/mod_syslog_file.php:136|check|if (getDolGlobalInt(''SYSLOG_FILE_ONEPERSESSION'') == 1) {\t// file depend on instance session key name", "core/modules/syslog/mod_syslog_file.php:139|check|if (getDolGlobalInt(''SYSLOG_FILE_ONEPERSESSION'') == 2) {\t// file depend on instance session key name + ip so nearly per user", "core/modules/syslog/mod_syslog_file.php:134|check|if (getDolGlobalString(''SYSLOG_FILE_ONEPERSESSION'')) {", "core/modules/syslog/mod_syslog_file.php:143|read|$suffixinfilename .= ''_'' . getDolGlobalString(''SYSLOG_FILE_ONEPERSESSION'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSLOG_FILE_SAVES', 'string', NULL, 'admin', 'Sets the number of rotated log file archives to retain.', 'Comment in core/class/utils.class.php:998: ''Nb of archive to keep is defined into $conf->global->SYSLOG_FILE_SAVES''. Read at line 1018 via getDolGlobalString(''SYSLOG_FILE_SAVES'', 10) as $nbSaves. Written via admin/syslog.php:162.', 'Increasing this value retains more archived log files, consuming more disk space. Decreasing it causes older archives to be deleted sooner during rotation.', 'Integer number of archives to keep. Default: 10 when unset.', 0, 0, 'admin/syslog.php|admin/syslog.php', 1, '7ebfd87df1fc44b6df30a570e29522a11a8d989e3be6dd875aad762370282f48', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/utils.class.php:998  * Nb of archive to keep is defined into $conf->global->SYSLOG_FILE_SAVES", "core/class/utils.class.php:1018|read|$nbSaves = intval(getDolGlobalString(''SYSLOG_FILE_SAVES'', 10));", "admin/syslog.php:162|write|$res = dolibarr_set_const($db, \"SYSLOG_FILE_SAVES\", $file_saves, ''chaine'', 0, '''', 0);", "admin/syslog.php:333|read|print ''<td colspan=\"2\"><input class=\"width50\" type=\"number\" name=\"file_saves\" placeholder=\"14\" min=\"0\" step=\"1\" value=\"''.getDolGlobalString(''SYSLOG_FILE_SAVES'').''\" />'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSLOG_HANDLERS', 'string', '["mod_syslog_file"]', 'admin', 'JSON-encoded array of active syslog handler module names that determine where Dolibarr writes log output.', 'Comment in core/lib/functions.lib.php:2766-2767: ''SYSLOG_HANDLERS = ["mod_syslog_file"] file name is then defined by SYSLOG_FILE'' and ''SYSLOG_HANDLERS = ["mod_syslog_syslog"] facility is then defined by SYSLOG_FACILITY''. Written via admin/syslog.php:126 as json_encode($activeModules). Read at line 54 via json_decode.', 'Changing this constant switches or combines the logging destinations. Selecting mod_syslog_file routes logs to a file; mod_syslog_syslog routes to the system syslog facility.', 'JSON array string. Examples: ["mod_syslog_file"] (file, path set by SYSLOG_FILE); ["mod_syslog_syslog"] (system syslog, facility set by SYSLOG_FACILITY).', 0, 0, 'admin/syslog.php|admin/syslog.php|admin/syslog.php|admin/syslog.php', 1, '4b8340a4ce28786c8b43841c87399cc07d67c5e26e9c32c64a5e76fb27030279', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions.lib.php:2766  *\tSYSLOG_HANDLERS = [\"mod_syslog_file\"]  \t\tfile name is then defined by SYSLOG_FILE", "core/lib/functions.lib.php:2767  *\tSYSLOG_HANDLERS = [\"mod_syslog_syslog\"]  \tfacility is then defined by SYSLOG_FACILITY", "admin/syslog.php:126|write|dolibarr_set_const($db, ''SYSLOG_HANDLERS'', json_encode($activeModules), ''chaine'', 0, '''', 0);", "admin/syslog.php:54|read|$activeModules = json_decode($conf->global->SYSLOG_HANDLERS);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSLOG_LEVEL', 'string', '7', 'admin', 'Sets the verbosity level of the Dolibarr syslog, using standard PHP LOG_* constants.', 'Read and written at admin/syslog.php (e.g., lines 153, 318-320) with options for LOG_EMERG through LOG_DEBUG. Checked at admin/system/perf.php:112 and admin/system/security.php:721 to warn when the level exceeds LOG_NOTICE. Default value is ''7''. Configurable via admin/syslog.php.', 'Increasing the log level above LOG_NOTICE causes verbose debug output and triggers a performance/security warning; decreasing it reduces log volume.', 'Standard PHP log level integers: LOG_EMERG=0, LOG_ALERT=1, LOG_CRIT=2, LOG_ERR=3, LOG_WARNING=4, LOG_NOTICE=5, LOG_INFO=6, LOG_DEBUG=7; default is 7.', 0, 0, 'admin/syslog.php|admin/syslog.php|admin/syslog.php|admin/syslog.php|admin/syslog.php|admin/syslog.php|admin/syslog.php|admin/syslog.php|admin/system/perf.php|admin/system/perf.php|admin/system/security.php|admin/system/security.php|admin/syslog.php', 1, '228a182d6036622838461de1c2d1ca3343354d3994b14ab2d4589204e6f8ac50', 'v2', '2026-04-21T11:16:15+00:00', '["admin/syslog.php:318|read|print ''<option value=\"''.LOG_EMERG.''\" ''.(getDolGlobalString(''SYSLOG_LEVEL'') == LOG_EMERG ? ''selected'' : '''').''>LOG_EMERG (''.LOG_EMERG.'')</option>'';", "admin/syslog.php:319|read|print ''<option value=\"''.LOG_ALERT.''\" ''.(getDolGlobalString(''SYSLOG_LEVEL'') == LOG_ALERT ? ''selected'' : '''').''>LOG_ALERT (''.LOG_ALERT.'')</option>'';", "admin/system/perf.php:112|check|if (getDolGlobalInt(''SYSLOG_LEVEL'') > LOG_NOTICE) {", "admin/syslog.php:153|write|$res = dolibarr_set_const($db, \"SYSLOG_LEVEL\", $level, ''chaine'', 0, '''', 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSTEMTOOLS_MYSQLDUMP', 'string', NULL, 'admin', 'Stores the full filesystem path to the mysqldump executable used for database backups.', 'Written via admin/tools/export.php:155; read in admin/tools/dolibarr_export.php:253 and core/class/utils.class.php:301 to execute database dumps. If unset, the export pages apply fallback logic at lines 250 and 298.', 'Setting this to the correct mysqldump binary path enables database export; removing it forces the code to attempt auto-detection or fail.', 'Absolute filesystem path to the mysqldump binary.', 0, 0, 'admin/tools/dolibarr_export.php|admin/tools/dolibarr_export.php|admin/tools/export.php', 1, 'b07ab919f44cdd9ade468827d938f74b5c2ea42e1fb384b795d77afb45f0ff72', 'v2', '2026-04-21T13:50:40+00:00', '["admin/tools/export.php:155|write|dolibarr_set_const($db, ''SYSTEMTOOLS_MYSQLDUMP'', $cmddump, ''chaine'', 0, '''', 0);", "admin/tools/dolibarr_export.php:253|read|$fullpathofmysqldump = getDolGlobalString(''SYSTEMTOOLS_MYSQLDUMP'');", "core/class/utils.class.php:301|read|$cmddump = getDolGlobalString(''SYSTEMTOOLS_MYSQLDUMP'');", "admin/tools/dolibarr_export.php:250|check|if (!getDolGlobalString(''SYSTEMTOOLS_MYSQLDUMP'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('SYSTEMTOOLS_POSTGRESQLDUMP', 'string', NULL, 'admin', 'Stores the full filesystem path to the pg_dump executable used for PostgreSQL database backups.', 'Written via admin/tools/export.php:195; read in admin/tools/dolibarr_export.php:430 and core/class/utils.class.php:620 to execute PostgreSQL dumps. If unset, fallback logic applies at line 427.', 'Setting this to the correct pg_dump binary path enables PostgreSQL export; removing it forces the code to attempt auto-detection or fail.', 'Absolute filesystem path to the pg_dump binary.', 0, 0, 'admin/tools/dolibarr_export.php|admin/tools/dolibarr_export.php|admin/tools/export.php', 1, '92f8a8655f93a865023a19cb7cbe483bd2ae6081a29abebfbe4f738a954afa95', 'v2', '2026-04-21T13:50:40+00:00', '["admin/tools/export.php:195|write|dolibarr_set_const($db, ''SYSTEMTOOLS_POSTGRESQLDUMP'', $cmddump, ''chaine'', 0, '''', 0);", "admin/tools/dolibarr_export.php:430|read|$fullpathofpgdump = getDolGlobalString(''SYSTEMTOOLS_POSTGRESQLDUMP'');", "core/class/utils.class.php:620|read|$cmddump = getDolGlobalString(''SYSTEMTOOLS_POSTGRESQLDUMP'');", "admin/tools/dolibarr_export.php:427|check|if (!getDolGlobalString(''SYSTEMTOOLS_POSTGRESQLDUMP'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ADDON', 'string', NULL, 'takepos', 'Selects the numbering add-on module used to generate TakePOS invoice/ticket reference numbers.', 'Written via takepos/admin/setup.php:91 (global) and takepos/admin/terminal.php:147 (per-terminal). Checked at takepos/admin/terminal.php:384 for value ''terminal''. A commented-out line at setup.php:487 shows a formerly rendered select array for this constant.', 'Changing this value switches the numbering scheme for POS tickets; selecting ''terminal'' applies per-terminal numbering.', 'String: add-on identifier (e.g. ''0'' for default, ''terminal'' for per-terminal numbering)', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/setup.php|takepos/admin/setup.php|takepos/admin/terminal.php', 1, '5931f13d2804f988a74d857b4420c5eb995885838b474b14f937066fefd5e315', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalString(''TAKEPOS_ADDON'') == \"terminal\") {", "//print $form->selectarray(''TAKEPOS_ADDON'', $array, (empty($conf->global->TAKEPOS_ADDON) ? ''0'' : $conf->global->TAKEPOS_ADDON), 0);", "$res = dolibarr_set_const($db, \"TAKEPOS_ADDON\", GETPOST(''TAKEPOS_ADDON'', ''alpha''), ''int'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ADD_BUTTON_OPEN_DRAWER', 'string', NULL, 'takepos', 'Adds a per-terminal ''Open Drawer'' menu button in TakePOS to manually trigger the cash drawer via DolibarrOpenDrawer(), independent of the takeposconnector print method.', 'Checked at takepos/index.php:1571 as getDolGlobalInt(''TAKEPOS_ADD_BUTTON_OPEN_DRAWER''.$term) > 0, where $term is the current terminal number, so the setting is per-terminal (e.g. TAKEPOS_ADD_BUTTON_OPEN_DRAWER1, ...2, etc.).', 'Setting the per-terminal variant to a positive integer adds an ''Open Drawer'' button calling DolibarrOpenDrawer() to that terminal''s menu, in addition to (or instead of) the takeposconnector-based drawer button.', 'Integer, per-terminal suffix (TAKEPOS_ADD_BUTTON_OPEN_DRAWER<term>): value > 0 shows the button for that terminal, 0/unset hides it.', 1, 0, NULL, 1, '621cb1b88e8f87f25d47348206021bcaac1ba91e45208cc67168cd482f5cbce6', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1571|check|if (getDolGlobalInt(''TAKEPOS_ADD_BUTTON_OPEN_DRAWER''.$term) > 0) { $menus[$r++] = array(''title'' => ...''DOL_OPEN_DRAWER''... ''action'' => ''DolibarrOpenDrawer();''); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ADD_BUTTON_TO_ENTER_DISCOUNT_WITH_KEYBOARD', 'string', NULL, 'takepos', 'Adds explicit ''Amount TTC'' and ''Percentage'' buttons to the TakePOS discount/reduction entry screen, as an alternative to typing directly into the reduction field.', 'Checked at takepos/reduction.php:242: when true, two extra <input type="button"> elements are printed calling formvalid(''amount'') and formvalid(''percent'') respectively, next to the reduction_total text field.', 'Enabling it gives cashiers two dedicated buttons to submit the discount as either a TTC amount or a percentage, useful on touchscreen/keyboard-limited terminals where typing directly is inconvenient.', 'Boolean: true/1 shows the two discount-mode buttons, false/unset (default) hides them (only the text field is shown).', 1, 0, NULL, 1, 'ccbdd1802e65e04c86dc7c84093d7ef9aea811912ab4dea825897f68ecdad64f', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/reduction.php:242|check|if (getDolGlobalString(''TAKEPOS_ADD_BUTTON_TO_ENTER_DISCOUNT_WITH_KEYBOARD'')) { print ''<input type=\"button\" ... value=\\''AmountTTC\\'' onclick=\"return formvalid(\\''amount\\'');\">''; ... }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ALTERNATIVE_PAYMENT_SCREEN', 'string', NULL, 'takepos', 'Overrides the default TakePOS payment page (pay.php) with a custom relative path, for a customized/alternative payment screen.', 'Read at takepos/index.php:680: if empty, $payurl defaults to ''pay.php''; otherwise $payurl = dol_buildpath($alternative_payurl, 1), used as the colorbox iframe URL when opening the payment popup.', 'Setting it replaces the payment popup''s target page from the built-in pay.php with a custom path built via dol_buildpath, letting third-party modules provide a custom payment screen.', 'Free-form relative path to a PHP page (passed to dol_buildpath); empty/unset uses the built-in ''pay.php''.', 1, 0, NULL, 1, '9178a179ee0dd1bfd0e984c3dcce7d94f70754a836e711e1a72e1de5829c3286', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:680|read|$alternative_payurl = getDolGlobalString(''TAKEPOS_ALTERNATIVE_PAYMENT_SCREEN''); if (empty($alternative_payurl)) { $payurl = \"pay.php\"; } else { $payurl = dol_buildpath($alternative_payurl, 1); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_AUTO_ORDER', 'string', NULL, 'takepos', 'When enabled, activates the TakePos automatic order feature, allowing products and categories to trigger auto-orders and enabling the public auto-order endpoint.', 'Checked in takepos/admin/bar.php:236 (admin UI present), viewimage.php:305 for product/category image serving with auto-order context, and takepos/public/auto_order.php:37 which blocks access when not set.', 'Enabling this constant activates the auto-order workflow in TakePos, including product image display in auto-order mode and the public auto-order page.', '0 or unset = auto-order feature disabled; truthy = auto-order feature enabled.', 0, 0, 'takepos/admin/bar.php', 1, '9d511716824060deb640fb38abc7bb2a18341882994cd420af5a32c5d3d68191', 'v2', '2026-04-21T11:16:15+00:00', '["takepos/public/auto_order.php:37|check|if (!getDolGlobalString(''TAKEPOS_AUTO_ORDER'')) {", "viewimage.php:305|check|if (getDolGlobalString(''TAKEPOS_AUTO_ORDER'') && in_array($modulepart, array(''product'', ''category''))) {", "takepos/admin/bar.php:236|check|if (getDolGlobalInt(''TAKEPOS_AUTO_ORDER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_AUTO_PRINT_TICKETS', 'string', NULL, 'takepos', 'Automatically triggers ticket printing once a TakePOS sale is fully paid.', 'Checked in takepos/invoice.php:1504: `if ($remaintopay <= 0 && getDolGlobalString(''TAKEPOS_AUTO_PRINT_TICKETS'') && $action != "history")`; toggled via ajax_constantonoff in takepos/admin/receipt.php:262, exposing it in the TakePOS admin UI.', 'Enabling it makes the POS automatically print the receipt/ticket as soon as the remaining amount to pay reaches zero, without a manual print action.', 'Boolean: 1/true auto-prints tickets when fully paid; 0/false (default) requires manual printing.', 0, 0, NULL, 1, 'd766e0e50dfa6b0bdd7ad17545ef3bf3ef9665b2b8b90155668b36818890e4e3', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:1504|check|if ($remaintopay <= 0 && getDolGlobalString(''TAKEPOS_AUTO_PRINT_TICKETS'') && $action != \"history\") {", "takepos/admin/receipt.php:262|print ajax_constantonoff(\"TAKEPOS_AUTO_PRINT_TICKETS\", array(), $conf->entity, 0, 0, 1, 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_BARCODE_RULE_TO_INSERT_PRODUCT', 'string', NULL, 'takepos', 'Barcode parsing rule string used by TakePOS to extract product information from scanned barcodes.', 'Written via takepos/admin/setup.php:98 and displayed as a text input at setup.php:429. Read in takepos/ajax/ajax.php:183 as `$barcode_rules` for barcode processing logic.', 'Changing this value alters how scanned barcodes are interpreted when adding products to a POS sale; an incorrect rule prevents barcode-based product lookup.', 'Rule string (format determined by barcode processing logic in takepos/ajax/ajax.php)', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php', 1, 'a0f0078271631301f59b1c2bcaa219ba6bfa7cb7d5a32e7298b6f1e672cacd8a', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, ''TAKEPOS_BARCODE_RULE_TO_INSERT_PRODUCT'', GETPOST(''TAKEPOS_BARCODE_RULE_TO_INSERT_PRODUCT'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$barcode_rules = getDolGlobalString(''TAKEPOS_BARCODE_RULE_TO_INSERT_PRODUCT'');", "print ''<input type=\"text\" name=\"TAKEPOS_BARCODE_RULE_TO_INSERT_PRODUCT\" value=\"'' . (getDolGlobalString(''TAKEPOS_BARCODE_RULE_TO_INSERT_PRODUCT'')) . ''\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_BAR_RESTAURANT', 'string', NULL, 'takepos', 'Enables bar and restaurant mode in TakePOS, activating table management, order printing, and related features.', 'Checked 11 times across takepos/admin/bar.php, takepos/admin/terminal.php, takepos/index.php, and takepos/invoice.php. A code comment at takepos/index.php:719 states: ''If we go here, it means $conf->global->TAKEPOS_BAR_RESTAURANT is not defined''. Configurable via takepos/admin/bar.php.', 'Without this constant set, bar/restaurant features (table ordering, order printers, supplements) are unavailable; enabling it activates the full hospitality workflow.', 'Truthy / non-empty string = bar/restaurant mode enabled; absent or empty = standard retail mode', 0, 0, 'takepos/admin/bar.php|takepos/admin/bar.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'ebe6c4e05d724fee736dc90b5a57e2e97ead5987b3d02d5716d3808a5049ac23', 'v2', '2026-04-21T13:50:40+00:00', '["// If we go here,it means $conf->global->TAKEPOS_BAR_RESTAURANT is not defined", "if (getDolGlobalInt(''TAKEPOS_BAR_RESTAURANT'')) {", "if (getDolGlobalString(''TAKEPOS_BAR_RESTAURANT'') && getDolGlobalInt(''TAKEPOS_ORDER_PRINTERS'') && $orderprinterallowed) {", "if (!getDolGlobalString(''TAKEPOS_BAR_RESTAURANT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CAN_EDIT_IF_ALREADY_VALIDATED', 'string', NULL, 'takepos', 'Allows editing of already-validated TakePOS invoices, including draft invoices that already have a reference.', 'Checked at takepos/invoice.php:1704; the comment at line 1708 states: ''If TAKEPOS_CAN_EDIT_IF_ALREADY_VALIDATED set, we show also draft invoice that already has a reference defined''. No admin UI write is present.', 'Enabling this constant unlocks editing of validated invoices in TakePOS; leaving it unset restricts editing to unvalidated records only.', 'Non-empty string/truthy = allow editing validated invoices; unset/empty = editing restricted.', 1, 0, NULL, 1, 'fe707f7a840854f8bf86406577a75ec9069dc354fa2642102f01f4cedb585472', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/invoice.php:1708  // If TAKEPOS_CAN_EDIT_IF_ALREADY_VALIDATED set, we show also draft invoice that already has a reference defined", "takepos/invoice.php:1704|check|if (!getDolGlobalString(''TAKEPOS_CAN_EDIT_IF_ALREADY_VALIDATED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CAN_FORCE_BANK_ACCOUNT_DURING_PAYMENT', 'string', NULL, 'takepos', 'Lets the TakePOS cashier manually pick the bank/cash account used for a payment, instead of relying on the automatic CASHDESK_ID_BANKACCOUNT_* mapping.', 'Read in takepos/invoice.php:314 (payment validation logic) and takepos/pay.php:608 (payment screen UI), both in the terminal''s payment flow.', 'When set, the payment page renders a bank-account selector (Form::select_comptes) and the chosen accountid (GETPOSTINT) is used directly as the bank account for the recorded payment; when unset, the account is derived from CASHDESK_ID_BANKACCOUNT_CASH/CHEQUE/<paytype><terminal> globals for backward compatibility.', 'Truthy string enables the manual bank-account selector during payment; empty/unset keeps the automatic CASHDESK_ID_BANKACCOUNT_* mapping.', 0, 0, NULL, 1, 'e9090f1406756cec168120daa2d15167d9c35d3acc5361b2cf142a097bdf8c7a', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:314: if (getDolGlobalString(''TAKEPOS_CAN_FORCE_BANK_ACCOUNT_DURING_PAYMENT'')) { $bankaccount = GETPOSTINT(''accountid'');", "takepos/pay.php:608: if (getDolGlobalString(''TAKEPOS_CAN_FORCE_BANK_ACCOUNT_DURING_PAYMENT'')) { ... $form->select_comptes(0, ''accountid'', 0, $filter, 1, '''');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CASHCONTROL_REPORT_SHOW_TOTAL_INCLUDING_TAXES_COLUMN', 'bool', NULL, 'compta', 'Adds a ''Total including taxes'' (TTC) column to the per-VAT-rate breakdown table of the TakePOS cash control report.', 'Checked twice in compta/cashcontrol/report.php (lines 461 and 466), each time printing an extra TotalTTC column/value (sum of HT + VAT amount per rate) only when the constant is non-zero.', 'Enabling it adds a tax-inclusive total column to the cash control report''s per-rate VAT breakdown; disabled (default) shows only the HT and VAT columns.', 'Boolean-like (getDolGlobalInt, explicit default 0): non-zero shows the TotalTTC column; 0/unset (default) hides it.', 1, 0, NULL, 1, 'f5e76708792b2501a78037537ffbf02326c8ac3512142c1b6f62f8fdb96cadf4', 'v2', '2026-07-24T07:05:23+00:00', '["compta/cashcontrol/report.php:461: if (getDolGlobalInt(''TAKEPOS_CASHCONTROL_REPORT_SHOW_TOTAL_INCLUDING_TAXES_COLUMN'', 0) != 0) {", "compta/cashcontrol/report.php:466: if (getDolGlobalInt(''TAKEPOS_CASHCONTROL_REPORT_SHOW_TOTAL_INCLUDING_TAXES_COLUMN'', 0) != 0) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CHANGE_PRICE_HT', 'string', NULL, 'takepos', 'Controls whether manual price entry in TakePOS uses the pre-tax (HT) amount instead of the tax-inclusive (TTC) amount.', 'Checked in takepos/index.php (multiple lines) and takepos/invoice.php:1147 to switch price-entry mode. Also drives the placeholder text in takepos/freezone.php:140, showing ''AmountHT'' when enabled.', 'When set to 1, cashiers enter pre-tax prices; when absent or 0, prices are entered tax-inclusive, affecting how line amounts are calculated and stored.', '1 = enter prices HT (pre-tax); 0 or absent = enter prices TTC (tax-inclusive)', 1, 0, NULL, 1, '25b6e5d4f837b42bbd1300057d30d83b1c265d3aa367a11a4b3373e227682cc6', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalInt(''TAKEPOS_CHANGE_PRICE_HT'')) {", "echo ''<input type=\"text\" id=\"number\" name=\"number\" class=\"takepospay\" style=\"width:15%;\" placeholder=\"''.$langs->trans(getDolGlobalString(\"TAKEPOS_CHANGE_PRICE_HT\") ? ''AmountHT'' : ''", "} elseif (getDolGlobalInt(''TAKEPOS_CHANGE_PRICE_HT'')  == 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CHOOSE_CONTACT', 'string', NULL, 'takepos', 'Enables a contact selection step within the TakePOS customer selection workflow.', 'Checked at takepos/index.php lines 669 and 1465, and at takepos/invoice.php lines 1678 and 1695. When set, a contact chooser UI element is rendered and contact-related logic is activated. No admin UI write is present.', 'Enabling this constant adds a contact picker after customer selection; leaving it unset or 0 skips the contact selection step.', 'Non-empty string/truthy = show contact chooser; 0 or unset = no contact selection.', 1, 0, NULL, 1, '4714d179cf3e598a73f49ac3c46a6fd4d76071fe385c26b19f1264dd7eff67e5', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/index.php:669|check|<?php if (getDolGlobalString(''TAKEPOS_CHOOSE_CONTACT'')) { ?>", "takepos/index.php:1465|check|if (getDolGlobalString(''TAKEPOS_CHOOSE_CONTACT'')) {", "takepos/invoice.php:1678|check|if (getDolGlobalInt(''TAKEPOS_CHOOSE_CONTACT'')) {", "takepos/invoice.php:1695|check|<?php if (getDolGlobalInt(''TAKEPOS_CHOOSE_CONTACT'') == 0) { ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_COLOR_THEME', 'string', NULL, 'takepos', 'Selects the color theme for the TakePos point-of-sale interface.', 'Written at takepos/admin/appearance.php:57 via dolibarr_set_const and read at :110 for the select control. Checked as an integer at takepos/pay.php:85, takepos/split.php:163, and takepos/index.php:125 to apply theme-specific styling.', 'Changing this value switches the visual color theme of the TakePos UI; a value of 1 activates a specific alternate theme.', '0 or unset = default theme; 1 = alternate color theme.', 0, 0, 'takepos/admin/appearance.php|takepos/admin/appearance.php|takepos/admin/appearance.php', 1, '9914e732ef5ac17b0591325fb87636b195114fe25399aa85f71c639380b5ad52', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/appearance.php:57|write|$res = dolibarr_set_const($db, \"TAKEPOS_COLOR_THEME\", GETPOST(''TAKEPOS_COLOR_THEME'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/pay.php:85|check|if (getDolGlobalInt(''TAKEPOS_COLOR_THEME'') == 1) {", "takepos/split.php:163|check|if (getDolGlobalInt(''TAKEPOS_COLOR_THEME'') == 1) {", "takepos/index.php:125|check|if (getDolGlobalInt(''TAKEPOS_COLOR_THEME'') == 1) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CONNECTOR_TO_WHB_CUSTOMER_DISPLAY', 'string', NULL, 'takepos', 'Switches the TakePOS customer-facing display output from an AJAX call to a print server to sending lines over a WHB customer-display WebSocket connector.', 'Read in takepos/pay.php:544 and takepos/invoice.php:1919, both inside a TAKEPOS_CUSTOMER_DISPLAY block that builds a ''TotalTTC'' line1/line2 pair for the customer display.', 'When set, the two display lines are sent via webSocketCustomerDisplay.send()/onOpen() (WHB hardware connector) instead of an $.ajax GET to TAKEPOS_PRINT_SERVER.''/display/index.php''.', 'Truthy string selects the WebSocket/WHB connector path; empty/unset uses the default AJAX print-server path.', 0, 0, NULL, 1, 'fbd60a1ef7ae1248757f2b8a7d174789cbb14e94c348d5fb5c3c13f396ee3ab4', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/pay.php:544: if (getDolGlobalString(''TAKEPOS_CONNECTOR_TO_WHB_CUSTOMER_DISPLAY'')) { echo ''webSocketCustomerDisplay.onOpen(function() {''; ...", "takepos/invoice.php:1919: if (getDolGlobalString(''TAKEPOS_CONNECTOR_TO_WHB_CUSTOMER_DISPLAY'')) { echo ''webSocketCustomerDisplay.send(line1);''; ..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CONNECTOR_TO_WHB_SCALE', 'string', NULL, 'takepos', 'Enables the JS WeighingScale() function to talk to a WHB-brand weighing scale connector (as opposed to no external scale integration).', 'Checked at takepos/index.php:1107 wrapping the WeighingScale() JS body; only when true does the function attempt the protocol-specific scale communication (see WEIGHINGSCALE_PROTOCOL for the sub-protocol).', 'Enabling it activates the WHB scale connector code path inside WeighingScale(), including the diag06-protocol API calls when WEIGHINGSCALE_PROTOCOL is also set.', 'Boolean: true/1 enables WHB scale connector logic in WeighingScale(), false/unset disables it (function becomes a no-op body).', 1, 0, NULL, 1, '6d0bd034a5aa4349b5d82528e7783bea8d204b94622c84ef51ccd6fc7fd83fad', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1107|check|function WeighingScale(callback) { ... <?php if (getDolGlobalString(''TAKEPOS_CONNECTOR_TO_WHB_SCALE'')) {?> <?php if (getDolGlobalString(''WEIGHINGSCALE_PROTOCOL'') == \"diag06\") { ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CONTROL_CASH_OPENING', 'string', NULL, 'takepos', 'Forces an automatic cash-control (cash fence) popup at TakePOS terminal startup, once per calendar day per terminal.', 'Checked at takepos/index.php:1164; per the inline comment (fix for #38597), it looks for any pos_cash_fence row created today for the current entity/terminal, regardless of status, so the popup only fires on the first cash control of the day and does not re-fire after refreshing post-closure. Has an admin UI toggle: `ajax_constantonoff("TAKEPOS_CONTROL_CASH_OPENING", ...)` in takepos/admin/setup.php:393.', 'Enabling it makes TakePOS check for an existing cash fence created today on that terminal and, if none exists, presumably prompts the user to open/control the cash drawer at session start.', 'Boolean: true/1 enables the daily auto-open cash-control check per terminal, false/unset disables it.', 0, 0, NULL, 1, 'd562db79f21ace7fb176fcffba56a950e125d7e23032e81c121ec785481313b6', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1164|check|if (getDolGlobalString(''TAKEPOS_CONTROL_CASH_OPENING'')) { // Look for any cash control fence created today on this terminal, regardless of its status, so the auto-open popup only fires on the first cash control of a calendar day... (#38597)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_CUSTOMER_DISPLAY', 'string', NULL, 'takepos', 'Enables the customer-facing display feature in TakePos.', 'Checked at takepos/pay.php:532, takepos/index.php:592, takepos/invoice.php:955, and takepos/invoice.php:1824; when set, customer-display-related output or actions are triggered.', 'Enabling this constant activates the customer display integration across TakePos views; disabling it suppresses all customer-display output.', 'Empty/unset = customer display disabled; any truthy value = customer display enabled.', 1, 0, NULL, 1, 'a7b41f47217e1237f2f2cbc91e4e8c178a01a0aa6cd05501f931ccf04755e6ca', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/pay.php:532|check|if (getDolGlobalString(''TAKEPOS_CUSTOMER_DISPLAY'')) {", "takepos/index.php:592|check|<?php if (getDolGlobalString(''TAKEPOS_CUSTOMER_DISPLAY'')) {", "takepos/invoice.php:955|check|if (getDolGlobalString(''TAKEPOS_CUSTOMER_DISPLAY'')) {", "takepos/invoice.php:1824|check|if (getDolGlobalString(''TAKEPOS_CUSTOMER_DISPLAY'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_DELAYED_PAYMENT', 'string', NULL, 'takepos', 'Adds a ''Reported'' (delayed payment) button on the TakePOS payment screen, letting a sale be validated without immediate payment.', 'Read in takepos/pay.php:785, guarding the button that calls Validate(''delayed''). Configured via an on/off toggle in takepos/admin/setup.php:400 using ajax_constantonoff(''TAKEPOS_DELAYED_PAYMENT'', ...), i.e. it has an admin UI.', 'When set, the payment screen shows an extra ''Reported'' button that submits the sale with a delayed/deferred payment status instead of requiring a payment method to be selected immediately.', 'Truthy value (toggle) enables the ''Reported'' button; empty/unset (default) hides it.', 0, 0, NULL, 1, '9f6f3e0387e8b1301a8278d00c39cfdb6d9501a10e56cb4c926f6ec2f6c59c34', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/pay.php:785: if (getDolGlobalString(''TAKEPOS_DELAYED_PAYMENT'')) { print ''<button type=\"button\" class=\"calcbutton2\" onclick=\"Validate(\\''delayed\\'')\">''.$langs->trans(\"Reported\").''</button>'';", "takepos/admin/setup.php:400: print ajax_constantonoff(\"TAKEPOS_DELAYED_PAYMENT\", array(), $conf->entity, 0, 0, 1, 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_DELAYED_TERMS', 'string', NULL, 'takepos', 'Sets the payment-term code applied automatically to invoices created via TakePOS with delayed/deferred payment.', 'In takepos/invoice.php:457-458, when the elseif branch getDolGlobalInt(''TAKEPOS_DELAYED_TERMS'') is true, $invoice->setPaymentTerms(getDolGlobalInt(''TAKEPOS_DELAYED_TERMS'')) is called, i.e. the constant''s integer value is used directly as the payment-term id.', 'Setting it to a valid payment-condition id makes TakePOS assign that payment term to invoices in this code path instead of leaving/using another default.', 'Integer: id of a payment-terms/conditions record (c_payment_term); 0/unset disables this branch.', 1, 0, NULL, 1, 'd45d27121b4fe3f25073bcf0e4a6fa0d395ee533cc07767437f183f65de67a99', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:457|read|} elseif (getDolGlobalInt(\"TAKEPOS_DELAYED_TERMS\")) {", "takepos/invoice.php:458|read|$invoice->setPaymentTerms(getDolGlobalInt(\"TAKEPOS_DELAYED_TERMS\"));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_DIRECT_PAYMENT', 'string', NULL, 'takepos', 'Adds a ''Direct Payment (Cash)'' menu button in TakePOS for one-click cash payment, bypassing the normal payment screen.', 'Checked at takepos/index.php:1523 to add the DirectPayment() menu entry. Its admin UI toggle is present but commented out in takepos/admin/setup.php:354 (`//print $form->selectyesno("TAKEPOS_DIRECT_PAYMENT", $conf->global->TAKEPOS_DIRECT_PAYMENT, 1);`), so there is currently no live admin UI control for it.', 'Enabling it surfaces a ''DirectPayment (Cash)'' button in the TakePOS menu, which calls the JS DirectPayment() function (loads invoice.php with action=valid&pay=LIQ) to instantly settle the sale as cash without going through the standard payment popup.', 'Boolean: true/1 shows the direct-cash-payment menu button, false/unset (default) hides it.', 1, 0, 'takepos/admin/setup.php', 1, '59a80ad8cc6bd3212eee05e59c7ffdf84250560d1dcc24d30ada1d5ce4629fe4', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/admin/setup.php:354  //print $form->selectyesno(\"TAKEPOS_DIRECT_PAYMENT\", $conf->global->TAKEPOS_DIRECT_PAYMENT, 1);", "takepos/index.php:1523|check|if (getDolGlobalString(''TAKEPOS_DIRECT_PAYMENT'')) { $menus[$r++] = array(''title'' => ...''DirectPayment''...''Cash''... ''action'' => ''DirectPayment();''); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_DISCOUNT_TTC', 'string', NULL, 'takepos', 'Chooses whether a manually-entered TakePOS free-zone amount is treated as a tax-excl. (HT) or tax-incl. (TTC) price when adding the line.', 'In takepos/invoice.php:1047, inside $invoice->addline(...), the price-base-type argument is computed as `getDolGlobalInt(''TAKEPOS_DISCOUNT_TTC'') ? ($number >= 0 ? ''HT'' : ''TTC'') : (getDolGlobalInt(''TAKEPOS_CHANGE_PRICE_HT'') ? ''HT'' : ''TTC'')`.', 'Its value interacts with the sign of the entered amount and with TAKEPOS_CHANGE_PRICE_HT to decide whether the line is priced HT or TTC; exact combined behavior beyond this expression is unclear from code alone.', 'Integer/boolean: truthy value makes positive amounts use ''HT'' and negative amounts use ''TTC''; falsy value defers to TAKEPOS_CHANGE_PRICE_HT to choose ''HT'' vs ''TTC''.', 1, 0, NULL, 1, '174bde583b0598fc74ca18b9dfbe0519f41f18d23f2ef806f8f130167f4f6300', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:1047|read|getDolGlobalInt(''TAKEPOS_DISCOUNT_TTC'') ? ($number >= 0 ? ''HT'' : ''TTC'') : (getDolGlobalInt(''TAKEPOS_CHANGE_PRICE_HT'') ? ''HT'' : ''TTC'')"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_EMAIL_TEMPLATE_INVOICE', 'string', NULL, 'takepos', 'ID of the email template used when sending invoices by email from TakePOS.', 'Written via takepos/admin/setup.php:92 and rendered as a select list at setup.php:385. Checked in takepos/invoice.php:1411 with `> 0` guard, and read in takepos/send.php:85 as `$model_id`.', 'When set to a valid template ID, TakePOS uses that email template when emailing invoices to customers; when absent or zero, the default template or no template is used.', 'Integer: ID of a Dolibarr email template; 0 or absent = no template selected', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php', 1, '25b97a5e183ac18788055ae1d3e601fa1aaef1b9b5606e9bf5b249f9afe7f315', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"TAKEPOS_EMAIL_TEMPLATE_INVOICE\", GETPOST(''TAKEPOS_EMAIL_TEMPLATE_INVOICE'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''TAKEPOS_EMAIL_TEMPLATE_INVOICE'') && getDolGlobalInt(''TAKEPOS_EMAIL_TEMPLATE_INVOICE'') > 0) {", "$model_id = getDolGlobalInt(''TAKEPOS_EMAIL_TEMPLATE_INVOICE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ENABLE_PRINT_WITHOUT_DETAILS', 'bool', NULL, 'takepos', 'Controls whether the TakePOS admin setup page shows the toggle for printing receipts without line details.', 'In takepos/admin/receipt.php:223, this bool gates display of the ''PrintWithoutDetailsButton'' admin row, which in turn lets the user toggle the actual behavior constant TAKEPOS_PRINT_WITHOUT_DETAILS via ajax_constantonoff; the code comment notes that on certified (''ALNE running'') versions the underlying setting is forced back on regardless.', 'Enabling it exposes the ''print without details'' option in the TakePOS admin UI; the actual print behavior is controlled by the separate constant TAKEPOS_PRINT_WITHOUT_DETAILS, which the certified-version check can override.', 'true/1 = show the option row in TakePOS receipt admin; false/unset (default) = row hidden.', 0, 0, 'takepos/admin/receipt.php', 1, '9b15f15623c6e80414d9b123e2f59ab1e3ad585ef903fe61984a4e501165587b', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/admin/receipt.php:223: if (getDolGlobalString(''TAKEPOS_ENABLE_PRINT_WITHOUT_DETAILS'')) { // Note: even if set manually, if version is certified, option disabled later", "takepos/admin/receipt.php:233: print ajax_constantonoff(''TAKEPOS_PRINT_WITHOUT_DETAILS'', array(), $conf->entity, 0, 0, 1, 0, 0, 0, '''', '''', ''inline-block'', 0, '''');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ENABLE_SUMUP', 'bool', NULL, 'takepos', 'Enables SumUp card-payment terminal integration in TakePOS.', 'Read in takepos/admin/setup.php, takepos/admin/terminal.php, and takepos/pay.php to conditionally display SumUp-related UI and payment options. Configurable via the admin UI in takepos/admin/setup.php and takepos/admin/terminal.php.', 'When disabled, SumUp payment options and associated UI elements are hidden; when enabled, the SumUp payment flow becomes available at the POS terminal.', '0 = disabled; non-zero integer = enabled', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php|takepos/admin/terminal.php', 1, '68fbacf2a7f907dd7265ed734686ef7f0e109f3f92ce87bb019b9e054e9226d2', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalInt(''TAKEPOS_ENABLE_SUMUP'')) {", "takepos/admin/setup.php:495|check", "takepos/admin/terminal.php:288|check", "takepos/pay.php:753|check"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_FOOTER', 'string', NULL, 'takepos', 'Custom HTML/text footer printed at the bottom of TakePOS receipts.', 'Written via takepos/admin/receipt.php:62 (global) and takepos/admin/terminal.php:155 (per-terminal variant). Read in takepos/receipt.php:539 via make_substitutions() to append the footer text to the receipt output.', 'Changing this value immediately affects the footer section of all subsequently generated receipts; variable substitution is applied to the stored value.', 'Any HTML or plain-text string (supports Dolibarr substitution variables)', 0, 0, 'takepos/admin/receipt.php|takepos/admin/terminal.php', 1, '5bc81bada9dad81ae01ad81df9c19e63616c647bd6ce1c7d3d637888efa013f4', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"TAKEPOS_FOOTER\", GETPOST(''TAKEPOS_FOOTER'', ''restricthtml''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''TAKEPOS_FOOTER'') || getDolGlobalString($constFreeText)) {", "$newfreetext .= make_substitutions(getDolGlobalString(''TAKEPOS_FOOTER''), $substitutionarray);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_FORBID_SALES_TO_DEFAULT_CUSTOMER', 'string', NULL, 'takepos', 'Prevents creating sales for the default (anonymous) customer in TakePOS, requiring a specific customer to be selected.', 'Checked in takepos/admin/terminal.php:212 to conditionally show the customer selector, and in takepos/index.php:657 to enforce the restriction during a sale.', 'When enabled, cashiers cannot complete a sale without selecting a named customer; when absent or falsy, sales to the default anonymous customer are permitted.', 'Non-empty string / truthy value = forbid sales to default customer; absent or empty = allow', 0, 0, 'takepos/admin/terminal.php', 1, '18dabbadb7420f327d6ed50094439bca063676b0a6e0a04d75ab9b8f9ef369e0', 'v2', '2026-04-21T13:50:40+00:00', '["if (!getDolGlobalString(''TAKEPOS_FORBID_SALES_TO_DEFAULT_CUSTOMER'')) {", "if (getDolGlobalString(''TAKEPOS_FORBID_SALES_TO_DEFAULT_CUSTOMER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_FORCE_TERMINAL_SELECT', 'string', NULL, 'takepos', 'Removes the close/dismiss button from the TakePOS terminal-selection modal, forcing the user to pick a terminal.', 'Checked at takepos/index.php:1326: when false/unset, a close (X) span is rendered in the ModalTerminal header; when true, that close control is omitted so the modal cannot be dismissed without selecting a terminal.', 'Enabling it prevents users from closing the terminal-selection popup without choosing a terminal button, effectively forcing terminal selection on session start.', 'Boolean: true/1 hides the modal''s close button (forces selection), false/unset (default) shows a close button allowing dismissal.', 1, 0, NULL, 1, 'f07ed3303a0b1456ea0ed7fddda758d0fc379932bda7175a5f3b18b49b89a695', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1326|check|if (!getDolGlobalString(''TAKEPOS_FORCE_TERMINAL_SELECT'')) { ?> <span class=\"close\" ... onclick=\"...style.display = ''none'';\">&times;</span>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_GIFT_RECEIPT', 'string', NULL, 'takepos', 'Enables a ''gift receipt'' option/mode in TakePOS (a receipt variant, presumably without prices).', 'Checked in takepos/invoice.php:1495 (`if ($customprinttemplateallowed && getDolGlobalString(''TAKEPOS_GIFT_RECEIPT''))`); explicitly reset to 0 at takepos/receipt.php:146 (`$conf->global->TAKEPOS_GIFT_RECEIPT = 0;`); toggled in the admin UI via two ajax_constantonoff calls in takepos/admin/receipt.php:251 and 254.', 'Enabling it (together with a custom print template being allowed) changes which print path/template is used to produce a gift-style receipt; the code also programmatically forces it back to 0 in receipt.php after use, suggesting it is a one-shot/session toggle rather than a persistent preference [SPECULATION].', 'Boolean: 1/true activates gift-receipt behavior; 0/false (default, also forced after use) is normal receipt.', 0, 0, NULL, 1, 'cf619d6a4d16b151146a50f48f26a9c494bdd0dc27802a63174d5a5654bfe6b7', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:1495|check|if ($customprinttemplateallowed && getDolGlobalString(''TAKEPOS_GIFT_RECEIPT'')) {", "takepos/receipt.php:146|write|$conf->global->TAKEPOS_GIFT_RECEIPT = 0;", "takepos/admin/receipt.php:251|print ajax_constantonoff(\"TAKEPOS_GIFT_RECEIPT\", array(), $conf->entity, 0, 0, 1, 0, 0, 0, '''', '''', ''inline-block'', 0, '''', 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_GROUP_SAME_PRODUCT', 'string', NULL, 'takepos', 'Merges identical product lines added to a TakePOS ticket into a single line with a summed quantity instead of adding separate lines.', 'Checked in takepos/invoice.php:944 (getDolGlobalString) before adding a new product line; toggled via ajax_constantonoff in takepos/admin/setup.php:322, so it is exposed in the TakePOS admin setup UI.', 'Enabling it changes how repeated additions of the same product behave in a POS sale — grouped into one line vs. one line per add.', 'Boolean: 1/true groups same-product lines; 0/false (default) adds a separate line each time.', 0, 0, NULL, 1, 'b27af2ce4906df6d3376af94b7c80deb69ae5505ca371af76620b2efd2e7d618', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:944|check|if (getDolGlobalString(''TAKEPOS_GROUP_SAME_PRODUCT'')) {", "takepos/admin/setup.php:322|print ajax_constantonoff(\"TAKEPOS_GROUP_SAME_PRODUCT\", array(), $conf->entity, 0, 0, 1, 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HEADER', 'string', NULL, 'takepos', 'Custom HTML/text header printed at the top of TakePOS receipts.', 'Written via takepos/admin/receipt.php:61 (global) and takepos/admin/terminal.php:152 (per-terminal variant). Read in takepos/receipt.php:200 via make_substitutions() to prepend the header text to the receipt output.', 'Changing this value immediately affects the header section of all subsequently generated receipts; variable substitution is applied to the stored value.', 'Any HTML or plain-text string (supports Dolibarr substitution variables)', 0, 0, 'takepos/admin/receipt.php|takepos/admin/terminal.php', 1, '8ece1f225ecdd5e0cecdc4766570bcc69852c13af09b436230483c4bc9a6ebb0', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"TAKEPOS_HEADER\", GETPOST(''TAKEPOS_HEADER'', ''restricthtml''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''TAKEPOS_HEADER'') || getDolGlobalString($constFreeText)) {", "$newfreetext .= make_substitutions(getDolGlobalString(''TAKEPOS_HEADER''), $substitutionarray);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HEAD_BAR', 'string', NULL, 'takepos', 'Yes/no TakePOS setup setting, likely controlling display of a header bar on the POS screen.', 'Set via a yes/no form field in takepos/admin/setup.php:361 on the TakePOS module setup page; no further usage or comment was found describing exactly what UI element the head bar is.', 'Toggling it changes a display setting on the TakePOS screen labeled ''TAKEPOS_HEAD_BAR''; exact visual effect unclear from code alone [SPECULATION].', 'Boolean (yes/no) via $form->selectyesno.', 0, 0, 'takepos/admin/setup.php', 1, '87da7c616d971261011f549dfeb01f47f028285ae1b02a748b8957fdad5d10ef', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/admin/setup.php:361: print $form->selectyesno(\"TAKEPOS_HEAD_BAR\", $conf->global->TAKEPOS_HEAD_BAR, 1);"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_CATEGORIES', 'bool', NULL, 'takepos', 'Controls whether the product category panel is hidden in the TakePOS interface.', 'Checked in takepos/admin/appearance.php:121 and in takepos/index.php at lines 1661 and 1703 to conditionally hide category-related UI elements. Value 1 hides the categories panel.', 'Setting to 1 removes the category navigation panel from the POS screen; leaving unset or 0 keeps the panel visible.', '1 = hide categories panel; 0 or unset = show categories panel.', 0, 0, 'takepos/admin/appearance.php', 1, 'e6860fe9884f8a86087d983798743d9407e28d85e8e7f6f005a4d00d9773c6c9', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/appearance.php:121|check|if (!getDolGlobalString(''TAKEPOS_HIDE_CATEGORIES'')) {", "takepos/index.php:1661|check|if (getDolGlobalInt(''TAKEPOS_HIDE_CATEGORIES'') == 1) {", "takepos/index.php:1703|check|<div class=\"div5<?php if (getDolGlobalInt(''TAKEPOS_HIDE_CATEGORIES'') == 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_CATEGORY_IMAGES', 'bool', NULL, 'takepos', 'Hides category thumbnail images in the TakePOS category grid, showing only labels/buttons without icons.', 'Checked at takepos/index.php:1704: the <img class="imgwrapper" id="catimg..."> element for a category tile is only printed when this constant is falsy.', 'Enabling it removes the category image <img> tags from the TakePOS category grid tiles, leaving only the button/label without a picture.', 'Boolean: true/1 hides category images, false/unset (default) shows them.', 1, 0, NULL, 1, '196582d9d557c824b16ec18dbfa475aac7f0dddfc8071f5b2b9c2f4d2c8fa7ac', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1704|check|if (!getDolGlobalString(''TAKEPOS_HIDE_CATEGORY_IMAGES'')) { echo ''<img class=\"imgwrapper\" id=\"catimg''.$count.''\" />''; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_DATE_OF_PRINTING', 'bool', NULL, 'takepos', 'Hides the printing date/time on the TakePOS receipt, unless a specific vendor build (ALNE) is running.', 'Checked in takepos/receipt.php:265: `if (isALNERunningVersion() || !getDolGlobalString(''TAKEPOS_HIDE_DATE_OF_PRINTING''))` — the printing date is shown when either the ALNE variant is running, or this constant is not set.', 'Setting it (on non-ALNE builds) removes the date-of-printing line from the receipt output.', 'Boolean: true hides the printing date on the receipt (except on ALNE builds where it always shows); false/unset shows it.', 1, 0, NULL, 1, 'bdf0ca9808d0b54febd787ef7b6acae825806004d6829f5c7e2d2a30843c95fd', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/receipt.php:265|check|if (isALNERunningVersion() || !getDolGlobalString(''TAKEPOS_HIDE_DATE_OF_PRINTING'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_HEAD_BAR', 'bool', NULL, 'takepos', 'Controls whether the top header bar is hidden in the TakePOS interface.', 'Checked at takepos/index.php at lines 1231, 1380, 1464, 1578, 1644, and 1655 to conditionally hide or show the head bar element and adjust layout classes accordingly. No admin UI write is present.', 'Enabling this constant hides the header bar across the POS interface, freeing screen space; disabling it restores the header.', 'Non-empty string/truthy = hide header bar; unset/empty = show header bar.', 1, 0, NULL, 1, 'fa7b2e9cd225a964d93ccc277126b236a380a030b5922541b44ff7e1ce5bfd51', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/index.php:1231|check|if (!getDolGlobalString(''TAKEPOS_HIDE_HEAD_BAR'')) {", "takepos/index.php:1464|check|if (getDolGlobalString(''TAKEPOS_HIDE_HEAD_BAR'')) {", "takepos/index.php:1578|check|if (getDolGlobalString(''TAKEPOS_HIDE_HEAD_BAR'')) {", "takepos/index.php:1644|check|if (getDolGlobalString(''TAKEPOS_HIDE_HEAD_BAR'') && !getDolGlobalString(''TAKEPOS_HIDE_SEARCH'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_HISTORY', 'bool', NULL, 'takepos', 'Hides the ''History'' menu entry/button in the TakePOS action menu.', 'Checked at takepos/index.php:1479: only when this is falsy is the History() menu entry added to the $menus array used to render TakePOS action buttons.', 'Enabling it removes the History button/action from the TakePOS interface, preventing quick access to the History() JS action from the main menu.', 'Boolean: true/1 hides the History menu entry, false/unset (default) shows it.', 1, 0, NULL, 1, 'adc1409d49fe3d8be340a87f1f9696c4e8a6e114b81ffb9e440717611ae3a1cb', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1479|check|if (! getDolGlobalString(''TAKEPOS_HIDE_HISTORY'')) { $menus[$r++] = array(''title'' => ...''History''... ''action'' => ''History();''); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_PRODUCT_IMAGES', 'bool', NULL, 'takepos', 'Controls whether product images are hidden throughout the TakePOS interface.', 'Checked in takepos/ajax/ajax.php:241 and in takepos/index.php at lines 390, 415, 1730, and 1736. When set, product image elements are suppressed in both the product grid and related rendering logic. No admin UI write is present.', 'Enabling this constant removes product image display from the POS screen, which can improve performance on slow connections.', 'Non-empty string/truthy = hide product images; unset/empty = show product images.', 1, 0, NULL, 1, 'f682ed5b4eee0dfd5d2a52907d2785636f04ea218d8f98a11447e6118c6b8347', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/ajax/ajax.php:241|check|if (!getDolGlobalString(''TAKEPOS_HIDE_PRODUCT_IMAGES'')) {", "takepos/index.php:390|check|<?php if (!getDolGlobalString(''TAKEPOS_HIDE_PRODUCT_IMAGES'')) {", "takepos/index.php:1730|check|if (getDolGlobalString(''TAKEPOS_HIDE_PRODUCT_IMAGES'')) {", "takepos/index.php:1736|check|<?php if ($count != $MAXPRODUCT - 2 && $count != $MAXPRODUCT - 1 && !getDolGlobalString(''TAKEPOS_HIDE_PRODUCT_IMAGES'')) { ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_PRODUCT_PRICES', 'bool', NULL, 'takepos', 'Hides the displayed unit price under each product tile in the TakePOS product grid.', 'Checked at takepos/index.php:1746: the <div id="proprice..."> element showing the product price is only printed when this constant is falsy; works alongside the related TAKEPOS_HIDE_PRODUCT_IMAGES check for images.', 'Enabling it removes the visible price div from each product button in TakePOS, so cashiers see product tiles without a price label.', 'Boolean: true/1 hides product prices on tiles, false/unset (default) shows them.', 1, 0, NULL, 1, '253e7257f5188c2377c02c55697c9a441e06bf76c8b2e118eded7bf303ba0b46', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1746|check|if (!getDolGlobalString(''TAKEPOS_HIDE_PRODUCT_PRICES'')) { print ''<div class=\"\" id=\"proprice''.$count.''\"></div>''; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_SEARCH', 'bool', NULL, 'takepos', 'Suppresses the product search input box in TakePOS when the head bar is already hidden.', 'Checked at takepos/index.php:1663 combined with TAKEPOS_HIDE_HEAD_BAR: the search <input id="search"> block is only printed if TAKEPOS_HIDE_HEAD_BAR is true AND TAKEPOS_HIDE_SEARCH is false.', 'When TAKEPOS_HIDE_HEAD_BAR is enabled, setting TAKEPOS_HIDE_SEARCH additionally removes the fallback search input that would otherwise replace the hidden head bar''s search box.', 'Boolean: true/1 hides the search input (only relevant when TAKEPOS_HIDE_HEAD_BAR is also set), false/unset shows it.', 1, 0, NULL, 1, '353b9fd937117649c8a37503979fc7b24cdc1fcb1fdafd56e25760be529f32fb', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1663|check|if (getDolGlobalString(''TAKEPOS_HIDE_HEAD_BAR'') && !getDolGlobalString(''TAKEPOS_HIDE_SEARCH'')) { print ''<!-- Show the search input text -->''...; print ''<input type=\"text\" id=\"search\" ...>''; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_HIDE_STOCK_ON_LINE', 'bool', NULL, 'takepos', 'Hides the remaining-stock indicator displayed next to a product line in the TakePOS ticket.', 'Checked in takepos/invoice.php:2319: the stock indicator is shown only if a per-product constant is set, the line has a linked product, AND `!getDolGlobalString(''TAKEPOS_HIDE_STOCK_ON_LINE'')`; toggled via ajax_constantonoff in takepos/admin/appearance.php:157, part of TakePOS appearance settings.', 'Enabling it suppresses the stock quantity display on POS lines even when otherwise configured to show it.', 'Boolean: true hides the stock-on-line display; false/unset (default) allows it to show (subject to other conditions).', 0, 0, NULL, 1, '2479a51138a32ff221ec49eb7e8b7a67948de3b932bd7570151b5df716101267', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:2319|check|if (getDolGlobalString($constantforkey) && $line->fk_product > 0 && !getDolGlobalString(''TAKEPOS_HIDE_STOCK_ON_LINE'')) {", "takepos/admin/appearance.php:157|print ajax_constantonoff(\"TAKEPOS_HIDE_STOCK_ON_LINE\", array(), $conf->entity, 0, 0, 1, 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_LINES_TO_SHOW', 'bool', NULL, 'takepos', 'Sets the maximum number of text lines shown per product tile in the TakePOS CSS layout.', 'Set via takepos/admin/appearance.php:58 and read at line 150 via selectarray. Applied directly in takepos/css/pos.css.php:503 as the -webkit-line-clamp CSS value, defaulting to 2.', 'Increasing the value allows more product name text to be visible per tile; decreasing it truncates longer names earlier.', 'Integer number of lines; default is 2 when not set.', 0, 0, 'takepos/admin/appearance.php|takepos/admin/appearance.php', 1, '7939a87883ef083f40961dbbeb53b38d325750bb084b894adcacb55f1225b2ce', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/appearance.php:58|write|$res = dolibarr_set_const($db, \"TAKEPOS_LINES_TO_SHOW\", GETPOST(''TAKEPOS_LINES_TO_SHOW'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/admin/appearance.php:150|read|print $form->selectarray(''TAKEPOS_LINES_TO_SHOW'', $array, getDolGlobalInt(''TAKEPOS_LINES_TO_SHOW'', 2), 0);", "takepos/css/pos.css.php:503|read|-webkit-line-clamp: <?php echo getDolGlobalInt(''TAKEPOS_LINES_TO_SHOW'', 2); ?>;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NB_MAXCATEG', 'string', NULL, 'takepos', 'Maximum number of category tiles displayed per page/screen in the TakePOS category grid.', 'Read at takepos/index.php:94: $MAXCATEG = getDolGlobalInt(''TAKEPOS_NB_MAXCATEG'', $maxcategbydefaultforthisdevice), where the default $maxcategbydefaultforthisdevice is 12.', 'Increasing/decreasing the value changes how many category buttons are rendered per page in the TakePOS UI grid before pagination/arrows kick in.', 'Integer count of categories per page; default is 12 when unset.', 1, 0, NULL, 1, '04537fd56f80abff8f7eaba2128a314d893e337772013cf1cc0e17083ce9d95e', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:94|read|$MAXCATEG = getDolGlobalInt(''TAKEPOS_NB_MAXCATEG'', $maxcategbydefaultforthisdevice);", "takepos/index.php|$maxcategbydefaultforthisdevice = 12;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NB_MAXPRODUCT', 'string', NULL, 'takepos', 'Maximum number of product tiles displayed per page/screen in the TakePOS product grid.', 'Read at takepos/index.php:95: $MAXPRODUCT = getDolGlobalInt(''TAKEPOS_NB_MAXPRODUCT'', $maxproductbydefaultforthisdevice), where the default $maxproductbydefaultforthisdevice is 24.', 'Increasing/decreasing the value changes how many product buttons are rendered per page in the TakePOS UI grid before pagination/arrows kick in.', 'Integer count of products per page; default is 24 when unset.', 1, 0, NULL, 1, '57a2d772370315fbfc8fb91459c7464f4931d34d4edaa0960a9d1c160f64552f', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:95|read|$MAXPRODUCT = getDolGlobalInt(''TAKEPOS_NB_MAXPRODUCT'', $maxproductbydefaultforthisdevice);", "takepos/index.php|$maxproductbydefaultforthisdevice = 24;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NO_CREDITNOTE', 'string', NULL, 'takepos', 'Disables the ''create credit note'' button for closed TakePOS invoices.', 'In takepos/invoice.php:1955, the button to create a credit note is only rendered when the invoice is not itself a credit note, is closed, and `!getDolGlobalString(''TAKEPOS_NO_CREDITNOTE'')` is true.', 'Enabling it removes the ability to create a credit note directly from a closed TakePOS invoice''s screen.', 'Boolean: true hides the create-credit-note button; false/unset (default) shows it for closed invoices.', 1, 0, NULL, 1, '04049b36e84660876a51c866feca70db4e0a60eeffc182f57435894a7509762b', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:1955|read|&& $invoice->type != Facture::TYPE_CREDIT_NOTE && !getDolGlobalString(''TAKEPOS_NO_CREDITNOTE'') && $invoice->status == $invoice::STATUS_CLOSED) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NO_FREE_ZONE_PRODUCT', 'string', NULL, 'takepos', 'Hides the ''FreeZone'' menu entry that lets a cashier add a non-predefined (free-text/manual) product line in TakePOS.', 'Checked at takepos/index.php:1499: only when this is falsy is the FreeZone() menu entry added. Has an admin UI toggle: `ajax_constantonoff("TAKEPOS_NO_FREE_ZONE_PRODUCT", ...)` in takepos/admin/setup.php:421.', 'Enabling it removes the ability to add arbitrary/free-form products from the TakePOS menu, restricting sales to predefined catalog products only.', 'Boolean: true/1 disables/hides the free-zone (non-predefined product) menu entry, false/unset (default) shows it.', 0, 0, NULL, 1, '80a4720178fc27885fb8dd66039782d75d3819369c524207f3de49e485be64af', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1499|check|if (!getDolGlobalString(''TAKEPOS_NO_FREE_ZONE_PRODUCT'')) { $menus[$r++] = array(''title'' => ...''FreeZone''... ''action'' => ''FreeZone();''); }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NO_GENERIC_THIRDPARTY', 'string', NULL, 'takepos', 'Requires a specific (non-generic) customer to be selected in TakePOS before payment can proceed.', 'Checked at takepos/index.php:668 (JS guard on CloseBill: if no idcustomer set, alerts ''TakePosCustomerMandatory'' and opens Customer()/Contact() selection) and takepos/invoice.php:1776 (clears #idcustomer when no contact found).', 'Enabling it blocks the payment/close-bill flow until a real customer is chosen, forcing the cashier through the customer-selection popup instead of using the default generic walk-in customer.', 'Boolean/int: truthy enforces mandatory customer selection before payment, false/unset (default) allows the generic/default customer.', 1, 0, NULL, 1, '8c160ac7de4173206e073e4bf46ae70684735e6fd2d126dc81b059faa8f2898d', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:668|check|<?php if (getDolGlobalInt(\"TAKEPOS_NO_GENERIC_THIRDPARTY\")) { ?> if ($(\"#idcustomer\").val() == \"\") { alert(...''TakePosCustomerMandatory''...); }", "takepos/invoice.php:1776|read|} elseif (getDolGlobalInt(\"TAKEPOS_NO_GENERIC_THIRDPARTY\")) { print ''$(\"#idcustomer\").val(\"\");''; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NO_SPLIT_SALE', 'string', NULL, 'takepos', 'Hides the ''SplitSale'' menu entry that lets a cashier split a sale/ticket in TakePOS.', 'Checked at takepos/index.php:1517: only when this is falsy is the Split() menu entry added to the TakePOS action menu.', 'Enabling it removes the ability to split a sale into multiple tickets/payments from the TakePOS menu.', 'Boolean: true/1 disables/hides the split-sale menu entry, false/unset (default) shows it.', 1, 0, NULL, 1, '649f39996b491653438d8d68d6f96f30c0ebe73f39ca3bc338edba16c037741e', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1517|check|if (!getDolGlobalString(''TAKEPOS_NO_SPLIT_SALE'')) { $menus[$r++] = array(''title'' => ...''SplitSale''... ''action'' => ''Split();''); }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NUMPAD', 'string', NULL, 'takepos', 'Selects the numpad layout/mode used on the TakePos payment screen.', 'Written at takepos/admin/setup.php:88 via dolibarr_set_const and read at :338 for the select control. Checked as integer at takepos/pay.php:290, :302, and read at :629 into $numpad for rendering logic. Configurable via admin/setup.php.', 'Changing this value switches the numpad layout on the TakePos payment screen; a value of 0 activates the default numpad path.', '0 or unset = default numpad layout; other integer values = alternate numpad modes.', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php|takepos/admin/setup.php', 1, '79c929cd5d85874762e13c2ec53b4c39aaf3ac70096c3374f718525588470d33', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/setup.php:88|write|$res = dolibarr_set_const($db, \"TAKEPOS_NUMPAD\", GETPOST(''TAKEPOS_NUMPAD'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/pay.php:290|check|if (!getDolGlobalInt(\"TAKEPOS_NUMPAD\")) {", "takepos/pay.php:629|read|$numpad = getDolGlobalInt(''TAKEPOS_NUMPAD'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NUMPAD_USE_PAYMENT_ICON', 'bool', NULL, 'takepos', 'Controls whether the TakePOS payment numpad displays payment icons on its buttons.', 'Checked extensively in takepos/pay.php (26 occurrences) using the pattern `!isset(...) || getDolGlobalString(...)`, meaning the icon is shown by default when the constant is absent. No admin UI write path is present.', 'Setting this to a falsy value disables payment icons on the numpad buttons; leaving it unset or truthy keeps icons displayed by default.', 'Truthy (or absent) = show icons; falsy = hide icons', 1, 0, NULL, 1, '3a89e80a0e67342b4b7887ae4f802728591b864a3430bbb559600dc9225fd23e', 'v2', '2026-04-21T13:50:40+00:00', '["if (!isset($conf->global->TAKEPOS_NUMPAD_USE_PAYMENT_ICON) || getDolGlobalString(''TAKEPOS_NUMPAD_USE_PAYMENT_ICON'')) {", "takepos/pay.php:643|check", "takepos/pay.php:647|check"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_NUM_TERMINALS', 'string', NULL, 'takepos', 'Sets the total number of TakePOS terminals configured for the point-of-sale system.', 'Written via takepos/admin/setup.php:90 and displayed in the UI at takepos/admin/setup.php:289 with a default of ''1''. Used in takepos/invoice.php, takepos/phone.php, takepos/index.php, and compta/cashcontrol/cashcontrol_card.php to determine terminal selection logic (10 occurrences across multiple files).', 'Increasing this value makes additional terminal slots available; setting it to 1 simplifies the UI by skipping terminal selection steps.', 'Integer >= 1: number of TakePOS terminals. Defaults to ''1'' when not set.', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php', 1, '16a3112478f945a5b32cfe58c7b8946c6909cfec528b7d507a0c62ee6b975cd5', 'v2', '2026-04-21T11:16:15+00:00', '["takepos/admin/setup.php:289|read|print ''<input type=\"number\" name=\"TAKEPOS_NUM_TERMINALS\" min=\"1\" class=\"width50\" value=\"'' . getDolGlobalString(''TAKEPOS_NUM_TERMINALS'', ''1'') . ''\">'';", "takepos/invoice.php:84|check|if (getDolGlobalString(''TAKEPOS_NUM_TERMINALS'') == \"1\") {", "takepos/phone.php:311|check|if (getDolGlobalString(''TAKEPOS_NUM_TERMINALS'') != \"1\" && $_SESSION[\"takeposterminal\"] == \"\") {", "compta/cashcontrol/cashcontrol_card.php:678|read|$numterminals = max(1, getDolGlobalString(''TAKEPOS_NUM_TERMINALS''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ORDER_NOTES', 'string', NULL, 'takepos', 'Enables the order notes feature in TakePOS bar/restaurant mode, allowing cashiers to add notes to orders.', 'Checked in takepos/admin/bar.php:82 (value == 1) and in takepos/index.php:1544 where order notes trigger a print action via the takeposconnector. Configurable via the admin UI at takepos/admin/bar.php.', 'When set to 1, cashiers can add free-text notes to orders; when combined with the takeposconnector print method, notes are also sent to the printer.', '1 = order notes enabled; 0 or absent = disabled', 0, 0, 'takepos/admin/bar.php', 1, '8fce6b53950a58ed93f21ca6ef979675f8a7a49a8bbc1a02459587e46b7b42ed', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalInt(''TAKEPOS_ORDER_NOTES'') == 1) {", "if (getDolGlobalString(''TAKEPOS_PRINT_METHOD'') == \"takeposconnector\" && getDolGlobalString(''TAKEPOS_ORDER_NOTES'') == 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ORDER_PRINTER1_TO_USE', 'string', NULL, 'takepos', 'ID of the first order printer assigned to a TakePOS terminal for routing kitchen/bar order tickets (per-terminal constant, suffixed with terminal number).', 'Written via takepos/admin/terminal.php:127 and rendered as a printer select list at terminal.php:476. Read in takepos/invoice.php:1277 as the target printer for sendToPrinter when routing order tickets to printer 1.', 'Setting this to a valid printer ID routes order tickets for printer-1 categories to that printer; leaving it unset disables routing to order printer 1.', 'Integer: ID of a configured receipt printer; 0 or absent = no order printer 1 configured', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '3af5fd7934e795a0ace4c0569fa6189b20350e80d0f31332c304eb3ccea5b6c8', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"TAKEPOS_ORDER_PRINTER1_TO_USE\".$terminaltouse, GETPOST(''TAKEPOS_ORDER_PRINTER1_TO_USE''.$terminaltouse, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "print $form->selectarray(''TAKEPOS_ORDER_PRINTER1_TO_USE''.$terminal, $printers, getDolGlobalInt(''TAKEPOS_ORDER_PRINTER1_TO_USE''.$terminal), 1);", "$ret = $printer->sendToPrinter($invoice, getDolGlobalInt(''TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS''.$_SESSION[\"takeposterminal\"]), getDolGlobalInt(''TAKEPOS_ORDER_PRINTER1_TO_USE''.$_SESSI"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ORDER_PRINTER2_TO_USE', 'string', NULL, 'takepos', 'Stores the ID of the second order printer assigned to a given TakePOS terminal.', 'Set via takepos/admin/terminal.php (line 130) using dolibarr_set_const and read back at line 480 via a selectarray dropdown. Used at takepos/invoice.php:1309 when sending an order to a printer with sendToPrinter().', 'Changing the value redirects order printing to a different printer for the terminal; leaving it unset means no second order printer is used.', 'Integer printer ID as stored in the printers list; empty/0 means no second printer selected.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'cdcf96c125ba3d40d8fefe1071195603eafe4d803f10b5c2f3893cf1f19a131d', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/terminal.php:130|write|$res = dolibarr_set_const($db, \"TAKEPOS_ORDER_PRINTER2_TO_USE\".$terminaltouse, GETPOST(''TAKEPOS_ORDER_PRINTER2_TO_USE''.$terminaltouse, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/admin/terminal.php:480|read|print $form->selectarray(''TAKEPOS_ORDER_PRINTER2_TO_USE''.$terminal, $printers, getDolGlobalInt(''TAKEPOS_ORDER_PRINTER2_TO_USE''.$terminal), 1);", "takepos/invoice.php:1309|read|$ret = $printer->sendToPrinter($invoice, getDolGlobalInt(''TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS''.$_SESSION[\"takeposterminal\"]), getDolGlobalInt(''TAKEPOS_ORDER_PRINTER2_TO_USE''.$_SESSI"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ORDER_PRINTER3_TO_USE', 'string', NULL, 'takepos', 'Stores the ID of the third order printer assigned to a given TakePOS terminal.', 'Set via takepos/admin/terminal.php (line 133) using dolibarr_set_const and read back at line 484 via a selectarray dropdown. Used at takepos/invoice.php:1341 when sending an order to a printer with sendToPrinter().', 'Changing the value redirects order printing to a different printer for the terminal; leaving it unset means no third order printer is used.', 'Integer printer ID as stored in the printers list; empty/0 means no third printer selected.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '335b6c07200391ab5f94120bee201bc61e82bb8bdc16b62a4897e9d52616c297', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/terminal.php:133|write|$res = dolibarr_set_const($db, \"TAKEPOS_ORDER_PRINTER3_TO_USE\".$terminaltouse, GETPOST(''TAKEPOS_ORDER_PRINTER3_TO_USE''.$terminaltouse, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/admin/terminal.php:484|read|print $form->selectarray(''TAKEPOS_ORDER_PRINTER3_TO_USE''.$terminal, $printers, getDolGlobalInt(''TAKEPOS_ORDER_PRINTER3_TO_USE''.$terminal), 1);", "takepos/invoice.php:1341|read|$ret = $printer->sendToPrinter($invoice, getDolGlobalInt(''TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS''.$_SESSION[\"takeposterminal\"]), getDolGlobalInt(''TAKEPOS_ORDER_PRINTER3_TO_USE''.$_SESSI"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ORDER_PRINTERS', 'string', NULL, 'takepos', 'Number of order printers configured for TakePOS bar/restaurant mode.', 'Checked in takepos/admin/bar.php:144-149, takepos/admin/terminal.php:444 and :473 and :511, and takepos/index.php:1490. Used together with TAKEPOS_BAR_RESTAURANT to gate display of per-printer terminal configuration sections.', 'Setting this to a non-zero value enables the order printer configuration UI and routes orders to the corresponding printers; zero or absent means no order printers are configured.', 'Integer: number of order printers (e.g. 1, 2, 3); 0 or absent = no order printers', 0, 0, 'takepos/admin/bar.php|takepos/admin/bar.php|takepos/admin/terminal.php|takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'fb6fd09119d9b865818c20c3f0c5dc8774e50e974ebbbf74e3c7ce9ea9347f8f', 'v2', '2026-04-21T13:50:40+00:00', '["$orderprinterallowed = (getDolGlobalString(''TAKEPOS_BAR_RESTAURANT'') && getDolGlobalInt(''TAKEPOS_ORDER_PRINTERS''));", "if (getDolGlobalString(''TAKEPOS_ORDER_PRINTERS'')) {", "if (getDolGlobalString(''TAKEPOS_BAR_RESTAURANT'') && getDolGlobalInt(''TAKEPOS_ORDER_PRINTERS'') && $orderprinterallowed) {", "if (getDolGlobalInt(''TAKEPOS_ORDER_PRINTERS'') && $orderprinterallowed) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINTED_CATEGORIES_1', 'string', NULL, 'takepos', 'Semicolon-delimited list of product category IDs routed to order printer 1 in TakePOS bar/restaurant mode.', 'Written via takepos/admin/orderprinters.php:76 and read in takepos/invoice.php:1240 as `$catsprinter1 = explode('';'', getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_1''))`. The admin page checks membership using strpos to manage category assignment.', 'Changing this value determines which product categories are sent to order printer 1 when an order is placed; categories not in the list are not routed to printer 1.', 'Semicolon-delimited string of product category rowids (e.g. '';1;3;7;'')', 0, 0, 'takepos/admin/orderprinters.php|takepos/admin/orderprinters.php', 1, 'bb83a114f8626dc9a0c2f62f0b063d340cbdd89ac5bde375b61e7d52d12f5e5e', 'v2', '2026-04-21T13:50:40+00:00', '["dolibarr_set_const($db, \"TAKEPOS_PRINTED_CATEGORIES_1\", $printedcategories, ''chaine'', 0, '''', $conf->entity);", "$catsprinter1 = explode('';'', getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_1''));", "if (strpos(getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_1''), '';''.$row[\"rowid\"].'';'') !== false) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINTED_CATEGORIES_2', 'string', NULL, 'takepos', 'Semicolon-delimited list of product category IDs routed to order printer 2 in TakePOS bar/restaurant mode.', 'Written via takepos/admin/orderprinters.php:86 and read in takepos/invoice.php:1241 as `$catsprinter2 = explode('';'', getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_2''))`. The admin page checks membership using strpos to manage category assignment.', 'Changing this value determines which product categories are sent to order printer 2 when an order is placed.', 'Semicolon-delimited string of product category rowids (e.g. '';2;4;'')', 0, 0, 'takepos/admin/orderprinters.php|takepos/admin/orderprinters.php', 1, 'd93735b0157a1d3335d61c6d7cf5de025a7bfbf616e6d4ef19221d99d5532fec', 'v2', '2026-04-21T13:50:40+00:00', '["dolibarr_set_const($db, \"TAKEPOS_PRINTED_CATEGORIES_2\", $printedcategories, ''chaine'', 0, '''', $conf->entity);", "$catsprinter2 = explode('';'', getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_2''));", "if (strpos(getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_2''), '';''.$row[\"rowid\"].'';'') !== false) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINTED_CATEGORIES_3', 'string', NULL, 'takepos', 'Semicolon-delimited list of product category IDs routed to order printer 3 in TakePOS bar/restaurant mode.', 'Written via takepos/admin/orderprinters.php:96 and read in takepos/invoice.php:1242 as `$catsprinter3 = explode('';'', getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_3''))`. The admin page checks membership using strpos to manage category assignment.', 'Changing this value determines which product categories are sent to order printer 3 when an order is placed.', 'Semicolon-delimited string of product category rowids (e.g. '';5;6;'')', 0, 0, 'takepos/admin/orderprinters.php|takepos/admin/orderprinters.php', 1, '926145e6fce7e88840b899891eb2951711e803f6b3d6b7b4e210b63930361fc3', 'v2', '2026-04-21T13:50:40+00:00', '["dolibarr_set_const($db, \"TAKEPOS_PRINTED_CATEGORIES_3\", $printedcategories, ''chaine'', 0, '''', $conf->entity);", "$catsprinter3 = explode('';'', getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_3''));", "if (strpos(getDolGlobalString(''TAKEPOS_PRINTED_CATEGORIES_3''), '';''.$row[\"rowid\"].'';'') !== false) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINTER_TO_USE', 'string', NULL, 'takepos', 'ID of the receipt printer assigned to a TakePOS terminal (per-terminal constant, suffixed with terminal number).', 'Written via takepos/admin/terminal.php:124 and rendered as a printer select list at terminal.php:469. Read extensively in takepos/ajax/ajax.php to initiate and route print jobs, and in takepos/index.php:1537 to look up the printer name.', 'Setting this to a valid printer ID causes receipt print jobs to be sent to that printer; a value of 0 or absent falls back to the takeposconnector print method if configured.', 'Integer: ID of a configured receipt printer; 0 or absent = no dedicated printer selected', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'c9d799a10ed8e1471132e530324966b224ce4642ae86a3fe4ac047108db9284e', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"TAKEPOS_PRINTER_TO_USE\".$terminaltouse, GETPOST(''TAKEPOS_PRINTER_TO_USE''.$terminaltouse, ''alpha''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalInt(''TAKEPOS_PRINTER_TO_USE''.$term) > 0) {", "$printer->initPrinter(getDolGlobalInt(''TAKEPOS_PRINTER_TO_USE''.$term));", "$printer->sendToPrinter($object, $templateidtouse, getDolGlobalInt(''TAKEPOS_PRINTER_TO_USE''.$term));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINT_INVOICE_DOC_INSTEAD_OF_RECEIPT', 'string', NULL, 'takepos', 'Adds a link/button to open the generated invoice PDF document instead of (or alongside) the plain POS receipt.', 'Checked twice in takepos/invoice.php: line 1958 adds a button linking to `/document.php?...&file=<ref>.pdf` (the invoice PDF) next to the create-credit-note button when true; line 1469 gates a similar behavior elsewhere in the payment/print flow.', 'Enabling it exposes a link to the actual invoice PDF document (via document.php) instead of only the built-in POS receipt print.', 'Boolean: true shows/uses the invoice PDF document link; false/unset (default) uses the standard POS receipt only.', 1, 0, NULL, 1, '181839b01e7acc64b162af5baf0b310ab7373333449888f8455432a6ca8c9643', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:1958|check|if (getDolGlobalInt(''TAKEPOS_PRINT_INVOICE_DOC_INSTEAD_OF_RECEIPT'')) {", "takepos/invoice.php:1959|  href=... modulepart=facture&file=... invoice->ref .pdf", "takepos/invoice.php:1469|check|if (getDolGlobalInt(''TAKEPOS_PRINT_INVOICE_DOC_INSTEAD_OF_RECEIPT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINT_METHOD', 'string', NULL, 'takepos', 'Selects the printing method used by TakePOS to output receipts and order tickets.', 'Written via takepos/admin/receipt.php:81 and referenced extensively (20 occurrences) across takepos/admin/receipt.php, takepos/admin/terminal.php, takepos/ajax/ajax.php, and takepos/class/dolreceiptprinter.class.php to route print jobs through the correct mechanism.', 'Selecting an unsupported or misconfigured method prevents receipts from printing; the ''takeposconnector'' method additionally requires TAKEPOS_PRINT_SERVER to be set.', '"browser" = print via browser dialog; "receiptprinter" = use Dolibarr receipt printer module; "takeposconnector" = send to remote print server via TakePOS connector', 0, 0, 'takepos/admin/receipt.php|takepos/admin/receipt.php|takepos/admin/receipt.php|takepos/admin/receipt.php|takepos/admin/terminal.php|takepos/admin/receipt.php', 1, '603a7ba35dcdbdea0446c0fb21be5e2b7007baf752862bf7b3222ea815c7069d', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalString(''TAKEPOS_PRINT_METHOD'') == \"takeposconnector\" && !isModEnabled(''receiptprinter'')) {", "if (getDolGlobalString(''TAKEPOS_PRINT_METHOD'') == \"browser\" || getDolGlobalString(''TAKEPOS_PRINT_METHOD'') == \"takeposconnector\") {", "if (isModEnabled(''receiptprinter'') || getDolGlobalString(''TAKEPOS_PRINT_METHOD'') == \"receiptprinter\" || getDolGlobalString(''TAKEPOS_PRINT_METHOD'') == \"takeposconnector\") {", "dolibarr_set_const($db, \"TAKEPOS_PRINT_METHOD\", GETPOST(''value'', ''alpha''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINT_PAYMENT_METHOD', 'string', NULL, 'takepos', 'Enables printing of the payment method on TakePOS receipts.', 'Written in takepos/admin/receipt.php:184, takepos/receipt.php:453, and takepos/receipt.php:142. Checked in takepos/receipt.php:461 to conditionally include payment method details in the receipt output.', 'When enabled, the payment method (e.g. cash, card) is printed on the receipt; when absent or false, the payment method section is omitted.', '1 = print payment method; 0 or absent = do not print', 0, 0, 'takepos/admin/receipt.php', 1, '714a8f5fdc1b5e56d1f42d4972f26ff2203262af903d8006aa39353e90ddf3eb', 'v2', '2026-04-21T13:50:40+00:00', '["$conf->global->TAKEPOS_PRINT_PAYMENT_METHOD = 1;", "if (getDolGlobalString(''TAKEPOS_PRINT_PAYMENT_METHOD'')) {", "takepos/receipt.php:461|check"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINT_SERVER', 'string', NULL, 'takepos', 'URL or IP address of the remote print server used by the TakePOS connector to send receipt HTML for printing.', 'Stores the address of the print server for the TakePOS connector print method. Used in takepos/invoice.php and takepos/index.php to decide how to route print jobs. When the value is a URL it is posted directly; when it is an IP address the system calls TAKEPOS_PRINT_SERVER:8111/print with the receipt HTML content.', 'Without a valid URL or IP set here the takeposconnector print method cannot send receipts to the remote printer; print operations using that method will silently skip or fail.', 'Valid URL (e.g. http://192.168.1.10) or raw IP address', 0, 0, 'takepos/admin/receipt.php|takepos/admin/receipt.php|takepos/admin/receipt.php', 1, '902f94c11e40ab02f18c11d1c27c20cf121b838f14a203b9967da5516516a319', 'v2', '2026-04-21T13:50:40+00:00', '["// If TAKEPOS_PRINT_SERVER is an URL", "// If TAKEPOS_PRINT_SERVER is an IP", "// Print by calling the receipt.php to get HTML content and send the HTML content to TAKEPOS_PRINT_SERVER:8111/print", "if (getDolGlobalString(''TAKEPOS_PRINT_METHOD'') == \"takeposconnector\" && filter_var(getDolGlobalString(''TAKEPOS_PRINT_SERVER''), FILTER_VALIDATE_URL) == true) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINT_WITHOUT_DETAILS', 'string', NULL, 'takepos', 'Enables condensed receipt printing that omits individual line-item details.', 'Written to 1 in takepos/admin/receipt.php:228 and to 0 in takepos/receipt.php:144. Checked in takepos/admin/receipt.php:235 and takepos/invoice.php:1403 to conditionally suppress line details in print output.', 'When enabled, printed receipts show only summary totals without individual product lines; when disabled, full line-item details are included.', '1 = print without line details; 0 = print full details', 0, 0, 'takepos/admin/receipt.php|takepos/admin/receipt.php', 1, '1a3af3e4b83245dae8d925d3a91eefea289382d1fecb15f94838c4b763158ddb', 'v2', '2026-04-21T13:50:40+00:00', '["$conf->global->TAKEPOS_PRINT_WITHOUT_DETAILS = 1;", "$conf->global->TAKEPOS_PRINT_WITHOUT_DETAILS = 0;", "if (getDolGlobalString(''TAKEPOS_PRINT_WITHOUT_DETAILS'')) {", "if ($customprinttemplateallowed && getDolGlobalString(''TAKEPOS_PRINT_WITHOUT_DETAILS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRINT_WITHOUT_DETAILS_LABEL_DEFAULT', 'string', NULL, 'takepos', 'Defines the default label text printed on a TakePOS receipt when the ''print without details'' option is active.', 'Written via takepos/admin/receipt.php:65 and displayed in the admin UI at receipt.php:239 as a text input. Read at takepos/printbox.php:102 into the variable $label_default for use during receipt generation.', 'Changing this value alters the label shown on condensed receipts; leaving it empty results in no default label being applied.', 'Any string (free-text label for condensed receipts)', 0, 0, 'takepos/admin/receipt.php|takepos/admin/receipt.php', 1, '66c936ebf61e9e6b728701b87e3e4ab3a0a7f547706c389007c23fc322e96d97', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, ''TAKEPOS_PRINT_WITHOUT_DETAILS_LABEL_DEFAULT'', GETPOST(''TAKEPOS_PRINT_WITHOUT_DETAILS_LABEL_DEFAULT'', ''alphanohtml''), ''chaine'', 0, '''', $conf->entity)", "$label_default = getDolGlobalString(''TAKEPOS_PRINT_WITHOUT_DETAILS_LABEL_DEFAULT'');", "print ''<input type=\"text\" name=\"TAKEPOS_PRINT_WITHOUT_DETAILS_LABEL_DEFAULT\" value=\"'' . getDolGlobalString(''TAKEPOS_PRINT_WITHOUT_DETAILS_LABEL_DEFAULT'') . ''\" />'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_PRODUCT_IN_STOCK', 'string', NULL, 'takepos', 'Restricts the TakePOS product list to only show products currently in stock.', 'Checked at multiple points in takepos/ajax/ajax.php (lines 118, 283, 307, 328, 339). When set to 1, stock availability is verified against the terminal''s assigned warehouse before adding products. No admin UI write is present.', 'Enabling this constant filters out out-of-stock products from the POS product list, preventing their addition to sales orders.', '1 = only show/add products with available stock; 0 or unset = no stock filter applied.', 1, 0, NULL, 1, '00fe8dc2541d3cda8062734b82638bdb7dd0128ac829d162b991fcd24caaa751', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/ajax/ajax.php:118|check|if (getDolGlobalInt(''TAKEPOS_PRODUCT_IN_STOCK'') == 1) {", "takepos/ajax/ajax.php:283|check|if (getDolGlobalInt(''TAKEPOS_PRODUCT_IN_STOCK'') == 1) {", "takepos/ajax/ajax.php:328|check|if (getDolGlobalInt(''TAKEPOS_PRODUCT_IN_STOCK'') == 1 && getDolGlobalInt(''CASHDESK_ID_WAREHOUSE''.$_SESSION[''takeposterminal''])) {", "takepos/ajax/ajax.php:339|check|if (getDolGlobalInt(''TAKEPOS_PRODUCT_IN_STOCK'') == 1 && !getDolGlobalInt(''CASHDESK_ID_WAREHOUSE''.$_SESSION[''takeposterminal''])) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_QR_MENU', 'string', NULL, 'takepos', 'Enables the QR code digital menu feature in TakePOS bar/restaurant mode.', 'Checked in takepos/admin/bar.php:217 to conditionally display QR menu configuration options, and in takepos/public/menu.php:45 where a falsy value exits the page entirely, preventing access to the public menu.', 'When enabled, the public QR menu endpoint is accessible and the admin shows related settings; when absent or zero, the public menu page is inaccessible.', 'Non-zero integer = QR menu enabled; 0 or absent = disabled', 0, 0, 'takepos/admin/bar.php', 1, '981d7bdf8765df26c209c22f9f5c7b1c34d01bc67a0dffcd8ac9d0131cab9e92', 'v2', '2026-04-21T13:50:40+00:00', '["if (getDolGlobalInt(''TAKEPOS_QR_MENU'')) {", "if (!$conf->global->TAKEPOS_QR_MENU) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_QTY_IN_STOCK', 'string', NULL, 'takepos', 'Enforces a stock-quantity check in TakePOS, preventing sale of more units than currently in stock (stock_reel).', 'Used twice in takepos/invoice.php: line 951 checks `(($line->qty + $qty) > $prod->stock_reel)` when adding to an existing line, and line 1009 checks `$qty > $prod->stock_reel` when adding a new line; both gated by getDolGlobalString(''TAKEPOS_QTY_IN_STOCK'').', 'Enabling it blocks/limits adding quantities of a product beyond its real stock level in TakePOS sales.', 'Boolean: true enforces the stock_reel limit on POS line quantities; false/unset (default) allows selling beyond stock.', 1, 0, NULL, 1, '1c337f9a40f631dbd4efa419ca67193902e9dcfa9eeea94f23ad8b542179c4e9', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:951|check|if (getDolGlobalString(''TAKEPOS_QTY_IN_STOCK'') && (($line->qty + $qty) > $prod->stock_reel)) {", "takepos/invoice.php:1009|check|if (getDolGlobalString(''TAKEPOS_QTY_IN_STOCK'') && $qty > $prod->stock_reel) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_RECEIPT_NAME', 'string', NULL, 'takepos', 'Custom name or title printed on TakePOS receipts.', 'Written via takepos/admin/receipt.php:63 and displayed in the admin UI at receipt.php:167. Read at takepos/receipt.php:229 where it is printed directly on the receipt output.', 'Changing this value alters the name label appearing on all subsequently generated receipts.', 'Any string (free-text receipt name/title)', 0, 0, 'takepos/admin/receipt.php|takepos/admin/receipt.php', 1, '51416049d7552e6a98fb88e15b54e9b7396e7fd3df63d9b09805899b139078a1', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"TAKEPOS_RECEIPT_NAME\", GETPOST(''TAKEPOS_RECEIPT_NAME'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "if (getDolGlobalString(''TAKEPOS_RECEIPT_NAME'')) {", "print getDolGlobalString(''TAKEPOS_RECEIPT_NAME'') . \" \";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_REF_ADDON', 'string', NULL, 'compta', 'Specifies the numbering module used to generate reference numbers for TakePOS point-of-sale invoices.', 'Configured via takepos/admin/setup.php:124 and used in compta/facture/class/facture.class.php:5117-5121. When not set, the system defaults to ''mod_takepos_ref_simple''; the configured addon module name is loaded to generate POS invoice references.', 'Changing this value switches the reference numbering scheme for TakePOS invoices; if the specified module does not exist, invoice creation will fail.', 'String name of a TakePOS numbering module (e.g., ''mod_takepos_ref_simple''); empty defaults to ''mod_takepos_ref_simple''', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php', 1, '7aaee3ffabb38889c02ee7569bcd8dcacab7523ff34f947780e5de21c5c716ce', 'v2', '2026-04-21T11:16:15+00:00', '["takepos/admin/setup.php:124|write|dolibarr_set_const($db, \"TAKEPOS_REF_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "compta/facture/class/facture.class.php:5117|check|if (!getDolGlobalString(''TAKEPOS_REF_ADDON'')) {", "compta/facture/class/facture.class.php:5118|write|$conf->global->TAKEPOS_REF_ADDON = ''mod_takepos_ref_simple'';", "compta/facture/class/facture.class.php:5121|read|$addon = getDolGlobalString(''TAKEPOS_REF_ADDON'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_REF_UNIVERSAL_MASK', 'string', NULL, 'core', 'Defines the mask/pattern used to generate the universal reference for TakePOS documents.', 'Read and displayed in an input field in core/modules/takepos/mod_takepos_ref_universal.php:95, and used to build the mask at line 142.', 'Changing the mask changes the format of the generated TakePOS universal reference.', NULL, 0, 0, NULL, 1, '517898c29f6a296e27f4788a002af0dc6ed33f5046d7b2af83c603a92a6073fe', 'v2', '2026-07-24T06:41:12+00:00', '["$texte .= ''<td class=\"right\">''.$form->textwithpicto(''<input type=\"text\" class=\"flat minwidth175\" name=\"maskvalue\" value=\"''.getDolGlobalString(''TAKEPOS_REF_UNIVERSAL_MASK'').''\">'', $t", "$mask = getDolGlobalString(''TAKEPOS_REF_UNIVERSAL_MASK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_ROOT_CATEGORY_ID', 'string', NULL, 'takepos', 'Specifies the root product category ID used to filter the product list in the TakePos point-of-sale interface.', 'Set via takepos/admin/setup.php:86; read and applied in takepos/ajax/ajax.php:172, takepos/index.php:149, and takepos/phone.php:162. When greater than 0, only products within the specified category tree are shown.', 'Setting this restricts the TakePos product browser to a specific category subtree; setting it to 0 or leaving it unset shows all products.', 'Integer category ID; 0 or unset means no category filter.', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php', 1, 'd37ee00b38a35b8e1891b135be4fc6bdc6344a4d6d708c18716c64371fc3852d', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/ajax/ajax.php:172|check|if (getDolGlobalInt(''TAKEPOS_ROOT_CATEGORY_ID'') > 0) {\t// A root category is defined, we must filter on products inside this category tree", "takepos/admin/setup.php:86|write|$res = dolibarr_set_const($db, \"TAKEPOS_ROOT_CATEGORY_ID\", GETPOST(''TAKEPOS_ROOT_CATEGORY_ID'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/index.php:149|check|if (getDolGlobalInt(''TAKEPOS_ROOT_CATEGORY_ID'') > 0) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SEND_INVOICE_AS_PDF', 'string', NULL, 'takepos', 'Controls whether TakePOS emails the invoice as a PDF attachment or as an inline ticket/receipt body.', 'Checked in takepos/send.php:97: if not set, the code renders and includes takepos/receipt.php into an output buffer to build an inline receipt; the else branch (PDF path) attaches the invoice''s last_main_doc file when the template allows joined files.', 'When set/true, TakePOS sends the invoice email with the PDF document attached (using the invoice''s last generated document) instead of an inline text/HTML receipt.', 'Boolean-like: truthy sends the invoice as a PDF attachment instead of an inline receipt.', 0, 0, NULL, 1, '9e097ff96ecd5b87e4c868a760d266b6f8b4a93c62c16ecb3ed6f05dbe77a3d8', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/send.php:97: if (!getDolGlobalString(''TAKEPOS_SEND_INVOICE_AS_PDF'')) {", "takepos/send.php:98-101: builds inline receipt via takepos/receipt.php include when constant is unset"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SHOW_CATEGORY_DESCRIPTION', 'bool', NULL, 'takepos', 'Controls whether category descriptions are displayed in the TakePOS product category panel.', 'Checked at takepos/index.php lines 251, 294, and 341; value 1 triggers rendering of category description text in three different category display sections. No admin UI write is present.', 'Setting to 1 shows category descriptions in the POS category panel; leaving unset or 0 hides them.', '1 = show category descriptions; 0 or unset = hide category descriptions.', 1, 0, NULL, 1, '12f63c43c9486127d15a6e608a9eaf00ed011cd829edbc0e8acd4591ef8b7e2a', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/index.php:251|check|if (getDolGlobalString(''TAKEPOS_SHOW_CATEGORY_DESCRIPTION'') == 1) { ?>", "takepos/index.php:294|check|if (getDolGlobalString(''TAKEPOS_SHOW_CATEGORY_DESCRIPTION'') == 1) { ?>", "takepos/index.php:341|check|<?php if (getDolGlobalString(''TAKEPOS_SHOW_CATEGORY_DESCRIPTION'') == 1) { ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SHOW_CUSTOMER', 'bool', NULL, 'takepos', 'Controls whether the customer/thirdparty name is shown on the printed TakePOS receipt.', 'Read via getDolGlobalString in takepos/receipt.php:250 to conditionally print customer info on the receipt; toggled via ajax_constantonoff in takepos/admin/receipt.php:174, so it is set through the TakePOS admin UI.', 'Enabling it adds the customer name/info block to the printed receipt.', 'Boolean: 1/true shows customer on receipt, 0/false (default) hides it.', 0, 0, NULL, 1, '13e523d6045ea3650dcbf677551655c39330d8dbda958e97f1673d955430a843', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/receipt.php:250|check|if (getDolGlobalString(''TAKEPOS_SHOW_CUSTOMER'')) {", "takepos/admin/receipt.php:174|print ajax_constantonoff(\"TAKEPOS_SHOW_CUSTOMER\", array(), $conf->entity, 0, 0, 1, 0);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SHOW_HT', 'bool', NULL, 'takepos', 'Controls whether tax-exclusive (HT) amounts are displayed alongside TTC totals in the TakePOS invoice view.', 'Checked at takepos/invoice.php at lines 1876, 1933, 2272, 2304, and 2314; when set, HT price/total columns are rendered in the invoice display. No admin UI write is present.', 'Enabling this constant shows pre-tax amounts in the POS invoice view; leaving it unset displays only tax-inclusive totals.', 'Non-empty string/truthy = show HT (pre-tax) amounts; 0 or unset = show TTC only.', 1, 0, NULL, 1, '2a60a7a9a19ae9861c15a6cd36cf45314af4553ffef229411fb33a007339c9ce', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/invoice.php:1876|check|if (getDolGlobalString(''TAKEPOS_SHOW_HT'')) {", "takepos/invoice.php:1933|check|if (getDolGlobalString(''TAKEPOS_SHOW_HT'')) {", "takepos/invoice.php:2272|check|if (getDolGlobalInt(''TAKEPOS_SHOW_HT'')) {", "takepos/invoice.php:2314|check|if (getDolGlobalString(''TAKEPOS_SHOW_HT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SHOW_HT_RECEIPT', 'bool', NULL, 'takepos', 'Controls whether amounts are shown tax-excluded (HT) on the TakePOS receipt.', 'Configured via admin UI takepos/admin/receipt.php:198 (writes value 1) and also set at takepos/receipt.php:143; checked at takepos/receipt.php:328, 346, and 368 to control receipt display.', 'When enabled, the TakePOS receipt template displays HT (tax-excluded) amount sections; when disabled, those sections are skipped.', NULL, 0, 0, 'takepos/admin/receipt.php', 1, 'b2d80856a63a45f24022fbb8c24837dadd6bc8dd04320d5bc2e574b1cf190570', 'v2', '2026-07-24T06:41:12+00:00', '["$conf->global->TAKEPOS_SHOW_HT_RECEIPT = 1;", "<?php if (getDolGlobalString(''TAKEPOS_SHOW_HT_RECEIPT'')) { ?>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SHOW_N_FIRST_LINES', 'bool', NULL, 'takepos', 'Truncates each TakePOS line''s description to only its first N lines/characters instead of showing the full text.', 'In takepos/invoice.php:2221, `if (!getDolGlobalString(''TAKEPOS_SHOW_N_FIRST_LINES''))` guards showing the full description; when set, line 2264 computes `$firstline = dolGetFirstLineOfText($line->desc, getDolGlobalInt(''TAKEPOS_SHOW_N_FIRST_LINES''))` to truncate it.', 'Setting it to a positive integer truncates each POS line''s description display to that many first lines via dolGetFirstLineOfText(); unset shows the full description.', 'Integer: number of first lines of description to display; 0/unset shows the full description text.', 1, 0, NULL, 1, '42c56255a5ce21b22ef7b017c40f507fb62d5ab576e2dc5df99ca34e9ac4360c', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:2221|check|if (!getDolGlobalString(''TAKEPOS_SHOW_N_FIRST_LINES'')) {", "takepos/invoice.php:2264|read|$firstline = dolGetFirstLineOfText($line->desc, getDolGlobalInt(''TAKEPOS_SHOW_N_FIRST_LINES''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SHOW_PRINT_COUNTER_ON_RECEIPT', 'bool', NULL, 'takepos', 'When enabled, shows the print counter number on TakePos receipts marked as duplicates.', 'Checked at takepos/receipt.php:302 and takepos/class/dolreceiptprinter.class.php:680. When truthy, blockedlog/lib/blockedlog.lib.php:537 appends the print counter (pos_print_counter - 1) to the DUPLICATA label on the receipt PDF.', 'Enabling this constant causes duplicate receipts to display their print count (e.g. ''DUPLICATA (no 2)''), aiding audit trail identification.', 'Boolean/truthy: non-empty value enables the feature; empty/unset disables it.', 1, 0, NULL, 1, 'e62aa6cc0b57e0422bdd83710194a208d7c426aa737add8942b9b129f82b0f78', 'v2', '2026-04-21T11:16:15+00:00', '["if (getDolGlobalString(''TAKEPOS_SHOW_PRINT_COUNTER_ON_RECEIPT'')) {", "''*** ''.$outputlangs->trans(\"DUPLICATA\").(getDolGlobalString(''TAKEPOS_SHOW_PRINT_COUNTER_ON_RECEIPT'') ? '' (no ''.($object->pos_print_counter - 1).'')'' : '''').'' ***''"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SHOW_PRODUCT_REFERENCE', 'bool', NULL, 'takepos', 'Controls how the product reference is displayed on product tiles in the TakePOS interface.', 'Set via takepos/admin/appearance.php:60 and rendered via selectarray at line 141. Checked in takepos/index.php at lines 417, 532, 831 (value==1) and lines 419, 534 (value==2); also checked in takepos/invoice.php:2145.', 'Changing the value toggles whether and how the product reference code appears on POS product tiles and invoice lines.', '1 = show product reference; 2 = show product reference in a different display mode; 0 or unset = do not show reference.', 0, 0, 'takepos/admin/appearance.php|takepos/admin/appearance.php', 1, '661c92c360578ec81cd9136825fa88825d641da289b9542b616e6187164ea910', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/appearance.php:60|write|$res = dolibarr_set_const($db, \"TAKEPOS_SHOW_PRODUCT_REFERENCE\", GETPOST(''TAKEPOS_SHOW_PRODUCT_REFERENCE'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/index.php:417|check|if (getDolGlobalInt(''TAKEPOS_SHOW_PRODUCT_REFERENCE'') == 1) {", "takepos/index.php:419|read|} elseif (getDolGlobalInt(''TAKEPOS_SHOW_PRODUCT_REFERENCE'') == 2) {", "takepos/invoice.php:2145|check|if (getDolGlobalInt(''TAKEPOS_SHOW_PRODUCT_REFERENCE'') == 1) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SHOW_SUBPRICE', 'bool', NULL, 'takepos', 'Shows the unit sub-price (price per unit) column/value for lines in the TakePOS ticket display.', 'Checked twice via getDolGlobalInt in takepos/invoice.php at lines 2018 and 2311, both gating display logic for POS invoice lines.', 'Enabling it adds the per-unit subprice to the TakePOS line display.', 'Boolean: true shows the subprice; false/unset (default) hides it.', 1, 0, NULL, 1, 'b96a4eef118fcb1e7f566143cb171f211f5fd5240cefca3a1a905addfed96ca1', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/invoice.php:2018|check|if (getDolGlobalInt(\"TAKEPOS_SHOW_SUBPRICE\")) {", "takepos/invoice.php:2311|check|if (getDolGlobalInt(\"TAKEPOS_SHOW_SUBPRICE\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SORTPRODUCTFIELD', 'string', NULL, 'takepos', 'Field name used to sort products displayed in the TakePOS product catalog.', 'Written via takepos/admin/setup.php:89 and rendered as a select array at setup.php:316 with default ''rowid''. Read in takepos/ajax/ajax.php:111 as the sort field for `getObjectsInCateg` and in takepos/public/menu.php:100 for the public QR menu product listing.', 'Changing this value changes the order in which products are listed in the POS interface and the public QR menu.', 'Database field name string (e.g. ''rowid'', ''label'', ''ref''); default is ''rowid''', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php', 1, '6338947de0531f242fb322fd41ead2435c51168ccc1293ef4e2e7059edf91529', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"TAKEPOS_SORTPRODUCTFIELD\", GETPOST(''TAKEPOS_SORTPRODUCTFIELD'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "$prods = $object->getObjectsInCateg(\"product\", 0, $limit, $offset, getDolGlobalString(''TAKEPOS_SORTPRODUCTFIELD''), ''ASC'', $filter);", "print $form->selectarray(''TAKEPOS_SORTPRODUCTFIELD'', $array, getDolGlobalString(''TAKEPOS_SORTPRODUCTFIELD'', ''rowid''), 0, 0, 0, '''', 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SUMUP_AFFILIATE', 'string', NULL, 'takepos', 'Stores the SumUp affiliate key used to initiate SumUp payments from TakePos.', 'Written at takepos/admin/setup.php:94 via dolibarr_set_const and displayed in a text input at :508. Read at takepos/pay.php:508 where it is URL-encoded into the sumupmerchant:// deep-link URI.', 'Setting this constant with a valid SumUp affiliate key enables SumUp payment processing in TakePos; leaving it empty disables SumUp integration.', 'Any SumUp affiliate key string; empty/unset = SumUp not configured.', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php', 1, '01e0d4e529694d4555631a35634ac77760afbcf2695f1f69e9ee2aacad15d723', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/setup.php:94|write|$res = dolibarr_set_const($db, \"TAKEPOS_SUMUP_AFFILIATE\", GETPOST(''TAKEPOS_SUMUP_AFFILIATE'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/pay.php:508|read|window.open(''sumupmerchant://pay/1.0?affiliate-key=<?php echo urlencode(getDolGlobalString(''TAKEPOS_SUMUP_AFFILIATE'')) ?>&app-id=<?php echo urlencode(getDolGlobalString(''TAKEPOS_SU"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SUMUP_APPID', 'string', NULL, 'takepos', 'Stores the SumUp application ID used to initiate SumUp payments from TakePos.', 'Written at takepos/admin/setup.php:95 via dolibarr_set_const and displayed in a text input at :513. Read at takepos/pay.php:508 where it is URL-encoded into the sumupmerchant:// deep-link URI alongside TAKEPOS_SUMUP_AFFILIATE.', 'Setting this constant with a valid SumUp app ID enables SumUp payment processing in TakePos; leaving it empty disables SumUp integration.', 'Any SumUp application ID string; empty/unset = SumUp not configured.', 0, 0, 'takepos/admin/setup.php|takepos/admin/setup.php', 1, 'fc5c489e3aea039e0a1e5b5cd9fecbbff170468b07aebed0c7dbdb09fafa8ce8', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/setup.php:95|write|$res = dolibarr_set_const($db, \"TAKEPOS_SUMUP_APPID\", GETPOST(''TAKEPOS_SUMUP_APPID'', ''alpha''), ''chaine'', 0, '''', $conf->entity);", "takepos/pay.php:508|read|window.open(''sumupmerchant://pay/1.0?affiliate-key=<?php echo urlencode(getDolGlobalString(''TAKEPOS_SUMUP_AFFILIATE'')) ?>&app-id=<?php echo urlencode(getDolGlobalString(''TAKEPOS_SU"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SUPPLEMENTS', 'string', NULL, 'takepos', 'Enables the supplements (add-ons) feature in TakePOS bar/restaurant mode, allowing additional products to be linked to order lines.', 'Checked in takepos/admin/bar.php:181, takepos/index.php:1486, and takepos/invoice.php:860. A commented-out line in the payload (takepos/admin/bar.php:177) reads: `//print $form->selectyesno("TAKEPOS_SUPPLEMENTS", $conf->global->TAKEPOS_SUPPLEMENTS, 1);` indicating this was formerly a yes/no UI toggle.', 'When enabled, cashiers can select supplement products to attach to order lines; when absent or disabled, the supplements UI is not shown.', 'Truthy / non-zero integer = supplements enabled; 0 or absent = disabled', 0, 0, 'takepos/admin/bar.php|takepos/admin/bar.php', 1, '0c1a514ae53352f181a8c58d3046dda2b31f990bd691bd2cf7c8c099a36ca604', 'v2', '2026-04-21T13:50:40+00:00', '["//print $form->selectyesno(\"TAKEPOS_SUPPLEMENTS\", $conf->global->TAKEPOS_SUPPLEMENTS, 1);", "if (getDolGlobalInt(''TAKEPOS_SUPPLEMENTS'')) {", "if (getDolGlobalString(''TAKEPOS_SUPPLEMENTS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_SUPPLEMENTS_CATEGORY', 'string', NULL, 'takepos', 'ID of the product category whose members are offered as supplements in TakePOS.', 'Written via takepos/admin/bar.php:68 and takepos/admin/setup.php:87. Read in takepos/ajax/ajax.php:98 as `$category = getDolGlobalInt(''TAKEPOS_SUPPLEMENTS_CATEGORY'')` and in takepos/invoice.php:864 to filter supplement candidates by category.', 'Changing this value changes which product category is presented as supplements; an incorrect ID results in no supplements being available.', 'Integer: ID of a Dolibarr product category; empty = no supplements category set', 0, 0, 'takepos/admin/bar.php|takepos/admin/bar.php|takepos/admin/setup.php', 1, 'd0e9a91a356b5206be7506126d87445775fe413245b8220b4cc15cb740a2b0d5', 'v2', '2026-04-21T13:50:40+00:00', '["$res = dolibarr_set_const($db, \"TAKEPOS_SUPPLEMENTS_CATEGORY\", $suplement_category, ''chaine'', 0, '''', $conf->entity);", "$category = getDolGlobalInt(''TAKEPOS_SUPPLEMENTS_CATEGORY'');", "$found = (array_search(getDolGlobalInt(''TAKEPOS_SUPPLEMENTS_CATEGORY''), array_column($categories, ''id'')));", "//print $form->selectCategories(Categorie::TYPE_PRODUCT, ''TAKEPOS_SUPPLEMENTS_CATEGORY'', null);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_TEMPLATE_TO_USE_FOR_INVOICES', 'bool', NULL, 'takepos', 'Selects the print template used for invoices on a given TakePOS terminal.', 'Set via takepos/admin/terminal.php (line 136) and displayed via selectarray at line 507. Read in takepos/ajax/ajax.php:460 as templateidtouse before calling sendToPrinter() at line 490.', 'Changing the template changes the layout/format of printed invoices for the terminal; the code notes it may not be ignored by sendToPrinter().', 'Integer template ID from the templates list; empty/0 means no specific template selected.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '869d1e6ba96ff5a08159b6f1b57803f128a24cd0e041bad499e9f8ca70a8d181', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/terminal.php:136|write|$res = dolibarr_set_const($db, \"TAKEPOS_TEMPLATE_TO_USE_FOR_INVOICES\".$terminaltouse, GETPOST(''TAKEPOS_TEMPLATE_TO_USE_FOR_INVOICES''.$terminaltouse, ''alpha''), ''chaine'', 0, '''', $con", "takepos/ajax/ajax.php:460|read|$templateidtouse = getDolGlobalInt(''TAKEPOS_TEMPLATE_TO_USE_FOR_INVOICES''.$term);\t// Note that this may not be ignored by the sendToPrinter()", "takepos/ajax/ajax.php:490|read|$printer->sendToPrinter($object, getDolGlobalInt(''TAKEPOS_TEMPLATE_TO_USE_FOR_INVOICES''.$term), getDolGlobalInt(''TAKEPOS_PRINTER_TO_USE''.$term));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS', 'bool', NULL, 'takepos', 'Selects the print template used for orders on a given TakePOS terminal.', 'Set via takepos/admin/terminal.php (line 139) and displayed via selectarray at line 514. Read in takepos/invoice.php at lines 1277, 1309, and 1341 when calling sendToPrinter() for each of the three order printers.', 'Changing the template changes the layout/format of printed order tickets for the terminal across all order printers.', 'Integer template ID from the templates list; empty/0 means no specific template selected.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, 'e3bc677cb6a6904ab40bf688bb5ed5662b0bcf5cb9b9437c99ae5024fa5a21fc', 'v2', '2026-04-21T13:50:40+00:00', '["takepos/admin/terminal.php:139|write|$res = dolibarr_set_const($db, \"TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS\".$terminaltouse, GETPOST(''TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS''.$terminaltouse, ''alpha''), ''chaine'', 0, '''', $conf->e", "takepos/invoice.php:1277|read|$ret = $printer->sendToPrinter($invoice, getDolGlobalInt(''TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS''.$_SESSION[\"takeposterminal\"]), getDolGlobalInt(''TAKEPOS_ORDER_PRINTER1_TO_USE''.$_SESSI", "takepos/invoice.php:1309|read|$ret = $printer->sendToPrinter($invoice, getDolGlobalInt(''TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS''.$_SESSION[\"takeposterminal\"]), getDolGlobalInt(''TAKEPOS_ORDER_PRINTER2_TO_USE''.$_SESSI", "takepos/invoice.php:1341|read|$ret = $printer->sendToPrinter($invoice, getDolGlobalInt(''TAKEPOS_TEMPLATE_TO_USE_FOR_ORDERS''.$_SESSION[\"takeposterminal\"]), getDolGlobalInt(''TAKEPOS_ORDER_PRINTER3_TO_USE''.$_SESSI"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_TERMINAL_NAME_', 'string', NULL, 'takepos', 'Stores the display name for each TakePOS terminal (suffix is the terminal number, e.g., TAKEPOS_TERMINAL_NAME_1).', 'Each suffixed variant holds the name for its terminal. Written via takepos/admin/terminal.php:86 and read in compta/cashcontrol/cashcontrol_card.php:680, compta/cashcontrol/report.php:162, core/lib/takepos.lib.php:61, and takepos/index.php at lines 1242 and 1321. Falls back to the translated ''TerminalName'' string when not set.', 'Setting a terminal name customises its label throughout the TakePOS UI and cash control reports.', 'String: display name for the terminal. Defaults to translated ''TerminalName {N}'' when empty.', 0, 0, 'takepos/admin/terminal.php|takepos/admin/terminal.php', 1, '2afa7b34e2b96053f992ebe626c82f944993999516c1482f9b80de8f78d7c5b2', 'v2', '2026-04-21T11:16:15+00:00', '["takepos/admin/terminal.php:204|read|print ''<input type=\"text\" name=\"terminalname''.$terminal.''\" value=\"''.getDolGlobalString(\"TAKEPOS_TERMINAL_NAME_\".$terminal, $langs->trans(\"TerminalName\", $terminal)).''\" >'';", "compta/cashcontrol/report.php:162|read|$nameterminal = getDolGlobalString(\"TAKEPOS_TERMINAL_NAME_\".$object->posnumber);", "core/lib/takepos.lib.php:61|read|$head[$h][1] = getDolGlobalString(''TAKEPOS_TERMINAL_NAME_''.$i, $langs->trans(\"TerminalName\", $i));", "takepos/index.php:1242|read|echo getDolGlobalString(\"TAKEPOS_TERMINAL_NAME_\".$_SESSION[\"takeposterminal\"], $langs->trans(\"TerminalName\", $_SESSION[\"takeposterminal\"]));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_TERMINAL_NAME_1', 'string', NULL, 'takepos', 'Custom display label for TakePOS terminal #1 button in the terminal-selection modal, overriding the default ''TerminalName'' translation.', 'Read at takepos/index.php:1334 (and again 1338 for terminal #1 as "TAKEPOS_TERMINAL_NAME_1"): getDolGlobalString("TAKEPOS_TERMINAL_NAME_1", $langs->trans("TerminalName", 1)) supplies the button label, falling back to the translated default if unset. Sibling constants TAKEPOS_TERMINAL_NAME_2..N follow the same pattern for other terminal numbers.', 'Setting it changes the label shown on the terminal #1 selection button in TakePOS; leaving it unset falls back to the localized ''TerminalName 1'' text.', 'Free-form string used as button label; falls back to $langs->trans(''TerminalName'', 1) when unset.', 1, 0, NULL, 1, '0f474ccf2d056af6bdf7f9b0b81e34cdda3af4b26a542dd57733a3b1ca520e64', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1334|read|<button ... onclick=\"location.href=''index.php?setterminal=1''\"><?php print getDolGlobalString(\"TAKEPOS_TERMINAL_NAME_1\", $langs->trans(\"TerminalName\", 1)); ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_TERMINAL_NB_FOR_PUBLIC', 'string', NULL, 'takepos', 'Sets which TakePOS terminal number is used for orders submitted from the public (customer-facing) auto-order page.', 'In takepos/public/auto_order.php:42: `$_SESSION["takeposterminal"] = getDolGlobalInt(''TAKEPOS_TERMINAL_NB_FOR_PUBLIC'', 1);` with an inline comment ''Default terminal for public submission is 1'', storing the terminal id in the session for the public order flow.', 'Setting it changes which POS terminal number public/self-service orders are attributed to; default is 1 if unset.', 'Integer: TakePOS terminal number for public submissions; default is 1 per the code''s own default argument and inline comment.', 1, 0, NULL, 1, 'ef6be949c1f43009fe72658e97a17d4243a51431bd07f589ed4fa50e4d1c474b', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/public/auto_order.php:42|read|$_SESSION[\"takeposterminal\"] = getDolGlobalInt(''TAKEPOS_TERMINAL_NB_FOR_PUBLIC'', 1);\t// Default terminal for public submission is 1"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_TICKET_VAT_GROUPPED', 'string', NULL, 'takepos', 'Enables grouping of VAT amounts by rate on TakePOS receipts.', 'Written in takepos/admin/receipt.php:122 and in takepos/receipt.php:141. Checked in takepos/receipt.php:387 to conditionally render grouped VAT summary lines at the bottom of the receipt.', 'When enabled, the receipt displays a VAT summary grouped by tax rate; when absent, VAT is not grouped on the ticket.', '1 = group VAT by rate on receipt; 0 or absent = no VAT grouping', 0, 0, 'takepos/admin/receipt.php', 1, 'e1cd339dbee240009edfcb6a598db2d687ebe85bad052817633c651f32d1e46b', 'v2', '2026-04-21T13:50:40+00:00', '["$conf->global->TAKEPOS_TICKET_VAT_GROUPPED = 1;", "if (getDolGlobalString(''TAKEPOS_TICKET_VAT_GROUPPED'')) {", "takepos/receipt.php:387|check"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_USE_ARROW_ON_NAVBAR', 'bool', NULL, 'takepos', 'Switches the TakePOS category/product navbar between arrow-based navigation and free scrolling.', 'Used in takepos/css/pos.css.php:372 and :998 to toggle CSS: when set, the .container gets overflow-x hidden (relies on arrow buttons) and the .arrows block is displayed; when unset, overflow is visible and .arrows is hidden (display:none).', 'Setting it true enables the left/right arrow buttons for navigating categories/products and disables free-scroll overflow; leaving it unset hides the arrows and allows normal scroll overflow.', 'Boolean: true/1 shows arrow navigation with hidden overflow, false/unset shows scrollable overflow with arrows hidden.', 1, 0, NULL, 1, '6339bf82129b303a4b1325a69726f4bfbcc003a1f9553122c3693c5e5b332c56', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/css/pos.css.php:372|check|if (getDolGlobalString(''TAKEPOS_USE_ARROW_ON_NAVBAR'')) {", "takepos/css/pos.css.php:998|check|if (!getDolGlobalString(''TAKEPOS_USE_ARROW_ON_NAVBAR'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_USE_DEFAULT_VATRATE_FOR_FREEZONE', 'bool', NULL, 'takepos', 'Controls whether the TakePOS free-zone (custom amount) entry shows VAT rate selection buttons.', 'Checked in takepos/freezone.php:150 with getDolGlobalString; when NOT set, the free-zone form displays a row of VAT rate buttons for the user to pick a rate for the manually-entered amount.', 'If set (true), TakePOS skips the VAT-rate picker on the freezone screen and presumably uses a default VAT rate instead of asking the user.', 'Boolean: unset/false shows VAT rate buttons on the freezone entry screen; true hides them (uses default VAT rate).', 1, 0, NULL, 1, 'a3eb33620249174a2ba18dec4c6e066de3819d6c628a17206eef03f906722018', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/freezone.php:150|check|if ($action == ''freezone'' && !getDolGlobalString(\"TAKEPOS_USE_DEFAULT_VATRATE_FOR_FREEZONE\") && $user->hasRight(''takepos'', ''run'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAKEPOS_WEIGHING_SCALE', 'string', NULL, 'takepos', 'Enables weighing-scale integration in TakePOS: prompts to weigh a product before adding it to the cart, and shows a ''WeighingScale'' action button.', 'Checked at takepos/index.php:600 (JS: calls WeighingScale(addInvoiceLine) instead of addInvoiceLine directly when the product''s unit is 2/weight) and :1601 (adds a ''WeighingScale'' menu button).', 'Enabling it changes product-add flow for weight-unit products to require a scale reading via WeighingScale() and surfaces an extra action button in the TakePOS menu.', 'Boolean: true/1 enables weighing-scale flow and menu button, false/unset disables it.', 1, 0, NULL, 1, '0fdd72e34ba82ec7c0e722a0e85f0acda919778588d39b99f6843e4bc718577a', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:600|check|if (getDolGlobalString(''TAKEPOS_WEIGHING_SCALE'')) { if ($(''#prodiv''+position).data(''unit'') == 2) { WeighingScale(addInvoiceLine); }", "takepos/index.php:1601|check|if (getDolGlobalString(''TAKEPOS_WEIGHING_SCALE'')) { $menus[$r++] = array(''title'' => ... ''WeighingScale''... );"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TARGET_ADDON_PDF', 'string', NULL, 'webhook', 'Name of the default PDF document model (template) used to generate documents for webhook ''target'' objects.', 'Checked in webhook/class/target.class.php:1035-1036 inside generateDocument(): if no explicit model is passed and $this->model_pdf is empty, this constant''s value (if set) is used as the $modele for document generation, otherwise falling back to ''standard_target''.', 'Setting it changes which PDF template is used by default to generate documents for Target objects that don''t already have a model_pdf set.', 'String: name of a document/PDF model for webhook Target objects; falls back to ''standard_target'' if unset.', 1, 0, NULL, 1, 'fa3fe2e10e088de589bbc75e68993ef0d1172a54f543b92b73b95ddd8934b988', 'v2', '2026-07-24T07:05:23+00:00', '["webhook/class/target.class.php:1035: } elseif (getDolGlobalString(''TARGET_ADDON_PDF'')) {", "webhook/class/target.class.php:1036: $modele = getDolGlobalString(''TARGET_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAX_ADD_CLONE_FOR_NEXT_MONTH_CHECKBOX', 'string', NULL, 'compta', 'Changes the clone dialog for a social/tax charge (compta/sociales) to offer a simple ''clone for next month'' checkbox instead of manual date/amount fields.', 'Checked in compta/sociales/card.php:478 in the clone confirmation form: when set, only a ''clone_for_next_month'' checkbox is shown; otherwise date, period, and amount fields are shown for manual entry.', 'Enabling it simplifies cloning of recurring social/tax charges by letting the user just tick a box to roll the charge to next month, instead of entering the new due date/period/amount manually.', 'Boolean: truthy shows the ''CloneTaxForNextMonth'' checkbox instead of manual date/amount fields.', 0, 0, NULL, 1, '7c36c7ac29efd6e95cc36cf9f81c8c4fefb6f45368648a99156c568bd90aa4d6', 'v2', '2026-07-24T07:05:23+00:00', '["compta/sociales/card.php:478|if (getDolGlobalString(''TAX_ADD_CLONE_FOR_NEXT_MONTH_CHECKBOX'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAX_DISABLE_VAT_MENUS', 'bool', NULL, 'core', 'Hides the VAT (''tax_vat'') menu section under Taxes and social contributions.', 'Checked in core/menus/standard/eldy.lib.php:1676, guarding the whole block that adds VAT menu entries (list/new/list under tax_vat), separate from the social-contributions menu entries above it.', 'Enabling it removes the VAT menu entries from the left menu, hiding VAT navigation while social contribution menus remain unaffected.', 'Truthy hides the VAT menu section; empty/0 shows it (default).', 1, 0, NULL, 1, 'eb51b0c2d721026e81774f44204adcfedda7254e1a20a12e8284ee39df2e3028', 'v2', '2026-07-24T07:05:23+00:00', '["core/menus/standard/eldy.lib.php:1676: if (!getDolGlobalString(''TAX_DISABLE_VAT_MENUS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAX_MODE', 'string', NULL, 'compta', 'Selects the general VAT liability timing mode for the company.', 'Configured via admin/taxes.php (read at line 78, written at line 88). Comments at lines 63, 68, and 73 of admin/taxes.php define: ''TAX_MODE=0 (most cases in FR)'', ''TAX_MODE=1 (option, VAT is due at invoice date)'', ''TAX_MODE=2 (option, VAT is due on payment date)''. Read by compta/tva/quadri_detail.php:95, index.php:73, clients.php:88, stats/byratecountry.php:130, and PDF modules.', 'Changing this value alters when VAT liability is recognised: at tax event (0), at invoice date (1), or at payment date (2), affecting VAT declaration reports and PDF generation.', '0 = VAT due at tax event (most cases in FR, default); 1 = VAT due at invoice date; 2 = VAT due at payment date', 0, 0, 'admin/taxes.php|admin/taxes.php', 1, 'c15e7f491ec955534e43637f98449b81c190011eaca1af1a8edad256ce6c27e5', 'v2', '2026-04-21T11:16:15+00:00', '["admin/taxes.php:63  // TAX_MODE=0 (most cases in FR):", "admin/taxes.php:68  // TAX_MODE=1 (option, VAT is due at invoice date):", "admin/taxes.php:73  // TAX_MODE=2 (option, VAT is due on payment date):", "compta/tva/quadri_detail.php:95|read|$modetax = getDolGlobalInt(''TAX_MODE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAX_MODE_BUY_PRODUCT', 'string', NULL, 'compta', 'Specifies the VAT recovery timing for purchased products: ''invoice'' (recoverable at invoice date) or ''payment'' (recoverable at payment date).', 'Configured via admin/taxes.php:124. Checked in compta/tva/quadri_detail.php:794 and :192, compta/tva/clients.php:668, and core/lib/tax.lib.php:164 and :717.', 'Setting this to ''payment'' delays VAT recovery on purchased products to payment date; ''invoice'' allows recovery at invoice receipt.', '''invoice'' = VAT recoverable at invoice date for purchased products; ''payment'' = VAT recoverable at payment date', 0, 0, 'admin/taxes.php|admin/taxes.php', 1, '725c799c5e3b9caadeb2e918c0b93269a5cd17b4ee32cb99b94ecf01d78cb077', 'v2', '2026-04-21T11:16:15+00:00', '["admin/taxes.php:124|write|$res = dolibarr_set_const($db, ''TAX_MODE_BUY_PRODUCT'', $valuebuyproduct, ''chaine'', 0, '''', $conf->entity);", "core/lib/tax.lib.php:164|read||| ($direction == ''buy'' && getDolGlobalString(''TAX_MODE_BUY_PRODUCT'') == ''invoice'')) {", "compta/tva/quadri_detail.php:794|check|if (getDolGlobalString(''TAX_MODE_BUY_PRODUCT'') == ''payment'' || getDolGlobalString(''TAX_MODE_BUY_SERVICE'') == ''payment'') {", "compta/tva/quadri_detail.php:192|check|if (getDolGlobalString(''TAX_MODE_BUY_SERVICE'') == ''invoice'' && getDolGlobalString(''TAX_MODE_BUY_PRODUCT'') == ''invoice'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAX_MODE_BUY_SERVICE', 'string', NULL, 'compta', 'Specifies the VAT recovery timing for purchased services: ''invoice'' (recoverable at invoice date) or ''payment'' (recoverable at payment date).', 'Configured via admin/taxes.php:132. Checked in compta/tva/quadri_detail.php:794 and :192, compta/tva/clients.php:668, and core/lib/tax.lib.php:359 and :898.', 'Setting this to ''payment'' delays VAT recovery on purchased services to payment date; ''invoice'' allows recovery at invoice receipt.', '''invoice'' = VAT recoverable at invoice date for purchased services; ''payment'' = VAT recoverable at payment date', 0, 0, 'admin/taxes.php|admin/taxes.php', 1, '91a8dfa6a675ab9563f11b951ce76ebb5a79ca05efcf2ff55b3358f839baee24', 'v2', '2026-04-21T11:16:15+00:00', '["admin/taxes.php:132|write|$res = dolibarr_set_const($db, ''TAX_MODE_BUY_SERVICE'', $valuebuyservice, ''chaine'', 0, '''', $conf->entity);", "core/lib/tax.lib.php:359|read||| ($direction == ''buy'' && getDolGlobalString(''TAX_MODE_BUY_SERVICE'') == ''invoice'')) {", "compta/tva/quadri_detail.php:794|check|if (getDolGlobalString(''TAX_MODE_BUY_PRODUCT'') == ''payment'' || getDolGlobalString(''TAX_MODE_BUY_SERVICE'') == ''payment'') {", "compta/tva/quadri_detail.php:192|check|if (getDolGlobalString(''TAX_MODE_BUY_SERVICE'') == ''invoice'' && getDolGlobalString(''TAX_MODE_BUY_PRODUCT'') == ''invoice'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAX_MODE_SELL_PRODUCT', 'string', NULL, 'compta', 'Specifies the VAT liability timing for sold products: ''invoice'' (due at invoice date) or ''payment'' (due at payment date).', 'Configured via admin/taxes.php:120. Checked in compta/tva/quadri_detail.php:558, compta/tva/index.php:446 and :485, compta/tva/clients.php:477, and compta/localtax pages. A commented line at compta/localtax/quadri_detail.php:160 shows ''RulesVATDueProducts'' and ''RulesVATInProducts'' labels keyed to ''invoice'' and ''payment'' respectively.', 'Setting this to ''payment'' delays VAT recognition on product sales to payment receipt; ''invoice'' recognises VAT at invoice creation.', '''invoice'' = VAT due at invoice date for sold products; ''payment'' = VAT due at payment receipt for sold products', 0, 0, 'admin/taxes.php|admin/taxes.php', 1, 'd0f86d19051e4551cab9d89c25f2de79e6d162f5543060cdc83fae03f92fe7d7', 'v2', '2026-04-21T11:16:15+00:00', '["admin/taxes.php:120|write|$res = dolibarr_set_const($db, ''TAX_MODE_SELL_PRODUCT'', $valuesellproduct, ''chaine'', 0, '''', $conf->entity);", "compta/tva/index.php:446|check|if (($type == 0 && getDolGlobalString(''TAX_MODE_SELL_PRODUCT'') == ''invoice'')", "compta/tva/clients.php:477|check|if (getDolGlobalString(''TAX_MODE_SELL_PRODUCT'') == ''payment'' || getDolGlobalString(''TAX_MODE_SELL_SERVICE'') == ''payment'') {", "compta/localtax/quadri_detail.php:160  /*if (getDolGlobalString(''TAX_MODE_SELL_PRODUCT'') == ''invoice'') $description.=$langs->trans(\"RulesVATDueProducts\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAX_MODE_SELL_SERVICE', 'string', NULL, 'compta', 'Specifies the VAT liability timing for sold services: ''invoice'' (due at invoice date) or ''payment'' (due at payment date).', 'Configured via admin/taxes.php:128. Checked in compta/tva/quadri_detail.php:558, compta/tva/clients.php:477, compta/localtax/quadri_detail.php:162, core/lib/tax.lib.php:358 and :897, and compta/tva/index.php:447.', 'Setting this to ''payment'' delays VAT recognition on service sales to payment receipt; ''invoice'' recognises VAT at invoice creation.', '''invoice'' = VAT due at invoice date for sold services; ''payment'' = VAT due at payment receipt for sold services', 0, 0, 'admin/taxes.php|admin/taxes.php', 1, 'b761d1c1c6136581eebdda73bf86775ad97c3392959589efde7121dd9d63271a', 'v2', '2026-04-21T11:16:15+00:00', '["admin/taxes.php:128|write|$res = dolibarr_set_const($db, ''TAX_MODE_SELL_SERVICE'', $valuesellservice, ''chaine'', 0, '''', $conf->entity);", "compta/tva/index.php:447|read||| ($type == 1 && getDolGlobalString(''TAX_MODE_SELL_SERVICE'') == ''invoice'')) {", "core/lib/tax.lib.php:358|check|if (($direction == ''sell'' && getDolGlobalString(''TAX_MODE_SELL_SERVICE'') == ''invoice'')", "compta/localtax/quadri_detail.php:162|check|if (getDolGlobalString(''TAX_MODE_SELL_SERVICE'') == ''invoice'') $description.=''<br>''.$langs->trans(\"RulesVATDueServices\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TAX_REPORT_EXTRA_REPORT', 'string', NULL, 'compta', 'Enables an extra radio-button option (''AddExtraReport'') on the VAT/tax report page for clients.', 'Checked in compta/tva/clients.php:181; when set it adds two radio inputs (SimpleReport / AddExtraReport) named ''extra_report'' to the report description block.', 'When set, users see and can toggle a ''SimpleReport'' vs ''AddExtraReport'' radio choice on the VAT clients report; the resulting ''extra_report'' parameter is used elsewhere to select report detail mode.', 'Bool: truthy shows the SimpleReport/AddExtraReport radio toggle on the tax report page.', 1, 0, NULL, 1, '2bee4b0b02f2c130eb7f219072a6a0a8e3c8e28709ae3436279618af20b3f236', 'v2', '2026-07-24T07:05:23+00:00', '["compta/tva/clients.php:181|check|if (getDolGlobalString(''TAX_REPORT_EXTRA_REPORT'')) {", "compta/tva/clients.php:182-190|read|radio name=\"extra_report\" value=\"0\"...SimpleReport...radio ... value=\"1\"...AddExtraReport"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TCPDF_THROW_ERRORS_INSTEAD_OF_DIE', 'string', NULL, 'barcode', 'Controls whether TCPDF errors throw a PHP exception or call die() when generating PDF documents.', 'A comment at core/lib/pdf.lib.php:169 states: ''TCPDF_THROW_ERRORS_INSTEAD_OF_DIE = 0 to restore the legacy die() behavior.'' The check at core/lib/pdf.lib.php:170 defaults to ''1''. barcode/printsheet.php temporarily overrides it to 1 at line 359 and restores the previous value at line 370.', 'When set to 1 (default), TCPDF errors raise exceptions that can be caught; setting to 0 reverts to the legacy die() call on PDF errors.', '1 = throw exception on TCPDF error (default); 0 = call die() on TCPDF error (legacy behavior).', 1, 0, NULL, 1, 'b2b414dfc136089a9151cdeb0481d1a7e83e2cf2a904da19ab792636238b27c8', 'v2', '2026-04-21T11:16:15+00:00', '["// TCPDF_THROW_ERRORS_INSTEAD_OF_DIE = 0 to restore the legacy die() behavior.", "core/lib/pdf.lib.php:170|check|if (getDolGlobalString(''TCPDF_THROW_ERRORS_INSTEAD_OF_DIE'', ''1'')) {", "barcode/printsheet.php:359|write|$conf->global->TCPDF_THROW_ERRORS_INSTEAD_OF_DIE = 1;", "barcode/printsheet.php:370|write|$conf->global->TCPDF_THROW_ERRORS_INSTEAD_OF_DIE = $previousConf;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ADD_BACKGROUND_ON_INPUT', 'string', NULL, 'theme', 'When enabled, applies a background color to input fields in the Eldy and MD themes.', 'Checked in theme/eldy/global.inc.php:379 and :404 to toggle between background and no-background CSS rules, and in theme/md/style.css.php:633 for the MD theme. Three occurrences across two files. No admin UI write is present.', 'Enabling this constant adds a background color to input fields; disabling it removes that background.', 'Boolean flag; unset or 0 = no background on inputs; any truthy value = background applied.', 1, 0, NULL, 1, 'd3c379dfd9ada118d97c74079ef810eaabf3774b19c6b35eb41f53a5193f4f71', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/global.inc.php:379|check|<?php if (!getDolGlobalString(''THEME_ADD_BACKGROUND_ON_INPUT'')) { ?>", "theme/eldy/global.inc.php:404|check|<?php if (getDolGlobalString(''THEME_ADD_BACKGROUND_ON_INPUT'')) { ?>", "theme/md/style.css.php:633|check|<?php if (!getDolGlobalString(''THEME_ADD_BACKGROUND_ON_INPUT'')) { ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_CUSTOM_CSS', 'string', NULL, 'theme', 'Stores custom CSS content injected at the end of the Eldy and MD theme stylesheets.', 'Read and printed in theme/eldy/global.inc.php:9590 unconditionally, and checked then printed in theme/md/style.css.php:9266-9267. Three occurrences across two files. No admin UI write is present in the payload.', 'Setting this constant injects arbitrary CSS at the end of the theme stylesheet, overriding any earlier theme rules.', 'Any valid CSS string; unset or empty = no custom CSS injected.', 1, 0, NULL, 1, '7e0b99f7e0147a56278999db7bbb7f5f75b01dc8218f5eb00283a1d569843ec7', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/global.inc.php:9590|read|print getDolGlobalString(''THEME_CUSTOM_CSS'');", "theme/md/style.css.php:9266|check|if (getDolGlobalString(''THEME_CUSTOM_CSS'')) {", "theme/md/style.css.php:9267|read|print getDolGlobalString(''THEME_CUSTOM_CSS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_DARKMODEENABLED', 'bool', NULL, 'theme', 'Controls whether dark mode is enabled for the Eldy theme, including a forced state via URL parameter.', 'Configured via admin/ihm.php (write at line 131, delete at line 128). Checked with getDolGlobalInt across theme/eldy/info-box.inc.php:48, theme/eldy/global.inc.php:5782 and :226, and theme/eldy/btn.inc.php:63 and :65, with value 2 treated distinctly from other truthy values. theme/eldy/style.css.php:174 also allows forcing the value from a URL GET parameter.', 'Changing this value toggles dark mode styling across the Eldy theme; the value 2 is treated differently from a plain enabled (1) state in multiple checks.', NULL, 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '5c7632ee10261ffed1329a9cd8360f7b7549446bcb59a2c2d2c66024eacb7774', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalInt(''THEME_DARKMODEENABLED'') != 2) { ?>", "$conf->global->THEME_DARKMODEENABLED = GETPOSTINT(''THEME_DARKMODEENABLED''); // If darkmode was forced on URL"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_BACKBODY', 'string', NULL, 'theme', 'Stores the custom background colour (RGB triplet) for the main content area in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:255 and theme/md/style.css.php to set $colorbackbody; used only when THEME_ELDY_ENABLE_PERSONALIZED is active. A colour picker is displayed in the group/user settings at core/lib/usergroups.lib.php:826. Configurable via admin/ihm.php. The comment at core/lib/usergroups.lib.php:800 labels it ''Background color for main area THEME_ELDY_BACKBODY''.', 'Changing this value alters the background colour of the main page area for all users (unless overridden per-user).', 'String: RGB triplet as ''R,G,B'' (e.g. ''255,255,255'' for white). Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '33ab4ceac09368792c46fc8e672129a9f40853de13d1ff5008d885cfe05a551b', 'v2', '2026-04-21T11:16:15+00:00', '["core/lib/usergroups.lib.php:800  // Background color for main area THEME_ELDY_BACKBODY", "theme/eldy/style.css.php:255|check|$colorbackbody = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_BACKBODY'') ? $colorbackbody : $conf->global->THEME_ELDY_BACKBODY)", "admin/ihm.php:153|write|dolibarr_set_const($db, ''THEME_ELDY_BACKBODY'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:826|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_BACKBODY''), array()), ''''), ''THEME_ELDY_BACKBODY'', ...);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_BACKTABACTIVE', 'string', NULL, 'theme', 'Stores the background colour (RGB triplet) for the active/selected tab in the Eldy and MD themes.', 'Set to ''234,234,234'' as a default in theme/eldy/style.css.php:248 and theme/md/style.css.php:254 when personalisation is disabled. Read in style.css.php:261 and md/style.css.php:266 into $colorbacktabactive. No admin UI write is present.', 'Changing this value alters the background colour of the currently selected tab across the UI.', 'String: RGB triplet as ''R,G,B'' (default ''234,234,234''). Empty or unset falls back to theme default.', 1, 0, NULL, 1, '585e7b323908b6a256629d54ca20951a66cc1f7d56e232ec240e52a6b20f0c2d', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:248|write|$conf->global->THEME_ELDY_BACKTABACTIVE = ''234,234,234'';", "theme/md/style.css.php:254|write|$conf->global->THEME_ELDY_BACKTABACTIVE = ''234,234,234'';", "theme/eldy/style.css.php:261|check|$colorbacktabactive = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_BACKTABACTIVE'') ? $colorbacktabactive : $conf->global->THEME_ELDY_BACK", "theme/md/style.css.php:266|check|$colorbacktabactive = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_BACKTABACTIVE'', $colorbacktabactive) : getDolUserString(''THEME_ELDY_BACKT"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_BACKTABCARD1', 'string', NULL, 'theme', 'Stores the background colour (RGB triplet) for card/record tab panels in the Eldy and MD themes.', 'Set to ''255,255,255'' as a default in theme/eldy/style.css.php:247 and theme/md/style.css.php:253 when THEME_ELDY_ENABLE_PERSONALIZED is disabled. Read in style.css.php:260 and md/style.css.php:265 into $colorbacktabcard1. No admin UI write is present.', 'Changing this value alters the background colour of card view tab content areas.', 'String: RGB triplet as ''R,G,B'' (default ''255,255,255''). Empty or unset falls back to theme default.', 1, 0, NULL, 1, '04dcac4c9e11547a8cbcd51a4684fda3a5bb598c20028a7deac268a24f604e08', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:247|write|$conf->global->THEME_ELDY_BACKTABCARD1 = ''255,255,255''; // card", "theme/md/style.css.php:253|write|$conf->global->THEME_ELDY_BACKTABCARD1 = ''255,255,255''; // card", "theme/eldy/style.css.php:260|check|$colorbacktabcard1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_BACKTABCARD1'') ? $colorbacktabcard1 : $conf->global->THEME_ELDY_BACKTA", "theme/md/style.css.php:265|check|$colorbacktabcard1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_BACKTABCARD1'', $colorbacktabcard1) : getDolUserString(''THEME_ELDY_BACKTAB"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_BACKTITLE1', 'string', NULL, 'theme', 'Stores the background color for title bars used by the Eldy and MD themes.', 'Configured via admin/ihm.php (write at line 181, delete at line 179). Read in theme/eldy/style.css.php:261 and theme/md/style.css.php:262 to compute colorbacktitle1, with a per-user override possible via getDolUserString when THEME_ELDY_ENABLE_PERSONALIZED is not set for the user.', 'Changing this value changes the background color of title elements in the Eldy/MD theme CSS, unless the user has enabled personalized colors.', NULL, 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'eafac88f07d99b1db433c0ccf17a2649137de1ae52d333c49797ed9b3d3be91c', 'v2', '2026-07-24T06:41:12+00:00', '["$colorbacktitle1      = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_BACKTITLE1'') ? $colorbacktitle1 : $conf->global->THEME_ELDY_BACKTITLE1", "<?php if (!colorIsLight(getDolGlobalString(''THEME_ELDY_BACKTITLE1''))) { ?>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_BORDER_RADIUS', 'string', NULL, 'theme', 'Sets the border radius (in pixels) applied to UI elements in the Eldy and MD themes when borders are enabled.', 'Written via admin/ihm.php:146. Read in theme/eldy/global.inc.php:159, theme/md/style.css.php:4701, theme/md/info-box.inc.php:20, and theme/eldy/dropdown.inc.php:28 with a default of 6. Ten occurrences across multiple files; configurable via admin/ihm.php.', 'Changing this value alters the corner rounding of UI elements across both themes. The value is only applied when THEME_ELDY_USEBORDERONTABLE is enabled.', 'Integer pixel value; default is 6 when unset.', 0, 0, 'admin/ihm.php', 1, '665db7140561a2ceb8b1e9b4ab5daafab095b95c7ac50282d29fdd975610a3fc', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:146|write|dolibarr_set_const($db, ''THEME_ELDY_BORDER_RADIUS'', GETPOSTINT(''THEME_ELDY_BORDER_RADIUS''), ''chaine'', 0, '''', $conf->entity);", "theme/eldy/global.inc.php:159|read|$borderradius = getDolGlobalString(''THEME_ELDY_USEBORDERONTABLE'') ? getDolGlobalInt(''THEME_ELDY_BORDER_RADIUS'', 6) : 0;", "theme/md/style.css.php:4701|read|<?php $borderradius = getDolGlobalString(''THEME_ELDY_USEBORDERONTABLE'') ? getDolGlobalInt(''THEME_ELDY_BORDER_RADIUS'', 6) : 0; ?>", "core/lib/usergroups.lib.php:634|read|print $form->selectarray(''THEME_ELDY_BORDER_RADIUS'', $listofborderradius, getDolGlobalInt(''THEME_ELDY_BORDER_RADIUS''), 0, 0, 0, '''', 0, 0, 0, '''', ''miwdith150 widthcentpercentminusx"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_BTNACTION', 'string', NULL, 'theme', 'Stores the custom background colour (RGB triplet) for action buttons in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:274 and theme/md/style.css.php:279 into $butactionbg. A colour picker is available at core/lib/usergroups.lib.php:1125. Configurable via admin/ihm.php.', 'Changing this value alters the background colour of all primary action buttons throughout the application.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default action button colour.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '98a8791efd85a2dcc5c1b382b573ff8502c716f56211cb443dfdea2cc61b7f2b', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:274|check|$butactionbg = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_BTNACTION'') ? $butactionbg : getDolGlobalString(''THEME_ELDY_BTNACTION''", "admin/ihm.php:249|write|dolibarr_set_const($db, ''THEME_ELDY_BTNACTION'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:1125|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_BTNACTION''), array()), ''''), ''THEME_ELDY_BTNACTION'','''',1).'' '';", "core/lib/usergroups.lib.php:1118|read|print ''<td>''.(getDolGlobalString(''THEME_ELDY_TOPMENU_BACK1'') ? getDolGlobalString(''THEME_ELDY_BTNACTION'') : $langs->trans(\"Default\")).''</td>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_ENABLE_PERSONALIZED', 'bool', NULL, 'theme', 'Gates whether per-user or global colour customisation is applied in the Eldy and MD themes.', 'When disabled (0), style.css.php resets colour variables to defaults (see commented-out lines at theme/eldy/style.css.php:203-204). When enabled, personalised colours from global or user config are applied. The comment at line 245 states this is a prerequisite for other editable colour options.', 'Disabling this constant forces all users to the default theme colours, ignoring any per-user or per-entity colour customisation.', 'Boolean flag: truthy = personalised colours applied; 0 = defaults enforced. Per comments: //$conf->global->THEME_ELDY_ENABLE_PERSONALIZED=0; disables global personalisation; //$user->conf->THEME_ELDY_ENABLE_PERSONALIZED=0; disables per-user personalisation.', 1, 0, NULL, 1, 'a3833d1e20512c784db4de324a1042f2055b3b309112e251ce7303e24fdf55c6', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:203  //$conf->global->THEME_ELDY_ENABLE_PERSONALIZED=0;", "theme/eldy/style.css.php:204  //$user->conf->THEME_ELDY_ENABLE_PERSONALIZED=0;", "theme/eldy/style.css.php:245  // Case of option editable only if option THEME_ELDY_ENABLE_PERSONALIZED is on", "theme/eldy/style.css.php:246|check|if (!getDolGlobalString(''THEME_ELDY_ENABLE_PERSONALIZED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_FONT_SIZE1', 'string', NULL, 'theme', 'Sets the primary font size used in the Eldy and MD themes.', 'Controls the main font size applied in theme/eldy/style.css.php:250 and theme/md/style.css.php:256. When user personalization is disabled, the global constant value overrides the theme default; otherwise the per-user value is used. No admin UI is provided.', 'Changing this value resizes the primary text across all pages rendered by the Eldy and MD themes for users without personal theme customization.', 'A CSS font size string (e.g., ''13px'', ''0.85em''); empty/unset means the compiled theme default is used.', 1, 0, NULL, 1, '6a337c4544c0f2278b6f031f9217402900e1ddd8ea15e40964a60aeb3f046b3b', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:276|check|$fontsize = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_FONT_SIZE1'') ? $fontsize : getDolGlobalString(''THEME_ELDY_FONT_SIZE1'')", "theme/md/style.css.php:281|check|$fontsize = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_FONT_SIZE1'', $fontsize) : getDolUserString(''THEME_ELDY_FONT_SIZE1'', $font", "theme/eldy/style.css.php:250|write|$conf->global->THEME_ELDY_FONT_SIZE1 = $fontsize;", "theme/md/style.css.php:256|write|$conf->global->THEME_ELDY_FONT_SIZE1 = $fontsize;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_FONT_SIZE2', 'string', NULL, 'theme', 'Sets the secondary (smaller) font size used in the Eldy and MD themes.', 'Controls the smaller font size applied in theme/eldy/style.css.php:251 (hardcoded to ''0.75em'') and theme/md/style.css.php:257 (hardcoded to ''0.7em''). When user personalization is disabled, the global constant is used; otherwise the per-user value is applied. No admin UI is provided.', 'Changing this value resizes secondary/smaller text across all pages rendered by the Eldy and MD themes for users without personal customization.', 'A CSS font size string (e.g., ''0.75em'', ''0.7em''); default written by theme code is ''0.75em'' (Eldy) or ''0.7em'' (MD).', 1, 0, NULL, 1, '327a2a74a85d418a2e90856d9708b76550c18e7228e2b70975f5a9efc965c1b8', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:251|write|$conf->global->THEME_ELDY_FONT_SIZE2 = ''0.75em'';", "theme/md/style.css.php:257|write|$conf->global->THEME_ELDY_FONT_SIZE2 = ''0.7em'';", "theme/eldy/style.css.php:277|check|$fontsizesmaller = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_FONT_SIZE2'') ? $fontsize : getDolGlobalString(''THEME_ELDY_FONT_SIZE2'')", "theme/md/style.css.php:282|check|$fontsizesmaller = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_FONT_SIZE2'', $fontsize) : getDolUserString(''THEME_ELDY_FONT_SIZE2'', $font"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_LINEBREAK', 'string', NULL, 'theme', 'Stores the background colour (RGB triplet) for separator/break rows in lists in the Eldy and MD themes.', 'Set to a default value via $conf->global at theme/eldy/style.css.php:231 and theme/md/style.css.php:235 when not already defined. Read in style.css.php:266 and md/style.css.php:271 into $colorbacklinebreak. No admin UI write is present.', 'Changing this value alters the colour of visual separator rows used to group list entries.', 'String: RGB triplet as ''R,G,B''. Empty or unset triggers the theme to set a default via $conf->global.', 1, 0, NULL, 1, '51f2459cd46a650bf6afa9f617cf91d05e9d804f371796b2498a29146f19d86a', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:230|read|if (!isset($conf->global->THEME_ELDY_LINEBREAK)) {", "theme/eldy/style.css.php:231|write|$conf->global->THEME_ELDY_LINEBREAK = $colorbacklinebreak;", "theme/eldy/style.css.php:266|check|$colorbacklinebreak = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_LINEBREAK'') ? $colorbacklinebreak : $conf->global->THEME_ELDY_LINEBREA", "theme/md/style.css.php:271|check|$colorbacklinebreak = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_LINEBREAK'', $colorbacklinebreak) : getDolUserString(''THEME_ELDY_LINEBREAK"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_LINEIMPAIR1', 'string', NULL, 'theme', 'Stores the primary background colour (RGB triplet) for odd-numbered list rows in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:262 and theme/md/style.css.php:267 into $colorbacklineimpair1. A colour picker is rendered at core/lib/usergroups.lib.php:931. Configurable via admin/ihm.php.', 'Changing this value alters the background colour of odd rows in all data tables and lists.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'facd8d4fd58ba67289c1daa08ca3a5c1a6e3075f4eaca97a24760dc524029b3f', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:262|check|$colorbacklineimpair1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_LINEIMPAIR1'') ? $colorbacklineimpair1 : $conf->global->THEME_ELDY_LINE", "admin/ihm.php:202|write|dolibarr_set_const($db, ''THEME_ELDY_LINEIMPAIR1'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:931|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_LINEIMPAIR1''), array()), ''''), ''THEME_ELDY_LINEIMPAIR1'', ...);", "core/lib/usergroups.lib.php:933|read|$color = colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_LINEIMPAIR1''), array()), '''');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_LINEIMPAIR2', 'string', NULL, 'theme', 'Stores the secondary background colour (RGB triplet) for odd-numbered list rows in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:263 and theme/md/style.css.php:268 into $colorbacklineimpair2. Configurable via admin/ihm.php.', 'Changing this value alters the secondary colour applied to odd rows in data tables, typically used for a gradient or border effect.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '9d3ad7c37c911fa8096f70ea3883cb59824d12a5575fd911dff3abd496e572b1', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:263|check|$colorbacklineimpair2 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_LINEIMPAIR2'') ? $colorbacklineimpair2 : $conf->global->THEME_ELDY_LINE", "admin/ihm.php:208|write|dolibarr_set_const($db, ''THEME_ELDY_LINEIMPAIR2'', $val, ''chaine'', 0, '''', $conf->entity);", "theme/md/style.css.php:268|check|$colorbacklineimpair2 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_LINEIMPAIR2'', $colorbacklineimpair2) : getDolUserString(''THEME_ELDY_LINE"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_LINEPAIR1', 'string', NULL, 'theme', 'Stores the primary background colour (RGB triplet) for even-numbered list rows in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:264 and theme/md/style.css.php:269 into $colorbacklinepair1. A colour picker is rendered at core/lib/usergroups.lib.php:955. Configurable via admin/ihm.php.', 'Changing this value alters the background colour of even rows in all data tables and lists.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'd813e2a3f985c6ccf07e76923e442a561c31d22bb8bbcb20736a2437cbfbe31b', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:264|check|$colorbacklinepair1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_LINEPAIR1'') ? $colorbacklinepair1 : $conf->global->THEME_ELDY_LINEPAIR", "admin/ihm.php:215|write|dolibarr_set_const($db, ''THEME_ELDY_LINEPAIR1'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:955|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_LINEPAIR1''), array()), ''''), ''THEME_ELDY_LINEPAIR1'', ...);", "core/lib/usergroups.lib.php:957|read|$color = colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_LINEPAIR1''), array()), '''');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_LINEPAIR2', 'string', NULL, 'theme', 'Stores the secondary background colour (RGB triplet) for even-numbered list rows in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:265 and theme/md/style.css.php:270 into $colorbacklinepair2. Configurable via admin/ihm.php.', 'Changing this value alters the secondary colour applied to even rows in data tables, typically used for a gradient or border effect.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '069725b461e48b49275c78fe1d865f59db5e0877484a6ea5d6efe68c54c42946', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:265|check|$colorbacklinepair2 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_LINEPAIR2'') ? $colorbacklinepair2 : $conf->global->THEME_ELDY_LINEPAIR", "admin/ihm.php:221|write|dolibarr_set_const($db, ''THEME_ELDY_LINEPAIR2'', $val, ''chaine'', 0, '''', $conf->entity);", "theme/md/style.css.php:270|check|$colorbacklinepair2 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_LINEPAIR2'', $colorbacklinepair2) : getDolUserString(''THEME_ELDY_LINEPAIR2"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_SHADOW_ON_SMALL_BOXES', 'string', NULL, 'theme', 'Enables a box-shadow effect on small list/table boxes in the first and second dashboard columns, in the Eldy theme.', 'Read in theme/eldy/global.inc.php:4624, guarding a CSS block that adds ''overflow-x: unset'' and ''box-shadow: 5px 5px 5px #f0f0f0'' to ''.firstcolumn''/''.secondcolumn table.noborder''; flagged with a TODO to possibly disable on smartphone.', 'Enabling it adds a drop-shadow visual style to small boxed tables on the Eldy theme dashboard columns; unset/0 leaves them without shadow.', 'Boolean-like: enabled = apply box-shadow styling to small boxes; unset/0 = no shadow (default CSS).', 0, 0, NULL, 1, '12ea90e39f8318a534153f9406c90f5cca22a1a99a6bd5af0e6680a2f31b7524', 'v2', '2026-07-24T07:05:23+00:00', '["theme/eldy/global.inc.php:4624: <?php if (getDolGlobalString(''THEME_ELDY_SHADOW_ON_SMALL_BOXES'')) { // TODO Disable on smartphone?>", "theme/eldy/global.inc.php:4628-4629: .firstcolumn table.noborder, .secondcolumn table.noborder { box-shadow: 5px 5px 5px #f0f0f0;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TEXT', 'string', NULL, 'theme', 'Stores the custom default body text colour (RGB triplet) for the Eldy and MD themes.', 'Set to ''0,0,0'' as a default at theme/eldy/style.css.php:249 and theme/md/style.css.php:255 when personalisation is off. Read in style.css.php:270 and md/style.css.php:276 into $colortext. No admin UI write is present.', 'Changing this value alters the default text colour for page body content.', 'String: RGB triplet as ''R,G,B'' (default ''0,0,0'' = black). Empty or unset triggers the theme to set a default.', 1, 0, NULL, 1, '342953fdb3ce4088aefa38c651ac4b0ce431c0305ae787c0d205c3092c416871', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:249|write|$conf->global->THEME_ELDY_TEXT = ''0,0,0'';", "theme/md/style.css.php:255|write|$conf->global->THEME_ELDY_TEXT = ''0,0,0'';", "theme/eldy/style.css.php:270|check|$colortext = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TEXT'') ? $colortext : getDolGlobalString(''THEME_ELDY_TEXT'')) : (empty(", "theme/md/style.css.php:276|check|$colortext = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_TEXT'', $colortext) : getDolUserString(''THEME_ELDY_TEXT'', $colortext);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TEXTBTNACTION', 'string', NULL, 'theme', 'Sets the text color used for action buttons in the Eldy and MD themes.', 'Controls the button action text color applied globally via theme/eldy/style.css.php:243 and theme/md/style.css.php:247. When personalization is disabled, the global value from this constant is used; otherwise the per-user value is checked. Configurable via admin/ihm.php.', 'Changing this value alters the foreground text color on action buttons across the Eldy and MD themes for all users who have not enabled personal theme customization.', 'A CSS-compatible color value (e.g., hex or RGB string); empty/unset means the theme default color is used.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '0dfb756e4d4f0da48e4a78d0aaaf2a900259574c946233d1708c68860d4c4bd5', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:256|write|dolibarr_set_const($db, ''THEME_ELDY_TEXTBTNACTION'', $val, ''chaine'', 0, '''', $conf->entity);", "theme/eldy/style.css.php:275|check|$textbutaction = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TEXTBTNACTION'') ? $textbutaction : getDolGlobalString(''THEME_ELDY_TEXTBTNACTION'')", "core/lib/usergroups.lib.php:1171|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_TEXTBTNACTION''), array()), ''''),''THEME_ELDY_TEXTBTNACTION'','''',1).'' '';", "core/lib/usergroups.lib.php:1164|read|print ''<td>''.(getDolGlobalString(''THEME_ELDY_TOPMENU_BACK1'') ? getDolGlobalString(''THEME_ELDY_TEXTBTNACTION'') :$langs->trans(\"Default\")).''</td>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TEXTLINK', 'string', NULL, 'theme', 'Stores the custom hyperlink text colour (RGB triplet) for the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:271 and theme/md/style.css.php:277 into $colortextlink. A colour picker is available at core/lib/usergroups.lib.php:999. Configurable via admin/ihm.php.', 'Changing this value alters the colour of all hyperlinks throughout the UI.', 'String: RGB triplet as ''R,G,B''. Empty or unset triggers the theme to set a default from $colortext.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'dbb1d529b8360a1691f9440b8f170b35913cc7db8cd68cd247628261d772d5d9', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:271|check|$colortextlink = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TEXTLINK'') ? $colortextlink : getDolGlobalString(''THEME_ELDY_TEXTLINK''", "admin/ihm.php:228|write|dolibarr_set_const($db, ''THEME_ELDY_TEXTLINK'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:999|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_TEXTLINK''), array()), ''''), ''THEME_ELDY_TEXTLINK'', ...);", "core/lib/usergroups.lib.php:1001|read|$color = colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_TEXTLINK''), array()), '''');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TEXTTITLE', 'string', NULL, 'theme', 'Stores the custom text colour (RGB triplet) for tab titles in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:268 and theme/md/style.css.php:274 into $colortexttitle. A colour picker is available at core/lib/usergroups.lib.php:890. Configurable via admin/ihm.php.', 'Changing this value alters the colour of tab title text across the UI.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'ab5b11f1f3bae8f97431f5670d5564fa6c82786d75731dc6ae886b6a91a85c29', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:268|check|$colortexttitle = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TEXTTITLE'') ? $colortexttitle : getDolGlobalString(''THEME_ELDY_TEXTTIT", "admin/ihm.php:188|write|dolibarr_set_const($db, ''THEME_ELDY_TEXTTITLE'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:890|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_TEXTTITLE''), array()), ''''), ''THEME_ELDY_TEXTTITLE'', ...);", "core/lib/usergroups.lib.php:892|read|print $formother->showColor(getDolGlobalString(''THEME_ELDY_TEXTTITLE''), $langs->trans(\"Default\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TEXTTITLELINK', 'string', NULL, 'theme', 'Stores the custom colour (RGB triplet) for hyperlinks within tab titles in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:269 and theme/md/style.css.php:275 into $colortexttitlelink. A colour picker is available at core/lib/usergroups.lib.php:910. Configurable via admin/ihm.php.', 'Changing this value alters the colour of clickable links that appear in tab title areas.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '263544c0e487fab2ca9ae840b857741c81013ae9d9a7b3c386ebabc5490f33ac', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:269|check|$colortexttitlelink = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TEXTTITLELINK'') ? $colortexttitlelink : getDolGlobalString(''THEME_ELDY", "admin/ihm.php:195|write|dolibarr_set_const($db, ''THEME_ELDY_TEXTTITLELINK'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:910|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_TEXTTITLELINK''), array()), ''''), ''THEME_ELDY_TEXTTITLELINK'', ...);", "core/lib/usergroups.lib.php:912|read|print $formother->showColor(getDolGlobalString(''THEME_ELDY_TEXTTITLELINK''), $langs->trans(\"Default\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TEXTTITLENOTAB', 'string', NULL, 'theme', 'Stores the custom text colour (RGB triplet) for section titles without tabs in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:267 and theme/md/style.css.php:273 into $colortexttitlenotab. A colour picker is available at core/lib/usergroups.lib.php:850. Configurable via admin/ihm.php.', 'Changing this value alters the colour of section titles that appear outside of tabbed panels.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '84f52892b6503996dc0c68651f1e9a4e59ee83c4fc4a0e1a8669138bf5572363', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:267|check|$colortexttitlenotab = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TEXTTITLENOTAB'') ? $colortexttitlenotab : getDolGlobalString(''THEME_EL", "admin/ihm.php:174|write|dolibarr_set_const($db, ''THEME_ELDY_TEXTTITLENOTAB'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:850|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_TEXTTITLENOTAB''), array()), ''''), ''THEME_ELDY_TEXTTITLENOTAB'', ...);", "core/lib/usergroups.lib.php:852|read|print $formother->showColor(getDolGlobalString(''THEME_ELDY_TEXTTITLENOTAB''), $langs->trans(\"Default\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TOPBORDER_TITLE1', 'string', NULL, 'theme', 'Stores the custom colour (RGB triplet) for the top border of title sections in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:258 and theme/md/style.css.php:263 into $colortopbordertitle1. No admin UI write is present; value must be set directly.', 'Changing this value alters the colour of the top border stripe displayed above section titles in the theme.', 'String: RGB triplet as ''R,G,B''. Empty or unset uses the theme default.', 1, 0, NULL, 1, '8cd869610b38c05f6268c14ec651b5a7bfc57bd2a706bf557a775b808dbce09c', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:258|check|$colortopbordertitle1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TOPBORDER_TITLE1'') ? $colortopbordertitle1 : $conf->global->THEME_ELDY", "theme/md/style.css.php:263|check|$colortopbordertitle1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_TOPBORDER_TITLE1'', $colortopbordertitle1) : getDolUserString(''THEME_ELDY", "theme/eldy/style.css.php:258|read|$colortopbordertitle1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TOPBORDER_TITLE1'') ? $colortopbordertitle1 : $conf->global->THEME_ELDY"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TOPMENU_BACK1', 'string', NULL, 'core', 'Stores the background color for the top menu bar in the Eldy and MD themes.', 'Configured via admin/ihm.php (write at line 160, delete at line 158). Read in main.inc.php:1781, theme/eldy/style.css.php:258, theme/md/style.css.php:259, and set/copied in multiple locations including core/tpl/login.tpl.php:208, with per-user override possible via THEME_ELDY_ENABLE_PERSONALIZED.', 'Changing this value changes the background color of the top horizontal menu across the Eldy/MD theme, unless overridden per-user.', NULL, 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'b532d8aef0c633dcee80ca924cb64803cf26f17df2b22ed3cecae2c71ecd9dd7', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''THEME_ELDY_TOPMENU_BACK1'')) {", "$colorbackhmenu1      = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_TOPMENU_BACK1'') ? $colorbackhmenu1 : $conf->global->THEME_ELDY_TOPMENU"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_TOTAL_BACKGROUND_LIKE_HEAD', 'string', NULL, 'theme', 'Makes the background color of list ''total'' rows match the header/title background color, in the Eldy theme.', 'Read in theme/eldy/global.inc.php:5247, conditionally emitting ''background: var(--colorbacktitle1);'' for the ''.liste_total''/''.liste_total_wrap'' CSS rules that style totals rows in lists.', 'Enabling it makes list total rows visually match the table header background (--colorbacktitle1); unset/0 leaves the total row without that background override.', 'Boolean-like: enabled = apply --colorbacktitle1 background to total rows; unset/0 = no background override (default).', 0, 0, NULL, 1, '201e71a22f5d2571039d62b5e4d2dc6ce028955f9fdad7fcdc5c396aafc2b3a9', 'v2', '2026-07-24T07:05:23+00:00', '["theme/eldy/global.inc.php:5247: <?php if (getDolGlobalString(''THEME_ELDY_TOTAL_BACKGROUND_LIKE_HEAD'')) { ?>background: var(--colorbacktitle1);<?php } ?>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_USEBOLDTITLE', 'string', NULL, 'theme', 'Toggles bold styling for table/section titles in the Eldy and md themes'' generated CSS.', 'Read identically in theme/eldy/style.css.php:209 and theme/md/style.css.php:209 as $useboldtitle = getDolGlobalInt(''THEME_ELDY_USEBOLDTITLE''), used to build the dynamic theme stylesheet.', 'Enabling it renders titles in bold in the generated CSS for both the eldy and md themes; the payload occurrences do not show the exact CSS rule produced.', 'Boolean-like flag (0/1, read via getDolGlobalInt).', 0, 0, NULL, 1, '368241d07531375afd01b71dddb17156ce089768507409272e9de63c38e6069f', 'v2', '2026-07-24T07:05:23+00:00', '["theme/eldy/style.css.php:209: $useboldtitle = getDolGlobalInt(''THEME_ELDY_USEBOLDTITLE'');", "theme/md/style.css.php:209: $useboldtitle = getDolGlobalInt(''THEME_ELDY_USEBOLDTITLE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_USEBORDERONTABLE', 'string', '1', 'theme', 'Controls whether borders are rendered on tables in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:208 and theme/md/style.css.php:213 to set the $userborderontable variable. Also used in theme/eldy/global.inc.php:159, theme/md/info-box.inc.php:20, and theme/eldy/dropdown.inc.php:28 to conditionally apply border-radius. Default is ''1''. Ten occurrences across multiple files. No admin UI write is present in the payload.', 'Disabling this constant removes table borders and sets border-radius to 0 across the Eldy and MD themes.', 'Integer; 1 (default) = borders enabled; 0 = borders disabled.', 1, 1, NULL, 1, '8583e0941a6fad552f3cc84340b3fd5c4c711691605b12e6ea4946a7b4aae725', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:208|read|$userborderontable = getDolGlobalInt(''THEME_ELDY_USEBORDERONTABLE'');", "theme/md/style.css.php:213|read|$userborderontable = getDolGlobalInt(''THEME_ELDY_USEBORDERONTABLE'');", "theme/eldy/global.inc.php:159|read|$borderradius = getDolGlobalString(''THEME_ELDY_USEBORDERONTABLE'') ? getDolGlobalInt(''THEME_ELDY_BORDER_RADIUS'', 6) : 0;", "core/lib/usergroups.lib.php:664|check|if (getDolGlobalString(''THEME_ELDY_USEBORDERONTABLE'') || getDolGlobalString(''THEME_SHOW_BORDER_ON_INPUT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_USECOMOACTROW', 'string', NULL, 'theme', 'Controls whether compact (higher) row height is used in list tables of the Eldy and MD themes.', 'When enabled, the CSS row height variable is set to ''300%''; when disabled or empty, it is set to ''155%'', as seen in theme/eldy/style.css.php:278 and theme/md/style.css.php:283. Configurable via admin/ihm.php:122.', 'Enabling this constant increases list row height to ''300%'', making rows taller across all list tables in the Eldy and MD themes.', 'Non-empty/truthy value = compact row height (''300%''); empty/unset = normal row height (''155%'').', 0, 0, 'admin/ihm.php', 1, 'cc1772758acbb2b9d9fe619ecd60843cc85af3ce88ad4aa41940ae2c90d84f47', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:278|check|$heightrow = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_USECOMOACTROW'') ? ''155%'' : ''300%'') : (empty($user->conf->THEME_ELDY_USECOMOAC", "theme/md/style.css.php:283|check|$heightrow = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (getDolGlobalString(''THEME_ELDY_USECOMOACTROW'') ? ''300%'' : ''155%'') : (getDolUserString(''THEME_ELDY_USECOMOACTRO", "admin/ihm.php:122|write|dolibarr_set_const($db, \"THEME_ELDY_USECOMOACTROW\", GETPOST(''THEME_ELDY_USECOMOACTROW''), ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:701  //print ajax_constantonoff(''THEME_ELDY_USECOMOACTROW'', array(), null, 0, 0, 1);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_USE_CHECKED', 'bool', NULL, 'theme', 'Sets the background color applied to checked/selected rows in list tables for the Eldy and MD themes.', 'Determines the checked-row highlight color ($colorbacklinepairchecked) in theme/eldy/style.css.php:281 and theme/md/style.css.php:287. If unset or equal to ''255,255,255'', no checked highlight is applied. Configurable via admin/ihm.php:242.', 'Setting this to a non-white color enables visible highlight on checked/selected rows in list tables; setting it to ''255,255,255'' or clearing it disables the highlight.', 'A CSS RGB string (e.g., ''200,220,240''); ''255,255,255'' or unset = no checked highlight; ''1'' = checked highlight enabled with default color.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '564bbcc7cdc738e5c3cf1e20a28f4c3ae16fc55bf7265b4169a5f3fc1dfb3000', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:242|write|dolibarr_set_const($db, \"THEME_ELDY_USE_CHECKED\", $val, ''chaine'', 0, '''', $conf->entity);", "theme/eldy/style.css.php:281|read|$colorbacklinepairchecked = ((!isset($conf->global->THEME_ELDY_USE_CHECKED) || getDolGlobalString(''THEME_ELDY_USE_CHECKED'') === ''255,255,255'') ? '''' : (getDolGlobalString(''THEME_ELD", "core/lib/usergroups.lib.php:1085|check|if (getDolGlobalString(''THEME_ELDY_USE_CHECKED'') == ''1'') {", "core/lib/usergroups.lib.php:1092|check|if (getDolGlobalString(''THEME_ELDY_USE_CHECKED'') == ''1'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_USE_HOVER', 'bool', NULL, 'theme', 'Sets the background color applied to hovered rows in list tables for the Eldy and MD themes.', 'Determines the hover highlight color ($colorbacklinepairhover) in theme/eldy/style.css.php:280 and theme/md/style.css.php:286. If unset or equal to ''255,255,255'', no hover color is applied. Configurable via admin/ihm.php:235.', 'Setting this to a non-white color enables visible row hover highlighting in list tables; setting it to ''255,255,255'' or clearing it disables the highlight.', 'A CSS RGB string (e.g., ''200,220,240''); ''255,255,255'' or unset = no hover highlight; ''1'' = hover enabled with default color.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '72aff1a93d2cc8549474cc525861508688845a863291e071a47905e0b599ddec', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ihm.php:235|write|dolibarr_set_const($db, \"THEME_ELDY_USE_HOVER\", $val, ''chaine'', 0, '''', $conf->entity);", "theme/eldy/style.css.php:280|read|$colorbacklinepairhover = ((!isset($conf->global->THEME_ELDY_USE_HOVER) || getDolGlobalString(''THEME_ELDY_USE_HOVER'') === ''255,255,255'') ? '''' : (getDolGlobalString(''THEME_ELDY_USE_", "core/lib/usergroups.lib.php:1037|check|if (getDolGlobalString(''THEME_ELDY_USE_HOVER'') == ''1'') {", "core/lib/usergroups.lib.php:1044|check|if (getDolGlobalString(''THEME_ELDY_USE_HOVER'') == ''1'') {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_VERMENU_BACK1', 'string', NULL, 'theme', 'Stores the custom background colour (RGB triplet) for the vertical navigation menu in the Eldy and MD themes.', 'Read in theme/eldy/style.css.php:257 and theme/md/style.css.php:262 into $colorbackvmenu1. A colour picker is provided at core/lib/usergroups.lib.php:768. Configurable via admin/ihm.php.', 'Changing this value alters the background colour of the left vertical navigation menu.', 'String: RGB triplet as ''R,G,B'' (e.g. ''51,51,51''). Empty or unset uses the theme default.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, '3e76066a40bfe135925493cd608741f4d61c89b67cbef11fa4f1d3315c1070cb', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/style.css.php:257|check|$colorbackvmenu1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? (!getDolGlobalString(''THEME_ELDY_VERMENU_BACK1'') ? $colorbackvmenu1 : $conf->global->THEME_ELDY_VERMENU", "admin/ihm.php:167|write|dolibarr_set_const($db, ''THEME_ELDY_VERMENU_BACK1'', $val, ''chaine'', 0, '''', $conf->entity);", "core/lib/usergroups.lib.php:768|read|print $formother->selectColor(colorArrayToHex(colorStringToArray(getDolGlobalString(''THEME_ELDY_VERMENU_BACK1''), array()), ''''),''THEME_ELDY_VERMENU_BACK1'','''',1).'' '';", "theme/md/style.css.php:262|check|$colorbackvmenu1 = empty($user->conf->THEME_ELDY_ENABLE_PERSONALIZED) ? getDolGlobalString(''THEME_ELDY_VERMENU_BACK1'', $colorbackvmenu1) : getDolUserString(''THEME_ELDY_VERMENU_"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_WITDHOFFSET_FOR_REDUC1', 'string', NULL, 'theme', 'Sets the pixel breakpoint for the first responsive layout reduction in the Eldy and MD themes.', 'Read in theme/eldy/global.inc.php:9148, theme/md/btn.inc.php:426, and theme/md/style.css.php:8932 as the max-width value in a media query, with a default computed from the number of top menu entries. Three occurrences across three files. No admin UI write is present.', 'Changing this value shifts the screen width at which the first CSS layout reduction is applied in both themes.', 'Integer pixel value; default is computed as round($nbtopmenuentries * 90, 0) + 340 when unset.', 1, 0, NULL, 1, '5b4a1a82cf5df8459c2002f5ac58a8326d10114ec00d54aa5458be9c297fb0e5', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/global.inc.php:9148|read|@media only screen and (max-width: <?php echo getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC1'', round($nbtopmenuentries * 90, 0) + 340); ?>px)\t/* reduction 1 */", "theme/md/btn.inc.php:426|read|@media only screen and (max-width: <?php echo getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC1'', round($nbtopmenuentries * 90, 0) + 340); ?>px)\t/* reduction 1 */", "theme/md/style.css.php:8932|read|@media only screen and (max-width: <?php echo getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC1'', round($nbtopmenuentries * 90, 0) + 340); ?>px)\t/* reduction 1 */"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_WITDHOFFSET_FOR_REDUC2', 'string', NULL, 'theme', 'Overrides the pixel width breakpoint at which the Eldy/MD theme applies the second-level responsive menu reduction.', 'Read in theme/eldy/btn.inc.php:377, theme/eldy/global.inc.php:9188, theme/md/btn.inc.php:434, and theme/md/style.css.php:8961 as the max-width media query breakpoint for ''reduction 2''. When unset, the breakpoint is calculated as round($nbtopmenuentries * 69, 0) + 130. No admin UI write path is present in the payload.', 'Setting this to a pixel value fixes the responsive breakpoint for the second menu-reduction level. Leaving it unset causes the breakpoint to be computed from the number of top menu entries.', 'Integer pixel value for the max-width media query breakpoint. Default computed as round($nbtopmenuentries * 69, 0) + 130.', 1, 0, NULL, 1, '0988fae6ed58c72b846d55595aba5df00f35a543a8d82d170b155d8b7be710ca', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/global.inc.php:9188|read|@media only screen and (max-width: <?php echo getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC2'', round($nbtopmenuentries * 69, 0) + 130); ?>px)\t/* reduction 2 */", "theme/md/style.css.php:8961|read|@media only screen and (max-width: <?php echo getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC2'', round($nbtopmenuentries * 66, 0) + 220); ?>px)\t/* reduction 2 */", "theme/eldy/btn.inc.php:377|read|@media only screen and (max-width: <?php echo !getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC2'') ? round($nbtopmenuentries * 69, 0) + 130 : $conf->global->THEME_ELDY_WITDHOFF"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ELDY_WITDHOFFSET_FOR_REDUC3', 'string', NULL, 'theme', 'Overrides the pixel width breakpoint at which the Eldy/MD theme applies the third-level responsive menu reduction.', 'Read in theme/eldy/btn.inc.php:385, theme/eldy/global.inc.php:2174, :2755, :9220, theme/md/btn.inc.php:442, theme/md/style.css.php:2280, and :9002 as the min-width or max-width media query breakpoint for ''reduction 3''. When unset, the breakpoint is calculated as round($nbtopmenuentries * 47, 0) + 130. No admin UI write path is present in the payload.', 'Setting this to a pixel value fixes the responsive breakpoint for the third menu-reduction level. Leaving it unset causes the breakpoint to be computed from the number of top menu entries.', 'Integer pixel value for the media query breakpoint. Default computed as round($nbtopmenuentries * 47, 0) + 130.', 1, 0, NULL, 1, '0be5f772c12d2b5d07c0fcd2a7fc2d998576cde1ba29cbddbeef0e8e2e4cd5b1', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/global.inc.php:2174|read|@media only screen and (min-width: <?php echo getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC3'', round($nbtopmenuentries * 47, 0) + 130); ?>px)\t/* reduction 3 */", "theme/eldy/global.inc.php:2755|read|@media only screen and (max-width: <?php echo getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC3'', round($nbtopmenuentries * 47, 0) + 130); ?>px)\t/* reduction 3 */", "theme/eldy/global.inc.php:9220|read|@media only screen and (max-width: <?php echo getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC3'', round($nbtopmenuentries * 47, 0) + 130); ?>px)\t/* reduction 3 */", "theme/md/btn.inc.php:442|read|@media only screen and (max-width: <?php echo !getDolGlobalString(''THEME_ELDY_WITDHOFFSET_FOR_REDUC3'') ? round($nbtopmenuentries * 47, 0) + 130 : getDolGlobalInt(''THEME_ELDY_WITDHO"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ENABLE_STICKY_COLUMN_ACTION', 'bool', NULL, 'theme', 'Enables CSS to make the ''action'' column sticky (fixed on the right) when scrolling wide tables in the theme.', 'Checked in theme/md/style.css.php:4610: <?php if (getDolGlobalString(''THEME_ENABLE_STICKY_COLUMN_ACTION'')) { ?> wraps CSS rules applying position: sticky; right: 0; to td.actioncolumn/th.actioncolumn in .tagtable.', 'When enabled, the action column of tagged tables (.tagtable .actioncolumn) stays pinned to the right edge while horizontally scrolling; when disabled, normal (non-sticky) column layout applies.', 'Boolean: 1/true enables sticky-right CSS for the action column.', 0, 0, NULL, 1, 'c77db7a58f1c8b51def392e52cdedc037d71ba8db310954cea31fd49d38b6315', 'v2', '2026-07-24T07:05:23+00:00', '["theme/md/style.css.php:4610: <?php if (getDolGlobalString(''THEME_ENABLE_STICKY_COLUMN_ACTION'')) { ?>", "theme/md/style.css.php: .tagtable td.actioncolumn, .tagtable th.actioncolumn { position: sticky; right: 0; ... }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_ENABLE_STICKY_COLUMN_REF', 'bool', NULL, 'theme', 'Enables CSS to make the ''ref'' column sticky (fixed on the left) when scrolling wide tables in the theme.', 'Checked in theme/md/style.css.php:4597: <?php if (getDolGlobalString(''THEME_ENABLE_STICKY_COLUMN_REF'')) { ?> wraps CSS rules applying position: sticky; left: 0; to td/th[data-key="ref"] in .tagtable.', 'When enabled, the reference column of tagged tables (.tagtable with data-key="ref") stays pinned to the left edge while horizontally scrolling; when disabled, normal (non-sticky) column layout applies.', 'Boolean: 1/true enables sticky-left CSS for the ref column.', 0, 0, NULL, 1, '2ea9f4fd2574ff7bac0b54165811e5ab09418177966e75325b61c6057bb42314', 'v2', '2026-07-24T07:05:23+00:00', '["theme/md/style.css.php:4597: <?php if (getDolGlobalString(''THEME_ENABLE_STICKY_COLUMN_REF'')) { ?>", "theme/md/style.css.php: .tagtable td[data-key=\"ref\"], .tagtable th[data-key=\"ref\"] { position: sticky; left: 0; ... }"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_FONT_FAMILY', 'string', NULL, 'theme', 'Overrides the default font family used across the Eldy and MD theme stylesheets and the WYSIWYG editor.', 'Checked and read in theme/eldy/style.css.php:194-195, theme/md/style.css.php:193-194, and core/class/doleditor.class.php:400-401, where it is prepended to the fontlist string.', 'When set, the specified font family is prepended to the CSS font list used by the theme and the doleditor, changing the rendered font.', NULL, 0, 0, NULL, 1, '01fa1469a49b7a664b449c991ac06d88324473f62c17e3d7b89d8ce260f13455', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''THEME_FONT_FAMILY'')) {", "$fontlist = getDolGlobalString(''THEME_FONT_FAMILY'').'', ''.$fontlist;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_INFOBOX_COLOR_ON_BACKGROUND', 'string', NULL, 'theme', 'When enabled, applies a colour-on-background style variant to info boxes in the Eldy and MD themes.', 'Checked in theme/eldy/info-box.inc.php:375, theme/md/info-box.inc.php:41, and theme/md/info-box.inc.php:489 to conditionally apply an alternative info-box rendering style. No admin UI write path is present in the payload.', 'Enabling this constant switches info boxes to a colour-on-background visual style. Leaving it unset uses the default info-box style.', 'Truthy value to enable colour-on-background style; unset or 0 for default style.', 1, 0, NULL, 1, '48e0b07194909a26ccff7dc3677304d0e269a3fc3bcce50b54a30a6f6b54202b', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/info-box.inc.php:375|check|if (getDolGlobalString(''THEME_INFOBOX_COLOR_ON_BACKGROUND'')) {", "theme/md/info-box.inc.php:41|check|if (getDolGlobalString(''THEME_INFOBOX_COLOR_ON_BACKGROUND'')) {", "theme/md/info-box.inc.php:489|check|if (getDolGlobalString(''THEME_INFOBOX_COLOR_ON_BACKGROUND'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_MENU_COLORLOGO', 'string', NULL, 'theme', 'When enabled, uses a colour version of the logo in the menu; when disabled, a monochrome or alternative logo is used.', 'Checked in theme/eldy/main_menu_fa_icons.inc.php:138 and theme/md/main_menu_fa_icons.inc.php:106 to decide which logo variant to render in the menu. Displayed as a yes/no value in core/lib/usergroups.lib.php:602. No admin UI write path is present in the payload.', 'Enabling this constant switches the menu logo to its colour variant. Leaving it unset causes the alternative (non-colour) logo to be used.', 'Truthy value to use colour logo in menu; unset or 0 to use alternative logo.', 1, 0, NULL, 1, '3a2b4beae1fd5c6dda76a907d4878e5dfae2411e4aa5f61fbe5d6cfb8a11a294', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/main_menu_fa_icons.inc.php:138|check|if (!getDolGlobalString(''THEME_MENU_COLORLOGO'')) {", "theme/md/main_menu_fa_icons.inc.php:106|check|if (!getDolGlobalString(''THEME_MENU_COLORLOGO'')) {", "core/lib/usergroups.lib.php:602|read|print yn(getDolGlobalString(''THEME_MENU_COLORLOGO''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_SATURATE_RATIO', 'string', NULL, 'theme', 'Controls the CSS saturation ratio applied to info-box colours in the Eldy and MD themes.', 'Written at runtime to $conf->global->THEME_SATURATE_RATIO in theme/eldy/info-box.inc.php:380, :383 and theme/md/info-box.inc.php:46, :49, :494, :497. The value is obtained from user input via GETPOSTFLOAT or defaulted to 0.8. Checked before applying saturation styling in theme/eldy/info-box.inc.php:392 and theme/md/info-box.inc.php:269.', 'Adjusting this value changes the CSS colour saturation intensity of info boxes. A value of 0.8 is used as the runtime default.', 'Float between 0 and 1 (e.g. 0.8). Runtime default is 0.8.', 1, 0, NULL, 1, 'fe355cfd10c38cd2b30b5214f21527a0ea9c4dbee0aeba5448e3f7d82936cf97', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/info-box.inc.php:380|write|$conf->global->THEME_SATURATE_RATIO = 0.8;", "theme/eldy/info-box.inc.php:383|write|$conf->global->THEME_SATURATE_RATIO = GETPOSTFLOAT(''THEME_SATURATE_RATIO'');", "theme/eldy/info-box.inc.php:392|check|<?php if (getDolGlobalString(''THEME_SATURATE_RATIO'')) { ?>", "theme/md/info-box.inc.php:269|check|<?php if (getDolGlobalString(''THEME_SATURATE_RATIO'')) { ?>"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_SHOW_BORDER_ON_INPUT', 'bool', NULL, 'theme', 'Toggles display of borders around input fields in the Eldy/MD themes.', 'Checked via getDolGlobalString extensively in theme/eldy/global.inc.php (lines 452, 538, 7645, 7680) and theme/md/style.css.php (lines 638, 7436, 7474), and also combined with THEME_ELDY_USEBORDERONTABLE in core/lib/usergroups.lib.php:664.', 'When enabled, input fields display a visible border; when disabled, borders are hidden in several theme templates.', NULL, 0, 0, NULL, 1, '69b853b89f3ee46cb5efad4a10cf479bb7d7d261d78d30623c9f7df0bb19e94f', 'v2', '2026-07-24T06:41:12+00:00', '["<?php if (!getDolGlobalString(''THEME_SHOW_BORDER_ON_INPUT'')) { ?>", "if (getDolGlobalString(''THEME_ELDY_USEBORDERONTABLE'') || getDolGlobalString(''THEME_SHOW_BORDER_ON_INPUT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_STICKY_TOPMENU', 'string', NULL, 'theme', 'Controls the sticky behavior of the top menu bar in the Eldy and MD themes.', 'Checked in theme/eldy/global.inc.php:2581, :2646, :2661 and theme/md/style.css.php:2800 against specific string values to apply different sticky scroll behaviors. Four occurrences across two files. No admin UI write is present.', 'Changing this value alters how the top menu sticks or scrolls relative to page content.', 'String; ''disabled'' = top menu not sticky; ''scrollleftmenu_after_mainpage'' = left menu scrolls after main page; other truthy values = standard sticky behavior.', 1, 0, NULL, 1, 'ea73258c62c0e69280e10fc62d9cd2136a8ea0782229f5b8ed9b26c3d42a4d72', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/global.inc.php:2581|check|<?php if (getDolGlobalString(''THEME_STICKY_TOPMENU'') == ''scrollleftmenu_after_mainpage'') { ?>", "theme/eldy/global.inc.php:2646|check|<?php if (getDolGlobalString(''THEME_STICKY_TOPMENU'') != ''disabled'') {  ?>", "theme/md/style.css.php:2800|check|<?php if (getDolGlobalString(''THEME_STICKY_TOPMENU'') != ''disabled'') {  ?>"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_TOPMENU_DISABLE_IMAGE', 'bool', NULL, 'core', 'Controls whether images or text are displayed in the top menu items.', 'Written via admin/ihm.php:140 and deleted via admin/ihm.php:138. Checked across theme/eldy/global.inc.php and theme/md/style.css.php against values 2, 3, and 4. COMMENTS state: ''To show text of top menu according to option THEME_TOPMENU_DISABLE_IMAGE'' and ''Text hidden by default when option THEME_TOPMENU_DISABLE_IMAGE''. Twenty-one occurrences across multiple files.', 'Changing this value switches the top menu between image-only, text-only, and combined display modes.', 'Integer; 0 or unset = images shown (text hidden by default); 2 = text shown alongside images; 3 = specific text-only variant; 4 = another display variant.', 0, 0, 'admin/ihm.php|admin/ihm.php', 1, 'cfd13b2e992d37e89e69e020526ecd19d7b17f58da692366fafc248463f43478', 'v2', '2026-04-21T11:16:15+00:00', '["theme/eldy/global.inc.php:3407  /* To show text of top menu according to option THEME_TOPMENU_DISABLE_IMAGE */", "theme/eldy/global.inc.php:3409  /* Text hidden by default when option THEME_TOPMENU_DISABLE_IMAGE */", "theme/eldy/global.inc.php:3410|check|<?php if (in_array(getDolGlobalInt(''THEME_TOPMENU_DISABLE_IMAGE''), array(2, 3, 4))) { ?>", "admin/ihm.php:140|write|dolibarr_set_const($db, ''THEME_TOPMENU_DISABLE_IMAGE'', GETPOST(''THEME_TOPMENU_DISABLE_IMAGE''), ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THEME_TOPMENU_DISABLE_TEXT', 'bool', NULL, 'core', 'Disables text labels on top-menu entries, showing only icons.', 'Checked in 6 occurrences across auguria.lib.php, eldy.lib.php, and empty.php menu files. When set, the text alongside top-menu icons is suppressed.', 'Setting this constant hides menu item labels in the top navigation bar, resulting in an icon-only menu.', 'Non-empty = text labels hidden; empty or unset = text labels shown', 1, 0, NULL, 1, '39dfa4b073ba3fcae6996a1bc9a09128cd18c9780f407357e6cb6abac05a46b5', 'v2', '2026-04-21T13:29:58+00:00', '["core/menus/standard/auguria.lib.php:271|check|if (!getDolGlobalString(''THEME_TOPMENU_DISABLE_TEXT'')) {", "core/menus/standard/eldy.lib.php:689|check|if (!getDolGlobalString(''THEME_TOPMENU_DISABLE_TEXT'')) {", "core/menus/standard/empty.php:574|check|if (!getDolGlobalString(''THEME_TOPMENU_DISABLE_TEXT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTIES_DISABLE_RELATED_OBJECT_TAB', 'bool', NULL, 'core', 'Disables the ''Referers'' (related commercial objects / consumption) tab on thirdparty cards.', 'In core/lib/company.lib.php:205-212, the ''Referers'' tab (linking to societe/consumption.php) is added when any of order/propal/invoice/intervention/supplier_proposal/supplier_order/supplier_invoice modules are enabled AND !getDolGlobalString(''THIRDPARTIES_DISABLE_RELATED_OBJECT_TAB'').', 'Setting it hides the Referers/consumption tab on thirdparty cards even if relevant commercial modules are enabled.', 'Boolean-like: set/non-empty disables (hides) the Referers tab; unset (default) shows it when a relevant module is enabled.', 1, 0, NULL, 1, '2171d5faafa14da5a2d709c11fa491ef565f04a6f7483aa889cd1b9ce99eeab2', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/company.lib.php:207-209: if ((isModEnabled(''order'') || ... ) && !getDolGlobalString(''THIRDPARTIES_DISABLE_RELATED_OBJECT_TAB'')) {", "core/lib/company.lib.php:211: $head[$h][1] = $langs->trans(\"Referers\");"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_CAN_HAVE_CUSTOMER_CATEGORY_EVEN_IF_NOT_CUSTOMER_PROSPECT', 'string', NULL, 'societe', 'When enabled, allows assigning customer categories to third parties that are not marked as customers or prospects.', 'Checked in societe/card.php:3294 alongside prospect/client status checks, and read in societe/card.php:1286 and :2278 to set JavaScript variables controlling category UI behavior. Three occurrences in one file.', 'Enabling this constant removes the customer/prospect status requirement for customer category assignment on third-party cards.', 'Boolean flag; unset or 0 = customer category only shown for customers/prospects; any truthy value = shown for all third parties.', 1, 0, NULL, 1, '0df8e71f04eadc4713951fa68145c57c9c339178fa3b559e9c5c7502cbba3044', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:3294|check|if ($object->prospect || $object->client || getDolGlobalString(''THIRDPARTY_CAN_HAVE_CUSTOMER_CATEGORY_EVEN_IF_NOT_CUSTOMER_PROSPECT'')) {", "societe/card.php:1286|read|var canHaveCustomerCategoryIfNotCustomerProspectSupplier = '' . (!getDolGlobalString(''THIRDPARTY_CAN_HAVE_CUSTOMER_CATEGORY_EVEN_IF_NOT_CUSTOMER_PROSPECT'') ? ''0'' : ''1'') . '';", "societe/card.php:2278|read|var canHaveCustomerCategoryIfNotCustomerProspect = '' . (getDolGlobalInt(''THIRDPARTY_CAN_HAVE_CUSTOMER_CATEGORY_EVEN_IF_NOT_CUSTOMER_PROSPECT'') ? ''1'' : ''0'') . '';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_CUSTOMERCODE_EQUALS_MEMBERREF', 'string', NULL, 'societe', 'Makes a thirdparty created from a member (Adherent) reuse the member''s reference as its customer code instead of auto-generating a new one.', 'Checked in societe/class/societe.class.php:4687 inside create_from_member(Adherent $member, ...): if set, code_client is assigned $member->ref; otherwise it falls back to the passed $customercode or -1 (auto-increment).', 'Enabling it makes the customer code of a thirdparty auto-created from a foundation member identical to that member''s reference instead of being generated by the normal customer-code numbering rule.', 'Boolean-like: truthy makes code_client = $member->ref instead of the auto-generated code.', 1, 0, NULL, 1, 'ad2885e051a5bd6db9b2e13c2bb881c49e08eaa8f2f0f3c9d99be9cc893e0327', 'v2', '2026-07-24T07:05:23+00:00', '["societe/class/societe.class.php:4687|check|if (getDolGlobalString(''THIRDPARTY_CUSTOMERCODE_EQUALS_MEMBERREF'')) {", "societe/class/societe.class.php: $this->code_client = $member->ref; // set Customer Code equal to existing Member Reference"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_CUSTOMERPROSPECT_BY_DEFAULT', 'string', NULL, 'societe', 'Sets a new third-party''s ''client'' status to prospect (3) by default when creating a company that is not explicitly typed as a supplier.', 'In societe/card.php:1053, during third-party creation, if the ''type'' POST parameter is not ''f'' (supplier), $object->client defaults to -1 unless this constant is set, in which case it is forced to 3 (prospect).', 'When set, newly created third parties default to prospect status instead of the standard ''unknown/not defined'' (-1) status.', 'Not set/falsy (default): $object->client = -1 (undefined). Truthy: $object->client = 3 (prospect).', 1, 0, NULL, 1, 'ff85db44b82ff03d02c6fb8911a40249552e7ba7ce0739716e07cfecbbf1834c', 'v2', '2026-07-24T07:05:23+00:00', '["societe/card.php:1051-1055|code|if (GETPOST(\"type\", ''aZ'') != ''f'') { $object->client = -1; if (getDolGlobalString(''THIRDPARTY_CUSTOMERPROSPECT_BY_DEFAULT'')) { $object->client = 3; } }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_CUSTOMERTYPE_BY_DEFAULT', 'string', NULL, 'societe', 'Sets the default customer type pre-selected when creating a new third party.', 'Written in societe/admin/societe.php:111 and read in societe/admin/societe.php:955 for display in the admin UI. Used in societe/card.php:1055 and :1056 to pre-populate the client field and in :1479/:1480 to pre-select customer or prospect status based on the value.', 'Changing this value alters the default customer classification applied to all newly created third parties. A value of 1 pre-selects customer; a value of 2 pre-selects prospect.', 'Integer; 1 = customer pre-selected by default, 2 = prospect pre-selected by default, 0 or unset = no default.', 0, 0, 'societe/admin/societe.php|societe/admin/societe.php', 1, 'e3b26be915f0cd36d746f03144154e85ad2c0948e94c195692ef3dfeabffd660', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:1056|read|$object->client = getDolGlobalInt(''THIRDPARTY_CUSTOMERTYPE_BY_DEFAULT'');", "societe/card.php:1479|read|$selectedcustomer = ((getDolGlobalInt(''THIRDPARTY_CUSTOMERTYPE_BY_DEFAULT'')==1 && GETPOST(\"type\", ''aZ'') != ''p'' && GETPOST(\"type\", ''aZ'') != ''f'') || (getDolGlobalInt(''THIRDPARTY_CUST", "societe/admin/societe.php:111|write|$res = dolibarr_set_const($db, \"THIRDPARTY_CUSTOMERTYPE_BY_DEFAULT\", $customertypedefault, ''chaine'', 0, '''', $conf->entity);", "societe/admin/societe.php:955|read|print $formcompany->selectProspectCustomerType(getDolGlobalInt(''THIRDPARTY_CUSTOMERTYPE_BY_DEFAULT''), ''defaultcustomertype'', ''defaultcustomertype'', ''admin'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_DEFAULT_CREATE_CONTACT', 'string', NULL, 'societe', 'Automatically creates a default contact when a new third party is created.', 'Checked in societe/class/societe.class.php at line 4738 and in societe/card.php at line 1009, where contact creation is triggered for non-private, non-individual new third parties.', 'Enabling this constant causes a contact record to be created automatically alongside new third party records that meet the conditions.', '0 or empty = no automatic contact creation; any truthy value = contact created automatically', 1, 0, NULL, 1, '08250e98c518c734dfe246a01c4edd9e15467cdc486f75a95f3086974904e8cd', 'v2', '2026-04-21T11:16:15+00:00', '["societe/class/societe.class.php:4738|check|if (getDolGlobalString(''THIRDPARTY_DEFAULT_CREATE_CONTACT'')) {", "societe/card.php:1009|check|if (getDolGlobalString(''THIRDPARTY_DEFAULT_CREATE_CONTACT'') && !GETPOSTISSET(''private'') && GETPOST(\"type\", ''aZ'') != ''f'') {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_DEFAULT_USELOCALTAX1', 'string', NULL, 'societe', 'Sets the default checked state of the ''apply local tax 1'' checkbox shown on a third-party''s edit form when the company''s country uses local tax 1.', 'Used twice in societe/card.php (lines 1857 and 1867) to determine the ''checked'' attribute of the localtax1assuj_value checkbox, shown only when $mysoc->localtax1_assuj == ''1''.', 'When set, the local-tax-1 checkbox for a third-party defaults to checked; when unset, it defaults to unchecked.', 'Not set/falsy (default): checkbox unchecked by default. Truthy: checkbox checked by default.', 1, 0, NULL, 1, '339ad3e46126d0054f818e7f33fb302cf4643929f76bb0269c4223a2fb4a3483', 'v2', '2026-07-24T07:05:23+00:00', '["societe/card.php:1857|read|print ''<input id=\"localtax1assuj_value\" ... '' . (getDolGlobalString(''THIRDPARTY_DEFAULT_USELOCALTAX1'') ? ''checked=\"checked\"'' : '''') . '' value=\"1\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_DEFAULT_USELOCALTAX2', 'string', NULL, 'societe', 'Sets the default checked state of the ''apply local tax 2'' checkbox shown on a third-party''s edit form when the company''s country uses local tax 2.', 'Used twice in societe/card.php (lines 1863 and 1871) to determine the ''checked'' attribute of the localtax2assuj_value checkbox, shown when $mysoc->localtax2_assuj == ''1''.', 'When set, the local-tax-2 checkbox for a third-party defaults to checked; when unset, it defaults to unchecked.', 'Not set/falsy (default): checkbox unchecked by default. Truthy: checkbox checked by default.', 1, 0, NULL, 1, '42357c9d1835372c7c671d62aeca37a7b08de021525ee9a51a07401646964f8b', 'v2', '2026-07-24T07:05:23+00:00', '["societe/card.php:1863|read|print ''<input id=\"localtax2assuj_value\" ... '' . (getDolGlobalString(''THIRDPARTY_DEFAULT_USELOCALTAX2'') ? ''checked=\"checked\"'' : '''') . '' value=\"1\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_ENABLE_PROSPECTION_ON_ALTERNATIVE_ADRESSES', 'bool', NULL, 'contact', 'Enables prospect-level tracking on contact records (alternative addresses) in addition to the thirdparty level.', 'When not set, there is no prospect level on contact level, only on thirdparty (contact/class/contact.class.php:403). When set, prospect-related dictionary entries and UI fields are activated in admin/dict.php, contact/card.php, and contact/list.php.', 'Enabling this constant activates prospect status management on contacts; disabling it restricts prospect tracking to the thirdparty level only.', 'Empty/unset = no prospect level on contacts (default); non-empty = prospect level enabled on contacts.', 0, 0, 'admin/dict.php|admin/dict.php', 1, '58228d41693702bf2864d9ca4d45d2fd946a0c81d33acd8e280877edc78cb241', 'v2', '2026-04-21T11:16:15+00:00', '["contact/class/contact.class.php:403  // If THIRDPARTY_ENABLE_PROSPECTION_ON_ALTERNATIVE_ADRESSES not set, there is no prospect level on contact level, only on thirdparty", "contact/class/contact.class.php:404|check|if (getDolGlobalString(''SOCIETE_DISABLE_PROSPECTS'') || !getDolGlobalString(''THIRDPARTY_ENABLE_PROSPECTION_ON_ALTERNATIVE_ADRESSES'')) {\t// Default behaviour", "admin/dict.php:593|read|$tabcond[DICT_STCOMMCONTACT] = (isModEnabled(\"societe\") && getDolGlobalString(''THIRDPARTY_ENABLE_PROSPECTION_ON_ALTERNATIVE_ADRESSES''));", "contact/card.php:1420|check|if (getDolGlobalString(''THIRDPARTY_ENABLE_PROSPECTION_ON_ALTERNATIVE_ADRESSES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_INCLUDE_PARENT_IN_LINKTO', 'string', NULL, 'core', 'Controls whether the parent company of a thirdparty is also scanned when listing linkable elements in the ''link to element'' popup.', 'Checked in core/class/html.form.class.php:11125; when true and the object''s thirdparty has a parent, the parent''s id is appended to $listofidcompanytoscan used in the linkable-elements SQL queries.', 'Enabling it broadens the linkable-element search to also include elements attached to the thirdparty''s parent company, not just the thirdparty itself.', 'Boolean: truthy value adds the thirdparty''s parent id to the list of company ids scanned for linkable elements.', 1, 0, NULL, 1, 'c39102937cb403e6b1aee5b5e1f1c42fda581d6246e87438e0311a33a6576210', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:11125|check|if (is_object($object->thirdparty) && ($object->thirdparty->parent > 0) && getDolGlobalString(''THIRDPARTY_INCLUDE_PARENT_IN_LINKTO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_INCLUDE_PROJECT_THIRDPARY_IN_LINKTO', 'string', NULL, 'core', 'Controls whether the thirdparty attached to the current object''s project is also scanned when listing linkable elements in the ''link to element'' popup.', 'Checked in core/class/html.form.class.php:11128; when true and the object has a linked project (fk_project > 0), that project''s thirdparty is loaded and presumably added to the scan list for linkable elements.', 'Enabling it broadens the linkable-element search to also include elements tied to the thirdparty associated with the object''s project.', 'Boolean: truthy value includes the project''s thirdparty in the linkable-elements scan.', 1, 0, NULL, 1, '4264c1174e983332e9dc7c5c9d7ab3376568eb45ff833a8c6869a9e0e7086c1e', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:11128|check|if (($object->fk_project > 0) && getDolGlobalString(''THIRDPARTY_INCLUDE_PROJECT_THIRDPARY_IN_LINKTO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_LIMIT_SIZE', 'string', NULL, 'core', 'Limits the number of rows returned when building the thirdparty (company) selection dropdown in form_thirdparty().', 'core/class/html.form.class.php:7701: `$limit = getDolGlobalInt(''THIRDPARTY_LIMIT_SIZE'');` then passed into select_company(). Note societe/ajax/ajaxcompanies.php:142 documents a related but separate constant: `$limit = getDolGlobalInt(''SEARCH_LIMIT_AJAX'') ?: 1000; // SEARCH_LIMIT_AJAX is a hidden option that has priority on option THIRDPARTY_LIMIT_SIZE if set.`', 'Setting it to a positive integer caps the number of thirdparty rows fetched/shown by form_thirdparty()''s select_company() call, which helps performance on databases with very many thirdparties; the ajax company search endpoint instead defaults to 1000 unless SEARCH_LIMIT_AJAX overrides it.', 'Integer: max number of thirdparty rows to fetch for the select_company dropdown in form_thirdparty(); comment on the related ajax endpoint notes SEARCH_LIMIT_AJAX (default 1000) takes priority over THIRDPARTY_LIMIT_SIZE there if set.', 1, 0, NULL, 1, '143d376605ef7c630a5e3a9a83bc0918261f84b30470fe7852dbab60b5e740c1', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:7701: $limit = getDolGlobalInt(''THIRDPARTY_LIMIT_SIZE'');", "societe/ajax/ajaxcompanies.php:142: $limit = getDolGlobalInt(''SEARCH_LIMIT_AJAX'') ?: 1000;\t\t// SEARCH_LIMIT_AJAX is a hidden option that has priority on option THIRDPARTY_LIMIT_SIZE if set."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_LOGO_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'societe', 'Enables indexing of an uploaded third-party logo file into Dolibarr''s database file index (ecm_files-like index), which otherwise is skipped.', 'Checked twice in societe/card.php (lines 612 and 785, in the two logo-upload code paths); when set, after moving the uploaded photo/logo file it calls deleteFilesIntoDatabaseIndex() then addFileIntoDatabaseIndex() to register the file in the database index.', 'When set, uploaded third-party logos are recorded in the file database index (enabling features that rely on that index, e.g. external file access/download tracking); when unset, the file is saved to disk but not indexed in the database.', 'Not set/falsy (default): logo file not added to database file index. Truthy: logo file indexed via addFileIntoDatabaseIndex().', 1, 0, NULL, 1, 'fbf10db8d644bc24d9736664c6c6e20722b24152ef30a86378912aec86308def', 'v2', '2026-07-24T07:05:23+00:00', '["societe/card.php:612|check|if (getDolGlobalString(''THIRDPARTY_LOGO_ALLOW_EXTERNAL_DOWNLOAD'')) {", "societe/card.php:614-617|code|deleteFilesIntoDatabaseIndex(...); ... addFileIntoDatabaseIndex(dirname($newfile), basename($newfile), '''', ''uploaded'', 1, $object);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_MAX_NB_PROF_ID', 'string', NULL, 'societe', 'Sets the maximum number of professional ID fields displayed on third-party cards.', 'Read in societe/card.php:1752, :2621, and :3083 into $NBPROFIDMAX with a default of 6. Three occurrences in one file. No admin UI write is present.', 'Changing this value controls the upper bound of professional ID fields rendered on third-party creation and edit forms.', 'Integer; default is 6 when unset.', 1, 0, NULL, 1, '42ba2d0525f7f8b26dd0ed0aaf6747440096b0400af64e6a610a42ce2644e908', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:1752|read|$NBPROFIDMAX = getDolGlobalInt(''THIRDPARTY_MAX_NB_PROF_ID'', 6);", "societe/card.php:2621|read|$NBPROFIDMAX = getDolGlobalInt(''THIRDPARTY_MAX_NB_PROF_ID'', 6);", "societe/card.php:3083|read|$NBPROFIDMAX = getDolGlobalInt(''THIRDPARTY_MAX_NB_PROF_ID'', 6);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_MIN_NB_PROF_ID', 'string', NULL, 'societe', 'Sets the minimum number of professional ID fields displayed on third-party cards.', 'Read in societe/card.php:1751, :2620, and :3083 into $NBPROFIDMIN with a default of 2. Three occurrences in one file. No admin UI write is present.', 'Changing this value controls the lower bound of professional ID fields rendered on third-party creation and edit forms.', 'Integer; default is 2 when unset.', 1, 0, NULL, 1, '2da27a4bd01a8ee5d0e3680a462992258094bfcc194afbbc2ef414a538d446a3', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:1751|read|$NBPROFIDMIN = getDolGlobalInt(''THIRDPARTY_MIN_NB_PROF_ID'', 2);", "societe/card.php:2620|read|$NBPROFIDMIN = getDolGlobalInt(''THIRDPARTY_MIN_NB_PROF_ID'', 2);", "societe/card.php:3082|read|$NBPROFIDMIN = getDolGlobalInt(''THIRDPARTY_MIN_NB_PROF_ID'', 2);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_INVOICE', 'string', NULL, 'compta', 'When enabled, copies extra fields from the linked third-party into newly created invoices.', 'Checked in compta/facture/card.php:4612 during invoice creation and in core/class/commonobject.class.php:9689 in a general extra-field propagation condition.', 'Enabling this constant causes the third-party''s extra fields to be copied to invoices, allowing custom third-party attributes to appear on invoice records.', '0 or unset = extra fields not propagated; truthy = third-party extra fields copied to invoice.', 1, 0, NULL, 1, '6802567b731ed054a4e80322cc216cd8c8629fd9cac7d8a5df730e29d547d920', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/card.php:4612|check|if (getDolGlobalString(''THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_INVOICE'') && !empty($soc->id)) {", "core/class/commonobject.class.php:9689|read|($this->element == ''facture'' && getDolGlobalInt(''THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_INVOICE''))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_ORDER', 'string', NULL, 'commande', 'Propagates thirdparty extrafield values onto orders created for that thirdparty.', 'Checked in commande/card.php:2485 and core/class/commonobject.class.php:9752, the latter restricted to objects whose element is ''commande''.', 'When enabled, extrafield values from the thirdparty are copied onto the order object during order creation/handling.', NULL, 0, 0, NULL, 1, 'f43857b41ba705a7901259ebd795cafdf02063f8eb302c48caa4203c74cbc764', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_ORDER'') && !empty($soc->id)) {", "|| ($this->element == ''commande'' && getDolGlobalInt(''THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_ORDER''))"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_PROPAL', 'string', NULL, 'comm', 'Copies extrafield values from the associated third party (customer) onto a new proposal''s extrafields form.', 'Checked in comm/propal/card.php:2656 right before the extrafields_add.tpl.php include; when set and $socid > 0, $thirdpartytopropagateextrafieldsfrom is set to the $soc object so the template can prefill matching extrafields.', 'Enabling it prefills proposal extrafields from the linked thirdparty''s extrafields at creation time; without it, proposal extrafields start empty.', 'Boolean-like (int via getDolGlobalInt).', 1, 0, NULL, 1, 'fb19e2d69b842e061dc2375824b0860c02e3a4bde4f1335ce099c71eaed1edbb', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:2656: if (getDolGlobalInt(''THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_PROPAL'') && $socid > 0) {", "comm/propal/card.php:2657: $thirdpartytopropagateextrafieldsfrom = $soc;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_SUPPLIER_ORDER', 'string', NULL, 'fourn', 'Copies extrafield values from the linked thirdparty onto the supplier order when creating it, and keeps them forced when the order''s company is changed.', 'In fourn/commande/card.php:2174, if set and the thirdparty exists, extrafields are fetched from the thirdparty and merged into $object->array_options. In core/class/commonobject.class.php:9753, alongside the analogous THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_INVOICE/_TO_ORDER constants, a comment explains: ''Expected behavior: if THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_XXX is set, when we change company, then we use the extrafields of the object (they are filled in the card when constant THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_XXX is set)''.', 'When set, thirdparty extrafields are copied onto the supplier order at creation and re-applied (instead of the new company''s own extrafields) if the company is changed via the changecompany action afterward.', 'Boolean: truthy enables extrafield propagation from thirdparty to order_supplier element.', 1, 0, NULL, 1, '909e819494a68ca32a9745036ed5ea9343284ab7017faca1fa5e4619d9231239', 'v2', '2026-07-24T07:05:23+00:00', '["fourn/commande/card.php:2174|check|if (getDolGlobalString(''THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_SUPPLIER_ORDER'') && !empty($societe->id)) {", "core/class/commonobject.class.php:9753|read|($this->element == ''order_supplier'' && getDolGlobalInt(''THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_SUPPLIER_ORDER''))", "// Expected behavior : if THIRDPARTY_PROPAGATE_EXTRAFIELDS_TO_XXX is set, when we change company, Then we use the extrafields of the object"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_PUBLIC_INTERFACE_TOPIC', 'string', NULL, 'public', 'Custom topic/title text shown in the header of the public online third-party (new company/member) registration page.', 'Passed into htmlPrintOnlineHeader() in public/company/new.php:132 as the topic parameter, alongside the THIRDPARTY_PUBLIC_INTERFACE_IMAGE constant for the header image, when rendering the public ''new company'' form header.', 'Setting it changes the topic/title text displayed at the top of the public new-company registration page; if unset, an empty topic string is used.', 'String: free-text topic/title shown in the public page header.', 1, 0, NULL, 1, 'dd8449ff4ddd9a23cb66368d3ab416374b55e809d5091623937d23104bc4a692', 'v2', '2026-07-24T07:05:23+00:00', '["public/company/new.php:132|read|htmlPrintOnlineHeader($mysoc, $langs, 1, getDolGlobalString(''THIRDPARTY_PUBLIC_INTERFACE_TOPIC''), ''THIRDPARTY_PUBLIC_INTERFACE_IMAGE'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_QUICKSEARCH_ON_FIELDS', 'string', NULL, 'societe', 'Overrides the default fields used for quick-search in the third-party list with a custom semicolon-separated field=label mapping.', 'When set, the third-party list page uses the field definitions from this constant instead of its default search fields. The value is a semicolon-separated string of SQL_field=LabelKey pairs. No admin UI; must be set directly in the database.', 'Changing this value alters which database columns are searched when using the quick-search on the third-party list. Removing it restores the default search field set.', 'Semicolon-separated field=label pairs, e.g. ''s.nom=ThirdPartyName;s.name_alias=AliasNameShort;s.code_client=CustomerCode''', 1, 0, NULL, 1, '303aaf7be4b0a8f183ca8cf8c754571eed61ff46a1d4656e4bde24abc4a01894', 'v2', '2026-04-21T11:16:15+00:00', '["societe/list.php:267  // Personalized search criteria. Example: $conf->global->THIRDPARTY_QUICKSEARCH_ON_FIELDS = ''s.nom=ThirdPartyName;s.name_alias=AliasNameShort;s.code_client=CustomerCode''", "societe/list.php:268|check|if (getDolGlobalString(''THIRDPARTY_QUICKSEARCH_ON_FIELDS'')) {", "societe/list.php:269|read|$fieldstosearchall = dolExplodeIntoArray(getDolGlobalString(''THIRDPARTY_QUICKSEARCH_ON_FIELDS''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_REF_INPUT_SIZE', 'string', NULL, 'expedition', 'Sets the input field size for the customer/supplier reference field shown on multiple document cards.', 'Read via getDolGlobalInt/getDolGlobalString/isset($conf->global->...) across many card pages, including webhook/triggerhistory_card.php:330, fourn/commande/card.php:2433, intracommreport/card.php:328, delivery/card.php:368, contrat/card.php:1517, modulebuilder/template/myobject_card.php:422, and compta/facture/card.php:5385, all using it to size the ''string:<size>'' editfieldval type for the ref field.', 'Changing this value changes the width/size of the editable reference input field on the affected document cards.', NULL, 0, 0, NULL, 1, 'e3d9e2b56feb2e8eb2248d83f06c45b92e8df19b21a55439ed66dc7076cdd6d8', 'v2', '2026-07-24T06:41:12+00:00', '["$morehtmlref .= $form->editfieldval(\"RefCustomer\", ''ref_client'', $object->ref_client, $object, $usercancreate, ''string''.(getDolGlobalInt(''THIRDPARTY_REF_INPUT_SIZE'') ? '':''.getDolGl"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_SEARCH_AUTOFOCUS', 'string', NULL, 'core', 'Adds the HTML ''autofocus'' attribute to the thirdparty (company) search input box.', 'core/class/html.form.class.php:1885: `$out .= ''<input type="text" ... '' . (getDolGlobalString(''THIRDPARTY_SEARCH_AUTOFOCUS'') ? ''autofocus'' : '''') . '' spellcheck="false" />'';`.', 'Setting it to a truthy value makes the browser automatically place keyboard focus in the thirdparty search field when the page loads; no effect otherwise.', 'Truthy = ''autofocus'' attribute added to the search input; 0/unset = no autofocus (default).', 1, 0, NULL, 1, '21dbc23f55108bfbeaff16f97fb1c99e258ca41203051afb9bef627ef819a162', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.form.class.php:1885: (getDolGlobalString(''THIRDPARTY_SEARCH_AUTOFOCUS'') ? ''autofocus'' : '''') . '' spellcheck=\"false\" />'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_SUGGEST_ALSO_ADDRESS_CREATION', 'string', NULL, 'societe', 'When enabled, presents an option to also create an address when creating a new third party.', 'Configured via societe/admin/societe.php and checked in societe/card.php:1208, :1458, :1727, :1867 and public/company/new.php:407. Six occurrences across two files.', 'Enabling this constant adds an address creation prompt to the third-party creation workflow, including the public company registration form.', 'Boolean flag; unset or 0 = address creation not suggested; any truthy value = suggestion shown.', 0, 0, 'societe/admin/societe.php', 1, 'c9e627f295663654138999e46dd726534042b537581077b32f40337d1e38746c', 'v2', '2026-04-21T11:16:15+00:00', '["societe/card.php:1208|check|if (getDolGlobalString(''THIRDPARTY_SUGGEST_ALSO_ADDRESS_CREATION'')) {", "societe/card.php:1727|check|if (isModEnabled(''mailing'') && getDolGlobalString(''THIRDPARTY_SUGGEST_ALSO_ADDRESS_CREATION'')) {", "public/company/new.php:407|check|if (isModEnabled(''mailing'') && getDolGlobalString(''THIRDPARTY_SUGGEST_ALSO_ADDRESS_CREATION'')) {", "societe/admin/societe.php:963|check|if (getDolGlobalString(''THIRDPARTY_SUGGEST_ALSO_ADDRESS_CREATION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_SUGGEST_ALSO_BANK_ACCOUNT', 'string', NULL, 'societe', 'When enabled (and the bank module is active), suggests also adding a bank account when creating/editing a third party.', 'Checked twice in societe/card.php:1619 and societe/card.php:2503, both gated by isModEnabled(''bank'').', 'Enabling it adds a bank-account suggestion step in the third-party card, but only if the bank module is enabled.', NULL, 0, 0, NULL, 1, 'd3cc8e44ea5b6e8e8a01968fbf6a79254ee1479141f059dc5bee02b435a6918a', 'v2', '2026-07-24T06:41:12+00:00', '["if (isModEnabled(''bank'') && getDolGlobalString(''THIRDPARTY_SUGGEST_ALSO_BANK_ACCOUNT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('THIRDPARTY_SUPPLIER_BY_DEFAULT', 'string', NULL, 'societe', 'Makes a newly created third-party default to supplier status when no explicit type is specified in the creation form, provided a supplier module is enabled.', 'In societe/card.php:1073, when supplier_order or supplier_invoice module is enabled and the posted ''type'' is empty (rather than explicitly ''f''), this constant being set causes $object->fournisseur to be set to 1.', 'When set, newly created third parties are flagged as suppliers by default (in addition to any other type) when the creation form does not specify a type; when unset, fournisseur stays unset unless type=''f'' was explicitly posted.', 'Not set/falsy (default): fournisseur flag not set unless type=''f'' explicitly. Truthy: fournisseur=1 by default when type is empty (and supplier module enabled).', 1, 0, NULL, 1, '036ce6001573db5f7d53341ee9d6fa073b63366c574fd7628b00b088313a56b7', 'v2', '2026-07-24T07:05:23+00:00', '["societe/card.php:1073|check|if ((isModEnabled(\"supplier_order\") || isModEnabled(\"supplier_invoice\")) && (GETPOST(\"type\") == ''f'' || (GETPOST(\"type\") == '''' && getDolGlobalString(''THIRDPARTY_SUPPLIER_BY_DEFAULT'')))) {", "societe/card.php:1074|code|$object->fournisseur = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKETS_MESSAGE_FORCE_MAIL', 'string', NULL, 'core', 'Pre-checks the ''send message by email'' checkbox by default when posting a message on a ticket.', 'Read in core/class/html.formticket.class.php:1675 when rendering the ticket message form; the ''send_email'' checkbox is checked if the user already posted send_email=1, otherwise it falls back to this constant''s truthiness to decide the default checked state.', 'Enabling it makes new ticket messages default to being emailed to the requester/contacts unless the user unchecks the box, changing the default notification behavior for ticket message replies.', 'Boolean-like (getDolGlobalInt): truthy pre-checks the send_email checkbox by default.', 1, 0, NULL, 1, '13fa0b5c8b161898d8ed36e128d3e481e9ff7acb85e5af1a067b801cc351917e', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formticket.class.php:1675|read|$checkbox_selected = (GETPOST(''send_email'') == \"1\" ? '' checked'' : (getDolGlobalInt(''TICKETS_MESSAGE_FORCE_MAIL'') ? ''checked'' : ''''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKETS_NO_COMPANY_ON_FORM', 'string', NULL, 'core', 'Removes the third-party (company) selector from the ticket creation form.', 'Read in core/class/html.formticket.class.php:216 in the FormTicket constructor; $this->withcompany is set to 1 only if this constant is NOT set (getDolGlobalInt negated) AND the societe module is enabled, otherwise withcompany is 0.', 'Enabling it hides the company/third-party field on the ticket form regardless of whether the societe (third-party) module is active.', 'Boolean-like: truthy forces withcompany=0 (hides company field) even when the societe module is enabled.', 1, 0, NULL, 1, '8b8268c0f8de5b62b1d6757a283334f3a9b8b8761a3edcdc26dc679c11e1f949', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formticket.class.php:216|read|$this->withcompany = (int) (!getDolGlobalInt(\"TICKETS_NO_COMPANY_ON_FORM\") && isModEnabled(\"societe\"));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_ADDON', 'string', NULL, 'admin', 'Specifies the numbering module class used to generate ticket reference numbers.', 'Written in admin/ticket.php at line 151 and read in ticket/class/ticket.class.php at line 2552 and emailcollector/class/emailcollector.class.php at line 3669, both with ''mod_ticket_simple'' as default.', 'Changing this constant switches the ticket reference numbering scheme. If the specified module does not exist, ticket number generation will fail.', 'String class name of a numbering module (default: ''mod_ticket_simple'')', 0, 0, 'admin/ticket.php|admin/ticket.php', 1, '0fe2f97545d2bf2f74e072cca21d20303b1897776017aa8e10963eac38c934e9', 'v2', '2026-04-21T11:16:15+00:00', '["dolibarr_set_const($db, \"TICKET_ADDON\", $value, ''chaine'', 0, '''', $conf->entity);", "$modele = getDolGlobalString(''TICKET_ADDON'', ''mod_ticket_simple'');", "if (getDolGlobalString(''TICKET_ADDON'') == ''mod_''.$classname) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_ADDON_PDF', 'string', NULL, 'admin', 'Selects the PDF generation module (template) used when producing PDF documents for tickets.', 'Configured via the ticket admin UI (admin/ticket.php:136, :139). The selected module name is compared against available templates (admin/ticket.php:117, :509) and used at document generation time to determine which PDF module to load (ticket/class/ticket.class.php:3479, :3480).', 'Changing this value switches the PDF template applied when generating ticket documents. Deleting it (admin/ticket.php:118) reverts to the default template.', 'String name of a PDF module/template class available for the ticket module.', 0, 0, 'admin/ticket.php|admin/ticket.php|admin/ticket.php|admin/ticket.php|admin/ticket.php', 1, '5e2fe45b8c4ef8bc94311c1c71f28b78ca15adebf0d00794b4f8579e11eee027', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ticket.php:136|write|if (dolibarr_set_const($db, \"TICKET_ADDON_PDF\", $value, ''chaine'', 0, '''', $conf->entity)) {", "ticket/class/ticket.class.php:3479|read|} elseif (getDolGlobalString(''TICKET_ADDON_PDF'')) {", "ticket/class/ticket.class.php:3480|read|$modele = getDolGlobalString(''TICKET_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_ADDON_PDF_ODT_PATH', 'string', NULL, 'core', 'Specifies the directory path(s) to scan for ODT document templates used in ticket PDF generation.', 'Read in core/modules/ticket/doc/doc_generic_ticket_odt.modules.php at line 121, where the value is split on commas and newlines to produce a list of directories to scan for ODT templates. Also displayed in the module info text at line 148.', 'Changing this value redirects the ODT template search to the specified directories; an empty or unset value results in no directories being scanned.', 'Comma- or newline-separated list of directory paths.', 1, 0, NULL, 1, 'c3210588190192fae695196e8f80a967892770a60caaa79453cf44ccc990ca5f', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/ticket/doc/doc_generic_ticket_odt.modules.php:121|read|$listofdir = explode('','', preg_replace(''/[\\r\\n]+/'', '','', trim(getDolGlobalString(''TICKET_ADDON_PDF_ODT_PATH''))));", "core/modules/ticket/doc/doc_generic_ticket_odt.modules.php:148|read|$texte .= getDolGlobalString(''TICKET_ADDON_PDF_ODT_PATH'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_ADD_AUTHOR_AS_CONTACT', 'string', NULL, 'ticket', 'Automatically adds the ticket author as a contact on the ticket, with mode 2 also linking external user contacts.', 'Checked in ticket/class/ticket.class.php at lines 587 and 591. At line 587 the author is added as a contact when the ticket is not created from the public interface. At line 591, when the value equals 2 and the user has a socid and contact_id, the external contact is also linked.', 'Setting to 1 adds internal authors as ticket contacts automatically. Setting to 2 additionally links external user contacts.', '0 or unset = author not added as contact; 1 = author added as contact (backoffice); 2 = author and external user contact added', 1, 0, NULL, 1, 'c867ba23086c0f2fe11a79e2f296a8e6949119f0566eafaa5302498ba358f525', 'v2', '2026-04-21T11:16:15+00:00', '["if (!$error && getDolGlobalString(''TICKET_ADD_AUTHOR_AS_CONTACT'') && empty($this->context[\"createdfrompublicinterface\"])) {", "if (!empty($user->socid) && !empty($user->contact_id) && getDolGlobalInt(''TICKET_ADD_AUTHOR_AS_CONTACT'') == 2) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_ASSIGN_CONTACT_TO_MESSAGE', 'string', NULL, 'admin', 'Enables searching for a contact by email from the public ticket area and assigning it as a contact on the ticket.', 'Configured via admin/ticket_public.php:462 (selectarray UI) and checked in ticket/class/ticket.class.php:1986, gated on public_area and origin_email being set. Documented in code comments at ticket/class/ticket.class.php:1915 and :2798.', 'When set, a contact matching the ticket''s origin email is searched and added as a contact of the ticket when created from the public area.', NULL, 0, 0, 'admin/ticket_public.php', 1, '82173b599543e4a294b789db0b3328ea6bf3fd1f52c4dcc440fddc98734ed499', 'v2', '2026-07-24T06:41:12+00:00', '["* @param\tint<0,1>\t$public_area\t\t0=Default, 1 if we are creating the message from a public area (so we can search contact from email to add it as contact of ticket if TICKET_ASSIGN_CONTACT_TO_MESSAGE is set)", "if ($public_area && !empty($this->origin_email) && getDolGlobalString(''TICKET_ASSIGN_CONTACT_TO_MESSAGE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_AUTO_ASSIGN_USER_CREATE', 'string', NULL, 'admin', 'Controls automatic assignment of the ticket creator as the assigned user when a ticket is created.', 'Configured via the ticket admin UI (admin/ticket.php:162, :613). Checked in ticket/card.php:334: when value is 1, the creator is assigned only if no user is already assigned; when value is 2, the creator is always assigned regardless of existing assignment.', 'Setting to 1 assigns the creator when no assignee exists. Setting to 2 always assigns the creator. Leaving it unset disables automatic assignment.', '0 or unset = no auto-assignment; 1 = assign creator if no assignee; 2 = always assign creator.', 0, 0, 'admin/ticket.php|admin/ticket.php', 1, '34b6fb7a5a13eb61869103b95f6ca2cd734f467066fa0fb8a67de56f139ed622', 'v2', '2026-04-21T11:16:15+00:00', '["ticket/card.php:334|check|if ((empty($fk_user_assign) && getDolGlobalInt(''TICKET_AUTO_ASSIGN_USER_CREATE'') == 1) || (getDolGlobalInt(''TICKET_AUTO_ASSIGN_USER_CREATE'') == 2)) {", "admin/ticket.php:613|read|print ''<input class=\"maxwidth50\" type=\"text\" id=\"TICKET_AUTO_ASSIGN_USER_CREATE\" name=\"TICKET_AUTO_ASSIGN_USER_CREATE\" value=\"''.getDolGlobalInt(''TICKET_AUTO_ASSIGN_USER_CREATE'').''\"", "admin/ticket.php:162|write|$res = dolibarr_set_const($db, ''TICKET_AUTO_ASSIGN_USER_CREATE'', $param_auto_assign, ''chaine'', 0, '''', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_AUTO_READ_WHEN_ASSIGN', 'string', NULL, 'admin', 'Automatically marks a ticket as read when it is assigned to a user.', 'Configured via an admin on/off toggle plus a category selectarray in admin/ticket.php:597-600 (Ticket module setup), and checked in ticket/class/ticket.class.php:1866 to trigger the auto-read behavior on assignment.', 'Enabling it changes ticket read/unread state automatically at assignment time instead of requiring the assignee to open the ticket.', 'Boolean/select value toggled on the Ticket module setup screen; exact option list comes from $arrval in admin/ticket.php (not given in payload).', 0, 0, 'admin/ticket.php', 1, 'd7ebc00c55b038082600486ae80e863f240d6511f1c86b6940fa65747e649b8f', 'v2', '2026-07-24T07:05:23+00:00', '["admin/ticket.php:597: print ajax_constantonoff(''TICKET_AUTO_READ_WHEN_ASSIGN'');", "ticket/class/ticket.class.php:1866: if (getDolGlobalString(''TICKET_AUTO_READ_WHEN_ASSIGN'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_AUTO_READ_WHEN_CREATED_FROM_BACKEND', 'string', NULL, 'admin', 'Controls whether a ticket is automatically marked as read when created from the backend (admin interface).', 'Configured via the ticket admin UI (admin/ticket.php:156, :585). Checked in ticket/card.php:327 to auto-mark a newly created ticket as read when the creating user has ticket management permissions. The admin email collector list also reads this value (admin/emailcollector_list.php:803).', 'Enabling this causes tickets created from the backend to be immediately marked as read by the creating user. Leaving it unset requires manual marking.', 'Truthy value to enable auto-read on backend creation; unset or 0 to disable.', 0, 0, 'admin/ticket.php|admin/emailcollector_list.php|admin/ticket.php', 1, 'cc040ef6ed3adb20407e6d9bd63484490bccadd054b8567ea251d104b0244ffb', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ticket.php:156|write|$res = dolibarr_set_const($db, ''TICKET_AUTO_READ_WHEN_CREATED_FROM_BACKEND'', $param_auto_read, ''chaine'', 0, '''', $conf->entity);", "ticket/card.php:327|check|if (getDolGlobalString(''TICKET_AUTO_READ_WHEN_CREATED_FROM_BACKEND'') && $permissiontomanage) {", "admin/ticket.php:585|read|print $formcategory->selectarray(\"TICKET_AUTO_READ_WHEN_CREATED_FROM_BACKEND\", $arrval, getDolGlobalString(''TICKET_AUTO_READ_WHEN_CREATED_FROM_BACKEND''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_CHECK_NOTIFY_THIRDPARTY_AT_CREATION', 'string', NULL, 'admin', 'Controls the default state of the ''notify thirdparty at ticket creation'' checkbox/behavior.', 'Configured via admin/ticket.php (write at line 85, selectarray UI at line 762). Read by emailcollector/class/emailcollector.class.php:3650 to set notify_tiers_at_create, and referenced (partly commented out) in ticket/card.php:767 and the commented line 799.', 'When set, tickets created (including via email collector) default to notifying the associated thirdparty at creation.', NULL, 0, 0, 'admin/ticket.php|admin/ticket.php', 1, '0ddfaabc4606b3a14129bc7f86f98c474eb098700522a6b1e45d62382ea76120', 'v2', '2026-07-24T06:41:12+00:00', '["$tickettocreate->notify_tiers_at_create = getDolGlobalInt(''TICKET_CHECK_NOTIFY_THIRDPARTY_AT_CREATION'');", "//  $formticket->withnotifytiersatcreate = ($notifyTiers ? 1 : (getDolGlobalString(''TICKET_CHECK_NOTIFY_THIRDPARTY_AT_CREATION'') ? 1 : 0));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_CLIENT_OTHER_TICKET_ONLY_OPEN', 'string', NULL, 'ticket', 'Restricts the ''ticket history'' link on a ticket card to show only open tickets for the same thirdparty.', 'Read in ticket/card.php:1049 when building the link to the thirdparty''s other tickets: appends `&search_fk_statut[]=openall` to the ticket list URL only if the constant is true.', 'When enabled, the ''TicketHistory'' link next to the thirdparty on a ticket card filters to open tickets only instead of showing all tickets for that customer.', 'Boolean (getDolGlobalBool): true/1 restricts the link to open tickets, false/0/unset shows all tickets.', 1, 0, NULL, 1, 'ff225b0ac712a5643e583d9bd114732e4bf81309a20f8749e23f1f13d5a8d9d6', 'v2', '2026-07-24T07:05:23+00:00', '["ticket/card.php:1049: (getDolGlobalBool(''TICKET_CLIENT_OTHER_TICKET_ONLY_OPEN'') ? ''&search_fk_statut[]=openall'' : '''')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_CREATE_THIRD_PARTY_WITH_CONTACT_IF_NOT_EXIST', 'string', NULL, 'public', 'Historically allowed the public ticket creation form to create a new thirdparty and contact automatically when none existed, matched by email.', 'Configured via admin/ticket_public.php (check at line 341, delete at line 183), and checked in public/ticket/ajax/ajax.php:71 and public/ticket/create_ticket.php:100. Code comments explicitly state this option was removed for being a security hole.', 'This option has been removed as a security hole per the code comments; the constant may still be checked in some code paths but is not intended to be used.', NULL, 1, 0, 'admin/ticket_public.php|admin/ticket_public.php', 1, '4064844027f5822ecb3159acee6285d0b9398d844766f3e86481d54fe2ae8430', 'v2', '2026-07-24T06:41:12+00:00', '["*  This option TICKET_CREATE_THIRD_PARTY_WITH_CONTACT_IF_NOT_EXIST has been removed because it is a security hole.", "// Option TICKET_CREATE_THIRD_PARTY_WITH_CONTACT_IF_NOT_EXIST must be set."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_DELAY_BEFORE_FIRST_RESPONSE', 'string', NULL, 'ticket', 'Defines the number of hours within which a first response to a ticket is expected before it is flagged as overdue.', 'Configured via the ticket admin UI (admin/ticket.php:187, :633). In the ticket list, if no response has been sent and the ticket is older than this value in hours, a late warning icon is shown (ticket/list.php:1176, :1179, :1180). Checked together with TICKET_DELAY_SINCE_LAST_RESPONSE for the warning column (ticket/list.php:1171).', 'Setting this to a positive integer causes tickets with no first response older than the configured hours to display a late warning. Leaving it unset disables this first-response delay check.', 'Integer number of hours. Tickets without a first response exceeding this age are flagged as late.', 0, 0, 'admin/ticket.php|admin/ticket.php', 1, '644c4cbd0c9d0cbccce50ce24c3c09ab460fb2cae7d5dda8a9c54639e2927862', 'v2', '2026-04-21T11:16:15+00:00', '["ticket/list.php:1176|check|if (getDolGlobalString(''TICKET_DELAY_BEFORE_FIRST_RESPONSE'') && $date_last_msg_sent == 0) {", "ticket/list.php:1179|check|if ($hour_diff_creation > getDolGlobalInt(''TICKET_DELAY_BEFORE_FIRST_RESPONSE'')) {", "ticket/list.php:1180|read|print \" \" . img_picto($langs->trans(''Late'') . '' : '' . $langs->trans(''TicketsDelayForFirstResponseTooLong'', getDolGlobalString(''TICKET_DELAY_BEFORE_FIRST_RESPONSE'')), ''warning'', ''st"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_DELAY_SINCE_LAST_RESPONSE', 'string', NULL, 'ticket', 'Defines the number of hours after which a ticket with no recent response is flagged as overdue.', 'Configured via the ticket admin UI (admin/ticket.php:193, :643). In the ticket list, if the number of hours since the last message exceeds this value, a late warning icon is displayed (ticket/list.php:1182, :1183). Checked together with TICKET_DELAY_BEFORE_FIRST_RESPONSE to determine whether to show any warning column (ticket/list.php:1171).', 'Setting this to a positive integer triggers a visual late warning on tickets where the last response is older than the configured number of hours. Leaving it unset disables this delay check.', 'Integer number of hours. Tickets exceeding this threshold since last response are flagged as late.', 0, 0, 'admin/ticket.php|admin/ticket.php', 1, '755d06a0c1ab95fad0d4eb933d40e2f9f5c941f16519e838250b4c59b5647b55', 'v2', '2026-04-21T11:16:15+00:00', '["ticket/list.php:1182|read|} elseif (getDolGlobalString(''TICKET_DELAY_SINCE_LAST_RESPONSE'') && $hour_diff > getDolGlobalInt(''TICKET_DELAY_SINCE_LAST_RESPONSE'')) {", "ticket/list.php:1183|read|print \" \" . img_picto($langs->trans(''Late'') . '' : '' . $langs->trans(''TicketsDelayFromLastResponseTooLong'', getDolGlobalString(''TICKET_DELAY_SINCE_LAST_RESPONSE'')), ''warning'');", "admin/ticket.php:643|read|<input type=\"number\" value=\"''.getDolGlobalString(''TICKET_DELAY_SINCE_LAST_RESPONSE'').''\" id=\"delay_between_responses\" name=\"delay_between_responses\" class=\"width50\">"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_DISABLE_ALL_MAILS', 'bool', NULL, 'core', 'Completely suppresses all outgoing emails triggered by the ticket module.', 'Checked in both the ticket email trigger (core/triggers/interface_50_modTicket_TicketEmail.class.php:85, :192) and in ticket/class/ticket.class.php:3176 before sending any ticket-related email. No admin UI write path is present in the payload.', 'Enabling this constant prevents any ticket-related notification email from being sent. Disabling it (or leaving unset) restores normal ticket email delivery.', 'Truthy value to disable all ticket emails; unset or 0 to allow emails.', 1, 0, NULL, 1, '2f200845e9c1e23874cb4d8708c002b68ef9546958943ca3f0447f933a0aa1ba', 'v2', '2026-04-21T11:16:15+00:00', '["core/triggers/interface_50_modTicket_TicketEmail.class.php:85|check|if (!getDolGlobalString(''TICKET_DISABLE_ALL_MAILS'')) {", "core/triggers/interface_50_modTicket_TicketEmail.class.php:192|check|if (!getDolGlobalString(''TICKET_DISABLE_ALL_MAILS'')) {", "ticket/class/ticket.class.php:3176|check|if (getDolGlobalString(''TICKET_DISABLE_ALL_MAILS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_DISABLE_MAIL_AUTOCOPY_TO', 'bool', NULL, 'core', 'Suppresses the MAIN_MAIL_AUTOCOPY_TO BCC behaviour specifically for ticket-related outgoing emails.', 'Checked in both the ticket email trigger (core/triggers/interface_50_modTicket_TicketEmail.class.php:93, :100, :197, :415, :426, :505) and in ticket/class/ticket.class.php:3220, :3283 to temporarily disable or restore MAIN_MAIL_AUTOCOPY_TO during ticket email sending. No admin UI write path is present in the payload.', 'Enabling this prevents MAIN_MAIL_AUTOCOPY_TO addresses from being BCC''d on ticket emails. Disabling it (or leaving unset) allows the global autocopy behaviour to apply to ticket emails.', 'Truthy value to suppress autocopy for ticket emails; unset or 0 to allow global autocopy.', 1, 0, NULL, 1, 'c55edf763a5561e4e4fd5777e289ed0470590965dce53aa1442762d4ca75610d', 'v2', '2026-04-21T11:16:15+00:00', '["ticket/class/ticket.class.php:3220|check|if (getDolGlobalString(''TICKET_DISABLE_MAIL_AUTOCOPY_TO'')) {", "ticket/class/ticket.class.php:3283|check|if (getDolGlobalString(''TICKET_DISABLE_MAIL_AUTOCOPY_TO'')) {", "core/triggers/interface_50_modTicket_TicketEmail.class.php:93|check|if (getDolGlobalString(''TICKET_DISABLE_MAIL_AUTOCOPY_TO'')) {", "core/triggers/interface_50_modTicket_TicketEmail.class.php:197|check|if (!getDolGlobalString(''TICKET_DISABLE_MAIL_AUTOCOPY_TO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_DISALLOW_CLASSIFICATION_MODIFICATION_EVEN_IF_CLOSED', 'bool', NULL, 'ticket', 'Blocks editing a ticket''s classification/properties once the ticket has reached STATUS_NEED_MORE_INFO or beyond, unless disabled.', 'Used in ticket/card.php:1250 to gate the edit-properties pencil icon: the edit link is shown only if `$object->status < STATUS_NEED_MORE_INFO || !getDolGlobalInt(''TICKET_DISALLOW_CLASSIFICATION_MODIFICATION_EVEN_IF_CLOSED'')`.', 'When set (truthy), tickets that are past STATUS_NEED_MORE_INFO (e.g. closed) can no longer have their classification/properties (type, category, severity...) edited via the UI edit link.', 'Boolean (getDolGlobalInt): 1/true = classification can no longer be modified once ticket reached STATUS_NEED_MORE_INFO or later; 0/unset = classification remains editable regardless of status.', 1, 0, NULL, 1, 'a0d34d65d44626687b5ee22434ce4c5e899038170bd2411d48cb3f66122c8240', 'v2', '2026-07-24T07:05:23+00:00', '["ticket/card.php:1250: ($object->status < $object::STATUS_NEED_MORE_INFO || !getDolGlobalInt(''TICKET_DISALLOW_CLASSIFICATION_MODIF..."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_DONOTSEARCH_ANYWHERE', 'string', NULL, 'core', 'When enabled, restricts ticket search queries to prefix-only matches, allowing database index use instead of full-text substring search.', 'Read at core/class/html.form.class.php:8433 and :8658. When truthy, $prefix is set to '''' (no leading wildcard), enabling index usage; when falsy, $prefix is ''%'' (leading wildcard, full substring search). The inline comment explicitly states ''Can use index if TICKET_DONOTSEARCH_ANYWHERE is on''.', 'Enabling improves search performance on large ticket tables by using indexed prefix queries. Disabling allows searching anywhere in the string but prevents index use.', 'Truthy = prefix-only search (index-friendly); empty/unset = substring search with leading wildcard.', 1, 0, NULL, 1, 'f39506e1a9b5c2d6874c894405f83602ff539eaf44b5641933628477a72f106c', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:8433|read|$prefix = getDolGlobalString(''TICKET_DONOTSEARCH_ANYWHERE'') ? '''' : ''%''; // Can use index if TICKET_DONOTSEARCH_ANYWHERE is on", "core/class/html.form.class.php:8658|read|$prefix = !getDolGlobalString(''TICKET_DONOTSEARCH_ANYWHERE'') ? ''%'' : ''''; // Can use index if PRODUCT_DONOTSEARCH_ANYWHERE is on"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_EMAIL_MUST_EXISTS', 'string', NULL, 'admin', 'Requires that the submitter''s email address corresponds to an existing contact when creating a public ticket.', 'When set, public/ticket/create_ticket.php:226 rejects ticket creation if the contact ID is negative or the contact has no linked company. admin/ticket_public.php:189 deletes the constant to disable this requirement. Also gates document access in document.php:301.', 'Enabling this enforces that only known contacts with linked companies can submit tickets via the public form; disabling it allows anyone to submit.', 'Non-zero integer value enforces the email-must-exist check; absent or zero disables it.', 0, 0, 'admin/ticket_public.php|admin/ticket_public.php', 1, '4e582e83502c00d5cdfb48a273e5edd07e1d7298e654928ef602591821ea81a6', 'v2', '2026-04-21T13:50:40+00:00', '["public/ticket/create_ticket.php:226|check|if (getDolGlobalInt(''TICKET_EMAIL_MUST_EXISTS'') && ($cid < 0 || empty($contacts[$cid]->socid))) {", "admin/ticket_public.php:189|write|$res = dolibarr_del_const($db, ''TICKET_EMAIL_MUST_EXISTS'', $conf->entity);", "document.php:301|read|} elseif ($modulepart == ''ticket'' && !getDolGlobalString(''TICKET_EMAIL_MUST_EXISTS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_ENABLE_PUBLIC_INTERFACE', 'bool', NULL, 'admin', 'Controls whether the public-facing ticket interface is accessible to unauthenticated users.', 'Configured via the public ticket admin UI (admin/ticket_public.php). When disabled, access to the public interface is blocked (public/ticket/index.php:84; admin/ticket_public.php:247). When enabled, ticket URLs for the public interface are generated (ticket/class/ticket.class.php:3061).', 'Enabling this constant opens the ticket interface to the public. Disabling it prevents unauthenticated users from accessing or submitting tickets through the public URL.', '1 = enabled, 0 = disabled.', 0, 0, 'admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php', 1, 'f3a01a9102115ce931b5662bbb43dac64bc5a29c968bda5abd9d616697e72021', 'v2', '2026-04-21T11:16:15+00:00', '["public/ticket/index.php:84|check|if (!getDolGlobalString(''TICKET_ENABLE_PUBLIC_INTERFACE'')) {", "admin/ticket_public.php:247|check|if (!getDolGlobalInt(''TICKET_ENABLE_PUBLIC_INTERFACE'')) {", "ticket/class/ticket.class.php:3061|read|$url_public_ticket = (getDolGlobalInt(''TICKET_ENABLE_PUBLIC_INTERFACE'') ?"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_ENABLE_RESOLUTION', 'bool', NULL, 'ticket', 'Enables the resolution field and the resolution dictionary for the ticket module.', 'Read in ticket/class/ticket.class.php at line 319 as the ''enabled'' condition for the resolution field, and in core/modules/modTicket.class.php at line 204 to conditionally load the resolution dictionary. A comment states: ''Dictionary of ticket resolutions (apparently unused except if TICKET_ENABLE_RESOLUTION is on)''.', 'When disabled, the resolution field is hidden on ticket forms and the resolution dictionary is not loaded. Enabling it activates both.', '0 or unset = resolution field disabled; 1 = resolution field and dictionary enabled', 1, 0, NULL, 1, '6b40be5161513febd5a8942a904b04ffb76c56905ede1d238e365b88d620e21d', 'v2', '2026-04-21T11:16:15+00:00', '["// Dictionary of ticket resolutions (apparently unused except if TICKET_ENABLE_RESOLUTION is on)", "''enabled'' => ''getDolGlobalString(\"TICKET_ENABLE_RESOLUTION\")''", "''cond'' => isModEnabled(''ticket'') && getDolGlobalString(''TICKET_ENABLE_RESOLUTION''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_INCLUDE_LINK_TO_PUBLIC_INTERFACE_IN_MESSAGE', 'string', NULL, 'ticket', 'Adds a clickable link to the ticket''s public tracking page inside outgoing ticket notification emails.', 'Used in ticket/class/ticket.class.php:3131: `if (getDolGlobalInt(''TICKET_INCLUDE_LINK_TO_PUBLIC_INTERFACE_IN_MESSAGE'')) { $message .= ''<br>'' . $langs->trans(''TicketNewEmailBodyInfosTrackUrlCustomer'') . '' : <a href="'' . $url_public_ticket . ''">'' . $object->track_id . ''</a><br>''; }`, where $url_public_ticket is built from TICKET_ENABLE_PUBLIC_INTERFACE / TICKET_URL_PUBLIC_INTERFACE just above.', 'When enabled, notification emails sent for a ticket include a hyperlink to the public tracking page (or internal ticket card if public interface is disabled) using the track_id; when disabled, that link line is omitted from the email body.', 'Boolean (getDolGlobalInt): 1/true adds the tracking link line to the email; 0/unset omits it.', 1, 0, NULL, 1, 'dc3345a6a271684244a21c1a336f5b7323831026367d06e76816e91b2beac369', 'v2', '2026-07-24T07:05:23+00:00', '["ticket/class/ticket.class.php:3131: if (getDolGlobalInt(''TICKET_INCLUDE_LINK_TO_PUBLIC_INTERFACE_IN_MESSAGE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_INCLUDE_SUSPENDED_STATUS', 'string', NULL, 'ticket', 'Controls whether suspended-status tickets are included in ticket list queries and counts.', 'Checked in ticket/class/ticket.class.php:361, ticket/class/actions_ticket.class.php:512, webportal/class/webportalticket.class.php:58, and ticket/index.php:246. When not set, suspended tickets are excluded from queries; when set, ticket/index.php:246 adds suspended tickets to counts.', 'When enabled, suspended tickets appear in lists and statistics; when disabled (default), they are filtered out.', 'Truthy (non-empty) to include suspended tickets; empty/unset to exclude them.', 1, 0, NULL, 1, '19f45005128e49c0246c5b3cbccc788766136ef4fac7cddd53eb790945c03f16', 'v2', '2026-04-21T11:16:15+00:00', '["ticket/class/actions_ticket.class.php:512|check|if (!getDolGlobalString(''TICKET_INCLUDE_SUSPENDED_STATUS'')) {", "webportal/class/webportalticket.class.php:58|check|if (!getDolGlobalString(''TICKET_INCLUDE_SUSPENDED_STATUS'')) {", "ticket/class/ticket.class.php:361|check|if (!getDolGlobalString(''TICKET_INCLUDE_SUSPENDED_STATUS'')) {", "ticket/index.php:246|check|if (getDolGlobalString(''TICKET_INCLUDE_SUSPENDED_STATUS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_LIMIT_VIEW_ASSIGNED_ONLY', 'string', NULL, 'ticket', 'Restricts internal users from viewing tickets that are not assigned to them, unless they have ticket management rights.', 'Configured via admin/ticket.php:175 and checked across 15 occurrences in ticket module pages (document.php:104, messaging.php:118, agenda.php:117, contact.php:94, index.php:187, card.php:807) with the pattern: getDolGlobalString(''TICKET_LIMIT_VIEW_ASSIGNED_ONLY'') && $object->fk_user_assign != $user->id && !$permissiontomanage.', 'Enabling this hides unassigned tickets from regular internal users; users with ticket management permission are not affected.', '0 or unset = all internal users can view all tickets; 1 = internal users can only view tickets assigned to them (unless they have management rights).', 0, 0, 'admin/ticket.php', 1, '8a1a2883049bf72c98fe93d45ff14c789ae751aaf2c91d461b5c6730ae1a28a2', 'v2', '2026-04-21T11:16:15+00:00', '["admin/ticket.php:175|write|$res = dolibarr_set_const($db, ''TICKET_LIMIT_VIEW_ASSIGNED_ONLY'', $param_limit_view, ''chaine'', 0, '''', $conf->entity);", "ticket/document.php:104|check|if (!$user->socid && getDolGlobalString(''TICKET_LIMIT_VIEW_ASSIGNED_ONLY'') && $object->fk_user_assign != $user->id && !$permissiontomanage) {", "ticket/messaging.php:118|check|if (!$user->socid && (getDolGlobalString(''TICKET_LIMIT_VIEW_ASSIGNED_ONLY'') && $object->fk_user_assign != $user->id) && !$permissiontomanage) {", "ticket/index.php:187|check|if (getDolGlobalString(''TICKET_LIMIT_VIEW_ASSIGNED_ONLY'') && !$permissiontomanage) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_LINK_TO_CONTRACT_WITH_HARDLINK', 'string', NULL, 'core', 'Controls whether tickets are linked to contracts using a hard link relationship.', 'Checked in ticket/card.php:1076, core/lib/contract.lib.php:58 (also gated on the ticket module being enabled), and core/class/html.formticket.class.php:787.', 'When enabled, the ticket-to-contract association uses a hard link mechanism rather than the default linking behavior.', NULL, 0, 0, NULL, 1, '07cd32395c7a50880426c95ffa95811469b003ec8547bb6b352a60f4273f915f', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''TICKET_LINK_TO_CONTRACT_WITH_HARDLINK'')) {", "if (isModEnabled(''ticket'') && getDolGlobalString(''TICKET_LINK_TO_CONTRACT_WITH_HARDLINK'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_MAX_VISIBLE_PHOTO', 'string', NULL, 'core', 'Sets the maximum number of photos shown in the ticket photo block on the object card.', 'In core/lib/functions.lib.php:3479, used as `getDolGlobalInt(''TICKET_MAX_VISIBLE_PHOTO'', 2)` to cap photos passed to show_photos() for a ticket; default is 2 (lower than the other object types), forced to 1 on phone layout.', 'Increasing/decreasing the value changes how many ticket photos are displayed at once in the card header photo block.', 'Integer count of photos to display; default 2 if unset.', 1, 0, NULL, 1, '1ce18e855750793e7011f0c239ec017c6fb2bf30f6b360130ca834c1be27732e', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3479|read|$maxvisiblephotos = getDolGlobalInt(''TICKET_MAX_VISIBLE_PHOTO'', 2);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_MESSAGE_MAIL_INTRO', 'string', NULL, 'admin', 'Sets a custom introduction text prepended to ticket notification emails.', 'Configured via admin/ticket.php (read with default '''' at line 786, write at lines 248 and 250). Used in ticket/class/ticket.class.php:2939 and :2996 with a fallback to the translated ''TicketMessageMailIntroText'', and checked in core/class/html.formticket.class.php:1905 and :1909.', 'When set, the custom intro text replaces the default translated intro text in ticket notification emails; a GETPOST value for ''mail_intro'' can override it at send time.', NULL, 0, 0, 'admin/ticket.php|admin/ticket.php|admin/ticket.php', 1, '90a29bd11c3b4bbdf765518db381c1d962e824f0ec691e4af15ff88960bebe3f', 'v2', '2026-07-24T06:41:12+00:00', '["$mail_intro = getDolGlobalString(''TICKET_MESSAGE_MAIL_INTRO'', '''');", "$message = getDolGlobalString(''TICKET_MESSAGE_MAIL_INTRO'', $langs->trans(''TicketMessageMailIntroText''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_MESSAGE_MAIL_NEW', 'string', NULL, 'admin', 'Stores the custom email body template sent to users when a new ticket is created.', 'Written via admin/ticket_public.php at lines 131 and 133; read back at line 498. Used in public/ticket/create_ticket.php:458 to compose the notification email body, falling back to ''TicketNewEmailBody'' translation if empty.', 'Changing this modifies the email body sent upon new ticket creation; removing it reverts to the default translated template.', 'HTML string; defaults to the translated value of ''TicketNewEmailBody'' if not set.', 0, 0, 'admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php', 1, 'd90384e81f2c17aec7c0922149bbd418a7675c011f7ea5ac0d902fe3ebffa927', 'v2', '2026-04-21T13:50:40+00:00', '["admin/ticket_public.php:131|write|$res = dolibarr_set_const($db, ''TICKET_MESSAGE_MAIL_NEW'', $mail_new_ticket, ''chaine'', 0, '''', $conf->entity);", "admin/ticket_public.php:498|read|$mail_mesg_new = getDolGlobalString(\"TICKET_MESSAGE_MAIL_NEW\", $langs->trans(''TicketNewEmailBody''));", "public/ticket/create_ticket.php:458|read|$message  = (getDolGlobalString(''TICKET_MESSAGE_MAIL_NEW'') !== '''' ? getDolGlobalString(''TICKET_MESSAGE_MAIL_NEW'') : $langs->transnoentities(''TicketNewEmailBody'')).''<br><br>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_MESSAGE_MAIL_SIGNATURE', 'string', NULL, 'core', 'Defines the email signature appended to ticket message emails sent from the system.', 'Configured via the ticket admin UI (admin/ticket.php). The value is read into $mail_signature for use in outgoing ticket emails (core/class/html.formticket.class.php:1898; ticket/class/ticket.class.php:2932). Presence of this constant is checked alongside TICKET_MESSAGE_MAIL_INTRO to determine whether to include signature/intro blocks (core/class/html.formticket.class.php:1864, :1872).', 'Setting this value causes ticket message emails to include the specified signature text. Clearing it removes the signature from outgoing ticket emails.', 'Any string (email signature text). Empty string disables.', 0, 0, 'admin/ticket.php|admin/ticket.php|admin/ticket.php', 1, '653fcdfaae447ecbe77771fe42899023423fa8c1c5c4dbc26cb22433af5e4f99', 'v2', '2026-04-21T11:16:15+00:00', '["core/class/html.formticket.class.php:1897  /*if ($user->rights->ticket->write && !$user->socid && !empty($conf->global->TICKET_MESSAGE_MAIL_SIGNATURE)) {", "core/class/html.formticket.class.php:1864|check|if (getDolGlobalString(''TICKET_MESSAGE_MAIL_INTRO'') || getDolGlobalString(''TICKET_MESSAGE_MAIL_SIGNATURE'')) {", "ticket/class/ticket.class.php:2932|read|$message_signature = GETPOST(''mail_signature'') ? GETPOST(''mail_signature'') : getDolGlobalString(''TICKET_MESSAGE_MAIL_SIGNATURE'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_NODISPLAYIFNOPHOTO', 'string', NULL, 'core', 'Suppresses the ''no photo'' placeholder image on the ticket card when the ticket has no photo.', 'In core/lib/functions.lib.php:3493, if the ticket has no photo to show and this constant is set, an empty div is used instead of rendering the generic no-photo picto.', 'Enabling it hides the generic ''no photo'' placeholder for tickets without photos, showing an empty block instead.', 'Boolean-like: any truthy value suppresses the no-photo placeholder.', 1, 0, NULL, 1, '0ddb450abcd596256fd2ad299df02215e19be51143301facb0144c05207a3ebb', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/functions.lib.php:3493|check|if (getDolGlobalString(''TICKET_NODISPLAYIFNOPHOTO'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_NOTIFICATION_ALSO_MAIN_ADDRESS', 'string', NULL, 'admin', 'Adds the thirdparty''s main email address as an additional recipient for ticket notifications.', 'Configured via admin/ticket_public.php (write at lines 161 and 172, selectarray UI at line 543). Checked in ticket/class/ticket.class.php at lines 2919, 3038, and 3156, and core/class/html.formticket.class.php:1778, each guarding against duplicating an address already in TICKET_NOTIFICATION_EMAIL_TO.', 'When enabled, ticket notification emails also include the thirdparty''s main address, unless that address already matches TICKET_NOTIFICATION_EMAIL_TO.', NULL, 0, 0, 'admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php', 1, 'aa9491c061d502befad74a4039f3b5999923bd3dea74d8b1696883cd01e4ef9f', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''TICKET_NOTIFICATION_ALSO_MAIN_ADDRESS'') && !array_key_exists(getDolGlobalString(''TICKET_NOTIFICATION_EMAIL_TO''), $sendto)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_NOTIFICATION_EMAIL_FROM', 'string', NULL, 'ticket', 'Sets the From email address used for ticket notification emails.', 'Configured via admin/ticket.php (write at lines 203 and 205, the latter defaulting to MAIN_MAIL_EMAIL_FROM; input field at line 691). Read in public/ticket/create_ticket.php:598 and :470, ticket/class/ticket.class.php:3177, and core/class/html.formticket.class.php:1726.', 'When set, ticket notification emails are sent from this address instead of falling back to MAIN_MAIL_EMAIL_FROM.', NULL, 0, 0, 'admin/ticket.php|admin/ticket.php|admin/ticket.php', 1, '8661f8ab7dbb757beb8d82b7a20033add2178a597378e4b70a9fffb4be5a0f79', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, ''TICKET_NOTIFICATION_EMAIL_FROM'', getDolGlobalString(''MAIN_MAIL_EMAIL_FROM''), ''chaine'', 0, $notification_email_description, $conf->entity);", "* @param int<0,1>\t\t$send_internal_cc \tReceive a copy on internal email at getDolGlobalString(''TICKET_NOTIFICATION_EMAIL_FROM'')"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_NOTIFICATION_EMAIL_REPLYTO', 'string', NULL, 'admin', 'Sets the Reply-To email address used for ticket notification emails.', 'Configured via admin/ticket.php (write at lines 214 and 216, the latter defaulting to MAIN_MAIL_EMAIL_FROM; input field at line 701). Read in ticket/class/ticket.class.php at lines 2970, 3059, and 3179, and core/class/html.formticket.class.php:1727.', 'When set, ticket notification emails use this address as Reply-To instead of falling back to MAIN_MAIL_EMAIL_FROM.', NULL, 0, 0, 'admin/ticket.php|admin/ticket.php|admin/ticket.php', 1, '72f932a06acfdd87847a85290bcc106230c0c5b05d3c07fe99b7618389039412', 'v2', '2026-07-24T06:41:12+00:00', '["$res = dolibarr_set_const($db, ''TICKET_NOTIFICATION_EMAIL_REPLYTO'', getDolGlobalString(''MAIN_MAIL_EMAIL_FROM''), ''chaine'', 0, $notification_email_replyto_description, $conf->entity)", "$replyto = getDolGlobalString(''TICKET_NOTIFICATION_EMAIL_REPLYTO'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_NOTIFICATION_EMAIL_TEMPLATE', 'string', NULL, 'admin', 'Selects the email template used for ticket notification emails.', 'Written and read in admin/ticket.php. The value is selected from an array of available message/template names via a dropdown in the ticket admin UI.', 'Changing this value switches the email template applied to all outgoing ticket notifications.', 'A string key identifying a mail template from the available templates list; empty string means none selected.', 0, 0, 'admin/ticket.php|admin/ticket.php|admin/ticket.php', 1, 'c750963aedd039a9f97e82465c0fc84ec8d919ffaf50fa46d9df3962e09fa56b', 'v2', '2026-04-21T13:29:58+00:00', '["admin/ticket.php:237|write|$res = dolibarr_set_const($db, ''TICKET_NOTIFICATION_EMAIL_TEMPLATE'', $notification_email_template, ''chaine'', 0, $notification_email_template_description, $conf->entity);", "admin/ticket.php:749|read|print $form->selectarray(''TICKET_NOTIFICATION_EMAIL_TEMPLATE'', $arrayofmessagename, getDolGlobalString(''TICKET_NOTIFICATION_EMAIL_TEMPLATE''), ''None'', 0, 0, '''', 0, 0, 0, '''', '''', 1);", "admin/ticket.php:239|write|$res = dolibarr_set_const($db, ''TICKET_NOTIFICATION_EMAIL_TEMPLATE'', '''', ''chaine'', 0, $notification_email_template_description, $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_NOTIFICATION_EMAIL_TO', 'string', NULL, 'ticket', 'Specifies the primary email address to which ticket-event notifications are sent.', 'Written in admin/ticket.php at lines 226 and 228. Read and checked in ticket/class/ticket.class.php at lines 2865-2866, 2976-2977, and 3089, where it is added to the sendto list when TICKET_NOTIFICATION_ALSO_MAIN_ADDRESS is also set. A comment in public/ticket/create_ticket.php line 490 states: ''Send email to TICKET_NOTIFICATION_EMAIL_TO''.', 'When set, this address receives ticket notifications. It works together with TICKET_NOTIFICATION_ALSO_MAIN_ADDRESS to control whether the address is included in all notification sends.', 'Email address string; empty or unset = no main notification recipient', 0, 0, 'admin/ticket.php|admin/ticket.php|admin/ticket.php', 1, '1ad48cb241011a69523be23a594df78296aade5012fc0d79b3cd9c2ae826c50b', 'v2', '2026-04-21T11:16:15+00:00', '["// Send email to TICKET_NOTIFICATION_EMAIL_TO", "$res = dolibarr_set_const($db, ''TICKET_NOTIFICATION_EMAIL_TO'', $notification_email_to, ''chaine'', 0, $notification_email_to_description, $conf->entity);", "if (getDolGlobalString(''TICKET_NOTIFICATION_EMAIL_TO'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_NOTIFY_AT_CLOSING', 'string', NULL, 'admin', 'Controls the default choice for notifying stakeholders when a ticket is closed.', 'Configured via admin/ticket.php (write at line 168, selectarray UI at line 777). Checked in core/triggers/interface_50_modTicket_TicketEmail.class.php:287 (requiring the ticket to have a linked thirdparty and no linked contacts), and used to set default selections in ticket/card.php:837 and ticket/list.php:816.', 'When enabled, the ticket-closing email trigger notifies the linked thirdparty when there are no linked contacts on the ticket.', NULL, 0, 0, 'admin/ticket.php|admin/ticket.php', 1, 'baa0eff9c2728d920e0c3b02162073774242098d5e05b4234f182c0e9c79653b', 'v2', '2026-07-24T06:41:12+00:00', '["if (empty($linked_contacts) && getDolGlobalString(''TICKET_NOTIFY_AT_CLOSING'') && !empty($object->fk_soc)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_NOTIFY_CUSTOMER_TICKET_ASSIGNED', 'string', NULL, 'core', 'Enables sending a notification email to the customer when their ticket is assigned to a user for the first time.', 'In core/triggers/interface_50_modTicket_TicketEmail.class.php:111, when set and the ticket previously had no assigned user (empty($object->oldcopy->fk_user_assign)), an email using the TicketAssignedCustomerEmail/TicketAssignedCustomerBody templates is sent to external contacts linked to the ticket.', 'Enabling it causes customers to receive an email (''ticket has been taken in charge'') the first time their ticket gets an assignee; leaving it unset means the customer is not notified of assignment.', 'boolean: 1/true sends the ticket-assigned email to the customer on first assignment; unset/0 = no such email.', 0, 0, NULL, 1, '5a18dd62fec8ad7cb1bf61ef348bfa4a298df6e99e985724b2eb1d3e1ab915a5', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_50_modTicket_TicketEmail.class.php:110-111: // Send an email to the Customer to inform him that his ticket has been taken in charge.\\nif (getDolGlobalString(''TICKET_NOTIFY_CUSTOMER_TICKET_ASSIGNED'') && empty($object->oldcopy->fk_user_assign)) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_PRODUCT_CATEGORY', 'string', NULL, 'admin', 'Selects the product category used by the ticket-to-contract workflow to determine which contract lines are eligible for linking.', 'Configured via admin/workflow.php (write at line 252, selectProductCategory UI at line 386). Used in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:598 (combined with WORKFLOW_TICKET_LINK_CONTRACT and module checks) and :606 to filter getListOfContracts by this category.', 'Changing this value changes which product category is used to filter contract lines when the ticket-contract linking workflow runs.', NULL, 0, 0, 'admin/workflow.php|admin/workflow.php', 1, '4a60ada0ec8385e0b7251aa0940e6eaa8428fba46f83868f60582e7d4753a71f', 'v2', '2026-07-24T06:41:12+00:00', '["if (isModEnabled(''contract'') && isModEnabled(''ticket'') && isModEnabled(''workflow'') && getDolGlobalString(''WORKFLOW_TICKET_LINK_CONTRACT'') && getDolGlobalString(''TICKET_PRODUCT_CATE"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_PUBLIC_DISPLAY_EXTERNAL_CONTRIBUTORS', 'string', NULL, 'public', 'Shows the list of external contributors (contacts) on the public ticket view page.', 'Checked in public/ticket/view.php:353; when true, the public ticket page prints a row listing external contributors fetched via $object->dao->liste_contact(-1, ''external'').', 'Enabling it exposes the names of external contacts linked to the ticket to anyone with the public ticket view link.', 'Boolean-like: any truthy value enables display of external contributors on the public ticket page.', 1, 0, NULL, 1, 'd08a19a71328d8c07e19107901f81d0fdff0cc281e70ed132978d28f63b40804', 'v2', '2026-07-24T07:05:23+00:00', '["public/ticket/view.php:353: if (getDolGlobalInt(''TICKET_PUBLIC_DISPLAY_EXTERNAL_CONTRIBUTORS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_PUBLIC_INTERFACE_TOPIC', 'string', NULL, 'admin', 'Sets the topic/title text displayed on the public ticket interface page.', 'Configured via admin/ticket_public.php (written at lines 98 and 100, including a blank-value write path). The value is read at admin/ticket_public.php:414 to populate the interface URL/topic display.', 'Changing this value alters the topic label shown on the public-facing ticket submission page. Setting it to empty removes the custom topic.', 'Any string value used as the topic label; empty string clears the topic.', 0, 0, 'admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php', 1, '07f802945cab0405a465fc25b13dfe4a7d06b5a7920c5c57ba0a162a926e494b', 'v2', '2026-04-21T13:29:58+00:00', '["admin/ticket_public.php:414|read|$url_interface = getDolGlobalString(\"TICKET_PUBLIC_INTERFACE_TOPIC\");", "admin/ticket_public.php:98|write|$res = dolibarr_set_const($db, ''TICKET_PUBLIC_INTERFACE_TOPIC'', $topic_interface, ''chaine'', 0, '''', $conf->entity);", "admin/ticket_public.php:100|write|$res = dolibarr_set_const($db, ''TICKET_PUBLIC_INTERFACE_TOPIC'', '''', ''chaine'', 0, '''', $conf->entity);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_DEFAULT_EMAIL', 'string', NULL, 'admin', 'Sets a default email address notified when a new message is posted on a ticket from the public area.', 'Configured via admin/ticket_public.php (write at line 152, input field at line 529). Checked and read in ticket/class/ticket.class.php:2911-2912, where it is added to the notification recipients array.', 'When set, this address is added as a notification recipient whenever a new public ticket message is created.', NULL, 0, 0, 'admin/ticket_public.php|admin/ticket_public.php', 1, 'af74bee5d4fcaa0363e7106f97969376202336d0fbf4027db156e0a871ed21ee', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_DEFAULT_EMAIL'')) {", "$sendto[getDolGlobalString(''TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_DEFAULT_EMAIL'')] = getDolGlobalString(''TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_DEFAULT_EMAIL'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_ENABLED', 'bool', NULL, 'admin', 'Enables sending email notifications to assigned users when a new message is added to a ticket from the public ticket area.', 'Admin on/off toggle rendered in admin/ticket_public.php:520 (`print $form->selectarray("TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_ENABLED", $arrval, getDolGlobalString(...))`) and checked in ticket/class/ticket.class.php:2877 (`if (getDolGlobalString(''TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_ENABLED'')) {`) inside the public-area message handling block.', 'When enabled, adding a message to a ticket from the public interface triggers emails to the ticket''s assigned internal contacts; when disabled, no such notification is sent.', '0 = No, 1 = Yes (rendered via a Yes/No select or ajax on/off toggle in the admin UI).', 0, 0, 'admin/ticket_public.php', 1, '9c8d1f3a9e569bba76ea5548bce8634c26763d6ed73af81b4eb6fbd1b9ae5eef', 'v2', '2026-07-24T07:05:23+00:00', '["admin/ticket_public.php:520|read|print $form->selectarray(\"TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_ENABLED\", $arrval, getDolGlobalString(\"TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_ENABLED\"));", "ticket/class/ticket.class.php:2877|check|if (getDolGlobalString(''TICKET_PUBLIC_NOTIFICATION_NEW_MESSAGE_ENABLED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_PUBLIC_SELECT_EXTERNAL_CONTRIBUTORS', 'string', NULL, 'public', 'Shows a form on the public ticket view page allowing an external contact to be added as a contributor to the ticket.', 'Checked in public/ticket/view.php:366, guarded also by a non-empty $object->dao->fk_soc; when true, a form with a contact selector and an ''add_contact'' action is printed on the public ticket page.', 'Enabling it lets anonymous/public visitors of a ticket linked to a company add new external contributors via a public form.', 'Boolean-like: any truthy value enables the add-contributor form on the public ticket page (requires the ticket to have a linked third party).', 1, 0, NULL, 1, 'b75807dff33e9dfab85cc714296e3d87fd8af791095fb5ecab3c2439c46d14e0', 'v2', '2026-07-24T07:05:23+00:00', '["public/ticket/view.php:366: if (getDolGlobalInt(''TICKET_PUBLIC_SELECT_EXTERNAL_CONTRIBUTORS'') && !empty($object->dao->fk_soc)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_PUBLIC_TEXT_HELP_MESSAGE', 'string', NULL, 'admin', 'Stores the help message text displayed on the public ticket submission form.', 'Managed via the admin UI at admin/ticket_public.php (written via dolibarr_set_const, reset to the default translation on reset action). Displayed in core/class/html.formticket.class.php:565 inside a warning div. Defaults to the translation of ''TicketPublicPleaseBeAccuratelyDescribe'' when unset.', 'Setting a custom value replaces the default instructional text shown to users on the public ticket form. Clearing it restores the default translated message.', 'Any non-empty string = custom help message; empty/unset = default translation ''TicketPublicPleaseBeAccuratelyDescribe''.', 0, 0, 'admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php', 1, '7556d7cbb52c4f7073f48bbdd13f3f20ebb2827db15b3e81492c8ca4ca99db7e', 'v2', '2026-04-21T13:50:40+00:00', '["admin/ticket_public.php:120|$res = dolibarr_set_const($db, ''TICKET_PUBLIC_TEXT_HELP_MESSAGE'', $text_help, ''chaine'', 0, '''', $conf->entity);", "admin/ticket_public.php:438|$public_text_help_message = getDolGlobalString(\"TICKET_PUBLIC_TEXT_HELP_MESSAGE\", $langs->trans(''TicketPublicPleaseBeAccuratelyDescribe''));", "html.formticket.class.php:565|print ''<div class=\"warning hideonsmartphone\">''.(getDolGlobalString(\"TICKET_PUBLIC_TEXT_HELP_MESSAGE\", $langs->trans(''TicketPublicPleaseBeAccuratelyDescribe''))).''</div>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_PUBLIC_TEXT_HOME', 'string', NULL, 'admin', 'Stores the custom introductory text displayed on the public ticket portal home page.', 'Written via admin/ticket_public.php at lines 109 and 111; read back at line 424 for display in the admin UI. Rendered on the public page at public/ticket/index.php:96 with a fallback to the translated default if unset.', 'Changing this updates the welcome text on the public ticket portal; removing it reverts to the default translated text.', 'HTML string; defaults to the translated value of ''TicketPublicDesc'' if unset.', 0, 0, 'admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php', 1, '5a02415f353180a02e3eb90d48a391980dbbcd119d7bfc40be1d71dbd6a0d59e', 'v2', '2026-04-21T13:50:40+00:00', '["admin/ticket_public.php:109|write|$res = dolibarr_set_const($db, ''TICKET_PUBLIC_TEXT_HOME'', $text_home, ''chaine'', 0, '''', $conf->entity);", "admin/ticket_public.php:424|read|$public_text_home = getDolGlobalString(''TICKET_PUBLIC_TEXT_HOME'', ''<span class=\"opacitymedium\">''.$langs->trans(\"TicketPublicDesc\").''</span>'');", "public/ticket/index.php:96|read|print ''<p style=\"text-align: center\">''.(getDolGlobalString(\"TICKET_PUBLIC_TEXT_HOME\", ''<span class=\"opacitymedium\">''.$langs->trans(\"TicketPublicDesc\")).''</span></p>'').''</p>'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_SEND_INTERNAL_CC', 'string', NULL, 'ticket', 'Specifies one or more email addresses (comma-separated) to be CC''d internally on all ticket notification emails.', 'Configured via the ticket admin UI (admin/ticket.php:711). When set, the value is split by comma and used as the CC list for ticket notification emails (ticket/class/ticket.class.php:2984, :3097; core/class/html.formticket.class.php:1769).', 'Setting this value causes all ticket notification emails to include the specified addresses in CC. Clearing it removes the internal CC from ticket emails.', 'Comma-separated list of email addresses.', 0, 0, 'admin/ticket.php|admin/ticket.php', 1, 'ac1852c4870234f4f12518fd197c67a01fd187ba318be0f6f3232f905345e0a6', 'v2', '2026-04-21T11:16:15+00:00', '["ticket/class/ticket.class.php:2984|read|$sendtocc = explode('','', getDolGlobalString(\"TICKET_SEND_INTERNAL_CC\"));", "ticket/class/ticket.class.php:3096|check|if (getDolGlobalString(\"TICKET_SEND_INTERNAL_CC\")) {", "core/class/html.formticket.class.php:1769|read|$sendtocc = getDolGlobalString(''TICKET_SEND_INTERNAL_CC'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_SEND_PRIVATE_EMAIL', 'string', NULL, 'core', 'When set, suppresses the email sending option for ticket messages.', 'Checked in two locations in core/class/html.formticket.class.php (lines 1580 and 1653) before rendering or processing the send-email action for ticket messages.', 'Enabling this prevents the email notification option from being offered when adding ticket messages. Disabling (or leaving unset) allows email sending to be triggered from the ticket message form.', 'Empty/unset = email sending option available; any truthy value = email sending suppressed.', 1, 0, NULL, 1, '6480c7d5f9bf2ec704c2c95887ed228df0a3bcdbdd18143228c27a04807f5411', 'v2', '2026-04-21T13:50:40+00:00', '["html.formticket.class.php:1580|if (!getDolGlobalString(''TICKET_SEND_PRIVATE_EMAIL'')) {", "html.formticket.class.php:1653|if (!getDolGlobalString(''TICKET_SEND_PRIVATE_EMAIL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_SET_STATUS_ON_ANSWER', 'string', NULL, 'ticket', 'Defines the ticket status to automatically apply when a staff member answers a ticket.', 'Configured via the ticket admin UI (admin/ticket.php:623). When set to a value >= 0, answering a ticket by a non-external, non-private user triggers setStatut() with the configured status (ticket/class/ticket.class.php:3140, :3142). A value < 0 skips the automatic status change.', 'Setting this to a valid status code causes tickets to be automatically moved to that status on each staff reply. Leaving it unset or negative preserves the existing status after a reply.', 'Integer status code >= 0 to auto-set status on answer; negative value disables auto-status change.', 0, 0, 'admin/ticket.php|admin/ticket.php', 1, '6ccd2218280906f0ad75fa9f1b12dca520d797ed6e66ccbe8f8bdfb7abd4d2dc', 'v2', '2026-04-21T11:16:15+00:00', '["ticket/class/ticket.class.php:3134  // Except if TICKET_SET_STATUS_ON_ANSWER has been defined", "ticket/class/ticket.class.php:3140|read|} elseif (getDolGlobalInt(''TICKET_SET_STATUS_ON_ANSWER'', -1) >= 0 && empty($user->socid) && empty($private)) {", "ticket/class/ticket.class.php:3142|read|$object->setStatut(getDolGlobalInt(''TICKET_SET_STATUS_ON_ANSWER''), null, '''', ''TICKET_MODIFY'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_SHOW_COMPANY_FOOTER', 'bool', NULL, 'public', 'Controls whether the company footer is shown on the public ticket pages.', 'Configured via admin/ticket_public.php:376 (selectarray UI) and checked in public/ticket/list.php:801, public/ticket/index.php:109, public/ticket/create_ticket.php:614, and public/ticket/view.php:503. Default value of 1 (enabled) is set in core/modules/modTicket.class.php:124 with description ''Enable footer on ticket public page''.', 'When enabled (default), the company footer is displayed on public ticket list, index, create, and view pages; disabling it hides the footer.', '1 = enabled (default, per modTicket.class.php), 0 = disabled', 0, 0, 'admin/ticket_public.php', 1, 'ef6697e0194b1978470ef7e7cf62c3515297278b94e07f302dddf17c443e5d96', 'v2', '2026-07-24T06:41:12+00:00', '["[''TICKET_SHOW_COMPANY_FOOTER'', ''chaine'', getDolGlobalInt(''TICKET_SHOW_COMPANY_FOOTER'', 1), ''Enable footer on ticket public page'', 0],"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_SHOW_COMPANY_LOGO', 'bool', NULL, 'admin', 'Controls whether the company logo is shown in the header of public ticket pages.', 'Configured via admin/ticket_public.php (write at line 89, selectarray UI at line 361). Default value of 1 (enabled) is set in core/modules/modTicket.class.php:123 with description ''Enable logo header on ticket public page'', and used in core/lib/ticket.lib.php:290 to decide whether to print the online header.', 'When enabled (default), the company logo is displayed in the header of public ticket pages; disabling it hides the logo.', '1 = enabled (default, per modTicket.class.php), 0 = disabled', 0, 0, 'admin/ticket_public.php|admin/ticket_public.php', 1, '1da2e389445b325e1a5cfb4f776760ee7f458e17ddded2bf2867330fcaba5c52', 'v2', '2026-07-24T06:41:12+00:00', '["[''TICKET_SHOW_COMPANY_LOGO'', ''chaine'', getDolGlobalInt(''TICKET_SHOW_COMPANY_LOGO'', 1), ''Enable logo header on ticket public page'', 0],"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_SHOW_MESSAGES_ON_CARD', 'bool', NULL, 'ticket', 'Shows the list of agenda/messaging actions directly on the ticket card''s main tab, duplicating what is on the Events/Agenda tab.', 'Used in ticket/card.php:1621: `if (getDolGlobalString(''TICKET_SHOW_MESSAGES_ON_CARD'')) { ... show_actions_messaging(...) }`. The code comment notes this is ''a duplicate of the view Events/Agenda but on the main tab''.', 'When enabled, an extra list of actions/messages (with buttons to add a message or event) is rendered inline on the ticket card, in addition to the dedicated Events/Agenda tab.', 'Boolean (getDolGlobalString truthiness): set/truthy shows the messages block on the card; unset/false hides it.', 1, 0, NULL, 1, 'd90fdf5141b388974f78792662bce39490391f5a83a3177678f97c824ffda216', 'v2', '2026-07-24T07:05:23+00:00', '["ticket/card.php:1621: if (getDolGlobalString(''TICKET_SHOW_MESSAGES_ON_CARD'')) {", "ticket/card.php: // Show messages on card (Note: this is a duplicate of the view Events/Agenda but on the main tab)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_SHOW_PROGRESSION', 'bool', NULL, 'public', 'Controls whether the ticket progression/progress field is displayed on public ticket pages.', 'Checked in eight locations across public/ticket/view.php, list.php (lines 275, 357, 494, 559, 652, 711), and admin/ticket_public.php:390. The admin page at line 390 conditionally acts when this is not set.', 'Enabling this shows the progress percentage on ticket list and view pages; disabling it hides it.', 'Any non-empty string value enables progression display.', 0, 0, 'admin/ticket_public.php', 1, 'c6b7a8cb1dbe07ca07eb7dde836dd23c895f824c01fe1bfd09c50ee3e99be547', 'v2', '2026-04-21T13:50:40+00:00', '["public/ticket/view.php:377|check|if (getDolGlobalString(''TICKET_SHOW_PROGRESSION'')) {", "public/ticket/list.php:652|check|if (getDolGlobalString(''TICKET_SHOW_PROGRESSION'') && !empty($arrayfields[''t.progress''][''checked''])) {", "public/ticket/list.php:275|check|if (!getDolGlobalString(''TICKET_SHOW_PROGRESSION'')) {", "admin/ticket_public.php:390|check|if (!getDolGlobalInt(''TICKET_SHOW_PROGRESSION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_UNIVERSAL_MASK', 'string', NULL, 'core', 'Numbering mask used by the ''Universal'' numbering module for Ticket references.', 'Read/written by mod_ticket_universal (core/modules/ticket/mod_ticket_universal.php:91,143): shown in an admin setup form input and consumed by getNextValue() to compute the next ticket ref.', 'Changing the mask changes the format of future ticket references generated by this numbering module; existing refs are unaffected.', 'Free-form mask string using Dolibarr''s generic mask code syntax (GenericMaskCodes tooltip), same convention as other numbering-module masks.', 0, 0, NULL, 1, 'eec12d8896da682f84160c7e59bdeee56302f80446be7a887279569f9b332c3f', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/ticket/mod_ticket_universal.php:143|read|$mask = getDolGlobalString(\"TICKET_UNIVERSAL_MASK\");", "core/modules/ticket/mod_ticket_universal.php:91|read|...name=\"maskticket\" value=\"''.getDolGlobalString(\"TICKET_UNIVERSAL_MASK\").''\">''"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_URL_PUBLIC_INTERFACE', 'string', NULL, 'public', 'Sets a custom base URL for the public ticket interface, overriding the default /public/ticket/ path.', 'Configured via admin/ticket_public.php (read at line 472, write at lines 142 and 144). Used as a fallback default across public/ticket/list.php:104, public/ticket/create_ticket.php:163, public/ticket/view.php:99, and ticket/class/ticket.class.php:3129, and to build the CSS asset path in public/ticket/list.php:127.', 'When set, links, redirects, and CSS asset URLs for the public ticket interface use this custom URL instead of the default dol_buildpath(''/public/ticket/...'') path.', NULL, 0, 0, 'admin/ticket_public.php|admin/ticket_public.php|admin/ticket_public.php', 1, '4fe8e2a3f2383616b104940655370d790ed46a7334271719a4964fb14e25c20c', 'v2', '2026-07-24T06:41:12+00:00', '["$backtopage = getDolGlobalString(''TICKET_URL_PUBLIC_INTERFACE'', DOL_URL_ROOT.''/public/ticket/'');", "(getDolGlobalString(''TICKET_URL_PUBLIC_INTERFACE'') ? getDolGlobalString(''TICKET_URL_PUBLIC_INTERFACE'') . ''/view.php'' : dol_buildpath(''/public/ticket/view.php'', 2)) : dol_buildpath("]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TICKET_USE_SEARCH_TO_SELECT', 'bool', NULL, 'core', 'Enables an AJAX search-to-select widget instead of a plain drop-down for ticket selection fields.', 'Checked and read across 5 locations in core/class/html.form.class.php (lines 8361, 8469, 8477, 8587, 8819). When truthy and JavaScript/AJAX is enabled, an ajax_combobox is rendered with this value passed as the minimum character threshold. When falsy, a plain select list is used.', 'Enabling improves performance and usability on large ticket datasets by replacing full drop-downs with asynchronous search. Disabling reverts to a full static list.', 'Truthy integer = enable AJAX search-to-select (value used as minimum chars for search); 0/empty = use plain select.', 1, 0, NULL, 1, '709c8d4f84ed2a1ff8647702dccbf07921af19450020cbc427adf8947f135ffe', 'v2', '2026-04-21T13:50:40+00:00', '["core/class/html.form.class.php:8361|check|if (!empty($conf->use_javascript_ajax) && getDolGlobalString(''TICKET_USE_SEARCH_TO_SELECT'')) {", "core/class/html.form.class.php:8469|read|$out .= ajax_combobox($htmlname, $events, getDolGlobalInt(''TICKET_USE_SEARCH_TO_SELECT''));", "core/class/html.form.class.php:8477|check|if (getDolGlobalString(''TICKET_USE_SEARCH_TO_SELECT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TIMESPENT_', 'string', NULL, 'core', 'Not a standalone constant: a prefix for per-numbering-module constants, illustrated by TIMESPENT_timespent_ADDON which stores the active time-spent reference numbering module.', 'The literal write found is $conf->global->TIMESPENT_timespent_ADDON = ''mod_timespent_standard'' in core/class/timespent.class.php:989, used as a fallback default inside getNextNumRef() when no numbering addon is configured yet; other TIMESPENT_-prefixed constants seen include TIMESPENT_ALWAYS_UPDATE_THM (task.class.php).', 'As a bare prefix, ''TIMESPENT_'' has no effect; the concrete constant TIMESPENT_timespent_ADDON determines which numbering module class (default ''mod_timespent_standard'') generates the next timespent reference.', 'String: numbering module class name, e.g. ''mod_timespent_standard'' (the default set when the constant is empty).', 1, 0, NULL, 1, 'f49cf9e62387ffc6f46356a7033eeaad30c3c1d412e79289f3e5d6ac42ba9041', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/timespent.class.php:988: if (!getDolGlobalString(''TIMESPENT_timespent_ADDON'')) {", "core/class/timespent.class.php:989: $conf->global->TIMESPENT_timespent_ADDON = ''mod_timespent_standard'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('TIMESPENT_ALWAYS_UPDATE_THM', 'string', NULL, 'projet', 'Forces the hourly rate (thm) of a time-spent entry to always be recalculated from the user''s current rate, instead of only when it was empty.', 'Used twice in projet/class/task.class.php: line 2171 as part of the condition to run the timespent update block, and line 2191 to force refetching the user''s thm even if $timespent->thm was already set.', 'When enabled, every timespent update re-reads the assigned user''s current hourly rate (thm) and overwrites the stored rate on the time entry, even if a rate was already recorded; when disabled, the rate is only set the first time (when empty).', 'Boolean-like (getDolGlobalString): non-empty forces re-updating thm on every save; empty/unset (default) updates thm only if it was not already set.', 1, 0, NULL, 1, 'ea28e2e411c9da140482cd0c110ed7410925d7cad5e1c40cc67069e5a267c430', 'v2', '2026-07-24T07:05:23+00:00', '["projet/class/task.class.php:2171: if ($ret == 1 && (($this->timespent_old_duration != $this->timespent_duration) || getDolGlobalString(''TIMESPENT_ALWAYS_UPDATE_THM''))) {", "projet/class/task.class.php:2191: if (empty($timespent->thm) || getDolGlobalString(''TIMESPENT_ALWAYS_UPDATE_THM'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('URL_REDIRECTION_AFTER_CHANGEPASSWORD', 'string', NULL, 'user', 'Overrides the URL the user is redirected to after a password reset email flow (send_password).', 'In user/class/user.class.php:2818-2821, User::send_password() defaults $url to the application root, then overwrites it with getDolGlobalString(''URL_REDIRECTION_AFTER_CHANGEPASSWORD'') if that constant is set.', 'Setting it changes the destination URL referenced/logged during the ''password forgotten'' email flow instead of the application root.', 'String: any URL; unset/empty keeps the default application root URL.', 1, 0, NULL, 1, 'd28fd1ab7fb6ca8a8afa0643dc30cc3229f557a3a09940311309595cb5930f3b', 'v2', '2026-07-24T07:05:23+00:00', '["user/class/user.class.php:2820|check|if (getDolGlobalString(''URL_REDIRECTION_AFTER_CHANGEPASSWORD'')) {", "user/class/user.class.php:2821|read|$url = getDolGlobalString(''URL_REDIRECTION_AFTER_CHANGEPASSWORD'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USERGROUP_ADDON_PDF', 'string', NULL, 'user', 'Specifies the active PDF generation module/model for user group documents.', 'Read by the user group class at user/class/usergroup.class.php to determine which PDF model to load when generating a document. The admin UI at admin/usergroup.php lets administrators select the active model by comparing against this constant.', 'Changing this value switches the PDF model used when generating user group documents; an empty or unset value disables PDF generation for user groups.', 'Any valid PDF module name available in the user group module.', 0, 0, 'admin/usergroup.php', 1, 'd960ad05128e9240599e43ba2c5406041651c0b5c1ab5b70d36723ee05a643a7', 'v2', '2026-04-21T13:50:40+00:00', '["admin/usergroup.php:224|check|if (getDolGlobalString(''USERGROUP_ADDON_PDF'') == $name) {", "user/class/usergroup.class.php:1039|check|if (getDolGlobalString(''USERGROUP_ADDON_PDF'')) {", "user/class/usergroup.class.php:1040|read|$modele = getDolGlobalString(''USERGROUP_ADDON_PDF'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USERGROUP_ADDON_PDF_ODT', 'string', NULL, 'admin', 'Stores the selected ODT document template for user group PDF generation.', 'Holds the name of the chosen ODT model for user group documents. Written and managed via the admin UI at admin/usergroup.php. When a new value is selected, the previous one is deleted and the new one is stored via dolibarr_set_const.', 'Changing this value switches the ODT template used for generating user group PDF documents; deleting it removes the active selection.', 'Any valid ODT template name available in the user group document module.', 0, 0, 'admin/usergroup.php|admin/usergroup.php|admin/usergroup.php|admin/usergroup.php', 1, '61f677a30d1f277a54439f2f44e6e5c7a78de1300ddd2cbedf795826b68e8785', 'v2', '2026-04-21T13:50:40+00:00', '["admin/usergroup.php:82|write|if (dolibarr_set_const($db, \"USERGROUP_ADDON_PDF_ODT\", $value, ''chaine'', 0, '''', $conf->entity)) {", "admin/usergroup.php:85|write|$conf->global->USERGROUP_ADDON_PDF_ODT = $value;", "admin/usergroup.php:75|check|if (getDolGlobalString(''USERGROUP_ADDON_PDF_ODT'') == \"$value\") {", "admin/usergroup.php:76|write|dolibarr_del_const($db, ''USERGROUP_ADDON_PDF_ODT'', $conf->entity);"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USERGROUP_ADDON_PDF_ODT_CLOSED', 'string', NULL, 'core', 'Stores the ODT model to preselect for a usergroup document when its status is ''closed''.', 'Set via a select box (value4) rendered in the doc module''s info() form in core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:180, shown only when MAIN_PROPAL_CHOOSE_ODT_DOCUMENT is enabled and reachable through the module configuration screen (setModuleOptions action), not a dedicated admin/*.php page.', 'Changes which ODT template is used by default for usergroup documents flagged as ''closed''; no effect if the ODT-choice UI is not enabled.', 'Name of an available ODT template file (as returned by ModelePDFUserGroup::liste_modeles()).', 0, 0, NULL, 1, 'ee886925e7162f53b35a366928c561891cdcb014bfc6eb58fbc25dd54c4e8dca', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:180|read|$texte .= $form->selectarray(''value4'', $list, getDolGlobalString(''USERGROUP_ADDON_PDF_ODT_CLOSED''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USERGROUP_ADDON_PDF_ODT_DEFAULT', 'string', NULL, 'core', 'Selects which ODT model is used by default when generating a user-group document (only relevant when ODT model choice is enabled).', 'Read in core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:168: `$texte .= $form->selectarray(''value2'', $list, getDolGlobalString(''USERGROUP_ADDON_PDF_ODT_DEFAULT''));`, populating a select box of available ODT models ($list from ModelePDFUserGroup::liste_modeles), shown only when `getDolGlobalInt(''MAIN_PROPAL_CHOOSE_ODT_DOCUMENT'') > 0`, and wired as hidden ''param2'' in the module''s admin form.', 'Changing it changes which ODT template file is pre-selected as the default model for user-group document generation.', 'Free-form string: filename/identifier of an ODT model, chosen from the list produced by ModelePDFUserGroup::liste_modeles().', 0, 0, NULL, 1, '034cff03e4e134312e84e2827fde8ea1d6c13c623ff616761596c2ab02ee3bd4', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:168: $texte .= $form->selectarray(''value2'', $list, getDolGlobalString(''USERGROUP_ADDON_PDF_ODT_DEFAULT''));", "core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:122: $texte .= ''<input type=\"hidden\" name=\"param2\" value=\"USERGROUP_ADDON_PDF_ODT_DEFAULT\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USERGROUP_ADDON_PDF_ODT_PATH', 'string', 'DOL_DATA_ROOT/doctemplates/usergroups', 'core', 'List of directories to scan for ODT templates used to generate user-group documents (default DOL_DATA_ROOT/doctemplates/usergroups).', 'Read in core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:115 as `$odtPath = trim(getDolGlobalString(''USERGROUP_ADDON_PDF_ODT_PATH''))`, then split and scanned for .ods/.odt files; also wired as a hidden ''param1'' field in the module''s own admin form (action ''setModuleOptions'').', 'Changing it changes which directories are scanned for ODT model files for user-group document generation; the payload''s DEFAULT value (''DOL_DATA_ROOT/doctemplates/usergroups'') is used when unset.', 'Free-form string: one or more directory paths (DOL_DATA_ROOT placeholder supported), comma/newline separated. Default: ''DOL_DATA_ROOT/doctemplates/usergroups''.', 0, 1, NULL, 1, 'e0c391950fc5248cb60f60393737f9a6bb0fb8f29049241fd333a531aee16f26', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:115: $odtPath = trim(getDolGlobalString(''USERGROUP_ADDON_PDF_ODT_PATH''));", "core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:121: $texte .= ''<input type=\"hidden\" name=\"param1\" value=\"USERGROUP_ADDON_PDF_ODT_PATH\">'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USERGROUP_ADDON_PDF_ODT_TOBILL', 'string', NULL, 'core', 'Stores the ODT model to preselect for a usergroup document when its status is ''to bill''.', 'Set via a select box (value3) rendered in the doc module''s info() form in core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:174, shown only when MAIN_PROPAL_CHOOSE_ODT_DOCUMENT is enabled and reachable through the module configuration screen (setModuleOptions action), not a dedicated admin/*.php page.', 'Changes which ODT template is used by default for usergroup documents flagged as ''to bill''; no effect if the ODT-choice UI is not enabled.', 'Name of an available ODT template file (as returned by ModelePDFUserGroup::liste_modeles()).', 0, 0, NULL, 1, '5d68708425d92c4608d727e3c7d99e7ef9be7cb3def9c988343e23c85b5f8dae', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/usergroup/doc/doc_generic_usergroup_odt.modules.php:174|read|$texte .= $form->selectarray(''value3'', $list, getDolGlobalString(''USERGROUP_ADDON_PDF_ODT_TOBILL''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_ADDON_PDF', 'string', NULL, 'user', 'Selects the PDF document model (template) used to generate a user''s PDF document.', 'Read in user/class/user.class.php:4246-4247 inside User::generateDocument(): if set, its value becomes $modele (model name); otherwise the code falls back to the hardcoded default ''bluesky'' model.', 'Changing it selects a different PDF template class (under core/modules/user/doc/) for generating user documents; an invalid/unknown model name would break document generation.', 'String: name of a user PDF document model/template; unset/empty falls back to default ''bluesky''.', 1, 0, NULL, 1, '2f65c6c318ece7ead1c64a807d2d1a2137f6e58c3f39e228e471aeaabae4e52c', 'v2', '2026-07-24T07:05:23+00:00', '["user/class/user.class.php:4246|check|if (getDolGlobalString(''USER_ADDON_PDF'')) {", "user/class/user.class.php:4247|read|$modele = getDolGlobalString(''USER_ADDON_PDF'');", "user/class/user.class.php:4249| } else { $modele = ''bluesky''; }"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_ADDON_PDF_ODT', 'string', NULL, 'admin', 'Selects the active ODT document template addon used to generate user profile PDF/ODT documents.', 'Set and managed in admin/user.php via dolibarr_set_const and dolibarr_del_const (lines 87, 90, 101). Compared against available model names at admin/user.php:304 to highlight the active selection in the UI.', 'Changing this value switches the document template used when generating user profile documents; deleting the constant reverts to the system default.', 'String; name of a user PDF/ODT addon model available in the system.', 0, 0, 'admin/user.php|admin/user.php|admin/user.php|admin/user.php|admin/user.php|admin/user.php', 1, 'fe4779ed91126bc2490157669ae579e2143b7e16e438fcef37482acad93637bc', 'v2', '2026-04-21T13:29:58+00:00', '["admin/user.php:87|write|if (dolibarr_set_const($db, \"USER_ADDON_PDF_ODT\", $value, ''chaine'', 0, '''', $conf->entity)) {", "admin/user.php:90|write|$conf->global->USER_ADDON_PDF_ODT = $value;", "admin/user.php:101|write|dolibarr_del_const($db, \"USER_ADDON_PDF_ODT\", $conf->entity);", "admin/user.php:304|check|if (getDolGlobalString(''USER_ADDON_PDF_ODT'') == $name) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_ADDON_PDF_ODT_CLOSED', 'string', NULL, 'core', 'Stores the ODT model to preselect for a user document when its status is ''closed''.', 'Set via a select box (value4) rendered in the doc module''s info() form in core/modules/user/doc/doc_generic_user_odt.modules.php:179, shown only when MAIN_PROPAL_CHOOSE_ODT_DOCUMENT is enabled; reachable through the module configuration screen (setModuleOptions action), not a dedicated admin/*.php page.', 'Changes which ODT template is used by default for user documents flagged ''closed''.', 'Name of an available ODT template file (as returned by ModelePDFUser::liste_modeles()).', 0, 0, NULL, 1, '42c6078f4926c925f7e3457f5d116af3cfad882462e0e5e949683910d807f389', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/user/doc/doc_generic_user_odt.modules.php:179|read|$out .= $form->selectarray(''value4'', $list, getDolGlobalString(''USER_ADDON_PDF_ODT_CLOSED''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_ADDON_PDF_ODT_DEFAULT', 'string', NULL, 'core', 'Stores the ODT model to preselect for a new user document (status ''create'').', 'Set via a select box (value2) rendered in the doc module''s info() form in core/modules/user/doc/doc_generic_user_odt.modules.php:167, shown only when MAIN_PROPAL_CHOOSE_ODT_DOCUMENT is enabled; reachable through the module configuration screen (setModuleOptions action), not a dedicated admin/*.php page.', 'Changes which ODT template is used by default when generating a document for a new user.', 'Name of an available ODT template file (as returned by ModelePDFUser::liste_modeles()).', 0, 0, NULL, 1, '8567d2e3bb9a5df8bfc64876254b76fea4becbcb209c0063255883ef8bfa1248', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/user/doc/doc_generic_user_odt.modules.php:167|read|$out .= $form->selectarray(''value2'', $list, getDolGlobalString(''USER_ADDON_PDF_ODT_DEFAULT''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_ADDON_PDF_ODT_PATH', 'string', 'DOL_DATA_ROOT/doctemplates/users', 'core', 'Comma-separated list of directories scanned for user-document ODT/ODS templates.', 'Read in core/modules/user/doc/doc_generic_user_odt.modules.php:114, where the value is trimmed, split on commas/newlines and each entry has the literal string ''DOL_DATA_ROOT'' substituted for the real data root before dol_dir_list() scans it for .ods/.odt files.', 'Adding directories here makes additional ODT/ODS templates available for user document generation; invalid/missing directories are flagged with a warning in the config UI.', 'Comma or newline separated directory paths; ''DOL_DATA_ROOT'' token is replaced by the actual data root constant. Default: ''DOL_DATA_ROOT/doctemplates/users''.', 1, 1, NULL, 1, 'c0aec93cd3137f5962b26e5ac4bdb82717c116d966e09f82b93c2e719612d03e', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/user/doc/doc_generic_user_odt.modules.php:114|read|$odtPath = trim(getDolGlobalString(''USER_ADDON_PDF_ODT_PATH''));", "core/modules/user/doc/doc_generic_user_odt.modules.php: $tmpdir = preg_replace(''/DOL_DATA_ROOT/'', DOL_DATA_ROOT, $tmpdir);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_ADDON_PDF_ODT_TOBILL', 'string', NULL, 'core', 'Stores the ODT model to preselect for a user document when its status is ''to bill''.', 'Set via a select box (value3) rendered in the doc module''s info() form in core/modules/user/doc/doc_generic_user_odt.modules.php:173, shown only when MAIN_PROPAL_CHOOSE_ODT_DOCUMENT is enabled; reachable through the module configuration screen (setModuleOptions action), not a dedicated admin/*.php page.', 'Changes which ODT template is used by default for user documents flagged ''to bill''.', 'Name of an available ODT template file (as returned by ModelePDFUser::liste_modeles()).', 0, 0, NULL, 1, '5fa227cdff978439eb9febce8710bab4acea1851b60ed6f0cc751bf3ce75e853', 'v2', '2026-07-24T07:05:23+00:00', '["core/modules/user/doc/doc_generic_user_odt.modules.php:173|read|$out .= $form->selectarray(''value3'', $list, getDolGlobalString(''USER_ADDON_PDF_ODT_TOBILL''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_DISABLE_STATE', 'bool', NULL, 'user', 'Hides the state/region field on user profile forms.', 'Checked in user/card.php at lines 1325 and 2864. When this constant is set, the state field is not rendered in user profile forms.', 'Setting this constant suppresses the state/region field in user forms; leaving it unset allows the field to appear.', 'Truthy value to disable (hide) the state field; empty or unset to show it.', 1, 0, NULL, 1, '5135395d69ffde4f1377bfe3b92b84e5572be94be3128aa417424a154a66ac04', 'v2', '2026-04-21T13:50:40+00:00', '["user/card.php:1325|check|if (!getDolGlobalString(''USER_DISABLE_STATE'')) {", "user/card.php:2864|check|if (!getDolGlobalString(''USER_DISABLE_STATE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_HIDE_EXTERNAL_IN_COMBOBOX', 'bool', NULL, 'core', 'Hides external users from user selection combo boxes.', 'Checked in comm/mailing/class/html.formadvtargetemailing.class.php:237, core/class/html.formother.class.php:545 (with a per-user override via getDolUserString), and core/class/html.form.class.php:2776.', 'When enabled, external users are excluded from user combo boxes across mailing target selection and other user-selection forms.', NULL, 0, 0, NULL, 1, 'de22bb80021ccb651fbb12f1710aa372af83bf6408266a93d2dad91f540598b9', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolUserString(''USER_HIDE_EXTERNAL_IN_COMBOBOX'', getDolGlobalString(''USER_HIDE_EXTERNAL_IN_COMBOBOX''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_HIDE_INACTIVE_IN_COMBOBOX', 'bool', NULL, 'admin', 'Hides inactive (disabled) users from user-selection combo boxes throughout the application.', 'Configured via admin/user.php with dolibarr_set_const. Documented at core/class/html.form.class.php:2214 as affecting the ''show only active users'' behaviour. Evaluated in html.form.class.php, html.formother.class.php, and comm/mailing targeting selectors.', 'When enabled, disabled user accounts are excluded from all user picker dropdowns; this reduces clutter but means those users cannot be selected for assignments even if needed.', 'Any truthy value hides inactive users; unset shows all users.', 0, 0, 'admin/user.php|admin/user.php', 1, 'a9308aff7b9c61dbfb054392cd5be5c1ab105001b5b84ed8a84401172cd7fd54', 'v2', '2026-04-21T13:29:58+00:00', '["core/class/html.form.class.php:2214  * @param int<0,1> \t\t\t$notdisabled \tShow only active users (note: this will also happen, whatever is this option, if USER_HIDE_INACTIVE_IN_COMBOBOX is on).", "admin/user.php:122|write|if (dolibarr_set_const($db, \"USER_HIDE_INACTIVE_IN_COMBOBOX\", $status, ''chaine'', 0, '''', $conf->entity) > 0) {", "core/class/html.form.class.php:2314|check|if (getDolGlobalString(''USER_HIDE_INACTIVE_IN_COMBOBOX'') || $notdisabled) {", "core/class/html.formother.class.php:548|check|if (getDolUserString(''USER_HIDE_INACTIVE_IN_COMBOBOX'', getDolGlobalString(''USER_HIDE_INACTIVE_IN_COMBOBOX''))) {\t// Can be set in setup of module User."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_HIDE_NONEMPLOYEE_IN_COMBOBOX', 'bool', NULL, 'core', 'Hides non-employee users from user selection combo boxes.', 'Checked in comm/mailing/class/html.formadvtargetemailing.class.php:234, core/class/html.formother.class.php:542 (with a per-user override via getDolUserString), and core/class/html.form.class.php:2773.', 'When enabled, users who are not marked as employees are excluded from user combo boxes across mailing target selection and other user-selection forms.', NULL, 0, 0, NULL, 1, 'a5854c7e1b9b0c5ddfee89b3a91a3d227032053627dd0aa9d230565f5763b04a', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolUserString(''USER_HIDE_NONEMPLOYEE_IN_COMBOBOX'', getDolGlobalString(''USER_HIDE_NONEMPLOYEE_IN_COMBOBOX''))) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_IMAGE_PUBLIC_INTERFACE', 'string', NULL, 'public', 'URL/path of a background image displayed on the public user profile page (e.g. for public recruitment cards).', 'Checked in public/users/view.php:299-301; if set, an <img> tag with id ''idUSER_IMAGE_PUBLIC_INTERFACE'' inside a ''backimagepublicrecruitment'' div is printed using this value as the src.', 'Setting it adds a background/decorative image to the public user profile page; unset, no such image block is rendered.', 'String: a URL or path to an image file.', 1, 0, NULL, 1, 'ebdf1200d93245073b3c6bca905eaa7dcd2863f9539f8bd7e86600098740296d', 'v2', '2026-07-24T07:05:23+00:00', '["public/users/view.php:299: if (getDolGlobalString(''USER_IMAGE_PUBLIC_INTERFACE'')) {", "public/users/view.php:301: print ''<img id=\"idUSER_IMAGE_PUBLIC_INTERFACE\" src=\"'' . getDolGlobalString(''USER_IMAGE_PUBLIC_INTERFACE'').''\">'';"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_MAIL_REQUIRED', 'string', NULL, 'user', 'Makes the email address field mandatory when creating or editing a user account.', 'Configured via admin/user.php:173 and enforced in user/class/user.class.php:1841 and :2252 (validation rejects missing/invalid email). The user/card.php form marks the email field with the CSS class ''fieldrequired'' when set. Also explicitly set to 0 at install/step5.php:306 during installation to allow creating the initial user without email.', 'Enabling this constant prevents saving a user record without a valid email address; disabling it makes email optional.', 'Any truthy value makes email mandatory; 0 or unset makes it optional.', 0, 0, 'admin/user.php', 1, 'e42105e2507268acb63ed96189ba0c9f16bab73f77d30aabc1fc684dde776f9d', 'v2', '2026-04-21T13:29:58+00:00', '["user/class/user.class.php:1841|check|if (getDolGlobalString(''USER_MAIL_REQUIRED'') && !isValidEmail($this->email)) {", "user/card.php:1369|read|print ''<tr><td''.(getDolGlobalString(''USER_MAIL_REQUIRED'') ? '' class=\"fieldrequired\"'' : '''').''>''.$langs->trans(\"EMail\").''</td>'';", "install/step5.php:306|write|$conf->global->USER_MAIL_REQUIRED = 0; \t\t\t// Force global option to be sure to create a new user with no email", "admin/user.php:173|check|if (!getDolGlobalString(''USER_MAIL_REQUIRED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_PASSWORD_GENERATED', 'string', NULL, 'core', 'Selects which password generation rule/class is used to generate user passwords.', 'Configured via admin/security.php (write at line 60, checks at lines 273 and 292 comparing against a key or the literal ''Perso''). Read in user/class/user.class.php:2647 and :2649 to build the class name ''modGeneratePass''.ucfirst(value), in user/card.php:3300 (special-cased for value ''none''), core/class/fields/passwordfield.class.php:138, and core/lib/security2.lib.php:537.', 'Changing this value changes which password generation module class is instantiated, altering how generated passwords are constructed; the special value ''none'' and ''Perso'' are handled distinctly in the code.', '''Perso'' = custom/personalized rule (per admin/security.php:292), ''none'' = generic rule (per user/card.php:3300), otherwise names a modGeneratePassXxx class', 0, 0, 'admin/security.php|admin/security.php|admin/security.php', 1, '1ae352f4f94156cde2db527c44f431a5129ed50848da8f3f1c0cdee784aab4be', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''USER_PASSWORD_GENERATED'') == \"Perso\") {", "$usegenericrule = getDolGlobalString(''USER_PASSWORD_GENERATED'') == ''none'' ? 1 : 0;", "$modGeneratePassClass = ''modGeneratePass''.ucfirst(getDolGlobalString(''USER_PASSWORD_GENERATED''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_PASSWORD_PATTERN', 'string', NULL, 'admin', 'Defines the semicolon-separated pattern rules for the custom password generator/validator.', 'Written via admin/security.php:171 and read in admin/system/security.php:603, admin/security.php:240, and core/modules/security/generate/modGeneratePassPerso.class.php:122 where it is exploded by '';''. If unset, the module initialises it to the default ''12;1;1;0;3;1'' (line 113).', 'Changing this constant alters the minimum length, character class requirements, and other constraints applied when generating or validating user passwords.', 'String: semicolon-separated integers, default ''12;1;1;0;3;1''.', 0, 0, 'admin/security.php|admin/system/security.php|admin/security.php', 1, '24f68f8b3e1ca98c4ff955cbbe7d3e92d6f4d2dd1b18adf286d48cc7496ae29e', 'v2', '2026-04-21T13:50:40+00:00', '["admin/security.php:171|write|dolibarr_set_const($db, \"USER_PASSWORD_PATTERN\", $pattern, ''chaine'', 0, '''', $conf->entity);", "core/modules/security/generate/modGeneratePassPerso.class.php:113|write|dolibarr_set_const($db, \"USER_PASSWORD_PATTERN\", ''12;1;1;0;3;1'', ''chaine'', 0, '''', $conf->entity);", "admin/system/security.php:603|read|$tabConf = explode(\";\", getDolGlobalString(''USER_PASSWORD_PATTERN''));"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USER_PHOTO_ALLOW_EXTERNAL_DOWNLOAD', 'bool', NULL, 'user', 'Enables indexing an uploaded user photo into the document database so it can be downloaded externally.', 'In user/card.php:696, after a user photo upload succeeds, if this bool is set the code calls deleteFilesIntoDatabaseIndex and addFileIntoDatabaseIndex to register the uploaded photo file in Dolibarr''s ecm/document index.', 'Setting it to true causes uploaded user photos to be indexed in the document database (making them reachable via document download/index features); unset/false skips this indexing step.', 'true/1 = index uploaded photo file into database; false/unset (default) = photo stored on disk only, not indexed.', 1, 0, NULL, 1, '33da48e42fb8af242ccd5e272dc73385c0ce0cd8065329e0d3100f6f717853e7', 'v2', '2026-07-24T07:05:23+00:00', '["user/card.php:696|check|if (getDolGlobalString(''USER_PHOTO_ALLOW_EXTERNAL_DOWNLOAD'')) {", "user/card.php:701: addFileIntoDatabaseIndex(dirname($newfile), basename($newfile), '''', ''uploaded'', 1, $object);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USE_COLOR_FOR_PROSPECTION_STATUS', 'bool', NULL, 'core', 'Enables colored badges (from the theme''s data colors) for prospect/opportunity status instead of plain text labels.', 'In core/lib/project.lib.php:2650-2660 a color is assigned per opportunity status from $theme_datacolor when getDolGlobalString(''USE_COLOR_FOR_PROSPECTION_STATUS'') is set; at line 2852 the inline comment states ''Because color of prospection status has no meaning yet, it is used if hidden constant is set'' — if NOT set, the plain-text OppStatus label is printed instead of the colored badge.', 'Enabling it changes how prospection/opportunity status is rendered in project lists: colored badge instead of plain translated text label.', 'Boolean-like: set/non-empty shows colored status badges; unset (default) shows plain OppStatus text label.', 1, 0, NULL, 1, '00e8dc584252062911c41030f89bf8e7d35869d28b1459a4be7d0520231edacf', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/project.lib.php:2650: if (is_array($listofstatus) && getDolGlobalString(''USE_COLOR_FOR_PROSPECTION_STATUS'')) {", "core/lib/project.lib.php:2851: // Because color of prospection status has no meaning yet, it is used if hidden constant is set", "core/lib/project.lib.php:2852: if (!getDolGlobalString(''USE_COLOR_FOR_PROSPECTION_STATUS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USE_PDFTK_FOR_PDF_CONCAT', 'bool', NULL, 'core', 'Selects PDFtk instead of the default engine for merging/concatenating PDF files during mass actions.', 'Checked at core/actions_massactions.inc.php:910 in the mass-action PDF merge routine that builds a single merged output file for selected objects (e.g. unpaid invoices).', 'When set, the PDF merge for mass actions is performed via PDFtk rather than the built-in merge library; behavior/output format may differ depending on PDFtk availability.', 'Truthy (non-empty string) selects PDFtk for the merge; empty/unset uses the default merge method.', 1, 0, NULL, 1, 'f19c110d99f42b38ef8cba68a43e0cb50dd3087c077df16b642decc38eafdf8e', 'v2', '2026-07-24T07:05:23+00:00', '["core/actions_massactions.inc.php:910: if (getDolGlobalString(''USE_PDFTK_FOR_PDF_CONCAT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USE_RETAINED_WARRANTY_ONLY_FOR_SITUATION_FINAL', 'bool', NULL, 'core', 'Restricts the retained warranty display on situation invoices to the final situation invoice only.', 'Used in pdf_octopus.modules.php: at line 3056 warranty from previous invoices is shown only when this constant is NOT set; at line 3146 the final-invoice-only logic is applied when it IS set. At line 175 it is force-written to 1 in the module constructor. A TODO comment (line 3138) notes that this flag should eventually be stored on invoices directly.', 'When enabled, retained warranty details appear only on the final situation invoice; when disabled, warranty from prior situation invoices is also rendered.', '1 = show retained warranty only on final situation invoice; empty/unset = show on all situation invoices.', 1, 0, NULL, 1, '5a46ec111d88392b7373afc4831523c95a1d59caa64bf63bb18c6e1542a67cec', 'v2', '2026-04-21T13:50:40+00:00', '["pdf_octopus.modules.php:3138  // TODO : add a flag on invoices to store this conf USE_RETAINED_WARRANTY_ONLY_FOR_SITUATION_FINAL", "pdf_octopus.modules.php:3056|check|if (! empty($previousInvoice->retained_warranty) && !getDolGlobalString(''USE_RETAINED_WARRANTY_ONLY_FOR_SITUATION_FINAL'')) {", "pdf_octopus.modules.php:3146|check|if ($object->isSituationInvoice() && getDolGlobalString(''USE_RETAINED_WARRANTY_ONLY_FOR_SITUATION_FINAL'')) {", "pdf_octopus.modules.php:175|write|$conf->global->USE_RETAINED_WARRANTY_ONLY_FOR_SITUATION_FINAL = 1;"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('USE_STRICT_CSV_RULES', 'bool', NULL, 'core', 'Enables strict RFC-compliant CSV formatting rules, including quoting cells that contain line breaks.', 'Checked in core/lib/functions2.lib.php:3096 and 3098; comments in exportcsv.class.php:214 and 273 say ''Clean data and add encloser if required (depending on value of USE_STRICT_CSV_RULES)'', and functions2.lib.php:3092 states: ''Rule 1 CSV: No CR, LF in cells (except if USE_STRICT_CSV_RULES is 1, we can keep record as it is but we must add quotes)''.', 'Setting to 1 allows cells with line breaks to be kept intact but forces them to be enclosed in quotes; leaving unset strips CR/LF from cell values.', '0 or unset = strip CR/LF from cells; 1 = preserve CR/LF but wrap cell in quotes.', 1, 0, NULL, 1, '088162910202092b7580f2ec95e950455d1cd658fd6e422e14332982538ff690', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/functions2.lib.php:3092  // Rule 1 CSV: No CR, LF in cells (except if USE_STRICT_CSV_RULES is 1, we can keep record as it is but we must add quotes)", "core/modules/export/exportcsv.class.php:214  // Clean data and add encloser if required (depending on value of USE_STRICT_CSV_RULES)", "core/lib/functions2.lib.php:3096|check|if (getDolGlobalString(''USE_STRICT_CSV_RULES'') && $oldvalue != $newvalue) {", "core/lib/functions2.lib.php:3098|check|if (getDolGlobalInt(''USE_STRICT_CSV_RULES'') == 1) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('UTF8UNICODE', 'string', NULL, 'core', 'Documentation placeholder: represents the pattern used by SQL migration scripts to conditionally run statements based on the database''s collation, via a comment marker like ''-- VMYSQLUTF8UNICODE'' tested against $conf->global->UTF8UNICODE-style constants.', 'Explained in a comment in core/lib/admin.lib.php:226 describing how a version-qualifier token in an SQL migration line (e.g. ''-- VMYSQLUTF8UNICODE'') is tested as a constant name, comparing it against the sanitized $conf->db->dolibarr_main_db_collation; actual migration markers use forms like VMYSQLUTF8UNICODECI (seen in install/mysql/migration/repair.sql).', 'This is not a directly user-settable configuration switch; it documents how the SQL migration loader decides whether to execute a given migration line based on the current DB collation string.', 'Exact behavior unclear from code alone [SPECULATION] beyond the collation-matching mechanism described in the comment.', 1, 0, NULL, 1, '84a2b6dd9ce563be37a2a1e102c02ea9bdfac856f2312f56d92cfba1ca639e3a', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/admin.lib.php:226: } else { // This is a test on a constant. For example when we have -- VMYSQLUTF8UNICODE, we test constant $conf->global->UTF8UNICODE", "core/lib/admin.lib.php:227: $dbcollation = strtoupper(preg_replace(''/_/'', '''', $conf->db->dolibarr_main_db_collation));", "install/mysql/migration/repair.sql:30: -- VMYSQLUTF8UNICODECI ALTER TABLE llx_accounting_account MODIFY account_number VARCHAR(20) CHARACTER SET utf8;"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('VARIANT_ALLOW_STOCK_MOVEMENT_ON_VARIANT_PARENT', 'bool', NULL, 'product', 'Allows stock movements to be recorded directly on a variant parent product instead of requiring selection of a specific child variant.', 'Set via variants/admin/admin.php:63 and read at admin.php:104. Checked in product/stock/replenish.php:431, product/stock/product.php:996, product/stock/product.php:1016, and product/stock/product.php:1026 to control whether parent-level stock movements are permitted.', 'When unset, stock movements on parent products with variants are excluded; only specific variant children can receive stock movements. When set, parent-level stock movements are allowed.', 'Truthy value = stock movements on variant parent allowed; empty/unset = movements restricted to child variants only.', 0, 0, 'variants/admin/admin.php|variants/admin/admin.php', 1, '4f8b953e32abb521541c6d7a2d7a4bafdefbcf1a4cd5174a8124f5b43c3c1660', 'v2', '2026-04-21T11:16:15+00:00', '["variants/admin/admin.php:63|write|if (!dolibarr_set_const($db, ''VARIANT_ALLOW_STOCK_MOVEMENT_ON_VARIANT_PARENT'', GETPOST(''VARIANT_ALLOW_STOCK_MOVEMENT_ON_VARIANT_PARENT''), ''chaine'', 0, '''', $conf->entity)) {", "product/stock/replenish.php:431|check|if (isModEnabled(''variants'') && !getDolGlobalString(''VARIANT_ALLOW_STOCK_MOVEMENT_ON_VARIANT_PARENT'')) {\t// Add test to exclude products that has variants", "product/stock/product.php:996|check|if ($variants && !getDolGlobalString(''VARIANT_ALLOW_STOCK_MOVEMENT_ON_VARIANT_PARENT'')) {", "product/stock/product.php:1016|check|if (!$variants || getDolGlobalString(''VARIANT_ALLOW_STOCK_MOVEMENT_ON_VARIANT_PARENT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('VATUPDATE_NO_TRANSACTION', 'string', NULL, 'product', 'Disables wrapping the mass VAT-rate update tool''s database changes in a transaction (begin/commit/rollback).', 'In product/admin/product_tools.php:79 and :284, the code only calls $db->begin() (and later commit()/rollback()) when this constant is falsy; when truthy, the VAT update runs without transaction wrapping.', 'Setting it removes transactional safety (atomic commit/rollback) around the mass VAT rate update process, so a failure partway through could leave data partially updated instead of being rolled back.', 'Boolean-like (read via getDolGlobalInt): truthy skips $db->begin()/commit()/rollback() around the VAT update.', 0, 0, 'product/admin/product_tools.php|product/admin/product_tools.php', 1, '38910cd50d2545a76863b020af5eb1704b157bbd3ba232a6138cd02b0499f3a6', 'v2', '2026-07-24T07:05:23+00:00', '["product/admin/product_tools.php:79|check|if (!getDolGlobalInt(''VATUPDATE_NO_TRANSACTION'')) {", "product/admin/product_tools.php:284|check|if (!getDolGlobalInt(''VATUPDATE_NO_TRANSACTION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WAREHOUSE_ASK_WAREHOUSE_DURING_ORDER', 'bool', NULL, 'commande', 'Prompts for a warehouse selection when creating or processing a customer order, when stock module is enabled.', 'Configured via admin/stock.php:847 (selectarray UI). Checked, always alongside isModEnabled(''stock''), in commande/card.php at lines 2279, 2433, and 3152, commande/list.php:1771, expedition/shipment.php:429, and commande/list_det.php at lines 979 and 223.', 'When enabled (and stock module active), order screens require/display a warehouse selection; the warehouse column is also conditionally shown/hidden in order line lists based on this setting.', NULL, 0, 0, 'admin/stock.php', 1, 'bcd5f4d823fde55d9adea957c6d04bdbe2e87e0a04e334c8f7266c77350771cf', 'v2', '2026-07-24T06:41:12+00:00', '["if (isModEnabled(''stock'') && empty($warehouse_id) && getDolGlobalString(''WAREHOUSE_ASK_WAREHOUSE_DURING_ORDER'')) {", "''c.fk_warehouse'' => array(''label'' => ''Warehouse'', ''checked'' => ''0'', ''enabled'' => (string) (int) (!isModEnabled(''stock'') && !getDolGlobalString(''WAREHOUSE_ASK_WAREHOUSE_DURING_ORDER"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WAREHOUSE_ASK_WAREHOUSE_DURING_PROJECT', 'bool', NULL, 'projet', 'Enables warehouse selection on the project elements overview page for stock-related operations.', 'Set via admin/stock.php:860 using a select array. Checked at projet/element.php:522 as the ''test'' condition for rendering the warehouse-related tab/element on the project overview. 2 occurrences across 2 files.', 'When unset, no warehouse selector is shown on the project elements page. When set to a truthy value and the stock module is enabled, the warehouse selection UI appears.', 'Truthy value = warehouse selection shown on project overview; 0 or unset = hidden.', 0, 0, 'admin/stock.php', 1, '2c7423bdd0216aab0c36d1caf94bfde074153e6837bf3173798d854d6ee46b64', 'v2', '2026-04-21T11:16:15+00:00', '["admin/stock.php:860|read|print $form->selectarray(\"WAREHOUSE_ASK_WAREHOUSE_DURING_PROJECT\", $arrval, getDolGlobalString(''WAREHOUSE_ASK_WAREHOUSE_DURING_PROJECT''));", "projet/element.php:522|read|''test'' => isModEnabled(''stock'') && $user->hasRight(''stock'', ''lire'') && getDolGlobalString(''WAREHOUSE_ASK_WAREHOUSE_DURING_PROJECT'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WAREHOUSE_ASK_WAREHOUSE_DURING_PROPAL', 'bool', NULL, 'comm', 'Enables warehouse selection during proposal creation and validation when the stock module is active.', 'When enabled and the stock module is active, the proposal workflow requires a warehouse to be selected during line creation and approval steps. Configurable via admin/stock.php. Seen in comm/propal/card.php and comm/propal/list.php.', 'Enabling this forces users to specify a warehouse on proposals, preventing validation without a valid warehouse selection when stock is managed.', 'Empty/unset = no warehouse prompt on proposals; truthy value = warehouse selection required.', 0, 0, 'admin/stock.php', 1, '11ab635bea90466539a857a2ce5c590c2f736b2a34cf54bcfc702b920bf200da', 'v2', '2026-04-21T13:29:58+00:00', '["admin/stock.php:835|read|print $form->selectarray(\"WAREHOUSE_ASK_WAREHOUSE_DURING_PROPAL\", $arrval, getDolGlobalString(''WAREHOUSE_ASK_WAREHOUSE_DURING_PROPAL''));", "comm/propal/card.php:2498|check|if (isModEnabled(''stock'') && getDolGlobalString(''WAREHOUSE_ASK_WAREHOUSE_DURING_PROPAL'')) {", "comm/propal/card.php:2349|check|if (isModEnabled(''stock'') && $warehouse_id < 0 && getDolGlobalString(''WAREHOUSE_ASK_WAREHOUSE_DURING_PROPAL'')) {", "comm/propal/list.php:1284|check|if (isModEnabled(''stock'') && getDolGlobalString(''WAREHOUSE_ASK_WAREHOUSE_DURING_PROPAL'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WAREHOUSE_DRAFT_WATERMARK', 'bool', NULL, 'core', 'Specifies the watermark text to stamp on draft stock movement PDF documents.', 'Checked and read in core/modules/movement/doc/pdf_standard_movementstock.modules.php at lines 969–970. When the movement object status is 0 (draft) and this constant is set, pdf_watermark() is called with the constant''s value as the watermark string. No admin UI write is present.', 'Setting this constant causes a watermark to appear on draft stock movement PDFs. Leaving it unset suppresses the watermark on those documents.', 'A non-empty string = watermark text rendered on draft movement PDFs; empty or unset = no watermark.', 1, 0, NULL, 1, '022675c0549f7087cedb08d224c3bf65ade6b3ecd3f32a2265d7a6581ffaa32d', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/movement/doc/pdf_standard_movementstock.modules.php:969|check|if ($object->status == 0 && getDolGlobalString(''WAREHOUSE_DRAFT_WATERMARK'')) {", "core/modules/movement/doc/pdf_standard_movementstock.modules.php:970|read|pdf_watermark($pdf, $outputlangs, $this->page_hauteur, $this->page_largeur, ''mm'', getDolGlobalString(''WAREHOUSE_DRAFT_WATERMARK''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBHOOK_POST_SEND_DATA_AS_PARAM_STRING', 'string', NULL, 'webhook', 'Sends webhook POST data encoded as a parameter string, for compatibility with pre-v20 Dolibarr versions.', 'Checked in webhook/target_card.php:177 and core/triggers/interface_95_modWebhook_WebhookTriggers.class.php:123, both annotated ''For compatibility with v20- versions''.', 'When enabled, webhook POST payloads are sent as a parameter string rather than the newer default format, to preserve compatibility with older webhook consumers.', NULL, 0, 0, NULL, 1, '56003ec802c6a26b6b0163df48969578d5ba1290109bac34952b4ce6cf968964', 'v2', '2026-07-24T06:41:12+00:00', '["if (getDolGlobalString(''WEBHOOK_POST_SEND_DATA_AS_PARAM_STRING'')) {\t\t// For compatibility with v20- versions"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBHOOK_TARGET_ADDON', 'string', NULL, 'webhook', 'Name of the numbering module (addon) used to generate reference numbers for webhook ''target'' objects.', 'Read in webhook/class/target.class.php:979 with default ''mod_target_standard'', inside getNextNumRef() which returns the next free reference for a Target object depending on the active numbering module.', 'Changing it swaps which numbering-module class is used to generate the next reference for webhook Target objects; must name an existing/loadable numbering module class.', 'String: class name of a numbering module for Target objects; default ''mod_target_standard''.', 1, 0, NULL, 1, 'f89d182498a8de4118cf9b818c0e2751171fa204335f5ea35b4bd5eb52c7e13f', 'v2', '2026-07-24T07:05:23+00:00', '["webhook/class/target.class.php:979: $classname = getDolGlobalString(''WEBHOOK_TARGET_ADDON'', ''mod_target_standard'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_', 'string', NULL, 'webportal', 'Not a real constant but a dynamic name prefix for per-module WebPortal access flags, built as WEBPORTAL_<MODULE>_LIST_ACCESS or WEBPORTAL_<ELEMENT>_CARD_ACCESS.', 'webportal/controllers/document.controller.class.php:190 builds ''WEBPORTAL_'' . $moduleNameUpperEn . ''_LIST_ACCESS'' and html.formcardwebportal.class.php:180 builds ''WEBPORTAL_'' . $elementEnUpper . ''_CARD_ACCESS''. Concrete instances (e.g. WEBPORTAL_PROPAL_LIST_ACCESS, WEBPORTAL_INVOICE_LIST_ACCESS, WEBPORTAL_MEMBER_CARD_ACCESS) are defined with admin UI Yes/No toggles or select fields in webportal/admin/setup.php.', 'This bare ''WEBPORTAL_'' entry has no standalone meaning; the actual per-module constants (dynamically composed) control whether a given document list or card is visible/accessible in the WebPortal for that module/element.', 'Not a single value; concrete suffixed constants are Yes/No (LIST_ACCESS) or a select/string like ''hidden'' (CARD_ACCESS default).', 0, 0, NULL, 1, '8c10c64cd8007332f340783bd2b607ea878843ac04649297d6b05adc40b1b76d', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/controllers/document.controller.class.php:190: if (getDolGlobalInt(''WEBPORTAL_'' . $moduleNameUpperEn . ''_LIST_ACCESS'')", "webportal/class/html.formcardwebportal.class.php:180: $elementCardAccess = getDolGlobalString(''WEBPORTAL_'' . $elementEnUpper . ''_CARD_ACCESS'', ''hidden'');", "webportal/admin/setup.php:113: $formSetup->newItem(''WEBPORTAL_INVOICE_LIST_ACCESS'')->setAsYesNo();"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_BANNER_BACKGROUND', 'string', NULL, 'webportal', 'URL of the background image used for the WebPortal banner/header.', 'Read in webportal/class/webPortalTheme.class.php:121 as bannerBackground; has an admin UI URL field in webportal/admin/setup_theme.php:110.', 'Setting a URL replaces the default banner background image shown in the WebPortal header area.', 'String URL; admin field type is a URL input.', 0, 0, NULL, 1, '2a0a752819d78c705812ce752b3f80827269f99a49ed23cf9e6f9d9c98c62833', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/class/webPortalTheme.class.php:121: $this->bannerBackground = getDolGlobalString(''WEBPORTAL_BANNER_BACKGROUND'');", "webportal/admin/setup_theme.php:110: $item = $formSetup->newItem(''WEBPORTAL_BANNER_BACKGROUND''); $item->fieldAttr = array(''type''=>''url'', ''size''=> 50, ''placeholder''=>''https://'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_BANNER_BACKGROUND_IS_DARK', 'string', NULL, 'webportal', 'Flags whether the WebPortal banner background image/color is dark, so the theme can pick contrasting text/icon colors.', 'Read in webportal/class/webPortalTheme.class.php:122 as bannerUseDarkTheme; has an admin UI Yes/No toggle in webportal/admin/setup_theme.php:114.', 'Toggling it switches the WebPortal banner''s foreground styling (e.g. text/icon color) to suit a dark vs light banner background.', 'Yes/No (admin UI setAsYesNo).', 0, 0, NULL, 1, 'bfc505969c19db23a06c4a240bd2a73487e59e819077eebedcde51134636ceee', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/class/webPortalTheme.class.php:122: $this->bannerUseDarkTheme = getDolGlobalInt(''WEBPORTAL_BANNER_BACKGROUND_IS_DARK'');", "webportal/admin/setup_theme.php:114: $item = $formSetup->newItem(''WEBPORTAL_BANNER_BACKGROUND_IS_DARK'')->setAsYesNo();"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_CDN_URL', 'string', NULL, 'webportal', 'Overrides the CDN base URL used by the WebPortal to serve public static assets, to hide the real public URL.', 'In webportal/class/context.class.php:217, $this->cdnUrl defaults to dol_buildpath(''/public/includes/'', 3) and is described in the preceding comment as settable ''IN HIDDEN CONF'' because ''IN SOME CASES IT COULD BE IMPORTANT TO HIDE PUBLIC URL''.', 'Setting it changes the base URL used for WebPortal static asset delivery, letting an admin serve assets from a different (e.g. CDN) domain instead of the default public path.', 'String URL (trailing slash trimmed); default dol_buildpath(''/public/includes/'', 3).', 1, 0, NULL, 1, '41d8363e0b0715304937f855dcdd68d09d8288414ee23fbc900c647cd400b43a', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/class/context.class.php:216: // BECAUSE IN SOME CASES IT COULD BE IMPORTANT TO HIDE PUBLIC URL BUT YOU CAN SET A CDN URL IN HIDDEN CONF", "webportal/class/context.class.php:217: $this->cdnUrl = getDolGlobalString(''WEBPORTAL_CDN_URL'', dol_buildpath(''/public/includes/'', 3));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_CUSTOM_CSS', 'string', NULL, 'webportal', 'Stores the custom CSS content for the web portal, served directly as part of the portal''s custom stylesheet.', 'Written in webportal/admin/configcss.php:85 from CSS editor input. Read in webportal/admin/configcss.php:147 for display and printed directly in public/webportal/css/themes/custom.css.php:101.', 'Changing this constant updates the custom CSS applied to the public web portal immediately upon the next page load.', 'String containing raw CSS; empty/unset = no custom styles applied.', 0, 0, 'webportal/admin/configcss.php|webportal/admin/configcss.php', 1, '388e301120440c2cf57fbaee216f4b16e6f3760f48cd4dce471bb6333d92ccc0', 'v2', '2026-04-21T11:16:15+00:00', '["webportal/admin/configcss.php:85|write|dolibarr_set_const($db, \"WEBPORTAL_CUSTOM_CSS\", $csscontent, ''chaine'', 0, '''', $conf->entity);", "webportal/admin/configcss.php:147|read|$customcssValue = getDolGlobalString(''WEBPORTAL_CUSTOM_CSS'');", "public/webportal/css/themes/custom.css.php:101|read|print getDolGlobalString(''WEBPORTAL_CUSTOM_CSS'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_DOCUMENT_LIST_ACCESS', 'string', NULL, 'public', 'Sets the access right level for the document list feature in the WebPortal.', 'Read in public/webportal/tpl/menu.tpl.php:86 to conditionally show the menu entry, and assigned to $this->accessRight in webportal/controllers/documentlist.controller.class.php:46.', 'Changing this value changes whether/how the document list menu entry and controller access are permitted in the WebPortal.', NULL, 0, 0, NULL, 1, '9b25ca653c63cac3f3e9dee463e20b317713d728657deb1b233c8ff8cfa30009', 'v2', '2026-07-24T06:41:12+00:00', '["$this->accessRight = getDolGlobalInt(''WEBPORTAL_DOCUMENT_LIST_ACCESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_FICHEINTER_LIST_ACCESS', 'string', NULL, 'public', 'Sets the access right level for the intervention (fiche inter) list feature in the WebPortal, when the intervention module is enabled.', 'Read in public/webportal/tpl/menu.tpl.php:66 (gated on isModEnabled(''intervention'')) and assigned to $this->accessRight in webportal/controllers/ficheinterlist.controller.class.php:39.', 'Changing this value changes whether/how the intervention list menu entry and controller access are permitted in the WebPortal, only when the intervention module is active.', NULL, 0, 0, NULL, 1, '36c3866268999db396a09c17333ff68fcf283f2b22bae261201bb35008980610', 'v2', '2026-07-24T06:41:12+00:00', '["$this->accessRight = isModEnabled(''intervention'') && getDolGlobalInt(''WEBPORTAL_FICHEINTER_LIST_ACCESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_INVOICE_LIST_ACCESS', 'string', NULL, 'public', 'Controls whether the web portal exposes the customer invoices list to portal users.', 'Checked in public/webportal/tpl/menu.tpl.php:56 and public/webportal/tpl/home.tpl.php:34 to show the menu item, and read in webportal/controllers/invoicelist.controller.class.php:40 to set the controller access right. No admin UI write found; HIDDEN_GUESS is 1.', 'When set to a non-zero value and the invoice module is enabled, portal users can access the invoices list; otherwise the list is hidden.', 'Integer: non-zero = access enabled; 0 or not set = access disabled', 1, 0, NULL, 1, '6eba51b0e84401965c2ad230445620c2d588ade08c4b23b2482b72d84a4d91c3', 'v2', '2026-04-21T11:16:15+00:00', '["public/webportal/tpl/menu.tpl.php:56|check|if (isModEnabled(''invoice'') && getDolGlobalInt(''WEBPORTAL_INVOICE_LIST_ACCESS'')) {", "public/webportal/tpl/home.tpl.php:34|check|<?php if (isModEnabled(''invoice'') && getDolGlobalInt(''WEBPORTAL_INVOICE_LIST_ACCESS'')) : ?>", "webportal/controllers/invoicelist.controller.class.php:40|read|$this->accessRight = isModEnabled(''invoice'') && getDolGlobalInt(''WEBPORTAL_INVOICE_LIST_ACCESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_LOGIN_BACKGROUND', 'string', NULL, 'webportal', 'URL of the background image used on the WebPortal login page.', 'Read in webportal/class/webPortalTheme.class.php:120 as loginBackground; has an admin UI URL field in webportal/admin/setup_theme.php:107.', 'Setting a URL replaces the default background image displayed behind the WebPortal login form.', 'String URL; admin field type is a URL input.', 0, 0, NULL, 1, '06916a01cf371308bd73b876dfc0b88963a43e5af97e9518c4bec6b769378c6d', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/class/webPortalTheme.class.php:120: $this->loginBackground = getDolGlobalString(''WEBPORTAL_LOGIN_BACKGROUND'');", "webportal/admin/setup_theme.php:107: $item = $formSetup->newItem(''WEBPORTAL_LOGIN_BACKGROUND''); $item->fieldAttr = array(''type''=>''url'', ''size''=> 50, ''placeholder''=>''https://'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_LOGIN_BY_MEMBER_ACCOUNT', 'string', NULL, 'public', 'Controls whether web portal authentication is performed against member accounts rather than third-party (societe) accounts.', 'Checked at public/webportal/webportal.main.inc.php:192, :204, :241, and :297 to branch between member-based and third-party-based login flows. When non-zero and the member module is enabled, member account credentials are used for authentication.', 'Switching this value changes whether portal users are authenticated as members or as third-party contacts, affecting which records are accessible after login.', '0 or unset = third-party (societe) login; non-zero = member account login', 1, 0, NULL, 1, 'd6dfed887f8f0195c3d764878ce173f00c58184ffc6ee5b481fcbaed2dc84c74', 'v2', '2026-04-21T13:50:40+00:00', '["public/webportal/webportal.main.inc.php:192|check|if (!$error && (isModEnabled(''societe'') && !getDolGlobalInt(''WEBPORTAL_LOGIN_BY_MEMBER_ACCOUNT''))) {", "public/webportal/webportal.main.inc.php:241|check|if (isModEnabled(''member'') && getDolGlobalInt(''WEBPORTAL_LOGIN_BY_MEMBER_ACCOUNT'') && !getDolGlobalString(''ADHERENT_LOGIN_NOT_REQUIRED'')) {", "public/webportal/webportal.main.inc.php:297|check|if (!getDolGlobalInt(''WEBPORTAL_LOGIN_BY_MEMBER_ACCOUNT'')) {", "public/webportal/webportal.main.inc.php:204|read|} elseif (!$error && isModEnabled(''member'') && getDolGlobalInt(''WEBPORTAL_LOGIN_BY_MEMBER_ACCOUNT'') && !getDolGlobalString(''ADHERENT_LOGIN_NOT_REQUIRED'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_LOGIN_BY_MODULE', 'string', NULL, 'public', 'Delegates the WebPortal login/authentication phase to a module-provided login file instead of the default WebPortal login flow.', 'In public/webportal/webportal.main.inc.php:137, if getDolGlobalInt(''WEBPORTAL_LOGIN_BY_MODULE'') is set and $conf->modules_parts[''webportallogin''] is a non-empty array, the code includes the first module/file pair from that array instead of running the default login block.', 'Enabling it changes the authentication phase of the WebPortal to be handled by an external module''s login file (registered via modules_parts[''webportallogin'']); if that array is empty, the default login logic in the elseif branch still runs.', 'Boolean-like truthy check; actual login file is resolved from $conf->modules_parts[''webportallogin''].', 1, 0, NULL, 1, '0ad96d66391242ac9c3da7e4731557ce2e472a16043698aae049016c41894760', 'v2', '2026-07-24T07:05:23+00:00', '["public/webportal/webportal.main.inc.php:137: if (getDolGlobalInt(''WEBPORTAL_LOGIN_BY_MODULE'') && !empty($conf->modules_parts[''webportallogin'']) && is_array($conf->modules_parts[''webportallogin''])) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_LOGIN_FORM_THEME', 'string', NULL, 'public', 'Selects the visual theme (CSS class/body-class) used for the web portal login form.', 'Read in public/webportal/tpl/header_login.tpl.php:63 as getDolGlobalString(''WEBPORTAL_LOGIN_FORM_THEME'', ''default''); the value is then lower-cased and sanitized (spaces to dashes, non [a-z0-9-_] characters stripped) before being used, presumably as a CSS/body class.', 'Changing the value switches which theme name is applied to the web portal login page; only alphanumeric/dash/underscore characters survive sanitization.', 'Free-form string, sanitized to lowercase alphanumeric/dash/underscore; default ''default'' when unset.', 1, 0, NULL, 1, 'f959b9a75637309a9503152579d10125a07999538de4b0fbe6ca66d77ea314ed', 'v2', '2026-07-24T07:05:23+00:00', '["public/webportal/tpl/header_login.tpl.php:63: $loginFormTheme = getDolGlobalString(''WEBPORTAL_LOGIN_FORM_THEME'', ''default'');", "public/webportal/tpl/header_login.tpl.php: // Remove all characters except letters, numbers, dash and underscore"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_LOGIN_LOGO_URL', 'string', NULL, 'webportal', 'URL of the logo image shown on the WebPortal login page.', 'Read in webportal/class/webPortalTheme.class.php:118 as the loginLogoUrl theme property, with an admin UI field in webportal/admin/setup_theme.php:98 (URL text input).', 'Setting a URL replaces the default login logo shown to WebPortal customers/users on the login screen.', 'String URL (e.g. https://...); admin field type is a URL input.', 0, 0, NULL, 1, '22ea9ca32041be11a5177591c14aecbf7759c8d89e5a2d92a00e74f88f563b98', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/class/webPortalTheme.class.php:118: $this->loginLogoUrl = getDolGlobalString(''WEBPORTAL_LOGIN_LOGO_URL'', $urllogo);", "webportal/admin/setup_theme.php:98: $item = $formSetup->newItem(''WEBPORTAL_LOGIN_LOGO_URL''); $item->fieldAttr = array(''type''=>''url'', ''size''=> 50, ''placeholder''=>''https://'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_MEMBER_CARD_ACCESS', 'string', NULL, 'public', 'Sets the access mode for the member card feature in the WebPortal.', 'Read in public/webportal/tpl/menu.tpl.php:106 and public/webportal/tpl/home.tpl.php:40 (checked against the values ''visible'' or ''edit'', gated on the member module and a logged-in member context), and in webportal/controllers/membercard.controller.class.php at lines 72 and 43.', 'The value determines whether the member card is shown and whether it is editable; only ''visible'' or ''edit'' values are treated as granting access on the home template.', '''visible'' or ''edit'' grant access on the WebPortal home page (per home.tpl.php:40)', 0, 0, NULL, 1, '3ce5dccfc602b730cf3032c0154921c21306df19c93f8f1b6c3a4ffaa1ffeced', 'v2', '2026-07-24T06:41:12+00:00', '["<?php if (isModEnabled(''member'') && in_array(getDolGlobalString(''WEBPORTAL_MEMBER_CARD_ACCESS''), [''visible'', ''edit'']) && $context->logged_member && $context->logged_member->id > 0)"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_MENU_LOGO_URL', 'string', NULL, 'webportal', 'URL of the logo image shown in the WebPortal menu/header, falling back to the login logo if unset.', 'Read in webportal/class/webPortalTheme.class.php:119 as menuLogoUrl, defaulting to $this->loginLogoUrl; has an admin UI URL field in webportal/admin/setup_theme.php:101.', 'Setting a URL overrides the menu logo independently from the login logo; leaving it empty reuses the login logo URL.', 'String URL; admin field type is a URL input.', 0, 0, NULL, 1, '609945b564e2927030ecee64513adf5e783294698ba80b998f910b0a55929aee', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/class/webPortalTheme.class.php:119: $this->menuLogoUrl = getDolGlobalString(''WEBPORTAL_MENU_LOGO_URL'', $this->loginLogoUrl);", "webportal/admin/setup_theme.php:101: $item = $formSetup->newItem(''WEBPORTAL_MENU_LOGO_URL''); $item->fieldAttr = array(''type''=>''url'', ''size''=> 50, ''placeholder''=>''https://'');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_ORDER_LIST_ACCESS', 'string', NULL, 'public', 'Controls whether the order list section is accessible in the web portal.', 'Checked at public/webportal/tpl/menu.tpl.php:46 and public/webportal/tpl/home.tpl.php:28 to conditionally show order-related UI, and read at webportal/controllers/orderlist.controller.class.php:41 to set the access right. The order module must also be enabled.', 'Setting a non-zero value (with the order module enabled) grants access to the order list in the web portal; a zero or absent value hides it.', '0 or not set = order list hidden/inaccessible; non-zero = order list accessible (requires order module enabled).', 1, 0, NULL, 1, 'a31835253484a8e2faafb66d705eec7b896cc7960c2dabcb6f1ed83e17154cfd', 'v2', '2026-04-21T11:16:15+00:00', '["public/webportal/tpl/menu.tpl.php:46|check|if (isModEnabled(''order'') && getDolGlobalInt(''WEBPORTAL_ORDER_LIST_ACCESS'')) {", "public/webportal/tpl/home.tpl.php:28|check|<?php if (isModEnabled(''order'') && getDolGlobalInt(''WEBPORTAL_ORDER_LIST_ACCESS'')) : ?>", "webportal/controllers/orderlist.controller.class.php:41|read|$this->accessRight = isModEnabled(''order'') && getDolGlobalInt(''WEBPORTAL_ORDER_LIST_ACCESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_PARAMS_REV', 'string', NULL, 'public', 'Tracks a revision counter used to cache-bust the WebPortal''s CSS stylesheet URLs.', 'Incremented and written via dolibarr_set_const in webportal/admin/configcss.php:90 (value + 1), and used as a ''revision'' query parameter for stylesheet links in public/webportal/tpl/header.tpl.php at lines 65 and 66.', 'Incrementing this value forces browsers to reload the WebPortal CSS stylesheets by changing the revision query parameter in their URLs.', NULL, 0, 0, 'webportal/admin/configcss.php|webportal/admin/configcss.php', 1, '69434514cca45893093022c10a980ac9a4ea7b4a66d30164d05305c902f85c81', 'v2', '2026-07-24T06:41:12+00:00', '["dolibarr_set_const($db, \"WEBPORTAL_PARAMS_REV\", getDolGlobalInt(''WEBPORTAL_PARAMS_REV'') + 1, ''chaine'', 0, '''', $conf->entity);", "<link rel=\"stylesheet\" href=\"<?php print $context->rootUrl.''css/style.css.php?revision=''.getDolGlobalInt(''WEBPORTAL_PARAMS_REV''); ?>\">"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_PARTNERSHIP_CARD_ACCESS', 'string', NULL, 'webportal', 'Controls the access level for the partnership card page in the web portal.', 'Read in webportal/controllers/partnershipcard.controller.class.php at lines 43 and 71, and in public/webportal/tpl/menu.tpl.php:121, stored in $cardAccess and used to determine portal display and access. No admin UI write found; HIDDEN_GUESS is 1.', 'The value of this constant is used directly as the cardAccess variable controlling which portal users can view the partnership card.', 'String: access control value (exact semantics determined by controller logic); empty = no access', 1, 0, NULL, 1, '25627f45c1815f2d809980e3c04822ca2e4fb91879d806be9ec828ae52aa02dd', 'v2', '2026-04-21T11:16:15+00:00', '["webportal/controllers/partnershipcard.controller.class.php:43|read|$cardAccess = getDolGlobalString(''WEBPORTAL_PARTNERSHIP_CARD_ACCESS'');", "webportal/controllers/partnershipcard.controller.class.php:71|read|$cardAccess = getDolGlobalString(''WEBPORTAL_PARTNERSHIP_CARD_ACCESS'');", "public/webportal/tpl/menu.tpl.php:121|read|$cardAccess = getDolGlobalString(''WEBPORTAL_PARTNERSHIP_CARD_ACCESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_PRIMARY_COLOR', 'string', NULL, 'webportal', 'Sets the primary/secondary theme color used across the WebPortal UI.', 'Read in webportal/class/webPortalTheme.class.php:134-135 as $outColor, falling back to the theme''s computed primaryColorHex if unset. Admin UI in webportal/admin/setup_theme.php:75-77 exposes it as a color picker (setAsColor) defaulting to $webPortalTheme->primaryColorHex.', 'Changing the color value re-themes the WebPortal''s primary UI accents; unset values fall back to the computed default primary color.', 'String color value (hex), admin field type is a color picker.', 0, 0, NULL, 1, '94d2fb42c0315eb0f9e1f230d613dbec4f9b4f0aa8b04c90994efceea7269485', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/class/webPortalTheme.class.php:135: $outColor = getDolGlobalString(''WEBPORTAL_PRIMARY_COLOR'');", "webportal/admin/setup_theme.php:75-77: $item = $formSetup->newItem(''WEBPORTAL_PRIMARY_COLOR''); $item->setAsColor(); $item->defaultFieldValue = $webPortalTheme->primaryColorHex;"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_PROPAL_LIST_ACCESS', 'string', NULL, 'public', 'Controls whether the web portal exposes the customer proposals (quotes) list to portal users.', 'Checked in public/webportal/tpl/menu.tpl.php:36 and public/webportal/tpl/home.tpl.php:22 to show the menu item, and read in webportal/controllers/propallist.controller.class.php:41 to set the controller access right. No admin UI write found; HIDDEN_GUESS is 1.', 'When set to a non-zero value and the propal module is enabled, portal users can access the proposals list; otherwise the list is hidden.', 'Integer: non-zero = access enabled; 0 or not set = access disabled', 1, 0, NULL, 1, 'ab1a30f6f6ffd7b80fa314681b97a07a28d8e63e63afe74c0d8b7629ba923d97', 'v2', '2026-04-21T11:16:15+00:00', '["public/webportal/tpl/menu.tpl.php:36|check|if (isModEnabled(''propal'') && getDolGlobalInt(''WEBPORTAL_PROPAL_LIST_ACCESS'')) {", "public/webportal/tpl/home.tpl.php:22|check|if (isModEnabled(''propal'') && getDolGlobalInt(''WEBPORTAL_PROPAL_LIST_ACCESS'')) : ?>", "webportal/controllers/propallist.controller.class.php:41|read|$this->accessRight = isModEnabled(''propal'') && getDolGlobalInt(''WEBPORTAL_PROPAL_LIST_ACCESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_ROOT_URL', 'string', NULL, 'webportal', 'Overrides the root URL of the web portal, used to build links and module entry points.', 'Checked and read in webportal/class/context.class.php (lines 331-332). Also used in core/modules/modWebPortal.class.php (line 291) as `''url'' => getDolGlobalString(''WEBPORTAL_ROOT_URL'', ''/public/webportal/index.php'')`.', 'Setting this value changes the base URL from which the web portal is accessed.', 'String (absolute URL or path); empty means `/public/webportal/index.php` is used as the default.', 1, 0, NULL, 1, '0aa918073c4fd1a3f9703576deb0c84eb7c175a7347925814aaba408d816af43', 'v2', '2026-04-21T11:16:15+00:00', '["webportal/class/context.class.php:331|check|if (getDolGlobalString(''WEBPORTAL_ROOT_URL'')) {", "webportal/class/context.class.php:332|read|$rootUrl = getDolGlobalString(''WEBPORTAL_ROOT_URL'');", "core/modules/modWebPortal.class.php:291|read|''url'' => getDolGlobalString(''WEBPORTAL_ROOT_URL'', ''/public/webportal/index.php''),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_SHARED_DOCS_DIR', 'string', NULL, 'webportal', 'Sets the subfolder name (inside the ECM documents directory) used as the shared documents root browsed by the WebPortal shared-documents controller.', 'In webportal/controllers/shareddocuments.controller.class.php:96, $shared_dir_name defaults to ''Documentscomptes'' and is used to build $base_dir_ged_partage = $conf->ecm->dir_output . ''/'' . $shared_dir_name, the base path listed via dol_dir_list.', 'Changing it points the WebPortal ''shared documents'' browser at a different subfolder under the ECM output directory instead of the default ''Documentscomptes'' folder.', 'String folder name, default ''Documentscomptes''.', 1, 0, NULL, 1, '17da1035756cdfcaab4e064f0c6580f33bf3860110426ded5aee71225149c4d2', 'v2', '2026-07-24T07:05:23+00:00', '["webportal/controllers/shareddocuments.controller.class.php:96: $shared_dir_name = getDolGlobalString(''WEBPORTAL_SHARED_DOCS_DIR'', ''Documentscomptes'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_SHARED_DOCUMENT_ACCESS', 'string', NULL, 'public', 'Sets the access right level for the shared documents feature in the WebPortal.', 'Read in public/webportal/tpl/menu.tpl.php:96 to conditionally show the menu entry, and assigned to $this->accessRight in webportal/controllers/shareddocuments.controller.class.php:36.', 'Changing this value changes whether/how the shared documents menu entry and controller access are permitted in the WebPortal.', NULL, 0, 0, NULL, 1, 'c135914d3e01c27ba46a19a3bf6a94785c730a23f8f589a27b8684595789af42', 'v2', '2026-07-24T06:41:12+00:00', '["$this->accessRight = getDolGlobalInt(''WEBPORTAL_SHARED_DOCUMENT_ACCESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_TICKET_LIST_ACCESS', 'string', NULL, 'public', 'Sets the access right level for the ticket list feature in the WebPortal, when the ticket module is enabled.', 'Read in public/webportal/tpl/menu.tpl.php:76 (gated on isModEnabled(''ticket'')) and assigned to $this->accessRight in webportal/controllers/ticketlist.controller.class.php:45.', 'Changing this value changes whether/how the ticket list menu entry and controller access are permitted in the WebPortal, only when the ticket module is active.', NULL, 0, 0, NULL, 1, 'bc2fe0382251897709fdc57f5134d71b1b0f02e199ffa594c6dae616b68c7f19', 'v2', '2026-07-24T06:41:12+00:00', '["$this->accessRight = isModEnabled(''ticket'') && getDolGlobalInt(''WEBPORTAL_TICKET_LIST_ACCESS'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_TITLE', 'string', NULL, 'public', 'Sets a custom title/brand name displayed in the WebPortal, falling back to the company name.', 'Read in webportal/class/context.class.php:206 to set appliName, falling back to MAIN_INFO_SOCIETE_NOM, and in public/webportal/tpl/menu.tpl.php:253 to set $brandTitle with the same fallback.', 'When set, the WebPortal displays this custom title instead of the company name (MAIN_INFO_SOCIETE_NOM).', NULL, 0, 0, NULL, 1, '1c75a1d4d0ef4cbad6f8a5a22b6b1b731689cbe63a609d037539afe0003c6472', 'v2', '2026-07-24T06:41:12+00:00', '["$this->appliName = getDolGlobalString(''WEBPORTAL_TITLE'', getDolGlobalString(''MAIN_INFO_SOCIETE_NOM''));", "$brandTitle = getDolGlobalString(''WEBPORTAL_TITLE'') ? getDolGlobalString(''WEBPORTAL_TITLE'') : getDolGlobalString(''MAIN_INFO_SOCIETE_NOM'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBPORTAL_USER_LOGGED', 'string', NULL, 'public', 'Stores the internal Dolibarr user id used to represent the currently logged-in WebPortal session.', 'Configured via webportal/admin/setup.php:77 using select_dolusers to pick a user, and read in public/webportal/webportal.main.inc.php:273 to set $user_id.', 'Changing this value changes which internal Dolibarr user account the WebPortal session is associated with.', NULL, 0, 0, 'webportal/admin/setup.php', 1, 'da72c03931f4b587ef0c9caeda870e604c9f8c13e7386746bf1d7925a4c01c0c', 'v2', '2026-07-24T06:41:12+00:00', '["$user_id = getDolGlobalInt(''WEBPORTAL_USER_LOGGED'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSERVICES_KEY', 'string', NULL, 'webservices', 'Sets the authentication key required to call the SOAP webservices API.', 'Configured via webservices/admin/index.php (write at line 56, input field at line 96) and checked in core/lib/ws.lib.php:44 by comparing the caller-provided dolibarrkey against this value.', 'Changing this key changes what value must be supplied as dolibarrkey by webservice clients to authenticate successfully; incorrect keys are rejected.', NULL, 0, 0, 'webservices/admin/index.php|webservices/admin/index.php', 1, '7c5b65ea7242b572a39baa0ced4023de9092ac1c14f357f8d0e1fc4798849db9', 'v2', '2026-07-24T06:41:12+00:00', '["if (!$error && ($authentication[''dolibarrkey''] != getDolGlobalString(''WEBSERVICES_KEY''))) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_', 'string', NULL, 'website', 'Prefix for per-website security policy constants (e.g. WEBSITE_{id}_SECURITY_FORCECSP) that store HTTP security header values for each website.', 'Read and displayed in admin/system/security.php at lines 909–923 for each website object; consumed in core/website.inc.php:156 and website/index.php:4456 to apply Content Security Policy and other HTTP security headers.', 'Setting these per-website constants overrides the HTTP security headers served with the website; leaving them unset results in undefined/default header values.', 'Any string value representing an HTTP security header policy; unset means the header uses the default (displayed as ''Undefined'' in the admin UI).', 0, 0, 'admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php|admin/system/security.php', 1, 'cc8e17ae712655a7c6167c1a97e6dde269801c5f05fbacfd36760f0885a4dd7a', 'v2', '2026-04-21T11:16:15+00:00', '["admin/system/security.php:909|read|print ''<strong>WEBSITE_''.$obj->id.''_SECURITY_FORCERP</strong> = ''.getDolGlobalString(''WEBSITE_''.$obj->id.''_SECURITY_FORCERP'', ''<span class=\"opacitymedium\">''.$langs->trans(\"Undefine", "admin/system/security.php:915|check|if (getDolGlobalString(''WEBSITE_''.$obj->id.''_SECURITY_FORCECSPPRO'')) {", "core/website.inc.php:156|read|$contentsecuritypolicy = getDolGlobalString(''WEBSITE_''.$website->id.''_SECURITY_FORCECSPRO'');", "website/index.php:4456|check|if (getDolGlobalString(\"WEBSITE_\".$object->id.\"_SECURITY_FORCECSPRO\")) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_ADD_CSS_TO_BODY', 'string', NULL, 'core', 'Stores additional CSS class names to inject into the body tag of website pages.', 'Checked and applied in core/lib/website.lib.php:434-435. When set, the value is appended to the existing class attribute of the <body id="bodywebsite" class="bodywebsite"> tag via str_replace.', 'Setting this constant adds the specified CSS classes to the website body tag, allowing custom styling. Clearing it leaves the body tag with its default classes only.', 'Any non-empty string = CSS class name(s) appended to the body element; empty/unset = no additional classes.', 1, 0, NULL, 1, 'fbbc7c705d961db0bb9e268aec4f1701943fcc28e20a9ce3f16060991a9026ad', 'v2', '2026-04-21T13:50:40+00:00', '["website.lib.php:434|if (getDolGlobalString(''WEBSITE_ADD_CSS_TO_BODY'')) {", "website.lib.php:435|$content = str_replace(''<body id=\"bodywebsite\" class=\"bodywebsite'', ''<body id=\"bodywebsite\" class=\"bodywebsite '' . getDolGlobalString(''WEBSITE_ADD_CSS_TO_BODY''), $content);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_ADD_PAGE_TYPE_PHPLIB', 'string', NULL, 'core', 'Would show ''library'' and ''service'' page-container types in the website page-type selector, if the code path were active.', 'The only reference, in core/class/html.formwebsite.class.php:143, sits inside a block comment (/* ... */) in selectTypeOfContainer(), so the getDolGlobalString(''WEBSITE_ADD_PAGE_TYPE_PHPLIB'') check is currently commented out and not executed.', 'As currently commented out in the source, setting this constant has no effect on the running code; it appears to be either dead/reserved functionality or a leftover from a removed feature.', 'Boolean-like intent per the commented code (would filter out ''library''/''service'' typecontainer options when unset), but inactive as the surrounding code is commented out.', 1, 0, NULL, 1, '2d391fcb2881e88a11f82800ffcef55ee6c0e6b5a0b57a87ffb001a3fee9497d', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/html.formwebsite.class.php:143|check|if (!getDolGlobalString(''WEBSITE_ADD_PAGE_TYPE_PHPLIB'')) {", "/*if (in_array($obj->typecontainer, array(''library'', ''service''))) { if (!getDolGlobalString(''WEBSITE_ADD_PAGE_TYPE_PHPLIB'')) { $i++; continue; } } */"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_ADD_RSS_FEED_INTO_SITEMAP', 'string', NULL, 'website', 'Adds an extra URL entry for the RSS feed wrapper (wrapper.php?rss=1) into the generated website sitemap.xml.', 'Checked in website/index.php:2935, guarded also by $addrsswrapper, with a comment noting ''Adding a RSS feed into a sitemap should not be required. The RSS contains pages that are already included into the sitemap and RSS feeds are not shown into index.''', 'Enabling it inserts a dedicated sitemap entry for the RSS feed URL, which per the code comment is not normally required since the feed''s pages are already listed elsewhere in the sitemap.', 'Boolean-like (getDolGlobalInt): non-zero adds the RSS feed URL to the sitemap; 0/unset (default) omits it.', 1, 0, NULL, 1, 'acd60c7b0a69e5c7716fef9e67ddd7da389b911481886ab45ffe74cfacfae653', 'v2', '2026-07-24T07:05:23+00:00', '["website/index.php:2935: if ($addrsswrapper && getDolGlobalInt(''WEBSITE_ADD_RSS_FEED_INTO_SITEMAP'')) {", "website/index.php: // Adding a RSS feed into a sitemap should not be required. The RSS contains pages that are already included into the sitemap and RSS feeds are not shown into index."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_ALLOW_CKEDITOR', 'bool', NULL, 'website', 'Shows a ''CKEditor'' button to edit website page content with CKEditor instead of only the raw HTML source editor.', 'Checked in website/index.php:3680: if set, prints an extra edit link to action=editcontent labeled ''CKEditor''; otherwise prints an HTML comment ''<!-- Add option WEBSITE_ALLOW_CKEDITOR to allow ckeditor -->''.', 'Enabling it exposes a CKEditor-based content editing option on website pages in addition to the default HTML source editor and meta editor.', 'Boolean-like (getDolGlobalInt): non-zero shows the CKEditor edit button; 0/unset (default) hides it.', 1, 0, NULL, 1, 'e757a53c62e4199b79c8cc070c6e15aca37e4f3ba8b3c994a34b8ede6d475cb0', 'v2', '2026-07-24T07:05:23+00:00', '["website/index.php:3680: if (getDolGlobalInt(''WEBSITE_ALLOW_CKEDITOR'')) {", "website/index.php: print ''<!-- Add option WEBSITE_ALLOW_CKEDITOR to allow ckeditor -->'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_ALLOW_FRAMES_ON_ALL_PAGES', 'bool', NULL, 'core', 'Globally permits all public website pages to be embedded in iframes, overriding per-page frame restrictions.', 'Checked in core/website.inc.php:119, 137, and 289 alongside the per-page $websitepage->allowed_in_frames flag; when set it bypasses the individual page restriction. Also checked in website template wrapper files. No admin UI is present.', 'Enabling this constant allows any page of the Dolibarr public website to be embedded in an iframe on any third-party site, which reduces clickjacking protection.', 'Boolean flag: truthy = framing allowed on all pages; 0 or unset = per-page allowed_in_frames setting is enforced.', 1, 0, NULL, 1, '69ee203e572ca433354444cc3f01c068ed69973cf9d585a89076ae476d30f5dd', 'v2', '2026-04-21T11:16:15+00:00', '["core/website.inc.php:119|check|if (empty($websitepage->allowed_in_frames) && !getDolGlobalString(''WEBSITE_ALLOW_FRAMES_ON_ALL_PAGES'')) {", "core/website.inc.php:137|check|if (empty($websitepage->allowed_in_frames) && !getDolGlobalString(''WEBSITE_ALLOW_FRAMES_ON_ALL_PAGES'')) {", "install/doctemplates/websites/website_template-association_exp/containers/wrapper.php:75|check|if (!getDolGlobalString(''WEBSITE_ALLOW_FRAMES_ON_ALL_PAGES'')) {", "website/samples/wrapper.php:80|check|if (!getDolGlobalString(''WEBSITE_ALLOW_FRAMES_ON_ALL_PAGES'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_ALLOW_OVERWRITE_GIT_SOURCE', 'bool', NULL, 'website', 'Allows overwriting of Git-tracked website source files during a site export or overwrite operation.', 'Checked in website/class/website.class.php:1787 and website/index.php:2619, :3302, :3305. When enabled, a UI element that would otherwise be hidden becomes visible. A commented-out link at website/index.php:3309 references the export-into-GIT action.', 'Enabling this constant permits overwriting files tracked by Git during website operations, which can result in loss of custom modifications to source files.', '0 (overwrite not allowed) or 1 (overwrite allowed)', 1, 0, NULL, 1, '4f5f7a81a5a6be9f5d1994ed81c6a010e3afcb0e81907804f449dd4ff4ef190d', 'v2', '2026-04-21T11:16:15+00:00', '["website/index.php:3302|read|$extraCssClass = getDolGlobalString(''WEBSITE_ALLOW_OVERWRITE_GIT_SOURCE'') ? ''hideobject'' : '''';", "website/class/website.class.php:1787|check|if (getDolGlobalString(''WEBSITE_ALLOW_OVERWRITE_GIT_SOURCE'')) {", "website/index.php:2619|check|if (getDolGlobalString(''WEBSITE_ALLOW_OVERWRITE_GIT_SOURCE'')) {", "website/index.php:3305|check|if (getDolGlobalString(''WEBSITE_ALLOW_OVERWRITE_GIT_SOURCE'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_DISABLE_CACHE_OF_CONTAINERS', 'bool', NULL, 'core', 'Disables the on-disk cache file used for rendered website containers/pages even when a cache delay is configured.', 'Checked in core/lib/website.lib.php:624; the cache file path ($fullpathcache) is only computed when $cachedelay > 0 AND this constant is not set, i.e. it overrides the cache-delay setting to fully disable container caching.', 'Enabling it prevents website page/container caching from being used at all, regardless of the configured cache delay, which can help during development/debugging of website content at the cost of performance.', 'Boolean: truthy value disables the container cache file mechanism even if $cachedelay > 0.', 1, 0, NULL, 1, '8c6475f5ef18265e53803ea1b8e69c8b10c7434dcfd3d73bcc3fc7c69096035d', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/website.lib.php:624|check|if ($cachedelay > 0 && !getDolGlobalString(\"WEBSITE_DISABLE_CACHE_OF_CONTAINERS\")) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_DISABLE_MAIN_LANGUAGE_INTO_LANGSUBDIR', 'bool', NULL, 'core', 'Prevents the main website language from being served under a language subdirectory path.', 'Checked as a negated condition at core/lib/website2.lib.php:102 and :530, both inside blocks that also test $object->otherlang. When set, the main-language-into-subdir routing logic is skipped.', 'Enabling this constant keeps the primary language content at the root URL path rather than under a language-code subdirectory, which affects multilingual URL structure.', 'Any truthy value disables main-language subdirectory routing; unset enables it when otherlang is configured.', 1, 0, NULL, 1, '54e2e482fcc407885423ca639b96a1738c4074b1c180565255b6de55644cccd3', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/website2.lib.php:102|check|if (!getDolGlobalString(''WEBSITE_DISABLE_MAIN_LANGUAGE_INTO_LANGSUBDIR'') && !empty($object->otherlang)) {", "core/lib/website2.lib.php:530|check|if (!getDolGlobalString(''WEBSITE_DISABLE_MAIN_LANGUAGE_INTO_LANGSUBDIR'') && is_object($object) && !empty($object->otherlang)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_DISALLOW_DOLLAR_UNDERSCORE', 'bool', NULL, 'core', 'Adds $_COOKIE/$_FILES/$_SESSION superglobal access to the list of forbidden PHP constructs when saving custom PHP code in Website module pages.', 'Checked in core/lib/website2.lib.php:1023 during validation of dynamic PHP content submitted for a website page; when set, occurrences of $_COOKIE[, $_FILES[, $_SESSION[ are neutralized and ''$_'' is added to $forbiddenphpstrings alongside the always-forbidden ''$$'' and ''}[''.', 'Enabling it tightens the security sandbox for website PHP snippets by additionally blocking direct use of $_COOKIE/$_FILES/$_SESSION (via the generic ''$_'' forbidden pattern), reducing what a user with ''writephp'' right can do in page code.', 'Boolean: truthy value adds ''$_'' (blocking $_COOKIE/$_FILES/$_SESSION patterns) to the forbidden PHP strings list; default forbidden list is just ''$$'' and ''}[''.', 1, 0, NULL, 1, 'dc350fee0f7556400fc00174b2e9be4b29b84dd02afef3498bac4b21441b5cd0', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/website2.lib.php:1023|check|if (getDolGlobalString(\"WEBSITE_DISALLOW_DOLLAR_UNDERSCORE\")) {", "$forbiddenphpstrings = array(''$$'', ''$_'', ''}['');"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_EDITINLINE', 'string', NULL, 'website', 'Enables inline editing mode in the website editor, allowing content to be edited directly on the page.', 'Set at website/index.php:469, deleted at line 475, and blocked by a commented line at 481 (''// Force disable of edit inline''). Checked at lines 3874 and 5983, and read at line 3715 to set the JavaScript variable isEditingEnabled.', 'When enabled, the website editor activates inline editing mode; when disabled, inline editing is not available.', 'Empty/unset or 0 = inline editing disabled; 1 = inline editing enabled.', 1, 0, NULL, 1, '99f9ba5e7269d5514ced27e734bd6c0e41749109ab5eec7055545a535934e0ac', 'v2', '2026-04-21T11:16:15+00:00', '["website/index.php:481  //dolibarr_set_const($db, ''WEBSITE_EDITINLINE'', 0); // Force disable of edit inline", "website/index.php:469|write|dolibarr_set_const($db, ''WEBSITE_EDITINLINE'', 1);", "website/index.php:3715|read|var isEditingEnabled = ''.(getDolGlobalString(\"WEBSITE_EDITINLINE\") ? ''true'' : ''false'').'';", "website/index.php:3874|check|if (!getDolGlobalString(''WEBSITE_EDITINLINE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_EDITINLINE_SAVE_CKEDITOR_EDIT', 'string', NULL, 'website', 'Enables experimental inline-edit saving of CKEditor content changes via ajax on website pages.', 'Checked in website/index.php:463 (shows a ''FeatureNotYetAvailable'' warning when not set) and website/index.php:3802 (guards the JS block that sends the edited CKEditor content back via ajax for update).', 'Enabling it activates an ajax-based auto-save of CKEditor edits during inline website editing; when disabled, the seteditinline action shows a ''feature not yet available'' warning instead.', 'Boolean-like (getDolGlobalString): non-empty enables the ajax CKEditor save behavior; empty/unset (default) shows a not-yet-available warning and skips the ajax send.', 1, 0, NULL, 1, '5a0dab482ba384e743b3b2fa8121d22ca161107ae7e8e94d13134b60264d755c', 'v2', '2026-07-24T07:05:23+00:00', '["website/index.php:463: if (!getDolGlobalString(''WEBSITE_EDITINLINE_SAVE_CKEDITOR_EDIT'')) {", "website/index.php: setEventMessages($langs->trans(\"FeatureNotYetAvailable\"), null, ''warnings'');", "website/index.php:3802: if (getDolGlobalString(''WEBSITE_EDITINLINE_SAVE_CKEDITOR_EDIT'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_EXPORT_KEEP_FILES_OF_PAGES', 'string', NULL, 'website', 'Controls whether generated PHP container files (page*.tpl.php and alias pages) of website pages are kept or deleted after a website export.', 'Checked in website/class/website.class.php:1144: if not set, the code deletes the pageX.tpl.php and alias page PHP files under dir_temp/.../containers/ for each exported page, per the comment ''We don''t need to keep the PHP files of pages and aliases (they are regenerated at import) so we remove them.''', 'Setting it to a truthy value skips the deletion of these regenerated PHP container files during export, leaving them in place instead of being cleaned up.', 'Boolean-like (getDolGlobalInt): non-zero keeps the PHP container files; 0/unset (default) deletes them after export since they are regenerated at import.', 1, 0, NULL, 1, 'c2a30b7c19eccfba405d89608ec8700c15ef7451bb1b8dcc3a359a8bcf641e2d', 'v2', '2026-07-24T07:05:23+00:00', '["website/class/website.class.php:1144: if (!getDolGlobalInt(''WEBSITE_EXPORT_KEEP_FILES_OF_PAGES'')) {", "website/class/website.class.php: // We don''t need to keep the PHP files of pages and aliases (they are regenerated at import) so we remove them."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_EXPORT_SQL_ON_SEVERAL_LINES', 'string', NULL, 'website', 'Adds a comment marker between exported SQL value fragments so a single-line SQL INSERT can later be restored to multiple readable lines.', 'Used twice in website/class/website.class.php (lines 1196 and 1217), each time appending "/* new line */\n" to the export buffer before the escaped string value, per inline comment ''Add a comment so we will able to restore a one line instruction on import''.', 'Enabling it makes the generated website export SQL file contain extra ''/* new line */'' comment markers between fields, purely for human readability of the export; does not affect functional import behavior beyond that marker.', 'Boolean-like (getDolGlobalString): non-empty inserts ''/* new line */'' markers in the export SQL; empty/unset (default) omits them.', 1, 0, NULL, 1, '823e761d64f66cc673ad66e6615bd2c3be397cdff899b4c747dbbcc8610e4042', 'v2', '2026-07-24T07:05:23+00:00', '["website/class/website.class.php:1196: if (getDolGlobalString(''WEBSITE_EXPORT_SQL_ON_SEVERAL_LINES'')) {", "website/class/website.class.php: $line .= \"/* new line */\\n\"; // Add a comment so we will able to restore a one line instruction on import"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_FORCE_DOCTYPE_HTML5', 'string', NULL, 'core', 'Forces generated website page templates to include an explicit <!DOCTYPE html> declaration.', 'Checked in core/lib/website2.lib.php:207 while building the PHP template content for a website page/container; when set, ''<!DOCTYPE html>'' is prepended to the generated HTML output.', 'Enabling it ensures rendered website pages declare HTML5 doctype, which can affect browser rendering mode (standards vs quirks mode) for pages built with the Website module.', 'Boolean: truthy value inserts ''<!DOCTYPE html>'' at the top of the generated page template.', 1, 0, NULL, 1, '9197c92788f48446de5e747dc486a0adbbb73ad3de9a5a85646e99f2ef2b9e49', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/website2.lib.php:207|check|if (getDolGlobalString(''WEBSITE_FORCE_DOCTYPE_HTML5'')) {", "$tplcontent .= \"<!DOCTYPE html>\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_MANAGE_IMAGE_FOR_PAGES', 'string', NULL, 'website', 'Legacy toggle that showed a manual ''WEBSITE_IMAGE'' field for a page''s RSS/thumbnail image; superseded by images taken automatically from page content.', 'Checked in website/index.php:4914, directly preceded by the comment ''Deprecated. Image for RSS or Thumbs are now taken from the content.''; when set it prints an extra WEBSITE_IMAGE text input row.', 'Enabling it re-exposes the deprecated manual per-page image field; the code comment indicates this behavior has been superseded and images are normally derived automatically from page content.', 'Boolean-like (getDolGlobalInt): non-zero shows the deprecated WEBSITE_IMAGE input field; 0/unset (default) hides it since it is deprecated.', 1, 0, NULL, 1, 'ad4d76a8019a10433ef659bfe9b39db0291fe18490e049acf1506efdcdd56143', 'v2', '2026-07-24T07:05:23+00:00', '["website/index.php:4914: if (getDolGlobalInt(''WEBSITE_MANAGE_IMAGE_FOR_PAGES'')) {", "website/index.php: // Deprecated. Image for RSS or Thumbs are now taken from the content."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_PAGE_SHOW_INTERNAL_LINKS_TO_OBJECT', 'bool', NULL, 'website', 'Shows extra ''ObjectClass''/''ObjectID'' fields on a website page allowing it to be linked to an internal Dolibarr object.', 'Checked in website/index.php:5050, marked with an inline TODO ''Replace this with link into element_element ?''; when set it prints text inputs for WEBSITE_OBJECTCLASS (placeholder ''ClassName::/path/class/ObjectClass.class.php'') and an ObjectID field.', 'Enabling it exposes manual fields on the page edit form to associate the page with an internal object class and id; the accompanying TODO indicates this is considered a temporary mechanism pending a proper element_element link.', 'Boolean-like (getDolGlobalString): non-empty shows the ObjectClass/ObjectID fields; empty/unset (default) hides them.', 1, 0, NULL, 1, '7604464d0680c24ee77c955606fe25c8918fa6ccde2026a3de7b858ab056de9a', 'v2', '2026-07-24T07:05:23+00:00', '["website/index.php:5050: if (getDolGlobalString(''WEBSITE_PAGE_SHOW_INTERNAL_LINKS_TO_OBJECT'')) {\t// TODO Replace this with link into element_element ?", "website/index.php: print ''<input type=\"text\" class=\"flat minwidth300\" name=\"WEBSITE_OBJECTCLASS\" placeholder=\"ClassName::/path/class/ObjectClass.class.php\" >'';"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_PERF_DISABLE_COUNTERS', 'bool', NULL, 'core', 'Disables incrementing the website page-view access counters for the Website module.', 'Checked in dolWebsiteIncrementCounter() in core/lib/website.lib.php:455; when the constant is falsy, the counter update logic (for ''blogpost''/''page'' types) executes; when truthy, it''s skipped.', 'Enabling it stops Dolibarr from recording/incrementing page-view counters for website pages and blog posts, which can reduce DB writes at the cost of losing view-count tracking.', 'Boolean: truthy value disables the page-access counter increment (performance option).', 1, 0, NULL, 1, 'caa33565e581a1b132c4b8f9b3ffe87e42030cf36f0cb4042621b93b37a583db', 'v2', '2026-07-24T07:05:23+00:00', '["core/lib/website.lib.php:455|check|if (!getDolGlobalInt(''WEBSITE_PERF_DISABLE_COUNTERS'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_PHP_ALLOW_DANGEROUS_CHARS', 'bool', NULL, 'core', 'Permits dangerous characters in website PHP page content that would otherwise be sanitised.', 'Checked as a negated condition at core/lib/website2.lib.php:1046 with inline comment ''If option is not on, we disallow functions to execute commands''.', 'Enabling this constant bypasses dangerous-character sanitisation in website PHP pages, which may allow injection of hazardous content; leaving it unset keeps sanitisation active.', 'Any truthy value permits dangerous characters; unset enforces sanitisation.', 1, 0, NULL, 1, 'b95d8ca241f0373363a2196e6cfec8501f8c4b7d76522668b6c65a8ede07eb08', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/website2.lib.php:1046|check|if (!getDolGlobalString(''WEBSITE_PHP_ALLOW_DANGEROUS_CHARS'')) {    // If option is not on, we disallow functions to execute commands"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_PHP_ALLOW_EXEC', 'bool', NULL, 'core', 'Permits execution of system commands (exec-family functions) within website PHP pages.', 'Checked as a negated condition at core/lib/website2.lib.php:993 with inline comment ''If option is not on, we disallow functions to execute commands''.', 'Enabling this constant unlocks system command execution from website pages, which is a significant security risk; leaving it unset keeps those functions blocked.', 'Any truthy value permits exec functions; unset or 0 disallows them.', 1, 0, NULL, 1, '52abc0148aa263f6dadf26b4a6681a5ea31b1e10a705e57f8f02be7a7517ec57', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/website2.lib.php:993|check|if (!getDolGlobalString(''WEBSITE_PHP_ALLOW_EXEC'')) {    // If option is not on, we disallow functions to execute commands"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_PHP_ALLOW_WRITE', 'bool', NULL, 'core', 'Permits file-write operations within website PHP pages.', 'Checked as a negated condition at core/lib/website2.lib.php:998 with inline comment ''If option is not on, we disallow functions to write files''.', 'Enabling this constant allows website PHP pages to write files to the filesystem; leaving it unset blocks file-write functions for security.', 'Any truthy value permits file-write functions; unset or 0 disallows them.', 1, 0, NULL, 1, '7f35b9b2e38c04dfcd88b2037038a7dc16a8b2c48a78ae81130b29e85e672ce3', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/website2.lib.php:998|check|if (!getDolGlobalString(''WEBSITE_PHP_ALLOW_WRITE'')) {    // If option is not on, we disallow functions to write files"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_PHP_DISALLOW_READ', 'bool', NULL, 'core', 'Disallows file-read operations within website PHP pages.', 'Checked at core/lib/website2.lib.php:1002 with inline comment ''If option is not on, we disallow functions to read files'', though the logic is inverted — it disallows reading when the constant IS set.', 'Setting this constant blocks file-read PHP functions in website pages, hardening security; leaving it unset allows file reads.', 'Any truthy value disallows file-read functions; unset permits them.', 1, 0, NULL, 1, '1673c8b7568ddec6083f47836649749ff74038996aee1dfac7a4ebc6b3ab2f38', 'v2', '2026-04-21T13:29:58+00:00', '["core/lib/website2.lib.php:1002|check|if (getDolGlobalString(''WEBSITE_PHP_DISALLOW_READ'')) {    // If option is not on, we disallow functions to read files"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_REPLACE_INFO_ABOUT_USAGE_WITH_WEBSERVER', 'string', NULL, 'website', 'Replaces the default ''how to deploy your website'' instructions block with a custom translated message.', 'Checked in website/index.php:3382-3384: if set, the code appends an HTML comment noting the translate key origin and prints $langs->trans(getDolGlobalString(''WEBSITE_REPLACE_INFO_ABOUT_USAGE_WITH_WEBSERVER'')) instead of the default 3-solutions deployment help text.', 'Setting this to a translation key replaces the built-in deployment help text (virtual host / webserver setup instructions) shown on the website admin page with a custom message.', 'String, used as a translation key passed to $langs->trans(); empty/unset (default) shows the built-in ''ToDeployYourWebsiteOnLiveYouHave3Solutions'' help text instead.', 1, 0, NULL, 1, 'd99b5fe90489821623c11944ad080e5e4b3377157e62b9d07b99fde67f517cc8', 'v2', '2026-07-24T07:05:23+00:00', '["website/index.php:3382: if (getDolGlobalString(''WEBSITE_REPLACE_INFO_ABOUT_USAGE_WITH_WEBSERVER'')) {", "website/index.php:3384: $htmltext .= ''<br>''.$langs->trans(getDolGlobalString(''WEBSITE_REPLACE_INFO_ABOUT_USAGE_WITH_WEBSERVER''));"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_SITEMAPS_ADD_WEEKLY_FREQ', 'string', NULL, 'website', 'Adds a weekly ''changefreq'' hint to URL entries in the generated website sitemap.xml.', 'Checked in website/index.php:2842 and 2947: if set, a <changefreq>weekly</changefreq> element is appended to each sitemap <url> entry (marked TODO to support other frequency values).', 'Enabling it makes the generated sitemap.xml advertise a weekly refresh frequency for pages to search engine crawlers; disabling it omits the changefreq element entirely.', 'Boolean-like (getDolGlobalString): non-empty adds changefreq=weekly to sitemap entries; empty/unset (default) omits changefreq.', 1, 0, NULL, 1, '87f0a9889a47b335ae23cb7ab8ee5bef43d1e7e4f047ea687ec7ace75c866fd7', 'v2', '2026-07-24T07:05:23+00:00', '["website/index.php:2842: if (getDolGlobalString(''WEBSITE_SITEMAPS_ADD_WEEKLY_FREQ'')) {", "website/index.php: $changefreq = $domtree->createElement(''changefreq'', ''weekly''); // TODO Manage other values"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEBSITE_SUBCONTAINERSINLINE', 'string', NULL, 'website', 'Enables the ''Include dynamic content'' (sub-containers inline) mode in the website editor.', 'Set programmatically in website/index.php at lines 480, 2747, and 3694 (and deleted at line 486); checked at lines 5955 and 3700. A commented line at 470 notes ''// Force disable of ''Include dynamic content''''. A comment at 5954 states ''// If mode WEBSITE_SUBCONTAINERSINLINE is on''.', 'When enabled, the website editor renders sub-containers inline within the page; when disabled, this dynamic content inclusion mode is off.', 'Empty/unset or 0 = sub-containers inline disabled; 1 = enabled (''Include dynamic content'' mode on).', 1, 0, NULL, 1, '07f28e71d640e593ef17f55aa0b85616e399b71f2deca59d682dc3d195e755c2', 'v2', '2026-04-21T11:16:15+00:00', '["website/index.php:470  //dolibarr_set_const($db, ''WEBSITE_SUBCONTAINERSINLINE'', 0); // Force disable of ''Include dynamic content''", "website/index.php:5954  // If mode WEBSITE_SUBCONTAINERSINLINE is on", "website/index.php:5955|check|if (getDolGlobalString(''WEBSITE_SUBCONTAINERSINLINE'')) {", "website/index.php:480|write|dolibarr_set_const($db, ''WEBSITE_SUBCONTAINERSINLINE'', 1);"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WEIGHINGSCALE_PROTOCOL', 'string', NULL, 'takepos', 'Selects the communication protocol used by the WHB weighing-scale connector in TakePOS; only the ''diag06'' value is handled specially.', 'Read at takepos/index.php:1108 inside WeighingScale(), nested under the TAKEPOS_CONNECTOR_TO_WHB_SCALE check: when equal to "diag06", the code fetches product data via the takeposconnector API before asking for weight.', 'Setting it to ''diag06'' triggers the Dialog-06 protocol branch, which needs the product''s unit price and calls the takeposconnector/products API before invoking askForWeight(); other/unset values skip this branch.', 'String: "diag06" enables the Dialog-06 protocol branch; other/unset values do not match this special case.', 1, 0, NULL, 1, '26026b7da59575ab6f87da77a96c669e7a0475ba00eff707d6eaa9471d392f7a', 'v2', '2026-07-24T07:05:23+00:00', '["takepos/index.php:1108|check|<?php if (getDolGlobalString(''WEIGHINGSCALE_PROTOCOL'') == \"diag06\") { ?> // Protocole Dialog-06, il a besoin du prix unitaire, le demander s''il manque"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WITHDRAWAL_ALLOW_ANY_INVOICE_STATUS', 'bool', NULL, 'compta', 'Removes the invoice status restriction when building direct debit or credit transfer payment batches.', 'When unset, bonprelevement.class.php:956, 1031, 1036, compta/prelevement/index.php:125, create.php:427, demandes.php:174, and compta/paymentbybanktransfer/index.php:143 all enforce a status filter on invoices eligible for withdrawal. Setting this constant bypasses that filter. No admin UI write path exists.', 'Enabling this constant allows invoices of any status to be included in withdrawal batches; without it, only invoices meeting the default status criteria are eligible.', 'Truthy string/bool=any status allowed, empty/0=status filter enforced', 1, 0, NULL, 1, 'da7d769eb7399b47dfa70c97d772e86d978949d8f5aa8252805e49d380113ec6', 'v2', '2026-04-21T11:16:15+00:00', '["compta/prelevement/class/bonprelevement.class.php:956|check|if (!getDolGlobalString(''WITHDRAWAL_ALLOW_ANY_INVOICE_STATUS'')) {", "compta/prelevement/class/bonprelevement.class.php:1031|check|if (!getDolGlobalString(''WITHDRAWAL_ALLOW_ANY_INVOICE_STATUS'')) {", "compta/prelevement/index.php:125|check|if (!getDolGlobalString(''WITHDRAWAL_ALLOW_ANY_INVOICE_STATUS'')) {", "compta/prelevement/create.php:427|check|if (!getDolGlobalString(''WITHDRAWAL_ALLOW_ANY_INVOICE_STATUS'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WITHDRAWAL_WITHOUT_BIC', 'string', NULL, 'societe', 'Allows bank withdrawal/direct-debit processing without requiring a valid BIC/Swift code.', 'Checked with getDolGlobalInt across compta/prelevement/class/bonprelevement.class.php (lines 1323 and 2511), societe/paymentmodes.php (lines 154, 158, 363, 2054, 2283), and compta/bank/class/account.class.php:1692, per the code comment there.', 'A non-valid BIC/Swift is a problem if it is not empty, or always a problem if WITHDRAWAL_WITHOUT_BIC is not set; when set (non-zero), BIC validation is bypassed for withdrawal/payment mode operations.', NULL, 0, 0, NULL, 1, '47a29d1ed8378561729a1d2cafe1714dc67f6c06e9e3a0f42bae30abbc11615e', 'v2', '2026-07-24T06:41:12+00:00', '["// A non valid BIC/Swift is a problem if: it is not empty or always a problem if WITHDRAWAL_WITHOUT_BIC is not set)."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WITHDRAW_STRICT_CHECK_AMOUNT', 'string', NULL, 'compta', 'Enables amount-based validation for direct debit withdrawal requests instead of request-count-based validation.', 'When set, compta/facture/prelevement.php:806 and 892 allow multiple partial withdrawal requests as long as the total does not exceed the invoice total. core/class/commoninvoice.class.php:1421 and 1573 check the sum of amounts rather than just counting requests.', 'Enabling this constant permits multiple partial debit requests up to the invoice total; disabling it enforces a simpler request-count check.', 'Truthy value enables sum-based amount checking; absent or falsy uses the default request-count check.', 1, 0, NULL, 1, '3721075a47c7dc53a6568c2b992db1a0cf585cad6f990c8c540543e34dcaffb9', 'v2', '2026-04-21T11:16:15+00:00', '["compta/facture/prelevement.php:804  // If WITHDRAW_STRICT_CHECK_AMOUNT is enabled, allow multiple partial requests as long as the total requested amount doesn''t exceed the invoice total", "core/class/commoninvoice.class.php:1420  // If WITHDRAW_STRICT_CHECK_AMOUNT is enabled, we check the sum of amounts instead of just counting requests", "compta/facture/prelevement.php:806|check|if (getDolGlobalString(''WITHDRAW_STRICT_CHECK_AMOUNT'')) {", "core/class/commoninvoice.class.php:1421|check|if (getDolGlobalString(''WITHDRAW_STRICT_CHECK_AMOUNT'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_BILL_ON_RECEPTION', 'string', NULL, 'reception', 'Controls whether the ''Billed'' column and billing workflow are active for receptions.', 'Checked in reception/card.php:2913 and 2923 to show the billing action button, and in reception/list.php:152 to enable the ''Billed'' column. Also referenced in admin/workflow.php:206 for workflow configuration. Configured via admin/workflow.php.', 'When not set to ''0'', the billed status column and create-invoice action are shown on reception pages; setting it to ''0'' hides them.', 'Any value other than ''0''=billing workflow active; ''0''=billing workflow disabled', 0, 0, 'admin/workflow.php', 1, '850b4e88dc630e753d3874c772b07c78b1768f2eb547e29c5c64f07f82da211d', 'v2', '2026-04-21T11:16:15+00:00', '["admin/workflow.php:206|read|''enabled'' => isModEnabled(\"reception\") && isModEnabled(\"supplier_invoice\") && getDolGlobalString(''WORKFLOW_BILL_ON_RECEPTION'') !== ''0'',", "reception/card.php:2913|check|if (getDolGlobalString(''WORKFLOW_BILL_ON_RECEPTION'') !== ''0'') {", "reception/list.php:152|read|''e.billed'' => array(''label'' => $langs->trans(\"Billed\"), ''checked'' => ''1'', ''position'' => 1000, ''enabled'' => ''getDolGlobalString(\"WORKFLOW_BILL_ON_RECEPTION\") !== \"0\"'')"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_BILL_ON_SHIPMENT', 'string', NULL, 'commande', 'Controls whether invoicing is triggered automatically when a shipment is validated, shifting the billing workflow from order to shipment.', 'Configured via admin/workflow.php (line 189). Checked in expedition/card.php:3812 and 3821 to trigger billing actions on shipment validation, and in commande/card.php:3639 and 3644 to suppress the ''classify billed'' action on orders when active. Also controls visibility of the ''Billed'' column in list views.', 'When set (and not ''0''), the billed status is managed at the shipment level rather than the order level, affecting column visibility and billing action availability across order and shipment UIs.', 'Non-''0'' truthy string to enable billing on shipment; ''0'' or empty to disable.', 0, 0, 'admin/workflow.php', 1, '2674205ef456a9837e3498a6583c7556040d8a381835cf9e9fe2f266dcbd9ed9', 'v2', '2026-04-21T13:50:40+00:00', '["admin/workflow.php:189|read|''enabled'' => isModEnabled(\"shipping\") && isModEnabled(\"invoice\") && getDolGlobalString(''WORKFLOW_BILL_ON_SHIPMENT'') !== ''0'',", "expedition/card.php:3812|check|if (getDolGlobalString(''WORKFLOW_BILL_ON_SHIPMENT'') !== ''0'') {", "commande/card.php:3639|check|if ($usercancreate && $object->status >= Commande::STATUS_VALIDATED && !getDolGlobalString(''ORDER_DISABLE_CLASSIFY_BILLED_FROM_ORDER'') && !getDolGlobalString(''WORKFLOW_BILL_ON_SHIP", "commande/list.php:267|read|''c.facture'' => array(''label'' => \"Billed\", ''checked'' => ''1'', ''enabled'' => (string) (int) (!getDolGlobalString(''WORKFLOW_BILL_ON_SHIPMENT'')), ''position'' => 995),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_CAN_CREATE_PURCHASE_ORDER_FROM_PROPOSAL', 'string', NULL, 'comm', 'Adds a ''Create purchase order'' action button on a signed proposal, letting users generate a supplier order directly from it.', 'Checked in comm/propal/card.php:3674; when set, an entry is pushed into $arrayforbutaction enabled only when status==STATUS_SIGNED and the supplier_order module is enabled.', 'Enabling it exposes an AddPurchaseOrder button on signed proposals (subject to the fourn/commande creer permission); default is no such button.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, 'bb5de3a1de5d21bbd1f7de9d4def8865e9a67d934d5e9ee03a954d0adef5089c', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:3674: if (getDolGlobalString(''WORKFLOW_CAN_CREATE_PURCHASE_ORDER_FROM_PROPOSAL'')) {", "comm/propal/card.php:3675: $arrayforbutaction[] = array("]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_CLASSIFY_IF_AMOUNTS_ARE_DIFFERENTS', 'string', NULL, 'core', 'Bypasses the amount-equality check used by the workflow module''s auto-classify-billed logic, forcing classification even when linked-element totals do not match.', 'Read only inside the private helper InterfaceWorkflowManager::shouldClassify() (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:671), which backs all the WORKFLOW_*_CLASSIFY_BILLED_* triggers. Not present in modWorkflow.class.php''s const array, admin/workflow.php''s checkbox list, or any workflow.lang description key, so it is a manual/expert-only constant with no admin UI exposure.', 'When set, shouldClassify() always returns true, so orders/proposals get classified billed regardless of whether the summed linked-element amount equals the object''s total; when unset, classification only happens if the rounded amounts match.', 'Per code comment: ''if the configuration allows unmatching amounts, allow classification anyway'' -- truthy disables the amount-equality safeguard.', 1, 0, NULL, 1, '2937bcb63118fbd7a734dc274f1096ad0b0b66540e502cc40d808c2a3cad46fd', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:671: if (getDolGlobalString(''WORKFLOW_CLASSIFY_IF_AMOUNTS_ARE_DIFFERENTS'')) { return true; }", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:670: // if the configuration allows unmatching amounts, allow classification anyway"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_DISABLE_CREATE_INVOICE_FROM_ORDER', 'bool', NULL, 'commande', 'Disables the action to create an invoice directly from an order.', 'Checked at compta/index.php:624 to hide the shortcut widget, and at commande/card.php:3610 to remove the ''create invoice'' permission entry, and at commande/card.php:3616 to hide the button. No admin UI is provided.', 'Enabling this constant removes the ''create invoice from order'' action from both the accounting dashboard and the order card, preventing direct invoice creation from orders.', 'Non-empty/truthy = invoice-from-order action disabled; empty/unset = action available.', 1, 0, NULL, 1, '43d97954e99ca8add357894b211fd4da173d8ca5d10710cbf7218abdef7381c4', 'v2', '2026-04-21T11:16:15+00:00', '["compta/index.php:624|check|if (isModEnabled(''invoice'') && isModEnabled(''order'') && $user->hasRight(\"commande\", \"lire\") && !getDolGlobalString(''WORKFLOW_DISABLE_CREATE_INVOICE_FROM_ORDER'')) {", "commande/card.php:3616|read|if (isModEnabled(''facture'') && $user->hasRight(''facture'', ''creer'') && empty($conf->global->WORKFLOW_DISABLE_CREATE_INVOICE_FROM_ORDER)) {", "commande/card.php:3610|read|''perm'' => ($user->hasRight(''facture'', ''creer'') && !getDolGlobalInt(''WORKFLOW_DISABLE_CREATE_INVOICE_FROM_ORDER'')),"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_INVOICE_AMOUNT_CLASSIFY_BILLED_ORDER', 'string', NULL, 'commande', 'Enables automatic classification of an order as billed based on invoiced amount, as part of the workflow module.', 'Checked in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:175 (requiring order module and workflow enabled), commande/list.php:1704, and expedition/list.php:1127.', 'When enabled, orders are automatically classified as billed once the invoiced amount condition is met, via the workflow trigger.', NULL, 0, 0, NULL, 1, '45c7c11af90b9c473d86664f2a7d88bf2bcc1f6f93a56385a959df4d63305e9e', 'v2', '2026-07-24T06:41:12+00:00', '["if (isModEnabled(''order'') && !empty($conf->workflow->enabled) && getDolGlobalString(''WORKFLOW_INVOICE_AMOUNT_CLASSIFY_BILLED_ORDER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_INVOICE_AMOUNT_CLASSIFY_BILLED_SUPPLIER_ORDER', 'string', NULL, 'core', 'Automatically marks a supplier order as billed when the invoiced amount reaches the order amount.', 'Checked in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:310. The comment at line 308 explicitly documents the intent: set purchase order to ''Billed'' if this constant is set.', 'Enabling this causes Dolibarr to set supplier orders to ''billed'' automatically when invoice amounts match.', '0 or empty = supplier order not auto-classified billed; non-empty = supplier order classified billed by invoice amount', 1, 0, NULL, 1, '16d5cf4c44f04faead4c9fa30110afaaf1f4fb9962f46770d0e72e6f8fa93ba8', 'v2', '2026-04-21T11:16:15+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:308  // Firstly, we set to purchase order to \"Billed\" if WORKFLOW_INVOICE_AMOUNT_CLASSIFY_BILLED_SUPPLIER_ORDER is set.", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:310|check|if ((isModEnabled(\"supplier_order\") || isModEnabled(\"supplier_invoice\")) && getDolGlobalString(''WORKFLOW_INVOICE_AMOUNT_CLASSIFY_BILLED_SUPPLIER_ORDER'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_INVOICE_CLASSIFY_BILLED_ORDER', 'string', NULL, 'core', 'Automatically classifies linked sales orders as billed once a customer invoice is set to fully paid.', 'Read in InterfaceWorkflowManager::runTrigger on action BILL_PAYED (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:413). Not present in modWorkflow.class.php''s const array nor in admin/workflow.php''s $workflowcodes list (unlike its siblings), but has a dedicated description key in langs/en_US/workflow.lang, suggesting it is legacy/manual-only rather than exposed as a checkbox in the current UI.', 'When set, validated/shipment-in-process/closed orders linked to the now-paid invoice are classified billed via classifyBilled(), gated by shouldClassify() comparing summed linked-order amount to the invoice total.', 'Truthy string enables the auto-classification; per langs/en_US/workflow.lang: ''When a customer invoice is set to paid, classify linked source sales orders as billed ... If you generate 1 invoice for n orders, this may set all orders to billed too.''', 1, 0, NULL, 1, '090e474cbfc6217b4c6caf35318b10041486ddea2ed0b4ea0e15b2f1aed3281a', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:413: if (isModEnabled(''order'') && getDolGlobalString(''WORKFLOW_INVOICE_CLASSIFY_BILLED_ORDER'')) {", "langs/en_US/workflow.lang:14: descWORKFLOW_INVOICE_CLASSIFY_BILLED_ORDER=When a customer invoice is set to paid, classify linked source sales orders as billed ... this may set all orders to billed too."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_INVOICE_CLASSIFY_BILLED_PROPAL', 'string', NULL, 'core', 'Automatically classifies linked proposals as billed when a customer invoice is validated.', 'Read in InterfaceWorkflowManager::runTrigger on action BILL_VALIDATE (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:199). Declared in core/modules/modWorkflow.class.php:88 and exposed as a checkbox in the ''classify_proposal'' family of admin/workflow.php (position 31).', 'When set, signed/billed proposals linked to the validated invoice are classified billed via classifyBilled(), gated by shouldClassify() comparing summed linked-proposal amount to the invoice total.', 'Truthy string enables the auto-classification; empty/unset disables it (checkbox in admin/workflow.php).', 0, 0, NULL, 1, '1488c2560e6e060fff58699585faff0d56ff38c61977ca99644de140a29844fb', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:199: if (isModEnabled(\"propal\") && !empty($conf->workflow->enabled) && getDolGlobalString(''WORKFLOW_INVOICE_CLASSIFY_BILLED_PROPAL'')) {", "core/modules/modWorkflow.class.php:88: 1 => array(''WORKFLOW_INVOICE_CLASSIFY_BILLED_PROPAL'', ''chaine'', ''1'', ...)", "admin/workflow.php:104: ''WORKFLOW_INVOICE_CLASSIFY_BILLED_PROPAL'' => array(''family'' => ''classify_proposal'', ''position'' => 31, ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_INVOICE_CLASSIFY_BILLED_SUPPLIER_PROPOSAL', 'string', NULL, 'core', 'Automatically marks a supplier proposal as billed when the linked supplier invoice is validated.', 'Checked in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:334. The comment at line 333 explicitly states: set the linked Proposal to ''Billed'' if this constant is set.', 'Enabling this causes the linked supplier proposal to be set to ''billed'' status automatically upon invoice validation.', '0 or empty = supplier proposal not auto-classified billed; non-empty = supplier proposal marked billed on invoice validation', 1, 0, NULL, 1, '794bc13982e9da49b5e32acedcaaa9597f1bd4e19dced556f96992f505eff1b1', 'v2', '2026-04-21T11:16:15+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:333  // Secondly, we set to linked Proposal to \"Billed\" if WORKFLOW_INVOICE_CLASSIFY_BILLED_SUPPLIER_PROPOSAL is set.", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:334|check|if (isModEnabled(''supplier_proposal'') && getDolGlobalString(''WORKFLOW_INVOICE_CLASSIFY_BILLED_SUPPLIER_PROPOSAL'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_ORDER_AUTOCREATE_INVOICE', 'string', NULL, 'core', 'Automatically creates a customer invoice when a sales order is closed.', 'Read in InterfaceWorkflowManager::runTrigger on action ORDER_CLOSE (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:115). Exposed as a checkbox in the ''create'' family of admin/workflow.php (position 20), toggled via the generic set/del action handler that calls dolibarr_set_const.', 'When set, closing an order auto-generates a linked Facture via createFromOrder(); if no bank account is set on the order but the thirdparty has a default one, it is applied unless BANK_ASK_PAYMENT_BANK_DURING_ORDER is set.', 'Truthy string enables auto-creation of the invoice; empty/unset disables it (checkbox in admin/workflow.php).', 0, 0, NULL, 1, '35837c85a2b27cd7b04b7acee7d900d4f35c823a344bc1c463eddf3844fd314d', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:115: if (isModEnabled(''invoice'') && getDolGlobalString(''WORKFLOW_ORDER_AUTOCREATE_INVOICE'')) {", "core/modules/modWorkflow.class.php:86: //0=>array(''WORKFLOW_ORDER_AUTOCREATE_INVOICE'', ''chaine'', ''1'', ''WORKFLOW_ORDER_AUTOCREATE_INVOICE'', 0, ''current'', 0),", "admin/workflow.php:81: ''WORKFLOW_ORDER_AUTOCREATE_INVOICE'' => array(''family'' => ''create'', ''position'' => 20, ''enabled'' => (isModEnabled(''order'') && isModEnabled(''invoice'')), ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_ORDER_CLASSIFY_BILLED_PROPAL', 'string', NULL, 'core', 'Automatically classifies linked proposals as billed when their linked sales order is classified billed.', 'Read in InterfaceWorkflowManager::runTrigger on action ORDER_CLASSIFY_BILLED (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:145). Declared in core/modules/modWorkflow.class.php:87 and exposed as a checkbox in the ''classify_proposal'' family of admin/workflow.php (position 30).', 'When set, all signed/billed proposals linked to the order are classified billed via classifyBilled(), but only if shouldClassify() finds the summed linked-proposal amount equal to the order total (unless WORKFLOW_CLASSIFY_IF_AMOUNTS_ARE_DIFFERENTS overrides that check).', 'Truthy string enables the auto-classification; empty/unset disables it (checkbox in admin/workflow.php).', 0, 0, NULL, 1, 'f469454700df7538cc0b424818b2afa8da5424abfeae771ba373390c498df456', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:145: if (isModEnabled(\"propal\") && !empty($conf->workflow->enabled) && getDolGlobalString(''WORKFLOW_ORDER_CLASSIFY_BILLED_PROPAL'')) {", "core/modules/modWorkflow.class.php:87: 0 => array(''WORKFLOW_ORDER_CLASSIFY_BILLED_PROPAL'', ''chaine'', ''1'', ''WORKFLOW_ORDER_CLASSIFY_BILLED_PROPAL'', 0, ''current'', 0),", "admin/workflow.php:97: ''WORKFLOW_ORDER_CLASSIFY_BILLED_PROPAL'' => array(''family'' => ''classify_proposal'', ''position'' => 30, ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_ORDER_CLASSIFY_RECEIVED_RECEPTION', 'string', NULL, 'core', 'Automatically marks a purchase order as fully received when its reception is validated and all ordered quantities have been received.', 'Read in InterfaceWorkflowManager::runTrigger on action RECEPTION_VALIDATE (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:526). Declared in core/modules/modWorkflow.class.php:94 and exposed as a checkbox in the ''classify_supplier_order'' family of admin/workflow.php (position 63), only shown when getDolGlobalString(''MAIN_FEATURES_LEVEL'') is set.', 'When set and a reception is validated, per-product quantities received vs ordered on the origin purchase order are compared; if there is no difference, the purchase order status is set to STATUS_RECEIVED_COMPLETELY.', 'Truthy string enables the auto-classification; empty/unset disables it (checkbox in admin/workflow.php, gated behind MAIN_FEATURES_LEVEL).', 0, 0, NULL, 1, 'ce33dea4b430d9a56bbf2f2e394da9c1f849374237e9567a0effa183fbfbd8ec', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:526: (getDolGlobalString(''WORKFLOW_ORDER_CLASSIFY_RECEIVED_RECEPTION'') && ($action == ''RECEPTION_VALIDATE'')) ||", "core/modules/modWorkflow.class.php:94: 7 => array(''WORKFLOW_ORDER_CLASSIFY_RECEIVED_RECEPTION'', ''chaine'', ''1'', ...)", "admin/workflow.php:151: ''enabled'' => (getDolGlobalString(''MAIN_FEATURES_LEVEL'') && isModEnabled(\"reception\") && isModEnabled(''supplier_order'')),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_ORDER_CLASSIFY_RECEIVED_RECEPTION_CLOSED', 'string', NULL, 'core', 'Automatically marks a purchase order as fully received when its reception is closed and all ordered quantities have been received.', 'Read in InterfaceWorkflowManager::runTrigger on action RECEPTION_CLOSED (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:527), sharing the same quantity-comparison logic as WORKFLOW_ORDER_CLASSIFY_RECEIVED_RECEPTION. Declared in core/modules/modWorkflow.class.php:95 and exposed as a checkbox in admin/workflow.php (position 64), gated behind MAIN_FEATURES_LEVEL.', 'When set and a reception is closed, per-product quantities received vs ordered on the origin purchase order are compared; if there is no difference, the purchase order status is set to STATUS_RECEIVED_COMPLETELY.', 'Truthy string enables the auto-classification; empty/unset disables it (checkbox in admin/workflow.php, gated behind MAIN_FEATURES_LEVEL).', 0, 0, NULL, 1, '8493289b250940fdac8eba0e48092a28ad9cd1fe1c21e99702c62020e4f61658', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:527: (getDolGlobalString(''WORKFLOW_ORDER_CLASSIFY_RECEIVED_RECEPTION_CLOSED'') && ($action == ''RECEPTION_CLOSED''))", "core/modules/modWorkflow.class.php:95: 8 => array(''WORKFLOW_ORDER_CLASSIFY_RECEIVED_RECEPTION_CLOSED'', ''chaine'', ''1'', ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING', 'string', NULL, 'core', 'Automatically closes a sales order when its shipment is validated and all ordered quantities have been shipped.', 'Read in InterfaceWorkflowManager::runTrigger on action SHIPPING_VALIDATE (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:444). Declared in core/modules/modWorkflow.class.php:89 and exposed as a checkbox in the ''classify_order'' family of admin/workflow.php (position 40).', 'When set and a shipment is validated, the code compares per-product quantities shipped vs ordered on the origin order; if there is no difference, the order is closed via $order->cloture($user).', 'Truthy string enables the auto-close on shipment validation; empty/unset disables it (checkbox in admin/workflow.php).', 0, 0, NULL, 1, 'a0dd7ee2b3710270a4b535dbb1a476a566fa861c2795bfb798fecde410755272', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:444: (getDolGlobalString(''WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING'') && ($action == ''SHIPPING_VALIDATE'')) ||", "core/modules/modWorkflow.class.php:89: 2 => array(''WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING'', ''chaine'', ''1'', ...)", "admin/workflow.php:113: ''WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING'' => array( // when shipping validated ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING_CLOSED', 'string', NULL, 'core', 'Automatically closes a sales order when its shipment is closed and all ordered quantities have been shipped.', 'Read in InterfaceWorkflowManager::runTrigger on action SHIPPING_CLOSED (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:445), sharing the same quantity-comparison logic as WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING. Declared in core/modules/modWorkflow.class.php:90 and exposed as a checkbox in the ''classify_order'' family of admin/workflow.php (position 41).', 'When set and a shipment is closed, the code compares per-product quantities shipped vs ordered on the origin order; if there is no difference, the order is closed via $order->cloture($user).', 'Truthy string enables the auto-close on shipment closure; empty/unset disables it (checkbox in admin/workflow.php).', 0, 0, NULL, 1, 'd93ba4296448dfa39c88385f71df804b7c327b8e715965767c306311281b01ca', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:445: (getDolGlobalString(''WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING_CLOSED'') && ($action == ''SHIPPING_CLOSED''))", "core/modules/modWorkflow.class.php:90: 3 => array(''WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING_CLOSED'', ''chaine'', ''1'', ...)", "admin/workflow.php:119: ''WORKFLOW_ORDER_CLASSIFY_SHIPPED_SHIPPING_CLOSED'' => array( // when shipping closed ..."]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_PROPAL_AUTOCREATE_ORDER', 'string', NULL, 'core', 'Automatically creates a sales order when a proposal (Propal) is closed as signed.', 'Read in the workflow trigger InterfaceWorkflowManager::runTrigger on action PROPAL_CLOSE_SIGNED (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:79). Registered as a workflow module constant in core/modules/modWorkflow.class.php:85 (currently commented out in the const array) and exposed as a checkbox in the ''create'' family of admin/workflow.php (WORKFLOW_PROPAL_AUTOCREATE_ORDER => array(''family'' => ''create'', ...)) which toggles it via dolibarr_set_const on action set/del.', 'When set, closing a signed proposal auto-generates a linked Commande via createFromProposal(); if permission to create orders is missing it is force-granted when the closing came from an online signature.', 'Truthy string enables the auto-creation; empty/unset disables it (checkbox in admin/workflow.php).', 0, 0, NULL, 1, '7b4ea3756ae8b442a53e3ecd859399769f748693b048d2b6e2b686fe4ac33910', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:79: if (isModEnabled(''order'') && getDolGlobalString(''WORKFLOW_PROPAL_AUTOCREATE_ORDER'')) {", "core/modules/modWorkflow.class.php:85: //0=>array(''WORKFLOW_PROPAL_AUTOCREATE_ORDER'', ''chaine'', ''1'', ''WORKFLOW_PROPAL_AUTOCREATE_ORDER'', 0, ''current'', 0),", "admin/workflow.php:75: ''WORKFLOW_PROPAL_AUTOCREATE_ORDER'' => array(''family'' => ''create'', ''position'' => 10, ''enabled'' => (isModEnabled(\"propal\") && isModEnabled(''order'')), ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_PROPAL_NEED_INVOICE_TO_BE_CLASSIFIED_BILLED', 'string', NULL, 'comm', 'Requires that at least one invoice already exist for a signed proposal before it can be manually classified as billed.', 'Checked in comm/propal/card.php:3747 (negated, OR''d with an invoice-count check); the ClassifyBilled button is enabled either if invoices already exist for the proposal, or if this constant is unset.', 'Enabling it hides/blocks the ClassifyBilled action on signed proposals with no linked invoice yet, forcing users to invoice first; default behaviour allows classifying billed without a linked invoice.', 'Boolean-like (truthy/falsy).', 1, 0, NULL, 1, '722103731653b9be30c6e572d7b2860fd76e65aa53089e1962d1420a174471a9', 'v2', '2026-07-24T07:05:23+00:00', '["comm/propal/card.php:3747: if ((is_array($arrayofinvoiceforpropal) && count($arrayofinvoiceforpropal) > 0) || !getDolGlobalString(''WORKFLOW_PROPAL_NEED_INVOICE_TO_BE_CLASSIFIED_BILLED'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_RECEPTION_CLASSIFY_BILLED_INVOICE', 'string', NULL, 'core', 'Automatically marks a reception as billed when the linked invoice is validated.', 'Checked in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:382. The comment at line 381 states it sets the reception to ''Billed''. Line 357 confirms this replaced the deprecated WORKFLOW_RECEPTION_CLASSIFY_CLOSED_INVOICE. The class method is documented in reception/class/reception.class.php:2146.', 'Enabling this causes Dolibarr to classify receptions as invoiced automatically on invoice validation.', '0 or empty = reception not auto-classified billed; non-empty = reception classified as billed on invoice validation', 1, 0, NULL, 1, '3128a252fa45ef433b67bef3a460b18f94b9ac4909b673baefac7c6e5695873f', 'v2', '2026-04-21T11:16:15+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:357  // Set reception to \"Closed\" if WORKFLOW_RECEPTION_CLASSIFY_CLOSED_INVOICE is set (deprecated, WORKFLOW_RECEPTION_CLASSIFY_BILLED_INVOICE instead))", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:381  // Then set reception to \"Billed\" if WORKFLOW_RECEPTION_CLASSIFY_BILLED_INVOICE is set", "reception/class/reception.class.php:2146  *\tClassify the reception as invoiced (used for example by trigger when WORKFLOW_RECEPTION_CLASSIFY_BILLED_INVOICE is on)", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:382|check|if (isModEnabled(\"reception\") && !empty($conf->workflow->enabled) && getDolGlobalString(''WORKFLOW_RECEPTION_CLASSIFY_BILLED_INVOICE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_RECEPTION_CLASSIFY_CLOSED_INVOICE', 'string', NULL, 'core', 'Triggers automatic classification of a reception as ''Closed'' when an associated invoice is closed, as a deprecated workflow setting.', 'Used in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:359. The comment at line 357 explicitly marks this as deprecated, recommending WORKFLOW_RECEPTION_CLASSIFY_BILLED_INVOICE instead.', 'When enabled, closing an invoice triggers the reception to be set to ''Closed'' status automatically; this behavior is deprecated.', 'Non-empty = enabled (reception auto-closed on invoice close); empty/unset = disabled.', 1, 0, NULL, 1, 'bedc3b0e04d744e6b9608954144b6ae1d24e8167ae21ff31bf72d024cb7556d2', 'v2', '2026-04-21T13:50:40+00:00', '["// Set reception to \"Closed\" if WORKFLOW_RECEPTION_CLASSIFY_CLOSED_INVOICE is set (deprecated, WORKFLOW_RECEPTION_CLASSIFY_BILLED_INVOICE instead))", "if (isModEnabled(\"reception\") && !empty($conf->workflow->enabled) && !empty($conf->global->WORKFLOW_RECEPTION_CLASSIFY_CLOSED_INVOICE)) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_SHIPPING_CLASSIFY_BILLED_INVOICE', 'string', NULL, 'core', 'Automatically marks a shipment as billed when the linked invoice is validated.', 'Checked in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:247. The comment at line 222 identifies this as the replacement for the deprecated WORKFLOW_SHIPPING_CLASSIFY_CLOSED_INVOICE. The method it invokes is documented in expedition/class/expedition.class.php:3122.', 'Enabling this causes Dolibarr to classify the shipment as invoiced automatically upon invoice validation.', '0 or empty = shipment not auto-classified billed; non-empty = shipment classified as billed on invoice validation', 1, 0, NULL, 1, '0ac773a069cec7473c2d6dcf5e5a487a8a1f358951368e60841a84d9644d5868', 'v2', '2026-04-21T11:16:15+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:222  // Set shipment to \"Closed\" if WORKFLOW_SHIPPING_CLASSIFY_CLOSED_INVOICE is set (deprecated, has been replaced with WORKFLOW_SHIPPING_CLASSIFY_BILLED_INVOICE instead))", "expedition/class/expedition.class.php:3122  *\tClassify the shipping as invoiced (used for example by trigger when WORKFLOW_SHIPPING_CLASSIFY_BILLED_INVOICE is on)", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:247|check|if (isModEnabled(\"shipping\") && !empty($conf->workflow->enabled) && getDolGlobalString(''WORKFLOW_SHIPPING_CLASSIFY_BILLED_INVOICE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_SHIPPING_CLASSIFY_CLOSED_INVOICE', 'string', NULL, 'core', 'Deprecated: previously set shipments to ''Closed'' status when an invoice was validated; replaced by WORKFLOW_SHIPPING_CLASSIFY_BILLED_INVOICE.', 'Checked in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:223. The comment at line 222 explicitly marks it as deprecated and replaced by WORKFLOW_SHIPPING_CLASSIFY_BILLED_INVOICE.', 'This constant is deprecated; use WORKFLOW_SHIPPING_CLASSIFY_BILLED_INVOICE instead. If still set, it triggers closing of shipments on invoice validation.', '0 or empty = no effect; non-empty = shipment closed on invoice (deprecated behavior)', 1, 0, NULL, 1, '9a3bb06f33d306170a0b6447e44d165f66a945be59f9cd3222d4ab32c0a73a7d', 'v2', '2026-04-21T11:16:15+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:222  // Set shipment to \"Closed\" if WORKFLOW_SHIPPING_CLASSIFY_CLOSED_INVOICE is set (deprecated, has been replaced with WORKFLOW_SHIPPING_CLASSIFY_BILLED_INVOICE instead))", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:223|check|if (isModEnabled(\"shipping\") && !empty($conf->workflow->enabled) && getDolGlobalString(''WORKFLOW_SHIPPING_CLASSIFY_CLOSED_INVOICE'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_SUM_INVOICES_AMOUNT_CLASSIFY_BILLED_ORDER', 'string', NULL, 'core', 'When a customer invoice is validated, classifies the single linked sales order as billed once the sum of all invoices linked to that order equals the order total.', 'Read in InterfaceWorkflowManager::runTrigger on action BILL_VALIDATE (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:271). Only applies when the invoice is linked to exactly one source order; it then sums all validated/closed invoices linked to that order and compares to the order total_ht before calling classifyBilled().', 'When set, enables multi-invoice reconciliation: an order billed across several invoices is only marked billed once all its linked invoices are validated/closed and their summed HT total matches the order amount.', 'Truthy string enables the check; empty/unset disables it.', 0, 0, NULL, 1, '059aa0c32e2f79657984585c2e500e186e24ce72e60f0709dbe074a881bacb21', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:271: if (isModEnabled(''order'') && isModEnabled(''workflow'') && getDolGlobalString(''WORKFLOW_SUM_INVOICES_AMOUNT_CLASSIFY_BILLED_ORDER'')) {", "core/modules/modWorkflow.class.php:92: 5 => array(''WORKFLOW_SUM_INVOICES_AMOUNT_CLASSIFY_BILLED_ORDER'', ''chaine'', ''1'', ''WORKFLOW_INVOICE_AMOUNT_CLASSIFY_BILLED_ORDER'', 0, ''current'', 0),", "admin/workflow.php:133: ''WORKFLOW_SUM_INVOICES_AMOUNT_CLASSIFY_BILLED_ORDER'' => array(''family'' => ''classify_order'', ''position'' => 43, ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_TICKET_CLOSE_INTERVENTION', 'string', NULL, 'ticket', 'When a ticket is closed, also closes (validates as done) all interventions (fichinter) linked to that ticket.', 'Used in ticket/class/ticket.class.php:2133 inside Ticket::close/setStatut-like logic: `if (isModEnabled(''intervention'') && getDolGlobalString(''WORKFLOW_TICKET_CLOSE_INTERVENTION'')) { ... foreach ($this->linkedObjectsIds[''fichinter''] as $fichinter_id) { ... if ($fichinter->statut == 0) ... } }` — fetches linked fichinter objects and closes those still in draft status (statut == 0).', 'When enabled and the Intervention module is active, closing a ticket automatically closes/validates any linked draft interventions instead of leaving them open.', 'Boolean (getDolGlobalString truthiness): truthy enables the automatic-close-linked-interventions workflow when a ticket is closed; falsy/unset leaves linked interventions untouched.', 1, 0, NULL, 1, '941a70ed2a145e19f3c5e00c905341be7fedde37c1f96a3ce2426395b865cf2e', 'v2', '2026-07-24T07:05:23+00:00', '["ticket/class/ticket.class.php:2133: if (isModEnabled(''intervention'') && getDolGlobalString(''WORKFLOW_TICKET_CLOSE_INTERVENTION'')) {"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_TICKET_CREATE_INTERVENTION', 'string', NULL, 'core', 'Automatically creates an intervention (Fichinter) when a new support ticket is created.', 'Read in InterfaceWorkflowManager::runTrigger on action TICKET_CREATE (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:630). Declared in core/modules/modWorkflow.class.php:99 and exposed as a checkbox in admin/workflow.php''s ''create'' family (position 25), enabled when both ticket and intervention modules are active.', 'When set, a Fichinter is created linked to the ticket''s thirdparty/project/contract, using PDF model FICHEINTER_ADDON_PDF (default ''soleil'') and copying the ticket''s extrafields; failure sets an error event message.', 'Truthy string enables the auto-creation; empty/unset disables it (checkbox in admin/workflow.php).', 0, 0, NULL, 1, '1958f6a2576224ca835dc62f7d7c8174e11bc7d5ce87eb0d267d159b5bbd21e2', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:630: if (isModEnabled(''intervention'') && isModEnabled(''ticket'') && isModEnabled(''workflow'') && getDolGlobalString(''WORKFLOW_TICKET_CREATE_INTERVENTION'')) {", "core/modules/modWorkflow.class.php:99: 12 => array(''WORKFLOW_TICKET_CREATE_INTERVENTION'', ''chaine'', ''0'', ''WORKFLOW_TICKET_CREATE_INTERVENTION'', 0, ''current'', 0),", "admin/workflow.php:87: ''WORKFLOW_TICKET_CREATE_INTERVENTION'' => array(''family'' => ''create'', ''position'' => 25, ''enabled'' => (isModEnabled(''ticket'') && isModEnabled(''intervention'')), ...)"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_TICKET_LINK_CONTRACT', 'string', NULL, 'admin', 'Enables automatic linking of a contract to a ticket based on the ticket''s third party and product category.', 'Managed via the admin UI at admin/workflow.php:225 and :376. The comment at admin/workflow.php:221 notes this depends on another workflow constant. Checked in core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:598 together with TICKET_PRODUCT_CATEGORY.', 'Enabling this causes Dolibarr to automatically find and link a contract to newly created or updated tickets when the contract module, ticket module, and workflow module are all active.', '0 or empty = no auto-linking; non-empty = contracts are automatically linked to tickets', 0, 0, 'admin/workflow.php|admin/workflow.php', 1, 'b88898ad212331c1cda24276f28268548fc9e072e9a362b8a49e67cf0c706359', 'v2', '2026-04-21T11:16:15+00:00', '["admin/workflow.php:221  // This one depends on previous one WORKFLOW_TICKET_LINK_CONTRACT", "admin/workflow.php:225|read|''enabled'' => (isModEnabled(''ticket'') && isModEnabled(''contract'') && getDolGlobalString(''WORKFLOW_TICKET_LINK_CONTRACT'')),", "core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:598|check|if (isModEnabled(''contract'') && isModEnabled(''ticket'') && isModEnabled(''workflow'') && getDolGlobalString(''WORKFLOW_TICKET_LINK_CONTRACT'') && getDolGlobalString(''TICKET_PRODUCT_CATE"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKFLOW_TICKET_USE_PARENT_COMPANY_CONTRACTS', 'bool', NULL, 'core', 'When auto-linking a new ticket to a contract, extends the contract search to the parent companies of the ticket''s thirdparty instead of only that thirdparty.', 'Read in InterfaceWorkflowManager::runTrigger on action TICKET_CREATE (core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:600). Declared in core/modules/modWorkflow.class.php:98 with description ''Search among parent companies contracts when automatically linking a ticket to available contracts'', and exposed as a checkbox in admin/workflow.php''s ''link_ticket'' family (position 501), only enabled/shown when WORKFLOW_TICKET_LINK_CONTRACT is also active.', 'When set, the list of company IDs used to search eligible contracts is built via getParentsForCompany() (thirdparty + its parents) instead of just [$object->fk_soc], widening which contracts a new ticket can auto-link to.', '''0'' (default, per const array) = only the ticket''s own thirdparty is searched; truthy = also search parent companies'' contracts.', 0, 0, NULL, 1, '4a525cf69d9e7211b9febdee7a02401b372110cc1185a5b6e4f3f620290a3c5c', 'v2', '2026-07-24T07:05:23+00:00', '["core/triggers/interface_20_modWorkflow_WorkflowManager.class.php:600: $company_ids = (!getDolGlobalString(''WORKFLOW_TICKET_USE_PARENT_COMPANY_CONTRACTS'')) ? [$object->fk_soc] : $societe->getParentsForCompany($object->fk_soc, [$object->fk_soc]);", "core/modules/modWorkflow.class.php:98: 11 => array(''WORKFLOW_TICKET_USE_PARENT_COMPANY_CONTRACTS'', ''chaine'', ''0'', ''Search among parent companies contracts when automatically linking a ticket to available contracts'', 0, ''current'', 0),", "admin/workflow.php:222: ''enabled'' => (isModEnabled(''ticket'') && isModEnabled(''contract'') && getDolGlobalString(''WORKFLOW_TICKET_LINK_CONTRACT'')),"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKSTATION_ADDON_PDF', 'string', NULL, 'workstation', 'Names the default PDF document model (template) used to generate workstation documents.', 'Read in workstation/class/workstation.class.php:902-903 inside generateDocument(); used as fallback model name when no object-specific model_pdf is set.', 'Setting it changes which PDF template (e.g. a custom model registered under core/modules/workstation/doc/) is used by default when generating a workstation document.', 'String: name of a registered workstation PDF document model (fallback default is ''standard_workstation'').', 1, 0, NULL, 1, 'e99e7be32897b8ad7d128a18623f6e95058c2de98a60654502e0af711faa7f7e', 'v2', '2026-07-24T07:05:23+00:00', '["workstation/class/workstation.class.php:902|read|} elseif (getDolGlobalString(''WORKSTATION_ADDON_PDF'')) {", "workstation/class/workstation.class.php:903|read|$modele = getDolGlobalString(''WORKSTATION_ADDON_PDF'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKSTATION_INCLUDE_DOC_GENERATION', 'string', NULL, 'admin', 'Shows the document-model (PDF template) generator selection section on the Workstation module''s admin setup page.', 'Checked in admin/workstation.php:287; when true, a ''DocumentModules'' titled section listing available document-model templates (queried from document_model) is displayed.', 'Enabling it adds a document-template configuration section to the Workstation admin page, letting document generation model(s) be selected for workstations.', 'Boolean-like: any truthy value shows the document-generation templates section on the Workstation admin page.', 0, 0, 'admin/workstation.php', 1, 'af7793d2ae04fac67e13a0911485b6b8bb4d14ce03c35e82c72e7f633693944a', 'v2', '2026-07-24T07:05:23+00:00', '["admin/workstation.php:287: if (getDolGlobalInt(''WORKSTATION_INCLUDE_DOC_GENERATION'')) {"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKSTATION_WORKSTATION_ADDON', 'string', NULL, 'workstation', 'Specifies the active numbering module class name for workstations.', 'Read at workstation/class/workstation.class.php:838 as the class name to instantiate, and at line 837 to derive the include filename. When not set, it defaults to ''mod_workstation_standard'' (written at line 831). No admin UI is provided.', 'Changing this constant switches the numbering module used to generate workstation reference codes.', 'A module class name string (e.g., ''mod_workstation_standard''); empty/unset = defaults to ''mod_workstation_standard''.', 1, 0, NULL, 1, 'b11affd98301e9faf85d6cd809e9a619917b5c73042b0138fb94f952b5efea19', 'v2', '2026-04-21T11:16:15+00:00', '["workstation/class/workstation.class.php:831|write|$conf->global->WORKSTATION_WORKSTATION_ADDON = ''mod_workstation_standard'';", "workstation/class/workstation.class.php:834|check|if (getDolGlobalString(''WORKSTATION_WORKSTATION_ADDON'')) {", "workstation/class/workstation.class.php:838|read|$classname = getDolGlobalString(''WORKSTATION_WORKSTATION_ADDON'');", "workstation/class/workstation.class.php:837|read|$file = getDolGlobalString(''WORKSTATION_WORKSTATION_ADDON'') . \".php\";"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WORKSTATION_WORKSTATION_ADVANCED_MASK', 'string', NULL, 'core', 'Defines the numbering mask used by the advanced workstation numbering module.', 'Read in core/modules/workstation/mod_workstation_advanced.php:91 to populate the mask input in the module configuration form, and at line 144 to generate workstation reference numbers.', 'Changing the mask alters the format of auto-generated workstation reference numbers.', 'String: a numbering mask pattern.', 1, 0, NULL, 1, '8a9aa2a33abd4c1fdf1a365287c80ba5eadbd0a6097a64979e16fb4eb177db7a', 'v2', '2026-04-21T13:50:40+00:00', '["core/modules/workstation/mod_workstation_advanced.php:91|read|... value=\"''.getDolGlobalString(''WORKSTATION_WORKSTATION_ADVANCED_MASK'').''\"...", "core/modules/workstation/mod_workstation_advanced.php:144|read|$mask = getDolGlobalString(''WORKSTATION_WORKSTATION_ADVANCED_MASK'');"]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WS_', 'string', NULL, 'core', 'Not a single constant but a dynamic name prefix (WS_<WEBSITEREF>_MAIN_COLOR / WS_<WEBSITEREF>_SECONDARY_COLOR) used to override the CSS main/secondary colors of a specific website in the ''association'' demo website template.', 'Used only in install/doctemplates/websites/website_template-association_exp/containers/styles.css.php:11385-11386, where the website ref (uppercased) is concatenated with ''_MAIN_COLOR'' or ''_SECONDARY_COLOR'' to build the actual constant name read via getDolGlobalString().', 'Setting WS_<REF>_MAIN_COLOR or WS_<REF>_SECONDARY_COLOR for a given website ref overrides that website''s CSS color variables in this specific demo template; otherwise CSS falls back to ''#5d5b6a'' / ''#FF7F50''.', 'No fixed value: name is built as WS_ + strtoupper(website->ref) + _MAIN_COLOR or _SECONDARY_COLOR, expected to hold a CSS color (e.g. hex code) or be unset (falls back to ''#5d5b6a'' / ''#FF7F50'').', 1, 0, NULL, 1, '12345c78a5722869b2270a65aa500de8d622ab2b6f45255f1c85b5605f345f89', 'v2', '2026-07-24T07:05:23+00:00', '["install/doctemplates/websites/website_template-association_exp/containers/styles.css.php:11385|read|--main-color: <?php print getDolGlobalString(''WS_'' . strtoupper($website->ref) . ''_MAIN_COLOR'') ?: ''#5d5b6a''; ?>;", "install/doctemplates/websites/website_template-association_exp/containers/styles.css.php:11386|read|--secondary-color: <?php print getDolGlobalString(''WS_'' . strtoupper($website->ref) . ''_SECONDARY_COLOR'') ?: ''#FF7F50''; ?>;"]', 'low', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WYSIWYG_ALLOW_UPLOAD_MEDIA_FILES', 'bool', NULL, 'core', 'Allows uploading media files (images, etc.) through the WYSIWYG editor''s file browser.', 'Checked in core/filemanagerdol/connectors/php/config.inc.php:54 to gate the local file browser connector, and read via getDolGlobalInt in core/class/doleditor.class.php:123 to set $uselocalbrowser. A code comment at config.inc.php:58 notes permissions are checked once upload is allowed via this setting.', 'When enabled, the WYSIWYG editor''s local file browser is made available and file uploads are permitted, subject to further permission checks noted in the code.', NULL, 0, 0, NULL, 1, 'f4ea96b00abc15a0a661fc9febb7229b8acd45159278119104ccf6ceb92f1da1', 'v2', '2026-07-24T06:41:12+00:00', '["if (!getDolGlobalString(''WYSIWYG_ALLOW_UPLOAD_MEDIA_FILES'')) {", "// If upload has been allowed with WYSIWYG_ALLOW_UPLOAD_MEDIA_FILES set, we check permissions."]', 'medium', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('WYSIWYG_TINYMCE_ENABLE_STATUS_BAR', 'bool', NULL, 'core', 'Enables the status bar at the bottom of the TinyMCE editor instance.', 'Checked in core/class/doleditor.class.php:381; if not set, ''statusbar: false,'' is added to the TinyMCE JS config, hiding the status bar. If set, the statusbar option is simply omitted, leaving TinyMCE''s default (visible) behavior.', 'Enabling it (or leaving it unset with no override, per the negative check) shows the TinyMCE status bar; the constant only actively hides it, it does not force-show it beyond TinyMCE''s own default.', 'Boolean-like: falsy/unset (default check path) hides the status bar by adding statusbar:false; truthy skips that override.', 1, 0, NULL, 1, 'aaccf2bd985b08836125e57a560da4e01d59687e7585e17951f631e03ceaa8a6', 'v2', '2026-07-24T07:05:23+00:00', '["core/class/doleditor.class.php:381|check|if (!getDolGlobalString(''WYSIWYG_TINYMCE_ENABLE_STATUS_BAR'')) {", "$out .= ''\t\tstatusbar: false,''.\"\\n\";"]', 'high', NULL);
INSERT INTO constants(name, type, default_value, module, purpose, description, impact, possible_values, hidden_setting, hidden_setting_guess, admin_ui_files, doc_quality, content_hash, hash_version, last_enriched, evidence, confidence, conf_php_wiring) VALUES('XXX', 'string', NULL, 'master.inc.php', 'Not a real constant: a documentation placeholder used in a source comment to represent ''any constant name'' loaded from the llx_const table into $conf->global.', 'Appears only in master.inc.php:311 as a generic comment explaining the mechanism by which all rows of llx_const become available as $conf->global->XXX (XXX being a stand-in for the actual constant name), immediately before the call to $conf->setValues($db).', 'Setting a constant literally named XXX has no documented special effect; this entry documents the general mechanism (constants are loaded from the database into $conf->global by conf->setValues()) rather than a specific configuration switch.', 'N/A - placeholder name in a comment, not an actual configurable constant.', 1, 0, NULL, 1, 'ea86e51a8f464ca96406b707dfc1c418df82c3092209980ff8a12e7e47f9a01a', 'v2', '2026-07-24T07:05:23+00:00', '["master.inc.php:311: // Here we read database (llx_const table) and define conf var $conf->global->XXX.", "master.inc.php:314: $conf->setValues($db);"]', 'low', NULL);
